window.KNOWLEDGEWALK_SEARCH = [{"id": "venice-winged-lion", "title": "\ubca0\ub124\uce58\uc544\uc5d0\uc11c\ub294 \uc0ac\uc790\uc5d0\uac8c\ub3c4 \ub0a0\uac1c\uac00 \uc788\ub2e4", "summary": "\uad11\uc7a5\uc5d0\ub3c4, \uac74\ubb3c \ubcbd\uc5d0\ub3c4, \uae30\ub150\ud488 \uac00\uac8c\uc5d0\ub3c4. \ubca0\ub124\uce58\uc544\uc758 \uc0ac\uc790\ub294 \uc65c \ub0a0\uac1c\uc640 \ucc45\uc744 \ucc59\uacbc\uc744\uae4c\uc694?", "category": "cities", "category_title": "Cities", "subcategory": "Europe", "url": "stories/venice-winged-lion/index.html", "image": "media/venice-winged-lion.jpg", "alt": "\ud3bc\uce5c \ucc45\uc5d0 \uc55e\ubc1c\uc744 \uc5b9\uc740 \ub0a0\uac1c \ub2ec\ub9b0 \uc0ac\uc790\uc758 \uc218\ucc44\ud654\ud48d \uc0bd\ud654", "text": "\ubca0\ub124\uce58\uc544\uc5d0\uc11c\ub294 \uc0ac\uc790\uc5d0\uac8c\ub3c4 \ub0a0\uac1c\uac00 \uc788\ub2e4 \ub0a0\uac1c\uc640 \ucc45\uc744 \ucc59\uae34 \uc0ac\uc790\uac00 \ub3c4\uc2dc\uc758 \uc5bc\uad74\uc774 \ub41c \uc0ac\uc5f0 \uad11\uc7a5\uc5d0\ub3c4, \uac74\ubb3c \ubcbd\uc5d0\ub3c4, \uae30\ub150\ud488 \uac00\uac8c\uc5d0\ub3c4. \ubca0\ub124\uce58\uc544\uc758 \uc0ac\uc790\ub294 \uc65c \ub0a0\uac1c\uc640 \ucc45\uc744 \ucc59\uacbc\uc744\uae4c\uc694? Europe \ub3c4\uc2dc \ubca0\ub124\uce58\uc544\uc5d0\uc11c\ub294 \uc0ac\uc790\ub97c \ub9cc\ub0a0 \uc900\ube44\ub97c \uc870\uae08 \ud574\uc57c \ud55c\ub2e4. \ub3d9\ubb3c\uc6d0\uc774 \uc544\ub2c8\ub77c \uad11\uc7a5\uacfc \uac74\ubb3c \ubcbd\uc5d0\uc11c \ub9d0\uc774\ub2e4. \uae30\ub150\ud488 \uac00\uac8c\uae4c\uc9c0 \ub4e4\uc5b4\uac00\uba74 \uc0ac\uc790\ub97c \ud53c\ud558\uae30\uac00 \ub354 \uc5b4\ub824\uc6cc\uc9c4\ub2e4. \uadf8\ub7f0\ub370 \uc774 \ub3c4\uc2dc\uc758 \uc0ac\uc790\ub294 \uc900\ube44\ubb3c\uc774 \ub9ce\ub2e4. \ub4f1\uc5d0 \ub0a0\uac1c\ub97c \ub2ec\uc558\uace0, \uc55e\ubc1c\uc5d0\ub294 \ucc45\uae4c\uc9c0 \ucc59\uacbc\ub2e4. \uac08\uae30\ub9cc\uc73c\ub85c\ub3c4 \ucda9\ubd84\ud788 \ub208\uc5d0 \ub74c \ud150\ub370, \uad73\uc774 \uc774 \ub450 \uac00\uc9c0\ub97c \ub354\ud588\ub2e4. \uc65c \ud558\ud544 \ub0a0\uac1c\uc640 \ucc45\uc77c\uae4c? \uc0ac\uc5f0\uc758 \uc8fc\uc778\uacf5\uc740 \uc131 \ub9c8\ub974\ucf54\ub2e4. \uadf8\ub9ac\uc2a4\ub3c4\uad50\uc5d0\uc11c \ub9c8\ub974\ucf54\ub294 \ubcf5\uc74c\uc11c \uc800\uc790\ub85c \uc804\ud574\uc9c0\ub294 \uc778\ubb3c\uc774\uba70, \ub0a0\uac1c \ub2ec\ub9b0 \uc0ac\uc790\ub294 \uadf8\ub97c \ub098\ud0c0\ub0b4\ub294 \uc0c1\uc9d5\uc774\ub2e4. \uc61b \uc885\uad50 \uadf8\ub9bc\uc5d0\uc11c\ub294 \uc0ac\ub78c\uc758 \uc774\ub984\uc744 \ud06c\uac8c \uc368 \ubd99\uc774\ub294 \ub300\uc2e0, \ud2b9\uc815\ud55c \ub3d9\ubb3c\uc774\ub098 \ubb3c\uac74\uc73c\ub85c \ub204\uad6c\uc778\uc9c0 \uc54c\ub824\uc8fc\uace4 \ud588\ub2e4. \ub9c8\ub974\ucf54\uc758 \uacbd\uc6b0\uc5d0\ub294 \uc0ac\uc790\uac00 \uadf8\ub7f0 \uc5ed\ud560\uc744 \ud588\ub2e4. \ub0a0\uac1c\ub294 \uc774 \uc0ac\uc790\uac00 \ucd08\uc6d0\uc5d0\uc11c \uc0ac\ub0e5\ud558\ub294 \ubcf4\ud1b5 \uc0ac\uc790\uac00 \uc544\ub2c8\ub77c, \uc885\uad50\uc801 \uc0c1\uc9d5\uc774\ub77c\ub294 \uac83\uc744 \ubcf4\uc5ec\uc900\ub2e4. \uc870\uae08 \uba40\uac8c \ub290\uaef4\uc9c4\ub2e4\uba74 \uc774\ub984\ud45c\ub77c\uace0 \uc0dd\uac01\ud574\ub3c4 \uc88b\ub2e4. \uadf8\ub9bc \uc18d\uc5d0 \ub0a0\uac1c \ub2ec\ub9b0 \uc0ac\uc790\uac00 \ub4f1\uc7a5\ud558\uba74, \uadf8\ub9ac\uc2a4\ub3c4\uad50\uc758 \uc0c1\uc9d5\uc5d0 \uc775\uc219\ud55c \uc0ac\ub78c\uc740 \ub9c8\ub974\ucf54\ub97c \ub5a0\uc62c\ub9b4 \uc218 \uc788\uc5c8\ub2e4. \ubb3c\ub860 \ubaa8\ub4e0 \uc2dc\ub300\uc758 \ubaa8\ub4e0 \uc0ac\uc790\uac00 \uac19\uc740 \ub73b\uc778 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubca0\ub124\uce58\uc544\uc758 \uc774 \uc0ac\uc790\ub294 \uadf8 \uc804\ud1b5 \uc548\uc5d0 \uc788\ub2e4. \ubca0\ub124\uce58\uc544\ub294 \uc131 \ub9c8\ub974\ucf54\ub97c \ub3c4\uc2dc\uc758 \uc218\ud638\uc131\uc778\uc73c\ub85c \ubaa8\uc168\ub2e4. \uc0b0\ub9c8\ub974\ucf54 \uad11\uc7a5\uacfc \uc0b0\ub9c8\ub974\ucf54 \ub300\uc131\ub2f9\uc758 \u2018\ub9c8\ub974\ucf54\u2019\ub3c4 \uac19\uc740 \uc774\ub984\uc774\ub2e4. \uadf8\ub7ec\ub2c8 \uadf8\uc758 \uc0c1\uc9d5\uc778 \uc0ac\uc790\uac00 \ub3c4\uc2dc\uc758 \uc5bc\uad74\uc774 \ub41c \ub370\uc5d0\ub294 \ub098\ub984\uc758 \uc774\uc720\uac00 \uc788\uc5c8\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc131\uc778\uc744 \uac00\ub9ac\ud0a4\ub358 \uadf8\ub9bc\uc774, \ubca0\ub124\uce58\uc544\uc5d0\uc11c\ub294 \ub3c4\uc2dc\uc640 \uc61b \uacf5\ud654\uad6d\uc744 \uac00\ub9ac\ud0a4\ub294 \ud45c\uc9c0\uac00 \ub41c \uac83\uc774\ub2e4. \uc131 \ub9c8\ub974\ucf54\ub97c \ub530\ub77c\uc628 \uc0ac\uc790\uac00 \ub3c4\uc2dc \uc804\uccb4\uc758 \uac04\ud310\uae4c\uc9c0 \ub9e1\uac8c \ub41c \uc148\uc774\ub2e4. \ub0a0\uac1c\ubcf4\ub2e4 \ucc45\uc774 \ub354 \uad81\uae08\ud560 \uc218\ub3c4 \uc788\ub2e4. \uc0ac\uc790\ub294 \ucc45\uc744 \uc77d\ub294 \uc911\uc77c\uae4c, \uc544\ub2c8\uba74 \uc911\uc694\ud55c \ub0b4\uc6a9\uc744 \uc6b0\ub9ac\uc5d0\uac8c \ubcf4\uc5ec\uc8fc\ub294 \uc911\uc77c\uae4c? \ud3bc\uccd0\uc9c4 \ucc45\uc5d0\ub294 \ub9c8\ub974\ucf54\uc5d0\uac8c \ud3c9\ud654\ub97c \uc804\ud558\ub294 \ub73b\uc758 \ub77c\ud2f4\uc5b4 \ubb38\uad6c\uac00 \uc801\ud78c \uc608\uac00 \uc788\ub2e4. \uc0b0\ub9c8\ub974\ucf54 \ub300\uc131\ub2f9\uc758 \uacf5\uc2dd \uc124\uba85\uc5d0\uc11c\ub3c4 \uc774 \ubb38\uad6c\uc640 \ub0a0\uac1c \ub2ec\ub9b0 \uc0ac\uc790\ub97c \ud568\uaed8 \uc18c\uac1c\ud55c\ub2e4. \ub2e8\uc21c\ud788 \ubc15\uc2dd\ud55c \uc0ac\uc790\ub97c \ub9cc\ub4e4\ub824\uace0 \ucc45\uc744 \ubcf4\ud0e0 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc0ac\uc790\uc640 \ucc45\uc774 \ud568\uaed8 \uc788\uc5b4\uc57c \ub204\uad6c\uc758 \uc0c1\uc9d5\uc778\uc9c0 \ub354 \ubd84\uba85\ud574\uc9c4\ub2e4. \ucc45\uae4c\uc9c0 \uacc1\ub4e4\uc774\uba74 \uc0ac\uc790\uc758 \ubaa8\uc2b5\uc740 \uc870\uae08 \ub2ec\ub77c\uc9c4\ub2e4. \ud798\uc13c \ub3d9\ubb3c\uc5d0\uac8c \uc870\uc6a9\ud788 \uc77d\uc744\uac70\ub9ac\ub97c \uac74\ub128 \ub4ef \ubcf4\uc774\uc9c0\ub9cc, \uc0ac\uc2e4\uc740 \uc131\uc778\uc744 \uc54c\uc544\ubcf4\uac8c \ud558\ub294 \uc5ec\ub7ec \ud45c\uc2dc\uac00 \ud568\uaed8 \ub193\uc778 \uac83\uc774\ub2e4. \uc61b \uadf8\ub9bc\uacfc \uc870\uac01\uc5d0\uc11c\ub294 \uc774\ub7f0 \ubb3c\uac74 \ud558\ub098\uac00 \ub4f1\uc7a5\uc778\ubb3c\uc758 \uc774\ub984\uc744 \uc54c\ub824\uc8fc\uae30\ub3c4 \ud588\ub2e4. \ucc45\uc5d0 \uae00\uc528\uac00 \uc788\ub2e4\uba74 \ubb34\uc5c7\uc774 \uc801\ud614\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc544\ub3c4 \uc88b\ub2e4. \ub2e4\ub9cc \uae00\uc790\uac00 \ub0a1\uc544 \uc798 \ubcf4\uc774\uc9c0 \uc54a\uac70\ub098, \ub192\uc774 \uc788\uc5b4 \uc77d\uae30 \uc5b4\ub824\uc6b8 \uc218\ub3c4 \uc788\ub2e4. \uadf8\ub7f4 \ub54c\ub294 \uac00\uae4c\uc774 \ub2e4\uac00\uac00\ub824 \uc560\uc4f0\uae30\ubcf4\ub2e4 \ud604\uc7a5\uc758 \uc548\ub0b4\ub098 \uc18c\uc7a5 \uae30\uad00\uc758 \uc124\uba85\uc744 \ucc3e\uc544\ubcf4\uba74 \ub41c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uac10\uc0c1\uc774 \ubcf5\uc7a1\ud574\uc9c8 \ud544\uc694\ub294 \uc5c6\ub2e4. \ucc45\uc774 \uc788\ub294\uc9c0, \ub0a0\uac1c\ub294 \uc5b4\ub5a4 \ubaa8\uc591\uc778\uc9c0, \ud45c\uc815\uc740 \uc5b4\ub5a4\uc9c0\ub9cc \ubcf4\uc544\ub3c4 \uc0ac\uc790\ub9c8\ub2e4 \uc870\uae08\uc529 \ub2e4\ub974\ub2e4\ub294 \uac83\uc744 \ubc1c\uacac\ud558\uac8c \ub41c\ub2e4. \uc815\ub2f5\uc744 \ub9de\ud788\ub294 \ub300\uc2e0 \ucc28\uc774\ub97c \ucc3e\ub294 \uad6c\uacbd\uc774\ub2e4. \uac19\uc740 \ub0a0\uac1c\uc640 \ucc45\uc774 \uc788\uc5b4\ub3c4 \uc5b4\ub514\uc5d0 \ub193\uc600\ub294\uc9c0\uc5d0 \ub530\ub77c \ub9cc\ub098\uac8c \ub418\ub294 \uc774\uc57c\uae30\ub294 \uc870\uae08 \ub2ec\ub77c\uc9c4\ub2e4. \uc131\ub2f9\uc758 \uc815\uba74\uc5d0\uc11c\ub294 \uc131\uc778\uacfc \uc2e0\uc559\uc758 \uc804\ud1b5\uc744, \ub3c4\uc2dc\uc758 \uc7a5\uc2dd\uc5d0\uc11c\ub294 \ubca0\ub124\uce58\uc544\ub77c\ub294 \uc7a5\uc18c\uc758 \uc815\uccb4\uc131\uc744 \ud568\uaed8 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \uc774\ubbf8\uc9c0\ub97c \uc54c\uc544\ubcf4\ub294 \uac83\uacfc \uadf8 \uc774\ubbf8\uc9c0\uac00 \ud2b9\uc815 \uc790\ub9ac\uc5d0 \ub193\uc778 \uc774\uc720\ub97c \uc77d\ub294 \uac83\uc740 \uc5f0\uacb0\ub418\uc9c0\ub9cc \uac19\uc740 \ub2e8\uacc4\ub294 \uc544\ub2c8\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \uc0ac\uc790\ub97c \ucc3e\uc558\ub2e4\uba74 \uace7\ubc14\ub85c \ud45c\uc815\ub9cc \ud655\ub300\ud558\uae30 \uc804\uc5d0 \uc8fc\ubcc0\uc744 \uc870\uae08 \ub113\uac8c \ubcf4\uc790. \uac74\ubb3c\uc758 \uc911\uc2ec \uac00\uae4c\uc774\uc5d0 \uc788\ub294\uc9c0, \ubb38\uc774\ub098 \ub2e4\ub978 \uc7a5\uc2dd\uacfc \uc5b4\ub5a4 \uad00\uacc4\uc778\uc9c0 \uc0b4\ud3b4\ubcf4\uba74 \ub41c\ub2e4. \uc774\ub54c \ubaa8\ub4e0 \uc0ac\uc790\uc5d0\uac8c \ud558\ub098\uc758 \uc815\ub2f5\uc744 \uc801\uc6a9\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uac1c\ubcc4 \uc791\ud488\uc758 \uc81c\uc791 \uc2dc\uae30\uc640 \uc124\uba85\uc744 \ud655\uc778\ud560\uc218\ub85d \uc775\uc219\ud55c \uc0c1\uc9d5 \uc548\uc758 \ucc28\uc774\ub3c4 \ub354 \uc798 \ubcf4\uc778\ub2e4. \uc0b0\ub9c8\ub974\ucf54 \ub300\uc131\ub2f9\uc758 \uc815\uba74\uc744 \uc62c\ub824\ub2e4\ubcf4\uba74 \uc7a5\uc2dd \uc0ac\uc774\uc5d0 \uc790\ub9ac \uc7a1\uc740 \uc0ac\uc790\ub97c \ubc1c\uacac\ud560 \uc218 \uc788\ub2e4. \uc5ec\ub7ec \uc544\uce58 \uac00\uc6b4\ub370 \uc911\uc2ec\uc774 \ub418\ub294 \ubd80\ubd84 \uc704\ucabd\uc774\ub2e4. \uc131\uc778\uc744 \uc0c1\uc9d5\ud558\ub294 \uc0ac\uc790\uac00 \uadf8 \uc131\uc778\uc744 \ubaa8\uc2e0 \uac74\ubb3c\uc5d0\uc11c\ub3c4 \uc5bc\uad74\uc744 \ub0b4\ubc00\uace0 \uc788\ub294 \uc148\uc774\ub2e4. \ub2e4\ub978 \uc0ac\uc790\ub4e4\uc740 \uac74\ubb3c\uc758 \ubcbd\uc774\ub098 \uc7a5\uc2dd \uc18d\uc5d0 \ub4e4\uc5b4\uac00 \uc788\ub2e4. \uc5b4\ub5a4 \uac83\uc740 \uc704\uc5c4 \uc788\uac8c \uc55e\uc744 \ubcf4\uace0, \uc5b4\ub5a4 \uac83\uc740 \uc606\ubaa8\uc2b5\uc744 \ubcf4\uc5ec\uc900\ub2e4. \uae30\ub150\ud488 \uc18d\uc73c\ub85c \ub4e4\uc5b4\uac00\uba74 \ubd84\uc704\uae30\uac00 \ud55c\uacb0 \ubd80\ub4dc\ub7ec\uc6cc\uc9c4\ub2e4. \ub098\ub77c\ub97c \ub300\ud45c\ud558\ub358 \uc0c1\uc9d5\uc774 \uc190\ubc14\ub2e5\ub9cc \ud55c \ubb3c\uac74\uc774 \ub418\uc5b4 \uc5ec\ud589 \uac00\ubc29\uc5d0 \uc2e4\ub824 \uac00\uae30\ub3c4 \ud55c\ub2e4. \uc0ac\uc790\ub97c \uc54c\uc544\ubcf4\ub294 \ub370 \uc775\uc219\ud574\uc9c0\uba74 \uac74\ubb3c\uc758 \uc7a5\uc2dd\ub3c4 \uc804\uacfc \ub2e4\ub974\uac8c \ubcf4\uc778\ub2e4. \uc5b4\ub5a4 \ub3d9\ubb3c\uc740 \uc774\uc57c\uae30\ub97c \ub098\ud0c0\ub0b4\uace0, \uc5b4\ub5a4 \ub3d9\ubb3c\uc740 \ud2b9\uc815 \uc778\ubb3c\uc744 \uc54c\ub824\uc900\ub2e4. \ubaa8\uc591\uc774 \ube44\uc2b7\ud574\ub3c4 \ub298 \uac19\uc740 \ub73b\uc740 \uc544\ub2c8\ub2c8, \ud2b9\ubcc4\ud788 \uad81\uae08\ud55c \uc870\uac01\uc740 \uadf8 \uac74\ubb3c\uc758 \uc124\uba85\uacfc \ud568\uaed8 \ubcf4\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc774 \uc815\ub3c4\ub9cc \uc54c\uace0 \uac78\uc5b4\ub3c4 \uc5ec\ud589\uc758 \ud48d\uacbd\uc774 \uc870\uae08 \ub2ec\ub77c\uc9c4\ub2e4. \ubc29\uae08 \uc9c0\ub098\uce5c \ubcbd\uc758 \uc7a5\uc2dd\uc774 \ub2e8\uc21c\ud55c \ub3d9\ubb3c\uc774 \uc544\ub2c8\ub77c\ub294 \uac83\uc744 \uc54c\uc544\ubcf4\uac8c \ub41c\ub2e4. \uae00\uc790\ub97c \uc77d\uc9c0 \ubabb\ud574\ub3c4 \uc791\uc740 \uadf8\ub9bc \ud558\ub098\uac00 \ub3c4\uc2dc\uc758 \uc774\ub984\uc744 \uc54c\ub824\uc8fc\ub294 \uc148\uc774\ub2e4. \ubca0\ub124\uce58\uc544\uc5d0 \uac04\ub2e4\uba74 \uc0ac\uc790 \ud55c \ub9c8\ub9ac\ucbe4\uc740 \ucc3e\uc544\ubcf4\uc544\ub3c4 \uc88b\uaca0\ub2e4. \uc131\ub2f9\uc758 \ub192\uc740 \uacf3\uc5d0 \uc788\ub294 \uc0ac\uc790\uc5ec\ub3c4 \uc88b\uace0, \uac00\uac8c \uc9c4\uc5f4\uc7a5 \uc18d\uc758 \uc791\uc740 \uc0ac\uc790\uc5ec\ub3c4 \uc88b\ub2e4. \ub0a0\uac1c\uc640 \ucc45\uc744 \ud655\uc778\ud588\ub2e4\uba74, \ub9c8\uc9c0\ub9c9\uc5d0\ub294 \uc5bc\uad74\uc744 \ud55c\ubc88 \ubcf4\uc790. \ub3c4\uc2dc\ub97c \ub300\ud45c\ud558\ub294 \uc77c\uc774 \uc81c\ubc95 \uadfc\uc5c4\ud55c \uc77c\uc778\uc9c0, \uc544\ub2c8\uba74 \uae30\ub150\ud488 \uac00\uac8c \uadfc\ubb34\uac00 \ub354 \ub9c8\uc74c\uc5d0 \ub4dc\ub294\uc9c0. \uadf8 \ud45c\uc815\ub9cc\ud07c\uc740 \ubcf4\ub294 \uc0ac\ub78c\uc774 \uc870\uae08 \uc790\uc720\ub86d\uac8c \uc77d\uc5b4\ub3c4 \uad1c\ucc2e\ub2e4."}, {"id": "apollo-bootprint-close-up", "title": "\ub2ec\uc5d0\uc11c\ub294 \uc2e0\ubc1c \ubc14\ub2e5\ub3c4 \uae30\ub85d\uc774 \ub418\uc5c8\ub2e4", "summary": "NASA\uac00 \uacf5\uac1c\ud55c \ub2ec\uc758 \ubc1c\uc790\uad6d \uc0ac\uc9c4\uc5d0\uc11c \ud0d0\uc0ac\uc758 \uc791\uc740 \ud754\uc801\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history", "category_title": "History", "subcategory": "America", "url": "stories/apollo-bootprint-close-up/index.html", "image": "media/apollo-bootprint-close-up.jpg", "alt": "NASA\uac00 \uc544\ud3f4\ub85c \uc6b0\uc8fc\ube44\ud589\uc0ac\uc758 \ub2ec \ubc1c\uc790\uad6d\uc73c\ub85c \uacf5\uac1c\ud55c \uc2e4\uc81c \uc0ac\uc9c4. \ud45c\uba74\uc5d0 \uc2e0\ubc1c \ubc11\ucc3d\uc758 \uc904\ubb34\ub2ac\uac00 \ub0a8\uc544 \uc788\uc2b5\ub2c8\ub2e4.", "text": "\ub2ec\uc5d0\uc11c\ub294 \uc2e0\ubc1c \ubc14\ub2e5\ub3c4 \uae30\ub85d\uc774 \ub418\uc5c8\ub2e4 \ud070 \ud0d0\uc0ac \uc774\uc57c\uae30\ub97c \uc791\uc740 \ubc1c\uc790\uad6d\uc73c\ub85c \ubcf4\uae30 NASA\uac00 \uacf5\uac1c\ud55c \ub2ec\uc758 \ubc1c\uc790\uad6d \uc0ac\uc9c4\uc5d0\uc11c \ud0d0\uc0ac\uc758 \uc791\uc740 \ud754\uc801\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. America \uc5ed\uc0ac \ub2ec \ud0d0\uc0ac\ub97c \ub5a0\uc62c\ub9ac\uba74 \uc6b0\uc8fc\uc120\uacfc \uc6b0\uc8fc\ubcf5, \uba40\ub9ac \ubcf4\uc774\ub294 \uc9c0\uad6c\uac00 \uba3c\uc800 \uc0dd\uac01\ub09c\ub2e4. \uadf8\ub7f0\ub370 NASA\uc758 \uacf5\uac1c \uc790\ub8cc\uc5d0\ub294 \uc0ac\ub78c\uc758 \uc5bc\uad74\ub3c4 \uc6b0\uc8fc\uc120\ub3c4 \uc5c6\uc774 \ubc1c\uc790\uad6d\uc744 \uac00\uae4c\uc774 \ucc0d\uc740 \uc0ac\uc9c4\uc774 \uc788\ub2e4. \ud654\uba74\uc744 \ucc44\uc6b0\ub294 \uac83\uc740 \ubc14\ub2e5\uc758 \ud759\uacfc \uc2e0\ubc1c \ubc11\ucc3d\uc758 \ubb34\ub2ac\ub2e4. NASA\ub294 \uc774 \uc0ac\uc9c4\uc744 \uc544\ud3f4\ub85c \uc6b0\uc8fc\ube44\ud589\uc0ac\uc758 \ub2ec \ubc1c\uc790\uad6d \uc790\ub8cc\ub85c \uc18c\uac1c\ud55c\ub2e4. \ucee4\ub2e4\ub780 \ud0d0\uc0ac \uc774\uc57c\uae30\ub97c \uc7a0\uc2dc \ub0b4\ub824\ub193\uace0 \ubcf4\uba74, \uc0ac\ub78c\uc774 \uc5b4\ub5a4 \uacf3\uc5d0 \ub2e4\ub140\uac14\ub294\uc9c0\ub97c \uc54c\ub824 \uc8fc\ub294 \uc544\uc8fc \uc775\uc219\ud55c \ud754\uc801\uc774 \ub098\uc628\ub2e4. \uc0ac\uc9c4\uc5d0\ub294 \ubc11\ucc3d\uc758 \uc5ec\ub7ec \uc904\uc774 \ubc1d\uace0 \uc5b4\ub450\uc6b4 \ubd80\ubd84\uc73c\ub85c \ub0a8\uc544 \uc788\ub2e4. \ubc1c\uc790\uad6d\uc758 \ubaa8\uc591\uc744 \uc54c\uc544\ubcf4\ub294 \ub370 \uc2e0\ubc1c \uc804\uccb4\ub098 \uc6b0\uc8fc\ubcf5\uc744 \ubcfc \ud544\uc694\ub294 \uc5c6\ub2e4. \ubc14\ub2e5\uc5d0 \uc62e\uaca8\uc9c4 \ubb34\ub2ac\ub9cc\uc73c\ub85c\ub3c4 \uc0ac\ub78c\uc774 \ub514\ub3a0\ub358 \uc790\ub9ac\ub97c \uc77d\uac8c \ub41c\ub2e4. \uc6b0\ub9ac\ub294 \uc77c\uc0c1\uc5d0\uc11c\ub3c4 \ube44\uc2b7\ud55c \uc77c\uc744 \ud55c\ub2e4. \uc816\uc740 \ubc14\ub2e5\uc774\ub098 \ud759\uae38\uc5d0 \ub0a8\uc740 \uc790\uad6d\uc744 \ubcf4\uace0 \ub204\uad70\uac00 \uc9c0\ub098\uac14\ub2e4\uace0 \uc9d0\uc791\ud55c\ub2e4. \ub0af\uc120 \ub2ec \ud45c\uba74\uc5d0\uc11c \uac11\uc790\uae30 \uadf8\ub7f0 \uac00\uae4c\uc6b4 \uacbd\ud5d8\uc744 \ub9cc\ub098\ub294 \uac83\uc774\ub2e4. \uc774 \uc790\ub8cc\uc758 \uc774\ub984\uc5d0\ub294 \uc544\ud3f4\ub85c\uc640 \ub2ec, \uc6b0\uc8fc\ube44\ud589\uc0ac\uc758 \ubc1c\uc790\uad6d\uc774\ub77c\ub294 \uc815\ubcf4\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \ub355\ubd84\uc5d0 \ub2e8\uc21c\ud55c \ud759\ubc14\ub2e5 \uc0ac\uc9c4\uacfc\ub294 \ub2e4\ub978 \ub9e5\ub77d\uc5d0\uc11c \uc774\ubbf8\uc9c0\ub97c \uc77d\uc744 \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uc0ac\uc9c4 \ud55c \uc7a5\uc5d0 \ubd99\uc740 \uc775\uc219\ud55c \uc774\ub984\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uc0ac\uc815\uc744 \uc54c \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc774 \uc790\uad6d\uc774 \ucd5c\ucd08\uc758 \ubc1c\uc790\uad6d\uc774\ub77c\uace0 \ub2e8\uc815\ud558\uac70\ub098 \uc5b4\ub290 \uc6b0\uc8fc\ube44\ud589\uc0ac\uc758 \uc5b4\ub290 \ubc1c\uc778\uc9c0 \uc815\ud558\uc9c0 \uc54a\ub294\ub2e4. \ud655\uc778\ud55c \uc790\ub8cc\uac00 \uc54c\ub824 \uc8fc\ub294 \ubc94\uc704 \uc548\uc5d0\uc11c \uc0ac\uc9c4\uc744 \ubcf4\ub294 \ud3b8\uc774 \uc815\ud655\ud558\ub2e4. \uc2e0\ubc1c\uc774 \ud45c\uba74\uc744 \ub204\ub974\uba74 \ub2ff\uc740 \ubd80\ubd84\uacfc \uc8fc\ubcc0\uc758 \ucc28\uc774\uac00 \ud754\uc801\uc73c\ub85c \ub0a8\uc744 \uc218 \uc788\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c\ub294 \uadf8 \uad00\uacc4\uac00 \uc904\ubb34\ub2ac\uc758 \ubc1d\uace0 \uc5b4\ub450\uc6b4 \ubd80\ubd84\uc73c\ub85c \ubcf4\uc778\ub2e4. \ubc11\ucc3d \uc790\uccb4\ub294 \ud654\uba74\uc5d0 \uc5c6\uc9c0\ub9cc \ubb34\uc5c7\uc778\uac00\uac00 \ub2ff\uc558\ub358 \ud615\uc0c1\uc744 \uc77d\uac8c \ub41c\ub2e4. \ubb3c\uac74\uc774 \uc790\ub9ac\ub97c \ub5a0\ub09c \ub4a4\uc5d0\ub3c4 \uadf8 \ubaa8\uc591\uc758 \uc77c\ubd80\uac00 \ub2e4\ub978 \uc7ac\ub8cc\uc5d0 \ub0a8\ub294 \uac83\uc774\ub2e4. \uc774 \uc124\uba85\ub9cc\uc73c\ub85c \uc0ac\uc9c4 \uc18d \uc790\uad6d\uc758 \ubaa8\ub4e0 \uc0dd\uc131 \uc870\uac74\uc744 \uc0c8\ub85c \uce21\uc815\ud560 \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc555\ub825\uc774\ub098 \ud1a0\uc591\uc758 \uc0c1\ud0dc, \uc815\ud655\ud55c \uae4a\uc774\ub97c \uc54c\ub824\uba74 \ub2e4\ub978 \uc790\ub8cc\uac00 \ud544\uc694\ud558\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc2e4\uc81c \uc0ac\uc9c4\uc5d0\uc11c \ubcfc \uc218 \uc788\ub294 \ubb34\ub2ac\uc640 \uba85\uc554\uc744 \ub530\ub77c\uac04\ub2e4. \uc775\uc219\ud55c \uc2e0\ubc1c\uc758 \ud615\ud0dc\uac00 \ub0af\uc120 \uc7a5\uc18c\uc758 \ud45c\uba74\uacfc \ub9cc\ub09c\ub2e4\ub294 \uc810\ub9cc\uc73c\ub85c\ub3c4 \ucda9\ubd84\ud788 \ub208\uae38\uc744 \ub048\ub2e4. \uac19\uc740 \ubb3c\uac74\ub3c4 \ube5b\uc744 \uc5b4\ub514\uc5d0\uc11c \ubc1b\ub294\uc9c0\uc5d0 \ub530\ub77c \ud45c\uba74\uc758 \ub192\ub0ae\uc774\uac00 \ub2ec\ub9ac \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \ubc1c\uc790\uad6d \uc0ac\uc9c4\uc758 \uc5b4\ub450\uc6b4 \uc120\uacfc \ubc1d\uc740 \uba74\uc744 \ubc88\uac08\uc544 \ubcf4\uba74 \ud3c9\uba74\uc758 \uc0c9\ubb34\ub2ac\uc640 \ub20c\ub9b0 \uc790\uad6d\uc758 \uc778\uc0c1\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uc0ac\uc9c4\uc740 \ud45c\uba74\uc744 \ubcf4\uc5ec \uc8fc\uc9c0\ub9cc \uadf8 \ubcf4\uc774\ub294 \ubc29\uc2dd\uc5d0\ub294 \ucd2c\uc601\uc758 \uc870\uac74\ub3c4 \ub4e4\uc5b4 \uc788\ub2e4. \uba85\uc554\uc740 \uc815\ubcf4\ub97c \uc804\ud558\ub294 \ud55c \ud1b5\ub85c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uadf8\ub9bc\uc790\ub9cc\uc73c\ub85c \uc2e4\uc81c \uc218\uce58\ub97c \uacc4\uc0b0\ud574 \ud655\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc774 \uae00\uc740 \uc0ac\uc9c4 \uac10\uc0c1\uc758 \uad00\ucc30\uc744 \uc74c\uc601\uc73c\ub85c \uc815\ubc00 \uce21\ub7c9\ud55c \uacb0\uacfc\ucc98\ub7fc \uc81c\uc2dc\ud558\uc9c0 \uc54a\ub294\ub2e4. \ubb34\uc5c7\uc774 \ubcf4\uc774\ub294\uc9c0 \uc815\ud655\ud788 \uc124\uba85\ud558\ub294 \uc77c\ub9cc\uc73c\ub85c\ub3c4 \ucda9\ubd84\ud788 \ud765\ubbf8\ub86d\ub2e4. \ubb34\ub2ac\ub97c \uc54c\uc544\ubcf8 \ub4a4 \ube5b\uc744 \uc0b4\ud53c\uba74 \ud55c \uc7a5\uc758 \uc0ac\uc9c4 \uc548\uc5d0\uc11c \uc0c8\ub85c\uc6b4 \uc815\ubcf4\uac00 \uc0dd\uae34\ub2e4. \ubc1c\uc790\uad6d\uc774\ub77c\ub294 \ud615\uc0c1\ub9cc\uc73c\ub85c \uc774\uacf3\uc774 \ub2ec\uc778\uc9c0 \ub2e4\ub978 \uacf3\uc778\uc9c0 \uc0ac\uc9c4 \ubc16\uc758 \ub9e5\ub77d\uc744 \ubaa8\ub450 \uc54c \uc218\ub294 \uc5c6\ub2e4. NASA\uac00 \ubd99\uc778 \uc790\ub8cc\uba85\uacfc \uc81c\uacf5 \uc815\ubcf4\ub97c \ud568\uaed8 \uc77d\uc5b4\uc57c \uc544\ud3f4\ub85c \ud65c\ub3d9\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uc0ac\uc9c4\uacfc \ucea1\uc158\uc740 \uc11c\ub85c \ub2e4\ub978 \uc5ed\ud560\uc744 \ub9e1\uc73c\uba70 \ud568\uaed8 \uae30\ub85d\uc744 \uc774\ub8ec\ub2e4. \uc798 \uc54c\ub824\uc9c4 \uc774\ubbf8\uc9c0\ub97c \ub2e4\uc2dc \ub9cc\ub0a0 \ub54c\uc5d0\ub3c4 \uadf8 \uc124\uba85\uc744 \ud655\uc778\ud560 \uc774\uc720\uac00 \uc788\ub2e4. \ud2b9\ud788 \ucd5c\ucd08\ub77c\ub294 \ub2e8\uc5b4\ub294 \uc870\uc2ec\ud574\uc11c \ubd99\uc5ec\uc57c \ud55c\ub2e4. \uc720\uba85\ud55c \uc0ac\uc9c4\uc774\ub77c\uace0 \uc778\ub958\uc758 \uccab \ubc1c\uc790\uad6d\uc744 \uc9c1\uc811 \ucc0d\uc740 \uc7a5\uba74\uc774\ub77c\uace0 \uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc5b4\ub290 \uc6b0\uc8fc\ube44\ud589\uc0ac\uc758 \uc5b4\ub290 \ubc1c\uc778\uc9c0\ub3c4 \uc774 \uc6d0\uace0\uac00 \ud655\uc778\ud55c \uc790\ub8cc\uc758 \ubc94\uc704 \ubc16\uc5d0 \uc788\ub2e4. \uc774\ubbf8\uc9c0\ub97c \ub35c \uadf9\uc801\uc73c\ub85c \uc18c\uac1c\ud558\ub354\ub77c\ub3c4 \uae30\ub85d\uc758 \uac00\uce58\ub294 \uc904\uc9c0 \uc54a\ub294\ub2e4. \ud655\uc778\ub41c \ubc94\uc704\ub97c \ubd84\uba85\ud788 \ud574\uc57c \ub2e4\ub978 \uc790\ub8cc\uc640\ub3c4 \uc815\ud655\ud788 \uc5f0\uacb0\ud560 \uc218 \uc788\ub2e4. \uc6b0\uc8fc \ud0d0\uc0ac\ub294 \ub85c\ucf13\uacfc \uae30\uacc4\uc758 \ud070 \ubaa8\uc2b5\uc73c\ub85c \uae30\uc5b5\ub418\uae30 \uc27d\ub2e4. \ubc1c\uc790\uad6d\uc740 \uadf8 \ud65c\ub3d9\uc5d0 \uc0ac\ub78c\uc758 \ubab8\uc774 \ucc38\uc5ec\ud588\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc77c\uc0c1\uc801\uc778 \ub3d9\uc791\uc73c\ub85c \uc804\ud55c\ub2e4. \ud55c \ubc88 \ub514\ub514\ub294 \uc77c\uc740 \ub108\ubb34 \uc775\uc219\ud558\uc9c0\ub9cc \uc7a5\uc18c\uac00 \ub2ec\ub77c\uc9c0\uba74 \uae30\ub85d\ud560 \ub9cc\ud55c \ud589\ub3d9\uc774 \ub41c\ub2e4. \ud070 \uae30\uc220\uc758 \uc5ed\uc0ac\ub97c \uc190\uacfc \ubc1c\uc758 \ud06c\uae30\uc5d0\uc11c \ub9cc\ub098\ub294 \uc785\uad6c\ub2e4. \uc774\uac83\uc774 \uc0ac\uc9c4 \uc18d \ubaa8\ub4e0 \uac10\uc815\uc744 \uc54c\ub824 \uc900\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ub2f9\uc2dc \uc0ac\ub78c\uc774 \uc5b4\ub5a4 \uc0dd\uac01\uc744 \ud588\ub294\uc9c0 \ub300\uc0ac\ub97c \uafb8\ubbf8\uae30\ubcf4\ub2e4 \ub0a8\uc740 \ud754\uc801\uc744 \ucc28\ubd84\ud558\uac8c \ubcfc \uc218 \uc788\ub2e4. \ud654\uba74\uc744 \uac00\uae4c\uc774 \ubcf4\uba70 \uc904\uc758 \uac04\uaca9\uacfc \ud45c\uba74\uc758 \ub2e4\ub978 \uc790\uad6d\uc744 \uc0b4\ud3b4\ubcf4\uc790. \uba40\ub9ac \uc788\ub294 \uc7a5\uc18c\uc758 \uc774\uc57c\uae30\uac00 \ubc1c\ubc14\ub2e5 \ubb34\ub2ac\ub77c\ub294 \uac00\uae4c\uc6b4 \ud615\uc0c1\uc73c\ub85c \uc6b0\ub9ac\uc5d0\uac8c \uc804\ub2ec\ub418\uc5c8\ub2e4\ub294 \uc810\uc774 \uc624\ub798 \ub0a8\ub294\ub2e4. \uc774 \uc774\ubbf8\uc9c0\ub294 NASA\uac00 \uacf5\uac1c\ud55c \uc2e4\uc81c \uc0ac\uc9c4\uc774\ub2e4. \uc0bd\ud654\ub85c \ubc11\ucc3d\uc744 \ub2e4\uc2dc \uadf8\ub9ac\uc9c0 \uc54a\uace0 \uc6d0\ub798 \uc0ac\uc9c4\uc744 \ud568\uaed8 \uc2e4\uc740 \uc774\uc720\ub3c4 \uc5ec\uae30\uc5d0 \uc788\ub2e4. \uc5b4\ub5a4 \ubb34\ub2ac\uac00 \uc5b4\ub5bb\uac8c \ub0a8\uc558\ub294\uc9c0\ub294 \uc2e4\uc81c \uc790\ub8cc\ub97c \ubcf4\ub294 \ud3b8\uc774 \ud6e8\uc52c \ube60\ub974\ub2e4. \uc6b0\uc8fc \ud0d0\uc0ac\ub294 \uac70\ub300\ud55c \uae30\uacc4\ub9cc\uc758 \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub2e4. \uc0ac\ub78c\uc758 \ubab8\uc744 \uac10\uc2fc \uc637\uacfc \ubc1c\uc744 \ub514\ub518 \uc2e0\ubc1c\ub3c4 \ud568\uaed8 \uc6c0\uc9c1\uc600\ub2e4. \ub2ec\uc744 \ubcf4\uace0 \uace0\uac1c\ub97c \ub4e4\ub358 \uc2dc\uc120\uc744 \uc774\ubc88\uc5d0\ub294 \uc544\ub798\ub85c \ub0b4\ub824 \ubcf4\uc790. \uc791\uc740 \ubc11\ucc3d\uc758 \ud754\uc801\uc5d0\uc11c\ub3c4 \ud0d0\uc0ac\uc758 \ub2e4\ub978 \uc5bc\uad74\uc744 \ub9cc\ub0a0 \uc218 \uc788\ub2e4."}, {"id": "arpanet-first-node", "title": "\uc778\ud130\ub137\uc5d0\ub3c4 \uccab \ubc88\uc9f8 \uc815\uac70\uc7a5\uc774 \uc788\uc5c8\ub2e4", "summary": "\uc5b4\ub514\uc5d0\ub098 \uc788\ub294 \uc778\ud130\ub137\ub3c4 \ucc98\uc74c\uc5d0\ub294 \uba87\uba87 \ucef4\ud4e8\ud130\ub97c \uc787\ub294 \uc2e4\ud5d8\uc5d0\uc11c \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.", "category": "history", "category_title": "History", "subcategory": "America", "url": "stories/arpanet-first-node/index.html", "image": "media/arpanet-first-node.jpg", "alt": "\ub450 \uc5f0\uad6c\uc2e4\uc758 \uc77c\ubc18\ud654\ud55c \ucd08\uae30 \ucef4\ud4e8\ud130\ub97c \uc120\uc73c\ub85c \uc5f0\uacb0\ud55c \uc124\uba85\uc6a9 AI \uc0bd\ud654", "text": "\uc778\ud130\ub137\uc5d0\ub3c4 \uccab \ubc88\uc9f8 \uc815\uac70\uc7a5\uc774 \uc788\uc5c8\ub2e4 1969\ub144, \uc5f0\uad6c\uc2e4\uc758 \ucef4\ud4e8\ud130\uac00 \uc5f0\uacb0\ub418\ub358 \ub54c \uc5b4\ub514\uc5d0\ub098 \uc788\ub294 \uc778\ud130\ub137\ub3c4 \ucc98\uc74c\uc5d0\ub294 \uba87\uba87 \ucef4\ud4e8\ud130\ub97c \uc787\ub294 \uc2e4\ud5d8\uc5d0\uc11c \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4. America \uc5ed\uc0ac \uc778\ud130\ub137\uc740 \ub208\uc5d0 \ubcf4\uc774\ub294 \uac74\ubb3c \ud558\ub098\uac00 \uc544\ub2c8\uc5b4\uc11c \ucd9c\ubc1c\uc810\uc744 \uc0c1\uc0c1\ud558\uae30 \uc5b4\ub835\ub2e4. \ud734\ub300\uc804\ud654\uc758 \ud654\uba74\uc744 \uc5f4\uba74 \uc774\ubbf8 \uadf8 \uc548\uc5d0 \uc788\uace0, \ub2e4\ub978 \ub098\ub77c\uc758 \uc18c\uc2dd\ub3c4 \uae08\uc138 \ub3c4\ucc29\ud55c\ub2e4. \uadf8\ub7f0\ub370 \uc624\ub298\uc758 \uc778\ud130\ub137\uc73c\ub85c \uc774\uc5b4\uc9c4 \ucd08\uae30 \ub124\ud2b8\uc6cc\ud06c\uc5d0\ub294 \uc2e4\uc81c \ucef4\ud4e8\ud130\uac00 \ub193\uc778 \uc5f0\uad6c\uc2e4\ub4e4\uc774 \uc788\uc5c8\ub2e4. \uadf8\uc911 \uccab \ubc88\uc9f8 \uc9c0\uc810\uc740 \ubbf8\uad6d UCLA\uc758 \ub808\ub108\ub4dc \ud074\ub77c\uc778\ub85d \uc5f0\uad6c\uc2e4\uc774\uc5c8\ub2e4. \uc778\ud130\ub137 \uba85\uc608\uc758 \uc804\ub2f9\uc740 \uadf8 \uc5f0\uad6c\uc2e4\uc758 \ucef4\ud4e8\ud130\uac00 1969\ub144 9\uc6d4 ARPANET\uc758 \uccab \ub178\ub4dc\uac00 \ub418\uc5c8\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \ub178\ub4dc\ub294 \uc5ec\uae30\uc11c \ub124\ud2b8\uc6cc\ud06c\uc5d0 \uc5f0\uacb0\ub418\ub294 \uc9c0\uc810\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uba74 \ub41c\ub2e4. \ubcf4\uc774\uc9c0 \uc54a\ub294 \uae38\uc758 \uccab \uc815\uac70\uc7a5\uc5d0 \uc8fc\uc18c\uc9c0\uac00 \uc788\uc5c8\ub358 \uc148\uc774\ub2e4. ARPANET\uc740 \uc624\ub298\uc758 \uc778\ud130\ub137\uc73c\ub85c \uc774\uc5b4\uc9c4 \ucd08\uae30 \ub124\ud2b8\uc6cc\ud06c\ub2e4. \uc9c0\uae08\uc758 \uc6f9\uc0ac\uc774\ud2b8\uc640 \uba54\uc2e0\uc800\uac00 \ubaa8\ub450 \uac16\ucd94\uc5b4\uc9c4 \uc0c1\ud0dc\ub85c \uc2dc\uc791\ud55c \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc6b0\uc120 \uc11c\ub85c \ub5a8\uc5b4\uc9c4 \ucef4\ud4e8\ud130\uac00 \uc815\ubcf4\ub97c \uc8fc\uace0\ubc1b\uc744 \uc218 \uc788\uc5b4\uc57c \ud588\ub2e4. \ud074\ub77c\uc778\ub85d\uc758 \uc5f0\uad6c\uc2e4\uc5d0\uc11c\ub294 \uccab \uc5f0\uacb0 \uc9c0\uc810\uc744 \ub9c8\ub828\ud55c \ub2e4\uc74c \ub2ec, \ub124\ud2b8\uc6cc\ud06c\ub97c \ud1b5\ud55c \uccab \uc804\uc1a1\uc774 \uc774\ub8e8\uc5b4\uc84c\ub2e4. \ub2e4\ub978 \ub05d\uc5d0\ub294 \uce98\ub9ac\ud3ec\ub2c8\uc544 SRI\uc758 \uc5f0\uad6c\ud300\uc774 \uc788\uc5c8\ub2e4. \uc778\ud130\ub137 \uba85\uc608\uc758 \uc804\ub2f9\uc740 \ub354\uae00\ub7ec\uc2a4 \uc5e5\uac94\ubc14\ud2b8\uac00 \uc774\ub04c\ub358 \uc5f0\uad6c\uc18c\uac00 \ub450 \ubc88\uc9f8 \ud638\uc2a4\ud2b8\uac00 \ub418\uc5b4 UCLA\uc640 \ucd08\uae30 \uc804\uc1a1\uc744 \uc8fc\uace0\ubc1b\uc558\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc7a5\uc18c\uc758 \uc5f0\uad6c\uac00 \ud558\ub098\uc758 \uc5f0\uacb0 \uc548\uc5d0\uc11c \ub9cc\ub09c \uac83\uc774\ub2e4. \uc624\ub298\uc758 \uac10\uac01\uc73c\ub85c \ubcf4\uba74 \ucef4\ud4e8\ud130 \ub450 \uacf3\uc774 \ub300\ud654\ud558\ub294 \uc77c\uc740 \uc791\uc740 \uc131\uacfc\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uc5f0\uacb0\uc774 \ub2f9\uc5f0\ud558\uc9c0 \uc54a\uc558\ub358 \uc2dc\uc810\uc5d0\ub294, \uadf8 \ub300\ud654\uac00 \uc774\ub8e8\uc5b4\uc9c0\ub3c4\ub85d \uc870\uac74\uc744 \ub9cc\ub4dc\ub294 \uc77c\ubd80\ud130 \ud544\uc694\ud588\ub2e4. \uc778\ud130\ub137\uc758 \uc2dc\uc791\uc744 \ud55c \uc0ac\ub78c\uc758 \uc0ac\uc9c4\uc73c\ub85c \uc124\uba85\ud558\ub824 \ud558\uba74 \uae08\uc138 \ub2e4\ub978 \uc774\ub984\ub4e4\uc774 \ub4f1\uc7a5\ud55c\ub2e4. \uc5f0\uacb0\uc758 \uc6d0\ub9ac\ub97c \uc5f0\uad6c\ud55c \uc0ac\ub78c, \ucef4\ud4e8\ud130\ub97c \uc900\ube44\ud55c \uc0ac\ub78c, \uc18c\ud504\ud2b8\uc6e8\uc5b4\uc640 \ud1b5\uc2e0 \uaddc\uce59\uc744 \ub9cc\ub4e0 \uc0ac\ub78c\ub4e4\uc774 \uc788\uc5c8\ub2e4. \ud074\ub77c\uc778\ub85d\uc740 \ud328\ud0b7 \ub124\ud2b8\uc6cc\ud06c\uc758 \uc218\ud559\uc801 \uc5f0\uad6c\ub85c\ub3c4 \uc18c\uac1c\ub41c\ub2e4. \uc815\ubcf4\ub97c \uc77c\uc815\ud55c \ub2e8\uc704\ub85c \ub098\ub204\uc5b4 \ubcf4\ub0b4\ub294 \ubc29\uc2dd\uc774 \ub124\ud2b8\uc6cc\ud06c\ub97c \uc774\ud574\ud558\ub294 \uc911\uc694\ud55c \ubc14\ud0d5\uc774 \ub418\uc5c8\ub2e4\ub294 \uac83\uc774\ub2e4. \uc5ec\uae30\uc11c \uc5b4\ub824\uc6b4 \uc218\uc2dd\uc744 \ub530\ub77c\uac08 \ud544\uc694\ub294 \uc5c6\ub2e4. \ucef4\ud4e8\ud130\ub97c \uc5f0\uacb0\ud558\ub294 \ub370\uc5d0\ub3c4 \uc5f0\uad6c\uac00 \ud544\uc694\ud588\ub2e4\ub294 \uc815\ub3c4\uba74 \ucda9\ubd84\ud558\ub2e4. \uccab \ubc88\uc9f8 \uc9c0\uc810\uc5d0 \uad00\uc2ec\uc744 \ub450\ub294 \uac83\uc740 \uadf8 \ud55c \uacf3\uc774 \ubaa8\ub4e0 \uac83\uc744 \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \uc5f0\uacb0\uc740 \uc0c1\ub300\uac00 \uc788\uc5b4\uc57c \uc131\ub9bd\ud55c\ub2e4. \uccab \uc815\uac70\uc7a5\uc774\ub77c\ub294 \ud45c\ud604\ub3c4 \ub450 \ubc88\uc9f8 \uc815\uac70\uc7a5\uc774 \uc0dd\uacbc\uc744 \ub54c \ube44\ub85c\uc18c \uc2e4\uac10\uc774 \ub09c\ub2e4. \ud55c \uc7a5\uc18c\uc5d0 \uc7a5\ube44\ub97c \ub9c8\ub828\ud558\ub294 \uc77c\uacfc \ub2e4\ub978 \uc7a5\uc18c\uc640 \uc815\ubcf4\ub97c \uc8fc\uace0\ubc1b\ub294 \uc77c\uc740 \uc774\uc5b4\uc9c0\uc9c0\ub9cc \ub2e4\ub974\ub2e4. \uc5f0\uad6c\uc2e4\uc758 \uccab \ub178\ub4dc\ub77c\ub294 \uae30\ub85d\uc740 \uadf8\uacf3\ub9cc\uc73c\ub85c \ub124\ud2b8\uc6cc\ud06c\uac00 \uc644\uc131\ub418\uc5c8\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \uc0c1\ub300\ud3b8\uc758 \uc7a5\ube44\uc640 \uc18c\ud504\ud2b8\uc6e8\uc5b4, \uc11c\ub85c \uc774\ud574\ud560 \ud1b5\uc2e0 \ubc29\uc2dd\ub3c4 \ud544\uc694\ud588\ub2e4. \uccab \uc815\uac70\uc7a5\uc774\ub77c\ub294 \ube44\uc720\ub294 \ud568\uaed8 \uc774\uc5b4\uc9c0\ub294 \ub2e4\ub978 \uc9c0\uc810\uc774 \uc788\uc744 \ub54c \uad6c\uccb4\uc801\uc778 \uc758\ubbf8\ub97c \uc5bb\ub294\ub2e4. \uadf8\ub798\uc11c UCLA\uc640 SRI\uc758 \uc774\ub984\uc744 \ud568\uaed8 \uae30\uc5b5\ud558\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc778\ud130\ub137\uc758 \uc5ed\uc0ac\ub97c \ud55c \uc5f0\uad6c\uc790\uc758 \uc5c5\uc801\uc73c\ub85c\ub9cc \uc904\uc774\uba74 \uc2e4\uc81c \uc5f0\uacb0\uc744 \uac00\ub2a5\ud558\uac8c \ud55c \uc5ec\ub7ec \uc5ed\ud560\uc774 \ubc30\uacbd\uc73c\ub85c \ubb3c\ub7ec\ub09c\ub2e4. \ub204\uac00 \ucc98\uc74c\uc774\ub0d0\ub294 \uc9c8\ubb38 \uc606\uc5d0 \uc5b4\ub290 \uacf3\uacfc \ubb34\uc5c7\uc744 \uc8fc\uace0\ubc1b\uc558\ub290\ub0d0\ub97c \ub193\uc73c\uba74 \uc0ac\uac74\uc758 \uc131\uaca9\uc774 \ub354 \ubd84\uba85\ud574\uc9c4\ub2e4. \ub124\ud2b8\uc6cc\ud06c\ub294 \uad00\uacc4\ub97c \ub9cc\ub4dc\ub294 \uae30\uc220\uc774\uae30\ub3c4 \ud558\ub2e4. \ud328\ud0b7\uc774\ub77c\ub294 \ub9d0\uc740 \uc815\ubcf4\ub97c \uc804\uc1a1\ud560 \ub54c \uc77c\uc815\ud55c \ub2e8\uc704\ub85c \ub098\ub204\uc5b4 \ub2e4\ub8e8\ub294 \uac1c\ub150\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uae34 \ub0b4\uc6a9\uc744 \ud558\ub098\uc758 \ub369\uc5b4\ub9ac\ub85c\ub9cc \uc0dd\uac01\ud558\uc9c0 \uc54a\uace0 \uc804\ub2ec\ud560 \ub2e8\uc704\uc640 \uaddc\uce59\uc744 \uc900\ube44\ud558\ub294 \uac83\uc774\ub2e4. \uc6b0\ud3b8\uc758 \ubd09\ud22c\uc5d0 \ube57\ub300\uba74 \uc774\ud574\ub97c \ub3c4\uc6b8 \uc218 \uc788\uc9c0\ub9cc \uc2e4\uc81c \ucef4\ud4e8\ud130\uc758 \ud1b5\uc2e0\uc774 \uc885\uc774 \uc6b4\ubc18\uacfc \ub611\uac19\uc740 \uc6d0\ub9ac\ub85c \uc774\ub8e8\uc5b4\uc9c4\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub824\uc6b4 \uc218\ud559\uc744 \ubab0\ub77c\ub3c4 \uc5f0\uad6c\uac00 \ud544\uc694\ud55c \uc774\uc720\ub294 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uc5ec\ub7ec \uc7a5\uce58\uac00 \uc815\ubcf4\ub97c \ubcf4\ub0b4\ub824 \ud560 \ub54c \ubb34\uc5c7\uc744 \uc5b4\ub5a4 \uc21c\uc11c\uc640 \uaddc\uce59\uc73c\ub85c \ub2e4\ub8f0\uc9c0 \uc815\ud574\uc57c \ud55c\ub2e4. \uc120\uc744 \uc5f0\uacb0\ud558\ub294 \uc77c\ub9cc\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\ub294 \ubb38\uc81c\ub2e4. \ud074\ub77c\uc778\ub85d\uc758 \ud328\ud0b7 \ub124\ud2b8\uc6cc\ud06c \uc5f0\uad6c\uac00 \ud568\uaed8 \uc18c\uac1c\ub418\ub294 \uac83\uc740 \uc7a5\ube44 \ub4a4\uc5d0 \uc774\ub7f0 \uc774\ub860\uacfc \uc124\uacc4\uc758 \uc9c8\ubb38\uc774 \uc788\uc5c8\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc624\ub298\uc740 \uc778\ud130\ub137\uc744 \uc5f4\uc5c8\ub2e4\uace0 \ub9d0\ud558\uba70 \ube0c\ub77c\uc6b0\uc800\ubd80\ud130 \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \ucd08\uae30 \uc5f0\uacb0\uc758 \uc2dc\uae30\uc5d0\ub294 \ud604\uc7ac\uc758 \uc6f9 \ud658\uacbd\uc774 \uac16\ucd94\uc5b4\uc838 \uc788\uc9c0 \uc54a\uc558\ub2e4. \uc11c\ub85c \ub2e4\ub978 \ucef4\ud4e8\ud130\uac00 \uc790\ub8cc\ub97c \uc8fc\uace0\ubc1b\ub294 \uae30\ubc18\uc758 \uc5ed\uc0ac\uc640 \uadf8 \uc704\uc5d0\uc11c \ubb38\uc11c\ub97c \uc77d\ub294 \uc6f9\uc758 \uc5ed\uc0ac\ub294 \uad6c\ubd84\ud560 \uc218 \uc788\ub2e4. \ud55c \uae30\uc220\uc774 \ub098\uc628 \ub0a0 \ubaa8\ub4e0 \uc11c\ube44\uc2a4\uac00 \ud568\uaed8 \uc0dd\uae34 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc61b \uc5f0\uad6c\uc2e4\uc744 \ubcfc \ub54c \uc624\ub298\uc758 \ud654\uba74\uc744 \uadf8\ub300\ub85c \ub367\uc50c\uc6b0\uc9c0 \uc54a\uc73c\uba74 \uc791\uc740 \uc131\ucde8\uac00 \ub2e4\ub974\uac8c \ub290\uaef4\uc9c4\ub2e4. \uc775\uc219\ud55c \uadf8\ub9bc\uc774\ub098 \uac80\uc0c9\ucc3d\uc774 \uc5c6\ub354\ub77c\ub3c4 \uc815\ubcf4\ub97c \ubcf4\ub0b4\uace0 \ubc1b\ub294 \uc77c\uc774 \uac00\ub2a5\ud574\uc9c0\uba74 \ub2e4\uc74c\uc758 \uc2e4\ud5d8\uc744 \ud560 \uc218 \uc788\uc5c8\ub2e4. \uae30\uc220\uc758 \uc2dc\uc791\uc744 \uc77d\ub294 \uc7ac\ubbf8\ub294 \uc9c0\uae08\ubcf4\ub2e4 \ubd80\uc871\ud55c \uac83\uc744 \ucc3e\ub294 \ub370\ubcf4\ub2e4, \ub2f9\uc2dc \ubb34\uc5c7\uc744 \uc0c8\ub85c \ud560 \uc218 \uc788\uc5c8\ub294\uc9c0 \uc54c\uc544\ubcf4\ub294 \ub370 \uc788\ub2e4. \uc774 \ucd08\uae30 \uc2e4\ud5d8\uacfc \uc9c0\uae08 \uc6b0\ub9ac\uac00 \uc0ac\uc6a9\ud558\ub294 \uc778\ud130\ub137 \uc0ac\uc774\uc5d0\ub294 \uc624\ub79c \uac1c\ubc1c \uacfc\uc815\uc774 \uc788\ub2e4. \uadf8 \uc0ac\uc774\ub97c \ud55c \ubc88\uc758 \uc804\uc1a1\uc73c\ub85c \uac74\ub108\ub6f0\uba74 \uc791\uc740 \uc2dc\uc791\uc774 \uc624\ud788\ub824 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ub124\ud2b8\uc6cc\ud06c\uac00 \uc810\uc810 \ub113\uc5b4\uc9c0\uae30 \uc804, \ub204\uad70\uac00\ub294 \ub2e4\ub978 \uc5f0\uad6c\uc2e4\uae4c\uc9c0 \uc2e0\ud638\uac00 \uc804\ub2ec\ub418\ub294\uc9c0 \ud655\uc778\ud558\uace0 \uc788\uc5c8\ub2e4. \uadf8\ub54c\uc758 \ucef4\ud4e8\ud130\uc640 \uc624\ub298\uc758 \ud734\ub300\uc804\ud654\ub294 \ubaa8\uc2b5\uc774 \ud06c\uac8c \ub2e4\ub974\uc9c0\ub9cc, \ub5a8\uc5b4\uc9c4 \uacf3\uc73c\ub85c \uc815\ubcf4\ub97c \ubcf4\ub0b8\ub2e4\ub294 \uc77c\uc740 \uc774\uc5b4\uc838 \uc788\ub2e4. \ub2e4\uc74c\uc5d0 \uba40\ub9ac \uc788\ub294 \uc0ac\ub78c\uc5d0\uac8c \uba54\uc2dc\uc9c0\ub97c \ubcf4\ub0b8\ub2e4\uba74 \uc7a0\uae50 \uc61b \uc5f0\uad6c\uc2e4\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc544\ub3c4 \uc88b\uaca0\ub2e4. \uc6b0\ub9ac\uac00 \uc7a5\uc18c\ub97c \uc758\uc2dd\ud558\uc9c0 \uc54a\uace0 \uac74\ub108\uac00\ub294 \uae38\ub3c4, \ucc98\uc74c\uc5d0\ub294 \ucef4\ud4e8\ud130\uac00 \ub193\uc778 \uad6c\uccb4\uc801\uc778 \uc7a5\uc18c\uc5d0\uc11c \uc2dc\uc791\ub418\uc5c8\ub2e4."}, {"id": "british-calendar-eleven-days", "title": "9\uc6d4 2\uc77c \ub2e4\uc74c \ub0a0\uc774 14\uc77c\uc774\uc5c8\ub358 \ub2ec\ub825", "summary": "1752\ub144 9\uc6d4 \ub2ec\ub825\uc758 \ub0a0\uc9dc\uac00 \uac74\ub108\ub6f0\ub294 \uc774\uc720\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history", "category_title": "History", "subcategory": "Europe", "url": "stories/british-calendar-eleven-days/index.html", "image": "media/british-calendar-eleven-days.jpg", "alt": "1752\ub144 9\uc6d4\uc758 \uc601\uad6d \ub2ec\ub825 \uaddc\uce59\uc744 \uc7ac\uad6c\uc131\ud55c \uc124\uba85\ub3c4. \ud654\uc694\uc77c 1\uc77c, \uc218\uc694\uc77c 2\uc77c \ub2e4\uc74c\uc774 \ubaa9\uc694\uc77c 14\uc77c\uc774\uba70 3\uc77c\ubd80\ud130 13\uc77c\uc740 \uc0dd\ub7b5\ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.", "text": "9\uc6d4 2\uc77c \ub2e4\uc74c \ub0a0\uc774 14\uc77c\uc774\uc5c8\ub358 \ub2ec\ub825 \uc601\uad6d \ub2ec\ub825\uc5d0 \ub0a8\uc740 \uc5f4\ud558\ub8e8\uc758 \ube48\uc790\ub9ac 1752\ub144 9\uc6d4 \ub2ec\ub825\uc758 \ub0a0\uc9dc\uac00 \uac74\ub108\ub6f0\ub294 \uc774\uc720\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Europe \uc5ed\uc0ac 9\uc6d4 \ub2ec\ub825\uc744 \ud3bc\ucce4\ub294\ub370 2\uc77c \uc606\uc5d0 14\uc77c\uc774 \uc801\ud600 \uc788\ub2e4. 3\uc77c\ubd80\ud130 13\uc77c\uae4c\uc9c0\uac00 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uc778\uc1c4\ub97c \uc798\ubabb\ud55c \uac83 \uac19\uc9c0\ub9cc, \ub2ec\ub825\uc744 \ubc14\uafb8\ub358 \uc2dc\uae30\uc758 \ub0a0\uc9dc\ub97c \ubcf4\uc5ec \uc8fc\ub294 \ubc29\ubc95\uc77c \uc218 \uc788\ub2e4. 1752\ub144 \uc601\uad6d \uc81c\uad6d\uc758 \uadf8\ub808\uace0\ub9ac\ub825 \uc804\ud658\uc744 \ubc18\uc601\ud55c \ub2ec\ub825\uc5d0\uc11c\ub294 9\uc6d4 2\uc77c \ub4a4\uc5d0 14\uc77c\uc774 \uc774\uc5b4\uc9c4\ub2e4. \ub0a0\uc9dc \uc774\ub984 \uc5f4\ud55c \uac1c\ub97c \uac74\ub108\ub6f4 \uac83\uc774\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \uadf8\ub9cc\ud07c \uc7a0\ub4e4\uc5b4 \uc788\uc5c8\ub2e4\ub294 \uc774\uc57c\uae30\ub294 \ubb3c\ub860 \uc544\ub2c8\ub2e4. \ucef4\ud4e8\ud130 \ub2ec\ub825 \ud504\ub85c\uadf8\ub7a8 cal\uc758 \uacf5\uc2dd \uc124\uba85\uc11c\ub294 \uc728\ub9ac\uc6b0\uc2a4\ub825\uacfc \uadf8\ub808\uace0\ub9ac\ub825\uc774 \uc724\ub144\uc744 \ub450\ub294 \ube48\ub3c4\uc5d0\uc11c \uc791\uc740 \ucc28\uc774\ub97c \uac00\uc9c4\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uadf8\ub808\uace0\ub9ac\ub825\uc740 \ucd98\ubd84 \uac19\uc740 \ud0dc\uc591\uc758 \uc8fc\uae30\uc640 \ub2ec\ub825\uc744 \ub354 \uc798 \ub9de\ucd94\ub824\ub294 \uc870\uc815\uc774\ub2e4. \uc774\ub984\uc740 \uc5b4\ub824\uc6cc\ub3c4 \ucd9c\ubc1c\uc810\uc740 \uce5c\uc219\ud558\ub2e4. \uc6b0\ub9ac\uac00 \uc138\ub294 \ub2ec\ub825\uc758 \ub0a0\uc9dc\uc640 \uacc4\uc808\uc758 \ud750\ub984\uc774 \uacc4\uc18d \uc5b4\uae0b\ub098\uc9c0 \uc54a\ub3c4\ub85d \ub9de\ucd94\ub294 \ubb38\uc81c\ub2e4. \uc624\ub798 \uc4f0\ub358 \uaddc\uce59\uc744 \ubc14\uafb8\uba74\uc11c \uc313\uc778 \ucc28\uc774\ub97c \ud55c \ubc88\uc5d0 \uc870\uc815\ud560 \ud544\uc694\uac00 \uc0dd\uacbc\ub2e4. \uc774 \uc124\uba85\uc11c\uc758 \uae30\ubcf8 \ub2ec\ub825\uc740 1752\ub144\uc758 \uc804\ud658\uc744 \ubc18\uc601\ud574 3\uc77c\ubd80\ud130 13\uc77c\uae4c\uc9c0\ub97c \ud45c\uc2dc\ud558\uc9c0 \uc54a\ub294\ub2e4. \uadf8\ub798\uc11c \uadf8\ud574 9\uc6d4\uc744 \ucc3e\uc73c\uba74 \ubcf4\ud1b5 \ub2ec\uacfc \ub2e4\ub978 \ubc30\uc5f4\uc744 \ub9cc\ub098\uac8c \ub41c\ub2e4. \ubaa8\ub4e0 \ub098\ub77c\uac00 \uac19\uc740 \ub0a0 \ub2ec\ub825\uc744 \ubc14\uafbc \uac83\uc740 \uc544\ub2c8\ub2e4. \ub530\ub77c\uc11c 1752\ub144 9\uc6d4\uc740 \uc138\uacc4 \uc5b4\ub514\uc11c\ub098 \ub611\uac19\uc558\ub2e4\uace0 \uc0dd\uac01\ud558\uba74 \uc548 \ub41c\ub2e4. \uc5b4\ub290 \uc9c0\uc5ed\uc758 \ub2ec\ub825 \uaddc\uce59\uc73c\ub85c \ub0a0\uc9dc\ub97c \ubcf4\uace0 \uc788\ub294\uc9c0\uac00 \ud568\uaed8 \ud544\uc694\ud558\ub2e4. 9\uc6d4 2\uc77c \ub2e4\uc74c\uc744 14\uc77c\ub85c \ubd80\ub978\ub2e4\uace0 \uc0ac\ub78c\ub4e4\uc774 \uc2e4\uc81c\ub85c 11\uc77c \ub3d9\uc548 \uc544\ubb34 \uc77c\ub3c4 \ud558\uc9c0 \uc54a\uc740 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud558\ub8e8\ub294 \uacc4\uc18d \uc774\uc5b4\uc84c\uc9c0\ub9cc \ub2ec\ub825\uc5d0\uc11c \ub0a0\uc9dc\ub97c \ubd99\uc774\ub294 \uaddc\uce59\uc744 \ubc14\uafbc \uac83\uc774\ub2e4. \uc774 \uad6c\ubd84\uc744 \uc54c\uba74 \ub0a0\uc9dc\uac00 \uc0ac\ub77c\uc84c\ub2e4\ub294 \ud45c\ud604\uc744 \uc870\uae08 \uc815\ud655\ud558\uac8c \uc77d\uc744 \uc218 \uc788\ub2e4. \ube44\uc5b4 \ubcf4\uc774\ub294 \uce78\uc740 \uc2dc\uac04\uc774 \uba48\ucd98 \ud754\uc801\uc774 \uc544\ub2c8\ub77c \ud45c\uae30\uc758 \uc804\ud658\uc774\ub2e4. 3\uc77c\ubd80\ud130 13\uc77c\uae4c\uc9c0\ub97c \uc138\uba74 \uc5f4\ud55c \uac1c\uc758 \ub0a0\uc9dc\uac00 \ub41c\ub2e4. \ucef4\ud4e8\ud130 \ub2ec\ub825\uc5d0 \uadf8 \uc22b\uc790\ub4e4\uc774 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uac83\uc740 \uace0\uc7a5\uc744 \ub73b\ud558\uc9c0 \uc54a\ub294\ub2e4. \ud2b9\uc815\ud55c \uc9c0\uc5ed\uc758 \uc804\ud658 \uaddc\uce59\uc744 \ubc18\uc601\ud558\ub3c4\ub85d \ub9cc\ub4e0 \uacb0\uacfc\uc77c \uc218 \uc788\ub2e4. \ud654\uba74\uc5d0\uc11c \uc774\uc0c1\ud55c \ubc30\uc5f4\uc744 \ub9cc\ub0ac\uc744 \ub54c \uba3c\uc800 \uc5b4\ub5a4 \ub2ec\ub825\uacfc \uc5ed\uc0ac\uc801 \uae30\uc900\uc744 \uc0ac\uc6a9\ud558\ub294\uc9c0 \ubb3c\uc5b4\ubcfc \uc774\uc720\uac00 \uc0dd\uae34\ub2e4. \uc9c0\uad6c\uc758 \uacc4\uc808 \uc8fc\uae30\uc640 \ub2ec\ub825\uc758 \ud55c \ud574\ub97c \ub9de\ucd94\uae30 \uc704\ud574 \uc724\ub144\uc744 \ub450\uc9c0\ub9cc, \uc5b4\ub5a4 \uaddc\uce59\uc73c\ub85c \ub354\ud560\uc9c0\ub294 \ub2ec\ub825 \uccb4\uacc4\ub9c8\ub2e4 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uc728\ub9ac\uc6b0\uc2a4\ub825\uacfc \uadf8\ub808\uace0\ub9ac\ub825\uc758 \ucc28\uc774\ub294 \uadf8\ub7f0 \uc57d\uc18d\uc758 \ucc28\uc774\ub2e4. \ub9e4\ub144 \ud06c\uac8c \uc5b4\uae0b\ub098\ub294 \uac83\ucc98\ub7fc \ubcf4\uc774\uc9c0 \uc54a\uc544\ub3c4 \uae34 \uae30\uac04\uc5d0\ub294 \uc870\uc815\ud560 \ucc28\uc774\uac00 \uc0dd\uae38 \uc218 \uc788\ub2e4. \uc791\uc740 \uc218\uc758 \ucc28\uc774\uac00 \uc2dc\uac04\uc774 \uc313\uc774\uba74\uc11c \ub2e4\ub978 \ubaa8\uc2b5\uc73c\ub85c \ub4dc\ub7ec\ub09c\ub2e4. \ub2ec\ub825\uc744 \ubc14\uafc0 \ub54c\uc5d0\ub294 \uc55e\uc73c\ub85c\uc758 \uaddc\uce59\uc744 \uc815\ud558\ub294 \uac83\uacfc \uc774\ubbf8 \ub204\uc801\ub41c \ucc28\uc774\ub97c \ucc98\ub9ac\ud558\ub294 \uc77c\uc744 \ud568\uaed8 \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4. \uc624\ub298\ubd80\ud130 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \uacc4\uc0b0\ud558\uaca0\ub2e4\uace0 \ub9d0\ud558\ub294 \uac83\ub9cc\uc73c\ub85c \uacfc\uac70\uc758 \ucc28\uc774\uac00 \uc800\uc808\ub85c \uc0ac\ub77c\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4. 1752\ub144\uc758 \ube48 \ub0a0\uc9dc\ub4e4\uc740 \uadf8 \ub450 \ubc88\uc9f8 \ubb38\uc81c\ub97c \ub208\uc5d0 \ubcf4\uc774\uac8c \ubcf4\uc5ec \uc8fc\ub294 \uc0ac\ub840\ub2e4. \uc77c\uc815\ud45c \uc548\uc5d0 \ucc9c\ubb38\ud559\uacfc \uc81c\ub3c4\uc758 \uc120\ud0dd\uc774 \ud568\uaed8 \uc788\ub2e4. \uc9c0\uc5ed\ub9c8\ub2e4 \ub2ec\ub825\uc744 \ubc14\uafbc \ub54c\uac00 \ub2e4\ub974\uba74 \uc11c\ub85c \ub2e4\ub978 \uacf3\uc758 \uae30\ub85d\uc774 \uac19\uc740 \uae30\uc900\uc73c\ub85c \ub0a0\uc9dc\ub97c \uc801\uc5c8\ub2e4\uace0 \uac00\uc815\ud560 \uc218 \uc5c6\ub2e4. \uc624\ub798\ub41c \ud3b8\uc9c0\ub098 \uc0ac\uac74 \uae30\ub85d\uc744 \ube44\uad50\ud560 \ub54c \ub0a0\uc9dc\uc758 \uc22b\uc790\ub9cc \uc62e\uaca8 \uc4f0\uba74 \ud63c\ub3d9\uc774 \uc0dd\uae38 \uc218 \uc788\ub2e4. \uc5b4\ub290 \uc9c0\uc5ed\uc5d0\uc11c \uc5b4\ub290 \ub2ec\ub825\uc744 \uc37c\ub294\uc9c0\uac00 \ub0b4\uc6a9\uc758 \ubb38\ub9e5\ucc98\ub7fc \uc911\uc694\ud574\uc9c0\ub294 \uac83\uc774\ub2e4. \uc774 \uae00\uc5d0\uc11c \ubaa8\ub4e0 \ub098\ub77c\uc758 \uc804\ud658\ud45c\ub97c \uc678\uc6b0\ub824\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc601\uad6d\uc758 1752\ub144 \uc0ac\ub840\ub97c \ub2e4\ub978 \uacf3\uc5d0 \uadf8\ub300\ub85c \uc801\uc6a9\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \uccab\uac78\uc74c\uc774\ub2e4. \uac19\uc740 9\uc6d4\uc774\ub77c\ub294 \ub9d0\ub3c4 \uae30\ub85d\uc758 \uc81c\ub3c4 \uc548\uc5d0\uc11c \uc77d\uc5b4\uc57c \ud560 \ub54c\uac00 \uc788\ub2e4. \uc22b\uc790\ub97c \ubc88\uc5ed\ud558\ub294 \uc77c\uc5d0\ub294 \uc5b8\uc5b4\ubfd0 \uc544\ub2c8\ub77c \uadf8 \uc22b\uc790\ub97c \ubd99\uc774\ub358 \uaddc\uce59\uc758 \uc774\ud574\ub3c4 \ud544\uc694\ud558\ub2e4. \ud654\uba74\uc5d0 \ub2ec\uc744 \uadf8\ub9ac\ub294 \ud504\ub85c\uadf8\ub7a8\ub3c4 \uc5b4\ub5a4 \ub2ec\ub825 \uaddc\uce59\uc744 \uc0ac\uc6a9\ud560\uc9c0 \uc815\ud574\uc57c \ud55c\ub2e4. \uacfc\uac70\uc758 \ub2ec\uae4c\uc9c0 \ubcf4\uc5ec \uc904 \ub54c\uc5d0\ub294 \uc804\ud658\uc758 \ucc98\ub9ac \ubc29\uc2dd\uc774 \ud2b9\ud788 \ubb38\uc81c\uac00 \ub41c\ub2e4. \uacf5\uc2dd \uc124\uba85\uc11c\uac00 \uae30\ubcf8\uac12\uc758 \uc758\ubbf8\ub97c \uc54c\ub824 \uc8fc\ub294 \uc774\uc720\ub2e4. \ub0a0\uc9dc\ub97c \uc608\uc058\uac8c \ubc30\uc5f4\ud55c \ud45c\ucc98\ub7fc \ubcf4\uc774\ub294 \uacb0\uacfc \ub4a4\uc5d0 \uc5ed\uc0ac\uc801 \uac00\uc815\uc744 \uc120\ud0dd\ud55c \uc124\uacc4\uac00 \uc788\ub2e4. \ub530\ub77c\uc11c \ub2e4\ub978 \ub3c4\uad6c\uac00 \ub2e4\ub978 \ubc30\uc5f4\uc744 \ubcf4\uc5ec \uc900\ub2e4\uace0 \uace7\ubc14\ub85c \ud558\ub098\uac00 \uac70\uc9d3\uc774\ub77c\uace0 \ud310\ub2e8\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc124\uc815\uacfc \uae30\uc900\uc774 \uac19\uc740\uc9c0 \uba3c\uc800 \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \uc774 \uc774\uc57c\uae30\ub294 \uba85\uc808\uc774\ub098 \uc57d\uc18d \ub0a0\uc9dc\ub97c \ubcf5\uc7a1\ud558\uac8c \ub9cc\ub4e4\uc790\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \ub108\ubb34 \uc775\uc219\ud574\uc11c \uc790\uc5f0 \uadf8\ub300\ub85c\uc758 \uac83\ucc98\ub7fc \ub290\uaef4\uc9c0\ub294 \ub2ec\ub825\ub3c4 \uc0ac\ub78c\ub4e4\uc774 \uc2dc\uac04\uc5d0 \uc774\ub984\uc744 \ubd99\uc774\uace0 \ub9de\ucd94\uc5b4 \uc628 \uccb4\uacc4\ub77c\ub294 \uc810\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ud568\uaed8 \uc2e4\uc740 \ud45c\ub294 \uc804\ud658 \ub2f9\uc2dc\uc758 \ub0a0\uc9dc \ubc30\uc5f4\uc744 \uc774\ud574\ud558\ub3c4\ub85d \ub2e4\uc2dc \ub9cc\ub4e0 \uc124\uba85\ub3c4\ub2e4. \uc2e4\uc81c \uc61b \ub2ec\ub825\uc744 \ucd2c\uc601\ud55c \uc0ac\uc9c4\uc740 \uc544\ub2c8\ub2e4. 2\uc77c\uacfc 14\uc77c \uc0ac\uc774\uc5d0 \ube48 \uc774\ub984\ub4e4\uc774 \uc788\ub2e4\ub294 \uc810\uc744 \ub208\uc73c\ub85c \ud655\uc778\ud560 \uc218 \uc788\ub2e4. \ud758\ub7ec\uac04 \uc2dc\uac04 \uc790\uccb4\ub97c \uc5c6\uc568 \uc218\ub294 \uc5c6\ub2e4. \uc5ec\uae30\uc11c \ubc14\ub010 \uac83\uc740 \uadf8\ub2e4\uc74c \ub0a0\uc5d0 \ubd99\uc774\ub294 \ub0a0\uc9dc\uc600\ub2e4. \ub298 \ub2f9\uc5f0\ud558\uac8c \uc77d\ub294 \ub2ec\ub825\ub3c4 \uc0ac\ub78c\ub4e4\uc774 \uc815\ud55c \uaddc\uce59\uc774\ub77c\ub294 \uc0ac\uc2e4\uc744, \uc774 \uc774\uc0c1\ud55c 9\uc6d4\uc740 \uc9e7\uace0 \uc120\uba85\ud558\uac8c \uc54c\ub824 \uc900\ub2e4."}, {"id": "canada-dog-travois", "title": "\ubc14\ud034 \uc5c6\uc774 \uc9d0\uc744 \uc62e\uae30\ub358 \uae34 \ub450 \uac1c\uc758 \ub9c9\ub300", "summary": "1910\ub144 \ubb34\ub835\uc758 \uc0ac\uc9c4\uc5d0 \ub0a8\uc740 \ud2b8\ub798\ubcf4\uc774\uc758 \ubaa8\uc591\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history", "category_title": "History", "subcategory": "America", "url": "stories/canada-dog-travois/index.html", "image": "media/canada-dog-travois.jpg", "alt": "1910\ub144 \ubb34\ub835 \uce90\ub098\ub2e4 \ub0a8\ubd80 \uc568\ubc84\ud0c0\uc758 \uce74\uc774\ub098\uc774 \uc0ac\ub78c\ub4e4\uacfc \uac1c\uac00 \ub044\ub294 \ud2b8\ub798\ubcf4\uc774\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uc5ed\uc0ac \uc0ac\uc9c4.", "text": "\ubc14\ud034 \uc5c6\uc774 \uc9d0\uc744 \uc62e\uae30\ub358 \uae34 \ub450 \uac1c\uc758 \ub9c9\ub300 \uce90\ub098\ub2e4\uc758 \uc61b \uc0ac\uc9c4 \uc18d \uac1c\uc640 \uc6b4\ubc18 \ub3c4\uad6c 1910\ub144 \ubb34\ub835\uc758 \uc0ac\uc9c4\uc5d0 \ub0a8\uc740 \ud2b8\ub798\ubcf4\uc774\uc758 \ubaa8\uc591\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. America \uc5ed\uc0ac \uc0ac\uc9c4 \uc18d \uc0ac\ub78c\ub4e4 \uacc1\uc5d0 \uac1c\ub4e4\uc774 \uc11c \uc788\ub2e4. \ub208\uae38\uc744 \uc544\ub798\ub85c \uc62e\uae30\uba74 \uac1c\uc758 \ubab8\uc5d0\uc11c \ub4a4\ucabd\uc73c\ub85c \uae38\uac8c \uc774\uc5b4\uc9c0\ub294 \ub9c9\ub300\uac00 \ubcf4\uc778\ub2e4. \ubc14\ud034 \ub2ec\ub9b0 \uc218\ub808\ub3c4, \uaca8\uc6b8 \ub208 \uc704\uc758 \uc370\ub9e4\ub3c4 \uc544\ub2cc \ubaa8\uc591\uc774\ub2e4. OpenStax\ub294 \uc774\ub97c \uce74\uc774\ub098\uc774 \uc5ec\uc131\ub4e4\uacfc \uac1c\uac00 \ub044\ub294 \ud2b8\ub798\ubcf4\uc774\uc758 \ubaa8\uc2b5\uc73c\ub85c \uc18c\uac1c\ud55c\ub2e4. \uc0ac\uc9c4\uc740 \uc624\ub298\ub0a0 \uce90\ub098\ub2e4 \ub0a8\ubd80 \uc568\ubc84\ud0c0\uc5d0 \ud574\ub2f9\ud558\ub294 \uc9c0\uc5ed\uc5d0\uc11c 1910\ub144 \ubb34\ub835 \ucd2c\uc601\ub41c \uc790\ub8cc\ub2e4. \ud2b8\ub798\ubcf4\uc774\ub294 \ub450 \uac1c\uc758 \uae34 \ub9c9\ub300\ub97c \uc9d0\uc744 \uc5b9\ub294 \ubd80\ubd84\uacfc \uc5f0\uacb0\ud55c \uc6b4\ubc18 \ub3c4\uad6c\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c\ub3c4 \uae38\uac8c \ubed7\uc740 \uc120\ub4e4\uacfc \uadf8 \uc0ac\uc774\uc5d0 \ub193\uc778 \uc9d0\uc758 \uc790\ub9ac\ub97c \ucc3e\uc544\ubcfc \uc218 \uc788\ub2e4. \ubc14\ud034\uac00 \ubcf4\uc5ec\uc57c \uc6b4\ubc18 \ub3c4\uad6c\ub77c\uace0 \uc0dd\uac01\ud558\uba74 \ucc98\uc74c\uc5d0\ub294 \uae30\ub2a5\uc744 \ub193\uce60 \uc218 \uc788\ub2e4. \uc5b4\ub5a4 \uac83\uc744 \uc5b4\ub5bb\uac8c \uc5f0\uacb0\ud574 \ud568\uaed8 \uc6c0\uc9c1\uc774\uac8c \ud588\ub294\uc9c0\ub97c \ubcf4\uba74 \ubaa8\uc591\uc774 \ub2e4\uc2dc \uc77d\ud78c\ub2e4. \ubcf5\uc7a1\ud55c \uae30\uacc4 \ubd80\ud488\uc774 \uc788\uc5b4\uc57c\ub9cc \uc9d0\uc744 \uc62e\uae38 \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc774 \uc0ac\uc9c4\uc758 \uac1c\ub294 \uc0ac\ub78c \uacc1\uc5d0\uc11c \uc774\ub3d9\uacfc \uc6b4\ubc18\uc5d0 \ucc38\uc5ec\ud558\ub294 \ub3d9\ubb3c\uc774\ub2e4. \ubc18\ub824\ub3d9\ubb3c\uc758 \ucd08\uc0c1\uc73c\ub85c\ub9cc \ubcf4\uc558\uc744 \ub54c\uc640\ub294 \ub2e4\ub978 \uad00\uacc4\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \uad50\uc7ac\ub294 \uac1c\uac00 \uc0ac\ub78c\uc758 \uc5ec\ub7ec \ud65c\ub3d9\uc5d0\uc11c \ub9e1\uc740 \uc5ed\ud560 \uac00\uc6b4\ub370 \uc6b4\ubc18\ub3c4 \ud568\uaed8 \uc18c\uac1c\ud55c\ub2e4. \ub2e4\ub9cc \uc774 \ud55c \uc7a5\uc744 \ubcf4\uace0 \uac1c\uac00 \uc5bc\ub9c8\ub098 \ubb34\uac70\uc6b4 \uc9d0\uc744 \uc5b4\ub5a4 \uac70\ub9ac\uae4c\uc9c0 \uc62e\uacbc\ub294\uc9c0 \uacc4\uc0b0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc2e4\uc81c \ubcf4\uc774\ub294 \uc7a5\uce58\uc640 \uae30\ub85d\ub41c \uc4f0\uc784\uc744 \uad6c\ubd84\ud574 \uc77d\ub294 \ud3b8\uc774 \uc88b\ub2e4. \ub113\uc740 \uac08\ub3cc\ucc98\ub7fc \ubcf4\uc774\ub294 \uc7a5\uce58\uac00 \uc544\ub2c8\ub77c \uae38\uac8c \ubed7\uc740 \ub450 \uc120\uacfc \uadf8 \uc0ac\uc774\uc758 \uc801\uc7ac \uacf5\uac04\uc744 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc55e\ucabd\uc5d0\uc11c \ub04c\uace0 \ub4a4\ucabd\uc774 \ub545\uc744 \ub530\ub77c \uc6c0\uc9c1\uc774\uba74 \uc9d0\uc744 \ub098\ub974\ub294 \uae38\uc774 \uc0dd\uae34\ub2e4. \ubc14\ud034\uc640 \ucd95\uc774 \uc5c6\ub294 \ud615\ud0dc\ub77c\ub3c4 \uc5f0\uacb0\ub41c \ub9c9\ub300\uc640 \uc9d0\uc758 \uc790\ub9ac\ub97c \ud1b5\ud574 \uc5ed\ud560\uc744 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uc6b4\ubc18 \ub3c4\uad6c\ub97c \uc54c\uc544\ubcf4\ub294 \uae30\uc900\uc744 \uc870\uae08 \ub113\ud600 \uc8fc\ub294 \ubb3c\uac74\uc774\ub2e4. \ub2e4\ub9cc \uc0ac\uc9c4\ub9cc\uc73c\ub85c \uc5b4\ub5a4 \uc7ac\ub8cc\uac00 \uc5bc\ub9c8\ub098 \uac15\ud558\uace0 \uc5b4\ub290 \uc9c0\ud615\uc5d0 \uac00\uc7a5 \uc801\ud569\ud588\ub294\uc9c0 \uc218\uce58\ub85c \ud3c9\uac00\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc7a5\uce58\ub97c \uc774\ub8e8\ub294 \ud615\ud0dc\uc640 \uc790\ub8cc\uac00 \uc54c\ub824 \uc8fc\ub294 \uc4f0\uc784\uc744 \uba3c\uc800 \ubcf4\ub294 \uac83\uc774\ub2e4. \uc775\uc219\ud55c \uc218\ub808\uac00 \uc5c6\ub2e4\ub294 \uc774\uc720\ub85c \ubd80\uc871\ud55c \ub3c4\uad6c\ub77c\uace0 \uc815\ud558\uae30\ubcf4\ub2e4 \uc5b4\ub5a4 \ud589\ub3d9\uc744 \uac00\ub2a5\ud558\uac8c \ud588\ub294\uc9c0 \ubb3b\ub294 \ud3b8\uc774 \uc774\ud574\uc5d0 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \uc0ac\uc9c4 \uc18d \uac1c\ub294 \ub2e8\uc21c\ud788 \uc0ac\ub78c \uacc1\uc5d0 \uc788\ub294 \ub3d9\ubb3c\uc774 \uc544\ub2c8\ub77c \uc6b4\ubc18 \ub3c4\uad6c\uc640 \uad00\uacc4\ub97c \ub9fa\uace0 \uc788\ub2e4. \uad50\uc7ac\ub294 \uc774 \uc7a5\uba74\uc744 \uc0ac\ub78c\uacfc \uac1c\uac00 \ub098\ub204\uc5b4 \uc628 \ud65c\ub3d9\uc758 \uc0ac\ub840\ub85c \uc18c\uac1c\ud55c\ub2e4. \ub3d9\ubb3c\uc758 \uc5ed\ud560\uc744 \uc624\ub298\uc758 \ubc18\ub824 \uacbd\ud5d8 \ud558\ub098\ub85c\ub9cc \uc0dd\uac01\ud558\uba74 \ub193\uce60 \uad00\uacc4\ub2e4. \ud568\uaed8 \uc0b0\ub2e4\ub294 \ub9d0\uc5d0\ub294 \uc2dc\ub300\uc640 \uc7a5\uc18c\uc5d0 \ub530\ub77c \ub2e4\ub978 \uc77c\uc774 \ub4e4\uc5b4 \uc788\uc5c8\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc774 \uc0ac\uc9c4\uc744 \uac1c\uc640 \uc0ac\ub78c\uc758 \ubaa8\ub4e0 \uad00\uacc4\ub97c \ub300\ud45c\ud558\ub294 \uc7a5\uba74\uc73c\ub85c \ub113\ud790 \uc218\ub294 \uc5c6\ub2e4. \uc5bc\ub9c8\ub098 \uc790\uc8fc \uc5b4\ub5a4 \ubb34\uac8c\ub97c \ub098\ub974\uace0 \uc5b4\ub5bb\uac8c \uae38\ub800\ub294\uc9c0\ub294 \ubcc4\ub3c4 \uc815\ubcf4\uac00 \ud544\uc694\ud558\ub2e4. \ud558\ub098\uc758 \uc7a5\uce58\ub97c \ubcf8 \ub4a4 \uc5ec\ub7ec \uc9d1\ub2e8\uc758 \uc0dd\ud65c\uc744 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ubb36\uc5b4\uc11c\ub294 \uc548 \ub41c\ub2e4. \uad6c\uccb4\uc801\uc778 \uc0ac\ub78c\uacfc \uc7a5\uc18c\ub97c \uc790\ub8cc\uc758 \uc124\uba85\ub300\ub85c \ub0a8\uaca8 \ub450\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4. \uad50\uc7ac\ub294 \uc0ac\uc9c4\uc758 \uc778\ubb3c\uc744 \uce74\uc774\ub098\uc774 \uc5ec\uc131\uc73c\ub85c, \uc7a5\uc18c\ub97c \ud604\uc7ac \uce90\ub098\ub2e4 \ub0a8\ubd80 \uc568\ubc84\ud0c0\uc5d0 \ud574\ub2f9\ud558\ub294 \uc9c0\uc5ed\uc73c\ub85c \uc18c\uac1c\ud558\uba70 \ucd2c\uc601 \uc2dc\uae30\ub97c 1910\ub144 \ubb34\ub835\uc73c\ub85c \uc801\ub294\ub2e4. \uc774 \ub2e8\uc11c\ub4e4\uc740 \uc0ac\uc9c4\uc744 \uc774\ub984 \uc5c6\ub294 \uc61b \ubd81\ubbf8\uc758 \uc7a5\uba74\uc73c\ub85c \ub9cc\ub4e4\uc9c0 \uc54a\uac8c \ud55c\ub2e4. \uc0ac\ub78c\uacfc \ub3c4\uad6c\uc5d0\ub294 \uad6c\uccb4\uc801\uc778 \uacf5\ub3d9\uccb4\uc640 \uc2dc\uac04\uc758 \ub9e5\ub77d\uc774 \uc788\uc5c8\ub2e4. \ud604\uc7ac\uc758 \uad6d\uac00 \uc774\ub984\uc740 \uc704\uce58\ub97c \ucc3e\uac8c \ub3c4\uc640\uc8fc\uc9c0\ub9cc \ub2f9\uc2dc \uc0ac\ub78c\ub4e4\uc758 \ubaa8\ub4e0 \uc815\uccb4\uc131\uc744 \uc124\uba85\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc9c0\ub3c4 \uc704\uc758 \uba85\uce6d\uacfc \uacf5\ub3d9\uccb4\uc758 \uc774\ub984\uc744 \ud568\uaed8 \uc77d\uc73c\uba74 \uc870\uae08 \ub354 \uc815\ud655\ud574\uc9c4\ub2e4. \uc624\ub798\ub41c \uc0ac\uc9c4\uc740 \uc2dc\ub300\uc758 \ubcf5\uc7a5\ub9cc \uad6c\uacbd\ud558\ub294 \uc774\ubbf8\uc9c0\uac00 \uc544\ub2c8\ub77c \ub204\uac00 \uc5b4\ub5a4 \ud658\uacbd\uc5d0\uc11c \ubb34\uc5c7\uc744 \ud588\ub294\uc9c0 \ubb3b\ub294 \uae30\ub85d\uc73c\ub85c \ub9cc\ub0a0 \uc218 \uc788\ub2e4. \uba3c\uc800 \ub9c9\ub300\uc758 \ub05d\uacfc \uc9d0\uc744 \ub193\ub294 \ubd80\ubd84\uc744 \uc0b4\ud53c\uace0, \ub2e4\uc74c\uc5d0 \uadf8 \uc7a5\uce58\uc640 \uac1c\uc758 \ubab8\uc774 \uc5b4\ub5bb\uac8c \uc5f0\uacb0\ub418\ub294\uc9c0 \ub208\uc73c\ub85c \ub530\ub77c\uac00 \ubcf4\uc790. \ubb3c\uac74\uc758 \uc804\uccb4 \uae30\ub2a5\uc744 \ud55c\ub208\uc5d0 \uc54c\uae30 \uc5b4\ub824\uc6b8 \ub54c\uc5d0\ub294 \uc811\uc810\uc744 \ucc3e\ub294 \uac83\uc774 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \uc0ac\ub78c\uc774 \uc11c \uc788\ub294 \uc790\ub9ac\uc640 \ub3c4\uad6c\uc758 \ubc29\ud5a5\uc744 \ud568\uaed8 \ubcf4\uba74 \uc774\ub3d9\uc758 \uac00\ub2a5\uc131\uc774 \uc870\uae08 \uad6c\uccb4\uc801\uc73c\ub85c \ub290\uaef4\uc9c4\ub2e4. \uc0ac\uc9c4\uc774 \uc815\uc9c0\ud55c \uc0c1\ud0dc\ub97c \ubcf4\uc5ec \uc900\ub2e4\uace0 \ud574\uc11c \uadf8 \ubb3c\uac74\ub3c4 \uc6d0\ub798 \uac00\ub9cc\ud788 \ub193\uc5ec \uc788\ub358 \uac83\ub9cc\uc740 \uc544\ub2c8\ub2e4. \uc6b4\ubc18\uc774\ub77c\ub294 \ud589\ub3d9\uc744 \uc704\ud574 \ub9cc\ub4e4\uc5c8\uc73c\ub098 \ud654\uba74\uc5d0\ub294 \ud55c\uc21c\uac04\ub9cc \ub0a8\uc558\ub2e4. \uadf8 \uc55e\ub4a4\ub97c \uc0c1\uc0c1\ud558\ub418 \uae30\ub85d\ub418\uc9c0 \uc54a\uc740 \uac70\ub9ac\uc640 \ub178\ub3d9\ub7c9\uc744 \uc0ac\uc2e4\ucc98\ub7fc \uc4f0\uc9c0\ub294 \uc54a\ub294\ub2e4. \ubc14\ud034 \uc5c6\uc774 \uc6c0\uc9c1\uc774\ub294 \uae34 \ub450 \ub9c9\ub300\ub294 \uc775\uc219\ud558\uc9c0 \uc54a\uc740 \uae30\uc220\uc744 \ub0ae\ucd94\uc5b4 \ubcf4\uc9c0 \uc54a\uace0 \uc77d\ub294 \uc5f0\uc2b5\uc774 \ub41c\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc0ac\uc9c4\uc740 \ud2b9\uc815 \uc2dc\uae30\uc758 \uc790\ub8cc\ub2e4. \uc624\ub298\ub0a0 \uce74\uc774\ub098\uc774 \uacf5\ub3d9\uccb4\uc758 \uc0dd\ud65c \uc804\uccb4\ub97c \uc774 \ubaa8\uc2b5 \ud558\ub098\ub85c \ub300\uc2e0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc624\ub798\ub41c \uc0ac\uc9c4\uc744 \ubcfc \ub54c\ub294 \uadf8\ub54c\uc758 \uc7a5\uba74\uc774\ub77c\ub294 \uc790\ub9ac\ub97c \ud568\uaed8 \ub0a8\uaca8 \ub450\uc5b4\uc57c \ud55c\ub2e4. \uadf8 \uc548\uc5d0\uc11c\ub3c4 \uc791\uc740 \ubc1c\uacac\uc740 \uac00\ub2a5\ud558\ub2e4. \ub298 \ubcf4\ub358 \ubc14\ud034\uac00 \uc5c6\ub294\ub370\ub3c4 \uc9d0\uc744 \ub193\uc744 \uc790\ub9ac\uc640 \ub04c\uace0 \uac08 \ubc29\ubc95\uc774 \uc788\ub2e4. \uae34 \ub450 \uac1c\uc758 \ub9c9\ub300\ub97c \uc54c\uc544\ubcf4\ub294 \uc21c\uac04 \uc0ac\uc9c4 \uc18d \uc120\ub4e4\uc774 \ub2e8\uc21c\ud55c \ubc30\uacbd\uc5d0\uc11c \uc0dd\ud65c\uc758 \ub3c4\uad6c\ub85c \ubc14\ub010\ub2e4."}, {"id": "clock-little-door-case", "title": "\uc2dc\uacc4\uc5d0\ub3c4 \uc791\uc740 \ubb38\uc774 \ub2ec\ub9b0 \uc9d1\uc774 \uc788\uc5c8\ub2e4", "summary": "\ubd89\uc740 \ubca8\ubcb3\uacfc \uac08\uc0c9 \uac00\uc8fd\uc73c\ub85c \uac10\uc2fc \uc61b \uc2dc\uacc4 \ud55c \uc870\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history", "category_title": "History", "subcategory": "Korea", "url": "stories/clock-little-door-case/index.html", "image": "media/clock-little-door-case.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc2dc\uacc4 \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc2dc\uacc4\uc5d0\ub3c4 \uc791\uc740 \ubb38\uc774 \ub2ec\ub9b0 \uc9d1\uc774 \uc788\uc5c8\ub2e4 \ubb38\uc744 \uc5f4\uba74 \uc2dc\uac04\uc774 \ubcf4\uc774\ub294 \ubcf4\uad00\ud568 \ubd89\uc740 \ubca8\ubcb3\uacfc \uac08\uc0c9 \uac00\uc8fd\uc73c\ub85c \uac10\uc2fc \uc61b \uc2dc\uacc4 \ud55c \uc870\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Korea \uc5ed\uc0ac \uc0ac\uc9c4 \uc18d \uc791\uc740 \ubb38\uc774 \uc591\ucabd\uc73c\ub85c \uc5f4\ub824 \uc788\ub2e4. \uadf8 \uc548\uc5d0\ub294 \uc2dc\uacc4\uac00 \uc549\uc544 \uc788\ub2e4. \uc2dc\uacc4\ub97c \ub123\ub294 \uc0c1\uc790\uac00 \uc544\ub2c8\ub77c \uc2dc\uacc4\ub9cc\uc744 \uc704\ud574 \uc9c0\uc740 \uc791\uc740 \uc9d1\ucc98\ub7fc \ubcf4\uc778\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \uc18c\uc7a5\ud488 \uc774\ub984\uc740 \uac04\ub2e8\ud788 \uc2dc\uacc4\ub2e4. \uc2dc\uacc4\uc640 \ubcf4\uad00 \ucf00\uc774\uc2a4\uac00 \ud55c \uc870\ub97c \uc774\ub8ec\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc804\uc2dc\uc7a5\uc5d0\uc11c \uc2dc\uacc4\uc758 \ubc14\ub298\ub9cc \ud655\uc778\ud558\uace0 \uc9c0\ub098\uac14\ub2e4\uba74, \uc774\ubc88\uc5d0\ub294 \ubc14\uae65\uc758 \uc9d1\uae4c\uc9c0 \ucc9c\ucc9c\ud788 \ubcf4\uc790. \uc2dc\uacc4 \uc55e\uba74\uc758 \uc22b\uc790\ub294 \uc6b0\ub9ac\uc5d0\uac8c \uc775\uc219\ud55c \uc544\ub77c\ube44\uc544 \uc22b\uc790\ub2e4. \uadf8\uc911 12\ub9cc \ubd89\uace0 \ub098\uba38\uc9c0\ub294 \uac80\ub2e4\uace0 \ubc15\ubb3c\uad00\uc740 \uc124\uba85\ud55c\ub2e4. \ub611\uac19\uc740 \uc22b\uc790\ud310 \uc548\uc5d0\uc11c \uc704\ucabd \ud55c \uc790\ub9ac\uc5d0\ub9cc \uc0c9\uc744 \ub2ec\ub9ac \uc900 \uac83\uc774\ub2e4. \uc65c \uadf8 \uc22b\uc790\ub9cc \ubd89\uac8c \ud588\ub294\uc9c0\ub294 \uc774 \uc790\ub8cc\uc5d0 \uc801\ud600 \uc788\uc9c0 \uc54a\ub2e4. \ud2b9\ubcc4\ud55c \uc758\ubbf8\ub97c \ubd99\uc774\uae30\ubcf4\ub2e4 \uba3c\uc800 \uc2e4\uc81c \ucc28\uc774\ub97c \ub208\uc73c\ub85c \ucc3e\uc544\ubcf4\uba74 \uc88b\ub2e4. \uc124\uba85\uc744 \uc77d\uae30 \uc804\uc5d0\ub294 \uc9c0\ub098\ucce4\uc744 \uc791\uc740 \uc120\ud0dd\uc774 \uc2dc\uacc4\uc758 \uc5bc\uad74\uc744 \ubc14\uafbc\ub2e4. \ubcf4\uad00 \ucf00\uc774\uc2a4\uc758 \ubc14\uae65\uc5d0\ub294 \uac08\uc0c9 \uac00\uc8fd\uc774 \uc50c\uc6cc\uc838 \uc788\uace0 \uc548\uc5d0\ub294 \ubd89\uc740 \ubca8\ubcb3\uc774 \uc788\ub2e4. \uc2dc\uacc4\uac00 \ub4e4\uc5b4\uac00\ub294 \uacf5\uac04\ub3c4 \ud06c\uae30\uc5d0 \uaf2d \ub9de\ub3c4\ub85d \ub9cc\ub4e4\uc5b4\uc84c\ub2e4\uace0 \ud55c\ub2e4. \ubb38\uc740 \uc88c\uc6b0\ub85c \ud65c\uc9dd \uc5f4 \uc218 \uc788\ub294 \uad6c\uc870\ub2e4. \ubcf4\uad00\ud560 \ub54c\uc640 \ub4e4\uc5ec\ub2e4\ubcfc \ub54c\uc758 \ubaa8\uc591\uc774 \ub2e4\ub978 \ubb3c\uac74\uc774\ub2e4. \uc624\ub298\uc758 \uc774\uc5b4\ud3f0 \ucf00\uc774\uc2a4\ub97c \ub5a0\uc62c\ub824 \ubcfc \uc218\ub3c4 \uc788\uc9c0\ub9cc, \uc774\uac83\uc774 \uc5ec\ud589\uc6a9\uc774\uc5c8\ub2e4\uac70\ub098 \ucda9\uaca9\uc744 \ub9c9\uae30 \uc704\ud574 \ub9cc\ub4e4\uc5b4\uc84c\ub2e4\uace0\uae4c\uc9c0 \ub2e8\uc815\ud560 \uadfc\uac70\ub294 \uc5c6\ub2e4. \ub9de\ucda4 \uacf5\uac04\uacfc \uc5ec\ub2eb\uc774\ubb38 \uc790\uccb4\uac00 \ubcf4\uc5ec \uc8fc\ub294 \uc7ac\ubbf8\ub97c \uc990\uae30\uba74 \ucda9\ubd84\ud558\ub2e4. \uc2dc\uacc4\ub294 \uc2dc\uac04\uc744 \ubcf4\uc5ec \uc8fc\uace0 \ucf00\uc774\uc2a4\ub294 \uadf8 \uc2dc\uacc4\ub97c \ub123\uc744 \uc790\ub9ac\ub97c \ub9cc\ub4e0\ub2e4. \ud55c \uc870\ub85c \ub0a8\uc544 \uc788\ub2e4\ub294 \uc124\uba85\uc744 \uc77d\uc73c\uba74 \ub450 \ubb3c\uac74\uc744 \ub530\ub85c \ubcf4\uc558\uc744 \ub54c\uc640 \ub2e4\ub978 \uad00\uacc4\uac00 \ub4dc\ub7ec\ub09c\ub2e4. \ub3c4\uad6c\uac00 \uc791\ub3d9\ud558\ub294 \uba74\ubfd0 \uc544\ub2c8\ub77c \ubcf4\uad00\ud558\uace0 \uaebc\ub0b4 \ubcf4\ub294 \ubc29\uc2dd\ub3c4 \uc0dd\ud65c\uc758 \uc77c\ubd80\uc600\ub2e4\ub294 \uc810\uc774\ub2e4. \uc2dc\uacc4\uc758 \ubab8\uccb4\ub9cc\uc73c\ub85c \uc804\uccb4 \uc0ac\uc6a9 \uacbd\ud5d8\uc744 \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc774 \ucf00\uc774\uc2a4\ub97c \uc624\ub298\uc758 \uc5ec\ud589\uc6a9 \ubcf4\ud638\ud568\uacfc \uac19\uc740 \ubaa9\uc801\uc774\ub77c\uace0 \ubc14\ub85c \uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc2e4\uc81c\ub85c \uc5b4\ub5a4 \uc774\ub3d9\uc744 \ud588\ub294\uc9c0\uc640 \ub204\uad6c\uc758 \ubc29\uc5d0 \ub193\uc600\ub294\uc9c0\ub294 \ub0a8\uc740 \uc790\ub8cc\uac00 \ud544\uc694\ud55c \ubb38\uc81c\ub2e4. \uc9c0\uae08 \ud655\uc778\ub418\ub294 \ub9de\ucda4 \uacf5\uac04\uacfc \uc5ec\ub2eb\uc774\ubb38\uc744 \uba3c\uc800 \ubcf4\uc790. \ud2b9\uc815\ud55c \ubb3c\uac74\uc744 \uc704\ud574 \ub9c8\ub828\ud55c \ud615\ud0dc\ub77c\ub294 \uc810\ub9cc\uc73c\ub85c\ub3c4 \uc2dc\uacc4\ub97c \ub300\ud558\ub358 \uc190\uc758 \ud589\ub3d9\uc744 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \uac08\uc0c9 \uac00\uc8fd\uc740 \ucf00\uc774\uc2a4\uc758 \uc678\ud615\uc744 \uc774\ub8e8\uace0 \ubd89\uc740 \ubca8\ubcb3\uc740 \uc548\ucabd\uc758 \ub2e4\ub978 \ud45c\uc815\uc744 \ub9cc\ub4e0\ub2e4. \uac19\uc740 \ubb3c\uac74\uc744 \ub2eb\uc544 \ub193\uc558\uc744 \ub54c\uc640 \uc5f4\uc5c8\uc744 \ub54c\uc758 \uc2dc\uac01\uc801 \uacbd\ud5d8\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc740 \uc7ac\ub8cc\ub97c \uad6c\ubd84\ud574 \uc54c\ub824 \uc8fc\ubbc0\ub85c \ub2e8\uc21c\ud788 \uac08\uc0c9 \uc0c1\uc790\ub77c\ub294 \uc778\uc0c1\uc5d0\uc11c \ud55c \uac78\uc74c \ub354 \ub4e4\uc5b4\uac08 \uc218 \uc788\ub2e4. \uc678\ubd80\uc640 \ub0b4\ubd80\uac00 \uc11c\ub85c \ub2e4\ub978 \uc5ed\ud560\uacfc \uac10\uc0c1\uc744 \ub9cc\ub4e0\ub2e4. \ub2e4\ub9cc \ud604\uc7ac \ubcf4\uc774\ub294 \uc0c9\uc744 \ucc98\uc74c \uc81c\uc791 \uc21c\uac04\uc758 \uc0c9\uacfc \uc644\uc804\ud788 \uac19\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ubcf4\uc874 \uc0c1\ud0dc\uc640 \uc0ac\uc9c4\uc758 \uc870\uac74\uc774 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uc7ac\ub8cc\uc758 \uc885\ub958\ub294 \ud574\uc124\uc744 \ud1b5\ud574 \ud655\uc778\ud558\uace0 \ud654\uba74\uc5d0\uc11c\ub294 \ubc30\uce58\uc640 \uad00\uacc4\ub97c \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \ucf00\uc774\uc2a4\ub3c4 \uc2dc\uacc4\ub97c \ub2f4\uc740 \ubc30\uacbd\uc5d0 \uadf8\uce58\uc9c0 \uc54a\uace0 \ub530\ub85c \uad00\ucc30\ud560 \uba74\uacfc \ubb38\uc744 \uac00\uc9c4 \ubb3c\uac74\uc774\uc5c8\ub2e4. 12\ub9cc \ubd89\uace0 \ub2e4\ub978 \uc22b\uc790\ub294 \uac80\ub2e4\ub294 \uc815\ubcf4\ub294 \uc0ac\uc9c4\uc744 \ub2e4\uc2dc \ubcf4\uac8c \ud55c\ub2e4. \uc804\ubd80 \uac19\uc740 \uc22b\uc790\ub77c\uace0 \uc0dd\uac01\ud558\uace0 \uc9c0\ub098\ucce4\ub2e4\uba74 \ud55c \uc790\ub9ac\uc758 \ucc28\uc774\uac00 \uc0c8\ub86d\uac8c \ub4dc\ub7ec\ub09c\ub2e4. \uac19\uc740 \ud45c\uba74\uc5d0\uc11c \uc0c9\uc744 \ub2ec\ub9ac \uc900 \uc120\ud0dd\uc740 \uc5b4\ub5a4 \uc9c0\uc810\uc744 \uad6c\ubd84\ud558\ub294 \ud6a8\uacfc\ub97c \ub0bc \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \ud6a8\uacfc\uc640 \uc81c\uc791\uc790\uc758 \ud655\uc778\ub41c \ubaa9\uc801\uc740 \uac19\uc740 \uac83\uc774 \uc544\ub2c8\ub2e4. \ud2b9\ubcc4\ud55c \uae30\ub150\uc77c\uc774\ub098 \uc18c\uc720\uc790\uc758 \ucde8\ud5a5\uc744 \uadfc\uac70 \uc5c6\uc774 \ubd99\uc774\ub294 \ub300\uc2e0 \uc2e4\uc81c\ub85c \uc5b4\ub290 \ubd80\ubd84\uc774 \ub2e4\ub974\uac8c \ucc98\ub9ac\ub418\uc5c8\ub294\uc9c0 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uc791\uc740 \ucc28\uc774\ub97c \uc544\ub294 \uac83\ub9cc\uc73c\ub85c \ubb3c\uac74\uc758 \uc5bc\uad74\uc774 \ub35c \uc775\uba85\uc801\uc73c\ub85c \ub290\uaef4\uc9c4\ub2e4. \uc2dc\uac01\uc744 \uc77d\ub294 \uc22b\uc790\ud310\uc5d0\uc11c \uc2dc\uacc4\ub97c \uad6c\uacbd\ud558\ub294 \uc0ac\ub78c\uc758 \uc2dc\uc120\ub3c4 \ud568\uaed8 \uc6c0\uc9c1\uc778\ub2e4. \uc4f0\ub294 \uc77c\uacfc \uac10\uc0c1\ud558\ub294 \uc77c\uc774 \uacb9\uce58\ub294 \uc790\ub9ac\ub2e4. \uc790\ub8cc\ub294 \uc7a0\uae08\uc7a5\uce58\uac00 \ub0a8\uc544 \uc788\uc9c0 \uc54a\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc5f0\ub300\uac00 \ubd84\uba85\ud558\uc9c0 \uc54a\ub2e4\ub294 \uc810\uc744 \uc54c\ub824 \uc900\ub2e4. \ubb3c\uac74\uc774 \uc798 \ubcf4\uc778\ub2e4\uace0 \uadf8 \uc774\ub825\uae4c\uc9c0 \ubaa8\ub450 \ud655\uc2e4\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \ub0a8\uc740 \ucf00\uc774\uc2a4\uc758 \ud615\ud0dc\uc640 \ube60\uc9c4 \uc7a5\uce58, \ud655\uc778\ub418\uc9c0 \uc54a\uc740 \uc81c\uc791 \uc2dc\uae30\ub97c \ud568\uaed8 \uc77d\uc5b4\uc57c \ud55c\ub2e4. \uadf8 \ube48\uce78\uc744 \ud2b9\uc815\ud55c \uc655\uc2e4 \uc778\ubb3c\uc758 \uc18c\uc9c0\ud488\uc774\ub77c\ub294 \uc774\uc57c\uae30\ub85c \ucc44\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc791\uc740 \ubb38\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc2dc\uacc4\ub97c \ub450\ub294 \uacf5\uac04\uacfc \ub2e4\uc2dc \ub4e4\uc5ec\ub2e4\ubcf4\ub294 \ud589\ub3d9\uc744 \uc0dd\uac01\ud574 \ubcf4\uc790. \ubb3c\uac74\uc744 \ubcf4\uc874\ud55c \uc0ac\ub78c\ub4e4\uc740 \uae30\ub2a5\ubfd0 \uc544\ub2c8\ub77c \ud568\uaed8 \uc4f0\uc778 \ubd80\uc18d\ubb3c\ub3c4 \ub0a8\uacbc\ub2e4. \ub355\ubd84\uc5d0 \uc6b0\ub9ac\ub294 \uc22b\uc790\ud310 \ud558\ub098\ub97c \ub118\uc5b4 \uc2dc\uac04\uc744 \ub9cc\ub098\ub294 \ubc29\uc2dd\uc758 \uc77c\ubd80\ub97c \uad6c\uacbd\ud560 \uc218 \uc788\ub2e4. \uc2dc\uacc4\uc758 \uc791\uc740 \uc9d1\uc774\ub77c\ub294 \ube44\uc720\uac00 \uad6c\uccb4\uc801\uc778 \ud615\ud0dc\ub97c \uc5bb\ub294 \uc21c\uac04\uc774\ub2e4. \ucf00\uc774\uc2a4 \ubb38\uc758 \uac00\uc6b4\ub370\uc5d0\ub294 \uc6d0\ub798 \ubd99\uc5c8\ub358 \uc7a0\uae08\uc7a5\uce58\uac00 \uc5c6\uc5b4\uc84c\uace0, \uace0\uc815\ud558\ub358 \uc791\uc740 \uae08\uc18d\ud310\ub9cc \ub0a8\uc558\ub2e4\uace0 \ud55c\ub2e4. \uc624\ub798\ub41c \ubb3c\uac74\uc740 \uac16\ucd94\uc5b4\uc9c4 \ubd80\ubd84\ubfd0 \uc544\ub2c8\ub77c \ube60\uc9c4 \ubd80\ubd84\uc73c\ub85c\ub3c4 \uc790\uae30 \uc0c1\ud0dc\ub97c \uc54c\ub824 \uc900\ub2e4. \uc81c\uc791 \uc5f0\ub300\ub294 \ubc15\ubb3c\uad00 \uc815\ubcf4\uc5d0\uc11c\ub3c4 \ubbf8\uc0c1\uc774\ub2e4. \ub204\uad6c\uc758 \ucc45\uc0c1\uc5d0 \uc5b8\uc81c \ub193\uc600\ub294\uc9c0 \uc0c1\uc0c1\uc73c\ub85c \ucc44\uc6b0\uae30\ubcf4\ub2e4 \uc9c0\uae08 \ud655\uc778\ud560 \uc218 \uc788\ub294 \ubb38\uacfc \uc22b\uc790, \uac00\uc8fd\uacfc \ubca8\ubcb3\uc744 \ubcf4\uc790. \uc2dc\uac04\uc744 \uc54c\ub824 \uc8fc\ub358 \ubb3c\uac74\uc5d0 \ubcf4\uad00\ud558\ub294 \uc2dc\uac04\uae4c\uc9c0 \ud568\uaed8 \ub4e4\uc5b4 \uc788\ub2e4\ub294 \ub290\ub08c\uc774 \ub4e0\ub2e4."}, {"id": "horn-bow-missing-string", "title": "\uc2dc\uc704 \uc5c6\ub294 \uc61b \ud65c\uc5d0\uc11c\ub294 \ubb34\uc5c7\uc744 \ubcfc \uc218 \uc788\uc744\uae4c", "summary": "\ud65c\uc2dc\uc704\uac00 \uc0ac\ub77c\uc838\ub3c4 \ub0a8\uc544 \uc788\ub294 \ub2e8\uc11c\ub294 \uc788\uc2b5\ub2c8\ub2e4. \uc791\uc740 \ud648\uacfc \uc190\uc7a1\uc774\ub97c \ub530\ub77c \uc61b \ubb3c\uac74\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history", "category_title": "History", "subcategory": "Korea", "url": "stories/horn-bow-missing-string/index.html", "image": "media/horn-bow-missing-string.jpg", "alt": "\ud65c\uc2dc\uc704 \uc5c6\uc774 \uad7d\uc740 \ubab8\uccb4\uc640 \uac00\uc6b4\ub370 \ubd89\uc740 \uc190\uc7a1\uc774\uac00 \ub0a8\uc544 \uc788\ub294 \uac01\uad81 \uc0ac\uc9c4", "text": "\uc2dc\uc704 \uc5c6\ub294 \uc61b \ud65c\uc5d0\uc11c\ub294 \ubb34\uc5c7\uc744 \ubcfc \uc218 \uc788\uc744\uae4c \uac01\uad81\uc758 \uad7d\uc740 \ubab8\uccb4\uc5d0 \ub0a8\uc544 \uc788\ub294 \uc7ac\ub8cc\uc640 \ud648 \ud65c\uc2dc\uc704\uac00 \uc0ac\ub77c\uc838\ub3c4 \ub0a8\uc544 \uc788\ub294 \ub2e8\uc11c\ub294 \uc788\uc2b5\ub2c8\ub2e4. \uc791\uc740 \ud648\uacfc \uc190\uc7a1\uc774\ub97c \ub530\ub77c \uc61b \ubb3c\uac74\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Korea \uc5ed\uc0ac \ud65c\uc744 \ub5a0\uc62c\ub9ac\uba74 \ud33d\ud33d\ud55c \uc904\uacfc \ud654\uc0b4\uc744 \ub2f9\uae30\ub294 \ubaa8\uc2b5\ubd80\ud130 \uc0dd\uac01\ub09c\ub2e4. \uadf8\ub7f0\ub370 \ubc15\ubb3c\uad00\uc5d0 \ub193\uc778 \ud65c\uc5d0 \uc904\uc774 \uc5c6\ub2e4\uba74 \uc5b4\ub514\ub97c \ubcf4\uc544\uc57c \ud560\uae4c. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \uac01\uad81 \ud55c \uc810\uc740 \ud65c\uc2dc\uc704 \uc5c6\uc774 \ub0a8\uc544 \uc788\ub2e4. \uc0ac\uc9c4 \uc18d\uc5d0\uc11c\ub294 \uad7d\uc740 \ubab8\uccb4\uac00 \uba3c\uc800 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uc124\uba85\uc744 \uc77d\uc73c\uba74 \uadf8 \uace1\uc120\uc744 \ub530\ub77c \uc791\uc740 \ub2e8\uc11c\ub4e4\uc774 \ud558\ub098\uc529 \ubcf4\uc774\uae30 \uc2dc\uc791\ud55c\ub2e4. \uac01\uad81\uc758 \u2018\uac01\u2019\uc740 \ubfd4\uc744 \ub73b\ud55c\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc6b0\ub9ac\ub098\ub77c\uc758 \ub300\ud45c\uc801\uc778 \uc2e4\uc804\uc6a9 \ud65c\uc774\ub77c\uace0 \uc18c\uac1c\ud558\uba70, \ud0c4\uc131\uc744 \ub192\uc774\uae30 \uc704\ud574 \ubb3c\uc18c\uc758 \ubfd4\uc744 \uc8fc\uc7ac\ub8cc\ub85c \uc0ac\uc6a9\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uba40\ub9ac\uc11c\ub294 \uac00\ub298\uace0 \uad7d\uc740 \ubb3c\uac74 \ud558\ub098\uc9c0\ub9cc, \uadf8 \uc548\uc5d0\ub294 \uc7ac\ub8cc\ub97c \uace0\ub978 \uc774\uc720\uac00 \uc788\ub2e4. \uadf8\uc800 \ub2e8\ub2e8\ud558\uae30\ub9cc \ud55c \ubb3c\uac74\uc744 \ub9cc\ub4dc\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ud718\uc5b4\uc9c0\ub294 \uc131\uc9c8\ub3c4 \uc0dd\uac01\ud574\uc57c \ud588\ub358 \uac83\uc774\ub2e4. \uc774 \uc720\ubb3c\uc758 \uc2dc\ub300\ub294 \uc870\uc120\uc73c\ub85c \uc18c\uac1c\ub418\uc5b4 \uc788\ub2e4. \uc624\ub298 \uacbd\uae30\uc7a5\uc5d0\uc11c \ubcf4\ub294 \ud65c\uc758 \ubaa8\uc2b5\uacfc \uace7\ubc14\ub85c \uacb9\uccd0 \ub193\uae30\ubcf4\ub2e4, \ub2f9\uc2dc\uc758 \ubb3c\uac74\uc5d0 \uc5b4\ub5a4 \uc7ac\ub8cc\ub97c \uc37c\ub294\uc9c0\ubd80\ud130 \uc0b4\ud3b4\ubcf4\ub294 \ud3b8\uc774 \uc774\ud574\ud558\uae30 \uc27d\ub2e4. \ub0a8\uc544 \uc788\ub294 \ud65c\uc5d0\ub294 \uc2dc\uc704\uac00 \uc5c6\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc904\uacfc \uad00\uacc4\ub41c \ubd80\ubd84\uae4c\uc9c0 \ubaa8\ub450 \uc0ac\ub77c\uc9c4 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc591 \ub05d\uc5d0 \uc904\uc744 \ub9ec \uc218 \uc788\ub3c4\ub85d \ud648\uc774 \ud30c\uc5ec \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud65c\uc758 \uac00\uc6b4\ub370\uc5d0\ub294 \uc190\uc7a1\uc774 \ubd80\ubd84\ub3c4 \uc788\ub2e4. \uc591 \ub05d\uc758 \ud648\uacfc \uac00\uc6b4\ub370\uc758 \uc190\uc7a1\uc774\ub97c \ub098\ub204\uc5b4 \ubcf4\uba74, \uae38\uac8c \uad7d\uc740 \ubab8\uccb4\uac00 \uc5b4\ub514\uc5d0\uc11c \uc190\uc5d0 \uc7a1\ud788\uace0 \uc5b4\ub514\uc5d0\uc11c \uc904\uacfc \ub9cc\ub0ac\ub294\uc9c0 \uc870\uae08\uc529 \uc77d\ud78c\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \uc644\uc131\ub41c \uc0ac\uc6a9 \uc7a5\uba74\uc774 \ubcf4\uc774\uc9c0 \uc54a\ub354\ub77c\ub3c4 \ud754\uc801\uc740 \uc5ed\ud560\uc744 \uc54c\ub824\uc900\ub2e4. \ube60\uc9c4 \ubd80\ubd84\uc744 \ub9c8\uc74c\ub300\ub85c \ucc44\uc6cc \ub123\uae30\ubcf4\ub2e4, \ub0a8\uc740 \uc790\ub9ac\ub97c \ucc28\ub840\ub85c \ubcf4\ub294 \uac83\ub9cc\uc73c\ub85c \ubb3c\uac74\uacfc \uac00\uae4c\uc6cc\uc9c8 \uc218 \uc788\ub2e4. \ud65c\uc744 \ub9cc\ub4dc\ub294 \uc7ac\ub8cc\ub294 \ubaa8\uc591\uc744 \uc720\uc9c0\ud558\uba74\uc11c\ub3c4 \ud718\uc5b4\uc84c\ub2e4 \ub3cc\uc544\uc624\ub294 \uc131\uc9c8\uc774 \ud544\uc694\ud558\ub2e4. \ub3cc\ucc98\ub7fc \ub2e8\ub2e8\ud558\uae30\ub9cc \ud558\uba74 \uc6d0\ud558\ub294 \ud589\ub3d9\uc744 \ub9cc\ub4e4\uae30 \uc5b4\ub835\ub2e4. \ubc15\ubb3c\uad00\uc774 \ubb3c\uc18c \ubfd4\uacfc \ud0c4\uc131\uc744 \ud568\uaed8 \uc124\uba85\ud558\ub294 \uac83\uc740 \uc7ac\ub8cc\ub97c \uadf8\uc800 \uadc0\ud558\uac70\ub098 \uc544\ub984\ub2f5\ub2e4\ub294 \uc774\uc720\ub85c\ub9cc \uace0\ub974\uc9c0 \uc54a\uc558\ub2e4\ub294 \ub2e8\uc11c\ub97c \uc900\ub2e4. \uc4f0\ub294 \ub3d9\uc791\uacfc \ubb3c\uc131\uc758 \uad00\uacc4\uac00 \uc81c\uc791\uc5d0 \ub4e4\uc5b4 \uc788\uc5c8\ub2e4. \uc774 \ub9d0\uc774 \uac01\uad81\uc758 \ubaa8\ub4e0 \uad6c\uc870\uc640 \uc7ac\ub8cc\ub97c \ud55c \uac00\uc9c0\ub85c \uc694\uc57d\ud55c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc790\ub8cc\ub294 \uc8fc\uc7ac\ub8cc\uc758 \ud2b9\uc9d5\uc744 \uc54c\ub824 \uc8fc\uba70 \uc804\uccb4 \uc81c\uc791 \uae30\uc220\uc758 \uc138\ubd80\ub294 \ub2e4\ub978 \uc124\uba85\uc774 \ud544\uc694\ud558\ub2e4. \uc720\ubb3c\uc744 \ubcf4\uba74 \ubb34\uc5c7\uc73c\ub85c \ub9cc\ub4e4\uc5c8\ub294\uc9c0 \uc606\uc5d0 \uc65c \uadf8\ub7f0 \uc131\uc9c8\uc774 \ud544\uc694\ud588\ub294\uc9c0\ub97c \ubb3c\uc5b4\ubcfc \uc218 \uc788\ub2e4. \uc5ed\uc0ac \uc18d \ubb34\uae30\ub294 \uacf5\uaca9\uc758 \uc774\uc57c\uae30\ubfd0 \uc544\ub2c8\ub77c \uc7ac\ub8cc\ub97c \uc774\ud574\ud55c \uae30\uc220\uc758 \uc5ed\uc0ac\ub85c\ub3c4 \uc77d\ud78c\ub2e4. \uc591\ub05d\uc758 \ud648\uc740 \ud604\uc7ac \uc5c6\ub294 \uc2dc\uc704\uc640\uc758 \uad00\uacc4\ub97c \uc54c\ub824 \uc900\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \ud65c\ub9cc \ub0a8\uc544 \uc788\ub2e4\uace0 \ucc98\uc74c\ubd80\ud130 \uc904 \uc5c6\uc774 \uc644\uc131\ud55c \ubb3c\uac74\uc73c\ub85c \uc0dd\uac01\ud558\uc9c0 \uc54a\uac8c \ud55c\ub2e4. \uc5c6\uc5b4\uc9c4 \ubd80\ud488\uc774 \uc788\uc5b4\ub3c4 \uadf8\uac83\uacfc \ub9de\ub2ff\ub358 \ubd80\ubd84\uc740 \ub0a8\uc744 \uc218 \uc788\ub2e4. \uc644\uc804\ud558\uc9c0 \uc54a\uc740 \uc720\ubb3c\uc744 \uc77d\uc744 \ub54c \uc811\uc810\uc744 \uc0b4\ud53c\ub294 \ubc29\ubc95\uc774\ub2e4. \ub2e4\ub9cc \ud648\uc758 \uc704\uce58\ub97c \ubcf4\uc558\ub2e4\uace0 \uc6d0\ub798\uc758 \uae38\uc774\uc640 \uc7a5\ub825\uc744 \uc0c8\ub85c \uacc4\uc0b0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc2e4\uc81c \uc7ac\ub8cc\uc758 \uc0c1\ud0dc\uc640 \uc0ac\uc6a9 \uc870\uac74\uc744 \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \ubcf4\uc874\ub41c \uc61b \ud65c\uc744 \ub2f9\uaca8 \uc2dc\ud5d8\ud558\ub294 \uac83\uc740 \uad00\ub78c\uc790\uc758 \uc77c\uc774 \uc544\ub2c8\ub2e4. \ub0a8\uc740 \uad6c\uc870\ub97c \uc124\uba85\uacfc \ud568\uaed8 \uc77d\uace0, \uc5f0\uc8fc\ub098 \uc0ac\uaca9\uc758 \ubcf5\uc6d0\uc740 \uc801\uc808\ud55c \uc790\ub8cc\uc640 \uc804\ubb38\uc801\uc778 \uac80\ud1a0\uc758 \uc601\uc5ed\uc73c\ub85c \uad6c\ubd84\ud560 \ud544\uc694\uac00 \uc788\ub2e4. \ud65c\uc740 \uc804\uccb4\uac00 \uae38\uac8c \uad7d\uc5c8\uc5b4\ub3c4 \uc0ac\ub78c\uc774 \uc7a1\ub294 \uc790\ub9ac\uac00 \ub530\ub85c \uc788\ub2e4. \uac00\uc6b4\ub370\uc758 \uc190\uc7a1\uc774\uc640 \uc591 \ub05d\uc758 \ud648\uc744 \ub098\ub204\uc5b4 \ubcf4\uba74 \uc190\uacfc \uc904\uc774 \ub9cc\ub098\ub294 \uad00\uacc4\uac00 \ubcf4\uc778\ub2e4. \ubb3c\uac74\uc758 \uc724\uacfd\ub9cc \uac10\uc0c1\ud560 \ub54c\ubcf4\ub2e4 \uc5b4\ub5a4 \ud589\ub3d9\uc744 \uc704\ud574 \uae38\uc774\uc640 \uc790\ub9ac\ub97c \ub098\ub204\uc5c8\ub294\uc9c0 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \ud615\ud0dc\uac00 \uc0ac\ub78c\uc758 \ubab8\uacfc \uc774\uc5b4\uc9c0\ub294 \uac83\uc774\ub2e4. \uc624\ub298 \uacbd\uae30\uc5d0\uc11c \ubcf8 \uc790\uc138\ub97c \uc774 \uc720\ubb3c\uc758 \uc2e4\uc81c \uc0ac\uc6a9 \uc7a5\uba74\uacfc \uace7\ubc14\ub85c \uac19\uac8c \ub193\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc2dc\ub300\uc640 \uc885\ub958\uc5d0 \ub530\ub77c \ub2e4\ub978 \uc870\uac74\uc774 \uc788\uc744 \uc218 \uc788\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc870\uc120\uc758 \uac01\uad81\uc774\ub77c\uace0 \uc18c\uac1c\ub41c \ud55c \uc810\uc744 \ubc14\ud0d5\uc73c\ub85c \uc7ac\ub8cc\uc640 \uc5f0\uacb0 \ubd80\ubd84\uc744 \uc0b4\ud3b4\ubcf8\ub2e4. \uc775\uc219\ud55c \ud65c\uc774\ub77c\ub294 \uc774\ub984 \uc548\uc5d0\ub3c4 \ub530\ub85c \ud655\uc778\ud560 \uae30\uc220\uacfc \uc2dc\uac04\uc774 \uc788\ub2e4\ub294 \uc810\uc744 \uc54c \uc218 \uc788\ub2e4. \uc6d0\ub798\ub294 \uc0ac\uc6a9\uc790\uac00 \uc7a1\uace0 \uc6c0\uc9c1\uc774\ub358 \ubb3c\uac74\uc774 \uc804\uc2dc\uc7a5\uc5d0\uc11c\ub294 \uc870\uc6a9\ud788 \ub193\uc778\ub2e4. \uc2dc\uc704\ub3c4 \uc5c6\uace0 \uc2e4\uc81c \ub3d9\uc791\ub3c4 \ubcf4\uc774\uc9c0 \uc54a\uc9c0\ub9cc, \uadf8 \uc0c1\ud0dc\uc5d0\uc11c \uc0c8\ub85c \ubcfc \uc218 \uc788\ub294 \uac83\uc774 \uc788\ub2e4. \uc5b4\ub514\uac00 \ubab8\uccb4\uc774\uace0 \uc5b4\ub290 \uacf3\uc774 \uc190\uc7a1\uc774\uc778\uc9c0, \ubd80\ud488\uc774 \uc5b4\ub5bb\uac8c \uc5f0\uacb0\ub418\uc5c8\uc744\uc9c0 \uc9c8\ubb38\ud560 \uc218 \uc788\ub2e4. \uc6c0\uc9c1\uc774\uc9c0 \uc54a\ub294\ub2e4\uace0 \uc4f0\uc784\uc758 \ud754\uc801\uae4c\uc9c0 \ubaa8\ub450 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774 \uc9c8\ubb38\uc744 \ub530\ub77c\uac00\uba74 \uc804\ud22c \uc7a5\uba74\uc744 \uc0c8\ub85c \uafb8\ubbf8\uc9c0 \uc54a\uace0\ub3c4 \uc720\ubb3c\uacfc \uac00\uae4c\uc6cc\uc9c8 \uc218 \uc788\ub2e4. \ub204\uac00 \uc5b8\uc81c \uc5bc\ub9c8\ub098 \uba40\ub9ac \uc3d8\uc558\ub294\uc9c0\ub294 \ub0a8\uc740 \uc790\ub8cc\uc758 \ub2e4\ub978 \ubb38\uc81c\ub85c \ub450\uc5b4\ub3c4 \ub41c\ub2e4. \uc791\uc740 \ud648\uacfc \uc7ac\ub8cc\uc758 \uc774\ub984\uc774 \uc6b0\ub9ac\uc5d0\uac8c \uc804\ud558\ub294 \uac83\uc740 \ud55c \ud589\ub3d9\uc744 \uac00\ub2a5\ud558\uac8c \ud558\ub824\uace0 \ubb3c\uac74\uc744 \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc774\ub2e4. \uc2dc\uc704 \uc5c6\ub294 \uc61b \ud65c\ub3c4 \uadf8 \uc5f0\uacb0\uc758 \uc77c\ubd80\ub97c \ub9d0\ud574 \uc900\ub2e4. \ubc15\ubb3c\uad00\uc5d0\ub294 \ucc98\uc74c \ub9cc\ub4e4\uc5b4\uc9c4 \uc0c1\ud0dc \uadf8\ub300\ub85c\uc778 \ubb3c\uac74\ub9cc \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \ubd80\ubd84\uc740 \ub0a8\uace0 \uc5b4\ub5a4 \ubd80\ubd84\uc740 \uc5c6\uc5b4\uc9c0\uae30\ub3c4 \ud55c\ub2e4. \uc774\ub54c \uc5c6\ub294 \ubd80\ubd84\ub9cc \uc544\uc26c\uc6cc\ud558\uba74 \ub0a8\uc740 \ubd80\ubd84\uc758 \uc7ac\ubbf8\ub97c \ub193\uce58\uae30 \uc27d\ub2e4. \uac01\uad81\uc5d0\uc11c\ub294 \uace1\uc120\uacfc \uc7ac\ub8cc, \uc190\uc7a1\uc774\uc640 \ud648\uc744 \ubcfc \uc218 \uc788\ub2e4. \ub204\uac00 \uc5b8\uc81c \uc774 \ud55c \uc810\uc744 \ub2f9\uacbc\ub294\uc9c0\uae4c\uc9c0 \uc124\uba85\uc774 \uc54c\ub824\uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub300\uc2e0 \uc190\uc744 \ub300\ub358 \uc790\ub9ac\uc640 \uc904\uc774 \ub2ff\ub358 \uc790\ub9ac\ub77c\ub294 \uad6c\uccb4\uc801\uc778 \ub2e8\uc11c\uac00 \uc788\ub2e4. \ub2e4\uc74c\uc5d0 \uc61b \ub3c4\uad6c\ub97c \ub9cc\ub0ac\ub294\ub370 \ud55c \ubd80\ubd84\uc774 \ube44\uc5b4 \uc788\ub2e4\uba74, \ub0a8\uc544 \uc788\ub294 \uac83\ubd80\ud130 \ucc9c\ucc9c\ud788 \uc0b4\ud3b4\ubcf4\uc790. \uc904\uc774 \uc5c6\ub294 \ud65c\ub3c4 \uc544\ubb34 \ub9d0 \uc5c6\ub294 \uace1\uc120\ub9cc\uc740 \uc544\ub2c8\ub2e4. \uc791\uc740 \ud648 \ud558\ub098\uac00 \uc6d0\ub798\uc758 \uc4f0\uc784\uc744 \uc0dd\uac01\ud558\uac8c \ud574 \uc900\ub2e4."}, {"id": "inca-quipu-knots-and-records", "title": "\ud0a4\ud478 \u2014 \uc789\uce74\ub294 \ub9e4\ub4ed\uc73c\ub85c \ubb34\uc5c7\uc744 \uae30\ub85d\ud588\uc744\uae4c", "summary": "\uc2e4\uc81c \ud0a4\ud478 \uc870\uac01\uacfc 16\uc138\uae30 \uae30\ub85d\uc744 \ud1b5\ud574 \uc789\uce74\uc758 \uc7a5\ubd80\u00b7\uc81c\uad6d \uc6b4\uc601\u00b7\ud574\ub3c5\uc758 \ud55c\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history", "category_title": "History", "subcategory": "America", "url": "stories/inca-quipu-knots-and-records/index.html", "image": "media/inca-quipu-knots-and-records.png", "alt": "1400~1600\ub144 \uc81c\uc791\uc73c\ub85c \uc18c\uac1c\ub418\ub294 \uc2e4\uc81c \ud0a4\ud478 \uc870\uac01. \uad75\uc740 \ub048 \uc544\ub798 \uc5ec\ub7ec \uac00\ub2e5\uacfc \ub9e4\ub4ed.", "text": "\ud0a4\ud478 \u2014 \uc789\uce74\ub294 \ub9e4\ub4ed\uc73c\ub85c \ubb34\uc5c7\uc744 \uae30\ub85d\ud588\uc744\uae4c \uc791\uc740 \ub048\ubb49\uce58\uc5d0 \ub0a8\uc740 \uc0ac\ub78c\uacfc \ubb3c\uc790\uc758 \uc218 \uc2e4\uc81c \ud0a4\ud478 \uc870\uac01\uacfc 16\uc138\uae30 \uae30\ub85d\uc744 \ud1b5\ud574 \uc789\uce74\uc758 \uc7a5\ubd80\u00b7\uc81c\uad6d \uc6b4\uc601\u00b7\ud574\ub3c5\uc758 \ud55c\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4. America \uc5ed\uc0ac \ubc15\ubb3c\uad00\uc5d0 \uc5ec\ub7ec \uac00\ub2e5\uc758 \ub048\uc774 \ub298\uc5b4\uc838 \uc788\ub2e4. \ub9e4\ub4ed\uc774 \ub4dc\ubb38\ub4dc\ubb38 \ubb36\uc600\uace0 \uae38\uc774\ub3c4 \uace0\ub974\uc9c0 \uc54a\ub2e4. \uc7a5\uc2dd\ud488\ucc98\ub7fc \ubcf4\uc77c \uc218 \uc788\uc9c0\ub9cc \uc774 \ubb3c\uac74\uc740 \uc789\uce74\uc758 \uae30\ub85d\uacfc \uc5f0\uacb0\ub41c\ub2e4. \ud0a4\ud478\ub77c\uace0 \ubd80\ub974\ub294 \ub9e4\ub4ed \uae30\ub85d \uc7a5\uce58\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc2e4\uc81c \ud0a4\ud478 \uc870\uac01\uc740 1400\ub144\uc5d0\uc11c 1600\ub144 \uc0ac\uc774\uc5d0 \ub9cc\ub4e4\uc5b4\uc9c4 \uac83\uc73c\ub85c \uc18c\uac1c\ub41c\ub2e4. \uc885\uc774\uc758 \uae00\uc790 \ub300\uc2e0 \ub048\uacfc \ub9e4\ub4ed\uc5d0 \uc815\ubcf4\ub97c \ub0a8\uacbc\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub0af\uc124\uc9c0\ub9cc, \ub113\uc740 \uc9c0\uc5ed\uc5d0\uc11c \uc0ac\ub78c\uacfc \ubb3c\uc790\uc758 \uc218\ub97c \ud30c\uc545\ud558\ub824 \ud588\ub2e4\ub294 \ubaa9\uc801\uc740 \uc758\uc678\ub85c \uc775\uc219\ud558\ub2e4. \uc789\uce74\ub294 \uc548\ub370\uc2a4 \uc9c0\uc5ed\uc758 \ub113\uc740 \ub545\uacfc \uc5ec\ub7ec \uacf5\ub3d9\uccb4\ub97c \uc5f0\uacb0\ud588\ub2e4. \uc0ac\ub78c\uacfc \uc790\uc6d0, \uc870\uc138\uc640 \ub178\ub3d9\uc744 \ud30c\uc545\ud558\ub294 \uc77c\uc740 \uc81c\uad6d\uc744 \uc6b4\uc601\ud558\ub294 \uc911\uc694\ud55c \uc870\uac74\uc774\uc5c8\ub2e4. \ubaa8\ub450\uc758 \uc5bc\uad74\uc744 \uc544\ub294 \uc791\uc740 \ub9c8\uc744\uacfc\ub294 \ub2e4\ub978 \uaddc\ubaa8\uc758 \uae30\ub85d\uc774 \ud544\uc694\ud588\ub2e4. \uad50\uc7ac\ub294 \ud0a4\ud478\uac00 \uc778\uad6c\uc640 \uc138\uae08, \ub545\uc758 \ubc30\ubd84\uacfc \uad70\ub300\uc758 \uc774\ub3d9 \uac19\uc740 \uc815\ubcf4\ub97c \uae30\ub85d\ud560 \uc218 \uc788\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub2e8\uc9c0 \uacc4\uc0b0\uc744 \ub3d5\ub294 \uac1c\uc778\uc758 \ubb3c\uac74\uc73c\ub85c\ub9cc \ubcfc \uc218\ub294 \uc5c6\ub2e4. \uc5b4\ub5a4 \uc218\ub97c \uae30\uc5b5\ud558\uace0 \uc804\ub2ec\ud560\uc9c0\ub294 \uacf5\ub3d9\uccb4\ub97c \uad00\ub9ac\ud558\ub294 \ud798\uacfc\ub3c4 \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub2e4. \uc0ac\uc9c4\uc744 \ubcf4\uba74 \uc911\uc2ec\uc774 \ub418\ub294 \ub048\uc744 \ub530\ub77c \uc5ec\ub7ec \uac00\ub2e5\uc774 \ub2ec\ub824 \uc788\ub2e4. \ud45c\uba74\uc758 \ub0b1\ub9d0\uc744 \uc77d\ub4ef \uace7\ubc14\ub85c \ub73b\uc744 \uc54c \uc218\ub294 \uc5c6\uc9c0\ub9cc, \ubc18\ubcf5\uacfc \ucc28\uc774\uac00 \uc788\ub294 \uad6c\uc870\ub77c\ub294 \uc810\uc740 \ubcf4\uc778\ub2e4. \ub9e4\ub4ed\uc758 \uc704\uce58\uc640 \uc885\ub958, \ub048\uc758 \uc0c9 \ub4f1 \uc5ec\ub7ec \uc694\uc18c\uac00 \uc815\ubcf4\uc758 \uad6c\ubd84\uc5d0 \uad00\uc5ec\ud560 \uc218 \uc788\uc5c8\ub2e4. \uad50\uc7ac\ub294 \ubb36\uace0 \ud480\uace0 \ub2e4\uc2dc \ubb36\ub294 \uc5ec\ub7ec \uc870\ud569\uc774 \uac00\ub2a5\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub2e4\ub9cc \uc774 \uc0ac\uc9c4\ub9cc\uc73c\ub85c \uac01\uac01\uc758 \ub9e4\ub4ed\uc774 \uc815\ud655\ud788 \uc5b4\ub5a4 \uc218\uc640 \ub300\uc0c1\uc744 \ub73b\ud558\ub294\uc9c0 \ud574\ub3c5\ud560 \uc218\ub294 \uc5c6\ub2e4. \ubb34\uc5c7\uc774 \uad6c\ubcc4\ub418\ub294\uc9c0 \uad00\ucc30\ud558\ub294 \uc77c\uacfc \uadf8 \uad6c\ubcc4\uc744 \ubc88\uc5ed\ud558\ub294 \uc77c \uc0ac\uc774\uc5d0\ub294 \uc544\uc9c1 \uac70\ub9ac\uac00 \uc788\ub2e4. \uc775\uc219\ud55c \ubb38\uc790\ub85c \uc801\ud78c \uc7a5\ubd80\ub97c \uba3c\uc800 \ub5a0\uc62c\ub9ac\uba74 \uc789\uce74\uc5d0 \uae30\ub85d\uc774 \uc5c6\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud558\uae30 \uc27d\ub2e4. \ud558\uc9c0\ub9cc \uc885\uc774\uc5d0 \uae00\uc790\ub97c \uc4f0\uc9c0 \uc54a\ub294 \uac83\uacfc \uc815\ubcf4\ub97c \ub0a8\uae30\uc9c0 \uc54a\ub294 \uac83\uc740 \ub2e4\ub978 \ub9d0\uc774\ub2e4. \ud0a4\ud478\ub294 \ud734\ub300\ud560 \uc218 \uc788\ub294 \ubb3c\uc9c8 \uc704\uc5d0 \uaddc\uce59\uc744 \ub2f4\uc740 \uc7a5\uce58\uc600\ub2e4. \uadf8\ub807\ub2e4\uace0 \ud0a4\ud478\ub97c \ud604\ub300\uc758 \ucc45\uc774\ub098 \ucef4\ud4e8\ud130 \ud30c\uc77c\uacfc \ubaa8\ub4e0 \uae30\ub2a5\uc774 \uac19\uc740 \ubb3c\uac74\uc73c\ub85c \uc124\uba85\ud560 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \ub2f9\uc2dc \uc0ac\ub78c\ub4e4\uc774 \uc0ac\uc6a9\ud55c \uad6c\uc870\uc640 \uadf8\uac83\uc744 \uc77d\uc744 \uc904 \uc544\ub294 \uc9c0\uc2dd\uc774 \uc788\uc5c8\ub2e4. \uc775\uc219\ud55c \uae30\uc900\uc73c\ub85c \ubd80\uc871\ud55c \uc810\ub9cc \ucc3e\uae30\ubcf4\ub2e4 \uc5b4\ub5a4 \ubb38\uc81c\ub97c \uc5b4\ub5a4 \ubc29\uc2dd\uc73c\ub85c \ud480\uc5c8\ub294\uc9c0 \ubcf4\ub294 \ud3b8\uc774 \ud765\ubbf8\ub86d\ub2e4. \uad50\uc7ac\ub294 \uc2a4\ud398\uc778\uc758 \uae30\ub85d\uc790 \ud398\ub4dc\ub85c \ub370 \uc2dc\uc5d0\uc0ac \ub370 \ub808\uc628\uc774 \ud604\uc9c0 \uc601\uc8fc\uc5d0\uac8c \ud0a4\ud478\uc758 \uc815\ud655\uc131\uc744 \uc124\uba85\ud574 \ub2ec\ub77c\uace0 \uc694\uccad\ud55c \uc77c\ud654\ub97c \uc778\uc6a9\ud55c\ub2e4. \uc601\uc8fc\ub294 \ud0a4\ud478\ub97c \uac00\uc838\uc624\uac8c \ud588\uace0, \uc2a4\ud398\uc778\uc778\ub4e4\uc774 \ub3c4\ucc29\ud55c \uc774\ud6c4 \uc81c\uacf5\ud55c \ubb3c\ud488\uc758 \ub0b4\uc5ed\uc744 \uc124\uba85\ud588\ub2e4. \uc2dc\uc5d0\uc0ac \ub370 \ub808\uc628\uc740 \uae08\uacfc \uc740, \uc758\ubcf5\uacfc \uace1\ubb3c \ub4f1\uc758 \uacc4\uc815\uc774 \ub098\uc624\ub294 \uac83\uc744 \ubcf4\uace0 \ub180\ub790\ub2e4\uace0 \uc801\uc5c8\ub2e4. \uc774\ub294 \ubaa8\ub4e0 \ud0a4\ud478\uc758 \ub0b4\uc6a9\uc744 \uc624\ub298 \uc6b0\ub9ac\uac00 \uc644\uc804\ud788 \uc77d\uc744 \uc218 \uc788\ub2e4\ub294 \uc99d\uac70\uac00 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \ub2f9\uc2dc \uadf8\uac83\uc744 \uc77d\ub294 \uc0ac\ub78c\uc5d0\uac8c \ub048\uc758 \ubc30\uc5f4\uc774 \uc2e4\uc81c \uac70\ub798\uc640 \ubb3c\ud488\uc758 \uae30\ub85d\uc73c\ub85c \uc791\ub3d9\ud588\ub2e4\ub294 \uc911\uc694\ud55c \uc99d\uc5b8\uc774\ub2e4. \ud0a4\ud478\uac00 \uc774\ub3d9\ud560 \uc218 \uc788\ub294 \ubb3c\uac74\uc774\ub77c\uace0 \ud574\ub3c4 \ub73b\uc774 \uc800\uc808\ub85c \ub4e4\ub9ac\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \uaddc\uce59\uc744 \uc0ac\uc6a9\ud588\uace0 \uae30\ub85d\ud55c \ub300\uc0c1\uc774 \ubb34\uc5c7\uc778\uc9c0 \uc544\ub294 \uc9c0\uc2dd\uc774 \ud544\uc694\ud588\ub2e4. \ubb3c\uac74\uacfc \uadf8\uac83\uc744 \ud574\uc11d\ud558\ub294 \uc0ac\ub78c\uc758 \uad00\uacc4\ub97c \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc6b0\ub9ac\ub3c4 \ucc98\uc74c \ubcf4\ub294 \uc57d\uc5b4\ub9cc \uac00\ub4dd\ud55c \uc7a5\ubd80\ub294 \uc124\uba85 \uc5c6\uc774 \uc77d\uae30 \uc5b4\ub835\ub2e4. \ud0a4\ud478 \uc5ed\uc2dc \ub0af\uc120 \uc0ac\ub78c\uc774 \ub048\uc744 \uc138\uc5b4 \ubcf4\uae30\ub9cc \ud558\uba74 \ubaa8\ub4e0 \uc0ac\ud68c\uc801 \ub9e5\ub77d\uae4c\uc9c0 \uc54c\uc544\ub0b4\ub294 \uc7a5\uce58\ub294 \uc544\ub2c8\uc5c8\ub2e4. \uc804\ub2ec\uacfc \ubcf4\uad00\uc758 \uc5ed\uc0ac\uc5d0\ub294 \uc815\ubcf4\ub97c \ub0a8\uae34 \uc7ac\ub8cc\ubfd0 \uc544\ub2c8\ub77c \uc77d\ub294 \ubc95\uc744 \uc774\uc5b4 \uc8fc\ub294 \uc0ac\ub78c\ub4e4\ub3c4 \ub4e4\uc5b4 \uc788\ub2e4. \uad50\uc7ac\uc5d0\ub294 \uc789\uce74\uc640 \uc2a4\ud398\uc778 \uc591\ucabd \ubc30\uacbd\uc744 \uac00\uc9c4 \uac00\ub974\uc2e4\ub77c\uc18c \ub370 \ub77c \ubca0\uac00\uc758 \uae30\ub85d\ub3c4 \uc778\uc6a9\ub41c\ub2e4. \uadf8\ub294 \ub9e4\ub4ed\uacfc \uad6c\uc2ac\uc758 \uae30\ub85d\uc5d0\uc11c \uc2dc\uc640 \uc774\uc57c\uae30\uac00 \uc804\ud574\uc84c\ub2e4\ub294 \uc124\uba85\uc744 \ub0a8\uacbc\ub2e4. \uc774\ub7f0 \uc99d\uc5b8\uc740 \ud0a4\ud478\uc758 \uc5ed\ud560\uc774 \uc218\ub7c9 \uae30\ub85d\ubcf4\ub2e4 \ub113\uc5c8\uc744 \uac00\ub2a5\uc131\uc744 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ud558\uc9c0\ub9cc \uac00\ub2a5\uc131\uacfc \uc644\uc804\ud55c \ud574\ub3c5\uc740 \ub2e4\ub974\ub2e4. \uc624\ub298\ub0a0 \ubaa8\ub4e0 \ud0a4\ud478\uc5d0\uc11c \ubb38\uc7a5\uacfc \uc2dc\ub97c \uc77d\uc744 \uc218 \uc788\ub2e4\ub294 \ub73b\uc73c\ub85c \uc18c\uac1c\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc5b4\ub5a4 \uc815\ubcf4\uae4c\uc9c0 \ub2f4\uc558\ub294\uc9c0, \uc218\ub7c9\uacfc \ub2e4\ub978 \ub0b4\uc6a9\uc774 \uc5b4\ub5bb\uac8c \uad6c\ubcc4\ub418\uc5c8\ub294\uc9c0\uc5d0\ub294 \ub0a8\uc740 \uc9c8\ubb38\uc774 \uc788\ub2e4. \ud765\ubbf8\ub85c\uc6b4 \uc99d\uc5b8\uc77c\uc218\ub85d \uadf8 \ubc94\uc704\ub97c \uc9c0\ud0a4\uba70 \uc77d\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc5ec\ub7ec \ud0a4\ud478\uac00 \ud30c\uad34\ub418\uc5c8\uace0 \uc0ac\uc6a9\uacfc \ud574\ub3c5\uc5d0 \ud544\uc694\ud55c \uc9c0\uc2dd\ub3c4 \ub9ce\uc774 \uc783\uc5b4\ubc84\ub838\ub2e4. \uadf8\ub798\uc11c \ubc15\ubb3c\uad00\uc5d0 \ub048\uc774 \ub0a8\uc544 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uadf8 \ub0b4\uc6a9\uc774 \ubaa8\ub450 \uc6b0\ub9ac\uc5d0\uac8c \uc5f4\ub824 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uac19\uc9c0 \uc54a\ub2e4. \uae30\ub85d\uc758 \ubcf4\uc874\uc5d0\ub294 \ubb3c\uc9c8\uacfc \uc9c0\uc2dd\uc774\ub77c\ub294 \ub450 \ubb38\uc81c\uac00 \uc788\ub2e4. \uc0ac\uc9c4 \uc18d\uc758 \ud0a4\ud478\ub3c4 \ub113\uc740 \uae30\ub85d \uc804\ud1b5\uc758 \ud55c \uc870\uac01\uc774\ub2e4. \uc81c\uc791 \uc2dc\uae30\uac00 1400~1600\ub144\uc73c\ub85c \uc81c\uc2dc\ub41c\ub2e4\ub294 \uc810\uc740 \uae30\uc5b5\ud558\ub418, \uadf8\uac83\ub9cc\uc73c\ub85c \uc5b4\ub290 \uad00\ub9ac\uac00 \uc5b4\ub290 \ud574\uc758 \uc138\uae08\uc744 \uc801\uc5c8\ub294\uc9c0 \uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc720\ubb3c\uc758 \uc124\uba85\uc774 \uc54c\ub824 \uc8fc\ub294 \ubc94\uc704\uc640 \uc6b0\ub9ac\uac00 \uae30\ub300\ud558\ub294 \uad6c\uccb4\uc801\uc778 \uc774\uc57c\uae30\ub294 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ud0a4\ud478\ub294 \uae30\ub85d\uc744 \ub0a8\uae30\ub824\ub294 \uc778\uac04\uc758 \ud544\uc694\uac00 \ubc18\ub4dc\uc2dc \uac19\uc740 \ubaa8\uc591\uc758 \ubb3c\uac74\uc744 \ub9cc\ub4e4\uc9c0\ub294 \uc54a\uc558\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ub113\uc740 \ub545\uc758 \uc0ac\ub78c\uacfc \uc790\uc6d0\uc744 \ud30c\uc545\ud558\ub824\ub294 \uc77c\uc740 \uc775\uc219\ud558\uc9c0\ub9cc \uadf8 \uc77c\uc744 \uc218\ud589\ud55c \ub048\uacfc \ub9e4\ub4ed\uc758 \uad6c\uc870\ub294 \uc0c8\ub86d\ub2e4. \uc775\uc219\ud568\uacfc \ub0af\uc126\uc774 \ud55c \ubb3c\uac74 \uc548\uc5d0 \ub193\uc5ec \uc788\ub2e4. \ub2e4\uc74c\uc5d0 \uc774\ub7f0 \ub048\ubb49\uce58\ub97c \ub9cc\ub098\uba74 \uc7a5\uc2dd\ucc98\ub7fc \ud6d1\uace0 \uc9c0\ub098\uac00\uae30\ubcf4\ub2e4 \uc5b4\ub514\uc5d0 \ucc28\uc774\uac00 \uc788\ub294\uc9c0 \uc7a0\uae50 \uc0b4\ud3b4\ubcf4\uc790. \uadf8\uac83\uc744 \uc77d\uc5c8\ub358 \uc0ac\ub78c\uc758 \uc190\uacfc \ubaa9\uc18c\ub9ac\ub3c4 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \uc789\uce74\uc758 \ub9e4\ub4ed\uc740 \uae00\uc790\uc758 \uc5ed\uc0ac \ubc16\uc73c\ub85c \ubc00\uc5b4 \ub450\uc5c8\ub358 \uae30\ub85d\uc758 \uc138\uacc4\ub97c \ub2e4\uc2dc \ud3bc\uccd0 \uc8fc\ub294 \uc791\uc740 \uc7a5\ubd80\ub2e4."}, {"id": "luther-pamphlets-and-reformation", "title": "\ub8e8\ud130 \u2014 \uc791\uc740 \uc778\uc1c4\ubb3c\uc740 \uc5b4\ub5bb\uac8c \uc720\ub7fd\uc744 \ud754\ub4e4\uc5c8\uc744\uae4c", "summary": "1517\ub144\uc758 \ub17c\uc81c\uc640 \uc778\uc1c4\ubb3c\uc758 \ud655\uc0b0\uc744 \ub530\ub77c \uc885\uad50\uac1c\ud601\uc758 \uc0ac\uc0c1\u00b7\uad8c\uc704\u00b7\uc815\uce58\uac00 \ub9cc\ub098\ub294 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history", "category_title": "History", "subcategory": "Europe", "url": "stories/luther-pamphlets-and-reformation/index.html", "image": "media/luther-pamphlets-and-reformation.png", "alt": "16\uc138\uae30 \ucd08 \ubd84\uc704\uae30\uc758 \uc778\uc1c4\uc18c\uc5d0\uc11c \uc778\uc1c4\uacf5\uc774 \uc791\uc740 \uc778\uc1c4\ubb3c\uc744 \uc0b4\ud53c\ub294 \uc0c1\uc0c1 \uc18d \uc7a5\uba74.", "text": "\ub8e8\ud130 \u2014 \uc791\uc740 \uc778\uc1c4\ubb3c\uc740 \uc5b4\ub5bb\uac8c \uc720\ub7fd\uc744 \ud754\ub4e4\uc5c8\uc744\uae4c \ud55c \uad50\uc218\uc758 \ub17c\uc7c1\uc774 \uc5ec\ub7ec \ub3c4\uc2dc\uc758 \uc77d\uc744\uac70\ub9ac\uac00 \ub418\uae30\uae4c\uc9c0 1517\ub144\uc758 \ub17c\uc81c\uc640 \uc778\uc1c4\ubb3c\uc758 \ud655\uc0b0\uc744 \ub530\ub77c \uc885\uad50\uac1c\ud601\uc758 \uc0ac\uc0c1\u00b7\uad8c\uc704\u00b7\uc815\uce58\uac00 \ub9cc\ub098\ub294 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Europe \uc5ed\uc0ac 1517\ub144 \ub3c5\uc77c \ube44\ud150\ubca0\ub974\ud06c\uc758 \uad50\uc218 \ub9c8\ub974\ud2f4 \ub8e8\ud130\ub294 \uad50\ud68c\uc758 \ud55c \uad00\ud589\uc5d0 \ubc18\ub300\ud558\ub294 \ub17c\uc81c\ub4e4\uc744 \uc37c\ub2e4. \uac15\uc758\uc2e4\uacfc \uc131\uc9c1\uc790\ub4e4\uc758 \ud1a0\ub860 \uc548\uc5d0\uc11c \ub05d\ub0a0 \uc218\ub3c4 \uc788\uc5c8\ub358 \uae00\uc774\uc5c8\ub2e4. \uadf8\ub7ec\ub098 \ubcf5\uc0ac\ub41c \uc885\uc774\ub294 \ub2e4\ub978 \ub3c4\uc2dc\ub85c \uc774\ub3d9\ud588\uace0 \ub17c\uc7c1\uc740 \uadf8 \uae00\uc744 \ucc98\uc74c \uc4f4 \uc7a5\uc18c\ubcf4\ub2e4 \ud6e8\uc52c \ub113\uc5b4\uc84c\ub2e4. \uc885\uad50\uac1c\ud601\uc744 \uac70\ub300\ud55c \uc0ac\uc0c1\uacfc \uc804\uc7c1\uc758 \uc774\ub984\uc73c\ub85c \uba3c\uc800 \ub9cc\ub098\uba74 \uc5b4\ub835\uac8c \ub290\uaef4\uc9c4\ub2e4. \uc774\ubc88\uc5d0\ub294 \uc791\uc740 \uc778\uc1c4\ubb3c\uc5d0\uc11c \ucd9c\ubc1c\ud574 \ubcf4\uc790. \uc65c \ud55c \uc218\ub3c4\uc0ac\uc758 \ubb38\uc81c \uc81c\uae30\uac00 \uc774\ub807\uac8c \uba40\ub9ac \ud37c\uc84c\uace0, \uc778\uc1c4\ub41c \uae00\uc740 \uadf8 \uacfc\uc815\uc5d0\uc11c \uc5b4\ub5a4 \uc5ed\ud560\uc744 \ud588\uc744\uae4c. \ub8e8\ud130\uac00 \ubb38\uc81c \uc0bc\uc740 \uac83 \uac00\uc6b4\ub370 \ud558\ub098\ub294 \uc624\ub298\ub0a0 \ud754\ud788 \uba74\uc8c4\ubd80\ub77c\uace0 \ubd80\ub974\ub294 \ub300\uc0ac \uc99d\uc11c\uc758 \ud310\ub9e4\uc600\ub2e4. \uac00\ud1a8\ub9ad\uc758 \uc124\uba85\uc5d0\uc11c\ub294 \uc5f0\uc625\uc5d0\uc11c \uacaa\ub294 \ubc8c\uc744 \uc904\uc774\ub294 \uac83\uacfc \uad00\ub828\ub41c \uc81c\ub3c4\uc600\ub2e4. \ub2e8\uc21c\ud788 \ub3c8\uc744 \ub0b4\uba74 \ubb34\uc2a8 \uc8c4\ub4e0 \uc5c6\uc5b4\uc9c4\ub2e4\ub294 \ud55c \ubb38\uc7a5\uc73c\ub85c \ub2f9\uc2dc \uad50\ub9ac\ub97c \uc694\uc57d\ud558\uba74 \uc815\ud655\ud558\uc9c0 \uc54a\ub2e4. \uadf8\ub7fc\uc5d0\ub3c4 \ub3c8\uc744 \ub0b4\ub294 \ud589\uc704\uac00 \ud68c\uac1c\uc640 \uc2e0\uc559\uc744 \ub300\uc2e0\ud558\ub294 \uac83\ucc98\ub7fc \ubc1b\uc544\ub4e4\uc5ec\uc9c8 \uc218 \uc788\ub2e4\ub294 \uc810\uc774 \ub8e8\ud130\uc5d0\uac8c \ud070 \ubb38\uc81c\uc600\ub2e4. \uad50\uc7ac\ub294 \uc694\ud55c \ud14c\uccbc\uc758 \ud310\ub9e4 \ud65c\ub3d9\uacfc \ub8e8\ud130\uc758 \uad6c\uc6d0\uc5d0 \ub300\ud55c \uace0\ubbfc\uc744 \uc5f0\uacb0\ud55c\ub2e4. \uae08\uc735\uc801 \uac70\ub798\ucc98\ub7fc \ubcf4\uc774\ub294 \ud589\uc704\uc640 \uc601\ud63c\uc758 \ubb38\uc81c\uac00 \uac19\uc740 \uc790\ub9ac\uc5d0\uc11c \ubd80\ub52a\ucce4\ub2e4. \ub8e8\ud130\ub294 \ub300\uc0ac \uc99d\uc11c \ud310\ub9e4\ub97c \ube44\ud310\ud558\ub294 95\uac1c \ub17c\uc81c\ub97c \uc791\uc131\ud588\ub2e4. \uad50\uc7ac\uc5d0 \uc2e4\ub9b0 \uc77c\ubd80 \ub17c\uc81c\uc5d0\ub294 \uac00\ub09c\ud55c \uc0ac\ub78c\uc744 \ub3d5\ub294 \uc77c\uc774 \uc99d\uc11c\ub97c \uc0ac\ub294 \uac83\ubcf4\ub2e4 \ub0ab\ub2e4\ub294 \uc8fc\uc7a5\ub3c4 \ubcf4\uc778\ub2e4. \ub17c\uc7c1\uc758 \uc911\uc2ec\uc5d0\ub294 \ub3c8\uc758 \uc9c0\ucd9c\uacfc \uc2e0\uc559\uc758 \uc2e4\ucc9c\uc744 \uc5b4\ub5bb\uac8c \ud3c9\uac00\ud560\uc9c0\ub77c\ub294 \uc9c8\ubb38\uc774 \uc788\uc5c8\ub2e4. \uc720\uba85\ud55c \uc7a5\uba74\uc740 \uad50\ud68c \ubb38\uc5d0 \ub17c\uc81c\ub97c \ubabb\uc73c\ub85c \ubc15\ub294 \ubaa8\uc2b5\uc774\ub2e4. \ud558\uc9c0\ub9cc \uc774\ubc88 \uc774\uc57c\uae30\uc758 \ucd9c\ubc1c\uc810\uc744 \uadf8 \uadf9\uc801\uc778 \uc7a5\uba74\uc758 \ubaa8\ub4e0 \uc138\ubd80\uc5d0 \uac78 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \uae00\uc774 \uc791\uc131\ub418\uace0 \uad50\ud68c \uad00\uacc4\uc790\uc5d0\uac8c \uc804\ub2ec\ub418\uc5c8\uc73c\uba70 \uc778\uc1c4\ub41c \uc0ac\ubcf8\uc73c\ub85c\ub3c4 \ud37c\uc84c\ub2e4\ub294 \uc810\uc774\ub2e4. \ub17c\uc7c1\uc740 \uc77d\uc744 \uc218 \uc788\ub294 \ud615\ud0dc\ub97c \uc5bb\uc5c8\ub2e4. \uc774\ubbf8 \uc720\ub7fd\uc5d0\uc11c \ubc1c\uc804\ud558\ub358 \uc778\uc1c4 \uae30\uc220\uc740 \uac19\uc740 \uae00\uc744 \uc5ec\ub7ec \ubd80 \ub9cc\ub4e4\uc5b4 \uc804\ub2ec\ud558\ub294 \ub370 \ud798\uc744 \ubcf4\ud0f0\ub2e4. \uad50\uc7ac\ub294 \ub8e8\ud130\uc758 \uc800\uc220 \uc218\ucc9c \ubd80\uac00 \uc720\ub7fd\uc5d0\uc11c \uc720\ud1b5\ub418\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud55c \uc0ac\ub78c\uc774 \uc9c1\uc811 \uac00\uc11c \ub9d0\ud558\uc9c0 \uc54a\uc544\ub3c4 \ub2e4\ub978 \uacf3\uc758 \ub3c5\uc790\uac00 \uae00\uc744 \ub9cc\ub0a0 \uc218 \uc788\uc5c8\ub2e4. \ubb3c\ub860 \uc778\uc1c4\ud588\ub2e4\uace0 \ub204\uad6c\ub098 \uc989\uc2dc \uac19\uc740 \ub73b\uc73c\ub85c \uc774\ud574\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc77d\uc744 \uc218 \uc788\ub294 \uc0ac\ub78c\uc758 \ubc94\uc704\uc640 \uc5b8\uc5b4, \uc804\ub2ec\uacfc \ud1a0\ub860\uc758 \uad00\uacc4\uac00 \ub0a8\ub294\ub2e4. \uae30\uc220\uc740 \uc0ac\uc0c1\uc744 \ub300\uc2e0 \ub9cc\ub4e0 \uac83\uc774 \uc544\ub2c8\ub77c \uadf8 \uc0ac\uc0c1\uc774 \uc774\ub3d9\ud558\uace0 \ub2e4\uc2dc \ub17c\uc758\ub420 \uc870\uac74\uc744 \ubc14\uafb8\uc5c8\ub2e4. \uc885\uc774\uc758 \uc218\uac00 \ub298\uc5b4\ub09c \uc77c\uacfc \ub17c\uc7c1\uc758 \ubc94\uc704\uac00 \ub113\uc5b4\uc9c4 \uc77c\uc774 \ub9cc\ub0ac\ub2e4. \ub8e8\ud130\ub294 \ucc98\uc74c\ubd80\ud130 \uc0c8\ub85c\uc6b4 \uad50\ud68c\ub97c \ubaa8\ub450 \uc124\uacc4\ud574 \ub193\uace0 \uc2dc\uc791\ud55c \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uad50\uc7ac\ub294 \uadf8\uac00 \uad50\ud68c \uad00\ud589\uc758 \uac1c\ud601\uc744 \ubc14\ub790\uc9c0\ub9cc \ub300\uc751 \uacfc\uc815\uc5d0\uc11c \uac08\ub4f1\uc774 \ub354 \ucee4\uc84c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub204\uac00 \uc8c4\uc640 \uad6c\uc6d0\uc5d0 \uad00\ud574 \uc5b4\ub5a4 \uad8c\ud55c\uc744 \uac00\uc9c0\ub294\uc9c0 \ubb3b\ub294 \uc77c\uc740 \uc81c\ub3c4\uc758 \uc911\uc2ec\uc744 \uac74\ub4dc\ub838\ub2e4. 1518\ub144 \uc544\uc6b0\ud06c\uc2a4\ubd80\ub974\ud06c\uc5d0\uc11c \ubb38\ub2f5\uc774 \uc774\ub8e8\uc5b4\uc84c\uace0, \uc8fc\uc7a5\uc744 \ucca0\ud68c\ud558\ub77c\ub294 \uc694\uad6c\ub3c4 \uc774\uc5b4\uc84c\ub2e4. \ub8e8\ud130\uac00 \ubb3c\ub7ec\uc11c\uc9c0 \uc54a\uc790 1521\ub144 \ud30c\ubb38\uc744 \ubc1b\uc558\ub2e4. \uc885\uc774\uc5d0 \uc801\ud78c \ube44\ud310\uc740 \ub2e8\uc21c\ud55c \uac1c\uc778 \uc758\uacac\uc73c\ub85c \ub0a8\uc9c0 \uc54a\uc558\ub2e4. \uae00\uc744 \uc4f4 \uc0ac\ub78c\uc758 \uc885\uad50\uc801 \uc9c0\uc704\uc640 \uadf8\ub97c \ub458\ub7ec\uc2fc \uad8c\ub825 \uad00\uacc4\uae4c\uc9c0 \ubc14\uafb8\uc5c8\ub2e4. \ub8e8\ud130\ub294 \uc2e0\uc559\uacfc \uc131\uc11c\uc758 \uad8c\uc704\ub97c \uac15\uc870\ud558\uba70 \uae30\uc874\uc758 \uad00\ud589\uacfc \uad50\ud669\uc758 \uad8c\uc704\ub97c \ub2e4\uc2dc \ubb3c\uc5c8\ub2e4. \uadf8\uac00 \uc8fc\uc7a5\ud55c \uad6c\uc6d0\uacfc \uc2e0\uc559\uc758 \uad00\uacc4\ub294 \ub2f9\uc2dc\uc758 \uacf5\uc2dd \uac00\ub974\uce68\uacfc \uc911\uc694\ud55c \ucc28\uc774\uac00 \uc788\uc5c8\ub2e4. \uc624\ub298\uc758 \ub3c5\uc790\ub294 \uc5b4\ub290 \ud55c\ucabd\uc744 \ud48d\uc790\uc801\uc778 \ud55c \uc904\ub85c \uc904\uc774\uae30\ubcf4\ub2e4 \uc0ac\ub78c\ub4e4\uc774 \ubb34\uc5c7\uc744 \ub450\uace0 \ub2e4\ud22c\uc5c8\ub294\uc9c0 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \uc778\uc1c4\ubb3c\uc758 \ud798\ub3c4 \ubc14\ub85c \uadf8 \uad6c\uccb4\uc801\uc778 \uc9c8\ubb38\uacfc \uc5f0\uacb0\ub418\uc5c8\ub2e4. \uc778\uc1c4\uae30\ub9cc \ub193\uc5ec \uc788\ub2e4\uace0 \uac19\uc740 \uc0ac\uac74\uc774 \uc790\ub3d9\uc73c\ub85c \uc77c\uc5b4\ub098\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ub7ab\ub3d9\uc548 \uc313\uc778 \ubd88\ub9cc\uacfc \uc2e0\uc559\uc758 \uace0\ubbfc, \uc5b4\ub5a4 \uc124\uba85\uc5d0 \uadc0\ub97c \uae30\uc6b8\uc77c \uc900\ube44\uac00 \ub418\uc5b4 \uc788\ub358 \uc0ac\ub78c\ub4e4\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4. \uae30\uc220\uacfc \uc2dc\ub300\uc758 \uc870\uac74\uc774 \ub9cc\ub09c \uac83\uc774\ub2e4. \uc885\uad50\uac1c\ud601\uc740 \uad50\ud68c\uc640 \uac1c\uc778\uc758 \uad00\uacc4\ub9cc \ubc14\uafbc \uac83\uc774 \uc544\ub2c8\uc5c8\ub2e4. \ub3c5\uc77c \uc9c0\uc5ed\uc758 \uc81c\ud6c4\ub4e4\uc5d0\uac8c \uad50\ud669\uc758 \uad8c\uc704\uc640 \uc0c8\ub85c\uc6b4 \uc2e0\uc559\uc758 \uc120\ud0dd\uc740 \uc815\uce58\uc801 \ubb38\uc81c\uc774\uae30\ub3c4 \ud588\ub2e4. \uad50\uc7ac\ub294 \ud1b5\uce58\uc790\ub4e4\uc774 \uc0c8 \uc885\uad50\ub97c \ubc1b\uc544\ub4e4\uc774\uba70 \uc790\uc2e0\uc758 \uad8c\ud55c\uacfc \uc5f0\uacb0\ud55c \uacfc\uc815\uc744 \uc124\uba85\ud55c\ub2e4. \ub530\ub77c\uc11c \ub17c\uc7c1\uc774 \ud37c\uc9c4 \uc77c\uc744 \ubaa8\ub450 \uc790\uc720\ub86d\uac8c \uc77d\uace0 \uace0\ub978 \uac1c\uc778\ub4e4\uc758 \ud569\uc758\ub85c\ub9cc \ubcfc \uc218\ub294 \uc5c6\ub2e4. \ub4a4\uc5d0\ub294 \ud1b5\uce58\uc790\uac00 \uc120\ud0dd\ud55c \uc885\uad50\ub97c \uc2e0\ubbfc\uc774 \ub530\ub77c\uc57c \ud558\ub294 \uc870\uac74\ub3c4 \ub098\ud0c0\ub0ac\ub2e4. \uc791\uc740 \uae00\uc774 \uacf5\uc801\uc778 \uc81c\ub3c4\uc5d0 \ub4e4\uc5b4\uac08 \ub54c \ucc98\uc74c\uc758 \uc9c8\ubb38\uacfc \ub2e4\ub978 \uad8c\ub825\uc758 \ubb38\uc81c\uac00 \ub354\ud574\uc9c8 \uc218 \uc788\uc5c8\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 16\uc138\uae30 \ucd08\uc758 \ubd84\uc704\uae30\ub97c \ub5a0\uc62c\ub9ac\ub294 \uc0c1\uc0c1 \uc18d \uc778\uc1c4\uc18c\ub2e4. \uc2e4\uc81c \ub8e8\ud130\uc758 \ucc45\uc744 \ucc0d\ub358 \uc7a5\uc18c\uc640 \uc7a5\ube44, \ud2b9\uc815 \uc778\ubb3c\uc744 \ubcf5\uc6d0\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uae00\uc744 \uc870\ud310\ud558\uace0 \uc885\uc774\uc5d0 \uc62e\uae30\uace0 \uc313\uc544 \ub450\ub294 \ubb3c\ub9ac\uc801\uc778 \uc791\uc5c5\uc744 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uc0ac\uc0c1\uc758 \uc5ed\uc0ac\uc5d0\uc11c\ub294 \uae00\uc744 \uc4f4 \uc720\uba85\ud55c \uc0ac\ub78c\ub9cc \uae30\uc5b5\ud558\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \uae00\uc774 \uba40\ub9ac \uac00\ub824\uba74 \ub9cc\ub4dc\ub294 \uc190\uacfc \uc62e\uae30\ub294 \uae38, \uc77d\uace0 \uc804\ud558\ub294 \uc0ac\ub78c\ub4e4\uc774 \ud544\uc694\ud558\ub2e4. \uc778\uc1c4\ubb3c\uc740 \uc0dd\uac01\uc758 \ub0b4\uc6a9\uacfc \uadf8\uac83\uc744 \uc774\ub3d9\uc2dc\ud0a4\ub294 \uc791\uc5c5\uc774 \ud568\uaed8 \uc774\ub8e8\uc5b4 \ub0b8 \ubb3c\uac74\uc774\uc5c8\ub2e4. \ub8e8\ud130\uc758 \uae00\uc774 \uc720\ub7fd\uc744 \ud754\ub4e0 \uc774\uc720\ub97c \uc778\uc1c4\uae30\uc758 \ubc1c\uba85 \ud558\ub098\ub85c \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \uac19\uc740 \ub17c\uc7c1\uc744 \uc5ec\ub7ec \uacf3\uc5d0\uc11c \ub9cc\ub0a0 \uc218 \uc788\uac8c \ud55c \ub9e4\uccb4\uc758 \uc5ed\ud560\uc740 \ubd84\uba85\ud558\ub2e4. \ud55c \ub3c4\uc2dc\uc758 \ubb38\ub2f5\uc774 \ub2e4\ub978 \ub3c4\uc2dc \uc0ac\ub78c\ub4e4\uc758 \ub300\ud654\uc5d0 \ub4e4\uc5b4\uac08 \uc218 \uc788\uc5c8\ub2e4. \uc624\ub798\ub41c \uc791\uc740 \ucc45\uc790\ub97c \ubcf4\uba74 \uadf8 \uc548\uc758 \uc8fc\uc7a5\uacfc \ud568\uaed8 \uadf8 \ucc45\uc790\uac00 \ub204\uad6c\uc758 \uc190\uc744 \uac70\uccd0 \uc5b4\ub514\ub85c \uac14\uc744\uc9c0\ub3c4 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc885\uad50\uac1c\ud601\uc758 \uc774\uc57c\uae30\ub294 \uc0ac\uc0c1\uc774 \uc5b4\ub5bb\uac8c \uc6c0\uc9c1\uc774\ub294\uc9c0\uc5d0 \uad00\ud55c \uc774\uc57c\uae30\uc774\uae30\ub3c4 \ud558\ub2e4. \ub8e8\ud130\uc758 \uc778\uc1c4\ubb3c\uc740 \uc0dd\uac01\uc758 \ud798\uacfc \uadf8\uac83\uc744 \ud37c\ub728\ub9ac\ub294 \uae30\uc220\uc774 \ub9cc\ub09c \uc21c\uac04\uc744 \ubcf4\uc5ec \uc900\ub2e4."}, {"id": "mummy-museum-move", "title": "\ubbf8\ub77c\uac00 \uc774\uc0ac\ud558\ub824\uba74 \ub204\uad6c\uc5d0\uac8c \ubb3c\uc5b4\ubd10\uc57c \ud560\uae4c", "summary": "\ubc15\ubb3c\uad00 \ubbf8\ub77c\uc758 \uc774\ub3d9\uc5d0\ub3c4 \ud3ec\uc7a5 \uc678\uc5d0 \ud655\uc778\ud560 \uc77c\uc774 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.", "category": "history", "category_title": "History", "subcategory": "America", "url": "stories/mummy-museum-move/index.html", "image": "media/mummy-museum-move.jpg", "alt": "\ubbf8\ub77c\uac00 \uc774\uc0ac\ud558\ub824\uba74 \ub204\uad6c\uc5d0\uac8c \ubb3c\uc5b4\ubd10\uc57c \ud560\uae4c\uc758 \uc8fc\uc81c\ub97c \ud45c\ud604\ud55c AI \uc124\uba85\uc6a9 \uc0bd\ud654. \uc2e4\uc81c \uc791\ud488\uc774\ub098 \uac74\ucd95\ubb3c\uc744 \uadf8\ub300\ub85c \uc7ac\ud604\ud55c \uc774\ubbf8\uc9c0\uac00 \uc544\ub2d9\ub2c8\ub2e4.", "text": "\ubbf8\ub77c\uac00 \uc774\uc0ac\ud558\ub824\uba74 \ub204\uad6c\uc5d0\uac8c \ubb3c\uc5b4\ubd10\uc57c \ud560\uae4c \uc624\ub798\ub41c \uc720\ud574\ub97c \uc62e\uae30\uba70 \ubbf8\uc220\uad00\uc774 \ud655\uc778\ud55c \uac83 \ubc15\ubb3c\uad00 \ubbf8\ub77c\uc758 \uc774\ub3d9\uc5d0\ub3c4 \ud3ec\uc7a5 \uc678\uc5d0 \ud655\uc778\ud560 \uc77c\uc774 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. America \uc5ed\uc0ac \ubc15\ubb3c\uad00\uc758 \ubbf8\ub77c\ub97c \ub2e4\ub978 \ubbf8\uc220\uad00\uc73c\ub85c \uc62e\uae34\ub2e4\uace0 \ud574 \ubcf4\uc790. \uba3c\uc800 \ub5a0\uc624\ub974\ub294 \uac83\uc740 \ud3ec\uc7a5 \uc0c1\uc790\uc640 \uc870\uc2ec\uc2a4\ub7ec\uc6b4 \uc6b4\uc1a1\uc774\ub2e4. \uadf8\ub7f0\ub370 \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc5d0\uc11c\ub294 \uadf8\ubcf4\ub2e4 \uc55e\uc11c \ubc95\ub960\ud300\uc5d0 \uc9c8\ubb38\uc774 \ub3c4\ucc29\ud588\ub2e4. \uc0ac\ub78c\uc758 \uc720\ud574\ub97c \uc8fc \uacbd\uacc4 \ub108\uba38\ub85c \uc62e\uae38 \ub54c \uc54c\uc544\uc57c \ud560 \ubc95\uc774 \uc788\ub290\ub0d0\ub294 \ub0b4\uc6a9\uc774\uc5c8\ub2e4. \ud669\uae08\uc774\ub098 \ub3cc\ub85c \ub9cc\ub4e0 \uc720\ubb3c\uacfc \ub2ec\ub9ac \ubbf8\ub77c\ub294 \ud55c\ub54c \uc0b4\uc558\ub358 \uc0ac\ub78c\uc758 \ubab8\uc774\ub2e4. \uc624\ub798\ub418\uc5c8\ub2e4\ub294 \uc774\uc720\ub85c \uadf8 \ucc28\uc774\uac00 \uc5c6\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ubbf8\uc220\uad00\uc758 \uacf5\uc2dd \uae00\uc5d0 \ub530\ub974\uba74 \ubbf8\ub77c\uc640 \uad00\uc740 \ub2e4\ub978 \uc8fc\uc758 \ubc15\ubb3c\uad00\uc5d0 50\ub144 \ub118\uac8c \ub300\uc5ec\ub418\uc5b4 \uc788\uc5c8\ub2e4. \uc5f0\uad6c\uc640 \uc804\uc2dc\ub97c \uc704\ud574 \ub2e4\uc2dc \uac00\uc838\uc624\ub824\uba74\uc11c \uc6b4\uc1a1 \ubb38\uc81c\ub97c \uac80\ud1a0\ud558\uac8c \ub41c \uac83\uc774\ub2e4. \uba40\ub9ac\uc11c \ubcf4\uba74 \ubc15\ubb3c\uad00 \uc18c\uc7a5\ud488\uc740 \ub298 \uac19\uc740 \uc790\ub9ac\uc5d0 \uc788\uc744 \uac83 \uac19\uc9c0\ub9cc \uc2e4\uc81c\ub85c\ub294 \ub300\uc5ec\uc640 \ubc18\ud658, \uc5f0\uad6c\ub97c \uc704\ud574 \uc6c0\uc9c1\uc778\ub2e4. \uc804\uc2dc\uc7a5\uc5d0\uc11c \uc6b0\ub9ac\uac00 \ubcf4\ub294 \ud55c \uc810\uc5d0\ub3c4 \ub2e4\ub978 \uae30\uad00\uc5d0\uc11c \uc9c0\ub0b8 \uae34 \uc2dc\uac04\uc774 \ub4e4\uc5b4 \uc788\uc744 \uc218 \uc788\ub2e4. \ubbf8\uc220\uad00 \ubc95\ub960\ud300\uc740 \uad00\ub828 \uaddc\uc815\uacfc \ub2e4\ub978 \ubc15\ubb3c\uad00\uc758 \uc0ac\ub840\ub97c \uac80\ud1a0\ud588\ub2e4. \uc774 \uc0ac\ub840\uc5d0\uc11c\ub294 \uc6b4\uc1a1\uc5d0 \ubc95\uc801\uc778 \uc7a5\uc560\uac00 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4\ub294 \ud310\ub2e8\uc744 \ub0b4\ub838\ub2e4\uace0 \uae00\uc740 \uc124\uba85\ud55c\ub2e4. \ubaa8\ub4e0 \ub098\ub77c\uc640 \ubaa8\ub4e0 \ubbf8\ub77c\uc5d0 \uadf8\ub300\ub85c \uc801\uc6a9\ub418\ub294 \uc548\ub0b4\ub294 \uc544\ub2c8\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \uc62e\uae38 \uc218 \uc788\uaca0\uc9c0 \ud558\uace0 \ubc14\ub85c \uc0c1\uc790\uc5d0 \ub123\uc9c0 \uc54a\uc558\ub2e4\ub294 \uc810\uc774\ub2e4. \ubb3c\uac74\uc758 \uc7ac\ub8cc\uc640 \uc0c1\ud0dc\ub97c \ud655\uc778\ud558\ub294 \uc77c\ucc98\ub7fc, \uadf8\uac83\uc744 \uc5b4\ub5a4 \ub300\uc0c1\uc73c\ub85c \ub2e4\ub8e8\uc5b4\uc57c \ud558\ub294\uc9c0 \ubb3b\ub294 \uacfc\uc815\ub3c4 \uc774\ub3d9 \uc900\ube44\uc5d0 \ub4e4\uc5b4 \uc788\uc5c8\ub2e4. \ubbf8\ub77c\uc640 \uad00\uc740 \ud568\uaed8 \uc804\uc2dc\ub418\ub354\ub77c\ub3c4 \uc131\uaca9\uc774 \uac19\uc740 \ub300\uc0c1\ub9cc\uc740 \uc544\ub2c8\ub2e4. \uad00\uc740 \uc0ac\ub78c\uc774 \uc81c\uc791\ud55c \ubb3c\uac74\uc774\uace0 \ubbf8\ub77c\ub294 \ud55c\ub54c \uc0b4\uc544 \uc788\ub358 \uc0ac\ub78c\uc758 \uc720\ud574\ub2e4. \uc62e\uae30\ub294 \uc808\ucc28\ub97c \uc0dd\uac01\ud560 \ub54c \ubcf4\uc874 \uc0c1\ud0dc\uc640 \uc18c\uc720 \uae30\ub85d\ubfd0 \uc544\ub2c8\ub77c \uc778\uac04\uc758 \ubab8\uc744 \uc5b4\ub5bb\uac8c \ub2e4\ub8f0\uc9c0\ub3c4 \ubb38\uc81c\uac00 \ub41c\ub2e4. \ubc15\ubb3c\uad00\uc758 \ubb3c\uac74\uc774\ub77c\ub294 \ud55c \ubb38\uc7a5\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uc9c8\ubb38\uc774 \ub05d\ub098\uc9c0 \uc54a\ub294 \uc774\uc720\ub2e4. \uc774\uac83\uc740 \ubbf8\uc220\uad00\uc774 \uc18c\uc7a5\ud55c \ubaa8\ub4e0 \uc790\ub8cc\uc5d0 \ub611\uac19\uc740 \ub2f5\uc744 \uc801\uc6a9\ud558\uc790\ub294 \ub9d0\uc774 \uc544\ub2c8\ub2e4. \uac01 \ub300\uc0c1\uc758 \uc131\uaca9\uacfc \uad00\ub828 \uaddc\uc815\uc744 \uc0b4\ud3b4\uc57c \ud55c\ub2e4\ub294 \ub73b\uc774\ub2e4. \uacf5\uc2dd \uae00\uc774 \ubc95\ub960\ud300\uc758 \uac80\ud1a0 \uacfc\uc815\uc744 \uc18c\uac1c\ud55c\ub2e4\ub294 \uc810\uc740 \uc774\ub7f0 \ucc28\uc774\ub97c \ubcf4\uc5ec \uc900\ub2e4. \uc804\uc2dc\uc7a5\uc5d0\uc11c\ub294 \ubcf4\uc774\uc9c0 \uc54a\ub294 \ubd84\ub958\uc640 \ucc45\uc784\uc758 \ubb38\uc81c\uac00 \uc774\ub3d9\uc744 \uc900\ube44\ud558\ub294 \ub2e8\uacc4\uc5d0\uc11c \ub4dc\ub7ec\ub0a0 \uc218 \uc788\ub2e4. 50\ub144 \ub118\uac8c \ub2e4\ub978 \uae30\uad00\uc5d0 \uc788\uc5c8\ub2e4\uba74 \ubc29\ubb38\uc790\uc758 \uae30\uc5b5 \uc18d\uc5d0\uc11c\ub294 \uadf8\uacf3\uc758 \ub300\ud45c \uc804\uc2dc\ubb3c\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218\ub3c4 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc624\ub7ab\ub3d9\uc548 \uc804\uc2dc\ud588\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc18c\uc7a5\uc758 \ubc95\uc801 \uad00\uacc4\ub294 \uac19\uc740 \uac83\uc774 \uc544\ub2c8\ub2e4. \ub300\uc5ec\uc640 \ubc18\ud658\uc774\ub77c\ub294 \ub9d0\uc740 \uc791\ud488\uc758 \ubb3c\ub9ac\uc801 \uc704\uce58\uc640 \uad00\ub9ac\uc758 \uad00\uacc4\ub97c \uad6c\ubd84\ud558\uac8c \ud55c\ub2e4. \uc5b4\ub514\uc5d0 \ubcf4\uc600\ub294\uc9c0\uc640 \ub204\uad6c\uc5d0\uac8c \uc18d\ud588\ub294\uc9c0\ub97c \ud568\uaed8 \uc77d\uc5b4\uc57c \ud55c\ub2e4. \uadf8\ub798\uc11c \ubc18\ud658\uc740 \ub2e8\uc21c\ud788 \ubb3c\uac74 \ud558\ub098\ub97c \ucc3d\uace0\uc5d0\uc11c \uaebc\ub0b4\ub294 \uc77c\uacfc \ub2e4\ub974\ub2e4. \ube4c\ub824 \ub454 \uae30\uad00\uc758 \uc804\uc2dc\uc640 \uc6d0\ub798 \uc18c\uc7a5 \uae30\uad00\uc758 \uc5f0\uad6c \uacc4\ud68d\uc774 \ud568\uaed8 \uc601\ud5a5\uc744 \ubc1b\uc744 \uc218 \uc788\ub2e4. \uc774 \uc0ac\ub840\uc5d0\uc11c \ubcf5\uc81c\ud488 \uc81c\uc791\uc5d0 \ud569\uc758\ud55c \uc77c\ub3c4 \uadf8\ub7f0 \uc870\uc815\uc758 \ud55c \ubd80\ubd84\uc73c\ub85c \ubcfc \uc218 \uc788\ub2e4. \uc774\ub3d9\uc758 \uc5ed\uc0ac\uc5d0\ub294 \uc6b4\uc1a1\uc218\ub2e8\ubfd0 \uc544\ub2c8\ub77c \uc5ec\ub7ec \uae30\uad00\uc758 \ub300\ud654\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \uae30\uad00\uc758 \ubc95\ub960\uc801 \ud310\ub2e8\uc740 \uc774 \uad6c\uccb4\uc801\uc778 \uc774\ub3d9\uc5d0 \ubc95\uc801 \uc7a5\uc560\uac00 \uc788\ub294\uc9c0\uc5d0 \uad00\ud55c \uac83\uc774\uc5c8\ub2e4. \uadf8 \ud310\ub2e8\uc774 \uace7 \ud3ec\uc7a5\uacfc \uc6b4\uc1a1\uc758 \ubaa8\ub4e0 \ubcf4\uc874 \ubb38\uc81c\ub97c \ud574\uacb0\ud588\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ud55c \uc77c\uc744 \ud560 \uc218 \uc788\ub294\uc9c0\uc640 \uc5b4\ub5bb\uac8c \ud574\uc57c \uc548\uc804\ud55c\uc9c0\ub294 \uc11c\ub85c \ub2e4\ub978 \uc804\ubb38\uc131\uc744 \uc694\uad6c\ud560 \uc218 \uc788\ub2e4. \ubbf8\uc220\uad00\uc758 \uc77c\uc740 \uc774 \uc870\uac74\ub4e4\uc744 \uc774\uc5b4 \uacb0\uc815\ud558\ub294 \uacfc\uc815\uc774\uae30\ub3c4 \ud558\ub2e4. \ub530\ub77c\uc11c \ud2b9\uc815 \uc0ac\ub840\uc758 \uacb0\uacfc\ub97c \ubaa8\ub4e0 \ub098\ub77c\uc758 \uc720\ud574 \uc6b4\uc1a1 \uc548\ub0b4\ub85c \uc0ac\uc6a9\ud560 \uc218 \uc5c6\ub2e4. \ubc95\uacfc \uc81c\ub3c4\ub294 \uc7a5\uc18c\uc640 \ub300\uc0c1\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c0\uace0 \uc2dc\uc810\uc758 \uc601\ud5a5\ub3c4 \ubc1b\ub294\ub2e4. \uc774 \uae00\uc5d0\uc11c \ud765\ubbf8\ub85c\uc6b4 \uac83\uc740 \uc5b4\ub5a4 \uc870\ubb38\uc744 \uc678\uc6b0\ub294 \ub370\ubcf4\ub2e4 \uc608\uc0c1\ubcf4\ub2e4 \ub9ce\uc740 \uc0ac\ub78c\uc774 \ud558\ub098\uc758 \uc774\uc0ac\ub97c \uac80\ud1a0\ud55c\ub2e4\ub294 \uc0ac\uc2e4\uc774\ub2e4. \ubb3c\uac74\uc758 \ud2b9\uc131\uc774 \ub2e4\ub978 \uc9c8\ubb38\uc744 \ubd88\ub7ec\uc628 \uac83\uc774\ub2e4. \uacf5\uc2dd \uae00\uc740 \ubc18\ud658 \ub4a4 \uc5f0\uad6c\ub97c \ud1b5\ud574 \uc774 \uc0ac\ub78c\uc744 \ub354 \uc798 \uc774\ud574\ud558\ub824\ub294 \uacc4\ud68d\ub3c4 \uc5b8\uae09\ud55c\ub2e4. \uc774\ub984\uacfc \ub098\uc774, \uc0b4\uc544 \uc788\ub358 \ud658\uacbd\uc744 \uc54c\uc544\ubcf4\ub824\ub294 \uc9c8\ubb38\uc740 \uc804\uc2dc\uc7a5\uc5d0\uc11c \uac89\ubaa8\uc2b5\uc744 \ubcf4\ub294 \uacbd\ud5d8\uacfc \ub2e4\ub974\ub2e4. \ub2e4\ub9cc \uc5f0\uad6c \uacc4\ud68d\uc774 \uc788\uc5c8\ub2e4\ub294 \ub9d0\uacfc \uadf8 \uacb0\uacfc\uac00 \uc774\ubbf8 \ubaa8\ub450 \ub098\uc654\ub2e4\ub294 \ub9d0\uc740 \ub098\ub204\uc5b4\uc57c \ud55c\ub2e4. \uc774 \uc6d0\uace0\ub294 \ud655\uc778\ud558\uc9c0 \uc54a\uc740 \uc0c8 \ubc1c\uacac\uc744 \ub367\ubd99\uc774\uc9c0 \uc54a\ub294\ub2e4. \ubcf5\uc81c\ud488\uc740 \ubcfc \uae30\ud68c\ub97c \uc774\uc5b4 \uc8fc\uc9c0\ub9cc \uc6d0\ubcf8\uc758 \ubaa8\ub4e0 \uc815\ubcf4\ub97c \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc7ac\ub8cc\uc640 \ubcf4\uc874, \uc5f0\uad6c\uac00 \uc694\uad6c\ud558\ub294 \uc790\ub8cc\ub294 \ub2e4\ub97c \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \ubb34\uc5c7\uc744 \ub0a8\uaca8 \ubcf4\uc5ec \uc8fc\uace0 \ubb34\uc5c7\uc744 \uc62e\uaca8 \uc870\uc0ac\ud560\uc9c0 \uc120\ud0dd\ud558\ub294 \uc77c\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4. \ubbf8\ub77c\uc758 \uc774\uc0ac\ub77c\ub294 \ub73b\ubc16\uc758 \uc81c\ubaa9 \ub4a4\uc5d0\uc11c \ubc15\ubb3c\uad00\uc774 \uacfc\uac70\uc758 \uc0ac\ub78c\uc744 \ub300\ud558\ub294 \uc5ec\ub7ec \ucc45\uc784\uc744 \uc77d\uac8c \ub41c\ub2e4. \ubc18\ud658 \uacfc\uc815\uc5d0\uc11c\ub294 \ube4c\ub824 \uac04 \ubc15\ubb3c\uad00\uc774 \ubbf8\ub77c\uc640 \uad00\uc758 \ubcf5\uc81c\ud488\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub3c4\ub85d \ud569\uc758\ub3c4 \ud588\ub2e4. \ud55c\ucabd\uc5d0\uc11c\ub294 \uc5f0\uad6c\ud560 \uc6d0\ub798 \uc790\ub8cc\ub97c \ub3cc\ub824\ubc1b\uace0, \ub2e4\ub978 \ucabd\uc5d0\uc11c\ub294 \ubcf5\uc81c\ud488\uc744 \ub0a8\uae30\ub294 \ubc29\uc2dd\uc774\uc5c8\ub2e4. \uacf5\uc2dd \uae00\uc740 \ub3cc\uc544\uc628 \ub4a4\uc758 \uc5f0\uad6c\uac00 \uae30\uc874 \uc2e0\uc6d0 \uc774\ud574\uc5d0\ub3c4 \uc9c8\ubb38\uc744 \ub358\uc84c\ub2e4\uace0 \ub367\ubd99\uc778\ub2e4. \uc804\uc2dc\ud488 \uc124\uba85\uc740 \uc601\uc6d0\ud788 \uace0\uc815\ub41c \uc815\ub2f5\uc774 \uc544\ub2d0 \uc218 \uc788\ub294 \uac83\uc774\ub2e4. \ubbf8\ub77c\uc758 \uc774\uc0ac\ub294 \uc0c1\uc790 \ud558\ub098\ub97c \uc62e\uae30\ub294 \uc77c\uc744 \ub118\uc5b4, \ud55c \uc0ac\ub78c\uc758 \ud754\uc801\uc744 \uc5b4\ub5bb\uac8c \ubcf4\uad00\ud558\uace0 \uc774\ud574\ud560\uc9c0 \ub2e4\uc2dc \ubb3b\ub294 \uc77c\uc774\uc5c8\ub2e4."}, {"id": "newton-mint-work", "title": "\ub274\ud134\uc758 \ub610 \ub2e4\ub978 \uc77c\ud130\ub294 \uc870\ud3d0\uad6d\uc774\uc5c8\ub2e4", "summary": "\uacfc\ud559\uc790\uc758 \uc774\ub984 \uc606\uc5d0 \uc870\ud3d0\uad6d\uc774\ub77c\ub294 \uc9c1\uc7a5\uc774 \ubd99\uc2b5\ub2c8\ub2e4. \ub274\ud134\uc740 \uadf8\uacf3\uc5d0\uc11c \ubb34\uc2a8 \uc77c\uc744 \ud588\uc744\uae4c\uc694?", "category": "history", "category_title": "History", "subcategory": "Europe", "url": "stories/newton-mint-work/index.html", "image": "media/newton-mint-work.jpg", "alt": "\uae43\ud39c\uacfc \ube48 \uc7a5\ubd80, \uc740\ube5b \ub3d9\uc804, \uc791\uc740 \ud504\ub9ac\uc998\uc774 \ub193\uc778 \ucc45\uc0c1\uc758 \uc124\uba85\uc6a9 AI \uc0bd\ud654", "text": "\ub274\ud134\uc758 \ub610 \ub2e4\ub978 \uc77c\ud130\ub294 \uc870\ud3d0\uad6d\uc774\uc5c8\ub2e4 \ub3d9\uc804\uc758 \ubb34\uac8c\ub97c \uc0b4\ud53c\ub358 \uacfc\ud559\uc790\uc758 \uc77c\uc0c1 \uacfc\ud559\uc790\uc758 \uc774\ub984 \uc606\uc5d0 \uc870\ud3d0\uad6d\uc774\ub77c\ub294 \uc9c1\uc7a5\uc774 \ubd99\uc2b5\ub2c8\ub2e4. \ub274\ud134\uc740 \uadf8\uacf3\uc5d0\uc11c \ubb34\uc2a8 \uc77c\uc744 \ud588\uc744\uae4c\uc694? Europe \uc5ed\uc0ac \ub274\ud134\uc774\ub77c\ub294 \uc774\ub984\uc744 \ub4e4\uc73c\uba74 \uacfc\ud559\ucc45\uc758 \ucd08\uc0c1\ud654\ubd80\ud130 \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \uadf8\ub7f0\ub370 \uadf8\uc758 \uc774\ub825\uc5d0\ub294 \uc870\uae08 \ub2e4\ub978 \uc7a5\uc18c\ub3c4 \ub098\uc628\ub2e4. \uae08\uc18d\uc744 \ub179\uc774\uace0 \ub3d9\uc804\uc744 \ub9cc\ub4dc\ub294 \uc655\ub9bd\uc870\ud3d0\uad6d\uc774\ub2e4. \uc11c\ub958\uc5d0 \uc11c\uba85\ub9cc \ud558\ub7ec \uac00\ub054 \ub4e4\ub978 \uba85\uc608\uc9c1\uc774\uc5c8\uc744\uae4c. \uc601\uad6d \uc655\ub9bd\uc870\ud3d0\uad6d\uc758 \uc124\uba85\uc744 \uc77d\uc73c\uba74 \uaf64 \ubc14\uc05c \uc9c1\uc7a5\uc774\uc5c8\uc74c\uc744 \uc54c \uc218 \uc788\ub2e4. \ub274\ud134\uc740 1696\ub144 \uadf8\uacf3\uc5d0\uc11c \uc77c\uc744 \uc2dc\uc791\ud588\uace0, \ub3d9\uc804\uc758 \ubb34\uac8c\uc640 \ud488\uc9c8\uc744 \ud655\uc778\ud558\ub294 \ubb38\uc81c\uc5d0 \uae4a\uc774 \uad00\uc5ec\ud588\ub2e4. \uc2e4\ud5d8\uc2e4\uc744 \ub5a0\ub09c \ub4a4\uc5d0\ub3c4 \uc815\ud655\ud558\uac8c \uc7ac\uace0 \ud655\uc778\ud558\ub294 \uc77c\uc774 \uadf8\ub97c \uae30\ub2e4\ub838\ub358 \uc148\uc774\ub2e4. \ub274\ud134\uc774 \uc870\ud3d0\uad6d\uc5d0 \ub4e4\uc5b4\uac14\uc744 \ubb34\ub835\uc5d0\ub294 \uc624\ub798\ub41c \uc740\ud654\ub97c \uc0c8\ub85c \ub9cc\ub4dc\ub294 \ud070 \uc791\uc5c5\uc774 \uc9c4\ud589\ub418\uace0 \uc788\uc5c8\ub2e4. \uc5ec\ub7ec \uc9c0\uc5ed\uc5d0 \ubcf4\uc870 \uc870\ud3d0 \uc2dc\uc124\uae4c\uc9c0 \ub9c8\ub828\ud560 \ub9cc\ud07c \uaddc\ubaa8\uac00 \ucef8\ub2e4. \uc0c8\ub85c\uc6b4 \uc9c1\uc7a5\uc5d0 \uc801\uc751\ud560 \uc2dc\uac04\ubd80\ud130 \ub109\ub109\ud558\uac8c \uc8fc\uc5b4\uc9c4 \uc0c1\ud669\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc655\ub9bd\uc870\ud3d0\uad6d\uc740 \uc774 \uc791\uc5c5\uc774 \uc57d 3\ub144 \uc548\uc5d0 \ub9c8\ubb34\ub9ac\ub418\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub274\ud134 \ud63c\uc790\uc11c \ubaa8\ub4e0 \uc77c\uc744 \ud574\ub0c8\ub2e4\ub294 \uc774\uc57c\uae30\ub294 \uc544\ub2c8\ub2e4. \uc218\ub9ce\uc740 \uc0ac\ub78c\uacfc \uc2dc\uc124\uc774 \uc6c0\uc9c1\uc774\ub294 \uc870\uc9c1 \uc548\uc5d0\uc11c \uadf8\ub3c4 \uc77c\uc744 \ub9e1\uc558\ub2e4. \uc774\ud6c4\uc5d0\ub294 \ub3d9\uc804\uc744 \uc704\uc870\ud558\uac70\ub098 \ud6fc\uc190\ud55c \uc0ac\ub78c\ub4e4\uc744 \uc870\uc0ac\ud558\ub294 \uc77c\uc5d0\ub3c4 \uad00\uc5ec\ud588\ub2e4. \ubc94\uc8c4\uc790\uc640 \uc81c\ubcf4\uc790\ub97c \uc9c1\uc811 \ub9cc\ub098 \uc870\uc0ac\ud55c \uae30\ub85d\ub3c4 \uc18c\uac1c\ub41c\ub2e4. \uc6b0\ub9ac\uac00 \uc775\uc219\ud558\uac8c \ub5a0\uc62c\ub9ac\ub294 \uacfc\ud559\uc790\uc758 \ubaa8\uc2b5\uc5d0 \uc11c\ub958\uc640 \uba74\ub2f4 \uc77c\uc815\uc774 \ub354\ud574\uc9c4\ub2e4. \uadf8\ub807\ub2e4\uace0 \uac70\ub9ac\uc5d0\uc11c \ubc94\uc778\uc744 \ucad3\ub294 \uc7a5\uba74\uae4c\uc9c0 \uc0c1\uc0c1\ud574 \ub123\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc2e4\uc81c\ub85c \ud655\uc778\ub418\ub294 \uc5c5\ubb34\ub9cc\uc73c\ub85c\ub3c4 \uadf8\uc758 \uc870\ud3d0\uad6d \uc0dd\ud65c\uc740 \ucda9\ubd84\ud788 \ubd84\uc8fc\ud574 \ubcf4\uc778\ub2e4. \uc870\ud3d0\uad6d\uc5d0\uc11c \uc911\uc694\ud55c \uac83\uc740 \ub3d9\uc804\uc5d0 \uc608\uc05c \uadf8\ub9bc\uc744 \ucc0d\ub294 \uc77c\ub9cc\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc815\ud574\uc9c4 \ubb34\uac8c\uc640 \uae08\uc18d\uc758 \uc21c\ub3c4\ub97c \ub9de\ucd94\uace0, \ub3d9\uc804\ub07c\ub9ac\uc758 \ucc28\uc774\ub97c \uc904\uc774\ub294 \uac83\ub3c4 \ud544\uc694\ud588\ub2e4. \uc655\ub9bd\uc870\ud3d0\uad6d\uc740 \ub274\ud134\uc758 \uae30\uc5ec \uac00\uc6b4\ub370 \ud558\ub098\ub85c \uc774\ub7f0 \uc815\ud655\uc131\uc5d0 \ub300\ud55c \uad00\uc2ec\uc744 \ub4e0\ub2e4. \uc190\uc5d0 \uc950\ub294 \uc791\uc740 \ub3d9\uc804\uc774\ub77c\ub3c4, \uc5ec\ub7ec \uac1c\uac00 \uc11c\ub85c \ub2e4\ub974\uac8c \ub9cc\ub4e4\uc5b4\uc9c0\uba74 \ub3c8\uc744 \uc0ac\uc6a9\ud558\ub294 \uc0ac\ub78c\ub4e4\uc5d0\uac8c \ubb38\uc81c\uac00 \ub420 \uc218 \uc788\uc5c8\ub2e4. \ub204\uad70\uac00\uc5d0\uac8c\ub294 \uc11c\ub958 \uc18d \uc791\uc740 \uc218\uce58\uc600\uaca0\uc9c0\ub9cc, \uc2e4\uc81c\ub85c\ub294 \uc7ac\ub8cc\uc640 \uc81c\uc791 \uacfc\uc815, \uac80\uc0ac\ub97c \uc5f0\uacb0\ud558\ub294 \ubb38\uc81c\uc600\ub2e4. \ucc45\uc0c1 \uc704\uc5d0\uc11c \uacc4\uc0b0\ud55c \uae30\uc900\uc774 \uc791\uc5c5\uc7a5\uc758 \uae08\uc18d\uc73c\ub85c \uc774\uc5b4\uc838\uc57c \ud588\ub2e4. \uadf8\uc758 \uc774\ub984\uc774 \ubd99\uc5c8\ub2e4\uace0 \ud574\uc11c \uc870\ud3d0\uad6d\uc758 \ubaa8\ub4e0 \uc81c\ub3c4\uac00 \ub2e8\ubc88\uc5d0 \ubc14\ub010 \uac83\uc740 \uc544\ub2c8\ub2e4. \uacf5\uc2dd \uc124\uba85\ub3c4 \ud070 \uc870\uc9c1 \uac1c\ud601\uacfc \uadf8\uac00 \uae30\uc6b8\uc778 \uad00\ub9ac\uc758 \ub178\ub825\uc744 \uad6c\ubd84\ud55c\ub2e4. \uc720\uba85\ud55c \uc778\ubb3c\uc758 \uc774\ub825\uc774\ub77c\uace0 \ubaa8\ub4e0 \uc77c\uc744 \uadf9\uc801\uc778 \ud601\uba85\uc73c\ub85c \ub9cc\ub4e4 \ud544\uc694\ub294 \uc5c6\ub2e4. \uacfc\ud559\uc0ac\uc5d0\uc11c \uc720\uba85\ud55c \uc0ac\ub78c\uc774\ub77c\ub3c4 \uc2e4\uc81c \uc9c1\uc7a5\uc5d0\uc11c\ub294 \ub9e1\uc740 \uc5ed\ud560\uacfc \uc870\uc9c1\uc758 \uc870\uac74\uc774 \uc788\ub2e4. \ub274\ud134\uc774 \uc870\ud3d0\uad6d\uc5d0\uc11c \ud55c \uc77c\uc744 \uc774\ub984\uc758 \uc704\ub300\ud568\uc73c\ub85c\ub9cc \uc124\uba85\ud558\uba74 \uc8fc\ubcc0\uc758 \ub178\ub3d9\uacfc \uc81c\ub3c4\uac00 \uc0ac\ub77c\uc9c4\ub2e4. \uc7ac\uc8fc\uc870\ub294 \ub9ce\uc740 \uc0ac\ub78c\uc774 \uc7ac\ub8cc\uc640 \uc7a5\ube44, \uae30\ub85d\uc744 \ub2e4\ub8e8\ub294 \ud070 \uc77c\uc774\uc5c8\ub2e4. \ub274\ud134\uc758 \uae30\uc5ec\ub97c \uc774\ud574\ud558\ub824\uba74 \uadf8\uac00 \ubb34\uc5c7\uc744 \ub9e1\uc558\ub294\uc9c0\ubd80\ud130 \uad6c\uccb4\uc801\uc73c\ub85c \ubcf4\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uacfc\ud559\uc758 \ubc1c\uacac\uacfc \ud589\uc815\uc758 \uc131\uacfc\uac00 \uc5b8\uc81c\ub098 \uac19\uc740 \ubaa8\uc2b5\uc73c\ub85c \ub098\ud0c0\ub098\ub294 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \uc2e4\ud5d8\uacfc \uacc4\uc0b0\uc5d0 \uc775\uc219\ud55c \ud0dc\ub3c4\uac00 \uc815\ud655\uc131\uc744 \uc911\uc2dc\ud558\ub294 \uc77c\uacfc \uc5f0\uacb0\ub420 \uc218 \uc788\uc9c0\ub9cc \ubaa8\ub4e0 \uad00\ub9ac\uc758 \uacb0\uc815\uc744 \uacfc\ud559 \ubc95\uce59\uc758 \uc801\uc6a9\uc774\ub77c\uace0 \ub2e8\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uacf5\uc2dd \uc124\uba85\uc774 \ud655\uc778\ud574 \uc8fc\ub294 \uc5c5\ubb34\ub97c \ub530\ub77c\uac00\uba74 \uacfc\uc7a5\ud558\uc9c0 \uc54a\uace0\ub3c4 \ub113\uc740 \uc0dd\uc560\uc758 \ud55c \ubd80\ubd84\uc744 \ub9cc\ub0a0 \uc218 \uc788\ub2e4. \ud55c \ub3d9\uc804\uc758 \ubb34\uac8c \ucc28\uc774\ub294 \uc791\uc544 \ubcf4\uc77c \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \ub9ce\uc740 \ub3d9\uc804\uc774 \ub9cc\ub4e4\uc5b4\uc9c0\uace0 \uc11c\ub85c \uad50\ud658\ub41c\ub2e4\uba74 \uc77c\uc815\ud55c \uae30\uc900\uc744 \uc720\uc9c0\ud558\ub294 \uc77c\uc774 \uc911\uc694\ud574\uc9c4\ub2e4. \uae08\uc18d\uc758 \uc21c\ub3c4\uc640 \ubb34\uac8c\ub294 \ub2e4\ub978 \ud56d\ubaa9\uc774\uc9c0\ub9cc \ud568\uaed8 \uad00\ub9ac\ud574\uc57c \ud560 \uc218 \uc788\ub2e4. \uc870\ud3d0\ub294 \ub208\uc5d0 \ub744\ub294 \ubb38\uc591\uacfc \ub35c \ubcf4\uc774\ub294 \uc218\uce58\ub97c \uac19\uc740 \ubb3c\uac74\uc5d0 \ub9de\ucd94\ub294 \uc791\uc5c5\uc774\uc5c8\ub2e4. \uc815\ud655\uc131\uc744 \uc694\uad6c\ud55c\ub2e4\ub294 \ub9d0\ub3c4 \uae30\uc900\ub9cc \uc885\uc774\uc5d0 \uc801\ub294 \uac83\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \uc7ac\ub8cc\ub97c \ub9c8\ub828\ud558\uace0 \ub9cc\ub4dc\ub294 \uacfc\uc815\uc5d0\uc11c \uadf8 \uae30\uc900\uc744 \uc9c0\ud0a4\ub294\uc9c0 \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \uc0ac\ub78c\uc758 \uc190\uc5d0\uc11c \ub098\uc628 \ubb3c\uac74\uc774 \ub2e4\uc74c \uc0ac\ub78c\uc5d0\uac8c \uac19\uc740 \ud654\ud3d0\ub85c \ubc1b\uc544\ub4e4\uc5ec\uc9c0\ub824\uba74 \ubc18\ubcf5 \uac00\ub2a5\ud55c \ud488\uc9c8\uc774 \ud544\uc694\ud558\ub2e4. \uc870\ud3d0\uad6d\uc758 \uc5c5\ubb34\ub294 \ucd94\uc0c1\uc801\uc778 \uc22b\uc790\uc640 \uc190\uc5d0 \uc950\ub294 \uae08\uc18d\uc744 \uc774\uc5b4 \uc8fc\ub294 \uc790\ub9ac\uc600\ub2e4. \uc704\uc870\uc640 \ud6fc\uc190\uc744 \ub2e4\ub8e8\ub294 \uc5c5\ubb34\uc5d0\ub294 \uc9c4\uc220\uacfc \uc99d\uac70, \uc11c\ub85c \ub2e4\ub978 \uc815\ubcf4\uc758 \ud655\uc778\uc774 \ub4e4\uc5b4\uac04\ub2e4. \ub274\ud134\uc774 \uc81c\ubcf4\uc790\uc640 \uad00\ub828\uc790\ub97c \uc9c1\uc811 \uc870\uc0ac\ud588\ub2e4\ub294 \uc124\uba85\uc740 \uadf8\uac00 \uc774\ub984\ub9cc \uc62c\ub824 \ub454 \uc778\ubb3c\uc774 \uc544\ub2c8\uc5c8\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ub2e4\ub9cc \uc720\uba85\ud55c \ud0d0\uc815\ucc98\ub7fc \ubaa8\ub4e0 \ubc94\uc8c4\ub97c \ud63c\uc790 \ud574\uacb0\ud588\ub2e4\ub294 \uadf9\uc801\uc778 \uc774\uc57c\uae30\ub85c \ubc14\uafc0 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5f0\uad6c\uc2e4\uc5d0\uc11c\uc758 \ubaa8\uc2b5\ub9cc \uc54c\uace0 \uc788\ub358 \ub3c5\uc790\uc5d0\uac8c\ub294 \uc774\ub7f0 \uc5c5\ubb34 \uc790\uccb4\uac00 \ucda9\ubd84\ud788 \uc0c8\ub85c\uc6b4 \uc7a5\uba74\uc774\ub2e4. \uc138\uc0c1\uacfc \ub5a8\uc5b4\uc838 \uc0dd\uac01\ub9cc \ud55c \uc0ac\ub78c\uc774 \uc544\ub2c8\ub77c \uc81c\ub3c4\uc758 \uc2e4\ubb34\ub97c \ub9e1\uace0 \ub2e4\ub978 \uc0ac\ub78c\uc758 \ub9d0\uacfc \uae30\ub85d\uc744 \ub2e4\ub8e8\uc5c8\ub2e4. \uc778\ubb3c\uc758 \uc0b6\uc744 \ud558\ub098\uc758 \ub300\ud45c \uc5c5\uc801\uc73c\ub85c\ub9cc \uc555\ucd95\ud558\uc9c0 \uc54a\uc744 \ub54c, \uc775\uc219\ud55c \uc774\ub984\uc5d0\uc11c\ub3c4 \uc544\uc9c1 \uc77d\uc744 \ubd80\ubd84\uc774 \ub0a8\uc544 \uc788\ub2e4. \ub274\ud134\uc740 1699\ub144\ubd80\ud130 \uc870\ud3d0\uad6d\uc758 \ub2e4\ub978 \uad00\ub9ac\uc9c1\uc744 \ub9e1\uc558\uace0, 1727\ub144 \uc138\uc0c1\uc744 \ub5a0\ub0a0 \ub54c\uae4c\uc9c0 \uadf8\uacf3\uacfc \uad00\uacc4\ub97c \uc774\uc5b4 \uac14\ub2e4. \uc7a0\uae50\uc758 \uc678\ub3c4\uac00 \uc544\ub2c8\ub77c \uc0dd\uc560\uc758 \uae34 \ubd80\ubd84\uc774\uc5c8\ub2e4. \uc774 \uc0ac\uc2e4\uc744 \uc54c\uace0 \ub098\uba74 \uc704\uc778\uc758 \uc774\ub825\ub3c4 \ud55c \uac00\uc9c0 \uc9c1\ud568\uc73c\ub85c\ub9cc \uc77d\ud788\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc5f0\uad6c \uacb0\uacfc\ub97c \ub0a8\uae34 \uc0ac\ub78c\uc5d0\uac8c\ub3c4 \uc870\uc9c1 \uc548\uc5d0\uc11c \ucc98\ub9ac\ud574\uc57c \ud560 \uc77c\uacfc \ud655\uc778\ud574\uc57c \ud560 \ubb38\uc11c\uac00 \uc788\uc5c8\ub2e4. \ub2e4\uc74c\uc5d0 \ub3d9\uc804\uc744 \uc190\uc5d0 \uc954\ub2e4\uace0 \ub274\ud134\uc744 \uaf2d \ub5a0\uc62c\ub9b4 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \uacfc\ud559\ucc45\uc758 \ucd08\uc0c1\ud654 \uc606\uc5d0 \ub3d9\uc804\uc758 \ubb34\uac8c\uc640 \uc21c\ub3c4\ub97c \uc0b4\ud53c\ub358 \ub610 \ub2e4\ub978 \uc9c1\uc7a5\uc778\uc758 \ubaa8\uc2b5\ub3c4 \ub193\uc544 \ubcfc \uc218\ub294 \uc788\uaca0\ub2e4. \uc791\uc740 \ub3c8 \ud55c \uac1c\ub97c \uc815\ud655\ud558\uac8c \ub9cc\ub4dc\ub294 \uc77c\ub3c4 \uadf8\uc758 \uc624\ub79c \uc77c\uc0c1\uc774\uc5c8\ub2e4."}, {"id": "nightingale-air-and-observation", "title": "\ub098\uc774\ud305\uac8c\uc77c \u2014 \ub4f1\ubd88\ubcf4\ub2e4 \uba3c\uc800 \ubcd1\uc2e4\uc758 \uacf5\uae30\ub97c \ubcf4\ub2e4", "summary": "Notes on Nursing\uc5d0\uc11c \ubcd1\uc2e4\uc758 \ud658\uacbd\uacfc \ud658\uc790\uc758 \uc791\uc740 \ubcc0\ud654\ub97c \uc0b4\ud53c\ub294 \ud0dc\ub3c4\ub97c \uc5ed\uc0ac\uc801 \ub9e5\ub77d\uc73c\ub85c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history", "category_title": "History", "subcategory": "Europe", "url": "stories/nightingale-air-and-observation/index.html", "image": "media/nightingale-air-and-observation.png", "alt": "\ub0ae\ube5b\uc774 \ub4dc\ub294 19\uc138\uae30\ud48d \ubcd1\uc2e4\uc5d0\uc11c \uc131\uc778 \ud658\uc790 \uacc1\uc758 \ub3cc\ubcf4\ub294 \uc0ac\ub78c\uc774 \uc218\ucca9\uc744 \ub4e4\uace0 \uc11c \uc788\ub294 \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\ub098\uc774\ud305\uac8c\uc77c \u2014 \ub4f1\ubd88\ubcf4\ub2e4 \uba3c\uc800 \ubcd1\uc2e4\uc758 \uacf5\uae30\ub97c \ubcf4\ub2e4 \uac04\ud638\uc5d0 \uad00\ud55c \uc624\ub798\ub41c \ucc45\uc774 \uc8fc\ubaa9\ud55c \ube5b\uacfc \uc18c\ub9ac, \uad00\ucc30 Notes on Nursing\uc5d0\uc11c \ubcd1\uc2e4\uc758 \ud658\uacbd\uacfc \ud658\uc790\uc758 \uc791\uc740 \ubcc0\ud654\ub97c \uc0b4\ud53c\ub294 \ud0dc\ub3c4\ub97c \uc5ed\uc0ac\uc801 \ub9e5\ub77d\uc73c\ub85c \uc77d\uc2b5\ub2c8\ub2e4. Europe \uc5ed\uc0ac \ub098\uc774\ud305\uac8c\uc77c\uc744 \ub5a0\uc62c\ub9ac\uba74 \uc5b4\ub450\uc6b4 \ubcd1\uc2e4\uc744 \ub3cc\uba70 \ub4f1\ubd88\uc744 \ub4e0 \uc0ac\ub78c\uc774 \uc0dd\uac01\ub09c\ub2e4. \uadf8\ub7f0\ub370 \uadf8\ub140\uc758 \u300e\uac04\ud638\uc5d0 \uad00\ud55c \uae30\ub85d\u300f\uc744 \ud3bc\uce58\uba74 \uccab\uba38\ub9ac\uc5d0\uc11c \ub9cc\ub098\ub294 \uac83\uc740 \ub4f1\ubd88\ubcf4\ub2e4 \uacf5\uae30\ub2e4. \ud658\uc790\uac00 \uc228 \uc26c\ub294 \ubc29\uc758 \uc0c1\ud0dc, \ucd94\uc704\uc640 \uc18c\uc74c, \ube5b\uacfc \uc2dd\uc0ac\ucc98\ub7fc \ub108\ubb34 \uc775\uc219\ud574\uc11c \uc9c0\ub098\uce58\uae30 \uc26c\uc6b4 \uac83\ub4e4\uc774\ub2e4. 19\uc138\uae30\uc5d0 \uc4f0\uc778 \uc774 \ucc45\uc740 \uc624\ub298\uc758 \uc758\ub8cc \uc9c0\uce68\uacfc \uac19\uc9c0 \uc54a\ub2e4. \uc61b \uce58\ub8cc\ubc95\uc744 \ub530\ub77c \ud558\uae30\ubcf4\ub2e4 \uc800\uc790\uac00 \ubb34\uc5c7\uc744 \uad00\ucc30\uc758 \ub300\uc0c1\uc73c\ub85c \uc0bc\uc558\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uc601\uc6c5\uc801\uc778 \ud55c \uc7a5\uba74 \ub4a4\uc5d0 \ud3c9\ubc94\ud55c \ud658\uacbd\uc744 \ub04a\uc784\uc5c6\uc774 \uc0b4\ud53c\ub294 \uc77c\uc774 \uc788\uc5c8\ub2e4\ub294 \uc810\uc774 \ud765\ubbf8\ub86d\ub2e4. \ucc45\uc758 \ubd80\uc81c\ub294 \uac04\ud638\uac00 \ubb34\uc5c7\uc774\uba70 \ubb34\uc5c7\uc774 \uc544\ub2cc\uc9c0\ub97c \ubb3b\ub294\ub2e4. \ub098\uc774\ud305\uac8c\uc77c\uc740 \uc57d\uc744 \uc8fc\uac70\ub098 \uc758\ub8cc \ucc98\uce58\ub97c \ud558\ub294 \uc77c\ub9cc\uc73c\ub85c \ud658\uc790\ub97c \ub3cc\ubcf4\ub294 \uacbd\ud5d8 \uc804\uccb4\uac00 \uc124\uba85\ub418\uc9c0\ub294 \uc54a\ub294\ub2e4\uace0 \ubcf8\ub2e4. \uc0ac\ub78c\uc774 \uba38\ubb34\ub294 \uacf5\uac04\uacfc \ud558\ub8e8\uc758 \ud750\ub984\ub3c4 \ubab8\uc758 \uc0c1\ud0dc\uc640 \uc5f0\uacb0\ub418\uc5b4 \uc788\ub2e4\uace0 \uc0dd\uac01\ud588\ub2e4. \uc774 \uad00\uc810\uc5d0\uc11c\ub294 \ubc29\uc774 \uc870\uc6a9\ud55c\uc9c0, \uc2dd\uc0ac\ub97c \uc2e4\uc81c\ub85c \uba39\uc5c8\ub294\uc9c0, \ubc24\uc5d0 \uc81c\ub300\ub85c \uc26c\uc5c8\ub294\uc9c0 \uac19\uc740 \uc9c8\ubb38\uc774 \uc911\uc694\ud574\uc9c4\ub2e4. \uba40\ub9ac\uc11c \ubcf4\uae30\uc5d0\ub294 \uc791\uc740 \uc77c\uc774\uc9c0\ub9cc \ud658\uc790\uc5d0\uac8c\ub294 \ud558\ub8e8\uc758 \ub300\ubd80\ubd84\uc744 \ucc28\uc9c0\ud560 \uc218 \uc788\ub2e4. \uac04\ud638\ub294 \uc88b\uc740 \ub9c8\uc74c\uc744 \uac00\uc84c\ub2e4\ub294 \ub9d0\ubfd0 \uc544\ub2c8\ub77c \uad6c\uccb4\uc801\uc73c\ub85c \ubb34\uc5c7\uc744 \uc0b4\ud3c8\ub294\uc9c0\ub85c \uc124\uba85\ub418\uc5b4\uc57c \ud588\ub2e4. \ud658\uae30\uc640 \ubcf4\uc628\uc744 \ub2e4\ub8e8\ub294 \uc7a5\uc5d0\uc11c \ub098\uc774\ud305\uac8c\uc77c\uc740 \uacf5\uae30\uac00 \uc5b4\ub514\uc5d0\uc11c \ub4e4\uc5b4\uc624\ub294\uc9c0 \ubb3b\ub294\ub2e4. \ub2e4\ub978 \ubc29\uc774\ub098 \ubcf5\ub3c4\uc758 \uacf5\uae30\ub97c \ub4e4\uc774\ub294 \uac83\uacfc \ubc14\uae65\uc5d0\uc11c \ub4e4\uc5b4\uc624\ub294 \uacf5\uae30\ub97c \uad6c\ubd84\ud55c\ub2e4. \uc5f4\uc5c8\ub2e4\ub294 \ub3d9\uc791 \ud558\ub098\ubcf4\ub2e4 \uc2e4\uc81c\ub85c \uc5b4\ub5a4 \uacf5\uae30\uac00 \ud658\uc790\uc5d0\uac8c \uc624\ub294\uc9c0\uac00 \uad00\uc2ec\uc758 \ub300\uc0c1\uc774\uc5c8\ub2e4. \uc624\ub298\uc758 \ubcd1\uc2e4\uc5d0\uc11c \ucc3d\ubb38\uc744 \uc5b4\ub5bb\uac8c \ub2e4\ub8f0\uc9c0\ub294 \uc2dc\uc124\uacfc \ud658\uc790 \uc0c1\ud0dc, \uac10\uc5fc \uad00\ub9ac \uae30\uc900\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c4\ub2e4. \uc774 \ucc45\uc758 \uc138\ubd80 \ubc29\ubc95\uc744 \ud604\uc7ac\uc758 \ucc98\ubc29\uc73c\ub85c \uc62e\uae30\ub824\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5ec\uae30\uc11c \ubcfc \uc810\uc740 \uc870\uce58\ub97c \ud588\ub2e4\ub294 \ud615\uc2dd\ubcf4\ub2e4 \uadf8 \uacb0\uacfc\uac00 \uc2e4\uc81c\ub85c \ubb34\uc5c7\uc778\uc9c0 \ud655\uc778\ud558\ub824\ub294 \ud0dc\ub3c4\ub2e4. \uc800\uc790\ub294 \ud658\uae30\ub97c \ub9d0\ud558\uba74\uc11c \ud658\uc790\ub97c \ucc28\uac11\uac8c \ud574\uc11c\ub294 \uc548 \ub41c\ub2e4\ub294 \uc870\uac74\ub3c4 \ud568\uaed8 \uac15\uc870\ud55c\ub2e4. \ud55c \uac00\uc9c0 \uc88b\uc740 \ubaa9\uc801\uc744 \uc704\ud574 \ub2e4\ub978 \ud544\uc694\ub97c \uc78a\uc5b4\ubc84\ub9ac\ub294 \uc0c1\ud669\uc744 \uacbd\uacc4\ud55c \uc148\uc774\ub2e4. \ubc29\uc758 \uc0c1\ud0dc\ub97c \ubc14\uafb8\ub294 \uc77c\uacfc \uadf8 \uc548\uc758 \uc0ac\ub78c\uc774 \uc5b4\ub5bb\uac8c \ub290\ub07c\uace0 \uc788\ub294\uc9c0 \ubcf4\ub294 \uc77c\uc740 \ud568\uaed8 \uac00\uc57c \ud588\ub2e4. \uc774 \ub300\ubaa9\uc744 \uc77d\uc73c\uba74 \ub3cc\ubd04\uc774 \ub2e8\uc21c\ud55c \ub3d9\uc791 \ubaa9\ub85d\uc774 \uc544\ub2c8\ub77c\ub294 \uc810\uc774 \ubcf4\uc778\ub2e4. \ud55c \ubc88 \ucc3d\ubb38\uc744 \ub9cc\uc84c\ub2e4\uace0 \uc77c\uc774 \ub05d\ub098\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc2dc\uac04\uacfc \uc870\uac74\uc5d0 \ub530\ub77c \ub2e4\uc2dc \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \ud658\uacbd\uc744 \uc815\ub3c8\ud558\ub294 \uc0ac\ub78c\uc758 \ud3b8\ub9ac\ud568\ubcf4\ub2e4 \uadf8 \ud658\uacbd \uc548\uc5d0 \uba38\ubb34\ub294 \uc0ac\ub78c\uc758 \uacbd\ud5d8\uc744 \uc911\uc2ec\uc5d0 \ub193\ub294 \uc9c8\ubb38\uc774\ub2e4. \ucc45\uc740 \uc18c\uc74c\uc5d0\ub3c4 \ub9ce\uc740 \uc8fc\uc758\ub97c \uae30\uc6b8\uc778\ub2e4. \uc26c\uace0 \uc788\ub294 \uc0ac\ub78c \uac00\uae4c\uc774\uc5d0\uc11c \uac11\uc790\uae30 \ub098\ub294 \uc18c\ub9ac\ub098 \uacc4\uc18d\ub420\uc9c0 \uc54c \uc218 \uc5c6\ub294 \uc6c0\uc9c1\uc784\uc740 \ubd80\ub2f4\uc774 \ub420 \uc218 \uc788\ub2e4\ub294 \uad00\ucc30\uc774\ub2e4. \ub3cc\ubcf4\ub294 \ucabd\uc5d0\uac8c \uc0ac\uc18c\ud55c \uc18c\ub9ac\uac00 \ud658\uc790\uc5d0\uac8c\ub3c4 \uc0ac\uc18c\ud558\ub9ac\ub77c\ub294 \ubcf4\uc7a5\uc740 \uc5c6\ub2e4. \uc774\uac83\uc740 \ubaa8\ub4e0 \uc18c\ub9ac\ub97c \uc5c6\uc560\uc57c \ud55c\ub2e4\ub294 \uc624\ub298\uc758 \uaddc\uce59\uc744 \uc81c\uc2dc\ud558\ub294 \ub9d0\uc774 \uc544\ub2c8\ub2e4. \uac19\uc740 \uacf5\uac04\uc744 \uc0ac\uc6a9\ud558\ub294 \ub450 \uc0ac\ub78c\uc774 \uc11c\ub85c \ub2e4\ub978 \uacbd\ud5d8\uc744 \ud55c\ub2e4\ub294 \uc810\uc5d0 \uc8fc\ubaa9\ud558\ub294 \uac83\uc774\ub2e4. \ub204\uc6cc\uc11c \uc624\ub7ab\ub3d9\uc548 \uc26c\ub294 \uc0ac\ub78c\uc758 \uc790\ub9ac\uc5d0\uc11c \ubc29\uc744 \uc0dd\uac01\ud558\uba74 \ud3c9\uc18c\uc5d0 \ub4e3\uc9c0 \uc54a\ub358 \uac83\ub4e4\uc774 \ub2e4\ub978 \ubb34\uac8c\ub85c \ub4e4\uc5b4\uc62c \uc218 \uc788\ub2e4. \uc2dd\uc0ac \uc5ed\uc2dc \uc900\ube44\ud588\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc2e4\uc81c\ub85c \uba39\uc740 \uc591\uc744 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ucc45\uc740 \ud658\uc790\uc758 \uc2dd\uc0ac\uc640 \uc74c\uc2dd\uc774 \uc81c\uacf5\ub418\ub294 \ub54c, \uad00\ucc30\uc758 \ud544\uc694\ub97c \ub2e4\ub8ec\ub2e4. \uadf8\ub987\uc744 \uac16\ub2e4 \ub193\uc558\uc73c\ub2c8 \ud544\uc694\ud55c \uc77c\uc744 \ub9c8\ucce4\ub2e4\uace0 \uc0dd\uac01\ud558\uba74 \ub208\uc55e\uc5d0\uc11c \ub193\uce58\ub294 \uac83\uc774 \uc0dd\uae34\ub2e4. \uad6c\uccb4\uc801\uc778 \uc74c\uc2dd\uc774\ub098 \ubd84\ub7c9\uc5d0 \uad00\ud55c \uc61b \uc124\uba85\uc744 \ud604\uc7ac\uc758 \uc601\uc591 \ucc98\ubc29\uc73c\ub85c \ubc1b\uc544\ub4e4\uc774\uc9c0\ub294 \ub9d0\uc790. \uc774 \uae00\uc5d0\uc11c \uc8fc\ubaa9\ud558\ub294 \uac83\uc740 \uc81c\uacf5\ud55c \uc11c\ube44\uc2a4\uc640 \uadf8\uac83\uc744 \ubc1b\uc740 \uc0ac\ub78c\uc758 \uc0c1\ud0dc \uc0ac\uc774\uc5d0 \ucc28\uc774\uac00 \uc788\uc744 \uc218 \uc788\ub2e4\ub294 \uc810\uc774\ub2e4. \ud55c \uc77c\uc774 \ubb34\uc5c7\uc778\uc9c0 \uae30\ub85d\ud558\ub294 \uac83\uacfc \uadf8 \uc77c\uc774 \uc5b4\ub5a4 \uacb0\uacfc\ub97c \ub0c8\ub294\uc9c0 \uc0b4\ud53c\ub294 \uc77c\uc740 \uc774\uc5b4\uc838\uc57c \ud55c\ub2e4. \ud6c4\ubc18\uc758 \uad00\ucc30\uc5d0 \uad00\ud55c \uc124\uba85\uc740 \ud658\uc790\uc758 \uc0c1\ud0dc\ub97c \ub9c9\uc5f0\ud55c \uc778\uc0c1\uc73c\ub85c \ubcf4\uace0\ud558\uc9c0 \ub9d0 \uac83\uc744 \uc694\uad6c\ud55c\ub2e4. \uc9c1\uc811 \uc0b4\ud540 \ub0b4\uc6a9\uacfc \ucd94\uce21\uc744 \uad6c\ubd84\ud558\uace0, \ud544\uc694\ud55c \uc0ac\uc2e4\uc744 \uc54c\uc544\ubcfc \uc218 \uc788\uac8c \uc804\ub2ec\ud558\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4\ub294 \uc0dd\uac01\uc774\ub2e4. \uce5c\uc808\ud55c \uc124\uba85\ub3c4 \uc815\ud655\ud558\uc9c0 \uc54a\uc73c\uba74 \ucda9\ubd84\ud55c \ub3c4\uc6c0\uc774 \ub418\uae30 \uc5b4\ub835\ub2e4. \uc88b\uc544 \ubcf4\uc600\ub2e4\ub294 \ub9d0\uacfc \uc7a0\uc744 \uc5bc\ub9c8\ub098 \uc7a4\ub294\uc9c0 \ud655\uc778\ud55c \ub9d0\uc740 \ub2e4\ub974\ub2e4. \uae30\ub85d\uc774 \uc0ac\ub78c\uc758 \uc0c1\ud0dc\ub97c \ubaa8\ub450 \uc218\uce58\ub85c \ubc14\uafc0 \uc218\ub294 \uc5c6\uc9c0\ub9cc, \uc790\uae30 \ub290\ub08c\ub9cc\uc73c\ub85c \ud0c0\uc778\uc758 \uacbd\ud5d8\uc744 \ub300\uc2e0\ud558\uc9c0 \uc54a\uac8c \ub3c4\uc6b8 \uc218\ub294 \uc788\ub2e4. \uad00\ucc30\uc740 \ubb34\uc2ec\ud558\uac8c \ubc14\ub77c\ubcf4\ub294 \uc77c\uc774 \uc544\ub2c8\ub77c \ubb34\uc5c7\uc744 \uc544\uc9c1 \ubaa8\ub974\ub294\uc9c0\ub3c4 \uc54c\uc544\ucc28\ub9ac\ub294 \uc77c\uc774\ub2e4. \uc774 \ucc45\uc5d0\ub294 \ub2f9\uc2dc\uc758 \uc9c8\ubcd1 \uc774\ud574\uc640 \uc5ec\uc131\uc758 \uc5ed\ud560\uc5d0 \uad00\ud55c \uc804\uc81c\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \ubaa8\ub4e0 \ub0b4\uc6a9\uc744 \ud604\ub300 \uc758\ud559\uc774\ub098 \uc624\ub298\uc758 \ud3c9\ub4f1\ud55c \ub3cc\ubd04 \uad00\uacc4\uc640 \uac19\uac8c \uc77d\uc744 \uc218 \uc5c6\ub2e4. \uc624\ub798\ub41c \uc778\ubb3c\uc758 \uae30\uc5ec\ub97c \uc778\uc815\ud558\ub294 \uc77c\uacfc \uadf8 \uc2dc\ub300\uc758 \uc124\uba85\uc744 \ubb34\uc870\uac74 \ub530\ub974\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \uc624\ud788\ub824 \ubb34\uc5c7\uc774 \ub0a8\uace0 \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc84c\ub294\uc9c0 \ube44\uad50\ud560 \ub54c \uc5ed\uc0ac \uc77d\uae30\uc758 \uc758\ubbf8\uac00 \uc0dd\uae34\ub2e4. \ubcd1\uc6d0 \ud658\uacbd\uacfc \uad50\uc721, \uc758\ub8cc \uae30\uc220\uc774 \ubcc0\ud574\ub3c4 \ud658\uc790\uac00 \uc2e4\uc81c\ub85c \uc5b4\ub5a4 \uacbd\ud5d8\uc744 \ud558\ub294\uc9c0 \ud655\uc778\ud574\uc57c \ud55c\ub2e4\ub294 \uc9c8\ubb38\uc740 \uacc4\uc18d \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uc704\ub300\ud55c \uc0ac\ub78c\uc774\ub77c\ub294 \uc774\ub984\uc744 \uc678\uc6b0\ub294 \uac83\ubcf4\ub2e4 \uad6c\uccb4\uc801\uc778 \uc791\uc5c5\uc744 \uc77d\ub294 \ud3b8\uc774 \uac00\uae4c\uc6cc\uc9c4\ub2e4. \uc601\uc6c5\uc758 \uc804\uae30\ub294 \ud070 \uc0ac\uac74\uc744 \uc911\uc2ec\uc73c\ub85c \uae30\uc5b5\ub418\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \uc774 \ucc45\uc758 \ub9ce\uc740 \ubd80\ubd84\uc740 \ubc29 \uc548\uc758 \ud3c9\ubc94\ud55c \uc2dc\uac04\uc5d0 \uba38\ubb38\ub2e4. \uacf5\uae30\uac00 \ub2f5\ub2f5\ud55c\uc9c0, \uc870\uc6a9\ud788 \uc274 \uc218 \uc788\ub294\uc9c0, \uc804\ud574 \ub4e4\uc740 \uc774\uc57c\uae30\uac00 \uc9c1\uc811 \ud655\uc778\ud55c \uc0ac\uc2e4\uc778\uc9c0 \ubb3b\ub294\ub2e4. \uc720\uba85\ud55c \uc0c1\uc9d5 \ub4a4\uc5d0 \ubc18\ubcf5\ub418\ub294 \uc8fc\uc758\uac00 \uc788\uc5c8\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\uc740 19\uc138\uae30 \ub3cc\ubd04\uc758 \ubd84\uc704\uae30\ub97c \uc0c8\ub85c \uc0c1\uc0c1\ud55c AI \uc0bd\ud654\ub2e4. \ub098\uc774\ud305\uac8c\uc77c\uc758 \uc2e4\uc81c \uc5bc\uad74\uc774\ub098 \ud2b9\uc815 \ubcd1\uc6d0\uc744 \ubcf5\uc6d0\ud558\uc9c0 \uc54a\uc558\uc73c\uba70 \uc624\ub298\uc758 \ubcd1\uc2e4 \uad00\ub9ac\ubc95\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \ucc3d\uac00\uc758 \uc791\uc740 \uc7a5\uba74\uc744 \ud1b5\ud574 \ub3cc\ubcf4\ub294 \uc0ac\ub78c\uc774 \ubb34\uc5c7\uc744 \uc0b4\ud53c\uace0 \uc788\ub294\uc9c0 \ub5a0\uc62c\ub824 \ubcf4\uc544\ub3c4 \uc88b\ub2e4."}, {"id": "passport-three-languages", "title": "\uc61b \uc5ec\uad8c \ud55c \uc7a5\uc5d0 \uc138 \uc5b8\uc5b4\uac00 \ubaa8\uc600\ub2e4", "summary": "\ud55c\ubb38\uacfc \uc601\uc5b4, \ud504\ub791\uc2a4\uc5b4\uac00 \ub098\ub780\ud788 \ub193\uc778 \uc5ec\uad8c \uc591\uc2dd\uc744 \ub4e4\uc5ec\ub2e4\ubd05\ub2c8\ub2e4.", "category": "history", "category_title": "History", "subcategory": "Korea", "url": "stories/passport-three-languages/index.html", "image": "media/passport-three-languages.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \ub300\uc870\uc120\uad6d \uc5ec\uad8c \uc591\uc2dd \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc61b \uc5ec\uad8c \ud55c \uc7a5\uc5d0 \uc138 \uc5b8\uc5b4\uac00 \ubaa8\uc600\ub2e4 \ucc45\uc790 \ub300\uc2e0 \ucee4\ub2e4\ub780 \uc885\uc774\ub85c \ub9cc\ub098\ub294 \uc5ec\ud589 \ubb38\uc11c \ud55c\ubb38\uacfc \uc601\uc5b4, \ud504\ub791\uc2a4\uc5b4\uac00 \ub098\ub780\ud788 \ub193\uc778 \uc5ec\uad8c \uc591\uc2dd\uc744 \ub4e4\uc5ec\ub2e4\ubd05\ub2c8\ub2e4. Korea \uc5ed\uc0ac \uc5ec\uad8c\uc744 \ub5a0\uc62c\ub9ac\uba74 \uc190\ubc14\ub2e5\ub9cc \ud55c \ucc45\uc790\ub97c \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \uadf8\ub7f0\ub370 \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \ub300\uc870\uc120\uad6d \uc5ec\uad8c \uc591\uc2dd\uc740 \ud55c \uc7a5\uc758 \ub113\uc740 \uc885\uc774\ub2e4. \uc0ac\uc9c4\uc744 \ubcf4\uba74 \uac00\uc6b4\ub370\ub97c \uacbd\uacc4\ub85c \uae00\uc904\uc758 \ubaa8\uc2b5\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uc77d\uc744 \uc218 \uc788\ub294 \uae00\uc790\ub97c \uba3c\uc800 \ucc3e\uc544\ub3c4 \uc88b\uace0, \ubb38\uc7a5\uc774 \ub193\uc778 \ubc29\ud5a5\ubd80\ud130 \uc0b4\ud3b4\ubcf4\uc544\ub3c4 \uc88b\ub2e4. \ud55c \uc7a5\uc758 \uc885\uc774\uac00 \uc11c\ub85c \ub2e4\ub978 \ub3c5\uc790\ub97c \ub9cc\ub0a0 \uc900\ube44\ub97c \ud558\uace0 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc870\uae08\uc529 \ubcf4\uc778\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc624\ub978\ucabd\uc5d0\ub294 \ud55c\ubb38, \uc67c\ucabd\uc5d0\ub294 \uc601\uc5b4\uc640 \ud504\ub791\uc2a4\uc5b4\ub85c \ub0b4\uc6a9\uc744 \uc778\uc1c4\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc138 \uc5b8\uc5b4\uac00 \uc11c\ub85c \ub2e4\ub978 \ubb38\uc11c\uc5d0 \ud769\uc5b4\uc9c4 \uac83\uc774 \uc544\ub2c8\ub77c \uac19\uc740 \uc885\uc774 \uc704\uc5d0 \ubaa8\uc600\ub2e4. \ud574\uc678\uc5d0\uc11c \uc4f0\ub294 \ubb38\uc11c\ub77c\ub294 \uac83\uc744 \ubaa8\uc591\ub9cc\uc73c\ub85c\ub3c4 \uc2e4\uac10\ud558\uac8c \ub41c\ub2e4. \uc9c0\uae08\uc758 \uc5ec\ud589\uc790\uac00 \ud734\ub300\uc804\ud654 \ubc88\uc5ed \ud654\uba74\uc744 \uaebc\ub0b4\ub4ef, \uc774 \uc885\uc774\ub3c4 \uc5b8\uc5b4\uac00 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ub0b4\uc6a9\uc744 \uc804\ub2ec\ud560 \uc790\ub9ac\ub97c \uac16\ucd94\uace0 \uc788\uc5c8\ub358 \uac83\uc774\ub2e4. \uc774\ub294 \uc624\ub298\uc758 \uacbd\ud5d8\uc5d0 \ube57\ub300\uc5b4 \ubcf4\ub294 \ubc29\ubc95\uc774\ub2e4. \uae00\uc790\ub9cc \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubc14\uae65\uc5d0\ub294 \ubc30\uaf43\uacfc \ub369\uad74\uc744 \uc5ee\uc740 \ubb34\ub2ac\uac00 \ub458\ub7ec\uc838 \uc788\uace0, \uac00\uc6b4\ub370 \uc704\ucabd\uc5d0\ub294 \ubc30\uaf43\ubb34\ub2ac, \ub124 \uadc0\ud241\uc774\uc5d0\ub294 \ud0dc\uadf9\ubb34\ub2ac\uac00 \ubc30\uce58\ub418\uc5b4 \uc788\ub2e4. \ubc15\ubb3c\uad00\uc740 \ucc0d\ud78c \ub3c4\uc7a5\uc758 \uc774\ub984\uacfc \uc704\uce58\ub3c4 \ud568\uaed8 \uc18c\uac1c\ud55c\ub2e4. \uba40\ub9ac\uc11c \ubcf4\uba74 \uc7a5\uc2dd\ucc98\ub7fc \ubcf4\uc774\ub294 \ubd80\ubd84\ub4e4\uc774 \ubb38\uc11c\ub97c \uc54c\uc544\ubcf4\uac8c \ud558\ub294 \uc5bc\uad74\uc744 \ub9cc\ub4e0\ub2e4. \uae00\uc744 \ubaa8\ub450 \uc77d\uae30 \uc5b4\ub824\uc6cc\ub3c4 \ud14c\ub450\ub9ac\uc640 \ub3c4\uc7a5\uc744 \ub530\ub77c\uac00\uba74 \ub2e8\uc21c\ud55c \uba54\ubaa8\uc9c0\uc640\ub294 \ub2e4\ub978 \uc131\uaca9\uc758 \uc885\uc774\ub77c\ub294 \uac83\uc744 \ub290\ub07c\uac8c \ub41c\ub2e4. \uac19\uc740 \uc885\uc774\uc5d0 \uc5ec\ub7ec \uc5b8\uc5b4\ub97c \ub193\uc73c\uba74 \uadf8 \ubb38\uc11c\uac00 \ud55c \uc5b8\uc5b4\ub97c \uc4f0\ub294 \uc0ac\ub78c\ub4e4 \uc548\uc5d0\uc11c\ub9cc \uba38\ubb3c\uc9c0 \uc54a\ub3c4\ub85d \uc900\ube44\ud588\ub2e4\ub294 \uc810\uc774 \ubcf4\uc778\ub2e4. \uc5ec\uad8c\uc740 \ub2e4\ub978 \uc7a5\uc18c\uc758 \ub2f4\ub2f9\uc790\uc5d0\uac8c\ub3c4 \uc790\uc2e0\uc744 \uc124\uba85\ud574\uc57c \ud558\ub294 \ubb3c\uac74\uc774\ub2e4. \ub204\uad6c\ub97c \uc704\ud55c \uae00\uc778\uc9c0 \uc0dd\uac01\ud558\uba74 \uc5b8\uc5b4\uc758 \ubc30\uce58\uac00 \ub2e8\uc21c\ud788 \uba4b\uc744 \ub0b4\uae30 \uc704\ud55c \uc120\ud0dd\ucc98\ub7fc \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ub2e4\ub9cc \uc138 \uc5b8\uc5b4\uac00 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ub2f9\uc2dc \ubaa8\ub4e0 \uc5ec\ud589\uc790\uac00 \ubaa8\ub4e0 \ub098\ub77c\uc5d0\uc11c \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uc778\uc815\ubc1b\uc558\ub2e4\uace0 \ub2e8\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \ubb38\uc11c\ub97c \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc2e4\uc81c \uc2ec\uc0ac \ubc0f \uc0ac\uc6a9\uc758 \uc5ed\uc0ac\ub294 \ubcc4\ub3c4\ub85c \ud655\uc778\ud560 \ubd80\ubd84\uc774\ub2e4. \uc5ec\uae30\uc11c\ub294 \ud55c\ubb38\uacfc \uc601\uc5b4, \ud504\ub791\uc2a4\uc5b4\uac00 \uc5b4\ub5a4 \uc704\uce58\uc5d0 \ub193\uc600\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uba70 \ubc1c\uae09\ud558\ub294 \ucabd\uc774 \uc608\uc0c1\ud55c \uc804\ub2ec\uc758 \ubc94\uc704\ub97c \uc0dd\uac01\ud574 \ubcf8\ub2e4. \ub3c4\uc7a5\uc740 \ubb38\uc11c\uc758 \ubc1c\uae09\uacfc \ud655\uc778 \uad00\uacc4\ub97c \ub4dc\ub7ec\ub0b4\ub294 \ud45c\uc9c0\uac00 \ub420 \uc218 \uc788\ub2e4. \ubc30\uaf43\uacfc \ud0dc\uadf9\uc758 \ubb34\ub2ac\ub3c4 \uc885\uc774\uc758 \uc2dc\uac01\uc801 \uc815\uccb4\uc131\uc744 \ub9cc\ub4e0\ub2e4. \uc5ec\ub7ec \uc5b8\uc5b4\uac00 \ud568\uaed8 \uc788\uc5b4\ub3c4 \uac19\uc740 \ud14c\ub450\ub9ac\uc640 \ud45c\uc9c0\ub97c \uacf5\uc720\ud558\uba74 \ud55c \ubb38\uc11c\ub77c\ub294 \uc778\uc0c1\uc774 \uc774\uc5b4\uc9c4\ub2e4. \uae00\uc744 \uc77d\ub294 \ud589\uc704\uc640 \ubb3c\uac74\uc758 \ud615\uc2dd\uc744 \uc54c\uc544\ubcf4\ub294 \ud589\uc704\uac00 \uacb9\uccd0 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \ud14c\ub450\ub9ac\uac00 \ud654\ub824\ud558\ub2e4\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \ubb38\uc11c\uc758 \ud6a8\ub825\uc774\ub098 \ubaa8\ub4e0 \ub3c4\uc7a5\uc758 \uad8c\ud55c\uc744 \ud310\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uad6c\uccb4\uc801\uc778 \uba85\uce6d\uacfc \uc704\uce58\ub294 \ubc15\ubb3c\uad00 \uc124\uba85\uacfc \ub300\uc870\ud560 \ubd80\ubd84\uc774\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c\ub294 \uba3c\uc800 \uae00\uc774 \ub193\uc778 \uad6c\uc5ed\uc744 \ub098\ub208 \ub4a4 \uac00\uc7a5\uc790\ub9ac\ub85c \ub208\uc744 \uc62e\uaca8 \ubcf4\uc790. \uc804\ub2ec\ud560 \ub0b4\uc6a9\uacfc \uadf8 \ub0b4\uc6a9\uc744 \ub2f4\ub294 \uacf5\uc801\uc778 \ud615\uc2dd\uc774 \uac19\uc740 \uc885\uc774 \uc704\uc5d0 \uc900\ube44\ub418\uc5b4 \uc788\uc5c8\ub2e4. \ubc15\ubb3c\uad00\uc740 \uac1c\uad6d \uc5f0\ud638\uc640 \uc678\ubd80\ub77c\ub294 \uae30\uad00 \uba85\uce6d \ub4f1\uc744 \uadfc\uac70\ub85c 1895\ub144 \uc791\uc131\uc73c\ub85c \ucd94\uc815\ud55c\ub2e4. \ub0a0\uc9dc\uac00 \uc624\ub298\uc758 \ubc29\uc2dd\uc73c\ub85c \ud06c\uac8c \uc801\ud600 \uc788\uc9c0 \uc54a\uc544\ub3c4 \ubb38\uc11c\uc758 \ud45c\ud604\uc774 \uc2dc\uae30\ub97c \uc881\ud788\ub294 \ub2e8\uc11c\uac00 \ub418\ub294 \uac83\uc774\ub2e4. \ud55c \ub2e8\uc5b4\uac00 \ub2f9\uc2dc\uc758 \uc81c\ub3c4\ub97c \uac00\ub9ac\ud0a4\uba74 \ub2e4\ub978 \uc2dc\uae30\uc758 \ubb38\uc11c\uc640 \uad6c\ubd84\ud560 \uae38\uc774 \uc0dd\uae34\ub2e4. \uc5ec\uae30\uc11c \ucd94\uc815\uc774\ub77c\ub294 \ub9d0\uc740 \uc9c0\uc6b0\uc9c0 \uc54a\ub294\ub2e4. \uc5ec\ub7ec \ub2e8\uc11c\uac00 \uac19\uc740 \ubc29\ud5a5\uc744 \uac00\ub9ac\ud0a8\ub2e4\ub294 \ud310\ub2e8\uacfc \ud2b9\uc815\ud55c \ub0a0\uc758 \ubc1c\uae09\uc744 \ubaa8\ub450 \ud655\uc778\ud588\ub2e4\ub294 \ud310\ub2e8\uc740 \ub2e4\ub974\ub2e4. \uc624\ub798\ub41c \uc790\ub8cc\uc758 \uc5f0\ub300\ub97c \uc77d\uc744 \ub54c\uc5d0\ub294 \uc774 \ucc28\uc774\ub97c \ub0a8\uaca8 \ub450\ub294 \uac83\uc774 \uc815\ud655\ud558\ub2e4. \uc5b8\uc5b4\uc758 \ub0b4\uc6a9\uc744 \ubab0\ub77c\ub3c4 \uae30\uad00 \uc774\ub984\uacfc \ud45c\uae30 \ubc29\uc2dd\uc774 \ubb38\uc11c\uc758 \uc2dc\uac04\uc744 \uc54c\ub824 \uc904 \uc218 \uc788\ub2e4\ub294 \uc810\uc740 \uc54c\uc544\ub458 \ub9cc\ud558\ub2e4. \uc5ec\uad8c\uc744 \uc18c\uc9c0\ud588\ub358 \uc0ac\ub78c\uc5d0\uac8c\ub294 \ub2e4\ub978 \uacf3\uc73c\ub85c \uc6c0\uc9c1\uc774\ub294 \uc77c\uc744 \uc704\ud55c \ubb38\uc11c\uc600\uc744 \uac83\uc774\ub2e4. \ud6c4\ub300\uc758 \uad00\ub78c\uc790\ub294 \uadf8 \uc885\uc774\uc5d0\uc11c \uad6d\uc81c\uc801\uc778 \ud1b5\uc2e0\uacfc \uc2e0\ubd84 \ud655\uc778\uc758 \ubc29\uc2dd\uc744 \uc0b4\ud540\ub2e4. \uac1c\uc778\uc758 \uc774\ub3d9\uacfc \uad6d\uac00 \uae30\uad00\uc758 \uc5c5\ubb34\uac00 \ud55c \ubb3c\uac74\uc5d0 \ub9cc\ub098\ub294 \uac83\uc774\ub2e4. \ub2e4\ub9cc \uad6c\uccb4\uc801\uc778 \uc5ec\ud589 \uacbd\ub85c\uc640 \uc18c\uc9c0\uc790\uc758 \uac10\uc815\uc740 \ud655\uc778\ud55c \uc790\ub8cc\uac00 \uc5c6\uc73c\uba74 \uc0c8\ub85c \uc4f0\uc9c0 \uc54a\ub294\ub2e4. \uc774\ub807\uac8c \ubcf4\uba74 \uc5ec\uad8c \uc0ac\uc9c4\uc758 \uc791\uc740 \ub3c4\uc7a5\uacfc \ud14c\ub450\ub9ac\uac00 \ub2e8\uc21c\ud55c \uc7a5\uc2dd\uc5d0 \uadf8\uce58\uc9c0 \uc54a\ub294\ub2e4. \ub204\uad70\uac00\uc758 \uc774\ub3d9\uc744 \ub2e4\ub978 \uc0ac\ub78c\uc774 \uc54c\uc544\ubcf4\uace0 \ud655\uc778\ud560 \uc218 \uc788\ub3c4\ub85d \ub9c8\ub828\ud55c \ud615\uc2dd\uc758 \uc77c\ubd80\uc600\ub2e4. \uc2a4\ub9c8\ud2b8\ud3f0 \ubc88\uc5ed \ud654\uba74\uc774\ub77c\ub294 \ud604\ub300\uc758 \ube44\uc720\ub294 \uadf8 \uc804\ub2ec\uc758 \ud544\uc694\ub97c \uac00\uae4c\uc774 \uac00\uc838\uc62c \ubfd0\uc774\ub2e4. \uc2e4\uc81c \ubb38\uc11c\uac00 \uac00\uc9c4 \uc2dc\ub300\uc758 \uc5b8\uc5b4\uc640 \uc81c\ub3c4\ub97c \ub530\ub85c \uc0b4\ud53c\uba74 \uc885\uc774 \ud55c \uc7a5\uc758 \uc774\uc57c\uae30\uac00 \ub354 \ub113\uc5b4\uc9c4\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc774 \uc591\uc2dd\uc5d0 \uc4f0\uc778 \uc5f0\ud638\uc640 \uc678\uad50 \ub2f4\ub2f9 \uad00\uccad\uc758 \uba85\uce6d\uc744 \uadfc\uac70\ub85c \uc791\uc131 \uc2dc\uae30\ub97c 1895\ub144\uc73c\ub85c \ucd94\uc815\ud55c\ub2e4. \ub0a0\uc9dc \ud558\ub098\ub97c \ub9d0\ud558\ub294 \ub370\ub3c4 \ubb38\uc11c \uc548\uc758 \ub2e8\uc11c\ub4e4\uc744 \ud568\uaed8 \uc77d\ub294 \uacfc\uc815\uc774 \ud544\uc694\ud55c \uac83\uc774\ub2e4. \uc774 \uc18c\uc7a5\ud488\uc740 \ud2b9\uc815 \uc5ec\ud589\uc790\uc758 \uc5ec\uc815\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc774 \uc544\ub2c8\ub77c \uc5ec\uad8c \uc591\uc2dd\uc744 \ubcf4\ub294 \uc790\ub8cc\ub2e4. \ub204\uad6c\uc758 \uc9d0\uac00\ubc29\uc5d0 \ub4e4\uc5b4 \uc788\uc5c8\uc744\uc9c0 \uc0c1\uc0c1\ud558\uae30\uc5d0 \uc55e\uc11c, \ud55c \uc885\uc774\uc5d0 \uc138 \uc5b8\uc5b4\ub97c \ub098\ub780\ud788 \ub193\uc558\ub2e4\ub294 \uc120\ud0dd\ubd80\ud130 \uae30\uc5b5\ud574 \ub450\uc790. \uad6d\uacbd\uc744 \ub118\uc744 \uc900\ube44\uac00 \ubb38\uc7a5 \ubc30\uce58\uc5d0\ub3c4 \ub0a8\uc544 \uc788\ub2e4."}, {"id": "rosetta-stone-three-scripts", "title": "\ub85c\uc81c\ud0c0\uc11d \u2014 \uc65c \uac19\uc740 \ub9d0\uc744 \uc138 \uac00\uc9c0 \ubb38\uc790\ub85c \uc0c8\uacbc\uc744\uae4c", "summary": "\ub450 \uc5b8\uc5b4\u00b7\uc138 \ubb38\uc790\ub85c \ub0a8\uc740 \ube44\ubb38\uc744 \ud1b5\ud574 \uc774\ub984\uacfc \ubc18\ubcf5\uc744 \ube44\uad50\ud558\uba70 \ubb38\uc790\ub97c \uc77d\uc5b4 \uac04 \uacfc\uc815\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history", "category_title": "History", "subcategory": "Africa", "url": "stories/rosetta-stone-three-scripts/index.html", "image": "media/rosetta-stone-three-scripts.png", "alt": "\uae68\uc9c4 \uac00\uc7a5\uc790\ub9ac\uc640 \uc138 \ubb38\uc790 \uad6c\uc5ed\uc774 \ubcf4\uc774\ub294 \ub85c\uc81c\ud0c0\uc11d\uc758 \uc61b \ube44\ubb38 \ub3c4\ud310.", "text": "\ub85c\uc81c\ud0c0\uc11d \u2014 \uc65c \uac19\uc740 \ub9d0\uc744 \uc138 \uac00\uc9c0 \ubb38\uc790\ub85c \uc0c8\uacbc\uc744\uae4c \ub3cc \ud55c \uc870\uac01\uc5d0\uc11c \uc2dc\uc791\ub41c \ube44\uad50\uc640 \ud574\ub3c5\uc758 \uae34 \uc2dc\uac04 \ub450 \uc5b8\uc5b4\u00b7\uc138 \ubb38\uc790\ub85c \ub0a8\uc740 \ube44\ubb38\uc744 \ud1b5\ud574 \uc774\ub984\uacfc \ubc18\ubcf5\uc744 \ube44\uad50\ud558\uba70 \ubb38\uc790\ub97c \uc77d\uc5b4 \uac04 \uacfc\uc815\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Africa \uc5ed\uc0ac \uae00\uc790\uac00 \ube7d\ube7d\ud55c \ub3cc \ud55c \uc870\uac01\uc774 \uc788\ub2e4. \ub9e8 \uc704\uc640 \uac00\uc6b4\ub370, \uc544\ub798\ucabd\uc758 \uae00\uc790 \ubaa8\uc591\uc774 \uc11c\ub85c \ub2e4\ub974\ub2e4. \uc138 \uc885\ub958\uc758 \ube44\ubc00\uc744 \ub530\ub85c \uc801\uc740 \uac83 \uac19\uc9c0\ub9cc, \ub85c\uc81c\ud0c0\uc11d\uc758 \uc911\uc694\ud55c \uc810\uc740 \uc11c\ub85c \uad00\uacc4\uc788\ub294 \ub0b4\uc6a9\uc744 \ub2e4\ub978 \ubb38\uc790\ub85c \uc0c8\uacbc\ub2e4\ub294 \ub370 \uc788\ub2e4. \uc77d\uc744 \uc218 \uc788\ub358 \ubd80\ubd84\uc774 \uc77d\uae30 \uc5b4\ub824\uc6e0\ub358 \ubd80\ubd84\uc744 \uc54c\uc544\ubcf4\ub294 \uc2e4\ub9c8\ub9ac\uac00 \ub418\uc5c8\ub2e4. \ub3cc \uc790\uccb4\uac00 \uace0\ub300 \uc774\uc9d1\ud2b8\uc758 \ubaa8\ub4e0 \ube44\ubc00\uc744 \ud55c\uaebc\ubc88\uc5d0 \uc124\uba85\ud574 \uc900 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5ec\ub7ec \uc0ac\ub78c\uc774 \uc0ac\ubcf8\uacfc \ub2e4\ub978 \uc790\ub8cc\ub97c \ube44\uad50\ud558\uba70 \uc624\ub7ab\ub3d9\uc548 \uc5f0\uad6c\ud588\ub2e4. \ud574\ub3c5\uc758 \uc774\uc57c\uae30\ub97c \ucc9c\uc7ac\uac00 \ub2e8\ubc88\uc5d0 \uc554\ud638\ub97c \ud47c \uc7a5\uba74\ubcf4\ub2e4, \ubc18\ubcf5\ub418\ub294 \ubaa8\uc591\uc5d0 \uc9c8\ubb38\uc744 \ub358\uc9c0\ub294 \uacfc\uc815\uc73c\ub85c \uc77d\uc5b4 \ubcf4\uc790. \ub85c\uc81c\ud0c0\uc11d\uc5d0\ub294 \uace0\ub300 \uc774\uc9d1\ud2b8\uc5b4\uc640 \uadf8\ub9ac\uc2a4\uc5b4\uac00 \uc4f0\uc600\ub2e4. \uc774\uc9d1\ud2b8\uc5b4\ub294 \uc0c1\ud615\ubb38\uc790\uc640 \ub370\ubaa8\ud2f1\uc774\ub77c\ub294 \ub450 \ubb38\uc790 \ud615\ud0dc\ub85c \ud45c\ud604\ub418\uc5c8\ub2e4. \uadf8\ub9ac\uc2a4\uc5b4 \ubd80\ubd84\uae4c\uc9c0 \ud569\ud558\uba74 \uc5b8\uc5b4\ub294 \ub458, \ubb38\uc790 \uccb4\uacc4\ub294 \uc14b\uc774\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \uad6c\uc5ed\uc774 \uc138 \uac1c\ub77c\uace0 \uc5b8\uc5b4\ub3c4 \uc138 \uac1c\ub77c\uace0 \ub9d0\ud558\uba74 \uad6c\ubd84\uc744 \ub193\uce58\uac8c \ub41c\ub2e4. \uac19\uc740 \uc5b8\uc5b4\ub3c4 \ub2e4\ub978 \uae00\uc790 \uccb4\uacc4\ub85c \uc801\uc744 \uc218 \uc788\ub2e4\ub294 \uc810\uc744 \ub5a0\uc62c\ub9ac\uba74 \uc870\uae08 \uc26c\uc6cc\uc9c4\ub2e4. \ub2e4\ub9cc \ud604\ub300\uc758 \ud45c\uae30 \uc0ac\ub840\uc640 \uace0\ub300 \ubb38\uc790\uac00 \uc644\uc804\ud788 \uac19\uc740 \uad00\uacc4\uc778 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5ec\uae30\uc11c\ub294 \ub9d0\uc758 \uccb4\uacc4\uc778 \uc5b8\uc5b4\uc640 \uadf8 \ub9d0\uc744 \uc801\ub294 \ubb38\uc790\ub77c\ub294 \uc11c\ub85c \ub2e4\ub978 \uce35\uc744 \ub098\ub204\uc5b4 \ubcf4\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4. \ube44\ubb38\uc740 \uae30\uc6d0\uc804 196\ub144 \ud504\ud1a8\ub808\ub9c8\uc774\uc624\uc2a4 5\uc138\uc640 \uad00\ub828\ub41c \ud3ec\uace0\uc758 \ub0b4\uc6a9\uc774\ub2e4. \ud6c4\ub300 \uc5f0\uad6c\uc790\ub4e4\uc5d0\uac8c \ubb38\uc790\ub97c \uac00\ub974\uccd0 \uc8fc\ub824\uace0 \ub9cc\ub4e0 \ube44\uad50\ud45c\uac00 \uc544\ub2c8\ub2e4. \ub2f9\uc2dc\uc758 \uad8c\ub825\uacfc \uc885\uad50\uc801 \uad00\uacc4 \uc18d\uc5d0\uc11c \uc655\uc744 \uae30\ub9ac\ub294 \ubb38\uc11c\uac00 \uc5ec\ub7ec \ubb38\uc790\ub85c \uc0c8\uaca8\uc9c4 \uac83\uc774\ub2e4. \ud558\ub098\uc758 \ub0b4\uc6a9\uc744 \uc5ec\ub7ec \ub3c5\uc790\uc640 \uad00\uc2b5\uc5d0 \ub9de\ucdb0 \ud45c\ud604\ud55c \uacb0\uacfc\uac00 \ud6d7\ub0a0 \uc804\ud600 \ub2e4\ub978 \uc6a9\ub3c4\ub85c \uc911\uc694\ud574\uc84c\ub2e4. \uc790\ub8cc\uc758 \uc6d0\ub798 \ubaa9\uc801\uacfc \ub098\uc911\uc5d0 \uc5bb\uc740 \uc758\ubbf8\ub294 \uac19\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \uc5b4\ub5a4 \ubb3c\uac74\uc774 \uc720\uba85\ud574\uc84c\ub294\uc9c0 \uc774\ud574\ud558\ub824\uba74 \ub9cc\ub4e4\uc5b4\uc9c4 \ub54c\uc758 \uc4f0\uc784\uacfc \ub4a4\uc5d0 \uc77c\uc5b4\ub09c \uc77c\uc744 \ub098\ub204\uc5b4 \uc0b4\ud544 \ud544\uc694\uac00 \uc788\ub2e4. \uc0c1\ub2e8\uacfc \uac00\uc7a5\uc790\ub9ac\ub294 \uae68\uc838 \uc788\uace0 \uae00\ub3c4 \ubaa8\ub450 \uac19\uc740 \uc815\ub3c4\ub85c \ubcf4\uc874\ub418\uc9c0 \uc54a\uc558\ub2e4. \ud2b9\ud788 \uc704\ucabd \uc0c1\ud615\ubb38\uc790 \uad6c\uc5ed\uc740 \uc6d0\ub798 \uc804\uccb4\uc758 \uc77c\ubd80\ub9cc \ub0a8\uc544 \uc788\ub2e4. \ub208\uc55e\uc758 \ubaa8\uc2b5\uc774 \ucc98\uc74c \uc81c\uc791\ub41c \ube44\uc11d\uc758 \uc644\uc804\ud55c \ud615\ud0dc\ub77c\uace0 \uc0dd\uac01\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \ub530\ub77c\uc11c \uac19\uc740 \ub0b4\uc6a9\uc774 \uc788\ub2e4\uace0 \ud574\uc11c \uc704\uc5d0\uc11c \ud55c \uc904, \uc544\ub798\uc5d0\uc11c \ud55c \uc904\uc744 \uadf8\ub300\ub85c \ub9de\ucd94\uba74 \ub05d\ub098\ub294 \ubb38\uc81c\ub294 \uc544\ub2c8\uc5c8\ub2e4. \ube60\uc9c4 \ubd80\ubd84\uacfc \ubb38\uc7a5\uc758 \ucc28\uc774, \uac01 \ubb38\uc790\uac00 \uc4f0\uc774\ub294 \ubc29\uc2dd\uc744 \uace0\ub824\ud574\uc57c \ud588\ub2e4. \uc2e4\uc81c \uc5f0\uad6c\ub294 \uac04\ub2e8\ud55c \uc138 \uce78\uc9dc\ub9ac \ub300\uc870\ud45c\ubcf4\ub2e4 \ud6e8\uc52c \ubcf5\uc7a1\ud55c \uc791\uc5c5\uc774\uc5c8\ub2e4. \uc774 \ub3cc\uc740 1799\ub144 \uc774\uc9d1\ud2b8\uc758 \ub85c\uc81c\ud0c0, \uace7 \ub77c\uc2dc\ub4dc \ubd80\uadfc\uc5d0\uc11c \ud504\ub791\uc2a4\uad70\uc758 \uacf5\uc0ac \uc911 \ubc1c\uacac\ub418\uc5c8\ub2e4. \uc774\ud6c4 \uad70\uc0ac\uc801 \ucda9\ub3cc\uacfc \ud56d\ubcf5 \ud611\uc815\uc758 \uacfc\uc815\uc5d0\uc11c \uc601\uad6d \uce21\uc73c\ub85c \ub118\uc5b4\uac14\uace0 1802\ub144 \uc601\uad6d\uc5d0 \ub3c4\ucc29\ud588\ub2e4. \ub098\uc911\uc5d0\ub294 \ub300\uc601\ubc15\ubb3c\uad00\uc5d0 \ub193\uc5ec \uad00\ub78c\uacfc \uc5f0\uad6c\uc758 \ub300\uc0c1\uc774 \ub418\uc5c8\ub2e4. \uc774 \uc774\ub3d9\uc744 \uc9c0\uc2dd\uc774 \uc790\uc5f0\uc2a4\ub7fd\uac8c \uc720\ub7fd\uc73c\ub85c \ubaa8\uc5ec\ub4e4\uc5c8\ub2e4\ub294 \uc774\uc57c\uae30\ub85c\ub9cc \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \uad70\ub300\uc640 \uad8c\ub825\uc774 \uc720\ubb3c\uc758 \uc774\ub3d9\uc5d0 \uc791\uc6a9\ud588\ub2e4. \ud574\ub3c5\uc5d0 \uae30\uc5ec\ud55c \uc5f0\uad6c\uc758 \uc5ed\uc0ac\uc640 \uc720\ubb3c\uc744 \ub204\uac00 \uc18c\uc720\ud558\uace0 \uc804\uc2dc\ud558\ub294\uac00\uc758 \uc9c8\ubb38\uc740 \uad6c\ubcc4\ud558\uba74\uc11c\ub3c4 \ud568\uaed8 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uc77d\uc744 \uc218 \uc788\ub294 \uadf8\ub9ac\uc2a4\uc5b4 \ub0b4\uc6a9\uc744 \ud1b5\ud574 \ube44\ubb38\uc774 \ub204\uad6c\uc640 \uc5b4\ub5a4 \uc77c\uc5d0 \uad00\ud55c \uac83\uc778\uc9c0 \uc54c \uc218 \uc788\uc5c8\ub2e4. \ub2e4\ub978 \ubb38\uc790 \uad6c\uc5ed\uc5d0\uc11c\ub3c4 \uc655\uc758 \uc774\ub984\ucc98\ub7fc \ubc18\ubcf5\ub420 \ub9cc\ud55c \ubd80\ubd84\uc744 \ucc3e\uc73c\uba74 \ube44\uad50\ud560 \ucd9c\ubc1c\uc810\uc774 \uc0dd\uae34\ub2e4. \ub0af\uc120 \uae00\uc790\ub97c \ubb34\uc791\uc815 \ud558\ub098\uc529 \ucd94\uce21\ud558\ub294 \uac83\uacfc\ub294 \ub2e4\ub978 \uc811\uadfc\uc774\ub2e4. \ud0c0\uc6d0\ud615 \ud14c\ub450\ub9ac\uc5d0 \uc2f8\uc778 \uc655\uba85\uc778 \uce74\ub974\ud22c\uc288\ub3c4 \uc911\uc694\ud55c \ub2e8\uc11c\uc600\ub2e4. \uc5f0\uad6c\uc790\ub4e4\uc740 \ud504\ud1a8\ub808\ub9c8\uc774\uc624\uc2a4\uc758 \uc774\ub984\uacfc \ub2e4\ub978 \ube44\ubb38 \uc790\ub8cc\uc758 \uc774\ub984\uc744 \ube44\uad50\ud588\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \ud074\ub808\uc624\ud30c\ud2b8\ub77c \uc774\ub984\uc758 \ube44\uad50\uc5d0\ub294 \ud544\ub77c\uc774\uc758 \uc624\ubca8\ub9ac\uc2a4\ud06c \uac19\uc740 \ub2e4\ub978 \uc790\ub8cc\uac00 \uc4f0\uc600\ub2e4. \ub450 \uc774\ub984\uc774 \ubaa8\ub450 \ub85c\uc81c\ud0c0\uc11d\uc5d0 \uc788\ub2e4\uace0 \uc0dd\uac01\ud558\uc9c0 \uc54a\ub3c4\ub85d \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \uc0c8\ub098 \ub208, \uc0ac\ub78c\ucc98\ub7fc \ubcf4\uc774\ub294 \ubaa8\uc591\uc774 \uc788\ub2e4\uace0 \ud574\uc11c \ubaa8\ub4e0 \uae30\ud638\ub97c \uc0ac\ubb3c\uc758 \uadf8\ub9bc \ub73b \ud558\ub098\ub85c \ubc14\uafc0 \uc218\ub294 \uc5c6\ub2e4. \uc18c\ub9ac\ub97c \ub098\ud0c0\ub0b4\ub294 \uae30\ub2a5\uc744 \uc774\ud574\ud558\ub294 \uac83\uc774 \uc911\uc694\ud588\ub2e4. \uae00\uc790\ucc98\ub7fc \uc0dd\uae34 \uadf8\ub9bc\uc774 \uc544\ub2c8\ub77c \uc5b8\uc5b4\ub97c \ud45c\ud604\ud558\ub294 \ubcf5\uc7a1\ud55c \ubb38\uc790 \uccb4\uacc4\ub97c \uc77d\uc5b4\uc57c \ud588\ub358 \uac83\uc774\ub2e4. \ud1a0\uba38\uc2a4 \uc601\uacfc \uc7a5\ud504\ub791\uc218\uc544 \uc0f9\ud3f4\ub9ac\uc639\uc744 \ube44\ub86f\ud55c \uc5ec\ub7ec \uc5f0\uad6c\uc790\uc758 \uae30\uc5ec\uac00 \uc774\uc5b4\uc84c\ub2e4. \uac19\uc740 \uc790\ub8cc\ub97c \ub450\uace0 \uc55e\uc120 \ud574\uc11d\uc744 \uace0\uce58\uace0 \ub2e4\ub978 \uc5b8\uc5b4 \uc9c0\uc2dd\uc744 \uc5f0\uacb0\ud558\ub294 \uacfc\uc815\uc774 \uc788\uc5c8\ub2e4. \uc774\uc9d1\ud2b8\uc5b4\ub97c \uc5f0\uad6c\ud560 \ub54c \ucf65\ud2b8\uc5b4\ub97c \uc544\ub294 \uc77c\ub3c4 \uc911\uc694\ud588\ub2e4. \ub3cc \ud55c \uc870\uac01\uacfc \ud55c \uc0ac\ub78c\uc758 \uc7ac\ub2a5\ub9cc\uc73c\ub85c \ub05d\ub09c \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub2e4. \ub85c\uc81c\ud0c0\uc11d\uc744 \uc9c1\uc811 \ubcfc \uc218 \uc788\ub294 \uc0ac\ub78c\uc740 \uc81c\ud55c\ub418\uc5b4 \uc788\uc5c8\ub2e4. \uc778\uc1c4\ud55c \ubcf5\uc0ac\uc640 \ud0c1\ubcf8, \uc11d\uace0 \ubaa8\ud615 \uac19\uc740 \uc790\ub8cc\uac00 \uc5ec\ub7ec \uacf3\uc73c\ub85c \uc804\ud574\uc9c0\uba74\uc11c \ub2e4\ub978 \uc5f0\uad6c\uc790\ub4e4\ub3c4 \ub0b4\uc6a9\uc744 \ube44\uad50\ud560 \uc218 \uc788\uc5c8\ub2e4. \uc6d0\ubcf8\uc744 \ubcf4\uc874\ud558\ub294 \uc77c\uacfc \uc815\ud655\ud558\uac8c \ubcf5\uc81c\ud574 \ub098\ub204\ub294 \uc77c\uc774 \uc5f0\uad6c\uc5d0\uc11c \uc5f0\uacb0\ub418\uc5c8\ub2e4. \uc774 \uae00\uc758 \uadfc\uac70\ub85c \uc77d\uc740 1913\ub144 \ubc15\ubb3c\uad00 \ud574\uc124\uc11c\ub294 \uadf8\ub7f0 \uacfc\uc815\uc744 \uae30\ub85d\ud558\uc9c0\ub9cc \uc2dc\ub300\uc758 \uc124\uba85\uacfc \ud55c\uacc4\ub3c4 \uc788\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \ub3cc\uc758 \uc7ac\uc9c8\uc5d0 \ub300\ud55c \uc61b \ubd84\ub958\ub97c \uc5ec\uae30\uc11c \uadf8\ub300\ub85c \ubc18\ubcf5\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc624\ub798\ub41c \uc790\ub8cc\ub294 \uc720\uc6a9\ud55c \uc6d0\uc804\uc774\uba74\uc11c \uc774\ud6c4 \uc5f0\uad6c\uc640 \uad6c\ubd84\ud574 \uc77d\uc5b4\uc57c \ud560 \ub300\uc0c1\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \uadf8 \ud574\uc124\uc11c\uc758 \uc2e4\uc81c \ube44\ubb38 \ub3c4\ud310\uc774\ub2e4. AI\uac00 \uc0c1\ud615\ubb38\uc790\ub97c \ub9cc\ub4e4\uc5b4 \ub123\uc740 \uadf8\ub9bc\uc774 \uc544\ub2c8\ub2e4. \uc138 \uad6c\uc5ed\uc758 \uae00\uc790 \ubaa8\uc591\uacfc \uae68\uc9c4 \uac00\uc7a5\uc790\ub9ac\ub97c \ubcf4\uace0 \ub098\uba74, \uc775\uc219\ud558\uac8c \uc77d\ub294 \uae00\uc5d0\ub3c4 \uc5b4\ub5a4 \ubb38\uc790\uc640 \uc5b8\uc5b4\uc758 \uc57d\uc18d\uc774 \ub193\uc5ec \uc788\ub294\uc9c0 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \ub85c\uc81c\ud0c0\uc11d\uc774 \ud765\ubbf8\ub85c\uc6b4 \uc774\uc720\ub294 \ube44\ubc00\uc2a4\ub7ec\uc6b4 \ub3cc\uc774\ub77c\ub294 \uc774\ub984 \ub54c\ubb38\ub9cc\uc774 \uc544\ub2c8\ub2e4. \uc54c\ub358 \ubd80\ubd84\uc5d0\uc11c \ubaa8\ub974\ub358 \ubd80\ubd84\uc73c\ub85c \ub118\uc5b4\uac00\uace0, \ud558\ub098\uc758 \ucd94\uce21\uc744 \ub2e4\ub978 \uc790\ub8cc\uc640 \ub300\uc870\ud574 \uace0\uccd0 \uac04 \uacfc\uc815\uc774 \ub2f4\uaca8 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uc77d\uae30\uc758 \uc5ed\uc0ac\ub294 \ud63c\uc790 \ub5a0\uc62c\ub9b0 \uc815\ub2f5\ubcf4\ub2e4 \ud568\uaed8 \ud655\uc778\ud55c \uc5f0\uacb0 \uc18d\uc5d0\uc11c \ub113\uc5b4\uc9c0\uae30\ub3c4 \ud55c\ub2e4."}, {"id": "suez-canal-shortcut-and-power", "title": "\uc218\uc5d0\uc988 \uc6b4\ud558 \u2014 \uc9c0\ub984\uae38\uc740 \uc5b4\ub5bb\uac8c \uc81c\uad6d\uc758 \uae38\uc774 \ub418\uc5c8\uc744\uae4c", "summary": "1881\ub144 \uc2e4\uc81c \ub3c4\ud310\uc744 \ubcf4\uba70 \uc6b4\ud558 \uac74\uc124\uacfc \ub178\ub3d9, 1875\ub144 \uc9c0\ubd84 \ub9e4\uac01, \uc601\uad6d\uc758 \uac1c\uc785\uc73c\ub85c \uc774\uc5b4\uc9c4 \uc5ed\uc0ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "history", "category_title": "History", "subcategory": "Middle East", "url": "stories/suez-canal-shortcut-and-power/index.html", "image": "media/suez-canal-shortcut-and-power.jpg", "alt": "1881\ub144 \uc5ed\uc0ac \ub3c4\ud310. \uc704\ucabd \uc9c0\uc911\ud574\uc640 \uc544\ub798\ucabd \ud64d\ud574\ub97c \uc787\ub294 \uc218\uc5d0\uc988 \uc6b4\ud558\uc758 \uacbd\ub85c.", "text": "\uc218\uc5d0\uc988 \uc6b4\ud558 \u2014 \uc9c0\ub984\uae38\uc740 \uc5b4\ub5bb\uac8c \uc81c\uad6d\uc758 \uae38\uc774 \ub418\uc5c8\uc744\uae4c 1869\ub144 \uc5f4\ub9b0 \ubb3c\uae38\uacfc \uc774\uc9d1\ud2b8\uc758 \uc8fc\uc2dd\u00b7\ubd80\ucc44\u00b7\uc8fc\uad8c 1881\ub144 \uc2e4\uc81c \ub3c4\ud310\uc744 \ubcf4\uba70 \uc6b4\ud558 \uac74\uc124\uacfc \ub178\ub3d9, 1875\ub144 \uc9c0\ubd84 \ub9e4\uac01, \uc601\uad6d\uc758 \uac1c\uc785\uc73c\ub85c \uc774\uc5b4\uc9c4 \uc5ed\uc0ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Middle East \uc5ed\uc0ac \ubc30\uac00 \uc720\ub7fd\uc5d0\uc11c \uc544\uc2dc\uc544\ub85c \uac00\ub824\uba74 \uc544\ud504\ub9ac\uce74 \ub0a8\ucabd\uc744 \ud06c\uac8c \ub3cc\uc544\uc57c \ud588\ub2e4. \uc9c0\uc911\ud574\uc640 \ud64d\ud574 \uc0ac\uc774\ub97c \uac00\ub85c\uc9c0\ub974\ub294 \ubb3c\uae38\uc774 \uc5f4\ub9b0\ub2e4\uba74 \ud56d\ub85c\uc758 \ubaa8\uc591\uc740 \ud06c\uac8c \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc5c8\ub2e4. \uc9c0\ub3c4 \uc704\uc758 \uc9e7\uc740 \uc120 \ud558\ub098\uac00 \uc138\uacc4\uc758 \ubc30\uac00 \uc6c0\uc9c1\uc774\ub294 \ubc29\uc2dd\uc744 \ubc14\uafb8\ub294 \uc148\uc774\ub2e4. 1869\ub144 \uc218\uc5d0\uc988 \uc6b4\ud558\uac00 \uac1c\ud1b5\ud588\ub2e4. \ud558\uc9c0\ub9cc \uc0c8\ub85c\uc6b4 \uae38\uc744 \ub9cc\ub4e0 \uc5ed\uc0ac\ub294 \ubc30\uac00 \ud3b8\ub9ac\ud574\uc84c\ub2e4\ub294 \uc774\uc57c\uae30\ub85c\ub9cc \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \uc774\uc9d1\ud2b8\uc758 \ub178\ub3d9\uacfc \uc815\ubd80\uc758 \ube5a, \uc6b4\ud558 \ud68c\uc0ac\uc758 \uc9c0\ubd84\uacfc \uc720\ub7fd \uac15\ub300\uad6d\uc758 \uc774\ud574\uad00\uacc4\uac00 \uac19\uc740 \ubb3c\uae38\uc5d0 \ubaa8\uc600\ub2e4. \uc218\uc5d0\uc988 \uc9c0\ud611\uc740 \uc9c0\uc911\ud574\uc640 \ud64d\ud574 \uc0ac\uc774\ub97c \ub098\ub204\uace0 \uc788\uc5c8\ub2e4. \uc774\uacf3\uc5d0 \uc6b4\ud558\ub97c \ub9cc\ub4e4\uba74 \ubc30\ub294 \uc544\ud504\ub9ac\uce74 \ub0a8\ub2e8\uc744 \ub3cc\uc544\uac00\uc9c0 \uc54a\uace0 \uc778\ub3c4\uc591 \ubc29\ud5a5\uc73c\ub85c \ub098\uc544\uac08 \uc218 \uc788\ub2e4. \uad50\uc7ac\ub294 \uc774\ub7f0 \uc5f0\uacb0\uc774 \ub0a8\uc544\uc2dc\uc544\uc640 \ub3d9\uc544\uc2dc\uc544\ub85c \uac00\ub294 \ubb34\uc5ed\uc744 \ud06c\uac8c \uc27d\uac8c \ud560 \uc218 \uc788\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub2e4\ub9cc \uc9c0\ub3c4\uc5d0\uc11c \uc120\uc774 \uc9e7\uc544 \ubcf4\uc778\ub2e4\uace0 \uacf5\uc0ac\uae4c\uc9c0 \uac04\ub2e8\ud55c \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ubb3c\uae38\uc744 \uc2e4\uc81c\ub85c \ud30c\uace0 \uc6b4\uc601\ud558\ub824\uba74 \ud5c8\uac00\uc640 \uc790\uae08, \uae30\uc220\uacfc \ub178\ub3d9\uc744 \ub9c8\ub828\ud574\uc57c \ud588\ub2e4. \uc9c0\ub9ac\uc801\uc778 \uac00\ub2a5\uc131\uc744 \ud604\uc2e4\uc758 \uae38\ub85c \ub9cc\ub4dc\ub294 \uacfc\uc815\uc5d0\ub294 \uc5ec\ub7ec \uc885\ub958\uc758 \uacb0\uc815\uc774 \ud544\uc694\ud588\ub2e4. 1854\ub144 \ud504\ub791\uc2a4\uc758 \uc678\uad50\uad00\uc774\uc790 \uc0ac\uc5c5\uac00 \ud398\ub974\ub514\ub0ad \ub4dc \ub808\uc149\uc2a4\ub294 \uc774\uc9d1\ud2b8\uc758 \uc0ac\uc774\ub4dc \ud30c\uc0e4\uc5d0\uac8c \uc6b4\ud558 \uac74\uc124 \ud5c8\uac00\ub97c \uc694\uccad\ud588\ub2e4. \ud5c8\uac00\ub97c \uc5bb\uc740 \ub4a4 \uc0ac\uc5c5\uc744 \ucd94\uc9c4\ud588\uace0 1859\ub144 \uacf5\uc0ac\uac00 \uc2dc\uc791\ub418\uc5c8\ub2e4. \uad6d\uc81c\uc801\uc778 \uae30\uc220\uacfc \uc790\uae08\uc758 \uad00\uc2ec\uc774 \uc774\uc9d1\ud2b8 \uc601\ud1a0 \uc704\uc5d0\uc11c \uad6c\uccb4\uc801\uc778 \uc0ac\uc5c5\uc774 \ub41c \uac83\uc774\ub2e4. \uc5ec\uae30\uc5d0\ub294 \uc720\ub7fd\uc778\uc758 \uacc4\ud68d\ub9cc \uc788\uc5c8\ub358 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc774\uc9d1\ud2b8 \ud1b5\uce58\uc790\uc758 \uc2b9\uc778\uacfc \uad6d\uac00\uc758 \uc790\uc6d0, \ud604\uc7a5\uc5d0\uc11c \uc77c\ud560 \uc0ac\ub78c\ub4e4\uc774 \ud544\uc694\ud588\ub2e4. \uc6b4\ud558\ub97c \uc720\uba85\ud55c \uc124\uacc4\uc790 \ud55c \uc0ac\ub78c\uc758 \uc791\ud488\ucc98\ub7fc \uc77d\uc73c\uba74 \uadf8 \uae38\uc774 \uc5b4\ub5a4 \uc815\uce58\uc801 \uad00\uacc4\uc640 \ub178\ub3d9 \uc704\uc5d0 \ub9cc\ub4e4\uc5b4\uc84c\ub294\uc9c0 \ub193\uce58\uae30 \uc27d\ub2e4. \uad50\uc7ac\ub294 \uc218\uc5d0\uc988 \uc6b4\ud558 \uc77c\ubd80\uc758 \uac74\uc124\uc5d0 \uc774\uc9d1\ud2b8\uc758 \uac15\uc81c \ub3d9\uc6d0 \ub178\ub3d9\uc774 \uc0ac\uc6a9\ub418\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc138\uacc4\uc758 \uad50\ud1b5\uc744 \ud3b8\ub9ac\ud558\uac8c \ub9cc\ub4dc\ub294 \uacf5\uc0ac\uc600\uc9c0\ub9cc \uadf8 \ud3b8\ub9ac\ud568\uc744 \ub9cc\ub4e0 \uc0ac\ub78c\ub4e4\uc758 \uacbd\ud5d8\uae4c\uc9c0 \uac00\ubcbc\uc6e0\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubc30\uc758 \uc774\ub3d9 \uc2dc\uac04\uc774 \uc904\uc5b4\ub4dc\ub294 \ud6a8\uacfc\uc640 \ud604\uc7a5\uc758 \ubd80\ub2f4\uc740 \ub2e4\ub978 \uc790\ub9ac\uc5d0\uc11c \ub098\ud0c0\ub0ac\ub2e4. \uc774\ubc88 \uae00\uc740 \ud655\uc778\ud558\uc9c0 \uc54a\uc740 \uc0ac\ub9dd\uc790 \uc218\ub098 \ud2b9\uc815 \ub178\ub3d9\uc790\uc758 \ud558\ub8e8\ub97c \ucc3d\uc791\ud558\uc9c0 \uc54a\ub294\ub2e4. \ub2e4\ub9cc \uac15\uc81c\ub85c \uc77c\uc744 \ud574\uc57c \ud588\ub358 \uc0ac\ub78c\ub4e4\uc774 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uac74\uc124\uc758 \uc911\uc694\ud55c \ubd80\ubd84\uc774\ub2e4. \uae30\ub150\ube44\uc801\uc778 \uae30\uc220\uc758 \uc5ed\uc0ac\ub97c \uc77d\uc744 \ub54c \ub204\uac00 \uc5b4\ub5a4 \uc870\uac74\uc73c\ub85c \uadf8\uac83\uc744 \ub9cc\ub4e4\uc5c8\ub294\uc9c0 \ud568\uaed8 \ubb3c\uc5b4\uc57c \ud55c\ub2e4. \uc6b4\ud558\ub294 1869\ub144 \uc120\ubc15 \ud1b5\ud589\uc5d0 \uc5f4\ub838\ub2e4. \uad50\uc7ac\uc5d0 \ub530\ub974\uba74 \uc601\uad6d\uc740 \ucc98\uc74c\ubd80\ud130 \uc774 \uc0ac\uc5c5\uc744 \ubc18\uae30\uae30\ub9cc \ud55c \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc544\ud504\ub9ac\uce74 \ub0a8\ub2e8\uc744 \uc9c0\ub098\ub294 \uae30\uc874 \ud56d\ub85c\uc5d0\uc11c\uc758 \uc6b0\uc704\uc640, \uc778\ub3c4\uc5d0 \uc811\uadfc\ud558\ub294 \uae38\uc774 \ub2ec\ub77c\uc9c0\ub294 \ubb38\uc81c\uac00 \uc788\uc5c8\uae30 \ub54c\ubb38\uc774\ub2e4. \uc0c8 \uae38\uc740 \ubaa8\ub450\uc5d0\uac8c \uac19\uc740 \uc758\ubbf8\uac00 \uc544\ub2c8\uc5c8\ub2e4. \ub204\uad70\uac00\uc5d0\uac8c\ub294 \uc774\ub3d9\uc758 \ud6a8\uc728\uc774\uc9c0\ub9cc \ub2e4\ub978 \uc138\ub825\uc5d0\uac8c\ub294 \uae30\uc874\uc758 \uc6b0\uc704\uac00 \ud754\ub4e4\ub9b4 \uac00\ub2a5\uc131\uc774\uc5c8\ub2e4. \uc6b4\ud558\uac00 \uae30\uc220\uc801\uc73c\ub85c \uac00\ub2a5\ud55c\uac00\uc640 \ub204\uac00 \uadf8 \uae38\uc744 \uc720\ub9ac\ud558\uac8c \uc774\uc6a9\ud558\ub294\uac00\ub294 \ub2e4\ub978 \uc9c8\ubb38\uc774\uc5c8\ub2e4. \ubb3c\uae38\uc774 \uc5f4\ub9ac\ub294 \uc21c\uac04\uc5d0\ub3c4 \uacbd\uc7c1\uc758 \uc9c0\ub3c4\ub294 \ud568\uaed8 \uadf8\ub824\uc9c0\uace0 \uc788\uc5c8\ub2e4. \uc0ac\uc774\ub4dc\uc758 \ub4a4\ub97c \uc774\uc740 \uc774\uc2a4\ub9c8\uc77c \ud30c\uc0e4\ub294 \uc720\ub7fd\uc758 \ucc44\uad8c\uc790\ub4e4\uc5d0\uac8c \ud070 \ube5a\uc744 \uc9c0\uac8c \ub418\uc5c8\ub2e4. 1875\ub144 \uadf8\ub294 \uc774\uc9d1\ud2b8\uac00 \uac00\uc9c4 \uc6b4\ud558 \ud68c\uc0ac\uc758 \uc9c0\ubd84\uc744 \uc601\uad6d\uc5d0 \ud314\uc558\ub2e4. \uad50\uc7ac\ub294 \ubd80\ucc44\uac00 \uc774\uc9d1\ud2b8 \uc815\ubd80\uc5d0 \ub300\ud55c \uc720\ub7fd\uc758 \uc601\ud5a5\ub825\uc744 \ud0a4\uc6b0\ub294 \uc870\uac74\uc774 \ub418\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc774\ub54c \uc6b4\ud558\uc758 \ubb3c\ub9ac\uc801\uc778 \uc18c\uc720\uc640 \ud68c\uc0ac \uc8fc\uc2dd, \uc815\ubd80\uc758 \uc8fc\uad8c\uc744 \ud55c \uac00\uc9c0\ub85c \uc11e\uc9c0 \uc54a\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4. \uc9c0\ubd84\uc744 \uc0c0\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uace7 \uadf8\ub0a0 \uc774\uc9d1\ud2b8 \uc804\uccb4\ub97c \uc601\ud1a0\ub85c \uc5bb\uc5c8\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \ud68c\uc0ac\uc640 \uad6d\uac00\uc758 \uc7ac\uc815 \uad00\uacc4\uac00 \uc815\uce58\uc801 \uac1c\uc785\uc758 \uae38\uc744 \ub113\ud614\ub2e4. \ubaa8\ub4e0 \ube5a\uc774 \uc6b4\ud558 \ud558\ub098 \ub54c\ubb38\uc5d0 \uc0dd\uacbc\ub2e4\uace0 \ub2e8\uc815\ud560 \uc218\ub3c4 \uc5c6\ub2e4. \uc601\uad6d\uacfc \ud504\ub791\uc2a4\uc758 \uad00\ub9ac\ub4e4\uc774 \uc774\uc9d1\ud2b8\uc758 \uc7ac\uc815\uc5d0 \uad00\uc5ec\ud588\uace0 \uc678\uc138\uc758 \uc601\ud5a5\uc5d0 \ubc18\ubc1c\ud558\ub294 \uc6c0\uc9c1\uc784\ub3c4 \ucee4\uc84c\ub2e4. \uad50\uc7ac\ub294 \uc544\ud750\uba54\ub4dc \uc6b0\ub77c\ube44\uac00 \uc774\ub048 \ubc18\ubc1c\uacfc \ud1b5\uce58\uc790\ub97c \ub458\ub7ec\uc2fc \uac08\ub4f1, 1882\ub144 \uc601\uad6d\uc758 \uad70\uc0ac \uac1c\uc785\uc73c\ub85c \uc774\uc5b4\uc9c4 \uacfc\uc815\uc744 \uc124\uba85\ud55c\ub2e4. \uc774 \uc0ac\uac74\ub4e4\uc744 \uc6b4\ud558\ub97c \uc0c0\uc73c\ub2c8 \uc804\uc7c1\ub3c4 \uc790\ub3d9\uc73c\ub85c \ub530\ub77c\uc654\ub2e4\ub294 \ud55c \uc904\ub85c \uc904\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \uad6d\ub0b4 \uc815\uce58\uc640 \ub300\uc678 \uad00\uacc4, \uc7ac\uc815\uacfc \uad70\uc0ac\uc758 \uc5ec\ub7ec \uc774\ud574\uad00\uacc4\uac00 \uc5bd\ud614\ub2e4. \ub2e4\ub9cc \uc138\uacc4\ub97c \uc787\ub294 \ubb3c\uae38\uacfc \uc774\uc9d1\ud2b8\uc758 \ub3c8 \ubb38\uc81c\uac00 \ud1b5\uce58\uc758 \ubb38\uc81c\ub85c \uae4a\uc774 \uc5f0\uacb0\ub418\uc5c8\ub2e4\ub294 \ud750\ub984\uc740 \ubd84\uba85\ud788 \ubcfc \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc2e4\uc81c \ub3c4\ud310\uc740 1881\ub144 \ubc31\uacfc\uc0ac\uc804\uc5d0 \ub098\uc628 \uc218\uc5d0\uc988 \uc6b4\ud558\uc758 \uacbd\ub85c\ub2e4. \uc704\ucabd \uc9c0\uc911\ud574\uc5d0\uc11c \uc544\ub798\ucabd \ud64d\ud574\ub85c \uc774\uc5b4\uc9c0\ub294 \uc120\uc744 \ub530\ub77c\uac00 \ubcf4\uc790. \uc0ac\ub78c\uacfc \ubc30\ubcf4\ub2e4 \uacbd\ub85c\uc758 \uc5f0\uacb0\uc744 \ud55c\ub208\uc5d0 \ubcf4\uac8c \ub9cc\ub4dc\ub294 \uadf8\ub9bc\uc774\ub2e4. \ud604\uc7ac\uc758 \uc6b4\ud558 \uc2dc\uc124\uc774\ub098 \ucd5c\uc2e0 \ud56d\ub85c \uc548\ub0b4\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uc9c0\ub3c4\ub294 \uc544\ub2c8\ub2e4. \uadf8\ub9bc\uc774 \uc81c\uc791\ub41c \uc2dc\uc810\uc740 \uac1c\ud1b5 \ub4a4\uc774\uba74\uc11c \uc601\uad6d\uc758 1882\ub144 \uac1c\uc785\ubcf4\ub2e4\ub294 \uc55e\uc120 \ub54c\ub2e4. \ud55c \uc7a5\uc758 \uc9c0\ub9ac \uc790\ub8cc\ub3c4 \uc5b4\ub290 \uc2dc\uac04\uc5d0 \ub9cc\ub4e4\uc5b4\uc84c\ub294\uc9c0 \uc54c\uba74 \ub2e4\ub978 \uc5ed\uc0ac\uc801 \uc790\ub9ac\uc5d0 \ub193\uc778\ub2e4. \ub2e8\uc21c\ud55c \uc9c0\ub984\uae38\ucc98\ub7fc \ubcf4\uc774\ub294 \uc120 \uc704\uc5d0\uc11c \uadf8 \ubb34\ub835 \uc5b4\ub5a4 \uc120\ud0dd\ub4e4\uc774 \uc9c4\ud589\ub418\uace0 \uc788\uc5c8\ub294\uc9c0 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \uc218\uc5d0\uc988 \uc6b4\ud558\ub294 \ubc14\ub2e4 \uc0ac\uc774\uc758 \uac70\ub9ac\ub97c \uc904\uc600\uc9c0\ub9cc \uadf8 \uc774\uc775\uacfc \ubd80\ub2f4\uc744 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ub098\ub204\uc9c0\ub294 \uc54a\uc558\ub2e4. \ud56d\ub85c\uac00 \uc9e7\uc544\uc9c4 \ubc30\uc640 \uac15\uc81c\ub85c \ub3d9\uc6d0\ub41c \ub178\ub3d9\uc790, \uc7ac\uc815\uc744 \ub9c8\ub828\ud558\ub824\ub358 \uc815\ubd80\uc640 \uc601\ud5a5\ub825\uc744 \ub113\ud78c \uac15\ub300\uad6d\uc740 \uac19\uc740 \uacf5\uc0ac\ub97c \uc11c\ub85c \ub2e4\ub974\uac8c \uacaa\uc5c8\ub2e4. \ub2e4\uc74c\uc5d0 \uc6b4\ud558\uc640 \ucca0\ub3c4 \uac19\uc740 \ud070 \uae38\uc744 \ubcf4\uba74 \uc5bc\ub9c8\ub098 \ube68\ub77c\uc84c\ub294\uc9c0\uc640 \ud568\uaed8 \ub204\uac00 \ub9cc\ub4e4\uace0 \ub204\uac00 \ud1b5\uc81c\ud588\ub294\uc9c0\ub3c4 \uc0b4\ud3b4\ubcf4\uc790. \uc218\uc5d0\uc988\uc758 \ubb3c\uae38\uc740 \uae30\uc220\uc758 \uc131\uacf5\uacfc \uae08\uc735\uc758 \uc5f0\uacb0, \uc815\uce58\uc801 \ud798\uc774 \ud55c \uc9c0\ub3c4 \uc704\uc5d0 \ub193\uc774\ub294 \uacfc\uc815\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uadf8\ub54c \uc9c0\ub984\uae38\uc758 \uc5ed\uc0ac\ub294 \uc138\uacc4\ub97c \uc774\ud574\ud558\ub294 \ud6e8\uc52c \uae34 \uc774\uc57c\uae30\uac00 \ub41c\ub2e4."}, {"id": "alexandria-museion-and-books", "title": "\uc54c\ub809\uc0b0\ub4dc\ub9ac\uc544 \u2014 \ud56d\uad6c \ub3c4\uc2dc\ub294 \uc65c \ud559\uc790\ub4e4\uc744 \ubaa8\uc558\uc744\uae4c", "summary": "\ubb34\uc138\uc774\uc628\uacfc \ub3c4\uc11c\uad00\uc744 \ud1b5\ud574 \ud5ec\ub808\ub2c8\uc998 \ub3c4\uc2dc\uc758 \ud559\ubb38\u00b7\uc5b8\uc5b4\u00b7\uc815\uce58 \ud6c4\uc6d0\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "cities", "category_title": "Cities", "subcategory": "Africa", "url": "stories/alexandria-museion-and-books/index.html", "image": "media/alexandria-museion-and-books.png", "alt": "\ud56d\uad6c\uac00 \ubcf4\uc774\ub294 \uc0c1\uc0c1 \uc18d \ubc29\uc5d0\uc11c \ub450 \uc0ac\ub78c\uc774 \ub450\ub8e8\ub9c8\ub9ac\ub97c \uc0b4\ud53c\ub294 \uc0bd\ud654.", "text": "\uc54c\ub809\uc0b0\ub4dc\ub9ac\uc544 \u2014 \ud56d\uad6c \ub3c4\uc2dc\ub294 \uc65c \ud559\uc790\ub4e4\uc744 \ubaa8\uc558\uc744\uae4c \ubc15\ubb3c\uad00\uc774\ub77c\ub294 \ub9d0\uc758 \uba3c \ucd9c\ubc1c\uc810\uc5d0\uc11c \ub9cc\ub098\ub294 \uc5f0\uad6c\uc640 \ud6c4\uc6d0 \ubb34\uc138\uc774\uc628\uacfc \ub3c4\uc11c\uad00\uc744 \ud1b5\ud574 \ud5ec\ub808\ub2c8\uc998 \ub3c4\uc2dc\uc758 \ud559\ubb38\u00b7\uc5b8\uc5b4\u00b7\uc815\uce58 \ud6c4\uc6d0\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Africa \ub3c4\uc2dc \ud56d\uad6c\uc5d0\ub294 \ubc30\uc640 \ubb3c\uac74\uc774 \ubaa8\uc778\ub2e4. \uadf8\ub7f0\ub370 \uace0\ub300 \uc54c\ub809\uc0b0\ub4dc\ub9ac\uc544\uc5d0\ub294 \ud559\uc790\uc640 \ucc45\ub3c4 \ubaa8\uc600\ub2e4. \uc2dc\uc7a5\uc5d0\uc11c \uac70\ub798\ud558\ub294 \uc9d0\uacfc \uc5f0\uad6c\uc5d0 \uc4f0\ub294 \ub450\ub8e8\ub9c8\ub9ac\ub294 \ub2e4\ub974\uc9c0\ub9cc, \uba40\ub9ac \uc788\ub294 \uac83\uc744 \ud55c\uacf3\uc5d0 \ubaa8\uc740\ub2e4\ub294 \uc810\uc5d0\uc11c\ub294 \ub2ee\uc740 \ubaa8\uc2b5\uc774 \uc788\ub2e4. \uc774 \ub3c4\uc2dc\uc758 \ub3c4\uc11c\uad00\uc740 \ub108\ubb34 \uc720\uba85\ud574\uc11c \uc0ac\ub77c\uc9c4 \uc21c\uac04\uc758 \uc774\uc57c\uae30\ub9cc \uba3c\uc800 \ub5a0\uc62c\ub9ac\uae30\ub3c4 \ud55c\ub2e4. \uc624\ub298\uc740 \ubd88\uae38 \ub300\uc2e0 \uadf8\ubcf4\ub2e4 \uc55e\uc120 \uc9c8\ubb38\uc5d0\uc11c \uc2dc\uc791\ud574 \ubcf4\uc790. \ub204\uac00 \uc65c \uc774\ub7f0 \ub3c4\uc2dc\uc5d0\uc11c \ud559\ubb38\uc744 \ud6c4\uc6d0\ud588\uace0, \uc0ac\ub78c\ub4e4\uc774 \ub9d0\ud558\ub294 \ubb34\uc138\uc774\uc628\uc740 \uc5b4\ub5a4 \uacf5\uac04\uc774\uc5c8\uc744\uae4c. \uc54c\ub809\uc0b0\ub4dc\ub9ac\uc544\ub294 \uc54c\ub809\uc0b0\ub4dc\ub85c\uc2a4\uac00 \uae30\uc6d0\uc804 331\ub144\uc5d0 \uc138\uc6e0\ub2e4. \uadf8\uc758 \uc8fd\uc74c \ub4a4 \uc81c\uad6d\uc740 \uc5ec\ub7ec \ud6c4\uacc4\uc790\uc758 \uc655\uad6d\uc73c\ub85c \ub098\ub258\uc5c8\uace0, \uc774\uc9d1\ud2b8\ub294 \ud504\ud1a8\ub808\ub9c8\uc774\uc624\uc2a4 \uc655\uc870\uc758 \uc9c0\ubc30 \uc544\ub798 \ub4e4\uc5b4\uac14\ub2e4. \uc54c\ub809\uc0b0\ub4dc\ub9ac\uc544\ub294 \uadf8 \uc655\uad6d\uc758 \uc218\ub3c4\uac00 \ub418\uc5c8\ub2e4. \uc0c8 \ub3c4\uc2dc\ub294 \uc774\ub984\ub09c \uc815\ubcf5\uc790\uc758 \uae30\ub150\ube44\uc778 \ub3d9\uc2dc\uc5d0 \ud6c4\uacc4 \uc655\uc870\uac00 \ud1b5\uce58\ud558\ub294 \ud604\uc2e4\uc758 \uc911\uc2ec\uc774\uc5c8\ub2e4. \uac74\ubb3c\uc744 \uc138\uc6b0\uace0 \uc0ac\ub78c\uc744 \ubaa8\uc73c\uba70 \uadf8\uacf3\uc744 \uc911\uc694\ud55c \uc7a5\uc18c\ub85c \ub9cc\ub4dc\ub294 \uc120\ud0dd\uc774 \uc774\uc5b4\uc84c\ub2e4. \ub3c4\uc2dc\uc758 \ubb38\ud654\uc801 \uba85\uc131\uc744 \ucc3d\uac74\uc790 \ud55c \uc0ac\ub78c\uc758 \uad6c\uc0c1\uc73c\ub85c\ub9cc \uc124\uba85\ud558\uae30 \uc5b4\ub824\uc6b4 \uc774\uc720\ub2e4. \ud504\ud1a8\ub808\ub9c8\uc774\uc624\uc2a4 \uc655\ub4e4\uc740 \ubb34\uc138\uc774\uc628\uc744 \uc138\uc6e0\ub2e4. \uc774\ub984\uc740 \ubb34\uc0ac\uc774, \uc989 \uc608\uc220\uacfc \ud559\ubb38\uc5d0 \uad00\ub828\ub41c \uc5ec\uc2e0\ub4e4\uc758 \uc9d1\uc774\ub77c\ub294 \ub73b\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uc624\ub298\ub0a0 \ubc15\ubb3c\uad00\uc744 \uac00\ub9ac\ud0a4\ub294 museum\uc774\ub77c\ub294 \ub9d0\uc758 \uc5b4\uc6d0\ub3c4 \uc5ec\uae30\uc5d0\uc11c \ub098\uc628\ub2e4. \ud558\uc9c0\ub9cc \ub2f9\uc2dc\uc758 \ubb34\uc138\uc774\uc628\uc744 \uc624\ub298\ub0a0 \uad00\ub78c\uac1d\uc774 \uc804\uc2dc\ud488 \uc0ac\uc774\ub97c \uac77\ub294 \ubc15\ubb3c\uad00\uacfc \ub611\uac19\uc774 \uc0dd\uac01\ud558\uba74 \uace4\ub780\ud558\ub2e4. \uad50\uc7ac\ub294 \uc774\ub97c \uacfc\ud559 \uc5f0\uad6c\uc640 \ubb38\ud559 \uc5f0\uad6c\uc758 \uc911\uc2ec\uc73c\ub85c \uc124\uba85\ud55c\ub2e4. \uc775\uc219\ud55c \ub2e8\uc5b4\uc758 \uc5b4\uc6d0\uc744 \uc548\ub2e4\ub294 \uac83\uc740 \ud604\uc7ac\uc758 \uae30\ub2a5\uae4c\uc9c0 \uacfc\uac70\uc5d0 \uadf8\ub300\ub85c \uc788\uc5c8\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ud559\uc790\uc758 \ub2a5\ub825\ub9cc\uc73c\ub85c \ud559\ubb38\uc758 \uc911\uc2ec\uc774 \uc800\uc808\ub85c \uc0dd\uae30\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud65c\ub3d9\uc744 \uc9c0\uc18d\ud560 \uacf5\uac04\uacfc \uc790\uc6d0, \ub2e4\ub978 \uc0ac\ub78c\uacfc \uc9c0\uc2dd\uc744 \ub098\ub20c \uc870\uac74\uc774 \uc788\uc5b4\uc57c \ud55c\ub2e4. \uc655\ub4e4\uc774 \uc774\ub7f0 \uae30\uad00\uc744 \ud6c4\uc6d0\ud588\ub2e4\ub294 \uc810\uc740 \uc5f0\uad6c\uc758 \uc5ed\uc0ac\uc640 \uc815\uce58\uc758 \uc5ed\uc0ac\uac00 \ub9cc\ub098\ub294 \ubd80\ubd84\uc774\ub2e4. \uc774\ub97c \uc624\ub298\ub0a0\uc758 \ub300\ud559\uc774\ub098 \uc5f0\uad6c\uc18c \uc870\uc9c1\uacfc \uc77c\ub300\uc77c\ub85c \ub9de\ucd9c \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5ec\uae30\uc11c \ud655\uc778\ud55c \uc0ac\uc2e4\uc740 \uc655\uc870\uac00 \ud559\ubb38 \uae30\uad00\uacfc \ucc45\uc758 \uc218\uc9d1\uc744 \uc9c0\uc6d0\ud588\ub2e4\ub294 \uc810\uc774\ub2e4. \uadf8 \uc9c0\uc6d0\uc740 \uc5b4\ub5a4 \uc9c0\uc2dd\uc774 \ud55c\uacf3\uc5d0 \ubaa8\uc774\uace0 \ub3c4\uc2dc\uc758 \uc704\uc0c1\uc744 \ub9cc\ub4dc\ub294\uc9c0\uc5d0 \uc601\ud5a5\uc744 \uc8fc\uc5c8\ub2e4. \uc54c\ub809\uc0b0\ub4dc\ub9ac\uc544\uc758 \ub3c4\uc11c\uad00\uc5d0\ub294 \ub9ce\uc740 \ucc45\uc774 \uc218\uc9d1\ub418\uc5c8\ub2e4. \ub2f9\uc2dc\uc758 \ucc45\uc740 \uc624\ub298\ub0a0 \uc11c\uc810\uc758 \uc81c\ubcf8 \ucc45\ub9cc\uc744 \ub5a0\uc62c\ub824\uc11c\ub294 \uc548 \ub41c\ub2e4. \ub450\ub8e8\ub9c8\ub9ac \uac19\uc740 \ub9e4\uccb4\ub85c \uae30\ub85d\ub41c \uc800\uc220\uc744 \ubaa8\uc544 \uc77d\uace0 \ube44\uad50\ud558\ub294 \ud65c\ub3d9\uc774\uc5c8\ub2e4. \uc774 \uae00\uc740 \ud2b9\uc815 \uc11c\uac00\uc758 \ubc30\uce58\ub098 \uc18c\uc7a5 \uc218\ub97c \ubcf5\uc6d0\ud558\uc9c0 \uc54a\ub294\ub2e4. \ucc45\uc774 \ub9ce\ub2e4\ub294 \uac83\uc740 \uc11c\ub85c \ub2e4\ub978 \uae00\uc744 \ub9cc\ub0a0 \uae30\ud68c\uac00 \ub298\uc5b4\ub09c\ub2e4\ub294 \ub73b\uc774\ub2e4. \uac19\uc740 \uc8fc\uc81c\uc758 \ub2e4\ub978 \uc124\uba85\uc744 \ube44\uad50\ud558\uace0 \uc55e\uc120 \uc0ac\ub78c\uc758 \uc9c0\uc2dd\uc744 \ub2e4\uc2dc \uc77d\uc744 \uc218 \uc788\ub2e4. \ud559\ubb38\uc758 \uc911\uc2ec\uc774\ub77c\ub294 \uba85\uc131\uc740 \ub6f0\uc5b4\ub09c \uac1c\uc778\ub9cc\uc758 \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub77c \uadf8\uac00 \ub9cc\ub0a0 \uc218 \uc788\ub358 \uc790\ub8cc\uc758 \ud658\uacbd\uacfc\ub3c4 \uc5f0\uacb0\ub41c\ub2e4. \ud5ec\ub808\ub2c8\uc998 \uc2dc\ub300\uc758 \uc54c\ub809\uc0b0\ub4dc\ub9ac\uc544\uc5d0\ub294 \uadf8\ub9ac\uc2a4\uc5b4\ub97c \uc4f0\ub294 \uc0ac\ub78c\uacfc \uc774\uc9d1\ud2b8\uc758 \uae30\uc874 \uc8fc\ubbfc, \uc774\uc8fc\ud55c \uc5ec\ub7ec \uacf5\ub3d9\uccb4\uac00 \uc788\uc5c8\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc5b8\uc5b4\uc640 \uc804\ud1b5\uc774 \ud55c \ub3c4\uc2dc \uc548\uc5d0\uc11c \ub9cc\ub0ac\ub2e4. \uad8c\ub825\uc758 \uc911\uc2ec\uacfc \uc77c\uc0c1\uc758 \uc5b8\uc5b4\uac00 \uc5b8\uc81c\ub098 \ub611\uac19\uc740 \ud615\ud0dc\ub85c \uc815\ub9ac\ub418\ub294 \uacf5\uac04\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uadf8\ub9ac\uc2a4\uc5b4\ub85c \ud65c\ub3d9\ud558\ub294 \uc0ac\ub78c\ub4e4\uc758 \uc99d\uac00\uc640 \uc815\uce58\uc801 \ud658\uacbd\uc740 \uc9c0\uc2dd\uc774 \uc774\ub3d9\ud558\ub294 \ubc29\uc2dd\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc8fc\uc5c8\ub2e4. \uc5b4\ub5a4 \uae00\uc744 \ub204\uad6c\uc758 \uc5b8\uc5b4\ub85c \uc77d\uac8c \ud560\uc9c0\uc758 \ubb38\uc81c\uac00 \uc0dd\uae34\ub2e4. \ub3c4\uc2dc\uc758 \ud559\ubb38\uc744 \ubb38\ud654\uac00 \uc11e\uc600\ub2e4\ub294 \ub9c9\uc5f0\ud55c \ub9d0\ub85c\ub9cc \uc124\uba85\ud558\uae30\ubcf4\ub2e4 \uc2e4\uc81c\ub85c \uc77d\uace0 \uac00\ub974\uce58\ub294 \uc5b8\uc5b4\ub97c \uc0dd\uac01\ud574 \ubcfc \uc218 \uc788\ub2e4. \uad50\uc7ac\ub294 \ud504\ud1a8\ub808\ub9c8\uc774\uc624\uc2a4 \uc2dc\ub300\uc5d0 \ud788\ube0c\ub9ac \uacbd\uc804\uc774 \uadf8\ub9ac\uc2a4\uc5b4\ub85c \ubc88\uc5ed\ub418\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc54c\ub809\uc0b0\ub4dc\ub9ac\uc544\uc5d0 \uc774\uc8fc\ud55c \uc720\ub300\uc778 \uacf5\ub3d9\uccb4\uc758 \uc874\uc7ac\uc640\ub3c4 \uc5f0\uacb0\ub418\ub294 \ubcc0\ud654\ub2e4. \uc5b4\ub5a4 \uc804\ud1b5\uc758 \uae00\uc774 \ub2e4\ub978 \uc5b8\uc5b4\ub97c \uc0ac\uc6a9\ud558\ub294 \uc0ac\ub78c\uc5d0\uac8c \uc77d\ud790 \uc218 \uc788\uac8c \ub41c \uac83\uc774\ub2e4. \uc5ec\uae30\uc11c \ubc88\uc5ed\uc5d0 \uad00\ud55c \uc720\uba85\ud55c \uc22b\uc790\uc640 \uae30\uc801\uc758 \uc77c\ud654\ub97c \uc0ac\uc2e4\ub85c \ub367\ubd99\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \ud655\uc778\ud560 \uc218 \uc788\ub294 \ud575\uc2ec\ub9cc\uc73c\ub85c\ub3c4 \ud765\ubbf8\ub86d\ub2e4. \ucc45\uc744 \uc62e\uae34\ub2e4\ub294 \uac83\uc740 \uc885\uc774 \ubb49\uce58\ub97c \uc7a5\uc18c\ub9cc \ubc14\uafb8\ub294 \uc77c\ubfd0 \uc544\ub2c8\ub77c, \uadf8 \uae00\uc744 \uc77d\uc744 \uc218 \uc788\ub294 \uc0ac\ub78c\uc758 \ubc94\uc704\ub97c \ubc14\uafb8\ub294 \uc77c\uc774\uae30\ub3c4 \ud588\ub2e4. \uc54c\ub809\uc0b0\ub4dc\ub9ac\uc544\uc758 \ub3c4\uc11c\uad00\uc744 \ud55c \ubc88\uc758 \ud654\uc7ac\uc640 \ud55c \uba85\uc758 \ucc45\uc784\uc790\ub85c\ub9cc \uc124\uba85\ud558\ub294 \uc774\uc57c\uae30\ub294 \uc870\uc2ec\ud574\uc11c \uc77d\uc5b4\uc57c \ud55c\ub2e4. \uc774\ubc88\uc5d0 \ud655\uc778\ud55c \uad50\uc7ac\uc758 \ubc94\uc704\ub294 \ub3c4\uc2dc\uc758 \ud615\uc131\uacfc \ud559\ubb38 \uae30\uad00\uc5d0 \uad00\ud55c \ub0b4\uc6a9\uc774\ub2e4. \ub204\uac00 \ud55c\ub0a0\uc5d0 \ubaa8\ub4e0 \ucc45\uc744 \uc5c6\uc574\ub2e4\ub294 \uc7a5\uba74\uc744 \ub9cc\ub4e4\uc5b4 \ub0bc \uadfc\uac70\ub85c \uc4f0\uc9c0 \uc54a\ub294\ub2e4. \uc720\uba85\ud55c \uc0c1\uc2e4\uc758 \uc774\uc57c\uae30\ubcf4\ub2e4 \uc55e\uc5d0 \uc624\ub798 \uc313\uc740 \ud65c\ub3d9\uc774 \uc788\uc5c8\ub2e4\ub294 \uc810\uc744 \uae30\uc5b5\ud558\uba74 \ub41c\ub2e4. \uc5f0\uad6c\ub97c \ud6c4\uc6d0\ud558\uace0 \uc800\uc220\uc744 \ubaa8\uc73c\uba70 \ubc88\uc5ed\uacfc \uc77d\uae30\ub97c \uc774\uc5b4 \uac04 \uc2dc\uac04\uc774 \ub3c4\uc2dc\uc758 \uc131\uaca9\uc744 \ub9cc\ub4e4\uc5c8\ub2e4. \uc0ac\ub77c\uc84c\ub2e4\ub294 \uacb0\ub9d0\ub9cc\uc73c\ub85c\ub294 \uadf8\uacf3\uc5d0\uc11c \ubb34\uc5c7\uc774 \uac00\ub2a5\ud588\ub294\uc9c0 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \ubc14\ub2e4\uac00 \ubcf4\uc774\ub294 \uacf3\uc5d0\uc11c \ub450\ub8e8\ub9c8\ub9ac\ub97c \ube44\uad50\ud558\ub294 \uc0ac\ub78c\ub4e4\uc744 \ud45c\ud604\ud588\ub2e4. \ubb34\uc138\uc774\uc628\uacfc \uace0\ub300 \ub3c4\uc11c\uad00\uc758 \uac74\ucd95\uc744 \uace0\uc99d\ud574 \ubcf5\uc6d0\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \ud2b9\uc815 \ud559\uc790\uc758 \uc5f0\uad6c\uc2e4\uc774\ub098 \uc2e4\uc81c \uc7a5\uba74\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uadf8\ub9bc\uc73c\ub85c \ubc1b\uc544\ub4e4\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \uc54c\ub809\uc0b0\ub4dc\ub9ac\uc544\ub97c \ub5a0\uc62c\ub9b4 \ub54c\ub294 \ubc30\uac00 \ub2ff\ub294 \uc790\ub9ac\uc640 \ucc45\uc744 \uc77d\ub294 \uc790\ub9ac\ub97c \ud568\uaed8 \ub193\uc544 \ubcf4\uc790. \ub3c4\uc2dc\ub294 \ubb3c\uac74\ubfd0 \uc544\ub2c8\ub77c \uc9c0\uc2dd\uc758 \ub3c4\ucc29\uc9c0\uac00 \ub420 \uc218 \uc788\uc5c8\ub2e4. \uc624\ub298\uc758 \ubc15\ubb3c\uad00\uc774\ub77c\ub294 \ub9d0 \ub4a4\uc5d0 \uc774\ub7f0 \uba3c \uc2dc\uac04\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c\ub3c4, \uc775\uc219\ud55c \ub2e8\uc5b4\uc640 \uc7a5\uc18c\ub97c \ubcf4\ub294 \uc990\uac70\uc6c0\uc774 \uc870\uae08 \ucee4\uc9c4\ub2e4."}, {"id": "athens-parthenon-and-tribute", "title": "\uc544\ud14c\ub124 \u2014 \ud30c\ub974\ud14c\ub17c\uc740 \ub204\uad6c\uc758 \ub3c8\uc73c\ub85c \uc9c0\uc5c8\uc744\uae4c", "summary": "\ud30c\ub974\ud14c\ub17c\uc758 \uc678\uad00\uacfc \uc544\ud14c\ub124\uc758 \ub3d9\ub9f9 \uad00\uacc4\ub97c \ud568\uaed8 \ubcf4\uba70 \ub3c4\uc2dc\uc758 \ubc88\uc601\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "cities", "category_title": "Cities", "subcategory": "Europe", "url": "stories/athens-parthenon-and-tribute/index.html", "image": "media/athens-parthenon-and-tribute.jpg", "alt": "\uc544\ud06c\ub85c\ud3f4\ub9ac\uc2a4 \uc704 \ud30c\ub974\ud14c\ub17c\uc758 \uae30\ub465\uacfc \ud604\uc7ac \ub0a8\uc544 \uc788\ub294 \uc11d\uc870 \uac74\ubb3c.", "text": "\uc544\ud14c\ub124 \u2014 \ud30c\ub974\ud14c\ub17c\uc740 \ub204\uad6c\uc758 \ub3c8\uc73c\ub85c \uc9c0\uc5c8\uc744\uae4c \uc544\ub984\ub2e4\uc6b4 \uc2e0\uc804 \uacc1\uc5d0\uc11c \ub3d9\ub9f9\uacfc \uad8c\ub825\uc744 \uc0dd\uac01\ud558\uae30 \ud30c\ub974\ud14c\ub17c\uc758 \uc678\uad00\uacfc \uc544\ud14c\ub124\uc758 \ub3d9\ub9f9 \uad00\uacc4\ub97c \ud568\uaed8 \ubcf4\uba70 \ub3c4\uc2dc\uc758 \ubc88\uc601\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Europe \ub3c4\uc2dc \uc544\ud14c\ub124\uc758 \uc544\ud06c\ub85c\ud3f4\ub9ac\uc2a4 \uc704\uc5d0\ub294 \uc9c0\ubd95\uc744 \uc783\uc740 \ud30c\ub974\ud14c\ub17c\uc774 \uc11c \uc788\ub2e4. \uc0ac\uc9c4\uc73c\ub85c \ubcf4\uba74 \uae30\ub465\uacfc \ud558\ub298\uc774 \uba3c\uc800 \ub4e4\uc5b4\uc628\ub2e4. \uc628\uc804\ud55c \uac74\ubb3c\uc774 \uc544\ub2cc\ub370\ub3c4 \ub3c4\uc2dc\ub97c \ub300\ud45c\ud558\ub294 \ubaa8\uc2b5\uc774 \ub420 \ub9cc\ud07c \uc778\uc0c1\uc774 \uac15\ud558\ub2e4. \uadf8\ub7f0\ub370 \uc774 \uc2e0\uc804\uc744 \uc138\uc6b0\ub294 \ub370 \uc4f4 \ub3c8\uc740 \uc5b4\ub514\uc5d0\uc11c \uc654\uc744\uae4c. \uac74\ucd95\uc758 \uc544\ub984\ub2e4\uc6c0\uacfc \ub3c8\uc758 \ucd9c\ucc98\ub294 \uc11c\ub85c \ubb34\uad00\ud55c \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub2e4. \ud30c\ub974\ud14c\ub17c\uc774 \ub9cc\ub4e4\uc5b4\uc9c4 \uc2dc\ub300\uc758 \uc544\ud14c\ub124\ub294 \uc608\uc220\uacfc \uc2dc\ubbfc\uc815\uce58\uc758 \ub3c4\uc2dc\uc774\uba74\uc11c \uac15\ub825\ud55c \ud574\uc0c1 \uc138\ub825\uc758 \uc911\uc2ec\uc774\uc5c8\ub2e4. \uc2e0\uc804\uc758 \uae30\ub465 \uc606\uc5d0 \ub2f9\uc2dc \ub3d9\ub9f9 \ub3c4\uc2dc\ub4e4\uc758 \uc790\ub9ac\ub3c4 \ub193\uc544 \ubcf4\uba74 \uc775\uc219\ud55c \uc720\uc801\uc774 \uc870\uae08 \ub2ec\ub9ac \ubcf4\uc778\ub2e4. \ud30c\ub974\ud14c\ub17c\uc740 \uae30\uc6d0\uc804 5\uc138\uae30\uc5d0 \uc544\ud14c\ub098\ub97c \uae30\ub9ac\uae30 \uc704\ud574 \uc138\uc6cc\uc84c\ub2e4. \uc544\ud14c\ub098\ub294 \uc544\ud14c\ub124\uc640 \ud2b9\ubcc4\ud55c \uad00\uacc4\ub97c \uac00\uc9c4 \uc5ec\uc2e0\uc774\uc5c8\ub2e4. \ub3c4\uc2dc\uc758 \ub192\uc740 \uacf3\uc5d0 \uc790\ub9ac\ud55c \ud070 \uc2e0\uc804\uc740 \uc885\uad50 \uacf5\uac04\uc774\uba74\uc11c \uc0ac\ub78c\ub4e4\uc774 \uc790\uc2e0\ub4e4\uc758 \ub3c4\uc2dc\ub97c \ubc14\ub77c\ubcf4\ub294 \uc0c1\uc9d5\uc774\uae30\ub3c4 \ud588\ub2e4. \uc624\ub298\uc758 \uc0ac\uc9c4\uc5d0\uc11c\ub294 \ub0a8\uc544 \uc788\ub294 \uae30\ub465\uacfc \uac74\ubb3c\uc758 \ubf08\ub300\ub97c \ubcfc \uc218 \uc788\ub2e4. \uc6d0\ub798\uc758 \uc0c9\uacfc \uc7a5\uc2dd, \uc9c0\ubd95\uc774 \ubaa8\ub450 \uadf8\ub300\ub85c \ub0a8\uc544 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc9c0\uae08 \ubcf4\uc774\ub294 \ud770 \ub3cc\uc758 \uc778\uc0c1\ub9cc\uc73c\ub85c \uace0\ub300\uc778\uc774 \ucc98\uc74c \ub9cc\ub09c \uc2e0\uc804\uc758 \uacbd\ud5d8\uc744 \uc644\uc804\ud788 \uc7ac\ud604\ud560 \uc218\ub294 \uc5c6\ub2e4. \ud398\ub974\uc2dc\uc544\uc640\uc758 \uc804\uc7c1\uc740 \uc544\ud14c\ub124\uc5d0\ub3c4 \ud070 \uc190\uc0c1\uc744 \ub0a8\uacbc\ub2e4. \uad50\uc7ac\ub294 \uc774\uc804 \uc2e0\uc804\uc774 \ud30c\uad34\ub41c \ub4a4 \uc544\ud14c\ub124\uac00 \uc7ac\uac74\uc5d0 \ub098\uc130\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc0c8 \uac74\ucd95\uc740 \uc544\ub984\ub2e4\uc6b4 \ubb3c\uac74\uc744 \ucd94\uac00\ud558\ub294 \uc77c\ub9cc\uc774 \uc544\ub2c8\ub77c \uc804\uc7c1 \ub4a4 \ub3c4\uc2dc\uc758 \ud798\uacfc \uc815\uccb4\uc131\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc120\ud0dd\uc774\uc5c8\ub2e4. \uc804\uc7c1\uc758 \uae30\uc5b5\uacfc \uc7ac\uac74\uc758 \uc758\uc9c0\uac00 \ud070 \uacf5\uc0ac\uc5d0 \ub4e4\uc5b4\uac04 \uac83\uc774\ub2e4. \uadf8\ub7ec\ub098 \ub204\uac00 \uc65c \uc9c0\uc73c\ub824 \ud588\ub294\uc9c0\uc640 \uadf8\uac83\uc744 \uc5b4\ub5bb\uac8c \ub9c8\ub828\ud588\ub294\uc9c0\ub294 \ub2e4\ub978 \uc9c8\ubb38\uc774\ub2e4. \uc88b\uc740 \ubaa9\uc801\uc744 \ub0b4\uc138\uc6b4 \uac74\ubb3c\ub3c4 \uc790\uc6d0\uacfc \ub178\ub3d9\uc744 \ubaa8\uc73c\ub294 \uad6c\uccb4\uc801\uc778 \uacfc\uc815\uc744 \ud544\uc694\ub85c \ud55c\ub2e4. \uc544\ud14c\ub124\ub294 \ub2e4\ub978 \uadf8\ub9ac\uc2a4 \ub3c4\uc2dc\uad6d\uac00\ub4e4\uacfc \ud574\uc0c1 \ub3d9\ub9f9\uc744 \uc774\ub8e8\uc5c8\ub2e4. \ubc14\ub2e4\ub97c \ud1b5\ud55c \uad70\uc0ac\ub825\uacfc \uc7ac\uc6d0\uc774 \uc911\uc694\ud55c \uad00\uacc4\uc600\ub2e4. \uc5ec\ub7ec \ub3c4\uc2dc\uac00 \uc5f0\uacb0\ub418\uc5c8\ub2e4\ub294 \uc810\uc5d0\uc11c\ub294 \uacf5\ub3d9\uc758 \ubc29\uc5b4\ub97c \uc0dd\uac01\ud560 \uc218 \uc788\uc9c0\ub9cc \uadf8 \uad00\uacc4\uac00 \uacc4\uc18d \ub3d9\ub4f1\ud558\uac8c \uc720\uc9c0\ub41c \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uad50\uc7ac\ub294 \uc544\ud14c\ub124\uac00 \ub3d9\ub9f9\uc5d0\uc11c \ub354 \uac15\ud55c \ud1b5\uc81c\ub825\uc744 \ud589\uc0ac\ud558\uac8c \ub418\ub294 \ud750\ub984\uc744 \uc124\uba85\ud55c\ub2e4. \ud568\uaed8 \ub300\ube44\ud558\uae30 \uc704\ud574 \ubaa8\uc740 \ud798\uc774 \ud55c \ub3c4\uc2dc\uc758 \uc601\ud5a5\ub825\uc73c\ub85c \uc9d1\uc911\ub420 \uc218 \uc788\uc5c8\ub358 \uac83\uc774\ub2e4. \uc544\ud14c\ub124\uc758 \ubc88\uc601\uc744 \ub3c4\uc2dc \uc548\ucabd\uc5d0\uc11c\ub9cc \ubcf4\uba74 \uadf8 \ubc14\uae65\uc758 \ubd80\ub2f4\uc740 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ud30c\ub974\ud14c\ub17c \uc7ac\uac74\uc5d0\ub294 \ub3d9\ub9f9 \ub3c4\uc2dc\ub4e4\uc774 \ub0b8 \uacf5\ub0a9 \uc131\uaca9\uc758 \uc790\uae08\uc774 \uc0ac\uc6a9\ub418\uc5c8\ub2e4. \uad50\uc7ac\ub294 \uc774 \uc77c\ub85c \ub2e4\ub978 \ub3c4\uc2dc\uad6d\uac00\ub4e4\uc758 \ubd88\ub9cc\uc774 \ucee4\uc84c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc624\ub298\ub0a0 \uc138\uacc4\uc758 \uad00\uad11\uac1d\uc774 \uac10\ud0c4\ud558\ub294 \uac74\ubb3c\uc774 \ub2f9\uc2dc\uc758 \ubaa8\ub4e0 \uad00\uacc4\uc790\uc5d0\uac8c \uac19\uc740 \uae30\uc068\uc774\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub290 \ub3c4\uc2dc\uc758 \uc790\ub791\uc740 \ub2e4\ub978 \ub3c4\uc2dc\uc5d0\uac8c \uc790\uc2e0\ub4e4\uc758 \uc790\uc6d0\uc774 \ub2e4\ub978 \uacf3\uc5d0 \uc4f0\uc774\ub294 \uc7a5\uba74\uc77c \uc218\ub3c4 \uc788\ub2e4. \uac74\ubb3c\uc758 \uc608\uc220\uc801 \uac00\uce58\uac00 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\uc9c0\ub9cc \uadf8 \uac00\uce58\ub9cc\uc73c\ub85c \uc790\uae08 \uc0ac\uc6a9\uc758 \uc815\uce58\uac00 \ub05d\ub098\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud55c \uac74\ubb3c\uc744 \ub193\uace0\ub3c4 \uc11c\ub85c \ub2e4\ub978 \uc2dc\uc120\uc774 \uc0dd\uae30\ub294 \uc774\uc720\ub2e4. \uc544\ud14c\ub124\ub294 \ubbfc\uc8fc\uc815\uc758 \uc5ed\uc0ac\uc5d0\uc11c \uc911\uc694\ud55c \ub3c4\uc2dc\ub2e4. \uadf8\ub7ec\ub098 \ub2f9\uc2dc\uc758 \uc815\uce58 \ucc38\uc5ec\ub294 \uc624\ub298\ub0a0 \uc131\uc778 \uc804\uccb4\uc758 \ubcf4\ud1b5\uc120\uac70\uc640 \uac19\uc9c0 \uc54a\uc558\ub2e4. \uc5ec\uc131\uacfc \ub178\uc608, \uac70\uc8fc \uc678\uad6d\uc778 \ub4f1\uc740 \uc2dc\ubbfc \ub0a8\uc131\uacfc \uac19\uc740 \uc815\uce58\uc801 \uc790\ub9ac\ub97c \uac16\uc9c0 \ubabb\ud588\ub2e4. \ub530\ub77c\uc11c \ubbfc\uc8fc\uc815\uc774\ub77c\ub294 \uc774\ub984\uc744 \ud604\ub300\uc758 \uc644\uc131\ub41c \uae30\uc900\uc73c\ub85c \uadf8\ub300\ub85c \uc77d\uc744 \uc218\ub294 \uc5c6\ub2e4. \ub3d9\uc2dc\uc5d0 \ubaa8\ub4e0 \uac83\uc774 \uc9c0\uae08\uacfc \ub2e4\ub974\ub2e4\ub294 \uc774\uc720\ub85c \uadf8 \uc81c\ub3c4\uc758 \uc758\ubbf8\ub97c \uc9c0\uc6cc \ubc84\ub9b4 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \ubb34\uc5c7\uc744 \uac00\ub2a5\ud558\uac8c \ud588\uc73c\uba70 \ub204\uad6c\ub97c \ubc14\uae65\uc5d0 \ub450\uc5c8\ub294\uc9c0 \ub098\ub204\uc5b4 \ubcf4\ub294 \ud3b8\uc774 \ub3c4\uc2dc\ub97c \ub354 \uc815\ud655\ud558\uac8c \uc774\ud574\ud558\uac8c \ud55c\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \uae30\ub465\ub4e4\uc774 \ubc18\ubcf5\ub418\ub294 \uac04\uaca9\uacfc \uc704\ucabd\uc758 \uc218\ud3c9\uc120\uc744 \ub530\ub77c\uac00 \ubcf4\uc790. \uc190\uc0c1\ub41c \uac74\ubb3c\uc5d0\uc11c\ub3c4 \uc804\uccb4\uc758 \uc9c8\uc11c\uac00 \ub290\uaef4\uc9c4\ub2e4. \uc774 \uc778\uc0c1\ub9cc\uc73c\ub85c \uc815\ubc00\ud55c \ube44\ub840\ub098 \uc61b \uc124\uacc4 \uc758\ub3c4\ub97c \ubaa8\ub450 \ud655\uc815\ud560 \uc218\ub294 \uc5c6\uc9c0\ub9cc \ub208\uc73c\ub85c \uac10\uc0c1\ud560 \uc218 \uc788\ub294 \ucd9c\ubc1c\uc810\uc740 \ub41c\ub2e4. \ud070 \uc2e0\uc804\uc744 \uc62c\ub824\ub2e4\ubcf4\ub294 \uacbd\ud5d8\uc5d0\ub294 \uaddc\ubaa8\uc758 \ud6a8\uacfc\uac00 \uc788\ub2e4. \uc0ac\ub78c\uc740 \uc790\uc2e0\ubcf4\ub2e4 \ud070 \uad6c\uc870\ubb3c \uc55e\uc5d0\uc11c \ub3c4\uc2dc\uc758 \uc790\uc6d0\uacfc \uae30\uc220\uc744 \uccb4\uac10\ud558\uac8c \ub41c\ub2e4. \ud30c\ub974\ud14c\ub17c\uc758 \ube44\uc6a9\uc744 \uc0dd\uac01\ud55c \ub4a4 \ub2e4\uc2dc \uae30\ub465\uc744 \ubcf4\uba74 \uadf8 \uc778\uc0c1 \ub4a4\uc758 \uc5ec\ub7ec \uacf5\ub3d9\uccb4\uc640 \ub178\ub3d9\ub3c4 \ud568\uaed8 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \uc544\ud14c\ub124\uac00 \uc9c0\ub2cc \ud574\uc0c1 \uc138\ub825\uacfc \uc2a4\ud30c\ub974\ud0c0\ub97c \uc911\uc2ec\uc73c\ub85c \ud55c \uc721\uc0c1 \uc138\ub825\uc758 \uacbd\uc7c1\uc740 \uadf8\ub9ac\uc2a4 \uc138\uacc4\ub97c \uac08\ub77c\ub193\uc558\ub2e4. \uad50\uc7ac\ub294 \ud3a0\ub85c\ud3f0\ub124\uc18c\uc2a4 \uc804\uc7c1\uc744 \uc774\ub7f0 \uad00\uacc4 \uc18d\uc5d0\uc11c \uc124\uba85\ud55c\ub2e4. \ub2e4\ub9cc \uc2e0\uc804 \ud558\ub098\uc758 \uac74\ucd95\uc774 \uc804\uc7c1 \uc804\uccb4\ub97c \uc77c\uc73c\ucf30\ub2e4\uace0 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub3c4\uc2dc\ub4e4 \uc0ac\uc774\uc758 \uac08\ub4f1\uc5d0\ub294 \uad8c\ub825\uacfc \uc548\ubcf4, \ub3d9\ub9f9\uc758 \ubcc0\ud654\uac00 \ud568\uaed8 \uc788\uc5c8\ub2e4. \ud30c\ub974\ud14c\ub17c\uc758 \uc790\uae08 \ubb38\uc81c\ub294 \uadf8 \ud070 \uad00\uacc4\ub97c \uac00\uae4c\uc774\uc5d0\uc11c \uc0dd\uac01\ud558\uac8c \ud558\ub294 \uc0ac\ub840\ub2e4. \uc791\uc740 \uc0ac\uac74\uacfc \uae34 \uc804\uc7c1 \uc0ac\uc774\uc758 \uc778\uacfc\ub97c \ubb34\ub9ac\ud558\uac8c \ud55c \uc904\ub85c \uc5f0\uacb0\ud558\uc9c0 \uc54a\uc544\ub3c4 \ucda9\ubd84\ud788 \uc758\ubbf8\uac00 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 \ud30c\ub974\ud14c\ub17c\uc758 \uc2e4\uc81c \uc720\uc801 \uc0ac\uc9c4\uc774\ub2e4. \uc9c0\uae08 \ub0a8\uc740 \ubaa8\uc2b5\uacfc \uace0\ub300\uc758 \uc644\uc131 \ubaa8\uc2b5\uc740 \uad6c\ubcc4\ud558\uba74\uc11c \uae30\ub465\uacfc \uc5b8\ub355\uc758 \uc778\uc0c1\uc744 \ubcfc \uc218 \uc788\ub2e4. \ud604\uc7ac\uc758 \uad00\ub78c \ub3d9\uc120\uc774\ub098 \ubcf4\uc874 \uc0c1\ud0dc\ub97c \uc2e4\uc2dc\uac04\uc73c\ub85c \uc548\ub0b4\ud558\ub294 \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \ud30c\ub974\ud14c\ub17c\uc744 \uc88b\uc544\ud558\uba74\uc11c \uadf8 \ube44\uc6a9\uc744 \ubb3c\uc744 \uc218 \uc788\ub2e4. \uc608\uc220\uc744 \uac10\uc0c1\ud558\ub294 \uc77c\uacfc \uad8c\ub825\uc758 \uc791\ub3d9\uc744 \uc54c\uc544\ubcf4\ub294 \uc77c\uc740 \uc11c\ub85c\ub97c \uc5c6\uc560\uc9c0 \uc54a\ub294\ub2e4. \uc544\ud14c\ub124\uc758 \ub192\uc740 \uc5b8\ub355\uc740 \ud6cc\ub96d\ud55c \uac74\ucd95\uc774 \uc5b4\ub5bb\uac8c \ub9cc\ub4e4\uc5b4\uc84c\uace0 \uadf8 \ub4a4\uc5d0 \ub204\uad6c\uc758 \uc790\uc6d0\uc774 \uc788\uc5c8\ub294\uc9c0 \uc0dd\uac01\ud560 \ub54c \ub354 \uae4a\uc740 \ud48d\uacbd\uc774 \ub41c\ub2e4."}, {"id": "baghdad-round-city-and-books", "title": "\ubc14\uadf8\ub2e4\ub4dc \u2014 \ub465\uadfc \ub3c4\uc2dc \ubc14\uae65\uc73c\ub85c \uc774\uc57c\uae30\uac00 \uc790\ub77c\ub2e4", "summary": "\ud6c4\ub300\uc758 \uc61b \uc9c0\ub3c4\uc5d0\uc11c \ub465\uadfc \uc218\ub3c4\uc758 \uad6c\uc0c1\uacfc \uad50\uc5ed\u00b7\ubc88\uc5ed\uc774 \ud0a4\uc6b4 \ub3c4\uc2dc\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "cities", "category_title": "Cities", "subcategory": "Middle East", "url": "stories/baghdad-round-city-and-books/index.html", "image": "media/baghdad-round-city-and-books.jpg", "alt": "1880\ub144\ub300 \ud6c4\ub300 \uc9c0\ub3c4\uc5d0 \ud45c\uc2dc\ub41c \ubc14\uadf8\ub2e4\ub4dc\uc758 \ub465\uadfc \uc911\uc2ec\ubd80\uc640 \ud2f0\uadf8\ub9ac\uc2a4\uac15, \uc218\ub85c \ubc0f \uc678\uacfd \uad6c\uc5ed.", "text": "\ubc14\uadf8\ub2e4\ub4dc \u2014 \ub465\uadfc \ub3c4\uc2dc \ubc14\uae65\uc73c\ub85c \uc774\uc57c\uae30\uac00 \uc790\ub77c\ub2e4 \uad81\uc804\uc5d0\uc11c \uc2dc\uc791\ud55c \uc6d0\uacfc \uac15\uc744 \ub530\ub77c \ubc88\uc9c4 \uc0dd\ud65c \ud6c4\ub300\uc758 \uc61b \uc9c0\ub3c4\uc5d0\uc11c \ub465\uadfc \uc218\ub3c4\uc758 \uad6c\uc0c1\uacfc \uad50\uc5ed\u00b7\ubc88\uc5ed\uc774 \ud0a4\uc6b4 \ub3c4\uc2dc\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Middle East \ub3c4\uc2dc \ub3c4\uc2dc \uc9c0\ub3c4\ub97c \ud3bc\ucce4\ub294\ub370 \ud55c\uac00\uc6b4\ub370 \ucee4\ub2e4\ub780 \uc6d0\uc774 \ubcf4\uc778\ub2e4\uba74 \uc5b4\ub5a8\uae4c. \ub3c4\ub85c\uac00 \uc6b0\uc5f0\ud788 \ub465\uae00\uc5b4\uc9c4 \uc815\ub3c4\uac00 \uc544\ub2c8\ub2e4. \uc131\ubcbd\uacfc \uc911\uc2ec \uacf5\uac04\uc744 \uc6d0\uc73c\ub85c \uacc4\ud68d\ud55c \ub3c4\uc2dc\ub2e4. \uc624\ub298\ub0a0 \uc774\ub77c\ud06c\uc758 \uc218\ub3c4 \ubc14\uadf8\ub2e4\ub4dc\uc5d0\ub294 \ubc14\ub85c \uc774\ub7f0 \ucd9c\ubc1c\uc810\uc774 \uc788\uc5c8\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc9c0\ub3c4\uc5d0\uc11c \uba3c\uc800 \ub465\uadfc \ubd80\ubd84\uc744 \ucc3e\uc544\ubcf4\uc790. \uadf8\ub2e4\uc74c\uc5d0\ub294 \uc2dc\uc120\uc744 \uc870\uae08 \uc606\uc73c\ub85c \uc62e\uaca8 \uac15\uacfc \uc218\ub85c, \uc6d0 \ubc14\uae65\uc758 \uae38\uc744 \ub530\ub77c\uac00\uba74 \ub41c\ub2e4. \ub450 \ubc88 \ubcf4\ub294 \uc0ac\uc774\uc5d0 \uc774\uc57c\uae30\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \uad8c\ub825\uc790\uac00 \uadf8\ub9b0 \uc218\ub3c4\uc758 \ubaa8\uc591\uacfc \uc0ac\ub78c\ub4e4\uc774 \uc0b4\uc544\uac00\uba70 \ub113\ud78c \ub3c4\uc2dc\uac00 \ud55c \uc7a5 \uc548\uc5d0 \ub4e4\uc5b4 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. 8\uc138\uae30\uc5d0 \ub4f1\uc7a5\ud55c \uc544\ubc14\uc2a4 \uc655\uc870\ub294 \ub2e4\ub9c8\uc2a4\ucfe0\uc2a4\uc5d0\uc11c \ub354 \ub3d9\ucabd\uc73c\ub85c \uc815\uce58\uc758 \ubb34\uac8c\uc911\uc2ec\uc744 \uc62e\uacbc\ub2e4. \uc0c8 \uc218\ub3c4 \ubc14\uadf8\ub2e4\ub4dc\ub294 \ud2f0\uadf8\ub9ac\uc2a4\uac15\uc744 \ub080 \uba54\uc18c\ud3ec\ud0c0\ubbf8\uc544\uc5d0 \uc790\ub9ac \uc7a1\uc558\ub2e4. \ube44\uc625\ud55c \ub18d\uacbd\uc9c0\uc640 \ubb3c\uae38\uc744 \uc774\uc6a9\ud560 \uc218 \uc788\uace0 \ub3d9\ucabd \uc9c0\uc5ed\uacfc\uc758 \uad00\uacc4\ub3c4 \uac15\ud654\ud560 \uc218 \uc788\ub294 \uacf3\uc774\uc5c8\ub2e4. \uc218\ub3c4 \uc774\uc804\uc740 \uad81\uc804\uc758 \uc8fc\uc18c\ub9cc \ubc14\uafb8\ub294 \uc77c\uc774 \uc544\ub2c8\ub2e4. \uad00\ub8cc\uc640 \uad70\uc778, \uc7a5\uc778\uacfc \uc0c1\uc778\ub3c4 \uc0c8\ub85c\uc6b4 \uc911\uc2ec\uc744 \ud5a5\ud574 \uc6c0\uc9c1\uc778\ub2e4. \uc655\uc870\uac00 \uc5b4\ub514\ub97c \uc911\uc694\ud558\uac8c \uc5ec\uae30\ub294\uc9c0 \ub3c4\uc2dc\uc758 \uc704\uce58\uac00 \ubcf4\uc5ec \uc8fc\ub294 \uc148\uc774\ub2e4. \ubc14\uadf8\ub2e4\ub4dc\uc758 \uc131\uc7a5\uc740 \uc774\ub7f0 \uc815\uce58\uc801 \uc120\ud0dd\uacfc \uc8fc\ubcc0\uc758 \uc0dd\uc0b0\u00b7\uad50\uc5ed \uc870\uac74\uc774 \ub9cc\ub09c \uacb0\uacfc\uc600\ub2e4. \ub465\uadfc \uc911\uc2ec\ubd80 \uc548\uc5d0\uc11c\ub294 \uce7c\ub9ac\ud504\uc758 \uad81\uc804\uc5d0 \uac00\uae4c\uc6b4 \uc790\ub9ac\uac00 \ud2b9\ubcc4\ud55c \uc704\uc2e0\uc744 \uac00\uc84c\ub2e4. \uac19\uc740 \ub3c4\uc2dc\uc758 \uc8fc\ubbfc\uc774\ub77c\ub3c4 \uad8c\ub825\uc758 \uc911\uc2ec\uc5d0 \uc5bc\ub9c8\ub098 \uac00\uae4c\uc6b4\uc9c0\uac00 \uc911\uc694\ud588\ub2e4. \uc6d0\uc740 \ubcf4\uae30 \uc88b\uc740 \ubb34\ub2ac\uc774\uba74\uc11c, \uc911\uc2ec\uacfc \uc8fc\ubcc0\uc744 \ub208\uc5d0 \ub744\uac8c \uad6c\ubd84\ud558\ub294 \ubc30\uce58\uc774\uae30\ub3c4 \ud588\ub2e4. \uadf8\ub807\ub2e4\uace0 \ub3d9\uadf8\ub77c\ubbf8 \uc548\uc5d0 \ubc14\uadf8\ub2e4\ub4dc\uc758 \ubaa8\ub4e0 \uc0b6\uc774 \ub4e4\uc5b4 \uc788\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc9c0\ub3c4\uc5d0\uc11c\ub3c4 \uac15\uac00\uc758 \uc5ec\ub7ec \uad6c\uc5ed\uacfc \uae38\uc774 \uc6d0\uc744 \ubc97\uc5b4\ub098 \uc774\uc5b4\uc9c4\ub2e4. \ucc98\uc74c \uacc4\ud68d\ud55c \uc911\uc2ec\ubd80\ub97c \ub3c4\uc2dc \uc804\uccb4\uc640 \ud63c\ub3d9\ud558\uc9c0 \uc54a\uc73c\uba74, \uc798 \uc815\ub3c8\ub41c \uc124\uacc4\ub3c4\uc640 \uc2e4\uc81c \ub3c4\uc2dc\uac00 \uc5b4\ub5bb\uac8c \ub2e4\ub978\uc9c0 \ud6e8\uc52c \uc27d\uac8c \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uc544\ubc14\uc2a4 \uc655\uc870\uac00 \ubd80\uc720\ud574\uc9c0\uace0 \uc601\ud5a5\ub825\uc774 \ucee4\uc9c0\uba74\uc11c \ubc14\uadf8\ub2e4\ub4dc\ub294 \uad50\uc5ed\uacfc \ubb38\ud654\uc758 \uc911\uc694\ud55c \uc911\uc2ec\uc73c\ub85c \uc131\uc7a5\ud588\ub2e4. \uc2dc\uac00\uc9c0\ub294 \uac15\uc744 \ub530\ub77c \ud37c\uc9c0\uace0 \uc8fc\ubcc0 \ub18d\uacbd\uc9c0 \ucabd\uc73c\ub85c\ub3c4 \ub113\uc5b4\uc84c\ub2e4. \uc131\ubcbd \uc548\uc758 \uc911\uc2ec\uc774 \ubd84\uba85\ud574\ub3c4 \uc0dd\ud65c\uc758 \uacbd\uacc4\uae4c\uc9c0 \uac19\uc740 \ubaa8\uc591\uc73c\ub85c \uba48\ucd94\uc9c0\ub294 \uc54a\uc558\ub2e4. \uac15\uc740 \uc9c0\ub3c4\uc5d0\uc11c \ub3c4\uc2dc\ub97c \uc7a5\uc2dd\ud558\ub294 \ud30c\ub780 \uc120\uc774 \uc544\ub2c8\ub2e4. \uc0ac\ub78c\uacfc \ubb3c\uc790\ub97c \uc62e\uae30\ub294 \ud1b5\ub85c\uc774\uc790 \uc8fc\ubcc0\uc758 \uc0dd\uc0b0\uacfc \ub3c4\uc2dc\uc758 \uc18c\ube44\ub97c \uc787\ub294 \uc870\uac74\uc774\uc5c8\ub2e4. \uc5b4\ub290 \uae38\uc774 \uac15\uc5d0 \ub2ff\ub294\uc9c0, \ubb3c\uae38 \uc606\uc73c\ub85c \uad6c\uc5ed\uc774 \uc5b4\ub5bb\uac8c \ubd99\uc5b4 \uc788\ub294\uc9c0 \uc0b4\ud53c\uba74 \uad81\uc804\ub9cc \ubcfc \ub54c\ub294 \ub193\ucce4\ub358 \ub3c4\uc2dc\uc758 \uc6c0\uc9c1\uc784\uc774 \ubcf4\uc778\ub2e4. \ubc14\uadf8\ub2e4\ub4dc\uc5d0\ub294 \uc5ec\ub7ec \uc5b8\uc5b4\ub97c \uc4f0\uace0 \uc11c\ub85c \ub2e4\ub978 \uc804\ud1b5\uc744 \ubc30\uc6b4 \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc600\ub2e4. \uc544\ubc14\uc2a4 \uc9c0\ubc30\uce35\uc758 \ud6c4\uc6d0\uc744 \ubc1b\uc544 \uadf8\ub9ac\uc2a4\uc5b4\uc640 \ud398\ub974\uc2dc\uc544\uc5b4 \ub4f1\uc73c\ub85c \uc804\ud574\uc9c0\ub358 \uc800\uc220\uc744 \uc544\ub78d\uc5b4\ub85c \uc62e\uae30\ub294 \uc791\uc5c5\ub3c4 \ud65c\ubc1c\ud574\uc84c\ub2e4. \ud559\ubb38\uc5d0 \ub300\ud55c \uad00\uc2ec\uc740 \uad81\uc815\uc758 \uad8c\uc704\uc640 \ud589\uc815, \uc2e4\uc81c \uc9c0\uc2dd\uc758 \ud544\uc694\uc640\ub3c4 \uc774\uc5b4\uc838 \uc788\uc5c8\ub2e4. \uc774 \uacfc\uc815\uc5d0\ub294 \uadf8\ub9ac\uc2a4\uc5b4\uc640 \uc2dc\ub9ac\uc544\uc5b4\ub97c \ubaa8\uad6d\uc5b4\ub85c \uc4f0\ub294 \ube44\ubb34\uc2ac\ub9bc \ud559\uc790\ub4e4\ub3c4 \ucc38\uc5ec\ud588\ub2e4. \uc11c\ub85c \ub2e4\ub978 \ubc30\uacbd\uc758 \uc0ac\ub78c\uc774 \ud568\uaed8 \uc77c\ud588\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \ubc88\uc5ed\uc740 \ud55c \uc0ac\ub78c\uc774 \uc0ac\uc804\uc744 \ud3bc\uce58\ub294 \uc7a5\uba74\ub9cc\uc73c\ub85c \uc124\uba85\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc6d0\uace0\ub97c \uad6c\ud558\uace0 \uc5b8\uc5b4\ub97c \uc774\ud574\ud558\uace0 \uc791\uc5c5\uc744 \ud6c4\uc6d0\ud558\ub294 \uad00\uacc4\uac00 \uc788\uc5b4\uc57c \ucc45 \ud55c \uad8c\uc774 \uc0c8\ub85c\uc6b4 \ub3c5\uc790\uc5d0\uac8c \uac08 \uc218 \uc788\ub2e4. \ubc88\uc5ed\ud55c \ub0b4\uc6a9\uc740 \uc5b8\uc81c\ub098 \uc190\ub300\uc9c0 \ub9d0\uc544\uc57c \ud558\ub294 \uc644\uc131\ud488\uc73c\ub85c \ucde8\uae09\ub41c \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ud559\uc790\ub4e4\uc740 \uacfc\uac70\uc758 \uacfc\ud559 \uc800\uc220\uc744 \uc77d\uc73c\uba70 \ub0b4\uc6a9\uc744 \ubc14\ub85c\uc7a1\uac70\ub098 \ubcf4\ucda9\ud558\uae30\ub3c4 \ud588\ub2e4. \uc55e\uc120 \uc2dc\ub300\uc758 \uc9c0\uc2dd\uc744 \uc874\uc911\ud558\ub294 \uc77c\uacfc \uc9c0\uae08\uc758 \uc9c8\ubb38\uc744 \ub367\ubd99\uc774\ub294 \uc77c\uc774 \ud568\uaed8 \uc774\ub8e8\uc5b4\uc9c4 \uac83\uc774\ub2e4. \uc81c\uc9c0 \uae30\uc220\uc758 \ud655\uc0b0\ub3c4 \uc774\ub7f0 \ubc30\uacbd\uc5d0\uc11c \uc911\uc694\ud588\ub2e4. \ucc45\uc744 \ub9cc\ub4dc\ub294 \ube44\uc6a9\uc744 \ub0ae\ucd9c \uc218 \uc788\ub294 \uc7ac\ub8cc\uc640 \uae30\uc220\uc740 \uc9c0\uc2dd\uc744 \uc62e\uae30\ub294 \uc77c\uc758 \uc870\uac74\uc744 \ubc14\uafb8\uc5c8\ub2e4. \ubb3c\ub860 \uadf8 \uc2dc\ub300 \uc0ac\ub78c \ubaa8\ub450\uac00 \ucc45\uc744 \uc77d\uc5c8\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uae00\uc744 \uc77d\ub294 \uc0ac\ub78c\uc740 \uc81c\ud55c\uc801\uc774\uc5c8\uc9c0\ub9cc, \ucc45\uc774 \ub9cc\ub4e4\uc5b4\uc9c0\uace0 \uc720\ud1b5\ub420 \uac00\ub2a5\uc131\uc774 \ub113\uc5b4\uc9c0\ub294 \ubcc0\ud654\ub294 \ub3c4\uc2dc\uc758 \uc131\uaca9\uc744 \ubc14\uafb8\uc5c8\ub2e4. \uc5ec\uae30 \uc2e4\uc740 \uac83\uc740 \uc911\uc138\uc778\uc774 \ubc14\ub85c \uadf8 \uc790\ub9ac\uc5d0\uc11c \uadf8\ub9b0 \ud604\uc7a5 \uae30\ub85d\uc774 \uc544\ub2c8\ub77c, \uad50\uc7ac\uac00 1880\ub144\ub300 \uc9c0\ub3c4\ub85c \uc18c\uac1c\ud55c \ud6c4\ub300\uc758 \uc790\ub8cc\ub2e4. \uc81c\ubaa9\uc5d0\ub294 \uc774\uc2ac\ub78c\ub825 150\ub144\uc5d0\uc11c 300\ub144 \uc0ac\uc774\uc758 \ubc14\uadf8\ub2e4\ub4dc\uac00 \ud45c\uc2dc\ub418\uc5b4 \uc788\ub2e4. \uacfc\uac70 \ub3c4\uc2dc\uc758 \ubc30\uce58\ub97c \uc774\ud574\ud558\ub3c4\ub85d \uad6c\uc131\ud55c \uadf8\ub9bc\uc774\uc9c0 \ud2b9\uc815 \ud558\ub8e8\uc758 \ud56d\uacf5\uc0ac\uc9c4\uc774 \uc544\ub2c8\ub2e4. \uadf8\ub798\uc11c \uac74\ubb3c \ud558\ub098\ud558\ub098\uc758 \uc2e4\uc81c \ub192\uc774\ub098 \uac70\ub9ac\ub97c \uc774 \uadf8\ub9bc\ub9cc\uc73c\ub85c \ud655\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub300\uc2e0 \ub465\uadfc \uc911\uc2ec, \ud2f0\uadf8\ub9ac\uc2a4\uac15, \ubc14\uae65\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \uae38\uc758 \uad00\uacc4\ub97c \uc77d\uae30\uc5d0 \uc88b\ub2e4. \uc81c\uc791 \uc2dc\uae30\uc640 \uadf8\ub824\uc9c4 \uc2dc\ub300\ub97c \ub098\ub204\uc5b4 \ubcf4\ub294 \uac04\ub2e8\ud55c \uc2b5\uad00\ub9cc\uc73c\ub85c\ub3c4 \uc61b \uc9c0\ub3c4\ub294 \ud6e8\uc52c \ud765\ubbf8\ub85c\uc6b4 \uc77d\uc744\uac70\ub9ac\uac00 \ub41c\ub2e4. \ubc14\uadf8\ub2e4\ub4dc \uc774\uc57c\uae30\ub97c \ub5a0\uc62c\ub9b4 \ub54c \uba4b\uc9c4 \uc6d0 \ud558\ub098\ub9cc \uae30\uc5b5\ud574\ub3c4 \ucd9c\ubc1c\uc740 \ucda9\ubd84\ud558\ub2e4. \ub2e4\ub9cc \uac70\uae30\uc11c \uac15\uacfc \uc2dc\uc7a5, \ucc45\uacfc \ubc88\uc5ed\uc790\uc758 \uc790\ub9ac\ub85c \uc870\uae08 \ub354 \uac78\uc5b4\uac00 \ubcf4\uc790. \uc218\ub3c4\uc758 \uad8c\uc704\ub97c \ud45c\ud604\ud55c \ubaa8\uc591 \uacc1\uc5d0\uc11c \uc218\ub9ce\uc740 \uc0ac\ub78c\uc774 \ub2e4\ub978 \uc774\uc720\ub85c \ub3c4\uc2dc\ub97c \ud0a4\uc6b0\uace0 \uc788\uc5c8\ub2e4. \ud55c \ub3c4\uc2dc\ub294 \uc124\uacc4\uc790\uc758 \uc758\ub3c4\ub300\ub85c\ub9cc \ub0a8\uc544 \uc788\uc9c0 \uc54a\ub294\ub2e4. \ubb3c\uac74\uc744 \uc2e4\uc5b4 \ub098\ub974\ub294 \uae38\uacfc \uc0c8\ub85c\uc6b4 \ub9d0\ub85c \uc77d\ud788\ub294 \ucc45\uc774 \uadf8 \uc548\uc5d0 \uacc4\uc18d \ub2e4\ub978 \uad00\uacc4\ub97c \ub9cc\ub4e0\ub2e4. \uc9c0\ub3c4 \ud55c\uac00\uc6b4\ub370\uc758 \ub3d9\uadf8\ub77c\ubbf8\uac00 \uc7ac\ubbf8\uc788\ub294 \uae4c\ub2ed\uc740, \uacb0\uad6d \uadf8 \uc120\ub9cc\uc73c\ub85c\ub294 \ub2e4 \ub2f4\uc744 \uc218 \uc5c6\ub294 \ubc14\uadf8\ub2e4\ub4dc\uc758 \uc0dd\ud65c\uc744 \uc0dd\uac01\ud558\uac8c \ud558\uae30 \ub54c\ubb38\uc774\ub2e4."}, {"id": "borobudur-stone-stories-and-steps", "title": "\ubcf4\ub85c\ubd80\ub450\ub974 \u2014 \ub3cc\uc5d0 \uc0c8\uae34 \uc774\uc57c\uae30\ub97c \ub530\ub77c \uac77\ub2e4", "summary": "1913\ub144\uc758 \uc2e4\uc81c \uc0ac\uc9c4\uc744 \ud1b5\ud574 \uc790\ubc14\uc758 \ubd88\uad50 \uae30\ub150\ubb3c\uacfc \uc21c\ub840, \ubc14\ub2e4 \uac74\ub108 \uad50\ub958\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "cities", "category_title": "Cities", "subcategory": "Asia", "url": "stories/borobudur-stone-stories-and-steps/index.html", "image": "media/borobudur-stone-stories-and-steps.jpg", "alt": "1913\ub144 \ubcf4\ub85c\ubd80\ub450\ub974 \uc0ac\uc9c4. \ub3cc\uacc4\ub2e8\uacfc \ubd80\uc870, \uc704\ucabd\uc758 \uad6c\uba4d \ub09c \uc2a4\ud22c\ud30c\uc640 \ub4a4\ud3b8\uc758 \uc0b0.", "text": "\ubcf4\ub85c\ubd80\ub450\ub974 \u2014 \ub3cc\uc5d0 \uc0c8\uae34 \uc774\uc57c\uae30\ub97c \ub530\ub77c \uac77\ub2e4 \ud070 \uae30\ub150\ubb3c\uc5d0\uc11c \uc791\uc740 \uc870\uac01\uc73c\ub85c \uc2dc\uc120\uc744 \uc62e\uae30\uba74 1913\ub144\uc758 \uc2e4\uc81c \uc0ac\uc9c4\uc744 \ud1b5\ud574 \uc790\ubc14\uc758 \ubd88\uad50 \uae30\ub150\ubb3c\uacfc \uc21c\ub840, \ubc14\ub2e4 \uac74\ub108 \uad50\ub958\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Asia \ub3c4\uc2dc \ub192\uc740 \ud0d1\uc774\ub098 \ud070 \uac74\ubb3c\uc744 \ub9cc\ub098\uba74 \uba3c\uc800 \uc804\uccb4\ub97c \uc0ac\uc9c4\uc5d0 \ub2f4\uace0 \uc2f6\uc5b4\uc9c4\ub2e4. \uadf8\ub7f0\ub370 \uc778\ub3c4\ub124\uc2dc\uc544 \uc790\ubc14\uc758 \ubcf4\ub85c\ubd80\ub450\ub974\uc5d0\uc11c\ub294 \uc870\uae08 \uac00\uae4c\uc774 \ub2e4\uac00\uac08 \uc774\uc720\ub3c4 \uc788\ub2e4. \uac70\ub300\ud55c \uad6c\uc870\ubb3c\uc758 \ubcbd\uc5d0 \uc791\uc740 \uc7a5\uba74\ub4e4\uc774 \uc0c8\uaca8\uc838 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uba40\ub9ac\uc11c \ubcf8 \ub369\uc5b4\ub9ac\uc640 \uac78\uc73c\uba70 \ub9cc\ub098\ub294 \ud45c\uba74\uc740 \uc11c\ub85c \ub2e4\ub978 \uacbd\ud5d8\uc744 \uc900\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 1913\ub144\uc758 \uc2e4\uc81c \uc0ac\uc9c4\uc774\ub2e4. \ub3cc\uae38\uacfc \uc870\uac01, \uc704\ucabd\uc758 \uc885 \ubaa8\uc591 \uad6c\uc870\ubb3c, \uba40\ub9ac \ubcf4\uc774\ub294 \uc0b0\uc774 \ud55c \ud654\uba74\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uc624\ub298\uc758 \uad00\uad11 \uc548\ub0b4\ub3c4\ub294 \uc544\ub2c8\uc9c0\ub9cc, \uc0ac\ub78c\uc758 \ud06c\uae30\uc640 \uac74\ucd95\uc758 \ud06c\uae30\ub97c \ube44\uad50\ud558\uba70 \uc624\ub798\ub41c \uc7a5\uc18c\ub97c \uc77d\uae30\uc5d0 \uc88b\uc740 \ucd9c\ubc1c\uc810\uc774\ub2e4. \ubcf4\ub85c\ubd80\ub450\ub974\ub294 \uc624\ub298\ub0a0 \uc778\ub3c4\ub124\uc2dc\uc544 \uc911\ubd80 \uc790\ubc14\uc5d0 \uc788\ub2e4. \uad50\uc7ac\ub294 \ubd88\uad50\ub97c \ud6c4\uc6d0\ud55c \uc0e4\uc77c\ub80c\ub4dc\ub77c \uc655\ub4e4\uc758 \uc2dc\uae30\uc640 \uc774 \uae30\ub150\ubb3c\uc758 \uac74\uc124\uc744 \uc5f0\uacb0\ud55c\ub2e4. \uc9c0\uae08\uc758 \uad6d\uacbd\uc774\ub098 \uc885\uad50 \ubd84\ud3ec\ub9cc\uc73c\ub85c \uc61b \uc790\ubc14\uc758 \ubaa8\uc2b5\uc744 \uc9d0\uc791\ud558\uba74 \uc774\ub7f0 \ud070 \ubd88\uad50 \uac74\ucd95\uc758 \uc874\uc7ac\uac00 \ub73b\ubc16\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \uacfc\uac70\uc758 \ub3d9\ub0a8\uc544\uc2dc\uc544\uc5d0\ub294 \uc11c\ub85c \ub2e4\ub978 \uc2e0\uc559\uacfc \uad8c\ub825\uc774 \uc790\ub9ac\ud588\ub2e4. \uac00\uae4c\uc6b4 \uc9c0\uc5ed\uc774\ub77c\uace0 \ubaa8\ub450 \uac19\uc740 \uae38\uc744 \uac78\uc740 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \ubcf4\ub85c\ubd80\ub450\ub974\ub294 \uadf8 \uac00\uc6b4\ub370 \ubd88\uad50\uac00 \uac74\ucd95\uacfc \ubbf8\uc220, \ud1b5\uce58\uc790\uc758 \ud6c4\uc6d0\uc73c\ub85c \ud45c\ud604\ub41c \uacbd\uc6b0\ub2e4. \ud558\ub098\uc758 \uc720\uc801\uc740 \ud55c \ub098\ub77c\uc758 \uc624\ub298\uacfc \ub2e4\ub978 \uc2dc\ub300\uc758 \ud48d\uacbd\uc744 \ud568\uaed8 \ubcf4\uc5ec \uc900\ub2e4. \uc0ac\uc9c4 \uc18d\uc758 \uc0ac\ub78c\uc744 \uae30\uc900\uc73c\ub85c \ub3cc\ubcbd\uc744 \ubcf4\uba74 \uc138\ubd80 \uc870\uac01\uc758 \ud06c\uae30\ub97c \uac00\ub2a0\ud560 \uc218 \uc788\ub2e4. \uad50\uc7ac\ub294 \uc774\uacf3\uc5d0 2,600\uac1c\uac00 \ub118\ub294 \ubd80\uc870 \ud328\ub110\uc774 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ubd80\uc870\ub294 \ub3cc\uc758 \ud45c\uba74\uc744 \uae4e\uc544 \uc7a5\uba74\uc774 \ub3c4\ub4dc\ub77c\uc838 \ubcf4\uc774\uac8c \ud55c \ud45c\ud604\uc774\ub2e4. \uc22b\uc790\ub97c \uc678\uc6b0\uae30\ubcf4\ub2e4 \uac74\ucd95\uc758 \ub9ce\uc740 \uba74\uc774 \uc774\uc57c\uae30\uc758 \uc790\ub9ac\uac00 \ub418\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud558\uba74 \uc88b\ub2e4. \uba40\ub9ac\uc11c \ubcfc \ub54c\ub294 \uce35\uacfc \uc724\uacfd\uc774 \uba3c\uc800 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uac00\uae4c\uc774\uc5d0\uc11c\ub294 \uc778\ubb3c\uacfc \uc7a5\uc2dd\uc758 \uc791\uc740 \ucc28\uc774\ub97c \uc0b4\ud53c\uac8c \ub41c\ub2e4. \uac19\uc740 \uac74\ucd95\ubb3c\uc774 \uc2dc\uc120\uc758 \uac70\ub9ac\uc5d0 \ub530\ub77c \ub2e4\ub974\uac8c \uc77d\ud788\ub294 \uac83\uc774\ub2e4. \uc0ac\uc9c4 \ud55c \uc7a5\uc73c\ub85c \ubaa8\ub4e0 \uc7a5\uba74\uc758 \ub0b4\uc6a9\uc744 \uc54c\uc544\ub0bc \uc218\ub294 \uc5c6\uc9c0\ub9cc, \ubcbd\uc774 \ub2e8\uc21c\ud55c \uacbd\uacc4 \uc774\uc0c1\uc774\ub77c\ub294 \uc810\uc740 \ub290\ub084 \uc218 \uc788\ub2e4. \uc0ac\uc9c4\uc758 \uc704\ucabd\uc5d0\ub294 \uc791\uc740 \uad6c\uba4d\uc774 \ub09c \uc885 \ubaa8\uc591\uc758 \uc2a4\ud22c\ud30c\ub4e4\uc774 \ubcf4\uc778\ub2e4. \uad50\uc7ac\ub294 \uc911\uc559\uc758 \ud070 \uad6c\uc870\ubb3c \uc8fc\uc704\uc5d0 72\uac1c\uc758 \uc774\ub7f0 \uc2a4\ud22c\ud30c\uac00 \uc788\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \ucc98\uc74c \ubcf4\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \ub3cc\ub85c \ub9cc\ub4e0 \ubc14\uad6c\ub2c8\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218\ub3c4 \uc788\ub2e4. \ub0af\uc120 \uc774\ub984\uc744 \uc678\uc6b0\uae30 \uc804\uc5d0 \ubc18\ubcf5\ub418\ub294 \ubaa8\uc591\uc744 \uc0b4\ud3b4\ubcf4\uc790. \uc791\uc740 \ud615\ud0dc\ub4e4\uc774 \ud568\uaed8 \ub193\uc774\uba74 \uc804\uccb4\uc758 \uc9c8\uc11c\uac00 \uc0dd\uae34\ub2e4. \uac01\uac01\uc758 \uad6c\uba4d\uacfc \uace1\uba74, \uadf8 \ub108\uba38\uc758 \uc0b0\uc744 \ubc88\uac08\uc544 \ubcf4\uba74 \ub3cc \uac74\ucd95\uc774 \uc8fc\ubcc0 \ud48d\uacbd\uacfc \ub9cc\ub098\ub294 \ubc29\uc2dd\ub3c4 \ubcf4\uc778\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \ud655\uc778\ud55c \ud615\ud0dc\uc640 \uc885\uad50\uc801 \uc0c1\uc9d5\uc758 \uc138\ubd80 \ud574\uc11d\uc740 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ubcf4\uc774\ub294 \ubaa8\ub4e0 \uc7a5\uc2dd\uc744 \ub9c8\uc74c\ub300\ub85c \ud558\ub098\uc758 \ub73b\uc73c\ub85c \ud480 \ud544\uc694\ub294 \uc5c6\ub2e4. \uad50\uc7ac\ub294 \ub3d9\ub0a8\uc544\uc2dc\uc544 \uc5ec\ub7ec \uc9c0\uc5ed\uc758 \ubd88\uad50\ub3c4\ub4e4\uc774 \ubcf4\ub85c\ubd80\ub450\ub974\ub97c \uc21c\ub840\ud588\uace0, \ud759\uc73c\ub85c \ub9cc\ub4e0 \uc791\uc740 \ud310\uacfc \uadf8\ub987 \uac19\uc740 \ubd09\ud5cc\ubb3c\uc744 \ub0a8\uacbc\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud070 \ub3cc \uac74\ubb3c\ub9cc \uc788\uc5c8\ub358 \uac83\uc774 \uc544\ub2c8\ub77c \uadf8\uacf3\uc73c\ub85c \uc774\ub3d9\ud55c \uc0ac\ub78c\ub4e4\uc758 \uc791\uc740 \ubb3c\uac74\ub3c4 \uc788\uc5c8\ub2e4. \uae30\ub150\ubb3c\uc758 \uc5ed\uc0ac\ub294 \uac74\uc124\uc744 \ub05d\ub0b8 \ub0a0 \ub4a4\uc5d0\ub3c4 \uc774\uc5b4\uc84c\ub2e4. \uc21c\ub840\ub294 \uc2e0\uc559\uc744 \ud2b9\uc815 \uc7a5\uc18c\uc5d0\uc11c \uc2e4\ucc9c\ud558\ub294 \uc5ec\ud589\uc774\uc5c8\ub2e4. \ub204\uac00 \uc5b4\ub290 \ub0a0 \uc5b4\ub5a4 \ub9c8\uc74c\uc73c\ub85c \uc654\ub294\uc9c0\uae4c\uc9c0 \uae30\ub85d \uc5c6\uc774 \ubcf5\uc6d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \ucc3e\uc544\uc628 \uc0ac\ub78c\ub4e4\uc774 \ud754\uc801\uc744 \ub0a8\uacbc\ub2e4\ub294 \uc0ac\uc2e4\uc5d0\uc11c \uac74\ucd95\uc774 \ubc18\ubcf5\ub418\ub294 \ubc29\ubb38\uc758 \ubaa9\uc801\uc9c0\uac00 \ub418\uc5c8\uc74c\uc744 \uc54c \uc218 \uc788\ub2e4. \ud070 \uc720\uc801 \uc606\uc758 \uc791\uc740 \ubb3c\uac74\ub3c4 \uc911\uc694\ud55c \uc790\ub8cc\uac00 \ub41c\ub2e4. \uc790\ubc14\uac00 \uc12c\uc774\ub77c\ub294 \uc774\uc720\ub85c \uace0\ub9bd\ub41c \uc7a5\uc18c\uc600\ub2e4\uace0 \uc0dd\uac01\ud558\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \uad50\uc7ac\ub294 \uc774 \uc9c0\uc5ed\uc744 \uc778\ub3c4\uc591\uacfc \ud574\ud611\uc744 \ud1b5\ud55c \uad50\uc5ed\uc758 \ud750\ub984 \uc18d\uc5d0\uc11c \uc124\uba85\ud55c\ub2e4. \uc778\ub3c4\uc5d0\uc11c \uc804\ud574\uc9c4 \uc885\uad50\uc640 \ubbf8\uc220\uc758 \uc601\ud5a5\ub3c4 \uc788\uc5c8\ub2e4. \ubc14\ub2e4\ub294 \ub5a8\uc5b4\ub728\ub9ac\ub294 \uacbd\uacc4\uc774\uba74\uc11c \uc0ac\ub78c\uacfc \uc0dd\uac01\uc774 \uc624\uac00\ub294 \uae38\uc774\uae30\ub3c4 \ud588\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubcf4\ub85c\ubd80\ub450\ub974\ub97c \uc678\ubd80\uc758 \uc124\uacc4\ub97c \uadf8\ub300\ub85c \uc62e\uaca8 \ub193\uc740 \ubb3c\uac74\uc73c\ub85c\ub9cc \ubcfc \uc218\ub294 \uc5c6\ub2e4. \ubb34\uc5c7\uc744 \ubc1b\uc544\ub4e4\uc774\uace0 \uc5b4\ub5a4 \uaddc\ubaa8\ub85c \uc138\uc6b0\uba70 \uc5b4\ub5bb\uac8c \ud6c4\uc6d0\ud560\uc9c0\ub294 \ud604\uc9c0\uc758 \uc120\ud0dd\uacfc \uc5ed\ub7c9\uc5d0 \ub2ec\ub824 \uc788\uc5c8\ub2e4. \uc601\ud5a5\uc744 \uc8fc\uace0\ubc1b\ub294\ub2e4\ub294 \ub9d0\uc5d0\ub294 \ubc1b\ub294 \ucabd\uc758 \ud65c\ub3d9\ub3c4 \ub4e4\uc5b4 \uc788\ub2e4. \ucee4\ub2e4\ub780 \ub3cc \uac74\ucd95 \uc790\uccb4\uac00 \uadf8 \ub178\ub825\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uad50\uc7ac\ub294 \uc774 \uc9c0\uc5ed\uc758 \ud1b5\uce58\uc790\ub4e4\uc774 \uc2e0\uc559\uc744 \ud6c4\uc6d0\ud558\uba70 \uc790\uc2e0\uc758 \uc815\ub2f9\uc131\uc744 \ub4dc\ub7ec\ub0c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc885\uad50 \uac74\ucd95\uc740 \uc2e0\uc559\uc758 \ud45c\ud604\uc774\uba74\uc11c \ub9ce\uc740 \uc790\uc6d0\uacfc \ub178\ub3d9\uc744 \ubaa8\uc744 \uc218 \uc788\ub294 \ud798\uc758 \ud45c\uc2dc\uc774\uae30\ub3c4 \ud588\ub2e4. \uc544\ub984\ub2e4\uc6c0\uacfc \uad8c\ub825\uc740 \uac19\uc740 \uc7a5\uc18c\uc5d0 \ud568\uaed8 \ub0a8\uc744 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uc774\ub7f0 \uad00\uacc4\ub97c \uc548\ub2e4\uace0 \ubaa8\ub4e0 \ubc29\ubb38\uc790\uc758 \uacbd\ud5d8\uc774 \uac19\uc558\ub2e4\uace0 \ud560 \uc218\ub294 \uc5c6\ub2e4. \uc655\uc2e4\uc758 \ubaa9\uc801\uacfc \uc21c\ub840\uc790\uc758 \uae30\ub3c4, \ub3cc\uc744 \ub2e4\ub4ec\uc740 \uc0ac\ub78c\uc758 \uc77c\uc740 \uc11c\ub85c \ub2e4\ub978 \uc790\ub9ac\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc84c\ub2e4. \ud55c \uac74\ubb3c\uc5d0 \ucc38\uc5ec\ud55c \uc5ec\ub7ec \uc0ac\ub78c\uc758 \uc5ed\ud560\uc744 \uc0dd\uac01\ud558\uba74 \uae30\ub150\ubb3c\uc740 \uc774\ub984\ub09c \uc655 \ud55c \uba85\uc758 \uc5c5\uc801\uc73c\ub85c\ub9cc \uba38\ubb3c\uc9c0 \uc54a\ub294\ub2e4. \uc774 \uc0ac\uc9c4\uc740 \ud604\uc7ac\uc758 \ubcf4\uc874 \uc0c1\ud0dc\ub97c \uc2e4\uc2dc\uac04\uc73c\ub85c \ubcf4\uc5ec \uc8fc\uc9c0 \uc54a\ub294\ub2e4. \ub610\ud55c \uc0ac\uc9c4\uc5d0 \uc0ac\ub78c\uc774 \ud55c \uba85 \ubcf4\uc778\ub2e4\uace0 \ub2f9\uc2dc \ubc29\ubb38\uc790\uac00 \ub298 \uc801\uc5c8\ub2e4\uace0 \uacb0\ub860 \ub0bc \uc218\ub3c4 \uc5c6\ub2e4. \ucd2c\uc601\ub41c \uc21c\uac04\uacfc \uc720\uc801 \uc804\uccb4\uc758 \uc624\ub79c \uc5ed\uc0ac\ub294 \ub2e4\ub978 \ubc94\uc704\uc758 \uc790\ub8cc\ub2e4. \uc0ac\uc9c4\uc758 \uc5f0\ub3c4\ub97c \uc544\ub294 \uc77c\uc740 \uc0c1\uc0c1\uc744 \ub9c9\uae30\ubcf4\ub2e4 \uac10\uc0c1\uc758 \uc790\ub9ac\ub97c \uc815\ud655\ud788 \uc7a1\uc544 \uc900\ub2e4. \ub300\uc2e0 \uc0ac\uc9c4\uc774 \uc798 \ubcf4\uc5ec \uc8fc\ub294 \uac83\uc744 \ucc28\ubd84\ud788 \uc77d\uc744 \uc218 \uc788\ub2e4. \ub3cc\uc758 \ubc18\ubcf5, \uae38\uacfc \ubcbd\uc758 \uad00\uacc4, \uc870\uac01 \uc606\uc5d0 \uc120 \uc0ac\ub78c\uc758 \ud06c\uae30\ub2e4. \uc624\ub798\ub41c \uc0ac\uc9c4\uc744 \ubcf4\ub294 \uc990\uac70\uc6c0\uc740 \ub2f9\uc2dc\uc758 \ubaa8\ub4e0 \uac83\uc744 \uc548\ub2e4\uace0 \ub290\ub07c\ub294 \ub370\ub9cc \uc788\uc9c0 \uc54a\ub2e4. \ubb34\uc5c7\uc774 \ub0a8\uc544 \uc788\uace0 \ubb34\uc5c7\uc740 \ud654\uba74 \ubc16\uc5d0 \uc788\ub294\uc9c0 \ucc3e\uc544\ubcf4\ub294 \ub370\uc5d0\ub3c4 \uc788\ub2e4. \ubcf4\ub85c\ubd80\ub450\ub974\ub97c \uae30\uc5b5\ud560 \ub54c\ub294 \uac70\ub300\ud55c \uae30\ub150\ubb3c\uc758 \uc724\uacfd\uacfc \uc791\uc740 \ub3cc\uc870\uac01\uc744 \ud568\uaed8 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uba40\ub9ac\uc11c \ubc14\ub77c\ubcf4\uace0 \uac00\uae4c\uc774\uc5d0\uc11c \uc0b4\ud53c\ub294 \ub450 \uc2dc\uc120\uc774 \ud55c \uc7a5\uc18c \uc548\uc5d0 \uc788\ub2e4. \uc5ec\uae30\uc5d0 \ubc14\ub2e4\ub97c \uac74\ub108\uc628 \uc2e0\uc559\uacfc \uc21c\ub840\uc790\uc758 \ubb3c\uac74\uae4c\uc9c0 \ub354\ud558\uba74 \ub3cc \uac74\ucd95\uc740 \ud6e8\uc52c \ub9ce\uc740 \uc6c0\uc9c1\uc784\uc744 \ud488\ub294\ub2e4. \ub2e4\uc74c\uc5d0 \uc720\uba85\ud55c \uac74\ucd95\uc744 \ub9cc\ub098\uba74 \uc804\uccb4 \uc0ac\uc9c4\uc744 \ucc0d\uc740 \ub4a4 \ubcbd \uac00\uae4c\uc774\uc5d0\uc11c\ub3c4 \uc7a0\uc2dc \uba48\ucdb0 \ubcf4\uba74 \uc5b4\ub5a8\uae4c. \ud558\ub098\uc758 \uc7a5\uba74\uacfc \ubc18\ubcf5\ub418\ub294 \ubaa8\uc591\uc774 \ub208\uc5d0 \ub4e4\uc5b4\uc62c \uc218 \uc788\ub2e4. \ubcf4\ub85c\ubd80\ub450\ub974\ub294 \ud070 \uc7a5\uc18c\ub97c \uc774\ud574\ud558\ub294 \ub610 \ud558\ub098\uc758 \ubc29\ubc95\uc774 \uc791\uc740 \ud45c\uba74\uc744 \uc77d\ub294 \uc77c\uc784\uc744 \uc54c\ub824 \uc900\ub2e4."}, {"id": "cahokia-mound-and-plaza", "title": "\uce74\ud638\ud0a4\uc544 \u2014 \ud3c9\ubc94\ud55c \uc5b8\ub355\uc778 \uc904 \uc54c\uc558\ub294\ub370", "summary": "\ubabd\ud06c\uc2a4 \ub9c8\uc6b4\ub4dc\uc640 \uad11\uc7a5\u00b7\uc8fc\uac70\uc9c0\uc758 \uad00\uacc4\ub97c \ud1b5\ud574 \ubd81\ubbf8 \uc6d0\uc8fc\ubbfc \ub3c4\uc2dc \uce74\ud638\ud0a4\uc544\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "cities", "category_title": "Cities", "subcategory": "Americas", "url": "stories/cahokia-mound-and-plaza/index.html", "image": "media/cahokia-mound-and-plaza.jpg", "alt": "\ud480\ub85c \ub36e\uc778 \uacc4\ub2e8\uc2dd \ud759 \uae30\ub2e8\uc778 \uce74\ud638\ud0a4\uc544 \ubabd\ud06c\uc2a4 \ub9c8\uc6b4\ub4dc\uc758 \uc2e4\uc81c \uc804\uacbd\uacfc \ud604\ub300 \ubc29\ubb38 \uacc4\ub2e8.", "text": "\uce74\ud638\ud0a4\uc544 \u2014 \ud3c9\ubc94\ud55c \uc5b8\ub355\uc778 \uc904 \uc54c\uc558\ub294\ub370 \uc794\ub514\uac00 \ub36e\uc778 \ud759\ubb34\ub354\uae30\uc5d0\uc11c \uac70\ub300\ud55c \ub3c4\uc2dc\ub97c \uc77d\ub294 \ubc29\ubc95 \ubabd\ud06c\uc2a4 \ub9c8\uc6b4\ub4dc\uc640 \uad11\uc7a5\u00b7\uc8fc\uac70\uc9c0\uc758 \uad00\uacc4\ub97c \ud1b5\ud574 \ubd81\ubbf8 \uc6d0\uc8fc\ubbfc \ub3c4\uc2dc \uce74\ud638\ud0a4\uc544\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Americas \ub3c4\uc2dc \uc0ac\uc9c4\ub9cc \uba3c\uc800 \ubcf4\uba74 \uc794\ub514\uac00 \ub36e\uc778 \uc5b8\ub355\uc774\ub2e4. \uc67c\ucabd\uc73c\ub85c \uacc4\ub2e8 \uac19\uc740 \uc120\uc774 \uc62c\ub77c\uac00\uace0 \uc704\ucabd\uc740 \ub113\uace0 \ud3c9\ud3c9\ud558\ub2e4. \uc8fc\ubcc0\uc758 \ud48d\uacbd\uacfc \ud06c\uac8c \ub2e4\ub974\uc9c0 \uc54a\uc544 \ub208\uae38\uc744 \uc624\ub798 \ubd99\uc7a1\uc9c0 \uc54a\uc744 \uc218\ub3c4 \uc788\ub2e4. \uadf8\ub7f0\ub370 \uc774\uac83\uc774 \uc0ac\ub78c\ub4e4\uc774 \ud759\uc744 \uc313\uc544 \ub9cc\ub4e0 \uac70\ub300\ud55c \uad6c\uc870\ubb3c\uc774\ub77c\uace0 \uc54c\uba74 \uc2dc\uc120\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \ubbf8\uad6d\uc758 \uc624\ub298\ub0a0 \uc138\uc778\ud2b8\ub8e8\uc774\uc2a4 \uadfc\ucc98\uc5d0 \ub0a8\uc544 \uc788\ub294 \uce74\ud638\ud0a4\uc544\uc758 \ubabd\ud06c\uc2a4 \ub9c8\uc6b4\ub4dc\ub2e4. \ud070 \ub3cc\uae30\ub465\uc774\ub098 \ub192\uc774 \ub0a8\uc740 \uc131\ubcbd\uc774 \uc5c6\uc5b4\ub3c4 \uc774\uacf3\uc740 \uc624\ub798\uc804 \ub3c4\uc2dc\ub97c \uc774\ub8e8\uc5c8\ub2e4. \ub545 \uc704\uc758 \ub192\ub0ae\uc774\ub97c \uac74\ubb3c\uc758 \ud754\uc801\uc73c\ub85c \uc77d\uc73c\uba74 \uc775\uc219\ud55c \ub3c4\uc2dc\uc758 \uc774\ubbf8\uc9c0\uac00 \uc870\uae08 \ub113\uc5b4\uc9c4\ub2e4. \uce74\ud638\ud0a4\uc544\ub294 \ubbf8\uc2dc\uc2dc\ud53c \ubb38\ud654\uad8c\uc758 \uc911\uc694\ud55c \uc911\uc2ec\uc774\uc5c8\ub2e4. \uc774 \ubb38\ud654\uad8c\uc758 \ud070 \uc815\ucc29\uc9c0\ub4e4\uc740 \uc625\uc218\uc218\ub97c \ube44\ub86f\ud55c \ub18d\uc5c5\uacfc \uc5f0\uacb0\ub418\uc5b4 \uc131\uc7a5\ud588\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \uacbd\uc791\uc9c0\uc640 \uc9d1, \uc758\ub840\uc640 \uad8c\ub825\uc758 \uacf5\uac04\uc744 \uc77c\uc815\ud55c \uad00\uacc4 \uc548\uc5d0 \ubc30\uce58\ud558\uba70 \uc0b4\uc558\ub2e4. \uad50\uc7ac\ub294 \uce74\ud638\ud0a4\uc544\uac00 1050\ub144 \ubb34\ub835 \ud070 \ub3c4\uc2dc \uc911\uc2ec\uc9c0\ub85c \ubc1c\uc804\ud558\uae30 \uc2dc\uc791\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc804\uc131\uae30\uc5d0\ub294 \uc8fc\ubcc0 \uc815\ucc29\uc9c0\ub97c \ud3ec\ud568\ud574 \uc218\ub9ce\uc740 \uc8fc\ubbfc\uacfc \ubc31 \uac1c\uac00 \ub118\ub294 \ud759\ubb34\ub364\u00b7\uae30\ub2e8\ub4e4\uc774 \uc788\uc5c8\ub2e4. \uc624\ub298 \ub0a8\uc740 \ud48d\uacbd\uc774 \uc870\uc6a9\ud558\ub2e4\uace0 \ub2f9\uc2dc\uc5d0\ub3c4 \uc0ac\ub78c\uc774 \ub4dc\ubb38 \ube48 \ub545\uc774\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \ubabd\ud06c\uc2a4 \ub9c8\uc6b4\ub4dc\ub294 \uc57d 100\ud53c\ud2b8, 30\ubbf8\ud130 \uc815\ub3c4 \ub192\uc774\uc5d0 \uc774\ub974\ub294 \uacc4\ub2e8\uc2dd \ud759 \uad6c\uc870\ubb3c\uc774\ub2e4. \ud55c \ubc88\uc5d0 \ud759\uc744 \ubd80\uc5b4 \ub05d\ub0b8 \uac83\uc774 \uc544\ub2c8\ub77c \uc5ec\ub7ec \ub2e8\uacc4\uc5d0 \uac78\uccd0 \ub9cc\ub4e4\uc5b4\uc84c\ub2e4. \uaf2d\ub300\uae30\uc5d0\ub294 \ubaa9\uc870 \uad6c\uc870\ubb3c\uc774 \uc788\uc5c8\uace0 \uc8fc\ubcc0 \uad11\uc7a5\uc5d0\uc11c \uc62c\ub77c\uac00\ub294 \uacc4\ub2e8\uc774 \uc788\uc5c8\ub2e4\uace0 \uad50\uc7ac\ub294 \uc124\uba85\ud55c\ub2e4. \uc774\ub97c \uc54c\uba74 \uc0ac\uc9c4\uc758 \ud3c9\ud3c9\ud55c \uc717\ubd80\ubd84\uacfc \uce35\uc744 \uc774\ub8ec \uacbd\uc0ac\uac00 \ub2e4\ub974\uac8c \ubcf4\uc778\ub2e4. \ub545\uc744 \uc774\uc6a9\ud574 \uc911\uc694\ud55c \uc7a5\uc18c\uc758 \ub192\uc774\ub97c \ub9cc\ub4e0 \uac83\uc774\ub2e4. \ud759\uc774\ub77c\ub294 \uc7ac\ub8cc\ub97c \uc37c\ub2e4\uace0 \uc870\uc9c1\uacfc \uae30\uc220\uc774 \ub2e8\uc21c\ud588\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ud759\uc744 \ubaa8\uc73c\uace0 \uc62e\uae30\uba70 \ud070 \ud615\ud0dc\ub97c \uc720\uc9c0\ud558\ub294 \ub370\ub3c4 \ub9ce\uc740 \uc0ac\ub78c\uc758 \ud611\ub825\uc774 \ud544\uc694\ud588\ub2e4. \ub192\uc740 \uad6c\uc870\ubb3c \ud558\ub098\ub97c \ub530\ub85c \ub5bc\uc5b4 \ub193\uc73c\uba74 \uac70\ub300\ud55c \uae30\ub150\ube44\ucc98\ub7fc\ub9cc \ubcf4\uc778\ub2e4. \uadf8\ub7ec\ub098 \uce74\ud638\ud0a4\uc544\uc758 \uc911\uc2ec\ubd80\uc5d0\uc11c\ub294 \uc5ec\ub7ec \ud759 \uae30\ub2e8\uacfc \ud070 \uad11\uc7a5\uc774 \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub2e4. \uc624\ub974\uace0 \ub0b4\ub824\uac00\ub294 \uc0ac\ub78c, \uc544\ub798\uc5d0\uc11c \ubc14\ub77c\ubcf4\ub294 \uc0ac\ub78c\uc758 \uc704\uce58\uac00 \uc11c\ub85c \ub2ec\ub790\uc744 \uac83\uc774\ub2e4. \ub3c4\uc2dc\uc758 \uc7a5\uc18c\ub294 \ub192\uc774\ubfd0 \uc544\ub2c8\ub77c \ub2e4\ub978 \uacf5\uac04\uacfc\uc758 \uad00\uacc4\ub85c \uc758\ubbf8\ub97c \uac16\ub294\ub2e4. \ub113\uc740 \uad11\uc7a5\uacfc \uadf8 \uc606\uc758 \ub192\uc740 \uae30\ub2e8\uc744 \uac19\uc774 \uc0dd\uac01\ud558\uba74 \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub514\uc5d0 \ubaa8\uc774\uace0 \uc911\uc694\ud55c \uc758\ub840\uac00 \uc5b4\ub5a4 \ud658\uacbd\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc84c\ub294\uc9c0 \uc9c8\ubb38\ud560 \uc218 \uc788\ub2e4. \ud2b9\uc815\ud55c \ud589\uc0ac \uc7a5\uba74\uc744 \ucc3d\uc791\ud558\uc9c0 \uc54a\uc544\ub3c4 \ubc30\uce58 \uc790\uccb4\uac00 \uc774\uc57c\uae30\ub97c \uac74\ub128\ub2e4. \uc911\uc2ec \uad11\uc7a5 \ubc14\uae65\uc73c\ub85c\ub294 \ubaa9\uc7ac\uc640 \uc774\uc5c9\uc744 \uc774\uc6a9\ud55c \uc9d1\ub4e4\uc774 \uc788\uc5c8\uace0 \uadf8 \uc8fc\ubcc0\uc73c\ub85c \uc625\uc218\uc218\ubc2d\uc774 \uc774\uc5b4\uc84c\ub2e4. \uc9c0\ubc30\uce35\uc758 \uac70\ucc98\uc640 \uc911\uc2ec \uae30\ub2e8\ub4e4\uc740 \ubc29\uc5b4\ubcbd\uc73c\ub85c \ub458\ub7ec\uc2f8\uc778 \uad6c\uc5ed\uacfc\ub3c4 \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub2e4. \ubaa8\ub450\uac00 \uac19\uc740 \uc704\uce58\uc640 \uc870\uac74\uc5d0\uc11c \uc0b4\uc558\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub3c4\uc2dc\ub97c \uc720\uc9c0\ud558\ub824\uba74 \uc758\ub840\ubfd0 \uc544\ub2c8\ub77c \ub9e4\uc77c \uba39\uace0 \uc790\uace0 \uc77c\ud558\ub294 \ud65c\ub3d9\uc774 \ud544\uc694\ud558\ub2e4. \uc9d1\uc5d0 \uc4f8 \uc7ac\ub8cc\uc640 \uc2dd\ub7c9\uc744 \ub9c8\ub828\ud558\uace0 \ubb3c\uac74\uc744 \ub9cc\ub4dc\ub294 \uc77c\uc774 \uc774\uc5b4\uc838\uc57c \ud588\ub2e4. \ub208\uc5d0 \ud06c\uac8c \ub0a8\uc740 \uae30\ub2e8\uc740 \uc624\ub7ab\ub3d9\uc548 \uc0dd\ud65c\uc744 \uc774\uc5b4 \uac04 \uc0ac\ub78c\ub4e4\uc758 \uc2dc\uac04 \uc704\uc5d0 \uc11c \uc788\ub294 \uc148\uc774\ub2e4. \uce74\ud638\ud0a4\uc544\uc758 \uc720\ub825\uc790\ub4e4\uc740 \ud574\uc591 \uc870\uac1c\uc640 \ud2b9\ubcc4\ud55c \ub3cc, \uad6c\ub9ac \uac19\uc740 \ubb3c\uac74\uc5d0 \uc811\uadfc\ud560 \uc218 \uc788\uc5c8\ub2e4. \uc774\ub7f0 \uc790\ub8cc\ub294 \ub3c4\uc2dc\uac00 \uac00\uae4c\uc6b4 \uacbd\uc791\uc9c0\ub9cc \ubc14\ub77c\ubcf4\ub358 \uacf3\uc774 \uc544\ub2c8\ub77c \uc7a5\uac70\ub9ac \uad50\uc5ed\ub9dd\uacfc\ub3c4 \uc5f0\uacb0\ub418\uc5c8\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ubc14\ub2e4\uc5d0\uc11c \ub098\uc628 \ubb3c\uac74\uc774 \ub0b4\ub959\uc758 \uc911\uc694\ud55c \uc790\ub9ac\ub85c \ub4e4\uc5b4\uc628 \uac83\uc774\ub2e4. \uadc0\ud55c \ubb3c\uac74\uc744 \uac00\uc84c\ub2e4\ub294 \uac83\uc740 \ub2e8\uc21c\ud788 \ucde8\ud5a5\uc774 \uc88b\uc558\ub2e4\ub294 \ub73b\ub9cc\uc740 \uc544\ub2c8\ub2e4. \ub204\uac00 \ub2e4\ub978 \uc9c0\uc5ed\uacfc \uad00\uacc4\ub97c \ub9fa\uace0 \ubb3c\uc790\ub97c \ubaa8\uc744 \uc218 \uc788\uc5c8\ub294\uc9c0\uac00 \uad8c\ub825\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uad50\uc7ac\ub294 \uacf5\ub0a9\uacfc \uad50\uc5ed\ub85c\uc5d0 \ub300\ud55c \ud1b5\uc81c\ub97c \uc774 \uc911\uc2ec\uc9c0\ub4e4\uc774 \ud798\uc744 \uc720\uc9c0\ud55c \ubc30\uacbd\uc73c\ub85c \uc124\uba85\ud55c\ub2e4. \ub3c4\uc2dc\uc758 \uc704\uc138\ub294 \ub192\uc740 \ud759 \uae30\ub2e8\ubfd0 \uc544\ub2c8\ub77c \uc0ac\ub78c \uc0ac\uc774\uc758 \uad00\uacc4\uc5d0\ub3c4 \uc788\uc5c8\ub2e4. \uce74\ud638\ud0a4\uc544\uc758 \uc5ec\ub7ec \ud759 \uad6c\uc870\ubb3c\uc5d0\ub294 \ub9e4\uc7a5\uc774\ub098 \uc758\ub840\ub97c \uc704\ud55c \uc7a5\uc18c\ub3c4 \uc788\uc5c8\ub2e4. \ud06c\uace0 \ub192\ub2e4\ub294 \uc678\ud615\ub9cc\uc73c\ub85c \ubaa8\ub450 \uac19\uc740 \uc885\ub958\uc758 \uac74\ubb3c \ubc1b\uce68\uc774\uc5c8\ub2e4\uace0 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc5b4\ub5a4 \uc7a5\uc18c\uc5d0\uc11c \ubb34\uc5c7\uc774 \ubc1c\uacac\ub418\uc5c8\ub294\uc9c0\uac00 \uac01\uac01\uc758 \ud574\uc11d\uc5d0 \uc911\uc694\ud558\ub2e4. \uc0ac\ub78c\uacfc \ubb3c\uac74\uc758 \ud754\uc801\uc744 \ud1b5\ud574 \uc9c0\uc704\uc758 \ucc28\uc774\ub97c \uc77d\uc744 \uc218\ub3c4 \uc788\uc9c0\ub9cc, \uc720\ubb3c\ub9cc\uc73c\ub85c \uc778\ubb3c\uc758 \uc774\ub984\uacfc \uc815\ud655\ud55c \uc9c1\ucc45\uae4c\uc9c0 \ubaa8\ub450 \ubcf5\uc6d0\ud560 \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uace0\uace0\ud559 \uc124\uba85\uc5d0\ub294 \ud655\uc778\ub41c \ud615\ud0dc\uc640 \uadf8 \uc758\ubbf8\uc5d0 \ub300\ud55c \ud574\uc11d\uc774 \ud568\uaed8 \uc788\ub2e4. \ub458\uc744 \ub098\ub204\uc5b4 \uc77d\uc73c\uba74 \uc54c\ub824\uc9c4 \ub0b4\uc6a9\uc774 \uc904\uc5b4\ub4dc\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uadfc\uac70\uc758 \uc131\uaca9\uc774 \ub354 \uc798 \ubcf4\uc778\ub2e4. \uce74\ud638\ud0a4\uc544\ub294 \uc624\ub7ab\ub3d9\uc548 \uac19\uc740 \uaddc\ubaa8\ub85c \uc720\uc9c0\ub418\uc9c0 \uc54a\uc558\ub2e4. \uc2dc\uac04\uc774 \uc9c0\ub098\uba70 \uc1e0\ud1f4\ud588\uace0 \uacb0\uad6d \ud070 \uc911\uc2ec\uc9c0\ub85c\uc11c\uc758 \uc0dd\ud65c\uc740 \ub05d\ub0ac\ub2e4. \ud558\uc9c0\ub9cc \uadf8\uac83\uc744 \ubbf8\uc2dc\uc2dc\ud53c \ubb38\ud654\uad8c \uc804\uccb4\ub098 \uc6d0\uc8fc\ubbfc \uc0ac\ud68c\uac00 \ub3d9\uc2dc\uc5d0 \uc0ac\ub77c\uc9c4 \uc77c\ub85c \uc774\ud574\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \ub2e4\ub978 \uc9c0\uc5ed\uc758 \uc911\uc2ec\uc9c0\ub4e4\uc774 \uc131\uc7a5\ud588\uace0 \uc0ac\ub78c\ub4e4\uc758 \uc0dd\ud65c\uacfc \ubb38\ud654\ub294 \ub2e4\ub978 \ud615\ud0dc\ub85c \uc774\uc5b4\uc84c\ub2e4. \uad50\uc7ac\ub294 \uc5d0\ud1a0\uc640\uc640 \ub9c8\uc6b4\ub4dc\ube4c \uac19\uc740 \uc0ac\ub840\ub97c \ud568\uaed8 \uc18c\uac1c\ud55c\ub2e4. \uc6b0\ub9ac\uac00 \ud55c \uc720\uc801\uc758 \ud765\ub9dd\uc744 \ub3c4\uc2dc\uc758 \uc774\uc57c\uae30\ub85c \uc77d\uc744 \ub54c, \uadf8\uacf3\uc744 \ub5a0\ub09c \uc0ac\ub78c\ub4e4\uc758 \uc774\ud6c4 \uc2dc\uac04\uae4c\uc9c0 \uc9c0\uc6cc \ubc84\ub9ac\uc9c0\ub294 \uc54a\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc0ac\uc9c4\uc758 \ud604\ub300 \uacc4\ub2e8\uc740 \ud604\uc7ac \ubc29\ubb38\uc790\uac00 \uc704\ub85c \uc62c\ub77c\uac00\uac8c \ud574 \uc8fc\ub294 \uc2dc\uc124\uc774\ub2e4. \uc774\uac83\uc744 \uc61b \ubaa9\uc870 \uacc4\ub2e8\uc758 \ubaa8\uc2b5 \uadf8\ub300\ub85c\ub77c\uace0 \ubcfc \uc218\ub294 \uc5c6\ub2e4. \uc624\ub298 \ubcfc \uc218 \uc788\ub294 \uae38\uacfc \uacfc\uac70\uc5d0 \uc124\uba85\ub41c \uae38\uc744 \ub098\ub204\uc5b4 \ubcf4\uba74\uc11c\ub3c4, \uc544\ub798\uc640 \uc704\uc758 \ub192\uc774 \ucc28\uc774\ub294 \uc9c1\uc811 \ub208\uc73c\ub85c \ub290\ub084 \uc218 \uc788\ub2e4. \uce74\ud638\ud0a4\uc544\ub294 \ub3c4\uc2dc\uac00 \ubc18\ub4dc\uc2dc \ub3cc\uacfc \ubcbd\ub3cc\uc758 \uc232\uc73c\ub85c\ub9cc \ub0a8\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc0ac\uc2e4\uc744 \uc54c\ub824 \uc900\ub2e4. \uc794\ub514\uc5d0 \ub36e\uc778 \ud759\ub3c4 \uc0ac\ub78c\uc758 \uacc4\ud68d\uacfc \ud611\ub825\uc744 \uc624\ub798 \ubcf4\uad00\ud560 \uc218 \uc788\ub2e4. \ud3c9\ubc94\ud55c \uc5b8\ub355\ucc98\ub7fc \ubcf4\uc600\ub358 \ud48d\uacbd\uc774 \ub2ec\ub77c\uc9c0\ub294 \uc21c\uac04, \uc9c0\ud615\uc744 \ubc14\ub77c\ubcf4\ub294 \ub208\uc774 \ub3c4\uc2dc\ub97c \uc77d\ub294 \ub208\uc73c\ub85c \ubc14\ub010\ub2e4."}, {"id": "changan-travelers-and-music", "title": "\uc7a5\uc548 \u2014 \uc218\ub3c4\uc758 \uac70\ub9ac\uc5d0\ub294 \uc5b4\ub5a4 \ub9d0\uacfc \uc74c\uc545\uc774 \ud758\ub800\uc744\uae4c", "summary": "\uc7a5\uc548\uc5d0 \ubaa8\uc778 \ud398\ub974\uc2dc\uc544 \uc774\uc8fc\ubbfc\uacfc \uc18c\uadf8\ub4dc \uc0c1\uc778\uc758 \ud65c\ub3d9\uc5d0\uc11c \uad6d\uc81c\ub3c4\uc2dc\uc758 \uc5ec\ub7ec \uc5bc\uad74\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "cities", "category_title": "Cities", "subcategory": "Asia", "url": "stories/changan-travelers-and-music/index.html", "image": "media/changan-travelers-and-music.png", "alt": "\uc5ec\ub7ec \uc0c1\uc778\uc774 \uc9c1\ubb3c\uacfc \uae08\uc18d \ubb3c\uac74\uc744 \uc0b4\ud3b4\ubcf4\ub294 \uc61b \ub3d9\uc544\uc2dc\uc544 \ub3c4\uc2dc \uc2dc\uc7a5\uc758 AI \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\uc7a5\uc548 \u2014 \uc218\ub3c4\uc758 \uac70\ub9ac\uc5d0\ub294 \uc5b4\ub5a4 \ub9d0\uacfc \uc74c\uc545\uc774 \ud758\ub800\uc744\uae4c \ub2f9\ub098\ub77c\uc758 \ub3c4\uc2dc\ub97c \ucc44\uc6b4 \uac83\uc740 \uad81\uc804\ub9cc\uc774 \uc544\ub2c8\uc5c8\ub2e4 \uc7a5\uc548\uc5d0 \ubaa8\uc778 \ud398\ub974\uc2dc\uc544 \uc774\uc8fc\ubbfc\uacfc \uc18c\uadf8\ub4dc \uc0c1\uc778\uc758 \ud65c\ub3d9\uc5d0\uc11c \uad6d\uc81c\ub3c4\uc2dc\uc758 \uc5ec\ub7ec \uc5bc\uad74\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Asia \ub3c4\uc2dc \uc61b \uc911\uad6d\uc758 \uc218\ub3c4\ub77c\uace0 \ud558\uba74 \uac70\ub300\ud55c \uad81\uc804\uacfc \ud669\uc81c\uc758 \ud589\ub82c\ubd80\ud130 \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \uadf8\ub7f0\ub370 \ub2f9\ub098\ub77c\uc758 \uc7a5\uc548\uc5d0\ub294 \uba3c \uc9c0\uc5ed\uc5d0\uc11c \uc628 \uc0ac\ub78c\uacfc \ubb3c\uac74\ub3c4 \ubaa8\uc600\ub2e4. \ub2e4\ub978 \ub9d0\ub85c \uac70\ub798\ud558\ub294 \uc0c1\uc778\uacfc \uc775\uc219\ud558\uc9c0 \uc54a\uc740 \uc74c\uc545\uc774 \uc218\ub3c4\uc758 \uc0dd\ud65c\uc5d0 \ub4e4\uc5b4\uc640 \uc788\uc5c8\ub2e4. \ub3c4\uc2dc\uc758 \uc911\uc2ec\uc5d0 \ub204\uac00 \uc0b4\uc558\ub294\uc9c0\ub97c \uc544\ub294 \uac83\ub9cc\ud07c \ub204\uac00 \ub4dc\ub098\ub4e4\uc5c8\ub294\uc9c0\ub3c4 \uc911\uc694\ud558\ub2e4. \uc7a5\uc548\uc744 \uc911\uad6d\uc774\ub77c\ub294 \uacbd\uacc4 \uc548\uc5d0\ub9cc \ub193\uc73c\uba74 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc0ac\ub78c\ub4e4\uc774 \uc788\ub2e4. \uc624\ub298\uc740 \uad81\uc804\uc758 \uc548\ucabd\ubcf4\ub2e4 \ub3c4\uc2dc\ub85c \uc774\uc5b4\uc9c4 \uae38\uacfc \uadf8 \uae38\uc5d0\uc11c \uc628 \uc0dd\ud65c\uc758 \ud754\uc801\uc744 \uc0b4\ud3b4\ubcf4\uc790. \uc7a5\uc548\uc740 \ub2f9\ub098\ub77c\uc758 \uc218\ub3c4\uc774\uc790 \uc2e4\ud06c\ub85c\ub4dc \uad50\uc5ed\ub9dd\uc758 \uc911\uc694\ud55c \ub3d9\ucabd \uac70\uc810\uc774\uc5c8\ub2e4. \uc2e4\ud06c\ub85c\ub4dc\ub77c\ub294 \uc774\ub984 \ub54c\ubb38\uc5d0 \ube44\ub2e8\uc744 \uc2e4\uc740 \ud589\ub82c \ud55c \uc904\uc744 \uc0c1\uc0c1\ud558\uae30 \uc27d\uc9c0\ub9cc, \uc2e4\uc81c\ub85c\ub294 \uc5ec\ub7ec \uc9c0\uc5ed\uacfc \ub3c4\uc2dc\ub97c \uc787\ub294 \uae38\ub4e4\uc774 \uc788\uc5c8\ub2e4. \ubaa8\ub4e0 \uc0c1\uc778\uc774 \ucc98\uc74c\ubd80\ud130 \ub05d\uae4c\uc9c0 \uac19\uc740 \uc5ec\ud589\uc744 \ud55c \uac83\ub3c4 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \uc0ac\ub78c\uc740 \uad6c\uac04\uc744 \uc624\uac00\uace0 \ub2e4\ub978 \uc0ac\ub78c\uc740 \ud55c \ub3c4\uc2dc\uc5d0 \uba38\ubb3c\uba70 \uac70\ub798\ub97c \uc774\uc5b4 \uac14\ub2e4. \uc7a5\uc548\uc758 \uad6d\uc81c\uc801\uc778 \uc131\uaca9\uc740 \uba3c \uc11c\ucabd\uc5d0\uc11c \ud55c \ubc88\uc5d0 \ub3c4\ucc29\ud55c \ud2b9\ubcc4\ud55c \uc190\ub2d8\ub4e4\ub9cc\uc73c\ub85c \uc0dd\uae34 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc774\ub7f0 \uc911\uac04\uc758 \uc5f0\uacb0\uacfc \ubc18\ubcf5\ub41c \uc655\ub798\uac00 \ub3c4\uc2dc\uc758 \uc0dd\ud65c\uc744 \ub113\ud600 \uac14\ub2e4. \uc624\ub298\ub0a0 \uc6b0\uc988\ubca0\ud0a4\uc2a4\ud0c4\uacfc \ud0c0\uc9c0\ud0a4\uc2a4\ud0c4 \uc77c\ub300\uc758 \uc18c\uadf8\ub4dc \uc9c0\uc5ed\uc740 \uc911\uc559\uc544\uc2dc\uc544 \uad50\uc5ed\uc758 \uc911\uc694\ud55c \ubc30\uacbd\uc774\uc5c8\ub2e4. \uc18c\uadf8\ub4dc \uc0c1\uc778\ub4e4\uc740 \uc11c\ucabd\uc758 \uc5ec\ub7ec \uc9c0\uc5ed\uacfc \ub3d9\ucabd \uc911\uad6d \uc0ac\uc774\uc5d0\uc11c \ud65c\ub3d9\ud588\ub2e4. \uad50\uc7ac\ub294 \uc7a5\uc548 \uac19\uc740 \uc911\uad6d \ub3c4\uc2dc\uc5d0\ub3c4 \uc774\ub4e4\uc758 \uad50\uc5ed \uacf5\ub3d9\uccb4\uac00 \uc788\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc774\uc8fc \uc0c1\uc778\uc774 \uacf5\ub3d9\uccb4\ub97c \uc774\ub8ec\ub2e4\ub294 \uac83\uc740 \ub2e8\uc21c\ud788 \uc7a0\uae50 \ubb3c\uac74\uc744 \ud314\uace0 \ub5a0\ub098\ub294 \uc7a5\uba74\uacfc \ub2e4\ub974\ub2e4. \uac70\ub798\ub97c \uc774\uc5b4 \uac08 \uc0ac\ub78c\uacfc \ub9d0\uc744 \ub098\ub20c \uc0c1\ub300, \uc0dd\ud65c\uc744 \uc720\uc9c0\ud560 \uad00\uacc4\uac00 \uc0dd\uae34\ub2e4\ub294 \ub73b\uc774\ub2e4. \ub3c4\uc2dc\uc758 \ub0af\uc120 \ubb3c\uac74 \ub4a4\uc5d0\ub294 \uadf8\uac83\uc744 \ub2e4\ub8e8\uace0 \uc124\uba85\ud560 \uc218 \uc788\ub294 \uc0ac\ub78c\ub4e4\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4. 7\uc138\uae30 \ud6c4\ubc18\uc5d0\ub294 \uc0ac\uc0b0 \uc655\uc870\uc758 \uc655\uc2e4 \uc778\ubb3c\ub4e4\uc774 \uc11c\ucabd\uc758 \uc815\uce58\uc801 \ubcc0\ud654 \uc18d\uc5d0\uc11c \ub2f9\ub098\ub77c \uad81\uc815\uc73c\ub85c \ud53c\uc2e0\ud588\ub2e4. \uad50\uc7ac\ub294 \uc774\uc640 \ud568\uaed8 \ud398\ub974\uc2dc\uc544\uacc4 \uc0c1\uc778 \uacf5\ub3d9\uccb4\uc758 \uc774\ub3d9\uc744 \uc124\uba85\ud55c\ub2e4. \ubb3c\uac74\uc744 \uc0ac\ub7ec \ub5a0\ub098\ub294 \uc5ec\ud589\ub9cc\uc774 \uc544\ub2c8\ub77c \uc548\uc804\uacfc \uc0c8\ub85c\uc6b4 \uc0dd\ud65c\uc744 \ucc3e\ub294 \uc774\ub3d9\ub3c4 \uc788\uc5c8\ub2e4. \ub3c4\uc2dc\ub85c \ub4e4\uc5b4\uc628 \uc0ac\ub78c\uc5d0\uac8c\ub294 \ucd9c\ubc1c\uc9c0\uc5d0\uc11c \uacaa\uc740 \uc0c1\uc2e4\uacfc \uac08\ub4f1\uc774 \uc788\uc5c8\uc744 \uc218 \uc788\ub2e4. \ub3c4\ucc29\ud55c \uacf3\uc5d0\uc11c\ub294 \ub0af\uc120 \uae30\uc220\uacfc \ucde8\ud5a5\uc744 \uc804\ud558\ub294 \uc0ac\ub78c\uc774 \ub418\uae30\ub3c4 \ud588\ub2e4. \ubb38\ud654 \uad50\ub958\ub77c\ub294 \ubc1d\uc740 \ud45c\ud604 \ub4a4\uc5d0\ub3c4 \uc11c\ub85c \ub2e4\ub978 \uc0ac\uc815\uc758 \uc5ec\uc815\uc774 \uacb9\uccd0 \uc788\uc5c8\ub2e4\ub294 \uc810\uc744 \uae30\uc5b5\ud560 \ub9cc\ud558\ub2e4. \uc7a5\uc548\uc5d0 \uc804\ud574\uc9c4 \uac83\uc5d0\ub294 \uc0ac\uce58\ud488\uacfc \uc740\uc81c \uacf5\uc608\ud488\ubfd0 \uc544\ub2c8\ub77c \uc544\ub78d\u00b7\ud398\ub974\uc2dc\uc544\u00b7\uc911\uc559\uc544\uc2dc\uc544\uc758 \uc74c\uc545\uacfc \ucda4\ub3c4 \uc788\uc5c8\ub2e4. \uc774\uac83\uc740 \uad50\uc5ed\uc774 \uc0c1\ud488 \ubaa9\ub85d\uc744 \ub298\ub9ac\ub294 \ub370\uc11c \ub05d\ub098\uc9c0 \uc54a\uc558\ub2e4\ub294 \ub73b\uc774\ub2e4. \ubab8\uc73c\ub85c \uc775\ud78c \ud45c\ud604\uacfc \uadc0\ub85c \uc990\uae30\ub294 \ucde8\ud5a5\ub3c4 \uc0ac\ub78c\uc744 \ub530\ub77c \uc6c0\uc9c1\uc600\ub2e4. \uc5b4\ub5a4 \ubb3c\uac74\uc740 \uc0ac\uace0\ud314 \uc218 \uc788\uc9c0\ub9cc \uc74c\uc545\uacfc \ucda4\uc740 \ub4e3\uace0 \ubcf4\uace0 \ubc30\uc6b0\ub294 \uc2dc\uac04\uc774 \ud544\uc694\ud558\ub2e4. \ub0af\uc120 \ucde8\ud5a5\uc774 \ub3c4\uc2dc\uc5d0 \ub4e4\uc5b4\uc628\ub2e4\ub294 \uac83\uc740 \uc0ac\ub78c\ub4e4 \uc0ac\uc774\uc758 \ub9cc\ub0a8\uc774 \uacc4\uc18d\ub41c\ub2e4\ub294 \uc758\ubbf8\ub2e4. \uc218\ub3c4\uc758 \ud654\ub824\ud568\uc744 \uae08\uacfc \ube44\ub2e8\uc758 \uc591\uc73c\ub85c\ub9cc \uc0dd\uac01\ud558\uba74 \uc774\ub7f0 \uc6c0\uc9c1\uc774\ub294 \ubb38\ud654\ub294 \ub193\uce58\uae30 \uc27d\ub2e4. \uc5ec\ub7ec \uc9c0\uc5ed\uc758 \uc0ac\ub78c\uc774 \ubaa8\uc600\ub2e4\uace0 \uac01\uc790\uac00 \uac19\uc740 \uad8c\ub9ac\uc640 \uc601\ud5a5\ub825\uc744 \uac00\uc84c\ub2e4\uace0 \ubcfc \uc218\ub294 \uc5c6\ub2e4. \uad81\uc815\uc758 \uc678\uad50\uc640 \uc0c1\uc778\uc758 \uac70\ub798, \uc774\uc8fc\ubbfc\uc758 \uc77c\uc0c1\uc740 \uc11c\ub85c \ub2e4\ub978 \uc870\uac74\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc84c\ub2e4. \uad6d\uc81c\ub3c4\uc2dc\ub77c\ub294 \ub9d0\uc740 \ub9ce\uc740 \ucc28\uc774\uac00 \uac00\uae4c\uc774 \uc788\uc5c8\ub2e4\ub294 \ucd9c\ubc1c\uc810\uc774\uc9c0 \ud3c9\ub4f1\uc744 \ubcf4\uc99d\ud558\ub294 \ud3c9\uac00\ud45c\ub294 \uc544\ub2c8\ub2e4. \ub610 \uc7a5\uc548\uc5d0\uc11c \ub9cc\ub09c \uc885\uad50\uc640 \ubb38\ud654\uac00 \uc911\uad6d \uc804\uccb4\uc5d0 \uac19\uc740 \uc18d\ub3c4\ub85c \ud37c\uc84c\ub2e4\uace0 \ub9d0\ud560 \uc218\ub3c4 \uc5c6\ub2e4. \uc218\ub3c4\uc758 \ud2b9\ubcc4\ud55c \ud658\uacbd\uacfc \uac01 \uc9c0\uc5ed\uc758 \uc0dd\ud65c\uc744 \ub098\ub204\uc5b4 \ubcf4\uc544\uc57c \ud55c\ub2e4. \ud55c \ub3c4\uc2dc\uc758 \ud48d\uacbd\uc774 \ub113\uc740 \uc81c\uad6d \uc804\uccb4\uc758 \ubaa8\uc2b5\uc744 \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. 755\ub144\uc5d0 \uc2dc\uc791\ub41c \uc548\uc0ac\uc758 \ub09c\uc740 \ub2f9 \uc81c\uad6d\uc744 \ud06c\uac8c \ud754\ub4e4\uc5c8\ub2e4. \uad50\uc7ac\ub294 \uc624\ub79c \uc9c4\uc555 \uacfc\uc815\uacfc \uc774\ud6c4\uc758 \uc57d\ud654\ub97c \uc124\uba85\ud55c\ub2e4. \uc7a5\uc548\uc774 \uad6d\uc81c\uc801\uc774\uace0 \ud654\ub824\ud55c \uc218\ub3c4\uc600\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc815\uce58\uc640 \uad70\uc0ac\uc758 \uc704\uae30\ub97c \ub9c9\uc544 \uc8fc\uc9c0\ub294 \uc54a\uc558\ub2e4. \ub3c4\uc2dc\uc758 \ubb38\ud654\uc801 \ub9e4\ub825\uacfc \uad6d\uac00\uc758 \uc548\uc815\uc740 \uac19\uc740 \uc9c0\ud45c\uac00 \uc544\ub2c8\ub2e4. \uc0ac\ub78c\uc774 \ubaa8\uc774\uace0 \ubb3c\uac74\uc774 \uc624\uac00\ub358 \uad00\uacc4\ub3c4 \uc804\uc7c1\uacfc \uad8c\ub825\uc758 \ubcc0\ud654\uc5d0 \uc601\ud5a5\uc744 \ubc1b\ub294\ub2e4. \ubc88\uc131\ud558\ub358 \uac70\ub9ac\ub97c \uc0c1\uc0c1\ud560 \ub54c \uadf8 \ubaa8\uc2b5\uc744 \uc601\uc6d0\ud788 \uace0\uc815\ub41c \ud3c9\ud654\ub85c\uc6b4 \uc7a5\uba74\uc73c\ub85c \ub9cc\ub4e4\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc5ed\uc0ac\ub97c \ub354 \uc785\uccb4\uc801\uc73c\ub85c \ubcf4\uac8c \ud55c\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 \uc0c1\uc778\ub4e4\uc774 \uc9c1\ubb3c\uacfc \ubb3c\uac74\uc744 \uc0b4\ud53c\ub294 AI \ubd84\uc704\uae30 \uc0bd\ud654\ub2e4. \uc7a5\uc548\uc758 \ud2b9\uc815 \uc2dc\uc7a5 \ubc30\uce58\uc640 \ubcf5\uc2dd, \uc2e4\uc81c \uac70\ub798 \uc7a5\uba74\uc744 \uace0\uc99d\ud574 \ubcf5\uc6d0\ud55c \uc790\ub8cc\uac00 \uc544\ub2c8\ub2e4. \uadf8\ub9bc\uc5d0 \ubcf4\uc774\ub294 \uc778\ubb3c\uc744 \ud2b9\uc815 \ubbfc\uc871\uc758 \ub300\ud45c \ubaa8\uc2b5\uc73c\ub85c \ubc1b\uc544\ub4e4\uc77c \ud544\uc694\ub3c4 \uc5c6\ub2e4. \ud655\uc778\ud55c \uc0ac\uc2e4\uc740 \uc5ec\ub7ec \uc9c0\uc5ed \ucd9c\uc2e0\uc758 \uc0ac\ub78c\ub4e4\uc774 \uad50\uc5ed \uacf5\ub3d9\uccb4\uc640 \uc774\uc8fc\ub97c \ud1b5\ud574 \uc7a5\uc548\uc5d0 \ubaa8\uc600\ub2e4\ub294 \uc810\uc774\ub2e4. \uc0bd\ud654\ub294 \uadf8\ub7f0 \ub9cc\ub0a8\uc744 \uac00\uae4c\uc774 \ub290\ub07c\uac8c \ud558\ub294 \uc5ed\ud560\uc744 \ud55c\ub2e4. \uc5ed\uc0ac\uc801 \uadfc\uac70\ub294 \uae00\uc758 \uc790\ub8cc\uc5d0\uc11c, \uc0c1\uc0c1\uc758 \uc7a5\uba74\uc740 \uc774\ubbf8\uc9c0\uc758 \uc548\ub0b4\ub97c \ub530\ub77c \ub098\ub204\uc5b4 \uc77d\uc73c\uba74 \ub41c\ub2e4. \uc7a5\uc548\uc758 \uc774\uc57c\uae30\ub97c \ub2e4 \uc77d\uace0 \ud669\uc81c\uc758 \uc774\ub984\uc744 \ub354 \uc678\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub300\uc2e0 \uba3c \uacf3\uc5d0\uc11c \uc628 \uc0c1\uc778\uc774 \uc790\uae30 \ub9d0\uc744 \ub2e4\ub978 \ub9d0\uacfc \ub9de\ucd94\uace0, \ub0af\uc120 \uc74c\uc545\uc774 \ub204\uad70\uac00\uc758 \uadc0\uc5d0 \ucc98\uc74c \ub2ff\ub294 \uc7a5\uba74\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \ub3c4\uc2dc\uc758 \uc5ed\uc0ac\ub294 \uadf8\ub7f0 \ub9cc\ub0a8\ub3c4 \ud3ec\ud568\ud55c\ub2e4. \uac70\ub300\ud55c \uc218\ub3c4\uc758 \ud798\uc740 \ubaa8\ub4e0 \uac83\uc744 \ud63c\uc790 \ub9cc\ub4e4\uc5b4 \ub0c8\ub2e4\ub294 \ub370\ub9cc \uc788\uc9c0 \uc54a\uc558\ub2e4. \ub2e4\ub978 \uc9c0\uc5ed\uc5d0\uc11c \uc628 \uc0ac\ub78c\uacfc \ubb3c\uac74, \ud45c\ud604\uc744 \ub9cc\ub098\uba70 \uc0c8\ub85c\uc6b4 \uc0dd\ud65c\uc744 \ub9cc\ub4e4\uc5c8\ub2e4. \uc7a5\uc548\uc744 \uad6d\uc81c\ub3c4\uc2dc\ub85c \uae30\uc5b5\ud55c\ub2e4\ub294 \uac83\uc740 \uad81\uc804\uc758 \ub192\uc774 \uc606\uc5d0 \uc774\ub984\uc774 \uc798 \ub0a8\uc9c0 \uc54a\uc740 \uc774\ub3d9\uc758 \uc2dc\uac04\ub3c4 \ud568\uaed8 \ub193\ub294 \uc77c\uc774\ub2e4."}, {"id": "chicago-lion-sports-helmet", "title": "\uc2dc\uce74\uace0\uc758 \uc0ac\uc790\ub294 \uac00\ub054 \ud5ec\uba67\uc744 \uc4f4\ub2e4", "summary": "\uadfc\uc5c4\ud55c \uccad\ub3d9 \uc0ac\uc790\ub4e4\uc774 \uc2a4\ud3ec\uce20 \ud5ec\uba67\uc744 \uc4f0\uac8c \ub41c \uc0ac\uc5f0\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "cities", "category_title": "Cities", "subcategory": "Americas", "url": "stories/chicago-lion-sports-helmet/index.html", "image": "media/chicago-lion-sports-helmet.jpg", "alt": "\uc2dc\uce74\uace0\uc758 \uc0ac\uc790\ub294 \uac00\ub054 \ud5ec\uba67\uc744 \uc4f4\ub2e4\uc758 \uc8fc\uc81c\ub97c \ud45c\ud604\ud55c AI \uc124\uba85\uc6a9 \uc0bd\ud654. \uc2e4\uc81c \uc791\ud488\uc774\ub098 \uac74\ucd95\ubb3c\uc744 \uadf8\ub300\ub85c \uc7ac\ud604\ud55c \uc774\ubbf8\uc9c0\uac00 \uc544\ub2d9\ub2c8\ub2e4.", "text": "\uc2dc\uce74\uace0\uc758 \uc0ac\uc790\ub294 \uac00\ub054 \ud5ec\uba67\uc744 \uc4f4\ub2e4 \ubbf8\uc220\uad00 \uc55e \uc870\uac01\uc0c1\uc774 \ub3c4\uc2dc\uc758 \uc751\uc6d0\ub2e8\uc774 \ub418\ub294 \ub0a0 \uadfc\uc5c4\ud55c \uccad\ub3d9 \uc0ac\uc790\ub4e4\uc774 \uc2a4\ud3ec\uce20 \ud5ec\uba67\uc744 \uc4f0\uac8c \ub41c \uc0ac\uc5f0\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Americas \ub3c4\uc2dc \ubbf8\uc220\uad00 \uc785\uad6c\uc758 \uc0ac\uc790\ub77c\uba74 \uadfc\uc5c4\ud55c \ud45c\uc815\uc744 \uae30\ub300\ud558\uac8c \ub41c\ub2e4. \uadf8\ub7f0\ub370 \ubbf8\uad6d \uc2dc\uce74\uace0\uc5d0\uc11c\ub294 \uadf8 \uc0ac\uc790\uc5d0\uac8c \ucee4\ub2e4\ub780 \uc2a4\ud3ec\uce20 \ud5ec\uba67\uc744 \uc50c\uc6b0\uae30\ub3c4 \ud55c\ub2e4. \uc870\uac01\uc0c1\uc774 \uac11\uc790\uae30 \ub3d9\ub124 \uc751\uc6d0\ub2e8\uc774 \ub41c \uac83 \uac19\uc740 \ubaa8\uc2b5\uc774\ub2e4. \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc740 \uc9c0\uc5ed \ud300\uc744 \uc751\uc6d0\ud558\ub294 \uc0ac\uc790\ub4e4\uc758 \uc774\uc57c\uae30\ub97c \uacf5\uc2dd \uae00\uc5d0 \ub0a8\uacbc\ub2e4. \uc791\ud488\uc758 \uc81c\uc791 \uc5f0\ub3c4\ub9cc \uc54c\uba74 \ub05d\ub098\ub294 \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub2e4. \ub3c4\uc2dc \uc0ac\ub78c\ub4e4\uc774 \uc870\uac01\uc0c1\uacfc \uc5b4\ub5bb\uac8c \uc9c0\ub0b4\ub294\uc9c0\ub3c4 \uc774 \uc0ac\uc790\ub4e4\uc758 \uc774\ub825\uc774 \ub41c\ub2e4. \ubbf8\uc220\uad00 \uc124\uba85\uc5d0 \ub530\ub974\uba74 \uc0ac\uc790\ub4e4\uc740 \uc5d0\ub4dc\uc6cc\ub4dc \ucf00\ubbf8\uc2a4\uac00 \ub9cc\ub4e4\uc5c8\uace0 1894\ub144 \ubbf8\uc220\uad00 \uc815\ubb38 \uc55e\uc5d0 \uc124\uce58\ub418\uc5c8\ub2e4. \uadf8\ub7f0\ub370 \ub458\uc740 \ub611\uac19\uc740 \uc870\uac01\uc774 \uc544\ub2c8\ub2e4. \uc790\uc138\ub3c4 \ub2e4\ub974\uace0 \ubab8\uc758 \ud06c\uae30\uc640 \uac08\uae30\uc758 \ubaa8\uc591\ub3c4 \ub2e4\ub974\ub2e4. \ubd81\ucabd \uc0ac\uc790\ub294 \uba39\uc787\uac10\uc744 \ucc3e\uc544 \uc6c0\uc9c1\uc774\ub294 \ub4ef\ud55c \uc790\uc138\uc774\uace0 \ub0a8\ucabd \uc0ac\uc790\ub294 \ub2f9\ub2f9\ud788 \ubc84\ud2f0\ub294 \uc790\uc138\ub85c \uc18c\uac1c\ub41c\ub2e4. \uac19\uc740 \uc0ac\uc790\ucc98\ub7fc \ubcf4\uace0 \uc9c0\ub098\ucce4\ub2e4\uba74 \ub2e4\uc74c\uc5d0\ub294 \ub2e4\ub9ac\uc640 \uace0\uac1c\ub97c \ube44\uad50\ud574 \ubcfc \ub9cc\ud558\ub2e4. \ubbf8\uc220\uad00\uc740 \uc0ac\uc790\ub4e4\uc774 \uc2a4\ud3ec\uce20 \uc751\uc6d0\uc5d0 \ucc38\uc5ec\ud55c \uc77c\uc744 1985\ub144 \uc2dc\uc98c \uc2dc\uce74\uace0 \ubca0\uc5b4\uc2a4\uc758 \uc288\ud37c\ubcfc \uc9c4\ucd9c\uc744 \uc751\uc6d0\ud558\ub358 \ub54c\ubd80\ud130 \uc124\uba85\ud55c\ub2e4. \ub2f9\uc2dc\uc758 \ud5ec\uba67\uc740 \ub4a4\uc9d1\uc740 \ubc14\ube44\ud050 \uadf8\ub9b4\uc5d0 \uac04\ub2e8\ud55c \uc548\uba74 \ubcf4\ud638\ub300\ub97c \ubd99\uc5ec \ub9cc\ub4e0 \uac83\uc774\uc5c8\ub2e4\uace0 \ud55c\ub2e4. \uac00\uac8c\uc5d0\uc11c \uc0ac \uc628 \uae30\uc131\ud488\uc774 \uc544\ub2c8\uc5c8\ub358 \uc148\uc774\ub2e4. \uc0ac\ub78c\ubcf4\ub2e4 \ud6e8\uc52c \ud070 \uba38\ub9ac\uc5d0 \ub9de\ucdb0\uc57c \ud558\ub2c8 \uc751\uc6d0 \ub3c4\uad6c\ub3c4 \ud2b9\ubcc4\ud55c \uc81c\uc791\uc774 \ud544\uc694\ud588\ub2e4. \ubbf8\uc220\uad00 \uc55e\uc5d0\uc11c\ub294 \uc791\ud488\uc744 \uac10\uc0c1\ud558\ub294 \uc77c\uacfc \uc2a4\ud3ec\uce20\ub97c \uc751\uc6d0\ud558\ub294 \uc77c\uc774 \uc774\ub807\uac8c \ub9cc\ub0ac\ub2e4. \ub450 \uc0ac\uc790\ub294 \ud06c\uae30\uc640 \uac08\uae30, \uc790\uc138\uac00 \uc11c\ub85c \ub2e4\ub974\ub2e4. \uacf5\uc2dd \uae00\uc740 \ubd81\ucabd \uc0ac\uc790\ub97c \uba39\uc787\uac10\uc744 \ucc3e\uc544 \uc6c0\uc9c1\uc774\ub294 \ub4ef\ud55c \uc774\ub984\uc73c\ub85c, \ub0a8\ucabd \uc0ac\uc790\ub97c \ub3c4\uc804\uc801\uc778 \uc790\uc138\ub85c \ubc84\ud2f0\ub294 \uc774\ub984\uc73c\ub85c \uc18c\uac1c\ud55c\ub2e4. \uac19\uc740 \ucd9c\uc785\ubb38\uc744 \uc0ac\uc774\uc5d0 \ub450\uace0 \uc788\uc5b4\ub3c4 \ud55c \ub9c8\ub9ac\ub97c \ubcf5\uc0ac\ud574 \ub193\uc740 \uad00\uacc4\uac00 \uc544\ub2c8\ub2e4. \uc791\ud488 \uc55e\uc5d0\uc11c\ub294 \uba3c\uc800 \uc55e\ub2e4\ub9ac\uac00 \uc5b4\ub514\uc5d0 \ub193\uc600\uace0 \uace0\uac1c\uac00 \uc5b4\ub290 \ucabd\uc73c\ub85c \ud5a5\ud558\ub294\uc9c0 \ube44\uad50\ud574 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uc774 \ucc28\uc774\ub294 \ud5ec\uba67\uc744 \ub9cc\ub4e4 \ub54c \ub73b\ubc16\uc758 \uc2e4\ubb34 \ubb38\uc81c\uac00 \ub41c\ub2e4. \ud55c\ucabd\uc5d0 \ub9de\ub294 \uc7a5\uc2dd\uc774 \ub2e4\ub978 \ucabd\uc5d0\ub3c4 \uaf2d \ub9de\uc73c\ub9ac\ub77c\ub294 \ubcf4\uc7a5\uc774 \uc5c6\uae30 \ub54c\ubb38\uc774\ub2e4. \uc870\uac01\uc758 \uac1c\uc131\uc744 \uac10\uc0c1\ud558\ub294 \uc77c\uacfc \uc7a5\uc2dd\ud488\uc758 \uce58\uc218\ub97c \uc7ac\ub294 \uc77c\uc774 \uac19\uc740 \ud2b9\uc9d5\uc744 \ubc14\ub77c\ubcf8\ub2e4. \ub3c4\uc2dc\uc758 \ucd95\uc81c\ub3c4 \uacb0\uad6d \uc2e4\uc81c \ubb3c\uac74\uc758 \ud06c\uae30\uc640 \ubaa8\uc591\uc744 \ub2e4\ub8e8\ub294 \uc0ac\ub78c\ub4e4\uc758 \uc190\uc744 \uac70\uccd0\uc57c \uc644\uc131\ub41c\ub2e4. \ubbf8\uc220\uad00\uc740 2007\ub144 \ubca0\uc5b4\uc2a4 \uc751\uc6d0 \ud589\uc0ac\ub97c \uc900\ube44\ud558\ub358 \uaca8\uc6b8\uc758 \uc77c\uc744 \uc804\ud55c\ub2e4. \uac70\ub300\ud55c \ud50c\ub77c\uc2a4\ud2f1 \ud5ec\uba67\uc744 \ubd81\ucabd \uc0ac\uc790\uc758 \uac08\uae30\uc5d0 \ub9de\ucd94\ub294 \uacfc\uc815\uc5d0\uc11c \uc77c\ubd80\uac00 \uae68\uc84c\ub2e4. \ucd94\uc6b4 \ub0a0 \uc7ac\ub8cc\uac00 \uc218\ucd95\ud55c \uc0c1\ud0dc\uc5d0\uc11c \uc7a5\uc2dd\uc744 \ub298\ub824 \ub07c\uc6b0\ub2e4 \ubb38\uc81c\uac00 \uc0dd\uacbc\ub2e4\ub294 \uc124\uba85\uc774\ub2e4. \uc0ac\uc790\uc758 \ubab8\uc774 \uc544\ub2c8\ub77c \ubcc4\ub3c4\ub85c \uc81c\uc791\ud55c \ud5ec\uba67\uc5d0\uc11c \uc77c\uc5b4\ub09c \uc0ac\uace0\uc600\ub2e4. \uc7a5\uc2dd\uc740 \ubc24\uc0ac\uc774\uc5d0 \uc218\ub9ac\ud574 \ub2e4\uc74c \ub0a0 \ub2e4\uc2dc \uc124\uce58\ud588\ub2e4. \uc774\ud6c4 \ud300\uc758 \ud328\ubc30\ub97c \uc0ac\uc790 \ud0d3\uc73c\ub85c \ub3cc\ub9ac\ub294 \ub18d\ub2f4\ub3c4 \uc788\uc5c8\uc9c0\ub9cc, \ubbf8\uc220\uad00\uc740 \uadf8 \ub9d0\uc744 \uc0ac\uc2e4\ub85c \ubc1b\uc544\ub4e4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uc774 \uc77c\ud654\uc758 \uc7ac\ubbf8\ub294 \uc2b9\ud328\ub97c \uc810\uce58\ub294 \ub370\ubcf4\ub2e4 \uc870\uac01\uc0c1\ub3c4 \uacc4\uc808\uacfc \uc7ac\ub8cc\uc758 \uc601\ud5a5\uc744 \ubc1b\ub294 \ud589\uc0ac\uc758 \ubb34\ub300\uac00 \ub41c\ub2e4\ub294 \ub370 \uc788\ub2e4. \ub3c4\uc2dc\uc758 \uc775\uc0b4 \ub4a4\uc5d0\ub294 \uc81c\uc791\uacfc \uc218\uc120\uc758 \uc2dc\uac04\ub3c4 \ub4e4\uc5b4 \uc788\ub2e4. \ubbf8\uc220\uad00\uc740 \uc791\ud488\uc744 \ubcf4\ub7ec \ucc3e\uc544\uac00\ub294 \uc7a5\uc18c\uc9c0\ub9cc \uc815\ubb38 \uc55e\uc740 \uac70\ub9ac\ub97c \uc9c0\ub098\ub358 \uc0ac\ub78c\ub3c4 \ub9cc\ub098\ub294 \uacf5\uac04\uc774\ub2e4. \ud5ec\uba67\uc744 \uc4f4 \uc0ac\uc790\ub294 \uc785\uc7a5\uad8c\uc744 \uc0ac\uc9c0 \uc54a\uc740 \uc2dc\ubbfc\uc5d0\uac8c\ub3c4 \uadf8\ub0a0\uc758 \uc774\uc57c\uae30\ub97c \uac74\ub128\ub2e4. \ud2b9\uc815 \uc791\ud488\uc744 \uc798 \uc544\ub294 \uc0ac\ub78c\ub9cc \ubc18\uc751\ud560 \uc218 \uc788\ub294 \ud45c\uc9c0\uac00 \uc544\ub2c8\ub77c \uc9c0\uc5ed \ud300\uc758 \uc18c\uc2dd\uc744 \uc544\ub294 \uc0ac\ub78c\uc774\ub77c\uba74 \ud568\uaed8 \uc54c\uc544\ubcfc \uc218 \uc788\ub294 \ubaa8\uc2b5\uc774 \ub41c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc870\uac01\uc758 \uc6d0\ub798 \ub73b\uc774 \ubaa8\ub450 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadfc\uc5c4\ud55c \uc790\uc138\ub294 \uadf8\ub300\ub85c\uc778\ub370 \uc784\uc2dc \uc7a5\uc2dd\uc774 \uc5b9\ud788\uba74\uc11c \uc0c8\ub85c\uc6b4 \ud45c\uc815\uc774 \uc0dd\uae34\ub2e4. \ubc14\ub00c\uc9c0 \uc54a\ub294 \ubd80\ubd84\uacfc \uc7a0\uc2dc \ub2ec\ub77c\uc9c0\ub294 \ubd80\ubd84\uc774 \ud568\uaed8 \ubcf4\uc774\uae30\uc5d0 \ub354 \uc7ac\ubbf8\uc788\ub2e4. \uac19\uc740 \uc7a5\uc18c\ub97c \uc5ec\ub7ec \ubc88 \uc9c0\ub098\uac00\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc774\ub7f0 \uc791\uc740 \ubcc0\ud654\uac00 \uacc4\uc808\uc774\ub098 \ud589\uc0ac\uc758 \uae30\uc5b5\uc744 \ub0a8\uae38 \uc218 \uc788\ub2e4. 1894\ub144 \uc124\uce58\ub77c\ub294 \uc774\ub825\uc740 \uc0ac\uc790\uac00 \uc5b8\uc81c \uadf8\uacf3\uc5d0 \uc654\ub294\uc9c0 \uc54c\ub824 \uc900\ub2e4. \uc751\uc6d0 \ud5ec\uba67\uc758 \uc77c\ud654\ub294 \uadf8 \ub4a4\uc5d0 \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub5a4 \uad00\uacc4\ub97c \ub9cc\ub4e4\uc5b4 \uc654\ub294\uc9c0 \ubcf4\uc5ec \uc900\ub2e4. \uacf5\uacf5 \uc870\uac01\uc758 \uc0dd\uc560\ub97c \uc81c\uc791\uacfc \uc124\uce58\uc5d0\uc11c \ub05d\ub0b4\uc9c0 \uc54a\uc73c\uba74 \uc218\ub9ac\uc640 \ud589\uc0ac, \uc2dc\ubbfc\uc758 \uc0ac\uc9c4\ub3c4 \ud568\uaed8 \uc9c8\ubb38\ud560 \uc218 \uc788\ub2e4. \uc791\ud488\uc740 \uc6c0\uc9c1\uc774\uc9c0 \uc54a\uc544\ub3c4 \uc8fc\ubcc0\uc758 \uc4f0\uc784\uacfc \uae30\uc5b5\uc740 \ub2ec\ub77c\uc9c4\ub2e4. \ubc29\ubb38\ud560 \ub54c \ud5ec\uba67\uc774 \uc5c6\ub354\ub77c\ub3c4 \uc774\uc57c\uae30\uac00 \ud2c0\ub9b0 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud589\uc0ac \ub54c\uc758 \ubcc0\ud654\uc640 \ub298 \ubcfc \uc218 \uc788\ub294 \ubaa8\uc2b5\uc744 \uad6c\ubd84\ud558\uba74 \ub41c\ub2e4. \uc0ac\uc790\ub97c \ub2e4\uc2dc \ubcf4\uac8c \ub41c\ub2e4\uba74 \uba3c\uc800 \ub450 \uc790\uc138\uc758 \ucc28\uc774\ub97c \ucc3e\uace0, \ub2e4\uc74c\uc5d0\ub294 \uc9c0\ub098\uac00\ub294 \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub290 \ucabd\uc5d0\uc11c \uba48\ucd94\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \ud55c \uc870\uac01\uc0c1\uc744 \uac10\uc0c1\ud558\ub294 \uc77c\uc774 \ub3c4\uc2dc\uac00 \uc790\uae30 \uc0c1\uc9d5\uc744 \uc0ac\uc6a9\ud558\ub294 \ubc29\uc2dd\uc744 \uc77d\ub294 \uc77c\ub85c \uc774\uc5b4\uc9c4\ub2e4. \uc774\ud6c4 \uc0ac\uc790\ub4e4\uc740 \uc544\uc774\uc2a4\ud558\ud0a4 \ud300 \ube14\ub799\ud638\ud06c\uc2a4\ub97c \uc751\uc6d0\ud558\ub294 \ud5ec\uba67\ub3c4 \uc37c\ub2e4. \ub2e4\ub9cc \ubc29\ubb38\ud560 \ub54c\ub9c8\ub2e4 \ud5ec\uba67\uc744 \ubcfc \uc218 \uc788\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ud2b9\uc815 \uc751\uc6d0 \ud589\uc0ac\uc5d0 \ub9de\ucdb0 \uc637\ucc28\ub9bc\uc774 \ub2ec\ub77c\uc9c0\ub294 \uc870\uac01\uc0c1\ub4e4\uc774\ub2e4. \uc624\ub798\ub41c \uacf5\uacf5 \uc870\uac01\uc740 \uac00\ub9cc\ud788 \uc11c \uc788\uae30\ub9cc \ud558\ub294 \ubb3c\uac74\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \ud558\uc9c0\ub9cc \uc8fc\ubcc0 \uc0ac\ub78c\ub4e4\uc774 \ubb34\uc5b8\uac00\ub97c \uc50c\uc6b0\uace0, \uc0ac\uc9c4\uc744 \ucc0d\uace0, \ucd94\uc5b5\uc744 \ubcf4\ud0dc\uba74 \uc0c8\ub85c\uc6b4 \uc774\uc57c\uae30\uac00 \ubd99\ub294\ub2e4. \uc2dc\uce74\uace0\uc758 \uc0ac\uc790\ub4e4\uc740 \ubbf8\uc220\uad00\uc744 \uc9c0\ud0a4\ub294 \ub3d9\uc2dc\uc5d0 \ub3c4\uc2dc\uc758 \uae30\ubd84\uc744 \ud568\uaed8 \ub098\ub204\uace0 \uc788\ub2e4."}, {"id": "cordoba-oranges-and-connections", "title": "\ucf54\ub974\ub3c4\ubc14 \u2014 \uc624\ub80c\uc9c0\ub098\ubb34 \ub4a4\uc5d0\uc11c \uc9c0\uc911\ud574\ub97c \ub9cc\ub098\ub2e4", "summary": "\uc911\uc138 \ucf54\ub974\ub3c4\ubc14\uc758 \uac10\uade4 \uc7ac\ubc30\uc640 \uad50\uc5ed\u00b7\ud559\ubb38\uc744 \ud1b5\ud574 \ub3c4\uc2dc \ud48d\uacbd\uc5d0 \uacb9\uce5c \uc774\ub3d9\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "cities", "category_title": "Cities", "subcategory": "Europe", "url": "stories/cordoba-oranges-and-connections/index.html", "image": "media/cordoba-oranges-and-connections.png", "alt": "\uac10\uade4\ub098\ubb34\uc640 \uadf8\ub298, \ucc45\uacfc \uadf8\ub987\uc774 \ub193\uc778 \uc9c0\uc911\ud574\ud48d \ub730\uc758 AI \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\ucf54\ub974\ub3c4\ubc14 \u2014 \uc624\ub80c\uc9c0\ub098\ubb34 \ub4a4\uc5d0\uc11c \uc9c0\uc911\ud574\ub97c \ub9cc\ub098\ub2e4 \ub3c4\uc2dc\uc758 \ud48d\uacbd\uc740 \uba3c \uacf3\uc5d0\uc11c \uc628 \uc5f0\uacb0\ub85c \uc790\ub77c\uae30\ub3c4 \ud55c\ub2e4 \uc911\uc138 \ucf54\ub974\ub3c4\ubc14\uc758 \uac10\uade4 \uc7ac\ubc30\uc640 \uad50\uc5ed\u00b7\ud559\ubb38\uc744 \ud1b5\ud574 \ub3c4\uc2dc \ud48d\uacbd\uc5d0 \uacb9\uce5c \uc774\ub3d9\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Europe \ub3c4\uc2dc \uc2a4\ud398\uc778 \ub0a8\ubd80\uc758 \ucf54\ub974\ub3c4\ubc14\ub97c \ub5a0\uc62c\ub9ac\uba74 \ud587\ube5b\uacfc \uadf8\ub298, \ub098\ubb34\uac00 \uc788\ub294 \ub730\uc758 \ud48d\uacbd\uc774 \uc798 \uc5b4\uc6b8\ub9b0\ub2e4. \uc774\ub7f0 \uc774\ubbf8\uc9c0\ub294 \uadf8\uc800 \ub530\ub73b\ud55c \ub0a0\uc528\uc758 \uacb0\uacfc\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \ud55c \ub3c4\uc2dc\uc5d0\uc11c \ubb34\uc5c7\uc744 \uae30\ub974\uace0 \uc5b4\ub5a4 \ub9d0\uc744 \ub098\ub204\uc5c8\ub294\uc9c0\ub294 \uba3c \uc9c0\uc5ed\uacfc\uc758 \uc5f0\uacb0\uc5d0\ub3c4 \uc601\ud5a5\uc744 \ubc1b\ub294\ub2e4. \uc911\uc138 \ucf54\ub974\ub3c4\ubc14\ub294 \uc9c0\uc911\ud574\uc758 \uc5ec\ub7ec \uacf3\uacfc \uc774\uc5b4\uc9c4 \ub3c4\uc2dc\uc600\ub2e4. \uad50\uc7ac\ub294 \uc774\uacf3\uc774 \uc624\ub80c\uc9c0\uc640 \ub77c\uc784, \ub808\ubaac\uc744 \uae30\ub974\ub294 \uacf3\uc73c\ub85c\ub3c4 \uc54c\ub824\uc84c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uacfc\uc77c \uc774\ub984 \uc138 \uac1c\uc5d0\uc11c \uc2dc\uc791\ud558\uba74 \uc655\uc870\uc758 \uc5f0\ud45c\uc640\ub294 \uc870\uae08 \ub2e4\ub978 \uae38\ub85c \ub3c4\uc2dc\uc758 \uc5ed\uc0ac\ub97c \uac78\uc5b4 \ubcfc \uc218 \uc788\ub2e4. 8\uc138\uae30 \uc774\ubca0\ub9ac\uc544\ubc18\ub3c4\uc758 \uc54c\uc548\ub2ec\ub8e8\uc2a4\uc5d0\uc11c\ub294 \uc6b0\ub9c8\uc774\uc57c \uac00\ubb38\uc758 \ud1b5\uce58\uac00 \uc790\ub9ac \uc7a1\uc558\ub2e4. \uc555\ub4dc \uc54c\ub77c\ud750\ub9cc 1\uc138\ub294 \ucf54\ub974\ub3c4\ubc14\ub97c \uc218\ub3c4\ub85c \uc0bc\uc558\ub2e4. \uc774 \ub3c4\uc2dc\ub294 \ubd81\uc544\ud504\ub9ac\uce74\uc640 \uc911\ub3d9 \ub4f1 \uc9c0\uc911\ud574 \uc138\uacc4\uc640 \uc0c1\uc5c5\uc801\u00b7\uc678\uad50\uc801 \uad00\uacc4\ub97c \uc774\uc5b4 \uac14\ub2e4. \ubc14\ub2e4\ub97c \uad6d\uacbd\ucc98\ub7fc\ub9cc \uc0dd\uac01\ud558\uba74 \uc800\ud3b8\uc758 \uc9c0\uc5ed\uc740 \uba40\ub9ac \ub5a8\uc5b4\uc9c4 \ub2e4\ub978 \uc138\uacc4\uac00 \ub41c\ub2e4. \uadf8\ub7ec\ub098 \ud56d\ud574\uc640 \uad50\uc5ed\uc758 \uae38\uc744 \uadf8\ub9ac\uba74 \ub3c4\uc2dc\ub97c \uc5f0\uacb0\ud558\ub294 \ud1b5\ub85c\ub3c4 \ub098\ud0c0\ub09c\ub2e4. \ucf54\ub974\ub3c4\ubc14\uc758 \uc131\uc7a5\uc740 \ubc18\ub3c4 \uc548\ucabd\uc758 \uc0ac\uc815\ub9cc\uc73c\ub85c \uc124\uba85\ub418\uc9c0 \uc54a\uc558\uace0, \ubc14\uae65\uc5d0\uc11c \uc624\uac00\ub294 \ubb3c\uac74\uacfc \uc0ac\ub78c\uc774 \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud588\ub2e4. \uad50\uc7ac\ub294 \uc774\ub7f0 \uc5f0\uacb0\uc744 \ud1b5\ud574 \uac10\uade4\ub958\uc640 \uc0ac\ud0d5\uc218\uc218, \uba74\ud654 \uac19\uc740 \ub18d\uc0b0\ubb3c\uc774 \ub354 \uba3c \uacf3\uc5d0\uc11c \uc774\ubca0\ub9ac\uc544\ubc18\ub3c4\ub85c \uc804\ud574\uc84c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc624\ub298 \ud48d\uacbd\uc5d0 \uc790\uc5f0\uc2a4\ub7fd\uac8c \ub4e4\uc5b4 \uc788\ub294 \uc791\ubb3c\ub3c4 \uc5b8\uc81c\ub098 \uac19\uc740 \uc790\ub9ac\uc5d0\uc11c \uc7ac\ubc30\ub418\uc5c8\ub358 \uac83\uc740 \uc544\ub2d0 \uc218 \uc788\ub2e4. \ubb3c\ub860 \ud604\uc7ac \ucf54\ub974\ub3c4\ubc14\uc758 \ud2b9\uc815 \ub098\ubb34\uac00 \uc911\uc138\uc758 \uc5b4\ub290 \ud488\uc885\uc744 \uc9c1\uc811 \uc774\uc5b4 \uc654\ub2e4\uace0 \uc774 \uc790\ub8cc\ub9cc\uc73c\ub85c \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc774\ubc88 \uc774\uc57c\uae30\ub294 \uac1c\ubcc4 \uc218\ubaa9\uc758 \uc871\ubcf4\uac00 \uc544\ub2c8\ub77c \uc791\ubb3c\uacfc \uc7ac\ubc30 \ubb38\ud654\uc758 \uc774\ub3d9\uc744 \ub2e4\ub8ec\ub2e4. \uc775\uc219\ud55c \uacfc\uc77c\ub3c4 \uad50\uc5ed\uc758 \uc5ed\uc0ac\uc640 \ud568\uaed8 \ubcf4\uba74 \ub3c4\uc2dc\uc758 \ud48d\uacbd\uc744 \ub2e4\ub974\uac8c \uc77d\uac8c \ud55c\ub2e4. 10\uc138\uae30 \ucf54\ub974\ub3c4\ubc14\uac00 \ubc88\uc131\ud560 \ub54c\uc5d0\ub294 \uad50\uc5ed\uacfc \ud568\uaed8 \uc7a5\uc778\uacfc \uc0c1\uc778, \ud559\uc790\uc640 \uc774\uc8fc\ubbfc\uc774 \ubaa8\uc600\ub2e4. \ub3c4\uc2dc\uac00 \ud06c\ub2e4\ub294 \uac83\uc740 \uac74\ubb3c\uc774 \ub9ce\ub2e4\ub294 \ub73b\ub9cc\uc774 \uc544\ub2c8\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uae30\uc220\uacfc \uacbd\ud5d8\uc744 \uac00\uc9c4 \uc0ac\ub78c\uc774 \uac00\uae4c\uc6b4 \uacf5\uac04\uc5d0\uc11c \ub9cc\ub0a0 \uc218 \uc788\ub2e4\ub294 \uc758\ubbf8\ub3c4 \uc788\ub2e4. \uc7a5\uc778\uc758 \ubb3c\uac74\uc5d0\ub294 \uc7ac\ub8cc\uac00 \ud544\uc694\ud558\uace0 \uc0c1\uc778\uc5d0\uac8c\ub294 \uac70\ub798\ud560 \uc0c1\ub300\uac00 \ud544\uc694\ud558\ub2e4. \uae00\uc744 \ubc30\uc6b0\uace0 \uac00\ub974\uce58\ub294 \ud65c\ub3d9\uc5d0\ub3c4 \uc0dd\ud65c\uc744 \uc720\uc9c0\ud560 \ud658\uacbd\uc774 \uc788\uc5b4\uc57c \ud55c\ub2e4. \uc774\ub7f0 \ud65c\ub3d9\uc774 \ud55c \ub3c4\uc2dc\uc5d0 \uacb9\uce60 \ub54c \ub3c4\uc2dc\ub294 \ub2e8\uc21c\ud788 \uc778\uad6c\uac00 \ubaa8\uc778 \uc7a5\uc18c\ubcf4\ub2e4 \ubcf5\uc7a1\ud55c \uad00\uacc4\uc758 \uacf5\uac04\uc774 \ub41c\ub2e4. \ucf54\ub974\ub3c4\ubc14\ub294 \uad50\uc5ed\ubfd0 \uc544\ub2c8\ub77c \ud559\ubb38\uacfc \uc608\uc220\uc758 \uc911\uc2ec\uc73c\ub85c\ub3c4 \uc131\uc7a5\ud588\ub2e4. \uad50\uc7ac\ub294 \ucf58\uc2a4\ud0c4\ud2f0\ub178\ud3f4\ub9ac\uc2a4\uc640 \ubc14\uadf8\ub2e4\ub4dc\uc5d0 \uacac\uc904 \ub9cc\ud55c \ub3c4\uc2dc\ub85c \uc18c\uac1c\ud55c\ub2e4. \uc774\ub294 \uc138 \ub3c4\uc2dc\uac00 \ubaa8\ub4e0 \uc810\uc5d0\uc11c \uac19\uc558\ub2e4\ub294 \ub9d0\ubcf4\ub2e4 \ub2f9\uc2dc\uc758 \ub113\uc740 \uad50\ub958 \uc18d\uc5d0\uc11c \ucf54\ub974\ub3c4\ubc14\uc758 \uc704\uc0c1\uc744 \uc774\ud574\ud558\ub294 \ud45c\ud604\uc774\ub2e4. \ubc30\uc6c0\uc740 \ub3c4\uc2dc\ub97c \ub4dc\ub098\ub4dc\ub294 \uae38\uacfc \ubb34\uad00\ud558\uc9c0 \uc54a\uc558\ub2e4. \ubb3c\uac74\uacfc \ud568\uaed8 \ucc45\uacfc \uc9c0\uc2dd, \uac00\ub974\uce58\ub294 \uc0ac\ub78c\uc774 \uc774\ub3d9\ud560 \uc218 \uc788\uc5c8\uae30 \ub54c\ubb38\uc774\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc0c1\uc5c5\uc774 \ud65c\ubc1c\ud558\uba74 \uc800\uc808\ub85c \ubaa8\ub450\uac00 \uad50\uc721\uc744 \ub204\ub9b0\ub2e4\uace0 \uc0dd\uac01\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc5f0\uacb0\uc740 \uac00\ub2a5\uc131\uc744 \ub113\ud600 \uc8fc\uc9c0\ub9cc \uadf8 \uae30\ud68c\ub97c \ub204\ub9ac\ub294 \uc870\uac74\uae4c\uc9c0 \uac19\uac8c \ub9cc\ub4e4\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc54c\uc548\ub2ec\ub8e8\uc2a4\uc5d0\ub294 \uc5ec\ub7ec \uc885\uad50\uc640 \ubbfc\uc871\uc774 \ud568\uaed8 \uc0b4\uc544\uac00\uba70 \ub9cc\ub4e4\uc5b4 \ub0b8 \ubb38\ud654\uac00 \uc788\uc5c8\ub2e4. \uc774 \uc0ac\uc2e4\uc740 \uc911\uc694\ud558\uc9c0\ub9cc \uc5b8\uc81c\ub098 \ud3c9\ub4f1\ud558\uace0 \uac08\ub4f1 \uc5c6\ub294 \uc0ac\ud68c\uc600\ub2e4\ub294 \ub73b\uc73c\ub85c \ubc14\uafc0 \uc218\ub294 \uc5c6\ub2e4. \uacf5\uc874\uacfc \uad8c\ub825\uc758 \ucc28\uc774, \uc815\uce58\uc801 \uacbd\uc7c1\uc740 \uac19\uc740 \uc2dc\ub300\uc5d0 \ud568\uaed8 \uc874\uc7ac\ud560 \uc218 \uc788\ub2e4. \uad50\uc7ac\ub3c4 \uad00\uc6a9\uc744 \ubcf4\uc774\ub294 \ud1b5\uce58\uac00 \uc788\uc5c8\ub358 \ud55c\ud3b8 \ub2e4\ub978 \uc2e0\uc559\uc758 \uc9c0\ubc30\uc790\ub4e4\uacfc \uc804\uc7c1\uc774 \uc774\uc5b4\uc84c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud568\uaed8 \uc0b4\uc558\ub2e4\ub294 \ud55c \ubb38\uc7a5\uc744 \ub0ad\ub9cc\uc801\uc778 \ud48d\uacbd\uc73c\ub85c\ub9cc \ub9cc\ub4e4\uba74 \ub2f9\uc2dc \uc8fc\ubbfc\uc758 \ub2e4\ub978 \uc870\uac74\uc744 \ub193\uce5c\ub2e4. \ub3c4\uc2dc\uc758 \uc131\ucde8\ub97c \uc54c\uc544\ubcf4\ub294 \uc77c\uacfc \uadf8 \uc548\uc758 \uae34\uc7a5\uc744 \uc778\uc815\ud558\ub294 \uc77c\uc740 \ud568\uaed8 \ud560 \uc218 \uc788\ub2e4. \ucf54\ub974\ub3c4\ubc14\ub97c \uc911\uc2ec\uc73c\ub85c \ud55c \uc815\uce58\uc801 \ud1b5\ud569\uc740 \uacc4\uc18d \uc720\uc9c0\ub418\uc9c0 \uc54a\uc558\ub2e4. \uc9c0\ubc30\uce35 \ub0b4\ubd80\uc758 \uac08\ub4f1\uacfc \ubd84\uc5f4\uc774 \uc0dd\uacbc\uace0 \uc54c\uc548\ub2ec\ub8e8\uc2a4\uc5d0\ub294 \uc5ec\ub7ec \ud6c4\uacc4 \uad6d\uac00\uac00 \ub4f1\uc7a5\ud588\ub2e4. \ubb38\ud654\uc640 \uad50\uc5ed\uc774 \ubc88\uc131\ud588\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uc815\uce58\uc801 \uc548\uc815\uae4c\uc9c0 \uc790\ub3d9\uc73c\ub85c \ubcf4\uc7a5\ub418\uc9c0\ub294 \uc54a\uc558\ub358 \uac83\uc774\ub2e4. \uc774\ud6c4\uc758 \uad00\uacc4\ub3c4 \ub2e8\uc21c\ud788 \uc885\uad50\uac00 \uac19\uc740 \uc0ac\ub78c\ub07c\ub9ac \ud55c\ud3b8\uc744 \uc774\ub8ec \ubaa8\uc2b5\ub9cc\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uad50\uc7ac\ub294 \ubb34\uc2ac\ub9bc \uad6d\uac00\ub4e4\ub07c\ub9ac \ub2e4\ud22c\uace0 \uae30\ub3c5\uad50 \uc138\ub825\uacfc \ub3d9\ub9f9\uc744 \ub9fa\uae30\ub3c4 \ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub3c4\uc2dc\uc758 \uc5ed\uc0ac\ub294 \uc544\ub984\ub2e4\uc6b4 \uc804\uc131\uae30\uc640 \uac11\uc791\uc2a4\ub7ec\uc6b4 \uc885\ub9d0 \ub450 \uc7a5\uba74\ubcf4\ub2e4 \ub9ce\uc740 \uc120\ud0dd\uc73c\ub85c \uc774\ub8e8\uc5b4\uc838 \uc788\uc5c8\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \uac10\uade4\ub098\ubb34\uc640 \uadf8\ub298\uc9c4 \ub730\uc744 \ud45c\ud604\ud55c AI \uc0bd\ud654\ub2e4. \ucf54\ub974\ub3c4\ubc14\uc758 \ud2b9\uc815 \uc815\uc6d0\uc774\ub098 \uc911\uc138 \uc8fc\ud0dd\uc744 \uc815\ud655\ud788 \ubcf5\uc6d0\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uc774 \uadf8\ub9bc\uc744 \uadfc\uac70\ub85c \ub2f9\uc2dc \uc9d1\uc758 \ubc30\uce58\uc640 \uc0dd\ud65c \ub3c4\uad6c\ub97c \ud655\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub300\uc2e0 \ub098\ubb34\uc640 \uadf8\ub298, \uc0ac\ub78c\ub4e4\uc774 \uc26c\uc5b4 \uac08 \uc218 \uc788\ub294 \uc791\uc740 \uacf5\uac04\uc744 \ub5a0\uc62c\ub9ac\ub294 \uc785\uad6c\ub85c \ubcfc \uc218 \uc788\ub2e4. \uc2e4\uc81c\ub85c \ud655\uc778\ud55c \uc791\ubb3c\uc758 \uc774\ub3d9\uacfc \ub3c4\uc2dc\uc758 \uc131\uc7a5\uc740 \uadfc\uac70\uc790\ub8cc\uc5d0\uc11c \uc77d\uace0, \uadf8\ub9bc\uc740 \uae00\ub85c \ub4e4\uc5b4\uac00\ub294 \ubd84\uc704\uae30\ub97c \ub3d5\ub294\ub2e4. \uc790\ub8cc\uc640 \uc0c1\uc0c1\uc758 \uc5ed\ud560\uc744 \ub098\ub204\uba74 \ud48d\uacbd\uc744 \ud3b8\ud558\uac8c \uac10\uc0c1\ud560 \uc218 \uc788\ub2e4. \uc624\ub80c\uc9c0 \ud55c \uc54c\ub9cc\uc73c\ub85c \ucf54\ub974\ub3c4\ubc14\uc758 \uc5ed\uc0ac\ub97c \ubaa8\ub450 \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \uba3c \uacf3\uc5d0\uc11c \uc628 \uc791\ubb3c\uc774 \ub3c4\uc2dc\uc758 \uc775\uc219\ud55c \ud48d\uacbd\uc774 \ub420 \uc218 \uc788\ub2e4\ub294 \uc810\uc740 \ubcf4\uc5ec \uc900\ub2e4. \uc0c1\uc778\uacfc \uc7a5\uc778, \ud559\uc790\uac00 \ub4dc\ub098\ub4e0 \uae38\ub3c4 \ube44\uc2b7\ud558\uac8c \ub3c4\uc2dc\uc758 \uc131\uaca9\uc744 \ubc14\uafb8\uc5c8\ub2e4. \ub2e4\uc74c\uc5d0 \uc5b4\ub290 \ub3c4\uc2dc\uc758 \ud2b9\ubcc4\ud55c \uba39\uc744\uac70\ub9ac\ub098 \ub098\ubb34\ub97c \ub9cc\ub098\uba74 \uc6d0\ub798\ubd80\ud130 \uac70\uae30 \uc788\uc5c8\ub294\uc9c0 \uad81\uae08\ud574\ud574 \ubcf4\uc790. \uadf8 \uc9c8\ubb38\uc740 \ub73b\ubc16\uc5d0 \ubc14\ub2e4\uc640 \ub2e4\ub978 \uc9c0\uc5ed\uc758 \uc0ac\ub78c\ub4e4\ub85c \uc774\uc5b4\uc9c8 \uc218 \uc788\ub2e4. \ucf54\ub974\ub3c4\ubc14\uc758 \uac10\uade4 \uc774\uc57c\uae30\ub294 \ud55c \ub3c4\uc2dc \uc548\uc758 \ud48d\uacbd\uc5d0 \ub113\uc740 \uc138\uacc4\uac00 \ub4e4\uc5b4\uc624\ub294 \ubc29\uc2dd\uc774\ub2e4."}, {"id": "cusco-roads-and-empire", "title": "\ucfe0\uc2a4\ucf54 \u2014 \uc0b0\uae38\uc740 \uc5b4\ub5bb\uac8c \uc81c\uad6d\uc744 \ubb36\uc5c8\uc744\uae4c", "summary": "\uc548\ub370\uc2a4\uc758 \uc218\ub3c4 \ucfe0\uc2a4\ucf54\uc640 \uc778\uce74 \ub3c4\ub85c\ub9dd\uc744 \ud1b5\ud574 \uc774\ub3d9\u00b7\uc0dd\uc0b0\u00b7\ud1b5\uce58\uc758 \uc5f0\uacb0\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "cities", "category_title": "Cities", "subcategory": "Americas", "url": "stories/cusco-roads-and-empire/index.html", "image": "media/cusco-roads-and-empire.jpg", "alt": "\uc0b0 \uc0ac\uc774\ub85c \ub3cc\uacc4\ub2e8\uacfc \uae38\uc774 \uc774\uc5b4\uc9c0\ub294 \uc778\uce74 \ud2b8\ub808\uc77c\uc758 \uc2e4\uc81c \uc0ac\uc9c4.", "text": "\ucfe0\uc2a4\ucf54 \u2014 \uc0b0\uae38\uc740 \uc5b4\ub5bb\uac8c \uc81c\uad6d\uc744 \ubb36\uc5c8\uc744\uae4c \ub192\uc740 \uc218\ub3c4\uc5d0\uc11c \uc774\uc5b4\uc9c4 \uae38\uacfc \ub2e4\ub9ac\uc758 \uc774\uc57c\uae30 \uc548\ub370\uc2a4\uc758 \uc218\ub3c4 \ucfe0\uc2a4\ucf54\uc640 \uc778\uce74 \ub3c4\ub85c\ub9dd\uc744 \ud1b5\ud574 \uc774\ub3d9\u00b7\uc0dd\uc0b0\u00b7\ud1b5\uce58\uc758 \uc5f0\uacb0\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Americas \ub3c4\uc2dc \uc0b0\uae38\uc744 \uc624\ub974\ub2e4\uac00 \ub3cc\uacc4\ub2e8\uc774 \ub2a5\uc120 \ub108\uba38\ub85c \uc774\uc5b4\uc9c0\ub294 \ubaa8\uc2b5\uc744 \ub9cc\ub09c\ub2e4. \ud48d\uacbd\uc740 \uba4b\uc9c0\uc9c0\ub9cc \ubb34\uac70\uc6b4 \uc9d0\uc744 \ub4e4\uace0 \uac78\uc5b4\uc57c \ud55c\ub2e4\uba74 \uc0dd\uac01\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uba40\ub9ac \uc788\ub294 \uc0ac\ub78c\uacfc \ubb3c\uac74\uc744 \uc5f0\uacb0\ud558\ub294 \uc77c\uc740 \ub192\uc740 \uc0b0\uc5d0\uc11c\ub294 \ub354\uc6b1 \uad6c\uccb4\uc801\uc778 \uc218\uace0\uac00 \ub41c\ub2e4. \uc778\uce74\uc758 \uc218\ub3c4 \ucfe0\uc2a4\ucf54\ub294 \uc548\ub370\uc2a4\uc0b0\ub9e5\uc758 \ub192\uc740 \uacf3\uc5d0 \uc788\uc5c8\ub2e4. \uc774\uacf3\uc744 \uc911\uc2ec\uc73c\ub85c \ub113\uc740 \uc601\uc5ed\uc744 \ub2e4\uc2a4\ub9ac\ub824\uba74 \uc88b\uc740 \ub3cc \uac74\ubb3c\ub9cc\uc73c\ub85c\ub294 \ubd80\uc871\ud588\ub2e4. \uacc4\uace1\uacfc \uc0b0, \uac74\uc870\ud55c \uc9c0\uc5ed\uc744 \uc9c0\ub098 \uc0ac\ub78c\uacfc \ubb3c\uc790\ub97c \uc774\uc5b4 \uc904 \uae38\uc774 \ud544\uc694\ud588\ub2e4. \ub3c4\uc2dc\ub97c \uc774\ud574\ud558\ub294 \uc2dc\uc120\uc744 \ub3c4\ub85c \ucabd\uc73c\ub85c \uc62e\uaca8 \ubcf4\uc790. \ucfe0\uc2a4\ucf54\uc758 \uc55e\uc120 \uacf5\ub3d9\uccb4\ub294 \uac10\uc790\uc640 \uc625\uc218\uc218\ub97c \uae30\ub974\uace0 \ub77c\ub9c8 \uac19\uc740 \ub3d9\ubb3c\uc744 \uae30\ub974\ub294 \ub18d\uacbd \uc0dd\ud65c\uacfc \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub2e4. \uad50\uc7ac\ub294 1000\ub144 \ubb34\ub835 \uc774 \uc9c0\uc5ed\uc5d0 \ub18d\uacbd \ub9c8\uc744 \uc0ac\ub78c\ub4e4\uc774 \uc790\ub9ac\ud558\uace0 \uc788\uc5c8\uc74c\uc744 \uc124\uba85\ud55c\ub2e4. \ud6c4\ub300\uc758 \uac70\ub300\ud55c \uc81c\uad6d\uc774 \ucc98\uc74c\ubd80\ud130 \uc644\uc131\ub418\uc5b4 \uc788\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc2dc\uac04\uc774 \ud750\ub974\uba70 \ucfe0\uc2a4\ucf54\uc758 \uc138\ub825\uc740 \uc8fc\ubcc0\uacfc \uacbd\uc7c1\ud558\uace0 \uad00\uacc4\ub97c \ub113\ud614\ub2e4. \ub3c4\uc2dc\uac00 \uc131\uc7a5\ud55c \ub4a4\uc5d0\ub294 \uadf8 \uc2dc\uc791\uc744 \uc124\uba85\ud558\ub294 \uc804\uc2b9\ub3c4 \uc911\uc694\ud574\uc84c\ub2e4. \ub3cc\uc774 \uc804\uc0ac\ub85c \ubcc0\ud588\ub2e4\ub294 \uc774\uc57c\uae30\ub098 \ud669\uae08 \uc9c0\ud321\uc774\uc758 \uc804\uc124\uc740 \ub2f9\uc2dc \uc0ac\ub78c\ub4e4\uc774 \uc790\uc2e0\ub4e4\uc758 \uae30\uc6d0\uc744 \uc5b4\ub5bb\uac8c \uc774\ud574\ud588\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\uc9c0\ub9cc, \uc2e4\uc81c \uc0ac\uac74\uc758 \uae30\ub85d\uacfc \uadf8\ub300\ub85c \uac19\uc9c0\ub294 \uc54a\ub2e4. \ucfe0\uc2a4\ucf54\ub294 \ud574\ubc1c 3\ucc9c \ubbf8\ud130\uac00 \ub118\ub294 \uc548\ub370\uc2a4 \uace0\uc9c0\ub300\uc5d0 \uc790\ub9ac\ud55c\ub2e4. \uc778\uce74\uc758 \uc11d\uacf5\ub4e4\uc740 \ub3cc\uc744 \uc815\uad50\ud558\uac8c \ub2e4\ub8e8\uc5b4 \uac74\ubb3c\uc744 \ub9cc\ub4e4\uc5c8\ub2e4. \uc624\ub298\ub0a0 \uadfc\ucc98\uc758 \uc0ad\uc0ac\uc774\uc640\ub9cc\uc5d0 \ub0a8\uc740 \uc11d\ubcbd\ub3c4 \uc774\ub7f0 \uae30\uc220\uc744 \uc54c\ub824 \uc8fc\ub294 \uc790\ub8cc\ub2e4. \ud558\uc9c0\ub9cc \uc218\ub3c4\ub294 \uc8fc\ubcc0\uc5d0\uc11c \uba39\uc744\uac70\ub9ac\uc640 \uc790\uc6d0\uc774 \ub4e4\uc5b4\uc624\uc9c0 \uc54a\uc73c\uba74 \uc720\uc9c0\ub418\uae30 \uc5b4\ub835\ub2e4. \uc911\uc694\ud55c \uc0ac\ub78c\uc774 \ubaa8\uc774\ub294 \uc911\uc2ec\uc774 \uc788\ub2e4\ub294 \uac83\uc740 \uadf8\uacf3\uacfc \ub2e4\ub978 \uc9c0\uc5ed \uc0ac\uc774\uc5d0 \uc9c0\uc18d\uc801\uc778 \uc774\ub3d9\uc774 \ud544\uc694\ud558\ub2e4\ub294 \ub73b\uc774\uae30\ub3c4 \ud558\ub2e4. \uac74\ubb3c\uc758 \ud06c\uae30\uc640 \uae38\uc758 \uc874\uc7ac\ub97c \ud568\uaed8 \uc0dd\uac01\ud574\uc57c \ub3c4\uc2dc\uc758 \uc0dd\ud65c\uc774 \ubcf4\uc778\ub2e4. \uc778\uce74\uac00 \uc9c0\ubc30\ud55c \uc9c0\uc5ed\uc5d0\ub294 \ub192\uc740 \uc0b0\uacfc \uae4a\uc740 \uacc4\uace1, \uc0ac\ub9c9\uacfc \ud574\uc548\uc758 \uc881\uc740 \ud3c9\uc9c0\uac00 \uc788\uc5c8\ub2e4. \uace7\uc740 \uae38 \ud558\ub098\ub97c \ubaa8\ub4e0 \uacf3\uc5d0 \ub611\uac19\uc774 \ub193\uc744 \uc218 \uc788\ub294 \ud658\uacbd\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc774\ub3d9\uc740 \uc9c0\ud615\uc5d0 \ub9de\ucd94\uc5b4 \ub2e4\ub978 \ubc29\ubc95\uc744 \ud544\uc694\ub85c \ud588\ub2e4. \uad50\uc7ac\ub294 \ud3c9\uc9c0\uc758 \uc9c1\uc120 \uad6c\uac04\uacfc \uc0b0\uae38\uc758 \uad7d\uc774, \ub3cc\uacc4\ub2e8\uacfc \uc5ec\ub7ec \uc7ac\ub8cc\uc758 \ub2e4\ub9ac\ub97c \ud568\uaed8 \uc124\uba85\ud55c\ub2e4. \ub3c4\ub85c\ub9dd\uc774 \uc788\ub2e4\ub294 \ud55c\ub9c8\ub514 \ub4a4\uc5d0\ub294 \uc11c\ub85c \ub2e4\ub978 \ud615\ud0dc\uc758 \uae38\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \uae38\uc774 \uc88b\ub2e4\ub294 \uac83\uc740 \uc5b8\uc81c\ub098 \ub113\uace0 \ud3c9\ud3c9\ud558\ub2e4\ub294 \ub73b\ub9cc\uc740 \uc544\ub2c8\uc5c8\ub358 \uc148\uc774\ub2e4. \ub3c4\ub85c\ub9dd\uc758 \uc77c\ubd80\ub294 \uc778\uce74 \uc774\uc804\ubd80\ud130 \uc874\uc7ac\ud588\ub2e4. \uc778\uce74\ub294 \uc774\ub97c \ub354 \ud06c\uac8c \uc5f0\uacb0\ud558\uace0 \ud655\ub300\ud558\uba70 \uac1c\uc120\ud588\ub2e4. \ud1b5\uce58\uc790\uac00 \ub113\uc740 \ub545\uc744 \ub2e4\uc2a4\ub9ac\ub824\ub294 \ubaa9\ud45c\uc640 \uc9c0\uc5ed\uc5d0 \ucd95\uc801\ub41c \uc774\ub3d9\uc758 \uae30\uc220\uc774 \ub9cc\ub09c \uac83\uc774\ub2e4. \uc774 \uc810\uc744 \uc54c\uba74 \uac70\ub300\ud55c \uae38\uc758 \ub9dd\uc744 \ud55c \uc0ac\ub78c\uc774 \ucc98\uc74c\ubd80\ud130 \ub05d\uae4c\uc9c0 \uc124\uacc4\ud574 \uc138\uc6b4 \uc791\ud488\ucc98\ub7fc \ubcf4\uae30 \uc5b4\ub835\ub2e4. \uc5ec\ub7ec \uc2dc\ub300\uc640 \uc9c0\uc5ed\uc758 \uacbd\ud5d8\uc774 \uc774\uc5b4\uc84c\ub2e4. \uc81c\uad6d\uc758 \uc774\ub984\uc73c\ub85c \uae30\uc5b5\ub418\ub294 \uae30\ubc18\uc2dc\uc124\uc5d0\ub3c4 \uadf8\ubcf4\ub2e4 \uc55e\uc120 \uc0ac\ub78c\ub4e4\uc758 \uae38\uc774 \ub4e4\uc5b4 \uc788\uc744 \uc218 \uc788\ub2e4. \uc778\uce74\uc758 \ub3c4\ub85c\ub294 \uad70\ub300\uac00 \uc774\ub3d9\ud558\ub294 \ub370 \uc4f0\uc600\uace0, \uc9c0\ubc29\uc5d0\uc11c \uc0dd\uc0b0\ud55c \ubb3c\uac74\uc744 \uc800\uc7a5\uace0\ub85c \uc62e\uae30\ub294 \ub370\ub3c4 \uc911\uc694\ud588\ub2e4. \uae38\uc740 \uc5ec\ud589\uc758 \uc990\uac70\uc6c0\ub9cc\uc744 \uc704\ud574 \uc874\uc7ac\ud55c \uc2dc\uc124\uc774 \uc544\ub2c8\uc5c8\ub2e4. \ud1b5\uce58\uc640 \uc790\uc6d0\uc758 \ubc30\ubd84\uc744 \uac00\ub2a5\ud558\uac8c \ud558\ub294 \uc7a5\uce58\uc774\uae30\ub3c4 \ud588\ub2e4. \uc5b4\ub290 \uc9c0\uc5ed\uc5d0\uc11c \ubb3c\uac74\uc744 \uac70\ub450\uace0 \uc5b4\ub514\uc5d0 \ubaa8\uc744\uc9c0 \uc815\ud558\ub294 \ud798\uc740 \uc8fc\ubbfc\uc758 \uc0dd\ud65c\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uae38\uc774 \uc798 \uc774\uc5b4\uc84c\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uadf8 \uae38\uc744 \uc774\uc6a9\ud55c \uc81c\ub3c4\uac00 \ubaa8\ub450\uc5d0\uac8c \uac19\uc740 \uc774\uc775\uc744 \uc8fc\uc5c8\ub2e4\ub294 \ud3c9\uac00\ub294 \uad6c\ubcc4\ud574\uc57c \ud55c\ub2e4. \ud3b8\ub9ac\ud55c \uc774\ub3d9\uc758 \uc5ed\uc0ac\uc5d0\ub294 \ub3d9\uc6d0\uacfc \uc758\ubb34\uc758 \ubb38\uc81c\ub3c4 \ud568\uaed8 \uc788\ub2e4. \uc778\uce74\ub294 \uc815\ubcf5\ud55c \uc9c0\uc5ed\uc5d0 \uacf5\ub0a9\uacfc \ub178\ub3d9 \uc758\ubb34\ub97c \uc694\uad6c\ud588\ub2e4. \ub113\uc740 \uc601\uc5ed\uc758 \uc0dd\uc0b0\uacfc \ub178\ub3d9\uc774 \uc81c\uad6d\uc758 \ud65c\ub3d9\uc744 \ub4b7\ubc1b\uce68\ud55c \uac83\uc774\ub2e4. \ub3cc\ub85c \ub9cc\ub4e0 \uc218\ub3c4\uc758 \ubaa8\uc2b5\ub9cc \ubcf4\uba74 \uc774 \uad00\uacc4\uac00 \ud654\uba74 \ubc16\uc5d0 \ub0a8\uae30 \uc27d\ub2e4. \uadf8\ub798\uc11c \ucfe0\uc2a4\ucf54\ub97c \uac10\uc0c1\ud560 \ub54c\ub294 \uc911\uc694\ud55c \uac74\ubb3c\uc774 \uba87 \uac1c \uc788\uc5c8\ub294\uc9c0\ubfd0 \uc544\ub2c8\ub77c \uadf8\uac83\uc744 \uc720\uc9c0\ud55c \uba39\uc744\uac70\ub9ac\uc640 \uc77c\uc190\uc774 \uc5b4\ub514\uc11c \uc654\ub294\uc9c0\ub3c4 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ud55c \ub3c4\uc2dc\uc758 \uc704\uc0c1\uc740 \ub3c4\uc2dc \uc548\ucabd\uc758 \uc131\ucde8\uc640 \ubc14\uae65 \uc9c0\uc5ed\uc758 \ubd80\ub2f4\uc774 \uc5f0\uacb0\ub41c \uacb0\uacfc\uc77c \uc218 \uc788\ub2e4. \uc218\ub3c4\uc5d0\uc11c \uba40\uc5b4\uc9c4 \uae38\ub3c4 \ub3c4\uc2dc\uc0ac\uc758 \uc77c\ubd80\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 \uc778\uce74 \ud2b8\ub808\uc77c\uc758 \uc2e4\uc81c \ub3cc\uacc4\ub2e8\uacfc \uc0b0 \ud48d\uacbd\uc774\ub2e4. \ucfe0\uc2a4\ucf54 \uc2dc\uac00\uc9c0 \uc790\uccb4\ub97c \ucd2c\uc601\ud55c \uc0ac\uc9c4\uc774\ub098 \uc804\uccb4 \ub3c4\ub85c\ub9dd\uc758 \ubaa8\uc2b5\uc740 \uc544\ub2c8\ub2e4. \uae38\uc758 \ud55c \uad6c\uac04\uc5d0\uc11c \uc0b0\uc545 \uc9c0\ud615\uacfc \uc0ac\ub78c\uc758 \uc774\ub3d9 \ud1b5\ub85c\uac00 \ub9cc\ub098\ub294 \ubc29\uc2dd\uc744 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \uacc4\ub2e8\uc744 \ub9cc\ub4e0 \ub3cc\uacfc \uc8fc\ubcc0\uc758 \uacbd\uc0ac, \uae38\uc774 \uc0ac\ub77c\uc9c0\ub294 \ubc29\ud5a5\uc744 \ucc28\ub840\ub85c \ubcf4\uba74 \uc774\ub3d9\uc758 \uaddc\ubaa8\ub97c \ubab8\uc73c\ub85c \uc870\uae08 \uc0c1\uc0c1\ud558\uac8c \ub41c\ub2e4. \ub2e4\ub9cc \uc0ac\uc9c4\ub9cc\uc73c\ub85c \ub204\uac00 \uc5b4\ub290 \ub0a0 \uc774 \uad6c\uac04\uc744 \uc9c0\ub098\uac14\ub294\uc9c0 \ud655\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc2e4\uc81c \uad00\ucc30\uacfc \uc5ed\uc0ac\uc801 \uc124\uba85\uc758 \ubc94\uc704\ub97c \ub098\ub204\uc5b4 \ubcf4\uc544\ub3c4 \uae38\uc758 \uc778\uc0c1\uc740 \ucda9\ubd84\ud788 \uac15\ud558\ub2e4. \ucfe0\uc2a4\ucf54\ub97c \uae30\uc5b5\ud560 \ub54c \ub192\uc740 \ub3cc \uac74\ubb3c \uacc1\uc5d0 \uba3c \uacf3\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \uae38\ub3c4 \ub0a8\uaca8 \ubcf4\uc790. \uc0b0\uacfc \uacc4\uace1\uc744 \uac74\ub108\uc624\ub294 \uc2dd\ub7c9\uacfc \ubb3c\uc790, \uc774\ub3d9\ud558\ub294 \uc0ac\ub78c\ub4e4\uc758 \uc2dc\uac04\uc774 \uc218\ub3c4\ub97c \ub9cc\ub4e4\uc5c8\ub2e4. \ub3c4\uc2dc\uc758 \uc5ed\uc0ac\uc640 \ub3c4\ub85c\uc758 \uc5ed\uc0ac\ub294 \ub530\ub85c \ub5a8\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \uc9c0\uae08 \uc6b0\ub9ac\uac00 \uc0ac\ub294 \ub3c4\uc2dc\ub3c4 \ub208\uc5d0 \ubcf4\uc774\ub294 \uac74\ubb3c\ub9cc\uc73c\ub85c \uc644\uc131\ub418\uc9c0 \uc54a\ub294\ub2e4. \ub2e4\ub978 \uc9c0\uc5ed\uacfc \uc5f0\uacb0\ub41c \uc774\ub3d9\uc774 \ub9e4\uc77c\uc758 \uc0dd\ud65c\uc744 \uac00\ub2a5\ud558\uac8c \ud55c\ub2e4. \uc778\uce74\uc758 \uc0b0\uae38\uc740 \uc624\ub798\ub41c \uc81c\uad6d\uc758 \uae30\uc220\uc744 \ubcf4\uc5ec \uc8fc\uba74\uc11c, \ub3c4\uc2dc\ub97c \uc5b4\ub514\uae4c\uc9c0 \ubcf4\uc544\uc57c \ud560\uc9c0 \ubb3b\ub294 \uc9c8\ubb38\ub3c4 \ub0a8\uae34\ub2e4."}, {"id": "great-zimbabwe-stone-and-trade", "title": "\uadf8\ub808\uc774\ud2b8 \uc9d0\ubc14\ube0c\uc6e8 \u2014 \ub3cc\uc744 \ubd99\uc774\uc9c0 \uc54a\uace0 \ubcbd\uc744 \uc138\uc6b0\ub2e4", "summary": "\ubaa8\ub974\ud0c0\ub974 \uc5c6\uc774 \uc313\uc740 \ubcbd\uacfc \uad50\uc5ed\ud488\uc744 \ud1b5\ud574 \ub0a8\ubd80 \uc544\ud504\ub9ac\uce74 \ub3c4\uc2dc\uc758 \uae30\uc220\uacfc \uc5f0\uacb0\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "cities", "category_title": "Cities", "subcategory": "Africa", "url": "stories/great-zimbabwe-stone-and-trade/index.html", "image": "media/great-zimbabwe-stone-and-trade.jpg", "alt": "\uadf8\ub808\uc774\ud2b8 \uc9d0\ubc14\ube0c\uc6e8 \uadf8\ub808\uc774\ud2b8 \uc778\ud074\ub85c\uc800 \uc548\uc5d0 \ub0a8\uc740 \ub3cc\ubcbd\uacfc \uc6d0\ubfd4\ud615 \uad6c\uc870\ubb3c, \ub098\ubb34\uc758 \uc2e4\uc81c \uc0ac\uc9c4.", "text": "\uadf8\ub808\uc774\ud2b8 \uc9d0\ubc14\ube0c\uc6e8 \u2014 \ub3cc\uc744 \ubd99\uc774\uc9c0 \uc54a\uace0 \ubcbd\uc744 \uc138\uc6b0\ub2e4 \ub0b4\ub959\uc758 \ub3cc\ub2f4\uc774 \ubc14\ub2e4 \uac74\ub108 \uc138\uacc4\uc640 \uc5f0\uacb0\ub418\ub294 \uc774\uc57c\uae30 \ubaa8\ub974\ud0c0\ub974 \uc5c6\uc774 \uc313\uc740 \ubcbd\uacfc \uad50\uc5ed\ud488\uc744 \ud1b5\ud574 \ub0a8\ubd80 \uc544\ud504\ub9ac\uce74 \ub3c4\uc2dc\uc758 \uae30\uc220\uacfc \uc5f0\uacb0\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Africa \ub3c4\uc2dc \ub3cc\ub2f4 \uac00\uae4c\uc774\uc5d0\uc11c \ub3cc\uacfc \ub3cc \uc0ac\uc774\ub97c \ubcf8\ub2e4. \uc811\ucc29 \uc7ac\ub8cc\ub97c \ubc1c\ub77c \ubd99\uc778 \ud754\uc801\uc774 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub370 \ubcbd\uc740 \ub192\uace0 \uae38\uac8c \uc774\uc5b4\uc9c4\ub2e4. \ub0a8\ubd80 \uc544\ud504\ub9ac\uce74\uc758 \uadf8\ub808\uc774\ud2b8 \uc9d0\ubc14\ube0c\uc6e8\uc5d0\ub294 \uc774\ub7f0 \ubc29\uc2dd\uc73c\ub85c \ub9cc\ub4e0 \ud070 \uc11d\uc870 \uc720\uc801\uc774 \ub0a8\uc544 \uc788\ub2e4. \uc0ac\uc9c4\uc758 \ub2f4\uc744 \ubcf4\uace0 \uac74\ucd95 \uae30\uc220\uc774 \uc2e0\uae30\ud558\ub2e4\uace0 \ub290\uaf08\ub2e4\uba74, \uac70\uae30\uc11c \ud55c \uac00\uc9c0\ub97c \ub354 \ubb3c\uc5b4\ubcfc \uc218 \uc788\ub2e4. \uc774 \uc548\ucabd\uc5d0\uc11c \uc0b4\ub358 \uc0ac\ub78c\ub4e4\uc740 \ubb34\uc5c7\uc744 \ub9cc\ub4e4\uace0 \uc5b4\ub514\uc640 \uac70\ub798\ud588\uc744\uae4c. \ub0b4\ub959\uc5d0 \uc790\ub9ac\ud55c \ub3c4\uc2dc\uc758 \uc774\uc57c\uae30\ub294 \ub73b\ubc16\uc5d0\ub3c4 \ub3d9\uc544\ud504\ub9ac\uce74 \ud574\uc548\uacfc \uc778\ub3c4\uc591 \ub108\uba38\uae4c\uc9c0 \uc774\uc5b4\uc9c4\ub2e4. \uc9d0\ubc14\ube0c\uc6e8\ub77c\ub294 \uc774\ub984\uc740 \uc1fc\ub098\uc5b4\uc758 \ub3cc\uc9d1\ub4e4\uc744 \ub73b\ud558\ub294 \ud45c\ud604\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uad50\uc7ac\ub3c4 \ub3cc \uac74\ubb3c\uc774\ub77c\ub294 \uc758\ubbf8\ub97c \uc124\uba85\ud55c\ub2e4. \uc624\ub298\ub0a0 \uad6d\uac00\uc758 \uc774\ub984\uc73c\ub85c \uc775\uc219\ud558\uc9c0\ub9cc, \uadf8\ub808\uc774\ud2b8 \uc9d0\ubc14\ube0c\uc6e8\ub294 \uc1fc\ub098\uc778\ub4e4\uc774 \uc131\uc7a5\uc2dc\ud0a8 \uc911\uc138\uc758 \uc911\uc694\ud55c \uc911\uc2ec\uc9c0\ub2e4. \ucc98\uc74c\ubd80\ud130 \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \uac70\ub300\ud55c \ub3cc\uc9d1 \uc548\uc5d0 \uc0b0 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774 \uc9c0\uc5ed\uc758 \uacf5\ub3d9\uccb4\ub294 \uac00\ucd95\uc744 \uae30\ub974\uace0 \ub18d\uc0ac\ub97c \uc9c0\uc5c8\uc73c\uba70 \ud759\uacfc \ub098\ubb34 \uac19\uc740 \uc7ac\ub8cc\ub85c\ub3c4 \uc9d1\uc744 \ub9cc\ub4e4\uc5c8\ub2e4. \uc624\ub798 \ub0a8\uc740 \ub3cc \uac74\ubb3c\uc774 \ub208\uae38\uc744 \ub048\ub2e4\uace0 \ub3c4\uc2dc\uc758 \uc77c\uc0c1 \uc804\uccb4\ub97c \ub3cc \ud558\ub098\uc758 \uc774\ubbf8\uc9c0\ub85c \ubc14\uafb8\uc5b4 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub4dc\ub77c\uc774\uc2a4\ud1a4\uc740 \ubaa8\ub974\ud0c0\ub974 \uac19\uc740 \uc811\ucc29 \uc7ac\ub8cc\ub97c \uc0ac\uc6a9\ud558\uc9c0 \uc54a\uace0 \ub3cc\uc744 \ub9de\ucd94\uc5b4 \uc313\ub294 \ubc29\uc2dd\uc774\ub2e4. \ud070 \ubcbd\uc744 \ub9cc\ub4e4\ub824\uba74 \ub3cc\uc758 \uc704\uce58\uc640 \ub9de\ubb3c\ub9ac\ub294 \uad00\uacc4\ub97c \uace0\ub824\ud574\uc57c \ud55c\ub2e4. \ub2e8\ub2e8\ud55c \ub3cc\uc774 \ucda9\ubd84\ud788 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uae34 \uad6c\uc870\ubb3c\uc774 \uc800\uc808\ub85c \uc11c\uc9c0\ub294 \uc54a\ub294\ub2e4. \uad50\uc7ac\ub294 11\uc138\uae30 \ubb34\ub835\ubd80\ud130 \uc774 \uc9c0\uc5ed\uc5d0\uc11c \uc774\ub7f0 \uc11d\uc870 \uac74\ubb3c\uc774 \ub098\ud0c0\ub0ac\uace0 \uc8fc\uc694 \uad6c\uc870\ubb3c\uc774 \uc624\ub79c \uc2dc\uac04\uc5d0 \uac78\uccd0 \uac74\uc124\ub418\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc790\ub8cc\uc5d0 \ub530\ub77c \uc138\ubd80\uc758 \uc5f0\ub300\uc640 \ud574\uc11d\uc740 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc9c0\ub9cc, \ud604\uc9c0 \uacf5\ub3d9\uccb4\uac00 \ucd95\uc801\ud55c \uac74\ucd95 \uae30\uc220\uc774 \uc911\uc694\ud55c \ubc30\uacbd\uc774\ub77c\ub294 \uc810\uc744 \ub193\uccd0\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc720\uc801\uc740 \ud558\ub098\uc758 \uc131\ucc44\ub9cc\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \uc5b8\ub355 \uc704\uc758 \ubcf5\ud569 \uacf5\uac04\uacfc \uac70\ub300\ud55c \ub2f4\uc744 \ub450\ub978 \uadf8\ub808\uc774\ud2b8 \uc778\ud074\ub85c\uc800, \uace8\uc9dc\uae30\uc5d0 \ub0a8\uc740 \uc5ec\ub7ec \uad6c\uc870\ubb3c\uc774 \ud568\uaed8 \uc788\ub2e4. \ud070 \ub2f4\uacfc \uc9d1\ub4e4\uc758 \ubc30\uce58\ub294 \uacf5\uac04 \uc0ac\uc774\uc758 \ucc28\uc774\ub97c \ub9cc\ub4e0\ub2e4. \ub2e4\ub9cc \uc774\uacf3\uc774 \uc815\ud655\ud788 \uc5b4\ub290 \uc758\ub840\ub97c \uc704\ud55c \uc790\ub9ac\uc600\ub294\uc9c0, \ub204\uac00 \uc5b4\ub5a4 \uac74\ubb3c\uc744 \uc0ac\uc6a9\ud588\ub294\uc9c0\uc5d0\ub294 \ub17c\uc7c1\uc774 \ub0a8\uc544 \uc788\ub2e4. \uc655\uad81\uc774\ub098 \uc885\uad50 \uacf5\uac04\uc774\ub77c\ub294 \ud574\uc11d\uc744 \ud55c \uac00\uc9c0 \ud655\uc815\ub41c \ud3c9\uba74\ub3c4\ucc98\ub7fc \uc18c\uac1c\ud558\uba74 \uadfc\uac70\ubcf4\ub2e4 \uc774\uc57c\uae30\uac00 \uc55e\uc120\ub2e4. \ud070 \uaddc\ubaa8\uac00 \uc870\uc9c1\uc801\uc778 \uc790\uc6d0\uacfc \ub178\ub3d9\uc744 \ud544\uc694\ub85c \ud588\ub2e4\ub294 \uc810\uacfc \uac01 \uc7a5\uc18c\uc758 \uad6c\uccb4\uc801 \uc6a9\ub3c4\ub294 \ub098\ub204\uc5b4 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uc774 \uc9c0\uc5ed\uc758 \uc0dd\ud65c\uc5d0\ub294 \ubaa9\ucd95\uacfc \ub18d\uacbd, \ucca0\uc744 \ub2e4\ub8e8\ub294 \uae30\uc220\uc774 \uc911\uc694\ud588\ub2e4. \uac00\ucd95\uacfc \ub18d\uc0b0\ubb3c\uc740 \uc0ac\ub78c\ub4e4\uc758 \uc0dd\uacc4\ub97c \ub4b7\ubc1b\uce68\ud588\uace0, \ub3c4\uad6c\uc640 \uc7a5\uc2dd\ud488\uc744 \ub9cc\ub4dc\ub294 \ud65c\ub3d9\ub3c4 \uc774\ub8e8\uc5b4\uc84c\ub2e4. \uc720\uba85\ud55c \uac74\ubb3c\uc740 \uc774\ub7f0 \uc0dd\uc0b0\uc774 \uacc4\uc18d\ub420 \uc218 \uc788\ub294 \ud658\uacbd\uacfc \ub5a8\uc5b4\uc838 \uc788\uc9c0 \uc54a\uc558\ub2e4. \uc74c\uc2dd\uacfc \uc77c\uc0c1\uc6a9\ud488\uc744 \uc0dd\uc0b0\ud558\ub294 \uc0ac\ub78c\uc774 \uc5c6\uc73c\uba74 \uad8c\ub825\uc758 \uc911\uc2ec\ub3c4 \uc720\uc9c0\ub420 \uc218 \uc5c6\ub2e4. \uc720\uc801\uc744 \uac10\uc0c1\ud560 \ub54c\ub294 \ud070 \ub2f4\uc744 \uc138\uc6b4 \uc0ac\ub78c\ubfd0 \uc544\ub2c8\ub77c \uadf8 \uacfc\uc815\uc5d0\uc11c \uba39\uc744\uac70\ub9ac\ub97c \ub9c8\ub828\ud558\uace0 \uc7ac\ub8cc\ub97c \ub2e4\ub8e8\uc5c8\ub358 \uc0ac\ub78c\ub3c4 \ud568\uaed8 \ub5a0\uc62c\ub824 \ubcf4\uc790. \ub3c4\uc2dc\uc758 \uae30\uc220\uc740 \ub208\uc5d0 \ud06c\uac8c \ub0a8\uc740 \uac74\ucd95\ub9cc\uc744 \ub73b\ud558\uc9c0 \uc54a\ub294\ub2e4. \uadf8\ub808\uc774\ud2b8 \uc9d0\ubc14\ube0c\uc6e8\ub294 \uae08\uacfc \uad6c\ub9ac, \uc0c1\uc544 \ub4f1\uc744 \uad50\uc5ed\ud558\uba70 \uc131\uc7a5\ud588\ub2e4. \ub3d9\uc544\ud504\ub9ac\uce74\uc758 \uc2a4\uc640\ud790\ub9ac \ud574\uc548 \ub3c4\uc2dc\ub4e4\uacfc \uc5f0\uacb0\ub418\uba74\uc11c \ub0b4\ub959\uc758 \ubb3c\ud488\uc740 \uc18c\ud314\ub77c\uc640 \ud0ac\uc640 \uac19\uc740 \uad50\uc5ed \uac70\uc810\uc744 \uac70\uccd0 \ub354 \ub113\uc740 \uc138\uacc4\ub85c \ub098\uac08 \uc218 \uc788\uc5c8\ub2e4. \uc5ec\uae30\uc11c \uc9c0\ub3c4\ub97c \ub3c4\uc2dc \uc8fc\ubcc0\ub9cc \uc798\ub77c \ubcf4\uba74 \uc911\uc694\ud55c \uae38\uc774 \uc0ac\ub77c\uc9c4\ub2e4. \ubc14\ub2e4\uc640 \ub5a8\uc5b4\uc838 \uc788\ub2e4\uace0 \ud574\uc591 \uad50\uc5ed\uacfc \ubb34\uad00\ud588\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub0b4\ub959\uacfc \ud574\uc548 \uc0ac\uc774\ub97c \uc624\uac00\ub294 \uc5ec\ub7ec \uc0ac\ub78c\uc758 \uad50\ud658\uc774 \uc9c0\uc5ed\uc744 \uc5f0\uacb0\ud588\ub2e4. \ud55c \ub3c4\uc2dc\uc758 \ubc88\uc601\uc774 \ubc18\ub4dc\uc2dc \uadf8 \ub3c4\uc2dc \uc8fc\ubbfc\uc758 \uc9c1\uc811\uc801\uc778 \uc7a5\uac70\ub9ac \ud56d\ud574\ub85c\ub9cc \ub9cc\ub4e4\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\ub3c4 \ubcf4\uc778\ub2e4. \uace0\uace0\ud559 \uc790\ub8cc\uc5d0\ub294 \uc911\uad6d \ub3c4\uc790\uae30\uc640 \ud398\ub974\uc2dc\uc544 \uc9c0\uc5ed\uc758 \ub3c4\uae30 \ub4f1 \uc678\ubd80\uc640\uc758 \uc5f0\uacb0\uc744 \ubcf4\uc5ec \uc8fc\ub294 \ubb3c\uac74\uc774 \uc788\ub2e4. \uc774\ub7f0 \ubc1c\uacac\uc740 \uc11d\uc870 \uc720\uc801\uc774 \uc678\ubd80 \uc138\uacc4\uc640 \ub2e8\uc808\ub41c \uacf5\uac04\uc774\uc5c8\ub2e4\ub294 \uc778\uc0c1\uc744 \ubc14\uafb8\uc5b4 \uc900\ub2e4. \uc791\uc740 \ud30c\ud3b8\uc774 \ud070 \uae38\uc758 \uc874\uc7ac\ub97c \uc54c\ub824 \uc8fc\ub294 \uc148\uc774\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubb3c\uac74 \ud558\ub098\uac00 \ubc1c\uacac\ub418\uc5c8\ub2e4\uace0 \ud2b9\uc815 \uc0c1\uc778\uc774 \uc911\uad6d\uc5d0\uc11c \uc774 \ub3c4\uc2dc\uae4c\uc9c0 \uc9c1\uc811 \uc5ec\ud589\ud588\ub2e4\uace0 \ub2e8\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc5ec\ub7ec \ubc88\uc758 \uad50\ud658\uc744 \uac70\uccd0 \uc62e\uaca8 \uc654\uc744 \uc218\ub3c4 \uc788\ub2e4. \ubb3c\uac74\uc758 \uc774\ub3d9\uacfc \uc0ac\ub78c \ud55c \uba85\uc758 \uc5ec\ud589 \uacbd\ub85c\ub294 \uac19\uc740 \uc99d\uac70\uac00 \uc544\ub2c8\ub2e4. \uc774 \uad6c\ubd84\uc744 \ud558\uba74 \uad50\uc5ed\ub9dd\uc758 \ub113\uc774\ub97c \uacfc\uc7a5 \uc5c6\uc774 \ub354 \ud765\ubbf8\ub86d\uac8c \uc77d\uc744 \uc218 \uc788\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c\ub294 \ub3cc\ub2f4\uc774 \uac15\ud558\uac8c \ubcf4\uc774\uc9c0\ub9cc, \ub2f9\uc2dc \uc0dd\ud65c\uc5d0 \uc4f0\uc778 \uc7ac\ub8cc\uac00 \ubaa8\ub450 \uac19\uc740 \uc0c1\ud0dc\ub85c \ubcf4\uc874\ub418\uc9c0\ub294 \uc54a\uc558\ub2e4. \ud759\uacfc \ub098\ubb34\ub85c \ub9cc\ub4e0 \uac70\ucc98\uc758 \ud754\uc801\ub3c4 \ud568\uaed8 \uc5f0\uad6c\ud574\uc57c \ud55c\ub2e4. \uc9c0\uae08 \ub208\uc5d0 \uc798 \ubcf4\uc774\ub294 \uac83\uacfc \uacfc\uac70\uc5d0 \uc911\uc694\ud588\ub358 \uac83\uc758 \ubaa9\ub85d\uc740 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uadf8\ub798\uc11c \uc720\uc801 \uc0ac\uc9c4\uc740 \ub3c4\uc2dc\uc758 \uc804\uccb4 \ubaa8\uc2b5\uc744 \uc644\uc131\ud574 \uc8fc\ub294 \uc815\ub2f5\uc9c0\uac00 \uc544\ub2c8\ub2e4. \ubb34\uc5c7\uc774 \uc624\ub798 \ubc84\ud17c\ub294\uc9c0\ub97c \ubcf4\uc5ec \uc8fc\ub294 \ucc3d\uc774\uae30\ub3c4 \ud558\ub2e4. \ub0a8\uc740 \ub2f4\uc758 \uae38\uc774\uc640 \ud615\ud0dc\ub97c \uc0b4\ud53c\ub294 \uac10\uc0c1\uc5d0 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc9d1\uacfc \uc791\uc5c5, \uc0dd\ud65c\uc758 \uad00\uacc4\ub97c \ub354\ud558\uba74 \uacfc\uac70\uc758 \uacf5\uac04\uc774 \uc870\uae08 \ub354 \ub113\uc5b4\uc9c4\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 \uadf8\ub808\uc774\ud2b8 \uc778\ud074\ub85c\uc800 \uc548\ucabd\uc758 \uc2e4\uc81c \uc720\uc801 \uc0ac\uc9c4\uc774\ub2e4. \uad6c\uccb4\uc801\uc778 \ub3cc \ubc30\uce58\uc640 \ubcbd\uc758 \ub192\uc774 \ucc28\uc774\ub97c \ubcfc \uc218 \uc788\uc9c0\ub9cc, \uadf8\uac83\ub9cc\uc73c\ub85c \uc61b \uc758\ub840\ub098 \uac70\uc8fc\uc790\uc758 \uc77c\uacfc\uae4c\uc9c0 \ubcf5\uc6d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ud655\uc778\ud55c \ubaa8\uc2b5\uc5d0\uc11c \uc774\uc57c\uae30\ub97c \uc2dc\uc791\ud558\uba74 \ub41c\ub2e4. \uadf8\ub808\uc774\ud2b8 \uc9d0\ubc14\ube0c\uc6e8\uc758 \ub3cc\ub4e4\uc740 \ubd99\uc774\ub294 \uc7ac\ub8cc \uc5c6\uc774 \ub9de\ubb3c\ub824 \uc11c \uc788\ub2e4. \ub3c4\uc2dc\uc758 \uc0b6\uc740 \ubc18\ub300\ub85c \uc218\ub9ce\uc740 \uc5f0\uacb0\uc744 \ud544\uc694\ub85c \ud588\ub2e4. \uacbd\uc791\uc9c0\uc640 \ubaa9\uc7a5, \uc7a5\uc778\uacfc \uad50\uc5ed\ub85c, \ub0b4\ub959\uacfc \ubc14\ub2e4\uac00 \uc774\uc5b4\uc84c\uae30 \ub54c\ubb38\uc774\ub2e4. \uac00\uae4c\uc774\uc5d0\uc11c \ubcf8 \ub3cc \uc0ac\uc774\uc758 \ud2c8\uc774 \uba40\ub9ac \ub5a8\uc5b4\uc9c4 \uc138\uacc4\uae4c\uc9c0 \uc0dd\uac01\ud558\uac8c \ud558\ub294 \uc720\uc801\uc774\ub2e4."}, {"id": "gyeonghoeru-pond-dragon", "title": "\uacbd\ud68c\ub8e8 \uc5f0\ubabb\uc5d0\uc11c\ub294 \uc65c \uccad\ub3d9 \uc6a9\uc774 \ub098\uc654\uc744\uae4c", "summary": "\uc5f0\ubabb\uc5d0\uc11c \ubc1c\uacac\ub41c \uc6a9\uc740 \uc7a5\uc2dd\uc5d0\uc11c \ub5a8\uc5b4\uc9c4 \ubb3c\uac74\uc774 \uc544\ub2c8\uc5c8\uc2b5\ub2c8\ub2e4. \uae30\ub85d\uc5d0\ub294 \ubb3c\uc5d0 \ub123\uc740 \uc774\uc720\uac00 \ub0a8\uc544 \uc788\uc2b5\ub2c8\ub2e4.", "category": "cities", "category_title": "Cities", "subcategory": "Asia", "url": "stories/gyeonghoeru-pond-dragon/index.html", "image": "media/gyeonghoeru-pond-dragon.jpg", "alt": "\uad81\uad90 \uc5f0\ubabb\uc758 \uc815\uc790 \ubc18\uc601\uacfc \ubb3c \uc544\ub798 \uc791\uc740 \uc6a9\uc758 \ud615\uc0c1\uc744 \uadf8\ub9b0 \uc124\uba85\uc6a9 AI \uc0bd\ud654", "text": "\uacbd\ud68c\ub8e8 \uc5f0\ubabb\uc5d0\uc11c\ub294 \uc65c \uccad\ub3d9 \uc6a9\uc774 \ub098\uc654\uc744\uae4c \ubb3c\uc18d\uc5d0 \ub123\uc5b4 \ub454 \uad81\uad90\uc758 \ud654\uc7ac \uc608\ubc29 \uae30\uc6d0 \uc5f0\ubabb\uc5d0\uc11c \ubc1c\uacac\ub41c \uc6a9\uc740 \uc7a5\uc2dd\uc5d0\uc11c \ub5a8\uc5b4\uc9c4 \ubb3c\uac74\uc774 \uc544\ub2c8\uc5c8\uc2b5\ub2c8\ub2e4. \uae30\ub85d\uc5d0\ub294 \ubb3c\uc5d0 \ub123\uc740 \uc774\uc720\uac00 \ub0a8\uc544 \uc788\uc2b5\ub2c8\ub2e4. Asia \ub3c4\uc2dc \uacbd\ubcf5\uad81\uc758 \uacbd\ud68c\ub8e8\ub97c \ubcf4\uba74 \uc5f0\ubabb\uc5d0 \ube44\uce5c \uac74\ubb3c\ubd80\ud130 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \ubb3c \uc544\ub798\uc5d0 \ubb34\uc5c7\uc774 \uc788\uc5c8\ub294\uc9c0\uae4c\uc9c0 \uc0dd\uac01\ud558\uac8c \ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \uadf8\ub7f0\ub370 1997\ub144, \uadf8 \uc5f0\ubabb\uc5d0\uc11c \uccad\ub3d9\uc73c\ub85c \ub9cc\ub4e0 \uc6a9\uc774 \ubc1c\uacac\ub418\uc5c8\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc18c\uac1c\ud558\ub294 \uc720\ubb3c\uc740 \uae38\uc774\uac00 1\ubbf8\ud130\ub97c \ud6cc\uca4d \ub118\uace0 \ubb34\uac8c\ub3c4 60\ud0ac\ub85c\uadf8\ub7a8\uc774 \ub118\ub294\ub2e4. \uc190\ubc14\ub2e5\uc5d0 \ub4e4\uc5b4\uc624\ub294 \uc791\uc740 \uc7a5\uc2dd\uc740 \uc544\ub2c8\ub2e4. \uc65c \uc774\ub7f0 \ubb3c\uac74\uc774 \ubb3c\uc18d\uc5d0 \uc788\uc5c8\uc744\uae4c. \ub204\uac00 \ub5a8\uc5b4\ub728\ub9b0 \uac83\uc774 \uc544\ub2c8\ub77c, \uad81\uad90\uc744 \ubd88\uc5d0\uc11c \uc9c0\ucf1c \ub2ec\ub77c\ub294 \ub73b\uc73c\ub85c \ub123\uc5b4 \ub454 \uc6a9\uc774\uc5c8\ub2e4. \ub098\ubb34\ub85c \uc9c0\uc740 \uac74\ubb3c\uc774 \ub9ce\uc558\ub358 \uad81\uad90\uc5d0\uc11c \ubd88\uc740 \ud070 \uac71\uc815\uac70\ub9ac\uc600\ub2e4. \uacbd\ubcf5\uad81\uc744 \ub2e4\uc2dc \uc9d3\ub294 \uacfc\uc815\uc5d0\uc11c\ub3c4 \ud654\uc7ac\ub97c \ud53c\ud558\ub824\ub294 \uc5ec\ub7ec \uc870\uce58\uac00 \uc774\ub8e8\uc5b4\uc84c\ub2e4\uace0 \ubc15\ubb3c\uad00\uc740 \uc124\uba85\ud55c\ub2e4. \ub2f9\uc2dc \uc0ac\ub78c\ub4e4\uc740 \uc6a9\uc774 \ubb3c\uacfc \uad6c\ub984\uc744 \ub2e4\uc2a4\ub9b0\ub2e4\uace0 \uc5ec\uacbc\ub2e4. \ubb3c\uc744 \ub2e4\ub8e8\ub294 \uc874\uc7ac\uc5d0\uac8c \ubd88\uc744 \ub9c9\uc544 \ub2ec\ub77c\ub294 \ub73b\uc744 \ub2f4\uc544 \uc5f0\ubabb\uc5d0 \uccad\ub3d9 \uc6a9\uc744 \ub123\uc740 \uac83\uc774\ub2e4. \uc774\ub54c\uc758 \uc6a9\uc740 \uc18c\ud654 \uc7a5\uce58\ub77c\uae30\ubcf4\ub2e4 \ubc14\ub78c\uc744 \ub2f4\uc740 \uc0c1\uc9d5\uc774\uc5c8\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc740 \u300e\uacbd\ubcf5\uad81\uc601\uac74\uc77c\uae30\u300f\ub97c \uadfc\uac70\ub85c \uc81c\uc791\uacfc \ubc30\uce58 \uacfc\uc815\uc744 \uc18c\uac1c\ud55c\ub2e4. \uc6a9\uc744 \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\ubfd0 \uc544\ub2c8\ub77c \ubb3c\uc5d0 \uac00\ub77c\uc549\ud78c \uae30\ub85d\uae4c\uc9c0 \ub0a8\uc544 \uc788\ub2e4. \ub2e8\uc21c\ud788 \uc0dd\uae40\uc0c8\ub97c \ubcf4\uace0 \uc624\ub298\uc758 \uad00\ub78c\uac1d\uc774 \ubd99\uc778 \ud574\uc11d\uc740 \uc544\ub2cc \uc148\uc774\ub2e4. \uccad\ub3d9 \uc6a9\uc740 1865\ub144\uc5d0 \ud55c \uc30d\uc73c\ub85c \uc81c\uc791\ub418\uc5c8\uace0, 1867\ub144\uc5d0 \uacbd\ud68c\ub8e8 \uc5f0\ubabb\uc5d0 \ub123\uc5c8\ub2e4\uace0 \uae30\ub85d\ub418\uc5b4 \uc788\ub2e4. \uadf8\ub7f0\ub370 1997\ub144 \ubc1c\uacac \ub2f9\uc2dc \ud655\uc778\ub41c \uac83\uc740 \ud55c \ub9c8\ub9ac\uc600\ub2e4. \ub458\uacfc \ud558\ub098\uc758 \ucc28\uc774\uac00 \uc791\uc740 \uad81\uae08\uc99d\uc744 \ub0a8\uae34\ub2e4. \uadf8\ub807\ub2e4\uace0 \ub2e4\ub978 \ud55c \ub9c8\ub9ac\uc758 \ud589\ubc29\uc744 \uc0c1\uc0c1\uc73c\ub85c \ucc44\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub0a8\uc544 \uc788\ub294 \uae30\ub85d\uc774 \uc54c\ub824\uc8fc\ub294 \uc218\uc640 \uc2e4\uc81c \ubc1c\uacac\uc5d0\uc11c \ud655\uc778\ud55c \uc218\ub97c \ub098\ub204\uc5b4 \uae30\uc5b5\ud558\uba74 \ub41c\ub2e4. \ubc1c\uacac\ub41c \uc6a9\uc740 \ubc18\ucabd\uc529 \uc8fc\uc870\ud55c \ub4a4 \ubd99\uc5ec \ub9cc\ub4dc\ub294 \ubc29\uc2dd\uc73c\ub85c \uc81c\uc791\ub418\uc5c8\ub2e4\uace0 \ud55c\ub2e4. \ubb3c\uc18d\uc5d0 \ub123\uc744 \ubb3c\uac74\uc5d0\ub3c4 \uae08\uc18d\uc744 \ub2e4\ub8e8\ub294 \uc218\uace0\uac00 \ub4e4\uc5b4\uac14\ub2e4. \ubcf4\uc774\uc9c0 \uc54a\ub294 \uacf3\uc5d0 \ub454\ub2e4\uace0 \ub300\ucda9 \ub9c8\ub828\ud55c \ubb3c\uac74\uc740 \uc544\ub2c8\uc5c8\ub358 \uac83\uc774\ub2e4. \uace0\uc0ac\ubb38\uc5d0\ub294 \uad81\uad90\uc744 \uc624\ub798 \ubcf4\ud638\ud574 \ub2ec\ub77c\ub294 \uae30\uc6d0\uc774 \ub2f4\uaca8 \uc788\ub2e4. \uadf8 \uae00\uc744 \ud1b5\ud574 \uc6b0\ub9ac\ub294 \uc6a9\uc774 \uc2e4\uc81c\ub85c \ubd88\uc744 \ub9c9\uc558\ub294\uc9c0\uac00 \uc544\ub2c8\ub77c, \uc0ac\ub78c\ub4e4\uc774 \ubb34\uc5c7\uc744 \ub450\ub824\uc6cc\ud558\uace0 \ubb34\uc5c7\uc744 \ubc14\ub790\ub294\uc9c0 \uc77d\uac8c \ub41c\ub2e4. \uc5f0\ubabb\uc5d0\uc11c \uae08\uc18d \ubb3c\uac74\uc774 \ub098\uc654\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c\ub294 \ubb3c\uc5d0 \ube60\ub728\ub9b0 \uac83\uc778\uc9c0 \uc77c\ubd80\ub7ec \ub123\uc740 \uac83\uc778\uc9c0 \uc54c\uae30 \uc5b4\ub835\ub2e4. \uc774 \uc6a9\uc740 \uacf5\uc0ac \uae30\ub85d\uacfc \ud568\uaed8 \uc77d\uc744 \uc218 \uc788\ub2e4\ub294 \uc810\uc5d0\uc11c \ud2b9\ubcc4\ud558\ub2e4. \uc81c\uc791\uacfc \ubc30\uce58\uc758 \uc2dc\uac04\uc774 \uc801\ud600 \uc788\uc5b4, \ubc1c\uacac\ud55c \ubb3c\uac74\uc744 \uad81\uad90\uc744 \ub2e4\uc2dc \uc9d3\ub358 \uc0ac\ub78c\ub4e4\uc758 \uc120\ud0dd\uacfc \uc5f0\uacb0\ud560 \uc218 \uc788\ub2e4. \uc720\ubb3c\uc740 \ubaa8\uc591\uc744 \ubcf4\uc5ec \uc8fc\uace0 \uae30\ub85d\uc740 \uadf8 \ubb3c\uac74\uc774 \ub193\uc778 \uc774\uc720\ub97c \uc124\uba85\ud55c\ub2e4. \ub450 \uc790\ub8cc\uac00 \ub098\ub780\ud788 \uc788\uc744 \ub54c\uc5d0\ub3c4 \uac01\uac01 \uc54c\ub824 \uc8fc\ub294 \ubc94\uc704\ub294 \ub2e4\ub974\ub2e4. \ubb38\uc11c\uc758 \ud55c \uc30d\uacfc \ubc1c\uacac \ub2f9\uc2dc\uc758 \ud55c \uc810\uc744 \uac19\uac8c \ub9cc\ub4e4 \uc218\ub294 \uc5c6\ub2e4. \uc624\ud788\ub824 \ucc28\uc774\ub97c \ub0a8\uaca8 \ub450\uba74 \uc55e\uc73c\ub85c \ubb34\uc5c7\uc744 \ub354 \ud655\uc778\ud574\uc57c \ud558\ub294\uc9c0 \ubcf4\uc778\ub2e4. \ubb3c\uac74\uacfc \ubb38\uc11c\uac00 \uc11c\ub85c\ub97c \ubcf4\uc644\ud55c\ub2e4\ub294 \uac83\uc740 \uc5b8\uc81c\ub098 \ube48\uce78 \uc5c6\uc774 \uc77c\uce58\ud55c\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \uae38\uc774 146.5\uc13c\ud2f0\ubbf8\ud130, \ubb34\uac8c 66.5\ud0ac\ub85c\uadf8\ub7a8\uc774\ub77c\ub294 \ud06c\uae30\ub97c \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc791\uc740 \ubd80\uc801\uc744 \ubab0\ub798 \ubb3c\uc5d0 \ub358\uc9c0\ub294 \uc7a5\uba74\uacfc\ub294 \ub2e4\ub974\ub2e4. \uae08\uc18d\uc744 \ub9c8\ub828\ud558\uace0 \ud615\uc0c1\uc744 \ub9cc\ub4e4\uace0 \uc62e\uae30\ub294 \uacfc\uc815\uc774 \ud544\uc694\ud55c \ubb3c\uac74\uc774\uc5c8\ub2e4. \ud55c \uc30d\uc744 \uc81c\uc791\ud588\ub2e4\ub294 \uae30\ub85d\uc744 \uc0dd\uac01\ud558\uba74 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uacf3\uc5d0 \ub450\ub294 \uc0c1\uc9d5\uc5d0\ub3c4 \uc801\uc9c0 \uc54a\uc740 \uc900\ube44\uac00 \ub4e4\uc5b4\uac14\uc74c\uc744 \uc9d0\uc791\ud560 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ub204\uac00 \uc5b4\ub5a4 \uc790\uc138\ub85c \uc6a9\uc744 \uc6b4\ubc18\ud588\ub294\uc9c0 \uac19\uc740 \uad6c\uccb4\uc801\uc778 \ud604\uc7a5\uc744 \uc0c1\uc0c1\uc73c\ub85c \ucc44\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \ud655\uc778\ub41c \ud06c\uae30\uc640 \uc81c\uc791 \ubc29\uc2dd\ub9cc\uc73c\ub85c\ub3c4 \ucda9\ubd84\ud788 \ud765\ubbf8\ub86d\ub2e4. \uac74\ucd95\uc744 \uc644\uc131\ud55c\ub2e4\ub294 \uc77c\uc5d0\ub294 \uc0ac\ub78c\ub4e4\uc774 \uac10\uc0c1\ud560 \uae30\ub465\uacfc \uc9c0\ubd95\ubfd0 \uc544\ub2c8\ub77c, \uc644\uc131\ud55c \ub4a4\uc5d0 \uc27d\uac8c \ubcf4\uc774\uc9c0 \uc54a\uc744 \ubb3c\uac74\uc744 \ub9c8\ub828\ud558\ub294 \uc77c\ub3c4 \ud3ec\ud568\ub418\uc5b4 \uc788\uc5c8\ub2e4. \uc6a9\uc744 \uc5f0\ubabb\uc5d0 \ub454 \uc774\uc720\ub294 \ubb3c\uacfc \uad6c\ub984\uc744 \ub2e4\uc2a4\ub9b0\ub2e4\uace0 \uc5ec\uae34 \uc874\uc7ac\uc5d0\uac8c \ud654\uc7ac\ub97c \ub9c9\uc544 \ub2ec\ub77c\uace0 \uae30\uc6d0\ud588\uae30 \ub54c\ubb38\uc774\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc0c1\uc9d5\uc758 \uc5f0\uacb0\uc774 \ubd84\uba85\ud558\ub2e4. \ubb3c\uacfc \ubd88\uc774\ub77c\ub294 \ub300\ube44\uac00 \uac74\ubb3c\uc758 \uc7ac\ub8cc\uc640 \uc704\ud5d8\uc5d0 \ub300\ud55c \uac71\uc815 \uc18d\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \ub098\ubb34\ub85c \uc9c0\uc740 \uad81\uad90\uc758 \uc544\ub984\ub2e4\uc6b4 \ubaa8\uc2b5\uacfc \uadf8\uac83\uc744 \uc783\uc744 \uc218 \uc788\ub2e4\ub294 \ub450\ub824\uc6c0\uc774 \uac19\uc740 \uacf5\uac04\uc5d0 \uc788\uc5c8\ub2e4. \uc624\ub298\uc758 \uc18c\ubc29 \uc124\ube44\uc640 \uac19\uc740 \uae30\ub2a5\uc744 \ud588\ub2e4\uace0 \ud310\ub2e8\ud558\uae30\ubcf4\ub2e4, \uc0ac\ub78c\ub4e4\uc774 \uc704\ud5d8\uc5d0 \ub300\uc751\ud560 \ub54c \uae30\uc220\uc801\uc778 \uc870\uce58\uc640 \uae30\uc6d0\uc744 \uc5b4\ub5bb\uac8c \ud568\uaed8 \ub450\uc5c8\ub294\uc9c0 \uc0dd\uac01\ud574 \ubcfc \uc218 \uc788\ub2e4. \ubc14\ub78c\uc744 \ub2f4\uc740 \ubb3c\uac74\uc740 \uc2e4\uc81c \uc704\ud5d8\uc744 \uc5c6\uc574\ub2e4\ub294 \uc99d\uba85\ubcf4\ub2e4 \uadf8 \uc704\ud5d8\uc774 \uc5bc\ub9c8\ub098 \uc911\uc694\ud55c \ubb38\uc81c\uc600\ub294\uc9c0\ub97c \ubcf4\uc5ec \uc900\ub2e4. \uc7a5\uc2dd\uc758 \ub73b\uc744 \uc544\ub294 \uc77c\uc774 \uac74\ubb3c\uc744 \uc0ac\uc6a9\ud558\ub358 \uc0ac\ub78c\uc758 \uac71\uc815\uc5d0 \uac00\uae4c\uc774 \uac00\ub294 \uae38\uc774 \ub41c\ub2e4. \uacbd\ud68c\ub8e8\ub97c \ubcf4\uba74 \uc815\uc790\uc640 \ubb3c\uc5d0 \ube44\uce5c \uc9c0\ubd95\uc744 \ud55c \uc7a5\uc758 \ud48d\uacbd\ucc98\ub7fc \ubc14\ub77c\ubcf4\uac8c \ub41c\ub2e4. \uc6a9\uc758 \uc774\uc57c\uae30\ub294 \uc2dc\uc120\uc744 \uc218\uba74 \uc544\ub798\ub85c \uc62e\uae34\ub2e4. \uc5f0\ubabb\uc774 \uac74\ubb3c\uc744 \ub3cb\ubcf4\uc774\uac8c \ud558\ub294 \ubc30\uacbd\uc774\uba74\uc11c \uae30\uc6d0\uc744 \ub9e1\uae30\ub294 \uc790\ub9ac\uc600\ub2e4\ub294 \uc0ac\uc2e4\uc740, \uac74\ucd95\uc758 \ubc94\uc704\ub97c \ubcbd\uacfc \uae30\ub465 \ubc16\uc73c\ub85c \ub113\ud78c\ub2e4. \uac19\uc740 \uacbd\uce58\ub97c \ubcf4\ub354\ub77c\ub3c4 \ubb3b\uac8c \ub418\ub294 \uc9c8\ubb38\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc0bd\ud654\uc5d0\uc11c \uc6a9\uc758 \uc815\ud655\ud55c \ud615\ud0dc\ub098 \ucd9c\ud1a0 \uc704\uce58\ub97c \uc54c\uc544\ub0bc \uc218\ub294 \uc5c6\ub2e4. \uc2e4\uc81c \uc720\ubb3c\uc758 \ubaa8\uc2b5\uacfc \ucd9c\ud1a0 \uc774\ub825\uc740 \ubc15\ubb3c\uad00 \uc790\ub8cc\ub97c \ud1b5\ud574 \ud655\uc778\ud560 \ubd80\ubd84\uc774\ub2e4. \ub300\uc2e0 \uc774 \uc774\uc57c\uae30\uc758 \uc785\uad6c\uc5d0\uc11c\ub294 \ubb3c \uc544\ub798\uc5d0\ub3c4 \uc0ac\ub78c\uc774 \uc120\ud0dd\ud574 \ub193\uc740 \uac83\uc774 \uc788\uc5c8\ub2e4\ub294 \uc810\uc744 \uae30\uc5b5\ud558\uba74 \uc88b\ub2e4. \uc870\uc6a9\ud55c \ud48d\uacbd\uc5d0 \uc81c\uc791\uacfc \uae30\ub85d, \uc7ac\ubc1c\uacac\uc758 \uc2dc\uac04\uc774 \ud3ec\uac1c\uc9c4\ub2e4. \uad81\uad90\uc758 \uc0c1\uc9d5\uc740 \uc9c0\ubd95\uc774\ub098 \ubb38 \uc704\uc5d0\uc11c\ub9cc \ubc1c\uacac\ub418\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uacbd\ud68c\ub8e8\uc758 \uc6a9\uc740 \uc624\ub7ab\ub3d9\uc548 \ubb3c \uc544\ub798\uc5d0 \uc788\uc5c8\ub2e4. \ubc14\ub77c\ubcf4\ub294 \uc0ac\ub78c\uc5d0\uac8c \uc790\uc2e0\uc744 \ub4dc\ub7ec\ub0b4\ub294 \uc7a5\uc2dd\uacfc\ub294 \uc870\uae08 \ub2e4\ub978 \uc790\ub9ac\ub2e4. \uc774 \uc0ac\uc2e4\uc744 \uc548 \ub4a4 \uacbd\ud68c\ub8e8\ub97c \ubcf4\uba74 \uc5f0\ubabb\uc774 \ub2e8\uc21c\ud55c \ubc30\uacbd\ub9cc\uc73c\ub85c \ubcf4\uc774\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \uac74\ubb3c\uc758 \uc544\ub984\ub2e4\uc6c0\uc744 \ube44\ucd94\ub358 \ubb3c\uc774, \ud55c\ub54c\ub294 \ubd88\uc744 \ub9c9\uc544 \uc8fc\uae30\ub97c \ubc14\ub77c\ub294 \ub9c8\uc74c\uc744 \ub9e1\uae34 \uacf3\uc774\uae30\ub3c4 \ud588\ub2e4. \ub2e4\uc74c\uc5d0 \uacbd\ud68c\ub8e8 \uc0ac\uc9c4\uc744 \ubcf4\uac8c \ub41c\ub2e4\uba74 \uc9c0\ubd95\uc5d0\uc11c \ubb3c\uac00\ub85c \uc2dc\uc120\uc744 \ub0b4\ub824 \ubcf4\uc790. \uc870\uc6a9\ud55c \uc218\uba74 \uc544\ub798\uc5d0\ub3c4 \uac74\ubb3c\uc744 \uc9c0\ud0a4\uace0 \uc2f6\uc5c8\ub358 \uc0ac\ub78c\ub4e4\uc758 \uc774\uc57c\uae30\uac00 \ub4e4\uc5b4 \uc788\uc5c8\ub2e4."}, {"id": "harappa-seal-and-distant-trade", "title": "\ud558\ub77c\ud30c \u2014 \uc791\uc740 \uc778\uc7a5\uc740 \uc65c \uba3c \ub3c4\uc2dc\uc5d0\uc11c \ub098\uc654\uc744\uae4c", "summary": "\uc778\ub354\uc2a4 \ubb38\uba85\uc758 \uc2e4\uc81c \uc778\uc7a5\uacfc \ud604\ub300 \uc555\uc778 \uc0ac\uc9c4\uc744 \ubcf4\uba70 \ub3c4\uc2dc\uc758 \uad50\uc5ed, \ud45c\uc2dc\uc640 \ud574\ub3c5\uc758 \ucc28\uc774\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "cities", "category_title": "Cities", "subcategory": "Asia", "url": "stories/harappa-seal-and-distant-trade/index.html", "image": "media/harappa-seal-and-distant-trade.jpg", "alt": "\uc778\ub354\uc2a4 \ubb38\uba85\uc758 \ub3d9\ubb3c\uacfc \uae30\ud638\uac00 \uc0c8\uaca8\uc9c4 \uc2e4\uc81c \uc778\uc7a5 \uc67c\ucabd, \ud604\ub300\uc5d0 \ub9cc\ub4e0 \uc810\ud1a0 \uc555\uc778 \uc624\ub978\ucabd.", "text": "\ud558\ub77c\ud30c \u2014 \uc791\uc740 \uc778\uc7a5\uc740 \uc65c \uba3c \ub3c4\uc2dc\uc5d0\uc11c \ub098\uc654\uc744\uae4c \uc544\uc9c1 \uc77d\uc9c0 \ubabb\ud55c \uae00\uc790\uc640 \ubb3c\uac74\uc774 \uac74\ub108\uac04 \uae38 \uc778\ub354\uc2a4 \ubb38\uba85\uc758 \uc2e4\uc81c \uc778\uc7a5\uacfc \ud604\ub300 \uc555\uc778 \uc0ac\uc9c4\uc744 \ubcf4\uba70 \ub3c4\uc2dc\uc758 \uad50\uc5ed, \ud45c\uc2dc\uc640 \ud574\ub3c5\uc758 \ucc28\uc774\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Asia \ub3c4\uc2dc \uc190\ubc14\ub2e5\ubcf4\ub2e4 \uc791\uc740 \uc778\uc7a5 \ud558\ub098\uc5d0\ub294 \ub3d9\ubb3c\uacfc \uc9e7\uc740 \uae30\ud638\ub4e4\uc774 \uc0c8\uaca8\uc838 \uc788\ub2e4. \ud070 \uad81\uc804\uc774\ub098 \uc655\uc758 \ubb34\ub364\ucc98\ub7fc \uc2dc\uc120\uc744 \uc555\ub3c4\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uadf8\ub7f0\ub370 \uc774\ub7f0 \uc791\uc740 \ubb3c\uac74\uc740 \uc624\ub798\ub41c \ub3c4\uc2dc\uac00 \ub2e4\ub978 \uc9c0\uc5ed\uacfc \uc5b4\ub5bb\uac8c \uc5f0\uacb0\ub418\uc5c8\ub294\uc9c0 \ubb3b\ub294 \uc911\uc694\ud55c \ub2e8\uc11c\uac00 \ub41c\ub2e4. \uc778\ub354\uc2a4 \ubb38\uba85\uc758 \ud558\ub77c\ud30c\ub97c \ub9cc\ub0a0 \ub54c\ub3c4 \uadf8\ub807\ub2e4. \ub3c4\uc2dc\uc758 \uc774\ub984\uc740 \ub0af\uc124\uc5b4\ub3c4 \ubb3c\uac74\uc5d0 \ud45c\uc2dc\ub97c \ub0a8\uae30\uace0 \ub2e4\ub978 \uacf3\uc73c\ub85c \ubcf4\ub0b4\ub294 \uc77c\uc740 \uc775\uc219\ud558\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc2e4\uc81c \uc778\uc7a5 \uc0ac\uc9c4\uc5d0\uc11c \ucd9c\ubc1c\ud574, \uc61b \uc0ac\ub78c\ub4e4\uc740 \ubb34\uc5c7\uc744 \uad6c\ubcc4\ud558\ub824 \ud588\uace0 \uc6b0\ub9ac\ub294 \uc5b4\ub514\uae4c\uc9c0 \uc77d\uc744 \uc218 \uc788\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uc778\ub354\uc2a4 \ubb38\uba85\uc740 \uc624\ub298\ub0a0 \ud30c\ud0a4\uc2a4\ud0c4\uacfc \uc778\ub3c4\uc5d0 \uac78\uce5c \ub113\uc740 \uc9c0\uc5ed\uc5d0\uc11c \ubc1c\uc804\ud588\ub2e4. \ud558\ub77c\ud30c\ub294 \uadf8 \ub300\ud45c\uc801\uc778 \uace0\uace0\ud559 \uc720\uc801 \uac00\uc6b4\ub370 \ud558\ub098\ub2e4. \uad50\uc7ac\ub294 \uadfc\ub300\uc758 \uc5f0\uad6c\uc5d0\uc11c \ud558\ub77c\ud30c\uac00 \uc77c\ucc0d \uc54c\ub824\uc9c4 \uc8fc\uc694 \uc720\uc801\uc774\uc5b4\uc11c \uc774 \ubb38\uba85\uc744 \ud558\ub77c\ud30c \ubb38\uba85\uc774\ub77c\uace0\ub3c4 \ubd80\ub978\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub3c4\uc2dc \ud558\ub098\uc758 \uc774\ub984\uc774 \ub113\uc740 \ubb38\ud654\ub97c \uac00\ub9ac\ud0a4\ub294 \ub9d0\uc774 \ub41c \uc148\uc774\ub2e4. \uadf8\ub807\ub2e4\uace0 \uadf8 \ub113\uc740 \uc9c0\uc5ed\uc774 \uc5b8\uc81c\ub098 \ud55c \uc655\uc758 \uba85\ub839 \uc544\ub798 \uc6c0\uc9c1\uc600\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc815\uce58 \uc870\uc9c1\uc758 \ubaa8\uc2b5\uc5d0\ub294 \uc544\uc9c1 \ubd88\ud655\uc2e4\ud55c \ubd80\ubd84\uc774 \uc788\ub2e4. \uac19\uc740 \uc774\ub984\uc73c\ub85c \ubb36\ub294 \uc77c\uacfc \uc2e4\uc81c \ud1b5\uce58 \ubc29\uc2dd\uc744 \uc544\ub294 \uc77c\uc740 \uad6c\ubcc4\ud560 \ud544\uc694\uac00 \uc788\ub2e4. \uad50\uc7ac\ub294 \uc778\ub354\uc2a4 \ub3c4\uc2dc\ub4e4\uc5d0\uc11c \uc798 \uc815\ub9ac\ub41c \uac70\ub9ac\uc640 \uc8fc\uac70 \uad6c\uc5ed, \uc791\uc5c5\uc7a5, \ubc30\uc218 \uc2dc\uc124\uc774 \ubc1c\uacac\ub418\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud558\ub77c\ud30c\uc5d0\ub3c4 \ubb3c\uac74\uc744 \ub9cc\ub4dc\ub294 \uad6c\uc5ed\uacfc \ub178\ub3d9\uc790\uc758 \uac70\uc8fc \ud754\uc801\uc774 \uc788\uc5c8\ub2e4. \ub3c4\uc2dc\uc758 \ud798\uc740 \ub208\uc5d0 \ub744\ub294 \uae30\ub150\ubb3c\ubfd0 \uc544\ub2c8\ub77c \uc77c\uc0c1\uc744 \uc870\uc9c1\ud558\ub294 \uc2dc\uc124\uc5d0\uc11c\ub3c4 \ub4dc\ub7ec\ub09c\ub2e4. \ub2e4\ub9cc \ubaa8\ub4e0 \uc720\uc801\uc758 \uc2dc\uc124\uc774 \ub611\uac19\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ubaa8\ud5e8\uc870\ub2e4\ub85c\uc5d0\uc11c \ud655\uc778\ub41c \ud2b9\uc815 \uac74\ubb3c\uc744 \uadf8\ub300\ub85c \ud558\ub77c\ud30c\uc758 \uac74\ubb3c\ub85c \uc62e\uaca8 \ub9d0\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc5ec\ub7ec \ub3c4\uc2dc\uac00 \uacf5\uc720\ud55c \ud2b9\uc9d5\uacfc \ud55c \uc7a5\uc18c\uc5d0\uc11c \uc9c1\uc811 \ud655\uc778\ud55c \uc0ac\uc2e4\uc744 \ub098\ub204\uba74, \ub2ee\uc740 \ubb38\uba85\uc774\ub77c\ub294 \ub9d0 \uc548\uc758 \ucc28\uc774\ub3c4 \ubcfc \uc218 \uc788\ub2e4. \uc778\ub354\uc2a4 \uc778\uc7a5\uc5d0\ub294 \ub3d9\ubb3c\uacfc \uc0ac\ub78c\uc758 \ubaa8\uc2b5, \uc9e7\uc740 \uae30\ud638\uac00 \uc0c8\uaca8\uc838 \uc788\ub2e4. \uad50\uc7ac\ub294 \uc774\ub7f0 \uc778\uc7a5\uc73c\ub85c \ubd80\ub4dc\ub7ec\uc6b4 \uc810\ud1a0\uc5d0 \uc790\uad6d\uc744 \ub0a8\uaca8 \uadf8\ub987\uc774\ub098 \uc9d0\uacfc \uad00\ub828\ub41c \ud45c\uc2dc\ub97c \ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc0c8\uae34 \ubb3c\uac74\uacfc \uadf8\uac83\uc774 \ub0a8\uae34 \ud754\uc801\uc740 \uc11c\ub85c \uc5f0\uacb0\ub418\ub294 \ub450 \ubd80\ubd84\uc774\ub2e4. \uc624\ub298\uc758 \ud0dd\ubc30 \uc0c1\uc790\uc5d0 \ubd99\uc740 \uc815\ubcf4\ud45c\uc640 \uc644\uc804\ud788 \uac19\uc740 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \uc5ec\ub7ec \uc0ac\ub78c\uc758 \ubb3c\uac74\uc774 \uc624\uac08 \ub54c \ubb34\uc5c7\uc744 \uad6c\ubcc4\ud558\uace0 \uc5b4\ub5bb\uac8c \ud655\uc778\ud560\uc9c0\ub77c\ub294 \uc9c8\ubb38\uc740 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \uc774\ub984\uc778\uc9c0 \uc9c0\uc704\uc778\uc9c0, \uc18c\uc720\uc640 \uac70\ub798\uc758 \uc5b4\ub5a4 \ub0b4\uc6a9\uc744 \ud45c\uc2dc\ud588\ub294\uc9c0 \uc138\ubd80\ub294 \uc544\uc9c1 \ub2e8\uc815\ud560 \uc218 \uc5c6\ub2e4. \uae30\ub2a5\uc758 \ucd94\uc815\uacfc \uae30\ud638\uc758 \uc815\ud655\ud55c \ubc88\uc5ed\uc740 \ub2e4\ub974\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc0ac\uc9c4\uc758 \uc67c\ucabd\uc740 \uc778\ub354\uc2a4 \ubb38\uba85\uc758 \uc2e4\uc81c \uc778\uc7a5\uc774\uace0, \uc624\ub978\ucabd\uc740 \uadf8\uac83\uc744 \ub20c\ub7ec \ub9cc\ub4e0 \ud604\ub300\uc758 \uc810\ud1a0 \uc555\uc778\uc774\ub2e4. \ub450 \ubb3c\uac74\uc774 \ubaa8\ub450 \uace0\ub300\uc5d0 \uc81c\uc791\ub41c \ud55c \uc30d\uc740 \uc544\ub2c8\ub2e4. \uc6d0\ub798 \uc0c8\uae34 \uba74\uc774 \uc5b4\ub5a4 \ud754\uc801\uc744 \ub9cc\ub4dc\ub294\uc9c0 \ubcf4\uae30 \uc88b\uac8c \ud568\uaed8 \uc81c\uc2dc\ud55c \uac83\uc774\ub2e4. \uc774 \ucc28\uc774\ub97c \uc54c\uba74 \ub3d9\ubb3c\uc758 \ubc29\ud5a5\uacfc \uae30\ud638\uc758 \ubc30\uce58\ub3c4 \ube44\uad50\ud558\uac8c \ub41c\ub2e4. \uac70\uc6b8\ucc98\ub7fc \ub4a4\uc9d1\ud788\ub294 \uad00\uacc4\ub97c \ub208\uc73c\ub85c \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \uc0ac\uc9c4\uc758 \uc124\uba85\uc744 \uc77d\ub294 \uc77c\uc740 \uac10\uc0c1\uc744 \ubc29\ud574\ud558\ub294 \ubd80\ub85d\uc774 \uc544\ub2c8\ub2e4. \ub208\uc55e\uc758 \uc790\ub8cc\uac00 \ubb34\uc5c7\uc774\uba70 \uc5b4\ub5a4 \uacfc\uc815\uc744 \ubcf4\uc5ec \uc8fc\ub294\uc9c0 \uc815\ud655\ud558\uac8c \ubcf4\ub294 \uccab \ub2e8\uacc4\ub2e4. \uad50\uc7ac\ub294 \uc778\ub354\uc2a4 \uacc4\ud1b5\uc758 \uc778\uc7a5\uc774 \uba54\uc18c\ud3ec\ud0c0\ubbf8\uc544\uc758 \uc6b0\ub974 \uac19\uc740 \ub3c4\uc2dc\uc5d0\uc11c\ub3c4 \ubc1c\uacac\ub418\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc778\ub354\uc2a4\uc640 \uba54\uc18c\ud3ec\ud0c0\ubbf8\uc544 \uc0ac\uc774\uc5d0\ub294 \ubc14\ub2e4\uc640 \uc721\uc9c0\ub97c \ud1b5\ud55c \uad50\uc5ed\uc774 \uc788\uc5c8\ub2e4. \uadc0\ud55c \ub3cc\uacfc \uc870\uac1c \uac19\uc740 \ubb3c\ud488\ub3c4 \uc624\uac14\ub2e4. \uc791\uc740 \uc778\uc7a5\uc774 \uc790\uae30 \uc9c0\uc5ed \ubc16\uc5d0\uc11c \ub098\uc628\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uadf8 \uc5f0\uacb0\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ud558\uc9c0\ub9cc \uc778\uc7a5 \ud55c \uac1c\uac00 \ubc1c\uacac\ub418\uc5c8\ub2e4\uace0 \ud2b9\uc815 \uc0c1\uc778\uc758 \uc804\uccb4 \uc5ec\ud589\uc744 \ubcf5\uc6d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ubb3c\uac74\uc740 \uc5ec\ub7ec \uc0ac\ub78c\uc758 \uc190\uc744 \uac70\ucce4\uc744 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uc790\ub8cc\uac00 \uc54c\ub824 \uc8fc\ub294 \uad50\ub958\uc758 \uc874\uc7ac\uc640 \uc6b0\ub9ac\uac00 \ubd99\uc774\uace0 \uc2f6\uc740 \ud55c \uc0ac\ub78c\uc758 \ubaa8\ud5d8\ub2f4\uc740 \ub2e4\ub978 \uac83\uc774\ub2e4. \uc815\ud655\ud788 \uc544\ub294 \ubc94\uc704 \uc548\uc5d0\uc11c\ub3c4 \uc774\ub3d9\uc758 \uaddc\ubaa8\ub294 \ucda9\ubd84\ud788 \ud765\ubbf8\ub86d\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \ub3d9\ubb3c\uc758 \ubaa8\uc591\uc744 \uc54c\uc544\ubcfc \uc218 \uc788\ub2e4\uace0 \uadf8 \uc704\uc758 \uae30\ud638\uae4c\uc9c0 \uc77d\uc740 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc778\ub354\uc2a4 \ubb38\uc790\ub294 \uc544\uc9c1 \ud574\ub3c5\ub418\uc9c0 \uc54a\uc558\ub2e4. \uc9e7\uc740 \ud45c\uc2dc\ub4e4\uc774 \uc5b4\ub5a4 \uc5b8\uc5b4\ub97c \ub2f4\uc558\ub294\uc9c0, \ubaa8\ub4e0 \uae30\ud638\uac00 \ubb34\uc5c7\uc744 \ub73b\ud588\ub294\uc9c0\ub294 \ud569\uc758\ub41c \ud574\ub2f5\uc774 \uc5c6\ub2e4. \uc775\uc219\ud55c \ubb38\uc790\ucc98\ub7fc \uc18c\ub9ac\ub97c \ubd99\uc5ec \uc77d\uc744 \uc218 \uc5c6\ub294 \uc0c1\ud0dc\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc544\ubb34\uac83\ub3c4 \uc5f0\uad6c\ud560 \uc218 \uc5c6\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uae30\ud638\uc758 \ubc18\ubcf5\uacfc \ubc30\uc5f4, \ubc1c\uacac\ub41c \uc7a5\uc18c\ub97c \ube44\uad50\ud560 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uaddc\uce59\uc744 \ucc3e\uc558\ub2e4\ub294 \ub9d0\uacfc \ubc88\uc5ed\uc5d0 \uc131\uacf5\ud588\ub2e4\ub294 \ub9d0\uc740 \ub2e4\ub974\ub2e4. \ubbf8\uc9c0\uc758 \uc790\ub8cc\uc5d0\uc11c \ud765\ubbf8\ub85c\uc6b4 \ud328\ud134\uc774 \ubcf4\uc77c\uc218\ub85d \uadf8 \ucc28\uc774\ub97c \uc9c0\ud0a4\ub294 \uc77c\uc774 \uc911\uc694\ud574\uc9c4\ub2e4. \uc655\uc758 \uc774\ub984\uc774 \uc801\ud78c \uae34 \uae30\ub85d\uc744 \uc77d\uc744 \uc218 \uc5c6\ub294 \uc0c1\ud669\uc5d0\uc11c\ub294 \uac74\ubb3c\uacfc \ub3c4\uad6c, \uc778\uc7a5 \uac19\uc740 \ubb3c\uac74\uc758 \ube44\uc911\uc774 \ucee4\uc9c4\ub2e4. \ub3c4\uc2dc\uc758 \uc8fc\ubbfc\uc774 \uae00\uc744 \ub0a8\uae30\uc9c0 \uc54a\uc558\ub2e4\ub294 \ub9d0\ubcf4\ub2e4\ub294 \uadf8\ub4e4\uc774 \ub0a8\uae34 \uae30\ud638\ub97c \uc6b0\ub9ac\uac00 \uc544\uc9c1 \uc77d\uc9c0 \ubabb\ud55c\ub2e4\uace0 \ud45c\ud604\ud558\ub294 \ud3b8\uc774 \uc815\ud655\ud558\ub2e4. \uce68\ubb35\uc740 \ub54c\ub85c \uc790\ub8cc\ubcf4\ub2e4 \ub3c5\uc790\uc758 \ub2a5\ub825\uc5d0 \uc788\ub2e4. \ud558\ub77c\ud30c\ub97c \uc774\ud574\ud558\ub294 \uc77c\uc740 \ud769\uc5b4\uc9c4 \ub2e8\uc11c\ub97c \ud568\uaed8 \ub193\ub294 \uacfc\uc815\uc774\ub2e4. \uac70\ub9ac\uc758 \ubc30\uce58\uc640 \uc0dd\uc0b0\uc758 \ud754\uc801, \uba3c \uacf3\uc5d0\uc11c \ub098\uc628 \ubb3c\uac74\uc774 \uc11c\ub85c\ub97c \ubcf4\uc644\ud55c\ub2e4. \uc5b4\ub290 \ud55c \uc885\ub958\uc758 \uc720\ubb3c\ub9cc\uc73c\ub85c \uc0ac\ud68c \uc804\uccb4\ub97c \ub2e4 \uc124\uba85\ud558\uc9c0 \uc54a\uc544\ub3c4 \ub41c\ub2e4. \uc9c8\ubb38\uc744 \uc5ec\ub7ec \uc790\ub8cc\uc5d0 \ub098\ub204\uc5b4 \ubb3b\ub294 \ubc29\uc2dd\uc774 \ud544\uc694\ud55c \uac83\uc774\ub2e4. \ud070 \ub3c4\uc2dc\uc758 \uc774\uc57c\uae30\ub97c \uc791\uc740 \uc778\uc7a5\uc73c\ub85c \uc2dc\uc791\ud558\uba74 \uc2dc\uc120\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uc774\ub984\ub09c \ud1b5\uce58\uc790\uc758 \uc5c5\uc801\ubcf4\ub2e4 \ubb3c\uac74\uc744 \ub9cc\ub4e4\uace0 \ud45c\uc2dc\ud558\uace0 \uc6b4\ubc18\ud55c \uc0ac\ub78c\ub4e4\uc774 \ub5a0\uc624\ub978\ub2e4. \uc544\uc9c1 \uc77d\uc9c0 \ubabb\ud55c \uae30\ud638 \uc606\uc5d0\ub3c4 \ud655\uc2e4\ud788 \uad00\ucc30\ud560 \uc218 \uc788\ub294 \ub3cc\uc758 \ubaa8\uc591\uacfc \uc790\uad6d, \ubc1c\uacac \uc7a5\uc18c\uc758 \uc5f0\uacb0\uc774 \uc788\ub2e4. \ub2e4\uc74c\uc5d0 \ubc15\ubb3c\uad00\uc5d0\uc11c \uc791\uc740 \ud45c\uc9c0\uac00 \ubd99\uc740 \uc778\uc7a5\uc744 \ub9cc\ub098\uba74 \uc7a0\uae50 \uba48\ucdb0 \ubcf4\uc790. \ubb34\uc5c7\uc744 \uc0c8\uacbc\ub294\uc9c0\uc640 \uc5b4\ub514\uc5d0\uc11c \ub098\uc654\ub294\uc9c0\ub97c \ud568\uaed8 \uc77d\uc73c\uba74 \uc88b\ub2e4. \ud558\ub77c\ud30c\uc758 \uc791\uc740 \uc778\uc7a5\uc740 \uc54c\uc544\ub0b8 \uac83\uacfc \ub0a8\uc740 \uc218\uc218\uaed8\ub07c\ub97c \ub098\ub780\ud788 \ub193\uc744 \ub54c \uc624\ub798\ub41c \ub3c4\uc2dc\uc758 \uc138\uacc4\uac00 \ub354 \ub113\uc5b4\uc9c4\ub2e4\ub294 \uac83\uc744 \ubcf4\uc5ec \uc900\ub2e4."}, {"id": "isfahan-square-and-everyday-life", "title": "\uc774\uc2a4\ud30c\ud55c \u2014 \uad11\uc7a5\uc5d0\uc11c\ub294 \uc7a5\uc0ac\ub3c4 \ud558\uace0 \uacf5\ub3c4 \ucce4\ub2e4", "summary": "\ub098\ud06c\uc170 \uc790\ud55c \uad11\uc7a5\uc5d0\uc11c \ud1b5\uce58\u00b7\uad50\uc5ed\u00b7\uc758\ub840\uc640 \uc77c\uc0c1\uc774 \ud568\uaed8 \ub9cc\ub098\ub294 \ubc29\uc2dd\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "cities", "category_title": "Cities", "subcategory": "Middle East", "url": "stories/isfahan-square-and-everyday-life/index.html", "image": "media/isfahan-square-and-everyday-life.jpg", "alt": "\uc774\uc2a4\ud30c\ud55c \ub098\ud06c\uc170 \uc790\ud55c \uad11\uc7a5\uc758 \uc815\uc6d0 \ub108\uba38 \uc0e4 \ubaa8\uc2a4\ud06c\ub97c \ubc14\ub77c\ubcf8 \uc0ac\uc9c4.", "text": "\uc774\uc2a4\ud30c\ud55c \u2014 \uad11\uc7a5\uc5d0\uc11c\ub294 \uc7a5\uc0ac\ub3c4 \ud558\uace0 \uacf5\ub3c4 \ucce4\ub2e4 \uad81\uc804\uacfc \ubaa8\uc2a4\ud06c \uc0ac\uc774\uc5d0 \ud3bc\uccd0\uc9c4 \ub3c4\uc2dc\uc758 \ubb34\ub300 \ub098\ud06c\uc170 \uc790\ud55c \uad11\uc7a5\uc5d0\uc11c \ud1b5\uce58\u00b7\uad50\uc5ed\u00b7\uc758\ub840\uc640 \uc77c\uc0c1\uc774 \ud568\uaed8 \ub9cc\ub098\ub294 \ubc29\uc2dd\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Middle East \ub3c4\uc2dc \ucee4\ub2e4\ub780 \uad11\uc7a5\uc744 \ubcf4\uba74 \ub113\uace0 \ube44\uc5b4 \uc788\ub294 \ubc14\ub2e5\ubd80\ud130 \ubcf4\uac8c \ub41c\ub2e4. \ud558\uc9c0\ub9cc \ube44\uc5b4 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ud560 \uc77c\uc774 \uc5c6\uc5c8\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \uc7a5\uc744 \uc5f4\uace0 \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc774\uace0, \uc5b4\ub5a4 \ub0a0\uc5d0\ub294 \ub9d0\uc744 \ud0c0\uace0 \uacf5\uc744 \uce58\ub294 \uacbd\uae30\uac00 \ubc8c\uc5b4\uc9c8 \uc218\ub3c4 \uc788\ub2e4. \uacf5\uac04\uc744 \ube44\uc6cc \ub450\uc5c8\uae30\uc5d0 \uc5ec\ub7ec \uc77c\uc774 \ub4e4\uc5b4\uc628\ub2e4. \uc774\ub780 \uc774\uc2a4\ud30c\ud55c\uc758 \ub098\ud06c\uc170 \uc790\ud55c \uad11\uc7a5\uc740 \uc774\ub7f0 \uc0dd\uac01\uc73c\ub85c \ubcf4\uae30 \uc88b\uc740 \uc7a5\uc18c\ub2e4. \uc8fc\ubcc0\uc5d0\ub294 \uad81\uc815\uc758 \uacf5\uac04\uacfc \ubaa8\uc2a4\ud06c, \uc2dc\uc7a5\uc774 \uc5f0\uacb0\ub418\uc5c8\ub2e4. \uac74\ubb3c \ud558\ub098\uc529\uc758 \uc544\ub984\ub2e4\uc6c0\ub3c4 \uc911\uc694\ud558\uc9c0\ub9cc \uadf8 \uc0ac\uc774\uc758 \ud070 \uc5f4\ub9b0 \uc790\ub9ac\uac00 \ubb34\uc5c7\uc744 \uac00\ub2a5\ud558\uac8c \ud588\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uc0ac\ud30c\ube44 \uc655\uc870\uc758 \uc544\ubc14\uc2a4 1\uc138\ub294 1598\ub144 \uc218\ub3c4\ub97c \uce74\uc988\ube48\uc5d0\uc11c \uc774\uc2a4\ud30c\ud55c\uc73c\ub85c \uc62e\uacbc\ub2e4. \uad50\uc7ac\ub294 \uc774 \uc704\uce58\uac00 \ubd88\uc548\uc815\ud55c \uad6d\uacbd\uc5d0\uc11c \ub354 \uba40\uace0 \ud398\ub974\uc2dc\uc544\ub9cc\uacfc \uc0c8\ub85c\uc6b4 \uad50\uc5ed \uc0c1\ub300\uc5d0\uac8c \ub354 \uac00\uae4c\uc6e0\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc218\ub3c4\ub294 \ubcf4\uae30 \uc88b\uc740 \uc7a5\uc18c\ub97c \uace0\ub974\ub294 \ubb38\uc81c\ub9cc\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ud1b5\uce58\uc758 \uc548\uc815\uacfc \ubb3c\uc790\uc758 \uc774\ub3d9, \ub2e4\ub978 \uc9c0\uc5ed\uacfc\uc758 \uad00\uacc4\uac00 \ud568\uaed8 \uace0\ub824\ub41c\ub2e4. \uc0c8 \uc218\ub3c4\ub97c \ub9cc\ub4e0\ub2e4\ub294 \uac83\uc740 \uac74\ubb3c\uc744 \uc62e\uae30\ub294 \uc77c\ubfd0 \uc544\ub2c8\ub77c \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub5a4 \ubc29\ud5a5\uc73c\ub85c \ubaa8\uc774\uace0 \uc790\uc6d0\uc774 \uc5b4\ub514\uc5d0 \uc9d1\uc911\ub420\uc9c0\ub97c \ubc14\uafb8\ub294 \uc120\ud0dd\uc774\ub2e4. \uc774\uc2a4\ud30c\ud55c\uc758 \ud070 \uacf5\uac04\uc5d0\ub294 \uadf8\ub7f0 \uc815\uce58\uc801 \uad6c\uc0c1\uc774 \ub4e4\uc5b4 \uc788\uc5c8\ub2e4. \ub098\ud06c\uc170 \uc790\ud55c \uad11\uc7a5 \uc8fc\ubcc0\uc5d0\ub294 \ud589\uc815 \uacf5\uac04\uacfc \uacf5\uacf5 \uc2dc\uc7a5\uc774 \uc5f4\ub824 \uc788\uc5c8\ub2e4. \uc655\uc2e4\uc758 \uacf5\uac04\uc740 \uad11\uc7a5\uc744 \ub0b4\ub824\ub2e4\ubcf4\uc558\uace0, \ub0a8\ucabd\uc5d0\ub294 \uc0e4 \ubaa8\uc2a4\ud06c\uac00 \uc790\ub9ac\ud588\ub2e4. \uc885\uad50\uc640 \uad8c\ub825, \uac70\ub798\uc758 \uc7a5\uc18c\uac00 \ud070 \uc5f4\ub9b0 \uacf5\uac04\uc744 \ud568\uaed8 \ub9c8\uc8fc\ud55c \uac83\uc774\ub2e4. \uac01 \uac74\ubb3c\uc744 \ub530\ub85c \uac10\uc0c1\ud560 \ub54c\ub294 \ub2e4\ub978 \uae30\ub2a5\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \uadf8\ub7ec\ub098 \uad11\uc7a5\uc5d0\uc11c \ubc14\ub77c\ubcf4\uba74 \uac19\uc740 \ub3c4\uc2dc\uc758 \uc911\uc2ec\uc744 \ub9cc\ub4dc\ub294 \uc694\uc18c\ub4e4\uc774 \ub41c\ub2e4. \ub204\uad6c\ub97c \ud5a5\ud574 \uc785\uad6c\uac00 \uc5f4\ub9ac\uace0 \uc5b4\ub290 \uacf3\uc5d0\uc11c \uc0ac\ub78c\ub4e4\uc774 \uc11c\ub85c\ub97c \ubcfc \uc218 \uc788\uc5c8\ub294\uc9c0 \uc0dd\uac01\ud558\uba74 \uacf5\uac04\uc758 \ubc30\uce58\uac00 \uc774\uc57c\uae30\ub97c \uc2dc\uc791\ud55c\ub2e4. \uad50\uc7ac\ub294 \uc774 \uc911\uc2ec\uc5d0\uc11c \uad81\uc815 \uc0ac\ub78c\uacfc \uc131\uc9c1\uc790, \uc678\uad6d \uc0ac\uc808\uacfc \uad70\uc778, \uc0c1\uc778\uacfc \uc77c\ubc18 \uc8fc\ubbfc\uc774 \uc11e\uc77c \uc218 \uc788\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc2e0\ubd84\uc774 \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uc774 \uac19\uc740 \uc7a5\uc18c\uc5d0 \uc788\uc5c8\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \uadf8\ub807\ub2e4\uace0 \uadf8\ub4e4\uc774 \ubaa8\ub450 \uac19\uc740 \uad8c\ud55c\uc744 \uac00\uc84c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uad11\uc7a5\uc758 \uac1c\ubc29\uc131\uacfc \uc0ac\ud68c\uc758 \ud3c9\ub4f1\uc740 \ub2e4\ub978 \uc9c8\ubb38\uc774\ub2e4. \ub204\uad70\uac00\ub294 \ud589\uc0ac\ub97c \uc9c0\ucf1c\ubcf4\uace0 \ub204\uad70\uac00\ub294 \ud1b5\uce58\uc790\uc758 \uc704\uc138\ub97c \ubcf4\uc600\uc744 \uc218 \uc788\ub2e4. \ud55c \uacf5\uac04\uc744 \ud568\uaed8 \uc4f4\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uadf8 \uc548\uc5d0\uc11c \ucc28\uc9c0\ud55c \uc790\ub9ac\ub294 \uad6c\ubcc4\ud574 \ubcfc \uc218 \uc788\ub2e4. \ub3c4\uc2dc\uc758 \uc911\uc2ec\uc740 \ub9cc\ub0a8\uc758 \uc790\ub9ac\uc774\uba74\uc11c \ucc28\uc774\uac00 \ub4dc\ub7ec\ub098\ub294 \uc790\ub9ac\uc774\uae30\ub3c4 \ud558\ub2e4. \uad11\uc7a5\uc740 \ub54c\ub54c\ub85c \ud3f4\ub85c \uacbd\uae30\uc640 \uacf5\uc801 \uc758\ub840, \ucd95\uc81c\ub97c \uc704\ud574 \ube44\uc6cc\uc84c\ub2e4. \ud3c9\uc18c\uc758 \uc774\ub3d9\uacfc \uac70\ub798\uac00 \ub2e4\ub978 \ud589\uc0ac\ub97c \uc704\ud55c \uacf5\uac04\uc73c\ub85c \ubc14\ub010 \uac83\uc774\ub2e4. \ub113\uc740 \uc7a5\uc18c\ub97c \ud55c \uac00\uc9c0 \uc6a9\ub3c4\uc758 \uc0c1\uc790\ucc98\ub7fc\ub9cc \uc0dd\uac01\ud558\uba74 \uc774\ub7f0 \ubcc0\ud654\ub294 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uc0ac\uc9c4\uc5d0\ub294 \ub2f9\uc2dc\uc758 \uacbd\uae30 \uc7a5\uba74\uc774 \ub2f4\uaca8 \uc788\uc9c0 \uc54a\ub2e4. \uadf8\ub798\uc11c \ud2b9\uc815 \uc120\uc218\uac00 \uc5b4\ub514\uc5d0\uc11c \ub2ec\ub838\ub294\uc9c0 \uc0c1\uc0c1\uc73c\ub85c \uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \uad11\uc7a5\uc758 \uae38\uc774\uc640 \uc5f4\ub9b0 \ud3ed\uc744 \ubcf4\uba70 \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc774\uace0 \uc6c0\uc9c1\uc774\ub294 \ud589\uc0ac\uc5d0 \uc5b4\ub5a4 \uc870\uac74\uc744 \uc8fc\uc5c8\uc744\uc9c0 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uac74\ubb3c \uc0ac\uc774\uc758 \ube48 \uacf5\uac04\ub3c4 \ub3c4\uc2dc\uc758 \uc911\uc694\ud55c \uc2dc\uc124\uc774\uc5c8\ub2e4. \uc774\uc2a4\ud30c\ud55c\uc5d0\ub294 \ucc28\ud558\ub974 \ubc14\uadf8\ub77c\ub294 \ub113\uc740 \uac00\ub85c\uc640 \uad81\uc804, \uc815\uc6d0\ub3c4 \uc870\uc131\ub418\uc5c8\ub2e4. \uad50\uc7ac\ub294 \ub098\ubb34\uc758 \uadf8\ub298\uacfc \uacfc\uc77c\ub098\ubb34, \ubd84\uc218\uc640 \ud750\ub974\ub294 \ubb3c\uc744 \ud568\uaed8 \uc124\uba85\ud55c\ub2e4. \ub3c4\uc2dc\ub294 \ub192\uc740 \ub3d4\uacfc \uc7a5\uc2dd\ub9cc\uc73c\ub85c \uafb8\uba70\uc9c4 \uac83\uc774 \uc544\ub2c8\ub77c \uc18c\ub9ac\uc640 \ubc14\ub78c, \ub0c4\uc0c8\ub97c \uacbd\ud5d8\ud558\ub294 \uacf5\uac04\uc73c\ub85c\ub3c4 \ub9cc\ub4e4\uc5b4\uc84c\ub2e4. \ubb3c\uc774 \ud750\ub974\uace0 \ub098\ubb47\uc78e\uc774 \ud754\ub4e4\ub9ac\ub294 \uc870\uac74\uc740 \uac74\ucd95\uc758 \ud06c\uae30\uc640 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \uc0ac\ub78c\uc758 \ubab8\uc5d0 \ub2ff\ub294\ub2e4. \ub3c4\uc2dc\ub97c \ubcf8\ub2e4\ub294 \ub9d0\uc744 \uc7a0\uc2dc \ub113\ud788\uba74 \uac77\uace0 \uc26c\uace0 \ub4e3\ub294 \uc77c\ub3c4 \ud3ec\ud568\ub41c\ub2e4. \uc544\ub984\ub2e4\uc6b4 \uc218\ub3c4\ub77c\ub294 \ud45c\ud604\uc774 \uc0ac\uc9c4\uc758 \uc678\uad00\ub9cc\uc744 \ub73b\ud558\uc9c0 \uc54a\uc558\uc74c\uc744 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uc544\ubc14\uc2a4\ub294 \uc0c8 \uc218\ub3c4\ub97c \ucc44\uc6b0\uae30 \uc704\ud574 \uc5ec\ub7ec \uacf5\ub3d9\uccb4\ub97c \uc774\uc8fc\uc2dc\ucf30\ub2e4. \uadf8\uc911\uc5d0\ub294 \uc804\uc7c1 \uacfc\uc815\uc5d0\uc11c \uace0\ud5a5\uc744 \ub5a0\ub098\uc57c \ud588\ub358 \uc544\ub974\uba54\ub2c8\uc544\uc778\uacfc \uce85\uce74\uc2a4 \uc9c0\uc5ed \uc0ac\ub78c\ub4e4\ub3c4 \uc788\uc5c8\ub2e4. \ub3c4\uc2dc\uac00 \ub2e4\ucc44\ub85c\uc6cc\uc84c\ub2e4\ub294 \uacb0\uacfc\ub97c \ubaa8\ub450\uc758 \uc790\uc720\ub85c\uc6b4 \uc5ec\ud589\uc73c\ub85c \uadf8\ub9b4 \uc218\ub294 \uc5c6\ub2e4. \uc544\ub974\uba54\ub2c8\uc544 \uae30\ub3c5\uad50 \uacf5\ub3d9\uccb4\uc758 \uc885\uad50 \uacf5\uac04\uacfc \uacbd\uc81c \ud65c\ub3d9\ub3c4 \uc774 \ub3c4\uc2dc\uc758 \uc77c\ubd80\uac00 \ub418\uc5c8\ub2e4. \uad50\uc7ac\ub294 \uc2e4\ud06c \uc81c\uc870\uc640 \uc218\ucd9c\uc5d0 \ucc38\uc5ec\ud55c \uc0ac\ub78c\ub4e4\uc758 \uc5ed\ud560\uc744 \uc124\uba85\ud55c\ub2e4. \ub2e4\ub978 \uc2e0\uc559\uc744 \ubc1b\uc544\ub4e4\uc778 \ub3c4\uc2dc\uc758 \ubaa8\uc2b5\uacfc \ud1b5\uce58\uc790\uac00 \uc0ac\ub78c\uc744 \uc774\ub3d9\uc2dc\ud0a8 \uad8c\ub825\uc740 \uac19\uc740 \uc5ed\uc0ac \uc548\uc5d0 \ud568\uaed8 \uc788\uc5c8\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc2e4\uc81c \uc0ac\uc9c4\uc5d0\uc11c\ub294 \uba3c\uc800 \uad11\uc7a5\uc758 \ub113\uc740 \uc790\ub9ac\uc640 \uadf8 \ub4a4\uc758 \uc0e4 \ubaa8\uc2a4\ud06c\ub97c \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uc774\uc5b4 \uc0ac\ub78c\uc758 \ud06c\uae30\uc640 \uac74\ubb3c\uc758 \ub192\uc774\ub97c \ube44\uad50\ud574 \ubcf4\uc790. \ud070 \uc7a5\uc2dd\uc758 \uc138\ubd80\ub97c \ub2e4 \uc54c\uc9c0 \ubabb\ud574\ub3c4 \uc911\uc2ec \uacf5\uac04\uc758 \uaddc\ubaa8\uc640 \ubc29\ud5a5\uc740 \ub290\ub084 \uc218 \uc788\ub2e4. \uc774 \uc0ac\uc9c4\uc774 \ub2f9\uc2dc\uc758 \ud589\uc0ac\ub97c \uadf8\ub300\ub85c \ubcf4\uc5ec \uc8fc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud604\uc7ac\uae4c\uc9c0 \ub0a8\uc740 \uacf5\uac04\uc5d0\uc11c \uacfc\uac70\uc758 \uae30\ub2a5\uc744 \uc790\ub8cc\uc640 \ud568\uaed8 \uc77d\ub294 \uac83\uc774\ub2e4. \uad50\uc7ac\uac00 \uc124\uba85\ud55c \uc2dc\uc7a5\uacfc \uc758\ub840, \ud3f4\ub85c\ub97c \ub5a0\uc62c\ub9ac\uba74 \uc0ac\uc9c4 \uc18d \ube44\uc5b4 \ubcf4\uc774\ub294 \uc790\ub9ac\uc5d0\ub3c4 \uc11c\ub85c \ub2e4\ub978 \uc2dc\uac04\uc758 \uc4f0\uc784\uc774 \ub193\uc778\ub2e4. \uc774\uc2a4\ud30c\ud55c\uc758 \uad11\uc7a5\uc740 \ub2e8\uc21c\ud788 \uba4b\uc9c4 \uac74\ubb3c\uc744 \uac10\uc0c1\ud560 \ubc30\uacbd\uc774 \uc544\ub2c8\ub2e4. \uad8c\ub825\uacfc \uad50\uc5ed, \uc2e0\uc559\uacfc \uc77c\uc0c1\uc774 \ub9cc\ub098\ub294 \ubb34\ub300\uc600\ub2e4. \uac19\uc740 \ubc14\ub2e5\uc774 \ub2e4\ub978 \ub0a0\uc5d0\ub294 \ub2e4\ub978 \uc5ed\ud560\uc744 \ud560 \uc218 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ub3c4\uc2dc\ub97c \uc0b4\uc544 \uc788\ub294 \uacf5\uac04\uc73c\ub85c \ubcf4\uac8c \ud55c\ub2e4. \ub2e4\uc74c\uc5d0 \ud070 \uad11\uc7a5\uc744 \uac78\uc744 \ub54c \ubb34\uc5c7\uc744 \uc138\uc6cc \ub193\uc558\ub294\uc9c0\ub9cc \ubcf4\uc9c0 \ub9d0\uace0 \ubb34\uc5c7\uc744 \uc704\ud574 \ube44\uc6cc \ub450\uc5c8\ub294\uc9c0\ub3c4 \uc0b4\ud3b4\ubcf4\uc790. \uc774\uc2a4\ud30c\ud55c\uc758 \uc5f4\ub9b0 \uc911\uc2ec\uc740 \uc0ac\ub78c\uc774 \ubaa8\uc774\uace0 \uad8c\uc704\uac00 \ubcf4\uc774\uba70 \ud589\uc0ac\uac00 \ud3bc\uccd0\uc9c0\ub294 \ubc29\uc2dd\uc744 \ud568\uaed8 \uc124\uacc4\ud55c \uc7a5\uc18c\uc600\ub2e4."}, {"id": "istanbul-hagia-sophia-many-times", "title": "\uc544\uc57c \uc18c\ud53c\uc544 \u2014 \ud070 \uc9c0\ubd95 \uc544\ub798 \uc5ec\ub7ec \uc2dc\ub300\uac00 \uba38\ubb3c\ub2e4", "summary": "19\uc138\uae30 \ub3c4\ud310\uc758 \ub3d4\uacfc \ucca8\ud0d1\uc744 \ub530\ub77c \uc544\uc57c \uc18c\ud53c\uc544\uc640 \uc774\uc2a4\ud0c4\ubd88\uc5d0 \uacb9\uce5c \uc2dc\ub300\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "cities", "category_title": "Cities", "subcategory": "Europe", "url": "stories/istanbul-hagia-sophia-many-times/index.html", "image": "media/istanbul-hagia-sophia-many-times.jpg", "alt": "\uc544\uc57c \uc18c\ud53c\uc544\uc758 \ud070 \uc911\uc559 \ub3d4\uacfc \ub0ae\uc740 \uc9c0\ubd95, \ucca8\ud0d1\uacfc \uac70\ub9ac\uc758 \uc0ac\ub78c\ub4e4\uc744 \ud45c\ud604\ud55c 1857\ub144 \uc5ed\uc0ac \ub3c4\ud310.", "text": "\uc544\uc57c \uc18c\ud53c\uc544 \u2014 \ud070 \uc9c0\ubd95 \uc544\ub798 \uc5ec\ub7ec \uc2dc\ub300\uac00 \uba38\ubb3c\ub2e4 \uc624\ub798\ub41c \uac74\ubb3c\uc740 \ud55c \ubc88\uc5d0 \uc644\uc131\ub41c \ubaa8\uc2b5\uc73c\ub85c \ub0a8\uc9c0 \uc54a\ub294\ub2e4 19\uc138\uae30 \ub3c4\ud310\uc758 \ub3d4\uacfc \ucca8\ud0d1\uc744 \ub530\ub77c \uc544\uc57c \uc18c\ud53c\uc544\uc640 \uc774\uc2a4\ud0c4\ubd88\uc5d0 \uacb9\uce5c \uc2dc\ub300\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Europe \ub3c4\uc2dc \uc774\uc2a4\ud0c4\ubd88\uc758 \uc624\ub798\ub41c \ud48d\uacbd\uc5d0\uc11c \uc544\uc57c \uc18c\ud53c\uc544\ub97c \ucc3e\uc744 \ub54c\ub294 \ud070 \ub3d4\uc744 \uba3c\uc800 \ubcf4\uac8c \ub41c\ub2e4. \uadf8 \uc606\uc73c\ub85c\ub294 \uac00\ub298\uace0 \ub192\uc740 \ucca8\ud0d1\ub4e4\uc774 \uc19f\uc544 \uc788\ub2e4. \ub0ae\uace0 \ub113\uc740 \uc9c0\ubd95\uacfc \uace7\uac8c \ubed7\uc740 \uc120\uc774 \ud55c\ub370 \uc788\uc73c\ub2c8 \ucc98\uc74c\ubd80\ud130 \uc774\ub7f0 \ubaa8\uc2b5\uc73c\ub85c \uc124\uacc4\ub418\uc5c8\uc744 \uac83 \uac19\ub2e4. \uadf8\ub7ec\ub098 \uc774 \uac74\ubb3c\uc744 \ud55c \ubc88\uc5d0 \ub9cc\ub4e0 \uc791\ud488\ucc98\ub7fc \uc0dd\uac01\ud558\uba74 \uc911\uc694\ud55c \uc774\uc57c\uae30\ub97c \ub193\uce5c\ub2e4. \ube44\uc794\ud2f4 \ud669\uc81c\uc758 \ub3c4\uc2dc\uc640 \uc624\uc2a4\ub9cc \uc220\ud0c4\uc758 \ub3c4\uc2dc\uac00 \uac19\uc740 \uc7a5\uc18c\uc5d0 \uacb9\uccd0 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 1857\ub144 \ub3c4\ud310\uc744 \ucc9c\ucc9c\ud788 \ubcf4\uba74 \uac74\ubb3c \ud558\ub098\uac00 \uc2dc\uac04\uc744 \ubcf4\uad00\ud558\ub294 \ubc29\uc2dd\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \uc544\uc57c \uc18c\ud53c\uc544\ub294 \uc131\uc2a4\ub7ec\uc6b4 \uc9c0\ud61c\ub97c \ub73b\ud558\ub294 \uc774\ub984\uc774\ub2e4. \uc18c\ud53c\uc544\ub77c\ub294 \uc778\ubb3c\uc5d0\uac8c \ubc14\uce5c \uac74\ubb3c\ub85c\ub9cc \uc774\ud574\ud558\uba74 \uc774\ub984\uc758 \ub73b\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uae30\ub3c5\uad50 \uc2e0\uc559\uc758 \uacf5\uac04\uc73c\ub85c \uc138\uc6cc\uc9c4 \uc774 \uac74\ubb3c\uc5d0\ub294 \ub2f9\uc2dc \ud1b5\uce58\uc790\uac00 \ud45c\ud604\ud558\ub824 \ud588\ub358 \uc885\uad50\uc801 \uad8c\uc704\ub3c4 \ub2f4\uaca8 \uc788\uc5c8\ub2e4. 6\uc138\uae30 \ud669\uc81c \uc720\uc2a4\ud2f0\ub2c8\uc544\ub204\uc2a4\ub294 \uc5ec\ub7ec \uad50\ud68c \uac74\uc124\uc744 \ud6c4\uc6d0\ud588\ub2e4. \uc544\uc57c \uc18c\ud53c\uc544\ub294 \uadf8 \uac00\uc6b4\ub370 \ud2b9\ud788 \uc911\uc694\ud55c \uac74\ubb3c\uc774\uc5c8\ub2e4. \uadf8\ub54c \ub3c4\uc2dc\uc758 \uc774\ub984\uc740 \ucf58\uc2a4\ud0c4\ud2f0\ub178\ud3f4\ub9ac\uc2a4\uc600\ub2e4. \uc624\ub298\ub0a0 \uc774\uc2a4\ud0c4\ubd88\uc5d0\uc11c \ub9cc\ub098\ub294 \uba85\uc18c\ub294 \uc624\ub798\uc804\ubd80\ud130 \uc9c0\uae08\uacfc \ub611\uac19\uc740 \uc774\ub984\uacfc \uc5ed\ud560\uc744 \uac00\uc84c\ub358 \uc7a5\uc18c\uac00 \uc544\ub2c8\ub2e4. \uad50\uc7ac\ub294 \uc544\uc57c \uc18c\ud53c\uc544\uac00 \ud669\uc81c\uc758 \uac70\ucc98\uc640 \ud788\ud3ec\ub4dc\ub86c \uac00\uae4c\uc774\uc5d0 \uc788\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud788\ud3ec\ub4dc\ub86c\uc740 \ub9d0\uacfc \uc804\ucc28 \uacbd\uc8fc\ub97c \ud558\ub294 \uacbd\uae30\uc7a5\uc774\ub2e4. \uc2e0\uc559\uc758 \uacf5\uac04, \ud1b5\uce58\uc758 \uc790\ub9ac, \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc774\ub294 \ud070 \ud589\uc0ac\uac00 \ub3c4\uc2dc \uc911\uc2ec\uc5d0\uc11c \uac00\uae4c\uc774 \ub193\uc5ec \uc788\uc5c8\ub358 \uc148\uc774\ub2e4. \uc774 \ubc30\uce58\ub97c \ub5a0\uc62c\ub9ac\uba74 \uad50\ud68c\ub97c \uadf8\uc800 \uc870\uc6a9\ud788 \uae30\ub3c4\ud558\ub294 \uac74\ubb3c\ub85c\ub9cc \ubcf4\uae30 \uc5b4\ub835\ub2e4. \ud669\uc81c\uc758 \uad8c\uc704\uc640 \uc2dc\ubbfc \uc55e\uc5d0 \ubaa8\uc2b5\uc744 \ub4dc\ub7ec\ub0b4\ub294 \ubc29\uc2dd\uc774 \uc885\uad50 \uacf5\uac04\uacfc \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub2e4. \uac74\ubb3c \uc548\uc758 \uc7a5\uc2dd\ub9cc \ubcf4\ub294 \ub300\uc2e0 \uc8fc\ubcc0\uc5d0 \ubb34\uc5c7\uc774 \uc788\uc5c8\ub294\uc9c0 \ubb3c\uc5b4\ubcf4\uba74 \ub3c4\uc2dc \uc18d \uc704\uce58\uac00 \uc774\uc57c\uae30\ub97c \ub354\ud574 \uc900\ub2e4. \uc790\ub8cc\uac00 \uc18c\uac1c\ud558\ub294 \uc911\uc2ec \ub3d4\uc758 \uc9c0\ub984\uc740 105\ud53c\ud2b8, \uc57d 32\ubbf8\ud130\ub2e4. \uc22b\uc790\ub97c \uc815\ud655\ud788 \uc0c1\uc0c1\ud558\uae30 \uc5b4\ub835\ub354\ub77c\ub3c4 \uc77c\ubc18\uc801\uc778 \ubc29\uc758 \ucc9c\uc7a5\ubcf4\ub2e4 \ud6e8\uc52c \ub113\uc740 \uacf5\uac04\uc744 \ub36e\ub294 \uaddc\ubaa8\ub77c\ub294 \uac83\uc740 \uc54c \uc218 \uc788\ub2e4. \ub3c4\ud310\uc5d0\uc11c\ub3c4 \uc911\uc559\uc758 \ub192\uc740 \uace1\uba74 \uc544\ub798\ub85c \ub354 \ub0ae\uc740 \uc9c0\ubd95\ub4e4\uc774 \uc774\uc5b4\uc9c4\ub2e4. \ub208\uc740 \uadf8 \uc5ec\ub7ec \uce35\uc744 \ub530\ub77c \uc704\ub85c \uc62c\ub77c\uac14\ub2e4\uac00 \uc8fc\ubcc0\uc73c\ub85c \ub0b4\ub824\uc628\ub2e4. \ub192\uc740 \ud558\ub098\uc758 \ubfb0\uc871\ud55c \uaf2d\ub300\uae30\ub9cc \ubcf4\ub294 \uac83\uacfc\ub294 \ub2e4\ub978 \uac10\uc0c1\uc774\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc815\ubc00\ud55c \uad6c\uc870 \uacc4\uc0b0\ubcf4\ub2e4, \ud070 \uace1\uba74\uacfc \uc8fc\ubcc0 \ubd80\ubd84\uc774 \uc804\uccb4\uc758 \ubb34\uac8c\uac10\uc744 \uc5b4\ub5bb\uac8c \ub098\ub204\ub294\uc9c0 \ubcf4\uc544\ub3c4 \ucda9\ubd84\ud558\ub2e4. \uac74\ucd95\uc758 \uc7ac\ubbf8\ub294 \uc774\ub984\uacfc \uc5f0\ub3c4\ub97c \uc678\uc6b0\uae30 \uc804\uc5d0 \uc2dc\uc791\ub420 \uc218 \uc788\ub2e4. 1453\ub144 \uc624\uc2a4\ub9cc \uc81c\uad6d\uc774 \ucf58\uc2a4\ud0c4\ud2f0\ub178\ud3f4\ub9ac\uc2a4\ub97c \uc815\ubcf5\ud588\ub2e4. \uba54\ud750\uba54\ud2b8 2\uc138\ub294 \uc774\uacf3\uc744 \uc0c8 \uc218\ub3c4\ub85c \uc0bc\uace0 \ub3c4\uc2dc\ub97c \uc7ac\uac74\ud588\ub2e4. \uad81\uc804\uacfc \ubcd1\uc6d0, \uad50\uc721 \uacf5\uac04\uc744 \ub9c8\ub828\ud558\uba70 \uc0c8\ub85c\uc6b4 \uc81c\uad6d\uc758 \uc911\uc2ec\uc73c\ub85c \ub9cc\ub4e4\uc5b4 \uac14\ub2e4. \uc544\uc57c \uc18c\ud53c\uc544\ub3c4 \uadf8 \ubcc0\ud654 \uc548\uc5d0 \uc788\uc5c8\ub2e4. \uad50\uc7ac\ub294 \uba54\ud750\uba54\ud2b8\uac00 \uae30\uc874 \uac74\ubb3c\uc744 \ubcf4\uc874\ud558\uba74\uc11c \ubaa8\uc2a4\ud06c\ub85c \uc804\ud658\ud558\ub3c4\ub85d \ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc911\uc694\ud55c \uac74\ubb3c\uc758 \uc5ed\uc0ac\ub294 \ucca0\uac70\uc640 \uc2e0\ucd95\uc73c\ub85c\ub9cc \uc774\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \ub0a8\uaca8 \ub454 \uad6c\uc870\uc5d0 \ub2e4\ub978 \uc0ac\uc6a9\uacfc \uc0c1\uc9d5\uc774 \ub354\ud574\uc9c0\ub294 \ubc29\uc2dd\ub3c4 \uc788\ub2e4. \ubaa8\uc2a4\ud06c\uc758 \ucca8\ud0d1\uc740 \ube44\uc794\ud2f4 \uad50\ud68c\ub85c \uc138\uc6cc\uc84c\ub358 \ub54c\uc758 \ubaa8\uc2b5\uacfc \uad6c\ubcc4\ud574\uc57c \ud55c\ub2e4. \ub3c4\ud310 \uc18d\uc5d0\uc11c \ud568\uaed8 \ubcf4\uc778\ub2e4\uace0 \ubaa8\ub450 \uac19\uc740 \uc2dc\uae30\uc5d0 \ub9cc\ub4e4\uc5b4\uc84c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uac74\ubb3c\uc5d0 \uc313\uc778 \uc2dc\uac04\uc740 \ud558\ub098\uc758 \uc644\uc131\ub41c \uc724\uacfd \uc548\uc5d0 \uc11e\uc5ec \ubcf4\uc77c \uc218 \uc788\ub2e4. \uc0ac\uc9c4\uc774\ub098 \uadf8\ub9bc\uc5d0\uc11c \uc774\ub7f0 \ubd80\ubd84\uc744 \ucc3e\uc544\ubcf4\ub294 \uc77c\uc740 \ubcf5\uc7a1\ud55c \uc591\uc2dd \uc2dc\ud5d8\uc774 \uc544\ub2c8\ub2e4. \uc5b4\ub290 \ubd80\ubd84\uc774 \uc624\ub798\ub41c \uc911\uc2ec\uc774\uace0 \uc5b4\ub5a4 \uc694\uc18c\uac00 \ub098\uc911\uc758 \uc4f0\uc784\uc744 \ubcf4\uc5ec \uc8fc\ub294\uc9c0 \uc9c8\ubb38\ud558\ub294 \uac83\uc774\ub2e4. \uc804\ubd80\uc758 \uc815\ud655\ud55c \uac74\ub9bd \uc5f0\ub300\ub97c \ubaa8\ub974\ub294 \uc0c1\ud0dc\uc5d0\uc11c\ub3c4, \ud55c \uc2dc\ub300\uc758 \uc124\uacc4\ub3c4\ub85c\ub9cc \uc124\uba85\ud558\uae30 \uc5b4\ub835\ub2e4\ub294 \uc810\uc740 \ucda9\ubd84\ud788 \uc77d\uc744 \uc218 \uc788\ub2e4. \ud070 \uac74\ubb3c\uc774 \ub0a8\uc544 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub3cc\uacfc \ubcbd\ub3cc\uc774 \ub2e8\ub2e8\ud588\ub2e4\ub294 \uc124\uba85\ub9cc\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \uc0c8\ub85c\uc6b4 \uc9c0\ubc30\uc790\uac00 \uadf8 \uacf5\uac04\uc744 \uc5b4\ub5bb\uac8c \ub2e4\ub8f0\uc9c0 \uacb0\uc815\ud588\uace0, \ub2e4\ub978 \ubaa9\uc801\uc5d0 \ub9de\ucd94\uc5b4 \uc0ac\uc6a9\ud588\ub2e4. \ubb3c\ub9ac\uc801\uc778 \uad6c\uc870\uc640 \uc815\uce58\uc801 \uc120\ud0dd\uc774 \ud568\uaed8 \uac74\ubb3c\uc758 \uc0dd\uc560\ub97c \ub9cc\ub4e4\uc5c8\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc804\ud658 \uacfc\uc815\uc5d0\uc11c \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \uac19\uc740 \uac10\uc815\uc744 \ub290\uaf08\uc73c\ub9ac\ub77c\uace0 \uc0dd\uac01\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub204\uad70\uac00\uc5d0\uac8c \uad8c\uc704\uc758 \uacc4\uc2b9\uc774\uc5c8\ub358 \ubcc0\ud654\ub294 \ub2e4\ub978 \ub204\uad70\uac00\uc5d0\uac8c \uc0c1\uc2e4\uc774\uc5c8\uc744 \uc218 \uc788\ub2e4. \ud55c \uac74\ubb3c\uc5d0 \uc5ec\ub7ec \uacf5\ub3d9\uccb4\uc758 \uae30\uc5b5\uc774 \ubd99\uc5b4 \uc788\ub2e4\ub294 \uc810\uc744 \uc778\uc815\ud558\uba74, \uc544\ub984\ub2f5\ub2e4\ub294 \uac10\uc0c1 \uc606\uc5d0 \uc5ed\uc0ac\uc758 \ubcf5\uc7a1\ud568\ub3c4 \ub193\uc744 \uc790\ub9ac\uac00 \uc0dd\uae34\ub2e4. 1857\ub144 \ub3c4\ud310\uc758 \uc544\ub798\ucabd\uc5d0\ub294 \uae38\uc744 \uac77\uac70\ub098 \uc11c \uc788\ub294 \uc791\uc740 \uc0ac\ub78c\ub4e4\uc774 \ubcf4\uc778\ub2e4. \uac74\ubb3c\uc5d0 \ube44\ud574 \ubab8\uc9d1\uc774 \uc791\uc544\uc11c \uc8fc\ubcc0 \uacf5\uac04\uc758 \uaddc\ubaa8\ub97c \ub290\ub07c\uac8c \ud55c\ub2e4. \uc2dc\uc120\uc744 \uc704\ub85c\ub9cc \ubcf4\ub0b4\ub2e4\uac00 \uc544\ub798\ub85c \ub0b4\ub9ac\uba74 \uac70\ub300\ud55c \uc720\uc801\ub3c4 \uc0ac\ub78c\ub4e4\uc774 \uc9c0\ub098\uac00\ub294 \ub3c4\uc2dc \uc548\uc5d0 \uc788\uc5c8\uc74c\uc744 \uc54c\uac8c \ub41c\ub2e4. \uc774 \uadf8\ub9bc\uc740 6\uc138\uae30\uc758 \ud604\uc7a5 \uc0ac\uc9c4\ub3c4 \ud604\uc7ac\uc758 \ubc29\ubb38 \uc548\ub0b4\ub3c4 \uc544\ub2c8\ub2e4. \ud2b9\uc815 \uc2dc\ub300\uc5d0 \ud45c\ud604\ud55c \uc678\uad00\uc774\ub2e4. \ub530\ub77c\uc11c \uc785\uc7a5 \ub3d9\uc120\uc774\ub098 \uc624\ub298\uc758 \ub0b4\ubd80 \uc6b4\uc601\uc744 \uc774 \ub3c4\ud310\uc5d0\uc11c \uc54c\uc544\ub0b4\ub824 \ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub300\uc2e0 \uadf8\ub9bc\uc774 \ubcf4\uc5ec \uc8fc\ub294 \uc5ec\ub7ec \uc9c0\ubd95\uacfc \ucca8\ud0d1, \uc0ac\ub78c\uc758 \ube44\uc728\uc744 \uc77d\ub294 \uc790\ub8cc\ub85c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4. \uc544\uc57c \uc18c\ud53c\uc544\ub97c \ub2e4\uc2dc \ub5a0\uc62c\ub9b4 \ub54c\ub294 \ub3d4 \ud558\ub098\ub9cc \uae30\uc5b5\ud574\ub3c4 \uc88b\ub2e4. \uac70\uae30\uc5d0 \ub3c4\uc2dc \uc911\uc2ec\uc758 \uad81\uc804\uacfc \uacbd\uae30\uc7a5, \ub2e4\ub978 \ud1b5\uce58\uc790\uac00 \ub4e4\uc5b4\uc628 \ub4a4\uc758 \uc5ed\ud560\uc744 \uc870\uae08\uc529 \ub367\ubd99\uc774\uba74 \uac74\ubb3c\uc774 \ud6e8\uc52c \uc785\uccb4\uc801\uc73c\ub85c \ubcf4\uc778\ub2e4. \uc2dc\ub300\ub294 \uac74\ubb3c \uacc1\uc744 \uc9c0\ub098\uac00\uae30\ub9cc \ud55c \uac83\uc774 \uc544\ub2c8\ub77c \uadf8 \uc4f0\uc784\uc744 \ubc14\uafb8\uc5c8\ub2e4. \uc624\ub798\ub41c \uac74\ucd95\ubb3c\uc744 \ubcf4\ub294 \uc990\uac70\uc6c0\uc740 \ucd5c\ucd08\uc758 \ubaa8\uc2b5\ub9cc \ucc3e\uc544\ub0b4\ub294 \ub370 \uc788\uc9c0 \uc54a\ub2e4. \ubb34\uc5c7\uc774 \ub0a8\uace0 \ubb34\uc5c7\uc774 \ub354\ud574\uc84c\ub294\uc9c0 \uc0b4\ud53c\ub294 \ub370\ub3c4 \uc788\ub2e4. \ud070 \uc9c0\ubd95 \uc544\ub798 \uba38\ubb3c\ub800\ub358 \uc5ec\ub7ec \uc2dc\ub300\ub97c \uc0dd\uac01\ud558\uba74, \uc775\uc219\ud55c \uba85\uc18c\uc758 \uc724\uacfd\uc774 \ud55c \uc7a5\uc758 \uadf8\ub9bc\ubcf4\ub2e4 \uae34 \uc774\uc57c\uae30\ub85c \ub2e4\uac00\uc628\ub2e4."}, {"id": "kyoto-genji-court-and-snow", "title": "\uad50\ud1a0 \u2014 \uad81\uc815\uc758 \ud558\ub8e8\ub294 \uc18c\uc124 \uc18d\uc5d0 \ub0a8\uc558\ub2e4", "summary": "\u300e\uac90\uc9c0 \uc774\uc57c\uae30\u300f\uc758 \ud6c4\ub300 \uadf8\ub9bc\uc744 \ubcf4\uba70 \ud5e4\uc774\uc548\ucfc4\uc758 \uad81\uc815 \ubb38\ud654\uc640 \uae00\uc4f0\uae30, \uae30\ub85d\uc758 \ubc94\uc704\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "cities", "category_title": "Cities", "subcategory": "Asia", "url": "stories/kyoto-genji-court-and-snow/index.html", "image": "media/kyoto-genji-court-and-snow.jpg", "alt": "17\uc138\uae30 \uac90\uc9c0 \uc774\uc57c\uae30 \ud654\ucca9\uc758 \uc7a5\uba74. \ud207\ub9c8\ub8e8 \ucabd \uc778\ubb3c\ub4e4\uacfc \ub208 \uc18d\uc758 \uc5b4\ub9b0 \uc2dc\ub140\ub4e4.", "text": "\uad50\ud1a0 \u2014 \uad81\uc815\uc758 \ud558\ub8e8\ub294 \uc18c\uc124 \uc18d\uc5d0 \ub0a8\uc558\ub2e4 \ub208\ub180\uc774 \uadf8\ub9bc\uc5d0\uc11c \ub9cc\ub098\ub294 \ud5e4\uc774\uc548 \uc2dc\ub300\uc758 \uc0dd\ud65c \u300e\uac90\uc9c0 \uc774\uc57c\uae30\u300f\uc758 \ud6c4\ub300 \uadf8\ub9bc\uc744 \ubcf4\uba70 \ud5e4\uc774\uc548\ucfc4\uc758 \uad81\uc815 \ubb38\ud654\uc640 \uae00\uc4f0\uae30, \uae30\ub85d\uc758 \ubc94\uc704\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Asia \ub3c4\uc2dc \uad50\ud1a0\ub97c \ub5a0\uc62c\ub9ac\uba74 \uc808\uacfc \uc815\uc6d0\ubd80\ud130 \uc0dd\uac01\ud558\uae30 \uc27d\ub2e4. \uadf8\ub7f0\ub370 \uc774 \ub3c4\uc2dc\uc758 \uc61b \uc0dd\ud65c\ub85c \ub4e4\uc5b4\uac00\ub294 \ub610 \ud558\ub098\uc758 \ubb38\uc740 \uc18c\uc124\uc774\ub2e4. \uad81\uc815\uc5d0\uc11c \ubb34\uc5c7\uc744 \uc785\uace0 \uc5b4\ub5a4 \uc545\uae30\ub97c \uc990\uacbc\uc73c\uba70 \uc0ac\ub78c\ub4e4 \uc0ac\uc774\uc5d0 \uc5b4\ub5a4 \uae30\ub300\uac00 \uc788\uc5c8\ub294\uc9c0\uac00 \uc774\uc57c\uae30 \uc18d\uc5d0 \ub0a8\uc544 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\uc5d0\uc11c\ub294 \uac74\ubb3c \uc548\ucabd\uc5d0\uc11c \ubc14\uae65\uc758 \ub208\ub180\uc774\ub97c \ubc14\ub77c\ubcf4\ub294 \uc0ac\ub78c\ub4e4\uc744 \ubcfc \uc218 \uc788\ub2e4. \u300e\uac90\uc9c0 \uc774\uc57c\uae30\u300f\uc758 \ud55c \uc7a5\uba74\uc744 \uadf8\ub9b0 17\uc138\uae30 \ud654\ucca9\uc774\ub2e4. \uc18c\uc124\uc758 \ubc30\uacbd\uacfc \uadf8\ub9bc\uc758 \uc81c\uc791 \uc2dc\uae30\ub294 \ub2e4\ub974\uc9c0\ub9cc, \ud6c4\ub300 \uc0ac\ub78c\ub4e4\uc774 \uc624\ub798\ub41c \uad81\uc815\uc758 \ud558\ub8e8\ub97c \uc5b4\ub5bb\uac8c \uc0c1\uc0c1\ud588\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uac8c \ud55c\ub2e4. 794\ub144 \uac04\ubb34 \ucc9c\ud669\uc740 \uc218\ub3c4\ub97c \ub098\ub77c\uc5d0\uc11c \ubd81\ucabd\uc758 \ud5e4\uc774\uc548\ucfc4\ub85c \uc62e\uacbc\ub2e4. \uc624\ub298\ub0a0 \uad50\ud1a0\uac00 \uc788\ub294 \uacf3\uc774\ub2e4. \uad50\uc7ac\ub294 \uc774\ud6c4 \uc624\ub7ab\ub3d9\uc548 \uc774\uacf3\uc774 \uc77c\ubcf8\uc758 \uc218\ub3c4\ub85c \uae30\ub2a5\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc9c0\uae08 \ub208\uc55e\uc5d0 \ub0a8\uc740 \ubaa8\ub4e0 \uac74\ubb3c\uc774 \uadf8\ub54c\ubd80\ud130 \uadf8\ub300\ub85c \uc788\uc5c8\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc218\ub3c4\uac00 \ub41c\ub2e4\ub294 \uac83\uc740 \uad81\uc804 \ud558\ub098\ub97c \uc138\uc6b0\ub294 \uac83 \uc774\uc0c1\uc774\uc5c8\ub2e4. \ud1b5\uce58\uc790\uc640 \uc720\ub825 \uac00\ubb38, \uad00\ub9ac\uc640 \uadf8 \uc0dd\ud65c\uc744 \ub4b7\ubc1b\uce68\ud558\ub294 \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc600\ub2e4. \uc815\uce58\uc758 \uc911\uc2ec\uc740 \ud2b9\uc815\ud55c \ucde8\ud5a5\uacfc \uaddc\uce59\uc744 \ub098\ub204\ub294 \ubb38\ud654\uc758 \uc911\uc2ec\uc774 \ub418\uae30\ub3c4 \ud588\ub2e4. \u300e\uac90\uc9c0 \uc774\uc57c\uae30\u300f\uac00 \ubcf4\uc5ec \uc8fc\ub294 \uad81\uc815\uc740 \uc774\ub7f0 \uad00\uacc4 \uc18d\uc5d0 \uc788\uc5c8\ub2e4. \uad50\uc7ac\ub294 \ud5e4\uc774\uc548 \uc2dc\ub300\uc5d0 \ud6c4\uc9c0\uc640\ub77c \uac00\ubb38\uc774 \ucc9c\ud669\uc744 \ubcf4\uc88c\ud558\uac70\ub098 \uc12d\uc815\uc758 \uc790\ub9ac\uc5d0 \uc624\ub974\uba70 \uc601\ud5a5\ub825\uc744 \ud0a4\uc6e0\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uad81\uc815\uc758 \uc5ed\uc0ac\ub294 \ucc9c\ud669 \ud55c \uc0ac\ub78c\uc758 \uc120\ud0dd\ub9cc\uc73c\ub85c \uc6c0\uc9c1\uc778 \uac83\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uac00\ubb38\uacfc \uc9c0\uc704, \ud63c\uc778\uacfc \uce5c\uc871 \uad00\uacc4\uac00 \uad8c\ub825\uc758 \uc870\uac74\uc774 \ub418\uc5c8\ub2e4. \uc18c\uc124 \uc18d \uc778\ubb3c\uc758 \uc0ac\ub791\uc774\ub098 \ub9cc\ub0a8\uc774 \uc624\ub298\uc758 \ub3c5\uc790\uc5d0\uac8c\ub294 \uc0ac\uc801\uc778 \uc77c\ucc98\ub7fc \ubcf4\uc77c \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uc2e0\ubd84\uacfc \ud608\ud1b5\uc774 \uc911\uc694\ud55c \uc0ac\ud68c\uc5d0\uc11c\ub294 \uce5c\ubc00\ud55c \uad00\uacc4\ub3c4 \uacf5\uc801\uc778 \uc790\ub9ac\ub97c \ubc14\uafc0 \uc218 \uc788\uc5c8\ub2e4. \uc904\uac70\ub9ac\uc758 \uac10\uc815\uc744 \ub530\ub77c\uac00\uba74\uc11c \uadf8 \uac10\uc815\uc774 \ub193\uc778 \uc0ac\ud68c\uc758 \uaddc\uce59\uc744 \ud568\uaed8 \ubcf4\uba74 \ud589\ub3d9\uc774 \uc870\uae08 \ub354 \uc798 \uc774\ud574\ub41c\ub2e4. \ub2f9\uc2dc \uc77c\ubcf8\uc5d0\uc11c\ub294 \uc911\uad6d\uc758 \ubb38\uc790\uc640 \ud559\ubb38\uc744 \ubc1b\uc544\ub4e4\uc774\ub294 \uc804\ud1b5\uc774 \uc788\uc5c8\ub2e4. \ub3d9\uc2dc\uc5d0 \uc77c\ubcf8\uc5b4\uc758 \uc18c\ub9ac\ub97c \uc801\ub294 \uac00\ub098\uac00 \ubc1c\uc804\ud588\ub2e4. \uad50\uc7ac\ub294 \uc774 \ubcc0\ud654\uc640 \u300e\uac90\uc9c0 \uc774\uc57c\uae30\u300f\ub97c \uc5f0\uacb0\ud574 \uc124\uba85\ud55c\ub2e4. \ub2e4\ub978 \ubb38\ud654\uc5d0\uc11c \uc628 \uae00\uc790\ub97c \uc0ac\uc6a9\ud558\ub358 \uc0ac\ud68c\uac00 \uc790\uae30 \ub9d0\uc758 \ud45c\ud604 \ubc29\ubc95\uc744 \ub113\ud600 \uac04 \uac83\uc774\ub2e4. \ubb38\uc790\uc758 \ubcc0\ud654\ub294 \uae00\uc790 \ubaa8\uc591\uc5d0 \uad00\ud55c \uc774\uc57c\uae30\ub9cc\uc774 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \ub9d0\uc744 \uc5bc\ub9c8\ub098 \uc790\uc5f0\uc2a4\ub7fd\uac8c \uc801\uc744 \uc218 \uc788\ub294\uc9c0\uc640 \uad00\ub828\ub41c\ub2e4. \ub9d0\ud22c\uc640 \uac10\uc815, \uc77c\uc0c1 \uc18d \uad00\uacc4\uac00 \uae00\ub85c \uc62e\uaca8\uc9c8 \uae38\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc678\ubd80\uc758 \ubb38\ud654\ub97c \ubc1b\uc544\ub4e4\uc774\ub294 \uc77c\uacfc \uc790\uae30 \uc5b8\uc5b4\uc758 \ud45c\ud604\uc744 \ub9cc\ub4dc\ub294 \uc77c\uc774 \ud568\uaed8 \uc9c4\ud589\ub418\uc5c8\ub2e4. \u300e\uac90\uc9c0 \uc774\uc57c\uae30\u300f\ub294 11\uc138\uae30 \uad81\uc815 \uc5ec\uc131 \ubb34\ub77c\uc0ac\ud0a4 \uc2dc\ud0a4\ubd80\uac00 \uc4f4 \uc791\ud488\uc73c\ub85c \uc54c\ub824\uc838 \uc788\ub2e4. \uad50\uc7ac\ub294 \uadf8\uac00 \uadc0\uc871 \uac00\ubb38 \ucd9c\uc2e0\uc73c\ub85c \uad81\uc815\uc5d0\uc11c \uc77c\ud588\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \uc790\uc138\ud55c \uc0dd\uc560\uc640 \uc9d1\ud544 \uacfc\uc815\uc5d0\ub294 \uc54c\ub824\uc9c0\uc9c0 \uc54a\uc740 \ubd80\ubd84\ub3c4 \uc788\uc73c\ubbc0\ub85c \ubaa8\ub4e0 \uc7a5\uba74\uc744 \uc791\uac00\uc758 \uc2e4\uc81c \uacbd\ud5d8\uc73c\ub85c \uc77d\uc744 \uc218\ub294 \uc5c6\ub2e4. \uc791\ud488\uc5d0\ub294 \ud5c8\uad6c\uc758 \ud669\uc790 \ud788\uce74\ub8e8 \uac90\uc9c0\uc640 \uc8fc\ubcc0 \uc778\ubb3c\ub4e4\uc758 \uad00\uacc4\uac00 \ud3bc\uccd0\uc9c4\ub2e4. \uc655\uc704 \uacc4\uc2b9\uc5d0\uc11c \ubc97\uc5b4\ub09c \uc778\ubb3c\uc758 \uc0b6\uacfc \uc5ec\ub7ec \uc0ac\ub791, \uc9c0\uc704\uc758 \ubb38\uc81c\uac00 \uc5bd\ud78c\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc804\uccb4 \uc904\uac70\ub9ac\ub97c \uc555\ucd95\ud558\uae30\ubcf4\ub2e4 \uc774 \uc18c\uc124\uc774 \uc61b \uc218\ub3c4\uc758 \uc0dd\ud65c\uc744 \ubc14\ub77c\ubcf4\ub294 \ucc3d\uc774 \ub41c\ub2e4\ub294 \uc810\uc5d0 \uc8fc\ubaa9\ud574 \ubcf4\uc790. 17\uc138\uae30 \ud654\ucca9\uc758 \uc7a5\uba74\uc5d0\uc11c\ub294 \uc5b4\ub9b0 \uc2dc\ub140\ub4e4\uc774 \ub208 \uc18d\uc5d0\uc11c \ub178\ub294 \ub3d9\uc548 \uac90\uc9c0\uc640 \ubb34\ub77c\uc0ac\ud0a4\uac00 \ud207\ub9c8\ub8e8 \ucabd\uc5d0\uc11c \uc9c0\ucf1c\ubcf8\ub2e4. \ud070 \uc0ac\uac74\ubcf4\ub2e4 \uc791\uc740 \ub180\uc774\uac00 \ud654\uba74\uc758 \uc911\uc2ec\uc774 \ub41c\ub2e4. \uac74\ubb3c\uc758 \uc548\ud30e\uacfc \uc0ac\ub78c\ub4e4\uc758 \uc790\ub9ac \ucc28\uc774\ub97c \uc0b4\ud53c\ub294 \uac83\ub9cc\uc73c\ub85c\ub3c4 \uadf8\ub9bc\uc744 \uc77d\ub294 \uc7ac\ubbf8\uac00 \uc788\ub2e4. \ub2e4\ub9cc \uc774 \uadf8\ub9bc\uc740 11\uc138\uae30 \uad81\uc815\uc5d0\uc11c \uc9c1\uc811 \ucd2c\uc601\ud55c \uc0dd\ud65c \uae30\ub85d\uc774 \uc544\ub2c8\ub2e4. \uc218\ubc31 \ub144 \ub4a4 \uc81c\uc791\uc790\uac00 \uc18c\uc124\uc744 \ud574\uc11d\ud55c \uc774\ubbf8\uc9c0\ub2e4. \uc61b \uc774\uc57c\uae30\ub97c \ud6c4\ub300\uc758 \ub208\uc73c\ub85c \ub2e4\uc2dc \ud45c\ud604\ud558\ub294 \uacfc\uc815\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \uc18c\uc124 \uc18d \uc2dc\ub300\uc640 \uadf8\ub9bc\uc758 \uc2dc\ub300\ub97c \ub098\ub204\uc5b4 \ubcf4\uba74 \uc624\ub798\ub41c \uc791\ud488\uc774 \uc5b4\ub5bb\uac8c \uacc4\uc18d \uc77d\ud614\ub294\uc9c0\ub3c4 \ubcf4\uc778\ub2e4. \uad50\uc7ac\ub294 \uc791\ud488\uc5d0 \uc758\ubcf5\uacfc \ub180\uc774, \uc545\uae30, \uc77c\uc0c1\uc758 \uc608\uc808\uc774 \ub098\ud0c0\ub09c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc774\ub7f0 \uc138\ubd80\ub294 \uad81\uc815 \ubb38\ud654\ub97c \uc774\ud574\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ud558\uc9c0\ub9cc \uad81\uc815\uc758 \uc0dd\ud65c\uc774 \ub2f9\uc2dc \uad50\ud1a0 \uc8fc\ubbfc \ubaa8\ub450\uc758 \uc0dd\ud65c\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ub3c4\uc2dc\uc758 \ubb38\ud654\ub294 \uadf8\uacf3\uc5d0\uc11c \uae00\uc744 \ub0a8\uae34 \uc0ac\ub78c\uc758 \ubc94\uc704\ubcf4\ub2e4 \ub113\uc5c8\ub2e4. \uc2dc\ub140\uc640 \uad00\ub9ac, \ubb3c\uc790\ub97c \uacf5\uae09\ud55c \uc0ac\ub78c\ub4e4\uc758 \uc790\ub9ac\ub294 \uc11c\ub85c \ub2ec\ub790\ub2e4. \uc791\ud488\uc5d0\uc11c \uc544\ub984\ub2e4\uc6b4 \uc7a5\uba74\uc744 \ub9cc\ub0ac\ub2e4\uace0 \uadf8 \uc0ac\ud68c\uc758 \ubaa8\ub4e0 \uad00\uacc4\uac00 \ud3b8\uc548\ud588\ub2e4\uace0 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub204\uac00 \ub9d0\ud558\uace0 \ub204\uad6c\uc758 \uad00\uc810\uc774 \uc911\uc2ec\uc778\uc9c0 \ubb3b\ub294 \uc77c\uc740 \uac10\uc0c1\uc744 \ubb34\uac81\uac8c \ub9cc\ub4e4\uae30\ubcf4\ub2e4 \ubcf4\uc774\uc9c0 \uc54a\ub358 \uc8fc\ubcc0\uc744 \ud568\uaed8 \ubcf4\uac8c \ud55c\ub2e4. \uc720\uba85\ud55c \uc18c\uc124\uc740 \uc2e4\uc81c \uc7a5\uc18c\ub97c \ub2e4\uc2dc \ubcf4\uac8c \ub9cc\ub4e0\ub2e4. \uad81\uc815\uc758 \ubc29\uacfc \ud207\ub9c8\ub8e8, \uacc4\uc808\uc744 \ub290\ub07c\ub294 \ub9c8\ub2f9\ub3c4 \uc774\uc57c\uae30\ub97c \uc54c\uace0 \ub098\uba74 \ub2e4\ub978 \ud45c\uc815\uc744 \uc5bb\ub294\ub2e4. \uac74\ubb3c\uc774 \ub2e8\uc9c0 \uc624\ub798\ub41c \ub098\ubb34\uc640 \uc9c0\ubd95\uc774 \uc544\ub2c8\ub77c \uc0ac\ub78c\ub4e4\uc774 \uc11c\ub85c\ub97c \uae30\ub2e4\ub9ac\uace0 \ubc14\ub77c\ubcf8 \uacf5\uac04\uc73c\ub85c \ub290\uaef4\uc9c0\ub294 \uac83\uc774\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc18c\uc124\uc758 \ubaa8\ub4e0 \uc7a5\uc18c\ub97c \uc9c0\uae08\uc758 \uc9c0\ub3c4 \uc704\uc5d0 \uc815\ud655\ud788 \ud45c\uc2dc\ud560 \uc218 \uc788\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ud5c8\uad6c\uc640 \uc5ed\uc0ac \uc790\ub8cc, \ud604\uc874\ud558\ub294 \uc720\uc801\uc740 \uac01\uac01\uc758 \ud655\uc778\uc774 \ud544\uc694\ud558\ub2e4. \uc774\ubc88 \uadf8\ub9bc\uc740 \ud2b9\uc815 \uad00\uad11\uc9c0\uc758 \uc61b \ubaa8\uc2b5\uc744 \uc778\uc99d\ud558\uae30\ubcf4\ub2e4 \uad81\uc815\uc758 \uacf5\uac04\uacfc \uc0dd\ud65c\uc744 \uc0dd\uac01\ud558\uac8c \ud558\ub294 \uc790\ub8cc\ub85c \ubcf4\ub294 \ud3b8\uc774 \uc54c\ub9de\ub2e4. \uc61b \ub3c4\uc2dc\ub97c \uc774\ud574\ud558\ub824\uace0 \uc655\uacfc \uc804\uc7c1\uc758 \uc5f0\ub3c4\ub9cc \uc678\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \ubb34\uc5c7\uc744 \uc785\uace0 \uc5b4\ub5bb\uac8c \ub180\uba70 \uc5b4\ub5a4 \ub9d0\uc744 \uae00\ub85c \ub0a8\uacbc\ub294\uc9c0\ub3c4 \ub3c4\uc2dc\uc758 \uc5ed\uc0ac\ub2e4. \u300e\uac90\uc9c0 \uc774\uc57c\uae30\u300f\uc640 \ud6c4\ub300\uc758 \uadf8\ub9bc\uc740 \ud5e4\uc774\uc548\ucfc4\uc758 \uad81\uc815 \ubb38\ud654\uac00 \uae34 \uc2dc\uac04 \ub3d9\uc548 \uc77d\ud788\uace0 \ub2e4\uc2dc \uadf8\ub824\uc84c\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uad50\ud1a0\ub97c \uc0dd\uac01\ud560 \ub54c \uc815\uc6d0\uacfc \uc0ac\ucc30 \uacc1\uc5d0 \uc774 \ub208\ub180\uc774 \uc7a5\uba74\ub3c4 \ub193\uc544 \ubcf4\uba74 \uc5b4\ub5a8\uae4c. \ud55c \ub3c4\uc2dc\uc5d0\ub294 \ud070 \uc815\uce58\uc758 \uc2dc\uac04\uacfc \uc791\uc740 \uc0dd\ud65c\uc758 \uc2dc\uac04\uc774 \ud568\uaed8 \ud750\ub978\ub2e4. \uc18c\uc124 \uc18d\uc758 \ud558\ub8e8\ub97c \uc77d\ub294 \uac83\uc740 \uadf8 \uac00\uc6b4\ub370 \uae30\ub85d\uacfc \uc0c1\uc0c1 \uc0ac\uc774\uc5d0 \ub0a8\uc740 \ud55c \uce35\uc744 \ucc9c\ucc9c\ud788 \uac78\uc5b4 \ubcf4\ub294 \uc77c\uc774\ub2e4."}, {"id": "mozambique-village-cultural-center", "title": "\uace0\ud5a5 \ub9c8\uc744\uc5d0 \ub465\uadfc \ucc3d\uc758 \ubb38\ud654 \uacf5\uac04\uc744 \ub9cc\ub4e4\ub2e4", "summary": "\ub9d0\ub791\uac00\ud0c0\ub098\uac00 \uace0\ud5a5\uc5d0\uc11c \uc2dc\uc791\ud55c \ubb38\ud654\uc13c\ud130\ub97c \ud1b5\ud574 \uc608\uc220\uacfc \ub9c8\uc744\uc758 \uad00\uacc4\ub97c \ubd05\ub2c8\ub2e4.", "category": "cities", "category_title": "Cities", "subcategory": "Africa", "url": "stories/mozambique-village-cultural-center/index.html", "image": "media/mozambique-village-cultural-center.jpg", "alt": "\uace0\ud5a5 \ub9c8\uc744\uc5d0 \ub465\uadfc \ucc3d\uc758 \ubb38\ud654 \uacf5\uac04\uc744 \ub9cc\ub4e4\ub2e4\uc758 \uc8fc\uc81c\ub97c \ud45c\ud604\ud55c AI \uc124\uba85\uc6a9 \uc0bd\ud654. \uc2e4\uc81c \uc791\ud488\uc774\ub098 \uac74\ucd95\ubb3c\uc744 \uadf8\ub300\ub85c \uc7ac\ud604\ud55c \uc774\ubbf8\uc9c0\uac00 \uc544\ub2d9\ub2c8\ub2e4.", "text": "\uace0\ud5a5 \ub9c8\uc744\uc5d0 \ub465\uadfc \ucc3d\uc758 \ubb38\ud654 \uacf5\uac04\uc744 \ub9cc\ub4e4\ub2e4 \ubaa8\uc7a0\ube44\ud06c \ud654\uac00\uc758 \uc77c\uc774 \uadf8\ub9bc \ubc16\uc73c\ub85c \uc774\uc5b4\uc9c4 \uc21c\uac04 \ub9d0\ub791\uac00\ud0c0\ub098\uac00 \uace0\ud5a5\uc5d0\uc11c \uc2dc\uc791\ud55c \ubb38\ud654\uc13c\ud130\ub97c \ud1b5\ud574 \uc608\uc220\uacfc \ub9c8\uc744\uc758 \uad00\uacc4\ub97c \ubd05\ub2c8\ub2e4. Africa \ub3c4\uc2dc \ud654\uac00\uc758 \uc791\uc5c5\uc774\ub77c\uace0 \ud558\uba74 \uce94\ubc84\uc2a4 \uc55e\uc5d0 \uc120 \ubaa8\uc2b5\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \uadf8\ub7f0\ub370 \ubaa8\uc7a0\ube44\ud06c\uc758 \ud654\uac00 \ub9d0\ub791\uac00\ud0c0\ub098 \uc751\uc6e8\ub0d0\ub294 \uace0\ud5a5 \ub9c8\uc744\uc5d0 \ubb38\ud654\uc13c\ud130\ub97c \ub9cc\ub4dc\ub294 \uc77c\ub3c4 \uc2dc\uc791\ud588\ub2e4. \uadf8\ub9bc\uc744 \ub193\uc744 \ubcbd\ub9cc\uc774 \uc544\ub2c8\ub77c \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc77c \uacf5\uac04\uc744 \uc0dd\uac01\ud55c \uac83\uc774\ub2e4. \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc758 \uc5f0\uad6c \uc790\ub8cc\ub294 \uadf8\uac00 1995\ub144\uc5d0 \ub9c8\ud0c8\ub77c\ub098\uc5d0\uc11c \uc774 \uacf5\uac04\uc744 \ub9cc\ub4e4\uae30 \uc2dc\uc791\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc608\uc220 \uad50\uc721\uacfc \ub9c8\uc744 \ud589\uc0ac\ub97c \uc704\ud55c \uacf3\uc774\uc5c8\ub2e4. \uadf8\ub294 \uc5b4\ub9b0 \uc2dc\uc808 \uace0\ud5a5\uc5d0\uc11c \ub3c4\uc790\uae30\uc640 \ubc14\uad6c\ub2c8 \ub9cc\ub4e4\uae30, \uadf8\ub9bc \uac19\uc740 \uc9c0\uc5ed\uc758 \uc608\uc220\uacfc \uacf5\uc608\ub97c \uc811\ud588\ub2e4. \uc774\ud6c4 \ub3c4\uc2dc\ub85c \ub098\uac00 \uc77c\ud558\uace0 \uadf8\ub9bc\uc744 \ubc30\uc6b0\uba70 \uc790\uc2e0\uc758 \uae38\uc744 \ub113\ud614\ub2e4\uace0 \ubbf8\uc220\uad00\uc740 \uc18c\uac1c\ud55c\ub2e4. \uc774 \ub300\ubaa9\uc740 \uadf8\ub97c \uc544\ubb34\ub7f0 \ubc30\uc6c0\ub3c4 \uc5c6\uc774 \ub4f1\uc7a5\ud55c \ud2b9\ubcc4\ud55c \ucc9c\uc7ac\ub85c \ubcf4\ub294 \uc0dd\uac01\uacfc \ub2e4\ub974\ub2e4. \ub9c8\uc744\uc5d0\uc11c \ub9cc\ub09c \uc190\uc77c\uacfc \ub3c4\uc2dc\uc5d0\uc11c\uc758 \ubc30\uc6c0, \ub2e4\ub978 \uc608\uc220\uac00\ub4e4\uacfc\uc758 \uad00\uacc4\uac00 \ud568\uaed8 \uc313\uc778 \uc0b6\uc774\uc5c8\ub2e4. \uace0\ud5a5\uc758 \ubb38\ud654 \uacf5\uac04\ub3c4 \uadf8\ub7f0 \uc2dc\uac04\uc744 \ub5a0\uc62c\ub9ac\uba70 \ubcfc \uc218 \uc788\ub2e4. \ubbf8\uc220\uad00\uc740 \ubb38\ud654\uc13c\ud130\uc758 \uac74\ucd95\uc5d0 \uae30\ud558\ud559\uc801 \uad6c\uc131\uacfc \uc0b0\uc5c5 \uc7ac\ub8cc\uac00 \uc4f0\uc600\uace0, \ub465\uadfc \ucc3d\uacfc \uaca9\uc790, \uc778\ubb3c \ud615\ud0dc\uc758 \ubcbd\uba74 \ubd80\uc870 \uac19\uc740 \uc694\uc18c\uac00 \ub354\ud574\uc84c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uce5c\uad6c\uc774\uc790 \ud6c4\uc6d0\uc790\uc600\ub358 \uac74\ucd95\uac00 \ud310\ucd08 \uac8c\ub4dc\uc2a4\uc640\uc758 \uad00\uacc4\ub3c4 \ud568\uaed8 \uc18c\uac1c\ud55c\ub2e4. \uc774\ub984\ub09c \uac74\ucd95 \uc591\uc2dd\uc744 \uba3c\uc800 \uc678\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub465\uadfc \ucc3d\uc73c\ub85c \ube5b\uc774 \ub4e4\uc5b4\uc624\uace0 \ubcbd\uc5d0\ub3c4 \ubb34\uc5b8\uac00\ub97c \ud45c\ud604\ud560 \uc790\ub9ac\uac00 \uc788\ub294 \uacf5\uac04\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc5ec\uae30\uc758 \uc0bd\ud654\ub294 \uadf8 \uc0dd\uac01\uc744 \ub3d5\ub294 \uac1c\ub150 \uadf8\ub9bc\uc774\uba70 \uc2e4\uc81c \uac74\ubb3c\uc744 \uadf8\ub300\ub85c \uadf8\ub9b0 \uc0ac\uc9c4\uc740 \uc544\ub2c8\ub2e4. \ub9d0\ub791\uac00\ud0c0\ub098\ub294 1936\ub144\uc5d0 \ud0dc\uc5b4\ub098 2011\ub144\uc5d0 \uc138\uc0c1\uc744 \ub5a0\ub0ac\ub2e4. \uadf8 \uc0ac\uc774 \ubaa8\uc7a0\ube44\ud06c\ub294 \ud3ec\ub974\ud22c\uac08\uc758 \uc2dd\ubbfc \uc9c0\ubc30\ub97c \ubc97\uc5b4\ub098 \ub3c5\ub9bd\ud588\uace0, \ub2e4\uc2dc \ub0b4\uc804\uc744 \uacaa\uc5c8\ub2e4. \ud654\uac00\uc758 \uc0dd\uc560\ub97c \uc774\ub7f0 \ubcc0\ud654\uc640 \ub098\ub780\ud788 \ub193\uc73c\uba74 \ubb38\ud654\uc13c\ud130\uac00 \ub2e8\uc21c\ud55c \uac1c\uc778 \uae30\ub150\uad00\ub9cc\uc740 \uc544\ub2c8\uc5c8\ub2e4\ub294 \uc810\uc774 \ubcf4\uc778\ub2e4. \uc608\uc220\uc744 \ubc30\uc6b0\uace0 \ud568\uaed8 \ubaa8\uc77c \uc7a5\uc18c\ub97c \uace0\ud5a5\uc5d0 \ub9c8\ub828\ud558\ub294 \uc77c\uc5d0\ub294 \uadf8\uac00 \uc0b4\uc544\uc628 \uc0ac\ud68c\uc758 \uc2dc\uac04\uc774 \uacb9\uccd0 \uc788\uc5c8\ub2e4. \ubbf8\uc220\uad00\uc740 \uadf8\uc758 \ucd08\uae30 \uc791\ud488\uc5d0 \uc778\uac04\uacfc \ub3d9\ubb3c, \uad34\ubb3c \uac19\uc740 \ud615\uc0c1\ub4e4\uc774 \ube7d\ube7d\ud558\uac8c \ub4f1\uc7a5\ud55c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc885\uad50\uc640 \uc9c0\uc5ed\uc758 \uc804\uc2b9, \uc2dd\ubbfc \uc9c0\ubc30 \uc544\ub798\uc758 \ud604\uc2e4\uc774 \uac19\uc740 \ud654\uba74\uc5d0 \ub4e4\uc5b4\uc654\ub2e4. \uc775\uc219\ud55c \uc0b6\uc744 \uc608\uc058\uac8c \uc7a5\uc2dd\ud558\ub294 \uadf8\ub9bc\ub9cc \uadf8\ub9b0 \uac83\uc774 \uc544\ub2c8\ub2e4. \ubc14\ub00c\ub294 \uc138\uc0c1\uc744 \uc5b4\ub5a4 \ud615\ud0dc\ub85c \ud45c\ud604\ud560\uc9c0 \uace0\ubbfc\ud558\ub358 \uc791\uc5c5\uc740 \ud6d7\ub0a0 \uc0ac\ub78c\uc774 \ubaa8\uc774\ub294 \uac74\ucd95 \uacf5\uac04\uc73c\ub85c\ub3c4 \ub113\uc5b4\uc84c\ub2e4. \uadf8\uac00 \uc218\ub3c4\ub85c \ub098\uac14\uc744 \ub54c \ud751\uc778 \ubaa8\uc7a0\ube44\ud06c\uc778\uc5d0\uac8c \uc815\uaddc \ubbf8\uc220 \uad50\uc721\uc758 \uae30\ud68c\ub294 \ud3c9\ub4f1\ud558\uc9c0 \uc54a\uc558\ub2e4. \uc2dd\ubbfc \uc9c0\ubc30 \uc544\ub798\uc758 \uc778\uc885\uc801\u00b7\uc0ac\ud68c\uc801 \uc7a5\ubcbd\uc774 \uc788\uc5c8\uae30 \ub54c\ubb38\uc774\ub2e4. \ubbf8\uc220\uad00\uc774 \uad50\uc721 \uacbd\ub85c\ub97c \uc790\uc138\ud788 \uc124\uba85\ud558\ub294 \uc774\uc720\ub3c4 \uc5ec\uae30\uc5d0 \uc788\ub2e4. \ub204\uad6c\uc5d0\uac8c\ub098 \uac19\uc740 \ud559\uad50\uc758 \ubb38\uc774 \uc5f4\ub824 \uc788\uc5c8\ub294\ub370 \ud63c\uc790 \ub2e4\ub978 \uae38\uc744 \uace0\ub978 \uc0ac\ub78c\ucc98\ub7fc \uc0dd\uc560\ub97c \ub2e8\uc21c\ud654\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc0b0\uc5c5\ud559\uad50\uc640 \ubbf8\uc220\uc13c\ud130\uc5d0\uc11c\uc758 \ubc30\uc6c0, \ub2e4\ub978 \uc608\uc220\uac00\uc640\uc758 \ub9cc\ub0a8\uc774 \uc791\uc5c5\uc5d0 \uc601\ud5a5\uc744 \uc8fc\uc5c8\ub2e4. \ud310\ucd08 \uac8c\ub4dc\uc2a4\ub294 \uc791\uc5c5\uc2e4\uacfc \uc0dd\ud65c\uc744 \uc704\ud55c \uc9c0\uc6d0, \uc791\ud488 \uc8fc\ubb38\uc73c\ub85c\ub3c4 \uadf8\uc758 \ud65c\ub3d9\uc744 \ub3c4\uc654\ub2e4. \uce5c\uad6c\ub77c\ub294 \ub9d0 \uc548\uc5d0\ub3c4 \uc774\ub807\uac8c \uad6c\uccb4\uc801\uc778 \uc870\uac74\uc774 \uc788\uc5c8\ub2e4. \uadf8\ub9bc\uc744 \uacc4\uc18d \uadf8\ub9b4 \uc218 \uc788\ub294 \uc790\ub9ac\uc640 \uc2dc\uac04\uc774 \uc5b4\ub5bb\uac8c \ub9c8\ub828\ub418\uc5c8\ub294\uc9c0 \uc54c\uba74 \uc791\ud488 \ub4a4\uc758 \uad00\uacc4\uac00 \uc870\uae08 \ub354 \uc798 \ubcf4\uc778\ub2e4. \ubb38\ud654\uc13c\ud130\uc758 \ub465\uadfc \ucc3d\uacfc \uaca9\uc790\ub294 \ube5b\uacfc \uc2dc\uc120\uc744 \ub098\ub204\ub294 \uac74\ucd95 \uc694\uc18c\ub2e4. \ubcbd\uc758 \uc778\ubb3c \ubd80\uc870\ub294 \ud3c9\ud3c9\ud55c \ud654\uba74\uacfc \ub2ec\ub9ac \uc2e4\uc81c \uacf5\uac04\uc5d0\uc11c \uadf8\ub9bc\uc790\uc640 \ub450\uaed8\ub97c \ub9cc\ub4e0\ub2e4. \uac74\ucd95\uac00\uc758 \uc124\uacc4 \uc5b8\uc5b4\uc640 \ud654\uac00\uc758 \ud615\uc0c1 \uac10\uac01\uc744 \uac19\uc740 \uc7a5\uc18c\uc5d0\uc11c \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uc5b4\ub290 \ud55c \uc694\uc18c\ub9cc \ubcf4\uace0 \uadf8 \uac74\ubb3c\uc744 \uc804\ud1b5\uc801\uc774\uac70\ub098 \uc678\ub798\uc801\uc774\ub77c\uace0 \ub2e8\uc815\ud558\uae30\uc5d0\ub294 \uc5ec\ub7ec \uacbd\ud5d8\uc774 \uc11e\uc5ec \uc788\ub2e4. \uc774\uac83\uc740 \uc0ac\uc9c4 \uc18d \uc138\ubd80\ub97c \uc678\uc6b0\uae30 \uc704\ud55c \ubaa9\ub85d\ubcf4\ub2e4 \ubcfc \uc21c\uc11c\ub97c \ub9cc\ub4dc\ub294 \uc124\uba85\uc774\ub2e4. \uc2e4\uc81c \uac74\ubb3c\uc758 \uc790\ub8cc\ub97c \ub9cc\ub098\uba74 \uba3c\uc800 \ucc3d\uacfc \ubcbd\uc758 \uad00\uacc4\ub97c, \ub2e4\uc74c\uc5d0\ub294 \uc0ac\ub78c\uc758 \ud615\uc0c1\uc774 \uc5b4\ub290 \ub192\uc774\uc5d0 \ub193\uc600\ub294\uc9c0 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \ubcf8\ubb38\uc758 AI \uc0bd\ud654\ub294 \uc774\ub7f0 \uad00\uc2ec\uc744 \ub3d5\ub294 \uac1c\ub150 \uc774\ubbf8\uc9c0\uc774\ubbc0\ub85c \ucc3d\uc758 \uc815\ud655\ud55c \uac1c\uc218\ub098 \ubc30\uce58\ub97c \ud655\uc778\ud558\ub294 \uadfc\uac70\ub85c \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub294\ub2e4. \ud55c \uc810\uc758 \uadf8\ub9bc\uc740 \uadf8\uac83\uc744 \ubcf4\ub294 \uc0ac\ub78c\uc744 \ub9cc\ub09c\ub2e4. \uad50\uc721 \uacf5\uac04\uc740 \uadf8\uacf3\uc5d0\uc11c \ub2e4\ub978 \uc0ac\ub78c\uc774 \uadf8\ub9bc\uc744 \uadf8\ub824 \ubcfc \uac00\ub2a5\uc131\uc744 \ub9cc\ub4e0\ub2e4. \ub450 \uc77c\uc740 \uc11c\ub85c \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \uc774\uc5b4\uc9c4\ub2e4. \uc644\uc131\ub41c \uc791\ud488\uc758 \uba85\uc131\uacfc \uadf8 \ub2e4\uc74c \uc791\uc5c5\uc744 \uc2dc\uc791\ud560 \uc0ac\ub78c\uc758 \uc790\ub9ac\ub97c \ud568\uaed8 \uc0dd\uac01\ud558\uba74, \ud654\uac00\uac00 \uc65c \uac74\ubb3c\uacfc \uc9c0\uc5ed \ud589\uc0ac\uc5d0\ub3c4 \uad00\uc2ec\uc744 \uac00\uc84c\ub294\uc9c0 \uc774\ud574\ud560 \uc2e4\ub9c8\ub9ac\uac00 \uc0dd\uae34\ub2e4. \ubb3c\ub860 \uc2e4\uc81c \uc774\uc6a9\uc790\uc758 \uacbd\ud5d8 \uc804\uccb4\ub97c \uc774 \uc124\ub9bd \ubaa9\uc801\ub9cc\uc73c\ub85c \uc54c \uc218\ub294 \uc5c6\ub2e4. \uc5ec\uae30\uc11c \ud655\uc778\ud558\ub294 \uac83\uc740 \uc608\uc220 \uad50\uc721\uacfc \uacf5\ub3d9\uccb4 \ud65c\ub3d9\uc744 \uc704\ud55c \uacf5\uac04\uc744 \uace0\ud5a5\uc5d0 \uc2dc\uc791\ud588\ub2e4\ub294 \uc120\ud0dd\uc774\ub2e4. \uba40\ub9ac \uc788\ub294 \ub300\ub3c4\uc2dc\uc758 \ubbf8\uc220\uad00\uc5d0 \uc791\ud488\uc774 \uac78\ub9ac\ub294 \uac83\uacfc \uc790\uae30\uac00 \uc790\ub780 \ub9c8\uc744\uc5d0\uc11c \uc608\uc220\uc744 \ub9cc\ub0a0 \uc218 \uc788\uac8c \ud558\ub294 \uc77c\uc774, \ud55c \uc0ac\ub78c\uc758 \ud65c\ub3d9 \uc548\uc5d0\uc11c \ub098\ub780\ud788 \uc774\uc5b4\uc9c8 \uc218 \uc788\uc5c8\ub2e4. \ubb38\ud654\uc13c\ud130\uac00 \uad50\uc721\uacfc \ub9c8\uc744 \ud589\uc0ac\ub97c \uc704\ud574 \uc2dc\uc791\ub418\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc778\uc0c1\uc801\uc774\ub2e4. \uc608\uc220\uc744 \uba40\ub9ac \uc788\ub294 \uc804\uc2dc\uc7a5\uc5d0\uc11c\ub9cc \ub9cc\ub098\ub294 \ub300\uc2e0 \uc790\uc2e0\uc774 \uc790\ub780 \uacf3\uc5d0\uc11c \ubc30\uc6b0\uace0 \ubaa8\uc77c \uc218 \uc788\ub3c4\ub85d \ud558\ub294 \uc120\ud0dd\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \uc774 \ud654\uac00\ub294 \uadf8\ub9bc\ubfd0 \uc544\ub2c8\ub77c \uae00\uacfc \uc2dc, \uad50\uc721\uacfc \uc870\uac01\uc5d0\uc11c\ub3c4 \ud65c\ub3d9\ud588\ub2e4. \uace0\ud5a5\uc758 \uacf5\uac04\uc740 \uadf8 \uc5ec\ub7ec \uc77c\uc744 \ub2f4\uc744 \ub610 \ud558\ub098\uc758 \ud615\ud0dc\ub85c \uc77d\ud78c\ub2e4. \uadf8\ub9bc \ud55c \uc810\uc744 \ub0a8\uae30\ub294 \uac83\uacfc \ud568\uaed8, \ub2e4\uc74c \uc0ac\ub78c\uc774 \ubb34\uc5b8\uac00\ub97c \uc2dc\uc791\ud560 \uc790\ub9ac\ub3c4 \ub9cc\ub4e4\uace0 \uc2f6\uc5c8\ub358 \uac83\uc774\ub2e4."}, {"id": "new-york-before-new-amsterdam", "title": "\ub274\uc695 \u2014 \ud55c\ub54c\ub294 \ub274\uc554\uc2a4\ud14c\ub974\ub2f4\uc774\uc5c8\ub2e4", "summary": "1664\ub144\uc758 \uc2e4\uc81c \uadf8\ub9bc\uc5d0\uc11c \ucd9c\ubc1c\ud574 \ub124\ub35c\ub780\ub4dc \uc2dd\ubbfc \ub3c4\uc2dc\uc758 \uad50\uc5ed\uacfc \uc774\ub984 \ubcc0\ud654, \uac00\ub824\uc9c4 \ub178\ub3d9\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "cities", "category_title": "Cities", "subcategory": "Americas", "url": "stories/new-york-before-new-amsterdam/index.html", "image": "media/new-york-before-new-amsterdam.png", "alt": "1664\ub144 \ube59\ubcf8\uc2a4\uc758 \ub274\uc554\uc2a4\ud14c\ub974\ub2f4 \uadf8\ub9bc. \ubb3c\uac00\uc758 \ub0ae\uc740 \uac74\ubb3c\uacfc \uc55e\ucabd\uc758 \ubc30\ub4e4.", "text": "\ub274\uc695 \u2014 \ud55c\ub54c\ub294 \ub274\uc554\uc2a4\ud14c\ub974\ub2f4\uc774\uc5c8\ub2e4 \ub3c4\uc2dc\uc758 \uc774\ub984\uc744 \ubc14\uafbc \ubc30\uc640 \uad50\uc5ed, \uadf8\ub9ac\uace0 \uc131\ubcbd 1664\ub144\uc758 \uc2e4\uc81c \uadf8\ub9bc\uc5d0\uc11c \ucd9c\ubc1c\ud574 \ub124\ub35c\ub780\ub4dc \uc2dd\ubbfc \ub3c4\uc2dc\uc758 \uad50\uc5ed\uacfc \uc774\ub984 \ubcc0\ud654, \uac00\ub824\uc9c4 \ub178\ub3d9\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Americas \ub3c4\uc2dc \ub274\uc695\uc774\ub77c\ub294 \uc774\ub984\uc740 \ub108\ubb34 \uc775\uc219\ud574\uc11c \ucc98\uc74c\ubd80\ud130 \uadf8 \uc774\ub984\uc774\uc5c8\uc744 \uac83\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \uadf8\ub7ec\ub098 \ub9e8\ud574\ud2bc \ub0a8\ucabd\uc5d0 \uc790\ub9ac\ud55c \ucd08\uae30\uc758 \uc720\ub7fd \uc2dd\ubbfc \ub3c4\uc2dc\ub294 \ub274\uc554\uc2a4\ud14c\ub974\ub2f4\uc73c\ub85c \ubd88\ub838\ub2e4. \uc554\uc2a4\ud14c\ub974\ub2f4\uc5d0 \uc0c8\ub85c\uc6b4 \uacf3\uc744 \ub73b\ud558\ub294 \ub9d0\uc744 \ubd99\uc778 \uc774\ub984\uc774\ub2e4. \ub3c4\uc2dc \uc774\ub984\uc5d0 \ubc14\ub2e4 \uac74\ub108\uc758 \uace0\ud5a5\uc774 \ub4e4\uc5b4 \uc788\uc5c8\ub358 \uc148\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\uc740 \ub124\ub35c\ub780\ub4dc\uc758 \ud654\uac00\uc774\uc790 \uc9c0\ub3c4 \uc81c\uc791\uc790 \uc694\ud558\ub124\uc2a4 \ube59\ubcf8\uc2a4\uac00 1664\ub144\uc5d0 \uadf8\ub9b0 \ub3c4\uc2dc\uc758 \ubaa8\uc2b5\uc774\ub2e4. \ubb3c\uac00\uc758 \ubc30\uc640 \ub0ae\uc740 \uac74\ubb3c\ub4e4\uc744 \ubcf4\uba74 \uc624\ub298\uc758 \ub192\uc740 \ube4c\ub529 \uc232\uacfc\ub294 \ub2e4\ub978 \ud48d\uacbd\uc774 \uc5f4\ub9b0\ub2e4. \uadf8 \uc791\uc740 \ud574\uc548\uc120\uc5d0 \uc5ec\ub7ec \ub300\ub959\uc758 \uad00\uacc4\uac00 \uacb9\uccd0 \uc788\uc5c8\ub2e4. \uad50\uc7ac\ub294 \ub124\ub35c\ub780\ub4dc\uc778\ub4e4\uc774 1624\ub144 \uc624\ub298\ub0a0 \ub9e8\ud574\ud2bc \uc12c\uc758 \ub0a8\ucabd\uc5d0 \ub274\uc554\uc2a4\ud14c\ub974\ub2f4\uc744 \uc138\uc6e0\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc774\uac83\uc740 \uc0ac\ub78c\uc774 \uc5c6\ub358 \uc12c\uc5d0\uc11c \ub3c4\uc2dc\uc758 \uc5ed\uc0ac\uac00 \ucc98\uc74c \uc2dc\uc791\ub418\uc5c8\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \uc720\ub7fd\uc778\uc774 \uc624\uae30 \uc804\ubd80\ud130 \uc6d0\uc8fc\ubbfc \uacf5\ub3d9\uccb4\uc758 \ub545\uacfc \uc0dd\ud65c\uc774 \uc788\uc5c8\ub2e4. \uc2dd\ubbfc \ub3c4\uc2dc\uc758 \uc124\ub9bd \uc5f0\ub3c4\ub294 \ud2b9\uc815 \uc138\ub825\uc774 \uac70\uc810\uc744 \ub9cc\ub4e0 \ub54c\ub97c \uc54c\ub824 \uc900\ub2e4. \uadf8 \uc774\uc804\uc758 \uc0ac\ub78c\uacfc \uc7a5\uc18c\uae4c\uc9c0 \uc9c0\uc6cc \uc8fc\ub294 \uc22b\uc790\ub294 \uc544\ub2c8\ub2e4. \ub3c4\uc2dc\uc758 \uc61b \uc774\ub984\uc744 \uc77d\uc744 \ub54c\ub3c4 \ub204\uad6c\uc758 \uae30\ub85d\uc5d0\uc11c \ubd99\uc778 \uc774\ub984\uc778\uc9c0 \ubb3c\uc5b4\ubcfc \ud544\uc694\uac00 \uc788\ub2e4. \uac19\uc740 \ub545\uc5d0 \uad00\ud55c \uc774\uc57c\uae30\uac00 \ud558\ub098\uc758 \uc5b8\uc5b4\ub85c\ub9cc \uc2dc\uc791\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub124\ub35c\ub780\ub4dc \uc2dd\ubbfc\uc790\ub4e4\uc758 \uac70\uc8fc\uc9c0\ub294 \ub274\uc554\uc2a4\ud14c\ub974\ub2f4\uc5d0\uc11c \ud5c8\ub4dc\uc2a8\uac15 \uacc4\uace1\uc744 \ub530\ub77c \ubd81\ucabd\uc73c\ub85c \uc774\uc5b4\uc84c\ub2e4. \uad50\uc7ac\ub294 \ub18d\uc5c5\ub3c4 \uc774\ub8e8\uc5b4\uc84c\uc9c0\ub9cc \ubaa8\ud53c \uad50\uc5ed\uc774 \uc911\uc694\ud55c \uc218\uc785\uc6d0\uc774\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud56d\uad6c\uc5d0 \ub3c4\ucc29\ud55c \ubb3c\uac74\uc740 \ubc14\ub2e4 \ubc14\ub85c \uc606\uc5d0\uc11c\ub9cc \ub9cc\ub4e4\uc5b4\uc9c4 \uac83\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc9c0\uae08\uc758 \ub274\uc695\uc744 \uae08\uc735\uacfc \ubb38\ud654\uc758 \ub3c4\uc2dc\ub85c \uba3c\uc800 \ub5a0\uc62c\ub9ac\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \ub3d9\ubb3c\uc758 \ubaa8\ud53c\uac00 \ub0af\uc120 \ucd9c\ubc1c\uc810\ucc98\ub7fc \ubcf4\uc778\ub2e4. \ud558\uc9c0\ub9cc \ucd08\uae30\uc758 \uad50\uc5ed\uc740 \ub0b4\ub959\uacfc \uac15, \ub300\uc11c\uc591\uc744 \uc5f0\uacb0\ud588\ub2e4. \uadf8\ub9bc \uc18d\uc758 \ubc30 \ud55c \ucc99\uc744 \ubcfc \ub54c\ub3c4 \uadf8 \ubc30\uc5d0 \uc2e4\ub9b4 \ubb3c\uac74\uc774 \uc5b4\ub514\uc11c \uc654\ub294\uc9c0 \uc0dd\uac01\ud558\uba74 \ub3c4\uc2dc\uc758 \uc9c0\ub3c4\uac00 \ub113\uc5b4\uc9c4\ub2e4. \ucd08\uae30\uc5d0\ub294 \ubaa8\ud53c\uc640 \uc720\ub7fd\uc758 \uae08\uc18d \ub3c4\uad6c, \ubaa8\uc9c1\ubb3c, \ubb34\uae30 \ub4f1\uc744 \uad50\ud658\ud558\ub294 \uad00\uacc4\uac00 \uc788\uc5c8\ub2e4. \uadf8\ub7ec\ub098 \uad50\uc5ed\uc774 \uc774\uc5b4\uc84c\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uace7\ubc14\ub85c \ud3c9\ub4f1\ud558\uace0 \ud3c9\ud654\ub85c\uc6b4 \uacf5\uc874\uc73c\ub85c \ubc14\uafc0 \uc218\ub294 \uc5c6\ub2e4. \uc2dd\ubbfc \uc9c0\ubc30\uc758 \ud655\ub300\uc640 \uc6d0\uc8fc\ubbfc\uc5d0 \ub300\ud55c \uc694\uad6c\ub294 \ucda9\ub3cc\ub85c \uc774\uc5b4\uc84c\ub2e4. \uad50\uc7ac\ub294 \ub124\ub35c\ub780\ub4dc\uc778\ub4e4\uc774 \uc790\uc2e0\ub4e4\uc774 \uc81c\uacf5\ud588\ub2e4\uace0 \uc5ec\uae34 \ud61c\ud0dd\uc5d0 \ub300\uac00\ub97c \uc694\uad6c\ud558\uba70 \uac08\ub4f1\uc774 \ucee4\uc84c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc774 \ub300\ubaa9\uc5d0\uc11c\ub294 \uac70\ub798\uc758 \ubaa9\ub85d\ubcf4\ub2e4 \ub204\uac00 \uc870\uac74\uc744 \uc815\ud558\ub824 \ud588\ub294\uc9c0\uac00 \uc911\uc694\ud558\ub2e4. \uc11c\ub85c \ubb3c\uac74\uc744 \uc8fc\uace0\ubc1b\uc558\ub2e4\uace0 \ud798\uc758 \ucc28\uc774\ub098 \ub545\uc744 \ub458\ub7ec\uc2fc \ubb38\uc81c\uac00 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ub3c4\uc2dc\ub97c \ubc29\uc5b4\ud558\uae30 \uc704\ud55c \uc2dc\uc124\uc740 \ub2f9\uc2dc \uac70\uc8fc\uc9c0\uc758 \uacbd\uacc4\uc5d0 \uc138\uc6cc\uc84c\ub2e4. \uad50\uc7ac\ub294 \ub124\ub35c\ub780\ub4dc\uc778\ub4e4\uc774 \ub178\uc608\ud654\ub41c \uc544\ud504\ub9ac\uce74\uc778\ub4e4\uc5d0\uac8c \uc774 \ubc29\uc5b4 \uc2dc\uc124\uc744 \uc9d3\ub3c4\ub85d \uac15\uc694\ud588\ub2e4\uace0 \uae30\ub85d\ud55c\ub2e4. \uadf8 \ubcbd\uc744 \ub530\ub77c \ub09c \uae38\uc774 \uc6d4\uc2a4\ud2b8\ub9ac\ud2b8\ub77c\ub294 \uc774\ub984\uc73c\ub85c \ubd88\ub838\ub2e4. \uc624\ub298\uc758 \uae08\uc735\uac00\ub97c \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \uc774\ub984 \ub4a4\uc5d0 \uac15\uc81c \ub178\ub3d9\uc758 \uc5ed\uc0ac\uac00 \uc788\ub294 \uac83\uc774\ub2e4. \uae38 \uc774\ub984\uc758 \uc720\ub798\ub97c \uc548\ub2e4\ub294 \uac83\uc740 \uc7ac\ubbf8\uc788\ub294 \ub9d0\ud480\uc774\ub9cc\uc740 \uc544\ub2c8\ub2e4. \ub204\uac00 \ud798\ub4e0 \uc77c\uc744 \ud588\uc73c\uba70 \ub204\uad6c\uc758 \uc774\ub984\uc740 \uae30\ub150\ub418\uc9c0 \uc54a\uc558\ub294\uc9c0 \ub3cc\uc544\ubcfc \uae30\ud68c\uc774\uae30\ub3c4 \ud558\ub2e4. \ub3c4\uc2dc\uc758 \uc720\uba85\ud55c \uc8fc\uc18c\uc5d0\ub294 \uc54c\ub824\uc9c4 \uc131\uacf5\ub2f4 \ubc16\uc758 \uc2dc\uac04\uc774 \ub4e4\uc5b4 \uc788\ub2e4. 1664\ub144 \uc601\uad6d\uc758 \uad70\uc0ac \uc6d0\uc815\ub300\uac00 \ub274\uc554\uc2a4\ud14c\ub974\ub2f4\uc5d0 \ub3c4\ucc29\ud588\ub2e4. \ub124\ub35c\ub780\ub4dc\uc640 \uc601\uad6d \uc0ac\uc774\uc758 \ub354 \ud070 \uacbd\uc7c1 \uc18d\uc5d0\uc11c \ubc8c\uc5b4\uc9c4 \uc77c\uc774\uc5c8\ub2e4. \uad50\uc7ac\ub294 \ubc29\uc5b4\uac00 \uc5b4\ub835\ub2e4\uace0 \ubcf8 \ub124\ub35c\ub780\ub4dc \uce21\uc774 \ud56d\ubcf5\ud588\uace0, \ub3c4\uc2dc \uc774\ub984\uc774 \ub274\uc695\uc73c\ub85c \ubc14\ub00c\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc0c8 \uc774\ub984\uc740 \uc6d0\uc815\uc744 \uc870\uc9c1\ud55c \uc694\ud06c \uacf5\uc791\uc744 \uae30\ub9ac\ub294 \uac83\uc774\uc5c8\ub2e4. \uc774\ub984 \ubcc0\uacbd\uc740 \ub2e8\uc21c\ud55c \uc0c8 \uac04\ud310\uc774 \uc544\ub2c8\ub77c \uc5b4\ub5a4 \uad8c\ub825\uc774 \uadf8 \uc7a5\uc18c\ub97c \ucc28\uc9c0\ud588\ub294\uc9c0 \ub4dc\ub7ec\ub0b4\ub294 \ud45c\uc2dc\uc600\ub2e4. \ub2e4\ub9cc \uadf8 \uc21c\uac04 \uc8fc\ubbfc\uc758 \ubaa8\ub4e0 \uc2b5\uad00\uacfc \uc5b8\uc5b4, \uc9d1\uc758 \ubaa8\uc2b5\uae4c\uc9c0 \ud55c \ubc88\uc5d0 \ub2ec\ub77c\uc84c\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub3c4\uc2dc\uc758 \uc774\ub984\uc774 \ub2ec\ub77c\uc9c0\uba74 \uc5ed\uc0ac\uac00 \ub450 \ub3d9\uac15 \ub09c \uac83\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \ubc30\uac00 \ub4dc\ub098\ub4dc\ub294 \uc9c0\ub9ac\uc640 \uc774\ubbf8 \ud615\uc131\ub41c \uac70\ub798 \uad00\uacc4, \uadf8\uacf3\uc5d0 \uc0ac\ub294 \uc0ac\ub78c\ub4e4\uc740 \uc0c8 \uad8c\ub825 \uc544\ub798\uc5d0\uc11c\ub3c4 \uc774\uc5b4\uc9c0\ub294 \uc870\uac74\uc774\uc5c8\ub2e4. \uc9c0\ubc30\uc790\uac00 \ubc14\ub00c\ub294 \uc77c\uacfc \uc0dd\ud65c\uc758 \ubaa8\ub4e0 \uc694\uc18c\uac00 \uad50\uccb4\ub418\ub294 \uc77c\uc740 \uac19\uc740 \uc18d\ub3c4\ub85c \uc77c\uc5b4\ub098\uc9c0 \uc54a\ub294\ub2e4. \uc774 \uc810\uc744 \uc0dd\uac01\ud558\uba74 \ub274\uc554\uc2a4\ud14c\ub974\ub2f4\uc740 \uc624\ub298\uc758 \ub274\uc695\uacfc \ubb34\uad00\ud55c \uc0ac\ub77c\uc9c4 \ub3d9\ub124\uac00 \uc544\ub2c8\ub2e4. \uadf8\ub807\ub2e4\uace0 \ud604\ub300 \ub3c4\uc2dc\uc758 \uc131\uaca9\uc744 \ubaa8\ub450 \ucd08\uae30 \uc2dd\ubbfc\uc9c0\uc5d0\uc11c \uc124\uba85\ud560 \uc218\ub3c4 \uc5c6\ub2e4. \uc624\ub79c \ubcc0\ud654 \uac00\uc6b4\ub370 \ud558\ub098\uc758 \uce35\uc744 \uc77d\ub294 \uac83\uc774\ub2e4. \uc61b \uc774\ub984\uc740 \uadf8 \uce35\uc73c\ub85c \ub4e4\uc5b4\uac00\ub294 \uc190\uc7a1\uc774\uac00 \ub41c\ub2e4. \ube59\ubcf8\uc2a4\uc758 \uadf8\ub9bc\uc5d0\uc11c\ub294 \ubb3c\uacfc \uac74\ubb3c \uc0ac\uc774\uc758 \uad00\uacc4\ub97c \uba3c\uc800 \uc0b4\ud3b4\ubcf4\uc790. \ubc14\ub2e4 \ucabd\uc5d0\uc11c \ubc14\ub77c\ubcf4\ub294 \ub3c4\uc2dc\uc758 \ubaa8\uc2b5\uc5d0\ub294 \ud56d\uad6c\uc758 \uc131\uaca9\uc774 \uc798 \ub4dc\ub7ec\ub09c\ub2e4. \uc624\ub298\uc758 \uc9c0\ub3c4\uc5d0\uc11c \uc775\uc219\ud55c \uac70\ub9ac\uc640 \uac74\ubb3c \ud558\ub098\ud558\ub098\ub97c \uadf8\ub300\ub85c \ucc3e\uc73c\ub824 \ud558\uae30\ubcf4\ub2e4 \ub2f9\uc2dc \ud654\uac00\uac00 \uc5b4\ub5a4 \uc724\uacfd\uc744 \ubcf4\uc5ec \uc8fc\uc5c8\ub294\uc9c0 \ubcf4\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uadf8\ub9bc\uc740 \uc0ac\uc9c4\uc774\ub098 \uc815\ubc00 \uce21\ub7c9\ub3c4\uc640 \uac19\uc9c0 \uc54a\ub2e4. \ud654\uac00\uc758 \uc2dc\uc810\uacfc \ud45c\ud604\uc744 \uac70\uce5c \uc790\ub8cc\ub2e4. \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc6d0\uc8fc\ubbfc\uc758 \uc0dd\ud65c\uacfc \uac15\uc81c \ub178\ub3d9\uae4c\uc9c0 \uc774 \ud654\uba74 \ud55c \uc7a5\uc774 \ubaa8\ub450 \ub2f4\uc9c0\ub294 \uc54a\ub294\ub2e4. \uadf8\ub798\uc11c \uadf8\ub9bc\uc744 \uac10\uc0c1\ud558\ub294 \uc77c\uacfc \uc5ed\uc0ac \uae30\ub85d\uc744 \ud568\uaed8 \uc77d\ub294 \uc77c\uc774 \uc11c\ub85c\ub97c \ubcf4\uc644\ud55c\ub2e4. \ub274\uc695\uc758 \uc61b \uc774\ub984\uc740 \uc720\ub7fd\uc758 \ub3c4\uc2dc \uc774\ub984\uc774 \ubc14\ub2e4\ub97c \uac74\ub108\uc628 \uc774\uc57c\uae30\uc774\uba74\uc11c, \uad50\uc5ed\uacfc \uc2dd\ubbfc \uacbd\uc7c1\uc774 \uacb9\uce5c \uc774\uc57c\uae30\ub2e4. \ubaa8\ud53c\uac00 \uc624\uac04 \uac15\uacfc \ud56d\uad6c, \ub178\uc608\ud654\ub41c \uc774\ub4e4\uc774 \uc138\uc6b4 \ubc29\uc5b4 \uc2dc\uc124, \uc601\uad6d \uc6d0\uc815\ub300\uac00 \ub4e4\uc5b4\uc628 \ubb3c\uae38\uc774 \uc774\ub984\uc758 \ubcc0\ud654 \ub4a4\uc5d0 \ub193\uc5ec \uc788\ub2e4. \ub2e4\uc74c\uc5d0 \ub3c4\uc2dc \uc774\ub984\uc758 \uc720\ub798\ub97c \ub9cc\ub098\uba74 \ub204\uac00 \ubd99\uc600\ub294\uc9c0\ub9cc \ubb3b\uc9c0 \ub9d0\uace0 \uadf8 \uc774\uc804\uc5d0\ub294 \ub204\uac00 \uc0b4\uc558\ub294\uc9c0\ub3c4 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc9e7\uc740 \uc774\ub984\uc740 \ub9ce\uc740 \uc2dc\uac04\uc744 \uc811\uc5b4 \ub123\uace0 \uc788\ub2e4. \ub274\uc554\uc2a4\ud14c\ub974\ub2f4\uc774\ub77c\ub294 \uc624\ub798\ub41c \uc774\ub984\uc744 \ud3b4 \ubcf4\ub294 \uc77c\uc740 \uc775\uc219\ud55c \ub274\uc695\uc744 \uc870\uae08 \ub354 \ub113\uac8c \uc774\ud574\ud558\ub294 \uc2dc\uc791\uc774 \ub41c\ub2e4."}, {"id": "palace-roof-pangolin", "title": "\uad81\uad90 \uc9c0\ubd95 \uc704\uc5d0\ub294 \ub0af\uc120 \ub3d9\ubb3c\uc774 \uc549\uc544 \uc788\uc5c8\ub2e4", "summary": "\ub192\uc740 \uc9c0\ubd95\uc5d0\uc11c \uba40\ub9ac \ubcf4\uc774\ub358 \uc791\uc740 \uc870\uac01\uc0c1\uc744 \uac00\uae4c\uc774 \ubd05\ub2c8\ub2e4.", "category": "cities", "category_title": "Cities", "subcategory": "Asia", "url": "stories/palace-roof-pangolin/index.html", "image": "media/palace-roof-pangolin.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc7a1\uc0c1 '\ucc9c\uc0b0\uac11' \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uad81\uad90 \uc9c0\ubd95 \uc704\uc5d0\ub294 \ub0af\uc120 \ub3d9\ubb3c\uc774 \uc549\uc544 \uc788\uc5c8\ub2e4 \uadfc\uc815\ubb38\uc5d0\uc11c \ub0b4\ub824\uc628 \ucc9c\uc0b0\uac11 \uc7a1\uc0c1 \ub192\uc740 \uc9c0\ubd95\uc5d0\uc11c \uba40\ub9ac \ubcf4\uc774\ub358 \uc791\uc740 \uc870\uac01\uc0c1\uc744 \uac00\uae4c\uc774 \ubd05\ub2c8\ub2e4. Asia \ub3c4\uc2dc \uad81\uad90 \uc9c0\ubd95\uc744 \uc62c\ub824\ub2e4\ubcf4\uba74 \ub05d\ubd80\ubd84\uc744 \ub530\ub77c \uc791\uc740 \ud615\uc0c1\ub4e4\uc774 \ub298\uc5b4\uc11c \uc788\ub2e4. \uba40\ub9ac\uc11c\ub294 \uc724\uacfd\ub9cc \ubcf4\uc5ec\uc11c \ubaa8\ub450 \ube44\uc2b7\ud55c \uc870\uac01\ucc98\ub7fc \ub290\uaef4\uc9c0\uae30 \uc27d\ub2e4. \uac00\uae4c\uc774 \ubcf4\uba74 \uadf8\uc911 \ud558\ub098\ub294 \uad75\uc740 \ubaa9\uacfc \uc791\uc740 \uc5bc\uad74\uc744 \uac00\uc9c4 \ub0af\uc120 \ubaa8\uc2b5\uc774\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \ucc9c\uc0b0\uac11\uc774\ub77c\uace0 \uc18c\uac1c\ud558\ub294 \uc7a1\uc0c1\uc774\ub2e4. \uacbd\ubcf5\uad81 \uadfc\uc815\ubb38 \uc9c0\ubd95\uc758 \ucd94\ub140\ub9c8\ub8e8\uc5d0 \uc62c\ub838\ub358 \uac83 \uac00\uc6b4\ub370 \ud558\ub098\ub2e4. \uc6d0\ub798\ub294 \uace0\uac1c\ub97c \ud55c\ucc38 \ub4e4\uc5b4\uc57c \ubcf4\uc558\uc744 \ubb3c\uac74\uc744 \uc774\uc81c \uc0ac\uc9c4\uc5d0\uc11c \ub208\ub192\uc774\ub85c \ub9cc\ub09c\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc740 \uc774 \uc7a1\uc0c1\uc5d0 \ubfd4\uacfc \ube44\ub298\uc774 \uc788\uace0 \ub4f1\uc5d0 \uaddc\uce59\uc801\uc778 \ub3cc\uae30\uac00 \ub3cb\uc558\ub2e4\uace0 \uc54c\ub824 \uc900\ub2e4. \uc0ac\uc9c4\uc744 \ubcf4\uba74 \uc5bc\uad74\ubcf4\ub2e4 \ubab8\uc744 \ub530\ub77c \uc774\uc5b4\uc9c0\ub294 \uad74\uace1\uc774 \uba3c\uc800 \uc778\uc0c1\uc5d0 \ub0a8\uc744 \uc218\ub3c4 \uc788\ub2e4. \ud55c \ubc29\ud5a5\uc5d0\uc11c\ub9cc \ubcf4\uace0 \ub3d9\ubb3c \uc774\ub984 \ub9de\ud788\uae30\ub97c \ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ucc9c\uc0b0\uac11\uc744 \ud615\uc0c1\ud654\ud55c \uc9c0\ubd95 \uc7a5\uc2dd\uc774\ub77c\ub294 \ubc15\ubb3c\uad00\uc758 \uba85\uce6d\uacfc \uc2e4\uc81c \uc870\uac01\uc758 \ud2b9\uc9d5\uc744 \ud568\uaed8 \uc77d\uc73c\uba74 \ub41c\ub2e4. \uc0b4\uc544 \uc788\ub294 \ub3d9\ubb3c\uc758 \ubab8\uc744 \uc815\ud655\ud788 \uc7ac\ud604\ud55c \ubaa8\ud615\uc73c\ub85c \uc0dd\uac01\ud560 \ubb3c\uac74\uc740 \uc544\ub2c8\ub2e4. \uc18c\uc7a5\ud488 \uc124\uba85\uc740 1867\ub144 \uadfc\uc815\ubb38\uc744 \ub2e4\uc2dc \uc138\uc6b8 \ub54c \ub610\ub294 \uadf8 \uc774\ud6c4\uc5d0 \uc9c0\ubd95\uc5d0 \uc62c\ub9b0 \uc7a1\uc0c1\uc774\ub77c\uace0 \ud55c\ub2e4. \ub531 \ud55c \ud574\uc5d0 \uc81c\uc791\ub418\uc5c8\ub2e4\uace0 \ubabb \ubc15\ub294 \ub300\uc2e0 \uac00\ub2a5\ud55c \uc2dc\uae30\ub97c \uc5f4\uc5b4 \ub193\uc740 \uc124\uba85\uc774\ub2e4. \uc774 \ucc28\uc774\ub294 \uc791\uc544 \ubcf4\uc5ec\ub3c4 \ubb3c\uac74\uc758 \uc774\ub825\uc744 \uc774\ud574\ud560 \ub54c \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \uac74\ubb3c\uc774 \ub2e4\uc2dc \uc138\uc6cc\uc9c4 \ud574\ub97c \uc548\ub2e4\uace0 \uadf8 \uc704\uc758 \ubaa8\ub4e0 \uc7a5\uc2dd\uc774 \uadf8\ub0a0 \ud568\uaed8 \ub9cc\ub4e4\uc5b4\uc84c\ub2e4\uace0 \uc815\ud560 \uc218\ub294 \uc5c6\ub294 \uac83\uc774\ub2e4. \uc775\uc219\ud55c \uad81\uad90\uc5d0\ub3c4 \uc774\ub807\uac8c \uc870\uae08\uc529 \ub530\ub85c \ud655\uc778\ud574\uc57c \ud560 \uc2dc\uac04\uc774 \ub0a8\uc544 \uc788\ub2e4. \ucd94\ub140\ub9c8\ub8e8\ub294 \uc9c0\ubd95 \ub05d\uc744 \ud5a5\ud574 \uc2dc\uc120\uc774 \ud758\ub7ec\uac00\ub294 \uc790\ub9ac\ub2e4. \uadf8 \uc704\uc5d0 \ub193\uc778 \ud615\uc0c1\uc740 \uc2e4\ub0b4\uc5d0\uc11c \uc190\uc5d0 \ub4e4\uace0 \ubcf4\ub294 \uc870\uac01\uacfc \ub2e4\ub978 \uc870\uac74\uc744 \uac00\uc9c4\ub2e4. \ubcf4\ub294 \uc0ac\ub78c\uc740 \ub300\uac1c \uc544\ub798\uc5d0\uc11c \uc62c\ub824\ub2e4\ubcf4\uace0, \uc138\ubd80\ubcf4\ub2e4 \uc724\uacfd\uc744 \uba3c\uc800 \ub9cc\ub09c\ub2e4. \ud070 \uac74\ucd95\ubb3c\uc758 \uac00\uc7a5\uc790\ub9ac\uc5d0\uc11c \uc791\uc740 \uc870\uac01\uc774 \uc5b4\ub5bb\uac8c \ub208\uc5d0 \ub4e4\uc5b4\uc624\ub294\uc9c0 \uc0dd\uac01\ud558\uba74 \uc7a5\uc2dd\uc758 \uc790\ub9ac\uac00 \uad6c\uccb4\uc801\uc73c\ub85c \ub290\uaef4\uc9c4\ub2e4. \uc624\ub298 \uc18c\uc7a5\ud488 \uc0ac\uc9c4\uc73c\ub85c \ubcf4\ub294 \ubb3c\uac74\uc740 \uadf8 \uac70\ub9ac\ub97c \ud06c\uac8c \uc904\uc5ec \uc900\ub2e4. \uba40\ub9ac\uc11c\ub294 \ud55c \ub369\uc5b4\ub9ac\uc600\uc744 \ubab8\uc774 \uad75\uc740 \ubaa9\uacfc \uc791\uc740 \uc5bc\uad74, \ub4f1 \uc704\uc758 \ub3cc\uae30\ub85c \ub098\ub25c\ub2e4. \ub192\uc740 \uacf3\uc5d0\uc11c \ubcf4\uc558\ub358 \uacbd\ud5d8\uacfc \ub208\ub192\uc774\uc5d0\uc11c \uc0b4\ud3b4\ubcf4\ub294 \uacbd\ud5d8\uc774 \uac19\uc740 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubc15\ubb3c\uad00\uc758 \uc0ac\uc9c4\uc740 \uc6d0\ub798\uc758 \uc704\uce58\uc5d0\uc11c\ub294 \uc9c0\ub098\ucce4\uc744 \ud2b9\uc9d5\uc744 \uc54c\uc544\ucc28\ub9ac\uac8c \ud55c\ub2e4. \ucc9c\uc0b0\uac11\uc774\ub77c\ub294 \uba85\uce6d\uc744 \ub4e4\uc73c\uba74 \ube44\ub298\ub85c \ub36e\uc778 \uc2e4\uc81c \ub3d9\ubb3c\uc744 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc774 \uc7a1\uc0c1\uc740 \uc0dd\ubb3c\ud559 \uc218\uc5c5\uc758 \ud45c\ubcf8\uc73c\ub85c \uc81c\uc791\ub41c \uac83\uc774 \uc544\ub2c8\ub2e4. \ubc15\ubb3c\uad00\uc774 \uc18c\uac1c\ud558\ub294 \ubfd4\uacfc \ub3cc\uae30, \ubab8\uc758 \ube44\ub840\ub97c \ud568\uaed8 \ubcf4\uba74 \ub3d9\ubb3c\uc758 \ud2b9\uc9d5\uc744 \uc7a5\uc2dd\uc758 \uc5b8\uc5b4\ub85c \ubc14\uafbc \ud615\uc0c1\uc73c\ub85c \uc77d\ub294 \ud3b8\uc774 \uc790\uc5f0\uc2a4\ub7fd\ub2e4. \uc774\ub984\uc744 \ub9de\ud614\ub2e4\uace0 \uad00\ucc30\uc774 \ubaa8\ub450 \ub05d\ub098\ub294 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \uc5b4\ub290 \ubd80\ubd84\uc744 \ud06c\uac8c \ud558\uace0 \ubb34\uc5c7\uc744 \ub2e8\uc21c\ud558\uac8c \ub9cc\ub4e4\uc5c8\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uba74 \uc7ac\ubbf8\uac00 \uc0dd\uae34\ub2e4. \uc5bc\uad74\ubcf4\ub2e4 \ubaa9\uacfc \ub4f1\uc5d0 \ub354 \ub208\uc774 \uac08 \uc218\ub3c4 \uc788\uace0, \uc606\ubaa8\uc2b5\uc5d0\uc11c\ub9cc \uc724\uacfd\uc774 \ubd84\uba85\ud574\uc9c8 \uc218\ub3c4 \uc788\ub2e4. \uc774\ub294 \uc2e4\uc81c \ubb3c\uac74\uc744 \ubcf4\ub294 \ubc29\ubc95\uc5d0 \uad00\ud55c \uc81c\uc548\uc774\ub2e4. \uc870\uac01\uc758 \ubaa8\ub4e0 \ud2b9\uc9d5\ub9c8\ub2e4 \ubc18\ub4dc\uc2dc \uc228\uc740 \uc0c1\uc9d5 \ud558\ub098\ub97c \ucc3e\uc544 \ubd99\uc5ec\uc57c \ud55c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. 1867\ub144 \uc911\uac74 \ub54c \ub610\ub294 \uadf8 \uc774\ud6c4\ub77c\ub294 \uc124\uba85\uc740 \uac74\ubb3c\uacfc \ubd80\uc18d\ubb3c\uc758 \uad00\uacc4\ub97c \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uac74\ucd95\ubb3c\uc740 \ud55c \ubc88 \uc9c0\uc5b4\uc9c4 \ub4a4\uc5d0\ub3c4 \uace0\uce58\uace0 \ubc14\uafb8\ub294 \uc2dc\uac04\uc744 \uac70\uce60 \uc218 \uc788\ub2e4. \uc9c0\ubd95 \uc704 \uc7a5\uc2dd\uc774 \ud604\uc7ac\uae4c\uc9c0 \ub0a8\uc558\ub2e4\uace0 \ud574\uc11c \ucc98\uc74c\uc758 \ubaa8\ub4e0 \ubd80\uc7ac\uac00 \uac19\uc740 \uc2dc\uae30\uc5d0 \ub9cc\ub4e4\uc5b4\uc838 \uadf8\ub300\ub85c \uc774\uc5b4\uc84c\ub2e4\uace0 \ub2e8\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc18c\uc7a5\ud488 \uc124\uba85\uc5d0 \ub0a8\uc740 \ub113\uc740 \uc2dc\uae30 \ubc94\uc704\ub294 \uc815\ubcf4\uac00 \ubb34\uc758\ubbf8\ud558\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \uc5b4\ub514\uae4c\uc9c0 \ud655\uc778\ub418\uace0 \uc5b4\ub514\ubd80\ud130 \ub354 \uc54c\uc544\ubcf4\uc544\uc57c \ud558\ub294\uc9c0 \ud45c\uc2dc\ud55c \uac83\uc774\ub2e4. \uc5f0\ub3c4\ub97c \ub531 \ud558\ub098 \uc678\uc6b0\ub294 \ub300\uc2e0 \uac74\ubb3c\uc758 \uc911\uac74\uacfc \uc7a5\uc2dd\uc758 \uc124\uce58\ub97c \ub098\ub204\uc5b4 \uae30\uc5b5\ud558\uba74, \uad81\uad90\uc744 \uba48\ucd98 \uadf8\ub9bc\uc774 \uc544\ub2c8\ub77c \uc5ec\ub7ec \ubc88 \uc190\ubcf8 \uc7a5\uc18c\ub85c \ubcfc \uc218 \uc788\ub2e4. \uad81\uad90\uc744 \uac77\ub294 \uc0ac\ub78c\uc740 \ub300\ubb38\uc774 \uc5f4\uc5b4 \uc8fc\ub294 \ud1b5\ub85c\ub97c \ub530\ub77c \uc774\ub3d9\ud55c\ub2e4. \uc7a1\uc0c1\uc740 \uadf8 \ud1b5\ub85c\ubcf4\ub2e4 \ub192\uc740 \uacf3\uc5d0\uc11c \ub2e4\ub978 \uc885\ub958\uc758 \ub9ac\ub4ec\uc744 \ub9cc\ub4e0\ub2e4. \uba40\ub9ac\uc11c \uc774\uc5b4\uc9c4 \uc791\uc740 \ud615\uc0c1\ub4e4\uc774 \uc904\uc744 \uc774\ub8e8\uace0, \uac00\uae4c\uc6b4 \uc790\ub8cc\uc5d0\uc11c\ub294 \uac01\uac01 \ub2e4\ub978 \ubab8\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \uc804\uccb4 \uac74\ubb3c\uc5d0\uc11c \uc138\ubd80\ub85c \ub0b4\ub824\uc624\ub294 \ubcf4\uae30\uc640, \uc138\ubd80\ub97c \uc54c\uace0 \ub2e4\uc2dc \uc804\uccb4\ub97c \ubcf4\ub294 \ubcf4\uae30\uac00 \uc624\uac08 \uc218 \uc788\ub2e4. \uc774 \ubb3c\uac74\uc744 \ub2e4\uc74c\uc5d0 \ub5a0\uc62c\ub9b4 \ub54c\uc5d0\ub294 \uc5b4\ub824\uc6b4 \uc774\ub984 \ud558\ub098\ubcf4\ub2e4 \ubaa9\uacfc \ub4f1\uc758 \ubaa8\uc591\uc744 \uba3c\uc800 \uae30\uc5b5\ud574 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \ube44\uc2b7\ud558\uac8c \ubcf4\uc774\ub294 \uc7a5\uc2dd\uc774 \uc2e4\uc81c\ub85c\ub294 \ub2e4\ub97c \uc218 \uc788\ub2e4\ub294 \uc791\uc740 \ub2e8\uc11c\ub2e4. \uac74\ucd95\uc744 \uae4a\uac8c \ubcf8\ub2e4\ub294 \uc77c\uc740 \uc804\ubb38 \uc6a9\uc5b4\ub97c \ub9ce\uc774 \uc4f0\ub294 \uac83\ubcf4\ub2e4, \ub298 \uc9c0\ub098\uce58\ub358 \uc790\ub9ac\uc5d0\uc11c \ubb34\uc5c7\uc774 \ub2ec\ub790\ub294\uc9c0 \uc54c\uc544\ubcf4\ub294 \ub370\uc11c \uc2dc\uc791\ub418\uae30\ub3c4 \ud55c\ub2e4. \uad81\uad90\uc5d0 \uac00\uba74 \ud070 \ubb38\uc774\ub098 \ud604\ud310\uc744 \uba3c\uc800 \ucc3e\uae30 \uc27d\ub2e4. \uc774 \uc7a1\uc0c1\uc744 \ud55c \ubc88 \ubcf4\uace0 \ub098\uba74 \uc2dc\uc120\uc774 \uc9c0\ubd95\uc758 \uac00\uc7a5\uc790\ub9ac\ub85c\ub3c4 \ud5a5\ud560 \uac83 \uac19\ub2e4. \uc791\uac8c \ubcf4\uc774\ub358 \uc724\uacfd \ud558\ub098\ud558\ub098\uc5d0 \uc11c\ub85c \ub2e4\ub978 \ubaa8\uc2b5\uc774 \ub4e4\uc5b4 \uc788\uc744 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uc0c1\uc9d5\uc758 \ub73b\uc744 \uc804\ubd80 \uc678\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \uad1c\ucc2e\ub2e4. \uc624\ub298\uc740 \uad75\uc740 \ubaa9\uacfc \ub4f1 \uc704\uc758 \ub3cc\uae30 \uc815\ub3c4\ub9cc \uae30\uc5b5\ud574 \ubcf4\uc790. \uc774\ub984\uc870\ucc28 \ub0af\uc124\ub358 \uc870\uac01 \ud558\ub098\uac00 \ub2e4\uc74c \uad81\uad90 \uc0b0\ucc45\uc5d0\uc11c \ub208\uae38\uc744 \ubd99\uc7a1\ub294 \ud45c\uc9c0\uac00 \ub420 \uc218 \uc788\ub2e4."}, {"id": "pompeii-isis-small-temple", "title": "\ud3fc\ud398\uc774 \u2014 \uc774\uc9d1\ud2b8\uc758 \uc5ec\uc2e0\uc740 \uc5b4\ub5bb\uac8c \uc774\uacf3\uc5d0 \uc654\uc744\uae4c", "summary": "\ud3fc\ud398\uc774 \uc774\uc2dc\uc2a4 \uc2e0\uc804\uc758 \uc704\uce58\uc640 \uacf5\uac04\uc744 \ud1b5\ud574 \ub85c\ub9c8 \ub3c4\uc2dc \uc548\uc5d0 \ub4e4\uc5b4\uc628 \uc2e0\uc559\uacfc \uc0dd\ud65c\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "cities", "category_title": "Cities", "subcategory": "Europe", "url": "stories/pompeii-isis-small-temple/index.html", "image": "media/pompeii-isis-small-temple.png", "alt": "\ud3fc\ud398\uc774 \uc774\uc2dc\uc2a4 \uc2e0\uc804\uc758 \uacc4\ub2e8\uacfc \uae30\ub465\uc774 \ub0a8\uc740 \uc815\uba74 \uc0ac\uc9c4.", "text": "\ud3fc\ud398\uc774 \u2014 \uc774\uc9d1\ud2b8\uc758 \uc5ec\uc2e0\uc740 \uc5b4\ub5bb\uac8c \uc774\uacf3\uc5d0 \uc654\uc744\uae4c \uadf9\uc7a5 \ub4a4 \uc791\uc740 \uc2e0\uc804\uc5d0\uc11c \ub9cc\ub098\ub294 \ub85c\ub9c8 \ub3c4\uc2dc\uc758 \ub2e4\ub978 \uc5bc\uad74 \ud3fc\ud398\uc774 \uc774\uc2dc\uc2a4 \uc2e0\uc804\uc758 \uc704\uce58\uc640 \uacf5\uac04\uc744 \ud1b5\ud574 \ub85c\ub9c8 \ub3c4\uc2dc \uc548\uc5d0 \ub4e4\uc5b4\uc628 \uc2e0\uc559\uacfc \uc0dd\ud65c\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Europe \ub3c4\uc2dc \ud3fc\ud398\uc774\ub77c\uace0 \ud558\uba74 \ud654\uc0b0\uc774 \ud130\uc9c0\ub358 \ub9c8\uc9c0\ub9c9 \ub0a0\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \uc720\uc801 \uc548\uc5d0\ub294 \uadf8\ub0a0 \uc774\uc804\uc758 \uc624\ub79c \uc0dd\ud65c\ub3c4 \ub0a8\uc544 \uc788\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \uc7a5\uc0ac\ub97c \ud558\uace0 \uacf5\uc5f0\uc744 \ubcf4\uace0 \uc2e0\uc5d0\uac8c \uae30\ub3c4\ud588\ub2e4. \ub3c4\uc2dc\ub97c \uc7ac\ub09c\uc758 \uc7a5\uba74 \ud558\ub098\ub85c\ub9cc \uae30\uc5b5\ud558\uba74 \uadf8\ub4e4\uc774 \ud3c9\uc18c \ubb34\uc5c7\uc744 \ubbff\uc5c8\ub294\uc9c0\ub294 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uc791\uc740 \uc774\uc2dc\uc2a4 \uc2e0\uc804\uc740 \uc774\ub7f0 \uc77c\uc0c1\uc73c\ub85c \ub4e4\uc5b4\uac00\ub294 \uc785\uad6c\uac00 \ub41c\ub2e4. \uc774\uc9d1\ud2b8\uc5d0\uc11c \uc628 \uc5ec\uc2e0\uc744 \ub85c\ub9c8\uc758 \uc774\ud0c8\ub9ac\uc544 \ub3c4\uc2dc\uc5d0\uc11c \ub9cc\ub09c\ub2e4\ub294 \uc0ac\uc2e4\ubd80\ud130 \ud765\ubbf8\ub86d\ub2e4. \uc2e0\uc804\uc758 \uaddc\ubaa8\uc640 \uadf9\uc7a5 \ub4a4\ub77c\ub294 \uc704\uce58\ub97c \uc0b4\ud53c\uba74 \ub0af\uc120 \uc2e0\uc559\uc774 \ub3c4\uc2dc \uc548\uc5d0\uc11c \ucc28\uc9c0\ud55c \uc790\ub9ac\uac00 \uc870\uae08\uc529 \ub4dc\ub7ec\ub09c\ub2e4. \ub85c\ub9c8\uc81c\uad6d\uc5d0\ub294 \uc5ec\ub7ec \uc9c0\uc5ed\uc758 \uc885\uad50\uac00 \ud568\uaed8 \uc874\uc7ac\ud588\ub2e4. \uc774\uc2dc\uc2a4 \uc22d\ubc30\ub294 \uc774\uc9d1\ud2b8\uc5d0\uc11c \uc2dc\uc791\ud574 \uae30\uc6d0\uc804 1\uc138\uae30 \ubb34\ub835 \ub85c\ub9c8\uc81c\uad6d \uc11c\ubd80\uc5d0\uc11c\ub3c4 \ud37c\uc84c\ub2e4. \uc0ac\ub78c\uc774 \uc774\ub3d9\ud558\uace0 \uc11c\ub85c \ub2e4\ub978 \uc9c0\uc5ed\uc774 \uc5f0\uacb0\ub418\uba74 \ubb3c\uac74\ubfd0 \uc544\ub2c8\ub77c \uae30\ub3c4\ud558\ub294 \ubc29\uc2dd\ub3c4 \uc804\ud574\uc9c8 \uc218 \uc788\ub2e4. \uc774\uc2dc\uc2a4\ub294 \uc2e0\uc790\ub4e4\uc5d0\uac8c \ud070 \ud798\uc744 \uc9c0\ub2cc \uc5ec\uc2e0\uc73c\ub85c \ubc1b\uc544\ub4e4\uc5ec\uc84c\ub2e4. \ub85c\ub9c8 \uc18c\uc124 \u300a\ud669\uae08 \ub2f9\ub098\uadc0\u300b\uc5d0\ub3c4 \uc8fc\uc778\uacf5\uc744 \uad6c\ud558\ub294 \uc874\uc7ac\ub85c \ub4f1\uc7a5\ud55c\ub2e4. \uc18c\uc124 \uc18d \uc7a5\uba74\uc744 \uc2e4\uc81c \uc0ac\uac74\uc73c\ub85c \ubcfc \uc218\ub294 \uc5c6\uc9c0\ub9cc, \ub2f9\uc2dc \uc0ac\ub78c\ub4e4\uc774 \uc774 \uc5ec\uc2e0\uc744 \uc5b4\ub5a4 \ub2a5\ub825\uacfc \uc5f0\uacb0\ud588\ub294\uc9c0 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub294 \uc790\ub8cc\ub2e4. \ud3fc\ud398\uc774\uc758 \uc774\uc2dc\uc2a4 \uc2e0\uc804\uc740 \ub3c4\uc2dc \uadf9\uc7a5 \ubc14\ub85c \ub4a4\uc5d0 \uc788\uc5c8\ub2e4. \ub2e4\ub978 \uacf5\uacf5 \uac74\ubb3c\uacfc \uba40\ub9ac \ub5a8\uc5b4\uc9c4 \uacf5\uac04\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc774 \uc704\uce58\ub294 \uc0c8\ub85c\uc6b4 \uc2e0\uc559\uc758 \uc7a5\uc18c\ub3c4 \ub3c4\uc2dc\uc758 \ud3c9\ubc94\ud55c \uc774\ub3d9\uacfc \ub9cc\ub0a0 \uc218 \uc788\uc5c8\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uadf8\ub807\ub2e4\uace0 \uacf5\uc5f0\uc744 \ubcf8 \uc0ac\ub78c\uc774 \ubaa8\ub450 \uc774\uc2dc\uc2a4 \uc2e0\uc790\uac00 \ub418\uc5c8\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc778\uc811\ud55c \uac74\ubb3c\ub4e4\uc774 \uc5b4\ub5a4 \uc77c\uc0c1 \uc18d\uc5d0 \ub193\uc5ec \uc788\uc5c8\ub294\uc9c0 \uc0dd\uac01\ud574 \ubcf4\ub294 \uac83\uc774\ub2e4. \uc720\uc801\uc744 \ud55c \ucc44\uc529 \ub530\ub85c \ubcfc \ub54c\ubcf4\ub2e4 \uc8fc\ubcc0\uc758 \uadf9\uc7a5\uacfc \uae38\uc744 \ud568\uaed8 \ub5a0\uc62c\ub9ac\uba74 \uc2e0\uc804\uc740 \uace0\ub9bd\ub41c \uae30\ub150\ubb3c\uc774 \uc544\ub2c8\ub77c \ub3c4\uc2dc\uc758 \ud55c \uc7a5\uc18c\uac00 \ub41c\ub2e4. \uc0ac\uc9c4\uc5d0\ub294 \ub730 \uc548\ucabd\uc758 \uc2e0\uc804 \uc815\uba74\uc774 \ubcf4\uc778\ub2e4. \uacc4\ub2e8 \uc704\uc5d0 \uae30\ub465\uc774 \ubc1b\uce58\ub294 \uc785\uad6c\uac00 \ub193\uc5ec \uc788\uace0 \uc8fc\ubcc0\uc73c\ub85c \ub0ae\uc740 \uacf5\uac04\uc774 \uc774\uc5b4\uc9c4\ub2e4. \ud070 \uc81c\uad6d\uc758 \uc885\uad50 \uac74\ucd95\uc774\ub77c\uace0 \ud574\uc11c \uc5b8\uc81c\ub098 \uac70\ub300\ud55c \uaddc\ubaa8\ub9cc\uc744 \uae30\ub300\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uad50\uc7ac\ub294 \uc774 \uc2e0\uc804\uc758 \ube44\uad50\uc801 \uc791\uc740 \ud06c\uae30\uc640 \ub0b4\ubd80 \uad6c\uc131\uc774 \uc774\uc2dc\uc2a4 \uc2e0\uc559\uc758 \uc785\ubb38 \uc758\ub840\uc640 \uad00\ub828\ub41c \uacf5\uac04\uc784\uc744 \uc124\uba85\ud55c\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\ub294 \uac83\uc740 \ub0a8\uc740 \uac74\ucd95\uc758 \ubaa8\uc2b5\uc774\ub2e4. \uacfc\uac70\uc5d0 \uc774\uacf3\uc744 \ub4dc\ub098\ub4e0 \uc0ac\ub78c\uc758 \uc218\uc640 \ud2b9\uc815 \uc758\ub840\uc758 \uc9c4\ud589\uc744 \uc0ac\uc9c4\ub9cc\uc73c\ub85c \uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc774 \uc2e0\uc804\uc740 \uc544\uc6b0\uad6c\uc2a4\ud22c\uc2a4 \uc2dc\ub300\uc5d0 \uc138\uc6cc\uc84c\uace0, 62\ub144 \ud3fc\ud398\uc774\uc758 \uc9c0\uc9c4 \ub4a4 \uc7ac\uac74\ub418\uc5c8\ub2e4\uace0 \uad50\uc7ac\ub294 \uc124\uba85\ud55c\ub2e4. \uadf8\ub85c\ubd80\ud130 17\ub144 \ub4a4 \ubca0\uc218\ube44\uc624 \ud654\uc0b0\uc758 \ubd84\ud654\uac00 \uc77c\uc5b4\ub0ac\ub2e4. \ub3c4\uc2dc\uc758 \ub9c8\uc9c0\ub9c9 \uc7ac\ub09c \uc774\uc804\uc5d0\ub3c4 \uac74\ubb3c\uc744 \ub2e4\uc2dc \uc138\uc6b0\ub294 \uc2dc\uac04\uc774 \uc788\uc5c8\ub358 \uac83\uc774\ub2e4. \uc720\uc801\uc744 \ubcf4\uba74 \ucc98\uc74c \uc138\uc6e0\uc744 \ub54c\ubd80\ud130 \uadf8\ub300\ub85c \uba48\ucd98 \ubb3c\uac74\ucc98\ub7fc \ub290\ub07c\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \uc0ac\ub78c\uc774 \uc0ac\ub294 \ub3c4\uc2dc\ub294 \uc190\uc0c1\ub418\uace0 \uace0\uccd0\uc9c4\ub2e4. \uc2e0\uc804\uc774 \uc7ac\uac74\ub418\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub204\uad70\uac00 \uadf8 \uc7a5\uc18c\ub97c \uacc4\uc18d \uc0ac\uc6a9\ud558\ub824 \ud588\uc74c\uc744 \uc54c\ub824 \uc900\ub2e4. \ub0a8\uc740 \ubcbd \ub4a4\uc5d0\ub294 \uc720\uc9c0\ud558\uace0 \ub2e4\uc2dc \ub9c8\ub828\ud55c \uc0dd\ud65c\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \uad50\uc7ac\uac00 \uc124\uba85\ud558\ub294 \uc61b \uc2e0\uc804\uc5d0\ub294 \uc774\uc2dc\uc2a4\uc640 \uc624\uc2dc\ub9ac\uc2a4\uc758 \uc0c1, \uc2e0\ud654\ub97c \uadf8\ub9b0 \ubcbd\ud654\uac00 \uc788\uc5c8\ub2e4. \uc785\ubb38\ud55c \uc2e0\uc790\ub4e4\uc774 \ubaa8\uc774\ub294 \uacf5\uac04\uacfc \uc0ac\uc81c\uc758 \uac70\ucc98, \uc81c\ub2e8\uacfc \uc9c0\ud558\uc758 \uc758\ub840 \uacf5\uac04\ub3c4 \uc18c\uac1c\ub41c\ub2e4. \uc785\uad6c \ud558\ub098\ub9cc \ubcf4\uace0 \uc804\uccb4\uc758 \uc5ed\ud560\uc744 \ub2e4 \uc54c \uc218\ub294 \uc5c6\ub294 \ubc30\uce58\ub2e4. \ub2e4\ub9cc \ud604\uc7ac \uc0ac\uc9c4\uc5d0 \uadf8 \ubaa8\ub4e0 \uc7a5\uc2dd\uacfc \ub0b4\ubd80 \uc2dc\uc124\uc774 \uc644\uc804\ud55c \ubaa8\uc2b5\uc73c\ub85c \ubcf4\uc778\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc790\ub8cc\uac00 \uc124\uba85\ud558\ub294 \uacfc\uac70 \uad6c\uc131\uacfc \ub208\uc55e\uc5d0 \ub0a8\uc740 \uc720\uc801\uc744 \uad6c\ubcc4\ud574\uc57c \ud55c\ub2e4. \uc774 \ucc28\uc774\ub97c \uc54c\uba74 \ubcf4\uc774\uc9c0 \uc54a\ub294 \ubd80\ubd84\uc744 \ub9c8\uc74c\ub300\ub85c \ucc44\uc6b0\uae30\ubcf4\ub2e4 \ubb34\uc5c7\uc744 \ub354 \ud655\uc778\ud560\uc9c0 \uc9c8\ubb38\ud560 \uc218 \uc788\ub2e4. \uc774\uc2dc\uc2a4 \uc2e0\uc559\uc740 \uc785\ubb38 \uc808\ucc28\uc640 \uc2e0\uc790 \uc9d1\ub2e8\uc758 \ud65c\ub3d9\uc744 \uac00\uc9c4 \uc774\ub978\ubc14 \uc2e0\ube44 \uc885\uad50\uc758 \ud558\ub098\ub85c \uc124\uba85\ub41c\ub2e4. \uc774\ub984 \ub54c\ubb38\uc5d0 \ud658\uc0c1 \uc18c\uc124\uc758 \ube44\ubc00 \uc870\uc9c1\uc744 \ub5a0\uc62c\ub9b4 \uc218 \uc788\uc9c0\ub9cc, \uadf8\uac83\ub9cc\uc73c\ub85c \ub2f9\uc2dc \uc885\uad50 \uc0dd\ud65c\uc744 \uc774\ud574\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc2e4\uc81c\ub85c\ub294 \uc0ac\ub78c\ub4e4\uc774 \uc2e0\uacfc \uad6c\uc6d0, \uacf5\ub3d9\uccb4\ub97c \ub9cc\ub098\ub294 \ubc29\uc2dd\uc758 \ud558\ub098\uc600\ub2e4. \uc5ec\ub7ec \uc885\uad50\uac00 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uace7\ubc14\ub85c \uc544\ubb34 \uac08\ub4f1\ub3c4 \uc5c6\uc5c8\ub2e4\ub294 \ub9d0\ub85c \ubc14\uafc0 \uc218\ub3c4 \uc5c6\ub2e4. \ub85c\ub9c8\uc81c\uad6d\uc5d0\uc11c \uac01 \uc885\uad50\uac00 \uc804\ud1b5 \uc758\ub840\uc640 \ub9fa\uc740 \uad00\uacc4\ub294 \ub2ec\ub790\ub2e4. \uc791\uc740 \uc2e0\uc804\uc740 \ub3c4\uc2dc\uc758 \ub2e4\uc591\uc131\uc744 \ubcf4\uc5ec \uc8fc\uc9c0\ub9cc, \uc81c\uad6d\uc758 \ubaa8\ub4e0 \uc2e0\uc559\uc774 \uac19\uc740 \uc870\uac74\uc5d0 \uc788\uc5c8\ub2e4\ub294 \uc99d\uba85\uc740 \uc544\ub2c8\ub2e4. \ud3fc\ud398\uc774\ub294 79\ub144\uc758 \ubd84\ud654 \ub54c\ubb38\uc5d0 \ud2b9\ubcc4\ud55c \uace0\uace0\ud559 \uc790\ub8cc\ub97c \ub0a8\uacbc\ub2e4. \ud558\uc9c0\ub9cc \uadf8\uacf3\uc758 \uc8fc\ubbfc\uc744 \ub9c8\uc9c0\ub9c9 \uc21c\uac04\ub9cc\uc73c\ub85c \uc124\uba85\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uacf5\uc5f0\uc7a5 \uac00\uae4c\uc774 \uc2e0\uc804\uc744 \ub450\uace0 \uac74\ubb3c\uc744 \uace0\uce58\uba70 \uc0dd\ud65c\uc744 \uc774\uc5b4 \uac00\ub358 \uc0ac\ub78c\ub4e4\uc774 \uc788\uc5c8\ub2e4. \uc774\uc2dc\uc2a4 \uc2e0\uc804\uc744 \ubc14\ub77c\ubcf4\uba74 \uc7ac\ub09c\ubcf4\ub2e4 \uc55e\uc120 \uc9c8\ubb38\uc774 \uc0dd\uae34\ub2e4. \uc774 \ub3c4\uc2dc \uc0ac\ub78c\ub4e4\uc740 \ub204\uad6c\uc640 \ud568\uaed8 \uae30\ub3c4\ud588\uace0 \uc5b4\ub5a4 \uc774\uc57c\uae30\uc5d0 \uc704\uc548\uc744 \uc5bb\uc5c8\uc744\uae4c. \uc815\ud655\ud788 \uc54c \uc218 \uc5c6\ub294 \uac1c\uc778\uc758 \ub9c8\uc74c\uc744 \ucc3d\uc791\ud558\uc9c0 \uc54a\uc544\ub3c4, \uacf5\uac04\uacfc \uc790\ub8cc\ub97c \ud1b5\ud574 \ub2f9\uc2dc \uc0dd\ud65c\uc758 \uc5ec\ub7ec \uc120\ud0dd\uc744 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 \ubc1c\uad74\ub41c \uc774\uc2dc\uc2a4 \uc2e0\uc804\uc758 \uc2e4\uc81c \uc0ac\uc9c4\uc774\ub2e4. \uc774\uc9d1\ud2b8 \uc2e0\uc559\uc774 \uc774\ud0c8\ub9ac\uc544 \ub3c4\uc2dc \uc548\uc5d0 \uc790\ub9ac\ud588\ub358 \uac74\ucd95\uc758 \ud754\uc801\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc5ec\uc2e0\uc758 \uc774\ub3d9 \uacbd\ub85c\ub97c \ud55c \uc0ac\ub78c\uc758 \uc5ec\ud589\uc73c\ub85c \ubcf5\uc6d0\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\uc9c0\ub9cc \uc9c0\uc911\ud574 \uc138\uacc4\uc758 \uc5f0\uacb0\uc744 \ub290\ub07c\uac8c \ud55c\ub2e4. \ub2e4\uc74c\uc5d0 \ub85c\ub9c8 \uc720\uc801\uc744 \ub9cc\ub098\uba74 \uc774\ub984\ub09c \ud669\uc81c\uc640 \ud070 \uacbd\uae30\uc7a5 \uacc1\uc758 \uc791\uc740 \uacf5\uac04\ub3c4 \ubcf4\uc544 \ub450\uc790. \uc81c\uad6d\uc758 \ub3c4\uc2dc\uc5d0\ub294 \uc5ec\ub7ec \uc9c0\uc5ed\uc5d0\uc11c \uc628 \ubbff\uc74c\uacfc \uc0dd\ud65c\uc774 \ub4e4\uc5b4 \uc788\uc5c8\ub2e4. \ud3fc\ud398\uc774\uc758 \uc791\uc740 \uc2e0\uc804\uc740 \ub3c4\uc2dc\uac00 \ubb34\uc5c7\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c0\ub294\uc9c0 \uc0dd\uac01\ud558\uac8c \ud558\ub294 \uc870\uc6a9\ud55c \uc774\uc57c\uae30\ub2e4."}, {"id": "rome-arena-crowd", "title": "\ucf5c\ub85c\uc138\uc6c0\uc5d0\uc11c\ub294 \ubb34\ub300\ub9cc\ud07c \uad00\uc911\uc11d\ub3c4 \ud06c\ub2e4", "summary": "\uc720\uba85\ud55c \uc720\uc801\uc744 \uacbd\uae30\uc7a5\uacfc \uad00\uc911\uc758 \uc790\ub9ac\ub77c\ub294 \uad00\uc810\uc5d0\uc11c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "cities", "category_title": "Cities", "subcategory": "Europe", "url": "stories/rome-arena-crowd/index.html", "image": "media/rome-arena-crowd.jpg", "alt": "\uc774\ud0c8\ub9ac\uc544 \ub85c\ub9c8 \ucf5c\ub85c\uc138\uc6c0 \ub0b4\ubd80\uc758 \uc2e4\uc81c \uc0ac\uc9c4. \uc5ec\ub7ec \uce35\uc758 \ubcbd\uacfc \ud604\uc7ac \ub0a8\uc740 \ub0b4\ubd80 \uad6c\uc870\uac00 \ubcf4\uc785\ub2c8\ub2e4.", "text": "\ucf5c\ub85c\uc138\uc6c0\uc5d0\uc11c\ub294 \ubb34\ub300\ub9cc\ud07c \uad00\uc911\uc11d\ub3c4 \ud06c\ub2e4 \ub85c\ub9c8\uc758 \ub3cc \uac74\ubb3c\uc5d0\uc11c \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc774\ub358 \uc790\ub9ac\ub97c \ubcf4\uae30 \uc720\uba85\ud55c \uc720\uc801\uc744 \uacbd\uae30\uc7a5\uacfc \uad00\uc911\uc758 \uc790\ub9ac\ub77c\ub294 \uad00\uc810\uc5d0\uc11c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Europe \ub3c4\uc2dc \ub85c\ub9c8\uc758 \ucf5c\ub85c\uc138\uc6c0 \uc0ac\uc9c4\uc744 \ubcf4\uba74 \ub3cc\ub85c \uc774\uc5b4\uc9c4 \ub465\uadfc \ubcbd\uacfc \uc5ec\ub7ec \uce35\uc758 \uacf5\uac04\uc774 \uba3c\uc800 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \ub108\ubb34 \uc720\uba85\ud55c \uac74\ubb3c\uc774\ub77c \uc774\ub984\ub9cc \ud655\uc778\ud558\uace0 \uc9c0\ub098\uce58\uae30 \uc27d\ub2e4. \uc774\ubc88\uc5d0\ub294 \uac00\uc6b4\ub370\uc758 \ubb34\ub300\ubcf4\ub2e4 \uadf8 \uc8fc\ubcc0\uc758 \uad00\uc911\uc11d\uc744 \uba3c\uc800 \ubcf4\uc790. \uc774 \uac74\ubb3c\uc740 \ube44\uc5b4 \uc788\ub294 \ub3cc \uad6c\uc870\ubb3c\ub85c \uc2dc\uc791\ud55c \uac83\uc774 \uc544\ub2c8\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc5ec \ubb34\uc5b8\uac00\ub97c \ud568\uaed8 \ubcf4\ub358 \uc7a5\uc18c\uc600\ub2e4. \uc0ac\uc9c4 \uc18d \ube48 \uacf5\uac04\uc5d0 \uad00\uc911\uc744 \ub5a0\uc62c\ub9ac\uba74 \uac74\ubb3c\uc758 \ud06c\uae30\uac00 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \ub290\uaef4\uc9c4\ub2e4. OpenStax \uad50\uc7ac\ub294 \uace0\ub300 \ub85c\ub9c8\uc758 \uc774\uacf3\uc5d0 \uc218\ub9cc \uba85\uc774 \ubaa8\uc5ec \uacbd\uae30\ub97c \ubcf4\uc558\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \ucf5c\ub85c\uc138\uc6c0\uc758 \uc774\uc57c\uae30\ub294 \ubb34\ub300 \uc704\uc5d0\uc11c \ubb34\uc5c7\uc774 \uc77c\uc5b4\ub0ac\ub294\uc9c0\ubfd0 \uc544\ub2c8\ub77c, \uadf8 \uc7a5\uba74\uc744 \ubcf4\uae30 \uc704\ud574 \uc5bc\ub9c8\ub098 \ub9ce\uc740 \uc0ac\ub78c\uc774 \ubaa8\uc600\ub294\uc9c0\uc640\ub3c4 \uad00\ub828\ub41c\ub2e4. \ud55c \uc0ac\ub78c\uc774 \uadf8\ub9bc \uc55e\uc5d0 \uc11c\ub294 \uac83\uacfc \ucee4\ub2e4\ub780 \uad00\uc911\uc11d\uc5d0\uc11c \uad70\uc911\uacfc \ud568\uaed8 \uad00\ub78c\ud558\ub294 \uacbd\ud5d8\uc740 \ub2e4\ub974\ub2e4. \uac19\uc740 \uc7a5\uba74\uc744 \ud5a5\ud574 \uc2dc\uc120\uc774 \ubaa8\uc774\ub3c4\ub85d \uacf5\uac04\uc744 \ub9c8\ub828\ud55c\ub2e4\ub294 \uac83\uc774 \uc774 \uac74\ubb3c\uc744 \ubcf4\ub294 \ub610 \ud558\ub098\uc758 \uc2e4\ub9c8\ub9ac\ub2e4. \uad50\uc7ac\ub294 \ucf5c\ub85c\uc138\uc6c0\uc774 \uace0\ub300 \uc0ac\ud68c\uc5d0\uc11c \ub9e1\uc558\ub358 \uc5ed\ud560\uc744 \uc624\ub298\ub0a0\uc758 \ud070 \uc2a4\ud3ec\uce20 \uacbd\uae30\uc7a5\uacfc \ube44\uad50\ud55c\ub2e4. \ub2e8\uc21c\ud788 \uad6c\uacbd\uac70\ub9ac\ub97c \uc81c\uacf5\ud558\ub294 \ub370 \uadf8\uce58\uc9c0 \uc54a\uace0 \uc0ac\ub78c\ub4e4\uc774 \uc18c\uc18d\uac10\uacfc \uc815\uccb4\uc131\uc744 \ub290\ub07c\ub294 \uc790\ub9ac\uac00 \ub420 \uc218 \uc788\ub2e4\ub294 \uad00\uc810\uc774\ub2e4. \uadf8\ub807\ub2e4\uace0 \ub2f9\uc2dc\uc758 \uacbd\uae30\uc640 \uc624\ub298\ub0a0\uc758 \uc2a4\ud3ec\uce20\uac00 \ub611\uac19\uc558\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uad50\uc7ac\ub294 \uac80\ud22c\uc0ac\uc640 \ub3d9\ubb3c\uc774 \ub4f1\uc7a5\ud558\ub294 \ud3ed\ub825\uc801\uc778 \uad6c\uacbd\uac70\ub9ac\ub3c4 \uc124\uba85\ud55c\ub2e4. \ubaa8\uc5ec \ubcf4\ub294 \uacf5\uac04\uc774\ub77c\ub294 \ub2ee\uc740 \uc810\uacfc, \uadf8 \uc548\uc758 \uc11c\ub85c \ub2e4\ub978 \ub0b4\uc6a9\uc744 \ub098\ub204\uc5b4 \ubcfc \ud544\uc694\uac00 \uc788\ub2e4. \uc0ac\uc9c4\uc758 \uc911\uc2ec\uc5d0\ub294 \ud55c\ub54c \ub9ce\uc740 \uc2dc\uc120\uc774 \ubaa8\uc600\uc744 \uacf5\uac04\uc774 \uc788\ub2e4. \uadf8 \ub458\ub808\ub97c \uc5ec\ub7ec \uce35\uc758 \uc790\ub9ac\uac00 \ub458\ub7ec\uc2fc\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \ubcf4\uace0\uc790 \ud55c \uc77c\uc774 \uac00\uc6b4\ub370\uc5d0\uc11c \ubc8c\uc5b4\uc9c0\uace0 \uad00\uc911\uc740 \uadf8 \uc8fc\ubcc0\uc5d0\uc11c \ubc14\ub77c\ubcf4\ub294 \ubc30\uce58\ub2e4. \uac74\ucd95\uc740 \uad6c\uacbd\uac70\ub9ac\uc758 \ubc30\uacbd\ub9cc\uc774 \uc544\ub2c8\ub77c, \uc11c\ub85c \ub5a8\uc5b4\uc9c4 \ub9ce\uc740 \uc0ac\ub78c\uc774 \ud55c \ub300\uc0c1\uc744 \ud5a5\ud558\uac8c \ud558\ub294 \uc7a5\uce58\uc774\uae30\ub3c4 \ud588\ub2e4. \uc774\uac83\uc744 \uc774\ud574\ud558\ub824\uace0 \uc5c6\uc5b4\uc9c4 \uac74\ucd95 \ubd80\ubd84\uc744 \uc0c1\uc0c1\uc73c\ub85c \ubaa8\ub450 \ubcf5\uc6d0\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ud604\uc7ac \uc0ac\uc9c4\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\ub294 \uc911\uc2ec\uacfc \ub458\ub808, \ub192\uc774\uc758 \uad00\uacc4\ub9cc \ub530\ub77c\uac00\ub3c4 \ub41c\ub2e4. \uac19\uc740 \uc790\ub9ac\uc5d0 \uc549\uc544\ub3c4 \ubb34\ub300\ub97c \ub0b4\ub824\ub2e4\ubcf4\ub294 \uac01\ub3c4\uc640 \uc606 \uc0ac\ub78c\uc744 \ub290\ub07c\ub294 \ubc29\uc2dd\uc740 \ub2ec\ub790\uc744 \uac83\uc774\ub2e4. \uacf5\uac04\uc758 \ud06c\uae30\uac00 \uad00\ub78c\uc758 \uacbd\ud5d8\uacfc \uc5b4\ub5bb\uac8c \uc5f0\uacb0\ub418\ub294\uc9c0 \ubb3c\uc5b4\ubcfc \uc218 \uc788\ub2e4. \uc9d1\uc5d0\uc11c \ud63c\uc790 \uacbd\uae30\ub97c \ubcf4\ub294 \uc21c\uac04\uacfc \ud070 \uacbd\uae30\uc7a5\uc5d0\uc11c \uc5ec\ub7ec \uc0ac\ub78c\uc758 \uc18c\ub9ac\ub97c \ub4e4\uc73c\uba70 \ubcf4\ub294 \uc21c\uac04\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc7a5\uba74\uc758 \ub0b4\uc6a9\uc774 \ube44\uc2b7\ud574\ub3c4 \uae34\uc7a5\uacfc \ud765\ubd84\uc774 \uc804\ud574\uc9c0\ub294 \ubc29\uc2dd\uc740 \ub2e4\ub974\ub2e4. \uad50\uc7ac\uac00 \uc624\ub298\uc758 \uc2a4\ud3ec\uce20 \uacf5\uac04\uc744 \ub098\ub780\ud788 \ub193\ub294 \uc774\uc720\ub3c4 \uc774\ub7f0 \uc9d1\ub2e8 \uacbd\ud5d8\uc744 \uc0dd\uac01\ud558\uac8c \ud558\ub824\ub294 \ub370 \uc788\ub2e4. \ub2e4\ub9cc \uc774\uac83\uc740 \ube44\uad50\ub97c \uc704\ud55c \ucd9c\ubc1c\uc810\uc774\uc9c0 \uace0\ub300\uc778\uc758 \uac10\uc815\uc744 \uadf8\ub300\ub85c \uc548\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc5ec\ub7ec \uc0ac\ub78c\uc774 \uac19\uc740 \ub54c \uac19\uc740 \uacf3\uc5d0 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uc18c\uc18d\uac10\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub2e4. \ubc18\ub300\ub85c \ub204\uac00 \uadf8 \uc790\ub9ac\uc5d0 \ud3ec\ud568\ub418\uace0 \uc5b4\ub5a4 \uc704\uce58\ub97c \ucc28\uc9c0\ud558\ub294\uc9c0\ub3c4 \uc9c8\ubb38\ud558\uac8c \ud55c\ub2e4. \uad70\uc911\uc774 \ud55c \ub369\uc5b4\ub9ac\ucc98\ub7fc \ubcf4\uc77c \ub54c\uc5d0\ub3c4 \uac1c\ubcc4 \uad00\ub78c\uc790\uc758 \uacbd\ud5d8\uae4c\uc9c0 \ubaa8\ub450 \uac19\uc558\ub2e4\uace0 \ubcfc \uc218\ub294 \uc5c6\ub2e4. \uac74\ucd95\uc758 \uc804\uccb4 \ubaa8\uc2b5\uacfc \uadf8 \uc548\uc758 \uc11c\ub85c \ub2e4\ub978 \uc790\ub9ac\ub97c \ud568\uaed8 \ub5a0\uc62c\ub9b4 \ud544\uc694\uac00 \uc788\ub2e4. \uac80\ud22c\uc0ac\uc640 \ub3d9\ubb3c\uc774 \ub4f1\uc7a5\ud558\ub294 \uad6c\uacbd\uac70\ub9ac\ub97c \uc624\ub298\uc758 \uc2a4\ud3ec\uce20\uc640 \uac19\uc740 \uc624\ub77d\uc73c\ub85c\ub9cc \uc815\ub9ac\ud558\uba74 \uc911\uc694\ud55c \ucc28\uc774\uac00 \uc0ac\ub77c\uc9c4\ub2e4. \uc0ac\ub78c\uacfc \ub3d9\ubb3c\uc758 \uace0\ud1b5\uc774 \uad00\ub78c\uc758 \ub300\uc0c1\uc774 \ub418\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \ub9ce\uc740 \uc0ac\ub78c\uc774 \ubaa8\uc600\ub2e4\ub294 \uaddc\ubaa8\uc640 \uadf8\uac83\uc744 \ubcfc \ub9cc\ud55c \uc77c\ub85c \ubc1b\uc544\ub4e4\uc600\ub2e4\ub294 \ud310\ub2e8\uc740 \uc11c\ub85c \ub2e4\ub978 \ubb38\uc81c\ub2e4. \uadf8\ub798\uc11c \ucf5c\ub85c\uc138\uc6c0\uc740 \uac74\ucd95 \uae30\uc220\uc5d0 \ub300\ud55c \uac10\ud0c4\uacfc \uad00\ub78c \ubb38\ud654\uc5d0 \ub300\ud55c \uc9c8\ubb38\uc744 \ub3d9\uc2dc\uc5d0 \ubd80\ub978\ub2e4. \ud070 \uacf5\uac04\uc744 \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \uc131\ucde8\ub9cc\uc73c\ub85c \uadf8 \uc548\uc5d0\uc11c \uc77c\uc5b4\ub09c \uc77c\uc774 \uc815\ub2f9\ud574\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc720\uc801\uc744 \uc77d\ub294 \uc990\uac70\uc6c0\uc740 \uacfc\uac70\ub97c \ubb34\uc870\uac74 \ucc2c\uc591\ud558\ub294 \ub370 \uc788\uc9c0 \uc54a\ub2e4. \uc624\ub298\uacfc \ub2ee\uc740 \uc810\uc744 \uc54c\uc544\ubcf4\uba74\uc11c \ub0af\uc124\uace0 \ubd88\ud3b8\ud55c \ucc28\uc774\ub3c4 \ub193\uce58\uc9c0 \uc54a\ub294 \ub370 \uc788\ub2e4. \ud604\uc7ac\uc758 \ub0b4\ubd80 \uc0ac\uc9c4\uc740 \uc0ac\ub78c\ub4e4\uc774 \ub5a0\ub09c \ub4a4 \ub0a8\uc740 \uc0c1\ud0dc\ub97c \ubcf4\uc5ec \uc900\ub2e4. \ubb34\ub108\uc9c4 \ubd80\ubd84\uc774\ub098 \ub4dc\ub7ec\ub09c \uad6c\uc870\ub97c \ubaa8\ub450 \uc6d0\ub798 \ubb34\ub300\uc758 \ubaa8\uc2b5\uc774\ub77c\uace0 \uc77d\uc5b4\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc2dc\uac04\uc774 \uc9c0\ub098\uba70 \ub2ec\ub77c\uc9c4 \uac74\ubb3c\uc758 \ud604\uc7ac\uc640 \uacfc\uac70\uc758 \uc4f0\uc784\uc744 \ub098\ub204\uc5b4 \ubcf4\ub294 \uc77c\uc774 \ud544\uc694\ud558\ub2e4. \uc790\ub8cc \uc0ac\uc9c4\uc774 \uc720\uc6a9\ud55c \uac83\uc740 \uc5c6\ub294 \ubd80\ubd84\uc744 \ub9c8\uc74c\ub300\ub85c \ucc44\uc6b0\uc9c0 \uc54a\uace0 \ub0a8\uc740 \uac83\uc744 \uc0b4\ud53c\uac8c \ud558\uae30 \ub54c\ubb38\uc774\ub2e4. \ub3cc\uc758 \ud070 \ub369\uc5b4\ub9ac\uc5d0\uc11c \uc0ac\ub78c\uc758 \uc6c0\uc9c1\uc784\uc744 \ub5a0\uc62c\ub9ac\uba74 \uac74\ubb3c\uc774 \uc870\uae08 \ub35c \ucd94\uc0c1\uc801\uc73c\ub85c \ub290\uaef4\uc9c4\ub2e4. \uc5b4\ub514\ub85c \ub4e4\uc5b4\uac00 \uc5b4\ub290 \ucabd\uc744 \ubcf4\uc558\uc744\uc9c0, \ub9ce\uc740 \uc2dc\uc120\uc774 \uac19\uc740 \uc21c\uac04 \uc5b4\ub514\uc5d0 \ubaa8\uc600\uc744\uc9c0\ub97c \uc9c8\ubb38\ud574 \ubcf4\uc790. \uc815\ud655\ud55c \uc88c\uc11d \ubc30\uce58\ub098 \uc2e0\ubd84\ubcc4 \uad6c\uc5ed\uc758 \uc124\uba85\uc740 \ubcc4\ub3c4 \uc5ed\uc0ac \uc790\ub8cc\uac00 \ud544\uc694\ud55c \ubb38\uc81c\ub85c \ub0a8\uae30\ub418, \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc5ec \ubcf4\ub294 \uc7a5\uc18c\ub77c\ub294 \uae30\ubcf8 \uc131\uaca9\uc740 \uc0ac\uc9c4 \uc18d \uacf5\uac04\uc5d0\uc11c\ub3c4 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 \ucf5c\ub85c\uc138\uc6c0 \ub0b4\ubd80\uc758 \uc2e4\uc81c \uc0ac\uc9c4\uc774\ub2e4. \uc624\ub298 \ub0a8\uc740 \ubaa8\uc2b5\uc744 \uace0\ub300\uc758 \uc644\uc804\ud55c \ubaa8\uc2b5\uc73c\ub85c \ubc14\uafb8\uc5b4 \uadf8\ub9ac\uc9c0\ub294 \uc54a\uc558\ub2e4. \ud604\uc7ac \ubcf4\uc774\ub294 \uc790\ub9ac\uc640 \uc0ac\ub77c\uc9c4 \ubd80\ubd84\uc744 \uc788\ub294 \uadf8\ub300\ub85c \ub9cc\ub098\uae30 \uc704\ud574\uc11c\ub2e4. \uc720\uba85\ud55c \uc720\uc801 \uc55e\uc5d0\uc11c\ub294 \uc5b8\uc81c \uc9c0\uc5c8\ub294\uc9c0\uc640 \uc5bc\ub9c8\ub098 \ud070\uc9c0\ub97c \uba3c\uc800 \ubb3b\uac8c \ub41c\ub2e4. \uadf8 \uc606\uc5d0 \ub204\uac00 \uc5b4\ub514\uc5d0\uc11c \ubb34\uc5c7\uc744 \ubcf4\uc558\uc744\uae4c\ub77c\ub294 \uc9c8\ubb38\ub3c4 \ub193\uc544 \ubcf4\uc790. \ub85c\ub9c8\uc758 \ub3cc \uac74\ubb3c\uc740 \uad00\uc911\uc774 \ub5a0\ub09c \ub4a4\uc5d0\ub3c4 \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc600\ub358 \uc790\ub9ac\ub97c \ub0a8\uaca8 \ub193\uace0 \uc788\ub2e4."}, {"id": "samarkand-registan-and-learning", "title": "\uc0ac\ub9c8\ub974\uce78\ud2b8 \u2014 \ud478\ub978 \uad11\uc7a5\uc5d0 \uc7a5\uc778\uacfc \ud559\uc790\uac00 \ubaa8\uc774\ub2e4", "summary": "\ub808\uae30\uc2a4\ud0c4\uacfc \ud559\ubb38\uc758 \ub3c4\uc2dc\ub97c \ud1b5\ud574 \uc0ac\ub9c8\ub974\uce78\ud2b8\uc5d0 \ubaa8\uc778 \uad50\uc5ed\u00b7\uc7a5\uc778\u00b7\ucc9c\ubb38\ud559\uc758 \uc5ed\uc0ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "cities", "category_title": "Cities", "subcategory": "Asia", "url": "stories/samarkand-registan-and-learning/index.html", "image": "media/samarkand-registan-and-learning.jpg", "alt": "\uc67c\ucabd\uc740 \uc0ac\ub9c8\ub974\uce78\ud2b8 \uc170\ub974\ub3c4\ub974 \ub9c8\ub4dc\ub77c\uc0ac\uc758 \uc2e4\uc81c \uc0ac\uc9c4, \uc624\ub978\ucabd\uc740 \uc5ed\uc0ac\uc801 \ub300\ubaa8\uc2a4\ud06c \uac74\uc124 \ud68c\ud654.", "text": "\uc0ac\ub9c8\ub974\uce78\ud2b8 \u2014 \ud478\ub978 \uad11\uc7a5\uc5d0 \uc7a5\uc778\uacfc \ud559\uc790\uac00 \ubaa8\uc774\ub2e4 \uc544\ub984\ub2e4\uc6b4 \uac74\ubb3c\uc744 \ubcf4\ub294 \uc77c\uacfc \uadf8 \ub4a4\uc758 \uc0ac\ub78c\uc744 \uae30\uc5b5\ud558\ub294 \uc77c \ub808\uae30\uc2a4\ud0c4\uacfc \ud559\ubb38\uc758 \ub3c4\uc2dc\ub97c \ud1b5\ud574 \uc0ac\ub9c8\ub974\uce78\ud2b8\uc5d0 \ubaa8\uc778 \uad50\uc5ed\u00b7\uc7a5\uc778\u00b7\ucc9c\ubb38\ud559\uc758 \uc5ed\uc0ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Asia \ub3c4\uc2dc \ud478\ub978\uc0c9\uacfc \ud759\ube5b\uc774 \uc11e\uc778 \ucee4\ub2e4\ub780 \uc785\uad6c, \ub192\uac8c \uc19f\uc740 \ud0d1, \uc7a5\uc2dd\uc73c\ub85c \ucc44\uc6b4 \ubcbd\uba74. \uc0ac\ub9c8\ub974\uce78\ud2b8\uc758 \ub808\uae30\uc2a4\ud0c4\uc744 \ubcf4\uba74 \uac74\ubb3c\uc774 \ub113\uc740 \uad11\uc7a5\uc744 \ud5a5\ud574 \ubb34\ub300\ucc98\ub7fc \uc11c \uc788\ub2e4\ub294 \ub290\ub08c\uc774 \ub4e0\ub2e4. \uc6b0\uc988\ubca0\ud0a4\uc2a4\ud0c4\uc758 \uc774 \ub3c4\uc2dc\ub294 \uc0ac\uc9c4 \ud55c \uc7a5\ub9cc\uc73c\ub85c\ub3c4 \uc5ec\ud589\ud558\uace0 \uc2f6\uc740 \ub9c8\uc74c\uc744 \uc77c\uc73c\ud0a8\ub2e4. \uadf8\ub7ec\ub098 \uc544\ub984\ub2e4\uc6b4 \uc7a5\uc18c\uac00 \uc800\uc808\ub85c \uc0dd\uae30\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc0ac\ub78c\uc774 \ubaa8\uc774\uace0 \ubb3c\uc790\uac00 \ub4e4\uc5b4\uc624\uba70, \ub204\uad70\uac00 \uadf8 \uc77c\uc744 \ud6c4\uc6d0\ud558\uace0 \ub2e4\ub978 \ub204\uad70\uac00\ub294 \uc190\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc57c \ud55c\ub2e4. \uc0ac\ub9c8\ub974\uce78\ud2b8\uc758 \uc774\uc57c\uae30\ub294 \uba4b\uc9c4 \uc678\uad00 \ub4a4\uc5d0\uc11c \uad50\uc5ed\uacfc \uad8c\ub825, \ubc30\uc6c0\uc774 \ub9cc\ub09c \uacfc\uc815\uc73c\ub85c \uc774\uc5b4\uc9c4\ub2e4. \uc0ac\ub9c8\ub974\uce78\ud2b8\ub294 \uc911\uc559\uc544\uc2dc\uc544\uc758 \uc911\uc694\ud55c \uc624\uc544\uc2dc\uc2a4 \ub3c4\uc2dc\uc600\ub2e4. \ubd80\ud558\ub77c\uc640 \ud568\uaed8 \uc18c\uadf8\ub4dc \uc0c1\uc778\ub4e4\uc758 \ud65c\ub3d9\uacfc \uc5f0\uacb0\ub418\uc5c8\uc73c\uba70, \ub3d9\uc11c \uad50\uc5ed\uc744 \uc774\uc5b4 \uc8fc\ub294 \uac70\uc810 \uac00\uc6b4\ub370 \ud558\ub098\uc600\ub2e4. \uc2e4\ud06c\ub85c\ub4dc\ub294 \ud55c \uc0ac\ub78c\uc774 \ucc98\uc74c\ubd80\ud130 \ub05d\uae4c\uc9c0 \uac77\ub294 \ud558\ub098\uc758 \ub3c4\ub85c\ubcf4\ub2e4 \uc5ec\ub7ec \uc9c0\uc5ed\uc744 \uc787\ub294 \uae38\uc758 \ub9dd\uc774\uc5c8\ub2e4. \uc18c\uadf8\ub4dc\uc778\ub4e4\uc740 \uc11c\ucabd\uacfc \ub3d9\ucabd\uc758 \uc5ec\ub7ec \uc0ac\ub78c\uacfc \uac70\ub798\ud588\uace0 \uc911\uad6d\uc758 \uc8fc\uc694 \ub3c4\uc2dc\ub4e4\uc5d0\ub3c4 \uad50\uc5ed \uacf5\ub3d9\uccb4\ub97c \ub450\uc5c8\ub2e4. \ubb3c\uac74\ubfd0 \uc544\ub2c8\ub77c \uc5b8\uc5b4\uc640 \uc885\uad50, \uc0dd\ud65c\uc758 \ubc29\uc2dd\ub3c4 \uc774\ub3d9\ud588\ub2e4. \uc0ac\ub9c8\ub974\uce78\ud2b8\ub97c \ud2b9\uc815 \uc815\ubcf5\uc790\uac00 \ucc98\uc74c \ub9cc\ub4e0 \ube48 \ubb34\ub300\ucc98\ub7fc \ubcf4\uba74 \uadf8\ubcf4\ub2e4 \uc624\ub798 \uc313\uc778 \ub3c4\uc2dc\uc758 \uc5ed\ud560\uc744 \ub193\uce5c\ub2e4. 14\uc138\uae30\uc5d0 \uc138\ub825\uc744 \ub113\ud78c \ud2f0\ubb34\ub974\ub294 \uc0ac\ub9c8\ub974\uce78\ud2b8\ub97c \uc790\uc2e0\uc758 \uc218\ub3c4\ub85c \uc0bc\uc558\ub2e4. \uc815\ubcf5\ud55c \uc9c0\uc5ed\uc5d0\uc11c \ubd80\uc640 \uc720\uc6a9\ud55c \uae30\uc220\uc744 \ubaa8\uc558\uace0, \uac74\ucd95\uac00\uc640 \uc608\uc220\uac00, \uc7a5\uc778\ub4e4\uc744 \uc218\ub3c4\ub85c \ubcf4\ub0c8\ub2e4. \ub3c4\uc2dc\ub294 \ud070 \uac74\uc124 \uc791\uc5c5\uc774 \uc774\uc5b4\uc9c0\ub294 \uc7a5\uc18c\uac00 \ub418\uc5c8\ub2e4. \uc7a5\uc778\uc774 \ub9ce\uc544\uc84c\ub2e4\ub294 \uacb0\uacfc\ub9cc\uc73c\ub85c \uc774\ub97c \uc790\uc720\ub85c\uc6b4 \uc608\uc220\uac00\ub4e4\uc758 \uc5ec\ud589\uc73c\ub85c \uadf8\ub824\uc11c\ub294 \uc548 \ub41c\ub2e4. \uad50\uc7ac\ub294 \uc815\ubcf5\uacfc \uac15\uc81c\uc801\uc778 \uc774\ub3d9\uc774 \uc774 \uacfc\uc815\uc5d0 \uc788\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uac74\ubb3c\uc758 \uc544\ub984\ub2e4\uc6c0\uc774 \uadf8 \ubc30\uacbd\uc758 \ud3ed\ub825\uc744 \uc5c6\uc560 \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub3c4\uc2dc\ub97c \uce6d\ucc2c\ud558\ub294 \uc77c\uacfc \uadf8\uacf3\uc73c\ub85c \uc624\uac8c \ub41c \uc0ac\ub78c\ub4e4\uc758 \uc870\uac74\uc744 \ubb3b\ub294 \uc77c\uc740 \ud568\uaed8 \ud560 \uc218 \uc788\ub2e4. \ub808\uae30\uc2a4\ud0c4\uc740 \uc0ac\ub9c8\ub974\uce78\ud2b8\uc758 \uacf5\uacf5 \uc9d1\ud68c\uc640 \ubc30\uc6c0\uc774 \uc774\ub8e8\uc5b4\uc9c4 \uc911\uc694\ud55c \uad11\uc7a5\uc774\uc5c8\ub2e4. \uad11\uc7a5\uc744 \ud5a5\ud574 \uc120 \ub9c8\ub4dc\ub77c\uc0ac\ub4e4\uc740 \uc885\uad50\uc640 \ud559\ubb38\uc758 \uad50\uc721 \uacf5\uac04\uc774\ub2e4. \ucee4\ub2e4\ub780 \ube48 \uacf5\uac04\uacfc \uadf8 \ub458\ub808\uc758 \uac74\ubb3c\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \uc7a5\uc18c\uc758 \uc131\uaca9\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \uac74\ubb3c \ud558\ub098\uc758 \uc815\uba74\ub9cc \ubcf4\uba74 \uc7a5\uc2dd\uc758 \uc544\ub984\ub2e4\uc6c0\uc5d0 \uc9d1\uc911\ud558\uac8c \ub41c\ub2e4. \ubc18\ub300\ub85c \uad11\uc7a5\uc5d0\uc11c \uc5b4\ub290 \ubc29\ud5a5\uc744 \ubcf4\uc544\ub3c4 \uc911\uc694\ud55c \uc785\uad6c\uac00 \uc2dc\uc120\uc5d0 \ub4e4\uc5b4\uc624\ub294 \ubc30\uce58\ub97c \uc0dd\uac01\ud558\uba74 \ub3c4\uc2dc\uc758 \uc911\uc2ec\uc744 \ub9cc\ub4dc\ub294 \ubc29\uc2dd\ub3c4 \ubcf4\uc778\ub2e4. \uc7a5\uc2dd\uacfc \uacf5\uac04\uc758 \uad00\uacc4\ub294 \uc11c\ub85c \ub2e4\ub978 \uac10\uc0c1\uc774 \uc544\ub2c8\ub77c \uac19\uc740 \uc7a5\uc18c\ub97c \ubcf4\ub294 \ub450 \uac70\ub9ac\ub2e4. \ud568\uaed8 \uc2e4\uc740 \ub3c4\ud310\uc758 \uc67c\ucabd\uc740 \ub808\uae30\uc2a4\ud0c4\uc758 \uc170\ub974\ub3c4\ub974 \ub9c8\ub4dc\ub77c\uc0ac \uc0ac\uc9c4\uc774\ub2e4. \uc624\ub978\ucabd\uc740 \ud2f0\ubb34\ub974\uc758 \uc6d0\uc815\uc744 \ub2e4\ub8ec \u300a\uc2b9\uc804\uae30\u300b\uc5d0 \uc2e4\ub9b0 \uc0ac\ub9c8\ub974\uce78\ud2b8 \ub300\ubaa8\uc2a4\ud06c \uac74\uc124 \uc7a5\uba74\uc774\ub2e4. \ud558\ub098\ub294 \ub0a8\uc544 \uc788\ub294 \uac74\ubb3c\uc758 \uc0ac\uc9c4\uc774\uace0 \ub2e4\ub978 \ud558\ub098\ub294 \uc5ed\uc0ac\uc801 \ud68c\ud654\ub2e4. \ub458\uc744 \ub098\ub780\ud788 \ub193\uc558\ub2e4\uace0 \uac19\uc740 \uac74\ubb3c\uc758 \uc644\uacf5 \uc804\uacfc \ud6c4\uac00 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc0ac\uc9c4\uc758 \ub9c8\ub4dc\ub77c\uc0ac\uc640 \ud68c\ud654 \uc18d \ub300\ubaa8\uc2a4\ud06c, \ub4a4\uc5d0\uc11c \uc18c\uac1c\ud560 \ucc9c\ubb38\ub300\ub3c4 \uc11c\ub85c \ub2e4\ub978 \uc7a5\uc18c\ub2e4. \uc774 \uad6c\ubd84\uc744 \uba3c\uc800 \ud574 \ub450\uba74 \uc5ec\ub7ec \uc2dc\ub300\uc758 \uac74\ucd95\uc744 \ud55c \uc0ac\ub78c\uc774 \ud55c \ubc88\uc5d0 \ub9cc\ub4e0 \ub3c4\uc2dc\ub85c \ubb49\ub6b1\uadf8\ub9ac\uc9c0 \uc54a\uac8c \ub41c\ub2e4. \uc624\ub978\ucabd \uadf8\ub9bc\uc5d0\ub294 \uc77c\uc744 \ud558\ub294 \uc5ec\ub7ec \uc778\ubb3c\uacfc \uc7ac\ub8cc\ub97c \uc62e\uae30\ub294 \uc7a5\uba74\uc774 \ubcf4\uc778\ub2e4. \ud070 \uac74\ubb3c\uc744 \uac10\uc0c1\ud558\ub2e4\uac00 \uc791\uc5c5\ud558\ub294 \uc0ac\ub78c\uc5d0\uac8c \uc2dc\uc120\uc744 \uc62e\uae30\uba74 \ub3c4\uc2dc \uac74\uc124\uc774 \uc190\uacfc \uc2dc\uac04\uc758 \ubb38\uc81c\uc600\ub2e4\ub294 \uc810\uc774 \uac00\uae4c\uc6cc\uc9c4\ub2e4. \uc655\uc758 \uc774\ub984\uc73c\ub85c \ubd88\ub9ac\ub294 \uac74\ubb3c\ub3c4 \uc5ec\ub7ec \uc0ac\ub78c\uc758 \ub2a5\ub825\uc774 \uc788\uc5b4\uc57c \ub9cc\ub4e4\uc5b4\uc9c4\ub2e4. \ub2e4\ub9cc \uc774 \uadf8\ub9bc\uc740 \uacf5\uc0ac \ud604\uc7a5\uc744 \uc0ac\uc9c4\ucc98\ub7fc \uadf8\ub300\ub85c \uc62e\uae34 \uae30\ub85d\uc740 \uc544\ub2c8\ub2e4. \uc2b9\ub9ac\ub97c \uae30\ub150\ud558\uace0 \ud1b5\uce58\uc790\uc758 \uc704\uc5c5\uc744 \ud45c\ud604\ud558\ub294 \ucc45\uc5d0 \ub2f4\uae34 \uc7a5\uba74\uc774\ub77c\ub294 \ub9e5\ub77d\uc774 \uc788\ub2e4. \uadf8 \ubaa9\uc801\uc744 \uae30\uc5b5\ud558\uba74\uc11c\ub3c4 \uadf8\ub9bc\uc774 \uc791\uc5c5\uc744 \uc5b4\ub5a4 \ubaa8\uc2b5\uc73c\ub85c \ubcf4\uc5ec \uc8fc\ub824 \ud588\ub294\uc9c0\ub294 \uad00\ucc30\ud560 \uc218 \uc788\ub2e4. \ud2f0\ubb34\ub974\uc758 \uc190\uc790 \uc6b8\ub8e8\uadf8\ubca0\ud06c\ub294 \uc0ac\ub9c8\ub974\uce78\ud2b8\uc5d0 \ub9c8\ub4dc\ub77c\uc0ac\uc640 \ucc9c\ubb38\ub300\ub97c \uc138\uc6b0\uace0 \uc218\ud559\uc790\uc640 \ucc9c\ubb38\ud559\uc790\ub97c \ucd08\uccad\ud588\ub2e4. \uad50\uc7ac\ub294 \uc774 \ub3c4\uc2dc\uac00 15\uc138\uae30\uc5d0 \uc911\uc694\ud55c \ud559\ubb38\uc758 \uc911\uc2ec\uc774 \ub418\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uad8c\ub825\uc744 \uacfc\uc2dc\ud558\ub294 \uac74\ucd95\ub9cc\uc774 \uc544\ub2c8\ub77c \ubc30\uc6c0\uc744 \ud6c4\uc6d0\ud558\ub294 \uacf5\uac04\ub3c4 \uc0dd\uaca8\ub09c \uac83\uc774\ub2e4. \ucc9c\ubb38\ub300\ub294 \ubcc4\uc744 \ubcf4\uae30 \uc88b\uc740 \uacbd\uce58\ub9cc\uc73c\ub85c \uc644\uc131\ub418\uc9c0 \uc54a\ub294\ub2e4. \uad00\uce21\uc744 \ud560 \uc0ac\ub78c\uacfc \uc9c0\uc2dd\uc744 \uc774\uc5b4 \uac08 \ud658\uacbd\uc774 \uc788\uc5b4\uc57c \ud55c\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc815\ubc00\ud55c \uad00\uce21 \uae30\uae30\uc758 \uad6c\uc870\ub098 \uac1c\ubcc4 \uc218\uce58\ub97c \ub2e4\ub8e8\uae30\ubcf4\ub2e4, \ud1b5\uce58\uc790\uc758 \ud6c4\uc6d0\uacfc \ud559\uc790\uc758 \ud65c\ub3d9\uc774 \ub3c4\uc2dc \uc548\uc5d0\uc11c \uc5b4\ub5bb\uac8c \ub9cc\ub0ac\ub294\uc9c0 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uba3c \uacf3\uc5d0\uc11c \uc0ac\ub78c\uc774 \ub4e4\uc5b4\uc624\ub294 \ub3c4\uc2dc\ub294 \ub2e4\ub978 \uc5b8\uc5b4\uc640 \uae30\uc220\uc744 \uc811\ud560 \uae30\ud68c\uac00 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \uad50\uc5ed\uc774 \ud65c\ubc1c\ud55c \uacf3\uc774 \ubc18\ub4dc\uc2dc \ud559\ubb38\uc758 \ub3c4\uc2dc\uac00 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc77c\ud560 \uc7a5\uc18c\uc640 \ud6c4\uc6d0, \ubc30\uc6c0\uc744 \uc9c0\uc18d\ud560 \uad00\uacc4\uac00 \ud568\uaed8 \ud544\uc694\ud558\ub2e4. \uc0ac\ub9c8\ub974\uce78\ud2b8\uc5d0\uc11c\ub294 \uc624\ub798\ub41c \uad50\uc5ed \uac70\uc810\uc758 \uc131\uaca9 \uc704\uc5d0 \uc815\ubcf5 \uc655\uc870\uc758 \uc218\ub3c4\ub77c\ub294 \uc5ed\ud560\uacfc \ud559\ubb38 \ud6c4\uc6d0\uc774 \uacb9\ucce4\ub2e4. \uac01\uac01\uc758 \uc2dc\uae30\ub97c \uac19\uc740 \uc7a5\uba74\uc73c\ub85c \uc11e\uae30\ubcf4\ub2e4 \ucc28\ub840\ub85c \ubcf4\uc544\uc57c \ub3c4\uc2dc\uc758 \ubcc0\ud654\uac00 \ubcf4\uc778\ub2e4. \uc5ec\ub7ec \uae30\ub2a5\uc774 \ub298 \ub611\uac19\uc740 \ube44\uc728\ub85c \uc720\uc9c0\ub418\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc0ac\uc9c4 \uc18d\uc758 \uc7a5\uc2dd\uc740 \uc5ec\uc804\ud788 \uc544\ub984\ub2f5\ub2e4. \uc5ed\uc0ac\uc801 \ubc30\uacbd\uc744 \uc548\ub2e4\uace0 \uadf8 \uc544\ub984\ub2e4\uc6c0\uc744 \ud3ec\uae30\ud560 \uc774\uc720\ub294 \uc5c6\ub2e4. \uc624\ud788\ub824 \uac74\ubb3c\uc744 \ub9cc\ub4e0 \uae30\uc220\uacfc \uadf8 \uae30\uc220\uc744 \uc9c0\ub2cc \uc0ac\ub78c\ub4e4\uc758 \uc774\ub3d9\uc774 \uad6c\uccb4\uc801\uc73c\ub85c \ub290\uaef4\uc838 \uac10\uc0c1\uc758 \ub0b4\uc6a9\uc774 \ub9ce\uc544\uc9c4\ub2e4. \uc0ac\ub9c8\ub974\uce78\ud2b8\ub97c \uae30\uc5b5\ud560 \ub54c \ud478\ub978 \uc815\uba74 \uc606\uc5d0 \uad11\uc7a5\uacfc \uc791\uc5c5\ud558\ub294 \uc190, \ubcc4\uc744 \uc5f0\uad6c\ud558\ub358 \uc0ac\ub78c\uc758 \uc790\ub9ac\ub3c4 \ub0a8\uaca8 \ubcf4\uc790. \ub3c4\uc2dc\ub294 \ud55c \uc601\uc6c5\uc758 \uc131\ucde8\ub9cc\uc73c\ub85c \uc124\uba85\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc0ac\uc9c4\uc5d0 \ud06c\uac8c \ubcf4\uc774\ub294 \uc774\ub984\ub09c \uac74\ubb3c\uacfc \uc791\uac8c \ubcf4\uc774\uac70\ub098 \uc0ac\ub77c\uc9c4 \uc0ac\ub78c\uc758 \uc2dc\uac04\uc744 \ud568\uaed8 \uc77d\uc744 \ub54c \uadf8 \uc7a5\uc18c\uc758 \uae4a\uc774\uac00 \uc0dd\uae34\ub2e4."}, {"id": "sofala-port-and-hinterland", "title": "\uc18c\ud314\ub77c \u2014 \uc791\uc740 \ud56d\uad6c \ub4a4\uc5d0\ub294 \uae34 \uae38\uc774 \uc788\uc5c8\ub2e4", "summary": "17\uc138\uae30 \uc18c\ud314\ub77c \ub3c4\ud310\uc5d0\uc11c \ucd9c\ubc1c\ud574 \ub0b4\ub959\uacfc \uc778\ub3c4\uc591\uc744 \uc774\uc740 \ud56d\uad6c\uc758 \uc5ed\ud560\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "cities", "category_title": "Cities", "subcategory": "Africa", "url": "stories/sofala-port-and-hinterland/index.html", "image": "media/sofala-port-and-hinterland.png", "alt": "1683\ub144 \uc18c\ud314\ub77c\ub97c \ud45c\ud604\ud55c \ub9d0\ub808 \ub3c4\ud310\uc758 \uc804\uccb4\uc640 \ud655\ub300 \uad6c\uc131. \ubb3c\uae38\uacfc \uc131\ucc44, \uc8fc\ubcc0 \uac74\ubb3c.", "text": "\uc18c\ud314\ub77c \u2014 \uc791\uc740 \ud56d\uad6c \ub4a4\uc5d0\ub294 \uae34 \uae38\uc774 \uc788\uc5c8\ub2e4 \ubc14\ub2e4\uc5d0 \ub3c4\ucc29\ud55c \uae08\uc740 \uc5b4\ub514\uc5d0\uc11c \uc654\uc744\uae4c 17\uc138\uae30 \uc18c\ud314\ub77c \ub3c4\ud310\uc5d0\uc11c \ucd9c\ubc1c\ud574 \ub0b4\ub959\uacfc \uc778\ub3c4\uc591\uc744 \uc774\uc740 \ud56d\uad6c\uc758 \uc5ed\ud560\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Africa \ub3c4\uc2dc \ud56d\uad6c\ub77c\uace0 \ud558\uba74 \ubc14\ub2e4\uc640 \ubc30\ubd80\ud130 \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \ud574\uc548\uc120\uacfc \uadf8 \uc606\uc758 \uac74\ubb3c\ub4e4\uc774 \ub3c4\uc2dc\uc758 \uc804\ubd80\ucc98\ub7fc \ub290\uaef4\uc9c0\uae30\ub3c4 \ud55c\ub2e4. \uadf8\ub7f0\ub370 \ud56d\uad6c\ub97c \ubd80\uc720\ud558\uac8c \ud55c \ubb3c\uac74\uc740 \uadf8\ub9bc\uc5d0 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uba3c \ub0b4\ub959\uc5d0\uc11c \uc654\uc744 \uc218\ub3c4 \uc788\ub2e4. \uc18c\ud314\ub77c\ub294 \uadf8 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uae38\uc744 \uc0dd\uac01\ud558\uac8c \ud558\ub294 \ub3c4\uc2dc\ub2e4. \uc624\ub298\ub0a0 \ubaa8\uc7a0\ube44\ud06c\uc5d0 \uc788\ub294 \uc774 \ud56d\uad6c\ub294 \ub3d9\uc544\ud504\ub9ac\uce74\uc758 \ud574\uc548\uacfc \ub0b4\ub959\uc744 \uc5f0\uacb0\ud588\ub2e4. \ubc30\uac00 \ub4e4\uc5b4\uc624\ub294 \uc790\ub9ac\ub77c\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uadf8 \uc911\uc694\uc131\uc774 \ubaa8\ub450 \uc124\uba85\ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \ubb34\uc5c7\uc774 \uc774\uacf3\uae4c\uc9c0 \uc654\uace0 \ub204\uac00 \ubc14\uae65\uc73c\ub85c \uac00\uc838\uac14\ub294\uc9c0\ub97c \uc0b4\ud53c\uba74 \uc791\uc740 \ud574\uc548 \ub3c4\uc2dc \ub4a4\uc758 \uc138\uacc4\uac00 \ub113\uc5b4\uc9c4\ub2e4. \uc544\ud504\ub9ac\uce74 \ub0b4\ub959\uc5d0\uc11c \ub098\uc628 \uae08\uacfc \uc5ec\ub7ec \ubb3c\ud488\uc740 \ud574\uc548\uc73c\ub85c \uc62e\uaca8\uc84c\ub2e4. \uc18c\ud314\ub77c\ub294 \uc774\ub97c \uc778\ub3c4\uc591 \uad50\uc5ed\uc73c\ub85c \uc787\ub294 \uc911\uc694\ud55c \uc9c0\uc810\uc774\uc5c8\ub2e4. \uc55e\uc120 \uae00\uc5d0\uc11c \ub9cc\ub09c \uadf8\ub808\uc774\ud2b8 \uc9d0\ubc14\ube0c\uc6e8\uc640\ub3c4 \uc5f0\uacb0\ub418\ub294 \uae38\uc774\ub2e4. \ub0b4\ub959\uc758 \ubc88\uc601\uacfc \ud56d\uad6c\uc758 \ubc88\uc601\uc740 \uc11c\ub85c \ub2e4\ub978 \uc9c0\ub3c4\uc758 \uc774\uc57c\uae30\uac00 \uc544\ub2c8\uc5c8\ub2e4. \ud56d\uad6c\uc5d0\uc11c\ub294 \ubb3c\uac74\uc744 \ub0b4\ub9ac\ub294 \uc77c\uacfc \ub2e4\uc74c \uc5ec\uc815\uc744 \uc900\ube44\ud558\ub294 \uc77c\uc774 \ub9cc\ub09c\ub2e4. \uc624\ub7ab\ub3d9\uc548 \uc774\ub3d9\ud55c \uc9d0\ub3c4 \ub204\uad70\uac00\uc5d0\uac8c\ub294 \uc774\uc81c \ub9c9 \uac70\ub798\ud560 \ubb3c\uac74\uc774\ub2e4. \uc5ec\ud589\uc758 \ub05d\uacfc \uc2dc\uc791\uc774 \uac19\uc740 \uc7a5\uc18c\uc5d0 \uacb9\uce5c\ub2e4\ub294 \uad00\uc810\uc73c\ub85c \ubcf4\uba74, \ud56d\uad6c\uac00 \ub2e8\uc9c0 \ubc30\ub97c \uc138\uc6cc \ub450\ub294 \uacf5\uac04 \uc774\uc0c1\uc774\ub77c\ub294 \uc810\uc774 \ubcf4\uc778\ub2e4. \ub3d9\uc544\ud504\ub9ac\uce74 \ud574\uc548\uc758 \uac15\ub825\ud55c \ub3c4\uc2dc\uad6d\uac00 \ud0ac\uc640\ub294 \uc18c\ud314\ub77c\ub97c \ud1b5\ud574 \uae08 \uad50\uc5ed\uc5d0 \uc811\uadfc\ud588\ub2e4. OpenStax\ub294 \ud0ac\uc640\uac00 \uc911\uac04\uc758 \uac70\ub798\uc790\ub97c \uac70\uce58\uc9c0 \uc54a\uace0 \ub354 \uc9c1\uc811\uc801\uc73c\ub85c \uae08\uc744 \ud655\ubcf4\ud558\ub824 \ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uad50\uc5ed\ub9dd\uc758 \ud55c \uc9c0\uc810\uc744 \ud1b5\uc81c\ud558\ub294 \uc77c\uc774 \ub3c4\uc2dc\uc758 \ud798\uacfc \uc5f0\uacb0\ub418\uc5c8\ub358 \uac83\uc774\ub2e4. \ubd80\uc720\ud55c \ud56d\uad6c\uac00 \ubc18\ub4dc\uc2dc \uc790\uae30 \uc8fc\ubcc0\uc5d0\uc11c \uae08\uc744 \uce90\ub294 \uacf3\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \uc0dd\uc0b0\uc9c0\uc640 \uad50\ud658 \uc9c0\uc810\uc744 \uc787\ub294 \uad00\uacc4\ub97c \uc7a5\uc545\ud574 \uc601\ud5a5\ub825\uc744 \uc5bb\uc744 \uc218 \uc788\ub2e4. \ubb3c\uac74\uc774 \uc5b4\ub514\uc5d0\uc11c \ub098\uc624\ub294\uc9c0\uc640 \uadf8 \ubb3c\uac74\uc758 \uc774\ub3d9\uc744 \ub204\uac00 \uc870\uc815\ud558\ub294\uc9c0\ub294 \ub2e4\ub978 \uc9c8\ubb38\uc774\ub2e4. \uc18c\ud314\ub77c\ub97c \ub458\ub7ec\uc2fc \uad00\uc2ec\uc740 \ubc14\ub85c \uadf8 \ucc28\uc774\uc5d0\uc11c \uc0dd\uaca8\ub0ac\ub2e4. \uc2a4\uc640\ud790\ub9ac \ud574\uc548\uc758 \uad50\uc5ed\uc740 \uc778\ub3c4\uc591\uc758 \uacc4\uc808\ud48d\uacfc \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub2e4. \ubc14\ub78c\uc758 \ubc29\ud5a5\uc774 \ubc14\ub00c\ub294 \uc2dc\uae30\ub97c \uc774\uc6a9\ud574 \ud56d\ud574\ud588\uae30 \ub54c\ubb38\uc774\ub2e4. \uc721\uc9c0\uc5d0\uc11c \uacc4\uc808\uc744 \ubcf4\uba70 \ub18d\uc0ac\uc77c\uc744 \uc815\ud558\ub294 \uac83\ucc98\ub7fc \ubc14\ub2e4\uc5d0\uc11c\ub294 \uc774\ub3d9\uc758 \ub54c\ub97c \uc0dd\uac01\ud574\uc57c \ud588\ub2e4. \uc774\uac83\uc740 \ud56d\uad6c\uac00 \uc790\uc5f0\uc758 \uc870\uac74\uc744 \ubb34\uc2dc\ud558\uace0 \uc5b8\uc81c\ub098 \uac19\uc740 \uc18d\ub3c4\ub85c \uc6c0\uc9c1\uc77c \uc218 \uc5c6\uc5c8\ub2e4\ub294 \ub73b\uc774\ub2e4. \ubb3c\uac74\uc744 \ud655\ubcf4\ud558\ub294 \uc77c\ubfd0 \uc544\ub2c8\ub77c \ucd9c\ud56d\uc744 \uae30\ub2e4\ub9ac\uace0 \ub2e4\ub978 \uc9c0\uc5ed\uacfc \ub54c\ub97c \ub9de\ucd94\ub294 \uacfc\uc815\ub3c4 \uc911\uc694\ud588\uc744 \uac83\uc774\ub2e4. \uc2e4\uc81c \ud56d\ud574\uc77c\uc815\uc744 \ucc3d\uc791\ud558\uc9c0 \uc54a\uc544\ub3c4 \uacc4\uc808\ud48d\uc774\ub77c\ub294 \uc870\uac74\uc5d0\uc11c \uad50\uc5ed\uc758 \ub9ac\ub4ec\uc744 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \ub3d9\uc544\ud504\ub9ac\uce74 \ud574\uc548\uc5d0\ub294 \uc544\ud504\ub9ac\uce74 \uc8fc\ubbfc\uacfc \uc544\ub78d\u00b7\ud398\ub974\uc2dc\uc544 \uc9c0\uc5ed\uc5d0\uc11c \uc628 \uc0ac\ub78c\ub4e4\uc774 \uad50\ub958\ud558\ub294 \ub3c4\uc2dc\ub4e4\uc774 \uc788\uc5c8\ub2e4. \uc2a4\uc640\ud790\ub9ac\uc5b4\ub294 \ubc18\ud22c\uacc4 \uc5b8\uc5b4\ub97c \ubc14\ud0d5\uc73c\ub85c \uc544\ub78d\uc5b4 \uc5b4\ud718 \ub4f1\uc758 \uc601\ud5a5\uc744 \ubc1b\uc73c\uba70 \ubc1c\uc804\ud588\ub2e4. \uc11c\ub85c \ub2e4\ub978 \ubc30\uacbd\uc758 \uc0ac\ub78c\ub4e4\uc774 \uac70\ub798\ud558\uace0 \uc0dd\ud65c\ud558\ub294 \ub370 \uacf5\ud1b5\uc758 \ub9d0\uc774 \uc5ed\ud560\uc744 \ud588\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc774 \ub3c4\uc2dc\ub4e4\uc744 \uc678\ubd80\uc778\uc774 \ube48 \ub545\uc5d0 \uc138\uc6b4 \uc7a5\uc18c\ucc98\ub7fc \uc124\uba85\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc9c0\uc5ed \uacf5\ub3d9\uccb4\uc640 \ub0b4\ub959\uc758 \uc0dd\uc0b0, \ud574\uc548\uc758 \uad50\ud658\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4. \ubc14\ub2e4 \uac74\ub108\uc628 \uc0ac\ub78c\uc758 \uae30\ub85d\ub9cc \ubc14\ub77c\ubcf4\uba74 \ud56d\uad6c\uac00 \uae30\ub300\uace0 \uc788\ub358 \ud604\uc9c0\uc758 \uad00\uacc4\uc640 \ub178\ub3d9\uc740 \uc27d\uac8c \ubc30\uacbd\uc73c\ub85c \ubc00\ub824\ub09c\ub2e4. \uc2a4\uc640\ud790\ub9ac \ud574\uc548\uc758 \ub3c4\uc2dc\ub4e4\uc740 \uc11c\ub85c \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\uc9c0\ub9cc \uacbd\uc7c1\ud558\uae30\ub3c4 \ud588\ub2e4. \ud0ac\uc640\uc758 \uc601\ud5a5\ub825\uc5d0\uc11c \ubc97\uc5b4\ub098\ub824\ub294 \ub2e4\ub978 \ub3c4\uc2dc\uc758 \ud1b5\uce58\uc790\ub4e4\uc740 \ud3ec\ub974\ud22c\uac08 \uc138\ub825\uacfc \uad00\uacc4\ub97c \ub9fa\uc5c8\ub2e4. \uc18c\ud314\ub77c\uc758 \uc9c0\ubc30\uc790\ub3c4 16\uc138\uae30 \ucd08 \ud3ec\ub974\ud22c\uac08\uacfc \ud611\uc57d\uc744 \ub9fa\uc5c8\ub2e4\uace0 \uad50\uc7ac\ub294 \uc124\uba85\ud55c\ub2e4. \ub530\ub77c\uc11c \uc544\ud504\ub9ac\uce74 \ub3c4\uc2dc\ub4e4\uacfc \uc720\ub7fd\uc778\uc774 \ucc98\uc74c\ubd80\ud130 \ub450 \ub369\uc5b4\ub9ac\ub85c\ub9cc \ub9de\uc130\ub2e4\uace0 \ubcf4\uba74 \ub2f9\uc2dc\uc758 \uc120\ud0dd\uc744 \ub193\uce5c\ub2e4. \uac00\uae4c\uc6b4 \uacbd\uc7c1\uc790\ub97c \uacac\uc81c\ud558\ub824\ub294 \ud310\ub2e8\uacfc \uc678\ubd80 \uc138\ub825\uc758 \uad50\uc5ed \ud1b5\uc81c \uc695\uad6c\uac00 \uc5bd\ud614\ub2e4. \ud55c\ucabd\uc5d0 \ub3c4\uc6c0\uc774 \ub420 \uac83\ucc98\ub7fc \ubcf4\uc778 \uad00\uacc4\uac00 \uc774\ud6c4\uc5d0\ub3c4 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uc720\uc9c0\ub41c\ub2e4\ub294 \ubcf4\uc7a5\uc740 \uc5c6\uc5c8\ub2e4. \ud3ec\ub974\ud22c\uac08\uc758 \uac1c\uc785\uc740 \ud1b5\uce58\uc790\ub97c \ubc14\uafb8\ub294 \ub370 \uadf8\uce58\uc9c0 \uc54a\uc558\ub2e4. \uad50\uc7ac\ub294 \ud0ac\uc640\uc5d0\uc11c \ubb3c\uac74\uc744 \ud3ec\ub974\ud22c\uac08 \ubc30\ub85c\ub9cc \uc6b4\ubc18\ud558\ub3c4\ub85d \ud55c \uc815\ucc45\uc774 \ud604\uc9c0 \uc0c1\uc778\ub4e4\uc5d0\uac8c \uc190\ud574\ub97c \uc8fc\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud56d\ud574 \uae30\uc220\ubfd0 \uc544\ub2c8\ub77c \uc5b4\ub5a4 \ubc30\ub97c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294\uc9c0\uac00 \uacbd\uc81c\uc758 \ubb38\uc81c\uac00 \ub41c \uac83\uc774\ub2e4. \uc774\ub294 \ud0ac\uc640\uc5d0\uc11c \uc124\uba85\ub41c \uc0ac\ub840\uc774\ubbc0\ub85c \uc18c\ud314\ub77c\uc758 \ub9e4\uc77c\uc758 \uc6b4\uc601\uc5d0 \uadf8\ub300\ub85c \uc62e\uaca8 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \uac19\uc740 \uad50\uc5ed\uad8c\uc5d0\uc11c \uc6b4\uc1a1\uc744 \ud1b5\uc81c\ud558\ub294 \ud798\uc774 \uc5b4\ub5a4 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\uc5c8\ub294\uc9c0\ub294 \ubcf4\uc5ec \uc900\ub2e4. \ud56d\uad6c\uc758 \uc5ed\uc0ac\ub294 \ubb34\uc5c7\uc744 \uc2e4\uc5c8\ub294\uc9c0\ubfd0 \uc544\ub2c8\ub77c \ub204\uac00 \uc6b4\ubc18 \uc870\uac74\uc744 \uc815\ud588\ub294\uc9c0\ub3c4 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 1683\ub144 \uc18c\ud314\ub77c\uc758 \ubaa8\uc2b5\uc744 \ud45c\ud604\ud55c \ub9d0\ub808\uc758 \uc5ed\uc0ac \ub3c4\ud310\uc774\ub2e4. \ubb3c\uae38\uacfc \ubc29\uc5b4 \uc2dc\uc124, \uc8fc\ubcc0 \uac74\ubb3c\uc744 \uad00\ucc30\ud560 \uc218 \uc788\uc9c0\ub9cc \ud604\ub300 \uc9c0\ub3c4\ub098 \ub2f9\uc2dc\uc758 \ubaa8\ub4e0 \uc0dd\ud65c\uc744 \uae30\ub85d\ud55c \uc0ac\uc9c4\uc740 \uc544\ub2c8\ub2e4. \uc720\ub7fd \uc81c\uc791\uc790\uc758 \uc2dc\uc120\uacfc \ud45c\ud604 \ubc29\uc2dd\uc744 \uac70\uce5c \uc790\ub8cc\ub77c\ub294 \uc810\ub3c4 \uae30\uc5b5\ud560 \ub9cc\ud558\ub2e4. \uadf8\ub9bc\uc5d0 \ub0b4\ub959\uc758 \uc0dd\uc0b0\uc9c0\uac00 \uc548 \ubcf4\uc778\ub2e4\uace0 \ud56d\uad6c\uc640 \ubb34\uad00\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ud788\ub824 \ubc14\ub2e4 \ucabd\uc5d0\uc11c \uadf8\ub9b0 \uadf8\ub9bc\uc774 \ubb34\uc5c7\uc744 \uc798 \ubcf4\uc5ec \uc8fc\uace0 \ubb34\uc5c7\uc744 \ud654\uba74 \ubc16\uc73c\ub85c \ub0a8\uacbc\ub294\uc9c0 \uc9c8\ubb38\ud560 \uc218 \uc788\ub2e4. \ud48d\uacbd\uc744 \ubcf4\ub294 \uc7ac\ubbf8\uc5d0 \ubb3c\uac74\uc758 \ucd9c\ubc1c\uc9c0\ub97c \ucc3e\ub294 \uad00\uc2ec\uc774 \ub354\ud574\uc9c4\ub2e4. \uc18c\ud314\ub77c\ub97c \uae30\uc5b5\ud560 \ub54c\ub294 \uae08\ube5b \ub3c4\uc2dc\ub97c \ub9c9\uc5f0\ud788 \uc0c1\uc0c1\ud558\uae30\ubcf4\ub2e4 \uae38\uc774 \ub9cc\ub098\ub294 \uc790\ub9ac\ub97c \ub5a0\uc62c\ub824 \ubcf4\uc790. \ub0b4\ub959\uc5d0\uc11c \uc628 \uc9d0\uacfc \uacc4\uc808\ud48d\uc744 \uae30\ub2e4\ub9ac\ub294 \ubc30, \uadf8 \uc0ac\uc774\ub97c \uc5f0\uacb0\ud55c \uc0ac\ub78c\ub4e4\uc758 \uac70\ub798\uac00 \uc788\uc5c8\ub2e4. \uc791\uc740 \ud574\uc548\uc120\uc740 \ud6e8\uc52c \ub113\uc740 \uad00\uacc4\uc758 \ud55c \ubd80\ubd84\uc774\uc5c8\ub2e4. \ub2e4\ub978 \ud56d\uad6c\ub97c \ubcfc \ub54c\ub3c4 \uac19\uc740 \uc9c8\ubb38\uc744 \ud574 \ubcfc \uc218 \uc788\ub2e4. \ubc30\uac00 \uc5b4\ub514\ub85c \uac00\ub294\uc9c0\ub9cc\uc774 \uc544\ub2c8\ub77c \uadf8 \ubc30\uc5d0 \uc2e4\ub9b0 \uac83\uc774 \uc5b4\ub514\uc5d0\uc11c \uc654\ub294\uac00. \uc18c\ud314\ub77c\ub294 \ubc14\ub2e4 \uc55e\uc5d0 \uc120 \ub3c4\uc2dc\uc774\uba74\uc11c, \ub4a4\ucabd\uc758 \uae34 \uc721\uc9c0 \uae38\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \uc774\ud574\ud560 \uc218 \uc788\ub294 \uc7a5\uc18c\uc600\ub2e4."}, {"id": "suzhou-grand-canal-and-city", "title": "\uc464\uc800\uc6b0 \u2014 \ubc30 \ud55c \ucc99\uc774 \ub3c4\uc2dc\uc758 \uae38\uc774 \ub418\ub358 \ud48d\uacbd", "summary": "\uccad\ub300 \uad81\uc815 \ud68c\ud654 \uc18d \uc464\uc800\uc6b0\uc758 \ubb3c\uae38\uc744 \ub530\ub77c \ub3c4\uc2dc\uc640 \ub300\uc6b4\ud558\uc758 \uc5f0\uacb0\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "cities", "category_title": "Cities", "subcategory": "Asia", "url": "stories/suzhou-grand-canal-and-city/index.html", "image": "media/suzhou-grand-canal-and-city.jpg", "alt": "\uac74\ub96d\uc81c\uc758 \ub0a8\ubc29 \uc21c\ud589 \uadf8\ub9bc \uc77c\ubd80\uc5d0 \ub098\ud0c0\ub09c \uc464\uc800\uc6b0\uc758 \ubc30\uc640 \ubb3c\uac00\uc758 \uc0ac\ub78c\ub4e4, \uac74\ubb3c.", "text": "\uc464\uc800\uc6b0 \u2014 \ubc30 \ud55c \ucc99\uc774 \ub3c4\uc2dc\uc758 \uae38\uc774 \ub418\ub358 \ud48d\uacbd \ud669\uc81c\uc758 \uc21c\ud589 \uadf8\ub9bc\uc5d0\uc11c \uc6b4\ud558\uc758 \uc77c\uc0c1\uc744 \ub4e4\uc5ec\ub2e4\ubcf4\ub2e4 \uccad\ub300 \uad81\uc815 \ud68c\ud654 \uc18d \uc464\uc800\uc6b0\uc758 \ubb3c\uae38\uc744 \ub530\ub77c \ub3c4\uc2dc\uc640 \ub300\uc6b4\ud558\uc758 \uc5f0\uacb0\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Asia \ub3c4\uc2dc \uae38\uc744 \uc124\uba85\ud560 \ub54c \uc6b0\ub9ac\ub294 \ub300\uac1c \uc624\ub978\ucabd\uc73c\ub85c \ub3cc\uc544 \uace8\ubaa9\uc744 \uc9c0\ub098\ub77c\uace0 \ub9d0\ud55c\ub2e4. \ud558\uc9c0\ub9cc \ubb3c\uae38\uc774 \uc0dd\ud65c \uae4a\uc219\uc774 \ub4e4\uc5b4\uc628 \ub3c4\uc2dc\ub77c\uba74 \ubc30\ub97c \uc5b4\ub514\uc5d0 \ub300\ub294\uc9c0\ub3c4 \uc911\uc694\ud55c \uc548\ub0b4\uac00 \ub41c\ub2e4. \uc911\uad6d \uc464\uc800\uc6b0\uc758 \uc61b \ud48d\uacbd\uc5d0\ub294 \uc9d1\uacfc \ub098\ubb34, \uc0ac\ub78c\uacfc \ubc30\uac00 \ubb3c\uac00\ub97c \uc911\uc2ec\uc73c\ub85c \ub098\ub780\ud788 \ub193\uc5ec \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\uc5d0\uc11c\ub294 \ucee4\ub2e4\ub780 \ubc30\ub97c \uba3c\uc800 \ucc3e\uac8c \ub41c\ub2e4. \uadf8\ub2e4\uc74c\uc5d0\ub294 \uae30\uc2ad\uc5d0 \uc120 \uc0ac\ub78c\ub4e4\uacfc \uac74\ubb3c \uc0ac\uc774\ub97c \ucc9c\ucc9c\ud788 \ubcf4\uc790. \ud669\uc81c\uc758 \uc5ec\ud589\uc744 \uae30\ub150\ud55c \uc7a5\uba74\uc774\uc9c0\ub9cc, \ub208\uae38\uc744 \uc870\uae08 \uc62e\uae30\uba74 \ubb3c\uc744 \uae38\ub85c \uc0bc\uc740 \ub3c4\uc2dc\uac00 \uc5b4\ub5bb\uac8c \ubcf4\uc600\ub294\uc9c0\ub3c4 \uc77d\uc744 \uc218 \uc788\ub2e4. \uc774 \ub3c4\ud310\uc740 \uac74\ub96d\uc81c\uc758 \ub0a8\ubc29 \uc21c\ud589\uc744 \uadf8\ub9b0 \uae34 \ub450\ub8e8\ub9c8\ub9ac \uac00\uc6b4\ub370 \uc464\uc800\uc6b0\ub85c \ub4e4\uc5b4\uc624\ub294 \uc7a5\uba74\uc758 \uc77c\ubd80\ub2e4. 1751\ub144\uc758 \uc5ec\ud589\uc744 \uae30\ub150\ud574 18\uc138\uae30 \uad81\uc815 \ud654\uac00\uac00 \uc81c\uc791\ud55c \uadf8\ub9bc\uc73c\ub85c \uad50\uc7ac\uc5d0 \uc18c\uac1c\ub418\uc5b4 \uc788\ub2e4. \uc5ec\ud589\ud55c \ub54c\uc640 \uadf8\ub9bc\uc744 \uc644\uc131\ud55c \ub54c\ub294 \uad6c\ubcc4\ud574\uc57c \ud55c\ub2e4. \uc0ac\uc9c4\ucc98\ub7fc \uc6b0\uc5f0\ud788 \ud3ec\ucc29\ud55c \ud558\ub8e8\ub3c4 \uc544\ub2c8\ub2e4. \ud1b5\uce58\uc790\uc758 \uc774\ub3d9\uc744 \uae30\ub85d\ud558\uace0 \uae30\ub150\ud558\ub824\ub294 \ubaa9\uc801\uc774 \uc788\ub294 \uad81\uc815 \ud68c\ud654\ub2e4. \ud654\uba74\uc758 \uc7a5\uba74\uc744 \uc790\uc138\ud788 \ubcfc \uc218 \uc788\uc73c\uba74\uc11c\ub3c4, \uadf8 \ubaa8\uc2b5\uc774 \ub2f9\uc2dc \uc8fc\ubbfc\uc758 \ud558\ub8e8\ub97c \uc544\ubb34\ub7f0 \uc120\ud0dd \uc5c6\uc774 \ubcf4\uc5ec \uc900\ub2e4\uace0 \uc0dd\uac01\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \uc774 \uadf8\ub9bc\uc744 \uc77d\ub294 \uccab\uac78\uc74c\uc774\ub2e4. \uadf8\ub9bc \ud55c\uac00\uc6b4\ub370 \ud070 \ubc30\uac00 \uc788\uace0 \uc591\ucabd\uc5d0\ub294 \uc0ac\ub78c\ub4e4\uc774 \uc11c \uc788\ub2e4. \uac74\ubb3c\uc740 \ubb3c\uc744 \uba40\ub9ac \ubc00\uc5b4\ub0b4\uc9c0 \uc54a\uace0 \uae30\uc2ad\uc744 \ub530\ub77c \uac00\uae4c\uc774 \ub193\uc5ec \uc788\ub2e4. \ubc30\uac00 \ub3c4\uc2dc \ubc14\uae65\uc5d0 \uc7a0\uc2dc \uc815\ubc15\ud55c \uc7a5\uba74\uc774\ub77c\uae30\ubcf4\ub2e4, \ubb3c\uae38\uc774 \uc2dc\uac00\uc9c0\uc758 \uc911\uc694\ud55c \ud1b5\ub85c\ub77c\ub294 \ub290\ub08c\uc744 \uc900\ub2e4. \uc5ec\uae30\uc11c \uad00\uc2ec\uc744 \ubc30 \ud55c \ucc99\uc5d0\uc11c \ubb3c\uacfc \uc721\uc9c0\uc758 \uc811\uc810\uc73c\ub85c \uc62e\uaca8 \ubcf4\uc790. \uc0ac\ub78c\uc774 \ubaa8\uc778 \uae30\uc2ad\uacfc \uac74\ubb3c\ub85c \uc774\uc5b4\uc9c0\ub294 \uae38, \ubc30\uac00 \ub2e4\uac00\uac08 \uc218 \uc788\ub294 \uc790\ub9ac\uac00 \ud568\uaed8 \ubcf4\uc778\ub2e4. \ub3c4\uc2dc\uc758 \ubb3c\uae38\uc740 \uacbd\uce58\uac00 \uc544\ub984\ub2e4\uc6b4 \uacf5\uac04\uc774\uba74\uc11c \uc0ac\ub78c\uacfc \ubb3c\uac74\uc774 \ub9cc\ub098\ub294 \uc2e4\uc6a9\uc801\uc778 \uc790\ub9ac\uc774\uae30\ub3c4 \ud588\ub2e4. \ub208\uc744 \ubb3c\uac00\uc758 \uc791\uc740 \uc778\ubb3c\ub4e4\ub85c \uc62e\uae30\uba74 \ud654\uba74\uc744 \uc77d\ub294 \uc18d\ub3c4\ub3c4 \ub290\ub824\uc9c4\ub2e4. \ucee4\ub2e4\ub780 \ubc30\ub97c \ub2e8\ubc88\uc5d0 \uc54c\uc544\ubcf4\ub294 \uac83\uacfc \ub2ec\ub9ac, \uc904\uc9c0\uc5b4 \uc120 \uc0ac\ub78c\uacfc \ub0ae\uc740 \uc9c0\ubd95\uc740 \ud55c \ubd80\ubd84\uc529 \ubcf4\uc544\uc57c \ud55c\ub2e4. \ub450\ub8e8\ub9c8\ub9ac\uc758 \uc7ac\ubbf8\ub294 \uc774\ub807\uac8c \uc2dc\uc120\uc744 \uc62e\uae38 \ub54c \uc8fc\uc778\uacf5 \ub4a4\uc758 \ub3c4\uc2dc\uac00 \uc870\uae08\uc529 \ub4dc\ub7ec\ub09c\ub2e4\ub294 \ub370\ub3c4 \uc788\ub2e4. \uc911\uad6d\uc758 \ud070 \uac15\ub4e4\uc740 \ub300\uccb4\ub85c \ub3d9\ucabd \ubc14\ub2e4\ub97c \ud5a5\ud574 \ud750\ub978\ub2e4. \ubc18\uba74 \ub113\uc740 \ub098\ub77c \uc548\uc5d0\uc11c\ub294 \ub0a8\ucabd\uacfc \ubd81\ucabd\uc744 \uc787\ub294 \uc774\ub3d9\ub3c4 \ud544\uc694\ud588\ub2e4. \uc9c0\uc5ed\ub9c8\ub2e4 \uc0dd\uc0b0\ud558\ub294 \uace1\ubb3c\uacfc \uae30\ud6c4\uac00 \ub2ec\ub790\uace0, \ubd81\ucabd\uc758 \ud070 \ub3c4\uc2dc\uc640 \uad8c\ub825 \uc911\uc2ec\uc5d0\ub294 \uc9c0\uc18d\uc801\uc778 \ubb3c\uc790 \uacf5\uae09\uc774 \ud544\uc694\ud588\ub2e4. \ub300\uc6b4\ud558\ub294 \uc774\ub7f0 \ubc29\ud5a5\uc758 \ucc28\uc774\ub97c \uc0ac\ub78c\uc758 \uc190\uc73c\ub85c \uc5f0\uacb0\ud55c \uac70\ub300\ud55c \ubb3c\uae38 \uccb4\uacc4\uc600\ub2e4. \ud55c \uc655\uc774 \uc5b4\ub290 \ub0a0 \ube48 \ub545\uc5d0 \ucc98\uc74c\ubd80\ud130 \ub05d\uae4c\uc9c0 \uadf8\uc5c8\ub2e4\uae30\ubcf4\ub2e4, \uc55e\uc120 \uc218\ub85c\ub97c \uc5ec\ub7ec \uc2dc\ub300\uc5d0 \uac78\uccd0 \uc5f0\uacb0\ud558\uace0 \uace0\uce58\uba70 \ud655\ub300\ud588\ub2e4. \uc9c0\ub3c4 \uc704\uc758 \ud55c \uc904\uc5d0\ub294 \uc11c\ub85c \ub2e4\ub978 \uc2dc\uae30\uc758 \uacf5\uc0ac\uc640 \ubaa9\uc801\uc774 \uacb9\uccd0 \uc788\ub2e4. \uc300\uc774\ub098 \ubc00 \uac19\uc740 \ubb3c\uac74\uc744 \ub9ce\uc774 \uc62e\uae30\ub824\uba74 \uc6b4\ubc18 \uc790\uccb4\uac00 \uc911\uc694\ud55c \ubb38\uc81c\uac00 \ub41c\ub2e4. \ud55c \uc0ac\ub78c\uc774 \ub4dc\ub294 \uc9d0\uacfc \ubc30\uc5d0 \uc2e4\uc5b4 \ubcf4\ub0b4\ub294 \uc9d0\uc740 \uac00\ub2a5\ud55c \uaddc\ubaa8\uac00 \ub2e4\ub974\ub2e4. \ub300\uc6b4\ud558\ub294 \ub0a8\ubd81\uc758 \uc2dd\ub7c9\uacfc \ubb3c\uc790 \uc774\ub3d9\uc744 \uac00\ub2a5\ud558\uac8c \ud558\uba70 \ub5a8\uc5b4\uc9c4 \uc9c0\uc5ed\uc758 \uacbd\uc81c\ub97c \uc5f0\uacb0\ud588\ub2e4. \ub3c4\uc2dc\ub294 \uc790\uae30 \uc548\uc5d0\uc11c \ub9cc\ub4e0 \uac83\ub9cc\uc73c\ub85c \uc0b4\uc544\uac00\uc9c0 \uc54a\ub294\ub2e4. \uba3c \uacf3\uc758 \uc0dd\uc0b0\uc774 \ub3c4\ucc29\ud558\uace0 \ub3c4\uc2dc\uc758 \ud544\uc694\uac00 \ub2e4\uc2dc \ub2e4\ub978 \uacf3\uc73c\ub85c \uc804\ud574\uc9c4\ub2e4. \ubb3c\uae38 \uc606\uc758 \uc9d1\ub4e4\uc744 \ubcf4\uba74\uc11c \uc791\uc740 \ub9c8\uc744 \uac19\uc740 \uce5c\uadfc\ud568\uc744 \ub290\ub084 \uc218 \uc788\uc9c0\ub9cc, \uadf8 \ubc30\uacbd\uc5d0\ub294 \ud6e8\uc52c \ub113\uc740 \ubc94\uc704\uc758 \uacf5\uae09\uacfc \uc18c\ube44\uac00 \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub358 \uc148\uc774\ub2e4. \uad50\uc7ac\ub294 \uc218\ub098\ub77c\uc758 \ub300\uaddc\ubaa8 \uc218\ub85c \uacf5\uc0ac\uc5d0 \uac15\uc81c\ub85c \ub3d9\uc6d0\ub41c \ub178\ub3d9\uc774 \uc788\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub0a8\ubd81\uc744 \uc787\ub294 \uc2dc\uc124\uc740 \ubb3c\uc790\ub97c \ud3b8\ub9ac\ud558\uac8c \uc62e\uae30\ub294 \ud1b5\ub85c\uc600\uc9c0\ub9cc, \uadf8\uac83\uc744 \ub9cc\ub4dc\ub294 \uacfc\uc815\uae4c\uc9c0 \ubaa8\ub450\uc5d0\uac8c \uc88b\uc740 \uacbd\ud5d8\uc774\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc6b4\ud558\uc758 \uc131\uacfc\uc640 \uac74\uc124\uc758 \ubd80\ub2f4\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc644\uc131\ub41c \ud48d\uacbd\uc5d0\uc11c\ub294 \uacf5\uc0ac \ud604\uc7a5\uacfc \ucc38\uc5ec\ud55c \uc0ac\ub78c\uc758 \uc774\ub984\uc774 \ubcf4\uc774\uc9c0 \uc54a\uc744 \ub54c\uac00 \ub9ce\ub2e4. \ubb3c \uc704\ub97c \uc774\ub3d9\ud558\ub294 \ud669\uc81c\uc758 \ubc30\uac00 \ub208\uae38\uc744 \ub04c\uc218\ub85d, \uadf8 \uc774\ub3d9\uc744 \uac00\ub2a5\ud558\uac8c \ud55c \uae38\uc740 \ub204\uac00 \ub9cc\ub4e4\uace0 \uc720\uc9c0\ud588\uc744\uae4c\ub77c\ub294 \uc9c8\ubb38\ub3c4 \ub0a8\uaca8 \ub458 \uc218 \uc788\ub2e4. \uadf8\ub9bc\uc758 \uc544\ub984\ub2e4\uc6c0\uc744 \uac10\uc0c1\ud558\ub294 \uc77c\uacfc \uadf8\ub7f0 \uc9c8\ubb38\uc740 \ucda9\ub3cc\ud558\uc9c0 \uc54a\ub294\ub2e4. \uadf8\ub9bc\uc758 \ud070 \ubc30\ub294 \ud2b9\ubcc4\ud55c \uc21c\ud589\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc774 \ubc30\uc758 \uc7a5\uc2dd\uacfc \ud06c\uae30\ub97c \ub2f9\uc2dc \ubaa8\ub4e0 \uc6b4\ubc18\uc120\uc758 \ud45c\uc900\uc73c\ub85c \uc774\ud574\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc606\uc758 \uc791\uc740 \ubc30\uc640 \uae30\uc2ad\uc758 \uc0ac\ub78c\ub4e4\uc744 \ud568\uaed8 \uc0b4\ud3b4\ubcf4\uba74 \ud55c \ud654\uba74 \uc548\uc5d0\uc11c\ub3c4 \uc11c\ub85c \ub2e4\ub978 \uc5ed\ud560\uacfc \uaddc\ubaa8\uac00 \ub4dc\ub7ec\ub09c\ub2e4. \ud654\uac00\ub294 \uc5b4\ub5a4 \uc7a5\uba74\uc744 \uae38\uac8c \ubcf4\uc5ec \uc8fc\uace0 \ubb34\uc5c7\uc744 \ud654\uba74\uc5d0\uc11c \ub35c\uc5b4 \ub0c8\uc744\uae4c. \uc774 \uc9c8\ubb38\uc744 \uac00\uc9c0\uace0 \ubcf4\uba74 \ub450\ub8e8\ub9c8\ub9ac\ub294 \ub2e8\uc21c\ud55c \ub3c4\uc2dc \uc548\ub0b4\ub3c4\uac00 \uc544\ub2c8\ub77c \ub3c4\uc2dc\ub97c \ubc14\ub77c\ubcf4\ub294 \ud55c \ubc29\uc2dd\uc774 \ub41c\ub2e4. \ub2f9\uc2dc\uc758 \uc464\uc800\uc6b0\ub97c \uad81\uae08\ud574\ud558\ub294 \ub9c8\uc74c\uacfc \uad81\uc815\uc774 \ubcf4\uc5ec \uc8fc\ub824 \ud55c \uc464\uc800\uc6b0\ub97c \uc77d\ub294 \uc77c\uc774 \ud568\uaed8 \uc2dc\uc791\ub41c\ub2e4. \uad50\uc7ac\ub294 \uadf8\ub9bc \uc18d \uc6b4\ud558 \uad6c\uac04\uc774 \uc624\ub298\ub0a0\uc5d0\ub294 \ub2f9\uc2dc\ucc98\ub7fc \uc4f0\uc774\uc9c0 \uc54a\ub294 \uacf3\uc774\ub77c\uace0 \uc124\uba85\ud55c\ub2e4. \uc774 \ub3c4\ud310\ub9cc \ub4e4\uace0 \ud604\uc7ac\uc758 \ubc30\ud3b8\uc774\ub098 \uc0b0\ucc45\ub85c\ub97c \uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc61b \ubb3c\uae38\uacfc \uc9c0\uae08\uc758 \ub3c4\uc2dc\ub97c \ube44\uad50\ud558\ub824\uba74 \ubcc4\ub3c4\uc758 \ud604\uc7ac \uc790\ub8cc\uac00 \ud544\uc694\ud558\ub2e4. \uadf8 \ub300\uc2e0 \uc774 \uadf8\ub9bc\uc740 \ub3c4\uc2dc\ub97c \uc774\ud574\ud558\ub294 \uc2dc\uc120\uc744 \ub113\ud600 \uc900\ub2e4. \uae38\uc740 \uc5b8\uc81c\ub098 \uc544\uc2a4\ud314\ud2b8\uc77c \ud544\uc694\uac00 \uc5c6\uace0, \uac74\ubb3c\uc758 \uc815\uba74\uc740 \ucc28\ub3c4\ub9cc \ud5a5\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc464\uc800\uc6b0\uc758 \ubc30\uc640 \uae30\uc2ad\uc744 \ucc9c\ucc9c\ud788 \ubcf4\uace0 \ub098\uba74 \ub0af\uc120 \uc61b \ud48d\uacbd\uc5d0\uc11c \uc6b0\ub9ac\uac00 \uc0ac\ub294 \ub3c4\uc2dc\uc5d0\ub3c4 \ud544\uc694\ud55c \uc9c8\ubb38\uc774 \ub5a0\uc624\ub978\ub2e4. \uc624\ub298\uc758 \uc0dd\ud65c\uc740 \uc5b4\ub5a4 \uae38\uc744 \ud1b5\ud574 \ub2e4\ub978 \uacf3\uacfc \uc5f0\uacb0\ub418\uc5b4 \uc788\uc744\uae4c."}, {"id": "tenochtitlan-lake-and-city", "title": "\ud14c\ub178\uce58\ud2f0\ud2c0\ub780 \u2014 \ud638\uc218 \uc704\uc758 \ub3c4\uc2dc\ub294 \uc5b4\ub5bb\uac8c \uba39\uace0\uc0b4\uc558\uc744\uae4c", "summary": "\uc544\uc2a4\ud14c\uce74 \uc218\ub3c4\uc758 \uc81c\ubc29\uae38\uacfc \uce58\ub0a8\ud30c, \uacf5\ub0a9\uc744 \ud1b5\ud574 \ud070 \ub3c4\uc2dc\ub97c \uc720\uc9c0\ud558\ub294 \uc77c\uc0c1\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "cities", "category_title": "Cities", "subcategory": "Americas", "url": "stories/tenochtitlan-lake-and-city/index.html", "image": "media/tenochtitlan-lake-and-city.jpg", "alt": "\ud14c\ub178\uce58\ud2f0\ud2c0\ub780 \ud15c\ud50c\ub85c \ub9c8\uc694\ub974\uc758 \uc30d\ub465\uc774 \uc2e0\uc804\uacfc \uacc4\ub2e8\uc744 \ud45c\ud604\ud55c \ud604\ub300 \ubaa8\ud615\uc758 \uc0ac\uc9c4.", "text": "\ud14c\ub178\uce58\ud2f0\ud2c0\ub780 \u2014 \ud638\uc218 \uc704\uc758 \ub3c4\uc2dc\ub294 \uc5b4\ub5bb\uac8c \uba39\uace0\uc0b4\uc558\uc744\uae4c \ud53c\ub77c\ubbf8\ub4dc \ub108\uba38\uc5d0\uc11c \ub9cc\ub098\ub294 \ubb3c\uae38\uacfc \ubc2d, \uc9d1\uc758 \uc774\uc57c\uae30 \uc544\uc2a4\ud14c\uce74 \uc218\ub3c4\uc758 \uc81c\ubc29\uae38\uacfc \uce58\ub0a8\ud30c, \uacf5\ub0a9\uc744 \ud1b5\ud574 \ud070 \ub3c4\uc2dc\ub97c \uc720\uc9c0\ud558\ub294 \uc77c\uc0c1\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Americas \ub3c4\uc2dc \ud070 \ub3c4\uc2dc\ub97c \uc9d3\uace0 \uc2f6\uc740\ub370 \ub208\uc55e\uc5d0 \ud638\uc218\uac00 \uc788\ub2e4. \ubb3c\uc744 \ud53c\ud574 \ub2e4\ub978 \uacf3\uc73c\ub85c \uac00\ub294 \ubc29\ubc95\ub3c4 \uc788\uaca0\uc9c0\ub9cc, \uba55\uc2dc\ucf54 \ubd84\uc9c0\uc5d0\uc11c\ub294 \ud638\uc218\uc758 \uc12c\ub4e4\uc774 \uac70\ub300\ud55c \uc218\ub3c4\uc758 \ubc14\ud0d5\uc774 \ub418\uc5c8\ub2e4. \uc544\uc2a4\ud14c\uce74\uc758 \ud14c\ub178\uce58\ud2f0\ud2c0\ub780\uc774\ub2e4. \uc774\ub984\uc740 \uc870\uae08 \uae38\uc5b4\ub3c4 \ucd9c\ubc1c \uc7a5\uba74\uc740 \uc27d\uac8c \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \uc774 \ub3c4\uc2dc\ub97c \uc124\uba85\ud560 \ub54c\ub294 \ub192\uc774 \uc19f\uc740 \uc2e0\uc804\uc774 \uba3c\uc800 \ub4f1\uc7a5\ud558\uace4 \ud55c\ub2e4. \uadf8\ub7ec\ub098 \uc2e0\uc804 \uacc4\ub2e8 \uc544\ub798\uc5d0\uc11c\ub3c4 \ub9e4\uc77c \uc2dd\uc0ac\uac00 \ud544\uc694\ud588\uace0, \uc0ac\ub78c\uc740 \uc9d1\uc73c\ub85c \ub3cc\uc544\uac00\uc57c \ud588\uc73c\uba70, \ubb3c\uac74\uc740 \uc81c\ub54c \ub3c4\ucc29\ud574\uc57c \ud588\ub2e4. \uc624\ub298\uc740 \uc720\uba85\ud55c \uaf2d\ub300\uae30\ubcf4\ub2e4 \ub3c4\uc2dc\ub97c \uacc4\uc18d \uc6c0\uc9c1\uc774\uac8c \ud55c \ub0ae\uc740 \uacf3\uc758 \uc774\uc57c\uae30\ub97c \ub530\ub77c\uac00 \ubcf4\uc790. \uc544\uc2a4\ud14c\uce74 \uc0ac\ub78c\ub4e4\uc740 1325\ub144 \ubb34\ub835 \ud14d\uc2a4\ucf54\ucf54\ud638\uc758 \uc12c\ub4e4\uc5d0\uc11c \ub3c4\uc2dc\ub97c \ub9cc\ub4e4\uae30 \uc2dc\uc791\ud588\ub2e4. \ucd08\uae30\uc5d0\ub294 \uc8fc\ubcc0 \uc138\ub825\uacfc \uac70\ub798\ud558\uace0 \uad70\uc0ac \ud65c\ub3d9\uc5d0 \ucc38\uc5ec\ud558\uba70 \uc0b4\uc544\ub0a8\uc558\ub2e4. \ucc98\uc74c\ubd80\ud130 \uba55\uc2dc\ucf54 \uc911\ubd80\ub97c \uc9c0\ubc30\ud558\ub294 \uac70\ub300\ud55c \uc218\ub3c4\uac00 \uc644\uc131\ub418\uc5b4 \uc788\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. 1428\ub144\uc5d0\ub294 \ud14c\ub178\uce58\ud2f0\ud2c0\ub780\uc774 \ud14d\uc2a4\ucf54\ucf54, \ud2c0\ub77c\ucf54\ud310\uacfc \uc0bc\uac01\ub3d9\ub9f9\uc744 \uc774\ub8e8\uc5b4 \uc9c0\uc5ed\uc758 \uac15\ub825\ud55c \uc138\ub825\uc744 \uaebe\uc5c8\ub2e4. \uc774\ud6c4 \uc9c0\ubc30 \uc601\uc5ed\uc774 \ud655\ub300\ub418\uba74\uc11c \uc218\ub3c4\uc758 \uc704\uc0c1\ub3c4 \ucee4\uc84c\ub2e4. \ub3c4\uc2dc\ub294 \uc88b\uc740 \uc790\ub9ac\uc5d0 \uac74\ubb3c\uc744 \ubaa8\uc740 \uacb0\uacfc\uc778 \ub3d9\uc2dc\uc5d0, \uc8fc\ubcc0\uacfc \uc5b4\ub5a4 \uad00\uacc4\ub97c \ub9fa\uc5c8\ub294\uc9c0\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uc7a5\uc18c\uc600\ub2e4. 16\uc138\uae30 \ucd08 \ud14c\ub178\uce58\ud2f0\ud2c0\ub780\uc740 \uc801\uc5b4\ub3c4 20\ub9cc \uba85\uc774 \uc0b4\uc558\ub358 \uac83\uc73c\ub85c \uad50\uc7ac\ub294 \uc124\uba85\ud55c\ub2e4. \ub2f9\uc2dc\uc758 \uc815\ud655\ud55c \uc778\uad6c\ub97c \uc624\ub298\ub0a0 \uc8fc\ubbfc\ub4f1\ub85d \ud1b5\uacc4\ucc98\ub7fc \ud655\uc815\ud560 \uc218\ub294 \uc5c6\uc9c0\ub9cc, \ub300\uaddc\ubaa8 \ub3c4\uc2dc\uc600\ub2e4\ub294 \uc810\uc740 \ubd84\uba85\ud558\ub2e4. \uc12c\uacfc \ud638\uc22b\uac00\ub97c \uc5f0\uacb0\ud558\ub294 \ud070 \uc81c\ubc29\uae38\ub4e4\uc774 \ubc14\uae65\uc73c\ub85c \ubed7\uc5b4 \uc788\uc5c8\ub2e4. \uc81c\ubc29\uae38\uc740 \uc131\uacfd\ub3c4\uc2dc\uc758 \ubb38 \uc55e \ub3c4\ub85c\uc640\ub294 \uc870\uac74\uc774 \ub2e4\ub974\ub2e4. \uc591\uc606\uc774 \ubb3c\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \uc0ac\ub78c\uacfc \ubb3c\uc790\uac00 \ub4dc\ub098\ub4dc\ub294 \uc5f0\uacb0\ubd80\uac00 \uc5b4\ub514\uc5d0 \ub193\uc600\ub294\uc9c0 \uc0dd\uac01\ud574 \ubcf4\uba74, \ud638\uc218\uac00 \ub3c4\uc2dc\ub97c \ubcf4\ud638\ud558\ub294 \ud658\uacbd\uc774\uba74\uc11c \uc774\ub3d9\uc758 \ubc29\ubc95\uc744 \ub530\ub85c \ub9c8\ub828\ud574\uc57c \ud558\ub294 \uc870\uac74\uc774\uae30\ub3c4 \ud588\uc74c\uc744 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \ub3c4\uc2dc \uc8fc\ubcc0\uc5d0\ub294 \uce58\ub0a8\ud30c\ub77c\uace0 \ubd80\ub974\ub294 \uc778\uacf5\uc801\uc73c\ub85c \uc870\uc131\ud55c \uacbd\uc791\uc9c0\uac00 \uc788\uc5c8\ub2e4. \ud754\ud788 \ubb3c \uc704\uc758 \ubc2d\uc774\ub77c\ub294 \ub9d0\ub9cc \ub4e3\uace0 \uc791\uc740 \ub5cf\ubaa9\ucc98\ub7fc \ub5a0\ub2e4\ub2c8\ub294 \ubaa8\uc2b5\uc744 \uc0c1\uc0c1\ud558\uc9c0\ub9cc, \ud638\uc218\uc758 \uc595\uc740 \uacf3\uc5d0 \ud759 \ub4f1\uc744 \uc313\uc544 \ub9cc\ub4e0 \uace0\uc815\ub41c \ubc2d\uc73c\ub85c \uc774\ud574\ud558\ub294 \ud3b8\uc774 \ub9de\ub2e4. \uadf8 \uc0ac\uc774\uc758 \uc218\ub85c\ub294 \ubb3c\uc744 \ub300\uace0 \uc774\ub3d9\ud558\ub294 \ub370 \uc4f0\uc600\ub2e4. \uc774 \ubc2d\ub4e4\uc740 \ub3c4\uc2dc \uc8fc\ubbfc\uc5d0\uac8c \uba39\uc744\uac70\ub9ac\ub97c \uacf5\uae09\ud588\ub2e4. \uac74\ubb3c\uc744 \uc138\uc6b4 \ub4a4 \uc2dd\ub7c9 \ubb38\uc81c\ub97c \ub530\ub85c \ud574\uacb0\ud55c \uac83\uc774 \uc544\ub2c8\ub77c, \uc0b4 \uacf5\uac04\uacfc \uc0dd\uc0b0\ud560 \uacf5\uac04, \ubb3c\uae38\uc774 \ud568\uaed8 \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub358 \uac83\uc774\ub2e4. \uc624\ub298\ub0a0 \ub3c4\uc2dc\uc758 \uc2dd\uc7ac\ub8cc\uac00 \uc5b4\ub514\uc11c \uc624\ub294\uc9c0 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uac83\uacfc \ube44\uad50\ud558\uba74 \ud638\uc218 \ub3c4\uc2dc\uc758 \uad6c\uc870\uac00 \ub354 \uad6c\uccb4\uc801\uc73c\ub85c \ub290\uaef4\uc9c4\ub2e4. \uc8fc\ubbfc\uc758 \uc9d1\uc740 \ud759\ubcbd\ub3cc\uacfc \ud3c9\ud3c9\ud55c \uc9c0\ubd95, \uc791\uc740 \ub9c8\ub2f9\uc744 \uac16\ucd98 \ud615\ud0dc\uac00 \ub9ce\uc558\ub2e4. \ub3c4\uc2dc \uc911\uc2ec\uc5d0\ub294 \uc2e0\uc804\uacfc \uacf5\ub180\uc774 \uacbd\uae30\uc7a5, \ud589\uc815 \uac74\ubb3c\uacfc \uc9c0\ubc30\uce35\uc758 \uac70\ucc98\uac00 \ubaa8\uc600\ub2e4. \uc0ac\ub78c\ub9c8\ub2e4 \uc0ac\ub294 \uc790\ub9ac\uc640 \ub3c4\uc2dc\uc5d0\uc11c \ub9e1\uc740 \uc5ed\ud560\uc774 \uac19\uc9c0\ub294 \uc54a\uc558\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \uc911\uc2ec \uc2e0\uc804\uc778 \ud15c\ud50c\ub85c \ub9c8\uc694\ub974 \ub4f1\uc744 \ubcf4\uc5ec \uc8fc\ub294 \ud604\ub300 \ubaa8\ud615\uc758 \uc0ac\uc9c4\uc774\ub2e4. \uc2e4\uc81c \uace0\ub300 \uac74\ubb3c\uc744 \uadf8\ub300\ub85c \ucd2c\uc601\ud55c \uc0ac\uc9c4\uc740 \uc544\ub2c8\ub2e4. \uc704\ucabd\uc5d0 \ub098\ub780\ud788 \uc120 \ub450 \uc2e0\uc804\uacfc \ub113\uc740 \uacc4\ub2e8\uc744 \ubcf4\uba74, \ub3c4\uc2dc \ud55c\ubcf5\ud310\uc758 \uc81c\uc758 \uacf5\uac04\uc774 \uc5bc\ub9c8\ub098 \ub450\ub4dc\ub7ec\uc9c4 \ud615\ud0dc\ub85c \uad6c\uc131\ub418\uc5c8\ub294\uc9c0 \uc9d0\uc791\ud560 \uc218 \uc788\ub2e4. \uc218\ub3c4\ub294 \uc8fc\ubcc0\uc758 \uacbd\uc791\uc9c0\ubfd0 \uc544\ub2c8\ub77c \ub113\uc740 \uc9c0\ubc30 \uc9c0\uc5ed\uc5d0\uc11c \ub4e4\uc5b4\uc624\ub294 \uacf5\ub0a9\uc5d0\ub3c4 \uc758\uc874\ud588\ub2e4. \uc9c0\uc5ed\uc5d0 \ub530\ub77c \uc2dd\ub7c9\uacfc \uc9c1\ubb3c, \ub3c4\uad6c\uc640 \uc0ac\uce58\ud488 \ub4f1 \uc694\uad6c\ubc1b\ub294 \ubb3c\ud488\uc774 \ub2ec\ub790\ub2e4. \uac00\uae4c\uc6b4 \uacf3\uc5d0\uc11c \uc77c\uc0c1\uc801\uc778 \uba39\uc744\uac70\ub9ac\ub97c, \ub354 \uba3c \uacf3\uc5d0\uc11c \ud2b9\ubcc4\ud55c \ubb3c\uac74\uc744 \ub4e4\uc5ec\uc624\ub294 \uc5f0\uacb0\ub3c4 \ub098\ud0c0\ub0ac\ub2e4. \ubb3c\uac74\uc774 \ub3c4\ucc29\ud588\ub2e4\ub294 \uacb0\uacfc\ub9cc \ubcf4\uba74 \uac70\ub300\ud55c \uc2dc\uc7a5\uc758 \ud48d\uc694\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc, \uacf5\ub0a9\uc740 \uc790\uc720\ub85c\uc6b4 \uac70\ub798\uc640 \uac19\uc9c0 \uc54a\ub2e4. \uc9c0\ubc30\uc640 \uc758\ubb34\uc758 \uad00\uacc4\uac00 \uc788\uc5c8\ub2e4. \uc218\ub3c4\uc758 \ubc88\uc601\uc744 \uc774\ud574\ud558\ub824\uba74 \ubb34\uc5c7\uc774 \uc5bc\ub9c8\ub098 \ubaa8\uc600\ub294\uc9c0\ubfd0 \uc544\ub2c8\ub77c \ub204\uac00 \uadf8\uac83\uc744 \ub9cc\ub4e4\uc5b4 \ubcf4\ub0b4\uc57c \ud588\ub294\uc9c0\ub3c4 \ud568\uaed8 \ubb3c\uc5b4\uc57c \ud55c\ub2e4. \uc544\uc2a4\ud14c\uce74 \uad6d\uac00\uc758 \uc885\uad50 \uc758\ub840\uc5d0\ub294 \uc778\uc2e0\uacf5\ud76c\uac00 \ud3ec\ud568\ub418\uc5b4 \uc788\uc5c8\ub2e4. \uc774 \uc0ac\uc2e4\uc744 \uac10\ucd94\uc9c0 \uc54a\ub354\ub77c\ub3c4 \uc790\uadf9\uc801\uc778 \uc7a5\uba74\ub9cc\uc73c\ub85c \ub3c4\uc2dc\ub97c \uc124\uba85\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub18d\uc0ac\uc640 \uc218\uacf5\uc5c5, \uc2dc\uc7a5 \uac70\ub798\uc640 \uac00\uc815\uc758 \ub178\ub3d9\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \uc774 \uc0ac\ud68c\uac00 \uc5b4\ub5bb\uac8c \uc720\uc9c0\ub418\uc5c8\ub294\uc9c0 \uc54c \uc218 \uc788\ub2e4. \uc8fc\ubbfc\ub4e4\uc740 \uac19\uc740 \ub192\uc774\uc758 \uacc4\uce35\uc5d0 \uc11c \uc788\uc9c0 \uc54a\uc558\ub2e4. \uadc0\uc871\uacfc \uc804\ubb38 \uc7a5\uc778, \uc0c1\uc778\uacfc \ub18d\ubbfc, \ub178\uc608\uac00 \ub41c \uc0ac\ub78c\ub4e4\uc774 \ub2e4\ub978 \uc870\uac74\uc5d0\uc11c \uc0b4\uc544\uac14\ub2e4. \ud2b9\ud788 \uc9d1 \uc548\uc5d0\uc11c \uc74c\uc2dd\uc744 \uc900\ube44\ud558\uace0 \uc9c1\ubb3c\uc744 \ub9cc\ub4dc\ub294 \uc77c\ub3c4 \ub9e4\uc77c \ub3c4\uc2dc\ub97c \uc9c0\ud0f1\ud588\ub2e4. \ub208\uc5d0 \ud06c\uac8c \ubcf4\uc774\ub294 \uac74\ucd95\uacfc \uc624\ub798 \ub0a8\uae30 \uc5b4\ub824\uc6b4 \uc77c\uc0c1\uc758 \ub178\ub3d9\uc740 \ubaa8\ub450 \ub3c4\uc2dc\uc758 \uc5ed\uc0ac\ub2e4. \uc624\ub298\ub0a0\uc758 \uc124\uba85\uc5d0\ub294 \uc6d0\uc8fc\ubbfc \uadf8\ub9bc \uae30\ub85d\uacfc \uace0\uace0\ud559 \uc790\ub8cc, \uc2a4\ud398\uc778\uc778\ub4e4\uc774 \ub0a8\uae34 \uae30\ub85d\uc774 \ud568\uaed8 \uc0ac\uc6a9\ub41c\ub2e4. \uc815\ubcf5 \uacfc\uc815\uc5d0\uc11c \ub9ce\uc740 \ud1a0\ucc29 \uae30\ub85d\uc774 \ud30c\uad34\ub418\uc5c8\uace0 \uc720\ub7fd\uc778\uc758 \uc124\uba85\uc5d0\ub294 \uc790\uc2e0\uc758 \uc885\uad50\uc640 \uac00\uce58\uad00\uc774 \ub4e4\uc5b4\uac14\ub2e4. \ub530\ub77c\uc11c \ub0a8\uc544 \uc788\ub294 \uae00\uc744 \ud22c\uba85\ud55c \ucc3d\ucc98\ub7fc \uc77d\uc744 \uc218\ub294 \uc5c6\ub2e4. \ud14c\ub178\uce58\ud2f0\ud2c0\ub780\uc744 \ucc98\uc74c \ub5a0\uc62c\ub9b4 \ub54c \ubb3c \uc704\uc5d0 \uc19f\uc740 \uc2e0\uc804\uc758 \ubaa8\uc2b5\uc740 \uc88b\uc740 \uc785\uad6c\uac00 \ub41c\ub2e4. \uac70\uae30\uc11c \uc81c\ubc29\uae38\uc744 \ub530\ub77c\uac00\uace0 \ubc2d\uacfc \uc9d1, \ub3c4\uc2dc\ub85c \ub4e4\uc5b4\uc624\ub294 \uc9d0\uc744 \uc0dd\uac01\ud574 \ubcf4\uc790. \uac70\ub300\ud55c \uc218\ub3c4\uac00 \uc720\uc9c0\ub41c \uae4c\ub2ed\uc740 \uc778\uc0c1\uc801\uc778 \uaf2d\ub300\uae30 \ud558\ub098\ubcf4\ub2e4, \uadf8 \uc544\ub798 \uc218\ub9ce\uc740 \uc0dd\ud65c\uc774 \uc11c\ub85c \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\uae30 \ub54c\ubb38\uc774\ub2e4."}, {"id": "timbuktu-trade-and-learning", "title": "\ud300\ubd81\ud22c \u2014 \uc0ac\ub9c9\uc758 \uae38 \ub05d\uc5d0\uc11c \ucc45\uc744 \ud3bc\uce58\ub2e4", "summary": "\uad50\uc5ed\ub85c\uc640 \uc774\uc2ac\ub78c \ud559\ubb38\uc774 \ub9cc\ub09c \ud300\ubd81\ud22c\ub97c \ubaa8\uc2a4\ud06c \uc0ac\uc9c4\uacfc \uc5ed\uc0ac \uae30\ub85d\uc73c\ub85c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "cities", "category_title": "Cities", "subcategory": "Africa", "url": "stories/timbuktu-trade-and-learning/index.html", "image": "media/timbuktu-trade-and-learning.jpg", "alt": "\ud300\ubd81\ud22c \uc9d5\uac8c\ub808\ubca0\ub974 \ubaa8\uc2a4\ud06c\ub97c \ub2e4\ub978 \ubc29\ud5a5\uc5d0\uc11c \ucd2c\uc601\ud55c \ub450 \uc7a5\uc758 \uc2e4\uc81c \uc0ac\uc9c4.", "text": "\ud300\ubd81\ud22c \u2014 \uc0ac\ub9c9\uc758 \uae38 \ub05d\uc5d0\uc11c \ucc45\uc744 \ud3bc\uce58\ub2e4 \uae08\uacfc \uc18c\uae08\uc774 \uc624\uac00\ub358 \ub3c4\uc2dc\uac00 \ubc30\uc6c0\uc758 \uc7a5\uc18c\uac00 \ub41c \uc774\uc720 \uad50\uc5ed\ub85c\uc640 \uc774\uc2ac\ub78c \ud559\ubb38\uc774 \ub9cc\ub09c \ud300\ubd81\ud22c\ub97c \ubaa8\uc2a4\ud06c \uc0ac\uc9c4\uacfc \uc5ed\uc0ac \uae30\ub85d\uc73c\ub85c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Africa \ub3c4\uc2dc \ud300\ubd81\ud22c\ub77c\ub294 \uc774\ub984\uc5d0\uc11c\ub294 \uc5b4\ub518\uac00 \uc544\uc8fc \uba3c \uacf3\uc758 \ub290\ub08c\uc774 \ub09c\ub2e4. \uc0ac\ub9c9 \ub108\uba38\uc758 \uc678\ub534 \ub3c4\uc2dc\ub97c \ub5a0\uc62c\ub9ac\uae30\ub3c4 \uc27d\ub2e4. \ud558\uc9c0\ub9cc \uc911\uc138 \uc11c\uc544\ud504\ub9ac\uce74\uc758 \uc9c0\ub3c4\uc5d0 \ubb34\uc5ed\uae38\uc744 \uadf8\ub824 \ub123\uc73c\uba74 \uc778\uc0c1\uc774 \ubc14\ub010\ub2e4. \uba40\ub9ac \ub5a8\uc5b4\uc9c4 \ub05d\uc790\ub9ac\uac00 \uc544\ub2c8\ub77c \uc5ec\ub7ec \uc774\ub3d9\uc774 \ub9cc\ub098\ub294 \uacf3\uc774 \ub098\ud0c0\ub09c\ub2e4. \uae08\uacfc \uc18c\uae08, \uc9c1\ubb3c\ub9cc \uadf8 \uae38\uc744 \ub530\ub77c \uc6c0\uc9c1\uc600\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc0ac\ub78c\uacfc \ucc45, \uacf5\ubd80\ud558\ub294 \ubc29\uc2dd\ub3c4 \ud568\uaed8 \uac74\ub108\uac14\ub2e4. \ud300\ubd81\ud22c\uac00 \ud559\ubb38\uc758 \ub3c4\uc2dc\ub85c \uae30\uc5b5\ub418\ub294 \uae4c\ub2ed\uc744 \uc774\ud574\ud558\ub824\uba74 \uba3c\uc800 \ub3c4\uc11c\uad00\uc758 \ubb38\ubcf4\ub2e4 \ub3c4\uc2dc \ubc14\uae65\uc758 \uae38\uc744 \ubc14\ub77c\ubcfc \ud544\uc694\uac00 \uc788\ub2e4. \ud300\ubd81\ud22c\ub294 \uc624\ub298\ub0a0 \ub9d0\ub9ac\uc5d0 \uc788\uc73c\uba70, \uadf8 \uc5ed\uc0ac\ub294 \uc0ac\ud558\ub77c\uc640 \uc0ac\ud5ec, \ub2c8\uc81c\ub974\uac15 \uc77c\ub300\uc758 \uad50\uc5ed\uacfc \uc5f0\uacb0\ub418\uc5b4 \uc788\ub2e4. \uc0ac\ud5ec\uc740 \uc0ac\ub9c9 \ub0a8\ucabd\uc5d0 \uc774\uc5b4\uc9c0\ub294 \uc9c0\uc5ed\uc774\ub2e4. \ubd81\ucabd\uc744 \uac00\ub85c\uc9c0\ub974\ub294 \uae38\uacfc \uc11c\uc544\ud504\ub9ac\uce74 \uc548\ucabd\uc758 \uc0dd\uc0b0\uc9c0\uac00 \ub9cc\ub098\ub294 \ub3c4\uc2dc\ub4e4\uc740 \uba3c \uacf3\uc758 \ubb3c\uac74\uc744 \uc11c\ub85c \uc774\uc5b4 \uc8fc\uc5c8\ub2e4. \uc18c\uae08\uc740 \ubd81\ucabd\uc5d0\uc11c \uc6b4\ubc18\ub418\uc5c8\uace0 \uae08\uc744 \ube44\ub86f\ud55c \uc5ec\ub7ec \ubb3c\ud488\uc740 \ub2e4\ub978 \uacbd\ub85c\ub97c \ud1b5\ud574 \uac70\ub798\ub418\uc5c8\ub2e4. \ubb3c\uac74\uc758 \ucd9c\ubc1c\uc9c0\uc640 \ud544\uc694\ud55c \uc7a5\uc18c\uac00 \ub2e4\ub974\uba74 \uadf8 \uc0ac\uc774\uc758 \uac70\ub9ac\ub97c \uac74\ub108\ub294 \uc0ac\ub78c\uc774 \uc911\uc694\ud574\uc9c4\ub2e4. \ud300\ubd81\ud22c\ub97c \uc0ac\ub9c9\uc5d0 \uace0\ub9bd\ub41c \uc810\uc73c\ub85c \uadf8\ub9ac\uba74 \ubc14\ub85c \uc774 \uc5f0\uacb0\uc744 \uc9c0\uc6cc \ubc84\ub9ac\uac8c \ub41c\ub2e4. 14\uc138\uae30 \ub9d0\ub9ac\uc758 \ud1b5\uce58\uc790 \ub9cc\uc0ac \ubb34\uc0ac\ub294 \uba54\uce74\ub85c \uc21c\ub840\ub97c \ub5a0\ub09c \uc778\ubb3c\ub85c \uc720\uba85\ud558\ub2e4. \ub9ce\uc740 \uae08\uc744 \ub098\ub204\uc5b4 \uc8fc\uc5c8\ub2e4\ub294 \uc774\uc57c\uae30\uac00 \uc790\uc8fc \ub530\ub77c\ubd99\uc9c0\ub9cc, \ub3c4\uc2dc\uc758 \ubb38\ud654\ub77c\ub294 \uad00\uc810\uc5d0\uc11c\ub294 \ub3cc\uc544\uc624\ub294 \uae38\ub3c4 \uc911\uc694\ud558\ub2e4. \uadf8\ub294 \ud559\uc790\uc640 \uac74\ucd95\uac00, \ucc45\uc744 \ub9d0\ub9ac\ub85c \ub4e4\uc5ec\uc624\ub294 \ub370 \uae30\uc5ec\ud588\ub2e4. \uad50\uc7ac\ub294 \uc774\ub7ec\ud55c \ud750\ub984 \uc18d\uc5d0\uc11c \ud300\ubd81\ud22c\uc758 \uc774\uc2ac\ub78c \ud559\ubb38\uacfc \uad50\uc721\uc774 \uc131\uc7a5\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc885\uad50\uc801 \uad8c\uc704, \ud1b5\uce58\uc790\uc758 \ud6c4\uc6d0, \uad50\uc5ed\uc73c\ub85c \uc5bb\ub294 \ubd80\uac00 \uc11c\ub85c \ub5a8\uc5b4\uc838 \uc788\uc9c0 \uc54a\uc558\ub358 \uac83\uc774\ub2e4. \uae08\uc774 \ub9ce\uc558\ub2e4\ub294 \uc77c\ud654\ub9cc\uc73c\ub85c \uae30\uc5b5\ud558\uba74, \uadf8 \uc790\uc6d0\uc774 \uc5b4\ub5a4 \ud65c\ub3d9\uc744 \uac00\ub2a5\ud558\uac8c \ud588\ub294\uc9c0\ub294 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ud568\uaed8 \uc2e4\uc740 \ub450 \uc0ac\uc9c4\uc740 \ud300\ubd81\ud22c\uc758 \uc9d5\uac8c\ub808\ubca0\ub974 \ubaa8\uc2a4\ud06c\ub97c \ubcf4\uc5ec \uc900\ub2e4. \uad50\uc7ac\ub294 \uc774 \ubaa8\uc2a4\ud06c\uc758 \uac74\ub9bd\uc744 1327\ub144\uc73c\ub85c \uc18c\uac1c\ud55c\ub2e4. \ud300\ubd81\ud22c\uc5d0\uc11c\ub294 \uafb8\ub780\uc744 \uacf5\ubd80\ud558\ub294 \uad50\uc721\uacfc \ud568\uaed8 \uc774\uc2ac\ub78c \ubc95, \ucca0\ud559\uacfc \uacfc\ud559\uc5d0 \uad00\ud55c \ubc30\uc6c0\ub3c4 \uc774\ub8e8\uc5b4\uc84c\ub2e4. \uc5ec\uae30\uc11c \uc624\ub298\ub0a0\uc758 \uc885\ud569\ub300\ud559 \ucea0\ud37c\uc2a4\ub97c \uadf8\ub300\ub85c \uc0c1\uc0c1\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc61b \ub3c4\uc2dc\uc758 \ubc30\uc6c0\uc740 \uc885\uad50 \uacf5\uac04, \uad50\uc0ac\uc640 \uc81c\uc790\uc758 \uad00\uacc4, \ud6c4\uc6d0\uc758 \ubc29\uc2dd \uc548\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc84c\ub2e4. \ud559\ubb38\uc774 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc874\uc911\ud558\uba74\uc11c\ub3c4, \ud604\ub300 \ub300\ud559\uc758 \uc2dc\uac04\ud45c\uc640 \ud559\uacfc \uc870\uc9c1\uc744 \uacfc\uac70\uc5d0 \uadf8\ub300\ub85c \uc62e\uaca8 \ub193\uc9c0 \uc54a\ub294 \ud3b8\uc774 \ub3c4\uc2dc\ub97c \ub354 \uc815\ud655\ud558\uac8c \uc774\ud574\ud558\uac8c \ud55c\ub2e4. \ucc45\uc740 \ud45c\uc9c0 \uc548\uc758 \uae00\ub9cc\uc73c\ub85c \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294\ub2e4. \ub9cc\ub4e0 \uc0ac\ub78c\uc774 \uc788\uace0 \uc6b4\ubc18\ud55c \uc0ac\ub78c\uc774 \uc788\uc73c\uba70, \uadf8 \uae00\uc744 \uc77d\uac70\ub098 \uac00\ub974\uce60 \uc0ac\ub78c\uc774 \ud544\uc694\ud558\ub2e4. \uba3c \uacf3\uc5d0\uc11c \ucc45\uc744 \ub4e4\uc5ec\uc628\ub2e4\ub294 \uc124\uba85\uc5d0\ub294 \uc774\ub7f0 \uc5ec\ub7ec \ub2e8\uacc4\uac00 \ud568\uaed8 \ub4e4\uc5b4 \uc788\ub2e4. \uad50\uc5ed\ub85c\uc640 \uc9c0\uc2dd\uc758 \uc774\ub3d9\uc744 \uac19\uc774 \ubcf4\uc544\uc57c \ud558\ub294 \uc774\uc720\ub2e4. \uc774\ub807\uac8c \uc0dd\uac01\ud558\uba74 \uc0c1\uc778\uacfc \ud559\uc790\ub294 \uc11c\ub85c \ubb34\uad00\ud55c \uc778\ubb3c\ub9cc\uc740 \uc544\ub2c8\ub2e4. \ub3c4\uc2dc\ub97c \ub4dc\ub098\ub4dc\ub294 \uc0ac\ub78c\ub4e4\uc758 \uc5f0\uacb0\uacfc \uc548\uc815\uc801\uc778 \uc0dd\ud65c\uc758 \uae30\ubc18\uc774 \uad50\uc721\uc744 \ub4b7\ubc1b\uce68\ud560 \uc218 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubaa8\ub4e0 \uc0c1\uc778\uc774 \ud559\uc790\uc600\uac70\ub098 \uac70\ub798\uac00 \uace7\ubc14\ub85c \ud559\ubb38\uc744 \ub0b3\uc558\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc11c\ub85c \ub2e4\ub978 \ud65c\ub3d9\uc774 \uac19\uc740 \ub3c4\uc2dc \uc548\uc5d0\uc11c \ub9cc\ub0a0 \uc870\uac74\uc744 \uc0b4\ud3b4\ubcf4\ub294 \uac83\uc774\ub2e4. \ud6c4\ub300\uc5d0 \ud300\ubd81\ud22c\ub97c \ubb18\uc0ac\ud55c \ub808\uc624 \uc544\ud504\ub9ac\uce74\ub204\uc2a4\uc758 \uae30\ub85d\uc5d0\ub294 \uc0c1\uc810\uacfc \uc9c1\ubb3c \uac70\ub798, \ubb3c\uacfc \uc2dd\ub7c9, \uad81\uc815\uc758 \ubaa8\uc2b5\uc774 \ub098\uc628\ub2e4. \ubc30\uc6c0\uc758 \uba85\uc131\ub9cc \uc788\ub294 \ub3c4\uc2dc\uac00 \uc544\ub2c8\ub77c \uba39\uace0 \uc77c\ud558\uace0 \uc0ac\uace0\ud30c\ub294 \uc0dd\ud65c\uc758 \uacf5\uac04\uc774\uc5c8\ub2e4\ub294 \uc810\uc744 \uc54c\ub824 \uc900\ub2e4. \ub2e4\ub9cc \uc5ec\ud589\uc790\uc758 \uc11c\uc220\uc744 \ub3c4\uc2dc \uc8fc\ubbfc \uc804\uccb4\uc758 \ubaa9\uc18c\ub9ac\ub85c \uc77d\uc744 \uc218\ub294 \uc5c6\ub2e4. \uadf8 \uae30\ub85d\uc5d0\ub294 \ub178\uc608\uac00 \ub41c \uc0ac\ub78c\ub4e4\uc758 \uc874\uc7ac\ub3c4 \ub4f1\uc7a5\ud55c\ub2e4. \ubc88\uc601\uacfc \ud559\ubb38\uc758 \uc774\uc57c\uae30\uac00 \ub2f9\uc2dc\uc758 \ubd88\ud3c9\ub4f1\uc744 \uc5c6\uc560 \uc8fc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc544\ub984\ub2e4\uc6b4 \ubb38\ud654\uc758 \uc131\uacfc\uc640 \uadf8 \ub3c4\uc2dc\ub97c \ub5a0\ubc1b\uce5c \uc0ac\ud68c\uc801 \uad00\uacc4\ub97c \ud568\uaed8 \ubcf4\uc544\uc57c, \ud300\ubd81\ud22c\ub97c \ub9c9\uc5f0\ud55c \ud669\uae08\uc2dc\ub300\uc758 \ud48d\uacbd\uc73c\ub85c\ub9cc \uc18c\ube44\ud558\uc9c0 \uc54a\uac8c \ub41c\ub2e4. \ud300\ubd81\ud22c\ub294 \ub9d0\ub9ac\uc640 \uc1a1\uac00\uc774\uc758 \uad8c\ub825 \ubcc0\ud654 \uc18d\uc5d0 \uc788\uc5c8\ub2e4. \uc1a1\uac00\uc774\uc758 \uc21c\ub2c8 \uc54c\ub9ac\uac00 \uc138\ub825\uc744 \ub113\ud788\ub358 \uc2dc\uae30\ub97c \ub450\uace0, \uc544\ub78d\uc5b4 \uc5ed\uc0ac \uae30\ub85d\uc740 \ud559\uc790\ub4e4\uc744 \uc5b5\uc555\ud55c \ud1b5\uce58\uc790\ub85c \ube44\ud310\ud55c\ub2e4. \ubc18\uba74 \uc1a1\uac00\uc774\uc758 \uad6c\uc804 \uc804\ud1b5\uc5d0\uc11c\ub294 \uac15\ub825\ud55c \uc815\ubcf5\uc790\uc774\uc790 \uac74\uad6d\uc758 \uc601\uc6c5\uc73c\ub85c \uae30\uc5b5\ub41c\ub2e4. \uac19\uc740 \uc778\ubb3c\uc758 \ud3c9\uac00\uac00 \ub2e4\ub978 \uc774\uc720\ub97c \uc0dd\uac01\ud558\uba74 \uc5ed\uc0ac\uac00 \uc870\uae08 \uc785\uccb4\uc801\uc73c\ub85c \ubcf4\uc778\ub2e4. \uc804\uc7c1\uc5d0\uc11c \uc774\uae34 \ud1b5\uce58\uc790\uc758 \uc131\ucde8\uc640 \ud559\uc790\ub4e4\uc774 \uacaa\uc740 \ubd88\uc548\uc740 \uac19\uc740 \uc810\uc218\ud45c\ub85c \uc815\ub9ac\ub418\uc9c0 \uc54a\ub294\ub2e4. \uad50\uc7ac\ub294 \uc774 \uacfc\uc815\uc5d0\uc11c \ud559\uc790\ub4e4\uc774 \ub2e4\ub978 \ub3c4\uc2dc\ub85c \ub5a0\ub098\uae30\ub3c4 \ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc9c0\uc2dd\uc744 \ub098\ub204\ub294 \ud658\uacbd\uc740 \uc815\uce58\uc758 \ubcc0\ud654\uc640 \ubb34\uad00\ud558\uc9c0 \uc54a\uc558\ub2e4. \uc0ac\uc9c4\uc758 \ud759\ube5b \ubcbd\uacfc \ub3cc\ucd9c\ub41c \ubd80\uc7ac, \ubb38 \uc55e\uc758 \uc0ac\ub78c\uc744 \ucc28\ub840\ub85c \ubcf4\uc790. \ub204\uad70\uac00\uc5d0\uac8c\ub294 \uc774\ub984\ub09c \uc720\uc801\uc774\uc9c0\ub9cc \ub204\uad70\uac00\uc5d0\uac8c\ub294 \uc0dd\ud65c \uc18d \uc885\uad50 \uacf5\uac04\uc774\ub2e4. \uc0ac\uc9c4\uc740 \uc911\uc138\uc758 \uc218\uc5c5 \uc7a5\uba74\uc774\ub098 \ucc45\uc758 \ub0b4\ubd80\ub97c \ubcf4\uc5ec \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc9c0\uae08 \ubcf4\uc774\ub294 \uac74\ubb3c\uacfc \uc5ed\uc0ac \uc124\uba85\uc744 \uad6c\ubcc4\ud558\uba70 \uc77d\uc73c\uba74 \ub41c\ub2e4. \ud300\ubd81\ud22c\uc758 \uc7ac\ubbf8\ub294 \uba3c \uc0ac\ub9c9\uc5d0\ub3c4 \ub73b\ubc16\uc5d0 \ucc45\uc774 \uc788\uc5c8\ub2e4\ub294 \ub180\ub77c\uc6c0\uc5d0\uc11c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \ucc98\uc74c\ubd80\ud130 \uadf8\uacf3\uc744 \uba40\uace0 \ube44\uc5b4 \uc788\ub294 \uc7a5\uc18c\ub85c \ubcf4\uc558\ub358 \uc6b0\ub9ac\uc758 \uc2dc\uc120\ub3c4 \ub3cc\uc544\ubcf4\uac8c \ud55c\ub2e4. \ubb3c\uac74\uacfc \uc0ac\ub78c, \uc2e0\uc559\uacfc \ubc30\uc6c0\uc774 \uc624\uac00\ub358 \uae38 \uc704\uc5d0\uc11c \uc774 \ub3c4\uc2dc\ub294 \uc624\ub7ab\ub3d9\uc548 \ub2e4\ub978 \uc138\uacc4\uc640 \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub2e4."}, {"id": "alice-language-and-rules", "title": "\uc774\uc0c1\ud55c \ub098\ub77c\uc758 \uc568\ub9ac\uc2a4 \u2014 \ub9d0\uc774 \ud1b5\ud558\uc9c0 \uc54a\ub294 \uc138\uacc4\uc5d0\uc11c \ub098\ub97c \ucc3e\uae30", "summary": "\uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc744 \ub530\ub77c \ub9d0\uacfc \uaddc\uce59\uc774 \ud754\ub4e4\ub9ac\ub294 \ubaa8\ud5d8\uc758 \uc7ac\ubbf8\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Literature", "url": "stories/alice-language-and-rules/index.html", "image": "media/alice-language-and-rules.png", "alt": "\uc568\ub9ac\uc2a4\uac00 \uc232\uc18d \uac08\ub9bc\uae38\uc5d0\uc11c \ub098\ubb34 \uc704\uc758 \uccb4\uc154 \uace0\uc591\uc774\ub97c \ubc14\ub77c\ubcf4\ub294 \uc0c1\uc0c1 \uc0bd\ud654.", "text": "\uc774\uc0c1\ud55c \ub098\ub77c\uc758 \uc568\ub9ac\uc2a4 \u2014 \ub9d0\uc774 \ud1b5\ud558\uc9c0 \uc54a\ub294 \uc138\uacc4\uc5d0\uc11c \ub098\ub97c \ucc3e\uae30 \ud1a0\ub07c\uad74\uacfc \ub2e4\uacfc\ud68c, \uc774\uc0c1\ud55c \uc7ac\ud310\uc744 \uc9c0\ub098\uac00\ub294 \uc18c\ub140 \uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc744 \ub530\ub77c \ub9d0\uacfc \uaddc\uce59\uc774 \ud754\ub4e4\ub9ac\ub294 \ubaa8\ud5d8\uc758 \uc7ac\ubbf8\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Literature \ubb38\ud654 \uae09\ud558\uac8c \ub2ec\ub9ac\ub294 \ud1a0\ub07c\uac00 \ud68c\uc911\uc2dc\uacc4\ub97c \uaebc\ub0b8\ub2e4. \uc2e0\uae30\ud574\uc11c \ub530\ub77c\uac04 \uc18c\ub140\ub294 \ud1a0\ub07c\uad74 \uc544\ub798\ub85c \ub5a8\uc5b4\uc9c0\uace0, \ubab8\uc758 \ud06c\uae30\uc640 \ub300\ud654\uc758 \uaddc\uce59\uc774 \uc790\uafb8 \ub2ec\ub77c\uc9c0\ub294 \uc138\uacc4\uc5d0 \ub4e4\uc5b4\uac04\ub2e4. \ub8e8\uc774\uc2a4 \uce90\ub7f4\uc758 \u300e\uc774\uc0c1\ud55c \ub098\ub77c\uc758 \uc568\ub9ac\uc2a4\u300f\ub2e4. \uc775\uc219\ud55c \uc81c\ubaa9\uc774\uc9c0\ub9cc \uc904\uac70\ub9ac\ub97c \ucc28\ub840\ub85c \uc77d\uc5b4 \ubcf4\uba74 \ub2e8\uc21c\ud788 \uae30\ubb18\ud55c \uc0dd\ubb3c\uc744 \ub9cc\ub098\ub294 \uc774\uc57c\uae30\ubcf4\ub2e4 \ud6e8\uc52c \uc7a5\ub09c\uc2a4\ub7fd\ub2e4. \uc568\ub9ac\uc2a4\ub294 \ubc30\uc6b4 \ub9d0\uacfc \uc608\uc808\uc744 \uac00\uc9c0\uace0 \ub0af\uc120 \uc138\uacc4\ub97c \uc774\ud574\ud558\ub824 \ud55c\ub2e4. \uadf8\ub7ec\ub098 \uadf8\uacf3\uc758 \uc778\ubb3c\ub4e4\uc740 \uac19\uc740 \ub2e8\uc5b4\ub97c \uc4f0\uba74\uc11c\ub3c4 \uac19\uc740 \ub73b\uc744 \ub098\ub204\uc9c0 \uc54a\ub294\ub2e4. \uc544\ub798\uc5d0\ub294 \uc8fc\uc694 \uc7a5\uba74\uacfc \uacb0\ub9d0\uc774 \ud3ec\ud568\ub418\uc5b4 \uc788\ub2e4. \ud1a0\ub07c\uad74\uc744 \ub0b4\ub824\uac04 \uc568\ub9ac\uc2a4\ub294 \uc791\uc740 \ubb38 \ub108\uba38\uc758 \uc544\ub984\ub2e4\uc6b4 \uc815\uc6d0\uc5d0 \uac00\uace0 \uc2f6\uc5b4 \ud55c\ub2e4. \ud558\uc9c0\ub9cc \ubb38\uacfc \ubab8\uc758 \ud06c\uae30\uac00 \ub9de\uc9c0 \uc54a\ub294\ub2e4. \ub9c8\uc2dc\uace0 \uba39\uc73c\uba70 \uc791\uc544\uc9c0\uac70\ub098 \ucee4\uc9c0\ub294 \ub3d9\uc548 \uc5f4\uc1e0\ub97c \ub193\uce58\uace0 \uc790\uae30 \ub208\ubb3c\uc5d0 \ud729\uc4f8\ub9ac\uae30\ub3c4 \ud55c\ub2e4. \uc6d0\ud558\ub294 \uacf3\uc5d0 \ub4e4\uc5b4\uac00\ub294 \uc77c\uc774 \uc0dd\uac01\ucc98\ub7fc \ub2e8\uc21c\ud558\uc9c0 \uc54a\ub2e4. \uc774 \ubcc0\ud654\ub294 \uc7ac\ubbf8\uc788\ub294 \ub9c8\ubc95\uc774\uba74\uc11c \uc790\uc2e0\uc744 \uc54c\uc544\ubcf4\ub294 \uac10\uac01\uc744 \ud754\ub4e0\ub2e4. \ubab8\uc774 \uc790\uafb8 \ubc14\ub00c\ub2c8 \ud3c9\uc18c\uc5d0 \ub2f9\uc5f0\ud588\ub358 \uc77c\uc744 \ud560 \uc218 \uc5c6\uace0, \uc678\uc6e0\ub358 \ub9d0\ub3c4 \uc774\uc0c1\ud558\uac8c \ub098\uc628\ub2e4. \ub3c5\uc790\ub294 \uc568\ub9ac\uc2a4\uc640 \ud568\uaed8 \uc775\uc219\ud55c \uae30\uc900\uc744 \uc7a0\uc2dc \uc783\ub294\ub2e4. \ubb34\uc5c7\uc744 \ud558\ub824\ub294\uc9c0\ub9cc\ud07c \uc9c0\uae08 \uc5b4\ub5a4 \uc0c1\ud0dc\uc778\uc9c0\ub3c4 \uc911\uc694\ud574\uc9c4\ub2e4. \uc560\ubc8c\ub808\ub97c \ub9cc\ub0ac\uc744 \ub54c \uc568\ub9ac\uc2a4\ub294 \uc790\uc2e0\uc774 \ub204\uad6c\uc778\uc9c0 \uc124\uba85\ud558\uae30 \uc5b4\ub835\ub2e4. \uc624\ub298\ub9cc \ud574\ub3c4 \ubab8\uc774 \uc5ec\ub7ec \ubc88 \ub2ec\ub77c\uc84c\uae30 \ub54c\ubb38\uc774\ub2e4. \uc0c1\ub300\uc758 \uc9c8\ubb38\uc740 \uac04\ub2e8\ud558\uc9c0\ub9cc \ub300\ub2f5\ud560 \uc870\uac74\uc740 \uac04\ub2e8\ud558\uc9c0 \uc54a\ub2e4. \uc5b4\uc81c \uc54c\uace0 \uc788\ub358 \uc790\uae30 \ubaa8\uc2b5\uc774 \uc624\ub298\uc758 \uc0c1\ud669\uc744 \ucda9\ubd84\ud788 \uc124\uba85\ud558\uc9c0 \ubabb\ud55c\ub2e4. \uc774\ub97c \ud55c \uac00\uc9c0 \ucca0\ud559 \uc774\ub860\uc758 \uc815\ub2f5\uc73c\ub85c \ud574\uc11d\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5b4\ub9b0\uc544\uc774\uc5d0\uac8c\ub3c4 \uc5b4\ub978\uc5d0\uac8c\ub3c4 \ubcc0\ud654\ud558\ub294 \uc790\uc2e0\uc744 \ub9d0\ud558\uae30 \uc5b4\ub824\uc6b4 \uc21c\uac04\uc740 \uc788\ub2e4. \uc791\ud488\uc740 \uadf8 \ubb38\uc81c\ub97c \ubb34\uac70\uc6b4 \uac15\uc758 \ub300\uc2e0 \ud06c\uae30\uc640 \ub9d0\ud22c, \uc5c9\ub6b1\ud55c \ubb38\ub2f5\uc73c\ub85c \ubcf4\uc5ec \uc900\ub2e4. \uc6c3\uc74c \uc18d\uc5d0\uc11c \uc790\uae30\uc18c\uac1c\uac00 \uc7a0\uae50 \ub0af\uc124\uc5b4\uc9c4\ub2e4. \uac08\ub9bc\uae38\uc5d0\uc11c \ub9cc\ub09c \uccb4\uc154 \uace0\uc591\uc774\uc640\uc758 \ub300\ud654\uc5d0\uc11c\ub294 \uc5b4\ub514\ub85c \uac00\uace0 \uc2f6\uc740\uc9c0\uac00 \uc911\uc694\ud574\uc9c4\ub2e4. \uae38\uc744 \ubb3b\ub294 \uc0ac\ub78c\uc740 \uc788\uc9c0\ub9cc \ubaa9\uc801\uc9c0\uac00 \ubd84\uba85\ud558\uc9c0 \uc54a\uc73c\uba74 \uc5b4\ub290 \uae38\uc774 \ub9de\ub294\uc9c0\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \ud754\ud788 \uc774 \uc7a5\uba74\ub9cc \ub5bc\uc5b4 \uaca9\uc5b8\ucc98\ub7fc \uc77d\uc9c0\ub9cc, \uc791\ud488 \uc18d\uc5d0\uc11c\ub294 \uace0\uc591\uc774\uc758 \uc5c9\ub6b1\ud568\uacfc \uc568\ub9ac\uc2a4\uc758 \ub2f9\ud669\uc774 \ud568\uaed8 \uc788\ub2e4. \uc18c\uc124\uc758 \ud55c \ubb38\uc7a5\uc744 \uc778\uc0dd\uc758 \ubaa8\ub4e0 \uc120\ud0dd\uc5d0 \uc801\uc6a9\ud560 \uba85\ub839\uc73c\ub85c \ub9cc\ub4e4 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \ubb34\uc5c7\uc744 \uc6d0\ud558\ub290\ub0d0\ub294 \uc9c8\ubb38 \uc5c6\uc774 \ud6a8\uc728\uc801\uc778 \uae38\ub9cc \ucc3e\uc744 \ub54c \uc0dd\uae30\ub294 \uc774\uc0c1\ud568\uc744 \ub290\uaef4 \ubcfc \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc0bd\ud654\ub294 \uc774 \ub9cc\ub0a8\uc744 \uc0c8\ub85c \uc0c1\uc0c1\ud55c \uc7a5\uba74\uc774\ub2e4. \uc6d0\uc791\uc758 \uc61b \ub3c4\ud310\uc774\ub098 \uc601\ud654\uc758 \uace0\uc591\uc774\ub97c \ubcf5\uc81c\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \ubaa8\uc790 \uc7a5\uc218\uc640 \uc0bc\uc6d4 \ud1a0\ub07c, \uaca8\uc6b8\uc7a0\uc950\uac00 \uc788\ub294 \ub2e4\uacfc\ud68c\ub294 \uc190\ub2d8\uc744 \ubc18\uae30\ub294 \ud3b8\uc548\ud55c \uc790\ub9ac\uac00 \uc544\ub2c8\ub2e4. \uc790\ub9ac\ub97c \uc62e\uae30\uace0 \ub9d0\uc7a5\ub09c\uc744 \ud558\uba70 \uc9c8\ubb38\uacfc \ub300\ub2f5\uc774 \uc5c7\uac08\ub9b0\ub2e4. \uc568\ub9ac\uc2a4\uac00 \uc608\uc758\ub97c \uc9c0\ud0a4\uba70 \uc774\ud574\ud558\ub824 \ud560\uc218\ub85d \ub300\ud654\ub294 \ub2e4\ub978 \ubc29\ud5a5\uc73c\ub85c \ub2ec\uc544\ub09c\ub2e4. \ub2e8\uc21c\ud788 \ubaa8\ub450\uac00 \uc774\uc0c1\ud55c \ub9d0\uc744 \ud574\uc11c \uc6c3\uae34 \uac83\ub9cc\uc740 \uc544\ub2c8\ub2e4. \uc6b0\ub9ac\ub294 \uc9c8\ubb38\uc744 \ubc1b\uc73c\uba74 \ub2f5\ud560 \uac83\uc774\ub77c\ub294 \uae30\ub300, \ub9d0\uc758 \uc21c\uc11c\uc640 \ub73b\uc774 \uc5b4\ub290 \uc815\ub3c4 \uacf5\uc720\ub420 \uac83\uc774\ub77c\ub294 \ubbff\uc74c\uc744 \uac00\uc9c0\uace0 \uc788\ub2e4. \uadf8 \uc57d\uc18d\uc774 \uacc4\uc18d \uc5b4\uae0b\ub0a0 \ub54c \uc775\uc219\ud55c \ucc28 \ud55c \uc794\uc758 \uc790\ub9ac\ub3c4 \ub0af\uc120 \uc138\uacc4\uac00 \ub41c\ub2e4. \uc5ec\uc655\uc758 \uacbd\uae30\uc5d0\uc11c\ub294 \ud64d\ud559\uacfc \uace0\uc2b4\ub3c4\uce58\uac00 \ub3c4\uad6c\uac00 \ub418\uace0, \uc0ac\ub78c\ub4e4\uc758 \ud0dc\ub3c4\ub3c4 \uc548\uc815\uc801\uc774\uc9c0 \uc54a\ub2e4. \ubb3c\uac74\ucc98\ub7fc \ub2e4\ub8e8\ub824\ub294 \ub300\uc0c1\uc774 \uc0b4\uc544 \uc6c0\uc9c1\uc774\ub2c8 \uacbd\uae30\uc758 \uaddc\uce59\uc744 \uc9c0\ud0a4\uae30 \uc5b4\ub835\ub2e4. \uc5ec\uc655\uc740 \uc790\uc8fc \uc704\ud611\uc801\uc778 \uba85\ub839\uc744 \ub0b4\ub9ac\uc9c0\ub9cc \uadf8 \ubaa9\uc18c\ub9ac\uac00 \ud569\ub9ac\uc801\uc778 \uc9c8\uc11c\ub97c \ubcf4\uc7a5\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc568\ub9ac\uc2a4\ub294 \uc815\ud574\uc9c4 \uaddc\uce59\uc744 \uc798 \ub530\ub974\ub294 \uac83\ub9cc\uc73c\ub85c \ubb38\uc81c\ub97c \ud574\uacb0\ud560 \uc218 \uc5c6\ub294 \uc790\ub9ac\uc5d0 \ub193\uc778\ub2e4. \uaddc\uce59\uc744 \ub9d0\ud558\ub294 \uc0ac\ub78c\uc774 \uc790\uae30 \uae30\ubd84\uc5d0 \ub530\ub77c \uadf8\uac83\uc744 \ubc14\uafb8\uae30 \ub54c\ubb38\uc774\ub2e4. \uad8c\uc704\uac00 \ud06c\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ub9d0\uc774 \uc774\uce58\uc5d0 \ub9de\ub294\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub2e4\ub97c \uc218 \uc788\ub2e4\ub294 \uac10\uc0c1\uc774 \uac00\ub2a5\ud574\uc9c4\ub2e4. \ud6c4\ubc18\uc5d0\ub294 \ud30c\uc774\ub97c \ud6d4\uce5c \uc0ac\uac74\uc744 \ub450\uace0 \uc7ac\ud310\uc774 \uc5f4\ub9b0\ub2e4. \uc99d\uac70\uc640 \uc99d\uc5b8\uc744 \ub530\uc838\uc57c \ud560 \uc790\ub9ac\uc778\ub370 \uc5c9\ub6b1\ud55c \ub9d0\uacfc \uc21c\uc11c\uac00 \ub07c\uc5b4\ub4e4\uace0, \ud310\uacb0\uacfc \ucc98\ubc8c\uc758 \uad00\uacc4\ub9c8\uc800 \ud754\ub4e4\ub9b0\ub2e4. \uaca9\uc2dd\uc744 \uac16\ucd98 \uc7a5\uc18c\ub77c\uace0 \ud574\uc11c \ud310\ub2e8\uc774 \uc81c\ub300\ub85c \uc774\ub8e8\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc568\ub9ac\uc2a4\ub294 \uc774\uacf3\uc5d0\uc11c\ub3c4 \uacc4\uc18d \ub2f9\ud669\ud558\uae30\ub9cc \ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ubab8\uc774 \ucee4\uc9c0\ub294 \ubcc0\ud654\uc640 \ud568\uaed8 \uc0c1\ub300\uc758 \ub9d0\uc744 \uc804\ubcf4\ub2e4 \ub35c \ub450\ub824\uc6cc\ud558\uba70 \ubc18\uc751\ud55c\ub2e4. \ucc98\uc74c\uc5d0\ub294 \ub0af\uc120 \uc138\uacc4\uc5d0 \ub9de\ucd94\ub824 \uc560\uc37c\ub358 \uc18c\ub140\uac00, \uc774\uc81c \uadf8 \uc138\uacc4\uc758 \uc774\uc0c1\ud568\uc744 \uc790\uae30 \ub9d0\ub85c \uc9c0\uc801\ud560 \uc218 \uc788\uac8c \ub41c\ub2e4. \ub9c8\uc9c0\ub9c9\uc5d0 \uce74\ub4dc\ub4e4\uc774 \ub0a0\uc544\uc624\ub974\uace0 \uc568\ub9ac\uc2a4\ub294 \uc7a0\uc5d0\uc11c \uae68\uc5b4\ub09c\ub2e4. \ubaa8\ud5d8\uc740 \uafc8\uc758 \uc2dc\uac04\uc73c\ub85c \ub3cc\uc544\uc628\ub2e4. \uadf8\ub807\ub2e4\uace0 \uafc8\uc774\uc5c8\uc73c\ub2c8 \ubaa8\ub4e0 \uc7a5\uba74\uc774 \ubb34\uc758\ubbf8\ud574\uc84c\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub0af\uc120 \ub9d0\uacfc \uaddc\uce59\uc744 \ud1b5\uacfc\ud558\uba70 \ub290\uaf08\ub358 \ud63c\ub780\uacfc \uc6c3\uc74c\uc740 \ub3c5\uc790\uc5d0\uac8c \ub0a8\uc544 \uc788\ub2e4. \ub05d\uc5d0\uc11c\ub294 \uc5b8\ub2c8\uac00 \uc568\ub9ac\uc2a4\uc758 \uafc8\uacfc \uc55e\uc73c\ub85c\uc758 \uc2dc\uac04\uc744 \ub5a0\uc62c\ub9ac\ub294 \uc7a5\uba74\ub3c4 \uc774\uc5b4\uc9c4\ub2e4. \uc774\uc0c1\ud55c \uc138\uacc4\uac00 \ub2eb\ud788\uace0 \uc77c\uc0c1\uc73c\ub85c \ub3cc\uc544\uc640\ub3c4 \uc774\uc57c\uae30\ub97c \ub4e3\uace0 \uc0c1\uc0c1\ud558\ub294 \ub2a5\ub825\uc740 \uacc4\uc18d\ub41c\ub2e4. \uadf8\ub798\uc11c \uacb0\ub9d0\uc740 \ud37c\uc990\uc758 \ud574\ub2f5 \ud558\ub098\ub97c \uc8fc\uae30\ubcf4\ub2e4 \uafc8\uc744 \uc774\uc57c\uae30\ub85c \uac04\uc9c1\ud558\ub294 \uc790\ub9ac\ub97c \ub0a8\uae34\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc5b4\ub5a4 \uc778\ubb3c\uc744 \uc5b4\ub5a4 \uc21c\uc11c\ub85c \ub9cc\ub098\ub294\uc9c0 \ud3b8\ud558\uac8c \uc77d\uc5b4\ub3c4 \uc88b\ub2e4. \ub2e4\uc74c\uc5d0\ub294 \uc568\ub9ac\uc2a4\uac00 \uc4f4 \ub9d0\uc774 \uc0c1\ub300\uc5d0\uac8c \uc5b4\ub5bb\uac8c \ubc1b\uc544\ub4e4\uc5ec\uc9c0\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \ub204\uac00 \uc9c8\ubb38\uc744 \ud53c\ud558\uace0 \ub204\uac00 \uc790\uae30 \ub73b\ub300\ub85c \ub2e8\uc5b4\ub97c \uc4f0\ub294\uc9c0 \ubcf4\uba74 \uae30\ubb18\ud55c \ub300\ud654\uac00 \uc870\uae08 \ub354 \uc815\uad50\ud558\uac8c \ub4e4\ub9b0\ub2e4. \u300e\uc774\uc0c1\ud55c \ub098\ub77c\uc758 \uc568\ub9ac\uc2a4\u300f\ub294 \ub0af\uc120 \uc138\uacc4\uc5d0 \ub300\ud55c \uc0c1\uc0c1\uacfc \uc6b0\ub9ac\uac00 \ub2f9\uc5f0\ud558\uac8c \uc4f0\ub294 \uc5b8\uc5b4\uc5d0 \ub300\ud55c \uc7a5\ub09c\uc744 \ud568\uaed8 \uac00\uc9c4\ub2e4. \ubaa8\ub4e0 \uc0c1\uc9d5\uc5d0 \ud558\ub098\uc529 \uc815\ub2f5\uc744 \ubd99\uc774\uc9c0 \uc54a\uc544\ub3c4 \uc990\uae38 \uc218 \uc788\ub2e4. \ud1a0\ub07c\uad74\uc5d0\uc11c \ub098\uc640 \ud3c9\uc18c\uc758 \ub300\ud654\ub97c \ub5a0\uc62c\ub9b4 \ub54c, \ub9d0\uc774 \ud1b5\ud55c\ub2e4\ub294 \uc77c\uc774 \uc5bc\ub9c8\ub098 \ub9ce\uc740 \uc57d\uc18d \uc704\uc5d0 \ub193\uc5ec \uc788\ub294\uc9c0 \uc870\uae08 \uc0c8\ub86d\uac8c \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4."}, {"id": "beethoven-fifth-four-notes", "title": "\ubca0\ud1a0\ubca4 \uad50\ud5a5\uace1 \uc81c5\ubc88 \u2014 \ub124 \uc74c\uc740 \uc5b4\ub5bb\uac8c \uae34 \uc774\uc57c\uae30\uac00 \ub420\uae4c", "summary": "\uc9e7\uc740 \uc74c\ud615\uc758 \ubc18\ubcf5\uacfc \ubcc0\ud654, \ub9c8\uc9c0\ub9c9 \uc545\uc7a5\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \ud750\ub984\uc744 \uc2e4\uc81c \uc545\ubcf4\uc640 \ud568\uaed8 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Music", "url": "stories/beethoven-fifth-four-notes/index.html", "image": "media/beethoven-fifth-four-notes.jpg", "alt": "\ubca0\ud1a0\ubca4 \uad50\ud5a5\uace1 \uc81c5\ubc88\uc758 \ub300\ud45c \uc74c\ud615\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc2e4\uc81c \uc545\ubcf4 \uc77c\ubd80. \uc138 \uac1c\uc758 \uc9e7\uc740 \uc74c\uacfc \uae38\uac8c \uba38\ubb34\ub294 \uc74c, \uac15\uc57d\u00b7\uc27c\ud45c\u00b7\ub298\uc784\ud45c\uac00 \ubcf4\uc785\ub2c8\ub2e4.", "text": "\ubca0\ud1a0\ubca4 \uad50\ud5a5\uace1 \uc81c5\ubc88 \u2014 \ub124 \uc74c\uc740 \uc5b4\ub5bb\uac8c \uae34 \uc774\uc57c\uae30\uac00 \ub420\uae4c \uc6b4\uba85\uc774\ub77c\ub294 \uc774\ub984\uc744 \uc7a0\uc2dc \ub0b4\ub824\ub193\uace0 \ub4e3\ub294 \ub124 \uc545\uc7a5 \uc9e7\uc740 \uc74c\ud615\uc758 \ubc18\ubcf5\uacfc \ubcc0\ud654, \ub9c8\uc9c0\ub9c9 \uc545\uc7a5\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \ud750\ub984\uc744 \uc2e4\uc81c \uc545\ubcf4\uc640 \ud568\uaed8 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Music \ubb38\ud654 \uc138 \ubc88 \uc9e7\uac8c, \ud55c \ubc88 \uae38\uac8c. \ubca0\ud1a0\ubca4 \uad50\ud5a5\uace1 \uc81c5\ubc88\uc758 \uc2dc\uc791\uc740 \ud074\ub798\uc2dd \uc81c\ubaa9\uc744 \uc798 \ubab0\ub77c\ub3c4 \uc54c\uc544\ub4e3\ub294 \uc0ac\ub78c\uc774 \ub9ce\ub2e4. \ub108\ubb34 \uc775\uc219\ud574\uc11c \ucc98\uc74c \ub124 \uc74c\ub9cc \ud655\uc778\ud558\uace0 \uc774\ubbf8 \uace1 \uc804\uccb4\ub97c \uc548\ub2e4\uace0 \ub290\ub07c\uae30 \uc27d\ub2e4. \ud558\uc9c0\ub9cc \uadf8 \uc9e7\uc740 \uc2dc\uc791\uc740 \uae34 \uc74c\uc545\uc758 \ubb38\uc5d0 \uac00\uae5d\ub2e4. \uc791\ud488\uc740 \ub2e4\ub2e8\uc870 \uad50\ud5a5\uace1 \uc81c5\ubc88, \uc791\ud488\ubc88\ud638 67\uc774\ub2e4. \u2018\uc6b4\uba85\u2019\uc774\ub77c\ub294 \uc774\ub984\uc774 \ub110\ub9ac \uc4f0\uc774\uc9c0\ub9cc \uadf8 \ud55c \ub2e8\uc5b4\ub85c \ubaa8\ub4e0 \uc7a5\uba74\uc744 \uc815\ub9ac\ud558\uc9c0 \uc54a\uace0, \uc791\uc740 \uc74c\ud615\uc774 \uc5b4\ub5bb\uac8c \ub3cc\uc544\uc624\uace0 \ub2ec\ub77c\uc9c0\ub294\uc9c0 \ub530\ub77c\uac00 \ubcf4\uc790. \uc545\ubcf4\ub97c \uc77d\uc9c0 \ubabb\ud574\ub3c4 \uc2dc\uc791\ud560 \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 \uc61b \uad50\ud5a5\uace1 \ud574\uc124\uc11c\uac00 \uc2e4\uc740 \uc2e4\uc81c \uc545\ubcf4 \uc77c\ubd80\ub2e4. \uc138 \uac1c\uc758 \uc9e7\uc740 \uc74c \ub4a4\uc5d0 \uc624\ub798 \uba38\ubb34\ub294 \uc74c\uc774 \ub098\uc624\uace0, \uadf8 \uc55e\uc758 \uc27c\uacfc \ub298\uc784\ud45c, \uac15\ud558\uac8c \ub0b4\ub77c\ub294 \ud45c\uae30\ub3c4 \ubcf4\uc778\ub2e4. \uc775\uc219\ud55c \u2018\ub530\ub530\ub530\ub2e8\u2019\uc744 \uae00\uc790\ub85c\ub9cc \uc801\uc73c\uba74 \ube60\uc9c0\ub294 \uc815\ubcf4\ub4e4\uc774\ub2e4. \ucc98\uc74c \ub4e4\uc5b4 \ubcfc \ub54c\ub294 \uc18c\ub9ac\uac00 \ub09c \uc21c\uac04\ubfd0 \uc544\ub2c8\ub77c \uba48\ucd94\uc5b4 \uc788\ub294 \uc21c\uac04\ub3c4 \uae30\ub2e4\ub824 \ubcf4\uc790. \ub2e4\uc74c \uc74c\uc774 \uc5b8\uc81c \uc62c\uc9c0 \uc0dd\uae30\ub294 \uae30\ub300\uac00 \uc2dc\uc791\uc758 \ud798\uc744 \ub9cc\ub4e0\ub2e4. \uac19\uc740 \ub124 \uc74c\uc774\ub77c\ub3c4 \uc5bc\ub9c8\ub098 \ubc00\uace0 \uc5b4\ub514\uc5d0\uc11c \uba38\ubb34\ub290\ub0d0\uc5d0 \ub530\ub77c \uc778\uc0c1\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ub9ac\ub4ec\uc740 \uc74c\uc758 \uac1c\uc218\ub9cc\uc744 \ub73b\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc61b \ud574\uc124\uc11c\uc5d0\ub3c4 \uc6b4\uba85\uc774 \ubb38\uc744 \ub450\ub4dc\ub9b0\ub2e4\ub294 \uc720\uba85\ud55c \uc124\uba85\uc774 \ub4f1\uc7a5\ud55c\ub2e4. \uc774\ub7f0 \uc774\uc57c\uae30\ub294 \uc9e7\uc740 \uc2dc\uc791\uc744 \uae30\uc5b5\ud558\ub294 \ub370 \ub3c4\uc6c0\uc744 \uc900\ub2e4. \ub2e4\ub9cc \uadf8\uac83\uc744 \uace1\uc758 \ubaa8\ub4e0 \ubd80\ubd84\uc744 \ud574\uc11d\ud558\ub294 \ud655\uc815\ub41c \uc791\uace1 \uc77c\uc9c0\ucc98\ub7fc \ucde8\uae09\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc774\ubc88\uc5d0 \ud655\uc778\ud55c \uc790\ub8cc\uc758 \uc815\uc2dd \ud45c\uc81c\ub294 \ubc88\ud638\uc640 \uc870\uc131\uc73c\ub85c \uc791\ud488\uc744 \uc2dd\ubcc4\ud55c\ub2e4. \uc6b4\uba85\uacfc \uc2f8\uc6cc \uc774\uae34\ub2e4\ub294 \uc774\uc57c\uae30\ub85c \ub4e4\uc5b4\ub3c4 \uc88b\uc9c0\ub9cc, \ub2e4\ub978 \ubc29\uc2dd\uc758 \ub4e3\uae30\ub3c4 \uac00\ub2a5\ud558\ub2e4. \uc5b4\ub5a4 \uc74c\ud615\uc774 \ub04a\uae30\uc9c0 \uc54a\uace0 \uc774\uc5b4\uc9c0\ub294\uc9c0, \ub2e4\ub978 \uc545\uae30\ub85c \ub118\uc5b4\uac08 \ub54c \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc9c0\ub294\uc9c0 \ub4e3\ub294 \uac83\uc774\ub2e4. \uce5c\uc219\ud55c \ubcc4\uba85 \uacc1\uc5d0 \uc74c\uc545\uc774 \uc2e4\uc81c\ub85c \ub9cc\ub4dc\ub294 \uad00\uacc4\ub97c \ub193\uc73c\uba74 \uace1\uc774 \ud55c \uac00\uc9c0 \uc904\uac70\ub9ac\ubcf4\ub2e4 \ub113\uc5b4\uc9c4\ub2e4. \uccab \uc545\uc7a5\uc5d0\uc11c\ub294 \uc2dc\uc791\uc758 \ub9ac\ub4ec\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \uc6c0\uc9c1\uc784\uc774 \uc5ec\ub7ec \uc790\ub9ac\uc5d0\uc11c \uadc0\ub97c \ubd99\uc7a1\ub294\ub2e4. \uac15\ud558\uac8c \ubab0\uc544\ubd99\uc774\ub294 \uc21c\uac04\uacfc \uc7a0\uc2dc \ub2e4\ub978 \ud45c\uc815\uc774 \uc5f4\ub9ac\ub294 \ubd80\ubd84\uc774 \uc774\uc5b4\uc9c0\uc9c0\ub9cc, \ucc98\uc74c\uc758 \uae34\uc7a5\uc740 \uc27d\uac8c \uc0ac\ub77c\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \uc9e7\uc740 \uc7ac\ub8cc\ub97c \uc5bc\ub9c8\ub098 \uae38\uace0 \ub2e4\uc591\ud558\uac8c \uc4f8 \uc218 \uc788\ub294\uc9c0 \ub290\ub07c\uac8c \ud55c\ub2e4. \ubc18\ubcf5\uc740 \uc81c\uc790\ub9ac\uc5d0\uc11c \uac19\uc740 \ub9d0\uc744 \ud558\ub294 \uac83\ub9cc\uc740 \uc544\ub2c8\ub2e4. \ub2e4\ub978 \ub192\uc774\uc640 \ub2e4\ub978 \uc545\uae30, \ub354 \ud070 \uc18c\ub9ac\uc640 \uc791\uc740 \uc18c\ub9ac\uc5d0\uc11c \ub3cc\uc544\uc62c \uc218 \uc788\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc5b4\ub514\uc11c \ub2e4\uc2dc \uc54c\uc544\ub4e3\uac8c \ub418\ub294\uc9c0 \ucc3e\uace0, \ub2e4\uc74c\uc5d0\ub294 \uadf8\ub54c \uc8fc\ubcc0\uc758 \uc18c\ub9ac\uac00 \uc5b4\ub5a4\uc9c0 \ub4e4\uc5b4 \ubcf4\uc790. \ubaa8\ub974\ub294 \uc545\uae30 \uc774\ub984\uc744 \ubaa8\ub450 \uc54c\uc544\uc57c \ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub450 \ubc88\uc9f8 \uc545\uc7a5\uc5d0\uc11c\ub294 \uccab \uc545\uc7a5\ubcf4\ub2e4 \ub113\uac8c \ub178\ub798\ud558\ub294 \uc120\uc728\uacfc \ucc28\ubd84\ud55c \uac78\uc74c\uc744 \ub9cc\ub09c\ub2e4. \uacc4\uc18d \uae34\ubc15\ud558\uac8c \ubab0\uc544\ubd99\uc774\ub294 \ud55c \ud3b8\uc758 \uc74c\uc545\uc744 \uc608\uc0c1\ud588\ub2e4\uba74 \uc758\uc678\ub85c \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \ud55c \uc791\ud488 \uc548\uc5d0\uc11c\ub3c4 \ub2e4\ub978 \uc885\ub958\uc758 \uc2dc\uac04\uc774 \uc5f4\ub9ac\ub294 \uac83\uc774\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubaa8\ub4e0 \uae34\uc7a5\uc774 \uc0ac\ub77c\uc838 \ud3b8\uc548\ud55c \ubc30\uacbd\uc74c\uc545\ub9cc \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc120\uc728\uc774 \ub2e4\uc2dc \ub098\ud0c0\ub0a0 \ub54c \uc8fc\ubcc0\uc758 \uc9dc\uc784\uacfc \ud798\uc774 \ub2ec\ub77c\uc9c0\ub294\uc9c0 \uadc0\ub97c \uae30\uc6b8\uc5ec \ubcf4\uc790. \ubd80\ub4dc\ub7ec\uc6b4 \ubd80\ubd84\uacfc \ub354 \ub2f9\ub2f9\ud558\uac8c \ub4e4\ub9ac\ub294 \ubd80\ubd84\uc744 \ube44\uad50\ud558\uba74 \ub290\ub9b0 \uc545\uc7a5\uc5d0\ub3c4 \ubcc0\ud654\uc758 \ud3ed\uc774 \uc788\ub2e4\ub294 \uc810\uc744 \uc54c \uc218 \uc788\ub2e4. \uc138 \ubc88\uc9f8 \uc545\uc7a5\uc5d0\uc11c\ub294 \ub0ae\uc740 \uc18c\ub9ac\uc640 \uc870\uc2ec\uc2a4\ub7ec\uc6b4 \uc6c0\uc9c1\uc784, \uac15\ud558\uac8c \ub098\ud0c0\ub098\ub294 \ubd80\ubd84\uc758 \ub300\ube44\ub97c \ub290\ub084 \uc218 \uc788\ub2e4. \uc55e\uc5d0\uc11c \ub4e4\uc740 \ub9ac\ub4ec\uc758 \uc131\uaca9\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \ub300\ubaa9\ub3c4 \uc788\ub2e4. \uccab \uc545\uc7a5\uc758 \uae30\uc5b5\uc774 \uc644\uc804\ud788 \ub2eb\ud788\uc9c0 \uc54a\uace0 \ub2e4\ub978 \ud45c\uc815\uc73c\ub85c \ub0a8\ub294 \uc148\uc774\ub2e4. \uc774 \ubd80\ubd84\uc744 \ube44\ubc00\uc2a4\ub7ec\uc6b4 \ubc24\uc774\ub098 \uae34\uc7a5\ub41c \ubc1c\uac78\uc74c\ucc98\ub7fc \uc0c1\uc0c1\ud574\ub3c4 \uc88b\uc9c0\ub9cc, \uadf8\uac83\uc774 \uc791\uace1\uac00\uac00 \uc815\ud574 \ub454 \uc7a5\uba74\uc774\ub77c\uace0 \ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc870\uc6a9\ud558\ub2e4\ub294 \uac83\uc774 \ub2e8\uc9c0 \uc26c\ub294 \uc2dc\uac04\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\uc744 \ub4e4\uc5b4 \ubcf4\uc790. \uc18c\ub9ac\uac00 \uc791\uc544\uc9c8\uc218\ub85d \ub2e4\uc74c\uc5d0 \ubb34\uc5c7\uc774 \ub098\uc62c\uc9c0 \uae30\ub2e4\ub9ac\ub294 \uac10\uac01\uc774 \ucee4\uc9c0\uae30\ub3c4 \ud55c\ub2e4. \uc138 \ubc88\uc9f8\uc5d0\uc11c \ub124 \ubc88\uc9f8\ub85c \uc774\uc5b4\uc9c0\ub294 \ubd80\ubd84\uc740 \uc804\uccb4\ub97c \ub4e3\ub294 \uc911\uc694\ud55c \uc774\uc720 \uc911 \ud558\ub098\ub2e4. \uc18c\ub9ac\uac00 \uc313\uc774\uace0 \uae30\ub2e4\ub9bc\uc774 \uae38\uc5b4\uc9c0\ub2e4\uac00 \ub9c8\uc9c0\ub9c9 \uc545\uc7a5\uc758 \ub113\uace0 \uac15\ud55c \uc18c\ub9ac\ub85c \ub098\uc544\uac04\ub2e4. \ucc98\uc74c \ub124 \uc74c\ub9cc \ub530\ub85c \ub4e4\uc5c8\uc744 \ub54c\ub294 \ub9cc\ub0a0 \uc218 \uc5c6\ub294 \uae34 \ud638\ud761\uc774\ub2e4. \uc774\ub54c \ub290\ub07c\ub294 \ud574\ubc29\uac10\uc774\ub098 \ubc1d\uc74c\uc740 \uc55e\uc5d0\uc11c \uc5b4\ub5a4 \uc2dc\uac04\uc744 \uac70\ucce4\ub294\uc9c0\uc640 \uc5f0\uacb0\ub41c\ub2e4. \ub05d\ubd80\ubd84\ub9cc \ub5bc\uc5b4 \ub4e4\uc73c\uba74 \uc6c5\uc7a5\ud55c \uc18c\ub9ac\uc774\uc9c0\ub9cc, \uadf8\uc804\uc758 \uae34\uc7a5\uc744 \uae30\uc5b5\ud558\uba70 \ub4e4\uc73c\uba74 \ub2e4\ub978 \ubb34\uac8c\ub97c \uac00\uc9c4\ub2e4. \uc74c\uc545\uc758 \uc758\ubbf8\uac00 \ud55c \uc120\uc728 \uc548\uc5d0\ub9cc \uc788\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc21c\uc11c\uc640 \uc9c0\ub098\uc628 \uc2dc\uac04\uc5d0\ub3c4 \uc788\ub2e4\ub294 \uc810\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ub9c8\uc9c0\ub9c9 \uc545\uc7a5\uc5d0\uc11c\ub294 \ud798\ucc28\uac8c \ub098\uc544\uac00\ub294 \ud750\ub984 \uc18d\uc5d0\uc11c\ub3c4 \uc55e\uc120 \uc545\uc7a5\uc758 \uae30\uc5b5\uc774 \ub418\uc0b4\uc544\ub098\ub294 \uc21c\uac04\uc774 \uc788\ub2e4. \uc9c1\uc120\uc73c\ub85c \ubc1d\uc740 \uacb0\ub860\uc5d0 \ub3c4\ucc29\ud55c\ub2e4\uace0\ub9cc \uc608\uc0c1\ud558\uba74 \uc774\ub7f0 \ub418\ub3cc\uc544\uc634\uc744 \ub193\uce60 \uc218 \uc788\ub2e4. \uc791\ud488\uc740 \uc9c0\ub098\uc628 \uc18c\ub9ac\ub97c \ub2e4\uc2dc \ub5a0\uc62c\ub9ac\uac8c \ud558\uba74\uc11c \ub05d\uc744 \ud5a5\ud55c\ub2e4. \ub9c8\ubb34\ub9ac\uac00 \uae38\uac8c \ub290\uaef4\uc9c8 \ub54c\uc5d0\ub294 \uc5b8\uc81c \ub05d\ub098\ub294\uc9c0 \ub9de\ud788\ub824 \ud558\uae30\ubcf4\ub2e4 \ub05d\uc744 \uc900\ube44\ud558\ub294 \ud798\uc774 \uc5b4\ub5bb\uac8c \uc720\uc9c0\ub418\ub294\uc9c0 \ub4e4\uc5b4 \ubcf4\uc790. \ud55c \ubc88\uc758 \ud070 \uc18c\ub9ac\ub85c \ub2eb\ub294 \uac83\uacfc \uc5ec\ub7ec \ubc88 \ud655\uc778\ud558\uba70 \ub2eb\ub294 \uac83\uc740 \ub2e4\ub978 \uacbd\ud5d8\uc774\ub2e4. \uc774 \uace1\uc774 \uc9e7\uc740 \ud45c\uc5b4\uac00 \uc544\ub2c8\ub77c \uae38\uac8c \uc9c4\ud589\ub418\ub294 \uc74c\uc545\uc774\ub77c\ub294 \uc0ac\uc2e4\uc774 \ub9c8\uc9c0\ub9c9\uae4c\uc9c0 \ub0a8\ub294\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc81c1\uc545\uc7a5, \ub2e4\uc74c\uc5d0\ub294 \uc81c3\uc545\uc7a5\uc5d0\uc11c \uc81c4\uc545\uc7a5\uc73c\ub85c \ub118\uc5b4\uac00\ub294 \ubd80\ubd84\uc744 \ub4e4\uc5b4\ub3c4 \uc88b\ub2e4. \uc5ec\uc720\uac00 \uc0dd\uae30\uba74 \ub124 \uc545\uc7a5\uc744 \uc774\uc5b4 \ub4e4\uc73c\uba70 \uc11c\ub85c \ub2e4\ub978 \ud45c\uc815\uc774 \uc5b4\ub5bb\uac8c \ud55c \uc791\ud488\uc744 \uc774\ub8e8\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uc815\ud574\uc9c4 \uac10\uc815\uc744 \ub9de\ud600\uc57c \ud558\ub294 \uac10\uc0c1\uc740 \uc544\ub2c8\ub2e4. \uc545\ubcf4\uc758 \uc9e7\uc740 \uc74c\uacfc \uae34 \uc74c\uc744 \ub208\uc73c\ub85c \ud655\uc778\ud55c \ub4a4 \uadc0\ub85c \ub2e4\uc2dc \ub9cc\ub098\uba74 \uc775\uc219\ud55c \uc2dc\uc791\ub3c4 \uc870\uae08 \uad6c\uccb4\uc801\uc73c\ub85c \ub4e4\ub9b0\ub2e4. \uc6b4\uba85\uc774\ub77c\ub294 \uc720\uba85\ud55c \uc774\ub984\uc740 \ucd9c\ubc1c\uc810\uc73c\ub85c \ub450\uace0, \uadf8 \ub4a4\uc758 \uc120\uc728\uacfc \uba48\ucda4, \ub3cc\uc544\uc624\ub294 \ub9ac\ub4ec\uc744 \ub530\ub77c\uac00 \ubcf4\uc790. \uc774\ubbf8 \uc548\ub2e4\uace0 \uc0dd\uac01\ud588\ub358 \ub124 \uc74c\uc774 \uc544\uc9c1 \ub4e3\uc9c0 \ubabb\ud55c \uae34 \uc2dc\uac04\uc73c\ub85c \uc774\uc5b4\uc9c4\ub2e4."}, {"id": "beethoven-life-and-work", "title": "\ubca0\ud1a0\ubca4\uc758 \uc0dd\uc560 \u2014 \ub4e4\ub9ac\ub294 \uc138\uacc4\uac00 \ub2ec\ub77c\uc838\ub3c4 \uc791\uc5c5\uc740 \uc774\uc5b4\uc84c\ub2e4", "summary": "\uc704\ub300\ud55c \uc74c\uc545\uac00\ub77c\ub294 \ub9d0 \ub4a4\uc758 \ubc30\uc6c0\uacfc \uc0dd\ud65c, \uc6d0\uace0\uc640 \uc0ac\ub78c\ub4e4\uc758 \uad00\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Music", "url": "stories/beethoven-life-and-work/index.html", "image": "media/beethoven-life-and-work.jpg", "alt": "\ub8e8\uc774 \ub808\ud2b8\ub860\uc758 1814\ub144 \ub4dc\ub85c\uc789\uc744 \ubc14\ud0d5\uc73c\ub85c \ud55c \ubca0\ud1a0\ubca4\uc758 \uc5ed\uc0ac\uc801 \ud310\ud654 \ucd08\uc0c1.", "text": "\ubca0\ud1a0\ubca4\uc758 \uc0dd\uc560 \u2014 \ub4e4\ub9ac\ub294 \uc138\uacc4\uac00 \ub2ec\ub77c\uc838\ub3c4 \uc791\uc5c5\uc740 \uc774\uc5b4\uc84c\ub2e4 \ubcf8\uc5d0\uc11c \ube48\uc73c\ub85c, \uccad\ub825\uc758 \uc5b4\ub824\uc6c0\uacfc \uc791\ud488\uc744 \ub9cc\ub4e4\uc5b4 \uac00\ub294 \uc2dc\uac04 \uc704\ub300\ud55c \uc74c\uc545\uac00\ub77c\ub294 \ub9d0 \ub4a4\uc758 \ubc30\uc6c0\uacfc \uc0dd\ud65c, \uc6d0\uace0\uc640 \uc0ac\ub78c\ub4e4\uc758 \uad00\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Music \ubb38\ud654 \ubca0\ud1a0\ubca4\uc744 \ub5a0\uc62c\ub9ac\uba74 \uac15\ud55c \ud45c\uc815\uc758 \uc5bc\uad74\uacfc \uc6c5\uc7a5\ud55c \uc74c\uc545, \ub4e4\uc744 \uc218 \uc5c6\uac8c \ub41c \uc791\uace1\uac00\ub77c\ub294 \uc774\uc57c\uae30\uac00 \ud568\uaed8 \ub098\uc628\ub2e4. \uadf8\ub7f0\ub370 \uadf8 \uba87 \uac00\uc9c0 \uc774\ubbf8\uc9c0\ub85c\ub294 \ud55c \uc0ac\ub78c\uc774 \uc5b4\ub5bb\uac8c \ubc30\uc6b0\uace0 \uc77c\ud558\uba70 \uc791\ud488\uc744 \ub2e4\ub4ec\uc5c8\ub294\uc9c0 \uc54c\uae30 \uc5b4\ub835\ub2e4. \uc0b6\uc744 \uc74c\uc545\uc758 \ube44\uadf9\uc801\uc778 \ubc30\uacbd \ud558\ub098\ub85c\ub9cc \ub9cc\ub4e4\uc9c0 \uc54a\uace0 \ub530\ub77c\uac00 \ubcfc \ud544\uc694\uac00 \uc788\ub2e4. \uadf8\ub294 1770\ub144 \ubcf8\uc5d0\uc11c \ud0dc\uc5b4\ub098 1827\ub144 \ube48\uc5d0\uc11c \uc138\uc0c1\uc744 \ub5a0\ub0ac\ub2e4. \uadf8 \uc0ac\uc774\uc5d0\ub294 \ud53c\uc544\ub178\ub97c \uc5f0\uc8fc\ud558\ub358 \uccad\ub144\uacfc \uc0c8\ub85c\uc6b4 \uc791\ud488\uc744 \uc4f0\ub358 \uc791\uace1\uac00, \uccad\ub825\uc758 \uc5b4\ub824\uc6c0\uacfc \uc0ac\ub78c\ub4e4\uacfc\uc758 \uad00\uacc4\ub97c \uac10\ub2f9\ud558\ub358 \uc0dd\ud65c\uc778\uc774 \uc788\uc5c8\ub2e4. \uc5b4\ub9b0 \ubca0\ud1a0\ubca4\uc740 \ubcf8\uc5d0\uc11c \uc74c\uc545\uc744 \ubc30\uc6e0\ub2e4. \uac00\uc871\uc758 \ud658\uacbd\uacfc \uc0dd\uacc4, \uc5f0\uc8fc\ub97c \uc775\ud600\uc57c \ud558\ub294 \uc2dc\uac04\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4. \ud6d7\ub0a0\uc758 \uc791\ud488 \uc774\ub984\ub9cc \ubcf4\uba74 \uc5b4\ub9b0 \uc2dc\uc808\ubd80\ud130 \uc790\uae30 \uc74c\uc545\uc744 \ubaa8\ub450 \uc54c\uace0 \uc788\ub358 \uc0ac\ub78c\ucc98\ub7fc \uc0c1\uc0c1\ud558\uae30 \uc27d\uc9c0\ub9cc, \uadf8\uc5d0\uac8c\ub3c4 \ubc30\uc6cc\uc57c \ud560 \uae30\uc220\uacfc \ucc98\uc74c \ub9cc\ub098\ub294 \uae30\ud68c\uac00 \uc788\uc5c8\ub2e4. \uc7ac\ub2a5\uc744 \ubc1c\uacac\ud558\ub294 \uadf9\uc801\uc778 \uc77c\ud654 \ud558\ub098\ubcf4\ub2e4 \uacc4\uc18d \uc545\uae30\ub97c \ub2e4\ub8e8\uace0 \uc74c\uc545\uc744 \uc775\ud788\ub294 \uc2dc\uac04\uc744 \uc0dd\uac01\ud574 \ubcf4\uc790. \ub208\uc5d0 \ub744\ub294 \ub2a5\ub825\uacfc \uadf8\uac83\uc744 \uc77c\ub85c \uc774\uc5b4 \uac00\ub294 \uc0dd\ud65c\uc740 \ub2e4\ub974\ub2e4. \uc74c\uc545\uac00\uc758 \uc0dd\uc560\uc5d0\uc11c\ub3c4 \uc5f0\uc2b5\uacfc \ud658\uacbd, \ub3c4\uc6c0\uc744 \uc8fc\ub294 \uc0ac\ub78c\ub4e4\uc774 \uad6c\uccb4\uc801\uc778 \uc790\ub9ac\ub97c \ucc28\uc9c0\ud55c\ub2e4. 1792\ub144 \uadf8\ub294 \ube48\uc73c\ub85c \uc62e\uaca8 \ud65c\ub3d9\ud55c\ub2e4. \uc0c8\ub85c\uc6b4 \ub3c4\uc2dc\uc5d0\uc11c \ubc30\uc6b0\uace0 \uc5f0\uc8fc\ud558\uba70 \uc0ac\ub78c\ub4e4\uc744 \ub9cc\ub09c\ub2e4. \uc5f0\uc8fc\uc790\ub85c \uc54c\ub824\uc9c0\ub294 \uc77c\uacfc \uc790\uae30 \uc791\ud488\uc744 \uc791\uace1\uac00\ub85c \ub0b4\ub193\ub294 \uc77c\uc774 \uc774\uc5b4\uc9c0\ub294 \uc2dc\uae30\ub2e4. \ube48\uc740 \uadf8\uc5d0\uac8c \uc774\ubbf8 \uc644\uc131\ub41c \uba85\uc131\uc744 \ud655\uc778\ud558\ub294 \ubb34\ub300\ub9cc\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ub3c4\uc2dc\uc758 \uccad\uc911\uacfc \uc74c\uc545\uac00, \ud6c4\uc6d0\uc790\uc640 \ucd9c\ud310\uc758 \uc870\uac74 \uc18d\uc5d0\uc11c \uc790\uc2e0\uc758 \uc790\ub9ac\ub97c \ub9cc\ub4e4\uc5b4\uc57c \ud588\ub2e4. \uc2a4\uc2a4\ub85c\uc758 \uac1c\uc131\uc744 \uc9c0\ud0a4\ub824\ub294 \ud0dc\ub3c4\ub3c4 \uc774\ub7f0 \uad00\uacc4\uc640 \ub5a8\uc5b4\uc838 \uc788\uc9c0 \uc54a\ub2e4. \ub3c5\ub9bd\uc801\uc778 \uc608\uc220\uac00\ub77c\ub294 \ub9d0\uc744 \ubaa8\ub4e0 \ub3c4\uc6c0\uacfc \ud604\uc2e4\uc758 \uc870\uac74\uc744 \ubc97\uc5b4\ub09c \uc0ac\ub78c\uc774\ub77c\ub294 \ub73b\uc73c\ub85c \ubc1b\uc544\ub4e4\uc774\uc9c0\ub294 \uc54a\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uccad\ub825\uc774 \ub098\ube60\uc9c0\ub294 \uacfc\uc815\uc740 \uc5f0\uc8fc\uc640 \uc77c\ubfd0 \uc544\ub2c8\ub77c \uc0ac\ub78c\uc744 \ub9cc\ub098\ub294 \uc0dd\ud65c\uc5d0\ub3c4 \uc601\ud5a5\uc744 \ubbf8\ucce4\ub2e4. \ub85c\ub9f9 \ub864\ub791\uc758 \uc804\uae30\uc5d0 \uc218\ub85d\ub41c \ud3b8\uc9c0\uc640 \ubb38\uc11c\uc5d0\ub294 \uadf8 \uc5b4\ub824\uc6c0\uc744 \uc5b4\ub5bb\uac8c \uc124\uba85\ud574\uc57c \ud560\uc9c0 \uace0\ubbfc\ud558\ub294 \ubaa9\uc18c\ub9ac\uac00 \ub0a8\uc544 \uc788\ub2e4. \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ubb34\ub69d\ub69d\ud558\uac8c \ubcf4\uc774\ub294 \ubaa8\uc2b5 \ub4a4\uc5d0 \uc54c\ub9ac\uc9c0 \ubabb\ud55c \uc0ac\uc815\uc774 \uc788\uc744 \uc218 \uc788\uc5c8\ub2e4. \uc774 \uae30\ub85d\uc744 \uc77d\uc73c\uba74 \uc131\uaca9\uc5d0 \ub300\ud55c \ub2e8\uc815\uc774 \uc870\uae08 \ub2a6\uc5b4\uc9c4\ub2e4. \ub298 \ud654\ub97c \ub0b4\ub294 \ucc9c\uc7ac\ub77c\ub294 \uc775\uc219\ud55c \uc778\uc0c1\ub9cc\uc73c\ub85c \uad00\uacc4 \uc804\uccb4\ub97c \uc124\uba85\ud558\uae30 \uc5b4\ub835\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubaa8\ub4e0 \uac08\ub4f1\uc774 \uccad\ub825 \ud558\ub098 \ub54c\ubb38\uc5d0 \uc77c\uc5b4\ub0ac\ub2e4\uace0 \uc815\ub9ac\ud560 \uc218\ub3c4 \uc5c6\ub2e4. \uc5ec\ub7ec \uc870\uac74\uc774 \ud55c \uc0ac\ub78c\uc758 \uc77c\uc0c1\uc744 \ud568\uaed8 \ub9cc\ub4e0\ub2e4. \ud558\uc77c\ub9ac\uac90\uc288\ud0c0\ud2b8\uc5d0\uc11c \uc4f4 1802\ub144\uc758 \uc720\uc11c\ub294 \uc790\uc2e0\uc758 \uace0\ud1b5\uacfc \uc624\ud574, \uc55e\uc73c\ub85c\uc758 \uc0b6\uc5d0 \uad00\ud55c \uc0dd\uac01\uc744 \uc804\ud55c\ub2e4. \uc791\ud488\uc744 \ub4e4\uc73c\uba70 \ub9c9\uc5f0\ud788 \uc0c1\uc0c1\ud588\ub358 \uc5b4\ub824\uc6c0\uc774 \uc2e4\uc81c \uae00\uc758 \ud615\ud0dc\ub85c \ub0a8\uc544 \uc788\ub2e4\ub294 \uc810\uc5d0\uc11c \uc911\uc694\ud55c \uc790\ub8cc\ub2e4. \ud654\ub824\ud55c \uc131\uacf5\ub2f4\ub9cc\uc73c\ub85c\ub294 \uc54c\uae30 \ud798\ub4e0 \ubaa9\uc18c\ub9ac\ub2e4. \uc5ec\uae30\uc11c \uace0\ud1b5\uc774 \ud6cc\ub96d\ud55c \uc791\ud488\uc744 \uc790\ub3d9\uc73c\ub85c \ub9cc\ub4e4\uc5b4 \uc8fc\uc5c8\ub2e4\ub294 \uacf5\uc2dd\uc744 \uc138\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5b4\ub824\uc6c0\uc744 \uacaa\ub294 \ub3d9\uc548\uc5d0\ub3c4 \uc5b4\ub5bb\uac8c \uc0b4\uc544\uac00\uace0 \uc791\uc5c5\ud560\uc9c0 \uace0\ubbfc\ud588\ub2e4\ub294 \uc810\uc744 \uc77d\ub294 \ud3b8\uc774 \ub0ab\ub2e4. \uc608\uc220\uc744 \uc774\ud574\ud558\ub824\uace0 \ud55c \uc0ac\ub78c\uc758 \uc544\ud514\uc744 \uac10\ub3d9\uc801\uc778 \uc7a5\uc2dd\uc73c\ub85c \uc18c\ube44\ud558\uc9c0 \uc54a\ub294 \ud0dc\ub3c4\ub3c4 \uc911\uc694\ud558\ub2e4. \uc791\uace1\uac00\uc758 \uc74c\uc545\uc740 \uc885\uc885 \uba38\ub9bf\uc18d\uc5d0\uc11c \uc644\uc131\ub418\uc5b4 \ud55c \ubc88\uc5d0 \uc885\uc774\ub85c \ub098\uc624\ub294 \uac83\ucc98\ub7fc \uc774\uc57c\uae30\ub41c\ub2e4. \ud558\uc9c0\ub9cc \ub0a8\uc740 \uc6d0\uace0\uc640 \uc5ec\ub7ec \uc790\ub8cc\ub97c \ubcf4\uba74 \ubb34\uc5c7\uc744 \uc120\ud0dd\ud558\uace0 \ub2e4\ub4ec\uc744\uc9c0 \uace0\ubbfc\ud558\ub294 \uc2dc\uac04\uc774 \uc788\uc5c8\ub2e4. \ud558\ub098\uc758 \uc120\uc728\uc744 \ub9cc\ub4e0 \ub4a4 \uc804\uccb4\uc758 \uad00\uacc4\ub97c \uc9dc\ub294 \uc77c\uc740 \ub2e4\ub978 \uc885\ub958\uc758 \uc791\uc5c5\uc774\ub2e4. \uc791\ud488\uc744 \ub4e4\uc744 \ub54c\ub3c4 \uc720\uba85\ud55c \uc8fc\uc81c\ub9cc \ub530\ub85c \uc544\ub294 \uac83\uc5d0\uc11c \uc870\uae08 \ub354 \ub098\uc544\uac08 \uc218 \uc788\ub2e4. \uc55e\uc758 \uc74c\uc545\uc774 \ub4a4\uc5d0\uc11c \uc5b4\ub5bb\uac8c \ub3cc\uc544\uc624\ub294\uc9c0, \uc5b4\ub5a4 \uc545\uc7a5\uc774 \uc11c\ub85c \ub300\ube44\ub418\ub294\uc9c0 \ub4e4\uc5b4 \ubcf4\ub294 \uac83\uc774\ub2e4. \ud55c \ubc88\uc758 \uc601\uac10\uacfc \uae34 \uad6c\uc131\uc758 \uc2dc\uac04\uc744 \ud568\uaed8 \uc0dd\uac01\ud558\uba74 \uc74c\uc545\uac00\uc758 \ub178\ub3d9\uc774 \uc870\uae08 \uad6c\uccb4\uc801\uc73c\ub85c \ubcf4\uc778\ub2e4. \uc804\uae30\uc640 \ud3b8\uc9c0\uc5d0\ub294 \ud6c4\uc6d0\uacfc \ub3c8, \uac00\uc871\uacfc \uac70\ucc98 \uac19\uc740 \ubb38\uc81c\uac00 \ub4f1\uc7a5\ud55c\ub2e4. \uc704\ub300\ud55c \uc791\ud488\uc744 \uc4f4\ub2e4\uace0 \uc77c\uc0c1\uc758 \uc0ac\uc815\uc774 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc791\ud488\uc744 \ub0b4\uace0 \uc5f0\uc8fc\ud558\uace0 \uc0dd\ud65c\uc744 \uc720\uc9c0\ud558\ub294 \uc77c\uc774 \uc11c\ub85c \uc5bd\ud614\ub2e4. \uc74c\uc545\uc758 \uc5ed\uc0ac\uc640 \uc0dd\ud65c\uc758 \uc5ed\uc0ac\ub294 \uac19\uc740 \uc0dd\uc560 \uc548\uc5d0 \uc788\ub2e4. \uc774\ub97c \uc54c\uba74 \uc791\ud488\uc744 \ub4e3\ub294 \uc990\uac70\uc6c0\uc774 \uaf2d \uc904\uc5b4\ub4dc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ud788\ub824 \uc644\uc131\ub41c \uc74c\uc545\uc744 \ub0a8\uae30\uae30 \uc704\ud574 \uc5b4\ub5a4 \uc870\uac74\uc744 \uac10\ub2f9\ud588\ub294\uc9c0 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uc791\uace1\uac00\ub97c \uc644\ubcbd\ud55c \uc131\uc778\uc73c\ub85c \ub9cc\ub4e4\uac70\ub098 \ubc18\ub300\ub85c \uc0ac\uc0dd\ud65c\uc758 \uac08\ub4f1\uc73c\ub85c \uc791\ud488 \uc804\uccb4\ub97c \ud310\uacb0\ud560 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \uad50\ud5a5\uace1 \uc81c9\ubc88\uc744 \ube44\ub86f\ud55c \ud6c4\uae30 \uc791\uc5c5\uc5d0\uc11c\ub294 \ubaa9\uc18c\ub9ac\uc640 \uc545\uae30, \ud070 \ud615\uc2dd\uacfc \uc138\ubc00\ud55c \uc6c0\uc9c1\uc784\uc774 \uc5ec\ub7ec \ubc29\uc2dd\uc73c\ub85c \ub098\ud0c0\ub09c\ub2e4. \uccad\ub825\uc774 \ud06c\uac8c \uc190\uc0c1\ub41c \uc2dc\uae30\uc5d0\ub3c4 \uc791\uc5c5\uc774 \uc774\uc5b4\uc84c\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uc911\uc694\ud558\ub2e4. \uadf8\ub7ec\ub098 \ubaa8\ub4e0 \uc791\ud488\uc744 \uac19\uc740 \uace0\ud1b5\uc758 \uace0\ubc31\uc73c\ub85c\ub9cc \ub4e3\ub294\ub2e4\uba74 \uc11c\ub85c \ub2e4\ub978 \uc74c\uc545\uc758 \uc131\uaca9\uc774 \uc0ac\ub77c\uc9c4\ub2e4. \uc55e\uc11c \ub9cc\ub09c \u3008\uc804\uc6d0\u3009\uc758 \uc2dc\ub0c7\uac00\uc640 \ub2e4\ub978 \uc791\ud488\uc758 \uae34\uc7a5, \ub178\ub798\ud558\ub294 \uc120\uc728\uacfc \uac15\ud55c \ub9ac\ub4ec\uc744 \ube44\uad50\ud574 \ubcf4\uc790. \ud55c \uc791\uace1\uac00 \uc548\uc5d0\ub3c4 \ub2e4\uc591\ud55c \ud45c\uc815\uc774 \uc788\ub2e4. \uc0dd\uc560\uc758 \ud070 \uc0ac\uc2e4\uc744 \uc54c\uc544 \ub454 \ub4a4\uc5d0\ub294 \ub2e4\uc2dc \uc2e4\uc81c\ub85c \uc774\uc5b4\uc9c0\ub294 \uc74c\uacfc \uad6c\uc870\uc5d0 \uadc0\ub97c \ub3cc\ub9ac\ub294 \uac83\uc774 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \ub8e8\uc774 \ub808\ud2b8\ub860\uc758 1814\ub144 \ub4dc\ub85c\uc789\uc744 \ubc14\ud0d5\uc73c\ub85c \ud55c \ube14\ub77c\uc9c0\uc6b0\uc2a4 \ud68c\ud3a0\uc758 \uc5ed\uc0ac\uc801 \ucd08\uc0c1 \ud310\ud654\ub2e4. \uc624\ub298 \ub5a0\uc62c\ub9ac\ub294 \ubca0\ud1a0\ubca4\uc758 \uc5bc\uad74\uc744 \uc804\ud558\ub294 \uc790\ub8cc \uc911 \ud558\ub098\uc9c0\ub9cc, \uadf8 \ud45c\uc815\ub9cc\uc73c\ub85c \ub9e4\uc77c\uc758 \uac10\uc815\uc744 \uc9c4\ub2e8\ud560 \uc218\ub294 \uc5c6\ub2e4. \ubca0\ud1a0\ubca4\uc758 \uc0b6\uc744 \uc54c\uc558\ub2e4\ub294 \uac83\uc740 \uccad\ub825\uacfc \uc8fd\uc74c\uc758 \uc5f0\ub3c4\ub97c \uc678\uc6e0\ub2e4\ub294 \ub73b\uc5d0 \uba38\ubb3c\uc9c0 \uc54a\ub294\ub2e4. \ubc30\uc6b0\uace0 \uc774\ub3d9\ud558\uace0, \ubb38\uc11c\ub97c \uc4f0\uace0, \uc6d0\uace0\ub97c \uace0\uce58\uba70 \uc77c\uc744 \uc774\uc5b4 \uac04 \uc0ac\ub78c\uc744 \ud568\uaed8 \uae30\uc5b5\ud558\ub294 \uac83\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \uc775\uc219\ud55c \uace1\uc744 \ub9cc\ub098\uba74 \ucc9c\uc7ac\ub77c\ub294 \ub9d0\uc5d0 \uac00\ub824\uc84c\ub358 \uae34 \uc791\uc5c5\uc758 \uc2dc\uac04\uc744 \uc870\uae08 \ub5a0\uc62c\ub824 \ubcf4\uc544\ub3c4 \uc88b\uaca0\ub2e4."}, {"id": "beethoven-pastoral-five-scenes", "title": "\ubca0\ud1a0\ubca4 \uc804\uc6d0 \uad50\ud5a5\uace1 \u2014 \uc2dc\uace8\uc758 \ud558\ub8e8\ub97c \ub2e4\uc12f \uc545\uc7a5\uc73c\ub85c \uac77\uae30", "summary": "\ud48d\uacbd\uacfc \uac10\uc815\uc774 \ud568\uaed8 \uc6c0\uc9c1\uc774\ub294 \uad50\ud5a5\uace1 \uc81c6\ubc88\uc758 \ud750\ub984\uc744 \ub530\ub77c \ub4e3\uc2b5\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Music", "url": "stories/beethoven-pastoral-five-scenes/index.html", "image": "media/beethoven-pastoral-five-scenes.jpg", "alt": "\ucf54\ub85c\uc758 \ud48d\uacbd\ud654 \uc791\uc740 \uace8\uc9dc\uae30\ub97c \uc7ac\ud604\ud55c \uc61b \ub3c4\ud310. \uc804\uc6d0 \uad50\ud5a5\uace1\uc758 \uc790\uc5f0 \ubd84\uc704\uae30\ub97c \ud568\uaed8 \ub5a0\uc62c\ub9ac\uae30 \uc704\ud55c \uad00\ub828 \uc774\ubbf8\uc9c0\uc785\ub2c8\ub2e4.", "text": "\ubca0\ud1a0\ubca4 \uc804\uc6d0 \uad50\ud5a5\uace1 \u2014 \uc2dc\uace8\uc758 \ud558\ub8e8\ub97c \ub2e4\uc12f \uc545\uc7a5\uc73c\ub85c \uac77\uae30 \ub4e4\ud310\uc758 \uae30\uc068\uacfc \uc2dc\ub0c7\ubb3c, \ud3ed\ud48d \ub4a4\uc758 \uac10\uc0ac \ud48d\uacbd\uacfc \uac10\uc815\uc774 \ud568\uaed8 \uc6c0\uc9c1\uc774\ub294 \uad50\ud5a5\uace1 \uc81c6\ubc88\uc758 \ud750\ub984\uc744 \ub530\ub77c \ub4e3\uc2b5\ub2c8\ub2e4. Music \ubb38\ud654 \uc2dc\uace8\uc5d0 \ub3c4\ucc29\ud558\uc790 \ub9c8\uc74c\uc774 \uc870\uae08 \ud480\ub9ac\uace0, \ubb3c\uac00\uc5d0\uc11c \uc624\ub798 \uba38\ubb3c\uace0 \uc2f6\uc5b4\uc9c4\ub2e4. \uc0ac\ub78c\ub4e4\uc758 \ubaa8\uc784\uc774 \uc2dc\uc791\ub418\uc9c0\ub9cc \uc5b4\ub290\uc0c8 \ud558\ub298\uc774 \uc5b4\ub450\uc6cc\uc9c0\uace0 \ube44\ubc14\ub78c\uc774 \ubab0\ub824\uc628\ub2e4. \ud3ed\ud48d\uc774 \uc9c0\ub09c \ub4a4\uc5d0\ub294 \ucc98\uc74c\uacfc \ub2e4\ub978 \uace0\uc694\uac00 \ucc3e\uc544\uc628\ub2e4. \ubca0\ud1a0\ubca4 \uad50\ud5a5\uace1 \uc81c6\ubc88 \u3008\uc804\uc6d0\u3009\uc740 \uc774\ub7f0 \ud750\ub984\uc744 \ub2e4\uc12f \uc545\uc7a5\uc73c\ub85c \ub4e4\ub824\uc900\ub2e4. 1808\ub144\uc758 \uc774 \uc791\ud488\uc740 \uac01 \uc545\uc7a5\uc5d0 \uc7a5\uba74\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \ud45c\uc81c\uac00 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \ub4e4\ub9ac\ub294 \uc74c\uc744 \ubaa8\ub450 \uc0ac\ubb3c \ud558\ub098\uc640 \ub9de\ucd94\ub294 \ud034\uc988\ub85c \ub9cc\ub4e4 \ud544\uc694\ub294 \uc5c6\ub2e4. \ud48d\uacbd\uc744 \ub9cc\ub098\ub294 \uc0ac\ub78c\uc758 \uac10\uc815\uc774 \uc5b4\ub5bb\uac8c \ubc14\ub00c\ub294\uc9c0 \ud568\uaed8 \ub4e4\uc5b4 \ubcf4\uc790. \uccab \uc545\uc7a5\uc758 \ud45c\uc81c\ub294 \uc2dc\uace8\uc5d0 \ub3c4\ucc29\ud588\uc744 \ub54c\uc758 \uc990\uac70\uc6b4 \uac10\uc815\uacfc \uc5f0\uacb0\ub41c\ub2e4. \ub9c9 \ub2ec\ub824\uc628 \ub4a4 \uac11\uc790\uae30 \uc644\uc804\ud788 \uba48\ucd94\uae30\ubcf4\ub2e4 \uc791\uc740 \uc6c0\uc9c1\uc784\uc774 \ubc18\ubcf5\ub418\uace0 \uc790\ub77c\uba70 \uacf5\uac04\uc774 \uc5f4\ub9ac\ub294 \ub290\ub08c\uc744 \uc900\ub2e4. \ucc98\uc74c\ubd80\ud130 \ud070 \uc0ac\uac74\uc774 \ud130\uc9c0\uc9c0 \uc54a\uc544\ub3c4 \uc74c\uc545\uc740 \uc6b0\ub9ac\ub97c \uc5b4\ub5a4 \uc7a5\uc18c\ub85c \ub370\ub824\uac08 \uc218 \uc788\ub2e4. \uc8fc\uc81c\uac00 \ub2e4\uc2dc \ub098\uc62c \ub54c\ub9c8\ub2e4 \uc5b4\ub514\uac00 \uac19\uace0 \uc5b4\ub514\uac00 \ub2ec\ub77c\uc9c0\ub294\uc9c0 \ub4e4\uc5b4 \ubcf4\uc790. \ubc18\ubcf5\uc740 \uc9c0\ub8e8\ud55c \ub300\uae30\uac00 \uc544\ub2c8\ub77c \ud55c \ud48d\uacbd\uc5d0 \ub354 \uc624\ub798 \uba38\ubb34\ub294 \uc2dc\uac04\uc774 \ub420 \uc218 \uc788\ub2e4. \ub0af\uc120 \uc7a5\uc18c\uc5d0 \ub3c4\ucc29\ud574 \uc11c\uc11c\ud788 \uc8fc\ubcc0\uc758 \uc18c\ub9ac\ub97c \uc54c\uc544\ub4e3\ub294 \uacbd\ud5d8\uc744 \ub5a0\uc62c\ub824\ub3c4 \uc88b\ub2e4. \ub458\uc9f8 \uc545\uc7a5\uc740 \uc2dc\ub0c7\uac00\uc758 \uc7a5\uba74\uc774\ub2e4. \ud750\ub974\ub294 \ubc18\uc8fc\uc640 \uc120\uc728\uc774 \uc774\uc5b4\uc9c0\uba74\uc11c \uccab \uc545\uc7a5\uc758 \ub3c4\ucc29\uacfc\ub294 \ub2e4\ub978 \uc885\ub958\uc758 \uba38\ubb34\ub984\uc744 \ub290\ub07c\uac8c \ud55c\ub2e4. \ubaa9\uc801\uc9c0\ub85c \ube68\ub9ac \uac00\ub294 \uc6c0\uc9c1\uc784\ubcf4\ub2e4 \uac19\uc740 \uacf3\uc5d0\uc11c \uacc4\uc18d \ud750\ub974\ub294 \ubb3c\uc744 \ub4e3\ub294 \uc2dc\uac04\uc5d0 \uac00\uae5d\ub2e4. \uc774\ub54c \uc5b4\ub5a4 \uc2e4\uc81c \uc2dc\ub0c7\ubb3c\uc744 \uc815\ud655\ud788 \ub179\uc74c\ud574 \uc62e\uae34 \uac83\ucc98\ub7fc \ub4e4\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc545\uae30\uac00 \ub9cc\ub4e0 \ubc18\ubcf5\uacfc \ubcc0\ud654\uac00 \ubb3c\uc758 \ub290\ub08c\uc744 \uc5b4\ub5bb\uac8c \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uba74 \ub41c\ub2e4. \uc790\uc5f0\uc744 \ubb18\uc0ac\ud558\ub294 \uc74c\uc545\uacfc \uc790\uc5f0 \uc18d\uc5d0\uc11c \uc0ac\ub78c\uc774 \ub290\ub07c\ub294 \uc74c\uc545\uc774 \uc11c\ub85c \uac00\uae4c\uc774 \ub193\uc778\ub2e4. \ub458\uc9f8 \uc545\uc7a5 \ub05d \ubb34\ub835\uc758 \uc0c8\uc18c\ub9ac\ub294 \uc720\uba85\ud558\ub2e4. \ud574\uc124 \uc790\ub8cc\ub294 \ub098\uc774\ud305\uac8c\uc77c\uc744 \ud50c\ub8e8\ud2b8, \uba54\ucd94\ub77c\uae30\ub97c \uc624\ubcf4\uc5d0, \ubed0\uafb8\uae30\ub97c \ud074\ub77c\ub9ac\ub137\uacfc \uc5f0\uacb0\ud558\uba70 \uc545\ubcf4\uc5d0 \ud45c\uc9c0\uac00 \uc788\uc74c\uc744 \uc124\uba85\ud55c\ub2e4. \ubaa8\ub4e0 \uc18c\ub9ac\uac00 \ub9c9\uc5f0\ud55c \uccad\uc911\uc758 \uc0c1\uc0c1\ub9cc\uc740 \uc544\ub2c8\ub77c\ub294 \ub73b\uc774\ub2e4. \uba3c\uc800 \uc0c8 \uc774\ub984\uc744 \uc678\uc6b0\uae30\ubcf4\ub2e4 \uc5b4\ub5a4 \uc18c\ub9ac\uac00 \uac00\ubccd\uac8c \uc774\uc5b4\uc9c0\uace0 \uc5b4\ub5a4 \uc18c\ub9ac\uac00 \ubc18\ubcf5\ud574\uc11c \ubd80\ub974\ub294\uc9c0 \ub4e4\uc5b4 \ubcf4\uc790. \uc54c\uace0 \ub4e4\uc73c\uba74 \uc545\uae30\uc758 \ucc28\uc774\ub97c \uc54c\uc544\ubcf4\ub294 \uae38\ub3c4 \ub41c\ub2e4. \ub2e4\ub9cc \uc2e4\uc81c \uc0c8 \uc6b8\uc74c\uc758 \uacfc\ud559\uc801 \ud45c\ubcf8\uc73c\ub85c \ud310\uc815\ud560 \uc77c\uc740 \uc544\ub2c8\ub2e4. \uc74c\uc545 \uc548\uc5d0\uc11c \uc11c\ub85c \ub2e4\ub978 \uc18c\ub9ac\ub4e4\uc774 \ub193\uc774\ub294 \uad00\uacc4\uac00 \uc911\uc694\ud558\ub2e4. \uc2dc\uace8 \uc0ac\ub78c\ub4e4\uc758 \uc990\uac70\uc6b4 \ubaa8\uc784\uc774\ub77c\ub294 \ud45c\uc81c\uac00 \ub098\uc624\uba74 \uc790\uc5f0\ub9cc \ubc14\ub77c\ubcf4\ub358 \uc2dc\uc120\uc774 \uc0ac\ub78c\ub4e4\uc758 \uc6c0\uc9c1\uc784\uc73c\ub85c \ubc14\ub010\ub2e4. \ucda4\uacfc \ubaa8\uc784\uc744 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub294 \ub9ac\ub4ec\uc774 \uadc0\ub97c \ubd99\uc7a1\ub294\ub2e4. \uc2dc\uace8\uc740 \ube48 \ub4e4\ud310\uc774 \uc544\ub2c8\ub77c \uc0ac\ub78c\ub4e4\uc774 \ub9cc\ub098 \uc0b4\uc544\uac00\ub294 \uc7a5\uc18c\uc774\uae30\ub3c4 \ud558\ub2e4. \uc778\ubb3c\uc758 \uc5bc\uad74\uc774\ub098 \uad6c\uccb4\uc801\uc778 \uc758\uc0c1\uc744 \uc0c1\uc0c1\ud558\uc9c0 \uc54a\uc544\ub3c4 \uad1c\ucc2e\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc545\uae30\uac00 \ub0b4\ub193\ub294 \uc6c0\uc9c1\uc784\uc774 \uc5bc\ub9c8\ub098 \uac00\ubccd\uac70\ub098 \ud22c\ubc15\ud558\uac8c \ub290\uaef4\uc9c0\ub294\uc9c0 \ub4e4\uc5b4 \ubcf4\uc790. \ud55c \uac00\uc9c0 \uc544\ub984\ub2e4\uc6b4 \ud45c\uc815\uc73c\ub85c\ub9cc \uc790\uc5f0\uc744 \uc124\uba85\ud558\uc9c0 \uc54a\uace0 \uadf8 \uc548\uc758 \ud65c\uae30\uc640 \ubab8\uc758 \ub9ac\ub4ec\uc744 \ub9cc\ub098\ub294 \uc2dc\uac04\uc774 \ub41c\ub2e4. \uc990\uac70\uc6b4 \ubaa8\uc784\uc5d0\uc11c \uac11\uc790\uae30 \ub0a0\uc528\uac00 \ubc14\ub010\ub2e4. \uc18c\ub9ac\uac00 \uac70\uce60\uc5b4\uc9c0\uace0 \uae34\uc7a5\uc774 \ucee4\uc9c0\uba70 \ucc9c\ub465\uacfc \ube44\ubc14\ub78c\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \uc55e\uc5d0\uc11c \ucda9\ubd84\ud788 \ud3c9\uc628\uacfc \ud65c\uae30\ub97c \uacbd\ud5d8\ud588\uae30 \ub54c\ubb38\uc5d0 \uc774 \ubcc0\ud654\ub294 \ub354 \ud06c\uac8c \ub2e4\uac00\uc62c \uc218 \uc788\ub2e4. \ud3ed\ud48d\uc774\ub77c\ub294 \uc81c\ubaa9\uc744 \uc54c\uace0 \ub4e4\uc73c\uba74 \ubb34\uc5c7\uc744 \ud45c\ud604\ud558\ub294\uc9c0 \uc27d\uac8c \ub4e4\uc5b4\uac08 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \ubaa8\ub4e0 \ud070 \uc18c\ub9ac\ub97c \ubc88\uac1c \ud55c \ubc88, \uc791\uc740 \uc18c\ub9ac\ub97c \ube57\ubc29\uc6b8 \ud558\ub098\ub85c \uc138\uc5b4 \ub9de\ucd9c \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5ec\ub7ec \uc18c\ub9ac\uac00 \ud568\uaed8 \uac15\ub3c4\ub97c \ubc14\uafb8\uba70 \uc548\uc815\ub41c \ub290\ub08c\uc744 \ud754\ub4dc\ub294 \ubc29\uc2dd\uc5d0 \uadc0\ub97c \ub450\uba74 \uc74c\uc545\uc758 \ud070 \ud750\ub984\uc774 \ubcf4\uc778\ub2e4. \ub2e4\uc12f\uc9f8 \uc545\uc7a5\uc740 \ubaa9\ub3d9\uc758 \ub178\ub798\uc640 \ud3ed\ud48d \ub4a4\uc758 \uae30\uc058\uace0 \uac10\uc0ac\ud55c \uac10\uc815\uc73c\ub85c \uc18c\uac1c\ub41c\ub2e4. \ub2e8\uc21c\ud788 \uccab \uc7a5\uba74\uc73c\ub85c \ub3cc\uc544\uac00 \uc544\ubb34 \uc77c\ub3c4 \uc5c6\uc5c8\ub358 \ub4ef \ub05d\ub098\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub4e3\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc774\ubbf8 \ud3ed\ud48d\uc744 \uc9c0\ub098\uc628 \uae30\uc5b5\uc774 \uc788\ub2e4. \uadf8\ub798\uc11c \ub9c8\uc9c0\ub9c9\uc758 \ubd80\ub4dc\ub7ec\uc6c0\uc774 \ucc98\uc74c\uc758 \uc5ec\uc720\uc640 \ub2e4\ub974\uac8c \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \uc791\ud488 \uc18d \ud48d\uacbd\uc774 \ub2ec\ub77c\uc84c\uae30 \ub54c\ubb38\ub9cc\uc774 \uc544\ub2c8\ub77c \uc6b0\ub9ac\uac00 \uc9c0\ub098\uc628 \uc2dc\uac04 \ub54c\ubb38\uc774\ub2e4. \ud55c \uc545\uc7a5\ub9cc \ub530\ub85c \ub4e4\uc5c8\uc744 \ub54c\uc640 \uc804\uccb4\ub97c \uc774\uc5b4 \ub4e4\uc5c8\uc744 \ub54c\uc758 \ucc28\uc774\uac00 \uc5ec\uae30\uc11c \ubd84\uba85\ud574\uc9c4\ub2e4. \uc804\uc6d0 \uad50\ud5a5\uace1\uc744 \ub2e4\ub8ec \uc61b \ud574\uc124\uc740 \ud48d\uacbd\uc758 \ubb18\uc0ac\ubcf4\ub2e4 \uac10\uc815\uc758 \ud45c\ud604\uc774\ub77c\ub294 \uc791\uace1\uac00\uc758 \uc124\uba85\ub3c4 \uc804\ud55c\ub2e4. \uc7a5\uba74\uc758 \uc774\ub984\uc744 \uc54c\ub824 \uc8fc\uba74\uc11c\ub3c4 \uc790\uc5f0\ubb3c\uc758 \ubaa8\uc0ac\ub9cc\uc73c\ub85c \uc791\ud488\uc744 \ub2eb\uc9c0 \uc54a\uc73c\ub824\ub294 \uc0dd\uac01\uc744 \uc77d\uc744 \uc218 \uc788\ub2e4. \uc624\ub298\uc758 \ub3c5\uc790\ub294 \uc74c\uc545\uc758 \ud45c\uc81c\ub97c \ucd9c\ubc1c\uc810\uc73c\ub85c \uc0bc\ub418 \uac19\uc740 \uac10\uc815\uc744 \ub290\uaef4\uc57c \ud55c\ub2e4\uace0 \uc560\uc4f8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc2dc\ub0c7\uac00\uc5d0\uc11c \ud3c9\uc628\ud568\uc744 \ub290\ub07c\ub294 \uc0ac\ub78c\ub3c4 \uc788\uace0 \ub04a\uc784\uc5c6\uc774 \uc6c0\uc9c1\uc774\ub294 \uc2dc\uac04\uc5d0 \ub354 \uadc0\ub97c \uae30\uc6b8\uc774\ub294 \uc0ac\ub78c\ub3c4 \uc788\ub2e4. \ud48d\uacbd\uc744 \ub9cc\ub09c\ub2e4\ub294 \uc77c\uc5d0\ub3c4 \uac01\uc790\uc758 \uae30\uc5b5\uc774 \ub4e4\uc5b4\uac04\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \ucf54\ub85c\uc758 \ud48d\uacbd\ud654 \u3008\uc791\uc740 \uace8\uc9dc\uae30\u3009\uc758 \uc61b \uc7ac\ud604 \ub3c4\ud310\uc774\ub2e4. \uc790\uc5f0\uc758 \ubd84\uc704\uae30\ub97c \ud568\uaed8 \ub5a0\uc62c\ub9ac\uae30 \uc704\ud574 \uace0\ub978 \uad00\ub828 \ud68c\ud654\uc774\uba70 \ubca0\ud1a0\ubca4\uc774 \uc774 \uadf8\ub9bc\uc744 \ubcf4\uace0 \uc791\uace1\ud588\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc74c\uc545\uc758 \uc2e4\uc81c \uc545\ubcf4\ub098 \ud2b9\uc815 \uc2dc\uace8\uc758 \ubcf5\uc6d0\ub3c4\uc640\ub3c4 \uad6c\ubd84\ub41c\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc2dc\ub0c7\uac00\uc758 \ub458\uc9f8 \uc545\uc7a5\uacfc \ud3ed\ud48d \ub4a4\uc758 \ub9c8\uc9c0\ub9c9 \uc545\uc7a5\uc744 \ube44\uad50\ud574 \ub4e4\uc5b4\ub3c4 \uc88b\ub2e4. \ub2e4\uc74c\uc5d0\ub294 \ub2e4\uc12f \uc545\uc7a5\uc744 \uc774\uc5b4 \ubcf4\uba70 \ub3c4\ucc29\uacfc \uba38\ubb34\ub984, \uc0ac\ub78c\ub4e4\uc758 \ubaa8\uc784\uacfc \ub0a0\uc528\uc758 \ubcc0\ud654\uac00 \uc5b4\ub5a4 \uc21c\uc11c\ub85c \ub9c8\uc74c\uc744 \uc6c0\uc9c1\uc774\ub294\uc9c0 \ub290\uaef4 \ubcf4\uc790. \uad50\ud5a5\uace1\uc774\ub77c\ub294 \uae34 \ud615\uc2dd\uc774 \ud55c \ud48d\uacbd\uc5d0 \uc624\ub798 \uba38\ubb3c \uc5ec\uc720\ub97c \ub9cc\ub4e4\uc5b4 \uc904 \uc218 \uc788\ub2e4."}, {"id": "book-owner-seal", "title": "\ucc45\uc5d0\ub3c4 \uc8fc\uc778\uc758 \uc774\ub984\ud45c\ub97c \ucc0d\uc5b4 \ub450\uc5c8\ub2e4", "summary": "\uc774\ub984\uc744 \uc4f0\uac70\ub098 \uc2a4\ud2f0\ucee4\ub97c \ubd99\uc774\ub4ef, \ucc45\uc5d0 \ub3c4\uc7a5\uc744 \ucc0d\uc5b4 \uc18c\uc7a5\uc744 \ud45c\uc2dc\ud558\uae30\ub3c4 \ud588\uc2b5\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Literature", "url": "stories/book-owner-seal/index.html", "image": "media/book-owner-seal.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00 \uc18c\uc7a5 \uc5f0\uacbd\uc7ac\uc7a5\uc11c\uc778 \uc778\uc7a5\uc758 \ub3cc \ubab8\uccb4 \ubaa8\uc2b5", "text": "\ucc45\uc5d0\ub3c4 \uc8fc\uc778\uc758 \uc774\ub984\ud45c\ub97c \ucc0d\uc5b4 \ub450\uc5c8\ub2e4 \uc791\uc740 \uc5f0\uacbd\uc7ac\uc7a5\uc11c\uc778\uc774 \uc54c\ub824\uc8fc\ub294 \ucc45\uacfc \ub3c4\uc7a5\uc758 \uad00\uacc4 \uc774\ub984\uc744 \uc4f0\uac70\ub098 \uc2a4\ud2f0\ucee4\ub97c \ubd99\uc774\ub4ef, \ucc45\uc5d0 \ub3c4\uc7a5\uc744 \ucc0d\uc5b4 \uc18c\uc7a5\uc744 \ud45c\uc2dc\ud558\uae30\ub3c4 \ud588\uc2b5\ub2c8\ub2e4. Literature \ubb38\ud654 \ucc45\uc744 \ube4c\ub824\uc8fc\uae30 \uc804\uc5d0 \uccab \uc7a5\uc5d0 \uc774\ub984\uc744 \uc368 \ub454 \uacbd\ud5d8\uc774 \uc788\uc744 \uac83\uc774\ub2e4. \ub098\uc911\uc5d0 \ub3cc\uc544\uc654\uc744 \ub54c \ub204\uad6c\uc758 \ucc45\uc778\uc9c0 \uc54c\uc544\ubcfc \uc218 \uc788\uac8c \ud558\ub824\ub294 \uc791\uc740 \ud45c\uc2dc\ub2e4. \uc61b \ucc45\uacfc \uc11c\ud654\uc5d0\uc11c\ub294 \uadf8\ub7f0 \uc5ed\ud560\uc744 \ud558\ub294 \ub3c4\uc7a5\ub3c4 \ub9cc\ub09c\ub2e4. \uc7a5\uc11c\uc778\uc774\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc5d0\ub294 \u2018\uc5f0\uacbd\uc7ac\uc7a5\uc11c\uc778\u2019\uc774\ub77c\ub294 \uae00\uc790\ub97c \uc0c8\uae34 \ub3cc\ub3c4\uc7a5\uc774 \uc788\ub2e4. \uc0ac\uc9c4 \uc18d\uc758 \ubab8\uccb4\ub294 \uc190\uc5d0 \ub4e4\uc5b4\uc62c \ub9cc\ud55c \ud06c\uae30\uc758 \uc791\uc740 \ub3cc\uc774\ub2e4. \uadf8\ub7f0\ub370 \uadf8 \ub3c4\uc7a5\uc774 \ub0a8\uae30\ub294 \uae00\uc790\uc5d0\ub294 \ucc45\uc774 \uba38\ubb3c\ub358 \uacf3\uc758 \uc774\ub984\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc774 \uc778\uc7a5\uc774 \uc5f0\uacbd\uc7ac\uc5d0 \uc18c\uc7a5\ud55c \uc11c\uc801\uacfc \uc11c\ud654 \ub4f1\uc5d0 \ucc0d\ub358 \uac83\uc774\ub77c\uace0 \uc124\uba85\ud55c\ub2e4. \uc81c\ubaa9\uc758 \u2018\uc7a5\uc11c\u2019\ub294 \ucc45\uc744 \ubaa8\uc544 \uc18c\uc7a5\ud55c\ub2e4\ub294 \ub9d0\uc774\ub2e4. \ub3c4\uc7a5\uc740 \uc791\uc740 \uc774\ub984\ud45c\uac00 \ub418\uc5b4 \uc18c\uc7a5 \uad00\uacc4\ub97c \ub4dc\ub7ec\ub0c8\ub2e4. \uc11c\uba85\uacfc \ub2ee\uc740 \uc810\ub3c4 \uc788\uc9c0\ub9cc \ud55c \ubc88 \uc0c8\uae34 \uae00\uc790\ub97c \uc5ec\ub7ec \uacf3\uc5d0 \ubc18\ubcf5\ud574 \ucc0d\uc744 \uc218 \uc788\ub2e4\ub294 \ucc28\uc774\uac00 \uc788\ub2e4. \ucc45\uc774 \uc5ec\ub7ec \uad8c\uc774\uc5b4\ub3c4 \uac19\uc740 \ub3c4\uc7a5\uc73c\ub85c \ud45c\uc2dc\ud560 \uc218 \uc788\ub2e4. \uc190\uc73c\ub85c \ub9e4\ubc88 \uac19\uc740 \uae00\uc790\ub97c \uc4f0\ub294 \uac83\uacfc\ub294 \ub2e4\ub978 \uc7ac\ubbf8\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc61b \ucc45\uc758 \ub3c4\uc7a5\uc774 \ubaa8\ub450 \uac19\uc740 \ubaa9\uc801\uc774\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc774 \uc774\uc57c\uae30\uc5d0\uc11c \uc0b4\ud3b4\ubcf4\ub294 \uac83\uc740 \uc18c\uc7a5\uc744 \ud45c\uc2dc\ud558\ub294 \uc7a5\uc11c\uc778 \ud55c \uc810\uc774\ub2e4. \uc778\uc7a5\uc758 \uc138\uacc4\uc5d0\ub294 \uad6d\uac00 \uc5c5\ubb34\uc6a9 \ub3c4\uc7a5\ubd80\ud130 \uac1c\uc778\uc774 \uc4f0\ub294 \ub3c4\uc7a5\uae4c\uc9c0 \uc5ec\ub7ec \uc885\ub958\uac00 \uc788\uc5c8\ub2e4. \uc774 \uc778\uc7a5\uc758 \uc0ac\uc6a9\uc790\uc5d0 \ub300\ud574 \ubc15\ubb3c\uad00\uc740 \u2018\ud5cc\uc885 \ucd94\uc815\u2019\uc774\ub77c\uace0 \uc801\uc5b4 \ub454\ub2e4. \ud5cc\uc885\uc774 \uc0ac\uc6a9\ud588\ub2e4\uace0 \ud655\uc815\ud558\ub294 \ub300\uc2e0, \ud604\uc7ac\uc758 \ud310\ub2e8\uc5d0 \uc5ec\uc9c0\ub97c \ub0a8\uae34 \uc124\uba85\uc774\ub2e4. \uc720\ubb3c \uc774\ub984\uc774 \ub610\ub837\ud558\uac8c \uc801\ud600 \uc788\uc5b4\ub3c4 \uadf8 \uc774\ub825\uc758 \ubaa8\ub4e0 \ubd80\ubd84\uc744 \uac19\uc740 \uc815\ub3c4\ub85c \uc544\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubb34\uc5c7\uc774 \uc0c8\uaca8\uc838 \uc788\ub294\uc9c0\uc640 \ub204\uac00 \uc2e4\uc81c\ub85c \uc0ac\uc6a9\ud588\ub294\uc9c0\ub294 \ub2e4\ub978 \uc9c8\ubb38\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \ubc15\ubb3c\uad00\uc758 \uc124\uba85\uc5d0\ub294 \ud5cc\uc885\uc774 \uc5ec\ub7ec \uc61b \uc778\uc7a5\uc744 \uc218\uc9d1\ud558\uace0 \uac10\uc0c1\ud588\uc73c\uba70 \uac1c\uc778\uc6a9 \uc778\uc7a5\ub3c4 \uc0ac\uc6a9\ud588\ub2e4\ub294 \uc774\uc57c\uae30\uac00 \ud568\uaed8 \ub098\uc628\ub2e4. \ub2e4\ub9cc \uadf8 \uc77c\ubc18\uc801\uc778 \ubc30\uacbd\uc774 \uc774 \ud55c \uc810\uc758 \uc0ac\uc6a9\uc790 \ucd94\uc815\uc744 \ud655\uc815\uc73c\ub85c \ubc14\uafb8\uc5b4 \uc8fc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc6b0\ub9ac\uac00 \ucc59\uae38 \uac83\uc740 \uc5b4\ub824\uc6b4 \uc655\uc2e4 \uacc4\ubcf4\ubcf4\ub2e4 \uc774 \uc791\uc740 \ub9d0\uc758 \ucc28\uc774\ub2e4. \u2018\ucd94\uc815\u2019\uc774\ub77c\ub294 \ub450 \uae00\uc790\ub97c \uadf8\ub300\ub85c \ub450\uc5b4\ub3c4 \ub3c4\uc7a5\uc744 \uad6c\uacbd\ud558\ub294 \uc7ac\ubbf8\ub294 \ucda9\ubd84\ud558\ub2e4. \uac19\uc740 \uc81c\ubaa9\uc758 \ucc45\uc774\ub77c\ub3c4 \uc5b4\ub290 \uc9d1\uc774\ub098 \uae30\uad00\uc5d0 \uc788\uc5c8\ub294\uc9c0\uc5d0 \ub530\ub77c \uc11c\ub85c \ub2e4\ub978 \ud754\uc801\uc774 \ub0a8\uc744 \uc218 \uc788\ub2e4. \uc7a5\uc11c\uc778\uc740 \uadf8 \ud754\uc801 \uac00\uc6b4\ub370 \ud558\ub098\ub2e4. \ubcf8\ubb38\uc744 \uc77d\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc800\uc790\uc758 \ubb38\uc7a5\uc774 \uba3c\uc800 \uc911\uc694\ud558\uc9c0\ub9cc, \ucc45\uc744 \ubb3c\uac74\uc73c\ub85c \uc0b4\ud3b4\ubcf4\ub294 \uc0ac\ub78c\uc740 \ub204\uac00 \uc18c\uc7a5\ud558\uace0 \uc5b4\ub5bb\uac8c \uc62e\uaca8 \uac14\ub294\uc9c0\ub3c4 \ubb3b\ub294\ub2e4. \ub3c4\uc7a5 \ud558\ub098\uac00 \uadf8 \ub450 \ubc88\uc9f8 \uc77d\uae30\ub97c \uc5f4\uc5b4 \uc900\ub2e4. \uc18c\uc720 \ud45c\uc2dc\uac00 \uc788\ub2e4\uace0 \ucc45\uc758 \ubaa8\ub4e0 \uc774\ub3d9 \uacbd\ub85c\uac00 \uace7 \uc644\uc131\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc778\uc7a5\uc774 \ucc0d\ud78c \ub54c\uc640 \uc774\ud6c4\uc758 \uc804\ub798\ub97c \ub2e4\ub978 \uc790\ub8cc\uc640 \ube44\uad50\ud574\uc57c \ud55c\ub2e4. \uadf8\ub798\ub3c4 \uc544\ubb34 \ud754\uc801 \uc5c6\ub294 \ud45c\uba74\uacfc\ub294 \uc9c8\ubb38\uc758 \ucd9c\ubc1c\uc810\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uac19\uc740 \uae00\uc790\uac00 \ub2e4\ub978 \ucc45\uc5d0\ub3c4 \ucc0d\ud600 \uc788\ub2e4\uba74 \uc5b4\ub5a4 \ubb36\uc74c\uc5d0 \uc18d\ud588\ub294\uc9c0 \uc0b4\ud3b4\ubcfc \uac00\ub2a5\uc131\uc774 \uc0dd\uae34\ub2e4. \uc791\uc740 \ud45c\uc9c0\uac00 \uc18c\uc7a5\uc758 \uad00\uacc4\ub97c \uc774\uc5b4 \uc8fc\ub294 \uac83\uc774\ub2e4. \uc778\uc7a5\uc740 \uc0c8\uaca8 \ub454 \uba74\uc5d0 \uc0c9\uc744 \ubb3b\ud600 \ub2e4\ub978 \ud45c\uba74\uc5d0 \ucc0d\ub294 \ub3c4\uad6c\ub2e4. \uc190\uc73c\ub85c \ub9e4\ubc88 \uac19\uc740 \uae00\uc790\ub97c \uc4f0\ub294 \ub300\uc2e0 \uac19\uc740 \ubaa8\uc591\uc744 \ubc18\ubcf5\ud574\uc11c \ub0a8\uae38 \uc218 \uc788\ub2e4. \ub3c4\uc7a5 \uc790\uccb4\uc758 \uc870\ud615\uacfc \ucc0d\ud78c \uc790\uad6d\uc740 \uc11c\ub85c \ub2e4\ub978 \ub300\uc0c1\uc73c\ub85c \ubcfc \uc218 \uc788\ub2e4. \ub3cc\ub85c \ub41c \ubb3c\uac74\uc744 \uac10\uc0c1\ud560 \ub54c\uc640 \ucc45\uc758 \uc5ec\ubc31\uc5d0\uc11c \uc778\uc601\uc744 \ucc3e\uc744 \ub54c \ub208\uc5ec\uaca8\ubcf4\ub294 \uc810\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uc0ac\uc9c4\uc73c\ub85c \uc778\uc7a5\uc744 \ub9cc\ub09c\ub2e4\uba74 \uc0c8\uaca8\uc9c4 \uba74\uacfc \ubab8\uccb4, \uc7a1\ub294 \ubd80\ubd84\uc744 \uad6c\ubcc4\ud574 \ubcfc \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uc774\ubbf8\uc9c0\uc5d0\uc11c \ubcf4\uc774\ub294 \uae00\uc790\ub97c \uadf8\ub300\ub85c \uc77d\uc5c8\ub2e4\uace0 \uc2e4\uc81c \ucc0d\ud614\uc744 \ub54c\uc758 \ubc29\ud5a5\uae4c\uc9c0 \uac19\uc740 \uac83\uc73c\ub85c \uc5ec\uaca8\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc0ac\uc6a9\ud574 \ub0a8\uae34 \uc790\uad6d\uacfc \ub3c4\uad6c\uc758 \uc0c1\ud0dc\ub97c \ud568\uaed8 \ud655\uc778\ud558\uba74 \ub354 \uc815\ud655\ud558\ub2e4. \ubb3c\uac74\uc758 \ubaa8\uc591\uc774 \ud589\ub3d9\uc744 \uac70\uccd0 \ub2e4\ub978 \uae30\ub85d\uc73c\ub85c \uc62e\uaca8 \uac00\ub294 \uad6c\uc870\ub97c \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc5f0\uacbd\uc7ac\uc5d0 \uc18c\uc7a5\ud55c \ucc45\uacfc \uc11c\ud654\uc5d0 \uc0ac\uc6a9\ud55c \uc778\uc7a5\uc774\ub77c\uace0 \uc124\uba85\ud55c\ub2e4. \uc774\ub984\uc740 \uc18c\uc7a5 \uacf5\uac04\uacfc \uad00\uacc4\ub97c \uc54c\ub824 \uc8fc\uc9c0\ub9cc \uac1c\ubcc4 \ucc45\ub9c8\ub2e4 \uc5b8\uc81c \ub204\uac00 \uc9c1\uc811 \ucc0d\uc5c8\ub294\uc9c0\uae4c\uc9c0 \uae30\ub85d\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uacf5\uac04\uc758 \uc774\ub984\uacfc \uc0ac\uc6a9\uc790\uc758 \uc774\ub984\ub3c4 \uc5b8\uc81c\ub098 \uac19\uc740 \uce35\uc758 \uc815\ubcf4\ub294 \uc544\ub2c8\ub2e4. \ud45c\uc2dc\uac00 \ubb34\uc5c7\uc744 \uac00\ub9ac\ud0a4\ub294\uc9c0 \uba3c\uc800 \uad6c\ubcc4\ud558\ub294 \ud3b8\uc774 \uc88b\ub2e4. \ud5cc\uc885\uc758 \uc778\uc7a5 \uc218\uc9d1\uacfc \uac10\uc0c1\uc774\ub77c\ub294 \ubc30\uacbd\uc740 \uc774 \ubb3c\uac74\uc744 \uc2dc\ub300 \uc548\uc5d0 \ub193\ub294 \ub370 \ub3c4\uc6c0\uc744 \uc900\ub2e4. \uadf8\ub7ec\ub098 \uc77c\ubc18\uc801\uc778 \ubc30\uacbd\ub9cc\uc73c\ub85c \ud55c \uc810\uc758 \uc0ac\uc6a9\uc790\uae4c\uc9c0 \ud655\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \ubc15\ubb3c\uad00\uc774 \ucd94\uc815\uc774\ub77c\uace0 \ub0a8\uae34 \ud45c\ud604\uc744 \uc720\uc9c0\ud558\uba74 \uc774\uc57c\uae30\uac00 \ub35c \uc7ac\ubbf8\uc788\uc5b4\uc9c0\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \ud655\uc2e4\ud55c \ubd80\ubd84\uacfc \ub0a8\uc740 \uc9c8\ubb38\uc744 \ud568\uaed8 \uac00\uc9c4 \ubb3c\uac74\uc73c\ub85c \ub354 \uc138\ubc00\ud558\uac8c \ubcf4\uac8c \ub41c\ub2e4. \uc624\ub298\uc758 \ucc45\uc5d0\ub3c4 \uc774\ub984\uc744 \uc801\uac70\ub098 \ucc45\uac08\ud53c\ub97c \ub123\uace0 \uba54\ubaa8\ub97c \ub0a8\uae34\ub2e4. \uc774\uac83\uc744 \uc655\uc2e4\uc758 \uc7a5\uc11c\uc778\uacfc \uac19\uc740 \uc81c\ub3c4\ub77c\uace0 \ud560 \uc218\ub294 \uc5c6\uc9c0\ub9cc, \ud14d\uc2a4\ud2b8\ub97c \ub2f4\uc740 \ubb3c\uac74\uc5d0 \uc0ac\uc6a9\uc790\uc758 \ud754\uc801\uc774 \ub354\ud574\uc9c4\ub2e4\ub294 \uc810\uc740 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \ud55c \uad8c\uc774 \uac19\uc740 \uc778\uc1c4 \ub0b4\uc6a9\ub9cc\uc73c\ub85c \uc124\uba85\ub418\uc9c0 \uc54a\ub294 \uc774\uc720\ub2e4. \uc77d\uace0 \ubcf4\uad00\ud558\uace0 \uac74\ub124\ub294 \ud589\ub3d9\uc774 \ucc45\uc758 \uc2dc\uac04\uc744 \ub298\ub9b0\ub2e4. \uc7a5\uc11c\uc778\uc744 \ubcf4\uc558\uc744 \ub54c\uc5d0\ub294 \uae00\uc790 \ubaa8\uc591\uc744 \uc0b4\ud540 \ub4a4 \uc5b4\ub514\uc5d0 \uc0ac\uc6a9\ud588\ub2e4\uace0 \uc124\uba85\ud558\ub294\uc9c0 \uc77d\uc5b4 \ubcf4\uc790. \uc778\uc7a5\uc758 \uc7ac\ub8cc\uc640 \uc0c8\uae40\uc740 \uc81c\uc791\uc744, \uc18c\uc7a5 \ud45c\uc2dc\ub294 \ucc45\uacfc \uc0ac\ub78c\uc758 \uad00\uacc4\ub97c \ubcf4\uc5ec \uc900\ub2e4. \ub3c5\uc11c\uc758 \uc5ed\uc0ac\ub294 \ubb34\uc5c7\uc744 \uc77d\uc5c8\ub294\uc9c0\ub9cc\uc774 \uc544\ub2c8\ub77c \uc5b4\ub5a4 \ubb3c\uac74\uc744 \ubaa8\uc73c\uace0 \uc54c\uc544\ubcf4\uba70 \ubcf4\uad00\ud588\ub294\uc9c0\ub3c4 \ud3ec\ud568\ud55c\ub2e4. \uc791\uc740 \ub3cc \ub3c4\uc7a5\uc5d0 \uadf8\ub7f0 \uc8fc\ubcc0\uc758 \uc2dc\uac04\uc774 \ub2f4\uaca8 \uc788\ub2e4. \ucc45\uc5d0\uc11c \uc77d\uc744\uac70\ub9ac\ub294 \ubcf8\ubb38\uc5d0\ub9cc \uc788\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc774\ub984\uc744 \uc801\uc740 \uc790\ub9ac, \uc18c\uc7a5 \ud45c\uc2dc, \ub204\uad70\uac00 \ub0a8\uae34 \uba54\ubaa8\ub3c4 \uadf8 \ucc45\uc774 \uc9c0\ub098\uc628 \uc2dc\uac04\uc744 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uc7a5\uc11c\uc778\uc744 \ubcf4\uba74 \uae00\uc790\ub97c \uc77d\ub294 \ubc29\uc2dd\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \ubb38\uc7a5\uc758 \ub73b\ub9cc \uc774\ud574\ud558\ub824\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \uc65c \uadf8 \uc790\ub9ac\uc5d0 \uadf8 \uc774\ub984\uc744 \ub0a8\uacbc\ub294\uc9c0 \uad81\uae08\ud574\uc9c4\ub2e4. \uac19\uc740 \ucc45\uc774\ub77c\ub3c4 \ub204\uad6c\uc758 \ucc45\uc7a5\uc5d0 \uc788\uc5c8\ub294\uc9c0\uac00 \ub610 \ud558\ub098\uc758 \uc774\uc57c\uae30\uac00 \ub420 \uc218 \uc788\ub2e4. \ub2e4\uc74c\uc5d0 \uc624\ub798\ub41c \ucc45\uc758 \uccab \uc7a5\uc5d0\uc11c \uc791\uc740 \uc778\uc7a5\uc744 \ubc1c\uacac\ud55c\ub2e4\uba74 \ubcf8\ubb38\uc73c\ub85c \ubc14\ub85c \ub118\uc5b4\uac00\uae30 \uc804\uc5d0 \uc7a0\uae50 \ubcf4\uc544\ub3c4 \uc88b\uaca0\ub2e4. \ucc45\uc5d0 \ub2f4\uae34 \uc774\uc57c\uae30 \uc606\uc5d0, \ucc45\uc744 \uac00\uc9c0\uace0 \uc788\ub358 \uc0ac\ub78c\uc758 \ud754\uc801\uc774 \ucc0d\ud600 \uc788\uc744\uc9c0\ub3c4 \ubaa8\ub978\ub2e4."}, {"id": "building-repair-letter", "title": "\uac74\ubb3c\uc744 \uace0\uce58\ub294 \uc77c\uc740 \uae00\ub85c\ub3c4 \ub0a8\uc558\ub2e4", "summary": "\ub0a1\uc740 \uac74\ubb3c\uc744 \uc190\ubcf4\ub294 \uc77c\uc5d0\ub3c4 \uae30\ub150\ubb38\uc774 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \uc885\uc774 \ud55c \uc7a5\uc5d0\uc11c \uc61b \uacf5\uc0ac\uc758 \uc0ac\uc815\uc744 \uc77d\uc5b4 \ubd05\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Architecture", "url": "stories/building-repair-letter/index.html", "image": "media/building-repair-letter.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00 \uc18c\uc7a5 \uc120\ub989 \uc815\uc790\uac01 \uc911\uc218 \uc0c1\ub7c9\ubb38\uc758 \uae00\uc528\uac00 \ubcf4\uc774\ub294 \uacf5\uac1c \uc0ac\uc9c4", "text": "\uac74\ubb3c\uc744 \uace0\uce58\ub294 \uc77c\uc740 \uae00\ub85c\ub3c4 \ub0a8\uc558\ub2e4 \uc120\ub989 \uc815\uc790\uac01 \uc0c1\ub7c9\ubb38\uc5d0 \ub2f4\uae34 \uc218\ub9ac\uc758 \uae30\ub85d \ub0a1\uc740 \uac74\ubb3c\uc744 \uc190\ubcf4\ub294 \uc77c\uc5d0\ub3c4 \uae30\ub150\ubb38\uc774 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \uc885\uc774 \ud55c \uc7a5\uc5d0\uc11c \uc61b \uacf5\uc0ac\uc758 \uc0ac\uc815\uc744 \uc77d\uc5b4 \ubd05\ub2c8\ub2e4. Architecture \ubb38\ud654 \uc624\ub798\ub41c \uac74\ubb3c \uc55e\uc5d0\uc11c\ub294 \uc5b8\uc81c \ucc98\uc74c \uc138\uc6e0\ub294\uc9c0\ubd80\ud130 \ubb3b\uac8c \ub41c\ub2e4. \ud558\uc9c0\ub9cc \ucc98\uc74c \uc9c0\uc740 \ub0a0\ub9cc\uc73c\ub85c \uac74\ubb3c\uc758 \uae34 \uc2dc\uac04\uc744 \ub2e4 \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \uae30\uc6b8\uc5b4\uc9c4 \uacf3\uc744 \ubc14\ub85c\uc7a1\uace0 \uc624\ub798\ub41c \ubd80\ubd84\uc744 \uace0\uce5c \uc2dc\uac04\ub3c4 \uc788\uc5c8\uae30 \ub54c\ubb38\uc774\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \u300c\uc120\ub989 \uc815\uc790\uac01 \uc911\uc218 \uc0c1\ub7c9\ubb38\u300d\uc740 \uadf8\ub7f0 \uc77c\uc744 \uae00\ub85c \ub0a8\uae34 \uc790\ub8cc\ub2e4. \uc0ac\uc9c4\uc73c\ub85c \ubcf4\uba74 \uc885\uc774 \uc704\uc5d0 \uae00\uc790\uac00 \uae38\uac8c \uc774\uc5b4\uc838 \uc788\ub2e4. \uac74\ubb3c\uc758 \uadf8\ub9bc\uc774\ub098 \uc124\uacc4\ub3c4\ub97c \uae30\ub300\ud588\ub2e4\uba74 \uc870\uae08 \ub2e4\ub978 \ubaa8\uc2b5\uc774\ub2e4. \uc774 \uae00\uc5d0\ub294 \ubb34\uc5c7\uc744 \uace0\ucce4\uace0 \uc65c \uc190\uc744 \ubcf4\uc544\uc57c \ud588\ub294\uc9c0\uac00 \ub2f4\uaca8 \uc788\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc774 \uc0c1\ub7c9\ubb38\uc774 1706\ub144 \uc120\ub989\uc758 \uc815\uc790\uac01\uc744 \uc911\uac74\ud560 \ub54c \uc791\uc131\ub418\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc624\ub79c \uc138\uc6d4 \ub3d9\uc548 \uc11d\ubb3c\uacfc \uc815\uc790\uac01\uc744 \ubcf4\uc218\ud574\uc57c \ud55c\ub2e4\ub294 \ud544\uc694\uac00 \uc81c\uae30\ub418\uc5c8\uace0, \uc2e4\uc81c\ub85c \uae30\uc6b8\uc5b4\uc9c4 \uac74\ubb3c\uc744 \ub2e4\uc2dc \uc190\ubcf4\uac8c \ub41c \uac83\uc774\ub2e4. \uae00\uc744 \uc9c0\uc740 \uc0ac\ub78c\uc740 \uc870\uc120 \ud6c4\uae30\uc758 \ubb38\uc2e0 \ucd5c\uc11d\ud56d\uc774\ub2e4. \uac19\uc740 \ub0b4\uc6a9\uc774 \uadf8\uc758 \ubb38\uc9d1\uc5d0\ub3c4 \uc2e4\ub824 \uc788\ub2e4\uace0 \ud55c\ub2e4. \ubc15\ubb3c\uad00\uc5d0 \ub0a8\uc740 \uc885\uc774\uc640 \ucc45 \uc18d\uc758 \uae00\uc774 \uc11c\ub85c \uc5f0\uacb0\ub41c\ub2e4. \uc0c1\ub7c9\ubb38\uc740 \uac74\ubb3c\uc744 \uc138\uc6b0\uac70\ub098 \uace0\uce58\ub294 \uc77c\uc744 \uae30\ub150\ud558\uace0 \uc798 \ub9c8\ubb34\ub9ac\ub418\uae30\ub97c \ubc14\ub77c\ub294 \uae00\uc774\ub2e4. \uc774 \uc790\ub8cc\uc758 \ubc88\uc5ed\uc5d0\uc11c\ub3c4 \uae30\ub465\uacfc \ucc98\ub9c8\uac00 \ube44\ubc14\ub78c\uc744 \uacaa\uc740 \uc0ac\uc815, \uc218\uc120\uc744 \ub2a6\ucd9c \uc218 \uc5c6\ub2e4\ub294 \ub73b\uc744 \uc77d\uc744 \uc218 \uc788\ub2e4. \uacf5\uc0ac\ub97c \uc544\ub984\ub2e4\uc6b4 \uc77c\ub85c\ub9cc \uafb8\ubbf8\ub294 \uae00\uc778 \uc904 \uc54c\uc558\ub294\ub370, \uc624\ub798\ub41c \uac74\ubb3c\uc774 \uacac\ub38c \uc628 \ubb38\uc81c\ub3c4 \ud568\uaed8 \ubcf4\uc778\ub2e4. \uc624\ub298\uc758 \uc218\ub9ac \uae30\ub85d\uc5d0\uc11c \ubc1c\uacac\ud560 \ubc95\ud55c \uc0ac\uc815\uc774 \uc61b \ubb38\uc7a5 \uc548\uc5d0\ub3c4 \ub4e4\uc5b4 \uc788\ub2e4. \uc124\uacc4\ub3c4\ub77c\uba74 \uce58\uc218\uc640 \uad6c\uc870\ub97c \uba3c\uc800 \ubcf4\uac8c \ub420 \uac83\uc774\ub2e4. \uc0c1\ub7c9\ubb38\uc5d0\uc11c\ub294 \uac74\ubb3c\uc744 \ub300\ud558\ub294 \ud0dc\ub3c4\uc640 \uacf5\uc0ac\uc758 \uc758\ubbf8\uac00 \uc55e\uc5d0 \ub098\uc628\ub2e4. \uac19\uc740 \uac74\ubb3c\uc744 \ub0a8\uae30\ub294 \uc790\ub8cc\uc5ec\ub3c4 \ub9e1\uc740 \uc5ed\ud560\uc774 \ub2e4\ub974\ub2e4. \uc774 \uae00\uc740 \uae30\uc874 \uc81c\ub3c4\ub97c \ub530\ub974\uba70 \ud130\ub97c \ub354 \ub113\ud788\uc9c0 \uc54a\uc558\ub2e4\ub294 \uc810, \uac10\ub3c5\uc744 \ub9e1\uaca8 \uc77c\uc744 \uc9c4\ud589\ud588\ub2e4\ub294 \uc810\ub3c4 \uc774\uc57c\uae30\ud55c\ub2e4. \uc774\ub7f0 \ub300\ubaa9\uc740 \ud654\ub824\ud55c \uc218\uc0ac \uc0ac\uc774\uc5d0 \ub193\uc5ec \uc788\uc5b4 \uadf8\ub0e5 \uc9c0\ub098\uce58\uae30 \uc27d\ub2e4. \ubb3c\ub860 \uc0c1\ub7c9\ubb38 \ud55c \ud3b8\ub9cc\uc73c\ub85c \uacf5\uc0ac\uc758 \ubaa8\ub4e0 \uacfc\uc815\uc744 \ubcf5\uc6d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub204\uac00 \uc5b4\ub290 \ub0a0 \uc5b4\ub5a4 \uc5f0\uc7a5\uc744 \ub4e4\uc5c8\ub294\uc9c0\uae4c\uc9c0 \uc54c\ub824\uc8fc\ub294 \uc791\uc5c5 \uc77c\uc9c0\ub294 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \uc65c \uacf5\uc0ac\uac00 \ud544\uc694\ud588\uace0 \uc5b4\ub5bb\uac8c \uc758\ubbf8\ub97c \ubd80\uc5ec\ud588\ub294\uc9c0 \ubcf4\uc5ec\uc8fc\ub294 \ucc3d\uc740 \ub41c\ub2e4. \ucc3d\uac74 \uc5f0\ub3c4\ub294 \uac74\ubb3c\uc758 \uc2dc\uc791\uc744 \uc54c\ub824 \uc8fc\uc9c0\ub9cc \uadf8 \ub4a4\uc758 \ube44\ubc14\ub78c\uacfc \uc190\uc9c8\uae4c\uc9c0 \ub9d0\ud574 \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc218\ub9ac\uc758 \uae30\ub85d\uc744 \ud568\uaed8 \uc77d\uc73c\uba74 \uc624\ub798\ub41c \ubaa8\uc2b5\uc774 \uc800\uc808\ub85c \uc774\uc5b4\uc9c4 \uac83\uc774 \uc544\ub2d8\uc744 \uc54c\uac8c \ub41c\ub2e4. \uae30\uc6b8\uc5b4\uc9c4 \ubd80\ubd84\uc744 \uc0b4\ud53c\uace0 \uacf5\uc0ac\ub97c \uacb0\uc815\ud558\uba70 \ub9e1\uae38 \uc0ac\ub78c\uc744 \uc815\ud558\ub294 \uc77c\uc774 \uc788\uc5c8\ub2e4. \uc9c0\uae08\uc758 \uad00\ub78c\uc790\ub294 \uadf8 \uc5ec\ub7ec \ubc88\uc758 \uc120\ud0dd \ub4a4\uc5d0 \ub0a8\uc740 \uac74\ubb3c\uc744 \ub9cc\ub098\ub294 \uc148\uc774\ub2e4. \uc0c1\ub7c9\ubb38\uc740 \uadf8 \uc120\ud0dd\uc744 \uae30\ub150\ud558\uace0 \uc758\ubbf8\ub97c \ubd80\uc5ec\ud558\ub294 \uae00\uc774\ub2e4. \ub0a1\uc740 \uacf3\uc744 \uace0\ucce4\ub2e4\ub294 \uc2e4\uc6a9\uc801\uc778 \uc0ac\uc815\uacfc, \uc624\ub798 \uc720\uc9c0\ub418\uae30\ub97c \ubc14\ub77c\ub294 \ub9c8\uc74c\uc774 \uac19\uc740 \ubb38\uc7a5 \uc548\uc5d0 \ub4e4\uc5b4\uac04\ub2e4. \uc624\ub298\uc758 \uacf5\uc0ac \ubcf4\uace0\uc11c\uc640 \uc5ed\ud560\uc774 \uc644\uc804\ud788 \uac19\uc9c0\ub294 \uc54a\uc9c0\ub9cc \uac74\ubb3c\uc744 \ub3cc\ubcf4\uc544\uc57c \ud560 \uc774\uc720\ub97c \uc124\uba85\ud55c\ub2e4\ub294 \uc810\uc5d0\uc11c \ub098\ub780\ud788 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ud130\ub97c \ub354 \ub113\ud788\uc9c0 \uc54a\uace0 \uae30\uc874\uc758 \uc81c\ub3c4\ub97c \ub530\ub790\ub2e4\ub294 \uc124\uba85\uc740 \uacf5\uc0ac\ub97c \ud655\uc7a5\uacfc \uacfc\uc2dc\ub85c\ub9cc \ubcf4\uc9c0 \uc54a\uac8c \ud55c\ub2e4. \uc798 \ubcf4\uc874\ud55c\ub2e4\ub294 \uc77c\uc774 \ubb34\uc5c7\uc744 \ub0a8\uae30\uace0 \ubb34\uc5c7\uc744 \ubc14\uafb8\ub294 \uc120\ud0dd\uc778\uc9c0 \ubb3b\uac8c \ud55c\ub2e4. \ub2e4\ub9cc \uc774 \ubb38\uc7a5\ub9cc\uc73c\ub85c \uc9c0\uae08\uc758 \ubaa8\ub4e0 \ubd80\uc7ac\uac00 \uadf8\ub54c\uc640 \ub611\uac19\ub2e4\ub294 \ub73b\uc73c\ub85c \ub113\ud790 \uc218\ub294 \uc5c6\ub2e4. \uae00\uc774 \ubcf4\uace0\ud558\ub294 \uacf5\uc0ac\uc758 \ubc29\uce68\uacfc \uc2e4\uc81c \ub0a8\uc740 \uac74\ucd95\uc740 \ud568\uaed8 \ub300\uc870\ud574\uc57c \ud560 \ub300\uc0c1\uc774\ub2e4. \ubb38\uc7a5 \uc18d\uc5d0\uc11c \uac10\ub3c5\uc744 \ub9e1\uacbc\ub2e4\ub294 \ubd80\ubd84\ub3c4 \uc9c0\ub098\uce58\uae30 \uc27d\ub2e4. \uacf5\uc0ac\ub294 \uc88b\uc740 \ub73b\ub9cc\uc73c\ub85c \uc9c4\ud589\ub418\uc9c0 \uc54a\ub294\ub2e4. \ud560 \uc77c\uc744 \ub098\ub204\uace0 \ucc45\uc784\uc744 \uc815\ud558\uba70 \uae30\uc874 \uc0c1\ud0dc\ub97c \ud655\uc778\ud558\ub294 \uacfc\uc815\uc774 \ud544\uc694\ud558\ub2e4. \ud654\ub824\ud55c \uc218\uc0ac \uc0ac\uc774\uc5d0 \uc774\ub7f0 \uc2e4\ubb34\uc801\uc778 \ub9d0\uc774 \ub193\uc774\uba74 \uc61b \uac74\ucd95\uc758 \uc5ed\uc0ac\uac00 \uc870\uae08 \ub354 \uc0ac\ub78c\uc758 \uc77c\ub85c \ub290\uaef4\uc9c4\ub2e4. \ubc15\ubb3c\uad00\uc758 \uc790\ub8cc\uc640 \ucd5c\uc11d\ud56d\uc758 \ubb38\uc9d1\uc740 \uac19\uc740 \ub0b4\uc6a9\uc744 \uc11c\ub85c \ub2e4\ub978 \uc790\ub9ac\uc5d0\uc11c \uc804\ud55c\ub2e4. \ud558\ub098\ub294 \ud2b9\uc815\ud55c \uac74\ucd95 \ud589\uc704\uc640 \uc5f0\uacb0\ub41c \ubb3c\uac74\uc774\uace0, \ub2e4\ub978 \ud558\ub098\ub294 \uae00\uc4f4\uc774\uc758 \uc800\uc220 \uac00\uc6b4\ub370 \ub193\uc778 \uae00\uc774\ub2e4. \ub0b4\uc6a9\uc774 \uacb9\uce5c\ub2e4\uace0 \ub450 \uc790\ub8cc\uc758 \uc9c8\ubb38\ub3c4 \ubaa8\ub450 \uac19\uc9c0\ub294 \uc54a\ub2e4. \uc885\uc774\uc758 \ud615\uc2dd\uacfc \uc804\ub798\ub97c \ubcfc \uc218\ub3c4 \uc788\uace0 \uc800\uc790\uc758 \uae00\uc4f0\uae30 \uc548\uc5d0\uc11c \uadf8 \ub73b\uc744 \uc77d\uc744 \uc218\ub3c4 \uc788\ub2e4. \uc11c\ub85c \ub2e4\ub978 \ud615\ud0dc\uc758 \uae30\ub85d\uc744 \ube44\uad50\ud558\uba74 \ube60\uc9c4 \uacf3\uc774\ub098 \ud45c\ud604\uc758 \ucc28\uc774\ub97c \ud655\uc778\ud560 \uae38\uc774 \uc0dd\uae34\ub2e4. \uc5ec\uae30\uc11c \uc2e4\uc81c \ud310\ubcf8 \ucc28\uc774\ub97c \uc870\uc0ac\ud574 \uc0c8 \uacb0\ub860\uc744 \ub0b8 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud55c \ub0b4\uc6a9\uc744 \uc5ec\ub7ec \uc790\ub8cc\uac00 \uc804\ud55c\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc5f0\uad6c\uc5d0 \uc5b4\ub5a4 \uac00\ub2a5\uc131\uc744 \uc8fc\ub294\uc9c0 \uc0dd\uac01\ud558\ub294 \uac83\uc774\ub2e4. \uc624\ub798\ub41c \uae00\uc740 \uc77d\ub294 \ubb38\uc7a5\uc774\uba74\uc11c \uc804\ub2ec\ub418\uc5b4 \uc628 \ubb3c\uac74\uc774\uae30\ub3c4 \ud558\ub2e4. \uac74\ubb3c \uc0ac\uc9c4\uc740 \ucc98\ub9c8\uc640 \uae30\ub465\uc758 \ubaa8\uc591\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc0c1\ub7c9\ubb38\uc740 \uc65c \uadf8 \uac74\ubb3c\uc744 \ub3cc\ubcfc \uac00\uce58\uac00 \uc788\ub2e4\uace0 \ubcf4\uc558\ub294\uc9c0\uc5d0 \uac00\uae4c\uc774 \uac04\ub2e4. \uc190\uc744 \ubcf4\uc544\uc57c \ud588\ub2e4\ub294 \uc0ac\uc815\uacfc \uc55e\uc73c\ub85c \uc798 \uc720\uc9c0\ub418\uae30\ub97c \ubc14\ub780\ub2e4\ub294 \ub9d0\uc774 \ud568\uaed8 \uc788\ub2e4. \uc790\ub8cc \ud558\ub098\uac00 \uac74\ucd95\uc758 \ubaa8\ub4e0 \uc815\ubcf4\ub97c \ub300\uc2e0\ud560 \uc218 \uc5c6\uae30\uc5d0 \uc11c\ub85c \ub2e4\ub978 \uae30\ub85d\uc744 \uc77d\ub294 \uc7ac\ubbf8\uac00 \uc0dd\uae34\ub2e4. \uc6d0\ubb38\uc744 \ubaa8\ub450 \ud574\ub3c5\ud558\uc9c0 \ubabb\ud558\ub354\ub77c\ub3c4 \ubc88\uc5ed\uc5d0\uc11c \ubc18\ubcf5\ub418\ub294 \uad00\uc2ec\uc744 \ucc3e\uc744 \uc218 \uc788\ub2e4. \ub0a1\uc74c\uacfc \uae30\uc6b8\uc5b4\uc9d0, \uae30\uc874 \uaddc\ubaa8\uc640 \ucc45\uc784, \uc774\ud6c4\uc758 \uc548\ub155 \uac19\uc740 \ub9d0\ub4e4\uc744 \ub530\ub77c\uac00 \ubcf4\uc790. \uc624\ub798\ub418\uc5c8\ub2e4\ub294 \uac10\ud0c4 \uc606\uc5d0 \ub204\uac00 \uc5b4\ub5bb\uac8c \uc624\ub798 \ub0a8\uae30\ub824 \ud588\ub294\uc9c0\ub77c\ub294 \uc9c8\ubb38\uc774 \ubd99\ub294\ub2e4. \uc218\ub9ac\uc758 \uc5ed\uc0ac\ub294 \uac74\ubb3c\uc758 \ubd80\uc218\uc801\uc778 \uc8fc\uc11d\uc774 \uc544\ub2c8\ub77c \ub0a8\uc544 \uc788\uac8c \ud55c \uc2dc\uac04\uc758 \uc77c\ubd80\ub2e4. \uc6d0\ubb38\uc758 \ud55c\uc790\ub97c \ubaa8\ub450 \uc77d\uc9c0 \ubabb\ud574\ub3c4 \uad1c\ucc2e\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc790\ub8cc\uc758 \uc124\uba85\uacfc \ubc88\uc5ed\uc744 \ud568\uaed8 \uacf5\uac1c\ud55c\ub2e4. \uae00\uc758 \uc81c\ubaa9\uacfc \uc791\uc131 \ubc30\uacbd\uc744 \uc54c\uace0 \ubcf4\uba74 \uc885\uc774 \uc704\uc758 \ube7d\ube7d\ud55c \uae00\uc528\ub3c4 \ub2e4\ub978 \uc778\uc0c1\uc744 \uc900\ub2e4. \uc624\ub798\ub41c \uac74\ubb3c\uc740 \ucc98\uc74c \ubaa8\uc2b5 \uadf8\ub300\ub85c \uc2dc\uac04\uc774 \uba48\ucd98 \ubb3c\uac74\ucc98\ub7fc \ubcf4\uc77c \ub54c\uac00 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \ubaa8\uc2b5\uc744 \uc774\uc5b4 \uac00\uae30 \uc704\ud574 \ub204\uad70\uac00\ub294 \uc190\uc744 \ubcf4\uc558\uace0, \ub54c\ub85c\ub294 \uadf8 \uc77c\uc744 \uae00\ub85c \ub0a8\uacbc\ub2e4. \ub2e4\uc74c\uc5d0 \uc720\uc11c \uae4a\uc740 \uac74\ubb3c\uc744 \uad6c\uacbd\ud55c\ub2e4\uba74 \ucc3d\uac74 \uc5f0\ub3c4 \uc606\uc758 \uc911\uc218\ub098 \uc911\uac74 \uae30\ub85d\ub3c4 \ud55c\ubc88 \uc0b4\ud3b4\ubcf4\uc790. \uc624\ub798\ub418\uc5c8\ub2e4\ub294 \ud55c\ub9c8\ub514 \uc548\uc5d0, \uc624\ub798 \ubc84\ud2f0\uac8c \ud558\ub824\ub358 \uc5ec\ub7ec \ubc88\uc758 \uc77c\uc774 \uc811\ud600 \uc788\ub2e4."}, {"id": "bulgaria-magura-human-figures", "title": "\ub3d9\uad74 \ubcbd\uc5d0\ub294 \ub3d9\ubb3c\ub9cc \uadf8\ub824\uc9c4 \uac83\uc774 \uc544\ub2c8\ub2e4", "summary": "\ubcbd\uba74\uc5d0 \ub0a8\uc740 \uc2e4\uc81c \uadf8\ub9bc\uc5d0\uc11c \uc0ac\ub78c\uacfc \ub3d9\ubb3c\uc758 \ud615\uc0c1\uc744 \ucc3e\uc544\ubd05\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Art", "url": "stories/bulgaria-magura-human-figures/index.html", "image": "media/bulgaria-magura-human-figures.jpg", "alt": "\ubd88\uac00\ub9ac\uc544 \ub9c8\uad6c\ub77c \ub3d9\uad74 \ubcbd\uba74\uc5d0 \uc0ac\ub78c\uacfc \ub3d9\ubb3c \ubaa8\uc591\uc774 \ud568\uaed8 \ub0a8\uc544 \uc788\ub294 \uc2e4\uc81c \ubcbd\ud654 \uc0ac\uc9c4.", "text": "\ub3d9\uad74 \ubcbd\uc5d0\ub294 \ub3d9\ubb3c\ub9cc \uadf8\ub824\uc9c4 \uac83\uc774 \uc544\ub2c8\ub2e4 \ubd88\uac00\ub9ac\uc544 \ub9c8\uad6c\ub77c \ub3d9\uad74\uc5d0\uc11c \ucc3e\ub294 \uc0ac\ub78c\uc758 \ubaa8\uc2b5 \ubcbd\uba74\uc5d0 \ub0a8\uc740 \uc2e4\uc81c \uadf8\ub9bc\uc5d0\uc11c \uc0ac\ub78c\uacfc \ub3d9\ubb3c\uc758 \ud615\uc0c1\uc744 \ucc3e\uc544\ubd05\ub2c8\ub2e4. Art \ubb38\ud654 \ub3d9\uad74 \ubcbd\ud654\ub77c\uace0 \ud558\uba74 \ucee4\ub2e4\ub780 \ub4e4\uc18c\ub098 \ub9d0\uc774 \uba3c\uc800 \ub5a0\uc624\ub97c \uc218 \uc788\ub2e4. \uadf8\ub7f0\ub370 \ubd88\uac00\ub9ac\uc544\uc758 \ub9c8\uad6c\ub77c \ub3d9\uad74 \uc0ac\uc9c4\uc744 \ubcf4\uba74 \uc0ac\ub78c\ucc98\ub7fc \ubcf4\uc774\ub294 \uc5ec\ub7ec \ud615\uc0c1\ub3c4 \ub3d9\ubb3c\ub4e4\uacfc \ud568\uaed8 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \ud314\uacfc \ub2e4\ub9ac\ub97c \ubc8c\ub9b0 \ub4ef\ud55c \uc5b4\ub450\uc6b4 \uc120\ub4e4\uc774\ub2e4. OpenStax \uad50\uc7ac\ub294 \uc774 \uadf8\ub9bc\ub4e4\uc744 \uc0ac\ub78c\uacfc \ub3d9\ubb3c\uc774 \ud568\uaed8 \ub4f1\uc7a5\ud558\ub294 \uc120\uc0ac\uc2dc\ub300 \ub3d9\uad74 \uadf8\ub9bc\uc73c\ub85c \uc18c\uac1c\ud55c\ub2e4. \uc774\ub984\uc744 \ubaa8\ub974\ub358 \ub3d9\uad74\uc5d0\uc11c\ub3c4 \uc2dc\uc120\uc744 \uc5b4\ub514\uc5d0 \ub450\ub290\ub0d0\uc5d0 \ub530\ub77c \ub2e4\ub978 \uc7a5\uba74\uc774 \uc5f4\ub9b0\ub2e4. \uc0ac\uc9c4 \uc18d \ud615\uc0c1\ub4e4\uc740 \uc624\ub298\uc758 \uc815\ubc00\ud55c \uc778\ubb3c\ud654\ucc98\ub7fc \uc5bc\uad74\uc744 \uc790\uc138\ud788 \ubcf4\uc5ec \uc8fc\uc9c0 \uc54a\ub294\ub2e4. \ub300\uc2e0 \ubab8\ud1b5\uacfc \ud314\ub2e4\ub9ac\ub97c \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \uac04\ub2e8\ud55c \ubaa8\uc591\uc774 \uc788\ub2e4. \ubb34\uc5c7\uc744 \uc0ac\ub78c\uc73c\ub85c \uc77d\uac8c \ub9cc\ub4dc\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\ub294 \uc7ac\ubbf8\uac00 \uc0dd\uae34\ub2e4. \uc606\uc5d0\ub294 \ubab8\uc758 \ud615\ud0dc\uac00 \ub2e4\ub978 \ub3d9\ubb3c \uadf8\ub9bc\ub4e4\ub3c4 \ub193\uc5ec \uc788\ub2e4. \uc120\uc744 \ud558\ub098\uc529 \ub530\ub77c\uac00\uba70 \uc11c\ub85c \ub2ee\uc740 \uac83\uacfc \ub2e4\ub978 \uac83\uc744 \uad6c\ubcc4\ud574 \ubcf4\uc790. \uba3c\uc800 \ub208\uc55e\uc758 \ud615\ud0dc\ub97c \ubcf4\ub294 \ub370 \ubcf5\uc7a1\ud55c \ud574\ub3c5\ud45c\uac00 \ud544\uc694\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \ud615\uc0c1\uc774 \ub450 \ud314\uc744 \uc62c\ub9b0 \uac83\ucc98\ub7fc \ubcf4\uc778\ub2e4\uace0 \uadf8 \uc0ac\ub78c\uc774 \ubb34\uc5c7\uc744 \ud558\ub358 \uc911\uc778\uc9c0\uae4c\uc9c0 \ubc14\ub85c \uc54c \uc218\ub294 \uc5c6\ub2e4. \uadf8\ub9bc\uc758 \ud615\ud0dc\ub97c \uc54c\uc544\ubcf4\ub294 \uc77c\uacfc \uadf8 \uc7a5\uba74\uc758 \ub73b\uc744 \ud655\uc815\ud558\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \uadf8\ub798\uc11c \uc774 \uae00\uc5d0\uc11c\ub294 \ud2b9\uc815 \uc758\ub840\ub098 \uc774\uc57c\uae30\ub97c \uc815\ub2f5\ucc98\ub7fc \ubd99\uc774\uc9c0 \uc54a\ub294\ub2e4. \uad50\uc7ac\uac00 \uc0ac\ub78c\uacfc \ub3d9\ubb3c\uc758 \uadf8\ub9bc\uc774\ub77c\uace0 \uc124\uba85\ud55c \ubc94\uc704 \uc548\uc5d0\uc11c \uc2e4\uc81c \uc0ac\uc9c4\uc744 \uc0b4\ud3b4\ubcf8\ub2e4. \uc624\ub798\ub41c \uadf8\ub9bc\uc744 \ubcfc \ub54c \ubaa8\ub974\ub294 \ubd80\ubd84\uc744 \ub0a8\uaca8 \ub450\ub294 \uac83\ub3c4 \ubcf4\ub294 \ubc29\ubc95\uc774\ub2e4. \uac04\ub2e8\ud55c \ud615\uc0c1\uc5d0\uc11c\ub3c4 \uc6b0\ub9ac\ub294 \uba38\ub9ac\uc640 \ubab8, \ud314\uacfc \ub2e4\ub9ac\ub97c \ucc3e\uc73c\ub824 \ud55c\ub2e4. \uc138\ubd80\uc801\uc778 \uc5bc\uad74\uc774 \uc5c6\uc5b4\ub3c4 \ubab8\uc758 \ubc29\ud5a5\uc774\ub098 \uc5ec\ub7ec \uc120\uc758 \uad00\uacc4\uac00 \uc0ac\ub78c\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud560 \uc218 \uc788\ub2e4. \uc0ac\uc9c4\uc744 \ucc9c\ucc9c\ud788 \ubcf4\uba74 \uc6b0\ub9ac\uac00 \ubb34\uc5c7\uc744 \uadfc\uac70\ub85c \uc778\ubb3c\ub85c \uc77d\ub294\uc9c0\ub3c4 \uc9c8\ubb38\ud558\uac8c \ub41c\ub2e4. \uadf8\ub9bc\uc744 \uc774\ud574\ud55c\ub2e4\ub294 \uc77c\uc774 \ud56d\uc0c1 \uc5bc\uad74\uc758 \ud45c\uc815\uc744 \uc815\ud655\ud788 \uc54c\uc544\ubcf4\ub294 \ub370\uc11c \uc2dc\uc791\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub3d9\ubb3c\ub85c \uc18c\uac1c\ub41c \ud615\uc0c1\uacfc \ub098\ub780\ud788 \ube44\uad50\ud558\uba74 \uc774 \ucc28\uc774\uac00 \ub354 \ubcf4\uc778\ub2e4. \uae38\uac8c \ubed7\uc740 \ubd80\ubd84\uacfc \ubab8\ud1b5\uc758 \ube44\ub840, \ub2e4\ub9ac\uac00 \ub193\uc778 \ubc29\ud5a5\uc744 \uc0b4\ud3b4\ubcf4\ub294 \uac83\uc774\ub2e4. \ub2e4\ub9cc \ube44\uad50\uac00 \uace7 \uc885\uc774\ub098 \uc778\ubb3c\uc758 \uc774\ub984\uc744 \uc0c8\ub85c \ud655\uc815\ud558\ub294 \uc791\uc5c5\uc740 \uc544\ub2c8\ub2e4. \uad50\uc7ac\uac00 \uc124\uba85\ud55c \ud070 \uad6c\ubd84 \uc548\uc5d0\uc11c \uc9c1\uc811 \ubcfc \uc218 \uc788\ub294 \ud615\ud0dc\ub97c \uc54c\uc544\ubcf4\ub824\ub294 \uad00\ucc30\uc5d0 \uac00\uae5d\ub2e4. \ub3d9\uad74 \ubcbd\uc740 \ubc18\ub4ef\ud558\uac8c \uc900\ube44\ud55c \uc885\uc774\uc758 \ud14c\ub450\ub9ac\uc640 \ub2e4\ub974\ub2e4. \uadf8\ub9bc\uc740 \uc790\uc5f0\uc758 \ud45c\uba74 \uc548\uc5d0\uc11c \ub2e4\ub978 \ubaa8\uc591\uacfc \uc774\uc6c3\ud55c\ub2e4. \uc9c0\uae08\uc758 \uc0ac\uc9c4\ub3c4 \uc804\uccb4 \uacf5\uac04 \uc911 \uc77c\ubd80\ub97c \uace8\ub77c \ubcf4\uc5ec \uc8fc\ubbc0\ub85c, \ud55c \ud654\uba74\uc758 \ub05d\uc744 \uc6d0\ub798 \uadf8\ub9bc \uc804\uccb4\uc758 \uacbd\uacc4\ub85c \uc624\ud574\ud558\uc9c0 \uc54a\uc544\uc57c \ud55c\ub2e4. \ubb34\uc5c7\uc774 \ud568\uaed8 \ubcf4\uc774\uace0 \ubb34\uc5c7\uc774 \uc0ac\uc9c4 \ubc16\uc5d0 \uc788\ub294\uc9c0 \uad6c\ubd84\ud560 \uc774\uc720\uac00 \uc788\ub2e4. \uc774\ub7f0 \ud45c\uba74\uc5d0\uc11c \ud615\uc0c1\ub4e4\uc744 \ubcf4\ub294 \uc77c\uc740 \ubc15\ubb3c\uad00 \uc561\uc790 \uc18d\uc758 \ud55c \uc791\ud488\uc744 \ubcf4\ub294 \uacbd\ud5d8\uacfc \ub2e4\ub97c \uc218 \uc788\ub2e4. \uac01\uac01\uc744 \ub530\ub85c \ub5bc\uc5b4 \ubcfc \uc218\ub3c4 \uc788\uace0 \uc11c\ub85c\uc758 \uac04\uaca9\uacfc \ubc29\ud5a5\uc744 \ubcfc \uc218\ub3c4 \uc788\ub2e4. \ub2e4\ub9cc \uc0ac\uc9c4\uc758 \uc870\uba85\uacfc \ucd2c\uc601 \ubc94\uc704\ub9cc\uc73c\ub85c \uc6d0\ub798 \ub3d9\uad74\uc5d0\uc11c \uc0ac\ub78c\ub4e4\uc774 \ubb34\uc5c7\uc744 \uc5bc\ub9c8\ub098 \ubcfc \uc218 \uc788\uc5c8\ub294\uc9c0 \ubaa8\ub450 \uc7ac\uad6c\uc131\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc774\ubbf8\uc9c0\uac00 \uc54c\ub824 \uc8fc\ub294 \ubd80\ubd84\uacfc \ud544\uc694\ud55c \ud604\uc7a5 \uc815\ubcf4\ub294 \ub098\ub25c\ub2e4. \ud314\uc744 \ub4e4\uc5c8\uac70\ub098 \ubab8\uc744 \uad7d\ud78c \ub4ef \ubcf4\uc774\uba74 \uc6b0\ub9ac\ub294 \uace7 \ud2b9\uc815\ud55c \uc7a5\uba74\uc758 \uc774\ub984\uc744 \ucc3e\ub294\ub2e4. \ucda4\uc774\ub098 \uc0ac\ub0e5, \uc758\uc2dd\uc774\ub77c\ub294 \ub9d0\uc774 \uba3c\uc800 \ub5a0\uc624\ub97c \uc218\ub3c4 \uc788\ub2e4. \uadf8\ub7ec\ub098 \ube44\uc2b7\ud55c \ubab8\uc9d3\ub3c4 \uc11c\ub85c \ub2e4\ub978 \uc0c1\ud669\uc5d0\uc11c \ub098\ud0c0\ub0a0 \uc218 \uc788\ub2e4. \ud615\ud0dc\uc758 \ub2ee\uc74c\ub9cc\uc73c\ub85c \ubb34\uc5c7\uc744 \uae30\ub150\ud558\uace0 \ub204\uac00 \uadf8\ub838\ub294\uc9c0\uae4c\uc9c0 \uc815\ud558\uba74 \uc124\uba85\uc774 \uc790\ub8cc\ub97c \ub118\uc5b4\uac08 \uc218 \uc788\ub2e4. \uadf8\ub798\uc11c \uc5ec\uae30\uc11c\ub294 \ubd88\ud655\uc2e4\ud568\uc744 \ub450\ub824\uc6cc\ud558\uae30\ubcf4\ub2e4 \uc9c8\ubb38\uc744 \ub098\ub204\uc5b4 \ubcf8\ub2e4. \uc5b4\ub5a4 \uc120\uc774 \ubcf4\uc774\ub294\uac00, \uc790\ub8cc\ub294 \uadf8\uac83\uc744 \ubb34\uc5c7\uc73c\ub85c \uc18c\uac1c\ud558\ub294\uac00, \uadf8 \uc774\uc0c1\uc758 \ud574\uc11d\uc5d0\ub294 \uc5b4\ub5a4 \uadfc\uac70\uac00 \ud544\uc694\ud55c\uac00. \uc774 \uc138 \ub2e8\uacc4\ub97c \uad6c\ubd84\ud558\uba74 \uc0c1\uc0c1\ud560 \uc5ec\uc9c0\uc640 \uc0ac\uc2e4\uc758 \ubc94\uc704\ub97c \ubaa8\ub450 \ub0a8\uae38 \uc218 \uc788\ub2e4. \uc815\ub2f5 \ud558\ub098\ub97c \ubd99\uc774\uc9c0 \uc54a\uc544\ub3c4 \uc624\ub798\ub41c \ubcbd\uc744 \ubcf4\ub294 \uc77c\uc740 \ucda9\ubd84\ud788 \ud48d\ubd80\ud558\ub2e4. \ud604\ub300\uc758 \uc815\ubc00\ud55c \uc778\ubb3c\ud654\ub97c \uae30\uc900\uc73c\ub85c\ub9cc \ubcf4\uba74 \ub2e8\uc21c\ud55c \uc120\uc740 \ubd80\uc871\ud558\uac8c \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uc801\uc740 \uc694\uc18c\ub85c \uc0ac\ub78c\uc774\ub098 \ub3d9\ubb3c\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4\ub294 \uc810\ub3c4 \ubcfc \uc218 \uc788\ub2e4. \uc774\uac83\uc744 \uc624\ub298\uc758 \uac04\ub2e8\ud55c \uadf8\ub9bc\uacfc \uace7\uc7a5 \uac19\uc740 \uc758\ubbf8\ub77c\uace0 \ub193\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \ube44\uc2b7\ud55c \ud45c\ud604 \uc218\ub2e8\uc774 \ubcf4\uc5ec\ub3c4 \uc0ac\uc6a9\ud55c \uc2dc\ub300\uc640 \uad00\uacc4\ub294 \ub2e4\ub97c \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uc0ac\uc9c4\uc744 \ub2e4\uc2dc \ubcfc \ub54c\uc5d0\ub294 \uba3c\uc800 \ud615\uc0c1 \ud558\ub098\ub97c \uace0\ub974\uace0 \ub2e4\uc74c\uc5d0 \uc8fc\ubcc0\uc758 \ubaa8\uc591\uc73c\ub85c \ub208\uc744 \ub113\ud600 \ubcf4\uc790. \uc5b4\ub290 \uac83\uc740 \ub2ee\uace0 \uc5b4\ub290 \uac83\uc740 \ub2e4\ub974\uac8c \ubcf4\uc774\ub294\uc9c0 \ucc9c\ucc9c\ud788 \ube44\uad50\ud558\uba74 \ub41c\ub2e4. \ub9c8\uad6c\ub77c \ub3d9\uad74\uc758 \uc2e4\uc81c \uc0ac\uc9c4\uc740 \uc0c1\uc0c1 \uc18d \uc120\uc0ac\uc2dc\ub300\ub97c \uc7a5\uc2dd\ud55c \uadf8\ub9bc\uacfc \uad6c\ubcc4\ub41c\ub2e4. \uc774\ub984\uc744 \ubaa8\ub974\ub294 \uc0ac\ub78c\ub4e4\uc774 \ub0a8\uae34 \ud45c\ud604 \uc55e\uc5d0\uc11c \uc624\ub298\uc758 \uc6b0\ub9ac\uac00 \uc5b4\ub5bb\uac8c \ubcf4\ub294\uc9c0 \ub3cc\uc544\ubcf4\uac8c \ud558\ub294 \uc790\ub8cc\ub2e4. \uc774\ubc88 \uc0ac\uc9c4\uc740 \ubcbd\ud654\ub97c AI\ub85c \ub2e4\uc2dc \uadf8\ub9b0 \uac83\uc774 \uc544\ub2c8\ub2e4. \ubc14\uc704\uc758 \ud45c\uba74\uacfc \uadf8 \uc704\uc5d0 \ub0a8\uc740 \uc120\uc744 \ud568\uaed8 \ubcf4\ub824\uba74 \uc2e4\uc81c \uc774\ubbf8\uc9c0\uac00 \ub354 \uc801\uc808\ud558\ub2e4. \ub9e4\ub048\ud55c \ud770 \uc885\uc774\uc5d0 \uc62e\uaca8 \ub193\uc558\uc744 \ub54c\uc640\ub294 \ub2e4\ub978 \uc778\uc0c1\uc774 \uc788\ub2e4. \ub3d9\uad74\uc758 \uc2dc\uac04\uc744 \ud55c \ubc88\uc5d0 \uc774\ud574\ud558\ub824 \uc560\uc4f8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc624\ub298\uc740 \ub3d9\ubb3c \uc606\uc5d0 \uc0ac\ub78c\uc774 \uc788\uc5c8\ub2e4\ub294 \uc810\ubd80\ud130 \uae30\uc5b5\ud574 \ubcf4\uc790. \uc624\ub798\ub41c \ubcbd\uba74\uc5d0\ub3c4 \uc138\uc0c1\uc744 \ubcf4\ub294 \uc0ac\ub78c\ubfd0 \uc544\ub2c8\ub77c, \uc790\uae30\uc640 \ub2ee\uc740 \ubab8\uc744 \ub0a8\uae30\ub294 \uc0ac\ub78c\uc758 \uc190\uae38\uc774 \uc788\uc5c8\ub2e4."}, {"id": "chardin-grace-before-meal", "title": "\uc2dd\uc0ac \uc804\uc758 \uae30\ub3c4 \u2014 \uc218\ud504\uac00 \uc2dd\uae30 \uc804, \uc7a0\uae50 \uba48\ucd98 \uc2dc\uac04", "summary": "\uc5b4\ub978\uacfc \ub450 \uc544\uc774, \uc2dd\uae30\uc640 \uc7a5\ub09c\uac10\uc758 \uad00\uacc4\ub85c 18\uc138\uae30 \uc77c\uc0c1\uc758 \ud68c\ud654\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Art", "url": "stories/chardin-grace-before-meal/index.html", "image": "media/chardin-grace-before-meal.jpg", "alt": "\uc0e4\ub974\ub315\uc758 \uc2dd\uc0ac \uc804\uc758 \uae30\ub3c4. \uc2dd\ud0c1 \uacc1\uc758 \uc5b4\ub978\uacfc \ub450 \uc544\uc774, \uc218\ud504 \uadf8\ub987\uacfc \uc758\uc790 \ub4a4\uc758 \uc791\uc740 \ubd81\uc774 \ubcf4\uc785\ub2c8\ub2e4.", "text": "\uc2dd\uc0ac \uc804\uc758 \uae30\ub3c4 \u2014 \uc218\ud504\uac00 \uc2dd\uae30 \uc804, \uc7a0\uae50 \uba48\ucd98 \uc2dc\uac04 \uc0e4\ub974\ub315\uc758 \uc791\uc740 \uc2dd\ud0c1\uc5d0\uc11c \uadf8\ub9bc\uc758 \uc911\uc2ec\uc744 \ucc3e\ub294 \ubc29\ubc95 \uc5b4\ub978\uacfc \ub450 \uc544\uc774, \uc2dd\uae30\uc640 \uc7a5\ub09c\uac10\uc758 \uad00\uacc4\ub85c 18\uc138\uae30 \uc77c\uc0c1\uc758 \ud68c\ud654\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Art \ubb38\ud654 \uc218\ud504\ub97c \ub2f4\uc73c\ub824\ub358 \uc5b4\ub978\uc774 \uace0\uac1c\ub97c \ub3cc\ub9b0\ub2e4. \uc2dd\ud0c1 \uacc1\uc758 \ub450 \uc544\uc774\ub294 \uc190\uc744 \ubaa8\uc73c\uace0 \uc788\ub2e4. \uc544\uc8fc \uc7a0\uae50 \uba48\ucd98 \uc2dd\uc0ac \uc2dc\uac04\uc774\ub2e4. \ud070 \uc5ed\uc0ac\uc801 \uc0ac\uac74\ub3c4 \uae30\uc801\ub3c4 \uc5c6\ub294\ub370 \uc7a5\ubc14\ud2f0\uc2a4\ud2b8 \uc2dc\uba54\uc639 \uc0e4\ub974\ub315\uc740 \uc774 \uc21c\uac04\uc744 \ud55c \uc7a5\uc758 \uadf8\ub9bc\uc73c\ub85c \ub0a8\uacbc\ub2e4. \u3008\uc2dd\uc0ac \uc804\uc758 \uae30\ub3c4\u3009\ub294 \ub204\uac00 \ubb34\uc5c7\uc744 \ud558\ub294\uc9c0 \ube44\uad50\uc801 \uc27d\uac8c \uc54c \uc218 \uc788\ub294 \uc791\ud488\uc774\ub2e4. \uadf8\ub807\ub2e4\uace0 \uccab\ub208\uc5d0 \ub0b4\uc6a9\uc744 \uc54c\uc544\ubcf4\uc558\uc73c\ub2c8 \ub2e4 \ubcf4\uc558\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc0ac\ub78c\uacfc \ubb3c\uac74\uc774 \uc5b4\ub5bb\uac8c \ub193\uc600\ub294\uc9c0 \uc0b4\ud53c\uba74 \ud3c9\ubc94\ud55c \uc7a5\uba74\uc758 \uc9dc\uc784\uc774 \ubcf4\uc778\ub2e4. \ud504\ub791\uc2a4\uc5b4 \uc81c\ubaa9 Le B\u00e9n\u00e9dicit\u00e9\ub294 \uc2dd\uc0ac \uc804\uc5d0 \ub4dc\ub9ac\ub294 \uac10\uc0ac\uc758 \uae30\ub3c4\ub97c \uac00\ub9ac\ud0a8\ub2e4. \uc544\uc774\ub4e4\uc774 \uc190\uc744 \ubaa8\uc740 \uc774\uc720\ub97c \uc54c\ub824 \uc8fc\ub294 \ub2e8\uc11c\ub2e4. \uc7a5\uba74\uc744 \uc774\ud574\ud558\ub294 \ub370 \uae34 \uc885\uad50\uc801 \ubc30\uacbd\uc9c0\uc2dd\uc774 \ud544\uc694\ud558\uc9c0\ub294 \uc54a\ub2e4. \uc74c\uc2dd\uc774 \ub098\uc624\uae30 \uc804 \ud568\uaed8 \uc7a0\uc2dc \uba48\ucd94\ub294 \uc2dc\uac04\uc73c\ub85c \ub4e4\uc5b4\uac00\uba74 \ub41c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc774 \uc7a5\uba74\uc744 \ubaa8\ub4e0 \uc720\ub7fd \uac00\uc815\uc758 \uacf5\ud1b5\ub41c \ubaa8\uc2b5\uc73c\ub85c \uc77c\ubc18\ud654\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \ud2b9\uc815 \uc2dc\ub300\uc758 \uac00\uc815\uc0dd\ud65c\uc744 \uc18c\uc7ac\ub85c \ud654\uac00\uac00 \uad6c\uc131\ud55c \uadf8\ub9bc\uc774\ub2e4. \uc61b \uc77c\uc0c1\uc758 \ud55c \ub2e8\uba74\uc744 \ubcf4\uc5ec \uc900\ub2e4\ub294 \uc810\uacfc, \ub2f9\uc2dc \ubaa8\ub4e0 \uc0ac\ub78c\uc758 \uc0dd\ud65c\uc744 \uadf8\ub300\ub85c \uc99d\uba85\ud55c\ub2e4\ub294 \uc8fc\uc7a5\uc740 \ub2e4\ub974\ub2e4. \uc5b4\ub978\uc758 \uc190\uc740 \uc74c\uc2dd\uc744 \ub2f4\ub294 \uc77c\uc5d0 \uac00\uae4c\uc774 \uc788\uace0 \uc5bc\uad74\uc740 \uc544\uc774\ub4e4 \ucabd\uc73c\ub85c \ud5a5\ud55c\ub2e4. \ubab8 \uc804\uccb4\ub97c \ud55c \ubc88\uc5d0 \ubcf4\uba74 \ub3cc\ubd04\uc774 \ub2e8\uc21c\ud55c \ubb3c\uac74\uc758 \uc804\ub2ec\ub9cc\uc740 \uc544\ub2c8\ub77c\ub294 \ub290\ub08c\uc744 \ubc1b\uc744 \uc218 \uc788\ub2e4. \uc74c\uc2dd\uc744 \ub0b4\uba74\uc11c \uc544\uc774\uac00 \ubb34\uc5c7\uc744 \ud558\ub294\uc9c0\ub3c4 \uc0b4\ud53c\ub294 \uac83\uc774\ub2e4. \uc774\uac83\uc744 \ud2b9\uc815 \uc778\ubb3c\uc758 \uc18d\ub9c8\uc74c\uc744 \uc6b0\ub9ac\uac00 \uc815\ud655\ud788 \uc548\ub2e4\ub294 \ub73b\uc73c\ub85c \ubc1b\uc544\ub4e4\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \uc190\uacfc \uc2dc\uc120\uc774 \uc11c\ub85c \ub2e4\ub978 \ubc29\ud5a5\uc758 \uad00\uacc4\ub97c \ub9cc\ub4e0\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uad00\ucc30\ud558\uba74 \ub41c\ub2e4. \ud55c \ubab8 \uc548\uc758 \uc791\uc740 \ubc29\ud5a5 \ucc28\uc774\uac00 \uc0ac\ub78c \uc0ac\uc774\uc758 \uc5f0\uacb0\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc544\uc774\ub4e4\uc758 \ud06c\uae30\uc640 \uc549\uc740 \uc790\uc138, \ubc14\ub77c\ubcf4\ub294 \ubc29\ud5a5\uc5d0\ub294 \ucc28\uc774\uac00 \uc788\ub2e4. \ub450 \uc0ac\ub78c\uc744 \ud55c \ub369\uc5b4\ub9ac\ub85c \ubcf4\uace0 \u2018\uae30\ub3c4\ud558\ub294 \uc544\uc774\ub4e4\u2019\uc774\ub77c\uace0\ub9cc \ubd80\ub974\uba74 \uc774\ub7f0 \uc791\uc740 \ucc28\uc774\ub97c \uc9c0\ub098\uce58\uae30 \uc27d\ub2e4. \uac01\uc790\uc758 \uc5bc\uad74\uacfc \uc190\uc744 \ub530\ub85c \ubcf8 \ub4a4 \ub2e4\uc2dc \ud568\uaed8 \ubcf4\uba74 \uad00\uacc4\uac00 \uc120\uba85\ud574\uc9c4\ub2e4. \uc5b4\ub9b0\uc544\uc774\uc5d0\uac8c \uc2dd\uc0ac \uc608\uc808\uc744 \uac00\ub974\uce58\ub294 \uc2dc\uac04\ucc98\ub7fc \uc77d\uc744 \uc218\ub3c4 \uc788\uc9c0\ub9cc, \uadf8\ub9bc\uc774 \ubaa8\ub4e0 \ub300\ud654\ub97c \uc9c1\uc811 \uc54c\ub824 \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub204\uac00 \ubc29\uae08 \ubb34\uc2a8 \ub9d0\uc744 \ud588\ub294\uc9c0 \ud655\uc815\ud558\uae30\ubcf4\ub2e4 \uc9c0\uae08 \ub208\uc55e\uc5d0 \ub0a8\uc740 \uc790\uc138\ub97c \ubcf4\uc790. \ud68c\ud654\uc758 \uc774\uc57c\uae30\ub294 \ub4e4\ub9ac\uc9c0 \uc54a\ub294 \ub300\uc0ac\ub97c \ubc18\ub4dc\uc2dc \ub9cc\ub4e4\uc5b4 \ub123\uc5b4\uc57c\ub9cc \uc0dd\uae30\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc791\uc740 \ubd81\uc740 \uc774 \ubc29\uc774 \uc5c4\uc219\ud55c \uae30\ub3c4\ub9cc\uc744 \uc704\ud55c \uacf3\uc774 \uc544\ub2c8\ub77c \uc544\uc774\uac00 \uc0dd\ud65c\ud558\ub294 \uacf5\uac04\uc784\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \uc544\uc774\ub4e4\uc740 \uc2dd\uc0ac\ud558\uae30 \uc804\uc5d0 \ub2e4\ub978 \ub180\uc774\ub97c \ud588\uc744 \uc218\ub3c4 \uc788\ub2e4. \ub2e4\ub9cc \uc2e4\uc81c\ub85c \uc5b8\uc81c \ubd81\uc744 \ucce4\ub294\uc9c0\uae4c\uc9c0 \uadf8\ub9bc\uc774 \uc54c\ub824 \uc8fc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubb3c\uac74\uc774 \ub354\ud558\ub294 \uc0dd\ud65c\uc758 \uae30\uc6b4\uc744 \ub290\uaef4 \ubcf4\uba74 \ucda9\ubd84\ud558\ub2e4. \uc2dd\ud0c1\uacfc \uc758\uc790, \uadf8\ub987\ub4e4\uc740 \ubc30\uacbd\uc758 \ube48\uce78\uc744 \ucc44\uc6b0\ub824\uace0 \uc544\ubb34\ub807\uac8c\ub098 \ub193\uc778 \uac83\ucc98\ub7fc \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ubab8\uacfc \ubb3c\uac74 \uc0ac\uc774\uc758 \uac70\ub9ac\uac00 \uc7a5\uba74\uc758 \ud06c\uae30\ub97c \uc815\ud55c\ub2e4. \ubc29 \uc804\uccb4\uac00 \uac70\ub300\ud55c \ubb34\ub300\uac00 \uc544\ub2c8\ub77c \uc11c\ub85c \uc190\uacfc \ub208\uae38\uc774 \ub2ff\ub294 \uc790\ub9ac\ub85c \ub2e4\uac00\uc628\ub2e4. \ubc1d\uc740 \uc2dd\ud0c1\ubcf4\ub294 \ud654\uba74\uc5d0\uc11c \ub113\uc740 \uc790\ub9ac\ub97c \ucc28\uc9c0\ud55c\ub2e4. \uc8fc\ubcc0\uc758 \uc5b4\ub450\uc6b4 \ubd80\ubd84\uacfc \ube44\uad50\ud558\uba74 \uc2dc\uc120\uc774 \uc790\uc5f0\uc2a4\ub7fd\uac8c \uc2dd\uc0ac\ud558\ub294 \uc790\ub9ac\ub85c \ubaa8\uc778\ub2e4. \uc778\ubb3c\uc758 \uc637\uacfc \uadf8\ub987\uc744 \ubcfc \ub54c\ub3c4 \uadf8 \ubc1d\uc740 \ubc14\ud0d5\uc774 \uc5b4\ub5a4 \uc5ed\ud560\uc744 \ud558\ub294\uc9c0 \ud568\uaed8 \uc0b4\ud3b4\ubcf4\uc790. \uc0c9\uc744 \ud654\ub824\ud568\uc758 \uc815\ub3c4\ub85c\ub9cc \ud3c9\uac00\ud558\uc9c0 \uc54a\uc73c\uba74 \uc774 \uadf8\ub9bc\uc758 \uc7ac\ubbf8\uac00 \ucee4\uc9c4\ub2e4. \ubb34\uc5c7\uc774 \uc55e\uc73c\ub85c \ub2e4\uac00\uc624\uace0 \ubb34\uc5c7\uc774 \ub4a4\ub85c \ubb3c\ub7ec\ub098\ub294\uc9c0, \ub2e4\ub978 \ubb3c\uac74\uc758 \uc0c9\uc774 \uacc1\uc5d0 \ub193\uc77c \ub54c \uc5b4\ub5bb\uac8c \ub290\uaef4\uc9c0\ub294\uc9c0 \ubcfc \uc218 \uc788\ub2e4. \uc815\ubb3c\ud654\ub97c \ub9ce\uc774 \uadf8\ub9b0 \uc0e4\ub974\ub315\uc758 \uadf8\ub9bc\uc5d0\uc11c \uc0ac\ub78c\uacfc \uc0ac\ubb3c\uc740 \uc11c\ub85c\uc758 \uc790\ub9ac\ub97c \ub9cc\ub4e0\ub2e4. \uc0e4\ub974\ub315\uc740 1699\ub144\uc5d0 \ud0dc\uc5b4\ub098 1779\ub144\uc5d0 \uc138\uc0c1\uc744 \ub5a0\ub09c \ud504\ub791\uc2a4 \ud654\uac00\ub2e4. \uc774 \uc791\ud488\uc5d0\uc11c\ub294 \ud654\ub824\ud55c \uc758\uc2dd\uc774\ub098 \uc601\uc6c5\uc758 \ud589\ub3d9 \ub300\uc2e0 \uc2dd\uc0ac \uc804\uc758 \uac00\uc871\uacfc \uc0dd\ud65c \ubb3c\uac74\uc774 \uc911\uc2ec\uc774 \ub41c\ub2e4. \ubb34\uc5c7\uc774 \uadf8\ub9bc\uc758 \uc911\uc694\ud55c \uc8fc\uc81c\uac00 \ub420 \uc218 \uc788\ub294\uc9c0 \uc0dd\uac01\ud558\uac8c \ud558\ub294 \uc120\ud0dd\uc774\ub2e4. \uadf8\ub7ec\ub098 \uc18c\ubc15\ud574 \ubcf4\uc774\ub294 \uc7a5\uba74\uc774\ub77c\uace0 \ud574\uc11c \ud654\uac00\uac00 \uc190\uc744 \ub300\uc9c0 \uc54a\uc740 \uc0dd\ud65c \uc0ac\uc9c4\ucc98\ub7fc \ubcfc \uc218\ub294 \uc5c6\ub2e4. \uac01\uc790\uc758 \uc790\uc138\uc640 \ube5b, \ubb3c\uac74\uc758 \uac04\uaca9\uc740 \ud654\uba74\uc758 \uc77c\ubd80\ub2e4. \ud3c9\ubc94\ud55c \uc18c\uc7ac\uc640 \uc138\uc2ec\ud55c \uad6c\uc131\uc740 \ubc18\ub300\ub9d0\uc774 \uc544\ub2c8\ub2e4. \uc624\ud788\ub824 \uc775\uc219\ud55c \uc21c\uac04\uc774 \uc624\ub798 \ubcf4\uac8c \ub418\ub294 \uadf8\ub9bc\uc73c\ub85c \ubc14\ub00c\ub294 \uc774\uc720\uac00 \uadf8 \uc548\uc5d0 \uc788\ub2e4. \uc61b \ub3c4\ub85d\uc740 \uc774 \uc8fc\uc81c\uc758 \uc5ec\ub7ec \ud310\ubcf8\uc744 \uc5b8\uae09\ud55c\ub2e4. \ub530\ub77c\uc11c \uac19\uc740 \uc7a5\uba74\uc774 \ubcf4\uc774\ub294 \ub2e4\ub978 \uc0ac\uc9c4\uc744 \ub9cc\ub098\ub354\ub77c\ub3c4 \ubaa8\ub450 \uc9c0\uae08 \ub3c4\ud310\uacfc \uc644\uc804\ud788 \uac19\uc740 \uadf8\ub9bc\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc774 \uae00\uc5d0\uc11c \ud568\uaed8 \ubcf4\ub294 \uac83\uc740 \ub8e8\ube0c\ub974 \ub3c4\ub85d\uc5d0 \uc2e4\ub9b0 \uc18c\uc7a5\ubcf8\uc758 \uc0c9\ucc44 \uc7ac\ud604 \uc790\ub8cc\ub2e4. \uc61b \uc778\uc1c4\uc758 \uc0c9\uacfc \uc138\ubd80\uac00 \ud604\uc7ac\uc758 \uc2e4\ubb3c\uc744 \uadf8\ub300\ub85c \ubcf4\uc5ec \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub3c4\ud310\uc744 \ubcf4\uba74\uc11c \uc815\ud655\ud55c \ud45c\uba74\uc774\ub098 \uc2e4\uc81c \ud06c\uae30\ub97c \ub9c8\uc74c\ub300\ub85c \ucd94\uc815\ud558\uae30\ubcf4\ub2e4 \uc138 \uc0ac\ub78c\uc758 \ubc30\uce58\uc640 \uc2dd\ud0c1\uc758 \ubc1d\uae30, \uc8fc\ubcc0 \ubb3c\uac74\uc758 \uad00\uacc4\ub97c \uc0b4\ud3b4\ubcf4\uba74 \uc88b\ub2e4. \ub9e4\uccb4\uc758 \ud55c\uacc4\ub97c \uc54c\uc544\ub3c4 \uac10\uc0c1\uc758 \uae38\uc740 \ucda9\ubd84\ud788 \ub0a8\ub294\ub2e4. \uc624\ub298\uc758 \uac00\uc871 \uc2dd\uc0ac\uc640 \uc774 \uc7a5\uba74\uc740 \uc637\ub3c4 \uc74c\uc2dd\ub3c4 \uc0dd\ud65c \ubc29\uc2dd\ub3c4 \ub2e4\ub974\ub2e4. \uadf8 \ucc28\uc774\ub97c \uc9c0\uc6b4 \ucc44 \u2018\uc608\ub098 \uc9c0\uae08\uc774\ub098 \ub611\uac19\ub2e4\u2019\uace0 \ub05d\ub0b4\uae30\ubcf4\ub2e4, \ub2ec\ub77c\uc9c4 \uac83\uacfc \uc54c\uc544\ubcfc \uc218 \uc788\ub294 \uac83\uc744 \ud568\uaed8 \ubcf4\uba74 \uc88b\ub2e4. \ub204\uad70\uac00 \uc74c\uc2dd\uc744 \ub0b4\uace0 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc190\uc9d3\uc744 \uc0b4\ud53c\ub294 \uad00\uacc4\ub294 \ub0af\uc120 \uc61b \ubc29 \uc548\uc5d0\uc11c\ub3c4 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uae30\ub3c4\ud558\ub294 \uc7a5\uba74\uc744 \ud655\uc778\ud588\ub2e4\uba74, \ub450 \ubc88\uc9f8\uc5d0\ub294 \uc74c\uc2dd\uacfc \uc544\uc774\ub97c \ud568\uaed8 \ubcf4\ub294 \uc5b4\ub978\uc758 \uc5bc\uad74\uc744, \uc138 \ubc88\uc9f8\uc5d0\ub294 \uc7a5\ub09c\uac10\uacfc \uc2dd\uae30\ub97c \ucc3e\uc544\ubcf4\uc790. \ud070 \uc0ac\uac74\uc774 \uc5c6\ub294 \uadf8\ub9bc\ub3c4 \uc2dc\uc120\uc744 \uc62e\uae38 \ub54c\ub9c8\ub2e4 \uc0c8\ub85c\uc6b4 \uc911\uc2ec\uc744 \ub0b4\uc5b4 \uc900\ub2e4. \uc2dd\uc0ac\uac00 \uc2dc\uc791\ub418\uae30 \uc804\uc758 \uc7a0\uae50\uc774 \uc774\ub807\uac8c \uae34 \uac10\uc0c1\uc774 \ub420 \uc218 \uc788\ub2e4."}, {"id": "chicago-floating-stair-detail", "title": "\uacc4\ub2e8 \uc544\ub798\uc758 \uc791\uc740 \ud2c8\uc774 \uac74\ubb3c\uc744 \uac00\ubccd\uac8c \ub9cc\ub4e0\ub2e4", "summary": "\ubcbd\uacfc \uacc4\ub2e8, \uc758\uc790 \uc544\ub798\uc758 \uac00\ub290\ub2e4\ub780 \ud2c8\uc5d0 \uc8fc\ubaa9\ud569\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Architecture", "url": "stories/chicago-floating-stair-detail/index.html", "image": "media/chicago-floating-stair-detail.jpg", "alt": "\uacc4\ub2e8 \uc544\ub798\uc758 \uc791\uc740 \ud2c8\uc774 \uac74\ubb3c\uc744 \uac00\ubccd\uac8c \ub9cc\ub4e0\ub2e4\uc758 \uc8fc\uc81c\ub97c \ud45c\ud604\ud55c AI \uc124\uba85\uc6a9 \uc0bd\ud654. \uc2e4\uc81c \uc791\ud488\uc774\ub098 \uac74\ucd95\ubb3c\uc744 \uadf8\ub300\ub85c \uc7ac\ud604\ud55c \uc774\ubbf8\uc9c0\uac00 \uc544\ub2d9\ub2c8\ub2e4.", "text": "\uacc4\ub2e8 \uc544\ub798\uc758 \uc791\uc740 \ud2c8\uc774 \uac74\ubb3c\uc744 \uac00\ubccd\uac8c \ub9cc\ub4e0\ub2e4 \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc5d0\uc11c \ubc14\ub2e5\uc744 \ud55c \ubc88 \ub354 \ubcf4\ub294 \ubc29\ubc95 \ubcbd\uacfc \uacc4\ub2e8, \uc758\uc790 \uc544\ub798\uc758 \uac00\ub290\ub2e4\ub780 \ud2c8\uc5d0 \uc8fc\ubaa9\ud569\ub2c8\ub2e4. Architecture \ubb38\ud654 \ud070 \uac74\ubb3c\uc744 \ubcf4\uace0 \uac00\ubccd\ub2e4\ub294 \ub290\ub08c\uc744 \ubc1b\uc744 \ub54c\uac00 \uc788\ub2e4. \uc2e4\uc81c \ubb34\uac8c\uac00 \uac00\ubcbc\uc6b8 \ub9ac\ub294 \uc5c6\ub294\ub370 \ubcbd\uc774\ub098 \uacc4\ub2e8\uc774 \uc0b4\uc9dd \ub5a0 \uc788\ub294 \uac83\ucc98\ub7fc \ubcf4\uc774\ub294 \uc21c\uac04\uc774\ub2e4. \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc758 \ubaa8\ub358 \uc719 \uc124\uba85\uc5d0\ub294 \uadf8 \ub290\ub08c\uc744 \ub9cc\ub4dc\ub294 \uc791\uc740 \ud2c8\uc774 \ub4f1\uc7a5\ud55c\ub2e4. \uc124\uacc4\uc790\ub294 \uc774\ud0c8\ub9ac\uc544 \uac74\ucd95\uac00 \ub80c\ucd08 \ud53c\uc544\ub178\ub2e4. \ubbf8\uc220\uad00\uc774 \uc18c\uac1c\ud558\ub294 \uadf8\uc758 \uc0dd\uac01 \uac00\uc6b4\ub370 \ud558\ub098\ub294 \uac74\ubb3c\uc774 \ub5a0\uc624\ub974\ub4ef \ubcf4\uc774\uac8c \ud558\ub294 \uc81c\ub85c \uadf8\ub798\ube44\ud2f0\ub77c\ub294 \ud45c\ud604\uc774\ub2e4. \ub9d0\uc740 \uac70\ucc3d\ud558\uc9c0\ub9cc \ub208\uc5ec\uaca8\ubcfc \uacf3\uc740 \uc758\uc678\ub85c \ubc1c\ubc11\uc774\ub2e4. \uae30\uad00\uc758 \uae00\uc740 \ubcbd \uc544\ub7ab\ubd80\ubd84\uc5d0 \uc57d 1\uc778\uce58\uc758 \ub4dc\ub7ec\ub09c \ud2c8\uc774 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc57d 2.5\uc13c\ud2f0\ubbf8\ud130\ub2e4. \ubcbd \uc804\uccb4\uc5d0 \ube44\ud558\uba74 \uc791\uc740 \ub192\uc774\uc9c0\ub9cc \ubc14\ub2e5\uacfc \ubcbd \uc0ac\uc774\uc5d0 \uac00\ub290\ub2e4\ub780 \uc120\uc744 \ub9cc\ub4e0\ub2e4. \ubcbd\uc740 \ub2f9\uc5f0\ud788 \ubc14\ub2e5\uc5d0 \ub2ff\uc544 \uc788\uc744 \uac83\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uae30 \uc27d\ub2e4. \uadf8 \ub9cc\ub098\ub294 \uc790\ub9ac\ub97c \uc870\uae08 \ub2e4\ub974\uac8c \ucc98\ub9ac\ud558\uba74 \ub369\uc5b4\ub9ac\uc758 \ub290\ub08c\ub3c4 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ucc9c\uc7a5\ub9cc \uc62c\ub824\ub2e4\ubcf4\ub358 \uc2dc\uc120\uc744 \uc544\ub798\ub85c \ub0b4\ub9ac\ub294 \uc774\uc720\uac00 \uc0dd\uae34\ub2e4. \uae00\uc5d0 \ub530\ub974\uba74 \ud53c\uc544\ub178\uac00 \ub514\uc790\uc778\ud55c \ubca4\uce58\ub3c4 \uc791\uc740 \ubc1b\uce68 \uc704\uc5d0 \ub193\uc5ec \ubc14\ub2e5\uc5d0\uc11c \uc870\uae08 \uc62c\ub77c\uac00 \uc788\ub2e4. \uc870\uac01\uc758 \ubc1b\uce68\ub300\uc640 \ub2e8 \uc5ed\uc2dc \ubc14\ub2e5\uc5d0\uc11c \ub5a8\uc5b4\uc838 \ubcf4\uc774\ub3c4\ub85d \ud588\uc73c\uba70, \ud070 \uacc4\ub2e8 \uc544\ub798\uc5d0\ub3c4 \ud2c8\uc774 \uc788\ub2e4. \ubcbd \ud558\ub098\uc5d0\ub9cc \ub123\uc740 \uc6b0\uc5f0\ud55c \uc7a5\uc2dd\uc774 \uc544\ub2c8\ub77c \uc5ec\ub7ec \ubd80\ubd84\uc5d0\uc11c \uc774\uc5b4\uc9c0\ub294 \uc120\ud0dd\uc774\uc5c8\ub2e4. \ub2e4\ub978 \ubaa8\uc591\uc758 \uac00\uad6c\uc640 \uad6c\uc870\ubb3c\uc774 \ube44\uc2b7\ud55c \ubc29\uc2dd\uc73c\ub85c \ubc14\ub2e5\uc744 \ub9cc\ub098\uba74 \uacf5\uac04 \uc804\uccb4\uc5d0\ub3c4 \uacf5\ud1b5\ub41c \uc778\uc0c1\uc774 \ub9cc\ub4e4\uc5b4\uc9c4\ub2e4. \ubcbd\uacfc \uacc4\ub2e8\uc740 \uc2e4\uc81c\ub85c \uc9c0\uc9c0\ub418\uc5b4\uc57c \ud55c\ub2e4. \uc81c\ub85c \uadf8\ub798\ube44\ud2f0\ub77c\ub294 \ub9d0\uc774 \uadf8 \uc870\uac74\uc744 \uc5c6\uc560\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubbf8\uc220\uad00\uc758 \uc124\uba85\uc740 \ubcf4\uc774\ub294 \uc811\uc810\uc744 \uc870\uc815\ud574 \ub369\uc5b4\ub9ac\uc758 \uc778\uc0c1\uc744 \ubc14\uafb8\ub294 \uc124\uacc4\ub97c \uc774\uc57c\uae30\ud55c\ub2e4. \uad6c\uc870\uc801\uc73c\ub85c \uc5b4\ub5bb\uac8c \uc11c \uc788\ub294\uac00\uc640 \uc0ac\ub78c\uc758 \ub208\uc5d0 \uc5b4\ub5bb\uac8c \ubcf4\uc774\ub294\uac00\ub294 \uc5f0\uacb0\ub418\uc5b4 \uc788\uc9c0\ub9cc \uac19\uc740 \uc9c8\ubb38\ub9cc\uc740 \uc544\ub2c8\ub2e4. \ubcbd \uc544\ub798\uc758 \ud2c8\uc740 \uadf8 \ucc28\uc774\ub97c \ub290\ub07c\uac8c \ud558\ub294 \uc791\uc740 \uc790\ub9ac\ub2e4. \ubc14\ub2e5\uc5d0\uc11c \ubcbd\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \uacbd\uacc4\uc5d0 \uadf8\ub9bc\uc790\uac00 \uc0dd\uae30\uba74 \uc804\uccb4 \uba74\uc774 \uc870\uae08 \ub5a8\uc5b4\uc838 \uc788\ub294 \ub4ef \ubcf4\uc77c \uc218 \uc788\ub2e4. \uac70\ub300\ud55c \uc7a5\uc2dd\uc744 \uc0c8\ub85c \ub354\ud558\uc9c0 \uc54a\uc544\ub3c4 \uc775\uc219\ud55c \uc811\uc810 \ud558\ub098\ub97c \ub2e4\ub974\uac8c \ucc98\ub9ac\ud574 \uacf5\uac04\uc758 \ud45c\uc815\uc744 \ubc14\uafb8\ub294 \ubc29\uc2dd\uc774\ub2e4. \uc815\ud655\ud55c \uad6c\uc870 \ub3c4\uba74 \uc5c6\uc774\ub3c4 \uad00\ub78c\uc790\uac00 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub294 \ub2e8\uc11c\uac00 \ub41c\ub2e4. \uc57d 2.5\uc13c\ud2f0\ubbf8\ud130\ub77c\ub294 \ub192\uc774\ub294 \uac74\ubb3c\uc758 \uc804\uccb4 \ud06c\uae30\uc5d0 \ube44\ud558\uba74 \uc544\uc8fc \uc791\ub2e4. \uadf8\ub7f0\ub370 \uc0ac\ub78c\uc740 \uc2e4\ub0b4\uc5d0\uc11c \ubcbd\uacfc \uac00\uad6c\ub97c \uac00\uae4c\uc774 \ub9cc\ub098\uae30 \ub54c\ubb38\uc5d0 \uc774\ub7f0 \uacbd\uacc4\ub97c \ub208\uce58\ucc4c \uc218 \uc788\ub2e4. \uba3c \uacf3\uc5d0\uc11c \uac74\ubb3c\uc758 \uc724\uacfd\uc744 \ubcf4\ub294 \uacbd\ud5d8\uacfc \ubcf5\ub3c4\uc5d0\uc11c \ubc1c\ubc11\uc758 \uc120\uc744 \ubcf4\ub294 \uacbd\ud5d8\uc740 \ub2e4\ub978 \ud06c\uae30\uc758 \uc815\ubcf4\ub97c \uc900\ub2e4. \ud06c\uae30 \ud558\ub098\ub9cc \uc678\uc6b0\uae30\ubcf4\ub2e4 \uadf8 \ud2c8\uc774 \uc5bc\ub9c8\ub098 \uae38\uac8c \uc774\uc5b4\uc9c0\ub294\uc9c0 \uc0dd\uac01\ud574 \ubcf4\uc790. \uc791\uc740 \ub192\uc774\ub3c4 \uc120\uc73c\ub85c \ubc18\ubcf5\ub418\uba74 \ud55c \uc810\uc758 \uc7a5\uc2dd\uacfc \ub2e4\ub978 \uc778\uc0c1\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub2e4. \ubcf8\ubb38\uc758 \uac1c\ub150 \uc0bd\ud654\ub294 \uc774\ub7f0 \uc2dc\uc120\uc744 \ub3d5\ub294 \uac83\uc774\ubbc0\ub85c \uc2e4\uc81c \ud604\uc7a5\uc758 \ubaa8\ub4e0 \uae38\uc774\uc640 \ubc1b\uce68 \uc704\uce58\ub97c \ud655\uc778\ud558\ub294 \uc790\ub8cc\ub85c \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc218\uce58\uc640 \uacf5\uac04\uc758 \uc2e4\uc81c \ubaa8\uc2b5\uc740 \uae30\uad00 \uc124\uba85 \ubc0f \ud604\uc7a5 \uc790\ub8cc\uc640 \ud568\uaed8 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \ubca4\uce58\uc640 \uc870\uac01 \ubc1b\uce68, \uacc4\ub2e8\uc740 \uc11c\ub85c \ub2e4\ub978 \uc77c\uc744 \ud558\ub294 \ubb3c\uac74\uc774\ub2e4. \uadf8\ub7f0\ub370 \ubc14\ub2e5\uacfc \ub9cc\ub098\ub294 \ubc29\uc2dd\uc744 \ube44\uc2b7\ud558\uac8c \ub2e4\ub8e8\uba74 \uacf5\uac04 \uc548\uc5d0\uc11c \uacf5\ud1b5\ub41c \ub9ac\ub4ec\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub2e4. \ud558\ub098\ud558\ub098\ub97c \ub530\ub85c \ub514\uc790\uc778\ud558\uba74\uc11c\ub3c4 \uc804\uccb4 \uc778\uc0c1\uc774 \uc774\uc5b4\uc9c0\ub3c4\ub85d \ud55c \uc120\ud0dd\uc73c\ub85c \uc77d\ud78c\ub2e4. \uac74\ucd95\uac00\uc758 \uc0dd\uac01\uc774 \uac74\ubb3c \uc678\uad00\uc5d0\uc11c\ub9cc \ub4dc\ub7ec\ub098\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uac00\uad6c\uc758 \ubc1b\uce68\uc744 \ubcf4\ub294 \uc77c\ub3c4 \uadf8\ub798\uc11c \uac10\uc0c1\uc758 \uc77c\ubd80\uac00 \ub41c\ub2e4. \uc549\ub294 \uba74\uc774\ub098 \uc804\uc2dc\ud558\ub294 \uc870\uac01\ubd80\ud130 \ubcf4\uae30 \uc27d\uc9c0\ub9cc \uadf8 \uc544\ub798\uc758 \uc791\uc740 \ubd80\ubd84\uc774 \ub369\uc5b4\ub9ac\uc758 \ubb34\uac8c\ub97c \ub2e4\ub974\uac8c \ub290\ub07c\uac8c \ud560 \uc218 \uc788\ub2e4. \uacf5\uac04\uc758 \ud1b5\uc77c\uac10\uc774 \ubaa8\ub450 \uac19\uc740 \ubaa8\uc591\uc744 \ubc18\ubcf5\ud558\ub294 \ub370\uc11c\ub9cc \uc0dd\uae30\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\uc744 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ub2e4\ub978 \uc0ac\ubb3c\ub4e4\uc774 \uac19\uc740 \uc811\uc810\uc758 \uaddc\uce59\uc744 \uacf5\uc720\ud560 \uc218\ub3c4 \uc788\ub2e4. \ub192\uc740 \ucc9c\uc7a5\uacfc \ud070 \uc720\ub9ac\ucc3d\uc744 \uc62c\ub824\ub2e4\ubcf8 \ub2e4\uc74c \ubc14\ub2e5 \uac00\uae4c\uc774\ub85c \ub208\uc744 \uc62e\uaca8 \ubcf4\uc790. \ubcbd\uacfc \ubc14\ub2e5\uc774 \ub9cc\ub098\ub294 \uc120, \uc758\uc790 \ub2e4\ub9ac\uc640 \ubc1b\uce68\uc758 \uac04\uaca9, \uacc4\ub2e8 \uc544\ub798\uc758 \uadf8\ub9bc\uc790\uac00 \uc0c8\ub85c\uc6b4 \uad00\ucc30 \ub300\uc0c1\uc774 \ub41c\ub2e4. \uc804\ubb38 \uc6a9\uc5b4\ub97c \ub9ce\uc774 \uae30\uc5b5\ud558\uc9c0 \uc54a\uc544\ub3c4 \ub208\uc758 \ub192\uc774\ub97c \ubc14\uafb8\ub294 \uac83\ub9cc\uc73c\ub85c \uc815\ubcf4\uac00 \ub298\uc5b4\ub09c\ub2e4. \ub2e4\ub9cc \uac00\ubccd\uac8c \ubcf4\uc778\ub2e4\ub294 \uac10\uc0c1\uc774 \ub204\uad6c\uc5d0\uac8c\ub098 \uac19\uc740 \uc815\ub3c4\ub85c \uc0dd\uae30\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uae30\uad00\uc758 \uc124\uacc4 \uc124\uba85\uc740 \uc758\ub3c4\ub97c \uc54c\ub824 \uc8fc\uace0 \uad00\ub78c\uc790\ub294 \uc790\uae30 \uacbd\ud5d8\uc744 \ud1b5\ud574 \ud655\uc778\ud55c\ub2e4. \uc758\ub3c4\ub97c \ub4e4\uc5c8\ub2e4\uace0 \ubc18\ub4dc\uc2dc \uac19\uc740 \ub290\ub08c\uc744 \ub0b4\uc57c \ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc124\uba85\uc774 \ud48d\uacbd\uc744 \ub300\uc2e0\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ud3c9\uc18c\uc5d0 \uc9c0\ub098\ucce4\ub358 \ubd80\ubd84\uc744 \ub2e4\uc2dc \ubcf4\uac8c \ud560 \ub54c \uac74\ucd95 \uc774\uc57c\uae30\ub294 \ub354 \uc7ac\ubbf8\uc788\uc5b4\uc9c4\ub2e4. \ubb3c\ub860 \uac74\ubb3c\uc774 \uc2e4\uc81c\ub85c \uacf5\uc911\uc5d0 \ub9e4\ub2ec\ub838\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uae30\uad00 \uae00\uc740 \ub208\uc5d0 \ubcf4\uc774\ub294 \uc811\uc810\uacfc \ud2c8\uc774 \uac00\ubcbc\uc6b4 \uc778\uc0c1\uc744 \uc8fc\ub294 \ubc29\uc2dd\uc744 \uc124\uba85\ud55c\ub2e4. \uad6c\uc870\ub97c \uc9c0\ud0f1\ud558\ub294 \uc6d0\ub9ac\ub97c \uc804\ubd80 \uc54c\uc544\uc57c\ub9cc \uc990\uae38 \uc218 \uc788\ub294 \ub300\ubaa9\uc740 \uc544\ub2c8\ub2e4. \ub2e4\uc74c\uc5d0 \uc0c8\ub85c\uc6b4 \uac74\ubb3c\uc5d0 \ub4e4\uc5b4\uac00\uba74 \ucc3d\ubb38\uc774\ub098 \uba4b\uc9c4 \ucc9c\uc7a5\uc744 \ubcf8 \ub4a4 \uc758\uc790 \ubc11\ub3c4 \ud55c \ubc88 \ubcf4\uc790. \ubc14\ub2e5\uacfc \ub9cc\ub098\ub294 \uc120\uc744 \uc5b4\ub5bb\uac8c \ub2e4\ub918\ub294\uc9c0 \uc0b4\ud53c\ub294 \uac83\uc774\ub2e4. \uac74\ucd95\uac00\uc758 \uc0dd\uac01\uc774 \uac00\uc7a5 \uc791\uc740 \uadf8\ub9bc\uc790\ucc98\ub7fc \ub0a8\uc544 \uc788\ub294 \uc790\ub9ac\uc77c \uc218 \uc788\ub2e4."}, {"id": "chopin-life-piano-and-home", "title": "\uc1fc\ud33d\uc758 \uc0dd\uc560 \u2014 \ub5a0\ub098\uc628 \ub098\ub77c\uac00 \ud53c\uc544\ub178\uc5d0 \ub0a8\uc744 \ub54c", "summary": "\ubc30\uc6c0\uacfc \uc774\uc8fc, \uac00\ub974\uce58\ub294 \uc0dd\ud65c\uacfc \uc791\uace1\uc758 \uc2dc\uac04\uc744 \ud1b5\ud574 \uc1fc\ud33d\uc744 \ub9cc\ub0a9\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Music", "url": "stories/chopin-life-piano-and-home/index.html", "image": "media/chopin-life-piano-and-home.png", "alt": "\ud1a0\uba38\uc2a4 \ud0dc\ud37c\uc758 \uc61b \uc1fc\ud33d \uc548\ub0b4\uc11c\uc5d0 \uc218\ub85d\ub41c \uc1fc\ud33d\uc758 \ucd08\uc0c1 \uc7ac\ud604 \ub3c4\ud310.", "text": "\uc1fc\ud33d\uc758 \uc0dd\uc560 \u2014 \ub5a0\ub098\uc628 \ub098\ub77c\uac00 \ud53c\uc544\ub178\uc5d0 \ub0a8\uc744 \ub54c \ubc14\ub974\uc0e4\ubc14\uc5d0\uc11c \ud30c\ub9ac\ub85c, \ucda4\uc758 \ub9ac\ub4ec\uacfc \ub178\ub798\ud558\ub294 \uac74\ubc18\uc744 \ub530\ub77c \ubc30\uc6c0\uacfc \uc774\uc8fc, \uac00\ub974\uce58\ub294 \uc0dd\ud65c\uacfc \uc791\uace1\uc758 \uc2dc\uac04\uc744 \ud1b5\ud574 \uc1fc\ud33d\uc744 \ub9cc\ub0a9\ub2c8\ub2e4. Music \ubb38\ud654 \uc1fc\ud33d\uc758 \uc74c\uc545\uc744 \ub4e4\uc73c\uba74 \ud53c\uc544\ub178\uac00 \ub178\ub798\ud558\ub294 \uac83\ucc98\ub7fc \ub290\uaef4\uc9c8 \ub54c\uac00 \uc788\ub2e4. \uba5c\ub85c\ub514\uac00 \ud55c\uc228\ucc98\ub7fc \uae38\uc5b4\uc84c\ub2e4\uac00 \uc7a5\uc2dd\uc74c\uc774 \uac00\ubccd\uac8c \ud769\uc5b4\uc9c0\uace0, \ub2e4\ub978 \uace1\uc5d0\uc11c\ub294 \ucda4\uc758 \uac78\uc74c\uc774 \ub610\ub837\ud558\uac8c \uc0b4\uc544\ub09c\ub2e4. \uc774\ub7f0 \ud45c\uc815\ub4e4\uc744 \uc5f0\uc57d\ud568\uc774\ub098 \uc2ac\ud514 \ud55c \uac00\uc9c0\ub85c\ub9cc \ubb36\uae30\ub294 \uc5b4\ub835\ub2e4. \ud504\ub808\ub370\ub9ac\ud06c \uc1fc\ud33d\uc740 1810\ub144\uc5d0 \ud0dc\uc5b4\ub098 1849\ub144\uc5d0 \uc138\uc0c1\uc744 \ub5a0\ub09c \ud3f4\ub780\ub4dc \uc791\uace1\uac00\uc774\uc790 \ud53c\uc544\ub2c8\uc2a4\ud2b8\ub2e4. \uc9e7\uc740 \uc0dd\uc560\ub97c \ucc9c\uc7ac\uc758 \ube44\uadf9\uc73c\ub85c\ub9cc \ub530\ub77c\uac00\uae30\ubcf4\ub2e4, \ubc30\uc6c0\uacfc \uc774\uc8fc, \uad50\uc2b5\uacfc \uc791\uace1\uc774 \uc5b4\ub5bb\uac8c \ud55c \uc545\uae30\uc758 \uc138\uacc4\ub97c \ub113\ud614\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uc1fc\ud33d\uc740 \ubc14\ub974\uc0e4\ubc14 \uadfc\ucc98\uc5d0\uc11c \ud0dc\uc5b4\ub098 \uc5b4\ub9b0 \uc2dc\uc808\ubd80\ud130 \uc74c\uc545\uc744 \ubc30\uc6b0\uace0 \uc5f0\uc8fc\ud588\ub2e4. \ubc14\ub974\uc0e4\ubc14\uc5d0\uc11c \uc131\uc7a5\ud558\uba70 \uc5d8\uc2a4\ub124\ub974 \uac19\uc740 \uc2a4\uc2b9\uc5d0\uac8c \ubc30\uc6e0\uace0, \ub610\ub798\uc640 \uac00\uc871\uc758 \uc0dd\ud65c \uc18d\uc5d0\uc11c \uc74c\uc545\uc744 \uc775\ud614\ub2e4. \uc774\ubbf8 \uc644\uc131\ub41c \ud53c\uc544\ub178\uc758 \uc2dc\uc778\uc774 \uc5b4\ub290 \ub0a0 \ub4f1\uc7a5\ud588\ub2e4\uae30\ubcf4\ub2e4 \ubc30\uc6c0\uacfc \uae30\ud68c\uac00 \uc313\uc778 \uc2dc\uac04\uc774\uc5c8\ub2e4. \uc774 \uc2dc\uae30\uc5d0 \ub9cc\ub09c \ud3f4\ub780\ub4dc\uc758 \ucda4\uacfc \ub178\ub798\ub294 \uc774\ud6c4 \uc791\ud488\uc744 \uc774\ud574\ud558\ub294 \ubc30\uacbd\uc774 \ub41c\ub2e4. \ub2e4\ub9cc \uadf8\uac00 \ub4e4\uc740 \ubaa8\ub4e0 \ubbfc\uc18d \uc120\uc728\uc744 \uadf8\ub300\ub85c \uc545\ubcf4\uc5d0 \uc62e\uacbc\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc775\uc219\ud55c \ub9ac\ub4ec\uacfc \ubab8\uc758 \uac10\uac01\uc744 \uc790\uae30 \uc791\ud488\uc758 \uc5b8\uc5b4\ub85c \ubc14\uafb8\uc5b4 \uac14\ub2e4\uace0 \ubcf4\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc1fc\ud33d\uc740 1830\ub144 \ubc14\ub974\uc0e4\ubc14\ub97c \ub5a0\ub0ac\uace0, 1831\ub144\uc5d0\ub294 \ud30c\ub9ac\uc5d0\uc11c \uc0dd\ud65c\ud558\uac8c \ub41c\ub2e4. \uadf8 \uc0ac\uc774 \ud3f4\ub780\ub4dc\uc758 \uc815\uce58\uc801 \uaca9\ubcc0\uc774 \uc774\uc5b4\uc84c\ub2e4. \uac00\uc871\uacfc \uc775\uc219\ud55c \ub3c4\uc2dc\ub97c \uc7a0\uc2dc \ub5a0\ub098\ub294 \uac83\uacfc, \uc27d\uac8c \ub3cc\uc544\uac08 \uc218 \uc5c6\ub294 \uc0dd\ud65c\uc744 \uc2dc\uc791\ud558\ub294 \uac83\uc740 \uac19\uc740 \uacbd\ud5d8\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc791\ud488\uc744 \ubaa8\ub450 \uace0\ud5a5\uc744 \uadf8\ub9ac\uc6cc\ud55c \uc554\ud638\ub85c \ud574\ub3c5\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uadf8\ub7ec\ub098 \ucda4\uc758 \ub9ac\ub4ec\uacfc \ud3f4\ub780\ub4dc\uc758 \uc774\ub984\uc774 \uadf8\uc758 \uc74c\uc545\uc5d0\uc11c \uacc4\uc18d \uc911\uc694\ud558\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc0dd\uc560\uc640 \ud568\uaed8 \ubcfc \uc218\ub294 \uc788\ub2e4. \uc774\uc8fc\ud55c \uc0ac\ub78c\uc5d0\uac8c \uace0\ud5a5\uc740 \ud48d\uacbd\uc758 \uae30\uc5b5\ubfd0 \uc544\ub2c8\ub77c \ubab8\uc5d0 \uc775\uc740 \uac78\uc74c\uacfc \ub9d0\ud22c\ub85c \ub0a8\uae30\ub3c4 \ud55c\ub2e4. \ud30c\ub9ac\ub294 \uc5ec\ub7ec \uc74c\uc545\uac00\uc640 \uc791\uac00, \ud6c4\uc6d0\uc790\uac00 \ub9cc\ub098\ub294 \ub3c4\uc2dc\uc600\ub2e4. \uc1fc\ud33d\uc740 \uadf8\uacf3\uc5d0\uc11c \uc5f0\uc8fc\ud558\uace0 \uc791\ud488\uc744 \ub0b4\uba70 \ud559\uc0dd\ub4e4\uc744 \uac00\ub974\ucce4\ub2e4. \ub300\uaddc\ubaa8 \ubb34\ub300\uc758 \uc5f4\uad11\ub9cc\uc73c\ub85c \uc0dd\ud65c\ud55c \uc608\uc220\uac00\ub77c\uace0 \ubcf4\uba74 \uad50\uc2b5\uacfc \uc0b4\ub871, \uc77c\uc0c1\uc801\uc778 \uad00\uacc4\uac00 \ucc28\uc9c0\ud55c \uc790\ub9ac\ub97c \ub193\uce5c\ub2e4. \ub204\uad70\uac00\uc758 \uc190\uac00\ub77d\uacfc \uc18c\ub9ac\ub97c \uac00\uae4c\uc774 \uc0b4\ud53c\ub294 \uad50\uc2b5\uc740 \uc791\uace1\uac00\uc758 \uc0dd\ud65c\uacfc\ub3c4 \uc5f0\uacb0\ub41c\ub2e4. \uadf8\uc758 \uc74c\uc545\uc5d0\ub294 \ud53c\uc544\ub178\uac00 \uc5b4\ub5a4 \uc6b8\ub9bc\uc744 \ub0bc \uc218 \uc788\uace0 \uc190\uc774 \uc5b4\ub5bb\uac8c \uc6c0\uc9c1\uc77c \uc218 \uc788\ub294\uc9c0\uc5d0 \ub300\ud55c \uc138\ubc00\ud55c \uad00\uc2ec\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \uba5c\ub85c\ub514\uc758 \uc544\ub984\ub2e4\uc6c0\uacfc \uc545\uae30\uc758 \uad6c\uccb4\uc801\uc778 \uc870\uac74\uc744 \ub530\ub85c \ub5bc\uae30 \uc5b4\ub835\ub2e4. \uc57c\uc0c1\uace1\uc774\ub77c\ub294 \uc774\ub984\uc740 \ubc24\uc758 \ubd84\uc704\uae30\ub97c \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \uc1fc\ud33d\uc774 \uc774 \uc7a5\ub974\ub97c \ud63c\uc790 \ucc98\uc74c \ubc1c\uba85\ud588\ub2e4\uace0 \ub9d0\ud558\ub294 \uac83\uc740 \uc815\ud655\ud558\uc9c0 \uc54a\ub2e4. \ud734\ub108\ucee4\uc758 \uc804\uae30\ub3c4 \uc874 \ud544\ub4dc\uc640\uc758 \uad00\uacc4\ub97c \uc9da\ub294\ub2e4. \uc1fc\ud33d\uc740 \uc774\ubbf8 \uc874\uc7ac\ud558\ub358 \uc7a5\ub974 \uc548\uc5d0\uc11c \uc790\uae30\ub9cc\uc758 \ub178\ub798\uc640 \uae34\uc7a5, \uc7a5\uc2dd\uc744 \ubc1c\uc804\uc2dc\ucf30\ub2e4. \ub4e4\uc5b4 \ubcfc \ub54c\ub294 \uc704\ucabd\uc758 \ub178\ub798\uc640 \uc544\ub798\ucabd\uc758 \ubc18\uc8fc\ub97c \ub530\ub85c \ub530\ub77c\uac00 \ubcf4\uc790. \ubc18\uc8fc\uac00 \ubc14\ud0d5\uc744 \ub9cc\ub4e4\uace0 \uc120\uc728\uc740 \uadf8 \uc704\uc5d0\uc11c \uc870\uae08 \ub354 \uc720\uc5f0\ud558\uac8c \uc6c0\uc9c1\uc774\ub294 \ub4ef \ub4e4\ub9b4 \uc218 \uc788\ub2e4. \uc2ac\ud504\ub2e4\ub294 \ub2e8\uc5b4 \ud558\ub098\ub85c \uc815\ub9ac\ud558\uae30\ubcf4\ub2e4 \ub178\ub798\uac00 \uc5b4\ub514\uc5d0\uc11c \uc26c\uace0 \uc5b4\ub514\uc5d0\uc11c \uae38\uc5b4\uc9c0\ub294\uc9c0 \ub290\ub07c\uba74 \uc74c\uc545\uc758 \ud45c\uc815\uc774 \uc138\ubd84\ub41c\ub2e4. \ub9c8\uc8fc\ub974\uce74\uc640 \ud3f4\ub85c\ub124\uc988\ub294 \ud3f4\ub780\ub4dc\uc758 \ucda4\uacfc \uc5f0\uacb0\ub41c \uc774\ub984\uc774\ub2e4. \uc1fc\ud33d\uc758 \uc791\ud488\uc5d0\uc11c\ub294 \uc2e4\uc81c \ucda4\uc758 \uc790\ub9ac\ub97c \ub118\uc5b4 \ud53c\uc544\ub178\ub85c \ub4e3\ub294 \uc74c\uc545\uc758 \uc138\uacc4\uac00 \ub41c\ub2e4. \ucda4\uc5d0\uc11c \ucd9c\ubc1c\ud588\ub2e4\uace0 \ud574\uc11c \uc5b8\uc81c\ub098 \ubb34\ub3c4\uc7a5\uc5d0\uc11c \ub611\uac19\uc774 \ucd94\ub3c4\ub85d \ub9cc\ub4e4\uc5b4\uc9c4 \uace1\ub9cc\uc740 \uc544\ub2c8\ub2e4. \ubc15\uc790\ub9c8\ub2e4 \ubb34\uac8c\uac00 \ub611\uac19\uc740\uc9c0, \uc5b4\ub5a4 \ubd80\ubd84\uc5d0\uc11c \ubc1c\uac78\uc74c\uc774 \uac78\ub9ac\ub294 \ub4ef \ub290\uaef4\uc9c0\ub294\uc9c0 \ub4e4\uc5b4 \ubcf4\uc790. \ud070 \uac10\uc815\ub9cc \ub530\ub77c\uac08 \ub54c\ubcf4\ub2e4 \ub9ac\ub4ec\uc758 \ud2b9\uc9d5\uc774 \uac00\uae4c\uc6cc\uc9c4\ub2e4. \uace0\ud5a5\uc758 \ud754\uc801\uc740 \ud2b9\uc815 \uc120\uc728\uc758 \uc778\uc6a9\ub9cc\uc774 \uc544\ub2c8\ub77c \uc774\ub7f0 \ubb34\uac8c\uc640 \uc6c0\uc9c1\uc784\uc758 \ubc29\uc2dd\uc5d0\ub3c4 \ub0a8\uc744 \uc218 \uc788\ub2e4. \uc1fc\ud33d\uc744 \uc124\uba85\ud560 \ub54c \ub8e8\ubc14\ud1a0\ub77c\ub294 \ub9d0\uc744 \uc790\uc8fc \ub9cc\ub09c\ub2e4. \uc2dc\uac04\uc744 \uc870\uae08 \ub298\uc774\uac70\ub098 \ub2f9\uae30\uba70 \ud45c\ud604\ud558\ub294 \uc5f0\uc8fc\uc640 \uad00\ub828\ub41c \ub9d0\uc774\ub2e4. \uadf8\ub7ec\ub098 \uc544\ubb34 \uacf3\uc5d0\uc11c\ub098 \uba48\ucd94\uace0 \uc804\uccb4 \ubc15\uc790\ub97c \uc783\uc5b4\ub3c4 \ub41c\ub2e4\ub294 \ud5c8\uac00\uc99d\uc740 \uc544\ub2c8\ub2e4. \ud750\ub984\uc744 \uc720\uc9c0\ud558\uba74\uc11c \uc18c\ub9ac\uc758 \ub9d0\ud22c\ub97c \uc138\uc2ec\ud558\uac8c \uc870\uc808\ud558\ub294 \ubb38\uc81c\uc5d0 \uac00\uae5d\ub2e4. \uc6b0\ub9ac\uac00 \ubb38\uc7a5\uc744 \uc77d\uc744 \ub54c \ubaa8\ub4e0 \uc74c\uc808\uc744 \uac19\uc740 \uae38\uc774\ub85c \ub9d0\ud558\uc9c0 \uc54a\ub294 \uac83\uc5d0 \ube44\uc720\ud560 \uc218 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubb38\uc7a5\uc774 \uc5b4\ub514\ub85c \ud5a5\ud558\ub294\uc9c0 \uc78a\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5f0\uc8fc \ub450 \uac1c\ub97c \ube44\uad50\ud574 \ubcf4\uba74 \uac19\uc740 \uc120\uc728\ub3c4 \uc228\uc744 \uc26c\ub294 \uc704\uce58\uc640 \uc6c0\uc9c1\uc784\uc774 \ub2e4\ub974\uac8c \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \uc774\ub97c \ubaa8\ub450 \uc791\uace1\uac00\uc758 \ud55c \uac00\uc9c0 \uac10\uc815\uc73c\ub85c \ud658\uc6d0\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc791\uac00 \uc870\ub974\uc8fc \uc0c1\ub4dc\uc640\uc758 \uad00\uacc4\ub294 \uc1fc\ud33d\uc758 \uc0dd\uc560\uc5d0\uc11c \ud070 \ube44\uc911\uc744 \ucc28\uc9c0\ud55c\ub2e4. \ub9c8\uc694\ub974\uce74 \uccb4\ub958\uc640 \ud504\ub791\uc2a4 \ub178\uc559\uc5d0\uc11c\uc758 \uc2dc\uac04\uc5d0\ub294 \uac74\uac15\uc758 \uc5b4\ub824\uc6c0\uacfc \uc0dd\ud65c, \uc791\uace1\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4. \ub450 \uc0ac\ub78c\uc758 \uad00\uacc4\ub97c \ub0ad\ub9cc\uc801\uc778 \uc0ac\ub791 \uc774\uc57c\uae30\ub9cc\uc73c\ub85c \ubcf4\uac70\ub098, \ubc18\ub300\ub85c \ub204\uac00 \ub204\uad6c\uc758 \uc608\uc220\uc744 \ub9dd\ucce4\ub2e4\ub294 \ud310\uc815\uc73c\ub85c \ub05d\ub0b4\uae30\ub294 \uc5b4\ub835\ub2e4. \uc624\ub798\ub41c \uc804\uae30\uc5d0\ub294 \uc0c1\ub4dc\uc640 \uc1fc\ud33d\uc744 \ud3c9\uac00\ud558\ub294 \uac15\ud55c \ud3b8\uacac\ub3c4 \uc11e\uc5ec \uc788\ub2e4. \uadf8\ub7f0 \uc778\ubb3c\ud3c9\uc744 \uadf8\ub300\ub85c \ubc1b\uc544\ub4e4\uc774\uae30\ubcf4\ub2e4 \uc5b4\ub514\uc5d0\uc11c \ud568\uaed8 \uc9c0\ub0c8\uace0 \uc5b4\ub5a4 \uc791\uc5c5\uacfc \uc5b4\ub824\uc6c0\uc774 \uc788\uc5c8\ub294\uc9c0 \uad6c\ubd84\ud574 \uc77d\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc0ac\uc0dd\ud65c\uc740 \uc791\ud488\uc744 \ub9cc\ub098\ub294 \ud55c \ubc30\uacbd\uc774\uc9c0\ub9cc \uc74c\uc545\uc758 \uac00\uce58\ub97c \ub300\uc2e0 \ud310\uacb0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uac74\uac15\uc774 \uc545\ud654\ub41c \uc1fc\ud33d\uc740 1849\ub144\uc5d0 \uc138\uc0c1\uc744 \ub5a0\ub0ac\ub2e4. \ud53c\uc544\ub178\ub97c \uc911\uc2ec\uc73c\ub85c \ub0a8\uae34 \uc791\ud488\ub4e4\uc740 \ub178\ub798\ud558\ub294 \uc120\uc728\uacfc \ucda4\uc758 \ub9ac\ub4ec, \uc815\uad50\ud55c \uc6c0\uc9c1\uc784\uc744 \uc11c\ub85c \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \uc774\uc5b4 \uac04\ub2e4. \ub4e3\uae30 \ud3b8\ud55c \uc57c\uc0c1\uace1 \ud558\ub098\uc640 \ud798 \uc788\ub294 \ud3f4\ub85c\ub124\uc988 \ud558\ub098\ub97c \ube44\uad50\ud558\ub294 \uac83\ub9cc\uc73c\ub85c\ub3c4 \ud55c \uc791\uace1\uac00\uc758 \ud3ed\ub113\uc740 \ud45c\uc815\uc744 \ub9cc\ub0a0 \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 \uc61b \uc74c\uc545 \uc548\ub0b4\uc11c\uc5d0 \uc2e4\ub9b0 \uc1fc\ud33d\uc758 \uc5ed\uc0ac\uc801 \ucd08\uc0c1 \uc7ac\ud604 \ub3c4\ud310\uc774\ub2e4. \uc5bc\uad74\ub9cc\uc73c\ub85c \uadf8\uc758 \uac74\uac15\uc774\ub098 \uc131\uaca9\uc744 \ud310\ub2e8\ud558\uae30\ubcf4\ub2e4 \uc74c\uc545\uc73c\ub85c \ub3cc\uc544\uac08 \ucd9c\ubc1c\uc810\uc73c\ub85c \ubcf4\uba74 \uc88b\ub2e4. \ubc14\ub974\uc0e4\ubc14\uc5d0\uc11c \ubc30\uc6b4 \uccad\ub144, \ud30c\ub9ac\uc5d0\uc11c \uac00\ub974\uce58\ub358 \uc74c\uc545\uac00, \ud55c \uc545\uae30\ub97c \uae4a\uac8c \ud0d0\uad6c\ud55c \uc791\uace1\uac00\ub97c \ud568\uaed8 \uae30\uc5b5\ud558\uba74 \uc775\uc219\ud55c \uc774\ub984 \ub4a4\uc758 \uc0b6\uc774 \uc870\uae08 \ub354 \uc785\uccb4\uc801\uc73c\ub85c \ub4e4\ub9b0\ub2e4."}, {"id": "christmas-carol-scrooge-change", "title": "\ud06c\ub9ac\uc2a4\ub9c8\uc2a4 \uce90\ub7f4 \u2014 \uc2a4\ud06c\ub8e8\uc9c0\uac00 \ub2e4\uc2dc \ubc30\uc6b0\ub294 \uc0ac\ub78c\uc758 \uc628\uae30", "summary": "\uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc744 \ub530\ub77c\uac00\uba70 \ub3c8\uc744 \uc138\ub358 \uc2a4\ud06c\ub8e8\uc9c0\uac00 \uc0ac\ub78c\ub4e4\uc758 \uc0b6\uc744 \ub2e4\uc2dc \ubcf4\uac8c \ub418\ub294 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Literature", "url": "stories/christmas-carol-scrooge-change/index.html", "image": "media/christmas-carol-scrooge-change.jpg", "alt": "\ud398\uc9c0\uc704\uadf8\uc758 \ud06c\ub9ac\uc2a4\ub9c8\uc2a4 \ubb34\ub3c4\ud68c\ub97c \uadf8\ub9b0 \uc61b \uc0bd\ud654. \uc2e4\ub0b4\uc5d0 \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc5ec \ucda4\ucd94\uace0 \uc788\uc2b5\ub2c8\ub2e4.", "text": "\ud06c\ub9ac\uc2a4\ub9c8\uc2a4 \uce90\ub7f4 \u2014 \uc2a4\ud06c\ub8e8\uc9c0\uac00 \ub2e4\uc2dc \ubc30\uc6b0\ub294 \uc0ac\ub78c\uc758 \uc628\uae30 \uc138 \uc720\ub839\uc774 \ubcf4\uc5ec \uc900 \uacfc\uac70\uc640 \ud604\uc7ac, \uc544\uc9c1 \ubc14\uafc0 \uc218 \uc788\ub294 \ubbf8\ub798 \uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc744 \ub530\ub77c\uac00\uba70 \ub3c8\uc744 \uc138\ub358 \uc2a4\ud06c\ub8e8\uc9c0\uac00 \uc0ac\ub78c\ub4e4\uc758 \uc0b6\uc744 \ub2e4\uc2dc \ubcf4\uac8c \ub418\ub294 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Literature \ubb38\ud654 \ud06c\ub9ac\uc2a4\ub9c8\uc2a4\ub97c \uc55e\ub454 \uac70\ub9ac\uc5d0\uc11c \ub204\uad70\uac00\ub294 \ub4e4\ub728\uace0 \ub204\uad70\uac00\ub294 \ubc14\uc058\ub2e4. \uc2a4\ud06c\ub8e8\uc9c0\ub294 \uadf8 \uc18c\ub780\uc744 \ub2ec\uac00\uc6cc\ud558\uc9c0 \uc54a\ub294\ub2e4. \ud568\uaed8 \uc77c\ud558\ub294 \uc0ac\ub78c\uc758 \ucd94\uc704\ubcf4\ub2e4 \uc7a5\ubd80\uc758 \uc22b\uc790\uc5d0 \ubbfc\uac10\ud558\uace0, \uc870\uce74\uc758 \ucd08\ub300\ub3c4 \uac70\uc808\ud55c\ub2e4. \ub530\ub73b\ud568\uc744 \ub204\ub9b4 \uc5ec\uc720\uac00 \uc5c6\ub294 \uc0ac\ub78c\uc774\ub77c\uae30\ubcf4\ub2e4, \ub530\ub73b\ud568\uc744 \uc4f8\ub370\uc5c6\ub294 \uc77c\ub85c \uc5ec\uae30\ub294 \uc0ac\ub78c\uc5d0 \uac00\uae5d\ub2e4. \ucc30\uc2a4 \ub514\ud0a8\uc2a4\uac00 1843\ub144\uc5d0 \ubc1c\ud45c\ud55c \u300e\ud06c\ub9ac\uc2a4\ub9c8\uc2a4 \uce90\ub7f4\u300f\uc740 \uadf8\uc5d0\uac8c \uc774\uc0c1\ud55c \ud558\ub8fb\ubc24\uc744 \uc120\ubb3c\ud55c\ub2e4. \uc8fd\uc740 \ub3d9\uc5c5\uc790\uc640 \uc138 \uc720\ub839\uc774 \ucc3e\uc544\uc640 \ub3c8\uc73c\ub85c\ub294 \ubcf4\uc774\uc9c0 \uc54a\ub358 \uc2dc\uac04\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc544\ub798\uc5d0\ub294 \uc8fc\uc694 \uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc774 \ud3ec\ud568\ub418\uc5b4 \uc788\ub2e4. \uc774\uc57c\uae30\ub294 \ub9d0\ub9ac\uac00 \uc8fd\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ubd84\uba85\ud788 \ubc1d\ud788\uba70 \uc2dc\uc791\ud55c\ub2e4. \uadf8 \ub9d0\ub9ac\uac00 \uc1e0\uc0ac\uc2ac\uc5d0 \ubb36\uc778 \uc720\ub839\uc73c\ub85c \uc2a4\ud06c\ub8e8\uc9c0 \uc55e\uc5d0 \ub098\ud0c0\ub09c\ub2e4. \uc0ac\uc2ac\uc5d0\ub294 \uc7a5\ubd80\uc640 \ub3c8\uc0c1\uc790 \uac19\uc740 \ubb3c\uac74\uc774 \ub9e4\ub2ec\ub824 \uc788\ub2e4. \uc0b4\uc544 \uc788\ub294 \ub3d9\uc548 \ubb34\uc5c7\uc5d0 \ub9e4\uc600\ub294\uc9c0\uac00 \uc8fd\uc5b4\uc11c\ub3c4 \ubab8\uc5d0 \ub0a8\uc740 \ubaa8\uc2b5\ucc98\ub7fc \uc77d\uc744 \uc218 \uc788\ub2e4. \ub9d0\ub9ac\ub294 \uc2a4\ud06c\ub8e8\uc9c0\uc5d0\uac8c \uacbd\uace0\ud558\uace0 \uc138 \uc720\ub839\uc758 \ubc29\ubb38\uc744 \uc608\uace0\ud55c\ub2e4. \ub2e8\uc21c\ud788 \uac81\uc744 \uc8fc\ub294 \uc7a5\uce58\ub9cc\uc740 \uc544\ub2c8\ub2e4. \uc2a4\ud06c\ub8e8\uc9c0\uac00 \uadf8\ub300\ub85c \uc0b4\uc544\uac00\uba74 \uc5b4\ub5a4 \uc0ac\ub78c\uc774 \ub420\uc9c0, \uc8fd\uc740 \ub3d9\uc5c5\uc790\uac00 \uba3c\uc800 \ubcf4\uc5ec \uc8fc\ub294 \uc148\uc774\ub2e4. \uc774\ubbf8 \ub05d\ub09c \uc0b6\uc758 \ud6c4\ud68c\uac00 \uc544\uc9c1 \uc0b4\uc544 \uc788\ub294 \uc0ac\ub78c\uc5d0\uac8c \ub3c4\ucc29\ud55c\ub2e4. \uccab \uc720\ub839\uc740 \uc2a4\ud06c\ub8e8\uc9c0\ub97c \uc5b4\ub9b0 \uc2dc\uc808\ub85c \ub370\ub824\uac04\ub2e4. \ud559\uad50\uc5d0 \ud640\ub85c \ub0a8\uaca8\uc9c4 \uc18c\ub144\uacfc \uadf8\ub97c \ucc3e\uc544\uc628 \uc5ec\ub3d9\uc0dd\uc758 \uae30\uc5b5\uc744 \ub9c8\uc8fc\ud558\uba74\uc11c, \uc9c0\uae08\uc758 \ub0c9\uc815\ud568 \uc544\ub798\uc5d0\ub3c4 \uc678\ub85c\uc6c0\uacfc \uc560\uc815\uc774 \uc788\uc5c8\uc74c\uc744 \uc54c\uac8c \ub41c\ub2e4. \uc2a4\ud06c\ub8e8\uc9c0\uac00 \uc6d0\ub798\ubd80\ud130 \uac10\uc815 \uc5c6\ub294 \uae30\uacc4\uc600\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc80a\uc740 \ub0a0\uc758 \uace0\uc6a9\uc8fc \ud398\uc9c0\uc704\uadf8\uac00 \uc5f0 \ud06c\ub9ac\uc2a4\ub9c8\uc2a4 \ubb34\ub3c4\ud68c\ub3c4 \ubcf4\uac8c \ub41c\ub2e4. \ubc29\uacfc \uc74c\uc2dd, \uc74c\uc545\uc744 \ub9c8\ub828\ud55c \ub355\ubd84\uc5d0 \uc0ac\ub78c\ub4e4\uc774 \uc5bc\ub9c8\ub098 \uc990\uac70\uc6cc\ud558\ub294\uc9c0 \uc9c0\ucf1c\ubcf4\ub294 \uc7a5\uba74\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc61b \uc0bd\ud654\uac00 \ubc14\ub85c \uc774 \ubb34\ub3c4\ud68c\ub97c \uadf8\ub838\ub2e4. \ub3c8\uc758 \uc561\uc218\ubcf4\ub2e4 \uadf8\uac83\uc744 \uc4f0\ub294 \uc0ac\ub78c\uc774 \ub2e4\ub978 \uc774\uc5d0\uac8c \uc5b4\ub5a4 \uc2dc\uac04\uc744 \ub9cc\ub4e4\uc5b4 \uc8fc\ub294\uc9c0\uac00 \uc911\uc694\ud574\uc9c4\ub2e4. \uacfc\uac70\uc5d0\ub294 \uc2a4\ud06c\ub8e8\uc9c0\ub97c \uc0ac\ub791\ud55c \ubca8\ub3c4 \uc788\uc5c8\ub2e4. \uadf8\ub7ec\ub098 \uadf8\uc758 \uad00\uc2ec\uc774 \uc810\ucc28 \ubd80\uc640 \uc548\uc804\uc5d0 \uc3e0\ub9ac\uba74\uc11c \ub450 \uc0ac\ub78c\uc758 \uad00\uacc4\ub294 \ub05d\ub09c\ub2e4. \uc720\ub839\uc774 \ubcf4\uc5ec \uc8fc\ub294 \uac83\uc740 \uac00\ub09c\ud588\uc744 \ub54c\ub294 \ud589\ubcf5\ud558\uace0 \ubd80\uc790\uac00 \ub418\uba74 \uc545\ud574\uc9c4\ub2e4\ub294 \ub2e8\uc21c\ud55c \uacf5\uc2dd\uc774 \uc544\ub2c8\ub2e4. \ub450\ub824\uc6c0\uc744 \ud53c\ud558\ub824\uace0 \ubd99\ub4e0 \uac83\uc774 \uc5b4\ub290 \uc21c\uac04 \uc0b6\uc758 \uc911\uc2ec\uc744 \ubaa8\ub450 \ucc28\uc9c0\ud558\ub294 \uacfc\uc815\uc774\ub2e4. \uc2a4\ud06c\ub8e8\uc9c0\ub294 \ubca8\uc774 \ub2e4\ub978 \uac00\uc871\uacfc \ud568\uaed8 \uc0ac\ub294 \ubaa8\uc2b5\ub3c4 \ubcf4\uac8c \ub41c\ub2e4. \uc790\uc2e0\uc774 \uac16\uc9c0 \ubabb\ud55c \uc0b6\uc744 \uc678\ubd80\uc5d0\uc11c \uad6c\uacbd\ud558\ub294 \uc2dc\uac04\uc774 \ub41c\ub2e4. \uacfc\uac70\uc758 \uc7a5\uba74\uc744 \ubc14\uafc0 \uc218 \uc5c6\uae30\uc5d0 \ub354 \uc544\ud504\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \uae30\uc5b5\uc740 \ud604\uc7ac\uc758 \uc0ac\ub78c\ub4e4\uc744 \uc5b4\ub5bb\uac8c \ub300\ud560\uc9c0 \ub2e4\uc2dc \uc0dd\uac01\ud558\uac8c \ud558\ub294 \ud798\ub3c4 \uac00\uc9c4\ub2e4. \ub458\uc9f8 \uc720\ub839\uc740 \uc11c\uae30 \ubc25 \ud06c\ub798\uce6b\uc758 \uc9d1\uc73c\ub85c \ub370\ub824\uac04\ub2e4. \uc2dd\ud0c1\uc740 \ub109\ub109\ud558\uc9c0 \uc54a\uc9c0\ub9cc \uac00\uc871\uc740 \ud568\uaed8 \uc74c\uc2dd\uc744 \ub098\ub204\uba70 \ud558\ub8e8\ub97c \ubcf4\ub0b8\ub2e4. \ubab8\uc774 \uc57d\ud55c \uc5b4\ub9b0 \ud0c0\uc774\ub2c8 \ud300\ub3c4 \uadf8 \uc790\ub9ac\uc5d0 \uc788\ub2e4. \uc2a4\ud06c\ub8e8\uc9c0\uc5d0\uac8c\ub294 \uc784\uae08\uc758 \ud56d\ubaa9\uc73c\ub85c\ub9cc \ubcf4\uc774\ub358 \uc0ac\ub78c\uc774 \uac00\uc871\uc758 \uc911\uc2ec\uc5d0\uc11c \uc0b4\uc544\uac00\ub294 \uc7a5\uba74\uc774\ub2e4. \uac00\ub09c\ud55c \uc9d1\uc758 \uc815\uaca8\uc6c0\uc774 \ubcf4\uc778\ub2e4\uace0 \ud574\uc11c \uac00\ub09c\uc774 \uc88b\uc740 \uac83\uc774\ub77c\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc544\uc774\uc758 \uac74\uac15\uacfc \uc0dd\ud65c\uc758 \ubd88\uc548\ub3c4 \ud568\uaed8 \ub193\uc5ec \uc788\ub2e4. \uc791\ud488\uc740 \uac00\uc871\uc758 \uc560\uc815\uc744 \ubcf4\uc5ec \uc8fc\uba74\uc11c, \uadf8 \uc560\uc815\ub9cc\uc73c\ub85c \ud574\uacb0\ud560 \uc218 \uc5c6\ub294 \uc870\uac74\uae4c\uc9c0 \ub3c5\uc790\uac00 \ubcf4\uac8c \ud55c\ub2e4. \uc0ac\ub78c\uc744 \ub3d5\ub294 \ubb38\uc81c\ub294 \uae30\ubd84 \uc88b\uc740 \ub3d9\uc815\uc73c\ub85c\ub9cc \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \ud604\uc7ac\uc758 \uc720\ub839\uc740 \uc637\uc790\ub77d \uc544\ub798\uc5d0\uc11c \ub450 \uc544\uc774\ub97c \ub4dc\ub7ec\ub0b8\ub2e4. \uc791\ud488\uc740 \uadf8\ub4e4\uc744 \ubb34\uc9c0\uc640 \uacb0\ud54d\uc774\ub77c\ub294 \uc774\ub984\uc73c\ub85c \uc81c\uc2dc\ud55c\ub2e4. \uc990\uac70\uc6b4 \ucd95\uc81c\uc758 \uc7a5\uba74\uc744 \ubcf4\ub358 \ub3c5\uc790\uc5d0\uac8c \uac11\uc790\uae30 \ubd88\ud3b8\ud55c \ud604\uc2e4\uc774 \ub4e4\uc5b4\uc624\ub294 \ub300\ubaa9\uc774\ub2e4. \ub204\uad70\uac00\uc758 \ud06c\ub9ac\uc2a4\ub9c8\uc2a4\uac00 \ube5b\ub0a0 \ub54c\uc5d0\ub3c4 \ub3c4\uc6c0\ubc1b\uc9c0 \ubabb\ud558\ub294 \uc544\uc774\ub294 \uc874\uc7ac\ud55c\ub2e4. \uc2a4\ud06c\ub8e8\uc9c0\uac00 \uac00\ub09c\ud55c \uc0ac\ub78c\ub4e4\uc5d0\uac8c \ud588\ub358 \ucc28\uac00\uc6b4 \ub9d0\ub3c4 \ub2e4\ub978 \uc790\ub9ac\uc5d0\uc11c \ub418\ub3cc\uc544\uc628\ub2e4. \uc81c\ub3c4\ub098 \uc2dc\uc124\uc774 \uc788\uc73c\ub2c8 \ub0b4 \ucc45\uc784\uc740 \ub05d\ub0ac\ub2e4\ub294 \ud0dc\ub3c4\uac00 \uc2e4\uc81c \uc0ac\ub78c \uc55e\uc5d0\uc11c \uc5b4\ub5a4 \ub9d0\uc774 \ub418\ub294\uc9c0 \ub4e3\uac8c \ub418\ub294 \uac83\uc774\ub2e4. \uc720\ub839\uc758 \uc5ec\ud589\uc740 \uc138\uc0c1\uc758 \uc5b4\ub824\uc6c0\uc744 \uc0c8\ub85c \ubc1c\uba85\ud558\uae30\ubcf4\ub2e4 \uadf8\uac00 \uc678\uba74\ud588\ub358 \uac83\uc744 \uac00\uae4c\uc774 \uac00\uc838\uc628\ub2e4. \ub9c8\uc9c0\ub9c9 \uc720\ub839\uc740 \ub9d0\uc5c6\uc774 \uc55e\ub0a0\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc5b4\ub5a4 \uc0ac\ub78c\uc774 \uc8fd\uc5c8\uc9c0\ub9cc \uc0ac\ub78c\ub4e4\uc758 \ubc18\uc751\uc740 \uc2f8\ub298\ud558\uace0, \ub0a8\uaca8\uc9c4 \ubb3c\uac74\uc740 \ud765\uc815\uac70\ub9ac\uac00 \ub41c\ub2e4. \uc2a4\ud06c\ub8e8\uc9c0\ub294 \uadf8\uac83\uc774 \uc790\uc2e0\uc758 \uc8fd\uc74c\uc784\uc744 \uc54c\uc544\ucc28\ub9b0\ub2e4. \uc7ac\uc0b0\uc744 \uc9c0\ud0a4\uba70 \uc0b4\uc544\ub3c4 \uadf8 \uc0b6\uc744 \uc560\ub3c4\ud560 \uad00\uacc4\uae4c\uc9c0 \uc800\uc808\ub85c \ub0a8\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ud06c\ub798\uce6b \uac00\uc871\uc5d0\uac8c\ub3c4 \uc0c1\uc2e4\uc774 \ub2e5\uce5c \ubbf8\ub798\uac00 \ud3bc\uccd0\uc9c4\ub2e4. \uc774 \uc7a5\uba74\uc740 \uc6b4\uba85\uc774 \uc774\ubbf8 \uc815\ud574\uc84c\ub2e4\ub294 \uc120\uc5b8\uc774\ub77c\uae30\ubcf4\ub2e4 \uc9c0\uae08\uc758 \uc120\ud0dd\uc744 \ubb3b\ub294 \uc704\uae30\ub2e4. \uc2a4\ud06c\ub8e8\uc9c0\ub294 \uc55e\uc73c\ub85c\uc758 \uc0b6\uc744 \ubc14\uafb8\uba74 \uc774 \ubbf8\ub798\ub3c4 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub294\uc9c0 \ub9e4\ub2ec\ub9b0\ub2e4. \uacfc\uac70\ub294 \ub3cc\uc774\ud0ac \uc218 \uc5c6\uc9c0\ub9cc \ud604\uc7ac\uc5d0\ub294 \uc544\uc9c1 \uc190\uc744 \ubed7\uc744 \uc218 \uc788\ub2e4. \uae68\uc5b4\ub09c \uc2a4\ud06c\ub8e8\uc9c0\ub294 \ud06c\ub9ac\uc2a4\ub9c8\uc2a4 \uc544\uce68\uc774 \uc544\uc9c1 \ub0a8\uc544 \uc788\uc74c\uc744 \uc54c\uace0 \uae30\ubed0\ud55c\ub2e4. \uc74c\uc2dd\uc744 \ubcf4\ub0b4\uace0 \uae30\ubd80\ud558\uba70 \uc870\uce74\uc758 \uc9d1\uc744 \ucc3e\ub294\ub2e4. \ubc25 \ud06c\ub798\uce6b\uc744 \ub300\ud558\ub294 \ubc29\uc2dd\uacfc \uc784\uae08\ub3c4 \ubc14\uafbc\ub2e4. \ub9c8\uc9c0\ub9c9\uc5d0\ub294 \ud0c0\uc774\ub2c8 \ud300\uc774 \uc0b4\uc544\ub0a8\uace0, \uc2a4\ud06c\ub8e8\uc9c0\uac00 \uadf8 \uc544\uc774\uc5d0\uac8c \ub610 \ud55c \uc0ac\ub78c\uc758 \ubcf4\ud638\uc790 \uac19\uc740 \uc874\uc7ac\uac00 \ub418\uc5c8\ub2e4\uace0 \uc804\ud55c\ub2e4. \uc774 \uacb0\ub9d0\uc758 \uc911\uc694\ud55c \uc810\uc740 \ub9c8\uc74c\uc18d \ubc18\uc131\ub9cc\uc73c\ub85c \uba48\ucd94\uc9c0 \uc54a\ub294\ub2e4\ub294 \ub370 \uc788\ub2e4. \uc5b4\uc81c \uc790\uc2e0\uc774 \ucc28\uac11\uac8c \ub300\ud588\ub358 \uc0ac\ub78c\uc5d0\uac8c \uc624\ub298 \ubb34\uc5c7\uc744 \ud560 \uac83\uc778\uac00. \ub3c8\uacfc \uc2dc\uac04, \uad00\uacc4\ub97c \ub2e4\ub974\uac8c \uc4f0\ub294 \ud589\ub3d9\uc774 \uc774\uc5b4\uc9c0\uba74\uc11c \ubcc0\ud654\ub294 \ub2e4\ub978 \uc0ac\ub78c\ub3c4 \uacaa\ub294 \ud604\uc2e4\uc774 \ub41c\ub2e4. \uc6d0\uc791\uc758 \ub2e4\uc12f \ubd80\ubd84\uc740 \ub178\ub798\uc758 \uc808\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \uc774\ub984\uc73c\ub85c \ub098\ub25c\ub2e4. \uc81c\ubaa9\uc758 \uce90\ub7f4\ub3c4 \ud06c\ub9ac\uc2a4\ub9c8\uc2a4 \ub178\ub798\ub97c \uac00\ub9ac\ud0a8\ub2e4. \uc990\uac70\uc6b4 \uacc4\uc808\uc758 \uc774\ub984\uc744 \ub2e8 \uc791\ud488\uc774\uc9c0\ub9cc, \uadf8 \ub178\ub798 \uc548\uc5d0\ub294 \uc678\ub85c\uc6c0\uacfc \uc0ac\ud68c\uc758 \ubb34\uc2ec\ud568, \ubc14\uafc0 \uc218 \uc788\ub294 \uc120\ud0dd\uc774 \ud568\uaed8 \ub2f4\uaca8 \uc788\ub2e4. \uc2a4\ud06c\ub8e8\uc9c0\uc758 \ubcc0\ud654\ub97c \ud604\uc2e4\uc758 \ubaa8\ub4e0 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\ub294 \ucc98\ubc29\uc73c\ub85c \uc77d\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \ud55c \uc0ac\ub78c\uc774 \uc790\uae30 \uc0b6\uc758 \uc911\uc2ec\uc744 \ubc14\uafb8\ub294 \uc774\uc57c\uae30\ub294 \uc5ec\uc804\ud788 \uc77d\uc744 \ub9cc\ud558\ub2e4. \uc624\ub298 \ub0b4\uac00 \ube44\uc6a9\uc73c\ub85c\ub9cc \uc14c\ub358 \ub204\uad70\uac00\uc5d0\uac8c \uc5b4\ub5a4 \uc0dd\ud65c\uacfc \uac00\uc871\uc774 \uc788\ub294\uc9c0, \uc624\ub798\ub41c \uc720\ub839 \uc774\uc57c\uae30\uac00 \uadf8 \uc791\uc740 \uc0c1\uc0c1\uc744 \uc5f4\uc5b4 \uc900\ub2e4."}, {"id": "clarinet-many-sizes", "title": "\ud074\ub77c\ub9ac\ub137\uc740 \ud55c \uac00\uc9c0 \ud06c\uae30\uac00 \uc544\ub2c8\ub2e4", "summary": "\uc791\uace0 \ub192\uc740 \uc545\uae30\ubd80\ud130 \ucee4\ub2e4\ub780 \uc800\uc74c \uc545\uae30\uae4c\uc9c0 \ud074\ub77c\ub9ac\ub137 \uac00\uc871\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Music", "url": "stories/clarinet-many-sizes/index.html", "image": "media/clarinet-many-sizes.jpg", "alt": "\ud074\ub77c\ub9ac\ub137\uc740 \ud55c \uac00\uc9c0 \ud06c\uae30\uac00 \uc544\ub2c8\ub2e4\uc758 \ub0b4\uc6a9\uc744 \ub3d5\ub294 \uc124\uba85\uc6a9 \uc774\ubbf8\uc9c0", "text": "\ud074\ub77c\ub9ac\ub137\uc740 \ud55c \uac00\uc9c0 \ud06c\uae30\uac00 \uc544\ub2c8\ub2e4 \uac19\uc740 \uc774\ub984\uc758 \uc545\uae30 \uc548\uc5d0 \uc228\uc5b4 \uc788\ub294 \ub113\uc740 \uac00\uc871 \uc791\uace0 \ub192\uc740 \uc545\uae30\ubd80\ud130 \ucee4\ub2e4\ub780 \uc800\uc74c \uc545\uae30\uae4c\uc9c0 \ud074\ub77c\ub9ac\ub137 \uac00\uc871\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Music \ubb38\ud654 \ud074\ub77c\ub9ac\ub137\uc774\ub77c\uace0 \ud558\uba74 \uac80\uc740 \uad00\uc5d0 \uc740\ube5b \uc7a5\uce58\uac00 \ub2ec\ub9b0 \uc545\uae30 \ud558\ub098\uac00 \uba3c\uc800 \ub5a0\uc624\ub978\ub2e4. \uadf8 \uc774\ub984\uc744 \uc54c\uba74 \uc678\ud615\ub3c4 \ub2e4 \uc548\ub2e4\uace0 \ub290\ub07c\uae30 \uc27d\ub2e4. \uadf8\ub7f0\ub370 \ud074\ub77c\ub9ac\ub137 \uac00\uc871\uc744 \ub098\ub780\ud788 \ub193\uc73c\uba74 \uc0dd\uac01\ubcf4\ub2e4 \ud06c\uae30 \ucc28\uc774\uac00 \ud06c\ub2e4. \uc601\uad6d \ud544\ud558\ubaa8\ub2c8\uc544 \uc624\ucf00\uc2a4\ud2b8\ub77c\ub294 \uc544\uc8fc \uc791\uace0 \ub192\uc740 \uc18c\ub9ac\ub97c \ub0b4\ub294 \uc885\ub958\ubd80\ud130 \ucee4\ub2e4\ub780 \ucf58\ud2b8\ub77c\ubca0\uc774\uc2a4 \uc885\ub958\uae4c\uc9c0 \uc5ec\ub7ec \ud06c\uae30\uac00 \uc788\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \uc775\uc219\ud55c \ud558\ub098\uc758 \ubaa8\uc2b5\uc774 \uac00\uc871 \uc804\uccb4\ub97c \ub300\uc2e0\ud558\uace0 \uc788\uc5c8\ub358 \uc148\uc774\ub2e4. \uc77c\ubc18\uc801\uc778 \ud074\ub77c\ub9ac\ub137\uc758 \uc18c\ub9ac\ub3c4 \ub298 \ud55c \uac00\uc9c0 \uc778\uc0c1\uc73c\ub85c\ub9cc \uc124\uba85\ub418\uc9c0 \uc54a\ub294\ub2e4. \ud544\ud558\ubaa8\ub2c8\uc544\ub294 \ub0ae\uc740 \uc74c\uc758 \ub530\ub73b\ud558\uace0 \uc6b8\ub9bc \uc788\ub294 \uc131\uaca9\uacfc \ub192\uc740 \uc74c\uc758 \ubc1d\uace0 \ub9d1\uc740 \uc131\uaca9\uc744 \ud568\uaed8 \uc774\uc57c\uae30\ud55c\ub2e4. \uac19\uc740 \uc0ac\ub78c\uc774 \ub0ae\uac8c \ub9d0\ud560 \ub54c\uc640 \ub192\uac8c \uc678\uce60 \ub54c\uc758 \uc778\uc0c1\uc774 \ub2e4\ub978 \uac83\ucc98\ub7fc \uc0dd\uac01\ud574 \ubcfc \uc218 \uc788\ub2e4. \ubb3c\ub860 \uc545\uae30\uc758 \uc18c\ub9ac\uac00 \uc0ac\ub78c \ubaa9\uc18c\ub9ac\uc640 \ub611\uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc9c4\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ub4e3\ub294 \uacbd\ud5d8\uc744 \uac00\uae4c\uc774 \uac00\uc838\uc624\ub294 \ube44\uc720\ub2e4. \uac00\uc871\uc758 \uc791\uc740 \ucabd\uc5d0\ub294 \ub192\uc740 \uc18c\ub9ac\ub97c \ub9e1\ub294 \uc18c\ud504\ub77c\ub2c8\ub178 \ud074\ub77c\ub9ac\ub137\uc774 \uc788\ub2e4. \ud070 \ucabd\uc758 \ucf58\ud2b8\ub77c\ubca0\uc774\uc2a4 \uc545\uae30\ub294 \ub354\ube14\ubca0\uc774\uc2a4\ubcf4\ub2e4 \ub0ae\uc740 \uc74c\uc744 \ub0bc \uc218 \uc788\ub2e4\uace0 \uc548\ub0b4\ub294 \uc124\uba85\ud55c\ub2e4. \ub208\uc5d0 \uc775\uc740 \ubcf4\ud1b5 \ud06c\uae30\uc758 \uc545\uae30\ub9cc \uc0dd\uac01\ud558\uba74 \uc798 \ub5a0\uc624\ub974\uc9c0 \uc54a\ub294 \ud3ed\uc774\ub2e4. \uac19\uc740 \uc774\ub984\uc758 \uac00\uc871\uc774 \uc74c\uc758 \ub192\ub0ae\uc774\uc640 \ud06c\uae30\uc5d0\uc11c \uc5b4\ub514\uae4c\uc9c0 \ub113\uc5b4\uc9c0\ub294\uc9c0 \ubcf4\ub294 \uac83\ub9cc\uc73c\ub85c\ub3c4 \uc624\ucf00\uc2a4\ud2b8\ub77c\ub97c \ubcf4\ub294 \uc7ac\ubbf8\uac00 \ub298\uc5b4\ub09c\ub2e4. \ud074\ub77c\ub9ac\ub137\uc774\ub77c\uace0 \ud558\uba74 \ubcf4\ud1b5 \uc775\uc219\ud55c \ud06c\uae30\uc758 \uac80\uc740 \uc545\uae30\ub97c \uba3c\uc800 \ub5a0\uc62c\ub9b0\ub2e4. \ud558\uc9c0\ub9cc \uac00\uc871 \uc804\uccb4\ub85c \uc2dc\uc120\uc744 \ub113\ud788\uba74 \ub192\uc740 \ucabd\uc758 \uc791\uc740 \uc545\uae30\uc640 \ub0ae\uc740 \ucabd\uc758 \ud070 \uc545\uae30\uac00 \ud568\uaed8 \ub4e4\uc5b4\uc628\ub2e4. \uac19\uc740 \uc774\ub984 \uc544\ub798\uc5d0\ub3c4 \ud06c\uae30\uc640 \ub9e1\ub294 \uc74c\uc5ed\uc774 \ub098\ub25c\ub2e4. \uc545\uae30 \uc774\ub984 \ud558\ub098\ub97c \uc548\ub2e4\ub294 \uac83\uacfc \uadf8 \uc545\uae30\uad70\uc758 \ud3ed\uc744 \uc548\ub2e4\ub294 \uac83\uc740 \ub2e4\ub978 \ub2e8\uacc4\ub2e4. \ud06c\uae30\uac00 \ub2ec\ub77c\uc9c0\uba74 \ubab8\uc5d0 \ub4dc\ub294 \ubc29\uc2dd\uacfc \ub208\uc5d0 \ubcf4\uc774\ub294 \ud615\ud0dc\ub3c4 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ud06c\uae30\ub9cc \ubcf4\uace0 \ubaa8\ub4e0 \uc18c\ub9ac\uc758 \uc138\ubd80\ub97c \uc815\ud655\ud788 \uc608\uce21\ud558\uac70\ub098 \ub0ae\uc740 \uc545\uae30\uac00 \uc5b8\uc81c\ub098 \ub454\ud55c \uc18c\ub9ac\ub97c \ub0b8\ub2e4\uace0 \uc815\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc2e4\uc81c \uc74c\uc0c9\uacfc \ud45c\ud604\uc740 \uc5f0\uc8fc\ub97c \ub4e4\uc5b4\uc57c \ud55c\ub2e4. \uad6c\uc870\ub97c \ubcf4\ub294 \uc77c\uc740 \uadf8 \uc18c\ub9ac\ub97c \ub9cc\ub098\uae30 \uc704\ud55c \uc9c8\ubb38\uc744 \ub9c8\ub828\ud55c\ub2e4. \ud544\ud558\ubaa8\ub2c8\uc544\uac00 \ub0ae\uc740 \uc74c\uacfc \ub192\uc740 \uc74c\uc758 \uc131\uaca9\uc744 \ub2e4\ub974\uac8c \uc124\uba85\ud558\ub294 \uc810\ub3c4 \ud765\ubbf8\ub86d\ub2e4. \ud558\ub098\uc758 \uc545\uae30\uc5d0\uc11c \ub098\uc624\ub294 \uc120\uc728\ub3c4 \uc5b4\ub290 \uc74c\uc5ed\uc5d0 \uba38\ubb34\ub294\uc9c0\uc5d0 \ub530\ub77c \uc778\uc0c1\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4\ub294 \ub73b\uc774\ub2e4. \uc545\uae30 \uc774\ub984\ub9cc\uc73c\ub85c \ub530\ub73b\ud558\ub2e4\uac70\ub098 \ub0a0\uce74\ub86d\ub2e4\ub294 \uc218\uc2dd \ud558\ub098\ub97c \ubd99\uc774\uba74 \uc774\ub7f0 \ud3ed\uc744 \ub193\uce58\uae30 \uc27d\ub2e4. \uc9e7\uc740 \uc120\uc728\uc774 \ub0ae\uc740 \uacf3\uc5d0\uc11c \uc2dc\uc791\ud574 \uc704\ub85c \uc6c0\uc9c1\uc774\ub294 \uc5f0\uc8fc\ub97c \ub4e4\uc73c\uba74 \ucc28\uc774\ub97c \ucc3e\uae30 \uc88b\ub2e4. \uc815\ud655\ud55c \uc74c\uc774\ub984\uc744 \ubab0\ub77c\ub3c4 \uc18c\ub9ac\uc758 \ubc1d\uae30\uc640 \ubb34\uac8c\uac00 \uc5b4\ub5bb\uac8c \ub290\uaef4\uc9c0\ub294\uc9c0 \ube44\uad50\ud560 \uc218 \uc788\ub2e4. \uc0ac\ub78c\ub9c8\ub2e4 \uac10\uc0c1\uc774 \uac19\uc544\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uae30\uad00\uc774 \uc81c\uc2dc\ud55c \ub9d0\uc740 \ubc18\ub4dc\uc2dc \ub290\uaef4\uc57c \ud560 \uc815\ub2f5\ubcf4\ub2e4 \ub2e4\ub978 \uad6c\uc5ed\uc744 \uc8fc\uc758\ud574\uc11c \ub4e4\uc5b4 \ubcf4\ub77c\ub294 \uc548\ub0b4\ub85c \uc77d\uc73c\uba74 \ub41c\ub2e4. \uae30\uad00 \uc548\ub0b4\ub294 \uc7ac\uc988\uc640 \uc2a4\uc719\uc5d0\uc11c\uc758 \ud45c\ud604\ub3c4 \ud568\uaed8 \uc774\uc57c\uae30\ud55c\ub2e4. \uac19\uc740 \uc545\uae30\uac00 \uc5b4\ub5a4 \ub9ac\ub4ec\uacfc \ub2e4\ub978 \uc5f0\uc8fc\uc790\ub4e4 \uc0ac\uc774\uc5d0 \ub193\uc774\ub294\uc9c0\uc5d0 \ub530\ub77c \uc778\uc0c1\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc74c\uc758 \uc2dc\uc791\uc744 \uc5b4\ub5bb\uac8c \ub2e4\ub8e8\uace0 \uc5b4\ub5a4 \uc6c0\uc9c1\uc784\uc744 \uac15\uc870\ud558\ub294\uc9c0\ub3c4 \ub4e3\ub294 \uacbd\ud5d8\uc5d0 \uc601\ud5a5\uc744 \uc900\ub2e4. \uc545\uae30\uc758 \uc774\ub984\uc774 \uace7 \ud558\ub098\uc758 \uc7a5\ub974\ub97c \ub73b\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \uc18c\ub9ac\uac00 \uc775\uc219\ud558\ub2e4\uba74 \ub2e4\ub978 \ud3b8\uc131\uc758 \uc5f0\uc8fc\uc640 \ub098\ub780\ud788 \ub4e4\uc5b4 \ubcf4\uc790. \uad50\ud5a5\uc545\uc5d0\uc11c \uae38\uac8c \ub178\ub798\ud558\ub294 \uc21c\uac04\uacfc \ub9ac\ub4ec\uc744 \ud0c0\uba70 \ud65c\ubc1c\ud788 \uc6c0\uc9c1\uc774\ub294 \uc21c\uac04\uc744 \ube44\uad50\ud560 \uc218 \uc788\ub2e4. \ubaa8\ub4e0 \ud074\ub77c\ub9ac\ub137 \uc5f0\uc8fc\uac00 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uc2a4\uc6b0\ud551 \ud6a8\uacfc\ub97c \uc0ac\uc6a9\ud55c\ub2e4\uace0 \uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud574\ub2f9 \uc5f0\uc8fc\uc5d0\uc11c \uc2e4\uc81c\ub85c \uc5b4\ub5a4 \uc120\ud0dd\uc744 \ud558\ub294\uc9c0 \ub4e3\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4. \ub0ae\uc740 \uc18c\ub9ac\ub97c \ub9e1\ub294 \uc545\uae30\ub294 \ud654\uba74\uc758 \uc911\uc2ec\uc5d0\uc11c \ub35c \ubcf4\uc774\uac70\ub098 \uc120\uc728 \ub4a4\uc5d0\uc11c \ub4e4\ub9b4 \uc218 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \ud544\uc694 \uc5c6\ub294 \ubc30\uacbd\uc774\ub77c\uace0 \ud310\ub2e8\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc804\uccb4 \uc18c\ub9ac\uac00 \uc5b4\ub5a4 \ubc14\ud0d5 \uc704\uc5d0 \ub193\uc774\ub294\uc9c0 \ub4e4\uc5b4 \ubcf4\uba74 \ub192\uace0 \ubc1d\uc740 \uc18c\ub9ac\ub9cc \ucad3\uc744 \ub54c\uc640 \ub2e4\ub978 \uc74c\uc545\uc774 \ubcf4\uc77c \uc218 \uc788\ub2e4. \uc774\ub294 \ud2b9\uc815 \uace1\uc758 \ud3b8\uc131\uc744 \uc0c8\ub85c \ub2e8\uc815\ud558\ub294 \ub9d0\uc774 \uc544\ub2c8\ub77c \ud569\uc8fc\ub97c \ub4e3\ub294 \uc81c\uc548\uc774\ub2e4. \ub2e4\uc74c \uc601\uc0c1\uc5d0\uc11c \ud074\ub77c\ub9ac\ub137 \uac00\uc871\uc744 \ucc3e\uc558\ub2e4\uba74 \ub204\uac00 \uac00\uc7a5 \ub208\uc5d0 \ub744\ub294\uc9c0\ubfd0 \uc544\ub2c8\ub77c \uc11c\ub85c \ub2e4\ub978 \ud06c\uae30\uac00 \uc788\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uc77c\ubc18\uc801\uc778 \ud55c \ubaa8\uc2b5\uc73c\ub85c \uae30\uc5b5\ud558\ub358 \uc774\ub984\uc774 \uc5ec\ub7ec \uc74c\uc5ed\uc758 \uac00\uc871\uc73c\ub85c \ubc14\ub010\ub2e4. \uc804\uc2dc\uc7a5\uc774\ub098 \uc545\uae30 \uc18c\uac1c\uc5d0\uc11c \ud06c\uae30\ub97c \ube44\uad50\ud55c \ub4a4 \uc2e4\uc81c \uc18c\ub9ac\ub97c \ub4e4\uc5b4 \ubcf4\uba74, \ubcf4\ub294 \uc815\ubcf4\uc640 \ub4e3\ub294 \uacbd\ud5d8\uc744 \ud568\uaed8 \ub298\ub9b4 \uc218 \uc788\ub2e4. \ud074\ub77c\ub9ac\ub137\uc740 \uc7ac\uc988\uc640 \uc2a4\uc719\uc758 \uc18c\ub9ac\uc640\ub3c4 \uac00\uae5d\ub2e4. \ud544\ud558\ubaa8\ub2c8\uc544\ub294 \ub9ac\ub4ec\uac10 \uc788\uace0 \ubbf8\ub044\ub7ec\uc9c0\ub4ef \uc6c0\uc9c1\uc774\ub294 \ud45c\ud604\uc5d0 \uc5b4\uc6b8\ub9ac\ub294 \uc545\uae30\ub85c \uc18c\uac1c\ud55c\ub2e4. \uacf5\uc5f0\uc7a5\uc758 \ud55c \uc790\ub9ac\ub9cc\uc73c\ub85c \uae30\uc5b5\ud560 \ud544\uc694\ub294 \uc5c6\ub294 \uac83\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \ud074\ub77c\ub9ac\ub137\uc744 \ub9cc\ub098\uba74 \uc774\ub984\uc744 \ub9de\ud78c \ub370\uc11c \uba48\ucd94\uc9c0 \ub9d0\uace0 \ud06c\uae30\uc640 \uc18c\ub9ac\uc758 \uc704\uce58\ub3c4 \uc0b4\ud3b4\ubcf4\uc790. \uac19\uc740 \uac00\uc871\uc774\ub77c\ub294 \ub9d0\uc740 \uc804\ubd80 \ub611\uac19\uc774 \uc0dd\uacbc\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \uc775\uc219\ud55c \uc545\uae30 \uc774\ub984 \ud558\ub098\uac00 \uc0dd\uac01\ubcf4\ub2e4 \ub113\uc740 \ud48d\uacbd\uc744 \uc5f4\uc5b4 \uc904 \uc218 \uc788\ub2e4."}, {"id": "confucius-life-and-learning", "title": "\uacf5\uc790\uc758 \uc0dd\uc560 \u2014 \ubc30\uc6c0\uc740 \uc5b8\uc81c \ub05d\ub098\ub294 \uac78\uae4c", "summary": "\ub178\ub098\ub77c\uc5d0\uc11c \uc5ec\ub7ec \ub098\ub77c\ub97c \uac70\uce5c \uc5ec\uc815, \ub17c\uc5b4\uc758 \ubc30\uc6c0\uacfc \uad00\uacc4\ub97c \ud1b5\ud574 \uacf5\uc790\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Philosophy", "url": "stories/confucius-life-and-learning/index.html", "image": "media/confucius-life-and-learning-cover-20261030.jpg", "alt": "1910\ub144 \uc601\ubb38\ud310 The Sayings of Confucius\uc758 \uc2e4\uc81c \ud45c\uc9c0. \uacf5\uc790\ub97c \ud45c\ud604\ud55c \ud6c4\ub300\uc758 \uc778\ubb3c \uadf8\ub9bc\uacfc \ucc45 \uc81c\ubaa9\uc774 \ubcf4\uc785\ub2c8\ub2e4.", "text": "\uacf5\uc790\uc758 \uc0dd\uc560 \u2014 \ubc30\uc6c0\uc740 \uc5b8\uc81c \ub05d\ub098\ub294 \uac78\uae4c \ub73b\ub300\ub85c \ub418\uc9c0 \uc54a\uc740 \uc815\uce58\uc758 \uae38\uacfc \uc624\ub798 \ub0a8\uc740 \uac00\ub974\uce68 \ub178\ub098\ub77c\uc5d0\uc11c \uc5ec\ub7ec \ub098\ub77c\ub97c \uac70\uce5c \uc5ec\uc815, \ub17c\uc5b4\uc758 \ubc30\uc6c0\uacfc \uad00\uacc4\ub97c \ud1b5\ud574 \uacf5\uc790\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Philosophy \ubb38\ud654 \uc11c\ub978\uc774\uba74 \uc790\ub9ac\ub97c \uc7a1\uace0 \ub9c8\ud754\uc774\uba74 \ud754\ub4e4\ub9ac\uc9c0 \uc54a\uc544\uc57c \ud55c\ub2e4\ub294 \ub9d0\uc744 \ub4e4\uc73c\uba74 \uc624\ud788\ub824 \ub9c8\uc74c\uc774 \uae09\ud574\uc9c8 \uc218 \uc788\ub2e4. \uadf8\ub7f0\ub370 \uadf8 \ub098\uc774\uc758 \ud45c\ud604\uc774 \uc624\ub298\uc758 \ubaa8\ub4e0 \uc0ac\ub78c\uc5d0\uac8c \uc801\uc6a9\ub418\ub294 \uc778\uc0dd \ud3c9\uac00\ud45c\uc600\uc744\uae4c. \uacf5\uc790\uc758 \ub9d0\uc744 \uc77d\ub294 \ucd9c\ubc1c\uc810\uc744 \uc5ec\uae30\uc11c \uc870\uae08 \ubc14\uafb8\uc5b4 \ubcfc \uc218 \uc788\ub2e4. \uacf5\uc790\ub294 \uae30\uc6d0\uc804 551\ub144\uc5d0 \ud0dc\uc5b4\ub098 \uae30\uc6d0\uc804 479\ub144\uc5d0 \uc138\uc0c1\uc744 \ub5a0\ub09c \uc911\uad6d \ucd98\ucd94\uc2dc\ub300\uc758 \uc778\ubb3c\uc774\ub2e4. \ub178\ub098\ub77c\uc5d0\uc11c \ubc30\uc6b0\uace0 \uac00\ub974\ucce4\uc73c\uba70 \uc815\uce58\uc758 \ud604\uc7a5\uc5d0\ub3c4 \ub098\uc130\ub2e4. \ucc98\uc74c\ubd80\ud130 \uc644\uc131\ub41c \uba85\uc5b8\uc758 \uc8fc\uc778\uc774\uc5c8\ub2e4\uae30\ubcf4\ub2e4, \ub73b\ub300\ub85c \ub418\uc9c0 \uc54a\ub294 \ud604\uc2e4 \uc18d\uc5d0\uc11c \uc5b4\ub5bb\uac8c \uc0b4\uace0 \ubc30\uc6b8\uc9c0 \ubb3c\uc5c8\ub358 \uc0ac\ub78c\uc73c\ub85c \ub9cc\ub098 \ubcf4\uc790. \uacf5\uc790\uac00 \uc0b4\ub358 \uc2dc\ub300\uc5d0\ub294 \uc5ec\ub7ec \ub098\ub77c\uc640 \uac15\ud55c \uac00\ubb38\uc774 \ud798\uc744 \uaca8\ub8e8\uc5c8\ub2e4. \uc624\ub798\ub41c \uc9c8\uc11c\uc640 \uc774\ub984\uc740 \ub0a8\uc544 \uc788\uc5b4\ub3c4 \uadf8\uac83\uc774 \uc2e4\uc81c \ud589\ub3d9\uc744 \ud1b5\uc81c\ud558\uc9c0 \ubabb\ud558\ub294 \uc77c\uc774 \ubc8c\uc5b4\uc84c\ub2e4. \uacf5\uc790\uac00 \uc608\uc640 \ubc14\ub978 \ud1b5\uce58\uc5d0 \uad00\uc2ec\uc744 \uac00\uc84c\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uc774\ub7f0 \ubc30\uacbd \uc18d\uc5d0\uc11c \uc774\ud574\ud558\uba74 \ub35c \ucd94\uc0c1\uc801\uc774\ub2e4. \uc608\ub294 \uc624\ub298\uc758 \uc778\uc0ac\ubc95\uc774\ub098 \uc2dd\uc0ac \uc608\uc808 \ubaa9\ub85d\ubcf4\ub2e4 \ub113\uc740 \ubb38\uc81c\ub2e4. \uad00\uacc4 \uc548\uc5d0\uc11c \uc5b4\ub5a4 \ud0dc\ub3c4\ub85c \ud589\ub3d9\ud558\uba70, \uc774\ub984\uc5d0 \uac78\ub9de\uc740 \ucc45\uc784\uc744 \uc5b4\ub5bb\uac8c \uc218\ud589\ud560 \uac83\uc778\uac00\uc640 \uc774\uc5b4\uc9c4\ub2e4. \uac89\uc73c\ub85c \uc758\uc2dd\uc744 \uc815\ud655\ud788 \uce58\ub974\ub294 \uc77c\uacfc \ub2e4\ub978 \uc0ac\ub78c\uc744 \uc81c\ub300\ub85c \ub300\ud558\ub294 \uc77c\uc774 \ub5a8\uc5b4\uc838 \ubc84\ub9b4 \ub54c \ubb34\uc5c7\uc774 \ub0a8\ub290\ub0d0\ub294 \uc9c8\ubb38\uc73c\ub85c \ub4e4\uc5b4\uac00\ub3c4 \uc88b\ub2e4. \uacf5\uc790\ub294 \ubc30\uc6b0\uace0 \uac00\ub974\uce58\ub294 \uc0ac\ub78c\uc73c\ub85c \uc54c\ub824\uc84c\uc9c0\ub9cc \uc815\uce58\uc640 \ubb34\uad00\ud558\uac8c \uad50\uc2e4\uc5d0\ub9cc \uba38\ubb34\ub978 \uc778\ubb3c\uc740 \uc544\ub2c8\ub2e4. \ub178\ub098\ub77c\uc5d0\uc11c \uad00\uc9c1\uc744 \ub9e1\uc558\uace0, \uc790\uc2e0\uc774 \uc0dd\uac01\ud55c \ubc14\ub978 \ud1b5\uce58\uac00 \ud604\uc2e4\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc9c0\uae30\ub97c \ubc14\ub790\ub2e4. \ub2e4\ub9cc \uc804\ud574\uc9c0\ub294 \uad00\uc9c1\uc758 \uc138\ubd80\uc640 \uc77c\ud654\uc5d0\ub294 \ud6c4\ub300\uc758 \uc124\uba85\uc774 \uc5bd\ud600 \uc788\uc73c\ubbc0\ub85c \ubaa8\ub4e0 \uc7a5\uba74\uc744 \uadf8\ub300\ub85c \ud604\uc7a5 \uae30\ub85d\ucc98\ub7fc \uc77d\uc9c0\ub294 \ub9d0\uc790. \uc911\uc694\ud55c \uac83\uc740 \uc0dd\uac01\uacfc \ud604\uc2e4\uc758 \uac70\ub9ac\uac00 \uadf8\uc758 \uc0dd\uc560 \uc548\uc5d0 \uc788\uc5c8\ub2e4\ub294 \uc810\uc774\ub2e4. \ubc14\ub978 \ub9d0\uc744 \uc548\ub2e4\uace0 \ud574\uc11c \uad8c\ub825\uc790\uac00 \uace7 \ub530\ub974\ub294 \uac83\ub3c4, \uc81c\ub3c4\uac00 \uc790\ub3d9\uc73c\ub85c \ubc14\ub00c\ub294 \uac83\ub3c4 \uc544\ub2c8\uc5c8\ub2e4. \uacf5\uc790\ub97c \ub298 \uc131\uacf5\ud55c \uc870\uc5b8\uc790\ub85c\ub9cc \uc0c1\uc0c1\ud558\uba74 \uc624\ud788\ub824 \ubc30\uc6c0\uc774 \uc65c \ud3c9\uc0dd\uc758 \uc77c\uc774 \ub418\uc5c8\ub294\uc9c0 \uc774\ud574\ud558\uae30 \uc5b4\ub835\ub2e4. \ub178\ub098\ub77c\ub97c \ub5a0\ub09c \ub4a4 \uacf5\uc790\ub294 \uc81c\uc790\ub4e4\uacfc \uc5ec\ub7ec \ub098\ub77c\ub97c \ub2e4\ub154\ub2e4. \uc790\uc2e0\uc758 \uc0dd\uac01\uc744 \ubc1b\uc544\ub4e4\uc77c \ud1b5\uce58\uc790\uc640 \uc790\ub9ac\ub97c \ucc3e\ub294 \uc5ec\uc815\uc774\uc5c8\uc9c0\ub9cc \uacc4\uc18d \ud658\uc601\ubc1b\uc740 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc815\uce58\uc801 \uc870\uac74\uacfc \uc0ac\ub78c\ub4e4\uc758 \uc774\ud574\uad00\uacc4\ub294 \uc774\uc0c1\uacfc \ub2e4\ub974\uac8c \uc6c0\uc9c1\uc600\ub2e4. \uc774\ub3d9\uc5d0\ub294 \uae30\ub300\ubfd0 \uc544\ub2c8\ub77c \uace4\ub780\uacfc \uc2e4\ub9dd\ub3c4 \uc788\uc5c8\ub2e4. \uc5ec\ud589\uc744 \ud588\ub2e4\ub294 \uc0ac\uc2e4 \uc790\uccb4\ubcf4\ub2e4 \ub73b\uc774 \ubc1b\uc544\ub4e4\uc5ec\uc9c0\uc9c0 \uc54a\uc744 \ub54c \uc5b4\ub5bb\uac8c \uc0b4\uc544\uac14\ub294\uc9c0\uac00 \uc911\uc694\ud558\ub2e4. \uacf5\uc790\uc640 \uc81c\uc790\ub4e4\uc758 \uad00\uacc4, \uc9c8\ubb38\uacfc \ub300\ub2f5\ub3c4 \uadf8\ub7f0 \uc2dc\uac04 \uc548\uc5d0 \uc788\uc5c8\ub2e4. \ud6d7\ub0a0\uc758 \ud070 \uba85\uc131\uc774 \ub2f9\ub300\uc758 \uc548\uc815\ub41c \uc131\uacf5\uc744 \uadf8\ub300\ub85c \ub73b\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\uc744 \uae30\uc5b5\ud560 \uc218 \uc788\ub2e4. \u300e\ub17c\uc5b4\u300f\ub294 \uacf5\uc790\uac00 \uc790\uc2e0\uc758 \ucca0\ud559\uc744 \ucc98\uc74c\ubd80\ud130 \ub05d\uae4c\uc9c0 \uccb4\uacc4\uc801\uc73c\ub85c \uc801\uc5b4 \ucd9c\ud310\ud55c \ucc45\uc774 \uc544\ub2c8\ub2e4. \uacf5\uc790\uc640 \uc81c\uc790\ub4e4\uc758 \ub9d0\uacfc \ud589\ub3d9\uc5d0 \uad00\ud55c \uc804\uc2b9\uc774 \ud6c4\ub300\uc5d0 \ubaa8\uc774\uace0 \uc815\ub9ac\ub41c \uc790\ub8cc\ub2e4. \uc6b0\ub9ac\uac00 \uc77d\ub294 \ubaa9\uc18c\ub9ac\uc5d0\ub294 \uc804\ub2ec\uacfc \ud3b8\uc9d1\uc758 \uc2dc\uac04\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \uadf8\ub798\uc11c \ud55c \uad6c\uc808\uc744 \uc5ed\uc0ac \uc18d \uc5b4\ub290 \ub0a0\uc758 \ubc1c\uc5b8\uacfc \uc644\uc804\ud788 \uac19\uc740 \ub179\ucde8\ub85c \ubcf4\uae30\ub294 \uc5b4\ub835\ub2e4. \uadf8\ub807\ub2e4\uace0 \uac00\ub974\uce68\uc758 \uc758\ubbf8\uac00 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \uc9c8\ubb38\uc5d0 \uc5b4\ub5a4 \ub2f5\uc774 \ub193\uc600\ub294\uc9c0 \uc0b4\ud53c\uba74, \ub204\uad6c\uc5d0\uac8c\ub098 \uac19\uc740 \ubb38\uc7a5 \ud558\ub098\ub97c \uac74\ub124\uae30\ubcf4\ub2e4 \uad00\uacc4\uc640 \uc0c1\ud669\uc744 \uc0dd\uac01\ud558\ub294 \uc77d\uae30\uac00 \uac00\ub2a5\ud574\uc9c4\ub2e4. \uc704\uc815\ud3b8\uc5d0\ub294 \uc5f4\ub2e4\uc12f\uc5d0 \ubc30\uc6c0\uc5d0 \ub73b\uc744 \ub450\uace0, \uc11c\ub978\uc5d0 \uc11c\uace0, \ub9c8\ud754\uc5d0 \ubbf8\ud639\ub418\uc9c0 \uc54a\uc558\ub2e4\ub294 \uc2dd\uc758 \uc0dd\uc560 \ud68c\uace0\uac00 \ub098\uc628\ub2e4. \uc270\uacfc \uc608\uc21c\uc744 \uac70\uccd0 \uc77c\ud754\uc5d0\ub294 \uc6d0\ud558\ub294 \ub300\ub85c \ud574\ub3c4 \uae30\uc900\uc744 \ub118\uc9c0 \uc54a\ub294 \uacbd\uc9c0\uc5d0 \uc774\ub974\ub800\ub2e4\uace0 \uc804\ud55c\ub2e4. \ubc30\uc6b0\uace0 \ub2e4\ub4ec\ub294 \uae34 \uc2dc\uac04\uc744 \ub3cc\uc544\ubcf4\ub294 \ud615\uc2dd\uc774\ub2e4. \uc774\uac83\uc744 \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \uac19\uc740 \ub098\uc774\uc5d0 \ub611\uac19\uc774 \ub2ec\uc131\ud574\uc57c \ud55c\ub2e4\ub294 \uaddc\uce59\uc73c\ub85c \ubc14\uafb8\uba74 \ubb38\uc7a5\uc758 \ubc29\ud5a5\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \ub0a8\uc758 \uc18d\ub3c4\ub97c \ud3c9\uac00\ud558\ub294 \ub370 \uc4f0\uae30\ubcf4\ub2e4, \uc9c0\uc2dd\uacfc \ubab8\uc5d0 \ubc34 \ud589\ub3d9\uc774 \uac00\uae4c\uc6cc\uc9c0\ub824\uba74 \uc2dc\uac04\uc774 \ud544\uc694\ud558\ub2e4\ub294 \ub73b\uc73c\ub85c \uc77d\uc5b4 \ubcfc \uc218 \uc788\ub2e4. \uc775\uc219\ud55c \ub9d0\ub3c4 \uc6d0\ub798\uc758 \ud68c\uace0 \ud615\uc2dd \uc548\uc5d0 \ub193\uc73c\uba74 \uc870\uae08 \ubd80\ub4dc\ub7fd\uac8c \ub2e4\uac00\uc628\ub2e4. \u300e\ub17c\uc5b4\u300f\uc5d0\uc11c\ub294 \ubc30\uc6b0\ub294 \uc77c\uacfc \uc0dd\uac01\ud558\ub294 \uc77c\uc744 \ud568\uaed8 \uac15\uc870\ud55c\ub2e4. \uc815\ubcf4\ub97c \ub9ce\uc774 \uc5bb\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ud310\ub2e8\uc774 \uc88b\uc544\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\uace0, \uc790\ub8cc \uc5c6\uc774 \uc790\uae30 \uc0dd\uac01\ub9cc \ubc18\ubcf5\ud558\ub294 \uac83\ub3c4 \ucda9\ubd84\ud558\uc9c0 \uc54a\ub2e4. \ubc30\uc6b4 \uac83\uc744 \uc790\uae30 \uacbd\ud5d8\uacfc \ud310\ub2e8 \uc18d\uc5d0\uc11c \ub2e4\uc2dc \uc0b4\ud53c\ub294 \uc655\ubcf5\uc774 \ud544\uc694\ud558\ub2e4. \uc624\ub298\uc758 \ub3c5\uc790\uc5d0\uac8c\ub3c4 \ub0af\uc124\uc9c0 \uc54a\uc740 \ubb38\uc81c\ub2e4. \ucc45\uc5d0\uc11c \ub9c8\uc74c\uc5d0 \ub4dc\ub294 \uad6c\uc808\uc744 \ucc3e\uc558\uc744 \ub54c \uadf8\uac83\uc744 \uc678\uc6b0\ub294 \ub370\uc11c \uba48\ucd94\uc9c0 \uc54a\uace0 \uc5b4\ub5a4 \uc0c1\ud669\uc5d0 \ub9de\uc73c\uba70 \uc5b4\ub5a4 \uacbd\uc6b0\uc5d0\ub294 \uc124\uba85\uc774 \ub354 \ud544\uc694\ud55c\uc9c0 \uc0dd\uac01\ud574 \ubcfc \uc218 \uc788\ub2e4. \uc774\ub294 \uacf5\uc790\uc758 \uc2e4\uc81c \ub300\ud654\ub97c \uadf8\ub300\ub85c \uc778\uc6a9\ud55c \uc608\uac00 \uc544\ub2c8\ub77c \uac00\ub974\uce68\uc744 \ud604\uc7ac\uc758 \uc77d\uae30\uc5d0 \uc5f0\uacb0\ud574 \ubcf4\ub294 \ubc29\ubc95\uc774\ub2e4. \uc778\uc774\ub77c\ub294 \ub9d0\uc740 \ubc88\uc5ed \ud55c \ub2e8\uc5b4\ub85c \ubaa8\ub450 \ub2f4\uae30 \uc5b4\ub835\uc9c0\ub9cc \uc0ac\ub78c\uc744 \ub300\ud558\ub294 \ud0dc\ub3c4\ub97c \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ub610 \uc790\uc2e0\uc774 \uc6d0\ud558\uc9c0 \uc54a\ub294 \uc77c\uc744 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uac15\uc694\ud558\uc9c0 \ub9d0\ub77c\ub294 \uac00\ub974\uce68\uc740 \uc0c1\ub300\uc758 \uc785\uc7a5\uc744 \ub3cc\uc544\ubcf4\ub294 \ucd9c\ubc1c\uc810\uc774 \ub41c\ub2e4. \ub73b\uc744 \uc54c\uace0 \uc788\ub2e4\ub294 \uac83\uacfc \ubd88\ud3b8\ud55c \uc21c\uac04\uc5d0 \uc2e4\uc81c\ub85c \uadf8\ub807\uac8c \ud589\ub3d9\ud558\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \uac00\ub839 \ub2e4\ub978 \uc0ac\ub78c\uc774 \ub9d0\uc744 \ub04a\uc744 \ub54c \ubd88\ucf8c\ud558\ub2e4\uba74 \ub098\ub3c4 \uc0c1\ub300\uc758 \ub9d0\uc744 \ub05d\uae4c\uc9c0 \ub4e3\ub294\uc9c0 \ub3cc\uc544\ubcfc \uc218 \uc788\ub2e4. \uc774\ub7f0 \uc791\uc740 \uc608\uac00 \uc778\uc774\ub098 \uc11c\uc758 \ubaa8\ub4e0 \ub73b\uc744 \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub2e4\ub9cc \ud070 \ucca0\ud559\uc801 \uc774\ub984\uc744 \uc77c\uc0c1\uc758 \uad6c\uccb4\uc801\uc778 \uad00\uacc4\uc5d0 \uc5f0\uacb0\ud558\ub294 \uccab\uac78\uc74c\uc740 \ub420 \uc218 \uc788\ub2e4. \uad00\uacc4\uc758 \uc870\ud654\uac00 \uc5b8\uc81c\ub098 \ud798\uc5c6\ub294 \uc0ac\ub78c\ub9cc \ucc38\uc544\uc57c \ud55c\ub2e4\ub294 \ub73b\uc73c\ub85c \uad73\uc5b4\uc838\uc11c\ub3c4 \uc548 \ub41c\ub2e4. \ub9d0\ub144\uc5d0 \ub178\ub098\ub77c\ub85c \ub3cc\uc544\uc628 \uacf5\uc790\ub294 \uac00\ub974\uce68\uacfc \uc61b \uc790\ub8cc\ub97c \ub2e4\ub8e8\ub294 \uc77c\uc5d0 \ud798\uc744 \uc3df\uc740 \uc778\ubb3c\ub85c \uc804\ud574\uc9c4\ub2e4. \uc624\ub298 \ub0a8\uc740 \uba85\uc131\ub9cc \ubcf4\uace0 \uc0dd\uc560 \uc804\uccb4\uac00 \uc21c\ud0c4\ud588\ub2e4\uace0 \uc0dd\uac01\ud558\uba74 \ud604\uc2e4\uacfc \ubd80\ub52a\uce58\ub358 \uc2dc\uac04\uc744 \ub193\uce5c\ub2e4. \uc815\uce58\uc5d0\uc11c \ub73b\uc744 \ubaa8\ub450 \ud3bc\uce58\uc9c0 \ubabb\ud55c \uc0b6\uacfc \uc624\ub798 \uc804\ud574\uc9c4 \uac00\ub974\uce68\uc774 \ud55c \uc0ac\ub78c \uc548\uc5d0 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 1910\ub144\uc5d0 \ucd9c\ud310\ub41c \u300eThe Sayings of Confucius\u300f\uc758 \uc2e4\uc81c \ud45c\uc9c0\ub2e4. \uc778\ubb3c \uadf8\ub9bc\uc740 \ud6c4\ub300 \ucd9c\ud310\ubb3c\uc774 \ud45c\ud604\ud55c \uacf5\uc790\uc758 \ubaa8\uc2b5\uc774\uba70, \uacf5\uc790\uac00 \uc0b4\ub358 \uc2dc\ub300\uc5d0 \uadf8\ub9b0 \ucd08\uc0c1\uc740 \uc544\ub2c8\ub2e4. \uacf5\uc790\ub97c \uc624\ub798\ub41c \uba85\ub839\uc758 \ubaa9\uc18c\ub9ac\ub85c\ub9cc \ub9cc\ub098\uae30\ubcf4\ub2e4, \ubc30\uc6b4 \uac83\uc744 \uc0b6\uc5d0 \uc775\ud788\ub824\uba74 \uc65c \uae34 \uc2dc\uac04\uc774 \ud544\uc694\ud55c\uc9c0 \ubb3b\ub294 \uc0ac\ub78c\uc73c\ub85c \uc77d\uc5b4 \ubcf4\uc790. \uc9c0\uae08 \ubc30\uc6b0\ub294 \uac83\uc774 \uc544\uc9c1 \uc788\ub2e4\uba74 \uadf8 \uc9c8\ubb38\uc744 \uc2dc\uc791\ud560 \uc790\ub9ac\ub3c4 \ub0a8\uc544 \uc788\ub2e4."}, {"id": "david-recamier-empty-space", "title": "\ub808\uce74\ubbf8\uc5d0 \ubd80\uc778\uc758 \ucd08\uc0c1 \u2014 \ube48 \uacf5\uac04\uc774 \uc0ac\ub78c\uc744 \ub3cb\ubcf4\uc774\uac8c \ud560 \ub54c", "summary": "\ub2e4\ube44\ub4dc\uc758 \ucd08\uc0c1\uc5d0\uc11c \uc790\uc138\uc640 \uac00\uad6c, \ub113\uac8c \ub0a8\uc740 \ubc30\uacbd\uc774 \ub9cc\ub4dc\ub294 \uc778\uc0c1\uc744 \uc2e4\uc81c \ub3c4\ud310\uacfc \ud568\uaed8 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Art", "url": "stories/david-recamier-empty-space/index.html", "image": "media/david-recamier-empty-space.jpg", "alt": "\ub2e4\ube44\ub4dc\uc758 \ub808\uce74\ubbf8\uc5d0 \ubd80\uc778 \ucd08\uc0c1\uc744 \uc7ac\ud604\ud55c \uc61b \ub3c4\ud310. \ud770 \ub4dc\ub808\uc2a4\ub97c \uc785\uc740 \uc778\ubb3c\uc774 \uae34 \uc758\uc790\uc5d0 \uae30\ub300\uace0 \uc67c\ucabd\uc5d0 \ub4f1\uc794\ub300\uac00 \uc11c \uc788\uc2b5\ub2c8\ub2e4.", "text": "\ub808\uce74\ubbf8\uc5d0 \ubd80\uc778\uc758 \ucd08\uc0c1 \u2014 \ube48 \uacf5\uac04\uc774 \uc0ac\ub78c\uc744 \ub3cb\ubcf4\uc774\uac8c \ud560 \ub54c \ud770 \ub4dc\ub808\uc2a4\uc640 \uae34 \uc758\uc790, \ub05d\ub0b4 \uc644\uc131\ub418\uc9c0 \uc54a\uc740 \uadf8\ub9bc \ub2e4\ube44\ub4dc\uc758 \ucd08\uc0c1\uc5d0\uc11c \uc790\uc138\uc640 \uac00\uad6c, \ub113\uac8c \ub0a8\uc740 \ubc30\uacbd\uc774 \ub9cc\ub4dc\ub294 \uc778\uc0c1\uc744 \uc2e4\uc81c \ub3c4\ud310\uacfc \ud568\uaed8 \uc77d\uc2b5\ub2c8\ub2e4. Art \ubb38\ud654 \ucd08\uc0c1\ud654\ub77c\uba74 \uc778\ubb3c\uc758 \uc5bc\uad74\uc774 \uac00\uc7a5 \uc911\uc694\ud560 \uac83 \uac19\ub2e4. \uadf8\ub7f0\ub370 \ub2e4\ube44\ub4dc\uc758 \u3008\ub808\uce74\ubbf8\uc5d0 \ubd80\uc778\uc758 \ucd08\uc0c1\u3009\uc5d0\uc11c\ub294 \uc5bc\uad74\ubcf4\ub2e4 \uba3c\uc800 \uae38\uac8c \ub193\uc778 \uc758\uc790\uc640 \ud770\uc637, \ub113\uace0 \uc870\uc6a9\ud55c \ubc30\uacbd\uc774 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \ubc29\uc744 \uac00\ub4dd \ucc44\uc6b8 \uc218\ub3c4 \uc788\uc5c8\uc744 \ubb3c\uac74\ub4e4\uc774 \ube60\uc838 \uc788\uc5b4\uc11c \uc624\ud788\ub824 \uc0ac\ub78c\uc774 \ub610\ub837\ud574 \ubcf4\uc778\ub2e4. \ubb34\uc5c7\uc744 \ub354 \uadf8\ub838\ub294\uc9c0\ubfd0 \uc544\ub2c8\ub77c \ubb34\uc5c7\uc774 \uc801\uac8c \ub193\uc600\ub294\uc9c0\ub3c4 \uc0b4\ud3b4\ubcf4\uc790. \uc774 \uadf8\ub9bc\uc740 \ub05d\ub0b4 \uc644\uc131\ub418\uc9c0 \uc54a\uc740 \uc791\ud488\uc73c\ub85c \uc804\ud574\uc9c4\ub2e4. \uadf8 \uc0ac\uc2e4\uc744 \uc54c\uace0 \ubcf4\uba74 \ube44\uc5b4 \uc788\ub294 \ub4ef\ud55c \ubd80\ubd84\uc744 \ub2e8\uc21c\ud788 \ubd80\uc871\ud55c \uc790\ub9ac\ub85c\ub9cc \uc77d\uc9c0 \uc54a\uac8c \ub41c\ub2e4. \ub808\uce74\ubbf8\uc5d0 \ubd80\uc778\uc740 \uae34 \uc758\uc790 \uc704\uc5d0 \ubab8\uc744 \uae30\ub300\uace0 \uc788\ub2e4. \ubab8\uc774 \ubed7\uc740 \ubc29\ud5a5\uacfc \uace0\uac1c\uac00 \ub3cc\uc544\uc628 \ubc29\ud5a5\uc774 \ub2e4\ub974\ub2e4. \ubab8\uc758 \uae38\uace0 \ub290\uae0b\ud55c \ud750\ub984\uc744 \ub530\ub77c\uac00\ub2e4\uac00 \uc5bc\uad74\uc5d0\uc11c \ub2e4\uc2dc \uad00\ub78c\uc790 \ucabd\uc73c\ub85c \uc2dc\uc120\uc774 \ub3cc\uc544\uc628\ub2e4. \uac00\ub9cc\ud788 \uc549\uc544 \uc788\uc5b4\ub3c4 \ud654\uba74\uc5d0\ub294 \uc6c0\uc9c1\uc784\uc758 \ubc29\ud5a5\uc774 \uc0dd\uae34\ub2e4. \ubab8\uc744 \uc815\uba74\uc73c\ub85c \uc138\uc6b0\uace0 \uc5bc\uad74\uc744 \uac00\uc6b4\ub370 \ub454 \ucd08\uc0c1\uacfc \ube44\uad50\ud558\uba74 \ucc28\uc774\uac00 \ubd84\uba85\ud558\ub2e4. \uc6b0\ub9ac\ub294 \uc778\ubb3c\uc744 \uace7\uc7a5 \ub9c8\uc8fc\ubcf4\uae30\ubcf4\ub2e4 \uadf8\ub140\uac00 \ub193\uc778 \uacf5\uac04\uacfc \uc790\uc138\ub97c \uac70\uccd0 \uc5bc\uad74\uc5d0 \ub3c4\ucc29\ud55c\ub2e4. \uc774\uac83\uc744 \uc2e4\uc81c \ubaa8\ub378\uc758 \uc131\uaca9\uc774\ub098 \ub9c8\uc74c \uc0c1\ud0dc\uc5d0 \ub300\ud55c \uc99d\uac70\ub85c \ub2e8\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uadf8\ub9bc\uc774 \uad00\ub78c\uc790\ub97c \ub9cc\ub098\uac8c \ud558\ub294 \ubc29\uc2dd\uc73c\ub85c \ubcf4\uba74 \ucda9\ubd84\ud558\ub2e4. \ud770 \ub4dc\ub808\uc2a4\ub294 \uc778\ubb3c\uc758 \uc0c1\uccb4\uc640 \ub2e4\ub9ac, \uc758\uc790\uc758 \uac00\uc7a5\uc790\ub9ac\ub85c \uae38\uac8c \uc774\uc5b4\uc9c4\ub2e4. \ubc30\uacbd\uc774 \uc0c1\ub300\uc801\uc73c\ub85c \uc5b4\ub461\uace0 \ucc28\ubd84\ud574\uc11c \ubc1d\uc740 \ucc9c\uc758 \uba74\uc774 \ub354 \uc27d\uac8c \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uc5bc\uad74\uc774 \ucc28\uc9c0\ud558\ub294 \ud06c\uae30\ub294 \uc791\uc9c0\ub9cc \uadf8\ucabd\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \ubc1d\uc740 \ud750\ub984\uc740 \ud6e8\uc52c \ub113\ub2e4. \uc637\uac10\uc774 \uc811\ud788\uace0 \ubc14\ub2e5 \ucabd\uc73c\ub85c \ub0b4\ub824\uc624\ub294 \ubd80\ubd84\uc744 \ucc9c\ucc9c\ud788 \ubcf4\uc790. \uac19\uc740 \ud770\uc0c9 \uc548\uc5d0\ub3c4 \uadf8\ub298\uacfc \ube5b\uc758 \ucc28\uc774\uac00 \uc788\ub2e4. \ube5b\ub098\ub294 \uc7a5\uc2e0\uad6c\ub97c \ub9ce\uc774 \uadf8\ub9ac\uc9c0 \uc54a\uc544\ub3c4 \ubc1d\uc740 \uba74\uacfc \uc8fc\ubcc0 \uc0c9\uc758 \ub300\ube44\ub9cc\uc73c\ub85c \uc778\ubb3c\uc758 \uc790\ub9ac\ub97c \uac15\uc870\ud560 \uc218 \uc788\ub2e4. \uc801\uc740 \uc0c9\uc774 \uace7 \ub2e8\uc21c\ud55c \ud6a8\uacfc\ub9cc \ub9cc\ub4e0\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc778\ubb3c\uc774 \uae30\ub300\ub294 \uac00\uad6c\ub294 \uc591\ub05d\uc774 \uc62c\ub77c\uac04 \uae34 \ud615\ud0dc\ub2e4. \ubab8\uc740 \uadf8 \uc704\uc5d0\uc11c \uc606\uc73c\ub85c \ubed7\uace0 \ud314\uc740 \ub465\uadfc \ubc1b\uce68 \uac00\uae4c\uc774\uc5d0 \ub193\uc778\ub2e4. \uac00\uad6c\uac00 \uc5c6\ub2e4\uba74 \uc774 \uc790\uc138\ub3c4 \uac19\uc740 \uc778\uc0c1\uc744 \ub9cc\ub4e4\uae30 \uc5b4\ub835\ub2e4. \uc758\uc790\ub294 \uc0ac\ub78c \ub4a4\uc758 \uc18c\ud488\uc774\uba74\uc11c \ubab8\uc758 \ubaa8\uc591\uc744 \uad6c\uc131\ud558\ub294 \uc7a5\uce58\ub2e4. \uc61b \ub3c4\ub85d\uc740 \uc774 \uac00\uad6c\ub97c \uc5e0\ud30c\uc774\uc5b4 \uc591\uc2dd\uc758 \uc18c\ud30c\ub85c \uc124\uba85\ud55c\ub2e4. \ub0af\uc120 \uc591\uc2dd \uc774\ub984\uc744 \uc678\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \uc120\uc758 \ud615\ud0dc\ub97c \ubcf4\uba74 \ub41c\ub2e4. \uace7\uc740 \ub2e4\ub9ac\uc640 \uace1\uc120\uc73c\ub85c \uc62c\ub77c\uac04 \ub05d\ubd80\ubd84\uc774 \ud654\uba74 \uc548\uc5d0\uc11c \uc5b4\ub5a4 \uc724\uacfd\uc744 \ub9cc\ub4dc\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uc778\ubb3c\uc758 \ubd80\ub4dc\ub7ec\uc6b4 \uc637\uacfc \uac00\uad6c\uc758 \ub610\ub837\ud55c \uc120\uc774 \uc11c\ub85c \ub2e4\ub978 \ud45c\uc815\uc744 \ub0b8\ub2e4. \ud654\uba74 \uc67c\ucabd\uc5d0\ub294 \ub192\uace0 \uac00\ub290\ub2e4\ub780 \ub4f1\uc794\ub300\uac00 \uc11c \uc788\ub2e4. \ubb3c\uac74\uc774 \ub9ce\uc9c0 \uc54a\uc740 \uacf5\uac04\uc5d0\uc11c \uc774 \uc138\ub85c\uc120\uc740 \uaf64 \uac15\ud55c \uc5ed\ud560\uc744 \ud55c\ub2e4. \uae38\uac8c \ub204\uc6b4 \uc778\ubb3c\uacfc \uac00\uad6c\uac00 \ub9cc\ub4dc\ub294 \uac00\ub85c \ubc29\ud5a5\uc5d0 \ub2e4\ub978 \ubc29\ud5a5\uc744 \ub193\uc544 \uc900\ub2e4. \ube44\uc5b4 \uc788\ub294 \ubc30\uacbd \uc18d\uc5d0\uc11c \ub192\uc774\ub3c4 \ub290\uaef4\uc9c0\uac8c \ud55c\ub2e4. \uc774 \ubb3c\uac74\uc5d0 \ubc18\ub4dc\uc2dc \ud558\ub098\uc758 \ube44\ubc00 \uc0c1\uc9d5\uc774 \uc788\ub2e4\uace0 \uc815\ud574 \ub193\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \uba3c\uc800 \uc2e4\uc81c\ub85c \ubcf4\uc774\ub294 \uc704\uce58\uc640 \ud06c\uae30, \uc724\uacfd\uc744 \uc0b4\ud3b4\ubcf4\uba74 \ub41c\ub2e4. \ubb3c\uac74\uc774 \uc801\uc744\uc218\ub85d \uc791\uc740 \ucc28\uc774\uac00 \ud06c\uac8c \ub290\uaef4\uc9c4\ub2e4. \ucd08\uc0c1\ud654\ub97c \uc77d\ub294 \ub370 \ud56d\uc0c1 \uc778\ubb3c\uc758 \uc2e0\ubd84\uc744 \uc54c\ub824 \uc8fc\ub294 \uc228\uc740 \uc554\ud638\uac00 \ud544\uc694\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \ubc30\uacbd\uc5d0\ub294 \uad6c\uccb4\uc801\uc778 \uc0dd\ud65c\uc758 \ud754\uc801\uc774 \ub9ce\uc9c0 \uc54a\ub2e4. \ucc45\uc7a5\uacfc \ucc3d\ubb38, \uc190\ub2d8\uacfc \ud654\ub824\ud55c \uc7a5\uc2dd\uc73c\ub85c \uc778\ubb3c\uc758 \uc0b6\uc744 \uc124\uba85\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc5bc\uad74\uacfc \uc790\uc138, \uc637\uacfc \uac00\uad6c\uac00 \ub354 \ub9ce\uc740 \ubaab\uc744 \ub9e1\ub294\ub2e4. \uc2e4\uc81c \ubc29\uc774 \uadf8\ub300\ub85c \uc774\ub807\uac8c \ube44\uc5b4 \uc788\uc5c8\ub2e4\uace0 \uc99d\uba85\ud558\ub294 \uadf8\ub9bc\ub3c4 \uc544\ub2c8\ub2e4. \ucd08\uc0c1\ud654\ub294 \ud604\uc2e4\uc758 \ubaa8\ub4e0 \uac83\uc744 \ube60\uc9d0\uc5c6\uc774 \uc62e\uae30\ub294 \ubaa9\ub85d\uc774 \uc544\ub2c8\ub2e4. \ubb34\uc5c7\uc744 \ud654\uba74\uc5d0 \ub193\uace0 \ubb34\uc5c7\uc744 \ub35c \ubcf4\uc5ec \uc904\uc9c0 \uc120\ud0dd\ud55c \uacb0\uacfc\ub2e4. \uc774 \uadf8\ub9bc\uc5d0\uc11c\ub294 \uc8fc\ubcc0 \uc774\uc57c\uae30\uac00 \uc904\uc5b4\ub4e0 \uc790\ub9ac\uc5d0 \uc778\ubb3c\uc758 \uc724\uacfd\uacfc \uc0c9\uc758 \uad00\uacc4\uac00 \ub0a8\ub294\ub2e4. \ub9d0\uc218\uac00 \uc801\uc740 \uacf5\uac04\uc774 \uc624\ud788\ub824 \ub208\uc744 \uc624\ub798 \uba38\ubb3c\uac8c \ud560 \uc218 \uc788\ub2e4. \ub3c4\ub85d\uc740 \uc774 \uc791\ud488\uc774 \uc644\uc131\ub418\uc9c0 \uc54a\uc740 \uc0c1\ud0dc\ub85c \ub0a8\uc558\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uadf8\ub798\uc11c \uc5b4\ub5a4 \ubd80\ubd84\uc758 \ub35c \ub2e4\ub4ec\uc5b4\uc9c4 \ub290\ub08c\uc744 \ubcfc \ub54c\ub3c4 \uadf8\uac83\uc744 \ub2e8\uc21c\ud788 \uc6d0\ub798 \uc758\ub3c4\ud55c \uc644\uc131 \ud6a8\uacfc\ub77c\uace0 \ud655\uc815\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc624\ub298 \uc6b0\ub9ac\uac00 \uac10\uc0c1\ud558\ub294 \ubaa8\uc2b5\uacfc \ud654\uac00\uac00 \ub05d\uae4c\uc9c0 \uc644\uc131\ud588\uc744 \ubaa8\uc2b5\uc740 \uac19\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubbf8\uc644\uc131\uc774\ub2c8 \ubcfc \uac83\uc774 \uc801\ub2e4\ub294 \ub73b\ub3c4 \uc544\ub2c8\ub2e4. \ud604\uc7ac \ub0a8\uc740 \uadf8\ub9bc \uc548\uc5d0\uc11c \ubc1d\uc740 \uc637\uacfc \ucc28\ubd84\ud55c \ubc30\uacbd, \uc815\ub9ac\ub41c \uac00\uad6c\uc758 \uc724\uacfd\uc740 \ubd84\uba85\ud788 \uc791\ub3d9\ud55c\ub2e4. \ubbf8\uc644\uc131\uc774\ub77c\ub294 \uc5ed\uc0ac\uc801 \uc0c1\ud0dc\uc640 \uc9c0\uae08\uc758 \uac10\uc0c1 \ud6a8\uacfc\ub97c \uad6c\ubd84\ud558\uba74 \ub458 \uc911 \ud558\ub098\ub97c \uc9c0\uc6b8 \ud544\uc694 \uc5c6\uc774 \uadf8\ub9bc\uc744 \ubcfc \uc218 \uc788\ub2e4. \uc790\ud06c \ub8e8\uc774 \ub2e4\ube44\ub4dc\ub294 \ud601\uba85\uacfc \ub098\ud3f4\ub808\uc639 \uc2dc\ub300\uc758 \uc5ed\uc0ac\ud654\ub85c\ub3c4 \uc54c\ub824\uc838 \uc788\ub2e4. \uc5ec\ub7ec \uc778\ubb3c\uacfc \uc758\uc2dd\uc744 \ud06c\uac8c \ubc30\uce58\ud55c \uc791\ud488\ub4e4\uc744 \ub5a0\uc62c\ub9ac\uba74 \uc774 \ucd08\uc0c1\uc758 \uc801\uc740 \uc694\uc18c\uac00 \ub354 \ud765\ubbf8\ub85c\uc6cc\uc9c4\ub2e4. \ud55c \ud654\uac00\uac00 \uadf8\ub9b0 \uadf8\ub9bc\uc774\ub77c\uace0 \ub298 \uac19\uc740 \uaddc\ubaa8\uc640 \ubaa9\uc18c\ub9ac\ub85c \ub9d0\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc61b \ub3c4\ub85d\uc740 \uadf8\uc758 \uc5ec\ub7ec \uc791\ud488\uc744 \uac15\ud558\uac8c \ud3c9\uac00\ud558\uc9c0\ub9cc \uadf8 \ud3c9\uac00\ub97c \uadf8\ub300\ub85c \uc624\ub298\uc758 \uc815\ub2f5\uc73c\ub85c \uc0bc\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5ed\uc0ac\ud654\ub294 \ucc28\uac11\uace0 \ucd08\uc0c1\ud654\ub9cc \uc9c4\uc2e4\ud558\ub2e4\uace0 \uc678\uc6b0\uae30\ubcf4\ub2e4, \uc11c\ub85c \ub2e4\ub978 \ud654\uba74\uc5d0\uc11c \ubb34\uc5c7\uc744 \uac15\uc870\ud558\ub294\uc9c0 \ube44\uad50\ud558\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc791\ud488\uc744 \ubd84\ub958\ud558\ub294 \uc774\ub984\uc740 \ubcf4\uae30\uc758 \ucd9c\ubc1c\uc810\uc774\uc9c0 \uac10\uc0c1\uc758 \ub05d\uc740 \uc544\ub2c8\ub2e4. \uba3c\uc800 \ud770 \ub4dc\ub808\uc2a4\uac00 \ub9cc\ub4dc\ub294 \ubc1d\uc740 \uba74\uc744 \ubcf4\uace0, \ub2e4\uc74c\uc5d0\ub294 \ubab8\uacfc \uc5bc\uad74\uc758 \ubc29\ud5a5\uc744, \ub9c8\uc9c0\ub9c9\uc5d0\ub294 \uc758\uc790\uc640 \ub4f1\uc794\ub300\uac00 \ub9cc\ub4dc\ub294 \uc120\uc744 \ub530\ub77c\uac00 \ubcf4\uc790. \uc778\ubb3c\uc5d0 \ub300\ud574 \uc544\ub294 \uac83\uc774 \ub9ce\uc9c0 \uc54a\uc544\ub3c4 \uc2e4\uc81c \uadf8\ub9bc \uc548\uc5d0\uc11c \ubcfc \uc218 \uc788\ub294 \uad00\uacc4\uac00 \ub298\uc5b4\ub09c\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \uc61b \ub8e8\ube0c\ub974 \ub3c4\ub85d\uc5d0 \uc218\ub85d\ub41c \uc2e4\uc81c \uc791\ud488\uc758 \uc7ac\ud604 \ub3c4\ud310\uc774\ub2e4. \uc778\ubb3c\uacfc \uac00\uad6c\ub97c \uc0c8\ub85c \ub9cc\ub4e0 AI \uadf8\ub9bc\uc774 \uc544\ub2c8\ub2e4. \uc0c9\uc740 \uc7ac\ud604\uacfc \ud654\uba74\uc5d0 \ub530\ub77c \ucc28\uc774\uac00 \uc788\uc744 \uc218 \uc788\uc9c0\ub9cc, \ube48 \ubc30\uacbd\uc774 \uc0ac\ub78c\uc744 \uc5b4\ub5bb\uac8c \ub3cb\ubcf4\uc774\uac8c \ud558\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uae30\uc5d0\ub294 \ucda9\ubd84\ud55c \uc785\uad6c\uac00 \ub41c\ub2e4."}, {"id": "descartes-method-and-doubt", "title": "\ub370\uce74\ub974\ud2b8 \ubc29\ubc95\uc11c\uc124 \u2014 \ubb34\uc5c7\uc744 \ud655\uc2e4\ud788 \uc548\ub2e4\uace0 \ub9d0\ud560 \uc218 \uc788\uc744\uae4c", "summary": "\ub124 \uac00\uc9c0 \uaddc\uce59\uacfc \uc720\uba85\ud55c \ubb38\uc7a5\uc774 \ub098\uc628 \ub9e5\ub77d\uc744 \uc26c\uc6b4 \uc608\uc640 \ud568\uaed8 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Philosophy", "url": "stories/descartes-method-and-doubt/index.html", "image": "media/descartes-method-and-doubt.png", "alt": "1649\ub144 \ub7f0\ub358\uc5d0\uc11c \uc778\uc1c4\ud55c \ubc29\ubc95\uc11c\uc124 \uc601\ubb38\ud310\uc758 \uc2e4\uc81c \ud45c\uc81c\uba74. Method\uc640 Reason\uc774\ub77c\ub294 \ub2e8\uc5b4 \ubc0f \ucd9c\ud310 \uc5f0\ub3c4\uac00 \ubcf4\uc785\ub2c8\ub2e4.", "text": "\ub370\uce74\ub974\ud2b8 \ubc29\ubc95\uc11c\uc124 \u2014 \ubb34\uc5c7\uc744 \ud655\uc2e4\ud788 \uc548\ub2e4\uace0 \ub9d0\ud560 \uc218 \uc788\uc744\uae4c \uc791\uac8c \ub098\ub204\uace0 \ucc28\ub840\ub85c \uc0b4\ud53c\ub294 \uc0dd\uac01\uc758 \uae38 \ub124 \uac00\uc9c0 \uaddc\uce59\uacfc \uc720\uba85\ud55c \ubb38\uc7a5\uc774 \ub098\uc628 \ub9e5\ub77d\uc744 \uc26c\uc6b4 \uc608\uc640 \ud568\uaed8 \uc77d\uc2b5\ub2c8\ub2e4. Philosophy \ubb38\ud654 \uc798 \uc548\ub2e4\uace0 \uc0dd\uac01\ud55c \uc77c\ub3c4 \uadfc\uac70\ub97c \ud558\ub098\uc529 \ubb3c\uc5b4\ubcf4\uba74 \ub2f5\uc774 \ud750\ub824\uc9c8 \ub54c\uac00 \uc788\ub2e4. \uc9c1\uc811 \ubcf8 \uac83\uacfc \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ub4e4\uc740 \uac83, \uc790\uc8fc \ubc18\ubcf5\ud574\uc11c \uc775\uc219\ud574\uc9c4 \ub9d0\uc774 \ub4a4\uc11e\uc5ec \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \ub370\uce74\ub974\ud2b8\uc758 \u300e\ubc29\ubc95\uc11c\uc124\u300f\uc740 \uc0dd\uac01\uc744 \uc5b4\ub514\uc5d0\uc11c \uc2dc\uc791\ud558\uace0 \uc5b4\ub5a4 \uc21c\uc11c\ub85c \ud655\uc778\ud560\uc9c0 \ubb3b\ub294 \ucc45\uc774\ub2e4. 1596\ub144\uc5d0 \ud0dc\uc5b4\ub098 1650\ub144\uc5d0 \uc138\uc0c1\uc744 \ub5a0\ub09c \ud504\ub791\uc2a4 \ucca0\ud559\uc790\ub294 \uc774 \uc791\ud488\uc744 1637\ub144\uc5d0 \ub0b4\ub193\uc558\ub2e4. \uc720\uba85\ud55c \u2018\ub098\ub294 \uc0dd\uac01\ud55c\ub2e4, \uadf8\ub7ec\ubbc0\ub85c \uc874\uc7ac\ud55c\ub2e4\u2019\ub9cc \uc678\uc6b0\uae30\ubcf4\ub2e4 \uc65c \uadf8\ub7f0 \ud655\uc2e4\ud55c \ucd9c\ubc1c\uc810\uc744 \ucc3e\uc73c\ub824 \ud588\ub294\uc9c0 \ud568\uaed8 \uc77d\uc73c\uba74 \ubb38\uc7a5\uc774 \uc870\uae08 \ub35c \ub0af\uc124\uc5b4\uc9c4\ub2e4. \ucc45\uc758 \uccab \ubd80\ubd84\uc5d0\ub294 \uc790\uc2e0\uc774 \ubc1b\uc740 \uad50\uc721\uacfc \uc138\uc0c1\uc744 \uc0b4\ud53c\ub824 \ud588\ub358 \uc2dc\uac04\uc774 \ub098\uc628\ub2e4. \ub9ce\uc740 \uac83\uc744 \ubc30\uc6e0\ub2e4\uace0 \ubaa8\ub4e0 \ud310\ub2e8\uc774 \ud655\uc2e4\ud574\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc5ec\ud589\uacfc \uacbd\ud5d8 \uc5ed\uc2dc \uc9c0\uc2dd\uc744 \ub113\ud790 \uc218 \uc788\uc9c0\ub9cc \uc11c\ub85c \ub2e4\ub978 \uad00\uc2b5\uacfc \uc0dd\uac01\uc744 \ub9cc\ub098\uac8c \ud55c\ub2e4. \uc774\ub7f0 \ud68c\uace0\uac00 \uc911\uc694\ud55c \uc774\uc720\ub294 \ubc29\ubc95\uc774 \uba38\ub9bf\uc18d\uc758 \uaddc\uce59 \ubaa9\ub85d\uc73c\ub85c\ub9cc \ub4f1\uc7a5\ud558\uc9c0 \uc54a\uae30 \ub54c\ubb38\uc774\ub2e4. \ubb34\uc5c7\uc744 \ubbff\uc5b4\uc57c \ud560\uc9c0 \ud63c\ub780\uc2a4\ub7ec\uc6b4 \uacbd\ud5d8\uc5d0\uc11c \ub354 \ub2e8\ub2e8\ud55c \uae30\uc900\uc744 \ucc3e\uc73c\ub824\ub294 \ud544\uc694\uac00 \uc0dd\uae34\ub2e4. \uc88b\uc740 \uad50\uc721\uacfc \uc2a4\uc2a4\ub85c \uac80\ud1a0\ud558\ub294 \ub2a5\ub825\uc740 \uac19\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4\ub294 \ucd9c\ubc1c\uc810\uc774\ub2e4. \ub370\uce74\ub974\ud2b8\uac00 \uc81c\uc2dc\ud558\ub294 \ubc29\ubc95\uc758 \ud55c \ubc29\ud5a5\uc740 \ubd84\uba85\ud558\uac8c \ud655\uc778\ub418\uc9c0 \uc54a\uc740 \uac83\uc744 \uc11c\ub458\ub7ec \ucc38\uc774\ub77c\uace0 \ubc1b\uc544\ub4e4\uc774\uc9c0 \uc54a\ub294 \uac83\uc774\ub2e4. \ub2f9\uc5f0\ud558\ub2e4\ub294 \ub290\ub08c\uacfc \uadfc\uac70\uac00 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uad6c\ubd84\ud558\uc790\ub294 \ub73b\uc73c\ub85c \ub4e4\uc5b4\uac08 \uc218 \uc788\ub2e4. \uadf8\uac00 \uc6d0\ud558\ub294 \uae30\uc900\uc740 \ub9e4\uc6b0 \uc5c4\uaca9\ud558\uc9c0\ub9cc \uc624\ub298\uc758 \ub3c5\uc790\ub3c4 \ubb38\uc81c\uc758 \ubc29\ud5a5\uc740 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \uc5b4\ub5a4 \ucc45\uc774 \ud6cc\ub96d\ud558\ub2e4\ub294 \ud3c9\uc744 \ub9ce\uc774 \ubcf4\uc558\uc744 \ub54c, \uc9c1\uc811 \uc77d\uc740 \ud310\ub2e8\uacfc \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uc758 \ud3c9\uac00\ub97c \ub098\ub204\uc5b4 \ubcfc \uc218 \uc788\ub2e4. \uc774\uac83\uc740 \uc6d0\ubb38\uc5d0 \ub098\uc624\ub294 \uc2e4\uc81c \uc0ac\ub840\uac00 \uc544\ub2c8\ub77c \uaddc\uce59\uc744 \uc774\ud574\ud558\uae30 \uc704\ud55c \uc608\ub2e4. \ubbff\uc74c\uc744 \ubaa8\ub450 \uc5c6\uc560\uae30\ubcf4\ub2e4 \uc9c0\uae08 \ubb34\uc5c7\uc744 \uadfc\uac70\ub85c \ud310\ub2e8\ud588\ub294\uc9c0 \uc54c\uc544\ubcf4\ub294 \uc77c\uc774\ub2e4. \ubcf5\uc7a1\ud55c \ubb38\uc81c\ub97c \uac00\ub2a5\ud55c \ud55c \uc791\uc740 \ubd80\ubd84\uc73c\ub85c \ub098\ub204\uc5b4 \uc0b4\ud53c\ub294 \uaddc\uce59\uc774 \ub098\uc628\ub2e4. \ud55c\uaebc\ubc88\uc5d0 \uc5b4\ub835\ub2e4\uace0 \ub290\uaef4\uc9c0\ub294 \uac83\ub3c4 \uc11c\ub85c \ub2e4\ub978 \uc9c8\ubb38\uc774 \uc5bd\ud600 \uc788\uc744 \uc218 \uc788\ub2e4. \ubd84\ub9ac\ud558\uba74 \uc5b4\ub514\ub97c \uc54c\uba70 \uc5b4\ub514\ub97c \ubaa8\ub974\ub294\uc9c0 \ubcf4\uc774\uae30 \uc2dc\uc791\ud55c\ub2e4. \uc5ec\ud589 \uacc4\ud68d\uc774 \uc5b4\ub835\ub2e4\uba74 \ube44\uc6a9\uacfc \uc774\ub3d9, \uba38\ubb34\ub294 \uc2dc\uac04\uacfc \uaf2d \ubcf4\uace0 \uc2f6\uc740 \ub300\uc0c1\uc744 \ub098\ub204\uc5b4 \ubcfc \uc218 \uc788\ub2e4. \ud55c \ubd80\ubd84\uc758 \ub2f5\uc774 \ub098\uba38\uc9c0 \uc804\uccb4\ub97c \uc790\ub3d9\uc73c\ub85c \ud574\uacb0\ud558\uc9c0\ub294 \uc54a\uc9c0\ub9cc \uc0dd\uac01\ud560 \uc790\ub9ac\uac00 \ubd84\uba85\ud574\uc9c4\ub2e4. \uc798\uac8c \ub098\ub208 \ub4a4 \ub2e4\uc2dc \uc5f0\uacb0\ud574\uc57c \ud55c\ub2e4\ub294 \uc810\ub3c4 \ud568\uaed8 \uae30\uc5b5\ud558\uba74 \uc88b\ub2e4. \ub2e8\uc21c\ud558\uace0 \uc54c\uae30 \uc26c\uc6b4 \uac83\uc5d0\uc11c \ub354 \ubcf5\uc7a1\ud55c \uac83\uc73c\ub85c \ub098\uc544\uac00\uba70, \ube60\ub728\ub9b0 \ubd80\ubd84\uc774 \uc5c6\ub294\uc9c0 \uc804\uccb4\ub97c \uc810\uac80\ud558\ub294 \uc0dd\uac01\ub3c4 \uc81c\uc2dc\ub41c\ub2e4. \ubb38\uc81c\ub97c \ub098\ub204\ub294 \uac83\uacfc \ubb34\uc5c7\ubd80\ud130 \uc0b4\ud544\uc9c0 \uc815\ud558\ub294 \uc77c\uc740 \uc11c\ub85c \uc5f0\uacb0\ub41c\ub2e4. \uadf8\ub9ac\uace0 \ub9c8\uc9c0\ub9c9\uc5d0\ub294 \ud769\uc5b4\uc9c4 \ud310\ub2e8\uc744 \ub2e4\uc2dc \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc774 \uaddc\uce59\uc744 \ub530\ub974\uba74 \uc0dd\ud65c\uc758 \ubaa8\ub4e0 \ubb38\uc81c\uac00 \uae54\ub054\ud558\uac8c \ud480\ub9b0\ub2e4\ub294 \uc57d\uc18d\uc73c\ub85c \uc77d\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc0ac\ub78c\uc758 \uac10\uc815\uacfc \uad00\uacc4\uc5d0\ub294 \ub2e8\uc21c\ud55c \uacc4\uc0b0\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\ub294 \uc870\uac74\uc774 \uc788\ub2e4. \ub2e4\ub9cc \ubb34\uc5c7\uc744 \uba3c\uc800 \ud655\uc778\ud588\uace0 \ubb34\uc5c7\uc744 \uc544\uc9c1 \uac80\ud1a0\ud558\uc9c0 \uc54a\uc558\ub294\uc9c0 \ub4dc\ub7ec\ub0b4\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub418\ub294 \uc0ac\uace0\uc758 \uc2b5\uad00\uc73c\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \ub354 \ud655\uc2e4\ud55c \uadfc\uac70\ub97c \ucc3e\uc73c\ub824\ub294 \uacfc\uc815\uc5d0\uc11c \uac10\uac01\uc774 \uc6b0\ub9ac\ub97c \uc798\ubabb \uc774\ub04c \uc218 \uc788\ub2e4\ub294 \ubb38\uc81c\uac00 \ub4f1\uc7a5\ud55c\ub2e4. \uafc8\uc18d\uc5d0\uc11c\ub3c4 \uc2e4\uc81c\ucc98\ub7fc \ub290\ub07c\ub294 \uacbd\ud5d8\uc774 \uc788\uc73c\ub2c8, \uc9c0\uae08 \ubd84\uba85\ud574 \ubcf4\uc778\ub2e4\ub294 \ub290\ub08c\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uac83\uc744 \ubcf4\uc99d\ud558\uae30 \uc5b4\ub835\ub2e4\ub294 \uac83\uc774\ub2e4. \uc774 \uc758\uc2ec\uc740 \uc138\uc0c1\uc758 \uc544\ubb34 \ub9d0\ub3c4 \ubbff\uc9c0 \uc54a\uaca0\ub2e4\ub294 \ud0dc\ub3c4\ub85c \ub05d\ub0b4\ub824\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \ud754\ub4e4\ub9b4 \uc218 \uc788\ub294 \uac83\uc744 \uc2dc\ud5d8\ud574 \ubcf4\uace0 \uadf8 \ub4a4\uc5d0\ub3c4 \ub0a8\ub294 \ucd9c\ubc1c\uc810\uc744 \ucc3e\uc73c\ub824 \ud55c\ub2e4. \uc758\uc2ec\ud558\ub294 \ud589\ub3d9\uc758 \ubaa9\uc801\uc774 \ubb34\uc5c7\uc778\uc9c0 \ub193\uce58\uba74 \ucc45\uc740 \ub05d\uc5c6\ub294 \ubd88\uc2e0\uc744 \uad8c\ud558\ub294 \ub9d0\ucc98\ub7fc \uc798\ubabb \ub4e4\ub9b4 \uc218 \uc788\ub2e4. \uc720\uba85\ud55c \ubb38\uc7a5\uc740 \uc774 \ub9e5\ub77d\uc5d0\uc11c \ub098\uc628\ub2e4. \ubaa8\ub4e0 \uac83\uc744 \uc758\uc2ec\ud558\ub354\ub77c\ub3c4 \uc9c0\uae08 \uc758\uc2ec\ud558\uace0 \uc0dd\uac01\ud558\ub294 \ud65c\ub3d9\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc644\uc804\ud788 \uc9c0\uc6b0\uae30\ub294 \uc5b4\ub835\ub2e4\ub294 \uac83\uc774\ub2e4. \uadf8 \uc0dd\uac01\ud558\ub294 \uc790\uc2e0\uc744 \ucd9c\ubc1c\uc810\uc73c\ub85c \uc0bc\uc73c\ub824\ub294 \ub17c\ub9ac\uac00 \ubb38\uc7a5\uc744 \ubc1b\uce5c\ub2e4. \uadf8\ub7ec\ub098 \ub0b4\uac00 \uc0dd\uac01\ud55c\ub2e4\ub294 \uc774\uc720\ub85c \ub0b4 \uc0dd\uac01\uc758 \ub0b4\uc6a9\uc774 \uc804\ubd80 \uc633\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc874\uc7ac\uc758 \ud655\uc2e4\uc131\uacfc \uc758\uacac\uc758 \uc815\ud655\uc131\uc740 \ub2e4\ub978 \ubb38\uc81c\ub2e4. \ub9c8\uc74c\uc5d0 \ub4dc\ub294 \uc8fc\uc7a5 \uc55e\uc5d0 \uc720\uba85\ud55c \ubb38\uc7a5\uc744 \ubd99\uc5ec \uac80\ud1a0\ub97c \ub05d\ub0b4\uae30\ubcf4\ub2e4, \uc624\ud788\ub824 \ubb34\uc5c7\uc744 \uc99d\uba85\ud55c \ub9d0\uc778\uc9c0 \ud55c\uacc4\ub97c \uc54c\uc544 \ub450\uba74 \ub354 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \u300e\ubc29\ubc95\uc11c\uc124\u300f\uc5d0\ub294 \uc774 \uc720\uba85\ud55c \ub300\ubaa9 \ub4a4\uc5d0\ub3c4 \uc2e0\uacfc \uc138\uacc4, \ud559\ubb38\uacfc \uc0b6\uc5d0 \uad00\ud55c \ub17c\uc758\uac00 \uc774\uc5b4\uc9c4\ub2e4. \uc624\ub298\uc758 \ub3c5\uc790\uac00 \uadf8 \ubaa8\ub4e0 \ub17c\uc99d\uc744 \ubc14\ub85c \ubc1b\uc544\ub4e4\uc5ec\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud655\uc2e4\ud55c \ucd9c\ubc1c\uc810\uc5d0\uc11c \uc5b4\ub5a4 \uae38\uc744 \uac70\uccd0 \ub2e4\ub978 \uc8fc\uc7a5\uc73c\ub85c \uac00\ub294\uc9c0 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \ucc45\uc5d0\ub294 \uc0dd\uac01\uc744 \uac80\ud1a0\ud558\ub294 \ub3d9\uc548 \uc2e4\uc81c \uc0b6\uc5d0\uc11c\ub294 \uc5b4\ub5bb\uac8c \ud589\ub3d9\ud560\uc9c0\uc5d0 \uad00\ud55c \ubb38\uc81c\ub3c4 \uc788\ub2e4. \ubaa8\ub4e0 \ub2f5\uc774 \uc644\uc131\ub420 \ub54c\uae4c\uc9c0 \uc0b4\uc544\uac00\ub294 \uc77c\uc744 \uba48\ucd9c \uc218\ub294 \uc5c6\uae30 \ub54c\ubb38\uc774\ub2e4. \ucca0\ud559\uc758 \uc5c4\uaca9\ud55c \uc694\uad6c\uc640 \ub9e4\uc77c\uc758 \ud310\ub2e8\uc774 \ub9cc\ub098\ub294 \uacf3\uc744 \ubcf4\uba74 \ucd94\uc0c1\uc801\uc778 \ucc45\uc774 \uc0dd\ud65c\uacfc \ub2ff\ub294 \uc9c0\uc810\uc774 \uc0dd\uae34\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 1649\ub144 \ub7f0\ub358\uc5d0\uc11c \uc778\uc1c4\ud55c \uc601\ubb38\ud310\uc758 \uc2e4\uc81c \ud45c\uc81c\uba74\uc774\ub2e4. \ud504\ub791\uc2a4\uc5b4 \ucd08\ud310\uc774\ub098 \ub370\uce74\ub974\ud2b8\uc758 \uce5c\ud544 \uc6d0\uace0\ub294 \uc544\ub2c8\uc9c0\ub9cc, \ubc29\ubc95\uacfc \uc774\uc131\uc774\ub77c\ub294 \ub2e8\uc5b4\uac00 \uc5b4\ub5a4 \ucc45\uc758 \uc81c\ubaa9\uc73c\ub85c \uc804\ud574\uc84c\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\ub294 \uc5ed\uc0ac\uc801 \uc790\ub8cc\ub2e4. \uc624\ub298 \uc798 \uc548\ub2e4\uace0 \uc5ec\uae30\ub294 \uac83 \ud558\ub098\ub97c \uace8\ub77c \uadfc\uac70\uc640 \uc21c\uc11c\ub97c \uc9e7\uac8c \uc801\uc5b4 \ubcf4\uc790. \ubb34\uc5c7\uc744 \uba3c\uc800 \ud655\uc778\ud560 \uc218 \uc788\uace0 \uc5b4\ub5a4 \ubd80\ubd84\uc774 \ube60\uc84c\ub294\uc9c0 \uc0b4\ud53c\uba74 \ub41c\ub2e4. \ub370\uce74\ub974\ud2b8\ub97c \uc77d\ub294 \uad50\uc591\uc740 \uc720\uba85\ud55c \ubb38\uc7a5\uc744 \uc778\uc6a9\ud558\ub294 \uc77c\uc5d0\uc11c \uadf8 \ubb38\uc7a5\uc774 \ud544\uc694\ud588\ub358 \uc9c8\ubb38\uc744 \uc790\uae30 \ub9d0\ub85c \ub418\ubb3b\ub294 \uc77c\ub85c \ub113\uc5b4\uc9c8 \uc218 \uc788\ub2e4."}, {"id": "dokseodang-gathering", "title": "\uadf8\ub9bc \uc18d \ubc43\ub180\uc774\uc5d0\ub294 \ucc38\uc11d\uc790 \uba85\ub2e8\uc774 \uc788\ub2e4", "summary": "\ud55c\uac15\uc5d0\uc11c \ubc30\ub97c \ud0c4 \uc0ac\ub78c\ub4e4, \uadf8\ub9ac\uace0 \uadf8\ub9bc \uc544\ub798 \ube7d\ube7d\ud55c \uae00\uc528. \uc624\ub798\ub41c \ubaa8\uc784 \uadf8\ub9bc\uc5d0\ub294 \ub204\uac00 \ud568\uaed8\ud588\ub294\uc9c0\ub3c4 \uc801\ud600 \uc788\uc2b5\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Art", "url": "stories/dokseodang-gathering/index.html", "image": "media/dokseodang-gathering.jpg", "alt": "\uc704\ucabd \uc81c\ubaa9\uacfc \uac00\uc6b4\ub370 \ud55c\uac15 \ud48d\uacbd, \uc544\ub798\ucabd \ucc38\uc11d\uc790 \uba85\ub2e8\uc73c\ub85c \uad6c\uc131\ub41c \ub3c5\uc11c\ub2f9\uacc4\ud68c\ub3c4 \uc871\uc790 \uc804\uccb4", "text": "\uadf8\ub9bc \uc18d \ubc43\ub180\uc774\uc5d0\ub294 \ucc38\uc11d\uc790 \uba85\ub2e8\uc774 \uc788\ub2e4 \ub3c5\uc11c\ub2f9\uacc4\ud68c\ub3c4\uc5d0 \ub0a8\uc740 \uc5f4\ub450 \uc0ac\ub78c\uc758 \ubaa8\uc784 \ud55c\uac15\uc5d0\uc11c \ubc30\ub97c \ud0c4 \uc0ac\ub78c\ub4e4, \uadf8\ub9ac\uace0 \uadf8\ub9bc \uc544\ub798 \ube7d\ube7d\ud55c \uae00\uc528. \uc624\ub798\ub41c \ubaa8\uc784 \uadf8\ub9bc\uc5d0\ub294 \ub204\uac00 \ud568\uaed8\ud588\ub294\uc9c0\ub3c4 \uc801\ud600 \uc788\uc2b5\ub2c8\ub2e4. Art \ubb38\ud654 \uc61b \uadf8\ub9bc\uc744 \ubcfc \ub54c \uae00\uc528\ub294 \uc77c\ub2e8 \uac74\ub108\ub6f0\uac8c \ub41c\ub2e4. \uc0b0\uc774 \uc5b4\ub514 \uc788\ub294\uc9c0, \uc0ac\ub78c\uc740 \ubb34\uc5c7\uc744 \ud558\ub294\uc9c0\ubd80\ud130 \ucc3e\uc544\ubcf4\ub294 \ud3b8\uc774 \uc27d\ub2e4. \ud55c\uc790\uac00 \ube7d\ube7d\ud558\uac8c \uc801\ud600 \uc788\uc73c\uba74 \uadf8\ub9bc \uc124\uba85\uc774\uaca0\uac70\ub2c8 \ud558\uace0 \uc9c0\ub098\uce58\uae30\ub3c4 \ud55c\ub2e4. \uadf8\ub7f0\ub370 \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \u300c\ub3c5\uc11c\ub2f9\uacc4\ud68c\ub3c4\u300d\uc5d0\uc11c\ub294 \uc544\ub798\ucabd \uae00\uc528\uc5d0\ub3c4 \uc7a0\uae50 \ub208\uc744 \uc8fc\uba74 \uc88b\uaca0\ub2e4. \uac70\uae30\uc5d0\ub294 \uc774 \ubaa8\uc784\uc5d0 \ucc38\uc11d\ud55c \uc0ac\ub78c\ub4e4\uc758 \uc774\ub984\uc774 \uc801\ud600 \uc788\ub2e4. \uadf8\ub9bc \uc18d\uc5d0\uc11c\ub294 \uad00\ubcf5 \ucc28\ub9bc\uc758 \uc0ac\ub78c\ub4e4\uc774 \ud55c\uac15\uc5d0\uc11c \ubc43\ub180\uc774\ub97c \ud55c\ub2e4. \ub290\uae0b\ud55c \ud48d\uacbd\ud654\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc, \uc791\ud488\uc740 \ubaa8\uc784\uc758 \uae30\uc5b5\uacfc \ucc38\uc11d\uc790 \uc815\ubcf4\ub97c \ud568\uaed8 \ub0a8\uaca8 \ub450\uc5c8\ub2e4. \uc624\ub298\uc758 \ub2e8\uccb4 \uae30\ub150\uc0ac\uc9c4 \ub4a4\uc5d0 \uc774\ub984\uc744 \uc801\uc5b4 \ub193\ub294 \ubaa8\uc2b5\uc774 \uc870\uae08 \ub5a0\uc624\ub978\ub2e4. \uc81c\ubaa9\uc758 \u2018\uacc4\ud68c\ub3c4\u2019\ub294 \ubaa8\uc784\uc744 \uae30\ub150\ud558\ub294 \uadf8\ub9bc\uc774\ub77c\ub294 \ub73b\uc73c\ub85c \uc77d\uc73c\uba74 \ub41c\ub2e4. \uc774 \uc791\ud488\uc740 \uc0ac\uac00\ub3c5\uc11c\ud55c \uc774\ub825\uc774 \uc788\ub294 \uad00\ub8cc\ub4e4\uc758 \ubaa8\uc784\uc744 \uae30\ub150\ud574 \ub9cc\ub4e4\uc5c8\ub2e4\uace0 \ubc15\ubb3c\uad00\uc740 \uc124\uba85\ud55c\ub2e4. \uc0ac\uac00\ub3c5\uc11c\ub294 \ud734\uac00\ub97c \ubc1b\uc544 \ub3c5\uc11c\uc5d0 \uc804\ub150\ud558\ub294 \uc77c\uc744 \uac00\ub9ac\ud0a8\ub2e4. \ucc45 \uc77d\ub358 \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc600\ub2e4\uace0 \ud558\ub2c8 \uadf8\ub9bc \uc18d\uc5d0\uc11c\ub3c4 \ubaa8\ub450 \ucc45\uc0c1 \uc55e\uc5d0 \uc549\uc544 \uc788\uc744 \uac83 \uac19\ub2e4. \ud558\uc9c0\ub9cc \uae30\ub85d\ub41c \ubaa8\uc784\uc758 \ubaa8\uc2b5\uc740 \ub2e4\ub974\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \ubc30\ub97c \ud0d4\uace0, \uadf8 \uc8fc\ubcc0\uc73c\ub85c \uac15\uacfc \uc0b0\uc774 \ud3bc\uccd0\uc838 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \uad00\ub9ac\ub4e4\uc774 \ubab0\ub798 \uc77c\uc744 \ube7c\uba39\uc5c8\ub2e4\uace0 \uc0c1\uc0c1\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uadf8\ub9bc\uc740 \ubaa8\uc784\uc758 \ud55c \uc7a5\uba74\uc744 \ubcf4\uc5ec\uc904 \ubfd0, \uc0ac\ub78c\ub4e4\uc774 \uc8fc\uace0\ubc1b\uc740 \ub9d0\uc774\ub098 \uadf8\ub0a0\uc758 \uc18d\uc0ac\uc815\uae4c\uc9c0 \uc54c\ub824\uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \uad00\ubcf5\uacfc \ubc43\ub180\uc774\uac00 \ud55c \ud654\uba74\uc5d0 \uc788\ub2e4\ub294 \uac83\ub9cc\uc73c\ub85c\ub3c4 \ucda9\ubd84\ud788 \ub208\uae38\uc744 \ub048\ub2e4. \ud48d\uacbd\uc740 \ub9c9\uc5f0\ud788 \uba4b\uc9c4 \uc0b0\uc218\ub97c \uadf8\ub824 \ub123\uc740 \uac83\ub9cc\uc740 \uc544\ub2c8\ub2e4. \ubc15\ubb3c\uad00\uc740 \ub3c5\uc11c\ub2f9\uc774 \uc788\ub358 \ud55c\uac15\ubcc0 \ub450\ubaa8\ud3ec, \uc9c0\uae08\uc758 \uc11c\uc6b8 \uc131\ub3d9\uad6c \uc625\uc218\ub3d9 \uc77c\ub300\uac00 \ubb18\uc0ac\ub418\uc5b4 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud654\uba74 \uac00\uc6b4\ub370 \uc19f\uc740 \uc751\ubd09\uc740 \ud604\uc7ac\uc758 \ub9e4\ubd09\uc0b0\uc5d0 \ud574\ub2f9\ud55c\ub2e4. \uc9c0\uae08 \uc544\ub294 \uc11c\uc6b8\uc758 \uc9c0\uba85\uacfc \uc5f0\uacb0\ud574 \ubcf4\uba74 \uc624\ub798\ub41c \uadf8\ub9bc\uc774 \uc870\uae08 \uac00\uae4c\uc6cc\uc9c4\ub2e4. \ud48d\uacbd\uc744 \ud1b5\uc9f8\ub85c \ud604\uc7ac\uc758 \uc9c0\ub3c4\uc640 \ub9de\ucd9c \ud544\uc694\ub294 \uc5c6\ub2e4. \ud55c\uac15\ubcc0\uc758 \uc5b4\ub290 \uc7a5\uc18c\ub97c \uae30\uc5b5\ud558\uba70 \uadf8\ub838\ub2e4\ub294 \ub2e8\uc11c \uc815\ub3c4\ub9cc \ucc59\uaca8\ub3c4 \uc88b\ub2e4. \uc774 \uc791\ud488\uc740 \uc704\uc5d0\uc11c \uc544\ub798\ub85c \uc77d\ub294 \uc21c\uc11c\uac00 \uc788\ub2e4. \ub9e8 \uc704\uc5d0\ub294 \uc81c\ubaa9, \uac00\uc6b4\ub370\uc5d0\ub294 \ubaa8\uc784 \uc7a5\uba74, \uc544\ub798\uc5d0\ub294 \ucc38\uc11d\uc790 \uba85\ub2e8\uc774 \ub193\uc778\ub2e4. \uba40\ub9ac\uc11c \ubcf4\uba74 \uae34 \uc871\uc790 \ud558\ub098\uc9c0\ub9cc, \uac00\uae4c\uc774\uc5d0\uc11c\ub294 \uc11c\ub85c \ub2e4\ub978 \uc77c\uc744 \ud558\ub294 \uc138 \ubd80\ubd84\uc774 \ubaa8\uc5ec \uc788\ub2e4. \uc544\ub798\ucabd \uba85\ub2e8\uc740 \u2018\uc88c\ubaa9\u2019\uc774\ub77c\uace0 \ubd80\ub978\ub2e4. \uc774 \uadf8\ub9bc\uc758 \uc88c\ubaa9\uc5d0\ub294 \uc5f4\ub450 \uc0ac\ub78c\uc758 \ud638\uc640 \uc774\ub984\ubfd0 \uc544\ub2c8\ub77c \ubcf8\uad00\uacfc \uc0dd\ub144, \uacfc\uac70\uc5d0 \uae09\uc81c\ud55c \uc5f0\ub3c4, \uc0ac\uac00\ub3c5\uc11c\ub97c \ud55c \uc2dc\uae30, \ub2f9\uc2dc \ud488\uacc4\uc640 \uad00\uc9c1\uae4c\uc9c0 \uc801\ud600 \uc788\ub2e4. \uc774\ub984\ub9cc \uc801\uc5b4\ub3c4 \uae30\ub150\uc740 \ub420 \ud150\ub370 \uaf64 \uaf3c\uaf3c\ud558\ub2e4. \ubaa8\uc784\uc5d0 \ub204\uac00 \uc788\uc5c8\ub294\uc9c0\uc640 \uadf8 \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub5a4 \uc774\ub825\uc744 \uc9c0\ub154\ub294\uc9c0\ub97c \ud568\uaed8 \ub0a8\uacbc\ub2e4. \ud6c4\ub300\uc758 \uad00\ub78c\uac1d\uc5d0\uac8c\ub294 \uadf8\ub9bc \uc606\uc5d0 \uc791\uc740 \uc778\ubb3c \uc18c\uac1c\uac00 \ubd99\uc5b4 \uc788\ub294 \uc148\uc774\ub2e4. \uc6b0\ub9ac\uac00 \uba85\ub2e8\uc758 \ud55c\uc790\ub97c \ubaa8\ub450 \uc77d\uc5b4\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub9bc\uc5d0\uc11c \uc0ac\ub78c\uc744 \ucc3e\uc740 \ub4a4 \uc544\ub798\uc758 \uae00\uc528\ub85c \ub208\uc744 \uc62e\uaca8 \ubcf4\uba74 \ub41c\ub2e4. \ub208\uc55e\uc758 \uc7a5\uba74\uacfc \uadf8 \uc7a5\uba74\uc5d0 \ucc38\uc5ec\ud55c \uc0ac\ub78c\ub4e4\uc758 \uae30\ub85d\uc774 \ud55c \uc791\ud488 \uc548\uc5d0 \ub098\ub780\ud788 \uc788\ub2e4\ub294 \uc810\uc744 \uc54c\uc544\ubcf4\ub294 \uac83\uc73c\ub85c \ucda9\ubd84\ud558\ub2e4. \uadf8\ub9bc\uc5d0 \uc5f0\ub3c4\uac00 \ud06c\uac8c \uc4f0\uc5ec \uc788\uc9c0 \uc54a\uc544\ub3c4 \uba85\ub2e8\uc740 \uc81c\uc791 \uc2dc\uae30\ub97c \ucd94\uc815\ud560 \ub2e8\uc11c\uac00 \ub41c\ub2e4. \uc5b4\ub5a4 \uc778\ubb3c\uc774 \uc5b4\ub5a4 \uad00\uc9c1\uc5d0 \uc788\uc5c8\ub2e4\ub294 \uae30\ub85d\uc740 \uadf8 \uc0ac\ub78c\uc758 \uc0dd\uc560 \uac00\uc6b4\ub370 \ud2b9\uc815\ud55c \ubc94\uc704\uc640 \uc5f0\uacb0\ub41c\ub2e4. \uc5ec\ub7ec \uc0ac\ub78c\uc758 \uc774\ub825\uc774 \uacb9\uce58\ub294 \ub54c\ub97c \ube44\uad50\ud558\uba74 \uac00\ub2a5\ud55c \uc2dc\uac04\uc744 \ub354 \uc881\ud600 \ubcfc \uc218 \uc788\ub2e4. \ubc15\ubb3c\uad00\uc774 1531\ub144\uacbd\uc774\ub77c\ub294 \uc2dc\uae30\ub97c \uc81c\uc2dc\ud558\ub294 \ubc30\uacbd\uc774\ub2e4. \uc5ec\uae30\uc11c \uc911\uc694\ud55c \uac83\uc740 \ud55c \uc0ac\ub78c\uc758 \uc774\ub984\uc744 \uc54c\uc544\ubcf4\ub294 \ub370\uc11c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc810\uc774\ub2e4. \ucc38\uc11d\uc790 \uc5f4\ub450 \uba85\uc758 \uc815\ubcf4\uac00 \ud568\uaed8 \ub193\uc600\uae30\uc5d0 \uc11c\ub85c \ube44\uad50\ud560 \uae38\uc774 \uc0dd\uae34\ub2e4. \uc791\uc740 \uae00\uc528\ub97c \uc7a5\uc2dd\uc801\uc778 \ubd80\ub85d\uc73c\ub85c\ub9cc \ubcf4\uba74 \ub193\uce58\ub294 \uae30\ub2a5\uc774\ub2e4. \ud48d\uacbd\uacfc \uc778\ubb3c\uc740 \ubaa8\uc784\uc758 \ubaa8\uc2b5\uc744 \ub0a8\uae30\uace0, \uc88c\ubaa9\uc740 \uadf8 \uc7a5\uba74\uc744 \uc5ed\uc0ac \uc18d \uc0ac\ub78c\uacfc \uc2dc\uac04\uc73c\ub85c \uc5f0\uacb0\ud574 \uc900\ub2e4. \ub450\ubaa8\ud3ec\uc640 \uc751\ubd09\uc774\ub77c\ub294 \uc9c0\uba85\uc740 \uc9c0\uae08\uc758 \ub3c4\uc2dc \ud48d\uacbd\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \uadf8\ub7ec\ub098 \uc61b \uadf8\ub9bc\uc744 \uc624\ub298\uc758 \ud56d\uacf5\uc0ac\uc9c4\ucc98\ub7fc \ub9de\ucd94\ub824 \ud558\uba74 \uc5b4\ub824\uc6c0\uc774 \uc0dd\uae34\ub2e4. \ud654\uac00\ub294 \uae30\uc5b5\ud560 \uc7a5\uc18c\uc640 \uae30\ub150\ud560 \ubaa8\uc784\uc744 \ud654\uba74\uc5d0 \ubc30\uce58\ud588\uace0 \uc138\ubd80\uc758 \uac70\ub9ac\uc640 \ubc29\ud5a5\uc744 \uc0ac\uc9c4\uacfc \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uae30\ub85d\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc2e4\uc81c \uc7a5\uc18c\ub97c \uac00\ub9ac\ud0a8\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uacf5\uac04 \uc804\uccb4\uac00 \uc815\ubc00 \uc9c0\ub3c4\ub77c\ub294 \uc8fc\uc7a5\uc740 \ub2e4\ub974\ub2e4. \uadf8\ub798\ub3c4 \uc9c0\uba85\uc744 \uc54c\uc544\ub450\uba74 \uc0b0\uc218\ub294 \uc774\ub984 \uc5c6\ub294 \ubc30\uacbd\uc5d0\uc11c \ubc97\uc5b4\ub09c\ub2e4. \ucc45\uc744 \uc77d\ub358 \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub5a4 \uc7a5\uc18c\ub97c \ud568\uaed8 \uae30\uc5b5\ud588\ub294\uc9c0 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uae00\uacfc \ud48d\uacbd\uc744 \ubc88\uac08\uc544 \ubcf4\uba70 \uc775\uc219\ud55c \uc11c\uc6b8\uc758 \ub2e4\ub978 \uc2dc\uac04\uc744 \ub9cc\ub098 \ubcf4\uc790. \ud589\uc815\uacfc \ub3c5\uc11c, \ud734\uc2dd\uc774 \ud55c \ud654\uba74\uc5d0 \ub193\uc778\ub2e4\ub294 \uc810\ub3c4 \uc774 \ubaa8\uc784 \uadf8\ub9bc\uc758 \uc7ac\ubbf8\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc774 \uc791\ud488\uc744 1531\ub144\uacbd\uc758 \uadf8\ub9bc\uc73c\ub85c \uc18c\uac1c\ud55c\ub2e4. \ud654\uba74\uc758 \uc5b4\ub290 \uad6c\uc11d\uc5d0 \ud070 \uc22b\uc790\ub85c \uc5f0\ub3c4\uac00 \uc801\ud600 \uc788\uc5b4\uc11c\uc77c\uae4c? \uc124\uba85\uc5d0 \ub530\ub974\uba74 \uc81c\uc791 \uc2dc\uae30\ub97c \ucd94\uc815\ud558\ub294 \uadfc\uac70\ub294 \uc88c\ubaa9\uc5d0 \uc801\ud78c \uad00\uc9c1\uc774\ub2e4. \ub4f1\uc7a5\uc778\ubb3c\ub4e4\uc774 \uc5b8\uc81c \uc5b4\ub5a4 \uc790\ub9ac\uc5d0 \uc788\uc5c8\ub294\uc9c0\ub97c \uc0b4\ud53c\uba74, \uadf8\ub9bc\uc774 \ub9cc\ub4e4\uc5b4\uc9c4 \ub54c\ub97c \uc881\ud600 \ubcfc \uc218 \uc788\ub2e4. \ud48d\uacbd\ubcf4\ub2e4 \uc544\ub798\ucabd\uc758 \uae00\uc528\uac00 \ub0a0\uc9dc\uc758 \ub2e8\uc11c\ub97c \uc8fc\ub294 \uac83\uc774\ub2e4. \uc5ec\uae30\uc11c \u2018\uacbd\u2019\uc774\ub77c\ub294 \ub9d0\ub3c4 \ub193\uce58\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc88b\ub2e4. 1531\ub144\uc758 \uc5b4\ub290 \ud558\ub8e8\ub97c \uc815\ud655\ud558\uac8c \ud655\uc778\ud588\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ub0a8\uc544 \uc788\ub294 \uc815\ubcf4\ub97c \ubc14\ud0d5\uc73c\ub85c \uadf8 \ubb34\ub835\uc774\ub77c\uace0 \ucd94\uc815\ud55c\ub2e4\ub294 \ub73b\uc774\ub2e4. \ubaa8\ub974\ub294 \ubd80\ubd84\uae4c\uc9c0 \ucc44\uc6cc \ub123\uc9c0 \uc54a\uc544\ub3c4 \uadf8\ub9bc\uc758 \uc7ac\ubbf8\uac00 \uc904\uc5b4\ub4e4\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub2e8\uccb4\uc0ac\uc9c4\uc744 \uc624\ub798 \ubcf4\uad00\ud558\ub2e4\uac00 \ub204\uad70\uac00\uc758 \uc774\ub984\uc774\ub098 \ub2f9\uc2dc\uc758 \uc77c\uc744 \ub5a0\uc62c\ub9b0 \uacbd\ud5d8\uc774 \uc788\uc744 \uac83\uc774\ub2e4. \uc774 \uadf8\ub9bc\uc5d0\uc11c\ub294 \uadf8 \ub2e8\uc11c\uac00 \uc791\ud488 \uc544\ub798\uc5d0 \ucc98\uc74c\ubd80\ud130 \ud568\uaed8 \uc801\ud600 \uc788\uc5c8\ub2e4. \ub2e4\uc74c\uc5d0 \uc61b \uadf8\ub9bc \uc18d\uc758 \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc5ec \uc788\ub294 \uc7a5\uba74\uc744 \ub9cc\ub098\uba74 \ud48d\uacbd\ub9cc \ubcf4\uace0 \uc9c0\ub098\uce58\uc9c0 \ub9d0\uace0 \uc8fc\ubcc0\uc758 \uae00\uc528\ub3c4 \ud55c\ubc88 \uc0b4\ud3b4\ubcf4\uc790. \uc77d\uae30 \uc5b4\ub824\uc6b4 \uae00\uc790 \uc0ac\uc774\uc5d0, \ub204\uac00 \ud568\uaed8\ud588\ub294\uc9c0 \uc78a\uc9c0 \uc54a\uc73c\ub824 \ub0a8\uae34 \uba85\ub2e8\uc774 \uc788\uc744\uc9c0\ub3c4 \ubaa8\ub978\ub2e4."}, {"id": "dorian-gray-portrait-and-conscience", "title": "\ub3c4\ub9ac\uc5b8 \uadf8\ub808\uc774\uc758 \ucd08\uc0c1 \u2014 \uc5bc\uad74 \ub300\uc2e0 \uadf8\ub9bc\uc774 \ub299\uc5b4 \uac04\ub2e4\uba74", "summary": "\uc790\uc2e0 \ub300\uc2e0 \ubcc0\ud574 \uac00\ub294 \ucd08\uc0c1\ud654 \uc55e\uc5d0\uc11c \ub3c4\ub9ac\uc5b8\uc774 \uc5b4\ub5a4 \uc120\ud0dd\uc744 \ud558\ub294\uc9c0 \uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc744 \ub530\ub77c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Literature", "url": "stories/dorian-gray-portrait-and-conscience/index.html", "image": "media/dorian-gray-portrait-and-conscience.png", "alt": "\ube45\ud1a0\ub9ac\uc544 \uc2dc\ub300\ud48d \ud654\uc2e4\uc5d0\uc11c \uc80a\uc740 \ub3c4\ub9ac\uc5b8\uc774 \uc790\uc2e0\uc758 \ucd08\uc0c1\ud654\ub97c \ubc14\ub77c\ubcf4\ub294 \uc6d0\uc791 \uae30\ubc18 \uc0c1\uc0c1 \uc0bd\ud654.", "text": "\ub3c4\ub9ac\uc5b8 \uadf8\ub808\uc774\uc758 \ucd08\uc0c1 \u2014 \uc5bc\uad74 \ub300\uc2e0 \uadf8\ub9bc\uc774 \ub299\uc5b4 \uac04\ub2e4\uba74 \uc544\ub984\ub2e4\uc6b4 \uac89\ubaa8\uc2b5\uacfc \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc120\ud0dd\uc758 \uae30\ub85d \uc790\uc2e0 \ub300\uc2e0 \ubcc0\ud574 \uac00\ub294 \ucd08\uc0c1\ud654 \uc55e\uc5d0\uc11c \ub3c4\ub9ac\uc5b8\uc774 \uc5b4\ub5a4 \uc120\ud0dd\uc744 \ud558\ub294\uc9c0 \uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc744 \ub530\ub77c \uc77d\uc2b5\ub2c8\ub2e4. Literature \ubb38\ud654 \ub0b4 \uc5bc\uad74\uc740 \uc80a\uc740 \ubaa8\uc2b5 \uadf8\ub300\ub85c\uc778\ub370 \ub098\ub97c \uadf8\ub9b0 \uadf8\ub9bc\ub9cc \ub098\uc774\ub97c \uba39\ub294\ub2e4\uba74 \uc5b4\ub5a8\uae4c. \uc624\uc2a4\uce74 \uc640\uc77c\ub4dc\uc758 \u300e\ub3c4\ub9ac\uc5b8 \uadf8\ub808\uc774\uc758 \ucd08\uc0c1\u300f\uc740 \ub204\uad6c\ub098 \uc7a0\uae50 \ub5a0\uc62c\ub9b4 \ub9cc\ud55c \uc18c\ub9dd\uc744 \uc704\ud5d8\ud55c \uc774\uc57c\uae30\ub85c \ubc14\uafbc\ub2e4. \uadf8\ub9bc\uc774 \ub300\uc2e0 \uac04\uc9c1\ud558\ub294 \uac83\uc740 \uc138\uc6d4\ubfd0 \uc544\ub2c8\ub77c \ub3c4\ub9ac\uc5b8\uc774 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ud55c \ud589\ub3d9\uc758 \ud754\uc801\uc774\ub2e4. \uc544\ub984\ub2f5\ub2e4\ub294 \ud3c9\uac00\uac00 \uc88b\uc740 \uc0ac\ub78c\uc774\ub77c\ub294 \ud3c9\uac00\uc640 \ub4a4\uc11e\uc77c \ub54c \ubb34\uc2a8 \uc77c\uc774 \uc0dd\uae38\uae4c. \uc18c\uc124\uc740 \uc774 \uc9c8\ubb38\uc744 \ud654\ub824\ud55c \ub300\ud654\uc640 \uc740\ubc00\ud55c \ubc29, \uac10\ucd94\uace0 \uc2f6\uc740 \ucd08\uc0c1\ud654\uc5d0 \ub2f4\ub294\ub2e4. \uc544\ub798\uc5d0\ub294 \uc8fc\uc694 \uc0ac\uac74\uacfc \uacb0\ub9d0\uc774 \ud3ec\ud568\ub418\uc5b4 \uc788\ub2e4. \ud654\uac00 \ubc30\uc9c8 \ud640\uc6cc\ub4dc\ub294 \uc80a\uc740 \ub3c4\ub9ac\uc5b8\uc758 \ucd08\uc0c1\ud654\ub97c \uadf8\ub9b0\ub2e4. \ubc30\uc9c8\uc5d0\uac8c \ub3c4\ub9ac\uc5b8\uc740 \ub2e8\uc21c\ud788 \uc544\ub984\ub2e4\uc6b4 \ubaa8\ub378\uc744 \ub118\uc5b4 \uc790\uae30 \uc608\uc220\uc5d0 \uae4a\uc740 \uc601\ud5a5\uc744 \uc900 \uc874\uc7ac\ub2e4. \uc644\uc131\ub41c \uadf8\ub9bc\uc5d0\ub294 \ud654\uac00\uac00 \ub300\uc0c1\uc744 \ubc14\ub77c\ubcf4\ub294 \ub9c8\uc74c\ub3c4 \ub4e4\uc5b4 \uc788\ub2e4. \uadf8\ub9bc\uacfc \uc2e4\uc81c \uc0ac\ub78c\uc774 \ucc98\uc74c\uc5d0\ub294 \ub098\ub780\ud788 \ub193\uc778\ub2e4. \uadf8 \uc790\ub9ac\uc5d0 \ud5e8\ub9ac \uacbd\uc774 \ub4f1\uc7a5\ud55c\ub2e4. \uadf8\ub294 \uc80a\uc74c\uacfc \uc544\ub984\ub2e4\uc6c0, \ucf8c\ub77d\uc758 \uac00\uce58\ub97c \ub9e4\ub825\uc801\uc778 \ub9d0\ub85c \uc774\uc57c\uae30\ud55c\ub2e4. \ub3c4\ub9ac\uc5b8\uc740 \uadf8 \ub9d0\uc744 \ub4e3\uace0 \uc790\uc2e0\uc5d0\uac8c \uc788\ub294 \uac83\uc774 \uc5bc\ub9c8\ub098 \ube68\ub9ac \uc0ac\ub77c\uc9c8 \uc218 \uc788\ub294\uc9c0 \ub450\ub824\uc6cc\ud55c\ub2e4. \ud5e8\ub9ac\uac00 \ub0b4\ub193\ub294 \ub3c4\ubc1c\uc801\uc778 \ubb38\uc7a5\uc744 \uc18c\uc124\uc758 \ucd5c\uc885 \uc815\ub2f5\uc73c\ub85c \uace7\ubc14\ub85c \ubc1b\uc544\ub4e4\uc774\uc9c0\ub294 \ub9d0\uc790. \uadf8 \ub9d0\uc774 \ub3c4\ub9ac\uc5b8\uc5d0\uac8c \ubbf8\uce58\ub294 \uc601\ud5a5\ub3c4 \uc774\uc57c\uae30\uc758 \uc77c\ubd80\ub2e4. \ub3c4\ub9ac\uc5b8\uc740 \uadf8\ub9bc\uc740 \uc80a\uac8c \ub0a8\uace0 \uc790\uc2e0\ub9cc \ub299\ub294 \ud604\uc2e4\uc744 \uacac\ub514\uae30 \uc5b4\ub824\uc6cc\ud55c\ub2e4. \ucc28\ub77c\ub9ac \uc790\uc2e0\uc774 \uadf8\ub300\ub85c \uc788\uace0 \uadf8\ub9bc\uc774 \ub2ec\ub77c\uc84c\uc73c\uba74 \uc88b\uaca0\ub2e4\uace0 \ubc14\ub780\ub2e4. \uc18c\ub9dd\uc740 \uc544\ub984\ub2e4\uc6b4 \uc21c\uac04\uc744 \ub193\uce58\uae30 \uc2eb\ub2e4\ub294 \ub9c8\uc74c\uc5d0\uc11c \uc2dc\uc791\ud558\uc9c0\ub9cc, \uace7 \uc0b6\uc758 \uacb0\uacfc\ub97c \ub2e4\ub978 \uacf3\uc5d0 \ub5a0\ub118\uae30\ub294 \uad6c\uc870\ub85c \uc774\uc5b4\uc9c4\ub2e4. \uc18c\uc124\uc740 \ub9c8\ubc95\uc758 \uc791\ub3d9 \uc6d0\ub9ac\ub97c \uae30\uc220 \uc124\uba85\uc11c\ucc98\ub7fc \ud480\uc9c0 \uc54a\ub294\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \uc18c\ub9dd\uc774 \uc774\ub8e8\uc5b4\uc9c4 \ub4a4 \ub3c4\ub9ac\uc5b8\uc774 \uc5b4\ub5a4 \uad00\uacc4\ub97c \ub9fa\ub294\uac00\ub2e4. \uac89\uc73c\ub85c\ub294 \uc774\uc804\uacfc \uac19\uc740 \uc5bc\uad74\uc744 \ubcf4\uc5ec \uc904 \uc218 \uc788\ub2e4\uba74 \uadf8\ub294 \ubb34\uc5c7\uae4c\uc9c0 \ud574\ub3c4 \ub41c\ub2e4\uace0 \uc0dd\uac01\ud558\uac8c \ub420\uae4c. \ucd08\uc0c1\ud654\ub294 \uc7a5\uc2dd\ud488\uc5d0\uc11c \uac10\ucd94\uace0 \uc2f6\uc740 \uae30\ub85d\uc73c\ub85c \ubc14\ub010\ub2e4. \ub3c4\ub9ac\uc5b8\uc740 \ubc30\uc6b0 \uc2dc\ube4c \ubca0\uc778\uc744 \uc0ac\ub791\ud55c\ub2e4\uace0 \ub290\ub080\ub2e4. \ubb34\ub300\uc5d0\uc11c \uc5ec\ub7ec \uc778\ubb3c\uc744 \uc5f0\uae30\ud558\ub294 \uadf8\ub140\uc758 \ubaa8\uc2b5\uc5d0 \ub9e4\ub8cc\ub41c\ub2e4. \uadf8\ub7f0\ub370 \uc2dc\ube4c\uc774 \uc2e4\uc81c \uc0ac\ub791\uc744 \uacbd\ud5d8\ud55c \ub4a4 \uc5f0\uae30\ub97c \uc804\ucc98\ub7fc \ud558\uc9c0 \ubabb\ud558\uc790 \ub3c4\ub9ac\uc5b8\uc758 \ud0dc\ub3c4\uac00 \uae09\uaca9\ud788 \ub2ec\ub77c\uc9c4\ub2e4. \uadf8\ub294 \uadf8\ub140\uc758 \uacf5\uc5f0\uc5d0 \uc2e4\ub9dd\ud558\uace0 \uc794\uc778\ud55c \ub9d0\uc744 \ud55c\ub2e4. \uc5ec\uae30\uc11c \uc0ac\ub791\ud55c \uac83\uc774 \ud55c \uc0ac\ub78c\uc758 \uc0b6\uc778\uc9c0, \uc790\uc2e0\uc774 \ubc14\ub77c\ubcf4\ub358 \uc544\ub984\ub2e4\uc6b4 \uacf5\uc5f0\uc778\uc9c0 \ubb3b\uac8c \ub41c\ub2e4. \uc2dc\ube4c\uc5d0\uac8c\ub294 \ubb34\ub300 \ubc16\uc758 \ub9c8\uc74c\uc774 \uc0dd\uacbc\ub294\ub370 \ub3c4\ub9ac\uc5b8\uc740 \uc790\uc2e0\uc744 \uc990\uac81\uac8c \ud574 \uc8fc\ub358 \ubaa8\uc2b5\uc774 \uc0ac\ub77c\uc84c\ub2e4\uace0 \ubc18\uc751\ud55c\ub2e4. \uc774\ud6c4 \uc2dc\ube4c\uc758 \uc8fd\uc74c\uc774 \uc804\ud574\uc9c0\uace0, \ucd08\uc0c1\ud654\uc5d0\ub294 \uc774\uc804\uacfc \ub2e4\ub978 \ud45c\uc815\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \ub3c4\ub9ac\uc5b8\uc740 \ucd08\uc0c1\ud654\uc5d0 \uc790\uc2e0\uc758 \ud589\ub3d9\uacfc \uc5f0\uacb0\ub41c \ubcc0\ud654\uac00 \uc0dd\uae34\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc54c\uc544\ucc28\ub9b0\ub2e4. \uadf8\ub9bc\uc744 \ub0a8\uc5d0\uac8c \ubcf4\uc774\uc9c0 \uc54a\ub294 \uacf3\uc5d0 \uac10\ucd94\uba74 \ubc14\uae65\uc758 \uc0ac\ub78c\ub4e4\uc740 \uc5ec\uc804\ud788 \uc80a\uace0 \ub9e4\ub825\uc801\uc778 \uadf8\ub97c \ub9cc\ub09c\ub2e4. \ubcf4\uc774\ub294 \ubaa8\uc2b5\uacfc \ubcf4\uc774\uc9c0 \uc54a\ub294 \uae30\ub85d \uc0ac\uc774\uc5d0 \uac70\ub9ac\uac00 \ubc8c\uc5b4\uc9c4\ub2e4. \uadf8\ub294 \ucde8\ud5a5\uacfc \uac10\uac01\uc758 \uc990\uac70\uc6c0\uc744 \uc887\uc73c\uba70 \uc0b4\uc544\uac04\ub2e4. \uc18c\uc124\uc774 \uc637\uac10\uacfc \ud5a5, \uc74c\uc545\uacfc \uc218\uc9d1\ud488\uc744 \uae38\uac8c \ub098\uc5f4\ud558\ub294 \ub300\ubaa9\ub3c4 \uc774 \uc0b6\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uc544\ub984\ub2e4\uc6b4 \uac83\uc744 \uc88b\uc544\ud558\ub294 \uc77c \uc790\uccb4\uac00 \uc8c4\ub77c\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ubbf8\uce5c \uacb0\uacfc\ub97c \uac00\ub9b0 \ucc44 \uc990\uac70\uc6c0\ub9cc\uc73c\ub85c \uc790\uae30\ub97c \uc124\uba85\ud558\ub824\ub294 \ud0dc\ub3c4\uac00 \ubb38\uc81c\ub97c \ud0a4\uc6b4\ub2e4. \uc138\uc6d4\uc774 \uc9c0\ub098\uba74\uc11c \ub3c4\ub9ac\uc5b8\uc5d0 \uad00\ud55c \uc88b\uc9c0 \uc54a\uc740 \uc18c\ubb38\uc774 \uc774\uc5b4\uc9c4\ub2e4. \ubc30\uc9c8\uc740 \ud55c\ub54c \uc790\uae30 \uc608\uc220\uc758 \uc911\uc2ec\uc774\uc5c8\ub358 \uc0ac\ub78c\uc5d0\uac8c \ubb34\uc2a8 \uc77c\uc774 \uc0dd\uacbc\ub294\uc9c0 \uc54c\uace0 \uc2f6\uc5b4 \ud55c\ub2e4. \ub3c4\ub9ac\uc5b8\uc774 \ucd08\uc0c1\ud654\ub97c \ubcf4\uc5ec \uc8fc\uc790 \uadf8\ub294 \uadf8\ub9bc\uc774 \ud488\uc740 \ubcc0\ud654\ub97c \ub9c8\uc8fc\ud558\uace0 \ub450\ub824\uc6cc\ud55c\ub2e4. \ubc30\uc9c8\uc740 \ub3c4\ub9ac\uc5b8\uc5d0\uac8c \ub3cc\uc544\uc124 \uae38\uc744 \uad8c\ud558\uc9c0\ub9cc, \ub3c4\ub9ac\uc5b8\uc740 \uadf8\ub97c \uc0b4\ud574\ud55c\ub2e4. \uadf8\ub9bc\uc774 \uc678\ubd80\uc758 \ubb3c\uac74\uc774\ub77c\uace0 \ud574\uc11c \uadf8 \uc55e\uc5d0\uc11c \uc0dd\uae30\ub294 \uac10\uc815\uc744 \ub2e4\ub8f0 \uc218 \uc788\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc790\uc2e0\uc758 \ubaa8\uc2b5\uc744 \uc99d\uc5b8\ud558\ub294 \uc0ac\ub78c\uc744 \uc5c6\uc560\ub3c4 \uc774\ubbf8 \uc77c\uc5b4\ub09c \uc120\ud0dd\uc740 \uc0ac\ub77c\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \uc228\uae30\ub294 \ud589\uc704\uac00 \ub610 \ub2e4\ub978 \ud3ed\ub825\uc73c\ub85c \uc774\uc5b4\uc9c4\ub2e4. \ub3c4\ub9ac\uc5b8\uc740 \uc568\ub7f0 \ucea0\ubca8\uc744 \uc555\ubc15\ud574 \uc0b4\ud574\uc758 \ud754\uc801\uc744 \ucc98\ub9ac\ud558\uac8c \ud55c\ub2e4. \uc5ec\uae30\uc5d0\uc11c\ub3c4 \uc790\uc2e0\uc774 \uc800\uc9c0\ub978 \uc77c\uc758 \ub4a4\ucc98\ub9ac\ub97c \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ub118\uae34\ub2e4. \ucd08\uc0c1\ud654\uac00 \ub300\uc2e0 \ub299\uc5b4 \uc8fc\ub294 \uad6c\uc870\uc640, \uc8fc\ubcc0 \uc0ac\ub78c\ub4e4\uc5d0\uac8c \uacb0\uacfc\ub97c \uac10\ub2f9\ud558\uac8c \ud558\ub294 \ud589\ub3d9\uc774 \uc11c\ub85c \ub2ee\uc544 \uac04\ub2e4. \ubc14\uae65\uc5d0\uc11c \ubcf4\ub294 \ub3c4\ub9ac\uc5b8\uc740 \uc5ec\uc804\ud788 \ubcc0\ud654\uac00 \uc801\uc9c0\ub9cc \uad00\uacc4\ub294 \uadf8\ub807\uc9c0 \uc54a\ub2e4. \ube44\ubc00\uc744 \uc720\uc9c0\ud558\ub824\uba74 \ub354 \ub9ce\uc740 \uac70\uc9d3\uacfc \uc555\ubc15\uc774 \ud544\uc694\ud574\uc9c4\ub2e4. \uc80a\uc74c\uc744 \ubcf4\uc874\ud55c \uac83\uc774 \ub450\ub824\uc6c0\uc744 \uc904\uc5ec \uc8fc\uae30\ubcf4\ub2e4 \ub450\ub824\uc6c0\uc744 \uac10\ucd9c \uacf5\uac04\uc744 \ub298\ub838\ub2e4\ub294 \uac10\uc0c1\uc774 \uac00\ub2a5\ud558\ub2e4. \uadf8\ub294 \uc790\uc720\ub85c\uc6cc\uc9c4 \ub4ef \ubcf4\uc774\uba74\uc11c\ub3c4 \uadf8\ub9bc\uc758 \uc874\uc7ac\uc5d0 \ubd99\uc7a1\ud78c\ub2e4. \ud6c4\ubc18\uc758 \ub3c4\ub9ac\uc5b8\uc740 \uc790\uc2e0\uc758 \ubcc0\ud654 \uac00\ub2a5\uc131\uc744 \uc0dd\uac01\ud558\uc9c0\ub9cc \ucd08\uc0c1\ud654\uc5d0\uc11c \uae30\ub300\ud55c \uae68\ub057\ud568\uc744 \ucc3e\uc9c0 \ubabb\ud55c\ub2e4. \uadf8\ub294 \ub9c8\uce68\ub0b4 \uadf8\ub9bc\uc744 \ud30c\uad34\ud558\ub824\uace0 \uce7c\uc744 \ub4e0\ub2e4. \uacb0\uacfc\ub97c \ub2f4\uace0 \uc788\ub294 \ubb3c\uac74\uc744 \uc5c6\uc560\uba74 \uadf8 \uacb0\uacfc\ub85c\ubd80\ud130 \ubc97\uc5b4\ub0a0 \uc218 \uc788\ub2e4\uace0 \uc5ec\uae30\ub294 \ub4ef\ud55c \ud589\ub3d9\uc774\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \ubc29\uc5d0 \ub4e4\uc5b4\uc654\uc744 \ub54c \uadf8\ub9bc\uc740 \ub2e4\uc2dc \uc80a\uc740 \ub3c4\ub9ac\uc5b8\uc758 \ubaa8\uc2b5\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ubc14\ub2e5\uc5d0\ub294 \ub299\uace0 \ubcc0\ud55c \ub0a8\uc790\uac00 \uc4f0\ub7ec\uc838 \uc788\uace0, \ubc18\uc9c0 \ub4f1\uc744 \ud1b5\ud574 \uadf8\uac00 \ub3c4\ub9ac\uc5b8\uc784\uc744 \uc54c\uc544\ubcf8\ub2e4. \uac89\ubaa8\uc2b5\uacfc \uac10\ucd94\uc5b4 \ub454 \uae30\ub85d\uc744 \ubd84\ub9ac\ud574 \ub193\ub358 \uc18c\ub9dd\uc740 \ub9c8\uc9c0\ub9c9\uc5d0 \ubb34\ub108\uc9c4\ub2e4. \uadf8\ub294 \uadf8\ub9bc \ubc16\uc5d0\uc11c\ub3c4 \uc790\uae30 \uc0b6\uc744 \ubc97\uc5b4\ub0a0 \uc218 \uc5c6\uc5c8\ub2e4. \uc18c\uc124\uc740 \uc544\ub984\ub2e4\uc6b4 \uc5bc\uad74\uacfc \uc544\ub984\ub2e4\uc6b4 \uc608\uc220\uc744 \ub9ce\uc774 \uc774\uc57c\uae30\ud558\uc9c0\ub9cc \ub2e8\uc21c\ud788 \uc544\ub984\ub2e4\uc6c0\uc740 \uc704\ud5d8\ud558\ub2e4\ub294 \uad50\ud6c8\uc73c\ub85c \uc904\uc774\uae30 \uc5b4\ub835\ub2e4. \ubc30\uc9c8\uacfc \ud5e8\ub9ac, \ub3c4\ub9ac\uc5b8\uc774 \uac19\uc740 \uc544\ub984\ub2e4\uc6c0\uc5d0 \uc11c\ub85c \ub2e4\ub974\uac8c \ubc18\uc751\ud558\uae30 \ub54c\ubb38\uc774\ub2e4. \ubbf8\uc801\uc778 \uc990\uac70\uc6c0\uacfc \ud0c0\uc778\uc5d0 \ub300\ud55c \ucc45\uc784\uc740 \uc5b4\ub5a4 \uad00\uacc4\uc5d0 \ub193\uc77c \uc218 \uc788\uc744\uae4c. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\uc740 \uc18c\uc124\uc758 \uc778\ubb3c\uacfc \ud654\uc2e4\uc744 \uc0c8\ub85c \uc0c1\uc0c1\ud55c AI \uc0bd\ud654\ub2e4. \ud2b9\uc815 \uc601\ud654\uc758 \ubc30\uc6b0\ub098 \uc2e4\uc81c \ucd08\uc0c1\ud654\ub97c \uc7ac\ud604\ud55c \uac83\uc774 \uc544\ub2c8\ub2e4. \uadf8\ub9bc \uc18d \uc80a\uc740 \uc5bc\uad74\uc744 \ubcf4\uba70 \uc6b0\ub9ac\uac00 \uadf8 \uc0ac\ub78c\uc5d0 \ub300\ud574 \uc5bc\ub9c8\ub098 \ub9ce\uc740 \uac83\uc744 \uc131\uae09\ud788 \uc9d0\uc791\ud558\ub294\uc9c0 \ub5a0\uc62c\ub9ac\uba74, \uc624\ub798\ub41c \uc18c\uc124\uc758 \uc9c8\ubb38\ub3c4 \uc870\uae08 \uac00\uae4c\uc6cc\uc9c4\ub2e4."}, {"id": "eighty-days-time-and-travel", "title": "80\uc77c\uac04\uc758 \uc138\uacc4 \uc77c\uc8fc \u2014 \uc2dc\uacc4\ubcf4\ub2e4 \ub2a6\uac8c \uc54c\uac8c \ub41c \uc5ec\ud589\uc758 \uc758\ubbf8", "summary": "\uad50\ud1b5\uc218\ub2e8\uacfc \uc2dc\uac04 \uacc4\uc0b0\uc744 \ub530\ub77c\uac00\uba70 \ud3ec\uadf8\uac00 \ub0b4\uae30 \ubc16\uc5d0\uc11c \uc5bb\uc740 \uac83\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Literature", "url": "stories/eighty-days-time-and-travel/index.html", "image": "media/eighty-days-time-and-travel.png", "alt": "1870\ub144\ub300 \uae30\ucc28\uc5ed \ubd84\uc704\uae30 \uc18d\uc5d0\uc11c \ud68c\uc911\uc2dc\uacc4\ub97c \ubcf4\ub294 \ud3ec\uadf8\uc640 \uae30\ucc28\ub97c \uc0b4\ud53c\ub294 \ud30c\uc2a4\ud30c\ub974\ud22c\ub97c \uadf8\ub9b0 \uc0c1\uc0c1 \uc0bd\ud654.", "text": "80\uc77c\uac04\uc758 \uc138\uacc4 \uc77c\uc8fc \u2014 \uc2dc\uacc4\ubcf4\ub2e4 \ub2a6\uac8c \uc54c\uac8c \ub41c \uc5ec\ud589\uc758 \uc758\ubbf8 \ud3ec\uadf8\uc640 \ud30c\uc2a4\ud30c\ub974\ud22c, \uacc4\ud68d\uacfc \uc6b0\uc5f0\uc774 \ud568\uaed8 \uc6c0\uc9c1\uc774\ub294 \ubaa8\ud5d8 \uad50\ud1b5\uc218\ub2e8\uacfc \uc2dc\uac04 \uacc4\uc0b0\uc744 \ub530\ub77c\uac00\uba70 \ud3ec\uadf8\uac00 \ub0b4\uae30 \ubc16\uc5d0\uc11c \uc5bb\uc740 \uac83\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Literature \ubb38\ud654 \ub9e4\uc77c \uac19\uc740 \uc2dc\uac04\uc5d0 \uc9d1\uc744 \ub098\uc11c\uace0 \uac19\uc740 \uc2b5\uad00\uc744 \uc9c0\ud0a4\ub294 \uc0ac\ub78c\uc774 \uc788\ub2e4. \ud544\ub9ac\uc5b4\uc2a4 \ud3ec\uadf8\uc5d0\uac8c \ud558\ub8e8\ub294 \uc815\ubc00\ud558\uac8c \ub9de\ucd98 \uc2dc\uacc4\ucc98\ub7fc \ubcf4\uc778\ub2e4. \uadf8\ub7f0\ub370 \uadf8\uac00 \uc5b4\ub290 \ub0a0 80\uc77c \uc548\uc5d0 \uc138\uacc4\ub97c \ub3cc\uc544\uc624\uaca0\ub2e4\ub294 \ub0b4\uae30\uc5d0 \ub098\uc120\ub2e4. \uc9c8\uc11c\uc815\uc5f0\ud55c \uc0ac\ub78c\uc774 \uc608\uce21\ud560 \uc218 \uc5c6\ub294 \uc138\uacc4\ub85c \ub4e4\uc5b4\uac00\ub294 \uc21c\uac04\uc774\ub2e4. \uc958 \ubca0\ub978\uc758 \u300e80\uc77c\uac04\uc758 \uc138\uacc4 \uc77c\uc8fc\u300f\uc5d0\uc11c\ub294 \uae30\ucc28\uc640 \ubc30\uac00 \uae38\uc744 \uc787\uace0 \uc0ac\uace0\uc640 \uc624\ud574\uac00 \uadf8 \uae38\uc744 \uc790\uafb8 \ubc14\uafbc\ub2e4. \uc0c8\ub85c\uc6b4 \ud558\uc778 \ud30c\uc2a4\ud30c\ub974\ud22c\ub294 \uc870\uc6a9\ud55c \uc77c\uc790\ub9ac\ub97c \uae30\ub300\ud588\ub2e4\uac00 \ub73b\ubc16\uc758 \ubaa8\ud5d8\uc5d0 \ud718\ub9d0\ub9b0\ub2e4. \uc544\ub798\uc5d0\ub294 \uc8fc\uc694 \uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc774 \ud3ec\ud568\ub418\uc5b4 \uc788\ub2e4. \uc774\uc57c\uae30\uc758 \ucd9c\ubc1c\uc810\uc740 1872\ub144 \ub7f0\ub358\uc774\ub2e4. \ub9ac\ud3fc \ud074\ub7fd\uc5d0\uc11c \uc138\uacc4 \uc5ec\ud589\uc5d0 \uac78\ub9ac\ub294 \uc2dc\uac04\uc744 \ub17c\ud558\ub358 \ud3ec\uadf8\ub294 80\uc77c\uc774\ub77c\ub294 \uacc4\uc0b0\uc5d0 \uc790\uae30 \ub3c8 2\ub9cc \ud30c\uc6b4\ub4dc\ub97c \uac74\ub2e4. \uae30\ucc28\uc640 \uc99d\uae30\uc120\uc758 \uc5f0\uacb0\uc774 \uc138\uacc4\ub97c \ub354 \uc791\uac8c \ubcf4\uc774\uac8c \ud558\ub358 \uc2dc\ub300\ub2e4. \ud558\uc9c0\ub9cc \uc608\uc815\ud45c\uc5d0\uc11c \uc120 \ud558\ub098\ub85c \uc774\uc5b4\uc9c0\ub294 \uae38\ub3c4 \ud604\uc7a5\uc5d0\uc11c\ub294 \ub2e4\ub974\ub2e4. \uae30\ucc28\ub97c \ub193\uce60 \uc218 \uc788\uace0 \ubc30\uc758 \ucd9c\ud56d \uc2dc\uac04\uc774 \ubc14\ub014 \uc218 \uc788\uc73c\uba70, \ub178\uc120\uc774 \uc644\uc131\ub418\uc5c8\ub2e4\ub294 \ub9d0\uacfc \uc2e4\uc81c\ub85c \ub05d\uae4c\uc9c0 \ub2ec\ub9b4 \uc218 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc5b4\uae0b\ub098\uae30\ub3c4 \ud55c\ub2e4. \uacc4\uc0b0 \uac00\ub2a5\ud55c \uc2dc\uac04\uacfc \ubab8\uc73c\ub85c \ud1b5\uacfc\ud574\uc57c \ud558\ub294 \uc2dc\uac04\uc774 \uc18c\uc124\uc758 \uae34\uc7a5\uc744 \ub9cc\ub4e0\ub2e4. \ud3ec\uadf8\ub294 \uce68\ucc29\ud558\uace0 \ub3c8\uc744 \uc368\uc11c\ub77c\ub3c4 \uc77c\uc815\uc744 \uc9c0\ud0a4\ub824 \ud55c\ub2e4. \ud30c\uc2a4\ud30c\ub974\ud22c\ub294 \uc8fc\ubcc0\uc744 \uad81\uae08\ud574\ud558\uace0 \uc0ac\ub78c\uacfc \ubd80\ub52a\uce58\uba70 \ub2f9\ud669\ud558\uae30\ub3c4 \ud55c\ub2e4. \uac19\uc740 \ubaa9\uc801\uc9c0\ub85c \uac00\uc9c0\ub9cc \uc138\uacc4\ub97c \ub300\ud558\ub294 \ubc29\uc2dd\uc774 \ub2e4\ub974\ub2e4. \ub3c5\uc790\ub294 \ub450 \uc0ac\ub78c\uc758 \ucc28\uc774 \ub355\ubd84\uc5d0 \uc2dc\uac04\ud45c \ubc16\uc758 \uc7a5\uba74\ub4e4\ub3c4 \ub9cc\ub098\uac8c \ub41c\ub2e4. \uc5b4\ub290 \ud55c\ucabd\uc774 \ub298 \uc633\uc740 \uac83\uc740 \uc544\ub2c8\ub2e4. \ube60\ub978 \ud310\ub2e8\uc774 \uc704\uae30\ub97c \ud480 \ub54c\ub3c4 \uc788\uace0, \ud638\uae30\uc2ec\uacfc \uc2e4\uc218\uac00 \ub73b\ubc16\uc758 \uace4\ub780\uc744 \ub9cc\ub4e4 \ub54c\ub3c4 \uc788\ub2e4. \ub450 \uc0ac\ub78c\uc774 \uc11c\ub85c\uc758 \ubd80\uc871\ud55c \ubd80\ubd84\uc744 \ucc44\uc6b0\uac70\ub098 \ub2e4\uc2dc \uc218\uc2b5\ud558\ub294 \uacfc\uc815\uc774 \uc5ec\ud589\uc744 \ub2e8\uc21c\ud55c \uae30\ub85d \uacbd\uc7c1 \uc774\uc0c1\uc758 \uc774\uc57c\uae30\ub85c \ub9cc\ub4e0\ub2e4. \ud615\uc0ac \ud53d\uc2a4\ub294 \ud3ec\uadf8\ub97c \uc740\ud589 \uc808\ub3c4 \uc0ac\uac74\uc758 \ubc94\uc778\uc73c\ub85c \uc758\uc2ec\ud55c\ub2e4. \uae09\ud788 \ub9ce\uc740 \ub3c8\uc744 \uac00\uc9c0\uace0 \uc774\ub3d9\ud558\ub294 \ud589\ub3d9\uc774 \uadf8\uc758 \ub208\uc5d0\ub294 \ub3c4\uc8fc\ucc98\ub7fc \ubcf4\uc778\ub2e4. \ud3ec\uadf8\uc5d0\uac8c\ub294 \ub0b4\uae30\uc758 \uc77c\uc815\uc774\uc9c0\ub9cc \ud53d\uc2a4\uc5d0\uac8c\ub294 \ubc94\uc778\uc758 \ud754\uc801\uc774\ub2e4. \uac19\uc740 \ud589\ub3d9\uc744 \uc11c\ub85c \ub2e4\ub978 \uc774\uc57c\uae30 \uc548\uc5d0\uc11c \ud574\uc11d\ud558\ub294 \uc148\uc774\ub2e4. \uc624\ud574\ub294 \ub2e8\uc21c\ud55c \uc7a5\uc2dd\uc774 \uc544\ub2c8\ub2e4. \uc758\uc2ec\ud55c \uc0ac\ub78c\uc774 \uc790\uae30 \ud574\uc11d\uc744 \ud655\uc2e0\ud558\uba70 \uc6c0\uc9c1\uc77c \ub54c \ub2e4\ub978 \uc0ac\ub78c\uc758 \uae38\uc774 \uc2e4\uc81c\ub85c \ub9c9\ud78c\ub2e4. \ub3c5\uc790\ub294 \ud3ec\uadf8\uac00 \uc5b4\ub5a4 \uc0ac\ub78c\uc778\uc9c0 \uc54c\uace0 \uc9c0\ucf1c\ubcf4\ubbc0\ub85c \ud53d\uc2a4\uc758 \ucd94\uc801\uc5d0\uc11c \ub2f5\ub2f5\ud568\uacfc \uc6c3\uc74c\uc744 \ud568\uaed8 \ub290\ub07c\uac8c \ub41c\ub2e4. \uc5ec\ud589 \uc911 \uc778\ub3c4\uc758 \ucca0\uae38\uc774 \uc774\uc5b4\uc9c0\uc9c0 \uc54a\uc740 \uad6c\uac04\uc744 \ub9cc\ub098\uc790 \uc77c\ud589\uc740 \ub2e4\ub978 \uc774\ub3d9 \uc218\ub2e8\uc744 \uad6c\ud55c\ub2e4. \ucf54\ub07c\ub9ac\ub97c \ud0c0\uace0 \ub098\uc544\uac00\ub294 \uacfc\uc815\uc5d0\uc11c \uc544\uc6b0\ub2e4\ub97c \uad6c\ud558\uac8c \ub41c\ub2e4. \uc2dc\uac04\uc744 \uc544\uaef4\uc57c \ud558\ub294 \ud3ec\uadf8\uac00 \ub2e4\ub978 \uc0ac\ub78c\uc744 \uc704\ud574 \uc704\ud5d8\uacfc \uc9c0\uc5f0\uc744 \uac10\uc218\ud558\ub294 \ub300\ubaa9\uc774\ub2e4. \uc774 \uc7a5\uba74\uc744 \uc77d\uc744 \ub54c\uc5d0\ub294 \ub2f9\uc2dc \uc720\ub7fd \uc18c\uc124\uc774 \ub0af\uc120 \uc9c0\uc5ed\uc744 \uadf8\ub9ac\ub294 \ubc29\uc2dd\ub3c4 \ud568\uaed8 \uc0dd\uac01\ud558\uba74 \uc88b\ub2e4. \uc791\ud488 \uc18d \uc704\ud5d8\uacfc \ud48d\uc2b5 \ubb18\uc0ac\ub97c \uadf8 \ub098\ub77c \uc0ac\ub78c\ub4e4\uc758 \uc0dd\ud65c \uc804\uccb4\ub85c \uc77c\ubc18\ud654\ud560 \uc218\ub294 \uc5c6\ub2e4. \ubaa8\ud5d8\uc758 \uc7ac\ubbf8\ub97c \uc77d\uc73c\uba74\uc11c\ub3c4 \uc11c\uc220\uc790\uc758 \uc2dc\uc120\uc774 \uc5b4\ub514\uc5d0\uc11c \uc654\ub294\uc9c0 \uc0b4\ud544 \uc5ec\uc9c0\ub294 \uc788\ub2e4. \uc544\uc6b0\ub2e4\ub294 \uad6c\uc870 \ub4a4 \uc5ec\ud589\uc758 \ub3d9\ud589\uc790\uac00 \ub41c\ub2e4. \ud3ec\uadf8\uc758 \ucc98\uc74c \uacc4\ud68d\uc5d0\ub294 \uc5c6\ub358 \uc0ac\ub78c\uc774\ub2e4. \ub0af\uc120 \uc774\ub97c \ub3d5\ub294 \uc120\ud0dd\uc774 \uc77c\ud589\uc758 \uad6c\uc131\uacfc \uc774\ud6c4\uc758 \uc0b6\uc744 \ubc14\uafbc\ub2e4. \uc5ec\ud589\uc774\ub780 \uc608\uc815\ud55c \uc9c0\uc810\uc744 \ud655\uc778\ud558\ub294 \uc77c\ub9cc\uc774 \uc544\ub2c8\ub77c \uc608\uc0c1\ud558\uc9c0 \ubabb\ud55c \uad00\uacc4\ub97c \ubc1b\uc544\ub4e4\uc774\ub294 \uc2dc\uac04\uc774\uae30\ub3c4 \ud558\ub2e4\ub294 \uc77d\uae30\uac00 \uac00\ub2a5\ud558\ub2e4. \ud3ec\uadf8\uac00 \ubaa8\ub4e0 \uad6c\uac04\uc5d0\uc11c \uac10\uc815\uc744 \uae38\uac8c \uc124\uba85\ud558\ub294 \uc778\ubb3c\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub798\uc11c \ub3c5\uc790\ub294 \ub9d0\ubcf4\ub2e4 \uc5b4\ub5a4 \uc0c1\ud669\uc5d0\uc11c \ub3c8\uacfc \uc2dc\uac04\uc744 \uc4f0\ub294\uc9c0 \uad00\ucc30\ud558\uac8c \ub41c\ub2e4. \uacc4\uc0b0\uc744 \uc798\ud558\ub294 \uc0ac\ub78c\uc774\ub77c\ub294 \uc18c\uac1c\ub9cc\uc73c\ub85c \uadf8\uc758 \ud589\ub3d9\uc744 \ub2e4 \uc774\ud574\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc77c\uc815\uc774 \ubd88\ub9ac\ud574\uc9c8 \ub54c \ubb34\uc5c7\uc744 \ud3ec\uae30\ud558\uc9c0 \uc54a\ub294\uc9c0\uac00 \uadf8\ub97c \ub354 \uc798 \ubcf4\uc5ec \uc900\ub2e4. \ub3d9\uc544\uc2dc\uc544\uc640 \ud0dc\ud3c9\uc591\uc744 \uc9c0\ub098 \ubbf8\uad6d\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \uc5ec\uc815\uc5d0\uc11c\ub3c4 \uc77c\ud589\uc740 \uacc4\uc18d \uad50\ud1b5\ud3b8\uc744 \ubc14\uafb8\uace0 \uc2dc\uac04\uc744 \ub9de\ucd98\ub2e4. \uae30\uacc4\uac00 \ube68\ub77c\uc84c\ub2e4\uace0 \uc5ec\ud589\uc774 \ub9c8\ucc30 \uc5c6\uc774 \uc9c4\ud589\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uae38\uc758 \uc870\uac74\uacfc \uc0ac\ub78c\ub4e4\uc758 \uacb0\uc815\uc774 \ub9e4\ubc88 \uc0ac\uc774\uc5d0 \ub07c\uc5b4\ub4e0\ub2e4. \ud754\ud788 \uac01\uc0c9\uc758 \uc774\ubbf8\uc9c0\ub85c \ub5a0\uc62c\ub9ac\ub294 \uc5f4\uae30\uad6c\uac00 \uc6d0\uc791\uc758 \uc138\uacc4 \uc77c\uc8fc\ub97c \ub04c\uace0 \uac00\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc6d0\ubb38\uc5d0\uc11c\ub294 \ucca0\ub3c4\uc640 \uc5ec\ub7ec \ubc30, \ucf54\ub07c\ub9ac \ub4f1 \uad6c\uccb4\uc801\uc778 \uc218\ub2e8\uc774 \uc911\uc694\ud558\ub2e4. \uc5b4\ub5a4 \uc7a5\uba74\uc744 \uae30\uc5b5\ud558\uace0 \uc788\uc5c8\ub294\uc9c0 \uc6d0\uc791\uacfc \ube44\uad50\ud558\ub294 \uc7ac\ubbf8\ub3c4 \uc788\ub2e4. \uc774\ubc88 \uc0bd\ud654\ub3c4 \uc774\ub3d9\uacfc \uae30\ub2e4\ub9bc\uc774 \ub9cc\ub098\ub294 \uae30\ucc28\uc5ed\uc758 \ubd84\uc704\uae30\ub97c \uc120\ud0dd\ud588\ub2e4. \uc601\uad6d\uc5d0 \ub3cc\uc544\uc628 \ub4a4 \ud53d\uc2a4\uc758 \uccb4\ud3ec \ub54c\ubb38\uc5d0 \uc2dc\uac04\uc774 \ub354 \uc9c0\uccb4\ub41c\ub2e4. \ud3ec\uadf8\ub294 \uc790\uc2e0\uc774 \ub0b4\uae30\uc5d0\uc11c \uc84c\ub2e4\uace0 \ubbff\ub294\ub2e4. \uadf8\ub7ec\ub098 \ud30c\uc2a4\ud30c\ub974\ud22c\uac00 \ub0a0\uc9dc\ub97c \ud655\uc778\ud558\uba74\uc11c \uc0c1\ud669\uc774 \ub4a4\uc9d1\ud78c\ub2e4. \ub3d9\ucabd\uc73c\ub85c \uc138\uacc4\ub97c \ub3cc\uc544\uc628 \ub3d9\uc548 \uacc4\uc0b0\uc5d0 \ud558\ub8e8\uc758 \ucc28\uc774\uac00 \uc0dd\uae34 \uac83\uc744 \ubbf8\ucc98 \uc54c\uc544\ucc28\ub9ac\uc9c0 \ubabb\ud588\ub358 \uac83\uc774\ub2e4. \uc18c\uc124\uc740 \ub9e4\uc77c\uc758 \uc2dc\uac04\uacfc \uc9c0\uad6c\ub97c \ud55c \ubc14\ud034 \ub3c4\ub294 \uc5ec\ud589\uc758 \uad00\uacc4\ub97c \uacb0\ub9d0\uc5d0 \uc5f0\uacb0\ud55c\ub2e4. \uc624\ub298\uc758 \ud45c\uc900\uc2dc \uc81c\ub3c4\ub97c \uadf8 \uc2dc\ub300\uc5d0 \uadf8\ub300\ub85c \uc801\uc6a9\ud574 \ub2e8\uc815\ud558\uae30\ubcf4\ub2e4 \uc791\ud488\uc774 \uc124\uba85\ud558\ub294 \u2018\uc5bb\uc740 \ud558\ub8e8\u2019\uc758 \uc7a5\uce58\ub85c \uc77d\uc73c\uba74 \uc88b\ub2e4. \ubaa8\ub4e0 \uac83\uc744 \uaf3c\uaf3c\ud788 \uacc4\uc0b0\ud558\ub358 \uc0ac\ub78c\ub3c4 \uacc4\uc0b0\uc758 \ud2c0 \ud558\ub098\ub97c \ub193\uce60 \uc218 \uc788\uc5c8\ub2e4\ub294 \uc810\uc774 \uc720\ucf8c\ud558\ub2e4. \ud3ec\uadf8\ub294 \uc57d\uc18d\ud55c \uc2dc\uac04\uc5d0 \ud074\ub7fd\uc5d0 \ub098\ud0c0\ub09c\ub2e4. \uadf8\ub7ec\ub098 \ub9c8\uc9c0\ub9c9 \uc9c8\ubb38\uc740 \uc2b9\ub9ac\ud55c \ub3c8\uc774 \uc5bc\ub9c8\ub0d0\uc5d0\ub9cc \uba38\ubb3c\uc9c0 \uc54a\ub294\ub2e4. \uc544\uc6b0\ub2e4\uc640 \ud568\uaed8\ud560 \uc0b6\uc774 \uc0dd\uacbc\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc5ec\ud589\uc758 \ub2e4\ub978 \uacb0\uc2e4\uc774 \ub41c\ub2e4. \ucc98\uc74c\uc758 \uacc4\uc0b0\uc5d0 \ub4e4\uc5b4 \uc788\uc9c0 \uc54a\uc558\ub358 \uac83\uc774 \ub05d\uc5d0\uc11c\ub294 \uc911\uc694\ud574\uc9c4\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \ud3ec\uadf8\uc640 \ud30c\uc2a4\ud30c\ub974\ud22c\ub97c 1870\ub144\ub300 \ubd84\uc704\uae30\uc758 \uac00\uc0c1 \uae30\ucc28\uc5ed\uc5d0 \ub193\uc558\ub2e4. \uc2e4\uc81c \uc5ed\uc774\ub098 \uc61b \uc778\ubb3c \uc0ac\uc9c4\uc744 \ubcf5\uc6d0\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \ud55c \uc0ac\ub78c\uc740 \uc2dc\uacc4\ub97c, \ub2e4\ub978 \uc0ac\ub78c\uc740 \ucd9c\ubc1c\ud560 \uae30\ucc28\ub97c \ubc14\ub77c\ubcf4\ub294 \ub300\ube44\ub85c \uc774\uc57c\uae30\ub97c \uc5f4\uc5c8\ub2e4. \uc138\uacc4\ub97c \ub3cc\uba70 \ub9de\ucd94\ub824\ub358 \uc2dc\uacc4\uc640, \uadf8 \uc5ec\ud589\uc5d0\uc11c \ub9cc\ub098\uac8c \ub41c \uc0ac\ub78c\uc744 \ud568\uaed8 \ub5a0\uc62c\ub9ac\uba70 \uc77d\uc5b4 \ubcf4\uc790."}, {"id": "el-greco-painting-journey", "title": "\uc720\uba85\ud55c \uadf8\ub9bc\ub3c4 \ucc98\uc74c\uc5d0\ub294 \uac70\uc808\ub2f9\ud588\ub2e4", "summary": "\uba54\ub9ac \ucee4\uc0db\uc774 \uc5d8 \uadf8\ub808\ucf54\uc758 \uc131\ubaa8\uc2b9\ucc9c\uc744 \ubbf8\uc220\uad00\uc5d0 \uc5f0\uacb0\ud558\ub824\ub358 \uc774\uc57c\uae30\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Art", "url": "stories/el-greco-painting-journey/index.html", "image": "media/el-greco-painting-journey.jpg", "alt": "\uc720\uba85\ud55c \uadf8\ub9bc\ub3c4 \ucc98\uc74c\uc5d0\ub294 \uac70\uc808\ub2f9\ud588\ub2e4\uc758 \uc8fc\uc81c\ub97c \ud45c\ud604\ud55c AI \uc124\uba85\uc6a9 \uc0bd\ud654. \uc2e4\uc81c \uc791\ud488\uc774\ub098 \uac74\ucd95\ubb3c\uc744 \uadf8\ub300\ub85c \uc7ac\ud604\ud55c \uc774\ubbf8\uc9c0\uac00 \uc544\ub2d9\ub2c8\ub2e4.", "text": "\uc720\uba85\ud55c \uadf8\ub9bc\ub3c4 \ucc98\uc74c\uc5d0\ub294 \uac70\uc808\ub2f9\ud588\ub2e4 \uc5d8 \uadf8\ub808\ucf54\uc758 \uc791\ud488\uc744 \uc704\ud574 \ubc1c \ubc97\uace0 \ub098\uc120 \ud654\uac00 \uba54\ub9ac \ucee4\uc0db\uc774 \uc5d8 \uadf8\ub808\ucf54\uc758 \uc131\ubaa8\uc2b9\ucc9c\uc744 \ubbf8\uc220\uad00\uc5d0 \uc5f0\uacb0\ud558\ub824\ub358 \uc774\uc57c\uae30\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Art \ubb38\ud654 \uc9c0\uae08 \ubbf8\uc220\uad00\uc758 \ub300\ud45c \uc791\ud488\uc774\ub77c\uace0 \ud574\uc11c \ucc98\uc74c\ubd80\ud130 \ubaa8\ub450\uac00 \uac16\uace0 \uc2f6\uc5b4 \ud588\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5d8 \uadf8\ub808\ucf54\uc758 \uc131\ubaa8\uc2b9\ucc9c\uc5d0\ub3c4 \uc120\ub73b \uc0c8 \uc9d1\uc744 \ucc3e\uc9c0 \ubabb\ud558\ub358 \uc2dc\uac04\uc774 \uc788\uc5c8\ub2e4. \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc758 \uacf5\uc2dd \uae00\uc740 \uc774 \uc791\ud488\uc774 \uc5ec\ub7ec \uae30\uad00\uc758 \uac70\uc808\uc744 \uc9c0\ub098 \uc18c\uc7a5\ud488\uc774 \ub41c \uacfc\uc815\uc744 \uc18c\uac1c\ud55c\ub2e4. \uc774\uc57c\uae30\uc758 \uac00\uc6b4\ub370\uc5d0\ub294 \ub2e4\ub978 \ud654\uac00 \uba54\ub9ac \ucee4\uc0db\uc774 \uc788\ub2e4. \uc790\uae30 \uadf8\ub9bc\uc774 \uc544\ub2cc \uc791\ud488\uc744 \uc704\ud574 \uafb8\uc900\ud788 \uc0ac\ub78c\ub4e4\uc744 \uc124\ub4dd\ud55c \uac83\uc774\ub2e4. \ubbf8\uc220\uad00\uc5d0 \ub530\ub974\uba74 \uc791\ud488\uc740 1904\ub144\uc5d0 \uc2dc\uc7a5\uc5d0 \ub098\uc654\ub2e4. \ub2f9\uc2dc \uc5d8 \uadf8\ub808\ucf54\uc758 \ud3c9\ud310\uc740 \uc9c0\uae08 \uc6b0\ub9ac\uac00 \uc0dd\uac01\ud558\ub294 \uac83\uacfc \uac19\uc9c0 \uc54a\uc558\ub2e4. \ub9c8\ub4dc\ub9ac\ub4dc\uc5d0\uc11c \ud314\ub9ac\uc9c0 \ubabb\ud55c \uc791\ud488\uc740 1904\ub144\ubd80\ud130 1905\ub144\uae4c\uc9c0 \ud30c\ub9ac\uc758 \ub4a4\ub791\ub93c\uc5d8 \ud654\ub791\uc5d0\uc11c \uc804\uc2dc\ub418\uc5c8\ub2e4. \uadf8\uacf3\uc5d0\uc11c \ucee4\uc0db\uc744 \ube44\ub86f\ud55c \ud654\uac00\ub4e4\uc774 \uc774 \uc791\ud488\uc5d0 \uad00\uc2ec\uc744 \uac00\uc84c\ub2e4. \ub204\uad70\uac00\uc5d0\uac8c\ub294 \ud314\uae30 \uc5b4\ub824\uc6b4 \uc624\ub798\ub41c \uadf8\ub9bc\uc774 \ub2e4\ub978 \ub204\uad70\uac00\uc5d0\uac8c\ub294 \uaf2d \ubbf8\uc220\uad00\uc5d0 \uc788\uc5b4\uc57c \ud560 \uadf8\ub9bc\uc774\uc5c8\ub358 \uc148\uc774\ub2e4. \ucee4\uc0db\uc740 \uba3c\uc800 \uce5c\uad6c\uc778 \ud558\ube0c\ub9c8\uc774\uc5b4 \ubd80\ubd80\uac00 \ud654\ub791\uc758 \uc791\ud488 \uad6c\uc785\uc744 \uc9c0\uc6d0\ud558\ub3c4\ub85d \uc124\ub4dd\ud588\ub2e4. \uc774\ud6c4 \ubbf8\uad6d \ubbf8\uc220\uad00\ub4e4\uc774 \uad00\uc2ec\uc744 \uac16\ub3c4\ub85d \uc6c0\uc9c1\uc600\ub2e4. \uc791\ud488\uc758 \ub2e4\uc74c \uc8fc\uc18c\ub97c \ucc3e\ub294 \uc77c\uc774 \ud55c \uc0ac\ub78c\uc758 \ubd80\ud0c1\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\uc558\ub358 \uac83\uc774\ub2e4. \ubbf8\uc220\uad00\uc758 \uae00\uc740 \ub274\uc695\uacfc \ud544\ub77c\ub378\ud53c\uc544, \ubcf4\uc2a4\ud134\uc5d0\uc11c \uac70\uc808\uc774 \uc774\uc5b4\uc84c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc624\ub298\uc758 \uba85\uc131\ub9cc \uc0dd\uac01\ud558\uba74 \ub180\ub78d\uc9c0\ub9cc, \uadf8\ub54c\uc758 \uae30\uad00\ub4e4\uc740 \uac01\uc790\uc758 \ud310\ub2e8\uc744 \ud588\ub2e4. \uc720\uba85\ud574\uc9c4 \ub4a4\uc758 \ud3c9\uac00\ub97c \uacfc\uac70\uc5d0 \uadf8\ub300\ub85c \uac00\uc838\uac00\uba74 \ubcf4\uc774\uc9c0 \uc54a\ub294 \ub300\ubaa9\uc774\ub2e4. \uae30\uad00\uc774 \ub2e4\ub8e8\ub294 \uc791\ud488\uc740 \uc5d8 \uadf8\ub808\ucf54\uc758 \u3008\uc131\ubaa8 \uc2b9\ucc9c\u3009\uc774\ub2e4. \uc885\uad50\uc801 \uc8fc\uc81c\ub97c \ub2f4\uc740 \uc624\ub798\ub41c \uadf8\ub9bc\uc774 \uc5ec\ub7ec \uc18c\uc720\uc790\ub97c \uac70\uccd0 \uadfc\ub300\uc758 \uc2dc\uc7a5\uacfc \ubbf8\uc220\uad00\uc744 \ub9cc\ub0ac\ub2e4. \uc9c0\uae08\uc758 \uc804\uc2dc\uc2e4\uc5d0\uc11c \ubcf4\ub294 \ud55c \uc7a5\uba74 \uc774\uc804\uc5d0, \uadf8\ub9bc\uc5d0\ub294 \ub2e4\uc74c \uc8fc\uc778\uc744 \ucc3e\uc73c\uba70 \ub3c4\uc2dc\ub97c \uc62e\uae34 \uc2dc\uac04\uc774 \uc788\uc5c8\ub2e4. \uc18c\uc7a5\ucc98\ub294 \uc791\ud488\uc758 \ucc98\uc74c\ubd80\ud130 \uace0\uc815\ub41c \uc8fc\uc18c\uac00 \uc544\ub2c8\uc5c8\ub2e4. 1904\ub144 \ub9c8\ub4dc\ub9ac\ub4dc\uc5d0\uc11c \ud310\ub9e4\uac00 \uc27d\uc9c0 \uc54a\uc558\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uc791\ud488\uc758 \uc218\uc900\uc744 \uc624\ub298 \ub300\uc2e0 \ud310\uc815\ud574 \uc8fc\uc9c0 \uc54a\ub294\ub2e4. \ub2f9\uc2dc\uc758 \ucde8\ud5a5\uacfc \ud3c9\uac00, \uad6c\uc785 \uc870\uac74\uc774 \uc11c\ub85c \uc791\uc6a9\ud588\uc744 \uc218 \uc788\ub2e4. \ubbf8\uc220\uad00\uc758 \uc124\uba85\uc740 \ud2b9\ud788 \uadf8 \ubb34\ub835 \uc5d8 \uadf8\ub808\ucf54\uc758 \uba85\uc131\uc774 \ub192\uc9c0 \uc54a\uc558\uc74c\uc744 \uac15\uc870\ud55c\ub2e4. \ud604\uc7ac\uc758 \uc720\uba85\ud568\uc744 \uacfc\uac70\uc758 \ubaa8\ub4e0 \uc0ac\ub78c\ub3c4 \ub2f9\uc5f0\ud788 \uc54c\uc558\uc744 \uac83\uc73c\ub85c \uc5ec\uae30\uc9c0 \uc54a\uc744 \ub54c \uc774\ub3d9\uc758 \uc774\uc57c\uae30\uac00 \ud765\ubbf8\ub85c\uc6cc\uc9c4\ub2e4. \ucee4\uc0db\uc740 \uc791\ud488\uc744 \uc88b\ub2e4\uace0 \ub9d0\ud558\ub294 \ub370\uc11c \uadf8\uce58\uc9c0 \uc54a\uc558\ub2e4. \ud558\ube0c\ub9c8\uc774\uc5b4 \ubd80\ubd80\uc758 \uc9c0\uc6d0\uc744 \ub04c\uc5b4\ub0b4\uace0 \ubbf8\uad6d\uc758 \uc5ec\ub7ec \uae30\uad00\uc774 \uad00\uc2ec\uc744 \uac16\ub3c4\ub85d \uc5f0\uacb0\ud588\ub2e4. \ubbf8\uc220\uad00\uc5d0 \uc88b\uc740 \uadf8\ub9bc\uc774 \ub4e4\uc5b4\uc624\ub294 \uacfc\uc815\uc5d0\ub294 \uac10\uc2dd\uc548\ub9cc\uc774 \uc544\ub2c8\ub77c \uc0ac\ub78c \uc0ac\uc774\uc758 \uc2e0\ub8b0\uc640 \uc2e4\uc81c \uad6c\uc785\uc744 \uac00\ub2a5\ud558\uac8c \ud558\ub294 \uc790\uae08\ub3c4 \ud544\uc694\ud588\ub2e4. \uc791\ud488\uc758 \uac00\uce58\ub97c \uc54c\uc544\ubcf4\ub294 \ud310\ub2e8\uacfc \uadf8 \ud310\ub2e8\uc744 \ud589\ub3d9\uc73c\ub85c \uc62e\uae30\ub294 \uc77c\uc740 \ub2e4\ub978 \ub2e8\uacc4\uc600\ub2e4. \uc774 \ub54c\ubb38\uc5d0 \uadf8\ub9bc\uc744 \ub458\ub7ec\uc2fc \uc0ac\ub78c\uc758 \uc774\ub984\ub3c4 \uc81c\uc791\uc790\uc758 \uc774\ub984 \uc606\uc5d0 \ub193\uc744 \uc218 \uc788\ub2e4. \ub204\uad6c\uc5d0\uac8c \ubcf4\uc5ec \uc8fc\uace0 \uc5b4\ub5bb\uac8c \uc124\ub4dd\ud588\ub294\uc9c0\uac00 \ub2e4\uc74c \uc18c\uc7a5\ucc98\uc5d0 \uc601\ud5a5\uc744 \uc8fc\uc5c8\uae30 \ub54c\ubb38\uc774\ub2e4. \ub2e4\ub9cc \ucee4\uc0db\uc774 \ubbf8\ub798\uc758 \uba85\uc131\uc744 \ubaa8\ub450 \uc815\ud655\ud788 \uc608\uacac\ud588\ub2e4\uace0 \uacfc\uc7a5\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub0a8\uc544 \uc788\ub294 \ud589\ub3d9\uc744 \ub530\ub77c\uac00\uba74 \ucda9\ubd84\ud558\ub2e4. \ub2e4\ub978 \uae30\uad00\ub4e4\uc774 \uac70\uc808\ud558\ub294 \ub3d9\uc548\uc5d0\ub3c4 \uc5f0\uacb0\uc744 \uc774\uc5b4 \uac14\ub2e4\ub294 \uc810\uc774 \uad6c\uccb4\uc801\uc778 \uc774\uc57c\uae30\ub2e4. \uc2dc\uce74\uace0\uc5d0\uc11c\uc758 \uad6c\uc785\ub3c4 \ud55c \ubc88\uc758 \uacb0\uc815\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\uc558\ub2e4. \ud544\uc694\ud55c \ub3c8\uc744 \ub9c8\ub828\ud558\ub294 \ub370 19\uac1c\uc6d4\uc774 \uac78\ub838\uace0, \uc774\uc0ac\ud68c \ub0b4\ubd80\uc5d0\ub3c4 \uc791\uac00\uc758 \ubbf8\uc220\uc0ac\uc801 \uc704\uce58\ub97c \uc758\uc2ec\ud558\ub294 \uc2dc\uc120\uc774 \uc788\uc5c8\ub2e4\uace0 \uae00\uc740 \uc804\ud55c\ub2e4. \ubbf8\uc220\uad00\uc774\ub77c\ub294 \uc774\ub984 \uc544\ub798\uc5d0 \ud558\ub098\uc758 \ub9c8\uc74c\ub9cc \uc788\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc88b\uc740 \uc791\ud488\uc774\ub77c\ub294 \ud3c9\uac00\ub97c \uacf5\uc720\ud558\uace0 \ube44\uc6a9\uc744 \uac10\uc218\ud560 \uc0ac\ub78c\uc744 \ubaa8\uc544\uc57c \ud588\ub2e4. \uc624\ub298 \ub300\ud45c \uc18c\uc7a5\ud488\uc774 \ub418\uc5c8\ub2e4\ub294 \uacb0\uacfc\ub97c \uc548 \ub4a4 \uc77d\uc73c\uba74 \uae30\ub2e4\ub9bc\uc740 \ub2f9\uc5f0\ud55c \uc808\ucc28\ucc98\ub7fc \ubcf4\uc77c \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \ub2f9\uc2dc\uc5d0\ub294 \uacb0\uad6d \uad6c\uc785\ud558\uac8c \ub420\uc9c0 \uc815\ud574\uc838 \uc788\uc9c0 \uc54a\uc558\uc744 \uac83\uc774\ub2e4. \uc774 \ubd88\ud655\uc2e4\uc131\uc744 \uae30\uc5b5\ud558\uba74 \uc791\ud488\uc744 \uc9c0\ucf1c\ub0b8 \ud55c \uc601\uc6c5\uc774\ub77c\ub294 \uc124\uba85\ubcf4\ub2e4 \uc5ec\ub7ec \ud310\ub2e8\uc774 \uc774\uc5b4\uc9c4 \uacfc\uc815\uc744 \ubcf4\uac8c \ub41c\ub2e4. \uc804\uc2dc\uc2e4\uc758 \uace0\uc694\ud55c \ubcbd \ub4a4\uc5d0\ub3c4 \ud1a0\ub860\uacfc \uc2dc\uac04\uc774 \uc788\uc5c8\ub2e4. \uae30\uad00 \uae00\uc740 \uc5b4\ub9b0 \ud5e4\ubc0d\uc6e8\uc774\uac00 \uc5b4\uba38\ub2c8\uc640 \ubbf8\uc220\uad00\uc5d0 \uc640 \uc774 \uadf8\ub9bc\uc744 \ubcf4\uc558\ub2e4\ub294 \uc77c\ud654\ub3c4 \uc18c\uac1c\ud55c\ub2e4. \uadf8\uac00 \ub098\uc911\uc5d0 \uc5d8 \uadf8\ub808\ucf54\uc758 \ub300\ub2f4\ud55c \ud45c\ud604\uacfc \uc790\uae30 \uae00\uc4f0\uae30\ub97c \uc5f0\uacb0\ud574 \ub9d0\ud588\ub2e4\ub294 \uc124\uba85\uc774\ub2e4. \uc774\ub294 \uadf8 \uae00\uc774 \uc804\ud558\ub294 \uc218\uc6a9\uc758 \uc77c\ud654\ub85c \uc77d\uc744 \uc218 \uc788\uc73c\uba70, \ubaa8\ub4e0 \uc791\ud488\uc758 \uc601\ud5a5\ub825\uc744 \uc22b\uc790\ub85c \uc99d\uba85\ud558\ub294 \uc790\ub8cc\ucc98\ub7fc \ub2e4\ub8e8\uc9c0\ub294 \uc54a\ub294\ub2e4. \uadf8\ub798\ub3c4 \uc791\ud488\uc758 \ub2e4\uc74c \uc2dc\uac04\uc774 \ubb34\uc5c7\uc778\uc9c0 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ubbf8\uc220\uad00\uc774 \uadf8\ub9bc\uc744 \uad6c\uc785\ud55c \ub4a4\uc5d0\ub294 \uc2e4\uc81c\ub85c \ucc3e\uc544\uc628 \uc0ac\ub78c\ub4e4\uc774 \uc790\uae30 \uacbd\ud5d8 \uc18d\uc5d0\uc11c \ub9cc\ub09c\ub2e4. \ub9cc\ub4e4\uc5b4\uc9c4 \uc2dc\ub300\uc758 \ub73b\uacfc \ud6c4\ub300 \uad00\ub78c\uc790\uac00 \uc5bb\uc740 \uc778\uc0c1\uc740 \uac19\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \ud55c \uadf8\ub9bc\uc758 \uc5ec\uc815\uc744 \ubcf8\ub2e4\ub294 \uac83\uc740 \uc2dc\uc7a5\uacfc \uae30\uad00\uc758 \uc774\ub3d9\ubfd0 \uc544\ub2c8\ub77c \ub2e4\ub978 \uc138\ub300\uc758 \uc2dc\uc120\uc73c\ub85c \ub4e4\uc5b4\uac00\ub294 \uae38\ub3c4 \ubcf4\ub294 \uc77c\uc774\ub2e4. \ub9c8\uce68\ub0b4 \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc774 \uad00\uc2ec\uc744 \ubcf4\uc600\uc9c0\ub9cc \uc790\uae08\uc744 \ubaa8\uc73c\ub294 \ub370\uc5d0\ub3c4 19\uac1c\uc6d4\uc774 \uac78\ub838\ub2e4\uace0 \ud55c\ub2e4. \uc791\ud488\uc740 \ub3c4\ucc29\ud55c \ub4a4 \ubbf8\uc220\uad00\uc744 \ub300\ud45c\ud558\ub294 \uadf8\ub9bc \uac00\uc6b4\ub370 \ud558\ub098\uac00 \ub418\uc5c8\ub2e4. \ud55c \uadf8\ub9bc\uc758 \uc790\ub9ac\ub97c \ub9cc\ub4e0 \uac83\uc740 \ud654\uac00\uc758 \uc190\uae38\ub9cc\uc774 \uc544\ub2c8\uc5c8\ub2e4. \ub2e4\ub978 \ud654\uac00\uc758 \uad00\uc2ec, \uce5c\uad6c\ub4e4\uc758 \uc9c0\uc6d0, \uae30\uad00\uc758 \uacb0\uc815\uacfc \uae30\ub2e4\ub9bc\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4. \uc804\uc2dc\uc7a5 \ubcbd\uc5d0 \uac78\ub9b0 \ud55c \uc810\uc744 \ubcfc \ub54c \uadf8 \ubcbd\uae4c\uc9c0 \uc624\ub294 \uae38\ub3c4 \uc788\uc5c8\ub2e4\ub294 \uac83\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \uc774\uc57c\uae30\ub2e4."}, {"id": "epictetus-what-is-up-to-us", "title": "\uc5d0\ud53d\ud14c\ud1a0\uc2a4 \u2014 \ub0b4\uac8c \ub2ec\ub9b0 \uc77c\uacfc \ub2ec\ub9ac\uc9c0 \uc54a\uc740 \uc77c", "summary": "\uacb0\uacfc\ub97c \ubaa8\ub450 \uc9c0\ubc30\ud558\ub824\ub294 \ub9c8\uc74c\uacfc \uc790\uc2e0\uc758 \ud310\ub2e8\uc744 \ub3cc\uc544\ubcf4\ub294 \ud0dc\ub3c4\ub97c \uace0\ub300 \ucca0\ud559\uc758 \ubb38\uc7a5\uc73c\ub85c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Philosophy", "url": "stories/epictetus-what-is-up-to-us/index.html", "image": "media/epictetus-what-is-up-to-us.png", "alt": "\ub3cc\uae30\ub465 \uadf8\ub298 \uc544\ub798\uc5d0\uc11c \uace0\ub300\uc758 \uc2a4\uc2b9\uacfc \uc131\uc778 \uc81c\uc790\uac00 \ubc14\ub78c\uc774 \ubd80\ub294 \ubc14\ub2e4\ub97c \uacc1\uc5d0 \ub450\uace0 \ub300\ud654\ud558\ub294 \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\uc5d0\ud53d\ud14c\ud1a0\uc2a4 \u2014 \ub0b4\uac8c \ub2ec\ub9b0 \uc77c\uacfc \ub2ec\ub9ac\uc9c0 \uc54a\uc740 \uc77c \uc5e5\ucf00\uc774\ub9ac\ub514\uc628\uc758 \uccab \uad6c\ubd84\uc744 \uc77c\uc0c1\uc5d0\uc11c \uc77d\uae30 \uacb0\uacfc\ub97c \ubaa8\ub450 \uc9c0\ubc30\ud558\ub824\ub294 \ub9c8\uc74c\uacfc \uc790\uc2e0\uc758 \ud310\ub2e8\uc744 \ub3cc\uc544\ubcf4\ub294 \ud0dc\ub3c4\ub97c \uace0\ub300 \ucca0\ud559\uc758 \ubb38\uc7a5\uc73c\ub85c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Philosophy \ubb38\ud654 \uc911\uc694\ud55c \ub2f5\uc7a5\uc744 \uae30\ub2e4\ub9b4 \ub54c \uc6b0\ub9ac\ub294 \ud654\uba74\uc744 \uba87 \ubc88\uc774\ub098 \ub2e4\uc2dc \ubcfc\uae4c. \ube68\ub9ac \ud655\uc778\ud55c\ub2e4\uace0 \uc0c1\ub300\uc758 \uacb0\uc815\uc774 \ub2ec\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\uc9c0\ub9cc \uae30\ub2e4\ub9ac\ub294 \ub9c8\uc74c\uc740 \uc790\uafb8 \uc190\uc744 \uc6c0\uc9c1\uc774\uac8c \ud55c\ub2e4. \uc5d0\ud53d\ud14c\ud1a0\uc2a4\uc758 \ucca0\ud559\uc740 \uc774\ub7f0 \uc21c\uac04\uc5d0 \uc9c8\ubb38 \ud558\ub098\ub97c \ub193\ub294\ub2e4. \uc9c0\uae08\uc758 \uc77c \uac00\uc6b4\ub370 \ubb34\uc5c7\uc774 \ub098\uc5d0\uac8c \ub2ec\ub824 \uc788\ub294\uac00. \u300e\uc5e5\ucf00\uc774\ub9ac\ub514\uc628\u300f\uc740 \uadf8\uc758 \uac00\ub974\uce68\uc744 \uc544\ub9ac\uc544\ub178\uc2a4\uac00 \uc815\ub9ac\ud55c \uc9e7\uc740 \uae38\uc7a1\uc774\ub2e4. \ud55c \uad6c\uc808\ub9cc \ub5bc\uba74 \ub9c8\uc74c\uc744 \ud3b8\ud558\uac8c \ud558\ub294 \uaca9\uc5b8\uc9d1\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc, \uc6d0\ubb38\uc740 \ud310\ub2e8\uacfc \uc695\ub9dd, \ud0c0\uc778\uacfc\uc758 \uad00\uacc4\ub97c \uc5b4\ub5bb\uac8c \ub2e4\ub8f0\uc9c0 \uc5f0\uc2b5\ud558\ub3c4\ub85d \uc694\uad6c\ud55c\ub2e4. \uac00\ubccd\uac8c \uc77d\ud788\uba74\uc11c\ub3c4 \uc27d\uac8c \ub05d\ub098\uc9c0\ub294 \uc54a\ub294 \ucc45\uc774\ub2e4. \ucc45\uc758 \uc2dc\uc791\uc740 \uc6b0\ub9ac\uc5d0\uac8c \ub2ec\ub9b0 \uac83\uacfc \uadf8\ub807\uc9c0 \uc54a\uc740 \uac83\uc744 \uad6c\ubd84\ud55c\ub2e4. \uc758\uacac\uacfc \uc758\ub3c4, \ubc14\ub78c\uacfc \ud68c\ud53c \uac19\uc740 \uc790\uc2e0\uc758 \ubc18\uc751\uc744 \ud55c\ucabd\uc5d0 \ub193\uace0, \uc7ac\uc0b0\uacfc \ud3c9\ud310, \uc9c0\uc704 \ub4f1\uc740 \ub2e4\ub978 \ucabd\uc5d0 \ub193\ub294\ub2e4. \ubab8\uc758 \uc0c1\ud0dc\ub3c4 \ubaa8\ub4e0 \uba74\uc5d0\uc11c \ub73b\ub300\ub85c \ud560 \uc218 \uc788\ub294 \uac83\uc73c\ub85c \ubcf4\uc9c0 \uc54a\ub294\ub2e4. \uc774 \uad6c\ubd84\uc744 \ub0b4\uac00 \uc544\ubb34 \uc601\ud5a5\ub3c4 \uc904 \uc218 \uc5c6\ub294 \uc77c\uacfc \ubb34\uc5c7\uc774\ub4e0 \uc644\uc804\ud788 \uc9c0\ubc30\ud560 \uc218 \uc788\ub294 \uc77c\uc774\ub77c\ub294 \ub2e8\uc21c\ud55c \ubaa9\ub85d\uc73c\ub85c \uc77d\uc9c0\ub294 \ub9d0\uc790. \uc6d0\ubb38\uc740 \ubc14\uae65\uc758 \uacb0\uacfc\uc5d0 \uc790\uae30 \uc790\uc720\ub97c \uc804\ubd80 \ub9e1\uae30\ub294 \ud0dc\ub3c4\ub97c \uacbd\uacc4\ud55c\ub2e4. \ud589\ub3d9\uc744 \uc120\ud0dd\ud560 \uc218 \uc788\ub2e4\ub294 \uac83\uacfc \uadf8 \ud589\ub3d9\uc758 \uacb0\uacfc\uac00 \ubc18\ub4dc\uc2dc \uc6d0\ud558\ub294 \ub300\ub85c \ub41c\ub2e4\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \ubc1c\ud45c\ub97c \uc900\ube44\ud558\ub294 \uc0ac\ub78c\uc744 \uc0dd\uac01\ud574 \ubcf4\uc790. \ub0b4\uc6a9\uc744 \ud655\uc778\ud558\uace0 \uc5f0\uc2b5\ud558\ub294 \uc77c\uc5d0\ub294 \uc790\uc2e0\uc774 \ud560 \uc218 \uc788\ub294 \ubaab\uc774 \uc788\ub2e4. \uadf8\ub7ec\ub098 \ubaa8\ub4e0 \uccad\uc911\uc758 \ud45c\uc815\uacfc \ud3c9\uac00\uae4c\uc9c0 \uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc88b\uc740 \uacb0\uacfc\ub97c \uc6d0\ud558\ub354\ub77c\ub3c4 \ub2e4\ub978 \uc0ac\ub78c\uc758 \ud310\ub2e8\uc744 \ub0b4 \ubb3c\uac74\ucc98\ub7fc \uc18c\uc720\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc774 \uc0ac\ub840\ub294 \uace0\ub300 \ucc45 \uc18d \uc7a5\uba74\uc744 \uadf8\ub300\ub85c \uc62e\uae34 \uac83\uc774 \uc544\ub2c8\ub77c \uad6c\ubd84\uc744 \ud604\uc7ac\uc758 \uc0dd\ud65c\uc5d0 \uc5f0\uacb0\ud55c \uc608\ub2e4. \uacb0\uacfc\ub97c \uc911\uc694\ud558\uac8c \uc5ec\uae30\uc9c0 \ub9d0\ub77c\ub294 \ub73b\ubcf4\ub2e4, \uc790\uc2e0\uc758 \uc900\ube44\uc640 \ud0c0\uc778\uc758 \ubc18\uc751\uc744 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ub2e4\ub8e8\uc9c0 \ub9d0\uc790\ub294 \uc0dd\uac01\uc73c\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \ub0b4\uac00 \ud560 \uc218 \uc788\ub294 \uc77c\uc744 \uc54c\uc544\uc57c \uadf8\ucabd\uc5d0 \ud798\uc744 \uc4f8 \uc218 \uc788\ub2e4. \ucc45\uc5d0\ub294 \uc0ac\ub78c\uc744 \ud754\ub4dc\ub294 \uac83\uc774 \uc0ac\ubb3c \uc790\uccb4\ubfd0 \uc544\ub2c8\ub77c \uadf8\uac83\uc744 \ubc14\ub77c\ubcf4\ub294 \ud310\ub2e8\uacfc \uad00\ub828\ub41c\ub2e4\ub294 \uac00\ub974\uce68\uc774 \ub098\uc628\ub2e4. \ub204\uad70\uac00 \ub2f5\uc7a5\uc744 \ub2a6\uac8c \ud558\uba74 \uc2e4\uc81c\ub85c \ud655\uc778\ud55c \uac83\uc740 \ub2f5\uc7a5\uc774 \uc544\uc9c1 \uc5c6\ub2e4\ub294 \uc0ac\uc2e4\uc774\ub2e4. \ub098\ub97c \ubb34\uc2dc\ud55c\ub2e4\ub294 \ud574\uc11d\uc740 \uadf8 \uc704\uc5d0 \ub354\ud55c \ud310\ub2e8\uc77c \uc218 \uc788\ub2e4. \ud574\uc11d\uc774 \uc5b8\uc81c\ub098 \ud2c0\ub9ac\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \ud655\uc778\ud55c \uc77c\uacfc \ucd94\uce21\ud55c \ub73b\uc744 \uc7a0\uae50 \ub098\ub204\uba74 \ub2e4\ub978 \uac00\ub2a5\uc131\uc744 \ubcfc \uc5ec\uc9c0\uac00 \uc0dd\uae34\ub2e4. \uc0c1\ub300\uac00 \ubc14\uc05c\uc9c0, \ub0b4\uc6a9\uc744 \uc54c\uc544\ubcf4\ub294 \uc911\uc778\uc9c0 \uc544\uc9c1 \ubaa8\ub97c \uc218 \uc788\ub2e4. \ucca0\ud559\uc758 \uad6c\ubd84\uc774 \uc77c\uc0c1\uc758 \ubb38\uc7a5 \ud558\ub098\ub97c \ucc9c\ucc9c\ud788 \uc77d\ub294 \uc77c\ub85c \uc774\uc5b4\uc9c0\ub294 \ub300\ubaa9\uc774\ub2e4. \uc5d0\ud53d\ud14c\ud1a0\uc2a4\uc758 \ubb38\uc7a5\uc5d0\ub294 \uc624\ub298\uc758 \ub3c5\uc790\uc5d0\uac8c \ub9e4\uc6b0 \uc5c4\uaca9\ud558\uac8c \ub4e4\ub9ac\ub294 \ubd80\ubd84\ub3c4 \uc788\ub2e4. \uc0c1\uc2e4\uacfc \uc9c8\ubcd1 \uc55e\uc5d0\uc11c \uc790\uc2e0\uc758 \ud310\ub2e8\uc744 \ub2e4\ub8e8\ub77c\ub294 \ub9d0\uc774 \uace7 \uace0\ud1b5\uc740 \ub2f9\uc0ac\uc790\uc758 \uc798\ubabb\uc774\ub77c\ub294 \ub73b\uc774 \ub418\uc5b4\uc11c\ub294 \uace4\ub780\ud558\ub2e4. \uc678\ubd80\uc758 \ud53c\ud574\uc640 \uc0ac\ud68c\uc801 \uc870\uac74\uc740 \uc2e4\uc81c\ub85c \uc0ac\ub78c\uc744 \ub2e4\uce58\uac8c \ud55c\ub2e4. \ub530\ub77c\uc11c \uc774 \uae00\uc5d0\uc11c\ub294 \uace0\ub300\uc758 \uac00\ub974\uce68\uc744 \ud604\ub300\uc758 \uce58\ub8cc\ub098 \uc2ec\ub9ac \uc0c1\ub2f4\uc744 \ub300\uc2e0\ud558\ub294 \ucc98\ubc29\uc73c\ub85c \uc81c\uc2dc\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc790\uc2e0\uc774 \ub367\ubd99\uc778 \ud574\uc11d\uc744 \uc0b4\ud53c\ub294 \uc77c\uc740 \ub3c4\uc6c0\uc774 \ub420 \uc218 \uc788\uc9c0\ub9cc \ud544\uc694\ud55c \ubcf4\ud638\uc640 \uc9c0\uc6d0, \uce58\ub8cc\ub97c \ubc1b\ub294 \uc77c\uacfc \uacbd\uc7c1\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ucca0\ud559\uc744 \uc77d\ub294 \uc77c\uc5d0\ub3c4 \uc801\uc6a9\ud560 \ubc94\uc704\ub97c \uc0dd\uac01\ud558\ub294 \ud310\ub2e8\uc774 \ud544\uc694\ud558\ub2e4. \uce6d\ucc2c\uc744 \ubc1b\ub294 \uac83\uc744 \uc720\uc77c\ud55c \uc131\uacf5\uc758 \uae30\uc900\uc73c\ub85c \uc0bc\uc73c\uba74 \uadf8 \uae30\uc900\uc758 \uc5f4\uc1e0\ub97c \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ub9e1\uae30\uac8c \ub41c\ub2e4. \uc6d0\ubb38\uc740 \uc774\ub807\uac8c \ud1b5\uc81c\ud558\uae30 \uc5b4\ub824\uc6b4 \ub300\uc0c1\uc744 \ubc18\ub4dc\uc2dc \uc5bb\uc5b4\uc57c \ud560 \uac83\uc73c\ub85c \ub9cc\ub4e4 \ub54c \uc0dd\uae30\ub294 \ud754\ub4e4\ub9bc\uc744 \uc9da\ub294\ub2e4. \ubc14\ub77c\ub294 \ub300\uc0c1\uc758 \uc131\uaca9\uc744 \uc0b4\ud3b4\ubcf4\ub77c\ub294 \uc694\uad6c\ub2e4. \uc6b0\ub9ac\ub294 \ud0c0\uc778\uc758 \uc778\uc815\uc744 \uc804\ud600 \uc6d0\ud558\uc9c0 \uc54a\ub294 \uc0ac\ub78c\uc774 \ub420 \ud544\uc694\uae4c\uc9c0\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \uc5b4\ub5a4 \ub0a0\uc758 \ubc18\uc751 \ud558\ub098\uac00 \uc790\uae30 \uc0b6 \uc804\uccb4\uc758 \uac00\uce58\ub97c \uacb0\uc815\ud558\ub3c4\ub85d \ub193\uace0 \uc788\uc9c0\ub294 \uc54a\uc740\uc9c0 \ubb3c\uc744 \uc218 \uc788\ub2e4. \ud070 \uc695\ub9dd\uc744 \uc5c6\uc560\uaca0\ub2e4\ub294 \uc120\uc5b8\ubcf4\ub2e4 \ubb34\uc5c7\uc744 \ub098\uc758 \uae30\uc900\uc73c\ub85c \uc0bc\ub294\uc9c0 \uad6c\uccb4\uc801\uc73c\ub85c \ud655\uc778\ud558\ub294 \ud3b8\uc774 \uac00\uae4c\uc6b4 \ucd9c\ubc1c\uc810\uc774\ub2e4. \uc774 \ucc45\uc740 \uac1c\uc778\uc758 \ub9c8\uc74c\ub9cc \uc774\uc57c\uae30\ud558\uc9c0 \uc54a\ub294\ub2e4. \uac00\uc871\uacfc \uc774\uc6c3\uc744 \ub300\ud558\ub294 \uc5ed\ud560\uacfc \ud0dc\ub3c4\ub3c4 \ub2e4\ub8ec\ub2e4. \ubc14\uae65\uc77c\uc744 \ubaa8\ub450 \ub0b4\uac8c \ub2ec\ub9ac\uc9c0 \uc54a\uc740 \uac83\uc73c\ub85c \ubd84\ub958\ud558\uace0 \uc544\ubb34 \ucc45\uc784\ub3c4 \uc9c0\uc9c0 \uc54a\ub294\ub2e4\uba74 \uad00\uacc4 \uc18d \ud589\ub3d9\uc744 \ub3cc\uc544\ubcf4\ub77c\ub294 \uc694\uad6c\uac00 \uc0ac\ub77c\uc838 \ubc84\ub9b0\ub2e4. \uc0c1\ub300\uc758 \ubc18\uc751\uc744 \uac15\uc81c\ub85c \uc815\ud560 \uc218 \uc5c6\ub2e4\ub294 \uc810\uacfc \ub0b4\uac00 \uc5b4\ub5a4 \ub9d0\uc744 \ud558\uace0 \uc5b4\ub5a4 \uc57d\uc18d\uc744 \uc9c0\ud0ac\uc9c0\ub294 \uad6c\ubd84\ud560 \uc218 \uc788\ub2e4. \ubaa8\ub4e0 \uacb0\uacfc\ub97c \uc7a5\uc545\ud558\uc9c0 \ubabb\ud574\ub3c4 \ud589\ub3d9\uc758 \ucc45\uc784\uc740 \ub0a8\ub294\ub2e4. \uace0\uc694\ud55c \ub9c8\uc74c\uc744 \uac16\ub294 \uc77c\uacfc \ud0c0\uc778\uc758 \uc5b4\ub824\uc6c0\uc744 \uc678\uba74\ud558\ub294 \uc77c\uc744 \uac19\uc740 \uac83\uc73c\ub85c \ub9cc\ub4e4\uc9c0 \uc54a\ub294 \uc77d\uae30\uac00 \ud544\uc694\ud558\ub2e4. \u300e\uc5e5\ucf00\uc774\ub9ac\ub514\uc628\u300f\uc740 \uc9e7\uc740 \ud56d\ubaa9\uc774 \uc774\uc5b4\uc838 \ube68\ub9ac \uc77d\uc744 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \ubb38\uc7a5\uc744 \ub9ce\uc774 \uc678\uc6b0\ub294 \uac83\uacfc \uc2e4\uc81c \uc0c1\ud669\uc5d0\uc11c \uad6c\ubcc4\ud558\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \uc5b4\ub5a4 \uc0ac\uac74\uc744 \ub5a0\uc62c\ub9ac\uace0 \uc0ac\uc2e4\uacfc \ud574\uc11d, \uc120\ud0dd\uacfc \uacb0\uacfc\ub97c \ub530\ub85c \uc801\uc5b4 \ubcf4\uba74 \ud55c \ud56d\ubaa9\uc5d0\uc11c\ub3c4 \uc624\ub798 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uc11c\ub85c \ubaa8\uc21c\ub418\ub294 \ub4ef\ud55c \uac10\uc815\uc774 \uc788\ub2e4\uace0 \uace7 \uc2e4\ud328\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \ubd88\uc548\uc774 \uc0dd\uae34 \uc21c\uac04 \uadf8\uac83\uc744 \uc54c\uc544\ucc28\ub9ac\uace0 \ub2e4\uc2dc \ud310\ub2e8\ud560 \uc5ec\uc9c0\ub3c4 \uc788\ub2e4. \uc774 \ud574\uc11d\uc740 \ub9c8\uc74c\uc774 \uc5b8\uc81c\ub098 \uc644\uc804\ud788 \uba85\ub839\uc744 \ub530\ub978\ub2e4\ub294 \uc8fc\uc7a5\ubcf4\ub2e4, \uc790\uae30 \ubc18\uc751\uc744 \ub3cc\uc544\ubcf4\ub294 \uc5f0\uc2b5\uc5d0 \ucd08\uc810\uc744 \ub9de\ucd98\ub2e4. \uc26c\uc6b4 \ud45c\uc5b4\ub97c \ub9cc\ub4dc\ub294 \ub300\uc2e0 \uc5b4\ub824\uc6b4 \uc21c\uac04\uc5d0 \uc0ac\uc6a9\ud560 \uc9c8\ubb38\uc744 \ub0a8\uae30\ub294 \uc148\uc774\ub2e4. \uae30\ub2e4\ub9ac\ub358 \ub2f5\uc740 \uc5ec\uc804\ud788 \uc624\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \uadf8\ub798\ub3c4 \ud544\uc694\ud55c \ub0b4\uc6a9\uc744 \ub354 \ud655\uc778\ud558\uac70\ub098, \ud574\uc57c \ud560 \ub2e4\ub978 \uc77c\uc744 \uc2dc\uc791\ud558\uac70\ub098, \uc801\uc808\ud55c \ub54c \ub2e4\uc2dc \ubb38\uc758\ud560 \uc218\ub294 \uc788\ub2e4. \uacb0\uacfc\ub97c \ubaa8\ub450 \uc18c\uc720\ud558\uc9c0 \uc54a\uc544\ub3c4 \ud589\ub3d9\ud560 \uc790\ub9ac\ub294 \ub0a8\ub294\ub2e4. \uccab \ubb38\uc7a5\uc758 \uad6c\ubd84\uc740 \uadf8 \uc790\ub9ac\ub97c \ucc3e\uac8c \ud55c\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\uc740 \uace0\ub300\uc758 \uc2a4\uc2b9\uacfc \uc81c\uc790\uac00 \ub300\ud654\ud558\ub294 \ubd84\uc704\uae30\ub97c \uc0c1\uc0c1\ud55c AI \uc0bd\ud654\ub2e4. \uc5d0\ud53d\ud14c\ud1a0\uc2a4\uc758 \uc2e4\uc81c \uc5bc\uad74\uc774\ub098 \uae30\ub85d\ub41c \ud55c \uc7a5\uba74\uc744 \ubcf5\uc6d0\ud55c \uac83\uc774 \uc544\ub2c8\ub2e4. \ubc14\uae65\uc758 \ubc14\ub78c\uc744 \uba48\ucd94\ub294 \ub300\uc2e0 \uc9c0\uae08\uc758 \ud310\ub2e8\uc744 \uc0b4\ud3b4\ubcf8\ub2e4\ub294 \uc0dd\uac01\uc744 \ud3b8\ud558\uac8c \ub5a0\uc62c\ub9ac\ub294 \uc785\uad6c\ub85c \ubcf4\uc544\ub3c4 \uc88b\ub2e4."}, {"id": "fragonard-music-lesson", "title": "\uc74c\uc545 \uc218\uc5c5 \u2014 \uc545\ubcf4\ubcf4\ub2e4 \uc11c\ub85c\uc758 \uc5bc\uad74\uc774 \uac00\uae4c\uc6b4 \uc2dc\uac04", "summary": "\uc74c\uc545\uc744 \uac00\ub974\uce58\ub294 \uc7a5\uba74\uacfc \uc778\ubb3c \uc0ac\uc774\uc758 \uce5c\ubc00\ud568\uc774 \uacb9\uce58\ub294 \uadf8\ub9bc\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Art", "url": "stories/fragonard-music-lesson/index.html", "image": "media/fragonard-music-lesson.jpg", "alt": "\ud504\ub77c\uace0\ub098\ub974\uc758 \uc74c\uc545 \uc218\uc5c5. \uac74\ubc18\uc545\uae30 \uc55e\uc758 \uc5ec\uc131\uacfc \uc545\ubcf4\ub97c \ub4e0 \ub0a8\uc131, \uc758\uc790 \uc704\uc758 \uace0\uc591\uc774\uc640 \ud604\uc545\uae30\uac00 \ubcf4\uc785\ub2c8\ub2e4.", "text": "\uc74c\uc545 \uc218\uc5c5 \u2014 \uc545\ubcf4\ubcf4\ub2e4 \uc11c\ub85c\uc758 \uc5bc\uad74\uc774 \uac00\uae4c\uc6b4 \uc2dc\uac04 \ud504\ub77c\uace0\ub098\ub974\uc758 \uc2e4\ub0b4\uc5d0\uc11c \uac74\ubc18\uacfc \uc2dc\uc120, \uc791\uc740 \uace0\uc591\uc774\ub97c \ucc3e\uc544\ubcf4\uae30 \uc74c\uc545\uc744 \uac00\ub974\uce58\ub294 \uc7a5\uba74\uacfc \uc778\ubb3c \uc0ac\uc774\uc758 \uce5c\ubc00\ud568\uc774 \uacb9\uce58\ub294 \uadf8\ub9bc\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Art \ubb38\ud654 \uc545\ubcf4\uac00 \ud3bc\uccd0\uc838 \uc788\uace0 \ud55c \uc0ac\ub78c\uc774 \uac74\ubc18 \uc55e\uc5d0 \uc549\uc544 \uc788\ub2e4. \ub2e4\ub978 \uc0ac\ub78c\uc740 \uc545\ubcf4\ub97c \ub4e4\uace0 \uac00\uae4c\uc774 \ubab8\uc744 \uae30\uc6b8\uc778\ub2e4. \uc81c\ubaa9\uc740 \uc74c\uc545 \uc218\uc5c5\uc778\ub370 \uadf8\ub9bc\uc744 \ubcfc\uc218\ub85d \ub450 \uc0ac\ub78c\uc758 \uc2dc\uc120\uc5d0\ub3c4 \uad00\uc2ec\uc774 \uac04\ub2e4. \ubb34\uc2a8 \uace1\uc744 \ubc30\uc6b0\ub294\uc9c0\ubcf4\ub2e4 \uc5b4\ub5a4 \uad00\uacc4\uc758 \uc2dc\uac04\uc774 \ud750\ub974\ub294\uc9c0\uac00 \uba3c\uc800 \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \ud504\ub77c\uace0\ub098\ub974\uc758 \u3008\uc74c\uc545 \uc218\uc5c5\u3009\uc774\ub2e4. \uc18c\ub9ac\ub97c \uc9c1\uc811 \ub4e4\uc744 \uc218 \uc5c6\ub294 \uadf8\ub9bc\uc774 \uc74c\uc545\uc744 \uc5b4\ub5a4 \ubc29\uc2dd\uc73c\ub85c \ubcf4\uc5ec \uc8fc\ub294\uc9c0, \ub610 \uc77c\uc0c1\uc758 \ud55c \uc7a5\uba74\uc744 \uc5b4\ub5bb\uac8c \uce5c\ubc00\ud55c \uacf5\uac04\uc73c\ub85c \ub9cc\ub4dc\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uc55e\ucabd \uc758\uc790\uc5d0\ub294 \ub73b\ubc16\uc758 \uc791\uc740 \uad6c\uacbd\uafbc\ub3c4 \uc788\ub2e4. \uadf8\ub9bc \uac00\uc6b4\ub370\uc5d0\ub294 \uac74\ubc18\uc545\uae30\uac00 \uc788\uace0 \uadf8 \uc55e\uc5d0 \uc5ec\uc131\uc774 \uc549\uc544 \uc788\ub2e4. \ub0a8\uc131\uc740 \ud3bc\uccd0\uc9c4 \uc545\ubcf4 \uac00\uae4c\uc774\uc5d0 \uc190\uc744 \ub454\ub2e4. \uc774 \ubb3c\uac74\ub4e4 \ub54c\ubb38\uc5d0 \uc81c\ubaa9\uc744 \uc77d\uae30 \uc804\uc5d0\ub3c4 \uc74c\uc545\uacfc \uad00\ub828\ub41c \uc2dc\uac04\uc784\uc744 \uc54c\uc544\ubcfc \uc218 \uc788\ub2e4. \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc18c\ub9ac\uac00 \ub208\uc5d0 \ubcf4\uc774\ub294 \ub3c4\uad6c\ub85c \ud45c\ud604\ub418\ub294 \uc148\uc774\ub2e4. \uc9c0\uae08 \uc6b0\ub9ac\uac00 \uc775\uc219\ud55c \ud604\ub300 \ud53c\uc544\ub178\uc640 \uc18c\ub9ac\uac00 \ub611\uac19\uc558\uc744 \uac83\uc774\ub77c\uace0 \uac00\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc6b0\uc120\uc740 \uac74\ubc18\uc744 \ub2e4\ub8e8\ub294 \uc0ac\ub78c\uacfc \uc545\ubcf4\ub97c \ud568\uaed8 \ubcf4\ub294 \uc0ac\ub78c\uc774 \uc5b4\ub5a4 \uac70\ub9ac\ub97c \uc774\ub8e8\ub294\uc9c0 \ubcf4\uc790. \uc545\uae30\uc758 \uc815\ud655\ud55c \uad6c\uc870\ub97c \ubaa8\ub450 \uc54c\uc544\uc57c \uc7a5\uba74\uc5d0 \ub4e4\uc5b4\uac08 \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub0a8\uc131\uc758 \ud55c \uc190\uc740 \uc545\ubcf4 \ucabd\uc5d0 \uc788\uace0 \ub2e4\ub978 \uc190\uc740 \uc5ec\uc131\uc758 \uc758\uc790 \ub4a4 \uac00\uae4c\uc774\uc5d0 \ub193\uc5ec \uc788\ub2e4. \uc545\ubcf4\ub97c \ub3c4\uc640\uc8fc\ub294 \ud589\ub3d9\uacfc \uc778\ubb3c \uacc1\uc5d0 \uba38\ubb34\ub294 \uc790\uc138\uac00 \ub3d9\uc2dc\uc5d0 \ubcf4\uc778\ub2e4. \ud558\ub098\uc758 \ubab8 \uc548\uc5d0\uc11c \uc74c\uc545\uacfc \uad00\uacc4\uac00 \ud568\uaed8 \ud45c\ud604\ub41c\ub2e4. \uc774\ub97c \uace7\ubc14\ub85c \ud2b9\uc815\ud55c \uc5f0\uc560 \uc0ac\uac74\uc758 \uc99d\uac70\ub77c\uace0 \ub2e8\uc815\ud558\uc9c0\ub294 \ub9d0\uc790. \uadf8\ub9bc\uc774 \ubcf4\uc5ec \uc8fc\ub294 \uac83\uc740 \ubab8\uc758 \uac70\ub9ac\uc640 \uc190\uc758 \uc704\uce58\ub2e4. \uad50\uc0ac\uc640 \ud559\uc0dd\uc774\ub77c\ub294 \uae30\ub2a5\ub9cc\uc73c\ub85c \uc7a5\uba74\uc774 \ub05d\ub098\ub294\uc9c0, \uadf8\ubcf4\ub2e4 \uac00\uae4c\uc6b4 \ubd84\uc704\uae30\ub3c4 \ub290\uaef4\uc9c0\ub294\uc9c0 \uad00\uac1d\uc774 \uc0b4\ud3b4\ubcfc \uc5ec\uc9c0\uac00 \uc0dd\uae34\ub2e4. \uc545\ubcf4\ub97c \ubcf4\uace0 \uc5bc\uad74\ub85c \ub208\uc744 \uc62e\uae30\uba74 \ub450 \uc0ac\ub78c\uc774 \uc11c\ub85c\ub97c \uc5b4\ub5bb\uac8c \ud5a5\ud558\ub294\uc9c0 \uad00\uc2ec\uc774 \uac04\ub2e4. \uc77d\uc5b4\uc57c \ud560 \uc885\uc774\uc640 \uac00\uae4c\uc774 \uc788\ub294 \uc5bc\uad74\uc774 \ud55c \ud654\uba74 \uc548\uc5d0\uc11c \uacbd\uc7c1\ud558\ub294 \uac83\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218\ub3c4 \uc788\ub2e4. \uc74c\uc545 \uc218\uc5c5\uc774\ub77c\ub294 \uc81c\ubaa9\uc5d0 \uc791\uc740 \uc6c3\uc74c\uc774 \ub354\ud574\uc9c0\ub294 \uc9c0\uc810\uc774\ub2e4. \uadf8\ub807\ub2e4\uace0 \ub450 \uc0ac\ub78c\uc758 \ub300\uc0ac\ub97c \uc6b0\ub9ac\uac00 \uc2e4\uc81c\ub85c \ub4e4\uc740 \uac83\ucc98\ub7fc \uc368 \ub123\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \ud45c\uc815\uacfc \ubc29\ud5a5\uc744 \ubcf4\uba70 \uac00\ub2a5\uc131\uc744 \ub290\ub07c\ub294 \uac83\uacfc \uc228\uc740 \uc0ac\uc5f0\uc744 \ud655\uc815\ud558\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \ud68c\ud654\ub294 \ub9d0\uc774 \uc5c6\uae30 \ub54c\ubb38\uc5d0 \uad00\uacc4\uc758 \ud574\uc11d\uc744 \uc5ec\uc720 \uc788\uac8c \ub0a8\uaca8 \ub458 \uc218 \uc788\ub2e4. \uc55e\ucabd \uc758\uc790\uc5d0\ub294 \uace0\uc591\uc774\uac00 \ubcf4\uc778\ub2e4. \uc74c\uc545\uc744 \uc5f0\uc8fc\ud558\uac70\ub098 \uc545\ubcf4\ub97c \uc77d\ub294 \uc8fc\uc778\uacf5\uc740 \uc544\ub2c8\uc9c0\ub9cc, \uc774 \ubc29\uc774 \uc0ac\ub78c\ub4e4\uc758 \uc77c\uc0c1\uc774 \uc788\ub294 \uacf5\uac04\ucc98\ub7fc \ub290\uaef4\uc9c0\uac8c \ud55c\ub2e4. \ud070 \uc8fc\uc81c\ub9cc \ucc3e\uc73c\ub824 \ubcf4\uba74 \ub193\uce58\uae30 \uc26c\uc6b4 \uc791\uc740 \uc874\uc7ac\ub2e4. \uace0\uc591\uc774\ub97c \ubc1c\uacac\ud588\ub2e4\uace0 \uc989\uc2dc \uc5b4\ub5a4 \uace0\uc815\ub41c \uc0c1\uc9d5\uc73c\ub85c \ubc88\uc5ed\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uba3c\uc800 \ub450 \uc0ac\ub78c\uacfc \uc5bc\ub9c8\ub098 \uac00\uae4c\uc774 \uc788\uc73c\uba70 \uc5b4\ub5a4 \ubb3c\uac74 \uacc1\uc5d0 \uc788\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \ubc29 \uc548\uc758 \uc791\uc740 \uc0dd\uba85\uc774 \uc7a5\uba74\uc758 \ub531\ub531\ud568\uc744 \ub35c\uc5b4 \uc8fc\ub294 \ub4ef\ud55c \uac10\uc0c1\uc744 \uac00\uc9c8 \uc218 \uc788\ub2e4. \uc81c\ubaa9 \ubc14\uae65\uc758 \uc138\ubd80\uac00 \uadf8\ub9bc\uc744 \ub354 \uc624\ub798 \ubcf4\uac8c \ud55c\ub2e4. \uc758\uc790 \uc704\uc640 \uc8fc\ubcc0\uc5d0\ub294 \ud604\uc545\uae30\uc640 \uc545\ubcf4 \uac19\uc740 \ubb3c\uac74\uc774 \ub193\uc5ec \uc788\ub2e4. \ubab8\uc758 \ubc29\ud5a5\uacfc \ubb3c\uac74\uc758 \ube44\uc2a4\ub4ec\ud55c \uc120\uc774 \uc11c\ub85c \uc774\uc5b4\uc9c0\uba70 \ud654\uba74\uc758 \uc6c0\uc9c1\uc784\uc744 \ub9cc\ub4e0\ub2e4. \uc778\ubb3c \ub458\ub9cc \uc798\ub77c \ubcf4\uba74 \uc774 \ub9ac\ub4ec\uc758 \uc77c\ubd80\uac00 \uc0ac\ub77c\uc9c4\ub2e4. \uc61b \ub3c4\ub85d\uc758 \uc545\uae30 \uc774\ub984\uc744 \uadf8\ub300\ub85c \ubaa8\ub4e0 \uc138\ubd80\uc758 \ud655\uc815 \ub2f5\uc73c\ub85c \uc0bc\uae30\ubcf4\ub2e4, \uc9c0\uae08 \ub3c4\ud310\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\ub294 \ud615\uc0c1\uacfc \ubc30\uce58\ubd80\ud130 \ubcf4\uc558\ub2e4. \uc0dd\ud65c\uc758 \ubb3c\uac74\uc774 \uc5b4\ub5a4 \uc120\uacfc \uba74\uc744 \ub9cc\ub4dc\ub294\uc9c0 \uc0b4\ud53c\ub294 \uc77c\ub3c4 \uac10\uc0c1\uc758 \uc77c\ubd80\ub2e4. \uc7a5\uc2dd\uc740 \ub54c\ub85c \uc778\ubb3c\uacfc \uac19\uc740 \uc815\ub3c4\ub85c \ud654\uba74\uc758 \uad00\uacc4\ub97c \ub9cc\ub4e0\ub2e4. \ud770 \uc637\uacfc \ub530\ub73b\ud55c \uc0c9\uc758 \uc545\uae30, \ud750\ub974\ub294 \ucc9c\uc758 \ubaa8\uc591\uc744 \ubc88\uac08\uc544 \ubcf4\uc790. \uc5bc\uad74\uacfc \uc190 \uc8fc\ubcc0\uc758 \ubc1d\uc740 \ubd80\ubd84\uc774 \uac00\uae4c\uc774 \ub2e4\uac00\uc624\uace0, \ub098\uba38\uc9c0 \uc2e4\ub0b4\ub294 \uc778\ubb3c\ub4e4\uc744 \ub458\ub7ec\uc2fc\ub2e4. \uc138\ubd80\ub97c \ub611\uac19\uc774 \uc120\uba85\ud558\uac8c \uc124\uba85\ud558\uc9c0 \uc54a\uc544\ub3c4 \uce5c\ubc00\ud55c \ubd84\uc704\uae30\uac00 \uc0dd\uae38 \uc218 \uc788\ub2e4. \uc774\ub7f0 \uc7a5\uba74\uc774 \ub2f9\uc2dc \ubaa8\ub4e0 \uc0ac\ub78c\uc758 \uc0dd\ud65c\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud2b9\uc815\ud55c \uc2e4\ub0b4\uc640 \uc5ec\uac00\uc758 \ubaa8\uc2b5\uc744 \ud654\uac00\uac00 \uace8\ub77c \uad6c\uc131\ud55c \uadf8\ub9bc\uc774\ub2e4. \ud3b8\uc548\ud558\uace0 \uc544\ub984\ub2e4\uc6b4 \uc778\uc0c1 \uc18d\uc5d0\ub3c4 \uc5b4\ub5a4 \uacf5\uac04\uc774 \uc608\uc220\uc758 \uc8fc\uc81c\uac00 \ub418\uc5c8\ub294\uc9c0 \uc0dd\uac01\ud560 \uc9c8\ubb38\uc774 \uc788\ub2e4. \ud48d\uacbd\uc744 \uc990\uae30\uba74\uc11c \uadf8 \uc870\uac74\ub3c4 \ud568\uaed8 \ubcfc \uc218 \uc788\ub2e4. \uc6b0\ub9ac\ub294 \uc545\uae30\ub97c \ubcf4\uba74 \uc5b4\ub5a4 \uc18c\ub9ac\uac00 \ub0a0\uc9c0 \ub5a0\uc62c\ub9b0\ub2e4. \uadf8\ub7ec\ub098 \uadf8\ub9bc\uc774 \ub4e4\ub824 \uc8fc\ub294 \uc2e4\uc81c \ub179\uc74c\uc740 \uc5c6\ub2e4. \uc9c0\uae08 \uc5b4\ub5a4 \uace1\uc744 \uc5f0\uc8fc\ud558\ub294\uc9c0 \ud655\uc815\ud558\uae30\ubcf4\ub2e4 \ud55c \uc0ac\ub78c\uc774 \ub4e3\uace0 \ub2e4\ub978 \uc0ac\ub78c\uc774 \uc5f0\uc8fc\ud558\ub294 \uad00\uacc4\ub97c \uc0c1\uc0c1\ud558\ub294 \ud3b8\uc774 \uc7a5\uba74\uc5d0 \uac00\uae4c\uc6b8 \uc218 \uc788\ub2e4. \ubc18\ub300\ub85c \uc7a0\uae50 \ubaa8\ub4e0 \uc18c\ub9ac\ub97c \ub044\uace0 \ub450 \uc0ac\ub78c\uc758 \uc790\uc138\ub9cc \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uc74c\uc545\uc774\ub77c\ub294 \uacf5\ub3d9\uc758 \ud65c\ub3d9\uc774 \uc5b4\ub5bb\uac8c \uac00\uae4c\uc6b4 \uac70\ub9ac\ub97c \ub9cc\ub4dc\ub294\uc9c0 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uc791\ud488\uc758 \uc81c\ubaa9\uacfc \uc2dc\uac01\uc801\uc778 \uc815\ubcf4\uac00 \uc11c\ub85c\ub97c \ub3d5\uc9c0\ub9cc \ud55c\ucabd\uc774 \ubaa8\ub4e0 \ud574\uc11d\uc744 \ub05d\ub0b4\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \uc61b \ub8e8\ube0c\ub974 \ub3c4\ub85d\uc5d0 \uc218\ub85d\ub41c \uc2e4\uc81c \ud68c\ud654\uc758 \uc0c9\ucc44 \uc7ac\ud604 \ub3c4\ud310\uc774\ub2e4. \ud604\ub300\uc778\uc774 \uc0c8\ub85c \ub9cc\ub4e0 \uc74c\uc545 \uc218\uc5c5 \uc0bd\ud654\uac00 \uc544\ub2c8\ub77c \ud504\ub77c\uace0\ub098\ub974\uc758 \ud654\uba74\uc744 \ubcf4\ub294 \uc790\ub8cc\ub2e4. \uc61b \uc778\uc1c4\uac00 \uc2e4\ubb3c\uc758 \ubaa8\ub4e0 \uc0c9\uacfc \uc9c8\uac10\uc744 \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\uc73c\ubbc0\ub85c \ud070 \uad6c\uc131\ubd80\ud130 \uc0b4\ud3b4\ubcf4\uc558\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc74c\uc545 \uc218\uc5c5\uc774\ub77c\ub294 \uc7a5\uba74\uc744 \ud655\uc778\ud558\uace0, \ub2e4\uc74c\uc5d0\ub294 \uc190\uacfc \uc5bc\uad74, \ub9c8\uc9c0\ub9c9\uc5d0\ub294 \uace0\uc591\uc774\uc640 \uc8fc\ubcc0 \ubb3c\uac74\uc744 \ucc3e\uc544\ubcf4\uc790. \uac19\uc740 \ubc29\uc774 \ubcfc \ub54c\ub9c8\ub2e4 \uc870\uae08 \ub2e4\ub978 \uc911\uc2ec\uc744 \ub0b4\uc5b4 \uc904 \uc218 \uc788\ub2e4. \ud2b9\ubcc4\ud55c \uc0ac\uac74\uc774 \uc5c6\ub294 \uadf8\ub9bc\ub3c4 \uc0ac\ub78c \uc0ac\uc774\uc758 \uac70\ub9ac\uc640 \uc791\uc740 \uc138\ubd80\ub97c \ud1b5\ud574 \ucda9\ubd84\ud788 \ud48d\ubd80\ud55c \uc77d\uc744\uac70\ub9ac\uac00 \ub41c\ub2e4."}, {"id": "frankenstein-creator-and-creature", "title": "\ud504\ub791\ucf04\uc288\ud0c0\uc778 \u2014 \ub9cc\ub4e4\uc5b4 \ub0b8 \uc0dd\uba85\uc5d0\uac8c\ub294 \ub204\uac00 \ucc45\uc784\uc9c8\uae4c", "summary": "\ube45\ud130\uc640 \ud53c\uc870\ubb3c\uc758 \uc904\uac70\ub9ac, \uc5ec\ub7ec \uacb9\uc758 \uc774\uc57c\uae30 \uad6c\uc870\ub97c \ud1b5\ud574 \ucc3d\uc870\uc640 \ucc45\uc784\uc758 \ubb38\uc81c\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Literature", "url": "stories/frankenstein-creator-and-creature/index.html", "image": "media/frankenstein-creator-and-creature-scene-20261030.png", "alt": "\uc232\uc18d \uc740\uc2e0\ucc98\uc5d0\uc11c \ucc45 \uacc1\uc5d0 \ud640\ub85c \uc549\uc544 \uba40\ub9ac \ubd88\ube5b\uc774 \uc788\ub294 \uc624\ub450\ub9c9\uc744 \ubc14\ub77c\ubcf4\ub294 \ud53c\uc870\ubb3c\uc758 \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\ud504\ub791\ucf04\uc288\ud0c0\uc778 \u2014 \ub9cc\ub4e4\uc5b4 \ub0b8 \uc0dd\uba85\uc5d0\uac8c\ub294 \ub204\uac00 \ucc45\uc784\uc9c8\uae4c \uacfc\ud559\uc790\uc758 \uc774\ub984\uacfc \uc774\ub984 \uc5c6\ub294 \ud53c\uc870\ubb3c, \uc11c\ub85c\uc758 \uc774\uc57c\uae30\ub97c \ub4e3\ub294 \uc18c\uc124 \ube45\ud130\uc640 \ud53c\uc870\ubb3c\uc758 \uc904\uac70\ub9ac, \uc5ec\ub7ec \uacb9\uc758 \uc774\uc57c\uae30 \uad6c\uc870\ub97c \ud1b5\ud574 \ucc3d\uc870\uc640 \ucc45\uc784\uc758 \ubb38\uc81c\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Literature \ubb38\ud654 \u2018\ud504\ub791\ucf04\uc288\ud0c0\uc778\u2019\uc774\ub77c\uace0 \ud558\uba74 \ubcfc\ud2b8\uac00 \ubc15\ud78c \uba38\ub9ac\ub098 \ud070 \ubab8\uc9d1\uc758 \uad34\ubb3c\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \uc6d0\uc791\uc5d0\uc11c \ud504\ub791\ucf04\uc288\ud0c0\uc778\uc740 \uc0dd\uba85\uc744 \ub9cc\ub4e4\uc5b4 \ub0b8 \ube45\ud130\uc758 \uc131\uc774\ub2e4. \ub9cc\ub4e4\uc5b4\uc9c4 \uc874\uc7ac\uc5d0\uac8c\ub294 \ubcc4\ub3c4\uc758 \uace0\uc720\ud55c \uc774\ub984\uc774 \ubd99\uc9c0 \uc54a\ub294\ub2e4. \uccab \uad6c\ubd84\uc744 \uc54c\uace0 \ub098\uba74 \uc81c\ubaa9\ubd80\ud130 \uc870\uae08 \ub2e4\ub974\uac8c \ub4e4\ub9b0\ub2e4. \uba54\ub9ac \uc178\ub9ac\uc758 \uc18c\uc124\uc740 1818\ub144\uc5d0 \ucc98\uc74c \ucd9c\uac04\ub418\uc5c8\ub2e4. \ub110\ub9ac \uc77d\ud788\ub294 1831\ub144 \ud310\ubcf8\uacfc\ub3c4 \uad6c\ubcc4\ud560 \ud544\uc694\uac00 \uc788\ub2e4. \uc5ec\uae30\uc11c\ub294 \ub300\uc870\ud55c \uc6d0\ubb38\uc758 \uc8fc\uc694 \uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc744 \ud3ec\ud568\ud574, \uad34\ubb3c\uc774 \ub204\uad6c\ub0d0\ub294 \uc9c8\ubb38\ubcf4\ub2e4 \ub204\uac00 \uc5b4\ub5a4 \ucc45\uc784\uc744 \uc9c0\ub294\uac00\ub77c\ub294 \uc9c8\ubb38\uc73c\ub85c \ub4e4\uc5b4\uac00 \ubcf8\ub2e4. \uc18c\uc124\uc740 \uacfc\ud559\uc790\uc758 \uc2e4\ud5d8\uc2e4\uc774 \uc544\ub2c8\ub77c \ud0d0\ud5d8\uac00 \ub85c\ubc84\ud2b8 \uc6d4\ud134\uc774 \ub204\uc774\uc5d0\uac8c \ubcf4\ub0b4\ub294 \ud3b8\uc9c0\ub85c \uc2dc\uc791\ud55c\ub2e4. \ubd81\ucabd\uc744 \ud5a5\ud558\ub358 \uc6d4\ud134\uc740 \uc5bc\uc74c \uc18d\uc5d0\uc11c \uae30\uc9c4\ub9e5\uc9c4\ud55c \ube45\ud130\ub97c \ub9cc\ub09c\ub2e4. \ube45\ud130\uac00 \uc790\uc2e0\uc758 \uc774\uc57c\uae30\ub97c \ub4e4\ub824\uc8fc\uace0, \uc6d4\ud134\uc740 \uadf8\uac83\uc744 \ud3b8\uc9c0\uc5d0 \uc62e\uae34\ub2e4. \ub3c5\uc790\ub294 \uc0ac\uac74\uc744 \ubc14\ub85c \ub208\uc55e\uc5d0\uc11c \ubcf4\ub294 \ub300\uc2e0 \ub204\uad70\uac00\uc758 \ub9d0\uc744 \ud1b5\ud574 \ub4e3\ub294\ub2e4. \uadf8 \uc548\uc5d0\ub294 \ud53c\uc870\ubb3c\uc774 \ube45\ud130\uc5d0\uac8c \ub4e4\ub824\uc8fc\ub294 \ud68c\uc0c1\ub3c4 \ub4e4\uc5b4 \uc788\ub2e4. \ubc14\uae65\uc758 \uc6d4\ud134, \uc548\ucabd\uc758 \ube45\ud130, \ub354 \uc548\ucabd\uc758 \ud53c\uc870\ubb3c\uc774\ub77c\ub294 \uc5ec\ub7ec \uacb9\uc744 \uae30\uc5b5\ud558\uba74 \uc65c \uc11c\ub85c\uc758 \ub9d0\uc744 \ube44\uad50\ud574\uc57c \ud558\ub294\uc9c0 \ubcf4\uc778\ub2e4. \uc81c\ub124\ubc14\uc5d0\uc11c \uc790\ub780 \ube45\ud130\ub294 \uc790\uc5f0\uc758 \ube44\ubc00\uacfc \uc0dd\uba85\uc758 \uc6d0\ub9ac\uc5d0 \ub9e4\ub8cc\ub41c\ub2e4. \ub300\ud559\uc774 \uc788\ub294 \uc789\uace8\uc288\ud0c0\ud2b8\uc5d0\uc11c \uc5f0\uad6c\uc5d0 \ubab0\ub450\ud558\uba70 \uc0b4\uc544 \uc788\ub294 \uc874\uc7ac\ub97c \ub9cc\ub4e4\uc5b4 \ub0bc \ubc29\ubc95\uc744 \ucc3e\ub294\ub2e4. \uac00\uc871\uacfc \uc77c\uc0c1\uc5d0\uc11c \uba40\uc5b4\uc9c4 \ucc44 \ubaa9\ud45c \ud558\ub098\ub97c \ud5a5\ud574 \ub098\uc544\uac00\ub294 \ubaa8\uc2b5\uc774\ub2e4. \uadf8\ub7ec\ub098 \ub9c8\uce68\ub0b4 \uc0dd\uba85\uc774 \uc6c0\uc9c1\uc774\ub294 \uc21c\uac04 \uadf8\ub294 \uc790\uc2e0\uc774 \ub9cc\ub4e0 \uc874\uc7ac\ub97c \ub450\ub824\uc6cc\ud558\uace0 \ud53c\ud55c\ub2e4. \uc624\ub7ab\ub3d9\uc548 \uc131\uacf5\ub9cc \uc0c1\uc0c1\ud588\uc9c0\ub9cc \uc131\uacf5 \ub4a4\uc758 \uad00\uacc4\ub294 \uc900\ube44\ud558\uc9c0 \ubabb\ud588\ub2e4. \uc18c\uc124\uc758 \ubb38\uc81c\ub294 \u2018\ub9cc\ub4e4 \uc218 \uc788\ub294\uac00\u2019\ub77c\ub294 \uc9c8\ubb38\uc774 \ud574\uacb0\ub418\ub294 \ubc14\ub85c \uadf8 \uc21c\uac04\ubd80\ud130 \ub354 \ucee4\uc9c4\ub2e4. \ud53c\uc870\ubb3c\uc740 \ucc98\uc74c\ubd80\ud130 \uc138\uc0c1\uc744 \ub2a5\uc219\ud558\uac8c \uc774\ud574\ud558\uc9c0 \ubabb\ud55c\ub2e4. \uac10\uac01\uacfc \ubc30\uace0\ud514, \ucd94\uc704\uc640 \ubd88\uc744 \uacbd\ud5d8\ud558\uba70 \uc0b4\uc544\uac08 \ubc29\ubc95\uc744 \ubc30\uc6b4\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \uadf8\uc758 \uc678\ubaa8\uc5d0 \ub180\ub77c \ub3c4\ub9dd\uce58\uac70\ub098 \uacf5\uaca9\ud55c\ub2e4. \uadf8\ub294 \uc778\uac04\uc758 \uc138\uacc4\ub97c \uc6d0\ud558\uc9c0\ub9cc \uadf8 \uc138\uacc4\ub85c \ub4e4\uc5b4\uac08 \ubb38\uc744 \ucc3e\uae30 \uc5b4\ub835\ub2e4. \ub4dc \ub77c\uc138 \uac00\uc871\uc758 \uc0dd\ud65c\uc744 \uc228\uc5b4 \uc9c0\ucf1c\ubcf4\ub294 \ub3d9\uc548 \ub9d0\uacfc \uad00\uacc4\ub97c \ubc30\uc6b4\ub2e4. \ucc45\uc744 \uc77d\uc73c\uba74\uc11c \uc790\uc2e0\uc758 \ucc98\uc9c0\uc640 \uc778\uac04\uc758 \uc5ed\uc0ac\ub97c \uc0dd\uac01\ud558\uac8c\ub3c4 \ub41c\ub2e4. \uc774 \uacfc\uc815\uc5d0\uc11c \ud53c\uc870\ubb3c\uc740 \uc18c\ub9ac\ub9cc \uc9c0\ub974\ub294 \uad34\ubb3c\uc774 \uc544\ub2c8\ub77c \ubc30\uc6b0\uace0 \ube44\uad50\ud558\uba70 \uc790\uae30 \uc0b6\uc758 \uc774\uc720\ub97c \ubb3b\ub294 \uc874\uc7ac\uac00 \ub41c\ub2e4. \ud53c\uc870\ubb3c\uc740 \ub208\uc774 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uac00\uc871\uc758 \ub178\uc778\uc5d0\uac8c \ub2e4\uac00\uac00 \uc790\uc2e0\uc758 \ub9d0\uc744 \ub4e4\uc5b4 \ub2ec\ub77c\uace0 \ud55c\ub2e4. \uc678\ubaa8\ub97c \uba3c\uc800 \ubcf4\uc9c0 \uc54a\ub294 \uc0c1\ub300\uc5d0\uac8c\ub294 \uc774\ud574\ubc1b\uc744 \uc218 \uc788\uc73c\ub9ac\ub77c\ub294 \uae30\ub300\ub2e4. \ud558\uc9c0\ub9cc \ub2e4\ub978 \uac00\uc871\uc774 \ub3cc\uc544\uc624\uba74\uc11c \uc2dc\ub3c4\ub294 \ubb34\ub108\uc9c0\uace0 \uadf8\ub294 \ub2e4\uc2dc \ubc30\ucc99\ub2f9\ud55c\ub2e4. \uc774 \uc7a5\uba74\uc740 \uc678\ubaa8\uc5d0 \ub300\ud55c \ud310\ub2e8\uacfc \ub9d0\uc744 \ub4e4\uc744 \uae30\ud68c\uc758 \uad00\uacc4\ub97c \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ub3d9\uc2dc\uc5d0 \ud53c\uc870\ubb3c\uc774 \ubd88\ud589\ud588\uc73c\ub2c8 \uc774\ud6c4\uc758 \ud3ed\ub825\uc740 \ubaa8\ub450 \uc815\ub2f9\ud558\ub2e4\ub294 \uacb0\ub860\uc73c\ub85c \ub098\uc544\uac00\uc9c0\ub294 \ub9d0\uc790. \uc18c\uc124\uc740 \uadf8\uac00 \uacaa\uc740 \uc0c1\ucc98\ub97c \ub4e4\ub824\uc8fc\uc9c0\ub9cc, \ub2e4\ub978 \uc0dd\uba85\uc744 \ud574\uce58\ub294 \uc120\ud0dd\uc758 \ucc45\uc784\uae4c\uc9c0 \uc5c6\uc560\uc9c0\ub294 \uc54a\ub294\ub2e4. \ube45\ud130\uc758 \uc5b4\ub9b0 \ub3d9\uc0dd \uc70c\ub9ac\uc5c4\uc774 \uc0b4\ud574\ub418\uace0 \uc950\uc2a4\ud2f4\uc774 \ubc94\uc778\uc73c\ub85c \ubab0\ub9b0\ub2e4. \ud53c\uc870\ubb3c\uc758 \ud589\ub3d9\uacfc \ube45\ud130\uc758 \uce68\ubb35\uc740 \uc9c1\uc811 \uc2e4\ud5d8\uc5d0 \ucc38\uc5ec\ud558\uc9c0 \uc54a\uc740 \uc0ac\ub78c\ub4e4\uc758 \uc0b6\uae4c\uc9c0 \ubb34\ub108\ub728\ub9b0\ub2e4. \ube44\ubc00\uc744 \uc9c0\ud0a4\uba74 \ubb38\uc81c\ub97c \uc790\uae30 \uc548\uc5d0 \ubb36\uc5b4 \ub458 \uc218 \uc788\ub2e4\ub294 \uc0dd\uac01\uc740 \ud1b5\ud558\uc9c0 \uc54a\ub294\ub2e4. \ube45\ud130\ub294 \ub450\ub824\uc6c0\uacfc \uc8c4\ucc45\uac10\uc744 \uacaa\uc73c\uba74\uc11c\ub3c4 \uc790\uc2e0\uc758 \uc774\uc57c\uae30\ub97c \uc5b4\ub5bb\uac8c \uc124\uba85\ud560\uc9c0 \ub9dd\uc124\uc778\ub2e4. \uadf8\ub294 \ub2e8\uc21c\ud788 \uc545\ud55c \uacfc\ud559\uc790\ub77c\uae30\ubcf4\ub2e4, \ud558\uace0 \uc2f6\uc740 \uc77c\uc744 \ud560 \ub54c\uc758 \ub300\ub2f4\ud568\uacfc \uacb0\uacfc\ub97c \uac10\ub2f9\ud560 \ub54c\uc758 \uc8fc\uc800\ud568\uc774 \ud06c\uac8c \uc5b4\uae0b\ub098\ub294 \uc778\ubb3c\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \uadf8 \uc5b4\uae0b\ub0a8\uc758 \ub300\uac00\ub294 \uc8fc\ubcc0 \uc0ac\ub78c\ub4e4\ub3c4 \uce58\ub978\ub2e4. \ud53c\uc870\ubb3c\uc740 \uc790\uc2e0\uacfc \ud568\uaed8 \uc0b4\uc544\uac08 \uc874\uc7ac\ub97c \ub9cc\ub4e4\uc5b4 \ub2ec\ub77c\uace0 \uc694\uad6c\ud55c\ub2e4. \uc778\uac04\uc5d0\uac8c \ubc1b\uc544\ub4e4\uc5ec\uc9c0\uae30 \uc5b4\ub835\ub2e4\uba74 \uc801\uc5b4\ub3c4 \ud640\ub85c \ub0a8\uc9c0 \uc54a\uac8c \ud574 \ub2ec\ub77c\ub294 \uc694\uccad\uc774\ub2e4. \ube45\ud130\ub294 \uc57d\uc18d\ud558\uace0 \uc791\uc5c5\uc744 \uc2dc\uc791\ud558\uc9c0\ub9cc \uc55e\uc73c\ub85c \uc0dd\uae38 \uc77c\uc744 \ub450\ub824\uc6cc\ud574 \uc644\uc131\ud558\uae30 \uc804\uc5d0 \ud30c\uad34\ud55c\ub2e4. \uc774 \uacb0\uc815\uc740 \uc26c\uc6b4 \uc815\ub2f5\uc73c\ub85c \ub098\ub204\uae30 \uc5b4\ub835\ub2e4. \uc774\ubbf8 \ub9cc\ub4e4\uc5b4\uc9c4 \uc874\uc7ac\uc5d0\uac8c \uc9c0\ub294 \ucc45\uc784\uacfc, \ub610 \ub2e4\ub978 \uc0dd\uba85\uc744 \ub9cc\ub4dc\ub294 \uc77c\uc758 \uc704\ud5d8\uc774 \ucda9\ub3cc\ud55c\ub2e4. \uc18c\uc124\uc740 \ub3c5\uc790\ub97c \uc5f0\uad6c\ub97c \uacc4\uc18d\ud558\ub77c\ub294 \ucabd\uc774\ub098 \ubaa8\ub4e0 \ucc3d\uc870\ub97c \uae08\uc9c0\ud558\ub77c\ub294 \ucabd\uc73c\ub85c \uace7\uc7a5 \ubcf4\ub0b4\uc9c0 \uc54a\uace0, \ucc98\uc74c\uc5d0 \ud53c\ud588\ub358 \uad00\uacc4\uc758 \ubb38\uc81c \uc55e\uc73c\ub85c \ub418\ub3cc\ub824 \ub193\ub294\ub2e4. \uce5c\uad6c \ud074\ub808\ub974\ubc1c\uacfc \ube45\ud130\uc758 \uc2e0\ubd80 \uc5d8\ub9ac\uc790\ubca0\uc2a4\uc5d0\uac8c\ub3c4 \uc8fd\uc74c\uc774 \ub2e5\uce5c\ub2e4. \ube45\ud130\ub294 \ud53c\uc870\ubb3c\uc744 \ucd94\uc801\ud558\uba70 \ub0a8\uc740 \uc0b6\uc744 \ubcf5\uc218\uc5d0 \uac74\ub2e4. \uc790\uc2e0\uc774 \ub9cc\ub4e0 \uc874\uc7ac\ub97c \ud53c\ud558\ub358 \uc0ac\ub78c\uc774 \uc774\uc81c \uadf8 \uc874\uc7ac\ub97c \ucad3\ub294 \uc77c\ub9cc\uc744 \uc0b6\uc758 \ubaa9\uc801\uc73c\ub85c \uc0bc\ub294\ub2e4. \ub458\uc758 \uad00\uacc4\ub294 \ub04a\uc5b4\uc9c0\uc9c0 \uc54a\uace0 \ub354 \ud30c\uad34\uc801\uc778 \ubc29\uc2dd\uc73c\ub85c \ubd99\uc7a1\ud78c\ub2e4. \uc5bc\uc74c\ubc14\ub2e4\uc5d0\uc11c \ube45\ud130\ub294 \uc6d4\ud134\uc5d0\uac8c \uc774\uc57c\uae30\ub97c \ub05d\ub0b4\uace0 \uc8fd\ub294\ub2e4. \ub9c8\uc9c0\ub9c9\uc5d0 \ud53c\uc870\ubb3c\uc774 \ub098\ud0c0\ub098 \uc790\uae30 \ud589\ub3d9\uc744 \ub3cc\uc544\ubcf4\uace0 \uc790\uc2e0\uc758 \uc0b6\ub3c4 \ub05d\ub0b4\uaca0\ub2e4\ub294 \ub73b\uc744 \ub9d0\ud55c \ub4a4 \uc0ac\ub77c\uc9c4\ub2e4. \ub3c5\uc790\uac00 \uadf8 \ub4a4\uc758 \uc2e4\ud589\uae4c\uc9c0 \uc9c1\uc811 \ubcf4\uc9c0\ub294 \uc54a\ub294\ub2e4. \uacb0\ub9d0\uc740 \uc2b9\ub9ac\ud55c \uc601\uc6c5\ubcf4\ub2e4 \ud669\ud3d0\ud574\uc9c4 \uad00\uacc4\ub97c \ub0a8\uae34\ub2e4. \uc6d4\ud134\uc5d0\uac8c\ub3c4 \ub0a8\ub4e4\uc774 \ub118\uc9c0 \ubabb\ud55c \uacbd\uacc4\ub97c \ub118\uace0 \uc2f6\ub2e4\ub294 \uc57c\ub9dd\uc774 \uc788\ub2e4. \uadf8\ub798\uc11c \ube45\ud130\uc758 \uc774\uc57c\uae30\ub97c \ub4e3\ub294 \uadf8\uc758 \uc704\uce58\uac00 \uc911\uc694\ud558\ub2e4. \ub204\uad70\uac00\uc758 \ube44\uadf9\uc744 \uc54c\uace0 \ub098\uc11c\ub3c4 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ub2e4\ub978 \uc0ac\ub78c\uc744 \uc704\ud5d8\uc5d0 \ubc00\uc5b4 \ub123\uc744 \uac83\uc778\uac00. \ud0d0\ud5d8\uc5d0 \ub3d9\ud589\ud55c \uc0ac\ub78c\ub4e4\uc758 \uc0b6\ub3c4 \uace0\ub824\ud574\uc57c \ud55c\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\uc740 \ud53c\uc870\ubb3c\uc758 \ubc30\uc6c0\uacfc \uace0\ub9bd\uc774\ub77c\ub294 \uc815\uc11c\ub97c \uc0c1\uc0c1\ud55c AI \uc0bd\ud654\ub2e4. \ud2b9\uc815 \uc7a5\uba74\uc744 \uc815\ud655\ud788 \ubcf5\uc6d0\ud558\uac70\ub098 \uc601\ud654 \uc18d \uc678\ud615\uc744 \uc62e\uae34 \uadf8\ub9bc\uc740 \uc544\ub2c8\ub2e4. \ub204\uad6c\uc758 \ub9d0\uc774 \ub204\uad6c\ub97c \uac70\uccd0 \ub3c5\uc790\uc5d0\uac8c \uc624\ub294\uc9c0 \ud655\uc778\ud558\uace0 \uc77d\uc73c\uba74, \ube45\ud130\uc758 \ud6c4\ud68c\uc640 \ud53c\uc870\ubb3c\uc758 \ud56d\ubcc0\uc774 \uac01\uac01 \ubb34\uc5c7\uc744 \uac15\uc870\ud558\uace0 \ube44\uc6cc \ub450\ub294\uc9c0\ub3c4 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \u300e\ud504\ub791\ucf04\uc288\ud0c0\uc778\u300f\uc744 \uacfc\ud559\uc740 \uc704\ud5d8\ud558\ub2e4\ub294 \ud55c \uc904\uc758 \uacbd\uace0\ub85c\ub9cc \uc77d\uc73c\uba74 \ub9ce\uc740 \ubd80\ubd84\uc774 \ube60\uc9c4\ub2e4. \uc9c0\uc2dd\uc5d0 \ub300\ud55c \uc5f4\ub9dd, \ub3cc\ubd04\uc744 \ubc1b\uc9c0 \ubabb\ud55c \uc0b6, \uc678\ubaa8\uc5d0 \ub300\ud55c \ud310\ub2e8, \uacb0\uacfc\ub97c \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ub5a0\ub118\uae30\ub294 \ud0dc\ub3c4\uac00 \ud568\uaed8 \ub4e4\uc5b4 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uc5b4\ub290 \ud55c\ucabd\uc758 \uace0\ud1b5\uc744 \uc774\ud574\ud558\ub294 \uac83\uacfc \uadf8 \ud589\ub3d9\uc744 \ubaa8\ub450 \ud5c8\uc6a9\ud558\ub294 \uac83\ub3c4 \ub2e4\ub978 \uc77c\uc774\ub2e4. \ubb34\uc5c7\uc744 \uc0c8\ub85c \ub9cc\ub4e4\uc5c8\uc744 \ub54c \uc131\uacf5\uc758 \uc21c\uac04\ub9cc\uc774 \uc544\ub2c8\ub77c \uadf8 \ub4a4\uc758 \uad00\uacc4\uae4c\uc9c0 \uc0c1\uc0c1\ud560 \uc218 \uc788\uc744\uae4c. \uc774 \uc9c8\ubb38\uc740 \uc2e4\ud5d8\uc2e4 \ubc16\uc5d0\uc11c\ub3c4 \uc720\ud6a8\ud558\ub2e4. \uc624\ub798\ub41c \uad34\ubb3c\uc758 \uc5bc\uad74\uc744 \ud655\uc778\ud558\uae30\ubcf4\ub2e4, \uc11c\ub85c\uc758 \uc774\uc57c\uae30\ub97c \ub4e3\uc9c0 \ubabb\ud55c \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub5bb\uac8c \ube44\uadf9\uc744 \ud0a4\uc6e0\ub294\uc9c0 \ub530\ub77c\uac00 \ubcf4\uba74 \uc791\ud488\uc740 \ud6e8\uc52c \ub113\uc5b4\uc9c4\ub2e4."}, {"id": "fur-elise-title-and-theme", "title": "\uc5d8\ub9ac\uc81c\ub97c \uc704\ud558\uc5ec \u2014 \uc775\uc219\ud55c \uc120\uc728 \uc55e\uc5d0 \ub0a8\uc740 \uc774\ub984", "summary": "\ubca0\ud1a0\ubca4\uc758 \uc791\uc740 \ud53c\uc544\ub178\uace1\uc744 \uc120\uc728\uacfc \ud45c\uc81c\uc5d0\uc11c \uc2dc\uc791\ud574 \ub4e4\uc5b4 \ubd05\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Music", "url": "stories/fur-elise-title-and-theme/index.html", "image": "media/fur-elise-title-and-theme-scene-20261030.png", "alt": "\ubd80\ub4dc\ub7ec\uc6b4 \ucc3d\uac00 \ube5b\uc774 \ub4dc\ub294 \ubc29\uc5d0 \uc61b \ud53c\uc544\ub178\uc640 \uc758\uc790\uac00 \ub193\uc778 \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\uc5d8\ub9ac\uc81c\ub97c \uc704\ud558\uc5ec \u2014 \uc775\uc219\ud55c \uc120\uc728 \uc55e\uc5d0 \ub0a8\uc740 \uc774\ub984 \uc81c\ubaa9\uc774 \ub9d0\ud574 \uc8fc\ub294 \uac83\uacfc \ub9d0\ud574 \uc8fc\uc9c0 \uc54a\ub294 \uac83 \ubca0\ud1a0\ubca4\uc758 \uc791\uc740 \ud53c\uc544\ub178\uace1\uc744 \uc120\uc728\uacfc \ud45c\uc81c\uc5d0\uc11c \uc2dc\uc791\ud574 \ub4e4\uc5b4 \ubd05\ub2c8\ub2e4. Music \ubb38\ud654 \ubbf8, \ub808 \uc0f5, \ubbf8, \ub808 \uc0f5. \uc9e7\uc740 \uc2dc\uc791\ub9cc\uc73c\ub85c \uace1\uc744 \uc54c\uc544\ub4e3\ub294 \uc0ac\ub78c\uc774 \ub9ce\ub2e4. \ubca0\ud1a0\ubca4\uc758 \u3008\uc5d8\ub9ac\uc81c\ub97c \uc704\ud558\uc5ec\u3009\ub294 \ud53c\uc544\ub178\ub97c \ubc30\uc6b0\ub358 \uae30\uc5b5\uc774\ub098 \uc77c\uc0c1\uc5d0\uc11c \ud758\ub7ec\ub098\uc624\ub358 \uc18c\ub9ac\uc640 \ud568\uaed8 \uc775\uc219\ud574\uc9c4 \uc791\ud488\uc774\ub2e4. \uadf8\ub7f0\ub370 \ucc98\uc74c\uc758 \uba87 \uc74c\uc744 \uc548\ub2e4\ub294 \uac83\uacfc \uace1 \uc804\uccb4\ub97c \ub4e4\uc5b4 \ubcf4\uc558\ub2e4\ub294 \uac83\uc740 \uc870\uae08 \ub2e4\ub974\ub2e4. \uc774 \uc791\ud488\uc744 \ub450 \uac1c\uc758 \uae38\ub85c \ub9cc\ub098 \ubcf4\uc790. \uba3c\uc800 \uc81c\ubaa9\uc774 \ubb34\uc5c7\uc744 \uc54c\ub824 \uc8fc\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uace0, \ub2e4\uc74c\uc5d0\ub294 \uc775\uc219\ud55c \uc120\uc728\uc774 \ub0af\uc120 \uad6c\uac04\uc744 \uc9c0\ub098 \uc5b4\ub5bb\uac8c \ub3cc\uc544\uc624\ub294\uc9c0 \ub4e4\uc5b4 \ubcf4\ub294 \uac83\uc774\ub2e4. \uc545\ubcf4\ub97c \uc77d\uc9c0 \ubabb\ud574\ub3c4 \ub530\ub77c\uac08 \uc218 \uc788\ub2e4. \ub3c5\uc77c\uc5b4 F\u00fcr Elise\ub294 \u2018\uc5d8\ub9ac\uc81c\ub97c \uc704\ud558\uc5ec\u2019\ub77c\ub294 \ub73b\uc774\ub2e4. \ub204\uad70\uac00\ub97c \ud5a5\ud55c \ud45c\uc81c\uac00 \ubd99\uc5b4 \uc788\uc73c\ub2c8 \uc774\ub984\uc758 \uc8fc\uc778\uc774 \uad81\uae08\ud574\uc9c0\ub294 \uac83\uc740 \uc790\uc5f0\uc2a4\ub7fd\ub2e4. \uadf8\ub7ec\ub098 \uc81c\ubaa9 \ud558\ub098\uac00 \uadf8 \uc0ac\ub78c\uc758 \uc2e0\uc6d0\uacfc \uc791\uace1\uac00\uc758 \uc5f0\uc560\uc0ac\ub97c \uc804\ubd80 \uc99d\uba85\ud574 \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc774\ubc88\uc5d0 \ub300\uc870\ud55c \uc545\ubcf4\ub294 \uc774 \uace1\uc744 \ubca0\ud1a0\ubca4\uc758 \ud53c\uc544\ub178\uace1, \uac00\ub2e8\uc870, WoO 59\ub85c \uc81c\uc2dc\ud558\uace0 1810\ub144\uc744 \ud45c\uae30\ud55c\ub2e4. \ubc18\uba74 \uc5d8\ub9ac\uc81c\uc758 \uc2e0\uc6d0\uc774\ub098 \ud5cc\uc815\uc758 \uacbd\uc704\ub97c \uc124\uba85\ud558\ub294 \uadfc\uac70\ub294 \uc81c\uacf5\ud558\uc9c0 \uc54a\ub294\ub2e4. \ub530\ub77c\uc11c \uc5ec\uae30\uc11c\ub294 \ud2b9\uc815 \uc778\ubb3c\uc744 \uc8fc\uc778\uacf5\uc73c\ub85c \ud55c \uace0\ubc31 \uc774\uc57c\uae30\ub97c \ud655\uc815\ud574\uc11c \ub4e4\ub824\uc8fc\uc9c0 \uc54a\ub294\ub2e4. \uc81c\ubaa9\uc758 \ub73b\uc740 \ubd84\uba85\ud788 \uc124\uba85\ud558\ub418, \uc0ac\uc5f0\uc744 \ud655\uc778\ud558\uc9c0 \ubabb\ud55c \uacf3\uc740 \ub0a8\uaca8 \ub450\ub294 \ud3b8\uc774 \uc791\ud488\uc744 \uc774\ud574\ud558\ub294 \ub370\ub3c4 \uc815\uc9c1\ud558\ub2e4. \ud074\ub798\uc2dd \uace1\uc5d0\ub294 \uc791\ud488\ubc88\ud638\uac00 \ubd99\ub294 \uacbd\uc6b0\uac00 \ub9ce\ub2e4. \uc774 \uace1\uc758 WoO\ub294 \ub3c5\uc77c\uc5b4 \u2018\uc791\ud488\ubc88\ud638 \uc5c6\ub294 \uc791\ud488\ub4e4\u2019\uc774\ub77c\ub294 \ubd84\ub958\ub97c \uc904\uc778 \ud45c\uae30\ub2e4. \ubca0\ud1a0\ubca4\uc758 \uc74c\uc545\uc744 \uc815\ub9ac\ud558\ub294 \ubaa9\ub85d \uc548\uc5d0\uc11c \uc774 \uace1\uc744 \ucc3e\uac8c \ud574 \uc8fc\ub294 \uc8fc\uc18c\ub77c\uace0 \uc0dd\uac01\ud558\uba74 \ub41c\ub2e4. \uc22b\uc790\uac00 \uc791\ub2e4\uace0 \ucd08\ubcf4\uc790\uc6a9\uc774\ub77c\ub294 \ub73b\ub3c4, 59\ubc88\uc9f8\ub85c \uc791\uace1\ud588\ub2e4\ub294 \ub73b\ub3c4 \uc544\ub2c8\ub2e4. \uac19\uc740 \uc81c\ubaa9\uc758 \ud3b8\uace1\uacfc \uc9e7\uac8c \uc798\ub77c \ub0b8 \uc74c\uc6d0\uc774 \ub9ce\uc744 \ub54c \u2018\ubca0\ud1a0\ubca4, WoO 59, \ud53c\uc544\ub178 \ub3c5\uc8fc\u2019\ub97c \ud568\uaed8 \ud655\uc778\ud558\uba74 \uc5b4\ub5a4 \uace1\uc778\uc9c0 \uad6c\ubd84\ud558\uae30 \uc27d\ub2e4. \uc5ec\uae30\uc11c \uc77d\uc740 \uac83\uc740 1888\ub144 \ucd9c\ud310 \uc545\ubcf4\ub97c \ubc14\ud0d5\uc73c\ub85c \ud604\ub300\uc5d0 \uc0c8\ub85c \uc870\ud310\ud55c \uc790\ub8cc\ub2e4. \uc624\ub298 \ubcf4\ub294 \uc545\ubcf4\uc640 \uc791\uace1\uac00\uac00 \uc885\uc774\uc5d0 \ucc98\uc74c \uc801\uc5c8\ub358 \uc6d0\uace0\ub97c \uac19\uc740 \ubb3c\uac74\uc73c\ub85c \uc18c\uac1c\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc2dc\uc791 \ubd80\ubd84\uc740 \ubbf8\uc640 \uadf8 \ubc14\ub85c \uc544\ub798\uc758 \ub808 \uc0f5\uc744 \uc624\uac00\uba70 \ub9dd\uc124\uc774\ub294 \ub4ef \uc6c0\uc9c1\uc778\ub2e4. \ub450 \uc74c\uc758 \uac70\ub9ac\ub294 \ud53c\uc544\ub178 \uac74\ubc18\uc5d0\uc11c \ubc14\ub85c \uc774\uc6c3\ud55c \ubc18\uc74c\uc774\ub2e4. \ud070 \ud3ed\uc73c\ub85c \ub6f0\uc5b4\uc624\ub974\ub294 \ub300\uc2e0 \uc881\uc740 \uacf3\uc744 \ubc18\ubcf5\ud574\uc11c \uac74\ub4dc\ub9ac\ubbc0\ub85c, \uc9e7\uc740 \uc6c0\uc9c1\uc784 \uc790\uccb4\uac00 \uace1\uc758 \uc5bc\uad74\uc774 \ub41c\ub2e4. \uc774\uc5b4 \uc2dc, \ub808, \ub3c4, \ub77c\ub85c \uae38\uc774 \uc5f4\ub9ac\uba70 \uc6b0\ub9ac\uac00 \uae30\uc5b5\ud558\ub294 \uccab \uad6c\uc808\uc774 \ub9cc\ub4e4\uc5b4\uc9c4\ub2e4. \uc624\ub978\uc190\uc758 \uc120\uc728 \uc544\ub798\uc5d0\uc11c\ub294 \uc67c\uc190\uc774 \ud654\uc74c\uc758 \uc74c\ub4e4\uc744 \ucc28\ub840\ub85c \ud3bc\uccd0 \ub193\ub294\ub2e4. \uc5ec\ub7ec \uc74c\uc744 \ud55c\uaebc\ubc88\uc5d0 \ub204\ub974\uc9c0 \uc54a\uace0 \ub098\ub204\uc5b4 \uc6b8\ub9ac\ub294 \ubc18\uc8fc\ub2e4. \uc775\uc219\ud55c \uba5c\ub85c\ub514\ub9cc \ub530\ub77c \ubd80\ub974\ub358 \uc0ac\ub78c\ub3c4 \ub0ae\uc740 \ucabd\uc758 \uc6c0\uc9c1\uc784\uc744 \ud568\uaed8 \ub4e4\uc73c\uba74 \uc74c\uc545\uc774 \ud55c \uc904\ub85c\ub9cc \uc9c4\ud589\ub418\uc9c0 \uc54a\ub294\ub2e4\ub294 \uac83\uc744 \ub290\ub084 \uc218 \uc788\ub2e4. \uace1\uc758 \ud750\ub984\uc744 \uac04\ub2e8\ud788 \uc801\uc73c\uba74 \u2018\ucc98\uc74c \uc120\uc728 \u2014 \ub2e4\ub978 \uc7a5\uba74 \u2014 \ucc98\uc74c \uc120\uc728 \u2014 \ub610 \ub2e4\ub978 \uc7a5\uba74 \u2014 \ucc98\uc74c \uc120\uc728\u2019\ucc98\ub7fc \ub4e4\uc744 \uc218 \uc788\ub2e4. \uc74c\uc545\uc5d0\uc11c \uc774\ub7f0 \ubc18\ubcf5\uacfc \ub300\ube44\ub97c \uc124\uba85\ud560 \ub54c \ub860\ub3c4\ub77c\ub294 \ub9d0\uc744 \uc4f4\ub2e4. \uc5b4\ub824\uc6b4 \ud615\uc2dd \uc774\ub984\ubcf4\ub2e4 \uc9d1\uc73c\ub85c \ub3cc\uc544\uc624\ub294 \uae38\uc744 \ub5a0\uc62c\ub824\ub3c4 \uc88b\ub2e4. \uac19\uc740 \ubb38\uc744 \ub2e4\uc2dc \uc5f4\uc5b4\ub3c4, \uadf8 \uc0ac\uc774 \uc5b4\ub514\ub97c \ub2e4\ub140\uc654\ub290\ub0d0\uc5d0 \ub530\ub77c \ub3cc\uc544\uc628 \ub290\ub08c\uc740 \ub2ec\ub77c\uc9c4\ub2e4. \ubc18\ubcf5\ub418\ub294 \uccab \uc120\uc728\uc744 A\ub77c\uace0 \ub9c8\uc74c\uc18d\uc73c\ub85c \ud45c\uc2dc\ud574 \ubcf4\uc790. A\uac00 \uc544\ub2cc \ubd80\ubd84\uc774 \ub098\uc624\uba74 \ubaa8\ub974\ub294 \uace1\uc73c\ub85c \ubc14\ub00c\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud558\uae30\ubcf4\ub2e4, \uc775\uc219\ud55c \uc120\uc728\uacfc \ubb34\uc5c7\uc774 \ub2e4\ub978\uc9c0 \ub4e4\uc5b4 \ubcf4\uba74 \ub41c\ub2e4. \uc545\ubcf4\uc758 \ubaa8\ub4e0 \ubc18\ubcf5 \uae30\ud638\ub97c \uacc4\uc0b0\ud558\uc9c0 \uc54a\uc544\ub3c4 \uadc0\ub85c \ud070 \uad6c\uc870\ub97c \uc7a1\uc744 \uc218 \uc788\ub294 \ubc29\ubc95\uc774\ub2e4. \ucc98\uc74c \uc120\uc728\uc744 \ubc97\uc5b4\ub098\uba74 \uc74c\ub4e4\uc774 \ub354 \ucd18\ucd18\ud558\uac8c \uc6c0\uc9c1\uc774\uace0 \uc74c\uc545\uc758 \ud45c\uc815\uc774 \ubc1d\uc544\uc9c0\ub294 \uad6c\uac04\uc774 \ub098\ud0c0\ub09c\ub2e4. \ucc98\uc74c\uc758 \uc870\uc2ec\uc2a4\ub7ec\uc6b4 \ubb3c\uc74c\ud45c\uc5d0\uc11c \uc870\uae08 \ub354 \ub113\uace0 \uc720\uc5f0\ud55c \uc6c0\uc9c1\uc784\uc73c\ub85c \ub098\uc544\uac00\ub294 \ub4ef \ub4e4\uc744 \uc218 \uc788\ub2e4. \uc774\ub294 \uac10\uc0c1\uc744 \ub3d5\uae30 \uc704\ud55c \ube44\uc720\uc774\uba70 \uc791\uace1\uac00\uac00 \uc815\ud574 \ub454 \uc904\uac70\ub9ac\ub294 \uc544\ub2c8\ub2e4. \ud53c\uc544\ub178\ub97c \ub9c9 \ubc30\uc6b0\ub294 \uc0ac\ub78c\uc774 \uccab \ubd80\ubd84\uc744 \uc5f0\uc8fc\ud560 \uc218 \uc788\ub2e4\uace0 \ud574\uc11c \uace1 \uc804\uccb4\uac00 \uac19\uc740 \ub09c\uc774\ub3c4\ub85c \uc774\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774 \uad6c\uac04\uc5d0\uc11c\ub294 \ube60\ub974\uac8c \uc774\uc5b4\uc9c0\ub294 \uc74c\ub4e4\uacfc \uc190\uc758 \uc774\ub3d9\uc774 \ud544\uc694\ud558\ub2e4. \ucc98\uc74c \uba87 \ub9c8\ub514\ub9cc\uc73c\ub85c \u2018\uc26c\uc6b4 \uc18c\ud488\u2019\uc774\ub77c\uace0 \ud310\ub2e8\ud558\uba74 \uc74c\uc545\uc774 \uac10\ucd94\uace0 \uc788\ub358 \ub2e4\ub978 \ud45c\uc815\uc744 \ub193\uce5c\ub2e4. \ub4a4\ucabd\uc758 \ub610 \ub2e4\ub978 \uad6c\uac04\uc5d0\uc11c\ub294 \ub0ae\uc740 \uc74c\uc758 \ubc18\ubcf5\uc774 \uadc0\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uadf8 \uc704\uc758 \ud654\uc74c\uacfc \uc120\uc728\uc774 \uc6c0\uc9c1\uc774\uba74\uc11c \ucc98\uc74c\ubcf4\ub2e4 \uae34\uc7a5\ub41c \ub290\ub08c\uc744 \ub9cc\ub4e0\ub2e4. \ucc98\uc74c\uc5d0 \uac00\uae4c\uc6b4 \ub450 \uc74c\uc744 \uc624\uac00\ub358 \uc12c\uc138\ud568\uacfc\ub294 \ub2e4\ub978, \uc870\uae08 \ub354 \ub2e8\ub2e8\ud558\uace0 \ub2e4\uae09\ud55c \ucd94\uc9c4\ub825\uc744 \ub4e4\uc744 \uc218 \uc788\ub2e4. \uadf8 \uae34\uc7a5\uc774 \uc9c0\ub09c \ub4a4 \ucc98\uc74c\uc758 \uc120\uc728\uc774 \ub3cc\uc544\uc624\uba74 \uace1\uc758 \uc2dc\uc791\uacfc \ub05d\uc774 \uc5f0\uacb0\ub41c\ub2e4. \uac19\uc740 \uc74c\uc774 \ub3cc\uc544\uc640\ub3c4 \uc774\ubbf8 \ub2e4\ub978 \uc7a5\uba74\uc744 \uac70\ucce4\uae30 \ub54c\ubb38\uc5d0 \ub2e8\uc21c\ud55c \ub418\ud480\uc774\ub85c\ub9cc \ub4e4\ub9ac\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \uc774\ubc88\uc5d0\ub294 \ubc18\uc8fc\ub97c, \ub2e4\uc74c\uc5d0\ub294 \uc120\uc728\uc744 \ub530\ub77c\uac00\uba70 \ub450 \ubc88 \ub4e4\uc5b4 \ubcf4\uba74 \uc774\ub7f0 \ubcc0\ud654\uac00 \ub354 \ubd84\uba85\ud574\uc9c4\ub2e4. \uba3c\uc800 \uace1 \uc804\uccb4\ub97c \ub05d\uae4c\uc9c0 \ud55c \ubc88 \ub4e4\uc5b4 \ubcf4\uc790. \ub450 \ubc88\uc9f8\uc5d0\ub294 \uccab \uc120\uc728\uc774 \ub3cc\uc544\uc624\ub294 \uc21c\uac04\uc744 \ucc3e\uace0, \uc138 \ubc88\uc9f8\uc5d0\ub294 \uac00\uc6b4\ub370 \ub450 \uad6c\uac04\uc758 \ucc28\uc774\ub97c \ub4e4\uc5b4 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \ubaa8\ub4e0 \uac83\uc744 \ud55c\uaebc\ubc88\uc5d0 \uc54c\uc544\ub0b4\ub824\uace0 \ud558\uc9c0 \uc54a\uc73c\uba74 \uc775\uc219\ud55c \uc74c\uc545\ub3c4 \uc0c8\ub86d\uac8c \ub4e4\uc744 \uc5ec\uc720\uac00 \uc0dd\uae34\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\uc740 \uc61b \ud53c\uc544\ub178\uac00 \ub193\uc778 \ubc29\uc744 \ud1b5\ud574 \uace1\uc758 \uc870\uc6a9\ud55c \ubd84\uc704\uae30\ub97c \uc0c1\uc0c1\ud55c AI \uc0bd\ud654\ub2e4. \ubca0\ud1a0\ubca4\uc758 \uc2e4\uc81c \ubc29\uc774\ub098 \uc545\uae30, \uc5d8\ub9ac\uc81c\uc758 \uc815\uccb4\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uc5d8\ub9ac\uc81c\uac00 \ub204\uad6c\uc600\ub294\uc9c0 \uad81\uae08\ud574\ud558\ub294 \ub9c8\uc74c\uacfc, \uc2e4\uc81c\ub85c \ub4e4\ub9ac\ub294 \uc74c\uc744 \uc990\uae30\ub294 \ub9c8\uc74c\uc740 \ud568\uaed8 \uac08 \uc218 \uc788\ub2e4. \ud655\uc815\ub418\uc9c0 \uc54a\uc740 \ub85c\ub9e8\uc2a4\ub97c \ucc44\uc6cc \ub123\uc9c0 \uc54a\uc544\ub3c4 \uc774 \uc9e7\uc740 \uace1 \uc548\uc5d0\ub294 \ubc18\ubcf5, \ub300\ube44, \uae34\uc7a5\uacfc \uadc0\ud658\uc774\ub77c\ub294 \uaf64 \ud48d\ubd80\ud55c \uc2dc\uac04\uc774 \ub4e4\uc5b4 \uc788\ub2e4."}, {"id": "gericault-medusa-distant-ship", "title": "\uba54\ub450\uc0ac\ud638\uc758 \ub5cf\ubaa9 \u2014 \uba40\ub9ac \ubcf4\uc774\ub294 \uc791\uc740 \ubc30\ub97c \ud5a5\ud558\uc5ec", "summary": "\uc81c\ub9ac\ucf54\uac00 \uc2e4\uc81c \ub09c\ud30c \uc0ac\uac74\uc744 \uadf8\ub9bc\uc73c\ub85c \uc62e\uae30\uba70 \uc2dc\uc120\uacfc \ubab8\uc758 \ubc29\ud5a5\uc73c\ub85c \uae34\uc7a5\uc744 \ub9cc\ub4e0 \ubc29\ubc95\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Art", "url": "stories/gericault-medusa-distant-ship/index.html", "image": "media/gericault-medusa-distant-ship.jpg", "alt": "\uc81c\ub9ac\ucf54\uc758 \uba54\ub450\uc0ac\ud638\uc758 \ub5cf\ubaa9\uc744 \uc7ac\ud604\ud55c \uc61b \ub3c4\ud310. \uc55e\ucabd\uc758 \uc4f0\ub7ec\uc9c4 \uc778\ubb3c\ub4e4\uacfc \uba3c \ubc30\ub97c \ud5a5\ud574 \ucc9c\uc744 \ub4dc\ub294 \uc0ac\ub78c\ub4e4\uc774 \ud568\uaed8 \ubcf4\uc785\ub2c8\ub2e4.", "text": "\uba54\ub450\uc0ac\ud638\uc758 \ub5cf\ubaa9 \u2014 \uba40\ub9ac \ubcf4\uc774\ub294 \uc791\uc740 \ubc30\ub97c \ud5a5\ud558\uc5ec \uc808\ub9dd\uacfc \uad6c\uc870\uc758 \uae30\ub300\uac00 \ud55c \ud654\uba74\uc5d0 \ub193\uc774\ub294 \ubc29\uc2dd \uc81c\ub9ac\ucf54\uac00 \uc2e4\uc81c \ub09c\ud30c \uc0ac\uac74\uc744 \uadf8\ub9bc\uc73c\ub85c \uc62e\uae30\uba70 \uc2dc\uc120\uacfc \ubab8\uc758 \ubc29\ud5a5\uc73c\ub85c \uae34\uc7a5\uc744 \ub9cc\ub4e0 \ubc29\ubc95\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Art \ubb38\ud654 \uadf8\ub9bc \uc548\uc758 \uc0ac\ub78c\ub4e4\uc740 \uba3c \uacf3\uc744 \ud5a5\ud574 \uc190\uacfc \ucc9c\uc744 \ub4e4\uc5b4 \uc62c\ub9b0\ub2e4. \uadf8\ub7f0\ub370 \uadf8\ub4e4\uc774 \ubc14\ub77c\ubcf4\ub294 \ubc30\ub294 \ub180\ub784 \ub9cc\ud07c \uc791\ub2e4. \ubc14\ub85c \uc55e\uc5d0\ub294 \uc6c0\uc9c1\uc774\uc9c0 \uc54a\ub294 \ubab8\ub4e4\uc774 \uc788\uace0 \ubc14\ub2e4\ub294 \ubd88\uc548\ud558\ub2e4. \uc81c\ub9ac\ucf54\uc758 \u3008\uba54\ub450\uc0ac\ud638\uc758 \ub5cf\ubaa9\u3009\uc5d0\uc11c\ub294 \ud76c\ub9dd\uc774 \uac70\ub300\ud55c \uc601\uc6c5\uc758 \ubaa8\uc2b5\ubcf4\ub2e4 \uac70\uc758 \ub193\uce60 \ub9cc\ud55c \uc218\ud3c9\uc120\uc758 \uc810\uc73c\ub85c \ub098\ud0c0\ub09c\ub2e4. \uc2e4\uc81c \ub09c\ud30c \uc0ac\uac74\uc5d0\uc11c \ucd9c\ubc1c\ud55c \uc774 \uadf8\ub9bc\uc740 1819\ub144 \uc0b4\ub871\uc5d0\uc11c \ud070 \uc8fc\ubaa9\uc744 \ubc1b\uc558\ub2e4. \ud3b8\uc548\ud55c \ud48d\uacbd\ud654\ub294 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \uad34\ub85c\uc6b4 \uc7a5\uba74\uc744 \uc790\uc138\ud788 \uc124\uba85\ud558\uae30\ubcf4\ub2e4 \uc0ac\ub78c\ub4e4\uc758 \uc2dc\uc120\uacfc \ud654\uba74\uc758 \ubc29\ud5a5\uc744 \ub530\ub77c\uac00\uba74, \ud654\uac00\uac00 \uace0\ud1b5\uacfc \uae30\ub300\ub97c \uc5b4\ub5bb\uac8c \ud568\uaed8 \ubcf4\uc774\uac8c \ud588\ub294\uc9c0 \uc77d\uc744 \uc218 \uc788\ub2e4. \uc81c\ubaa9\uc758 \uba54\ub450\uc0ac\ub294 \uc2e0\ud654 \uc18d \uc778\ubb3c\uc774 \uc544\ub2c8\ub77c \ub09c\ud30c\ud55c \ubc30\uc758 \uc774\ub984\uc774\ub2e4. \uc0b4\uc544\ub0a8\uc740 \uc0ac\ub78c\ub4e4\uc774 \ub5cf\ubaa9\uc5d0 \ub9e4\ub2ec\ub824 \ubc14\ub2e4\ub97c \ub5a0\ub3c4\ub294 \uc0c1\ud669\uc774 \uadf8\ub9bc\uc758 \ubc14\ud0d5\uc774\ub2e4. \uc548\uc815\ub41c \ubc30\uc758 \uac11\ud310\ucc98\ub7fc \ubcf4\uc544\uc11c\ub294 \uc548 \ub418\ub294 \uc774\uc720\ub2e4. \uc778\ubb3c\ub4e4\uc774 \uc11c\uac70\ub098 \uae30\ub300\ub294 \ubc14\ub2e5 \uc790\uccb4\uac00 \ubd88\uc548\uc815\ud558\ub2e4. \ub113\uc740 \ubc14\ub2e4\uc5d0 \ube44\ud558\uba74 \uc0ac\ub78c\uc774 \ub51b\ub294 \uacf3\uc740 \uc881\ub2e4. \ubb34\ub300\uc758 \uac00\uc7a5\uc790\ub9ac\ucc98\ub7fc \ud654\uba74 \uc55e\ucabd\uc5d0 \uac78\ub9b0 \ub5cf\ubaa9\uc744 \ubcf4\uba74 \uad00\ub78c\uc790\uc640 \uc0ac\uac74\uc758 \uac70\ub9ac\ub3c4 \uac00\uae5d\uac8c \ub290\uaef4\uc9c4\ub2e4. \uba40\ub9ac\uc11c \ubc14\ub2e4\uc758 \uc544\ub984\ub2e4\uc6c0\uc744 \uac10\uc0c1\ud558\ub294 \uc2dc\uc810\ubcf4\ub2e4 \uc0ac\ub78c\ub4e4\uc758 \uc704\ud0dc\ub85c\uc6b4 \uc790\ub9ac \uac00\uae4c\uc774\uc5d0 \uc138\uc6cc\uc9c0\ub294 \ub290\ub08c\uc774\ub2e4. \uc544\ub798\ucabd\uc5d0\ub294 \ud798\uc5c6\uc774 \ub298\uc5b4\uc9c4 \uc778\ubb3c\ub4e4\uc774 \uc788\ub2e4. \uadf8 \uacc1\uc758 \uc0ac\ub78c\ub4e4\ub3c4 \uc11c\ub85c \ub2e4\ub978 \ubc29\ud5a5\uc73c\ub85c \ubab8\uc744 \uae30\ub300\uac70\ub098 \uace0\uac1c\ub97c \uc219\uc778\ub2e4. \ubaa8\ub450\uac00 \ud55c \uac00\uc9c0 \uac10\uc815\uc744 \uac19\uc740 \uc790\uc138\ub85c \ud45c\ud604\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc774\ubbf8 \uc9c0\uce5c \uc0ac\ub78c\uacfc \uc544\uc9c1 \ubc14\uae65\uc744 \ubc14\ub77c\ubcf4\ub294 \uc0ac\ub78c\uc774 \uac19\uc740 \ub5cf\ubaa9\uc5d0 \uc788\ub2e4. \uc774 \ucc28\uc774 \ub54c\ubb38\uc5d0 \uadf8\ub9bc\uc744 \uc808\ub9dd\uc774\ub77c\ub294 \ub2e8\uc5b4 \ud558\ub098\ub85c \ub05d\ub0b4\uae30 \uc5b4\ub835\ub2e4. \uc5b4\ub5a4 \uc778\ubb3c\uc5d0\uac8c\ub294 \ubab8\uc744 \ub4dc\ub294 \uc77c\uc870\ucc28 \uc5b4\ub824\uc6cc \ubcf4\uc774\uace0, \ub2e4\ub978 \uc778\ubb3c\uc5d0\uac8c\ub294 \uc190\uc744 \ub4e4\uc5b4 \uc2e0\ud638\ub97c \ubcf4\ub0b4\ub294 \uc77c\uc774 \ub9c8\uc9c0\ub9c9 \ud589\ub3d9\uc774 \ub41c\ub2e4. \uac10\uc815\uc740 \ud45c\uc815\ubfd0 \uc544\ub2c8\ub77c \ubab8\uc758 \ub192\uc774\uc640 \ud798\uc758 \ubc29\ud5a5\uc73c\ub85c \ub4dc\ub7ec\ub09c\ub2e4. \uc2dc\uc120\uc744 \uc624\ub978\ucabd \uc704\ub85c \uc62e\uae30\uba74 \ubab8\ub4e4\uc774 \uacb9\uccd0\uc9c0\uace0 \uc6c0\uc9c1\uc784\uc774 \ub192\uc544\uc9c4\ub2e4. \ub0ae\uac8c \ub193\uc778 \uc0ac\ub78c\ub4e4\uc5d0\uc11c \ubb34\uc5b8\uac00\ub97c \uac00\ub9ac\ud0a4\ub294 \uc0ac\ub78c\uc744 \uc9c0\ub098, \uac00\uc7a5 \ub192\uc740 \uc790\ub9ac\uc5d0\uc11c \ucc9c\uc744 \ud754\ub4dc\ub294 \uc778\ubb3c \ucabd\uc73c\ub85c \uc62c\ub77c\uac04\ub2e4. \uc5ec\ub7ec \uc0ac\ub78c\uc774 \ud558\ub098\uc758 \ud070 \ubc29\ud5a5\uc744 \ub9cc\ub4dc\ub294 \uc148\uc774\ub2e4. \uac1c\uac1c\uc778\uc758 \ud574\ubd80\ud559\uc801 \uc790\uc138\ub97c \ubd84\uc11d\ud558\uc9c0 \uc54a\uc544\ub3c4 \uc774 \ud750\ub984\uc740 \ubcf4\uc778\ub2e4. \ud654\uba74\uc758 \uc5b4\ub514\uac00 \ub0ae\uace0 \uc5b4\ub514\uac00 \ub192\uc544\uc9c0\ub294\uc9c0, \ud314\uc774 \uc5b4\ub290 \ucabd\uc73c\ub85c \ubed7\ub294\uc9c0\ub9cc \ub530\ub77c\uac00\ub3c4 \ub41c\ub2e4. \uadf8\ub9bc\uc740 \ub9ce\uc740 \uc778\ubb3c\uc744 \ubb34\uc791\uc815 \ubaa8\uc544 \ub193\uc740 \uac83\uc774 \uc544\ub2c8\ub77c \uc6b0\ub9ac\uc758 \ub208\uc774 \uc9c0\ub098\uac08 \uae38\uc744 \uc870\uc9c1\ud558\uace0 \uc788\ub2e4. \uc778\ubb3c\ub4e4\uc758 \uc6c0\uc9c1\uc784\uc744 \ub530\ub77c \ub05d\uae4c\uc9c0 \uac00\uba74 \uc218\ud3c9\uc120 \uadfc\ucc98\uc758 \uc791\uc740 \uad6c\uc870\uc120\uc774 \ubcf4\uc778\ub2e4. \uc0ac\ub78c\uc774 \uc544\ubb34\ub9ac \ud06c\uac8c \ubab8\uc9d3\ud574\ub3c4 \uba3c \ubc30\uc5d0\uc11c \uc54c\uc544\ubcfc \uc218 \uc788\uc744\uc9c0\ub294 \uc54c \uc218 \uc5c6\ub2e4. \ud76c\ub9dd\uc758 \ub300\uc0c1\uc774 \uc791\uace0 \uba40\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc2e0\ud638\ub97c \ubcf4\ub0b4\ub294 \uc0ac\ub78c\ub4e4\uc758 \uc808\ubc15\ud568\uc744 \ub354 \ud06c\uac8c \ub9cc\ub4e0\ub2e4. \ubc30\uac00 \ub208\uc55e\uc5d0\uc11c \ud655\uc2e4\ud558\uac8c \ub2e4\uac00\uc624\ub294 \uc7a5\uba74\uc774\uc5c8\ub2e4\uba74 \uadf8\ub9bc\uc758 \uae34\uc7a5\uc740 \ub2ec\ub790\uc744 \uac83\uc774\ub2e4. \uc5ec\uae30\uc11c\ub294 \uad6c\uc870\ub420 \uac00\ub2a5\uc131\uacfc \ub193\uce60 \uac00\ub2a5\uc131\uc774 \ud568\uaed8 \ub0a8\uc544 \uc788\ub2e4. \uc0ac\uac74\uc758 \ubaa8\ub4e0 \uacb0\uacfc\ub97c \ud55c \uc7a5\uba74\uc5d0 \ud3bc\uce58\uae30\ubcf4\ub2e4 \uc5b4\ub290 \uc21c\uac04\uc744 \uba48\ucd94\uc5b4 \ub193\uc744\uc9c0\uac00 \uadf8\ub9bc\uc758 \ud798\uacfc \uc5f0\uacb0\ub41c\ub2e4\ub294 \uac83\uc744 \ubcfc \uc218 \uc788\ub2e4. \uc67c\ucabd\uc758 \ub3db\uacfc \uc904, \uc5b4\ub450\uc6b4 \ud558\ub298\uacfc \ud30c\ub3c4\ub3c4 \ud654\uba74\uc758 \uc6c0\uc9c1\uc784\uc5d0 \ucc38\uc5ec\ud55c\ub2e4. \uc0ac\ub78c\ub4e4\uc758 \ubab8\uc774 \uad6c\uc870\uc120 \ucabd\uc73c\ub85c \ud5a5\ud558\ub354\ub77c\ub3c4 \uadf8 \ubc14\ub78c\uc774 \uace7 \uc548\uc815\ub41c \uc774\ub3d9\uc744 \ubcf4\uc7a5\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc790\uc5f0\uc740 \uc778\ubb3c\uc758 \uae30\ub300\uc5d0 \ub9de\ucdb0 \ud3b8\uc548\ud55c \ubc30\uacbd\uc774 \ub418\uc5b4 \uc8fc\uc9c0 \uc54a\ub294\ub2e4. \ubc1d\uc740 \ubd80\ubd84\uacfc \uc5b4\ub450\uc6b4 \ubd80\ubd84\uc758 \ub300\ube44\ub3c4 \uc0b4\ud3b4\ubcf4\uc790. \uc778\ubb3c\uc758 \ubab8\uc774 \ub4dc\ub7ec\ub098\ub294 \uacf3\uacfc \uadf8\ub9bc\uc790\uac00 \ubb49\uce58\ub294 \uacf3\uc744 \uc624\uac00\uba74 \uc2dc\uc120\uc774 \ud55c\uacf3\uc5d0\ub9cc \uace0\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4. \ubc14\ub2e4\uac00 \ub113\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc0ac\ub78c\uc774 \uac00\uae4c\uc774 \uc788\ub2e4\ub294 \ub290\ub08c\uc774 \ud568\uaed8 \uc0dd\uae34\ub2e4. \ubc30\uacbd\uc758 \ub0a0\uc528\ub3c4 \uc0ac\uac74\uc758 \uc555\ub825\uc73c\ub85c \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \uc774 \uc791\ud488\uc740 \uc2e4\uc81c \ub09c\ud30c\uc758 \uace0\ud1b5\uc5d0\uc11c \ucd9c\ubc1c\ud588\uc9c0\ub9cc \uc0ac\uac74\uc744 \ucd2c\uc601\ud55c \uc0ac\uc9c4\uc740 \uc544\ub2c8\ub2e4. \ud654\uac00\ub294 \uc0ac\ub78c\uacfc \ube5b, \ub3d9\uc791\uc744 \uc120\ud0dd\ud558\uace0 \uad6c\uc131\ud588\ub2e4. \uc2e4\uc81c \uc77c\uc774 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ub208\uc55e\uc758 \ubaa8\ub4e0 \uc138\ubd80\uac00 \uadf8 \uc21c\uac04 \uadf8\ub300\ub85c\ub77c\ub294 \uc8fc\uc7a5\uc740 \ub2e4\ub974\ub2e4. \uc624\ub798\ub41c \ub3c4\ub85d\uc5d0\ub294 \uc778\ubb3c\ub4e4\uc744 \ud2b9\uc815 \uc0dd\uc874\uc790\uc640 \uc5f0\uacb0\ud558\ub294 \uc124\uba85\ub3c4 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc774 \uae00\uc5d0\uc11c\ub294 \ud654\uba74\uc5d0\uc11c \uc9c1\uc811 \ubcfc \uc218 \uc788\ub294 \uad00\uacc4\uc640 \ud655\uc778\ud55c \ud070 \ubc30\uacbd\uc744 \uc911\uc2ec\uc73c\ub85c \uc77d\ub294\ub2e4. \uc0ac\uac74\uc758 \ucc38\uac00\uc790 \uc218\ub098 \ucc45\uc784 \ubb38\uc81c \uc804\uccb4\ub97c \uc774 \ud55c \uadf8\ub9bc\uc758 \ubaa8\uc2b5\ub9cc\uc73c\ub85c \ud655\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc5ed\uc0ac \uc790\ub8cc\uc640 \ud68c\ud654\uc758 \ud45c\ud604\uc740 \uc11c\ub85c \ub300\uc870\ud560 \ud544\uc694\uac00 \uc788\ub2e4. \uc791\ud488\uc740 \uc138\ub85c \uc57d 5\ubbf8\ud130, \uac00\ub85c \uc57d 7\ubbf8\ud130\uc5d0 \uc774\ub974\ub294 \uac70\ub300\ud55c \uce94\ubc84\uc2a4\ub2e4. \ud654\uba74\uc5d0\uc11c \uc791\uac8c \ubcfc \ub54c\uc640 \uc2e4\uc81c \ud06c\uae30 \uc55e\uc5d0 \uc130\uc744 \ub54c\uc758 \uacbd\ud5d8\uc774 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uc0dd\uc874\uc744 \uae30\ub2e4\ub9ac\ub294 \uc0ac\ub78c\ub4e4\uc758 \ubab8\uc774 \ub2e8\uc21c\ud55c \uc791\uc740 \uc0bd\ud654 \uc18d \uc778\ubb3c\ub85c\ub9cc \ubcf4\uc774\uc9c0 \uc54a\ub294 \uaddc\ubaa8\ub2e4. \uc61b \ub3c4\ub85d\uc740 \uc774 \uc791\ud488\uc744 \ub0ad\ub9cc\uc8fc\uc758 \ud68c\ud654\uc758 \uc911\uc694\ud55c \ubcc0\ud654\uc640 \uc5f0\uacb0\ud55c\ub2e4. \uc591\uc2dd \uc774\ub984\uc744 \uc678\uc6b0\uae30\ubcf4\ub2e4 \ubb34\uc5c7\uc774 \uc804\uba74\uc73c\ub85c \ub098\uc654\ub294\uc9c0 \ubcf4\uba74 \ub41c\ub2e4. \uc815\ub3c8\ub41c \uc704\uc5c4\ubcf4\ub2e4 \ud754\ub4e4\ub9ac\ub294 \ubab8\uacfc \uaca9\ud55c \uac10\uc815, \ud604\uc2e4\uc758 \uace0\ud1b5\uc774 \ud070 \ud654\uba74\uc744 \ucc28\uc9c0\ud55c\ub2e4. \ubbf8\uc220\uc758 \uc911\uc694\ud55c \uc8fc\uc81c\uac00 \ubb34\uc5c7\uc77c \uc218 \uc788\ub294\uc9c0 \ubb3b\ub294 \uadf8\ub9bc\uc774\uae30\ub3c4 \ud558\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uba3c \ubc30\uac00 \uc5b4\ub514\uc5d0 \uc788\ub294\uc9c0 \ucc3e\uc544\ubcf4\uace0, \ub2e4\uc74c\uc5d0\ub294 \uadf8 \ubc30\ub97c \ud5a5\ud55c \ubab8\uc9d3\uc774 \uc5b4\ub514\uc5d0\uc11c \uc2dc\uc791\ub418\ub294\uc9c0 \uac70\uafb8\ub85c \ub530\ub77c\uac00 \ubcf4\uc790. \uc791\ud488\uc758 \uc758\ubbf8\ub97c \uc228\uc740 \ubb3c\uac74 \ud558\ub098\uc758 \uc815\ub2f5\uc73c\ub85c \ud478\ub294 \ub300\uc2e0 \ud654\uba74 \uc548\uc758 \uac70\ub9ac\uc640 \ubc29\ud5a5\uc744 \uc77d\ub294 \ubc29\ubc95\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \uc61b \ub8e8\ube0c\ub974 \ub3c4\ub85d\uc758 \uc2e4\uc81c \uc791\ud488 \uc7ac\ud604 \ub3c4\ud310\uc774\ub2e4. \uace0\ud1b5\uc758 \uc7a5\uba74\uc744 \uc0c8\ub85c \ub9cc\ub4e4\uc5b4 \ub0b8 AI \uc0bd\ud654\uac00 \uc544\ub2c8\ub2e4. \uc791\uc740 \ubc30\ub97c \ud5a5\ud574 \uc62c\ub77c\uac00\ub294 \uc2dc\uc120\uacfc \uc55e\ucabd\uc5d0 \ub0a8\uc740 \ubb34\uac8c\ub97c \ud568\uaed8 \ubcf4\uba74, \ud76c\ub9dd\uacfc \uc808\ub9dd\uc774 \uc5b4\ub5bb\uac8c \uac19\uc740 \uc21c\uac04\uc5d0 \uc874\uc7ac\ud558\ub294\uc9c0 \ub290\ub084 \uc218 \uc788\ub2e4."}, {"id": "glass-photo-pillow-ruler", "title": "\uc61b \ubca0\uac1c \uc0ac\uc9c4 \uc606\uc5d0\ub294 \uc65c \uc790\uac00 \uc11c \uc788\uc744\uae4c", "summary": "\uc720\ub9ac\uac74\ud310\uc5d0 \ub0a8\uc740 \ubca0\uac1c \uc0ac\uc9c4\uc5d0\uc11c \ub208\uae08\uc790\uc640 \ubc88\ud638\ub97c \ubc1c\uacac\ud569\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Art", "url": "stories/glass-photo-pillow-ruler/index.html", "image": "media/glass-photo-pillow-ruler.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \ubc31\uc790\ubca0\uac1c \uc720\ub9ac\uac74\ud310 \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc61b \ubca0\uac1c \uc0ac\uc9c4 \uc606\uc5d0\ub294 \uc65c \uc790\uac00 \uc11c \uc788\uc744\uae4c \uc8fc\uc778\uacf5\ub9cc\ud07c \uc911\uc694\ud55c \uc0ac\uc9c4 \uc18d \uc870\uc5f0 \uc720\ub9ac\uac74\ud310\uc5d0 \ub0a8\uc740 \ubca0\uac1c \uc0ac\uc9c4\uc5d0\uc11c \ub208\uae08\uc790\uc640 \ubc88\ud638\ub97c \ubc1c\uacac\ud569\ub2c8\ub2e4. Art \ubb38\ud654 \uc624\ub798\ub41c \ud751\ubc31 \uc0ac\uc9c4 \ud55c \uc7a5\uc744 \ubcf4\uc790. \uac00\uc6b4\ub370\uc5d0\ub294 \ubca0\uac1c\uac00 \ub193\uc5ec \uc788\uace0 \uc624\ub978\ucabd\uc5d0\ub294 \uae34 \ub9c9\ub300\uac00 \uc11c \uc788\ub2e4. \uae30\ub150\uc0ac\uc9c4\uc774\ub77c\uba74 \uce58\uc6cc \ub450\uc5c8\uc744 \uac83 \uac19\uc740 \ubb3c\uac74\uc778\ub370, \uc774 \uc0ac\uc9c4\uc5d0\uc11c\ub294 \ud568\uaed8 \ub0a8\uc544 \uc788\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc18c\uc7a5\ud55c \ubc31\uc790\ubca0\uac1c \uc720\ub9ac\uac74\ud310\uc774\ub2e4. \uc774 \uc790\ub8cc\uc5d0\uc11c \ubc15\ubb3c\uad00\uc774 \uc18c\uc7a5\ud55c \uac83\uc740 \uc0ac\uc9c4\uc744 \ub2f4\uc740 \uc720\ub9ac\uac74\ud310\uc774\uba70, \uc0ac\uc9c4 \uc18d \ubca0\uac1c \uc790\uccb4\uc640\ub294 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ud55c \uc7a5\uc758 \uc0ac\uc9c4\uc5d0\ub3c4 \uc11c\ub85c \ub2e4\ub978 \ubb3c\uac74\uc758 \uc774\ub825\uc774 \uacb9\uce5c\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc740 \uc624\ub978\ucabd \ub9c9\ub300\ub97c \ud06c\uae30 \uce21\uc815\uc6a9 \uc790\ub77c\uace0 \uc54c\ub824 \uc900\ub2e4. \uc0ac\uc9c4\ub9cc \ubcf4\uba74 \ubca0\uac1c\uac00 \uc190\ubc14\ub2e5\ub9cc \ud55c\uc9c0, \ud6e8\uc52c \ud070\uc9c0 \uac00\ub2a0\ud558\uae30 \uc5b4\ub835\ub2e4. \uacc1\uc5d0 \uc120 \uc790\ub294 \uadf8 \ud310\ub2e8\uc744 \ub3d5\ub294 \uc5ed\ud560\uc744 \ud55c\ub2e4. \uc624\ub298 \uc911\uace0 \ubb3c\ud488 \uc0ac\uc9c4\uc5d0 \ub3d9\uc804\uc774\ub098 \uc790\ub97c \ud568\uaed8 \ub193\ub294 \uc77c\uc744 \ub5a0\uc62c\ub824\ub3c4 \uc88b\ub2e4. \uc0ac\uc9c4\uc740 \ubaa8\uc591\uc744 \ubcf4\uc5ec \uc8fc\ub294 \ub370 \ub2a5\ud558\uc9c0\ub9cc \ud06c\uae30\ub97c \uc800\uc808\ub85c \uc124\uba85\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc624\ub798\ub41c \ucd2c\uc601\uc5d0\ub3c4 \uadf8 \ube48\ud2c8\uc744 \ucc44\uc6b8 \ub3c4\uad6c\uac00 \ud544\uc694\ud588\ub358 \uac83\uc774\ub2e4. \uc0ac\uc9c4 \uc18d \uc624\ub978\ucabd\uc5d0\ub294 \ucd2c\uc601 \ub2f9\uc2dc \ubc88\ud638 6014\ub3c4 \ub0a8\uc544 \uc788\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc0ac\uc9c4 \uc18d \ubca0\uac1c\uac00 \uc911\uad6d \ub3c4\uc790\uc774\uba70 \ud604\uc7ac \uad6d\ub9bd\uc911\uc559\ubc15\ubb3c\uad00\uc758 \ub355\uc2182165\ub85c \uc18c\uc7a5\ub418\uc5b4 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ucd2c\uc601 \ubc88\ud638\uc640 \uc9c0\uae08\uc758 \uc18c\uc7a5\ud488 \ubc88\ud638\ub294 \uac19\uc740 \uac83\uc774 \uc544\ub2c8\ub2e4. \uadf8\ub798\uc11c \uc22b\uc790\uac00 \ub2e4\ub974\ub2e4\uace0 \uc0ac\uc9c4\uc774 \uc798\ubabb\ub418\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5b4\ub290 \uc22b\uc790\uac00 \uc0ac\uc9c4\uc744 \uc704\ud55c \uae30\ub85d\uc774\uace0 \uc5b4\ub290 \uc22b\uc790\uac00 \ubb3c\uac74\uc744 \ucc3e\ub294 \ud45c\uc9c0\uc778\uc9c0 \ub098\ub204\uc5b4 \ubcf4\uba74 \ud55c\uacb0 \uc774\ud574\ud558\uae30 \uc27d\ub2e4. \uc774 \uc18c\uc7a5\ud488\uc5d0\uc11c \uba3c\uc800 \uad6c\ubcc4\ud560 \uac83\uc740 \ucd2c\uc601 \ub300\uc0c1\uacfc \uc0ac\uc9c4\uc744 \ub0a8\uae34 \ub9e4\uccb4\ub2e4. \ubc31\uc790\ubca0\uac1c\ub294 \uce74\uba54\ub77c \uc55e\uc5d0 \ub193\uc778 \ubb3c\uac74\uc774\uace0, \uc720\ub9ac\uac74\ud310\uc740 \uadf8 \ubaa8\uc2b5\uc744 \ub2f4\uc740 \uc0ac\uc9c4 \uc790\ub8cc\ub2e4. \ud654\uba74\uc5d0\uc11c \ud55c \ubc88\uc5d0 \ub9cc\ub098\uae30 \ub54c\ubb38\uc5d0 \ub458\uc744 \uac19\uc740 \uc18c\uc7a5\ud488\uc73c\ub85c \uc0dd\uac01\ud558\uae30 \uc27d\uc9c0\ub9cc \uac01\uac01\uc758 \uc774\ub825\uacfc \uc9c8\ubb38\uc774 \uc788\ub2e4. \ub3c4\uc790\uc758 \ud604\uc7ac \uc18c\uc7a5\ucc98\uc640 \uc0ac\uc9c4\uc758 \ubcf4\uad00\ucc98\ub97c \ub530\ub85c \uc77d\uc5b4\uc57c \ud558\ub294 \uc774\uc720\ub2e4. \ub3c4\uc790\ub9cc \ubcf4\uba74 \ud615\ud0dc\uc640 \uc81c\uc791, \uc0ac\uc6a9\uc744 \ubb3b\uac8c \ub41c\ub2e4. \uac74\ud310\uc744 \ubcf4\uba74 \uc5b4\ub5a4 \uac01\ub3c4\uc5d0\uc11c \ubb34\uc5c7\uacfc \ud568\uaed8 \ucc0d\uc5c8\uace0 \uc5b4\ub5bb\uac8c \uc2dd\ubcc4\ud588\ub294\uc9c0\ub3c4 \ubb3b\uac8c \ub41c\ub2e4. \uac19\uc740 \uc774\ubbf8\uc9c0 \uc548\uc5d0 \ubb3c\uac74\uc758 \uc5ed\uc0ac\uc640 \uae30\ub85d\ud558\ub294 \ud589\uc704\uc758 \uc5ed\uc0ac\uac00 \uacb9\uce5c\ub2e4. \uc5f0\uad6c\ub97c \ub3d5\uae30 \uc704\ud574 \ub9cc\ub4e0 \uc0ac\uc9c4\uc774 \ub098\uc911\uc5d0\ub294 \uadf8 \uc5f0\uad6c \ubc29\uc2dd \uc790\uccb4\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uc790\ub8cc\uac00 \ub418\ub294 \uc148\uc774\ub2e4. \uc0ac\uc9c4 \uc18d \uce21\uc815\uc6a9 \uc790\ub294 \ud06c\uae30\ub97c \ucd94\uc815\ud560 \uae30\uc900\uc744 \uc900\ub2e4. \uc0ac\uc9c4\uc744 \ud655\ub300\ud574\uc11c \ubcf4\ub294 \uc815\ub3c4\uac00 \ub2ec\ub77c\uc838\ub3c4 \ub300\uc0c1 \uc606\uc758 \uae30\uc900\uc774 \ud568\uaed8 \ubcf4\uc774\uba74 \ube44\ub840\ub97c \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \ud654\uba74\uc758 \uc778\uc1c4 \ud06c\uae30\ub098 \ud734\ub300\uc804\ud654\uc758 \ud06c\uae30\uac00 \uace7 \uc720\ubb3c\uc758 \uc2e4\uc81c \ud06c\uae30\ub77c\uace0 \ucc29\uac01\ud558\ub294 \uc77c\uc744 \uc904\uc5ec \uc900\ub2e4. \ub300\uc0c1\uacfc \ud568\uaed8 \ub2e4\ub978 \ubb3c\uac74\uc744 \ub193\ub294 \uc120\ud0dd\uc5d0\ub294 \uc774\ub7f0 \uc815\ubcf4\uc758 \ubaa9\uc801\uc774 \uc788\ub2e4. \uadf8\ub807\uc9c0\ub9cc \uc790\uac00 \ubcf4\uc778\ub2e4\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \uc0ac\uc9c4\uc758 \uc5b4\ub290 \uce58\uc218\ub4e0 \uc815\ud655\ud558\uac8c \uc7ac\uc5b4 \ub0bc \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub300\uc0c1\uacfc \uc790\uc758 \ubc29\ud5a5, \ucd2c\uc601 \uac01\ub3c4\uc5d0 \ub530\ub77c \ubcf4\uc774\ub294 \uad00\uacc4\uac00 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 \uc0ac\uc9c4\ub9cc\uc73c\ub85c \uc0c8 \uc2e4\uce21\uac12\uc744 \uacc4\uc0b0\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc5b4\ub5a4 \uc815\ubcf4\ub97c \ub0a8\uae30\ub824\uace0 \uc774\ub7f0 \ucd2c\uc601\uc744 \ud588\ub294\uc9c0 \uc77d\ub294 \ub370 \ucd08\uc810\uc744 \ub9de\ucd98\ub2e4. \uae30\ub85d\uc774 \uce5c\uc808\ud55c \uacf3\uacfc \uc5ec\uc804\ud788 \ud655\uc778\uc774 \ud544\uc694\ud55c \uacf3\uc744 \ub098\ub204\uc5b4 \ubcfc \uc218 \uc788\ub2e4. 6014\ub294 \ucd2c\uc601 \uc790\ub8cc\uc640 \uad00\uacc4\ub41c \ubc88\ud638\uc774\uace0 \ub355\uc2182165\ub294 \ud604\uc7ac \ub3c4\uc790\ub97c \uc2dd\ubcc4\ud558\ub294 \uc18c\uc7a5 \ubc88\ud638\ub2e4. \uc22b\uc790\uac00 \ub2e4\ub974\ub2e4\uace0 \uc5b4\ub290 \ud55c\ucabd\uc744 \ud2c0\ub9b0 \uac83\uc73c\ub85c \uace0\uce60 \ud544\uc694\ub294 \uc5c6\ub2e4. \uac01\uac01 \ubb34\uc5c7\uc744 \uad00\ub9ac\ud558\ub294 \uccb4\uacc4\uc778\uc9c0 \uba3c\uc800 \uc54c\uc544\uc57c \ud55c\ub2e4. \ubb3c\uac74\uacfc \uc0ac\uc9c4, \uae30\uc99d\uacfc \ubcf4\uad00\uc774 \uc11c\ub85c \ub2e4\ub978 \uae30\ub85d\uc744 \ub9cc\ub4e4 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uc774\ub7f0 \ubc88\ud638\ub4e4\uc744 \uc5f0\uacb0\ud574 \ub193\uc73c\uba74 \uacfc\uac70\uc758 \uc0ac\uc9c4 \uc18d \ubb3c\uac74\uc744 \uc624\ub298\uc758 \uc18c\uc7a5\ud488\uacfc \ub300\uc870\ud560 \uae38\uc774 \uc0dd\uae34\ub2e4. \uc0ac\uc9c4\uc774 \ub2ee\uc558\ub2e4\ub294 \uc778\uc0c1\ub9cc\uc73c\ub85c \ud655\uc778\ud558\ub294 \uac83\ubcf4\ub2e4 \uc815\ubcf4\uac00 \ub354\ud574\uc9c0\ub294 \uac83\uc774\ub2e4. \uc790\ub8cc\ub97c \uc815\ub9ac\ud558\ub294 \uc791\uc740 \ud45c\uc9c0\uac00 \uc0ac\ub78c\uacfc \uc2dc\ub300\uac00 \ub2ec\ub77c\uc838\ub3c4 \uac19\uc740 \ub300\uc0c1\uc744 \ub2e4\uc2dc \ucc3e\ub3c4\ub85d \ub3d5\ub294\ub2e4. \ubc88\ud638\uac00 \uc9c0\ub8e8\ud55c \ubd80\ub85d\ucc98\ub7fc \ubcf4\uc5ec\ub3c4 \ubb3c\uac74\uc758 \uc774\ub3d9\uc744 \uc787\ub294 \uc911\uc694\ud55c \ub3c4\uad6c\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc740 \uc0ac\uc9c4 \uc18d \ubca0\uac1c \uc717\ubd80\ubd84\uc758 \ud30c\uc190\uacfc \uc218\ub9ac \ud754\uc801\ub3c4 \uc9da\ub294\ub2e4. \ub9e4\ub048\ud55c \uc644\uc131\ud488\ub9cc \uae30\ub300\ud558\uba74 \uc9c0\ub098\uce60 \uc218 \uc788\uc9c0\ub9cc, \ub0a8\uc740 \uc0c1\ud0dc\ub294 \uc0ac\uc6a9\uacfc \uc190\uc0c1\uc744 \uac70\uce5c \ubb3c\uac74\uc758 \uc2dc\uac04\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ub2e4\ub9cc \uc774 \uc0ac\uc9c4 \ud558\ub098\ub85c \uc5b8\uc81c \uc5b4\ub5a4 \uc0ac\uace0\uac00 \uc788\uc5c8\uace0 \ub204\uac00 \uace0\ucce4\ub294\uc9c0\uae4c\uc9c0 \uc7ac\uad6c\uc131\ud560 \uc218\ub294 \uc5c6\ub2e4. \ud655\uc778\ub418\ub294 \ud754\uc801\uacfc \uadf8 \uc6d0\uc778\uc758 \uc774\uc57c\uae30\ub294 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \uc0ac\uc9c4\uc744 \ub2e4\uc2dc \ubcfc \ub54c\uc5d0\ub294 \uac00\uc6b4\ub370 \ub3c4\uc790\uc5d0\uc11c \uac00\uc7a5\uc790\ub9ac\uc758 \uc790\uc640 \ubc88\ud638\ub85c \ub208\uc744 \uc62e\uaca8 \ubcf4\uc790. \uc720\ubb3c\uc744 \uc798 \ubcf4\uc774\uac8c \ud558\ub824 \ub9c8\ub828\ud55c \uc8fc\ubcc0 \uc815\ubcf4\uac00 \ud568\uaed8 \ub4dc\ub7ec\ub09c\ub2e4. \ub3c4\uc790\ub294 \uadf8 \uc2dc\ub300\uc758 \ubb3c\uac74\uc774\uace0, \uc0ac\uc9c4\uc740 \ub204\uad70\uac00 \uadf8 \ubb3c\uac74\uc744 \uc54c\uc544\ubcf4\uace0 \uae30\ub85d\ud55c \uacb0\uacfc\ub2e4. \uc624\ub798\ub41c \ubca0\uac1c \ud55c \uc7a5\uba74\uc5d0\uc11c \ubcf4\uc874\ud558\ub294 \uc0ac\ub78c\uc758 \uc2dc\uc120\uae4c\uc9c0 \ub9cc\ub0a0 \uc218 \uc788\ub2e4. \uc124\uba85\uc5d0\ub294 \ubca0\uac1c\uc758 \ud30c\uc190\ub41c \uc717\ubd80\ubd84\uc774 \uc218\ub9ac\ub418\uc5c8\ub2e4\ub294 \ub0b4\uc6a9\ub3c4 \uc788\ub2e4. \uc644\ubcbd\ud55c \uc678\ud615\ub9cc \uae30\ub85d\ud55c \uac83\uc774 \uc544\ub2c8\ub77c, \uadf8\ub54c \ub0a8\uc544 \uc788\ub358 \uc0c1\ud0dc \uc5ed\uc2dc \uc0ac\uc9c4\uacfc \uc124\uba85 \uc548\uc5d0 \ub4e4\uc5b4 \uc788\ub294 \uc148\uc774\ub2e4. \uc774 \uc0ac\uc9c4\uc744 \ubcfc \ub54c \ubca0\uac1c \ubb34\ub2ac\ub97c \ubaa8\ub450 \uc77d\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc606\uc758 \uc790\uc640 \ubc88\ud638\ubd80\ud130 \ucc3e\uc544\ubcf4\uc790. \ubb3c\uac74\uc744 \uc544\ub984\ub2f5\uac8c \ubcf4\uc5ec \uc8fc\ub294 \uc0ac\uc9c4\uacfc \ubb3c\uac74\uc744 \uc815\ud655\ud558\uac8c \ub0a8\uae30\ub294 \uc0ac\uc9c4\uc774 \uc5b4\ub5a4 \uc810\uc5d0\uc11c \ub2e4\ub978\uc9c0, \uc791\uc740 \uc870\uc5f0\ub4e4\uc774 \uc870\uc6a9\ud788 \uc54c\ub824 \uc900\ub2e4."}, {"id": "goldberg-variations-return", "title": "\uace8\ub4dc\ubca0\ub974\ud06c \ubcc0\uc8fc\uace1 \u2014 \uac19\uc740 \uc74c\uc545\uc774 \ub3cc\uc544\uc640\ub3c4 \ub2e4\ub974\uac8c \ub4e4\ub9ac\ub294 \uc774\uc720", "summary": "\uace1\uc758 \uc774\ub984\uc5d0 \uc5bd\ud78c \uc804\uc2b9\uc744 \uad6c\ubd84\ud558\uace0, \ubc18\ubcf5\uacfc \ubcc0\ud615\uc744 \ub530\ub77c \ubc14\ud750\uc758 \uae34 \uc791\ud488\uc744 \ub4e3\uc2b5\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Music", "url": "stories/goldberg-variations-return/index.html", "image": "media/goldberg-variations-return.jpg", "alt": "\ud558\uc6b0\uc2a4\ub9cc\uc774 \uadf8\ub9b0 \uc694\ud55c \uc81c\ubc14\uc2a4\ud2f0\uc548 \ubc14\ud750 \ucd08\uc0c1\uc758 \uc61b \uc7ac\ud604 \ub3c4\ud310. \ubc14\ud750\uac00 \uc545\ubcf4\ub97c \ub4e4\uace0 \uc788\uc2b5\ub2c8\ub2e4.", "text": "\uace8\ub4dc\ubca0\ub974\ud06c \ubcc0\uc8fc\uace1 \u2014 \uac19\uc740 \uc74c\uc545\uc774 \ub3cc\uc544\uc640\ub3c4 \ub2e4\ub974\uac8c \ub4e4\ub9ac\ub294 \uc774\uc720 \uc544\ub9ac\uc544\uc640 \uc11c\ub978 \uac1c\uc758 \ubcc0\uc8fc, \uc7a0 \ubabb \ub4dc\ub294 \ubc31\uc791\uc758 \uc774\uc57c\uae30\ub97c \ub118\uc5b4\uc11c \uace1\uc758 \uc774\ub984\uc5d0 \uc5bd\ud78c \uc804\uc2b9\uc744 \uad6c\ubd84\ud558\uace0, \ubc18\ubcf5\uacfc \ubcc0\ud615\uc744 \ub530\ub77c \ubc14\ud750\uc758 \uae34 \uc791\ud488\uc744 \ub4e3\uc2b5\ub2c8\ub2e4. Music \ubb38\ud654 \uc870\uc6a9\ud55c \uc544\ub9ac\uc544\uac00 \ub05d\ub09c \ub4a4 \uc74c\uc545\uc774 \uc5ec\ub7ec \ubaa8\uc2b5\uc73c\ub85c \ubc14\ub010\ub2e4. \uc5b4\ub5a4 \ubd80\ubd84\uc740 \uacbd\ucf8c\ud558\uace0 \uc5b4\ub5a4 \ubd80\ubd84\uc740 \ucd18\ucd18\ud558\uba70, \uc5b4\ub290 \uc21c\uac04\uc5d0\ub294 \uc2dc\uac04\uc774 \uae4a\uac8c \uac00\ub77c\uc549\ub294 \ub4ef\ud558\ub2e4. \uae34 \uae38\uc744 \uc9c0\ub09c \ub4a4 \ucc98\uc74c\uc758 \uc544\ub9ac\uc544\uac00 \ub2e4\uc2dc \ub098\uc628\ub2e4. \uac19\uc740 \uc74c\uc545\uc778\ub370 \ucc98\uc74c \ub4e4\uc744 \ub54c\uc640 \uac19\uc9c0 \uc54a\uac8c \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \ubc14\ud750\uc758 \u300a\uace8\ub4dc\ubca0\ub974\ud06c \ubcc0\uc8fc\uace1\u300b\uc740 \uadf8 \uacbd\ud5d8\uc744 \ub9cc\ub4dc\ub294 \uc791\ud488\uc774\ub2e4. \uc720\uba85\ud55c \uc774\ub984\uc758 \uc0ac\uc5f0\ub3c4 \ud765\ubbf8\ub86d\uc9c0\ub9cc, \ub4e3\ub294 \uc0ac\ub78c\uc5d0\uac8c \ub354 \uc624\ub798 \ub0a8\ub294 \uac83\uc740 \uac19\uc740 \ubc14\ud0d5\uc5d0\uc11c \uc5bc\ub9c8\ub098 \ub2e4\ub978 \uc138\uacc4\uac00 \ub098\uc62c \uc218 \uc788\ub290\ub0d0\ub294 \ub180\ub77c\uc6c0\uc774\ub2e4. \ud3ec\ub974\ucf08\uc774 1802\ub144\uc5d0 \uc4f4 \ubc14\ud750 \uc804\uae30\uc5d0\ub294 \ud55c \ubc31\uc791\uc758 \ubd88\uba74\uc5d0 \uad00\ud55c \uc774\uc57c\uae30\uac00 \ub098\uc628\ub2e4. \uc7a0 \ubabb \ub4dc\ub294 \ubc24\uc5d0 \uc74c\uc545\uc744 \ub4e3\ub358 \ubc31\uc791\uc774 \uace8\ub4dc\ubca0\ub974\ud06c\uc5d0\uac8c \uc5f0\uc8fc\ud560 \uace1\uc744 \ubc14\ud750\uc5d0\uac8c \ubd80\ud0c1\ud588\uace0, \uc774 \ubcc0\uc8fc\uace1\uc774 \ub9cc\ub4e4\uc5b4\uc84c\ub2e4\ub294 \uc804\uc2b9\uc774\ub2e4. \ud070 \ubcf4\uc0c1\uc744 \uc8fc\uc5c8\ub2e4\ub294 \uc77c\ud654\uae4c\uc9c0 \ub4a4\ub530\ub978\ub2e4. \ub2e4\ub9cc \uc774 \uc804\uae30\ub294 \uc791\ud488\uc758 \ud0c4\uc0dd\uc744 \uadf8 \uc790\ub9ac\uc5d0\uc11c \uae30\ub85d\ud55c \ub3d9\uc2dc\ub300 \uc77c\uc9c0\uac00 \uc544\ub2c8\ub2e4. \uc624\ub298\uc758 \ub300\uc870 \uc790\ub8cc\ub85c\ub294 \uadf8\ub7f0 \uc774\uc57c\uae30\uac00 \ud6c4\ub300\uc5d0 \uc804\ud574\uc84c\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ud655\uc778\ud560 \uc218 \uc788\ub2e4. \ub530\ub77c\uc11c \u2018\uc7a0\uc7ac\uc6b0\ub824\uace0 \uc8fc\ubb38\ubc1b\uc544 \ub9cc\ub4e0 \uc218\uba74 \uc74c\uc545\u2019\uc774\ub77c\uace0 \uc791\ud488\uc758 \ubaa9\uc801\uc744 \ub2e8\uc815\ud558\uc9c0 \ub9d0\uc790. \uc81c\ubaa9\uc758 \uc774\uc57c\uae30\uc640 \uc2e4\uc81c \uc74c\uc545\uc740 \uad6c\ubcc4\ud574 \ub4e4\uc744 \uc5ec\uc9c0\uac00 \uc788\ub2e4. \uc545\ubcf4\uc5d0\ub294 \uc544\ub9ac\uc544\uc640 \uc11c\ub978 \uac1c\uc758 \ubcc0\uc8fc\ub77c\ub294 \uad6c\uc131\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \ucc98\uc74c\uc758 \uc544\ub9ac\uc544\ub294 \uc138 \ubc15\uc758 \ud750\ub984 \uc18d\uc5d0\uc11c \uc7a5\uc2dd\ub41c \uc120\uc728\uc744 \ub4e4\ub824\uc900\ub2e4. \uc774\uc5b4\uc9c0\ub294 \ubcc0\uc8fc\ub4e4\uc740 \uac19\uc740 \uba5c\ub85c\ub514\ub97c \ub2e8\uc21c\ud788 \ube60\ub974\uac8c, \ub290\ub9ac\uac8c \ubc18\ubcf5\ud558\ub294 \ubc29\uc2dd\uc5d0 \uba38\ubb3c\uc9c0 \uc54a\ub294\ub2e4. \uc911\uc694\ud55c \uc5f0\uacb0\uc740 \uc74c\uc545 \uc544\ub798\ub97c \ubc1b\uce58\ub294 \ud654\uc131\uacfc \uad6c\uc870\uc5d0 \uc788\ub2e4. \uc120\uc728\uc758 \uac89\ubaa8\uc2b5\uc774 \ud06c\uac8c \ubc14\ub00c\uc5b4\ub3c4 \ubc14\ud0d5\uc758 \uae38\uc744 \uacf5\uc720\ud558\ub294 \uc148\uc774\ub2e4. \uc9d1\uc758 \uae30\ub465\uacfc \ubc29\uc758 \ud2c0\uc740 \uc774\uc5b4\uc9c0\ub294\ub370 \uadf8 \uc548\uc758 \uc0dd\ud65c\uacfc \ube5b\uc774 \ub2ec\ub77c\uc9c4\ub2e4\uace0 \uc0dd\uac01\ud574\ub3c4 \uc88b\ub2e4. \uc5b4\ub824\uc6b4 \uc6a9\uc5b4\ubcf4\ub2e4 \ud45c\uba74\uacfc \ubc14\ud0d5\uc774 \ub530\ub85c \uc6c0\uc9c1\uc77c \uc218 \uc788\ub2e4\ub294 \uac10\uac01\uc744 \uba3c\uc800 \uc7a1\uc544 \ubcf4\uc790. \uccab \ubcc0\uc8fc\ub97c \ub4e3\uace0 \u2018\ubc29\uae08 \uc544\ub9ac\uc544\uc640 \uc5b4\ub514\uac00 \uac19\uc9c0?\u2019 \ud558\uace0 \ub290\ub07c\ub294 \uac83\uc740 \uc790\uc5f0\uc2a4\ub7fd\ub2e4. \uc544\ub9ac\uc544\uc758 \ub178\ub798\ub97c \uadf8\ub300\ub85c \ud765\uc5bc\uac70\ub9ac\ub824 \ud558\uba74 \uc774\uc5b4\uc9c0\ub294 \uc74c\uc545\uc774 \ub0af\uc124 \uc218 \uc788\ub2e4. \ub300\uc2e0 \ubc15\uc790\uc758 \ud750\ub984\uacfc \uad6c\uc808\uc774 \ub9c8\ubb34\ub9ac\ub418\ub294 \uac10\uac01, \ub0ae\uc740 \uc74c\uc758 \ubc29\ud5a5\uc5d0 \uadc0\ub97c \uae30\uc6b8\uc5ec \ubcf4\uc790. \ucc98\uc74c \ub4e3\ub294 \uc790\ub9ac\uc5d0\uc11c \uc11c\ub978 \uace1\uc744 \ubc88\ud638\ub300\ub85c \uae30\uc5b5\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ubc1d\uac8c \ub6f0\ub294 \ubd80\ubd84\uc774 \uc788\ub294\uc9c0, \uc131\ubd80\uac00 \uc5bd\ud600 \ub4e4\ub9ac\ub294\uc9c0, \uc74c\uc774 \ub4dc\ubb38\ub4dc\ubb38 \ub193\uc774\ub294\uc9c0 \uc815\ub3c4\ub97c \uad6c\ubd84\ud574\ub3c4 \ucda9\ubd84\ud558\ub2e4. \ud558\ub098\uc758 \ud45c\uc815\uc73c\ub85c \ub05d\uae4c\uc9c0 \uc774\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ub290\ub07c\ub294 \ub370\uc11c \uac10\uc0c1\uc774 \uc2dc\uc791\ub41c\ub2e4. \uc81c3\ubcc0\uc8fc\uc758 \uc545\ubcf4\uc5d0\ub294 \uce74\ub17c\uc774\ub77c\ub294 \ud45c\uc81c\uac00 \uc788\ub2e4. \ud55c \uc131\ubd80\uac00 \ub0b4\ub193\uc740 \uc6c0\uc9c1\uc784\uc744 \ub2e4\ub978 \uc131\ubd80\uac00 \uc77c\uc815\ud55c \uac04\uaca9\uc744 \ub450\uace0 \ub530\ub77c\uc624\ub294 \ubc29\uc2dd\uc774\ub2e4. \uc6b0\ub9ac\uac00 \ub3cc\ub9bc\ub178\ub798\uc5d0\uc11c \uacbd\ud5d8\ud558\ub294 \uc6d0\ub9ac\ub97c \ub5a0\uc62c\ub9ac\uba74 \uc9c4\uc785\ud558\uae30 \uc27d\ub2e4. \ub2e8\uc21c\ud788 \uac19\uc740 \uc18c\ub9ac\ub97c \ud06c\uac8c \uacb9\uce58\ub294 \uac83\uacfc\ub294 \ub2e4\ub974\ub2e4. \ub4e3\ub294 \uc0ac\ub78c\uc740 \uba3c\uc800 \uc55e\uc5d0 \ub098\uc628 \uc18c\ub9ac\ub97c \ucc3e\uace0, \ub4a4\uc5d0\uc11c \ube44\uc2b7\ud55c \uc6c0\uc9c1\uc784\uc774 \ub098\uc624\ub294\uc9c0 \uae30\ub2e4\ub824 \ubcfc \uc218 \uc788\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc18c\ub9ac\uac00 \uac01\uc790\uc758 \uae38\uc744 \uac00\uba74\uc11c \uc804\uccb4\ub97c \uc774\ub8ec\ub2e4\ub294 \uac83\uc774 \ubc14\ud750 \uc74c\uc545\uc758 \uc7ac\ubbf8 \uc911 \ud558\ub098\ub2e4. \ubaa8\ub4e0 \uaddc\uce59\uc744 \uc54c\uc544\ub9de\ud600\uc57c \uc990\uae38 \uc218 \uc788\ub294 \uc218\ud559 \uc2dc\ud5d8\uc740 \uc544\ub2c8\ub2e4. \uc81c25\ubcc0\uc8fc\ub294 \uc0ac\ub2e8\uc870\ub85c \ub418\uc5b4 \uc788\uc73c\uba70, \uc55e\ub4a4\uc758 \ud65c\uae30\ucc2c \ubd80\ubd84\uacfc \ub2e4\ub978 \ubb34\uac8c\ub97c \ub290\ub07c\uac8c \ud560 \uc218 \uc788\ub2e4. \uc5b4\ub5a4 \ud45c\uc815\uc744 \ub290\ub084\uc9c0\ub294 \ub4e3\ub294 \uc0ac\ub78c\uc758 \ubaab\uc774\uc9c0\ub9cc \uae34 \uc5ec\uc815\uc5d0\uc11c \uae4a\uc219\ud55c \uacf3\uc73c\ub85c \ub4e4\uc5b4\uc624\ub294 \ub4ef\ud55c \uacbd\ud5d8\uc744 \uc8fc\ub294 \ub300\ubaa9\uc774\ub2e4. \uac19\uc740 \ubc14\ud0d5 \uc704\uc5d0\uc11c\ub3c4 \uc74c\uc545\uc758 \uc815\uc11c\ub294 \ud06c\uac8c \ub2ec\ub77c\uc9c4\ub2e4. \uc2ac\ud508 \uc0ac\uc5f0\uc744 \ud558\ub098 \uc815\ud574 \uc74c\ub9c8\ub2e4 \ubc30\uc815\ud558\uc9c0 \uc54a\uc544\ub3c4 \ub41c\ub2e4. \uc120\uc728\uc774 \uc5bc\ub9c8\ub098 \uc624\ub798 \uba38\ubb34\ub294\uc9c0, \ub2e4\ub978 \uc74c\uc774 \ub4e4\uc5b4\uc62c \ub54c \uae34\uc7a5\uc774 \uc5b4\ub5bb\uac8c \ub290\uaef4\uc9c0\ub294\uc9c0 \ub4e4\uc5b4 \ubcf4\uc790. \ube60\ub978 \uc190\ub180\ub9bc\ub9cc\uc774 \uc791\ud488\uc758 \ud48d\ubd80\ud568\uc744 \ub9cc\ub4dc\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\ub3c4 \uc774 \ubd80\ubd84\uc5d0\uc11c \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \uc81c30\ubcc0\uc8fc\ub294 \ucffc\ub4e4\ub9ac\ubcb3\uc774\ub77c\ub294 \uc774\ub984\uc744 \uac00\uc9c4\ub2e4. \ud3ec\ub974\ucf08 \uc804\uae30\uc5d0 \ubd99\uc740 \ud574\uc124\uc740 \uc11c\ub85c \ub2e4\ub978 \ubbfc\uc694 \uc120\uc728\ub4e4\uc774 \uc4f0\uc600\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc5c4\uaca9\ud55c \uc9dc\uc784\uc744 \ub530\ub77c \uae34 \uae38\uc744 \uc628 \ub4a4 \uc0dd\ud65c \uc18d \ub178\ub798 \uac19\uc740 \uc131\uaca9\uc744 \ub9cc\ub098\ub294 \uc148\uc774\ub2e4. \uc5ec\uae30\uc11c\ub3c4 \ubc14\ud750\uc758 \uc74c\uc545\uc740 \ud55c \uac00\uc9c0 \uc704\uc5c4\ub9cc \uc720\uc9c0\ud558\uc9c0 \uc54a\ub294\ub2e4. \ub2f9\uc2dc \ub178\ub798\uc758 \uac00\uc0ac\ub97c \ubaa8\ub450 \uc54c\uc9c0 \ubabb\ud574\ub3c4 \ub9c8\uc9c0\ub9c9 \ubd80\ubd84\uc758 \uc131\uaca9\uc774 \uc55e\uc758 \ubcc0\uc8fc\uc640 \uc5b4\ub5bb\uac8c \ub2e4\ub978\uc9c0 \ub4e4\uc744 \uc218 \uc788\ub2e4. \ub0af\uc120 \uc774\ub984\uc774 \ub9ce\uc774 \ub098\uc640 \ubd80\ub2f4\uc2a4\ub7fd\ub2e4\uba74 \u2018\uc5ec\ub7ec \ub178\ub798\ub97c \ud568\uaed8 \ub193\ub294 \uc74c\uc545\u2019 \uc815\ub3c4\uc758 \uae38\uc7a1\uc774\ub85c \uc2dc\uc791\ud574\ub3c4 \uc88b\ub2e4. \uad6c\uccb4\uc801\uc778 \uc9c0\uc2dd\uc740 \ub2e4\uc2dc \ub4e4\uc744 \ub54c \uc870\uae08\uc529 \ubcf4\ud0dc\uba74 \ub41c\ub2e4. \ub9c8\uc9c0\ub9c9 \uc545\ubcf4\uc5d0\ub294 \ucc98\uc74c\uc758 \uc544\ub9ac\uc544\ub85c \ub3cc\uc544\uac00 \ub05d\ub0b4\ub77c\ub294 \uc9c0\uc2dc\uac00 \uc788\ub2e4. \uc0c8\ub85c\uc6b4 \uacb0\ub860\uc758 \uc120\uc728\uc744 \ub367\ubd99\uc774\ub294 \ub300\uc2e0 \ucd9c\ubc1c\ud588\ub358 \uc74c\uc545\uc744 \ub2e4\uc2dc \ub9cc\ub098\ub294 \uac83\uc774\ub2e4. \ub4e3\ub294 \uc0ac\ub78c\uc740 \uadf8 \uc0ac\uc774 \uc11c\ub978 \ubc88\uc758 \ub2e4\ub978 \ud48d\uacbd\uc744 \uc9c0\ub098\uc654\ub2e4. \uadf8\ub798\uc11c \uc74c\uc545\uc740 \uac19\uc544\ub3c4 \uae30\uc5b5\uc740 \uac19\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \ucc98\uc74c\uc5d0\ub294 \ub2e8\uc815\ud55c \uc2dc\uc791\uc73c\ub85c \ub4e4\ub838\ub358 \uc544\ub9ac\uc544\uac00 \ub05d\uc5d0\uc11c\ub294 \ud734\uc2dd\uc774\ub098 \ub3cc\uc544\uc634\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218\ub3c4 \uc788\ub2e4. \uc791\uace1\uac00\uac00 \uc815\ud574 \uc900 \ud558\ub098\uc758 \uac10\uc815\uc774\ub77c\uace0 \ub2e8\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uad6c\uc870\uac00 \uccad\uc911\uc758 \uacbd\ud5d8\uc744 \uc5b4\ub5bb\uac8c \ubc14\uafb8\ub294\uc9c0 \uc2a4\uc2a4\ub85c \ub290\uaef4 \ubcf4\ub294 \ub300\ubaa9\uc774\ub2e4. \uba3c\uc800 \uc544\ub9ac\uc544\uc640 \uc81c1\ubcc0\uc8fc\ub97c \ub4e3\uace0, \ub2e4\uc74c\uc5d0\ub294 \uce74\ub17c\uc778 \uc81c3\ubcc0\uc8fc, \uc81c25\ubcc0\uc8fc, \ub9c8\uc9c0\ub9c9 \ubcc0\uc8fc\uc640 \ub3cc\uc544\uc628 \uc544\ub9ac\uc544\ub97c \ube44\uad50\ud574 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uc804\uccb4\ub97c \ub2e4 \ub4e4\uc73c\uba74 \ud750\ub984\uc744 \ub354 \ub113\uac8c \ub290\ub084 \uc218 \uc788\uc9c0\ub9cc, \ucc98\uc74c\ubd80\ud130 \uae34 \uc2dc\uac04\uc744 \ub0b4\uc57c\ub9cc \uc2dc\uc791\ud560 \uc218 \uc788\ub294 \uc791\ud488\uc740 \uc544\ub2c8\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \ud558\uc6b0\uc2a4\ub9cc\uc774 \uadf8\ub9b0 \ubc14\ud750 \ucd08\uc0c1\uc758 \uc5ed\uc0ac\uc801 \uc7ac\ud604 \ub3c4\ud310\uc774\ub2e4. \ubc31\uc791\uc758 \uce68\uc2e4\uc774\ub098 \ub2f9\uc2dc \uc5f0\uc8fc \uc7a5\uba74\uc744 \uc7ac\ud604\ud55c \uadf8\ub9bc\uc740 \uc544\ub2c8\ub2e4. \uc81c\ubaa9\uc758 \uc804\uc2b9\uc744 \ub4e3\ub294 \uc990\uac70\uc6c0 \uacc1\uc5d0, \uc74c\ub4e4\uc774 \uc2e4\uc81c\ub85c \ub9cc\ub4dc\ub294 \ubcc0\ud615\uacfc \uadc0\ud658\uc758 \uacbd\ud5d8\uc744 \ub450\uc5b4 \ubcf4\uc790. \uc65c \uac19\uc740 \uc74c\uc545\uc774 \ub9c8\uc9c0\ub9c9\uc5d0\ub294 \uc870\uae08 \ub2e4\ub974\uac8c \ub4e4\ub9ac\ub294\uc9c0 \uc9c1\uc811 \ub9cc\ub0a0 \uc218 \uc788\ub2e4."}, {"id": "harp-colored-strings", "title": "\ud558\ud504 \uc904\uc5d0\ub294 \uc65c \ube68\uac04\uc0c9\uc774 \uc11e\uc5ec \uc788\uc744\uae4c", "summary": "\uba40\ub9ac\uc11c\ub294 \ubaa8\ub450 \ube44\uc2b7\ud574 \ubcf4\uc774\ub294 \ud558\ud504\uc758 \uc904. \uac00\uae4c\uc774 \ubcf4\uba74 \uc5f0\uc8fc\uc790\ub97c \uc704\ud55c \uc791\uc740 \uc0c9\uae54 \ud45c\uc9c0\uac00 \uc788\uc2b5\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Music", "url": "stories/harp-colored-strings/index.html", "image": "media/harp-colored-strings.jpg", "alt": "\ubc1d\uc740 \uc904 \uc0ac\uc774\uc5d0 \ubd89\uace0 \uc5b4\ub450\uc6b4 \uc904\uc774 \uc11e\uc778 \ud558\ud504 \uc77c\ubd80\ub97c \uadf8\ub9b0 AI \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\ud558\ud504 \uc904\uc5d0\ub294 \uc65c \ube68\uac04\uc0c9\uc774 \uc11e\uc5ec \uc788\uc744\uae4c \uc218\ub9ce\uc740 \ud604 \uc0ac\uc774\uc5d0\uc11c \uae38\uc744 \ucc3e\ub294 \uc0c9\uae54 \uba40\ub9ac\uc11c\ub294 \ubaa8\ub450 \ube44\uc2b7\ud574 \ubcf4\uc774\ub294 \ud558\ud504\uc758 \uc904. \uac00\uae4c\uc774 \ubcf4\uba74 \uc5f0\uc8fc\uc790\ub97c \uc704\ud55c \uc791\uc740 \uc0c9\uae54 \ud45c\uc9c0\uac00 \uc788\uc2b5\ub2c8\ub2e4. Music \ubb38\ud654 \ud558\ud504\ub97c \ubcf4\uba74 \uba3c\uc800 \uc904\uc758 \uc218\uc5d0 \uc555\ub3c4\ub41c\ub2e4. \uae38\uace0 \uc9e7\uc740 \uc904\uc774 \ub098\ub780\ud788 \uc11c \uc788\uc5b4\uc11c, \uc5b4\ub514\ub97c \uc9da\uc5b4\uc57c \uc6d0\ud558\ub294 \uc18c\ub9ac\uac00 \ub098\ub294\uc9c0 \uc7a0\uae50 \ub9c9\ub9c9\ud574\uc9c4\ub2e4. \uadf8\ub7f0\ub370 \uac00\uae4c\uc774 \ubcf4\uba74 \ubaa8\ub4e0 \uc904\uc774 \uac19\uc740 \uc0c9\uc740 \uc544\ub2c8\ub2e4. \ube68\uac04 \uc904\uc774 \uc11e\uc5ec \uc788\uace0 \uc5b4\ub450\uc6b4 \uc904\ub3c4 \ubcf4\uc778\ub2e4. \uc7a5\uc2dd\uc73c\ub85c \uc0c9\uc744 \ub123\uc740 \uac83 \uac19\uc9c0\ub9cc, \uc5f0\uc8fc\uc790\uac00 \uc904\uc744 \ucc3e\ub294 \ub370 \ub3c4\uc6c0\uc744 \uc8fc\ub294 \ud45c\uc2dc\ub2e4. \ud544\ud558\ubaa8\ub2c8\uc544 \uc624\ucf00\uc2a4\ud2b8\ub77c\uc758 \ud558\ud504 \uc548\ub0b4\ub294 \ub3c4\uc5d0 \ud574\ub2f9\ud558\ub294 C \uc904\uc744 \ube68\uac04\uc0c9, \ud30c\uc5d0 \ud574\ub2f9\ud558\ub294 F \uc904\uc744 \uac80\uc740\uc0c9\uc73c\ub85c \uc18c\uac1c\ud55c\ub2e4. \ube7d\ube7d\ud55c \uc904 \uc0ac\uc774\uc5d0 \uc54c\uc544\ubcf4\uae30 \uc26c\uc6b4 \uae30\uc900\uc810\uc744 \ub454 \uac83\uc774\ub2e4. \uc774\uc57c\uae30\uc758 \ub300\uc0c1\uc740 \uc624\ucf00\uc2a4\ud2b8\ub77c\uc5d0\uc11c \uc0ac\uc6a9\ud558\ub294 \ud604\ub300\uc801\uc778 \ud398\ub2ec \ud558\ud504\ub2e4. \uc548\ub0b4\uc5d0 \ub530\ub974\uba74 \uc774 \ud558\ud504\uc5d0\ub294 47\uac1c\uc758 \uc904\uc774 \uc788\ub2e4. \uc904\ub9c8\ub2e4 \uc190\uae00\uc528 \uc774\ub984\ud45c\ub97c \ub2ec\uae30\ubcf4\ub2e4 \uc0c9\uc73c\ub85c \uc790\ub9ac\ub97c \uad6c\ubd84\ud558\uba74 \uc5f0\uc8fc \uc911\uc5d0\ub3c4 \ub208\uc5d0 \ube68\ub9ac \ub4e4\uc5b4\uc628\ub2e4. \uc6b0\ub9ac\ub3c4 \ube44\uc2b7\ud55c \ud45c\uc2dc\ub97c \uc4f4\ub2e4. \uc790\uc8fc \ucc3e\ub294 \ucc45\uc5d0 \uc0c9\uae54 \ucabd\uc9c0\ub97c \ubd99\uc774\uac70\ub098, \ube44\uc2b7\ud55c \uc5f4\uc1e0\ub97c \uad6c\ubd84\ud558\ub824 \uace0\ub9ac\ub97c \ub2ec \ub54c\uac00 \uc788\ub2e4. \ud558\ud504\uc758 \uc904\uc5d0\uc11c\ub294 \uc0c9\uc774 \uadf8 \uc791\uc740 \uae38\uc7a1\uc774 \uc5ed\ud560\uc744 \ud55c\ub2e4. \ud558\ud504\ub97c \ubcf4\ub294 \uc2dc\uc120\uc740 \ubcf4\ud1b5 \uc190\uc5d0 \uba38\ubb38\ub2e4. \ud558\uc9c0\ub9cc \uc544\ub798\uc5d0\ub294 \uc77c\uacf1 \uac1c\uc758 \ud398\ub2ec\ub3c4 \uc788\ub2e4. \uc774 \ud398\ub2ec\uc740 \uac19\uc740 \uc774\ub984\uc758 \uc74c\uc5d0 \ud574\ub2f9\ud558\ub294 \uc904\ub4e4\uc758 \uc74c\ub192\uc774\ub97c \ubc14\uafb8\ub294 \ub370 \uc4f0\uc778\ub2e4. \ud544\ud558\ubaa8\ub2c8\uc544\ub294 C \ud398\ub2ec\uc744 \ubc14\uafb8\uba74 \uc5ec\ub7ec \ub192\uc774\uc5d0 \uc788\ub294 C \uc904\ub4e4\uc774 \ud568\uaed8 \uc601\ud5a5\uc744 \ubc1b\ub294\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc904 \ud558\ub098\ub9c8\ub2e4 \ubc1c\ud310 \ud558\ub098\uac00 \uc788\ub294 \uad6c\uc870\ub294 \uc544\ub2cc \uac83\uc774\ub2e4. \uadf8\ub798\uc11c \uc5f0\uc8fc\uc790\ub294 \uc190\uc73c\ub85c \uc904\uc744 \ub72f\ub294 \ub3d9\uc548\uc5d0\ub3c4 \ubc1c\ubc11\uc758 \uc0c1\ud0dc\ub97c \uc0b4\ud540\ub2e4. \uc26c\ub294 \uad6c\uac04\uc774 \ubcf4\uc778\ub2e4\uace0 \uc644\uc804\ud788 \ud560 \uc77c\uc774 \uc5c6\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub2e4\uc74c\uc5d0 \ud544\uc694\ud55c \uc18c\ub9ac\ub97c \uc704\ud574 \ud398\ub2ec\uc744 \ubc14\uafb8\ub294 \uc2dc\uac04\uc77c \uc218\ub3c4 \uc788\ub2e4. 47\uac1c\uc758 \uc904 \uc55e\uc5d0\uc11c \uc5f0\uc8fc\uc790\ub294 \uc9c0\uae08 \ud544\uc694\ud55c \uc74c\uc758 \uc790\ub9ac\ub97c \ube60\ub974\uac8c \uc54c\uc544\ubcf4\uc544\uc57c \ud55c\ub2e4. \ubaa8\ub4e0 \uc904\uc774 \ub611\uac19\uc774 \ubcf4\uc778\ub2e4\uba74 \uc190\uc758 \uc774\ub3d9\uc744 \ud655\uc778\ud558\ub294 \uc77c\ub3c4 \uc5b4\ub824\uc6cc\uc9c8 \uc218 \uc788\ub2e4. \ube68\uac04 C\uc640 \uac80\uc740 F\ub294 \uc5ec\ub7ec \ub192\uc774\uc5d0 \uac78\uccd0 \ubc18\ubcf5\ub418\ub294 \uae30\uc900\uc810\uc774\ub2e4. \uc0c9\uc774 \uc18c\ub9ac\ub97c \uc9c1\uc811 \ub9cc\ub4e4\uc5b4 \ub0b4\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \uc5f0\uc8fc\ud560 \uc704\uce58\ub97c \ucc3e\ub294 \uc0ac\ub78c\uc744 \ub3d5\ub294 \ud45c\uc2dc\ub77c\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \uc545\ubcf4\uc758 \uc74c\uacfc \uc2e4\uc81c \uc904 \uc0ac\uc774\ub97c \uc5f0\uacb0\ud558\ub294 \uc77c\uc5d0\ub294 \ub208\uacfc \uc190\uc774 \ud568\uaed8 \uc4f0\uc778\ub2e4. \uc0c9\uc744 \uc544\ub294 \uad00\ub78c\uc790\ub77c\uba74 \uc5f0\uc8fc\uc790\uc758 \uc190\uc774 \uc5b4\ub290 \uad6c\uc5ed\uc744 \uc624\uac00\ub294\uc9c0 \uc870\uae08 \ub354 \uad6c\uccb4\uc801\uc73c\ub85c \ubcfc \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ubaa8\ub4e0 \ud558\ud504\uac00 \uac19\uc740 \uc904 \uc218\uc640 \uc0c9\uc744 \uac00\uc9c4\ub2e4\uace0 \uc77c\ubc18\ud654\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc774 \uae00\uc5d0\uc11c \uc124\uba85\ud558\ub294 \ud604\ub300 \ud398\ub2ec \ud558\ud504\uc758 \uad6c\uc131\uc774\ub77c\ub294 \ubc94\uc704\ub97c \uae30\uc5b5\ud558\uba74 \ub41c\ub2e4. \ud53c\uc544\ub178\uc5d0\uc11c \uc11c\ub85c \ub2e4\ub978 \ub192\uc774\uc758 \ub3c4\uac00 \ubc18\ubcf5\ub418\ub4ef \ud558\ud504\uc5d0\ub3c4 \uac19\uc740 \uc774\ub984\uc744 \uac00\uc9c4 \uc5ec\ub7ec \uc904\uc774 \uc788\ub2e4. \uc548\ub0b4\ub294 C \ud398\ub2ec\uc744 \uc6c0\uc9c1\uc774\uba74 \uc5ec\ub7ec \ub192\uc774\uc758 C \uc904\uc5d0 \ud568\uaed8 \uc601\ud5a5\uc744 \uc900\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc904\uc758 \ucd1d\uac1c\uc218\uc640 \ud398\ub2ec\uc758 \uac1c\uc218\uac00 \uc77c\uce58\ud558\uc9c0 \uc54a\ub294 \uae4c\ub2ed\uc774\ub2e4. \ubc1c \ud558\ub098\uac00 \ubb3c\uac74 \ud558\ub098\ub9cc \ub9e1\ub294 \uad6c\uc870\uac00 \uc544\ub2c8\ub77c \uc74c\uc758 \uc774\ub984\uc744 \uae30\uc900\uc73c\ub85c \ubb36\uc778 \uc870\uc808\uc744 \ud558\ub294 \uc148\uc774\ub2e4. \uc774 \uad00\uacc4\ub97c \uc54c\uace0 \ubcf4\uba74 \ud558\ud504\ub97c \ub2e8\uc21c\ud788 \uc904\uc744 \ub9ce\uc774 \ub2e8 \uc545\uae30\ub85c \uae30\uc5b5\ud558\uae30 \uc5b4\ub835\ub2e4. \uc190\uc740 \uc5b4\ub5a4 \uc904\uc744 \uc5b8\uc81c \ub72f\uc744\uc9c0 \ub2e4\ub8e8\uace0 \ubc1c\uc740 \ud544\uc694\ud55c \uc74c\ub192\uc774\uc758 \uc0c1\ud0dc\ub97c \uc900\ube44\ud55c\ub2e4. \ubb3c\ub860 \uc2e4\uc81c \uc5f0\uc8fc\uc758 \ubaa8\ub4e0 \uc870\uc791\uc744 \ub450 \ubb38\uc7a5\uc73c\ub85c \uc694\uc57d\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \ub208\uc5d0 \ubcf4\uc774\ub294 \uc190\uc758 \ub3d9\uc791 \ub4a4\uc5d0 \ub2e4\ub978 \uc900\ube44\uac00 \uc788\ub2e4\ub294 \uc810\uc774 \uacf5\uc5f0\uc758 \ud48d\uacbd\uc744 \ubc14\uafd4 \uc900\ub2e4. \uc120\uc728\uc774 \uc7a0\uc2dc \ub04a\uaca8\ub3c4 \uc5f0\uc8fc\uc790\uac00 \ud398\ub2ec\uc744 \ubc14\uafb8\uac70\ub098 \uc190\uc744 \uc62e\uae30\ub294 \ubaa8\uc2b5\uc744 \ubcfc \uc218 \uc788\ub2e4. \uc74c\uc545\uc740 \uc9c0\uae08 \uc6b8\ub9ac\ub294 \uc18c\ub9ac\ubfd0 \uc544\ub2c8\ub77c \uace7 \uc6b8\ub9b4 \uc18c\ub9ac\uc758 \uc870\uac74\ub3c4 \ud544\uc694\ud558\uae30 \ub54c\ubb38\uc774\ub2e4. \uad00\uac1d\uc5d0\uac8c \uc870\uc6a9\ud55c \uad6c\uac04\uc774 \uc5f0\uc8fc\uc790\uc5d0\uac8c\ub294 \ub2e4\uc74c \uc7a5\uba74\uc758 \uc900\ube44 \uc2dc\uac04\uc774 \ub420 \uc218 \uc788\ub2e4. \uc27c\uc744 \uc544\ubb34 \ud65c\ub3d9\ub3c4 \uc5c6\ub294 \ube48\uce78\uc73c\ub85c\ub9cc \ubcf4\uc9c0 \uc54a\uac8c \ub418\ub294 \ub300\ubaa9\uc774\ub2e4. \ud558\ud504\ub9cc\uc758 \ud2b9\ubcc4\ud55c \ub9c8\ubc95\uc774\ub77c\uae30\ubcf4\ub2e4 \ud569\uc8fc\uc5d0\uc11c \ub9cc\ub098\ub294 \uc900\ube44\uc758 \ud55c \uc0ac\ub840\ub2e4. \ud604\uc744 \uace0\ub974\uace0 \ubab8\uc758 \uc704\uce58\ub97c \uc7a1\ub294 \uc77c\uc774 \uad00\ub78c\uc790\uc5d0\uac8c \ubaa8\ub450 \ud06c\uac8c \ub4dc\ub7ec\ub098\uc9c0\ub294 \uc54a\ub294\ub2e4. \uadf8\ub798\uc11c \uacf5\uc5f0\uc744 \ubcfc \ub54c \ud55c \ubc88\uc740 \uc120\uc728\uc744 \ub4e3\uace0 \ub2e4\ub978 \ud55c \ubc88\uc740 \uc900\ube44 \ub3d9\uc791\uc744 \ub530\ub77c\uac00\ub3c4 \uc88b\ub2e4. \uc815\ud655\ud788 \uc5b4\ub5a4 \ud398\ub2ec\uc744 \ubc1f\ub294\uc9c0 \uc54c\uc544\ub9de\ud790 \ud544\uc694 \uc5c6\uc774\ub3c4 \uc74c\uc545\uc744 \ub9cc\ub4dc\ub294 \uc6c0\uc9c1\uc784\uc774 \ubcf4\uc778\ub2e4. \uc904\uc758 \uc0c9\uc744 \uc54c\uc558\ub2e4\uace0 \uace7\ubc14\ub85c \uc74c\uc744 \uadc0\ub85c \uad6c\ubd84\ud558\ub294 \ub2a5\ub825\uc774 \uc0dd\uae30\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub798\ub3c4 \ubcf5\uc7a1\ud574 \ubcf4\uc774\ub358 \uc545\uae30\uc5d0 \ub208\uc774 \uba38\ubb3c \ud45c\uc9c0\uac00 \uc0dd\uae34\ub2e4. \uc74c\uc545\uc744 \ubc30\uc6b0\ub294 \uc785\uad6c\uac00 \uc545\ubcf4\uc640 \uc74c\uc774\ub984\uc758 \uc554\uae30 \ud558\ub098\ub85c\ub9cc \uc815\ud574\uc838 \uc788\uc9c0 \uc54a\ub2e4\ub294 \ub73b\uc774\ub2e4. \uad6c\uc870\uc758 \uc791\uc740 \ub2e8\uc11c\uac00 \ub0af\uc120 \uc545\uae30\ub97c \ub2e4\uc2dc \ubcf4\uace0 \uc2f6\uac8c \ub9cc\ub4e4 \uc218 \uc788\ub2e4. \ub2e4\uc74c \ud569\uc8fc \uc601\uc0c1\uc5d0\uc11c \ud558\ud504\ub97c \ucc3e\uc558\ub2e4\uba74 \uba3c\uc800 \uc0c9\uc774 \ubc18\ubcf5\ub418\ub294 \uad6c\uac04\uc744 \ubcf4\uace0, \uc190\uacfc \ubc1c\uc758 \uc6c0\uc9c1\uc784\uc744 \ubc88\uac08\uc544 \uc0b4\ud3b4\ubcf4\uc790. \uc18c\ub9ac\uac00 \ubcf4\uc774\ub294 \uc790\ub9ac\uc640 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc870\uc808\uc774 \uc5b4\ub5bb\uac8c \ub098\ub258\ub294\uc9c0 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ube5b\ub098\ub294 \ub9ce\uc740 \uc904 \uac00\uc6b4\ub370 \ube68\uac04\uc0c9 \uba87 \uac00\ub2e5\uc774 \ub2e8\uc21c\ud55c \uc7a5\uc2dd\uc5d0\uc11c \uc5f0\uc8fc\ub97c \ub3d5\ub294 \uae38\uc7a1\uc774\ub85c \ubc14\ub00c\ub294 \uc21c\uac04\uc774\ub2e4. \ud558\ud504\uc758 \uace1\uc120\uacfc \uc904\uc740 \uba40\ub9ac\uc11c\ub3c4 \uc544\ub984\ub2f5\ub2e4. \uac00\uae4c\uc774\uc5d0\uc11c\ub294 \uadf8 \uc544\ub984\ub2e4\uc6b4 \ubaa8\uc2b5 \uc548\uc5d0 \uc5f0\uc8fc\ub97c \ub3d5\ub294 \uc7a5\uce58\uac00 \ub4e4\uc5b4 \uc788\ub2e4\ub294 \uac83\uc774 \ubcf4\uc778\ub2e4. \uc0c9\uae54\uc740 \uc704\uce58\ub97c, \ud398\ub2ec\uc740 \uc74c\uc758 \ubcc0\ud654\ub97c \ub2e4\ub8ec\ub2e4. \ud544\ud558\ubaa8\ub2c8\uc544\ub294 \ud558\ud504 \uc5f0\uc8fc\uc790\ub4e4\uc774 \uacf5\uc5f0 \uc804\uc5d0 \uc5ec\ub7ec \uc904\uc744 \uc870\uc728\ud558\ub294 \ubaa8\uc2b5\ub3c4 \uc18c\uac1c\ud55c\ub2e4. \ubc18\uc9dd\uc774\ub294 \uc904\uc774 \ub9ce\uc774 \uc788\ub2e4\ub294 \uac83\uc740, \uadf8\ub9cc\ud07c \ubbf8\ub9ac \ud655\uc778\ud574\uc57c \ud560 \uc18c\ub9ac\ub3c4 \ub9ce\ub2e4\ub294 \ub73b\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \ud558\ud504\ub97c \ub9cc\ub098\uba74 \uc904\uc744 \ud558\ub098\uc529 \uc138\ub824\uace0 \uc560\uc4f0\uc9c0 \uc54a\uc544\ub3c4 \uc88b\ub2e4. \uba3c\uc800 \ube68\uac04 \uc904\uc744 \ucc3e\uc544\ubcf4\uc790. \uc544\ub984\ub2e4\uc6b4 \uc545\uae30 \uc548\uc5d0\uc11c \uc5f0\uc8fc\uc790\uac00 \uae38\uc744 \uc783\uc9c0 \uc54a\ub3c4\ub85d \ub9c8\ub828\ud55c \uc791\uc740 \ud45c\uc9c0\uac00 \ubcf4\uc77c \uac83\uc774\ub2e4."}, {"id": "holbein-erasmus-writing", "title": "\uc5d0\ub77c\uc2a4\ubb34\uc2a4\uc758 \ucd08\uc0c1 \u2014 \uae00\uc744 \uc4f0\ub294 \uc190\uc774 \uc5bc\uad74\uc744 \uc124\uba85\ud560 \ub54c", "summary": "\ubaa8\ud53c \uc637\uacfc \ud39c, \ub0ae\ucd98 \ub208\uae38\uc744 \ub530\ub77c \ud55c \uc0ac\ub78c\uc758 \uc77c\uc774 \ucd08\uc0c1\uc5d0 \ub2f4\uae30\ub294 \ubc29\uc2dd\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Art", "url": "stories/holbein-erasmus-writing/index.html", "image": "media/holbein-erasmus-writing.jpg", "alt": "\ud640\ubc14\uc778\uc758 \uc5d0\ub77c\uc2a4\ubb34\uc2a4 \ucd08\uc0c1. \ubaa8\ud53c \uc637\uacfc \uac80\uc740 \ubaa8\uc790\ub97c \uc4f4 \uc778\ubb3c\uc774 \uc606\uc5bc\uad74\ub85c \ucc45\uc0c1\uc5d0\uc11c \uae00\uc744 \uc501\ub2c8\ub2e4.", "text": "\uc5d0\ub77c\uc2a4\ubb34\uc2a4\uc758 \ucd08\uc0c1 \u2014 \uae00\uc744 \uc4f0\ub294 \uc190\uc774 \uc5bc\uad74\uc744 \uc124\uba85\ud560 \ub54c \ud640\ubc14\uc778\uc774 \uadf8\ub9b0 \ud559\uc790\uc758 \uc606\uc5bc\uad74\uacfc \ucc45\uc0c1 \uc704\uc758 \uc2dc\uac04 \ubaa8\ud53c \uc637\uacfc \ud39c, \ub0ae\ucd98 \ub208\uae38\uc744 \ub530\ub77c \ud55c \uc0ac\ub78c\uc758 \uc77c\uc774 \ucd08\uc0c1\uc5d0 \ub2f4\uae30\ub294 \ubc29\uc2dd\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Art \ubb38\ud654 \ucd08\uc0c1\ud654 \uc18d \uc0ac\ub78c\uc740 \uc6b0\ub9ac\uc5d0\uac8c \uc2dc\uc120\uc744 \ubcf4\ub0b4\uc9c0 \uc54a\ub294\ub2e4. \uace0\uac1c\ub97c \uc870\uae08 \uc219\uc774\uace0 \ucc45\uc0c1 \uc704\uc5d0 \uc190\uc744 \ub454 \ucc44 \uae00\uc744 \uc4f4\ub2e4. \uad00\uac1d\uc5d0\uac8c \uc790\uae30\ub97c \uc18c\uac1c\ud558\ub824\ub294 \uc790\uc138\ubcf4\ub2e4 \uc9c0\uae08 \ud558\ub294 \uc77c\uc5d0 \ubab0\ub450\ud55c \ubaa8\uc2b5\uc774\ub2e4. \ud640\ubc14\uc778\uc758 \u3008\uc5d0\ub77c\uc2a4\ubb34\uc2a4\uc758 \ucd08\uc0c1\u3009\uc740 \uadf8 \uc870\uc6a9\ud55c \uc2dc\uac04\uc744 \uc911\uc2ec\uc5d0 \ub193\ub294\ub2e4. \uc5d0\ub77c\uc2a4\ubb34\uc2a4\uac00 \ub204\uad6c\uc778\uc9c0 \ucc98\uc74c\uc5d0\ub294 \ubab0\ub77c\ub3c4 \uad1c\ucc2e\ub2e4. \uba3c\uc800 \uc190\uacfc \uc5bc\uad74\uc774 \uc5b4\ub514\ub97c \ud5a5\ud558\ub294\uc9c0 \ubcf4\uace0, \uadf8\uac00 \uc778\ubb38\uc8fc\uc758\uc790\ub85c \uc54c\ub824\uc9c4 \ud559\uc790\ub77c\ub294 \uc815\ubcf4\ub97c \ubcf4\ud0dc \ubcf4\uc790. \uc778\ubb3c\uc758 \uc774\ub984\uacfc \ud654\uba74\uc758 \uc138\ubd80\uac00 \uc5f0\uacb0\ub418\uba74\uc11c \ucd08\uc0c1\ud654\uac00 \uc77d\ud788\uae30 \uc2dc\uc791\ud55c\ub2e4. \uc778\ubb3c\uc740 \uac70\uc758 \uc606\ubaa8\uc2b5\uc73c\ub85c \uc549\uc544 \uc788\ub2e4. \uc815\uba74\uc5d0\uc11c \uc11c\ub85c \ub208\uc744 \ub9de\ucd94\ub294 \ucd08\uc0c1\uacfc \ub2ec\ub9ac, \uad00\uac1d\uc740 \uadf8\uac00 \ubb34\uc5c7\uc744 \ubcf4\uace0 \uc788\ub294\uc9c0 \ub530\ub77c\uac00\uac8c \ub41c\ub2e4. \ub208\uae38\uc740 \ucc45\uc0c1 \ucabd\uc73c\ub85c \ub0b4\ub824\uc624\uace0 \uc190\uc758 \uc6c0\uc9c1\uc784\uacfc \uc774\uc5b4\uc9c4\ub2e4. \uc5bc\uad74\uc774 \uad00\uac1d\uc5d0\uac8c \ubaa8\ub4e0 \uc8fc\uc758\ub97c \uc8fc\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc7a5\uba74\uc758 \uc131\uaca9\uc744 \ub9cc\ub4e0\ub2e4. \uc6b0\ub9ac\ub294 \ub204\uad70\uac00\ub97c \uc548\ub2e4\uace0 \ud560 \ub54c \uc5bc\uad74\uc744 \uae30\uc5b5\ud558\ub294 \uc77c\uc744 \uba3c\uc800 \ub5a0\uc62c\ub9ac\uace4 \ud55c\ub2e4. \uadf8\ub7ec\ub098 \uc774 \uadf8\ub9bc\uc5d0\uc11c\ub294 \uc5bc\uad74\uc744 \ubcf4\ub294 \ubc29\uc2dd \uc790\uccb4\uac00 \uc77c\ud558\ub294 \uc790\uc138\uc640 \uc5f0\uacb0\ub41c\ub2e4. \uc0ac\ub78c\uc758 \uc815\uccb4\uc131\uc744 \ud45c\uc815\ub9cc\uc774 \uc544\ub2c8\ub77c \uc5b4\ub5a4 \ud65c\ub3d9 \uc18d\uc5d0\uc11c \uc774\ud574\ud560 \uc218 \uc788\ub294\uc9c0 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uc190\uc5d0\ub294 \uae00\uc744 \uc4f0\ub294 \ub3c4\uad6c\uac00 \uc788\uace0 \uc885\uc774 \uc704\uc5d0\uc11c \uc77c\uc774 \uc9c4\ud589\ub41c\ub2e4. \uc190\uc744 \uba3c\uc800 \ubcf4\uace0 \uc5bc\uad74\ub85c \ub3cc\uc544\uc624\uba74 \ub0ae\ucd98 \ub208\uae38\uc774 \ub2e8\uc21c\ud788 \uc218\uc90d\uac70\ub098 \uce68\uc6b8\ud55c \ud45c\uc815\uc73c\ub85c\ub9cc \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uae00\uc744 \uc4f0\ub294 \ud589\ub3d9\uacfc \uad00\ub828\ub41c \uc790\uc138\ub85c \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uc774 \uc21c\uc11c\uac00 \uac10\uc0c1\uc758 \uc720\uc77c\ud55c \ubc29\ubc95\uc740 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \uc5bc\uad74\uc5d0\uc11c \uc131\uaca9\uc744 \uace7\ubc14\ub85c \ud310\uc815\ud558\ub824\ub294 \uc2b5\uad00\uc744 \uc7a0\uc2dc \ub2a6\ucd9c \uc218 \uc788\ub2e4. \uc9c0\uae08 \ubb34\uc5c7\uc744 \ud558\ub294\uac00\ub97c \uba3c\uc800 \ubcf4\ub294 \uac83\uc774\ub2e4. \uc0ac\ub78c\uc758 \ubab8\uc9d3\uc744 \uad6c\uccb4\uc801\uc778 \uc77c\uacfc \ud568\uaed8 \uc0b4\ud53c\uba74 \uadfc\uac70 \uc5c6\uc774 \ub9c8\uc74c\uc18d \uc774\uc57c\uae30\ub97c \ubd99\uc774\ub294 \uc77c\ub3c4 \uc904\uc5b4\ub4e0\ub2e4. \uc5d0\ub77c\uc2a4\ubb34\uc2a4\ub294 \ub450\ud23c\ud55c \ubaa8\ud53c \uc637\uacfc \uc5b4\ub450\uc6b4 \ubaa8\uc790\ub97c \uc4f0\uace0 \uc788\ub2e4. \uba38\ub9ac\uc640 \uc5b4\uae68\ub97c \uac10\uc2fc \ub113\uc740 \uba74\uc774 \uc5bc\uad74\uacfc \uc190\uc758 \ubc1d\uc740 \ubd80\ubd84\uc744 \ubc1b\uccd0 \uc900\ub2e4. \ubb34\uc5c7\uc774 \uc5b4\ub461\uace0 \ubb34\uc5c7\uc774 \ub4dc\ub7ec\ub098\ub294\uc9c0 \ube44\uad50\ud558\uba74 \ud654\uba74\uc758 \uc911\uc2ec\uc744 \ub290\ub084 \uc218 \uc788\ub2e4. \uc637\uc774 \ub2f9\uc2dc\uc758 \uc5b4\ub5a4 \uc0dd\ud65c \uc870\uac74\uacfc \uad00\ub828\ub418\ub294\uc9c0 \ub354 \uc5f0\uad6c\ud560 \uc218 \uc788\uc9c0\ub9cc, \uc774\ubbf8\uc9c0 \ud558\ub098\ub85c \ubaa8\ub4e0 \uc2e0\ubd84\uacfc \uacbd\uc81c \uc0c1\ud0dc\ub97c \uacc4\uc0b0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc9c0\uae08\uc740 \uc9c8\uac10\uacfc \uc0c9\uc774 \uc778\ubb3c\uc758 \uc874\uc7ac\uac10\uc744 \uc5b4\ub5bb\uac8c \ub9cc\ub4dc\ub294\uc9c0 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uc791\uc740 \uc7a5\uc2dd\ubcf4\ub2e4 \ub113\uc740 \ucc28\ub9bc\uc0c8\uc758 \ub369\uc5b4\ub9ac\uac00 \uc911\uc694\ud55c \ucd08\uc0c1\uc774\ub2e4. \uc5d0\ub77c\uc2a4\ubb34\uc2a4\ub294 \uc778\ubb38\uc8fc\uc758\uc790\ub85c \uc54c\ub824\uc838 \uc788\ub2e4. \uc774 \ub9e5\ub77d\uc758 \uc778\ubb38\uc8fc\uc758\ub294 \uc0ac\ub78c\uc5d0\uac8c \uce5c\uc808\ud558\uc790\ub294 \ud0dc\ub3c4\ub9cc\uc774 \uc544\ub2c8\ub77c \uc5b8\uc5b4\uc640 \uace0\uc804, \ubb38\ud5cc\uc744 \uacf5\ubd80\ud558\uace0 \uc77d\ub294 \ud65c\ub3d9\uacfc \uc5f0\uacb0\ub41c \ub9d0\uc774\ub2e4. \uadf8\ub9bc\uc758 \ud39c\uacfc \uc885\uc774, \uc9d1\uc911\ud558\ub294 \uc790\uc138\ub97c \uadf8 \uc815\ubcf4\uc640 \ud568\uaed8 \ubcfc \uc218 \uc788\ub2e4. \ud55c \uc7a5\uc758 \ucd08\uc0c1\uc774 \uadf8\uc758 \uc0ac\uc0c1\uc744 \ubaa8\ub450 \uc124\uba85\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uadf8\ub7ec\ub098 \uc778\ubb3c\uc774 \uc5b4\ub5a4 \uc77c\uc744 \ud558\ub294 \uc0ac\ub78c\uc778\uc9c0 \uc54c\uace0 \ub098\uba74 \uc791\uac00\uac00 \ubb34\uc5c7\uc744 \uc911\uc2ec\uc5d0 \ub193\uc558\ub294\uc9c0 \ub354 \uad6c\uccb4\uc801\uc73c\ub85c \ubcf4\uc778\ub2e4. \uad8c\ub825\uc744 \ub4dc\ub7ec\ub0b4\ub294 \ud070 \ub3c4\uad6c\ub098 \ubb34\uae30 \ub300\uc2e0 \uae00\uc744 \uc4f0\ub294 \ud589\uc704\uac00 \ud654\uba74\uc758 \uc911\uc2ec\uc774\ub77c\ub294 \uc810\uc774 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \ub4a4\ucabd\uc5d0\ub294 \ubb34\ub2ac\uac00 \uc788\ub294 \ucee4\ud2bc\uc774 \ubcf4\uc778\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubc30\uacbd\uc774 \uc778\ubb3c\ubcf4\ub2e4 \ud06c\uac8c \uc774\uc57c\uae30\ub97c \ub04c\uace0 \uac00\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc5bc\uad74\uacfc \uc190, \uc637\uc758 \uba74\uc744 \ubcf8 \ub4a4 \ucee4\ud2bc\uc73c\ub85c \ub208\uc744 \uc62e\uae30\uba74 \uc778\ubb3c\uc758 \uc724\uacfd\uacfc \uc8fc\ubcc0\uc758 \uad00\uacc4\ub97c \ub290\ub084 \uc218 \uc788\ub2e4. \ubaa8\ub4e0 \uc7a5\uc2dd\uc744 \uc0c1\uc9d5 \uc0ac\uc804\uc73c\ub85c \ud574\ub3c5\ud558\ub824 \uc560\uc4f8 \ud544\uc694\ub294 \uc5c6\ub2e4. \ubc18\ubcf5\ub418\ub294 \ubb34\ub2ac\uc640 \ubd80\ub4dc\ub7fd\uac8c \uaebe\uc774\ub294 \uc637, \uc5bc\uad74\uc758 \uc120\uc774 \uc11c\ub85c \ub2e4\ub978 \ub9ac\ub4ec\uc744 \ub9cc\ub4e0\ub2e4\ub294 \uc810\uc744 \ubcf4\uc790. \uc815\uc9c0\ub41c \uc778\ubb3c \ud558\ub098\uc758 \uadf8\ub9bc\uc5d0\uc11c\ub3c4 \ubaa8\uc591\uacfc \uc7ac\ub8cc\ub97c \ube44\uad50\ud558\uba70 \ubcfc \uc77c\uc774 \ub0a8\uc544 \uc788\ub2e4. \ubcf4\ud1b5 \ucd08\uc0c1\ud654\ub97c \ucc0d\uac70\ub098 \uadf8\ub9b0\ub2e4\uace0 \ud558\uba74 \ud3c9\uc18c\uc758 \uc77c\uc744 \uba48\ucd94\uace0 \uc790\uc138\ub97c \uc7a1\ub294 \uc7a5\uba74\uc744 \ub5a0\uc62c\ub9b0\ub2e4. \uc774 \uc791\ud488\uc740 \uc77c\ud558\ub294 \ubaa8\uc2b5 \uc790\uccb4\ub97c \uc778\ubb3c \uc18c\uac1c\uc758 \ubc29\uc2dd\uc73c\ub85c \uc0bc\ub294\ub2e4. \uadf8\ub798\uc11c \uad00\uac1d\uc740 \ud55c \uc0ac\ub78c\uc774 \ubcf4\ub0b4\ub294 \uc2dc\uac04\uc758 \uc77c\ubd80\ub97c \ubcf4\uac8c \ub418\ub294 \ub4ef\ud55c \ub290\ub08c\uc744 \ubc1b\uc744 \uc218 \uc788\ub2e4. \ubb3c\ub860 \uc2e4\uc81c \uc791\uc5c5 \uc911 \uc6b0\uc5f0\ud788 \ucc0d\ud78c \uc0ac\uc9c4\uacfc\ub294 \ub2e4\ub974\ub2e4. \ud654\uac00\ub294 \uc778\ubb3c\uc758 \ubc29\ud5a5\uacfc \uc190, \ubb3c\uac74\uacfc \ubc30\uacbd\uc744 \uc120\ud0dd\ud574 \ud654\uba74\uc744 \ub9cc\ub4e0\ub2e4. \uc790\uc5f0\uc2a4\ub7ec\uc6b4 \uc778\uc0c1\uacfc \uc138\uc2ec\ud55c \uad6c\uc131\uc740 \ud568\uaed8 \uc874\uc7ac\ud55c\ub2e4. \uadf8\uac83\uc744 \uc54c\uace0 \ub098\uba74 \uc870\uc6a9\ud55c \uadf8\ub9bc\uc774 \ubb34\uc2ec\ud558\uac8c \ub9cc\ub4e4\uc5b4\uc9c4 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\uc774 \ubcf4\uc778\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \uc61b \ub8e8\ube0c\ub974 \ub3c4\ub85d\uc5d0 \uc218\ub85d\ub41c \uc2e4\uc81c \uc791\ud488\uc758 \uc0c9\ucc44 \uc7ac\ud604 \ub3c4\ud310\uc774\ub2e4. \ud604\ub300\uc778\uc774 \ube44\uc2b7\ud55c \ud559\uc790\ub97c \uc0c8\ub85c \uadf8\ub9b0 \uc0bd\ud654\uac00 \uc544\ub2c8\ub77c \ud640\ubc14\uc778\uc758 \ud654\uba74 \uad6c\uc131\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc790\ub8cc\ub2e4. \uc5bc\uad74\uacfc \uc190, \ucc28\ub9bc\uc0c8\uc758 \ud070 \uad00\uacc4\ub97c \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \uc61b \uc778\uc1c4\uc758 \uc0c9\uacfc \uc138\ubd80\ub294 \uc624\ub298 \uc2e4\ubb3c\uc744 \uc644\uc804\ud788 \ub300\uc2e0\ud558\uc9c0 \uc54a\ub294\ub2e4. \uadf8\ub807\ub2e4\uace0 \uac10\uc0c1\uc774 \uc2dc\uc791\ub418\uc9c0 \ubabb\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc791\uc740 \ud39c \ub05d\uc758 \ubaa8\ub4e0 \uc120\uc744 \ub9de\ud788\ub824 \ud558\uae30\ubcf4\ub2e4, \ub208\uae38\uc774 \uc5b4\ub514\ub85c \ub0b4\ub824\uac00\uace0 \uc190\uc774 \uc5b4\ub5a4 \ubc29\ud5a5\uc744 \ud5a5\ud558\ub294\uc9c0\ubd80\ud130 \ubcf4\uba74 \ub41c\ub2e4. \uac00\uae4c\uc6b4 \ub2e8\uc11c\uac00 \ucda9\ubd84\ud55c \ucd9c\ubc1c\uc810\uc774 \ub41c\ub2e4. \uadf8\ub9bc\uc744 \ubcf8 \ub4a4 \uc5d0\ub77c\uc2a4\ubb34\uc2a4\ub77c\ub294 \uc774\ub984\uacfc \ud568\uaed8 \uae00\uc744 \uc4f0\ub294 \uc190\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc5b4\ub5a4 \uc0ac\ub78c\uc744 \uae30\uc5b5\ud558\ub294 \uc77c\uc740 \uc774\ub984\uacfc \uc0dd\ubab0\ub144\uc758 \ubaa9\ub85d\ub9cc\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \uadf8\uac00 \ubb34\uc5c7\uc744 \ud558\ub294 \uc0ac\ub78c\uc73c\ub85c \ud45c\ud604\ub418\uc5c8\ub294\uc9c0 \uc544\ub294 \uac83\ub3c4 \ud558\ub098\uc758 \uc9c0\uc2dd\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \ub2e4\ub978 \ud559\uc790\uc758 \ucd08\uc0c1\uc744 \ub9cc\ub098\uba74 \ucc45\uc744 \ub4e4\uace0 \uc788\ub294\uc9c0, \uad00\uac1d\uc744 \ubcf4\ub294\uc9c0, \uc77c\ud558\ub294 \ubaa8\uc2b5\uc744 \ubcf4\uc5ec \uc8fc\ub294\uc9c0 \ube44\uad50\ud574 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uac19\uc740 \uc885\ub958\uc758 \uc0ac\ub78c\uc744 \uadf8\ub9b0 \ucd08\uc0c1\ub4e4\ub3c4 \uc11c\ub85c \ub2e4\ub978 \uc120\ud0dd\uc744 \ud55c\ub2e4. \ud640\ubc14\uc778\uc758 \uc870\uc6a9\ud55c \ucc45\uc0c1\uc740 \uadf8\ub7f0 \ucc28\uc774\ub97c \uc54c\uc544\ubcf4\uac8c \ud558\ub294 \uc88b\uc740 \uc2dc\uc791\uc774\ub2e4."}, {"id": "inkstone-water-dropper", "title": "\ubcbc\ub8e8\ud568 \uc18d \ud574\ud0dc\uc758 \uc785\uc5d0\ub294 \uc791\uc740 \uad6c\uba4d\uc774 \uc788\ub2e4", "summary": "\uac80\uc740 \uce60\ud568\uc758 \ub69c\uaed1\uc5d0\ub294 \ubd80\ucc44\uac00, \uc548\ucabd\uc5d0\ub294 \uc791\uc740 \ud574\ud0dc\uac00 \uc788\uc2b5\ub2c8\ub2e4. \uc7a5\uc2dd\uacfc \uc4f0\uc784\uc774 \ud55c \uc0c1\uc790\uc5d0\uc11c \ub9cc\ub0a9\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Art", "url": "stories/inkstone-water-dropper/index.html", "image": "media/inkstone-water-dropper.jpg", "alt": "\ub69c\uaed1\uc744 \uc5f4\uc5b4 \ubcbc\ub8e8\uc640 \uc791\uc740 \ud574\ud0dc \ubaa8\uc591 \uc5f0\uc801\uc744 \ud568\uaed8 \ubcf4\uc5ec \uc8fc\ub294 \ub098\uc804\uce60\uae30\ubd80\ucc44\ubb34\ub2ac\uc5f0\uac11 \uc0ac\uc9c4", "text": "\ubcbc\ub8e8\ud568 \uc18d \ud574\ud0dc\uc758 \uc785\uc5d0\ub294 \uc791\uc740 \uad6c\uba4d\uc774 \uc788\ub2e4 \uae00\uc4f0\uae30 \ub3c4\uad6c\ub97c \ub2f4\uc740 \uc0c1\uc790\uc5d0\uc11c \ub9cc\ub098\ub294 \ub73b\ubc16\uc758 \ub3d9\ubb3c \uac80\uc740 \uce60\ud568\uc758 \ub69c\uaed1\uc5d0\ub294 \ubd80\ucc44\uac00, \uc548\ucabd\uc5d0\ub294 \uc791\uc740 \ud574\ud0dc\uac00 \uc788\uc2b5\ub2c8\ub2e4. \uc7a5\uc2dd\uacfc \uc4f0\uc784\uc774 \ud55c \uc0c1\uc790\uc5d0\uc11c \ub9cc\ub0a9\ub2c8\ub2e4. Art \ubb38\ud654 \uac80\uc740 \uce60\uc744 \ud55c \uc0c1\uc790\uc5d0 \ubc18\uc9dd\uc774\ub294 \ubd80\ucc44 \ubb34\ub2ac\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \uac89\ubaa8\uc2b5\ub9cc \ubcf4\uba74 \uc7a5\uc2dd\ud488\uc744 \ub2f4\uc740 \ud568\uc77c \uac83 \uac19\ub2e4. \uadf8\ub7f0\ub370 \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc18c\uac1c\ud558\ub294 \uc774 \ubb3c\uac74\uc758 \uc774\ub984\uc740 \u300c\ub098\uc804\uce60\uae30\ubd80\ucc44\ubb34\ub2ac\uc5f0\uac11\u300d\uc774\ub2e4. \ubcbc\ub8e8\uc640 \uc5f0\uc801\uc744 \ud568\uaed8 \ubcf4\uad00\ud558\ub294 \uc0c1\uc790\ub2e4. \u2018\uc5f0\uc801\u2019\uc774\ub77c\ub294 \ub0af\uc120 \ub9d0\uc740 \uc7a0\uae50 \ub4a4\ub85c \ub450\uc5b4\ub3c4 \uc88b\ub2e4. \uc774 \uc0c1\uc790 \uc548\uc5d0\ub294 \uc791\uc740 \ud574\ud0dc \ubaa8\uc591\uc758 \uae08\uc18d \ubb3c\uac74\uc774 \ub4e4\uc5b4 \uc788\uace0, \uadf8 \ub4f1\uc5d0 \ud558\ub098, \uc785\uc5d0 \ud558\ub098 \uad6c\uba4d\uc774 \uc788\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc5d0 \ub530\ub974\uba74 \ud568\uc758 \uc548\ucabd \uac00\uc6b4\ub370\ub294 \ubcbc\ub8e8 \ubaa8\uc591\uc5d0 \ub9de\uac8c \ud30c\uc5ec \uc788\ub2e4. \ubcbc\ub8e8\ub97c \uadf8 \uc790\ub9ac\uc5d0 \ub07c\uc6cc \ub123\uc5b4 \ubcf4\uad00\ud558\ub3c4\ub85d \ud55c \uac83\uc774\ub2e4. \uc5f0\uc801\uc744 \uc704\ud55c \ud648\ub3c4 \uc788\uc5b4 \uc27d\uac8c \uc6c0\uc9c1\uc774\uc9c0 \uc54a\ub3c4\ub85d \ud588\ub2e4. \uadf8\ub0e5 \ub113\uc740 \uc0c1\uc790\uc5d0 \ub3c4\uad6c\ub97c \ub123\uc5b4 \ub454 \uac83\uacfc\ub294 \ub2e4\ub974\ub2e4. \uc548\uc5d0 \ub4e4\uc5b4\uac08 \ubb3c\uac74\uc758 \ubaa8\uc591\uc744 \uc0dd\uac01\ud574 \uc790\ub9ac\ub97c \ub9c8\ub828\ud588\ub2e4. \uc624\ub298\uc758 \uc548\uacbd\uc9d1\uc774\ub098 \ub3c4\uad6c \ubcf4\uad00\ud568\uc5d0\uc11c\ub3c4 \ub9cc\ub098\ub294 \uc775\uc219\ud55c \uc0dd\uac01\uc774\ub2e4. \ub69c\uaed1\uc774 \uae4a\ub2e4\ub294 \uc810\ub3c4 \ub208\uc5d0 \ub748\ub2e4. \ub69c\uaed1\uacfc \ubab8\uccb4\ub97c \ub36e\uc73c\uba74 \ubab8\uccb4\uc758 \ubc14\ub2e5 \ubd80\ubd84\ub9cc \ubcf4\uc774\ub294 \ud615\ud0dc\ub77c\uace0 \ud55c\ub2e4. \ub2eb\uc558\uc744 \ub54c\uc758 \ub2e8\uc815\ud55c \ubaa8\uc2b5\uacfc \uc5f4\uc5c8\uc744 \ub54c\uc758 \uc54c\ub9de\uc740 \uc790\ub9ac\uac00 \ud55c \ubb3c\uac74 \uc548\uc5d0 \uc788\ub2e4. \uc5f0\uc801\uc740 \ubcbc\ub8e8\uc5d0 \uc4f8 \ubb3c\uc744 \ub2f4\ub294 \ub3c4\uad6c\ub2e4. \uc774 \ud568\uc758 \uc5f0\uc801\uc740 \ud574\ud0dc \ubaa8\uc591\uc774\uba70, \ub4f1 \ubd80\ubd84\uc5d0 \ubb3c\uc744 \ub123\ub294 \uad6c\uba4d\uc774 \uc788\uace0 \uc785 \ubd80\ubd84\uc5d0\ub294 \ubb3c\uc774 \ub098\uc624\ub294 \uc791\uc740 \ub465\uadfc \uad6c\uba4d\uc774 \ub6ab\ub824 \uc788\ub2e4. \ub3d9\ubb3c\uc758 \uc5bc\uad74\uc744 \uc54c\uc544\ubcf8 \ub2e4\uc74c\uc5d0 \uad6c\uba4d\uc758 \uc704\uce58\ub97c \ubcf4\uba74 \uc4f0\uc784\ub3c4 \ud568\uaed8 \ub4dc\ub7ec\ub09c\ub2e4. \uc7a5\uc2dd\uc744 \uc704\ud574 \ub354\ud55c \uc785\uc774 \ubb3c\uc744 \ub0b4\ubcf4\ub0b4\ub294 \uc790\ub9ac\uc774\uae30\ub3c4 \ud558\ub2e4. \ubb3c\uac74\uc758 \uae30\ub2a5\uc774 \uc0dd\uae40\uc0c8 \uc548\uc73c\ub85c \ub4e4\uc5b4\uac00 \uc788\ub2e4. \uc0ac\uc9c4\uc73c\ub85c \uad6c\uba4d\uc774 \ubaa8\ub450 \ub610\ub837\ud558\uc9c0 \uc54a\ub354\ub77c\ub3c4 \ubc15\ubb3c\uad00 \uc124\uba85\uc744 \ub530\ub77c \uc704\uce58\ub97c \uc9d0\uc791\ud574 \ubcfc \uc218 \uc788\ub2e4. \ud574\ud0dc\uac00 \uc65c \uadf8 \uc0c1\uc790 \uc548\uc5d0 \uc788\ub294\uc9c0 \uc54c\uace0 \ub098\uba74 \uc791\uc740 \ub3d9\ubb3c\uc744 \ubcf4\ub294 \ub208\uc774 \uc870\uae08 \ub2ec\ub77c\uc9c4\ub2e4. \uba39\uacfc \ubcbc\ub8e8\ub97c \uc0ac\uc6a9\ud558\ub294 \uae00\uc4f0\uae30\uc5d0\ub294 \ubb3c\uc744 \ub9c8\ub828\ud558\uace0 \ub3c4\uad6c\ub97c \uc81c\uc790\ub9ac\uc5d0 \ub450\ub294 \uc77c\uc774 \ub530\ub77c\uc628\ub2e4. \uc644\uc131\ub41c \uae00\uc528\ub9cc \ubcf4\uc544\uc11c\ub294 \uc798 \ub4dc\ub7ec\ub098\uc9c0 \uc54a\ub294 \uc2dc\uac04\uc774\ub2e4. \ubcbc\ub8e8\ud568\uc740 \uadf8 \uc900\ube44\ub97c \ud55c \ubb3c\uac74 \uc548\uc5d0 \ubaa8\uc544 \ub193\ub294\ub2e4. \uc5b4\ub290 \ub3c4\uad6c\ub97c \uc5b4\ub514\uc5d0 \ub450\uace0 \ub2e4\uc2dc \uaebc\ub0bc\uc9c0 \uc0dd\uac01\ud55c \uad6c\uc870\uac00 \uc788\uc5b4\uc57c \uc0ac\uc6a9\ud558\ub294 \uc190\ub3c4 \ub2e4\uc74c \ud589\ub3d9\uc744 \ucc3e\uae30 \uc27d\ub2e4. \uc774 \ud568\uc758 \uc548\ucabd\uc5d0 \ub3c4\uad6c \ubaa8\uc591\uc5d0 \ub9de\ucd98 \ud648\uc774 \uc788\ub2e4\ub294 \uc124\uba85\uc740 \uadf8\ub798\uc11c \uc911\uc694\ud558\ub2e4. \ub123\uc744 \uc218 \uc788\ub294 \uacf5\uac04\uc744 \ud06c\uac8c \ub9cc\ub4e4\uae30\ub9cc \ud55c \uac83\uc774 \uc544\ub2c8\ub2e4. \ub4e4\uc5b4\uac08 \ubb3c\uac74\uc758 \uc724\uacfd\uc5d0 \ub9de\ucdb0 \uc790\ub9ac\ub97c \ub098\ub204\uc5c8\ub2e4. \uc624\ub298\uc758 \ub3c4\uad6c \uc0c1\uc790\uc640 \ube44\uad50\ud558\ub294 \uac83\uc740 \uc4f0\uc784\uc744 \uc774\ud574\ud558\ub294 \ube44\uc720\uc774\uba70, \ub2f9\uc2dc \uc0ac\uc6a9\uc790\uac00 \uac19\uc740 \ub9d0\uc744 \ud588\ub2e4\ub294 \uae30\ub85d\uc744 \ub73b\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ubb3c\uac74\uc758 \ubc30\uce58\uac00 \uae00\uc4f0\uae30\uc758 \uc900\ube44\ub97c \ub3c4\uc654\ub2e4\ub294 \uc810\uc744 \ubcfc \uc218 \uc788\ub2e4. \ubb3c\uc740 \ub4f1 \ucabd\uc758 \uc785\uc218\uad6c\ub85c \ub4e4\uc5b4\uac00\uace0 \uc785 \ucabd\uc758 \uc791\uc740 \uad6c\uba4d\uc73c\ub85c \ub098\uc628\ub2e4. \ud558\ub098\uc758 \ud615\uc0c1\uc5d0\uc11c \ubb3c\uc744 \ucc44\uc6b0\ub294 \uc790\ub9ac\uc640 \ub0b4\ubcf4\ub0b4\ub294 \uc790\ub9ac\uac00 \ub098\ub25c\ub2e4. \uc870\uac01\uc744 \ubcf4\ub294 \ub208\uc5d0\uc11c \ub3c4\uad6c\ub97c \uc4f0\ub294 \ub208\uc73c\ub85c \ubc14\uafb8\uba74 \uac19\uc740 \ubab8\uc774 \ud1b5\ub85c\ub97c \uac00\uc9c4 \uc6a9\uae30\ub85c \ubcf4\uc778\ub2e4. \uc7a5\uc2dd\uacfc \uae30\ub2a5\uc774 \ubcc4\ub3c4\uc758 \ubd80\ud488\uc73c\ub85c\ub9cc \ub098\ub258\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub358 \uac83\uc774\ub2e4. \uadf8\ub807\ub2e4\uace0 \uad6c\uba4d\uc758 \uc704\uce58\ub9cc\uc73c\ub85c \ub2f9\uc2dc \ubb3c\uc744 \ub530\ub974\ub294 \uc190\ub3d9\uc791\uacfc \uc0ac\uc6a9\ub7c9\uc744 \ubaa8\ub450 \uc54c \uc218\ub294 \uc5c6\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc5f0\uc801\uc774\ub77c\ub294 \ub3c4\uad6c\uc758 \uc5ed\ud560\uacfc \ud655\uc778\ub41c \uad6c\uc870\ub97c \uc5f0\uacb0\ud55c\ub2e4. \ubb3c\uc744 \ubcf4\uad00\ud558\uace0 \uc870\uae08\uc529 \uc4f0\ub294 \uc77c\uc744 \ub3d9\ubb3c\uc758 \ubab8 \uc548\uc5d0 \ub2f4\uc558\ub2e4\ub294 \uc810\uc774 \ud765\ubbf8\ub86d\ub2e4. \uae30\ub2a5\uc744 \uc228\uacbc\ub2e4\uae30\ubcf4\ub2e4 \uae30\ub2a5\uc744 \uc990\uae38 \ub9cc\ud55c \ud615\uc0c1\uc73c\ub85c \ub9cc\ub4e0 \ubb3c\uac74\uc73c\ub85c \uc77d\uc5b4 \ubcfc \uc218 \uc788\ub2e4. \uae4a\uc740 \ub69c\uaed1\uc740 \ub2eb\uc740 \uc0c1\ud0dc\uc5d0\uc11c \ubab8\uccb4\uc758 \ub9ce\uc740 \ubd80\ubd84\uc744 \uac00\ub9b0\ub2e4. \ubc14\uae65\uc5d0\uc11c\ub294 \ud558\ub098\uc758 \ub2e8\uc815\ud55c \ud568\ucc98\ub7fc \ubcf4\uc774\uace0 \uc548\uc744 \uc5f4\uba74 \ubcbc\ub8e8\uc640 \uc5f0\uc801\uc758 \uad6c\uccb4\uc801\uc778 \uc790\ub9ac\uac00 \ub098\ud0c0\ub09c\ub2e4. \ubcf4\uad00\ud558\ub294 \uc2dc\uac04\uacfc \uc0ac\uc6a9\ud558\ub294 \uc2dc\uac04\uc774 \uac19\uc740 \ubaa8\uc2b5\uc744 \uc694\uad6c\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub69c\uaed1\uc774 \ub9cc\ub4e0 \uacbd\uacc4\uac00 \uadf8 \ub450 \uc7a5\uba74\uc744 \ub098\ub204\uc5b4 \uc900\ub2e4. \uc774\ub7f0 \ubb3c\uac74\uc744 \uc0ac\uc9c4 \ud55c \uc7a5\uc73c\ub85c \ubcfc \ub54c\uc5d0\ub294 \ud604\uc7ac \uc5f4\ub824 \uc788\ub294\uc9c0, \ubb34\uc5c7\uc774 \uaebc\ub0b4\uc838 \uc788\ub294\uc9c0\ubd80\ud130 \ud655\uc778\ud558\uba74 \uc88b\ub2e4. \uc804\uc2dc\ub97c \uc704\ud574 \ud3bc\uccd0 \ub193\uc740 \uc0c1\ud0dc\ub97c \uc5b8\uc81c\ub098 \uadf8 \ubaa8\uc2b5\uc73c\ub85c \uc0ac\uc6a9\ud588\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc218\ub0a9 \ub3c4\uad6c\ub294 \ub2eb\ud78c \uc678\ud615\uacfc \uc5f4\ub9b0 \ub0b4\ubd80\ub97c \ud568\uaed8 \ubcfc \ub54c \uc124\uacc4\uc758 \ub73b\uc774 \ub354 \uc798 \ubcf4\uc778\ub2e4. \uac89\uc758 \uc7a5\uc2dd\uacfc \uc548\ucabd\uc758 \ud648\uc774 \uc11c\ub85c \ub2e4\ub978 \uc77c\uc744 \ud558\uace0 \uc788\uc5c8\ub2e4. \ubc15\ubb3c\uad00\uc740 \ud568\uc758 \ubd80\ucc44 \ubaa8\uc591 \ub098\uc804\uacfc \uae08\uc0c9 \ub048 \uc7a5\uc2dd\ub3c4 \uc124\uba85\ud55c\ub2e4. \ubc14\uae65\uc758 \ud45c\uba74\uacfc \ub0b4\ubd80\uc758 \uc5f0\uc801\uc740 \uac01\uae30 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \ubb3c\uac74\uc5d0 \ud45c\uc815\uc744 \ub354\ud55c\ub2e4. \ud558\ub098\ub294 \uba74\uc758 \ubb34\ub2ac\uc640 \ube5b\uc744 \ub9cc\ub4e4\uace0, \ub2e4\ub978 \ud558\ub098\ub294 \uc785\uccb4\uc801\uc778 \ubab8 \uc548\uc5d0 \ubb3c\uc744 \ub2f4\ub294\ub2e4. \ub2e8\uc21c\ud788 \ud654\ub824\ud55c \uc0c1\uc790\ub77c\ub294 \ub9d0\ubcf4\ub2e4 \uac01\uac01 \uc5b4\ub514\uc5d0 \ubb34\uc5c7\uc774 \ub193\uc600\ub294\uc9c0 \ubcf4\uba74 \ub354 \ub9ce\uc740 \uac83\uc774 \uc77d\ud78c\ub2e4. \ud574\ud0dc\ub77c\ub294 \uc774\ub984\uc744 \ub4e4\uc5c8\ub2e4\uace0 \ubaa8\ub4e0 \uc7a5\uc2dd\uc5d0 \uac19\uc740 \uae30\uc6d0\uc744 \ud655\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc774 \ubb3c\uac74\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\ub294 \uc704\uce58\uc640 \uc4f0\uc784\uc744 \uba3c\uc800 \uc0b4\ud3b4\ubcf4\uba74 \ub41c\ub2e4. \uc88b\uc740 \uae00\uc528\uac00 \ub0a8\uae30 \uc804\uc758 \uc870\uc6a9\ud55c \uc900\ube44 \uc2dc\uac04\uc5d0\ub3c4 \uc0ac\ub78c\ub4e4\uc774 \uc0ac\uc6a9\ud558\ub294 \ubb3c\uac74\uc744 \uace0\ub974\uace0 \uafb8\ubbf8\ub294 \ucde8\ud5a5\uc774 \uc788\uc5c8\ub2e4. \uc791\uc740 \uc5f0\uc801\uc758 \uc785\uc740 \uadf8 \uc0dd\ud65c\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \ub73b\ubc16\uc758 \uc785\uad6c\ub2e4. \ud568\uc758 \ub69c\uaed1\uc5d0\ub294 \ubd80\ucc44\ub97c \ubcf8\ub72c \ubb34\ub2ac\uac00 \uc788\ub2e4. \ubd80\ucc44\uc5d0 \ub4e4\uc5b4\uac04 \ubb34\ub2ac\uc640 \ubd80\ucc57\uc0b4, \uad6c\uc2ac\uacfc \uace0\ub9ac\ub294 \ub098\uc804\uc73c\ub85c \ud45c\ud604\ud588\uace0 \ub048\uc740 \uae08\uc0c9 \uc548\ub8cc\ub85c \ub098\ud0c0\ub0c8\ub2e4\uace0 \ud55c\ub2e4. \ub098\uc804\uc740 \ube5b\uc744 \ubc1b\uc73c\uba74 \ubc18\uc9dd\uc774\ub294 \uc7ac\ub8cc\ub2e4. \uc0c1\uc790\uc758 \uae30\ub2a5\ub9cc \uc0dd\uac01\ud558\uba74 \uc5c6\uc5b4\ub3c4 \ub420 \uac83 \uac19\uc740 \ubd80\ubd84\uc774\uc9c0\ub9cc, \uadf8 \ub355\ubd84\uc5d0 \ub2eb\ud78c \ud568\uc5d0\ub3c4 \uc624\ub798 \ubc14\ub77c\ubcfc \uc790\ub9ac\uac00 \uc0dd\uae34\ub2e4. \ub2e4\uc74c\uc5d0 \uc61b \ubb38\ubc29\uad6c\ub97c \ub9cc\ub098\uba74 \uae00\uc528\ub97c \uc4f0\ub294 \ub3c4\uad6c\ub77c\ub294 \uc124\uba85\ub9cc \uc77d\uace0 \uc9c0\ub098\uce58\uc9c0 \uc54a\uc544\ub3c4 \uc88b\uaca0\ub2e4. \ub69c\uaed1\uc758 \ubd80\ucc44\uc5d0\uc11c \uc548\ucabd\uc758 \uc791\uc740 \ud574\ud0dc\uae4c\uc9c0, \uc4f0\ub294 \uc0ac\ub78c\uc758 \uc190\uae38\uc744 \uae30\ub2e4\ub9ac\ub358 \ubb3c\uac74\uc5d0\ub294 \uae30\ub2a5\uacfc \uad6c\uacbd\uac70\ub9ac\uac00 \ub098\ub780\ud788 \ub4e4\uc5b4 \uc788\ub2e4."}, {"id": "italy-print-painting-proposal", "title": "\ud310\ud654 \ud55c \uc7a5\uc774 \ud070 \uadf8\ub9bc\uc758 \uc81c\uc548\uc11c\uac00 \ub418\uc5c8\ub2e4", "summary": "\uc0b4\ubc14\ud1a0\ub974 \ub85c\uc0ac\uac00 \ud310\ud654\ub85c \ubcf4\uc5ec \uc8fc\uace0 \uc2f6\uc5c8\ub358 \ub354 \ud070 \uadf8\ub9bc\uc744 \uc0dd\uac01\ud574 \ubd05\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Art", "url": "stories/italy-print-painting-proposal/index.html", "image": "media/italy-print-painting-proposal.jpg", "alt": "\ud310\ud654 \ud55c \uc7a5\uc774 \ud070 \uadf8\ub9bc\uc758 \uc81c\uc548\uc11c\uac00 \ub418\uc5c8\ub2e4\uc758 \uc8fc\uc81c\ub97c \ud45c\ud604\ud55c AI \uc124\uba85\uc6a9 \uc0bd\ud654. \uc2e4\uc81c \uc791\ud488\uc774\ub098 \uac74\ucd95\ubb3c\uc744 \uadf8\ub300\ub85c \uc7ac\ud604\ud55c \uc774\ubbf8\uc9c0\uac00 \uc544\ub2d9\ub2c8\ub2e4.", "text": "\ud310\ud654 \ud55c \uc7a5\uc774 \ud070 \uadf8\ub9bc\uc758 \uc81c\uc548\uc11c\uac00 \ub418\uc5c8\ub2e4 \uc774\ud0c8\ub9ac\uc544 \ud654\uac00\uac00 \ud6c4\uc6d0\uc790\ub97c \ucc3e\ub358 \ubc29\ubc95 \uc0b4\ubc14\ud1a0\ub974 \ub85c\uc0ac\uac00 \ud310\ud654\ub85c \ubcf4\uc5ec \uc8fc\uace0 \uc2f6\uc5c8\ub358 \ub354 \ud070 \uadf8\ub9bc\uc744 \uc0dd\uac01\ud574 \ubd05\ub2c8\ub2e4. Art \ubb38\ud654 \uadf8\ub9bc\uc744 \ud06c\uac8c \uadf8\ub9ac\uace0 \uc2f6\uc740\ub370 \uadf8 \uc77c\uc744 \ub9e1\uaca8 \uc904 \uc0ac\ub78c\uc774 \uc5c6\ub2e4\uba74 \uc5b4\ub5bb\uac8c \ud560\uae4c. \uc694\uc998\uc774\ub77c\uba74 \uad6c\uc0c1\uc548\uc774\ub098 \uc791\uc740 \uacac\ubcf8\uc744 \ub9cc\ub4e4\uc5b4 \ubcf4\uc5ec \uc904 \uc218 \uc788\uc744 \uac83\uc774\ub2e4. \uc774\ud0c8\ub9ac\uc544\uc758 \uc608\uc220\uac00 \uc0b4\ubc14\ud1a0\ub974 \ub85c\uc0ac\uc5d0\uac8c\ub294 \ud310\ud654\ub77c\ub294 \ubc29\ubc95\uc774 \uc788\uc5c8\ub2e4. \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc740 \uadf8\uc758 \uac70\uc778\ub4e4\uc758 \ucd94\ub77d\uc774\ub77c\ub294 \ud310\ud654\ub97c \uc18c\uac1c\ud558\uba70 \ud070 \uadf8\ub9bc\uc744 \uc2e4\ud604\ud558\uae30 \uc704\ud574 \ud6c4\uc6d0\uc790\uc758 \uad00\uc2ec\uc744 \uc5bb\uc73c\ub824\ub358 \ubaa9\uc801\ub3c4 \uc124\uba85\ud55c\ub2e4. \ud310\ud654\uac00 \uc644\uc131\ub41c \uc791\ud488\uc774\uba74\uc11c \ub2e4\uc74c \uc77c\uc744 \uc81c\uc548\ud558\ub294 \ubb3c\uac74\uc774 \ub41c \uc148\uc774\ub2e4. \ubbf8\uc220\uad00 \ud574\uc124\uc5d0 \ub530\ub974\uba74 \uc791\ud488\uc740 \uac70\uc778\ub4e4\uc774 \uc2e0\ub4e4\uc758 \uc790\ub9ac\ub97c \uacf5\uaca9\ud558\ub824 \ud558\uc790 \uc720\ud53c\ud14c\ub974\uac00 \ubc88\uac1c\ub85c \uadf8\ub4e4\uc744 \ub5a8\uc5b4\ub728\ub9ac\ub294 \uc7a5\uba74\uc744 \ub2f4\ub294\ub2e4. \uc704\ucabd \uad6c\ub984\uc5d0\ub294 \uc2e0\uc774, \uc544\ub798\uc5d0\ub294 \ucd94\ub77d\ud558\ub294 \uac70\uc778\ub4e4\uc774 \ub193\uc774\ub294 \uad6c\uc0c1\uc774\ub2e4. \uc6b0\ub9ac\uac00 \uc5ec\uae30\uc11c \ubcf4\ub294 \uc0bd\ud654\ub294 \uadf8 \ud310\ud654\ub97c \ubcf5\uc81c\ud55c \uac83\uc774 \uc544\ub2c8\ub77c \uc791\uc5c5\uc2e4\uc744 \ub5a0\uc62c\ub9ac\ub3c4\ub85d \ub9cc\ub4e0 \uc124\uba85\uc6a9 \uadf8\ub9bc\uc774\ub2e4. \uc2e4\uc81c \ud654\uba74\uc758 \uad6c\uc131\uc5d0 \uad00\ud55c \uc774\uc57c\uae30\ub294 \ubbf8\uc220\uad00\uc758 \uc791\ud488 \ud574\uc124\uc744 \uadfc\uac70\ub85c \uc77d\uc73c\uba74 \ub41c\ub2e4. \ub85c\uc0ac\ub294 \ud310\ud654\uac00\uc774\uba74\uc11c \ud654\uac00\uc600\uace0 \uc2dc\uc640 \uc5f0\uae30, \uc74c\uc545\uc5d0\uc11c\ub3c4 \ud65c\ub3d9\ud588\ub2e4\uace0 \ubbf8\uc220\uad00\uc740 \uc18c\uac1c\ud55c\ub2e4. \ud55c \uac00\uc9c0 \uc774\ub984\ud45c\ub9cc\uc73c\ub85c \uadf8\uc758 \uc77c\uc744 \ubaa8\ub450 \uc124\uba85\ud558\uae30\ub294 \uc5b4\ub824\uc6b4 \uc778\ubb3c\uc774\uc5c8\ub2e4. \uc774 \ud310\ud654\ub294 \uac19\uc740 \uc8fc\uc81c\uc758 \ud68c\ud654\ub97c \uc81c\uc791\ud560 \uc0dd\uac01\uc744 \uc54c\ub9ac\uace0 \uadf8 \uc77c\uc744 \ud6c4\uc6d0\ud560 \uc0ac\ub78c\uc744 \ucc3e\uae30 \uc704\ud55c \uac83\uc774\uc5c8\ub2e4\uace0 \ud55c\ub2e4. \uc774\ubbf8 \ud55c \ubc88 \ub9cc\ub4e0 \uc774\ubbf8\uc9c0\ub97c \ub2e4\uc74c \uc7ac\ub8cc\uc640 \ub2e4\uc74c \ud06c\uae30\uc758 \uc791\uc5c5\uc73c\ub85c \uc774\uc5b4 \ubcf4\ub824\ub294 \uc2dc\ub3c4\uc600\ub2e4. \ubbf8\uc220\uad00\uc774 \uc124\uba85\ud558\ub294 \uc7a5\uba74\uc5d0\ub294 \ub69c\ub837\ud55c \ubc29\ud5a5\uc774 \uc788\ub2e4. \uac70\uc778\ub4e4\uc740 \uc2e0\ub4e4\uc758 \uc790\ub9ac\ub97c \uacf5\uaca9\ud558\ub824 \ud558\uc9c0\ub9cc \uc720\ud53c\ud14c\ub974\uc758 \ubc88\uac1c\ub97c \ub9de\uc544 \uc544\ub798\ub85c \ucd94\ub77d\ud55c\ub2e4. \uc704\ucabd \uad6c\ub984\uacfc \uc544\ub798\ucabd \ubab8\uc758 \ub300\ube44\uac00 \uc774\uc57c\uae30\ub97c \uad6c\uc131\ud55c\ub2e4. \uc2e0\ud654\uc758 \uc774\ub984\uc744 \ubaa8\ub450 \ubaa8\ub974\ub354\ub77c\ub3c4 \uc5b4\ub290 \ubc29\ud5a5\uc73c\ub85c \ud798\uc774 \uc791\uc6a9\ud558\ub294\uc9c0 \uc54c\uba74 \uc7a5\uba74\uc758 \uae34\uc7a5\uc774 \uc870\uae08 \ubcf4\uc778\ub2e4. \ub2e4\ub9cc \ubcf8\ubb38\uc5d0 \uc2e4\ub9b0 \uc791\uc5c5\uc2e4 \uc0bd\ud654\uc5d0\uc11c \uc6d0\ubcf8 \ud310\ud654\uc758 \uc778\ubb3c \ubc30\uce58\ub97c \uc9c1\uc811 \ud655\uc778\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc2e4\uc81c \ud654\uba74\uc5d0 \ub300\ud55c \uc124\uba85\uc740 \uae30\uad00\uc758 \uc6d0\ubcf8 \ud574\uc124\uc744 \ub530\ub77c \uc77d\ub294 \ubd80\ubd84\uc774\ub2e4. \uadf8\ub9bc\uacfc \uc124\uba85\uc774 \uac01\uac01 \ubb34\uc5c7\uc744 \ubcf4\uc5ec \uc8fc\ub294\uc9c0 \uad6c\ubd84\ud558\uba74 \uc0c1\uc0c1\ud55c \uc7a5\uba74\uc744 \uc0ac\ub8cc\ucc98\ub7fc \ubc1b\uc544\ub4e4\uc774\uc9c0 \uc54a\uc73c\uba74\uc11c\ub3c4 \uc791\ud488\uc758 \uad6c\uc0c1\uc744 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uae30\uad00 \ud574\uc124\uc740 \uc791\ud488 \uc544\ub798\uc5d0 \uc62c\ub77c\uac04 \uc790\uac00 \ub354 \ud070 \ubab0\ub77d\uc744 \uacaa\ub294\ub2e4\ub294 \ucde8\uc9c0\uc758 \uacbd\uace0\uac00 \uc801\ud600 \uc788\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \ucd94\ub77d\ud558\ub294 \ubab8\uacfc \ubb38\uc7a5\uc774 \uc11c\ub85c \uac19\uc740 \ubc29\ud5a5\uc744 \uac00\ub9ac\ud0a4\ub294 \uc148\uc774\ub2e4. \uc774\ubbf8\uc9c0\ub9cc \ubcf4\uace0 \uc2e0\ud654\uc758 \ud55c \uc7a5\uba74\uc73c\ub85c \uc9c0\ub098\ucce4\ub2e4\uba74 \uae00\uc744 \ud1b5\ud574 \uad00\ub78c\uc790\uc5d0\uac8c \uc5b4\ub5a4 \uc0dd\uac01\uc744 \uc694\uad6c\ud558\ub294\uc9c0 \ub2e4\uc2dc \ubcfc \uc218 \uc788\ub2e4. \uadf8 \ubb38\uc7a5\uc744 \uace7\ubc14\ub85c \ud654\uac00\uc758 \ubaa8\ub4e0 \uc815\uce58\uc801 \uc785\uc7a5\uc774\ub098 \uac1c\uc778\uc801 \ubd88\ud589\uc758 \uc554\ud638\ub85c \ud574\uc11d\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5ec\uae30\uc11c \ud655\uc778\ub418\ub294 \uac83\uc740 \uadf8\ub9bc\uc5d0 \ub367\ubd99\uc778 \ub9d0\uc758 \uc5ed\ud560\uc774\ub2e4. \uc2dc\uc778\uc774\uae30\ub3c4 \ud588\ub358 \uc791\uac00\uc758 \ud65c\ub3d9\uacfc \uc5f0\uacb0\ud574 \ubcf4\uba74 \uc774\ubbf8\uc9c0\uc640 \uc5b8\uc5b4\uac00 \uc11c\ub85c \ub2e4\ub978 \ubd84\uc57c\ub85c\ub9cc \ub5a8\uc5b4\uc838 \uc788\uc9c0 \uc54a\uc558\ub2e4\ub294 \uc810\uc774 \ud765\ubbf8\ub86d\ub2e4. \uadf8\ub9bc\uc758 \ubc14\uae65 \uc5ec\ubc31\uc5d0\ub3c4 \uc77d\uc744 \uac83\uc774 \uc788\uc5c8\ub2e4. \ubcf4\ud1b5 \uc6b0\ub9ac\ub294 \uc644\uc131\ud488\uc744 \ubcf8 \ub4a4 \uadf8 \uc791\ud488\uc758 \uc804 \ub2e8\uacc4\ub97c \ucc3e\ub294\ub2e4. \uc774 \uacbd\uc6b0 \ud310\ud654\ub294 \uadf8 \uc790\uccb4\ub85c \uc644\uc131\ud55c \uc791\uc5c5\uc774\uba74\uc11c \uc55e\uc73c\ub85c \ub9cc\ub4e4 \ud68c\ud654\ub97c \uc54c\ub9ac\ub294 \uc81c\uc548\uc774\uae30\ub3c4 \ud588\ub2e4. \uc9c0\uae08 \uc788\ub294 \uc774\ubbf8\uc9c0\uac00 \ub2e4\uc74c \uc7ac\ub8cc\uc758 \uc791\uc5c5\uc744 \uc124\ub4dd\ud558\ub294 \uc5ed\ud560\uc744 \ub9e1\uc558\ub2e4. \uc791\ud488\uc774 \ud63c\uc790 \ub2eb\ud78c \uacb0\uacfc\ubb3c\uc774 \uc544\ub2c8\ub77c \ub2e4\uc74c \uc81c\uc791\uc744 \ud5a5\ud55c \ub300\ud654\uac00 \ub41c \uac83\uc774\ub2e4. \ud68c\ud654\ub97c \uc2e4\uc81c\ub85c \uc81c\uc791\ud558\ub824\uba74 \uc0dd\uac01\uacfc \uc19c\uc528\ub9cc\uc774 \uc544\ub2c8\ub77c \ube44\uc6a9\uacfc \ud6c4\uc6d0\uc774 \ud544\uc694\ud560 \uc218 \uc788\ub2e4. \uae30\uad00\uc774 \ud6c4\uc6d0\uc790\ub97c \ucc3e\uc73c\ub824\ub294 \ubaa9\uc801\uc744 \uc124\uba85\ud558\ub294 \uc774\uc720\ub2e4. \uc774 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uacb0\uad6d \uc5b4\ub290 \ud6c4\uc6d0\uc790\uac00 \ub098\uc130\uace0 \uacc4\ud68d\uc774 \uc5b4\ub5bb\uac8c \ub05d\ub0ac\ub294\uc9c0\uae4c\uc9c0 \ucd94\uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc81c\uc548\uc758 \ubaa9\uc801\uacfc \ub098\uc911\uc758 \uc2e4\ud604 \uc5ec\ubd80\ub294 \uc11c\ub85c \ub2e4\ub978 \uae30\ub85d\uc73c\ub85c \ud655\uc778\ud560 \ubb38\uc81c\ub2e4. \ub85c\uc0ac\uac00 \uadf8\ub9bc\uacfc \ud310\ud654\ubfd0 \uc544\ub2c8\ub77c \uc2dc\uc640 \uc5f0\uae30, \uc74c\uc545\uc5d0\ub3c4 \uad00\uc5ec\ud588\ub2e4\ub294 \uc124\uba85\uc740 \ub2e8\uc21c\ud788 \uc7ac\uc8fc\uac00 \ub9ce\uc558\ub2e4\ub294 \uce6d\ucc2c\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \uc778\ubb3c\uc758 \ubab8\uc9d3\uacfc \uc7a5\uba74\uc758 \uadf9\uc801\uc778 \ub300\ube44, \ubb38\uc7a5\uc774 \ud568\uaed8 \uc788\ub294 \uc791\uc5c5\uc744 \ubcfc \ub54c \uadf8 \ud3ed\ub113\uc740 \uad00\uc2ec\uc744 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ubaa8\ub4e0 \ud615\uc2dd\uc758 \ud2b9\uc9d5\uc744 \ub2e4\ub978 \uc9c1\uc5c5 \ud558\ub098\uc5d0\uc11c \uc9c1\uc811 \uac00\uc838\uc654\ub2e4\uace0 \ud655\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \ud655\uc778\ub41c \ud65c\ub3d9\uc758 \ubc94\uc704\ub294 \uc791\uac00\ub97c \ub9cc\ub098\ub294 \uc785\uad6c\ub97c \ub113\ud600 \uc900\ub2e4. \ud55c \uc0ac\ub78c\uc744 \ud310\ud654\uac00\ub77c\ub294 \ub9d0\ub85c\ub9cc \uae30\uc5b5\ud588\uc744 \ub54c\ubcf4\ub2e4 \uc5ec\ub7ec \ub9e4\uccb4 \uc0ac\uc774\ub97c \uc624\uac04 \uc81c\uc791\uc790\ub85c \ubcfc \uc218 \uc788\ub2e4. \uc791\uc740 \uc885\uc774 \uc704\uc5d0 \ud070 \uc7a5\uba74\uc744 \uc81c\uc548\ud558\uace0 \ub610 \ub2e4\ub978 \uadf8\ub9bc\uc744 \uae30\ub300\ud558\uac8c \ud558\ub294 \uc77c\ub3c4 \uadf8 \ud65c\ub3d9\uc758 \ud55c \ubaa8\uc2b5\uc774\uc5c8\ub2e4. \uc608\uc220\ud488\uc744 \uad6c\uacbd\ud558\ub2e4\uac00 \uadf8\uac83\uc744 \ub9cc\ub4e4\uae30 \uc704\ud55c \uc870\uac74\uae4c\uc9c0 \ubcf4\uac8c \ub418\ub294 \uc774\uc57c\uae30\ub2e4. \uc624\ub298\uc758 \ub208\uc73c\ub85c \ubcf4\uba74 \uc791\uc740 \ubaa8\ud615\uc774\ub098 \uc81c\uc548\uc11c\ub97c \ub9cc\ub4dc\ub294 \uc77c\uacfc \ub2ee\uc544 \ubcf4\uc778\ub2e4. \ub2e4\ub9cc \ud310\ud654\uac00 \ub2e8\uc21c\ud55c \ubbf8\uc644\uc131 \ucd08\uc548\uc774\uc5c8\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ud310\ud654 \uc790\uccb4\ub85c \uc644\uc131\ub41c \uc791\ud488\uc774\uba74\uc11c \ub354 \ud070 \uacc4\ud68d\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc5ed\ud560\ub3c4 \ud55c \uac83\uc774\ub2e4. \ubbf8\uc220\uad00\uc758 \uc791\ud488 \ud558\ub098\ub97c \ubcfc \ub54c \uadf8 \ub4a4\uc5d0 \ubb34\uc5c7\uc744 \ud558\ub824 \ud588\ub294\uc9c0\ub3c4 \uc9c8\ubb38\ud574 \ubcfc \uc218 \uc788\ub2e4. \ub9cc\ub4e0 \uc0ac\ub78c\uc774 \uc774 \uc774\ubbf8\uc9c0\ub85c \ub204\uad6c\ub97c \uc124\ub4dd\ud558\uace0 \uc2f6\uc5c8\ub294\uc9c0 \uc0dd\uac01\ud558\ub294 \uac83\uc774\ub2e4. \uac70\uc778\ub4e4\uc758 \ucd94\ub77d\uc740 \uc2e0\ud654\uc758 \uc7a5\uba74\uc778 \ub3d9\uc2dc\uc5d0 \ud55c \uc608\uc220\uac00\uc758 \ub2e4\uc74c \uc791\uc5c5\uc744 \ud5a5\ud55c \uc81c\uc548\uc774\uae30\ub3c4 \ud588\ub2e4."}, {"id": "jane-austen-life-and-writing", "title": "\uc81c\uc778 \uc624\uc2a4\ud2f4\uc758 \uc0dd\uc560 \u2014 \uc791\uc740 \uac70\uc2e4\uc5d0\uc11c \ub113\uc740 \uc138\uacc4\ub97c \uc4f0\ub2e4", "summary": "\uac00\uc871 \uc804\uae30\uc640 \ud3b8\uc9c0\ub97c \ud1b5\ud574 \uc775\uc219\ud55c \uc5f0\uc560\uc18c\uc124 \ub4a4\uc758 \uc791\uac00 \uc0dd\ud65c\uc744 \ub530\ub77c\uac11\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Literature", "url": "stories/jane-austen-life-and-writing/index.html", "image": "media/jane-austen-life-and-writing.jpg", "alt": "\uc624\uc2a4\ud2f4 \uac00\uc871 \uc804\uae30\uc5d0 \uc2e4\ub9b0 \uc81c\uc778 \uc624\uc2a4\ud2f4\uc758 \uc5ed\uc0ac\uc801 \ucd08\uc0c1 \uc7ac\ud604 \ub3c4\ud310.", "text": "\uc81c\uc778 \uc624\uc2a4\ud2f4\uc758 \uc0dd\uc560 \u2014 \uc791\uc740 \uac70\uc2e4\uc5d0\uc11c \ub113\uc740 \uc138\uacc4\ub97c \uc4f0\ub2e4 \uc2a4\ud2f0\ube10\ud134\uc5d0\uc11c \ucd08\ud134\uae4c\uc9c0, \uac00\uc871\uacfc \uc774\uc0ac\uc640 \ucd9c\ud310\uc758 \uc2dc\uac04 \uac00\uc871 \uc804\uae30\uc640 \ud3b8\uc9c0\ub97c \ud1b5\ud574 \uc775\uc219\ud55c \uc5f0\uc560\uc18c\uc124 \ub4a4\uc758 \uc791\uac00 \uc0dd\ud65c\uc744 \ub530\ub77c\uac11\ub2c8\ub2e4. Literature \ubb38\ud654 \ubb34\ub3c4\ud68c\uc640 \ubc29\ubb38, \uac70\uc2e4\uc758 \ub300\ud654\uc640 \uacb0\ud63c \uc774\uc57c\uae30. \uc81c\uc778 \uc624\uc2a4\ud2f4\uc758 \uc18c\uc124\uc744 \ub5a0\uc62c\ub9ac\uba74 \uc791\uc740 \uc0dd\ud65c \uc7a5\uba74\ub4e4\uc774 \uba3c\uc800 \uc0dd\uac01\ub09c\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \uc548\uc5d0\ub294 \ub3c8\uacfc \uc0c1\uc18d, \ud0c0\uc778\uc758 \ud3c9\uac00\uc640 \uc790\uae30 \ud310\ub2e8\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \uc791\uac00\ub294 \uc775\uc219\ud55c \uacf5\uac04\uc744 \uc881\uc740 \uc138\uacc4\ub85c\ub9cc \ub450\uc9c0 \uc54a\uc558\ub2e4. \uc624\uc2a4\ud2f4\uc740 1775\ub144\uc5d0 \ud0dc\uc5b4\ub098 1817\ub144\uc5d0 \uc138\uc0c1\uc744 \ub5a0\ub0ac\ub2e4. \uadf8\uc758 \uc0dd\uc560\ub97c \uc870\uc6a9\ud55c \uc2dc\uace8\uc5d0\uc11c \uc800\uc808\ub85c \uba85\uc791\uc774 \ub098\uc628 \uc774\uc57c\uae30\ub85c\ub9cc \uc815\ub9ac\ud558\uba74, \uc774\ub3d9\uacfc \uac00\uc871\uc758 \uc0ac\uc815, \uc791\ud488\uc744 \uace0\uce58\uace0 \uc138\uc0c1\uc5d0 \ub0b4\ub193\ub294 \uc2dc\uac04\uc774 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uc774\ubc88\uc5d0\ub294 \uc18c\uc124 \ubc16\uc758 \uc0dd\ud65c\uc744 \uc870\uae08 \ub530\ub77c\uac00 \ubcf4\uc790. \uadf8\ub294 \uc2a4\ud2f0\ube10\ud134\uc758 \ubaa9\uc0ac\uad00\uc5d0\uc11c \uc790\ub790\ub2e4. \uac00\uc871 \uc548\uc5d0\uc11c \ucc45\uc744 \uc77d\uace0 \uae00\uc744 \uc4f0\uba70 \uc774\uc57c\uae30\ub97c \uc990\uae30\ub294 \ud658\uacbd\uc774 \uc788\uc5c8\ub2e4. \uc5b4\ub9b0 \uc2dc\uc808\uc758 \uae00\uc5d0\uc11c\ub3c4 \ubb38\uc7a5\uc744 \ud749\ub0b4 \ub0b4\uace0 \uacfc\uc7a5\ud558\uba70 \uc0ac\ub78c\ub4e4\uc758 \ud0dc\ub3c4\ub97c \uc7ac\ubbf8\uc788\uac8c \ube44\ud2b8\ub294 \ubaa8\uc2b5\uc744 \ubcfc \uc218 \uc788\ub2e4. \ub098\uc911\uc758 \uc815\uad50\ud55c \uc18c\uc124\uc5d0 \uc55e\uc120 \uc5f0\uc2b5\uc758 \uc2dc\uac04\uc774\ub2e4. \uc791\uac00\uc758 \uc7ac\ub2a5\uc744 \uac00\uc871\uc758 \uc601\ud5a5\ub9cc\uc73c\ub85c \ubaa8\ub450 \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \ud63c\uc790 \uba38\ub9bf\uc18d\uc5d0\uc11c \uc774\uc57c\uae30\ub97c \uc644\uc131\ud55c \uc874\uc7ac\ub85c \uc0c1\uc0c1\ud558\uae30\ubcf4\ub2e4, \uae00\uc744 \uc77d\uace0 \ub4e4\uc5b4 \uc904 \uc0ac\ub78c\ub4e4\uc774 \uc788\ub358 \uad6c\uccb4\uc801\uc778 \uc0dd\ud65c\uc744 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ub300\ud654\uc758 \ub9ac\ub4ec\uacfc \ub2e4\ub978 \uc0ac\ub78c\uc758 \ubc18\uc751\uc744 \uc544\ub294 \uac10\uac01\ub3c4 \uc774\ub7f0 \uc138\uacc4\uc640 \ub2ff\uc544 \uc788\uc5c8\uc744 \uac83\uc774\ub2e4. \uc5b8\ub2c8 \uce90\uc120\ub4dc\ub77c\ub294 \uc911\uc694\ud55c \uac00\uc871\uc774\uc790 \ud3b8\uc9c0 \uc0c1\ub300\uc600\ub2e4. \ub0a8\uc544 \uc788\ub294 \ud3b8\uc9c0\ub294 \uc774\uc0ac\uc640 \ubc29\ubb38, \uc0ac\ub78c\ub4e4\uc758 \uc18c\uc2dd\uacfc \uc791\ud488\uc758 \uc9c4\ud589\uc744 \uc804\ud55c\ub2e4. \uc6b0\ub9ac\ub294 \uc18c\uc124\uacfc\ub294 \ub2e4\ub978 \ub9d0\ud22c\uc758 \uc624\uc2a4\ud2f4\uc744 \uadf8 \uae30\ub85d\uc5d0\uc11c \ub9cc\ub098\uae30\ub3c4 \ud55c\ub2e4. \uadf8\ub7ec\ub098 \ubaa8\ub4e0 \ud3b8\uc9c0\uac00 \ub0a8\uc544 \uc788\uc9c0\ub294 \uc54a\ub2e4. \uac00\uc871 \uc804\uae30 \uc790\uccb4\ub3c4 \uce90\uc120\ub4dc\ub77c\uac00 \ud3b8\uc9c0 \uc77c\ubd80\ub97c \uc5c6\uc574\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc124\uba85\ud55c\ub2e4. \uadf8\ub798\uc11c \ub0a8\uc740 \uae30\ub85d\uc758 \ube48\uce78\uc744 \uc0c1\uc0c1\uc73c\ub85c \ubaa8\ub450 \ucc44\uc6cc \uc791\uac00\uc758 \uc18d\ub9c8\uc74c\uc744 \ud655\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uac00\uae4c\uc6b4 \uac00\uc871\uc774 \uc804\ud55c \uc790\ub8cc\ub77c\ub294 \uc7a5\uc810\uacfc \uadf8\ub4e4\uc774 \uace0\ub974\uace0 \ub0a8\uae34 \uae30\ub85d\uc774\ub77c\ub294 \uc131\uaca9\uc744 \ud568\uaed8 \uc77d\uc73c\uba74 \uc88b\ub2e4. \uac00\uc871\uc774 \uc2a4\ud2f0\ube10\ud134\uc744 \ub5a0\ub098 \ubc30\uc2a4\ub85c \uc62e\uae34 \uc77c\uc740 \uc911\uc694\ud55c \uc0dd\ud65c\uc758 \ubcc0\ud654\uc600\ub2e4. \uc775\uc219\ud55c \uc9d1\uc744 \ub5a0\ub098 \uc0ac\ub78c\uacfc \uacf5\uac04\uc744 \uc0c8\ub86d\uac8c \ub9cc\ub098\uac8c \ub41c\ub2e4. \uc774\ud6c4 \uc544\ubc84\uc9c0\uac00 \uc138\uc0c1\uc744 \ub5a0\ub098\uba74\uc11c \uc5b4\uba38\ub2c8\uc640 \uc790\ub9e4\ub4e4\uc758 \uc0dd\ud65c \uc870\uac74\ub3c4 \ub2e4\uc2dc \ub2ec\ub77c\uc84c\ub2e4. \uc774 \uc774\ub3d9\uc744 \uace7\ubc14\ub85c \uc5b4\ub290 \uc18c\uc124 \uc7a5\uba74\uc758 \uc2e4\uc81c \uc6d0\uc778\uc774\ub77c\uace0 \uc5f0\uacb0\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc791\ud488 \uc18d \uc0ac\uac74\uacfc \uc791\uac00\uc758 \uacbd\ud5d8\uc740 \uc77c\ub300\uc77c \ub300\uc751\ud45c\uac00 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \uac70\ucc98\uc640 \uacbd\uc81c\uc801 \uae30\ubc18\uc774 \ubc14\ub014 \ub54c \uae00\uc744 \uc4f0\ub294 \uc0ac\ub78c\uc758 \ud558\ub8e8\ub3c4 \uc601\ud5a5\uc744 \ubc1b\ub294\ub2e4\ub294 \uc810\uc740 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uc548\uc815\ub41c \uc791\uc5c5\uc740 \ub9c8\uc74c\ub9cc \uba39\uc73c\uba74 \uc5b8\uc81c\ub098 \ud655\ubcf4\ub418\ub294 \uc790\uc6d0\uc774 \uc544\ub2c8\uc5c8\ub2e4. \ucd08\ud134\uc73c\ub85c \uc62e\uaca8 \uc9c0\ub0b4\uac8c \ub41c \uc2dc\uae30\ub294 \uc791\ud488\uc744 \ub2e4\ub4ec\uace0 \ucd9c\ud310\ud558\ub294 \uc0b6\uc744 \uc774\ud574\ud558\ub294 \ub370 \uc911\uc694\ud558\ub2e4. \uac00\uc871\uc758 \ub3c4\uc6c0\uc73c\ub85c \uac70\ucc98\uac00 \ub9c8\ub828\ub418\uace0 \uc775\uc219\ud55c \uc6d0\uace0\ub97c \ub2e4\uc2dc \uc190\ubcf4\uba70 \uc0c8\ub85c\uc6b4 \uc791\uc5c5\uc744 \uc774\uc5b4 \uac04\ub2e4. \ud55c \uad8c\uc758 \uc18c\uc124\uc740 \ucc98\uc74c \uc0dd\uac01\ub09c \ud574\uc640 \ub3c5\uc790\uac00 \ub9cc\ub098\uac8c \ub41c \ud574\uac00 \ud06c\uac8c \ub2e4\ub97c \uc218 \uc788\ub2e4. \uc774 \uc810\uc744 \uc54c\uba74 \uc774\ubbf8 \uc368 \ub454 \uac83\uc744 \uace0\uce58\ub294 \uc77c\ub3c4 \ucc3d\uc791\uc758 \uc911\uc2ec\uc774\ub77c\ub294 \uc0ac\uc2e4\uc774 \ubcf4\uc778\ub2e4. \uc791\uac00\ub294 \uccab \uc601\uac10\uc744 \ubcf4\uad00\ub9cc \ud55c \uac83\uc774 \uc544\ub2c8\ub77c \ubb38\uc7a5\uacfc \uc778\ubb3c, \uad6c\uc870\ub97c \ub2e4\ub4ec\uc5c8\ub2e4. \ucd9c\ud310\ub41c \ucc45\uc744 \ubcf4\uace0 \ucc98\uc74c\ubd80\ud130 \uadf8 \ubaa8\uc2b5\uc73c\ub85c \ub5a0\uc62c\ub790\uc744 \uac83\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uae30 \uc27d\uc9c0\ub9cc, \uadf8 \uc55e\uc5d0\ub294 \uc5ec\ub7ec \ubc88\uc758 \ud310\ub2e8\uc774 \ub193\uc5ec \uc788\ub2e4. \u300e\uc774\uc131\uacfc \uac10\uc131\u300f\uc740 1811\ub144, \u300e\uc624\ub9cc\uacfc \ud3b8\uacac\u300f\uc740 1813\ub144\uc5d0 \ucd9c\uac04\ub418\uc5c8\ub2e4. \uc774\ud6c4 \u300e\ub9e8\uc2a4\ud544\ub4dc \ud30c\ud06c\u300f\uc640 \u300e\uc5d0\ub9c8\u300f \uac19\uc740 \uc791\ud488\uc774 \uc774\uc5b4\uc9c4\ub2e4. \uc18c\uc124 \uc18d \ubb34\ub3c4\ud68c\uc640 \uac00\uc871\ub4e4\uc758 \ub300\ud654\uac00 \ucc45\uc744 \uc0b0 \ub3c5\uc790\uc758 \uc0dd\ud65c \uc548\uc73c\ub85c \ub4e4\uc5b4\uac00\ub294 \uc2dc\uac04\uc774 \uc5f4\ub9b0 \uac83\uc774\ub2e4. \ucd9c\ud310\uc740 \uc791\ud488\uc774 \uc88b\uc73c\uba74 \uc790\ub3d9\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c0\ub294 \ub2e8\uc77c\ud55c \uc21c\uac04\uc774 \uc544\ub2c8\ub2e4. \uc6d0\uace0\ub97c \ub0b4\uace0 \uc870\uac74\uc744 \uc815\ud558\uace0 \uc778\uc1c4\uc640 \ud310\ub9e4\ub97c \uc9c0\ucf1c\ubcf4\ub294 \uacfc\uc815\uc774 \uc788\uc5c8\ub2e4. \uac00\uc871 \uc804\uae30\uc640 \ud3b8\uc9c0\ub97c \uc77d\uc73c\uba74 \uc791\ud488\uc744 \uc4f4 \uc0ac\ub78c\uc5d0\uac8c\ub3c4 \ub3c8\uacfc \ub3c5\uc790\uc758 \ubc18\uc751\uc774 \uad6c\uccb4\uc801\uc778 \uad00\uc2ec\uc774\uc5c8\ub2e4\ub294 \uc810\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \ubb38\ud559\uc758 \uac00\uce58\uc640 \ucc45\uc774 \ub9cc\ub4e4\uc5b4\uc9c0\ub294 \ud604\uc2e4\uc740 \ud568\uaed8 \uc874\uc7ac\ud55c\ub2e4. \uc624\uc2a4\ud2f4\uc758 \uc18c\uc124\uc5d0\uc11c\ub294 \ub204\uad6c\uc640 \uacb0\ud63c\ud558\ub294\uc9c0\uac00 \uc911\uc694\ud55c \ubb38\uc81c\ub2e4. \ub3d9\uc2dc\uc5d0 \uadf8 \uc120\ud0dd\uc744 \ub458\ub7ec\uc2fc \uc0dd\ud65c\uc758 \uc548\uc815\uacfc \uc7ac\uc0b0, \uac00\uc871\uc758 \uae30\ub300\uac00 \ubc18\ubcf5\ud574\uc11c \ub4f1\uc7a5\ud55c\ub2e4. \uc0ac\ub78c\uc744 \uc0ac\ub791\ud55c\ub2e4\ub294 \ub9d0\uc774 \uadf8\uac00 \ub193\uc778 \uc0ac\ud68c\uc801 \uc870\uac74\uc744 \uc800\uc808\ub85c \uc9c0\uc6b0\uc9c0\ub294 \uc54a\ub294\ub2e4. \uadf8\ub798\uc11c \uadf8\uc758 \uad00\uc2ec\uc744 \uc5f0\uc560\ub9cc \uc798 \uad00\ucc30\ud55c \uc7ac\uce58\ub85c \uc881\ud788\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc791\uc740 \ubb34\ub840\uac00 \ub204\uad6c\uc5d0\uac8c \ub354 \uc27d\uac8c \ud5c8\uc6a9\ub418\ub294\uc9c0, \uc790\uae30 \ud310\ub2e8\uc5d0 \ub300\ud55c \uc790\uc2e0\uac10\uc774 \uc5b4\ub5bb\uac8c \uc624\ub958\ub97c \ub9cc\ub4e4 \uc218 \uc788\ub294\uc9c0\ub3c4 \uc77d\uac8c \ub41c\ub2e4. \uc778\ubb3c\ub4e4\uc758 \ub300\ud654\ub97c \ub530\ub77c\uac00\uba74 \uc0ac\ub791\uacfc \ub3c8, \uc778\uc2dd\uacfc \uc608\uc758\uac00 \uac19\uc740 \uc7a5\uba74\uc5d0\uc11c \uc791\ub3d9\ud55c\ub2e4. \uac74\uac15\uc774 \ub098\ube60\uc9c4 \uadf8\ub294 1817\ub144\uc5d0 \uc138\uc0c1\uc744 \ub5a0\ub0ac\ub2e4. \ub9d0\ub144\uae4c\uc9c0 \uc791\uc5c5\uacfc \uac00\uc871\uc758 \uc0dd\ud65c\uc774 \uc774\uc5b4\uc84c\uace0, \uc77c\ubd80 \uc791\ud488\uc740 \uc8fd\uc740 \ub4a4 \ub3c5\uc790\uc640 \ub9cc\ub0ac\ub2e4. \uc624\ub298 \uc6b0\ub9ac\uac00 \uc54c\uace0 \uc788\ub294 \uc791\ud488 \ubaa9\ub85d\uc774 \uc791\uac00\uac00 \uc0b4\uc544\uc11c \ub204\ub9b0 \uba85\uc131\uacfc \uc815\ud655\ud788 \uc77c\uce58\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud655\uc778\ud558\uc9c0 \uc54a\uc740 \ubcd1\uba85\uc744 \ubd99\uc774\uac70\ub098 \ub9c8\uc9c0\ub9c9 \uc2dc\uae30\ub97c \uc18c\uc124\uc758 \ubaa8\ub4e0 \ubd84\uc704\uae30\uc640 \uc5f0\uacb0\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub0a8\uc544 \uc788\ub294 \uae30\ub85d\uc774 \uc54c\ub824 \uc8fc\ub294 \uc0dd\ud65c\uacfc \uc791\ud488\uc758 \uc2dc\uac04\uc744 \ucc28\ub840\ub85c \uc77d\uc73c\uba74 \ucda9\ubd84\ud558\ub2e4. \uc9e7\uc740 \uc0dd\uc560\ub77c\ub294 \ub9d0 \uc548\uc5d0\ub3c4 \uc11c\ub85c \ub2e4\ub978 \uc9d1\uacfc \uc6d0\uace0, \uad00\uacc4\uac00 \uc788\uc5c8\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 1913\ub144 \uac00\uc871 \uc804\uae30\uc5d0 \uc218\ub85d\ub41c \uc624\uc2a4\ud2f4\uc758 \uc5ed\uc0ac\uc801 \ucd08\uc0c1 \uc7ac\ud604 \ub3c4\ud310\uc774\ub2e4. \uc18c\uc124 \uc18d \uc5ec\uc8fc\uc778\uacf5\uc758 \uc5bc\uad74\uc744 \uadf8\ub9b0 \uac83\uc774 \uc544\ub2c8\ub77c \uc2e4\uc81c \uc791\uac00\ub97c \uc804\ud558\ub294 \ud6c4\ub300 \uc790\ub8cc\ub2e4. \uc5bc\uad74\ub9cc\uc73c\ub85c \ubb38\uccb4\ub098 \uc131\uaca9\uc744 \ubaa8\ub450 \uc124\uba85\ud560 \uc218\ub294 \uc5c6\uc9c0\ub9cc \uc791\uac00\uc758 \uc0b6\uc73c\ub85c \ub4e4\uc5b4\uac08 \ucd9c\ubc1c\uc810\uc774 \ub41c\ub2e4. \uc18c\uc124\ub85c \ub3cc\uc544\uac00\uba74 \ub204\uac00 \ub9d0\uc744 \ub3c5\ucc28\uc9c0\ud558\uace0 \ub204\uac00 \uc870\uc6a9\ud788 \ud310\ub2e8\uc744 \ubc14\uafb8\ub294\uc9c0 \ub4e4\uc5b4 \ubcf4\uc790. \uc791\uc740 \uac70\uc2e4\uc744 \uc138\ubc00\ud558\uac8c \uc37c\ub2e4\ub294 \uac83\uc740 \ubcfc \uc138\uacc4\uac00 \uc791\uc558\ub2e4\ub294 \ub73b\uacfc \uac19\uc9c0 \uc54a\ub2e4. \ud55c \uc0ac\ub78c\uc758 \ub9d0\ud22c\uc640 \uc120\ud0dd \uc548\uc5d0\uc11c \uc0ac\ud68c\uc758 \ub113\uc740 \uad00\uacc4\ub97c \ub4dc\ub7ec\ub0b8 \uc791\uac00\ub97c \ub2e4\uc2dc \ub9cc\ub098\uac8c \ub41c\ub2e4."}, {"id": "japan-fierce-temple-guardian", "title": "\uc808\uc744 \uc9c0\ud0a4\ub294 \uc5bc\uad74\uc740 \uc65c \uadf8\ub807\uac8c \ubb34\uc11c\uc6b8\uae4c", "summary": "\ud5d8\uc0c1\uad82\uc740 \ud45c\uc815\uc774 \ubc29\ubb38\uac1d\uc744 \ud5a5\ud55c \uc801\ub300\uac10\ub9cc\uc740 \uc544\ub2d0 \uc218 \uc788\ub2e4\ub294 \uc774\uc57c\uae30\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Art", "url": "stories/japan-fierce-temple-guardian/index.html", "image": "media/japan-fierce-temple-guardian.jpg", "alt": "\uc808\uc744 \uc9c0\ud0a4\ub294 \uc5bc\uad74\uc740 \uc65c \uadf8\ub807\uac8c \ubb34\uc11c\uc6b8\uae4c\uc758 \uc8fc\uc81c\ub97c \ud45c\ud604\ud55c AI \uc124\uba85\uc6a9 \uc0bd\ud654. \uc2e4\uc81c \uc791\ud488\uc774\ub098 \uac74\ucd95\ubb3c\uc744 \uadf8\ub300\ub85c \uc7ac\ud604\ud55c \uc774\ubbf8\uc9c0\uac00 \uc544\ub2d9\ub2c8\ub2e4.", "text": "\uc808\uc744 \uc9c0\ud0a4\ub294 \uc5bc\uad74\uc740 \uc65c \uadf8\ub807\uac8c \ubb34\uc11c\uc6b8\uae4c \uc77c\ubcf8 \uc218\ud638\uc0c1\uc744 \ubcf4\ub294 \uc2dc\uc120\uc744 \ubc14\uafb8\ub294 \ubc29\ubc95 \ud5d8\uc0c1\uad82\uc740 \ud45c\uc815\uc774 \ubc29\ubb38\uac1d\uc744 \ud5a5\ud55c \uc801\ub300\uac10\ub9cc\uc740 \uc544\ub2d0 \uc218 \uc788\ub2e4\ub294 \uc774\uc57c\uae30\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Art \ubb38\ud654 \ub208\uc744 \ud06c\uac8c \ub728\uace0 \uc785\uc744 \ubc8c\ub9b0 \uc870\uac01\uc0c1\uc774 \uc55e\uc744 \ub0b4\ub824\ub2e4\ubcf8\ub2e4. \ucc98\uc74c \ub9cc\ub0ac\ub2e4\uba74 \ubc18\uac11\uac8c \ub9de\uc544 \uc8fc\ub294 \uc5bc\uad74\uc774\ub77c\uace0 \ud558\uae30\ub294 \uc5b4\ub824\uc6b8 \uac83\uc774\ub2e4. \uadf8\ub7f0\ub370 \uc77c\ubcf8\uc758 \ubd88\uad50 \uc218\ud638\uc0c1\uc744 \ubcfc \ub54c\ub294 \uc9c8\ubb38\uc744 \ud55c \ubc88 \ubc14\uafd4 \ubcfc \uc218 \uc788\ub2e4. \ub204\uad6c\ub97c \uac81\uc8fc\uae30 \uc704\ud55c \ud45c\uc815\uc77c\uae4c. \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc740 \uc288\ucf58\uace0\uc9c4\uc73c\ub85c \uc18c\uac1c\ud558\ub294 \uc218\ud638\uc0c1\uc5d0 \uad00\ud55c \uad50\uc721 \uc790\ub8cc\uc5d0\uc11c \ubc14\ub85c \uadf8 \ub450 \uac00\uc9c0 \ub290\ub08c\uc744 \ud568\uaed8 \uc9da\ub294\ub2e4. \ubb34\uc11c\uc6c0\uacfc \ubcf4\ud638\ubc1b\ub294 \ub9c8\uc74c\uc774\ub2e4. \ubbf8\uc220\uad00 \uc124\uba85\uc740 \ud06c\uac8c \ubd80\ub985\ub72c \ub208\uacfc \uc678\uce58\ub294 \ub4ef \uc5f4\ub9b0 \uc785, \uac15\ud55c \ubab8\uc758 \ud45c\ud604\uc744 \uc774\uc57c\uae30\ud55c\ub2e4. \uc0ac\ucc30\ub85c \ub2e4\uac00\uc624\ub294 \uc0ac\ub78c\uc5d0\uac8c \ub450\ub824\uc6c0\uc744 \uc904 \uc218 \uc788\ub294 \ubaa8\uc2b5\uc774\ub2e4. \uadf8\ub7ec\ub098 \uc548\uc73c\ub85c \ub4e4\uc5b4\uac00 \ub9c8\uc74c\uc744 \uac00\ub77c\uc549\ud788\ub824\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \ub2e4\ub978 \ub73b\uc73c\ub85c \ub290\uaef4\uc9c8 \uc218\ub3c4 \uc788\ub2e4. \ubb34\uc5b8\uac00\uac00 \uc790\uc2e0\uc744 \uc9c0\ucf1c \uc8fc\uace0 \uc788\ub2e4\ub294 \uc548\ub3c4\uac10\uc774\ub2e4. \uac19\uc740 \ud45c\uc815\uc774\ub77c\ub3c4 \uadf8 \uc874\uc7ac\ub97c \ub0b4 \ud3b8\uc73c\ub85c \uc0dd\uac01\ud558\ub294\uc9c0\uc5d0 \ub530\ub77c \uc778\uc0c1\uc774 \ub2ec\ub77c\uc9c0\ub294 \uac83\uc774\ub2e4. \uc774 \uc870\uac01\uc744 \uacf5\uaca9\uc801\uc778 \uc5bc\uad74 \ud558\ub098\ub85c\ub9cc \ubcf4\uba74 \uae30\uad34\ud55c \uc7a5\uc2dd\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uc0ac\ucc30\uc744 \uc9c0\ud0a4\ub294 \uc5ed\ud560\uacfc \ud568\uaed8 \ubcf4\uba74 \ubab8\uc9d3\uc744 \uc77d\ub294 \ubc29\ubc95\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uc6c3\uace0 \uc788\uc5b4\uc57c\ub9cc \uce5c\uc808\ud55c \uc874\uc7ac\uc778 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ub298\ub0a0 \ubb38 \uc55e\uc5d0 \ubd99\uc774\ub294 \uacbd\uace0\ubb38\ub3c4 \ub5a0\uc62c\ub824 \ubcfc \uc218 \uc788\ub2e4. \ub4e4\uc5b4\uc624\ub294 \ubaa8\ub4e0 \uc0ac\ub78c\uc744 \ubbf8\uc6cc\ud574\uc11c\ub77c\uae30\ubcf4\ub2e4 \uc548\ucabd\uc758 \uc0ac\ub78c\uacfc \uacf5\uac04\uc744 \ubcf4\ud638\ud558\ub824\ub294 \ubaa9\uc801\uc77c \ub54c\uac00 \uc788\ub2e4. \uc774\uac83\uc740 \uc5ed\ud560\uc744 \uc774\ud574\ud558\uae30 \uc704\ud55c \ud604\ub300\uc758 \ube44\uc720\ub2e4. \uac19\uc740 \uac15\ud55c \ud45c\uc815\uc774\ub77c\ub3c4 \ubb34\uc5c7\uc744 \uc9c0\ud0a4\ub294 \uc874\uc7ac\uc778\uc9c0\uc5d0 \ub530\ub77c \uc778\uc0c1\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uc704\ud611\uc744 \ubc1b\ub294 \ucabd\uc5d0\uc11c\ub294 \uacf5\uaca9\uc73c\ub85c, \ubcf4\ud638\ubc1b\ub294 \ucabd\uc5d0\uc11c\ub294 \ubc29\uc5b4\ub85c \ub290\ub084 \uc218 \uc788\ub2e4. \ubbf8\uc220\uad00\uc758 \uad50\uc721 \uc790\ub8cc\ub3c4 \uc774 \ub450 \uac00\ub2a5\uc131\uc744 \ud568\uaed8 \uc81c\uc548\ud55c\ub2e4. \ud45c\uc815\uc758 \ubaa8\uc591\uacfc \uadf8\uac83\uc774 \ud5a5\ud55c \uad00\uacc4\ub97c \ub098\ub204\uc5b4 \uc77d\uc73c\uba74 \ubb34\uc12d\ub2e4\ub294 \uccab \uac10\uc0c1\uc5d0\uc11c \ud55c \uac78\uc74c \ub354 \ub4e4\uc5b4\uac08 \uc218 \uc788\ub2e4. \uc774\uac83\uc740 \ub2f9\uc2dc\uc758 \ubaa8\ub4e0 \ubc29\ubb38\uc790\uac00 \uac19\uc740 \uac10\uc815\uc744 \ub290\uaf08\ub2e4\ub294 \uae30\ub85d\uc740 \uc544\ub2c8\ub2e4. \uad50\uc721 \uc790\ub8cc\uac00 \uac00\ub2a5\ud55c \ubc18\uc751\uc744 \uc0dd\uac01\ud574 \ubcf4\ub3c4\ub85d \ub358\uc9c4 \uad00\uc810\uc774\ub2e4. \uc790\uc2e0\uc774 \uc0ac\ucc30\ub85c \ub2e4\uac00\uc624\ub294 \uc0ac\ub78c\uc778\uc9c0 \uc548\uc5d0\uc11c \uace0\uc694\ud788 \uba38\ubb34\ub974\ub824\ub294 \uc0ac\ub78c\uc778\uc9c0 \uc0c1\uc0c1\ud574 \ubcf4\uba74, \ud558\ub098\uc758 \uc870\uac01\uc744 \uc11c\ub85c \ub2e4\ub978 \uc790\ub9ac\uc5d0\uc11c \ub9cc\ub098\ub294 \uacbd\ud5d8\uc744 \uc774\ud574\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ubd80\ub985\ub72c \ub208\uc740 \uc2dc\uc120\uc758 \ubc29\ud5a5\uc744 \uac15\uc870\ud558\uace0 \ud06c\uac8c \uc5f4\ub9b0 \uc785\uc740 \uc18c\ub9ac\uac00 \ub098\ub294 \ub4ef\ud55c \uc778\uc0c1\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub2e4. \uac15\ud55c \ubab8\uc758 \ud45c\ud604\uc774 \uadf8 \uc5bc\uad74\uacfc \ud568\uaed8 \ub193\uc774\uba74 \uc791\uc740 \ud45c\uc815 \ubcc0\ud654\ubcf4\ub2e4 \ud6e8\uc52c \ud070 \ud798\uc73c\ub85c \ub2e4\uac00\uc628\ub2e4. \ub3cc\uc774\ub098 \ub098\ubb34\ub85c \ub41c \ud615\uc0c1\uc5d0\uc11c\ub3c4 \uc6b0\ub9ac\ub294 \uc6c0\uc9c1\uc784\uacfc \uc18c\ub9ac\ub97c \ub5a0\uc62c\ub9b0\ub2e4. \uc870\uac01\uc758 \uc815\uc9c0\ud55c \uc0c1\ud0dc\uc640 \ud45c\ud604\ud558\ub294 \ud589\ub3d9 \uc0ac\uc774\uc5d0 \ucc28\uc774\uac00 \uc788\ub294 \uc148\uc774\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc2e4\uc81c\ub85c \uc5b4\ub5a4 \ub9d0\uc744 \uc678\uce58\ub294\uc9c0 \ub300\uc0ac\ub97c \ubd99\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \ud655\uc778\ud560 \uc218 \uc788\ub294 \uac83\uc740 \ub208\uacfc \uc785, \ubab8\uc758 \ud45c\ud604\uc774\uba70 \uad6c\uccb4\uc801\uc778 \ubc1c\uc5b8\uc740 \ub0a8\uc544 \uc788\uc9c0 \uc54a\ub2e4. \uc18c\ub9ac\uac00 \ub0a0 \uac83 \uac19\ub2e4\ub294 \uac10\uc0c1\uacfc \uc2e4\uc81c\ub85c \ubb34\uc5c7\uc744 \ub9d0\ud588\ub2e4\ub294 \uc774\uc57c\uae30\ub294 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \uc870\uac01\uc774 \ubcf4\uc5ec \uc8fc\ub294 \ud798\ub9cc\uc73c\ub85c\ub3c4 \ud654\uba74\uc744 \uc624\ub798 \ubc14\ub77c\ubcfc \ub2e8\uc11c\ub294 \ucda9\ubd84\ud558\ub2e4. \uae30\uad00 \uc124\uba85\uc740 \uc774 \uc778\ubb3c\uc774 \ubc14\uc704 \uac19\uc740 \ubc1b\uce68 \uc704\uc5d0\uc11c \ub0b4\ub824\ub2e4\ubcf4\ub294 \uc778\uc0c1\uc744 \uc900\ub2e4\uace0 \uc774\uc57c\uae30\ud55c\ub2e4. \ubb3c\uac74\uc758 \ud06c\uae30\ubfd0 \uc544\ub2c8\ub77c \uad00\ub78c\uc790\uc640\uc758 \ub192\uc774 \ucc28\uc774\ub3c4 \uac10\uc0c1\uc5d0 \ucc38\uc5ec\ud55c\ub2e4. \ub208\ub192\uc774\ub97c \ub9de\ucd94\ub294 \uc791\uc740 \uc870\uac01\uacfc \uace0\uac1c\ub97c \ub4e4\uc5b4 \ub9c8\uc8fc\ud558\ub294 \ud615\uc0c1\uc740 \uc0ac\ub78c\uc758 \ubab8\uc5d0 \ub2e4\ub978 \ubc18\uc751\uc744 \uc904 \uc218 \uc788\ub2e4. \uc5b4\ub514\uc5d0\uc11c \ubcf4\ub294\uc9c0\uac00 \uc791\ud488\uc758 \uc77c\ubd80\uac00 \ub418\ub294 \ub300\ubaa9\uc774\ub2e4. \ubcf8\ubb38\uc758 \uc124\uba85\uc6a9 \uc0bd\ud654\ub294 \uc2e4\uc81c \uc870\uac01\uc758 \uce58\uc218\uc640 \uc804\uc2dc \uc704\uce58\ub97c \uc7ac\ud604\ud55c \uc0ac\uc9c4\uc774 \uc544\ub2c8\ub2e4. \uadf8\ub7ec\ubbc0\ub85c \uc815\ud655\ud55c \ubc1b\uce68 \ub192\uc774\ub97c \uadf8\ub9bc\uc5d0\uc11c \uc7ac\uac70\ub098 \ud604\uc7ac \uc5b4\ub290 \ubb38 \uc55e\uc5d0 \ub193\uc600\ub2e4\uace0 \ub2e8\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uae30\uad00\uc758 \ud574\uc124\uc5d0\uc11c \ud655\uc778\ud55c \uad00\uacc4\ub97c \ubc14\ud0d5\uc73c\ub85c \uc65c \ub192\uc774\uc640 \ubc29\ud5a5\uc774 \uc911\uc694\ud560 \uc218 \uc788\ub294\uc9c0 \uc0dd\uac01\ud574 \ubcf4\ub294 \uac83\uc774\ub2e4. \uadf8\ub9bc\uc758 \uc0c1\uc0c1\uacfc \uc0ac\uc2e4\uc758 \ubc94\uc704\ub97c \ud568\uaed8 \uc77d\uc73c\uba74 \ub41c\ub2e4. \uc6b0\ub9ac\ub294 \uce5c\uc808\ud568\uc744 \ubd80\ub4dc\ub7ec\uc6b4 \uc5bc\uad74\uacfc \uc27d\uac8c \uc5f0\uacb0\ud55c\ub2e4. \uc218\ud638\uc0c1\uc758 \uc5ed\ud560\uc744 \uc54c\uba74 \uadf8 \uc5f0\uacb0\uc774 \uc720\uc77c\ud55c \uae30\uc900\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\uc744 \ub290\ub084 \uc218 \uc788\ub2e4. \ub204\uad70\uac00\ub97c \uc9c0\ud0a4\uae30 \uc704\ud574 \ubc14\uae65\uc744 \uacbd\uacc4\ud558\ub294 \ubaa8\uc2b5\uc740 \uc548\ucabd\uc758 \uc0ac\ub78c\uc5d0\uac8c \ub2e4\ub978 \uc758\ubbf8\ub85c \ub2e4\uac00\uc62c \uc218 \uc788\ub2e4. \ud558\ub098\uc758 \uac10\uc815 \ub2e8\uc5b4\ubcf4\ub2e4 \uad00\uacc4\ub97c \ubcf4\ub294 \uc77c\uc774 \ud574\uc11d\uc758 \ud3ed\uc744 \ub113\ud78c\ub2e4. \ub2e4\ub9cc \ubb34\uc11c\uc6b4 \ud615\uc0c1\uc774\uba74 \uc5b8\uc81c\ub098 \uc88b\uc740 \ubcf4\ud638\uc790\ub77c\ub294 \uc0c8\ub85c\uc6b4 \uaddc\uce59\uc744 \ub9cc\ub4e4 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \uac01\uac01\uc758 \uc804\ud1b5\uacfc \uc791\ud488 \uc124\uba85\uc744 \ub530\ub77c \ud655\uc778\ud560 \ubd80\ubd84\uc774 \uc788\ub2e4. \uc774 \uc870\uac01\uc5d0\uc11c\ub294 \uc0ac\ucc30\uc744 \uc9c0\ud0a8\ub2e4\ub294 \uc5ed\ud560\uc774 \ud45c\uc815\uc744 \uc77d\ub294 \uc911\uc694\ud55c \uc5f4\uc1e0\ub2e4. \ucc98\uc74c\uc758 \ub180\ub77c\uc6c0\uc744 \ubc84\ub9ac\uc9c0 \uc54a\uace0 \uadf8 \ub180\ub77c\uc6c0\uc774 \uc65c \uc0dd\uacbc\ub294\uc9c0 \ub354 \uc0b4\ud53c\ub294 \ubc29\uc2dd\uc73c\ub85c \uac10\uc0c1\uc744 \uc774\uc5b4 \uac08 \uc218 \uc788\ub2e4. \uae30\uad00 \uc790\ub8cc\ub294 \uc6d0\ub798 \ubc29\ubb38\uac1d\uc774 \ub290\uaf08\uc744 \ubc18\uc751\uc744 \uac00\ub2a5\uc131\uc73c\ub85c \uc124\uba85\ud55c\ub2e4. \uc2e4\uc81c \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \uac19\uc740 \ub450\ub824\uc6c0\uc774\ub098 \uc548\ub3c4\uac10\uc744 \ub290\uaf08\ub2e4\uace0 \uc815\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ub798\ub41c \uc870\uac01 \uc55e\uc5d0\uc11c\ub3c4 \ubcf4\ub294 \uc0ac\ub78c\uc758 \uacbd\ud5d8\uc740 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uadf8\ub7fc\uc5d0\ub3c4 \ub204\uad6c\ub97c \uc9c0\ud0a4\uace0 \ub204\uad6c\ub97c \ud5a5\ud574 \ud798\uc744 \ubcf4\uc774\ub294\uac00\ub77c\ub294 \uc9c8\ubb38\uc740 \uc4f8\ubaa8\uac00 \uc788\ub2e4. \ub2e4\uc74c\uc5d0 \ubb34\uc11c\uc6b4 \ud45c\uc815\uc758 \uc218\ud638\uc0c1\uc744 \ub9cc\ub098\uba74 \uc5bc\uad74\uc744 \ud53c\ud558\uae30 \uc804\uc5d0 \uc5ed\ud560\uc744 \uc0dd\uac01\ud574 \ubcf4\uc790. \ub0af\uc124\ub358 \ud45c\uc815\uc774 \ub2e4\ub978 \ub73b\uc73c\ub85c \ub2e4\uac00\uc624\ub294 \uc21c\uac04\uc774 \uc788\uc744 \uc218 \uc788\ub2e4."}, {"id": "japan-phoenix-wood-panels", "title": "\uc77c\ubcf8\uc758 \ub098\ubb34 \uc7a5\uc2dd\uc740 \uad00\ub78c\uc11d \uc544\ub798\uc5d0\uc11c \ubc1c\uacac\ub410\ub2e4", "summary": "\uac74\ubb3c\uc774 \uc0ac\ub77c\uc9c4 \ub4a4\uc5d0\ub3c4 \ub0a8\uc558\ub358 \uc77c\ubcf8\uc2dd \uac74\ucd95 \uc7a5\uc2dd\uc758 \uc774\ub3d9\uc744 \ub530\ub77c\uac11\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Architecture", "url": "stories/japan-phoenix-wood-panels/index.html", "image": "media/japan-phoenix-wood-panels.jpg", "alt": "\uc77c\ubcf8\uc758 \ub098\ubb34 \uc7a5\uc2dd\uc740 \uad00\ub78c\uc11d \uc544\ub798\uc5d0\uc11c \ubc1c\uacac\ub410\ub2e4\uc758 \uc8fc\uc81c\ub97c \ud45c\ud604\ud55c AI \uc124\uba85\uc6a9 \uc0bd\ud654. \uc2e4\uc81c \uc791\ud488\uc774\ub098 \uac74\ucd95\ubb3c\uc744 \uadf8\ub300\ub85c \uc7ac\ud604\ud55c \uc774\ubbf8\uc9c0\uac00 \uc544\ub2d9\ub2c8\ub2e4.", "text": "\uc77c\ubcf8\uc758 \ub098\ubb34 \uc7a5\uc2dd\uc740 \uad00\ub78c\uc11d \uc544\ub798\uc5d0\uc11c \ubc1c\uacac\ub410\ub2e4 \ubc15\ub78c\ud68c \uac74\ubb3c\uc5d0\uc11c \ubbf8\uc220\uad00\uc73c\ub85c \uc774\uc5b4\uc9c4 \ub124 \uc870\uac01 \uac74\ubb3c\uc774 \uc0ac\ub77c\uc9c4 \ub4a4\uc5d0\ub3c4 \ub0a8\uc558\ub358 \uc77c\ubcf8\uc2dd \uac74\ucd95 \uc7a5\uc2dd\uc758 \uc774\ub3d9\uc744 \ub530\ub77c\uac11\ub2c8\ub2e4. Architecture \ubb38\ud654 \uc6b4\ub3d9\uc7a5 \uad00\ub78c\uc11d \uc544\ub798\uc5d0\uc11c \uc77c\ubcf8 \uac74\ucd95 \uc7a5\uc2dd\uc774 \ub098\uc628\ub2e4\uba74 \uc870\uae08 \uc5c9\ub6b1\ud558\uac8c \ub4e4\ub9b0\ub2e4. \ud558\uc9c0\ub9cc \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc774 \uc18c\uac1c\ud558\ub294 \ub124 \uc810\uc758 \ubaa9\uc870 \uc7a5\uc2dd\uc5d0\ub294 \uadf8\ub7f0 \uc2dc\uac04\uc774 \uc788\uc5c8\ub2e4. \ud55c\ub54c \ubc15\ub78c\ud68c \uac74\ubb3c\uc5d0 \ub2ec\ub838\ub358 \ubb3c\uac74\ub4e4\uc774\ub2e4. \uc774 \uc7a5\uc2dd\uc740 \ub780\ub9c8\ub77c\uace0 \ubd80\ub974\ub294 \ubaa9\uc870 \uac74\ucd95 \ubd80\uc7ac\ub2e4. \ubb38 \uc704\ucabd \uacf5\uac04\uc5d0 \ub193\uc774\ub294 \uc7a5\uc2dd\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uba74 \uc774\ud574\ud558\uae30 \uc27d\ub2e4. \ucc98\uc74c\ubd80\ud130 \uc720\ub9ac\uc7a5 \uc548\uc5d0 \uc804\uc2dc\ud558\ub824\uace0 \ub9cc\ub4e0 \uc870\uac01\uc740 \uc544\ub2c8\uc5c8\ub2e4. 1893\ub144 \uc2dc\uce74\uace0 \ub9cc\uad6d\ubc15\ub78c\ud68c\uc5d0\uc11c \uc77c\ubcf8\uc740 \ud53c\ub2c9\uc2a4 \ud640\uc774\ub77c\ub294 \uad6d\uac00 \uc804\uc2dc\uad00\uc744 \uc138\uc6e0\ub2e4. \ubbf8\uc220\uad00 \uc124\uba85\uc740 \uc774 \uac74\ubb3c\uc774 \uad50\ud1a0 \uadfc\uad50\uc758 11\uc138\uae30 \uc0ac\ucc30\uc744 \ubcf8\ub5b4\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \ub2e4\ub978 \uc804\uc2dc\uad00\ub4e4\uacfc\ub294 \uad6c\ubcc4\ub418\ub294 \uc77c\ubcf8\uc2dd \uac74\ubb3c\uc774\uc5c8\ub2e4. \ub124 \uc810\uc758 \ubaa9\uc870 \uc7a5\uc2dd\ub3c4 \uadf8 \uc804\uc2dc\uad00\uc744 \uc704\ud574 \ub9cc\ub4e4\uc5b4\uc84c\ub2e4. \uac74\ubb3c\uc758 \uc77c\ubd80\uc600\uc73c\ub2c8 \uc0ac\ub78c\ub4e4\uc740 \uc870\uac01 \ud558\ub098\ub97c \ub530\ub85c \ubcf4\uae30\ubcf4\ub2e4 \uadf8 \uc544\ub798\ub97c \uc9c0\ub098\uac00\uba70 \uacf5\uac04 \uc804\uccb4\ub97c \ub9cc\ub0ac\uc744 \uac83\uc774\ub2e4. \uc774\uac83\uc740 \uac74\ucd95 \ubd80\uc7ac\uc758 \uc790\ub9ac\ub97c \ub5a0\uc62c\ub824 \ubcf4\ub294 \ubc29\uc2dd\uc774\ub2e4. \ubc15\ub78c\ud68c\uac00 \ub05d\ub09c \ub4a4 \uc77c\ubcf8 \uc815\ubd80\ub294 \uc804\uc2dc\uad00\uc744 \uc2dc\uce74\uace0\uc2dc\uc5d0 \uae30\uc99d\ud588\ub2e4. \uadf8\ub7ec\ub098 \uac74\ubb3c\uc740 1945\ub144\uacfc 1946\ub144\uc758 \ud654\uc7ac\ub85c \ud6fc\uc190\ub418\uc5b4 \ucca0\uac70\ub418\uc5c8\ub2e4\uace0 \ud55c\ub2e4. \ubbf8\uc220\uad00\uc740 \ub124 \uc7a5\uc2dd\uc774 \ub0a8\uc740 \ubd80\uc7ac\uc600\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uadf8 \ub4a4 \uc774 \ubb3c\uac74\ub4e4\uc740 \uc194\uc800 \ud544\ub4dc\uc758 \uad00\ub78c\uc11d \uc544\ub798\uc5d0 \ubcf4\uad00\ub418\uc5c8\uace0, \uc78a\ud78c \ucc44 \uc9c0\ub0b4\ub2e4\uac00 1973\ub144\uc5d0 \ubc1c\uacac\ub418\uc5c8\ub2e4. \uac74\ucd95 \uc7a5\uc2dd\uc758 \ub2e4\uc74c \uc8fc\uc18c\uac00 \uc0ac\ucc30\ub3c4 \ubc15\ubb3c\uad00\ub3c4 \uc544\ub2cc \uacbd\uae30\uc7a5\uc774\uc5c8\ub2e4\ub294 \uc810\uc774 \ub73b\ubc16\uc774\ub2e4. \ub780\ub9c8\ub294 \uac74\ubb3c \uc704\ucabd\uc758 \uac00\ub85c \uacf5\uac04\uc5d0 \uc4f0\uc774\ub294 \uc7a5\uc2dd \ubd80\uc7ac\ub2e4. \uc774 \ub124 \uc810\uc740 \ubd88\uad50 \uc870\uac01\uac00 \ub2e4\uce74\ubb34\ub77c \uace0\uc6b4\uc774 \ubc15\ub78c\ud68c \uc77c\ubcf8\uad00\uc744 \uc704\ud574 \ub9cc\ub4e0 \uac83\uc73c\ub85c \ubbf8\uc220\uad00\uc740 \uc18c\uac1c\ud55c\ub2e4. \uc791\uc740 \uc218\uc9d1\ud488\uc744 \ub098\uc911\uc5d0 \uac74\ubb3c\uc5d0 \ub193\uc740 \uac83\uc774 \uc544\ub2c8\ub77c \uac74\ucd95 \uacf5\uac04\uacfc \ud568\uaed8 \ubcf4\uc774\ub3c4\ub85d \ub9c8\ub828\ub41c \ubb3c\uac74\uc774\uc5c8\ub2e4. \uc804\uc2dc\uad00\uc758 \uc804\uccb4 \ubaa8\uc2b5\uacfc \uc870\uac01\uc758 \uc138\ubd80\ub97c \uc5f0\uacb0\ud574 \ubcfc \uc774\uc720\uac00 \uc788\ub2e4. \ubc15\ub78c\ud68c\uc5d0\uc11c \uad6d\uac00 \uc804\uc2dc\uad00\uc740 \ubb3c\uac74\ub9cc \ubcf4\uc5ec \uc8fc\ub294 \uacf3\uc774 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \uac74\ubb3c \uc548\uc5d0\uc11c \uadf8 \ubb3c\uac74\uc744 \ub9cc\ub098\uac8c \ud560\uc9c0\ub3c4 \ud55c \ub098\ub77c\ub97c \ud45c\ud604\ud558\ub294 \uc120\ud0dd\uc774 \ub41c\ub2e4. \uad50\ud1a0 \uadfc\uad50 \uc0ac\ucc30\uc744 \ubcf8\ub72c \uc77c\ubcf8\uad00\uc740 \ub2f9\uc2dc \ub2e4\ub978 \uc804\uc2dc\uad00\ub4e4\uacfc \uad6c\ubcc4\ub418\ub294 \ubaa8\uc2b5\uc744 \uac00\uc84c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc774 \uac74\ubb3c \ud558\ub098\uac00 \uc77c\ubcf8 \uac74\ucd95\uc758 \ubaa8\ub4e0 \uc804\ud1b5\uc744 \ub300\ud45c\ud55c\ub2e4\uace0 \ub113\ud600 \uc77d\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \ud654\uc7ac \ub4a4 \uc804\uc2dc\uad00\uc774 \ucca0\uac70\ub418\uc5c8\ub2e4\ub294 \ub9d0\ub9cc \ub4e4\uc73c\uba74 \uadf8 \uc5ed\uc0ac\ub3c4 \ubaa8\ub450 \ub05d\ub0ac\ub2e4\uace0 \uc0dd\uac01\ud558\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \ub124 \ubaa9\uc870 \ubd80\uc7ac\ub294 \ub0a8\uc544 \ub2e4\ub978 \uc7a5\uc18c\ub85c \uc62e\uaca8\uc84c\ub2e4. \uc804\uccb4 \uac74\ubb3c\uc758 \uc6b4\uba85\uacfc \uc77c\ubd80\ub97c \uc774\ub8e8\ub358 \ubb3c\uac74\uc758 \uc6b4\uba85\uc774 \uac08\ub77c\uc9c4 \uac83\uc774\ub2e4. \uc720\ubb3c\uc758 \uc0dd\uc560\uc5d0\ub294 \uc81c\uc791\ubfd0 \uc544\ub2c8\ub77c \ubd84\ub9ac\uc640 \uc774\ub3d9, \ubcf4\uad00\uc758 \uc2dc\uac04\uc774 \ud3ec\ud568\ub41c\ub2e4. \uc194\uc800 \ud544\ub4dc\ub77c\ub294 \uc0c8 \uc7a5\uc18c\ub294 \ucc98\uc74c\uc758 \uc4f0\uc784\uacfc \ud06c\uac8c \ub2e4\ub974\ub2e4. \uc0ac\ucc30\uc744 \ubcf8\ub72c \uc804\uc2dc\uad00\uc758 \uc7a5\uc2dd\uc774 \uacbd\uae30\uc7a5 \uad00\ub78c\uc11d \uc544\ub798\uc5d0 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uacf5\uac04\uc758 \uc774\ub984\ub9cc\uc73c\ub85c \ubb34\uc5c7\uc774 \ub4e4\uc5b4 \uc788\ub294\uc9c0 \uc9d0\uc791\ud560 \uc218 \uc5c6\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ub2e4\ub9cc \uc78a\ud600 \uc788\uc5c8\ub2e4\ub294 \uc124\uba85\uc5d0\uc11c \ub204\uac00 \uc5b8\uc81c \uc5b4\ub5a4 \uc2e4\uc218\ub97c \ud588\ub294\uc9c0\uae4c\uc9c0 \uc0c8 \uc774\uc57c\uae30\ub85c \ub9cc\ub4e4\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud655\uc778\ud55c \uc774\ub3d9\uc758 \ud070 \uacbd\ub85c\uac00 \uc911\uc2ec\uc774\ub2e4. 1973\ub144 \ubc1c\uacac\ud55c \ub4a4 \ub450 \uc810\uc740 \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc73c\ub85c, \ub098\uba38\uc9c0 \ub450 \uc810\uc740 \uc77c\ub9ac\ub178\uc774\ub300\ud559\uad50 \uc2dc\uce74\uace0 \ucea0\ud37c\uc2a4\ub85c \ub098\ub258\uc5b4 \uac14\ub2e4. \uc6d0\ub798 \uac19\uc740 \uac74\ubb3c\uc5d0 \uc788\ub358 \ubb3c\uac74\uc774\ub77c\ub3c4 \uad00\ub9ac\ud558\ub294 \uae30\uad00\uc740 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc5c8\ub2e4. \uac19\uc740 \uc774\ub984\uc758 \ub124 \uc810\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uac19\uc740 \uc7a5\uc18c\uc5d0\uc11c \ubcfc \uc218 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ubcc4\uac1c\uc600\ub2e4. \uc774\ud6c4 \ub300\ud559 \uce21\uc5d0\uc11c \ubcf4\uc874 \uc0c1\ud0dc\ub97c \uc5fc\ub824\ud558\uba74\uc11c \uc18c\uc7a5\ud488\uc744 \ubbf8\uc220\uad00\uc73c\ub85c \ub118\uacbc\uace0 \ub124 \uc810\uc744 \ud568\uaed8 \ub3cc\ubcfc \uc870\uac74\uc774 \ub9c8\ub828\ub418\uc5c8\ub2e4\uace0 \uae00\uc740 \uc124\uba85\ud55c\ub2e4. \ubaa8\uc73c\ub294 \uc77c\uc5d0\ub294 \ub300\ud45c \uc791\ud488\uc744 \ub9ce\uc774 \uac16\ucd94\ub824\ub294 \ubaa9\uc801\ub9cc \uc788\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \ud568\uaed8 \ubcf4\uc874\ud558\uace0 \uad00\uacc4\ub97c \uc0b4\ud3b4\ubcfc \uc774\uc720\ub3c4 \uc788\ub2e4. \ubc1c\uacac\ud55c \uc21c\uac04 \uc774\ud6c4\uc5d0 \uc5b4\ub5a4 \ud310\ub2e8\uc744 \ud588\ub294\uc9c0\uac00 \ubb3c\uac74\uc758 \ub2e4\uc74c \uc2dc\uac04\uc744 \ub9cc\ub4e0\ub2e4. \uae30\uad00 \uae00\uc740 \uc77c\ubcf8 \ubbf8\uc220 \uc804\uc2dc\uc2e4\uc758 \uac1c\ud3b8\uc744 \uc900\ube44\ud558\ub358 \uc2dc\uc810\uc5d0 \uc4f0\uc600\ub2e4. \uadf8\ub798\uc11c \uadf8\ub54c\uc758 \ubcf4\uc874\uacfc \uc804\uc2dc \uacc4\ud68d\uc744 \ud604\uc7ac\uc758 \uad00\ub78c \uc815\ubcf4\ub85c \uadf8\ub300\ub85c \uc0ac\uc6a9\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc624\ub798\ub41c \uac8c\uc2dc\uae00\uc774 \uc54c\ub824 \uc8fc\ub294 \uc5ed\uc0ac\uc640 \uc624\ub298 \ubb38\uc744 \uc5ec\ub294 \uc804\uc2dc\uc2e4\uc740 \uad6c\ubd84\ud574\uc11c \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \uc791\ud488\uc774 \uc5b4\ub514\ub97c \uac70\uccd0 \uc654\ub294\uc9c0 \uc77d\ub294 \uc790\ub8cc\uc640 \ubc29\ubb38 \uc548\ub0b4\ub294 \uc5ed\ud560\uc774 \ub2e4\ub974\ub2e4. \uc774 \uc774\ub825\uc744 \uc54c\uace0 \uc2e4\uc81c \ubd80\uc7ac\ub97c \ub9cc\ub09c\ub2e4\uba74 \uba3c\uc800 \uc870\uac01\uc758 \ubaa8\uc2b5\uc5d0, \ub2e4\uc74c\uc5d0\ub294 \ubcf8\ub798 \uac74\ubb3c\uc5d0\uc11c \ub193\uc600\ub358 \uc790\ub9ac\ub85c \uad00\uc2ec\uc744 \uc62e\uaca8 \ubcfc \uc218 \uc788\ub2e4. \uac74\ubb3c\uc5d0\uc11c \ub5a8\uc5b4\uc838 \ub098\uc628 \uc7a5\uc2dd\ub3c4 \uc81c\uc791 \uc7a5\uc18c\uc640 \ubc15\ub78c\ud68c, \uacbd\uae30\uc7a5\uc758 \ucc3d\uace0\uc640 \ubc15\ubb3c\uad00\uc744 \uc774\uc5b4 \uc900\ub2e4. \uc791\uc740 \ubaa9\uc870 \uc870\uac01\uc5d0 \uc2dc\uce74\uace0\uc758 \ub3c4\uc2dc\uc0ac\uc640 \uc77c\ubcf8\uc758 \ubbf8\uc220\uc774 \ud568\uaed8 \ub0a8\uc544 \uc788\ub294 \uc148\uc774\ub2e4. \ubc1c\uacac \ub4a4\uc5d0\ub294 \ub450 \uc810\uc529 \ub2e4\ub978 \uae30\uad00\uc73c\ub85c \ub098\ub258\uc5c8\ub2e4\uac00 \ub124 \uc810 \ubaa8\ub450 \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc73c\ub85c \ubaa8\uc600\ub2e4. \uae30\uad00\uc774 \ub0a8\uae34 \uae00\uc740 \uc774 \uc7a5\uc2dd\ub4e4\uc744 \ud568\uaed8 \ubcf4\uc874\ud558\uace0 \ubcf4\uc5ec \uc8fc\ub824\ub358 \uacfc\uc815\uc744 \uc18c\uac1c\ud55c\ub2e4. \uc624\ub798\uc804\uc758 \uc804\uc2dc \uc900\ube44\ub97c \uae30\ub85d\ud55c \uae00\uc774\ubbc0\ub85c \uc9c0\uae08\uc758 \uc804\uc2dc\uc2e4 \uc548\ub0b4\uc640\ub294 \uad6c\ubd84\ud574\uc11c \uc77d\uc73c\uba74 \ub41c\ub2e4. \uac74\ubb3c\uc740 \uc0ac\ub77c\uc838\ub3c4 \uadf8 \uc77c\ubd80\uac00 \ub2e4\ub978 \uc2dc\uac04\uc744 \uc0b4\uc544\uac08 \uc218 \uc788\ub2e4. \uc77c\ubcf8\uc2dd \uc804\uc2dc\uad00\uacfc \ubbf8\uad6d\uc758 \uc6b4\ub3d9\uc7a5, \ubbf8\uc220\uad00\uc744 \uc774\uc5b4 \uc8fc\ub294 \uac83\uc740 \ub124 \uc870\uac01\uc758 \ub098\ubb34\uc600\ub2e4. \ubb3c\uac74\uc758 \uc774\ub825\uc740 \ub73b\ubc16\uc758 \uc7a5\uc18c\uc5d0\uc11c \ud55c \uc7a5 \ub354 \ub298\uc5b4\ub098\uae30\ub3c4 \ud55c\ub2e4."}, {"id": "leonardo-life-of-observation", "title": "\ub808\uc624\ub098\ub974\ub3c4 \ub2e4\ube48\uce58\uc758 \uc0dd\uc560 \u2014 \uadf8\ub9bc \ud55c \uc7a5\uc5d0\uc11c \uc138\uc0c1\uc744 \uad00\ucc30\ud558\ub2e4", "summary": "\ud654\uac00\uc758 \uc774\ub3d9\uacfc \uc791\ud488, \uad00\ucc30 \uae30\ub85d\uc744 \ud1b5\ud574 \ub2e4\uc7ac\ub2e4\ub2a5\ud558\ub2e4\ub294 \ub9d0 \ub4a4\uc758 \uc2dc\uac04\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Art", "url": "stories/leonardo-life-of-observation/index.html", "image": "media/leonardo-life-of-observation.jpg", "alt": "\ub2e4\ube48\uce58\uc758 \ucd5c\ud6c4\uc758 \ub9cc\ucc2c\uc744 \uc7ac\ud604\ud55c \uc61b \ub3c4\ud310. \uae34 \uc2dd\ud0c1 \uc911\uc559\uc758 \uc608\uc218\uc640 \uc591\ucabd \uc81c\uc790\ub4e4\uc774 \ud45c\ud604\ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.", "text": "\ub808\uc624\ub098\ub974\ub3c4 \ub2e4\ube48\uce58\uc758 \uc0dd\uc560 \u2014 \uadf8\ub9bc \ud55c \uc7a5\uc5d0\uc11c \uc138\uc0c1\uc744 \uad00\ucc30\ud558\ub2e4 \uacf5\ubc29\uc758 \ubc30\uc6c0\uacfc \uad81\uc815\uc758 \uc77c, \ub05d\ub098\uc9c0 \uc54a\uc740 \uc9c8\ubb38\ub4e4 \ud654\uac00\uc758 \uc774\ub3d9\uacfc \uc791\ud488, \uad00\ucc30 \uae30\ub85d\uc744 \ud1b5\ud574 \ub2e4\uc7ac\ub2e4\ub2a5\ud558\ub2e4\ub294 \ub9d0 \ub4a4\uc758 \uc2dc\uac04\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Art \ubb38\ud654 \ub2e4\ube48\uce58\ub77c\ub294 \uc774\ub984\uc5d0\ub294 \uc5ec\ub7ec \ubaa8\uc2b5\uc774 \uacb9\uccd0 \uc788\ub2e4. \u3008\ubaa8\ub098\ub9ac\uc790\u3009\ub97c \uadf8\ub9b0 \ud654\uac00\uc774\uba74\uc11c \uc778\uccb4\uc640 \ubb3c, \ub0a0\uc544\uac00\ub294 \uc6c0\uc9c1\uc784\uacfc \uae30\uacc4\uc5d0\ub3c4 \uad00\uc2ec\uc744 \uac00\uc84c\ub358 \uc0ac\ub78c\uc774\ub2e4. \uc774\ub7f0 \uc774\ub984 \uc55e\uc5d0\uc11c\ub294 \ud0c0\uace0\ub09c \ucc9c\uc7ac\uc600\ub2e4\ub294 \ub9d0\ub85c \uc27d\uac8c \uc815\ub9ac\uac00 \ub05d\ub098\uace4 \ud55c\ub2e4. \uadf8\ub7ec\ub098 1452\ub144\uc5d0 \ud0dc\uc5b4\ub098 1519\ub144\uc5d0 \uc138\uc0c1\uc744 \ub5a0\ub09c \ud55c \uc0ac\ub78c\uc758 \uc0b6\uc5d0\ub294 \ubc30\uc6b0\uace0 \uc758\ub8b0\ub97c \ubc1b\uace0 \uc774\ub3d9\ud558\uba70, \ub05d\ub0b4\uc9c0 \ubabb\ud55c \uc77c\uacfc \ub2e4\uc2dc \uc0b4\ud540 \ubb38\uc81c\uac00 \uc788\uc5c8\ub2e4. \ubb34\uc5c7\uc774\ub4e0 \uc989\uc2dc \ud574\ub0b8 \uc0ac\ub78c\uc73c\ub85c \uc0c1\uc0c1\ud558\uae30\ubcf4\ub2e4 \ubb34\uc5c7\uc744 \uc624\ub798 \ubcf4\uace0 \uc5b4\ub5bb\uac8c \uc77c\ud588\ub294\uc9c0 \ub530\ub77c\uac00 \ubcf4\uba74 \ub2e4\ube48\uce58\uac00 \uc870\uae08 \uac00\uae4c\uc6cc\uc9c4\ub2e4. \uadf8\ub294 \ud53c\ub80c\uccb4\uc758 \ubca0\ub85c\ud0a4\uc624 \uacf5\ubc29\uc5d0\uc11c \ubc30\uc6e0\ub2e4. \uacf5\ubc29\uc740 \uc644\uc131\ub41c \uadf8\ub9bc\ub9cc \uad6c\uacbd\ud558\ub294 \uc7a5\uc18c\uac00 \uc544\ub2c8\ub77c \uc7ac\ub8cc\uc640 \ub3c4\uad6c\ub97c \ub2e4\ub8e8\uace0 \uc5ec\ub7ec \uc0ac\ub78c\uc774 \uc791\uc5c5\uc744 \ub098\ub204\ub294 \ud604\uc7a5\uc774\uc5c8\ub2e4. \uadf8\ub9bc\uacfc \uc785\uccb4\uc801\uc778 \ud615\ud0dc, \uc190\uc758 \uae30\uc220\uacfc \uad00\ucc30\uc774 \uac00\uae4c\uc774 \ub193\uc77c \uc218 \uc788\ub294 \ud658\uacbd\uc774\ub2e4. \uc5b4\ub9b0 \uc2dc\uc808\uc758 \uc7ac\ub2a5\uc744 \uacfc\uc7a5\ud558\ub294 \uc77c\ud654\ubcf4\ub2e4 \uc774\ub7f0 \ubc30\uc6c0\uc758 \uc870\uac74\uc744 \uc0dd\uac01\ud574 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \ubb34\uc5c7\uc744 \uc798 \ubcf4\ub824\uba74 \ubb34\uc5c7\uc744 \ub9cc\ub4e4\uc5b4 \ubcf4\uace0 \uc5b4\ub5a4 \uc7ac\ub8cc\ub97c \uc54c\uc544\uc57c \ud558\ub294\uc9c0 \uc775\ud788\ub294 \uc2dc\uac04\uc774 \ud544\uc694\ud588\ub2e4. \ub6f0\uc5b4\ub09c \uc791\ud488 \ub4a4\uc5d0\ub3c4 \ubc18\ubcf5\ub418\ub294 \uc190\uc758 \uc77c\uc774 \uc788\uc5c8\uc74c\uc744 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \ubc00\ub77c\ub178\uc5d0\uc11c \uc2a4\ud3ec\ub974\ucc28 \uac00\ubb38\uc758 \ud6c4\uc6d0\uc744 \ubc1b\ub294 \ub3d9\uc548 \ub2e4\ube48\uce58\uc758 \ud65c\ub3d9\uc740 \ud68c\ud654\ub9cc\uc73c\ub85c \uc124\uba85\ub418\uc9c0 \uc54a\ub294\ub2e4. \uad81\uc815\uc758 \uc694\uad6c\uc640 \uc7a5\uc2dd, \uae30\ub150\ubb3c\uacfc \uae30\uc220\uc801 \uad00\uc2ec\uc774 \uac19\uc740 \uc0b6 \uc548\uc5d0 \uc788\uc5c8\ub2e4. \uc608\uc220\uac00\uac00 \uc790\uae30 \uad00\uc2ec\ub9cc\uc744 \uc704\ud574 \uc870\uc6a9\ud788 \uc791\uc5c5\ud558\ub294 \uc624\ub298\uc758 \ub0ad\ub9cc\uc801 \uc774\ubbf8\uc9c0\uc640\ub294 \ub2e4\ub978 \uc870\uac74\uc774\ub2e4. \ub204\uac00 \uc77c\uc744 \ub9e1\uae30\uace0 \uc5b4\ub5a4 \uc790\uc6d0\uc744 \uc8fc\ub294\uc9c0\ub294 \ubb34\uc5c7\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub294\uc9c0\uc640 \uc5f0\uacb0\ub41c\ub2e4. \ub2e4\ube48\uce58\uc758 \uc774\ub3d9\uc744 \ub3c4\uc2dc \uc774\ub984 \uba87 \uac1c\ub85c \uc678\uc6b0\uae30\ubcf4\ub2e4 \uc791\uc5c5\uc758 \ud658\uacbd\uc774 \ubc14\ub00c\ub294 \uacfc\uc815\uc73c\ub85c \ubcf4\uba74 \uc88b\ub2e4. \uc0c8\ub85c\uc6b4 \uc7a5\uc18c\ub294 \ube5b\uacfc \ud48d\uacbd\ubfd0 \uc544\ub2c8\ub77c \uc77c\uc758 \uc885\ub958\uc640 \uc0ac\ub78c \uad00\uacc4\ub3c4 \ubc14\uafb8\uc5c8\ub2e4. \ubc00\ub77c\ub178\uc758 \u3008\ucd5c\ud6c4\uc758 \ub9cc\ucc2c\u3009\uc740 \uae34 \uc2dd\ud0c1\uc744 \ub458\ub7ec\uc2fc \uc778\ubb3c\ub4e4\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uac00\uc6b4\ub370 \uc608\uc218\ub97c \uc911\uc2ec\uc73c\ub85c \uc81c\uc790\ub4e4\uc758 \uc190\uacfc \uc5bc\uad74, \ubab8\uc758 \uc6c0\uc9c1\uc784\uc774 \uc11c\ub85c \ub2e4\ub974\uac8c \ud3bc\uccd0\uc9c4\ub2e4. \uac19\uc740 \uc0ac\uac74 \uc55e\uc5d0\uc11c \ubaa8\ub450\uac00 \ub611\uac19\uc774 \ubc18\uc751\ud558\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc810\uc744 \ud55c \ud654\uba74\uc5d0 \uc5ee\ub294\ub2e4. \uc0ac\ub78c\uc758 \ud45c\uc815\uc744 \uba87 \uc885\ub958\ub85c \ubd84\ub958\ud574 \ubd99\uc778 \uadf8\ub9bc\ucc98\ub7fc \ubcf4\uae30\ubcf4\ub2e4, \uc778\ubb3c\ub07c\ub9ac \uc2dc\uc120\uacfc \uc190\uc9d3\uc774 \uc5b4\ub5bb\uac8c \uc774\uc5b4\uc9c0\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uacf5\uac04\uc744 \uad6c\uc131\ud558\ub294 \uc77c\uacfc \uc0ac\ub78c\uc758 \ubc18\uc751\uc744 \uad00\ucc30\ud558\ub294 \uc77c\uc774 \ub9cc\ub098\ub294 \uc7a5\uba74\uc774\ub2e4. \uc644\uc131\ub41c \uc720\uba85 \uc791\ud488\uc758 \uc774\ub984 \ub4a4\uc5d0 \ubb34\uc5c7\uc744 \ubcfc\uc9c0 \uad6c\uccb4\uc801\uc778 \uae38\uc774 \uc0dd\uae34\ub2e4. \ub2e4\ube48\uce58\uc758 \uc791\uc5c5\uc5d0\ub294 \ubbf8\uc644\uc131\uc73c\ub85c \ub0a8\uc740 \uac83\ub4e4\ub3c4 \uc788\ub2e4. \uc644\ubcbd\ud55c \ucc9c\uc7ac\ub77c\uba74 \uc65c \ub05d\ub0b4\uc9c0 \ubabb\ud588\ub290\ub0d0\uace0 \uc27d\uac8c \ubb3b\uae30\ubcf4\ub2e4, \uad00\uc2ec\uc758 \ud3ed\uacfc \uc758\ub8b0\uc758 \uc870\uac74, \uc774\ub3d9\uacfc \uc644\uc131 \uc0ac\uc774\uc5d0 \uae34\uc7a5\uc774 \uc788\uc5c8\ub2e4\ub294 \uc810\uc744 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ubb34\uc5c7\uc5d0\ub4e0 \uad00\uc2ec\uc774 \ub9ce\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ubaa8\ub4e0 \uc77c\uc744 \ub9c8\uce5c\ub2e4\ub294 \ubcf4\uc7a5\uc740 \uc544\ub2c8\ub2e4. \uc774 \ubaa8\uc2b5\uc744 \uadfc\uac70\ub85c \uc624\ub298\uc758 \ubcd1\uba85\uc774\ub098 \uc131\uaca9 \uc720\ud615\uc744 \ubd99\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \ud655\uc778\ud560 \uc218 \uc788\ub294 \uac83\uc740 \uc791\uc5c5\uc758 \uacb0\uacfc\uc640 \uae30\ub85d\uc758 \ud754\uc801\uc774\ub2e4. \ub9ce\uc740 \uc9c8\ubb38\uc744 \uac00\uc84c\ub2e4\ub294 \ucc2c\uc0ac\uc640 \uc2e4\uc81c\ub85c \uc644\uc131\ud574\uc57c \ud558\ub294 \uc77c\uc758 \ubd80\ub2f4\uc744 \ud568\uaed8 \ubcf4\ub294 \ud3b8\uc774 \ud55c \uc0ac\ub78c\uc758 \uc0dd\uc560\ub97c \ub354 \uc785\uccb4\uc801\uc73c\ub85c \ub9cc\ub4e0\ub2e4. \uadf8\ub294 \uc778\uccb4\uc640 \ud574\ubd80\ud559, \uad11\ud559\uacfc \uc790\uc5f0\uc758 \uc6c0\uc9c1\uc784 \ub4f1\uc744 \uc0b4\ud3c8\ub2e4. \ud654\uac00\uac00 \uc5bc\uad74\uacfc \ubab8\uc744 \ud45c\ud604\ud558\ub824\uba74 \uac89\uc73c\ub85c \ub4dc\ub7ec\ub09c \uc724\uacfd\ubfd0 \uc544\ub2c8\ub77c \uc548\uc5d0\uc11c \uc5b4\ub5bb\uac8c \uc6c0\uc9c1\uc774\ub294\uc9c0\ub3c4 \uad81\uae08\ud574\uc9c8 \uc218 \uc788\ub2e4. \ubb3c\uccb4\uac00 \ubcf4\uc774\ub294 \ubc29\uc2dd\uacfc \ube5b\uc744 \uc5f0\uad6c\ud558\ub294 \uad00\uc2ec\ub3c4 \ud68c\ud654\uc640 \ub5a8\uc5b4\uc838 \uc788\uc9c0 \uc54a\uc558\ub2e4. \uadf8\ub807\ub2e4\uace0 \ub0a8\uc544 \uc788\ub294 \ubaa8\ub4e0 \uae30\uacc4 \uadf8\ub9bc\uc744 \uc2e4\uc81c\ub85c \uc81c\uc791\ub418\uc5b4 \uc791\ub3d9\ud55c \ubc1c\uba85\ud488\uc774\ub77c\uace0 \ubd80\ub97c \uc218\ub294 \uc5c6\ub2e4. \uad00\ucc30 \uae30\ub85d, \uad6c\uc0c1, \uc644\uc131\ub41c \ubb3c\uac74\uc740 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \uc2dc\ub300\ub97c \uc55e\uc11c\uac14\ub2e4\ub294 \uac10\ud0c4 \uacc1\uc5d0 \ubb34\uc5c7\uc774 \uc2e4\uc81c\ub85c \ud655\uc778\ub418\ub294\uc9c0\ub97c \uc0b4\ud53c\uba74 \uc5f0\uad6c\uc758 \uc131\uaca9\uc774 \uc624\ud788\ub824 \ub354 \ubd84\uba85\ud574\uc9c4\ub2e4. \uadf8\uc758 \uae30\ub85d\uc5d0\ub294 \uc624\ub978\ucabd\uc5d0\uc11c \uc67c\ucabd\uc73c\ub85c \uc4f4 \uae00\uc774 \uc788\ub2e4. \ub0af\uc120 \uae00\uc528 \ubc29\ud5a5\uc740 \uae30\uc5b5\ud558\uae30 \uc88b\uc740 \ud2b9\uc9d5\uc774\uc9c0\ub9cc, \ube44\ubc00 \uc554\ud638\ub97c \ub9cc\ub4e4\ub824\uace0 \ubaa8\ub4e0 \uae00\uc744 \uadf8\ub807\uac8c \uc37c\ub2e4\uace0 \ub2e8\uc815\ud558\uc9c0\ub294 \ub9d0\uc790. \uae30\ub85d\uc758 \ub0b4\uc6a9\uacfc \uc4f0\ub294 \ubc29\uc2dd\uc740 \uac01\uac01 \uadfc\uac70\ub97c \uc0b4\ud3b4\uc57c \ud558\ub294 \ubb38\uc81c\ub2e4. \uae00\uc528\uc758 \ud2b9\uc774\ud568\uc5d0\uc11c \ud55c \uac78\uc74c \ub354 \uac00\uba74 \ubb34\uc5c7\uc744 \uacc4\uc18d \uae30\ub85d\ud588\ub294\uc9c0\uc5d0 \uad00\uc2ec\uc774 \uc0dd\uae34\ub2e4. \ubcf8 \uac83\uc744 \uadf8\ub9ac\uace0, \uad81\uae08\ud55c \uad6c\uc870\ub97c \uc0b4\ud53c\uba70, \ubb38\uc81c\ub97c \ub2e4\uc2dc \ub0a8\uae30\ub294 \ud589\uc704\ub2e4. \ucc9c\uc7ac\uc758 \uc0dd\uac01\uc740 \uba38\ub9bf\uc18d\uc5d0\uc11c \ud55c \ubc88\uc5d0 \uc644\uc131\ub418\uae30\ubcf4\ub2e4 \uc885\uc774 \uc704\uc5d0\uc11c \ud754\uc801\uacfc \uc9c8\ubb38\uc73c\ub85c \ub0a8\uae30\ub3c4 \ud588\ub2e4. \ub9d0\ub144\uc758 \ub2e4\ube48\uce58\ub294 \ud504\ub791\uc218\uc544 1\uc138\uc758 \ud6c4\uc6d0\uc744 \ubc1b\uc73c\uba70 \ud504\ub791\uc2a4\uc5d0\uc11c \uc9c0\ub0c8\ub2e4. \uadf8\uc758 \uc791\ud488\uacfc \uae30\ub85d\uc740 \ud55c \ub098\ub77c\uc758 \uc791\uc5c5\uc2e4\uc5d0\ub9cc \uba38\ubb34\ub974\uc9c0 \uc54a\uc558\ub2e4. \uc774\ub3d9\uacfc \ud6c4\uc6d0, \ud6c4\ub300\uc758 \uc218\uc9d1\uc744 \uac70\uce58\uba70 \uc624\ub298\uc758 \ub3c5\uc790\uac00 \uc5ec\ub7ec \uc7a5\uc18c\uc640 \uc790\ub8cc\uc5d0\uc11c \ub9cc\ub098\uac8c \ub418\uc5c8\ub2e4. \uc655\uc758 \ud488\uc5d0\uc11c \uc8fd\uc5c8\ub2e4\ub294 \uc2dd\uc758 \uc720\uba85\ud55c \uc7a5\uba74\uc744 \ud655\uc778\ub41c \ub9c8\uc9c0\ub9c9 \uc21c\uac04\ucc98\ub7fc \uc7ac\ud604\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ud55c \uc0ac\ub78c\uc758 \uc0dd\uc560\ub97c \uc544\ub984\ub2e4\uc6b4 \uc77c\ud654 \ud558\ub098\ub85c \ub2eb\uc9c0 \uc54a\uc544\ub3c4 \uadf8\ub9bc\uacfc \uae30\ub85d\uc740 \ucda9\ubd84\ud788 \ud48d\ubd80\ud558\ub2e4. \uc624\ud788\ub824 \ub0a8\uc740 \uc790\ub8cc\uac00 \uc11c\ub85c \ub2e4\ub978 \uc2dc\uae30\uc758 \uc77c\uc744 \uc5b4\ub5bb\uac8c \ubcf4\uc5ec \uc8fc\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\ub294 \uae38\uc774 \uc5f4\ub9b0\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \uc61b \uc804\uae30\uc5d0 \uc218\ub85d\ub41c \u3008\ucd5c\ud6c4\uc758 \ub9cc\ucc2c\u3009\uc758 \uc7ac\ud604 \ub3c4\ud310\uc774\ub2e4. \uc624\ub298\uc758 \ubcbd\ud654 \uc0c1\ud0dc\uc640 \uc0c9\uc744 \uadf8\ub300\ub85c \ubcf4\uc5ec \uc8fc\ub294 \ucd5c\uc2e0 \uc0ac\uc9c4\uc740 \uc544\ub2c8\uc9c0\ub9cc \uc778\ubb3c\uacfc \uacf5\uac04\uc758 \ud070 \uad6c\uc131\uc744 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \ub2e4\ube48\uce58\uc758 \uc0c1\uc0c1 \uc18d \uc790\ud654\uc0c1\uc744 \uc0c8\ub85c \ub9cc\ub4e0 \uc790\ub8cc\uc640\ub3c4 \uad6c\ubd84\ub41c\ub2e4. \uadf8\ub97c \uc77d\uace0 \ub098\uba74 \ud55c \uadf8\ub9bc \uc548\uc5d0\uc11c \ubb34\uc5c7\uc744 \ubcf4\ub824 \ud588\ub294\uc9c0 \ub2e4\uc2dc \ubb3c\uc5b4\ubcfc \uc218 \uc788\ub2e4. \uc0ac\ub78c\uc758 \ud45c\uc815\uacfc \uc190, \ubab8\uc758 \uad6c\uc870\uc640 \ube5b\uc774 \uc5b4\ub5bb\uac8c \uc5f0\uacb0\ub418\ub294\uac00. \ub2e4\uc7ac\ub2e4\ub2a5\ud558\ub2e4\ub294 \ud070 \uce6d\ucc2c\uc744 \uba87 \uac00\uc9c0 \uad6c\uccb4\uc801\uc778 \uad00\uc2ec\uc73c\ub85c \ub098\ub204\uba74, \ub2e4\ube48\uce58\ub294 \ubaa8\ub4e0 \uac83\uc744 \uc544\ub294 \uc774\ub984\uc5d0\uc11c \uc624\ub798 \uad00\ucc30\ud558\uace0 \uc9c8\ubb38\ud558\ub358 \uc0ac\ub78c\uc73c\ub85c \ubcf4\uc774\uae30 \uc2dc\uc791\ud55c\ub2e4."}, {"id": "les-miserables-reading-guide", "title": "\ub808 \ubbf8\uc81c\ub77c\ube14 \u2014 \ube75 \ud55c \uc870\uac01\uc5d0\uc11c \uc2dc\uc791\ub41c \uae34 \uc9c8\ubb38", "summary": "\uc8fc\uc694 \uc904\uac70\ub9ac\uc640 \uacb0\ub9d0, \uc778\ubb3c\ub4e4\uc758 \uc120\ud0dd\uacfc 1832\ub144 \ud30c\ub9ac \ubd09\uae30\uc758 \ubc30\uacbd\uc744 \ucc28\ub840\ub85c \ud480\uc5b4 \ubd05\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Literature", "url": "stories/les-miserables-reading-guide/index.html", "image": "media/les-miserables-reading-guide-scene-20261030.png", "alt": "\uc18c\ubc15\ud55c \ubc29\uc5d0\uc11c \ubbf8\ub9ac\uc5d8 \uc8fc\uad50\uac00 \uc9c0\uce5c \uc7a5\ubc1c\uc7a5\uc5d0\uac8c \uc740\ucd1b\ub300 \ub450 \uac1c\ub97c \uac74\ub124\ub294 \uc6d0\uc791 \uae30\ubc18 \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\ub808 \ubbf8\uc81c\ub77c\ube14 \u2014 \ube75 \ud55c \uc870\uac01\uc5d0\uc11c \uc2dc\uc791\ub41c \uae34 \uc9c8\ubb38 \uc7a5\ubc1c\uc7a5\u00b7\ud321\ud2f4\u00b7\ucf54\uc81c\ud2b8\u00b7\uc790\ubca0\ub974\uc758 \uc0b6\uc73c\ub85c \uc77d\ub294 \uc904\uac70\ub9ac\uc640 \uc791\ud488\uc758 \uc9c8\ubb38 \uc8fc\uc694 \uc904\uac70\ub9ac\uc640 \uacb0\ub9d0, \uc778\ubb3c\ub4e4\uc758 \uc120\ud0dd\uacfc 1832\ub144 \ud30c\ub9ac \ubd09\uae30\uc758 \ubc30\uacbd\uc744 \ucc28\ub840\ub85c \ud480\uc5b4 \ubd05\ub2c8\ub2e4. Literature \ubb38\ud654 \uc7a5\ubc1c\uc7a5\uc774 \ud6d4\uce5c \uac83\uc740 \ube75 \ud55c \uc870\uac01\uc774\uc5c8\ub2e4. \uad76\uc8fc\ub9ac\ub294 \ub204\uc774\uc758 \uc544\uc774\ub4e4\uc744 \uba39\uc774\ub824\uace0 \ud55c \uc77c\uc774\uc5c8\ub2e4. \uadf8\ub7ec\ub098 \uc808\ub3c4\uc640 \uc774\uc5b4\uc9c4 \ud0c8\uc625 \uc2dc\ub3c4\ub85c \uac10\uc625\uc5d0\uc11c \ubcf4\ub0b8 \uc2dc\uac04\uc740 \ubaa8\ub450 19\ub144\uc774 \ub41c\ub2e4. \ubb38\uc774 \uc5f4\ub824 \ubc16\uc73c\ub85c \ub098\uc628 \ub4a4\uc5d0\ub3c4 \uc0ac\ub78c\ub4e4\uc740 \uadf8\ub97c \uc804\uacfc\uc790\ub85c \uba3c\uc800 \ubcf8\ub2e4. \ucc98\ubc8c\uc740 \ub05d\ub0ac\ub294\ub370 \uc0b6\uc744 \ub2e4\uc2dc \uc2dc\uc791\ud560 \uc790\ub9ac\ub294 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ube45\ud1a0\ub974 \uc704\uace0\uac00 1862\ub144\uc5d0 \ubc1c\ud45c\ud55c \u300e\ub808 \ubbf8\uc81c\ub77c\ube14\u300f\uc740 \uc774 \ucd9c\ubc1c\uc810\uc5d0\uc11c \ud55c \uc0ac\ub78c\uc758 \ubcc0\ud654\uc640 \uc5ec\ub7ec \uc0ac\ub78c\uc758 \ubd88\ud589\uc744 \uae38\uac8c \uc5ee\ub294\ub2e4. \uc81c\ubaa9\uc740 \ub300\ub7b5 \u2018\ube44\ucc38\ud55c \uc0ac\ub78c\ub4e4\u2019\uc774\ub77c\ub294 \ub73b\uc774\ub2e4. \ud55c \uc601\uc6c5\uc758 \uc131\uacf5\ub2f4\uc744 \uae30\ub300\ud558\uae30\ubcf4\ub2e4, \uac00\ub09c\uacfc \uc81c\ub3c4 \uc18d\uc5d0\uc11c \uc11c\ub85c \uae30\ub300\uac70\ub098 \uc0c1\ucc98 \uc8fc\ub294 \uc0ac\ub78c\ub4e4\uc758 \uc774\uc57c\uae30\ub85c \ub4e4\uc5b4\uac00\uba74 \ubc29\ub300\ud55c \uc18c\uc124\uc758 \uae38\uc774 \uc870\uae08 \ubcf4\uc778\ub2e4. \uc774 \uae00\uc5d0\ub294 \uc8fc\uc694 \uc0ac\uac74\uacfc \uacb0\ub9d0\uc774 \ud3ec\ud568\ub418\uc5b4 \uc788\ub2e4. \uc791\ud488\uc744 \uc77d\uae30 \uc804 \uae38\uc7a1\uc774\ub85c \ubcf4\uc544\ub3c4 \uc88b\uace0, \ucc45\uc744 \ub36e\uc740 \ub4a4 \uc778\ubb3c\ub4e4\uc758 \uad00\uacc4\ub97c \uc815\ub9ac\ud558\ub294 \ub370 \uc368\ub3c4 \uc88b\ub2e4. \uc7a5\ubc1c\uc7a5\uc744 \uc9d1\uc5d0 \ub4e4\uc778 \ubbf8\ub9ac\uc5d8 \uc8fc\uad50\ub294 \uc74c\uc2dd\uacfc \uc7a0\uc790\ub9ac\ub97c \ub0b4\uc5b4 \uc900\ub2e4. \uc7a5\ubc1c\uc7a5\uc740 \uadf8 \uc9d1\uc5d0\uc11c \uc740\uc2dd\uae30\ub97c \ud6d4\uccd0 \ub2ec\uc544\ub0ac\ub2e4\uac00 \ud5cc\ubcd1\ub4e4\uc5d0\uac8c \ubd99\uc7a1\ud600 \ub3cc\uc544\uc628\ub2e4. \uadf8\ub54c \uc8fc\uad50\ub294 \uc790\uc2e0\uc774 \uc900 \ubb3c\uac74\uc774\ub77c\uace0 \ub9d0\ud558\uace0, \uc740\ucd1b\ub300\uae4c\uc9c0 \uac00\uc838\uac00\ub77c\uba70 \uac74\ub128\ub2e4. \uc7a5\ubc1c\uc7a5\uc774 \ub2e4\uc2dc \uc8c4\uc218\ub85c \ub3cc\uc544\uac08 \uc218\ub3c4 \uc788\ub358 \uc21c\uac04\uc5d0 \ub2e4\ub978 \uae38\uc774 \uc5f4\ub9b0 \uac83\uc774\ub2e4. \ud558\uc9c0\ub9cc \uc18c\uc124\uc740 \uadf8\ub97c \uc989\uc2dc \ucc29\ud55c \uc0ac\ub78c\uc73c\ub85c \ubc14\uafb8\uc9c0 \uc54a\ub294\ub2e4. \uc774\uc5b4 \ub9cc\ub09c \uc18c\ub144 \ud504\ud2f0 \uc81c\ub974\ubca0\uc758 \ub3d9\uc804\uc744 \ub3cc\ub824\uc8fc\uc9c0 \uc54a\ub294 \uc77c\uae4c\uc9c0 \ubc8c\uc5b4\uc9c4\ub2e4. \ub4a4\ub2a6\uac8c \uc790\uc2e0\uc758 \ud589\ub3d9\uc744 \uae68\ub2eb\uace0 \uad34\ub85c\uc6cc\ud558\ub294 \uc7a5\uba74\uc774 \uc911\uc694\ud558\ub2e4. \uc6a9\uc11c\ub97c \ud55c \ubc88 \ubc1b\uc558\ub2e4\uace0 \uc624\ub798 \uad73\uc5b4\uc9c4 \uc2b5\uad00\uc774 \uace7 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc8fc\uad50\uc758 \uce5c\uc808\uc740 \ubcc0\uc2e0\uc758 \ub9c8\ubc95\uc774\ub77c\uae30\ubcf4\ub2e4, \uc2a4\uc2a4\ub85c\ub97c \ub2e4\uc2dc \ubcf4\uac8c \ub9cc\ub4dc\ub294 \uc2dc\uc791\uc5d0 \uac00\uae5d\ub2e4. \uc138\uc6d4\uc774 \ud758\ub7ec \uc7a5\ubc1c\uc7a5\uc740 \ub9c8\ub4e4\ub80c\uc774\ub77c\ub294 \uc774\ub984\uc73c\ub85c \uc0b4\uc544\uac04\ub2e4. \uc0ac\uc5c5\uc744 \uc77c\uc73c\ucf1c \uc77c\uc790\ub9ac\ub97c \ub9cc\ub4e4\uace0 \uc0ac\ub78c\ub4e4\uc744 \ub3c4\uc6b0\uba70 \uc2dc\uc7a5\uc758 \uc790\ub9ac\uc5d0\uae4c\uc9c0 \uc624\ub978\ub2e4. \ub204\uad70\uac00\uc5d0\uac8c \uadf8\ub294 \uc874\uacbd\ud560 \ub9cc\ud55c \uc0ac\ub78c\uc774\ub2e4. \uadf8\ub7ec\ub098 \uacbd\ucc30\uad00 \uc790\ubca0\ub974\ub294 \uadf8\uc5d0\uac8c\uc11c \uacfc\uac70\uc758 \uc8c4\uc218\ub97c \ub5a0\uc62c\ub9b0\ub2e4. \uc774\ub984\uc744 \ubc14\uafb8\uc5b4\ub3c4 \uacfc\uac70\uc640 \ud604\uc7ac\uc758 \ucda9\ub3cc\uc740 \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \uc774\ub54c \uc0f9\ub9c8\ud2f0\uc678\ub77c\ub294 \uc0ac\ub78c\uc774 \uc7a5\ubc1c\uc7a5\uc73c\ub85c \uc624\uc778\ub418\uc5b4 \uc7ac\ud310\ubc1b\uac8c \ub41c\ub2e4. \uc7a5\ubc1c\uc7a5\uc774 \uc785\uc744 \ub2e4\ubb3c\uba74 \uc790\uc2e0\uc758 \uc0c8 \uc0b6\uacfc \ub3c4\uc2dc\uc758 \uc77c\uc790\ub9ac\ub97c \uc9c0\ud0ac \uc218 \uc788\uc9c0\ub9cc, \uc544\ubb34 \uc0c1\uad00 \uc5c6\ub294 \uc0ac\ub78c\uc774 \ub300\uc2e0 \ubc8c\uc744 \ubc1b\ub294\ub2e4. \uadf8\ub294 \uacb0\uad6d \ubc95\uc815\uc5d0 \ub098\uac00 \uc790\uc2e0\uc758 \uc815\uccb4\ub97c \ubc1d\ud78c\ub2e4. \uc18c\uc124\uc758 \uae34 \ub3c5\ubc31\uc774 \ud798\uc744 \uc5bb\ub294 \ub300\ubaa9\uc774\ub2e4. \ub3c5\uc790\ub294 \u2018\uc88b\uc740 \uc0ac\ub78c\uc774 \ub418\uc5c8\uc73c\ub2c8 \ube44\ubc00\uc744 \uc9c0\ucf1c\ub3c4 \ub41c\ub2e4\u2019\ub294 \uc26c\uc6b4 \ub2f5 \uc55e\uc5d0\uc11c \uba48\ucd94\uac8c \ub41c\ub2e4. \ud321\ud2f4\uc740 \uc5b4\ub9b0 \ub538 \ucf54\uc81c\ud2b8\ub97c \ud14c\ub098\ub974\ub514\uc5d0 \ubd80\ubd80\uc5d0\uac8c \ub9e1\uae30\uace0 \uc77c\ud558\ub294 \uc5ec\uc131\uc774\ub2e4. \ub538\uc744 \ub3cc\ubcf4\ub294 \ube44\uc6a9\uc744 \ubcf4\ub0b4\uc57c \ud558\uc9c0\ub9cc \uc77c\uc790\ub9ac\ub97c \uc783\uace0, \uc810\uc810 \ub354 \uad81\uc9c0\uc5d0 \ubab0\ub9b0\ub2e4. \ud14c\ub098\ub974\ub514\uc5d0 \ubd80\ubd80\ub294 \ucf54\uc81c\ud2b8\ub97c \uc798 \ub3cc\ubcf4\uc9c0 \uc54a\uc73c\uba74\uc11c\ub3c4 \ub3c8\uc744 \uc694\uad6c\ud55c\ub2e4. \ud321\ud2f4\uc740 \ubab8\uacfc \uc0dd\ud65c\uc744 \uc18c\ubaa8\ud558\uba70 \ub538\uc744 \uc9c0\ud0a4\ub824 \uc560\uc4f4\ub2e4. \uc704\uace0\ub294 \uc774 \uc778\ubb3c\uc744 \ud1b5\ud574 \uac00\ub09c\uc744 \ub2e8\uc9c0 \uc131\uc2e4\ud558\uc9c0 \ubabb\ud55c \uac1c\uc778\uc758 \ubb38\uc81c\ub85c \uc124\uba85\ud560 \uc218 \uc788\ub294\uc9c0 \ubb3b\ub294\ub2e4. \uc77c\uc790\ub9ac\uc640 \ud3c9\ud310, \ub3cc\ubd04\uc758 \ube44\uc6a9\uc774 \ub3d9\uc2dc\uc5d0 \ubb34\ub108\uc9c0\uba74 \ubb34\uc5c7\uc774 \ub0a8\ub294\uac00. \uc7a5\ubc1c\uc7a5\uc740 \ud321\ud2f4\uc744 \ub3d5\uace0 \ucf54\uc81c\ud2b8\ub97c \ub370\ub824\uc624\uaca0\ub2e4\uace0 \uc57d\uc18d\ud558\uc9c0\ub9cc, \ud321\ud2f4\uc740 \ub538\uacfc \ub2e4\uc2dc \ub9cc\ub098\uc9c0 \ubabb\ud55c \ucc44 \uc8fd\ub294\ub2e4. \uc57d\uc18d\uc740 \uc774\uc81c \ub0a8\uc740 \uc0ac\ub78c\uc758 \ucc45\uc784\uc774 \ub41c\ub2e4. \ucf54\uc81c\ud2b8\ub294 \ud14c\ub098\ub974\ub514\uc5d0 \ubd80\ubd80\uc758 \uc9d1\uc5d0\uc11c \ud5c8\ub4dc\ub81b\uc77c\uc744 \ud558\uba70 \uc9c0\ub0b8\ub2e4. \uc5b4\ub9b0\uc544\uc774\uac00 \uc5b4\ub450\uc6b4 \uae38\uc5d0\uc11c \ubb3c\uc744 \uae38\uc5b4 \ub098\ub974\ub294 \uc7a5\uba74\uc740 \uc18c\uc124\uc758 \ube44\ucc38\ud568\uc744 \ucd94\uc0c1\uc801\uc778 \ub9d0\ubcf4\ub2e4 \ubd84\uba85\ud558\uac8c \ubcf4\uc5ec \uc900\ub2e4. \uc7a5\ubc1c\uc7a5\uc740 \uadf8 \uc544\uc774\ub97c \ub9cc\ub098 \ubb3c\ud1b5\uc744 \ub4e4\uc5b4 \uc8fc\uace0, \uacb0\uad6d \uadf8 \uc9d1\uc5d0\uc11c \ub370\ub9ac\uace0 \ub098\uc628\ub2e4. \ub204\uad70\uac00\uc758 \uc9d0\uc744 \ub300\uc2e0 \ub4dc\ub294 \ud589\ub3d9\uc774 \ub450 \uc0ac\ub78c\uc758 \uad00\uacc4\ub97c \uc2dc\uc791\ud55c\ub2e4. \ucf54\uc81c\ud2b8\ub97c \ubcf4\ud638\ud558\ub294 \ub3d9\uc548 \uc7a5\ubc1c\uc7a5\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \ub3c4\uc6c0\uc744 \ubc1b\uc558\ub358 \uc0ac\ub78c\uc774 \uc774\uc81c \ub204\uad70\uac00\ub97c \ub3cc\ubcf4\ub294 \uc0ac\ub78c\uc774 \ub41c\ub2e4. \uc790\ubca0\ub974\uc758 \ucd94\uc801\uc744 \ud53c\ud574 \ud30c\ub9ac\uc758 \uc218\ub140\uc6d0\uc5d0 \uba38\ubb34\ub294 \uacfc\uc815\uc5d0\ub294 \uc7a5\ubc1c\uc7a5\uc774 \uc804\uc5d0 \uad6c\ud574 \uc900 \ud3ec\uc290\ub974\ubc29\uc758 \ub3c4\uc6c0\ub3c4 \uc791\uc6a9\ud55c\ub2e4. \uc18c\uc124\uc5d0\uc11c \uc120\ud589\uc740 \ub298 \uc989\uac01\uc801\uc778 \ubcf4\uc0c1\uc73c\ub85c \ub3cc\uc544\uc624\uc9c0\ub294 \uc54a\uc9c0\ub9cc, \uc0ac\ub78c \uc0ac\uc774\uc5d0 \uc608\uc0c1\ud558\uc9c0 \ubabb\ud588\ub358 \uae38\uc744 \ub0a8\uae34\ub2e4. \uc131\uc7a5\ud55c \ucf54\uc81c\ud2b8\ub294 \uccad\ub144 \ub9c8\ub9ac\uc6b0\uc2a4\ub97c \ub9cc\ub098 \uc0ac\ub791\uc5d0 \ube60\uc9c4\ub2e4. \ub9c8\ub9ac\uc6b0\uc2a4\ub294 \uac00\uc871\uacfc \uc815\uce58\uc801 \uc0dd\uac01\uc744 \ub193\uace0 \uac08\ub4f1\ud558\uace0, \uacf5\ud654\uc8fc\uc758\ub97c \uc9c0\uc9c0\ud558\ub294 \uc80a\uc740\uc774\ub4e4\uacfc\ub3c4 \uac00\uae4c\uc774 \uc9c0\ub0b8\ub2e4. \ub450 \uc0ac\ub78c\uc758 \uc0ac\ub791\uc740 \uc18c\uc124\uc5d0 \ubc1d\uc740 \uc6c0\uc9c1\uc784\uc744 \ub9cc\ub4e4\uc9c0\ub9cc \uc7a5\ubc1c\uc7a5\uc5d0\uac8c\ub294 \ubd88\uc548\uc774 \ub41c\ub2e4. \uc790\uc2e0\uc5d0\uac8c \uc0b6\uc758 \uc911\uc2ec\uc774 \ub41c \uc544\uc774\uac00 \ub2e4\ub978 \uc0ac\ub78c\uc744 \ud5a5\ud558\uae30 \uc2dc\uc791\ud55c \uac83\uc774\ub2e4. \ub9c8\ub9ac\uc6b0\uc2a4\ub97c \uc0ac\ub791\ud558\ub294 \uc5d0\ud3ec\ub2cc\uc740 \ud14c\ub098\ub974\ub514\uc5d0 \ubd80\ubd80\uc758 \ub538\uc774\ub2e4. \uac19\uc740 \uc9d1\uc5d0\uc11c \uc790\ub780 \uc544\uc774\ub4e4\uc774 \uc11c\ub85c \ub2e4\ub978 \uae38\uc5d0 \ub193\uc774\uace0, \uc0ac\ub791\ud558\ub294 \ub9c8\uc74c\ub3c4 \ubaa8\ub450 \uac19\uc740 \uacb0\ub9d0\ub85c \uc774\uc5b4\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc704\uace0\ub294 \uc8fc\uc778\uacf5 \ub450 \uc0ac\ub78c\uc758 \uc5f0\uc560\ub9cc \ub530\ub85c \ub5bc\uc5b4 \ub193\uc9c0 \uc54a\uace0 \uc8fc\ubcc0\uc758 \uac00\ub09c\uacfc \uc9c8\ud22c, \ud5cc\uc2e0\uc744 \ud568\uaed8 \ubcf4\uc5ec \uc900\ub2e4. \uc7a5\ubc1c\uc7a5 \uc5ed\uc2dc \ucf54\uc81c\ud2b8\uc758 \ud589\ubcf5\uc744 \ubc14\ub780\ub2e4\ub294 \ub9c8\uc74c\uacfc \uc790\uc2e0 \uacc1\uc5d0 \ub450\uace0 \uc2f6\ub2e4\ub294 \ub9c8\uc74c \uc0ac\uc774\uc5d0\uc11c \ud754\ub4e4\ub9b0\ub2e4. \ud6c4\ubc18\uc758 \ubd09\uae30\ub294 1789\ub144 \ud504\ub791\uc2a4\ud601\uba85\uc774 \uc544\ub2c8\ub77c 1832\ub144 6\uc6d4 \ud30c\ub9ac\uc758 \ubd09\uae30\ub2e4. \ub77c\ub9c8\ub974\ud06c \uc7a5\uad70\uc758 \uc7a5\ub840\ub97c \uacc4\uae30\ub85c \uae34\uc7a5\uc774 \ub192\uc544\uc9c0\uace0, \uc559\uc878\ub77c\ub97c \ube44\ub86f\ud55c \uccad\ub144\ub4e4\uc740 \ubc14\ub9ac\ucf00\uc774\ub4dc\ub97c \uc313\ub294\ub2e4. \ud601\uba85\uc73c\ub85c \ubaa8\ub4e0 \ubb38\uc81c\uac00 \ud574\uacb0\ub41c \uc0ac\ud68c\uac00 \uc544\ub2c8\ub77c, \uadf8 \ub4a4\uc5d0\ub3c4 \ubd88\ud3c9\ub4f1\uacfc \uc815\uce58\uc801 \uac08\ub4f1\uc774 \ub0a8\uc544 \uc788\ub358 \uc0ac\ud68c\ub2e4. \uc774\uacf3\uc5d0\ub294 \uc815\uce58\uc801 \uc774\uc0c1\uc744 \ub9d0\ud558\ub294 \uccad\ub144\ub4e4\ubfd0 \uc544\ub2c8\ub77c \uac70\ub9ac\uc758 \uc18c\ub144 \uac00\ube0c\ub85c\uc288\ub3c4 \uc788\ub2e4. \ubd09\uae30\ub294 \uc7a5\ub300\ud55c \uc601\uc6c5\ub2f4\uc73c\ub85c\ub9cc \uc9c4\ud589\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc80a\uc740\uc774\ub4e4\uc774 \uc8fd\uace0, \uc5d0\ud3ec\ub2cc\ub3c4 \ub9c8\ub9ac\uc6b0\uc2a4 \uacc1\uc5d0\uc11c \ubaa9\uc228\uc744 \uc783\ub294\ub2e4. \uac1c\uc778\uc758 \uc0ac\ub791\uacfc \uc0ac\ud68c\ub97c \ubc14\uafb8\ub824\ub294 \uc5f4\ub9dd\uc774 \ud55c \uc7a5\uc18c\uc5d0\uc11c \ub9cc\ub098\ub294 \ub3d9\uc2dc\uc5d0, \uadf8 \ub300\uac00\uac00 \uc5bc\ub9c8\ub098 \ud070\uc9c0\ub3c4 \ub4dc\ub7ec\ub09c\ub2e4. \uc7a5\ubc1c\uc7a5\uc740 \ubc14\ub9ac\ucf00\uc774\ub4dc\uc5d0\uc11c \ubd99\uc7a1\ud78c \uc790\ubca0\ub974\ub97c \ucc98\ud615\ud558\ub294 \ub300\uc2e0 \ud480\uc5b4 \uc900\ub2e4. \uc790\ubca0\ub974\uc5d0\uac8c \uc7a5\ubc1c\uc7a5\uc740 \ubd99\uc7a1\uc544\uc57c \ud560 \ubc94\uc8c4\uc790\ub2e4. \uadf8\ub7f0\ub370 \uadf8 \uc0ac\ub78c\uc774 \uc790\uc2e0\uc744 \uc0b4\ub824 \ubcf4\ub0b8\ub2e4. \ubc95\uc744 \uc9c0\ud0a4\ub294 \uc0ac\ub78c\uc740 \uc120\ud558\uace0 \uc8c4\uc218\ub294 \uc545\ud558\ub2e4\ub294 \ub2e8\ub2e8\ud55c \uad6c\ubd84 \uc548\uc5d0 \ub4e4\uc5b4\uac00\uc9c0 \uc54a\ub294 \uc77c\uc774 \ubc8c\uc5b4\uc9c4 \uc148\uc774\ub2e4. \uc804\ud22c \ub4a4 \uc7a5\ubc1c\uc7a5\uc740 \ubd80\uc0c1\ud55c \ub9c8\ub9ac\uc6b0\uc2a4\ub97c \uc5c5\uace0 \ud558\uc218\ub3c4\ub97c \uc9c0\ub098 \ube60\uc838\ub098\uc628\ub2e4. \ucf54\uc81c\ud2b8\ub97c \uc790\uc2e0\uc5d0\uac8c\uc11c \ub370\ub824\uac08 \uc0ac\ub78c\uc744 \uad6c\ud55c\ub2e4\ub294 \uc810\uc5d0\uc11c \uc774 \ud589\ub3d9\uc740 \ub354 \ubb34\uac81\ub2e4. \ub2e4\uc2dc \uc7a5\ubc1c\uc7a5\uc744 \ub9cc\ub09c \uc790\ubca0\ub974\ub294 \ub05d\ub0b4 \uadf8\ub97c \ub193\uc544\uc8fc\uc9c0\ub9cc, \uc790\uc2e0\uc774 \ubbff\uc5b4 \uc628 \uc9c8\uc11c\uc640 \ub208\uc55e\uc758 \uc778\uac04 \uc0ac\uc774\uc758 \ubaa8\uc21c\uc744 \uacac\ub514\uc9c0 \ubabb\ud558\uace0 \uc2a4\uc2a4\ub85c \uc0dd\uc744 \ub9c8\uac10\ud55c\ub2e4. \uc774 \uc8fd\uc74c\uc744 \ub2e8\uc21c\ud55c \uc545\ub2f9\uc758 \ud328\ubc30\ub85c \uc77d\uc73c\uba74 \uc18c\uc124\uc774 \uc624\ub798 \uc313\uc544 \uc628 \uac08\ub4f1\uc744 \ub193\uce58\uac8c \ub41c\ub2e4. \ub9c8\ub9ac\uc6b0\uc2a4\uc640 \ucf54\uc81c\ud2b8\ub294 \uacb0\ud63c\ud55c\ub2e4. \uc7a5\ubc1c\uc7a5\uc740 \uc790\uc2e0\uc758 \uc804\uacfc\ub97c \ub9c8\ub9ac\uc6b0\uc2a4\uc5d0\uac8c \uc54c\ub9ac\uace0, \uc624\ud574\uc640 \uac70\ub9ac\uac10 \uc18d\uc5d0\uc11c \uc810\ucc28 \ucf54\uc81c\ud2b8\uc758 \uc77c\uc0c1\uc5d0\uc11c \ubb3c\ub7ec\ub09c\ub2e4. \uc0b4\uc544\ub0a8\uc740 \uc0ac\ub78c\ub4e4\uc774 \ud589\ubcf5\ud574\uc84c\ub2e4\uace0 \ud574\uc11c \uadf8\ub4e4\uc744 \uc0b4\ub9b0 \uc0ac\ub78c\uc758 \ubaab\uae4c\uc9c0 \uc790\uc5f0\uc2a4\ub7fd\uac8c \ubcf4\uc7a5\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc18c\uc124\uc740 \ucd95\ubcf5\uc758 \uc7a5\uba74 \ub4a4\uc5d0 \ub0a8\uc740 \uc678\ub85c\uc6c0\uae4c\uc9c0 \ub530\ub77c\uac04\ub2e4. \ub4a4\ub2a6\uac8c \ub9c8\ub9ac\uc6b0\uc2a4\ub294 \uc790\uc2e0\uc744 \uad6c\ud55c \uc0ac\ub78c\uc774 \uc7a5\ubc1c\uc7a5\uc774\uc5c8\uc74c\uc744 \uc54c\uac8c \ub41c\ub2e4. \ucf54\uc81c\ud2b8\uc640 \ud568\uaed8 \ucc3e\uc544\uac14\uc744 \ub54c \uc7a5\ubc1c\uc7a5\uc758 \uc0dd\uba85\uc740 \uc5bc\ub9c8 \ub0a8\uc9c0 \uc54a\uc558\ub2e4. \ub450 \uc0ac\ub78c\uc774 \uacc1\uc5d0 \uc788\ub294 \uac00\uc6b4\ub370 \uadf8\uc758 \uc0b6\uc740 \ub05d\uc744 \ub9fa\uace0, \uc8fc\uad50\uc5d0\uac8c \ubc1b\uc740 \uc740\ucd1b\ub300\ub294 \ub9c8\uc9c0\ub9c9 \uc7a5\uba74\uc5d0\ub3c4 \ub0a8\ub294\ub2e4. \ucc98\uc74c \ubc1b\uc558\ub358 \uc790\ube44\uac00 \uae34 \uc138\uc6d4 \ub3d9\uc548 \uc5b4\ub5a4 \uc0b6\uc73c\ub85c \uc774\uc5b4\uc84c\ub294\uc9c0\ub97c \ub3cc\uc544\ubcf4\uac8c \ud558\ub294 \ubb3c\uac74\uc774\ub2e4. \uc6d0\uc791\uc5d0\ub294 \uc6cc\ud138\ub8e8 \uc804\ud22c, \uc218\ub3c4\uc6d0, \ud30c\ub9ac\uc758 \ud558\uc218\ub3c4\ucc98\ub7fc \uc904\uac70\ub9ac\ub9cc \ub530\ub77c\uac00\ub824\ub294 \ub3c5\uc790\uc5d0\uac8c \uae38\uac8c \ub290\uaef4\uc9c8 \uc124\uba85\uc774 \uc788\ub2e4. \ub9c8\ub9ac\uc6b0\uc2a4\uc758 \uc544\ubc84\uc9c0\uc640 \ud14c\ub098\ub974\ub514\uc5d0\uac00 \uc5bd\ud78c \uacfc\uac70\ub97c \uc774\ud574\ud558\uac8c \ud558\ub294 \ub300\ubaa9\ub3c4 \uc788\uc9c0\ub9cc, \ubaa8\ub4e0 \uc124\uba85\uc774 \uc0ac\uac74\uc744 \ube68\ub9ac \uc9c4\ud589\uc2dc\ud0a4\uae30 \uc704\ud574 \uc874\uc7ac\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc704\uace0\ub294 \uc0ac\ub78c\uc774 \uc0b4\uc544\uac00\ub294 \uc0ac\ud68c \uc804\uccb4\ub97c \uc18c\uc124 \uc548\uc73c\ub85c \ub04c\uc5b4\ub4e4\uc774\ub824 \ud55c\ub2e4. \uc774\ub7f0 \ubd80\ubd84\uc744 \uc77d\uc73c\uba70 \uc911\uc2ec \uc9c8\ubb38\uc744 \ubd99\ub4e4\uc5b4 \ub450\uba74 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ubb34\uc5c7\uc774 \ud55c \uc0ac\ub78c\uc744 \ube44\ucc38\ud558\uac8c \ub9cc\ub4dc\ub294\uac00, \uc0ac\ub78c\uc744 \ubc14\uafb8\ub294 \uac83\uc740 \ubb34\uc5c7\uc778\uac00, \ubc95\uc774 \uc9c0\ucf1c \uc8fc\uc9c0 \ubabb\ud558\ub294 \uc0ac\ub78c\uc5d0\uac8c \uc5b4\ub5a4 \ucc45\uc784\uc744 \uc9c8 \uac83\uc778\uac00. \uc778\ubb3c\uc758 \uc120\ud0dd\uc5d0\uc11c \uc7a0\uc2dc \uba40\uc5b4\uc9c4 \uc124\uba85\ub3c4 \uc774 \uc9c8\ubb38\ub4e4\uacfc \uc5f0\uacb0\ud574 \ubcfc \uc218 \uc788\ub2e4. \ucc98\uc74c\ubd80\ud130 \ubaa8\ub4e0 \ubc30\uacbd\uc744 \uc678\uc6b0\ub824 \ud558\uae30\ubcf4\ub2e4, \uc9c0\uae08 \uc774 \uc7a5\uba74\uc774 \ub204\uad6c\uc758 \uc0b6\uc744 \ub354 \uc798 \ubcf4\uac8c \ud558\ub294\uc9c0 \uc0dd\uac01\ud574 \ubcf4\uc790. \uc7a5\ubc1c\uc7a5\uc740 \uc22d\uace0\ud55c \uc120\ud0dd\uc744 \ud558\uc9c0\ub9cc \ucc98\uc74c\ubd80\ud130 \uc644\uc131\ub41c \uc131\uc778\uc740 \uc544\ub2c8\ub2e4. \uc790\ubca0\ub974\ub294 \ubb34\uc870\uac74 \uc0ac\uc545\ud574\uc11c\ub9cc \uc6c0\uc9c1\uc774\uc9c0 \uc54a\uace0, \ucf54\uc81c\ud2b8\uc758 \uc0ac\ub791\ub3c4 \uc544\ubc84\uc9c0\uc758 \ud76c\uc0dd\uc744 \uc989\uc2dc \uc54c\uc544\ubcf4\ub294 \uc644\ubcbd\ud55c \uc774\ud574\ub85c \uc774\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \uc774\ub7f0 \uc5b4\uae0b\ub0a8\uc774 \uc778\ubb3c\ub4e4\uc744 \ub2e8\uc21c\ud55c \uad50\ud6c8\uc758 \ud45c\uc9c0\ud310\ubcf4\ub2e4 \uc624\ub798 \uc0b4\uc544 \uc788\uac8c \ud55c\ub2e4. \u300e\ub808 \ubbf8\uc81c\ub77c\ube14\u300f\uc744 \uc77d\uace0 \ub0a8\ub294 \uac83\uc740 \ube75\uc744 \ud6d4\uce5c \uc8c4\uc218\uac00 \ud6cc\ub96d\ud55c \uc0ac\ub78c\uc774 \ub418\uc5c8\ub2e4\ub294 \uc904\uac70\ub9ac\ub9cc\uc774 \uc544\ub2c8\ub2e4. \ud321\ud2f4\uc5d0\uac8c\ub294 \uc65c \ubc84\ud2f8 \uc790\ub9ac\uac00 \uc5c6\uc5c8\ub294\uc9c0, \ucf54\uc81c\ud2b8\uc5d0\uac8c\ub294 \ub204\uac00 \uc190\uc744 \ub0b4\ubc00\uc5c8\ub294\uc9c0, \uc790\ubca0\ub974\ub294 \uc65c \ub2e4\ub978 \ud310\ub2e8\uc73c\ub85c \ub118\uc5b4\uac00\uc9c0 \ubabb\ud588\ub294\uc9c0\ub3c4 \ud568\uaed8 \ub0a8\ub294\ub2e4. \uc81c\ubaa9\uc774 \ubcf5\uc218\ud615\uc778 \uae4c\ub2ed\uc744 \ub5a0\uc62c\ub9ac\uba70 \ud55c \uc0ac\ub78c\uc529 \ub2e4\uc2dc \ubcf4\uba74, \uae34 \uc18c\uc124\uc740 \uc5ec\ub7ec \uc0b6\uc744 \uc774\ud574\ud558\ub294 \uae38\ub85c \ubc14\ub010\ub2e4."}, {"id": "man-ray-chess-photo-layout", "title": "\uccb4\uc2a4 \ub9d0\uc744 \uc5b4\ub514\uc5d0 \ub458\uc9c0 \uc624\ub798\ub41c \uc0ac\uc9c4\uc5d0 \ubb3c\uc5c8\ub2e4", "summary": "\ub9e8 \ub808\uc774\uc758 \uccb4\uc2a4 \uc138\ud2b8\ub97c \uc804\uc2dc\ud558\uba70 \ub9d0\uc758 \uc704\uce58\ub97c \uace0\ub974\ub358 \uacfc\uc815\uc744 \ub530\ub77c\uac11\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Art", "url": "stories/man-ray-chess-photo-layout/index.html", "image": "media/man-ray-chess-photo-layout.jpg", "alt": "\uccb4\uc2a4 \ub9d0\uc744 \uc5b4\ub514\uc5d0 \ub458\uc9c0 \uc624\ub798\ub41c \uc0ac\uc9c4\uc5d0 \ubb3c\uc5c8\ub2e4\uc758 \uc8fc\uc81c\ub97c \ud45c\ud604\ud55c AI \uc124\uba85\uc6a9 \uc0bd\ud654. \uc2e4\uc81c \uc791\ud488\uc774\ub098 \uac74\ucd95\ubb3c\uc744 \uadf8\ub300\ub85c \uc7ac\ud604\ud55c \uc774\ubbf8\uc9c0\uac00 \uc544\ub2d9\ub2c8\ub2e4.", "text": "\uccb4\uc2a4 \ub9d0\uc744 \uc5b4\ub514\uc5d0 \ub458\uc9c0 \uc624\ub798\ub41c \uc0ac\uc9c4\uc5d0 \ubb3c\uc5c8\ub2e4 \uc791\ud488 \uc804\uc2dc\uac00 \uc791\uc740 \ucd94\ub9ac \ubb38\uc81c\uac00 \ub41c \uc21c\uac04 \ub9e8 \ub808\uc774\uc758 \uccb4\uc2a4 \uc138\ud2b8\ub97c \uc804\uc2dc\ud558\uba70 \ub9d0\uc758 \uc704\uce58\ub97c \uace0\ub974\ub358 \uacfc\uc815\uc744 \ub530\ub77c\uac11\ub2c8\ub2e4. Art \ubb38\ud654 \uccb4\uc2a4 \uc138\ud2b8\ub97c \uc804\uc2dc\ud55c\ub2e4\uace0 \ud558\uba74 \ub9d0\ub4e4\uc744 \uc608\uc058\uac8c \uc138\uc6cc \ub450\uba74 \ub420 \uac83 \uac19\ub2e4. \uadf8\ub7f0\ub370 \uac8c\uc784 \ub3c4\uad6c\ub294 \uc704\uce58\uc5d0 \ub530\ub77c \uc804\ud600 \ub2e4\ub978 \uc7a5\uba74\uc774 \ub41c\ub2e4. \ub9c9 \uc2dc\uc791\ud55c \ud310\uc77c \uc218\ub3c4 \uc788\uace0, \ub204\uad70\uac00 \ub2e4\uc74c \uc218\ub97c \uace0\ubbfc\ud558\ub294 \ud310\uc77c \uc218\ub3c4 \uc788\ub2e4. \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc740 \ub9e8 \ub808\uc774\uac00 \ub514\uc790\uc778\ud55c \uccb4\uc2a4 \uc138\ud2b8\ub97c \ub193\uc73c\uba70 \uc774\ub7f0 \uace0\ubbfc\uc744 \ud588\ub2e4. \uc5b4\ub5bb\uac8c \ubc30\uce58\ud574\uc57c \uc774 \ubb3c\uac74\uc744 \ub354 \uc798 \ubcf4\uc5ec \uc904 \uc218 \uc788\uc744\uae4c. \uadf8 \uc9c8\ubb38\uc740 \uc624\ub798\ub41c \uc0ac\uc9c4 \ud55c \uc7a5\uc73c\ub85c \uc774\uc5b4\uc84c\ub2e4. \uacf5\uc2dd \uc124\uba85\uc5d0 \ub530\ub974\uba74 \ub9e8 \ub808\uc774\ub294 1920\ub144\uc5d0 \uccab \uccb4\uc2a4 \uc138\ud2b8\ub97c \ub514\uc790\uc778\ud588\ub2e4. \ubbf8\uc220\uad00\uc758 \uc138\ud2b8\ub294 \uc778\ub3c4 \uc778\ub3c4\ub974\uc758 \ub9c8\ud558\ub77c\uc790\ub97c \uc704\ud574 1927\ub144\uc5d0 \ub9cc\ub4e0 \uac83\uc73c\ub85c \uc18c\uac1c\ub41c\ub2e4. \uc608\uc220\uac00\uac00 \ub9cc\ub4e0 \uccb4\uc2a4 \ub9d0\uc774\ub2c8 \uc870\uac01\uc73c\ub85c \ubcfc \uc218 \uc788\uc9c0\ub9cc, \ub3d9\uc2dc\uc5d0 \uc2e4\uc81c \uac8c\uc784\uc758 \uc790\ub9ac\ub97c \uac00\uc9c4 \ubb3c\uac74\uc774\ub2e4. \ub9d0\uc744 \ud55c \uac1c\ub9cc \uc55e\uc73c\ub85c \uc62e\uaca8 \ub193\ub294 \uac83\uacfc \uac8c\uc784 \uc911\uac04\uc758 \ud310\uc744 \ub9cc\ub4dc\ub294 \uac83\uc740 \ubcf4\ub294 \uc0ac\ub78c\uc5d0\uac8c \ub2e4\ub978 \ub290\ub08c\uc744 \uc900\ub2e4. \ubbf8\uc220\uad00\uc740 \ub2e4\ub978 \uc138\ud2b8\uc758 \uc0ac\uc9c4\uc744 \ucc38\uace0\ud574 \ubc30\uce58\ud558\uae30\ub3c4 \ud588\uc9c0\ub9cc \ub354 \uc624\ub798\ub41c \uc790\ub8cc\ub97c \uc0b4\ud3c8\ub2e4. \uc911\uc694\ud55c \ub2e8\uc11c\ub294 1921\ub144 \ub9e8 \ub808\uc774\uc758 \uc790\ud654\uc0c1 \uc0ac\uc9c4\uc774\uc5c8\ub2e4. \ubb38\uc81c\ub294 \uc0ac\uc9c4\uc5d0 \uccb4\uc2a4\ud310 \uc77c\ubd80\ub9cc \ub098\uc640 \uc788\ub2e4\ub294 \uc810\uc774\uc5c8\ub2e4. \uae30\uad00 \uae00\uc758 \ud544\uc790\ub294 \uc0ac\uc9c4\uc744 \ud655\ub300\ud558\uace0 \ubcf4\uc774\ub294 \uce78\uc758 \uac00\uc7a5\uc790\ub9ac\ub97c \ub530\ub77c \ud3c9\ud589\uc120\uc744 \uadf8\uc5c8\ub2e4. \ubcf4\uc774\ub294 \ub9d0\uc758 \uc704\uce58\ub97c \ucc3e\uace0, \uccb4\uc2a4\uc758 \uaddc\uce59\uc744 \uc0dd\uac01\ud574 \uac00\ub824\uc9c4 \ubd80\ubd84\uc758 \ubc30\uce58\ub97c \ucd94\uc815\ud588\ub2e4. \uc0ac\uc9c4\uc744 \ubcf4\ub294 \uc77c\uc774 \uc791\uc740 \ud37c\uc990 \ud480\uc774\uac00 \ub41c \uac83\uc774\ub2e4. \uccb4\uc2a4 \uc138\ud2b8\ub97c \uc870\uac01\ucc98\ub7fc \ubcf8\ub2e4\uba74 \uac1c\ubcc4 \ub9d0\uc758 \ud615\ud0dc\uc640 \uc7ac\ub8cc\uac00 \uba3c\uc800 \uc911\uc694\ud574 \ubcf4\uc778\ub2e4. \uac8c\uc784\uc758 \ub3c4\uad6c\ub85c \ubcf4\uba74 \uc5b4\ub5a4 \ub9d0\uc774 \uc5b4\ub290 \uce78\uc5d0 \uc788\ub294\uc9c0\ub3c4 \uc758\ubbf8\ub97c \ub9cc\ub4e0\ub2e4. \uac19\uc740 \ubb3c\uac74\uc744 \ub193\uace0\ub3c4 \uc804\uc2dc\ub294 \ub450 \uc9c8\ubb38 \uc0ac\uc774\uc5d0\uc11c \uc120\ud0dd\ud574\uc57c \ud55c\ub2e4. \ub2e8\uc815\ud558\uac8c \uc904 \uc138\uc6b0\ub294 \uac83\uc774 \uc5b8\uc81c\ub098 \uc81c\uc791\uc790\uac00 \uc990\uae30\ub358 \uac8c\uc784\uc758 \ubaa8\uc2b5\uc744 \uc798 \ubcf4\uc5ec \uc8fc\ub294 \uac83\uc740 \uc544\ub2d0 \uc218 \uc788\ub2e4. \ubbf8\uc220\uad00\uc740 \ud55c\ub54c \uc878 \ud558\ub098\ub9cc \uc55e\uc73c\ub85c \uc62e\uaca8 \uc804\uc2dc\ud588\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \uc774\ud6c4 \ub2e4\ub978 \uc18c\uc7a5 \uc138\ud2b8\uc758 \uc0ac\uc9c4\uc744 \ucc38\uace0\ud55c \ubc30\uce58\ub3c4 \uc0ac\uc6a9\ud588\ub2e4. \uc791\ud488\uc774 \ub0a8\uc544 \uc788\ub2e4\uace0 \uadf8 \uc804\uc2dc \ubc29\uc2dd\uc774 \ucc98\uc74c\ubd80\ud130 \ud558\ub098\ub85c \uc815\ud574\uc838 \uc788\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubcf4\uc874\ub41c \ubb3c\uac74\uacfc \uadf8\uac83\uc744 \ubcf4\uc5ec \uc8fc\ub294 \ubc30\uc5f4\uc740 \uc11c\ub85c \uc5f0\uacb0\ub418\uc9c0\ub9cc \ub2e4\ub978 \uce35\uc758 \uacb0\uc815\uc774\ub2e4. 1921\ub144 \uc790\ud654\uc0c1 \uc0ac\uc9c4\uc740 \uccb4\uc2a4\ud310 \uc804\uccb4\ub97c \uba85\ud655\ud788 \ubcf4\uc5ec \uc8fc\uc9c0 \uc54a\ub294\ub2e4. \ud544\uc790\ub294 \ud655\ub300 \uc0ac\uc9c4\uc5d0\uc11c \ubcf4\uc774\ub294 \uce78\uc758 \uac00\uc7a5\uc790\ub9ac\ub97c \ub530\ub77c \uc120\uc744 \uae0b\uace0 \ud310\uc758 \ubc29\ud5a5\uc744 \uac00\ub2a0\ud588\ub2e4. \uc0ac\uc9c4\uc744 \ud06c\uac8c \ubcf4\uba74 \uc800\uc808\ub85c \ubaa8\ub4e0 \ub2f5\uc774 \ub098\uc624\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \uc774\ubbf8 \ubcf4\uc774\ub294 \uc815\ubcf4\uc758 \uad00\uacc4\ub97c \uc774\uc6a9\ud574 \uac00\ub824\uc9c4 \ubd80\ubd84\uc744 \uc881\ud600 \uac04 \uac83\uc774\ub2e4. \uccb4\uc2a4 \uaddc\uce59\ub3c4 \ubcf4\uc870 \ub2e8\uc11c\uac00 \ub418\uc5c8\ub2e4. \uc5b4\ub5a4 \ub9d0\uc774 \uc6c0\uc9c1\uc600\ub2e4\uba74 \ub2e4\ub978 \ub9d0\uc758 \uac00\ub2a5\ud55c \uc790\ub9ac\uac00 \uc904\uc5b4\ub4e4 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \ub2e4\ub9cc \uaddc\uce59\uc5d0 \ub9de\ub294 \ubc30\uce58\ub97c \ucc3e\ub294 \uac83\uacfc \uc2e4\uc81c \uadf8\ub0a0\uc758 \uac8c\uc784\uc744 \ud655\uc815\ud558\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \uc774 \ucc28\uc774\ub97c \ub193\uce58\uba74 \ud765\ubbf8\ub85c\uc6b4 \uc5f0\uad6c \uc81c\uc548\uc774 \ub9c8\uce58 \uc644\uc804\ud788 \uc785\uc99d\ub41c \uc5ed\uc0ac \uc7a5\uba74\ucc98\ub7fc \ubc14\ub00c\uc5b4 \ubc84\ub9b0\ub2e4. \uae30\uad00 \uae00\uc758 \ud544\uc790\ub294 \ud770 \ub9d0\uc744 \ub450\ub294 \ub9e8 \ub808\uc774\uac00 \ub2e4\uc12f \ubc88\uc9f8 \uc218\ub97c \ub454 \ub4a4 \ud30c\uc774\ud504\uc5d0 \ubd88\uc744 \ubd99\uc774\ub294 \uc21c\uac04\uc73c\ub85c \ubcf4\uba74 \ubc30\uce58\uac00 \uc798 \ub9de\ub294\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uadf8 \ub9d0\uc740 \uc0ac\uc9c4\uc774 \uc9c1\uc811 \ubaa8\ub4e0 \uc218\uc21c\uc744 \uae30\ub85d\ud558\uace0 \uc788\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \ubcf4\uc774\ub294 \uc790\ub8cc\uc640 \uac8c\uc784\uc758 \uac00\ub2a5\uc131\uc744 \uc774\uc5b4 \ub9cc\ub4e0 \ud574\uc11d\uc774\ub2e4. \uae00\uc740 \ub9c8\uc9c0\ub9c9\uc5d0\ub3c4 \ub9de\uac8c \ubcf5\uc6d0\ud588\ub294\uc9c0\ub97c \uc9c8\ubb38\uc73c\ub85c \ub0a8\uae34\ub2e4. \ubbf8\uc220\uad00\uc774 \uadf8 \uc81c\uc548\uc744 \uc804\uc2dc \ubc30\uce58\uc5d0 \ubc18\uc601\ud588\ub2e4\ub294 \uc0ac\uc2e4\ub3c4 \uac00\uc124\uc758 \uc131\uaca9\uc744 \uc5c6\uc560\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc804\uc2dc\uc5d0\ub294 \uc9c0\uae08 \uac00\uc9c4 \uc790\ub8cc\ub85c \uac00\uc7a5 \uc801\uc808\ud558\ub2e4\uace0 \ud310\ub2e8\ud55c \uc120\ud0dd\uc774 \ub4e4\uc5b4\uac08 \uc218 \uc788\ub2e4. \ud655\uc2e0\uc758 \uc815\ub3c4\ub97c \uc194\uc9c1\ud558\uac8c \ud45c\uc2dc\ud558\uba74\uc11c\ub3c4 \uad00\ub78c\uc790\uc5d0\uac8c \uc0dd\uac01\ud560 \uc7a5\uba74\uc744 \uc81c\uc2dc\ud558\ub294 \uac83\uc774\ub2e4. \ubc15\ubb3c\uad00\uc740 \ubb3c\uac74\uc744 \ubcf4\uad00\ud558\ub294 \uacf3\uc774\uba74\uc11c \uc774\ub7f0 \ud310\ub2e8\uc744 \uc124\uba85\ud558\ub294 \uacf3\uc774\uae30\ub3c4 \ud558\ub2e4. \uccb4\uc2a4\ud310\uc740 \uc0ac\uc6a9\uc790\uac00 \uc190\uc744 \ub308 \ub54c \ubc30\uce58\uac00 \ubc14\ub00c\ub294 \ubb3c\uac74\uc774\ub2e4. \uc644\uc131\ud55c \ub4a4 \uc6c0\uc9c1\uc774\uc9c0 \uc54a\ub294 \uc870\uac01\ub9cc \uae30\ub300\ud558\uba74 \uc774 \ud2b9\uc131\uc744 \ub193\uce58\uac8c \ub41c\ub2e4. \ub9e8 \ub808\uc774\uac00 \uccb4\uc2a4\ub97c \uc990\uacbc\uace0 \uc0c8\ub85c\uc6b4 \ub9d0\uc758 \ud615\ud0dc\ub97c \uace0\uc548\ud588\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ud568\uaed8 \ubcf4\uba74, \ub514\uc790\uc778\uacfc \ub180\uc774\uac00 \uc11c\ub85c \ub2e4\ub978 \uc138\uacc4\ub85c\ub9cc \ub5a8\uc5b4\uc838 \uc788\uc9c0 \uc54a\uc558\uc74c\uc744 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ud604\uc7ac \uc804\uc2dc\uc758 \ud2b9\uc815 \uce78\uc744 \uc815\ub2f5\ucc98\ub7fc \uc678\uc6b0\uae30\ubcf4\ub2e4 \ubc30\uc5f4\uc744 \uc815\ud560 \ub54c \uc5b4\ub5a4 \uc790\ub8cc\ub97c \ubcf4\uc558\ub294\uc9c0 \ubb3c\uc5b4\ubcf4\uc790. \uc0ac\uc9c4\uacfc \uc791\ud488, \uaddc\uce59\uacfc \ud050\ub808\uc774\ud130\uc758 \ud310\ub2e8\uc774 \ud568\uaed8 \uc791\uc6a9\ud55c\ub2e4. \uc791\uc740 \ub9d0\uc744 \uc5b4\ub514\uc5d0 \ub193\uc744\uc9c0\ub77c\ub294 \ubb38\uc81c\uc5d0\uc11c \uc608\uc220\ud488\uc774 \uc6d0\ub798 \uc5b4\ub5bb\uac8c \uc4f0\uc600\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\ub824\ub294 \ub178\ub825\uae4c\uc9c0 \uc77d\ud78c\ub2e4. \uc804\uc2dc\uc7a5\uc758 \uc815\uc9c0\ud55c \ubaa8\uc2b5 \ub4a4\uc5d0\ub3c4 \uc6c0\uc9c1\uc600\ub358 \uc190\uc758 \uc2dc\uac04\uc774 \ub0a8\uc544 \uc788\ub2e4. \uadf8\uac00 \uc81c\uc548\ud55c \ubc30\uce58\ub294 \uc2e4\uc81c \uc804\uc2dc\ub97c \ub2e4\uc2dc \ub193\ub294 \ub370 \uc0ac\uc6a9\ub418\uc5c8\ub2e4\uace0 \uae00\uc740 \uc804\ud55c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc0ac\uc9c4 \ubc16\uc758 \ub9d0\uae4c\uc9c0 \uc644\ubcbd\ud558\uac8c \ud655\uc778\ud588\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ud544\uc790 \uc5ed\uc2dc \uc790\uc2e0\uc758 \uac00\uc124\uc774 \ub9de\ub294\uc9c0 \uc9c8\ubb38\uc744 \ub0a8\uacbc\ub2e4. \uc774 \uc774\uc57c\uae30\uc758 \uc7ac\ubbf8\ub294 \uc791\ud488\uc758 \uc81c\ubaa9\uc774\ub098 \uac00\uaca9\uc5d0 \uc788\uc9c0 \uc54a\ub2e4. \uccb4\uc2a4 \ub9d0 \uba87 \uac1c\ub97c \uc5b4\ub514\uc5d0 \ub458\uc9c0 \uc815\ud558\ub824\uace0 \uc0ac\uc9c4\uacfc \uac8c\uc784 \uaddc\uce59\uc744 \ud568\uaed8 \uc0b4\ud3c8\ub2e4\ub294 \ub370 \uc788\ub2e4. \uc804\uc2dc\uc7a5 \uc18d \uac00\uc9c0\ub7f0\ud55c \ubc30\uce58\uc5d0\ub3c4 \ub204\uad70\uac00\uc758 \uae34 \uad00\ucc30\uacfc \uc870\uc2ec\uc2a4\ub7ec\uc6b4 \ucd94\ub9ac\uac00 \ub4e4\uc5b4 \uc788\uc744 \uc218 \uc788\ub2e4."}, {"id": "marcus-aurelius-meditations", "title": "\ub9c8\ub974\ucfe0\uc2a4 \uc544\uc6b0\ub810\ub9ac\uc6b0\uc2a4 \uba85\uc0c1\ub85d \u2014 \ud669\uc81c\ub3c4 \uc790\uc2e0\uc5d0\uac8c \ub9d0\uc744 \uac78\uc5c8\ub2e4", "summary": "\uc9e7\uc740 \uae30\ub85d\ub4e4\uc744 \ud1b5\ud574 \ud669\uc81c\uc758 \uc0dd\uc560\uc640 \uc2a4\ud1a0\uc544 \ucca0\ud559\uc758 \uc77c\uc0c1\uc801\uc778 \uc9c8\ubb38\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Philosophy", "url": "stories/marcus-aurelius-meditations/index.html", "image": "media/marcus-aurelius-meditations.jpg", "alt": "\uba85\uc0c1\ub85d\uc758 \uc61b \uc601\ubb38\ud310\uc5d0 \uc218\ub85d\ub41c \ub9c8\ub974\ucfe0\uc2a4 \uc544\uc6b0\ub810\ub9ac\uc6b0\uc2a4\uc758 \ucd08\uc0c1 \uc7ac\ud604 \ub3c4\ud310.", "text": "\ub9c8\ub974\ucfe0\uc2a4 \uc544\uc6b0\ub810\ub9ac\uc6b0\uc2a4 \uba85\uc0c1\ub85d \u2014 \ud669\uc81c\ub3c4 \uc790\uc2e0\uc5d0\uac8c \ub9d0\uc744 \uac78\uc5c8\ub2e4 \ub2e4\ub978 \uc0ac\ub78c\uc744 \ubc14\uafb8\uae30 \uc804\uc5d0 \uc0b4\ud53c\ub294 \ud310\ub2e8\uacfc \ud558\ub8e8\uc758 \ud589\ub3d9 \uc9e7\uc740 \uae30\ub85d\ub4e4\uc744 \ud1b5\ud574 \ud669\uc81c\uc758 \uc0dd\uc560\uc640 \uc2a4\ud1a0\uc544 \ucca0\ud559\uc758 \uc77c\uc0c1\uc801\uc778 \uc9c8\ubb38\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Philosophy \ubb38\ud654 \uc544\uce68\uc5d0 \uc77c\uc5b4\ub098 \ud574\uc57c \ud560 \uc77c\uc744 \uc2dc\uc791\ud558\uae30 \uc2eb\uc740 \ub0a0\uc774 \uc788\ub2e4. \uc624\ub798\ub41c \ucc45\uc5d0\uc11c \uc774\uc640 \ube44\uc2b7\ud55c \ub9dd\uc124\uc784\uc744 \ub9cc\ub098\uba74 \uc800\uc790\uac00 \ub85c\ub9c8 \ud669\uc81c\uc600\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc870\uae08 \uc758\uc678\ub85c \ub290\uaef4\uc9c4\ub2e4. \ubaa8\ub4e0 \uba85\ub839\uc744 \ub0b4\ub9b4 \uc218 \uc788\uc744 \ub4ef\ud55c \uc0ac\ub78c\ub3c4 \uc790\uc2e0\uc758 \ud558\ub8e8\ub97c \uc2a4\uc2a4\ub85c \uc124\ub4dd\ud574\uc57c \ud588\ub358 \uac83\uc774\ub2e4. \ub9c8\ub974\ucfe0\uc2a4 \uc544\uc6b0\ub810\ub9ac\uc6b0\uc2a4\uc758 \u300e\uba85\uc0c1\ub85d\u300f\uc740 \uc9e7\uc740 \uae30\ub85d\ub4e4\uc744 \ud1b5\ud574 \uc790\uc2e0\uc744 \ub2e4\ub8e8\ub294 \ubc95\uc744 \ub418\ubb3b\ub294 \ucc45\uc774\ub2e4. \uc644\uc131\ub41c \uc815\ub2f5\uc744 \uc544\ub7ab\uc0ac\ub78c\uc5d0\uac8c \uc120\ud3ec\ud558\ub294 \uc5f0\uc124\ucc98\ub7fc\ub9cc \uc77d\uae30\ubcf4\ub2e4, \uc65c \uc5b4\ub5a4 \ub9d0\uc744 \uc790\uae30\uc5d0\uac8c \uac70\ub4ed \ud574\uc57c \ud588\ub294\uc9c0 \uc0dd\uac01\ud558\uba70 \ub4e4\uc5b4\uac00 \ubcf4\uba74 \uac00\uae5d\ub2e4. \uadf8\ub294 121\ub144\uc5d0 \ud0dc\uc5b4\ub098 180\ub144\uc5d0 \uc138\uc0c1\uc744 \ub5a0\ub0ac\ub2e4. \uc548\ud1a0\ub2c8\ub204\uc2a4 \ud53c\uc6b0\uc2a4\uc758 \ub4a4\ub97c \uc774\uc5b4 161\ub144\uc5d0 \ud669\uc81c\uac00 \ub418\uc5c8\uace0, \ud1b5\uce58\uc758 \uc2dc\uac04\uc5d0\ub294 \uc804\uc7c1\uacfc \uc5ec\ub7ec \uc5b4\ub824\uc6c0\uc774 \uc788\uc5c8\ub2e4. \ucc45\uc5d0\uc11c \ub9d0\ud558\ub294 \ud3c9\uc815\uc740 \ubaa8\ub4e0 \uc678\ubd80 \ubb38\uc81c\uac00 \ud574\uacb0\ub41c \uc870\uc6a9\ud55c \ubc29\uc5d0\uc11c\ub9cc \uc0dd\uac01\ud55c \uc8fc\uc81c\uac00 \uc544\ub2c8\uc5c8\ub2e4. \uadf8\ub807\ub2e4\uace0 \ud798\ub4e0 \uc77c\uc744 \uacaa\uc5c8\uc73c\ub2c8 \ubaa8\ub4e0 \ud310\ub2e8\uc774 \uc633\uc558\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ud669\uc81c\ub77c\ub294 \uc9c0\uc704\uc5d0\ub294 \ud070 \uad8c\ud55c\uacfc \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uc601\ud5a5\uc744 \ubbf8\uce58\ub294 \ucc45\uc784\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4. \ucca0\ud559\uc744 \uc4f0\ub294 \uc0ac\ub78c\uacfc \uc2e4\uc81c\ub85c \ud1b5\uce58\ud558\ub294 \uc0ac\ub78c\uc744 \ubaa8\ub450 \ubcf4\uc544\uc57c, \ud55c \uc0ac\ub78c\uc744 \uadf8\uc800 \ud6cc\ub96d\ud55c \uaca9\uc5b8\uc758 \uc774\ub984\uc73c\ub85c\ub9cc \ub9cc\ub4e4\uc9c0 \uc54a\uac8c \ub41c\ub2e4. \uc81c1\uad8c\uc5d0\uc11c\ub294 \uac00\uc871\uacfc \uc2a4\uc2b9, \uc8fc\ubcc0 \uc0ac\ub78c\ub4e4\uc5d0\uac8c\uc11c \ubb34\uc5c7\uc744 \ubc30\uc6e0\ub294\uc9c0 \ub3cc\uc544\ubcf8\ub2e4. \uc2a4\uc2a4\ub85c\ub97c \uc544\ubb34\uc5d0\uac8c\ub3c4 \ube5a\uc9c0\uc9c0 \uc54a\uc740 \uc9c0\ud61c\ub85c\uc6b4 \uc0ac\ub78c\uc73c\ub85c \uc18c\uac1c\ud558\ub294 \ubc29\uc2dd\uacfc \ub2e4\ub974\ub2e4. \uc5b4\ub5a4 \ud0dc\ub3c4\ub97c \ubcf4\uace0 \uc775\ud614\uc73c\uba70 \uc5b4\ub5a4 \ub3c4\uc6c0\uc744 \ubc1b\uc558\ub294\uc9c0\ub97c \uba3c\uc800 \ub193\ub294\ub2e4. \uc774 \ubd80\ubd84\uc744 \uc77d\uc744 \ub54c\ub294 \uc774\ub984\uc744 \uc804\ubd80 \uc678\uc6b0\uae30\ubcf4\ub2e4 \ubc30\uc6c0\uc758 \ub0b4\uc6a9\uc774 \uc5b4\ub5bb\uac8c \uad6c\uccb4\uc801\uc778 \ud589\ub3d9\uacfc \uc5f0\uacb0\ub418\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \ucc38\ub294 \ud0dc\ub3c4\uc640 \ub9d0\uc744 \ub2e4\ub8e8\ub294 \ubc95, \uc77c\ud558\ub294 \uc790\uc138\ub294 \ucd94\uc0c1\uc801\uc778 \ub355\ubaa9\uc774\uba74\uc11c \ub3d9\uc2dc\uc5d0 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc0dd\ud65c\uc5d0\uc11c \ubcfc \uc218 \uc788\ub294 \uac83\uc774\uc5c8\ub2e4. \ucca0\ud559\uc758 \uc2dc\uc791\uc5d0 \uad00\uacc4\uc758 \uae30\uc5b5\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \ub2e4\ub978 \uc0ac\ub78c\uc758 \ubb34\ub840\uc640 \uace0\uc9d1\uc744 \uc0dd\uac01\ud558\ub294 \ub300\ubaa9\ub4e4\ub3c4 \ub098\uc628\ub2e4. \uc138\uc0c1\uc5d0 \ubd88\ud3b8\ud55c \uc0ac\ub78c\uc774 \uc5c6\uc5b4\uc57c\ub9cc \ud3c9\uc628\ud560 \uc218 \uc788\ub2e4\uace0 \uae30\ub300\ud558\uba74 \ud558\ub8e8\uc758 \uc870\uac74\uc744 \ub108\ubb34 \uc881\uac8c \ub9cc\ub4e4 \uc218 \uc788\ub2e4. \uc800\uc790\ub294 \uc678\ubd80\uc5d0 \ub300\ud55c \ubd88\ud3c9\uc5d0 \uc55e\uc11c \uc790\uc2e0\uc774 \uc5b4\ub5a4 \ud310\ub2e8\uacfc \ud589\ub3d9\uc744 \ud560\uc9c0 \ub3cc\uc544\ubcf4\ub824 \ud55c\ub2e4. \uadf8\ub807\ub2e4\uace0 \ub0a8\uc774 \ud574\ub97c \ub07c\uccd0\ub3c4 \uc544\ubb34 \uc77c \uc5c6\ub2e4\uace0 \ubc1b\uc544\ub4e4\uc774\ub77c\ub294 \ub9d0\ub85c \ub2e8\uc21c\ud654\ud558\uba74 \uc548 \ub41c\ub2e4. \ubb34\uc5c7\uc744 \uc798\ubabb\uc774\ub77c\uace0 \ubcf4\uace0 \uc5b4\ub5a4 \ud589\ub3d9\uc744 \ucde8\ud560\uc9c0, \uadf8 \uacfc\uc815\uc5d0\uc11c \uc790\uc2e0\uae4c\uc9c0 \ubb34\ubd84\ubcc4\ud574\uc9c0\uc9c0 \uc54a\uc744\uc9c0 \uc0b4\ud53c\ub294 \ubb38\uc81c\ub2e4. \ucc38\ub294\ub2e4\ub294 \ub2e8\uc5b4 \ud558\ub098\ubcf4\ub2e4 \ud310\ub2e8\uc744 \uc783\uc9c0 \uc54a\ub294\ub2e4\ub294 \ubc29\ud5a5\uc73c\ub85c \uc77d\uc5b4 \ubcfc \uc218 \uc788\ub2e4. \u300e\uba85\uc0c1\ub85d\u300f\uc740 \ubc14\uae65\uc5d0\uc11c \uc77c\uc5b4\ub09c \uc77c\uacfc \uadf8 \uc77c\uc5d0 \ub300\ud55c \uc790\uc2e0\uc758 \ud310\ub2e8\uc744 \uac70\ub4ed \uad6c\ubd84\ud558\uac8c \ud55c\ub2e4. \uc5b4\ub5a4 \uc77c\uc774 \ubd88\ucf8c\ud588\ub2e4\ub294 \ub290\ub08c\uc740 \uc0ac\uc2e4\uc774\uc9c0\ub9cc \uadf8 \ub290\ub08c\uc774 \uc0ac\uac74\uc758 \ubaa8\ub4e0 \ub73b\uc744 \ub2e4 \uc124\uba85\ud558\ub294 \uac83\uc740 \uc544\ub2d0 \uc218 \uc788\ub2e4. \uba48\ucd94\uc5b4 \uc0b4\ud544 \ud2c8\uc744 \ub9cc\ub4dc\ub294 \uac83\uc774\ub2e4. \uc624\ub298\uc758 \uc608\ub85c \uc57d\uc18d\ud55c \ub2f5\uc7a5\uc744 \ub2a6\uac8c \ubc1b\uc740 \uc0c1\ud669\uc744 \uc0dd\uac01\ud574 \ubcfc \uc218 \uc788\ub2e4. \uc0c1\ub300\uac00 \ub098\ub97c \ubb34\uc2dc\ud55c\ub2e4\uace0 \ubc14\ub85c \uacb0\uc815\ud558\uae30 \uc804\uc5d0 \uc544\uc9c1 \ubaa8\ub974\ub294 \uc870\uac74\uc774 \uc788\ub294\uc9c0 \ubb3b\ub294 \uac83\uc774\ub2e4. \uc774\ub294 \uc6d0\ubb38\uc758 \uc2e4\uc81c \uc0ac\ub840\ub97c \uc778\uc6a9\ud55c \uac83\uc774 \uc544\ub2c8\ub77c \uc0dd\uac01\uc758 \ubc29\ud5a5\uc744 \uc774\ud574\ud558\uae30 \uc704\ud55c \uc608\ub2e4. \ud655\uc778\ud560 \uc77c\uacfc \uc0c1\uc0c1\uc73c\ub85c \ubd99\uc778 \uc124\uba85\uc744 \ub098\ub204\ub294 \ub370 \ucca0\ud559\uc774 \uc4f0\uc77c \uc218 \uc788\ub2e4. \uc81c5\uad8c\uc758 \uc2dc\uc791\uc5d0\uc11c\ub294 \uc544\uce68\uc5d0 \uc77c\uc5b4\ub098\uae30 \uc2eb\uc744 \ub54c \uc790\uae30\uc5d0\uac8c \uc5b4\ub5a4 \ub9d0\uc744 \ud560\uc9c0 \ubb3b\ub294\ub2e4. \uc778\uac04\uc774 \ud574\uc57c \ud560 \uc77c\uc744 \uc704\ud574 \uc77c\uc5b4\ub098\ub294 \ubb38\uc81c\ub97c \ub2e4\ub978 \uc0dd\uba85\ub4e4\uc774 \ud65c\ub3d9\ud558\ub294 \ubaa8\uc2b5\uacfc \uc5f0\uacb0\ud55c\ub2e4. \ud669\uc81c\uc758 \uac70\ub300\ud55c \uacf5\uc801\ubcf4\ub2e4 \ub9e4\uc77c\uc758 \uc791\uc740 \uc800\ud56d\uc744 \ub2e4\ub8e8\ub294 \uad6c\uc808\uc774 \uba3c\uc800 \ub208\uc5d0 \ub4e4\uc5b4\uc62c \uc218\ub3c4 \uc788\ub2e4. \uc774\uac83\uc744 \uc26c\uc9c0 \ub9d0\uace0 \uc77c\ud558\ub77c\ub294 \ud604\ub300\uc758 \uc0dd\uc0b0\uc131 \uba85\ub839\uc73c\ub85c \ubc14\ub85c \ubc14\uafb8\uc9c0\ub294 \ub9d0\uc790. \ucc45\uc740 \uc790\uae30 \uc0b6\uc758 \uc5ed\ud560\uacfc \ud589\ub3d9\uc744 \uc0dd\uac01\ud558\ub294 \ub9e5\ub77d\uc5d0 \ub193\uc5ec \uc788\ub2e4. \uc9c0\uae08\uc758 \ub3c5\uc790\ub294 \uc790\uc2e0\uc758 \uc870\uac74\uacfc \uac74\uac15, \ub9e1\uc740 \ucc45\uc784\uc744 \uc0b4\ud53c\uba70 \uc77d\uc744 \uc218 \uc788\ub2e4. \uace0\ub300\uc758 \ubb38\uc7a5\uc774 \uc624\ub298 \ubaa8\ub4e0 \uc0ac\ub78c\uc758 \ub3d9\uc77c\ud55c \uc77c\uc815\ud45c\uac00 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc2a4\ud1a0\uc544 \ucca0\ud559\uc744 \uc774\uc57c\uae30\ud560 \ub54c \ud63c\uc790 \ud3c9\uc628\ud574\uc9c0\ub294 \uae30\uc220\ub9cc \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \uc774 \ucc45\uc5d0\ub294 \uc0ac\ub78c\ub4e4\uacfc \ud568\uaed8 \uc0b4\uc544\uac00\ub294 \uc77c\uacfc \uc815\uc758, \uacf5\ub3d9\uc758 \uc774\uc775\uc5d0 \uad00\ud55c \uc0dd\uac01\ub3c4 \ubc18\ubcf5\ud574\uc11c \ub098\uc628\ub2e4. \ub0b4 \uae30\ubd84\uc744 \uc9c0\ud0a4\ub294 \uac83\uacfc \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uc5b4\ub5a4 \ud589\ub3d9\uc744 \ud558\ub294\uac00\ub294 \ub5a8\uc5b4\uc838 \uc788\uc9c0 \uc54a\ub2e4. \ud2b9\ud788 \uad8c\ud55c\uc744 \uac00\uc9c4 \uc0ac\ub78c\uc758 \ud3c9\uc815\uc740 \uc790\uc2e0\ub9cc \ud3b8\uc548\ud558\uae30 \uc704\ud55c \uc0c1\ud0dc\ub85c \ub05d\ub0a0 \uc218 \uc5c6\ub2e4. \ud310\ub2e8\uc774 \ub35c \ud754\ub4e4\ub9b0\ub2e4\uba74 \uadf8 \ud798\uc744 \uc5b4\ub5a4 \uacb0\uc815\uc5d0 \uc0ac\uc6a9\ud560 \uac83\uc778\uac00\ub77c\ub294 \ubb38\uc81c\uac00 \ub0a8\ub294\ub2e4. \ud669\uc81c\uc758 \ucc45\uc744 \uc77d\ub294 \uc7ac\ubbf8\ub3c4 \uc5ec\uae30 \uc788\ub2e4. \ub9c8\uc74c\uc18d\uc758 \uc9c8\ubb38\uc774 \uc2e4\uc81c \uc138\uacc4\uc5d0 \ubbf8\uce58\ub294 \ucc45\uc784\uacfc \ub9cc\ub09c\ub2e4. \u300e\uba85\uc0c1\ub85d\u300f\uc5d0\uc11c\ub294 \ube44\uc2b7\ud55c \uc0dd\uac01\uc774 \uc5ec\ub7ec \ubc88 \ub098\ud0c0\ub09c\ub2e4. \ucc98\uc74c\ubd80\ud130 \ub05d\uae4c\uc9c0 \ud55c \uc8fc\uc7a5\uc73c\ub85c \uace7\uac8c \ub098\uc544\uac00\ub294 \uad50\uacfc\uc11c\ub97c \uae30\ub300\ud558\uba74 \ub418\ud480\uc774\ucc98\ub7fc \ub290\ub084 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc774\ubbf8 \uc548\ub2e4\uace0 \uc5ec\uae30\ub294 \uc6d0\uce59\uc744 \uc2e4\uc81c\ub85c \uc9c0\ud0a4\uae30 \uc704\ud574 \ub2e4\uc2dc \uc801\ub294 \ub9d0\ub85c \ubcf4\uba74 \ubc18\ubcf5\uc758 \uc131\uaca9\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \ub3c5\uc790\uac00 \ubaa8\ub4e0 \uad6c\uc808\uc5d0 \ub3d9\uc758\ud574\uc57c \ud558\ub294 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \uc9e7\uc740 \ub300\ubaa9 \ud558\ub098\ub97c \uc77d\uace0 \uadf8\uac83\uc774 \uc5b4\ub5a4 \uc0c1\ud669\uc5d0\uc11c\ub294 \ub3c4\uc6c0\uc774 \ub418\uace0 \uc5b4\ub5a4 \uacf3\uc5d0\uc11c\ub294 \uc124\uba85\uc774 \ub354 \ud544\uc694\ud55c\uc9c0 \uc0dd\uac01\ud574 \ubcf4\uc790. \uc720\uba85\ud55c \ubb38\uc7a5\uc744 \ub5bc\uc5b4 \uc790\uc2e0\uc758 \ud310\ub2e8\uc744 \uba74\uc81c\ud574 \uc8fc\ub294 \ub9d0\ub85c \uc4f0\uae30\ubcf4\ub2e4 \uac80\ud1a0\ud560 \ub9d0\ub85c \ub193\ub294 \ud3b8\uc774 \ucc45\uacfc \uc624\ub798 \ub9cc\ub098\ub294 \ubc29\ubc95\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 \uc61b \uc601\ubb38\ud310\uc5d0 \uc218\ub85d\ub41c \ub9c8\ub974\ucfe0\uc2a4 \uc544\uc6b0\ub810\ub9ac\uc6b0\uc2a4\uc758 \uc5ed\uc0ac\uc801 \ucd08\uc0c1 \uc7ac\ud604 \ub3c4\ud310\uc774\ub2e4. \ud669\uc81c\uc758 \ud558\ub8e8\ub97c \uc9c1\uc811 \ucd2c\uc601\ud55c \uc790\ub8cc\ub098 \uae00\uc744 \uc4f0\ub358 \uc21c\uac04\uc744 \ubcf5\uc6d0\ud55c \uadf8\ub9bc\uc740 \uc544\ub2c8\ub2e4. \ud2b9\uc815 \uc5bc\uad74\uc5d0\uc11c \uc644\ubcbd\ud55c \uce68\ucc29\ud568\uc744 \uc77d\uc5b4 \ub0b4\ub824\uace0 \ud558\uae30\ubcf4\ub2e4 \uae30\ub85d\uc758 \uc9c8\ubb38\uc73c\ub85c \ub3cc\uc544\uac00\uba74 \uc88b\ub2e4. \uc624\ub298 \ubb34\uc2a8 \uc77c\uc774 \uc788\uc5c8\ub294\uc9c0\uc640 \uadf8 \uc77c\uc5d0 \ub0b4\uac00 \uc5b4\ub5a4 \uc124\uba85\uc744 \ubd99\uc600\ub294\uc9c0\ub97c \ud55c \ubc88 \ub098\ub204\uc5b4 \uc801\uc5b4 \ubcf4\uc790. \uc138\uc0c1\uc744 \ub73b\ub300\ub85c \ub9cc\ub4e4 \uc218 \uc5c6\ub2e4\ub294 \uccb4\ub150\ub9cc \ub0a8\uae30\ub824\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc544\uc9c1 \uc0b4\ud544 \ud310\ub2e8\uacfc \uc120\ud0dd\ud560 \ud589\ub3d9\uc774 \ubb34\uc5c7\uc778\uc9c0 \uc54c\uc544\ubcf4\ub294 \uc77c\uc774\ub2e4. \ud669\uc81c\uac00 \uc790\uc2e0\uc5d0\uac8c \uac74\ub128 \uc624\ub798\ub41c \ub9d0\uc774 \uc624\ub298\uc758 \ud558\ub8e8\ub97c \ub3cc\uc544\ubcf4\ub294 \uc791\uc740 \ub3c4\uad6c\uac00 \ub420 \uc218 \uc788\ub2e4."}, {"id": "metal-flute-inlaid-flowers", "title": "\ub300\uae08\uc5d0\ub3c4 \ubc18\uc9dd\uc774\ub294 \uaf43\ubb34\ub2ac\uac00 \uc788\uc5c8\ub2e4", "summary": "\uae08\uc740\uc785\uc0ac \uc7a5\uc2dd\uc774 \uc788\ub294 \ub300\uae08\uc5d0\uc11c \uc545\uae30\uc758 \ub610 \ub2e4\ub978 \ud45c\uc815\uc744 \ucc3e\uc2b5\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Music", "url": "stories/metal-flute-inlaid-flowers/index.html", "image": "media/metal-flute-inlaid-flowers.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \ucca0\uc81c\uae08\uc740\uc785\uc0ac\ub300\uae08 \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\ub300\uae08\uc5d0\ub3c4 \ubc18\uc9dd\uc774\ub294 \uaf43\ubb34\ub2ac\uac00 \uc788\uc5c8\ub2e4 \uc18c\ub9ac\ub97c \ub0b4\ub294 \uae34 \uad00\uc5d0 \ub354\ud55c \uc7a5\uc2dd \uae08\uc740\uc785\uc0ac \uc7a5\uc2dd\uc774 \uc788\ub294 \ub300\uae08\uc5d0\uc11c \uc545\uae30\uc758 \ub610 \ub2e4\ub978 \ud45c\uc815\uc744 \ucc3e\uc2b5\ub2c8\ub2e4. Music \ubb38\ud654 \ub300\uae08\uc774\ub77c\ub294 \uc774\ub984\uc744 \ub4e4\uc73c\uba74 \uae38\ucb49\ud55c \ub300\ub098\ubb34 \uc545\uae30\uac00 \ub5a0\uc624\ub978\ub2e4. \uadf8\ub7f0\ub370 \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \ucca0\uc81c\uae08\uc740\uc785\uc0ac\ub300\uae08\uc740 \uc774\ub984\ubd80\ud130 \uc870\uae08 \ub2e4\ub974\ub2e4. \uae08\uc18d\uc73c\ub85c \ub9cc\ub4e0 \uc545\uae30\uc5d0 \uaf43\uacfc \ud559 \ubb34\ub2ac\uae4c\uc9c0 \ub354\ud588\ub2e4. \uc804\uccb4 \uc0ac\uc9c4\uc5d0\uc11c\ub294 \uac00\ub290\ub2e4\ub780 \uc120\ucc98\ub7fc \ubcf4\uc5ec\uc11c \uc7a5\uc2dd\uc774 \uc27d\uac8c \ub208\uc5d0 \ub4e4\uc5b4\uc624\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \uc545\uae30\ub77c\ub294 \uc0ac\uc2e4\uc744 \ud655\uc778\ud55c \ub4a4, \uc774\ubc88\uc5d0\ub294 \uc5b4\ub514\uc5d0 \uc5b4\ub5a4 \ubb34\ub2ac\ub97c \ub193\uc558\ub294\uc9c0 \uc124\uba85\uc744 \uae38\uc7a1\uc774 \uc0bc\uc544 \ucc9c\ucc9c\ud788 \uc0b4\ud3b4\ubcf4\uc790. \ubc15\ubb3c\uad00\uc740 \uc774 \uc545\uae30\ub97c \uac00\ub85c\ub85c \uc5f0\uc8fc\ud558\ub294 \uad00\uc545\uae30\ub85c \uc18c\uac1c\ud558\uace0, \ubab8\uccb4\uc5d0 \uad6c\uba4d\uc774 \uc5f4\ub450 \uac1c \ub6ab\ub824 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uae38\uac8c \ubed7\uc740 \uad00\uacfc \uad6c\uba4d\uc740 \uc18c\ub9ac\ub97c \ub0b4\ub294 \uc545\uae30\uc758 \ud2b9\uc9d5\uc744 \ubcf4\uc5ec \uc8fc\ub294 \ubd80\ubd84\uc774\ub2e4. \uac70\uae30\uc5d0 \uae08\uc740\uc785\uc0ac \uae30\ubc95\uc73c\ub85c \uaf43\ubb34\ub2ac\uc640 \uaf43\ub369\uad74\ubb34\ub2ac\ub97c \ub354\ud588\ub2e4\uace0 \ud55c\ub2e4. \uc5f0\uc8fc \ub3c4\uad6c\uc758 \ud45c\uba74\uc5d0 \uc7a5\uc2dd\uc758 \uc790\ub9ac\uac00 \ud568\uaed8 \ub9c8\ub828\ub41c \uac83\uc774\ub2e4. \uad6c\uba4d\uc744 \ubaa8\ub450 \uac19\uc740 \uc6a9\ub3c4\uc758 \uc190\uac00\ub77d \uad6c\uba4d\uc774\ub77c\uace0 \ub2e8\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5ec\uae30\uc11c\ub294 \ubc15\ubb3c\uad00\uc774 \uc54c\ub824 \uc8fc\ub294 \uc804\uccb4 \uac1c\uc218\ub85c \uc77d\uc73c\uba74 \ub41c\ub2e4. \uc591\ub05d\uc5d0\ub294 \uac19\uc740 \uae30\ubc95\uc73c\ub85c \ud559 \ubb34\ub2ac\ub97c \ud45c\ud604\ud588\ub2e4. \ubab8\ud1b5\uc758 \uaf43\uacfc \ub05d\ubd80\ubd84\uc758 \uc0c8\ub97c \ub098\ub204\uc5b4 \ub193\uc740 \uad6c\uc131\uc774 \ubcf4\uc778\ub2e4. \uac00\uc6b4\ub370\uc640 \ub05d\uc744 \ub530\ub85c \uc0b4\ud53c\ub294 \uac83\ub9cc\uc73c\ub85c\ub3c4 \uae34 \ubb3c\uac74\uc744 \ubcf4\ub294 \uc21c\uc11c\uac00 \uc0dd\uae34\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \uc791\uc740 \ubb34\ub2ac\uac00 \uc120\uba85\ud558\uc9c0 \uc54a\uc744 \ub54c\ub294 \ud655\ub300\ud574 \ubcf4\ub418 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc120\uc744 \uc5b5\uc9c0\ub85c \uc77d\uc5b4\ub0bc \ud544\uc694\ub294 \uc5c6\ub2e4. \uc545\uae30\uc758 \uc7a5\uc2dd\uc5d0 \uad00\ud55c \uc815\ubcf4\ub294 \uc0ac\uc9c4\uacfc \ud568\uaed8 \uc81c\uacf5\ub418\ub294 \uc18c\uc7a5\ud488 \uc124\uba85\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\ub2e4. \ub300\uae08\uc758 \uc0ac\uc9c4\uc744 \ubcfc \ub54c \ud55c\uac00\uc6b4\ub370\ub9cc \ud655\ub300\ud558\uba74 \uae34 \uad00 \uc804\uccb4\uc758 \uad6c\uc131\uc744 \ub193\uce60 \uc218 \uc788\ub2e4. \uba3c\uc800 \ub05d\uc5d0\uc11c \ub05d\uae4c\uc9c0 \uc774\uc5b4\uc9c0\ub294 \ud615\ud0dc\ub97c \ubcf4\uace0 \ub2e4\uc74c\uc5d0 \uad6c\uba4d\uacfc \ud45c\uba74\uc758 \ubb34\ub2ac\ub97c \uc0b4\ud3b4\ubcf4\uc790. \uc18c\ub9ac\ub97c \ub9cc\ub4dc\ub294 \uad6c\uc870\uc640 \uc7a5\uc2dd\uc774 \uac19\uc740 \uae38\uc774 \uc548\uc5d0 \ub098\ub780\ud788 \ub193\uc778\ub2e4. \uc5b4\ub290 \ud55c\ucabd\uc744 \ubd80\uc218\uc801\uc778 \uac83\uc73c\ub85c \uc9c0\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \uc545\uae30\ub97c \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uad00\uc545\uae30\ub77c\ub294 \uc774\ub984\uc744 \ub4e4\uc5c8\ub2e4\uace0 \ub208\uc55e\uc758 \ubaa8\ub4e0 \uad6c\uba4d\uc744 \uac19\uc740 \uc6a9\ub3c4\ub85c \ubb36\uc5b4\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc790\ub8cc\ub294 \uc804\uccb4 \uad6c\uba4d\uc758 \uac1c\uc218\ub97c \uc54c\ub824 \uc8fc\uc9c0\ub9cc, \uac01\uac01\uc758 \uae30\ub2a5\uc744 \uc124\uba85 \uc5c6\uc774 \uc0c8\ub85c \ub098\ub204\uc5b4 \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc5f0\uc8fc \uad6c\uc870\uc758 \uc138\ubd80\ub294 \ub2e4\ub978 \uc545\uae30 \uc790\ub8cc\uc640 \ud568\uaed8 \ud655\uc778\ud560 \ubb38\uc81c\ub2e4. \uc720\ubb3c\uc758 \uc124\uba85\uc774 \uc81c\uacf5\ud558\ub294 \ubc94\uc704 \uc548\uc5d0\uc11c\ub3c4 \ubaa8\uc591\uacfc \uc7a5\uc2dd\uc758 \ubc30\uce58\ub97c \ubcfc \ub2e8\uc11c\ub294 \ucda9\ubd84\ud558\ub2e4. \uae08\uc740\uc785\uc0ac\ub77c\ub294 \ub9d0\uc740 \uae08\uacfc \uc740\uc744 \uc774\uc6a9\ud574 \ubb34\ub2ac\ub97c \ud45c\ud604\ud55c \uc81c\uc791\uc744 \uac00\ub9ac\ud0a8\ub2e4. \uc7a5\uc2dd\ub41c \uc120\uc774 \uc788\ub2e4\ub294 \uacb0\uacfc\ub9cc \ubcf4\uae30\ubcf4\ub2e4 \uc11c\ub85c \ub2e4\ub978 \uc7ac\ub8cc\ub97c \ud45c\uba74\uc5d0 \uc815\uad50\ud558\uac8c \ubc30\uce58\ud588\ub2e4\ub294 \uc218\uace0\ub97c \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \uaf43\uacfc \ub369\uad74\uc758 \ubc18\ubcf5\uc740 \uae34 \uad00\uc744 \ub530\ub77c \uc2dc\uc120\uc744 \uc6c0\uc9c1\uc774\uac8c \ud55c\ub2e4. \uc18c\ub9ac\ub97c \ub4e3\uae30 \uc804\ubd80\ud130 \ub208\uc73c\ub85c \ub530\ub77c\uac08 \ub9ac\ub4ec\uc774 \uc788\ub294 \uc148\uc774\ub2e4. \ub2e4\ub9cc \uc0ac\uc9c4\uc758 \ubc18\uc9dd\uc784\uc744 \uadfc\uac70\ub85c \uc7ac\ub8cc\uc758 \uc815\ud655\ud55c \ube44\uc728\uc774\ub098 \ubaa8\ub4e0 \uac00\uacf5 \ub2e8\uacc4\ub97c \ud310\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc5ec\uae30\uc11c\ub294 \ubc15\ubb3c\uad00\uc774 \ud655\uc778\ud55c \uae30\ubc95\uacfc \ubb34\ub2ac\ub97c \uae30\uc900\uc73c\ub85c \uc77d\ub294\ub2e4. \uc61b \uc7a5\uc778\uc758 \uae30\uc220\uc774 \uad81\uae08\ud574\uc9c0\ub354\ub77c\ub3c4 \ube44\uc2b7\ud55c \uacf5\uc608\ud488\uc5d0\uc11c \ubcf8 \uacf5\uc815\uc744 \uc774 \ud55c \uc810\uc5d0 \ubaa8\ub450 \ub300\uc785\ud558\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc124\uba85\ub41c \uc0ac\uc2e4\uacfc \uac10\uc0c1\uc758 \ubc94\uc704\ub97c \ub098\ub204\uba74 \ubb3c\uac74\uc774 \ub354 \ub610\ub837\ud574\uc9c4\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc870\uc120\uc2dc\ub300 \ub300\uae08\uc774 \uc81c\ub840\uc545\uacfc \uc5f0\ub840\uc545\uc758 \ud3b8\uc131\uc5d0 \uc4f0\uc600\ub2e4\ub294 \ubc30\uacbd\ub3c4 \uc18c\uac1c\ud55c\ub2e4. \uc74c\uc545\uc774 \uc5b4\ub5a4 \uc790\ub9ac\uc5d0\uc11c \uc5f0\uc8fc\ub418\uc5c8\ub294\uc9c0 \uc54c\uba74 \uc545\uae30\uc758 \uc7a5\uc2dd\uc774 \uc0ac\uce58\ub77c\ub294 \ud55c\ub9c8\ub514\ub85c\ub9cc \uc815\ub9ac\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc758\ub840\uc640 \uc5f0\ud68c\uc5d0\uc11c\ub294 \ub4e3\ub294 \uacbd\ud5d8\ubfd0 \uc544\ub2c8\ub77c \uacf5\uac04\uacfc \uc0ac\ub78c, \ubb3c\uac74\uc774 \ud568\uaed8 \ub9cc\ub4dc\ub294 \uaca9\uc2dd\ub3c4 \uc911\uc694\ud588\uc744 \uc218 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc774 \ud55c \uc810\uc774 \uc5b4\ub290 \uc758\uc2dd\uc5d0\uc11c \ub204\uad6c\uc758 \uc190\uc5d0 \ub4e4\ub838\ub294\uc9c0\uae4c\uc9c0 \ud655\uc778\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc545\uae30\uc758 \uc77c\ubc18\uc801\uc778 \uc5ed\uc0ac\uc640 \uac1c\ubcc4 \uc720\ubb3c\uc758 \uc0ac\uc6a9 \uc774\ub825\uc740 \ub2e4\ub974\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc74c\uc545\uc744 \uc774\ub8e8\ub294 \ub3c4\uad6c\uac00 \ub3d9\uc2dc\uc5d0 \uacf5\uc608\ud488\uc774\ub77c\ub294 \uc810\uc744 \uc0b4\ud3b4\ubcf8\ub2e4. \uacf5\uc5f0\uc758 \uc18c\ub9ac\uac00 \uc0ac\ub77c\uc9c4 \ub4a4\uc5d0\ub3c4 \uc7ac\ub8cc\uc640 \ubb34\ub2ac\ub294 \ub2f9\uc2dc \uc545\uae30\ub97c \ub300\ud558\ub358 \ud0dc\ub3c4\ub97c \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uc0ac\uc9c4\uc5d0\ub294 \uad00\uc758 \ud615\ud0dc\uc640 \ud45c\uba74\uc740 \ub0a8\uc9c0\ub9cc \uc2e4\uc81c \uc74c\uc0c9\uacfc \uc5f0\uc8fc \uc870\uac74\uc740 \ub4e4\ub9ac\uc9c0 \uc54a\ub294\ub2e4. \ubc18\ub300\ub85c \uc545\uae30 \uc18c\ub9ac\ub9cc \ub4e4\uc5b4\uc11c\ub294 \uae08\uc740\uc785\uc0ac\uc758 \uc120\uc744 \uc54c\uc544\ubcfc \uc218 \uc5c6\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc790\ub8cc\uac00 \uc545\uae30\uc758 \ub2e4\ub978 \uba74\uc744 \uc804\ud55c\ub2e4. \uc804\uc2dc \uc0ac\uc9c4\uc744 \ubcf4\uace0 \uc2e4\uc81c \uc5f0\uc8fc \uc790\ub8cc\ub97c \ucc3e\uc544\ubcf4\ub294 \uc77c\uc774 \uc774\uc5b4\uc9c8 \uc218 \uc788\uc9c0\ub9cc \ub458\uc744 \uac19\uc740 \uc815\ubcf4\ub85c \ucde8\uae09\ud558\uc9c0 \uc54a\uc544\uc57c \ud55c\ub2e4. \uc774 \ubb3c\uac74\uc5d0\uc11c \ucd9c\ubc1c\ud574 \ub300\uae08 \uc18c\ub9ac\ub97c \ub4e3\uac8c \ub41c\ub2e4\uba74 \ubc18\uc9dd\uc774\ub294 \ubb34\ub2ac\uac00 \uc5b4\ub5a4 \ud2b9\uc815\ud55c \uc74c\uc744 \ub9cc\ub4e4\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uad6c\uc870\uc640 \uc7a5\uc2dd\uc740 \uad00\uacc4\uac00 \uc788\ub354\ub77c\ub3c4 \uac19\uc740 \uc5ed\ud560\uc744 \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubcf4\uae30\uc640 \ub4e3\uae30\uac00 \uac01\uc790\uc758 \ubaab\uc744 \uac00\uc9c8 \ub54c \uc545\uae30\ub97c \ub9cc\ub098\ub294 \uacbd\ud5d8\uc774 \ub113\uc5b4\uc9c4\ub2e4. \uae38\uac8c \ubed7\uc740 \uad00 \uc704\uc758 \uaf43 \ud55c \uc904\uc774 \uc74c\uc545 \ubc16\uc73c\ub85c\ub3c4 \uc774\uc5b4\uc9c0\ub294 \uc774\uc57c\uae30\ub97c \uc5f4\uc5b4 \uc900\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc870\uc120\uc2dc\ub300 \ub300\uae08\uc774 \uc81c\ub840\uc545\uacfc \uc5f0\ub840\uc545\uc758 \uc5ec\ub7ec \ud3b8\uc131\uc5d0\uc11c \uc5f0\uc8fc\ub418\uc5c8\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \ub2e4\ub9cc \uc0ac\uc9c4\uc758 \uc774 \uc720\ubb3c\uc774 \uc5b4\ub5a4 \ub0a0 \uc5b4\ub5a4 \uace1\uc744 \uc5f0\uc8fc\ud588\ub294\uc9c0\uae4c\uc9c0 \uc54c\ub824 \uc8fc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ub298 \uc0ac\uc9c4\uc73c\ub85c \uc54c \uc218 \uc5c6\ub294 \uac83\uc740 \uc2e4\uc81c \uc74c\uc0c9\uc774\ub2e4. \ub300\uc2e0 \ub0a8\uc544 \uc788\ub294 \uac83\uc740 \uae34 \uad00\uacfc \uad6c\uba4d, \uae08\uc18d \ud45c\uba74\uacfc \uc7a5\uc2dd\uc774\ub2e4. \uc74c\uc545\uc744 \ub4e3\uc9c0 \ubabb\ud558\ub294 \uc790\ub9ac\uc5d0\uc11c\ub3c4 \uc545\uae30\ub97c \ubcf4\ub294 \uc7ac\ubbf8\ub294 \uc788\ub2e4. \uc18c\ub9ac\ub97c \ub9cc\ub4e4\ub358 \ubb3c\uac74\uc5d0 \uaf43\uacfc \ud559\uc744 \ub354\ud558\uace0 \uc2f6\uc5c8\ub358 \uc120\ud0dd\uc774 \uadf8 \ud55c \uac00\uc9c0\ub2e4."}, {"id": "metal-flute-woodwind-family", "title": "\uae08\uc18d\uc73c\ub85c \ub9cc\ub4e0 \ud50c\ub8e8\ud2b8\ub294 \uc65c \ubaa9\uad00\uc545\uae30\uc77c\uae4c", "summary": "\uc740\ube5b \ud50c\ub8e8\ud2b8\uc640 \ubaa9\uad00\uc545\uae30\ub77c\ub294 \ubd84\ub958 \uc0ac\uc774\uc758 \uac04\uaca9\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Music", "url": "stories/metal-flute-woodwind-family/index.html", "image": "media/metal-flute-woodwind-family.jpg", "alt": "\uae08\uc18d\uc73c\ub85c \ub9cc\ub4e0 \ud50c\ub8e8\ud2b8\ub294 \uc65c \ubaa9\uad00\uc545\uae30\uc77c\uae4c\uc758 \ub0b4\uc6a9\uc744 \ub3d5\ub294 \uc124\uba85\uc6a9 \uc774\ubbf8\uc9c0", "text": "\uae08\uc18d\uc73c\ub85c \ub9cc\ub4e0 \ud50c\ub8e8\ud2b8\ub294 \uc65c \ubaa9\uad00\uc545\uae30\uc77c\uae4c \uc774\ub984 \uc18d \uc7ac\ub8cc\uc640 \uc9c0\uae08\uc758 \ubaa8\uc2b5\uc744 \ub098\ub204\uc5b4 \ubcf4\uae30 \uc740\ube5b \ud50c\ub8e8\ud2b8\uc640 \ubaa9\uad00\uc545\uae30\ub77c\ub294 \ubd84\ub958 \uc0ac\uc774\uc758 \uac04\uaca9\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Music \ubb38\ud654 \ubb34\ub300\uc758 \ud50c\ub8e8\ud2b8\ub294 \ubc18\uc9dd\uc774\ub294 \uae08\uc18d \uc545\uae30\ucc98\ub7fc \ubcf4\uc778\ub2e4. \uadf8\ub7f0\ub370 \uc624\ucf00\uc2a4\ud2b8\ub77c\uc5d0\uc11c\ub294 \ubaa9\uad00\uc545\uae30\ub77c\uace0 \ubd80\ub978\ub2e4. \ub098\ubb34\ub97c \ub73b\ud558\ub294 \uc774\ub984\uacfc \ub208\uc55e\uc758 \uc7ac\ub8cc\uac00 \ub9de\uc9c0 \uc54a\ub294 \uac83\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \uc601\uad6d \ud544\ud558\ubaa8\ub2c8\uc544 \uc624\ucf00\uc2a4\ud2b8\ub77c\uc758 \uc548\ub0b4\ub294 \uc61b \ud50c\ub8e8\ud2b8\ub294 \ub098\ubb34\ub85c \ub9cc\ub4e4\uc5c8\uc9c0\ub9cc \ud604\ub300 \ud50c\ub8e8\ud2b8\uc758 \ub300\ubd80\ubd84\uc740 \uae08\uc18d\uc774\ub77c\uace0 \uc124\uba85\ud55c\ub2e4. \ubd84\ub958\uc758 \uc774\ub984\ub9cc \ubcf4\uace0 \uc9c0\uae08 \uc4f0\ub294 \uc545\uae30\uc758 \uc7ac\ub8cc\ub97c \uc815\ud558\uba74 \uc0dd\uae30\ub294 \uc791\uc740 \uc5b4\uae0b\ub0a8\uc774\ub2e4. \uc545\uae30\uc758 \uc774\ub984\uacfc \ubd84\ub958\uc5d0\ub294 \uc9c0\ub098\uc628 \uc2dc\uac04\uc774 \ub0a8\uc544 \uc788\ub2e4. \uc624\ub298\uc758 \ud50c\ub8e8\ud2b8\uac00 \uae08\uc18d\uc774\ub77c\uace0 \ud574\uc11c \ubaa9\uad00\uc545\uae30\ub77c\ub294 \uc774\ub984\uc744 \uc7ac\ub8cc \uac80\uc0ac\ud45c\ucc98\ub7fc \uc77d\uc744 \uc218\ub294 \uc5c6\ub294 \uac83\uc774\ub2e4. \ud544\ud558\ubaa8\ub2c8\uc544\ub294 \ud53c\ucf5c\ub85c\ub294 \uc9c0\uae08\ub3c4 \ub300\uccb4\ub85c \ub098\ubb34\ub85c \ub9cc\ub4e0\ub2e4\uace0 \ub367\ubd99\uc778\ub2e4. \uac00\uae4c\uc6b4 \uc545\uae30 \uac00\uc871 \uc548\uc5d0\uc11c\ub3c4 \uc7ac\ub8cc\uac00 \ubaa8\ub450 \uac19\uc9c0\ub294 \uc54a\ub2e4. \ubc18\uc9dd\uc774\ub294 \uac83\uacfc \uac80\uac8c \ubcf4\uc774\ub294 \uac83\uc744 \ud568\uaed8 \ubcfc \ub54c \uc774 \ucc28\uc774\ub97c \ub5a0\uc62c\ub824\ub3c4 \uc88b\uaca0\ub2e4. 19\uc138\uae30\uc5d0 \ud50c\ub8e8\ud2b8\uc758 \uc5f0\uc8fc \uae30\ubc95\uc774 \ud06c\uac8c \ubc1c\uc804\ud558\ub294 \ub370\uc5d0\ub294 \ud45c\uba74\uc758 \uae08\uc18d \ud0a4\uc640 \ud328\ub4dc \uccb4\uacc4\ub3c4 \uc911\uc694\ud588\ub2e4\uace0 \uc548\ub0b4\ub294 \uc124\uba85\ud55c\ub2e4. \uc190\uc774 \uc9c1\uc811 \ubaa8\ub4e0 \uad6c\uba4d\uc744 \ub9c9\ub294 \ubaa8\uc2b5\ub9cc \uc0c1\uc0c1\ud588\ub2e4\uba74 \uc791\uc740 \uc7a5\uce58\ub4e4\uc744 \ub2e4\uc2dc \ubcfc \uc774\uc720\uac00 \uc0dd\uae34\ub2e4. \uc774 \uc7a5\uce58\ub4e4\uc740 \ub354 \ubcf5\uc7a1\ud55c \uc74c\uc545\uc744 \uc5f0\uc8fc\ud560 \uc218 \uc788\ub3c4\ub85d \ub3c4\uc654\ub2e4. \uc545\uae30\ub97c \ub9cc\ub4dc\ub294 \uc77c\uc774 \uc7ac\ub8cc\ub97c \uace0\ub974\ub294 \ub370\uc5d0\uc11c \ub05d\ub098\uc9c0 \uc54a\uace0, \uc5f0\uc8fc\uc790\uc758 \uc190\uacfc \uc6d0\ud558\ub294 \uc18c\ub9ac \uc0ac\uc774\ub97c \uc5f0\uacb0\ud558\ub294 \uc77c\uc774\ub77c\ub294 \uc810\uc774 \ubcf4\uc778\ub2e4. \ubaa9\uad00\uc774\ub77c\ub294 \uc774\ub984\uc744 \uace7 \ub098\ubb34\ub85c \ub9cc\ub4e0 \ubaa8\ub4e0 \uc545\uae30\ub77c\ub294 \ub73b\uc73c\ub85c \uc77d\uc73c\uba74 \uae08\uc18d \ud50c\ub8e8\ud2b8\uac00 \uc608\uc678\ucc98\ub7fc \ubcf4\uc778\ub2e4. \uadf8\ub7ec\ub098 \ubd84\ub958\uc5d0\ub294 \uc545\uae30\uac00 \uc774\uc5b4 \uc628 \uc5ed\uc0ac\uc640 \uc5f0\uc8fc \ubc29\uc2dd\uc774 \ud568\uaed8 \ub4e4\uc5b4 \uc788\ub2e4. \ud604\uc7ac\uc758 \uc7ac\ub8cc\ub97c \ud55c \ubc88 \ud655\uc778\ud558\ub294 \uc77c\ub9cc\uc73c\ub85c \uadf8 \uc774\ub984\uc758 \ubaa8\ub4e0 \uc774\uc720\ub97c \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \ubb3c\uac74\uc758 \ubcc0\ud654\uac00 \ubd84\ub958\uc758 \ub9d0\ubcf4\ub2e4 \ube60\ub974\uac8c \ub290\uaef4\uc9c0\ub294 \uc0ac\ub840\ub2e4. \ube44\uc2b7\ud55c \uc77c\uc740 \uc77c\uc0c1\uc758 \uc5ec\ub7ec \uc774\ub984\uc5d0\uc11c\ub3c4 \ub9cc\ub09c\ub2e4. \ucc98\uc74c\uc758 \uc7ac\ub8cc\ub098 \ud615\ud0dc\uc5d0\uc11c \uc0dd\uae34 \ub9d0\uc774 \ubb3c\uac74\uc758 \ubcc0\ud654 \ub4a4\uc5d0\ub3c4 \ub0a8\uc744 \uc218 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubaa8\ub4e0 \uc545\uae30\uad70\uc744 \uc7ac\ub8cc\uc640 \ubb34\uad00\ud55c \uc784\uc758\uc758 \ubb36\uc74c\uc73c\ub85c \ubcf4\uc790\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 \uacf5\uc2dd \uc548\ub0b4\uac00 \ud50c\ub8e8\ud2b8\ub97c \ubaa9\uad00\uc545\uae30\ub85c \uc18c\uac1c\ud558\uba74\uc11c \uacfc\uac70\uc758 \ubaa9\uc81c\uc640 \ud604\ub300\uc758 \uae08\uc18d\uc81c\ub97c \ud568\uaed8 \uc124\uba85\ud55c\ub2e4\ub294 \uc810\uc744 \ub530\ub77c\uac04\ub2e4. \ud50c\ub8e8\ud2b8\uc758 \ud45c\uba74\uc5d0\ub294 \uc5ec\ub7ec \ud0a4\uc640 \ud328\ub4dc\uac00 \ub193\uc5ec \uc788\ub2e4. \uc190\uac00\ub77d\uc744 \uc5b4\ub514\uc5d0 \ub300\ub294\uc9c0\uc640 \uc5b4\ub5a4 \uad6c\uba4d\uc774 \uc5f4\ub9ac\uace0 \ub2eb\ud788\ub294\uc9c0\uac00 \uc7a5\uce58\ub97c \ud1b5\ud574 \uc5f0\uacb0\ub41c\ub2e4. \uc190\uc774 \ub2ff\ub294 \uc704\uce58\uc640 \uc18c\ub9ac\ub97c \ub9cc\ub4dc\ub294 \uc870\uac74 \uc0ac\uc774\uc5d0 \uae30\uacc4\uc801\uc778 \ub3c4\uc6c0\uc744 \ub9c8\ub828\ud55c \uc148\uc774\ub2e4. \uc545\uae30\ub97c \ub9cc\ub4dc\ub294 \uc0ac\ub78c\uc758 \uc120\ud0dd\uc774 \uc5f0\uc8fc\ud560 \uc218 \uc788\ub294 \uc74c\uc545\uc758 \ubc94\uc704\uc640 \uad00\uacc4\ub418\ub294 \uc774\uc720\ub2e4. \uae30\uad00\uc740 19\uc138\uae30\uc5d0 \ubc1c\uc804\ud55c \uccb4\uacc4\ub97c \ub354 \ubcf5\uc7a1\ud55c \uc74c\uc545\uc744 \uc5f0\uc8fc\ud558\ub294 \uc870\uac74\uacfc \uc5f0\uacb0\ud574 \uc18c\uac1c\ud55c\ub2e4. \ud55c \uc0ac\ub78c\uc758 \uc190\uc774 \ubaa8\ub4e0 \uc790\ub9ac\ub97c \uc9c1\uc811 \ub9c9\ub294 \ubaa8\uc2b5\uc744 \ub5a0\uc62c\ub9ac\uae30\ubcf4\ub2e4 \uc870\uc791\uc744 \uc804\ub2ec\ud558\ub294 \uc7a5\uce58\uac00 \uc788\ub2e4\ub294 \uc810\uc744 \ubcf4\uba74 \ub41c\ub2e4. \ub2e4\ub9cc \ubcf8\ubb38\uc758 \uadf8\ub9bc\uc744 \uc815\ud655\ud55c \uc6b4\uc9c0\ud45c\ub85c \uc0ac\uc6a9\ud558\uac70\ub098 \ud0a4 \ud558\ub098\ub9c8\ub2e4 \ud2b9\uc815\ud55c \uc74c\uc744 \ubc14\ub85c \ub300\uc751\uc2dc\ud0a4\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc2e4\uc81c \uc5f0\uc8fc\ubc95\uc740 \ubcc4\ub3c4\uc758 \uc790\ub8cc\uac00 \ud544\uc694\ud55c \uc601\uc5ed\uc774\ub2e4. \uc77c\ubc18\uc801\uc778 C \ud50c\ub8e8\ud2b8 \uc606\uc5d0\ub294 \uc791\uc740 \ud53c\ucf5c\ub85c\uc640 \uc54c\ud1a0, \ubca0\uc774\uc2a4 \ud50c\ub8e8\ud2b8 \uac19\uc740 \uc885\ub958\uac00 \uc788\ub2e4. \uc545\uae30\uad70 \uc548\uc5d0\uc11c \uc11c\ub85c \ub2e4\ub978 \ub192\uc774\uc758 \uc18c\ub9ac\ub97c \ub9e1\uc744 \uc218 \uc788\ub294 \uad6c\uc131\uc774\ub2e4. \uadf8\uc911 \ud53c\ucf5c\ub85c\ub294 \ub300\uccb4\ub85c \ubaa9\uc81c\ub85c \ub9cc\ub4e0\ub2e4\ub294 \uc124\uba85\ub3c4 \uc788\uc5b4, \ud50c\ub8e8\ud2b8 \uac00\uc871\uc744 \ubaa8\ub450 \uac19\uc740 \uc7ac\ub8cc\uc640 \ud06c\uae30\uc758 \ubb3c\uac74\uc73c\ub85c \uc0dd\uac01\ud558\uae30 \uc5b4\ub835\uac8c \ud55c\ub2e4. \uc5f0\uc8fc \uc601\uc0c1\uc744 \ubcfc \ub54c \uac00\uc7a5 \uc791\uac8c \ubcf4\uc774\ub294 \uc545\uae30\uc640 \uc775\uc219\ud55c \ud06c\uae30\uc758 \ud50c\ub8e8\ud2b8\ub97c \ube44\uad50\ud574\ub3c4 \uc7ac\ubbf8\uc788\ub2e4. \ub2e4\ub9cc \ud654\uba74\uc758 \ud06c\uae30\ub9cc\uc73c\ub85c \uc815\ud655\ud55c \uc885\ub958\ub97c \ud310\uc815\ud558\uae30\ubcf4\ub2e4\ub294 \uc548\ub0b4\uc640 \ud568\uaed8 \ud655\uc778\ud558\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc74c\uc545\uc758 \uac00\uc871\uc774\ub77c\ub294 \ub9d0\uc740 \ub2e4 \ub611\uac19\ub2e4\ub294 \ub73b\ubcf4\ub2e4 \uacf5\ud1b5\ub41c \uad00\uacc4 \uc548\uc5d0\uc11c \ucc28\uc774\uac00 \uc788\ub2e4\ub294 \ub73b\uc73c\ub85c \uc774\ud574\ud558\uba74 \ub354 \ud48d\ubd80\ud574\uc9c4\ub2e4. \uc7ac\ub8cc\ub97c \ubcf4\uc558\ub2e4\uba74 \ub2e4\uc74c\uc5d0\ub294 \uc18c\ub9ac\uc758 \uc5b4\ub290 \ubd80\ubd84\uc744 \ub4e3\uace0 \uc2f6\uc740\uc9c0 \uc0dd\uac01\ud574 \ubcfc \uc218 \uc788\ub2e4. \ubc18\uc9dd\uc774\ub294 \uc678\ud615\uc774 \uc5b8\uc81c\ub098 \uac19\uc740 \uc74c\uc0c9\uc744 \ubcf4\uc7a5\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc74c\uc5ed\uacfc \uc5f0\uc8fc \ubc29\uc2dd, \ub2e4\ub978 \uc545\uae30\uc640\uc758 \uad00\uacc4\uc5d0 \ub530\ub77c \uc778\uc0c1\uc740 \ub2ec\ub77c\uc9c4\ub2e4. \uc7ac\ub8cc\uc758 \uc774\ub984\ub9cc\uc73c\ub85c \ub530\ub73b\ud558\ub2e4\uac70\ub098 \ucc28\uac11\ub2e4\ub294 \uac10\uc0c1\uc744 \ubbf8\ub9ac \uc815\ud560 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \ud50c\ub8e8\ud2b8\uc758 \uc774\uc57c\uae30\ub294 \uc18c\ub9ac\ub97c \ub9cc\ub4dc\ub294 \ubb3c\uac74\uc774 \uc624\ub7ab\ub3d9\uc548 \ubc14\ub00c\uc5b4 \uc654\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc5f0\uc8fc\uc790\uc758 \uc190\uc744 \ub3d5\ub294 \uc7a5\uce58\uc640 \uc7ac\ub8cc\uc758 \uc120\ud0dd\uc774 \ud568\uaed8 \ubc1c\uc804\ud588\ub2e4. \ubaa9\uad00\uc774\ub77c\ub294 \uc775\uc219\ud55c \ubd84\ub958 \uc55e\uc5d0\uc11c \uc7a0\uae50 \uba48\ucd94\uba74, \ud55c \uc774\ub984\uc774 \uc11c\ub85c \ub2e4\ub978 \uc2dc\ub300\uc758 \ubb3c\uac74\ub4e4\uc744 \uc5b4\ub5bb\uac8c \uc774\uc5b4 \uc8fc\ub294\uc9c0 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \uc545\uae30 \uc774\ub984\uc744 \uc678\uc6b0\ub294 \uc77c\uc5d0\uc11c \uadf8 \ubcc0\ud654\uc758 \uc2dc\uac04\uc744 \uc77d\ub294 \uc77c\ub85c \ub118\uc5b4\uac00\ub294 \uc791\uc740 \uacc4\uae30\ub2e4. \uc624\ucf00\uc2a4\ud2b8\ub77c\uc5d0\uc11c\ub294 \uc77c\ubc18\uc801\uc778 C \ud50c\ub8e8\ud2b8 \uc678\uc5d0 \ud53c\ucf5c\ub85c\uc640 \uc54c\ud1a0 \ud50c\ub8e8\ud2b8, \ub54c\ub85c\ub294 \ubca0\uc774\uc2a4 \ud50c\ub8e8\ud2b8\ub3c4 \uc4f4\ub2e4. \ud50c\ub8e8\ud2b8\ub77c\ub294 \uc774\ub984 \uc544\ub798\uc5d0\ub3c4 \ud06c\uae30\uc640 \uc5ed\ud560\uc774 \ub2e4\ub978 \uc545\uae30\ub4e4\uc774 \uc788\ub2e4. \uc624\ub298\uc740 \ubaa8\ub4e0 \uc885\ub958\ub97c \uc678\uc6b0\uae30\ubcf4\ub2e4 \uc740\ube5b \ud45c\uba74\uacfc \ubaa9\uad00\uc545\uae30\ub77c\ub294 \uc774\ub984 \uc0ac\uc774\uc758 \uac04\uaca9\ub9cc \uae30\uc5b5\ud574 \ubcf4\uc790. \ubb3c\uac74\uc758 \uc9c0\uae08 \ubaa8\uc2b5\uacfc \uadf8 \ubb3c\uac74\uc744 \ubd80\ub974\ub294 \ub9d0\uc774 \uaf2d \uac19\uc740 \uc2dc\uae30\uc758 \uc774\uc57c\uae30\ub9cc \ub2f4\uace0 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc791\uc740 \uc545\uae30 \ud558\ub098\uc5d0\ub3c4 \uadf8\ub7f0 \uc2dc\uac04\uc774 \uacb9\uce5c\ub2e4."}, {"id": "millet-gleaners-harvest", "title": "\uc774\uc0ad \uc90d\ub294 \uc5ec\uc778\ub4e4 \u2014 \ud48d\uc694\ub85c\uc6b4 \ub4e4\ud310\uc758 \uac00\uc7a5 \ub0ae\uc740 \uc790\ub9ac", "summary": "\uc138 \uc0ac\ub78c\uc758 \ubab8\uacfc \ub113\uc740 \ub4e4\ud310\uc744 \ub530\ub77c \uc77c\uacfc \ubd84\ubc30\ub97c \uc0dd\uac01\ud558\uac8c \ud558\ub294 \ud654\uba74\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Art", "url": "stories/millet-gleaners-harvest/index.html", "image": "media/millet-gleaners-harvest.jpg", "alt": "\ubc00\ub808\uc758 \uc774\uc0ad \uc90d\ub294 \uc5ec\uc778\ub4e4. \uc804\uacbd\uc758 \uc138 \uc5ec\uc778\uc774 \ud5c8\ub9ac\ub97c \uc219\uc5ec \uc774\uc0ad\uc744 \uc90d\uace0 \ub4a4\ucabd\uc5d0\uc11c\ub294 \ub9ce\uc740 \uc218\ud655\ubb3c\uc774 \ubaa8\uc785\ub2c8\ub2e4.", "text": "\uc774\uc0ad \uc90d\ub294 \uc5ec\uc778\ub4e4 \u2014 \ud48d\uc694\ub85c\uc6b4 \ub4e4\ud310\uc758 \uac00\uc7a5 \ub0ae\uc740 \uc790\ub9ac \ubc00\ub808\uc758 \uadf8\ub9bc\uc5d0\uc11c \uc218\ud655\uacfc \uc791\uc740 \uc90d\uae30\ub97c \ud568\uaed8 \ubcf4\uae30 \uc138 \uc0ac\ub78c\uc758 \ubab8\uacfc \ub113\uc740 \ub4e4\ud310\uc744 \ub530\ub77c \uc77c\uacfc \ubd84\ubc30\ub97c \uc0dd\uac01\ud558\uac8c \ud558\ub294 \ud654\uba74\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Art \ubb38\ud654 \ub4e4\ud310\uc758 \uba40\ub9ac\uc5d0\ub294 \uace1\uc2dd\uc774 \ub9ce\uc774 \ubaa8\uc5ec \uc788\ub2e4. \uadf8\ub7f0\ub370 \uadf8\ub9bc \uc55e\ucabd\uc758 \uc138 \uc0ac\ub78c\uc740 \ud5c8\ub9ac\ub97c \uad7d\ud600 \ubc14\ub2e5\uc5d0\uc11c \uc791\uc740 \uc774\uc0ad\uc744 \uc90d\ub294\ub2e4. \uac19\uc740 \uc218\ud655\uc758 \ud48d\uacbd \uc548\uc5d0 \ud070 \ub354\ubbf8\uc640 \uc190\ub05d\uc758 \uc791\uc740 \uc591\uc774 \ud568\uaed8 \ub193\uc778\ub2e4. \ubc00\ub808\uc758 \u3008\uc774\uc0ad \uc90d\ub294 \uc5ec\uc778\ub4e4\u3009\uc774\ub2e4. \uc774 \uadf8\ub9bc\uc740 \ubb34\uc5c7\uc744 \ud558\ub294 \uc0ac\ub78c\ub4e4\uc778\uc9c0 \uc54c\uae30 \uc26c\uc6b0\uba74\uc11c\ub3c4, \uc624\ub798 \ubcf4\uba74 \uadf8 \ub2e8\uc21c\ud55c \uc124\uba85\ubcf4\ub2e4 \ub9ce\uc740 \uac83\uc744 \ub290\ub07c\uac8c \ud55c\ub2e4. \uc804\uacbd\uacfc \ubc30\uacbd, \ubab8\uc758 \ud06c\uae30\uc640 \uc77c\uc758 \uc591\uc774 \uc11c\ub85c \ub2e4\ub978 \uac10\uac01\uc744 \ub9cc\ub4e4\uae30 \ub54c\ubb38\uc774\ub2e4. \uba3c\uc800 \uc138 \uc0ac\ub78c\uc758 \uc190\uc5d0\uc11c \uc2dc\uc791\ud574 \ub4e4\ud310 \ub05d\uae4c\uc9c0 \ub208\uc744 \uc62e\uaca8 \ubcf4\uc790. \uc774\uc0ad \uc90d\uae30\ub294 \ud070 \uc218\ud655\uc744 \uac70\ub454 \ub4a4 \ub4e4\ud310\uc5d0 \ub0a8\uc740 \uc791\uc740 \uace1\uc2dd\ub4e4\uc744 \ubaa8\uc73c\ub294 \uc77c\uc774\ub2e4. \uadf8\ub9bc\uc5d0\uc11c\ub294 \ub450 \uc0ac\ub78c\uc774 \uae4a\uc774 \ud5c8\ub9ac\ub97c \uad7d\ud788\uace0 \ub2e4\ub978 \ud55c \uc0ac\ub78c\uc740 \uc870\uae08 \ubab8\uc744 \uc138\uc6b4 \uc790\uc138\ub97c \ubcf4\uc778\ub2e4. \uc77c\uc744 \ud558\ub294 \ub3d9\uc548 \uacc4\uc18d \ubc18\ubcf5\ub420 \ub3d9\uc791\uc744 \ud55c \ud654\uba74 \uc548\uc5d0\uc11c \ub9cc\ub098\ub294 \uc148\uc774\ub2e4. \uc774\ub97c \ub2e8\uc21c\ud788 \uc0b0\ucc45\ud558\ub2e4 \ub5a8\uc5b4\uc9c4 \uace1\uc2dd\uc744 \uc90d\ub294 \uac00\ubcbc\uc6b4 \uc77c\ub85c \uc0c1\uc0c1\ud558\uba74 \ubab8\uc758 \ubb34\uac8c\ub97c \ub193\uce58\uae30 \uc27d\ub2e4. \uc190\uc740 \ub0ae\uc740 \uacf3\uc5d0 \ub2ff\uc544\uc57c \ud558\uace0 \uc2dc\uc120\uc740 \ub545\uc744 \uc0b4\ud540\ub2e4. \uadf8\ub9bc\uc740 \ub178\ub3d9\uc774\ub77c\ub294 \ud070 \ub9d0 \ub300\uc2e0 \uadf8 \uc77c\uc744 \ud558\ub294 \ub370 \ud544\uc694\ud55c \uc790\uc138\ub97c \ubcf4\uc5ec \uc900\ub2e4. \uc6b0\ub9ac\ub294 \ucd08\uc0c1\ud654\uc5d0\uc11c \uc5bc\uad74\uc758 \ud45c\uc815\uc744 \uba3c\uc800 \ucc3e\ub294 \ub370 \uc775\uc219\ud558\ub2e4. \uc774 \uadf8\ub9bc\uc758 \uc778\ubb3c\ub4e4\uc740 \uace0\uac1c\ub97c \uc219\uc774\uace0 \uc788\uc5b4 \uc5bc\uad74\ub9cc\uc73c\ub85c \uac10\uc815\uc744 \uc77d\uae30 \uc5b4\ub835\ub2e4. \ub300\uc2e0 \ub4f1\uacfc \ud5c8\ub9ac, \ud314\uacfc \ubb34\ub98e\uc774 \uc5b4\ub5a4 \ubc29\ud5a5\uc73c\ub85c \ub193\uc600\ub294\uc9c0\uac00 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \ud45c\uc815\uc744 \ub69c\ub837\uc774 \ubcf4\uc9c0 \ubabb\ud55c\ub2e4\uace0 \uc0ac\ub78c\uc774 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ud788\ub824 \ubab8\uc774 \ud558\ub294 \uc77c\uc744 \ub354 \uc624\ub798 \ubcf4\uac8c \ub420 \uc218 \uc788\ub2e4. \ubb34\uc2a8 \uc0dd\uac01\uc744 \ud588\ub294\uc9c0 \ub300\uc0ac\ub97c \ubd99\uc774\uae30\ubcf4\ub2e4, \uc9c0\uae08 \uc774 \ud589\ub3d9\uc744 \uc5bc\ub9c8\ub098 \ubc18\ubcf5\ud574\uc57c \uc791\uc740 \ubb36\uc74c\uc774 \uc0dd\uae38\uc9c0 \uc0c1\uc0c1\ud574 \ubcf4\uc790. \uadf8\ub9bc\uc758 \uc2dc\uac04\uc740 \ud55c \ubc88\uc758 \ub3d9\uc791\ubcf4\ub2e4 \uae38\uc5b4\uc9c4\ub2e4. \uc67c\ucabd\uc758 \uc778\ubb3c\uc5d0\uc11c \uac00\uc6b4\ub370\ub97c \uac70\uccd0 \uc624\ub978\ucabd\uc73c\ub85c \ub208\uc744 \uc62e\uaca8 \ubcf4\uc790. \ube44\uc2b7\ud55c \uc77c\uc744 \ud558\uc9c0\ub9cc \ubab8\uc758 \ub192\uc774\uc640 \ud314\uc758 \uc704\uce58\ub294 \uc870\uae08\uc529 \ub2e4\ub974\ub2e4. \ubaa8\ub450 \ub611\uac19\uc740 \ubaa8\uc591\uc73c\ub85c \ubc18\ubcf5\ub418\uc9c0 \uc54a\uae30 \ub54c\ubb38\uc5d0 \uc7a5\uba74\uc740 \uc815\uc9c0\ub41c \ub3c4\uc2dd\uc774 \uc544\ub2c8\ub77c \uc0b4\uc544 \uc788\ub294 \uc6c0\uc9c1\uc784\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \uc774\ub97c \ud55c \uc0ac\ub78c\uc774 \uc6c0\uc9c1\uc774\ub294 \uc5f0\uc18d \uc0ac\uc9c4\uc774\ub77c\uace0 \ud655\uc815\ud558\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc778\ubb3c\uc758 \uc790\uc138\ub97c \uc774\uc5b4 \ubcf4\uba70 \uc77c\uc758 \ub9ac\ub4ec\uc744 \ub290\ub07c\ub294 \ubc29\ubc95\uc774\ub2e4. \uac19\uc740 \uc77c\uc744 \ud558\ub294 \uc0ac\ub78c\ub4e4\ub3c4 \uac01\uc790\uc758 \ubab8\uacfc \uc18d\ub3c4\ub97c \uac00\uc9c4\ub2e4\ub294 \uc810\uc774 \ud654\uba74 \uc548\uc5d0 \ub0a8\ub294\ub2e4. \ubc30\uacbd\uc5d0\ub294 \uace1\uc2dd \ub354\ubbf8\uc640 \uc218\ub808, \uc218\ud655\ud558\ub294 \uc0ac\ub78c\ub4e4, \ub9d0\uc744 \ud0c4 \uc778\ubb3c\uc774 \ubcf4\uc778\ub2e4. \uc55e\ucabd\uc5d0\uc11c \uc190\uc73c\ub85c \ubaa8\uc73c\ub294 \uc591\uacfc\ub294 \ub2e4\ub978 \uaddc\ubaa8\ub2e4. \ub450 \uc790\ub9ac\ub97c \ud568\uaed8 \ubcf4\uba74\uc11c \ub204\uac00 \ubb34\uc5c7\uc744 \uc5bc\ub9c8\ub098 \uac00\uc9c0\ub294\uc9c0\uc5d0 \uad00\ud55c \uc9c8\ubb38\uc744 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \uadf8\ub9bc \ud55c \uc7a5\uc73c\ub85c \ub2f9\uc2dc\uc758 \ubaa8\ub4e0 \ud1a0\uc9c0 \uc81c\ub3c4\uc640 \uc784\uae08 \uad00\uacc4\ub97c \ud655\uc778\ud588\ub2e4\uace0 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc9c0\uae08 \ub208\uc73c\ub85c \ud655\uc778\ud558\ub294 \uac83\uc740 \ud070 \uc218\ud655\uacfc \uc791\uc740 \uc90d\uae30\uac00 \ud55c \ud654\uba74\uc5d0 \ud568\uaed8 \uc788\ub2e4\ub294 \uc810\uc774\ub2e4. \uadf8 \uc2dc\uac01\uc801 \ucc28\uc774\uac00 \uc0ac\ud68c\uc758 \uad00\uacc4\ub97c \uc0dd\uac01\ud558\ub3c4\ub85d \uc5ec\uc9c0\ub97c \uc5f0\ub2e4. \uc804\uacbd\uc758 \uc138 \uc0ac\ub78c\uc740 \ud654\uba74\uc5d0\uc11c \ud070 \uc790\ub9ac\ub97c \ucc28\uc9c0\ud55c\ub2e4. \uba40\ub9ac\uc758 \ud48d\uc694\ub85c\uc6b4 \uc218\ud655\uc774 \uc7a5\uba74 \uc804\uccb4\ub97c \uc124\uba85\ud558\ub294 \uc8fc\uc778\uacf5\uc73c\ub85c\ub9cc \ub0a8\uc9c0 \uc54a\ub294\ub2e4. \uac00\uae4c\uc6b4 \uacf3\uc5d0\uc11c \ubab8\uc744 \ub0ae\ucd94\ub294 \uc0ac\ub78c\ub4e4\uc774 \uc6b0\ub9ac\uc758 \ub208\uc55e\uc5d0 \uba3c\uc800 \ub193\uc778\ub2e4. \ubb34\uc5c7\uc744 \uc911\uc2ec\uc5d0 \ub458\uc9c0 \ud654\uac00\uac00 \uace0\ub978 \uacb0\uacfc\ub2e4. \uc791\uc740 \uc77c\uc744 \ud558\ub294 \uc0ac\ub78c\uc744 \uc791\uac8c \uadf8\ub9b4 \ud544\uc694\ub294 \uc5c6\uc5c8\ub2e4. \uadf8\ub9bc\uc758 \ubb3c\ub9ac\uc801\uc778 \ud06c\uae30\uc640 \uc0ac\ud68c\uc801\uc778 \uc8fc\ubaa9\uc774 \uc5b4\ub5a4 \uad00\uacc4\ub97c \ub9fa\ub294\uc9c0 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \uc624\ub298\uc758 \uac10\uc0c1\uc744 \uc791\uac00\uac00 \uc9c1\uc811 \uc120\uc5b8\ud55c \uc815\uce58\uc801 \uad6c\ud638\ucc98\ub7fc \ub9cc\ub4e4\uc9c0\ub294 \uc54a\ub354\ub77c\ub3c4, \uc774 \uc120\ud0dd\uc774 \ubcf4\ub294 \uc21c\uc11c\ub97c \ubc14\uafb8\ub294 \uac83\uc740 \ub290\ub084 \uc218 \uc788\ub2e4. \ub530\ub73b\ud55c \ud759\ube5b\uacfc \uc218\ud655\uae30\uc758 \ud48d\uacbd \ub54c\ubb38\uc5d0 \ucc98\uc74c\uc5d0\ub294 \ud3c9\uc628\ud55c \ub18d\ucd0c \uc7a5\uba74\ucc98\ub7fc \ubcf4\uc77c \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc0ac\ub78c\ub4e4\uc758 \uad7d\uc740 \ubab8\uc744 \ud568\uaed8 \ubcf4\uba74 \ub2e4\ub978 \ubb34\uac8c\ub3c4 \ub290\uaef4\uc9c4\ub2e4. \ubcf4\uae30 \uc88b\uc740 \ud48d\uacbd\uacfc \uadf8 \uc548\uc5d0\uc11c \uc0b4\uc544\uac00\ub294 \ub178\ub3d9\uc740 \uac19\uc740 \uac10\uc815\uc73c\ub85c\ub9cc \uc815\ub9ac\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc0c9\uc774 \ub530\ub73b\ud558\ub2c8 \uc0dd\ud65c\ub3c4 \ud589\ubcf5\ud588\uc744 \uac83\uc774\ub77c\uace0 \uacb0\ub860 \ub0b4\ub9ac\uc9c0 \ub9d0\uc790. \ubc18\ub300\ub85c \ubab8\uc744 \uad7d\ud614\uc73c\ub2c8 \uc5bc\uad74\uc5d0 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc808\ub9dd\uae4c\uc9c0 \uc6b0\ub9ac\uac00 \ubaa8\ub450 \uc548\ub2e4\uace0 \ud560 \uc218\ub3c4 \uc5c6\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \uc790\uc138\uc640 \uacf5\uac04\uc744 \uadfc\uac70\ub85c \uc0dd\uac01\uc744 \ub113\ud788\ub418, \uc778\ubb3c\uc758 \ub0b4\uba74\uc744 \ub2e8\uc815\ud558\uc9c0 \uc54a\ub294 \uac10\uc0c1\uc774 \uac00\ub2a5\ud558\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \uc624\ub798\ub41c \ubbf8\uc220 \ub3c4\ub85d\uc5d0 \uc218\ub85d\ub41c \uc2e4\uc81c \ud68c\ud654\uc758 \uc0c9\ucc44 \uc7ac\ud604 \uc790\ub8cc\ub2e4. \ub18d\ubbfc\ub4e4\uc758 \ubaa8\uc2b5\uc744 AI\ub85c \ub2e4\uc2dc \ub9cc\ub4e0 \uadf8\ub9bc\uc740 \uc544\ub2c8\ub2e4. \uc778\ubb3c\uc758 \ubc30\uce58\uc640 \ub113\uc740 \ub4e4\ud310\uc774 \uc774\ub8e8\ub294 \uad00\uacc4\ub97c \ud655\uc778\ud560 \uc218 \uc788\ub3c4\ub85d \uc6d0\ub798 \ub3c4\ud310\uc744 \uc0ac\uc6a9\ud588\ub2e4. \uc624\ub798\ub41c \uc18c\uc7a5\ud488 \uc548\ub0b4\uc758 \ubc88\ud638\uc640 \uc804\uc2dc \uc815\ubcf4\ub294 \uc624\ub298\uc758 \uc704\uce58\ub97c \ubcf4\uc99d\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc774 \uc790\ub8cc\ub294 \ud604\uc7ac \ubc15\ubb3c\uad00\uc744 \ucc3e\uc544\uac00\ub294 \uc9c0\ub3c4\uac00 \uc544\ub2c8\ub77c \uc791\ud488\uc744 \uc77d\ub294 \ub370 \uc4f0\ub294 \uc774\ubbf8\uc9c0\ub2e4. \uc61b \uc778\uc1c4\uc758 \uc0c9\uacfc \uc138\ubd80 \uc5ed\uc2dc \uc2e4\ubb3c \uc804\uccb4\ub97c \ub300\uc2e0\ud558\uc9c0 \uc54a\uc73c\ubbc0\ub85c \ud070 \uad6c\uc131\ubd80\ud130 \ubcf4\ub294 \ud3b8\uc774 \uc801\uc808\ud558\ub2e4. \uadf8\ub9bc\uc744 \ubcf8 \ub4a4 \ucc98\uc74c\uc758 \uc190\uc73c\ub85c \ub2e4\uc2dc \ub3cc\uc544\uac00 \ubcf4\uc790. \ub4a4\uc758 \ud070 \ub354\ubbf8\ub97c \uc54c\uace0 \ub098\uba74 \uc55e\uc758 \uc791\uc740 \uc90d\uae30\uac00 \ucc98\uc74c\uacfc \ub2e4\ub974\uac8c \ubcf4\uc77c \uc218 \uc788\ub2e4. \uba40\ub9ac\uc640 \uac00\uae4c\uc774, \ub9ce\uc740 \uac83\uacfc \uc791\uc740 \uac83\uc774 \uc11c\ub85c\uc758 \uc758\ubbf8\ub97c \ub9cc\ub4e0\ub2e4. \ud55c \ubd80\ubd84\ub9cc \uc798\ub77c \ubcfc \ub54c\ubcf4\ub2e4 \uc804\uccb4\uc5d0\uc11c \uc0dd\uae30\ub294 \ud798\uc774\ub2e4. \u3008\uc774\uc0ad \uc90d\ub294 \uc5ec\uc778\ub4e4\u3009\uc740 \uc77c\ud558\ub294 \uc0ac\ub78c\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub9cc \uc54c\ub824 \uc8fc\ub294 \uadf8\ub9bc\uc774 \uc544\ub2c8\ub2e4. \ub204\uad6c\uc758 \ubab8\uc744 \ud06c\uac8c \ubcf4\uace0 \uc5b4\ub5a4 \ud48d\uc694\ub97c \ubc30\uacbd\uc73c\ub85c \ub450\ub294\uc9c0 \ubb3b\uac8c \ud55c\ub2e4. \uae38\uac8c \uc124\uba85\ud558\uc9c0 \uc54a\uc544\ub3c4 \uc138 \uc0ac\ub78c\uc758 \ubc18\ubcf5\ub418\ub294 \uc790\uc138\uac00 \uc2dc\uc120\uc744 \ubd99\uc7a1\ub294\ub2e4. \uadf8 \uc55e\uc5d0 \uc7a0\uc2dc \uba38\ubb34\ub294 \uac83\uc774 \uc774 \uc791\ud488\uc744 \uc77d\ub294 \uc88b\uc740 \uc2dc\uc791\uc774\ub2e4."}, {"id": "mona-lisa-looking-guide", "title": "\ubaa8\ub098\ub9ac\uc790 \u2014 \ubbf8\uc18c\uc640 \uc190, \uadf8\ub9ac\uace0 \uadf8\ub9bc\uc774 \uc0ac\ub77c\uc9c4 \ud574", "summary": "\uc190\uacfc \ud48d\uacbd\uc744 \ubcf4\ub294 \ubc29\ubc95\uc5d0 1911\ub144 \ub3c4\ub09c\uc758 \ub3d9\uc2dc\ub300 \uae30\ub85d\uc744 \ub354\ud574 \uc791\ud488\uacfc \uba85\uc131\uc758 \uad00\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Art", "url": "stories/mona-lisa-looking-guide/index.html", "image": "media/mona-lisa-looking-guide.jpg", "alt": "\ub808\uc624\ub098\ub974\ub3c4 \ub2e4\ube48\uce58, \ubaa8\ub098\ub9ac\uc790 \u00b7 \uc61b \ub8e8\ube0c\ub974 \ub3c4\ub85d\uc758 \ud68c\ud654 \uc7ac\ud604\ub3c4\ud310", "text": "\ubaa8\ub098\ub9ac\uc790 \u2014 \ubbf8\uc18c\uc640 \uc190, \uadf8\ub9ac\uace0 \uadf8\ub9bc\uc774 \uc0ac\ub77c\uc9c4 \ud574 \ucd08\uc0c1 \uc18d \uc778\ubb3c\uacfc \ud48d\uacbd, 1911\ub144 \ub3c4\ub09c\uc774 \ub0a8\uae34 \uae30\ub85d \uc190\uacfc \ud48d\uacbd\uc744 \ubcf4\ub294 \ubc29\ubc95\uc5d0 1911\ub144 \ub3c4\ub09c\uc758 \ub3d9\uc2dc\ub300 \uae30\ub85d\uc744 \ub354\ud574 \uc791\ud488\uacfc \uba85\uc131\uc758 \uad00\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Art \ubb38\ud654 \ubaa8\ub098\ub9ac\uc790 \uc55e\uc5d0 \uc11c\uba74 \ubbf8\uc18c\ub97c \uba3c\uc800 \ud655\uc778\ud558\uac8c \ub41c\ub2e4. \uadf8\ub7f0\ub370 \uc774 \uadf8\ub9bc\uc740 \uc785\uac00 \ud558\ub098\ub9cc\uc73c\ub85c \uc720\uba85\ud574\uc9c4 \uc791\ud488\uc774 \uc544\ub2c8\ub2e4. \uc778\ubb3c\uacfc \ud48d\uacbd\uc744 \uc5ee\uc740 \ud68c\ud654\uc774\uba74\uc11c, \uc774\ub984\uacfc \ud574\uc11d\uc774 \uc313\uc774\uace0 \ub3c4\ub09c\uae4c\uc9c0 \uacaa\uc73c\uba70 \uc0ac\ub78c\ub4e4\uc758 \uad00\uc2ec \uc18d\uc5d0 \uc0b4\uc544\uc628 \ubb3c\uac74\uc774\uae30\ub3c4 \ud558\ub2e4. \uc774\ubc88\uc5d0\ub294 \uadf8\ub9bc \uc18d\uc73c\ub85c \ub4e4\uc5b4\uac00\ub294 \uae38\uacfc \uadf8\ub9bc \ubc14\uae65\uc758 \uc5ed\uc0ac\ub97c \ud568\uaed8 \uac78\uc5b4 \ubcf4\uc790. \ubb34\uc5c7\uc744 \uadf8\ub838\ub294\uc9c0 \uc54c\uba74 \uc5bc\uad74\uc774 \uac00\uae4c\uc6cc\uc9c0\uace0, \ub204\uad70\uac00 \uc774 \uc791\ud488\uc744 \uac00\uc838\uac00 \ubc84\ub838\ub2e4\ub294 \uc0ac\uac74\uc744 \uc54c\uba74 \ubc15\ubb3c\uad00\uc5d0 \uac78\ub9b0 \uadf8\ub9bc\uc744 \ubcf4\ub294 \uac10\uac01\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \ub974\ub124\uc0c1\uc2a4 \ud654\uac00 \ub808\uc624\ub098\ub974\ub3c4 \ub2e4\ube48\uce58\uac00 \uadf8\ub9b0 \uc774 \ucd08\uc0c1\uc740 \ub9ac\uc790 \uac8c\ub77c\ub974\ub514\ub2c8\ub97c \ubaa8\ub378\ub85c \ud55c \uac83\uc73c\ub85c \uc54c\ub824\uc838 \uc788\ub2e4. \ub0a8\ud3b8\uc758 \uc131 \uc870\ucf58\ub3c4\uc640 \uc5f0\uacb0\ub41c \uc774\ub984\uc73c\ub85c \uc774\ud0c8\ub9ac\uc544\uc5b4 \ub77c \uc870\ucf58\ub2e4, \ud504\ub791\uc2a4\uc5b4 \ub77c \uc870\ucf69\ub4dc\ub77c\uace0\ub3c4 \ubd88\ub9b0\ub2e4. \u2018\ubaa8\ub098\ub9ac\uc790\u2019\uc640 \u2018\ub77c \uc870\ucf69\ub4dc\u2019\uac00 \uc11c\ub85c \ub2e4\ub978 \uadf8\ub9bc\uc758 \uc774\ub984\uc740 \uc544\ub2c8\ub2e4. \uc720\uba85\ud55c \ubbf8\uc18c\ub77c\ub294 \ub9d0\ub9cc \ub5a0\uc62c\ub9ac\ub2e4\uac00 \ud55c \uc0ac\ub78c\uc758 \ucd08\uc0c1\uc774\ub77c\ub294 \uc0ac\uc2e4\ub85c \ub3cc\uc544\uc624\uba74 \uc9c8\ubb38\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \ubb34\uc5c7\uc744 \uc0dd\uac01\ud574\uc11c \uc6c3\uc5c8\ub290\ub0d0\ub294 \ucd94\uce21\uc5d0 \uc55e\uc11c, \ud654\uac00\uac00 \ud55c \uc778\ubb3c\uc744 \ud654\uba74 \uc548\uc5d0 \uc5b4\ub5bb\uac8c \uc549\ud614\ub294\uc9c0 \ubcf4\uac8c \ub41c\ub2e4. \uadf8\ub9bc \uc18d \ud45c\uc815\ub9cc\uc73c\ub85c \uc2e4\uc81c \ubaa8\ub378\uc758 \uc131\uaca9\uc774\ub098 \ub2f9\uc2dc \uac10\uc815\uae4c\uc9c0 \ud655\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \ud654\uba74 \uc544\ub798\uc5d0\ub294 \ub450 \uc190\uc774 \uacb9\uccd0\uc838 \uc788\ub2e4. \ubab8\uc740 \uc870\uae08 \ub3cc\ub824 \uc549\uc544 \uc788\uc9c0\ub9cc \uc5bc\uad74\uc740 \uad00\uac1d \ucabd\uc744 \ud5a5\ud55c\ub2e4. \uc190\uc5d0\uc11c \uc5b4\uae68\ub85c, \uc5b4\uae68\uc5d0\uc11c \uc5bc\uad74\ub85c \ub208\uc744 \uc62c\ub9ac\uba74 \uc778\ubb3c \uc804\uccb4\uac00 \ucc28\ubd84\ud558\uac8c \uc790\ub9ac\ub97c \uc7a1\uace0 \uc788\ub2e4\ub294 \ub290\ub08c\uc744 \ubc1b\uc744 \uc218 \uc788\ub2e4. \uc785\uac00\ub9cc \ud655\ub300\ud574 \ubcfc \ub54c\uc640\ub294 \ub2e4\ub978 \uacbd\ud5d8\uc774\ub2e4. \ub208\uae38\uc744 \uc7a1\uc544\ub044\ub294 \ud45c\uc815 \uc544\ub798\uc5d0 \uc190\uacfc \ud314\uc774 \ub9cc\ub4dc\ub294 \uc548\uc815\uac10\uc774 \uc788\ub2e4. \uc5bc\uad74\uc774 \ud63c\uc790 \ub5a0 \uc788\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ubab8\uacfc \ud568\uaed8 \uacf5\uac04\uc744 \ucc28\uc9c0\ud55c\ub2e4\ub294 \uc810\uc744 \uc0b4\ud3b4\ubcf4\uc790. \uba85\ud654\ub97c \ubcfc \ub54c \uc138\ubd80 \ud558\ub098\ub97c \uc54c\uace0 \ub098\uba74 \uadf8 \ubd80\ubd84\ub9cc \ud655\uc778\ud558\uae30 \uc26c\uc6b4\ub370, \uc624\ud788\ub824 \uc720\uba85\ud55c \uc138\ubd80\uc5d0\uc11c \uc7a0\uc2dc \ub5a8\uc5b4\uc838\uc57c \uadf8\ub9bc \uc804\uccb4\uac00 \ub2e4\uc2dc \ubcf4\uc774\uae30\ub3c4 \ud55c\ub2e4. \uc778\ubb3c \ub4a4\uc5d0\ub294 \ubc14\uc704\uc640 \ubb3c\uae38, \uad7d\uc774\uce58\ub294 \uae38\uacfc \uba40\ub9ac \uc774\uc5b4\uc9c0\ub294 \ud48d\uacbd\uc774 \ub193\uc5ec \uc788\ub2e4. \uac00\uae4c\uc6b4 \uc5bc\uad74\uacfc \uc190, \uc544\uc8fc \uba3c \ubc30\uacbd\uc774 \ud55c \ud654\uba74\uc5d0 \uacf5\uc874\ud55c\ub2e4. \uc778\ubb3c\uc758 \uc548\uc815\ub41c \uc790\uc138\uc640 \uad74\uace1\uc9c4 \uc9c0\ud615\uc744 \ubc88\uac08\uc544 \ubcf4\uba74 \uadf8\ub9bc\uc774 \ub2e8\uc21c\ud55c \uc99d\uba85\uc0ac\uc9c4\ucc98\ub7fc \ub9cc\ub4e4\uc5b4\uc9c0\uc9c0 \uc54a\uc558\ub2e4\ub294 \uc810\uc744 \ub290\ub084 \uc218 \uc788\ub2e4. \uc774 \ubc30\uacbd\uc774 \uc2e4\uc81c \uc5b4\ub290 \uc7a5\uc18c\uc778\uc9c0 \uc5ec\uae30\uc11c \ud55c \uacf3\uc73c\ub85c \ud655\uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud48d\uacbd\uc744 \uc9c0\uba85\uc758 \uc218\uc218\uaed8\ub07c\ub85c\ub9cc \ub2e4\ub8e8\uae30\ubcf4\ub2e4 \uac00\uae4c\uc6b4 \uc0ac\ub78c\uacfc \uba3c \uc138\uacc4\uac00 \uc5b4\ub5a4 \uad00\uacc4\ub97c \uc774\ub8e8\ub294\uc9c0 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uac19\uc740 \ub3c4\ud310\uc5d0\uc11c\ub3c4 \uc5bc\uad74\uc744 \uac00\ub9ac\uace0 \ubc30\uacbd\ub9cc \ubcf8 \ub4a4 \ub2e4\uc2dc \uc804\uccb4\ub97c \ubcf4\uba74 \ucc98\uc74c\uc5d0\ub294 \uc9c0\ub098\ucce4\ub358 \ubd80\ubd84\uc774 \ub208\uc5d0 \ub4e4\uc5b4\uc62c \uc218 \uc788\ub2e4. \uc774 \uc791\ud488\uc758 \uc5ed\uc0ac\uc5d0\ub294 \uc2e4\uc81c \ub3c4\ub09c \uc0ac\uac74\uc774 \uc788\ub2e4. 1911\ub144 \ubaa8\ub098\ub9ac\uc790\ub294 \ub8e8\ube0c\ub974\uc5d0\uc11c \ub3c4\ub09c\ub2f9\ud588\ub2e4. \ubc15\ubb3c\uad00\uc5d0 \uac78\ub9b0 \uba85\ud654\uac00 \ub2f9\uc5f0\ud788 \uadf8 \uc790\ub9ac\uc5d0 \uc788\uc744 \uac83\uc774\ub77c\ub294 \ubbff\uc74c\uc774 \uae68\uc9c4 \uac83\uc774\ub2e4. \uc624\ub298\uc758 \uc804\uc2dc\uc7a5\uc744 \ub5a0\uc62c\ub9ac\uba74 \uba3c \uc774\uc57c\uae30 \uac19\uc9c0\ub9cc, \ub2f9\uc2dc \uc0ac\ub78c\uc5d0\uac8c\ub294 \ubbf8\uc220 \uc791\ud488\uc758 \uac10\uc0c1\uacfc \ubcc4\uac1c\ub85c \uadf8\ub9bc \uc790\uccb4\uc758 \ud589\ubc29\uc774 \ubb38\uc81c\uac00 \ub418\uc5c8\ub2e4. \uadf8 \ucda9\uaca9\uc740 \ub2f9\uc2dc \uc5ec\ud589\ucc45\uc5d0\ub3c4 \ud754\uc801\uc744 \ub0a8\uacbc\ub2e4. E. V. \ub8e8\ucee4\uc2a4\ub294 1912\ub144 \uc11c\ubb38\uc744 \ubd99\uc778 \u300e\ud53c\ub80c\uccb4\ub97c \uac70\ub2d0\ub2e4\u300f\uc5d0\uc11c \ub808\uc624\ub098\ub974\ub3c4\uc758 \ud6fc\uc190\ub418\uac70\ub098 \ubbf8\uc644\uc131\uc73c\ub85c \ub0a8\uc740 \uc791\ud488\ub4e4\uc744 \uc774\uc57c\uae30\ud558\ub2e4\uac00, \ubaa8\ub098\ub9ac\uc790\ub9c8\uc800 1911\ub144 \ub8e8\ube0c\ub974\uc5d0\uc11c \ub3c4\ub09c\ub2f9\ud588\ub2e4\uace0 \ub367\ubd99\uc778\ub2e4. \uc774 \uae30\ub85d\uc5d0\uc11c\ub294 \ubc94\ud589\uc744 \uc18c\uc124\ucc98\ub7fc \uc7ac\ud604\ud558\uae30\ubcf4\ub2e4, \uc774\ubbf8 \uc720\uba85\ud588\ub358 \uadf8\ub9bc\uc758 \ubd80\uc7ac\uac00 \ub3d9\uc2dc\ub300\uc758 \uae00\uc5d0 \ub4e4\uc5b4\uc654\ub2e4\ub294 \uc810\uc744 \ud655\uc778\ud560 \uc218 \uc788\ub2e4. \ub3c4\ub09c \uc9c1\uc804\uc758 \uba85\uc131\uc744 \uc0dd\uac01\ud560 \uc790\ub8cc\ub3c4 \uc788\ub2e4. \ub8e8\ucee4\uc2a4\uc758 \ub2e4\ub978 \ucc45 \u300e\ud30c\ub9ac\ub97c \uac70\ub2d0\ub2e4\u300f\ub294 \ubaa8\ub098\ub9ac\uc790\uac00 \uc5c6\ub294 \ud30c\ub9ac\ub294 \uc6b0\ub9ac\uac00 \uc544\ub294 \ud30c\ub9ac\uac00 \uc544\ub2d0 \uac83\uc774\ub77c\uace0 \ud560 \ub9cc\ud07c \uadf8\ub9bc\uc744 \ub192\uc774 \ud3c9\uac00\ud588\ub2e4. \ub530\ub77c\uc11c \u2018\ub3c4\ub09c \uc804\uc5d0\ub294 \uc544\ubb34\ub3c4 \ubaa8\ub974\ub358 \uadf8\ub9bc\uc778\ub370 \uc0ac\uac74 \ud558\ub098\ub85c \uba85\ud654\uac00 \ub418\uc5c8\ub2e4\u2019\uace0 \ub2e8\uc21c\ud654\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc774\ubbf8 \ud3c9\uac00\ubc1b\ub358 \uc791\ud488\uc5d0 \ub3c4\ub09c\uc774\ub77c\ub294 \uc0c8\ub85c\uc6b4 \uc774\uc57c\uae30\uac00 \ub354\ud574\uc84c\ub2e4\uace0 \ubcf4\ub294 \ud3b8\uc774 \uc790\ub8cc\uc640 \ub9de\ub294\ub2e4. \ud55c \uadf8\ub9bc\uc774 \uc0ac\ub77c\uc84c\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub450 \uc885\ub958\uc758 \uac00\uce58\ub97c \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \ud558\ub098\ub294 \ud654\uba74 \uc790\uccb4\uc758 \ud68c\ud654\uc801 \uac00\uce58\uc774\uace0, \ub2e4\ub978 \ud558\ub098\ub294 \ub9ce\uc740 \uc0ac\ub78c\uc774 \uadf8 \uc791\ud488\uc744 \uae30\uc5b5\ud558\uace0 \ub9cc\ub098\uace0 \uc2f6\uc5b4 \ud55c\ub2e4\ub294 \uc0ac\ud68c\uc801 \uac00\uce58\ub2e4. \uc720\uba85\ud55c \uadf8\ub9bc\uc758 \ubd80\uc7ac\uac00 \ud06c\uac8c \ub290\uaef4\uc9c0\ub294 \uac83\uc740 \uac00\uaca9 \ub54c\ubb38\ub9cc\uc774 \uc544\ub2c8\ub77c, \ud568\uaed8 \uacf5\uc720\ud558\ub358 \uc774\ubbf8\uc9c0\uac00 \uc2e4\uc81c \ubb3c\uac74\uc73c\ub85c\ub294 \ub354 \uc774\uc0c1 \uac70\uae30 \uc5c6\uae30 \ub54c\ubb38\uc774\ub2e4. \ub3c4\ub09c\uc744 \uc548 \ub4a4\uc5d0\ub294 \uc791\ud488\uc758 \uc874\uc7ac \ubc29\uc2dd\ub3c4 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \uc0ac\uc9c4\uc73c\ub85c\ub294 \uc5bc\uad74\uc744 \uacc4\uc18d \ubcfc \uc218 \uc788\uc5b4\ub3c4, \uc2e4\uc81c \uadf8\ub9bc\uc774 \uc5b4\ub514 \uc788\ub294\uc9c0 \uc54c \uc218 \uc5c6\ub2e4\uba74 \uac19\uc740 \uacbd\ud5d8\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub9bc\uc758 \uc774\ubbf8\uc9c0\ub97c \uc548\ub2e4\ub294 \uac83\uacfc \uadf8 \uc6d0\uc791\uc774 \uc6b0\ub9ac \uacc1\uc5d0 \ub0a8\uc544 \uc788\ub2e4\ub294 \uac83\uc740 \uc11c\ub85c \ub2e4\ub978 \uc77c\uc774\ub2e4. \uc774 \uc0ac\uac74\uc740 \uc720\uba85\ud55c \uc5bc\uad74 \ub4a4\uc5d0 \uc0ac\ub77c\uc9c8 \uc218\ub3c4 \uc788\ub294 \ud55c \uc810\uc758 \ubb3c\uac74\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ub4dc\ub7ec\ub0b8\ub2e4. \ub3c4\ub09c \uc0ac\uac74, \ubcf5\uc81c\ud488, \ucc45\uacfc \uac01\uc885 \ub9e4\uccb4\ub97c \ud1b5\ud574 \uc6b0\ub9ac\ub294 \uc2e4\ubb3c\uc744 \ubcf4\uae30 \uc804\ubd80\ud130 \uc774 \uc5bc\uad74\uc744 \uc548\ub2e4. \ub108\ubb34 \uc775\uc219\ud558\uba74 \uadf8\ub9bc\uc744 \uc9c1\uc811 \uad00\ucc30\ud558\uae30\ubcf4\ub2e4 \u2018\uc720\uba85\ud558\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ud655\uc778\ud558\ub294 \uc77c\u2019\ub85c \uad00\ub78c\uc774 \ub05d\ub0a0 \uc218 \uc788\ub2e4. \uc774 \uc810\uc5d0\uc11c \ubaa8\ub098\ub9ac\uc790\ub294 \uadf8\ub9bc\uc744 \uac10\uc0c1\ud558\ub294 \uc6b0\ub9ac\uc758 \uc2b5\uad00\uae4c\uc9c0 \ub3cc\uc544\ubcf4\uac8c \ud55c\ub2e4. \ub2e4\uc2dc \uc190\uacfc \ubab8, \uc5bc\uad74\uacfc \ud48d\uacbd\uc744 \ucc28\ub840\ub85c \ubcf4\uc790. \ud45c\uc815\uc744 \ud55c \uac00\uc9c0 \uac10\uc815\uc73c\ub85c \uc815\ub9ac\ud558\uc9c0 \uc54a\uace0, \uac00\uae4c\uc774\uc5d0\uc11c \ubcfc \ub54c\uc640 \uc804\uccb4\ub97c \ubcfc \ub54c \uc778\uc0c1\uc774 \uc5b4\ub5bb\uac8c \ub2e4\ub978\uc9c0 \ube44\uad50\ud574\ub3c4 \uc88b\ub2e4. \ub204\uad70\uac00\ub294 \ucc28\ubd84\ud568\uc744, \ub204\uad70\uac00\ub294 \uac70\ub9ac\uac10\uc744 \ub290\ub084 \uc218 \uc788\ub2e4. \uc720\uba85\ud55c \uc124\uba85\uc744 \uadf8\ub300\ub85c \ub290\ub07c\uc9c0 \ubabb\ud588\ub2e4\uace0 \uac10\uc0c1\uc5d0 \uc2e4\ud328\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \uc61b \ub8e8\ube0c\ub974 \ub3c4\ub85d\uc758 \uc2e4\uc81c \uc791\ud488 \uc0c9\ucc44 \uc7ac\ud604 \ub3c4\ud310\uc774\ub2e4. \uc624\ub298\uc758 \uc791\ud488\uc744 \uc0c8\ub85c \ucd2c\uc601\ud55c \uace0\ud574\uc0c1\ub3c4 \uc0ac\uc9c4\uc740 \uc544\ub2c8\ubbc0\ub85c \uc778\uc1c4\uc758 \uc0c9\uacfc \uc138\ubd80\uac00 \uc2e4\ubb3c\uc744 \uc644\uc804\ud788 \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc6d0\uc791\uc758 \uad6c\uc131\uacfc \uc8fc\uc694 \ubd80\ubd84\uc744 \uc0b4\ud3b4\ubcf4\ub294 \uc790\ub8cc\ub85c \uc0ac\uc6a9\ud588\ub2e4. \ubaa8\ub098\ub9ac\uc790\uc5d0\uc11c\ub294 \ud654\uba74\uc744 \ubcf4\ub294 \uc77c\uacfc \uadf8 \ud654\uba74\uc744 \ub458\ub7ec\uc2fc \uc5ed\uc0ac\ub97c \uc77d\ub294 \uc77c\uc774 \ud568\uaed8 \uac00\ub2a5\ud558\ub2e4. \ub3c4\ub09c \uc774\uc57c\uae30\ub97c \uc54c\uace0 \ub098\uc11c \uadf8\ub9bc\uc73c\ub85c \ub3cc\uc544\uc624\uba74 \uc720\uba85\ud55c \ubbf8\uc18c\uac00 \uc870\uae08 \ub2e4\ub978 \uc9c8\ubb38\uc744 \uac74\ub128\ub2e4. \uc6b0\ub9ac\ub294 \uc65c \uc774 \uc0ac\ub78c\uc744 \uae30\uc5b5\ud558\uace0, \uc65c \uc774 \ud55c \uc7a5\uc758 \uadf8\ub9bc\uc744 \ub9cc\ub098\ub7ec \uac00\ub294\uac00. \uc791\ud488\uc758 \uc0ac\uc5f0\uc740 \ub208\uc744 \ub300\uc2e0\ud558\ub294 \uc124\uba85\uc774 \uc544\ub2c8\ub77c, \ub2e4\uc2dc \ubc14\ub77c\ubcfc \uc774\uc720\uac00 \ub420 \uc218 \uc788\ub2e4."}, {"id": "moonlight-sonata-name", "title": "\uc6d4\uad11 \u2014 \ubca0\ud1a0\ubca4\uc774 \ubd99\uc778 \uc81c\ubaa9\uc740 \uc544\ub2c8\uc5c8\ub2e4", "summary": "\uc6d4\uad11\uc774\ub77c\ub294 \uc774\ub984\uacfc \uc18c\ub098\ud0c0 \uc790\uccb4\ub97c \ub098\ub204\uc5b4 \ub4e3\ub294 \ubc29\ubc95\uc744 \uc81c\uc548\ud569\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Music", "url": "stories/moonlight-sonata-name/index.html", "image": "media/moonlight-sonata-name.jpg", "alt": "1917\ub144 Romain Rolland, Beethoven \uc218\ub85d \uc6d4\uad11 \uc18c\ub098\ud0c0 \uc790\ud544 \uc545\ubcf4 \uc7ac\ud604\ub3c4\ud310", "text": "\uc6d4\uad11 \u2014 \ubca0\ud1a0\ubca4\uc774 \ubd99\uc778 \uc81c\ubaa9\uc740 \uc544\ub2c8\uc5c8\ub2e4 \ub2ec\ube5b\uc774\ub77c\ub294 \ubcc4\uba85 \ub4a4\uc5d0\uc11c \uc138 \uc545\uc7a5\uc744 \ub4e3\uae30 \uc6d4\uad11\uc774\ub77c\ub294 \uc774\ub984\uacfc \uc18c\ub098\ud0c0 \uc790\uccb4\ub97c \ub098\ub204\uc5b4 \ub4e3\ub294 \ubc29\ubc95\uc744 \uc81c\uc548\ud569\ub2c8\ub2e4. Music \ubb38\ud654 \u3008\uc6d4\uad11\u3009\uc744 \ucc98\uc74c \ub4e3\ub294 \uc0ac\ub78c\ub3c4 \uccab \uc545\uc7a5\uc5d0\ub294 \uc27d\uac8c \uadc0\ub97c \uae30\uc6b8\uc778\ub2e4. \ub0ae\uc740 \uc74c \uc704\ub85c \uc794\uc794\ud55c \uc18c\ub9ac\uac00 \uc774\uc5b4\uc9c0\uace0, \uadf8 \uc704\uc5d0\uc11c \ub178\ub798\uac00 \ucc9c\ucc9c\ud788 \ubaa8\uc2b5\uc744 \ub4dc\ub7ec\ub0b8\ub2e4. \uc774\ub984\uc744 \uc54c\uace0 \ub4e4\uc73c\uba74 \ub2ec\ube5b\uc774 \ub5a0\uc624\ub974\uae30 \uc27d\ub2e4. \uadf8\ub7f0\ub370 \uc138 \uc545\uc7a5\uc744 \ubaa8\ub450 \ub4e4\uc73c\uba74 \ub9c8\uc9c0\ub9c9\uc5d0\ub294 \uaf64 \ub2e4\ub978 \ud48d\uacbd\uc744 \ub9cc\ub098\uac8c \ub41c\ub2e4. \uc774 \uace1\uc740 \uc870\uc6a9\ud55c \uccab \uc545\uc7a5\uc73c\ub85c \uc2dc\uc791\ud574 \uaca9\ub82c\ud55c \ub05d\uc73c\ub85c \ub098\uc544\uac00\ub294 \ud53c\uc544\ub178 \uc18c\ub098\ud0c0\ub2e4. \ubcc4\uba85\uc758 \uc720\ub798\uc640 \uc791\ud488\uc758 \uc2e4\uc81c \uad6c\uc870\ub97c \ud568\uaed8 \uc54c\uba74, \uc720\uba85\ud55c \ubd80\ubd84\ub9cc \ubc18\ubcf5\ud574\uc11c \ub4e3\ub358 \uc74c\uc545\uc774 \uc870\uae08 \ub113\uc5b4\uc9c4\ub2e4. \uc6b0\ub9ac\uac00 \u3008\uc6d4\uad11\u3009\uc774\ub77c\uace0 \ubd80\ub974\ub294 \uace1\uc740 \ubca0\ud1a0\ubca4\uc758 \ud53c\uc544\ub178 \uc18c\ub098\ud0c0 \uc81c14\ubc88, \uc791\ud488\ubc88\ud638 27\uc758 2\ubc88\uc774\ub2e4. \uc791\ud488\uc5d0\ub294 \u2018\ud658\uc0c1\uace1\ud48d\uc758 \uc18c\ub098\ud0c0\u2019\ub77c\ub294 \ub73b\uc758 Sonata quasi una fantasia\ub77c\ub294 \ud45c\uc81c\uac00 \uc788\ub2e4. \ub2ec\ube5b\uc740 \uc774 \ubcf8\ub798 \ud45c\uc81c\uc5d0 \ub4e4\uc5b4 \uc788\uc9c0 \uc54a\ub2e4. \ub85c\ub9f9 \ub864\ub791\uc758 \uc804\uae30 \u300e\ubca0\ud1a0\ubca4\u300f\uc5d0 \ud568\uaed8 \uc2e4\ub9b0 \uc18c\ub098\ud0c0 \ud574\uc124\uc740 \u2018\uc6d4\uad11\u2019\uc774\ub77c\ub294 \ubcc4\uce6d\uc744 \uc2dc\uc778 \ub810\uc288\ud0c0\ud504\uc640 \uc5f0\uacb0\ud55c\ub2e4. \uc911\uc694\ud55c \uc810\uc740 \uc791\uace1\uac00\uc758 \ud45c\uc81c\uac00 \uc544\ub2c8\ub77c \ub2e4\ub978 \uc0ac\ub78c\uc774 \uc74c\uc545\uc744 \ub4e3\uace0 \ubd99\uc778 \uc774\ub984\uc774\ub77c\ub294 \uac83\uc774\ub2e4. \ubcc4\uce6d\uc774 \ub110\ub9ac \uc4f0\uc778\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ubca0\ud1a0\ubca4\uc774 \ub2ec\ube5b\uc744 \ubb18\uc0ac\ud558\ub824 \uc791\uace1\ud588\ub2e4\ub294 \uc8fc\uc7a5\uc740 \uad6c\ubcc4\ud574\uc57c \ud55c\ub2e4. \uac19\uc740 \uc790\ub8cc\ub294 \uc791\ud488\uc774 \uc904\ub9ac\uc5d0\ud0c0 \uadc0\ucc28\ub974\ub514\uc5d0\uac8c \ud5cc\uc815\ub418\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud5cc\uc815\uc740 \ucc45\uc758 \uccab\uba38\ub9ac\uc5d0 \uc774\ub984\uc744 \ubc14\uce58\ub294 \uac83\uacfc \ube44\uc2b7\ud558\uac8c, \ub204\uad6c\uc5d0\uac8c \uc791\ud488\uc744 \ub4dc\ub9ac\ub294\uc9c0 \ubc1d\ud788\ub294 \ubc29\uc2dd\uc774\ub2e4. \uadc0\ucc28\ub974\ub514\uc640\uc758 \uad00\uacc4\ub294 \uc774 \uc791\ud488\uc744 \ub458\ub7ec\uc2fc \uc804\uae30\uc801 \ubc30\uacbd\uc758 \ud55c \ubd80\ubd84\uc774\ub2e4. \ub2e4\ub9cc \ud5cc\uc815 \ub300\uc0c1\uc774 \uc788\ub2e4\ub294 \uc774\uc720\ub85c \ubaa8\ub4e0 \uc120\uc728\uc744 \ud2b9\uc815 \uc5f0\uc560 \uc7a5\uba74\uc758 \uc554\ud638\ub77c\uace0 \ud574\ub3c5\ud560 \uc218\ub294 \uc5c6\ub2e4. \uccab \uc545\uc7a5\uc740 \uace0\ubc31, \ub458\uc9f8\ub294 \ub9cc\ub0a8, \uc14b\uc9f8\ub294 \uc774\ubcc4\uc774\ub77c\ub294 \uc2dd\uc758 \uc774\uc57c\uae30\ub97c \uc791\uace1\uac00\uc758 \ud655\uc815\ub41c \uc124\uba85\ucc98\ub7fc \ubd99\uc774\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc0ac\ub78c\uc758 \uc0ac\uc5f0\uc744 \uc54c\uace0 \ub4e4\uc5b4\ub3c4, \uc74c\uc545\uc774 \uc2e4\uc81c\ub85c \uc5b4\ub5a4 \ud750\ub984\uc744 \ub9cc\ub4dc\ub294\uc9c0\ub294 \ub530\ub85c \uc0b4\ud544 \uc218 \uc788\ub2e4. \uccab \uc545\uc7a5\uc758 \uc9c0\uc2dc\ub294 Adagio sostenuto, \ub290\ub9ac\uac8c \uc9c0\uc18d\ud558\uc5ec \uc5f0\uc8fc\ud558\ub77c\ub294 \ub73b\uc73c\ub85c \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \ub0ae\uc740 \uc74c\uc774 \ubc14\ud0d5\uc744 \uc7a1\uace0, \uc911\uac04\uc5d0\uc11c\ub294 \uc138 \uc74c\uc529 \uc774\uc5b4\uc9c0\ub294 \ubc18\uc8fc\uac00 \uafb8\uc900\ud788 \uc6c0\uc9c1\uc774\uba70, \uadf8 \uc704\uc5d0 \ube44\uad50\uc801 \uae34 \uc74c\uac00\uc758 \uc120\uc728\uc774 \ub098\ud0c0\ub09c\ub2e4. \uc794\uc794\ud558\ub2e4\uace0 \ud574\uc11c \uc544\ubb34 \uc6c0\uc9c1\uc784\ub3c4 \uc5c6\ub294 \uc74c\uc545\uc740 \uc544\ub2c8\ub2e4. \ucc98\uc74c\uc5d0\ub294 \ub178\ub798\ud558\ub294 \uac00\uc7a5 \uc704\ucabd \uc18c\ub9ac\ub9cc \ub4e4\uc5b4 \ubcf4\uc790. \ub2e4\uc74c\uc5d0\ub294 \uadf8 \uc544\ub798\uc5d0\uc11c \uacc4\uc18d \uc774\uc5b4\uc9c0\ub294 \ubc18\uc8fc\ub97c \ub530\ub77c\uac00 \ubcf4\uc790. \uac19\uc740 \uace1 \uc548\uc5d0 \uba48\ucd98 \ub4ef\ud55c \uc2dc\uac04\uacfc \ud758\ub7ec\uac00\ub294 \uc2dc\uac04\uc774 \ud568\uaed8 \uc788\ub2e4\ub294 \ub290\ub08c\uc744 \ubc1b\uc744 \uc218 \uc788\ub2e4. \uc18c\ub9ac\uac00 \uc870\uae08\uc529 \uc313\uc774\uace0 \ud654\uc74c\uc774 \ub2ec\ub77c\uc9c8 \ub54c \uace0\uc694\ud568\uc5d0\ub3c4 \uc791\uc740 \uae34\uc7a5\uc774 \uc0dd\uae34\ub2e4. \ubc24\uc758 \ud48d\uacbd\uc744 \ub5a0\uc62c\ub9ac\uba70 \ub4e3\ub294 \uac83\uc740 \uc790\uc5f0\uc2a4\ub7ec\uc6b4 \uac10\uc0c1\uc774\ub2e4. \ud558\uc9c0\ub9cc \uccab \uc545\uc7a5\uc774 \ud3b8\uc548\ud55c \ubc30\uacbd\uc74c\uc545\uc73c\ub85c\ub9cc \ub4e4\ub9ac\ub294\uc9c0, \uc5b4\ub518\uac00 \ubb34\uac70\uc6c0\uacfc \uae30\ub2e4\ub9bc\ub3c4 \uc788\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uba74 \uc88b\ub2e4. \ud2b9\uc815 \uc7a5\uba74\uc744 \uc815\ub2f5\uc73c\ub85c \uc0bc\uc9c0 \uc54a\uc744 \ub54c \uc74c\uc545 \uc548\uc758 \ubbf8\ubb18\ud55c \ubcc0\ud654\uac00 \ub354 \uc798 \ub4e4\ub9b4 \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 1917\ub144 \uc804\uae30\uc5d0 \uc218\ub85d\ub41c \uc790\ud544 \uc545\ubcf4\uc758 \uc7ac\ud604 \ub3c4\ud310\uc774\ub2e4. \ud604\ub300 \uc870\ud310 \uc545\ubcf4\ucc98\ub7fc \ubc18\ub4ef\ud558\uc9c0 \uc54a\uc740 \uc790\ub8cc\uc5d0\uc11c, \uc624\ub298\uc758 \uc720\uba85\ud55c \ubcc4\uba85 \ub4a4\uc5d0\ub294 \uad6c\uccb4\uc801\uc778 \uc74c\uacfc \uc5f0\uc8fc \uc9c0\uc2dc\ub97c \uc801\ub358 \uc791\uace1\uac00\uc758 \uc791\uc5c5\uc774 \uc788\uc5c8\ub2e4\ub294 \uc810\ub3c4 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \uc61b \uc778\uc1c4 \ub3c4\ud310\uc774 \uc6d0\uace0 \uc2e4\ubb3c\uc758 \uc0c1\ud0dc\ub97c \ubaa8\ub450 \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub458\uc9f8 \uc545\uc7a5 Allegretto\ub294 \uccab \uc545\uc7a5\ubcf4\ub2e4 \uac00\ubccd\uace0 \uac78\uc74c\uc774 \ubd84\uba85\ud558\uac8c \ub290\uaef4\uc9c4\ub2e4. \uccab \uc545\uc7a5\uc5d0\uc11c \uae38\uac8c \uba38\ubb3c\ub358 \uc2dc\uac04\uc774 \uc9e7\uc740 \uc6c0\uc9c1\uc784\uc73c\ub85c \ud480\ub9ac\ub294 \ub4ef\ud558\ub2e4. \ucda4\uc744 \uc5f0\uc0c1\ud558\uba70 \ub4e4\uc5b4\ub3c4 \uc88b\uc9c0\ub9cc, \uc2e4\uc81c\ub85c \uc5b4\ub5a4 \uc0ac\ub78c\uc774 \ucda4\ucd94\ub294 \uc7a5\uba74\uc744 \ubb18\uc0ac\ud55c \uac83\uc774\ub77c\uace0 \ub2e8\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc720\uba85\ud55c \uccab \uc545\uc7a5\uacfc \uac15\ub82c\ud55c \uc14b\uc9f8 \uc545\uc7a5 \uc0ac\uc774\uc5d0 \uc788\uc5b4 \uc774 \ubd80\ubd84\uc740 \uc9c0\ub098\uac00\ub294 \ub2e4\ub9ac\ucc98\ub7fc \ucde8\uae09\ub418\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \uc774 \uc9e7\uc740 \uc804\ud658\uc774 \uc788\uae30 \ub54c\ubb38\uc5d0 \uc791\ud488 \uc804\uccb4\uc758 \ub300\ube44\uac00 \ub354 \uc120\uba85\ud574\uc9c4\ub2e4. \ub458\uc9f8 \uc545\uc7a5\uc774 \ub05d\ub098\uae30 \uc804 \uc7a0\uae50\uc758 \uac00\ubcbc\uc6c0\uc744 \uae30\uc5b5\ud574 \ub450\uba74 \ub9c8\uc9c0\ub9c9 \uc545\uc7a5\uc758 \uccab \uc6c0\uc9c1\uc784\uc774 \ud55c\uce35 \ud06c\uac8c \ub2e4\uac00\uc628\ub2e4. \ub9c8\uc9c0\ub9c9 \uc9c0\uc2dc\ub294 Presto agitato, \ub9e4\uc6b0 \ube60\ub974\uace0 \uaca9\ud558\uac8c\ub77c\ub294 \ub73b\uc774\ub2e4. \uc74c\ub4e4\uc774 \ube60\ub974\uac8c \uc19f\uc544\uc624\ub974\uace0, \uac15\ud55c \ud654\uc74c\uc774 \ubc15\ud788\uba70, \uc26c\uc9c0 \uc54a\uace0 \ubc00\uc5b4\ubd99\uc774\ub294 \ub4ef\ud55c \uc5d0\ub108\uc9c0\uac00 \ub098\uc628\ub2e4. \uccab \uc545\uc7a5\uc758 \ud45c\uc815\ub9cc \uc54c\uace0 \uc788\uc5c8\ub2e4\uba74 \uac19\uc740 \uc18c\ub098\ud0c0\uc758 \ub9c8\uc9c0\ub9c9\uc774\ub77c\ub294 \uc0ac\uc2e4\uc774 \ub180\ub77c\uc6b8 \uc218 \uc788\ub2e4. \ud55c\ud3b8 \uc55e\uc120 \uc18c\ub098\ud0c0 \ud574\uc124\uc740 \uccab \uc545\uc7a5\uacfc \ub9c8\uc9c0\ub9c9 \uc545\uc7a5\uc758 \uc74c\ud615 \uc0ac\uc774\uc5d0 \uc5f0\uacb0\uc744 \uc9da\uae30\ub3c4 \ud55c\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uace1 \uc138 \ud3b8\uc744 \uc784\uc758\ub85c \ubd99\uc5ec \ub193\uc558\ub2e4\uae30\ubcf4\ub2e4, \ub2e4\ub978 \uc18d\ub3c4\uc640 \ud798\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \ud55c \uc791\ud488\uc73c\ub85c \ub4e4\uc744 \uc5ec\uc9c0\uac00 \uc788\ub2e4\ub294 \ub73b\uc774\ub2e4. \ucc98\uc74c\ubd80\ud130 \uc545\ubcf4\uc758 \ub300\uc751 \uad00\uacc4\ub97c \ucc3e\uc9c0 \ubabb\ud574\ub3c4 \uad1c\ucc2e\ub2e4. \uace0\uc694\ud558\uac8c \uc2dc\uc791\ud55c \uc74c\uc545\uc774 \uc5b4\ub514\uae4c\uc9c0 \uc6c0\uc9c1\uc774\ub294\uc9c0\ub9cc \ub530\ub77c\uac00 \ubcf4\uc790. \ud658\uc0c1\uace1\ud48d\uc774\ub77c\ub294 \ub9d0\uc740 \uc544\ubb34\ub807\uac8c\ub098 \uc5f0\uc8fc\ud574\ub3c4 \ub41c\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \ud1b5\uc0c1\uc801\uc778 \ud2c0\uc744 \uc758\uc2dd\ud558\uba74\uc11c\ub3c4 \uc545\uc7a5\ub4e4\uc758 \uc131\uaca9\uacfc \uc5f0\uacb0\uc744 \uc790\uc720\ub86d\uac8c \uad6c\uc131\ud558\ub824\ub294 \ud45c\uc81c\ub85c \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uc774 \uc18c\ub098\ud0c0\uc5d0\uc11c\ub294 \ube60\ub974\uace0 \ud654\ub824\ud55c \uccab\uba38\ub9ac\ub85c \uccad\uc911\uc744 \ubd99\uc7a1\uae30\ubcf4\ub2e4 \ub290\ub9b0 \uccab \uc545\uc7a5\uc73c\ub85c \uc2dc\uac04\uc744 \uc5f4\uace0, \ub05d\uc5d0\uc11c \ud070 \ud798\uc744 \ud130\ub728\ub9b0\ub2e4. \u2018\uc6d4\uad11\u2019\uc774 \ud48d\uacbd\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \uc774\ub984\uc774\ub77c\uba74 \u2018\ud658\uc0c1\uace1\ud48d\uc758 \uc18c\ub098\ud0c0\u2019\ub294 \uc791\ud488\uc758 \uc9dc\uc784\uc744 \uc0dd\uac01\ud558\uac8c \ud558\ub294 \uc774\ub984\uc774\ub2e4. \ub450 \uc774\ub984\uc744 \ud568\uaed8 \uc54c\uc544 \ub450\uba74 \ud558\ub098\ub294 \uc0c1\uc0c1\uc5d0, \ub2e4\ub978 \ud558\ub098\ub294 \ub4e3\ub294 \ubc29\ubc95\uc5d0 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \uc720\uba85\ud55c \ubcc4\uba85\uc744 \ubc84\ub9b4 \uc774\uc720\ub3c4, \uadf8\uac83 \ud558\ub098\ub85c \uc804\ubd80\ub97c \uc124\uba85\ud560 \uc774\uc720\ub3c4 \uc5c6\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uccab \uc545\uc7a5\uc5d0\uc11c \ubc18\ubcf5\ub418\ub294 \ubc18\uc8fc\ub97c \ucc3e\uc544\ubcf4\uace0, \ub458\uc9f8\uc5d0\uc11c\ub294 \uac78\uc74c\uc758 \ubcc0\ud654\ub97c, \uc14b\uc9f8\uc5d0\uc11c\ub294 \uc19f\uad6c\uce58\ub294 \uc5d0\ub108\uc9c0\ub97c \ub290\uaef4 \ubcf4\uc790. \uc5f0\uc8fc\uc790\ub9c8\ub2e4 \ube60\ub974\uae30\uc640 \uc18c\ub9ac\uc758 \ubb34\uac8c\uac00 \ub2e4\ub974\ubbc0\ub85c \uc7ac\uc0dd \uc2dc\uac04 \ud558\ub098\ub97c \uc815\ub2f5\uc73c\ub85c \uc0dd\uac01\ud560 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \ub9c8\uc9c0\ub9c9 \uc74c\uc744 \ub4e3\uace0 \ucc98\uc74c\uc744 \ub5a0\uc62c\ub9ac\uba74 \ub2ec\ube5b\uc774\ub77c\ub294 \uc81c\ubaa9\uacfc\ub294 \uc870\uae08 \ub2e4\ub978 \uae30\uc5b5\uc774 \ub0a8\uc744 \uc218 \uc788\ub2e4. \uc774 \uace1\uc758 \ub9e4\ub825\uc740 \uc870\uc6a9\ud568\ub9cc\ub3c4 \uaca9\ub82c\ud568\ub9cc\ub3c4 \uc544\ub2c8\ub2e4. \uc11c\ub85c \ub2e4\ub978 \ud45c\uc815\uc774 \ud55c \uc791\ud488\uc758 \uc2dc\uac04 \uc548\uc5d0 \ub193\uc774\ub294 \uacbd\ud5d8\uc774\ub2e4. \uc775\uc219\ud55c \uccab \uc545\uc7a5\uc744 \ucd9c\ubc1c\uc810\uc73c\ub85c \uc0bc\ub418, \ub05d\uae4c\uc9c0 \uac78\uc5b4\uac00 \ubcf4\uba74 \uc18c\ub098\ud0c0 \uc804\uccb4\uac00 \ubcf4\uc774\uae30 \uc2dc\uc791\ud55c\ub2e4."}, {"id": "mountain-chief-recorded-song", "title": "\uc61b \ub179\uc74c \uc0ac\uc9c4\uc5d0\uc11c \uadf8\ub294 \ub178\ub798\ub97c \ub4e3\uace0 \uc788\uc5c8\ub2e4", "summary": "\uc18c\ub9ac\ub97c \ub2f4\ub294 \uae30\uacc4 \uacc1\uc5d0 \uc0ac\ub78c\uc758 \ud574\uc11d\ub3c4 \ud544\uc694\ud588\ub358 \uc7a5\uba74\uc744 \ubd05\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Music", "url": "stories/mountain-chief-recorded-song/index.html", "image": "media/mountain-chief-recorded-song.jpg", "alt": "1916\ub144 \ud504\ub79c\uc2dc\uc2a4 \ub374\uc2a4\ubaa8\uc5b4\uc640 \ub9c8\uc6b4\ud2f4 \uce58\ud504, \ub098\ud314 \ubaa8\uc591 \uc7a5\uce58\uac00 \ud568\uaed8 \uc788\ub294 \uc5ed\uc0ac \uc0ac\uc9c4. \uad50\uc7ac\ub294 \ub179\uc74c\ub41c \ub178\ub798\ub97c \ub4e3\uace0 \uc218\ud654\ub85c \ud574\uc11d\ud558\ub294 \uc7a5\uba74\uc774\ub77c\uace0 \uc124\uba85\ud569\ub2c8\ub2e4.", "text": "\uc61b \ub179\uc74c \uc0ac\uc9c4\uc5d0\uc11c \uadf8\ub294 \ub178\ub798\ub97c \ub4e3\uace0 \uc788\uc5c8\ub2e4 1916\ub144\uc758 \ub098\ud314\uacfc \uc0ac\ub78c \uc0ac\uc774\uc5d0 \ub193\uc778 \uc124\uba85 \uc18c\ub9ac\ub97c \ub2f4\ub294 \uae30\uacc4 \uacc1\uc5d0 \uc0ac\ub78c\uc758 \ud574\uc11d\ub3c4 \ud544\uc694\ud588\ub358 \uc7a5\uba74\uc744 \ubd05\ub2c8\ub2e4. Music \ubb38\ud654 \ud751\ubc31 \uc0ac\uc9c4 \uc18d\uc5d0 \ucee4\ub2e4\ub780 \ub098\ud314 \ubaa8\uc591\uc758 \uc7a5\uce58\uac00 \uc788\ub2e4. \uc624\ub978\ucabd\uc5d0\ub294 \ud55c \uc0ac\ub78c\uc774 \uc549\uc544 \uc788\uace0 \uc67c\ucabd\uc5d0\ub294 \ub2e4\ub978 \uc0ac\ub78c\uc774 \uc790\ub9ac\ud55c\ub2e4. \uc624\ub798\ub41c \ub179\uc74c \uc7a5\uba74\uc774\ub77c\uace0\ub9cc \uc0dd\uac01\ud558\uba74 \ub204\uad70\uac00 \ub178\ub798\ud558\ub294 \uc21c\uac04\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \ud558\uc9c0\ub9cc OpenStax\uac00 \uc18c\uac1c\ud558\ub294 \uc774 1916\ub144 \uc0ac\uc9c4\uc5d0\uc11c \ub9c8\uc6b4\ud2f4 \uce58\ud504\ub294 \ub179\uc74c\ub41c \ub178\ub798\ub97c \ub4e3\uace0 \uc788\uc5c8\ub2e4. \uadf8 \uacc1\uc5d0\ub294 \ubd81\ubbf8 \uc6d0\uc8fc\ubbfc \uc74c\uc545\uc744 \uc5f0\uad6c\ud55c \ud504\ub79c\uc2dc\uc2a4 \ub374\uc2a4\ubaa8\uc5b4\uac00 \uc788\ub2e4. \uad50\uc7ac\uc758 \ucea1\uc158\uc5d0 \ub530\ub974\uba74 \ub9c8\uc6b4\ud2f4 \uce58\ud504\ub294 \ub374\uc2a4\ubaa8\uc5b4\uac00 \ub179\uc74c\ud55c \ub178\ub798\ub97c \ub4e4\uc73c\uba70 \ubd81\ubbf8 \ud3c9\uc6d0 \uc9c0\uc5ed\uc758 \uc218\ud654\ub85c \ud574\uc11d\ud574 \uc8fc\uc5c8\ub2e4. \uc0ac\uc9c4\uc744 \ub2e8\uc21c\ud788 \uc18c\ub9ac\ub97c \uc800\uc7a5\ud558\ub294 \uae30\uacc4\uc758 \uae30\ub85d\uc73c\ub85c\ub9cc \uc77d\uae30 \uc5b4\ub824\uc6cc\uc9c0\ub294 \ub300\ubaa9\uc774\ub2e4. \ub178\ub798\uac00 \uc7a5\uce58 \uc548\uc5d0 \ub2f4\uaca8 \uc788\ub2e4\uace0 \uadf8 \ub178\ub798\uc758 \ub9e5\ub77d\uae4c\uc9c0 \uc800\uc808\ub85c \uc804\ub2ec\ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub4e3\ub294 \uc0ac\ub78c\uacfc \uc124\uba85\ud558\ub294 \uc0ac\ub78c, \uc11c\ub85c \uc758\ubbf8\ub97c \ub098\ub204\ub294 \uacfc\uc815\ub3c4 \uadf8 \uacc1\uc5d0 \uc788\ub2e4. \uc774\uac83\uc740 \uc774 \uc7a5\uba74\uc5d0\uc11c \uc0dd\uac01\ud574 \ubcfc \uc218 \uc788\ub294 \uc810\uc774\ub2e4. \ub179\uc74c\ud55c\ub2e4\uace0 \uc124\uba85\ud560 \ub54c\uc640 \ub179\uc74c\uc744 \ub4e3\ub294\ub2e4\uace0 \uc124\uba85\ud560 \ub54c \uc0ac\uc9c4\uc758 \uc2dc\uac04\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \ub204\uac00 \ubb34\uc5c7\uc744 \ud558\uace0 \uc788\uc5c8\ub294\uc9c0 \uc54c\ub824 \uc8fc\ub294 \uc9e7\uc740 \ucea1\uc158\uc774 \ubcf4\ub294 \ubc29\ud5a5\uc744 \ubc14\uafb8\ub294 \uac83\uc774\ub2e4. \uc774 \uc0ac\uc9c4\uc5d0\uc11c \uc2e4\uc81c\ub85c \uc5b4\ub5a4 \uac00\uc0ac\uc758 \uc5b4\ub290 \ubd80\ubd84\uc744 \uc124\uba85\ud588\ub294\uc9c0\uae4c\uc9c0 \uc0c8\ub85c \ub9cc\ub4e4\uc5b4 \ubd99\uc774\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc790\ub8cc\uac00 \uc54c\ub824 \uc8fc\ub294 \ud589\ub3d9\uc744 \uba3c\uc800 \uc77d\uc73c\uba74, \uace0\uac1c\uc640 \uc190\uc758 \uc704\uce58\ub3c4 \uadf8 \uc7a5\uba74 \uc548\uc5d0\uc11c \ub2e4\uc2dc \uc0b4\ud3b4\ubcf4\uac8c \ub41c\ub2e4. \uc0ac\uc9c4 \uc18d\uc5d0 \ub179\uc74c \uc7a5\uce58\uac00 \ubcf4\uc774\uba74 \uc6b0\ub9ac\ub294 \ub204\uad70\uac00 \ub178\ub798\ub97c \ub179\uc74c\ud558\ub294 \uc21c\uac04\uc774\ub77c\uace0 \uc9d0\uc791\ud558\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \ucea1\uc158\uc740 \uc774\ubbf8 \ub179\uc74c\ud55c \ub178\ub798\ub97c \ub4e3\uace0 \ud574\uc11d\ud558\ub294 \uc7a5\uba74\uc774\ub77c\uace0 \uc54c\ub824 \uc900\ub2e4. \uac19\uc740 \ubb3c\uac74 \uc55e\uc5d0 \uc549\uc544 \uc788\uc5b4\ub3c4 \ubcf4\ub0b4\ub294 \uc18c\ub9ac\uc640 \ubc1b\uc544 \ub4e3\ub294 \uc18c\ub9ac\uc758 \uc2dc\uac04\uc740 \ub2e4\ub974\ub2e4. \uc0ac\uc9c4\uc758 \uc678\ud615\uacfc \ub0a8\uc740 \uc124\uba85\uc744 \ud568\uaed8 \uc77d\uc5b4\uc57c \ud558\ub294 \uc774\uc720\ub2e4. \uc0ac\uc9c4\uc744 \ubcf4\uc790\ub9c8\uc790 \ub5a0\uc62c\ub9b0 \uccab \uc774\uc57c\uae30\ub97c \uc9c0\uc6cc\uc57c \ud560 \ub54c\uc5d0\ub3c4 \uad00\ucc30\uc774 \uc2e4\ud328\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc124\uba85\uc744 \uc77d\uace0 \uc190\uc758 \ub3d9\uc791\uacfc \ubab8\uc758 \ubc29\ud5a5\uc744 \ub2e4\uc2dc \ubcf4\uac8c \ub418\uae30 \ub54c\ubb38\uc774\ub2e4. \ub2e4\ub9cc \uc5b4\ub5a4 \uac00\uc0ac\uc5d0 \ub9de\ucd94\uc5b4 \uc5b4\ub5a4 \ub73b\uc744 \uc804\ub2ec\ud588\ub294\uc9c0\uae4c\uc9c0\ub294 \uc774 \uc790\ub8cc\uc758 \ucea1\uc158\uc73c\ub85c \uc54c \uc218 \uc5c6\ub2e4. \ud655\uc778\ub418\ub294 \ud589\ub3d9\uc774 \ubb34\uc5c7\uc778\uc9c0\ubd80\ud130 \uc815\ud655\ud788 \uc138\uc6b0\uba74 \uc624\ud788\ub824 \ub354 \ub9ce\uc740 \uc9c8\ubb38\uc774 \uac00\ub2a5\ud574\uc9c4\ub2e4. \uc790\ub8cc\ub294 \ub9c8\uc6b4\ud2f4 \uce58\ud504\uac00 \ubd81\ubbf8 \ud3c9\uc6d0 \uc9c0\uc5ed\uc758 \uc218\ud654\ub85c \ub178\ub798\ub97c \ud574\uc11d\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud55c \uc7a5\uba74\uc5d0\uc11c \ub4e3\uae30\uc640 \ubab8\uc9d3, \uc758\ubbf8\ub97c \uc804\ud558\ub294 \uc77c\uc774 \ud568\uaed8 \uc774\ub8e8\uc5b4\uc84c\ub2e4. \uc18c\ub9ac\uac00 \ub179\uc74c \uc7a5\uce58 \uc548\uc5d0 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uadf8 \ubb38\ud654\uc758 \uc9c0\uc2dd\uc774 \uc804\ubd80 \uc800\uc7a5\ub41c \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ub9e5\ub77d\uc744 \uc54c\uace0 \uc124\uba85\ud558\ub294 \uc0ac\ub78c\uc758 \uc5ed\ud560\uc774 \uadf8 \uacc1\uc5d0 \ub0a8\uc544 \uc788\ub2e4. \uc5ec\uae30\uc758 \uc218\ud654\ub97c \uc624\ub298\uc758 \ud2b9\uc815 \uc218\uc5b4 \uccb4\uacc4\uc640 \uc124\uba85 \uc5c6\uc774 \uac19\ub2e4\uace0 \ub193\uac70\ub098, \uc778\ubb3c\uc758 \uccad\uac01 \uc0c1\ud0dc\ub97c \ucd94\uce21\ud574\uc11c\ub3c4 \uc548 \ub41c\ub2e4. \uc0ac\uc9c4\uc758 \ud589\ub3d9\uc740 \uc790\ub8cc\uac00 \ubc1d\ud78c \uc9c0\uc5ed\uc801 \ub9e5\ub77d\uc5d0\uc11c \uc77d\uc744 \ubd80\ubd84\uc774\ub2e4. \ubab8\uc9d3\uc744 \ub2e8\uc21c\ud55c \uc7a5\uc2dd\ucc98\ub7fc \ubcf4\ub294 \ub300\uc2e0 \ub73b\uc744 \ub098\ub204\ub294 \ud65c\ub3d9\uc73c\ub85c \ubc14\ub77c\ubcf4\uba74 \ub178\ub798\uc640 \uc5b8\uc5b4\uc758 \uad00\uacc4\ub97c \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ub374\uc2a4\ubaa8\uc5b4\ub294 \ubd81\ubbf8 \uc6d0\uc8fc\ubbfc \uc74c\uc545\uc744 \uc5f0\uad6c\ud55c \uc778\ubb3c\uc774\ub2e4. \uadf8 \uc5ed\ud560\ub9cc \uac15\uc870\ud558\uba74 \ub9c8\uc6b4\ud2f4 \uce58\ud504\ub294 \uae30\ub85d\uc758 \ub300\uc0c1\ucc98\ub7fc \ubcf4\uc77c \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \ucea1\uc158\uc5d0\ub294 \uadf8\uac00 \ub4e3\uace0 \ud574\uc11d\ud558\ub294 \ud589\ub3d9\uc774 \ubd84\uba85\ud788 \ub098\uc628\ub2e4. \uc5f0\uad6c\uc5d0 \uc4f0\uc774\ub294 \uc9c0\uc2dd\uc740 \uc7a5\uce58\ub97c \uc900\ube44\ud55c \uc0ac\ub78c\uc5d0\uac8c\ub9cc \uc788\uc5c8\ub358 \uac83\uc774 \uc544\ub2c8\ub2e4. \ub204\uac00 \ubb34\uc5c7\uc744 \uc54c\uace0 \uc804\ud574 \uc8fc\uc5c8\ub294\uc9c0 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc774 \uad00\uc810\uc740 \uc0ac\uc9c4 \uc18d \ubaa8\ub4e0 \uad00\uacc4\uac00 \ud3c9\ub4f1\ud588\ub2e4\uace0 \uc27d\uac8c \ub2e8\uc815\ud558\ub294 \uac83\uacfc\ub3c4 \ub2e4\ub974\ub2e4. \ub2f9\uc2dc \uc5f0\uad6c\uac00 \uc774\ub8e8\uc5b4\uc9c4 \uc0ac\ud68c\uc801 \uc870\uac74\uc740 \ubcc4\ub3c4\ub85c \ud655\uc778\ud560 \ubb38\uc81c\ub2e4. \uc5ec\uae30\uc11c\ub294 \ud55c \uc7a5\uba74\uc744 \uc124\uba85\ud560 \ub54c \uc9c0\uc2dd\uc744 \uc81c\uacf5\ud558\ub294 \uc0ac\ub78c\uc758 \ud589\ub3d9\uacfc \uc774\ub984\uc744 \uc9c0\uc6b0\uc9c0 \uc54a\ub294 \ub370 \ucd08\uc810\uc744 \ub9de\ucd98\ub2e4. \uc790\ub8cc\ub97c \ub9cc\ub4e4 \ub54c\uc758 \uad00\uacc4\ub97c \ubb3b\ub294 \uc77c\ub3c4 \uc0ac\uc9c4 \uc77d\uae30\uc758 \uc77c\ubd80\ub2e4. \uc74c\uc545\uc744 \ub4e3\ub294 \uc0ac\ub78c\uc740 \uc18c\ub9ac\uc758 \ub192\ub0ae\uc774\uc640 \ub9ac\ub4ec\uc744 \ub290\ub084 \uc218 \uc788\uc9c0\ub9cc \uc5b8\uc5b4\uc640 \uad00\uc2b5\uc744 \ubaa8\ub974\uba74 \ub193\uce58\ub294 \ub9e5\ub77d\uc774 \uc788\uc744 \uc218 \uc788\ub2e4. \uc774 \uc0ac\uc9c4\uc740 \uadf8 \uc0ac\uc774\uc5d0 \uc124\uba85\uacfc \ud574\uc11d\uc758 \uc2dc\uac04\uc774 \uc788\uc5c8\ub2e4\ub294 \uc810\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uae30\ub85d\uc740 \ud63c\uc790 \ubaa8\ub4e0 \ub73b\uc744 \ub9d0\ud574 \uc8fc\ub294 \ubb3c\uac74\uc774 \uc544\ub2c8\ub77c \ub2e4\uc2dc \ub4e3\uace0 \uc11c\ub85c \ud655\uc778\ud558\ub294 \ud65c\ub3d9\uc744 \uac00\ub2a5\ud558\uac8c \ud558\ub294 \ub9e4\uccb4\uc774\uae30\ub3c4 \ud558\ub2e4. \uc2e4\uc81c \uc0ac\uc9c4\uc740 \uc0c8\ub85c \ub9cc\ub4e0 \uc5ed\uc0ac \uc0bd\ud654\uc640 \ub2ec\ub9ac \ucd2c\uc601 \ub2f9\uc2dc\uc758 \uc778\ubb3c\uacfc \ubb3c\uac74\uc744 \uc804\ud55c\ub2e4. \uadf8\ub807\uc9c0\ub9cc \ud55c \uc7a5\uc758 \uc0ac\uc9c4\uc774 \uc55e\ub4a4\uc758 \ub300\ud654 \uc804\uccb4\ub97c \uc54c\ub824 \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \ubcf4\uc774\ub294 \uac83\uacfc \uc804\ud574\uc9c0\ub294 \uc124\uba85\uc744 \uc624\uac00\uba70 \ub204\uac00 \ubb34\uc5c7\uc744 \ud558\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uc624\ub798\ub41c \uc7a5\uce58\ubcf4\ub2e4 \uadf8 \uc55e\uc5d0\uc11c \uc758\ubbf8\ub97c \ub098\ub204\ub358 \uc0ac\ub78c\ub4e4\uc758 \ud589\ub3d9\uc774 \ub354 \ub610\ub837\ud574\uc9c8 \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 \uc2e4\uc81c \uc5ed\uc0ac \uc0ac\uc9c4\uc774\ub2e4. \ub2f9\uc2dc\uc758 \uc790\uc138\uc640 \uc7a5\uce58, \uc0ac\ub78c \uc0ac\uc774\uc758 \uac70\ub9ac\ub97c \uc0c1\uc0c1\uc73c\ub85c \uc7ac\ubc30\uce58\ud558\uc9c0 \uc54a\uace0 \uc790\ub8cc\uac00 \ub0a8\uae34 \ubaa8\uc2b5\uc744 \ubcf4\ub3c4\ub85d \ud588\ub2e4. \uc624\ub798\ub41c \uc7a5\ube44\uc5d0 \uc2dc\uc120\uc744 \ube7c\uc557\uae30\ub2e4\uac00\ub3c4 \uc0ac\ub78c \ucabd\uc73c\ub85c \ub2e4\uc2dc \ub3cc\uc544\uc624\uac8c \ub41c\ub2e4. \uc18c\ub9ac\ub97c \ub0a8\uae30\ub294 \uae30\uc220\uc740 \uc911\uc694\ud558\uc9c0\ub9cc \uc18c\ub9ac\uc758 \ub73b\uc744 \uc544\ub294 \uc0ac\ub78c\ub3c4 \uc911\uc694\ud558\ub2e4. \uc774 \uc791\uc740 \ub9cc\ub0a8\uc744 \ud1b5\ud574 \ub178\ub798\ub97c \uae30\ub85d\ud55c\ub2e4\ub294 \uac83\uc774 \uae30\uacc4\uc758 \uc77c\ub85c\ub9cc \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc0dd\uac01\ud574 \ubcfc \uc218 \uc788\ub2e4. \uc0ac\uc9c4 \uc18d\uc5d0\ub294 \ub4e3\ub294 \uc2dc\uac04\uacfc \uc124\uba85\ud558\ub294 \uc2dc\uac04\uc774 \ud568\uaed8 \uc788\ub2e4."}, {"id": "mozart-turkish-rondo", "title": "\ud130\ud0a4 \ud589\uc9c4\uace1 \u2014 \ud53c\uc544\ub178\uc5d0\uc11c \uad70\uc545\ub300\uac00 \ub4e4\ub9ac\ub294 \uc774\uc720", "summary": "\uc81c\ubaa9\uc758 \ub73b\uacfc \uc2dc\ub300\uc758 \uc74c\uc545 \ucde8\ud5a5, \uac00\ubcbc\uc6b4 \uc120\uc728\uacfc \ud798\ucc2c \uad6c\uac04\uc758 \ub300\ube44\ub97c \ub530\ub77c \ub4e3\uc2b5\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Music", "url": "stories/mozart-turkish-rondo/index.html", "image": "media/mozart-turkish-rondo-scene-20261030.png", "alt": "\ud587\uc0b4\uc774 \ub4e4\uc5b4\uc624\ub294 \ubc29\uc5d0\uc11c \uc61b \uac74\ubc18\uc545\uae30\ub97c \uc5f0\uc8fc\ud558\ub294 \uc190\uc758 \uc6c0\uc9c1\uc784\uc744 \ud45c\ud604\ud55c \uc0c1\uc0c1 \uc0bd\ud654.", "text": "\ud130\ud0a4 \ud589\uc9c4\uace1 \u2014 \ud53c\uc544\ub178\uc5d0\uc11c \uad70\uc545\ub300\uac00 \ub4e4\ub9ac\ub294 \uc774\uc720 \ubaa8\ucc28\ub974\ud2b8\uc758 \u2018\ud130\ud0a4\ud48d\u2019\uacfc \ud53c\uc544\ub178 \uc18c\ub098\ud0c0 K.331\uc758 \ub9c8\uc9c0\ub9c9 \uc545\uc7a5 \uc81c\ubaa9\uc758 \ub73b\uacfc \uc2dc\ub300\uc758 \uc74c\uc545 \ucde8\ud5a5, \uac00\ubcbc\uc6b4 \uc120\uc728\uacfc \ud798\ucc2c \uad6c\uac04\uc758 \ub300\ube44\ub97c \ub530\ub77c \ub4e3\uc2b5\ub2c8\ub2e4. Music \ubb38\ud654 \ud53c\uc544\ub178\uac00 \uac00\ubccd\uac8c \uba87 \uc74c\uc744 \uad74\ub9ac\ub354\ub2c8 \uc5b4\ub290\uc0c8 \uc529\uc529\ud55c \uac78\uc74c\uc73c\ub85c \ubc14\ub010\ub2e4. \ubaa8\ucc28\ub974\ud2b8\uc758 \u3008\ud130\ud0a4 \ud589\uc9c4\uace1\u3009\uc740 \uc81c\ubaa9\uacfc \uc120\uc728\uc774 \ubaa8\ub450 \uce5c\uc219\ud558\ub2e4. \uadf8\ub7f0\ub370 \ud130\ud0a4 \uc0ac\ub78c\uc774 \ub9cc\ub4e0 \ud589\uc9c4\uace1\ub3c4, \uc6d0\ub798 \uad70\uc545\ub300\uac00 \uc5f0\uc8fc\ud558\ub3c4\ub85d \uc4f4 \uace1\ub3c4 \uc544\ub2c8\ub2e4. \ud53c\uc544\ub178 \ud55c \ub300\uac00 \uc11c\ub85c \ub2e4\ub978 \ud45c\uc815\uc744 \uc624\uac00\uba70 \ub4e4\ub824\uc8fc\ub294 \uc74c\uc545\uc774\ub2e4. \uc81c\ubaa9\uc744 \uc774\ud574\ud560 \uc2e4\ub9c8\ub9ac\ub294 \uc545\ubcf4\uc758 Alla Turca\uc5d0 \uc788\ub2e4. \u2018\ud130\ud0a4\ud48d\uc73c\ub85c\u2019\ub77c\ub294 \ub73b\uc774\ub2e4. \uc5b4\ub514\uc5d0\uc11c \ud0dc\uc5b4\ub09c \uace1\uc778\uac00\ubcf4\ub2e4 \uc5b4\ub5a4 \uc18c\ub9ac\uc640 \ubd84\uc704\uae30\ub97c \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294\uac00\ub97c \uc54c\ub824 \uc8fc\ub294 \uc774\ub984\uc774\ub2e4. \uc774 \uace1\uc740 \ubaa8\ucc28\ub974\ud2b8\uc758 \ud53c\uc544\ub178 \uc18c\ub098\ud0c0 K.331\uc5d0 \uc18d\ud55c\ub2e4. \uccab \uc545\uc7a5\uc740 \uc8fc\uc81c\uc640 \ubcc0\uc8fc, \ub458\uc9f8\ub294 \ubbf8\ub274\uc5d0\ud2b8, \ub9c8\uc9c0\ub9c9\uc774 \uc6b0\ub9ac\uac00 \ud589\uc9c4\uace1\uc73c\ub85c \ubd80\ub974\ub294 \ub860\ub3c4\ub2e4. \uc720\uba85\ud55c \ub9c8\uc9c0\ub9c9 \ubd80\ubd84\ub9cc \ub530\ub85c \uc5f0\uc8fc\ub418\uba74\uc11c \ud55c \uace1\uc758 \uc774\ub984\ucc98\ub7fc \uc775\uc219\ud574\uc84c\ub2e4. \uc791\ud488\ubc88\ud638 K.331\uc740 \ubaa8\ucc28\ub974\ud2b8\uc758 \uc74c\uc545\uc744 \uc815\ub9ac\ud55c \ubaa9\ub85d\uc758 \ubc88\ud638\ub2e4. \uccab \uc545\uc7a5\ubd80\ud130 \ub4e4\uc5b4 \ubcf4\uba74 \ub9c8\uc9c0\ub9c9\uc758 \uacbd\ucf8c\ud568\uc774 \uc55e\uc758 \uc74c\uc545\uacfc \uc5b4\ub5a4 \ub300\ube44\ub97c \uc774\ub8e8\ub294\uc9c0 \uc54c \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uc138 \uc545\uc7a5\uc744 \ubaa8\ub450 \ub4e4\uc5b4\uc57c\ub9cc \uc774 \uace1\uc744 \uc990\uae38 \uc790\uaca9\uc774 \uc0dd\uae30\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub9c8\uc9c0\ub9c9 \uc545\uc7a5\uc5d0\uc11c \uc2dc\uc791\ud574 \uc804\uccb4 \uc18c\ub098\ud0c0\ub85c \ub113\ud600 \uac00\ub3c4 \uc88b\ub2e4. \ub2f9\uc2dc \uc720\ub7fd \uc74c\uc545\uc5d0\ub294 \ud130\ud0a4\ud48d\uc744 \ub098\ud0c0\ub0b4\ub294 \ud45c\ud604\uc774 \uc0ac\uc6a9\ub418\uc5c8\ub2e4. \uad70\uc545\uc744 \uc5f0\uc0c1\uc2dc\ud0a4\ub294 \ud798 \uc788\ub294 \ubc15\uc790\uc640 \ud0c0\uc545\uae30 \uac19\uc740 \ud6a8\uacfc\uac00 \uadf8 \uc774\ubbf8\uc9c0\uc5d0 \ub4e4\uc5b4\uac04\ub2e4. \ubaa8\ucc28\ub974\ud2b8\uc758 \uc791\ud488\uc744 \ub2e4\ub8e8\ub294 \uc61b \uc804\uae30\ub3c4 \uc74c\uc545\uadf9\uc758 \ud130\ud0a4\ud48d \ub9ac\ub4ec\uacfc \uc74c\ud5a5\uc744 \uc124\uba85\ud558\uba74\uc11c \uadf8\uac83\uc774 \uc2e4\uc81c \ud130\ud0a4 \uc74c\uc545\uacfc \uaf2d \uac19\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub77c\uace0 \uc9da\ub294\ub2e4. \uadf8\ub7ec\ubbc0\ub85c \uc774 \uace1\uc744 \uc624\uc2a4\ub9cc \uc81c\uad6d\uc758 \uc0dd\ud65c\uacfc \uc74c\uc545\uc744 \uadf8\ub300\ub85c \uc62e\uae34 \uc18c\ub9ac \uae30\ub85d\ucc98\ub7fc \ub4e3\uc9c0\ub294 \ub9d0\uc790. \uc720\ub7fd\uc758 \uc791\uace1\uac00\uc640 \uccad\uc911\uc774 \uc790\uae30 \uc74c\uc545 \uc548\uc5d0\uc11c \ubc1b\uc544\ub4e4\uc778 \u2018\ud130\ud0a4\ud48d\u2019\uc774\ub77c\ub294 \uc591\uc2dd\uc73c\ub85c \ubcf4\ub294 \ud3b8\uc774 \uc801\uc808\ud558\ub2e4. \uc81c\ubaa9\uc5d0\ub294 \uc74c\uc545\uc758 \ud2b9\uc9d5\ubfd0 \uc544\ub2c8\ub77c \ub2e4\ub978 \ubb38\ud654\uac00 \uc5b4\ub5a4 \uc774\ubbf8\uc9c0\ub85c \uc804\ub2ec\ub418\uc5c8\ub294\uc9c0\uc5d0 \uad00\ud55c \uc5ed\uc0ac\ub3c4 \ub4e4\uc5b4 \uc788\ub2e4. \uccab \ubd80\ubd84\uc740 \uc57d\ud55c \uc18c\ub9ac\ub85c \uc9e7\uc740 \uc74c\ub4e4\uc774 \uc6c0\uc9c1\uc778\ub2e4. \ubc14\ub85c \ud070 \uad70\uc545\ub300\uac00 \ub4f1\uc7a5\ud558\ub294 \ub300\uc2e0 \uc791\uc740 \ud68c\uc804\uacfc \uc7ac\ube60\ub978 \uac78\uc74c \uac19\uc740 \ub290\ub08c\uc744 \uc900\ub2e4. \uc545\ubcf4\ub97c \ubcf4\uc9c0 \uc54a\uc544\ub3c4 \uc74c\ub4e4\uc774 \uac00\uae4c\uc6b4 \uacf3\uc744 \uc624\uac00\ub294\uc9c0, \uae38\uac8c \ub178\ub798\ud558\ub294\uc9c0 \uadc0\ub97c \uae30\uc6b8\uc77c \uc218 \uc788\ub2e4. \ud53c\uc544\ub178\uc758 \ub0ae\uc740 \ucabd\uc5d0\uc11c\ub294 \ubc15\uc790\ub97c \uc7a1\ub294 \ubc18\uc8fc\uac00 \uc774\uc5b4\uc9c4\ub2e4. \uc704\ucabd\uc758 \uac00\ubcbc\uc6b4 \uc6c0\uc9c1\uc784\uacfc \uc544\ub798\ucabd\uc758 \uac78\uc74c\uc744 \ub530\ub85c \ub4e4\uc5b4 \ubcf4\uc790. \uc120\uc728\ub9cc \ub530\ub77c \ud765\uc5bc\uac70\ub9ac\ub358 \uace1\uc5d0\uc11c\ub3c4 \uc11c\ub85c \ub2e4\ub978 \uc5ed\ud560\uc758 \uc18c\ub9ac\uac00 \uc788\ub2e4\ub294 \uac83\uc744 \uc54c\uc544\ucc28\ub9ac\uac8c \ub41c\ub2e4. \uc791\uc740 \uc7a5\uba74\uc774\uc9c0\ub9cc \uc774\ubbf8 \ud63c\uc790 \ub178\ub798\ud558\ub294 \uc74c\uc545 \uc774\uc0c1\uc73c\ub85c \uc9dc\uc5ec \uc788\ub2e4. \uace1\uc774 \uc9c4\ud589\ub418\uba74 \ubc1d\uace0 \ud798\ucc2c \ubd80\ubd84\uc774 \ub098\ud0c0\ub098\uace0 \ud654\uc74c\uacfc \ubc18\ubcf5\ub418\ub294 \uc74c\uc774 \ub354 \ub450\ub4dc\ub7ec\uc9c4\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \ubcf4\ud1b5 \ud589\uc9c4\uace1\uc758 \uc131\uaca9\uc744 \uac15\ud558\uac8c \ub290\ub07c\ub294 \ub300\ubaa9\uc774\ub2e4. \uc55e\uc758 \uac00\ubcbc\uc6b4 \uc6c0\uc9c1\uc784\uacfc \ub098\ub780\ud788 \ub4e4\uc73c\uba74 \uac19\uc740 \ube60\ub974\uae30 \uc548\uc5d0\uc11c\ub3c4 \ubb34\uac8c\uc640 \ud45c\uc815\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4\ub294 \uc810\uc774 \ubcf4\uc778\ub2e4. \uc5ec\uae30\uc11c \ud53c\uc544\ub178\ub294 \ubd81\uc774\ub098 \uc2ec\ubc8c\uc988\ub97c \uc2e4\uc81c\ub85c \ucd94\uac00\ud558\uc9c0 \uc54a\uace0\ub3c4 \ud0c0\uc545\uae30 \uac19\uc740 \ubd84\uba85\ud55c \ud0c0\uaca9\uac10\uc744 \ub9cc\ub4e4\uc5b4 \ub0bc \uc218 \uc788\ub2e4. \uc74c\uc744 \uc9e7\uac8c \uad6c\ubd84\ud558\uace0 \ud654\uc74c\uc744 \uac15\uc870\ud558\ub294 \ubc29\uc2dd\uc774 \ud6a8\uacfc\ub97c \ub0b8\ub2e4. \uc774 \uc18c\ub9ac\ub97c \ud2b9\uc815 \uad70\ub300\uc758 \uc2e4\uc81c \ud589\uc9c4 \uc7a5\uba74\uc73c\ub85c \ud655\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc545\uae30\uc758 \ud45c\ud604 \uac00\ub2a5\uc131\uc744 \ub4e3\ub294 \uae38\uc774\uae30\ub3c4 \ud558\ub2e4. \ub860\ub3c4\ub294 \uc911\uc694\ud55c \ubd80\ubd84\uc774 \ub2e4\ub978 \uad6c\uac04\uc744 \uc0ac\uc774\uc5d0 \ub450\uace0 \ub418\ub3cc\uc544\uc624\ub294 \ud615\uc2dd\uc744 \ub9d0\ud560 \ub54c \uc4f0\ub294 \uc774\ub984\uc774\ub2e4. \uc774 \uace1\uc5d0\uc11c\ub3c4 \uc775\uc219\ud55c \uc6c0\uc9c1\uc784\uc774 \ub3cc\uc544\uc624\uace0 \uc0c8\ub85c\uc6b4 \uc7a5\uba74\uc774 \ub07c\uc5b4\ub4e4\uba70 \uadc0\ub97c \ubd99\uc7a1\ub294\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uae00\uc790\ub85c \uc21c\uc11c\ub97c \uc678\uc6b0\uae30\ubcf4\ub2e4 \u2018\uc5ec\uae30 \ub2e4\uc2dc \ub098\uc654\ub124\u2019 \ud558\ub294 \uc21c\uac04\uc744 \ucc3e\uc73c\uba74 \ucda9\ubd84\ud558\ub2e4. \uac19\uc740 \ubd80\ubd84\uc774 \ub3cc\uc544\uc628\ub2e4\uace0 \uac10\uc0c1\uc774 \uc81c\uc790\ub9ac\ub9cc \ub3c4\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub2e4\ub978 \uc74c\uc0c9\uacfc \uac15\uc57d\uc744 \uc9c0\ub098 \ub2e4\uc2dc \ub9cc\ub098\ub294 \uc21c\uac04\uc740 \ucc98\uc74c\uacfc \ub2e4\ub974\uac8c \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \uc9d1 \uadfc\ucc98\uc758 \uc775\uc219\ud55c \uae38\ub3c4 \uba3c \uacf3\uc744 \ub2e4\ub140\uc628 \ub4a4\uc5d0\ub294 \uc870\uae08 \ub2e4\ub974\uac8c \ubcf4\uc774\ub294 \uac83\uacfc \ube44\uc2b7\ud558\ub2e4. \uc774\ub294 \uac10\uc0c1\uc744 \ub3d5\ub294 \ube44\uc720\uc774\uba70 \uc791\uace1\uac00\uac00 \uc815\ud574 \ub454 \uc774\uc57c\uae30\ub294 \uc544\ub2c8\ub2e4. \uc545\ubcf4\uc5d0\ub294 \ube60\ub974\uac8c \uc774\uc5b4\uc9c0\ub294 \uc74c\uacfc \uc190\uc758 \uc774\ub3d9, \uc9e7\uc740 \uac15\uc138\uc640 \ub300\ube44\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \uac00\ubccd\uac8c \ub4e4\ub9b0\ub2e4\uace0 \uc5f0\uc8fc\uc790\uc758 \uc190\uae4c\uc9c0 \ud3b8\uc548\ud558\uae30\ub9cc \ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc74c\ub4e4\uc774 \ubb49\uce58\uc9c0 \uc54a\ub3c4\ub85d \uc815\ub9ac\ud558\uba74\uc11c\ub3c4 \ubc15\uc790\uac00 \ub298\uc5b4\uc9c0\uc9c0 \uc54a\uc544\uc57c \uacbd\ucf8c\ud55c \uc778\uc0c1\uc774 \uc0b4\uc544\ub09c\ub2e4. \ub4e3\ub294 \uc0ac\ub78c\uc740 \uc5f0\uc8fc \uae30\uc220\uc744 \ud3c9\uac00\ud558\ub824 \uc560\uc4f0\uc9c0 \uc54a\uc544\ub3c4 \ub41c\ub2e4. \uc9e7\uc740 \uc74c\uc774 \uc5bc\ub9c8\ub098 \ub610\ub837\ud558\uac8c \uc774\uc5b4\uc9c0\ub294\uc9c0, \uac15\ud55c \ubd80\ubd84\uc73c\ub85c \ub118\uc5b4\uac08 \ub54c \ub9ac\ub4ec\uc774 \uc5b4\ub5bb\uac8c \ub290\uaef4\uc9c0\ub294\uc9c0\ub9cc \uc0b4\ud3b4\ubcf4\uc790. \uac19\uc740 \uace1\uc758 \uc5f0\uc8fc \ub450 \uac1c\ub97c \ube44\uad50\ud558\uba74 \uc18c\ub9ac\uc758 \ubb34\uac8c\uc640 \uc7a5\ub09c\uc2a4\ub7ec\uc6b4 \ub290\ub08c\uc774 \uaf64 \ub2e4\ub97c \uc218 \uc788\ub2e4. \ucc98\uc74c\uc758 \uc8fc\uc81c\uc640 \ubcc0\uc8fc\uc5d0\uc11c\ub294 \ud558\ub098\uc758 \ub178\ub798\uac00 \uc5ec\ub7ec \ubaa8\uc2b5\uc73c\ub85c \ubc14\ub00c\uace0, \ubbf8\ub274\uc5d0\ud2b8\uc5d0\uc11c\ub294 \ucda4\uc758 \uac78\uc74c\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \ub9c8\uc9c0\ub9c9 \ub860\ub3c4\ub294 \ub610 \ub2e4\ub978 \ubc29\uc2dd\uc758 \ud65c\uae30\ub97c \ub9cc\ub4e0\ub2e4. \ud55c \uc18c\ub098\ud0c0 \uc548\uc5d0 \ubcc0\ud615, \ucda4, \ubc18\ubcf5\uacfc \ub300\ube44\ub77c\ub294 \uc11c\ub85c \ub2e4\ub978 \uc7ac\ubbf8\uac00 \uc788\ub294 \uc148\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\uc740 \uac74\ubc18\uc744 \uc5f0\uc8fc\ud558\ub294 \uc190\uc758 \uc6c0\uc9c1\uc784\uc73c\ub85c \uace1\uc758 \uacbd\ucf8c\ud568\uc744 \ud45c\ud604\ud55c AI \uc0bd\ud654\ub2e4. \ubaa8\ucc28\ub974\ud2b8\uc758 \uc2e4\uc81c \uc5f0\uc8fc\ub098 \ub2f9\uc2dc \uad70\uc545\ub300\uc758 \ubaa8\uc2b5\uc744 \ubcf5\uc6d0\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uc720\uba85\ud55c \ud589\uc9c4\uace1\uc744 \uc804\uccb4 \uc791\ud488\uc758 \uc9c0\ub3c4\uc5d0 \ud55c \ubc88 \uc62c\ub824 \ubcf4\uba74, \uc774 \uace1 \uc55e\ub4a4\uc758 \uc74c\uc545\uc744 \ucc3e\ub294 \uc77c\ub3c4 \uc26c\uc6cc\uc9c4\ub2e4. \ud55c \ubc88\uc740 \uc775\uc219\ud55c \uba5c\ub85c\ub514\ub97c \ud3b8\ud558\uac8c \ub4e3\uace0, \ub2e4\uc74c\uc5d0\ub294 \uc57d\ud558\uac8c \uc2dc\uc791\ud558\ub294 \ubd80\ubd84\uacfc \ud798\ucc28\uac8c \ub098\uc11c\ub294 \ubd80\ubd84\uc758 \ucc28\uc774\ub97c \ub4e4\uc5b4 \ubcf4\uc790. \uadf8\ub2e4\uc74c \uc804\uccb4 \uc18c\ub098\ud0c0\ub85c \ub3cc\uc544\uac00\uba74 \ub9c8\uc9c0\ub9c9 \uc545\uc7a5\uc758 \uc131\uaca9\uc774 \ub354 \ub610\ub837\ud574\uc9c4\ub2e4. \uc54c\uac8c \ub41c \uc9c0\uc2dd\uc774 \uc74c\uc545\uc744 \ubc29\ud574\ud558\uae30\ubcf4\ub2e4 \uadc0\uac00 \uba38\ubb3c \uc790\ub9ac\ub97c \ub298\ub9ac\ub294 \ubc29\uc2dd\uc774\ub2e4. \u3008\ud130\ud0a4 \ud589\uc9c4\uace1\u3009\uc758 \uc81c\ubaa9\uc740 \ud130\ud0a4\uc758 \ubaa8\ub4e0 \uc74c\uc545\uc744 \ub300\ud45c\ud55c\ub2e4\ub294 \uc120\uc5b8\uc774 \uc544\ub2c8\ub2e4. \uc720\ub7fd \uc74c\uc545 \uc548\uc5d0\uc11c \ubc1b\uc544\ub4e4\uc778 \ud55c \uc591\uc2dd\uacfc \ud53c\uc544\ub178\uc758 \ud45c\ud604\uc744 \ub9cc\ub098\ub294 \uc791\uc740 \ubb38\uc774\ub2e4. \uadf8 \ucc28\uc774\ub97c \uc54c\uace0 \ub098\uba74 \uc775\uc219\ud55c \uace1\uc744 \uc990\uae30\uba74\uc11c\ub3c4, \ub2e4\ub978 \ubb38\ud654\uc758 \uc774\ub984\uc774 \uc74c\uc545 \uc18d\uc5d0\uc11c \uc5b4\ub5bb\uac8c \uc4f0\uc600\ub294\uc9c0 \ud568\uaed8 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4."}, {"id": "oz-wizard-road-and-home", "title": "\uc624\uc988\uc758 \ub9c8\ubc95\uc0ac \u2014 \ud544\uc694\ud55c \uac83\uc740 \uc774\ubbf8 \uae38 \uc704\uc5d0 \uc788\uc5c8\uc744\uae4c", "summary": "\uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc744 \ub530\ub77c\uac00\uba70 \uc9d1\uc73c\ub85c \ub3cc\uc544\uac00\ub294 \ubaa8\ud5d8\uacfc \ub3d9\ub8cc\ub4e4\uc758 \ubcc0\ud654\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Literature", "url": "stories/oz-wizard-road-and-home/index.html", "image": "media/oz-wizard-road-and-home.png", "alt": "\ub178\ub780 \ubcbd\ub3cc\uae38\uc744 \ud568\uaed8 \uac77\ub294 \ub3c4\ub85c\uc2dc\uc640 \ud1a0\ud1a0, \ud5c8\uc218\uc544\ube44, \uc591\ucca0 \ub098\ubb34\uafbc\uacfc \uc0ac\uc790\ub97c \uadf8\ub9b0 \uc0c1\uc0c1 \uc0bd\ud654.", "text": "\uc624\uc988\uc758 \ub9c8\ubc95\uc0ac \u2014 \ud544\uc694\ud55c \uac83\uc740 \uc774\ubbf8 \uae38 \uc704\uc5d0 \uc788\uc5c8\uc744\uae4c \ub3c4\ub85c\uc2dc\uc640 \uc138 \ub3d9\ub8cc\uac00 \ucc3e\uc544 \ub098\uc120 \uc9c0\ud61c\uc640 \ub9c8\uc74c, \uc6a9\uae30 \uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc744 \ub530\ub77c\uac00\uba70 \uc9d1\uc73c\ub85c \ub3cc\uc544\uac00\ub294 \ubaa8\ud5d8\uacfc \ub3d9\ub8cc\ub4e4\uc758 \ubcc0\ud654\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Literature \ubb38\ud654 \uc9d1\uc774 \ud1b5\uc9f8\ub85c \ubc14\ub78c\uc5d0 \uc2e4\ub824 \ub0af\uc120 \ub098\ub77c\uc5d0 \ub0b4\ub824\uc549\ub294\ub2e4. \uce94\uc790\uc2a4\uc5d0\uc11c \uc0b4\ub358 \ub3c4\ub85c\uc2dc\uc5d0\uac8c \ud544\uc694\ud55c \uac83\uc740 \uac70\ub300\ud55c \ud798\uc774\ub098 \uc655\uad00\uc774 \uc544\ub2c8\ub2e4. \uc775\uc219\ud55c \uc9d1\uc73c\ub85c \ub3cc\uc544\uac00\ub294 \uae38\uc774\ub2e4. \uadf8\ub7f0\ub370 \uadf8 \uae38\uc5d0\uc11c \ub9cc\ub09c \ub3d9\ub8cc\ub4e4\uc740 \uc800\ub9c8\ub2e4 \uc790\uc2e0\uc5d0\uac8c \uaf2d \uc5c6\ub294 \uac83\uc774 \ud558\ub098\uc529 \uc788\ub2e4\uace0 \ub9d0\ud55c\ub2e4. L. \ud504\ub7ad\ud06c \ubc14\uc6c0\uc758 \u300e\uc624\uc988\uc758 \ub9c8\ubc95\uc0ac\u300f\ub294 1900\ub144 \uc11c\ubb38\uc744 \uac00\uc9c4 \ubaa8\ud5d8 \uc774\uc57c\uae30\ub2e4. \uc5b4\ub9b0\uc774\ub97c \uc704\ud55c \uc791\ud488\uc774\uc9c0\ub9cc \uc5b4\ub978\uc774 \uc77d\uc5b4\ub3c4 \ub0a8\ub294 \uc9c8\ubb38\uc774 \uc788\ub2e4. \ub0b4\uac00 \uc5c6\ub2e4\uace0 \uc0dd\uac01\ud558\ub294 \ub2a5\ub825\uc744 \ub2e4\ub978 \uc0ac\ub78c\uc740 \uc774\ubbf8 \ub0b4 \ud589\ub3d9\uc5d0\uc11c \ubcf4\uace0 \uc788\ub294 \uac83\uc740 \uc544\ub2d0\uae4c. \uc544\ub798\uc5d0\ub294 \uc8fc\uc694 \uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc774 \ud3ec\ud568\ub418\uc5b4 \uc788\ub2e4. \ud68c\uc624\ub9ac\ubc14\ub78c\uc5d0 \ub0a0\ub824 \uc628 \uc9d1\uc740 \ub3d9\ucabd\uc758 \ub098\uc05c \ub9c8\ub140 \uc704\uc5d0 \ub5a8\uc5b4\uc9c4\ub2e4. \ub3c4\ub85c\uc2dc\ub294 \ub9c8\ub140\uc758 \uc740\uad6c\ub450\ub97c \uc5bb\uace0, \uc5d0\uba54\ub784\ub4dc \uc2dc\uc758 \uc704\ub300\ud55c \uc624\uc988\ub97c \ucc3e\uc544\uac00\uba74 \uc9d1\uc73c\ub85c \ub3cc\uc544\uac08 \ubc29\ubc95\uc744 \uc54c \uc218 \uc788\uc73c\ub9ac\ub77c\ub294 \ub9d0\uc744 \ub4e3\ub294\ub2e4. \ud1a0\ud1a0\uc640 \ud568\uaed8 \ub178\ub780 \ubcbd\ub3cc\uae38\uc744 \ub530\ub77c \ub098\uc11c\ub294 \uc774\uc720\ub2e4. \uc6d0\uc791\uc758 \uad6c\ub450\ub294 \uc740\uc0c9\uc774\ub2e4. \ub2e4\ub978 \uac01\uc0c9\uc5d0\uc11c \uc775\uc219\ud574\uc9c4 \ubaa8\uc2b5\uacfc \uad6c\ubcc4\ud558\uba74 \uc791\uc740 \ubb3c\uac74 \ud558\ub098\ub3c4 \uc0c8\ub86d\uac8c \ubcf4\uc778\ub2e4. \ub2e4\ub9cc \uc0c9\uc744 \uc678\uc6b0\ub294 \uac83\uc774 \uac10\uc0c1\uc758 \ubaa9\uc801\uc740 \uc544\ub2c8\ub2e4. \ub0af\uc120 \uc138\uacc4\uc5d0 \ub4e4\uc5b4\uc628 \uc18c\ub140\uac00 \ub3c4\uc6c0\uc744 \uad6c\ud558\uba70 \ud55c \uac78\uc74c\uc529 \uc6c0\uc9c1\uc774\uae30 \uc2dc\uc791\ud588\ub2e4\ub294 \uc810\uc774 \uc774\uc57c\uae30\uc758 \ucd9c\ubc1c\uc774\ub2e4. \ud5c8\uc218\uc544\ube44\ub294 \uc790\uc2e0\uc5d0\uac8c \ub1cc\uac00 \uc5c6\uc5b4\uc11c \uc9c0\ud61c\ub86d\uc9c0 \ubabb\ud558\ub2e4\uace0 \uc0dd\uac01\ud55c\ub2e4. \uc624\uc988\uc5d0\uac8c \ub1cc\ub97c \ub2ec\ub77c\uace0 \uccad\ud558\ub824\uace0 \ub3c4\ub85c\uc2dc\uc640 \ub3d9\ud589\ud55c\ub2e4. \uadf8\ub7ec\ub098 \uae38\uc5d0\uc11c \uc704\ud5d8\uc744 \ud53c\ud558\uace0 \ubb38\uc81c\ub97c \ud480\uc5b4\uc57c \ud560 \ub54c \uadf8\ub294 \uc5ec\ub7ec \uc0dd\uac01\uc744 \ub0b4\ub193\ub294\ub2e4. \uc2a4\uc2a4\ub85c\uc758 \ud3c9\uac00\uc640 \uc2e4\uc81c \ud589\ub3d9 \uc0ac\uc774\uc5d0 \ud2c8\uc774 \uc0dd\uae34\ub2e4. \uc791\ud488\uc740 \u2018\uc0ac\uc2e4\uc740 \ub611\ub611\ud588\ub2e4\u2019\uace0 \uc124\uba85\ud558\uace0 \uace7\ubc14\ub85c \ub05d\ub0b4\uc9c0 \uc54a\ub294\ub2e4. \ub3c5\uc790\uac00 \ud5c8\uc218\uc544\ube44\uc758 \ub9d0\uc744 \ub4e3\uace0, \uc774\uc5b4\uc9c0\ub294 \ud589\ub3d9\uc744 \uc5ec\ub7ec \ubc88 \ubcf4\uac8c \ud55c\ub2e4. \ub204\uad70\uac00\ub97c \uc774\ud574\ud558\ub294 \ub370\uc5d0\ub294 \uadf8 \uc0ac\ub78c\uc774 \uc790\uae30\uc18c\uac1c\uc5d0\uc11c \ub9d0\ud55c \ubd80\uc871\ud568\ubfd0 \uc544\ub2c8\ub77c \uc2e4\uc81c\ub85c \uc5b4\ub5bb\uac8c \ubb38\uc81c\ub97c \ub300\ud558\ub294\uc9c0\ub3c4 \uc911\uc694\ud558\ub2e4\ub294 \uc77d\uae30\uac00 \uac00\ub2a5\ud574\uc9c4\ub2e4. \uc591\ucca0 \ub098\ubb34\uafbc\uc740 \uc2ec\uc7a5\uc744 \uc6d0\ud55c\ub2e4. \uc790\uc2e0\uc5d0\uac8c \ub530\ub73b\ud55c \ub9c8\uc74c\uc774 \uc5c6\ub2e4\uace0 \ub290\ub07c\uae30 \ub54c\ubb38\uc774\ub2e4. \uadf8\ub7f0\ub370 \uadf8\ub294 \ub2e4\ub978 \uc0dd\uba85\uc744 \uac71\uc815\ud558\uace0 \ub0a8\uc5d0\uac8c \ud574\ub97c \ub07c\uce60\uae4c \uc870\uc2ec\ud55c\ub2e4. \ubab8\uc774 \uc591\ucca0\ub85c \ub418\uc5b4 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ud0c0\uc778\uc744 \ub300\ud558\ub294 \ud0dc\ub3c4\ub294 \uac19\uc740 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc2ec\uc7a5\uc740 \ubab8\uc18d\uc758 \ubb3c\uac74\uc774\uba74\uc11c \uc0ac\ub791\ud558\uace0 \ub3cc\ubcfc \uc218 \uc788\ub2e4\ub294 \ud655\uc2e0\uc758 \uc0c1\uc9d5\ucc98\ub7fc \uc77d\ud78c\ub2e4. \ud5c8\uc218\uc544\ube44\uac00 \ub1cc\ub97c \ubc14\ub77c\ub294 \uac83\uacfc \ub098\ub780\ud788 \ubcf4\uba74 \ub3d9\ub8cc\ub4e4\uc758 \uc18c\ub9dd\uc774 \uc11c\ub85c \ub2e4\ub978 \uc9c8\ubb38\uc744 \uaebc\ub0b8\ub2e4. \ubb34\uc5c7\uc744 \uac00\uc84c\ub2e4\ub294 \uc99d\uba85\uacfc \uc2e4\uc81c\ub85c \uadf8\ub807\uac8c \uc0b4\uc544\uac00\ub294 \uc77c\uc740 \uc5b4\ub5a4 \uad00\uacc4\uc5d0 \uc788\uc744\uae4c. \uc0ac\uc790\ub294 \uc790\uc2e0\uc774 \uac81\uc7c1\uc774\ub77c\uace0 \ub9d0\ud55c\ub2e4. \uac15\ud55c \ubab8\uacfc \ud070 \ubaa9\uc18c\ub9ac\uac00 \uc788\uc73c\ub2c8 \ub450\ub824\uc6c0\ub3c4 \uc5c6\uc5b4\uc57c \ud55c\ub2e4\uace0 \uae30\ub300\ud558\uc9c0\ub9cc \uc2e4\uc81c\ub85c\ub294 \uadf8\ub807\uc9c0 \uc54a\ub2e4. \uadf8\ub294 \uc624\uc988\uc5d0\uac8c \uc6a9\uae30\ub97c \uc5bb\uace0 \uc2f6\uc5b4 \ud55c\ub2e4. \uc790\uae30\uc5d0\uac8c \ubaa8\uc790\ub780 \uac83\uc744 \ub2e4\ub978 \uc874\uc7ac\uac00 \ucc44\uc6cc \uc904 \uc218 \uc788\ub2e4\uace0 \ubbff\ub294 \uc148\uc774\ub2e4. \uc5ec\ud589\uc774 \uc774\uc5b4\uc9c0\uba74 \uc0ac\uc790\ub294 \ub450\ub824\uc6c0\uc744 \ub290\ub07c\uba74\uc11c\ub3c4 \ub3d9\ub8cc\ub4e4\uc744 \uc704\ud574 \ud589\ub3d9\ud55c\ub2e4. \uadf8\ub798\uc11c \uc6a9\uae30\ub294 \uc544\ubb34\uac83\ub3c4 \ubb34\uc12d\uc9c0 \uc54a\uc740 \uc0c1\ud0dc\ub9cc\uc744 \ub73b\ud558\ub294\uc9c0 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \uc774 \uc5ed\uc2dc \uc791\ud488\uc774 \ud604\ub300\uc758 \uc2ec\ub9ac\ud559 \uc774\ub860\uc744 \uc124\uba85\ud558\ub824 \uc37c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc778\ubb3c\uc758 \ub9d0\uacfc \ud589\ub3d9\uc744 \ube44\uad50\ud558\uba70 \uc5bb\uc744 \uc218 \uc788\ub294 \uac10\uc0c1\uc758 \ud55c \ubc29\ud5a5\uc774\ub2e4. \uc5d0\uba54\ub784\ub4dc \uc2dc\uc5d0 \ub3c4\ucc29\ud574\ub3c4 \uc18c\uc6d0\uc740 \ubc14\ub85c \uc774\ub8e8\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \uc624\uc988\ub294 \uc11c\ucabd\uc758 \ub098\uc05c \ub9c8\ub140\ub97c \ubb3c\ub9ac\uce58\ub77c\ub294 \uc870\uac74\uc744 \ub0b4\uac74\ub2e4. \ub3c4\uc6c0\uc744 \ubc1b\uc73c\ub824\uba74 \uc774\ubbf8 \ub450\ub824\uc6cc\ud558\ub358 \uc77c\uc744 \ud574\ub0b4\uc57c \ud558\ub294 \uc0c1\ud669\uc774\ub2e4. \uac89\uc73c\ub85c\ub294 \ud798\uc5c6\ub294 \uc0ac\ub78c\ub4e4\uc774 \uac70\ub300\ud55c \uad8c\uc704\ub97c \ucc3e\uc544\uac14\uc9c0\ub9cc, \uc2e4\uc81c\ub85c \uae38 \uc704\uc5d0\uc11c \uc704\ud5d8\uc744 \uac10\ub2f9\ud558\ub294 \uac83\uc740 \uc774 \ub3d9\ub8cc\ub4e4\uc774\ub2e4. \uc11c\ucabd \ub9c8\ub140\uc758 \uc190\uc5d0 \ubd99\uc7a1\ud78c \ub4a4 \ub3c4\ub85c\uc2dc\ub294 \ub73b\ubc16\uc758 \ubc29\uc2dd\uc73c\ub85c \ubc97\uc5b4\ub09c\ub2e4. \ubb3c\uc774 \ub9c8\ub140\ub97c \ub179\uc774\ub294 \uacb0\ub9d0\uc774\ub2e4. \uc774\ub97c \uce58\ubc00\ud558\uac8c \uacc4\ud68d\ud55c \uc601\uc6c5\uc758 \uc2b9\ub9ac\ub77c\uace0\ub9cc \uc77d\uae30\ubcf4\ub2e4, \ub0af\uc120 \uc138\uacc4\uc5d0\uc11c \ubab0\ub790\ub358 \uc870\uac74\uc744 \uacbd\ud5d8\ud558\uba70 \uae38\uc774 \uc5f4\ub9ac\ub294 \ubaa8\ud5d8\uc758 \uc131\uaca9\uc73c\ub85c \ubcfc \uc218 \uc788\ub2e4. \ub3cc\uc544\uc628 \ub3d9\ub8cc\ub4e4\uc740 \uc624\uc988\uc758 \uc815\uccb4\ub97c \uc54c\uac8c \ub41c\ub2e4. \ubb34\uc11c\uc6b4 \ubaa8\uc2b5\uacfc \uac70\ub300\ud55c \uad8c\uc704 \ub4a4\uc5d0 \uc788\uc5c8\ub358 \uac83\uc740 \uc0ac\ub78c\ub4e4\uc774 \uae30\ub300\ud55c \ucd08\uc6d4\uc801 \uc874\uc7ac\uc640 \ub2e4\ub978 \ud3c9\ubc94\ud55c \uc0ac\ub78c\uc774\uc5c8\ub2e4. \uadf8\uac00 \ubcf4\uc5ec \uc900 \uc704\uc5c4\uacfc \uc2e4\uc81c \ub2a5\ub825\uc758 \uac04\uaca9\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \ud558\uc9c0\ub9cc \uc774 \uc7a5\uba74\uc774 \ubaa8\ub4e0 \ub3c4\uc6c0\uc740 \uac70\uc9d3\uc774\ub77c\ub294 \uacb0\ub860\uc73c\ub85c\ub9cc \uc774\uc5b4\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud5c8\uc218\uc544\ube44\uc640 \ub098\ubb34\uafbc, \uc0ac\uc790\uc5d0\uac8c \uc8fc\ub294 \ubb3c\uac74\uacfc \ub9d0\uc740 \uadf8\ub4e4\uc774 \uc790\uc2e0\uc744 \ubc14\ub77c\ubcf4\ub294 \ubc29\uc2dd\uc744 \ubc14\uafb8\uae30\ub3c4 \ud55c\ub2e4. \uc774\ubbf8 \ud589\ub3d9\uc73c\ub85c \ubcf4\uc5ec \uc900 \ub2a5\ub825\uc744 \uc2a4\uc2a4\ub85c \uc778\uc815\ud558\ub824\uba74 \uc5b4\ub5a4 \uacc4\uae30\uac00 \ud544\uc694\ud55c\uac00\ub77c\ub294 \uc9c8\ubb38\uc774 \ub0a8\ub294\ub2e4. \uc624\uc988\uac00 \uc900\ube44\ud55c \uae30\uad6c\ub85c \ud568\uaed8 \ub5a0\ub098\ub824\ub358 \uacc4\ud68d\uc740 \uc5b4\uae0b\ub098\uace0, \ub3c4\ub85c\uc2dc\ub294 \ub2e4\uc2dc \uae38\uc744 \ucc3e\uc544\uc57c \ud55c\ub2e4. \ub05d\ub0b4 \uae00\ub9b0\ub2e4\ub97c \ub9cc\ub098 \uc740\uad6c\ub450\uac00 \uac00\uc9c4 \ud798\uc744 \uc54c\uac8c \ub41c\ub2e4. \uc9d1\uc73c\ub85c \ub3cc\uc544\uac08 \uc218 \uc788\ub294 \ubb3c\uac74\uc740 \uc0dd\uac01\ubcf4\ub2e4 \uc77c\ucc0d\ubd80\ud130 \uacc1\uc5d0 \uc788\uc5c8\uc9c0\ub9cc \uadf8 \uc0ac\uc2e4\uc744 \uc54c\uae30\uae4c\uc9c0 \uae34 \uc5ec\ud589\uc774 \ud544\uc694\ud588\ub2e4. \uc774\uac83\uc744 \ubaa8\ud5d8 \uc804\uccb4\uac00 \uc4f8\ub370\uc5c6\uc5c8\ub2e4\ub294 \ub73b\uc73c\ub85c \uc77d\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5ec\ud589\ud558\ub294 \ub3d9\uc548 \ub3d9\ub8cc\ub4e4\uc774 \uc0dd\uae30\uace0 \uac01\uc790\uc758 \ubaa8\uc2b5\uc744 \ubcf4\uac8c \ub41c\ub2e4. \uc6d0\ud558\ub294 \uacb0\uacfc\uc5d0 \uac00\uc7a5 \ube68\ub9ac \ub3c4\ucc29\ud558\ub294 \uae38\uacfc, \uadf8 \uc0ac\uc774 \uc0ac\ub78c\uc744 \ub9cc\ub098\uace0 \ub2ec\ub77c\uc9c0\ub294 \uc2dc\uac04\uc740 \uc11c\ub85c \ub2e4\ub978 \uac00\uce58\ub97c \uac00\uc9c8 \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 \ub3c4\ub85c\uc2dc\uc640 \ud1a0\ud1a0, \uc138 \ub3d9\ub8cc\uac00 \uae38\uc744 \uac77\ub294 \ubaa8\uc2b5\uc744 \uc0c8\ub85c \uc0c1\uc0c1\ud55c AI \uc0bd\ud654\ub2e4. \uc6d0\uc791\uc5d0 \uc2e4\ub9b0 \uc61b \uadf8\ub9bc\uc774\ub098 \ud2b9\uc815 \uc601\ud654\uc758 \uc7a5\uba74\uc744 \ubcf5\uc81c\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uc774\ub4e4\uc774 \ud568\uaed8 \uc6c0\uc9c1\uc774\ub294 \ubaa8\uc2b5\uc774 \uae00\ub85c \ub4e4\uc5b4\uac00\ub294 \uc785\uad6c\uac00 \ub418\ub3c4\ub85d \ub9cc\ub4e4\uc5c8\ub2e4. \uc791\ud488\uc744 \uc77d\uace0 \ub098\uba74 \ub204\uac00 \uac00\uc7a5 \uac15\ud588\ub294\uc9c0 \uace0\ub974\ub294 \ub300\uc2e0 \uac01\uc790\uac00 \uc5b4\ub5a4 \uc21c\uac04\uc5d0 \ub2e4\ub978 \uc774\ub97c \ub3c4\uc654\ub294\uc9c0 \ub5a0\uc62c\ub824 \ubcf4\uc790. \ub1cc\uc640 \uc2ec\uc7a5, \uc6a9\uae30\ub77c\ub294 \uc18c\ub9dd\uc740 \uacb0\uad6d \uae38 \uc704\uc758 \uad6c\uccb4\uc801\uc778 \ud589\ub3d9\uacfc \uc774\uc5b4\uc9c4\ub2e4. \uc9d1\uc73c\ub85c \ub3cc\uc544\uac00\ub294 \uc774\uc57c\uae30 \uc548\uc5d0, \uc790\uc2e0\uc744 \uc870\uae08 \ub2e4\ub974\uac8c \ubcf4\uac8c \ub418\ub294 \uc774\uc57c\uae30\ub3c4 \ud568\uaed8 \ub193\uc5ec \uc788\ub2e4."}, {"id": "poem-plaque-raised-letters", "title": "\uc774 \ud604\ud310\uc758 \uae00\uc790\ub294 \ub530\ub85c \ub9cc\ub4e4\uc5b4 \ubd99\uc600\ub2e4", "summary": "\uc2dc \ud55c \ud3b8\uacfc \uc785\uccb4\uc801\uc778 \uae00\uc790\uac00 \ud568\uaed8 \ub0a8\uc740 \ud604\ud310\uc744 \ubd05\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Literature", "url": "stories/poem-plaque-raised-letters/index.html", "image": "media/poem-plaque-raised-letters.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \ubc30\ub9bc\ucd98\ubc29\uacbd\ucc28\uc5b4\uc81c \ud604\ud310 \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc774 \ud604\ud310\uc758 \uae00\uc790\ub294 \ub530\ub85c \ub9cc\ub4e4\uc5b4 \ubd99\uc600\ub2e4 \uc138\uc790\uac00 \ub2f5\ud55c \uc2dc\uac00 \ub098\ubb34\ud310\uc5d0 \ub0a8\ub294 \uacfc\uc815 \uc2dc \ud55c \ud3b8\uacfc \uc785\uccb4\uc801\uc778 \uae00\uc790\uac00 \ud568\uaed8 \ub0a8\uc740 \ud604\ud310\uc744 \ubd05\ub2c8\ub2e4. Literature \ubb38\ud654 \ud604\ud310\uc774\ub77c\uace0 \ud558\uba74 \uac74\ubb3c \uc774\ub984\uc774 \ud06c\uac8c \uc801\ud78c \ud310\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \uadf8\ub7f0\ub370 \uc774 \ud604\ud310\uc5d0\ub294 \uc5ec\ub7ec \uc904\uc758 \uae00\uc774 \ub2f4\uaca8 \uc788\ub2e4. \uc774\ub984\ud45c\ub77c\uae30\ubcf4\ub2e4 \ubcbd\uc5d0 \uac78\uc5b4 \ub450\ub294 \ud55c \ud3b8\uc758 \uc2dc\uc5d0 \uac00\uae5d\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \ubc30\ub9bc\ucd98\ubc29\uacbd\ucc28\uc5b4\uc81c \ud604\ud310\uc774\ub2e4. \uc81c\ubaa9\uc740 \uae38\uace0 \ub0af\uc124\uc9c0\ub9cc \uadf8 \uc548\uc758 \uc0c1\ud669\uc740 \uc870\uae08 \uce5c\uc219\ud558\ub2e4. \ub204\uad70\uac00 \uba3c\uc800 \uc2dc\ub97c \uc9c0\uc5c8\uace0 \ub2e4\ub978 \uc0ac\ub78c\uc774 \uadf8 \uc2dc\uc5d0 \ub2f5\ud588\ub2e4. \ubc15\ubb3c\uad00\uc5d0 \ub530\ub974\uba74 1886\ub144 3\uc6d4 15\uc77c \uace0\uc885\uc740 \uc138\uc790\uac00 \uacf5\ubd80\ud558\ub294 \uc790\ub9ac\uc5d0 \ub098\uc544\uac14\ub2e4. \uae30\uc05c \ub9c8\uc74c\uc5d0 \uad00\uc6d0\ub4e4\uc5d0\uac8c \uc220\uc744 \ub0b4\ub9ac\uace0 \uc2dc\ub97c \uc9c0\uc5c8\uc73c\uba70, \uc655\uc138\uc790\ub294 \uadf8 \uc2dc\uc5d0 \ud654\ub2f5\ud588\ub2e4. \ud6d7\ub0a0 \uc21c\uc885\uc774 \ub418\ub294 \uc138\uc790\ub2e4. \uc774 \ud604\ud310\uc5d0\ub294 \uadf8 \ub2f5\uc2dc\uac00 \uc0c8\uaca8\uc838 \uc788\ub2e4. \uae34 \uad00\uc9c1\uba85\uc774\ub098 \uc5b4\ub824\uc6b4 \uc758\ub840 \uc808\ucc28\ub97c \uba3c\uc800 \uc54c\uc544\uc57c\ub9cc \ubcf4\ub294 \ubb3c\uac74\uc740 \uc544\ub2c8\ub2e4. \ub204\uad70\uac00\uc758 \uae00\uc5d0 \ub2e4\ub978 \uae00\ub85c \uc751\ub2f5\ud55c \uc7a5\uba74\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uba74 \uc2dc\uc791\uc774 \ud55c\uacb0 \uac00\ubcbc\uc6cc\uc9c4\ub2e4. \ubc15\ubb3c\uad00\uc740 \uac19\uc740 \ub0b4\uc6a9\uc774 \uc21c\uc885\uc758 \ubb38\uc9d1\uc778 \uc815\ud5cc\uc9d1\uc5d0\ub3c4 \uae30\ub85d\ub418\uc5b4 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uae00\uc740 \ucc45 \uc548\uc5d0\ub3c4 \ub0a8\uc558\uace0, \ud604\ud310\uc774\ub77c\ub294 \ubb3c\uac74\uc5d0\ub3c4 \ub0a8\uc558\ub2e4. \uac19\uc740 \ubb38\uc7a5\uc774 \uba38\ubb34\ub294 \uc790\ub9ac\uac00 \ub2ec\ub77c\uc9c0\ub294 \uac83\uc774\ub2e4. \ucc45\uc5d0\uc11c\ub294 \ud398\uc774\uc9c0\ub97c \ub118\uaca8 \uc77d\uc9c0\ub9cc \ud604\ud310\uc740 \uacf5\uac04\uc5d0 \uac78\uc5b4 \ub454\ub2e4. \uadf8\ub798\uc11c \uc2dc\ub97c \uae30\uc5b5\ud558\ub294 \ubc29\uc2dd\ub3c4 \ub2e4\ub974\uac8c \uc0c1\uc0c1\ud560 \uc218 \uc788\ub2e4. \ubb3c\ub860 \uc2e4\uc81c\ub85c \ub204\uac00 \uc774 \uc55e\uc5d0\uc11c \uc2dc\ub97c \uc77d\uc5c8\ub294\uc9c0\ub294 \uc774 \ubb3c\uac74\ub9cc \ubcf4\uace0 \uc815\ud560 \uc218 \uc5c6\ub2e4. \ud654\ub2f5\uc740 \uc55e\uc120 \uae00\uc5d0 \ub2e4\ub978 \uae00\ub85c \uc751\ub2f5\ud558\ub294 \uc77c\uc774\ub2e4. \uace0\uc885\uc774 \uacf5\ubd80\ud558\ub294 \uc138\uc790\ub97c \ucc3e\uc544\uc640 \uc9c0\uc740 \uc2dc\uc640 \uc138\uc790\uc758 \ub2f5\uc2dc\ub97c \ud568\uaed8 \ub5a0\uc62c\ub9ac\uba74 \uc774 \ud604\ud310\uc740 \ud63c\uc790 \ub2eb\ud78c \ubb38\uc7a5\uc774 \uc544\ub2c8\uac8c \ub41c\ub2e4. \uae00\uc744 \uc8fc\uace0\ubc1b\uc740 \uad00\uacc4\uc640 \ud2b9\uc815\ud55c \ub0a0\uc758 \uc0c1\ud669\uc774 \uc791\ud488\uc758 \ubc30\uacbd\uc5d0 \uc788\ub2e4. \uae00\uc528\ub97c \ub2e4 \uc77d\uc9c0 \ubabb\ud574\ub3c4 \ub204\uad70\uac00\uc758 \ub9d0\uc5d0 \ub2e4\uc2dc \ub9d0\uc744 \uac74\ub128 \uc7a5\uba74\uc774\ub77c\ub294 \ud2c0\uc740 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uc655\uacfc \uc138\uc790\ub77c\ub294 \uc9c0\uc704\ub3c4 \ub2e8\uc21c\ud55c \uac00\uc871\uc758 \ub300\ud654\uc640 \ub2e4\ub978 \ubb38\ub9e5\uc744 \ub9cc\ub4e0\ub2e4. \ud559\uc2b5\uc758 \uc790\ub9ac\uc640 \uad00\uc6d0\ub4e4\uc774 \ud568\uaed8 \uc788\ub294 \uc0c1\ud669\uc5d0\uc11c \uc2dc\uac00 \uc9c0\uc5b4\uc84c\ub2e4\ub294 \uae30\ub85d\uc774 \ub0a8\uc544 \uc788\ub2e4. \ub2e4\ub9cc \uadf8 \uc790\ub9ac\uc5d0 \uc788\ub358 \uc0ac\ub78c\ub4e4\uc758 \uc2e4\uc81c \ud45c\uc815\uacfc \ub300\uc0ac\ub97c \uc0c1\uc0c1\uc73c\ub85c \ucc44\uc6cc \ub123\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub0a8\uc740 \ub0a0\uc9dc\uc640 \ud589\ub3d9\uc744 \ub530\ub77c\uac00\uba74 \uae30\ub150\ud560 \uc77c\uc744 \uae00\ub85c \uc62e\uae30\ub294 \ub2f9\uc2dc\uc758 \uc120\ud0dd\uc774 \ubcf4\uc778\ub2e4. \uc774 \ud604\ud310\uc740 \ub098\ubb34 \uae00\uc790\ub97c \ub530\ub85c \uc870\uac01\ud574 \ud310\uc5d0 \ubd99\uc778 \ubc29\uc2dd\uc774\ub77c\uace0 \ubc15\ubb3c\uad00\uc740 \uc124\uba85\ud55c\ub2e4. \ud3c9\ud3c9\ud55c \uba74\uc744 \uba39\uc73c\ub85c \ucc44\uc6b0\uac70\ub098 \ubc14\ud0d5\uc744 \ud30c\ub0b4\ub294 \uac83\uacfc \uc81c\uc791 \uacfc\uc815\uc774 \ub2e4\ub974\ub2e4. \uae00\uc790\uc758 \ubaa8\uc591\uc744 \uac1c\ubcc4 \ubd80\ud488\uc73c\ub85c \ub9cc\ub4e4\uc5b4 \uc790\ub9ac\ub97c \ub9de\ucd94\ub294 \uc77c\uc774 \ud544\uc694\ud588\ub2e4. \uc644\uc131\ub41c \ubb38\uc7a5\uc744 \uc77d\uc744 \ub54c\uc5d0\ub294 \uc798 \ub4dc\ub7ec\ub098\uc9c0 \uc54a\ub294 \uc870\ub9bd\uc758 \uc2dc\uac04\uc774 \uc788\ub294 \uac83\uc774\ub2e4. \ubd99\uc778 \uae00\uc790\ub294 \uba74\uc5d0\uc11c \ub192\uc774\uac00 \uc0dd\uae34\ub2e4. \uadf8\ub798\uc11c \uae00\uc528\ub294 \ub73b\uc744 \uc804\ud558\ub294 \ud45c\uc9c0\uc774\uba74\uc11c \ub450\uaed8\uc640 \uadf8\ub9bc\uc790\ub97c \uac00\uc9c4 \ud615\uc0c1\uc774\uae30\ub3c4 \ud558\ub2e4. \uc2e4\uc81c \uc0ac\uc9c4\uc5d0\uc11c\ub294 \uc815\uba74\ubfd0 \uc544\ub2c8\ub77c \uac00\uc7a5\uc790\ub9ac\uc640 \uae00\uc790 \uc8fc\ubcc0\uc744 \uc0b4\ud3b4\ubcf4\uba74 \uadf8 \uad6c\uc870\ub97c \uc0dd\uac01\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ub2e4\ub9cc \uc0ac\uc9c4\uc758 \ube5b\ub9cc\uc73c\ub85c \uc815\ud655\ud55c \ub450\uaed8\ub098 \uc811\ucc29 \ubc29\uc2dd\uc744 \uc0c8\ub85c \ud310\uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc81c\uc791 \ubc29\uc2dd\uc740 \ubc15\ubb3c\uad00 \uc124\uba85\uc744 \uadfc\uac70\ub85c \uc77d\ub294\ub2e4. \uc815\ud5cc\uc9d1 \uc548\uc758 \uac19\uc740 \uc2dc\ub294 \uc800\uc220\uc758 \ud750\ub984 \uc18d\uc5d0 \ub193\uc778\ub2e4. \ud604\ud310\uc740 \ud55c \uacf5\uac04\uc5d0 \uac78\uc5b4 \uadf8 \ubb38\uc7a5\uc744 \uacc4\uc18d \ubcf4\uc774\uac8c \ud55c\ub2e4. \ub0b4\uc6a9\uc774 \uac19\uc544\ub3c4 \ud398\uc774\uc9c0\ub97c \ub118\uaca8 \ub9cc\ub098\ub294 \ubc29\uc2dd\uacfc \uace0\uac1c\ub97c \ub4e4\uc5b4 \ub9c8\uc8fc\ud558\ub294 \ubc29\uc2dd\uc740 \ub2e4\ub974\ub2e4. \uc5b4\ub290 \uac83\uc774 \ub354 \uc9c4\uc9dc \uae30\ub85d\uc778\uc9c0 \uace0\ub974\uae30\ubcf4\ub2e4 \uc11c\ub85c \ub2e4\ub978 \ud615\ud0dc\uac00 \ubb34\uc5c7\uc744 \ub0a8\uae30\ub294\uc9c0 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \uacf5\uac04\uc5d0 \ub193\uc774\ub294 \uae00\uc740 \uc0ac\ub78c\ub4e4\uc758 \uc774\ub3d9\uacfc \uc2dc\uc120\uc758 \ub192\uc774\ub3c4 \ub9cc\ub098\uac8c \ub41c\ub2e4. \ub2e4\ub9cc \uc774 \uc720\ubb3c\ub9cc\uc73c\ub85c \uc6d0\ub798 \uac78\ub838\ub358 \ubaa8\ub4e0 \uc704\uce58\uc640 \uad00\ub78c \uc0c1\ud669\uc744 \uc54c \uc218\ub294 \uc5c6\ub2e4. \uc5ec\uae30\uc11c\ub294 \ubb38\uc7a5\uc744 \ub098\ubb34 \uae00\uc790\ub85c \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \uad6c\uccb4\uc801\uc778 \ubb3c\uc131\uc744 \uba3c\uc800 \ubcf8\ub2e4. \ubb38\ud559\uc774 \uc885\uc774\uc758 \ud398\uc774\uc9c0 \ubc16\uc73c\ub85c \ub098\uac00 \uac74\ucd95\uacfc \uc7a5\uc2dd\uc758 \uc77c\ubd80\uac00 \ub420 \uc218\ub3c4 \uc788\uc5c8\ub2e4\ub294 \uc810\uc774 \uac00\uae4c\uc6cc\uc9c4\ub2e4. \ud55c\uc790\ub97c \ubaa8\ub450 \ud574\ub3c5\ud558\uc9c0 \ubabb\ud558\uba74 \uc720\ubb3c \uc55e\uc5d0\uc11c \ud560 \uc77c\uc774 \uc5c6\ub2e4\uace0 \ub290\ub07c\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \uae00\uc790\ub97c \ubd99\uc778 \uad6c\uc870\uc640 \ubb38\uc7a5 \uc904\uc758 \ubc30\uc5f4, \uc81c\ubaa9\uacfc \uc124\uba85\uc758 \uad00\uacc4\ub97c \uba3c\uc800 \ubcfc \uc218 \uc788\ub2e4. \ubc15\ubb3c\uad00\uc758 \ubc88\uc5ed\uacfc \ud574\uc124\uc744 \uacc1\ub4e4\uc774\uba74 \ub0b4\uc6a9\uc73c\ub85c \ub4e4\uc5b4\uac08 \uae38\ub3c4 \uc0dd\uae34\ub2e4. \uc77d\ub294 \ub2a5\ub825\uacfc \ubb3c\uac74\uc744 \ubcf4\ub294 \uacbd\ud5d8\uc774 \uc11c\ub85c \ub3c4\uc6b8 \uc218 \uc788\ub2e4. \ud604\ud310\uc740 \uc2dc\ub97c \uae30\uc5b5\ud558\uac8c \ud558\ub294 \ub9e4\uccb4\uc774\uba74\uc11c \uc7a5\uc778\uc758 \uc190\uc744 \uac70\uce5c \ub098\ubb34 \ubb3c\uac74\uc774\ub2e4. \uc655\uacfc \uc138\uc790\uc758 \uae00\uc4f0\uae30, \ucc45\uc73c\ub85c \ub0a8\uc740 \uae30\ub85d, \uac1c\ubcc4 \uae00\uc790\ub97c \uc870\uac01\ud55c \uc81c\uc791\uc774 \ud55c \ud45c\uba74\uc5d0 \uacb9\uce5c\ub2e4. \uae00\uc790 \ud558\ub098\uac00 \ud310\uc5d0\uc11c \uc870\uae08 \uc19f\uc544 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc54c\uba74 \ubb38\uc7a5\uc774 \ub2e8\uc21c\ud788 \uc801\ud600 \uc788\ub2e4\ub294 \ub9d0\ub3c4 \ub354 \uad6c\uccb4\uc801\uc73c\ub85c \ub4e4\ub9b0\ub2e4. \uc758\ubbf8\uc640 \uc7ac\ub8cc\ub97c \ud568\uaed8 \ub9cc\ub098\ub294 \uac10\uc0c1\uc774 \uac00\ub2a5\ud574\uc9c4\ub2e4. \ub9cc\ub4dc\ub294 \ubc29\ubc95\ub3c4 \ub208\uc5ec\uaca8\ubcfc \ub9cc\ud558\ub2e4. \ubc15\ubb3c\uad00\uc740 \uae00\uc790\ub97c \ub530\ub85c \ub098\ubb34\ub85c \uc870\uac01\ud55c \ub4a4 \ubd99\uc600\ub2e4\uace0 \ud55c\ub2e4. \ud3c9\ud3c9\ud55c \ud310\uc5d0 \ubd93\uc73c\ub85c \uc4f0\ub294 \ubc29\ubc95\uacfc \ub2ec\ub9ac \uae00\uc790 \uc790\uccb4\uac00 \uc791\uc740 \ubd80\ud488\uc774 \ub418\ub294 \uc148\uc774\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \uae00\uc790 \ud558\ub098\uc758 \uac00\uc7a5\uc790\ub9ac\ub97c \ub530\ub77c\ubcf4\uc790. \uc2dc\uc758 \ub73b\uc744 \ubaa8\ub450 \ubc88\uc5ed\ud558\uc9c0 \uc54a\uc544\ub3c4, \ubb38\uc7a5\uc744 \uc785\uccb4\uc801\uc778 \ubb3c\uac74\uc73c\ub85c \ubc14\uafb8\ub294 \uc190\uae38\uc744 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ub204\uad70\uac00\uc758 \ub2f5\uc2dc\uac00 \ucc45\uc758 \ud55c \ud398\uc774\uc9c0\uc640 \ub098\ubb34\ud310\uc758 \ud55c \uc904\ub85c \uac01\uac01 \ub0a8\uc558\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc774 \ud604\ud310\uc744 \uc870\uae08 \ub2e4\ub974\uac8c \ubcf4\uac8c \ud55c\ub2e4."}, {"id": "pride-prejudice-first-impressions", "title": "\uc624\ub9cc\uacfc \ud3b8\uacac \u2014 \ucc98\uc74c \ubcf8 \uc778\uc0c1\uc744 \ubbff\uc5b4\ub3c4 \ub420\uae4c", "summary": "\uc5d8\ub9ac\uc790\ubca0\uc2a4\uc640 \ub2e4\uc544\uc2dc\uc758 \uad00\uacc4\ub97c \ud1b5\ud574 \uc624\uc2a4\ud2f4\uc774 \ubcf4\uc5ec \uc8fc\ub294 \uc0ac\ub791\uacfc \uc0ac\ud68c\uc758 \uc870\uac74\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Literature", "url": "stories/pride-prejudice-first-impressions/index.html", "image": "media/pride-prejudice-first-impressions.jpg", "alt": "1913\ub144 Jane Austen: Her Life and Letters \uc218\ub85d \uc81c\uc778 \uc624\uc2a4\ud2f4 \ucd08\uc0c1 \uc7ac\ud604\ub3c4\ud310", "text": "\uc624\ub9cc\uacfc \ud3b8\uacac \u2014 \ucc98\uc74c \ubcf8 \uc778\uc0c1\uc744 \ubbff\uc5b4\ub3c4 \ub420\uae4c \uc0ac\ub791 \uc774\uc57c\uae30 \uc548\uc5d0 \ub4e4\uc5b4 \uc788\ub294 \ud310\ub2e8\uc758 \uc2b5\uad00 \uc5d8\ub9ac\uc790\ubca0\uc2a4\uc640 \ub2e4\uc544\uc2dc\uc758 \uad00\uacc4\ub97c \ud1b5\ud574 \uc624\uc2a4\ud2f4\uc774 \ubcf4\uc5ec \uc8fc\ub294 \uc0ac\ub791\uacfc \uc0ac\ud68c\uc758 \uc870\uac74\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Literature \ubb38\ud654 \ubb34\ub3c4\ud68c\uc5d0\uc11c \ub204\uad70\uac00 \ub098\ub97c \ub300\uc218\ub86d\uc9c0 \uc54a\uac8c \uc5ec\uae30\ub294 \ub9d0\uc744 \ud588\ub2e4\uace0 \uc0dd\uac01\ud574 \ubcf4\uc790. \uadf8 \uc0ac\ub78c\uc758 \ub2e4\uc74c \ud589\ub3d9\ub3c4 \uc27d\uac8c \uc88b\uac8c \ubcf4\uc774\uc9c0 \uc54a\uc744 \uac83\uc774\ub2e4. \uc81c\uc778 \uc624\uc2a4\ud2f4\uc758 \u300e\uc624\ub9cc\uacfc \ud3b8\uacac\u300f\uc740 \uadf8\ub7f0 \uccab\uc778\uc0c1\uc774 \uad73\uc5b4\uc9c0\ub294 \uc18d\ub3c4\uc640, \uadf8\uac83\uc744 \uace0\uce58\ub294 \ub370 \ud544\uc694\ud55c \uc2dc\uac04\uc744 \uc0ac\ub791 \uc774\uc57c\uae30 \uc18d\uc5d0 \ub123\uc740 \uc791\ud488\uc774\ub2e4. 1813\ub144\uc5d0 \ucd9c\uac04\ub41c \uc18c\uc124\uc5d0\ub294 \uc804\uc7c1\ud130\ubcf4\ub2e4 \uac70\uc2e4\uacfc \uc2dd\ud0c1, \uc0b0\ucc45\uae38\uc774 \uc790\uc8fc \ub098\uc628\ub2e4. \ud558\uc9c0\ub9cc \uc870\uc6a9\ud55c \uc7a5\uc18c\ub77c\uace0 \uc774\ud574\uad00\uacc4\uae4c\uc9c0 \uc791\uc9c0\ub294 \uc54a\ub2e4. \uc0ac\ub791\uc744 \uace0\ub974\ub294 \uc77c\uc5d0 \uc7ac\uc0b0\uacfc \uc0c1\uc18d, \uac00\uc871\uc758 \ud3c9\ud310\uc774 \ub530\ub77c\ubd99\ub294\ub2e4. \uc544\ub798\uc5d0\ub294 \uc8fc\uc694 \uc0ac\uac74\uacfc \uacb0\ub9d0\uc774 \ud3ec\ud568\ub418\uc5b4 \uc788\ub2e4. \ubca0\ub137 \ubd80\ubd80\uc5d0\uac8c\ub294 \uc81c\uc778, \uc5d8\ub9ac\uc790\ubca0\uc2a4, \uba54\ub9ac, \ud0a4\ud2f0, \ub9ac\ub514\uc544\ub77c\ub294 \ub2e4\uc12f \ub538\uc774 \uc788\ub2e4. \uac00\uae4c\uc6b4 \uc800\ud0dd\uc5d0 \ubd80\uc720\ud55c \ub3c5\uc2e0 \ub0a8\uc790 \ube59\ub9ac\uac00 \uc774\uc0ac \uc624\uc790 \uc5b4\uba38\ub2c8\ub294 \ub538\ub4e4\uc758 \uc7a5\ub798\ub97c \ub5a0\uc62c\ub9b0\ub2e4. \ubb34\ub3c4\ud68c\uc5d0\uc11c \ube59\ub9ac\uc640 \ub9cf\ub538 \uc81c\uc778\uc740 \uc11c\ub85c \ud638\uac10\uc744 \ub290\ub07c\uc9c0\ub9cc, \ube59\ub9ac\uc758 \uce5c\uad6c \ub2e4\uc544\uc2dc\ub294 \ucc28\uac11\uace0 \uac70\ub9cc\ud558\uac8c \ubcf4\uc778\ub2e4. \uc5d8\ub9ac\uc790\ubca0\uc2a4\ub294 \uc790\uc2e0\uc744 \ub0ae\uac8c \ud3c9\uac00\ud558\ub294 \ub2e4\uc544\uc2dc\uc758 \ub9d0\uc744 \ub4e3\uace0 \ubc18\uac10\uc744 \ud488\ub294\ub2e4. \uc774\ud6c4 \ub3c5\uc790\ub294 \uc7ac\uce58 \uc788\ub294 \uc5d8\ub9ac\uc790\ubca0\uc2a4\uc758 \ub208\uc73c\ub85c \ub2e4\uc544\uc2dc\ub97c \ubcf4\ub294 \uc77c\uc774 \ub9ce\ub2e4. \uc8fc\uc778\uacf5\uacfc \ud568\uaed8 \uc6c3\uace0 \ud310\ub2e8\ud558\ub2e4 \ubcf4\uba74, \uc6b0\ub9ac\uac00 \uac00\uc9c4 \uc815\ubcf4\ub3c4 \ud55c\ucabd\uc73c\ub85c \uae30\uc6b8\uc5b4 \uc788\uc744 \uc218 \uc788\ub2e4\ub294 \uc810\uc744 \uc78a\uae30 \uc27d\ub2e4. \ubca0\ub137\uac00\uc758 \uc7ac\uc0b0\uc740 \uc815\ud574\uc9c4 \uc0c1\uc18d \uc870\uac74 \ub54c\ubb38\uc5d0 \uc544\ub4e4\uc774 \uc5c6\ub294 \uacbd\uc6b0 \ub0a8\uc790 \uce5c\ucc99 \ucf5c\ub9b0\uc2a4\uc5d0\uac8c \ub118\uc5b4\uac00\uac8c \ub418\uc5b4 \uc788\ub2e4. \uc5b4\uba38\ub2c8\uc758 \ud638\ub4e4\uac11\uc5d0\ub294 \uc6b0\uc2a4\uc6b4 \uba74\ub3c4 \uc788\uc9c0\ub9cc \ub538\ub4e4\uc758 \uc0dd\ud65c \uae30\ubc18\uc744 \uac71\uc815\ud558\ub294 \ud604\uc2e4\ub3c4 \ub4e4\uc5b4 \uc788\ub2e4. \ub2e4\ub9cc \uc774\ub97c \ub2f9\uc2dc \ubaa8\ub4e0 \uc5ec\uc131\uc774 \uc7ac\uc0b0\uc744 \uc0c1\uc18d\ubc1b\uc744 \uc218 \uc5c6\uc5c8\ub2e4\ub294 \ub73b\uc73c\ub85c \ud655\ub300\ud558\uba74 \uc548 \ub41c\ub2e4. \uc791\ud488 \uc18d \uc774 \uc9d1\uc548\uc5d0 \uac78\ub9b0 \uc870\uac74\uc774 \ubb38\uc81c\ub2e4. \ucf5c\ub9b0\uc2a4\uac00 \uccad\ud63c\ud588\uc744 \ub54c \uc5d8\ub9ac\uc790\ubca0\uc2a4\ub294 \uac70\uc808\ud55c\ub2e4. \uadf8\ub7ec\ub098 \uce5c\uad6c \uc0ec\ub7ff\uc740 \uadf8\uc640 \uacb0\ud63c\ud55c\ub2e4. \uac19\uc740 \uc120\ud0dd\uc744 \ud558\uc9c0 \uc54a\uc558\ub2e4\uace0 \uc0ec\ub7ff\uc744 \ub2e8\uc9c0 \uacc4\uc0b0\uc801\uc778 \uc0ac\ub78c\uc73c\ub85c \uce58\ubd80\ud558\uba74 \uc791\ud488\uc774 \ubcf4\uc5ec \uc8fc\ub294 \ud3ed\uc774 \uc881\uc544\uc9c4\ub2e4. \uc0ac\ub791\uc744 \uae30\ub2e4\ub9b4 \uc5ec\uc720\uc640 \uc548\uc815\ub41c \uc0dd\ud65c\uc744 \ud655\ubcf4\ud560 \uae30\ud68c\uac00 \ub204\uad6c\uc5d0\uac8c\ub098 \ub611\uac19\uc774 \uc8fc\uc5b4\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4\ub294 \uac83\uc774\ub2e4. \uc7a5\uad50 \uc704\ucef4\uc740 \ub2e4\uc815\ud55c \ud0dc\ub3c4\ub85c \uc5d8\ub9ac\uc790\ubca0\uc2a4\uc5d0\uac8c \uc811\uadfc\ud558\uace0, \ub2e4\uc544\uc2dc\uc5d0\uac8c \ubd80\ub2f9\ud55c \ub300\uc6b0\ub97c \ubc1b\uc558\ub2e4\uace0 \ub9d0\ud55c\ub2e4. \uc774\ubbf8 \ub2e4\uc544\uc2dc\ub97c \uc2eb\uc5b4\ud558\ub358 \uc5d8\ub9ac\uc790\ubca0\uc2a4\uc5d0\uac8c\ub294 \ubbff\uae30 \uc26c\uc6b4 \uc774\uc57c\uae30\ub2e4. \ubc18\uba74 \ub2e4\uc544\uc2dc\ub294 \uc810\ucc28 \uadf8\uc5d0\uac8c \ub04c\ub9ac\uc9c0\ub9cc \uc790\uc2e0\uc758 \uacc4\uae09\uc758\uc2dd\uacfc \ubca0\ub137 \uac00\uc871\uc5d0 \ub300\ud55c \ud3c9\uac00\ub97c \ucda9\ubd84\ud788 \ub118\uc5b4\uc11c\uc9c0 \ubabb\ud55c\ub2e4. \ub2e4\uc544\uc2dc\uc758 \uccab \uccad\ud63c\uc740 \uc0ac\ub791 \uace0\ubc31\uc774\uba74\uc11c \ub3d9\uc2dc\uc5d0 \uc0c1\ub300 \uac00\uc871\uc758 \ub0ae\uc740 \uc9c0\uc704\ub97c \ub4e4\uba39\uc774\ub294 \ub9d0\uc774 \ub41c\ub2e4. \uc5d8\ub9ac\uc790\ubca0\uc2a4\ub294 \uac70\uc808\ud558\uace0, \uc81c\uc778\uacfc \ube59\ub9ac \uc0ac\uc774\ub97c \uac08\ub77c\ub193\uc740 \uc77c\uacfc \uc704\ucef4\uc5d0 \uad00\ud55c \uc77c\uae4c\uc9c0 \ube44\ub09c\ud55c\ub2e4. \ub2e4\uc544\uc2dc\ub294 \ud3b8\uc9c0\ub97c \uc368 \uc790\uc2e0\uc758 \ud589\ub3d9\uacfc \uc704\ucef4\uc758 \uacfc\uac70\ub97c \uc124\uba85\ud55c\ub2e4. \uc5ec\uae30\uc11c \ud3b8\uc9c0\ub294 \uac10\ub3d9\uc801\uc778 \uc7a5\uc2dd\ubcf4\ub2e4, \ub3c5\uc790\uac00 \uc54c\uace0 \uc788\ub358 \uc0ac\uc2e4\uc744 \ub2e4\uc2dc \uc810\uac80\ud558\uac8c \ud558\ub294 \uc790\ub8cc\uc5d0 \uac00\uae5d\ub2e4. \ud3b8\uc9c0\ub97c \uc77d\uc740 \uc5d8\ub9ac\uc790\ubca0\uc2a4\ub294 \uc704\ucef4\uc5d0 \ub300\ud55c \uc790\uc2e0\uc758 \ud310\ub2e8\uc774 \uc5bc\ub9c8\ub098 \ud638\uac10\uc5d0 \uae30\ub300\uace0 \uc788\uc5c8\ub294\uc9c0 \ub3cc\uc544\ubcf8\ub2e4. \uadf8\ub807\ub2e4\uace0 \ub2e4\uc544\uc2dc\uc758 \ubd88\ucf8c\ud55c \ud0dc\ub3c4\uae4c\uc9c0 \ud55c\uaebc\ubc88\uc5d0 \uc815\ub2f9\ud654\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub294 \ub2e4\ub978 \uc0ac\ub78c\uc744 \ub300\ud558\ub294 \ubc29\uc2dd\uc744 \ubc14\uafb8\uc5b4\uc57c \ud558\uace0, \uc5d8\ub9ac\uc790\ubca0\uc2a4\ub3c4 \uc790\uc2e0\uc774 \ubcf4\uace0 \uc2f6\uc740 \uac83\ub9cc \ubcf4\uc558\uc744 \uac00\ub2a5\uc131\uc744 \ubc1b\uc544\ub4e4\uc5ec\uc57c \ud55c\ub2e4. \ud6c4\uc5d0 \ub2e4\uc544\uc2dc\uc758 \uc800\ud0dd \ud3a8\ubc8c\ub9ac\ub97c \ubc29\ubb38\ud558\uba74\uc11c \uc5d8\ub9ac\uc790\ubca0\uc2a4\ub294 \ud558\uc778\ub4e4\uc758 \ud3c9\uac00\uc640 \uadf8\uc758 \ub2ec\ub77c\uc9c4 \ud0dc\ub3c4\ub97c \uc811\ud55c\ub2e4. \ubd80\uc720\ud55c \uc9d1\uc744 \ubcf4\uc558\uc73c\ub2c8 \ub9c8\uc74c\uc774 \ubc14\ub00c\uc5c8\ub2e4\ub294 \uc124\uba85\ub9cc\uc73c\ub85c\ub294 \ubd80\uc871\ud558\ub2e4. \ucc98\uc74c\uc758 \ub9d0, \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uc758 \uc99d\uc5b8, \uc2e4\uc81c \ud589\ub3d9\uc744 \ud568\uaed8 \ube44\uad50\ud558\uac8c \ub418\uc5c8\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \uc0c1\ub300\ub97c \uc774\ud574\ud558\ub294 \uadfc\uac70\uac00 \ub113\uc5b4\uc9c0\ub294 \uac83\uc774\ub2e4. \ub9c9\ub0b4 \ub9ac\ub514\uc544\uac00 \uc704\ucef4\uacfc \ud568\uaed8 \ub5a0\ub098\ub294 \uc0ac\uac74\uc740 \ud55c \uc0ac\ub78c\uc758 \uc5f0\uc560 \ubb38\uc81c\ub85c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \uacb0\ud63c\ud558\uc9c0 \uc54a\uc740 \ub3d9\ud589\uc774 \uc54c\ub824\uc9c0\uba74 \uac00\uc871 \uc804\uccb4\uc758 \ud3c9\ud310\uacfc \ub2e4\ub978 \ub538\ub4e4\uc758 \ud63c\uc778\uc5d0\ub3c4 \ud070 \ud0c0\uaca9\uc774 \uc0dd\uae38 \uc218 \uc788\ub294 \uc0ac\ud68c\ub2e4. \ub2e4\uc544\uc2dc\ub294 \ubb38\uc81c\ub97c \uc218\uc2b5\ud558\uace0 \ub450 \uc0ac\ub78c\uc758 \uacb0\ud63c\uc774 \uc774\ub8e8\uc5b4\uc9c0\ub294 \ub370 \uac1c\uc785\ud558\uc9c0\ub9cc, \ucc98\uc74c\uc5d0\ub294 \uc790\uc2e0\uc758 \uc5ed\ud560\uc744 \ub4dc\ub7ec\ub0b4\uc9c0 \uc54a\ub294\ub2e4. \uc774 \ud589\ub3d9\uc740 \uc5d8\ub9ac\uc790\ubca0\uc2a4\uc5d0\uac8c \uadf8\uc758 \uc131\uaca9\uc744 \ub2e4\uc2dc \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uccab \uccad\ud63c\uc5d0\uc11c \uc790\uae30 \uac10\uc815\uc744 \uc55e\uc138\uc6b0\ub358 \uc0ac\ub78c\uacfc \uc9c0\uae08\uc758 \ud589\ub3d9 \uc0ac\uc774\uc5d0 \ucc28\uc774\uac00 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \ub3d9\uc2dc\uc5d0 \uc18c\uc124\uc740 \uacb0\ud63c\uc774 \uc131\ub9bd\ud588\ub2e4\uace0 \ud574\uc11c \uc704\ucef4\uacfc \ub9ac\ub514\uc544\uc758 \uad00\uacc4\uac00 \ud6cc\ub96d\ud574\uc84c\ub2e4\uace0 \ud3ec\uc7a5\ud558\uc9c0\ub3c4 \uc54a\ub294\ub2e4. \ubaa8\ub4e0 \ud63c\uc778\uc774 \uac19\uc740 \ud589\ubcf5\uc758 \uc99d\uac70\ub294 \uc544\ub2c8\ub2e4. \uc81c\uc778\uacfc \ube59\ub9ac\ub294 \ub2e4\uc2dc \ub9cc\ub098 \uacb0\ud63c\ud558\uace0, \uc5d8\ub9ac\uc790\ubca0\uc2a4\uc640 \ub2e4\uc544\uc2dc \uc5ed\uc2dc \uc11c\ub85c\uc758 \ubcc0\ud654\ub97c \ud655\uc778\ud55c \ub4a4 \ud568\uaed8\ud558\uae30\ub85c \ud55c\ub2e4. \ub2e4\uc544\uc2dc\uc758 \uce5c\ucc99 \ub808\uc774\ub514 \uce90\uc11c\ub9b0\uc774 \uc2e0\ubd84 \ucc28\uc774\ub97c \ub0b4\uc138\uc6cc \ubc18\ub300\ud558\ub294 \uc7a5\uba74\uc5d0\uc11c\ub294, \ub204\uac00 \uacb0\ud63c\uc744 \uacb0\uc815\ud560 \uad8c\ub9ac\uac00 \uc788\ub294\uc9c0\ub3c4 \ubb38\uc81c\uac00 \ub41c\ub2e4. \uc0ac\ub791 \uc774\uc57c\uae30\uc758 \uacb0\ub9d0 \uc548\uc5d0 \uac1c\uc778\uc758 \ud310\ub2e8\uacfc \uc0ac\ud68c\uc801 \uc704\uacc4\uc758 \ucda9\ub3cc\uc774 \ub0a8\uc544 \uc788\ub2e4. \ub2e4\uc544\uc2dc\ub294 \uc624\ub9cc, \uc5d8\ub9ac\uc790\ubca0\uc2a4\ub294 \ud3b8\uacac\uc774\ub77c\uace0 \ub531 \ub098\ub204\uba74 \uc678\uc6b0\uae30 \ud3b8\ud558\ub2e4. \uadf8\ub7ec\ub098 \ub450 \uc0ac\ub78c\uc740 \uac01\uae30 \uc790\ubd80\uc2ec\uacfc \uc120\uc785\uacac\uc744 \ub4dc\ub7ec\ub0b8\ub2e4. \uc774 \uc791\ud488\uc758 \uc990\uac70\uc6c0\uc740 \ub2e8\uc810\uc744 \ud558\ub098\uc529 \ubc30\uc815\ud558\ub294 \ub370 \uc788\uae30\ubcf4\ub2e4, \ub611\ub611\ud55c \uc0ac\ub78c\ub3c4 \ud2c0\ub9ac\uace0 \uadf8\uac83\uc744 \uc778\uc815\ud558\uba70 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4\ub294 \uacfc\uc815\uc744 \uc9c0\ucf1c\ubcf4\ub294 \ub370 \uc788\ub2e4. \uc624\uc2a4\ud2f4\uc740 \ub204\uac00 \ub9d0\uc744 \ub3c5\ucc28\uc9c0\ud558\uace0 \ub204\uad6c\uc758 \ub9d0\uc744 \ubabb \uc54c\uc544\ub4e3\ub294\uc9c0, \uc608\uc758 \ubc14\ub978 \ubb38\uc7a5 \uc18d\uc5d0 \uc5b4\ub5a4 \ubb34\ub840\ud568\uc774 \uc228\uc5b4 \uc788\ub294\uc9c0 \ubcf4\uc5ec \uc900\ub2e4. \uc0ac\uac74\ub9cc \uc694\uc57d\ud558\uba74 \uc0ac\ub77c\uc9c0\ub294 \uc7ac\ubbf8\ub2e4. \ub2e4\uc74c\uc5d0 \uac70\uc2e4\uc758 \uae34 \ub300\ud654\uac00 \ub098\uc624\uba74 \uc815\ubcf4\ub97c \ube68\ub9ac \uc5bb\uc73c\ub824 \ud558\uae30\ubcf4\ub2e4, \uadf8 \ub9d0\uc774 \uc0c1\ub300\uc5d0\uac8c \uc5b4\ub5bb\uac8c \ub4e4\ub9b4\uc9c0 \ud55c \ubc88 \uc0dd\uac01\ud574 \ubcf4\uc790. \ud568\uaed8 \uc2e4\uc740 \ucd08\uc0c1\uc740 \uc5d8\ub9ac\uc790\ubca0\uc2a4\uac00 \uc544\ub2c8\ub77c \uc791\uac00 \uc81c\uc778 \uc624\uc2a4\ud2f4\uc758 \uc5ed\uc0ac\uc801 \uc7ac\ud604 \ub3c4\ud310\uc774\ub2e4. \uc18c\uc124 \uc18d \uc778\ubb3c\uc758 \uc5bc\uad74\uc740 \ub3c5\uc790\uc758 \ubaab\uc73c\ub85c \ub0a8\uaca8 \ub450\uc5b4\ub3c4 \uc88b\ub2e4. \uccab\uc778\uc0c1\uc740 \ub204\uad6c\ub098 \uac16\uc9c0\ub9cc \uadf8\uac83\uc744 \ub05d\uae4c\uc9c0 \uc9c0\ucf1c\uc57c \ud560 \uc758\ubb34\ub294 \uc5c6\ub2e4\ub294 \uc0dd\uac01, \uc774 \uc624\ub798\ub41c \uc5f0\uc560\uc18c\uc124\uc774 \uc624\ub298\uc758 \ub9cc\ub0a8\uc5d0\ub3c4 \uac74\ub124\ub294 \uc77d\uc744\uac70\ub9ac\ub2e4."}, {"id": "raphael-belle-jardiniere", "title": "\uc544\ub984\ub2e4\uc6b4 \uc815\uc6d0\uc0ac \u2014 \uadf8\ub9bc \uc18d \uc5ec\uc778\uc740 \ub204\uad6c\uc77c\uae4c", "summary": "\ub8e8\ube0c\ub974 \uc791\ud488\uc758 \uc778\ubb3c\uacfc \ubab8\uc9d3\uc744 \uc54c\uc544\ubcf4\uba70 \uc885\uad50 \ud68c\ud654\uc5d0 \ub2e4\uac00\uac00 \ubd05\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Art", "url": "stories/raphael-belle-jardiniere/index.html", "image": "media/raphael-belle-jardiniere.jpg", "alt": "\ub77c\ud30c\uc5d8\ub85c, \uc544\ub984\ub2e4\uc6b4 \uc815\uc6d0\uc0ac \u00b7 \uc61b \ub8e8\ube0c\ub974 \ub3c4\ub85d Plate VII", "text": "\uc544\ub984\ub2e4\uc6b4 \uc815\uc6d0\uc0ac \u2014 \uadf8\ub9bc \uc18d \uc5ec\uc778\uc740 \ub204\uad6c\uc77c\uae4c \ub77c\ud30c\uc5d8\ub85c\uc758 \uc131\ubaa8\uc790\ud654\ub97c \ubcf4\ub294 \uc138 \uac00\uc9c0 \ub2e8\uc11c \ub8e8\ube0c\ub974 \uc791\ud488\uc758 \uc778\ubb3c\uacfc \ubab8\uc9d3\uc744 \uc54c\uc544\ubcf4\uba70 \uc885\uad50 \ud68c\ud654\uc5d0 \ub2e4\uac00\uac00 \ubd05\ub2c8\ub2e4. Art \ubb38\ud654 \u2018\uc544\ub984\ub2e4\uc6b4 \uc815\uc6d0\uc0ac\u2019\ub77c\ub294 \uc81c\ubaa9\uc744 \ub4e4\uc73c\uba74 \uaf43\ubc2d\uc744 \uac00\uafb8\ub294 \uc5ec\uc778\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \ub77c\ud30c\uc5d8\ub85c\uc758 \uadf8\ub9bc\uc5d0\ub294 \uc131\ubaa8 \ub9c8\ub9ac\uc544\uc640 \uc544\uae30 \uc608\uc218, \uc5b4\ub9b0 \uc138\ub840 \uc694\ud55c\uc774 \ub4f1\uc7a5\ud55c\ub2e4. \uc815\uc6d0 \uc77c\uc744 \uc124\uba85\ud558\ub294 \uadf8\ub9bc\uc774 \uc544\ub2c8\ub77c \ud480\uacfc \uaf43\uc774 \uc788\ub294 \ud48d\uacbd \uc18d\uc5d0 \uc885\uad50\uc801 \uc778\ubb3c\ub4e4\uc744 \ub193\uc740 \uc131\ubaa8\uc790\ud654\ub2e4. \uc885\uad50 \ud68c\ud654\uac00 \ub0af\uc124\uc5b4\ub3c4 \uc778\ubb3c \uc774\ub984\uc744 \uc870\uae08 \uc54c\uace0 \uc2dc\uc120\uacfc \ubab8\uc9d3\uc744 \ub530\ub77c\uac00\uba74 \ucda9\ubd84\ud788 \ub4e4\uc5b4\uac08 \uc218 \uc788\ub2e4. \uc774 \uadf8\ub9bc\uc5d0\uc11c\ub294 \uad50\ub9ac\uc758 \ubaa9\ub85d\ubcf4\ub2e4 \ud55c \uc5b4\ub978\uacfc \ub450 \uc544\uc774 \uc0ac\uc774\uc758 \uad00\uacc4\uac00 \uba3c\uc800 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uac00\uc6b4\ub370 \uc549\uc544 \uc788\ub294 \uc5ec\uc778\uc774 \ub9c8\ub9ac\uc544\uc774\uace0, \uacc1\uc5d0 \uc11c \uc788\ub294 \uc544\uc774\uac00 \uc608\uc218, \ub2e4\ub978 \ucabd\uc5d0\uc11c \ubb34\ub98e\uc744 \uad7d\ud78c \uc544\uc774\uac00 \uc138\ub840 \uc694\ud55c\uc774\ub2e4. \uc138\ub840 \uc694\ud55c\uc740 \uc131\uc11c\uc5d0\uc11c \uc608\uc218\uc758 \uae38\uc744 \uc900\ube44\ud558\ub294 \uc778\ubb3c\ub85c \ub4f1\uc7a5\ud55c\ub2e4. \uc5ec\uae30\uc11c\ub294 \ub450 \uc544\uc774\uac00 \uc5b4\ub9b0 \uc2dc\uc808 \ud55c \ud654\uba74 \uc548\uc5d0 \ud568\uaed8 \ub193\uc5ec \uc788\ub2e4. \uc774\ub294 \uc5b4\ub5a4 \uc21c\uac04\uc744 \uc0ac\uc9c4\ucc98\ub7fc \uae30\ub85d\ud55c \uc7a5\uba74\uc774\ub77c\uae30\ubcf4\ub2e4 \uae30\ub3c5\uad50 \ud68c\ud654\uac00 \uc778\ubb3c\ub4e4\uc758 \uad00\uacc4\ub97c \ubcf4\uc5ec \uc8fc\ub294 \ubc29\uc2dd\uc73c\ub85c \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc138 \uc0ac\ub78c\uc758 \uc774\ub984\uc744 \uc54c\uba74 \ub2e8\uc21c\ud788 \uc5ec\uc778\uacfc \uc544\uc774\ub4e4\uc774 \uc788\ub2e4\ub294 \uccab\uc778\uc0c1\uc5d0\uc11c \ud55c \uac78\uc74c \ub098\uc544\uac00, \uc65c \ubab8\uc9d3\uc774 \uc11c\ub85c\ub97c \ud5a5\ud558\ub294\uc9c0\ub3c4 \uc0b4\ud544 \uc218 \uc788\ub2e4. \ud504\ub791\uc2a4\uc5b4 \ud45c\uc81c \ub77c \ubca8 \uc790\ub974\ub514\ub2c8\uc5d0\ub974\ub294 \u2018\uc544\ub984\ub2e4\uc6b4 \uc815\uc6d0\uc0ac\u2019\ub77c\ub294 \ub73b\uc73c\ub85c \ubd88\ub9b0\ub2e4. \ud558\uc9c0\ub9cc \uc81c\ubaa9\uc5d0 \uc815\uc6d0\uc0ac\uac00 \uc788\ub2e4\uace0 \ud574\uc11c \ub9c8\ub9ac\uc544\uac00 \uc815\uc6d0 \uc77c\uc744 \ud558\ub294 \uc9c1\uc5c5\uc778\uc73c\ub85c \ub4f1\uc7a5\ud55c\ub2e4\uace0 \uc77d\uc73c\uba74 \uc7a5\uba74\uc744 \ub193\uce58\uac8c \ub41c\ub2e4. \uaf43\uacfc \ud480\uc774 \uc788\ub294 \ubc30\uacbd\uacfc \uc774 \uc81c\ubaa9\uc744 \ud568\uaed8 \ubc1b\uc544\ub4e4\uc774\ub294 \ud3b8\uc774 \uc790\uc5f0\uc2a4\ub7fd\ub2e4. \uc774\ubc88 \uc790\ub8cc\ub9cc\uc73c\ub85c \ub204\uac00 \uc5b8\uc81c \uc774 \ubcc4\uce6d\uc744 \ucc98\uc74c \ubd99\uc600\ub294\uc9c0\uae4c\uc9c0 \ud655\uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc791\ud488\uc758 \ub0b4\uc6a9\uacfc \uc81c\ubaa9\uc758 \ub9d0\ub73b\uc740 \uc124\uba85\ud560 \uc218 \uc788\uc5b4\ub3c4 \ubcc4\uce6d\uc758 \ud0c4\uc0dd \uacbd\uc704\ub294 \ub610 \ub2e4\ub978 \uc99d\uac70\uac00 \ud544\uc694\ud55c \uc77c\uc774\ub2e4. \uc791\ud488 \uc774\ub984\uc744 \uc544\ub294 \uac83\uc774 \ubaa8\ub4e0 \ub0b4\ub825\uc744 \uc548\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ub9c8\ub9ac\uc544\uc758 \uba38\ub9ac\ub97c \uc704\ucabd \uaf2d\uc9d3\uc810\ucc98\ub7fc \ubcf4\uace0 \uc591\uc606\uacfc \uc544\ub798\ub85c \ub208\uc744 \ub0b4\ub824 \ubcf4\uc790. \ub9c8\ub9ac\uc544\uc640 \ub450 \uc544\uc774\uac00 \uc774\ub8e8\ub294 \ub369\uc5b4\ub9ac\uac00 \ub113\uc5b4\uc9c0\uba70 \ud654\uba74 \uc544\ub798\uc5d0 \uc790\ub9ac\ub97c \uc7a1\ub294\ub2e4. \uc0bc\uac01\ud615 \uac19\uc740 \uad6c\uc131\uc774\ub77c\uace0 \uc124\uba85\ud558\ub294 \uc774\uc720\ub97c \ubcf5\uc7a1\ud55c \ub3c4\ud615 \uc5c6\uc774\ub3c4 \ub290\ub084 \uc218 \uc788\ub2e4. \uc774\ub294 \uc2e4\uc81c\ub85c \uc120\uc744 \uadf8\uc5b4 \uc815\ud655\ud55c \uc0bc\uac01\ud615\uc744 \uc99d\uba85\ud558\ub77c\ub294 \ubb38\uc81c\uac00 \uc544\ub2c8\ub2e4. \uc778\ubb3c\ub4e4\uc774 \ud769\uc5b4\uc9c0\uc9c0 \uc54a\uace0 \ud558\ub098\uc758 \ubb34\ub9ac\ub85c \ubcf4\uc774\ub294 \uc548\uc815\uac10\uc5d0 \uc8fc\ubaa9\ud558\ub294 \ubc29\ubc95\uc774\ub2e4. \uc544\uc774\ub4e4\uc758 \uc791\uc740 \uc6c0\uc9c1\uc784\uacfc \ub9c8\ub9ac\uc544\uc758 \ud070 \ubab8\uc774 \ud568\uaed8 \ud654\uba74\uc758 \uade0\ud615\uc744 \ub9cc\ub4e0\ub2e4. \ub9c8\ub9ac\uc544\ub294 \uad00\uac1d\uc5d0\uac8c \uc124\uba85\ud558\ub4ef \uc815\uba74\uc744 \ubc14\ub77c\ubcf4\uae30\ubcf4\ub2e4 \uc544\uc774\uc5d0\uac8c \ub208\uae38\uc744 \ub454\ub2e4. \uc608\uc218\uc640 \uc694\ud55c\uc758 \uc790\uc138 \uc5ed\uc2dc \uc11c\ub85c\uc758 \uc874\uc7ac\ub97c \uc758\uc2dd\ud558\ub294 \uad00\uacc4 \uc548\uc5d0 \ub193\uc5ec \uc788\ub2e4. \uba3c\uc800 \uac01\uc790\uc758 \uc5bc\uad74\uc744 \ubcf4\uace0, \ub2e4\uc74c\uc5d0\ub294 \uc5bc\uad74\ub4e4\uc774 \uc5b4\ub514\ub85c \ud5a5\ud558\ub294\uc9c0 \ub530\ub77c\uac00 \ubcf4\uc790. \uc774\ub984\ud45c \uc138 \uac1c\uc600\ub358 \uc7a5\uba74\uc774 \uad00\uacc4\ub97c \uac00\uc9c4 \uc0ac\ub78c\ub4e4\uc758 \ubaa8\uc2b5\uc73c\ub85c \ubc14\ub010\ub2e4. \ub9c8\ub9ac\uc544\uc758 \uc190\uacfc \uc544\uc774\uc758 \ubab8\uc774 \uac00\uae4c\uc774 \ub193\uc778 \ubd80\ubd84\uc5d0\uc11c\ub294 \ub3cc\ubd04\uc758 \ubab8\uc9d3\uc744 \ub290\ub084 \uc218 \uc788\ub2e4. \ubb3c\ub860 \uc774 \uadf8\ub9bc\uc758 \uc8fc\uc81c\ub294 \uc885\uad50\uc801\uc774\ub2e4. \uadf8\ub807\uc9c0\ub9cc \uc5b4\ub978\uc774 \uc544\uc774\ub97c \uc9c0\ucf1c\ubcf4\uace0 \uc544\uc774\uac00 \uac00\uae4c\uc774 \uae30\ub300\ub294 \uacbd\ud5d8\uc744 \ud1b5\ud574 \ub0af\uc120 \uc8fc\uc81c\uc5d0 \ub2e4\uac00\uac08 \uc218\ub3c4 \uc788\ub2e4. \uce5c\uc219\ud55c \ubab8\uc9d3\uacfc \uc885\uad50\uc801 \uc758\ubbf8\uac00 \ud568\uaed8 \uc874\uc7ac\ud55c\ub2e4. \uc5b4\ub9b0 \uc694\ud55c\uc774 \uc9c0\ub2cc \uc2ed\uc790\uac00 \ubaa8\uc591\uc758 \ud45c\uc9c0\ub294 \uc778\ubb3c\uc744 \uc54c\uc544\ubcf4\ub294 \ub2e8\uc11c\ub2e4. \uae30\ub3c5\uad50 \uadf8\ub9bc\uc5d0\ub294 \uc778\ubb3c\uacfc \uc5f0\uacb0\ub41c \ubb3c\uac74\uc774\ub098 \uc790\uc138\uac00 \uc790\uc8fc \uc0ac\uc6a9\ub41c\ub2e4. \uae00\ub85c \uc774\ub984\uc744 \uc801\uc9c0 \uc54a\uc544\ub3c4 \uad00\uac1d\uc774 \ub300\uc0c1\uc744 \uc54c\uc544\ubcf4\ub3c4\ub85d \ub3d5\ub294 \ud68c\ud654\uc758 \uc5b8\uc5b4\ub77c\uace0 \uc0dd\uac01\ud558\uba74 \ub41c\ub2e4. \uc2ed\uc790\uac00\ub294 \uc608\uc218\uc758 \ud6d7\ub0a0 \uc218\ub09c\ub3c4 \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \ud3c9\ud654\ub85c\uc6b4 \uc5b4\ub9b0 \uc2dc\uc808\uc758 \uc7a5\uba74 \uc548\uc5d0 \uc55e\uc73c\ub85c\uc758 \uc774\uc57c\uae30\ub97c \uc554\uc2dc\ud558\ub294 \ud45c\uc9c0\uac00 \ub4e4\uc5b4 \uc788\ub294 \uc148\uc774\ub2e4. \uadf8\ub9bc\uc774 \ucc28\ubd84\ud558\uace0 \uc544\ub984\ub2f5\ub2e4\uace0 \ud574\uc11c \uadf8 \uc758\ubbf8\uae4c\uc9c0 \uc624\uc9c1 \ud3c9\uc628\ud568\uc5d0 \uba38\ubb34\ub974\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc544\uc774\ub4e4\uc758 \ubaa8\uc2b5\uc744 \ubcf4\uba70 \uc774\ud6c4\uc758 \uc11c\uc0ac\ub97c \ud568\uaed8 \uc0dd\uac01\ud558\ub294 \uac10\uc0c1\ub3c4 \uac00\ub2a5\ud558\ub2e4. \ub9c8\ub9ac\uc544\uc758 \uc637\uc5d0\uc11c\ub294 \ubd89\uc740\uc0c9\uacfc \ud478\ub978\uc0c9\uc774 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uc778\ubb3c\uc744 \ub610\ub837\ud558\uac8c \ubb36\uc5b4 \uc8fc\ub294 \uc0c9\uc758 \uc911\uc2ec\uc774\ub2e4. \ub4a4\ucabd\uc758 \ud48d\uacbd\uc73c\ub85c \uc2dc\uc120\uc744 \uc62e\uacbc\ub2e4\uac00 \ub2e4\uc2dc \uc637\uc73c\ub85c \ub3cc\uc544\uc624\uba74 \uac00\uae4c\uc6b4 \uc778\ubb3c\ub4e4\uc774 \uc5b4\ub5bb\uac8c \uc55e\uc5d0 \uc790\ub9ac \uc7a1\ub294\uc9c0 \ub290\ub084 \uc218 \uc788\ub2e4. \ub77c\ud30c\uc5d8\ub85c\ub294 \ub974\ub124\uc0c1\uc2a4\uc758 \ud654\uac00\uc774\uba70 \uc774 \uc791\ud488\uc5d0\uc11c\ub294 \uc778\ubb3c\uc758 \ubd80\ub4dc\ub7ec\uc6b4 \ubab8\uc9d3\uacfc \uc548\uc815\ub41c \ubc30\uce58\uac00 \uc798 \ub4dc\ub7ec\ub09c\ub2e4. \ub2e4\ub9cc \u2018\uade0\ud615 \uc7a1\ud614\ub2e4\u2019\ub294 \ud3c9\uac00\ub97c \uc678\uc6b4 \ub4a4 \uac10\uc0c1\uc744 \ub05d\ub0b4\uae30\ubcf4\ub2e4, \uc5b4\ub5a4 \ubd80\ubd84\uc774 \uadf8 \ub290\ub08c\uc744 \ub9cc\ub4dc\ub294\uc9c0 \uc9c1\uc811 \ucc3e\uc544\ubcf4\uc790. \uc778\ubb3c \uc0ac\uc774\uc758 \uac04\uaca9\uacfc \uc637\uc758 \ub113\uc740 \uc0c9\uba74\uc774 \uad6c\uccb4\uc801\uc778 \uae38\uc7a1\uc774\uac00 \ub41c\ub2e4. \ub9c8\ub9ac\uc544\uc640 \uc608\uc218, \uc138\ub840 \uc694\ud55c\uc774 \ub204\uad6c\uc778\uc9c0\ub9cc \uc54c\uc544\ub3c4 \ucc98\uc74c\ubcf4\ub2e4 \ud6e8\uc52c \ub9ce\uc740 \uac83\uc744 \uc77d\uc744 \uc218 \uc788\ub2e4. \ub354 \uc54c\uace0 \uc2f6\ub2e4\uba74 \uc138\ub840 \uc694\ud55c\uc758 \uc5ed\ud560\uc774\ub098 \uc131\ubaa8\uc790\ud654\uc758 \uc804\ud1b5\uc73c\ub85c \ub113\ud600 \uac08 \uc218 \uc788\uc9c0\ub9cc \ucc98\uc74c\ubd80\ud130 \ubaa8\ub450 \uc54c\uc544\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud544\uc694\ud55c \uc9c0\uc2dd\uc744 \ud558\ub098 \uc5bb\uace0 \ub2e4\uc2dc \uadf8\ub9bc\uc744 \ubcf4\ub294 \uc655\ubcf5\uc774 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \uc61b \ub8e8\ube0c\ub974 \ub3c4\ub85d\uc5d0 \uc218\ub85d\ub41c \uc2e4\uc81c \uc791\ud488\uc758 \uc7ac\ud604 \ub3c4\ud310\uc774\ub2e4. \ucd5c\uc2e0 \uc2e4\ubb3c \uc0ac\uc9c4\uacfc \uc0c9\u00b7\uc138\ubd80\uac00 \uac19\ub2e4\uace0 \ubcf4\uc9c0\ub294 \ub9d0\uc790. \uc624\ub298\uc740 \uc138 \uc0ac\ub78c\uc758 \uc774\ub984\uc744 \ud655\uc778\ud558\uace0, \uc2dc\uc120\uc758 \uae38\uc744 \ub530\ub77c\uac00\uace0, \ub9c8\uc9c0\ub9c9\uc5d0 \uc2ed\uc790\uac00\ub97c \ub2e4\uc2dc \ubcf4\ub294 \uc21c\uc11c\ub85c \uac10\uc0c1\ud574 \ubcf4\uc790. \ud3c9\ud654\ub85c\uc6b4 \uc7a5\uba74 \uc18d\uc5d0 \ub2f4\uae34 \uad00\uacc4\uc640 \uc55e\uc73c\ub85c\uc758 \uc774\uc57c\uae30\uac00 \uc870\uae08\uc529 \ub4dc\ub7ec\ub0a0 \uac83\uc774\ub2e4."}, {"id": "rembrandt-emmaus-light", "title": "\uc5e0\ub9c8\uc624\uc758 \uc21c\ub840\uc790\ub4e4 \u2014 \uc2dd\ud0c1\uc5d0\uc11c \ub0af\uc120 \uc774\ub97c \uc54c\uc544\ubcf4\ub294 \uc21c\uac04", "summary": "\uc131\uc11c\uc758 \uc7a5\uba74\uacfc \ud654\uba74 \uc18d \uc190\u00b7\uc2dc\uc120\u00b7\ube48 \uacf5\uac04\uc744 \ud568\uaed8 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Art", "url": "stories/rembrandt-emmaus-light/index.html", "image": "media/rembrandt-emmaus-light.jpg", "alt": "\ub818\ube0c\ub780\ud2b8\uc758 \uc5e0\ub9c8\uc624\uc758 \uc21c\ub840\uc790\ub4e4. \uc608\uc218\uc640 \ub450 \uc81c\uc790\uac00 \uc2dd\ud0c1\uc5d0 \uc549\uace0 \uc624\ub978\ucabd\uc5d0\ub294 \uc74c\uc2dd\uc744 \ub098\ub974\ub294 \uc778\ubb3c\uc774 \uc788\uc2b5\ub2c8\ub2e4.", "text": "\uc5e0\ub9c8\uc624\uc758 \uc21c\ub840\uc790\ub4e4 \u2014 \uc2dd\ud0c1\uc5d0\uc11c \ub0af\uc120 \uc774\ub97c \uc54c\uc544\ubcf4\ub294 \uc21c\uac04 \ub818\ube0c\ub780\ud2b8\uac00 \ube75\uacfc \ube5b\uc73c\ub85c \ub9cc\ub4e0 \uc870\uc6a9\ud55c \uc774\uc57c\uae30 \uc131\uc11c\uc758 \uc7a5\uba74\uacfc \ud654\uba74 \uc18d \uc190\u00b7\uc2dc\uc120\u00b7\ube48 \uacf5\uac04\uc744 \ud568\uaed8 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Art \ubb38\ud654 \uc5b4\ub450\uc6b4 \ubc29 \ud55c\uac00\uc6b4\ub370 \uc791\uc740 \uc2dd\ud0c1\uc774 \uc788\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \uc549\uc544 \uc788\uace0 \uc606\uc5d0\uc11c\ub294 \uc74c\uc2dd\uc744 \uac00\uc838\uc628\ub2e4. \uadf8\ub7f0\ub370 \uc774 \ud3c9\ubc94\ud55c \uc2dd\uc0ac \uc548\uc5d0\uc11c \ud568\uaed8 \uc788\ub358 \uc0ac\ub78c\uc774 \ub204\uad6c\uc778\uc9c0 \uc54c\uc544\ubcf4\ub294 \uc0ac\uac74\uc774 \uc77c\uc5b4\ub09c\ub2e4. \ub818\ube0c\ub780\ud2b8\uc758 \u3008\uc5e0\ub9c8\uc624\uc758 \uc21c\ub840\uc790\ub4e4\u3009\uc774\ub2e4. \uc774 \uc791\ud488\uc740 \ud070 \ubab8\uc9d3\uacfc \uad70\uc911\uc73c\ub85c \uc774\uc57c\uae30\ub97c \uc804\ub2ec\ud558\uc9c0 \uc54a\ub294\ub2e4. \ube75\uc744 \uc7a1\uc740 \uc190\uacfc \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uc758 \ubc18\uc751, \uc778\ubb3c \uc704\ub85c \ub0a8\uaca8\uc9c4 \ub113\uc740 \ubcbd\uc774 \uc7a5\uba74\uc758 \ud798\uc744 \ub9cc\ub4e0\ub2e4. \uba3c\uc800 \ubb34\uc2a8 \uc774\uc57c\uae30\uc778\uc9c0 \uc870\uae08 \uc54c\uace0 \uadf8\ub9bc\uc744 \ubcf4\uba74 \uc870\uc6a9\ud55c \uc2dd\ud0c1\uc758 \uae34\uc7a5\uc774 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uc774 \uc7a5\uba74\uc740 \ubd80\ud65c\ud55c \uc608\uc218\uac00 \uc5e0\ub9c8\uc624\ub85c \uac00\ub294 \uc81c\uc790\ub4e4\uacfc \ub9cc\ub098\ub294 \uae30\ub3c5\uad50\uc758 \uc774\uc57c\uae30\uc640 \uc774\uc5b4\uc9c4\ub2e4. \uc81c\uc790\ub4e4\uc740 \uae38\uc5d0\uc11c \ud568\uaed8 \uac77\uace0 \uc774\uc57c\uae30\ud558\uba74\uc11c\ub3c4 \ub3d9\ud589\ud55c \uc0ac\ub78c\uc774 \ub204\uad6c\uc778\uc9c0 \uc54c\uc544\ubcf4\uc9c0 \ubabb\ud558\ub2e4\uac00 \uc2dd\ud0c1\uc5d0\uc11c \ube75\uc744 \ub098\ub204\ub294 \ud589\uc704\ub97c \ud1b5\ud574 \uc54c\uc544\ubcf8\ub2e4. \uc81c\ubaa9 \uc18d \ub0af\uc120 \uc9c0\uba85\uc744 \ubaa8\ub450 \uc678\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \ud575\uc2ec\uc740 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uacc1\uc5d0 \uc788\uc73c\uba74\uc11c\ub3c4 \uc54c\uc544\ubcf4\uc9c0 \ubabb\ud588\ub358 \uc0ac\ub78c\uc744 \uc77c\uc0c1\uc801\uc778 \ud589\ub3d9 \ud558\ub098\uc5d0\uc11c \ub2e4\uc2dc \ubcf4\uac8c \ub418\ub294 \uc21c\uac04\uc774\ub2e4. \uadf8\ub9bc\uc758 \uc885\uad50\uc801 \uc8fc\uc81c\ub97c \uc9c0\uc6b0\uc9c0 \uc54a\uc73c\uba74\uc11c\ub3c4, \uac00\uae4c\uc6b4 \uc774\ub97c \uc774\ud574\ud558\ub294 \uc77c\uc774 \uc5b8\uc81c \uc77c\uc5b4\ub098\ub294\uc9c0\uc5d0 \uad00\ud55c \uac10\uac01\uc73c\ub85c \ub2e4\uac00\uac08 \uc218 \uc788\ub2e4. \ud654\uba74 \uac00\uc6b4\ub370\uc5d0\ub294 \uc608\uc218\uac00 \uc549\uc544 \uc788\uace0 \ub450 \uc81c\uc790\uac00 \uc88c\uc6b0\uc5d0 \ub193\uc5ec \uc788\ub2e4. \uc5bc\uad74\ub9cc \ubcf4\ub294 \ub370\uc11c \uadf8\uce58\uc9c0 \ub9d0\uace0 \uc190\uacfc \uc2dd\ud0c1\uc758 \ube75\uc73c\ub85c \ub208\uc744 \ub0b4\ub824 \ubcf4\uc790. \uc774\uc57c\uae30\uc5d0\uc11c \uc54c\uc544\ubd04\uc758 \uacc4\uae30\uac00 \ub418\ub294 \ud589\ub3d9\uc774 \ubc14\ub85c \uadf8\uacf3\uc5d0 \ub193\uc5ec \uc788\ub2e4. \uc0c1\uc9d5\uc744 \ub9ce\uc774 \uc54c\uc544\uc57c\ub9cc \uc774\ud574\ud560 \uc218 \uc788\ub294 \uadf8\ub9bc\ucc98\ub7fc \ub290\uaef4\uc84c\ub2e4\uba74 \uc778\ubb3c\uc758 \ubab8\uc9d3\ubd80\ud130 \ubcf4\uba74 \ub41c\ub2e4. \ub204\uac00 \uc190\uc744 \ubaa8\uc73c\uace0 \ub204\uac00 \ubab8\uc744 \uc6c0\uc9c1\uc774\ub294\uc9c0, \uadf8 \uc6c0\uc9c1\uc784\uc774 \uc911\uc559\uc744 \uc5b4\ub5bb\uac8c \ud5a5\ud558\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\ub294 \uac83\uc774\ub2e4. \uc774\ub984\ud45c\ub97c \ud655\uc778\ud558\ub358 \ud654\uba74\uc774 \uc0ac\ub78c \uc0ac\uc774\uc758 \ubc18\uc751\uc73c\ub85c \ubc14\ub010\ub2e4. \ubc29\uc758 \ubaa8\ub4e0 \uacf3\uc774 \uac19\uc740 \ubc1d\uae30\ub85c \uadf8\ub824\uc838 \uc788\uc9c0\ub294 \uc54a\ub2e4. \uc2dd\ud0c1\uacfc \uc911\uc559\uc758 \uc778\ubb3c, \uc8fc\ubcc0\uc758 \uc5b4\ub450\uc6b4 \uc790\ub9ac\ub97c \ubc88\uac08\uc544 \ubcf4\uba74 \ub208\uc774 \uc5b4\ub514\uc5d0 \uba38\ubb34\ub294\uc9c0 \ub290\ub084 \uc218 \uc788\ub2e4. \uc61b \ub3c4\ub85d\uc740 \uc67c\ucabd\uc5d0\uc11c \ub4e4\uc5b4\uc624\ub294 \ube5b\uc744 \uc124\uba85\ud55c\ub2e4. \uc2e4\uc81c \ub3c4\ud310\uc5d0\uc11c\ub3c4 \ubc1d\uc740 \ubd80\ubd84\uacfc \uadf8\ub298\uc758 \ucc28\uc774\uac00 \uc7a5\uba74\uc744 \ubb36\ub294\ub2e4. \uc774\ub97c \ube5b \ud558\ub098\ud558\ub098\uac00 \ud2b9\uc815 \uad50\ub9ac\ub97c \uac00\ub9ac\ud0a4\ub294 \uc554\ud638\ub77c\uace0\ub9cc \ud574\uc11d\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc6b0\uc120 \ubc1d\uae30 \ub54c\ubb38\uc5d0 \uc5b4\ub5a4 \uc190\uacfc \uc5bc\uad74\uc774 \uac00\uae4c\uc6cc\uc9c0\ub294\uc9c0 \ubcf4\uc790. \ub818\ube0c\ub780\ud2b8\uc758 \ud68c\ud654\uc5d0\uc11c \ube5b\uc740 \uc0ac\ubb3c\uc758 \ud45c\uba74\uc744 \ub4dc\ub7ec\ub0b4\uba74\uc11c \ub3d9\uc2dc\uc5d0 \uc778\ubb3c\ub4e4\uc758 \uad00\uacc4\ub97c \ubcf4\uac8c \ud558\ub294 \uae38\uc774 \ub420 \uc218 \uc788\ub2e4. \uc778\ubb3c\ub4e4 \uc704\uc5d0\ub294 \ub113\uace0 \uc5b4\ub450\uc6b4 \uacf5\uac04\uc774 \ub0a8\uc544 \uc788\ub2e4. \uc0ac\ub78c\ub9cc \uc798\ub77c \ud655\ub300\ud558\uba74 \ub193\uce58\uae30 \uc26c\uc6b4 \ubd80\ubd84\uc774\ub2e4. \uc2dd\ud0c1\uc758 \ub192\uc774\uc640 \ubc29\uc758 \ud06c\uae30\ub97c \ud568\uaed8 \ubcf4\uba74 \uc791\uc740 \ubaa8\uc784\uc774 \ud070 \uacf5\uac04 \uc548\uc5d0 \uc870\uc6a9\ud788 \ub193\uc600\ub2e4\ub294 \ub290\ub08c\uc744 \ubc1b\uac8c \ub41c\ub2e4. \uc774 \uc5ec\ubc31\uc744 \uc4f8\ubaa8\uc5c6\ub294 \ubc30\uacbd\uc73c\ub85c \uc0dd\uac01\ud558\uc9c0 \ub9d0\uace0 \uc7a0\uae50 \uba38\ubb3c\ub7ec \ubcf4\uc790. \uc8fc\ubcc0\uc774 \ub35c \ubcf5\uc7a1\ud560\uc218\ub85d \uc2dd\ud0c1 \uac00\uae4c\uc774\uc758 \uc6c0\uc9c1\uc784\uc740 \ub354 \uc911\uc694\ud558\uac8c \ubcf4\uc77c \uc218 \uc788\ub2e4. \ud070 \uc0ac\uac74\uc744 \ud06c\uac8c \uadf8\ub824\uc57c\ub9cc \uc911\uc694\ud574\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uac10\uc0c1\uc744 \uac00\ub2a5\ud558\uac8c \ud558\ub294 \uad6c\uc131\uc774\ub2e4. \uc624\ub978\ucabd\uc5d0\ub294 \uc811\uc2dc\ub97c \ub4e4\uace0 \ub4e4\uc5b4\uc624\ub294 \uc80a\uc740 \uc778\ubb3c\uc774 \uc788\ub2e4. \uc911\uc559\uc758 \uc885\uad50\uc801 \uc0ac\uac74\uacfc \ud568\uaed8 \uc74c\uc2dd\uc744 \ub098\ub974\ub294 \uad6c\uccb4\uc801\uc778 \uc77c\uc774 \uac19\uc740 \ud654\uba74 \uc548\uc5d0 \ub193\uc778\ub2e4. \ucd08\uc6d4\uc801\uc778 \uc8fc\uc81c\uac00 \ud604\uc2e4\uc758 \uc0dd\ud65c \uacf5\uac04 \uc18d\uc5d0\uc11c \ud45c\ud604\ub418\ub294 \uac83\uc774\ub2e4. \ub204\uad6c\ub098 \uac19\uc740 \uc815\ub3c4\ub85c \ubb34\uc2a8 \uc77c\uc774 \ubc8c\uc5b4\uc9c0\ub294\uc9c0 \uc54c\uc544\ucc28\ub9ac\uace0 \uc788\ub2e4\uace0 \ub2e8\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uac01\uc790\uc758 \uc790\uc138\uc640 \uc2dc\uc120\uc774 \ub2e4\ub974\ub2e4\ub294 \uc810\uc744 \ubcf4\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc6b0\ub9ac\uac00 \uc911\uc694\ud55c \uc21c\uac04\uc744 \uacaa\uc744 \ub54c\ub3c4 \uc8fc\ubcc0\uc758 \ubaa8\ub4e0 \uc77c\uc774 \ub3d9\uc2dc\uc5d0 \uba48\ucd94\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc2dd\ud0c1\uc758 \uc0ac\uac74\uacfc \uc0dd\ud65c\uc758 \uc6c0\uc9c1\uc784\uc774 \uacb9\uccd0 \uc788\ub2e4. \uadf8\ub9bc\uc740 \ud55c \uc21c\uac04\uc744 \ubcf4\uc5ec \uc8fc\uc9c0\ub9cc, \uc774\uc57c\uae30\ub97c \uc54c\uace0 \ubcf4\uba74 \uadf8 \uc55e\ub4a4\uc758 \uc2dc\uac04\uc774 \ud568\uaed8 \ub5a0\uc624\ub978\ub2e4. \uc54c\uc544\ubcf4\uc9c0 \ubabb\ud588\ub358 \uae38 \uc704\uc758 \uc2dc\uac04, \ube75\uc744 \ub098\ub204\ub294 \uc9c0\uae08, \uadf8 \ub4a4 \ub2ec\ub77c\uc9c8 \uc774\ud574\uac00 \uac19\uc740 \ud654\uba74 \uc8fc\ubcc0\uc5d0 \ub193\uc774\ub294 \uc148\uc774\ub2e4. \ud68c\ud654\uac00 \uc815\uc9c0\ub41c \uc7a5\uba74\ub9cc \uc804\ub2ec\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub798\uc11c \ucc98\uc74c \ubcfc \ub54c\uc640 \uc904\uac70\ub9ac\ub97c \uc54c\uace0 \ub2e4\uc2dc \ubcfc \ub54c \uacbd\ud5d8\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uc9c0\uc2dd\uc774 \uadf8\ub9bc\uc744 \ubcf4\ub294 \uc77c\uc744 \ub300\uc2e0\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \uc790\uc138\uc640 \ubb3c\uac74\uc774 \uc5b4\ub5a4 \uc2dc\uac04\uacfc \uc5f0\uacb0\ub418\ub294\uc9c0 \uc54c\ub824 \uc900\ub2e4. \uc815\ubcf4\ub97c \ud558\ub098 \uc5bb\uace0 \ud654\uba74\uc73c\ub85c \ub3cc\uc544\uc624\ub294 \uc655\ubcf5\uc744 \uc990\uaca8 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uc61b \ub3c4\ub85d\uc740 \uc791\ud488\uc758 \uc11c\uba85\uc5d0 1648\ub144\uc744 \uc81c\uc2dc\ud55c\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 \uadf8 \ub3c4\ub85d\uc5d0 \uc218\ub85d\ub41c \uc2e4\uc81c \ud68c\ud654\uc758 \uc0c9\ucc44 \uc7ac\ud604 \uc790\ub8cc\ub2e4. \ub2f9\uc2dc \uc131\uc11c \uc7a5\uba74\uc744 \uc0c8\ub85c \uc0c1\uc0c1\ud55c \ud604\ub300 \uc0bd\ud654\uac00 \uc544\ub2c8\ub77c \ub818\ube0c\ub780\ud2b8\uc758 \ud654\uba74 \uad6c\uc131\uc744 \ubcf4\ub294 \ub370 \uc4f0\ub294 \uc790\ub8cc\ub2e4. \ub2e4\ub9cc \uc61b \uc778\uc1c4\ubb3c\uc774\ubbc0\ub85c \ud604\uc7ac \uc2e4\ubb3c\uc758 \uc0c9\uacfc \ud45c\uba74\uc744 \uc644\uc804\ud788 \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uadf8 \ucc28\uc774\ub97c \ubaa8\ub978 \ucc44 \uc138\ubd80 \uc0c9 \ud558\ub098\ub97c \ub2e8\uc815\ud558\uae30\ubcf4\ub2e4 \uc2dd\ud0c1\uc758 \ubc30\uce58\uc640 \ud070 \ubc1d\uae30, \uc0ac\ub78c \uc0ac\uc774\uc758 \uac70\ub9ac\ub97c \uc0b4\ud3b4\ubcf4\uba74 \uc88b\ub2e4. \ub3c4\ud310\uc774 \uac00\uc9c4 \uc870\uac74 \uc548\uc5d0\uc11c\ub3c4 \uac10\uc0c1\uc758 \uae38\uc740 \ucda9\ubd84\ud788 \uc5f4\ub9b0\ub2e4. \uadf8\ub9bc\uc744 \ud55c \ubc14\ud034 \ubcf4\uace0 \ub2e4\uc2dc \ube75\uc744 \ub098\ub204\ub294 \uc190\uc73c\ub85c \ub3cc\uc544\uc640 \ubcf4\uc790. \uc81c\uc790\ub4e4\uc774 \uc0ac\ub78c\uc744 \uc54c\uc544\ubcf4\ub294 \uacc4\uae30\ub294 \uc774\ub984\uc744 \uc0c8\ub85c \ub4e4\uc5c8\uae30 \ub54c\ubb38\ub9cc\uc774 \uc544\ub2c8\ub77c \uc775\uc219\ud55c \ud589\ub3d9\uc744 \ubcf4\uc558\uae30 \ub54c\ubb38\uc774\ub2e4. \uc774 \uc11c\uc0ac\ub294 \uadf8 \uc791\uc740 \uc778\uc2dd\uc758 \ubcc0\ud654\ub97c \uc911\uc2ec\uc5d0 \ub454\ub2e4. \ubaa8\ub4e0 \uad00\uac1d\uc774 \uc885\uad50\uc801 \ubbff\uc74c\uc744 \uacf5\uc720\ud558\uc9c0 \uc54a\uc544\ub3c4 \uc7a5\uba74\uc744 \uc77d\uc744 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uc791\ud488\uc774 \uac00\uc9c4 \uc885\uad50\uc801 \uc758\ubbf8\ub97c \uc5c6\uc560\uae30\ubcf4\ub2e4 \uadf8 \uc758\ubbf8\uac00 \uc5b4\ub5bb\uac8c \uad6c\uccb4\uc801\uc778 \uc190\uacfc \uc2dd\ud0c1\uc73c\ub85c \ud45c\ud604\ub418\uc5c8\ub294\uc9c0 \ubcf4\ub294 \uac83\uc774\ub2e4. \uc870\uc6a9\ud55c \ubc29\uc5d0\uc11c \ud55c \uc0ac\ub78c\uc744 \ub2e4\uc2dc \uc54c\uc544\ubcf4\ub294 \uc21c\uac04\uc774 \uc624\ub798 \ub0a8\ub294 \uadf8\ub9bc\uc774\ub2e4."}, {"id": "rembrandt-life-self-portraits", "title": "\ub818\ube0c\ub780\ud2b8\uc758 \uc0dd\uc560 \u2014 \uc5bc\uad74\uacfc \ube5b\uc744 \ub2e4\uc2dc \ubc14\ub77c\ubcf8 \uc2dc\uac04", "summary": "\ub300\ud45c\uc791\uacfc \uc0dd\ud65c\uc758 \ubcc0\ud654\ub97c \ud568\uaed8 \ub530\ub77c\uac00\uba70 \ube44\uadf9\uc758 \ucc9c\uc7ac\ub77c\ub294 \ub2e8\uc21c\ud55c \uadf8\ub9bc\uc744 \ub113\ud799\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Art", "url": "stories/rembrandt-life-self-portraits/index.html", "image": "media/rembrandt-life-self-portraits.jpg", "alt": "1640\ub144 \ub818\ube0c\ub780\ud2b8\uac00 \ub3cc \ub09c\uac04\uc5d0 \uae30\ub300 \uc120 \uc790\uc2e0\uc758 \ubaa8\uc2b5\uc744 \uadf8\ub9b0 \ucd08\uc0c1\uc758 \uc61b \uc7ac\ud604 \ub3c4\ud310.", "text": "\ub818\ube0c\ub780\ud2b8\uc758 \uc0dd\uc560 \u2014 \uc5bc\uad74\uacfc \ube5b\uc744 \ub2e4\uc2dc \ubc14\ub77c\ubcf8 \uc2dc\uac04 \ub808\uc774\ub358\uc5d0\uc11c \uc554\uc2a4\ud14c\ub974\ub2f4\uc73c\ub85c, \ucd08\uc0c1\uacfc \ud310\ud654\uc640 \uc790\ud654\uc0c1\uc758 \uae38 \ub300\ud45c\uc791\uacfc \uc0dd\ud65c\uc758 \ubcc0\ud654\ub97c \ud568\uaed8 \ub530\ub77c\uac00\uba70 \ube44\uadf9\uc758 \ucc9c\uc7ac\ub77c\ub294 \ub2e8\uc21c\ud55c \uadf8\ub9bc\uc744 \ub113\ud799\ub2c8\ub2e4. Art \ubb38\ud654 \uc5b4\ub5a4 \uc790\ud654\uc0c1\uc5d0\uc11c\ub294 \ud654\ub824\ud55c \uc637\uc744 \uc785\uc740 \uc0ac\ub78c\uc774 \uad00\uac1d\uc744 \ubc14\ub77c\ubcf4\uace0, \ub2e4\ub978 \uc790\ud654\uc0c1\uc5d0\uc11c\ub294 \ub098\uc774 \ub4e0 \uc5bc\uad74\uc774 \uc5b4\ub450\uc6b4 \ubc14\ud0d5\uc5d0\uc11c \ub4dc\ub7ec\ub09c\ub2e4. \ud55c \uc0ac\ub78c\uc774 \uc790\uae30 \ubaa8\uc2b5\uc744 \uc5ec\ub7ec \ubc88 \uadf8\ub838\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c\ub3c4 \uc624\ub798 \ubcfc \uc774\uc57c\uae30\uac00 \uc0dd\uae34\ub2e4. \ub818\ube0c\ub780\ud2b8\uc758 \uc5bc\uad74\uc740 \uc0dd\uc560\ub97c \uc0dd\uac01\ud558\uac8c \ud558\ub294 \uc5ec\ub7ec \uc785\uad6c \uc911 \ud558\ub098\ub2e4. \uadf8\ub294 17\uc138\uae30 \ub124\ub35c\ub780\ub4dc\uc5d0\uc11c \ucd08\uc0c1\uacfc \uc885\uad50\ud654, \ud310\ud654 \ub4f1\uc744 \ub9cc\ub4e4\uc5c8\ub2e4. \uc131\uacf5\uacfc \uc0c1\uc2e4\uc774\ub77c\ub294 \ud070 \ub2e8\uc5b4\ub85c\ub9cc \uc815\ub9ac\ud558\uae30\ubcf4\ub2e4 \uc5b4\ub5a4 \uc0ac\ub78c\ub4e4\uc744 \uc5b4\ub5bb\uac8c \uadf8\ub838\uace0 \uc790\uae30 \ubaa8\uc2b5\uc744 \uc5b4\ub5bb\uac8c \ub2e4\uc2dc \ubcf4\uc558\ub294\uc9c0 \ub530\ub77c\uac00 \ubcf4\uc790. \uc5b4\ub450\uc6b4 \uadf8\ub9bc\uc744 \ub0a8\uae34 \uc2ac\ud508 \ud654\uac00\ub77c\ub294 \uc778\uc0c1\ubcf4\ub2e4 \ub113\uc740 \uc0b6\uc774 \ubcf4\uc778\ub2e4. \ub808\uc774\ub358\uc5d0\uc11c \uc790\ub780 \ub818\ube0c\ub780\ud2b8\ub294 \uadf8\ub9bc\uc744 \ubc30\uc6b0\uace0 \uc791\uc5c5\uc744 \uc2dc\uc791\ud588\ub2e4. \ucc98\uc74c\ubd80\ud130 \uc624\ub298\ub0a0\uc758 \uc774\ub984\uac12\uc744 \uac00\uc9c4 \uac70\uc7a5\uc774\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc7ac\ub8cc\uc640 \ud45c\ud604\uc744 \uc775\ud788\uace0 \ub2e4\ub978 \uadf8\ub9bc\uc744 \ubcf4\uba70 \uc5b4\ub5a4 \uc7a5\uba74\uc744 \ub9cc\ub4e4\uc9c0 \ucc3e\uc544\uac00\ub294 \uc2dc\uac04\uc774 \uc788\uc5c8\ub2e4. \uc804\uae30\ub294 \uc720\ub144\uc758 \uc77c\ud654\ub97c \uc7ac\ubbf8\uc788\uac8c \uc804\ud558\uc9c0\ub9cc \ubaa8\ub4e0 \uae30\uc5b5\uc744 \uc644\ubcbd\ud55c \ud604\uc7a5 \uae30\ub85d\uc73c\ub85c \ubcfc \uc218\ub294 \uc5c6\ub2e4. \ub300\uc2e0 \ucd08\uae30\uc758 \ubc30\uc6c0\uacfc \uc791\uc5c5\uc774\ub77c\ub294 \uc2e4\uc81c \uacfc\uc815\uc744 \uc0dd\uac01\ud558\uba74 \uc88b\ub2e4. \uc778\ubb3c\uc758 \ud45c\uc815\uacfc \ube5b, \uc774\uc57c\uae30\ub97c \ud55c \ud654\uba74\uc5d0 \ub193\ub294 \ub2a5\ub825\ub3c4 \uc5f0\uc2b5\uacfc \uad00\ucc30\uc744 \ud1b5\ud574 \ub2e4\ub4ec\uc5b4 \uac14\ub2e4. \uc554\uc2a4\ud14c\ub974\ub2f4\uc73c\ub85c \uc62e\uae34 \ub4a4\uc5d0\ub294 \uc758\ub8b0\uc778\uacfc \uc8fc\ubb38, \uacb0\ud63c\uacfc \uc0dd\ud65c\uc774 \uc774\uc5b4\uc9c4\ub2e4. \uc0ac\uc2a4\ud0a4\uc544\uc640\uc758 \uad00\uacc4\ub3c4 \uc774 \uc0b6\uc758 \uc911\uc694\ud55c \ubd80\ubd84\uc774\ub2e4. \ub3c4\uc2dc\uc5d0\uc11c \uc0ac\ub78c\uc758 \ucd08\uc0c1\uc744 \uadf8\ub9b0\ub2e4\ub294 \uac83\uc740 \uc5bc\uad74\uc744 \uc798 \ubb18\uc0ac\ud558\ub294 \uc77c\ubfd0 \uc544\ub2c8\ub77c \uadf8 \uc0ac\ud68c\uc758 \uad00\uacc4 \uc18d\uc5d0\uc11c \uc77c\ud558\ub294 \ubb38\uc81c\uc774\uae30\ub3c4 \ud588\ub2e4. \uc778\ubb3c\ub4e4\uc740 \uc790\uc2e0\uc758 \ubaa8\uc2b5\uc774 \uc5b4\ub5a4 \uadf8\ub9bc\uc73c\ub85c \ub0a8\uc744\uc9c0 \uae30\ub300\ud588\uc744 \uac83\uc774\ub2e4. \ud654\uac00\ub294 \uadf8\ub7f0 \uc694\uad6c\uc640 \uc790\uae30 \ud45c\ud604\uc758 \uc120\ud0dd \uc0ac\uc774\uc5d0\uc11c \ud654\uba74\uc744 \ub9cc\ub4e0\ub2e4. \uc791\ud488\uc774 \ud6cc\ub96d\ud558\ub2e4\ub294 \uc624\ub298\uc758 \ud3c9\uac00\ub9cc\uc73c\ub85c \ub2f9\uc2dc\uc758 \ubaa8\ub4e0 \uc758\ub8b0 \uad00\uacc4\uae4c\uc9c0 \uc21c\uc870\ub85c\uc6e0\ub2e4\uace0 \uc0dd\uac01\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc77c\uc758 \uc870\uac74\uacfc \uacb0\uacfc\ub294 \ud568\uaed8 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \u3008\ud288\ud504 \ubc15\uc0ac\uc758 \ud574\ubd80\ud559 \uac15\uc758\u3009\ub098 \ud754\ud788 \u3008\uc57c\uacbd\u3009\uc774\ub77c \ubd80\ub974\ub294 \uc2dc\ubbfc\uacbd\ube44\ub300\uc758 \uc9d1\ub2e8\ucd08\uc0c1\uc5d0\uc11c\ub294 \uc5ec\ub7ec \uc778\ubb3c\uc744 \ud55c \ud654\uba74\uc5d0 \ubb36\ub294\ub2e4. \ubaa8\ub450\uac00 \uac19\uc740 \ubc29\ud5a5\uc744 \ubc14\ub77c\ubcf4\uace0 \uac19\uc740 \uc790\uc138\ub97c \ucde8\ud558\ub294 \ubaa9\ub85d\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \uad00\uc2ec\uacfc \uc6c0\uc9c1\uc784\uc758 \ucc28\uc774\uac00 \ubaa8\uc784\uc758 \uc131\uaca9\uc744 \ub9cc\ub4e0\ub2e4. \ud2b9\ud788 \u3008\uc57c\uacbd\u3009\uc774\ub77c\ub294 \uc774\ub984\ub9cc \ubcf4\uace0 \ud55c\ubc24\uc758 \uadfc\ubb34 \uc7a5\uba74\uc774\ub77c\uace0 \ud655\uc815\ud558\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc61b \uc791\ud488 \ud574\uc124\ub3c4 \uc774 \uc720\uba85\ud55c \ud638\uce6d\uc758 \ubb38\uc81c\ub97c \uc9da\ub294\ub2e4. \uc81c\ubaa9\uc744 \uc544\ub294 \uc77c\uc5d0\uc11c \ucd9c\ubc1c\ud574, \uc2e4\uc81c\ub85c \uc0ac\ub78c\ub4e4\uc758 \ubab8\uc774 \uc5b4\ub5bb\uac8c \uc6c0\uc9c1\uc774\uace0 \ube5b\uc774 \uc5b4\ub514\uc5d0 \ub193\uc774\ub294\uc9c0 \ubcf4\ub294 \ucabd\uc73c\ub85c \ub098\uc544\uac08 \uc218 \uc788\ub2e4. \ub818\ube0c\ub780\ud2b8\ub294 \ud68c\ud654\ubfd0 \uc544\ub2c8\ub77c \uc5d0\uce6d \uac19\uc740 \ud310\ud654 \uc791\uc5c5\ub3c4 \ud588\ub2e4. \uae08\uc18d\ud310\uc5d0 \uc120\uc744 \ub9cc\ub4e4\uace0 \uc778\uc1c4\ud558\ub294 \uacfc\uc815\uc5d0\uc11c\ub294 \uc0c9\uc774 \ub113\uac8c \ub193\uc774\ub294 \uadf8\ub9bc\uacfc \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \ube5b\uacfc \uacf5\uac04\uc744 \ud45c\ud604\ud55c\ub2e4. \uc791\uc740 \uc120\uacfc \ube44\uc5b4 \uc788\ub294 \uc790\ub9ac\uac00 \ud070 \uc5ed\ud560\uc744 \ud560 \uc218 \uc788\ub2e4. \uc720\uba85\ud55c \uc720\ud654 \uba87 \uc810\ub9cc \uae30\uc5b5\ud558\uba74 \uc774 \uc791\uc5c5\uc758 \ud3ed\uc744 \ub193\uce58\uae30 \uc27d\ub2e4. \ud55c \uc791\uac00\uac00 \uc5b8\uc81c\ub098 \uac19\uc740 \uc7ac\ub8cc\ub85c \uac19\uc740 \ud6a8\uacfc\ub9cc \ucc3e\uc740 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ud310\ud654\uc640 \uadf8\ub9bc\uc744 \ubc88\uac08\uc544 \ubcf4\uba74 \uc5bc\uad74\uacfc \ubab8, \uc0dd\ud65c\uacfc \uc131\uc11c \uc774\uc57c\uae30\ub97c \ub2e4\ub8e8\ub294 \uad00\uc2ec\uc774 \uc11c\ub85c \ub2e4\ub978 \uc7ac\ub8cc \uc548\uc5d0\uc11c \uc774\uc5b4\uc9c0\ub294 \ubaa8\uc2b5\uc744 \ubcfc \uc218 \uc788\ub2e4. \uc790\ud654\uc0c1\uc744 \uadf8\ub9b0\ub2e4\ub294 \uac83\uc740 \uc790\uae30 \uc778\uc0dd\uc744 \uae30\ub85d\ud558\ub294 \uc77c\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc \uadf8\uac83\ub9cc\uc73c\ub85c \uc124\uba85\ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \uac00\uae4c\uc774 \uc788\ub294 \ubaa8\ub378\uc744 \ud1b5\ud574 \ud45c\uc815\uacfc \ube5b, \uc637\uacfc \uc790\uc138\ub97c \uc2e4\ud5d8\ud560 \uc218\ub3c4 \uc788\ub2e4. \uc624\ub298\uc758 \ub3c5\uc790\ub294 \uac19\uc740 \uc0ac\ub78c\uc774 \uc5ec\ub7ec \ubaa8\uc2b5\uc73c\ub85c \ub098\ud0c0\ub098\ub294 \uc2dc\uac04\uc744 \ud568\uaed8 \ubcf4\uac8c \ub41c\ub2e4. \uc80a\uc740 \uc790\ud654\uc0c1\uacfc \ub2a6\uc740 \uc790\ud654\uc0c1\uc744 \ube44\uad50\ud558\uba70 \uc0dd\uc560\uc758 \ucc28\uc774\ub97c \ub290\uaef4\ub3c4 \uc88b\ub2e4. \ub2e4\ub9cc \uc5bc\uad74\uc5d0 \ubcf4\uc774\ub294 \ubaa8\ub4e0 \uc8fc\ub984\uc744 \ud2b9\uc815\ud55c \uc0ac\uac74\uc758 \uacb0\uacfc\ub77c\uace0 \uc77d\uc744 \uc218\ub294 \uc5c6\ub2e4. \uc791\ud488\uc740 \ub0a0\uc9dc\uc640 \uc790\ub8cc\uc758 \ub3c4\uc6c0\uc744 \ubc1b\uc544 \uc774\ud574\ud558\ub294 \ud68c\ud654\uc774\uc9c0, \uacfc\uac70\uc758 \uac10\uc815\uacfc \ubcd1\uc744 \ubaa8\ub450 \ud310\ub3c5\ud560 \uc218 \uc788\ub294 \uac80\uc0ac\ud45c\ub294 \uc544\ub2c8\ub2e4. \uc0ac\uc2a4\ud0a4\uc544\ub97c \ube44\ub86f\ud55c \uac00\uae4c\uc6b4 \uc0ac\ub78c\ub4e4\uc758 \uc0c1\uc2e4\uacfc \uc7ac\uc815\uc758 \uc5b4\ub824\uc6c0\uc740 \uadf8\uc758 \uc0dd\uc560\uc5d0\uc11c \uc911\uc694\ud55c \uc0ac\uac74\uc774\ub2e4. \ud2f0\ud22c\uc2a4\uc640 \uc8fc\ubcc0 \uc0ac\ub78c\ub4e4 \uc5ed\uc2dc \uc791\ud488\uacfc \uc0dd\ud65c \uc18d\uc5d0 \uc790\ub9ac\ub97c \uac00\uc9c4\ub2e4. \uc0ac\ub78c\uc744 \uadf8\ub9ac\ub294 \uc791\uc5c5\uacfc \uadf8 \uc0ac\ub78c\ub4e4\uacfc \uc0b4\uc544\uac00\ub294 \uc77c\uc740 \uac19\uc740 \uc2dc\uac04 \uc548\uc5d0 \uc788\uc5c8\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc5b4\ub5a4 \ub300\ud45c\uc791\uc774 \uc2e4\ud328\ud574 \uace7\ubc14\ub85c \ubaa8\ub4e0 \uac83\uc744 \uc783\uc5c8\ub2e4\ub294 \ub2e8\uc21c\ud55c \ucd94\ub77d\uc758 \uc774\uc57c\uae30\ub85c \uc815\ub9ac\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ud6c4\ub300 \uc804\uae30\uc5d0\ub294 \uadf9\uc801\uc778 \uc77c\ud654\uac00 \ub367\ubd99\uae30\ub3c4 \ud55c\ub2e4. \ud655\uc778\ub418\ub294 \uc0ac\uac74\uc744 \ubcf4\ub418 \uc791\ud488 \uc804\uccb4\uac00 \ubd88\ud589 \ud558\ub098\uc5d0\uc11c \uc790\ub3d9\uc73c\ub85c \ub098\uc654\ub2e4\uace0 \uc0dd\uac01\ud558\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc0ac\ub78c\uacfc \uadf8\ub9bc\uc744 \ub354 \uc798 \uc774\ud574\ud558\uac8c \ud55c\ub2e4. \ub2a6\uc740 \uc2dc\uae30\uc5d0\ub3c4 \uadf8\ub294 \ucd08\uc0c1\uacfc \uc5ec\ub7ec \uc774\uc57c\uae30\ub97c \uadf8\ub838\ub2e4. \ud070 \uc774\ub984\uc73c\ub85c \uc54c\ub824\uc9c4 \uc791\ud488\ub4e4\ub9cc\uc774 \uc544\ub2c8\ub77c \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc5bc\uad74\uc744 \uc5b4\ub5bb\uac8c \ubcf4\uc774\uac8c \ud560\uc9c0 \ud310\ub2e8\ud558\ub294 \uc791\uc5c5\uc774 \uc774\uc5b4\uc84c\ub2e4. \uc0b6\uc774 \uc5b4\ub824\uc6cc\uc84c\ub2e4\ub294 \ud55c \uc904\uc774 \uadf8 \ub4a4\uc758 \ubaa8\ub4e0 \uc2dc\uac04\uc744 \uc124\uba85\ud558\uc9c0\ub294 \ubabb\ud55c\ub2e4. \uadf8\ub294 1669\ub144\uc5d0 \uc138\uc0c1\uc744 \ub5a0\ub0ac\ub2e4. \uc624\ub298\uc758 \uba85\uc131\uacfc \ub2f9\ub300\uc758 \uc0dd\ud65c\uc744 \uc644\uc804\ud788 \uac19\uc740 \uac83\uc73c\ub85c \ub193\uc744 \uc218\ub294 \uc5c6\uc9c0\ub9cc, \uc78a\ud78c \ucc9c\uc7ac\ub77c\ub294 \ud45c\ud604 \ud558\ub098\ub85c\ub3c4 \uc791\uc5c5\uc758 \uad00\uacc4\uac00 \ub2e4 \ub2f4\uae30\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub0a8\uc740 \uadf8\ub9bc\uacfc \ud310\ud654\uac00 \uac01\uac01 \uc5b4\ub5a4 \uc2dc\uac04\uc744 \ubcf4\uc5ec \uc8fc\ub294\uc9c0 \ucc28\ub840\ub85c \ubcf4\ub294 \ud3b8\uc774 \ub354 \ud48d\ubd80\ud558\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 1640\ub144 \ub818\ube0c\ub780\ud2b8\uac00 \ub3cc \ub09c\uac04\uc5d0 \uae30\ub300 \uc120 \ubaa8\uc2b5\uc744 \uadf8\ub9b0 \uc790\ud654\uc0c1\uc758 \uc61b \uc7ac\ud604 \ub3c4\ud310\uc774\ub2e4. \ubaa8\uc790\uc640 \uc637, \ud314\uc758 \uc704\uce58\uac00 \uc5bc\uad74\uacfc \ud568\uaed8 \uad00\uac1d\uc744 \ud5a5\ud558\ub294 \uc778\uc0c1\uc744 \ub9cc\ub4e0\ub2e4. \uc2e4\uc81c \uc791\ud488\uc758 \uad6c\uc131\uc744 \ubcf4\ub294 \uc790\ub8cc\uc774\uba70 \uc0c8\ub85c \uc0c1\uc0c1\ud55c \ucd08\uc0c1\uc774 \uc544\ub2c8\ub2e4. \ud55c \uc0ac\ub78c\uc758 \uc0dd\uc560\ub97c \uc77d\uc740 \ub4a4 \uc774 \uc5bc\uad74\ub85c \ub3cc\uc544\uc624\uba74 \uc131\uacf5\uc774\ub098 \ube44\uadf9 \uac00\uc6b4\ub370 \ud558\ub098\ub9cc \uace0\ub97c \ud544\uc694\uac00 \uc5c6\uc5b4\uc9c4\ub2e4. \uc77c\ud558\uace0 \uad00\ucc30\ud558\uace0 \uc790\uae30 \ubaa8\uc2b5\uc744 \ub2e4\uc2dc \uadf8\ub9b0 \uc2dc\uac04\uc774 \ud568\uaed8 \ub5a0\uc624\ub978\ub2e4. \ub818\ube0c\ub780\ud2b8\uc758 \uad50\uc591\uc740 \uc5b4\ub450\uc6b4 \ubc14\ud0d5\uc758 \ud654\uac00\ub77c\ub294 \uc774\ub984\uc744 \uc678\uc6b0\ub294 \uac83\uc5d0\uc11c, \uc5ec\ub7ec \uc5bc\uad74\uacfc \ube5b\uc744 \uad6c\uccb4\uc801\uc73c\ub85c \ubcf4\ub294 \ucabd\uc73c\ub85c \ub113\uc5b4\uc9c8 \uc218 \uc788\ub2e4."}, {"id": "schubert-erlking-four-voices", "title": "\uc288\ubca0\ub974\ud2b8 \ub9c8\uc655 \u2014 \ud55c \uac00\uc218\uac00 \ub124 \uc0ac\ub78c\uc744 \ub178\ub798\ud560 \ub54c", "summary": "\uad34\ud14c\uc758 \uc2dc\uc5d0 \ubd99\uc778 \uac00\uace1\uc758 \uc904\uac70\ub9ac\uc640 \uac01 \uc778\ubb3c\uc758 \uc18c\ub9ac\ub97c \ub530\ub77c \ub4e3\uc2b5\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Music", "url": "stories/schubert-erlking-four-voices/index.html", "image": "media/schubert-erlking-four-voices.jpg", "alt": "\uc288\ubca0\ub974\ud2b8 \ub9c8\uc655\uc758 \uc81c2\ud310\uc744 \uc704\ud574 \uc81c\uc791\ub41c \uc61b \ud310\ud654. \ub9d0\uc744 \ud0c0\uace0 \ub2ec\ub9ac\ub294 \uc778\ubb3c\uacfc \uc8fc\uc704\uc758 \ud658\uc0c1\uc801 \ud615\uc0c1\uc774 \ud45c\ud604\ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.", "text": "\uc288\ubca0\ub974\ud2b8 \ub9c8\uc655 \u2014 \ud55c \uac00\uc218\uac00 \ub124 \uc0ac\ub78c\uc744 \ub178\ub798\ud560 \ub54c \ub2ec\ub9ac\ub294 \ub9d0\uacfc \ub124 \ubaa9\uc18c\ub9ac, \ud53c\uc544\ub178\uac00 \ub9cc\ub4dc\ub294 \ub610 \ud558\ub098\uc758 \uc774\uc57c\uae30 \uad34\ud14c\uc758 \uc2dc\uc5d0 \ubd99\uc778 \uac00\uace1\uc758 \uc904\uac70\ub9ac\uc640 \uac01 \uc778\ubb3c\uc758 \uc18c\ub9ac\ub97c \ub530\ub77c \ub4e3\uc2b5\ub2c8\ub2e4. Music \ubb38\ud654 \ubc24\uae38\uc744 \ub9d0\uc744 \ud0c0\uace0 \ub2ec\ub9ac\ub294 \uc544\ubc84\uc9c0\uac00 \uc788\ub2e4. \ud488 \uc548\uc758 \uc544\uc774\ub294 \ubb34\uc5b8\uac00\ub97c \ubcf4\uace0 \ub450\ub824\uc6cc\ud558\uace0, \uc544\ubc84\uc9c0\ub294 \uc544\uc774\ub97c \ub2ec\ub798\uba70 \uacc4\uc18d \ub098\uc544\uac04\ub2e4. \uc5ec\uae30\uc5d0 \ub204\uad70\uac00 \ub2ec\ucf64\ud55c \ub9d0\ub85c \uc544\uc774\ub97c \ubd80\ub978\ub2e4. \ub124 \uc0ac\ub78c\uc774 \uc11c\ub85c \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \ub9d0\ud558\ub294 \uc774\uc57c\uae30\uc778\ub370, \ubb34\ub300\uc5d0\ub294 \uac00\uc218 \ud55c \uba85\uacfc \ud53c\uc544\ub2c8\uc2a4\ud2b8 \ud55c \uba85\uc774 \uc788\uc744 \uc218 \uc788\ub2e4. \uc288\ubca0\ub974\ud2b8\uc758 \uac00\uace1 \u3008\ub9c8\uc655\u3009\uc774\ub2e4. \uad34\ud14c\uc758 \uc2dc\uc5d0 \uc74c\uc545\uc744 \ubd99\uc778 \uc791\ud488\uc73c\ub85c, \ud655\uc778\ud55c \uc545\ubcf4\ub294 1815\ub144\uacfc D.328\uc774\ub77c\ub294 \ubc88\ud638\ub97c \uc81c\uc2dc\ud55c\ub2e4. \uc774 \uae00\uc5d0\ub294 \ub178\ub798\uc758 \ub9c8\uc9c0\ub9c9 \uc7a5\uba74\uae4c\uc9c0 \ud3ec\ud568\ub418\uc5b4 \uc788\ub2e4. \ub3c5\uc77c\uc5b4 \uc81c\ubaa9\uc740 Erlk\u00f6nig\ub2e4. \uc288\ubca0\ub974\ud2b8\ub294 \uad34\ud14c\uc758 \uc2dc\uac00 \uac00\uc9c4 \uc774\uc57c\uae30\ub97c \uc131\uc545\uacfc \ud53c\uc544\ub178\uc758 \uc2dc\uac04\uc73c\ub85c \uc62e\uacbc\ub2e4. \ub178\ub798\uac00 \ub2e8\uc21c\ud788 \uc2dc\ub97c \uc608\uc05c \uba5c\ub85c\ub514\ub85c \uc77d\uc5b4 \uc8fc\ub294 \uac83\ub9cc\uc740 \uc544\ub2c8\ub2e4. \ub4f1\uc7a5\uc778\ubb3c\uc758 \ucc28\uc774\uc640 \uae34\ubc15\ud55c \uc9c4\ud589\uc744 \uc18c\ub9ac\uc758 \uad00\uacc4\ub85c \ub9cc\ub4e0\ub2e4. \ud55c\uad6d\uc5b4 \uc81c\ubaa9\uc758 \ub9c8\uc655\uc744 \ub4e3\uace0 \uc5b4\ub5a4 \uc885\uad50\uc758 \uc545\ub9c8\ub97c \uba3c\uc800 \ub5a0\uc62c\ub9b4 \uc218\ub3c4 \uc788\uc9c0\ub9cc, \uc5ec\uae30\uc11c\ub294 \uc544\uc774\ub97c \ubd80\ub974\ub294 \ucd08\uc6d4\uc801\uc778 \uc874\uc7ac\uac00 \uc2dc \uc18d\uc5d0\uc11c \uc5b4\ub5a4 \uc5ed\ud560\uc744 \ud558\ub294\uc9c0\ubd80\ud130 \ubcf4\uba74 \uc88b\ub2e4. \uc774\ub984\uc5d0 \uad00\ud55c \uc0c1\uc0c1\uc744 \ub113\ud788\uae30 \uc804\uc5d0, \ud55c \ud3b8\uc758 \uc774\uc57c\uae30 \uc548\uc5d0\uc11c \uc2e4\uc81c\ub85c \ubb34\uc2a8 \uc77c\uc774 \ubc8c\uc5b4\uc9c0\ub294\uc9c0 \ub530\ub77c\uac00\ub294 \uac83\uc774\ub2e4. \uccab\uba38\ub9ac\uc758 \ud53c\uc544\ub178\uc5d0\uc11c\ub294 \uc74c\ub4e4\uc774 \ucd18\ucd18\ud558\uac8c \ubc18\ubcf5\ub41c\ub2e4. \ub9d0\uc744 \ud0c0\uace0 \uae09\ud788 \ub2ec\ub9ac\ub294 \uc6c0\uc9c1\uc784\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \uc18c\ub9ac\ub2e4. \uc131\uc545\uc774 \uc5c6\uc744 \ub54c\uc5d0\ub3c4 \uc774\ubbf8 \uc7a5\uba74\uc758 \uc18d\ub3c4\uc640 \uae34\uc7a5\uc774 \ud615\uc131\ub41c\ub2e4. \ubc18\uc8fc\ub77c\ub294 \ub9d0\ub9cc \ub4e3\uace0 \ub4a4\uc5d0 \uae54\ub9ac\ub294 \uc7a5\uc2dd\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uba74 \ub193\uce58\ub294 \ubd80\ubd84\uc774\ub2e4. \uac19\uc740 \uc74c\uc744 \ubc18\ubcf5\ud558\ub294 \uac83\uc740 \uc5f0\uc8fc\uc790\uc5d0\uac8c\ub3c4 \uc26c\uc6b4 \uc77c\ub9cc\uc740 \uc544\ub2c8\ub2e4. \uacc4\uc18d \uc6c0\uc9c1\uc774\ub294 \ud798\uc744 \uc720\uc9c0\ud558\uba74\uc11c \ub178\ub798\uc640 \uc5b4\uc6b8\ub824\uc57c \ud55c\ub2e4. \ub4e3\ub294 \uc0ac\ub78c\uc740 \uae30\uc220\uc744 \ud3c9\uac00\ud558\ub824 \uc560\uc4f0\uc9c0 \uc54a\uace0, \uc774 \ubc18\ubcf5\uc774 \uba48\ucd94\uc9c0 \uc54a\uae30 \ub54c\ubb38\uc5d0 \ubaa9\uc18c\ub9ac\ub4e4\uc774 \uc5b4\ub5a4 \uc0c1\ud669 \uc18d\uc5d0\uc11c \ub4e4\ub9ac\ub294\uc9c0 \ub290\uaef4 \ubcf4\uba74 \ub41c\ub2e4. \ucc98\uc74c\uc5d0\ub294 \ud654\uc790\uac00 \ubc24\uae38\uc758 \uc7a5\uba74\uc744 \uc81c\uc2dc\ud55c\ub2e4. \ub204\uac00 \ub2ec\ub9ac\uace0 \ub204\uad6c\ub97c \uc548\uace0 \uc788\ub294\uc9c0 \uc54c\ub824 \uc8fc\uba70 \uccad\uc911\uc744 \uc774\uc57c\uae30 \uc548\uc73c\ub85c \ub4e4\uc778\ub2e4. \uac00\uc218\ub294 \uc774 \ubaa9\uc18c\ub9ac\uc5d0\uc11c \uc544\ubc84\uc9c0\uc640 \uc544\uc774\uc758 \ub9d0\ub85c \uace7 \uc62e\uaca8 \uac00\uc57c \ud55c\ub2e4. \uc5ec\ub7ec \ubc30\uc5ed\uc774 \ub098\ub204\uc5b4 \ub4f1\uc7a5\ud558\ub294 \uc5f0\uadf9\uacfc\ub294 \ub2e4\ub978 \ubc29\uc2dd\uc774\ub2e4. \uac00\uc0ac\ub97c \ubbf8\ub9ac \uc77d\uc5b4 \ub450\uba74 \uac00\uc218\uac00 \ubc14\ub00c\uc9c0 \uc54a\ub294\ub370\ub3c4 \uc5ed\ud560\uc774 \ub2ec\ub77c\uc9c0\ub294 \uc21c\uac04\uc744 \ub354 \uc27d\uac8c \ub4e3\uac8c \ub41c\ub2e4. \ub3c5\uc77c\uc5b4\ub97c \ubaa8\ub974\ub354\ub77c\ub3c4 \uba3c\uc800 \uc774\uc57c\uae30\uc758 \uc21c\uc11c\ub97c \uc54c\uace0 \ub4e3\ub294 \uac83\uc774 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \uc74c \ud558\ub098\ub9c8\ub2e4 \ubc88\uc5ed\uc744 \ubd99\uc774\ub824 \ud558\uae30\ubcf4\ub2e4 \uc9c0\uae08 \ub204\uad6c\uc758 \ub9d0\uc778\uac00\ub97c \ucc3e\uc544\ubcf4\ub294 \uac83\uc774\ub2e4. \uc544\uc774\uc5d0\uac8c\ub294 \ub450\ub824\uc6b4 \uc874\uc7ac\uac00 \ubcf4\uc778\ub2e4. \uc544\ubc84\uc9c0\ub294 \uc548\uac1c\ub098 \ubc14\ub78c, \uc790\uc5f0\uc758 \ubaa8\uc2b5\uc73c\ub85c \uc124\uba85\ud558\uba70 \uc9c4\uc815\uc2dc\ud0a4\ub824 \ud55c\ub2e4. \ub450 \uc0ac\ub78c\uc740 \uac19\uc740 \uae38\uc744 \uac00\uc9c0\ub9cc \uac19\uc740 \uc138\uacc4\ub97c \uacbd\ud5d8\ud558\uace0 \uc788\uc9c0\ub294 \uc54a\ub2e4. \uc774 \ucc28\uc774\uac00 \ub300\ud654\ub97c \uacc4\uc18d \uc6c0\uc9c1\uc778\ub2e4. \uc544\ubc84\uc9c0\uc758 \ucc28\ubd84\ud558\uac8c \ub2ec\ub798\ub294 \uc18c\ub9ac\uc640 \uc544\uc774\uc758 \ubd88\uc548\ud55c \uc678\uce68\uc744 \ube44\uad50\ud574 \ubcf4\uc790. \ud55c \uac00\uc218\uac00 \ub192\uc774\uc640 \ud798, \ub9d0\ud22c\ub97c \ubc14\uafb8\uba70 \ub450 \uc0ac\ub78c\uc744 \uad6c\ubd84\ud55c\ub2e4. \uc544\ubc84\uc9c0\uac00 \uc544\uc774\ub97c \uc0ac\ub791\ud558\uc9c0 \uc54a\uc544 \uc774\ud574\ud558\uc9c0 \ubabb\ud55c\ub2e4\uace0 \uace7\ubc14\ub85c \ud310\ub2e8\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub3cc\ubcf4\ub824\ub294 \ub9c8\uc74c\uacfc \uc0c1\ub300\uac00 \ub290\ub07c\ub294 \uacf5\ud3ec\uac00 \uaf2d \uac19\uc740 \uc124\uba85\uc73c\ub85c \ub9cc\ub098\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc544\uc774\ub97c \ubd80\ub974\ub294 \uc874\uc7ac\ub294 \ucc98\uc74c\ubd80\ud130 \ud070 \uc18c\ub9ac\ub85c \uc704\ud611\ud558\uae30\ub9cc \ud558\uc9c0 \uc54a\ub294\ub2e4. \ub354 \ubd80\ub4dc\ub7fd\uace0 \ub9e4\ub825\uc801\uc73c\ub85c \ub4e4\ub9ac\ub294 \ub9d0\ub85c \uc720\ud639\ud55c\ub2e4. \ubc14\uae65\uc758 \uae34\ubc15\ud55c \ud53c\uc544\ub178\uc640 \ub2e4\ub978 \uc131\uaca9\uc758 \ub178\ub798\uac00 \uc7a0\uc2dc \uacb9\uce58\uba74 \uc74c\uc545\uc758 \ubd88\ud3b8\ud568\uc740 \uc624\ud788\ub824 \ucee4\uc9c8 \uc218 \uc788\ub2e4. \ubb34\uc11c\uc6b4 \uc7a5\uba74\uc740 \ubc18\ub4dc\uc2dc \uac70\uce60\uace0 \uc2dc\ub044\ub7ec\uc6b4 \uc18c\ub9ac\ub85c\ub9cc \ub9cc\ub4e4\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc810\uc774 \ud765\ubbf8\ub86d\ub2e4. \ub2e4\uc815\ud55c \ub9d0\ud22c\uac00 \uc5b4\ub5a4 \uc0c1\ud669\uc5d0\uc11c \ub098\uc624\uace0 \ub204\uad6c\ub97c \ud5a5\ud558\ub294\uc9c0\uc5d0 \ub530\ub77c \uc758\ubbf8\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \ud55c \uace1 \uc548\uc5d0\uc11c \uc18c\ub9ac\uc758 \uc544\ub984\ub2e4\uc6c0\uacfc \uc774\uc57c\uae30\uc758 \uc704\ud5d8\uc774 \uac19\uc740 \ubc29\ud5a5\uc73c\ub85c\ub9cc \uc6c0\uc9c1\uc774\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc544\uc774\ub294 \uc544\ubc84\uc9c0\ub97c \ubd80\ub974\uba70 \uc790\uc2e0\uc774 \uacaa\ub294 \uc77c\uc744 \uc54c\ub9ac\ub824 \ud55c\ub2e4. \uadf8 \ud638\uc18c\uac00 \ubc18\ubcf5\ub420\uc218\ub85d \uccad\uc911\uc740 \uac19\uc740 \ub300\ub2f5\ub9cc\uc73c\ub85c\ub294 \uc0c1\ud669\uc774 \ud480\ub9ac\uc9c0 \uc54a\ub294\ub2e4\ub294 \uac83\uc744 \ub290\ub080\ub2e4. \uc55e\uc11c \ub4e4\uc5c8\ub358 \uc720\ud639\uc758 \ubd80\ub4dc\ub7ec\uc6c0\uacfc \uc544\uc774\uc758 \uc678\uce68\uc744 \uae30\uc5b5\ud574 \ub450\uba74 \uc778\ubb3c\ub4e4\uc758 \ucc28\uc774\uac00 \ub354 \ub69c\ub837\ud574\uc9c4\ub2e4. \uc5ec\uae30\uc11c \uc6d0\uc778\uc744 \ud558\ub098\uc758 \uc9c4\ub2e8\uc73c\ub85c \ud655\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc2dc\uc640 \uac00\uace1\uc740 \uc544\uc774\uac00 \ubb34\uc5c7\uc744 \ubcf4\uace0 \uc544\ubc84\uc9c0\uac00 \uc5b4\ub5bb\uac8c \ubc18\uc751\ud558\ub294\uc9c0 \ubcf4\uc5ec \uc900\ub2e4. \uc791\ud488 \ubc16\uc758 \ubcd1\uba85\uc774\ub098 \ucd08\uc790\uc5f0\uc801 \uc0ac\uc2e4\uc744 \uc99d\uba85\ud558\ub294 \uae30\ub85d\uc73c\ub85c \uc77d\uae30\ubcf4\ub2e4, \uc11c\ub85c \ub2e4\ub978 \uacbd\ud5d8\uc774 \ub05d\ub0b4 \ub9cc\ub098\uc9c0 \ubabb\ud558\ub294 \uc7a5\uba74\uc73c\ub85c \ub4e4\uc744 \uc218 \uc788\ub2e4. \uc544\ubc84\uc9c0\ub294 \uc544\uc774\ub97c \uc548\uace0 \ubaa9\uc801\uc9c0\uc5d0 \ub3c4\ucc29\ud558\uc9c0\ub9cc \uc544\uc774\ub294 \uc774\ubbf8 \uc8fd\uc5b4 \uc788\ub2e4. \ub9c8\uc9c0\ub9c9\uc5d0\ub294 \uc55e\uc11c \ub2ec\ub9ac\ub358 \ud750\ub984\uacfc \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \uc0ac\uc2e4\uc774 \uc804\ub2ec\ub41c\ub2e4. \ud53c\uc544\ub178\uc640 \ubaa9\uc18c\ub9ac\uac00 \ub9cc\ub4e4\uc5b4 \uc628 \uae34\ubc15\ud568\uc744 \uae30\uc5b5\ud558\uae30 \ub54c\ubb38\uc5d0 \uadf8 \uba48\ucda4\uc740 \ub354 \ud06c\uac8c \ub4e4\ub9b4 \uc218 \uc788\ub2e4. \uc774 \uacb0\ub9d0\uc744 \ub180\ub77c\uc6b4 \ubc18\uc804\uc73c\ub85c\ub9cc \uae30\ub2e4\ub9ac\uae30\ubcf4\ub2e4 \uadf8\uc804\uc758 \ubaa8\ub4e0 \ub9d0\uc774 \uc5b4\ub5a4 \uad00\uacc4\uc5d0 \uc788\uc5c8\ub294\uc9c0 \ub3cc\uc544\ubcf4\uba74 \uc88b\ub2e4. \ub2ec\ub798\ub294 \ub9d0, \uc720\ud639\ud558\ub294 \ub9d0, \ub3c4\uc6c0\uc744 \uad6c\ud558\ub294 \ub9d0\uc774 \uac19\uc740 \uc2dc\uac04\uc5d0 \uc774\uc5b4\uc84c\uc9c0\ub9cc \uacb0\uacfc\ub294 \ub9c9\uc9c0 \ubabb\ud588\ub2e4. \uac00\uace1\uc740 \uc9e7\uc740 \ubd84\ub7c9 \uc548\uc5d0 \uadf8 \uc5b4\uae0b\ub0a8\uc744 \uc751\ucd95\ud55c\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \ub9c8\uc655\uc758 \uc81c2\ud310\uc744 \uc704\ud574 \uc81c\uc791\ub41c \ud504\ub780\uce20 \ubc14\uc774\uae00\uc758 \uc5ed\uc0ac\uc801 \ud310\ud654\uac00 \uc804\uae30\uc5d0 \uc7ac\uc218\ub85d\ub41c \uc790\ub8cc\ub2e4. \ub9d0\uc744 \ud0c4 \uc778\ubb3c\uacfc \ud658\uc0c1\uc801 \ud615\uc0c1\uc744 \ud45c\ud604\ud55c \ucd9c\ud310 \uc0bd\ud654\uc774\uba70, \uc288\ubca0\ub974\ud2b8\uac00 \ubaa9\uaca9\ud55c \uc2e4\uc81c \uc0ac\uac74\uc758 \uadf8\ub9bc\uc740 \uc544\ub2c8\ub2e4. \ub178\ub798\uac00 \ub2e4\ub8e8\ub294 \ubc24\uae38\uc758 \ubd84\uc704\uae30\ub85c \ub4e4\uc5b4\uac00\ub294 \ubb38\uc73c\ub85c \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc904\uac70\ub9ac\ub97c \uc54c\uace0 \ud3b8\ud558\uac8c \ub4e3\uace0, \ub2e4\uc74c\uc5d0\ub294 \ud654\uc790\uc640 \uc544\ubc84\uc9c0, \uc544\uc774\uc640 \ub9c8\uc655\uc744 \ub098\ub204\uc5b4 \ucc3e\uc544\ubcf4\uc790. \ub9c8\uc9c0\ub9c9\uc73c\ub85c \ud53c\uc544\ub178\ub9cc \uadc0\ub85c \ub530\ub77c\uac00 \ubcf4\uba74 \ud55c \ubc88 \ub354 \ub2e4\ub978 \uace1\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \ud55c \uac00\uc218\uc758 \ub124 \ubaa9\uc18c\ub9ac \uacc1\uc5d0\uc11c \ud53c\uc544\ub178 \uc5ed\uc2dc \uc774\uc57c\uae30\ub97c \ub9d0\ud558\uace0 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ub4e4\ub9ac\uae30 \uc2dc\uc791\ud55c\ub2e4."}, {"id": "schubert-trout-clear-water", "title": "\uc288\ubca0\ub974\ud2b8 \uc1a1\uc5b4 \u2014 \ub9d1\uc740 \ubb3c\uc740 \uc65c \ud750\ub824\uc84c\uc744\uae4c", "summary": "\uac00\uace1 D.550\uc758 \uc138 \uc5f0\uacfc \ubc18\uc8fc\ub97c \ub530\ub77c\uac00\uba70 \ubb3c\uace0\uae30\ub97c \ubc14\ub77c\ubcf4\ub358 \ud654\uc790\uc758 \uac10\uc815 \ubcc0\ud654\ub97c \ub4e3\uc2b5\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Music", "url": "stories/schubert-trout-clear-water/index.html", "image": "media/schubert-trout-clear-water.png", "alt": "\ub9d1\uc740 \uc2dc\ub0c7\ubb3c\uc5d0\uc11c \uc1a1\uc5b4\uac00 \ud5e4\uc5c4\uce58\uace0 \uba3c \uac15\uac00\uc5d0 \uc791\uc740 \uc0ac\ub78c\uc774 \uc11c \uc788\ub294 \uc0c1\uc0c1 \ud48d\uacbd.", "text": "\uc288\ubca0\ub974\ud2b8 \uc1a1\uc5b4 \u2014 \ub9d1\uc740 \ubb3c\uc740 \uc65c \ud750\ub824\uc84c\uc744\uae4c \uac00\ubcbc\uc6b4 \ud53c\uc544\ub178 \ubc18\uc8fc \ub4a4\uc5d0\uc11c \ub2ec\ub77c\uc9c0\ub294 \uc9e7\uc740 \uc774\uc57c\uae30 \uac00\uace1 D.550\uc758 \uc138 \uc5f0\uacfc \ubc18\uc8fc\ub97c \ub530\ub77c\uac00\uba70 \ubb3c\uace0\uae30\ub97c \ubc14\ub77c\ubcf4\ub358 \ud654\uc790\uc758 \uac10\uc815 \ubcc0\ud654\ub97c \ub4e3\uc2b5\ub2c8\ub2e4. Music \ubb38\ud654 \ud53c\uc544\ub178\uac00 \uac00\ubccd\uac8c \uc6c0\uc9c1\uc774\uba74 \ubb3c\uc774 \ubc18\uc9dd\uc774\ub294 \uac83 \uac19\ub2e4. \uadf8 \uc704\ub85c \ub204\uad70\uac00\uac00 \ub9d1\uc740 \uc2dc\ub0c7\ubb3c\uc5d0\uc11c \ud5e4\uc5c4\uce58\ub294 \uc1a1\uc5b4\ub97c \ub178\ub798\ud55c\ub2e4. \uc288\ubca0\ub974\ud2b8\uc758 \uac00\uace1 \u3008\uc1a1\uc5b4\u3009\ub294 \ucc98\uc74c \uba87 \ub9c8\ub514\ub9cc \ub4e4\uc73c\uba74 \uae30\ubd84 \uc88b\uc740 \uc790\uc5f0\uc758 \uc18c\ud488\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \uadf8\ub7ec\ub098 \uac00\uc0ac\ub97c \ub530\ub77c\uac00\uba74 \ubb3c\uc758 \ube5b\uacfc \ud568\uaed8 \uc774\uc57c\uae30\uc758 \ud45c\uc815\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uc5ec\uae30\uc11c \ub2e4\ub8e8\ub294 \uc791\ud488\uc740 \ubaa9\uc18c\ub9ac\uc640 \ud53c\uc544\ub178\ub97c \uc704\ud55c \uac00\uace1 D.550, \ub3c5\uc77c\uc5b4 \uc81c\ubaa9\uc73c\ub85c \u3008Die Forelle\u3009\ub2e4. \uc545\ubcf4\uc5d0 \uc2e4\ub9b0 \uc2dc\uc758 \uc138 \uc5f0\uc744 \ucc28\ub840\ub85c \uc0b4\ud3b4\ubcf4\uc790. \uc74c\uc545\uc744 \uc77d\uc9c0 \ubabb\ud574\ub3c4 \ub204\uac00 \ubb34\uc5c7\uc744 \ubcf4\uace0 \uc788\ub294\uc9c0 \uc54c\uba74 \uadc0\uac00 \uba38\ubb34\ub294 \uc790\ub9ac\uac00 \ub298\uc5b4\ub09c\ub2e4. Forelle\ub294 \uc1a1\uc5b4\ub97c \ub73b\ud55c\ub2e4. \uac00\uc0ac\uc758 \ubc14\ud0d5\uc740 \ud06c\ub9ac\uc2a4\ud2f0\uc548 \ud504\ub9ac\ub4dc\ub9ac\ud788 \ub2e4\ub2c8\uc5d8 \uc288\ubc14\ub974\ud2b8\uc758 \uc2dc\ub2e4. \uc288\ubca0\ub974\ud2b8\uac00 \uc2dc\uc758 \ub9d0\uc744 \uc74c\uc545\uc73c\ub85c \uc62e\uacbc\ub2e4\ub294 \uc810\uc744 \uc54c\uba74 \uace1\uc744 \ub530\ub77c\uac00\ub294 \uc77c\uc774 \uc870\uae08 \uc26c\uc6cc\uc9c4\ub2e4. \uc74c\uc545 \ubc16\uc758 \uc774\uc57c\uae30\ub97c \uc5b5\uc9c0\ub85c \ub9cc\ub4e4\uc5b4 \ubd99\uc77c \ud544\uc694 \uc5c6\uc774 \uc774\ubbf8 \ub178\ub7ab\ub9d0 \uc548\uc5d0 \uc0ac\uac74\uc774 \uc788\ub2e4. \uc81c\ubaa9\ub9cc \ubcf4\uace0 \uc1a1\uc5b4 \uc790\uc2e0\uc774 \ubd80\ub974\ub294 \ub178\ub798\ub77c\uace0 \uc0dd\uac01\ud558\uae30 \uc27d\uc9c0\ub9cc \ud654\uc790\ub294 \uac15\uac00\uc5d0\uc11c \uadf8 \ubb3c\uace0\uae30\ub97c \uc9c0\ucf1c\ubcf4\ub294 \uc0ac\ub78c\uc774\ub2e4. \ubb3c\uc758 \uc0c1\ud0dc\ub97c \ubcf4\uace0 \ub09a\uc2dc\uafbc\uc758 \ud589\ub3d9\uc744 \ud310\ub2e8\ud558\uba70 \ub9c8\uc9c0\ub9c9\uc5d0\ub294 \uc18d\uc784\uc218\ub97c \ub2f9\ud55c \ubb3c\uace0\uae30\ub97c \ubc14\ub77c\ubcf8\ub2e4. \ud48d\uacbd\uc740 \uc774 \uad00\ucc30\uc790\uc758 \uac10\uc815\uc744 \uac70\uccd0 \uc6b0\ub9ac\uc5d0\uac8c \uc804\ud574\uc9c4\ub2e4. \ub178\ub798\uac00 \ub098\uc624\uae30 \uc804\ubd80\ud130 \ud53c\uc544\ub178\uc5d0\ub294 \uc791\uace0 \ube60\ub978 \uc74c\uc758 \uc6c0\uc9c1\uc784\uc774 \uc788\ub2e4. \ubb3c\uacb0\uc774\ub098 \ubb3c\uace0\uae30\uc758 \ub0a0\ub835\ud568\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc88b\uc740 \ubc18\uc8fc\ub2e4. \uc2e4\uc81c \uc2dc\ub0c7\ubb3c\uc758 \uc18c\ub9ac\ub97c \ub179\uc74c\ud55c \uac83\uc740 \uc544\ub2c8\uc9c0\ub9cc, \ubc18\ubcf5\ub418\ub294 \uc6c0\uc9c1\uc784\uacfc \uac00\ubcbc\uc6b4 \ub9ac\ub4ec\uc774 \ub4e3\ub294 \uc0ac\ub78c\uc758 \uc0c1\uc0c1\uc744 \ub3d5\ub294\ub2e4. \uc774\ub54c \uc120\uc728\ub9cc \uae30\ub2e4\ub9ac\uc9c0 \ub9d0\uace0 \ubc18\uc8fc\uc758 \ubaa8\uc591\uc744 \uc7a0\uc2dc \ub4e4\uc5b4 \ubcf4\uc790. \ubaa9\uc18c\ub9ac\uac00 \ub098\ud0c0\ub09c \ub4a4\uc5d0\ub3c4 \uc544\ub798\uc5d0\uc11c \uc5b4\ub5a4 \uc6c0\uc9c1\uc784\uc774 \uc774\uc5b4\uc9c0\ub294\uc9c0 \uc54c\uba74 \ud53c\uc544\ub178\uac00 \ub2e8\uc21c\ud788 \uc74c\uc815\uc744 \ub9de\ucdb0 \uc8fc\ub294 \ubc30\uacbd\uc774 \uc544\ub2c8\ub77c\ub294 \uc810\uc774 \ubcf4\uc778\ub2e4. \ub178\ub798\uc640 \ubc18\uc8fc\ub294 \uac19\uc740 \uc7a5\uba74\uc744 \uc11c\ub85c \ub2e4\ub978 \ubc29\ubc95\uc73c\ub85c \ub4e4\ub824\uc900\ub2e4. \uccab \uc5f0\uc5d0\uc11c \uc1a1\uc5b4\ub294 \ub9d1\uc740 \uc2dc\ub0c7\ubb3c \uc18d\uc744 \ud654\uc0b4\ucc98\ub7fc \uc7ac\ube60\ub974\uac8c \uc6c0\uc9c1\uc778\ub2e4. \uac15\uac00\uc758 \ud654\uc790\ub294 \uadf8 \ubaa8\uc2b5\uc744 \uc990\uac81\uace0 \ud3c9\uc628\ud558\uac8c \ubc14\ub77c\ubcf8\ub2e4. \uc544\uc9c1\uc740 \ubd99\uc7a1\ud790 \uc704\ud5d8\ubcf4\ub2e4 \uc6c0\uc9c1\uc774\ub294 \uc0dd\uba85\uc744 \uc9c0\ucf1c\ubcf4\ub294 \uae30\uc068\uc774 \uc55e\uc5d0 \uc788\ub2e4. \uc9e7\uc740 \ub9d0\ub4e4 \uc548\uc5d0 \ubb3c\uace0\uae30\uc640 \uad00\ucc30\uc790\uc758 \uc790\ub9ac\uac00 \ud568\uaed8 \ub193\uc778\ub2e4. \ub178\ub798\uac00 \uac00\ubccd\uac8c \uc774\uc5b4\uc9c0\ub294 \ub290\ub08c\uacfc \ubc18\uc8fc\uc758 \uc6c0\uc9c1\uc784\uc744 \ud568\uaed8 \ub4e4\uc5b4 \ubcf4\uc790. \ubb3c\uace0\uae30\uc758 \uc18d\ub3c4\uc640 \ubcf4\ub294 \uc0ac\ub78c\uc758 \ub290\uae0b\ud568\uc774 \ud55c \uc7a5\uba74 \uc548\uc5d0 \uc788\ub2e4. \uc74c\uc545\uc758 \ubaa8\ub4e0 \uc74c\uc744 \ubb3c\ubc29\uc6b8 \ud558\ub098\uc5d0 \ub9de\ucd9c \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5b4\ub5a4 \uc6c0\uc9c1\uc784\uc774 \uacc4\uc18d\ub418\uace0 \ubb34\uc5c7\uc774 \uadf8 \uc704\uc5d0\uc11c \ub178\ub798\ud558\ub294\uc9c0 \ub290\ub07c\uba74 \ucda9\ubd84\ud558\ub2e4. \ub2e4\uc74c\uc5d0\ub294 \ub09a\uc2ef\ub300\ub97c \ub4e0 \uc0ac\ub78c\uc774 \uac15\uac00\uc5d0 \uc11c \uc788\ub2e4. \ud654\uc790\ub294 \ubb3c\uc774 \ub9d1\uc740 \ub3d9\uc548\uc5d0\ub294 \uc1a1\uc5b4\uac00 \uc27d\uac8c \ub09a\uc774\uc9c0 \uc54a\uc744 \uac83\uc774\ub77c\uace0 \uc0dd\uac01\ud55c\ub2e4. \uac19\uc740 \ub9d1\uc74c\uc774 \ucc98\uc74c\uc5d0\ub294 \uc544\ub984\ub2e4\uc6b4 \ud48d\uacbd\uc774\uc5c8\uc9c0\ub9cc \uc774\uc81c\ub294 \ubb3c\uace0\uae30\ub97c \uc9c0\ucf1c \uc8fc\ub294 \uc870\uac74\uc73c\ub85c \ubc14\ub010\ub2e4. \ucc98\uc74c\uacfc \ube44\uc2b7\ud55c \uc74c\uc545\uc744 \ub2e4\uc2dc \ub4e3\ub354\ub77c\ub3c4 \ub73b\uc774 \uc644\uc804\ud788 \uac19\uc9c0\ub294 \uc54a\ub2e4. \ub3c5\uc790\ub294 \uc774\ubbf8 \ub09a\uc2dc\uafbc\uc744 \ubcf4\uc558\ub2e4. \ubc30\uacbd\uc5d0\uc11c \uc791\uc740 \uc704\ud611\uc774 \uc0dd\uacbc\ub294\ub370 \uc775\uc219\ud55c \uc6c0\uc9c1\uc784\uc740 \uacc4\uc18d\ub41c\ub2e4. \ubc18\ubcf5\uc740 \uc0ac\uac74\uc774 \uc5c6\ub294 \uc0c1\ud0dc\uac00 \uc544\ub2c8\ub77c \uac19\uc740 \ud48d\uacbd\uc744 \uc0c8 \uc815\ubcf4\uc640 \ud568\uaed8 \ub2e4\uc2dc \ubcf4\ub294 \uc2dc\uac04\uc774 \ub420 \uc218 \uc788\ub2e4. \ub09a\uc2dc\uafbc\uc740 \uae30\ub2e4\ub9bc\uc774 \uae38\uc5b4\uc9c0\uc790 \ubb3c\uc744 \uc77c\ubd80\ub7ec \ud750\ub9b0\ub2e4. \ub9d1\uc740 \ubb3c\uc5d0\uc11c \uc790\uc720\ub86d\uac8c \uc6c0\uc9c1\uc774\ub358 \uc1a1\uc5b4\ub294 \ub2ec\ub77c\uc9c4 \uc870\uac74\uc5d0\uc11c \uc7a1\ud78c\ub2e4. \ud654\uc790\ub294 \uc18d\uc784\uc218\ub97c \ub2f9\ud55c \ubb3c\uace0\uae30\ub97c \ubcf4\uace0 \ub9c8\uc74c\uc774 \uaca9\ud574\uc9c4\ub2e4. \uac00\uc0ac\ub294 \ud55c\uac00\ud55c \uad00\ucc30\uc5d0\uc11c \ub204\uad70\uac00\uc758 \ud589\ub3d9\uc744 \ud310\ub2e8\ud558\ub294 \ub9d0\ub85c \uc774\ub3d9\ud55c\ub2e4. \uadf8 \ubcc0\ud654\uc5d0 \ub9de\ucd94\uc5b4 \uc74c\uc545\ub3c4 \ucc98\uc74c\uc758 \uac00\ubcbc\uc6c0\ub9cc \uc720\uc9c0\ud558\uc9c0 \uc54a\ub294\ub2e4. \ubc18\uc8fc\uc640 \ub178\ub798\uc758 \ud798, \ub9d0\uc774 \ub193\uc774\ub294 \ub9ac\ub4ec\uc5d0\uc11c \uae34\uc7a5\uc774 \ucee4\uc9c0\ub294 \ubd80\ubd84\uc744 \ub4e4\uc5b4 \ubcf4\uc790. \ub2e8\uc21c\ud788 \ube60\ub974\uac70\ub098 \ub290\ub9b0\uc9c0\ub97c \ub118\uc5b4 \uac19\uc740 \ubaa9\uc18c\ub9ac\uac00 \uc5b4\ub5a4 \uc0c1\ud669\uc5d0\uc11c \ub2e4\ub978 \ubb34\uac8c\ub97c \uac16\uac8c \ub418\ub294\uc9c0 \ub290\ub084 \uc218 \uc788\ub2e4. \uc775\uc219\ud55c \ubc18\uc8fc\uc758 \uc6c0\uc9c1\uc784\uc774 \ub2e4\uc2dc \ub4e4\ub9b4 \ub54c \ucc98\uc74c\uc758 \ud3c9\uc628\uc774 \ubaa8\ub450 \ubcf5\uc6d0\ub418\uc5c8\ub2e4\uace0 \ub290\uaef4\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub4e3\ub294 \uc0ac\ub78c\uc740 \uc774\ubbf8 \uc1a1\uc5b4\uac00 \uc7a1\ud78c \uc77c\uc744 \uc548\ub2e4. \uc55e\uc5d0\uc11c \uc990\uac70\uc6e0\ub358 \uc6c0\uc9c1\uc784\uc744 \ub2e4\uc2dc \ub9cc\ub098\ub3c4 \uac00\uc0ac\uc758 \uae30\uc5b5\uc774 \uadf8 \uc18c\ub9ac\ub97c \ub2ec\ub9ac \ub4e3\uac8c \ud560 \uc218 \uc788\ub2e4. \uc9e7\uc740 \uac00\uace1\uc5d0\uc11c \uc74c\uc545\uacfc \ub9d0\uc774 \ud568\uaed8 \ub9cc\ub4dc\ub294 \ud6a8\uacfc\ub2e4. \uae30\uc545 \ubc18\uc8fc\ub9cc \ub4e4\uc744 \ub54c\uc640 \uac00\uc0ac\ub97c \uc54c\uace0 \ub4e4\uc744 \ub54c\uc758 \uc778\uc0c1\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc5b4\ub290 \ucabd\uc774 \uc720\uc77c\ud558\uac8c \uc633\ub2e4\uae30\ubcf4\ub2e4, \ubb34\uc5c7\uc744 \ub4e3\uace0 \uc788\uc5c8\ub294\uc9c0 \uc54c\uc544\ucc28\ub9ac\ub294 \uacfc\uc815\uc5d0 \uac00\uae5d\ub2e4. \ud55c \uace1 \uc548\uc5d0\ub3c4 \uc5ec\ub7ec \ubc88 \uc0c8\ub86d\uac8c \ub4e4\uc5b4\uac08 \uae38\uc774 \uc788\ub2e4. \uc774 \ub178\ub798\ub97c \uace7\ubc14\ub85c \ud558\ub098\uc758 \uc815\uce58\uc801 \uc0ac\uac74\uc774\ub098 \uc791\uace1\uac00\uc758 \ube44\ubc00 \uacbd\ud5d8\uacfc \ub300\uc751\uc2dc\ud0ac \ud544\uc694\ub294 \uc5c6\ub2e4. \uc774\ubc88\uc5d0 \ud655\uc778\ud55c \uadfc\uac70\ub294 \uc545\ubcf4\uc640 \uac70\uae30\uc5d0 \uc2e4\ub9b0 \uac00\uc0ac\ub2e4. \ubd84\uba85\ud788 \uc77d\uc744 \uc218 \uc788\ub294 \uac83\uc740 \ubb3c\uc758 \uc870\uac74\uc744 \ubc14\uafbc \uc0ac\ub78c\uc758 \ud589\ub3d9\uacfc \uadf8 \uacb0\uacfc\ub97c \ubcf8 \ud654\uc790\uc758 \ubc18\uc751\uc774\ub2e4. \uc5ec\uae30\uc11c \uc790\uc5f0\uc758 \ud48d\uacbd\uacfc \uc778\uac04\uc758 \uc120\ud0dd\uc774 \ub9cc\ub09c\ub2e4. \uc790\uc720\ub86d\uac8c \uc6c0\uc9c1\uc774\ub358 \uc874\uc7ac\ub97c \uc7a1\uae30 \uc704\ud574 \ud658\uacbd\uc744 \ubc14\uafb8\ub294 \uc77c\uc740 \ub2e8\uc21c\ud55c \ud48d\uacbd \ubb18\uc0ac\ubcf4\ub2e4 \ub0a0\uce74\ub86d\ub2e4. \ubc1d\uc740 \uc74c\uc545\uc774\ub77c\uace0 \ud574\uc11c \uadf8 \uc548\uc758 \uc774\uc57c\uae30\ub3c4 \ub05d\uae4c\uc9c0 \uc544\ubb34 \uac71\uc815\uc774 \uc5c6\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\uc744 \uae30\uc5b5\ud560 \uc218 \uc788\ub2e4. \ud55c \ubc88\uc740 \ud53c\uc544\ub178\uc758 \uc6c0\uc9c1\uc784\uc744, \ub2e4\uc74c\uc5d0\ub294 \uccab \uc5f0\uacfc \ub458\uc9f8 \uc5f0\uc758 \ube44\uc2b7\ud55c \ud750\ub984\uc744, \ub9c8\uc9c0\ub9c9\uc5d0\ub294 \ubb3c\uc744 \ud750\ub9ac\ub294 \uc14b\uc9f8 \uc5f0\uc758 \ubcc0\ud654\ub97c \ub530\ub77c\uac00 \ubcf4\uc790. \uc131\uc545\uac00\uac00 \ub3c5\uc77c\uc5b4\uc758 \ub9d0\uc744 \uc5b4\ub5bb\uac8c \uac15\uc870\ud558\ub294\uc9c0 \ubab0\ub77c\ub3c4 \ubaa9\uc18c\ub9ac\uc758 \ud798\uacfc \ubc18\uc8fc\uc758 \ucc28\uc774\ub294 \ub290\ub084 \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\uc740 \ub9d1\uc740 \ubb3c\uc5d0\uc11c \ud5e4\uc5c4\uce58\ub294 \uc1a1\uc5b4\ub97c \uc0c1\uc0c1\ud55c AI \uc0bd\ud654\ub2e4. \uc2e4\uc81c \uc791\uace1 \uc7a5\uc18c\ub098 \uace1\uc758 \uc545\ubcf4\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uadf8\ub9bc\uc758 \ud3c9\uc628\ud568\uc744 \uc785\uad6c\ub85c \uc0bc\uace0 \uac00\uc0ac\uac00 \uc5b4\ub514\ub85c \uc6c0\uc9c1\uc774\ub294\uc9c0 \ub05d\uae4c\uc9c0 \ub4e4\uc5b4 \ubcf4\uba74, \uc775\uc219\ud55c \uc81c\ubaa9 \uc548\uc5d0\uc11c \uc0dd\uac01\ubcf4\ub2e4 \ub610\ub837\ud55c \uc9e7\uc740 \ub4dc\ub77c\ub9c8\ub97c \ub9cc\ub0a0 \uc218 \uc788\ub2e4."}, {"id": "schumann-traumerei-memory", "title": "\ud2b8\ub85c\uc774\uba54\ub77c\uc774 \u2014 \uc9e7\uc740 \ud53c\uc544\ub178\uace1\uc774 \uc624\ub798\ub41c \uae30\uc5b5\ucc98\ub7fc \ub4e4\ub9b4 \ub54c", "summary": "\uc81c\ubaa9\uc758 \ub73b\uacfc \uc120\uc728\uc758 \ud638\ud761, \ubaa8\uc74c\uace1 \uc548\uc758 \uc790\ub9ac\ub97c \ud568\uaed8 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Music", "url": "stories/schumann-traumerei-memory/index.html", "image": "media/schumann-traumerei-memory.png", "alt": "\ud53c\uc544\ub178\uc640 \ucc3d\uac00\uc758 \uc791\uc740 \uc7a5\ub09c\uac10, \uc815\uc6d0\uc744 \ubc14\ub77c\ubcf4\ub294 \uc778\ubb3c\uc744 \uadf8\ub9b0 \ubabd\uc0c1\uc758 \ubd84\uc704\uae30 \uc0bd\ud654.", "text": "\ud2b8\ub85c\uc774\uba54\ub77c\uc774 \u2014 \uc9e7\uc740 \ud53c\uc544\ub178\uace1\uc774 \uc624\ub798\ub41c \uae30\uc5b5\ucc98\ub7fc \ub4e4\ub9b4 \ub54c \uc288\ub9cc \uc5b4\ub9b0\uc774 \uc815\uacbd\uc758 \uc77c\uacf1 \ubc88\uc9f8 \uace1\uc744 \ucc9c\ucc9c\ud788 \ub4e3\uae30 \uc81c\ubaa9\uc758 \ub73b\uacfc \uc120\uc728\uc758 \ud638\ud761, \ubaa8\uc74c\uace1 \uc548\uc758 \uc790\ub9ac\ub97c \ud568\uaed8 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Music \ubb38\ud654 \ucc98\uc74c\ubd80\ud130 \ub05d\uae4c\uc9c0 \uae38\uac8c \uc18c\ub9ac\uce58\uc9c0 \uc54a\ub294 \uc74c\uc545\uc774 \uc788\ub2e4. \ub204\uad70\uac00 \uc870\uc6a9\ud788 \ub9d0\uc744 \uaebc\ub0b4\uace0 \uc7a0\uc2dc \uc0dd\uac01\ud558\ub2e4\uac00 \ub2e4\uc2dc \uc787\ub294 \uac83\ucc98\ub7fc \ub4e4\ub9b0\ub2e4. \uc288\ub9cc\uc758 \u3008\ud2b8\ub85c\uc774\uba54\ub77c\uc774\u3009\ub294 \uc9e7\uc740 \ud53c\uc544\ub178\uace1\uc774\uc9c0\ub9cc \uc5b4\ub5a4 \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc624\ub798\ub41c \uae30\uc5b5\uc758 \uae38\uc774\ub97c \uac00\uc9c4 \uc74c\uc545\uc73c\ub85c \ub0a8\ub294\ub2e4. \ub3c5\uc77c\uc5b4 \uc81c\ubaa9 Tr\u00e4umerei\ub294 \uafc8\uafb8\uae30, \ubabd\uc0c1\uc774\ub77c\ub294 \ub73b\uc73c\ub85c \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \ud2b9\uc815\ud55c \uafc8\uc758 \ub0b4\uc6a9\uc744 \uc124\uba85\ud558\ub294 \uc81c\ubaa9\uc774\ub77c\uae30\ubcf4\ub2e4 \uc7a0\uc2dc \ub9c8\uc74c\uc774 \ub2e4\ub978 \uacf3\uc5d0 \uba38\ubb34\ub294 \uc0c1\ud0dc\ub97c \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \uadf8 \uc774\ub984\uc744 \uc54c\uace0 \ub098\uba74 \ubb34\uc5c7\uc744 \uc0c1\uc0c1\ud574\uc57c \ud558\ub290\ub0d0\ubcf4\ub2e4 \uc18c\ub9ac\uac00 \uc5b4\ub5bb\uac8c \ud750\ub974\ub294\uc9c0 \ub4e3\ub294 \uae38\uc774 \uc5f4\ub9b0\ub2e4. \uc774 \uace1\uc740 \uc791\ud488\ubc88\ud638 15\uc758 \u300a\uc5b4\ub9b0\uc774 \uc815\uacbd\u300b\uc5d0 \ub4e4\uc5b4 \uc788\ub2e4. \ub530\ub85c \uc5f0\uc8fc\ub418\ub294 \uc77c\uc774 \ub9ce\uc9c0\ub9cc \uc6d0\ub798\ub294 \uc5ec\ub7ec \uc81c\ubaa9\uc758 \uc9e7\uc740 \uace1\ub4e4\uc774 \uc774\uc5b4\uc9c0\ub294 \ubaa8\uc74c\uace1\uc758 \ud55c \ubd80\ubd84\uc774\ub2e4. \uadf8 \uc548\uc5d0\ub294 \ub0af\uc120 \ub098\ub77c\uc758 \uc774\uc57c\uae30\uc640 \ub180\uc774, \uc791\uc740 \uc0ac\uac74\uacfc \uc7a0\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \uc81c\ubaa9\ub4e4\uc774 \ub193\uc778\ub2e4. \uc81c\ubaa9\uc5d0 \uc5b4\ub9b0\uc774\uac00 \uc788\ub2e4\uace0 \uc5b4\ub9b0\uc774\uc758 \ub2e8\uc21c\ud55c \uc5f0\uc2b5\uace1 \ubaa9\ub85d\uc73c\ub85c\ub9cc \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5b4\ub978\ub3c4 \uc5b4\ub9b0 \uc2dc\uc808\uc758 \uac10\uac01\uacfc \uae30\uc5b5\uc744 \ub5a0\uc62c\ub9ac\uba70 \ub4e4\uc744 \uc218 \uc788\ub2e4. \uc791\uc740 \uc7a5\uba74\uc744 \uc9e7\uc740 \uc74c\uc545\uc73c\ub85c \ub098\ub204\uc5c8\uae30 \ub54c\ubb38\uc5d0, \ud55c \uace1\uc529 \ub4e3\uace0 \ub2e4\uc2dc \uc804\uccb4\uc758 \uc21c\uc11c\ub97c \uc0b4\ud53c\ub294 \ubc29\ubc95\ub3c4 \uac00\ub2a5\ud558\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uac00\uc7a5 \uc704\uc5d0\uc11c \ub4e4\ub9ac\ub294 \uc120\uc728\uc744 \ud55c \uc904\uc758 \ub178\ub798\ucc98\ub7fc \ub530\ub77c\uac00 \ubcf4\uc790. \uc74c\uc774 \uc5b4\ub514\uc5d0\uc11c \uc62c\ub77c\uac00\uace0 \uc5b4\ub514\uc5d0\uc11c \uba38\ubb34\ub294\uc9c0, \ub9c8\uce68\ud45c\ucc98\ub7fc \ub290\uaef4\uc9c0\ub294 \uacf3\uc774 \uc5b4\ub514\uc778\uc9c0 \ub4e4\uc5b4 \ubcf4\ub294 \uac83\uc774\ub2e4. \uc545\ubcf4\ub97c \uc77d\uc9c0 \ubabb\ud574\ub3c4 \ub178\ub798\uc758 \ud638\ud761\uc740 \ub290\ub084 \uc218 \uc788\ub2e4. \ub108\ubb34 \uc720\uba85\ud55c \uace1\uc740 \uc774\ubbf8 \uc54c\uace0 \uc788\ub294 \uac10\uc815\uc73c\ub85c \ubc14\ub85c \ub36e\uae30 \uc27d\ub2e4. \uc2ac\ud504\ub2e4\uac70\ub098 \ud3b8\uc548\ud558\ub2e4\ub294 \ub9d0\uc774 \uba3c\uc800 \ub098\uc640\ub3c4 \uad1c\ucc2e\uc9c0\ub9cc, \uadf8\ub2e4\uc74c\uc5d0\ub294 \uc5b4\ub5a4 \uc6c0\uc9c1\uc784 \ub54c\ubb38\uc5d0 \uadf8\ub807\uac8c \ub4e4\ub838\ub294\uc9c0 \ubb3c\uc5b4\ubcfc \uc218 \uc788\ub2e4. \uac10\uc0c1\uc744 \uad6c\uccb4\uc801\uc778 \uc18c\ub9ac\uc640 \uc5f0\uacb0\ud558\uba74 \uc775\uc219\ud55c \uba5c\ub85c\ub514\ub3c4 \uc870\uae08 \uc0c8\ub85c\uc6cc\uc9c4\ub2e4. \ud53c\uc544\ub178\uc5d0\ub294 \uc55e\uc5d0 \ub098\uc624\ub294 \ub178\ub798\ub9cc \uc788\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uadf8 \uc544\ub798\uc758 \uc74c\ub4e4\uc774 \uc774\uc5b4\uc9c0\uba70 \ubc14\ud0d5\uc744 \ub9cc\ub4e4\uace0, \ub54c\ub85c\ub294 \uc548\ucabd\uc758 \uc18c\ub9ac\ub3c4 \uc6c0\uc9c1\uc778\ub2e4. \ud55c \uc0ac\ub78c\uc774 \uac74\ubc18\uc744 \ub204\ub974\uc9c0\ub9cc \uadc0\uc5d0\ub294 \uc5ec\ub7ec \uce35\uc758 \uad00\uacc4\uac00 \uc0dd\uae34\ub2e4. \uc870\uc6a9\ud55c \uace1\uc5d0\uc11c\ub3c4 \ubcfc\ub968 \ud558\ub098\ub85c \uc124\uba85\ub418\uc9c0 \uc54a\ub294 \uc9dc\uc784\uc774 \uc788\ub2e4. \ub450 \ubc88\uc9f8\ub85c \ub4e4\uc744 \ub54c\uc5d0\ub294 \ub192\uc740 \uc120\uc728\uc744 \ub193\uce58\uc9c0 \uc54a\uc73c\ub824 \uc560\uc4f0\uae30\ubcf4\ub2e4 \ub0ae\uc740 \ucabd\uc774 \uc5b4\ub5bb\uac8c \uc6c0\uc9c1\uc774\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \ubc30\uacbd\ucc98\ub7fc \ub4e4\ub9ac\ub358 \ubd80\ubd84\uc774 \uc120\uc728\uc744 \uc5b4\ub514\ub85c \uc774\ub044\ub294\uc9c0 \uc54c\uc544\ucc28\ub9b4 \uc218 \uc788\ub2e4. \ud55c \ubc88\uc758 \uac10\uc0c1\uc5d0 \ubaa8\ub4e0 \uac83\uc744 \uc7a1\uc73c\ub824 \ud558\uc9c0 \uc54a\uc73c\uba74 \ubc18\ubcf5\ud574\uc11c \ub4e3\ub294 \uc774\uc720\ub3c4 \uc0dd\uae34\ub2e4. \uc774 \uace1\uc744 \uc5ec\ub7ec \uc5f0\uc8fc\ub85c \ub4e4\uc73c\uba74 \ube60\ub974\uae30\uc640 \uba38\ubb34\ub294 \uc704\uce58\uac00 \ub2e4\ub974\uac8c \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \uc74c\uc744 \ub04a\uc9c0 \uc54a\uace0 \uc774\uc5b4 \uac00\ub294 \ubc29\uc2dd, \uc18c\ub9ac\ub97c \uc870\uae08 \ub113\ud788\uac70\ub098 \uac00\ubccd\uac8c \ub193\ub294 \ubc29\uc2dd\uc774 \ub178\ub798\uc758 \ub9d0\ud22c\ub97c \ubc14\uafbc\ub2e4. \uac19\uc740 \ubb38\uc7a5\ub3c4 \uc77d\ub294 \ud638\ud761\uc5d0 \ub530\ub77c \uc778\uc0c1\uc774 \ub2ec\ub77c\uc9c0\ub294 \uac83\uacfc \ube44\uc2b7\ud558\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc544\ubb34 \uacf3\uc5d0\uc11c\ub098 \uc624\ub798 \uba48\ucd94\uba74 \ub354 \uae4a\uc740 \uc74c\uc545\uc774 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud55c \uad6c\uc808\uc774 \uc5b4\ub514\ub85c \ud5a5\ud558\uace0 \ub2e4\uc74c \uad6c\uc808\uacfc \uc5b4\ub5bb\uac8c \uc774\uc5b4\uc9c0\ub294\uc9c0\uac00 \ud568\uaed8 \uc788\uc5b4\uc57c \ud55c\ub2e4. \ub290\ub9b0 \uc74c\uc545\uc758 \ud45c\ud604\ub3c4 \ub9c9\uc5f0\ud788 \uc2dc\uac04\uc744 \ub298\ub9ac\ub294 \uc77c\ubcf4\ub2e4 \uad00\uacc4\ub97c \ub9cc\ub4dc\ub294 \uc77c\uc5d0 \uac00\uae5d\ub2e4. \uc74c\uc758 \uc218\uac00 \ud654\ub824\ud55c \uace1\ubcf4\ub2e4 \uc801\uac8c \ub290\uaef4\uc838\ub3c4 \uac01 \uc18c\ub9ac\ub97c \uc5b4\ub5bb\uac8c \uc5f0\uacb0\ud560\uc9c0\ub294 \uc138\uc2ec\ud55c \ubb38\uc81c\ub2e4. \uc120\uc728\uc774 \ubc18\uc8fc\uc5d0 \uac00\ub824\uc9c0\uc9c0 \uc54a\uac8c \ud558\uba74\uc11c \ub2e4\ub978 \uc131\ubd80\ub97c \uc9c0\uc6b0\uc9c0 \uc54a\uace0, \uc791\uc740 \ucc28\uc774\ub85c \ud750\ub984\uc744 \ub9cc\ub4dc\ub294 \uc77c\uc774 \ud544\uc694\ud558\ub2e4. \ub4e3\uae30 \ud3b8\ud55c \uc778\uc0c1 \ub4a4\uc5d0 \uc5f0\uc8fc\uc758 \ud310\ub2e8\uc774 \uc788\ub2e4. \uad00\uac1d\uc774 \uadf8 \ub09c\ub3c4\ub97c \ubaa8\ub450 \uacc4\uc0b0\ud574\uc57c \ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \uc26c\uc6cc \ubcf4\uc774\ub294 \uc74c\uc545\uc744 \uac00\uce58\uac00 \uc791\ub2e4\uace0 \ud310\ub2e8\ud558\uc9c0 \uc54a\ub294 \uc5ec\uc720\ub294 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ub208\uc5d0 \uc798 \ubcf4\uc774\ub294 \ud070 \uc6c0\uc9c1\uc784\ub9cc\uc774 \uc608\uc220\uc758 \uc5b4\ub824\uc6c0\uacfc \uae4a\uc774\ub97c \ub9cc\ub4dc\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc0ac\uc2e4\uc744 \uc774 \uace1\uc5d0\uc11c\ub3c4 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \u300a\uc5b4\ub9b0\uc774 \uc815\uacbd\u300b\uc758 \uc81c\ubaa9\ub4e4\uc744 \ub530\ub77c\uac00\uba74 \ub180\uc774\uc640 \uc0ac\uac74, \ubabd\uc0c1\uacfc \ud734\uc2dd\uc758 \ud45c\uc815\uc774 \uc774\uc6c3\ud55c\ub2e4. \u3008\ud2b8\ub85c\uc774\uba54\ub77c\uc774\u3009\ub97c \ub530\ub85c \ub4e4\uc744 \ub54c\uc758 \uace0\uc694\uc640 \ubaa8\uc74c\uace1 \uc548\uc5d0\uc11c \ub9cc\ub0a0 \ub54c\uc758 \uace0\uc694\ub294 \ub2e4\ub974\uac8c \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \uc5b4\ub514\uc5d0 \ub193\uc600\ub294\uc9c0\uac00 \ub4e3\ub294 \uacbd\ud5d8\uc744 \ubc14\uafbc\ub2e4. \uc61b \uc288\ub9cc \ud574\uc124\ub3c4 \uc774 \uc81c\ubaa9\ub4e4\uc758 \uc774\uc5b4\uc9d0\uc744 \uc0b4\ud53c\uba70 \uc544\uc774\uc758 \ubc14\uae65 \ud65c\ub3d9\uc5d0\uc11c \uc548\ucabd \ub9c8\uc74c\uc73c\ub85c \uc2dc\uc120\uc774 \uc62e\uaca8 \uac00\ub294 \ub4ef\ud55c \uac10\uc0c1\uc744 \uc804\ud55c\ub2e4. \uadf8\uac83\uc744 \ubaa8\ub4e0 \uad00\uac1d\uc758 \uc815\ub2f5\uc73c\ub85c \uc0bc\uc744 \ud544\uc694\ub294 \uc5c6\uc9c0\ub9cc, \uc21c\uc11c\ub97c \ubc14\uafb8\uc9c0 \uc54a\uace0 \ubaa8\uc74c\uace1\uc744 \ub9cc\ub098 \ubcfc \uc774\uc720\ub294 \ub41c\ub2e4. \uc791\uc740 \uace1\ub4e4\uc774 \uc11c\ub85c\uc758 \ubd84\uc704\uae30\ub97c \ubc1d\ud600 \uc904 \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\uc5d0\ub294 \ud53c\uc544\ub178\uc640 \uc5f4\ub9b0 \ucc3d, \uc791\uc740 \uc7a5\ub09c\uac10\uacfc \uc815\uc6d0\uc744 \ubc14\ub77c\ubcf4\ub294 \uc0ac\ub78c\uc774 \uc788\ub2e4. \uc81c\ubaa9\uc774 \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \ud68c\uc0c1\uacfc \ubabd\uc0c1\uc758 \ubd84\uc704\uae30\ub97c \uc0c8\ub85c \uadf8\ub9b0 \uadf8\ub9bc\uc774\ub2e4. \uc288\ub9cc\uc774\ub098 \ud074\ub77c\ub77c\uc758 \uc2e4\uc81c \ubc29\uc744 \ubcf5\uc6d0\ud558\uac70\ub098 \uc791\uace1 \uc21c\uac04\uc744 \uc7ac\ud604\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \ub3c5\uc790\ub294 \uadf8\ub9bc\uc5d0\uc11c \uc790\uae30\ub9cc\uc758 \uae30\uc5b5\uc744 \ub5a0\uc62c\ub824\ub3c4 \uc88b\uace0, \uc774\ubbf8\uc9c0\ub97c \uc7a0\uc2dc \ub36e\uace0 \uc74c\uc545\uc744 \ub4e4\uc5b4\ub3c4 \uc88b\ub2e4. \ud55c \uc7a5\uc18c\uc640 \uc0ac\uc5f0\uc744 \uc815\ub2f5\uc73c\ub85c \ubd99\uc774\uc9c0 \uc54a\uae30 \uc704\ud574 \uc545\ubcf4\uc758 \uac00\uc9dc \uc74c\ud45c\ub098 \ud2b9\uc815 \uc778\ubb3c\uc758 \uc5bc\uad74\uc740 \ub123\uc9c0 \uc54a\uc558\ub2e4. \uc74c\uc545\uc744 \ub4e3\ub294 \uc790\uc720\ub97c \ub3d5\ub294 \uad00\ub828 \uc774\ubbf8\uc9c0\ub85c \uc900\ube44\ud588\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc120\uc728\uc744, \ub2e4\uc74c\uc5d0\ub294 \uc544\ub798\uc758 \uc18c\ub9ac\ub97c, \uadf8\ub2e4\uc74c\uc5d0\ub294 \uad6c\uc808\uc774 \uc26c\ub294 \uacf3\uc744 \ub4e4\uc5b4 \ubcf4\uc790. \ubaa8\ub450 \ub2e4\ub974\ub2e4\uace0 \ub290\ub07c\uc9c0 \ubabb\ud574\ub3c4 \uad1c\ucc2e\ub2e4. \uc7a0\uae50 \uc9d1\uc911\ud560 \ub300\uc0c1\uc744 \ubc14\uafb8\ub294 \uac83\ub9cc\uc73c\ub85c \uac19\uc740 \uace1\uc744 \ub4e3\ub294 \uc790\uc138\uac00 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \u3008\ud2b8\ub85c\uc774\uba54\ub77c\uc774\u3009\uc5d0\uc11c \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \uac19\uc740 \uc5b4\ub9b0 \uc2dc\uc808\uc744 \ub5a0\uc62c\ub9b4 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc624\ub798\ub41c \uae30\uc5b5\ucc98\ub7fc \ub4e4\ub9b0\ub2e4\ub294 \uac10\uc0c1\ub3c4 \ud55c \uac00\uc9c0 \uac00\ub2a5\uc131\uc774\ub2e4. \uc9e7\uc740 \uc74c\uc545\uc774 \uac01\uc790\uc758 \uc2dc\uac04\uacfc \ub9cc\ub098\uba70 \uc624\ub798 \ub0a8\uc744 \uc218 \uc788\ub2e4\ub294 \uc810\uc774 \uc774 \uc791\ud488\uc744 \uac70\ub4ed \ucc3e\uac8c \ud55c\ub2e4. \uc791\uc740 \uace1 \ud558\ub098\ub97c \ucda9\ubd84\ud788 \ub4e4\uc740 \uacbd\ud5d8\ub3c4 \uad50\uc591\uc758 \ud55c \ud615\ud0dc\uac00 \ub420 \uc218 \uc788\ub2e4."}, {"id": "sherlock-red-headed-league", "title": "\ubd89\uc740 \uba38\ub9ac \uc5f0\ub9f9 \u2014 \ub108\ubb34 \uc88b\uc740 \uc544\ub974\ubc14\uc774\ud2b8\uc758 \ube44\ubc00", "summary": "\ubc31\uacfc\uc0ac\uc804\uc744 \ubca0\ub07c\ub294 \uc77c\uacfc \uc804\ub2f9\ud3ec\uc758 \uc9c0\ud558\uc2e4\uc774 \uc5b4\ub5bb\uac8c \uc774\uc5b4\uc9c0\ub294\uc9c0 \uc0ac\uac74\uc758 \ud574\uacb0\uae4c\uc9c0 \ub530\ub77c\uac11\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Literature", "url": "stories/sherlock-red-headed-league/index.html", "image": "media/sherlock-red-headed-league.png", "alt": "\ubd89\uc740 \uba38\ub9ac\uc758 \uc70c\uc2a8\uc774 \ub7f0\ub358 \uc0ac\ubb34\uc2e4\uc5d0\uc11c \ucee4\ub2e4\ub780 \ubc31\uacfc\uc0ac\uc804\uc744 \uc190\uc73c\ub85c \ubca0\ub07c\ub294 \uc6d0\uc791 \uae30\ubc18 \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\ubd89\uc740 \uba38\ub9ac \uc5f0\ub9f9 \u2014 \ub108\ubb34 \uc88b\uc740 \uc544\ub974\ubc14\uc774\ud2b8\uc758 \ube44\ubc00 \uc15c\ub85d \ud648\uc988\ub294 \uc774\uc0c1\ud55c \uc77c\uc790\ub9ac\uc5d0\uc11c \ubb34\uc5c7\uc744 \ubcf4\uc558\uc744\uae4c \ubc31\uacfc\uc0ac\uc804\uc744 \ubca0\ub07c\ub294 \uc77c\uacfc \uc804\ub2f9\ud3ec\uc758 \uc9c0\ud558\uc2e4\uc774 \uc5b4\ub5bb\uac8c \uc774\uc5b4\uc9c0\ub294\uc9c0 \uc0ac\uac74\uc758 \ud574\uacb0\uae4c\uc9c0 \ub530\ub77c\uac11\ub2c8\ub2e4. Literature \ubb38\ud654 \uba38\ub9ac\uce74\ub77d\uc774 \ubd89\ub2e4\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \ub3c8\uc744 \ubc1b\ub294 \uc790\ub9ac\uac00 \uc788\ub2e4. \ud574\uc57c \ud560 \uc77c\uc740 \uc815\ud574\uc9c4 \uc2dc\uac04\uc5d0 \uc0ac\ubb34\uc2e4\uc5d0 \uc640\uc11c \ubc31\uacfc\uc0ac\uc804\uc744 \ubca0\ub07c\ub294 \uac83\ubfd0\uc774\ub2e4. \uc774\uc0c1\ud558\uc9c0\ub9cc \ub3c8\uc740 \uc81c\ub300\ub85c \uc9c0\uae09\ub41c\ub2e4. \uc544\uc11c \ucf54\ub10c \ub3c4\uc77c\uc758 \uc15c\ub85d \ud648\uc988 \uc774\uc57c\uae30 \u300c\ubd89\uc740 \uba38\ub9ac \uc5f0\ub9f9\u300d\uc740 \uc774\ub807\uac8c \uc6b0\uc2a4\uc6b4 \uad6c\uc778 \uad11\uace0\ub85c \ub3c5\uc790\ub97c \ubd88\ub7ec\ub4e4\uc778\ub2e4. \uc0ac\uc18c\ud558\uace0 \uae30\ubb18\ud574 \ubcf4\uc774\ub294 \uc870\uac74\uc774 \uc0ac\uc2e4\uc740 \ub204\uad70\uac00\uc5d0\uac8c \ub9e4\uc6b0 \uc911\uc694\ud55c \uc7a5\uce58\uc600\ub2e4. \ubb34\uc5c7\uc774 \uc774\uc0c1\ud55c\uac00\ub97c \uc54c\uc544\ucc28\ub9ac\ub294 \uc77c\uacfc \uadf8 \uc774\uc0c1\ud568\uc774 \ub204\uad6c\uc5d0\uac8c \ub3c4\uc6c0\uc774 \ub418\ub294\uc9c0 \ubb3b\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \uc544\ub798\uc5d0\ub294 \uc0ac\uac74\uc758 \ud574\uacb0\uacfc \uacb0\ub9d0\uc774 \ud3ec\ud568\ub418\uc5b4 \uc788\ub2e4. \uc81c\uc774\ubca0\uc988 \uc70c\uc2a8\uc740 \ub7f0\ub358\uc5d0\uc11c \uc791\uc740 \uc804\ub2f9\ud3ec\ub97c \uc6b4\uc601\ud55c\ub2e4. \uadf8\uc758 \uc870\uc218 \ube48\uc13c\ud2b8 \uc2a4\ud3f4\ub529\uc740 \uc2e0\ubb38 \uad11\uace0\ub97c \ubcf4\uc5ec \uc8fc\uba70 \ubd89\uc740 \uba38\ub9ac \ub0a8\uc131\ub4e4\uc744 \uc704\ud55c \uc790\ub9ac\ub97c \uad8c\ud55c\ub2e4. \uc70c\uc2a8\uc5d0\uac8c\ub294 \ud3c9\ubc94\ud55c \uc601\uc5c5 \uc678\uc5d0 \uc548\uc815\uc801\uc778 \uc218\uc785\uc774 \uc0dd\uae38 \uae30\ud68c\ucc98\ub7fc \ubcf4\uc778\ub2e4. \uc774\uc57c\uae30\ub294 \uc758\uc0ac \uc653\uc2a8\uc774 \ud648\uc988\uc640 \ud568\uaed8 \uc70c\uc2a8\uc758 \ub9d0\uc744 \ub4e3\ub294 \ubc29\uc2dd\uc73c\ub85c \uc9c4\ud589\ub41c\ub2e4. \ub3c5\uc790\ub3c4 \uc190\ub2d8\uacfc \uac19\uc740 \uc815\ubcf4\ub97c \uc804\ub2ec\ubc1b\uc9c0\ub9cc \ud648\uc988\ub294 \ubb34\uc5c7\uc744 \ub530\ub85c \uae30\uc5b5\ud558\ub294\uc9c0 \ucda9\ubd84\ud788 \uc54c\ub824 \uc8fc\uc9c0 \uc54a\ub294\ub2e4. \uac19\uc740 \uc124\uba85\uc744 \ub4e4\uc73c\uba74\uc11c \uc11c\ub85c \ub2e4\ub978 \uac83\uc5d0 \uc8fc\ubaa9\ud558\ub294 \uc0ac\ub78c\ub4e4\uc758 \ucc28\uc774\uac00 \ucd94\ub9ac\uc758 \uc7ac\ubbf8\ub97c \ub9cc\ub4e0\ub2e4. \uc9c0\uc6d0 \uc7a5\uc18c\uc5d0\ub294 \ubd89\uc740 \uba38\ub9ac\uc758 \ub0a8\uc790\ub4e4\uc774 \ub9ce\uc774 \ubaa8\uc5ec \uc788\ub2e4. \uc70c\uc2a8\uc740 \uc790\uc2e0\uc758 \uba38\ub9ac\uc0c9\uc744 \ud655\uc778\ubc1b\uace0 \uc790\ub9ac\ub97c \uc5bb\ub294\ub2e4. \ubcc4\uac83 \uc544\ub2cc \uc870\uac74\uc774 \uc5c4\uaca9\ud558\uac8c \uac80\uc0ac\ub418\uace0 \uacbd\uc7c1\uae4c\uc9c0 \ubc8c\uc5b4\uc9c0\uc790, \uc774\uc0c1\ud55c \uc77c\uc740 \uc624\ud788\ub824 \uc81c\ub300\ub85c \uc6b4\uc601\ub418\ub294 \uc81c\ub3c4\ucc98\ub7fc \ubcf4\uc774\uae30 \uc2dc\uc791\ud55c\ub2e4. \uc774\ub7f0 \uc7a5\uba74\uc740 \uc0ac\ub78c\uc758 \ubbff\uc74c\uc744 \ub9cc\ub4dc\ub294 \ubc29\uc2dd\ub3c4 \ubcf4\uc5ec \uc900\ub2e4. \uc904\uc744 \uc120 \uc0ac\ub78c\uc774 \ub9ce\uace0 \ub2f4\ub2f9\uc790\uac00 \uae4c\ub2e4\ub86d\uac8c \uad74\uba74 \uae30\ud68c\uac00 \ud76c\uadc0\ud558\uace0 \uc911\uc694\ud558\ub2e4\uace0 \ub290\ub07c\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \ub9ce\uc740 \uc9c0\uc6d0\uc790\uc640 \uc815\uad50\ud55c \uc808\ucc28\uac00 \uc788\ub2e4\uace0 \ud574\uc11c \uc77c\uc790\ub9ac\uc758 \ubaa9\uc801\uae4c\uc9c0 \uc815\ub2f9\ud558\ub2e4\ub294 \ubcf4\uc7a5\uc740 \uc5c6\ub2e4. \uc18c\uc124\uc740 \uadf8 \ud2c8\uc744 \uc7a5\ub09c\uc2a4\ub7fd\uac8c \uc774\uc6a9\ud55c\ub2e4. \uc70c\uc2a8\uc774 \ud558\ub294 \uc77c\uc740 \ubc31\uacfc\uc0ac\uc804\uc744 \uc190\uc73c\ub85c \uc62e\uaca8 \uc4f0\ub294 \uac83\uc774\ub2e4. \uadfc\ubb34 \uc2dc\uac04\uc740 \uc624\uc804 \uc5f4 \uc2dc\ubd80\ud130 \uc624\ud6c4 \ub450 \uc2dc\uae4c\uc9c0\uc774\uace0, \uadf8\ub3d9\uc548 \uc0ac\ubb34\uc2e4\uc744 \ub5a0\ub098\uba74 \uc548 \ub41c\ub2e4. \ubcf4\uc218\ub294 \uc8fc\ub2f9 4\ud30c\uc6b4\ub4dc\ub2e4. \ubc18\ubcf5\ud574\uc11c \uc798 \uc9c0\uae09\ub418\ub2c8 \ucc98\uc74c\uc758 \uc758\uc2ec\uc740 \ub204\uadf8\ub7ec\uc9c4\ub2e4. \ub3c5\uc790\ub294 \ubb34\uc5c7\uc744 \uc65c \ubca0\ub07c\ub294\uc9c0\uc5d0 \uad00\uc2ec\uc744 \uac16\uac8c \ub418\uc9c0\ub9cc \ub2e4\ub978 \uc9c8\ubb38\ub3c4 \uac00\ub2a5\ud558\ub2e4. \uc774 \uc77c\uc774 \uc2e4\uc81c\ub85c \uc0dd\uc0b0\ud558\ub294 \uac83\uc740 \uae00\uc758 \uc0ac\ubcf8\ubfd0\uc77c\uae4c. \uadfc\ubb34 \uc2dc\uac04 \ub3d9\uc548 \uc70c\uc2a8\uc774 \uc5b4\ub514\uc5d0 \uc5c6\uac8c \ub418\ub294\uc9c0 \uc0dd\uac01\ud558\uba74 \uc0ac\uac74\uc758 \ubc29\ud5a5\uc774 \ubc14\ub010\ub2e4. \ub178\ub3d9\uc758 \uacb0\uacfc\ubcf4\ub2e4 \uc0ac\ub78c\uc758 \uc790\ub9ac\ub97c \uc77c\uc815\ud558\uac8c \ube44\uc6cc \ub450\ub294 \uc77c\uc774 \uc911\uc694\ud560 \uc218 \uc788\ub2e4. \uc77c\uc774 \uacc4\uc18d\ub418\ub358 \uc5b4\ub290 \ub0a0 \uc70c\uc2a8\uc740 \uc5f0\ub9f9\uc774 \ud574\uc0b0\ub418\uc5c8\ub2e4\ub294 \uc548\ub0b4\ub97c \ubc1c\uacac\ud55c\ub2e4. \uc124\uba85\ud574 \uc904 \uc0ac\ub78c\uc740 \uc5c6\uace0 \ub2f4\ub2f9\uc790\uc758 \uc815\uccb4\ub3c4 \ubd84\uba85\ud558\uc9c0 \uc54a\ub2e4. \uc790\uc2e0\uc774 \uc77c\ud55c \uc774\uc720\ubcf4\ub2e4 \uac11\uc790\uae30 \uc218\uc785\uc744 \uc783\uc5c8\ub2e4\ub294 \ub2f9\ud639\uac10\uc774 \uba3c\uc800 \ub4e0\ub2e4. \uadf8\ub294 \uc774 \uc774\uc0c1\ud55c \uc77c\uc744 \ud648\uc988\uc5d0\uac8c \uac00\uc838\uc628\ub2e4. \uc774\ubbf8 \ub3c8\uc744 \ubc1b\uc558\uc73c\ub2c8 \uc18d\uc740 \uac83\uc774 \uc5c6\ub2e4\uace0 \uc0dd\uac01\ud560 \uc218\ub3c4 \uc788\ub2e4. \ud558\uc9c0\ub9cc \ub204\uad70\uac00\uac00 \ubcf4\uc218\ub97c \uc9c0\uae09\ud574\uc11c\ub77c\ub3c4 \uc5bb\uace0 \uc2f6\uc5c8\ub358 \uac83\uc774 \ubb34\uc5c7\uc778\uc9c0\uac00 \ub0a8\ub294\ub2e4. \uac89\uc73c\ub85c \ubcf4\uc774\ub294 \uac70\ub798\uac00 \uc190\ud574\ucc98\ub7fc \ubcf4\uc774\uc9c0 \uc54a\uc544\ub3c4, \uadf8 \uac70\ub798 \ub4a4\uc5d0 \ub2e4\ub978 \uacc4\ud68d\uc774 \uc788\uc744 \uc218 \uc788\ub2e4. \ud648\uc988\ub294 \uad11\uace0\uc758 \uae30\ubb18\ud568\uc744 \uac10\uc0c1\ud558\ub294 \ub370\uc11c \uba48\ucd94\uc9c0 \uc54a\ub294\ub2e4. \ud648\uc988\ub294 \uc804\ub2f9\ud3ec \uc8fc\ubcc0\uc744 \uc0b4\ud53c\uace0 \uc870\uc218\uc640\ub3c4 \ub9c8\uc8fc\uce5c\ub2e4. \uc70c\uc2a8\uc774 \ub9d0\ud55c \uc870\uc218\uc758 \uc0ac\uc9c4 \ucde8\ubbf8\uc640 \uc9c0\ud558\uc2e4\uc5d0 \uba38\ubb34\ub294 \uc2b5\uad00\uc740 \ub2e4\ub978 \ub73b\uc744 \uc5bb\ub294\ub2e4. \ud648\uc988\uac00 \uc8fc\ubaa9\ud55c \ubc14\uc9c0 \ubb34\ub98e\uc758 \ud754\uc801\ub3c4 \uadf8 \uc0ac\ub78c\uc774 \ubab8\uc744 \uc5b4\ub5bb\uac8c \uc0ac\uc6a9\ud588\ub294\uc9c0 \uc0dd\uac01\ud558\uac8c \ud558\ub294 \ub2e8\uc11c\ub2e4. \uac70\ub9ac\uc5d0\uc11c \ubcf4\uc774\ub294 \uac74\ubb3c\uc758 \uc55e\uba74\ub9cc\uc73c\ub85c\ub294 \ucda9\ubd84\ud558\uc9c0 \uc54a\ub2e4. \uc804\ub2f9\ud3ec \ub4a4\ucabd\uc774 \uc5b4\ub5a4 \uc7a5\uc18c\uc640 \uc774\uc5b4\uc9c0\ub294\uc9c0 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \ud648\uc988\uac00 \uace8\ubaa9\uacfc \uc8fc\ubcc0\uc744 \ud655\uc778\ud558\ub294 \uc7a5\uba74\uc740 \uc791\uc740 \uc810\ud3ec\ub97c \ub354 \ud070 \uacf5\uac04 \uc548\uc5d0 \ub193\ub294\ub2e4. \uc774\uc57c\uae30\uc758 \uc9c0\ub3c4\ub294 \uc885\uc774\uc5d0\ub9cc \uc788\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uac74\ubb3c\uc758 \ubc30\uce58 \uc18d\uc5d0\ub3c4 \uc788\ub2e4. \ubaa9\ud45c\ub294 \uac00\uae4c\uc6b4 \uc740\ud589\uc758 \uc9c0\ud558\uc5d0 \ubcf4\uad00\ub41c \uae08\uc774\uc5c8\ub2e4. \ubc94\uc778\ub4e4\uc740 \uc804\ub2f9\ud3ec \uc9c0\ud558\uc5d0\uc11c \uc740\ud589 \ucabd\uc73c\ub85c \ud1b5\ub85c\ub97c \ub9cc\ub4e4\ub824 \ud588\ub2e4. \uc774\ub97c \uc704\ud574 \uc8fc\uc778\uc778 \uc70c\uc2a8\uc744 \ub9e4\uc77c \uc77c\uc815\ud55c \uc2dc\uac04 \uac00\uac8c \ubc16\uc5d0 \ub450\ub294 \uc7a5\uce58\uac00 \ud544\uc694\ud588\ub2e4. \uc870\uc218\uac00 \uc0c1\ub300\uc801\uc73c\ub85c \uc801\uc740 \ubcf4\uc218\ub85c \uc77c\ud558\ub358 \uc774\uc720\ub3c4 \uc774 \uacc4\ud68d \uc18d\uc5d0\uc11c \ub2ec\ub77c \ubcf4\uc778\ub2e4. \ubd89\uc740 \uba38\ub9ac\ub77c\ub294 \uc870\uac74\uacfc \ubc31\uacfc\uc0ac\uc804 \ud544\uc0ac\ub294 \uc70c\uc2a8\uc744 \ud2b9\ubcc4\ud788 \uc120\ud0dd\ub41c \uc0ac\ub78c\ucc98\ub7fc \ub290\ub07c\uac8c \ud558\ub294 \ubb34\ub300\uc600\ub2e4. \uc784\uae08\uc744 \uc2e4\uc81c\ub85c \uc9c0\uae09\ud55c \uac83\ub3c4 \uacc4\ud68d\uc744 \uc720\uc9c0\ud558\uae30 \uc704\ud55c \ube44\uc6a9\uc774\uc5c8\ub2e4. \uc774\uc0c1\ud55c \uc77c\uc790\ub9ac\uc640 \uc9c4\uc9c0\ud55c \ubc94\uc8c4\uac00 \uc11c\ub85c \ubb34\uad00\ud55c \uc774\uc57c\uae30\uac00 \uc544\ub2c8\uc5c8\ub358 \uac83\uc774\ub2e4. \uc5f0\ub9f9\uc774 \uc0ac\ub77c\uc9c4 \uc2dc\uc810\uc740 \uc900\ube44\uac00 \ub05d\ub0ac\ub2e4\ub294 \uc2e0\ud638\ub85c \uc77d\ud78c\ub2e4. \ud648\uc988\uc640 \ub3d9\ub8cc\ub4e4\uc740 \uc740\ud589 \uc9c0\ud558\uc5d0\uc11c \ubc94\uc778\ub4e4\uc774 \ub098\ud0c0\ub098\uae30\ub97c \uae30\ub2e4\ub9b0\ub2e4. \ubc1d\uc740 \uc0ac\ubb34\uc2e4\uc5d0\uc11c \uc6b0\uc2a4\uc6b4 \uc0ac\uc5f0\uc744 \ub4e3\ub358 \ubd84\uc704\uae30\ub294 \uc5b4\ub450\uc6b4 \uacf5\uac04\uc758 \uae34\uc7a5\uc73c\ub85c \ubc14\ub010\ub2e4. \uc870\uc218\ub85c \ud589\uc138\ud55c \uc778\ubb3c\uc758 \uc815\uccb4\uc640 \uacc4\ud68d\uc774 \ub4dc\ub7ec\ub098\uace0 \ubc94\ud589\uc740 \uc800\uc9c0\ub41c\ub2e4. \ud648\uc988\ub294 \ub098\uc911\uc5d0 \uc790\uc2e0\uc774 \uc5b4\ub5a4 \ub2e8\uc11c\ub97c \uc5f0\uacb0\ud588\ub294\uc9c0 \uc124\uba85\ud55c\ub2e4. \ub3c5\uc790\ub294 \uc55e\uc5d0\uc11c \uc774\ubbf8 \uc77d\uc5c8\ub358 \uc815\ubcf4\ub97c \ub2e4\uc2dc \ubcf4\uac8c \ub41c\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc9c0\ub098\uce5c \uba38\ub9ac\uc0c9 \uac80\uc0ac\ub098 \uadfc\ubb34 \uaddc\uc815\uc774 \uc6c3\uc74c\uc758 \uc7ac\ub8cc\uc600\uc9c0\ub9cc, \uacb0\ub9d0 \ub4a4\uc5d0\ub294 \ubaa9\uc801\uc744 \ub2ec\uc131\ud558\uae30 \uc704\ud574 \uc9dc\uc778 \uc870\uac74\uc73c\ub85c \ubc14\ub010\ub2e4. \ub2e4\uc2dc \uc77d\uc744 \ub54c \uc7ac\ubbf8\uac00 \ub0a8\ub294 \uc774\uc720\ub2e4. \uc774 \uc774\uc57c\uae30\ub294 \uc138\uc0c1\uc5d0\uc11c \ub108\ubb34 \uc88b\uc740 \uc81c\uc548\uc744 \ub9cc\ub098\uba74 \ubaa8\ub450 \ubc94\uc8c4\ub77c\uace0 \uc0dd\uac01\ud558\ub77c\ub294 \uc124\uba85\uc11c\uac00 \uc544\ub2c8\ub2e4. \uc18c\uc124\uc758 \uc990\uac70\uc6c0\uc740 \uad00\ucc30\ud55c \uac83\ub4e4\uc774 \ud558\ub098\uc758 \ubaa9\uc801\uacfc \uacf5\uac04 \uc548\uc5d0\uc11c \ub9de\ubb3c\ub9ac\ub294 \uc21c\uac04\uc5d0 \uc788\ub2e4. \ub2e8\uc11c\ub97c \ub9ce\uc774 \ubcf4\ub294 \uc77c\ubfd0 \uc544\ub2c8\ub77c \uc5b4\ub290 \uc9c8\ubb38\uc744 \ub358\uc9c8\uc9c0\uac00 \uc911\uc694\ud558\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \ubc31\uacfc\uc0ac\uc804\uc744 \ubca0\ub07c\ub294 \uc70c\uc2a8\uc758 \uc0c1\ud669\uc744 \uc0c8\ub85c \uc0c1\uc0c1\ud588\ub2e4. \uc0ac\uac74\uc758 \uc9c0\ub3c4\ub97c \uadf8\ub824 \uc815\ub2f5\uc744 \uba3c\uc800 \uc54c\ub824 \uc8fc\ub294 \uadf8\ub9bc\uc740 \uc544\ub2c8\ub2e4. \ud3c9\ubc94\ud558\uac8c \ucc45\uc0c1 \uc55e\uc5d0 \uc549\uc740 \uc0ac\ub78c\uc774 \uc5b4\ub5a4 \uacc4\ud68d\uc758 \uc77c\ubd80\uac00 \ub418\uc5b4 \uc788\ub294\uc9c0, \ubcf8\ubb38\uc744 \ub530\ub77c\uac00\uba70 \uc870\uae08 \ub2a6\uac8c \uc54c\uc544\ucc28\ub9ac\ub294 \uc7ac\ubbf8\ub97c \ub0a8\uaca8 \ub450\uc5c8\ub2e4."}, {"id": "silver-kettle-hidden-letters", "title": "\uc8fc\uc804\uc790\uc758 \uc774\uc57c\uae30\ub294 \ubc14\ub2e5\uc5d0\ub3c4 \uc801\ud600 \uc788\ub2e4", "summary": "\uc740\uc81c \uc8fc\uc804\uc790\uc758 \uaf43\ubd09\uc624\ub9ac \uc190\uc7a1\uc774\uc640 \ubc14\ub2e5\uc758 \uba85\ubb38\uc744 \ucc3e\uc544\ubd05\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Art", "url": "stories/silver-kettle-hidden-letters/index.html", "image": "media/silver-kettle-hidden-letters.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc740\uc81c\uc8fc\uc804\uc790 \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc8fc\uc804\uc790\uc758 \uc774\uc57c\uae30\ub294 \ubc14\ub2e5\uc5d0\ub3c4 \uc801\ud600 \uc788\ub2e4 \ubc18\uc9dd\uc774\ub294 \ubab8\uccb4 \uc544\ub798\uc758 \uc791\uc740 \uae00\uc790\ub4e4 \uc740\uc81c \uc8fc\uc804\uc790\uc758 \uaf43\ubd09\uc624\ub9ac \uc190\uc7a1\uc774\uc640 \ubc14\ub2e5\uc758 \uba85\ubb38\uc744 \ucc3e\uc544\ubd05\ub2c8\ub2e4. Art \ubb38\ud654 \uc740\ube5b \uc8fc\uc804\uc790\ub97c \ubcf4\uba74 \uba3c\uc800 \uae38\uac8c \ubed7\uc740 \uc8fc\ub465\uc774\uc640 \ud718\uc5b4\uc9c4 \uc190\uc7a1\uc774\uac00 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uac00\uc6b4\ub370 \ub465\uadfc \ubab8\ud1b5\uae4c\uc9c0, \ubb3c\uc744 \ub530\ub974\ub294 \ubb3c\uac74\uc774\ub77c\ub294 \uc0ac\uc2e4\uc740 \uc5b4\ub835\uc9c0 \uc54a\uac8c \uc54c\uc544\ubcfc \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uc774 \uc8fc\uc804\uc790\ub294 \uc606\ubaa8\uc2b5\ub9cc \ubcf4\uace0 \ub05d\ub0b4\uae30 \uc544\uae5d\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \uc124\uba85\uc744 \ub530\ub77c\uac00\uba74 \ub69c\uaed1\uc5d0\ub294 \uaf43\ubd09\uc624\ub9ac\uac00 \uc788\uace0, \ubab8\uccb4 \uc591\ucabd\uc5d0\ub294 \uae00\uc790\uac00 \uc788\uc73c\uba70, \ubc14\ub2e5\uc5d0\ub3c4 \uae30\ub85d\uc774 \uc788\ub2e4. \ud55c \ubb3c\uac74\uc744 \ubcf4\ub294 \ubc29\ud5a5\uc774 \uc138 \ubc88 \ubc14\ub010\ub2e4. \ubc15\ubb3c\uad00\uc740 \ub69c\uaed1 \uc190\uc7a1\uc774\ub97c \uc5f0\ubd09\uc624\ub9ac \ud615\ud0dc\ub85c \uc124\uba85\ud55c\ub2e4. \uc9d1\uc5b4 \ub4dc\ub294 \ubd80\ubd84\uc5d0 \uaf43\uc758 \ubaa8\uc591\uc744 \ube4c\ub824 \ub193\uc740 \uac83\uc774\ub2e4. \uc2e4\uc81c \uc5f0\uaf43\uc774 \ud540 \ud48d\uacbd\uc744 \uadf8\ub9b0 \ub300\uc2e0 \uc190\uc5d0 \ub2ff\ub294 \uc791\uc740 \uaf2d\uc9c0\ub97c \uaf43\ucc98\ub7fc \ub9cc\ub4e4\uc5c8\ub2e4. \ub69c\uaed1\uc5d0\ub294 \uc120\uc73c\ub85c \uc0c8\uae34 \ubc15\uc950\ubb34\ub2ac\ub3c4 \uc788\ub2e4\uace0 \ud55c\ub2e4. \uc0ac\uc9c4 \ud55c \uc7a5\uc5d0 \ubaa8\ub4e0 \ubc29\ud5a5\uc774 \ubcf4\uc774\uc9c0\ub294 \uc54a\uc73c\ub2c8, \ubcf4\uc774\uc9c0 \uc54a\ub294 \ubb34\ub2ac\ub97c \uc5b5\uc9c0\ub85c \ucc3e\uc544\ub0b4\uae30\ubcf4\ub2e4 \uc124\uba85\uc744 \uae38\uc7a1\uc774\ub85c \uc0bc\uc73c\uba74 \ub41c\ub2e4. \ubc15\uc950\uc758 \ub73b\uae4c\uc9c0 \uc774 \uc790\ub8cc\ub9cc\uc73c\ub85c \uae38\uac8c \ud480\uc9c0\ub294 \uc54a\uae30\ub85c \ud558\uc790. \ubab8\uccb4 \uc591\ucabd\uc5d0\ub294 \ub465\uadfc \ud2c0\uc758 \uc218\uba85 \uc218, \uace7 \u58fd\ub97c \ub098\ud0c0\ub0b8 \ubb34\ub2ac\uac00 \uc788\ub2e4. \uc8fc\uc804\uc790\uc758 \ub465\uadfc \ud615\ud0dc \uc548\uc5d0 \uae00\uc790 \uc7a5\uc2dd\uc774 \ub354\ud574\uc9c4 \uac83\uc774\ub2e4. \ub2e8\uc21c\ud788 \ubc18\uc9dd\uc774\ub294 \uc740\uadf8\ub987\uc774\ub77c\uace0\ub9cc \ubcf4\uae30\uc5d0\ub294 \ubcfc\uac70\ub9ac\uac00 \ub9ce\ub2e4. \uad7d\uc5d0\ub294 \uc120\ud76c\uad81\uc744 \ub73b\ud558\ub294 \u5ba3\u79a7\u5bae\uc73c\ub85c \uc2dc\uc791\ud558\ub294 \uae00\uc774 \uc0c8\uaca8\uc838 \uc788\ub2e4. \ubc15\ubb3c\uad00\uc740 \uadf8 \uba85\ubb38 \uc804\uccb4\ub97c \uc18c\uac1c\ud55c\ub2e4. \uadf8\uc911\uc5d0\ub294 \uc0c8\ub85c \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \u65b0\u9020\uc640 \ubb34\uac8c\ub97c \ub73b\ud558\ub294 \u91cd \uac19\uc740 \uae00\uc790\ub3c4 \ubcf4\uc778\ub2e4. \uc7a5\uc2dd\uacfc \ubcc4\uac1c\ub85c \uc81c\uc791\uc5d0 \uad00\ud55c \uc815\ubcf4\ub97c \ub0a8\uae30\ub294 \uc790\ub9ac\uc600\uc74c\uc744 \uc77d\uc744 \uc218 \uc788\ub2e4. \uc8fc\uc804\uc790\ub294 \uc561\uccb4\ub97c \ub2f4\ub294 \ubab8\uccb4\uc640 \ub530\ub974\ub294 \ucabd, \uc190\uc73c\ub85c \uc7a1\ub294 \ubd80\ubd84\uc774 \uad00\uacc4\ub97c \uc774\ub8e8\ub294 \ubb3c\uac74\uc774\ub2e4. \ud45c\uba74\uc758 \uc7a5\uc2dd\uc744 \ucc3e\uae30 \uc804\uc5d0 \uc5b4\ub290 \uacf3\uc744 \ub4e4\uace0 \uc5b4\ub5bb\uac8c \uae30\uc6b8\uc774\uac8c \ub418\ub294\uc9c0 \uc0dd\uac01\ud558\uba74 \ud615\ud0dc\uac00 \ub35c \ub0af\uc124\uc5b4\uc9c4\ub2e4. \ub2e4\ub9cc \uc774 \uc720\ubb3c\uc774 \uc2e4\uc81c\ub85c \uc5b4\ub5a4 \uc790\ub9ac\uc5d0\uc11c \uc5b4\ub5a4 \uc74c\ub8cc\ub97c \ub2f4\uc558\ub294\uc9c0\uae4c\uc9c0 \ubaa8\uc591\ub9cc\uc73c\ub85c \ud655\uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc4f0\uc784\uc758 \uac00\ub2a5\uc131\uacfc \uac1c\ubcc4 \uc0ac\uc6a9 \uc774\ub825\uc740 \ub2e4\ub978 \uc815\ubcf4\ub2e4. \uc5f0\ubd09\uc624\ub9ac\ucc98\ub7fc \ub9cc\ub4e0 \ub69c\uaed1 \uaf2d\uc9c0\ub294 \uc7a5\uc2dd\uc744 \uac10\uc0c1\ud558\ub294 \ub208\uacfc \ubb3c\uac74\uc744 \uc0ac\uc6a9\ud558\ub294 \uc190\uc774 \ub9cc\ub098\ub294 \uc790\ub9ac\ub2e4. \uaf43 \ubaa8\uc591\uc744 \ubcf4\ub294 \ub370\uc11c \ud55c \uac78\uc74c \ub354 \ub098\uc544\uac00 \uc65c \uadf8\ub7f0 \uc704\uce58\uc5d0 \ubd99\uc5b4 \uc788\ub294\uc9c0 \ubcf4\uba74 \ub41c\ub2e4. \uc0dd\ud65c \ub3c4\uad6c\uc758 \uc544\ub984\ub2e4\uc6c0\uc740 \ud45c\uba74\uc5d0 \ubb34\ub2ac\ub97c \ub354\ud558\ub294 \uc77c\uc5d0\ub9cc \uc788\uc9c0 \uc54a\ub2e4. \ub9cc\uc9c0\uace0 \uc5f4\uace0 \ub2eb\ub294 \ubd80\ubd84 \uc790\uccb4\uc5d0 \ud615\uc0c1\uc744 \ub123\ub294 \uc120\ud0dd\ub3c4 \uc788\ub2e4. \ubab8\uccb4\uc758 \uc6d0\uc218\ubb38\uc740 \uc218\uba85 \uc218\ub77c\ub294 \uae00\uc790\ub97c \uc7a5\uc2dd\uc758 \uad6c\uc131\uc73c\ub85c \uc0ac\uc6a9\ud55c\ub2e4. \ubb38\uc790\ub97c \uc77d\ub294 \uc77c\uacfc \ubb34\ub2ac\ub97c \ubcf4\ub294 \uc77c\uc774 \uacb9\uce5c\ub2e4. \ub73b\uc744 \ubaa8\ub974\uba74 \ub465\uadfc \ud615\ud0dc\uc640 \uc120\uc758 \ubc30\uc5f4\uc774 \uba3c\uc800 \ubcf4\uc774\uace0, \ub73b\uc744 \uc54c\uba74 \uadf8 \uc548\uc758 \ubc14\ub78c\uc744 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \ud55c \ud45c\uba74\uc774 \ub450 \uac00\uc9c0 \uc77d\uae30\uc758 \uc18d\ub3c4\ub97c \ud5c8\uc6a9\ud558\ub294 \uc148\uc774\ub2e4. \uadf8\ub807\ub2e4\uace0 \uac19\uc740 \uae00\uc790\uac00 \ubcf4\uc774\ub294 \ubaa8\ub4e0 \ubb3c\uac74\uc5d0 \ub3d9\uc77c\ud55c \uc0ac\uc6a9\uc790\ub97c \uc0c1\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc7a5\uc2dd\uc5d0 \ub2f4\uae34 \uc77c\ubc18\uc801\uc778 \uc758\ubbf8\uc640 \ub204\uac00 \uc5b8\uc81c \uc5b4\ub5a4 \ubaa9\uc801\uc73c\ub85c \uc0ac\uc6a9\ud588\ub294\uc9c0\ub294 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \uc774 \uc8fc\uc804\uc790\uc5d0\uc11c\ub294 \ubab8\uccb4\uc640 \ub69c\uaed1\uc758 \uc7a5\uc2dd\uc744 \ub098\ub204\uc5b4 \ubcf4\ub294 \uac83\ub9cc\uc73c\ub85c\ub3c4 \ud45c\uba74\uc774 \ub2e8\uc21c\ud558\uc9c0 \uc54a\uc74c\uc744 \uc54c \uc218 \uc788\ub2e4. \ubb34\ub2ac\ub97c \ubaa8\ub450 \uc678\uc6b0\uae30\ubcf4\ub2e4 \uc5b4\ub514\uc5d0 \ub193\uc600\ub294\uc9c0 \uc0b4\ud53c\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uad7d\uc758 \uba85\ubb38\uc740 \ud3c9\uc18c \uc8fc\uc804\uc790\ub97c \ub193\uc558\uc744 \ub54c \uc27d\uac8c \ub4dc\ub7ec\ub098\uc9c0 \uc54a\ub294 \uc704\uce58\uc5d0 \uc788\ub2e4. \uc798 \ubcf4\uc774\ub294 \ubab8\uccb4\uc758 \uc7a5\uc2dd\uacfc \ub2e4\ub978 \uc815\ubcf4\ub97c \ub9e1\ub294\ub2e4. \uc120\ud76c\uad81\uc774\ub77c\ub294 \uc774\ub984\uacfc \uc0c8\ub85c \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \ud45c\ud604, \ubb34\uac8c\ub97c \uac00\ub9ac\ud0a4\ub294 \ub9d0\uc774 \ud568\uaed8 \uc788\ub2e4. \uac10\uc0c1\ud560 \ud45c\uba74\ub9cc \ubcf8\ub2e4\uba74 \ub193\uce60 \uc81c\uc791\uacfc \uad00\ub9ac\uc758 \ub2e8\uc11c\uac00 \uc544\ub798\ucabd\uc5d0 \ub0a8\uc740 \uac83\uc774\ub2e4. \uba85\ubb38 \uc18d \uc5f0\ub3c4 \ud45c\ud604\uc744 \uc624\ub298\uc758 \uc5f0\ub3c4\ub85c \ud480\uc5b4 \uc77d\ub294 \ub370\uc5d0\ub294 \ub2e4\ub978 \uae30\ub85d\uacfc \ub2f9\uc2dc \ud45c\uae30\ubc95\uc758 \ud655\uc778\uc774 \ud544\uc694\ud558\ub2e4. \ubb34\uac8c \uc5ed\uc2dc \uc61b \ub2e8\uc704\ub97c \ud604\uc7ac\uc758 \uadf8\ub7a8\uc73c\ub85c \ubc14\ub85c \ubc14\uafb8\uc5b4 \uc801\uc9c0 \uc54a\ub294\ub2e4. \ub300\uc2e0 \uc774\ub984\uacfc \uc2dc\uae30, \uc81c\uc791\uacfc \uc218\ub7c9\uc5d0 \uad00\ud55c \uc815\ubcf4\uac00 \ud558\ub098\uc758 \uc9e7\uc740 \uae00 \uc548\uc5d0 \ubb36\uc600\ub2e4\ub294 \uc810\uc744 \ubcfc \uc218 \uc788\ub2e4. \uc790\ub8cc\uc5d0 \uc4f0\uc778 \ub2e8\uc704\ub97c \uadf8\ub300\ub85c \ub0a8\uae30\ub294 \uac83\uc774 \uc774\ud6c4 \ube44\uad50\uc5d0\ub3c4 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ub208\uc5d0 \uc798 \ub744\ub294 \uc7a5\uc2dd\uc740 \uc0ac\ub78c\uc774 \ubb3c\uac74\uc744 \ubc14\ub77c\ubcf4\uace0 \uc0ac\uc6a9\ud558\ub294 \uc2dc\uac04\uc744 \ub9cc\ub4e0\ub2e4. \ub208\uc5d0 \ub35c \ub744\ub294 \uba85\ubb38\uc740 \uc81c\uc791\uacfc \uc18c\uc18d\uc744 \ud655\uc778\ud558\ub294 \uc2dc\uac04\uc744 \uc5f0\ub2e4. \uc5b4\ub290 \ucabd\ub9cc \uc9c4\uc9dc \uc815\ubcf4\ub77c\uace0 \uace0\ub97c \ud544\uc694\ub294 \uc5c6\ub2e4. \uc8fc\uc804\uc790\ub294 \uc544\ub984\ub2f5\uac8c \ubcf4\uc774\ub3c4\ub85d \ub9cc\ub4e0 \ub3c4\uad6c\uc774\uba74\uc11c \uc774\ub984\uacfc \ubb34\uac8c\ub97c \uc801\uc5b4 \uad00\ub9ac\ud55c \ubb3c\uac74\uc774\uae30\ub3c4 \ud588\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \ubc14\ub2e5\uc774 \ubcf4\uc774\uc9c0 \uc54a\ub354\ub77c\ub3c4 \ubc15\ubb3c\uad00 \uc124\uba85\uc774 \uc774 \ub450 \uce35\uc744 \uc774\uc5b4 \uc900\ub2e4. \uad00\ub78c\uc790\uac00 \uc804\uc2dc\ubb3c\uc744 \uc9c1\uc811 \ub4e4\uc5b4 \ub4a4\uc9d1\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc81c\uacf5\ub41c \ub2e4\ub978 \ubc29\ud5a5\uc758 \uc0ac\uc9c4\uacfc \uae00\uc744 \ud568\uaed8 \ubcf4\ub294 \uac83\uc774 \uc548\uc804\ud558\uace0 \uc815\ud655\ud55c \ubc29\ubc95\uc774\ub2e4. \uc740\ube5b \ud45c\uba74\uc5d0\uc11c \uc2dc\uc791\ud55c \uc774\uc57c\uae30\uac00 \ubc11\uba74\uc758 \uc791\uc740 \uae00\uc790\ub85c \ub0b4\ub824\uac08 \ub54c, \uc0dd\ud65c \ub3c4\uad6c\uac00 \uae30\ub85d \uc790\ub8cc\uac00 \ub418\ub294 \uc21c\uac04\uc744 \ub9cc\ub0a0 \uc218 \uc788\ub2e4. \uc5ec\uae30\uc11c\ub294 \ubb34\uc778\ub144\uc744 \ud2b9\uc815\ud55c \uc11c\uae30 \uc5f0\ub3c4\ub85c \ubc14\uafb8\uac70\ub098 \uc61b \ubb34\uac8c\ub97c \uc9c0\uae08\uc758 \uadf8\ub7a8\uc73c\ub85c \ud658\uc0b0\ud558\uc9c0 \uc54a\ub294\ub2e4. \ucd94\uac00 \ub300\uc870 \uc5c6\uc774 \uc22b\uc790\ub9cc \ud655\uc815\ud558\uba74 \uc791\uc740 \uae00\uc528\uac00 \uc54c\ub824 \uc8fc\ub294 \ubc94\uc704\ub97c \ub118\uc5b4\uc124 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \ub300\uc2e0 \ubcf4\ub294 \uc21c\uc11c \ud558\ub098\ub97c \uae30\uc5b5\ud574 \ub450\uba74 \uc88b\uaca0\ub2e4. \ub69c\uaed1\uc758 \uaf43, \ubab8\uccb4\uc758 \uae00\uc790, \ubc14\ub2e5\uc758 \uae30\ub85d. \uc775\uc219\ud55c \uc8fc\uc804\uc790\ub3c4 \uc5b4\ub514\ub97c \ubcf4\ub290\ub0d0\uc5d0 \ub530\ub77c \uc7a5\uc2dd\ud488\uc774 \ub418\uc5c8\ub2e4\uac00 \uae30\ub85d\ubb3c\uc774 \ub41c\ub2e4. \ub2e4\uc74c\uc5d0 \uc61b \uadf8\ub987\uc744 \ub9cc\ub0a0 \ub54c \ubc14\ub2e5 \uc0ac\uc9c4\uc744 \ud55c \ubc88 \ub354 \ub20c\ub7ec \ubcf4\uace0 \uc2f6\uc5b4\uc9c0\ub294 \uc774\uc720\ub2e4."}, {"id": "socrates-life-and-questions", "title": "\uc18c\ud06c\ub77c\ud14c\uc2a4\uc758 \uc0dd\uc560 \u2014 \uc9c8\ubb38\uc744 \uba48\ucd94\uc9c0 \uc54a\uc740 \uc0ac\ub78c", "summary": "\uc9c1\uc811 \ub0a8\uae34 \uc800\uc220 \uc5c6\uc774\ub3c4 \uc624\ub798 \uae30\uc5b5\ub418\ub294 \ucca0\ud559\uc790\ub97c \uc9c8\ubb38\uacfc \uc7ac\ud310\uc758 \uc7a5\uba74\uc5d0\uc11c \ub9cc\ub098 \ubd05\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Philosophy", "url": "stories/socrates-life-and-questions/index.html", "image": "media/socrates-life-and-questions.jpg", "alt": "\uc790\ud06c \ub8e8\uc774 \ub2e4\ube44\ub4dc, \uc18c\ud06c\ub77c\ud14c\uc2a4\uc758 \uc8fd\uc74c(1787) \u00b7 Metropolitan Museum of Art / Wikimedia Commons, CC0 1.0; OpenStax \uc218\ub85d\ubcf8", "text": "\uc18c\ud06c\ub77c\ud14c\uc2a4\uc758 \uc0dd\uc560 \u2014 \uc9c8\ubb38\uc744 \uba48\ucd94\uc9c0 \uc54a\uc740 \uc0ac\ub78c \uc544\ud14c\ub124\uc758 \ub300\ud654\uc5d0\uc11c \ubc95\uc815\uc758 \ubcc0\ub860\uae4c\uc9c0 \uc9c1\uc811 \ub0a8\uae34 \uc800\uc220 \uc5c6\uc774\ub3c4 \uc624\ub798 \uae30\uc5b5\ub418\ub294 \ucca0\ud559\uc790\ub97c \uc9c8\ubb38\uacfc \uc7ac\ud310\uc758 \uc7a5\uba74\uc5d0\uc11c \ub9cc\ub098 \ubd05\ub2c8\ub2e4. Philosophy \ubb38\ud654 \ub204\uad70\uac00\uc5d0\uac8c \u2018\uc88b\uc740 \uc0ac\ub78c\uc740 \uc5b4\ub5a4 \uc0ac\ub78c\uc778\uac00\uc694?\u2019\ub77c\ub294 \uc9c8\ubb38\uc744 \ubc1b\uc558\ub2e4\uace0 \ud574 \ubcf4\uc790. \uce5c\uc808\ud55c \uc0ac\ub78c\uc774\ub77c\uace0 \ub2f5\ud558\uba74 \uace7 \ub2e4\uc74c \uc9c8\ubb38\uc774 \uc628\ub2e4. \uc0c1\ub300\ub97c \uc704\ud574 \uac70\uc9d3\ub9d0\ud558\ub294 \uac83\ub3c4 \uce5c\uc808\ud55c\uac00, \ub098\uc05c \uc77c\uc744 \ub3c4\uc640\uc8fc\ub294 \uce5c\uc808\uc740 \uc5b4\ub5a4\uac00. \uc775\uc219\ud55c \ub9d0 \ud558\ub098\uac00 \uac11\uc790\uae30 \ub0af\uc124\uc5b4\uc9c4\ub2e4. \uae30\uc6d0\uc804 5\uc138\uae30 \uc544\ud14c\ub124\uc5d0\uc11c \ud65c\ub3d9\ud55c \uc18c\ud06c\ub77c\ud14c\uc2a4\ub294 \uc774\ub7f0 \uc2dd\uc73c\ub85c \uc0ac\ub78c\ub4e4\uc774 \uc548\ub2e4\uace0 \uc0dd\uac01\ud55c \uac83\uc758 \uadfc\uac70\ub97c \ub2e4\uc2dc \uc0b4\ud53c\uac8c \ud558\ub294 \uc778\ubb3c\ub85c \uc804\ud574\uc9c4\ub2e4. \uc704\uc758 \ubb38\ub2f5\uc740 \uadf8\uc758 \uc2e4\uc81c \ubc1c\uc5b8\uc744 \uc778\uc6a9\ud55c \uac83\uc774 \uc544\ub2c8\ub77c \uc9c8\ubb38\uc758 \ubc29\uc2dd\uc744 \uc124\uba85\ud558\uae30 \uc704\ud574 \ub9cc\ub4e0 \uc608\ub2e4. \ucca0\ud559\uc790\uc758 \uc0dd\uc560\ub3c4 \uba85\uc5b8\uc744 \uba87 \uac1c \uc678\uc6b0\ub294 \uac83\ubcf4\ub2e4 \uadf8\uac00 \ub204\uad6c\uc5d0\uac8c \ubb34\uc5c7\uc744 \ubb3c\uc5c8\uace0 \uc65c \uac08\ub4f1\uc744 \uacaa\uc5c8\ub294\uc9c0 \ub530\ub77c\uac00\uba74 \uac00\uae4c\uc6cc\uc9c4\ub2e4. \uc18c\ud06c\ub77c\ud14c\uc2a4\ub294 \ucca0\ud559 \uc800\uc220\uc744 \ub0a8\uae30\uc9c0 \uc54a\uc558\ub2e4. \uc6b0\ub9ac\ub294 \uc8fc\ub85c \ud50c\ub77c\ud1a4\uc744 \ube44\ub86f\ud55c \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uc758 \uae00\uc744 \ud1b5\ud574 \uadf8\ub97c \ub9cc\ub09c\ub2e4. \ub530\ub77c\uc11c \uc804\ud574\uc9c0\ub294 \ubaa8\ub4e0 \ubb38\uc7a5\uc744 \uadf8\uac00 \uc2e4\uc81c\ub85c \uadf8 \uc790\ub9ac\uc5d0\uc11c \ud55c \ub9d0\uacfc \ub611\uac19\ub2e4\uace0 \uc77d\uc744 \uc218\ub294 \uc5c6\ub2e4. \uc5ed\uc0ac \uc18d \uc778\ubb3c\uacfc \uc791\uac00\uac00 \uadf8\ub9b0 \uc778\ubb3c\uc744 \uad6c\ubcc4\ud558\ub294 \uc8fc\uc758\uac00 \ud544\uc694\ud558\ub2e4. \uc774\ub294 \uc18c\ud06c\ub77c\ud14c\uc2a4\ub97c \uc54c \uc218 \uc5c6\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \uc885\ub958\uc758 \uc790\ub8cc\ub85c \uadf8\ub97c \ub9cc\ub098\ub294\uc9c0 \uc54c\uace0 \uc77d\uc790\ub294 \ub73b\uc774\ub2e4. \ud50c\ub77c\ud1a4\uc758 \ub300\ud654\ud3b8\uc5d0\uc11c\ub294 \uc18c\ud06c\ub77c\ud14c\uc2a4\uac00 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ubb3b\uace0 \uc0c1\ub300\uc758 \ub300\ub2f5\uc744 \uac80\ud1a0\ud55c\ub2e4. \ud55c \ucca0\ud559\uc790\uc758 \uc8fc\uc7a5\uc744 \ud56d\ubaa9\ubcc4\ub85c \uc815\ub9ac\ud55c \uad50\uacfc\uc11c\uc640 \ub2ec\ub9ac, \uc0dd\uac01\uc774 \ub9c9\ud788\uace0 \ubc14\ub00c\ub294 \uacfc\uc815\uae4c\uc9c0 \ubb38\ud559\uc801 \ud615\uc2dd\uc73c\ub85c \ubcf4\uc5ec \uc900\ub2e4. \uc544\ud14c\ub124\uc5d0\uc11c\ub294 \uc2dc\ubbfc\ub4e4\uc774 \uc815\uce58\uc640 \uc7ac\ud310\uc5d0 \ucc38\uc5ec\ud588\uace0 \uacf5\uac1c\uc801\uc73c\ub85c \ub9d0\ud558\ub294 \ub2a5\ub825\uc774 \uc911\uc694\ud588\ub2e4. \ubb3c\ub860 \uc624\ub298\ub0a0\uc758 \ubcf4\ud1b5\uc120\uac70 \uc0ac\ud68c\uc640 \uac19\uc9c0\ub294 \uc54a\uc73c\uba70 \uc5ec\uc131\uacfc \ub178\uc608 \ub4f1 \ub9ce\uc740 \uc0ac\ub78c\uc774 \uc2dc\ubbfc \uc815\uce58\uc5d0\uc11c \ubc30\uc81c\ub418\uc5c8\ub2e4. \uc774\ub7f0 \ub3c4\uc2dc\uc5d0\uc11c \uc9c0\ud61c\uc640 \ub355\uc744 \uc548\ub2e4\uace0 \ub9d0\ud558\ub294 \uc0ac\ub78c\uc5d0\uac8c \uacc4\uc18d \uc9c8\ubb38\ud558\ub294 \uc77c\uc740 \ub2e8\uc21c\ud55c \ub9d0\ub180\uc774\uc5d0 \uba38\ubb3c\uc9c0 \uc54a\ub294\ub2e4. \ud6cc\ub96d\ud55c \uc2dc\ubbfc, \uc815\uc758, \uacbd\uac74\ud568\uc774 \ubb34\uc5c7\uc778\uc9c0 \ubb3b\ub294 \uc21c\uac04 \uc0ac\ub78c\ub4e4\uc774 \uc758\uc9c0\ud558\ub294 \ud310\ub2e8\uc758 \uae30\uc900\uc774 \ud754\ub4e4\ub9b4 \uc218 \uc788\ub2e4. \ub9ce\uc740 \uc0ac\ub78c \uc55e\uc5d0\uc11c \uc124\uba85\uc774 \ub9c9\ud788\ub294 \uacbd\ud5d8\uc740 \ubd88\ud3b8\ud558\ub2e4. \uc18c\ud06c\ub77c\ud14c\uc2a4\uc758 \uc9c8\ubb38\uc740 \ubc30\uc6c0\uc758 \uacc4\uae30\uac00 \ub420 \uc218 \uc788\uc5c8\uc9c0\ub9cc \ubc18\uac10\uacfc \uc758\uc2ec\ub3c4 \ubd88\ub7ec\uc62c \uc218 \uc788\ub294 \ud65c\ub3d9\uc774\uc5c8\ub2e4. \ud50c\ub77c\ud1a4\uc758 \u300e\uc18c\ud06c\ub77c\ud14c\uc2a4\uc758 \ubcc0\uba85\u300f\uc5d0\uc11c \uc18c\ud06c\ub77c\ud14c\uc2a4\ub294 \ub378\ud3ec\uc774\uc758 \uc2e0\ud0c1\uc5d0 \uad00\ud55c \uc774\uc57c\uae30\ub97c \ub4e4\ub824\uc900\ub2e4. \uce5c\uad6c \uce74\uc774\ub808\ud3f0\uc774 \uc790\uc2e0\ubcf4\ub2e4 \uc9c0\ud61c\ub85c\uc6b4 \uc0ac\ub78c\uc774 \uc788\ub294\uc9c0 \ubb3c\uc5c8\uace0 \uc5c6\ub2e4\ub294 \ub2f5\uc744 \ubc1b\uc558\ub2e4\uace0 \ud55c\ub2e4. \uc18c\ud06c\ub77c\ud14c\uc2a4\ub294 \uc790\uc2e0\uc774 \ub300\ub2e8\ud55c \uc9c0\uc2dd\uc744 \uac00\uc84c\ub2e4\uace0 \uc0dd\uac01\ud558\uc9c0 \uc54a\uc558\uae30\uc5d0 \uadf8 \ub73b\uc744 \uc54c\uc544\ubcf4\ub824 \ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uadf8\ub294 \uc815\uce58\uac00\uc640 \uc2dc\uc778, \uc7a5\uc778\ub4e4\uc744 \ucc3e\uc544\uac00 \ubb3b\ub294\ub2e4. \uadf8\uc911\uc5d0\ub294 \uc2e4\uc81c\ub85c \ub6f0\uc5b4\ub09c \uc19c\uc528\ub97c \uac00\uc9c4 \uc0ac\ub78c\ub3c4 \uc788\uc9c0\ub9cc, \uc790\uae30 \ubd84\uc57c\uc758 \ub2a5\ub825\uc744 \uc774\uc720\ub85c \ub2e4\ub978 \uc911\uc694\ud55c \uc77c\uae4c\uc9c0 \ubaa8\ub450 \uc548\ub2e4\uace0 \uc0dd\uac01\ud558\ub294 \uacbd\uc6b0\uac00 \ub4dc\ub7ec\ub09c\ub2e4. \ud55c \uac00\uc9c0\ub97c \uc798\ud55c\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ubaa8\ub4e0 \ud310\ub2e8\uc5d0 \uad8c\uc704\ub97c \uac00\uc9c4\ub2e4\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4\ub294 \ubb38\uc81c\ub2e4. \uc774 \uc774\uc57c\uae30\uc5d0\uc11c \uc911\uc694\ud55c \uac83\uc740 \uc790\uc2e0\uc774 \ubaa8\ub974\ub294 \uac83\uc744 \uc548\ub2e4\uace0 \uc5ec\uae30\uc9c0 \uc54a\uc73c\ub824\ub294 \ud0dc\ub3c4\ub2e4. \uadf8\ub798\uc11c \uc18c\ud06c\ub77c\ud14c\uc2a4\uc758 \ubb34\uc9c0\ub294 \uc544\ubb34\uac83\ub3c4 \ubc30\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \ub41c\ub2e4\ub294 \uba74\ud5c8\uac00 \uc544\ub2c8\ub2e4. \uc790\uc2e0\uc774 \uac00\uc9c4 \ub300\ub2f5\uc774 \uc5b4\ub514\uae4c\uc9c0 \uc720\ud6a8\ud55c\uc9c0 \uc0b4\ud53c\ub294 \ucd9c\ubc1c\uc810\uc5d0 \uac00\uae5d\ub2e4. \uc6a9\uae30\ub97c \ub450\ub824\uc6c0 \uc5c6\ub294 \ud589\ub3d9\uc774\ub77c\uace0 \uc815\uc758\ud574 \ubcf4\uc790. \uadf8\ub807\ub2e4\uba74 \uc704\ud5d8\uc744 \ubab0\ub77c \ubb34\ubaa8\ud558\uac8c \ub6f0\uc5b4\ub4e0 \uc0ac\ub78c\ub3c4 \uc6a9\uac10\ud55c\uac00. \ucc98\uc74c \ub2f5\uc774 \ubd80\uc871\ud558\ub2e4\ub294 \uac83\uc744 \uc54c\uba74 \uc704\ud5d8\uc744 \uc774\ud574\ud558\ub294 \ub2a5\ub825\uacfc \ud589\ub3d9\uc758 \uc774\uc720\ub97c \ub354 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \uc774\uac83 \uc5ed\uc2dc \uc2e4\uc81c \ub300\ud654\ud3b8\uc758 \uc778\uc6a9\uc774 \uc544\ub2c8\ub77c \ubc29\ubc95\uc744 \ud480\uc5b4 \uc4f4 \uc608\ub2e4. \uc9c8\ubb38\uc740 \ub2f5\uc744 \uc5c6\uc560\uae30\ubcf4\ub2e4 \ub2f5\uc744 \ub354 \uc815\uad50\ud558\uac8c \ub9cc\ub4e4 \uc218 \uc788\ub2e4. \uc18c\ud06c\ub77c\ud14c\uc2a4\ub294 \uae30\uc6d0\uc804 399\ub144 \ubd88\uacbd\uacfc \uc80a\uc740\uc774\ub4e4\uc744 \ud0c0\ub77d\uc2dc\ud0a8\ub2e4\ub294 \ud610\uc758\ub85c \uc7ac\ud310\uc744 \ubc1b\ub294\ub2e4. \uc80a\uc740 \uc0ac\ub78c\ub4e4\uc774 \uadf8\ub97c \ub530\ub77c \uc9c8\ubb38\ud558\ub294 \ud65c\ub3d9\uc744 \ud749\ub0b4 \ub0b4\uace0, \uadf8 \ub54c\ubb38\uc5d0 \uc6d0\ub9dd\uc774 \uc0dd\uacbc\ub2e4\ub294 \uc124\uba85\ub3c4 \u300e\ubcc0\uba85\u300f\uc5d0 \ub098\uc628\ub2e4. \uadf8\ub7ec\ub098 \uace0\ub300 \uc7ac\ud310\uc744 \uc624\ub298\uc758 \ud45c\ud604\uc758 \uc790\uc720 \uc0ac\uac74 \ud558\ub098\ub85c\ub9cc \ub2e8\uc21c\ud654\ud558\uba74 \ub2f9\uc2dc\uc758 \uc885\uad50\uc640 \uc2dc\ubbfc \uacf5\ub3d9\uccb4\uc758 \uad00\uacc4\ub97c \ub193\uce58\uac8c \ub41c\ub2e4. \u300e\ubcc0\uba85\u300f\uc758 \uc81c\ubaa9\ub3c4 \uc774\ud574\ud574 \ub450\uba74 \uc88b\ub2e4. \uc5ec\uae30\uc11c \ubcc0\uba85\uc740 \uc798\ubabb\uc744 \ud53c\ud558\ub824\uace0 \ud551\uacc4\ub97c \ub298\uc5b4\ub193\ub294\ub2e4\ub294 \uc77c\uc0c1\uc801 \ub73b\ubcf4\ub2e4 \ubc95\uc815\uc758 \uc790\uae30 \ubcc0\ub860\uc744 \uac00\ub9ac\ud0a8\ub2e4. \uc18c\ud06c\ub77c\ud14c\uc2a4\ub294 \ubc95\uc815\uc5d0\uc11c \uc790\uc2e0\uc774 \uc5b4\ub5a4 \uc77c\uc744 \ud574 \uc654\uc73c\uba70 \uc65c \uadf8 \ud65c\ub3d9\uc5d0 \uac00\uce58\uac00 \uc788\ub2e4\uace0 \ubcf4\ub294\uc9c0 \uc124\uba85\ud55c\ub2e4. \ud50c\ub77c\ud1a4\uc758 \uc791\ud488\uc744 \uc7ac\ud310\uc758 \ub179\uc74c\uc774\ub098 \uc18d\uae30\ub85d\ucc98\ub7fc \ucde8\uae09\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc791\ud488 \uc18d \uc18c\ud06c\ub77c\ud14c\uc2a4\ub294 \uccad\uc911\uc758 \ub3d9\uc815\uc2ec\uc744 \uc790\uadf9\ud558\ub294 \uac83\ub9cc\uc73c\ub85c \uc790\uc2e0\uc744 \uc0b4\ub9ac\ub824 \ud558\uc9c0 \uc54a\ub294\ub2e4. \uc0ac\ub78c\ub4e4\uc5d0\uac8c \uc7ac\uc0b0\uacfc \ud3c9\ud310 \ubabb\uc9c0\uc54a\uac8c \uc790\uc2e0\uc758 \uc0b6\uacfc \ub9c8\uc74c\uc744 \ub3cc\ubcf4\ub77c\uace0 \uc694\uad6c\ud574 \uc654\ub2e4\uace0 \uc8fc\uc7a5\ud55c\ub2e4. \ubaa9\uc228\uc744 \uad6c\ud558\uae30 \uc704\ud574 \uadf8 \ud65c\ub3d9\uc744 \ubc84\ub9ac\ub294 \uac83\uc774 \uacfc\uc5f0 \uc633\uc740\uc9c0\ub3c4 \ubb3b\ub294\ub2e4. \uc774 \ud0dc\ub3c4\ub294 \ud6cc\ub96d\ud558\uac8c \ubcf4\uc77c \uc218 \uc788\uc9c0\ub9cc \ub2f9\uc2dc \ubc30\uc2ec\uc6d0 \ubaa8\ub450\uc5d0\uac8c \uc124\ub4dd\ub825 \uc788\uac8c \ub4e4\ub838\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uacb0\uad6d \uadf8\ub294 \uc720\uc8c4 \ud310\ub2e8\uacfc \uc0ac\ud615 \uc120\uace0\ub97c \ubc1b\ub294\ub2e4. \uc774\ub97c \u2018\ub611\ub611\ud55c \ud55c \uc0ac\ub78c\uacfc \uc5b4\ub9ac\uc11d\uc740 \ubaa8\ub4e0 \uc2dc\ubbfc\u2019\uc758 \uc2f8\uc6c0\uc73c\ub85c\ub9cc \uc77d\uae30\ubcf4\ub2e4, \uacf5\ub3d9\uccb4\uc758 \uc758\uc2ec \uc18d\uc5d0\uc11c\ub3c4 \uac1c\uc778\uc774 \uc9c0\ucf1c\uc57c \ud55c\ub2e4\uace0 \uc0dd\uac01\ud55c \uc6d0\uce59\uc774 \ubb34\uc5c7\uc774\uc5c8\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\ub294 \ud3b8\uc774 \uc791\ud488\uc744 \ub354 \uae4a\uac8c \uc77d\uac8c \ud55c\ub2e4. \ud50c\ub77c\ud1a4\uc758 \u300e\ud30c\uc774\ub3c8\u300f\uc740 \uac10\uc625\uc5d0\uc11c \ub9c8\uc9c0\ub9c9 \uc2dc\uac04\uc744 \ubcf4\ub0b4\ub294 \uc18c\ud06c\ub77c\ud14c\uc2a4\ub97c \ub300\ud654\uc758 \ud615\uc2dd\uc73c\ub85c \uc804\ud55c\ub2e4. \uc601\ud63c\uacfc \uc8fd\uc74c\uc5d0 \uad00\ud55c \ub17c\uc758 \ub05d\uc5d0 \ub3c5\uc57d\uc744 \ub9c8\uc2dc\ub294 \uc7a5\uba74\uc774 \ub098\uc628\ub2e4. \uc774 \uc5ed\uc2dc \ucca0\ud559\uc801 \ubaa9\uc801\uc744 \uac00\uc9c4 \uc791\ud488\uc774\ubbc0\ub85c \ub9c8\uc9c0\ub9c9 \ud558\ub8e8\ub97c \ube60\uc9d0\uc5c6\uc774 \uae30\ub85d\ud55c \ud604\uc7a5 \uc77c\uc9c0\uc640\ub294 \ub2e4\ub974\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc790\ud06c \ub8e8\uc774 \ub2e4\ube44\ub4dc\uc758 \u3008\uc18c\ud06c\ub77c\ud14c\uc2a4\uc758 \uc8fd\uc74c\u3009\uc740 1787\ub144\uc5d0 \uadf8\ub9b0 \ud6c4\ub300\uc758 \ud68c\ud654\ub2e4. \uace7\uac8c \uc549\uc740 \uc911\uc2ec \uc778\ubb3c\uacfc \uc8fc\ubcc0 \uc0ac\ub78c\ub4e4\uc758 \ubab8\uc9d3\uc744 \ube44\uad50\ud558\uba74, \ud654\uac00\uac00 \ucca0\ud559\uc790\uc758 \ub9c8\uc9c0\ub9c9\uc744 \uc5b4\ub5a4 \ud0dc\ub3c4\ub85c \ubcf4\uc774\uac8c \ud588\ub294\uc9c0 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uace0\ub300\uc778\uc758 \uc2e4\uc81c \uc5bc\uad74\uacfc \ud604\uc7a5\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc0ac\uc9c4 \uc790\ub8cc\ub85c \uc77d\uc9c0\ub294 \ub9d0\uc790. \uc18c\ud06c\ub77c\ud14c\uc2a4\uac00 \uc9c8\ubb38\ud588\ub2e4\ub294 \uc0ac\uc2e4\ub9cc \ubc30\uc6b0\uace0 \ub0a8\uc744 \ubab0\uc544\ubd99\uc774\ub294 \uae30\uc220\ub85c \uc4f0\uba74 \uc911\uc694\ud55c \ubd80\ubd84\uc744 \ub193\uce60 \uc218 \uc788\ub2e4. \uc790\uc2e0\uc758 \ub2f5 \uc5ed\uc2dc \uac80\ud1a0 \ub300\uc0c1\uc774\ub77c\ub294 \uc810\uc744 \ud568\uaed8 \uae30\uc5b5\ud574\uc57c \ud55c\ub2e4. \uc0c1\ub300\uc758 \ube48\ud2c8\uc744 \ucc3e\ub294 \uac83\uacfc \ub354 \ub098\uc740 \ud310\ub2e8\uc5d0 \ud568\uaed8 \uc774\ub974\ub294 \uac83\uc740 \uac19\uc9c0 \uc54a\ub2e4. \uc624\ub298 \uc790\uc2e0\uc774 \uc790\uc8fc \uc4f0\ub294 \ub9d0 \ud558\ub098\ub97c \uace8\ub77c \ubcf4\uc790. \uc131\uacf5, \ud589\ubcf5, \uc815\uc758 \uac19\uc740 \ub9d0\ub3c4 \uc88b\uace0 \uc88b\uc740 \uce5c\uad6c\ub77c\ub294 \ub9d0\ub3c4 \uc88b\ub2e4. \ub73b\uc744 \ud55c \ubb38\uc7a5\uc73c\ub85c \uc801\uace0 \uadf8 \uc815\uc758\uac00 \ub9de\uc9c0 \uc54a\ub294 \uacbd\uc6b0\ub97c \ud558\ub098 \ub5a0\uc62c\ub824 \ubcf4\uba74 \ub41c\ub2e4. \uace0\ub300 \ucca0\ud559\uc790\uc758 \uc0b6\uc740 \uadf8\ub807\uac8c \uc791\uc740 \uc9c8\ubb38\uc73c\ub85c \uc624\ub298\uc758 \uc0b6\uc5d0 \uc774\uc5b4\uc9c8 \uc218 \uc788\ub2e4. \uadf8\uc758 \uc8fd\uc74c\ub9cc \uae30\uc5b5\ud558\ub294 \uac83\uc5d0\uc11c, \uc0b4\uc544 \uc788\ub294 \ub3d9\uc548 \uacc4\uc18d\ud588\ub358 \uac80\ud1a0\ub97c \uc870\uae08 \ud574 \ubcf4\ub294 \ucabd\uc73c\ub85c \ub098\uc544\uac00\ub294 \uac83\uc774\ub2e4."}, {"id": "stone-chime-thickness", "title": "\uc774 \ub3cc\uc740 \ub450\ub4dc\ub9ac\uba74 \uc74c\uc774 \ub41c\ub2e4", "summary": "\uaebe\uc778 \ub3cc \ud55c \uc7a5\uc774 \uc545\uae30\uac00 \ub418\ub294 \ubc29\ubc95\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Music", "url": "stories/stone-chime-thickness/index.html", "image": "media/stone-chime-thickness.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \ud3b8\uacbd \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc774 \ub3cc\uc740 \ub450\ub4dc\ub9ac\uba74 \uc74c\uc774 \ub41c\ub2e4 \ud3b8\uacbd \ud55c \uc870\uac01\uc5d0\uc11c \uc2dc\uc791\ud558\ub294 \uc74c\uc545 \uc774\uc57c\uae30 \uaebe\uc778 \ub3cc \ud55c \uc7a5\uc774 \uc545\uae30\uac00 \ub418\ub294 \ubc29\ubc95\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Music \ubb38\ud654 \uc0ac\uc9c4 \uc18d \ub3cc\uc740 \ud55c\ucabd\uc774 \uaebe\uc5ec \uc788\ub2e4. \ub05d\ubd80\ubd84\uc5d0 \uad6c\uba4d\ub3c4 \ud558\ub098 \ubcf4\uc778\ub2e4. \ub530\ub85c \ub193\uc73c\uba74 \ubb34\uc5c7\uc744 \ub9cc\ub4e4\ub2e4 \ub0a8\uae34 \uc870\uac01\ucc98\ub7fc \ubcf4\uc77c \uc218 \uc788\uc9c0\ub9cc, \uc774\uac83\uc740 \uc18c\ub9ac\ub97c \ub0b4\ub294 \uc545\uae30\uc758 \ud55c \ubd80\ubd84\uc774\ub2e4. \uc774\ub984\uc740 \ud3b8\uacbd\uc774\ub2e4. \ud53c\uc544\ub178\uc758 \uac74\ubc18\uc774\ub098 \ubc14\uc774\uc62c\ub9b0\uc758 \uc904\ucc98\ub7fc \uc774 \uc545\uae30\uc5d0\uc11c\ub294 \ub3cc\uc774 \uc74c\uc744 \ub9e1\ub294\ub2e4. \ubb34\ub300 \uc704 \uc545\uae30\ub97c \ub5a0\uc62c\ub9ac\ub2e4\uac00 \uac11\uc790\uae30 \ub3cc\uc744 \ub9cc\ub098\ub2c8 \uc74c\uc545\uc758 \uc7ac\ub8cc\uac00 \uc0dd\uac01\ubcf4\ub2e4 \ub113\uac8c \ub290\uaef4\uc9c4\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc740 \uc625\uc11d\uc744 \uae4e\uc544 \ub9cc\ub4e0 \uacbd \uc5f4\uc5ec\uc12f \uac1c\ub97c \ub450 \ub2e8\uc758 \ud2c0\uc5d0 \uc5ec\ub35f \uac1c\uc529 \ub9e4\ub2ec\uc544 \uc5f0\uc8fc\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc0ac\uc9c4\uc758 \ud55c \uc870\uac01\uc744 \ubcf4\ub294 \uac83\uacfc \uc804\uccb4 \uc545\uae30\ub97c \uc0c1\uc0c1\ud558\ub294 \uc77c \uc0ac\uc774\uc5d0 \uc791\uc740 \uac04\uaca9\uc774 \uc788\ub2e4. \uad6c\uba4d\uc740 \uadf8 \uc870\uac01\uc774 \ud63c\uc790 \ub193\uc774\ub294 \ubb3c\uac74\uc774 \uc544\ub2c8\ub77c \ub9e4\ub2ec\ub9ac\ub294 \ubb3c\uac74\uc774\ub77c\ub294 \uc0ac\uc2e4\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \uc774\ub984 \ubaa8\ub97c \ub3cc\uc774 \uc904\uc9c0\uc5b4 \uc18c\ub9ac\ub97c \ub0b4\ub294 \uc545\uae30\uc758 \ud55c \uc790\ub9ac\ub85c \uc62e\uaca8 \uac00\ub294 \uc21c\uac04\uc774\ub2e4. \uc774 \uc545\uae30\uc5d0\uc11c \uc7ac\ubbf8\uc788\ub294 \ubd80\ubd84\uc740 \uc74c\ub192\uc774\ub97c \ub3cc\uc758 \ub450\uaed8\ub85c \uc870\uc808\ud588\ub2e4\ub294 \uc810\uc774\ub2e4. \uc904\uc744 \ud33d\ud33d\ud558\uac8c \ub2f9\uae30\uac70\ub098 \uad00\uc758 \uad6c\uba4d\uc744 \ub9c9\ub294 \ubc29\uc2dd\uacfc\ub294 \ub2e4\ub974\ub2e4. \uae4e\uc544 \ub9cc\ub4e0 \ub3cc\uc758 \ub450\uaed8\uac00 \uc74c\uc545\uc744 \uc900\ube44\ud558\ub294 \uc77c\uc774 \ub418\ub294 \uac83\uc774\ub2e4. \uc5f0\uc8fc\ud560 \ub54c\ub294 \uc18c\ubfd4\ub85c \ub9cc\ub4e0 \ub3c4\uad6c\uc778 \uac01\ud1f4\ub85c \uacbd\uc758 \uc544\ub7ab\ubd80\ubd84\uc744 \ucce4\ub2e4\uace0 \ud55c\ub2e4. \ub3cc\uc774\ub77c\uace0 \uc544\ubb34 \ub9c9\ub300\ub098 \uac00\uc838\uc640 \ub450\ub4dc\ub9ac\ub294 \ubc29\uc2dd\uc740 \uc544\ub2c8\ub2e4. \uc18c\ub9ac\ub97c \ub0bc \ubb3c\uac74\uacfc \uadf8\uac83\uc744 \uce58\ub294 \ub3c4\uad6c\uac00 \ud568\uaed8 \uac16\ucd94\uc5b4\uc9c4\ub2e4. \uc0ac\uc9c4 \uc18d \uacbd \ud558\ub098\ub9cc \ubcf4\uba74 \ubaa8\uc591\uc774 \ub3c5\ud2b9\ud55c \ub3cc \uc870\uac01\uc73c\ub85c \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc804\uccb4 \ud3b8\uacbd\uc5d0\uc11c\ub294 \uc5ec\ub7ec \uc74c\uc744 \ub9e1\ub294 \uacbd\ub4e4\uc774 \ud2c0\uc5d0 \ub098\ub780\ud788 \uac78\ub9b0\ub2e4. \uac01\uac01\uc758 \ubb3c\uac74\uacfc \uadf8 \ubb3c\uac74\ub4e4\uc774 \uc774\ub8e8\ub294 \ubc30\uc5f4\uc744 \ud568\uaed8 \uc0dd\uac01\ud574\uc57c \uc4f0\uc784\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \uac19\uc740 \uc885\ub958\uc758 \uc7ac\ub8cc\uac00 \uc5ec\ub7ec \ub192\uc774\uc758 \uc18c\ub9ac\ub97c \ub0b4\ub3c4\ub85d \uc900\ube44\ub41c \uccb4\uacc4\uc600\ub2e4. \uc5f4\uc5ec\uc12f \uacbd\uc744 \ub450 \ub2e8\uc5d0 \uc5ec\ub35f \uac1c\uc529 \uac74\ub2e4\ub294 \uc124\uba85\uc740 \ub2e8\uc21c\ud55c \uac1c\uc218 \uc815\ubcf4 \uc774\uc0c1\uc774\ub2e4. \uc5f0\uc8fc\uc790\uac00 \uc18c\ub9ac\ub97c \uc120\ud0dd\ud560 \uc218 \uc788\ub294 \uc790\ub9ac\uac00 \ub9c8\ub828\ub418\uc5b4 \uc788\ub2e4\ub294 \ub73b\uc774\ub2e4. \ub2e4\ub9cc \uc774 \uc0ac\uc9c4\uc5d0\uc11c \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc804\uccb4 \ud2c0\uc758 \uc815\ud655\ud55c \uce58\uc218\ub97c \uc0c8\ub85c \ubcf5\uc6d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ud55c \uc810\uc758 \uc18c\uc7a5\ud488\uacfc \uc545\uae30 \uc804\uccb4\uc758 \uad6c\uc131\uc744 \uae30\uad00 \uc124\uba85\uc744 \ud1b5\ud574 \uc5f0\uacb0\ud574 \uc77d\ub294 \uac83\uc774 \ucd9c\ubc1c\uc810\uc774\ub2e4. \ud3b8\uacbd\uc5d0\uc11c\ub294 \ub3cc\uc758 \ub450\uaed8\ub97c \uc870\uc808\ud574 \uc74c\ub192\uc774\ub97c \ub2e4\ub8e8\uc5c8\ub2e4\uace0 \uc790\ub8cc\ub294 \uc124\uba85\ud55c\ub2e4. \uc904\uc758 \uc7a5\ub825\uc744 \ubc14\uafb8\ub294 \uc545\uae30\uc640\ub294 \ub2e4\ub978 \uc900\ube44\ub2e4. \uc644\uc131\ub41c \uc870\uac01\uc758 \ubaa8\uc591\uc744 \uac10\uc0c1\ud558\ub294 \uc77c \uc606\uc5d0, \uc18c\ub9ac\uc758 \uc870\uac74\uc744 \ub9de\ucd94\uae30 \uc704\ud574 \uc7ac\ub8cc\ub97c \ub2e4\ub4ec\ub294 \uc77c\uc744 \ub193\uc744 \uc218 \uc788\ub2e4. \uacf5\uc608\uc640 \uc74c\uc545\uc774 \ubd84\ub9ac\ub418\uc5b4 \uc788\uc9c0 \uc54a\uc740 \ub300\ubaa9\uc774\ub2e4. \uc774\ub54c \ub450\uaed8 \ud558\ub098\ub9cc \ubcf4\uace0 \uc0ac\uc9c4 \uc18d \uacbd\uc774 \uc815\ud655\ud788 \uc5b4\ub5a4 \uc74c\uc744 \ub0b4\ub294\uc9c0 \uc54c\uc544\ub0bc \uc218\ub294 \uc5c6\ub2e4. \uc2e4\uc81c \uce58\uc218\uc640 \uc0c1\ud0dc, \uc5f0\uc8fc \uc870\uac74\uc744 \ud655\uc778\ud574\uc57c \ud560 \ubb38\uc81c\ub2e4. \uc18c\uc7a5\ud488 \uc0ac\uc9c4\uc744 \ubcf8 \uac10\uc0c1\uacfc \uc74c\ud5a5 \uce21\uc815\uc740 \ub2e4\ub978 \uc791\uc5c5\uc774\ub2e4. \ub2e4\ub9cc \uc190\uc73c\ub85c \uc7ac\ub8cc\ub97c \uae4e\uace0 \ud655\uc778\ud558\ub294 \uacfc\uc815\uc774 \uc74c\uc545\uc758 \ucd9c\ubc1c\uc810\uc774\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub208\uc55e\uc758 \ub3cc\uc744 \ub2e4\ub974\uac8c \ubcf4\uac8c \ud55c\ub2e4. \uac01\ud1f4\ub294 \uc18c\ubfd4\ub85c \ub9cc\ub4e0 \ud0c0\uaca9 \ub3c4\uad6c\ub85c \uc18c\uac1c\ub41c\ub2e4. \uc5f0\uc8fc\uc5d0\uc11c\ub294 \ubb34\uc5c7\uc744 \uce58\ub294\uc9c0\ub9cc \uc544\ub2c8\ub77c \ubb34\uc5c7\uc73c\ub85c \uc5b4\ub290 \ubd80\ubd84\uc744 \uce58\ub294\uc9c0\ub3c4 \uc911\uc694\ud558\ub2e4. \uae30\uad00\uc740 \uacbd\uc758 \uc544\ub7ab\ubd80\ubd84\uc744 \ucce4\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc18c\ub9ac \ub098\ub294 \ubb3c\uac74\uc744 \uc544\ubb34 \ubc29\uc2dd\uc73c\ub85c\ub098 \ub450\ub4dc\ub9ac\ub294 \uac83\uacfc, \uc815\ud574\uc9c4 \ub3c4\uad6c\uc640 \ub3d9\uc791\uc73c\ub85c \uc5f0\uc8fc\ud558\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \uc624\ub298\uc758 \uad00\ub78c\uc790\ub294 \uc2e4\uc81c \uc720\ubb3c\uc744 \uc2dc\ud5d8 \uc0bc\uc544 \uccd0 \ubcfc \uc218 \uc5c6\ub2e4. \uc18c\ub9ac\ub97c \uc54c\uace0 \uc2f6\ub2e4\uba74 \uc801\uc808\ud55c \uc5f0\uc8fc \uc790\ub8cc\uc640 \ud574\uc124\uc744 \ucc3e\uc544\uc57c \ud55c\ub2e4. \ub300\uc2e0 \uad6c\uba4d\uacfc \ud615\ud0dc\ub97c \ubcf4\uba70 \ub9e4\ub2e4\ub294 \ubc29\uc2dd\uacfc \uc18c\ub9ac \ub0b4\ub294 \uc790\ub9ac\ub97c \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ubb3c\uac74\uc744 \uc190\uc0c1\uc2dc\ud0a4\uc9c0 \uc54a\uc73c\uba74\uc11c\ub3c4 \uc4f0\uc784\uc73c\ub85c \uc0c1\uc0c1\ud558\ub294 \uae38\uc774 \uc788\ub294 \uac83\uc774\ub2e4. \uc545\uae30\ub294 \ubcf4\uad00\ud560 \ub300\uc0c1\uc774\uba74\uc11c \uc6d0\ub798 \ud589\ub3d9\uc744 \uc704\ud574 \ub9cc\ub4e0 \ub3c4\uad6c\uc600\ub2e4. \ubc15\ubb3c\uad00\uc740 \ud3b8\uacbd\uc774 \uc870\uc120\uc2dc\ub300 \uc81c\ub840\uc640 \uc5f0\ub840\uc5d0 \uc0ac\uc6a9\ub418\uc5c8\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \uc18c\ub9ac\ub9cc\uc744 \ub530\ub85c \ub5bc\uc5b4 \ub4e3\ub294 \uacbd\ud5d8\uacfc \uc815\ud574\uc9c4 \uc790\ub9ac\uc5d0\uc11c \ub2e4\ub978 \uc545\uae30\uc640 \ud568\uaed8 \uc6b8\ub9ac\ub294 \uacbd\ud5d8\uc740 \ub2ec\ub790\uc744 \uac83\uc774\ub2e4. \uc74c\uc545\uc740 \uc74c\uc758 \ub192\uc774\ubfd0 \uc544\ub2c8\ub77c \uc5b8\uc81c \uc5b4\ub514\uc5d0\uc11c \ub204\uad6c\uc640 \ud568\uaed8 \ub0b4\ub294\uc9c0\uc758 \uc57d\uc18d\ub3c4 \uac00\uc9c4\ub2e4. \ub3cc\uc744 \ub2e4\ub4ec\uc740 \uae30\uc220\uc774 \uacf5\ub3d9\uc758 \ud589\uc0ac \uc548\uc73c\ub85c \ub4e4\uc5b4\uac00\ub294 \uc21c\uac04\uc774\ub2e4. \uc774 \ud55c \uc810\uc758 \uc774\ub825\ub9cc\uc73c\ub85c \ud2b9\uc815\ud55c \ub0a0\uc758 \uc5f0\uc8fc\ub97c \uc7ac\ud604\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uac1c\ubcc4 \uacbd\uc758 \ubcf4\uc874 \uc0c1\ud0dc\uc640 \ud3b8\uacbd\uc774\ub77c\ub294 \uc545\uae30\uc758 \uc77c\ubc18\uc801\uc778 \uc4f0\uc784\uc740 \uad6c\ubd84\ud574\uc11c \uc54c \uc218 \uc788\ub2e4. \uc774\ub984 \uc5c6\ub294 \ub3cc\ucc98\ub7fc \ubcf4\uc774\ub358 \ubb3c\uac74\uc774 \uc5ec\ub7ec \uc74c \uac00\uc6b4\ub370 \ud55c \uc790\ub9ac\ub97c \ub9e1\uc558\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uae30\uc5b5\ud574 \ubcf4\uc790. \uc870\uc6a9\ud55c \uc804\uc2dc\uc7a5\uc5d0\uc11c\ub3c4 \uadf8 \ubc30\uc5f4\uacfc \uc18c\ub9ac\uc758 \uac00\ub2a5\uc131\uc744 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \ubc15\ubb3c\uad00\uc740 \ud3b8\uacbd\uc774 \uc870\uc120\uc2dc\ub300\uc758 \uc5ec\ub7ec \uc81c\ub840\uc640 \uc5f0\ub840\uc5d0 \uc0ac\uc6a9\ub418\uc5c8\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \uc624\ub298 \uc0ac\uc9c4\uc5d0\uc11c \ubcf4\uc774\ub294 \uac83\uc740 \uc870\uc6a9\ud55c \ub3cc \ud55c \uc7a5\uc774\uc9c0\ub9cc, \uc6d0\ub798\ub294 \ub2e4\ub978 \uc545\uae30\uc640 \ud568\uaed8 \uc18c\ub9ac\ub97c \ub0b4\ub358 \uc790\ub9ac\uc758 \uc77c\ubd80\uc600\ub358 \uc148\uc774\ub2e4. \uc0ac\uc9c4\uc744 \ub2e4\uc2dc \ubcfc \ub54c \ubaa8\ub4e0 \uc74c\uc758 \uc774\ub984\uc744 \uc678\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uad6c\uba4d \ud558\ub098\uc640 \uaebe\uc778 \ubaa8\uc591, \ub450\uaed8\ub97c \ub5a0\uc62c\ub9ac\ub294 \uac83\uc73c\ub85c \ucda9\ubd84\ud558\ub2e4. \uc545\uae30\ub294 \uaf2d \uc904\uc774 \uc788\uac70\ub098 \uc18d\uc774 \ube48 \uad00\uc774\uc5b4\uc57c \ud55c\ub2e4\ub294 \uc0dd\uac01\ub3c4 \uc7a0\uc2dc \ub0b4\ub824\ub193\uc744 \uc218 \uc788\ub2e4. \ub3cc\uc5d0\ub3c4 \uc74c\uc545\uc744 \ub9e1\uae34 \uc0ac\ub78c\ub4e4\uc774 \uc788\uc5c8\ub2e4."}, {"id": "titian-man-with-glove", "title": "\uc7a5\uac11\uc744 \ub080 \ub0a8\uc790 \u2014 \uc5bc\uad74\ubcf4\ub2e4 \uc190\uc774 \uba3c\uc800 \uc54c\ub824 \uc8fc\ub294 \uac83", "summary": "\ubaa8\ub378\uc758 \uc774\ub984\uc744 \ub9de\ud788\ub294 \ub300\uc2e0 \uc5bc\uad74\u00b7\uc190\u00b7\uc7a5\uac11\uc774 \uc774\ub8e8\ub294 \uad00\uacc4\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Art", "url": "stories/titian-man-with-glove/index.html", "image": "media/titian-man-with-glove.jpg", "alt": "\ud2f0\uce58\uc544\ub178\uc758 \uc7a5\uac11\uc744 \ub080 \ub0a8\uc790. \uac80\uc740 \uc637\uacfc \ud770 \uc154\uce20\ub97c \uc785\uc740 \uc778\ubb3c\uc774 \uc606\uc744 \ubc14\ub77c\ubcf4\uace0 \ud55c \uc190\uc5d0\ub294 \uc7a5\uac11\uc744 \ub07c\uace0 \uc788\uc2b5\ub2c8\ub2e4.", "text": "\uc7a5\uac11\uc744 \ub080 \ub0a8\uc790 \u2014 \uc5bc\uad74\ubcf4\ub2e4 \uc190\uc774 \uba3c\uc800 \uc54c\ub824 \uc8fc\ub294 \uac83 \ud2f0\uce58\uc544\ub178\uc758 \ucd08\uc0c1\uc5d0\uc11c \uac80\uc740 \uc637\uacfc \uc791\uc740 \ubb3c\uac74 \uc77d\uae30 \ubaa8\ub378\uc758 \uc774\ub984\uc744 \ub9de\ud788\ub294 \ub300\uc2e0 \uc5bc\uad74\u00b7\uc190\u00b7\uc7a5\uac11\uc774 \uc774\ub8e8\ub294 \uad00\uacc4\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Art \ubb38\ud654 \ud55c \ub0a8\uc790\uac00 \uac80\uc740 \uc637\uc744 \uc785\uace0 \uc11c \uc788\ub2e4. \ud770 \uc154\uce20\uc640 \ubaa9\uae43, \uc5bc\uad74\uacfc \uc190\uc774 \uc5b4\ub450\uc6b4 \ud654\uba74\uc5d0\uc11c \uba3c\uc800 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uadf8\uac00 \ubb34\uc5c7\uc744 \ud588\uace0 \uc5b4\ub5a4 \uc774\ub984\uc744 \uac00\uc84c\ub294\uc9c0 \ubab0\ub77c\ub3c4 \uc5b4\ub5a4 \ud0dc\ub3c4\ub85c \uc6b0\ub9ac \uc55e\uc5d0 \ub193\uc600\ub294\uc9c0\ub294 \ub290\ub084 \uc218 \uc788\ub2e4. \ud2f0\uce58\uc544\ub178\uc758 \u3008\uc7a5\uac11\uc744 \ub080 \ub0a8\uc790\u3009\ub2e4. \ucd08\uc0c1\ud654\ub97c \ubcf4\uba74 \ubaa8\ub378\uc758 \uc2e0\uc6d0\uc744 \uba3c\uc800 \uc54c\uace0 \uc2f6\uc5b4\uc9c4\ub2e4. \ud558\uc9c0\ub9cc \uc774 \uc791\ud488\uc5d0\uc11c\ub294 \uc81c\ubaa9\uc774 \uac00\ub9ac\ud0a4\ub294 \uc791\uc740 \ubb3c\uac74\uc744 \ub530\ub77c\uac00 \ubcf4\ub294 \uac83\ub3c4 \uc88b\uc740 \uc2dc\uc791\uc774\ub2e4. \uc5bc\uad74\uc744 \ubcf4\uace0 \uc190\uc73c\ub85c \ub0b4\ub824\uc624\uba74, \uc778\ubb3c\uc758 \uc874\uc7ac\uac10\uc774 \ud55c \ubd80\ubd84\ub9cc\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc9c4 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\uc774 \ubcf4\uc778\ub2e4. \uc778\ubb3c\uc758 \uc637\uc740 \ub113\uace0 \uc5b4\ub450\uc6b4 \uba74\uc744 \uc774\ub8ec\ub2e4. \uba40\ub9ac\uc11c \ubcf4\uba74 \uc0c9\uc774 \ub2e8\uc870\ub86d\ub2e4\uace0 \ub290\ub084 \uc218 \uc788\uc9c0\ub9cc, \uadf8 \uc5b4\ub450\uc6c0 \ub54c\ubb38\uc5d0 \uc5bc\uad74\uacfc \ud770 \uc637\uae43, \ub450 \uc190\uc758 \ucc28\uc774\uac00 \ub354 \ub610\ub837\ud574\uc9c4\ub2e4. \ubaa8\ub4e0 \ubd80\ubd84\uc774 \uac19\uc740 \uc815\ub3c4\ub85c \uc2dc\uc120\uc744 \ub04c\uc9c0 \uc54a\ub294 \uad6c\uc131\uc774 \uc778\ubb3c\uc758 \uc911\uc2ec\uc744 \uc7a1\uc544 \uc900\ub2e4. \ud654\ub824\ud55c \uc637\uc758 \ubb34\ub2ac\uac00 \ub9ce\uc9c0 \uc54a\uc544\ub3c4 \ucd08\uc0c1\uc740 \ud48d\ubd80\ud560 \uc218 \uc788\ub2e4. \uc5b4\ub514\uac00 \ubc1d\uace0 \uc5b4\ub514\uac00 \uac00\ub77c\uc549\uc544 \uc788\ub294\uc9c0, \uc5b4\uae68\uc640 \ubab8\uc758 \uc724\uacfd\uc774 \ubc30\uacbd\uc5d0\uc11c \uc5b4\ub5bb\uac8c \uad6c\ubcc4\ub418\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uac80\uc740\uc0c9\uc744 \uadf8\ub9bc\uc758 \ube48\uce78\uc73c\ub85c \ucde8\uae09\ud558\uc9c0 \uc54a\uc73c\uba74 \ubcfc \ubd80\ubd84\uc774 \ub298\uc5b4\ub09c\ub2e4. \uc778\ubb3c\uc740 \uc5bc\uad74\uacfc \ub208\uae38\uc744 \uc815\uba74\uc5d0 \uace0\uc815\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc57d\uac04 \uc606\uc744 \ubc14\ub77c\ubcf4\ub294 \ub4ef\ud55c \uc790\uc138\ub2e4. \uad00\uac1d\uc744 \ud5a5\ud574 \ubaa8\ub4e0 \uac83\uc744 \uc124\uba85\ud558\ub824\ub294 \ubaa8\uc2b5\ubcf4\ub2e4, \ud654\uba74 \ubc16\uc5d0\ub3c4 \uc790\uae30 \uad00\uc2ec\uc774 \uc788\ub294 \uc0ac\ub78c\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \uadf8 \ubc29\ud5a5\uc5d0 \ubb34\uc5c7\uc774 \uc2e4\uc81c\ub85c \uc788\uc5c8\ub294\uc9c0 \uc6b0\ub9ac\uac00 \ud655\uc778\ud560 \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub9bc \ubc16\uc758 \uc0ac\ub78c\uc774\ub098 \ub300\ud654\ub97c \uc9c0\uc5b4\ub0b4\ub294 \ub300\uc2e0, \uc815\uba74\uc744 \ubcfc \ub54c\uc640 \uc774 \uc2dc\uc120\uc774 \uc8fc\ub294 \uc778\uc0c1\uc774 \uc5b4\ub5bb\uac8c \ub2e4\ub978\uc9c0 \uc0dd\uac01\ud574 \ubcf4\uc790. \ud55c \uc0ac\ub78c\uc758 \ub0b4\uba74\uc744 \ubaa8\ub450 \uc548\ub2e4\uace0 \uc8fc\uc7a5\ud558\uc9c0 \uc54a\uc544\ub3c4 \uc790\uc138\uc758 \ud6a8\uacfc\ub294 \ub290\ub084 \uc218 \uc788\ub2e4. \uc67c\uc190 \ucabd\uc5d0\ub294 \uc7a5\uac11\uacfc \ub2e4\ub978 \ud55c \uc9dd\uc758 \uc7a5\uac11\uc774 \ubcf4\uc778\ub2e4. \uc190\uc740 \ubc1b\uce68\ub300 \uac00\uae4c\uc774 \ub193\uc5ec \uc788\uc5b4 \ubab8\uc758 \uc704\uce58\ub97c \uc548\uc815\uc2dc\ud0a4\ub294 \uc5ed\ud560\ub3c4 \ud55c\ub2e4. \uc81c\ubaa9\uc744 \uc54c\uace0 \ub098\uba74 \uadf8 \ubd80\ubd84\uc774 \uba3c\uc800 \ubcf4\uc774\uc9c0\ub9cc, \ud55c \ubc88 \ucc3e\uc740 \ub4a4\uc5d0\ub294 \uc5bc\uad74\uacfc\uc758 \uac70\ub9ac\ub97c \ud568\uaed8 \uc0b4\ud53c\uba74 \uc88b\ub2e4. \uc7a5\uac11\uc740 \uc190\uc744 \ub36e\ub294 \ubb3c\uac74\uc774\uba74\uc11c \ucd08\uc0c1 \uc18d \ucc28\ub9bc\uc0c8\uc758 \uc77c\ubd80\ub2e4. \uc637\uacfc \uc7a5\uc2e0\uad6c, \ubab8\uc758 \ud0dc\ub3c4\ub97c \ud568\uaed8 \ubcf4\uba74 \uc778\ubb3c\uc774 \uc5b4\ub5a4 \uc0ac\ud68c\uc801 \uc774\ubbf8\uc9c0\ub97c \ubcf4\uc5ec \uc8fc\ub3c4\ub85d \uad6c\uc131\ub418\uc5c8\ub294\uc9c0 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \ub2e4\ub9cc \uc7a5\uac11 \ud558\ub098\ub85c \uc815\ud655\ud55c \uc9c1\uc5c5\uc774\ub098 \uc2e0\ubd84\uc744 \ud655\uc815\ud558\ub294 \uac83\uc740 \ub2e4\ub978 \uc99d\uac70\uac00 \ud544\uc694\ud55c \uc77c\uc774\ub2e4. \uadf8\ub9bc\uc5d0\ub294 \uc7a5\uac11\uc73c\ub85c \ub36e\uc778 \uc190\uacfc \uadf8\ub807\uc9c0 \uc54a\uc740 \uc190\uc758 \ucc28\uc774\uac00 \uc788\ub2e4. \ub9e8\uc190 \ucabd\uc5d0\ub294 \ubc18\uc9c0\ub3c4 \ubcf4\uc778\ub2e4. \uc5bc\uad74\uacfc \ud568\uaed8 \ud53c\ubd80\uac00 \ub4dc\ub7ec\ub098\ub294 \ubd80\ubd84, \ucc9c\uacfc \uac00\uc8fd\uc73c\ub85c \ub36e\uc778 \ubd80\ubd84\uc744 \ubc88\uac08\uc544 \ubcf4\uba74 \ucd08\uc0c1 \uc548\uc758 \uc7ac\ub8cc\uac00 \ub2e4\uc591\ud558\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ub290\ub084 \uc218 \uc788\ub2e4. \uc190\uc740 \uc5bc\uad74\uc5d0 \ub367\ubd99\uc740 \ubd80\uc18d\ud488\uc774 \uc544\ub2c8\ub2e4. \uc5b4\ub5bb\uac8c \ub193\uc5ec \uc788\ub290\ub0d0\uc5d0 \ub530\ub77c \uc778\ubb3c\uc758 \uae34\uc7a5\uacfc \ud3b8\uc548\ud568\uc774 \ub2e4\ub974\uac8c \ubcf4\uc77c \uc218 \uc788\ub2e4. \uc785\uac00\uc758 \ud45c\uc815\ub9cc \uad00\ucc30\ud558\ub358 \uac10\uc0c1\uc744 \uc190\uacfc \ud314\ub85c \ub113\ud788\ub294 \uc88b\uc740 \uc791\ud488\uc774\ub2e4. \ub204\uad70\uac00\uc758 \uc131\uaca9\uc744 \uc190 \ud558\ub098\ub85c \uc9c4\ub2e8\ud558\ub294 \ub300\uc2e0 \ud654\uba74\uc774 \ub9cc\ub4dc\ub294 \uc790\uc138\ub97c \uc0b4\ud3b4\ubcf4\uc790. \uac80\uc740 \uc637 \uc0ac\uc774\uc758 \ud770 \uc154\uce20\ub294 \uc5bc\uad74 \uc544\ub798\uc5d0\uc11c \ubc1d\uc740 \uae38\uc744 \ub9cc\ub4e0\ub2e4. \ubaa9 \uadfc\ucc98\uc758 \uae08\ube5b\uacfc \uc190\uc758 \uc791\uc740 \uc7a5\uc2dd\uc740 \uc2dc\uc120\uc744 \ub2e4\uc2dc \uba48\ucd94\uac8c \ud55c\ub2e4. \ud070 \uc7a5\uc2dd\ubcf4\ub2e4 \uc791\uc740 \ucc28\uc774\uac00 \ub450\ub4dc\ub7ec\uc9c0\ub294 \ud654\uba74\uc774\ub2e4. \uc5b4\ub514\uc5d0 \ub208\uc774 \uba3c\uc800 \uac00\ub294\uc9c0 \uc2a4\uc2a4\ub85c \ub530\ub77c\uac00 \ubcf4\uba74 \uad6c\uc131\uc744 \uad6c\uccb4\uc801\uc73c\ub85c \ub290\ub084 \uc218 \uc788\ub2e4. \uc5bc\uad74\uc5d0\uc11c \ud770 \uc637\uc73c\ub85c, \uc190\uacfc \uc7a5\uac11\uc73c\ub85c \ub0b4\ub824\uc654\ub2e4\uac00 \ub2e4\uc2dc \uc5bc\uad74\ub85c \uc62c\ub77c\uac00 \ubcf4\uc790. \uc775\uc219\ud55c \ucd08\uc0c1\ub3c4 \ub208\uae38\uc758 \uc21c\uc11c\ub97c \ubc14\uafb8\uba74 \ub2e4\ub978 \uad00\uacc4\uac00 \ubcf4\uc778\ub2e4. \uc774 \uc21c\uc11c\uac00 \uc815\ub2f5\uc774\ub77c\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc791\ud488\uc744 \ud55c \ubc88 \ub354 \ubcf4\ub294 \uc791\uc740 \ubc29\ubc95\uc73c\ub85c \uc0ac\uc6a9\ud558\uba74 \ub41c\ub2e4. \ud2f0\uce58\uc544\ub178\ub294 \ubca0\ub124\uce58\uc544 \ud68c\ud654\uc758 \uc911\uc694\ud55c \ud654\uac00\ub85c, \uc778\ubb3c\uacfc \uc637, \ud53c\ubd80\uc640 \ube5b\uc758 \uad00\uacc4\ub97c \ub2e4\ub8e8\ub294 \ucd08\uc0c1\ub4e4\uc744 \ub0a8\uacbc\ub2e4. \uc774 \uc791\ud488\uc5d0\uc11c\ub3c4 \uc8fc\uc778\uacf5\uc758 \uc774\uc57c\uae30\ub97c \uae00\ub85c \uae38\uac8c \ubd99\uc774\uc9c0 \uc54a\uace0 \ud654\uba74 \uc790\uccb4\ub85c \uc874\uc7ac\uac10\uc744 \ub9cc\ub4e0\ub2e4. \uc0ac\ub78c\uc758 \uc5bc\uad74\ubfd0 \uc544\ub2c8\ub77c \uc8fc\ubcc0 \uc7ac\ub8cc\ub97c \uadf8\ub9ac\ub294 \uc77c\uc774 \ud568\uaed8 \uc791\uc6a9\ud55c\ub2e4. \ubaa8\ub378\uc758 \uc774\ub984\uc744 \ud655\uc778\ud558\ub294 \uc5f0\uad6c\ub294 \uc911\uc694\ud558\uc9c0\ub9cc, \uad00\uac1d\uc758 \uac10\uc0c1\uc774 \uadf8 \ud655\uc778 \uc804\uae4c\uc9c0 \uc815\uc9c0\ud574\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc544\ub294 \uc0ac\uc2e4\uc774 \uc801\uc744 \ub54c\uc5d0\ub3c4 \uc0c9\uacfc \uc790\uc138, \ubb3c\uac74\uc758 \uad00\uacc4\ub97c \ubcfc \uc218 \uc788\ub2e4. \ub098\uc911\uc5d0 \ub354 \uc815\ud655\ud55c \uc815\ubcf4\ub97c \uc5bb\uc73c\uba74 \uadf8\ub54c \ub2e4\uc2dc \uadf8\ub9bc\uc73c\ub85c \ub3cc\uc544\uc624\uba74 \ub41c\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 \uc61b \ub8e8\ube0c\ub974 \ub3c4\ub85d\uc5d0 \uc2e4\ub9b0 \uc2e4\uc81c \ud68c\ud654 \uc7ac\ud604 \uc790\ub8cc\ub2e4. \uac80\uc740 \uc637\uacfc \ubc30\uacbd\uc758 \ubbf8\ubb18\ud55c \ucc28\uc774\ub294 \uc61b \uc778\uc1c4\uc5d0\uc11c \uc2e4\ubb3c\uacfc \ub2e4\ub974\uac8c \ubcf4\uc77c \uc218 \uc788\ub2e4. \uadf8\ub7ec\ubbc0\ub85c \ubaa8\ub4e0 \uc5b4\ub450\uc6b4 \ubd80\ubd84\uc758 \ud45c\uba74\uae4c\uc9c0 \ud655\uc815\ud558\uae30\ubcf4\ub2e4 \ud070 \ubc1d\uae30\uc640 \uc778\ubb3c\uc758 \ubc30\uce58\ub97c \uc911\uc2ec\uc73c\ub85c \uc0b4\ud3b4\ubcf4\uc558\ub2e4. \uc6d0\uc791\uc744 \ub2ee\uac8c \uc0c8\ub85c \ub9cc\ub4e0 AI \ucd08\uc0c1\uc774 \uc544\ub2c8\ub77c \uc2e4\uc81c \uc791\ud488\uc758 \ub3c4\ud310\uc774\ub77c\ub294 \uc810\uc740 \uad6c\ubd84\ud574 \ub450\uba74 \uc88b\ub2e4. \ud604\ub300\uc778\uc774 \uc0c1\uc0c1\ud55c \ub0a8\uc790\uc758 \uc637\ucc28\ub9bc\uc744 \ud2f0\uce58\uc544\ub178\uc758 \uc120\ud0dd\uc774\ub77c\uace0 \uc124\uba85\ud558\uc9c0 \uc54a\uae30 \uc704\ud574\uc11c\ub2e4. \uc774\ubbf8\uc9c0\uc758 \uc885\ub958\ub97c \uc54c\uace0 \ubcf4\ub294 \uac83\uc774 \uc791\ud488\uc5d0 \uad00\ud55c \uc9c0\uc2dd\uc744 \ub354 \ub2e8\ub2e8\ud558\uac8c \ud574 \uc900\ub2e4. \uadf8\ub9bc\uc744 \ubcf8 \ub4a4 \uc81c\ubaa9\uc744 \ub2e4\uc2dc \uc77d\uc73c\uba74 \uc7a5\uac11\uc774\ub77c\ub294 \uc791\uc740 \ubb3c\uac74\uc774 \ub2e4\ub978 \ubb34\uac8c\ub97c \uac00\uc9c4\ub2e4. \uc5bc\uad74\uacfc \uc190, \ucc28\ub9bc\uc0c8\ub97c \uc5f0\uacb0\ud574 \uae30\uc5b5\ud558\uac8c \ud558\ub294 \ud45c\uc9c0\uac00 \ub418\uc5c8\uae30 \ub54c\ubb38\uc774\ub2e4. \ud3c9\ubc94\ud55c \ubb3c\uac74\ub3c4 \ud654\uba74 \uc18d \uc704\uce58\uc640 \uad00\uacc4\uc5d0 \ub530\ub77c \uc0ac\ub78c\uc744 \ub5a0\uc62c\ub9ac\ub294 \uc5f4\uc1e0\uac00 \ub420 \uc218 \uc788\ub2e4. \uc624\ub298\uc740 \uc774 \ub0a8\uc790\uc758 \ubaa8\ub4e0 \uc0ac\uc5f0\uc744 \uc54c\uc544\ub0b4\ub824 \ud558\uc9c0 \uc54a\uc544\ub3c4 \uc88b\ub2e4. \uc5b4\ub5a4 \ubd80\ubd84\uc740 \ubc1d\uac8c \ub4dc\ub7ec\ub098\uace0 \uc5b4\ub5a4 \ubd80\ubd84\uc740 \uc5b4\ub460\uc5d0 \ub0a8\ub294\uc9c0 \ubcf4\uba70 \ud55c \uc0ac\ub78c\uc758 \uc55e\uc5d0 \uc7a0\uc2dc \uba38\ubb3c\ub7ec \ubcf4\uc790. \ucd08\uc0c1\ud654\uc758 \uad50\uc591\uc740 \uc774\ub984\uc744 \uc678\uc6b0\ub294 \uc77c\ubfd0 \uc544\ub2c8\ub77c \uc0ac\ub78c\uc744 \ubcf4\ub294 \uc790\uc2e0\uc758 \uc2b5\uad00\uc744 \uc870\uae08 \ub113\ud788\ub294 \ub370\uc11c\ub3c4 \uc0dd\uae34\ub2e4."}, {"id": "treasure-island-trust-and-map", "title": "\ubcf4\ubb3c\uc12c \u2014 \uc9c0\ub3c4\ubcf4\ub2e4 \uc5b4\ub824\uc6b4 \uac83\uc740 \uc0ac\ub78c\uc744 \uc77d\ub294 \uc77c", "summary": "\ubcf4\ubb3c\uc744 \ucc3e\ub294 \ubaa8\ud5d8\uc758 \uc904\uac70\ub9ac\uc640 \uc778\ubb3c\uc758 \uc120\ud0dd\uc744 \ud568\uaed8 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Literature", "url": "stories/treasure-island-trust-and-map/index.html", "image": "media/treasure-island-trust-and-map.png", "alt": "\uc9d0 \ud638\ud0a8\uc2a4\uac00 \ubc30 \uc704\uc5d0\uc11c \uc9c0\ub3c4\ub97c \ub4e4\uace0 \uc678\ub2e4\ub9ac\uc758 \ub871 \uc874 \uc2e4\ubc84\uc640 \uc12c\uc744 \ubc14\ub77c\ubcf4\ub294 \uc0c1\uc0c1 \uc0bd\ud654.", "text": "\ubcf4\ubb3c\uc12c \u2014 \uc9c0\ub3c4\ubcf4\ub2e4 \uc5b4\ub824\uc6b4 \uac83\uc740 \uc0ac\ub78c\uc744 \uc77d\ub294 \uc77c \uc9d0 \ud638\ud0a8\uc2a4\uc640 \ub871 \uc874 \uc2e4\ubc84, \ubbff\uc74c\uc774 \ud754\ub4e4\ub9ac\ub294 \ubc14\ub2e4 \ubcf4\ubb3c\uc744 \ucc3e\ub294 \ubaa8\ud5d8\uc758 \uc904\uac70\ub9ac\uc640 \uc778\ubb3c\uc758 \uc120\ud0dd\uc744 \ud568\uaed8 \uc77d\uc2b5\ub2c8\ub2e4. Literature \ubb38\ud654 \uc624\ub798\ub41c \uc9c0\ub3c4\uc5d0\ub294 \ubcf4\ubb3c\uc774 \ubb3b\ud78c \uc790\ub9ac\uac00 \ud45c\uc2dc\ub418\uc5b4 \uc788\ub2e4. \ubaa9\uc801\uc9c0\ub9cc \uc54c\uba74 \uae38\uc744 \ucc3e\uc744 \uc218 \uc788\uc744 \uac83 \uac19\uc9c0\ub9cc, \ud568\uaed8 \ubc30\ub97c \ud0c4 \uc0ac\ub78c\ub4e4 \uc911 \ub204\uad6c\ub97c \ubbff\uc5b4\uc57c \ud558\ub294\uc9c0\ub294 \uc9c0\ub3c4\uc5d0 \ub098\uc624\uc9c0 \uc54a\ub294\ub2e4. \u300e\ubcf4\ubb3c\uc12c\u300f\uc758 \ubaa8\ud5d8\uc740 \uadf8 \ub450 \uc885\ub958\uc758 \uc5b4\ub824\uc6c0\uc744 \ud568\uaed8 \uc6c0\uc9c1\uc778\ub2e4. \uc18c\ub144 \uc9d0 \ud638\ud0a8\uc2a4\ub294 \uc5b4\ub978\ub4e4\uc758 \ube44\ubc00\uacfc \ud0d0\uc695, \uc6a9\uae30\uc640 \uacc4\uc0b0\uc774 \uc5bd\ud78c \ubc14\ub2e4\ub85c \ub4e4\uc5b4\uac04\ub2e4. \uac00\uc7a5 \uc778\uc0c1\uc801\uc778 \uc5b4\ub978\uc740 \uce5c\uadfc\ud55c \ub9d0\ud22c\uc640 \uc704\ud5d8\ud55c \uc18d\ub0b4\ub97c \ud568\uaed8 \uac00\uc9c4 \ub871 \uc874 \uc2e4\ubc84\ub2e4. \uc544\ub798\uc5d0\ub294 \uc8fc\uc694 \uc904\uac70\ub9ac\uc640 \uacb0\ub9d0\uc774 \ud3ec\ud568\ub418\uc5b4 \uc788\ub2e4. \uc9d0\uc758 \uc9d1\uc774 \uc6b4\uc601\ud558\ub294 \uc5ec\uad00\uc5d0 \ube4c\ub9ac \ubcf8\uc988\ub77c\ub294 \ub299\uc740 \uc120\uc6d0\uc774 \uba38\ubb38\ub2e4. \uadf8\ub97c \ucc3e\uc544\uc624\ub294 \uc218\uc0c1\ud55c \uc778\ubb3c\ub4e4\uacfc \uac80\uc740 \ud45c\uc2dd\uc740 \ud3c9\ubc94\ud55c \uc0dd\ud65c\uc744 \uc704\ud611\ud55c\ub2e4. \ubcf8\uc988\uac00 \uc8fd\uc740 \ub4a4 \uc9d0\uc740 \ubb3c\uac74\ub4e4 \uc0ac\uc774\uc5d0\uc11c \ubcf4\ubb3c \uc9c0\ub3c4\ub97c \ubc1c\uacac\ud55c\ub2e4. \uc77c\uc0c1\uc5d0\uc11c \uaebc\ub0b8 \uc885\uc774 \ud55c \uc7a5\uc774 \uba3c \uc12c\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \ubb38\uc774 \ub41c\ub2e4. \uc9d0\uc740 \ucc98\uc74c\ubd80\ud130 \ub2a5\uc219\ud55c \ubaa8\ud5d8\uac00\ub294 \uc544\ub2c8\ub2e4. \ubb34\uc2a8 \uc77c\uc774 \ubc8c\uc5b4\uc9c0\ub294\uc9c0 \uc644\uc804\ud788 \uc54c\uc9c0 \ubabb\ud558\ub294 \uc0c1\ud0dc\uc5d0\uc11c \uc6c0\uc9c1\uc778\ub2e4. \ub3c5\uc790\ub294 \uc18c\ub144\uc774 \ub4e3\uace0 \ubcf4\uace0 \uc624\ud574\ud558\ub294 \uacfc\uc815\uc744 \ub530\ub77c\uac00\ubbc0\ub85c, \uc774\ubbf8 \ubaa8\ub4e0 \uac83\uc744 \uc544\ub294 \uc601\uc6c5\uc758 \uc2b9\ub9ac\ubcf4\ub2e4 \uc0c8\ub85c\uc6b4 \uc138\uacc4\ub97c \ubc30\uc6cc \uac00\ub294 \uae34\uc7a5\uc744 \uacbd\ud5d8\ud558\uac8c \ub41c\ub2e4. \ub9ac\ube0c\uc9c0 \uc758\uc0ac\uc640 \ud2b8\ub9b4\ub85c\ub2c8 \uc9c0\uc8fc\uac00 \uc6d0\uc815\uc5d0 \ub098\uc11c\uace0 \ud788\uc2a4\ud30c\ub2c8\uc62c\ub77c\ud638\uac00 \uc900\ube44\ub41c\ub2e4. \ud544\uc694\ud55c \uac83\uc740 \ubc30\uc640 \uc2dd\ub7c9\ubfd0 \uc544\ub2c8\ub77c \ud568\uaed8 \uc77c\ud560 \uc0ac\ub78c\ub4e4\uc774\ub2e4. \uc774 \uacfc\uc815\uc5d0\uc11c \uc694\ub9ac\uc0ac \ub871 \uc874 \uc2e4\ubc84\uac00 \uc911\uc694\ud55c \uc790\ub9ac\ub97c \ucc28\uc9c0\ud55c\ub2e4. \uc0ac\ub78c\uc744 \ucd94\ucc9c\ud558\uace0 \ubd84\uc704\uae30\ub97c \ub9cc\ub4e4\uba70 \uc2e0\ub8b0\ub97c \uc5bb\ub294\ub2e4. \ub3c8\uacfc \uc9c0\uc704\uac00 \uc788\ub2e4\uace0 \ud574\uc11c \uc0ac\ub78c\uc744 \ubcf4\ub294 \ud310\ub2e8\uae4c\uc9c0 \uc800\uc808\ub85c \uc88b\uc544\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc900\ube44\ub294 \uac89\uc73c\ub85c \uc21c\uc870\ub85c\uc6cc\ub3c4 \uadf8 \uc548\uc5d0 \ub2e4\ub978 \ubaa9\uc801\uc744 \uac00\uc9c4 \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc778\ub2e4. \ubcf4\ubb3c \uc9c0\ub3c4\ub97c \uc190\uc5d0 \ub123\ub294 \uac83\uacfc \ubaa8\ud5d8\uc744 \uc81c\ub300\ub85c \uc774\ud574\ud558\ub294 \uac83\uc740 \uc11c\ub85c \ub2e4\ub978 \uc77c\uc774\ub77c\ub294 \uc0ac\uc2e4\uc774 \uc11c\uc11c\ud788 \ub4dc\ub7ec\ub09c\ub2e4. \uc2e4\ubc84\ub294 \ud55c\ucabd \ub2e4\ub9ac\uac00 \uc5c6\uace0 \ubaa9\ubc1c\uc744 \uc0ac\uc6a9\ud55c\ub2e4. \ub110\ub9ac \ub5a0\uc62c\ub9ac\ub294 \ud574\uc801\uc758 \uc0c1\uc9d5\uc744 \ubaa8\ub450 \ud55c\uaebc\ubc88\uc5d0 \ubd99\uc774\uae30\ubcf4\ub2e4 \uc6d0\uc791\uc758 \uc774 \uad6c\uccb4\uc801\uc778 \ubaa8\uc2b5\uc744 \uc54c\uc544 \ub450\uba74 \uc88b\ub2e4. \uadf8\uc758 \ud798\uc740 \uac70\uce5c \uc678\ubaa8\ub9cc\uc774 \uc544\ub2c8\ub77c \uc0ac\ub78c\uc744 \ub300\ud558\uace0 \uc0c1\ud669\uc744 \uc77d\ub294 \ub2a5\ub825\uc5d0\ub3c4 \uc788\ub2e4. \uc9d0\uc5d0\uac8c \ub9d0\uc744 \uac78\uace0 \uce5c\uadfc\ud558\uac8c \ud589\ub3d9\ud558\ub294 \ubaa8\uc2b5\uacfc, \ub2e4\ub978 \ubaa9\uc801\uc744 \uc704\ud574 \uacc4\uc0b0\ud558\ub294 \ubaa8\uc2b5\uc774 \uac19\uc740 \uc778\ubb3c \uc548\uc5d0 \uc788\ub2e4. \uadf8\ub798\uc11c \uc2e4\ubc84\ub97c \ucc98\uc74c\ubd80\ud130 \ub05d\uae4c\uc9c0 \ub2e8\uc21c\ud55c \uc545\ub2f9\uc758 \uc5bc\uad74\ub85c\ub9cc \uc77d\uae30 \uc5b4\ub835\ub2e4. \ub204\uad70\uac00\uac00 \ub098\uc5d0\uac8c \uce5c\uc808\ud588\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uadf8\uc758 \ubaa8\ub4e0 \ud589\ub3d9\uc744 \uc124\uba85\ud558\uac70\ub098 \ubcf4\uc99d\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4\ub294 \ubb38\uc81c\ub3c4 \uc0dd\uae34\ub2e4. \uc9d0\uc740 \uc0ac\uacfc \ud1b5\uc5d0 \ub4e4\uc5b4\uac00 \uc788\ub2e4\uac00 \uc2e4\ubc84\uc640 \ub2e4\ub978 \uc120\uc6d0\ub4e4\uc758 \ub300\ud654\ub97c \ub4e3\ub294\ub2e4. \ubbff\uc5c8\ub358 \ub3d9\ud589 \uc18d\uc5d0 \ubc18\ub780\uacfc \ubcf4\ubb3c \ud0c8\ucde8\uc758 \uacc4\ud68d\uc774 \uc788\uc5c8\uc74c\uc744 \uc54c\uac8c \ub418\ub294 \uc7a5\uba74\uc774\ub2e4. \uac89\uc73c\ub85c \ubcf4\uc774\ub358 \uc5ec\ud589\uacfc \uc2e4\uc81c\ub85c \uc9c4\ud589\ub418\ub358 \uacc4\ud68d\uc774 \ub2ec\ub790\ub2e4. \uc0c8\ub85c\uc6b4 \uc0ac\uc2e4\uc744 \uc54c\uc558\ub2e4\uace0 \uace7\ubc14\ub85c \uc548\uc804\ud574\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub204\uad6c\uc5d0\uac8c \uc54c\ub9ac\uace0 \uc5b4\ub5bb\uac8c \ud589\ub3d9\ud574\uc57c \ud560\uc9c0 \ud310\ub2e8\ud574\uc57c \ud55c\ub2e4. \uc9d0\uc774 \uac00\uc9c4 \uc815\ubcf4\ub294 \ud798\uc774 \ub418\uc9c0\ub9cc \uc704\ud5d8\ub3c4 \ud568\uaed8 \uac00\uc838\uc628\ub2e4. \ubaa8\ud5d8\uc758 \uc7ac\ubbf8\ub294 \ube44\ubc00\uc744 \ub4e3\ub294 \ub370\uc11c \ub05d\ub098\uc9c0 \uc54a\uace0 \uadf8 \uc9c0\uc2dd\uc744 \uac00\uc9c0\uace0 \ub2e4\uc74c \ud589\ub3d9\uc744 \uace0\ub974\ub294 \ub370 \uc774\uc5b4\uc9c4\ub2e4. \uc12c\uc5d0 \ub3c4\ucc29\ud55c \ub4a4 \uc77c\ud589\uc740 \uac08\ub77c\uc9c0\uace0 \ucda9\ub3cc\ud55c\ub2e4. \uc9d0\uc740 \ubca4 \uac74\uc744 \ub9cc\ub098\uace0, \ubc30\ub97c \ub458\ub7ec\uc2fc \uc704\ud5d8 \uc18d\uc5d0\ub3c4 \ub6f0\uc5b4\ub4e0\ub2e4. \ud63c\uc790 \ud589\ub3d9\ud558\ub294 \uc120\ud0dd\uc774 \uc911\uc694\ud55c \ubcc0\ud654\ub97c \ub9cc\ub4e4\uc9c0\ub9cc \uc5b8\uc81c\ub098 \ubbf8\ub9ac \uc0dd\uac01\ud55c \ub300\ub85c \uc798\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud2b9\ud788 \ubc30 \uc704\uc5d0\uc11c \uc774\uc2a4\ub77c\uc5d8 \ud578\uc988\uc640 \ub9c8\uc8fc\ud558\ub294 \ub300\ubaa9\uc740 \ubaa8\ud5d8\uc758 \uc704\ud5d8\uc744 \uad6c\uccb4\uc801\uc73c\ub85c \ubcf4\uc5ec \uc900\ub2e4. \uc774\ub97c \uba4b\uc9c4 \uc6a9\uae30\uc758 \uc21c\uac04\uc73c\ub85c\ub9cc \uc77d\uc73c\uba74 \uc18c\ub144\uc774 \uac10\ub2f9\ud574\uc57c \ud558\ub294 \uacf5\ud3ec\uac00 \uc9c0\uc6cc\uc9c0\uae30 \uc27d\ub2e4. \uc18c\uc124\uc758 \uae34\uc7a5\uc740 \ub300\ub2f4\ud568\uacfc \ubd88\uc548, \uc6b0\uc5f0\uacfc \ud310\ub2e8\uc774 \ud568\uaed8 \uc788\ub2e4\ub294 \ub370 \uc788\ub2e4. \ud574\uc801\ub4e4\uc774 \uae30\ub300\ud55c \uacf3\uc5d0\ub294 \ubcf4\ubb3c\uc774 \uadf8\ub300\ub85c \ub0a8\uc544 \uc788\uc9c0 \uc54a\ub2e4. \ubca4 \uac74\uc774 \uc774\ubbf8 \uadf8\uac83\uc744 \uc62e\uaca8 \ub193\uc558\uae30 \ub54c\ubb38\uc774\ub2e4. \uc9c0\ub3c4\ub294 \uacfc\uac70\uc758 \uc815\ubcf4\ub97c \ub2f4\uace0 \uc788\uc5c8\uc9c0\ub9cc \uc774\ud6c4\uc5d0 \uc77c\uc5b4\ub09c \uc77c\uae4c\uc9c0 \uc790\ub3d9\uc73c\ub85c \uc54c\ub824 \uc8fc\uc9c0\ub294 \uc54a\uc558\ub2e4. \uc885\uc774\uc5d0 \ud655\uc2e0\uc744 \uac78\uc5c8\ub358 \uc0ac\ub78c\ub4e4\uc758 \uacc4\ud68d\uc774 \ud754\ub4e4\ub9b0\ub2e4. \uc774 \uc7a5\uba74\uc5d0\uc11c\ub294 \ubb3c\uac74\uc758 \uac00\uce58\ubfd0 \uc544\ub2c8\ub77c \uc815\ubcf4\uac00 \uc5b8\uc81c\uc758 \uac83\uc778\uc9c0\ub3c4 \uc911\uc694\ud574\uc9c4\ub2e4. \uc815\ub2f5\ucc98\ub7fc \ubcf4\uc774\ub358 \ud45c\uc2dc\ub294 \uc0c1\ud669\uc774 \ub2ec\ub77c\uc9c0\uba74 \ucda9\ubd84\ud558\uc9c0 \uc54a\ub2e4. \ubcf4\ubb3c\uc774 \uc788\ub294 \uc7a5\uc18c\ub97c \uc548\ub2e4\ub294 \ubbff\uc74c\uacfc \uc2e4\uc81c\ub85c \uadf8\uacf3\uc5d0 \ub3c4\ucc29\ud574 \ub9cc\ub098\ub294 \ud604\uc2e4 \uc0ac\uc774\uc758 \ucc28\uc774\uac00 \uacb0\ub9d0\uc744 \uc6c0\uc9c1\uc778\ub2e4. \uc2e4\ubc84\ub294 \uc704\ud5d8\ud574\uc9c4 \uc0c1\ud669\uc5d0\uc11c\ub3c4 \uc0b4\uc544\ub0a8\uc744 \uae38\uc744 \ucc3e\ub294\ub2e4. \uc9d0\uc744 \uc9c0\ucf1c \uc8fc\ub294 \ud589\ub3d9\uc744 \ud558\uba74\uc11c\ub3c4 \uc790\uc2e0\uc758 \uc774\uc775\uc744 \ub193\uc9c0 \uc54a\ub294\ub2e4. \ub3c4\uc6c0\uc744 \uc8fc\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ubbff\uc744 \uc218 \uc788\ub294 \uc0ac\ub78c\uc73c\ub85c \uc644\uc804\ud788 \ubc14\ub00c\uc5c8\ub2e4\ub294 \ud310\ub2e8\uc744 \uace7\ubc14\ub85c \uac19\uac8c \ub9cc\ub4e4\uae30\ub294 \uc5b4\ub835\ub2e4. \ub9c8\uce68\ub0b4 \ubcf4\ubb3c\uc744 \uac00\uc9c0\uace0 \ub5a0\ub098\ub294 \uc5ec\uc815\uc5d0\uc11c\ub3c4 \uadf8\ub294 \ub05d\uae4c\uc9c0 \uae54\ub054\ud558\uac8c \uc815\ub9ac\ub418\uc9c0 \uc54a\ub294\ub2e4. \ub3c8\uc758 \uc77c\ubd80\ub97c \uac00\uc9c0\uace0 \uc0ac\ub77c\uc9c0\ub294 \uc2e4\ubc84\ub294 \ub3c5\uc790\uc5d0\uac8c\ub3c4 \ubaa8\ud638\ud55c \uae30\uc5b5\uc744 \ub0a8\uae34\ub2e4. \uc9c8\uc11c\uac00 \ud68c\ubcf5\ub418\uba74 \uc545\uc778\uc740 \uc815\ud574\uc9c4 \ubc8c\uc744 \ubc1b\uace0 \ubaa8\ub4e0 \ubb38\uc81c\uac00 \ub05d\ub09c\ub2e4\ub294 \ub2e8\uc21c\ud55c \ub9c8\ubb34\ub9ac\uc640 \uac70\ub9ac\uac00 \uc788\ub2e4. \uc9d0\uc740 \ubaa8\ud5d8\uc5d0\uc11c \ub3cc\uc544\uc624\uc9c0\ub9cc \uc12c\uacfc \ubc14\ub2e4\uc758 \uc18c\ub9ac\ub97c \uc644\uc804\ud788 \uc78a\uc9c0 \ubabb\ud55c\ub2e4. \ubcf4\ubb3c\uc744 \uc5bb\uc5c8\ub2e4\ub294 \uc131\uacf5\ub9cc\uc73c\ub85c \uacbd\ud5d8\uc774 \ubaa8\ub450 \ud658\ud55c \ucd94\uc5b5\uc774 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubb34\uc11c\uc6e0\ub358 \uc7a5\uba74\uacfc \ubbff\uc74c\uc774 \ud754\ub4e4\ub9b0 \uc21c\uac04\ub3c4 \ud568\uaed8 \ub0a8\ub294\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uc9d0\uacfc \ubaa9\ubc1c\uc744 \uc9da\uc740 \uc678\ub2e4\ub9ac\uc758 \uc2e4\ubc84\uac00 \uc12c\uc744 \ubc14\ub77c\ubcf4\ub294 \uc7a5\uba74\uc744 \uc0c1\uc0c1\ud588\ub2e4. \uc6d0\uc791 \uc9c0\ub3c4\ub098 \uc2e4\uc81c \ubc30\uc758 \ubcf5\uc6d0\ub3c4\ub294 \uc544\ub2c8\ub2e4. \ub450 \uc0ac\ub78c\uc774 \uac19\uc740 \uacf3\uc744 \ubc14\ub77c\ubcf4\uba74\uc11c\ub3c4 \uac19\uc740 \ubaa9\uc801\uc744 \uac00\uc84c\ub2e4\uace0 \ub2e8\uc815\ud560 \uc218 \uc5c6\ub2e4\ub294 \uad00\uacc4\ub97c \ub2f4\uc558\ub2e4. \uc9c0\ub3c4\uc5d0 \uc5c6\ub294 \uc0ac\ub78c\uc758 \uc18d\ub0b4\ub97c \uc77d\ub294 \uc77c\uc774 \uc65c \ub354 \uc5b4\ub824\uc6e0\ub294\uc9c0 \uc0dd\uac01\ud558\uba70 \uc18c\uc124\ub85c \ub3cc\uc544\uac00 \ubcf4\uc790."}, {"id": "trombone-sliding-notes", "title": "\ud2b8\ub86c\ubcf8 \uc5f0\uc8fc\uc790\ub294 \uc65c \ud314\uc744 \uae38\uac8c \ubed7\uc744\uae4c", "summary": "\uc55e\uc73c\ub85c \ub098\uac14\ub2e4 \ub3cc\uc544\uc624\ub294 \uae34 \uad00. \ud2b8\ub86c\ubcf8\uc758 \ub208\uc5d0 \ub744\ub294 \ub3d9\uc791\uc740 \uc74c\uc744 \uace0\ub974\ub294 \uc77c\uc774\uae30\ub3c4 \ud569\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Music", "url": "stories/trombone-sliding-notes/index.html", "image": "media/trombone-sliding-notes.jpg", "alt": "\uae08\ube5b \ud2b8\ub86c\ubcf8\uacfc \uae38\uac8c \ubed7\uc740 \uc2ac\ub77c\uc774\ub4dc\ub97c \ubcf4\uc5ec \uc8fc\ub294 AI \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\ud2b8\ub86c\ubcf8 \uc5f0\uc8fc\uc790\ub294 \uc65c \ud314\uc744 \uae38\uac8c \ubed7\uc744\uae4c \uc18c\ub9ac \uc0ac\uc774\ub97c \ubbf8\ub044\ub7ec\uc9c0\ub294 \uae08\uad00\uc545\uae30 \uc55e\uc73c\ub85c \ub098\uac14\ub2e4 \ub3cc\uc544\uc624\ub294 \uae34 \uad00. \ud2b8\ub86c\ubcf8\uc758 \ub208\uc5d0 \ub744\ub294 \ub3d9\uc791\uc740 \uc74c\uc744 \uace0\ub974\ub294 \uc77c\uc774\uae30\ub3c4 \ud569\ub2c8\ub2e4. Music \ubb38\ud654 \uc624\ucf00\uc2a4\ud2b8\ub77c\uc5d0\uc11c \ud2b8\ub86c\ubcf8\uc744 \ucc3e\ub294 \uc26c\uc6b4 \ubc29\ubc95\uc774 \uc788\ub2e4. \uc5f0\uc8fc\uc790\uc758 \ud314\uc774 \uc55e\ub4a4\ub85c \uae38\uac8c \uc6c0\uc9c1\uc774\ub294 \uc790\ub9ac\ub97c \ubcf4\ub294 \uac83\uc774\ub2e4. \ubc88\uca4d\uc774\ub294 \uad00 \ud55c\ucabd\uc774 \ub098\uac14\ub2e4\uac00 \ub4e4\uc5b4\uc628\ub2e4. \ucc98\uc74c \ubcf4\uba74 \uc545\uae30\ub97c \ub298\uc600\ub2e4 \uc904\uc600\ub2e4 \ud558\ub294 \ubb18\uae30 \uac19\ub2e4. \ud558\uc9c0\ub9cc \uc5f0\uc8fc\uc790\ub294 \uadf8 \uc6c0\uc9c1\uc784\uc73c\ub85c \uc74c\uc744 \uace0\ub974\uace0 \uc788\ub2e4. \ud544\ud558\ubaa8\ub2c8\uc544 \uc624\ucf00\uc2a4\ud2b8\ub77c\ub294 \ud2b8\ub86c\ubcf8\uc758 \uc2ac\ub77c\uc774\ub4dc\ub97c \uc74c\ub192\uc774\ub97c \uc120\ud0dd\ud558\ub294 \uc7a5\uce58\ub85c \uc124\uba85\ud55c\ub2e4. \ud2b8\ub86c\ubcf8\uc758 \ub208\uc5d0 \ub744\ub294 \ubd80\ubd84\uc740 \uae38\uac8c \uc811\ud600 \ub3cc\uc544\uc624\ub294 \uad00\uc774\ub2e4. \uadf8 \uad00\uc758 \uc77c\ubd80\ub97c \ubbf8\ub044\ub7ec\ub728\ub9ac\ub294 \uc2ac\ub77c\uc774\ub4dc\uac00 \uc545\uae30 \ubc14\uae65\uc73c\ub85c \uae38\uac8c \ubed7\uc5b4 \uc788\ub2e4. \uc545\uae30\ub97c \ucc98\uc74c \ubcf4\ub294 \uc0ac\ub78c\ub3c4 \uc6c0\uc9c1\uc774\ub294 \uacf3\uc744 \uc27d\uac8c \ucc3e\uc744 \uc218 \uc788\ub2e4. \ubc84\ud2bc\uc744 \uc9e7\uac8c \ub204\ub974\ub294 \ub3d9\uc791\uacfc \ub2ec\ub9ac, \uc2ac\ub77c\uc774\ub4dc\uc758 \uc774\ub3d9\uc740 \uac1d\uc11d\uc5d0\uc11c\ub3c4 \ubcf4\uc778\ub2e4. \ud314\uc774 \ud070 \ub3d9\uc791\uc744 \ud558\uc9c0\ub9cc \ubaa9\uc801\uc740 \uc12c\uc138\ud558\ub2e4. \uc5f0\uc8fc\uc790\ub294 \uc545\uae30\uc758 \uae38\uc774\ub97c \ubc14\uafb8\uba70 \ud544\uc694\ud55c \uc18c\ub9ac\ub97c \ucc3e\uc544\uac04\ub2e4. \uadf8\ub798\uc11c \ud2b8\ub86c\ubcf8\uc740 \uc18c\ub9ac\ub97c \ub4e3\ub294 \uc7ac\ubbf8\uc640 \ub3d9\uc791\uc744 \ubcf4\ub294 \uc7ac\ubbf8\uac00 \ud568\uaed8 \uc788\ub294 \uc545\uae30\ub2e4. \uc6c0\uc9c1\uc784\uc744 \ud55c \ubc88 \uc54c\uc544\ub450\uba74 \ub9ce\uc740 \uc545\uae30\uac00 \ubaa8\uc778 \uc7a5\uba74\uc5d0\uc11c\ub3c4 \ub2e4\uc2dc \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \ud2b8\ub86c\ubcf8\uc740 \uc74c \uc0ac\uc774\ub97c \ubbf8\ub044\ub7ec\uc9c0\ub4ef \uc787\ub294 \uc18c\ub9ac\ub85c\ub3c4 \uc720\uba85\ud558\ub2e4. \u2018\uae00\ub9ac\uc0b0\ub3c4\u2019\ub77c\uace0 \ubd80\ub974\ub294 \ud6a8\uacfc\ub2e4. \ub2e8\uc5b4\ub97c \uc678\uc6b0\uae30\ubcf4\ub2e4 \uc18c\ub9ac\uac00 \uc544\ub798\uc704\ub85c \ucb49 \ubbf8\ub044\ub7ec\uc9c0\ub294 \ub290\ub08c\uc744 \ub5a0\uc62c\ub9ac\uba74 \uc27d\ub2e4. \ud544\ud558\ubaa8\ub2c8\uc544\ub294 \uc774 \ud2b9\uc9d5\uc774 \ub9cc\ud654\uc758 \uc74c\uc545\uc5d0\uc11c\ub3c4 \uc624\ub7ab\ub3d9\uc548 \ud65c\uc6a9\ub418\uc5c8\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \uc6b0\uc2a4\uaf5d\uc2a4\ub7ec\uc6b4 \ub3d9\uc791\uc5d0 \ub9de\ucdb0 \uc18c\ub9ac\uac00 \ud718\uc5b4\uc9c0\ub294 \ub4ef\ud55c \uc7a5\uba74\uc744 \ub5a0\uc62c\ub9ac\uba74, \ub0af\uc120 \uc545\uae30\uac00 \uc870\uae08 \uc775\uc219\ud574\uc9c4\ub2e4. \uadf8\ub7ec\ub098 \ud2b8\ub86c\ubcf8\uc744 \uc6c3\uae34 \uc18c\ub9ac\ub9cc \ub0b4\ub294 \uc545\uae30\ub85c \uae30\uc5b5\ud558\uba74 \uc544\uc27d\ub2e4. \uac19\uc740 \uc548\ub0b4\ub294 \ud2b8\ub86c\ubcf8\uc774 \uc544\uc8fc \ubd80\ub4dc\ub7ec\uc6b4 \uc120\uc728\ub3c4 \uc5f0\uc8fc\ud560 \uc218 \uc788\ub2e4\uace0 \uac15\uc870\ud55c\ub2e4. \ud55c \uac00\uc9c0 \ud6a8\uacfc\uac00 \uc778\uc0c1\uc801\uc774\ub77c\uace0 \uadf8 \uc545\uae30\uc758 \ubaa8\ub4e0 \ud45c\uc815\uc774 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc2ac\ub77c\uc774\ub4dc\ub97c \uc6c0\uc9c1\uc774\ub294 \uc77c\uc740 \ub208\uc5d0 \ubcf4\uc774\ub294 \uad00\uc758 \uae38\uc774\ub97c \ubc14\uafb8\ub294 \ud589\ub3d9\uc774\ub2e4. \uc5f0\uc8fc\uc790\ub294 \uc785\uacfc \ud638\ud761\uc744 \uc0ac\uc6a9\ud558\uba74\uc11c \uadf8 \uae38\uc774\ub3c4 \uc870\uc808\ud55c\ub2e4. \uadf8\ub798\uc11c \ud314\uc758 \uc6c0\uc9c1\uc784\ub9cc \ubcf4\uace0 \uc5f0\uc8fc \uc804\uccb4\uac00 \ub2e8\uc21c\ud55c \ubc00\uace0 \ub2f9\uae30\uae30\ub77c\uace0 \uc0dd\uac01\ud560 \uc218\ub294 \uc5c6\ub2e4. \ud070 \ub3d9\uc791\uacfc \uc815\uad50\ud55c \uc18c\ub9ac\uc758 \uc120\ud0dd\uc774 \ud568\uaed8 \uc774\ub8e8\uc5b4\uc9c4\ub2e4. \uac1d\uc11d\uc5d0\uc11c \ubcf4\uc774\ub294 \ud589\ub3d9\uc740 \uadf8 \uac00\uc6b4\ub370 \ub208\uc5d0 \uc798 \ub744\ub294 \ubd80\ubd84\uc774\ub2e4. \uc774 \uad00\uacc4\ub97c \uc54c\uba74 \ud2b8\ub86c\ubcf8\uc744 \ucc98\uc74c \ubcf4\ub294 \uc0ac\ub78c\ub3c4 \ubb34\uc5c7\uc744 \uad00\ucc30\ud560\uc9c0 \uc54c\uac8c \ub41c\ub2e4. \uc190\uc774 \uba40\ub9ac \ub098\uac08 \ub54c\uc640 \uac00\uae4c\uc6cc\uc9c8 \ub54c \uc18c\ub9ac\uac00 \uc5b4\ub5bb\uac8c \ub2ec\ub77c\uc9c0\ub294\uc9c0 \ub4e4\uc5b4 \ubcf4\uc790. \ub2e4\ub9cc \ubaa8\ub4e0 \uc74c\ub192\uc774\ub97c \ud314\uc758 \uac70\ub9ac \ud558\ub098\ub85c \uc77c\ub300\uc77c \ub300\uc751\uc2dc\ud0a4\uac70\ub098 \uc0ac\uc9c4 \ud55c \uc7a5\uc5d0\uc11c \ud2b9\uc815 \uc74c\uc744 \uc54c\uc544\ub9de\ud788\ub824 \ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc2e4\uc81c \uc5f0\uc8fc\uc5d0\ub294 \ub3d9\uc2dc\uc5d0 \uc791\uc6a9\ud558\ub294 \ub2e4\ub978 \uc870\uc808\uc774 \uc788\ub2e4. \uc2ac\ub77c\uc774\ub4dc\uac00 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc5b8\uc81c\ub098 \uc18c\ub9ac\ub97c \ubbf8\ub044\ub7ec\ub728\ub9b0\ub2e4\ub294 \uc8fc\uc7a5\uc740 \ub2e4\ub974\ub2e4. \uae00\ub9ac\uc0b0\ub3c4\ub294 \uc774 \uc545\uae30\uc758 \uc778\uc0c1\uc801\uc778 \ud6a8\uacfc\uc774\uc9c0\ub9cc \uace1 \uc804\uccb4\uac00 \uadf8 \ud6a8\uacfc\ub85c\ub9cc \uc774\ub8e8\uc5b4\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc120\uc728\uc758 \uc74c\ub4e4\uc744 \ub610\ub837\ud558\uac8c \ub098\ub204\uc5b4 \ub0b4\uac70\ub098 \uae38\uac8c \uc774\uc5b4 \ub178\ub798\ud558\ub294 \uc21c\uac04\ub3c4 \uc788\ub2e4. \ud558\ub098\uc758 \ud2b9\uc9d5\uc744 \uc54c\uc544\ubcf8 \ub4a4\uc5d0\ub294 \uadf8 \ud2b9\uc9d5\uc774 \uc4f0\uc774\uc9c0 \uc54a\ub294 \uc21c\uac04\uc744 \ub4e4\uc5b4\ubcf4\ub294 \uac83\ub3c4 \uc7ac\ubbf8\uc788\ub2e4. \ub9cc\ud654 \uc74c\uc545\uc758 \uc775\uc0b4\uc2a4\ub7ec\uc6b4 \uc18c\ub9ac\ub97c \ub5a0\uc62c\ub838\ub2e4\uba74 \ub2e4\uc74c\uc5d0\ub294 \ubd80\ub4dc\ub7ec\uc6b4 \uc120\uc728\uc744 \ucc3e\uc544\ubcf4\uc790. \uac19\uc740 \uc545\uae30\uac00 \ub2e4\ub978 \ubb38\uc7a5 \uc18d\uc5d0\uc11c \uc5b4\ub5a4 \uc5ed\ud560\uc744 \ud558\ub294\uc9c0 \ube44\uad50\ud558\ub294 \uac83\uc774\ub2e4. \uadf8\ub9bc \uc18d \uc778\ubb3c\uc758 \uac78\uc74c\uc5d0 \ub9de\ucd98 \ud6a8\uacfc\uc640 \ud569\uc8fc \uc548\uc5d0\uc11c \uae38\uac8c \ubd80\ub294 \uc74c\uc740 \uc11c\ub85c \ub2e4\ub978 \ud45c\uc815\uc744 \ub9cc\ub4e0\ub2e4. \uc545\uae30\uc758 \ub2a5\ub825\uc740 \uac00\uc7a5 \uc720\uba85\ud55c \uc18c\ub9ac \ud558\ub098\ubcf4\ub2e4 \ub113\ub2e4. \ud63c\uc790 \ud55c \uc74c\uc744 \ub0b4\ub294 \uacbd\uc6b0\uc640 \ub2e4\ub978 \uc545\uae30\ub4e4 \uc0ac\uc774\uc5d0 \ub4e4\uc5b4\uac00\ub294 \uacbd\uc6b0\uc5d0\ub294 \ub4e4\ub9ac\ub294 \uad00\uacc4\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \uc74c\uc0c9\uc774 \ube44\uc2b7\ud55c \uc18c\ub9ac\ub07c\ub9ac \uacb9\uce58\uae30\ub3c4 \ud558\uace0 \ub2e4\ub978 \uc18c\ub9ac\ub97c \ubc1b\uccd0 \uc8fc\uae30\ub3c4 \ud55c\ub2e4. \ud2b9\uc815 \uc5f0\uc8fc\uc5d0\uc11c \ubb34\uc5c7\uc744 \ub9e1\ub294\uc9c0\ub294 \uc545\ubcf4\uc640 \uc2e4\uc81c \uc18c\ub9ac\ub97c \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \ub2e4\ub9cc \ub298 \uc804\uba74\uc5d0\uc11c \ud070 \uc18c\ub9ac\ub9cc \ub0b4\ub294 \uc545\uae30\ub85c \uae30\uc5b5\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ud544\ud558\ubaa8\ub2c8\uc544\ub294 \ub974\ub124\uc0c1\uc2a4 \uc2dc\ub300 \uad50\ud68c \ud569\uc8fc\uc640 \uc774\uc5b4\uc9c0\ub294 \uc5ed\uc0ac\ub3c4 \uc18c\uac1c\ud55c\ub2e4. \uc9c0\uae08\uc758 \uc624\ucf00\uc2a4\ud2b8\ub77c \uc548\uc5d0\uc11c \ub9cc\ub098\ub294 \uc545\uae30\uac00 \uc5ec\ub7ec \uc0ac\uc6a9\uc758 \uc2dc\uac04\uc744 \uac70\uccd0 \uc654\ub2e4\ub294 \ub2e8\uc11c\ub2e4. \uacfc\uac70\uc758 \ubaa8\ub4e0 \ud2b8\ub86c\ubcf8\uc774 \uc624\ub298\uc758 \ubaa8\uc591\uacfc \ub611\uac19\uc558\ub2e4\uace0 \ub2e8\uc815\ud558\uae30\ubcf4\ub2e4 \uc5b4\ub5a4 \uc790\ub9ac\uc5d0\uc11c \uc5b4\ub5a4 \uc18c\ub9ac\ub85c \uc4f0\uc600\ub294\uc9c0 \ubb3b\ub294 \uc785\uad6c\ub85c \ubcfc \uc218 \uc788\ub2e4. \uc5f0\uc8fc \uc601\uc0c1\uc744 \ud55c \ubc88\uc740 \ub208\uc744 \ub5bc\uace0 \ub4e3\uace0, \ub2e4\uc74c\uc5d0\ub294 \ud314\uc758 \uc6c0\uc9c1\uc784\uc744 \ubcf4\uba70 \ub4e4\uc5b4 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc775\uc0b4\uc2a4\ub7fd\uac8c\ub9cc \ub4e4\ub9ac\ub358 \uc18c\ub9ac\uac00 \uc870\uc2ec\uc2a4\ub7fd\uac8c \uc774\uc5b4\uc9c0\ub294 \uc120\uc728\uc77c \uc218 \uc788\uace0, \ud070 \ub3d9\uc791\uc774 \ub73b\ubc16\uc5d0 \uc870\uc6a9\ud55c \uad6c\uac04\uc5d0\uc11c\ub3c4 \ud544\uc694\ud560 \uc218 \uc788\ub2e4. \ub3c4\uad6c\uc758 \uad6c\uc870\ub97c \uc870\uae08 \uc544\ub294 \uc77c\uc740 \uac10\uc0c1\uc744 \ub354 \uc5b4\ub835\uac8c \ud558\uae30\ubcf4\ub2e4 \uc8fc\uc758\ub97c \ub193\uc744 \uc790\ub9ac\ub97c \ub298\ub9b4 \uc218 \uc788\ub2e4. \uc774 \uae00\uc758 \uc0bd\ud654\ub294 \uc5f0\uc8fc\uc758 \uac1c\ub150\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc704\ud55c \uadf8\ub9bc\uc774\uba70 \uc815\ud655\ud55c \uc5f0\uc8fc \uc790\uc138\ub97c \uac00\ub974\uce58\ub294 \ub3c4\uba74\uc740 \uc544\ub2c8\ub2e4. \uc2e4\uc81c \uc190\uacfc \ud638\ud761\uc758 \uc0ac\uc6a9\uc740 \uc5f0\uc8fc\uc790\uc758 \uc2dc\uc5f0\uacfc \uad50\uc721 \uc790\ub8cc\ub85c \ud655\uc778\ud560 \uc601\uc5ed\uc774\ub2e4. \uc6b0\ub9ac\ub294 \uad00\ub78c\uc790\ub85c\uc11c \uc18c\ub9ac\uc640 \uc6c0\uc9c1\uc784\uc758 \uad00\uacc4\ub97c \ubc1c\uacac\ud558\ub294 \uac83\uc73c\ub85c\ub3c4 \ucda9\ubd84\ud558\ub2e4. \uae38\uac8c \ubed7\ub294 \ud314\uc774 \uc5b4\ub5a4 \uc74c\uc545\uc801 \ubb38\uc7a5\uc744 \ub9cc\ub4dc\ub294\uc9c0 \uc0c8\ub86d\uac8c \ub4e4\uc744 \uc218 \uc788\ub2e4. \ud2b8\ub86c\ubcf8\uc740 \uc624\ucf00\uc2a4\ud2b8\ub77c\uac00 \uc6c5\uc7a5\ud574\uc9c0\ub294 \uc21c\uac04\uc5d0 \ud798\uc744 \ubcf4\ud0dc\uae30\ub3c4 \ud55c\ub2e4. \uadf8\ub798\uc11c \ud06c\uace0 \uac15\ud55c \uc18c\ub9ac\ubd80\ud130 \uc5f0\uc0c1\ud558\uae30 \uc27d\ub2e4. \ud558\uc9c0\ub9cc \ud544\ud558\ubaa8\ub2c8\uc544\ub294 \ub974\ub124\uc0c1\uc2a4 \uc2dc\ub300\uc5d0 \uad50\ud68c\uc5d0\uc11c \ud2b8\ub86c\ubcf8 \ud569\uc8fc\ub85c \uc5f0\uc8fc\ud558\ub358 \uc12c\uc138\ud55c \uc74c\uc545\ub3c4 \uc18c\uac1c\ud55c\ub2e4. \ubb34\ub300\uc5d0\uc11c \ubcf4\uc774\ub294 \uae34 \uad00\uacfc \ud798\ucc2c \uc790\uc138\ub9cc\uc73c\ub85c \uc18c\ub9ac\uc758 \uc131\uaca9\uc744 \ud558\ub098\ub85c \uc815\ud558\uae30\ub294 \uc5b4\ub835\ub2e4. \ubd80\ub4dc\ub7fd\uac8c \uc774\uc5b4\uc9c0\ub294 \uc120\uc728\uc744 \ub4e4\uc744 \ub54c\uc5d0\ub3c4 \uac19\uc740 \uc2ac\ub77c\uc774\ub4dc\uac00 \uc6c0\uc9c1\uc778\ub2e4. \ub2e4\uc74c\uc5d0 \uacf5\uc5f0 \uc601\uc0c1\uc744 \ubcfc \ub54c\ub294 \ud314\uc774 \uc55e\uc73c\ub85c \ub098\uc624\ub294 \uc21c\uac04\uacfc \uadf8\ub54c\uc758 \uc18c\ub9ac\ub97c \ud568\uaed8 \ub530\ub77c\uac00 \ubcf4\uc790. \ud07c\uc9c1\ud55c \ub3d9\uc791 \uc18d\uc5d0\uc11c \uc74c\uc744 \uace0\ub974\ub294 \uc77c\uc774 \uc0dd\uac01\ubcf4\ub2e4 \uc870\uc6a9\ud558\uace0 \uc138\ubc00\ud558\uac8c \uc774\ub8e8\uc5b4\uc9c0\uace0 \uc788\ub2e4."}, {"id": "van-eyck-rolin-window", "title": "\ub864\ub7ad \uc7ac\uc0c1\uc758 \uc131\ubaa8 \u2014 \uc791\uc740 \ubc29 \ub108\uba38\uc5d0 \ub3c4\uc2dc\uac00 \ud3bc\uccd0\uc9c4\ub2e4", "summary": "\uc580 \ubc18 \uc5d0\uc774\ud06c\uc758 \uadf8\ub9bc\uc5d0\uc11c \uac00\uae4c\uc6b4 \uc778\ubb3c\uacfc \uba3c \uc138\uacc4\uac00 \ub9cc\ub098\ub294 \ubc29\uc2dd\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Art", "url": "stories/van-eyck-rolin-window/index.html", "image": "media/van-eyck-rolin-window.jpg", "alt": "\uc580 \ubc18 \uc5d0\uc774\ud06c\uc758 \ub864\ub7ad \uc7ac\uc0c1\uc758 \uc131\ubaa8. \uae30\ub3c4\ud558\ub294 \ub0a8\uc131\uacfc \uc131\ubaa8\uc790, \ucc9c\uc0ac, \ucc3d\ubb38 \ub108\uba38\uc758 \ub3c4\uc2dc\uc640 \uac15\uc774 \ubcf4\uc785\ub2c8\ub2e4.", "text": "\ub864\ub7ad \uc7ac\uc0c1\uc758 \uc131\ubaa8 \u2014 \uc791\uc740 \ubc29 \ub108\uba38\uc5d0 \ub3c4\uc2dc\uac00 \ud3bc\uccd0\uc9c4\ub2e4 \uae30\ub3c4\ud558\ub294 \ud6c4\uc6d0\uc790\uc640 \uc131\ubaa8\uc790, \ucc3d\ubc16 \ud48d\uacbd\uc744 \ud568\uaed8 \uc77d\uae30 \uc580 \ubc18 \uc5d0\uc774\ud06c\uc758 \uadf8\ub9bc\uc5d0\uc11c \uac00\uae4c\uc6b4 \uc778\ubb3c\uacfc \uba3c \uc138\uacc4\uac00 \ub9cc\ub098\ub294 \ubc29\uc2dd\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Art \ubb38\ud654 \uc67c\ucabd\uc5d0\ub294 \ud654\ub824\ud55c \uc637\uc744 \uc785\uc740 \ub0a8\uc790\uac00 \uc190\uc744 \ubaa8\uc73c\uace0, \uc624\ub978\ucabd\uc5d0\ub294 \uc544\uc774\ub97c \uc548\uc740 \uc5ec\uc778\uc774 \uc549\uc544 \uc788\ub2e4. \ub4a4\uc5d0\uc11c\ub294 \ucc9c\uc0ac\uac00 \uc655\uad00\uc744 \ub4e4\uace0 \uc788\ub2e4. \uadf8\ub7f0\ub370 \uc778\ubb3c\ub4e4\ub9cc \ubcf4\uace0 \ub05d\ub0b4\uae30\uc5d0\ub294 \ucc3d \ub108\uba38\uc758 \ud48d\uacbd\uc774 \ub108\ubb34 \uba40\ub9ac \ud3bc\uccd0\uc9c4\ub2e4. \ubc29 \uc548\uacfc \ubc14\uae65\uc758 \ub3c4\uc2dc\uac00 \ud55c \ud654\uba74\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uc580 \ubc18 \uc5d0\uc774\ud06c\uc758 \u3008\ub864\ub7ad \uc7ac\uc0c1\uc758 \uc131\ubaa8\u3009\ub2e4. \ub0af\uc120 \uc774\ub984\uacfc \uc885\uad50\uc801 \uc778\ubb3c \ub54c\ubb38\uc5d0 \uc5b4\ub835\uac8c \ub290\uaef4\uc9c4\ub2e4\uba74, \uba3c\uc800 \uc55e\uc758 \uc0ac\ub78c\ub4e4\uacfc \ub4a4\uc758 \uac15\uc744 \ubc88\uac08\uc544 \ubcf4\uc790. \uadf8\ub9bc\uc740 \uac00\uae4c\uc6b4 \uad00\uacc4\uc640 \ub113\uc740 \uc138\uacc4\ub97c \ud568\uaed8 \ubcf4\ub3c4\ub85d \ub9cc\ub4e0\ub2e4. \uc67c\ucabd\uc5d0\uc11c \uae30\ub3c4\ud558\ub294 \uc778\ubb3c\uc740 \ub864\ub7ad \uc7ac\uc0c1\uc73c\ub85c \uc2dd\ubcc4\ub41c\ub2e4. \uc774 \uc791\ud488\uc740 \uc131\ubaa8\uc790\uc640 \uae30\uc99d\uc790\uc758 \ubaa8\uc2b5\uc744 \ud568\uaed8 \ub2f4\uc740 \ud68c\ud654\ub2e4. \uc885\uad50\uc801 \ub300\uc0c1\ub9cc\uc744 \ub530\ub85c \uadf8\ub9ac\ub294 \ub300\uc2e0, \uadf8 \uc55e\uc5d0 \uae30\ub3c4\ud558\ub294 \uc2e4\uc81c \uc0ac\ud68c\uc758 \uc778\ubb3c\uc774 \ud568\uaed8 \ub098\ud0c0\ub09c\ub2e4. \ucc98\uc74c\ubd80\ud130 \uae30\uc99d\uc790\uc758 \ubaa8\ub4e0 \uacbd\ub825\uacfc \uc9c0\uc704\ub97c \uc678\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \uc774 \uadf8\ub9bc \uc548\uc5d0\ub294 \uc2e0\uc559\uc758 \uc138\uacc4\uc640 \uadf8 \uadf8\ub9bc\uc744 \ub9c8\ub828\ud55c \uc0ac\ub78c\uc758 \uc138\uacc4\uac00 \ub3d9\uc2dc\uc5d0 \ub4e4\uc5b4 \uc788\ub2e4\ub294 \uc810\uc744 \uc54c\uc544 \ub450\uba74 \uc88b\ub2e4. \uc778\ubb3c\uc758 \ubc30\uce58\ub97c \ubcf4\uba74 \ub2e8\uc21c\ud55c \uc131\ubaa8\uc790\ud654\uc640\ub294 \ub2e4\ub978 \uad00\uacc4\uac00 \ubcf4\uc778\ub2e4. \uc624\ub978\ucabd\uc740 \uc131\ubaa8 \ub9c8\ub9ac\uc544\uc640 \uc544\uae30 \uc608\uc218\ub2e4. \ucc9c\uc0ac\uac00 \uc655\uad00\uc744 \ub4e4\uace0 \ub098\ud0c0\ub098\ub294 \ubaa8\uc2b5\uc740 \ud654\uba74\uc774 \uc77c\uc0c1\uc801\uc778 \ubaa8\uc790 \ucd08\uc0c1\ub9cc\uc740 \uc544\ub2c8\ub77c\ub294 \ud45c\uc9c0\ub2e4. \uc544\uc774\uc640 \uc5b4\uba38\ub2c8\ub77c\ub294 \uce5c\uc219\ud55c \uad00\uacc4 \uc18d\uc5d0 \uae30\ub3c5\uad50 \ud68c\ud654\uc758 \uc758\ubbf8\uac00 \uacb9\uce5c\ub2e4. \uc774\ub984\uc744 \uc870\uae08 \uc54c\uace0 \ub098\uba74 \ub450 \uc0ac\ub78c\uc758 \uc790\uc138\uc640 \ub0a8\uc790\ub97c \ud5a5\ud55c \uad00\uacc4\ub97c \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \uc885\uad50\uc801 \uc9c0\uc2dd\uc774 \uac10\uc0c1\uc744 \ub300\uc2e0\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \ub208\uc55e\uc758 \ubab8\uc9d3\uc744 \uc77d\ub294 \ub2e8\uc11c\ub97c \uc8fc\ub294 \uac83\uc774\ub2e4. \uc655\uad00\uacfc \uc637, \uc190\uc758 \ubc29\ud5a5\uc774 \ubb34\uc5c7\uc744 \ub354 \ubcf4\uac8c \ud558\ub294\uc9c0 \ucc9c\ucc9c\ud788 \ub530\ub77c\uac00 \ubcf4\uc790. \uae30\ub3c4\ud558\ub294 \ub0a8\uc131\uacfc \uc131\ubaa8\uc790\ub294 \uc11c\ub85c \ub9c8\uc8fc\ud55c \ub4ef \uac19\uc740 \ud68c\ub791 \uc548\uc5d0 \ub193\uc5ec \uc788\ub2e4. \ud06c\uae30\uc640 \uac70\ub9ac \ub54c\ubb38\uc5d0 \uad00\uac1d\uc740 \ub450 \uc138\uacc4\uac00 \uc544\uc8fc \uba40\ub9ac \ub5a8\uc5b4\uc838 \uc788\ub2e4\uace0\ub9cc \ub290\ub07c\uc9c0 \uc54a\ub294\ub2e4. \uc2e0\uc559\uc758 \ub300\uc0c1\uacfc \uae30\ub3c4\ud558\ub294 \uc0ac\ub78c\uc774 \uac00\uae4c\uc774 \ub9cc\ub098\ub294 \ubc29\uc2dd\uc73c\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc2e4\uc81c\ub85c \uadf8\ub4e4\uc774 \uac19\uc740 \ubc29\uc5d0\uc11c \ub9cc\ub0ac\ub2e4\ub294 \uc5ed\uc0ac\uc801 \uc7a5\uba74\uc744 \uae30\ub85d\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \ud68c\ud654\uac00 \uc11c\ub85c \ub2e4\ub978 \ucc28\uc6d0\uc758 \uc778\ubb3c\uacfc \uc758\ubbf8\ub97c \ud55c \uacf5\uac04\uc5d0 \uad6c\uc131\ud558\ub294 \uac83\uc774\ub2e4. \ud654\uba74\uc744 \uc0ac\uc2e4\uc758 \uc0ac\uc9c4\uc73c\ub85c \uc624\ud574\ud558\uc9c0 \uc54a\uc744 \ub54c \uc774\ub7f0 \ubc30\uce58\uac00 \uc8fc\ub294 \ud798\ub3c4 \ub354 \uc798 \uc774\ud574\ub41c\ub2e4. \uac00\uae4c\uc6b4 \uc778\ubb3c\ub4e4 \uc0ac\uc774\uc640 \uc544\ub798\uc5d0\ub294 \ubc14\ub2e5\uc758 \ubb34\ub2ac\uac00 \uc788\uace0, \ub4a4\uc5d0\ub294 \uae30\ub465\uacfc \uc544\uce58\uac00 \uc774\uc5b4\uc9c4\ub2e4. \uc774\ub7f0 \uad6c\uc870\ub97c \ub530\ub77c\uac00\uba74 \ubc29\uc774 \ud3c9\ud3c9\ud55c \ubb34\ub2ac\ub85c \ub05d\ub098\uc9c0 \uc54a\uace0 \uae4a\uc774\ub97c \uac00\uc9c4 \uacf5\uac04\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \uc0ac\ub78c\uc744 \ub458\ub7ec\uc2fc \uac74\ucd95\ub3c4 \uac10\uc0c1\uc758 \uc911\uc694\ud55c \ubd80\ubd84\uc774\ub2e4. \ubaa8\ub4e0 \uc7a5\uc2dd\uc744 \uc815\ud655\ud788 \uc7ac\uc5b4\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc2dc\uc120\uc774 \uc5b4\ub514\uc5d0\uc11c \uba48\ucd94\uace0 \uc5b4\ub514\ub85c \uba40\uc5b4\uc9c0\ub294\uc9c0 \ub530\ub77c\uac00 \ubcf4\uba74 \ub41c\ub2e4. \uc778\ubb3c\uc758 \ubab8\uc774 \ud070 \uc790\ub9ac\ub97c \ucc28\uc9c0\ud558\uba74\uc11c\ub3c4 \ucc3d\ubc16\uc73c\ub85c \ub208\uc744 \uc5f4\uc5b4 \ub450\ub294 \ubc29\uc2dd\uc774, \uac00\uae4c\uc6b4 \uc7a5\uba74\uacfc \uba3c \ud48d\uacbd\uc744 \ud55c\uaebc\ubc88\uc5d0 \ubcf4\uac8c \ub9cc\ub4e0\ub2e4. \ub4a4\ucabd\uc758 \uc791\uc740 \uc815\uc6d0\uc744 \uc9c0\ub098\uba74 \uac15\uacfc \ub2e4\ub9ac, \uba40\ub9ac\uc758 \uac74\ubb3c\ub4e4\uc774 \ubcf4\uc778\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc0ac\uc18c\ud55c \ubc30\uacbd\ucc98\ub7fc \ub290\uaef4\uc84c\ub358 \ubd80\ubd84\uc5d0 \uc138\uacc4\uac00 \ud558\ub098 \ub354 \ub4e4\uc5b4 \uc788\ub294 \uc148\uc774\ub2e4. \uac00\uae4c\uc774 \ud655\ub300\ud574 \ubcf4\uace0 \ub2e4\uc2dc \uc804\uccb4\ub85c \ub3cc\uc544\uc624\uba74 \uadf8\ub9bc\uc774 \ud488\uc740 \uac70\ub9ac\uc758 \ucc28\uc774\uac00 \ub290\uaef4\uc9c4\ub2e4. \uc5b4\ub5a4 \uc2e4\uc81c \ub3c4\uc2dc\ub97c \uadf8\ub300\ub85c \uc62e\uacbc\ub294\uc9c0 \uc774 \uae00\uc5d0\uc11c \ud55c \uacf3\uc73c\ub85c \ud655\uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc9c0\uae08 \ub208\uc73c\ub85c \ud655\uc778\ud558\ub294 \uac83\uc740 \uc0ac\ub78c\uc774 \uc788\ub294 \ubc29\uacfc \uc774\uc5b4\uc9c0\ub294 \ud48d\uacbd\uc774\ub2e4. \uc815\ud655\ud55c \uc9c0\uba85\uc744 \ub9de\ud788\ub294 \uc77c\ub9cc\uc774 \uac10\uc0c1\uc758 \ubaa9\ud45c\ub294 \uc544\ub2c8\ub2e4. \uc791\uc740 \ud654\uba74 \uc548\uc5d0\uc11c \uc5bc\ub9c8\ub098 \ub113\uc740 \uacf3\uc744 \ubcf4\uac8c \ub418\ub294\uc9c0 \ub290\uaef4\ub3c4 \uc88b\ub2e4. \ub0a8\uc790\uc758 \ubb34\ub2ac \uc788\ub294 \uc637\uacfc \uc131\ubaa8\uc758 \ub113\uc740 \ubd89\uc740 \uc637, \ucc9c\uc0ac\uc758 \uc655\uad00\uc740 \uac00\uae4c\uc6b4 \uacf3\uc5d0\uc11c \uc2dc\uc120\uc744 \ubd99\uc7a1\ub294\ub2e4. \uac15\uacfc \ub3c4\uc2dc\uc758 \uc791\uc740 \ubaa8\uc2b5\uc740 \ub354 \uba40\ub9ac \ub208\uc744 \uc6c0\uc9c1\uc774\uac8c \ud55c\ub2e4. \uc138\ubd80\uac00 \ub9ce\ub2e4\ub294 \uc0ac\uc2e4\ubcf4\ub2e4 \uadf8 \uc138\ubd80\ub4e4\uc774 \uc11c\ub85c \ub2e4\ub978 \uac70\ub9ac\ub97c \ub9cc\ub4e0\ub2e4\ub294 \uc810\uc5d0 \uc8fc\ubaa9\ud574 \ubcf4\uc790. \ubc18 \uc5d0\uc774\ud06c\ub97c \uc720\ud654\ub97c \ud63c\uc790 \ucc98\uc74c \ubc1c\uba85\ud55c \uc0ac\ub78c\uc774\ub77c\uace0 \uac04\ub2e8\ud788 \uc815\ub9ac\ud558\uc9c0\ub294 \ub9d0\uc790. \uc774 \uc791\ud488\uc5d0\uc11c \uc9c1\uc811 \ubcfc \uc218 \uc788\ub294 \uac83\uc740 \uc0c9\uacfc \ubb3c\uc9c8\uc758 \ud45c\ud604, \uc791\uc740 \uac83\ub4e4\uc744 \ud654\uba74\uc758 \uacf5\uac04 \uc548\uc5d0 \ub193\uc740 \uc19c\uc528\ub2e4. \uc720\uba85\ud55c \ubc1c\uba85 \uc774\uc57c\uae30\ubcf4\ub2e4 \uc2e4\uc81c\ub85c \uadf8\ub824\uc9c4 \uad00\uacc4\ub97c \ubcf4\ub294 \ud3b8\uc774 \uadf8\ub9bc\uc5d0 \ub354 \uac00\uae4c\uc774 \uac04\ub2e4. \uae30\ub3c4\ud558\ub294 \ud6c4\uc6d0\uc790\uac00 \uc790\uc2e0\uc758 \ubaa8\uc2b5\uc744 \uc885\uad50\uc801 \uc7a5\uba74\uc5d0 \ud568\uaed8 \ub0a8\uae34\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ud765\ubbf8\ub86d\ub2e4. \uac1c\uc778\uc758 \uc2e0\uc559\ubfd0 \uc544\ub2c8\ub77c \uc0ac\ud68c\uc801 \uc704\uce58\uc640 \uc790\uae30 \ubaa8\uc2b5\uc744 \ubcf4\uc774\ub294 \ubc29\uc2dd\ub3c4 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ub2e4\ub9cc \uadf8 \ub9c8\uc74c\uc18d \ub3d9\uae30\ub97c \uc624\uc9c1 \uacfc\uc2dc\ub098 \uc624\uc9c1 \uc21c\uc218\ud55c \ubbff\uc74c \ud558\ub098\ub85c \ub2e8\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uadf8\ub9bc\uc744 \ubcfc \ub54c\ub3c4 \ub458 \uc911 \ud558\ub098\ub9cc \uace0\ub974\ub824 \uc560\uc4f8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \uc911\uc694\ud55c \ub300\uc0c1\uc744 \uc5b4\ub5bb\uac8c \ud45c\ud604\ud558\uace0 \uc790\uae30 \uc0b6\uacfc \uc5f0\uacb0\ud588\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\ub294 \uac83\uc774\ub2e4. \uc791\ud488\uc740 \uc131\ubaa8\uc640 \uc544\uc774\ub9cc\uc744 \uc124\uba85\ud558\ub294 \ub370\uc11c \ub098\uc544\uac00, \uadf8\uac83\uc744 \ubc14\ub77c\ubcf4\ub294 \uc0ac\ub78c\uc758 \uc790\ub9ac\uae4c\uc9c0 \ud568\uaed8 \ub2f4\ub294\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 \uc61b \ub8e8\ube0c\ub974 \ub3c4\ub85d\uc758 \uc2e4\uc81c \ud68c\ud654 \uc0c9\ucc44 \uc7ac\ud604 \uc790\ub8cc\ub2e4. \ucd5c\uc2e0 \uace0\ud574\uc0c1\ub3c4 \uc0ac\uc9c4\ucc98\ub7fc \ubaa8\ub4e0 \ud45c\uba74\uc744 \ubcf4\uc5ec \uc8fc\uc9c0\ub294 \uc54a\uc9c0\ub9cc \uc778\ubb3c\uacfc \uac74\ucd95, \uba3c \ud48d\uacbd\uc758 \ud070 \uad00\uacc4\ub97c \ud655\uc778\ud560 \uc218 \uc788\ub2e4. \uc0c1\uc0c1\uc73c\ub85c \uc0c8\ub85c \ub9cc\ub4e0 \uc131\ubaa8 \uc7a5\uba74\uacfc\ub294 \uad6c\ubd84\ub41c\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc55e\uc758 \uc138 \uc778\ubb3c\uacfc \ucc9c\uc0ac\ub97c \uc54c\uc544\ubcf4\uace0, \ub2e4\uc74c\uc5d0\ub294 \uc778\ubb3c \uc0ac\uc774\ub85c \ucc3d\ubc16\uc744 \ubc14\ub77c\ubcf4\uc790. \ub2e4\uc2dc \ucc98\uc74c\uc73c\ub85c \ub3cc\uc544\uc624\uba74 \uae30\ub3c4\ud558\ub294 \uc0ac\ub78c\ub3c4 \ub354 \ub113\uc740 \uc138\uacc4 \uc548\uc5d0 \ub193\uc778\ub2e4. \ud55c \uadf8\ub9bc\uc758 \uad50\uc591\uc740 \uc791\uc740 \uc0c1\uc9d5\uc744 \ub9ce\uc774 \uc678\uc6b0\ub294 \ub370\ub9cc \uc788\uc9c0 \uc54a\ub2e4. \ud654\uba74 \uc18d \uac70\ub9ac\uc640 \uad00\uacc4\ub97c \ucc28\ub840\ub85c \uc54c\uc544\ubcf4\ub294 \ub370\uc11c\ub3c4 \uc2dc\uc791\ub41c\ub2e4."}, {"id": "van-gogh-life-and-letters", "title": "\ubc18 \uace0\ud750\uc758 \uc0dd\uc560 \u2014 \uadf8\ub9bc \uacc1\uc5d0\ub294 \ud3b8\uc9c0\uac00 \uc788\uc5c8\ub2e4", "summary": "\uc11c\uac04\uc9d1\uacfc \uc790\ud654\uc0c1\uc744 \ud1b5\ud574 \ubc30\uc6b0\uace0 \uc77c\ud558\uace0 \uad00\uacc4\ub97c \ub9fa\ub358 \ud654\uac00\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Art", "url": "stories/van-gogh-life-and-letters/index.html", "image": "media/van-gogh-life-and-letters.jpg", "alt": "\ubc18 \uace0\ud750 \uc790\ud654\uc0c1 \u00b7 1913\ub144 The Letters of a Post-Impressionist \uc218\ub85d \uc7ac\ud604\ub3c4\ud310", "text": "\ubc18 \uace0\ud750\uc758 \uc0dd\uc560 \u2014 \uadf8\ub9bc \uacc1\uc5d0\ub294 \ud3b8\uc9c0\uac00 \uc788\uc5c8\ub2e4 \ucc9c\uc7ac\ub77c\ub294 \ud55c\ub9c8\ub514 \ubc16\uc5d0\uc11c \ub9cc\ub098\ub294 \ud55c \uc0ac\ub78c \uc11c\uac04\uc9d1\uacfc \uc790\ud654\uc0c1\uc744 \ud1b5\ud574 \ubc30\uc6b0\uace0 \uc77c\ud558\uace0 \uad00\uacc4\ub97c \ub9fa\ub358 \ud654\uac00\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Art \ubb38\ud654 \ubc18 \uace0\ud750\uc758 \uc0dd\uc560\ub97c \uc774\uc57c\uae30\ud560 \ub54c\ub294 \u2018\uace0\ud1b5\ubc1b\uc740 \ucc9c\uc7ac\u2019\ub77c\ub294 \ub9d0\uc774 \uba3c\uc800 \ub098\uc624\uae30 \uc27d\ub2e4. \ud558\uc9c0\ub9cc \uadf8 \ub9d0\ub9cc\uc73c\ub85c\ub294 \uc5b4\ub450\uc6b4 \ub18d\ubbfc\uc758 \uc5bc\uad74\uc744 \uadf8\ub9ac\ub358 \uc0ac\ub78c\uc774 \uc5b4\ub5bb\uac8c \uc544\ub97c\uc758 \ubc1d\uc740 \ubc29\uacfc \uc0dd\ub808\ubbf8\uc758 \ubc24\ud558\ub298\uc744 \uadf8\ub9ac\uac8c \ub418\uc5c8\ub294\uc9c0 \uc54c\uae30 \uc5b4\ub835\ub2e4. \uadf8\uc758 \uadf8\ub9bc\uc5d0\ub294 \uc11c\ub85c \ub2e4\ub978 \uc7a5\uc18c\uc640 \uacf5\ubd80, \uc0ac\ub78c\uacfc \uc0dd\ud65c\uc774 \ub4e4\uc5b4 \uc788\ub2e4. 1853\ub144\uc5d0 \ud0dc\uc5b4\ub098 1890\ub144\uc5d0 \uc138\uc0c1\uc744 \ub5a0\ub09c \ub124\ub35c\ub780\ub4dc \ud654\uac00 \ube48\uc13c\ud2b8 \ubc18 \uace0\ud750\ub97c, \uc774\ubc88\uc5d0\ub294 \uc791\ud488\uacfc \ud3b8\uc9c0\uac00 \ub9cc\ub098\ub294 \uba87 \uac1c\uc758 \uc804\ud658\uc810\uc73c\ub85c \ub530\ub77c\uac00 \ubcf4\uc790. \ud3b8\uc9c0\ub294 \uc804\uae30\uc758 \ube48\uce78\uc744 \ubaa8\ub450 \ucc44\uc6b0\uc9c0\ub294 \uc54a\uc9c0\ub9cc \uadf8\uac00 \uc2e4\uc81c\ub85c \ubb34\uc5c7\uc744 \uace0\ubbfc\ud558\uba70 \uc77c\ud588\ub294\uc9c0 \uc54c\ub824 \uc900\ub2e4. \uc9c0\uae08\uc758 \uc6b0\ub9ac\ub294 \uc720\uba85\ud55c \uadf8\ub9bc\ubd80\ud130 \ub9cc\ub09c\ub2e4. \uadf8\ub798\uc11c \ubc18 \uace0\ud750\uac00 \ucc98\uc74c\ubd80\ud130 \uc790\uc2e0\ub9cc\uc758 \uc0c9\uacfc \ubd93\uc9c8\uc744 \uac00\uc9c0\uace0 \uc788\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud558\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \ud3b8\uc9c0\uc5d0\ub294 \ubb34\uc5c7\uc744 \uadf8\ub9b4\uc9c0 \uc815\ud558\uace0, \ubaa8\ub378\uc744 \uad6c\ud558\uace0, \uba38\ub9ac\uc640 \uc190\uc744 \uac70\ub4ed \uc5f0\uc2b5\ud558\ub294 \uc2dc\uac04\uc774 \ub0a8\uc544 \uc788\ub2e4. \uc791\ud488\uc758 \uacb0\uacfc\uc640 \uc791\uc5c5\uc758 \uacfc\uc815\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \uc0b6\uc758 \uc6c0\uc9c1\uc784\uc774 \ubcf4\uc778\ub2e4. \ud2b9\ud788 \ub3d9\uc0dd \ud14c\uc624\ub294 \uc911\uc694\ud55c \ud3b8\uc9c0 \uc0c1\ub300\uc600\ub2e4. \ud615\uc740 \ubb3c\uac10\uacfc \ub3c8, \uadf8\ub9bc\uc5d0 \ub300\ud55c \uacc4\ud68d\uacfc \ubd88\uc548\uc744 \ub3d9\uc0dd\uc5d0\uac8c \uc774\uc57c\uae30\ud55c\ub2e4. \ud14c\uc624\ub294 \uc0dd\ud65c\uacfc \uc791\uc5c5\uc744 \uc9c0\uc6d0\ud588\uace0, \ud615\uc740 \uadf8 \uad00\uacc4 \uc18d\uc5d0\uc11c \uacc4\uc18d \uc77c\uc744 \uc774\uc5b4 \uac14\ub2e4. \ud654\uac00\uc758 \uc0b6\uc744 \uace0\ub3c5\ud55c \uc601\uc6c5\uc758 \uc774\uc57c\uae30\ub85c\ub9cc \ub9cc\ub4e4\uba74 \uc774\ub7f0 \uad6c\uccb4\uc801\uc778 \uc5f0\uacb0\uc774 \uc0ac\ub77c\uc9c4\ub2e4. 1880\ub144 6\uc6d4\uacbd \ubca8\uae30\uc5d0 \ubcf4\ub9ac\ub098\uc8fc\uc758 \ud034\uc5e0\uc5d0\uc11c \ud14c\uc624\uc5d0\uac8c \uc4f4 \ud3b8\uc9c0\uc5d0\ub294 \uc9c4\ub85c\uc640 \uac00\uc871 \uad00\uacc4\uc758 \uc5b4\ub824\uc6c0\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \ubc18 \uace0\ud750\ub294 \ub3d9\uc0dd\uc774 \ubcf4\ub0b4 \uc900 \ub3c8\uc5d0 \uac10\uc0ac\ub97c \uc804\ud558\uba74\uc11c\ub3c4, \uc790\uc2e0\uc774 \uac00\uc871\uc5d0\uac8c \uc2e0\ub8b0\ubc1b\uc9c0 \ubabb\ud55c\ub2e4\uace0 \ub290\ub07c\ub294 \uc0ac\uc815\uc744 \uc774\uc57c\uae30\ud55c\ub2e4. \ud6d7\ub0a0\uc758 \uba85\uc131\uc744 \uc7a0\uc2dc \ub0b4\ub824\ub193\uc73c\uba74 \uc55e\ub0a0\uc774 \ubd88\ud655\uc2e4\ud588\ub358 \uc2a4\ubb3c\uc77c\uacf1 \uc0b4\uc758 \uc0ac\ub78c\uc774 \ubcf4\uc778\ub2e4. \uadf8 \ud3b8\uc9c0\uc5d0\ub294 \uc131\uc11c\uc640 \ubb38\ud559\uc744 \uc77d\uace0 \ubbf8\uc220\uc744 \uc0dd\uac01\ud558\ub294 \uc2dc\uac04\ub3c4 \ub0a8\uc544 \uc788\ub2e4. \ubc29\ud5a5\uc774 \uc7a1\ud788\uc9c0 \uc54a\uc558\ub2e4\ub294 \uac83\uc774 \uc544\ubb34 \uad00\uc2ec\ub3c4 \ub178\ub825\ub3c4 \uc5c6\uc5c8\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ub110\ub9ac \uc54c\ub824\uc9c4 \uc791\ud488\uc774 \ub098\uc624\uae30 \uc804\uc758 \uc774\ub7f0 \uc2dc\uae30\ub97c \uc54c\uace0 \ub098\uba74, \uadf8\uc758 \uc0dd\uc560\uac00 \ucc9c\uc7ac\uc758 \ud0c4\uc0dd\uacfc \ube44\uadf9\uc801\uc778 \uc8fd\uc74c \uc0ac\uc774\ub97c \uace7\uc7a5 \ub2ec\ub9b0 \uc774\uc57c\uae30\ub294 \uc544\ub2c8\uc5c8\ub2e4\ub294 \uac83\uc744 \uc54c \uc218 \uc788\ub2e4. 1885\ub144 4\uc6d4 30\uc77c \ub258\ub10c\uc5d0\uc11c \ud14c\uc624\uc5d0\uac8c \ubcf4\ub0b8 \ud3b8\uc9c0\uc5d0\uc11c \ubc18 \uace0\ud750\ub294 \u3008\uac10\uc790 \uba39\ub294 \uc0ac\ub78c\ub4e4\u3009\uc744 \uc124\uba85\ud55c\ub2e4. \uadf8\ub294 \uc644\uc131\ub41c \uadf8\ub9bc\uc758 \uc791\uc5c5 \uae30\uac04\ub9cc\uc774 \uc544\ub2c8\ub77c \uadf8\uc804 \uaca8\uc6b8 \ub0b4\ub0b4 \uba38\ub9ac\uc640 \uc190\uc744 \uadf8\ub9b0 \uc2b5\uc791\uc774 \uc788\uc5c8\ub2e4\uace0 \uc54c\ub9b0\ub2e4. \uc9e7\uc740 \uc2dc\uac04\uc5d0 \uadf8\ub9b0 \uac83\ucc98\ub7fc \ubcf4\uc5ec\ub3c4 \uadf8 \uc55e\uc5d0\ub294 \uae34 \uc900\ube44\uac00 \ub193\uc5ec \uc788\ub2e4\ub294 \ub73b\uc774\ub2e4. \uad00\uc2ec\uc744 \ub454 \uac83\uc740 \uc608\uc058\uac8c \uafb8\ubbfc \ub18d\ubbfc\uc758 \ubaa8\uc2b5\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uac10\uc790\ub97c \uc9d1\ub294 \uc190\uc774 \uc2e4\uc81c\ub85c \ub545\uc744 \uc77c\uad70 \uc190\uc774\ub77c\ub294 \uc810, \uadf8 \uc74c\uc2dd\uacfc \ub178\ub3d9\uc774 \uc774\uc5b4\uc838 \uc788\ub2e4\ub294 \uc810\uc744 \ubcf4\uc5ec \uc8fc\uace0 \uc2f6\uc5b4 \ud588\ub2e4. \uc774 \ucd08\uae30\uc758 \uad00\uc2ec\uc744 \uc54c\uc544 \ub450\uba74 \uc774\ud6c4\uc758 \ubc1d\uc740 \uc0c9\ucc44\ub9cc\uc73c\ub85c \ubc18 \uace0\ud750 \uc804\uccb4\ub97c \uc124\uba85\ud558\uc9c0 \uc54a\uac8c \ub41c\ub2e4. \uc0ac\ub78c\uc744 \uc5b4\ub5bb\uac8c \uadf8\ub9b4 \uac83\uc778\uac00\ub77c\ub294 \uc9c8\ubb38\uc774 \uc774\ubbf8 \uc791\uc5c5\uc758 \uc911\uc2ec\uc5d0 \uc788\uc5c8\ub2e4. \uadf8\uc758 \uc791\uc5c5 \uc5ec\uc815\uc5d0\ub294 \ub124\ub35c\ub780\ub4dc\uc640 \ud30c\ub9ac, \ub0a8\ud504\ub791\uc2a4\uc758 \uc544\ub97c, \uc0dd\ub808\ubbf8, \ub9c8\uc9c0\ub9c9 \uc2dc\uae30\uc758 \uc624\ubca0\ub974\uc26c\ub974\uc6b0\uc544\uc988\uac00 \uc774\uc5b4\uc9c4\ub2e4. \uc774 \uc774\ub984\ub4e4\uc744 \uba85\ud654\uac00 \ud0c4\uc0dd\ud55c \uad00\uad11\uc9c0\ub85c\ub9cc \uc678\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc7a5\uc18c\uac00 \ub2ec\ub77c\uc9c8 \ub54c \ub9cc\ub098\ub294 \uc0ac\ub78c\uacfc \ube5b, \uadf8\ub9bc\uc744 \ubcfc \uae30\ud68c\uc640 \uc791\uc5c5 \uc870\uac74\ub3c4 \ud568\uaed8 \ubc14\ub010\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc911\uc694\ud558\ub2e4. \ud30c\ub9ac \uc2dc\uae30\uc640 \ub0a8\ud504\ub791\uc2a4 \uc2dc\uae30\ub97c \ub5a0\uc62c\ub9b4 \ub54c\ub3c4 \uc5b4\ub450\uc6b4 \uadf8\ub9bc\uc774 \uc5b4\ub290 \ub0a0 \ud55c\uc21c\uac04\uc5d0 \ubc1d\uc544\uc84c\ub2e4\uace0 \uc815\ub9ac\ud558\uae30\ubcf4\ub2e4, \ubb34\uc5c7\uc744 \uad00\ucc30\ud558\uace0 \uc5b4\ub5a4 \uc0c9\uc744 \uc4f0\ub824 \ud588\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uba74 \uc88b\ub2e4. \ud3b8\uc9c0\ub294 \uadf8\uac00 \ub2e4\ub978 \ud654\uac00\ub97c \uc758\uc2dd\ud558\uace0 \uc790\uc2e0\uc758 \uc791\ud488\uc744 \ube44\uad50\ud558\uba70 \ubc29\ud5a5\uc744 \ucc3e\uc558\ub2e4\ub294 \uac83\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uace0\uac31\uacfc \ubca0\ub974\ub098\ub974 \uac19\uc740 \ub3d9\ub8cc\uc758 \uc774\ub984\ub3c4 \uc774\ub7f0 \uc791\uc5c5\uc758 \ub300\ud654 \uc18d\uc5d0 \ub4f1\uc7a5\ud55c\ub2e4. 1888\ub144 10\uc6d4 16\uc77c \uc544\ub97c\uc5d0\uc11c \uc4f4 \ud3b8\uc9c0\ub294 \u3008\uce68\uc2e4\u3009\uc744 \uc124\uba85\ud55c\ub2e4. \ubc18 \uace0\ud750\ub294 \ubc29 \uc548\uc758 \ubb3c\uac74\uc744 \uc790\uc138\ud788 \ub098\uc5f4\ud558\uba74\uc11c \uc0c9\uacfc \ub2e8\uc21c\ud55c \ud615\ud0dc\ub97c \ud1b5\ud574 \ud734\uc2dd\uc758 \ub290\ub08c\uc744 \uc804\ud558\ub824\uace0 \ud55c\ub2e4. \uce68\ub300\uc640 \uc758\uc790, \ubb38\uacfc \ubcbd\uc744 \uadf8\ub0e5 \ubcf4\uc774\ub294 \ub300\ub85c \uc62e\uae30\ub294 \uac83\ub9cc\uc774 \ubaa9\uc801\uc740 \uc544\ub2c8\uc5c8\ub358 \uc148\uc774\ub2e4. \uc774\ub97c \uc54c\uace0 \ub098\uba74 \ubc18 \uace0\ud750\uc758 \uac15\ud55c \uc0c9\uc744 \ubb34\uc870\uac74 \ud765\ubd84\uc774\ub098 \ubd88\uc548\uc758 \ud45c\uc2dc\ub85c \ubcfc \uc218 \uc5c6\uac8c \ub41c\ub2e4. \uadf8\uac00 \uc870\uc6a9\ud55c \uc27c\uc744 \ud45c\ud604\ud558\ub824\uace0 \uc120\ud0dd\ud55c \uc0c9\ub3c4 \uc788\uc5c8\ub2e4. \uc5b4\ub5a4 \uadf8\ub9bc\uc758 \uc0c9\uc774 \uac15\ud558\ub2e4\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \ud654\uac00\uc758 \uc815\uc2e0 \uc0c1\ud0dc\ub97c \ubc14\ub85c \uc9c4\ub2e8\ud558\uc9c0 \ub9d0\uc544\uc57c \ud558\ub294 \uae4c\ub2ed\uc774\ub2e4. \uc791\ud488\uc758 \uc2e4\uc81c \uc124\uba85\uacfc \ud654\uba74\uc744 \ud568\uaed8 \uc0b4\ud53c\ub294 \ud3b8\uc774 \ub0ab\ub2e4. \ubc18 \uace0\ud750\ub294 \ub3d9\ub8cc \ud654\uac00\ub4e4\uacfc\uc758 \uad00\uacc4\ub97c \uc911\uc694\ud558\uac8c \uc5ec\uacbc\ub2e4. \ud3b8\uc9c0\uc5d0\ub294 \uace0\uac31\uacfc \ubca0\ub974\ub098\ub974\uc758 \uc791\ud488\uc744 \ud3c9\uac00\ud558\uace0, \uc790\uc2e0\uc758 \uadf8\ub9bc\uacfc \uc5b4\ub5a4 \uc810\uc5d0\uc11c \ud1b5\ud560 \uc218 \uc788\uc744\uc9c0 \uc0dd\uac01\ud558\ub294 \ub0b4\uc6a9\uc774 \uc788\ub2e4. \ud63c\uc790\ub9cc\uc758 \uba38\ub9bf\uc18d \uc138\uacc4\ub97c \uadf8\ub300\ub85c \uc3df\uc544 \ub0b8 \ud654\uac00\ub77c\ub294 \uc778\uc0c1\uacfc\ub294 \ub2e4\ub978 \ubaa8\uc2b5\uc774\ub2e4. \uadf8\ub294 \ub2e4\ub978 \uc0ac\ub78c\uc774 \uc790\uc2e0\uc758 \uadf8\ub9bc\uc744 \uc5b4\ub5bb\uac8c \ubcfc\uc9c0\ub3c4 \uace0\ubbfc\ud588\ub2e4. \uc0dd\ud65c\uc774 \ub298 \uc548\uc815\uc801\uc774\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uacbd\uc81c\uc801 \uc758\uc874\uacfc \uad00\uacc4\uc758 \uc5b4\ub824\uc6c0, \uac74\uac15\uc0c1\uc758 \uc704\uae30\uac00 \uc791\uc5c5\uacfc \ud568\uaed8 \uc774\uc5b4\uc84c\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubd88\ud589\uc774 \ub9ce\uc744\uc218\ub85d \uc704\ub300\ud55c \uc608\uc220\uc774 \ub098\uc628\ub2e4\ub294 \uacf5\uc2dd\uc744 \ub9cc\ub4e4 \uc218\ub294 \uc5c6\ub2e4. \uc5b4\ub824\uc6c0 \uc18d\uc5d0\uc11c\ub3c4 \uc791\uc5c5\uc744 \uc9c0\uc18d\ud558\ub824 \ud588\ub2e4\ub294 \uc0ac\uc2e4\uacfc, \uc5b4\ub824\uc6c0\uc774 \uc791\ud488\uc758 \uac00\uce58\ub97c \ub9cc\ub4e4\uc5b4 \uc8fc\uc5c8\ub2e4\ub294 \uc8fc\uc7a5\uc740 \ub2e4\ub974\ub2e4. \uc0dd\ub808\ubbf8 \uc2dc\uae30\uc758 1889\ub144 6\uc6d4 \ud3b8\uc9c0\uc5d0\uc11c \uadf8\ub294 \uc0dd\ud65c\uc758 \uc808\uc81c\uc640 \uce58\ub8cc, \uc791\uc5c5\uc774 \uc790\uc2e0\uc5d0\uac8c \uc5b4\ub5a4 \uc5ed\ud560\uc744 \ud558\ub294\uc9c0 \ud14c\uc624\uc5d0\uac8c \uc54c\ub9b0\ub2e4. \uc0c8\ub85c \uadf8\ub9b0 \uc62c\ub9ac\ube0c\ub098\ubb34 \ud48d\uacbd\uacfc \ubcc4\uc774 \uc788\ub294 \ubc24\ud558\ub298\uc744 \uc774\uc57c\uae30\ud558\uace0, \ub3d9\ub8cc\ub4e4\uacfc \ub098\ub208 \ud68c\ud654\uc758 \uc0dd\uac01\ub3c4 \ub3cc\uc544\ubcf8\ub2e4. \uac74\uac15\uc758 \uc5b4\ub824\uc6c0\uacfc \uad6c\uccb4\uc801\uc778 \uc791\uc5c5 \uacc4\ud68d\uc774 \uac19\uc740 \ud3b8\uc9c0 \uc548\uc5d0 \ub193\uc5ec \uc788\ub2e4. \ubc24\ud558\ub298\uc758 \uadf8\ub9bc\uc744 \uc8fd\uc74c\uc758 \uc608\uace0\ub098 \uc99d\uc0c1\uc758 \ub3c4\uc2dd\uc73c\ub85c\ub9cc \uc77d\uc73c\uba74 \uc774\ub7f0 \uc791\uc5c5\uc758 \uc5b8\uc5b4\uac00 \uc0ac\ub77c\uc9c4\ub2e4. \ubb34\uc5c7\uc744 \ubcf4\uc558\uace0 \uc0c9\uacfc \uc120\uc73c\ub85c \ubb34\uc5c7\uc744 \ud45c\ud604\ud558\ub824 \ud588\ub294\uc9c0 \uba3c\uc800 \ubb3c\uc5b4\ubcf4\uc790. \uc774 \uae00\uc740 \uc624\ub798\ub41c \uc11c\uac04\uc9d1\uc758 \ub0a0\uc9dc\uac00 \ubd80\uc815\ud655\ud55c \uacf3\uc744 \uadf8\ub300\ub85c \uc62e\uae30\uc9c0 \uc54a\uace0, \ud604\ub300 \ud3b8\uc9c0 \uc815\ub9ac\ubcf8\uc758 \ud574\ub2f9 \uae30\ub85d\uacfc \ub300\uc870\ud588\ub2e4. \ud604\ub300 \ubc88\uc5ed\ubb38 \uc790\uccb4\ub97c \uc62e\uaca8 \uc2e3\uc9c0\ub294 \uc54a\uc558\ub2e4. 1890\ub144 7\uc6d4\uacbd \uc624\ubca0\ub974\uc26c\ub974\uc6b0\uc544\uc988\uc5d0\uc11c \ubcf4\ub0b8 \ud3b8\uc9c0\uc5d0\ub294 \ub113\uc740 \ubc00\ubc2d\uacfc \uac70\uce5c \ud558\ub298\uc744 \uadf8\ub9b0 \uc791\uc5c5, \uac00\uc871\uc758 \uc0dd\ud65c\uc5d0 \ub300\ud55c \uac71\uc815\uc774 \ud568\uaed8 \ub098\uc628\ub2e4. \uc774 \ud3b8\uc9c0\ub294 \uc0b6\uc758 \ub9c8\uc9c0\ub9c9 \uc2dc\uae30\uc5d0 \uc18d\ud558\uc9c0\ub9cc, \ubb38\uc7a5 \ud558\ub098\ub97c \uace7\ubc14\ub85c \uc8fd\uc74c\uc758 \uc608\uc5b8\ucc98\ub7fc \uc77d\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \uadf8\ub9bc\uc744 \uc644\uc131\ud558\uace0 \uac00\uc871\uc5d0\uac8c \ubcf4\uc5ec \uc8fc\ub824\ub294 \uc77c\uc0c1\uc801\uc778 \ubc14\ub78c\ub3c4 \uc548\uc5d0 \uc788\ub2e4. \ubc18 \uace0\ud750\ub294 \uac19\uc740 \ud574\uc5d0 \uc138\uc0c1\uc744 \ub5a0\ub0ac\ub2e4. \uc5ec\uae30\uc11c\ub294 \uadf8\ub9bc\uc758 \ud2b9\uc815 \uc0c8\ub098 \ud558\ub298\uc744 \uc0ac\ub9dd \uacbd\uc704\uc758 \uc99d\uac70\ub85c \uc0bc\uac70\ub098, \ud3b8\uc9c0\ub9cc\uc73c\ub85c \ubcd1\uba85\uc744 \ud655\uc815\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc0b6\uc758 \ub05d\uc744 \uc548\ub2e4\ub294 \uc774\uc720\ub85c \uadf8\uc804\uc758 \ubaa8\ub4e0 \uc791\uc5c5\uc744 \uc8fd\uc74c\uc73c\ub85c\ub9cc \ud5a5\ud558\ub294 \uae38\ub85c \ub9cc\ub4e4\uba74 \ud654\uac00\uac00 \uc2e4\uc81c\ub85c \ud574 \uc628 \ud0d0\uad6c\ub97c \ub193\uce58\uae30 \uc27d\ub2e4. \ucc98\uc74c \uc77d\ub294\ub2e4\uba74 \u3008\uac10\uc790 \uba39\ub294 \uc0ac\ub78c\ub4e4\u3009\uc5d0\uc11c\ub294 \uc190\uacfc \ub178\ub3d9\uc744, \u3008\uce68\uc2e4\u3009\uc5d0\uc11c\ub294 \uc0c9\uacfc \ud734\uc2dd\uc744, \uc0dd\ub808\ubbf8\uc758 \ubc24\ud558\ub298\uc5d0\uc11c\ub294 \ud48d\uacbd\uacfc \ud45c\ud604\uc744 \ube44\uad50\ud574 \ubcf4\uc790. \uc11c\ub85c \ub2e4\ub978 \uc2dc\uae30\uc758 \uc791\ud488\uc744 \ub098\ub780\ud788 \ub193\uc73c\uba74 \u2018\ud56d\uc0c1 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uadf8\ub9b0 \ud654\uac00\u2019\uac00 \uc544\ub2c8\ub77c \uacc4\uc18d \ubcc0\ud654\ub97c \uc2dc\ub3c4\ud55c \uc0ac\ub78c\uc774 \ubcf4\uc778\ub2e4. \uc774\ubc88 \uae00\uc5d0 \uc2e4\uc740 \uc774\ubbf8\uc9c0\ub294 1913\ub144 \uc11c\uac04\uc9d1\uc5d0 \uc218\ub85d\ub41c \uc790\ud654\uc0c1\uc758 \uc7ac\ud604 \ub3c4\ud310\uc774\uba70 \uc774 \uc138 \uc791\ud488\uc758 \uc0ac\uc9c4\uc740 \uc544\ub2c8\ub2e4. \ubc18 \uace0\ud750\uc758 \uadf8\ub9bc \uacc1\uc5d0\ub294 \ub3c8\uacfc \ubb3c\uac10, \uacf5\ubd80\uc640 \uac00\uc871, \ud734\uc2dd\uacfc \uce58\ub8cc\ub97c \ub9d0\ud558\ub294 \ud3b8\uc9c0\uac00 \ub0a8\uc544 \uc788\ub2e4. \uadf8\uac83\uc744 \uc54c\uace0 \ub2e4\uc2dc \uc790\ud654\uc0c1\uc744 \ubcf4\uba74 \uc720\uba85\ud55c \ube44\uadf9\uc758 \uc5bc\uad74\ub9cc \ubcf4\uc774\uc9c0\ub294 \uc54a\uc744 \uac83\uc774\ub2e4. \uc9e7\uc740 \uc0dd\uc560 \uc548\uc5d0\uc11c \uc5b4\ub5bb\uac8c \uc77c\ud560\uc9c0 \uac70\ub4ed \uc0dd\uac01\ud588\ub358 \uc0ac\ub78c, \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uc790\uc2e0\uc758 \uadf8\ub9bc\uc744 \uc774\ud574\uc2dc\ud0a4\ub824 \ud588\ub358 \uc0ac\ub78c\uc744 \ud568\uaed8 \ub9cc\ub0a0 \uc218 \uc788\ub2e4."}, {"id": "vermeer-lacemaker-looking-guide", "title": "\ub808\uc774\uc2a4 \ub728\ub294 \uc5ec\uc778 \u2014 \uc791\uc740 \uc77c\uc5d0 \uc2dc\uc120\uc774 \ubaa8\uc77c \ub54c", "summary": "\ub8e8\ube0c\ub974\uc758 \uc870\uc6a9\ud55c \uc791\uc5c5 \uc7a5\uba74\uc5d0\uc11c \uc778\ubb3c\uc758 \uc190\uacfc \uc2e4, \uc0c9\uc744 \ub530\ub77c\uac00 \ubd05\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Art", "url": "stories/vermeer-lacemaker-looking-guide/index.html", "image": "media/vermeer-lacemaker-looking-guide.jpg", "alt": "\uc694\ud558\ub124\uc2a4 \ubca0\ub974\uba54\ub974, \ub808\uc774\uc2a4 \ub728\ub294 \uc5ec\uc778 \u00b7 \uc61b \ub8e8\ube0c\ub974 \ub3c4\ub85d Plate XXXVI", "text": "\ub808\uc774\uc2a4 \ub728\ub294 \uc5ec\uc778 \u2014 \uc791\uc740 \uc77c\uc5d0 \uc2dc\uc120\uc774 \ubaa8\uc77c \ub54c \ubca0\ub974\uba54\ub974\uac00 \ubcf4\uc5ec \uc8fc\ub294 \uc190\uacfc \uc9d1\uc911\uc758 \uc7a5\uba74 \ub8e8\ube0c\ub974\uc758 \uc870\uc6a9\ud55c \uc791\uc5c5 \uc7a5\uba74\uc5d0\uc11c \uc778\ubb3c\uc758 \uc190\uacfc \uc2e4, \uc0c9\uc744 \ub530\ub77c\uac00 \ubd05\ub2c8\ub2e4. Art \ubb38\ud654 \ud55c \uc5ec\uc778\uc774 \uace0\uac1c\ub97c \uc219\uc774\uace0 \uc190\ub05d\uc5d0 \uc9d1\uc911\ud558\uace0 \uc788\ub2e4. \uc601\uc6c5\uc758 \uc2b9\ub9ac\ub3c4 \uc655\uc758 \uc989\uc704\ub3c4 \uc544\ub2cc, \uc791\uc740 \uc791\uc5c5\uc774 \uadf8\ub9bc\uc758 \uc804\ubd80\uc778 \uac83\ucc98\ub7fc \ubcf4\uc778\ub2e4. \uc694\ud558\ub124\uc2a4 \ubca0\ub974\uba54\ub974\uc758 \u3008\ub808\uc774\uc2a4 \ub728\ub294 \uc5ec\uc778\u3009\uc744 \ucc98\uc74c \ub9cc\ub098\uba74 \ubb34\uc5c7\uc744 \uc624\ub798 \ubcf4\uc544\uc57c \ud560\uc9c0 \ub9c9\ub9c9\ud560 \uc218\ub3c4 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uadf8\ub9bc \uc18d \uc0ac\ub78c\uc774 \ubc14\ub77c\ubcf4\ub294 \ubc29\ud5a5\uc744 \ub530\ub77c\uac00\uba74 \ud654\uba74\uc758 \uc911\uc2ec\uc744 \ucc3e\uc744 \uc218 \uc788\ub2e4. \uc774 \uc791\ud488\uc740 \ud070 \uc0ac\uac74 \uc5c6\uc774\ub3c4 \uc0ac\ub78c\uc758 \uc2dc\uac04\uc744 \ubd99\uc7a1\uc744 \uc218 \uc788\ub2e4\ub294 \uac83\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ud504\ub791\uc2a4\uc5b4 \uc81c\ubaa9 \ub77c \ub2f9\ud154\ub9ac\uc5d0\ub974\ub294 \ub808\uc774\uc2a4\ub97c \ub9cc\ub4dc\ub294 \uc5ec\uc778\uc744 \uac00\ub9ac\ud0a8\ub2e4. \uc5ec\uc778\uc740 \ubcf4\ube48\uc774\ub77c\ub294 \uc791\uc740 \ub3c4\uad6c\uc5d0 \uac10\uae34 \uc2e4\uc744 \ub2e4\ub8e8\uba70 \ub808\uc774\uc2a4\ub97c \ub9cc\ub4e4\uace0 \uc788\ub2e4. \uc2e4\uc758 \uad50\ucc28\ub85c \ubb34\ub2ac\ub97c \uc9dc\ub294 \uc77c\uc774\ub2e4. \uae34 \ub300\ubc14\ub298\ub85c \ud138\uc637\uc744 \ub728\ub294 \uc7a5\uba74\uc744 \uba3c\uc800 \ub5a0\uc62c\ub838\ub2e4\uba74 \uc190 \uc8fc\ubcc0\uc758 \uc791\uc740 \ub3c4\uad6c\uc640 \uc791\uc5c5 \uc790\ub9ac\ub97c \ub2e4\uc2dc \ubcf4\uc790. \uadf8\ub9bc\uc758 \uc81c\ubaa9\uc744 \uc544\ub294 \uac83\uacfc \uadf8 \uc77c\uc774 \ubb34\uc5c7\uc778\uc9c0 \uc544\ub294 \uac83\uc740 \uc870\uae08 \ub2e4\ub978 \uacbd\ud5d8\uc774\ub2e4. \ub3c4\ud310\uc5d0\uc11c\ub294 \uc2e4\uacfc \ub3c4\uad6c\uc758 \uc138\ubd80\ub97c \ubaa8\ub450 \uad6c\ubcc4\ud558\uae30 \uc5b4\ub835\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc791\uc740 \uc810 \ud558\ub098\ub97c \uc5b5\uc9c0\ub85c \ud2b9\uc815 \ub3c4\uad6c\ub77c\uace0 \ud310\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub450 \uc190\uc774 \uc544\uc8fc \uc881\uc740 \uc790\ub9ac\uc5d0 \ubaa8\uc5ec \uc788\uace0 \uc2dc\uc120\uc774 \uadf8\uacf3\uc744 \ud5a5\ud55c\ub2e4\ub294 \uad00\uacc4\ubd80\ud130 \ubcf4\uba74 \ub41c\ub2e4. \uc7a5\uba74\uc744 \uc774\ud574\ud558\ub294 \ub370 \ud544\uc694\ud55c \ud575\uc2ec\uc740 \uc774\ubbf8 \ubcf4\uc778\ub2e4. \ucd08\uc0c1\ud654\uc5d0\uc11c\ub294 \uc778\ubb3c\uc774 \uad00\uac1d\uc744 \uc815\uba74\uc73c\ub85c \ubc14\ub77c\ubcf4\ub294 \uacbd\uc6b0\uac00 \ub9ce\ub2e4. \uc5ec\uae30\uc758 \uc5ec\uc778\uc740 \uc6b0\ub9ac\ub97c \ud5a5\ud574 \ud3ec\uc988\ub97c \ucde8\ud558\uae30\ubcf4\ub2e4 \uc790\uae30 \uc77c\uc744 \ud558\uace0 \uc788\ub2e4. \uadf8\ub798\uc11c \uad00\uac1d\uc740 \ub204\uad70\uac00\uc758 \ubc29\uc5d0 \uc7a0\uae50 \ub4e4\uc5b4\uc640 \uc870\uc6a9\ud788 \uadf8 \uc2dc\uac04\uc744 \uc9c0\ucf1c\ubcf4\ub294 \ub4ef\ud55c \uc704\uce58\uc5d0 \ub193\uc778\ub2e4. \uc778\ubb3c\uc758 \ub208\uc5d0\uc11c \uc190\uc73c\ub85c \ub0b4\ub824\uc624\ub294 \uae38\uc744 \ub530\ub77c\uac00 \ubcf4\uc790. \uc6b0\ub9ac\uac00 \ubcf4\ub294 \ubc29\ud5a5\uacfc \uadf8\ub9bc \uc18d \uc0ac\ub78c\uc774 \ubcf4\ub294 \ubc29\ud5a5\uc774 \uacb9\uce58\uba74\uc11c \uc791\uc740 \uc791\uc5c5\uc774 \ub354 \uc911\uc694\ud558\uac8c \ub290\uaef4\uc9c4\ub2e4. \ubb34\uc2a8 \uc0ac\uac74\uc778\uc9c0 \ubab0\ub77c\uc11c \ube44\uc5b4 \uc788\ub294 \uadf8\ub9bc\uc774 \uc544\ub2c8\ub77c, \ud55c \uc0ac\ub78c\uc774 \uc9d1\uc911\ud558\uace0 \uc788\ub2e4\ub294 \uc0ac\uac74\uc774 \uc774\ubbf8 \uc77c\uc5b4\ub098\uace0 \uc788\ub294 \uadf8\ub9bc\uc73c\ub85c \ubcfc \uc218 \uc788\ub2e4. \uc5ec\uc778\uc740 \ubc1d\uc740 \ub178\ub780\ube5b \uc0c1\uc758\ub97c \uc785\uc5c8\ub2e4. \uc8fc\ubcc0\uc758 \ube44\uad50\uc801 \uc5b4\ub450\uc6b4 \ubd80\ubd84\uacfc \uad6c\ubcc4\ub418\uba74\uc11c \ubab8\uc774 \uac00\uae4c\uc774 \ub290\uaef4\uc9c4\ub2e4. \uba3c\uc800 \uc0c9\uc5d0 \uc774\ub04c\ub9ac\uace0, \uadf8 \uc0c9\uc744 \uc785\uc740 \uc0ac\ub78c\uc758 \uc790\uc138\ub97c \ub530\ub77c\uac00\uba70 \uc190\ub05d\uc5d0 \uc774\ub974\ub294 \uc2dd\uc73c\ub85c \uac10\uc0c1\ud574 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uc774\ub294 \ud55c \uac00\uc9c0 \uc77d\ub294 \ubc29\ubc95\uc774\uba70 \ubaa8\ub4e0 \uad00\uac1d\uc774 \uac19\uc740 \uc21c\uc11c\ub85c \ubcf4\uc544\uc57c \ud55c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uba38\ub9ac\uc640 \uc5b4\uae68, \ub450 \ud314\uc774 \ub9cc\ub4dc\ub294 \ubaa8\uc591\uc744 \uc0b4\ud53c\uba74 \uc778\ubb3c\uc774 \ud06c\uac8c \uc6c0\uc9c1\uc774\uc9c0 \uc54a\uc544\ub3c4 \ud654\uba74\uc5d0 \ubc29\ud5a5\uc774 \uc788\ub2e4\ub294 \uac83\uc744 \ub290\ub084 \uc218 \uc788\ub2e4. \uc190\uc774 \uc5b4\ub514\uc5d0 \ubaa8\uc774\ub294\uc9c0, \ud314\uc774 \uadf8 \uc790\ub9ac\ub97c \uc5b4\ub5bb\uac8c \uac10\uc2f8\ub294\uc9c0 \ubcf4\ub294 \uac83\uc774\ub2e4. \uc0c9\ub9cc \ub530\ub85c \ubcf4\ub294 \uac83\uc5d0\uc11c \ubab8\uc758 \uad6c\uc870\ub85c \ub118\uc5b4\uac00\uba74 \uadf8\ub9bc\uc774 \uc870\uae08 \ub354 \uc785\uccb4\uc801\uc73c\ub85c \ub2e4\uac00\uc628\ub2e4. \ud654\uba74 \uc55e\uc5d0\ub294 \ucfe0\uc158\uacfc \uc2e4, \ucc45\ucc98\ub7fc \ubcf4\uc774\ub294 \ubb3c\uac74\uc774 \ub193\uc5ec \uc788\ub2e4. \ub178\ub780 \uc637\uc758 \ub113\uc740 \uc0c9\uba74\uacfc \ub2ec\ub9ac \uc55e\ucabd\uc758 \ubd89\uc740 \uc2e4\uc740 \ud480\uc5b4\uc9c4 \uac00\ub2e5\ucc98\ub7fc \ubcf4\uc778\ub2e4. \uc774 \uc5b4\uc218\uc120\ud55c \ubd80\ubd84\uacfc \uc190 \uc8fc\ubcc0\uc758 \uc9d1\uc911\ub41c \uc790\uc138\ub97c \ubc88\uac08\uc544 \ubcf4\uc544\ub3c4 \uc7ac\ubbf8\uc788\ub2e4. \ubaa8\ub4e0 \uacf3\uc774 \uac19\uc740 \uc815\ub3c4\ub85c \ub610\ub837\ud558\uac8c \uc815\ub9ac\ub418\uc5b4\uc57c\ub9cc \uadf8\ub9bc\uc774 \uc0dd\uc0dd\ud574\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc791\uc5c5\ud558\ub294 \uc7a5\uba74\uc5d0 \ub2e4\ub978 \ubb3c\uac74\ub4e4\uc774 \ub07c\uc5b4 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub3c4 \uc911\uc694\ud558\ub2e4. \uc0ac\ub78c\uc740 \ubc30\uacbd \uc5c6\ub294 \uacf5\uac04\uc5d0\uc11c \uc190\ub9cc \uc6c0\uc9c1\uc774\uc9c0 \uc54a\ub294\ub2e4. \uc8fc\ubcc0\uc758 \ubb3c\uac74\uacfc \uac70\ub9ac\ub97c \ub9cc\ub4e4\uba70 \uc77c\ud55c\ub2e4. \ub2e4\ub9cc \ucc45\uc774 \uc788\ub2e4\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \uc5ec\uc778\uc758 \uc2e0\uc559\uc774\ub098 \uc131\uaca9\uc744 \uace7\ubc14\ub85c \ub2e8\uc815\ud558\uc9c0\ub294 \ub9d0\uc790. \ubb3c\uac74\uc758 \uc874\uc7ac\ub97c \ud655\uc778\ud558\ub294 \uac83\uacfc \uadf8 \uc0c1\uc9d5\uc744 \ud655\uc815\ud558\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \ubca0\ub974\uba54\ub974\ub294 17\uc138\uae30 \ub124\ub35c\ub780\ub4dc \ud654\uac00\uc774\uba70 \uc870\uc6a9\ud55c \uc2e4\ub0b4\uc758 \uc778\ubb3c\uc744 \uadf8\ub9b0 \uc791\ud488\ub4e4\ub85c \uc54c\ub824\uc838 \uc788\ub2e4. \uc655\uc2e4\uc758 \ud070 \uc0ac\uac74\ubcf4\ub2e4 \ubc29 \uc548\uc758 \uc77c\uc0c1, \ud3b8\uc9c0\ub97c \uc77d\uac70\ub098 \uc77c\uc744 \ud558\ub294 \uc778\ubb3c \uac19\uc740 \uc7a5\uba74\uc5d0\uc11c \ud68c\ud654\uc758 \uc8fc\uc81c\ub97c \ucc3e\uc558\ub2e4. \uc774 \uc791\ud488\ub3c4 \uadf8\ub7f0 \uac10\uc0c1\uc758 \uc785\uad6c\uac00 \ub41c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uadf8\ub9bc\uc744 \ub2f9\uc2dc \ub124\ub35c\ub780\ub4dc\uc758 \ubaa8\ub4e0 \uac00\uc815\uc774 \uc774\ub7ac\ub2e4\ub294 \uc0ac\uc9c4 \uc99d\uac70\ucc98\ub7fc \uc77d\uc744 \uc218\ub294 \uc5c6\ub2e4. \ud654\uac00\ub294 \uc2e4\uc81c \uc0dd\ud65c\uc5d0\uc11c \ubcfc \uc218 \uc788\ub294 \uc18c\uc7ac\ub97c \uace0\ub974\uace0 \ubc30\uce58\ud558\uc5ec \ud654\uba74\uc744 \ub9cc\ub4e0\ub2e4. \uc77c\uc0c1\uc758 \uc7a5\uba74\uc774\uba74\uc11c \ub3d9\uc2dc\uc5d0 \uc798 \uad6c\uc131\ub41c \ud68c\ud654\ub77c\ub294 \ub450 \uc131\uaca9\uc744 \ud568\uaed8 \uc0dd\uac01\ud558\uba74 \uc88b\ub2e4. \uadf8\ub9bc \uc18d \uc5ec\uc778\uc774 \ud654\uac00\uc758 \uac00\uc871 \uc911 \ub204\uad6c\ub77c\uace0 \uc5ec\uae30\uc11c \ud655\uc815\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc5bc\uad74\uc744 \ubcf4\uace0 \uc774\ub984\uc744 \uc54c\uc544\ub9de\ud600\uc57c \uc791\ud488\uc744 \uc774\ud574\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\uae68\ub97c \ub465\uae00\uac8c \ubaa8\uc73c\uace0 \uc2dc\uc120\uc744 \ub0ae\ucd94\ub294 \uc790\uc138\ub9cc\uc73c\ub85c\ub3c4 \uc6b0\ub9ac\ub294 \uc9d1\uc911\ud558\ub294 \ubab8\uc758 \uacbd\ud5d8\uc744 \uc54c\uc544\ubcfc \uc218 \uc788\ub2e4. \ubc14\ub290\uc9c8\uc774\ub098 \uae00\uc4f0\uae30, \uc791\uc740 \ubb3c\uac74\uc744 \uace0\uce58\ub294 \uc77c\uc744 \ud574 \ubcf8 \uae30\uc5b5\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \ub0a8\uc774 \ubd80\ub974\uba74 \uc7a0\uae50 \uace0\uac1c\ub97c \ub4e4\uc9c0\ub9cc \uace7 \ub2e4\uc2dc \ub3cc\uc544\uac00\uace0 \uc2f6\uc740 \uadf8\ub7f0 \uc2dc\uac04\uc774 \uc788\ub2e4. \uc61b \uadf8\ub9bc \uc18d \uc0ac\ub78c\uc744 \uc624\ub298\uc758 \uc6b0\ub9ac\uc640 \ub611\uac19\ub2e4\uace0 \ub2e8\uc21c\ud654\ud558\uc9c0 \uc54a\uc73c\uba74\uc11c\ub3c4, \ubab8\uc758 \uc790\uc138\ub97c \ud1b5\ud574 \uac00\uae4c\uc6cc\uc9c8 \uc218\ub294 \uc788\ub2e4. \uc774 \uc791\ud488\uc744 \ubcfc \ub54c\ub294 \ubaa8\ub4e0 \ubd80\ubd84\uc758 \uc124\uba85\uc744 \ube60\uc9d0\uc5c6\uc774 \uc678\uc6b0\uae30\ubcf4\ub2e4 \uc138 \ubc88 \uc2dc\uc120\uc744 \uc62e\uaca8 \ubcf4\uc790. \ub178\ub780 \uc637\uc744 \ubcf4\uace0, \uc5bc\uad74\uacfc \uc190\uc758 \uc5f0\uacb0\uc744 \ubcf4\uace0, \ub9c8\uc9c0\ub9c9\uc73c\ub85c \uc8fc\ubcc0 \ubb3c\uac74\uacfc\uc758 \uad00\uacc4\ub97c \ubcf4\ub294 \uac83\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc61b \uc0c9\ucc44 \uc7ac\ud604 \ub3c4\ud310\uc5d0\uc11c\ub294 \ubbf8\uc138\ud55c \ud45c\uba74\ubcf4\ub2e4 \uc804\uccb4 \uad6c\uc131\uacfc \ud070 \uc0c9\uc758 \uad00\uacc4\ub97c \uc911\uc2ec\uc73c\ub85c \uc0b4\ud3b4\ubcf4\ub294 \ud3b8\uc774 \uc801\uc808\ud558\ub2e4. \ud55c \uc0ac\ub78c\uc758 \uc791\uc740 \uc77c\uc774 \uadf8\ub9bc\uc758 \uc911\uc2ec\uc5d0 \ub193\uc600\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uae30\uc5b5\ud558\uace0 \ub098\uba74 \uc870\uc6a9\ud55c \uc7a5\uba74\uc774 \uc2ec\uc2ec\ud558\uac8c\ub9cc \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ud070 \uc0ac\uac74\uc744 \uadf8\ub9b0 \uadf8\ub9bc\uc740 \uc0ac\uac74\uc758 \uacb0\uacfc\ub97c \uad81\uae08\ud558\uac8c \ud55c\ub2e4. \uc774 \uadf8\ub9bc\uc740 \ud55c \uc0ac\ub78c\uc774 \uc9c0\uae08 \ubcf4\ub0b4\uace0 \uc788\ub294 \uc2dc\uac04\uc744 \uc870\uae08 \ub354 \ubc14\ub77c\ubcf4\uac8c \ud55c\ub2e4. \uadf8 \ucc28\uc774\ub97c \ub290\ub07c\ub294 \uac83\uc774 \ubca0\ub974\uba54\ub974\ub97c \ub9cc\ub098\ub294 \uc88b\uc740 \uc2dc\uc791\uc774\ub2e4."}, {"id": "vigee-lebrun-mother-daughter", "title": "\ub538\uc744 \uc548\uc740 \uc790\ud654\uc0c1 \u2014 \ube44\uc81c \ub974 \ube0c\ub8c5\uc774 \ub0a8\uae34 \ub450 \uac00\uc9c0 \uc5bc\uad74", "summary": "\uc5c4\ub9c8\uc640 \uc544\uc774\uc758 \ubab8\uc9d3\uc744 \uc77d\uace0 \uc655\uc2e4\uc758 \ucd08\uc0c1\ud654\uac00\uc600\ub358 \uc5ec\uc131\uc758 \uc791\uc5c5\uacfc \uc774\ub3d9\uc744 \ud568\uaed8 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Art", "url": "stories/vigee-lebrun-mother-daughter/index.html", "image": "media/vigee-lebrun-mother-daughter.jpg", "alt": "\ube44\uc81c \ub974 \ube0c\ub8c5\uc774 \ub538\uc744 \ub450 \ud314\ub85c \uc548\uc740 \uc790\ud654\uc0c1. \ub450 \uc0ac\ub78c\uc758 \uc5bc\uad74\uc774 \uad00\uac1d\uc744 \ud5a5\ud569\ub2c8\ub2e4.", "text": "\ub538\uc744 \uc548\uc740 \uc790\ud654\uc0c1 \u2014 \ube44\uc81c \ub974 \ube0c\ub8c5\uc774 \ub0a8\uae34 \ub450 \uac00\uc9c0 \uc5bc\uad74 \uadf8\ub9bc \uc18d \uc5b4\uba38\ub2c8\ub97c \ub118\uc5b4, \uadf8\ub9bc\uc744 \uadf8\ub9b0 \uc0ac\ub78c\uc758 \uc0dd\uc560\uae4c\uc9c0 \uc5c4\ub9c8\uc640 \uc544\uc774\uc758 \ubab8\uc9d3\uc744 \uc77d\uace0 \uc655\uc2e4\uc758 \ucd08\uc0c1\ud654\uac00\uc600\ub358 \uc5ec\uc131\uc758 \uc791\uc5c5\uacfc \uc774\ub3d9\uc744 \ud568\uaed8 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Art \ubb38\ud654 \uc544\uc774\ub97c \ud488\uc5d0 \uc548\uc740 \uc5ec\uc778\uc774 \uc6b0\ub9ac\ub97c \ubc14\ub77c\ubcf8\ub2e4. \uc544\uc774\ub3c4 \uace0\uac1c\ub97c \ub3cc\ub824 \uad00\uac1d\uc744 \ud5a5\ud55c\ub2e4. \ub450 \ud314\uc740 \uc544\uc774\ub97c \ub2e8\ub2e8\ud788 \uac10\uc2f8\uace0 \uc637\uc758 \ub113\uc740 \uc8fc\ub984\uc740 \ub450 \ubab8\uc744 \ud558\ub098\ub85c \ubb36\ub294\ub2e4. \ucc98\uc74c \ubcf4\uba74 \ub2e4\uc815\ud55c \ubaa8\ub140\uc758 \ucd08\uc0c1\uc774\ub2e4. \uadf8\ub7f0\ub370 \uadf8\ub9bc \uc18d \uc5ec\uc778\uc740 \uc774 \uc791\ud488\uc744 \uadf8\ub9b0 \ud654\uac00 \uc790\uc2e0\uc774\ub2e4. \uc5d8\ub9ac\uc790\ubca0\ud2b8 \ub8e8\uc774\uc988 \ube44\uc81c \ub974 \ube0c\ub8c5\uc740 \uc790\uc2e0\uc744 \uadf8\ub9ac\uba74\uc11c \uc5b4\uba38\ub2c8\uc758 \ubaa8\uc2b5\ub3c4 \ud568\uaed8 \ub0a8\uacbc\ub2e4. \ubaa8\ub378\uacfc \uc791\uac00\uac00 \uac19\uc740 \uc0ac\ub78c\uc774\ub77c\ub294 \uc0ac\uc2e4\uc744 \uc54c\uace0 \ub098\uba74, \ud488 \uc548\uc758 \uad00\uacc4\ubfd0 \uc544\ub2c8\ub77c \uc774 \ud654\uba74\uc744 \ub9cc\ub4e4\uace0 \ub0b4\ub193\uc740 \uc0ac\ub78c\uc758 \uc0b6\uc5d0\ub3c4 \uad00\uc2ec\uc774 \uc0dd\uae34\ub2e4. \uba3c\uc800 \uc5b4\ub978\uacfc \uc544\uc774\uc758 \uc5bc\uad74\uc744 \uac01\uac01 \ubcf4\uace0 \uadf8 \uc0ac\uc774\uc758 \uac70\ub9ac\ub97c \uc0b4\ud3b4\ubcf4\uc790. \uc11c\ub85c \uae30\ub300\uace0 \uc788\uc73c\uba74\uc11c\ub3c4 \uc5bc\uad74\uc758 \ubc29\ud5a5\uc740 \uad00\uac1d\uc5d0\uac8c \uc5f4\ub824 \uc788\ub2e4. \ubcf4\ub294 \uc0ac\ub78c\uc740 \ub458\ub9cc\uc758 \uad00\uacc4\ub97c \ubc29\ud574\ud558\uae30\ubcf4\ub2e4 \uadf8 \uad00\uacc4\ub97c \ud568\uaed8 \ubcf4\ub3c4\ub85d \ucd08\ub300\ubc1b\ub294 \ub4ef\ud55c \ub290\ub08c\uc744 \ubc1b\uc744 \uc218 \uc788\ub2e4. \uadf8\ub2e4\uc74c\uc5d0\ub294 \uc5bc\uad74\uc5d0\uc11c \ud314\ub85c \ub208\uc744 \ub0b4\ub824 \ubcf4\uc790. \uc548\ucabd\uc73c\ub85c \ubaa8\uc774\ub294 \uc190\uacfc \ud314\uc774 \uc544\uc774\ub97c \ub458\ub7ec\uc2f8\uba70 \ud070 \ub369\uc5b4\ub9ac\ub97c \ub9cc\ub4e0\ub2e4. \ud45c\uc815\ub9cc \ub5bc\uc5b4 \ub193\uace0 \ubcfc \ub54c\ubcf4\ub2e4 \ubab8 \uc804\uccb4\uc758 \uc5f0\uacb0\uc774 \ubd84\uba85\ud574\uc9c4\ub2e4. \ub2e4\uc815\ud558\ub2e4\ub294 \uac10\uc815\uc774 \uc5bc\uad74\uc758 \ubbf8\uc18c \ud558\ub098\ub85c\ub9cc \ub9cc\ub4e4\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubc1d\uc740 \uc0c1\uc758\uc640 \ubcf4\ub78f\ube5b \uc18c\ub9e4, \ub178\ub780\ube5b \uce58\ub9c8\uac00 \uc5b4\ub450\uc6b4 \ubc30\uacbd\uc5d0\uc11c \uad6c\ubcc4\ub41c\ub2e4. \uc544\uc774\uc758 \ubc1d\uc740 \uc637\uc740 \uc5b4\ub978\uc758 \ubab8 \uac00\uae4c\uc774\uc5d0 \ub193\uc774\uba74\uc11c \ub450 \uc0ac\ub78c\uc744 \ub354 \ubc00\uc811\ud558\uac8c \ubcf4\uc774\uac8c \ud55c\ub2e4. \uc0c9\uc740 \uc758\uc0c1\uc744 \uc124\uba85\ud558\ub294 \uc815\ubcf4\uc774\uba74\uc11c \ud654\uba74\uc758 \uad00\uacc4\ub97c \ub9cc\ub4dc\ub294 \uc7ac\ub8cc\uc774\uae30\ub3c4 \ud558\ub2e4. \uc8fc\ub984\uc744 \ubaa8\ub450 \uc138\ubc00\ud558\uac8c \ud574\ub3c5\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub113\uc740 \ucc9c\uc758 \ud750\ub984\uc774 \uc5b4\ub514\ub85c \ud5a5\ud558\ub294\uc9c0, \uc190\uacfc \uc544\uc774\uc758 \ubab8\uc774 \uc5b4\ub5a4 \uc0c9\uba74 \uc704\uc5d0 \ub193\uc774\ub294\uc9c0 \ub530\ub77c\uac00 \ubcf4\uc790. \ucd08\uc0c1\ud654\uc5d0\uc11c \uc778\ubb3c\uc758 \uc5bc\uad74\uc744 \uc774\ud574\ud558\ub294 \uc77c\uacfc \ubab8\uc744 \ub458\ub7ec\uc2fc \uc0ac\ubb3c\uc744 \ubcf4\ub294 \uc77c\uc740 \ub530\ub85c \ub5a8\uc5b4\uc838 \uc788\uc9c0 \uc54a\ub2e4. \ud654\uac00\uac00 \uc790\uae30 \ubaa8\uc2b5\uc744 \uadf8\ub9ac\uba74 \uc6b0\ub9ac\ub294 \uadf8 \uc0ac\ub78c\uc758 \uc2e4\uc81c \uc5bc\uad74\uc744 \uc54c \uc218 \uc788\uc744 \uac83\uc774\ub77c \uae30\ub300\ud55c\ub2e4. \uadf8\ub7ec\ub098 \uc790\ud654\uc0c1\uc5d0\ub294 \uc5b4\ub5bb\uac8c \ubcf4\uc77c\uc9c0 \uace0\ub974\ub294 \uc120\ud0dd\ub3c4 \ub4e4\uc5b4\uac04\ub2e4. \uc5b4\ub5a4 \uc637\uc744 \uc785\uace0 \ub204\uad6c\uc640 \ud568\uaed8 \uc788\uc73c\uba70 \uad00\uac1d\uc744 \uc5b4\ub290 \ubc29\ud5a5\uc73c\ub85c \ubcfc \uac83\uc778\uac00. \ud654\uba74\uc740 \uadf8\ub7f0 \ud310\ub2e8\uc758 \uacb0\uacfc\ub2e4. \uc774 \uc791\ud488\uc5d0\uc11c \ud654\uac00\ub294 \ud63c\uc790 \ubd93\uc744 \ub4e0 \ubaa8\uc2b5 \ub300\uc2e0 \ub538\uacfc \ud568\uaed8 \ub098\ud0c0\ub09c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc791\uc5c5\ud558\ub294 \uc0ac\ub78c\uc758 \uc815\uccb4\uc131\uc774 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ud788\ub824 \uc5b4\uba38\ub2c8\uc758 \ubaa8\uc2b5\uc744 \uc774\ucc98\ub7fc \uad6c\uc131\ud574 \ubcf4\uc5ec \uc900 \uc8fc\uccb4\uac00 \ubc14\ub85c \ud654\uac00\ub77c\ub294 \uc0ac\uc2e4\uc774 \ub450 \uc5ed\ud560\uc744 \ud568\uaed8 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uc5b4\ub290 \ud55c\ucabd\ub9cc\uc774 \uadf8 \uc0ac\ub78c\uc758 \uc9c4\uc9dc \ubaa8\uc2b5\uc774\ub77c\uace0 \uace0\ub97c \ud544\uc694\ub294 \uc5c6\ub2e4. \ube44\uc81c \ub974 \ube0c\ub8c5\uc740 1755\ub144 \ud30c\ub9ac\uc5d0\uc11c \ud0dc\uc5b4\ub0ac\uace0 \uc544\ubc84\uc9c0\ub3c4 \ud654\uac00\uc600\ub2e4. \ud68c\uace0\ub85d\uc5d0\ub294 \uadf8\ub9bc\uc744 \ubc30\uc6b0\ub358 \uc77c\uacfc \ucd08\uc0c1 \uc8fc\ubb38\uc744 \ubc1b\uc73c\uba70 \uc0dd\ud65c\uc744 \uafb8\ub9ac\ub358 \uacbd\ud5d8\uc774 \ub0a8\uc544 \uc788\ub2e4. \uc7ac\ub2a5 \uc788\ub294 \uc544\uc774\uac00 \uace7\ubc14\ub85c \uc720\uba85\ud55c \uc655\uc2e4 \ud654\uac00\uac00 \ub418\uc5c8\ub2e4\ub294 \ud55c \uc904 \uc0ac\uc774\uc5d0\ub294 \uc0ac\ub78c\uc744 \ub9cc\ub098\uace0 \uadf8\ub9bc\uc744 \uc644\uc131\ud558\uba70 \uc2e0\ub8b0\ub97c \uc5bb\ub294 \uc77c\uc774 \ub4e4\uc5b4 \uc788\uc5c8\ub2e4. \uadf8\ub294 \ub9c8\ub9ac \uc559\ud22c\uc544\ub124\ud2b8\ub97c \ube44\ub86f\ud55c \uc655\uc2e4\uacfc \uadc0\uc871\uc758 \ucd08\uc0c1\uc744 \uadf8\ub838\uace0 \uc544\uce74\ub370\ubbf8\uc5d0\ub3c4 \ubc1b\uc544\ub4e4\uc5ec\uc84c\ub2e4. \ud68c\uace0\ub85d\uc740 \uadf8 \uacfc\uc815\uc5d0 \ub2e4\ub978 \ud654\uac00\ub4e4\uc758 \uc9c0\uc9c0\uc640 \ubc18\ub300\uac00 \uc788\uc5c8\ub2e4\uace0 \uc804\ud55c\ub2e4. \uc804\ubb38 \ud654\uac00\ub85c \uc778\uc815\ubc1b\ub294 \uc77c\uc740 \uc88b\uc740 \uadf8\ub9bc\uc744 \uadf8\ub9ac\ub294 \ub2a5\ub825\ub9cc\uc73c\ub85c \uc800\uc808\ub85c \ub05d\ub098\ub294 \ubb38\uc81c\uac00 \uc544\ub2c8\uc5c8\ub2e4. \uc655\uc2e4\uc758 \uc8fc\ubb38\uc740 \uc131\uacf5\uacfc \uba85\uc131\uc744 \uac00\uc838\ub2e4\uc8fc\uc5c8\uc9c0\ub9cc \uc815\uce58\uc801 \uaca9\ubcc0 \uc18d\uc5d0\uc11c\ub294 \uc704\ud5d8\ud55c \uad00\uacc4\uac00 \ub420 \uc218\ub3c4 \uc788\uc5c8\ub2e4. \ud504\ub791\uc2a4\ud601\uba85\uae30\uc758 \ubd88\uc548 \uc18d\uc5d0\uc11c \uadf8\ub294 \ub538\uc744 \ub370\ub9ac\uace0 \ud30c\ub9ac\ub97c \ub5a0\ub09c\ub2e4. \ud68c\uace0\ub85d\uc740 \ub2f9\uc2dc\uc758 \ub450\ub824\uc6c0\uacfc \uc774\ub3d9\uc744 \uc790\uc2e0\uc758 \uc2dc\uc120\uc73c\ub85c \uc790\uc138\ud788 \uc804\ud55c\ub2e4. \uc774 \uae30\ub85d\uc744 \uc77d\uc744 \ub54c\ub294 \uc791\uac00\uac00 \ud2b9\uc815 \uc0ac\ud68c\uc801 \uad00\uacc4\uc640 \uacbd\ud5d8\uc744 \uac00\uc9c4 \uc0ac\ub78c\uc774\uc5c8\ub2e4\ub294 \uc810\ub3c4 \uae30\uc5b5\ud558\uba74 \uc88b\ub2e4. \ud68c\uace0\ub85d\uc740 \uc911\uc694\ud55c \uc9c1\uc811 \uae30\ub85d\uc774\uc9c0\ub9cc \ud601\uba85 \uc804\uccb4\ub97c \uc911\ub9bd\uc801\uc73c\ub85c \uc815\ub9ac\ud55c \uad50\uacfc\uc11c\ub294 \uc544\ub2c8\ub2e4. \uc790\uae30 \uc0b6\uc744 \uc124\uba85\ud558\ub294 \ubaa9\uc18c\ub9ac\uc640 \ub354 \ub113\uc740 \uc5ed\uc0ac\ub97c \uac19\uc740 \uac83\uc73c\ub85c \ub9cc\ub4e4\uc9c0 \uc54a\uace0 \uc77d\uc744 \uc218 \uc788\ub2e4. \uc774\ud0c8\ub9ac\uc544\uc640 \uc624\uc2a4\ud2b8\ub9ac\uc544, \ub7ec\uc2dc\uc544 \ub4f1 \uc5ec\ub7ec \uacf3\uc744 \uac70\uce58\ub294 \ub3d9\uc548\uc5d0\ub3c4 \uadf8\ub294 \ucd08\uc0c1\ud654\ub97c \uadf8\ub838\ub2e4. \ub5a0\ub0a8\uc774 \uace7 \uc791\uc5c5\uc758 \ub05d\uc774 \ub41c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc758\ub8b0\uc778\uc744 \ub9cc\ub098\uace0 \uc790\uc2e0\uc758 \ud3c9\ud310\uc744 \uc774\uc5b4 \uac00\ub294 \ub2a5\ub825\uc740 \uadf8\uc758 \uc0dd\uc560\uc5d0\uc11c \ud070 \ube44\uc911\uc744 \ucc28\uc9c0\ud55c\ub2e4. \uc608\uc220\uac00\uc758 \uc0b6\uc5d0 \uc774\ub3d9\uacfc \uc77c\uc758 \uc870\uac74\uc774 \ud568\uaed8 \ub4e4\uc5b4 \uc788\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubaa8\ub4e0 \uc774\ub3d9\uc744 \ud654\ub824\ud55c \uc5ec\ud589\uc73c\ub85c\ub9cc \uc77d\uc744 \uc218\ub294 \uc5c6\ub2e4. \uc815\uce58\uc801 \ubd88\uc548\uacfc \uac00\uc871\uc758 \uc0ac\uc815, \ud0c0\uc9c0\uc758 \uc0dd\ud65c\ub3c4 \uadf8 \uc548\uc5d0 \uc788\ub2e4. \uc131\uacf5\ud55c \ud654\uac00\ub77c\ub294 \ub9d0\uacfc \ubd88\uc548\uc815\ud55c \uc2dc\uac04\uc744 \ubcf4\ub0b8 \uc0ac\ub78c\uc774\ub77c\ub294 \ub9d0\uc740 \ud55c \uc0dd\uc560 \uc548\uc5d0\uc11c \ud568\uaed8 \uc131\ub9bd\ud560 \uc218 \uc788\ub2e4. \ub530\ub73b\ud55c \ud3ec\uc639\uc744 \ubcf4\uace0 \ub450 \uc0ac\ub78c\uc758 \uad00\uacc4\uac00 \ud3c9\uc0dd \uc5b8\uc81c\ub098 \uac19\uc558\uc744 \uac83\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uae30 \uc27d\ub2e4. \ud558\uc9c0\ub9cc \ud55c \uc7a5\uc758 \ucd08\uc0c1\uc740 \ud55c \uc0dd\uc560 \uc804\uccb4\uc758 \uae30\ub85d\uc774 \uc544\ub2c8\ub2e4. \ud68c\uace0\ub85d\uc5d0\ub294 \ub538\uc758 \uc131\uc7a5\uacfc \uacb0\ud63c, \uac00\uc871 \uad00\uacc4\uc758 \uc5b4\ub824\uc6c0\ub3c4 \ub4f1\uc7a5\ud55c\ub2e4. \ud654\uba74\uc758 \ub2e4\uc815\ud568\uc744 \uc0ac\uc2e4\uc774 \uc544\ub2cc \uac83\uc73c\ub85c \uc9c0\uc6b8 \ud544\uc694\ub3c4, \uadf8\uac83\uc73c\ub85c \ubaa8\ub4e0 \uc2dc\uac04\uc744 \uc124\uba85\ud560 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \uc624\ud788\ub824 \uadf8\ub9bc\uacfc \uc0dd\uc560\ub97c \ud568\uaed8 \ubcf4\uba74 \ucd08\uc0c1\ud654\uac00 \ubb34\uc5c7\uc744 \ubcf4\uc5ec \uc8fc\uace0 \ubb34\uc5c7\uc744 \ub0a8\uaca8 \ub450\ub294\uc9c0 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \uadf8\ub9bc\uc744 \ubcf4\uace0 \ub9c8\uc74c\uc744 \ub290\ub080 \ub2e4\uc74c, \uadf8 \ub290\ub08c\uacfc \uc5ed\uc0ac\uc801 \uc0ac\uc2e4\uc774 \uc11c\ub85c \ub2e4\ub978 \uce35\uc704\uc784\uc744 \uc544\ub294 \uac83\uc740 \uac10\uc0c1\uc744 \ucc28\uac11\uac8c \ub9cc\ub4dc\ub294 \uc77c\uc774 \uc544\ub2c8\ub2e4. \ud55c \uc0ac\ub78c\uc744 \uc9c0\ub098\uce58\uac8c \ub2e8\uc21c\ud558\uac8c \ub9cc\ub4e4\uc9c0 \uc54a\ub294 \ubc29\ubc95\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 \ub3c4\ud310\uc740 \uc61b \ub8e8\ube0c\ub974 \ub3c4\ub85d\uc5d0 \uc218\ub85d\ub41c \uc791\uac00\uc640 \ub538\uc758 \uc790\ud654\uc0c1 \uc911 \ud55c \uc810\uc774\ub2e4. \ube44\uc2b7\ud55c \uc8fc\uc81c\uc758 \ub2e4\ub978 \uc790\ud654\uc0c1\uacfc\ub294 \uad6c\ubd84\ud574\uc57c \ud558\uba70, \uc61b \uc778\uc1c4\uc758 \uc0c9\uc774 \ud604\uc7ac\uc758 \uc2e4\ubb3c\uacfc \uc644\uc804\ud788 \uac19\ub2e4\uace0 \ubcfc \uc218\ub294 \uc5c6\ub2e4. \uc5ec\uae30\uc11c\ub294 \ub450 \uc5bc\uad74\uacfc \ud314, \uc637\uc774 \ub9cc\ub4dc\ub294 \uc804\uccb4 \uad00\uacc4\ub97c \uc0b4\ud3b4\ubcf4\uc558\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc544\uc774\ub97c \uc548\uc740 \uc5b4\uba38\ub2c8\uac00 \ubcf4\uc600\ub2e4\uba74, \ub2e4\uc2dc \ubcfc \ub54c\ub294 \uadf8 \uc7a5\uba74\uc744 \uc124\uacc4\ud558\uace0 \uc9c1\uc811 \uadf8\ub824 \ub2e4\ub978 \uc0ac\ub78c \uc55e\uc5d0 \ub0b4\ub193\uc740 \ud654\uac00\ub3c4 \ubcf4\uc77c \uac83\uc774\ub2e4. \ub2e4\uc815\ud55c \uad00\uacc4\uc640 \uc804\ubb38\uc801\uc778 \uc791\uc5c5\uc740 \ud55c \ud654\uba74 \uc548\uc5d0 \ud568\uaed8 \uc788\ub2e4. \ube44\uc81c \ub974 \ube0c\ub8c5\uc758 \uc790\ud654\uc0c1\uc740 \uc0ac\ub78c\uc744 \ud55c \uac00\uc9c0 \uc5ed\ud560\ub85c\ub9cc \uae30\uc5b5\ud558\uc9c0 \uc54a\ub3c4\ub85d \uc2dc\uc120\uc744 \ub113\ud600 \uc900\ub2e4."}, {"id": "vivaldi-four-seasons-spring", "title": "\ube44\ubc1c\ub514 \uc0ac\uacc4 \u2014 \uc0c8\uc18c\ub9ac\uc5d0\uc11c \ud3ed\ud48d\uacfc \uaca8\uc6b8\uc758 \ubd88\uac00\uae4c\uc9c0", "summary": "\ubd04\u00b7\uc5ec\ub984\u00b7\uac00\uc744\u00b7\uaca8\uc6b8\uc758 \uc2dc\uc640 \uc545\uc7a5\ubcc4 \uc7a5\uba74\uc744 \ub530\ub77c \ube44\ubc1c\ub514\uc758 \ub124 \ud611\uc8fc\uace1\uc744 \ub4e3\uc2b5\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Music", "url": "stories/vivaldi-four-seasons-spring/index.html", "image": "media/vivaldi-four-seasons-spring-scene-20261030.png", "alt": "\ucc3d\uac00\uc758 \ubc14\uc774\uc62c\ub9b0\uacfc \ud65c \ub108\uba38\ub85c \ubd04\uaf43\u00b7\uc5ec\ub984\uc758 \ube44\u00b7\uac00\uc744 \ub2e8\ud48d\u00b7\uaca8\uc6b8 \ub208\uc774 \uc774\uc5b4\uc9c0\ub294 \uc2dc\uc801\uc778 \uc0c1\uc0c1 \ud48d\uacbd.", "text": "\ube44\ubc1c\ub514 \uc0ac\uacc4 \u2014 \uc0c8\uc18c\ub9ac\uc5d0\uc11c \ud3ed\ud48d\uacfc \uaca8\uc6b8\uc758 \ubd88\uac00\uae4c\uc9c0 \uc5f4\ub450 \uc545\uc7a5 \uc18d \ub124 \uacc4\uc808\uc744 \uc2dc\uc640 \ud568\uaed8 \ub4e3\ub294 \uae38\uc7a1\uc774 \ubd04\u00b7\uc5ec\ub984\u00b7\uac00\uc744\u00b7\uaca8\uc6b8\uc758 \uc2dc\uc640 \uc545\uc7a5\ubcc4 \uc7a5\uba74\uc744 \ub530\ub77c \ube44\ubc1c\ub514\uc758 \ub124 \ud611\uc8fc\uace1\uc744 \ub4e3\uc2b5\ub2c8\ub2e4. Music \ubb38\ud654 \ubd04\uc5d0\ub294 \uc0c8\uac00 \uc6b8\uace0, \uc5ec\ub984\uc5d0\ub294 \ud3ed\ud48d\uc774 \ubab0\ub824\uc624\uba70, \uac00\uc744\uc5d0\ub294 \uc0ac\ub78c\ub4e4\uc774 \uc220\uc744 \ub9c8\uc2dc\uace0 \ucda4\ucd98\ub2e4. \uaca8\uc6b8\uc5d0\ub294 \ucd94\uc704\uc5d0 \uc774\ub97c \ub5a8\ub2e4\uac00 \ub530\ub73b\ud55c \ubd88\uac00\ub85c \ub4e4\uc5b4\uac04\ub2e4. \ube44\ubc1c\ub514\uc758 \u300a\uc0ac\uacc4\u300b\ub294 \uc544\ub984\ub2e4\uc6b4 \uc790\uc5f0 \ud48d\uacbd\ub9cc \ubaa8\uc544 \ub193\uc740 \uc74c\uc545\uc774 \uc544\ub2c8\ub2e4. \uadf8 \uacc4\uc808\uc744 \uc0b4\uc544\uac00\ub294 \ubab8\uacfc \uc0dd\ud65c\uc774 \ud568\uaed8 \ub4e4\uc5b4 \uc788\ub2e4. \uacc4\uc808\uc758 \uc81c\ubaa9\uc744 \uc54c\uace0 \ub4e3\ub294 \uac83\uc5d0\uc11c \ud55c \uac78\uc74c \ub354 \ub098\uc544\uac00, \uac01 \uace1\uacfc \ud568\uaed8 \uc804\ud574\uc9c0\ub294 \uc9e7\uc740 \uc2dc\ub97c \uae38\uc7a1\uc774\ub85c \uc0bc\uc544 \ubcf4\uc790. \uc18c\ub9ac\uc758 \ubaa8\ub4e0 \uc815\ub2f5\uc744 \ub9de\ud788\ub294 \uacf5\ubd80\uac00 \uc544\ub2c8\ub77c, \uc775\uc219\ud55c \uc120\uc728 \uc18d\uc5d0\uc11c \uc7a5\uba74\uc744 \uc870\uae08 \ub354 \ubc1c\uacac\ud558\ub294 \uac10\uc0c1\uc774\ub2e4. \ubd04\u00b7\uc5ec\ub984\u00b7\uac00\uc744\u00b7\uaca8\uc6b8\uc740 \uac01\uac01 \ub3c5\ub9bd\ub41c \ubc14\uc774\uc62c\ub9b0 \ud611\uc8fc\uace1\uc774\ub2e4. \uc791\ud488\ubc88\ud638 8\uc758 \uccab \ub124 \uace1\uc774\uba70, \uc545\ubcf4 \uc790\ub8cc\ub294 1725\ub144\uc744 \uc81c\uc2dc\ud55c\ub2e4. \uac01 \ud611\uc8fc\uace1\uc740 \uc138 \uc545\uc7a5\uc73c\ub85c \uc774\ub8e8\uc5b4\uc838 \uc788\uc73c\ubbc0\ub85c \ubaa8\ub450 \ud569\ud558\uba74 \uc5f4\ub450 \uc545\uc7a5\uc774\ub2e4. \ubcf4\ud1b5 \ube60\ub978 \ud750\ub984, \ub290\ub9b0 \ud750\ub984, \ub2e4\uc2dc \ube60\ub978 \ud750\ub984\uc744 \ub530\ub77c \ud55c \uacc4\uc808\uc774 \ud3bc\uccd0\uc9c4\ub2e4. \ud611\uc8fc\uace1\uc5d0\uc11c\ub294 \ub3c5\uc8fc \uc545\uae30\uc640 \ud569\uc8fc\uac00 \uc11c\ub85c \uad00\uacc4\ub97c \ub9fa\ub294\ub2e4. \uc5ec\uae30\uc11c\ub294 \ubc14\uc774\uc62c\ub9b0 \ub3c5\uc8fc\uc758 \ub0a0\ub835\ud55c \uc6c0\uc9c1\uc784\uacfc \uc5ec\ub7ec \ud604\uc545\uae30\uac00 \ud568\uaed8 \ub9cc\ub4dc\ub294 \ub369\uc5b4\ub9ac\ub97c \ubc88\uac08\uc544 \ub4e4\uc5b4 \ubcf4\uc790. \ud63c\uc790 \ub098\uc11c\ub294 \uc18c\ub9ac\uc640 \ud568\uaed8 \ub418\ub3cc\uc544\uc624\ub294 \uc18c\ub9ac\uc758 \ucc28\uc774\ub97c \uc54c\uc544\ucc28\ub9ac\uae30\ub9cc \ud574\ub3c4 \uc74c\uc545\uc758 \uae38\uc774 \uaf64 \ubd84\uba85\ud574\uc9c4\ub2e4. \ub124 \uacc4\uc808\uc5d0\ub294 \uc18c\ub124\ud2b8\ub77c\ub294 \ud615\uc2dd\uc758 \uc9e7\uc740 \uc2dc\uac00 \ud568\uaed8 \uc804\ud574\uc9c0\uace0, \ud655\uc778\ud55c \uc545\ubcf4 \uc790\ub8cc\ub294 \uc2dc\uc758 \uad6c\uc808\uc744 \uc545\uc7a5\uc758 \ud2b9\uc815 \ubd80\ubd84\uc5d0 \ubc30\uce58\ud55c\ub2e4. \uc0c8, \ubc14\ub78c, \ucc9c\ub465, \ucda4, \uc5bc\uc74c\uae38 \uac19\uc740 \uc7a5\uba74\uc774 \ub9c9\uc5f0\ud55c \uc0c1\uc0c1\ub9cc\uc740 \uc544\ub2c8\ub77c\ub294 \ub73b\uc774\ub2e4. \uc74c\uc545\uacfc \uc5f0\uacb0\ub41c \uae00\uc758 \ub2e8\uc11c\uac00 \uc2e4\uc81c\ub85c \ub0a8\uc544 \uc788\ub2e4. \ub2e4\ub9cc \ubaa8\ub4e0 \uc2dc\ub97c \ube44\ubc1c\ub514\uac00 \uc9c1\uc811 \uc9c0\uc5c8\ub2e4\uace0 \uc5ec\uae30\uc11c \ud655\uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc774\ubc88\uc5d0 \ud655\uc778\ud55c \uadfc\uac70\ub294 \uc2dc\uc758 \ub0b4\uc6a9\uacfc \uc545\ubcf4 \uc548\uc758 \ub300\uc751\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\uc740 \ubc14\uc774\uc62c\ub9b0\uacfc \uc0ac\uacc4\uc808\uc758 \ud48d\uacbd\uc744 \uc2dc\uc801\uc73c\ub85c \uc5f0\uacb0\ud55c AI \uc0bd\ud654\ub2e4. \ud2b9\uc815 \uacf5\uc5f0\uc774\ub098 \uc2e4\uc81c \ud55c \uc7a5\uc18c\ub97c \uc7ac\ud604\ud55c \uadf8\ub9bc\uc740 \uc544\ub2c8\ub2e4. \ub124 \uacc4\uc808\uc758 \uc774\uc57c\uae30\ub294 \uc544\ub798\uc5d0\uc11c \ucc28\ub840\ub85c \ub9cc\ub098 \ubcf4\uc790. \uccab \uc545\uc7a5\uc758 \uc2dc\ub294 \ubd04\uc758 \ub3c4\ucc29\uacfc \uc0c8\ub4e4\uc758 \ub178\ub798, \uc2dc\ub0c7\ubb3c\uc758 \ud750\ub984\uc73c\ub85c \uc2dc\uc791\ud55c\ub2e4. \ubc14\uc774\uc62c\ub9b0\uc758 \uc9e7\uc740 \uc6c0\uc9c1\uc784\uc744 \uc0c8\uc18c\ub9ac\ucc98\ub7fc \ub4e4\uc5b4 \ubcf4\uace0, \ud569\uc8fc\uac00 \ub3cc\uc544\uc62c \ub54c\ub9c8\ub2e4 \ubc1d\uc740 \ubc14\uae65 \ud48d\uacbd\uc774 \ub2e4\uc2dc \uc5f4\ub9ac\ub294 \ub290\ub08c\uc744 \ubc1b\uc544\ub3c4 \uc88b\ub2e4. \uc774\ub54c \ubc18\ubcf5\ub418\ub294 \ubd80\ubd84\uc740 \uc0c8\ub85c\uc6b4 \uc7a5\uba74 \uc0ac\uc774\uc5d0\uc11c \uae38\uc744 \uc783\uc9c0 \uc54a\uac8c \ud574 \uc8fc\ub294 \ud45c\uc9c0\ucc98\ub7fc \ub4e4\uc744 \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \ud558\ub298\uc740 \uacc4\uc18d \ub9d1\uc9c0 \uc54a\ub2e4. \uc2dc\uc5d0\ub294 \uad6c\ub984\uacfc \ubc88\uac1c, \ucc9c\ub465\uc774 \ub098\ud0c0\ub098\uace0 \uadf8 \ub4a4 \uc0c8\ub4e4\uc774 \ub2e4\uc2dc \ub178\ub798\ud55c\ub2e4. \uadf8\ub798\uc11c \uac11\uc790\uae30 \uc74c\uc545\uc774 \uae34\ubc15\ud574\uc9c8 \ub54c \u2018\ubd04\uc778\ub370 \uc65c \uc774\ub807\uac8c \uac70\uce60\uae4c\u2019\ub77c\uace0 \uc0dd\uac01\ud558\uae30\ubcf4\ub2e4 \ud55c \uacc4\uc808 \uc548\uc5d0\ub3c4 \ub0a0\uc528\uc758 \ubcc0\ud654\uac00 \uc788\ub2e4\ub294 \uc810\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \ubc1d\uc740 \uc7a5\uba74\uc774 \ub3cc\uc544\uc62c \ub54c\uc758 \ubc18\uac00\uc6c0\ub3c4 \ub354 \ucee4\uc9c4\ub2e4. \ub458\uc9f8 \uc545\uc7a5\uc758 \uc2dc\uc5d0\ub294 \ud480\uacfc \ub098\ubb47\uc78e\uc758 \uc6c0\uc9c1\uc784, \uc7a0\ub4e0 \ubaa9\ub3d9, \uacc1\uc758 \uac1c\uac00 \ub4f1\uc7a5\ud55c\ub2e4. \ud070 \uc0ac\uac74\uc774 \ubc8c\uc5b4\uc9c0\ub358 \ubc14\uae65\uc5d0\uc11c \ud55c \uc0ac\ub78c\uc758 \ud734\uc2dd\uc73c\ub85c \uc2dc\uc120\uc774 \uac00\uae4c\uc6cc\uc9c4\ub2e4. \uc74c\uc545\uc744 \ub4e4\uc744 \ub54c\ub3c4 \uacc4\uc18d \uc0c8 \uc7a5\uba74\uc744 \ucc3e\uc73c\ub824 \ud558\uae30\ubcf4\ub2e4 \uc704\ucabd \uc120\uc728\uacfc \uadf8 \uc544\ub798 \uc774\uc5b4\uc9c0\ub294 \uc18c\ub9ac\uc758 \uce35\uc744 \ucc28\ubd84\ud788 \ub4e4\uc5b4 \ubcf4\uc790. \uc14b\uc9f8 \uc545\uc7a5\uc740 \ubaa9\ub3d9\ub4e4\uacfc \ub2d8\ud504\ub4e4\uc758 \ubaa9\uac00\uc801\uc778 \ucda4\uc73c\ub85c \uc774\uc5b4\uc9c4\ub2e4. \ubd04\uc740 \uc790\uc5f0\uc774 \uae68\uc5b4\ub098\ub294 \uc7a5\uba74\uc5d0\uc11c \uc2dc\uc791\ud574 \uc26c\ub294 \uc2dc\uac04\uacfc \uc0ac\ub78c\ub4e4\uc758 \uc6c0\uc9c1\uc784\uae4c\uc9c0 \ud488\ub294\ub2e4. \uccab \uc545\uc7a5\uc758 \uc720\uba85\ud55c \ubd80\ubd84\ub9cc \ub4e3\uace0 \uba48\ucd94\uba74 \uc774 \uacc4\uc808\uc758 \ud558\ub8e8 \uac00\uc6b4\ub370 \uc0c1\ub2f9\ud55c \ubd80\ubd84\uc744 \ub193\uce58\ub294 \uc148\uc774\ub2e4. \uc5ec\ub984\uc758 \uc2dc\ub294 \ub728\uac70\uc6b4 \ud587\ube5b \uc544\ub798 \uc0ac\ub78c\uacfc \uac00\ucd95\uc774 \uc9c0\uce58\ub294 \ubaa8\uc2b5\uc73c\ub85c \uc2dc\uc791\ud55c\ub2e4. \uc0c8\ub4e4\uc758 \uc18c\ub9ac\uc640 \ubd80\ub4dc\ub7ec\uc6b4 \ubc14\ub78c\uc774 \ub098\ud0c0\ub098\uc9c0\ub9cc \uac11\uc791\uc2a4\ub7ec\uc6b4 \ubd81\ud48d\uc774 \ubd88\uace0, \ubaa9\ub3d9\uc740 \ub2e4\uac00\uc62c \ud3ed\ud48d\uc744 \uac71\uc815\ud55c\ub2e4. \uc624\ub298 \uc6b0\ub9ac\uac00 \uc5ec\ub984\uc774\ub77c\ub294 \ub9d0\uc5d0\uc11c \ub5a0\uc62c\ub9ac\ub294 \ud574\ubcc0\uc758 \ud734\uac00\uc640\ub294 \ub2e4\ub978 \uc0dd\ud65c\uc758 \uac10\uac01\uc774\ub2e4. \ub290\ub9b0 \ub458\uc9f8 \uc545\uc7a5\uc5d0\uc11c\ub3c4 \uc644\uc804\ud788 \uc274 \uc218\ub294 \uc5c6\ub2e4. \ubc88\uac1c\uc640 \ucc9c\ub465\uc5d0 \ub300\ud55c \ub450\ub824\uc6c0, \ud30c\ub9ac\uc640 \ubc8c\ub808\ub4e4\uc774 \ud734\uc2dd\uc744 \ubc29\ud574\ud55c\ub2e4. \uc14b\uc9f8 \uc545\uc7a5\uc5d0\uc11c\ub294 \uacb0\uad6d \ud3ed\ud48d\uc774 \ud130\uc9c0\uace0 \uc6b0\ubc15\uc774 \uace1\uc2dd\uc744 \ud574\uce5c\ub2e4. \ube60\ub978 \uc74c\ub4e4\uc774 \uc3df\uc544\uc9c0\ub294 \uc21c\uac04\uc758 \ud654\ub824\ud568\uacfc \ud568\uaed8, \uadf8 \ub0a0\uc528\ub97c \uacac\ub38c\uc57c \ud558\ub294 \uc0ac\ub78c\uc758 \uac71\uc815\uc744 \uc0dd\uac01\ud558\uba74 \uc74c\uc545\uc758 \ud45c\uc815\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uac00\uc744\uc740 \uc218\ud655\uc744 \uae30\ubed0\ud558\ub294 \ub178\ub798\uc640 \ucda4\uc73c\ub85c \uc2dc\uc791\ud55c\ub2e4. \uc220\uc5d0 \ucde8\ud55c \uc0ac\ub78c\ub4e4\uc774 \uc7a0\uc5d0 \ube60\uc838\ub4dc\ub294 \ubaa8\uc2b5\ub3c4 \uc2dc\uc5d0 \ub098\uc628\ub2e4. \uc74c\uc545\uc758 \ud65c\uae30\uc640 \uc6c0\uc9c1\uc784\uc774 \uac00\ub77c\uc549\ub294 \ubd80\ubd84\uc744 \ubc88\uac08\uc544 \ub4e4\uc73c\uba74 \ub2e8\uc9c0 \u2018\ud48d\uc694\ub85c\uc6b4 \uac00\uc744\u2019\uc774\ub77c\ub294 \ud55c \ub2e8\uc5b4\ubcf4\ub2e4 \uad6c\uccb4\uc801\uc778 \uc0dd\ud65c \uc7a5\uba74\uc774 \ub5a0\uc624\ub978\ub2e4. \ub458\uc9f8 \uc545\uc7a5\uc5d0\ub294 \uc7a0\uc758 \uc2dc\uac04\uc774 \uc774\uc5b4\uc9c0\uace0, \uc14b\uc9f8\uc5d0\uc11c\ub294 \uc0c8\ubcbd\uc758 \uc0ac\ub0e5\uc774 \uc2dc\uc791\ub41c\ub2e4. \ubfd4\ud53c\ub9ac\uc640 \ucd1d, \uac1c\uc640 \ucad3\uae30\ub294 \uc9d0\uc2b9\uc774 \ub4f1\uc7a5\ud55c\ub2e4. \ub9c8\uc9c0\ub9c9\uae4c\uc9c0 \ud3c9\ud654\ub85c\uc6b4 \uc804\uc6d0 \ud48d\uacbd\ub9cc \uc774\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ub298\uc758 \uac10\uac01\uc73c\ub85c \ubd88\ud3b8\ud558\uac8c \ub290\ub084 \uc218 \uc788\ub294 \uc7a5\uba74\ub3c4 \ud3ec\ud568\ud574, \ub2f9\uc2dc\uc758 \uacc4\uc808 \uc0dd\ud65c\uc744 \ub2f4\uc740 \uc74c\uc545\uc73c\ub85c \ub9cc\ub098\uba74 \uc88b\ub2e4. \uccab \uc545\uc7a5\uc758 \uc2dc\uc5d0\ub294 \ucc28\uac00\uc6b4 \ubc14\ub78c \uc18d\uc5d0\uc11c \ubab8\uc744 \ub5a8\uace0 \ubc1c\uc744 \uad6c\ub974\uba70 \uc774\ub97c \ub5a0\ub294 \uc0ac\ub78c\uc774 \ub098\uc628\ub2e4. \ubc18\ubcf5\ub418\ub294 \uc9e7\uc740 \uc18c\ub9ac\ub97c \ub4e4\uc73c\uba74 \ucd94\uc704\uc5d0 \uc6c0\uce20\ub7ec\ub4e0 \ubab8\uc758 \uc6c0\uc9c1\uc784\uc744 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \uc7a5\uba74\uc744 \uc54c\uace0 \ub098\uba74 \uaca8\uc6b8\uc774 \ub208\uc758 \uc544\ub984\ub2e4\uc6c0\ub9cc\uc740 \uc544\ub2c8\ub77c\ub294 \uc0ac\uc2e4\uc774 \uadc0\ub85c\ub3c4 \uac00\uae4c\uc6cc\uc9c4\ub2e4. \ub458\uc9f8 \uc545\uc7a5\uc5d0\uc11c\ub294 \ubd88\uac00\uc5d0\uc11c \uc870\uc6a9\ud558\uace0 \ud3b8\uc548\ud55c \uc2dc\uac04\uc744 \ubcf4\ub0b4\ub294 \ubc18\uba74 \ubc16\uc5d0\ub294 \ube44\uac00 \ub0b4\ub9b0\ub2e4. \uc2e4\ub0b4\uc640 \uc2e4\uc678\uc758 \ub300\ube44\uac00 \uc774 \uc9e7\uc740 \uc545\uc7a5\uc758 \uc990\uac70\uc6c0\uc774\ub2e4. \uc14b\uc9f8\uc5d0\uc11c\ub294 \uc5bc\uc74c \uc704\ub97c \uc870\uc2ec\ud788 \uac77\ub2e4\uac00 \ubbf8\ub044\ub7ec\uc9c0\uace0, \ub2e4\uc2dc \ub2ec\ub9ac\ub2e4\uac00 \uc5bc\uc74c\uc774 \uac08\ub77c\uc9c0\uba70 \ubc14\ub78c\ub4e4\uc774 \ub9de\uc120\ub2e4. \uaca8\uc6b8\uc740 \uac00\ub9cc\ud788 \uc5bc\uc5b4\ubd99\uc740 \ud48d\uacbd\uc774 \uc544\ub2c8\ub77c \uc870\uc2ec\uc2a4\ub7ec\uc6b4 \uac78\uc74c\uacfc \uac11\uc791\uc2a4\ub7ec\uc6b4 \uc6c0\uc9c1\uc784\uc73c\ub85c \ub05d\uc744 \ud5a5\ud55c\ub2e4. \ubaa8\ub4e0 \uc74c\uc774 \uc5b4\ub5a4 \uc0ac\ubb3c \ud558\ub098\uc640 \uc815\ud655\ud788 \ub300\uc751\ud55c\ub2e4\uace0 \uc0dd\uac01\ud558\uba74 \uac10\uc0c1\uc774 \ud034\uc988\uac00 \ub418\uae30 \uc27d\ub2e4. \uba3c\uc800 \ub3c5\uc8fc\uc640 \ud569\uc8fc\uc758 \ucc28\uc774, \ube60\ub974\uae30\uc758 \ubcc0\ud654, \uac19\uc740 \ubd80\ubd84\uc774 \ub418\ub3cc\uc544\uc624\ub294 \uc21c\uac04\uc744 \ub4e4\uc5b4 \ubcf4\uc790. \uadf8 \uc704\uc5d0 \uc2dc\uc758 \uc7a5\uba74\uc744 \uc5b9\uc73c\uba74 \uc74c\uc545\uc744 \ub4e3\ub294 \uae38\uc7a1\uc774\uac00 \uc0dd\uae34\ub2e4. \ube44\ubc1c\ub514\ub294 1678\ub144\uc5d0 \ud0dc\uc5b4\ub098 1741\ub144\uc5d0 \uc138\uc0c1\uc744 \ub5a0\ub09c \uc791\uace1\uac00\ub2e4. \u300a\uc0ac\uacc4\u300b\uc758 \uc7ac\ubbf8\ub294 \uba3c \uc2dc\ub300\uc758 \uc74c\uc545\uc774\ub77c\ub294 \uc0ac\uc2e4\uc5d0\ub9cc \uc788\uc9c0 \uc54a\ub2e4. \uc0c8\uc18c\ub9ac\ub97c \ubc18\uae30\uace0 \ud3ed\ud48d\uc744 \uac71\uc815\ud558\uba70 \ucd94\uc704\ub97c \ud53c\ud574 \ubd88\uac00\uc5d0 \uc549\ub294 \ubab8\uc758 \uacbd\ud5d8\uc740 \uc624\ub298\uc758 \uc6b0\ub9ac\uc5d0\uac8c\ub3c4 \ub0af\uc124\uc9c0 \uc54a\ub2e4. \ucc98\uc74c\uc5d0\ub294 \ubd04 \ud558\ub098\ub97c, \ub2e4\uc74c\uc5d0\ub294 \uac00\uc7a5 \uad81\uae08\ud55c \uacc4\uc808\uc744 \uace8\ub77c \ub4e4\uc5b4\ub3c4 \ucda9\ubd84\ud558\ub2e4. \uc5f4\ub450 \uc545\uc7a5\uc744 \ud55c\uaebc\ubc88\uc5d0 \uacf5\ubd80\ud574\uc57c \uc2dc\uc791\ud560 \uc218 \uc788\ub294 \uc74c\uc545\uc740 \uc544\ub2c8\ub2e4."}, {"id": "watteau-cythera-pilgrimage", "title": "\uc2dc\ud14c\ub77c \uc12c\uc73c\ub85c\uc758 \uc21c\ub840 \u2014 \uc5f0\uc778\ub4e4\uc740 \uc5b4\ub514\ub85c \uac00\ub294 \uac78\uae4c", "summary": "\ube44\ub108\uc2a4\uc758 \ud45c\uc9c0\uc640 \uc5f0\uc778\ub4e4\uc758 \uc6c0\uc9c1\uc784\uc744 \ub530\ub77c \ub8e8\ube0c\ub974\uc758 \ud68c\ud654\ub97c \ucc9c\ucc9c\ud788 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Art", "url": "stories/watteau-cythera-pilgrimage/index.html", "image": "media/watteau-cythera-pilgrimage.jpg", "alt": "\uc640\ud1a0\uc758 \uc2dc\ud14c\ub77c \uc12c\uc73c\ub85c\uc758 \uc21c\ub840. \uc624\ub978\ucabd \ub098\ubb34 \uc544\ub798\uc5d0\uc11c \uc67c\ucabd \ubc30 \ucabd\uc73c\ub85c \uc5f0\uc778\ub4e4\uc758 \uc6c0\uc9c1\uc784\uc774 \uc774\uc5b4\uc9d1\ub2c8\ub2e4.", "text": "\uc2dc\ud14c\ub77c \uc12c\uc73c\ub85c\uc758 \uc21c\ub840 \u2014 \uc5f0\uc778\ub4e4\uc740 \uc5b4\ub514\ub85c \uac00\ub294 \uac78\uae4c \uc640\ud1a0\uc758 \uadf8\ub9bc\uc5d0\uc11c \uc190\uc9d3\uacfc \ubc1c\uac78\uc74c, \ud589\ubcf5 \uc18d\uc758 \uba38\ubb47\uac70\ub9bc\uc744 \uc77d\uae30 \ube44\ub108\uc2a4\uc758 \ud45c\uc9c0\uc640 \uc5f0\uc778\ub4e4\uc758 \uc6c0\uc9c1\uc784\uc744 \ub530\ub77c \ub8e8\ube0c\ub974\uc758 \ud68c\ud654\ub97c \ucc9c\ucc9c\ud788 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Art \ubb38\ud654 \uc798 \ucc28\ub824\uc785\uc740 \uc0ac\ub78c\ub4e4\uc774 \ub098\ubb34 \uc544\ub798\uc5d0 \ubaa8\uc5ec \uc788\ub2e4. \uc5b4\ub5a4 \uc774\ub294 \uc549\uc544 \uc788\uace0 \uc5b4\ub5a4 \uc774\ub294 \uc77c\uc5b4\uc11c\uba70, \ub610 \ub2e4\ub978 \uc774\ub4e4\uc740 \ubc30 \ucabd\uc73c\ub85c \uac78\uc5b4\uac04\ub2e4. \ucd95\uc81c\uc758 \ud55c \uc7a5\uba74 \uac19\uc9c0\ub9cc \ubb34\uc5c7\uc774 \ub9c9 \uc2dc\uc791\ub418\ub294\uc9c0 \ub05d\ub098\ub294\uc9c0 \ubd84\uba85\ud558\uac8c \ub9d0\ud558\uae30\ub294 \uc5b4\ub835\ub2e4. \uc559\ud22c\uc548 \uc640\ud1a0\uc758 \u3008\uc2dc\ud14c\ub77c \uc12c\uc73c\ub85c\uc758 \uc21c\ub840\u3009\ub2e4. \uc2dc\ud14c\ub77c \uc12c\uc73c\ub85c\uc758 \ucd9c\ud56d\uc774\ub77c\ub294 \uc774\ub984\uc73c\ub85c\ub3c4 \uc54c\ub824\uc9c4 \uc774 \uadf8\ub9bc\uc740 \uc0ac\ub791\uc758 \ud48d\uacbd\uc744 \ubcf4\uc5ec \uc8fc\uba74\uc11c\ub3c4 \ub5a0\ub0a8\uacfc \uba38\ubb34\ub984 \uc0ac\uc774\uc758 \uc2dc\uac04\uc744 \ub290\ub07c\uac8c \ud55c\ub2e4. \uc778\ubb3c\ub4e4\uc758 \uc791\uc740 \ubab8\uc9d3\uc744 \ub530\ub77c\uac00\uba74 \uc81c\ubaa9\ub9cc \uc77d\uc744 \ub54c\ubcf4\ub2e4 \ud6e8\uc52c \ub9ce\uc740 \uc77c\uc774 \ubcf4\uc778\ub2e4. \uadf8\ub9ac\uc2a4\uc758 \uc12c \uc2dc\ud14c\ub77c\ub294 \uc0ac\ub791\uc758 \uc5ec\uc2e0 \uc544\ud504\ub85c\ub514\ud14c\uc640 \uc5f0\uacb0\ub418\uc5b4 \uc628 \uc774\ub984\uc774\ub2e4. \ub85c\ub9c8\uc2dd \uc774\ub984\uc73c\ub85c\ub294 \ube44\ub108\uc2a4\ub2e4. \uadf8\ub9bc \uc624\ub978\ucabd \ub098\ubb34 \uacc1\uc5d0\ub3c4 \ube44\ub108\uc2a4\uc758 \ubaa8\uc2b5\uc744 \ud55c \ud45c\uc9c0\uac00 \uc788\uace0 \uaf43\uc7a5\uc2dd\uc774 \ub354\ud574\uc838 \uc788\ub2e4. \uacf5\uac04\uc758 \uc131\uaca9\uc744 \uc54c\ub824 \uc8fc\ub294 \ub2e8\uc11c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc774 \uadf8\ub9bc\uc744 \uc12c\uc758 \uc2e4\uc81c \uc9c0\ud615\uc744 \uc548\ub0b4\ud558\ub294 \uc5ec\ud589 \uc9c0\ub3c4\ub85c \ubcfc \uc218\ub294 \uc5c6\ub2e4. \uc0ac\ub791\uc744 \uc5f0\uc0c1\uc2dc\ud0a4\ub294 \uc7a5\uc18c\uc758 \uc774\ub984\uacfc \uc0c1\uc0c1 \uc18d \ud48d\uacbd\uc744 \uc5ee\uc740 \ud68c\ud654\ub85c \ub9cc\ub098\ub294 \ud3b8\uc774 \uc88b\ub2e4. \ubb34\uc5c7\uc774 \uc0ac\uc2e4\uc758 \uc9c0\uba85\uc774\uace0 \ubb34\uc5c7\uc774 \uadf8\ub9bc\uc758 \uad6c\uc131\uc778\uc9c0 \uad6c\ubd84\ud558\uba74 \uc0c1\uc0c1\uc744 \ub354 \uc790\uc720\ub86d\uac8c \uc990\uae38 \uc218 \uc788\ub2e4. \uc624\ub978\ucabd \ub098\ubb34 \uc544\ub798\uc5d0\ub294 \uc544\uc9c1 \uc790\ub9ac\ub97c \ub728\uc9c0 \uc54a\uc740 \ub0a8\ub140\uac00 \ubcf4\uc778\ub2e4. \uc8fc\ubcc0 \uc0ac\ub78c\ub4e4\uc774 \uc774\ub3d9\ud558\ub294\ub370\ub3c4 \uc774\ub4e4\uc740 \uc7a0\uc2dc \uc790\uae30\ub4e4\ub9cc\uc758 \uc2dc\uac04\uc744 \ubcf4\ub0b4\ub294 \uac83\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \uc870\uc6a9\ud55c \ub300\ud654\uac00 \uc774\uc5b4\uc9c0\ub294\uc9c0, \ub9c8\uc9c0\ub9c9\uc73c\ub85c \uba38\ubb3c\ub7ec \uc788\ub294\uc9c0 \ubab8\uc758 \ubc29\ud5a5\uc744 \ubcf4\uba70 \uc0c1\uc0c1\ud574 \ubcfc \uc218 \uc788\ub2e4. \uc774\ub54c \uc778\ubb3c\ub4e4\uc758 \ub9c8\uc74c\uc18d \ub300\uc0ac\ub97c \ud655\uc815\ud574 \uc904 \ud544\uc694\ub294 \uc5c6\ub2e4. \uadf8\ub9bc\uc774 \ubcf4\uc5ec \uc8fc\ub294 \uac83\uc740 \uc790\uc138\uc640 \uac70\ub9ac, \uc190\uacfc \uc5bc\uad74\uc758 \ubc29\ud5a5\uc774\ub2e4. \ubcf4\ub294 \uc0ac\ub78c\uc740 \uadf8 \ub2e8\uc11c\ub97c \uc5f0\uacb0\ud574 \uad00\uacc4\ub97c \uc77d\ub294\ub2e4. \uc0ac\ub791\uc774\ub77c\ub294 \ud070 \uc8fc\uc81c\uac00 \uac70\ucc3d\ud55c \uc120\uc5b8\ubcf4\ub2e4 \uc791\uc740 \ubab8\uc9d3\uc5d0\uc11c \uba3c\uc800 \uc2dc\uc791\ub418\ub294 \uc148\uc774\ub2e4. \uc870\uae08 \uc67c\ucabd\uc73c\ub85c \ub208\uc744 \uc62e\uae30\uba74 \ub0a8\uc790\uac00 \uc5ec\uc790\uc758 \uc190\uc744 \uc7a1\uc544 \uc77c\uc73c\ud0a4\ub294 \ub4ef\ud55c \ubaa8\uc2b5\uc774 \ub098\uc628\ub2e4. \ub354 \uac00\uc6b4\ub370\uc5d0\uc11c\ub294 \ub2e4\ub978 \ub450 \uc0ac\ub78c\uc774 \ubab8\uc744 \uac00\uae4c\uc774\ud55c \ucc44 \uc774\ub3d9\ud55c\ub2e4. \uc549\uc544 \uc788\uc74c, \uc77c\uc5b4\ub0a8, \uac77\uae30\ub77c\ub294 \ub2e4\ub978 \ub2e8\uacc4\uac00 \ud55c \ud654\uba74\uc5d0 \ub098\ub780\ud788 \ub193\uc778 \uac83\uc774\ub2e4. \uc774\ub4e4\uc744 \uc2dc\uac04\uc758 \ud750\ub984\ucc98\ub7fc \uc77d\uc73c\uba74 \uc815\uc9c0\ub41c \uadf8\ub9bc\uc774 \ucc9c\ucc9c\ud788 \uc6c0\uc9c1\uc774\uae30 \uc2dc\uc791\ud55c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uac19\uc740 \uc778\ubb3c \ud55c \uc30d\uc774 \uc5ec\ub7ec \ubc88 \uadf8\ub824\uc84c\ub2e4\uace0 \ud655\uc815\ud558\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc790\uc138\ub97c \uc774\uc5b4 \ubcf4\uba74\uc11c \uadf8\ub9bc \uc548\uc5d0 \ub9cc\ub4e4\uc5b4\uc9c4 \ub9ac\ub4ec\uc744 \ub290\ub07c\ub294 \uac10\uc0c1 \ubc29\ubc95\uc774\ub2e4. \uc624\ub978\ucabd\uc5d0\uc11c \uc2dc\uc791\ud55c \uc2dc\uc120\uc740 \uc0ac\ub78c\ub4e4\uc744 \ub530\ub77c \uc67c\ucabd\uc758 \ubc30 \ucabd\uc73c\ub85c \uc774\uc5b4\uc9c4\ub2e4. \uc8fc\ubcc0\uc5d0\ub294 \ub0a0\uac1c \ub2ec\ub9b0 \uc791\uc740 \uc0ac\ub791\uc758 \uc2e0\ub4e4\uc774 \ub5a0\ub2e4\ub2cc\ub2e4. \uc778\uac04\uc758 \ubab8\uc9d3\ub9cc\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c4 \ud604\uc2e4\uc801 \uc7a5\uba74\uc5d0 \uc2e0\ud654\uc801 \ud45c\uc9c0\uac00 \uc11e\uc774\uba74\uc11c, \uc774 \ubaa8\uc784\uc774 \ud3c9\ubc94\ud55c \uc678\ucd9c \uc774\uc0c1\uc758 \uc0c1\uc0c1 \uc18d \uacf5\uac04\uc784\uc744 \uc54c\ub824 \uc900\ub2e4. \uc778\ubb3c\ub9cc \ud655\ub300\ud574\uc11c \ubcf4\uba74 \ub193\uce58\uae30 \uc26c\uc6b4 \ubd80\ubd84\uc774\ub2e4. \uc804\uccb4 \ub3c4\ud310\uc73c\ub85c \ub3cc\uc544\uc640 \ubc30\uc640 \ub098\ubb34, \uba3c \ubb3c\uacfc \uc0b0\uc744 \ud568\uaed8 \ubcf4\uc790. \uac00\uae4c\uc6b4 \uc0ac\ub78c\ub4e4\uc758 \uc774\uc57c\uae30\uac00 \ub113\uc740 \ud48d\uacbd \uc18d\uc5d0 \ub193\uc77c \ub54c \uae30\ubd84\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uc791\uc740 \uad00\uacc4\uc640 \ud070 \uacf5\uac04\uc774 \uc11c\ub85c\ub97c \ubc1b\uccd0 \uc900\ub2e4. \uc81c\ubaa9\uc740 \uae38\uc744 \uac00\ub9ac\ud0a4\uc9c0\ub9cc \ud654\uba74\uc758 \ubaa8\ub4e0 \uc0ac\ub78c\uc744 \ud55c \uac00\uc9c0 \ud589\ub3d9\uc73c\ub85c \uc815\ub9ac\ud558\uae30\ub294 \uc5b4\ub835\ub2e4. \ubc30 \ucabd\uc73c\ub85c \ud5a5\ud558\ub294 \uc6c0\uc9c1\uc784\uc744 \ub530\ub77c\uac00\uba74 \ub5a0\ub0a8\ucc98\ub7fc \ub290\uaef4\uc9c0\uace0, \uc0ac\ub791\uc758 \uc12c\uc774\ub77c\ub294 \uc81c\ubaa9\uc744 \uba3c\uc800 \ub5a0\uc62c\ub9ac\uba74 \ub3c4\ucc29\uc758 \uc7a5\uba74\uc744 \uc0c1\uc0c1\ud560 \uc218\ub3c4 \uc788\ub2e4. \uadf8\ub9bc \uc18d \uba38\ubb47\uac70\ub9bc\uc740 \uc774\ub7f0 \uc9c8\ubb38\uc744 \uc624\ub798 \ub0a8\uae34\ub2e4. \uc5ec\uae30\uc11c\ub294 \ubaa8\ub4e0 \uc778\ubb3c\uc774 \uac19\uc740 \ubc29\ud5a5\uc758 \uac10\uc815\uc744 \uac00\uc9c0\uace0 \uc788\ub2e4\uace0 \ub2e8\uc815\ud558\uc9c0 \uc54a\ub294\ub2e4. \ud568\uaed8 \uc788\uc5b4\ub3c4 \ub204\uad70\uac00\ub294 \ub354 \uba38\ubb3c\uace0 \uc2f6\uace0 \ub204\uad70\uac00\ub294 \uba3c\uc800 \uc77c\uc5b4\ub0a0 \uc218 \uc788\ub2e4. \ubaa9\uc801\uc9c0\ub97c \uc54c\uc544\uc57c\ub9cc \uc77d\uc744 \uc218 \uc788\ub294 \uadf8\ub9bc\uc774 \uc544\ub2c8\ub77c, \uc6c0\uc9c1\uc784\uacfc \ub9dd\uc124\uc784\uc744 \ubcf4\ub294 \uac83 \uc790\uccb4\uac00 \uac10\uc0c1\uc758 \ub0b4\uc6a9\uc774 \ub418\ub294 \uadf8\ub9bc\uc774\ub2e4. \ubd80\ub4dc\ub7ec\uc6b4 \uc0c9\uacfc \uac00\uae4c\uc6b4 \ubab8\uc9d3\uc740 \uc990\uac70\uc6b4 \uae30\ubd84\uc744 \uc900\ub2e4. \uadf8\ub7ec\ub098 \uc990\uac70\uc6c0\uc774 \ub05d\uc5c6\uc774 \uacc4\uc18d\ub420 \uac83 \uac19\uc740 \ud655\uc2e0\ub9cc \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc790\ub9ac\ub97c \uc815\ub9ac\ud558\uace0 \uae38\uc744 \ub098\uc11c\ub294 \uc0ac\ub78c\uc744 \ubcf4\uba74 \uc88b\uc740 \uc2dc\uac04\uc774 \uc9c0\ub098\uac00\uace0 \uc788\ub2e4\ub294 \ub290\ub08c\uc744 \ubc1b\uc744 \uc218\ub3c4 \uc788\ub2e4. \uc774\ub294 \uc791\ud488\uc744 \uc77d\ub294 \ud55c \ubc29\ubc95\uc774\uba70 \ubaa8\ub4e0 \uc0ac\ub78c\uc758 \uac10\uc815\uc774 \uac19\uc544\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uce5c\uad6c\ub4e4\uacfc \uc990\uac70\uc6b4 \uc2dc\uac04\uc744 \ubcf4\ub0b8 \ub4a4 \ud5e4\uc5b4\uc9c0\ub294 \uc21c\uac04\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uc2e4\uc81c \uadf8\ub9bc\uc758 \uc778\ubb3c\ub4e4\uc744 \uc624\ub298\uc758 \uc6b0\ub9ac\uc640 \ub611\uac19\ub2e4\uace0 \ub9d0\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \ub0af\uc120 \uc637\uacfc \uc2e0\ud654\uc758 \uc774\ub984\uc744 \ub118\uc5b4 \uac00\uae4c\uc6cc\uc9c8 \uac10\uac01\uc744 \ucc3e\ub294 \uac83\uc774\ub2e4. \uc791\uc740 \ubab8\uc9d3\uc774 \uc624\ub798 \ub0a8\ub294 \uc774\uc720\ub3c4 \uadf8\ub7f0 \uacbd\ud5d8\uacfc \uc5f0\uacb0\ub420 \uc218 \uc788\ub2e4. \uc61b \ub8e8\ube0c\ub974 \ub3c4\ub85d\uc740 \uc774 \uc791\ud488\uc744 \uc640\ud1a0\uac00 \uc544\uce74\ub370\ubbf8\uc5d0 \uc81c\ucd9c\ud55c 1717\ub144 \uc791\ud488\uc73c\ub85c \uc124\uba85\ud55c\ub2e4. \ube44\uc2b7\ud55c \uc8fc\uc81c\uc758 \ub2e4\ub978 \ud310\ubcf8\ub3c4 \uc5b8\uae09\ud55c\ub2e4. \uac19\uc740 \uc81c\ubaa9\uc774\ub098 \ube44\uc2b7\ud55c \uad6c\ub3c4\uac00 \ubcf4\uc778\ub2e4\uace0 \ubaa8\ub450 \uac19\uc740 \uadf8\ub9bc\uc758 \ub2e4\ub978 \uc0ac\uc9c4\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\uc744 \uc54c\uc544 \ub450\uba74 \uc88b\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 \uadf8 \ub3c4\ub85d\uc758 \ub8e8\ube0c\ub974 \ud310\ubcf8 \uc0c9\ucc44 \uc7ac\ud604 \ub3c4\ud310\uc774\ub2e4. \uc61b \uc778\uc1c4\ubb3c\uc774\ub77c \uc624\ub298 \uc2e4\ubb3c\uc758 \uc0c9\uc744 \uc644\uc804\ud788 \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud604\uc7ac\uc758 \uc804\uc2dc \uc704\uce58\ub97c \uc54c\ub824 \uc8fc\ub294 \uc548\ub0b4\ub3c4\ub85c \uc4f0\uae30\ubcf4\ub2e4 \uc778\ubb3c\ub4e4\uc758 \ubc30\uce58\uc640 \ud070 \uc0c9\uc758 \uad00\uacc4\ub97c \ubcf4\ub294 \uc790\ub8cc\ub85c \ud65c\uc6a9\ud588\ub2e4. \uc624\ub978\ucabd\uc758 \uc549\uc740 \uc0ac\ub78c, \uc77c\uc5b4\ub098\ub294 \uc0ac\ub78c, \uac00\uc6b4\ub370 \uac77\ub294 \uc0ac\ub78c, \uc67c\ucabd \ubc30\uc758 \uc21c\uc11c\ub85c \ucc9c\ucc9c\ud788 \uc2dc\uc120\uc744 \uc62e\uaca8 \ubcf4\uc790. \ub2e4\uc74c\uc5d0\ub294 \ubc18\ub300 \ubc29\ud5a5\uc73c\ub85c \ub3cc\uc544\uc640 \ub098\ubb34 \uc544\ub798\uc758 \uc870\uc6a9\ud55c \ub450 \uc0ac\ub78c\uc744 \ub2e4\uc2dc \ubcf4\uba74 \uc88b\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc0ac\ub78c \uc218\uac00 \ub9ce\uc544 \ubcf5\uc7a1\ud558\ub358 \uadf8\ub9bc\uc5d0 \uc791\uc740 \uc774\uc57c\uae30\ub4e4\uc774 \uc0dd\uae34\ub2e4. \uc640\ud1a0\ub294 \uc0ac\ub791\uc744 \uc124\uba85\ud558\ub294 \ubb38\uc7a5 \ud558\ub098 \ub300\uc2e0 \uc5ec\ub7ec \uc0ac\ub78c\uc758 \uc790\uc138\uc640 \ud48d\uacbd\uc744 \ub0a8\uacbc\ub2e4. \ucd9c\ubc1c\uc778\uc9c0 \ub3c4\ucc29\uc778\uc9c0 \ud55c \ubc88\uc5d0 \uacb0\ub860 \ub0b4\ub9ac\uc9c0 \uc54a\uc544\ub3c4 \ub41c\ub2e4. \uadf8\ub9bc \uc18d \uc2dc\uac04\uc774 \uc5b4\ub514\uc5d0\uc11c \uba38\ubb3c\uace0 \uc5b4\ub514\uc5d0\uc11c \uc6c0\uc9c1\uc774\ub294\uc9c0 \ubcf4\uace0 \ub098\uba74, \uc12c\uc758 \uc774\ub984\ubcf4\ub2e4 \uadf8\uacf3\uc744 \ub5a0\ub098\uac70\ub098 \ucc3e\uc544\uac00\ub294 \uc0ac\ub78c\ub4e4\uc758 \ub9c8\uc74c\uc774 \ub354 \uc624\ub798 \ub0a8\uc744 \uc218 \uc788\ub2e4."}, {"id": "blue-dish-hidden-fortune", "title": "\uc811\uc2dc \ubc14\ub2e5\uc5d0\uc11c \ubcf5 \ud55c \uae00\uc790\ub97c \ub9cc\ub098\ub2e4", "summary": "\ubc31\uc790 \uc811\uc2dc\uc758 \uac00\uc6b4\ub370\uc640 \ubc14\uae65\uba74\uc744 \ub530\ub77c\uac00\uba70 \uae00\uc790\uc640 \uaf43\uc744 \ucc3e\uc2b5\ub2c8\ub2e4.", "category": "life", "category_title": "Life", "subcategory": "Food", "url": "stories/blue-dish-hidden-fortune/index.html", "image": "media/blue-dish-hidden-fortune.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \ubc31\uc790\uccad\ud654\ubcf5\uc790\u00b7\ud480\uaf43\ubb34\ub2ac\uc811\uc2dc \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc811\uc2dc \ubc14\ub2e5\uc5d0\uc11c \ubcf5 \ud55c \uae00\uc790\ub97c \ub9cc\ub098\ub2e4 \uc74c\uc2dd \uc544\ub798\uc5d0 \uc228\uc5b4 \uc788\uc744 \ud478\ub978 \uc778\uc0ac \ubc31\uc790 \uc811\uc2dc\uc758 \uac00\uc6b4\ub370\uc640 \ubc14\uae65\uba74\uc744 \ub530\ub77c\uac00\uba70 \uae00\uc790\uc640 \uaf43\uc744 \ucc3e\uc2b5\ub2c8\ub2e4. Food \uc0dd\ud65c \uc74c\uc2dd\uc744 \ub2f4\uc740 \uc811\uc2dc\uc5d0\uc11c\ub294 \uc694\ub9ac\uac00 \uba3c\uc800 \ubcf4\uc778\ub2e4. \uadf8\ub987 \ud55c\uac00\uc6b4\ub370 \uc5b4\ub5a4 \uadf8\ub9bc\uc774 \uc788\ub294\uc9c0\ub294 \ub2e4 \uba39\uace0 \ub098\uc11c\uc57c \uc54c\uac8c \ub418\ub294 \uacbd\uc6b0\uac00 \ub9ce\ub2e4. \uc774 \uc811\uc2dc\ub77c\uba74 \ub9c8\uc9c0\ub9c9\uc5d0 \ubcf5 \ud55c \uae00\uc790\ub97c \ub9cc\ub098\uac8c \ub420\uc9c0\ub3c4 \ubaa8\ub974\uaca0\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc18c\uc7a5\ud55c \ubc31\uc790\uccad\ud654\ubcf5\uc790\u00b7\ud480\uaf43\ubb34\ub2ac\uc811\uc2dc\ub2e4. \uc774\ub984\uc740 \uae38\uc9c0\ub9cc \ub208\uc5ec\uaca8\ubcfc \uac83\uc740 \uc5b4\ub835\uc9c0 \uc54a\ub2e4. \ud770 \ubc14\ud0d5\uc5d0 \ud478\ub978 \uc120, \uc548\ucabd\uc758 \uae00\uc790, \ubc14\uae65\ucabd\uc758 \uaf43\uc774\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc5d0 \ub530\ub974\uba74 \uc811\uc2dc \uc548\ubc14\ub2e5\uc5d0\ub294 \ucee4\ub2e4\ub780 \uc6d0 \ub450 \uc904\uc774 \uc788\uace0 \uadf8 \uc548\uc5d0 \ub3c4\uc548\ud654\ub41c \ubcf5, \uace7 \u798f \uae00\uc790\uac00 \uc788\ub2e4. \ubd93\uae00\uc528 \ud55c \uae00\uc790\ub97c \uadf8\ub300\ub85c \uc801\uc740 \uac83\uc774 \uc544\ub2c8\ub77c \ubb34\ub2ac\ucc98\ub7fc \uad6c\uc131\ud55c \uae00\uc790\ub2e4. \uadf8\ub798\uc11c \ucc98\uc74c\uc5d0\ub294 \uaf43\uc774\ub098 \uae30\ud558\ud559\ubb34\ub2ac\ub85c \ubcf4\uc77c \uc218 \uc788\ub2e4. \uae00\uc790\ub77c\ub294 \uc124\uba85\uc744 \ub4e3\uace0 \ub098\uba74 \uac00\uc6b4\ub370\ub97c \ub2e4\uc2dc \ub4e4\uc5ec\ub2e4\ubcf4\uac8c \ub41c\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \ud55c \ubc88\uc5d0 \uc77d\ud788\uc9c0 \uc54a\ub294\ub2e4\uace0 \uc774\uc0c1\ud55c \uc77c\uc740 \uc544\ub2c8\ub2e4. \uc774\ub984\uc744 \uc54c\uace0 \ucc3e\uc544\ubcf4\ub294 \uacfc\uc815 \uc790\uccb4\uac00 \uc774 \uc811\uc2dc\ub97c \ubcf4\ub294 \uc7ac\ubbf8\ub2e4. \uc7a5\uc2dd\uc740 \uc74c\uc2dd\uc774 \ub193\uc77c \uc548\ucabd\uc5d0\uc11c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \ubc14\uae65\uba74\uc740 S\uc790 \ubaa8\uc591\uc758 \uc120\uc73c\ub85c \ub2e4\uc12f \uad6c\uc5ed\uc744 \ub098\ub204\uace0 \uac01 \uce78\uc5d0 \ud480\uaf43\ubb34\ub2ac\ub97c \uadf8\ub838\ub2e4\uace0 \ud55c\ub2e4. \ud14c\ub450\ub9ac\uc640 \uad7d\uc5d0\ub3c4 \ud478\ub978 \uc120\uc774 \ub458\ub7ec\uc838 \uc788\ub2e4. \ud55c \uc811\uc2dc\ub97c \uc704\uc5d0\uc11c \ubcf4\uba74 \uae00\uc790\uac00 \uc911\uc2ec\uc774\uace0, \uc606\uc5d0\uc11c \ubcf4\uba74 \uaf43\uc774 \uc911\uc2ec\uc774 \ub41c\ub2e4. \uc815\uba74 \uc0ac\uc9c4 \ud55c \uc7a5\ub9cc\uc73c\ub85c \ubb3c\uac74\uc744 \ub2e4 \ubcf4\uc558\ub2e4\uace0 \ub290\ub07c\uae30 \uc26c\uc6b4\ub370, \uadf8\ub987\uc740 \ubc14\ub77c\ubcf4\ub294 \ubc29\ud5a5\uc5d0 \ub530\ub77c \uc804\ud600 \ub2e4\ub978 \ubd80\ubd84\uc744 \ub0b4\uc900\ub2e4. \uadf8\ub987\uc758 \uc548\ucabd\uc740 \uc4f0\uc784\uc758 \uc911\uc2ec\uc774\uba74\uc11c \ubb34\ub2ac\uac00 \ub193\uc77c \uc790\ub9ac\uc774\uae30\ub3c4 \ud558\ub2e4. \uc774 \uc811\uc2dc\uc5d0\ub294 \ub450 \uacb9\uc758 \uc6d0\uacfc \ub3c4\uc548\ud654\ud55c \ubcf5 \uae00\uc790\uac00 \uadf8 \uc548\uc5d0 \uc788\ub2e4. \uc74c\uc2dd\uc744 \ub2f4\uc558\uc744 \ub54c\uc640 \ube44\uc6cc \ub450\uc5c8\uc744 \ub54c \ubcf4\uc774\ub294 \ubd80\ubd84\uc774 \ub2ec\ub790\uc744 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uc5b4\ub5a4 \uc74c\uc2dd\uc744 \uc2e4\uc81c\ub85c \ub2f4\uc558\ub294\uc9c0\uc640 \uc2dd\uc0ac\uac00 \ub05d\ub098\uba74 \uc5b4\ub5a4 \ubc18\uc751\uc744 \ubcf4\uc600\ub294\uc9c0\ub294 \ud655\uc778\ub418\uc9c0 \uc54a\uc740 \uc774\uc57c\uae30\ub2e4. \uc5ec\uae30\uc11c\ub294 \uadf8\ub987\uc744 \uc4f0\ub294 \ud589\ub3d9\uacfc \ubcf4\ub294 \ubc29\ud5a5\uc744 \ud568\uaed8 \uc0dd\uac01\ud574 \ubcfc \uc218 \uc788\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \uc704\ucabd\uc744 \ubcf4\uc558\uc744 \ub54c \ub208\uc5d0 \ub4e4\uc5b4\uc624\ub294 \uc815\ubcf4\uac00 \uc2e4\uc81c \uc0ac\uc6a9 \uc911\uc5d0\ub3c4 \ub298 \uac19\uc740 \uc815\ub3c4\ub85c \ub4dc\ub7ec\ub0ac\ub2e4\uace0 \uac00\uc815\ud558\uc9c0 \uc54a\ub294 \uac83\uc774\ub2e4. \uc0dd\ud65c \ub3c4\uad6c\uc758 \uc7a5\uc2dd\uc740 \uc804\uc2dc \uc0ac\uc9c4\ucc98\ub7fc \uc5b8\uc81c\ub098 \ubaa8\ub450 \ud3bc\uccd0\uc838 \ubcf4\uc774\ub294 \uc0c1\ud0dc\uc5d0\ub9cc \uc788\uc9c0 \uc54a\uc558\ub2e4. \ubb3c\uac74\uc758 \uc4f0\uc784\uc774 \uac10\uc0c1\uc758 \uc870\uac74\ub3c4 \ubc14\uafc0 \uc218 \uc788\ub2e4. \ub3c4\uc548\ud654\ud55c \uae00\uc790\ub294 \ud3c9\uc18c \uc77d\ub358 \uc790\ud615\uc5d0\uc11c \uba40\uc5b4\uc9c8 \uc218 \uc788\ub2e4. \ucc98\uc74c\uc5d0\ub294 \ud478\ub978 \uc120\uc758 \ud328\ud134\ucc98\ub7fc \ubcf4\uc774\uace0 \uc124\uba85\uc744 \uc77d\uc740 \ub4a4 \uae00\uc790\ub97c \ub2e4\uc2dc \ucc3e\uac8c \ub41c\ub2e4. \uc774 \uc655\ubcf5\uc774 \uc7a5\uc2dd \ubb38\uc790\ub97c \ubcf4\ub294 \uc7ac\ubbf8\ub2e4. \uae00\uc774 \ub73b\ub9cc \uc804\ub2ec\ud55c\ub2e4\ub294 \uc0dd\uac01\uacfc \uadf8\ub9bc\uc740 \ub9d0 \uc5c6\uc774 \ubaa8\uc591\ub9cc \ubcf4\uc778\ub2e4\ub294 \uc0dd\uac01\uc758 \uacbd\uacc4\uac00 \uc870\uae08 \ud750\ub824\uc9c4\ub2e4. \ubcf5\uc774\ub77c\ub294 \ub9d0\uc774 \uc788\ub2e4\uace0 \ud2b9\uc815\ud55c \uc18c\uc720\uc790\uc758 \uc18c\uc6d0\uc774\ub098 \uae30\ub150\uc77c\uc744 \uc0c8\ub85c \ucd94\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc77c\ubc18\uc801\uc778 \ub73b\uacfc \uac1c\ubcc4 \ubb3c\uac74\uc758 \uad6c\uccb4\uc801 \uc0ac\uc6a9\uc740 \ub2e4\ub978 \uc815\ubcf4\ub2e4. \ubc15\ubb3c\uad00\uc774 \uc2dd\ubcc4\ud55c \uae00\uc790\ub97c \uae30\uc900\uc73c\ub85c \ubcf4\ub418 \ub208\uc55e\uc5d0\uc11c \uc5b4\ub5a4 \uc120\uc774 \uadf8\ub807\uac8c \uad6c\uc131\ub418\uc5c8\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uba74 \ub41c\ub2e4. \ub73b\uc744 \uc544\ub294 \uc77c\uc774 \uad00\ucc30\uc744 \ub05d\ub0b4\uae30\ubcf4\ub2e4 \uc0c8\ub85c\uc6b4 \uad00\ucc30\uc744 \uc2dc\uc791\ud558\uac8c \ud560 \uc218 \uc788\ub2e4. \ubc14\uae65\uba74\uc758 S\uc790 \uad6c\ud68d\uc740 \ub458\ub808\ub97c \ub2e4\uc12f \ubd80\ubd84\uc73c\ub85c \ub098\ub204\uace0 \uadf8 \uc548\uc5d0 \ud480\uaf43\uc744 \ubc30\uce58\ud55c\ub2e4. \uc704\uc5d0\uc11c \ubcfc \ub54c\uc758 \uc911\uc559 \uae00\uc790\uc640 \uc606\uc5d0\uc11c \ubcfc \ub54c\uc758 \ubd84\ud560 \ubb34\ub2ac\ub294 \ub2e4\ub978 \uad6c\uc870\ub2e4. \ud558\ub098\uc758 \ubb3c\uac74\uc774 \uc5ec\ub7ec \uba74\uc5d0\uc11c \ubcc4\uac1c\uc758 \ubcf4\uae30\ub97c \uc81c\uacf5\ud55c\ub2e4. \uc815\uba74 \uc0ac\uc9c4 \ud55c \uc7a5\uc774 \uadf8\ub987 \uc804\uccb4\uc758 \uc7a5\uc2dd \uacc4\ud68d\uc744 \ubaa8\ub450 \uc54c\ub824 \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc774 \uc815\ubcf4\ub97c \uc54c\uace0 \uc2e4\uc81c \uc0ac\uc9c4\uc744 \ub2e4\uc2dc \ubcf4\uba74 \uc5b4\ub5a4 \uba74\uc774 \ubcf4\uc774\uace0 \uc5b4\ub5a4 \uba74\uc774 \uac00\ub824\uc838 \uc788\ub294\uc9c0 \uad6c\ubcc4\ud558\uac8c \ub41c\ub2e4. \uc124\uba85\uc740 \ubcf4\uc774\uc9c0 \uc54a\ub294 \ubd80\ubd84\uc744 \uc0c1\uc0c1\uc73c\ub85c \uc815\ud655\ud788 \uadf8\ub9ac\ub77c\ub294 \uc694\uad6c\ubcf4\ub2e4 \ub2e4\ub978 \ubc29\ud5a5\ub3c4 \uc788\uc74c\uc744 \uc54c\ub824 \uc8fc\ub294 \uae38\uc7a1\uc774\ub2e4. \ubcc4\ub3c4\uc758 \uc0ac\uc9c4\uacfc \uae30\uad00 \uc124\uba85\uc744 \ud568\uaed8 \ubcf4\uba74 \ub41c\ub2e4. \ubb3c\uac74\uc744 \uc9c1\uc811 \ub4a4\uc9d1\uc5b4 \ud655\uc778\ud558\ub824\ub294 \ub300\uc2e0 \uc81c\uacf5\ub41c \uc790\ub8cc\ub85c \uc2dc\uc120\uc744 \ub113\ud790 \uc218 \uc788\ub2e4. \uad6c\uc5f0\uacfc \uad7d\uc5d0 \ub193\uc778 \uccad\ud654\uc120\uc740 \uc811\uc2dc\uc758 \uc704\uc640 \uc544\ub798 \uacbd\uacc4\ub97c \ub530\ub77c\uac04\ub2e4. \uc911\uc559\uc758 \uae00\uc790\uc640 \ubc14\uae65\uc758 \ud480\uaf43\uc774 \uc11c\ub85c \ub2e4\ub978 \uc7a5\uc2dd\uc774\uc5b4\ub3c4 \uc120\uc774 \uc804\uccb4\uc758 \ub458\ub808\ub97c \uc815\ub9ac\ud560 \uc218 \uc788\ub2e4. \ud070 \uc0c1\uc9d5\uc744 \uba3c\uc800 \uc77d\uace0 \uadf8 \ubc14\uae65\uc744 \ubcf4\uba74 \ub2e8\uc21c\ud55c \uacbd\uacc4\ucc98\ub7fc \ubcf4\uc600\ub358 \ubd80\ubd84\uc5d0\ub3c4 \uc81c\uc791\uc758 \uc120\ud0dd\uc774 \uc788\uc74c\uc744 \uc54c\uac8c \ub41c\ub2e4. \uc785\uc9c0\ub984 18\uc13c\ud2f0\ubbf8\ud130\ub77c\ub294 \ud06c\uae30\uae4c\uc9c0 \ud568\uaed8 \uc77d\uc73c\uba74 \ud654\uba74\uc5d0 \ud655\ub300\ub41c \uc774\ubbf8\uc9c0\uac00 \uc0dd\ud65c\uc758 \uaddc\ubaa8\ub85c \ub3cc\uc544\uc628\ub2e4. \uc190\uc5d0 \ub4e4 \uc218 \uc788\ub294 \uadf8\ub987 \ud55c \uc810\uc5d0 \uc77d\ub294 \uae00\uc790\uc640 \ubcf4\ub294 \ubb34\ub2ac, \ub2f4\ub294 \uae30\ub2a5\uc774 \ud568\uaed8 \ub193\uc600\ub2e4. \ubcf5\uc774\ub77c\ub294 \ud55c \uae00\uc790\ub97c \uc54c\uc544\ubcf8 \ub4a4\uc5d0\ub3c4 \uad00\ucc30\uc774 \ub05d\ub098\uc9c0 \uc54a\ub294 \uc774\uc720\ub2e4. \uc811\uc2dc\ub97c \ub458\ub7ec\ubcf4\ub294 \ubc29\ud5a5\ub9cc \ubc14\uafb8\uc5b4\ub3c4 \uc0c8\ub85c\uc6b4 \uba74\uc774 \ub098\ud0c0\ub09c\ub2e4. \uc18c\uc7a5\ud488 \uc815\ubcf4\uc5d0\ub294 \uc785\uc9c0\ub984\uc774 18\uc13c\ud2f0\ubbf8\ud130\ub77c\uace0 \uc801\ud600 \uc788\ub2e4. \uac70\ub300\ud55c \uc804\uc2dc\uc6a9 \uc811\uc2dc\ub97c \uc0c1\uc0c1\ud558\uae30\ubcf4\ub2e4 \ud06c\uae30\ub97c \uac00\ub2a0\ud558\uba70 \ubcf4\uba74 \ubb34\ub2ac\uc640\uc758 \uac70\ub9ac\ub3c4 \uc870\uae08 \uac00\uae4c\uc6cc\uc9c4\ub2e4. \uc2e4\uc81c\ub85c \uc5b4\ub5a4 \uc74c\uc2dd\uc744 \ub2f4\uc558\uace0 \ub204\uac00 \uc0ac\uc6a9\ud588\ub294\uc9c0\ub294 \uc774 \uc790\ub8cc\uc5d0\uc11c \ud655\uc778\ud558\uc9c0 \ubabb\ud588\ub2e4. \ubcf5\uc744 \ub9cc\ub09c\ub2e4\ub294 \uccab \uc7a5\uba74\ub3c4 \uadf8\ub987\uc758 \ubc30\uce58\ub97c \ub5a0\uc62c\ub824 \ubcf8 \uc6b0\ub9ac\uc758 \uc0c1\uc0c1\uc774\ub2e4. \ud655\uc2e4\ud55c \uac83\uc740 \ube48 \uc811\uc2dc\ub9cc\uc73c\ub85c\ub3c4 \ubcfc\uac70\ub9ac\uac00 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc774\ub2e4. \uac00\uc6b4\ub370\uc758 \uae00\uc790\ub97c \ubcf4\uace0, \uc606\uc758 \uaf43\uc744 \ubcf4\ub294 \uac83. \uc2dd\ud0c1\uc758 \ubb3c\uac74\uc744 \ucc9c\ucc9c\ud788 \uc77d\ub294 \uac04\ub2e8\ud55c \ubc29\ubc95\uc774\ub2e4."}, {"id": "brazier-animal-feet", "title": "\ud654\ub85c \uc544\ub798\uc5d0 \uc791\uc740 \uc9d0\uc2b9\uc758 \ubc1c\uc774 \uc788\ub2e4", "summary": "\ud3c9\ubc94\ud55c \uc138 \ubc1c\ucc98\ub7fc \ubcf4\uc774\ub358 \ud654\ub85c \ub2e4\ub9ac\uc5d0 \uc5bc\uad74\uacfc \ubc1c\uc774 \uc228\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.", "category": "life", "category_title": "Life", "subcategory": "Housing", "url": "stories/brazier-animal-feet/index.html", "image": "media/brazier-animal-feet.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc0bc\uc871\ud654\ub85c \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\ud654\ub85c \uc544\ub798\uc5d0 \uc791\uc740 \uc9d0\uc2b9\uc758 \ubc1c\uc774 \uc788\ub2e4 \ub530\ub73b\ud568\uc744 \ub2f4\ub294 \uadf8\ub987\uc758 \ub73b\ubc16\uc758 \ud45c\uc815 \ud3c9\ubc94\ud55c \uc138 \ubc1c\ucc98\ub7fc \ubcf4\uc774\ub358 \ud654\ub85c \ub2e4\ub9ac\uc5d0 \uc5bc\uad74\uacfc \ubc1c\uc774 \uc228\uc5b4 \uc788\uc2b5\ub2c8\ub2e4. Housing \uc0dd\ud65c \ub465\uadfc \ud654\ub85c \ud55c \uc810\uc774 \ub193\uc5ec \uc788\ub2e4. \uac00\uc6b4\ub370\ub294 \uae4a\uac8c \ud30c\uc600\uace0 \uac00\uc7a5\uc790\ub9ac\ub294 \ub113\uac8c \ubc8c\uc5b4\uc84c\ub2e4. \uc704\uc5d0\uc11c \ubcf4\uba74 \uaf64 \uc58c\uc804\ud55c \ubb3c\uac74\uc778\ub370, \uc2dc\uc120\uc744 \uc544\ub798\ub85c \ub0b4\ub9ac\uba74 \ubd84\uc704\uae30\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \uc138 \ub2e4\ub9ac\uac00 \uc791\uc740 \uc9d0\uc2b9\ucc98\ub7fc \uc0dd\uacbc\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc18c\uc7a5\ud55c \uc0bc\uc871\ud654\ub85c\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc601\uce5c\uc655\ube44 \uc774\ubc29\uc790\uac00 \uc18c\uc720\ud588\ub358 \ubb3c\uac74\uc73c\ub85c \uc18c\uac1c\ud55c\ub2e4. \uac70\ucc3d\ud55c \uc758\ub840 \uc7a5\uba74\uc744 \uc0c1\uc0c1\ud558\uae30 \uc804\uc5d0, \uba3c\uc800 \uadf8 \ubc1c\ubd80\ud130 \uc0b4\ud3b4\ubcf4\uba74 \uc88b\uaca0\ub2e4. \ub2e4\ub9ac\uc758 \uc704\ucabd\uc5d0\ub294 \ubfd4\uc774 \ub450 \uac1c \ub2ec\ub9b0 \uc5bc\uad74\uc774 \ud45c\ud604\ub418\uc5b4 \uc788\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc758 \uc774\ub984\uc740 \uadc0\uba74\uc774\ub2e4. \ub0af\uc120 \ub2e8\uc5b4\uc9c0\ub9cc \uc0ac\uc9c4\uacfc \ud568\uaed8 \ubcf4\uba74 \uc870\uae08 \uc27d\ub2e4. \ub2e4\ub9ac\uc640 \ubab8\ud1b5\uc774 \ub9cc\ub098\ub294 \uacf3\uc5d0 \uc785\uccb4\uc801\uc778 \uc5bc\uad74\uc774 \ub193\uc5ec \uc788\ub2e4\ub294 \ub73b\uc774\ub2e4. \uadf8 \uc544\ub798\ub294 \ub3d9\ubb3c\uc758 \ubc1c \ud615\ud0dc\ub85c \ub9cc\ub4e4\uc5c8\ub2e4. \uc5bc\uad74\uc774 \uc788\uace0 \ubc1c\uc774 \uc788\uc73c\ub2c8 \ub2e8\uc21c\ud788 \ubc1b\uce68 \uc138 \uac1c\ub97c \ubd99\uc778 \uac83\uacfc\ub294 \uc778\uc0c1\uc774 \ub2e4\ub974\ub2e4. \ub465\uadfc \ubab8\uccb4\ub97c \uc791\uc740 \uc0dd\ubb3c\ub4e4\uc774 \ubc1b\ub4e4\uace0 \uc788\ub294 \uac83\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218\ub3c4 \uc788\ub2e4. \uc774\uac83\uc740 \ubaa8\uc591\uc5d0\uc11c \uc5bb\ub294 \uac10\uc0c1\uc774\uc9c0, \ud2b9\uc815 \ub3d9\ubb3c\uc744 \ud655\uc778\ud588\ub2e4\ub294 \uc774\uc57c\uae30\ub294 \uc544\ub2c8\ub2e4. \ud654\ub85c\ub294 \uad6c\ub9ac\ub85c \ub9cc\ub4e0 \ubab8\uccb4\uc5d0 \uc138 \uac1c\uc758 \ub2e4\ub9ac\uac00 \ub2ec\ub9b0 \uad6c\uc870\ub2e4. \ubc15\ubb3c\uad00\uc740 \ub2e4\ub9ac\ub97c \ub530\ub85c \uc8fc\uc870\ud55c \ub2e4\uc74c \ub9ac\ubcb3\uc73c\ub85c \ubab8\uccb4\uc5d0 \ubd99\uc600\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uba40\ub9ac\uc11c\ub294 \ud55c \ub369\uc5b4\ub9ac \uac19\uc544\ub3c4 \ub9cc\ub4dc\ub294 \uacfc\uc815\uc5d0\uc11c\ub294 \ubd80\ud488\uc774 \ub098\ub258\uc5c8\ub358 \uac83\uc774\ub2e4. \ub113\uc740 \ud14c\ub450\ub9ac \ub05d\uc5d0\ub294 \ub465\uae00\uac8c \ud131\ub3c4 \uc84c\ub2e4. \ubab8\uccb4\uc640 \ub2e4\ub9ac, \uac00\uc7a5\uc790\ub9ac\ub97c \ucc28\ub840\ub85c \ubcf4\uba74 \ud070 \ubaa8\uc591 \uc548\uc5d0 \uc11c\ub85c \ub2e4\ub978 \uc791\uc5c5\uc774 \ub4e4\uc5b4 \uc788\uc74c\uc744 \uc54c\uac8c \ub41c\ub2e4. \uc7a5\uc778\uc758 \uc190\uae38\uc744 \ucc3e\ub294 \ub370 \ubc18\ub4dc\uc2dc \ubcf5\uc7a1\ud55c \ubb38\uc591\ubd80\ud130 \uc77d\uc5b4\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud654\ub85c\uc758 \ub2e4\ub9ac\ub294 \uc7a5\uc2dd\uc778 \ub3d9\uc2dc\uc5d0 \ubab8\uccb4\ub97c \uc138\uc6b0\ub294 \ubd80\ubd84\uc774\ub2e4. \uc138 \uac1c\uc758 \ubc1b\uce68\uc774 \uc5b4\ub514\uc5d0 \ubd99\ub294\uc9c0 \ubcf4\uba74 \ub465\uadfc \uc6a9\uae30\uc640 \ubc14\ub2e5\uc758 \uad00\uacc4\uac00 \ub4dc\ub7ec\ub09c\ub2e4. \uc815\uba74\uc758 \ubb34\ub2ac\ub9cc \ubcf4\uc558\uc744 \ub54c\uc640 \ub2e4\ub978 \uad6c\uc870\uc758 \uc9c8\ubb38\uc774 \uc0dd\uae34\ub2e4. \ub2e4\ub9cc \uc2e4\uc81c \uc548\uc815\uc131\uacfc \ubb34\uac8c \uc911\uc2ec\uc744 \uc0ac\uc9c4\ub9cc\uc73c\ub85c \uce21\uc815\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \ud615\ud0dc\ub97c \uc774\ud574\ud558\ub294 \uad00\ucc30\uacfc \uacf5\ud559\uc801 \uac80\uc0ac\ub294 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \uc0bc\uc871\uc774\ub77c\ub294 \ub9d0\uc740 \ubc14\ub85c \uc774\ub7f0 \uc138 \ub2e4\ub9ac\uc758 \uad6c\uc131\uc744 \uac00\ub9ac\ud0a8\ub2e4. \uc774\ub984\uc744 \uc54c\uba74 \ub0af\uc120 \uc804\ubb38 \uc6a9\uc5b4\uac00 \ub208\uc55e\uc758 \uac1c\uc218\uc640 \uc5f0\uacb0\ub41c\ub2e4. \uc804\uccb4\ub97c \ud55c \ubc88 \ubcf8 \ub4a4 \ubab8\uccb4\uc640 \ub2e4\ub9ac\uac00 \ub9cc\ub098\ub294 \uc790\ub9ac\ub97c \uc0b4\ud3b4\ubcf4\uc790. \uae08\uc18d \ubb3c\uac74\uc758 \ud070 \uc724\uacfd\uc774 \uc5ec\ub7ec \ubd80\ud488\uc758 \uad00\uacc4\ub85c \ub098\ub258\uae30 \uc2dc\uc791\ud55c\ub2e4. \uc18c\uc7a5\ud488\uc758 \uc774\ub984\ub3c4 \uad00\ucc30\uc758 \uc21c\uc11c\ub97c \ub9cc\ub4e4\uc5b4 \uc904 \uc218 \uc788\ub2e4. \ubc15\ubb3c\uad00\uc740 \ub2e4\ub9ac\ub97c \ubcc4\ub3c4\ub85c \uc8fc\uc870\ud55c \ub4a4 \ub9ac\ubcb3\uc73c\ub85c \ubd99\uc600\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ubab8\uccb4\uc640 \ub2e4\ub9ac\uc758 \uc81c\uc791\uc744 \ub098\ub204\uace0 \ub098\uc911\uc5d0 \uc5f0\uacb0\ud558\ub294 \uacfc\uc815\uc774 \uc788\uc5c8\ub2e4\ub294 \ub73b\uc774\ub2e4. \uc644\uc131\ud488\uc5d0\uc11c \uae08\uc18d\uc774 \uc774\uc5b4\uc838 \ubcf4\uc778\ub2e4\uace0 \ucc98\uc74c\ubd80\ud130 \ud55c \ub369\uc5b4\ub9ac\ub85c \ubaa8\ub450 \ub9cc\ub4e4\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc774\uc74c\uc758 \uc815\ubcf4\ub294 \ub208\uc5d0 \ubcf4\uc774\ub294 \uc678\ud615\uacfc \uc81c\uc791\uc758 \uc2dc\uac04\uc744 \uc774\uc5b4 \uc900\ub2e4. \ub9ac\ubcb3\uc740 \ubd80\ud488\uc744 \uace0\uc815\ud558\ub294 \ub370 \uc4f0\ub294 \uae08\uc18d \uc5f0\uacb0 \uc694\uc18c\ub2e4. \uadf8\ub7ec\ub098 \uc774 \ubb3c\uac74\uc758 \ubaa8\ub4e0 \uce58\uc218\uc640 \uc791\uc5c5 \uc21c\uc11c\ub97c \uc0ac\uc9c4\uc5d0\uc11c \uc0c8\ub85c \ubcf5\uc6d0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uae30\uad00\uc774 \ud655\uc778\ud55c \uc5f0\uacb0 \ubc29\uc2dd\uc744 \uc54c\uba74 \uc5b4\ub290 \ubd80\ubd84\uc744 \ub354 \uc0b4\ud3b4\ubcfc\uc9c0 \uc54c \uc218 \uc788\ub2e4. \uc7a5\uc2dd\uc5d0\ub9cc \uba38\ubb3c\ub358 \uc2dc\uc120\uc774 \uc811\ud569 \ubd80\uadfc\uc73c\ub85c \uc62e\uaca8 \uac04\ub2e4. \uae30\uc220\uc758 \ud754\uc801\uc740 \ud654\ub824\ud55c \uba74\uc758 \ubc14\uae65\uc5d0\ub3c4 \uc788\ub2e4. \ub2e4\ub9ac \uc704\uc758 \uc5bc\uad74\uacfc \uc544\ub798\uc758 \ubc1c\uc740 \uace7\uac8c \uc790\ub978 \uae30\ub465\uacfc \ub2e4\ub978 \ud45c\uc815\uc744 \uc900\ub2e4. \ubab8\uccb4\ub97c \ubc1b\uce58\ub294 \ubd80\ubd84\uc774 \uc0b4\uc544 \uc788\ub294 \uc874\uc7ac\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218\ub3c4 \uc788\ub2e4. \uc774\uac83\uc740 \ubb3c\uac74\uc758 \ubaa8\uc591\uc5d0\uc11c \uc5bb\ub294 \uac10\uc0c1\uc774\uba70 \ud2b9\uc815 \ub3d9\ubb3c\uc758 \uc885\ub958\uc640 \uc758\ubbf8\ub97c \ud655\uc815\ud588\ub2e4\ub294 \uc8fc\uc7a5\uc740 \uc544\ub2c8\ub2e4. \uae30\uad00\uc774 \uadc0\uba74\uc774\ub77c\uace0 \ubd80\ub978 \ud615\uc0c1\uc744 \uba3c\uc800 \uae30\uc900\uc73c\ub85c \uc0bc\ub294\ub2e4. \ub9cc\uc57d \uc5bc\uad74\ub9cc \ud655\ub300\ud574\uc11c \ubcf4\uba74 \uc804\uccb4 \ub2e4\ub9ac\uc758 \uc5ed\ud560\uc740 \ubc30\uacbd\uc73c\ub85c \ubb3c\ub7ec\ub09c\ub2e4. \ubc18\ub300\ub85c \uba40\ub9ac\uc11c \ubc1b\uce68\ub9cc \ubcf4\uba74 \uadf8 \ud45c\uc815\uc774 \uc0ac\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ub450 \ubcf4\uae30\ub97c \uc624\uac00\uba74 \uae30\ub2a5\uacfc \ud615\uc0c1\uc774 \uc5b4\ub5bb\uac8c \uac19\uc740 \uc790\ub9ac\uc5d0\uc11c \ub9cc\ub0ac\ub294\uc9c0 \ubcf4\uc778\ub2e4. \uc870\uac01\ucc98\ub7fc \uac10\uc0c1\ud560 \ubd80\ubd84\uc774 \ub3c4\uad6c\ub97c \uc9c0\ud0f1\ud558\ub294 \ubd80\ud488 \uc548\uc5d0\ub3c4 \ub193\uc5ec \uc788\uc5c8\ub2e4\ub294 \uc810\uc774 \uc7ac\ubbf8\uc788\ub2e4. \uc774\ubc29\uc790\uac00 \uc18c\uc720\ud588\ub358 \uc720\ud488\uc774\ub77c\ub294 \uc815\ubcf4\ub294 \ubb3c\uac74\uc758 \uc804\ub798\uc640 \uc778\ubb3c\uc744 \uc5f0\uacb0\ud55c\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uc5b4\ub290 \ub0a0 \ubb34\uc5c7\uc744 \ub123\uace0 \ub204\uad6c\uc640 \ud568\uaed8 \uc0ac\uc6a9\ud588\ub294\uc9c0\uae4c\uc9c0 \uc54c \uc218\ub294 \uc5c6\ub2e4. \uc54c\ub824\uc9c4 \uc18c\uc720 \uad00\uacc4\uc640 \ud655\uc778\ub418\uc9c0 \uc54a\uc740 \uc0dd\ud65c\uc758 \uc7a5\uba74\uc744 \ub098\ub204\uc5b4 \uc77d\uc73c\uba74 \ubb34\ub9ac\ud55c \uc655\uc2e4 \uc77c\ud654\ub97c \ub367\ubd99\uc774\uc9c0 \uc54a\uace0\ub3c4 \ubb3c\uac74\uc744 \ubcfc \uc218 \uc788\ub2e4. \ud654\ub85c\ub294 \uc5f4\uc744 \ub2e4\ub8e8\ub294 \ub3c4\uad6c\uc774\uc9c0\ub9cc \uc5ec\uae30\uc11c\ub294 \uc0ac\uc6a9\uc744 \uc7ac\ud604\ud558\uac70\ub098 \ud604\uc7ac \uc720\ubb3c\uc5d0 \ubd88\uc744 \ub123\ub294 \ubc29\ubc95\uc744 \uc548\ub0b4\ud558\uc9c0 \uc54a\ub294\ub2e4. \ub0a8\uc740 \ud615\ud0dc\uc640 \uc81c\uc791 \uc124\uba85\uc774 \uc911\uc2ec\uc774\ub2e4. \ub465\uadfc \ud14c\ub450\ub9ac\uc640 \ubab8\uccb4\ub97c \ubcf8 \ub4a4 \uc791\uc740 \uc138 \ubc1c\ub85c \ub208\uc744 \ub0b4\ub824 \ubcf4\uc790. \ud070 \uae30\ub2a5\uc744 \ub9e1\uc740 \ubb3c\uac74\uc774 \uc544\ub798\ucabd\uc758 \ud45c\uc815\uacfc \uc774\uc74c\uc5d0 \uc815\uc131\ub3c4 \ud568\uaed8 \ub2f4\uc558\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ubcf4\uc778\ub2e4. \uc774 \ubb3c\uac74\uc5d0\uc11c \uc5b4\ub5a4 \uc5bc\uad74\uc774 \uc5b4\ub5a4 \ud798\uc744 \uc9c0\ucf1c \uc8fc\uc5c8\ub2e4\uace0 \ub2e8\uc815\ud560 \uc790\ub8cc\ub294 \uc5ec\uae30\uc11c \ud655\uc778\ud558\uc9c0 \ubabb\ud588\ub2e4. \uadf8\ub798\uc11c \uc0c1\uc9d5 \ud480\uc774\ub97c \uae38\uac8c \ubd99\uc774\uae30\ubcf4\ub2e4 \uc2e4\uc81c \ub0a8\uc544 \uc788\ub294 \ud615\ud0dc\ub97c \ubcf4\ub294 \ud3b8\uc774 \ub354 \uc990\uac81\ub2e4. \ub2e4\uc74c\uc5d0 \ud654\ub85c\ub098 \ud5a5\ub85c\ub97c \ub9cc\ub098\uba74 \uadf8\ub987 \uc548\ucabd\ub9cc \ub4e4\uc5ec\ub2e4\ubcf4\uc9c0 \ub9d0\uace0 \uc544\ub798\ub3c4 \ubcf4\uc790. \ubc14\ub2e5\uc744 \ub51b\uace0 \uc788\ub294 \ubc1c\uc5d0 \uc758\uc678\ub85c \uac00\uc7a5 \uc7ac\ubbf8\uc788\ub294 \ud45c\uc815\uc774 \uc228\uc5b4 \uc788\uc744\uc9c0 \ubaa8\ub978\ub2e4. \uc774 \uc0bc\uc871\ud654\ub85c\uc5d0\uc11c\ub294 \ub530\ub73b\ud55c \uadf8\ub987\ubcf4\ub2e4 \uba3c\uc800 \uc138 \ubc1c\uc758 \uac1c\uc131\uc774 \uae30\uc5b5\uc5d0 \ub0a8\ub294\ub2e4."}, {"id": "christmas-pudding-sixpence", "title": "\ud06c\ub9ac\uc2a4\ub9c8\uc2a4 \ud478\ub529\uc5d0\ub294 \uc65c \ub3d9\uc804 \uc774\uc57c\uae30\uac00 \ub530\ub77c\uc62c\uae4c", "summary": "\uc5f0\ub9d0 \ub514\uc800\ud2b8 \uc606\uc5d0 \uc740\ube5b \ub3d9\uc804\uc774 \ub4f1\uc7a5\ud569\ub2c8\ub2e4. \ub3c8\uc758 \uc561\uba74\ubcf4\ub2e4 \ud589\uc6b4\uc744 \ubc14\ub77c\ub294 \ub9c8\uc74c\uc774 \uc55e\uc5d0 \ub193\uc774\ub294 \ud48d\uc2b5\uc785\ub2c8\ub2e4.", "category": "life", "category_title": "Life", "subcategory": "Folks", "url": "stories/christmas-pudding-sixpence/index.html", "image": "media/christmas-pudding-sixpence.jpg", "alt": "\ud478\ub529 \uc811\uc2dc \ubc14\uae65\uc5d0 \uc740\ube5b \ub3d9\uc804\uc744 \ub098\ub780\ud788 \ub193\uc740 AI \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\ud06c\ub9ac\uc2a4\ub9c8\uc2a4 \ud478\ub529\uc5d0\ub294 \uc65c \ub3d9\uc804 \uc774\uc57c\uae30\uac00 \ub530\ub77c\uc62c\uae4c \uc791\uc740 \uc2dd\uc2a4\ud39c\uc2a4\uc5d0 \ub2f4\uc544 \ub450\uc5c8\ub358 \uc0c8\ud574\uc758 \ubc14\ub78c \uc5f0\ub9d0 \ub514\uc800\ud2b8 \uc606\uc5d0 \uc740\ube5b \ub3d9\uc804\uc774 \ub4f1\uc7a5\ud569\ub2c8\ub2e4. \ub3c8\uc758 \uc561\uba74\ubcf4\ub2e4 \ud589\uc6b4\uc744 \ubc14\ub77c\ub294 \ub9c8\uc74c\uc774 \uc55e\uc5d0 \ub193\uc774\ub294 \ud48d\uc2b5\uc785\ub2c8\ub2e4. Folks \uc0dd\ud65c \ud06c\ub9ac\uc2a4\ub9c8\uc2a4 \ud478\ub529 \uc0ac\uc9c4\uc744 \ubcf4\uba74 \ub465\uadfc \ub514\uc800\ud2b8 \uc606\uc5d0 \uc791\uc740 \uc740\ube5b \ub3d9\uc804\uc774 \ub193\uc5ec \uc788\uae30\ub3c4 \ud558\ub2e4. \ud6c4\uc2dd \uac12\uc744 \ubbf8\ub9ac \uacc4\uc0b0\ud574 \ub454 \uac83\uc77c\uae4c. \uadf8 \ub3d9\uc804\uc740 \uc601\uad6d\uc758 \uc2dd\uc2a4\ud39c\uc2a4\uc640 \uad00\ub828\ub41c \ud48d\uc2b5\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \ud478\ub529 \uc18d\uc5d0 \ub3d9\uc804\uc744 \uc228\uae30\uace0, \uadf8\uac83\uc744 \ucc3e\uc740 \uc0ac\ub78c\uc5d0\uac8c \ub2e4\uc74c \ud574\uc758 \uc88b\uc740 \uc6b4\uc774 \uc624\uae30\ub97c \ubc14\ub790\ub2e4\ub294 \uc774\uc57c\uae30\ub2e4. \ub3d9\uc804\uc774 \ub3c8\uc744 \ub0b4\ub294 \uc790\ub9ac\uc5d0\uc11c \uc7a0\uae50 \ubc97\uc5b4\ub098 \uc18c\uc6d0\uc744 \ub2f4\ub294 \ubb3c\uac74\uc774 \ub41c\ub2e4. \uc655\ub9bd\uc870\ud3d0\uad6d\uc740 2024\ub144 \ubcf4\ub3c4\uc790\ub8cc\uc5d0\uc11c \u2018\uc2a4\ud138\uc5c5 \uc120\ub370\uc774\u2019\ub77c\ub294 \ud48d\uc2b5\uc744 \uc18c\uac1c\ud588\ub2e4. \ub300\ub9bc\uc808\uc774 \uc2dc\uc791\ub418\uae30 \uc804 \ub9c8\uc9c0\ub9c9 \uc77c\uc694\uc77c, \uac00\uc871\uacfc \uce5c\uad6c\uac00 \ubaa8\uc5ec \ud06c\ub9ac\uc2a4\ub9c8\uc2a4 \ud478\ub529\uc744 \uc900\ube44\ud558\ub294 \ub0a0\uc774\ub2e4. \uc790\ub8cc\uc5d0 \uc18c\uac1c\ub41c \uc74c\uc2dd\uc0ac \uc5f0\uad6c\uc790 \uc560\ub2c8 \uadf8\ub808\uc774\ub294 \uc0ac\ub78c\ub4e4\uc774 \ubc18\uc8fd\uc744 \ubc88\uac08\uc544 \uc800\uc73c\uba70 \uc18c\uc6d0\uc744 \ube4c\ub358 \uc804\ud1b5\uc744 \uc124\uba85\ud55c\ub2e4. \ud06c\ub9ac\uc2a4\ub9c8\uc2a4 \ub2f9\uc77c\ub9cc \uae30\ub2e4\ub9ac\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \ubbf8\ub9ac \ubaa8\uc5ec \uc900\ube44\ud558\ub294 \uc2dc\uac04\uc5d0\ub3c4 \uc758\ubbf8\ub97c \ub450\uc5c8\ub358 \uc148\uc774\ub2e4. \uc774 \uc774\ub984\uc5d0\ub294 \u2018\uc800\uc5b4 \uc11e\ub2e4\u2019\ub77c\ub294 \ub73b\uacfc \uc5f0\uacb0\ub418\ub294 \ub9d0\uc7a5\ub09c\ub3c4 \uc788\ub2e4. \uadf8\ub808\uc774\ub294 \uad50\ud68c\uc758 \uae30\ub3c4\ubb38\uc5d0 \ub098\uc624\ub294 \ud45c\ud604\uc774 \ud478\ub529 \uc900\ube44\ub97c \ub5a0\uc62c\ub9ac\ub294 \uacc4\uae30\ub85c \uc4f0\uc600\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \uae38\uace0 \uc5b4\ub824\uc6b4 \uc124\uba85\ubcf4\ub2e4, \uc775\uc219\ud55c \ub9d0\uc744 \uc5f0\ub9d0\uc758 \ud560 \uc77c\uacfc \uc5ee\uc5b4 \uae30\uc5b5\ud55c \ubaa8\uc2b5\uc774 \uc7ac\ubbf8\uc788\ub2e4. \uac19\uc740 \uc790\ub8cc\ub294 \ub354 \uc624\ub798\ub41c \ud2b8\uc6f0\ud504\uc2a4 \ucf00\uc774\ud06c\uc5d0 \ud45c\uc2dd\uc744 \uc228\uae30\ub358 \ud48d\uc2b5\ub3c4 \uc774\uc57c\uae30\ud55c\ub2e4. \uc774\ud6c4\uc758 \ud478\ub529 \uc804\ud1b5\uc5d0\uc11c\ub294 \uc791\uc740 \ub3d9\uc804\uc744 \ucc3e\uc740 \uc0ac\ub78c\uc5d0\uac8c \ubd80\uc640 \uac74\uac15, \ud589\ubcf5\uc744 \uae30\uc6d0\ud588\ub2e4\ub294 \uac83\uc774\ub2e4. \ub3d9\uc804\uc744 \ucc3e\uc558\ub2e4\uace0 \uc2e4\uc81c\ub85c \ubbf8\ub798\uac00 \ub2ec\ub77c\uc9c4\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \ud55c \ud574\ub97c \ub9c8\ubb34\ub9ac\ud558\ub294 \uc790\ub9ac\uc5d0 \ub2e4\uc74c \ud574\uc758 \ubc14\ub78c\uc744 \uc5b9\uc5c8\ub2e4\ub294 \uc810\uc774\ub2e4. \ud3c9\ubc94\ud55c \ud6c4\uc2dd\uc5d0 \uc791\uc740 \ub73b\ubc16\uc758 \uc77c\uc774 \ub354\ud574\uc9c4\ub2e4. \uadf8\ub798\uc11c \uc774 \uc774\uc57c\uae30\uc5d0\uc11c \ub3d9\uc804\uc758 \uc561\uba74\uc740 \uc8fc\uc778\uacf5\uc774 \uc544\ub2c8\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \ud568\uaed8 \uc900\ube44\ud558\uace0, \ub204\uad70\uac00 \uc88b\uc740 \uac83\uc744 \ubc1c\uacac\ud558\uae30\ub97c \uae30\ub300\ud588\ub2e4\ub294 \uae30\uc5b5\uc774 \ub3d9\uc804 \uc8fc\ubcc0\uc5d0 \ub0a8\ub294\ub2e4. \ud478\ub529\uc744 \uc900\ube44\ud558\ub294 \ub0a0\uc5d0 \ubaa8\uc5ec \ubc18\uc8fd\uc744 \uc813\ub294\ub2e4\ub294 \uc774\uc57c\uae30\ub294 \ud06c\ub9ac\uc2a4\ub9c8\uc2a4\uc758 \uc911\uc2ec\uc744 \uc2dd\ud0c1\uc758 \ud55c\uc21c\uac04\uc5d0\uc11c \uc55e\uc120 \uc2dc\uac04\uc73c\ub85c \uc62e\uae34\ub2e4. \ub9cc\ub4dc\ub294 \uacfc\uc815\uc5d0 \ud568\uaed8 \ucc38\uc5ec\ud558\uba74 \uc74c\uc2dd\uc740 \ub204\uad70\uac00 \uc644\uc131\ud574\uc11c \ub0b4\ub193\ub294 \uacb0\uacfc\ub9cc\uc774 \uc544\ub2c8\ub77c \uac19\uc774 \uc900\ube44\ud55c \uae30\uc5b5\ub3c4 \uac16\uac8c \ub41c\ub2e4. \ub2ec\ub825\uc758 \ud2b9\uc815\ud55c \ub0a0\uacfc \ubc18\ubcf5\ub418\ub294 \ud589\ub3d9\uc774 \ud574\ub9c8\ub2e4 \uc5f0\uacb0\ub418\ub294 \uc148\uc774\ub2e4. \ub2e4\ub9cc \ubaa8\ub4e0 \uac00\uc815\uc774 \uc5b8\uc81c\ub098 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uc774 \ud48d\uc2b5\uc744 \uc9c0\ucf30\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc790\ub8cc\ub294 \ud2b9\uc815 \uc804\ud1b5\uc744 \uc18c\uac1c\ud558\uace0 \ub418\uc0b4\ub9ac\ub824\ub294 \ubaa9\uc801\uc73c\ub85c \uc4f0\uc600\ub2e4. \uba85\uc808\uc758 \ud48d\uc2b5\uc5d0\ub294 \uc774\uc5b4\uc9c4 \uc2e4\ucc9c\ubfd0 \uc544\ub2c8\ub77c \ub098\uc911\uc5d0 \ub2e4\uc2dc \uac15\uc870\ud558\uace0 \uc0c1\ud488\uacfc \uc5f0\uacb0\ud558\ub294 \uc120\ud0dd\ub3c4 \uc788\ub2e4. \uc9c0\uae08 \uc77d\ub294 \uc124\uba85\uc774 \uc5b4\ub290 \uc2dc\uc810\uc5d0 \uc5b4\ub5a4 \ubaa9\uc801\uc73c\ub85c \uc804\ud574\uc9c0\ub294\uc9c0 \ud568\uaed8 \ubcf4\uba74 \ub354 \uc815\ud655\ud558\ub2e4. \uc2a4\ud138\uc5c5\uc774\ub77c\ub294 \ud45c\ud604\uc740 \uc885\uad50\uc801 \ubb38\ub9e5\uc758 \ub9d0\uacfc \ubc18\uc8fd\uc744 \uc813\ub294 \ud589\ub3d9\uc744 \uc5f0\uacb0\ud558\ub294 \ub9d0\uc7a5\ub09c\uc73c\ub85c \uc18c\uac1c\ub41c\ub2e4. \uc5b4\ub824\uc6b4 \uad50\ub9ac\ub97c \ubaa8\ub450 \uc54c\uc544\uc57c\ub9cc \uc774\ud574\ud560 \uc218 \uc788\ub294 \uc7a5\uba74\uc740 \uc544\ub2c8\ub2e4. \uc774\ubbf8 \uc775\uc219\ud55c \ud45c\ud604\uc774 \uacc4\uc808\uc758 \uc900\ube44\uc640 \ub9cc\ub098 \uae30\uc5b5\ud558\uae30 \uc26c\uc6b4 \uc774\ub984\uc774 \ub418\uc5c8\ub2e4\ub294 \uc810\uc744 \ubcfc \uc218 \uc788\ub2e4. \uac19\uc740 \ub9d0\ub3c4 \uc7a5\uc18c\uac00 \ub2ec\ub77c\uc9c0\uba74 \ub2e4\ub978 \ud589\ub3d9\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \uc774\ub984\uc744 \uae30\uc5b5\ud55c\ub2e4\uace0 \uc720\ub798\uc758 \ubaa8\ub4e0 \uc2dc\uac04\uc774 \ud655\uc815\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub290 \uc124\uba85\uc774 \uc74c\uc2dd\uc0ac \uc5f0\uad6c\uc790\uc758 \ud574\uc124\uc774\uace0 \uc5b4\ub290 \ubd80\ubd84\uc774 \uc9c0\uae08\uc758 \ud64d\ubcf4 \ubb38\uad6c\uc778\uc9c0 \uad6c\ubd84\ud558\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc804\ud1b5\uc758 \uc774\uc57c\uae30\ub294 \uc790\ub8cc\ub97c \uc77d\ub294 \ud604\uc7ac\uc5d0\ub3c4 \uc0c8\ub85c \uafb8\ub824\uc838 \uc804\ub2ec\ub41c\ub2e4. \uc774\ub984\uc774 \uc7ac\ubbf8\uc788\ub2e4\ub294 \uac10\uc0c1\uacfc \uadf8 \uc720\ub798\uac00 \uc5b4\ub5a4 \uadfc\uac70\ub85c \uc18c\uac1c\ub418\ub294\uc9c0\uc758 \uc9c8\ubb38\uc744 \ud568\uaed8 \uac00\uc9c8 \uc218 \uc788\ub2e4. \uc791\uc740 \ud45c\uc2dd\uc744 \uc74c\uc2dd \uc548\uc5d0\uc11c \ucc3e\ub294 \ud48d\uc2b5\uc740 \uc815\ud574\uc9c4 \uc21c\uc11c\uc5d0 \ub73b\ubc16\uc758 \uc21c\uac04\uc744 \ub354\ud55c\ub2e4. \ub204\uac00 \ubc1c\uacac\ud560\uc9c0 \ubaa8\ub974\ub294 \ud45c\uc9c0\ub294 \uadf8 \uc790\ub9ac\uc5d0 \uc788\ub294 \uc0ac\ub78c\ub4e4\uc758 \uae30\ub300\ub97c \ubaa8\uc744 \uc218 \uc788\ub2e4. \ub3d9\uc804\uc758 \uae08\uc18d \uac00\uce58\ub098 \uc561\uba74\ub9cc\uc73c\ub85c \uc124\uba85\ud558\uae30 \uc5b4\ub824\uc6b4 \uc4f0\uc784\uc774\ub2e4. \uba39\ub294 \uc74c\uc2dd\uacfc \ubc1c\uacac\uc744 \uae30\ub2e4\ub9ac\ub294 \ub180\uc774, \uc88b\uc740 \ub73b\uc758 \uae30\uc6d0\uc774 \uc5f0\uacb0\ub41c\ub2e4. \ubb3c\ub860 \ud45c\uc2dd\uc744 \ucc3e\uc740 \uc0ac\ub78c\uc758 \ubbf8\ub798\uac00 \uc2e4\uc81c\ub85c \ub2ec\ub77c\uc84c\ub2e4\ub294 \uc99d\uac70\ub97c \ub9d0\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubb38\ud654\uc801 \uc758\ubbf8\ub97c \uc790\uc5f0\uc758 \uc778\uacfc\uad00\uacc4\ub85c \ubc14\uafb8\uc9c0 \uc54a\uc544\ub3c4 \uc774\uc57c\uae30\ub294 \ucda9\ubd84\ud788 \uc7ac\ubbf8\uc788\ub2e4. \uc774 \uae00\uc740 \uc720\ub798\ub97c \uc18c\uac1c\ud558\uba70 \uc2e4\uc81c \uc74c\uc2dd\uc5d0 \ub3d9\uc804\uc744 \ub123\uc5b4 \uc870\ub9ac\ud558\ub294 \ubc29\ubc95\uc744 \uc548\ub0b4\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc804\ud1b5\uc744 \uc77d\ub294 \uc77c\uacfc \uadf8\ub300\ub85c \uc2e4\ud589\ud558\ub294 \uc77c\uc740 \uad6c\ubd84\ud560 \uc218 \uc788\ub2e4. \uc655\ub9bd\uc870\ud3d0\uad6d\uc774 \uc774 \uc804\ud1b5\uc744 \uc18c\uac1c\ud55c\ub2e4\ub294 \uc0ac\uc2e4\ub3c4 \ub208\uc5ec\uaca8\ubcfc \ub9cc\ud558\ub2e4. \uc74c\uc2dd\ub9cc\uc774 \uc544\ub2c8\ub77c \ub3d9\uc804\uc774 \uc0ac\ub78c\ub4e4\uc758 \uae30\uc5b5 \uc18d\uc5d0\uc11c \uc5b4\ub5bb\uac8c \uc4f0\uc600\ub294\uc9c0\ub97c \ubcf4\uc5ec \uc904 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \ub3d9\uc2dc\uc5d0 \uc0c1\ud488\uacfc \uc5f0\uacb0\ud55c \ubcf4\ub3c4\uc790\ub8cc\ub77c\ub294 \uc131\uaca9\uc774 \uc788\ub2e4. \uc5ed\uc0ac \uc774\uc57c\uae30\uac00 \ud2b9\uc815\ud55c \ubb3c\uac74\uc758 \ud64d\ubcf4\uc5d0 \uc4f0\uc778\ub2e4\ub294 \uc810\uc744 \uc228\uae30\uc9c0 \uc54a\uace0 \uc77d\uc73c\uba74 \uc815\ubcf4\uc758 \ub9e5\ub77d\uc774 \ub354 \ubd84\uba85\ud574\uc9c4\ub2e4. \uc774 \uc0ac\ub840\uc5d0\uc11c\ub294 \uc74c\uc2dd\uc0ac \uc5f0\uad6c\uc790\uc758 \uc124\uba85\uacfc \uc790\ub8cc\uc758 \ubaa9\uc801\uc744 \ub098\ub780\ud788 \ub193\ub294\ub2e4. \ud64d\ubcf4 \uc790\ub8cc\ub77c\uace0 \ubaa8\ub4e0 \uc124\uba85\uc744 \uc9c0\uc6b8 \ud544\uc694\ub3c4, \uae30\uad00 \uc774\ub984\uc774 \uc788\ub2e4\uace0 \ubaa8\ub4e0 \uacfc\uc7a5\uc744 \uc0ac\uc2e4\ub85c \ubc1b\uc744 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \ub204\uad6c\uc758 \uc5b4\ub5a4 \uc124\uba85\uc744 \uadfc\uac70\ub85c \uc0bc\uc558\ub294\uc9c0 \ud655\uc778\ud558\uba70 \ub0a8\uae38 \ubd80\ubd84\uc744 \uace0\ub974\ub294 \uac83\uc774\ub2e4. \ud06c\ub9ac\uc2a4\ub9c8\uc2a4 \ud478\ub529\uc758 \ub3d9\uc804\uc740 \uba85\uc808\uc758 \ubd80\uc5cc\uacfc \uc624\ub298\uc758 \uc804\ud1b5 \uc18c\uac1c\uac00 \ub9cc\ub098\ub294 \uc791\uc740 \ubb3c\uac74\uc774\ub2e4. \uc655\ub9bd\uc870\ud3d0\uad6d\uc774 \uc774 \uc790\ub8cc\ub97c \ub0b8 \uac83\uc740 \uc804\ud1b5\uc744 \ub418\uc0b4\ub9ac\ub824\ub294 \uc0c1\ud488 \ud64d\ubcf4\uc640\ub3c4 \uad00\ub828\uc774 \uc788\ub2e4. \uadf8\ub7ec\ub2c8 \uc624\ub298\uc758 \uc601\uad6d \uac00\uc815\uc774 \ubaa8\ub450 \uac19\uc740 \ud478\ub529\uc744 \ub9cc\ub4e4\uace0 \uac19\uc740 \ud48d\uc2b5\uc744 \uc9c0\ud0a8\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uadf8 \uc810\uc744 \uc54c\uace0 \uc77d\uc5b4\ub3c4 \uc791\uc740 \uc774\uc57c\uae30\ub294 \ub0a8\ub294\ub2e4. \ud2b9\ubcc4\ud55c \ub0a0\uc758 \uc74c\uc2dd\uc5d0\ub294 \ub9db\uacfc \uc7ac\ub8cc\ub9cc \ub4e4\uc5b4\uac00\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc900\ube44\ud558\ub294 \uc21c\uc11c, \ud568\uaed8\ud558\ub294 \uc0ac\ub78c, \uc88b\uc740 \uc6b4\uc744 \ubc14\ub77c\ub358 \ub9c8\uc74c\ub3c4 \ubd99\uc5b4 \uc788\ub2e4. \ub2e4\uc74c\uc5d0 \ud478\ub529 \uc606\uc758 \uc740\ube5b \ub3d9\uc804\uc744 \ubcf4\uac8c \ub41c\ub2e4\uba74 \ud6c4\uc2dd \uac12 \ub300\uc2e0 \ub204\uad70\uac00\uc758 \uc18c\uc6d0\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc774\ubc88 \uc0bd\ud654\ucc98\ub7fc \ub3d9\uc804\uc744 \uc811\uc2dc \ubc16\uc5d0 \ub098\ub780\ud788 \ub193\uc544\ub450\uc5b4\ub3c4, \uadf8 \uc791\uc740 \ubb3c\uac74\uc774 \ub4e4\ub824\uc8fc\ub294 \uc5f0\ub9d0 \uc774\uc57c\uae30\ub294 \ucda9\ubd84\ud788 \uc804\ud574\uc9c4\ub2e4."}, {"id": "coffeehouse-news-and-conversation", "title": "\ucee4\ud53c\ud558\uc6b0\uc2a4 \u2014 \ucee4\ud53c \ud55c \uc794 \uc606\uc5d0 \ub274\uc2a4\uac00 \ub193\uc600\ub358 \uc774\uc720", "summary": "\uc61b \ucee4\ud53c\ud558\uc6b0\uc2a4\uc758 \ub300\ud654\uc640 \uc778\uc1c4\ubb3c, \uac70\ub798\ub97c \uc0b4\ud3b4\ubcf4\uba70 \uc74c\ub8cc\ub97c \ub9c8\uc2dc\ub294 \uc7a5\uc18c\uac00 \uc0ac\ud68c\uc801 \uacf5\uac04\uc774 \ub418\ub294 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "life", "category_title": "Life", "subcategory": "Food", "url": "stories/coffeehouse-news-and-conversation/index.html", "image": "media/coffeehouse-news-and-conversation.jpg", "alt": "\ud0c1\uc790 \uc8fc\uc704\uc5d0 \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc778 \uc61b \ucee4\ud53c\ud558\uc6b0\uc2a4\uc758 \uc2e4\uc81c \ubaa9\ud310\ud654 \uc7ac\ud604 \ub3c4\ud310.", "text": "\ucee4\ud53c\ud558\uc6b0\uc2a4 \u2014 \ucee4\ud53c \ud55c \uc794 \uc606\uc5d0 \ub274\uc2a4\uac00 \ub193\uc600\ub358 \uc774\uc720 \uc61b \ub7f0\ub358\uc758 \uc791\uc740 \uac00\uac8c\uc5d0\uc11c \uc0ac\ub78c\ub4e4\uc774 \ub098\ub208 \uac83\ub4e4 \uc61b \ucee4\ud53c\ud558\uc6b0\uc2a4\uc758 \ub300\ud654\uc640 \uc778\uc1c4\ubb3c, \uac70\ub798\ub97c \uc0b4\ud3b4\ubcf4\uba70 \uc74c\ub8cc\ub97c \ub9c8\uc2dc\ub294 \uc7a5\uc18c\uac00 \uc0ac\ud68c\uc801 \uacf5\uac04\uc774 \ub418\ub294 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Food \uc0dd\ud65c \ucee4\ud53c\ub97c \uc8fc\ubb38\ud558\uace0 \uc790\ub9ac\uc5d0 \uc549\ub294\ub2e4. \uc606 \ud14c\uc774\ube14\uc5d0\uc11c\ub294 \uc815\uce58 \uc774\uc57c\uae30\uac00 \ub4e4\ub9ac\uace0, \ub204\uad70\uac00\ub294 \uc0c8\ub85c \ub098\uc628 \uc18c\uc2dd\uc744 \uc77d\ub294\ub2e4. \uc9c0\uae08\uc758 \uce74\ud398\uc5d0\uc11c\ub3c4 \ub0af\uc124\uc9c0 \uc54a\uc740 \uc7a5\uba74\uc774\uc9c0\ub9cc, 17~18\uc138\uae30 \ub7f0\ub358\uc758 \ucee4\ud53c\ud558\uc6b0\uc2a4\uc5d0\uc11c\ub294 \uc774\ub7f0 \ub9cc\ub0a8\uc774 \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud588\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \uc74c\ub8cc\uc640 \ud568\uaed8 \uc774\uc57c\uae30\uc640 \uc815\ubcf4\ub97c \uc5bb\uc5c8\ub2e4. \uc70c\ub9ac\uc5c4 \ud574\ub9ac\uc2a8 \uc720\ucee4\uc2a4\uac00 1922\ub144\uc5d0 \ud3b4\ub0b8 \u300eAll About Coffee\u300f\uc5d0\ub294 \uc61b \ucee4\ud53c\ud558\uc6b0\uc2a4\uc758 \uc790\ub8cc\uc640 \uadf8\ub9bc\uc774 \ub9ce\uc774 \ubaa8\uc5ec \uc788\ub2e4. \uc0c1\uc5c5\uacfc \ucee4\ud53c \ubb38\ud654\ub97c \ud3ed\ub113\uac8c \ub2e4\ub8ec \uc624\ub798\ub41c \ucc45\uc774\ubbc0\ub85c \ubaa8\ub4e0 \uc124\uba85\uc744 \uadf8\ub300\ub85c \ud655\uc815\ud558\uc9c0\ub294 \uc54a\uc73c\uba74\uc11c, \uc5b4\ub5a4 \ud65c\ub3d9\uc774 \ud55c \uc7a5\uc18c\uc5d0 \ubaa8\uc600\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uc601\uad6d\uc5d0\uc11c \ucee4\ud53c\ub294 \ucc98\uc74c\ubd80\ud130 \ub204\uad6c\ub098 \uc544\ub294 \uc77c\uc0c1 \uc74c\ub8cc\uac00 \uc544\ub2c8\uc5c8\ub2e4. \ucc45\uc740 1652\ub144 \ub7f0\ub358\uc758 \ud30c\uc2a4\ucf70 \ub85c\uc81c\uc640 \ucee4\ud53c \ud310\ub9e4\uc758 \ucd08\uae30 \uc5ed\uc0ac\ub97c \uc124\uba85\ud55c\ub2e4. \ub0af\uc120 \uc74c\ub8cc\ub97c \ud314\ub824\uba74 \ub9db\ubfd0 \uc544\ub2c8\ub77c \uc5b4\ub5a4 \ubb3c\uac74\uc778\uc9c0, \uc65c \ub9c8\uc2e4 \ub9cc\ud55c\uc9c0 \uc54c\ub9ac\ub294 \ub9d0\ub3c4 \ud544\uc694\ud588\ub2e4. \uc61b \uad11\uace0\uc5d0\ub294 \uc624\ub298\uc758 \uae30\uc900\uc73c\ub85c \ubc1b\uc544\ub4e4\uc774\uae30 \uc5b4\ub824\uc6b4 \uac74\uac15 \uc8fc\uc7a5\ub3c4 \uc2e4\ub838\ub2e4. \uadf8\ub7f0 \ud6a8\ub2a5\uc744 \uc774 \uae00\uc5d0\uc11c \ub418\ud480\uc774\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uad11\uace0\ub97c \ud765\ubbf8\ub86d\uac8c \uc77d\uc744 \uc9c0\uc810\uc740 \ub2f9\uc2dc \uc0ac\ub78c\ub4e4\uc774 \uc0c8\ub85c\uc6b4 \uc74c\ub8cc\ub97c \uc5b4\ub5bb\uac8c \uc124\uba85\ud558\ub824 \ud588\ub294\uac00\ub2e4. \ucee4\ud53c\uc758 \ub9db\uc774 \uc54c\ub824\uc9c0\ub294 \uacfc\uc815\uc5d0\ub294 \uc774\uc57c\uae30\uc640 \uc778\uc1c4\ubb3c\ub3c4 \ud568\uaed8 \uc788\uc5c8\ub2e4. \ucee4\ud53c\ud558\uc6b0\uc2a4\ub294 \uc220\uc744 \uc911\uc2ec\uc5d0 \ub193\uc740 \uc7a5\uc18c\uc640 \ub2e4\ub978 \uc131\uaca9\uc73c\ub85c \uc774\uc57c\uae30\ub418\uc5c8\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \ucee4\ud53c\ub97c \ub9c8\uc2dc\uba70 \ub300\ud654\ud558\uace0 \uc790\ub8cc\ub97c \uc77d\uc744 \uc218 \uc788\uc5c8\ub2e4. \ub2e4\ub9cc \uc61b \ucc45\uc774 \uc220\uc9d1\uacfc \ucee4\ud53c\ud558\uc6b0\uc2a4\ub97c \uc120\uba85\ud558\uac8c \ub300\ube44\ud55c\ub2e4\uace0 \ud574\uc11c \ubaa8\ub4e0 \uac00\uac8c\uac00 \ud56d\uc0c1 \uc870\uc6a9\ud558\uace0 \uc810\uc796\uc558\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5b4\ub5a4 \uc74c\ub8cc\ub97c \ud310\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uadf8 \uacf5\uac04\uc758 \ubb38\ud654\uac00 \uc790\ub3d9\uc73c\ub85c \uc815\ud574\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub204\uac00 \ubaa8\uc774\uace0 \ubb34\uc5c7\uc744 \ud558\uba70 \uc5bc\ub9c8\ub098 \uc624\ub798 \uba38\ubb34\ub294\uc9c0\uac00 \ud568\uaed8 \uc911\uc694\ud558\ub2e4. \ucee4\ud53c\ud558\uc6b0\uc2a4\uc758 \ud765\ubbf8\ub85c\uc6b4 \uc810\uc740 \uc794 \uc18d\uc5d0 \ub4e0 \uac83\ubfd0 \uc544\ub2c8\ub77c \uac19\uc740 \ud14c\uc774\ube14 \uc8fc\ubcc0\uc5d0\uc11c \ubc8c\uc5b4\uc9c4 \ud65c\ub3d9\uc5d0 \uc788\ub2e4. \ucc45\uc740 \ucee4\ud53c\ud558\uc6b0\uc2a4\uc758 \uc2e0\ubb38\uacfc \uc77d\uc744\uac70\ub9ac, \uc18c\uc2dd\uc744 \ub458\ub7ec\uc2fc \ud1a0\ub860\uc744 \uc124\uba85\ud55c\ub2e4. \uac19\uc740 \uc790\ub8cc\ub97c \uc5ec\ub7ec \uc0ac\ub78c\uc774 \uc811\ud558\uba74 \ub204\uad70\uac00 \uc77d\uc740 \ubb38\uc7a5\uc774 \ub2e4\ub978 \uc0ac\ub78c\uc758 \ub9d0\uc774 \ub420 \uc218 \uc788\ub2e4. \uc815\ubcf4\ub97c \uc5bb\ub294 \uc77c\uacfc \uadf8 \uc815\ubcf4\uc5d0 \uad00\ud574 \uc758\uacac\uc744 \ub098\ub204\ub294 \uc77c\uc774 \ud55c \uc7a5\uc18c\uc5d0\uc11c \uc774\uc5b4\uc84c\ub2e4. \uc77d\ub294 \ub2a5\ub825\uacfc \ub300\ud654\uc758 \uc790\ub9ac\ub3c4 \uc11c\ub85c \ub9cc\ub09c\ub2e4. \ud63c\uc790 \uc870\uc6a9\ud788 \ub05d\ub0b8 \ub3c5\uc11c\uc640 \ub2ec\ub9ac \ub2e4\ub978 \uc0ac\ub78c\uc740 \uac19\uc740 \uc18c\uc2dd\uc744 \uc5b4\ub5bb\uac8c \uc774\ud574\ud588\ub294\uc9c0 \uace7\ubc14\ub85c \uc54c \uc218 \uc788\ub2e4. \ubb3c\ub860 \ub9d0\uc774 \uc624\uac04\ub2e4\uace0 \ubaa8\ub450 \uc815\ud655\ud55c \uc815\ubcf4\uac00 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc0c8 \uc18c\uc2dd\uacfc \ucd94\uce21, \uc18c\ubb38\ub3c4 \uac19\uc740 \uacf5\uac04\uc744 \uc6c0\uc9c1\uc77c \uc218 \uc788\uc5c8\ub2e4. \uc790\ub8cc\uc5d0\ub294 \ucee4\ud53c\ud558\uc6b0\uc2a4\ub97c \ud398\ub2c8 \ub300\ud559\uc774\ub77c\uace0 \ubd80\ub978 \uc0ac\ub840\uac00 \ub098\uc628\ub2e4. \ube44\uad50\uc801 \uc791\uc740 \ub3c8\uc744 \ub0b4\uace0 \ub300\ud654\uc640 \uc815\ubcf4\uc5d0 \uc811\ud560 \uc218 \uc788\ub294 \uacf5\uac04\uc774\ub77c\ub294 \uc778\uc2dd\uc774 \ub2f4\uae34 \ubcc4\uba85\uc774\ub2e4. \uac15\uc758\uc2e4\uacfc \ud559\uc704\ub97c \uac16\ucd98 \uc2e4\uc81c \ub300\ud559\uc774 \ub418\uc5c8\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc785\uc7a5\uacfc \uc74c\ub8cc, \uc77d\uc744\uac70\ub9ac\uc758 \ube44\uc6a9\uc740 \uc2dc\uae30\uc640 \uc7a5\uc18c\uc5d0 \ub530\ub77c \ub2e4\ub97c \uc218 \uc788\ub2e4. \uc5b4\ub514\uc11c\ub098 \ucee4\ud53c \ud55c \uc794\uc774 \uc815\ud655\ud788 1\ud398\ub2c8\uc600\ub2e4\uace0 \uc678\uc6b0\uae30\ubcf4\ub2e4, \ubc30\uc6c0\uc774 \ubc18\ub4dc\uc2dc \uacf5\uc2dd \ud559\uad50 \uc548\uc5d0\uc11c\ub9cc \uc77c\uc5b4\ub098\uc9c0\ub294 \uc54a\ub294\ub2e4\ub294 \ub2f9\uc2dc\uc758 \ube44\uc720\ub85c \uc77d\uc73c\uba74 \uc88b\ub2e4. \ub2e4\ub978 \uc0ac\ub78c\uc758 \ub9d0\uc744 \ub4e3\ub294 \uacbd\ud5d8\ub3c4 \uc9c0\uc2dd\uc758 \ud55c \ud1b5\ub85c\uac00 \ub418\uc5c8\ub2e4. \uc11c\ub85c \ube44\uc2b7\ud55c \uad00\uc2ec\uc744 \uac00\uc9c4 \uc0ac\ub78c\uc774 \ubc18\ubcf5\ud574\uc11c \uac19\uc740 \uacf3\uc5d0 \uc624\uba74 \uac00\uac8c\ub294 \uadf8 \ubd84\uc57c\uc758 \uc815\ubcf4\ub97c \ucc3e\ub294 \uc7a5\uc18c\uac00 \ub420 \uc218 \uc788\ub2e4. \uc61b \ub7f0\ub358 \ucee4\ud53c\ud558\uc6b0\uc2a4\uc758 \uae30\ub85d\uc5d0\ub294 \ubb38\ud559\uacfc \uc815\uce58\ubfd0 \uc544\ub2c8\ub77c \ud574\uc6b4\uacfc \uac70\ub798\uc758 \uc18c\uc2dd\ub3c4 \ub4f1\uc7a5\ud55c\ub2e4. \ub85c\uc774\uc988 \uac19\uc740 \uc774\ub984\ub3c4 \uc774\ub7f0 \ucee4\ud53c\ud558\uc6b0\uc2a4\uc758 \uc5ed\uc0ac\uc640 \uc774\uc5b4\uc9c4\ub2e4. \ub204\uac00 \ub3cc\uc544\uc654\ub294\uc9c0, \uc5b4\ub5a4 \ubc30\uac00 \uc5b4\ub514\ub85c \uac14\ub294\uc9c0 \uac19\uc740 \uc18c\uc2dd\uc740 \ub300\ud654\uc758 \uc18c\uc7ac\uc774\uba74\uc11c \uac70\ub798\uc758 \ud310\ub2e8 \uc790\ub8cc\uac00 \ub420 \uc218 \uc788\uc5c8\ub2e4. \uac19\uc740 \uacf5\uac04\uc5d0\uc11c \uc790\uc8fc \uc5bc\uad74\uc744 \ub9c8\uc8fc\ud558\ub294 \uc77c\ub3c4 \uad00\uacc4\ub97c \ub9cc\ub4e0\ub2e4. \ucee4\ud53c \uc790\uccb4\uc758 \uac00\uaca9\uc744 \ub118\uc5b4, \uadf8 \uc7a5\uc18c\uc5d0\uc11c \ub9cc\ub0a0 \uc218 \uc788\ub294 \uc815\ubcf4\uc640 \uc0ac\ub78c\uc774 \uac00\uce58\ub97c \uac16\uac8c \ub418\ub294 \uac83\uc774\ub2e4. \ud398\ub2c8 \ub300\ud559\uc774\ub77c\ub294 \ubc1d\uc740 \ubcc4\uba85\ub9cc\uc73c\ub85c \uc644\uc804\ud788 \ud3c9\ub4f1\ud55c \uc0ac\ud68c\uac00 \uc2e4\ud604\ub418\uc5c8\ub2e4\uace0 \ub9d0\ud558\uae30\ub294 \uc5b4\ub835\ub2e4. \uadf8\ub9bc\uacfc \uae30\ub85d\uc5d0 \ub098\ud0c0\ub098\ub294 \ucc38\uc11d\uc790\uc758 \ubaa8\uc2b5, \ub2f9\uc2dc\uc758 \uc131\ubcc4\uacfc \uacc4\uce35 \uc9c8\uc11c\ub97c \ud568\uaed8 \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4. \uc801\uc740 \uc785\uc7a5 \ube44\uc6a9\uacfc \ubaa8\ub450\uc5d0\uac8c \uac19\uc740 \uae30\ud68c\ub294 \uac19\uc740 \ub9d0\uc774 \uc544\ub2c8\ub2e4. \ucc45\uc5d0 \uc2e4\ub9b0 \uc774\uc0c1\uc801\uc778 \ub300\ud654\uc758 \ubd84\uc704\uae30\ub3c4 \ubaa8\ub4e0 \uc774\uc6a9\uc790\uc758 \uacbd\ud5d8\uc744 \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub204\uac00 \ub9d0\ud560 \uc218 \uc788\uc5c8\uace0 \ub204\uac00 \uadf8 \uc790\ub9ac\uc5d0 \uc5c6\uc5c8\ub294\uc9c0 \ubb3b\ub294 \uac83\uc740 \ucee4\ud53c\ud558\uc6b0\uc2a4\ub97c \uae4e\uc544\ub0b4\ub9ac\ub824\ub294 \uc77c\uc774 \uc544\ub2c8\ub2e4. \uc911\uc694\ud55c \uc0ac\ud68c \uacf5\uac04\uc774\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ub354 \uad6c\uccb4\uc801\uc73c\ub85c \uc774\ud574\ud558\ub824\ub294 \uc9c8\ubb38\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\uc740 \ucc45\uc774 1674\ub144 \ubaa9\ud310\ud654\uc5d0\uc11c \uac00\uc838\uc654\ub2e4\uace0 \uc124\uba85\ud558\ub294 \ucee4\ud53c\ud558\uc6b0\uc2a4 \uc7a5\uba74\uc758 \uc7ac\ud604 \ub3c4\ud310\uc774\ub2e4. \ud0c1\uc790 \uc8fc\ubcc0\uc5d0 \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc774\uace0, \ub4a4\uc640 \uc606\uc5d0\uc11c\ub3c4 \uc778\ubb3c\ub4e4\uc774 \uad00\uacc4\ub97c \ub9cc\ub4e0\ub2e4. \uc624\ub298\uc758 \uac1c\uc778\uc6a9 \ub178\ud2b8\ubd81\ucc98\ub7fc \uac01\uc790\uc758 \uc791\uc740 \ud654\uba74\uc774 \uacf5\uac04\uc744 \ub098\ub204\uc9c0\ub294 \uc54a\ub294\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc774 \ud55c \uc7a5\uc774 \ub2f9\uc2dc \ub7f0\ub358\uc758 \ubaa8\ub4e0 \uac00\uac8c\ub97c \uc815\ud655\ud788 \ubcf4\uc5ec \uc8fc\ub294 \uc0ac\uc9c4\uc740 \uc544\ub2c8\ub2e4. \uc81c\uc791\uc790\uc758 \ud45c\ud604\uc744 \uac70\uce5c \uc774\ubbf8\uc9c0\uc774\uba70 \ud6c4\ub300 \ucc45\uc5d0 \ub2e4\uc2dc \uc2e4\ub9b0 \uc790\ub8cc\ub2e4. \ub204\uac00 \uc5b4\ub514\uc5d0 \uc11c\uace0 \ub204\uac00 \ub204\uad6c\ub97c \ud5a5\ud558\ub294\uc9c0 \uba3c\uc800 \uc0b4\ud3b4\ubcf4\uba74, \uc74c\ub8cc\uc758 \uc6a9\uae30\ubcf4\ub2e4 \uc0ac\ub78c \uc0ac\uc774\uc758 \ubc30\uce58\uac00 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uc624\ub298\uc758 \uce74\ud398\uc5d0 \uc549\uc544 \uc0ac\ub78c\ub4e4\uc758 \ub2e4\uc591\ud55c \ubaa9\uc801\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \ud63c\uc790 \uc77d\uace0 \uc77c\ud558\ub294 \uc0ac\ub78c\ub3c4, \ub204\uad70\uac00\ub97c \ub9cc\ub098 \uc18c\uc2dd\uc744 \ub4e3\ub294 \uc0ac\ub78c\ub3c4 \uc788\ub2e4. \uac19\uc740 \uc74c\ub8cc\ub97c \uc0ac\ub3c4 \uac01\uc790\uac00 \uc0ac\ub294 \uc2dc\uac04\uacfc \uad00\uacc4\ub294 \ub2e4\ub974\ub2e4. \uc61b \ucee4\ud53c\ud558\uc6b0\uc2a4\uc758 \uc774\uc57c\uae30\ub97c \uadf8\ub300\ub85c \ud604\uc7ac\uc640 \uac19\uac8c \ub193\uc744 \ud544\uc694\ub294 \uc5c6\uc9c0\ub9cc \uc774\ub7f0 \uc9c8\ubb38\uc740 \uc774\uc5b4\uc9c4\ub2e4. \ucee4\ud53c\ud558\uc6b0\uc2a4\ub294 \ucee4\ud53c\uac00 \uc0ac\ub78c\uc744 \ud604\uba85\ud558\uac8c \ub9cc\ub4e0\ub2e4\ub294 \uc804\uc124\ubcf4\ub2e4, \uc0ac\ub78c\ub4e4\uc774 \ubc18\ubcf5\ud574\uc11c \ubaa8\uc77c \uc790\ub9ac\uac00 \ubb34\uc5c7\uc744 \uac00\ub2a5\ud558\uac8c \ud558\ub294\uc9c0 \ubcf4\uc5ec \uc900\ub2e4. \ud55c \uc794\uc740 \uc9e7\uac8c \ub9c8\uc2e4 \uc218 \uc788\uc5b4\ub3c4 \uadf8 \uc606\uc5d0\uc11c \ub098\ub208 \uc815\ubcf4\uc640 \ub300\ud654\ub294 \ub354 \uba40\ub9ac \uac08 \uc218 \uc788\ub2e4. \uc74c\ub8cc\uc758 \uc5ed\uc0ac\uac00 \uace7 \ub9cc\ub0a8\uc758 \uc5ed\uc0ac\ub85c \ub113\uc5b4\uc9c0\ub294 \uc9c0\uc810\uc774\ub2e4."}, {"id": "crane-embroidered-badge", "title": "\uad00\ubcf5\uc758 \ud559 \ub450 \ub9c8\ub9ac\ub294 \ubb34\uc5c7\uc744 \uc54c\ub824\uc904\uae4c", "summary": "\uc637 \uc704\uc758 \uc791\uc740 \uadf8\ub9bc\uc5d0\ub294 \uc785\ub294 \uc0ac\ub78c\uc758 \uc9c0\uc704\uc640 \uc790\uc218\uc758 \uc19c\uc528\uac00 \ud568\uaed8 \ub2f4\uacbc\uc2b5\ub2c8\ub2e4.", "category": "life", "category_title": "Life", "subcategory": "Clothing", "url": "stories/crane-embroidered-badge/index.html", "image": "media/crane-embroidered-badge.jpg", "alt": "\ub450 \ud559\uacfc \uc2dd\ubb3c \ubb34\ub2ac\ub97c \uc5ec\ub7ec \uc0c9 \uc2e4\ub85c \uc218\ub193\uc740 \uc30d\ud559\ubb34\ub2ac \ud749\ubc30\uc758 \uc138\ubd80 \uc0ac\uc9c4", "text": "\uad00\ubcf5\uc758 \ud559 \ub450 \ub9c8\ub9ac\ub294 \ubb34\uc5c7\uc744 \uc54c\ub824\uc904\uae4c \uc30d\ud559\ubb34\ub2ac \ud749\ubc30\ub97c \uac00\uae4c\uc774\uc5d0\uc11c \ubcf4\ub294 \uc7ac\ubbf8 \uc637 \uc704\uc758 \uc791\uc740 \uadf8\ub9bc\uc5d0\ub294 \uc785\ub294 \uc0ac\ub78c\uc758 \uc9c0\uc704\uc640 \uc790\uc218\uc758 \uc19c\uc528\uac00 \ud568\uaed8 \ub2f4\uacbc\uc2b5\ub2c8\ub2e4. Clothing \uc0dd\ud65c \uc61b \uad00\ubcf5\uc744 \ubcf4\uba74 \uac00\uc2b4\uaed8\uc758 \uc0ac\uac01\ud615 \uadf8\ub9bc\uc774 \uba3c\uc800 \ub208\uc5d0 \ub74c \ub54c\uac00 \uc788\ub2e4. \ub113\uc740 \uc637 \ud55c\uac00\uc6b4\ub370\uc5d0\uc11c \ub3d9\ubb3c\uc774 \ub0a0\uac70\ub098 \uad6c\ub984 \uc0ac\uc774\ub97c \uc6c0\uc9c1\uc778\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \u300c\uc30d\ud559\ubb34\ub2ac \ud749\ubc30\u300d\uc5d0\ub294 \ub450 \ub9c8\ub9ac \ud559\uc774 \uc704\uc544\ub798\ub85c \ub9c8\uc8fc \ubcf4\uace0 \uc788\ub2e4. \uac00\uae4c\uc774 \ubcf4\uba74 \ud770 \ubab8\uacfc \ub0a0\uac1c\ub3c4 \ubb3c\uac10\uc774 \uc544\ub2c8\ub77c \uc2e4\ub85c \ub9cc\ub4e4\uc5b4\uc838 \uc788\ub2e4. \uc608\uc05c \uadf8\ub9bc\uc744 \uc637\uc5d0 \ubd99\uc778 \uac83\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc, \uc774 \ubb3c\uac74\uc5d0\ub294 \ucc29\uc6a9\uc790\uc758 \uc9c0\uc704\ub97c \ub098\ud0c0\ub0b4\ub294 \uc5ed\ud560\ub3c4 \uc788\uc5c8\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc774 \ud749\ubc30\ub97c \ubb38\uad00 \ub2f9\uc0c1\uad00\uc774 \ucc29\uc6a9\ud55c \uac83\uc73c\ub85c \uc124\uba85\ud55c\ub2e4. \ub2f9\uc0c1\uad00\uc740 \uad00\ub8cc\uc758 \ub192\uc740 \uc9c0\uc704\uc5d0 \uc18d\ud558\ub294 \uad6c\ubd84\uc774\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc138\uc138\ud55c \ud488\uacc4\ud45c\ubcf4\ub2e4, \uc637\uc758 \ubb38\uc591\uc774 \uc544\ubb34\ub807\uac8c\ub098 \uc815\ud574\uc9c0\uc9c0\ub294 \uc54a\uc558\ub2e4\ub294 \uc810\uc744 \uc54c\uc544\ub450\uba74 \ub41c\ub2e4. \ubc15\ubb3c\uad00\uc758 \uad81\uc911 \uc790\uc218 \uc804\uc2dc \uc124\uba85\uc5d0\uc11c\ub3c4 \uc2e0\ud558\ub4e4\uc5d0\uac8c \uad00\uc9c1\uacfc \ub4f1\uae09\uc5d0 \ub530\ub77c \uc218\uc2e4\uacfc \ubb38\uc591\uc744 \ub2ec\ub9ac\ud55c \ud749\ubc30\ub97c \ub0b4\ub838\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \uc7a5\uc2dd\uacfc \uc0ac\ud68c\uc801\uc778 \uad6c\ubd84\uc774 \uac19\uc740 \ubb3c\uac74 \uc548\uc5d0 \uc788\uc5c8\ub2e4. \uadf8\ub807\ub2e4\uace0 \ub3d9\ubb3c\uc758 \uc218\ub9cc \uc678\uc6cc \ubaa8\ub4e0 \uc2dc\ub300\uc758 \uad00\ubcf5\uc744 \ub9de\ud788\ub294 \uc2dc\ud5d8\uc744 \ubcfc \ud544\uc694\ub294 \uc5c6\ub2e4. \uc9c0\uae08 \ubcf4\ub294 \ud55c \uc810\uc758 \uc124\uba85\ubd80\ud130 \uc77d\uc73c\uba74 \ucda9\ubd84\ud558\ub2e4. \uc774 \ud749\ubc30\uc5d0\ub294 \ud559 \ub450 \ub9c8\ub9ac\uc640 \ubd88\ub85c\ucd08\ub97c \ubb38 \ubaa8\uc2b5\uc774 \uc218\ub193\uc5ec \uc788\ub2e4. \uc0ac\uc9c4\uc744 \ud655\ub300\ud558\uba74 \ud770 \ub0a0\uac1c\ub97c \ucc44\uc6b4 \uc2e4\uc758 \uacb0\uc744 \ubcfc \uc218 \uc788\ub2e4. \uad6c\ub984 \uac00\uc7a5\uc790\ub9ac\uc5d0\ub294 \ub610 \ub2e4\ub978 \ube5b\uae54\uacfc \uc9c8\uac10\uc774 \uc774\uc5b4\uc9c4\ub2e4. \uba40\ub9ac\uc11c\ub294 \ud558\ub098\uc758 \uadf8\ub9bc\uc774\uc9c0\ub9cc \uac00\uae4c\uc774\uc5d0\uc11c\ub294 \uc791\uc740 \uc2e4\uc758 \uc6c0\uc9c1\uc784\uc73c\ub85c \ub098\ub25c\ub2e4. \uad81\uc911 \uc790\uc218\ub294 \uc804\ubb38 \ud654\uc6d0\uc774 \ubc11\uadf8\ub9bc\uc744 \uadf8\ub9ac\uace0 \uc218\ubc29\uc758 \uc0ac\ub78c\ub4e4\uc774 \uc774\ub97c \uc62e\uaca8 \uc218\ub193\ub294 \ubc29\uc2dd\uc73c\ub85c \uc81c\uc791\ub418\uc5c8\ub2e4\uace0 \ubc15\ubb3c\uad00\uc740 \uc124\uba85\ud55c\ub2e4. \uadf8\ub9ac\ub294 \uc77c\uacfc \ubc14\ub290\uc9c8\ud558\ub294 \uc77c\uc774 \ud55c \ubb3c\uac74\uc5d0\uc11c \ub9cc\ub09c\ub2e4. \uc774 \uacfc\uc815\uc5d0\uc11c \ud3c9\uba74\uc758 \uadf8\ub9bc\uc740 \uc637\uac10 \uc704\uc758 \uc9c8\uac10\uc744 \uc5bb\ub294\ub2e4. \ube5b\uc744 \ubc1b\ub294 \ubc29\ud5a5\uc5d0 \ub530\ub77c \uc2e4\uc758 \ud45c\uba74\uc774 \ub2ec\ub77c \ubcf4\uc774\ub294 \uac83\ub3c4 \uc790\uc218 \uc0ac\uc9c4\uc744 \ubcf4\ub294 \uc990\uac70\uc6c0\uc774\ub2e4. \ub3d9\ubb3c\uc774 \ubb34\uc5c7\uc778\uc9c0 \uc54c\uc544\ubcf8 \ub4a4\uc5d0\ub294 \uc5b4\ub5bb\uac8c \ub9cc\ub4e4\uc5b4\uc84c\ub294\uc9c0\ub3c4 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uc637\uc758 \ubb34\ub2ac\ub294 \uac00\uae4c\uc774\uc5d0\uc11c \uc544\ub984\ub2f5\uac8c \ubcfc \ub300\uc0c1\uc774\uba74\uc11c \ub2e4\ub978 \uc0ac\ub78c\uc774 \uc785\uc740 \uc0ac\ub78c\uc744 \uc54c\uc544\ubcf4\uac8c \ud558\ub294 \ud45c\uc9c0\uac00 \ub420 \uc218 \uc788\ub2e4. \ud749\ubc30\ub294 \uad00\ubcf5\uc774\ub77c\ub294 \uc81c\ub3c4 \uc548\uc5d0\uc11c \uadf8\ub7f0 \uc5ed\ud560\uc744 \ub9e1\ub294\ub2e4. \uac1c\uc778\uc758 \ucde8\ud5a5\ub300\ub85c \uace0\ub978 \ub3d9\ubb3c \uadf8\ub9bc\uacfc \uc9c0\uc704\uc5d0 \ub9de\ucdb0 \uc0ac\uc6a9\ud558\ub294 \ubb38\uc591\uc740 \uac19\uc740 \uc9c8\ubb38\uc73c\ub85c \uc124\uba85\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc7a5\uc2dd\uc774 \uc0ac\ud68c\uc801\uc778 \uc57d\uc18d\uacfc \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub2e4. \uadf8\ub798\uc11c \uc774 \uc720\ubb3c\uc758 \ud559 \ub450 \ub9c8\ub9ac\ub97c \uc548\ub2e4\uace0 \ubaa8\ub4e0 \uad00\ubcf5\uc758 \ud488\uacc4\ub97c \uc989\uc2dc \ud310\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc2dc\ub300\uc640 \uc885\ub958, \uad6c\uccb4\uc801\uc778 \uc81c\ub3c4\uac00 \ud568\uaed8 \ud544\uc694\ud558\ub2e4. \uc9c0\uae08\uc740 \ubc15\ubb3c\uad00\uc774 \uc774 \ud55c \uc810\uc744 \ubb38\uad00 \ub2f9\uc0c1\uad00\uc758 \ud749\ubc30\ub85c \uc18c\uac1c\ud55c\ub2e4\ub294 \uc124\uba85\uc744 \uae30\uc900\uc73c\ub85c \uc0bc\ub294\ub2e4. \ud55c \ubb3c\uac74\uc758 \uc774\ub984\uc744 \uc815\ud655\ud788 \uc77d\uc740 \ub4a4 \ub354 \ub113\uc740 \uad00\ubcf5\uc758 \uaddc\uce59\uc744 \ucc3e\uc544\uac00\ub294 \ud3b8\uc774 \uc774\ud574\ud558\uae30 \uc27d\ub2e4. \uad81\uc911 \uc790\uc218\uc758 \ubd84\uc5c5\uc5d0 \uad00\ud55c \ud574\uc124\uc744 \uc77d\uc73c\uba74 \uadf8\ub824 \ub193\uc740 \ud615\uc0c1\uc774 \uc5b4\ub5bb\uac8c \uc2e4\ub85c \uc62e\uaca8\uc84c\ub294\uc9c0 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \uc120\uacfc \uba74\uc744 \ucc9c \uc704\uc5d0 \ucc44\uc6b0\ub824\uba74 \uc0c9\uacfc \ubc29\ud5a5, \uc7ac\ub8cc\uc758 \uacb0\uc744 \ub2e4\ub8e8\uc5b4\uc57c \ud55c\ub2e4. \uadf8\ub9bc\uc744 \uadf8\ub300\ub85c \ubcf5\uc0ac\ud558\ub294 \uc77c\ucc98\ub7fc \ubcf4\uc5ec\ub3c4 \uc190\uc758 \uae30\uc220\uc774 \ub9cc\ub4dc\ub294 \ud45c\uba74\uc740 \ub2e4\ub978 \ub9e4\uccb4\uc758 \uacb0\uacfc\ub2e4. \uac19\uc740 \ud559\uc774 \ud3c9\ud3c9\ud55c \uc120\uacfc \uc785\uccb4\uc801\uc778 \uc2e4 \uc0ac\uc774\ub97c \uac74\ub108\uac04\ub2e4. \ub2e4\ub9cc \uc77c\ubc18\uc801\uc778 \uad81\uc911 \uc790\uc218\uc758 \uc81c\uc791 \uc124\uba85\uc774 \uc774 \ud55c \uc810\uc758 \uc81c\uc791\uc790 \uc774\ub984\uc744 \ubaa8\ub450 \ubc1d\ud600 \uc8fc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub204\uac00 \ubc11\uadf8\ub9bc\uc744 \uadf8\ub9ac\uace0 \ub204\uac00 \uc218\ub193\uc558\ub294\uc9c0\uc5d0 \uad00\ud55c \uac1c\ubcc4 \uc774\ub825\uc740 \ubcc4\ub3c4 \uc790\ub8cc\uac00 \ud544\uc694\ud558\ub2e4. \uc791\uc5c5\uc744 \ub098\ub204\ub294 \uc81c\ub3c4\uc758 \ubc30\uacbd\uacfc \ub208\uc55e\uc758 \uad6c\uccb4\uc801\uc778 \uc720\ubb3c\uc744 \uc5f0\uacb0\ud558\ub418, \ud655\uc778\ub418\uc9c0 \uc54a\uc740 \uc7a5\uc778\uc758 \uc774\uc57c\uae30\ub97c \ub367\ubd99\uc774\uc9c0 \uc54a\ub294 \uac83\uc774 \uc815\ud655\ud558\ub2e4. \ud559\uc774\ub77c\ub294 \ub3d9\ubb3c\uc744 \uc54c\uc544\ubcf8 \ub4a4\uc5d0\ub294 \ub0a0\uac1c\uc640 \ubab8\uc744 \uc774\ub8e8\ub294 \uc2e4\uc758 \uacb0\uc744 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uba40\ub9ac\uc11c \ud558\ub098\ub85c \ubcf4\uc774\ub294 \ud770 \ubd80\ubd84\ub3c4 \uac00\uae4c\uc774\uc5d0\uc11c\ub294 \ucd18\ucd18\ud788 \ub193\uc778 \uc791\uc740 \uc120\ub4e4\uc774\ub2e4. \uac19\uc740 \uc0c9\ucc98\ub7fc \ubcf4\uc5ec\ub3c4 \ube5b\uc744 \ubc1b\ub294 \ubc29\ud5a5\uacfc \uc9c8\uac10\uc5d0 \ub530\ub77c \uc778\uc0c1\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc790\uc218\ub294 \uc0c9\uc744 \uce60\ud55c \uadf8\ub9bc\uacfc \ub2e4\ub978 \ud45c\uba74\uc744 \uac00\uc9c4\ub2e4. \uc0ac\uc9c4\uc744 \ubcfc \ub54c\uc5d0\ub294 \ubb34\ub2ac\uc758 \uc774\ub984\uc744 \ube68\ub9ac \ub9de\ud788\ub294 \ub300\uc2e0 \ud070 \uba74\uc5d0\uc11c \uc791\uc740 \uc2e4\ub85c \uc2dc\uc120\uc744 \uc62e\uaca8 \ubcf4\uc790. \ub2e4\ub9cc \ud654\uba74\uc758 \uc870\uba85\uacfc \ud655\ub300 \uc815\ub3c4\uc5d0 \ub530\ub77c \ubcf4\uc774\ub294 \uacb0\uc740 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc9c1\uc811 \uad00\ucc30\ud55c \uc138\ubd80\uc640 \ubc15\ubb3c\uad00\uc774 \uc124\uba85\ud558\ub294 \ubb38\uc591\uc744 \ud568\uaed8 \uc77d\uc73c\uba74 \ub41c\ub2e4. \uc544\ub984\ub2e4\uc6b4 \uc0c1\uc9d5\uc774\ub77c\ub294 \ub9d0 \ub4a4\uc5d0 \uc218\ub9ce\uc740 \ubc14\ub298\ub540\uc774 \uc788\uc5c8\ub2e4\ub294 \uc810\uc774 \uad6c\uccb4\uc801\uc73c\ub85c \ub290\uaef4\uc9c4\ub2e4. \uad00\ubcf5\uc5d0 \ubd99\uc5b4 \uc788\uc744 \ub54c\uc758 \ud749\ubc30\ub294 \uc785\uc740 \uc0ac\ub78c\uc758 \uc6c0\uc9c1\uc784\uacfc \uac70\ub9ac \uc18d\uc5d0\uc11c \ubcf4\uc600\uc744 \uac83\uc774\ub2e4. \uc804\uc2dc\uc7a5\uc774\ub098 \uc0ac\uc9c4\uc5d0\uc11c\ub294 \uadf8 \ubd80\ubd84\ub9cc \ub530\ub85c \uc624\ub798 \ubcfc \uc218 \uc788\ub2e4. \uc6d0\ub798 \ubab8\uc5d0 \ubd99\uc778 \ud45c\uc9c0\uc640 \uc624\ub298 \ub208\uc55e\uc758 \uacf5\uc608\ud488\uc774\ub77c\ub294 \ub450 \ubaa8\uc2b5\uc774 \uacb9\uce5c\ub2e4. \uc5b4\ub290 \ud558\ub098\ub97c \uc9c0\uc6b0\uc9c0 \uc54a\uc73c\uba74 \uc0ac\ud68c\uc801 \uc5ed\ud560\uacfc \uc81c\uc791\uc758 \uc544\ub984\ub2e4\uc6c0\uc744 \ud568\uaed8 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \ub450 \ud559\uc774 \ub9c8\uc8fc \ubcf4\uace0 \ubd88\ub85c\ucd08\ub97c \ubb38 \uad6c\uc131\uc744 \ub2e4\uc2dc \ubcf4\uc790. \ubb34\uc5c7\uc744 \uadf8\ub838\ub294\uc9c0\uc640 \uc5b4\ub5bb\uac8c \uc218\ub193\uc558\ub294\uc9c0\uac00 \ud55c \ubb3c\uac74 \uc548\uc5d0 \uc788\ub2e4. \uc5b4\ub824\uc6b4 \uad00\uc9c1\ud45c\ub97c \ubaa8\ub450 \uc678\uc6b0\uc9c0 \uc54a\uc544\ub3c4, \uc0ac\ub78c\uc744 \uad6c\ubd84\ud558\ub294 \ud45c\uc9c0\uac00 \uc774\ub807\uac8c \ub9ce\uc740 \uc190\uc77c\uacfc \uc0c1\uc9d5\uc744 \ud488\uc744 \uc218 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub0a8\ub294\ub2e4. \uc637\uac10 \ud55c \uc870\uac01\uc5d0\uc11c \uc81c\ub3c4\uc640 \uacf5\uc608\uac00 \ub9cc\ub09c\ub2e4. \ubcf5\uc2dd \uc804\uc2dc\uc5d0\ub294 \ub0af\uc120 \uc637 \uc774\ub984\uacfc \uae34 \uc124\uba85\uc774 \ubd99\uc5b4 \uc788\uae30 \uc27d\ub2e4. \ucc98\uc74c\ubd80\ud130 \ubaa8\ub450 \uc678\uc6b0\ub824 \ud558\uba74 \uad00\ub78c\uc774 \uacf5\ubd80\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \uadf8\ub7f4 \ub54c\ub294 \ub9c8\uc74c\uc5d0 \ub4dc\ub294 \ubb38\uc591 \ud558\ub098\ubd80\ud130 \ucc3e\uc544\ubcf4\uc544\ub3c4 \uc88b\ub2e4. \ud559\uc758 \ub0a0\uac1c\uac00 \uc5b4\ub514\uae4c\uc9c0 \ud3bc\uccd0\uc838 \uc788\ub294\uc9c0, \uad6c\ub984\uc740 \uc5b4\ub5a4 \uc0c9\uc778\uc9c0, \uac19\uc740 \ud770 \ubd80\ubd84\ub3c4 \uc2e4\uc758 \ubc29\ud5a5\uc774 \ub2e4\ub978\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uc54c\uace0 \uc788\ub294 \ub3d9\ubb3c\uc774 \ub0af\uc120 \uc637\uc744 \ubcf4\ub294 \uc785\uad6c\uac00 \ub41c\ub2e4. \uadf8\ub2e4\uc74c \uc124\uba85\uc5d0\uc11c \ub204\uac00 \uc785\ub358 \uac83\uc778\uc9c0 \ud655\uc778\ud558\uba74 \uc791\uc740 \uadf8\ub9bc\uc758 \ub450 \uc5ed\ud560\uc774 \ud568\uaed8 \ubcf4\uc778\ub2e4. \ud55c \uc0ac\ub78c\uc758 \uc790\ub9ac\ub97c \uc54c\ub824\uc8fc\ub294 \ud45c\uc2dc\uc774\uba74\uc11c, \uc5ec\ub7ec \uc0ac\ub78c\uc758 \uc190\uc774 \uc9c0\ub098\uac04 \uc12c\uc138\ud55c \uacf5\uc608\ud488\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \uad00\ubcf5 \uc18d \ub3d9\ubb3c\uc744 \ub9cc\ub098\uba74 \uc774\ub984\ub9cc \ub9de\ud788\uace0 \uc9c0\ub098\uce58\uc9c0 \uc54a\uc544\ub3c4 \uc88b\uaca0\ub2e4. \uc2e4 \ud55c \uac00\ub2e5\uc529 \uac00\uae4c\uc774 \ubcf4\ub294 \ub370\uc5d0\ub3c4 \uc0dd\uac01\ubcf4\ub2e4 \uae34 \uad6c\uacbd\uac70\ub9ac\uac00 \uc228\uc5b4 \uc788\ub2e4."}, {"id": "dasik-sweets-frame", "title": "\uacfc\uc790\ub97c \ub192\uc774 \uc313\ub294 \ub370\uc5d0\ub3c4 \ud2c0\uc774 \ud544\uc694\ud588\ub2e4", "summary": "\uc704\uc544\ub798\uac00 \ub6ab\ub9b0 \uae08\uc18d \ud2c0\uc5d0\uc11c \uc81c\uc0ac\uc0c1 \uc74c\uc2dd\uc758 \ubaa8\uc591\uc744 \uc7a1\ub358 \ubc29\ubc95\uc744 \ubd05\ub2c8\ub2e4.", "category": "life", "category_title": "Life", "subcategory": "Food", "url": "stories/dasik-sweets-frame/index.html", "image": "media/dasik-sweets-frame.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc720\uc81c \ub2e4\uc2dd\uc6b0\ub9ac \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uacfc\uc790\ub97c \ub192\uc774 \uc313\ub294 \ub370\uc5d0\ub3c4 \ud2c0\uc774 \ud544\uc694\ud588\ub2e4 \uc774\ub984\uc740 \ub0af\uc124\uc9c0\ub9cc \uc4f0\uc784\uc740 \uc120\uba85\ud55c \ub2e4\uc2dd\uc6b0\ub9ac \uc704\uc544\ub798\uac00 \ub6ab\ub9b0 \uae08\uc18d \ud2c0\uc5d0\uc11c \uc81c\uc0ac\uc0c1 \uc74c\uc2dd\uc758 \ubaa8\uc591\uc744 \uc7a1\ub358 \ubc29\ubc95\uc744 \ubd05\ub2c8\ub2e4. Food \uc0dd\ud65c \uc791\uc740 \uc6d0\ud1b5 \ud558\ub098\uac00 \ub193\uc5ec \uc788\ub2e4. \uc606\uc740 \uae30\ub465 \uc0ac\uc774\ub85c \ud6e4\ud788 \ubcf4\uc774\uace0 \uc704\uc640 \uc544\ub798\ub3c4 \ub6ab\ub824 \uc788\ub2e4. \ubb3c\uc744 \ub2f4\ub294 \uadf8\ub987 \uac19\uc9c0\ub294 \uc54a\ub2e4. \ubb34\uc5c7\uc5d0 \uc37c\uc744\uae4c \uad81\uae08\ud574\uc9c0\ub294 \uc21c\uac04, \uc774\ub984\uc744 \uc77d\ub294\ub2e4. \ub2e4\uc2dd\uc6b0\ub9ac\ub2e4. \uc6b0\ub9ac\ub77c\ub294 \ub9d0 \ub54c\ubb38\uc5d0 \ubb34\uc5c7\uc744 \uac00\ub450\ub294 \uc791\uc740 \uc6b8\ud0c0\ub9ac\ub97c \ub5a0\uc62c\ub838\ub2e4\uba74 \uc4f0\uc784\uc5d0 \uc870\uae08 \uac00\uae4c\uc774 \uac04 \uc148\uc774\ub2e4. \ub2e4\ub9cc \uc774 \uc548\uc5d0\uc11c \uc790\ub9ac\ub97c \uc7a1\ub294 \uac83\uc740 \ub3d9\ubb3c\uc774 \uc544\ub2c8\ub77c \uc74c\uc2dd\uc774\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc740 \uc6b0\ub9ac\ub97c \uc81c\uc0ac\uc5d0 \uc4f0\ub294 \uadf8\ub987\uc758 \ud55c \uc885\ub958\ub85c \uc124\uba85\ud55c\ub2e4. \uc0b0\uc790\uc640 \ub2e4\uc2dd, \uc57d\uacfc \uac19\uc740 \uc74c\uc2dd\uc744 \ub192\uc774 \uc313\uc744 \ub54c \uace0\uc815\ud558\ub294 \ub370 \uc0ac\uc6a9\ud588\ub2e4\ub294 \uac83\uc774\ub2e4. \ub2e4\uc2dd\uc6b0\ub9ac\ub294 \uadf8\uc911 \ub2e4\uc2dd\uc744 \uace0\uc815\ud558\ub294 \ubb3c\uac74\uc774\ub2e4. \uc2dd\ud0c1 \uc704\uc5d0 \uacfc\uc790\ub97c \ub192\uc774 \ud3ec\uac1c\uc5b4 \ubcf8\ub2e4\uba74 \ub9e8 \uc544\ub798 \uac83\ub9cc \uc798 \ub193\ub294\ub2e4\uace0 \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc0dd\uac01\uc774 \ub4e0\ub2e4. \uc774 \ubb3c\uac74\uc740 \uc313\uc740 \ud615\ud0dc\ub97c \ubd99\ub4e4\uc5b4 \uc8fc\ub294 \ud2c0\uc774\ub77c\ub294 \uc4f0\uc784\uc744 \uac16\ub294\ub2e4. \uc74c\uc2dd \uc790\uccb4\ubfd0 \uc544\ub2c8\ub77c \uc74c\uc2dd\uc744 \uc5b4\ub5a4 \ubaa8\uc2b5\uc73c\ub85c \uc62c\ub9b4\uc9c0\ub3c4 \uc900\ube44\ud55c \uc148\uc774\ub2e4. \uc774 \uc18c\uc7a5\ud488\uc740 \uc704\uc544\ub798\uac00 \ub6ab\ub9b0 \uc6d0\ud1b5\ud615\uc774\uba70 \uc606\uba74\uc740 \uc5ec\ub35f \uae30\ub465\uc73c\ub85c \uc774\ub8e8\uc5b4\uc838 \uc788\ub2e4. \uae30\ub465\uc5d0\ub294 \ubd80\ucc44 \uac19\uc740 \ud615\ud0dc\uc758 \uc7a5\uc2dd\ub3c4 \uc788\ub2e4. \ubcf4\uae30\uc5d0\ub294 \uac00\ubcbc\uc6b4 \uc6b8\ud0c0\ub9ac \uac19\uc9c0\ub9cc \ub458\ub808\ub97c \uc7a1\uc544 \uc8fc\ub294 \ubaa8\uc591\uc774\ub2e4. \ubcc4\ub3c4\uc758 \ub2e4\uc2dd\uc6b0\ub9ac\ub300\uc640 \ud55c \uc9dd\uc744 \uc774\ub8e8\uc5b4 \ubc1b\uce68 \uc704\uc5d0 \uace0\uc815\ud588\ub2e4\uace0 \ud55c\ub2e4. \uad6c\uba4d \ub09c \uc6d0\ud1b5 \ud558\ub098\uac00 \ud63c\uc790 \ubc14\ub2e5\uc5d0 \ub193\uc774\ub294 \uac83\ub9cc \uc0dd\uac01\ud558\uba74 \uc4f0\uc784\uc744 \ub193\uce58\uae30 \uc27d\ub2e4. \ud568\uaed8 \uc0ac\uc6a9\ud558\ub294 \ubc1b\uce68\uae4c\uc9c0 \ub5a0\uc62c\ub824\uc57c \uad6c\uc870\uac00 \uc774\uc5b4\uc9c4\ub2e4. \uc74c\uc2dd\uc740 \uba39\uc744 \uc7ac\ub8cc\ub85c \uc900\ube44\ub418\uc9c0\ub9cc \uc758\ub840\uc5d0\uc11c\ub294 \ub193\ub294 \ud615\ud0dc\ub3c4 \uc911\uc694\ud574\uc9c8 \uc218 \uc788\ub2e4. \ub192\uc774 \uc313\uc740 \uacfc\uc790\ub97c \uc77c\uc815\ud55c \ubaa8\uc2b5\uc73c\ub85c \uc720\uc9c0\ud558\ub824\uba74 \uc8fc\ubcc0\uc744 \uc7a1\uc544 \uc8fc\ub294 \ub3c4\uad6c\uac00 \ud544\uc694\ud558\ub2e4. \ub2e4\uc2dd\uc6b0\ub9ac\ub294 \uadf8\ub7f0 \uc77c\uc5d0 \uc4f0\uc778\ub2e4\uace0 \uc124\uba85\ub41c\ub2e4. \uc870\ub9ac\ud558\ub294 \uae30\uc220\uacfc \ucc28\ub9ac\ub294 \uae30\uc220\uc774 \ubaa8\ub450 \uc74c\uc2dd\uc758 \uc5ed\uc0ac \uc548\uc5d0 \uc788\uc5c8\ub358 \uc148\uc774\ub2e4. \uc774\uac83\uc744 \uc624\ub298\uc758 \uc811\uc2dc\uc5d0 \uacfc\uc790\ub97c \uc313\ub294 \ub180\uc774\uc640 \uc644\uc804\ud788 \uac19\uc740 \ud48d\uc2b5\uc774\ub77c\uace0 \ub193\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc81c\uc0ac\uc5d0 \uc4f0\ub294 \ub3c4\uad6c\ub77c\ub294 \ub9e5\ub77d\uc774 \ub530\ub85c \uc788\ub2e4. \ud604\ub300\uc758 \ube44\uc720\ub294 \uc9c0\uc9c0\ud558\ub294 \ud2c0\uc774 \uc65c \ud544\uc694\ud55c\uc9c0 \uc774\ud574\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub420 \ubfd0\uc774\ub2e4. \uc2e4\uc81c \uc5b4\ub5a4 \uc758\ub840\uc5d0\uc11c \uc5bc\ub9c8\ub098 \uc313\uc558\ub294\uc9c0\uc640 \uadf8\ub0a0\uc758 \ubc30\uce58\ub294 \ud574\ub2f9 \uae30\ub85d\uc774 \ub354 \ud544\uc694\ud55c \ubb38\uc81c\ub85c \ub0a8\uaca8 \ub454\ub2e4. \uc704\uc544\ub798\uac00 \ub6ab\ub9ac\uace0 \uc606\uba74\uc774 \uae30\ub465\uc73c\ub85c \ub41c \ubaa8\uc2b5\uc740 \uc74c\uc2dd\uc744 \uc804\ubd80 \ub2f4\ub294 \uae4a\uc740 \uadf8\ub987\uacfc \ub2e4\ub974\ub2e4. \ud2c0\uc758 \ub458\ub808\uac00 \ud615\ud0dc\ub97c \uc7a1\uc544 \uc8fc\uace0 \uc548\ucabd\uc5d0\ub294 \uc313\uc744 \uc790\ub9ac\uac00 \uc0dd\uae34\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \ube44\uc5b4 \ubcf4\uc774\ub294 \ubd80\ubd84\uc744 \ube60\uc9c4 \uc870\uac01\uc774\ub77c\uace0 \uba3c\uc800 \uc0dd\uac01\ud558\uc9c0 \ub9d0\uace0, \uc560\ucd08\uc5d0 \uadf8\ub7f0 \uad6c\uc870\ub85c \ub9cc\ub4e0 \ubb3c\uac74\uc778\uc9c0 \ud574\uc124\uacfc \ud568\uaed8 \ud655\uc778\ud560 \uc218 \uc788\ub2e4. \uc5ec\ub35f \uae30\ub465\uc774\ub77c\ub294 \uc124\uba85\uc740 \uc606\uba74\uc758 \ubc18\ubcf5\uc744 \uc77d\uac8c \ud55c\ub2e4. \uae30\ub465\uacfc \uae30\ub465 \uc0ac\uc774\uc5d0 \uac04\uaca9\uc774 \uc788\uace0 \uc0c1\ubd80\uc640 \uc544\ub798\ucabd\uc774 \uadf8 \uad00\uacc4\ub97c \ubb36\ub294\ub2e4. \uc815\ud655\ud55c \uc81c\uc791 \uce58\uc218\ub97c \ubab0\ub77c\ub3c4 \uc804\uccb4\uc640 \ubd80\ubd84\uc774 \uc5b4\ub5bb\uac8c \uc774\uc5b4\uc9c0\ub294\uc9c0 \ubcfc \uc218 \uc788\ub2e4. \ubb3c\uac74\uc744 \ubc1b\uce58\ub294 \uc120\uacfc \ube44\uc5b4 \uc788\ub294 \uacf5\uac04\uc774 \ud568\uaed8 \uae30\ub2a5\uc744 \ub9cc\ub4e0\ub2e4\ub294 \uc810\uc5d0\uc11c \uac74\ucd95\uc758 \uc791\uc740 \uad6c\uc870\ub97c \ubcf4\ub294 \ub4ef\ud55c \uc7ac\ubbf8\ub3c4 \uc788\ub2e4. \ubcc4\ub3c4\uc758 \uc6b0\ub9ac\ub300\uc640 \uc9dd\uc744 \uc774\ub8ec\ub2e4\ub294 \uc815\ubcf4\ub294 \uc0ac\uc9c4 \uc18d \ud55c \uc810\ub9cc\uc73c\ub85c \uc0c1\uc758 \ubaa8\uc2b5\uc744 \ub05d\ub0b4\uc9c0 \uc54a\uac8c \ud55c\ub2e4. \uace0\uc815\ud560 \ud2c0\uacfc \uadf8\uac83\uc744 \ub193\ub294 \ubc14\ud0d5\uc774 \ud568\uaed8 \ud544\uc694\ud588\ub2e4. \ubc15\ubb3c\uad00\uc5d0\uc11c \ub3c4\uad6c\ub97c \ub530\ub85c \ubd84\ub958\ud574 \uc18c\uac1c\ud558\ub354\ub77c\ub3c4 \uc2e4\uc81c\ub85c\ub294 \uc5ec\ub7ec \ubd80\ud488\uc774 \uad00\uacc4\ub97c \ub9fa\uc73c\uba70 \uc0ac\uc6a9\ub420 \uc218 \uc788\ub2e4. \uc18c\uc7a5\ud488\uc758 \ub2e8\uc704\uc640 \uc0ac\uc6a9\uc758 \ub2e8\uc704\uac00 \ud56d\uc0c1 \uac19\uc9c0\ub294 \uc54a\ub2e4. \uc774\uac83\uc744 \uc54c\uace0 \ubcf4\uba74 \uc804\uc2dc \uc124\uba85\uc5d0\uc11c \ud55c \uc870\ub098 \uc9dd\uc774\ub77c\ub294 \ub9d0\ub3c4 \ub354 \uad6c\uccb4\uc801\uc73c\ub85c \uc77d\ud78c\ub2e4. \ub2e8\uc21c\ud788 \uac19\uc740 \ubaa8\uc591 \ub450 \uac1c\ub77c\ub294 \ub73b\ub9cc\uc740 \uc544\ub2d0 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \ub2e4\ub9cc \uc774 \uc790\ub8cc\ub85c \uc804\uccb4 \uc81c\uae30\uc758 \uc218\uc640 \uc815\ud655\ud55c \ubc30\uce58\ub97c \uc0c8\ub85c \ud655\uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud655\uc778\ub41c \ubc1b\uce68\uacfc \ud2c0\uc758 \uc5f0\uacb0\ubd80\ud130 \ub530\ub77c\uac00\uba74 \ucda9\ubd84\ud558\ub2e4. \ud55c \ubb3c\uac74\uc744 \uc124\uba85\ud558\ub294 \ub370 \uc606\uc758 \ubb3c\uac74\uc774 \ud544\uc694\ud55c \uacbd\uc6b0\ub2e4. \uc0c1\ubd80\uc5d0 \uc74c\uac01\ud55c \u8336\u98df\uc740 \uc774 \ub3c4\uad6c\uc758 \uc774\ub984\uacfc \uc5f0\uacb0\ub418\ub294 \ud45c\uc9c0\ub2e4. \ubaa8\uc591\ub9cc \ubcf4\uc558\uc744 \ub54c\ub294 \ubb34\uc5c7\uc744 \uace0\uc815\ud558\ub294\uc9c0 \uc54c\uae30 \uc5b4\ub824\uc6cc\ub3c4 \uae00\uc790\uac00 \uc6a9\ub3c4\ub97c \ucc3e\ub294 \ub2e8\uc11c\uac00 \ub41c\ub2e4. \uc5ec\uae30\uc11c \ubb38\uc790\ub294 \uac10\uc0c1\ud560 \uc7a5\uc2dd\uc774\uba74\uc11c \uc2e4\uc81c \uc77c\uc744 \uad6c\ubd84\ud558\ub294 \uc815\ubcf4\uac00 \ub420 \uc218 \uc788\ub2e4. \uc74c\uc2dd\uc758 \uc885\ub958\uc5d0 \ub9de\ucd98 \ub3c4\uad6c\ub97c \uc54c\uc544\ubcf4\uac8c \ud558\ub294 \uc5ed\ud560\uc774\ub2e4. \uc774\ub984\uc744 \uc548 \ub4a4\uc5d0\ub294 \uacfc\uc790 \uc790\uccb4\ubcf4\ub2e4 \uadf8\uac83\uc744 \ucc28\ub9ac\ub358 \uc0ac\ub78c\uc758 \uc900\ube44\ub97c \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \uc644\uc131\ud55c \uc0c1\uc740 \ud55c \uc7a5\uba74\uc774\uc9c0\ub9cc \uadf8 \ub4a4\uc5d0\ub294 \ub3c4\uad6c\ub97c \uad6c\ubd84\ud558\uace0 \ub9de\ucd94\uba70 \ub192\uc774\ub97c \uc720\uc9c0\ud558\ub294 \uc190\uc77c\uc774 \uc788\uc5c8\ub2e4. \uc791\uc740 \uc6d0\ud1b5\ud615 \ubb3c\uac74\uc740 \uadf8 \uc2dc\uac04\uc744 \ub0a8\uacbc\ub2e4. \uba39\uc744\uac70\ub9ac\uc758 \uc5ed\uc0ac\ub97c \ub9db\uacfc \uc7ac\ub8cc\uc5d0\uc11c \ucc28\ub9ac\ub294 \ud615\uc2dd\uae4c\uc9c0 \ub113\ud600 \ubcf4\ub294 \uc785\uad6c\ub2e4. \uc6d0\ud1b5 \uc704\ucabd \ubc14\uae65\uc5d0\ub294 \ub2e4\uc2dd\uc744 \ub73b\ud558\ub294 \u8336\u98df \ub450 \uae00\uc790\ub97c \uc0c8\uacbc\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc6a9\ub3c4\ub97c \uad6c\ubcc4\ud558\uae30 \uc704\ud55c \ud45c\uc2dc\ub77c\uace0 \uc124\uba85\ud55c\ub2e4. \ube44\uc2b7\ud55c \ubb3c\uac74\uc774 \uc788\uc5b4\ub3c4 \ubb34\uc5c7\uc744 \ub9e1\ub294\uc9c0 \uae00\uc790\ub85c \uc54c\ub824 \uc8fc\ub294 \uac83\uc774\ub2e4. \ub0af\uc120 \uc81c\uae30 \uc774\ub984\uc744 \uc5ec\ub7ec \uac1c \uc678\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \uc88b\ub2e4. \uc624\ub298\uc740 \uacfc\uc790\ub97c \ub192\uc774 \uc313\ub294 \uc77c\uc5d0\ub3c4 \ud2c0\uacfc \ubc1b\uce68, \uc6a9\ub3c4\ub97c \uc801\uc740 \uae00\uc528\uac00 \uc788\uc5c8\ub2e4\ub294 \uc810\uc744 \uae30\uc5b5\ud574 \ubcf4\uc790. \uadf8\ub987\ucc98\ub7fc \ubcf4\uc774\uc9c0 \uc54a\ub358 \uc6d0\ud1b5\uc774 \uc81c\uc0ac\uc0c1 \uc74c\uc2dd\uc758 \ubaa8\uc591\uc744 \ub9cc\ub4dc\ub294 \ub3c4\uad6c\ub85c \ubc14\ub00c\uc5b4 \ubcf4\uc778\ub2e4."}, {"id": "embroidered-spoon-pouch", "title": "\uc218\uc800\ub97c \ub123\ub294 \uc8fc\uba38\ub2c8\uc5d0 \ubc14\ub78c\uc744 \uc218\ub193\uc558\ub2e4", "summary": "\ubd89\uc740 \uc218\uc800\uc9d1\uc758 \uadf8\ub9bc\uacfc \uae00\uc528\ub97c \ub530\ub77c\uac00\uba70 \uc0dd\ud65c \uc18d \uc18c\ub9dd\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "life", "category_title": "Life", "subcategory": "Food", "url": "stories/embroidered-spoon-pouch/index.html", "image": "media/embroidered-spoon-pouch.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc790\uc218\uc218\uc800\uc9d1 \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc218\uc800\ub97c \ub123\ub294 \uc8fc\uba38\ub2c8\uc5d0 \ubc14\ub78c\uc744 \uc218\ub193\uc558\ub2e4 \ubc25\uc0c1 \uacc1\uc758 \uc791\uc740 \ubb3c\uac74\uc5d0 \ub2f4\uae34 \uae34 \ucd95\uc6d0 \ubd89\uc740 \uc218\uc800\uc9d1\uc758 \uadf8\ub9bc\uacfc \uae00\uc528\ub97c \ub530\ub77c\uac00\uba70 \uc0dd\ud65c \uc18d \uc18c\ub9dd\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Food \uc0dd\ud65c \uc0ac\uc9c4\uc744 \uc5bc\ud54f \ubcf4\uba74 \uae38\ucb49\ud55c \uc7a5\uc2dd\ud488 \uac19\ub2e4. \ubd89\uc740 \ubc14\ud0d5\uc5d0 \uaf43\uc774 \ud53c\uace0, \uc0c8\uac00 \uc11c \uc788\uace0, \uc5ec\ub7ec \uc0c9\uc758 \uc220\uc774 \uc544\ub798\ub85c \ub298\uc5b4\uc9c4\ub2e4. \uc774\ub984\uc744 \ubcf4\uace0 \ub098\uc11c\uc57c \uace0\uac1c\ub97c \ub044\ub355\uc778\ub2e4. \uc790\uc218\uc218\uc800\uc9d1\uc774\ub2e4. \uc21f\uac00\ub77d\uacfc \uc813\uac00\ub77d\uc744 \ub2f4\ub294 \ubb3c\uac74\uc778\ub370 \uc7a5\uc2dd\uc740 \uaf64 \ud48d\uc131\ud558\ub2e4. \ubb34\uc5c7\uc744 \ub2f4\ub294 \uc8fc\uba38\ub2c8\uc778\uc9c0\ub9cc \uc54c\uba74 \uc9c0\ub098\uce58\uae30 \uc27d\uc9c0\ub9cc, \ubb34\uc5c7\uc744 \uc218\ub193\uc558\ub294\uc9c0\uae4c\uc9c0 \ubcf4\uba74 \ub610 \ud558\ub098\uc758 \uc774\uc57c\uae30\uac00 \uc5f4\ub9b0\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc740 \uc55e\uba74 \uc544\ub798\ucabd\uc5d0 \ubc14\uc704\uc640 \uc601\uc9c0, \ud30c\ub3c4\uac00 \uc788\uace0 \uac00\uc6b4\ub370\uc5d0 \uc18c\ub098\ubb34\uc640 \ubaa8\ub780, \ud559 \ub450 \ub9c8\ub9ac \ub4f1\uc774 \uc218\ub193\uc600\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc5ec\ub7ec \uc0c9\uc758 \uc2e4\ub85c \uadf8\ub9b0 \ud48d\uacbd\uc774\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc774 \ubb38\uc591\ub4e4\uc774 \uc624\ub798 \uc0b4\uace0 \ubcf5\uc744 \ub204\ub9ac\uba70 \ud3c9\uc548\ud558\uae30\ub97c \ubc14\ub77c\ub294 \ub9c8\uc74c\uc744 \ud45c\ud604\ud55c\ub2e4\uace0 \ud480\uc774\ud55c\ub2e4. \ubaa8\ub974\ub294 \ubb38\uc591\uc758 \uc774\ub984\uc744 \uc804\ubd80 \uc678\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \uc88b\ub2e4. \uc2dd\uc0ac \ub3c4\uad6c\ub97c \ub123\ub294 \uc8fc\uba38\ub2c8\uac00 \uc88b\uc740 \uc0b6\uc5d0 \ub300\ud55c \ubc14\ub78c\uae4c\uc9c0 \ud488\uace0 \uc788\ub2e4\ub294 \uc810\uc774 \uc7ac\ubbf8\uc788\ub2e4. \uc774 \uc218\uc800\uc9d1\uc740 \uc55e\uba74\ub9cc \ubcf4\uace0 \ub05d\ub0bc \ubb3c\uac74\uc774 \uc544\ub2c8\ub2e4. \ub4b7\uba74\uc5d0\ub294 \uc911\uc559\uc120\uc744 \uc0ac\uc774\uc5d0 \ub450\uace0 \uae38\ud55c \ub73b\uc758 \uae00\uadc0\uac00 \uc218\ub193\uc5ec \uc788\ub2e4. \uc624\ub798 \uc0b4\uace0 \ud3c9\uc548\ud558\uae30\ub97c \ubc14\ub77c\ub294 \ud45c\ud604\uacfc \uc5ec\uc720\uc640 \ubd80\uadc0\ub97c \ubc14\ub77c\ub294 \ud45c\ud604\uc774\ub2e4. \ub208\uc73c\ub85c \ubcf4\ub294 \uadf8\ub9bc\uacfc \uc77d\ub294 \uae00\uc774 \ud55c \uc8fc\uba38\ub2c8\uc5d0 \ud568\uaed8 \ub193\uc600\ub2e4. \uc55e\uc758 \ud48d\uacbd\uc744 \ub4a4\uc758 \ubb38\uc7a5\uc774 \ub2e4\uc2dc \ud480\uc5b4 \uc8fc\ub294 \uac83\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \uc624\ub298\ub0a0 \uc120\ubb3c\uc5d0 \uc9e7\uc740 \ucd95\ud558 \uce74\ub4dc\ub97c \ub367\ubd99\uc774\ub294 \uc77c\uc744 \ube44\uad50\ud574 \ubcfc \uc218\ub3c4 \uc788\uaca0\ub2e4. \ubb3c\ub860 \uc774 \ubb3c\uac74\uc774 \uc2e4\uc81c \uc5b4\ub5a4 \uc120\ubb3c \uc790\ub9ac\uc5d0\uc11c \uc4f0\uc600\ub294\uc9c0\ub294 \ud655\uc778\ub41c \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub2e4. \uc218\uc800\ub97c \ub123\ub294 \uc8fc\uba38\ub2c8\ub294 \uc548\uc5d0 \ub4e4\uc5b4\uac08 \uae38\uace0 \uac00\ub294 \ubb3c\uac74\uc744 \uc608\uc0c1\ud55c\ub2e4. \uc7a5\uc2dd\uc758 \ud48d\uacbd\uc744 \ubcf4\uae30 \uc804\uc5d0 \ubb3c\uac74\uc758 \uc804\uccb4 \ube44\ub840\uc640 \uc5ec\ub2eb\ub294 \uc790\ub9ac\ub97c \uc0b4\ud3b4\ubcf4\uba74 \uc4f0\uc784\uacfc \uc5f0\uacb0\ub41c\ub2e4. \ub2e4\ub9cc \uc774 \uc18c\uc7a5\ud488\uc5d0 \uc5b4\ub5a4 \uc218\uc800 \ud55c \ubc8c\uc774 \uc2e4\uc81c \ub4e4\uc5b4 \uc788\uc5c8\ub294\uc9c0\ub098 \uc5b4\ub514\ub85c \ub4e4\uace0 \uac14\ub294\uc9c0\ub294 \ud655\uc778\ub41c \uc124\uba85\uc774 \ud544\uc694\ud558\ub2e4. \ubcf4\uad00 \uae30\ub2a5\uacfc \uad6c\uccb4\uc801\uc778 \uc0ac\uc6a9 \uc7a5\uba74\uc740 \uad6c\ubd84\ud560 \uc218 \uc788\ub2e4. \uc624\ub298\uc758 \uc548\uacbd\uc9d1\uc774\ub098 \ud544\ud1b5\uc744 \ub5a0\uc62c\ub9ac\uba74 \ub3c4\uad6c\uc5d0 \ub9de\ucd98 \uc218\ub0a9\uc744 \uc774\ud574\ud558\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \uadf8\uac83\ub4e4\uacfc \uac19\uc740 \uc0dd\ud65c \uc81c\ub3c4\uc600\ub2e4\uace0 \uacb0\ub860\ub0bc \ud544\uc694\ub294 \uc5c6\ub2e4. \ubb3c\uac74\uc744 \ub123\uace0 \uaebc\ub0b4\ub294 \uc790\ub9ac\ub97c \ub9c8\ub828\ud588\ub2e4\ub294 \uacf5\ud1b5\uc810\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc774 \uc720\ubb3c\uc758 \ubaa8\uc591\uacfc \uc7a5\uc2dd\uc744 \ub530\ub85c \ubcf4\ub294 \uac83\uc774\ub2e4. \uce5c\uc219\ud55c \ube44\uc720\ub294 \ub0af\uc120 \ubb3c\uac74\uc744 \uc54c\uc544\ubcf4\ub294 \uc785\uad6c\uc774\uc9c0 \ubaa8\ub4e0 \ucc28\uc774\ub97c \uc9c0\uc6b0\ub294 \ub2f5\uc740 \uc544\ub2c8\ub2e4. \ubc14\uc704\uc640 \ud30c\ub3c4\ub294 \uc544\ub798\ucabd\uc744 \uc774\ub8e8\uace0 \uc18c\ub098\ubb34\uc640 \uaf43, \ud559\uc740 \uadf8 \uc704\uc5d0 \uad00\uacc4\ub97c \ub9cc\ub4e0\ub2e4. \ubc15\ubb3c\uad00\uc758 \ubb34\ub2ac \uc124\uba85\uc744 \ub530\ub77c\uac00\uba74 \ud55c\ub208\uc5d0 \ud654\ub824\ud558\ub2e4\ub294 \uc778\uc0c1\uc5d0\uc11c \uc5ec\ub7ec \uc694\uc18c\ub85c \uc7a5\uba74\uc774 \ub098\ub25c\ub2e4. \ubb34\uc5c7\uc774 \uc5b4\ub514\uc5d0 \ub193\uc600\ub294\uc9c0 \uc0b4\ud53c\ub294 \uc77c\uc740 \ub3d9\ubb3c\uacfc \uc2dd\ubb3c \uc774\ub984\uc744 \ub9ce\uc774 \uc678\uc6b0\ub294 \uac83\ubcf4\ub2e4 \uadf8\ub9bc\uc758 \uad6c\uc131\uc5d0 \uac00\uae4c\uc774 \uac00\uac8c \ud55c\ub2e4. \uc2e4\ub85c \ub9cc\ub4dc\ub294 \ud48d\uacbd\uc740 \uc885\uc774\uc5d0 \uadf8\ub9b0 \uadf8\ub9bc\uacfc \ub2e4\ub978 \ud45c\uba74\uc744 \uac00\uc9c4\ub2e4. \uc0c9\uc2e4\uc774 \ub098\ub780\ud788 \ub193\uc774\uace0 \ubc29\ud5a5\uc5d0 \ub530\ub77c \uacb0\uc774 \ubcf4\uc778\ub2e4. \uc2e4\uc81c \uc0ac\uc9c4\uc5d0\uc11c \uc138\ubd80\uac00 \ucda9\ubd84\ud788 \ub4dc\ub7ec\ub098\uc9c0 \uc54a\uc73c\uba74 \ud574\uc124\uc744 \uae30\uc900\uc73c\ub85c \ud070 \uad6c\uc131\uc744 \ud655\uc778\ud558\uba74 \ub41c\ub2e4. \ubcf4\uc774\uc9c0 \uc54a\ub294 \ubaa8\ub4e0 \ubc14\ub298\ub540\uc744 \uc0c1\uc0c1\uc73c\ub85c \uc77d\uc5b4\ub0bc \ud544\uc694\ub294 \uc5c6\ub2e4. \uc54c\ub824\uc9c4 \ubb34\ub2ac\uc640 \uc2e4\uc81c \ubcf4\uc774\ub294 \ud615\ud0dc\ub97c \uc624\uac00\ub294 \uac10\uc0c1\uc774 \uac00\ub2a5\ud558\ub2e4. \uc55e\uba74\uc740 \uae38\uc0c1 \ubb34\ub2ac\ub97c, \ub4b7\uba74\uc740 \uc88b\uc740 \uc0b6\uc744 \ubc14\ub77c\ub294 \uae00\uc744 \ub2f4\ub294\ub2e4. \uadf8\ub9bc\uacfc \uae00\uc774 \ubc18\ub4dc\uc2dc \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uc815\ubcf4\ub97c \uc804\ud558\ub294 \uac83\uc740 \uc544\ub2c8\uc9c0\ub9cc, \uc774 \ubb3c\uac74\uc5d0\uc11c\ub294 \uc11c\ub85c \ub2ee\uc740 \ubc14\ub78c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc77d\uc744 \uc218 \uc788\ub294 \uc0ac\ub78c\uacfc \uba3c\uc800 \ud615\uc0c1\uc744 \ubcf4\ub294 \uc0ac\ub78c\uc740 \ub2e4\ub978 \uc785\uad6c\ub85c \ub4e4\uc5b4\uc640 \ube44\uc2b7\ud55c \ub73b\uc744 \ub9cc\ub0a0 \uc218 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubb38\uc591 \ud558\ub098\ub9c8\ub2e4 \ub531 \ud558\ub098\uc758 \ub73b\ub9cc \uc601\uc6d0\ud788 \ubd99\ub294\ub2e4\uace0 \uc77c\ubc18\ud654\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc5ec\uae30\uc11c\ub294 \ubc15\ubb3c\uad00\uc774 \uc774 \uc18c\uc7a5\ud488\uc758 \uad6c\uc131\uc744 \uc5b4\ub5bb\uac8c \ud480\uc774\ud558\ub294\uc9c0 \ub530\ub77c\uac04\ub2e4. \uac1c\ubcc4 \ubb3c\uac74\uc758 \uc0ac\uc6a9\uc790\ub97c \ubaa8\ub97c \ub54c\uc5d0\ub3c4 \ud45c\ud604\ub41c \ubc14\ub78c\uc744 \uc77d\uc744 \uc218\ub294 \uc788\ub2e4. \ub204\uac00 \ub204\uad6c\uc5d0\uac8c \uc120\ubb3c\ud588\ub294\uc9c0 \ud655\uc778\ub418\uc9c0 \uc54a\uc558\ub2e4\ub294 \uc810\uacfc \uc88b\uc740 \ub73b\uc744 \ub2f4\uc558\ub2e4\ub294 \uc124\uba85\uc744 \ud568\uaed8 \ub0a8\uae30\ub294 \uac83\uc774\ub2e4. \ubc15\ubb3c\uad00\uc740 \ub69c\uaed1\uc758 \ub9e4\ud654\uc640 \ub048, \uc220 \uc7a5\uc2dd\ub3c4 \uc18c\uac1c\ud55c\ub2e4. \uc55e\ub4b7\uba74\uc758 \uc911\uc2ec \uc7a5\uba74\uc744 \ubcf8 \ub4a4 \ub05d\ubd80\ubd84\uc73c\ub85c \ub208\uc744 \uc62e\uaca8 \ubcf4\uba74 \ubb3c\uac74\uc744 \uc5ec\ub2eb\uace0 \ubb36\ub294 \uad6c\uc870\uc5d0 \uc7a5\uc2dd\uc774 \uc774\uc5b4\uc9d0\uc744 \uc54c \uc218 \uc788\ub2e4. \uae30\ub2a5\uc744 \uc704\ud55c \uc791\uc740 \ubd80\ubd84\ub3c4 \uafb8\ubc08\uc758 \ubc94\uc704 \ubc16\uc5d0 \uc788\uc9c0 \uc54a\uc558\ub2e4. \uc804\uccb4\ub97c \ub9c8\ubb34\ub9ac\ud558\ub294 \uc190\uae38\uc774 \uc5ec\ub7ec \uc790\ub9ac\uc5d0 \ub193\uc5ec \uc788\ub2e4. \ubb3c\uac74\uc758 \uc77c\ubd80\ub9cc \uc804\uc2dc\uc7a5\uc5d0 \ubcf4\uc774\uac70\ub098 \uc0ac\uc9c4 \ud55c\ucabd\uc774 \uac00\ub824\uc838 \uc788\uc5b4\ub3c4 \ud574\uc124\uc774 \ub2e4\ub978 \uba74\uc744 \ucc3e\uc544\ubcf4\uac8c \ub3c4\uc640\uc900\ub2e4. \ub2e4\ub9cc \uad00\ub78c\uc790\uac00 \uc9c1\uc811 \ub4a4\uc9d1\uc5b4 \ud655\uc778\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc790\ub8cc\ub97c \ud568\uaed8 \uc77d\uc73c\uba70 \uc74c\uc2dd \ub3c4\uad6c\uc758 \uc9d1\uc774\ub77c\ub294 \uc4f0\uc784\uacfc \uc0b6\uc744 \ubc14\ub77c\ub294 \ud45c\ud604\uc744 \ub098\ub780\ud788 \ubcfc \uc218 \uc788\ub2e4. \uc791\uc740 \uc8fc\uba38\ub2c8\uac00 \uc0dd\ud65c\uc758 \uc900\ube44\uc640 \uacf5\uc608, \uc18c\ub9dd\uc744 \ud568\uaed8 \ud488\uc5c8\ub2e4\ub294 \uc810\uc774 \ub0a8\ub294\ub2e4. \ub69c\uaed1\uc758 \uc55e\ub4b7\uba74\uc5d0\ub3c4 \ub9e4\ud654\uac00 \ub450 \uc1a1\uc774\uc529 \uc218\ub193\uc600\ub2e4. \uaf43\uc758 \uc528\ubc29\uc5d0\ub294 \uad6c\uba4d\uc744 \ub0b4\uace0 \ub048\uc744 \uaff0\uc5c8\uc73c\uba70 \uadf8 \uc544\ub798\ub85c \uc5ec\ub7ec \uc0c9\uc758 \uc220\uc744 \ub2ec\uc558\ub2e4. \uc8fc\uba38\ub2c8\ub97c \uafb8\ubbf8\ub294 \uc77c\uc774 \ubab8\uccb4\uc5d0\uc11c \ub05d\ub098\uc9c0 \uc54a\uc740 \uc148\uc774\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \ud55c\uaebc\ubc88\uc5d0 \ubaa8\ub4e0 \ubb34\ub2ac\ub97c \ucc3e\uc73c\ub824 \ud558\uba74 \ub208\uc774 \ubc14\ube60\uc9c4\ub2e4. \uba3c\uc800 \ud559\uc744 \ubcf4\uace0 \ub2e4\uc74c\uc5d0 \uaf43\uc744 \ubcf4\ub294 \uc815\ub3c4\uba74 \ucda9\ubd84\ud558\ub2e4. \ub9e4\uc77c\uc758 \uc2dd\uc0ac\uc640 \uba40\uc9c0 \uc54a\uc740 \ubb3c\uac74\uc5d0 \uc774\ub807\uac8c \ub9ce\uc740 \uc88b\uc740 \ub73b\uc744 \ubaa8\uc544 \ub450\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c\ub3c4, \ubd89\uc740 \uc218\uc800\uc9d1\uc740 \uc791\uc740 \uadf8\ub9bc\ucc45\ucc98\ub7fc \uc77d\ud78c\ub2e4."}, {"id": "henna-paste-and-stain", "title": "\ud53c\ubd80 \uc704\uc758 \ubb34\ub2ac\ub294 \uc53b\uc5b4 \ub0b8 \ub4a4\uc5d0\ub3c4 \ub0a8\ub294\ub2e4", "summary": "\ud53c\ubd80\uc5d0 \ubc14\ub978 \uc7ac\ub8cc\uc640 \uadf8 \uc7ac\ub8cc\uac00 \ub0a8\uae34 \ubb34\ub2ac\ub97c \ub098\ub204\uc5b4 \ubd05\ub2c8\ub2e4.", "category": "life", "category_title": "Life", "subcategory": "Clothing", "url": "stories/henna-paste-and-stain/index.html", "image": "media/henna-paste-and-stain.jpg", "alt": "\ud55c \uc0ac\ub78c\uc774 \ub2e4\ub978 \uc0ac\ub78c\uc758 \ud314\uc5d0 \ud5e4\ub098 \ubb34\ub2ac\ub97c \ub354\ud558\ub294 \uc791\uc5c5\uc758 \uc2e4\uc81c \uc0ac\uc9c4.", "text": "\ud53c\ubd80 \uc704\uc758 \ubb34\ub2ac\ub294 \uc53b\uc5b4 \ub0b8 \ub4a4\uc5d0\ub3c4 \ub0a8\ub294\ub2e4 \ud5e4\ub098\uac00 \uadf8\ub824\uc9c0\ub294 \uc21c\uac04\uacfc \ub0a8\uaca8\uc9c0\ub294 \uc0c9 \ud53c\ubd80\uc5d0 \ubc14\ub978 \uc7ac\ub8cc\uc640 \uadf8 \uc7ac\ub8cc\uac00 \ub0a8\uae34 \ubb34\ub2ac\ub97c \ub098\ub204\uc5b4 \ubd05\ub2c8\ub2e4. Clothing \uc0dd\ud65c \uc0ac\uc9c4 \uc18d\uc5d0\uc11c\ub294 \ud55c \uc0ac\ub78c\uc774 \ub2e4\ub978 \uc0ac\ub78c\uc758 \ud314\uc5d0 \uc791\uc740 \uc120\uc744 \ub354\ud558\uace0 \uc788\ub2e4. \uc190\uacfc \ud314\uc5d0 \ubcf5\uc7a1\ud55c \ubb34\ub2ac\uac00 \uc774\uc5b4\uc9c4\ub2e4. \ud5e4\ub098\ub97c \ubc14\ub974\ub294 \uc7a5\uba74\uc774\ub2e4. \uc6b0\ub9ac\uac00 \uc644\uc131\ub41c \uc7a5\uc2dd\uc774\ub77c\uace0 \ubcf4\ub294 \ubaa8\uc2b5 \uc55e\uc5d0\ub294 \uc7ac\ub8cc\ub97c \uc5b9\ub294 \uc2dc\uac04\uc774 \uc788\ub2e4. OpenStax \uad50\uc7ac\ub294 \ud5e4\ub098 \uc78e\uc744 \ube7b\uace0 \uace0\ub974\uac8c \ub9cc\ub4e0 \uc7ac\ub8cc\ub97c \ud53c\ubd80\uc5d0 \ubb34\ub2ac\ub85c \ubc14\ub974\ub294 \uacfc\uc815\uc744 \uc124\uba85\ud55c\ub2e4. \uadf8 \uc7ac\ub8cc\ub97c \uac77\uc5b4 \ub0b8 \ub4a4\uc5d0\ub3c4 \ud53c\ubd80\uc5d0\ub294 \ubd89\uac70\ub098 \uc8fc\ud669\ube5b\uc758 \uc0c9\uc774 \ub0a8\ub294\ub2e4. \uadf8\ub798\uc11c \ud5e4\ub098\ub294 \ubc14\ub978 \uc21c\uac04\uc758 \ubaa8\uc2b5\uacfc \uc7ac\ub8cc\ub97c \uc81c\uac70\ud55c \ub4a4\uc758 \ubaa8\uc2b5\uc774 \ub2e4\ub97c \uc218 \uc788\ub2e4. \ud53c\ubd80 \uc704\uc5d0 \uc62c\ub77c\uc628 \ubd80\ubd84\ub9cc\uc774 \ubb34\ub2ac\uc758 \uc804\ubd80\ub294 \uc544\ub2c8\ub2e4. \uadf8 \uc544\ub798\uc5d0 \ub0a8\uc740 \uc0c9\ub3c4 \uc7a5\uc2dd\uc774 \ub41c\ub2e4. \uc0ac\uc9c4\uc744 \ubcfc \ub54c \uc9d9\uac8c \ubcf4\uc774\ub294 \uc120\uacfc \uadf8\ub9b0 \uc0ac\ub78c\uc758 \uc190\uc744 \ud568\uaed8 \uc0b4\ud3b4\ubcf4\uc790. \uc774\ubbf8 \uc644\uc131\ub41c \uacb0\uacfc\ub9cc \ubcf4\ub294 \ub300\uc2e0 \uc120\uc744 \ub354\ud558\ub294 \uc791\uc5c5\uc744 \uc77d\uac8c \ub41c\ub2e4. \uc774 \uc774\ubbf8\uc9c0 \ud55c \uc7a5\uc774 \ubaa8\ub4e0 \ub2e8\uacc4\uc758 \uac19\uc740 \ud314\uc744 \uc5f0\uc18d \ucd2c\uc601\ud55c \uac83\uc774\ub77c\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uad50\uc7ac\ub294 \ud5e4\ub098\ub97c \uc778\ub3c4 \uc544\ub300\ub959\uacfc \ubd81\uc544\ud504\ub9ac\uce74 \ub4f1 \uc5ec\ub7ec \uc9c0\uc5ed\uc5d0\uc11c \uc0ac\uc6a9\ud558\ub294 \ubab8 \uafb8\ubc08\uc758 \uc608\ub85c \uc18c\uac1c\ud55c\ub2e4. \ud63c\ub840\ub098 \uc885\uad50\uc801 \uae30\ub150\uc77c \uac19\uc740 \ud2b9\ubcc4\ud55c \ub54c \uc190\uc774\ub098 \ubc1c\uc744 \uc7a5\uc2dd\ud558\uae30\ub3c4 \ud55c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc9c0\uc5ed\ub9c8\ub2e4 \ub611\uac19\uc740 \ubb34\ub2ac\uc5d0 \uac19\uc740 \ub73b\uc744 \ubd99\uc778\ub2e4\ub294 \ub9d0\uc740 \uc544\ub2c8\ub2e4. \uac19\uc740 \uc7ac\ub8cc\ub77c\ub3c4 \ub204\uac00 \uc5b8\uc81c \uc5b4\ub5a4 \uad00\uacc4 \uc18d\uc5d0\uc11c \uc0ac\uc6a9\ud558\ub294\uc9c0\uc5d0 \ub530\ub77c \uc77d\ub294 \ub9e5\ub77d\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ubb34\ub2ac\uc758 \uc774\ub984\uc744 \ud558\ub098\ub85c \ubb36\uc5b4 \ubc84\ub9ac\uae30\ubcf4\ub2e4 \uc0ac\uc6a9\ub418\ub294 \uc790\ub9ac\ub97c \ud568\uaed8 \ubcf4\uba74 \uc88b\ub2e4. \uad50\uc7ac\ub294 \ud5e4\ub098 \uc78e\uc744 \uac08\uace0 \uccb4\uc9c8\ud55c \uc7ac\ub8cc\ub97c \ud53c\ubd80\uc5d0 \uc0ac\uc6a9\ud55c \ub4a4 \uc81c\uac70\ud558\uba74 \uc0c9\uc774 \ub0a8\ub294\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub9cc\ub4dc\ub294 \uc7ac\ub8cc\uc640 \ucd5c\uc885\uc801\uc73c\ub85c \ubcf4\uc774\ub294 \uc0c9\uc774 \uac19\uc740 \uc0c1\ud0dc\ub294 \uc544\ub2c8\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \ub3c4\ud1b0\ud558\uac8c \uc62c\ub77c\uc628 \uc120\uc744 \ubcf4\uc558\ub2e4\uba74 \uc544\uc9c1 \ud45c\uba74\uc5d0 \uc7ac\ub8cc\uac00 \uc788\ub294 \uacfc\uc815\uc77c \uc218 \uc788\ub2e4. \uacb0\uacfc\ub9cc\uc774 \uc544\ub2c8\ub77c \ubcc0\ud654\ud558\ub294 \ub2e8\uacc4\ub97c \ub098\ub204\uc5b4 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc774 \ucc28\uc774\ub294 \uc5b4\ub5a4 \ud53c\ubd80 \uc7a5\uc2dd\uc778\uc9c0 \uc774\ud574\ud558\ub294 \ub370 \uc911\uc694\ud558\ub2e4. \ud558\uc9c0\ub9cc \uc2e4\uc81c \uc7ac\ub8cc\uc758 \ubc30\ud569\uc774\ub098 \ub3c4\ud3ec \uc2dc\uac04, \uac1c\uc778\uc758 \ubc18\uc751\uc744 \uc774 \uc0ac\uc9c4\ub9cc\uc73c\ub85c \uc54c \uc218\ub294 \uc5c6\ub2e4. \uc774 \uae00\uc740 \ub530\ub77c \ud558\ub294 \uc2dc\uc220 \uc548\ub0b4\uac00 \uc544\ub2c8\ub77c \uad50\uc7ac\uac00 \uc18c\uac1c\ud55c \uc7ac\ub8cc\uc640 \ud615\ud0dc\uc758 \uad00\uacc4\ub97c \uc77d\ub294 \uc774\uc57c\uae30\ub2e4. \ubb34\ub2ac\uac00 \ubcf4\uc774\ub294 \ubc29\uc2dd\uacfc \uadf8\uac83\uc744 \ub9cc\ub4dc\ub294 \uacfc\uc815\uc744 \uad6c\ubd84\ud558\ub294 \ub370 \ucd08\uc810\uc744 \ub9de\ucd98\ub2e4. \uc2e4\uc81c \uc0ac\uc9c4\uc5d0\ub294 \uc644\uc131\ub41c \ubb34\ub2ac\ubfd0 \uc544\ub2c8\ub77c \uc791\uc5c5\ud558\ub294 \uc190\ub3c4 \ubcf4\uc778\ub2e4. \uc7a5\uc2dd\uc740 \ucc98\uc74c\ubd80\ud130 \ud53c\ubd80\uc5d0 \uc788\ub358 \uac83\uc774 \uc544\ub2c8\ub77c \ub2e4\ub978 \uc0ac\ub78c\uc774 \uc120\uc744 \ub193\uc73c\uba70 \ub9cc\ub4e0 \uacb0\uacfc\ub2e4. \uac00\uae4c\uc774 \uc549\uc544 \uc2dc\uac04\uc744 \ud568\uaed8 \uc4f0\ub294 \ud589\ub3d9\uc774 \uadf8 \ub4a4\uc5d0 \uc788\ub2e4. \ub2e8\uc21c\ud788 \ubb34\ub2ac \ud558\ub098\ub97c \uace0\ub974\ub294 \uac83\uacfc \uc2e4\uc81c\ub85c \ubab8\uc5d0 \ud45c\ud604\ud558\ub294 \uacbd\ud5d8\uc740 \uac19\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ub450 \uc0ac\ub78c\uc774 \uc5b4\ub5a4 \uad00\uacc4\uc778\uc9c0, \uadf8\ub0a0 \uc5b4\ub5a4 \ub300\ud654\ub97c \ub098\ub204\uc5c8\ub294\uc9c0\uae4c\uc9c0 \uc0c1\uc0c1\uc73c\ub85c \uc801\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc0ac\uc9c4\uc774 \ubcf4\uc5ec \uc8fc\ub294 \uac83\uc740 \uc791\uc5c5\uacfc \ubab8\uc758 \uc811\uc810\uc774\ub2e4. \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc190\uc774 \uad00\uc5ec\ud558\ub294 \uafb8\ubc08\uc774\ub77c\ub294 \uc810\uc744 \ubcf4\uba74 \ubb3c\uac74\uc758 \uc7a5\uc2dd\uacfc \ub2e4\ub978 \uad00\uacc4\uac00 \ub4dc\ub7ec\ub09c\ub2e4. \uc544\ub984\ub2e4\uc6b4 \uc120\uc740 \uc7ac\ub8cc\ubfd0 \uc544\ub2c8\ub77c \uc0ac\ub78c \uc0ac\uc774\uc758 \ud589\ub3d9\uc744 \uac70\uccd0 \ub193\uc778\ub2e4. \ud63c\ub840\uc640 \uae30\ub150\uc77c\uc774\ub77c\ub294 \ubc30\uacbd\uc744 \uc54c\uba74 \ubb34\ub2ac\ub294 \uac1c\uc778\uc758 \ucde8\ud5a5\ub9cc\uc73c\ub85c \uc124\uba85\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc5b4\ub5a4 \ub0a0\uc744 \uc704\ud574 \uafb8\ubbf8\uace0 \uadf8 \ubaa8\uc2b5\uc744 \ub2e4\ub978 \uc0ac\ub78c\uacfc \ub098\ub204\ub294 \uc77c\ub3c4 \uc788\uc744 \uc218 \uc788\ub2e4. \ubab8\uc744 \uafb8\ubbf8\ub294 \ud589\ub3d9\uc774 \ub2ec\ub825\uacfc \uad00\uacc4, \ucd95\ud558\uc758 \uc790\ub9ac\uc5d0 \uc5f0\uacb0\ub41c\ub2e4. \ubb3c\ub860 \ubaa8\ub4e0 \uc9c0\uc5ed\uacfc \uc0ac\ub78c\uc774 \uac19\uc740 \uc774\uc720\ub85c \uac19\uc740 \ubaa8\uc591\uc744 \uc4f0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uac19\uc740 \uc7ac\ub8cc\uac00 \ub113\uc740 \uc9c0\uc5ed\uc5d0 \uc4f0\uc778\ub2e4\uace0 \ud55c \uac00\uc9c0 \ubb38\ud654\uc758 \uace0\uc815\ub41c \uc0c1\uc9d5\ud45c\ub85c \uc815\ub9ac\ud558\uba74 \ucc28\uc774\ub97c \ub193\uce58\uac8c \ub41c\ub2e4. \uc5b4\ub290 \uc9c0\uc5ed\uc758 \uc5b4\ub5a4 \ud589\uc0ac\ub97c \uc124\uba85\ud558\ub294\uc9c0 \uc790\ub8cc\uc758 \ubc94\uc704\ub97c \uba3c\uc800 \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \uc778\ub3c4 \uc544\ub300\ub959\uacfc \ubd81\uc544\ud504\ub9ac\uce74\uc758 \uc0ac\ub840\ub97c \ud558\ub098\uc758 \ub611\uac19\uc740 \uacbd\ud5d8\uc73c\ub85c \ubb36\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc815\ud655\ud558\ub2e4. \uacf5\ud1b5\uc810\uacfc \ucc28\uc774\ub97c \ud568\uaed8 \ubcf4\ub294 \uac83\uc774 \ubb38\ud654 \uc77d\uae30\uc758 \uc990\uac70\uc6c0\uc774\ub2e4. \uac89\uc758 \uc7ac\ub8cc\ub97c \uc81c\uac70\ud55c \ub4a4\uc5d0\ub3c4 \uc0c9\uc774 \ub0a8\ub294\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uc7a5\uc2dd\uc758 \uc2dc\uac04\uc744 \ub458\ub85c \ub098\ub208\ub2e4. \uc120\uc744 \ub193\ub294 \uc21c\uac04\uacfc \uadf8\ub2e4\uc74c \ubab8\uc5d0 \uc0c9\uc744 \uc9c0\ub2c8\ub294 \uc2dc\uac04\uc774 \uc788\ub2e4. \uc0ac\uc9c4 \ud55c \uc7a5\uc740 \uc5b4\ub290 \ud55c\ub54c\ub97c \ubcf4\uc5ec \uc8fc\uc9c0\ub9cc \uadf8 \uc55e\ub4a4\uc758 \ubcc0\ud654\ub97c \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uc7a5\uc2dd\uc740 \uc644\uc131\ud55c \ubb3c\uac74\ucc98\ub7fc \uace0\uc815\ub41c \ubaa8\uc2b5\ub9cc \uac16\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ubab8\uacfc \ud568\uaed8 \ub2ec\ub77c\uc9c0\ub294 \uac83\uc774\uae30\ub3c4 \ud558\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc5bc\ub9c8\ub098 \uc624\ub798\uac14\ub294\uc9c0\ub098 \uc5b4\ub5a4 \uc0c9\uc774 \ub204\uad6c\uc5d0\uac8c \ub098\ud0c0\ub0ac\ub294\uc9c0\ub97c \uc0c8\ub85c \ub2e8\uc815\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc790\ub8cc\uc758 \uc77c\ubc18\uc801\uc778 \uacfc\uc815 \uc124\uba85\uacfc \uac1c\ubcc4 \uc0ac\uc9c4\uc758 \uc0c1\ud0dc\ub97c \uad6c\ubd84\ud574 \uc77d\ub294\ub2e4. \ubcf4\uc774\ub294 \uc120\uc744 \ucc9c\ucc9c\ud788 \ub530\ub77c\uac00\uace0 \uadf8\uac83\uc744 \ub9cc\ub4dc\ub294 \uc190\uc758 \uc704\uce58\ub3c4 \ubcf4\uc544 \ubcf4\uc790. \ud53c\ubd80\uc758 \ubb34\ub2ac\uc5d0\uc11c \uc7ac\ub8cc\uc640 \uc2dc\uac04, \uc0ac\ub78c \uc0ac\uc774\uc758 \uad00\uacc4\uac00 \ud568\uaed8 \ub4dc\ub7ec\ub0a0 \uc218 \uc788\ub2e4. \uc774 \uc0ac\uc9c4\uc758 \uc7a5\uc18c\ub97c \ud655\uc778 \uc5c6\uc774 \ud2b9\uc815 \ub098\ub77c\ub098 \ub3c4\uc2dc\ub85c \uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc5ec\uae30\uc11c \uc2e4\uc81c\ub85c \ubcfc \uc218 \uc788\ub294 \uac83\uc740 \ud53c\ubd80 \uc704\uc5d0 \ubb34\ub2ac\ub97c \ub354\ud558\ub294 \uc791\uc5c5\uc774\uba70, \ubb38\ud654\uc801 \uc4f0\uc784\uc740 \uad50\uc7ac\uc758 \uc124\uba85\uc73c\ub85c \ub530\ub85c \uc77d\ub294 \ubd80\ubd84\uc774\ub2e4. \ubab8\uc744 \uafb8\ubbf8\ub294 \uc77c\uc5d0\ub294 \uc637\uacfc \ubcf4\uc11d\ub9cc \uc788\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc120\uc744 \uae0b\uace0 \uc7ac\ub8cc\ub97c \uae30\ub2e4\ub9b0 \ub4a4 \uc0c9\uc744 \ub0a8\uae30\ub294 \ubc29\ubc95\ub3c4 \uc788\ub2e4. \ud5e4\ub098\uc758 \uc7a5\uba74\uc740 \uc7a5\uc2dd\uc774 \ubb34\uc5c7\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc9c0\uace0 \uc5b8\uc81c \uc644\uc131\ub418\ub294\uc9c0\ub97c \uc870\uae08 \ub2e4\ub974\uac8c \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4."}, {"id": "jordan-moving-tent", "title": "\uc774 \uc9d1\uc740 \ub2e4\uc74c \ubaa9\ucd08\uc9c0\uae4c\uc9c0 \ud568\uaed8 \uac04\ub2e4", "summary": "\uc774\ub3d9\ud558\ub294 \uc0dd\ud65c\uc5d0\uc11c \ucc9c\ub9c9\uc774 \uc784\uc2dc \uac70\ucc98 \uc774\uc0c1\uc758 \uc9d1\uc774 \ub418\ub294 \ubc29\uc2dd\uc744 \ubd05\ub2c8\ub2e4.", "category": "life", "category_title": "Life", "subcategory": "Housing", "url": "stories/jordan-moving-tent/index.html", "image": "media/jordan-moving-tent.jpg", "alt": "\uc694\ub974\ub2e8\uc758 \uacbd\uc0ac\uc9c0\uc5d0 \uc138\uc6cc\uc9c4 \uae38\ucb49\ud55c \ubca0\ub450\uc778 \ucc9c\ub9c9\uacfc \uc8fc\ubcc0 \ud48d\uacbd\uc758 \uc2e4\uc81c \uc0ac\uc9c4.", "text": "\uc774 \uc9d1\uc740 \ub2e4\uc74c \ubaa9\ucd08\uc9c0\uae4c\uc9c0 \ud568\uaed8 \uac04\ub2e4 \uc694\ub974\ub2e8\uc758 \ucc9c\ub9c9\uc5d0\uc11c \uc9d1\uc758 \uc870\uac74\uc744 \ub2e4\uc2dc \ubcf4\uae30 \uc774\ub3d9\ud558\ub294 \uc0dd\ud65c\uc5d0\uc11c \ucc9c\ub9c9\uc774 \uc784\uc2dc \uac70\ucc98 \uc774\uc0c1\uc758 \uc9d1\uc774 \ub418\ub294 \ubc29\uc2dd\uc744 \ubd05\ub2c8\ub2e4. Housing \uc0dd\ud65c \uc0ac\uc9c4 \uc18d \ube44\ud0c8\uc5d0\ub294 \ub0ae\uace0 \uae38\ucb49\ud55c \ucc9c\ub9c9\uc774 \ub193\uc5ec \uc788\ub2e4. \ub2e8\ub2e8\ud55c \ubcbd\ub3cc \uac74\ubb3c\uc5d0 \uc775\uc219\ud558\ub2e4\uba74 \uc7a0\uae50 \uba38\ubb34\ub294 \uc57c\uc601\uc9c0\ucc98\ub7fc \ubcf4\uc77c \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uc774\ub3d9\ud558\uba70 \uac00\ucd95\uc744 \ub3cc\ubcf4\ub294 \uc0dd\ud65c\uc5d0\uc11c\ub294 \uc9d1\ub3c4 \ud568\uaed8 \uc6c0\uc9c1\uc77c \uc218 \uc788\uc5b4\uc57c \ud55c\ub2e4. OpenStax\uc758 \uc778\ub958\ud559 \uad50\uc7ac\ub294 \uc774 \uc0ac\uc9c4\uc744 \uc694\ub974\ub2e8\uc758 \ubca0\ub450\uc778 \ucc9c\ub9c9\uc73c\ub85c \uc18c\uac1c\ud55c\ub2e4. \uc9d1\uc744 \ud55c \uc7a5\uc18c\uc5d0 \uace0\uc815\ub41c \uac74\ubb3c\uc774\ub77c\uace0\ub9cc \uc0dd\uac01\ud558\uba74 \uc9c0\ub098\uce58\uae30 \uc26c\uc6b4 \uc0dd\ud65c\uc758 \uc870\uac74\uc774 \uc788\ub2e4. \uad50\uc7ac\ub294 \uc77c\ubd80 \ubca0\ub450\uc778 \ubaa9\ucd95 \uacf5\ub3d9\uccb4\uac00 \uac00\ucd95\uc744 \uba39\uc77c \ud480\uacfc \ubb3c\uc744 \ucc3e\uc544 \uac70\ucc98\ub97c \uc62e\uaca8 \uc654\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc774\ub7f0 \uc0dd\ud65c\uc5d0\uc11c\ub294 \uc9d1\uc744 \uc138\uc6b0\ub294 \uc77c\uacfc \uac77\ub294 \uc77c\uc774 \ubaa8\ub450 \uc911\uc694\ud558\ub2e4. \ubb34\ub108\uc9c0\uc9c0 \uc54a\ub294 \uac83\ub9cc\uc774 \uc88b\uc740 \uc9d1\uc758 \uc870\uac74\uc740 \uc544\ub2c8\ub2e4. \uc0ac\uc6a9\ud558\ub358 \uac70\ucc98\ub97c \uc815\ub9ac\ud558\uace0 \ub2e4\ub978 \uc790\ub9ac\uc5d0\uc11c \ub2e4\uc2dc \ud3bc\uce60 \uc218 \uc788\uc5b4\uc57c \ud55c\ub2e4. \ucc9c\ub9c9\uc740 \uadf8 \ud544\uc694\uc640 \uc798 \ub9de\ub294 \ud615\ud0dc\ub2e4. \uc0ac\uc9c4\uc758 \ub0ae\uc740 \uc9c0\ubd95\uc744 \ubcfc \ub54c \uc624\ub298 \uba38\ubb34\ub294 \uc790\ub9ac\uc640 \ub2e4\uc74c\uc5d0 \uba38\ubb3c \uc790\ub9ac\ub97c \ud568\uaed8 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \uc774\ub3d9\ud558\ub294 \uc9d1\uc774\ub77c\uace0 \uc548\ucabd\uc774 \uc544\ubb34\ub807\uac8c\ub098 \ube44\uc5b4 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uad50\uc7ac\ub294 \uc804\ud1b5\uc801\uc778 \ubca0\ub450\uc778 \uac70\ucc98\uc5d0\uc11c \uc870\ub9ac\uc640 \ubcf4\uad00, \uc190\ub2d8 \ub9de\uc774 \ub4f1\uc744 \uc704\ud574 \uacf5\uac04\uc744 \ub098\ub204\ub294 \uc608\ub97c \uc18c\uac1c\ud55c\ub2e4. \uac00\uc871\uc758 \uc77c\uacfc \uad00\uacc4\uac00 \uacf5\uac04 \uc548\uc5d0 \uc790\ub9ac \uc7a1\ub294 \uac83\uc774\ub2e4. \ubb3c\ub860 \uc0ac\uc9c4\ub9cc \ubcf4\uace0 \uc774 \ucc9c\ub9c9\uc758 \ubaa8\ub4e0 \ubc29 \ubc30\uce58\ub97c \uc54c\uc544\ub0bc \uc218\ub294 \uc5c6\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc774\ub3d9 \uac00\ub2a5\uc131\uacfc \uc77c\uc0c1\uc758 \uad6c\ubd84\uc774 \ud568\uaed8 \uc788\uc744 \uc218 \uc788\ub2e4\ub294 \uc810\uc744 \uc0b4\ud3b4\ubcf4\uba74 \ucda9\ubd84\ud558\ub2e4. \uac00\ubcbc\uc6b4 \uc7ac\ub8cc\uac00 \uac00\ubcbc\uc6b4 \uc0dd\ud65c\uc744 \ub73b\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc6b0\ub9ac\ub294 \uc9d1\uc744 \uc8fc\uc18c\uac00 \uace0\uc815\ub41c \uac74\ubb3c\ub85c \uc0dd\uac01\ud558\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \ubaa9\ucd08\uc9c0\uc640 \ubb3c\uc744 \ub530\ub77c \uc774\ub3d9\ud558\ub294 \uc0dd\ud65c\uc5d0\uc11c\ub294 \ub2e4\uc2dc \uc138\uc6b8 \uc218 \uc788\ub294\uc9c0\uac00 \uc911\uc694\ud55c \uc870\uac74\uc774 \ub41c\ub2e4. \uac19\uc740 \uc7a5\uc18c\uc5d0 \uc624\ub798 \uc11c \uc788\ub2e4\ub294 \uae30\uc900\ub9cc\uc73c\ub85c \uc9d1\uc758 \uc88b\uace0 \ub098\uc068\uc744 \ud310\ub2e8\ud558\uae30 \uc5b4\ub835\ub2e4. \ucc9c\ub9c9\uc740 \uba38\ubb34\ub294 \uac83\uacfc \uc62e\uae30\ub294 \uac83\uc744 \ud568\uaed8 \uc900\ube44\ud558\ub294 \uac70\ucc98\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc0ac\uc9c4 \uc18d \uc9d1\ub2e8\uc774 \uc5b8\uc81c \uc5b4\ub5a4 \uacbd\ub85c\ub85c \uc774\ub3d9\ud588\ub294\uc9c0\uae4c\uc9c0 \uc54c \uc218\ub294 \uc5c6\ub2e4. \uc774\ub3d9 \uac00\ub2a5\uc131\uc744 \uac00\uc9c4 \uc8fc\uac70\uc758 \ud2b9\uc9d5\uacfc \ud2b9\uc815 \uac00\uc871\uc758 \uc0dd\ud65c\uc740 \uad6c\ubcc4\ud574\uc57c \ud55c\ub2e4. \uad50\uc7ac\ub294 \uc77c\ubd80 \ubaa9\ucd95 \uacf5\ub3d9\uccb4\uc758 \uc0ac\ub840\ub97c \uc124\uba85\ud55c\ub2e4. \ubca0\ub450\uc778\uc774\ub77c\ub294 \uc774\ub984\uc744 \uac00\uc9c4 \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \ud604\uc7ac\ub3c4 \ud55c \ubc29\uc2dd\uc73c\ub85c \uc0b0\ub2e4\uace0 \uc77c\ubc18\ud654\ud558\uba74 \uc790\ub8cc\uc758 \ubc94\uc704\ub97c \ubc97\uc5b4\ub09c\ub2e4. \uc870\ub9ac\uc640 \ubcf4\uad00, \uc190\ub2d8 \ub9de\uc774\uc758 \uc790\ub9ac\ub97c \ub098\ub204\ub294 \uc77c\uc740 \ubcbd\ub3cc\ubc29\uc5d0\uc11c\ub9cc \uc0dd\uae30\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc77c\uc758 \uc885\ub958\uc640 \uc0ac\ub78c \uc0ac\uc774\uc758 \uad00\uacc4\uac00 \uc788\uc73c\uba74 \ucc9c\ub9c9 \uc548\uc5d0\uc11c\ub3c4 \uc704\uce58\uac00 \uc758\ubbf8\ub97c \uac00\uc9c8 \uc218 \uc788\ub2e4. \uc9d1\uc758 \uc870\uc9c1\uc744 \uc7ac\ub8cc\uc758 \ub2e8\ub2e8\ud568\ub9cc\uc73c\ub85c \uc124\uba85\ud560 \uc218 \uc5c6\ub294 \uc774\uc720\ub2e4. \uac00\ubcbc\uc6b4 \uac70\ucc98\uac00 \uace7 \uad6c\ubd84 \uc5c6\ub294 \ube48 \uacf5\uac04\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ub2e4\ub9cc \uc0ac\uc9c4\uc758 \ubc14\uae65\ubaa8\uc2b5\uc744 \ubcf4\uace0 \uc548\ucabd\uc758 \ubaa8\ub4e0 \ubc30\uce58\ub97c \uadf8\ub824 \ub123\uc5b4\uc11c\ub294 \uc548 \ub41c\ub2e4. \uad50\uc7ac\uac00 \uc804\ud1b5 \uac70\ucc98\uc758 \uc608\ub85c \uc124\uba85\ud558\ub294 \ub0b4\uc6a9\uacfc \uc9c0\uae08 \ubcf4\uc774\ub294 \uc0ac\uc9c4\uc744 \ud568\uaed8 \uc77d\ub294 \uac83\uc774\ub2e4. \ubb38\uacfc \uae30\ub465, \ucc9c\uc758 \uacbd\uacc4\ub97c \uad00\ucc30\ud558\ub418 \uc2e4\uc81c \uae30\ub2a5\uc758 \uc138\ubd80\ub294 \ud574\ub2f9 \uc124\uba85\uc744 \uae30\uc900\uc73c\ub85c \uc0bc\ub294\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \uad6c\uc870\uc640 \uc0ac\ud68c\uc801 \uc0ac\uc6a9\uc740 \uc11c\ub85c \ubcf4\uc644\ud560 \uc218 \uc788\ub2e4. \ubaa9\ucd95\uc5d0\uc11c\ub294 \uc0ac\ub78c\ub9cc\uc774 \uc544\ub2c8\ub77c \uac00\ucd95\uc758 \uba39\uc774\uc640 \ubb3c\ub3c4 \uc774\ub3d9\uc5d0 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\ub2e4. \uc9d1\uc744 \uc5b4\ub514\uc5d0 \ub458\uc9c0\uc758 \ubb38\uc81c\uc5d0 \ub2e4\ub978 \uc0dd\ubb3c\uc758 \uc0dd\ud65c \uc870\uac74\uc774 \ub4e4\uc5b4\uc624\ub294 \uc148\uc774\ub2e4. \ub3c4\uc2dc\uc758 \uc0c1\uac00\uc640 \ucd9c\ud1f4\uadfc \uac70\ub9ac\ub97c \uc911\uc2ec\uc73c\ub85c \uc9d1\uc744 \uc0dd\uac01\ud558\ub294 \uacbd\ud5d8\uacfc \ub098\ub780\ud788 \ub193\uc73c\uba74, \uc8fc\uac70\uc758 \uc120\ud0dd\uc774 \ud658\uacbd\uacfc \uc77c\uc758 \ubc29\uc2dd\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9d0\uc744 \uc54c \uc218 \uc788\ub2e4. \uc774 \ube44\uad50\uac00 \uc5b4\ub290 \uc0dd\ud65c\uc774 \ub354 \uc790\uc5f0\uc2a4\ub7fd\uac70\ub098 \uc6b0\uc6d4\ud558\ub2e4\ub294 \uc21c\uc704\ub97c \ub9cc\ub4dc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc870\uac74\uc5d0\uc11c \ubb34\uc5c7\uc744 \uc911\uc694\ud558\uac8c \uc5ec\uacbc\ub294\uc9c0 \uc774\ud574\ud558\uae30 \uc704\ud55c \uad00\uc810\uc774\ub2e4. \ubaa8\ub4e0 \ucc9c\ub9c9\uc744 \uc5b4\ub824\uc6b4 \uc0ac\uc815 \ub54c\ubb38\uc5d0 \uc120\ud0dd\ud55c \uc784\uc2dc \uac74\ubb3c\ub85c\ub9cc \uc124\uba85\ud558\ub294 \uac83\ub3c4 \ucda9\ubd84\ud558\uc9c0 \uc54a\ub2e4. \uad50\uc7ac\uac00 \uc18c\uac1c\ud558\ub294 \uc774\ub3d9\uacfc \uc0dd\ud65c\uc758 \uad00\uacc4\ub97c \uba3c\uc800 \uc77d\uc5b4 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uad50\uc7ac\ub294 \uc624\ub298\uc758 \ubca0\ub450\uc778 \uacf5\ub3d9\uccb4\uac00 \ub2e4\uc591\ud55c \uc815\ucc29\uacfc \ub178\ub3d9\uc758 \ud615\ud0dc\ub97c \uac00\uc9c4\ub2e4\ub294 \uc810\ub3c4 \ud568\uaed8 \uc124\uba85\ud55c\ub2e4. \uacfc\uac70\uc758 \ud55c \uc8fc\uac70 \ubaa8\uc2b5\uc774 \uc0ac\ub78c\ub4e4\uc758 \ud604\uc7ac \uc804\uccb4\ub97c \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc804\ud1b5\uc744 \uc54c\uace0 \uc788\ub2e4\ub294 \ub9d0\uc774 \ud2b9\uc815 \uc9d1\ub2e8\uc744 \uc61b \uc0ac\uc9c4 \uc18d\uc5d0 \uace0\uc815\uc2dc\ud0a4\ub294 \uc77c\uc774 \ub418\uc5b4\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc624\ub798\ub41c \uc0dd\ud65c\uc758 \uae30\uc220\uacfc \uc9c0\uae08\uc758 \uc5ec\ub7ec \uc120\ud0dd\uc740 \ud568\uaed8 \uc788\uc744 \uc218 \uc788\ub2e4. \uc774 \uc0ac\uc9c4\uc744 \ubcfc \ub54c\uc5d0\ub294 \uc694\ub974\ub2e8\uc758 \uc2e4\uc81c \uc7a5\uba74\uc774\ub77c\ub294 \uc815\ubcf4\ub97c \ub0a8\uae30\uace0 \ucc9c\ub9c9\uc758 \ud3bc\uccd0\uc9c4 \ubaa8\uc591\uc744 \ub530\ub77c\uac00 \ubcf4\uc790. \uba40\ub9ac\uc11c \ubcf8 \ub0ae\uc740 \uc9c0\ubd95 \uc548\uc5d0\ub3c4 \uc77c\uacfc \uad00\uacc4\uc758 \uc790\ub9ac\uac00 \uc788\uc5c8\uc744 \uc218 \uc788\ub2e4. \uc9d1\uc744 \uc6c0\uc9c1\uc774\uc9c0 \uc54a\ub294 \ubcbd\uc73c\ub85c\ub9cc \uc815\uc758\ud558\ub358 \uc2dc\uc120\uc5d0\uc11c \ubc97\uc5b4\ub098\uba74, \ubb34\uc5c7\uc744 \uac00\uc9c0\uace0 \ub2e4\uc74c \uc7a5\uc18c\ub85c \uac08 \uc218 \uc788\uac8c \ud588\ub294\uc9c0\ub77c\ub294 \uc0c8\ub85c\uc6b4 \uac74\ucd95\uc758 \uc9c8\ubb38\uc744 \uc5bb\ub294\ub2e4. \uc624\ub298\uc758 \ubca0\ub450\uc778 \uc0dd\ud65c\uc744 \ubaa8\ub450 \ucc9c\ub9c9 \ud558\ub098\ub85c \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \uad50\uc7ac\ub3c4 \uc815\ucc29\ud55c \ub9c8\uc744\uacfc \ub3c4\uc2dc\uc758 \uc0b6, \uc5ec\ub7ec \ud615\ud0dc\uc758 \uc77c\uc744 \ud568\uaed8 \uc18c\uac1c\ud55c\ub2e4. \uc0ac\uc9c4\uc740 \uadf8 \ub2e4\uc591\ud55c \uc0b6 \uac00\uc6b4\ub370 \ud55c \uac70\ucc98\uc758 \ubaa8\uc2b5\uc774\ub2e4. \uadf8\ub7fc\uc5d0\ub3c4 \uc774 \uc7a5\uba74\uc740 \uc775\uc219\ud55c \uc9c8\ubb38\uc744 \ubc14\uafd4 \uc900\ub2e4. \uc88b\uc740 \uc9d1\uc740 \uc624\ub798 \uac19\uc740 \uc790\ub9ac\uc5d0 \ub0a8\ub294 \uc9d1\uc77c\uae4c, \ud544\uc694\ud55c \uacf3\uae4c\uc9c0 \ud568\uaed8 \uac00\ub294 \uc9d1\uc77c\uae4c. \uc0ac\ub78c\uc758 \uc0dd\ud65c\uc774 \ub2ec\ub77c\uc9c0\uba74 \uc9d1\uc5d0 \uae30\ub300\ud558\ub294 \ub2a5\ub825\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uc694\ub974\ub2e8\uc758 \ucc9c\ub9c9\uc740 \uadf8\ub7f0 \uc9d1\uc758 \ub2e4\ub978 \uc5bc\uad74\uc744 \ubcf4\uc5ec \uc900\ub2e4."}, {"id": "kabyle-house-shared-roof", "title": "\ud55c \uc9c0\ubd95 \uc544\ub798 \uc0ac\ub78c\uacfc \uac00\ucd95\uc758 \uc790\ub9ac\uac00 \uc788\uc5c8\ub2e4", "summary": "\ub3cc\uc9d1\uc758 \uc678\uad00\uacfc \uc9d1 \uc548\uc744 \uad6c\ubd84\ud55c \uc61b \uc5f0\uad6c \uc0ac\ub840\ub97c \ud568\uaed8 \ubd05\ub2c8\ub2e4.", "category": "life", "category_title": "Life", "subcategory": "Housing", "url": "stories/kabyle-house-shared-roof/index.html", "image": "media/kabyle-house-shared-roof.jpg", "alt": "\uc54c\uc81c\ub9ac \ubd81\ubd80\uc758 \uce74\ube4c \uc8fc\ud0dd \uc678\uad00 \uc2e4\uc81c \uc0ac\uc9c4. \ub3cc\ubcbd\uacfc \ubd89\uc740 \uae30\uc640\uc9c0\ubd95\uc774 \ubaa8\uc5ec \uc788\uc73c\uba70 \uc2e4\ub0b4\ub294 \ubcf4\uc774\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.", "text": "\ud55c \uc9c0\ubd95 \uc544\ub798 \uc0ac\ub78c\uacfc \uac00\ucd95\uc758 \uc790\ub9ac\uac00 \uc788\uc5c8\ub2e4 \uc54c\uc81c\ub9ac \uce74\ube4c \uc8fc\ud0dd\uc744 \uc77d\ub294 \uc791\uc740 \ub2e8\uc11c \ub3cc\uc9d1\uc758 \uc678\uad00\uacfc \uc9d1 \uc548\uc744 \uad6c\ubd84\ud55c \uc61b \uc5f0\uad6c \uc0ac\ub840\ub97c \ud568\uaed8 \ubd05\ub2c8\ub2e4. Housing \uc0dd\ud65c \uc0ac\uc9c4\uc5d0\ub294 \ubd89\uc740 \uc9c0\ubd95\uacfc \ub3cc\ubcbd\uc774 \ubaa8\uc5ec \uc788\ub2e4. \uc54c\uc81c\ub9ac \ubd81\ubd80\uc758 \uce74\ube4c \uc0ac\ub78c\ub4e4\uc774 \uc9c0\uc740 \uc9d1\ub4e4\uc774\ub2e4. \ubc16\uc5d0\uc11c \ubcf4\uba74 \ub2e8\ub2e8\ud55c \ubcbd\uacfc \uc9c0\ubd95\uc774 \uba3c\uc800 \ubcf4\uc774\uc9c0\ub9cc, \uc9d1\uc744 \uc774\ud574\ud558\ub294 \uc77c\uc740 \uadf8 \uc548\uc758 \uc790\ub9ac\ub97c \uc0dd\uac01\ud558\ub294 \ub370\uc11c\ub3c4 \uc2dc\uc791\ub41c\ub2e4. OpenStax \uad50\uc7ac\ub294 1960\ub144\ub300 \ud53c\uc5d0\ub974 \ubd80\ub974\ub514\uc678\uac00 \ubd84\uc11d\ud55c \uc804\ud1b5 \uce74\ube4c \uc8fc\ud0dd\uc758 \uc0ac\ub840\ub97c \uc18c\uac1c\ud55c\ub2e4. \uc774 \uc0ac\uc9c4\uc758 \uc9d1 \ud55c \ucc44\ub97c \uadf8\ub300\ub85c \uc870\uc0ac\ud55c \ud3c9\uba74\ub3c4\ub77c\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc678\uad00 \uc0ac\uc9c4\uacfc \uc124\uba85\uc758 \uc0ac\ub840\ub97c \ud568\uaed8 \uc77d\ub294 \uac83\uc774\ub2e4. \uc5f0\uad6c \uc0ac\ub840\uc758 \uc9d1\uc5d0\ub294 \ub0ae\uc740 \uad6c\ud68d\uc744 \ub098\ub204\ub294 \ubcbd\uc774 \uc788\uc5c8\uace0, \uadf8\ucabd\uc740 \ubc24\uc5d0 \uac00\ucd95\uc744 \ub4e4\uc774\ub294 \uc790\ub9ac\uc600\ub2e4. \uac19\uc740 \uc9c0\ubd95 \uc544\ub798\uc5d0\uc11c\ub3c4 \ubc14\ub2e5\uc744 \ub0ae\ucd94\uace0 \uad6c\ubd84\ud574 \uc11c\ub85c \ub2e4\ub978 \ud65c\ub3d9\uc758 \uc790\ub9ac\ub97c \ub9cc\ub4e4\uc5c8\ub2e4. \ub098\uba38\uc9c0 \ub354 \ub192\uace0 \ub113\uc740 \ubd80\ubd84\uc740 \uc0ac\ub78c\uc758 \uc0dd\ud65c\uc5d0 \uc4f0\uc600\ub2e4. \uc9d1\uc744 \ubc29 \uc774\ub984 \uba87 \uac1c\ub85c\ub9cc \ub098\ub204\ub294 \ub300\uc2e0 \ub192\uc774\uc640 \uacbd\uacc4\ub85c \uc77d\uc5b4 \ubcf4\uba74 \ub0b4\ubd80\uc758 \uad6c\uc131\uc774 \ub2e4\ub974\uac8c \ub290\uaef4\uc9c4\ub2e4. \uad50\uc7ac\ub294 \ubb38 \ubc18\ub300\ucabd\uc758 \ubca0\ud2c0 \uc790\ub9ac\uc640 \uadf8\uacf3\uc5d0 \ub4dc\ub294 \ube5b\ub3c4 \uc124\uba85\ud55c\ub2e4. \uc190\ub2d8 \ub4f1\uc744 \ub9de\ub294 \uc790\ub9ac\uc640 \uc5ec\ub7ec \uc0dd\ud65c \ud65c\ub3d9\uc774 \uc9d1 \uc548\uc758 \uc704\uce58\uc5d0 \ub530\ub77c \uad6c\ubcc4\ub418\uc5c8\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \ubcf4\uc774\uc9c0 \uc54a\ub294 \ub0b4\ubd80\ub97c \ub9c8\uc74c\ub300\ub85c \uadf8\ub824 \ub123\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5ec\uae30\uc11c \ubcfc \uac83\uc740 \uc9c0\ubd95\uc758 \uc7ac\ub8cc\ub9cc\uc774 \uc544\ub2c8\ub77c \uc77c\uc744 \ud558\uace0 \uc0ac\ub78c\uc744 \ub9de\ub294 \ubc29\uc2dd\ub3c4 \uc9d1\uc758 \uad6c\uc131\uc5d0 \uc601\ud5a5\uc744 \uc900\ub2e4\ub294 \uc810\uc774\ub2e4. \uc5b4\ub5a4 \uc790\ub9ac\ub97c \uc88b\ub2e4\uace0 \uc5ec\uae30\ub294\uc9c0\uc5d0\ub3c4 \uc0dd\ud65c\uc758 \uc0dd\uac01\uc774 \ub2f4\uae38 \uc218 \uc788\ub2e4. \uac74\ubb3c\uc758 \uac89\ubaa8\uc591\uc5d0\uc11c \ud55c \uacf5\uac04\uc744 \uc0c1\uc0c1\ud558\uae30 \uc27d\uc9c0\ub9cc \uc548\uc5d0\uc11c\ub294 \ub192\uc774\uc640 \uacbd\uacc4\uac00 \uc5ed\ud560\uc744 \ub098\ub20c \uc218 \uc788\ub2e4. \uc0ac\ub78c\uacfc \uac00\ucd95\uc758 \uad6c\ud68d\uc744 \ub2e4\ub974\uac8c \ub450\uc5c8\ub2e4\ub294 \uc124\uba85\uc740 \ubcbd\uacfc \ubc14\ub2e5\uc758 \uc791\uc740 \ucc28\uc774\ub97c \uc0dd\ud65c\uc758 \uad6c\uc870\ub85c \uc77d\uac8c \ud55c\ub2e4. \ubc29\uc758 \uc774\ub984\ub9cc\uc73c\ub85c \uc9d1\uc744 \uc774\ud574\ud558\ub294 \ubc29\uc2dd\uacfc \ub2e4\ub978 \ub2e8\uc11c\ub2e4. \ud568\uaed8 \uc788\ub2e4\ub294 \uac83\uacfc \uad6c\ubd84\uc774 \uc5c6\ub2e4\ub294 \uac83\uc740 \uac19\uc740 \ub9d0\uc774 \uc544\ub2c8\ub2e4. \uc0ac\uc9c4\uc740 \uc2e4\uc81c \uc678\uad00\uc744 \ubcf4\uc5ec \uc8fc\uace0 \uad50\uc7ac\uc758 \uc5f0\uad6c \uc124\uba85\uc740 \ub0b4\ubd80\uc758 \uc0ac\uc6a9\uc744 \uc54c\ub824 \uc900\ub2e4. \ub450 \uc790\ub8cc\uac00 \uc11c\ub85c \uac19\uc740 \uc815\ubcf4\ub97c \ub2f4\uc740 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubc14\uae65\uc758 \ub3cc\uacfc \uc9c0\ubd95\uc744 \ud655\uc778\ud558\ub294 \uc77c\uacfc \uc548\ucabd\uc758 \ubca0\ud2c0 \uc790\ub9ac, \ub0ae\uc740 \uad6c\ud68d\uc744 \uc774\ud574\ud558\ub294 \uc77c\uc744 \uad6c\ubd84\ud558\uba74 \uc0ac\uc9c4\uc5d0 \uc5c6\ub294 \uc138\ubd80\ub97c \ubcf4\uc558\ub2e4\uace0 \ucc29\uac01\ud558\uc9c0 \uc54a\uac8c \ub41c\ub2e4. \uc124\uba85\uc744 \ud1b5\ud574 \uc2dc\uc120\uc744 \ub113\ud790 \uc218 \uc788\ub2e4. \ubca0\ud2c0\uacfc \ube5b\uc758 \uad00\uacc4\ub97c \uc18c\uac1c\ud558\ub294 \ub300\ubaa9\uc740 \uacf5\uac04\uc744 \ud06c\uae30\uc640 \uc7ac\ub8cc \uc774\uc0c1\uc758 \uac83\uc73c\ub85c \ubcf4\uac8c \ud55c\ub2e4. \uc5b4\ub5a4 \uc77c\uc744 \ud558\ub824\uba74 \uadf8 \uc77c\uc5d0 \ub9de\ub294 \uc790\ub9ac\uac00 \ud544\uc694\ud560 \uc218 \uc788\ub2e4. \ubb3c\uac74\uc744 \uc5b4\ub514\uc5d0 \ub450\ub294\uc9c0\uc640 \ubb38\uc744 \ud1b5\ud574 \ub4e4\uc5b4\uc624\ub294 \ube5b\uc774 \uc5b4\ub5bb\uac8c \ub2ff\ub294\uc9c0\uac00 \uc0dd\ud65c\uc758 \ubc30\uce58\ub97c \ub9cc\ub4dc\ub294 \uc694\uc18c\uac00 \ub41c\ub2e4. \ub2e4\ub9cc \uc5ec\uae30\uc11c \uc2e4\uc81c \uc870\ub3c4\ub098 \uc791\uc5c5 \ub2a5\ub960\uc744 \uce21\uc815\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc2e4\ub0b4 \ubc30\uce58\uac00 \ub2e8\uc21c\ud788 \uc544\ubb34 \uacf3\uc5d0\ub098 \ub0a8\uc740 \uac00\uad6c\ub97c \ub193\uc740 \uacb0\uacfc\ub9cc\uc740 \uc544\ub2c8\ub77c\ub294 \uc9c8\ubb38\uc744 \uc5bb\uc744 \uc218 \uc788\ub2e4. \uc870\ub9ac\uc640 \uc218\ub0a9, \uc77c\uacfc \uc190\ub2d8 \ub9de\uc774\uc5d0\ub294 \uc11c\ub85c \ub2e4\ub978 \uc694\uad6c\uac00 \uc788\ub2e4. \uc5b4\ub5a4 \uc790\ub9ac\ub97c \uc88b\ub2e4\uace0 \uc5ec\uacbc\ub294\uc9c0\uc5d0\ub3c4 \uacf5\ub3d9\uccb4\uc758 \uc0dd\uac01\uc774 \ub4e4\uc5b4\uac08 \uc218 \uc788\ub2e4. \uc9d1\uc758 \ud3c9\uba74\uc740 \uc0dd\ud65c\uc744 \ub2f4\uc73c\uba74\uc11c \uadf8 \uc0dd\ud65c\uc758 \uad00\uacc4\ub97c \ub098\ud0c0\ub0b4\ub294 \ud615\uc2dd\uc774\uae30\ub3c4 \ud558\ub2e4. \uad50\uc7ac\ub294 1960\ub144\ub300 \ud53c\uc5d0\ub974 \ubd80\ub974\ub514\uc678\uac00 \ubd84\uc11d\ud55c \uc804\ud1b5 \uce74\ube4c \uc8fc\ud0dd\uc744 \uc0ac\ub840\ub85c \ub4e0\ub2e4. \ud2b9\uc815\ud55c \uc2dc\uc810\uc758 \uc5f0\uad6c\uc640 \ud574\uc11d\uc774\uc9c0 \uc54c\uc81c\ub9ac \ubd81\ubd80\uc758 \ubaa8\ub4e0 \ud604\uc7ac \uc8fc\ud0dd\uc744 \uc870\uc0ac\ud55c \ud45c\uc900 \uc124\uba85\uc774 \uc544\ub2c8\ub2e4. \uc5f0\uad6c\uc790\uc758 \uc9c8\ubb38\uacfc \uadf8\ub54c \uc0b4\ud540 \ub300\uc0c1\uc758 \ubc94\uc704\ub97c \ub0a8\uaca8 \ub450\uc5b4\uc57c \ud55c\ub2e4. \uc9d1 \ud55c \ucc44\uc758 \ubaa8\ub378\uc744 \ud558\ub098\uc758 \ubb38\ud654 \uc804\uccb4\uc640 \uac19\uac8c \ub193\uc73c\uba74 \ucc28\uc774\uac00 \uc0ac\ub77c\uc9c4\ub2e4. \ub530\ub77c\uc11c \uc624\ub298 \uadf8 \uc9c0\uc5ed\uc5d0 \uac00\uba74 \uc0ac\uc9c4\uacfc \ub611\uac19\uc740 \ub0b4\ubd80\uac00 \uc5b4\ub514\uc11c\ub098 \ubcf4\uc77c \uac83\uc774\ub77c\uace0 \uae30\ub300\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc8fc\uac70\ub294 \uc2dc\ub300\uc640 \uc0ac\ud68c\uc758 \ubcc0\ud654\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc61b \uc5f0\uad6c\uc758 \uac00\uce58\ub294 \ud604\uc7ac\ub97c \uba48\ucd94\uac8c \ud558\ub294 \ub370\ubcf4\ub2e4 \uc5b4\ub5a4 \uad00\uacc4\ub97c \uad00\ucc30\ud588\ub294\uc9c0 \uc54c\uac8c \ud558\ub294 \ub370 \uc788\ub2e4. \uc790\ub8cc\uc758 \uc2dc\uac04\ub3c4 \uac74\ubb3c\uc758 \uc7ac\ub8cc\ucc98\ub7fc \ud568\uaed8 \uc77d\uc744 \uc815\ubcf4\ub2e4. \uc678\uad00\uc758 \ub3cc\uc744 \ubcf8 \ub2e4\uc74c \ub0b4\ubd80\uc5d0\uc11c \uc77c\uc5b4\ub0ac\ub358 \ud65c\ub3d9\uc744 \uc124\uba85\uacfc \uc5f0\uacb0\ud574 \ubcf4\uc790. \uadf8 \ud65c\ub3d9\uc774 \ubaa8\ub450 \uc0ac\uc9c4\uc5d0 \uc9c1\uc811 \ucc0d\ud614\ub2e4\uace0 \uc0dd\uac01\ud558\uc9c0 \uc54a\uc73c\uba74 \ubc14\uae65\uacfc \uc548\ucabd\uc758 \uc11c\ub85c \ub2e4\ub978 \uc790\ub8cc\ub97c \ud568\uaed8 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4. \uc8fc\uac70\ub97c \uc77d\ub294 \uc77c\uc740 \ubc29\uc758 \uac1c\uc218\ub97c \ub9de\ud788\ub294 \uc2dc\ud5d8\ubcf4\ub2e4 \uc0ac\ub78c\uc774 \ubb34\uc5c7\uc744 \ud558\uba70 \uc0b4\uc558\ub294\uc9c0 \ubb3b\ub294 \uacfc\uc815\uc5d0 \uac00\uae5d\ub2e4. \uc774\ub54c \uac00\ucd95\uacfc \uac19\uc740 \uc9c0\ubd95 \uc544\ub798 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uace7 \ubd88\ud3b8\ud558\uac70\ub098 \ube44\uc704\uc0dd\uc801\uc774\uc5c8\ub2e4\ub294 \ud3c9\uac00\ub85c \ubc14\uafc0 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \ud655\uc778\ub418\uc9c0 \uc54a\uc740 \uc0dd\ud65c\uc758 \uc0c1\ud0dc\ub97c \uc624\ub298\uc758 \uac10\uac01\ub9cc\uc73c\ub85c \ud310\uc815\ud558\uc9c0 \uc54a\ub294 \uac83\uc774\ub2e4. \ub0ae\uc740 \uad6c\ud68d\uacfc \ub192\uc740 \uad6c\ud68d, \ube5b\uacfc \ubca0\ud2c0\uc758 \uc790\ub9ac\ub97c \ub530\ub77c\uac00\ub2e4 \ubcf4\uba74 \ub0af\uc120 \uc9d1\uc774 \ud558\ub098\uc758 \uc0dd\ud65c \uc870\uc9c1\uc73c\ub85c \ub2e4\uac00\uc628\ub2e4. \ud070 \uc9c0\ubd95 \uc544\ub798\uc5d0\ub294 \uc5ec\ub7ec \uad00\uacc4\uc758 \uacbd\uacc4\uac00 \uc788\uc5c8\ub2e4. \uc774\uac83\uc740 \ud2b9\uc815 \uc2dc\uae30\uc758 \uc804\ud1b5 \uc8fc\ud0dd \uc5f0\uad6c \uc0ac\ub840\ub2e4. \uc624\ub298\ub0a0\uc758 \ubaa8\ub4e0 \uce74\ube4c \uac00\uc815\uc774 \uac19\uc740 \uacf5\uac04\uc5d0\uc11c \uac19\uc740 \uaddc\uce59\uc73c\ub85c \uc0b0\ub2e4\uace0 \ub113\ud600 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc9d1\uc758 \uc4f0\uc784\uc740 \uc2dc\uac04\uacfc \uc0ac\ub78c\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c4\ub2e4. \uadf8\ub7fc\uc5d0\ub3c4 \uc774\ub7f0 \uc0ac\ub840\ub294 \uc775\uc219\ud55c \uc9d1\uc744 \ub2e4\uc2dc \ubcf4\ub294 \ubc29\ubc95\uc744 \uc900\ub2e4. \uc65c \uc774 \uc790\ub9ac\ub294 \ub192\uace0 \uc800 \uc790\ub9ac\ub294 \ub0ae\uc744\uae4c, \uc65c \uc190\ub2d8\uc744 \uc774\ucabd\uc5d0 \uc549\ud790\uae4c. \ub3cc\ubcbd\uacfc \uc9c0\ubd95 \uc548\uc5d0\ub294 \uc7ac\ub8cc\ubfd0 \uc544\ub2c8\ub77c \uc11c\ub85c \ub2e4\ub978 \uc0dd\ud65c\uc744 \ud55c \uacf5\uac04\uc5d0 \ub193\uc73c\ub824\ub358 \uc120\ud0dd\ub3c4 \ub4e4\uc5b4 \uc788\ub2e4."}, {"id": "lock-green-knot", "title": "\uc61b \uc5f4\uc1e0\uc5d0\ub3c4 \ucd08\ub85d\uc0c9 \ub9e4\ub4ed\uc774 \ub2ec\ub824 \uc788\uc5c8\ub2e4", "summary": "\uaf43\ubb34\ub2ac \uc790\ubb3c\uc1e0\uc640 \ub179\uc0c9 \ub9e4\ub4ed\uc774 \ub2ec\ub9b0 \uc5f4\uc1e0\ub97c \ud568\uaed8 \ubd05\ub2c8\ub2e4.", "category": "life", "category_title": "Life", "subcategory": "Housing", "url": "stories/lock-green-knot/index.html", "image": "media/lock-green-knot.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc790\ubb3c\uc1e0, \uc5f4\uc1e0 \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc61b \uc5f4\uc1e0\uc5d0\ub3c4 \ucd08\ub85d\uc0c9 \ub9e4\ub4ed\uc774 \ub2ec\ub824 \uc788\uc5c8\ub2e4 \uc7a0\uadf8\ub294 \ubb3c\uac74\uc5d0\ub3c4 \uafb8\ubc08\uc740 \ub0a8\uc558\ub2e4 \uaf43\ubb34\ub2ac \uc790\ubb3c\uc1e0\uc640 \ub179\uc0c9 \ub9e4\ub4ed\uc774 \ub2ec\ub9b0 \uc5f4\uc1e0\ub97c \ud568\uaed8 \ubd05\ub2c8\ub2e4. Housing \uc0dd\ud65c \uc5f4\uc1e0\ub97c \ucc3e\ub290\ub77c \uac00\ubc29 \uc548\uc744 \ub4a4\uc801\uc778 \uacbd\ud5d8\uc774 \uc788\ub2e4\uba74, \uc5f4\uc1e0\uace0\ub9ac \ud558\ub098\uc5d0\ub3c4 \ucde8\ud5a5\uc774 \ub4e4\uc5b4\uac04\ub2e4\ub294 \ub9d0\uc744 \uc774\ud574\ud560 \uac83\uc774\ub2e4. \uc798 \ubcf4\uc774\ub294 \uc0c9\uc744 \uace0\ub974\uae30\ub3c4 \ud558\uace0, \ub9c8\uc74c\uc5d0 \ub4dc\ub294 \uc791\uc740 \uc7a5\uc2dd\uc744 \ub2ec\uae30\ub3c4 \ud55c\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \uc61b \uc790\ubb3c\uc1e0\uc640 \uc5f4\uc1e0\ub97c \ubcf4\uba74 \uadf8\ub7f0 \uc624\ub298\uc758 \uc2b5\uad00\uc774 \ubb38\ub4dd \ub5a0\uc624\ub978\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc5d0 \ub530\ub974\uba74 \uc5f4\uc1e0 \ub05d\uc5d0\ub294 \ub179\uc0c9 \ub9e4\ub4ed\uc774 \ub2ec\ub824 \uc788\ub2e4. \uc791\uc740 \uc7a0\uae08 \ub3c4\uad6c\uc5d0\ub3c4 \uc0c9\uc744 \ubcf4\ud0e0 \uac83\uc774\ub2e4. \uc774 \ud55c \uc30d\uc740 \uc601\uce5c\uc655\ube44\uc758 \uc720\ud488\uc73c\ub85c \uc804\ud574\uc9c0\ub294 \ubb3c\uac74\uc774\ub2e4. \uc5ec\uae30\uc11c \ub208\uc5ec\uaca8\ubcfc \ub9d0\uc740 \u2018\uc804\ud574\uc9c0\ub294\u2019\uc774\ub2e4. \ub204\uac00 \uc5b8\uc81c \uc5b4\ub290 \uc0c1\uc790\ub97c \uc7a0\uac14\ub294\uc9c0\uae4c\uc9c0 \ud655\uc815\ub41c \uc7a5\uba74\uc73c\ub85c \ubc14\uafb8\uc5b4 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ud655\uc778\ub418\ub294 \uac83\uc740 \ud45c\uba74\uc758 \uc7a5\uc2dd\uc774\ub2e4. \uc790\ubb3c\uc1e0 \uc55e\uba74\uc5d0\ub294 \ub465\uadfc \ubb34\ub2ac\uc640 \uaf43\ubb34\ub2ac\uac00 \uc74c\uac01\ub418\uc5b4 \uc788\ub2e4. \uc74c\uac01\uc740 \ubc14\ud0d5\uc744 \ud30c\uc11c \uc120\uc774\ub098 \ubb34\ub2ac\ub97c \ub098\ud0c0\ub0b4\ub294 \ubc29\uc2dd\uc774\ub2e4. \uc791\uc544\uc11c \uadf8\ub0e5 \uc9c0\ub098\uce60 \ubb3c\uac74\uc5d0\ub3c4 \ube48 \ud45c\uba74\uc744 \uadf8\ub300\ub85c \ub450\uc9c0 \uc54a\uc558\ub2e4. \uc5f4\uc1e0 \ub05d\uc758 \ub9e4\ub4ed\uc740 \uc790\ubb3c\uc1e0\uc758 \uc0c8\uae34 \ubb34\ub2ac\uc640 \ub2e4\ub978 \ubc29\ubc95\uc73c\ub85c \ubb3c\uac74\uc744 \uafb8\ubbfc\ub2e4. \ub2e8\ub2e8\ud55c \uae08\uc18d\uc5d0\ub294 \ud30c\uc778 \uc120\uc774, \ub05d\ubd80\ubd84\uc5d0\ub294 \ub179\uc0c9 \ub9e4\ub4ed\uc774 \ubd99\ub294\ub2e4. \ud55c \uc870\ub97c \uc774\ub8e8\uba74\uc11c\ub3c4 \uc7ac\ub8cc\uc758 \ub290\ub08c\uc740 \ub2e4\ub974\ub2e4. \ub9e4\ub4ed\uc774 \uc190\uc5d0 \uc7a1\uae30 \ud3b8\ud588\uc744\uc9c0, \uba40\ub9ac\uc11c \ucc3e\uae30 \uc26c\uc6e0\uc744\uc9c0 \uc0c1\uc0c1\ud574 \ubcfc \uc218\ub294 \uc788\ub2e4. \uadf8\ub7ec\ub098 \ubc15\ubb3c\uad00 \uc124\uba85\uc740 \uadf8 \ubaa9\uc801\uae4c\uc9c0 \uc815\ud574 \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc624\ub298\uc758 \uc5f4\uc1e0\uace0\ub9ac\uc640 \ub2ee\uc558\ub2e4\ub294 \uc0dd\uac01\uc740 \uc6b0\ub9ac\uc758 \ube44\uad50\ub85c \ub0a8\uaca8 \ub450\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc790\ubb3c\uc1e0\uc640 \uc5f4\uc1e0\ub294 \uc11c\ub85c \ub2e4\ub978 \uc5ed\ud560\uc744 \ub9e1\uc9c0\ub9cc \ud55c \uc870\ub85c \uc774\ud574\ub41c\ub2e4. \uc5f4\uc1e0\ub9cc \ub0a8\uc544 \uc788\uc73c\uba74 \ubb34\uc5c7\uc744 \uc5f4\uc5c8\ub294\uc9c0 \uad81\uae08\ud558\uace0, \uc790\ubb3c\uc1e0\ub9cc \uc788\uc73c\uba74 \uc5b4\ub5bb\uac8c \uc5f4\uc5c8\ub294\uc9c0 \ubb3b\uac8c \ub41c\ub2e4. \ud568\uaed8 \uc18c\uac1c\ub41c\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uadf8 \uad00\uacc4\ub97c \ubcfc \uc218 \uc788\uac8c \ud55c\ub2e4. \ub2e4\ub9cc \uc774 \uc0ac\uc9c4\uc73c\ub85c \ub0b4\ubd80 \uad6c\uc870\uc758 \ubaa8\ub4e0 \uc791\ub3d9\uc744 \ud655\uc778\ud558\uac70\ub098 \uc815\ud655\ud55c \uac1c\ud3d0 \uc808\ucc28\ub97c \uc7ac\ud604\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uba3c\uc800 \ub450 \ubb3c\uac74\uc774 \uac01\uac01 \uc5b4\ub5a4 \ud615\ud0dc\uc778\uc9c0 \uc0b4\ud3b4\ubcf4\uace0 \uc774\ud6c4 \ud45c\uba74\uc758 \uc7a5\uc2dd\uc73c\ub85c \uc2dc\uc120\uc744 \uc62e\uaca8 \ubcf4\uc790. \uae08\uc18d\uc758 \ub369\uc5b4\ub9ac\uc640 \uc5f4\uc1e0 \ub05d\uc758 \ubd80\ub4dc\ub7ec\uc6b4 \ub9e4\ub4ed\uc740 \ub208\uc5d0 \ub2e4\ub978 \uc778\uc0c1\uc744 \uc900\ub2e4. \uae30\ub2a5\uc774 \ub2e4\ub978 \ubd80\ud488\ub4e4\uc774 \ud55c \ubb36\uc74c\uc73c\ub85c \uc0ac\uc6a9\ub420 \uc218 \uc788\ub2e4\ub294 \uc810\uacfc, \uadf8 \uac01\uac01\uc5d0 \uafb8\ubc08\uc758 \uc790\ub9ac\uac00 \uc788\uc5c8\ub2e4\ub294 \uc810\uc744 \ud568\uaed8 \ubcfc \uc218 \uc788\ub2e4. \uc74c\uac01\ud55c \ub465\uadfc \ubb34\ub2ac\uc640 \uaf43\ubb34\ub2ac\ub294 \ubc14\ud0d5\uc744 \ud30c\uc11c \ub9cc\ub4e0\ub2e4. \uc885\uc774\uc5d0 \uadf8\ub9b0 \uc120\uacfc \ub2ec\ub9ac \uc2e4\uc81c \ud45c\uba74\uc758 \ub192\ub0ae\uc774\uac00 \uc0dd\uae34\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \uc870\uba85\uacfc \ubc29\ud5a5\uc5d0 \ub530\ub77c \uc120\uc774 \ub354 \uc120\uba85\ud558\uac70\ub098 \ud76c\ubbf8\ud558\uac8c \ubcf4\uc77c \uc218 \uc788\ub294 \uc774\uc720\ub3c4 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uc7a5\uc2dd\uc758 \uc774\ub984\uc744 \uc54c\uace0 \ub098\uba74 \ub2e8\uc21c\ud788 \ubc18\uc9dd\uc774\ub294 \uae08\uc18d\uc774\ub77c\uace0 \uc9c0\ub098\uce58\uc9c0 \uc54a\uac8c \ub41c\ub2e4. \uadf8\ub807\uc9c0\ub9cc \uc0ac\uc9c4\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uac00\uacf5 \ub3c4\uad6c\uc640 \uc81c\uc791\uc790\uc758 \uc190\uc744 \ud2b9\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uae30\uad00\uc774 \uc124\uba85\ud55c \uae30\ubc95\uacfc \uc2e4\uc81c\ub85c \ubcf4\uc774\ub294 \uc120\uc744 \ud568\uaed8 \uc77d\ub294 \uac83\uc774 \uba3c\uc800\ub2e4. \uc791\uc740 \ubb3c\uac74\uc758 \ud45c\uba74\uc5d0 \ubb34\ub2ac\ub97c \ub123\uc5c8\ub2e4\ub294 \uc120\ud0dd\uc740 \uc7a0\uadf8\ub294 \uae30\ub2a5 \uc678\uc5d0\ub3c4 \ubcf4\ub294 \uc990\uac70\uc6c0\uc744 \uace0\ub824\ud588\uc74c\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \uc4f0\uc774\ub294 \ubb3c\uac74\uc758 \uc544\ub984\ub2e4\uc6c0\uc740 \ud06c\uae30\uc640 \ube44\ub840\ud558\uc9c0 \uc54a\ub294\ub2e4. \ub179\uc0c9 \ub9e4\ub4ed\uc740 \uae08\uc18d\uacfc \ub2e4\ub978 \uc0c9\uacfc \uc9c8\uac10\uc744 \ub354\ud55c\ub2e4. \uc190\uc73c\ub85c \uc7a1\uac70\ub098 \ubb3c\uac74\uc744 \ucc3e\uc744 \ub54c \uc5b4\ub5a4 \ub3c4\uc6c0\uc774 \ub418\uc5c8\uc744\uc9c0 \uc0dd\uac01\ud574 \ubcfc \uc218 \uc788\uc9c0\ub9cc, \uadf8\uac83\uc774 \uc81c\uc791\uc758 \ud655\uc778\ub41c \uc774\uc720\ub77c\uace0 \ub2e8\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc624\ub298\uc758 \uc5f4\uc1e0\uace0\ub9ac\ub97c \ub5a0\uc62c\ub9ac\ub294 \uac83\uc740 \uac10\uc0c1\uc744 \ub3d5\ub294 \ube44\uad50\ub2e4. \uc61b \uc0ac\uc6a9\uc790\uc758 \uc124\uba85\uc744 \uc2e4\uc81c\ub85c \ub4e4\uc740 \uac83\ucc98\ub7fc \uc4f0\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc815\ud655\ud558\ub2e4. \uc774 \uad6c\ubd84\uc744 \uc54c\uba74 \uc0c1\uc0c1\ud558\ub294 \uc990\uac70\uc6c0\uc744 \uc5c6\uc568 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \ubb34\uc5c7\uc774 \uc790\ub8cc\uc758 \uc124\uba85\uc774\uace0 \ubb34\uc5c7\uc774 \uc9c0\uae08 \uad00\ub78c\uc790\uc758 \uc0dd\uac01\uc778\uc9c0 \ub098\ub204\uc5b4 \ub450\uba74 \ub41c\ub2e4. \ub9e4\ub4ed\uc758 \uc0c9\uc744 \uc54c\uc544\ubcf4\uace0 \ud45c\uba74\uc758 \ubb38\uc591\uacfc \ub098\ub780\ud788 \ubcf4\ub294 \uac83\ub9cc\uc73c\ub85c \ud55c \uc870\uc758 \uad6c\uc131\uc774 \ub354 \uc120\uba85\ud574\uc9c4\ub2e4. \uae30\ub2a5\uc744 \ub9e1\ub294 \ub2e8\ub2e8\ud55c \uae08\uc18d\uacfc \uc190\uc744 \uac70\uce5c \ub048\uc774 \uc11c\ub85c \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \ud45c\uc815\uc744 \ub9cc\ub4e4\uc5c8\ub2e4. \uc601\uce5c\uc655\ube44\uc758 \uc720\ud488\uc73c\ub85c \uc804\ud574\uc9c4\ub2e4\ub294 \uc124\uba85\uc740 \ub204\uac00 \uc5b8\uc81c \uc7a0\uac14\ub2e4\ub294 \uc774\uc57c\uae30\uc640 \ub2e4\ub974\ub2e4. \uc5b4\ub5a4 \uad00\uacc4\ub85c \uc54c\ub824\uc838 \uc654\ub294\uc9c0 \ud45c\uc2dc\ud55c \ub9d0\uc774\ub2e4. \uc624\ub798\ub41c \ubb3c\uac74\uc744 \uc18c\uac1c\ud560 \ub54c \uc774 \ud45c\ud604\uc744 \uc720\uc9c0\ud558\ub294 \uac83\uc740 \ubd88\ud544\uc694\ud55c \ub9dd\uc124\uc784\ubcf4\ub2e4 \uc790\ub8cc\uc758 \uc815\ud655\uc131\uc744 \uc9c0\ud0a4\ub294 \uc77c\uc5d0 \uac00\uae5d\ub2e4. \ud655\uc2e4\ud55c \ud45c\uba74\uacfc \uc54c\ub824\uc9c4 \uc774\ub825\uc758 \uc815\ub3c4\ub97c \ud568\uaed8 \ubcf4\ub294 \uac83\uc774\ub2e4. \ub204\uad70\uac00\uc758 \ube44\ubc00 \uc0c1\uc790\ub098 \uadf9\uc801\uc778 \uc0ac\uac74\uc744 \uc0c8\ub85c \ub9cc\ub4e4\uc5b4\uc57c\ub9cc \uc790\ubb3c\uc1e0\uac00 \ud765\ubbf8\ub85c\uc6cc\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5f4\uc1e0 \ub05d\uc5d0 \ub9e4\ub4ed\uc744 \ub354\ud558\uace0 \uc791\uc740 \uba74\uc5d0 \uaf43\uc744 \uc0c8\uae34 \ubb3c\uac74\uc740 \uadf8 \uc790\uccb4\ub85c \uc0dd\ud65c\uc758 \uc120\ud0dd\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ubb34\uc5c7\uc744 \uc7a0\uac14\ub294\uc9c0 \ubaa8\ub974\ub294 \ube48\uce78\uc744 \ub0a8\uae30\uba74\uc11c\ub3c4, \uc0ac\ub78c\ub4e4\uc774 \uc7a0\uadf8\uace0 \ubcf4\uad00\ud558\ub294 \ub3c4\uad6c\ub97c \uc5b4\ub5bb\uac8c \uafb8\uba84\ub294\uc9c0\ub294 \ucc9c\ucc9c\ud788 \uc77d\uc744 \uc218 \uc788\ub2e4. \uc0c1\uc790\ub97c \uc5f4\uc5b4 \uc548\uc758 \ubcf4\ubb3c\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc774\uc57c\uae30\ub294 \uc544\ub2c8\ub2e4. \uc774 \uc790\ubb3c\uc1e0\uac00 \uc9c0\ud0a4\ub358 \ubb3c\uac74\uc740 \ud655\uc778\ud558\uc9c0 \ubabb\ud588\ub2e4. \ub300\uc2e0 \uc7a0\uadf8\ub294 \ub3c4\uad6c \uc790\uccb4\uc5d0\ub3c4 \ubcf4\ub294 \uc990\uac70\uc6c0\uc774 \uc788\uc5c8\ub2e4\ub294 \uac83\uc744 \ud45c\uba74\uacfc \ub9e4\ub4ed\uc5d0\uc11c \ubc1c\uacac\ud55c\ub2e4. \uc0ac\uc9c4\uc744 \ub2e4\uc2dc \ubcf4\uba74 \ucee4\ub2e4\ub780 \uc7a5\uc2dd\ubcf4\ub2e4 \uc791\uc740 \uc120\uc774 \uba3c\uc800 \ub208\uc5d0 \ub4e4\uc5b4\uc62c \uc218 \uc788\ub2e4. \uadf8 \uc606\uc5d0 \ub193\uc600\uc744 \uc5f4\uc1e0\uc758 \ucd08\ub85d\uc0c9\uae4c\uc9c0 \ub5a0\uc62c\ub9ac\uba74, \uc7a0\uae08\uc7a5\uce58\ub294 \uae30\ub2a5\ub9cc \ub0a8\uc740 \uae08\uc18d \ubd80\ud488\uc5d0\uc11c \uc870\uae08 \ub2e4\ub978 \uc5bc\uad74\uc744 \uc5bb\ub294\ub2e4. \uc61b \uc0dd\ud65c\uc758 \ucde8\ud5a5\uc740 \uc774\ub807\uac8c \uc791\uc740 \uacf3\uc5d0\ub3c4 \ub0a8\uc544 \uc788\ub2e4."}, {"id": "maehwa-portable-toilet", "title": "\uad81\uad90\uc758 \uc791\uc740 \uc0c1\uc790\uc5d0\ub294 \uc0dd\ud65c\uc758 \ud544\uc694\uac00 \ub2f4\uacbc\ub2e4", "summary": "\uc758\uc790\ucc98\ub7fc\ub3c4 \uc0c1\uc790\ucc98\ub7fc\ub3c4 \ubcf4\uc774\ub294 \ubb3c\uac74. \uc774\ub984\uacfc \uc4f0\uc784\uc744 \uc54c\uace0 \ub098\uba74 \uc61b \uc0dd\ud65c\uc758 \ub2e4\ub978 \uba74\uc774 \ubcf4\uc785\ub2c8\ub2e4.", "category": "life", "category_title": "Life", "subcategory": "Housing", "url": "stories/maehwa-portable-toilet/index.html", "image": "media/maehwa-portable-toilet.jpg", "alt": "\uc9c1\ubb3c\ub85c \uc2fc \ub098\ubb34\ud2c0\uacfc \uc704\ucabd \uad6c\uba4d\uc774 \ubcf4\uc774\ub294 \uc655\uc2e4 \uc774\ub3d9\uc2dd \ubcc0\uae30 \ub9e4\ud654\ud2c0", "text": "\uad81\uad90\uc758 \uc791\uc740 \uc0c1\uc790\uc5d0\ub294 \uc0dd\ud65c\uc758 \ud544\uc694\uac00 \ub2f4\uacbc\ub2e4 \uc774\ub3d9\uc2dd \uc6a9\ubcc0\uae30 \ub9e4\ud654\ud2c0\uc758 \uad6c\uc870\ub97c \ub4e4\uc5ec\ub2e4\ubcf4\ub2e4 \uc758\uc790\ucc98\ub7fc\ub3c4 \uc0c1\uc790\ucc98\ub7fc\ub3c4 \ubcf4\uc774\ub294 \ubb3c\uac74. \uc774\ub984\uacfc \uc4f0\uc784\uc744 \uc54c\uace0 \ub098\uba74 \uc61b \uc0dd\ud65c\uc758 \ub2e4\ub978 \uba74\uc774 \ubcf4\uc785\ub2c8\ub2e4. Housing \uc0dd\ud65c \uad81\uad90\uc758 \uc0dd\ud65c\uc744 \uc0c1\uc0c1\ud558\uba74 \ud070 \uce68\uc804\uacfc \ud654\ub824\ud55c \uac00\uad6c\ubd80\ud130 \ub5a0\uc624\ub974\uae30 \uc27d\ub2e4. \ud558\uc9c0\ub9cc \uc0dd\ud65c\uc744 \uac00\ub2a5\ud558\uac8c \ud558\ub294 \uac83\uc740 \uba4b\uc9c4 \ubb3c\uac74\ub9cc\uc774 \uc544\ub2c8\ub2e4. \ub9e4\uc77c \ud574\uacb0\ud574\uc57c \ud558\ub294 \uc791\uc740 \ud544\uc694\ub3c4 \uc788\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \u300c\ub9e4\ud654\ud2c0\u300d\uc740 \uadf8\ub7f0 \uba74\uc744 \ubcf4\uc5ec\uc900\ub2e4. \uc9c1\uc721\uba74\uccb4\uc758 \ub098\ubb34 \ubab8\uccb4\uc5d0 \ucc9c\uc744 \uc50c\uc6e0\uace0, \uc717\uba74\uc5d0\ub294 \uae34 \uad6c\uba4d\uc774 \ub098 \uc788\ub2e4. \ud06c\uc9c0 \uc54a\uc740 \uac00\uad6c\ucc98\ub7fc \ubcf4\uc774\ub294 \uc774 \ubb3c\uac74\uc740 \uc655\uc2e4 \uc804\uc6a9\uc758 \uc774\ub3d9\uc2dd \uc6a9\ubcc0\uae30\uc600\ub2e4. \uc774\ub984\ub9cc \ub4e3\uace0 \uaf43\uc744 \uc7a5\uc2dd\ud558\ub294 \ud2c0\uc744 \ub5a0\uc62c\ub838\ub2e4\uba74 \uc4f0\uc784\uc774 \uaf64 \ub2e4\ub974\uac8c \ub290\uaef4\uc9c8 \uac83\uc774\ub2e4. \uc774 \ub9e4\ud654\ud2c0\uc740 \ubc30\uc124\ubb3c\uc744 \ubc1b\ub294 \uc6a9\uae30\ub97c \ub123\uace0 \ube84 \uc218 \uc788\ub3c4\ub85d \uace0\uc548\ub418\uc5c8\ub2e4\uace0 \ud55c\ub2e4. \uc0ac\uc6a9\uc790\uac00 \uc549\ub294 \ubd80\ubd84\uacfc \uc548\ucabd\uc758 \uc6a9\uae30\ub97c \ub098\ub204\uc5b4 \uc0dd\uac01\ud55c \uad6c\uc870\ub2e4. \uc717\uba74\uc758 \uad6c\uba4d\ub9cc \uc788\ub294 \ub2e8\uc21c\ud55c \uc0c1\uc790\ub3c4 \uc544\ub2c8\ub2e4. \uc544\ub798 \uc591\uc606\uc5d0\ub294 \ubc1c\ud310\uc774 \ub9c8\ub828\ub418\uc5b4 \uc788\uace0, \uc88c\ub300 \uc717\ubd80\ubd84\uc5d0\ub294 \ub4f1\ubc1b\uce68\uc744 \uace0\uc815\ud558\uae30 \uc704\ud55c \ud648\ub3c4 \ub0a8\uc544 \uc788\ub2e4. \uc124\uba85\uc744 \uc77d\uc73c\uba70 \uc0ac\uc9c4\uc744 \ub2e4\uc2dc \ubcf4\uba74 \uae30\ub2a5\uc5d0 \ud544\uc694\ud55c \ubd80\ubd84\ub4e4\uc774 \ud558\ub098\uc529 \ubcf4\uc778\ub2e4. \uc6c0\uc9c1\uc77c \uc218 \uc788\ub2e4\ub294 \uc810\ub3c4 \uc774 \ubb3c\uac74\uc758 \uc131\uaca9\uc744 \uc54c\ub824\uc900\ub2e4. \ubc29 \uc548\uc5d0\uc11c \uc4f0\ub294 \uac00\uad6c\ucc98\ub7fc \uc0ac\uc6a9\ud558\uba74\uc11c, \uc548\ucabd \uc6a9\uae30\ub97c \ub2e4\ub8e8\uace0 \ud544\uc694\uc5d0 \ub530\ub77c \uc704\uce58\ub97c \uc62e\uae38 \uc218 \uc788\ub294 \ubc29\uc2dd\uc774\uc5c8\ub2e4. \uc624\ub298\uc758 \ubc30\uad00 \uc2dc\uc124\uacfc\ub294 \ub2e4\ub978 \ubc29\ubc95\uc73c\ub85c \uc0dd\ud65c\uc758 \ubb38\uc81c\ub97c \ud574\uacb0\ud55c \uac83\uc774\ub2e4. \ubc15\ubb3c\uad00\uc5d0\ub294 \uac19\uc740 \ub9e4\ud654\ud2c0\uc774\ub77c\ub294 \uc774\ub984\uc758 \uccad\ub3d9\uc81c \uc774\ub3d9\uc2dd \uc6a9\ubcc0\uae30\ub3c4 \uc788\ub2e4. \uc124\uba85\uc5d0\ub294 \ub0b4\ubd80\uc5d0 \uc7ac\ub97c \ub2f4\uc544 \uc18c\ub9ac\uc640 \ub0c4\uc0c8\ub97c \uc904\uc774\ub824 \ud588\ub2e4\uace0 \ub098\uc628\ub2e4. \ub450 \ubb3c\uac74\uc744 \ubcf4\uba74 \uc6a9\ubcc0\uc744 \ubc1b\ub294 \uae30\ub2a5\ubfd0 \uc544\ub2c8\ub77c \uc0ac\uc6a9 \ub4a4\uc758 \ucc98\ub9ac, \uc8fc\ubcc0\uc5d0 \uc8fc\ub294 \uc601\ud5a5\uc744 \uc0dd\uac01\ud588\ub2e4\ub294 \uac83\uc744 \uc54c \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ud55c \uc720\ubb3c\uc758 \uc124\uba85\uc744 \ubaa8\ub4e0 \uc655\uc2e4 \uc6a9\ubcc0\uae30\uc5d0 \ub611\uac19\uc774 \uc801\uc6a9\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc7ac\ub8cc\uc640 \uad6c\uc870\uac00 \ub2e4\ub978 \ubb3c\uac74\uc740 \uac01\uac01\uc758 \uae30\ub85d\uc744 \ub530\ub77c \ubcf4\uc544\uc57c \ud55c\ub2e4. \ub204\uac00 \uc5b8\uc81c \uc5b4\ub290 \ubc29\uc5d0\uc11c \uc37c\ub294\uc9c0, \uc8fc\ubcc0 \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub5a4 \ub9d0\uc744 \ud588\ub294\uc9c0\ub294 \uc5ec\uae30\uc758 \uc18c\uc7a5\ud488 \uc124\uba85\ub9cc\uc73c\ub85c \uc54c \uc218 \uc5c6\ub2e4. \uadf8\ub7f0 \uc7a5\uba74\uc744 \ub367\ubd99\uc774\uc9c0 \uc54a\uc544\ub3c4 \ub0a8\uc544 \uc788\ub294 \uad6c\uc870\ub9cc\uc73c\ub85c \uc0dd\ud65c\uc758 \uace0\ubbfc\uc744 \uc9d0\uc791\ud560 \uc218 \uc788\ub2e4. \uad81\uad90\uc744 \ud070 \uc758\uc2dd\uacfc \ud654\ub824\ud55c \uc637\uc758 \uc7a5\uc18c\ub85c\ub9cc \ubcf4\uba74 \uc77c\uc0c1\uc801\uc778 \ubab8\uc758 \ud65c\ub3d9\uc740 \uc798 \ub5a0\uc624\ub974\uc9c0 \uc54a\ub294\ub2e4. \uc774\ub3d9\uc2dd \uc6a9\ubcc0\uae30\ub294 \uadf8\ub7f0 \ube48\uc790\ub9ac\ub97c \ubcf4\uc5ec \uc900\ub2e4. \ub204\uad70\uac00 \uc549\uace0 \uc77c\uc5b4\ub098\uba70 \ub0b4\ubd80 \uc6a9\uae30\ub97c \ub2e4\ub8e8\uc5b4\uc57c \ud588\ub358 \ubb3c\uac74\uc774\ub2e4. \ud2b9\ubcc4\ud55c \uc2e0\ubd84\uc758 \uc0dd\ud65c\uc5d0\ub3c4 \ubc18\ubcf5\ud574\uc11c \ud574\uacb0\ud574\uc57c \ud558\ub294 \ud3c9\ubc94\ud55c \ud544\uc694\uac00 \uc788\uc5c8\ub2e4. \uadf8\ub807\ub2e4\uace0 \ub204\uac00 \uc0ac\uc6a9\ud588\ub294\uc9c0 \ud655\uc778\ub418\uc9c0 \uc54a\uc740 \uc720\ubb3c\uc5d0 \ud2b9\uc815 \uc655\uc758 \ube44\ubc00 \uc77c\ud654\ub97c \ub367\ubd99\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \uc774\ub984\ub09c \uc778\ubb3c\uc774 \ub4f1\uc7a5\ud558\uc9c0 \uc54a\uc544\ub3c4 \ud615\ud0dc \uc790\uccb4\uac00 \ub9d0\ud574 \uc8fc\ub294 \uc0dd\ud65c\uc740 \ucda9\ubd84\ud788 \ud765\ubbf8\ub86d\ub2e4. \ubc1c\uc744 \ub450\ub294 \ubd80\ubd84\uacfc \ub4f1\ubc1b\uce68\uc758 \ud648\uc774 \uc788\ub2e4\ub294 \uc124\uba85\ub9cc\uc73c\ub85c\ub3c4, \ub2e8\uc21c\ud788 \ubb3c\uc9c8\uc744 \ub2f4\ub294 \ud1b5\uc774 \uc544\ub2c8\ub77c \uc0ac\ub78c\uc758 \uc790\uc138\ub97c \uc0dd\uac01\ud55c \ubb3c\uac74\uc784\uc744 \uc54c \uc218 \uc788\ub2e4. \uc549\ub294 \uad6c\uc870\uc640 \ubc30\uc124\ubb3c\uc744 \ubc1b\ub294 \uc6a9\uae30\uac00 \ubd84\ub9ac\ub41c\ub2e4\ub294 \uc810\uc740 \uc0ac\uc6a9\uacfc \ucc98\ub9ac\uc758 \uc2dc\uac04\uc744 \ub098\ub204\uc5b4 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ud558\ub098\uc758 \uc0c1\uc790 \uc804\uccb4\ub97c \ub9e4\ubc88 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ub2e4\ub8f0 \ud544\uc694\uac00 \uc5c6\ub3c4\ub85d \ubd80\ud488\uc744 \ub098\ub208 \ud615\ud0dc\ub2e4. \ub2e4\ub9cc \ub2f9\uc2dc\uc758 \uc815\ud655\ud55c \ucc98\ub9ac \uc808\ucc28\uc640 \ub2f4\ub2f9\uc790\uc758 \uc5ed\ud560\uc740 \uc18c\uc7a5\ud488 \uc124\uba85\ub9cc\uc73c\ub85c \uc7ac\ud604\ud560 \uc218 \uc5c6\ub2e4. \uae30\ub2a5\uc758 \uad6c\ubd84\uc744 \uba3c\uc800 \ubcf4\ub294 \uac83\uc774\ub2e4. \ubab8\uc744 \ubc1b\uce58\ub294 \ubd80\ubd84\uc5d0\ub294 \uc9c1\ubb3c\ub85c \uc2fc \ub098\ubb34\ud2c0\uc774 \uc788\uace0 \uc548\ucabd\uc5d0 \uc6a9\uae30\ub97c \ub123\ub294\ub2e4. \uc7ac\ub8cc\uac00 \ub2e4\ub974\uba74 \ub9e1\ub294 \uc790\ub9ac\ub3c4 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \uc804\uccb4\uac00 \uac19\uc740 \ube5b\uae54\ub85c \ubcf4\uc774\ub354\ub77c\ub3c4 \uad6c\uc131\uc740 \ud55c \ub369\uc5b4\ub9ac\ubcf4\ub2e4 \ubcf5\uc7a1\ud558\ub2e4. \uac74\ucd95\uc758 \ubc29 \uc548\uc5d0\uc11c \uc4f0\ub294 \uc791\uc740 \ubb3c\uac74\uc5d0\ub3c4 \uc11c\ub85c \ub2e4\ub978 \uc7ac\ub8cc\uc640 \ud589\ub3d9\uc744 \uc774\uc5b4 \uc8fc\ub294 \uc124\uacc4\uac00 \ub4e4\uc5b4 \uc788\uc5c8\ub2e4. \ubc30\uad00\uacfc \uace0\uc815\ub41c \uc124\ube44\ub97c \ub5a0\uc62c\ub9ac\uba74 \uc6a9\ubcc0\uc744 \ubcf4\ub294 \uc7a5\uc18c\uac00 \uac74\ubb3c \uc548\uc758 \ud55c \uc704\uce58\uc5d0 \ubb36\uc778\ub2e4. \uc774\ub3d9\uc2dd \ub3c4\uad6c\ub294 \uadf8\uc640 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \uc0dd\ud65c\uc758 \ubb38\uc81c\ub97c \ub2e4\ub8ec\ub2e4. \ud544\uc694\ud560 \ub54c \uc7a5\uc18c\ub97c \uc815\ud558\uace0 \ubd80\uc18d \uc6a9\uae30\ub97c \uad00\ub9ac\ud574\uc57c \ud55c\ub2e4\ub294 \uc810\uc744 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uc774\ub3d9\uc2dd\uc774\ub77c\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uc5b8\uc81c\ub098 \uc5ec\ud589 \uc911\uc5d0 \uc0ac\uc6a9\ud55c \ubb3c\uac74\uc774\ub77c\uace0 \ub2e8\uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uacfc\uac70\uc758 \ub3c4\uad6c\ub97c \uc9c0\uae08\ubcf4\ub2e4 \ubd88\ud3b8\ud55c \ub2e8\uacc4\ub85c\ub9cc \uc815\ub9ac\ud558\uba74 \ub2f9\uc2dc \ubb34\uc5c7\uc744 \ud574\uacb0\ud558\ub824 \ud588\ub294\uc9c0 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ubc18\ub300\ub85c \uc655\uc2e4 \ubb3c\uac74\uc774\ub77c\uace0 \ubaa8\ub4e0 \uc810\uc5d0\uc11c \uc644\ubcbd\ud55c \ubc29\ubc95\uc774\uc5c8\ub2e4\uace0 \ubcfc \ud544\uc694\ub3c4 \uc5c6\ub2e4. \ud655\uc778\ub41c \uad6c\uc870\uc640 \uadf8 \uc548\uc5d0\uc11c \uac00\ub2a5\ud588\ub358 \ud589\ub3d9\uc744 \uc77d\ub294 \ud3b8\uc774 \uc88b\ub2e4. \ubb3c\uac74\uc744 \ube44\uad50\ud558\ub294 \ubaa9\uc801\uc740 \uc21c\uc704\ub97c \ub9e4\uae30\uae30\ubcf4\ub2e4 \uc11c\ub85c \ub2e4\ub978 \uc0dd\ud65c \uc870\uac74\uc744 \uc774\ud574\ud558\ub294 \ub370 \uc788\ub2e4. \uccad\ub3d9\uc81c \uc6a9\ubcc0\uae30\uc758 \uc124\uba85\uc5d0 \ub4f1\uc7a5\ud558\ub294 \uc7ac\ub294 \ub2e8\uc21c\ud788 \ub2f4\uae34 \ub0b4\uc6a9\ubb3c\uc758 \uc815\ubcf4\uac00 \uc544\ub2c8\ub2e4. \uc8fc\ubcc0\uc5d0 \ubbf8\uce58\ub294 \uc18c\ub9ac\uc640 \ub0c4\uc0c8\uae4c\uc9c0 \uc2e0\uacbd \uc37c\ub2e4\ub294 \uae30\ub2a5 \uc124\uba85\uc774\ub2e4. \ubab8\uc758 \ud65c\ub3d9\uc744 \ubc1b\ub294 \ub3c4\uad6c\uac00 \uc0ac\ub78c\uacfc \uacf5\uac04\uc758 \uad00\uacc4\ub3c4 \ub2e4\ub8e8\uc5c8\ub2e4\ub294 \uc810\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ub2e4\ub9cc \ubaa9\uc81c \ud2c0\uc758 \uc720\ubb3c\uacfc \uae08\uc18d \uc6a9\uae30\ub97c \uac19\uc740 \uc0c1\ud0dc\ub85c \ubaa8\ub450 \ubb36\uc5b4\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc18c\uc7a5\ud488\uc758 \uc124\uba85\uc740 \uac01 \ubb3c\uac74\uc758 \ud2b9\uc9d5\uc744 \ube44\uad50\ud558\uac8c \ud55c\ub2e4. \ud558\ub098\uc5d0\uc11c \uc77d\uc740 \ub0b4\uc6a9\uc744 \ub2e4\ub978 \ubb3c\uac74\uc758 \ud655\uc778\ub41c \uc0ac\uc2e4\ub85c \uc62e\uaca8 \uc4f0\uc9c0 \uc54a\uc73c\uba74 \ucc28\uc774\uac00 \ub0a8\ub294\ub2e4. \uc0c1\uc790\uc758 \ud615\ud0dc\ub97c \ub530\ub77c\uac00\uba70 \uc0ac\ub78c\uc774 \uc549\ub294 \uc790\ub9ac\uc640 \uc548\ucabd\uc758 \ubd84\ub9ac \uad6c\uc870\ub97c \ub098\ub204\uc5b4 \ubcf4\uc790. \ud070 \uad81\uad90\uc758 \ud48d\uacbd\uc5d0\uc11c \uc798 \ub4dc\ub7ec\ub098\uc9c0 \uc54a\ub358 \uc0dd\ud65c\uc758 \uc791\uc740 \uae30\uc220\uc774 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uad81\uad90\uc744 \uad6c\uacbd\ud560 \ub54c\ub294 \uacf5\uac04\uc774 \uc6cc\ub099 \ucee4\uc11c \uadf8 \uc548\uc5d0\uc11c \uc2e4\uc81c\ub85c \uc5b4\ub5bb\uac8c \uc9c0\ub0c8\ub294\uc9c0 \ub193\uce58\uae30 \uc27d\ub2e4. \uc791\uc740 \uc0dd\ud65c \ub3c4\uad6c\ub294 \uadf8 \uac70\ub9ac\ub97c \uc904\uc5ec \uc900\ub2e4. \uc5b4\ub518\uac00\uc5d0 \ub193\uace0 \uc0ac\ub78c\uc774 \uc0ac\uc6a9\ud574\uc57c \ud588\ub358 \ubb3c\uac74\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \ub9e4\ud654\ud2c0\uc744 \ubcf4\uba74\uc11c \uc61b\uc0ac\ub78c\ub4e4\uc758 \uc0dd\ud65c\uc744 \ubd88\ud3b8\ud568 \ud558\ub098\ub85c\ub9cc \ud3c9\uac00\ud560 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \ub2f9\uc2dc\uc758 \uc7ac\ub8cc\uc640 \ubc29\uc2dd\uc73c\ub85c \ubb34\uc5c7\uc744 \ud574\uacb0\ud558\ub824 \ud588\ub294\uc9c0\ub97c \ubcf4\uba74 \ub41c\ub2e4. \ub123\uace0 \ube7c\ub294 \uc6a9\uae30, \ubc1c\ud310, \ub4f1\ubc1b\uce68\uc758 \ud754\uc801\uc740 \uadf8 \ub2f5\uc758 \uc77c\ubd80\ub2e4. \ub2e4\uc74c\uc5d0 \uc0dd\ud65c \uc720\ubb3c \uc804\uc2dc\ub97c \ub9cc\ub098\uba74 \ud654\ub824\ud55c \uc7a5\uc2dd \uc0ac\uc774\uc758 \uc18c\ubc15\ud55c \ubb3c\uac74\ub3c4 \uc0b4\ud3b4\ubcf4\uc790. \ud070 \uc5ed\uc0ac\uc758 \ubb34\ub300\uc600\ub358 \uad81\uad90\uc5d0\ub3c4, \ub9e4\uc77c\uc758 \uc0dd\ud65c\uc744 \ubc1b\uccd0 \uc8fc\ub294 \uc791\uc740 \uac00\uad6c\uac00 \ud544\uc694\ud588\ub2e4."}, {"id": "mexico-tortilla-grinding-stone", "title": "\ud1a0\ub974\ud2f0\uc57c \uc55e\uc5d0\ub294 \ub3cc \ub450 \uac1c\uac00 \uc788\uc5c8\ub2e4", "summary": "\uc644\uc131\ub41c \uc74c\uc2dd \ub4a4\uc5d0 \uc788\ub294 \uac08\ub3cc\uacfc \uc190\uc758 \uc6c0\uc9c1\uc784\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "life", "category_title": "Life", "subcategory": "Food", "url": "stories/mexico-tortilla-grinding-stone/index.html", "image": "media/mexico-tortilla-grinding-stone.jpg", "alt": "\uba55\uc2dc\ucf54 \ud478\uc5d0\ub974\ud1a0\ubc14\uc57c\ub974\ud0c0\uc5d0\uc11c \uba54\ud0c0\ud14c\uc640 \ub9c8\ub178\ub85c \uc625\uc218\uc218 \uc7ac\ub8cc\ub97c \uac00\ub294 \uc791\uc5c5\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc2e4\uc81c \uc0ac\uc9c4.", "text": "\ud1a0\ub974\ud2f0\uc57c \uc55e\uc5d0\ub294 \ub3cc \ub450 \uac1c\uac00 \uc788\uc5c8\ub2e4 \uba55\uc2dc\ucf54\uc758 \uc625\uc218\uc218 \uc74c\uc2dd\uacfc \uc190 \uac00\uae4c\uc6b4 \ub3c4\uad6c \uc644\uc131\ub41c \uc74c\uc2dd \ub4a4\uc5d0 \uc788\ub294 \uac08\ub3cc\uacfc \uc190\uc758 \uc6c0\uc9c1\uc784\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Food \uc0dd\ud65c \uba55\uc2dc\ucf54 \uc74c\uc2dd \ud1a0\ub974\ud2f0\uc57c\ub97c \ub5a0\uc62c\ub9b4 \ub54c\ub294 \ub465\uae00\uace0 \ub0a9\uc791\ud55c \uc644\uc131\ud488\uc774 \uba3c\uc800 \uc0dd\uac01\ub09c\ub2e4. \uc0ac\uc9c4\uc744 \uc870\uae08 \ub4a4\ub85c \ub3cc\ub824 \ubcf4\uba74 \uadf8 \uc55e\uc5d0 \ub3cc \ub450 \uac1c\uc640 \uc190\uc758 \uc6c0\uc9c1\uc784\uc774 \uc788\ub2e4. \ud55c\ucabd\uc740 \ub113\uace0 \ub2e4\ub978 \ucabd\uc740 \uae38\ucb49\ud558\ub2e4. OpenStax \uad50\uc7ac\ub294 \uba55\uc2dc\ucf54 \ud478\uc5d0\ub974\ud1a0\ubc14\uc57c\ub974\ud0c0\uc5d0\uc11c \ud1a0\ub974\ud2f0\uc57c\ub97c \ub9cc\ub4dc\ub294 \uc7a5\uba74\uc73c\ub85c \uc774 \uc0ac\uc9c4\uc744 \uc18c\uac1c\ud55c\ub2e4. \uc0ac\uc9c4 \uc18d \ub3c4\uad6c\ub294 \uc625\uc218\uc218\ub97c \uac08\uc544 \uc7ac\ub8cc\ub97c \uc900\ube44\ud558\ub294 \ub370 \uc4f0\ub294 \uba54\ud0c0\ud14c\uc640 \ub9c8\ub178\ub2e4. \uba54\ud0c0\ud14c\ub294 \uc7ac\ub8cc\ub97c \ubc1b\uce58\ub294 \ub113\uc740 \uac08\ub3cc\uc774\uace0, \ub9c8\ub178\ub294 \uc190\uc73c\ub85c \uc7a1\uc544 \uc6c0\uc9c1\uc774\ub294 \uae38\ucb49\ud55c \ub3cc\uc774\ub2e4. \ubaa8\uc591\uc774 \ub2e4\ub978 \ub450 \ubb3c\uac74\uc774 \ub9cc\ub098 \ud558\ub098\uc758 \uc791\uc5c5\uc744 \uc774\ub8ec\ub2e4. \ubbf9\uc11c\ucc98\ub7fc \ub36e\uac1c\ub97c \ub2eb\uace0 \uae30\ub2e4\ub9ac\ub294 \ub3c4\uad6c\ub97c \uc0dd\uac01\ud588\ub2e4\uba74 \ub9cc\ub4dc\ub294 \uc0ac\ub78c\uc758 \uc190\uc774 \ucc28\uc9c0\ud558\ub294 \uc790\ub9ac\uac00 \ub2e4\ub974\uac8c \ubcf4\uc77c \uc218 \uc788\ub2e4. \uc7ac\ub8cc\ub97c \uc5bc\ub9c8\ub098 \uc798\uac8c \uac08\uc9c0 \uc0b4\ud53c\uace0 \ubab8\uc744 \uc6c0\uc9c1\uc774\ub294 \uc77c\uc774 \uc900\ube44 \uacfc\uc815 \uc548\uc5d0 \ub4e4\uc5b4 \uc788\ub2e4. \uad50\uc7ac\ub294 \uc804\ud1b5\uc801\uc778 \uac00\ub8e8 \uc900\ube44\uc5d0 \uc54c\ub9de\uc740 \uc7ac\ub8cc\ub97c \uace0\ub974\uace0, \uc6d0\ud558\ub294 \uace0\uc6b4 \uc815\ub3c4\ub97c \ud310\ub2e8\ud558\uba70, \uac08\ub3cc\uc744 \ub2e4\ub8e8\ub294 \ub2a5\ub825\uc774 \ud544\uc694\ud558\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub3c4\uad6c\uac00 \uc788\ub2e4\uace0 \uac19\uc740 \uacb0\uacfc\uac00 \uc800\uc808\ub85c \ub098\uc624\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc6b0\ub9ac\ub294 \uc74c\uc2dd \uc774\ub984\uc740 \uc790\uc8fc \uae30\uc5b5\ud558\uc9c0\ub9cc \uadf8 \uc74c\uc2dd\uc758 \uc7ac\ub8cc\ub97c \uc900\ube44\ud558\ub294 \uc190\ub180\ub9bc\uc740 \uc798 \ubcf4\uc9c0 \ubabb\ud55c\ub2e4. \uc0ac\uc9c4 \ud55c \uc7a5\uc5d0\uc11c \uac08\ub3cc\uc758 \ud45c\uba74\uacfc \uc190\uc774 \ub193\uc778 \uc790\ub9ac\ub97c \uc0b4\ud3b4\ubcf4\uba74 \uba39\uae30 \uc9c1\uc804\ubcf4\ub2e4 \uc870\uae08 \uc774\ub978 \uc2dc\uac04\uc73c\ub85c \ub4e4\uc5b4\uac00\uac8c \ub41c\ub2e4. \uba54\ud0c0\ud14c\uc640 \ub9c8\ub178\ub294 \uac19\uc740 \ub3cc\uc774\ub77c\ub294 \uc7ac\ub8cc\ub85c \ubb36\uc744 \uc218 \uc788\uc9c0\ub9cc \uc5ed\ud560\uc740 \ub098\ub25c\ub2e4. \uc544\ub798\uc758 \ub113\uc740 \ud45c\uba74\uc774 \uc7ac\ub8cc\ub97c \ubc1b\uace0 \uc190\uc73c\ub85c \uc6c0\uc9c1\uc774\ub294 \ub3cc\uc774 \uadf8 \uc704\uc5d0\uc11c \uc77c\uc744 \ud55c\ub2e4. \uc5b4\ub290 \ud558\ub098\ub9cc \ubcf4\uba74 \ubc14\ub2e5\uc774\ub098 \uae38\ucb49\ud55c \ubb3c\uac74\ucc98\ub7fc \ubcf4\uc77c \uc218 \uc788\uc9c0\ub9cc \ud568\uaed8 \ub193\uc774\uba74 \uc6c0\uc9c1\uc784\uc774 \uc77d\ud78c\ub2e4. \ub3c4\uad6c\ub294 \uac1c\ubcc4 \ubaa8\uc591\ubfd0 \uc544\ub2c8\ub77c \uc11c\ub85c \ub2ff\ub294 \uad00\uacc4\ub97c \ud1b5\ud574 \uae30\ub2a5\uc744 \ub9cc\ub4e0\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c\ub294 \uc190\uc774 \uc5b4\ub290 \ubd80\ubd84\uc744 \uc7a1\ub294\uc9c0\uc640 \uc791\uc5c5 \ud45c\uba74\uc774 \uc5b4\ub290 \ubc29\ud5a5\uc73c\ub85c \ub193\uc600\ub294\uc9c0\ubd80\ud130 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uc815\uc9c0 \uc0ac\uc9c4 \ud55c \uc7a5\uc73c\ub85c \uc190\ub3d9\uc791\uc758 \uc18d\ub3c4\uc640 \ud798\uc744 \uacc4\uc0b0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc2e4\uc81c \uc791\uc5c5\uc758 \ubaa8\ub4e0 \ub2e8\uacc4\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uc601\uc0c1\ub3c4 \uc544\ub2c8\ub2e4. \ub0a8\uc544 \uc788\ub294 \ud55c\uc21c\uac04\uc5d0\uc11c \ubb34\uc5c7\uc774 \ubb34\uc5c7\uacfc \uc5f0\uacb0\ub418\uc5b4 \uc788\ub294\uc9c0 \uc54c\uc544\ubcf4\ub294 \uac83\uc774 \ucd9c\ubc1c\uc810\uc774\ub2e4. \uae30\uacc4\uac00 \uc544\ub2cc \ub3c4\uad6c\ub77c\uace0 \uc544\ubb34\ub807\uac8c\ub098 \uc6c0\uc9c1\uc5ec\ub3c4 \uac19\uc740 \uacb0\uacfc\uac00 \ub098\uc624\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc7ac\ub8cc\uc758 \uc0c1\ud0dc\ub97c \uc0b4\ud53c\uace0 \uc6d0\ud558\ub294 \uace0\uc6b4 \uc815\ub3c4\ub97c \uc54c\uc544\uc57c \ud55c\ub2e4\uace0 \uad50\uc7ac\ub294 \uc124\uba85\ud55c\ub2e4. \ubc18\ubcf5\ub418\ub294 \uc190\ub180\ub9bc \uc548\uc5d0\ub3c4 \uacbd\ud5d8\uc744 \ud1b5\ud574 \uc775\ud78c \ud310\ub2e8\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \ub2e8\uc21c \ub178\ub3d9\uc774\ub77c\ub294 \ub9d0\ub85c \ud55c \ubc88\uc5d0 \uc815\ub9ac\ud558\uae30 \uc5b4\ub824\uc6b4 \uc774\uc720\ub2e4. \uc6b0\ub9ac\ub294 \uc644\uc131\ub41c \ud1a0\ub974\ud2f0\uc57c\uc758 \ub9db\uacfc \ud06c\uae30\ub294 \uc27d\uac8c \ub9d0\ud558\uc9c0\ub9cc \uadf8 \uc55e\uc758 \uc7ac\ub8cc \uc900\ube44\ub294 \ub35c \uc774\uc57c\uae30\ud55c\ub2e4. \uc5b4\ub290 \uc2dc\uc810\uc5d0 \ucda9\ubd84\ud788 \uac08\ub838\ub2e4\uace0 \ubcfc\uc9c0, \uc190\uacfc \ub3c4\uad6c\ub97c \uc5b4\ub5bb\uac8c \ub2e4\ub8f0\uc9c0\ub294 \uacb0\uacfc\uc5d0 \uc601\ud5a5\uc744 \uc900\ub2e4. \ub2e4\ub9cc \uc774 \uc6d0\uace0\uc5d0\uc11c\ub294 \ud604\uc7a5 \uc790\ub8cc \uc5c6\uc774 \ud2b9\uc815\ud55c \uc870\ub9ac\ubc95\uacfc \uc2dc\uac04\uc744 \uc0c8\ub85c \uc81c\uc2dc\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc900\ube44\ud558\ub294 \uc0ac\ub78c\uc758 \uc9c0\uc2dd\uc774 \ud544\uc694\ud588\ub2e4\ub294 \ud070 \ub9e5\ub77d\uc5d0 \uc8fc\ubaa9\ud55c\ub2e4. \uad50\uc7ac\uc758 \ucea1\uc158\uc740 \uc0ac\uc9c4\uc744 \uba55\uc2dc\ucf54 \ud478\uc5d0\ub974\ud1a0\ubc14\uc57c\ub974\ud0c0\uc758 \ud1a0\ub974\ud2f0\uc57c \uc900\ube44 \uc7a5\uba74\uc73c\ub85c \uc18c\uac1c\ud55c\ub2e4. \ud55c \uc7a5\uba74\uc744 \uba55\uc2dc\ucf54\uc758 \ubaa8\ub4e0 \uac00\uc815\uc774\ub098 \ubaa8\ub4e0 \uc2dc\ub300\uc758 \uc870\ub9ac \ubc29\uc2dd\uc73c\ub85c \ubc14\uafc0 \uc218\ub294 \uc5c6\ub2e4. \uad6c\uccb4\uc801\uc778 \uc7a5\uc18c\uac00 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uc774\ub7f0 \uacfc\ub3c4\ud55c \uc77c\ubc18\ud654\ub97c \ub9c9\uc544 \uc900\ub2e4. \uac19\uc740 \uc74c\uc2dd \uc774\ub984 \uc544\ub798\uc5d0\ub3c4 \uc5ec\ub7ec \ub3c4\uad6c\uc640 \uc900\ube44 \ubc29\uc2dd\uc774 \uc788\uc744 \uc218 \uc788\ub2e4. \uc9c0\uc5ed\uacfc \uc0ac\ub78c\uc758 \uae30\uc220\uc744 \ub0a8\uaca8 \ub450\uba74 \uc61b \ub3c4\uad6c\uc640 \ud604\ub300 \uae30\uacc4\ub97c \ub2e8\uc21c\ud788 \ubc1c\uc804\uc758 \uc21c\uc11c\ub85c \ub098\ub204\uc9c0 \uc54a\uac8c \ub41c\ub2e4. \uc774 \ubc29\uc2dd\uc774 \ubb34\uc5c7\uc744 \uac00\ub2a5\ud558\uac8c \ud588\uace0 \uadf8 \uc548\uc5d0\uc11c \uc5b4\ub5a4 \uacbd\ud5d8\uc774 \ud544\uc694\ud588\ub294\uc9c0 \ubb3b\ub294 \ud3b8\uc774 \uc815\ud655\ud558\ub2e4. \uc0ac\uc9c4 \uc18d \uc778\ubb3c\uc758 \uc0dd\ud65c \uc804\uccb4\ub97c \uc54c\uc9c0 \ubabb\ud574\ub3c4 \uadf8 \uc0ac\ub78c\uc774 \uc9c0\uae08 \uc218\ud589\ud558\ub294 \uc791\uc5c5\uc744 \ubc30\uc6b8 \uc218 \uc788\ub2e4. \uc74c\uc2dd \ubb38\ud654\ub294 \uc7ac\ub8cc\ubfd0 \uc544\ub2c8\ub77c \ub9cc\ub4dc\ub294 \ud589\ub3d9\uc5d0\ub3c4 \uc788\ub2e4. \uc644\uc131\ub41c \uc74c\uc2dd\uc740 \uc2dd\ud0c1 \uc704\uc5d0 \uc9e7\uac8c \uba38\ubb3c \uc218 \uc788\uc9c0\ub9cc \uadf8 \uc55e\uc5d0\ub294 \uc5ec\ub7ec \uc900\ube44\uac00 \uc774\uc5b4\uc9c4\ub2e4. \uac08\ub3cc \uc0ac\uc9c4\uc740 \ud3c9\uc18c \uc811\uc2dc\uc5d0 \uac00\ub824\uc9c0\ub294 \uadf8 \uc2dc\uac04\uc744 \ub4dc\ub7ec\ub0b8\ub2e4. \ub204\uad70\uac00 \uc7ac\ub8cc\ub97c \uace8\ub790\uace0 \uc190\uc5d0 \uc775\uc740 \ub3c4\uad6c\ub85c \uc0c1\ud0dc\ub97c \ubc14\uafb8\uc5c8\ub2e4. \uba39\uc744 \uc218 \uc788\ub294 \ud615\ud0dc\uac00 \uc790\uc5f0\uc2a4\ub7fd\uac8c \ubc14\ub85c \ub098\ud0c0\ub09c \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ub2e4\uc74c\uc5d0 \uc775\uc219\ud55c \uc74c\uc2dd\uc758 \uc81c\uc791 \uc0ac\uc9c4\uc744 \ubcf4\uba74 \uc774\ub984\ubd80\ud130 \ud655\uc778\ud55c \ub4a4 \ub3c4\uad6c\uc640 \uc190\uc758 \uc811\uc810\uc744 \ubcf4\uc544 \ubcf4\uc790. \uc7ac\ub8cc\uac00 \ub193\uc778 \uba74\uacfc \uc6c0\uc9c1\uc774\ub294 \ub3c4\uad6c\ub97c \ub098\ub204\uc5b4 \ubcf4\uba74 \uc791\uc740 \uad6c\uc870\uac00 \ub4dc\ub7ec\ub09c\ub2e4. \ud1a0\ub974\ud2f0\uc57c \uc55e\uc758 \ub450 \ub3cc\uc740 \uc694\ub9ac\uc758 \uc5ed\uc0ac\ub97c \uc8fc\ubc29\uc758 \uc7a5\uce58\ubfd0 \uc544\ub2c8\ub77c \ubab8\uacfc \ud310\ub2e8\uc758 \uc5ed\uc0ac\ub85c \uc77d\ub294 \uc785\uad6c\uac00 \ub41c\ub2e4. \ub2e8\uc21c\ud574 \ubcf4\uc774\ub294 \ub3c4\uad6c\uc5d0 \uacbd\ud5d8\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4. \uc774 \uc0ac\uc9c4\uc774 \uba55\uc2dc\ucf54\uc758 \ubaa8\ub4e0 \uac00\uc815\uc774 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ud1a0\ub974\ud2f0\uc57c\ub97c \ub9cc\ub4e0\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc2e4\uc81c \ub0a8\uc544 \uc788\ub294 \ud55c \uc791\uc5c5 \uc7a5\uba74\uc744 \ubcf4\uace0 \uc788\ub2e4. \uad6c\uccb4\uc801\uc778 \uc870\ub9ac\ubc95\uc774\ub098 \uc7ac\ub8cc \ucc98\ub9ac\ubc95\uc744 \uc774 \uc0ac\uc9c4\ub9cc\uc73c\ub85c \uc815\ud558\uc9c0\ub3c4 \uc54a\ub294\ub2e4. \ub300\uc2e0 \uc775\uc219\ud55c \uc74c\uc2dd\uc744 \ubcfc \ub54c \uadf8 \uc55e\uc5d0 \uc5b4\ub5a4 \ub3c4\uad6c\uac00 \uc788\uc5c8\ub294\uc9c0 \ubb3c\uc5b4\ubcfc \uc218 \uc788\ub2e4. \ub0a9\uc791\ud55c \ud55c \uc7a5\uc774 \uc2dd\ud0c1\uc5d0 \uc624\uae30 \uc804\uc5d0 \ub204\uad70\uac00\ub294 \ub3cc\uc758 \ubb34\uac8c\uc640 \uc7ac\ub8cc\uc758 \uc0c1\ud0dc\ub97c \uc190\uc73c\ub85c \ub2e4\ub8e8\uc5c8\ub2e4. \ud1a0\ub974\ud2f0\uc57c\uc758 \ub2e4\ub978 \uc5bc\uad74\uc740 \uadf8\ub807\uac8c \uc644\uc131\ud488 \ubc14\uae65\uc5d0 \uc788\ub2e4."}, {"id": "popcorn-little-explosion", "title": "\ud31d\ucf58 \ud55c \uc54c\uc740 \uc5b4\ub5bb\uac8c \uc800\ub807\uac8c \ucee4\uc9c8\uae4c", "summary": "\ubd84\uba85 \ub2e8\ub2e8\ud55c \uc54c\uac31\uc774\uc600\ub294\ub370 \uc5b4\ub290\uc0c8 \ud558\uc597\uace0 \uac00\ubcbc\uc6b4 \uac04\uc2dd\uc73c\ub85c. \ud31d\ucf58\uc758 \ubcc0\uc2e0\uc5d0\ub294 \uc528\uc557 \uc18d \uc218\ubd84\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.", "category": "life", "category_title": "Life", "subcategory": "Food", "url": "stories/popcorn-little-explosion/index.html", "image": "media/popcorn-little-explosion.jpg", "alt": "\ud31d\ucf58 \ud55c \uc54c\uc740 \uc5b4\ub5bb\uac8c \uc800\ub807\uac8c \ucee4\uc9c8\uae4c \u2014 \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\ud31d\ucf58 \ud55c \uc54c\uc740 \uc5b4\ub5bb\uac8c \uc800\ub807\uac8c \ucee4\uc9c8\uae4c \uc54c\uac31\uc774 \uc548\uc5d0 \ub0a8\uc544 \uc788\ub358 \uc218\ubd84\uc774 \ud558\ub294 \uc77c \ubd84\uba85 \ub2e8\ub2e8\ud55c \uc54c\uac31\uc774\uc600\ub294\ub370 \uc5b4\ub290\uc0c8 \ud558\uc597\uace0 \uac00\ubcbc\uc6b4 \uac04\uc2dd\uc73c\ub85c. \ud31d\ucf58\uc758 \ubcc0\uc2e0\uc5d0\ub294 \uc528\uc557 \uc18d \uc218\ubd84\uc774 \ud544\uc694\ud569\ub2c8\ub2e4. Food \uc0dd\ud65c \uc601\ud654\uac00 \uc2dc\uc791\ub418\uae30 \uc804, \ud31d\ucf58 \ud1b5\uc5d0\ub294 \ubc8c\uc368 \uc190\uc774 \uba87 \ubc88 \uc624\uac04\ub2e4. \ud558\uc597\uace0 \uac00\ubcbc\uc6b4 \uc870\uac01\uc744 \uc9d1\ub2e4 \ubcf4\uba74 \uac00\ub054 \ubc14\ub2e5\uc5d0 \ub0a8\uc740 \ub2e8\ub2e8\ud55c \uc54c\uac31\uc774\ub97c \ub9cc\ub098\uae30\ub3c4 \ud55c\ub2e4. \ub458\uc740 \uac19\uc740 \uc625\uc218\uc218\uc5d0\uc11c \ucd9c\ubc1c\ud588\ub2e4. \uadf8\ub7f0\ub370 \ud558\ub098\ub294 \ubd80\ud480\uc5b4 \uc62c\ub790\uace0 \ub2e4\ub978 \ud558\ub098\ub294 \uc791\uc740 \ub3cc\ucc98\ub7fc \ub0a8\uc558\ub2e4. \ub300\uccb4 \uc54c\uac31\uc774 \uc548\uc5d0\uc11c \ubb34\uc2a8 \uc77c\uc774 \ubc8c\uc5b4\uc9c4 \uac83\uc77c\uae4c. \ud31d\ucf58\uc744 \ub9cc\ub4dc\ub294 \ub370\uc5d0\ub294 \ub2e8\uc9c0 \ub192\uc740 \uc628\ub3c4\ub9cc \ud544\uc694\ud55c \uac83\uc774 \uc544\ub2c8\ub2e4. \ub208\uc5d0 \uc798 \ubcf4\uc774\uc9c0 \uc54a\uc9c0\ub9cc \uc911\uc694\ud55c \uc900\ube44\ubb3c\uc774 \uc788\ub2e4. \uc54c\uac31\uc774 \uc548\uc758 \uc218\ubd84\uc774\ub2e4. \ud31d\ucf58\uc6a9 \uc625\uc218\uc218\ub3c4 \ubcf4\uad00\uacfc \uac00\uacf5\uc744 \uac70\uccd0 \uc6b0\ub9ac \uc190\uc5d0 \uc628\ub2e4. \ubbf8\uad6d \uad6d\ub9bd\ub18d\uc5c5\ub3c4\uc11c\uad00\uc758 \ud31d\ucf58 \uc804\uc2dc\ub294 \uc218\ud655\ud55c \uc625\uc218\uc218\ub97c \uc801\uc808\ud55c \uc218\ubd84 \uc0c1\ud0dc\ub85c \ub9d0\ub9ac\ub294 \uacfc\uc815\ubd80\ud130 \uc18c\uac1c\ud55c\ub2e4. \ubb34\uc870\uac74 \ubc14\uc2f9 \ub9d0\ub9ac\ub294 \uac83\uc774 \ubaa9\uc801\uc740 \uc544\ub2c8\ub2e4. \ud130\uc9c0\ub294 \ub370 \ud544\uc694\ud55c \uc218\ubd84\uc740 \ub0a8\uaca8\uc57c \ud55c\ub2e4. \uac00\uacf5 \uacfc\uc815\uc5d0\uc11c\ub294 \uc190\uc0c1\ub41c \uc54c\uac31\uc774\ub098 \uc774\ubb3c\uc9c8\uc744 \uace8\ub77c\ub0b4\uace0, \ud3ec\uc7a5\ud558\uae30 \uc88b\uac8c \uc815\ub9ac\ud55c\ub2e4. \uc791\uc740 \ubd09\uc9c0 \uc18d\uc5d0 \ub2f4\uaca8 \uc788\uc73c\ub2c8 \ub2e8\uc21c\ud55c \ubb3c\uac74\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc, \uadf8 \uc548\uc5d0\uc11c\ub3c4 \uc0c1\ud0dc\ub97c \ub9de\ucd94\ub294 \uc77c\uc774 \uc788\uc5c8\ub358 \uac83\uc774\ub2e4. \uc9d1\uc5d0\uc11c \ub370\uc6b4 \uc54c\uac31\uc774 \uc911 \uc77c\ubd80\uac00 \ub0a8\uc558\ub2e4\uace0 \ud574\uc11c \ubaa8\ub450 \uac19\uc740 \uc774\uc720\ub85c \uc2e4\ud328\ud588\ub2e4\uace0 \ub2e8\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \ud31d\ucf58\uc774 \ud130\uc9c0\ub824\uba74 \ub0b4\ubd80\uc758 \uc218\ubd84\uacfc \uc555\ub825\uc774 \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud55c\ub2e4\ub294 \uc810\uc744 \uc54c\uba74, \uc54c\uac31\uc774\uc758 \uc0c1\ud0dc\uac00 \uc65c \ud544\uc694\ud55c\uc9c0 \uc774\ud574\ud558\uae30 \uc27d\ub2e4. \ud31d\ucf58 \ud55c \ud1b5\uc744 \uc870\uae08 \ucc9c\ucc9c\ud788 \ubcf4\uba74 \ubaa8\ub450 \uac19\uc740 \ubaa8\uc591\uc774 \uc544\ub2c8\ub2e4. \uc5ec\ub7ec \ubc29\ud5a5\uc73c\ub85c \ubc8c\uc5b4\uc9c4 \uac83\ub3c4 \uc788\uace0, \ube44\uad50\uc801 \ub465\uae00\uac8c \ubcf4\uc774\ub294 \uac83\ub3c4 \uc788\ub2e4. \uc5b4\ub290 \ucabd\uc774 \ub354 \uc7ac\ubbf8\uc788\uac8c \uc0dd\uacbc\ub294\uc9c0 \uace8\ub77c \ubcf4\ub294 \uac83\ub9cc\uc73c\ub85c\ub3c4 \uc791\uc740 \uad6c\uacbd\uc774 \ub41c\ub2e4. \ud31d\ucf58\uc6a9 \uc54c\uac31\uc774\ub3c4 \ubaa8\ub450 \uc131\uacf5\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc218\ubd84 \uc0c1\ud0dc\ub098 \uaecd\uc9c8\uc758 \uc190\uc0c1, \uac00\uc5f4 \uc870\uac74\uc774 \uc601\ud5a5\uc744 \uc900\ub2e4. \uadf8\ub798\uc11c \ubc14\ub2e5\uc5d0 \ub0a8\uc740 \uc54c\uac31\uc774\ub97c \ubcf4\uace0 \ubb34\uc870\uac74 \ub35c \uc775\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ud130\uc9c0\uae30 \uc704\ud55c \uc870\uac74\uc744 \uac16\ucd94\uc9c0 \ubabb\ud588\uc744 \uc218\ub3c4 \uc788\ub2e4. \uae30\ub984 \uc5ed\uc2dc \ud31d\ucf58\uc758 \ud770 \ubd80\ubd84\uc744 \ub9cc\ub4dc\ub294 \uc7ac\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uae30\ub984\uc740 \uc870\ub9ac \uacfc\uc815\uc5d0\uc11c \uc5f4\uc744 \uc804\ub2ec\ud558\uace0 \ub9db\uc744 \ub354\ud560 \uc218 \uc788\uc9c0\ub9cc, \ub728\uac70\uc6b4 \uacf5\uae30\ub97c \uc774\uc6a9\ud574 \ub9cc\ub4dc\ub294 \ud31d\ucf58\ub3c4 \uc788\ub2e4. \ubcc0\uc2e0\uc758 \uc8fc\uc778\uacf5\uc740 \uc5ec\uc804\ud788 \uc625\uc218\uc218 \uc54c\uac31\uc774 \uc548\uc5d0 \uc788\ub2e4. \ubb3c\ub860 \uc774 \uc774\uc57c\uae30\ub294 \ud130\uc9c0\uc9c0 \uc54a\uc740 \uc54c\uac31\uc774\ub97c \uc5b5\uc9c0\ub85c \uc539\uc5b4 \ubcf4\ub77c\ub294 \uad8c\uc720\uac00 \uc544\ub2c8\ub2e4. \ud31d\ucf58 \uc0ac\uc774\uc5d0\uc11c \ub2e8\ub2e8\ud55c \uac83\uc774 \ub290\uaef4\uc9c0\uba74 \ub530\ub85c \uace8\ub77c\ub0b4\uba74 \ub41c\ub2e4. \uc6d0\ub9ac\ub97c \uc544\ub294 \uac83\uacfc \uc774\uac00 \ud574\uc57c \ud560 \uc77c\uc744 \ub298\ub9ac\ub294 \uac83\uc740 \ub2e4\ub978 \ubb38\uc81c\ub2e4. \uc54c\uac31\uc774\ub97c \ub370\uc6b0\uba74 \ub0b4\ubd80\uc758 \uc218\ubd84\uacfc \uc804\ubd84\uc774 \uc5f4\uc758 \uc601\ud5a5\uc744 \ubc1b\ub294\ub2e4. \uc218\ubd84\uc774 \uc218\uc99d\uae30\ub85c \ubcc0\ud558\uace0 \uc555\ub825\uc774 \ucee4\uc9c0\ub294 \ub3d9\uc548 \ubc14\uae65\uc758 \uaecd\uc9c8\uc740 \uadf8 \ubcc0\ud654\ub97c \ud55c\ub3d9\uc548 \ubd99\uc7a1\ub294\ub2e4. \uaecd\uc9c8\uc774 \ud130\uc9c0\ub294 \uc21c\uac04 \uc548\ucabd\uc758 \uc870\uac74\uc774 \uac11\uc790\uae30 \ub2ec\ub77c\uc9c0\uace0 \uc804\ubd84\uc774 \ud33d\ucc3d\ud55c\ub2e4. \uc791\uc740 \uc54c\uac31\uc774\uac00 \ud070 \ud770 \ub369\uc5b4\ub9ac\ucc98\ub7fc \ubcc0\ud558\ub294 \ub370\uc5d0\ub294 \uc774 \uc548\uacfc \ubc16\uc758 \uad00\uacc4\uac00 \uc911\uc694\ud558\ub2e4. \uadf8\ub798\uc11c \ud31d\ucf58\uc740 \ud45c\uba74\uc744 \uc608\uc058\uac8c \ubd80\ud480\ub9ac\ub294 \uc7a5\uc2dd\uc774 \uc544\ub2c8\ub2e4. \uc5f4\uc744 \ubc1b\uc740 \uc7ac\ub8cc\uc640 \uac07\ud78c \uc218\ubd84, \ud130\uc9c8 \ub54c\uc758 \ubcc0\ud654\uac00 \uc774\uc5b4\uc9c4 \uacb0\uacfc\ub2e4. \ub2e4\ub9cc \uc5ec\uae30\uc11c \ud2b9\uc815 \uc628\ub3c4\uc640 \uc555\ub825\uc758 \uc815\ud655\ud55c \uac12\uc744 \uc0c8\ub85c \uce21\uc815\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc870\ub9ac \uc870\uac74\uc744 \uc218\uce58\ub85c \ub2e8\uc815\ud558\uc9c0 \uc54a\uc544\ub3c4 \uac89\uc774 \uc7a1\uc544 \uc8fc\ub358 \uc555\ub825\uc774 \ud480\ub9ac\uba70 \ubcc0\ud654\ud55c\ub2e4\ub294 \ud750\ub984\uc740 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \ubc14\uc2f9 \ub9c8\ub974\uba74 \uc798 \ubcf4\uad00\ub420 \uac83 \uac19\uc9c0\ub9cc \ud31d\ucf58\uc5d0\uc11c\ub294 \ub0b4\ubd80 \uc218\ubd84\uc774 \ud130\uc9c0\ub294 \uc6d0\ub9ac\uc640 \uc5f0\uacb0\ub41c\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubb34\uc870\uac74 \ucd95\ucd95\ud558\uac8c \ub9cc\ub4e4\uba74 \ub41c\ub2e4\ub294 \ub73b\ub3c4 \uc544\ub2c8\ub2e4. \ub18d\uc5c5\ub3c4\uc11c\uad00\uc774 \uc218\ud655 \ub4a4 \uc801\uc808\ud55c \uc218\ubd84 \uc0c1\ud0dc\ub97c \ub9de\ucd94\ub294 \uacfc\uc815\uc744 \uc18c\uac1c\ud558\ub294 \uc774\uc720\ub2e4. \uc7ac\ub8cc\uc758 \uc870\uac74\uc744 \ub9de\ucd94\ub294 \uc77c\uc740 \uac00\uc5f4\ud558\uae30 \uc804\ubd80\ud130 \uc2dc\uc791\ub418\uc5b4 \uc788\uc5c8\ub2e4. \uc774 \uad00\uc810\uc5d0\uc11c \ud3ec\uc7a5\uc758 \uc54c\uac31\uc774\ub294 \uc790\uc5f0\uc5d0\uc11c \ubc14\ub85c \ub611\uac19\uc774 \ub098\uc628 \uc644\uc131\ud488\ucc98\ub7fc\ub9cc \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uace0\ub974\uace0 \ub9d0\ub9ac\uace0 \uc190\uc0c1\ub41c \uac83\uc744 \ubd84\ub9ac\ud558\ub294 \ub2e8\uacc4\uac00 \uc788\uc5c8\ub2e4. \ud55c \ubc88\uc5d0 \ub9ce\uc740 \uc591\uc774 \ube44\uc2b7\ud558\uac8c \ubc18\uc751\ud558\ub3c4\ub85d \uc900\ube44\ud558\ub294 \uac83\uc774\ub2e4. \uc74c\uc2dd\uc758 \ubcc0\uc2e0\uc744 \ubcf4\ub294 \uc7ac\ubbf8 \uc606\uc5d0 \uc7ac\ub8cc\ub97c \uc548\uc815\uc801\uc73c\ub85c \ub2e4\ub8e8\ub294 \uc0dd\uc0b0\uc758 \uc77c\uc774 \ud568\uaed8 \ubcf4\uc778\ub2e4. \ucee4\uc9c4 \ubd80\ubd84\uc740 \uc625\uc218\uc218 \uc548\uc758 \uc804\ubd84\uc774 \ud33d\ucc3d\ud55c \uacb0\uacfc\ub2e4. \uae30\ub984\uc774\ub098 \uc124\ud0d5\uc744 \ub123\uc5c8\uc744 \ub54c \uc0dd\uae34 \uac89\ubaa8\uc2b5\uacfc \uad6c\ubd84\ud574\uc11c \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ub9db\uc744 \ub354\ud558\uac70\ub098 \uc5f4\uc744 \uc804\ub2ec\ud558\ub294 \uc7ac\ub8cc\uac00 \uc788\uc5b4\ub3c4 \ubcc0\uc2e0\uc758 \uc911\uc2ec\uc740 \uc54c\uac31\uc774 \uc548\uc5d0 \uc788\ub2e4. \ub728\uac70\uc6b4 \uacf5\uae30\ub85c \ub9cc\ub4dc\ub294 \ubc29\uc2dd\ub3c4 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uadf8 \ucc28\uc774\ub97c \ubcf4\uc5ec \uc900\ub2e4. \uc644\uc131\ub41c \ud31d\ucf58\uc744 \ub2e4\uc2dc \uc6d0\ub798\uc758 \ub2e8\ub2e8\ud55c \uc54c\uac31\uc774\ub85c \ub2e8\uc21c\ud788 \uc811\uc5b4 \ub123\uc744 \uc218 \uc5c6\ub294 \uae4c\ub2ed\ub3c4 \ud615\ud0dc \ubcc0\ud654\uac00 \ub2e8\uc9c0 \uc870\uac01\uc744 \ud3b4 \ub193\uc740 \uc77c\uc774 \uc544\ub2c8\uae30 \ub54c\ubb38\uc774\ub2e4. \ubb3c\uacfc \uc804\ubd84\uc758 \uc0c1\ud0dc, \uaecd\uc9c8\uc758 \uad6c\uc870\uac00 \ud568\uaed8 \ubcc0\ud588\ub2e4. \uc774\uac83\uc744 \ubcf5\uc7a1\ud55c \ud654\ud559\uc2dd\uc73c\ub85c \uc124\uba85\ud558\uc9c0 \uc54a\uc544\ub3c4 \uc548\ucabd \uc7ac\ub8cc\uac00 \uc5f4\uacfc \uc555\ub825\uc744 \uacaa\uc5c8\ub2e4\ub294 \ud750\ub984\uc744 \ub530\ub77c\uac08 \uc218 \uc788\ub2e4. \uac04\uc2dd \ud55c \uc54c\uc5d0\uc11c \ubb3c\uc9c8\uc758 \ubcc0\ud654\ub97c \ub9cc\ub098\ub294 \uc21c\uac04\uc774\ub2e4. \ud31d\ucf58 \ud55c \ud1b5\uc744 \uc870\uae08 \ucc9c\ucc9c\ud788 \ubcf4\uba74 \ubaa8\ub450 \uac19\uc740 \ubaa8\uc591\uc774 \uc544\ub2c8\ub2e4. \ub0a0\uac1c\ucc98\ub7fc \uc5ec\ub7ec \ubc29\ud5a5\uc73c\ub85c \ubc8c\uc5b4\uc9c4 \uac83\ub3c4 \uc788\uace0, \ube44\uad50\uc801 \ub465\uae00\uac8c \ubd80\ud47c \uac83\ub3c4 \uc788\ub2e4. \ud488\uc885\uacfc \uac00\uc5f4 \uc870\uac74\uc5d0 \ub530\ub77c \ubaa8\uc2b5\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uadf8\ub798\uc11c \ud31d\ucf58\uc740 \uac04\uc2dd\uc774\uba74\uc11c \uc791\uc740 \uad6c\uacbd\uac70\ub9ac\uc774\uae30\ub3c4 \ud558\ub2e4. \ub611\uac19\uc740 \uae08\ud615\uc73c\ub85c \ucc0d\uc740 \uacfc\uc790\uc640 \ub2ec\ub9ac, \uc54c\uac31\uc774\ub9c8\ub2e4 \ud130\uc9c0\uace0 \uad73\uc740 \ud754\uc801\uc774 \ub0a8\ub294\ub2e4. \uac19\uc740 \ud1b5 \uc548\uc5d0\uc11c\ub3c4 \uc720\ub09c\ud788 \ud070 \uc870\uac01\uacfc \uc791\uc740 \uc870\uac01\uc774 \uc11e\uc5ec \uc788\ub2e4. \uc601\ud654\ub97c \ubcfc \ub54c \uc774 \ubaa8\ub4e0 \uacfc\uc815\uc744 \ub5a0\uc62c\ub9b4 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc774\uc57c\uae30\uc758 \uc911\uc694\ud55c \uc7a5\uba74\uc5d0 \uc625\uc218\uc218\uc758 \uaecd\uc9c8\uc744 \uc5f0\uad6c\ud558\uace0 \uc788\uc744 \uc774\uc720\ub3c4 \uc5c6\ub2e4. \ub2e4\ub9cc \ub2e4\uc74c\uc5d0 \ud31d\ucf58\uc744 \uc9d1\uc5c8\uc744 \ub54c, \uadf8 \uac00\ubcbc\uc6b4 \uc870\uac01\uc774 \ud55c\ub54c\ub294 \ub2e8\ub2e8\ud55c \uc528\uc557\uc774\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc7a0\uae50 \uc0dd\uac01\ud574 \ubcfc \uc218 \uc788\ub2e4. \uc694\ub780\ud55c \uc18c\ub9ac\uc640 \ud568\uaed8 \ubc8c\uc5b4\uc9c0\ub294 \uc791\uc740 \ubcc0\uc2e0. \ud31d\ucf58\uc740 \uc601\ud654\uac00 \uc2dc\uc791\ub418\uae30\ub3c4 \uc804\uc5d0 \uc790\uae30 \ubaab\uc758 \uc9e7\uc740 \uc7a5\uba74\uc744 \ub05d\ub0b8 \uc148\uc774\ub2e4."}, {"id": "princess-crescent-comb", "title": "\uc791\uc740 \ubc18\ub2ec\uc740 \uba38\ub9ac\ub97c \ube57\ub294 \ub3c4\uad6c\uc600\ub2e4", "summary": "\ub098\ubb34\ub85c \ub9cc\ub4e0 \uc791\uc740 \uc5bc\ub808\ube57\uc774 \ub0af\uc120 \uc655\uc2e4 \uc778\ubb3c\uc744 \uac00\uae4c\uc774 \ub370\ub824\uc635\ub2c8\ub2e4.", "category": "life", "category_title": "Life", "subcategory": "Clothing", "url": "stories/princess-crescent-comb/index.html", "image": "media/princess-crescent-comb.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc5bc\ub808\ube57 \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc791\uc740 \ubc18\ub2ec\uc740 \uba38\ub9ac\ub97c \ube57\ub294 \ub3c4\uad6c\uc600\ub2e4 \ud654\ud611\uc639\uc8fc\uc758 \ube57\uc5d0\uc11c \ubc1c\uacac\ud558\ub294 \uc77c\uc0c1\uc758 \ubaa8\uc591 \ub098\ubb34\ub85c \ub9cc\ub4e0 \uc791\uc740 \uc5bc\ub808\ube57\uc774 \ub0af\uc120 \uc655\uc2e4 \uc778\ubb3c\uc744 \uac00\uae4c\uc774 \ub370\ub824\uc635\ub2c8\ub2e4. Clothing \uc0dd\ud65c \uc791\uc740 \uac08\uc0c9 \uc870\uac01\uc774 \ubc18\ub2ec\ucc98\ub7fc \uad7d\uc5b4 \uc788\ub2e4. \uc544\ub798\ucabd\uc758 \ube57\uc0b4\uc744 \ubcf4\uae30 \uc804\uc5d0\ub294 \ubb34\uc2a8 \ubb3c\uac74\uc778\uc9c0 \uc7a0\uae50 \uace0\uac1c\ub97c \uae30\uc6b8\uc774\uac8c \ub41c\ub2e4. \uc774\ub984\uc740 \uc5bc\ub808\ube57\uc774\ub2e4. \uad81\uc911 \uc720\ubb3c\uc774\ub77c\uace0 \ud558\uba74 \uba3c\uc800 \ucee4\ub2e4\ub780 \uc655\uad00\uc774\ub098 \ud654\ub824\ud55c \uc758\ubcf5\uc744 \ub5a0\uc62c\ub9ac\uc9c0\ub9cc, \uba38\ub9ac\ub97c \uc815\ub3c8\ud558\ub294 \uc791\uc740 \ub3c4\uad6c\ub3c4 \ub0a8\uc544 \uc788\ub2e4. \uc774 \ube57\uc740 \ud654\ud611\uc639\uc8fc\uc758 \ubb18\uc5d0\uc11c \ucd9c\ud1a0\ub41c \uac83\uc73c\ub85c \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc18c\uac1c\ud55c\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc740 \ud615\ud0dc\ub97c \ud3c9\ud3c9\ud55c \ubc18\ub2ec \ubaa8\uc591\uc774\ub77c\uace0 \ud558\uace0, \ube57\uc0b4\uc740 \ud55c\ucabd\uc73c\ub85c\ub9cc \ub098 \uc788\ub2e4\uace0 \uc801\ub294\ub2e4. \uc0ac\uc9c4\uc744 \ubcf4\uba74 \ub465\uadfc \ub4f1\uacfc \ube57\uc0b4\uc774 \uc788\ub294 \uac00\uc7a5\uc790\ub9ac\uac00 \uc11c\ub85c \ub2e4\ub978 \uc120\uc744 \ub9cc\ub4e0\ub2e4. \uc774 \ube57\uc758 \uc7ac\ub8cc\ub294 \ub098\ubb34\ub2e4. \ubd89\uc740 \uce60\uc744 \ub73b\ud558\ub294 \uc8fc\uce60\uc740 \ub4f1\ub9c8\ub8e8\uc5d0 \ud588\ub2e4\uace0 \ud55c\ub2e4. \uc0ac\uc9c4 \uc804\uccb4\uac00 \ubd89\uc740\uc0c9\uc73c\ub85c \uc120\uba85\ud558\uc9c0 \uc54a\ub354\ub77c\ub3c4, \ud604\uc7ac \ubaa8\uc2b5\uacfc \uc124\uba85\uc5d0 \ub0a8\uc740 \uc81c\uc791 \ud2b9\uc9d5\uc744 \ud568\uaed8 \uc77d\uc73c\uba74 \ub193\uce58\uae30 \uc26c\uc6b4 \ubd80\ubd84\uc744 \ubc1c\uacac\ud560 \uc218 \uc788\ub2e4. \ud654\ud611\uc639\uc8fc\ub294 1733\ub144\uc5d0 \ud0dc\uc5b4\ub098 1752\ub144\uc5d0 \uc138\uc0c1\uc744 \ub5a0\ub09c \uc778\ubb3c\uc774\ub2e4. \ubc15\ubb3c\uad00\uc774 \uc54c\ub824 \uc8fc\ub294 \uc0dd\ubab0\ub144\uacfc \ucd9c\ud1a0 \uc7a5\uc18c\uac00 \uc774 \uc791\uc740 \ube57\uc744 \ud2b9\uc815\ud55c \uc778\ubb3c\uc758 \ud754\uc801\uacfc \uc774\uc5b4 \uc900\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc2e4\uc81c\ub85c \uc5b4\ub290 \ub0a0 \uc5b4\ub5a4 \uba38\ub9ac\ub97c \ube57\uc5c8\ub294\uc9c0\uae4c\uc9c0 \uc7ac\ud604\ud560 \uc218\ub294 \uc5c6\ub2e4. \ubb18\uc5d0\uc11c \ub098\uc654\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc0dd\uc804\uc758 \uc0ac\uc6a9 \uc7a5\uba74\uc740 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \uc0c1\uc0c1\uc758 \ub300\ud654\ub97c \ubd99\uc774\uc9c0 \uc54a\uc544\ub3c4, \uc6b0\ub9ac\uac00 \uc544\ub294 \ube57\uc774\ub77c\ub294 \ubb3c\uac74\ub9cc\uc73c\ub85c \ub0af\uc120 \uc0ac\ub78c\uacfc\uc758 \uac70\ub9ac\uac00 \uc870\uae08 \uc904\uc5b4\ub4e0\ub2e4. \uac00\ub85c 4.9\uc13c\ud2f0\ubbf8\ud130\ub77c\ub294 \uc218\uce58\ub294 \uc791\uc740 \ubb3c\uac74\uc758 \uc2e4\uac10\uc744 \uc900\ub2e4. \uc655\uc2e4 \uc778\ubb3c\uacfc \uad00\uacc4\ub41c \uc720\ubb3c\uc774\ub77c\uace0 \uc5b8\uc81c\ub098 \uac70\ub300\ud558\uace0 \ud654\ub824\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc190\uc5d0 \ub4e4\uace0 \uba38\ub9ac\ub97c \uc815\ub9ac\ud558\ub294 \ub3c4\uad6c\uc758 \ud06c\uae30\uc5d0\uc11c \uadf8 \uc0dd\ud65c\uc744 \ub9cc\ub0a0 \uc218\ub3c4 \uc788\ub2e4. \ub2e4\ub9cc \uc6b0\ub9ac\uac00 \uc775\uc219\ud558\uac8c \uc0ac\uc6a9\ud558\ub294 \ube57\uacfc \uc4f0\ub294 \ubc29\uc2dd\uc774 \ubaa8\ub4e0 \uc810\uc5d0\uc11c \uac19\uc558\ub2e4\uace0 \ub2e8\uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc0ac\uc9c4\uc740 \ud655\ub300\ub418\uc5b4 \ubcf4\uc774\uae30 \ub54c\ubb38\uc5d0 \ud06c\uae30 \ud45c\uae30\ub97c \ud568\uaed8 \uc77d\ub294 \uc77c\uc774 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ud654\uba74\uc744 \uac00\ub4dd \ucc44\uc6b4 \uc720\ubb3c\uc774 \uc2e4\uc81c\ub85c\ub294 \uc190 \uc548\uc5d0 \ub4e4\uc5b4\uc624\ub294 \ubb3c\uac74\uc77c \uc218 \uc788\ub2e4. \ub465\uadfc \ub4f1\uacfc \ucd18\ucd18\ud55c \ube57\uc0b4\uc744 \ubcf8 \ub4a4 \uc22b\uc790\ub97c \ub3cc\uc544\ubcf4\uba74 \uac19\uc740 \uc774\ubbf8\uc9c0\uc758 \uc778\uc0c1\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \ubaa8\uc591\uacfc \uce58\uc218\ub294 \uc11c\ub85c \ub2e4\ub978 \uc815\ubcf4\ub97c \ubcf4\ud0dc \uc900\ub2e4. \ub465\uadfc \ub4f1\ub9c8\ub8e8\uc640 \ube57\uc0b4\uc774 \ub09c \ucabd\uc740 \uac19\uc740 \uc724\uacfd \uc548\uc5d0\uc11c \ub2e4\ub978 \uae30\ub2a5\uc744 \uac16\ub294\ub2e4. \uc190\uc73c\ub85c \uc7a1\ub294 \ubd80\ubd84\uacfc \uba38\ub9ac\uce74\ub77d\uc744 \uc815\ub9ac\ud558\ub294 \ubd80\ubd84\uc744 \ub098\ub204\uc5b4 \uc0dd\uac01\ud558\uba74 \ud615\ud0dc\uac00 \ucd94\uc0c1\uc801\uc778 \uc7a5\uc2dd\uc5d0\uc11c \ub3c4\uad6c\ub85c \ubc14\ub010\ub2e4. \uc65c \uc5b4\ub5a4 \uac00\uc7a5\uc790\ub9ac\ub294 \ub9e4\ub048\ud558\uace0 \ub2e4\ub978 \ucabd\uc740 \ub098\ub258\uc5b4 \uc788\ub294\uc9c0 \uc9c8\ubb38\ud560 \uc218 \uc788\ub2e4. \uc775\uc219\ud55c \ubb3c\uac74\uc758 \uad6c\uc870\ub97c \ub2e4\uc2dc \ubcf4\ub294 \ubc29\ubc95\uc774\ub2e4. \ubc15\ubb3c\uad00\uc774 \ub4f1\ub9c8\ub8e8\uc758 \uc8fc\uce60\uc744 \ub530\ub85c \uc124\uba85\ud558\ub294 \uc810\ub3c4 \uc774\ub7f0 \uad6c\ubd84\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uc804\uccb4\ub97c \ud55c \uac00\uc9c0 \uc0c9\uc758 \ubb3c\uac74\uc73c\ub85c\ub9cc \uae30\uc5b5\ud558\uc9c0 \ub9d0\uace0 \uce60\ud55c \uc790\ub9ac\uc640 \ube57\uc0b4\uc758 \uad00\uacc4\ub97c \uc0b4\ud3b4\ubcf4\uba74 \ub41c\ub2e4. \uc0ac\uc9c4\uc758 \ud604\uc7ac \uc0c9\uacfc \uc81c\uc791 \ub2f9\uc2dc\uc758 \uc0c1\ud0dc\uac00 \uc644\uc804\ud788 \uac19\uc73c\ub9ac\ub77c\uace0 \uac00\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uae30\ub85d\ub41c \uae30\ubc95\uc774 \uad00\ucc30\uc744 \ub3d5\uace0 \uad00\ucc30\uc740 \uadf8 \uc124\uba85\uc744 \uad6c\uccb4\uc801\uc73c\ub85c \ub9cc\ub4e0\ub2e4. \ud654\ud611\uc639\uc8fc\uc758 \ubb18\uc5d0\uc11c \ub098\uc654\ub2e4\ub294 \uc815\ubcf4\ub294 \uc774\ub984 \uc5c6\ub294 \ube57\uc744 \ud2b9\uc815\ud55c \uc5ed\uc0ac\uc801 \uc778\ubb3c\uc758 \uc790\ub8cc\uc640 \uc774\uc5b4 \uc900\ub2e4. \uc0dd\ubab0\ub144\uc744 \ud568\uaed8 \uc54c\uba74 \ubb3c\uac74\uc774 \ub193\uc778 \uc2dc\uac04\uc758 \ub9e5\ub77d\ub3c4 \uc0dd\uae34\ub2e4. \uadf8\ub7ec\ub098 \ubb18\uc5d0 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc0b4\uc544 \uc788\uc744 \ub54c \uc5b4\ub290 \ub0a0 \uc9c1\uc811 \uc0ac\uc6a9\ud588\ub2e4\ub294 \uc7a5\uba74\uc740 \ub2e4\ub974\ub2e4. \ubc1c\uacac\uc758 \uad00\uacc4\uc640 \uad6c\uccb4\uc801\uc778 \uc0dd\ud65c\uc758 \uc7ac\uad6c\uc131\uc744 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \uadf8\ub798\uc11c \uc774 \uae00\uc5d0\uc11c\ub294 \uba38\ub9ac\ub97c \ube57\uc5b4 \uc8fc\ub294 \ub300\ud654\ub098 \ub2f9\uc2dc \ubc29\uc758 \ubaa8\uc2b5\uc744 \uc0c8\ub85c \ub9cc\ub4e4\uc9c0 \uc54a\ub294\ub2e4. \uadf8\ub7f0 \uc7a5\uba74\uc774 \uc5c6\uc5b4\ub3c4 \uc0ac\ub78c\ub4e4\uc774 \ubab8\uc744 \uac00\uafb8\uba70 \uc4f0\ub358 \ub3c4\uad6c\ub77c\ub294 \uc810\uc774 \uac70\ub9ac\ub97c \uc904\uc5ec \uc900\ub2e4. \uc655\uc2e4\uc758 \uc774\ub984\uc744 \ubaa8\ub974\ub358 \ub3c5\uc790\uc5d0\uac8c\ub3c4 \ube57\uc774\ub77c\ub294 \ubb3c\uac74\uc740 \uce5c\uc219\ud558\ub2e4. \uc775\uc219\ud55c \uae30\ub2a5\uc774 \ub0af\uc120 \uc0ac\ub78c\uc744 \ub9cc\ub098\ub294 \uc791\uc740 \uc785\uad6c\uac00 \ub41c\ub2e4. \ubaa9\uc7ac\uc5d0 \ube57\uc0b4\uc744 \ub9cc\ub4e0 \ubb3c\uac74\uc740 \ub2e8\ub2e8\ud55c \uae08\uc18d \ub369\uc5b4\ub9ac\uc640 \ub2e4\ub978 \uad6c\uc870\ub97c \uac00\uc9c4\ub2e4. \uc791\uc740 \ubd80\ubd84\ub4e4\uc774 \ubc18\ubcf5\ub418\uba74\uc11c \ud558\ub098\uc758 \uc4f0\uc784\uc744 \uc774\ub8ec\ub2e4. \ub2e4\ub9cc \uc0ac\uc9c4\uc744 \ubcf4\uace0 \ubaa8\ub4e0 \uc190\uc0c1\uc758 \uc6d0\uc778\uc774\ub098 \ub545\uc18d\uc5d0\uc11c\uc758 \ubcc0\ud654\ub97c \uc0c8\ub85c \ud310\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc7ac\ub8cc\uc640 \ud615\ud0dc\ub97c \uc54c\uc544\ubcf4\ub294 \uc77c\uacfc \ubcf4\uc874 \uacfc\uc815\uc744 \uc124\uba85\ud558\ub294 \uc77c\uc740 \ub2e4\ub978 \uadfc\uac70\ub97c \uc694\uad6c\ud55c\ub2e4. \ud604\uc7ac \ub0a8\uc740 \ubaa8\uc2b5\uc744 \ucda9\ubd84\ud788 \ubcf4\ub294 \uac83\ub9cc\uc73c\ub85c\ub3c4 \uc9c8\ubb38\uc740 \ub298\uc5b4\ub09c\ub2e4. \uc65c \uc774 \uc815\ub3c4 \ud06c\uae30\ub85c \ub9cc\ub4e4\uc5c8\uc744\uc9c0, \uc5b4\ub290 \ucabd\uc744 \uc950\uac8c \ub418\ub294\uc9c0, \uce60\uc740 \uc5b4\ub514\uc5d0 \ub193\uc600\ub294\uc9c0 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \ubaa8\ub4e0 \uc9c8\ubb38\uc5d0 \ud655\uc815\ub41c \ub2f5\uc744 \ubd99\uc774\uc9c0 \uc54a\uc544\ub3c4 \uc88b\ub2e4. \uc791\uc740 \ubc18\ub2ec\uc740 \ud654\ub824\ud55c \uc655\uc2e4\uc758 \uc774\ubbf8\uc9c0 \uc606\uc5d0 \ubab8\uacfc \uc190\uc758 \uc77c\uc0c1\uc774\ub77c\ub294 \ub610 \ub2e4\ub978 \uc2dc\uac04\uc744 \ub193\uc544 \uc900\ub2e4. \uc18c\uc7a5\ud488 \uc815\ubcf4\uc758 \uac00\ub85c \uae38\uc774\ub294 4.9\uc13c\ud2f0\ubbf8\ud130\ub2e4. \uc22b\uc790\ub97c \uc77d\uace0 \uc0ac\uc9c4\uc744 \ub2e4\uc2dc \ubcf4\uba74 \ucc98\uc74c\uc5d0 \uc9d0\uc791\ud588\ub358 \uac83\ubcf4\ub2e4 \ub354 \uc791\uc740 \ubb3c\uac74\uc73c\ub85c \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \ud654\uba74\uc5d0\uc11c \ud06c\uac8c \ubcf8\ub2e4\uace0 \uc2e4\uc81c \ubb3c\uac74\ub3c4 \ucee4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774 \ube57\uc5d0\uc11c \ud2b9\ubcc4\ud55c \ube44\ubc00\uc744 \ucc3e\uc73c\ub824\uace0 \uc560\uc4f8 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub098\ubb34\ub97c \ub2e4\ub4ec\uace0 \ud55c\ucabd\uc5d0 \ube57\uc0b4\uc744 \ub0b4\uace0 \ub4f1\uc5d0 \ubd89\uc740 \uce60\uc744 \ud588\ub2e4\ub294 \uac83. \uadf8\ub7f0 \uad6c\uccb4\uc801\uc778 \ubaa8\uc2b5\uc774 \uc624\ub798\uc804\uc758 \uc0dd\ud65c\uc744 \ub5a0\uc62c\ub9b4 \ucd9c\ubc1c\uc810\uc774 \ub41c\ub2e4. \ubc18\ub2ec \ubaa8\uc591 \ud558\ub098\uac00 \uc778\ubb3c\uc758 \uae34 \uc124\uba85\ubcf4\ub2e4 \uc624\ub798 \uae30\uc5b5\ub420 \ub54c\ub3c4 \uc788\ub2e4."}, {"id": "red-comb-chest-turtle", "title": "\ube57\uc744 \ub2f4\ub294 \uc0c1\uc790\uc758 \ubb38\uc9c0\uae30\ub294 \uac70\ubd81\uc774\uc5c8\ub2e4", "summary": "\uc11c\ub78d\uacfc \uce78\ub9c9\uc774\ub97c \uac16\ucd98 \ube57\uc811\uc5d0\uc11c \uac70\ubd81\uc774 \ubaa8\uc591 \uc790\ubb3c\uc1e0\ub97c \ubc1c\uacac\ud569\ub2c8\ub2e4.", "category": "life", "category_title": "Life", "subcategory": "Housing", "url": "stories/red-comb-chest-turtle/index.html", "image": "media/red-comb-chest-turtle.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc8fc\uce60\ube57\uc811 \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\ube57\uc744 \ub2f4\ub294 \uc0c1\uc790\uc758 \ubb38\uc9c0\uae30\ub294 \uac70\ubd81\uc774\uc5c8\ub2e4 \ubd89\uc740 \ube57\uc811\uc5d0 \ub2ec\ub9b0 \uc791\uc740 \uc790\ubb3c\uc1e0 \uc11c\ub78d\uacfc \uce78\ub9c9\uc774\ub97c \uac16\ucd98 \ube57\uc811\uc5d0\uc11c \uac70\ubd81\uc774 \ubaa8\uc591 \uc790\ubb3c\uc1e0\ub97c \ubc1c\uacac\ud569\ub2c8\ub2e4. Housing \uc0dd\ud65c \uc791\uc740 \ubd89\uc740 \uc0c1\uc790\uac00 \uc788\ub2e4. \ubb38\uc9dd\uacfc \uae08\uc18d \uc7a5\uc2dd\uc774 \ub2ec\ub824 \uc788\uc5b4\uc11c \uac00\uad6c\ub97c \uc904\uc5ec \ub193\uc740 \uac83\ucc98\ub7fc \ubcf4\uc778\ub2e4. \uac00\uae4c\uc774 \uc0b4\ud3b4\ubcfc \ub54c \uc7ac\ubbf8\uc788\ub294 \uac83\uc740 \uac00\uc6b4\ub370 \ubd99\uc740 \uc790\ubb3c\uc1e0\ub2e4. \ubaa8\uc591\uc774 \uac70\ubd81\uc774\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \uc8fc\uce60\ube57\uc811\uc774\ub2e4. \ube57\uc811\uc774\ub77c\ub294 \ub0af\uc120 \uc774\ub984\uc744 \ub9cc\ub0ac\ub2e4\uba74, \ube57\uc744 \ub450\ub294 \uc791\uc740 \uc218\ub0a9 \uac00\uad6c\ub97c \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc774 \ubb3c\uac74\uc5d0\uc11c\ub294 \uc548\uc744 \uc815\ub9ac\ud558\ub294 \uad6c\uc870\uc640 \ubc16\uc744 \uafb8\ubbf8\ub294 \uc7a5\uc2dd\uc774 \ud568\uaed8 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc717\ub2e8\uc744 \uc816\ud600 \uc5ec\ub294 \ubd80\ubd84\uacfc \uc548\ucabd\uc758 \uc11c\ub78d \ub450 \uac1c\uac00 \uc788\ub294 \uad6c\uc870\ub77c\uace0 \uc124\uba85\ud55c\ub2e4. \uc717\ubd80\ubd84 \uc548\uc5d0\ub294 \uce78\ub9c9\uc774\ub3c4 \uc788\uc73c\uba70, \ud604\uc7ac \uadf8 \uc77c\ubd80\ub294 \uc5c6\uc5b4\uc838 \uc788\ub2e4. \uc791\uc740 \uc0c1\uc790\ub77c\uace0 \uc548\uc774 \ud145 \ube44\uc5b4 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ub298\ub0a0 \ud654\uc7a5\ub300 \uc11c\ub78d\uc5d0 \uc815\ub9ac\ud568\uc744 \ub123\ub294 \ubaa8\uc2b5\uc744 \uc0dd\uac01\ud558\uba74 \uc774\ud574\ud558\uae30 \uc27d\ub2e4. \ub2e4\ub9cc \uac01 \uce78\uc5d0 \uc815\ud655\ud788 \ubb34\uc5c7\uc744 \ub123\uc5c8\ub294\uc9c0\ub294 \uc774 \uc124\uba85\ub9cc\uc73c\ub85c \uc54c \uc218 \uc5c6\ub2e4. \ubb3c\uac74\ub9c8\ub2e4 \uc790\ub9ac\ub97c \ub098\ub204\uc5b4 \ub454 \uad6c\uc870\uc5d0 \uba3c\uc800 \uc8fc\ubaa9\ud558\uba74 \ub41c\ub2e4. \uac89\uba74\uc5d0\ub294 \ubd89\uc740 \uce60\uc744 \ud588\uace0 \ub0b4\ubd80\ub294 \uac80\uc740 \uce60\ub85c \ub9c8\uac10\ud588\ub2e4. \uc11c\ub78d \uc5ed\uc2dc \uc55e\uba74\uc740 \ubd89\uace0 \ub098\uba38\uc9c0 \uba74\uc740 \uac80\ub2e4\uace0 \ud55c\ub2e4. \ub2eb\uc558\uc744 \ub54c \ubcf4\uc774\ub294 \ubd80\ubd84\uacfc \uc5f4\uc5c8\uc744 \ub54c \ub4dc\ub7ec\ub098\ub294 \ubd80\ubd84\uc758 \uc0c9\uc774 \ub2e4\ub974\ub2e4. \uae08\uc18d \uc7a5\uc2dd\uc5d0\ub294 \uaf43\ubb34\ub2ac\ub97c \ube44\ub86f\ud55c \uc5ec\ub7ec \ubb34\ub2ac\uac00 \uc788\ub2e4. \ud638\ub9ac\ubcd1\uacfc \ubcf5\uc22d\uc544, \ubd80\ucc44, \uaf43\uacfc \uc0c8 \uc7a5\uc2dd\ub3c4 \uc124\uba85\uc5d0 \ub4f1\uc7a5\ud55c\ub2e4. \uc791\uc740 \uc218\ub0a9 \uac00\uad6c\uc5d0 \uaf64 \ub9ce\uc740 \ubcfc\uac70\ub9ac\ub97c \ubaa8\uc544 \ub454 \uc148\uc774\uc9c0\ub9cc, \ucc98\uc74c\ubd80\ud130 \ubaa8\ub450 \ucc3e\uc73c\ub824 \uc560\uc4f8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc0c1\uc790\uc758 \ub69c\uaed1\uc744 \uc816\ud788\ub294 \ub3d9\uc791\uacfc \uc11c\ub78d\uc744 \ub2f9\uae30\ub294 \ub3d9\uc791\uc740 \uc11c\ub85c \ub2e4\ub974\ub2e4. \uac19\uc740 \uc791\uc740 \uac00\uad6c \uc548\uc5d0\uc11c \ub450 \ubc29\uc2dd\uc758 \uc811\uadfc\uc744 \ub9c8\ub828\ud588\ub2e4\ub294 \uc810\uc774 \ud765\ubbf8\ub86d\ub2e4. \ud070 \ud2c0\uc740 \ud558\ub098\uc5ec\ub3c4 \uc548\uc758 \ubb3c\uac74\uc744 \uaebc\ub0b4\ub294 \uae38\uc740 \uc5ec\ub7ec \uac1c\uc77c \uc218 \uc788\ub2e4. \uc218\ub0a9\uc758 \ud615\ud0dc\ub97c \uc2e4\uc81c \uc190\uc758 \ud589\ub3d9\uacfc \uc5f0\uacb0\ud574 \ubcf4\uba74 \uad6c\uc870\ub97c \ub354 \uc27d\uac8c \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uac01 \uce78\uc5d0 \uc5b4\ub290 \uc885\ub958\uc758 \ube57\uacfc \ubb3c\uac74\uc774 \ub4e4\uc5b4\uac14\ub294\uc9c0\ub97c \ubaa8\ub450 \uc548\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc774\ub984\uc774 \ube57\uc811\uc774\ub77c\uace0 \ud574\uc11c \ud604\uc7ac \ube44\uc5b4 \uc788\ub294 \ubaa8\ub4e0 \uce78\uc5d0 \uac19\uc740 \ubb3c\uac74\uc744 \ucc44\uc6cc \ub123\uc744 \uc218\ub294 \uc5c6\ub2e4. \ubc15\ubb3c\uad00\uc774 \uc124\uba85\ud558\ub294 \uce78\ub9c9\uc774\uc640 \uc11c\ub78d\uc744 \uba3c\uc800 \ubcf4\uc790. \ub098\ub204\uc5b4 \ubcf4\uad00\ud558\ub824\ub294 \uc758\ub3c4\ub294 \uc54c \uc218 \uc788\uc9c0\ub9cc \uadf8 \uc548\uc758 \uad6c\uccb4\uc801\uc778 \uc0dd\ud65c \ubaa9\ub85d\uc740 \ub610 \ub2e4\ub978 \uc790\ub8cc\uac00 \ud544\uc694\ud558\ub2e4. \uac89\uc758 \ubd89\uc740 \uce60\uacfc \uc548\uc758 \uac80\uc740 \uce60\uc740 \ubcf4\ub294 \uc0c1\ud669\uc744 \ub2ec\ub9ac\ud55c\ub2e4. \ub2eb\uc558\uc744 \ub54c \ud558\ub098\uc758 \uc0c9\uc73c\ub85c \uae30\uc5b5\ud560 \ubb3c\uac74\uc774 \uc5f4\ub9ac\uba74 \ub2e4\ub978 \uba74\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc11c\ub78d\ub3c4 \uc55e\uba74\uacfc \ub098\uba38\uc9c0 \ubd80\ubd84\uc744 \ub2e4\ub974\uac8c \ub9c8\uac10\ud588\ub2e4\uace0 \ud558\ub2c8, \ubb3c\uac74\uc774 \uc6c0\uc9c1\uc77c \ub54c \ub098\ud0c0\ub098\ub294 \ud45c\uc815\uc774 \uc788\uc5c8\ub2e4. \ub2e8\uc21c\ud55c \uac89\uce58\uc7a5\ub9cc\uc73c\ub85c \uc124\uba85\ub418\uc9c0 \uc54a\ub294 \uc0c9\uc758 \ubc30\uce58\ub2e4. \uc774\uac83\uc744 \uc0ac\uc9c4\uc5d0\uc11c \ud655\uc778\ud560 \ub54c\uc5d0\ub294 \uc5b4\ub290 \ubd80\ubd84\uc774 \uc5f4\ub824 \uc788\uace0 \ubb34\uc5c7\uc774 \uac00\ub824\uc838 \uc788\ub294\uc9c0\ubd80\ud130 \uad6c\ubcc4\ud558\uba74 \uc88b\ub2e4. \ud45c\uba74\uc758 \uc0c9\uc744 \ucc98\uc74c \uc81c\uc791 \ub2f9\uc2dc\uc758 \uc0c1\ud0dc\uc640 \ub611\uac19\ub2e4\uace0 \ub2e8\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uadf8\ub7ec\ub098 \ud604\uc7ac \ub0a8\uc740 \uad6c\ubd84\uacfc \uae30\ub85d\ub41c \ub9c8\uac10\uc744 \ud568\uaed8 \uc77d\uc73c\uba74, \ub2eb\ud78c \ubaa8\uc2b5\ub9cc\uc73c\ub85c \uac00\uad6c\ub97c \ub2e4 \ubcf4\uc558\ub2e4\uace0 \uc0dd\uac01\ud558\uc9c0 \uc54a\uac8c \ub41c\ub2e4. \uc6c0\uc9c1\uc784\uc774 \uc788\uc5b4\uc57c \ub098\ud0c0\ub098\ub294 \uba74\ub3c4 \ubb3c\uac74\uc758 \uc77c\ubd80\ub2e4. \uc81c\ubaa9\uc758 \uac70\ubd81\uc774\ub294 \uc0c1\uc790\ub97c \uc9c0\ud0a4\ub294 \uc0c1\uc0c1 \uc18d \uc774\uc57c\uae30\ub9cc\uc774 \uc544\ub2c8\ub77c \uc790\ubb3c\uc1e0\uc758 \ud615\uc0c1\uc774\ub2e4. \uc7a0\uadf8\ub294 \uae30\ub2a5\uc744 \ub9e1\uc740 \uae08\uc18d \ubd80\ud488\uc5d0 \uc0dd\ubb3c\uc758 \ubab8\uc744 \ud45c\ud604\ud588\ub2e4. \uc774\uac83\uc744 \uc54c\uace0 \ub098\uba74 \uadc0\uc5ec\uc6b4 \uac70\ubd81 \uc7a5\uc2dd\uc774\ub77c\ub294 \uccab\uc778\uc0c1\uc774 \uc2e4\uc81c \uc4f0\uc784\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uae30\ub2a5\uacfc \ud615\uc0c1\uc774 \uac19\uc740 \uc790\ub9ac\uc5d0 \ub193\uc778 \uc0ac\ub840\ub2e4. \uac70\ubd81\uc744 \ud2b9\uc815\ud55c \uc18c\uc6d0 \ud558\ub098\uc640 \uace7\ubc14\ub85c \uc5f0\uacb0\ud574 \uc81c\uc791\uc790\uc758 \uc758\ub3c4\ub97c \ud655\uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc5ec\uae30\uc11c \ud655\uc778\ub418\ub294 \uac83\uc740 \uac70\ubd81\uc774 \ud615\ud0dc\uc758 \uc790\ubb3c\uc1e0\uc640 \ub2e4\uc591\ud55c \uae08\uc18d \ubb38\uc591\uc774\ub2e4. \ubc14\uae65\uc758 \ud654\ub824\ud55c \uce60\uacfc \uc791\uc740 \uae08\uc18d \ubd80\ubd84\uc774 \uac01\uac01 \ub2e4\ub978 \uc7ac\ub8cc\uc758 \ud45c\uc815\uc744 \ub9cc\ub4e0\ub2e4. \ud070 \uba74\uc744 \ubcf8 \ub4a4 \uc811\uc810\uacfc \uc7a0\uadf8\ub294 \ubd80\ubd84\uc73c\ub85c \ub208\uc744 \uc62e\uae30\uba74 \uac00\uad6c\uc758 \uad6c\uc870\uac00 \ub354 \uc790\uc138\ud788 \ubcf4\uc778\ub2e4. \ud604\uc7ac \uc77c\ubd80\uac00 \uacb0\uc2e4\ub418\uc5c8\ub2e4\ub294 \uc815\ubcf4\ub294 \ubaa8\uc790\ub780 \ubd80\ubd84\uc744 \uad00\ub78c\uc790\uc758 \uc0c1\uc0c1\uc73c\ub85c \uba54\uc6b0\uc9c0 \uc54a\ub3c4\ub85d \ub3d5\ub294\ub2e4. \ubb3c\uac74\uc758 \uc6d0\ub798 \uad6c\ud68d\uacfc \ub0a8\uc740 \ubaa8\uc2b5\uc774 \uc644\uc804\ud788 \uac19\uc9c0\ub294 \uc54a\uc744 \uc218 \uc788\ub2e4. \uc18c\uc7a5\ud488\uc744 \uc124\uba85\ud560 \ub54c \uc5c6\ub294 \ubd80\ubd84\uae4c\uc9c0 \ubc1d\ud600 \ub450\ub294 \uac83\uc740 \uc2e4\uc218\ub098 \uacb0\ud568\uc744 \uc228\uae30\uc9c0 \uc54a\ub294 \uae30\ub85d\uc758 \ud0dc\ub3c4\ub2e4. \uc5f0\uad6c\uc640 \ubcf5\uc6d0\uc758 \ucd9c\ubc1c\uc810\uc774 \ub418\uae30\ub3c4 \ud55c\ub2e4. \uc774 \uc791\uc740 \uac00\uad6c\ub97c \ub2e4\uc2dc \ubcf4\uac8c \ub41c\ub2e4\uba74 \uba3c\uc800 \ubb38\uacfc \uc11c\ub78d\uc758 \ubc29\ud5a5\uc744, \ub2e4\uc74c\uc5d0\ub294 \uc0c9\uacfc \uc790\ubb3c\uc1e0\uc758 \ubaa8\uc591\uc744 \uc0b4\ud3b4\ubcf4\uc790. \ube57\uc744 \ubcf4\uad00\ud558\ub294 \uae30\ub2a5 \uc8fc\uc704\uc5d0 \uc5ec\ub7ec \ubc88\uc758 \ub9cc\ub4e4\uae30\uc640 \uafb8\ubbf8\uae30\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \ub204\uac00 \uc5b4\ub290 \uc544\uce68\uc5d0 \uc0ac\uc6a9\ud588\ub294\uc9c0 \uc774\uc57c\uae30\ud558\uc9c0 \uc54a\uc544\ub3c4 \ub0a8\uc740 \ud615\ud0dc\ub294 \uadf8 \ud589\ub3d9\uc744 \uc900\ube44\ud55c \uc190\uc758 \uc0dd\uac01\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ubb3c\uac74\uc744 \uc218\ub0a9\ud558\ub294 \uc0c1\uc790\ub3c4 \uadf8 \uc790\uccb4\ub85c \uc77d\uc744 \uba74\uc774 \ub9ce\ub2e4. \uc774 \ube57\uc811\uc5d0\ub294 \uac70\ubd81\uc774 \ud615\ud0dc\uc758 \uc790\ubb3c\uc1e0\uac00 \ubd99\uc5b4 \uc788\ub2e4\uace0 \ubc15\ubb3c\uad00\uc740 \uc54c\ub824 \uc900\ub2e4. \uc11c\ub78d \uc18d\uc744 \ub2e4 \ud655\uc778\ud558\uc9c0 \uc54a\uc544\ub3c4 \uc774 \uc791\uc740 \ub3d9\ubb3c \ud558\ub098 \ub355\ubd84\uc5d0 \uc0c1\uc790\uc758 \uc778\uc0c1\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uac70\ubd81\uc774 \uc7a5\uc2dd\uc758 \ub73b\uc744 \uc774 \uc790\ub8cc\ub9cc\uc73c\ub85c \ud655\uc815\ud558\uac70\ub098 \uc7a0\uae08\uc7a5\uce58\uc758 \uc131\ub2a5\uc744 \uc9d0\uc791\ud558\uc9c0\ub294 \ub9d0\uc790. \uc5ec\uae30\uc11c \uc990\uae38 \uac83\uc740 \uc218\ub0a9 \uac00\uad6c\uc758 \ud55c\uac00\uc6b4\ub370 \ub3d9\ubb3c\uc758 \ubaa8\uc591\uc744 \ub193\uc558\ub2e4\ub294 \uc120\ud0dd\uc774\ub2e4. \ubd89\uc740 \uc0c1\uc790\ub97c \ub2e4\uc2dc \ubcfc \ub54c \ubb38\uc591\uc774 \ub9ce\uc558\ub2e4\ub294 \uae30\uc5b5\ubcf4\ub2e4, \ube57\uc744 \uc9c0\ud0a4\ub294 \uac70\ubd81\uc774 \uac19\uc558\ub2e4\ub294 \uc778\uc0c1\uc774 \uba3c\uc800 \ub5a0\uc624\ub97c\uc9c0\ub3c4 \ubaa8\ub978\ub2e4."}, {"id": "scent-bead-norigae", "title": "\uc774 \ubaa9\uac78\uc774 \uac19\uc740 \uc7a5\uc2dd\uc740 \uce58\ub9c8 \uc18d\uc5d0 \uc228\uc5c8\ub2e4", "summary": "\uad6c\uc2ac\ucc98\ub7fc \uc774\uc5b4\uc9c4 \uc7a5\uc2e0\uad6c\uac00 \ud5a5\uae30\ub97c \uac04\uc9c1\ud558\ub358 \ubc29\ubc95\uc744 \ub4e4\uc5ec\ub2e4\ubd05\ub2c8\ub2e4.", "category": "life", "category_title": "Life", "subcategory": "Clothing", "url": "stories/scent-bead-norigae/index.html", "image": "media/scent-bead-norigae.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc904\ud5a5\ub178\ub9ac\uac1c \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc774 \ubaa9\uac78\uc774 \uac19\uc740 \uc7a5\uc2dd\uc740 \uce58\ub9c8 \uc18d\uc5d0 \uc228\uc5c8\ub2e4 \ub208\ubcf4\ub2e4 \ucf54\uac00 \uba3c\uc800 \ub9cc\ub098\ub294 \ub178\ub9ac\uac1c \uad6c\uc2ac\ucc98\ub7fc \uc774\uc5b4\uc9c4 \uc7a5\uc2e0\uad6c\uac00 \ud5a5\uae30\ub97c \uac04\uc9c1\ud558\ub358 \ubc29\ubc95\uc744 \ub4e4\uc5ec\ub2e4\ubd05\ub2c8\ub2e4. Clothing \uc0dd\ud65c \uc0ac\uc9c4 \uc18d \ubb3c\uac74\uc740 \uae34 \ubaa9\uac78\uc774\ucc98\ub7fc \ubcf4\uc778\ub2e4. \uc0c9\uc774 \ub2e4\ub978 \uc791\uc740 \uc54c\ub4e4\uc774 \uc904\uc744 \ub530\ub77c \uc774\uc5b4\uc9c0\uace0, \uc544\ub798\uc5d0\ub294 \uc220\uc774 \ub2ec\ub838\ub2e4. \uadf8\ub7f0\ub370 \uc774\ub984\uc740 \ubaa9\uac78\uc774\uac00 \uc544\ub2c8\ub77c \uc904\ud5a5\ub178\ub9ac\uac1c\ub2e4. \uc7a5\uc2e0\uad6c\ub77c\uba74 \ub0a8\uc5d0\uac8c \ubcf4\uc5ec \uc8fc\ub294 \ubb3c\uac74\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uae30 \uc27d\ub2e4. \uc774 \ub178\ub9ac\uac1c\ub294 \uc870\uae08 \ub2e4\ub974\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc5d0\ub294 \uc740\uc740\ud55c \ud5a5\uae30\ub97c \ud48d\uae30\ub3c4\ub85d \uce58\ub9c8 \uc18d\uc5d0 \ucc3c\ub2e4\uace0 \uc801\ud600 \uc788\ub2e4. \ub208\uc5d0 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc790\ub9ac\uc5d0\ub3c4 \uafb8\ubc08\uc774 \uc788\uc5c8\ub358 \uc148\uc774\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc740 \uc904\ud5a5\uc744 \ud5a5\uc73c\ub85c \ub9cc\ub4e0 \ub465\uadfc \uc54c\uc744 \uc774\uc5b4 \ub193\uc740 \uac83\uc73c\ub85c \uc124\uba85\ud55c\ub2e4. \ud5a5\uc744 \uad6c\uc2ac \ubaa8\uc591\uc73c\ub85c \ube5a\uc5b4 \uc0c9\uc744 \uce60\ud558\uac70\ub098 \ucc9c\uc73c\ub85c \uc2f8\uc11c, \uc5fc\uc8fc\ucc98\ub7fc \uc5f0\uacb0\ud558\ub294 \ubc29\uc2dd\uc774\ub2e4. \uc774 \uc18c\uc7a5\ud488\uc758 \uc124\uba85\uc5d0\ub294 \ubd89\uc740\uc0c9\uacfc \ud669\uc0c9, \ub179\uc0c9, \ud770\uc0c9\uc774 \ub4f1\uc7a5\ud55c\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \uc0c9\uc744 \ucc3e\ub2e4 \ubcf4\uba74 \ucc98\uc74c\uc5d0\ub294 \uadf8\uc800 \uc608\uc05c \uad6c\uc2ac\uc774\ub77c\uace0 \uc5ec\uacbc\ub358 \ubd80\ubd84\uc744 \ub2e4\uc2dc \ubcf4\uac8c \ub41c\ub2e4. \ubaa8\uc591\ubfd0 \uc544\ub2c8\ub77c \ud5a5\uae30\ub97c \ud568\uaed8 \uc0dd\uac01\ud574\uc57c \ud558\ub294 \ubb3c\uac74\uc774\ub2e4. \ub178\ub9ac\uac1c\ub294 \uc800\uace0\ub9ac \uace0\ub984\uc774\ub098 \uce58\ub9c8\ud5c8\ub9ac \ub048\uc5d0 \ucc28\ub294 \uc7a5\uc2e0\uad6c\ub2e4. \uc904\ud5a5\ub178\ub9ac\uac1c \uc5ed\uc2dc \uc637\uacfc \ud568\uaed8 \uc4f0\uc600\uc9c0\ub9cc, \ubc15\ubb3c\uad00\uc740 \uce58\ub9c8 \uc18d\uc5d0 \ucc28\ub294 \uc4f0\uc784\uc744 \ub530\ub85c \uc18c\uac1c\ud55c\ub2e4. \uac89\uc73c\ub85c \ub4dc\ub7ec\ub098\ub294 \uc7a5\uc2dd\uacfc \ud5a5\uae30\ub97c \uac00\uae4c\uc774 \ub450\ub294 \uc77c\uc740 \uaf2d \uac19\uc744 \ud544\uc694\uac00 \uc5c6\uc5c8\ub2e4. \uc624\ub298\ub0a0 \ud5a5\uc218\ub97c \ubfcc\ub9ac\ub294 \uc77c\uacfc \ub098\ub780\ud788 \ub5a0\uc62c\ub9b4 \uc218\ub294 \uc788\ub2e4. \ub2e4\ub9cc \uc774 \ubb3c\uac74\uc5d0 \uc5b4\ub5a4 \ud5a5 \uc7ac\ub8cc\uac00 \ub4e4\uc5b4\uac14\ub294\uc9c0, \ud5a5\uc774 \uc5bc\ub9c8\ub098 \uc624\ub798\uac14\ub294\uc9c0\uae4c\uc9c0 \ud655\uc778\ub41c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc0ac\uc9c4\ub9cc \ubcf4\uace0 \uaf43\ud5a5\uae30\uc600\uc744 \uac83\uc774\ub77c\uace0 \uc815\ud574 \ubc84\ub9ac\uba74 \uc774\uc57c\uae30\uac00 \ubb3c\uac74\ubcf4\ub2e4 \uc55e\uc11c \ub098\uac04\ub2e4. \uc7a5\uc2e0\uad6c\ub294 \ub0a8\uc5d0\uac8c \ubcf4\uc774\ub294 \ubb3c\uac74\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uae30 \uc27d\ub2e4. \uc904\ud5a5\ub178\ub9ac\uac1c\ub294 \ud5a5\uc744 \uac00\uae4c\uc774 \ub450\ub294 \uc4f0\uc784\uc744 \ud1b5\ud574 \uadf8 \uc0dd\uac01\uc744 \uc870\uae08 \ub113\ud78c\ub2e4. \uce58\ub9c8 \uc18d\uc5d0 \ucc3c\ub2e4\ub294 \uc124\uba85\uc740 \ubc18\ub4dc\uc2dc \ubc16\uc73c\ub85c \ub4dc\ub7ec\ub098\uc57c\ub9cc \uc7a5\uc2dd\uc774 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc785\uc740 \uc0ac\ub78c\uc774 \ub290\ub07c\ub294 \uac10\uac01\uacfc \ub2e4\ub978 \uc0ac\ub78c\uc774 \ubcf4\ub294 \ubaa8\uc2b5\uc740 \ub2e4\ub97c \uc218 \uc788\uc5c8\ub2e4. \ud5a5\uc744 \uc0ac\uc6a9\ud588\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ub2f9\uc2dc \ucc29\uc6a9\uc790\uc758 \uac10\uc815\uc744 \ub300\uc2e0 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc2dc\uc6d0\ud588\uc744\uc9c0 \ud3b8\uc548\ud588\uc744\uc9c0, \uc5b4\ub290 \uc21c\uac04 \ud5a5\uc744 \ub9e1\uc558\uc744\uc9c0\uae4c\uc9c0\ub294 \ud655\uc778\ub418\uc9c0 \uc54a\ub294\ub2e4. \uadf8\ub807\uc9c0\ub9cc \uc2dc\uac01 \uc678\uc758 \uac10\uac01\uc744 \uace0\ub824\ud55c \ubb3c\uac74\uc774\ub77c\ub294 \uc810\uc740 \ubd84\uba85\ud55c \uad00\uc2ec\uac70\ub9ac\uac00 \ub41c\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c\ub294 \uc804\ud574\uc9c0\uc9c0 \uc54a\ub294 \uae30\ub2a5\uc744 \ud574\uc124\uc774 \uc54c\ub824 \uc8fc\ub294 \uc0ac\ub840\ub2e4. \ub465\uadfc \uc54c\uc744 \uc774\uc5b4 \ub193\uc73c\uba74 \uc904\uc758 \uae38\uc774\uc640 \uad6c\uc2ac\uc758 \ubc18\ubcf5\uc774 \ud558\ub098\uc758 \ud615\ud0dc\ub97c \ub9cc\ub4e0\ub2e4. \ud5a5\uc744 \ube5a\uace0 \uc0c9\uc744 \uce60\ud558\uac70\ub098 \ucc9c\uc73c\ub85c \uc2f8\ub294 \uc81c\uc791 \ubc29\uc2dd\uc740 \ub2e8\uc21c\ud55c \uac00\ub8e8\ub97c \ub2f4\uc544 \ub193\ub294 \uac83\uacfc \ub2e4\ub978 \ubaa8\uc591\uc744 \uc900\ub2e4. \uc7ac\ub8cc\uc758 \uc131\uc9c8\uc744 \ud2b9\uc815\ud55c \ubab8 \uc7a5\uc2dd\uc73c\ub85c \uc0ac\uc6a9\ud560 \uc218 \uc788\uac8c \ubc14\uafbc \uac83\uc774\ub2e4. \uc190\uc73c\ub85c \ub9cc\ub4dc\ub294 \uacfc\uc815\uacfc \ucc29\uc6a9\uc758 \ubc29\uc2dd\uc774 \uc11c\ub85c \uc5f0\uacb0\ub41c\ub2e4. \ub2e4\ub9cc \uc774 \uc18c\uc7a5\ud488\uc5d0 \uc4f0\uc778 \ubaa8\ub4e0 \uc6d0\ub8cc\uc640 \ubc30\ud569, \uc81c\uc791 \uc21c\uc11c\ub97c \uc0c1\uc138\ud788 \uc54c \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc77c\ubc18\uc801\uc778 \uc904\ud5a5 \uc124\uba85\uacfc \uc774 \ubb3c\uac74\uc5d0\uc11c \ud655\uc778\ud55c \ud2b9\uc9d5\uc744 \ub098\ub204\uc5b4 \uc77d\uc73c\uba74 \ub41c\ub2e4. \ud654\ub824\ud55c \uc0c9\uc774 \ubcf4\uc778\ub2e4\uace0 \ud2b9\uc815\ud55c \uaf43\uc774\ub098 \uc57d\uc7ac\uc758 \uc774\ub984\uc744 \ubd99\uc774\uc9c0 \uc54a\ub294\ub2e4. \ubaa8\uc591\uacfc \uc0c9\uc5d0 \uad00\ud55c \uc815\ubcf4\uac00 \ud5a5\uc758 \uc885\ub958\ub97c \uc790\ub3d9\uc73c\ub85c \uc54c\ub824 \uc8fc\uc9c0\ub294 \uc54a\uae30 \ub54c\ubb38\uc774\ub2e4. \ubd89\uc740\uc0c9\uacfc \ud669\uc0c9, \ub179\uc0c9\uacfc \ud770\uc0c9\uc774\ub77c\ub294 \uad6c\ubd84\uc740 \uc0ac\uc9c4\uc758 \uc904\uc744 \ucc9c\ucc9c\ud788 \ub530\ub77c\uac00\uac8c \ud55c\ub2e4. \uc791\uc740 \uc54c\ub4e4\uc774 \uac19\uc740 \ubaa8\uc591\ub9cc \ubc18\ubcf5\ud558\ub294\uc9c0, \uc0c9\uc774 \uc5b4\ub290 \uc21c\uc11c\ub85c \ub193\uc600\ub294\uc9c0 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \uc790\ub8cc\uac00 \uc54c\ub824 \uc8fc\ub294 \uc0c9\uc744 \uae30\uc900\uc73c\ub85c \ubcf4\ub418 \ucd2c\uc601\uacfc \ud654\uba74\uc5d0\uc11c \uc0c9\uc774 \ub2ec\ub77c \ubcf4\uc77c \uc218 \uc788\ub2e4\ub294 \uc810\ub3c4 \uae30\uc5b5\ud558\uba74 \uc88b\ub2e4. \ub208\uc55e\uc758 \uc0ac\uc9c4\uc774 \ucc98\uc74c \uc81c\uc791\ud55c \ub0a0\uc758 \uc0c9\uc744 \uc644\uc804\ud788 \ub418\uc0b4\ub9ac\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uce58\ub9c8 \uc18d\uc774\ub77c\ub294 \uc4f0\uc784\uacfc \uc0c9\uc758 \uafb8\ubc08\uc744 \ud568\uaed8 \ub193\uc73c\uba74 \ub610 \ub2e4\ub978 \uc9c8\ubb38\uc774 \uc0dd\uae34\ub2e4. \ubcf4\uc774\uc9c0 \uc54a\uc744 \uc218 \uc788\ub294 \ubd80\ubd84\uc5d0\ub3c4 \uc0ac\ub78c\ub4e4\uc774 \ud615\uc0c1\uacfc \uc0c9\uc744 \ub9c8\ub828\ud588\ub2e4\ub294 \uac83\uc774\ub2e4. \uc774\uac83\uc744 \uc0ac\uce58\ub098 \ube44\ubc00\uc2a4\ub7ec\uc6b4 \ud48d\uc2b5 \ud558\ub098\ub85c \ub2e8\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ubb3c\uac74\uc744 \uace0\ub974\uace0 \ub9cc\ub4dc\ub294 \uc0ac\ub78c\uc5d0\uac8c \ubc14\uae65\uc758 \uc2dc\uc120\ub9cc\uc774 \uc720\uc77c\ud55c \uae30\uc900\uc740 \uc544\ub2c8\uc5c8\uc744 \uc218 \uc788\uc74c\uc744 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ubaa8\uc591\uc774 \ub2ee\uc740 \uc624\ub298\uc758 \ubb3c\uac74\uc744 \ub5a0\uc62c\ub9ac\ub294 \uc77c\uc740 \uc774\ud574\ub97c \ub3d5\uc9c0\ub9cc \uc4f0\uc784\uc744 \ud655\uc815\ud558\ub294 \uadfc\uac70\uac00 \ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \ubaa9\uac78\uc774 \uac19\uc544 \ubcf4\uc778\ub2e4\ub294 \uccab \uac10\uc0c1 \ub4a4\uc5d0 \ubc15\ubb3c\uad00\uc758 \uba85\uce6d\uacfc \ucc29\uc6a9 \uc124\uba85\uc744 \ub193\uc73c\uba74 \ub2e4\ub978 \uc0dd\ud65c\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \uc775\uc219\ud55c \ud615\ud0dc\ub97c \ubc1c\uacac\ud55c \ub2e4\uc74c \ub0af\uc120 \uc0ac\uc6a9\ubc95\uc744 \ubc30\uc6b0\ub294 \uc21c\uc11c\ub2e4. \uc720\ubb3c\uc744 \uac00\uae4c\uc774 \ubcf4\ub294 \uc7ac\ubbf8\uac00 \uc5ec\uae30\uc5d0 \uc788\ub2e4. \ub178\ub9ac\uac1c\ub294 \uc637\uacfc \ubab8, \uc6c0\uc9c1\uc784\uacfc \uac10\uac01\uc774 \ub9cc\ub098\ub294 \ub3c4\uad6c\ub2e4. \uc804\uc2dc\uc7a5\uc5d0\uc11c\ub294 \uc815\uc9c0\ud55c \uc904\ub9cc \ubcf4\uc5ec\ub3c4 \uc6d0\ub798\ub294 \ucc29\uc6a9\ud558\ub294 \uc0ac\ub78c\uacfc \uad00\uacc4\ub97c \ub9fa\uc5c8\ub358 \ubb3c\uac74\uc774\uc5c8\ub2e4. \ud5a5\uc774 \uc9c0\uae08\ub3c4 \ub09c\ub2e4\uace0 \ud655\uc778\ud558\uc9c0\ub294 \uc54a\uc73c\uba74\uc11c \uadf8 \uae30\ub2a5\uc758 \uae30\ub85d\uc744 \uc77d\uc744 \uc218 \uc788\ub2e4. \uc0ac\uc9c4\uc73c\ub85c\ub294 \ub9e1\uc744 \uc218 \uc5c6\ub294 \uc7a5\uc2dd\uc758 \ud55c \uba74\uc774 \uc791\uc740 \uad6c\uc2ac\ub4e4 \uc0ac\uc774\uc5d0\uc11c \ub5a0\uc624\ub978\ub2e4. \uc774 \ub178\ub9ac\uac1c\uc758 \uc7ac\ubbf8\ub294 \uc4f0\uc784\uc744 \uc54c\uace0 \ub098\uc11c \ubaa8\uc2b5\uc774 \ub2ec\ub77c \ubcf4\uc778\ub2e4\ub294 \ub370 \uc788\ub2e4. \uae38\uac8c \uc774\uc5b4\uc9c4 \uc54c\ub4e4\uc740 \uc0c9\uc744 \ub098\ub204\ub294 \uc7a5\uc2dd\uc778 \ub3d9\uc2dc\uc5d0 \ud5a5\uc744 \uac04\uc9c1\ud558\ub294 \ubd80\ubd84\uc774\uc5c8\ub2e4. \uc9c0\uae08 \uc0ac\uc9c4\uc5d0\uc11c\ub294 \ud5a5\uae30\ub97c \ub9e1\uc744 \uc218 \uc5c6\ub2e4. \uadf8\ub798\ub3c4 \uce58\ub9c8 \uc18d\uc5d0 \ub2ec\uc558\ub2e4\ub294 \uc9e7\uc740 \uc124\uba85 \ub355\ubd84\uc5d0, \uc624\ub798\ub41c \uc7a5\uc2e0\uad6c\uac00 \uc720\ub9ac\uc7a5 \uc548\uc758 \ubc18\uc9dd\uc774\ub294 \ubb3c\uac74\uc5d0\uc11c \uc77c\uc0c1 \uac00\uae4c\uc774\ub85c \ub0b4\ub824\uc628\ub2e4. \uc61b\uc0ac\ub78c\ub3c4 \uc790\uc2e0\uc758 \ubab8 \uac00\uae4c\uc774\uc5d0 \uae30\ubd84 \uc88b\uc740 \ubb34\uc5c7\uc744 \ub450\uace0 \uc2f6\uc5c8\ub358 \ubaa8\uc591\uc774\ub2e4."}, {"id": "three-sisters-garden", "title": "\uc625\uc218\uc218\uc640 \ucf69, \ud638\ubc15\uc740 \uc65c \uc138 \uc790\ub9e4\uc77c\uae4c", "summary": "\ud55c \ubc2d\uc5d0\uc11c \ud568\uaed8 \uc790\ub77c\ub294 \uc791\ubb3c\ub4e4\uc774 \uc11c\ub85c \ub3d5\ub294 \ubc29\uc2dd\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "life", "category_title": "Life", "subcategory": "Food", "url": "stories/three-sisters-garden/index.html", "image": "media/three-sisters-garden.jpg", "alt": "\uad50\uc7ac\uac00 \uc138 \uc790\ub9e4 \uc7ac\ubc30\uc758 \uc218\ud655 \uc608\ub85c \uc81c\uc2dc\ud55c Sterling College \uc0ac\uc9c4. \uc5ec\ub7ec \uc0ac\ub78c\ub4e4\uc774 \uc625\uc218\uc218\uc640 \ub2e4\uc591\ud55c \uc218\ud655\ubb3c\uc744 \uc0b4\ud3b4\ubcf4\uace0 \uc788\uc2b5\ub2c8\ub2e4.", "text": "\uc625\uc218\uc218\uc640 \ucf69, \ud638\ubc15\uc740 \uc65c \uc138 \uc790\ub9e4\uc77c\uae4c \ubd81\ubbf8 \ubc2d\uc5d0\uc11c \ub9cc\ub098\ub294 \uc11c\ub85c \ub2e4\ub978 \uc138 \uac00\uc9c0 \uc5ed\ud560 \ud55c \ubc2d\uc5d0\uc11c \ud568\uaed8 \uc790\ub77c\ub294 \uc791\ubb3c\ub4e4\uc774 \uc11c\ub85c \ub3d5\ub294 \ubc29\uc2dd\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Food \uc0dd\ud65c \uc625\uc218\uc218\uc640 \ucf69, \ud638\ubc15\uc744 \ud55c\uc790\ub9ac\uc5d0 \ub193\uc73c\uba74 \uc7a5\ubcf4\uae30 \ubaa9\ub85d\ucc98\ub7fc \ubcf4\uc778\ub2e4. \uadf8\ub7f0\ub370 \ubd81\ubbf8\uc758 \uc5ec\ub7ec \uc6d0\uc8fc\ubbfc \uc7ac\ubc30 \uc804\ud1b5\uc5d0\uc11c\ub294 \uc774 \uc870\ud569\uc744 \uc138 \uc790\ub9e4\ub77c\uace0 \ubd80\ub978\ub2e4. \ud568\uaed8 \uba39\ub294 \uc74c\uc2dd\uc77c \ubfd0 \uc544\ub2c8\ub77c \ud568\uaed8 \uc790\ub77c\ub3c4\ub85d \ub450\ub294 \uc791\ubb3c\ub4e4\uc774\ub2e4. OpenStax \uad50\uc7ac\ub294 \uadf8\uc911 \ud558\uc6b0\ub370\ub178\uc1fc\ub2c8\uc758 \uc0ac\ub840\ub97c \uc124\uba85\ud55c\ub2e4. \uc9c0\uae08\uc758 \ub274\uc695\uc8fc \ubd81\ubd80 \uc9c0\uc5ed\uacfc \uc774\uc5b4\uc9c0\ub294 \uc774 \uacf5\ub3d9\uccb4\ub294 \uc625\uc218\uc218\uc640 \ucf69, \ud638\ubc15\uc744 \uc791\uc740 \ub454\ub355\uc5d0\uc11c \ud568\uaed8 \uae38\ub800\ub2e4. \ube60\ub974\uac8c \uc790\ub77c\ub294 \uc625\uc218\uc218\ub294 \ub369\uad74\ucf69\uc774 \ud0c0\uace0 \uc62c\ub77c\uac08 \uc9c0\uc9c0\ub300\uac00 \ub41c\ub2e4. \ubc2d\uc5d0 \ub530\ub85c \uae30\ub465\ub9cc \uc138\uc6b0\ub294 \ub300\uc2e0 \ub2e4\ub978 \uc791\ubb3c\uc758 \uc904\uae30\uac00 \uadf8 \uc790\ub9ac\ub97c \ub9e1\ub294 \uac83\uc774\ub2e4. \ubc18\ub300\ub85c \ucf69\uc740 \uc138\uade0\uacfc\uc758 \uad00\uacc4\ub97c \ud1b5\ud574 \ud1a0\uc591\uc5d0 \uc9c8\uc18c\ub97c \ub354\ud558\ub294 \ub370 \ub3c4\uc6c0\uc744 \uc900\ub2e4. \uc9c8\uc18c\ub97c \ud544\uc694\ub85c \ud558\ub294 \uc8fc\ubcc0 \uc791\ubb3c\ub4e4\uacfc \uc5f0\uacb0\ub418\ub294 \uc5ed\ud560\uc774\ub2e4. \uc138 \uc790\ub9e4\ub77c\ub294 \uc774\ub984\uc744 \uc54c\uace0 \ubcf4\uba74 \ud55c \uc2dd\ubb3c\uc774 \uc790\uae30 \uc790\ub9ac\ub9cc \ucc28\uc9c0\ud558\uace0 \uc788\ub294 \uac83\uc774 \uc544\ub2d8\uc744 \ub290\ub07c\uac8c \ub41c\ub2e4. \ud638\ubc15\uc740 \ud070 \uc78e\uacfc \ub369\uad74\ub85c \ub545\uc744 \ub36e\ub294\ub2e4. \uad50\uc7ac\ub294 \uc774 \ub36e\uac1c\uac00 \uc7a1\ucd08\ub97c \uc5b5\uc81c\ud558\uace0 \ud759\uc758 \uc218\ubd84\uc744 \uc9c0\ud0a4\uba70 \uce68\uc2dd\uc744 \uc904\uc774\ub294 \ub370 \ub3c4\uc6c0\uc744 \uc900\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc625\uc218\uc218\uac00 \uc704\ub85c \uc790\ub784 \ub3d9\uc548 \uc544\ub798\ucabd\uc5d0\uc11c\ub294 \ub610 \ub2e4\ub978 \uc77c\uc774 \uc77c\uc5b4\ub098\ub294 \uc148\uc774\ub2e4. \uc5ec\uae30\uc11c \uc911\uc694\ud55c \uac83\uc740 \ubaa8\ub4e0 \uc885\ub958\ub97c \uc544\ubb34\ub807\uac8c\ub098 \uc11e\uc73c\uba74 \ub41c\ub2e4\ub294 \ub9d0\uc774 \uc544\ub2c8\ub2e4. \ud2b9\uc815 \uc791\ubb3c\uacfc \uc7ac\ubc30 \ubc29\uc2dd\uc5d0 \uad00\ud55c \uc0ac\ub840\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc2dd\ubb3c\uc758 \uc131\uc9c8\uc744 \uc54c\uace0 \ubc30\uce58\ud574 \uc628 \uc9c0\uc2dd\uc774 \uadf8 \uc548\uc5d0 \uc788\ub2e4. \uc625\uc218\uc218\ub294 \uc704\ub85c \uc790\ub77c\uace0 \ucf69\uc740 \uae30\ub300\uc5b4 \uc624\ub974\uba70 \ud638\ubc15\uc740 \ub545 \uac00\uae4c\uc774 \ub113\uac8c \ud37c\uc9c4\ub2e4. \uc138 \uc791\ubb3c\uc758 \uc11c\ub85c \ub2e4\ub978 \ud615\ud0dc\uac00 \uac19\uc740 \ubc2d\uc5d0\uc11c \ub2e4\ub978 \uc790\ub9ac\ub97c \ub9e1\ub294\ub2e4. \uac19\uc740 \ub192\uc774\uc5d0\uc11c \ub611\uac19\uc774 \uacbd\uc7c1\ud558\ub294 \ubaa8\uc2b5\ub9cc \uc0c1\uc0c1\ud588\uc744 \ub54c\ubcf4\ub2e4 \uad00\uacc4\uac00 \uad6c\uccb4\uc801\uc73c\ub85c \ubcf4\uc778\ub2e4. \ud63c\uc791\uc740 \ub2e8\uc21c\ud788 \uc885\ub958\ub97c \ub9ce\uc774 \uc11e\ub294\ub2e4\ub294 \ub9d0\ubcf4\ub2e4 \ubc30\uce58\uc640 \uc131\uc9c8\uc744 \ud568\uaed8 \uc0dd\uac01\ud558\ub294 \ubc29\uc2dd\uc73c\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ubc2d\ub9c8\ub2e4 \uc5b4\ub5a4 \ud488\uc885\uc744 \uc5b8\uc81c \uc2ec\uace0 \uc5b4\ub290 \uac04\uaca9\uc744 \ub450\ub294\uc9c0\ub294 \ub530\ub85c \uc54c\uc544\uc57c \ud55c\ub2e4. \uad50\uc7ac\uc758 \uc0ac\ub840\ub97c \ubaa8\ub4e0 \ud658\uacbd\uc5d0\uc11c \uac19\uc740 \uacb0\uacfc\uac00 \ub098\ub294 \uc989\uc11d \uc7ac\ubc30\ubc95\uc73c\ub85c \uc0ac\uc6a9\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc11c\ub85c \ub3d5\ub294 \ud6a8\uacfc\uac00 \uc18c\uac1c\ub418\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ub204\uad6c\ub098 \uac19\uc740 \uc218\ud655\uc744 \ubcf4\uc7a5\ubc1b\ub294\ub2e4\ub294 \uc8fc\uc7a5\uc740 \ub2e4\ub974\ub2e4. \uc791\ubb3c\uc758 \uad00\uacc4\ub97c \uc544\ub294 \uc77c\uc774 \uc2e4\uc81c \uc870\uac74\uc744 \uc0b4\ud53c\ub294 \uc77c\uc744 \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc9c8\uc18c\uc640 \uad00\ub828\ub41c \uc124\uba85\uc5d0\ub294 \uc138\uade0\uacfc\uc758 \uad00\uacc4\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \uc2dd\ubb3c \ud558\ub098\uc758 \ub2a5\ub825\ucc98\ub7fc \ubcf4\uc774\ub294 \ud6a8\uacfc \ub4a4\uc5d0\ub3c4 \ub2e4\ub978 \uc0dd\ubb3c\uc758 \ud65c\ub3d9\uc774 \ud568\uaed8 \uc788\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \uc625\uc218\uc218\uc640 \ucf69, \ud638\ubc15\ub9cc\uc73c\ub85c \ubc2d\uc758 \ubaa8\ub4e0 \uad00\uacc4\uac00 \ub05d\ub098\uc9c0\ub294 \uc54a\ub294 \uc148\uc774\ub2e4. \uc791\uc740 \ubc2d\uc5d0\uc11c\ub3c4 \uc5ec\ub7ec \uc0dd\ubb3c\uacfc \ud759\uc758 \uc870\uac74\uc744 \ud568\uaed8 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uc774\uac83\uc744 \ucf69\uc774 \uc989\uc2dc \uc8fc\ubcc0\uc758 \ubaa8\ub4e0 \uc791\ubb3c\uc5d0 \uc815\ud574\uc9c4 \uc591\uc758 \uc601\uc591\uc744 \ub098\ub204\uc5b4 \uc900\ub2e4\ub294 \uadf8\ub9bc\uc73c\ub85c \ub2e8\uc21c\ud654\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc7ac\ubc30\uc758 \uc2dc\uc810\uacfc \uad00\ub9ac, \ud1a0\uc591\uc5d0 \ub530\ub77c \uc2e4\uc81c \uad00\uacc4\ub97c \ud655\uc778\ud560 \ubb38\uc81c\uac00 \uc788\ub2e4. \uc5ec\uae30\uc11c\ub294 \uad50\uc7ac\uac00 \uc124\uba85\ud55c \ud070 \uc6d0\ub9ac\ub97c \ub530\ub77c \uac01 \uc791\ubb3c\uc774 \uc5b4\ub5a4 \uc774\uc810\uacfc \uc5f0\uacb0\ub418\ub294\uc9c0 \uc0b4\ud3b4\ubcf8\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc131\uc9c8\uc744 \uc54c\uace0 \ud568\uaed8 \uc774\uc6a9\ud574 \uc628 \uc9c0\uc2dd\uc5d0 \uad00\uc2ec\uc744 \ub450\ub294 \uac83\uc774\ub2e4. \uad50\uc7ac\ub294 \ud558\uc6b0\ub370\ub178\uc1fc\ub2c8\uc758 \uc0ac\ub840\uc5d0\uc11c \uc138 \uc791\ubb3c\uc774 \uc11c\ub85c \ub5bc\uc5b4 \ub193\uc744 \uc218 \uc5c6\ub294 \uc874\uc7ac\ub85c \uc774\ud574\ub418\uc5c8\ub2e4\ub294 \uae30\ub85d\uc744 \uc18c\uac1c\ud55c\ub2e4. \ub18d\uc0ac\uc758 \ubb3c\ub9ac\uc801\uc778 \uc774\uc810\uacfc \uacf5\ub3d9\uccb4\uc758 \uc774\uc57c\uae30\uc640 \ubbff\uc74c\uc774 \ud568\uaed8 \uc804\ud574\uc84c\ub2e4. \uc0dd\ud0dc\uc801\uc778 \uc124\uba85\ub9cc \ub0a8\uae30\uba74 \uc0ac\ub78c\ub4e4\uc774 \uadf8 \uc791\ubb3c\ub4e4\uc744 \uc5b4\ub5a4 \uad00\uacc4\ub85c \uae30\uc5b5\ud588\ub294\uc9c0 \ub193\uce60 \uc218 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \ud558\ub098\uc758 \uc804\uc2b9\uc744 \ubd81\ubbf8\uc640 \uc911\ubbf8\uc758 \ubaa8\ub4e0 \uacf5\ub3d9\uccb4\uc5d0 \ub611\uac19\uc774 \uc801\uc6a9\ud574\uc11c\ub3c4 \uc548 \ub41c\ub2e4. \uc9c0\uc5ed\uacfc \uc9d1\ub2e8\ub9c8\ub2e4 \uc7ac\ubc30\uc640 \uc774\uc57c\uae30\uac00 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uad50\uc7ac\uac00 \uc5b4\ub5a4 \uc0ac\ub840\ub97c \ub4e4\uace0 \uc788\ub294\uc9c0 \uc774\ub984\uc744 \ub0a8\uaca8 \ub450\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4. \uac19\uc740 \uc791\ubb3c\uc744 \uc0ac\uc6a9\ud588\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uac19\uc740 \ubb38\ud654\uc801 \uc758\ubbf8\ub97c \ubd99\uc600\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uad6c\ubd84\ud560 \uc218 \uc788\ub2e4. \ubcf8\ubb38\uc5d0 \uc2e4\ub9b0 \uc2e4\uc81c \uc0ac\uc9c4\uc740 \uad50\uc7ac\uac00 \uc18c\uac1c\ud558\ub294 \uc138 \uc790\ub9e4 \uc218\ud655\uc758 \uc608\ub2e4. \uc644\uc131\ub41c \uc791\ubb3c\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc7a5\uba74\uc774 \ubaa8\ub4e0 \uc7ac\ubc30 \uacfc\uc815\uc744 \uc9c1\uc811 \ucd2c\uc601\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \ud48d\uc131\ud55c \uacb0\uacfc\ub97c \ubcf4\uace0 \uc904\uae30\uc640 \ub369\uad74\uc758 \uc704\uce58\ub97c \uc0ac\uc9c4 \uc18d\uc5d0 \ub9c8\uc74c\ub300\ub85c \uadf8\ub824 \ub123\uc9c0 \uc54a\uc73c\uba74 \uc790\ub8cc\uc758 \uc5ed\ud560\uc774 \ub354 \uc815\ud655\ud574\uc9c4\ub2e4. \ud574\uc124\uc774 \uc54c\ub824 \uc8fc\ub294 \uad6c\uc870\uc640 \ub208\uc5d0 \ubcf4\uc774\ub294 \uc218\ud655\uc744 \ub098\ub204\uc5b4 \ubcfc \uc218 \uc788\ub2e4. \uc74c\uc2dd\uc758 \uc5ed\uc0ac\ub294 \uc5b4\ub5a4 \uc7ac\ub8cc\ub97c \uba39\uc5c8\ub294\uc9c0\ubfd0 \uc544\ub2c8\ub77c \uc5b4\ub5bb\uac8c \ud568\uaed8 \uae38\ub800\ub294\uc9c0\ub3c4 \ud3ec\ud568\ud55c\ub2e4. \uc138 \uc790\ub9e4\ub77c\ub294 \uc774\ub984\uc744 \uae30\uc5b5\ud588\ub2e4\uba74 \ub2e4\uc74c\uc5d0\ub294 \uc138 \uc791\ubb3c\uc758 \ud06c\uae30\uc640 \uc790\ub77c\ub294 \ubc29\ud5a5\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uce5c\uadfc\ud55c \ubcc4\uba85 \ub4a4\uc5d0 \uad00\ucc30\uacfc \uacbd\ud5d8, \uacf5\ub3d9\uccb4\uc758 \uae30\uc5b5\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4. \ubc2d\uc740 \uc2dd\ubb3c\uc774 \ub098\ub780\ud788 \uc120 \uacf3\uc774\uba74\uc11c \uc11c\ub85c\uc758 \ucc28\uc774\ub97c \uc774\uc6a9\ud55c \uc9c0\uc2dd\uc774 \ub193\uc778 \uacf5\uac04\uc774\uae30\ub3c4 \ud558\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc0ac\uc9c4\uc740 \uad50\uc7ac\uac00 \uc138 \uc790\ub9e4 \uc7ac\ubc30\uc640 \uc218\ud655\uc758 \uc608\ub85c \uc81c\uc2dc\ud55c \uc2e4\uc81c \uc7a5\uba74\uc774\ub2e4. \uc0ac\uc9c4 \uc18d \uc0ac\ub78c\ub4e4\uc744 \ud2b9\uc815 \uc6d0\uc8fc\ubbfc \uacf5\ub3d9\uccb4\uc758 \uad6c\uc131\uc6d0\uc774\ub77c\uace0 \ucd94\uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc0ac\uc9c4\uc758 \uc0ac\ub840\uc640 \uc124\uba85\ud558\ub294 \uc5ed\uc0ac\uc801 \uc7ac\ubc30 \uc804\ud1b5\uc740 \uad6c\ubd84\ud574 \ubcfc \ud544\uc694\uac00 \uc788\ub2e4. \uadf8\ub798\ub3c4 \ubc2d\uc744 \ubcf4\ub294 \uc9c8\ubb38\uc740 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc904\uc744 \uc5bc\ub9c8\ub098 \uace7\uac8c \uc138\uc6e0\ub290\ub0d0\ub9cc\uc774 \uc544\ub2c8\ub77c, \uc606\uc5d0\uc11c \uc790\ub77c\ub294 \uc2dd\ubb3c\uc774 \uc5b4\ub5a4 \ub3c4\uc6c0\uc744 \uc8fc\ub290\ub0d0\ub97c \uc0b4\ud53c\ub294 \uac83\uc774\ub2e4. \uc138 \uc790\ub9e4\ub77c\ub294 \uc774\ub984\uc740 \uc2dd\ubb3c \uc0ac\uc774\uc758 \uad00\uacc4\ub97c \uae30\uc5b5\ud558\uae30 \uc88b\uc740 \uc791\uc740 \uc774\uc57c\uae30\uc774\uae30\ub3c4 \ud558\ub2e4."}, {"id": "victorian-paper-lace-valentine", "title": "\uc61b \uc5f0\uc560\ud3b8\uc9c0\uc5d0\ub294 \uc885\uc774\ub85c \ub9cc\ub4e0 \ub808\uc774\uc2a4\uac00 \uc788\uc5c8\ub2e4", "summary": "\uaf43\uacfc \ucc9c, \uc885\uc774 \ub808\uc774\uc2a4\ub97c \uacb9\uccd0 \ub9cc\ub4e0 \ubc38\ub7f0\ud0c0\uc778 \uce74\ub4dc\uc758 \ubaa8\uc2b5\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "life", "category_title": "Life", "subcategory": "Folks", "url": "stories/victorian-paper-lace-valentine/index.html", "image": "media/victorian-paper-lace-valentine.jpg", "alt": "\uc61b \uc5f0\uc560\ud3b8\uc9c0\uc5d0\ub294 \uc885\uc774\ub85c \ub9cc\ub4e0 \ub808\uc774\uc2a4\uac00 \uc788\uc5c8\ub2e4\uc758 \uc8fc\uc81c\ub97c \ud45c\ud604\ud55c AI \uc124\uba85\uc6a9 \uc0bd\ud654. \uc2e4\uc81c \uc791\ud488\uc774\ub098 \uac74\ucd95\ubb3c\uc744 \uadf8\ub300\ub85c \uc7ac\ud604\ud55c \uc774\ubbf8\uc9c0\uac00 \uc544\ub2d9\ub2c8\ub2e4.", "text": "\uc61b \uc5f0\uc560\ud3b8\uc9c0\uc5d0\ub294 \uc885\uc774\ub85c \ub9cc\ub4e0 \ub808\uc774\uc2a4\uac00 \uc788\uc5c8\ub2e4 \ubbf8\uad6d\uc758 \uce74\ub4dc \uc81c\uc791\uc790\uac00 \uafb8\ubbfc \uc791\uc740 \uaf43\ubc14\uad6c\ub2c8 \uaf43\uacfc \ucc9c, \uc885\uc774 \ub808\uc774\uc2a4\ub97c \uacb9\uccd0 \ub9cc\ub4e0 \ubc38\ub7f0\ud0c0\uc778 \uce74\ub4dc\uc758 \ubaa8\uc2b5\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Folks \uc0dd\ud65c \ucd95\ud558 \uce74\ub4dc \ud55c \uc7a5\uc744 \uc5f4\uc5c8\ub294\ub370 \uc885\uc774\uaf43\uacfc \ucc9c \uc870\uac01\uc774 \uce35\uce35\uc774 \ubd99\uc5b4 \uc788\ub2e4\uba74 \uc5b4\ub5a8\uae4c. \ud3b8\uc9c0\ub97c \uc77d\uae30 \uc804\uc5d0 \uba3c\uc800 \uc791\uc740 \uacf5\uc608\ud488\uc744 \ud3bc\uccd0 \ubcf4\ub294 \ub290\ub08c\uc77c \uac83\uc774\ub2e4. 19\uc138\uae30 \ubc38\ub7f0\ud0c0\uc778 \uce74\ub4dc \uc911\uc5d0\ub294 \uc2e4\uc81c\ub85c \uadf8\ub7f0 \ubb3c\uac74\ub4e4\uc774 \uc788\uc5c8\ub2e4. \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc740 \ube45\ud1a0\ub9ac\uc544 \uc2dc\ub300\uc758 \ubc38\ub7f0\ud0c0\uc778 \uce74\ub4dc\ub97c 2\ucc9c \uc810 \ub118\uac8c \uc18c\uc7a5\ud55c \uceec\ub809\uc158\uc744 \uc18c\uac1c\ud55c\ub2e4. \uc778\uc1c4\ub41c \ud55c \uc904\ub9cc \uc788\ub294 \uce74\ub4dc\uac00 \uc544\ub2c8\ub77c \uc885\uc774 \ub808\uc774\uc2a4\uc640 \ucc9c, \uc778\uc870 \uaf43\uc744 \ub354\ud55c \uce74\ub4dc\ub4e4\uc774 \ud568\uaed8 \uc788\ub2e4. \ub2f9\uc2dc\uc758 \uce74\ub4dc\ub294 \ud615\ud0dc\uac00 \ub2e4\uc591\ud588\ub2e4. \uc775\uc0b4\uc2a4\ub7ec\uc6b4 \uc8fc\uc81c\ub97c \uc778\uc1c4\ud55c \uac12\uc2fc \uce74\ub4dc\ub3c4 \uc788\uc5c8\uace0, \uc5ec\ub7ec \uc7ac\ub8cc\ub97c \ubd99\uc5ec \uc785\uccb4\uc801\uc73c\ub85c \ub9cc\ub4e0 \uce74\ub4dc\ub3c4 \uc788\uc5c8\ub2e4\uace0 \ud55c\ub2e4. \ub204\uad6c\ub098 \uac19\uc740 \ubaa8\uc591\uc73c\ub85c \ub9c8\uc74c\uc744 \uc804\ud588\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc885\uc774\ub97c \uc624\ub824 \ub9cc\ub4e0 \ub808\uc774\uc2a4\ub294 \ube48 \uacf5\uac04\uae4c\uc9c0 \uc7a5\uc2dd\uc774 \ub41c\ub2e4. \uaf43\uc744 \ud3c9\uba74\uc5d0 \uadf8\ub9ac\ub294 \ub300\uc2e0 \uc885\uc774\uc640 \ucc9c\uc73c\ub85c \ub9cc\ub4e4\uc5b4 \ubd99\uc774\uba74 \uce74\ub4dc\uc758 \ud45c\uba74\uc5d0\ub3c4 \ub192\ub0ae\uc774\uac00 \uc0dd\uae34\ub2e4. \ubc1b\ub294 \uc0ac\ub78c\uc740 \ubb38\uc7a5\ub9cc \uc77d\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uacb9\uce5c \uc7ac\ub8cc\ub97c \ud568\uaed8 \ubcf4\uac8c \ub41c\ub2e4. \ubbf8\uc220\uad00\uc758 \uc124\uba85\uc740 \ubbf8\uad6d \ub9e4\uc0ac\ucd94\uc138\uce20\uc8fc \uc6b0\uc2a4\ud130\uc5d0\uc11c \uc77c\ud55c \uce74\ub4dc \uc81c\uc791\uc790 \uc5d0\uc2a4\ud130 \ud558\uc6b8\ub79c\ub4dc\ub97c \uc18c\uac1c\ud55c\ub2e4. \uadf8\ub294 1849\ub144\uc5d0 \uc790\uc2e0\uc758 \ud68c\uc0ac\ub97c \uc5f4\uc5c8\uace0 \uc5ec\uc131\ub4e4\uc744 \uace0\uc6a9\ud588\ub2e4\uace0 \ud55c\ub2e4. \ud2b9\ud788 \uc778\uae30\ub97c \ub048 \uac83\uc740 \uba54\uc774 \ubc14\uc2a4\ucf13\uc774\ub77c\ub294 \uaf43\ubc14\uad6c\ub2c8 \ud615\ud0dc\uc758 \uce74\ub4dc\uc600\ub2e4. \uc885\uc774 \ub808\uc774\uc2a4 \uac00\uc6b4\ub370 \ucee4\ub2e4\ub780 \uc624\ub824 \ub0b8 \ubc14\uad6c\ub2c8\ub97c \ub450\uace0, \uc548\uc5d0\ub294 \uc885\uc774\uc640 \ucc9c\uc73c\ub85c \ub9cc\ub4e0 \uaf43\ub4e4\uc744 \ube7d\ube7d\ud558\uac8c \ubaa8\uc558\ub2e4. \ubbf8\uc220\uad00\uc740 \uc774\ub7f0 \uce74\ub4dc \ub450 \uc810\uc744 \uc18c\uc7a5\ud558\uace0 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc885\uc774 \ub808\uc774\uc2a4\ub294 \uc120\uc744 \ub0a8\uae30\ub294 \uac83\ub9cc \uc544\ub2c8\ub77c \uc0ac\uc774\ub97c \uc624\ub824 \ube44\uc6b0\uba74\uc11c \ubb34\ub2ac\ub97c \ub9cc\ub4e0\ub2e4. \ubc1d\uc740 \uba74\uc744 \ucc44\uc6b4 \uadf8\ub9bc\uacfc \ub2ec\ub9ac \ube48\uacf3 \ub108\uba38\ub85c \ub2e4\ub978 \uc7ac\ub8cc\uac00 \ubcf4\uc77c \uc218 \uc788\ub2e4. \uadf8\ub798\uc11c \uc5ec\ub7ec \uce35\uc774 \uacb9\uce58\uba74 \uc791\uc740 \uadf8\ub9bc\uc790\uc640 \ub192\ub0ae\uc774\uac00 \uc0dd\uae34\ub2e4. \uce74\ub4dc\ub294 \uc190\uc5d0 \ub4e4\uace0 \uc77d\ub294 \ubb38\uc7a5\uc774\uba74\uc11c \uacf5\uac04\uc744 \uac00\uc9c4 \uacf5\uc608\ud488\uc774 \ub41c\ub2e4. \uc774\ub7f0 \ud45c\uba74\uc744 \uc0ac\uc9c4\uc73c\ub85c \ubcfc \ub54c\uc5d0\ub294 \uaf43\ubd80\ud130 \ucc3e\uc740 \ub4a4 \uac00\uc7a5\uc790\ub9ac\ub97c \ub530\ub77c\uac00 \ubcf4\uc790. \ubb34\uc5c7\uc744 \uc778\uc1c4\ud588\uace0 \ubb34\uc5c7\uc744 \uc798\ub77c \ubd99\uc600\ub294\uc9c0 \uad6c\ubcc4\ud560 \uc218 \uc788\ub2e4\uba74 \uc81c\uc791 \uacfc\uc815\uc774 \uc870\uae08 \ub354 \uad6c\uccb4\uc801\uc73c\ub85c \ub290\uaef4\uc9c4\ub2e4. \ub2e4\ub9cc \uc0ac\uc9c4\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uc811\ucc29 \uc21c\uc11c\uc640 \uc791\uc5c5 \uc2dc\uac04\uc744 \ud655\uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc644\uc131\ub41c \ud615\ud0dc\uc5d0\uc11c \ub0a8\uc740 \uce35\uc758 \uad00\uacc4\ub97c \uc0b4\ud53c\ub294 \uac83\uc774 \uba3c\uc800\ub2e4. \uc5ec\ub7ec \uc7ac\ub8cc\ub97c \ubd99\uc5ec \ud310\ub9e4\ud55c \uce74\ub4dc\ub294 \uc644\uc804\ud788 \uac1c\uc778\uc801\uc778 \ud3b8\uc9c0\uc640 \uae30\uc131 \uc0c1\ud488\uc758 \uacbd\uacc4\uc5d0 \ub193\uc778\ub2e4. \uac19\uc740 \ubaa8\uc591\uc744 \uc5ec\ub7ec \uc0ac\ub78c\uc774 \uad6c\uc785\ud560 \uc218 \uc788\uc5b4\ub3c4 \ubc1b\uc740 \uc0ac\ub78c\uc740 \uadf8\uac83\uc744 \uc790\uae30\uc5d0\uac8c \uc628 \ubb3c\uac74\uc73c\ub85c \uc77d\ub294\ub2e4. \uc0c1\ud488\uc73c\ub85c \uc81c\uc791\ud558\ub294 \uacfc\uc815\uacfc \uad00\uacc4 \uc548\uc5d0\uc11c \uc0ac\uc6a9\ud558\ub294 \uacbd\ud5d8\uc774 \uacb9\uce5c\ub2e4. \ub9c8\uc74c\uc744 \uc804\ud558\ub294 \uc77c\uc5d0 \ubb3c\uac74\uc744 \ub9cc\ub4dc\ub294 \uc0b0\uc5c5\uc774 \ucc38\uc5ec\ud55c \uac83\uc774\ub2e4. \ud558\uc6b8\ub79c\ub4dc\uac00 \ud68c\uc0ac\ub97c \uc138\uc6b0\uace0 \uc5ec\uc131\uc744 \uace0\uc6a9\ud588\ub2e4\ub294 \uc124\uba85\ub3c4 \uc774 \uad00\uc810\uc5d0\uc11c \ubcfc \uc218 \uc788\ub2e4. \ud55c \uc0ac\ub78c\uc774 \uc9d1\uc5d0\uc11c \uc6b0\uc5f0\ud788 \ub9cc\ub4e0 \uce74\ub4dc\ub9cc\uc758 \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub77c \uc870\uc9c1\ud574\uc11c \uc5ec\ub7ec \uc7a5\uc744 \uc81c\uc791\ud55c \uc5ed\uc0ac\ub2e4. \ub2e4\ub9cc \uc774 \uc815\ubcf4\ub9cc\uc73c\ub85c \uace0\uc6a9\ud55c \ubaa8\ub4e0 \uc5ec\uc131\uc758 \uacbd\ud5d8\uc774\ub098 \uadfc\ubb34 \uc870\uac74\uc744 \ubbf8\ud654\ud560 \uc218\ub294 \uc5c6\ub2e4. \ud655\uc778\ub41c \uc0ac\uc5c5\uc758 \ud615\ud0dc\uc640 \uc544\uc9c1 \uc54c\uc544\ubcf4\uc544\uc57c \ud560 \ub178\ub3d9\uc758 \uc5ed\uc0ac\ub97c \ub098\ub204\uc5b4 \uc77d\ub294\ub2e4. \uc885\uc774 \ub808\uc774\uc2a4 \uac00\uc6b4\ub370 \ucee4\ub2e4\ub780 \ubc14\uad6c\ub2c8 \ubaa8\uc591\uc744 \ub193\uace0 \uadf8 \uc548\uc5d0 \uaf43\uc744 \ucc44\uc6b4 \uad6c\uc131\uc740 \ud45c\uba74\uc744 \ub2e8\uc21c\ud55c \uae00\uc758 \ubc30\uacbd\uc73c\ub85c \ub450\uc9c0 \uc54a\ub294\ub2e4. \uaf43\uc744 \ubc14\uce58\ub294 \ubab8\uc9d3\uacfc \uc77d\uc744 \ubb38\uc7a5\uc774 \uac19\uc740 \uce74\ub4dc \uc548\uc5d0 \uc788\ub2e4. \uc2e4\uc81c \uaf43\ub2e4\ubc1c\uc744 \uadf8\ub300\ub85c \ubcf4\ub0b8 \uac83\uc740 \uc544\ub2c8\uc9c0\ub9cc \uc885\uc774\uc640 \ucc9c\uc774 \uadf8 \ud48d\uacbd\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \uc7ac\ub8cc\uac00 \ub2e4\ub978 \uc120\ubb3c\uc758 \ud615\uc0c1\uc744 \ub9cc\ub4dc\ub294 \uc148\uc774\ub2e4. \ubbf8\uc220\uad00\uc774 \uc774\ub7f0 \uce74\ub4dc \ub450 \uc810\uc744 \uc18c\uc7a5\ud55c\ub2e4\ub294 \uc0ac\uc2e4\ub3c4 \ud765\ubbf8\ub86d\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uac1c\uc778\uc5d0\uac8c \ubcf4\ub0b4\uae30 \uc704\ud55c \uc0c1\ud488\uc774\uc5c8\uc9c0\ub9cc \ub098\uc911\uc5d0\ub294 \ub2f9\uc2dc\uc758 \uc81c\uc791\uacfc \ucde8\ud5a5\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc790\ub8cc\uac00 \ub41c\ub2e4. \uc0ac\uc801\uc778 \uae30\uc5b5\uacfc \uacf5\uc801\uc778 \uc218\uc9d1\uc774 \ubb3c\uac74\uc758 \uc11c\ub85c \ub2e4\ub978 \uc2dc\uac04\uc744 \ub9cc\ub4e0\ub2e4. \ud2b9\uc815 \uc218\uc2e0\uc790\uc758 \uc774\uc57c\uae30\uac00 \ud655\uc778\ub418\uc9c0 \uc54a\uc544\ub3c4 \ud615\ud0dc\uc640 \uc7ac\ub8cc\uc5d0\uc11c \uc77d\uc744 \ubd80\ubd84\uc740 \ub0a8\uc544 \uc788\ub2e4. \ube45\ud1a0\ub9ac\uc544 \uc2dc\ub300\ub77c\ub294 \uc774\ub984\uc744 \ub4e4\uc5c8\ub2e4\uace0 \uc5ec\uae30\uc758 \ubaa8\ub4e0 \uce74\ub4dc\uac00 \uc601\uad6d\uc5d0\uc11c \ub9cc\ub4e4\uc5b4\uc84c\ub2e4\uace0 \uc0dd\uac01\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \ud558\uc6b8\ub79c\ub4dc\uc758 \uc0ac\ub840\ub294 \ubbf8\uad6d \ub9e4\uc0ac\ucd94\uc138\uce20\uc8fc \uc6b0\uc2a4\ud130\uc758 \uc0ac\uc5c5\uc744 \uc774\uc57c\uae30\ud55c\ub2e4. \uc2dc\ub300\ub97c \ubd80\ub974\ub294 \uc774\ub984\uacfc \uac1c\ubcc4 \ubb3c\uac74\uc758 \uc81c\uc791\uc9c0\ub294 \uad6c\ubd84\ud574\uc11c \ud655\uc778\ud560 \uc815\ubcf4\ub2e4. \ube44\uc2b7\ud55c \ucde8\ud5a5\uc774 \uc5ec\ub7ec \uc9c0\uc5ed\uc744 \uc624\uac08 \uc218 \uc788\ub2e4\ub294 \uad00\uc810\ub3c4 \uc0dd\uae34\ub2e4. \ub530\ub77c\uc11c \ud55c \uc885\ub958\uc758 \uce74\ub4dc\uac00 \uadf8 \uc2dc\ub300\uc758 \ubaa8\ub4e0 \uc0ac\ub791 \ud45c\ud604\uc744 \ub300\ud45c\ud55c\ub2e4\uace0 \uc678\uc6b0\uae30\ubcf4\ub2e4 \uc11c\ub85c \ub2e4\ub978 \ud615\uc2dd \uc911 \ud55c \uc0ac\ub840\ub85c \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uc775\uc0b4\uc2a4\ub7ec\uc6b4 \uc778\uc1c4 \uce74\ub4dc\uc640 \uc815\uad50\ud55c \uc785\uccb4 \uce74\ub4dc\uac00 \ud568\uaed8 \uc788\uc5c8\ub2e4\ub294 \uc124\uba85\uc774 \ub2e4\uc591\ud568\uc744 \uc54c\ub824 \uc900\ub2e4. \uc885\uc774 \ub808\uc774\uc2a4\uc758 \uc791\uc740 \ud2c8\uc5d0\uc11c \uac1c\uc778\uc758 \ub9d0\uacfc \uc0c1\ud488, \uc7a5\uc778\uc758 \uc190\uacfc \uc2dc\ub300\uc758 \ucde8\ud5a5\uc774 \uc11c\ub85c \ub9cc\ub09c\ub2e4. \uc9c0\uae08\uc740 \uadf8\ub9bc\uacfc \ubb38\uad6c\ub97c \uace8\ub77c \uc804\uc1a1\ud558\uba74 \uba87 \ucd08 \uc548\uc5d0 \ub9c8\uc74c\uc744 \uc804\ud560 \uc218 \uc788\ub2e4. \uc774\ub7f0 \uce74\ub4dc\ub294 \uadf8 \uc8fc\ubcc0\uc744 \ub9cc\ub4dc\ub294 \ub370\uc5d0\ub3c4 \uc190\uc774 \ub9ce\uc774 \uac14\uc744 \uac83\uc774\ub2e4. \ub9d0 \ub300\uc2e0 \uc5b4\ub5a4 \uc7ac\ub8cc\ub97c \uace0\ub974\uace0 \uc5b4\ub5bb\uac8c \uacb9\ucce4\ub294\uc9c0\uac00 \uc778\uc0ac\uc5d0 \ub354\ud574\uc9c4\ub2e4. \uc61b \uce74\ub4dc\ub97c \ubaa8\ub450 \uac70\ucc3d\ud55c \uc0ac\ub791\uc758 \uc99d\uac70\ub85c \uc77d\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc624\ub298\uc740 \uc885\uc774 \ub808\uc774\uc2a4\uc640 \uaf43\ubc14\uad6c\ub2c8\ub9cc \ub5a0\uc62c\ub824 \ubcf4\uc790. \ud55c \uc7a5\uc758 \uc885\uc774\ub97c \ub354 \uc608\uc058\uac8c \uafb8\uba70 \ub204\uad70\uac00\uc5d0\uac8c \uac74\ub124\uace0 \uc2f6\uc5c8\ub358 \ub9c8\uc74c\uc740 \uc9c0\uae08\uc758 \uce74\ub4dc \uace0\ub974\uae30\uc640\ub3c4 \ud06c\uac8c \uba40\uc9c0 \uc54a\ub2e4."}, {"id": "zongzi-leaf-parcel", "title": "\uc911\uad6d\uc758 \uba85\uc808 \uc74c\uc2dd\uc5d0\ub294 \uc78e\uc0ac\uadc0 \ud3ec\uc7a5\uc774 \uc788\ub2e4", "summary": "\uc300 \uc74c\uc2dd \ud558\ub098\uc5d0 \uc7ac\ub8cc\uc640 \ud3ec\uc7a5, \uba85\uc808\uc758 \uc2dc\uac04\uc774 \ud568\uaed8 \ub193\uc785\ub2c8\ub2e4.", "category": "life", "category_title": "Life", "subcategory": "Food", "url": "stories/zongzi-leaf-parcel/index.html", "image": "media/zongzi-leaf-parcel.jpg", "alt": "\uc811\uc2dc\uc5d0 \ub193\uc778 \uc78e\uc0ac\uadc0\ub85c \uc2f8\uace0 \uc2e4\ub85c \ubb36\uc740 \ucad1\ucbd4\uc758 \uc2e4\uc81c \uc0ac\uc9c4.", "text": "\uc911\uad6d\uc758 \uba85\uc808 \uc74c\uc2dd\uc5d0\ub294 \uc78e\uc0ac\uadc0 \ud3ec\uc7a5\uc774 \uc788\ub2e4 \uc2e4\ub85c \ubb36\uc740 \ucad1\ucbd4\ub97c \uc5f4\uae30 \uc804\uc5d0 \ubcf4\uae30 \uc300 \uc74c\uc2dd \ud558\ub098\uc5d0 \uc7ac\ub8cc\uc640 \ud3ec\uc7a5, \uba85\uc808\uc758 \uc2dc\uac04\uc774 \ud568\uaed8 \ub193\uc785\ub2c8\ub2e4. Food \uc0dd\ud65c \uc811\uc2dc \uc704\uc5d0 \uc791\uc740 \uafb8\ub7ec\ubbf8\ub4e4\uc774 \ub193\uc5ec \uc788\ub2e4. \uc9d9\uc740 \uc78e\uc73c\ub85c \uc2f8\uace0 \uc2e4\uc744 \ub458\ub7ec \ubb36\uc5b4\uc11c \uc74c\uc2dd\uc774\ub77c\uae30\ubcf4\ub2e4 \uba3c\uc800 \ud480\uc5b4\uc57c \ud560 \uc120\ubb3c\ucc98\ub7fc \ubcf4\uc778\ub2e4. \uc911\uad6d\uc758 \ucad1\ucbd4\ub2e4. OpenStax\uc758 \uc778\ub958\ud559 \uad50\uc7ac\ub294 \uc0ac\uc9c4 \uc18d \uc74c\uc2dd\uc744 \ub300\ub098\ubb34 \uc78e\uc5d0 \uc2fc \ucc39\uc300 \uc74c\uc2dd\uc73c\ub85c \uc18c\uac1c\ud55c\ub2e4. \uba39\uae30 \uc804\ubd80\ud130 \ubaa8\uc591\uacfc \ud3ec\uc7a5\uc774 \ub208\uc5d0 \ub4e4\uc5b4\uc624\ub294 \uba85\uc808 \uc74c\uc2dd\uc774\ub2e4. \uad50\uc7ac\ub294 \ucad1\ucbd4\ub97c \uc5ec\ub7ec \uc885\ub958\uc758 \uc18d\uc7ac\ub8cc\ub97c \ub123\ub294 \ucc39\uc300 \uc74c\uc2dd\uc73c\ub85c \uc124\uba85\ud55c\ub2e4. \uac89\uc758 \uc78e\uacfc \uc2e4\uc774 \ubcf4\uc778\ub2e4\uace0 \uc548\uc758 \ub9db\uae4c\uc9c0 \ubaa8\ub450 \uc54c \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uac19\uc740 \uc774\ub984 \uc548\uc5d0\ub3c4 \ub2e4\ub978 \uc18d\uc774 \uc788\uc744 \uc218 \uc788\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c\ub294 \uba3c\uc800 \uc78e\uc774 \uc811\ud78c \uc120\uacfc \ubb36\uc778 \uc2e4\uc744 \ub530\ub77c \ubcf4\uc790. \ud3ec\uc7a5\uc9c0\ucc98\ub7fc \ubcf4\uc774\ub294 \ubd80\ubd84\ub3c4 \uc74c\uc2dd\uc758 \ubaa8\uc2b5\uc744 \uc774\ub8e8\uace0 \uc788\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc78e\uc774 \uc5b4\ub5a4 \ud654\ud559\uc801 \ud6a8\uacfc\ub97c \ub0b8\ub2e4\uac70\ub098 \ubaa8\ub450 \uac19\uc740 \ubaa8\uc591\uc73c\ub85c \uc2f8\uc57c \ud55c\ub2e4\uace0 \uc124\uba85\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ucad1\ucbd4\ub294 \uc911\uad6d\uc758 \ub2e8\uc624, \uace7 \ub450\uc548\uc6b0\uc640 \uc774\uc5b4\uc9c0\ub294 \ub300\ud45c \uc74c\uc2dd\uc73c\ub85c \uc18c\uac1c\ub41c\ub2e4. \uad50\uc7ac\ub294 \uc774 \uba85\uc808\uc744 \uc911\uad6d \uc74c\ub825\uc758 \ub2e4\uc12f\uc9f8 \ub2ec \ub2e4\uc12f\uc9f8 \ub0a0\uc5d0 \uc9c0\ub0b4\ub294 \ud589\uc0ac\ub85c \uc124\uba85\ud55c\ub2e4. \uc775\uc219\ud55c \ub2ec\ub825 \ub0a0\uc9dc\uc640 \ud2b9\uc815 \uc74c\uc2dd\uc774 \ub9cc\ub098\uba74 \ub9db\uc744 \uae30\uc5b5\ud558\ub294 \ubc29\uc2dd\ub3c4 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc544\ubb34 \ub0a0\uc774\ub098 \uba39\uc744 \uc218 \uc788\ub294 \uc7ac\ub8cc\ub77c\ub3c4 \uc5b4\ub5a4 \ub0a0\uc758 \uc74c\uc2dd\uc774 \ub418\uba74 \uc0ac\ub78c\ub4e4\uc740 \ub2e4\uc74c \ud574 \uac19\uc740 \uc2dc\uae30\ub97c \ud568\uaed8 \ub5a0\uc62c\ub9ac\uac8c \ub41c\ub2e4. \uc774\uac83\uc740 \uba85\uc808 \uc74c\uc2dd\uc744 \uc77d\ub294 \ud55c \uac00\uc9c0 \uad00\uc810\uc774\ub2e4. \ud3ec\uc7a5\uc740 \ub0b4\uc6a9\ubb3c\uc744 \uac00\ub9ac\ub294 \uac83\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc \ucad1\ucbd4\uc5d0\uc11c\ub294 \uc74c\uc2dd\uc758 \ubc14\uae65\ubaa8\uc591\uc744 \ud568\uaed8 \ub9cc\ub4e0\ub2e4. \uc78e\uc774 \uc811\ud78c \uba74\uacfc \uc2e4\uc774 \uc9c0\ub098\uac00\ub294 \ubc29\ud5a5\uc744 \ubcf4\uba74 \uc791\uac8c \ub098\ub204\uc5b4 \ub2f4\ub294 \ud589\ub3d9\uc774 \ub5a0\uc624\ub978\ub2e4. \ub2e4\ub9cc \uc0ac\uc9c4 \uc18d \ud55c \uac1c\uc758 \ud615\ud0dc\uac00 \ubaa8\ub4e0 \uc9c0\uc5ed\uc758 \uc720\uc77c\ud55c \ubaa8\uc591\uc774\ub77c\uace0 \uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uac19\uc740 \uc774\ub984 \uc544\ub798\uc5d0\ub3c4 \uc7ac\ub8cc\uc640 \uc2f8\ub294 \ubc29\uc2dd\uc758 \ucc28\uc774\uac00 \uc788\uc744 \uc218 \uc788\ub2e4. \uc78e\uc758 \uc885\ub958\ub3c4 \uc790\ub8cc\uac00 \uc124\uba85\ud558\ub294 \ubc94\uc704\uc5d0\uc11c \uc77d\uc5b4\uc57c \ud55c\ub2e4. \uc774 \uc0ac\uc9c4\uc740 \ub300\ub098\ubb34 \uc78e\uacfc \uc2e4\ub85c \uac10\uc2fc \ubaa8\uc2b5\uc73c\ub85c \uc18c\uac1c\ub41c\ub2e4. \uc2dd\ubb3c \uc774\ub984\uc774 \uc788\ub2e4\uace0 \ud5a5\uacfc \uc870\ub9ac \ud6a8\uacfc\uc758 \ubaa8\ub4e0 \uc138\ubd80\uac00 \uc800\uc808\ub85c \uc785\uc99d\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5ec\uae30\uc11c\ub294 \ud45c\uba74\uc5d0 \ub193\uc778 \uc78e\uc774 \ub2e8\uc21c\ud55c \ubc30\uacbd\uc774 \uc544\ub2c8\ub77c \uc74c\uc2dd\uc758 \ubaa8\uc2b5\uc744 \uc774\ub8e8\ub294 \ubd80\ubd84\uc774\ub77c\ub294 \uc810\ubd80\ud130 \uc0b4\ud3b4\ubcf8\ub2e4. \uad50\uc7ac\ub294 \uc5ec\ub7ec \uae30\uc6d0 \uc774\uc57c\uae30 \uac00\uc6b4\ub370 \uad74\uc6d0\uc744 \uae30\ub9ac\ub294 \uc804\uc2b9\uc744 \uc18c\uac1c\ud55c\ub2e4. \uad8c\ub825\uc5d0\uc11c \uba40\uc5b4\uc9c4 \uc2dc\uc778\uacfc \uad00\ub9ac\uc758 \uc8fd\uc74c \ub4a4\uc5d0 \uc0ac\ub78c\ub4e4\uc774 \uac15\uc5d0 \uc300 \uc74c\uc2dd\uc744 \ub358\uc84c\ub2e4\ub294 \uc774\uc57c\uae30\ub2e4. \ubb3c\uace0\uae30\uc758 \uad00\uc2ec\uc744 \ub3cc\ub824 \uadf8\uc758 \ubab8\uc744 \ucc3e\uc73c\ub824 \ud588\ub2e4\uace0 \uc804\ud574\uc9c4\ub2e4. \uc74c\uc2dd\uc774 \ub204\uad70\uac00\ub97c \uae30\uc5b5\ud558\ub294 \ud589\ub3d9\uacfc \uc5f0\uacb0\ub418\ub294 \uc124\uba85\uc774\ub2e4. \ub2e4\ub9cc \uc774 \uc804\uc2b9\uc744 \ud55c \ubc88\uc758 \uc0ac\uac74\uc774 \ubaa8\ub4e0 \ucad1\ucbd4\uc758 \uc2dc\uc791\uc774\uc5c8\ub2e4\ub294 \ud655\uc815\ub41c \uae30\ub85d\uc73c\ub85c \ubc14\uafb8\uc9c0\ub294 \uc54a\ub294\ub2e4. \uad50\uc7ac \uc790\uccb4\ub3c4 \ub2e8\uc624\uc758 \uc720\ub798\uac00 \uc5ec\ub7ec \uac00\uc9c0\ub77c\uace0 \uc54c\ub824 \uc900\ub2e4. \uc804\uc2b9\uc740 \uc0ac\ub78c\ub4e4\uc774 \uc74c\uc2dd\uacfc \uba85\uc808\uc744 \uc5b4\ub5a4 \uc774\uc57c\uae30\ub85c \uae30\uc5b5\ud588\ub294\uc9c0 \ubcf4\uc5ec \uc904 \uc218 \uc788\ub2e4. \uc2e4\uc81c \uae30\uc6d0\uc744 \ubc1d\ud788\ub294 \uc5ed\uc0ac \uc5f0\uad6c\uc640 \ubb38\ud654\uc801 \uc758\ubbf8\ub97c \uc77d\ub294 \uc77c\uc740 \uac19\uc740 \uc790\ub8cc\ub97c \ubcf4\uc544\ub3c4 \uc9c8\ubb38\uc774 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uc74c\ub825 \ub2e4\uc12f\uc9f8 \ub2ec \ub2e4\uc12f\uc9f8 \ub0a0\uc774\ub77c\ub294 \uc2dc\uc810\uc740 \ub9e4\ub144 \ub3cc\uc544\uc628\ub2e4. \ud2b9\uc815 \uc74c\uc2dd\uc744 \uadf8\ub0a0\uacfc \uc5f0\uacb0\ud558\uba74 \uc7ac\ub8cc\uc758 \ub9db\uc774 \uc0ac\ub78c\uacfc \ud589\uc0ac\uc758 \uae30\uc5b5\uc744 \ud568\uaed8 \ubd88\ub7ec\uc62c \uc218 \uc788\ub2e4. \uc5b8\uc81c \uba39\ub290\ub0d0\uac00 \ubb34\uc5c7\uc744 \uba39\ub290\ub0d0\uc758 \ub73b\uc5d0 \uc601\ud5a5\uc744 \uc8fc\ub294 \uac83\uc774\ub2e4. \uac19\uc740 \ucc39\uc300\uc774\ub77c\ub3c4 \uc77c\uc0c1\uc758 \uc2dd\uc0ac\uc640 \uba85\uc808 \uc74c\uc2dd\uc774\ub77c\ub294 \uc790\ub9ac\ub294 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \uba85\uc808 \ubc16\uc5d0\ub294 \uc804\ud600 \uba39\uc9c0 \uc54a\ub294\ub2e4\uac70\ub098 \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \uac19\uc740 \ucd94\uc5b5\uc744 \uac00\uc9c4\ub2e4\uace0 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc9c0\uc5ed\uacfc \uac00\uc815, \uac1c\uc778\uc758 \uacbd\ud5d8\uc740 \ub2e4\uc591\ud558\ub2e4. \uc5ec\uae30\uc11c\ub294 \ud589\uc0ac\uc640 \uc74c\uc2dd\uc758 \uc5f0\uacb0\uc744 \uc18c\uac1c\ud558\ub294 \uad50\uc7ac\uc758 \uad00\uc810\uc744 \ub530\ub77c\uac04\ub2e4. \ud558\ub098\uc758 \uc774\ub984\uc744 \ubc30\uc6b4 \ub4a4 \ub9db\uc758 \ud45c\uc900 \ud558\ub098\ub85c \uc904\uc774\uae30\ubcf4\ub2e4 \uc5b4\ub5a4 \uc790\ub9ac\uc5d0 \ub193\uc600\ub294\uc9c0 \uc9c8\ubb38\ud558\ub294 \ud3b8\uc774 \ubb38\ud654\uc5d0 \uac00\uae4c\uc774 \uac04\ub2e4. \uc0ac\uc9c4\uc758 \ud3ec\uc7a5\uc744 \uc54c\uc544\ubcf4\uc544\ub3c4 \uc18d\uc7ac\ub8cc\uae4c\uc9c0 \uc790\ub3d9\uc73c\ub85c \uc77d\uc744 \uc218\ub294 \uc5c6\ub2e4. \uad50\uc7ac\ub294 \ub2e4\uc591\ud55c \uc18d\uc744 \ub123\ub294\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub2eb\ud78c \ubb3c\uac74\uc5d0\uc11c \ubcf4\uc774\uc9c0 \uc54a\ub294 \ubd80\ubd84\uc744 \uc77c\ubc18\uc801\uc778 \uc608 \ud558\ub098\ub85c \ucc44\uc6b0\uc9c0 \uc54a\ub294 \uac83\uc774 \uc815\ud655\ud558\ub2e4. \uc774\ub984\uc774 \uac19\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ubaa8\ub4e0 \uad6c\uc131 \uc694\uc18c\uac00 \uac19\ub2e4\ub294 \uc8fc\uc7a5\uc744 \uad6c\ubd84\ud560 \uc218 \uc788\ub2e4. \uc774 \uc791\uc740 \ud55c\uacc4\ub294 \uac10\uc0c1\uc744 \ub9c9\uae30\ubcf4\ub2e4 \ub354 \ub9ce\uc740 \uad00\uc2ec\uc744 \ub0a8\uae34\ub2e4. \ub2e4\ub978 \uc9c0\uc5ed\uc758 \ucad1\ucbd4\ub97c \ub9cc\ub098\uba74 \ubb34\uc5c7\uc73c\ub85c \uc2f8\uace0 \uc5b4\ub5bb\uac8c \ubb36\uc5c8\ub294\uc9c0, \uc5b4\ub5a4 \ub0a0\uc758 \uc74c\uc2dd\uc73c\ub85c \uc18c\uac1c\ud558\ub294\uc9c0 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \uc78e\uc0ac\uadc0\uc640 \uc2e4\ub85c \ub458\ub7ec\uc2fc \ubaa8\uc591\uc5d0\uc11c \uc7ac\ub8cc\uc640 \uc190\uc77c, \ub2ec\ub825\uacfc \uc774\uc57c\uae30\uc758 \uad00\uacc4\uac00 \ub4dc\ub7ec\ub09c\ub2e4. \uc74c\uc2dd\uc758 \uc774\ub984 \ud558\ub098\uac00 \uadf8 \ub4a4\uc758 \uc5ec\ub7ec \uc0dd\ud65c\uc744 \ubcf4\ub294 \ud45c\uc9c0\uac00 \ub41c\ub2e4. \uc774 \uba85\uc808\uc5d0\ub294 \uad74\uc6d0\uacfc \uad00\ub828\ub41c \uc774\uc57c\uae30\ub97c \ube44\ub86f\ud574 \uc5ec\ub7ec \uae30\uc6d0 \uc774\uc57c\uae30\uac00 \uc804\ud574\uc9c4\ub2e4. \uad50\uc7ac\ub3c4 \ud558\ub098\uc758 \uc720\ub798\ub9cc\uc774 \uc720\uc77c\ud55c \uc0ac\uc2e4\uc774\ub77c\uace0 \uc81c\uc2dc\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc624\ub79c \ud48d\uc2b5\uc5d0 \ubd99\uc740 \uc774\uc57c\uae30\ub294 \uadf8 \uc790\uccb4\ub85c \ub098\ub204\uc5b4 \uc77d\uc744 \ubd80\ubd84\uc774\ub2e4. \uc624\ub298\uc740 \uc2e4\ub85c \ubb36\uc778 \uafb8\ub7ec\ubbf8 \ud558\ub098\ub9cc \uae30\uc5b5\ud574\ub3c4 \uc88b\uaca0\ub2e4. \uc6b0\ub9ac\uac00 \uc74c\uc2dd\uc774\ub77c\uace0 \ubd80\ub974\ub294 \uac83\uc740 \ub9db\ub9cc\uc774 \uc544\ub2c8\ub2e4. \uc2f8\ub294 \ubaa8\uc591\uacfc \uc5ec\ub294 \uc190\uae38, \ud574\ub9c8\ub2e4 \ub3cc\uc544\uc624\ub294 \ub54c\ub3c4 \ud568\uaed8 \ub4e4\uc5b4 \uc788\ub2e4. \ucad1\ucbd4\ub294 \uadf8\ub7f0 \uc5ec\ub7ec \uacb9\uc744 \ud55c\ub208\uc5d0 \ubcf4\uc5ec \uc8fc\ub294 \uc74c\uc2dd\uc774\ub2e4."}, {"id": "airbnb-room-and-neighborhood", "title": "\uc5d0\uc5b4\ube44\uc564\ube44 \u2014 \ube48\ubc29\uc744 \uc5f0\uacb0\ud558\uba74 \uc0dd\uae30\ub294 \uc77c", "summary": "\ucd08\uae30\uc758 \uc5d0\uc5b4 \ub9e4\ud2b8\ub9ac\uc2a4 \uc0ac\ub840\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc628\ub77c\uc778 \uc911\uac1c, \ub3d9\ub124 \uc815\ubcf4\uc640 \uaddc\uce59\uc758 \ubb38\uc81c\uae4c\uc9c0 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "companies", "category_title": "Companies", "subcategory": "Technology", "url": "stories/airbnb-room-and-neighborhood/index.html", "image": "media/airbnb-room-and-neighborhood.png", "alt": "\uc5ec\ud589 \uac00\ubc29\uc744 \ub4e0 \ubc29\ubb38\uac1d\uacfc \ubc29\uc758 \ubb38\uc744 \uc5f4\uc5b4 \ub9de\uc774\ud558\ub294 \uc9d1\uc8fc\uc778\uc758 \uc0c1\uc0c1 \uc18d \ub9cc\ub0a8.", "text": "\uc5d0\uc5b4\ube44\uc564\ube44 \u2014 \ube48\ubc29\uc744 \uc5f0\uacb0\ud558\uba74 \uc0dd\uae30\ub294 \uc77c \uc9d1\uc8fc\uc778\uacfc \uc5ec\ud589\uc790 \uc0ac\uc774\uc5d0 \uc0c8\ub85c\uc6b4 \uc2dc\uc7a5\uc774 \ub9cc\ub4e4\uc5b4\uc84c\ub2e4 \ucd08\uae30\uc758 \uc5d0\uc5b4 \ub9e4\ud2b8\ub9ac\uc2a4 \uc0ac\ub840\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc628\ub77c\uc778 \uc911\uac1c, \ub3d9\ub124 \uc815\ubcf4\uc640 \uaddc\uce59\uc758 \ubb38\uc81c\uae4c\uc9c0 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Technology \uae30\uc5c5 \uc5ec\ud589\uc744 \uc55e\ub450\uace0 \uc798 \uacf3\uc744 \ucc3e\ub294 \uc0ac\ub78c\uc774 \uc788\ub2e4. \ub2e4\ub978 \ud55c\ucabd\uc5d0\ub294 \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub294 \ubc29\uc774 \uc788\ub2e4. \ub450 \uc0ac\uc815\uc774 \uc11c\ub85c\ub97c \uc54c\uc9c0 \ubabb\ud558\uba74 \uc544\ubb34 \uc77c\ub3c4 \uc0dd\uae30\uc9c0 \uc54a\ub294\ub2e4. \ud558\uc9c0\ub9cc \ucc3e\uace0 \uc5f0\ub77d\ud558\uace0 \uac70\ub798\ud560 \uc218 \uc788\ub294 \uae38\uc774 \ub9cc\ub4e4\uc5b4\uc9c0\uba74 \ub0a8\ub294 \uacf5\uac04\uc740 \ub2e4\ub978 \uc4f0\uc784\uc744 \uc5bb\uc744 \uc218 \uc788\ub2e4. \uc5d0\uc5b4\ube44\uc564\ube44\uc758 \ucd9c\ubc1c \uc774\uc57c\uae30\ub294 \uc774 \ub2e8\uc21c\ud55c \uc5f0\uacb0\uc5d0\uc11c \uc2dc\uc791\ud55c\ub2e4. \ub2e4\ub9cc \uc571 \ud654\uba74\uc5d0\uc11c \ube48\ubc29\uc744 \ucc3e\ub294 \uc77c\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uacfc\uc815\uc774 \uc124\uba85\ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub204\uad70\uac00\uc758 \uc9d1\uc774 \uc5ec\ud589\uc790\uc758 \uc219\uc18c\uac00 \ub418\uba74 \uc2e0\ub8b0\uc640 \uc0dd\ud65c, \ub3d9\ub124\uc758 \uaddc\uce59\uae4c\uc9c0 \ud568\uaed8 \uc5f0\uacb0\ub418\uae30 \ub54c\ubb38\uc774\ub2e4. \uad50\uc7ac\ub294 \ube0c\ub77c\uc774\uc5b8 \uccb4\uc2a4\ud0a4\uc640 \uc870 \uac8c\ube44\uc544\uac00 \uc9d1\uc138 \ubd80\ub2f4\uc744 \uacaa\ub358 \ub54c \uc790\uc2e0\uc758 \uacf5\uac04\uc5d0 \uc190\ub2d8\uc744 \ubc1b\uace0 \uc5d0\uc5b4 \ub9e4\ud2b8\ub9ac\uc2a4\uc5d0\uc11c \uc790\uac8c \ud55c \uc0ac\ub840\ub97c \uc18c\uac1c\ud55c\ub2e4. \uc9c0\uae08\uc758 \uac70\ub300\ud55c \uc11c\ube44\uc2a4\ub97c \ub5a0\uc62c\ub9ac\uae30 \uc804\uc5d0 \uc0dd\ud65c \uc18d\uc758 \uad6c\uccb4\uc801\uc778 \uc0ac\uc815\uc774 \uc788\uc5c8\ub2e4\ub294 \uac83\uc774\ub2e4. \ucc98\uc74c\uc758 \ud544\uc694\ub294 \uc790\uc2e0\uc774 \uac00\uc9c4 \uacf5\uac04\uc73c\ub85c \uc218\uc785\uc744 \uc5bb\ub294 \uc77c\uc774\uc5c8\ub2e4. \uc774 \uc0ac\ub840\ub97c \ubbf8\ub798\uc758 \ubaa8\ub4e0 \uc131\uacf5\uc774 \uc608\uc815\ub41c \uc21c\uac04\uc73c\ub85c \uafb8\ubc00 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc8fc\ubcc0\uc5d0\uc11c \uc0dd\uae34 \ubd88\ud3b8\uc744 \ub2e4\ub978 \uc0ac\ub78c\uc758 \ud544\uc694\uc640 \uc5f0\uacb0\ud574 \ubcf4\uc558\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \uadf8\ub807\ub2e4\uace0 \uac19\uc740 \uc77c\uc744 \ud574 \ubcf4\uba74 \ub204\uad6c\ub098 \uac19\uc740 \uae30\uc5c5\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub2e4\ub294 \ub73b\ub3c4 \uc544\ub2c8\ub2e4. \uc791\uc740 \uc2dc\ub3c4\uc640 \uc9c0\uc18d \uac00\ub2a5\ud55c \uc0ac\uc5c5 \uc0ac\uc774\uc5d0\ub294 \ub9ce\uc740 \uc900\ube44\uac00 \ub0a8\uc544 \uc788\uc5c8\ub2e4. \uc804\ud1b5\uc801\uc778 \uc219\ubc15 \uc0ac\uc5c5\uc744 \uc0dd\uac01\ud558\uba74 \uac74\ubb3c\uc744 \ub9c8\ub828\ud558\uace0 \ubc29\uc744 \uad00\ub9ac\ud558\ub294 \ubaa8\uc2b5\uc774 \uba3c\uc800 \ub5a0\uc624\ub978\ub2e4. \uc628\ub77c\uc778 \uc911\uac1c\ub294 \uc774\ubbf8 \uc874\uc7ac\ud558\ub294 \uacf5\uac04\uc758 \uc81c\uacf5\uc790\uc640 \uc774\uc6a9\uc790\ub97c \uc5f0\uacb0\ud558\ub294 \ub370 \ubb34\uac8c\uac00 \uc788\ub2e4. \uad50\uc7ac\ub294 \uc774\ub7f0 \uc720\ud615\uc744 \uc811\uadfc \uacbd\uc81c \ub610\ub294 \uc628\ub77c\uc778 \ud50c\ub7ab\ud3fc \uacbd\uc81c\uc758 \uc0ac\ub840\ub85c \uc124\uba85\ud55c\ub2e4. \uc790\uc0b0\uc744 \uc18c\uc720\ud558\ub294 \uc77c\uacfc \uc77c\uc815 \uae30\uac04 \uc774\uc6a9\ud560 \uad8c\ub9ac\ub97c \uc5f0\uacb0\ud558\ub294 \uc77c\uc774 \uad6c\ubd84\ub418\ub294 \uac83\uc774\ub2e4. \ub2e4\ub9cc \ud50c\ub7ab\ud3fc\uc774 \uacf5\uac04\uc744 \uc9c1\uc811 \uc18c\uc720\ud558\uc9c0 \uc54a\ub294\ub2e4\uace0 \uc11c\ube44\uc2a4\uc5d0 \uad00\ud55c \ucc45\uc784\uc758 \uc9c8\ubb38\uae4c\uc9c0 \uc5c6\uc5b4\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4. \uac80\uc0c9 \ud654\uba74\uc744 \ub9cc\ub4e0 \ub4a4\uc5d0\ub3c4 \uc2e4\uc81c \ub9cc\ub0a8\uacfc \uac70\ub798\ub294 \uc0ac\ub78c\uc758 \uc0dd\ud65c \uacf5\uac04\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc9c4\ub2e4. \uc5ec\ud589\uc790\ub294 \ubc29\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ubfd0 \uc544\ub2c8\ub77c \uadf8\uacf3\uc774 \uc5b4\ub5a4 \uacf3\uc778\uc9c0 \uc54c\uace0 \uc2f6\uc5b4 \ud55c\ub2e4. \uc704\uce58\uc640 \uc8fc\ubcc0 \ud658\uacbd\uc774 \uc790\uae30 \uc77c\uc815\uc5d0 \ub9de\ub294\uc9c0\ub3c4 \uc911\uc694\ud558\ub2e4. \uc9d1\uc8fc\uc778\uc5d0\uac8c\ub3c4 \ub0af\uc120 \uc0ac\ub78c\uc774 \ubc29\ubb38\ud55c\ub2e4\ub294 \uc810\uc740 \ubcc4\ub3c4\uc758 \ubb38\uc81c\ub2e4. \uc591\ucabd\uc758 \ud544\uc694\uac00 \ub9de\ub294\uc9c0 \ud655\uc778\ud560 \uc815\ubcf4\uac00 \uc788\uc5b4\uc57c \uac70\ub798\uac00 \uc131\ub9bd\ud55c\ub2e4. \uc774 \ub54c\ubb38\uc5d0 \uc628\ub77c\uc778 \uc2dc\uc7a5\uc740 \ub2e8\uc21c\ud788 \ubaa9\ub85d\uc744 \uae38\uac8c \ubcf4\uc5ec \uc8fc\ub294 \uac83\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \ubb34\uc5c7\uc744 \uac19\uc740 \uae30\uc900\uc73c\ub85c \ube44\uad50\ud558\uace0 \uc5b4\ub5a4 \ub0b4\uc6a9\uc744 \ubd84\uba85\ud558\uac8c \uc54c\ub824 \uc904\uc9c0 \uacb0\uc815\ud574\uc57c \ud55c\ub2e4. \ubcf4\uae30 \uc88b\uc740 \uc0ac\uc9c4\uacfc \uc2e4\uc81c \uc774\uc6a9 \uc870\uac74 \uc0ac\uc774\uc758 \uac04\uaca9\uc774 \ud06c\uba74 \ud3b8\ub9ac\ud55c \uac80\uc0c9\uc774 \uace7 \uc88b\uc740 \uacbd\ud5d8\uc73c\ub85c \uc774\uc5b4\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4. \uad50\uc7ac\ub294 \uc5d0\uc5b4\ube44\uc564\ube44\uac00 2012\ub144 \ub3d9\ub124 \uc548\ub0b4 \uc11c\ube44\uc2a4 \ub124\uc774\ube0c\uc640\uc774\uc988\ub97c \uc778\uc218\ud55c \uc0ac\ub840\ub97c \uc18c\uac1c\ud55c\ub2e4. \ub0af\uc120 \uc9c0\uc5ed\uc758 \uc219\uc18c\ub97c \uace0\ub974\ub294 \uc0ac\ub78c\uc5d0\uac8c \uc8fc\ubcc0\uc744 \uc774\ud574\ud560 \uc815\ubcf4\ub97c \uc81c\uacf5\ud558\ub294 \ubc29\ud5a5\uc774\uc5c8\ub2e4. \uc5ec\ud589\uc790\uc758 \uc9c8\ubb38\uc740 \uce68\ub300\uac00 \uc788\ub294\uac00\uc5d0\uc11c \uc5b4\ub5a4 \ub3d9\ub124\uc5d0 \uba38\ubb3c \uac83\uc778\uac00\ub85c \ub113\uc5b4\uc9c8 \uc218 \uc788\ub2e4. \uc774\ubc88 \uae00\uc740 \ub2f9\uc2dc\uc758 \uc0ac\uc5c5 \uc120\ud0dd\uc744 \uc124\uba85\ud558\ub294 \uac83\uc73c\ub85c \uadf8 \uc11c\ube44\uc2a4\uac00 \ud604\uc7ac \uac19\uc740 \uc774\ub984\uacfc \ud615\ud0dc\ub85c \uc6b4\uc601\ub41c\ub2e4\ub294 \uc548\ub0b4\ub294 \uc544\ub2c8\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \ubc29\uc758 \uc815\ubcf4\uc640 \uc9c0\uc5ed\uc758 \uc815\ubcf4\ub97c \ud568\uaed8 \ubcf4\ub824 \ud588\ub2e4\ub294 \uc810\uc774\ub2e4. \uc0c1\ud488\uc758 \uacbd\uacc4\ub97c \uc5b4\ub514\uae4c\uc9c0 \uc7a1\ub294\uc9c0\uc5d0 \ub530\ub77c \uae30\uc5c5\uc774 \ub9c8\ub828\ud574\uc57c \ud558\ub294 \uc815\ubcf4\uc640 \ud611\ub825\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uac70\ub798 \ud654\uba74\uc5d0\ub294 \uc9d1\uc8fc\uc778\uacfc \uc5ec\ud589\uc790\uac00 \uc911\uc2ec\uc73c\ub85c \ub4f1\uc7a5\ud55c\ub2e4. \uadf8\ub7ec\ub098 \uc2e4\uc81c \uacf5\uac04\uc5d0\ub294 \uc774\uc6c3\uacfc \uac74\ubb3c\uc758 \ub2e4\ub978 \uc774\uc6a9\uc790\ub3c4 \uc788\ub2e4. \ub4dc\ub098\ub4dc\ub294 \uc0ac\ub78c\uc774 \ubc14\ub00c\uba74 \uc0dd\ud65c\uc758 \uc870\uac74\uc5d0 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\ub2e4. \uad50\uc7ac\uac00 \uaddc\uc81c\uc640 \uc2e0\ub8b0\ub97c \uc911\uc694\ud55c \uc9c8\ubb38\uc73c\ub85c \ub2e4\ub8e8\ub294 \uc774\uc720\ub2e4. \ud55c \uc0ac\ub78c\uc5d0\uac8c\ub294 \ub0a8\ub294 \uacf5\uac04\uc744 \ud65c\uc6a9\ud558\ub294 \uc88b\uc740 \uae30\ud68c\uac00 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc0c8\ub85c\uc6b4 \uad00\ub9ac \ubb38\uc81c\uc77c \uc218 \uc788\ub2e4. \uae30\uc220\uc774 \ub450 \ub2f9\uc0ac\uc790\ub97c \uc27d\uac8c \uc774\uc5b4 \uc8fc\uc5b4\ub3c4 \uc8fc\ubcc0\uc758 \uc774\ud574\uad00\uacc4\uae4c\uc9c0 \uc790\ub3d9\uc73c\ub85c \uc77c\uce58\uc2dc\ud0a4\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc628\ub77c\uc778\uc5d0\uc11c \uac04\ub2e8\ud574 \ubcf4\uc774\ub294 \uac70\ub798\uac00 \uc624\ud504\ub77c\uc778\uc5d0\uc11c\ub294 \uc5ec\ub7ec \uc0ac\ub78c\uc758 \ubb38\uc81c\ub77c\ub294 \uc810\uc744 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uad50\uc7ac\ub294 \uac1c\uc778\uc758 \ubc29 \ub300\uc5ec\ub97c \ud638\ud154\uacfc \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ubcfc \uac83\uc778\uc9c0, \uc5b4\ub5a4 \uc138\uae08\uacfc \uc548\uc804 \uaddc\uce59\uc744 \uc801\uc6a9\ud560 \uac83\uc778\uc9c0 \ub17c\uc758\ud55c\ub2e4. \uc9c0\uc5ed\uc5d0 \ub530\ub77c \ub2e8\uae30 \uc784\ub300\uc758 \ud5c8\uc6a9 \uc870\uac74\uacfc \uaddc\uc81c\uac00 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uc219\ubc15\uc758 \uc81c\uacf5 \ubc29\uc2dd\uc774 \ub2ec\ub77c\uc9c0\uba74 \uae30\uc874 \uc81c\ub3c4\ub97c \uc5b4\ub514\uae4c\uc9c0 \uc801\uc6a9\ud560\uc9c0\ub3c4 \uc9c8\ubb38\uc774 \ub41c\ub2e4. \ub530\ub77c\uc11c \uc774 \uae00\uc5d0\uc11c \uc5b4\ub290 \ub3c4\uc2dc\uc758 \ud604\uc7ac \uc601\uc5c5 \ud5c8\uc6a9 \uc5ec\ubd80\ub97c \uc548\ub0b4\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc2e4\uc81c \uc774\uc6a9\uc774\ub098 \uc6b4\uc601\uc5d0\ub294 \ud574\ub2f9 \uc2dc\uc810\uacfc \uc9c0\uc5ed\uc758 \uaddc\uc815\uc744 \ub530\ub85c \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \uc5ec\uae30\uc11c\ub294 \uae30\uc5c5\uc758 \uc0c8\ub85c\uc6b4 \ubc29\uc2dd\uc774 \uae30\uc874 \uaddc\uce59\uacfc \ub9cc\ub098\uba70 \uc0ac\ud68c\uc801 \ub17c\uc758\ub3c4 \ud568\uaed8 \ub9cc\ub4e0\ub2e4\ub294 \uc810\uc744 \uc77d\ub294 \uac83\uc774 \uc54c\ub9de\ub2e4. \uacf5\uc720\ub77c\ub294 \ub9d0\uc5d0\ub294 \uc11c\ub85c \ub3d5\ub294 \uac00\ubcbc\uc6b4 \ub290\ub08c\uc774 \uc788\ub2e4. \ud558\uc9c0\ub9cc \ub3c8\uc744 \ubc1b\uace0 \uacf5\uac04\uc744 \uc81c\uacf5\ud558\ub294 \ud65c\ub3d9\uc5d0\ub294 \uc0ac\uc5c5\uc758 \uc131\uaca9\ub3c4 \uc788\ub2e4. \uad50\uc7ac\ub294 \uc774\ub7f0 \uac70\ub798\ub97c \ubaa8\ub450 \uac19\uc740 \uc885\ub958\uc758 \uacf5\ub3d9 \uc0ac\uc6a9\uc73c\ub85c\ub9cc \ubcf4\uc9c0 \uc54a\uace0 \uc628\ub77c\uc778 \ud50c\ub7ab\ud3fc\uc774\ub77c\ub294 \ud2c0\uc5d0\uc11c \uc77d\uc744 \ud544\uc694\uac00 \uc788\uc74c\uc744 \uc124\uba85\ud55c\ub2e4. \ub9d0\uc758 \uc778\uc0c1\uacfc \uc2e4\uc81c \uc6b4\uc601\uc744 \ub098\ub204\uba74 \uc7a5\uc810\uacfc \uc9c8\ubb38\uc744 \ud568\uaed8 \ubcfc \uc218 \uc788\ub2e4. \uacf5\uac04\uc744 \ub354 \ub2e4\uc591\ud558\uac8c \ud65c\uc6a9\ud560 \uae30\ud68c\uac00 \uc0dd\uae30\ub294 \ud55c\ud3b8 \ucc45\uc784\uacfc \ubcf4\ud638\uc758 \uae30\uc900\ub3c4 \ud544\uc694\ud558\ub2e4. \uc0c8\ub85c\uc6b4 \uc2dc\uc7a5\uc774\ub77c\ub294 \uc774\uc720\ub85c \ubb34\uc870\uac74 \uc88b\uc740 \uac83\uc73c\ub85c \ubcf4\uac70\ub098 \uae30\uc874\uacfc \ub2e4\ub974\ub2e4\ub294 \uc774\uc720\ub85c \uc758\ubbf8\ub97c \uc9c0\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uc9d1\uc8fc\uc778\uacfc \uc5ec\ud589\uc790\uac00 \ubb38 \uc55e\uc5d0\uc11c \ub9cc\ub098\ub294 \uc0c1\uc0c1 \uc18d \uc7a5\uba74\uc774\ub2e4. \uc2e4\uc81c \ucc3d\uc5c5\uc790\ub098 \ub4f1\ub85d \uc219\uc18c, \uc774\uc6a9\uc790\uc758 \uc0ac\uc9c4\uc740 \uc544\ub2c8\ub2e4. \ub0af\uc120 \uc0ac\ub78c\ub07c\ub9ac \uacf5\uac04\uc744 \ub098\ub208\ub2e4\ub294 \uad6c\uc0c1\uc758 \ucd9c\ubc1c\uc810\uc744 \ub5a0\uc62c\ub9ac\ub294 \uc774\ubbf8\uc9c0\ub2e4. \uc5d0\uc5b4\ube44\uc564\ube44\uc758 \uc0ac\ub840\ub294 \uae30\uc220\uc774 \ub0a8\ub294 \uc790\uc6d0\uacfc \ud544\uc694\ud55c \uc0ac\ub78c\uc744 \ub9cc\ub098\uac8c \ud560 \uc218 \uc788\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ub3d9\uc2dc\uc5d0 \uc5f0\uacb0 \uc774\ud6c4\uc5d0\ub294 \uc124\uba85\uacfc \uc57d\uc18d, \uc0dd\ud65c\uc758 \uaddc\uce59\uc774 \ub0a8\ub294\ub2e4. \ube48\ubc29 \ud558\ub098\uac00 \uc2dc\uc7a5\uc774 \ub418\ub294 \uacfc\uc815\uc740 \ubc84\ud2bc\uc758 \ud3b8\ub9ac\ud568\ubfd0 \uc544\ub2c8\ub77c \uadf8 \ubc84\ud2bc \ubc16\uc5d0\uc11c \ub9cc\ub098\ub294 \uc0ac\ub78c\ub4e4\uae4c\uc9c0 \ud568\uaed8 \uc124\uacc4\ud558\ub294 \uc774\uc57c\uae30\ub2e4."}, {"id": "amazon-order-and-warehouse", "title": "\uc544\ub9c8\uc874 \u2014 \uc8fc\ubb38 \ubc84\ud2bc \ub4a4\uc5d0\ub294 \ubb34\uc5c7\uc774 \ub0a8\uc544 \uc788\uc744\uae4c", "summary": "2010\ub144\ub300 \uc544\ub9c8\uc874 \uc0ac\ub840\ub97c \ud1b5\ud574 \uc628\ub77c\uc778 \uc8fc\ubb38\uacfc \ubb3c\ub958\u00b7\ud68c\uc6d0\uc81c\u00b7\ub178\ub3d9\uc758 \uc5f0\uacb0\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "companies", "category_title": "Companies", "subcategory": "Technology", "url": "stories/amazon-order-and-warehouse/index.html", "image": "media/amazon-order-and-warehouse.png", "alt": "\uc0c1\uc790\ub97c \ud655\uc778\ud558\ub294 \uc0ac\ub78c\uacfc \uc120\ubc18\uc744 \uc815\ub9ac\ud558\ub294 \uc0ac\ub78c\uc774 \uc788\ub294 \ubc30\uc1a1 \uc791\uc5c5\uc7a5\uc758 AI \uc7a5\uba74.", "text": "\uc544\ub9c8\uc874 \u2014 \uc8fc\ubb38 \ubc84\ud2bc \ub4a4\uc5d0\ub294 \ubb34\uc5c7\uc774 \ub0a8\uc544 \uc788\uc744\uae4c \ud654\uba74\uc5d0\uc11c \uc0ac\ub294 \ubb3c\uac74\uc740 \uacb0\uad6d \ud604\uc2e4\uc758 \uae38\uc744 \uc9c0\ub098\uc628\ub2e4 2010\ub144\ub300 \uc544\ub9c8\uc874 \uc0ac\ub840\ub97c \ud1b5\ud574 \uc628\ub77c\uc778 \uc8fc\ubb38\uacfc \ubb3c\ub958\u00b7\ud68c\uc6d0\uc81c\u00b7\ub178\ub3d9\uc758 \uc5f0\uacb0\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Technology \uae30\uc5c5 \ubb3c\uac74\uc744 \uace0\ub974\uace0 \uc8fc\ubb38 \ubc84\ud2bc\uc744 \ub204\ub978\ub2e4. \ud654\uba74\uc5d0 \ud655\uc778 \uba54\uc2dc\uc9c0\uac00 \ub728\uba74 \uad6c\ub9e4\ub294 \ub05d\ub09c \uac83\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \uadf8\ub7ec\ub098 \ubb3c\uac74\uc774 \uc6b0\ub9ac \uc9d1\uc5d0 \uc624\ub824\uba74 \uadf8\ub54c\ubd80\ud130 \ub9ce\uc740 \uc77c\uc774 \uc2dc\uc791\ub418\uc5b4\uc57c \ud55c\ub2e4. \ub204\uad70\uac00\ub294 \uc0c1\ud488\uc744 \ucc3e\uace0 \ud3ec\uc7a5\ud558\uace0 \uc6b4\ubc18\ud574\uc57c \ud55c\ub2e4. \uc544\ub9c8\uc874\uc740 \uc774\ub7f0 \ud654\uba74\uacfc \ud604\uc2e4\uc758 \uc5f0\uacb0\uc744 \uc0dd\uac01\ud558\uae30 \uc88b\uc740 \uae30\uc5c5\uc774\ub2e4. OpenStax\uc758 \uacbd\uc601\ud559 \uad50\uc7ac\ub294 2010\ub144\ub300 \uc544\ub9c8\uc874\uc758 \uc628\ub77c\uc778 \ud310\ub9e4 \uc804\ub7b5\uacfc \ubb3c\ub958 \uac70\uc810, \ud68c\uc6d0\uc81c \uc11c\ube44\uc2a4\ub97c \ud568\uaed8 \uc124\uba85\ud55c\ub2e4. \uc778\ud130\ub137 \uae30\uc5c5\uc774\ub77c\uace0 \ud574\uc11c \uc911\uc694\ud55c \uc77c\uc774 \ubaa8\ub450 \uc778\ud130\ub137 \uc548\uc5d0\uc11c\ub9cc \uc774\ub8e8\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uad50\uc7ac\uac00 \uc18c\uac1c\ud558\ub294 \uace0\uac1d\uc758 \ud575\uc2ec \uc9c8\ubb38\uc740 \ub450 \uac00\uc9c0\ub85c \uc815\ub9ac\ub41c\ub2e4. \ub0b4\uac00 \uc6d0\ud558\ub294 \uac83\uc774 \uc788\ub294\uac00, \uadf8\ub9ac\uace0 \ud544\uc694\ud560 \ub54c \ubc1b\uc744 \uc218 \uc788\ub294\uac00. \uc0c1\ud488\uc744 \ub9ce\uc774 \ubcf4\uc5ec \uc8fc\ub294 \ub2a5\ub825\uacfc \uc2e4\uc81c\ub85c \uc804\ub2ec\ud558\ub294 \ub2a5\ub825\uc774 \ud568\uaed8 \ud544\uc694\ud558\ub2e4\ub294 \ub73b\uc774\ub2e4. \uccab \uc9c8\ubb38\uc5d0\ub9cc \ub2f5\ud558\uba74 \ubaa9\ub85d\uc774 \ud6cc\ub96d\ud55c \uc804\uc2dc\uc7a5\uc774 \ub420 \uc218 \uc788\ub2e4. \ub450 \ubc88\uc9f8 \uc9c8\ubb38\uc744 \ud574\uacb0\ud558\ub824\uba74 \uc7ac\uace0\uc640 \ubc30\uc1a1, \ub3c4\ucc29\ud560 \uc2dc\uc810\uc744 \ub2e4\ub8e8\uc5b4\uc57c \ud55c\ub2e4. \uace0\uac1d\uc774 \ud3b8\ub9ac\ud558\ub2e4\uace0 \ub290\ub07c\ub294 \uacbd\ud5d8\uc740 \uc774 \ub450 \uac00\uc9c0\uac00 \uc5b4\uae0b\ub098\uc9c0 \uc54a\uc744 \ub54c \ub9cc\ub4e4\uc5b4\uc9c4\ub2e4. \ud654\uba74\uc758 \uac04\uacb0\ud568 \ub4a4\uc5d0\ub294 \ub2e4\ub978 \uc885\ub958\uc758 \ubcf5\uc7a1\ud568\uc774 \uc788\ub2e4. \uc544\ub9c8\uc874\uc758 \ub514\uc9c0\ud138 \ud310\ub9e4\ub294 \uc721\uc9c0\uc758 \ubb3c\ub958 \uac70\uc810\uacfc \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub2e4. \ubb3c\ub9ac\uc801\uc778 \uc0c1\ud488\uc744 \ubcf4\uad00\ud558\uace0 \uc8fc\ubb38\uc5d0 \ub9de\ucd94\uc5b4 \ub0b4\ubcf4\ub0b4\uc57c \ud558\uae30 \ub54c\ubb38\uc774\ub2e4. \uace0\uac1d\uc774 \ub9e4\uc7a5 \uc548\uc744 \uac78\uc5b4 \ub2e4\ub2c8\uc9c0 \uc54a\ub294 \ub300\uc2e0 \uc0c1\ud488\uc744 \uc900\ube44\ud558\ub294 \uacf5\uac04\uc740 \ub2e4\ub978 \uacf3\uc5d0 \uc874\uc7ac\ud55c\ub2e4. \uc774 \uc810\uc744 \uc54c\uba74 \uc628\ub77c\uc778\uacfc \uc624\ud504\ub77c\uc778\uc744 \uc644\uc804\ud788 \uac08\ub77c \uc0dd\uac01\ud558\uae30 \uc5b4\ub835\ub2e4. \uc6f9\uc0ac\uc774\ud2b8\uac00 \ubc14\ub00c\ub294 \uc18d\ub3c4\uc640 \ucc3d\uace0\u00b7\uc6b4\uc1a1\uc758 \uc870\uac74\uc740 \ub2e4\ub974\ub2e4. \ud654\uba74\uc5d0\uc11c \ud310\ub9e4 \uc9c0\uc5ed\uc744 \ub113\ud788\ub294 \uac83\uacfc \uadf8 \uc9c0\uc5ed\uc5d0 \uc548\uc815\uc801\uc73c\ub85c \ubb3c\uac74\uc744 \ubcf4\ub0bc \uc218 \uc788\ub294 \uac83\uc740 \uac19\uc740 \uc791\uc5c5\uc774 \uc544\ub2c8\ub2e4. \uad50\uc7ac\ub294 \ud504\ub77c\uc784 \ud68c\uc6d0\uc81c\ub97c \uc544\ub9c8\uc874 \uc804\ub7b5\uc758 \uc911\uc694\ud55c \uc77c\ubd80\ub85c \uc124\uba85\ud55c\ub2e4. \uace0\uac1d\uc774 \uad6c\ub9e4\ud560 \ub54c\ub9c8\ub2e4 \uac1c\ubcc4\uc801\uc73c\ub85c\ub9cc \ud310\ub2e8\ud558\ub294 \uad00\uacc4\uc5d0\uc11c, \uc77c\uc815\ud55c \uc870\uac74\uc758 \uc11c\ube44\uc2a4\ub97c \uacc4\uc18d \uc774\uc6a9\ud558\ub294 \uad00\uacc4\ub85c \ubc14\uafb8\ub294 \ubc29\uc2dd\uc774\ub2e4. \uae30\uc5c5\uc740 \ubc18\ubcf5\ud574\uc11c \ucc3e\uc544\uc624\ub294 \uace0\uac1d\uacfc\uc758 \uc5f0\uacb0\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub2e4. \uc5ec\uae30\uc11c \ub2f9\uc2dc \ud68c\uc6d0\ube44\ub098 \uc81c\uacf5 \ud61c\ud0dd\uc744 \uc624\ub298\uc758 \uc548\ub0b4\ub85c \uc62e\uae38 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc774\ubc88 \uae00\uc740 \uc5ed\uc0ac\uc801 \uacbd\uc601 \uc0ac\ub840\ub97c \ub2e4\ub8ec\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \ud68c\uc6d0\uc81c\uac00 \ud654\uba74 \uc704\uc5d0 \ubd99\uc740 \ud560\uc778 \ud45c\uc2dc\ub9cc\uc774 \uc544\ub2c8\ub77c \ubc18\ubcf5 \uc774\uc6a9\uacfc \ubb3c\ub958 \uc11c\ube44\uc2a4\ub97c \ud568\uaed8 \uc0dd\uac01\ud558\uac8c \ud558\ub294 \uc0ac\uc5c5 \uad6c\uc870\uc600\ub2e4\ub294 \uc810\uc774\ub2e4. \ubb3c\uac74\uc744 \ube68\ub9ac \ubc1b\ub294 \uacbd\ud5d8\uc740 \ud3b8\ub9ac\ud558\ub2e4. \ud558\uc9c0\ub9cc \uc18d\ub3c4\ub97c \ub192\uc774\ub824\uba74 \uc6b4\uc601\uc5d0 \ud544\uc694\ud55c \uc790\uc6d0\uacfc \ube44\uc6a9\uc774 \uc0dd\uae34\ub2e4. \uad50\uc7ac\ub294 \uc544\ub9c8\uc874\uc758 \uacfc\uc81c\ub85c \ub192\uc740 \ubc30\uc1a1 \ube44\uc6a9\ub3c4 \ud568\uaed8 \uc18c\uac1c\ud55c\ub2e4. \uc8fc\ubb38\uc774 \ub9ce\uc544\uc84c\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uc8fc\ubb38\uc774 \uac19\uc740 \ub9cc\ud07c \uc774\uc775\uc744 \ub0a8\uae34\ub2e4\uace0 \ubcfc \uc218\ub294 \uc5c6\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \uace0\uac1d\uc774 \ub290\ub07c\ub294 \uc9e7\uc740 \uae30\ub2e4\ub9bc\uc740 \uae30\uc5c5\uc774 \ubbf8\ub9ac \uc900\ube44\ud55c \uacf5\uac04\uacfc \uc791\uc5c5\uc758 \uacb0\uacfc\uc77c \uc218 \uc788\ub2e4. \uc774\uac83\uc740 \ud2b9\uc815 \ubc30\uc1a1\uc758 \ub0b4\ubd80 \uc6d0\uac00\ub97c \uacc4\uc0b0\ud55c \uc124\uba85\uc740 \uc544\ub2c8\ub2e4. \ud3b8\ub9ac\ud568\uc758 \uac00\uaca9\uc774 \uc5b4\ub514\uc5d0 \ub193\uc774\ub294\uc9c0 \uc9c8\ubb38\ud558\ub294 \uad00\uc810\uc774\ub2e4. \ud654\uba74\uc5d0\uc11c \ubb34\ub8cc\ub85c \ubcf4\uc774\ub294 \uc11c\ube44\uc2a4\uc640 \ud604\uc2e4\uc5d0\uc11c \ube44\uc6a9\uc774 \ub4e4\uc9c0 \uc54a\ub294 \uc11c\ube44\uc2a4\ub294 \ub2e4\ub974\ub2e4. \ud574\ub2f9 \uc0ac\ub840\ub294 \ubb3c\ub958 \uacf5\uac04\uc5d0\uc11c \uc0ac\ub78c\uacfc \ub85c\ubd07\uc774 \ud568\uaed8 \uc77c\ud558\ub294 \ubaa8\uc2b5\uc744 \uc18c\uac1c\ud55c\ub2e4. \uc790\ub3d9\ud654\uac00 \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud558\ub354\ub77c\ub3c4 \uc8fc\ubb38 \ud558\ub098\uac00 \uc544\ubb34\ub7f0 \uc0ac\ub78c\uc758 \uc77c \uc5c6\uc774 \ucc98\ub9ac\ub41c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ubb34\uc5c7\uc744 \uae30\uacc4\uac00 \ub9e1\uace0 \ubb34\uc5c7\uc744 \uc0ac\ub78c\uc774 \ub9e1\ub294\uc9c0 \ubcc4\ub3c4\ub85c \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uae30\uc220\uc744 \ub3c4\uc785\ud588\ub2e4\ub294 \uc18c\uc2dd\ub9cc \ub4e4\uc73c\uba74 \uc804\uccb4 \uacfc\uc815\uc774 \ud55c \ubc88\uc5d0 \ubc14\ub010 \uac83\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \uc2e4\uc81c\ub85c\ub294 \uae30\uc874 \uc791\uc5c5\uacfc \uc0c8\ub85c\uc6b4 \uc7a5\uce58\uac00 \ud568\uaed8 \ub3cc\uc544\uac08 \uc218 \uc788\ub2e4. \uc5b4\ub290 \ud55c \ucc3d\uace0\uc758 \uc124\ube44\ub97c \ub2e4\ub978 \ubaa8\ub4e0 \uacf3\uc5d0 \uc801\uc6a9\ud558\ub294 \uc2dd\uc73c\ub85c \ub113\ud600 \ub9d0\ud560 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \uc774\ubc88 \uadf8\ub9bc \uc5ed\uc2dc \ud2b9\uc815 \ud604\uc7a5\uc744 \ubcf5\uc6d0\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uad50\uc7ac\ub294 \ub2f9\uc2dc \ubb3c\ub958 \ud604\uc7a5\uc758 \ub178\ub3d9 \uc870\uac74\uacfc \ubc30\uc1a1 \uacc4\uc57d\uc790\ub4e4\uc758 \ubd80\ub2f4\uc5d0 \ub300\ud55c \ube44\ud310\ub3c4 \ub2e4\ub8ec\ub2e4. \uc11c\ube44\uc2a4\uc758 \uc18d\ub3c4\ub97c \ud3c9\uac00\ud560 \ub54c \uace0\uac1d\uc774 \uae30\ub2e4\ub9b0 \uc2dc\uac04\ub9cc \ubcfc \uc218\ub294 \uc5c6\ub2e4\ub294 \ub73b\uc774\ub2e4. \uadf8 \uc2dc\uac04\uc744 \uc904\uc774\ub294 \uacfc\uc815\uc5d0\uc11c \uc77c\ud558\ub294 \uc0ac\ub78c\uc758 \uacbd\ud5d8\ub3c4 \uc0dd\uae34\ub2e4. \uc774\uac83\uc740 \uae30\uc5c5\uc758 \ubaa8\ub4e0 \ud65c\ub3d9\uc744 \ud55c \uac00\uc9c0 \ud3c9\uac00\ub85c \ub05d\ub0b4\ub824\ub294 \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \ub9e4\ucd9c\uacfc \uc774\uc6a9\uc790\uc758 \ub9cc\uc871\uc774 \ub192\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uadfc\ubb34 \uc870\uac74\uc5d0 \uad00\ud55c \uc9c8\ubb38\uc744 \uc790\ub3d9\uc73c\ub85c \ud574\uacb0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uac19\uc740 \uc0ac\uc5c5\uc744 \uace0\uac1d\uacfc \uc9c1\uc6d0, \uc8fc\ubcc0\uc758 \ub2e4\ub978 \uae30\uc5c5\uc774 \uc11c\ub85c \ub2e4\ub978 \uc790\ub9ac\uc5d0\uc11c \uacbd\ud5d8\ud560 \uc218 \uc788\ub2e4. \uc628\ub77c\uc778 \ud310\ub9e4\uac00 \ucee4\uc9c0\uba74 \uace0\uac1d\ubfd0 \uc544\ub2c8\ub77c \ub2e4\ub978 \ud310\ub9e4\uc790\uc758 \ud658\uacbd\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uad50\uc7ac\ub294 \ub3c5\ub9bd \uc0ac\uc5c5\uc790\ub4e4\uc774 \uc544\ub9c8\uc874\uacfc\uc758 \uacbd\uc7c1\uc744 \uc911\uc694\ud55c \ubb38\uc81c\ub85c \ubcf4\uc558\ub358 \uc0ac\ub840\ub97c \uc18c\uac1c\ud55c\ub2e4. \ud55c \uae30\uc5c5\uc758 \ud3b8\ub9ac\ud55c \uc11c\ube44\uc2a4\uac00 \uc2dc\uc7a5\uc758 \ub2e4\ub978 \ucc38\uc5ec\uc790\uc5d0\uac8c\ub294 \uc0c8\ub85c\uc6b4 \ub300\uc751\uc744 \uc694\uad6c\ud560 \uc218 \uc788\uc5c8\ub2e4. \uc774 \uad00\uacc4\ub97c \uc131\uacf5\ud55c \ud68c\uc0ac\uc640 \ub4a4\ucc98\uc9c4 \uac00\uac8c\ub77c\ub294 \ub450 \uce78\uc73c\ub85c\ub9cc \uc815\ub9ac\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uaddc\ubaa8\uc640 \ubc30\uc1a1 \uccb4\uacc4, \uace0\uac1d\uc774 \ucc3e\uc544\uc624\ub294 \uacbd\ub85c\uac00 \ub2e4\ub974\uba74 \uc120\ud0dd\ud560 \uc218 \uc788\ub294 \ubc29\ubc95\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uae30\uc5c5 \uc774\uc57c\uae30\ub97c \uc77d\ub294 \uc7ac\ubbf8\ub294 \ud55c \ud68c\uc0ac\uc758 \uc131\uc7a5\ubfd0 \uc544\ub2c8\ub77c \uadf8 \uc8fc\ubcc0\uc758 \uad00\uacc4\uac00 \ubc14\ub00c\ub294 \ub370\ub3c4 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uc0c1\ud488\uc744 \ud655\uc778\ud558\uace0 \ud3ec\uc7a5\ud558\ub294 \uc791\uc5c5\uc7a5\uc758 \ubd84\uc704\uae30\ub97c \ud45c\ud604\ud588\ub2e4. \uc544\ub9c8\uc874\uc758 \uc2e4\uc81c \uc9c1\uc6d0\u00b7\ucc3d\uace0\u00b7\ud604\uc7ac \ud45c\uc900 \uc791\uc5c5\uc744 \uc7ac\ud604\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \ud654\uba74\uc5d0\uc11c \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc900\ube44\uc640 \uc0ac\ub78c\uc758 \uc190\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc704\ud55c \uadf8\ub9bc\uc774\ub2e4. \uc774 \uc0ac\ub840\ub294 \uc778\ud130\ub137 \uae30\uc5c5\uc758 \uacbd\uc7c1\ub825\uc774 \ud654\uba74 \ub514\uc790\uc778\uc5d0\ub9cc \uc788\uc9c0 \uc54a\ub2e4\ub294 \uc810\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc8fc\ubb38\uc774 \ud604\uc2e4\uc758 \ubb3c\uac74\uacfc \ub9cc\ub098\ub294 \uc5f0\uacb0\ub3c4 \uc124\uacc4\ud574\uc57c \ud588\ub2e4. \ub2e4\uc74c\uc5d0 \uc791\uc740 \uc0c1\uc790\ub97c \ubc1b\uc744 \ub54c\ub294 \uc7ac\uc0dd\ub418\ub294 \uc54c\ub9bc\ubfd0 \uc544\ub2c8\ub77c, \uadf8 \uc0c1\uc790\uac00 \ud654\uba74\uc5d0\uc11c \ubb38 \uc55e\uae4c\uc9c0 \uc624\ub294 \ub3d9\uc548 \uac70\ucce4\uc744 \uc77c\ub4e4\ub3c4 \uc7a0\uae50 \uc0dd\uac01\ud574 \ubcfc \ub9cc\ud558\ub2e4."}, {"id": "away-suitcase-and-travel-book", "title": "\uc5b4\uc6e8\uc774 \u2014 \uc5ec\ud589\uac00\ubc29\ubcf4\ub2e4 \uc5ec\ud589 \ucc45\uc774 \uba3c\uc800 \ub3c4\ucc29\ud588\ub2e4", "summary": "\uc5b4\uc6e8\uc774\uc758 2015~2016\ub144 \ucd08\uae30 \uc0ac\ub840\ub97c \ud1b5\ud574 \uace0\uac1d \uc870\uc0ac\u00b7\uc81c\uc870 \uc120\ud0dd\u00b7\uc608\uc57d \ud310\ub9e4\uc640 \uc2a4\ud1a0\ub9ac\ud154\ub9c1\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "companies", "category_title": "Companies", "subcategory": "Fashion", "url": "stories/away-suitcase-and-travel-book/index.html", "image": "media/away-suitcase-and-travel-book.png", "alt": "\uc5ec\ud589\uac00\ubc29\uacfc \ucc45 \uacc1\uc5d0\uc11c \ub450 \uc0ac\ub78c\uc774 \uac00\ubc29 \uc2dc\uc81c\ud488\uc744 \uc758\ub17c\ud558\ub294 AI \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\uc5b4\uc6e8\uc774 \u2014 \uc5ec\ud589\uac00\ubc29\ubcf4\ub2e4 \uc5ec\ud589 \ucc45\uc774 \uba3c\uc800 \ub3c4\ucc29\ud588\ub2e4 \uace0\uc7a5 \ub09c \uac00\ubc29\uc5d0\uc11c \uc81c\ud488\uacfc \uc774\uc57c\uae30\ub97c \ud568\uaed8 \ub9cc\ub4e4\uae30\uae4c\uc9c0 \uc5b4\uc6e8\uc774\uc758 2015~2016\ub144 \ucd08\uae30 \uc0ac\ub840\ub97c \ud1b5\ud574 \uace0\uac1d \uc870\uc0ac\u00b7\uc81c\uc870 \uc120\ud0dd\u00b7\uc608\uc57d \ud310\ub9e4\uc640 \uc2a4\ud1a0\ub9ac\ud154\ub9c1\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Fashion \uae30\uc5c5 \uc5ec\ud589\uc744 \ub5a0\ub0ac\ub294\ub370 \uac00\ubc29\uc774 \uace0\uc7a5 \ub09c\ub2e4. \ubc14\ud034\ub098 \uc190\uc7a1\uc774 \ub54c\ubb38\uc5d0 \uc9d0\uc744 \uc62e\uae30\ub294 \uc77c\uc774 \uac11\uc790\uae30 \ud798\ub4e4\uc5b4\uc9c0\uba74, \ud3c9\uc18c\uc5d0\ub294 \ubcc4\uc0dd\uac01 \uc5c6\ub358 \uc5ec\ud589\uac00\ubc29\uc758 \uc911\uc694\uc131\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \uc81c\ub2c8\ud37c \ub8e8\ube44\uc624\uc5d0\uac8c\ub294 \uc774\ub7f0 \ubd88\ud3b8\uc774 \uc0c8\ub85c\uc6b4 \uc0ac\uc5c5\uc744 \uc0dd\uac01\ud558\ub294 \uacc4\uae30\uac00 \ub418\uc5c8\ub2e4. \ub8e8\ube44\uc624\ub294 \uc2a4\ud14c\ud37c\ub2c8 \ucf54\ub9ac\uc640 \ud568\uaed8 \uc5b4\uc6e8\uc774\ub77c\ub294 \uc5ec\ud589\uac00\ubc29 \ud68c\uc0ac\ub97c \uc900\ube44\ud588\ub2e4. \uadf8\ub7f0\ub370 \ucd08\uae30 \uace0\uac1d \uc911\uc5d0\ub294 \uac00\ubc29\ubcf4\ub2e4 \uba3c\uc800 \uc5ec\ud589 \uc774\uc57c\uae30\ub97c \ub2f4\uc740 \ucc45\uc744 \ubc1b\uc740 \uc0ac\ub78c\ub4e4\uc774 \uc788\uc5c8\ub2e4. \uc544\uc9c1 \ubcf4\ub0b4 \uc904 \uc81c\ud488\uc774 \uc5c6\uc744 \ub54c \ubb34\uc5c7\uc73c\ub85c \uae30\ub300\ub97c \ub9cc\ub4e4 \uac83\uc778\uac00\ub77c\ub294 \uc9c8\ubb38\uc5d0\uc11c \ub098\uc628 \uc120\ud0dd\uc774\uc5c8\ub2e4. OpenStax \uacbd\uc601\ud559 \uad50\uc7ac\ub294 \ub450 \uc0ac\ub78c\uc774 2015\ub144\uc5d0 \uac00\ubc29 \uc2dc\uc7a5\uc744 \uc870\uc0ac\ud558\uae30 \uc2dc\uc791\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub2f9\uc2dc \ub8e8\ube44\uc624\ub294 \uc800\ub834\ud558\uc9c0\ub9cc \ud488\uc9c8\uc774 \uc544\uc26c\uc6b4 \uc81c\ud488\uacfc \ub192\uc740 \ud488\uc9c8\uc774\uc9c0\ub9cc \ube44\uc2fc \uc81c\ud488 \uc0ac\uc774\uc5d0 \uc5ec\uc9c0\uac00 \uc788\ub2e4\uace0 \ubcf4\uc558\ub2e4. \uc774\uac83\uc740 \ucc3d\uc5c5\uc790\uac00 \ubc1c\uacac\ud55c \uc2dc\uc7a5\uc758 \uae30\ud68c\uc774\uc9c0 \ubaa8\ub4e0 \uac00\ubc29\uc758 \uac1d\uad00\uc801\uc778 \ub4f1\uae09\ud45c\ub294 \uc544\ub2c8\ub2e4. \ub450 \uc0ac\ub78c\uc740 \uac00\uaca9\uc758 \uc774\uc720\ub97c \uc81c\ud488 \uc790\uccb4\uc5d0\uc11c\ub9cc \ucc3e\uc9c0 \uc54a\uc558\ub2e4. \uc804\ubb38\uc810\uacfc \ubc31\ud654\uc810 \ub4f1\uc744 \uac70\uce58\ub294 \uc720\ud1b5 \uad6c\uc870\uac00 \ucd5c\uc885 \uac00\uaca9\uc5d0 \uc5b4\ub5a4 \uc601\ud5a5\uc744 \ubbf8\uce58\ub294\uc9c0\ub3c4 \uc0b4\ud3c8\ub2e4. \uc18c\ube44\uc790\uc5d0\uac8c \uc9c1\uc811 \ud310\ub9e4\ud558\uba74 \ub2e4\ub978 \uac00\uaca9\ub300\uc758 \uc81c\ud488\uc744 \uc81c\uc548\ud560 \uc218 \uc788\uaca0\ub2e4\ub294 \uad6c\uc0c1\uc774 \uc5ec\uae30\uc11c \ub098\uc654\ub2e4. \ucc3d\uc5c5 \uacc4\uae30\uac00 \uc0dd\uacbc\ub2e4\uace0 \ubc14\ub85c \uc81c\ud488\uc744 \ub9cc\ub4e4\uc9c0\ub294 \uc54a\uc558\ub2e4. \ub450 \uc0ac\ub78c\uc740 \uc218\ubc31 \uba85\uc5d0\uac8c \uae30\uc874 \uac00\ubc29\uc5d0\uc11c \ubb34\uc5c7\uc774 \uc88b\uace0 \ubb34\uc5c7\uc774 \uac00\uc7a5 \uc131\uac00\uc2e0\uc9c0 \ubb3c\uc5c8\ub2e4. \uc790\uc2e0\uc758 \uc5ec\ud589 \uacbd\ud5d8\uc744 \ucd9c\ubc1c\uc810\uc73c\ub85c \uc0bc\ub418 \ub2e4\ub978 \uc0ac\ub78c\uc758 \ud544\uc694\ub3c4 \uc54c\uc544\ubcf4\ub824 \ud55c \uac83\uc774\ub2e4. \uc774 \ucc28\uc774\ub294 \uc0dd\uac01\ubcf4\ub2e4 \uc911\uc694\ud558\ub2e4. \ub098\uc5d0\uac8c \ub2f5\ub2f5\ud55c \uc810\uc774 \ub9ce\uc740 \uace0\uac1d\uc5d0\uac8c\ub3c4 \uc911\uc694\ud55c \ubb38\uc81c\uc778\uc9c0 \ud655\uc778\ud574\uc57c \ud558\uae30 \ub54c\ubb38\uc774\ub2e4. \uc5b4\ub5a4 \ubc14\ud034\ub97c \uc4f8\uc9c0, \ubb34\uac8c\uc640 \uc678\ud615\uc744 \uc5b4\ub5bb\uac8c \ub9de\ucd9c\uc9c0 \uac19\uc740 \uacb0\uc815\uc740 \uace0\uac1d\uc758 \ub9d0\uc744 \uc2e4\uc81c \ubb3c\uac74\uc758 \uc120\ud0dd\uc73c\ub85c \uc62e\uae30\ub294 \uacfc\uc815\uc774\uc5c8\ub2e4. \uc778\ud130\ubdf0\ub294 \uc81c\ud488\uc744 \ub300\uc2e0 \ub9cc\ub4e4\uc5b4 \uc8fc\uc9c0 \uc54a\uc9c0\ub9cc \uacb0\uc815\uc758 \uadfc\uac70\uac00 \ub420 \uc218 \uc788\ub2e4. \ub8e8\ube44\uc624\ub294 \ube0c\ub79c\ub4dc\uc640 \ub9c8\ucf00\ud305 \ucabd, \ucf54\ub9ac\ub294 \uc6b4\uc601\uacfc \uacf5\uae09\ub9dd \ucabd\uc758 \uacbd\ud5d8\uc744 \uac16\uace0 \uc788\uc5c8\ub2e4. \ub450 \uc0ac\ub78c \ubaa8\ub450 \uc804\uc790\uc0c1\uac70\ub798 \uae30\uc5c5\uc5d0\uc11c \uc77c\ud55c \uacbd\ud5d8\ub3c4 \uc788\uc5c8\ub2e4. \uac19\uc740 \uc81c\ud488\uc744 \ubcf4\uba74\uc11c \ubb34\uc5c7\uc744 \uace0\uac1d\uc5d0\uac8c \ub9d0\ud560\uc9c0\uc640 \uc5b4\ub5bb\uac8c \ub9cc\ub4e4\uc5b4 \uc804\ub2ec\ud560\uc9c0\ub97c \ub2e4\ub978 \uac01\ub3c4\uc5d0\uc11c \uc0dd\uac01\ud560 \uc218 \uc788\uc5c8\ub2e4. \uac00\ubc29\uc744 \ub9cc\ub4dc\ub294 \ud68c\uc0ac\ub77c\uace0 \ub514\uc790\uc778\ub9cc \uc798\ud558\uba74 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc0dd\uc0b0\ud560 \uacf3\uc744 \ucc3e\uace0 \ube44\uc6a9\uc744 \ub9c8\ub828\ud558\uba70 \uace0\uac1d\uc744 \ub9cc\ub098\uc57c \ud55c\ub2e4. \uc11c\ub85c \ub2e4\ub978 \ub2a5\ub825\uc744 \ud568\uaed8 \uc4f0\ub294 \uc77c\uc740 \ucc3d\uc5c5\uc790\uc758 \uac1c\uc778\uc801\uc778 \uc601\uac10\ub9cc\ud07c \uc911\uc694\ud588\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \ubb3c\uac74 \ud558\ub098\uc758 \ub4a4\uc5d0\ub294 \uc5ec\ub7ec \uc885\ub958\uc758 \ud310\ub2e8\uc774 \ud544\uc694\ud558\ub2e4. \ub450 \uc0ac\ub78c\uc740 \uc81c\uc870 \ud30c\ud2b8\ub108\ub3c4 \uc870\uc0ac\ud588\ub2e4. \ub2e8\ub2e8\ud55c \ud3f4\ub9ac\uce74\ubcf4\ub124\uc774\ud2b8 \uc678\uc7a5\uc744 \ub9cc\ub4dc\ub294 \ud6c4\ubcf4 \uc5c5\uccb4\ub4e4\uc774 \uc544\uc2dc\uc544\uc5d0 \ub9ce\uc558\uace0, \uc5ec\ub7ec \uacf3\uc744 \ube44\uad50\ud55c \ub4a4 \uc9c1\uc811 \ubc29\ubb38\ud588\ub2e4. \uc790\ub8cc\uc5d0\uc11c \uc88b\uc740 \uc778\uc0c1\uc744 \uc8fc\ub294 \uc5c5\uccb4\uac00 \ud604\uc7a5\uc5d0\uc11c\ub3c4 \ubc18\ub4dc\uc2dc \uac19\uc740 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4\uace0 \uad50\uc7ac\ub294 \uc124\uba85\ud55c\ub2e4. \uacb0\uad6d \uc911\uad6d\uc758 \uc81c\uc870 \ud30c\ud2b8\ub108\uc640 \ud611\ub825\ud588\uc73c\uba70 \uad00\uacc4\ub97c \uc720\uc9c0\ud558\ub294 \ub370\ub3c4 \uc2dc\uac04\uc744 \ub4e4\uc600\ub2e4. \uc81c\ud488\uc744 \uc678\ubd80 \uacf5\uc7a5\uc5d0\uc11c \ub9cc\ub4e0\ub2e4\uace0 \ucc3d\uc5c5\uc790\uc758 \uc77c\uc774 \ub05d\ub098\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \uae30\uc900\uc744 \uacf5\uc720\ud558\uace0 \ubb38\uc81c\uac00 \uc0dd\uae38 \ub54c \uc5b4\ub5bb\uac8c \uc18c\ud1b5\ud560\uc9c0\ub3c4 \uc0ac\uc5c5\uc758 \uc77c\ubd80\ub2e4. \ube0c\ub79c\ub4dc\uc758 \uac89\ubaa8\uc2b5\uacfc \uc0dd\uc0b0\uc758 \uc870\uac74\uc774 \uc5ec\uae30\uc11c \uc5f0\uacb0\ub41c\ub2e4. 2015\ub144 \ub9d0\uc5d0\ub294 \uccab \uc81c\ud488\uc774 \uc900\ube44\ub418\ub294 \uc911\uc774\uc5c8\uc9c0\ub9cc \uc5f0\ub9d0 \uc120\ubb3c \uc2dc\uae30\uc5d0 \ub9de\ucd94\uc5b4 \uac00\ubc29\uc744 \uacf5\uae09\ud558\uae30 \uc5b4\ub824\uc6e0\ub2e4. \uc544\uc9c1 \uc5c6\ub294 \ubb3c\uac74\uc744 \uc774\ubbf8 \uc788\ub294 \uac83\ucc98\ub7fc \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub450 \uc0ac\ub78c\uc740 \uc608\uc57d \uad6c\ub9e4\uc640 \ud568\uaed8 \uc81c\uacf5\ud560 \ub2e4\ub978 \ud615\ud0dc\uc758 \uacbd\ud5d8\uc744 \uc0dd\uac01\ud588\ub2e4. \uadf8 \uacb0\uacfc\uac00 \uc5ec\ud589\uc744 \uc8fc\uc81c\ub85c \ud55c \ucc45\uc774\uc5c8\ub2e4. \uc5ec\ub7ec \ucc3d\uc791\uc790\uc5d0\uac8c \uc5ec\ud589 \uacbd\ud5d8\uc744 \uc778\ud130\ubdf0\ud574 \u300aThe Places We Return To\u300b\ub77c\ub294 \ud558\ub4dc\ucee4\ubc84 \ucc45\uc744 \ub9cc\ub4e4\uc5c8\ub2e4. \uad50\uc7ac\uc5d0 \ub530\ub974\uba74 40\uba85\uc758 \uc774\uc57c\uae30\ub97c \ub2f4\uc558\ub2e4. \uc5ec\ud589\uac00\ubc29\uc744 \ubc14\ub85c \ud3bc\uce60 \uc218 \uc5c6\ub294 \uace0\uac1d\uc5d0\uac8c \uc5ec\ud589\uc774\ub77c\ub294 \uc8fc\uc81c\uc758 \uc77d\uc744\uac70\ub9ac\ub97c \uba3c\uc800 \uac74\ub128 \uc148\uc774\ub2e4. \ub2f9\uc2dc \uc81c\uc548\uc740 \uac00\ubc29 \uc790\uccb4\ub97c \uc989\uc2dc \ubc1b\ub294 \ubc29\uc2dd\uc774 \uc544\ub2c8\uc5c8\ub2e4. 2015\ub144 11\uc6d4\ubd80\ud130 \ud5a5\ud6c4 \uac00\ubc29\uc744 \ubc1b\uc744 \uc218 \uc788\ub294 \uae30\ud504\ud2b8\uce74\ub4dc\ub97c \uad6c\uc785\ud558\uba74 \uc5ec\ud589 \ucc45\uc744 \ud568\uaed8 \ubc1b\uc558\uace0, \uac00\ubc29\uc73c\ub85c \uad50\ud658\ud560 \uc2dc\uc810\uc740 2016\ub144 2\uc6d4\ub85c \uc548\ub0b4\ub418\uc5c8\ub2e4. \ubb3c\uac74\uacfc \uc57d\uc18d\uc758 \uc2dc\uac04\uc744 \uad6c\ubd84\ud574 \uc124\uba85\ud55c \ubc29\uc2dd\uc774\ub2e4. \ucc45\uc740 \uac00\ubc29\uc758 \ubc14\ud034 \uc131\ub2a5\uc744 \uc99d\uba85\ud558\ub294 \uc2dc\ud5d8 \uc131\uc801\uc11c\ub294 \uc544\ub2c8\ub2e4. \ub300\uc2e0 \ube0c\ub79c\ub4dc\uac00 \uc5b4\ub5a4 \uc5ec\ud589\uc744 \uc774\uc57c\uae30\ud558\uace0 \uc2f6\uc740\uc9c0 \ubcf4\uc5ec \uc8fc\uace0, \uc81c\ud488\uc744 \uae30\ub2e4\ub9ac\ub294 \ub3d9\uc548 \uad00\uc2ec\uc744 \uc774\uc5b4 \uc8fc\uc5c8\ub2e4. \uc0ac\ub78c\ub4e4\uc5d0\uac8c \ub9d0\uc744 \uac70\ub294 \ubc29\uc2dd\uacfc \uc2e4\uc81c\ub85c \ubc30\uc1a1\ud574\uc57c \ud558\ub294 \uc758\ubb34\ub294 \uac01\uac01 \uc874\uc7ac\ud588\ub2e4. \uc774 \uc0ac\ub840\ub97c \uc2a4\ud1a0\ub9ac\ud154\ub9c1\ub9cc \uc798\ud558\uba74 \ubb3c\uac74 \uc5c6\uc774\ub3c4 \uc131\uacf5\ud55c\ub2e4\ub294 \uacf5\uc2dd\uc73c\ub85c \uc77d\uc73c\uba74 \uc911\uc694\ud55c \ubd80\ubd84\uc774 \ube60\uc9c4\ub2e4. \uadf8\uc804\uc5d0 \uace0\uac1d \uc870\uc0ac\uc640 \uc2dc\uc81c\ud488 \uac1c\ubc1c, \uc81c\uc870 \ud30c\ud2b8\ub108 \uc120\ud0dd\uc774 \uc788\uc5c8\ub2e4. \ucc45\uc774 \uad00\uc2ec\uc744 \ub9cc\ub4e4\ub354\ub77c\ub3c4 \ub098\uc911\uc5d0 \ubc1b\uc744 \uac00\ubc29\uc774 \uace0\uac1d\uc758 \uae30\ub300\uc5d0 \ub9de\uc544\uc57c \uad00\uacc4\uac00 \uc774\uc5b4\uc9c8 \uc218 \uc788\ub2e4. \uad50\uc7ac\ub294 \ucd08\uae30 \ucc45 1,200\ubd80\uac00 \ubaa8\ub450 \ud310\ub9e4\ub418\uc5c8\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \uc774\ub294 \ub2f9\uc2dc \ucd9c\ubc1c\uc744 \uc124\uba85\ud558\ub294 \uc218\uce58\uc774\uba70 \uc624\ub298\ub0a0 \ud68c\uc0ac\uc758 \uc804\uccb4 \uc131\uacfc\ub97c \ub73b\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc774\ubc88 \uae00\ub3c4 2015~2016\ub144 \ucd08\uae30 \uc0ac\ub840\ub97c \uc77d\ub294 \uac83\uc73c\ub85c, \ud604\uc7ac \uc81c\ud488\uc758 \uac00\uaca9\uc774\ub098 \uae30\ub2a5, \ubc30\uc1a1 \uc870\uac74\uc744 \uc548\ub0b4\ud558\uc9c0 \uc54a\ub294\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uac00\ubc29\uacfc \uc5ec\ud589 \ucc45, \uc81c\ud488\uc744 \uc758\ub17c\ud558\ub294 \uc0ac\ub78c\uc758 \ubaa8\uc2b5\uc744 \ub2f4\uc558\ub2e4. \uc2e4\uc81c \ucc3d\ub9bd\uc790\uc758 \ucd08\uc0c1\uc774\ub098 \ucd08\uae30 \uac00\ubc29\uacfc \ucc45\uc758 \uc815\ud655\ud55c \ub514\uc790\uc778\uc744 \uc7ac\ud604\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \ubb3c\uac74\uc744 \ub9cc\ub4e4\uae30 \uc804\ud6c4\uc5d0 \uc5b4\ub5a4 \uc0dd\uac01\uc774 \uc624\uac14\uc744\uc9c0 \ub5a0\uc62c\ub9ac\ub294 \ubd84\uc704\uae30 \uadf8\ub9bc\uc774\ub2e4. \uc5b4\uc6e8\uc774\uc758 \ucd08\uae30 \uc774\uc57c\uae30\ub294 \uc88b\uc740 \uc81c\ud488\uacfc \uc88b\uc740 \uc774\uc57c\uae30\uac00 \uacbd\uc7c1\ud574\uc57c \ud558\ub294 \uac83\uc774 \uc544\ub2d8\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uac00\ubc29\uc740 \uc5ec\ud589\uc758 \uc9d0\uc744 \ub2f4\uace0 \ucc45\uc740 \uc5ec\ud589\uc758 \uae30\uc5b5\uc744 \ub2f4\uc558\ub2e4. \ub458\uc744 \uc5f0\uacb0\ud55c \uc120\ud0dd\uc774 \ud765\ubbf8\ub85c\uc6b4 \uc774\uc720\ub294 \ubb3c\uac74 \ud558\ub098\ub97c \ud314\uae30 \uc704\ud574\uc11c\ub3c4 \uc0ac\ub78c\uc758 \ubd88\ud3b8\uacfc \uae30\ub300, \uae30\ub2e4\ub9ac\ub294 \uc2dc\uac04\uae4c\uc9c0 \uc0dd\uac01\ud574\uc57c \ud588\uae30 \ub54c\ubb38\uc774\ub2e4."}, {"id": "bmw-car-made-across-borders", "title": "BMW \u2014 \ub3c5\uc77c \uc790\ub3d9\ucc28\ub97c \ubbf8\uad6d\uc5d0\uc11c \ub9cc\ub4e4\uba74", "summary": "BMW\uc758 \ubbf8\uad6d \uc0dd\uc0b0 \uc0ac\ub840\ub85c \ud574\uc678 \uacf5\uc7a5\u00b7\ubb3c\ub958\u00b7\uc2dc\uc7a5\uacfc \ube0c\ub79c\ub4dc\uc758 \uad00\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "companies", "category_title": "Companies", "subcategory": "Automotive", "url": "stories/bmw-car-made-across-borders/index.html", "image": "media/bmw-car-made-across-borders.png", "alt": "\uc77c\ubc18\uc801\uc778 \uc790\ub3d9\ucc28 \uc870\ub9bd \uacf5\uac04\uc5d0\uc11c \ucc28\uccb4\ub97c \uc0b4\ud53c\ub294 \uc791\uc5c5\uc790\ub4e4\uc758 \uc0bd\ud654.", "text": "BMW \u2014 \ub3c5\uc77c \uc790\ub3d9\ucc28\ub97c \ubbf8\uad6d\uc5d0\uc11c \ub9cc\ub4e4\uba74 \ube0c\ub79c\ub4dc\uc758 \uace0\ud5a5\uacfc \uacf5\uc7a5\uc758 \uc8fc\uc18c\ub294 \uc65c \ub2e4\ub97c\uae4c BMW\uc758 \ubbf8\uad6d \uc0dd\uc0b0 \uc0ac\ub840\ub85c \ud574\uc678 \uacf5\uc7a5\u00b7\ubb3c\ub958\u00b7\uc2dc\uc7a5\uacfc \ube0c\ub79c\ub4dc\uc758 \uad00\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Automotive \uae30\uc5c5 \uc790\ub3d9\ucc28\ub97c \ubcf4\uba70 \ub3c5\uc77c \ube0c\ub79c\ub4dc\ub77c\uace0 \ub9d0\ud55c\ub2e4. \uadf8\ub7f0\ub370 \uadf8 \ucc28\ub97c \ub9cc\ub4e0 \uacf5\uc7a5\uc740 \ubbf8\uad6d\uc5d0 \uc788\uc744 \uc218 \uc788\ub2e4. \uc774\ub984\uc744 \uc775\uc219\ud558\uac8c \uc54c\uace0 \uc788\uc744\uc218\ub85d \ucc98\uc74c\uc5d0\ub294 \ub73b\ubc16\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \ube0c\ub79c\ub4dc\uc758 \uace0\ud5a5\uacfc \uc870\ub9bd\ub41c \uc7a5\uc18c\ub294 \uc65c \uac19\uc740 \uc8fc\uc18c\uac00 \uc544\ub2d0\uae4c. BMW\uc758 \ubbf8\uad6d \uc0dd\uc0b0\uc740 \uacbd\uc601\ud559 \uad50\uc7ac\uac00 \ud574\uc678 \uc9c1\uc811\ud22c\uc790\ub97c \uc124\uba85\ud558\ub294 \uc0ac\ub840 \uac00\uc6b4\ub370 \ud558\ub098\ub2e4. \uc790\ub3d9\ucc28\uac00 \uad6d\uacbd\uc744 \ub118\ub294\ub2e4\ub294 \uac83\uc740 \uc644\uc131\ub41c \ucc28\ub97c \ubc30\uc5d0 \uc2e3\ub294 \uc77c\ub9cc\uc774 \uc544\ub2c8\ub2e4. \uae30\uc5c5\uc774 \uacf5\uc7a5\uc744 \ub2e4\ub978 \ub098\ub77c\uc5d0 \uc138\uc6b0\ub294 \ubc29\uc2dd\uc73c\ub85c \uc0dd\uc0b0\uc758 \uc9c0\ub3c4\ub97c \ubc14\uafb8\uae30\ub3c4 \ud55c\ub2e4. \ube0c\ub79c\ub4dc\uc5d0\ub294 \uc5ed\uc0ac\uc640 \ub514\uc790\uc778, \uc0ac\ub78c\ub4e4\uc774 \uc313\uc544 \uc628 \uc774\ubbf8\uc9c0\uac00 \ubd99\ub294\ub2e4. BMW\ub97c \ub3c5\uc77c \uc790\ub3d9\ucc28 \ud68c\uc0ac\ub77c\uace0 \ubd80\ub974\ub294 \ub9d0\uc5d0\ub294 \uadf8\ub7f0 \ubc30\uacbd\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uadf8 \ud45c\ud604\uc774 \ubaa8\ub4e0 \uc81c\ud488\uc758 \ubd80\ud488\uacfc \uc791\uc5c5\uc774 \ud55c \ub098\ub77c \uc548\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc9c4\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc644\uc131\ucc28\uc758 \uc0dd\uc0b0\uc9c0\uc640 \uc124\uacc4\u00b7\uae30\uc5c5\uc758 \ubcf8\uac70\uc9c0, \ubd80\ud488\uc744 \uacf5\uae09\ubc1b\ub294 \uacf3\uc740 \uc11c\ub85c \ub2e4\ub978 \uc9c8\ubb38\uc774\ub2e4. \uc790\ub3d9\ucc28 \ud55c \ub300\uc758 \uad6d\uc801\uc774\ub77c\ub294 \ud45c\ud604\uc740 \uc77c\uc0c1\uc801\uc73c\ub85c \ud3b8\ub9ac\ud558\uc9c0\ub9cc \uadf8 \uc548\uc5d0 \uc5ec\ub7ec \uc885\ub958\uc758 \uc5f0\uacb0\uc744 \ubb36\uc5b4 \ub193\uae30\ub3c4 \ud55c\ub2e4. \ubb34\uc5c7\uc744 \uc54c\uace0 \uc2f6\uc740\uc9c0 \ub098\ub204\uc5b4 \ubcf4\uba74 \ub2f5\ub3c4 \ub354 \ubd84\uba85\ud574\uc9c4\ub2e4. \uad50\uc7ac\ub294 \ubbf8\uad6d \uc0ac\uc6b0\uc2a4\uce90\ub864\ub77c\uc774\ub098\uc8fc \uc2a4\ud30c\ud134\ubc84\uadf8\uc758 BMW \uacf5\uc7a5\uc5d0\uc11c SUV\uac00 \uc0dd\uc0b0\ub418\ub294 \uc0ac\ub840\ub97c \uc124\uba85\ud55c\ub2e4. \ub2f9\uc2dc X3\uc640 X5 \uac19\uc740 \ubaa8\ub378\uc744 \ub4e4\uc5c8\ub2e4. \uc774\ub294 \uadf8 \uc2dc\uae30\uc758 \uc0ac\ub840\uc774\uba70 \ud604\uc7ac \ubaa8\ub4e0 \ubaa8\ub378\uc758 \uc0dd\uc0b0\uc9c0\ub97c \uc815\ub9ac\ud55c \ubaa9\ub85d\uc740 \uc544\ub2c8\ub2e4. \uc911\uc694\ud55c \uc810\uc740 \uc678\uad6d \uae30\uc5c5\uc774 \uc644\uc131\ucc28\ub97c \uc218\ucd9c\ub9cc \ud558\ub294 \ub300\uc2e0 \ud604\uc9c0\uc5d0\uc11c \uc0dd\uc0b0 \uc2dc\uc124\uc744 \uc6b4\uc601\ud588\ub2e4\ub294 \uac83\uc774\ub2e4. \uc18c\ube44\uc790\ub294 \ub3c5\uc77c \ud68c\uc0ac\uc758 \ube0c\ub79c\ub4dc\ub97c \uc120\ud0dd\ud558\uba74\uc11c \ubbf8\uad6d\uc5d0\uc11c \uc870\ub9bd\ub41c \uc81c\ud488\uc744 \uc0b4 \uc218 \uc788\ub2e4. \ucc98\uc74c\uc758 \ubaa8\uc21c\uc740 \uc11c\ub85c \ub2e4\ub978 \uc8fc\uc18c\ub97c \uac19\uc740 \uc885\ub958\uc758 \uc815\ubcf4\ub85c \ubcf4\uc558\uc744 \ub54c \uc0dd\uae34 \uc148\uc774\ub2e4. \uae30\uc5c5\uc774 \ud574\uc678 \uacf5\uc7a5\uc744 \uc138\uc6b0\ub294 \uc774\uc720 \uac00\uc6b4\ub370 \ud558\ub098\ub294 \uace0\uac1d\uc5d0\uac8c \ub354 \uac00\uae4c\uc6cc\uc9c0\ub294 \uac83\uc774\ub2e4. \uc81c\ud488\uc744 \uba40\ub9ac\uc11c \uc644\uc131\ud574 \ubcf4\ub0b4\ub294 \ubc29\uc2dd\uacfc \ud604\uc9c0\uc5d0\uc11c \ub9cc\ub4dc\ub294 \ubc29\uc2dd\uc740 \ubb3c\ub958\uc640 \uc77c\uc815\uc758 \uc870\uac74\uc774 \ub2e4\ub974\ub2e4. \ucee4\ub2e4\ub780 \uc790\ub3d9\ucc28\ub97c \uc5b4\ub5bb\uac8c \uc774\ub3d9\uc2dc\ud0ac\uc9c0\ub3c4 \ube44\uc6a9\uacfc \uc5f0\uacb0\ub41c\ub2e4. \ubb3c\ub860 \uacf5\uc7a5\uc774 \uac00\uae5d\ub2e4\uace0 \ubaa8\ub4e0 \ubd80\ud488\uae4c\uc9c0 \uac00\uae4c\uc6b4 \uacf3\uc5d0\uc11c \uc624\uac70\ub098 \ubaa8\ub4e0 \ubc30\uc1a1\uc774 \ube68\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc0dd\uc0b0\uc9c0\uc758 \uc774\ub3d9\uc740 \uacf5\uae09\ub9dd \uc804\uccb4\uc758 \uad00\uacc4\ub97c \ub2e4\uc2dc \uc9dc\ub294 \ubb38\uc81c\ub2e4. \ud55c \uad6c\uac04\uc744 \uc904\uc774\uba74\uc11c \ub2e4\ub978 \uad6c\uac04\uc758 \uc774\ub3d9\uc774 \uc0dd\uae38 \uc218\ub3c4 \uc788\ub2e4. \ud604\uc9c0 \uc0dd\uc0b0\uc774\ub77c\ub294 \ub9d0 \ub4a4\uc758 \uad6c\uccb4\uc801\uc778 \uc5f0\uacb0\uc744 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uad50\uc7ac\ub294 \ud604\uc9c0 \uc0dd\uc0b0\uc774 \uc218\uc785\ud488\uc5d0 \ubd80\uacfc\ub418\ub294 \uad00\uc138\ub098 \ubb34\uc5ed \uc7a5\ubcbd\uacfc \uad00\ub828\ub420 \uc218 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ubb3c\uac74\uc744 \ud310\ub9e4\ud560 \uc2dc\uc7a5\uc5d0 \uacf5\uc7a5\uc744 \ub450\uba74 \uc644\uc131\ud488 \uc218\uc785\uacfc \ub2e4\ub978 \uc870\uac74\uc744 \ub9cc\ub0a0 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uae30\uc5c5\uc758 \uc785\uc9c0 \uc120\ud0dd\uc740 \uae30\uc220 \ubb38\uc81c\ub9cc\uc774 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \uc774 \uc124\uba85\uc744 \ud604\uc7ac\uc758 \ud2b9\uc815 \uad00\uc138\uc728\uc774\ub098 \uc815\ucc45\uc5d0 \ubc14\ub85c \uc801\uc6a9\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc81c\ub3c4\ub294 \uc2dc\uae30\uc640 \ub098\ub77c, \ud488\ubaa9\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c4\ub2e4. \uc774\ubc88 \uc6d0\uace0\ub294 \uc5b4\ub5a4 \uc815\uce58\uc801 \uacb0\uc815\uc774 \ucd5c\uc2e0\uc73c\ub85c \ub0b4\ub824\uc84c\ub294\uc9c0 \uc54c\ub824 \uc8fc\uae30\ubcf4\ub2e4, \uacf5\uc7a5 \uc8fc\uc18c\ub97c \uc815\ud560 \ub54c \uc81c\ub3c4\ub3c4 \uace0\ub824\ud55c\ub2e4\ub294 \uc6d0\ub9ac\ub97c \uc77d\ub294 \uae00\uc774\ub2e4. \uc0dd\uc0b0 \uc2dc\uc124\uc5d0\ub294 \uc124\ube44\ubfd0 \uc544\ub2c8\ub77c \uae30\uc220\uc744 \uac00\uc9c4 \uc0ac\ub78c\uacfc \uacf5\uae09\uc790, \uad00\ub9ac\uc758 \uad00\uacc4\uac00 \ud544\uc694\ud558\ub2e4. \ud604\uc9c0\uc758 \uc804\ubb38\uc131\uacfc \ube44\uc6a9 \uc870\uac74\ub3c4 \ud574\uc678 \uc9c1\uc811\ud22c\uc790\uc758 \uc774\uc720\uac00 \ub420 \uc218 \uc788\ub2e4\uace0 \uad50\uc7ac\ub294 \uc124\uba85\ud55c\ub2e4. \uae30\uc5c5\uc740 \ub545 \uc704\uc5d0 \uacf5\uc7a5 \uac74\ubb3c \ud55c \ucc44\ub9cc \uc62e\uae30\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc0dd\uc0b0 \uae30\uc900\uacfc \ud6c8\ub828, \ubd80\ud488\uc758 \ud488\uc9c8\uacfc \uc791\uc5c5\uc758 \uc5f0\uacb0\uc744 \ub9c8\ub828\ud574\uc57c \ud55c\ub2e4. \uc774 \ubd80\ubd84\uc740 \uc6d0\ub9ac\ub97c \uc124\uba85\ud558\ub294 \uac83\uc774\uba70 \ud2b9\uc815 BMW \uacf5\uc7a5\uc758 \ud604\uc7ac \uad50\uc721 \uacfc\uc815\uc744 \ucde8\uc7ac\ud55c \uae30\ub85d\uc740 \uc544\ub2c8\ub2e4. \uac19\uc740 \uc0c1\ud45c\uc758 \uc81c\ud488\uc744 \uc5ec\ub7ec \uc7a5\uc18c\uc5d0\uc11c \ub9cc\ub4e0\ub2e4\ub294 \ubaa9\ud45c\uc5d0\ub294 \uadf8\ub7f0 \uae30\uc900\uc744 \uc774\uc5b4 \uac00\ub294 \uacfc\uc81c\uac00 \uc0dd\uae34\ub2e4. \uc0dd\uc0b0 \uad6d\uac00\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uc81c\ud488\uc758 \ud488\uc9c8\uc744 \uc815\ud558\uba74 \uc911\uc694\ud55c \ucc28\uc774\ub97c \ub193\uce60 \uc218 \uc788\ub2e4. \uc5b4\ub5a4 \uc124\uacc4\uc640 \uae30\uc900\uc744 \uc801\uc6a9\ud558\uace0 \uc5b4\ub5a4 \ubd80\ud488\uc744 \uc4f0\uba70 \uc5b4\ub5bb\uac8c \ud655\uc778\ud588\ub294\uc9c0\uac00 \ud568\uaed8 \uad00\uc5ec\ud55c\ub2e4. \uc88b\uc740 \uc81c\ud488\uc744 \ub9cc\ub4e0\ub2e4\ub294 \uc57d\uc18d\uc740 \uad6d\uae30\uc758 \ubaa8\uc591\ub9cc\uc73c\ub85c \uc2e4\ud589\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc774\uac83\uc740 \uc5b4\ub290 \ub098\ub77c \uacf5\uc7a5\uc774 \ub354 \ub0ab\ub2e4\ub294 \ube44\uad50\uac00 \uc544\ub2c8\ub2e4. \ube0c\ub79c\ub4dc\uc758 \uc774\ubbf8\uc9c0\uc640 \uc2e4\uc81c \uc0dd\uc0b0\uc758 \uc870\uac74\uc744 \ub098\ub204\uc5b4 \uc77d\uc790\ub294 \ub73b\uc774\ub2e4. \uae30\uc5c5\uc774 \ud574\uc678\uc5d0\uc11c \uc0dd\uc0b0\ud574\ub3c4 \uace0\uac1d\uc740 \uc775\uc219\ud55c \uc0c1\ud45c\uc5d0 \uae30\ub300\ub97c \uac16\ub294\ub2e4. \uadf8 \uae30\ub300\uc640 \ud604\uc7a5\uc758 \uacb0\uacfc\ub97c \uc5f0\uacb0\ud558\ub294 \uc77c\uc774 \uae30\uc5c5\uc758 \ucc45\uc784\uc73c\ub85c \ub0a8\ub294\ub2e4. \ud070 \uc0dd\uc0b0 \uc2dc\uc124\uc740 \ub178\ub3d9\uacfc \uacf5\uae09, \uc6b4\uc1a1\uc758 \uad00\uacc4\ub97c \uc8fc\ubcc0\uc5d0 \ub9cc\ub4e0\ub2e4. \ud68c\uc0ac\uac00 \uc2dc\uc7a5 \uac00\uae4c\uc774 \uac14\ub2e4\ub294 \uc124\uba85\uacfc \ud604\uc9c0 \uc0ac\ud68c\uac00 \uacf5\uc7a5\uc744 \ub9de\uc774\ud55c \uacbd\ud5d8\uc740 \ub2e4\ub978 \uac01\ub3c4\uc5d0\uc11c \ubcfc \uc218 \uc788\ub2e4. \ubb34\uc5c7\uc774 \uc774\uc775\uc774\uace0 \uc5b4\ub5a4 \uc900\ube44\uac00 \ud544\uc694\ud55c\uc9c0\ub294 \ucc38\uc5ec\uc790\uc5d0 \ub530\ub77c \ub2e4\ub974\ub2e4. \uc774\ubc88 \uae00\uc740 \uc2a4\ud30c\ud134\ubc84\uadf8 \uc9c0\uc5ed\uc758 \ud604\uc7ac \uace0\uc6a9 \uc218\ub098 \uacbd\uc81c \ud6a8\uacfc\ub97c \uacc4\uc0b0\ud558\uc9c0 \uc54a\ub294\ub2e4. \uadf8\ub7f0 \ud3c9\uac00\ub294 \ubcc4\ub3c4\uc758 \uc9c0\uc5ed \uc790\ub8cc\uac00 \ud544\uc694\ud558\ub2e4. \ub300\uc2e0 \ud574\uc678 \uc9c1\uc811\ud22c\uc790\ub97c \uae30\uc5c5\uc758 \uacb0\uc815\uc73c\ub85c\ub9cc \ub05d\ub0b4\uc9c0 \uc54a\uace0 \uadf8\uacf3\uc5d0\uc11c \ud568\uaed8 \uc77c\ud558\ub294 \uc0ac\ub78c\uacfc \uc5c5\uccb4\uc758 \uad00\uacc4\ub85c\ub3c4 \ubc14\ub77c\ubcfc \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uc791\uc5c5\uc790\ub4e4\uc774 \uc790\ub3d9\ucc28\uc758 \uc77c\ubd80\ub97c \ud655\uc778\ud558\ub294 \uacf5\uc7a5 \ubd84\uc704\uae30\ub2e4. \uc2e4\uc81c BMW \ubaa8\ub378\uacfc \ubbf8\uad6d \uacf5\uc7a5\uc758 \uc124\ube44\ub97c \ubcf5\uc6d0\ud55c \uc0ac\uc9c4\uc774 \uc544\ub2c8\ub2e4. \uc790\ub3d9\ucc28\uac00 \uc5b4\ub5a4 \uc7a5\uc18c\uc758 \uc0dd\uc0b0\uacfc \uc5f0\uacb0\ub418\ub294\uc9c0 \ub5a0\uc62c\ub9ac\uae30 \uc704\ud55c \uc774\ubbf8\uc9c0\ub2e4. \uc774\uc81c \ub3c5\uc77c \ube0c\ub79c\ub4dc\ub77c\ub294 \ub9d0\uacfc \ubbf8\uad6d\uc5d0\uc11c \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \ub9d0\uc774 \uc11c\ub85c \ub2e4\ub974\uac8c \ub2f5\ud558\uace0 \uc788\ub2e4\ub294 \uac83\uc744 \uc54c \uc218 \uc788\ub2e4. \ud558\ub098\ub294 \uae30\uc5c5\uacfc \ube0c\ub79c\ub4dc\uc758 \ubc30\uacbd\uc744, \ub2e4\ub978 \ud558\ub098\ub294 \uc0dd\uc0b0\uc758 \uc7a5\uc18c\ub97c \uac00\ub9ac\ud0a8\ub2e4. \uc790\ub3d9\ucc28 \ud55c \ub300\ub97c \ubcfc \ub54c \uc8fc\uc18c\ub97c \ud558\ub098\ub9cc \ubb3b\uc9c0 \uc54a\uc73c\uba74, \uc138\uacc4\uc758 \uc0b0\uc5c5\uc774 \uc5f0\uacb0\ub418\ub294 \ubc29\uc2dd\ub3c4 \uc870\uae08 \ub354 \uad6c\uccb4\uc801\uc73c\ub85c \ubcf4\uc778\ub2e4."}, {"id": "bombas-socks-and-giving", "title": "\ubd04\ubc14\uc2a4 \u2014 \uc65c \ud558\ud544 \uc591\ub9d0\uc774\uc5c8\uc744\uae4c", "summary": "2013~2017\ub144 \ubd04\ubc14\uc2a4 \uc0ac\ub840\uc5d0\uc11c \ud310\ub9e4 \uc0c1\ud488\u00b7\uae30\ubd80 \uc57d\uc18d\u00b7\uc2e4\uc81c \ud544\uc694\ub97c \ud568\uaed8 \uc0dd\uac01\ud569\ub2c8\ub2e4.", "category": "companies", "category_title": "Companies", "subcategory": "Fashion", "url": "stories/bombas-socks-and-giving/index.html", "image": "media/bombas-socks-and-giving.png", "alt": "\uc0c1\uc790\uc5d0 \uae68\ub057\ud55c \uc591\ub9d0\uc744 \uc815\ub9ac\ud558\ub294 \ub450 \uc0ac\ub78c\uc758 AI \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\ubd04\ubc14\uc2a4 \u2014 \uc65c \ud558\ud544 \uc591\ub9d0\uc774\uc5c8\uc744\uae4c \uc77c\uc0c1\uc801\uc778 \ubb3c\uac74\uc744 \ud30c\ub294 \ud68c\uc0ac\uac00 \ubc1c\uacac\ud55c \ub2e4\ub978 \ud544\uc694 2013~2017\ub144 \ubd04\ubc14\uc2a4 \uc0ac\ub840\uc5d0\uc11c \ud310\ub9e4 \uc0c1\ud488\u00b7\uae30\ubd80 \uc57d\uc18d\u00b7\uc2e4\uc81c \ud544\uc694\ub97c \ud568\uaed8 \uc0dd\uac01\ud569\ub2c8\ub2e4. Fashion \uae30\uc5c5 \uc591\ub9d0\uc740 \uc120\ubb3c\uc758 \uc8fc\uc778\uacf5\uc774 \ub418\uae30\ubcf4\ub2e4 \uc11c\ub78d \uc18d\uc5d0\uc11c \uc790\uae30 \ucc28\ub840\ub97c \uae30\ub2e4\ub9ac\ub294 \ubb3c\uac74\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \ub9e4\uc77c \uc4f0\uc9c0\ub9cc \ud2b9\ubcc4\ud788 \uc774\uc57c\uae30\ud560 \uc77c\uc774 \ub9ce\uc9c0\ub294 \uc54a\ub2e4. \uadf8\ub7f0\ub370 \uc5b4\ub5a4 \ud658\uacbd\uc5d0\uc11c\ub294 \uc774 \ud3c9\ubc94\ud55c \ubb3c\uac74\uc744 \ucda9\ubd84\ud788 \uac16\ucd94\ub294 \uc77c\uc774 \uc911\uc694\ud558\ub2e4. \ubd04\ubc14\uc2a4\ub77c\ub294 \uc591\ub9d0 \ud68c\uc0ac\uc758 \ucd9c\ubc1c\uc5d0\ub294 \uc774\ub7f0 \uad00\ucc30\uc774 \uc788\uc5c8\ub2e4. \uacbd\uc601\ud559 \uad50\uc7ac\ub294 \ucc3d\uc5c5\uc790\ub4e4\uc774 \ub178\uc219\uc778\uc744 \uc9c0\uc6d0\ud558\ub294 \ubcf4\ud638\uc2dc\uc124\uc5d0\uc11c \uc591\ub9d0 \uc694\uccad\uc774 \ub9ce\ub2e4\ub294 \uc810\uc5d0 \uc8fc\ubaa9\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ubb34\uc5c7\uc744 \ud314 \uc218 \uc788\uc744\uae4c\ub77c\ub294 \uc9c8\ubb38 \uc606\uc5d0 \ub204\uac00 \uc5b4\ub5a4 \ubb3c\uac74\uc744 \ud544\uc694\ub85c \ud558\ub294\uac00\ub77c\ub294 \uc9c8\ubb38\uc774 \ub193\uc600\ub2e4. \uc0ac\ub78c\uc744 \ub3d5\ub294 \uc77c\uc744 \ub5a0\uc62c\ub9b4 \ub54c \ud070 \uac74\ubb3c\uc774\ub098 \ub9ce\uc740 \uc2dd\ub7c9\ubd80\ud130 \uc0dd\uac01\ud558\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \ub9e4\uc77c \ubab8\uc5d0 \ub2ff\uace0 \uc790\uc8fc \uc4f0\ub294 \uc791\uc740 \ubb3c\uac74\uc5d0\ub3c4 \ubd80\uc871\uc774 \uc0dd\uae38 \uc218 \uc788\ub2e4. \ub204\uad70\uac00\uc5d0\uac8c \ud754\ud55c \ubb3c\uac74\uc774\ub77c\ub294 \uc0ac\uc2e4\uc774 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c\ub3c4 \ucda9\ubd84\ud788 \uc788\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ubd04\ubc14\uc2a4 \ucc3d\uc5c5 \uc0ac\ub840\uc758 \ud765\ubbf8\ub85c\uc6b4 \uc810\uc740 \ud544\uc694\uc758 \uaddc\ubaa8\ub97c \ubb3c\uac74\uc758 \ud06c\uae30\ub85c \ud310\ub2e8\ud558\uc9c0 \uc54a\uc558\ub2e4\ub294 \ub370 \uc788\ub2e4. \ub2e4\ub9cc \ud2b9\uc815 \uad50\uc7ac\uac00 \uc18c\uac1c\ud55c \uad00\ucc30\uc744 \uc804 \uc138\uacc4 \ubaa8\ub4e0 \uc2dc\uc124\uc758 \ud604\uc7ac \uc6b0\uc120\uc21c\uc704\ub85c \ub113\ud790 \uc218\ub294 \uc5c6\ub2e4. \uc2e4\uc81c \uc9c0\uc6d0\uc5d0\uc11c\ub294 \uadf8 \uc9c0\uc5ed\uacfc \uae30\uad00\uc774 \uc694\uccad\ud558\ub294 \ub0b4\uc6a9\uc744 \ud655\uc778\ud558\ub294 \uc77c\uc774 \uba3c\uc800\ub2e4. \ub79c\ub514 \uace8\ub4dc\ubc84\uadf8\uc640 \ub370\uc774\ube44\ub4dc \ud788\uc2a4\ub294 2013\ub144 \ubd04\ubc14\uc2a4\ub97c \uc2dc\uc791\ud588\ub2e4. \uad50\uc7ac\ub294 \uc774\ub4e4\uc774 \uc591\ub9d0\uc744 \uac1c\uc120\ud55c \uc81c\ud488\uc73c\ub85c \uc81c\uc548\ud558\uba74\uc11c \ub3c4\uc6c0\uc774 \ud544\uc694\ud55c \uc0ac\ub78c\uc5d0\uac8c \uc591\ub9d0\uc744 \uc81c\uacf5\ud558\ub294 \uad6c\uc0c1\uc744 \ud568\uaed8 \ub9cc\ub4e4\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud310\ub9e4\uc640 \uc9c0\uc6d0\uc744 \uc11c\ub85c \ub2e4\ub978 \ub450 \ud65c\ub3d9\uc73c\ub85c\ub9cc \ub0a8\uaca8 \ub450\uc9c0 \uc54a\uc73c\ub824 \ud55c \uac83\uc774\ub2e4. \ubb3c\ub860 \ud68c\uc0ac\uac00 \uc591\ub9d0\uc744 \uc0c8\ub86d\uac8c \ub9cc\ub4e4\uc5c8\ub2e4\uace0 \ud45c\ud604\ud558\ub294 \uac83\uacfc \uadf8 \ud488\uc9c8\uc774 \ubaa8\ub4e0 \uacbd\uc7c1 \uc81c\ud488\ubcf4\ub2e4 \uc6b0\uc6d4\ud558\ub2e4\ub294 \ud3c9\uac00\ub294 \ub2e4\ub974\ub2e4. \uc774\ubc88 \uc774\uc57c\uae30\ub294 \uc81c\ud488\uc758 \ucc29\uc6a9 \uc2dc\ud5d8\uc774\ub098 \uad6c\ub9e4 \ucd94\ucc9c\uc774 \uc544\ub2c8\ub2e4. \ud3c9\ubc94\ud55c \uc18c\ube44\uc7ac\uc5d0 \uc5b4\ub5a4 \uc0ac\uc5c5\uc758 \uc57d\uc18d\uc744 \ubd99\uc600\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\ub294 \uc0ac\ub840\ub2e4. \ub2f9\uc2dc \ubd04\ubc14\uc2a4\uac00 \ub0b4\uc138\uc6b4 \ubc29\uc2dd\uc740 \uace0\uac1d\uc774 \uc591\ub9d0 \ud55c \ucf24\ub808\ub97c \uc0ac\uba74 \ud55c \ucf24\ub808\ub97c \ub3c4\uc6c0\uc774 \ud544\uc694\ud55c \uc0ac\ub78c\uc5d0\uac8c \uae30\ubd80\ud558\ub294 \uac83\uc774\uc5c8\ub2e4. \uace0\uac1d\uc740 \uc790\uc2e0\uc774 \uc4f8 \ubb3c\uac74\uc744 \uad6c\uc785\ud558\uba74\uc11c \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uc81c\uacf5\ud560 \ubb3c\uac74\uacfc\ub3c4 \uc5f0\uacb0\ub418\ub294 \uad6c\uc870\ub97c \ub9cc\ub0ac\ub2e4. \uc774 \uc57d\uc18d\uc774 \uc774\ud574\ud558\uae30 \uc26c\uc6b4 \uc774\uc720\ub294 \uacc4\uc0b0\uc758 \ub2e8\uc704\uac00 \uac19\uae30 \ub54c\ubb38\uc774\ub2e4. \ud55c \ucf24\ub808\uc640 \ud55c \ucf24\ub808\ub77c\ub294 \ub300\uc751\uc744 \uae08\ubc29 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc26c\uc6b4 \uc124\uba85\uacfc \uc2e4\uc81c \uc6b4\uc601\uc774 \ub2e8\uc21c\ud558\ub2e4\ub294 \ub9d0\uc740 \ub2e4\ub974\ub2e4. \uc5b4\ub514\uc5d0\uc11c \uc5b4\ub5a4 \ubb3c\uac74\uc744 \uc900\ube44\ud558\uace0 \uc5b4\ub5bb\uac8c \uc804\ub2ec\ud560\uc9c0\ub294 \ubcc4\ub3c4\uc758 \uc77c\uc744 \ud544\uc694\ub85c \ud55c\ub2e4. \ubb3c\uac74\uc744 \uc81c\uacf5\ud558\ub824\uba74 \ubc1b\ub294 \uacf3\uacfc\uc758 \uc5f0\uacb0\uc774 \uc788\uc5b4\uc57c \ud55c\ub2e4. \uc5b4\ub5a4 \uc218\ub7c9\uacfc \uc885\ub958\uac00 \ud544\uc694\ud55c\uc9c0 \ud655\uc778\ud558\uace0 \ubcf4\uad00\uacfc \uc804\ub2ec\uc758 \uc870\uac74\uc744 \ub9de\ucd94\uc5b4\uc57c \ud55c\ub2e4. \uc774\ub294 \ubd04\ubc14\uc2a4\uc758 \uac1c\ubcc4 \ubc30\uc1a1\uc744 \ucde8\uc7ac\ud55c \uae30\ub85d\uc774 \uc544\ub2c8\ub77c \ubb3c\ud488 \uc9c0\uc6d0\uc744 \uc77d\uc744 \ub54c \ud544\uc694\ud55c \uae30\ubcf8\uc801\uc778 \uc9c8\ubb38\uc774\ub2e4. \ud310\ub9e4\ud55c \uc218\ub7c9\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uc9c0\uc6d0\uc758 \uacb0\uacfc\uac00 \uc124\uba85\ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \ubb3c\uac74\uc774 \uc2e4\uc81c\ub85c \ud544\uc694\ud55c \uacf3\uc5d0 \ub3c4\ucc29\ud588\ub294\uc9c0, \uadf8\uacf3\uc5d0\uc11c \uc0ac\uc6a9\ud560 \uc218 \uc788\uc5c8\ub294\uc9c0\uac00 \uc911\uc694\ud558\ub2e4. \uae30\ubd80\ub77c\ub294 \ub9d0\uc758 \uc88b\uc740 \uc778\uc0c1 \ub4a4\ub97c \uc870\uae08 \ub354 \uc0b4\ud3b4\ubcf4\uba74 \ubb3c\ub958\uc640 \ud611\ub825, \uc9c0\uc18d\uc801\uc778 \ud655\uc778\uc758 \uc77c\uc774 \ub098\ud0c0\ub09c\ub2e4. \uae30\uc5c5\uc758 \uc0ac\ud68c\uc801 \ubaa9\ud45c\ub294 \uc5b4\ub5a4 \uace0\uac1d\uc5d0\uac8c \uad6c\ub9e4 \uc774\uc720\uac00 \ub420 \uc218 \uc788\ub2e4. \uc591\ub9d0\uc758 \uae30\ub2a5\uacfc \uac00\uaca9\uc744 \ub530\uc9c0\uba74\uc11c \uadf8 \ud68c\uc0ac\uac00 \ubb34\uc5c7\uc744 \ud558\ub824\ub294\uc9c0\ub3c4 \uc0b4\ud3b4\ubcf4\ub294 \uac83\uc774\ub2e4. \uc18c\ube44\uac00 \uac1c\uc778\uc758 \uc0ac\uc6a9 \uacbd\ud5d8 \ubc14\uae65\uc758 \ubb38\uc81c\uc640 \uc5f0\uacb0\ub418\ub294 \uc9c0\uc810\uc774\ub2e4. \uadf8\ub807\ub2e4\uace0 \uae30\ubd80 \uc57d\uc18d\uc774 \uc788\ub294 \uc0c1\ud488\uc744 \uc0ac\ub294 \uac83\ub9cc\uc774 \uc720\uc77c\ud558\uac8c \uc88b\uc740 \uc120\ud0dd\uc740 \uc544\ub2c8\ub2e4. \uc0ac\ub78c\ub9c8\ub2e4 \ud544\uc694\ud55c \ubb3c\uac74\uacfc \uc608\uc0b0, \ub2e4\ub978 \uc9c0\uc6d0 \ubc29\ubc95\uc774 \uc788\ub2e4. \uae30\uc5c5\uc758 \ud65c\ub3d9\uc744 \uc774\ud574\ud558\ub294 \uac83\uacfc \ub3c5\uc790\uc5d0\uac8c \ud2b9\uc815 \uad6c\ub9e4\ub97c \uad8c\ud558\ub294 \uc77c\uc740 \uad6c\ubd84\ud560 \uc218 \uc788\ub2e4. \uc774\uc57c\uae30\ub97c \uc548\ub2e4\uace0 \ubc18\ub4dc\uc2dc \uac19\uc740 \uc18c\ube44\ub97c \ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uad50\uc7ac\ub294 \ud68c\uc0ac\uac00 \ubc1d\ud78c \uc790\ub8cc\ub97c \ubc14\ud0d5\uc73c\ub85c 2017\ub144 10\uc6d4\uae4c\uc9c0 \uc591\ub9d0 400\ub9cc \ucf24\ub808 \uc774\uc0c1\uc744 \uae30\ubd80\ud588\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \ub2f9\uc2dc \uaddc\ubaa8\ub97c \uc774\ud574\ud558\ub294 \ub2e8\uc11c\uc774\uc9c0\ub9cc \ud604\uc7ac\uae4c\uc9c0\uc758 \uc2e4\uc801\uc774\ub098 \ub3c5\ub9bd\uc801\uc778 \ud6a8\uacfc \ud3c9\uac00\ub97c \ub73b\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud68c\uc0ac\uc758 \uc9d1\uacc4\ub77c\ub294 \ucd9c\ucc98\ub3c4 \ud568\uaed8 \uae30\uc5b5\ud574\uc57c \ud55c\ub2e4. \ub9ce\uc740 \uc218\ub7c9\uc744 \uc81c\uacf5\ud588\ub2e4\ub294 \uc8fc\uc7a5\uacfc \ubc1b\ub294 \uc0ac\ub78c\uc758 \uc0dd\ud65c\uc774 \uc5b4\ub5bb\uac8c \ub2ec\ub77c\uc84c\ub294\uc9c0\ub294 \uad00\ub828\ub418\uc9c0\ub9cc \uac19\uc740 \uc9c8\ubb38\uc740 \uc544\ub2c8\ub2e4. \uc804\uc790\ub294 \uc804\ub2ec\ud55c \ubb3c\uac74\uc758 \uc591\uc744, \ud6c4\uc790\ub294 \uc2e4\uc81c \uacbd\ud5d8\uacfc \ubcc0\ud654\ub97c \ubb3b\ub294\ub2e4. \uc22b\uc790\ub97c \uc874\uc911\ud558\uba74\uc11c\ub3c4 \uc22b\uc790\uac00 \ub2f5\ud558\uc9c0 \uc54a\uc740 \uc9c8\ubb38\uc744 \ub0a8\uaca8 \ub458 \uc218 \uc788\ub2e4. \uc774\ud574\uad00\uacc4\uc790\ub77c\ub294 \ub9d0\uc740 \uae30\uc5c5\uc758 \uacb0\uc815\uc5d0 \uc601\ud5a5\uc744 \ubc1b\ub294 \uc5ec\ub7ec \ub300\uc0c1\uc744 \uac00\ub9ac\ud0a8\ub2e4. \uace0\uac1d\uacfc \uc8fc\uc8fc\ubfd0 \uc544\ub2c8\ub77c \uc9c1\uc6d0\uacfc \uacf5\uae09\uc790, \uc9c0\uc5ed\uc0ac\ud68c\ub3c4 \ud3ec\ud568\ub41c\ub2e4. \ubd04\ubc14\uc2a4 \uc0ac\ub840\uc5d0\uc11c\ub294 \uc81c\ud488\uc744 \uad6c\ub9e4\ud558\uc9c0 \uc54a\ub294 \uc9c0\uc6d0 \ub300\uc0c1\ub3c4 \ud68c\uc0ac\uc758 \ud65c\ub3d9\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uc774\ub807\uac8c \ubcf4\uba74 \uae30\uc5c5\uc758 \ubaa9\uc801\uc744 \ub3c8\uc744 \ubc84\ub294\uac00 \uc544\ub2c8\uba74 \ub3d5\ub294\uac00\uc758 \uc591\uc790\ud0dd\uc77c\ub85c\ub9cc \uc815\ub9ac\ud558\uae30 \uc5b4\ub835\ub2e4. \ud310\ub9e4\uc640 \uc9c0\uc6d0\uc774 \ud568\uaed8 \ub3cc\uc544\uac00\ub3c4\ub85d \ub9cc\ub4e0 \uad6c\uc870\uc5d0\uc11c\ub294 \ub450 \ud65c\ub3d9\uc758 \uad00\uacc4\ub97c \uacc4\uc18d \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \ubaa9\ud45c\uac00 \uc88b\ub2e4\ub294 \uc120\uc5b8\uacfc \uadf8 \ubaa9\ud45c\ub97c \uafb8\uc900\ud788 \uc2e4\ud589\ud558\ub294 \uc6b4\uc601\uc740 \uc11c\ub85c\ub97c \ud544\uc694\ub85c \ud55c\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uc0ac\ub78c\ub4e4\uc774 \uc591\ub9d0\uc744 \uc815\ub9ac\ud558\ub294 \ubd84\uc704\uae30\ub97c \ud45c\ud604\ud588\ub2e4. \ubd04\ubc14\uc2a4\uc758 \uc2e4\uc81c \ubd09\uc0ac\uc790\ub098 \uc9c0\uc6d0 \uc2dc\uc124, \uae30\ubd80 \ud589\uc0ac\ub97c \ucd2c\uc601\ud55c \uc790\ub8cc\uac00 \uc544\ub2c8\ub2e4. \uc774 \uc6d0\uace0\ub3c4 \ucc3d\uc5c5 \ucd08\uae30\uc758 \uad50\uc7ac \uc0ac\ub840\ub97c \ub2e4\ub8e8\uba70 \ud604\uc7ac \uc0c1\ud488\uacfc \uae30\ubd80 \uc815\ucc45\uc744 \uc548\ub0b4\ud558\uc9c0 \uc54a\ub294\ub2e4. \ubd04\ubc14\uc2a4\uc758 \uc774\uc57c\uae30\ub97c \uc77d\uace0 \ub098\uba74 \uc11c\ub78d \uc18d \uc591\ub9d0\uc774 \uc870\uae08 \ub2e4\ub974\uac8c \ubcf4\uc77c \uc218 \uc788\ub2e4. \ubb3c\uac74\uc758 \ud3c9\ubc94\ud568\uacfc \uadf8 \ud544\uc694\uc758 \ud06c\uae30\ub294 \uac19\uc740 \uae30\uc900\uc774 \uc544\ub2c8\uae30 \ub54c\ubb38\uc774\ub2e4. \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub358 \ud544\uc694\ub97c \uc54c\uc544\ucc28\ub9ac\ub294 \uc77c\uc740 \ucee4\ub2e4\ub780 \ubc1c\uba85\ubcf4\ub2e4 \uc791\uc544 \ubcf4\uc77c\uc9c0 \ubab0\ub77c\ub3c4, \uc5b4\ub5a4 \uc0ac\uc5c5\uc744 \ub9cc\ub4e4\uc9c0 \uc815\ud558\ub294 \uc911\uc694\ud55c \ucd9c\ubc1c\uc810\uc774 \ub420 \uc218 \uc788\ub2e4."}, {"id": "boxed-bulk-shopping-without-car", "title": "\ubc15\uc2a4\ub4dc \u2014 \ucc28 \uc5c6\uc774\ub3c4 \ucc3d\uace0\ud615 \uc1fc\ud551\uc744 \ud560 \uc218 \uc788\uc744\uae4c", "summary": "2016\ub144 \ucc3d\uc5c5\uc790 \uc778\ud130\ubdf0\ub97c \uc778\uc6a9\ud55c \uad50\uc7ac \uc0ac\ub840\ub85c \ub300\uc6a9\ub7c9 \uc0c1\ud488\uacfc \ubaa8\ubc14\uc77c \uc8fc\ubb38, \ubc30\uc1a1\uc758 \uc5f0\uacb0\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "companies", "category_title": "Companies", "subcategory": "Technology", "url": "stories/boxed-bulk-shopping-without-car/index.html", "image": "media/boxed-bulk-shopping-without-car.png", "alt": "\ub3c4\uc2dc\uc758 \uc9d1 \uc55e\uc5d0\uc11c \ud070 \ubb36\uc74c\uc758 \uc0dd\ud65c\uc6a9\ud488\uc744 \ubc1b\ub294 \uc77c\ubc18\uc801\uc778 \ubc30\uc1a1 \uc7a5\uba74\uc758 \uc0bd\ud654.", "text": "\ubc15\uc2a4\ub4dc \u2014 \ucc28 \uc5c6\uc774\ub3c4 \ucc3d\uace0\ud615 \uc1fc\ud551\uc744 \ud560 \uc218 \uc788\uc744\uae4c \ub3c4\uc2dc \uc0dd\ud65c\uc758 \uc791\uc740 \ubd88\ud3b8\uc5d0\uc11c \uc2dc\uc791\ud55c 2010\ub144\ub300\uc758 \uc0ac\uc5c5 \uad6c\uc0c1 2016\ub144 \ucc3d\uc5c5\uc790 \uc778\ud130\ubdf0\ub97c \uc778\uc6a9\ud55c \uad50\uc7ac \uc0ac\ub840\ub85c \ub300\uc6a9\ub7c9 \uc0c1\ud488\uacfc \ubaa8\ubc14\uc77c \uc8fc\ubb38, \ubc30\uc1a1\uc758 \uc5f0\uacb0\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Technology \uae30\uc5c5 \ud070 \ubb36\uc74c\uc758 \ud734\uc9c0\ub098 \uc0dd\ud65c\uc6a9\ud488\uc740 \ub0b1\uac1c\ubcf4\ub2e4 \uc800\ub834\ud558\uac8c \ub290\uaef4\uc9c8 \ub54c\uac00 \uc788\ub2e4. \ubb38\uc81c\ub294 \uc0ac\ub294 \uc21c\uac04\ubcf4\ub2e4 \uc9d1\uae4c\uc9c0 \uac00\uc838\uc624\ub294 \uae38\uc774\ub2e4. \ucc28\uac00 \uc5c6\uace0 \ub9e4\uc7a5\uc774 \uba40\ub2e4\uba74 \uc88b\uc740 \uac00\uaca9 \uc55e\uc5d0\ub3c4 \ub2e4\ub978 \ube44\uc6a9\uc774 \uc0dd\uae34\ub2e4. \ubb3c\uac74\uc758 \uac12\uacfc \uadf8\uac83\uc744 \uc5bb\ub294 \ub370 \ub4dc\ub294 \uc218\uace0\ub294 \uac19\uc740 \ud56d\ubaa9\uc774 \uc544\ub2c8\ub2e4. \ubbf8\uad6d \uae30\uc5c5 \ubc15\uc2a4\ub4dc\uc758 \ucd08\uae30 \uad6c\uc0c1\uc740 \uc774\ub7f0 \ubd88\ud3b8\uc744 \uaca8\ub0e5\ud588\ub2e4. \uc5ec\uae30\uc11c\ub294 \uacbd\uc601 \uad50\uc7ac\uac00 2016\ub144 \ucc3d\uc5c5\uc790 \uc778\ud130\ubdf0 \ub4f1\uc744 \ubc14\ud0d5\uc73c\ub85c \uc18c\uac1c\ud55c \ub2f9\uc2dc\uc758 \uc0ac\ub840\ub97c \uc77d\ub294\ub2e4. \ud604\uc7ac\uc758 \uc11c\ube44\uc2a4\uc640 \uae30\uc5c5 \uc0c1\ud0dc\ub97c \uc548\ub0b4\ud558\uac70\ub098 \uc774\ud6c4\uc758 \uacbd\uc601 \uc131\uacfc\ub97c \ud3c9\uac00\ud558\ub294 \uae00\uc740 \uc544\ub2c8\ub2e4. \uad50\uc7ac\uc5d0 \ub530\ub974\uba74 \ucc3d\uc5c5\uc790 \uce58\uc5d0 \ud669\uc740 \uad50\uc678\uc5d0\uc11c \uc0b4 \ub54c \ucc3d\uace0\ud615 \ub9e4\uc7a5\uc744 \uc774\uc6a9\ud588\uc9c0\ub9cc \ub3c4\uc2dc\ub85c \uc62e\uaca8 \ucc28\uac00 \uc5c6\uc5b4\uc9c0\uc790 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uc7a5\uc744 \ubcf4\uae30 \uc5b4\ub824\uc6cc\uc84c\ub2e4. \uac00\uaca9\uc744 \uc544\ub294 \uac83\uacfc \uc2e4\uc81c\ub85c \uadf8 \uac00\uaca9\uc5d0 \ubb3c\uac74\uc744 \uc0b4 \uc218 \uc788\ub294 \uac83\uc740 \ub2ec\ub790\ub2e4. \uc0dd\ud65c \uc7a5\uc18c\uc758 \ubcc0\ud654\uac00 \uc0c8\ub85c\uc6b4 \ubb38\uc81c\ub97c \ub4dc\ub7ec\ub0b8 \uac83\uc774\ub2e4. \uc774 \uc7a5\uba74\uc5d0\ub294 \ud2b9\ubcc4\ud55c \ucca8\ub2e8 \uc81c\ud488\uc758 \ubc1c\uba85\uc774 \ub4f1\uc7a5\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc774\ubbf8 \uc788\ub358 \uc0c1\ud488\uacfc \ub9e4\uc7a5\uc774 \uc788\uc5c8\ub2e4. \ub2ec\ub77c\uc9c4 \uac83\uc740 \uc774\uc6a9\uc790\uc758 \uad50\ud1b5\uc218\ub2e8\uacfc \uc0dd\ud65c \ubc29\uc2dd\uc774\uc5c8\ub2e4. \uc775\uc219\ud55c \ubb3c\uac74\ub3c4 \uc5b4\ub5a4 \uc0ac\ub78c\uc5d0\uac8c \uc5b4\ub5a4 \uacbd\ub85c\ub85c \uc804\ub2ec\ub418\ub294\uc9c0\ub97c \ubc14\uafb8\uba74 \uc0ac\uc5c5\uc758 \uc9c8\ubb38\uc774 \uc0c8\ub85c \uc0dd\uae38 \uc218 \uc788\ub2e4. \ubc15\uc2a4\ub4dc\ub294 \ud734\uc9c0\uc640 \uc5d0\ub108\uc9c0\ubc14 \uac19\uc740 \ub300\uc6a9\ub7c9 \uc0c1\ud488\uc744 \uc571\uc73c\ub85c \uc8fc\ubb38\ud558\uace0 \uc9d1\uc73c\ub85c \ubc1b\ub294 \uad6c\uc0c1\uc744 \uc81c\uc2dc\ud588\ub2e4. \ud734\ub300\uc804\ud654 \ud654\uba74\uc5d0\uc11c\ub294 \uc190\uac00\ub77d\uc73c\ub85c \uace0\ub974\uc9c0\ub9cc \ud654\uba74 \ubc16\uc5d0\uc11c\ub294 \ud070 \ubd80\ud53c\uc758 \ubb3c\uac74\uc774 \uc774\ub3d9\ud574\uc57c \ud55c\ub2e4. \uc791\uc740 \uc8fc\ubb38 \uc7a5\uce58\uc640 \ud070 \ubb3c\ub958\uac00 \uc5f0\uacb0\ub418\ub294 \ubc29\uc2dd\uc774\ub2e4. \uace0\uac1d\uc5d0\uac8c \ud3b8\ub9ac\ud574\uc9c4 \uc77c\uc774 \uc0ac\ud68c \uc804\uccb4\uc5d0\uc11c \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uace0\uac1d\uc774 \ub9e4\uc7a5\uc5d0 \uac00\uc11c \ubb3c\uac74\uc744 \ub098\ub974\ub294 \uc218\uace0\uc758 \uc77c\ubd80\uac00 \uae30\uc5c5\uc758 \ubcf4\uad00\uacfc \ud3ec\uc7a5, \ubc30\uc1a1\uc73c\ub85c \uc62e\uaca8 \uac04\ub2e4. \uc628\ub77c\uc778 \uc0ac\uc5c5\uc744 \ud654\uba74\uc758 \uc774\uc57c\uae30\ub85c\ub9cc \ubcf4\uba74 \uc774 \uc774\ub3d9\uc774 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ud3b8\ub9ac\ud568 \ub4a4\uc5d0\ub294 \ub204\uad70\uac00\uc758 \uad6c\uccb4\uc801\uc778 \uc791\uc5c5\uc774 \uc788\ub2e4. \ubb3c\uac74\uc758 \ub2e8\uac00\uac00 \ub0ae\uc544\ub3c4 \ubaa8\ub4e0 \uc0ac\ub78c\uc5d0\uac8c \uac19\uc740 \uac00\uce58\uac00 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc9d1\uc5d0 \ub458 \uacf5\uac04\uacfc \ud544\uc694\ud55c \uc591, \uc8fc\ubb38 \uc870\uac74\uc744 \ud568\uaed8 \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4. \ud63c\uc790 \uc0ac\ub294 \uc0ac\ub78c\uc5d0\uac8c \ud070 \ubb36\uc74c\uc740 \ubcf4\uad00\uc758 \ubd80\ub2f4\uc77c \uc218\ub3c4 \uc788\ub2e4. \uc774\ubc88\uc5d0\ub294 \ud2b9\uc815 \uc0c1\ud488\uc758 \uc2e4\uc81c \uac00\uaca9\uc744 \ube44\uad50\ud558\ub294 \ub300\uc2e0 \uc120\ud0dd\uc5d0 \ub4e4\uc5b4\uac00\ub294 \uc870\uac74\uc744 \uc0b4\ud3b4\ubcf4\uc790. \ucc3d\uc5c5\uc790\uc758 \ubd88\ud3b8\uc774 \uc88b\uc740 \ucd9c\ubc1c\uc810\uc774 \ub420 \uc218\ub294 \uc788\uc9c0\ub9cc \uadf8\uac83\uc774 \ubaa8\ub4e0 \uace0\uac1d\uc758 \ud544\uc694\ub97c \ub300\ud45c\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub204\uad6c\uc5d0\uac8c \ubb38\uc81c\ub97c \ud480\uc5b4 \uc8fc\ub294\uc9c0 \ubc94\uc704\ub97c \uc815\ud574\uc57c \ud55c\ub2e4. \ub3c4\uc2dc\uc758 \ucc28 \uc5c6\ub294 \uc774\uc6a9\uc790\ub77c\ub294 \uad00\ucc30\uc774 \uc758\ubbf8 \uc788\uc5c8\ub358 \uc774\uc720\ub3c4 \ub9c9\uc5f0\ud788 \ubaa8\ub450\uc5d0\uac8c \uc88b\ub2e4\uace0 \ub9d0\ud558\uae30\ubcf4\ub2e4 \uad6c\uccb4\uc801\uc778 \uc0dd\ud65c \uc7a5\uba74\uc5d0\uc11c \uc2dc\uc791\ud588\uae30 \ub54c\ubb38\uc774\ub2e4. \uad50\uc7ac\ub294 \ucd08\uae30 \uc131\uc7a5 \uacfc\uc815\uc5d0\uc11c \uc790\uae08\uc744 \ub9c8\ub828\ud558\uace0 \ubb3c\ub958\uc13c\ud130\ub97c \uc138\uc6b0\uba70 \uc9c1\uc6d0\uc744 \ucc44\uc6a9\ud55c \uc77c\uc744 \uc18c\uac1c\ud55c\ub2e4. \uacf5\uae09\uc790\uc640\uc758 \uad00\uacc4\ub97c \ub113\ud788\uace0 \uc790\uccb4 \uc0c1\ud45c \uc0c1\ud488\ub3c4 \uac1c\ubc1c\ud588\ub2e4. \uc8fc\ubb38\uc744 \ubc1b\ub294 \uae30\ub2a5 \ub4a4\uc5d0 \ubb3c\uac74\uc744 \ud655\ubcf4\ud558\uace0 \uc6c0\uc9c1\uc77c \uc900\ube44\uac00 \ud544\uc694\ud588\ub358 \uac83\uc774\ub2e4. \uc8fc\ubb38\uc774 \ub298\uc5b4\ub098\ub294 \uac83\uacfc \uc8fc\ubb38\uc744 \uc81c\ub300\ub85c \ucc98\ub9ac\ud560 \uc218 \uc788\ub294 \ub2a5\ub825\uc774 \ub298\uc5b4\ub098\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \uc7ac\uace0\uc640 \uc791\uc5c5, \ubc30\uc1a1\uc758 \uc18d\ub3c4\ub97c \ub9de\ucd94\uc5b4\uc57c \ud55c\ub2e4. \ud2b9\ud788 \ud070 \ubb36\uc74c\uc758 \uc0dd\ud65c\uc6a9\ud488\uc740 \ud654\uba74\uc5d0\uc11c\ub294 \uac19\uc740 \ud06c\uae30\uc758 \uc0ac\uc9c4\uc774\uc5b4\ub3c4 \uc2e4\uc81c \uacf5\uac04\uc5d0\uc11c\ub294 \ubd80\ud53c\uac00 \ud06c\ub2e4. \ub514\uc9c0\ud138\uc758 \ud3b8\ub9ac\ud568\uc740 \ubb3c\ub9ac\uc801 \uc870\uac74\uacfc \ub530\ub85c \uc6c0\uc9c1\uc77c \uc218 \uc5c6\ub2e4. \uad50\uc7ac\uac00 \uc778\uc6a9\ud55c \ub2f9\uc2dc \ud669\uc758 \uc124\uba85\uc5d0\ub294 \uac00\uce58\uc640 \ud3b8\ub9ac\ud568, \ube0c\ub79c\ub4dc\uc758 \uc911\uc694\uc131\uc774 \ud568\uaed8 \ub098\uc628\ub2e4. \uacbd\uc7c1\uc790\ub4e4\ub3c4 \ube44\uc2b7\ud55c \uac00\uaca9\uacfc \ubc30\uc1a1\uc744 \uc81c\uacf5\ud558\uba74 \uace0\uac1d\uc740 \ub2e4\ub978 \uae30\uc900\uc73c\ub85c \ud68c\uc0ac\ub97c \uad6c\ubcc4\ud560 \uc218 \uc788\ub2e4. \ucc98\uc74c\uc758 \uc88b\uc740 \uc544\uc774\ub514\uc5b4\uac00 \uacc4\uc18d \ub3c5\uc810\uc801\uc778 \uc7a5\uc810\uc73c\ub85c \ub0a8\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774 \uc9c8\ubb38\uc740 \ubc15\uc2a4\ub4dc\uc5d0\ub9cc \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294\ub2e4. \ub530\ub77c \ud558\uae30 \uc26c\uc6b4 \uae30\ub2a5\uacfc \uc624\ub798 \uc313\uc544\uc57c \ud558\ub294 \uc2e0\ub8b0\ub294 \uc11c\ub85c \ub2e4\ub978 \uc790\uc0b0\uc774\ub2e4. \ud55c \ubc88\uc758 \uc8fc\ubb38\uc744 \uc5bb\ub294 \ubc29\ubc95\uacfc \ub2e4\uc2dc \uc120\ud0dd\ubc1b\ub294 \uc774\uc720\ub97c \ub098\ub204\uc5b4 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uac00\uaca9\ud45c\uac00 \ube44\uc2b7\ud574\uc9c4 \ub2e4\uc74c\uc5d0\ub3c4 \uace0\uac1d\uc758 \uacbd\ud5d8\uc740 \uac19\uc740 \ubaa8\uc591\uc77c \ud544\uc694\uac00 \uc5c6\ub2e4. \uad50\uc7ac\ub294 \ub2f9\uc2dc \ud669\uc774 \uc9c1\uc6d0 \uc790\ub140\uc758 \ub300\ud559 \uad50\uc721\uacfc \uacb0\ud63c \ube44\uc6a9\uc744 \uc9c0\uc6d0\ud55c \uc0ac\ub840\uac00 \ud68c\uc0ac \uc774\ubbf8\uc9c0\uc640 \uc5f0\uacb0\ub418\uc5c8\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \uc77c\ubd80 \uace0\uac1d\uc5d0\uac8c\ub294 \uae30\uc5c5\uc774 \uc0ac\ub78c\uc744 \ub300\ud558\ub294 \ubc29\uc2dd\ub3c4 \uc120\ud0dd \uae30\uc900\uc774 \ub420 \uc218 \uc788\ub2e4\ub294 \uc124\uba85\uc774\ub2e4. \uc0c1\ud488\uc758 \uac00\uce58\uc640 \uae30\uc5c5\uc774 \ub0b4\uc138\uc6b0\ub294 \uac00\uce58\uac00 \ub9cc\ub098\ub294 \uc9c0\uc810\uc774\ub2e4. \ub2e4\ub9cc \uacfc\uac70 \uc0ac\ub840\ub97c \ud604\uc7ac \ubaa8\ub4e0 \uc9c1\uc6d0\uc758 \ubcf5\uc9c0 \uaddc\uc815\uc73c\ub85c \uc77d\uc5b4\uc11c\ub294 \uc548 \ub41c\ub2e4. \uae30\uc5c5\uc5d0 \uad00\ud55c \uc88b\uc740 \uc774\uc57c\uae30 \ud55c \uac00\uc9c0\uac00 \uc7ac\ubb34\uc640 \uc6b4\uc601 \uc804\uccb4\ub97c \ud3c9\uac00\ud574 \uc8fc\ub294 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \uc2dc\uae30\uc758 \uc5b4\ub5a4 \ud589\ub3d9\uc744 \uadfc\uac70\ub85c \ud558\ub294\uc9c0 \ub098\ub204\uc5b4 \ubcf4\uba74 \ud638\uac10\uacfc \ud655\uc778\uc744 \ud568\uaed8 \uc720\uc9c0\ud560 \uc218 \uc788\ub2e4. \uacbd\uc601 \uad50\uc7ac\ub294 \uae30\uc5c5\uc758 \ud55c \uc7a5\uba74\uc744 \uace8\ub77c \ud2b9\uc815 \uc6d0\ub9ac\ub97c \uc124\uba85\ud55c\ub2e4. \uadf8 \uae30\uc5c5\uc758 \uc774\ud6c4 \uc5ed\uc0ac\ub97c \uc804\ubd80 \ub530\ub77c\uac00\ub294 \uc790\ub8cc\ub294 \uc544\ub2d0 \uc218 \uc788\ub2e4. \ubc15\uc2a4\ub4dc\uc758 \uc774 \uc0ac\ub840\ub3c4 \ubaa8\ubc14\uc77c \uc8fc\ubb38\uacfc \ub300\uc6a9\ub7c9 \ubc30\uc1a1\uc744 \uc5f0\uacb0\ud55c \ucd08\uae30 \uc804\ub7b5\uc744 \uc774\ud574\ud558\ub294 \ub370 \ucd08\uc810\uc744 \ub450\uc5b4\uc57c \ud55c\ub2e4. \ub530\ub77c\uc11c \uacfc\uac70\uc5d0 \uad00\uc2ec\uc744 \ubaa8\uc558\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ud604\uc7ac\uae4c\uc9c0 \uac19\uc740 \uc131\uacfc\uac00 \uc774\uc5b4\uc84c\ub2e4\ub294 \ub9d0\ub85c \ubc14\uafb8\uc9c0 \uc54a\ub294\ub2e4. \uc88b\uc740 \ubb38\uc81c\ub97c \ucc3e\ub294 \uc77c\uacfc \uc7a5\uae30\uac04 \uc0ac\uc5c5\uc744 \uc720\uc9c0\ud558\ub294 \uc77c\uc5d0\ub294 \ub2e4\ub978 \uc870\uac74\ub3c4 \ud544\uc694\ud558\ub2e4. \uc0ac\ub840\uac00 \ubcf4\uc5ec \uc8fc\ub294 \ud1b5\ucc30\uc744 \uc77d\uc73c\uba74\uc11c \ub3d9\uc2dc\uc5d0 \uc790\ub8cc\uac00 \ub2e4\ub8e8\ub294 \uc2dc\uac04\uc758 \ub05d\uc744 \uc54c\uc544 \ub450\ub294 \ud3b8\uc774 \uc815\ud655\ud558\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \ub3c4\uc2dc\uc758 \uc9d1 \uc55e\uc5d0 \uc0dd\ud65c\uc6a9\ud488\uc774 \ub3c4\ucc29\ud558\ub294 \uc77c\ubc18\uc801\uc778 \uc7a5\uba74\uc774\ub2e4. \uc2e4\uc81c \ubc15\uc2a4\ub4dc\uc758 \ud3ec\uc7a5\uacfc \ubc30\uc1a1 \ubc29\uc2dd, \uc9c1\uc6d0\uc774\ub098 \uace0\uac1d\uc744 \uc7ac\ud604\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uc0c1\ud488\uc774 \uc9d1\uae4c\uc9c0 \uc774\ub3d9\ud55c\ub2e4\ub294 \uad6c\uc0c1\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc704\ud55c \uadf8\ub9bc\uc774\ub2e4. \uc774 \ucd08\uae30 \uc0ac\ub840\ub294 \uc0c8\ub85c\uc6b4 \uc0ac\uc5c5\uc774 \uaf2d \uc0c8\ub85c\uc6b4 \ubb3c\uac74\uc5d0\uc11c \uc2dc\uc791\ud558\ub294 \uac83\uc740 \uc544\ub2d8\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc774\ubbf8 \uc788\ub294 \ubb3c\uac74\uc744 \uc5b4\ub5a4 \uc0dd\ud65c \uc870\uac74\uc758 \uc0ac\ub78c\uc5d0\uac8c \uc5b4\ub5bb\uac8c \uc804\ub2ec\ud560\uc9c0\ub3c4 \uc9c8\ubb38\uc774 \ub41c\ub2e4. \ucc3d\uace0\ud615 \uc1fc\ud551\uc758 \ud070 \ubb36\uc74c\uacfc \ucc28 \uc5c6\ub294 \ub3c4\uc2dc\uc778\uc758 \uc791\uc740 \uc9d1 \uc0ac\uc774\uc5d0\ub294 \uac00\uaca9\ud45c\ub9cc\uc73c\ub85c \ubcf4\uc774\uc9c0 \uc54a\ub294 \uae38\uc774 \uc788\uc5c8\ub2e4."}, {"id": "dell-order-before-computer", "title": "\ub378 \u2014 \uc8fc\ubb38\uc744 \uba3c\uc800 \ub4e3\uace0 \ucef4\ud4e8\ud130\ub97c \ub9cc\ub4e4\uba74", "summary": "\ub378\uc758 \ub9de\ucda4\ud615 \ucef4\ud4e8\ud130 \uc0ac\ub840\ub85c \uace0\uac1d\uc758 \uc120\ud0dd\uacfc \uc2e4\uc81c \uc0dd\uc0b0\uc774 \uc5f0\uacb0\ub418\ub294 \ubc29\uc2dd\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "companies", "category_title": "Companies", "subcategory": "Technology", "url": "stories/dell-order-before-computer/index.html", "image": "media/dell-order-before-computer.png", "alt": "\uc791\uc5c5\ub300 \uc704 \ucef4\ud4e8\ud130 \ubd80\ud488\uc744 \ubcf4\uba70 \uad6c\uc131\uc5d0 \uad00\ud574 \uc774\uc57c\uae30\ud558\ub294 \ub450 \uc0ac\ub78c\uc758 \uc0bd\ud654.", "text": "\ub378 \u2014 \uc8fc\ubb38\uc744 \uba3c\uc800 \ub4e3\uace0 \ucef4\ud4e8\ud130\ub97c \ub9cc\ub4e4\uba74 \uc120\ud0dd\ub780 \ub4a4\uc5d0\uc11c \uc774\uc5b4\uc9c0\ub294 \ubd80\ud488\uacfc \uacf5\uae09\uc758 \uc774\uc57c\uae30 \ub378\uc758 \ub9de\ucda4\ud615 \ucef4\ud4e8\ud130 \uc0ac\ub840\ub85c \uace0\uac1d\uc758 \uc120\ud0dd\uacfc \uc2e4\uc81c \uc0dd\uc0b0\uc774 \uc5f0\uacb0\ub418\ub294 \ubc29\uc2dd\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Technology \uae30\uc5c5 \ucef4\ud4e8\ud130\ub97c \uace0\ub97c \ub54c \uba54\ubaa8\ub9ac\ub97c \uc5bc\ub9c8\ub098 \ub123\uc744\uc9c0, \uc800\uc7a5 \uacf5\uac04\uc740 \uc5b4\ub290 \uc815\ub3c4\ub85c \ud560\uc9c0 \uc120\ud0dd\ud558\ub294 \ud654\uba74\uc744 \ub9cc\ub09c\ub2e4. \ud074\ub9ad\uc740 \uac04\ub2e8\ud558\ub2e4. \uadf8\ub7ec\ub098 \uc120\ud0dd\uc774 \ub2ec\ub77c\uc9c0\uba74 \uc548\uc5d0 \ub4e4\uc5b4\uac08 \ubd80\ud488\ub3c4 \ub2ec\ub77c\uc838\uc57c \ud55c\ub2e4. \uc8fc\ubb38\uc758 \ub9d0\uc774 \uc2e4\uc81c \ubb3c\uac74\uc73c\ub85c \ubc14\ub00c\ub294 \uacfc\uc815\uc774 \uc788\ub294 \uac83\uc774\ub2e4. \ub378\uc758 \uc0ac\uc5c5 \uc774\uc57c\uae30\ub294 \uc774\ub7f0 \uc5f0\uacb0\uc5d0\uc11c \ucd9c\ubc1c\ud55c\ub2e4. \ub9c8\uc774\ud074 \ub378\uc758 \ucd08\uae30 \uc0ac\ub840\ub294 \uace0\uac1d\uc5d0\uac8c \ub9de\ucd98 \ucef4\ud4e8\ud130\ub97c \ub9cc\ub4e4\uace0 \uc9c1\uc811 \uc804\ub2ec\ud558\ub294 \ubc29\uc2dd\uc73c\ub85c \uacbd\uc601 \uad50\uc7ac\uc5d0 \uc18c\uac1c\ub41c\ub2e4. \ub354 \uc0c8\ub85c\uc6b4 \ubd80\ud488\uc744 \ubc1c\uba85\ud558\ub294 \uac83\uacfc \uc774\ubbf8 \uc788\ub294 \ubd80\ud488\uc744 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \uc870\ud569\ud574 \ud310\ub9e4\ud558\ub294 \uac83\uc740 \ub2e4\ub978 \uc885\ub958\uc758 \ud601\uc2e0\uc774\ub2e4. \uad50\uc7ac\ub294 \ud14d\uc0ac\uc2a4\ub300\ud559\uad50 \ud559\uc0dd\uc774\ub358 \ub9c8\uc774\ud074 \ub378\uc774 \ubd80\ud488\uc744 \uc0ac\uc11c \uc6d0\ud558\ub294 \ucef4\ud4e8\ud130\ub97c \uc9c1\uc811 \uc870\ub9bd\ud588\uace0, \uce5c\uad6c\ub4e4\uc774 \uc790\uc2e0\ub4e4\uc758 \uac83\ub3c4 \ub9cc\ub4e4\uc5b4 \ub2ec\ub77c\uace0 \ud588\ub358 \uc77c\ud654\ub97c \uc18c\uac1c\ud55c\ub2e4. \uc790\uc2e0\uc758 \ud544\uc694\ub97c \ud574\uacb0\ud558\ub358 \ud65c\ub3d9\uc774 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc694\uccad\uacfc \ub9cc\ub09c \uac83\uc774\ub2e4. \uc774 \uc124\uba85\uc744 \ubaa8\ub4e0 \uc131\uacf5\uc744 \uc608\uace0\ud55c \uc644\ubcbd\ud55c \uc0ac\uc5c5 \uacc4\ud68d\uc73c\ub85c \uc77d\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \ucd9c\ubc1c\uc810\uc5d0\uc11c \uc911\uc694\ud588\ub358 \uac83\uc740 \uc0ac\ub78c\ub9c8\ub2e4 \uc6d0\ud558\ub294 \uad6c\uc131\uc774 \ub2e4\ub97c \uc218 \uc788\ub2e4\ub294 \uad00\ucc30\uc774\uc5c8\ub2e4. \uc644\uc131\ud488\uc744 \uace0\ub974\ub294 \uace0\uac1d\ub9cc \uc788\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc6d0\ud558\ub294 \ubd80\ud488\uc758 \uc870\ud569\uc744 \ub9d0\ud558\ub294 \uace0\uac1d\ub3c4 \uc788\uc5c8\ub2e4. \uc5b4\ub5a4 \uc0ac\ub78c\uc740 \uc5ec\ub7ec \ud504\ub85c\uadf8\ub7a8\uc744 \ub3d9\uc2dc\uc5d0 \uc4f0\ub824 \ud558\uace0 \ub2e4\ub978 \uc0ac\ub78c\uc740 \uc790\ub8cc\ub97c \ub9ce\uc774 \ubcf4\uad00\ud558\ub824 \ud55c\ub2e4. \uc774\ub7f0 \uac00\uc0c1 \uc608\ub97c \ub5a0\uc62c\ub9ac\uba74 \uba54\ubaa8\ub9ac\uc640 \uc800\uc7a5 \uc7a5\uce58\uc758 \uc120\ud0dd\uc774 \uc65c \ub2ec\ub77c\uc9c0\ub294\uc9c0 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \ubaa8\ub450\uc5d0\uac8c \uac00\uc7a5 \uc88b\uc740 \ud55c \uac00\uc9c0 \uc0ac\uc591\uc744 \uc815\ud558\uae30\ub294 \uc5b4\ub835\ub2e4. \ub9de\ucda4\ud615 \ud310\ub9e4\ub294 \uace0\uac1d\uc758 \ucc28\uc774\ub97c \uc81c\ud488 \uad6c\uc131\uc5d0 \ubc18\uc601\ud558\ub824\ub294 \ubc29\uc2dd\uc774\ub2e4. \ud558\uc9c0\ub9cc \uace0\uac1d\uc774 \ub9d0\ud558\ub294 \ubaa8\ub4e0 \uc870\ud569\uc744 \ubb34\ud55c\ud788 \ub9cc\ub4e4\uc5b4 \uc8fc\ub294 \uac83\uacfc\ub294 \ub2e4\ub974\ub2e4. \uc2e4\uc81c\ub85c \uc0dd\uc0b0\ud558\uace0 \uc81c\uacf5\ud560 \uc218 \uc788\ub294 \uc120\ud0dd\uc758 \ubc94\uc704\ub97c \uba3c\uc800 \uc900\ube44\ud574\uc57c \ud55c\ub2e4. \uc120\ud0dd\ub780\uc758 \uc218\uc5d0\ub3c4 \uc6b4\uc601\uc758 \uc870\uac74\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \uc81c\uc870 \ucabd\uc774 \uace0\uac1d\uc758 \uc8fc\ubb38\uc744 \uc9c1\uc811 \ubc1b\uc73c\uba74 \uc5b4\ub5a4 \uad6c\uc131\uc744 \uc6d0\ud558\ub294\uc9c0 \ub354 \uac00\uae4c\uc774\uc5d0\uc11c \ud30c\uc545\ud560 \uc218 \uc788\ub2e4. \uc5ec\ub7ec \uc720\ud1b5 \ub2e8\uacc4\ub97c \uac70\uce58\uba70 \uc644\uc131\ud488\uc744 \ubcf4\ub0b4\ub294 \ubc29\uc2dd\uacfc \ub2e4\ub978 \uc815\ubcf4\uc758 \ud750\ub984\uc774 \uc0dd\uae34\ub2e4. \uace0\uac1d\uc758 \uc120\ud0dd\uc774 \uc0dd\uc0b0\ud560 \ubb3c\uac74\uc744 \uc815\ud558\ub294 \ub370 \uad00\uc5ec\ud558\ub294 \uac83\uc774\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc911\uac04 \uc720\ud1b5\uc744 \uc904\uc600\uc73c\ub2c8 \ud544\uc694\ud55c \uc77c\ub3c4 \ubaa8\ub450 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc8fc\ubb38\uc744 \uc774\ud574\ud558\uace0 \uc81c\ud488\uc744 \uc548\ub0b4\ud558\uba70 \uc804\ub2ec\ud558\ub294 \uc77c\uc744 \ub204\uad70\uac00\ub294 \ud574\uc57c \ud55c\ub2e4. \uae30\uc874\uc758 \uc77c\uc744 \uc5c6\uc560\ub294 \ubd80\ubd84\uacfc \uae30\uc5c5 \uc548\uc73c\ub85c \uac00\uc838\uc624\ub294 \ubd80\ubd84\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \ud310\ub9e4 \ubc29\uc2dd\uc758 \ubcc0\ud654\ub97c \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uad50\uc7ac\ub294 \ub378\uc744 \uace0\uac1d \uc0ac\uc591\uc5d0 \ub9de\ucd94\uc5b4 \ucef4\ud4e8\ud130\ub97c \ub9cc\ub4dc\ub294 \uc0ac\ub840\ub85c \uc124\uba85\ud55c\ub2e4. \uc774\ub97c \uac00\ub2a5\ud558\uac8c \ud558\ub824\uba74 \uba54\ubaa8\ub9ac\uc640 \uc800\uc7a5 \uc7a5\uce58 \ub4f1 \ud544\uc694\ud55c \ubd80\ud488\uc744 \ub9c8\ub828\ud558\uace0 \uc870\ub9bd\uc758 \ud750\ub984\uc744 \ub9de\ucd94\uc5b4\uc57c \ud55c\ub2e4. \uc8fc\ubb38 \ud654\uba74\uacfc \uc0dd\uc0b0 \ud604\uc7a5\uc758 \uc815\ubcf4\uac00 \ub5a8\uc5b4\uc838 \uc788\uc73c\uba74 \uc120\ud0dd\uc740 \uc57d\uc18d\uc5d0\ub9cc \uba38\ubb34\ub97c \uc218 \uc788\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \ud2b9\uc815 \ubd80\ud488\uc744 \ub9ce\uc774 \uc6d0\ud558\ub294 \uc2dc\uae30\uc5d0\ub294 \uacf5\uae09\uacfc \uc791\uc5c5\uc758 \uade0\ud615\ub3c4 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc774\uac83\uc740 \uc2e4\uc81c \uc5b4\ub290 \ub0a0\uc758 \ub378 \uacf5\uc7a5 \uc0c1\ud669\uc744 \uc7ac\ud604\ud55c \uac83\uc774 \uc544\ub2c8\ub77c \uc6d0\ub9ac\ub97c \uc0dd\uac01\ud558\ub294 \uc608\ub2e4. \uace0\uac1d\uc758 \uc120\ud0dd\uad8c\uc740 \uadf8 \ub4a4\uc5d0\uc11c \uc5ec\ub7ec \uc900\ube44\uac00 \ud568\uaed8 \uc6c0\uc9c1\uc77c \ub54c \uc2e4\uc81c \uacbd\ud5d8\uc774 \ub41c\ub2e4. \uc81c\ud488\uc758 \uc774\ub984\uc740 \ub378\uc774\uc9c0\ub9cc \uc81c\uc870\uc640 \ubd80\ud488\uc758 \uc5f0\uacb0\uc5d0\ub294 \ub2e4\ub978 \uae30\uc5c5\ub4e4\ub3c4 \ucc38\uc5ec\ud55c\ub2e4. \uad50\uc7ac\ub294 \uacc4\uc57d \uc81c\uc870\uc5c5\uccb4\uc640\uc758 \ud611\ub825\uc744 \uc124\uba85\ud55c\ub2e4. \ud558\ub098\uc758 \uc0c1\ud45c\uac00 \ubd99\uc740 \ubb3c\uac74\uc774 \ud55c \ud68c\uc0ac \uc548\uc758 \ubaa8\ub4e0 \uacfc\uc815\ub9cc\uc73c\ub85c \uc644\uc131\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc81c\ud488\uc744 \ub9cc\ub4dc\ub294 \uc77c\uc744 \uc870\ub9bd\ub300 \uc704\uc758 \uc791\uc5c5\uc73c\ub85c\ub9cc \ubcfc \uc218 \uc5c6\ub2e4. \uc5b4\ub5a4 \uae30\uc900\uc744 \uacf5\uae09\uc790\uc640 \uacf5\uc720\ud558\uace0 \ubd80\ud488\uc774 \uc5b8\uc81c \ub4e4\uc5b4\uc624\uba70 \ub9c8\uc9c0\ub9c9 \ud655\uc778\uacfc \ubc30\uc1a1\uc744 \uc5b4\ub5bb\uac8c \uc774\uc5b4 \uac08\uc9c0\ub3c4 \uc911\uc694\ud558\ub2e4. \ub9de\ucda4\ud615 \ud310\ub9e4\ub294 \uac1c\uc778\uc758 \uc120\ud0dd\uc744 \uac15\uc870\ud558\uc9c0\ub9cc \uc2e4\ud589\uc740 \uc624\ud788\ub824 \ub9ce\uc740 \uc870\uc9c1\uc758 \ud611\ub825\uc744 \ud544\uc694\ub85c \ud55c\ub2e4. \ub0b4\uac8c \ub9de\ub294 \ucef4\ud4e8\ud130\ub97c \uace0\ub97c \uc218 \uc788\ub2e4\ub294 \uc124\uba85\uc740 \ub9e4\ub825\uc801\uc774\ub2e4. \ud558\uc9c0\ub9cc \ubb34\uc5c7\uc744 \uace0\ub974\uba74 \uc88b\uc740\uc9c0 \ubaa8\ub974\ub294 \uace0\uac1d\uc5d0\uac8c\ub294 \uc120\ud0dd\uc774 \ub9ce\uc544\uc9c0\ub294 \uac83 \uc790\uccb4\uac00 \ubd80\ub2f4\uc77c \uc218 \uc788\ub2e4. \uc81c\ud488\uc758 \ucc28\uc774\ub97c \uc54c\uc544\ubcf4\uae30 \uc27d\uac8c \uc548\ub0b4\ud558\ub294 \uc77c\ub3c4 \uc0ac\uc5c5\uc758 \uc77c\ubd80\uac00 \ub41c\ub2e4. \uc774\uac83\uc740 \ub378\uc758 \ud604\uc7ac \uc8fc\ubb38 \ud654\uba74\uc744 \ud3c9\uac00\ud55c \ub0b4\uc6a9\uc740 \uc544\ub2c8\ub2e4. \ub9de\ucda4\ud615 \uc81c\ud488\uc744 \uc77d\uc744 \ub54c \ub367\ubd99\uc77c \uc218 \uc788\ub294 \uc9c8\ubb38\uc774\ub2e4. \uace0\uac1d\uc774 \ucc28\uc774\ub97c \uc774\ud574\ud558\uace0 \uc120\ud0dd\uc758 \uacb0\uacfc\ub97c \uc608\uc0c1\ud560 \uc218 \uc788\uc5b4\uc57c \uc120\ud0dd\uad8c\uc774 \ud3b8\ub9ac\ud568\uc774 \ub41c\ub2e4. \ub9ce\uc740 \ud56d\ubaa9\uacfc \uc88b\uc740 \uc548\ub0b4\ub294 \uac19\uc740 \ub73b\uc774 \uc544\ub2c8\ub2e4. \uad50\uc7ac\uac00 \uc18c\uac1c\ud55c \uc0ac\ub840\ub97c \ub378\uc758 \ubaa8\ub4e0 \uc2dc\ub300\uc640 \ubaa8\ub4e0 \ud310\ub9e4 \uacbd\ub85c\uc5d0 \uc801\uc6a9\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc774\ubc88 \uae00\uc740 \ub9de\ucda4\ud615 \uc870\ub9bd\uacfc \uc9c1\uc811 \ud310\ub9e4\ub77c\ub294 \uad6c\uc0c1\uc774 \uac16\ub294 \uc758\ubbf8\uc5d0 \ucd08\uc810\uc744 \ub9de\ucd98\ub2e4. \ud604\uc7ac \ubaa8\ub378\uc758 \uc0ac\uc591\uacfc \ub0a9\uae30, \uc81c\uc870 \uad6d\uac00\ub97c \uc548\ub0b4\ud558\ub294 \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \ub610 \uc774\ub7f0 \ubc29\uc2dd\uc774 \ubaa8\ub4e0 \uc81c\ud488\uc5d0 \ucd5c\uc120\uc774\ub77c\ub294 \uacb0\ub860\ub3c4 \ud544\uc694\ud558\uc9c0 \uc54a\ub2e4. \uace0\uac1d\uc774 \uad6c\uc131\uc744 \ubc14\uafc0 \uc774\uc720\uac00 \uc801\uac70\ub098 \ube60\ub978 \uc644\uc131\ud488 \uad6c\ub9e4\ub97c \uc6d0\ud55c\ub2e4\uba74 \ub2e4\ub978 \ubc29\uc2dd\uc774 \ub9de\uc744 \uc218 \uc788\ub2e4. \ud601\uc2e0\uc740 \uc5b8\uc81c\ub098 \uac19\uc740 \uacf5\uc2dd\uc774 \uc544\ub2c8\ub77c \uc81c\ud488\uacfc \uace0\uac1d\uc758 \uc870\uac74\uc5d0 \ub9de\ucd94\uc5b4 \ud310\ub2e8\ud560 \ubb38\uc81c\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \ubd80\ud488\uc744 \ubcf4\uba70 \uad6c\uc131\uc744 \uc758\ub17c\ud558\ub294 \uc791\uc5c5\ub300\uc758 \ubd84\uc704\uae30\ub2e4. \ub9c8\uc774\ud074 \ub378\uc758 \uc2e4\uc81c \uae30\uc219\uc0ac\uc640 \uc778\ubb3c, \ud2b9\uc815 \uc81c\ud488\uc774\ub098 \uacf5\uc7a5\uc744 \ubcf5\uc6d0\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uc120\ud0dd\uacfc \uc870\ub9bd\uc774 \ub9cc\ub098\ub294 \uc7a5\uba74\uc744 \ub5a0\uc62c\ub9ac\ub294 \uadf8\ub9bc\uc774\ub2e4. \ub378\uc758 \uc0ac\ub840\ub294 \uae30\uc220 \uae30\uc5c5\uc758 \ubcc0\ud654\uac00 \uc0c8\ub85c\uc6b4 \uce69\uc744 \ub9cc\ub4dc\ub294 \ub370\uc11c\ub9cc \uc2dc\uc791\ud558\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc810\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uace0\uac1d\uc774 \uc6d0\ud558\ub294 \uac83\uc744 \ub4e3\uace0 \ubd80\ud488\uacfc \uc0dd\uc0b0\uc744 \uc5f0\uacb0\ud558\ub294 \ubc29\uc2dd\ub3c4 \ubc14\uafc0 \uc218 \uc788\uc5c8\ub2e4. \uc791\uc740 \uc120\ud0dd\ub780\uc744 \ub204\ub974\ub294 \uc21c\uac04 \ub4a4\uc5d0\uc11c \uc5b4\ub5a4 \uc900\ube44\uac00 \uc6c0\uc9c1\uc774\ub294\uc9c0 \uc0dd\uac01\ud558\uba74 \uc775\uc219\ud55c \ucef4\ud4e8\ud130 \uad6c\ub9e4\ub3c4 \ub2e4\ub978 \uc774\uc57c\uae30\ub85c \ubcf4\uc778\ub2e4."}, {"id": "ford-moving-assembly", "title": "\ud3ec\ub4dc\uc758 \uc870\ub9bd\ub77c\uc778 \u2014 \uc0ac\ub78c\uc774 \ucc28\ub97c \ucc3e\uc544\ub2e4\ub2c8\uc9c0 \uc54a\uac8c \ub418\uc790", "summary": "\uc77c\ud558\ub294 \uc790\ub9ac\uc640 \ubd80\ud488\uc758 \uc774\ub3d9\uc744 \ubc14\uafbc \uacf5\uc7a5 \uc2e4\ud5d8\uc5d0\uc11c \uc0dd\uc0b0\uc131\uacfc \ub178\ub3d9\uc758 \ub450 \uc5bc\uad74\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "companies", "category_title": "Companies", "subcategory": "Automotive", "url": "stories/ford-moving-assembly/index.html", "image": "media/ford-moving-assembly.png", "alt": "20\uc138\uae30 \ucd08 \uc790\ub3d9\ucc28 \uacf5\uc7a5\uc5d0\uc11c \uc791\uc5c5\uc790\ub4e4\uc774 \uc774\ub3d9\ud558\ub294 \uc100\uc2dc\uc758 \uc5ec\ub7ec \ubd80\ubd84\uc744 \uc870\ub9bd\ud558\ub294 \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\ud3ec\ub4dc\uc758 \uc870\ub9bd\ub77c\uc778 \u2014 \uc0ac\ub78c\uc774 \ucc28\ub97c \ucc3e\uc544\ub2e4\ub2c8\uc9c0 \uc54a\uac8c \ub418\uc790 \uc790\ub3d9\ucc28\ub97c \ubc14\uafbc \uac83\uc740 \uc5d4\uc9c4\ub9cc\uc774 \uc544\ub2c8\uc5c8\ub2e4 \uc77c\ud558\ub294 \uc790\ub9ac\uc640 \ubd80\ud488\uc758 \uc774\ub3d9\uc744 \ubc14\uafbc \uacf5\uc7a5 \uc2e4\ud5d8\uc5d0\uc11c \uc0dd\uc0b0\uc131\uacfc \ub178\ub3d9\uc758 \ub450 \uc5bc\uad74\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Automotive \uae30\uc5c5 \uc790\ub3d9\ucc28 \ud55c \ub300\ub97c \ub9cc\ub4e4\ub824\uba74 \uc0ac\ub78c\uc774 \ucc28 \uc8fc\uc704\ub97c \uba87 \ubc14\ud034\ub098 \ub3cc\uc544\uc57c \ud560\uae4c. \uacf5\uad6c\ub97c \ucc3e\uace0, \ubb34\uac70\uc6b4 \ubd80\ud488\uc744 \uc62e\uae30\uace0, \ub2e4\uc74c \uc791\uc5c5\uc744 \uae30\ub2e4\ub9b0\ub2e4. \uc644\uc131\ub41c \uc790\ub3d9\ucc28\uc5d0\ub294 \ubcf4\uc774\uc9c0 \uc54a\uc9c0\ub9cc \uacf5\uc7a5\uc758 \ud558\ub8e8\uc5d0\ub294 \uc774\ub7f0 \uc2dc\uac04\uc774 \uac00\ub4dd\ud558\ub2e4. \ud3ec\ub4dc\uc758 \uc870\ub9bd\ub77c\uc778 \uc774\uc57c\uae30\ub294 \ub354 \ud798\uc13c \uc5d4\uc9c4\ubcf4\ub2e4 \uc774 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc6c0\uc9c1\uc784\uc5d0\uc11c \uc2dc\uc791\ud55c\ub2e4. \ud5e8\ub9ac \ud3ec\ub4dc\uac00 \uc0c8\ubba4\uc5bc \ud06c\ub77c\uc6b0\ub354\uc640 \ud568\uaed8 \uc4f4 \ud68c\uace0\ub85d \u300a\ub098\uc758 \uc0b6\uacfc \uc77c\u300b\uc5d0\ub294 \uacf5\uc7a5 \ubc30\uce58\ub97c \uc870\uae08\uc529 \ubc14\uafb8\ub358 \uacfc\uc815\uc774 \ub098\uc628\ub2e4. \uacbd\uc601\uc790\uac00 \uc790\uc2e0\uc758 \uc131\uacfc\ub97c \uc124\uba85\ud55c \ucc45\uc774\ub77c\ub294 \uc810\uc744 \uae30\uc5b5\ud558\uba70 \uc77d\uc73c\uba74, \uc720\uba85\ud55c \ubc1c\uba85\ub2f4 \ub4a4\uc758 \uc2e4\ud5d8\uacfc \uadf8 \uc2e4\ud5d8\uc774 \uc0ac\ub78c\uc5d0\uac8c \ub358\uc9c0\ub294 \uc9c8\ubb38\uc774 \ud568\uaed8 \ubcf4\uc778\ub2e4. \ud68c\uace0\ub85d\uc5d0\uc11c \ud3ec\ub4dc\ub294 \uc870\ub9bd \ubc29\uc2dd\uc744 \ubc14\uafb8\ub294 \uccab\uac78\uc74c\uc744 \uc774\ub807\uac8c \uc124\uba85\ud55c\ub2e4. \uc0ac\ub78c\uc774 \uc77c\uc744 \ucc3e\uc544\ub2e4\ub2c8\ub294 \ub300\uc2e0 \uc77c\uc774 \uc0ac\ub78c\uc5d0\uac8c \uc624\uac8c \ud588\ub2e4\ub294 \uac83\uc774\ub2e4. \ubd80\ud488\uc774 \ud544\uc694\ud55c \uc21c\uc11c\ub300\ub85c \ub193\uc774\uace0, \ub2e4\uc74c \uc791\uc5c5\uc790\uc5d0\uac8c \ub118\uc5b4\uac00\ub294 \uac70\ub9ac\uac00 \uc9e7\uc544\uc9c0\ub3c4\ub85d \uc791\uc5c5\uc7a5\uc744 \ub2e4\uc2dc \ubc30\uc5f4\ud588\ub2e4. \ubabb \ud558\ub098\ub97c \uc870\uc774\ub294 \uc19c\uc528\ub9cc \ube68\ub77c\uc838\uc11c\ub294 \ucda9\ubd84\ud558\uc9c0 \uc54a\ub2e4. \ubabb\uc744 \uac00\uc838\uc624\ub294 \ub370 \ub4dc\ub294 \uc2dc\uac04\uc774 \uadf8\ub300\ub85c\ub77c\uba74 \ud558\ub8e8 \uc804\uccb4\ub294 \ud06c\uac8c \ub2ec\ub77c\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \ud3ec\ub4dc\ub294 \uc0ac\ub78c\uc774 \uac77\uace0 \ubab8\uc744 \uc219\uc774\ub294 \ub3d9\uc791\uae4c\uc9c0 \uc0dd\uc0b0 \uacfc\uc815\uc73c\ub85c \ubcf4\uc558\ub2e4. \uc6b0\ub9ac\uac00 \uac00\uad6c\ub97c \uc870\ub9bd\ud558\ub2e4\uac00 \ub4dc\ub77c\uc774\ubc84\ub97c \ucc3e\ub290\ub77c \uc790\ub9ac\ub97c \ub728\ub294 \uc77c\uc744 \uacf5\uc7a5 \uc804\uccb4\uc758 \ud06c\uae30\ub85c \ud655\ub300\ud55c \uc148\uc774\ub2e4. \ucc45\uc740 1913\ub144 \ubd04, \ud50c\ub77c\uc774\ud720 \ub9c8\uadf8\ub124\ud1a0\ub77c\ub294 \uc810\ud654 \uad00\ub828 \ubd80\ud488\uc758 \uc870\ub9bd\uc5d0 \uc774\ub3d9\uc2dd \ub77c\uc778\uc744 \uc2dc\ud5d8\ud588\ub2e4\uace0 \uc804\ud55c\ub2e4. \uc790\ub3d9\ucc28 \ud55c \ub300\ub97c \ucc98\uc74c\ubd80\ud130 \ub05d\uae4c\uc9c0 \uc6c0\uc9c1\uc774\ub294 \uac70\ub300\ud55c \uc124\ube44\ub97c \ub2e8\ubc88\uc5d0 \uc644\uc131\ud588\ub2e4\ub294 \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub2e4. \uba3c\uc800 \uc791\uc740 \ubd80\ud488 \ud558\ub098\ub85c \uc0c8\ub85c\uc6b4 \ubc29\uc2dd\uc744 \uc2dc\ud5d8\ud588\ub2e4. \ud55c \uc0ac\ub78c\uc774 \uc5ec\ub7ec \uc791\uc5c5\uc744 \uc774\uc5b4 \ud558\ub358 \uacfc\uc815\uc744 \uc5ec\ub7ec \ub2e8\uacc4\ub85c \ub098\ub204\uace0, \uc791\uc5c5\uc758 \ub192\uc774\uc640 \uc774\ub3d9 \uc18d\ub3c4\ub97c \uc870\uc815\ud588\ub2e4. \ud68c\uace0\ub85d\uc5d0\ub294 \uc2dc\uce74\uace0 \uc721\uac00\uacf5\uc7a5\uc758 \uc774\ub3d9 \uc7a5\uce58\uac00 \ubc1c\uc0c1\uc5d0 \ucc38\uace0\uac00 \ub418\uc5c8\ub2e4\ub294 \uc124\uba85\ub3c4 \uc788\ub2e4. \ud3ec\ub4dc\uac00 \uc138\uc0c1\uc758 \ubd84\uc5c5\uacfc \uc774\ub3d9\uc2dd \uc0dd\uc0b0\uc744 \ud63c\uc790 \ucc98\uc74c \ubc1c\uba85\ud588\ub2e4\uace0 \ub113\ud600 \ub9d0\ud558\uba74 \uc774 \ubc30\uacbd\uc744 \ub193\uce58\uac8c \ub41c\ub2e4. \ubd80\ud488\uc5d0\uc11c \ud6a8\uacfc\ub97c \ubcf8 \ub4a4\uc5d0\ub294 \uc790\ub3d9\ucc28\uc758 \ubf08\ub300\uc778 \uc100\uc2dc\uc5d0\ub3c4 \uc2dc\ub3c4\ud588\ub2e4. \ud68c\uace0\ub85d\uc5d0 \ub530\ub974\uba74 \ucd08\uae30 \uc2e4\ud5d8\uc5d0\uc11c\ub294 \ubc27\uc904\uacfc \uad8c\uc591\uae30\ub85c \uc100\uc2dc\ub97c \ub04c\uc5c8\uace0, \uc870\ub9bd\uacf5\ub4e4\uc774 \ud568\uaed8 \uc6c0\uc9c1\uc774\uba70 \ud544\uc694\ud55c \ubd80\ud488\uc744 \uc9d1\uc5c8\ub2e4. \uc624\ub298\ub0a0 \uc0ac\uc9c4\uc5d0\uc11c \ubcf4\ub294 \uc815\ub3c8\ub41c \uacf5\uc7a5\ubcf4\ub2e4 \ud6e8\uc52c \uac70\uce5c \uc2dc\ud5d8\uc774\uc5c8\ub2e4. \uadf8\ub2e4\uc74c\uc5d0\ub294 \uc791\uc5c5 \ub192\uc774\ub97c \ubc14\uafb8\uace0 \uac01 \uc0ac\ub78c\uc774 \ub9e1\ub294 \ub3d9\uc791\uc744 \ub354 \uc138\ubd84\ud654\ud588\ub2e4. \uc5b4\ub290 \uc7a5\uce58 \ud558\ub098\ub97c \ub4e4\uc5ec\ub193\uc790 \ubaa8\ub4e0 \ubb38\uc81c\uac00 \uc0ac\ub77c\uc9c4 \uac83\uc774 \uc544\ub2c8\ub2e4. \uacf5\uad6c\uac00 \ub193\uc774\ub294 \uc704\uce58, \ubd80\ud488\uc774 \ub3c4\ucc29\ud558\ub294 \uc21c\uc11c, \uc0ac\ub78c\uc774 \uc190\uc744 \ubed7\ub294 \ub192\uc774\uac00 \ud568\uaed8 \ub9de\uc544\uc57c \ucc28\uac00 \uc77c\uc815\ud558\uac8c \uc55e\uc73c\ub85c \ub098\uac08 \uc218 \uc788\uc5c8\ub2e4. \ud3ec\ub4dc\ub294 \uc774\ub3d9 \uc18d\ub3c4\ub97c \uc5ec\ub7ec \ubc88 \ubc14\uafb8\uc5c8\ub2e4\uace0 \uc801\uc5c8\ub2e4. \ube68\ub9ac \uc6c0\uc9c1\uc774\uae30\ub9cc \ud558\uba74 \uc88b\uc740 \ub77c\uc778\uc774\ub77c\uba74 \uc774\ub7f0 \uc870\uc815\uc740 \ud544\uc694\ud558\uc9c0 \uc54a\uc558\uc744 \uac83\uc774\ub2e4. \uc791\uc5c5\uc744 \ub05d\ub0b4\uae30\ub3c4 \uc804\uc5d0 \ubd80\ud488\uc774 \uc9c0\ub098\uac00\uba74 \ub2e4\uc74c \ub2e8\uacc4\uc5d0 \ubb38\uc81c\uac00 \uc313\uc774\uace0, \ub108\ubb34 \ub290\ub9ac\uba74 \uc55e\uc5d0\uc11c \uc904\uc778 \uc2dc\uac04\uc744 \ub4a4\uc5d0\uc11c \ub2e4\uc2dc \uc783\ub294\ub2e4. \uc870\ub9bd\ub77c\uc778\uc758 \ud575\uc2ec\uc740 \ud55c \uc0ac\ub78c\uc758 \ub208\ubd80\uc2e0 \uc190\ub180\ub9bc\ubcf4\ub2e4 \uc5ec\ub7ec \uc0ac\ub78c\uc758 \uc18d\ub3c4\ub97c \uc11c\ub85c \ub9de\ucd94\ub294 \ub370 \uc788\uc5c8\ub2e4. \uc870\ub9bd \uc911\uac04\uc5d0 \uc798\ubabb\ub41c \ubd80\ud488\uc774 \ub07c\uac70\ub098 \uc791\uc5c5\uc774 \ub2a6\uc5b4\uc9c8 \ub54c\uc758 \uc601\ud5a5\ub3c4 \ucee4\uc9c4\ub2e4. \uacf5\uc7a5\uc740 \uac01\uac01\uc758 \uc7a5\uc778\uc774 \ub3c5\ub9bd\ud574\uc11c \uc77c\ud558\ub294 \uacf5\uac04\uc5d0\uc11c \uc11c\ub85c\uc758 \ubc15\uc790\uc5d0 \uc601\ud5a5\uc744 \ubc1b\ub294 \uc5f0\uacb0\ub41c \uacf5\uac04\uc73c\ub85c \ubc14\ub00c\uc5c8\ub2e4. \uc774 \ubc29\uc2dd\uc740 \ube44\uc2b7\ud55c \ubd80\ud488\uc744 \uc815\ud574\uc9c4 \uc21c\uc11c\ub85c \ubc18\ubcf5\ud574\uc11c \uc870\ub9bd\ud560 \ub54c \ud798\uc744 \ubc1c\ud718\ud55c\ub2e4. \uc8fc\ubb38\ub9c8\ub2e4 \uad6c\uc870\uac00 \uc644\uc804\ud788 \ub2ec\ub77c\uc9c4\ub2e4\uba74 \uac19\uc740 \ubc30\uce58\uc640 \uc18d\ub3c4\ub97c \uc720\uc9c0\ud558\uae30 \uc5b4\ub835\ub2e4. \uc0dd\uc0b0 \ubc29\uc2dd\uc758 \ubcc0\ud654\ub294 \uc81c\ud488\uc744 \uc5bc\ub9c8\ub098 \ub2e4\uc591\ud558\uac8c \ub9cc\ub4e4 \uac83\uc778\uc9c0\ub77c\ub294 \uacbd\uc601\uc758 \uc120\ud0dd\uacfc \ub5a8\uc5b4\uc838 \uc788\uc9c0 \uc54a\uc558\ub2e4. \uc791\uc5c5 \uc2dc\uac04\uc774 \uc904\uc5b4\ub4e4\uba74 \ud55c \ub300\ub97c \ub9cc\ub4dc\ub294 \ube44\uc6a9\uc744 \ub0ae\ucd9c \uac00\ub2a5\uc131\uc774 \uc0dd\uae34\ub2e4. \uadf8\ub7ec\ub098 \uc790\ub3d9\ucc28 \uac00\uaca9\uc758 \ubcc0\ud654 \uc804\uccb4\ub97c \uc870\ub9bd\ub77c\uc778 \ud55c \uac00\uc9c0\ub85c \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \ubd80\ud488 \uc0dd\uc0b0, \uc7ac\ub8cc \uad6c\uc785, \ud310\ub9e4 \uaddc\ubaa8\ub3c4 \ud568\uaed8 \uc791\uc6a9\ud55c\ub2e4. \uc5ec\uae30\uc11c \ubd84\uba85\ud788 \ubcfc \uc218 \uc788\ub294 \uac83\uc740 \uc6c0\uc9c1\uc784\uc744 \uc904\uc774\ub294 \uc77c\uc774 \uae30\uc5c5\uc758 \uacbd\uc7c1\ub825\uacfc \uc5f0\uacb0\ub418\uc5c8\ub2e4\ub294 \uc810\uc774\ub2e4. \ubb34\uac70\uc6b4 \uac83\uc744 \uba40\ub9ac \ub098\ub974\uac70\ub098 \uc790\uc8fc \ubab8\uc744 \uc219\uc774\ub294 \uc77c\uc744 \uc904\uc774\ub294 \uac83\uc740 \ubd84\uba85 \ub3c4\uc6c0\uc774 \ub420 \uc218 \uc788\ub2e4. \ubc18\uba74 \uac19\uc740 \uc9e7\uc740 \ub3d9\uc791\uc744 \uc624\ub798 \ubc18\ubcf5\ud558\uace0 \uc815\ud574\uc9c4 \uc18d\ub3c4\uc5d0 \ub9de\ucd94\ub294 \ubd80\ub2f4\ub3c4 \uc0dd\uac01\ud574 \ubcfc \uc218 \uc788\ub2e4. \uc0dd\uc0b0\ub7c9\uc774 \ub298\uc5c8\ub2e4\ub294 \uc218\uce58\ub9cc\uc73c\ub85c \uc77c\ud558\ub294 \uc0ac\ub78c\uc758 \uacbd\ud5d8\uc774 \ubaa8\ub450 \uc88b\uc544\uc84c\ub2e4\uace0 \ud310\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc774 \uc9c8\ubb38\uc740 \ud68c\uace0\ub85d\uc744 \uc77d\ub294 \ud0dc\ub3c4\uc640\ub3c4 \uc5f0\uacb0\ub41c\ub2e4. \uacbd\uc601\uc790\ub294 \uc790\uc2e0\uc774 \uc870\uc9c1\ud55c \uc0dd\uc0b0\uc758 \ud6a8\uc728\uc744 \uc55e\uc138\uc6b4\ub2e4. \uadf8 \uc124\uba85\uc740 \uc911\uc694\ud55c \uc790\ub8cc\uc774\uc9c0\ub9cc \ub178\ub3d9\uc790 \ubaa8\ub450\uc758 \ubaa9\uc18c\ub9ac\ub97c \ub300\uc2e0\ud558\uc9c0 \uc54a\ub294\ub2e4. \ud68c\uace0\ub85d\uc5d0 \uc801\ud78c \uc2dc\uac04 \ub2e8\ucd95\uc740 \uc800\uc790\uc758 \ubcf4\uace0\ub85c \uc77d\uace0, \uac70\uae30\uc11c \uace7\ubc14\ub85c \ubaa8\ub4e0 \uc0ac\ub78c\uc758 \ub9cc\uc871\uc744 \ucd94\ub860\ud558\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc815\ud655\ud558\ub2e4. \uc790\ub3d9\ucc28\uac00 \uc904\uc9c0\uc5b4 \uc788\ub294 \uc61b \uacf5\uc7a5 \uc0ac\uc9c4\uc744 \ubcf4\uba74 \uc644\uc131\ud488\ubcf4\ub2e4 \uadf8 \uc0ac\uc774\ub97c \uc0b4\ud3b4\ubcf4\uc790. \ubd80\ud488\uc774 \uc5b4\ub290 \ucabd\uc5d0\uc11c \ub4e4\uc5b4\uc624\uace0 \uc0ac\ub78c\uc774 \uc5b4\ub514\uc5d0 \uc11c \uc788\ub294\uc9c0, \ub2e4\uc74c \uc0ac\ub78c\uc5d0\uac8c \ubb34\uc5c7\uc744 \ub118\uae30\ub294\uc9c0 \uc0dd\uac01\ud558\uba74 \uc870\ub9bd\ub77c\uc778\uc774 \ucd94\uc0c1\uc801\uc778 \uc6a9\uc5b4\uc5d0\uc11c \uad6c\uccb4\uc801\uc778 \uacf5\uac04\uc73c\ub85c \ubc14\ub010\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\uc740 \uc774 \uc6d0\ub9ac\ub97c \ub5a0\uc62c\ub9ac\uae30 \uc704\ud55c AI \uc0bd\ud654\ub2e4. \ud2b9\uc815 \uacf5\uc7a5\uc758 \uc2e4\uc81c \uc124\ube44\ub97c \ubcf5\uc6d0\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uc2e4\uc81c \uacf5\uc815\uc758 \uc815\ud655\ud55c \ubaa8\uc591\uacfc \uc5ec\uae30\uc11c \uc124\uba85\ud55c \uc0dd\uc0b0 \uc6d0\ub9ac\ub97c \uad6c\ubcc4\ud558\uba74 \uadf8\ub9bc\uc744 \ud3b8\ud558\uac8c \ubcf4\uba74\uc11c\ub3c4 \uc0c1\uc0c1\uc73c\ub85c \ucc44\uc6b4 \uc7a5\uba74\uc744 \uc0ac\ub8cc\uc640 \ud63c\ub3d9\ud558\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \ud3ec\ub4dc\uc758 \uc774\uc57c\uae30\ub294 \uc88b\uc740 \ubb3c\uac74\uc744 \ub9cc\ub4dc\ub294 \uc77c\uc774 \uadf8 \ubb3c\uac74\uc758 \uc124\uacc4\ub3c4 \uc548\uc5d0\uc11c\ub9cc \uc774\ub8e8\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4\ub294 \uac83\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uac19\uc740 \ubd80\ud488\uc774\ub77c\ub3c4 \uc5b4\ub514\uc5d0 \ub193\uace0 \uc5b4\ub5a4 \uc21c\uc11c\ub85c \ub118\uae30\ub294\uc9c0\uc5d0 \ub530\ub77c \uacf5\uc7a5 \uc804\uccb4\uc758 \ud558\ub8e8\uac00 \ub2ec\ub77c\uc84c\ub2e4. \ub208\uc5d0 \uc798 \ub744\uc9c0 \uc54a\ub358 \uc774\ub3d9\uc774 \uc911\uc694\ud55c \uc124\uacc4\uc758 \ub300\uc0c1\uc774 \ub41c \uac83\uc774\ub2e4. \ub3d9\uc2dc\uc5d0 \ud6a8\uc728\uc744 \ub204\uad6c\uc758 \uad00\uc810\uc5d0\uc11c \ud310\ub2e8\ud560\uc9c0\ub3c4 \ubb3b\uac8c \ud55c\ub2e4. \ub354 \ub9ce\uc740 \uc790\ub3d9\ucc28\uc640 \ub354 \uc9e7\uc740 \uc791\uc5c5 \uc2dc\uac04, \ubc18\ubcf5\ub418\ub294 \ub178\ub3d9\uc758 \uacbd\ud5d8\uc740 \ud55c \uc7a5\uba74 \uc548\uc5d0 \ud568\uaed8 \uc788\ub2e4. \uc870\ub9bd\ub77c\uc778\uc744 \uc54c\uace0 \ub098\uba74 \uc624\ub798\ub41c \uc790\ub3d9\ucc28 \ud55c \ub300\uc5d0\uc11c\ub3c4 \uc5d4\uc9c4\ubfd0 \uc544\ub2c8\ub77c \uc218\ub9ce\uc740 \uc0ac\ub78c\uc758 \uc790\ub9ac\uc640 \uc6c0\uc9c1\uc784\uc744 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4."}, {"id": "harley-davidson-riders-and-community", "title": "\ud560\ub9ac\ub370\uc774\ube44\uc2a8 \u2014 \uc624\ud1a0\ubc14\uc774 \ub2e4\uc74c\uc5d0\ub294 \ubb34\uc5c7\uc744 \ud314\uae4c", "summary": "\uc18c\uc720\uc790 \ubaa8\uc784\uacfc \ucd08\ubcf4\uc790\ub97c \ub3d5\ub294 \uacbd\ud5d8\uc744 \ud1b5\ud574 \uc81c\ud488 \uc774\ud6c4\uc758 \uad00\uacc4\uac00 \ube0c\ub79c\ub4dc\ub97c \ub9cc\ub4dc\ub294 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "companies", "category_title": "Companies", "subcategory": "Automotive", "url": "stories/harley-davidson-riders-and-community/index.html", "image": "media/harley-davidson-riders-and-community.png", "alt": "\uae38\uac00\uc5d0 \uc138\uc6b4 \uc77c\ubc18\uc801\uc778 \uc624\ud1a0\ubc14\uc774 \uc606\uc5d0\uc11c \uc0ac\ub78c\ub4e4\uc774 \uc9c0\ub3c4\ub97c \ubcf4\uba70 \uacbd\ud5d8\uc744 \ub098\ub204\ub294 \uc0bd\ud654.", "text": "\ud560\ub9ac\ub370\uc774\ube44\uc2a8 \u2014 \uc624\ud1a0\ubc14\uc774 \ub2e4\uc74c\uc5d0\ub294 \ubb34\uc5c7\uc744 \ud314\uae4c \ubb3c\uac74\uc744 \uc0b0 \ub4a4\uc5d0 \uc2dc\uc791\ub418\ub294 \uc0ac\ub78c\ub4e4\uc758 \uad00\uacc4 \uc18c\uc720\uc790 \ubaa8\uc784\uacfc \ucd08\ubcf4\uc790\ub97c \ub3d5\ub294 \uacbd\ud5d8\uc744 \ud1b5\ud574 \uc81c\ud488 \uc774\ud6c4\uc758 \uad00\uacc4\uac00 \ube0c\ub79c\ub4dc\ub97c \ub9cc\ub4dc\ub294 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Automotive \uae30\uc5c5 \uac19\uc740 \uc624\ud1a0\ubc14\uc774\ub97c \ud0c0\ub294 \uc0ac\ub78c\ub4e4\uc774 \uc8fc\ub9d0 \uc544\uce68\uc5d0 \ubaa8\uc778\ub2e4. \ucc98\uc74c \ub9cc\ub09c \uc0ac\uc774\uc778\ub370\ub3c4 \uc7a5\ube44\uc640 \uae38 \uc774\uc57c\uae30\uac00 \uace7 \uc774\uc5b4\uc9c4\ub2e4. \ud55c \uc0ac\ub78c\uc740 \uba3c \uac70\ub9ac\ub97c \ub2ec\ub9b4 \uc900\ube44\ub97c \ubb3b\uace0 \ub2e4\ub978 \uc0ac\ub78c\uc740 \uc790\uc2e0\uc758 \uacbd\ud5d8\uc744 \ub4e4\ub824\uc900\ub2e4. \uc774\ub7f0 \uac00\uc0c1\uc758 \uc7a5\uba74\uc744 \ub5a0\uc62c\ub9ac\uba74 \uc81c\ud488\uc744 \uc0b0 \ub2e4\uc74c\uc5d0 \ubb34\uc5c7\uc774 \uc2dc\uc791\ub418\ub294\uc9c0 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \ud560\ub9ac\ub370\uc774\ube44\uc2a8\uc740 \uacbd\uc601 \uad50\uc7ac\uc5d0\uc11c \uc774\ub7f0 \uacbd\ud5d8\uacfc \uad00\uacc4\ub97c \uc124\uba85\ud558\ub294 \uc0ac\ub840\ub85c \ub4f1\uc7a5\ud55c\ub2e4. \uc5d4\uc9c4\uacfc \ubc14\ud034\ub9cc\uc774 \uc544\ub2c8\ub77c \uc18c\uc720\uc790\uac00 \ub2e4\ub978 \uc0ac\ub78c\uacfc \ub098\ub204\ub294 \uc2dc\uac04\uc774 \ube0c\ub79c\ub4dc\uc758 \uc77c\ubd80\uac00 \ub418\ub294 \uac83\uc774\ub2e4. \uc624\ud1a0\ubc14\uc774\ub97c \uc798 \ubaa8\ub974\ub294 \ub3c5\uc790\ub3c4 \ubb3c\uac74\uacfc \uacf5\ub3d9\uccb4\uc758 \uad00\uacc4\ub85c \uc77d\uc5b4 \ubcfc \uc218 \uc788\ub2e4. \uad50\uc7ac\ub294 \ud560\ub9ac\ub370\uc774\ube44\uc2a8\uc758 \uace0\uac1d\ub4e4\uc774 \ubaa8\ub450 \uac19\uc740 \uacbd\ud5d8\uc744 \uc6d0\ud558\uc9c0 \uc54a\ub294\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc5b4\ub5a4 \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc77c\uc0c1\uc5d0\uc11c \ubc97\uc5b4\ub098\ub294 \uc5ec\ud589\uc774\uace0 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc774\ub3d9 \uc218\ub2e8\uc774\ub098 \uc0dd\ud65c \ubc29\uc2dd\uc758 \uc77c\ubd80\ub2e4. \ud558\ub098\uc758 \uc0c1\ud45c\ub97c \uc120\ud0dd\ud574\ub3c4 \uadf8 \ubb3c\uac74\uc5d0 \uae30\ub300\ud558\ub294 \uac83\uc740 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uad11\uace0\uc5d0\uc11c \uc790\uc8fc \ubcf4\uc774\ub294 \uc790\uc720\ub77c\ub294 \ub2e8\uc5b4\ub3c4 \ubaa8\ub4e0 \uc0ac\ub78c\uc5d0\uac8c \uac19\uc740 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ud63c\uc790 \uc870\uc6a9\ud788 \ub2ec\ub9ac\ub294 \uc77c\uacfc \uc0ac\ub78c\ub4e4\uacfc \ud568\uaed8 \ub5a0\ub098\ub294 \uc77c\uc740 \ub2e4\ub978 \uc990\uac70\uc6c0\uc774\ub2e4. \uae30\uc5c5\uc774 \uc81c\uc2dc\ud55c \uc774\ubbf8\uc9c0\uc640 \uc18c\uc720\uc790\uac00 \uc2e4\uc81c\ub85c \ub9cc\ub4dc\ub294 \uacbd\ud5d8\uc744 \ub098\ub204\uc5b4 \ubcf4\uba74 \uace0\uac1d\uc740 \ub2e8\uc21c\ud788 \uad11\uace0\ub97c \ub530\ub77c \ud558\ub294 \uc874\uc7ac\ub85c\ub9cc \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uad50\uc7ac\ub294 \uc77c\ubd80 \ud310\ub9e4\uc810\uc5d0\uc11c \ubd80\ud488\uacfc \uc561\uc138\uc11c\ub9ac\ub97c \uace8\ub77c \ucc28\ub97c \uafb8\ubbf8\ub294 \uc77c\uc744 \ub3d5\ub294 \uc804\ubb38 \uc0c1\ub2f4\uc744 \uc18c\uac1c\ud55c\ub2e4. \uc0c1\ud45c\uac00 \uac19\uc544\ub3c4 \uc18c\uc720\uc790\uac00 \uc138\ubd80\ub97c \ubc14\uafb8\uba70 \uc790\uae30 \ucde8\ud5a5\uc744 \ub4dc\ub7ec\ub0bc \uc218 \uc788\ub294 \uac83\uc774\ub2e4. \uc758\ubcf5\uacfc \uc7a5\ube44 \uac19\uc740 \uc8fc\ubcc0 \uc0c1\ud488\ub3c4 \uc774 \uacbd\ud5d8\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uc774\uac83\uc740 \ud2b9\uc815\ud55c \uac1c\uc870\ub97c \uad8c\ud558\uac70\ub098 \ubaa8\ub4e0 \ud310\ub9e4\uc810\uc758 \ud604\uc7ac \uc11c\ube44\uc2a4\ub97c \uc548\ub0b4\ud558\ub294 \ub9d0\uc740 \uc544\ub2c8\ub2e4. \uc6d0\ub798\uc758 \uc81c\ud488\uacfc \ub098\uc5d0\uac8c \ub9de\ucd94\ub294 \uacfc\uc815\uc774 \ud568\uaed8 \uc0c1\ud488\uc774 \ub420 \uc218 \uc788\ub2e4\ub294 \uc0ac\ub840\ub2e4. \uac19\uc740 \uae30\ub2a5\uc744 \uac00\uc9c4 \ubb3c\uac74 \uc0ac\uc774\uc5d0\uc11c\ub3c4 \ub0b4\uac00 \ucc38\uc5ec\ud574 \uc120\ud0dd\ud588\ub2e4\ub294 \ub290\ub08c\uc740 \ub2e4\ub978 \uc885\ub958\uc758 \uc560\ucc29\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub2e4. \ud560\ub9ac \uc624\ub108\uc2a4 \uadf8\ub8f9, \ud754\ud788 H.O.G.\ub77c\uace0 \ubd80\ub974\ub294 \uc18c\uc720\uc790 \ubaa8\uc784\ub3c4 \uad50\uc7ac\uc5d0 \uc18c\uac1c\ub41c\ub2e4. \ud589\uc0ac\uc640 \ud568\uaed8 \ub2ec\ub9ac\ub294 \ubaa8\uc784\uc740 \uc624\ud1a0\ubc14\uc774\ub97c \uc0b0 \uc0ac\ub78c\uc774 \ub2e4\ub978 \uc18c\uc720\uc790\ub97c \ub9cc\ub0a0 \uae30\ud68c\ub97c \uc900\ub2e4. \ub9e4\uc7a5\uacfc \uc9d1\uc744 \uc624\uac00\ub294 \uad00\uacc4 \ubc16\uc5d0 \uc0c8\ub85c\uc6b4 \uc7a5\uc18c\uac00 \ub9cc\ub4e4\uc5b4\uc9c0\ub294 \uc148\uc774\ub2e4. \ub2e4\ub9cc \ud68c\uc6d0\uc774\ub77c\ub294 \uc774\ub984\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \uc5b8\uc81c\ub098 \uac19\uc740 \uc0dd\uac01\uc744 \uac16\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ucc38\uc5ec\ud558\ub294 \uc815\ub3c4\uc640 \uc5ec\ud589\uc758 \ucde8\ud5a5\ub3c4 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uacf5\ub3d9\uccb4\uac00 \uc788\ub2e4\ub294 \ub9d0\uc740 \uac1c\uc778\ucc28\uac00 \uc0ac\ub77c\uc84c\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \ub2e4\uc591\ud55c \uc0ac\ub78c\uc774 \uc81c\ud488 \ud558\ub098\ub97c \uacf5\ud1b5\uc758 \ub300\ud654 \uc18c\uc7ac\ub85c \uc0bc\uc744 \uc218 \uc788\ub2e4\ub294 \uc810\uc5d0\uc11c \uc77d\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uad50\uc7ac\uac00 \ud2b9\ud788 \uac15\uc870\ud558\ub294 \uac83\uc740 \uacbd\ud5d8 \ub9ce\uc740 \uc18c\uc720\uc790\uac00 \uc0c8 \uc18c\uc720\uc790\ub97c \ub3d5\ub294 \uc5ed\ud560\uc774\ub2e4. \ub354 \uae34 \uc5ec\ud589\uc744 \uc5b4\ub5bb\uac8c \uc900\ube44\ud560\uc9c0, \uc9d0\uc744 \uc5b4\ub5bb\uac8c \ucc59\uae38\uc9c0 \uac19\uc740 \uacbd\ud5d8\uc744 \ub098\ub208\ub2e4. \uc81c\ud488 \uc124\uba85\uc11c\uac00 \ub2f4\uae30 \uc5b4\ub824\uc6b4 \uc0dd\ud65c\uc758 \uc9c0\uc2dd\uc774 \uc0ac\ub78c \uc0ac\uc774\ub97c \ud1b5\ud574 \uc804\ub2ec\ub418\ub294 \uac83\uc774\ub2e4. \uc774\ub54c \uc548\ub0b4\uc790\ub294 \ud68c\uc0ac \uc9c1\uc6d0\ub9cc\uc774 \uc544\ub2c8\ub2e4. \uc790\uc2e0\uc774 \ud574 \ubcf8 \uc77c\uc744 \ubc14\ud0d5\uc73c\ub85c \uc870\uc5b8\ud558\ub294 \ub2e4\ub978 \uc774\uc6a9\uc790\ub2e4. \ubb3c\ub860 \uac1c\uc778\uc758 \uacbd\ud5d8\uc774 \uacf5\uc2dd \uc548\uc804 \uc9c0\uce68\uc774\ub098 \uc804\ubb38 \uad50\uc721\uc744 \ub300\uc2e0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \ubb3c\uac74\uc744 \uc0ac\uc6a9\ud558\ub294 \ub370 \ud544\uc694\ud55c \uc815\ubcf4\uac00 \ud310\ub9e4 \uc2dc\uc810\uc758 \uc124\uba85\ub9cc\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc810\uc740 \ubd84\uba85\ud574\uc9c4\ub2e4. \ub0af\uc120 \uad11\uace0\uc758 \uc88b\uc740 \ub9d0\ubcf4\ub2e4 \uc544\ub294 \uc0ac\ub78c\uc758 \uc0ac\uc6a9 \uacbd\ud5d8\uc5d0 \ub9c8\uc74c\uc774 \uc6c0\uc9c1\uc77c \ub54c\uac00 \uc788\ub2e4. \uadf8 \uc0ac\ub78c\uc758 \ucde8\ud5a5\uacfc \uc0c1\ud669\uc744 \uc54c\uba74 \ub0b4 \uacbd\uc6b0\uc640 \ube44\uad50\ud558\uae30\ub3c4 \uc27d\ub2e4. \uad50\uc7ac\ub294 \uc18c\uc720\uc790\ub4e4\uc758 \uc774\ub7f0 \ub300\ud654\uc640 \ucd94\ucc9c\uc774 \ube0c\ub79c\ub4dc\uc758 \uc911\uc694\ud55c \uc804\ub2ec \uacbd\ub85c\uac00 \ub41c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc774\uc6a9\uc790\uc758 \ub9d0\uc774 \ubaa8\ub450 \uac1d\uad00\uc801\uc774\uac70\ub098 \ubaa8\ub4e0 \uad6c\ub9e4\uc790\uc5d0\uac8c \ub9de\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc88b\uc544\ud558\ub294 \ube0c\ub79c\ub4dc\uc5d0\ub294 \uc560\uc815\uacfc \uae30\ub300\uac00 \ud568\uaed8 \uc791\uc6a9\ud55c\ub2e4. \uce5c\uadfc\ud55c \ucd94\ucc9c\uc744 \ub4e3\ub294 \uc77c\uacfc \uc81c\ud488\uc758 \uc870\uac74\uc744 \ubcc4\ub3c4\ub85c \ud655\uc778\ud558\ub294 \uc77c\uc740 \ud568\uaed8 \ud560 \uc218 \uc788\ub2e4. \uacbd\ud5d8\uc774 \uc124\ub4dd\ub825\uc744 \uac16\ub294 \uc774\uc720\ub97c \uc774\ud574\ud558\ub418 \uadf8\uac83\uc744 \ubcf4\uc99d\uc11c\ucc98\ub7fc \uc77d\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \ud55c \ubc88 \uad6c\ub9e4\uac00 \uc774\ub8e8\uc5b4\uc84c\ub2e4\uace0 \uacf5\ub3d9\uccb4\uac00 \uc800\uc808\ub85c \uc624\ub798 \uc774\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \ub2e4\uc2dc \ub9cc\ub098\uace0 \uc815\ubcf4\ub97c \ub098\ub20c \uc790\ub9ac\uac00 \ud544\uc694\ud558\ub2e4. \uad50\uc7ac\ub294 \ud589\uc0ac\uc640 \uc628\ub77c\uc778 \ubaa8\uc784, \uad00\ub828 \uac04\ud589\ubb3c\uc774 \uacbd\ud5d8\uc744 \uc774\uc5b4 \uc8fc\ub294 \ud1b5\ub85c\ub77c\uace0 \uc18c\uac1c\ud55c\ub2e4. \uc81c\ud488 \ubc14\uae65\uc5d0\ub3c4 \uad00\uacc4\ub97c \uc720\uc9c0\ud558\ub294 \uc77c\uc774 \uc874\uc7ac\ud55c\ub2e4. \uc774\ub7f0 \ud65c\ub3d9\uc5d0\ub294 \uc2dc\uac04\uacfc \ube44\uc6a9\uc774 \ub4e0\ub2e4. \ub9e4\ub825\uc801\uc778 \uad6c\ud638\ub97c \ubd99\uc774\ub294 \uc77c\uacfc \uc2e4\uc81c\ub85c \uc0c8 \uc774\uc6a9\uc790\uac00 \ud3b8\ud558\uac8c \ucc38\uc5ec\ud560 \uc218 \uc788\ub3c4\ub85d \ub3d5\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \ube0c\ub79c\ub4dc\ub97c \uc88b\uc544\ud558\ub294 \uc0ac\ub78c\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uae30\uc5c5\uc758 \ubaa8\ub4e0 \ubb38\uc81c\uac00 \ud574\uacb0\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc88b\uc740 \uad00\uacc4\ub294 \uacc4\uc18d \ub3cc\ubcf4\uc544\uc57c \ud558\ub294 \ud65c\ub3d9\uc5d0 \uac00\uae5d\ub2e4. \uc624\ud1a0\ubc14\uc774\uc758 \ub0ad\ub9cc\uc740 \uc0ac\uc9c4\uacfc \uc774\uc57c\uae30\ub85c \uc804\ud574\uc9c0\uae30 \uc88b\ub2e4. \ud558\uc9c0\ub9cc \uc2e4\uc81c \uc120\ud0dd\uc5d0\ub294 \uc548\uc804\uacfc \ube44\uc6a9, \uc774\uc6a9 \ud658\uacbd\uc774 \ud568\uaed8 \ub4e4\uc5b4\uac04\ub2e4. \uc774\ubc88 \uc6d0\uace0\ub294 \uad50\uc7ac\uac00 \uc18c\uac1c\ud55c \ube0c\ub79c\ub4dc \uacf5\ub3d9\uccb4\uc758 \uc0ac\ub840\ub97c \ub2e4\ub8e8\uba70 \ud2b9\uc815 \ubaa8\ub378\uc758 \uc131\ub2a5\uc774\ub098 \ud604\uc7ac \ud310\ub9e4 \uc2e4\uc801\uc744 \ud3c9\uac00\ud55c \uae00\uc740 \uc544\ub2c8\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub3c4 \uc77c\ubc18\uc801\uc778 \ub77c\uc774\ub354\ub4e4\uc758 \ub9cc\ub0a8\uc744 \ud45c\ud604\ud588\ub2e4. \uc2e4\uc81c \ubaa8\uc784\uc758 \ucc38\uac00\uc790\ub098 \ud560\ub9ac\ub370\uc774\ube44\uc2a8\uc758 \ud2b9\uc815 \ucc28\uc885\uc744 \uc7ac\ud604\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uc774\ubbf8\uc9c0\uc5d0\uc11c\ub294 \uc5ec\ud589\uc744 \ub098\ub204\ub294 \ubd84\uc704\uae30\ub97c \ubcf4\uace0, \uae30\uc5c5\uc758 \uc0ac\ub840\uc5d0\uc11c\ub294 \ubb3c\uac74 \uc774\ud6c4\uc758 \uad00\uacc4\ub77c\ub294 \uc9c8\ubb38\uc744 \uc77d\uc73c\uba74 \ub41c\ub2e4. \ud560\ub9ac\ub370\uc774\ube44\uc2a8\uc758 \uc0ac\ub840\uc5d0\uc11c \ud765\ubbf8\ub85c\uc6b4 \uac83\uc740 \uc624\ud1a0\ubc14\uc774\ub97c \ub118\uaca8\ubc1b\uc740 \ub4a4\uc758 \uc2dc\uac04\uc774\ub2e4. \uc0ac\uc6a9\ud558\ub294 \ubc95\uc744 \ubc30\uc6b0\uace0 \ub2e4\ub978 \uc0ac\ub78c\uc744 \ub9cc\ub098\uba70 \uc790\uae30 \uacbd\ud5d8\uc744 \ub9d0\ud558\uac8c \ub41c\ub2e4. \ubb3c\uac74\uc774 \ub300\ud654\uc758 \uc2dc\uc791\uc810\uc774 \ub418\uace0 \uadf8 \ub300\ud654\uac00 \ube0c\ub79c\ub4dc\uc758 \uc758\ubbf8\ub97c \ub2e4\uc2dc \ub9cc\ub4e0\ub2e4. \ub2e4\uc74c\uc5d0 \uc5b4\ub5a4 \ubb3c\uac74\uc744 \uc624\ub798 \uc88b\uc544\ud558\ub294 \uc0ac\ub78c\ub4e4\uc744 \ub9cc\ub098\uba74 \ubb34\uc5c7\uc774 \uc88b\uc740\uc9c0\ubfd0 \uc544\ub2c8\ub77c \ub204\uad6c\uc640 \ubb34\uc5c7\uc744 \ub098\ub204\ub294\uc9c0\ub3c4 \ubb3c\uc5b4\ubcf4\uc790. \uae30\ub2a5\uacfc \uac00\uaca9 \ubc16\uc758 \uc774\uc57c\uae30\uac00 \ub098\uc62c \uc218 \uc788\ub2e4. \uae30\uc5c5\uc774 \ub9cc\ub4dc\ub294 \uac83\uc740 \uc81c\ud488\uc774\uc9c0\ub9cc \uadf8 \uc81c\ud488\uc774 \uc0b4\uc544\uac00\ub294 \uc138\uacc4\ub294 \uc774\uc6a9\uc790\ub4e4\uc758 \uad00\uacc4 \uc18d\uc5d0\uc11c\ub3c4 \ub9cc\ub4e4\uc5b4\uc9c4\ub2e4."}, {"id": "kodak-camera-and-lessons", "title": "\ucf54\ub2e5\uc740 \uce74\uba54\ub77c\uc640 \ud568\uaed8 \ubb34\uc5c7\uc744 \ud314\uc558\uc744\uae4c", "summary": "\ube0c\ub77c\uc6b0\ub2c8 \uce74\uba54\ub77c\uc640 \uc548\ub0b4 \ucc45\uc790, \uc7a1\uc9c0\ub97c \ud1b5\ud574 \uc0ac\uc9c4\uc744 \uc77c\uc0c1\uc758 \ucde8\ubbf8\ub85c \ub9cc\ub4e4\ub824\ub358 \uae30\uc5c5\uc758 \ubc29\uc2dd\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "companies", "category_title": "Companies", "subcategory": "Technology", "url": "stories/kodak-camera-and-lessons/index.html", "image": "media/kodak-camera-and-lessons.jpg", "alt": "1914\ub144 \ucf54\ub2e5 \uce74\ud0c8\ub85c\uadf8\uc758 No. 1 \ube0c\ub77c\uc6b0\ub2c8 \uc0c1\uc790\ud615 \uce74\uba54\ub77c \uc2e4\uc81c \ub3c4\ud310.", "text": "\ucf54\ub2e5\uc740 \uce74\uba54\ub77c\uc640 \ud568\uaed8 \ubb34\uc5c7\uc744 \ud314\uc558\uc744\uae4c 1914\ub144 \uce74\ud0c8\ub85c\uadf8\uc5d0\uc11c \ub9cc\ub098\ub294 \uc0ac\uc9c4\uc744 \ubc30\uc6b0\ub294 \uc0ac\ub78c\ub4e4 \ube0c\ub77c\uc6b0\ub2c8 \uce74\uba54\ub77c\uc640 \uc548\ub0b4 \ucc45\uc790, \uc7a1\uc9c0\ub97c \ud1b5\ud574 \uc0ac\uc9c4\uc744 \uc77c\uc0c1\uc758 \ucde8\ubbf8\ub85c \ub9cc\ub4e4\ub824\ub358 \uae30\uc5c5\uc758 \ubc29\uc2dd\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Technology \uae30\uc5c5 \uce74\uba54\ub77c\ub97c \uc0c0\ub2e4\uace0 \uace7\ubc14\ub85c \uc88b\uc740 \uc0ac\uc9c4\uc744 \ucc0d\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc544\uc774\uac00 \uc6c0\uc9c1\uc774\uace0, \ud587\ube5b\uc740 \ub108\ubb34 \uac15\ud558\uace0, \ud070 \uac74\ubb3c\uc740 \uc0ac\uc9c4 \uc548\uc5d0 \ub2e4 \ub4e4\uc5b4\uc624\uc9c0 \uc54a\ub294\ub2e4. \uc624\ub298\ub0a0\uc5d0\ub3c4 \uc775\uc219\ud55c \uc774 \ub09c\uac10\ud568\uc744 1914\ub144 \ucf54\ub2e5\uc758 \uce74\ud0c8\ub85c\uadf8\uac00 \uae38\uac8c \uc774\uc57c\uae30\ud55c\ub2e4. \ubb3c\uac74 \ubaa9\ub85d\uc758 \uccab\uba38\ub9ac\uc5d0 \ub193\uc778 \ub9d0\uc740 \ub73b\ubc16\uc5d0\ub3c4 \ub2e8\uc21c\ud588\ub2e4. \ub354 \uc27d\uac8c \ub9cc\ub4e4\ub77c\ub294 \uac83\uc774\uc5c8\ub2e4. \u300aKodaks and Kodak Supplies, 1914\u300b\ub294 \ud310\ub9e4\ub97c \uc704\ud55c \uc778\uc1c4\ubb3c\uc774\ub2e4. \uc81c\ud488\uc758 \uc7a5\uc810\uc740 \uac15\uc870\ud558\uace0 \uc57d\uc810\uc740 \ub35c \ub9d0\ud560 \uc218 \uc788\ub2e4. \uadf8\ub807\uc9c0\ub9cc \uc5b4\ub5a4 \uc0ac\ub78c\uc744 \uace0\uac1d\uc73c\ub85c \uc0c1\uc0c1\ud588\ub294\uc9c0, \uce74\uba54\ub77c\ub97c \uc0b0 \ub4a4 \ubb34\uc5c7\uc744 \ub3c4\uc640\uc8fc\uaca0\ub2e4\uace0 \uc57d\uc18d\ud588\ub294\uc9c0\ub97c \uc77d\uae30\uc5d0\ub294 \ud765\ubbf8\ub85c\uc6b4 \uc790\ub8cc\ub2e4. \uce74\ud0c8\ub85c\uadf8\ub294 \ucf54\ub2e5\uc774 \uc0ac\uc9c4\uc744 \uc27d\uac8c \ub9cc\ub4dc\ub294 \uae30\uad6c\ubfd0 \uc544\ub2c8\ub77c \uc0ac\ub78c\ub4e4\uc5d0\uac8c \uc0ac\uc9c4 \ucc0d\ub294 \ubc29\ubc95\uc744 \uc124\uba85\ud574 \uc654\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \uccab \ucf54\ub2e5\uc774 \ub098\uc628 1888\ub144\uc758 \uc124\uba85\uc11c\ub3c4 \ub2e8\uc21c\ud55c \uae30\uacc4 \uc870\uc791 \uc548\ub0b4\ub97c \ub118\uc5b4 \uac74\ubb3c\uacfc \uc5b4\ub9b0\uc544\uc774\ub97c \uc5b4\ub5bb\uac8c \ucc0d\uc744\uc9c0 \ub2e4\ub8e8\uc5c8\ub2e4\ub294 \uac83\uc774 \ud68c\uc0ac \uce21\uc758 \uc124\uba85\uc774\ub2e4. \uc5ec\uae30\uc5d0\ub294 \uc0c8\ub85c\uc6b4 \uace0\uac1d\uc5d0 \ub300\ud55c \uc0dd\uac01\uc774 \ub2f4\uaca8 \uc788\ub2e4. \uc774\ubbf8 \uc0ac\uc9c4\uc744 \uc798 \uc544\ub294 \uc804\ubb38\uac00\uc5d0\uac8c\ub9cc \ubb3c\uac74\uc744 \ud314\ub824\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc88b\uc740 \uc7a5\uba74\uc744 \ub0a8\uae30\uace0 \uc2f6\uc9c0\ub9cc \ub178\ucd9c \uc2dc\uac04\uc774\ub098 \ube5b\uc744 \uc798 \ubaa8\ub974\ub294 \uc0ac\ub78c\ub3c4 \uace0\uac1d\uc774 \ub420 \uc218 \uc788\ub2e4. \uae30\uc220\uc758 \uc0ac\uc6a9\uc790\ub97c \ub113\ud788\ub824\uba74 \uae30\uacc4\uc640 \ud568\uaed8 \ubc30\uc6b8 \uc218 \uc788\ub294 \uae38\ub3c4 \ub9c8\ub828\ud574\uc57c \ud588\ub2e4. \uc2e4\uc81c \ub3c4\ud310\uc5d0 \ubcf4\uc774\ub294 No. 1 \ube0c\ub77c\uc6b0\ub2c8\ub294 \ud654\ub824\ud55c \uc7a5\ube44\ubcf4\ub2e4 \uc190\uc5d0 \ub4e4\uace0 \ub2e4\ub2d0 \uc218 \uc788\ub294 \uc0c1\uc790\uc5d0 \uac00\uae5d\ub2e4. \uce74\ud0c8\ub85c\uadf8\ub294 \uc774 \uc81c\ud488\uc774 \uc6d0\ub798 \uc5b4\ub9b0\uc774\ub97c \uc5fc\ub450\uc5d0 \ub450\uc5c8\uc9c0\ub9cc \uc5b4\ub978\ub3c4 \uc0ac\uc6a9\ud558\uac8c \ub418\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc774\uac83 \uc5ed\uc2dc \ub2f9\uc2dc \ud310\ub9e4\uc790\uac00 \ub0b4\uc138\uc6b4 \uc81c\ud488 \uc774\uc57c\uae30\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \uae30\ub2a5\uc744 \ub9ce\uc774 \ub123\ub294 \uac83\ub9cc\uc774 \uc81c\ud488\uc758 \ub9e4\ub825\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc7a5\uce58\ub97c \ub0af\uc124\uc5b4\ud558\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \ubb34\uc5c7\uc744 \ud574\uc57c \ud560\uc9c0 \uc27d\uac8c \uc54c \uc218 \uc788\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \ube44\uad50\uc801 \ub2e8\uc21c\ud55c \uce74\uba54\ub77c\ub85c \uc77c\ub2e8 \uc0ac\uc9c4\uc744 \ucc0d\uc5b4 \ubcf4\ub294 \uacbd\ud5d8\uc740, \uc0ac\uc9c4\uc744 \ud2b9\ubcc4\ud55c \uc804\ubb38\uac00\uc758 \uc791\uc5c5\uc5d0\uc11c \uac00\uae4c\uc6b4 \uc0dd\ud65c\uc758 \ud65c\ub3d9\uc73c\ub85c \uc62e\uae30\ub294 \ud55c \ubc29\ubc95\uc774\uc5c8\ub2e4. \uc774 \ud310\ubcf8\uc5d0\ub294 No. 1 \ube0c\ub77c\uc6b0\ub2c8 \ubcf8\uccb4\uc758 \uac00\uaca9\uc774 1\ub2ec\ub7ec\ub85c \uc801\ud600 \uc788\ub2e4. \uc606\uc5d0\ub294 \ud734\ub300\uc6a9 \ucf00\uc774\uc2a4\uc640 \ubcc4\ub3c4 \ud30c\uc778\ub354 \ub4f1\uc758 \uac00\uaca9\ub3c4 \ubcf4\uc778\ub2e4. \uc624\ub298\uc758 \uac00\uaca9 \uac10\uac01\uc73c\ub85c \uc544\uc8fc \uc2f8\ub2e4\uace0 \ub2e8\uc815\ud558\uae30 \uc804\uc5d0, \uadf8 \uc22b\uc790\uac00 1914\ub144 \uce74\ud0c8\ub85c\uadf8\uc758 \ud45c\uc2dc \uac00\uaca9\uc774\ub77c\ub294 \uc0ac\uc2e4\uc744 \uba3c\uc800 \ubd99\uc7a1\uc544\uc57c \ud55c\ub2e4. \uad6c\uc785 \ube44\uc6a9\uc5d0\ub294 \ubcf8\uccb4\ub9cc \uc788\ub294 \uac83\uc774 \uc544\ub2c8\uc5c8\ub2e4. \ud544\ub984\uacfc \ud604\uc0c1, \uc778\ud654\uc5d0 \ub4e4\uc5b4\uac00\ub294 \ube44\uc6a9\ub3c4 \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4. \uc774 \uc790\ub8cc\ub294 \ud1a0\ub860\ud1a0\uc758 \uc8fc\uc18c\ub97c \uc0ac\uc6a9\ud558\ub294 \ud310\ubcf8\uc774\ubbc0\ub85c \ubaa8\ub4e0 \ub098\ub77c\uc5d0\uc11c \uac19\uc740 \uc870\uac74\uc73c\ub85c \uc0b4 \uc218 \uc788\uc5c8\ub2e4\uace0 \ub113\ud600 \ub9d0\ud560 \uc218\ub3c4 \uc5c6\ub2e4. \uc791\uc740 \uac00\uaca9\ud45c \ud558\ub098\uc5d0\ub3c4 \uc2dc\ub300\uc640 \ud310\ub9e4 \uc9c0\uc5ed\uc774\ub77c\ub294 \ubb38\ub9e5\uc774 \ubd99\ub294\ub2e4. \uc9c0\uae08\uc740 \ud654\uba74\uc5d0\uc11c \uacb0\uacfc\ub97c \ubc14\ub85c \ud655\uc778\ud558\uc9c0\ub9cc, \ub2f9\uc2dc \ud544\ub984 \uc0ac\uc9c4\uc5d0\uc11c\ub294 \ucd2c\uc601\uacfc \uacb0\uacfc\ub97c \ubcf4\ub294 \uc21c\uac04 \uc0ac\uc774\uc5d0 \ub2e4\ub978 \uacfc\uc815\uc774 \uc788\uc5c8\ub2e4. \ud544\ub984\uc744 \ub2e4\ub8e8\uace0 \ud604\uc0c1\ud558\uace0 \uc778\ud654\ud574\uc57c \ud588\ub2e4. \uc774 \uce74\ud0c8\ub85c\uadf8\uc5d0\ub294 \uce74\uba54\ub77c\ubfd0 \uc544\ub2c8\ub77c \ud544\ub984, \uc778\ud654\uc9c0, \ud604\uc0c1 \ub3c4\uad6c\uc640 \uad00\ub828 \uc6a9\ud488\uc774 \uc774\uc5b4\uc9c4\ub2e4. \uce74\uba54\ub77c\ub97c \uc911\uc2ec\uc73c\ub85c \uc5ec\ub7ec \uc0c1\ud488\uacfc \uc11c\ube44\uc2a4\uac00 \uc5f0\uacb0\ub418\ub294 \ubaa8\uc2b5\uc744 \ubcfc \uc218 \uc788\ub2e4. \uace0\uac1d\uc740 \uae30\uacc4 \ud558\ub098\ub97c \uac16\ub294 \ub3d9\uc2dc\uc5d0 \uacc4\uc18d \uc18c\ubaa8\ub418\ub294 \uc7ac\ub8cc\ub97c \uc4f0\ub294 \ud65c\ub3d9\uc5d0 \ub4e4\uc5b4\uac14\ub2e4. \uc774\uac83\uc744 \uc624\ub298\uc758 \ubaa8\ub4e0 \uad6c\ub3c5 \uc0ac\uc5c5\uacfc \uac19\ub2e4\uace0 \ud560 \ud544\uc694\ub294 \uc5c6\uc9c0\ub9cc, \uccab \ud310\ub9e4 \ub4a4\uc5d0\ub3c4 \uae30\uc5c5\uacfc \uc774\uc6a9\uc790\uc758 \uad00\uacc4\uac00 \uc774\uc5b4\uc9c4\ub2e4\ub294 \uc810\uc740 \ub208\uc5ec\uaca8\ubcfc \ub9cc\ud558\ub2e4. \uc88b\uc740 \uc21c\uac04\uc744 \ub193\uce58\uac70\ub098 \uc0ac\uc9c4\uc774 \uc81c\ub300\ub85c \ub098\uc624\uc9c0 \uc54a\uc73c\uba74 \uc0ac\ub78c\uc740 \uce74\uba54\ub77c\ub97c \uc4f0\uc9c0 \uc54a\uac8c \ub420 \uc218\ub3c4 \uc788\ub2e4. \ud68c\uc0ac\uac00 \uc0ac\uc6a9\ubc95\uc744 \uac00\ub974\uce58\ub294 \uc77c\uc740 \uce5c\uc808\ud55c \ubd80\ub85d\uc774\uba74\uc11c \uc0c1\ud488\uc744 \uacc4\uc18d \uc0ac\uc6a9\ud558\ub3c4\ub85d \ub3d5\ub294 \uc77c\uc774\uae30\ub3c4 \ud558\ub2e4. \uace0\uac1d\uc758 \uc131\uacf5\uc801\uc778 \uacbd\ud5d8\uacfc \uae30\uc5c5\uc758 \ubc18\ubcf5 \ud310\ub9e4\uac00 \uac19\uc740 \ubc29\ud5a5\uc744 \ud5a5\ud560 \uc218 \uc788\uc5c8\ub2e4. \uce74\ud0c8\ub85c\uadf8\ub294 \ubb34\uc5c7\uc744 \ud558\ub77c\ub294 \uc9c0\uc2dc\ubfd0 \uc544\ub2c8\ub77c \uc65c \uadf8\ub807\uac8c \ud574\uc57c \ud558\ub294\uc9c0\ub3c4 \uc124\uba85\ud574 \uc654\ub2e4\uace0 \uac15\uc870\ud55c\ub2e4. \uad11\uace0 \ubb38\uad6c\ub97c \uadf8\ub300\ub85c \uc131\uacfc\ub85c \ubc1b\uc544\ub4e4\uc77c \uc218\ub294 \uc5c6\uc9c0\ub9cc, \uc801\uc5b4\ub3c4 \uc0ac\uc6a9\uc790\uc758 \uc5b4\ub824\uc6c0\uc744 \ud310\ub9e4\uc758 \uc911\uc694\ud55c \ubb38\uc81c\ub85c \uc778\uc2dd\ud588\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uc77d\uc744 \uc218 \uc788\ub2e4. \uc0ac\uc9c4\uc744 \ubaa8\ub974\ub294 \uc0ac\ub78c\uc774 \ub298\uc5b4\ub09c\ub2e4\ub294 \uac83\uc740 \uc548\ub0b4\uc758 \ud544\uc694\ub3c4 \ucee4\uc9c4\ub2e4\ub294 \ub73b\uc774\uc5c8\ub2e4. 1914\ub144 5\uc6d4 1\uc77c \uc774\ud6c4 \ucf54\ub2e5\uc774\ub098 \ube0c\ub77c\uc6b0\ub2c8\ub97c \uad6c\ub9e4\ud558\ub294 \uc0ac\ub78c\uc5d0\uac8c \u300aKodakery\u300b\ub77c\ub294 \uc7a1\uc9c0\ub97c 1\ub144 \ub3d9\uc548 \ubb34\ub8cc\ub85c \ubcf4\ub0b4\uaca0\ub2e4\ub294 \uc548\ub0b4\ub3c4 \uc788\ub2e4. \uce74\ud0c8\ub85c\uadf8\ub294 \uc774\ub97c \ub9e4\ub2ec \uc0ac\uc9c4 \uc2e4\ub825\uc744 \ub3d5\ub294 \uc791\uc740 \uc7a1\uc9c0\ub85c \uc18c\uac1c\ud55c\ub2e4. \uacc4\uc18d \ubc1b\uc544 \ubcf4\ub824\uba74 \ubcc4\ub3c4\ub85c \uad6c\ub3c5\ud560 \uc218 \uc788\ub2e4\ub294 \uc870\uac74\ub3c4 \ubd99\uc5c8\ub2e4. \ud55c \ubc88 \uac74\ub124\ub294 \uc124\uba85\uc11c\uc640 \uc815\uae30\uc801\uc73c\ub85c \ub3c4\ucc29\ud558\ub294 \uc7a1\uc9c0\ub294 \ub2e4\ub978 \uc5ed\ud560\uc744 \ud55c\ub2e4. \uc7a1\uc9c0\uc5d0\ub294 \uc0c8\ub85c\uc6b4 \ucd2c\uc601 \uc544\uc774\ub514\uc5b4\ub97c \uc18c\uac1c\ud558\uace0 \uc5b4\ub824\uc6b4 \uc810\uc744 \ub2e4\uc2dc \uc124\uba85\ud560 \uae30\ud68c\uac00 \uc788\ub2e4. \uad6c\ub9e4\uac00 \ub05d\ub09c \ub4a4\uc5d0\ub3c4 \uace0\uac1d\uc758 \ucc45\uc0c1 \uc704\uc5d0 \ud68c\uc0ac\uac00 \ub9cc\ub4e0 \uc774\uc57c\uae30\uac00 \ucc3e\uc544\uc624\ub294 \uac83\uc774\ub2e4. \uc0c1\ud488 \uc124\uba85\uc774 \ud558\ub098\uc758 \uc791\uc740 \ub3c5\uc11c \uacbd\ud5d8\uc73c\ub85c \uc774\uc5b4\uc84c\ub2e4. \uce74\ud0c8\ub85c\uadf8\ub97c \ubcf4\uba74 \uc0ac\uc9c4\uc744 \ucc0d\ub294 \uc77c\uc774 \uc5b4\ub5a4 \uc990\uac70\uc6c0\uc73c\ub85c \uc81c\uc2dc\ub418\ub294\uc9c0\ub3c4 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \uc5ec\ud589\uacfc \uac00\uc871, \uc791\uc740 \uc77c\uc0c1\uc758 \uc7a5\uba74\uc744 \ub0a8\uae30\uace0 \uc2f6\uc740 \ub9c8\uc74c\uc774 \uae30\uad6c\uc640 \uc6a9\ud488\uc744 \uc18c\uac1c\ud558\ub294 \ubb38\uc7a5 \uc0ac\uc774\uc5d0 \uc788\ub2e4. \uce74\uba54\ub77c\uc758 \uc5ed\uc0ac\uc5d0\ub294 \ub80c\uc988\uc640 \uc154\ud130\uc758 \ubc1c\uc804\ubfd0 \uc544\ub2c8\ub77c \ubb34\uc5c7\uc744 \uae30\uc5b5\ud558\uace0 \uc2f6\uc5c8\ub294\uac00\ub77c\ub294 \uc9c8\ubb38\ub3c4 \ub4e4\uc5b4 \uc788\ub2e4. \ub2e4\ub9cc \uce74\ud0c8\ub85c\uadf8\uac00 \uc57d\uc18d\ud558\ub294 \uc26c\uc6c0\uacfc \uc2e4\uc81c \uc0ac\uc6a9\uc790\uc758 \uacbd\ud5d8\uc740 \uac19\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \uce74\uba54\ub77c\ub97c \uc0b4 \uc218 \uc788\uc5c8\ub358 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \ud310\ub9e4 \uc790\ub8cc\uac00 \ubcf4\uc5ec \uc8fc\ub294 \uac83\uc740 \ub2f9\uc2dc \uc0ac\ud68c \uc804\uccb4\uc758 \uc644\uc804\ud55c \ubaa8\uc2b5\ubcf4\ub2e4 \uae30\uc5c5\uc774 \ub113\ud788\uace0 \uc2f6\uc5c8\ub358 \uace0\uac1d\uc758 \uc138\uacc4\uc5d0 \uac00\uae5d\ub2e4. \uadf8 \ucc28\uc774\ub97c \uc54c\uace0 \uc77d\uc73c\uba74 \uad11\uace0\ub3c4 \uc88b\uc740 \uc5ed\uc0ac \uc790\ub8cc\uac00 \ub41c\ub2e4. \ucf54\ub2e5\uc758 \uc774 \uc778\uc1c4\ubb3c\uc5d0\uc11c \ud765\ubbf8\ub85c\uc6b4 \uac83\uc740 \uce74\uba54\ub77c\ub97c \uc544\uc8fc \uac04\ub2e8\ud55c \ubb3c\uac74\uc73c\ub85c \ubcf4\uc774\uac8c \ud558\ub824\uba74\uc11c\ub3c4 \ub9ce\uc740 \uc124\uba85\uc744 \uc81c\uacf5\ud55c\ub2e4\ub294 \uc810\uc774\ub2e4. \uc27d\ub2e4\ub294 \ub9d0\uc774 \uc544\ubb34\uac83\ub3c4 \ubc30\uc6b8 \ud544\uc694\uac00 \uc5c6\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc0ac\uc6a9\uc790\uac00 \uc791\uc740 \uc2e4\ud328\ub97c \ub118\uae30\uace0 \ub2e4\uc74c \uc0ac\uc9c4\uc744 \ucc0d\uac8c \ub3d5\ub294 \uc77c\uc774 \ud568\uaed8 \ud544\uc694\ud588\ub2e4. \uc0ac\uc9c4 \uc18d \ube0c\ub77c\uc6b0\ub2c8\ub97c \ub2e4\uc2dc \ubcf4\uba74 \ub2e8\uc21c\ud55c \uc0c1\uc790 \ub4a4\uc5d0 \uc124\uba85\uc11c\uc640 \uc7a1\uc9c0, \ud544\ub984\uacfc \uc778\ud654\uc9c0, \ud310\ub9e4\uc810\uc774 \ub530\ub77c \ub098\uc628\ub2e4. \uae30\uc5c5\uc740 \ubb3c\uac74 \ud558\ub098\ub97c \ub9cc\ub4e4\uc9c0\ub9cc \uc0ac\ub78c\uc740 \uadf8\uac83\uc744 \uc0ac\uc6a9\ud558\ub294 \uc2dc\uac04\uc744 \uc0b4\uc544\uac04\ub2e4. \uc88b\uc740 \uc0c1\ud488\uc744 \uc774\ud574\ud558\ub824\uba74 \uadf8 \uc2dc\uac04\uc774 \uc5b4\ub5bb\uac8c \uc900\ube44\ub418\uc5c8\ub294\uc9c0\ub3c4 \ubcfc \ud544\uc694\uac00 \uc788\ub2e4."}, {"id": "lego-first-wheels", "title": "\ub808\uace0 \ube14\ub85d\uc774 \uad74\ub7ec\uac00\uae30 \uc2dc\uc791\ud55c \ub0a0", "summary": "\ubcbd\uacfc \uc9d1\uc744 \uc313\ub358 \ube14\ub85d\uc5d0 \ubc14\ud034\uac00 \ubd99\uc5c8\uc2b5\ub2c8\ub2e4. \uc6c0\uc9c1\uc77c \uc218 \uc788\ub2e4\ub294 \uac83\uc740 \ub180\uc774\uc5d0 \uc5b4\ub5a4 \ubcc0\ud654\ub97c \uc8fc\uc5c8\uc744\uae4c\uc694?", "category": "companies", "category_title": "Companies", "subcategory": "Technology", "url": "stories/lego-first-wheels/index.html", "image": "media/lego-first-wheels.jpg", "alt": "\ube14\ub85d \uc7a5\ub09c\uac10 \uc790\ub3d9\ucc28\uc640 \uc791\uc740 \ubc14\ud034\ub97c \uadf8\ub9b0 AI \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\ub808\uace0 \ube14\ub85d\uc774 \uad74\ub7ec\uac00\uae30 \uc2dc\uc791\ud55c \ub0a0 \uc791\uc740 \ubc14\ud034 \ud558\ub098\uac00 \ubc14\uafbc \ub180\uc774\uc758 \uc6c0\uc9c1\uc784 \ubcbd\uacfc \uc9d1\uc744 \uc313\ub358 \ube14\ub85d\uc5d0 \ubc14\ud034\uac00 \ubd99\uc5c8\uc2b5\ub2c8\ub2e4. \uc6c0\uc9c1\uc77c \uc218 \uc788\ub2e4\ub294 \uac83\uc740 \ub180\uc774\uc5d0 \uc5b4\ub5a4 \ubcc0\ud654\ub97c \uc8fc\uc5c8\uc744\uae4c\uc694? Technology \uae30\uc5c5 \ube14\ub85d\uc73c\ub85c \uc790\ub3d9\ucc28\ub97c \ub9cc\ub4e4\uc5c8\ub294\ub370 \ubc14\ud034\uac00 \uc5c6\ub2e4\uba74 \uc5b4\ub5bb\uac8c \ub420\uae4c. \ubaa8\uc591\uc740 \uc790\ub3d9\ucc28\uc9c0\ub9cc \uc6c0\uc9c1\uc774\ub824\uba74 \ubc14\ub2e5 \uc704\ub85c \ubc00\uac70\ub098 \uc190\uc73c\ub85c \ub4e4\uc5b4 \uc62e\uaca8\uc57c \ud55c\ub2e4. \uc9c0\uae08\uc740 \ub2f9\uc5f0\ud558\uac8c \ub290\uaef4\uc9c0\ub294 \ub808\uace0\uc758 \ubc14\ud034\ub3c4 \ucc98\uc74c\ubd80\ud130 \uc788\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub808\uace0 \uacf5\uc2dd \uc5f0\ud601\uc740 1950\ub144\ub300 \ub9d0, \ube14\ub85d\uc5d0 \ub9de\ub294 \ubc14\ud034\ub97c \ub9cc\ub4e4\uae30 \uc704\ud574 \uc5ec\ub7ec \uc0ac\ub78c\uc774 \uc124\uacc4\ub97c \uace0\ubbfc\ud558\ub358 \uacfc\uc815\uc744 \uc18c\uac1c\ud55c\ub2e4. \uc791\uc740 \uc6d0 \ud558\ub098\ub97c \ubd99\uc774\uba74 \ub420 \uac83 \uac19\uc9c0\ub9cc, \ube14\ub85d\uc758 \uc138\uacc4\uc5d0\uc11c\ub294 \uadf8 \uc6d0\uc744 \uc5b4\ub514\uc5d0 \uc5b4\ub5bb\uac8c \uc5f0\uacb0\ud560\uc9c0\uac00 \ubb38\uc81c\uc600\ub2e4. \uacf5\uc2dd \uc5f0\ud601\uc5d0 \ub530\ub974\uba74 \uac1c\ubc1c \ubd80\uc11c\uc758 \ud06c\ub204\ub4dc \ubb04\ub808\ub974 \ud06c\ub9ac\uc2a4\ud150\uc13c\uc740 1958\ub144\uc5d0 \ubc14\ud034\uc758 \ubaa8\uc2b5\uc744 \uc2a4\ucf00\uce58\ud588\ub2e4. \ucc98\uc74c\uc5d0\ub294 \ubc14\ud034\ub97c \ube14\ub85d \ub450 \uac1c \uc0ac\uc774\uc5d0 \ub450\ub824 \ud588\uc9c0\ub9cc, \uadf8 \ubc29\uc2dd\uc740 \uc81c\ub300\ub85c \uc791\ub3d9\ud558\uc9c0 \uc54a\uc558\ub2e4. \uadf8 \ub4a4\uc758 \ud574\uacb0\ucc45\uc5d0\ub294 \ube14\ub85d\uacfc \uae08\uc18d \ucd95, \ubc14\ud034 \uc911\uc2ec\ubd80\uc640 \uace0\ubb34 \ud0c0\uc774\uc5b4\uac00 \ud568\uaed8 \ub4e4\uc5b4\uac14\ub2e4. \ucd95\uc744 \ubc1b\uc544 \uc8fc\ub294 \uad6c\uba4d\uc774 \uc788\ub294 \ube14\ub85d\uacfc \uc5f0\uacb0\ud558\ub294 \ubc29\uc2dd\uc774\uc5c8\ub2e4. \ubc14\ud034\ub9cc \ub530\ub85c \uc798 \uad74\ub7ec\uac04\ub2e4\uace0 \ub05d\ub098\ub294 \uc77c\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc774\ubbf8 \uc788\ub358 \ube14\ub85d\uacfc \ud568\uaed8 \uc4f8 \uc218 \uc788\uc5b4\uc57c \ud588\ub2e4. \uc0c8 \ubd80\ud488 \ud558\ub098\uac00 \uae30\uc874 \ub180\uc774\uc758 \uc57d\uc18d \uc548\uc73c\ub85c \ub4e4\uc5b4\uac00\ub294 \uacfc\uc815\uc774\uc5c8\ub358 \uac83\uc774\ub2e4. \uc774 \ubc14\ud034\ub294 \uc218\uc815\uc744 \uac70\uccd0 1962\ub144\uc5d0 \ucd9c\uc2dc\ub418\uc5c8\ub2e4. \ub808\uace0\ub294 \uac19\uc740 \ud574 \ub258\ub978\ubca0\ub974\ud06c \ubc15\ub78c\ud68c\uc5d0\uc11c \ubc14\ud034\ub97c \uc120\ubcf4\uc778 \uc7a5\uba74\ub3c4 \uc5f0\ud601\uc5d0 \ub2f4\uace0 \uc788\ub2e4. \uacf5\uc2dd \uc124\uba85\uc740 \ubc14\ud034\uc758 \ub4f1\uc7a5\uc744 \ube14\ub85d\uc5d0 \uc6c0\uc9c1\uc784\uc774 \ub354\ud574\uc9c4 \uc804\ud658\uc810\uc73c\ub85c \uc18c\uac1c\ud55c\ub2e4. \uc774\ud6c4 1960\ub144\ub300\uc5d0 \ube14\ub85d\uc73c\ub85c \ub9cc\ub4dc\ub294 \uc790\ub3d9\ucc28\uc640 \uae30\ucc28\uac00 \ub354 \ub9ce\uc774 \ub4f1\uc7a5\ud588\ub2e4. \uac00\ub9cc\ud788 \uc138\uc6cc \ub450\ub358 \ubaa8\uc591\uc774 \uad74\ub7ec\uac00\uba74 \ub180\uc774\uc758 \uc9c8\ubb38\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \ubb34\uc5c7\uc744 \ub9cc\ub4e4\uae4c\uc5d0 \ub354\ud574, \uc5b4\ub514\ub85c \uc6c0\uc9c1\uc77c\uae4c\ub97c \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \uac19\uc740 \ube14\ub85d\uc774 \ubc14\ud034 \uc704\uc5d0\uc11c\ub294 \ub2e4\ub978 \uc5ed\ud560\uc744 \ub9e1\ub294\ub2e4. \uc790\ub3d9\ucc28\uc758 \uac89\ubaa8\uc591\uc5d0 \ub3d9\uadf8\ub780 \ubd80\ud488\uc744 \ubd99\uc778\ub2e4\uace0 \ubaa8\ub450 \uc798 \uad74\ub7ec\uac00\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubc14\ud034\uac00 \ub3c4\ub294 \ubd80\ubd84\uacfc \ucc28\uccb4\ub97c \ubc1b\uce58\ub294 \ubd80\ubd84\uc758 \uad00\uacc4\uac00 \ub9de\uc544\uc57c \ud55c\ub2e4. \ub808\uace0 \uc5f0\ud601\uc5d0 \ub098\uc624\ub294 \uae08\uc18d \ucd95\uacfc \uad6c\uba4d\uc774 \uc788\ub294 \ube14\ub85d, \uc911\uc2ec\ubd80\uc640 \uace0\ubb34 \ud0c0\uc774\uc5b4\ub294 \uc774 \ubb38\uc81c\ub97c \uc11c\ub85c \ub098\ub204\uc5b4 \ub9e1\ub294 \uad6c\uc131\uc73c\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \ud558\ub098\uc758 \ubc14\ud034\uac00 \uc0ac\uc2e4\uc740 \uc5ec\ub7ec \ubd80\ud488\uc758 \uad00\uacc4\uc600\ub358 \uc148\uc774\ub2e4. \ucd95\uc774 \ubc14\ud034\ub97c \uc5b4\ub5a4 \uc704\uce58\uc5d0 \ub450\ub294\uc9c0, \ucc28\uccb4\uac00 \uc6c0\uc9c1\uc774\ub294 \ub3d9\uc548 \ubd80\ud488\uc774 \uc11c\ub85c \uc5b4\ub5bb\uac8c \ub9cc\ub098\ub294\uc9c0 \uc0dd\uac01\ud574 \ubcf4\uc790. \uc815\ud655\ud55c \uc81c\uc791 \uce58\uc218\ub97c \ubab0\ub77c\ub3c4 \uc5f0\uacb0\uacfc \ud68c\uc804\uc774\ub77c\ub294 \ub450 \uac00\uc9c0 \uc694\uad6c\ub294 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \ub2e8\ub2e8\ud788 \ubd99\uc5b4 \uc788\uc5b4\uc57c \ud558\ub294 \ube14\ub85d\uc758 \uc131\uc9c8\uacfc \uc790\uc720\ub86d\uac8c \ub3cc\uc544\uc57c \ud558\ub294 \ubc14\ud034\uc758 \uc131\uc9c8\uc744 \uac19\uc740 \uc7a5\ub09c\uac10 \uc548\uc5d0 \ub9c8\ub828\ud574\uc57c \ud588\ub2e4. \ucc98\uc74c\uc5d0 \ubc14\ud034\ub97c \ube14\ub85d \ub450 \uac1c \uc0ac\uc774\uc5d0 \ub193\uc73c\ub824 \ud588\ub2e4\ub294 \uae30\ub85d\uc740 \uc644\uc131\ud488\ub9cc \ubcf4\uace0\ub294 \uc54c\uae30 \uc5b4\ub824\uc6b4 \uc815\ubcf4\ub2e4. \ub098\uc911\uc758 \ub2f5\uc744 \uc54c\uace0 \ubcf4\uba74 \uc26c\uc6cc \ubcf4\uc774\ub294 \ubb38\uc81c\ub3c4 \uc2e4\uc81c\ub85c\ub294 \uc5ec\ub7ec \ubc30\uce58\ub97c \uc2dc\ud5d8\ud558\uba70 \ud480\uc5c8\uc744 \uc218 \uc788\ub2e4. \ucc98\uc74c\uc758 \uad6c\uc0c1\uacfc \ucd5c\uc885 \uc81c\ud488\uc744 \ube44\uad50\ud558\uba74 \uc81c\ud488 \uac1c\ubc1c\uc744 \ud55c \ubc88\uc758 \ubc88\ub729\uc784\ubcf4\ub2e4 \uc218\uc815\uc758 \uacfc\uc815\uc73c\ub85c \uc77d\uac8c \ub41c\ub2e4. \uc774 \uc790\ub8cc\uac00 \ubaa8\ub4e0 \uc2dc\ud5d8\uc758 \uc138\ubd80\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub807\uc9c0\ub9cc \uacf5\uc2dd \uc5f0\ud601\uc5d0 \uc2a4\ucf00\uce58\uc640 \uc791\ub3d9\ud558\uc9c0 \uc54a\uc740 \ubc29\uc548\uc774 \ud568\uaed8 \uc18c\uac1c\ub41c\ub2e4\ub294 \uc810\ub9cc\uc73c\ub85c\ub3c4 \uc758\ubbf8\uac00 \uc788\ub2e4. \uae30\uc5c5\uc758 \uc5ed\uc0ac\ub97c \ub298 \uc131\uacf5\ud55c \uc81c\ud488\uc758 \ud589\ub82c\ub85c\ub9cc \ubcfc \ud544\uc694\uac00 \uc5c6\uc5b4\uc9c4\ub2e4. \ubb34\uc5c7\uc744 \ub9cc\ub4e4\uc5c8\ub294\uc9c0 \uc606\uc5d0 \ubb34\uc5c7\uc744 \ubc14\uafb8\uc5b4\uc57c \ud588\ub294\uc9c0\ub77c\ub294 \uc9c8\ubb38\uc744 \ub193\uc744 \uc218 \uc788\ub2e4. \ubc14\ud034\ub97c \ucc98\uc74c \ubcf8 \uc0ac\ub78c\uc740 \ubc14\ud034 \uc790\uccb4\ubcf4\ub2e4 \uadf8 \uc704\uc5d0 \ubb34\uc5c7\uc744 \uc5b9\uc744\uc9c0 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uc774\ubbf8 \uc775\uc219\ud55c \ube14\ub85d\uc774 \ucc28\uccb4\uac00 \ub418\uace0 \uc88c\uc11d\uc774 \ub418\uace0 \uc9d0\uce78\uc774 \ub41c\ub2e4. \uc0c8\ub85c \ucd94\uac00\ud55c \ubd80\ud488\uc740 \uc790\uae30 \uc5ed\ud560\ub9cc \ud558\ub098 \ub298\ub9ac\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ub2e4\ub978 \ubd80\ud488\ub4e4\uc774 \ub4e4\uc5b4\uac08 \uc7a5\uba74\ub3c4 \ubc14\uafbc\ub2e4. \ub180\uc774\uc758 \ud655\uc7a5\uc774 \ubb3c\uac74\uc758 \uad00\uacc4\uc5d0\uc11c \uc77c\uc5b4\ub098\ub294 \uc21c\uac04\uc774\ub2e4. \uadf8\ub798\uc11c \uacf5\uc2dd \uc5f0\ud601\uc5d0\uc11c \uc790\ub3d9\ucc28\uc640 \uae30\ucc28\uc758 \ud655\uc7a5\uc774 \uc774\uc5b4\uc9c0\ub294 \uac83\uc740 \uc790\uc5f0\uc2a4\ub7fd\ub2e4. \uc815\uc9c0\ud55c \ubaa8\ud615\uc744 \ub9cc\ub4dc\ub294 \uac83\uacfc \uc6c0\uc9c1\uc774\ub294 \ubaa8\ud615\uc744 \uc0ac\uc6a9\ud558\ub294 \uac83\uc740 \ub2e4\ub978 \uc9c8\ubb38\uc744 \ub0b3\ub294\ub2e4. \uae38\uacfc \uc815\ub958\uc7a5\uc744 \ub9cc\ub4e4\uace0, \ubb34\uc5b8\uac00\ub97c \uc2e3\uace0 \ub0b4\ub9ac\ub294 \uc774\uc57c\uae30\ub97c \ubd99\uc77c \uc218\ub3c4 \uc788\ub2e4. \uc774\ub294 \uc774\uc6a9\uc790\uac00 \ub9cc\ub4e4\uc5b4 \uac08 \uac00\ub2a5\uc131\uc758 \uc608\uc774\uba70 \ub2f9\uc2dc \ubaa8\ub4e0 \uc544\uc774\uac00 \uac19\uc740 \ub180\uc774\ub97c \ud588\ub2e4\ub294 \uae30\ub85d\uc744 \ub73b\ud558\uc9c0 \uc54a\ub294\ub2e4. \ube14\ub85d \ub180\uc774\ub294 \uacb0\ud569\uacfc \ubd84\ub9ac\ub97c \ud1b5\ud574 \ubaa8\uc591\uc744 \ubc14\uafb8\ub294 \ub370 \uac15\uc810\uc774 \uc788\ub2e4. \ubc14\ud034\ub294 \uadf8 \ubaa8\uc591\uc744 \uc2e4\uc81c \uacf5\uac04\uc5d0\uc11c \uc6c0\uc9c1\uc774\ub294 \ub300\uc0c1\uc73c\ub85c \ubc14\uafbc\ub2e4. \uc313\uc740 \ub192\uc774\uc640 \ud3ed\ubfd0 \uc544\ub2c8\ub77c \ubc14\ub2e5\uc5d0\uc11c\uc758 \uc6c0\uc9c1\uc784\ub3c4 \uacbd\ud5d8\ud558\uac8c \ub418\ub294 \uac83\uc774\ub2e4. \ubb34\uc5c7\uc774 \ub354 \ud6cc\ub96d\ud55c \ub180\uc774\uc778\uc9c0 \uc21c\uc11c\ub97c \ub9e4\uae30\uae30\ubcf4\ub2e4 \uc11c\ub85c \ub2e4\ub978 \ud589\ub3d9\uc774 \uac00\ub2a5\ud574\uc84c\ub2e4\ub294 \uc810\uc744 \ubcfc \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uc0c8\ub85c\uc6b4 \ubd80\ud488\uc774 \ub098\uc654\ub2e4\uace0 \ubaa8\ub4e0 \uc81c\ud488\uc774 \uc5b8\uc81c\ub098 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ud638\ud658\ub41c\ub2e4\uace0 \ub113\ud600 \ub9d0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc5f0\ud601\uc774 \uc124\uba85\ud558\ub294 \ub2f9\uc2dc\uc758 \uc5f0\uacb0 \ubc29\uc2dd\uacfc \ucd9c\uc2dc\ub97c \uc0b4\ud3b4\ubcf8\ub2e4. \uc775\uc219\ud55c \uc7a5\ub09c\uac10\uc758 \uc9c4\ud654\ub97c \uc774\ud574\ud558\ub294 \ub370 \uac00\uc7a5 \ub3c4\uc6c0\uc774 \ub418\ub294 \uac83\uc740 \uac70\ub300\ud55c \uacb0\uacfc\ubb3c\ubcf4\ub2e4 \uc791\uc740 \ubd80\ud488 \ud558\ub098\uac00 \uae30\uc874\uc758 \uc57d\uc18d \uc548\uc73c\ub85c \ub4e4\uc5b4\uc624\ub294 \uacfc\uc815\uc744 \ubcf4\ub294 \uc77c\uc77c \ub54c\ub3c4 \uc788\ub2e4. \uc644\uc131\ub41c \uc7a5\ub09c\uac10\uc744 \ubcf4\uba74 \uc804\uccb4\uc758 \uba4b\uc9c4 \ubaa8\uc591\ubd80\ud130 \ubcf4\uc778\ub2e4. \ud558\uc9c0\ub9cc \uadf8 \ubaa8\uc2b5\uc744 \uac00\ub2a5\ud558\uac8c \ud55c \ubcc0\ud654\uac00 \uc544\uc8fc \uc791\uc740 \ubd80\ud488\uc5d0 \ub4e4\uc5b4 \uc788\ub294 \uacbd\uc6b0\ub3c4 \uc788\ub2e4. \ubc14\ud034\ub294 \ub208\uc5d0 \uc798 \ub744\uba74\uc11c\ub3c4 \ub108\ubb34 \uc775\uc219\ud574\uc838 \ucd9c\ubc1c\uc810\uc744 \uc78a\uae30 \uc26c\uc6b4 \ubd80\ud488\uc774\ub2e4. \ub808\uace0\uc758 \uc5f0\ud601\uc744 \uc77d\uace0 \ub098\uba74 \ubc14\ud034\ub97c \ub2e8\uc21c\ud788 \ub3d9\uadf8\ub780 \uc7a5\uc2dd\uc73c\ub85c \ubcf4\uae30\ub294 \uc5b4\ub835\ub2e4. \uc798 \ub3cc\uc544\uac00\uba74\uc11c\ub3c4 \ub2e4\ub978 \ubd80\ud488\uacfc \ud568\uaed8 \uc791\ub3d9\ud574\uc57c \ud588\ub358, \uc791\uc740 \uc124\uacc4 \ubb38\uc81c\uc758 \ub2f5\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \ube14\ub85d \uc790\ub3d9\ucc28\ub97c \uad74\ub824 \ubcf4\uac8c \ub41c\ub2e4\uba74 \ucc28\uccb4 \uc544\ub798\ub3c4 \ud55c\ubc88 \ubcf4\uc790. \uc791\uc740 \uac80\uc740 \ubc14\ud034\uac00 \ubd99\uc740 \uc790\ub9ac\uc5d0\uc11c, \uc313\ub294 \ub180\uc774\ub294 \uc6c0\uc9c1\uc774\ub294 \ub180\uc774\ub85c \ud55c \uac78\uc74c \ub354 \ub098\uc544\uac14\ub2e4."}, {"id": "lego-play-well", "title": "\ub808\uace0\ub77c\ub294 \uc774\ub984\uc740 \uc6d0\ub798 \ubb34\uc2a8 \ub73b\uc77c\uae4c", "summary": "\uc775\uc219\ud55c \ub124 \uae00\uc790 \uc548\uc5d0 \ub374\ub9c8\ud06c\uc5b4\ub85c \ub180\uc774\uc5d0 \uad00\ud55c \ub73b\uc774 \uc228\uc5b4 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub984\ubd80\ud130 \uba3c\uc800 \ub4e4\uc5ec\ub2e4\ubcf4\ub294 \ub808\uace0 \uc774\uc57c\uae30.", "category": "companies", "category_title": "Companies", "subcategory": "Technology", "url": "stories/lego-play-well/index.html", "image": "media/lego-play-well.jpg", "alt": "\ub808\uace0\ub77c\ub294 \uc774\ub984\uc740 \uc6d0\ub798 \ubb34\uc2a8 \ub73b\uc77c\uae4c \u2014 \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\ub808\uace0\ub77c\ub294 \uc774\ub984\uc740 \uc6d0\ub798 \ubb34\uc2a8 \ub73b\uc77c\uae4c \uc791\uc740 \ube14\ub85d\ubcf4\ub2e4 \uba3c\uc800 \uc788\uc5c8\ub358 \u2018\uc798 \ub180\uc790\u2019\ub77c\ub294 \ub9d0 \uc775\uc219\ud55c \ub124 \uae00\uc790 \uc548\uc5d0 \ub374\ub9c8\ud06c\uc5b4\ub85c \ub180\uc774\uc5d0 \uad00\ud55c \ub73b\uc774 \uc228\uc5b4 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub984\ubd80\ud130 \uba3c\uc800 \ub4e4\uc5ec\ub2e4\ubcf4\ub294 \ub808\uace0 \uc774\uc57c\uae30. Technology \uae30\uc5c5 \ub808\uace0 \uc0c1\uc790\ub97c \uc5f4\uba74 \uba3c\uc800 \uc124\uba85\uc11c\ub97c \ucc3e\ub294 \uc0ac\ub78c\uc774 \uc788\ub2e4. \ubc18\ub300\ub85c \ubd80\ud488\ubd80\ud130 \uc3df\uc544 \ub193\uace0 \ub9c8\uc74c\ub300\ub85c \uc313\ub294 \uc0ac\ub78c\ub3c4 \uc788\ub2e4. \uac19\uc740 \ube14\ub85d\uc744 \ubc1b\uc544\ub3c4 \ub178\ub294 \ubc29\ubc95\uc740 \uc870\uae08\uc529 \ub2e4\ub974\ub2e4. \uadf8\ub7f0\ub370 \ub808\uace0\ub77c\ub294 \uc774\ub984 \uc790\uccb4\uc5d0\ub3c4 \ub180\uc774\uc5d0 \uad00\ud55c \ub9d0\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \ub374\ub9c8\ud06c\uc5b4 \u2018leg godt\u2019\uc5d0\uc11c \uac00\uc838\uc628 \uc774\ub984\uc73c\ub85c, \ud754\ud788 \u2018\uc798 \ub180\uc544\ub77c\u2019 \ub610\ub294 \u2018\uc798 \ub180\uc790\u2019\ub77c\ub294 \ub73b\uc73c\ub85c \ud480\uc774\ub41c\ub2e4. \ubcf5\uc7a1\ud55c \uc6b0\uc8fc\uc120\uc774\ub098 \ucee4\ub2e4\ub780 \uc131\uc744 \ub9cc\ub4e4\uae30 \uc804\uc5d0, \uc774\ub984\uc774 \uba3c\uc800 \uac74\ub124\ub294 \ub9d0\uc740 \uc758\uc678\ub85c \uac04\ub2e8\ud588\ub358 \uc148\uc774\ub2e4. \ub808\uace0\uc758 \ucc3d\uc5c5\uc790 \uc62c\ub808 \ud0a4\ub974\ud06c \ud06c\ub9ac\uc2a4\ud2f0\uc548\uc13c\uc740 \ub374\ub9c8\ud06c \ube4c\ub8ec\uc5d0\uc11c \ubaa9\uacf5 \uc77c\uc744 \ud558\uba70 \uc7a5\ub09c\uac10\uc744 \ub9cc\ub4e4\uc5c8\ub2e4. \ucd08\uae30\uc758 \uc81c\ud488\uc740 \uc624\ub298\ub0a0 \uc6b0\ub9ac\uac00 \ub5a0\uc62c\ub9ac\ub294 \ud50c\ub77c\uc2a4\ud2f1 \ube14\ub85d\ub9cc\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c4 \uc138\uacc4\uc640 \ub2ec\ub790\ub2e4. \ub098\ubb34 \uc7a5\ub09c\uac10\uc774 \uc788\uc5c8\ub2e4. \ub808\uace0\ub77c\ub294 \uc774\ub984\uc740 \uc624\ub298\ub0a0\uc758 \ud50c\ub77c\uc2a4\ud2f1 \ube14\ub85d \ubaa8\uc591\uc744 \ubcf4\uace0 \uadf8 \ud2b9\uc9d5\uc5d0 \ub9de\ucd94\uc5b4 \uc9c0\uc740 \uac83\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uacf5\uc2dd \uc5f0\ud601\uc740 \ubaa9\uc7ac \uc7a5\ub09c\uac10\uc744 \ub9cc\ub4e4\ub358 \uc2dc\uae30\uc5d0 \ub374\ub9c8\ud06c\uc5b4 LEG GODT\ub97c \uc870\ud569\ud574 \uc774\ub984\uc744 \uc815\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub180\uc774\uc5d0 \uad00\ud55c \uc774\ub984\uc744 \uba3c\uc800 \uac16\uace0, \uadf8 \uc544\ub798\uc5d0\uc11c \uc7a5\ub09c\uac10\uc774 \ub2ec\ub77c\uc838 \uac04 \uac83\uc774\ub2e4. \uc774 \uc0ac\uc2e4\uc744 \uc54c\uba74 \uc775\uc219\ud55c \uc774\ub984\uc774 \uc870\uae08 \uc0c8\ub86d\uac8c \ub4e4\ub9b0\ub2e4. \uc6b0\ub9ac\ub294 \ubcf4\ud1b5 \ub808\uace0\ub97c \ubcf4\uba74 \ubc14\ub85c \ube14\ub85d\uc744 \ub5a0\uc62c\ub9b0\ub2e4. \ud558\uc9c0\ub9cc \uc774\ub984\uc774 \uc0dd\uacbc\uc744 \ub54c\ubd80\ud130 \uc9c0\uae08\uc758 \ubaa8\ub4e0 \uc81c\ud488\uc774 \uc815\ud574\uc838 \uc788\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ub7ab\ub3d9\uc548 \uc4f0\uc778 \uc774\ub984\uc5d0\ub294 \uadf8\ub7f0 \uc2dc\uac04\uc774 \uc811\ud600 \uc788\ub2e4. \uc624\ub298\uc758 \ubb3c\uac74\ub9cc \ubcf4\uace0 \uacfc\uac70\uae4c\uc9c0 \uac19\uc740 \ubaa8\uc2b5\uc774\uc5c8\uc744 \uac83\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uba74 \ub193\uce58\ub294 \ubd80\ubd84\uc774\ub2e4. \ub808\uace0\uc758 \uacbd\uc6b0\uc5d0\ub294 \uc774\ub984\uc774 \uc7a5\ub09c\uac10\uc758 \uc7ac\ub8cc \ubcc0\ud654\ubcf4\ub2e4 \uc624\ub798 \ub0a8\uc558\ub2e4. \uc9c0\uae08\uc758 \ub808\uace0\ub97c \ub5a0\uc62c\ub9ac\uba74 \uc11c\ub85c \ub9de\ubb3c\ub9ac\ub294 \ub3cc\uae30\uc640 \uad6c\uba4d\uc774 \uc0dd\uac01\ub09c\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \ube14\ub85d \ud55c \uac1c\uc758 \ubaa8\uc591\ub9cc\uc774 \uc544\ub2c8\ub77c, \uc5ec\ub7ec \uac1c\uac00 \uc5f0\uacb0\ub41c\ub2e4\ub294 \uc810\uc774\ub2e4. \ud63c\uc790 \uc788\uc744 \ub54c\ub294 \uc791\uc740 \ubd80\ud488\uc774\uc9c0\ub9cc \ub2e4\ub978 \ubd80\ud488\uc744 \ub9cc\ub098\uba74 \uc9d1\ub3c4 \ub418\uace0 \uc790\ub3d9\ucc28\ub3c4 \ub41c\ub2e4. \ubb3c\ub860 \uc544\ubb34 \uc870\ud569\uc774\ub098 \ub2e4 \uc798 \ub9de\ub294\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc81c\ud488\uc5d0 \ub530\ub77c \uc4f0\ub294 \ubc29\ubc95\uacfc \ud638\ud658 \ubc94\uc704\uac00 \ub2e4\ub974\ub2e4. \uadf8\ub798\ub3c4 \ub9ce\uc740 \ube14\ub85d\uc744 \ub2e4\uc2dc \ub5bc\uace0 \uc0c8\ub85c \uc870\ub9bd\ud560 \uc218 \uc788\ub2e4\ub294 \uc810\uc740 \uc774 \ub180\uc774\uc758 \ud070 \ud2b9\uc9d5\uc774\ub2e4. \uc124\uba85\uc11c\ub300\ub85c \uc644\uc131\ud558\ub294 \uc7ac\ubbf8\uc640, \uc644\uc131\ud55c \uac83\uc744 \ub2e4\uc2dc \ubc14\uafb8\ub294 \uc7ac\ubbf8\uac00 \ud568\uaed8 \uc788\ub2e4. \uc9c0\ubd95\uc744 \ub5bc\uc5b4 \ub2e4\ub978 \uacf3\uc5d0 \ubd99\uc5ec \ubcf4\uac70\ub098 \ub0a8\uc740 \ubd80\ud488\uc73c\ub85c \ucc98\uc74c \uacc4\ud68d\uc5d0 \uc5c6\ub358 \ubb3c\uac74\uc744 \ub9cc\ub4e4 \uc218\ub3c4 \uc788\ub2e4. \uc0c1\uc790\uc5d0 \uadf8\ub824\uc9c4 \ubaa8\uc2b5\uc774 \ub180\uc774\uc758 \uc720\uc77c\ud55c \uacb0\ub9d0\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub798\uc11c \u2018\uc798 \ub180\uc790\u2019\ub77c\ub294 \uc774\ub984\uc740 \uaf64 \ub113\uac8c \ub4e4\ub9b0\ub2e4. \uc5ec\uae30\uc11c \uc798\ud55c\ub2e4\ub294 \uac83\uc744 \ub204\uac00 \ub354 \ube68\ub9ac \uc644\uc131\ud588\ub294\uc9c0\ub85c\ub9cc \uc77d\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \uc774\uac83\uc740 \uc774\ub984\uc744 \uc624\ub298\uc758 \uc6b0\ub9ac\uac00 \uc990\uae30\ub294 \ubc29\uc2dd\uc774\ub2e4. \ucc3d\uc5c5\uc790\uac00 \ubaa8\ub4e0 \uc0ac\uc6a9\uc790\uc758 \ub180\uc774\ub97c \ubbf8\ub9ac \uc0c1\uc0c1\ud588\ub2e4\uace0 \ub9d0\ud558\ub824\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubaa9\uc7ac \uc7a5\ub09c\uac10\uacfc \uc624\ub298\ub0a0\uc758 \uc870\ub9bd \ube14\ub85d\uc740 \uc7ac\ub8cc\uc640 \uc0ac\uc6a9 \uacbd\ud5d8\uc774 \ub2e4\ub974\ub2e4. \uadf8\ub7f0\ub370 \ub180\uc774\ub97c \ub73b\ud558\ub294 \uc774\ub984\uc740 \uadf8 \ubcc0\ud654\ub97c \uac74\ub108 \uc774\uc5b4\uc84c\ub2e4. \ud68c\uc0ac\uac00 \uc5b4\ub5a4 \uc81c\ud488\uc744 \ub9cc\ub4e4\uace0 \uc788\ub294\uc9c0\uc640 \ube0c\ub79c\ub4dc\uac00 \uc5b4\ub5a4 \ub9d0\ub85c \uae30\uc5b5\ub418\ub294\uc9c0\ub294 \uaf2d \uac19\uc740 \uc18d\ub3c4\ub85c \ubc14\ub00c\uc9c0 \uc54a\ub294\ub2e4. \uc774\ub984\uc758 \uc720\ub798\ub294 \uae30\uc5c5\uc758 \ucd9c\ubc1c\uc810\uacfc \uc9c0\uae08\uc758 \ubaa8\uc2b5\uc744 \ub098\ub780\ud788 \ubcf4\uac8c \ud55c\ub2e4. \uc774\ub984\uc744 \ub73b\ud480\uc774\ud558\ub294 \ub370\uc11c \uba48\ucd94\uc9c0 \uc54a\uace0 \uc2e4\uc81c \uc81c\ud488\uc758 \uad00\uacc4\ub97c \ubcf4\uba74 \ub354 \uc7ac\ubbf8\uc788\ub2e4. \ub3cc\uae30\uc640 \uc548\ucabd \ud29c\ube0c\uac00 \ub9de\ubb3c\ub9ac\ub294 \ubc29\uc2dd\uc740 \ubd80\ud488\uc744 \uc5f0\uacb0\ud55c \uc0c1\ud0dc\uc5d0\uc11c \ud615\ud0dc\ub97c \uc720\uc9c0\ud558\ub3c4\ub85d \ub3d5\ub294\ub2e4. \uc644\uc131\ud55c \ub4a4 \ub2e4\uc2dc \ub5bc\uc5b4 \uc4f0\ub294 \uacbd\ud5d8\ub3c4 \uc774\ub7f0 \uacb0\ud569\uc758 \uc131\uc9c8\uacfc \uad00\uacc4\uac00 \uc788\ub2e4. \ub180\uc774\uc5d0 \uad00\ud55c \ub9d0\uacfc \ubb3c\uac74\uc744 \ub2e4\ub8e8\ub294 \uc190\uc758 \uacbd\ud5d8\uc774 \ub9cc\ub098\ub294 \uc9c0\uc810\uc774\ub2e4. \uc124\uba85\uc11c\ub97c \ub530\ub77c \ub9cc\ub4e0 \ubaa8\ud615\uc740 \ud558\ub098\uc758 \ud574\ub2f5\uc774\uc9c0\ub9cc \ubd80\ud488\uc758 \uac00\ub2a5\ud55c \uc4f0\uc784\uc744 \ubaa8\ub450 \uc18c\uc9c4\ud55c \uacb0\uacfc\ub294 \uc544\ub2c8\ub2e4. \ubaa8\uc591\uc744 \ubc14\uafc0 \uc218 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uc644\uc131\uc744 \ub05d\uc774 \uc544\ub2c8\ub77c \ub2e4\uc74c \uc120\ud0dd\uc758 \ucd9c\ubc1c\uc810\uc73c\ub85c \ub9cc\ub4e4 \uc218 \uc788\ub2e4. \uc5b4\ub978\uc774 \uace0\ub978 \uc815\ub2f5\uacfc \ub2e4\ub978 \ubaa8\uc591\uc744 \ub9cc\ub4e4\ub354\ub77c\ub3c4 \ubd80\ud488\ub4e4\uc774 \uc5b4\ub5a4 \ubc29\uc2dd\uc73c\ub85c \uacb0\ud569\ub418\ub294\uc9c0 \uc2dc\ud5d8\ud558\ub294 \uacbd\ud5d8\uc740 \ub0a8\ub294\ub2e4. \uc774\uac83\uc744 \ubaa8\ub4e0 \uc81c\ud488\uc758 \uacf5\uc2dd \uad50\uc721 \ud6a8\uacfc\ub77c\uace0 \ub2e8\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc774\ub984\uc744 \uc624\ub298\uc758 \ub180\uc774\uc5d0 \uc5f0\uacb0\ud574 \uc77d\uc5b4 \ubcf4\ub294 \uad00\uc810\uc774\ub2e4. \uc798 \ub17c\ub2e4\ub294 \ub9d0\uc774 \ube60\ub974\uace0 \uc815\ud655\ud558\uac8c \ubcf5\uc81c\ud55c\ub2e4\ub294 \ub73b\ub9cc\uc740 \uc544\ub2d0 \uc218 \uc788\ub2e4\ub294 \uc0dd\uac01\uc744 \ub3d5\ub294\ub2e4. \uac19\uc740 \ub124 \uae00\uc790\ub97c \uc54c\uace0\ub3c4 \uc0ac\ub78c\ub9c8\ub2e4 \ub2e4\ub978 \ub180\uc774\uc758 \uc7a5\uba74\uc744 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4\ub294 \uc810\uc774 \uc774 \uc774\ub984\uc758 \uc5ec\uc720\ub2e4. \ube0c\ub79c\ub4dc \uc774\ub984\uc744 \ub108\ubb34 \uc790\uc8fc \ubcf4\uba74 \ub73b\uc744 \uc0dd\uac01\ud558\uc9c0 \uc54a\uac8c \ub41c\ub2e4. \uac04\ud310\ucc98\ub7fc \uc54c\uc544\ubcf4\uba74 \ucda9\ubd84\ud558\uae30 \ub54c\ubb38\uc774\ub2e4. \uadf8\ub7f0\ub370 \uac00\ub054 \uadf8 \uc774\ub984\uc744 \ucc98\uc74c \ub4e3\ub294 \ub9d0\ucc98\ub7fc \ud480\uc5b4 \ubcf4\uba74 \ubb3c\uac74\uc758 \ub2e4\ub978 \uba74\uc774 \ubcf4\uc778\ub2e4. \ub808\uace0\ub294 \ub374\ub9c8\ud06c\uc758 \uc791\uc740 \uc791\uc5c5\uc7a5\uc5d0\uc11c \ucd9c\ubc1c\ud55c \uc7a5\ub09c\uac10 \ud68c\uc0ac\uc774\uba74\uc11c, \uc9c0\uae08\uc740 \uc5ec\ub7ec \ub098\ub77c\uc758 \uc0ac\ub78c\ub4e4\uc774 \uac01\uc790\uc758 \ubc29\uc2dd\uc73c\ub85c \uac00\uc9c0\uace0 \ub178\ub294 \uc774\ub984\uc774 \ub418\uc5c8\ub2e4. \uadf8 \ubcc0\ud654\ub97c \ub124 \uae00\uc790\ub9cc \ubcf4\uace0 \uc9d0\uc791\ud558\uae30\ub294 \uc5b4\ub835\ub2e4. \ub2e4\uc74c\uc5d0 \ube14\ub85d\uc744 \uc870\ub9bd\ud560 \uc77c\uc774 \uc0dd\uae34\ub2e4\uba74 \uc774\ub984\uc744 \ud55c \ubc88 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc124\uba85\uc11c\uc758 \ub9c8\uc9c0\ub9c9 \uc7a5\uc5d0 \ub3c4\ucc29\ud574\uc57c\ub9cc \ub180\uc774\uac00 \uc644\uc131\ub418\ub294 \uac83\uc740 \uc544\ub2d0\uc9c0\ub3c4 \ubaa8\ub978\ub2e4. \uc791\uc740 \ubd80\ud488 \ud558\ub098\uac00 \ub0a8\uc544\uc11c \uc5c9\ub6b1\ud55c \ubb3c\uac74\uc744 \ub9cc\ub4dc\ub294 \uc21c\uac04\ub3c4 \ucda9\ubd84\ud788 \uc7ac\ubbf8\uc788\ub2e4. \ud68c\uc0ac \uc774\ub984\uc744 \uacf5\ubd80\ud558\ub7ec \uc2dc\uc791\ud55c \uc774\uc57c\uae30\ub294 \uc544\ub2c8\uc5c8\ub294\ub370, \uc774\ub984\uc744 \ud480\uace0 \ub098\ub2c8 \uacb0\uad6d \ub2e4\uc2dc \ub178\ub294 \uc774\uc57c\uae30\ub85c \ub3cc\uc544\uc654\ub2e4. \ub808\uace0\ub77c\ub294 \ub9d0\uc5d0\ub294 \ucc98\uc74c\ubd80\ud130 \uadf8 \ub2e8\uc11c\uac00 \ub4e4\uc5b4 \uc788\uc5c8\ub2e4."}, {"id": "microsoft-dos-open-archive", "title": "\ub9c8\uc774\ud06c\ub85c\uc18c\ud504\ud2b8\uac00 \uc61b \ud504\ub85c\uadf8\ub7a8\uc744 \uacf5\uac1c\ud55c \uae4c\ub2ed", "summary": "\uc61b \uc6b4\uc601\uccb4\uc81c\uc758 \uc124\uacc4 \ub0b4\uc6a9\uc744 \uacf5\uac1c\ud55c \uacf5\uc2dd \uc800\uc7a5\uc18c\uc5d0\uc11c \uc18c\ud504\ud2b8\uc6e8\uc5b4\ub97c \ubcf4\uc874\ud558\ub294 \uc758\ubbf8\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "companies", "category_title": "Companies", "subcategory": "Technology", "url": "stories/microsoft-dos-open-archive/index.html", "image": "media/microsoft-dos-open-archive.png", "alt": "\uc61b \uac1c\uc778\uc6a9 \ucef4\ud4e8\ud130\uc640 \ud50c\ub85c\ud53c \ub514\uc2a4\ud06c, \uc778\uc1c4 \uae30\ub85d\uc744 \ubcf4\uad00 \uc0c1\uc790\uc640 \ud568\uaed8 \uc0b4\ud3b4\ubcf4\ub294 \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\ub9c8\uc774\ud06c\ub85c\uc18c\ud504\ud2b8\uac00 \uc61b \ud504\ub85c\uadf8\ub7a8\uc744 \uacf5\uac1c\ud55c \uae4c\ub2ed MS-DOS\uc758 \uc18c\uc2a4 \ucf54\ub4dc\ub97c \uc5ed\uc0ac \uc790\ub8cc\ub85c \uc77d\ub294 \uc2dc\uac04 \uc61b \uc6b4\uc601\uccb4\uc81c\uc758 \uc124\uacc4 \ub0b4\uc6a9\uc744 \uacf5\uac1c\ud55c \uacf5\uc2dd \uc800\uc7a5\uc18c\uc5d0\uc11c \uc18c\ud504\ud2b8\uc6e8\uc5b4\ub97c \ubcf4\uc874\ud558\ub294 \uc758\ubbf8\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Technology \uae30\uc5c5 \ubc15\ubb3c\uad00\uc5d0\uc11c \uc624\ub798\ub41c \ucef4\ud4e8\ud130\ub97c \ub9cc\ub098\uba74 \ubca0\uc774\uc9c0\uc0c9 \ubcf8\uccb4\uc640 \ucee4\ub2e4\ub780 \ubaa8\ub2c8\ud130\uac00 \uba3c\uc800 \ubcf4\uc778\ub2e4. \ud558\uc9c0\ub9cc \uc804\uc6d0\uc744 \ucf1c\ub3c4 \ub2f9\uc2dc\uc758 \uacbd\ud5d8\uc774 \ubaa8\ub450 \ub3cc\uc544\uc624\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc548\uc5d0\uc11c \uc5b4\ub5a4 \ud504\ub85c\uadf8\ub7a8\uc774 \uc6c0\uc9c1\uc600\ub294\uc9c0, \uadf8 \ud504\ub85c\uadf8\ub7a8\uc774 \uc5b4\ub5a4 \uc0dd\uac01\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc84c\ub294\uc9c0 \uc54c\uc544\uc57c \ucef4\ud4e8\ud130\uc758 \uacfc\uac70\uac00 \uc870\uae08 \ub354 \uc120\uba85\ud574\uc9c4\ub2e4. \ub9c8\uc774\ud06c\ub85c\uc18c\ud504\ud2b8\ub294 \uacf5\uc2dd GitHub \uc800\uc7a5\uc18c\uc5d0 \ucd08\uae30 MS-DOS\uc758 \uc18c\uc2a4 \ucf54\ub4dc\uc640 \uc77c\ubd80 \uc2e4\ud589 \ud30c\uc77c\uc744 \uacf5\uac1c\ud574 \ub193\uc558\ub2e4. \uc775\uc219\ud558\uc9c0 \uc54a\uc740 \ucf54\ub4dc\uac00 \uc794\ub729 \uc788\ub294 \uacf5\uac04\uc774\uc9c0\ub9cc, \ud504\ub85c\uadf8\ub798\ubc0d\uc744 \ud558\uc9c0 \uc54a\ub294 \uc0ac\ub78c\ub3c4 \uadf8 \uacf5\uac1c\uc758 \uc758\ubbf8\ub294 \uc77d\uc744 \uc218 \uc788\ub2e4. \uae30\uacc4\uc758 \uac89\ubaa8\uc2b5 \uc606\uc5d0 \uc791\ub3d9 \ubc29\uc2dd\uc758 \uae30\ub85d\uc744 \ub193\uc740 \uc148\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \uc18c\uc2a4 \ucf54\ub4dc\ub294 \uc0ac\ub78c\uc774 \ud504\ub85c\uadf8\ub7a8\uc744 \ub9cc\ub4e4 \ub54c \uc791\uc131\ud558\ub294 \uc9c0\uc2dc\uc758 \uae30\ub85d\uc774\ub2e4. \uc2e4\uc81c\ub85c \uc2e4\ud589\ub418\ub294 \ud30c\uc77c\uacfc\ub294 \ud615\uc2dd\uacfc \uc5ed\ud560\uc774 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uc644\uc131\ub41c \uc74c\uc2dd\uc744 \uba39\ub294 \uac83\uacfc \uc694\ub9ac\uc758 \uc7ac\ub8cc\u00b7\uc21c\uc11c\ub97c \uc77d\ub294 \uc77c\uc774 \ub2e4\ub974\ub4ef, \uc791\ub3d9 \uacb0\uacfc\ub9cc \ubcf4\ub294 \uac83\uacfc \uadf8 \uacb0\uacfc\ub97c \ub9cc\ub4dc\ub294 \ub0b4\uc6a9\uc744 \uc0b4\ud3b4\ubcf4\ub294 \uc77c\ub3c4 \ub2e4\ub974\ub2e4. \ubb3c\ub860 \ucf54\ub4dc\uac00 \uacf5\uac1c\ub418\uc5c8\ub2e4\uace0 \ub204\uad6c\ub098 \uace7\ubc14\ub85c \ubaa8\ub4e0 \ub0b4\uc6a9\uc744 \uc774\ud574\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc61b \uae30\uacc4\uc758 \uad6c\uc870\uc640 \ub2f9\uc2dc\uc758 \ub3c4\uad6c\ub97c \uc54c\uc544\uc57c \uc77d\ud788\ub294 \ubd80\ubd84\ub3c4 \ub9ce\ub2e4. \uadf8\ub798\ub3c4 \uc9c8\ubb38\ud560 \uc218 \uc788\ub294 \uadfc\uac70\uac00 \uc0dd\uae34\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \uc791\ub3d9 \ubc29\uc2dd\uc774 \uc624\uc9c1 \uae30\uc5b5\uc774\ub098 \ud68c\uace0\uc5d0\ub9cc \uc758\uc874\ud558\uc9c0 \uc54a\uac8c \ub418\ub294 \uac83\uc774\ub2e4. \uc6b4\uc601\uccb4\uc81c\ub294 \ub2e4\ub978 \ud504\ub85c\uadf8\ub7a8\uc774 \ucef4\ud4e8\ud130\uc758 \uc7a5\uce58\uc640 \ud30c\uc77c\uc744 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub3c4\ub85d \uae30\ubcf8\uc801\uc778 \uc77c\uc744 \ub9e1\ub294\ub2e4. MS-DOS\ub77c\ub294 \uc774\ub984\uc740 \ucd08\uae30 \uac1c\uc778\uc6a9 \ucef4\ud4e8\ud130\uc758 \uc5ed\uc0ac\uc5d0\uc11c \uc790\uc8fc \ub4f1\uc7a5\ud55c\ub2e4. \uc624\ub298\uc758 \uadf8\ub9bc \uc911\uc2ec \ud654\uba74\uacfc \ub2e4\ub978 \uc2dc\ub300\uc758 \ucef4\ud4e8\ud130 \uc0ac\uc6a9\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \uc774\ub984\uc774\uae30\ub3c4 \ud558\ub2e4. \uc774 \uae00\uc758 \uc911\uc2ec\uc740 \ud2b9\uc815 \uba85\ub839\uc5b4\ub97c \ubc30\uc6b0\ub294 \ub370 \uc788\uc9c0 \uc54a\ub2e4. \uc5b4\ub5a4 \ud504\ub85c\uadf8\ub7a8\uc774 \uc2e4\ud589\ub418\uae30 \uc804\uc5d0 \uadf8 \ubc14\ud0d5\uc744 \ub9c8\ub828\ud558\ub294 \uc18c\ud504\ud2b8\uc6e8\uc5b4\uac00 \ud544\uc694\ud558\ub2e4\ub294 \uc810\uc744 \uc774\ud574\ud558\uba74 \ucda9\ubd84\ud558\ub2e4. \ub208\uc5d0 \uc798 \ub744\ub294 \ubb38\uc11c \uc791\uc131 \ud504\ub85c\uadf8\ub7a8\uc774\ub098 \uac8c\uc784 \uc544\ub798\uc5d0\ub3c4 \uc0ac\uc6a9\uc790\uac00 \uc9c1\uc811 \uc758\uc2dd\ud558\uc9c0 \uc54a\ub294 \uae30\ubcf8 \uc791\uc5c5\uc774 \ub193\uc5ec \uc788\ub2e4. \ud604\uc7ac \uacf5\uc2dd \uc548\ub0b4\ub294 MS-DOS 1.25\uc640 2.0\uc758 \uc6d0\ubcf8 \uc18c\uc2a4 \ucf54\ub4dc \ubc0f \uc2e4\ud589 \ud30c\uc77c, \uadf8\ub9ac\uace0 IBM\uacfc \ub9c8\uc774\ud06c\ub85c\uc18c\ud504\ud2b8\uac00 \ud568\uaed8 \uac1c\ubc1c\ud55c 4.00\uc758 \uc18c\uc2a4 \ucf54\ub4dc\ub97c \uc124\uba85\ud55c\ub2e4. \uc61b MS-DOS\uc758 \ubaa8\ub4e0 \ubc84\uc804\uc774 \ube60\uc9d0\uc5c6\uc774 \ub4e4\uc5b4 \uc788\ub294 \uc644\uc804\ud55c \ubc15\ubb3c\uad00\uc774\ub77c\uace0 \uc18c\uac1c\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc548\ub0b4\ubb38\uc740 1.25\uc640 2.0 \uc790\ub8cc\uac00 2014\ub144 3\uc6d4 25\uc77c \ucef4\ud4e8\ud130 \uc5ed\uc0ac \ubc15\ubb3c\uad00\uc744 \ud1b5\ud574 \uba3c\uc800 \uacf5\uc720\ub418\uc5c8\ub2e4\uace0 \ubc1d\ud78c\ub2e4. \uc774\ud6c4 \uc774 \uc800\uc7a5\uc18c\uc5d0\uc11c \ub2e4\uc2dc \uc81c\uacf5\ud558\ub294 \uc774\uc720\ub85c \uc790\ub8cc\ub97c \ub354 \uc27d\uac8c \ucc3e\uace0 \ub2e4\ub978 \uae00\uc5d0\uc11c \ucc38\uc870\ud558\uba70 \uc0b4\ud3b4\ubcfc \uc218 \uc788\uac8c \ud55c\ub2e4\ub294 \uc810\uc744 \ub4e0\ub2e4. \uc624\ub798\ub41c \uc790\ub8cc\uc758 \uc811\uadfc\uc131\ub3c4 \ubcf4\uc874\uc758 \uc77c\ubd80\uc778 \uac83\uc774\ub2e4. \uc61b \ud504\ub85c\uadf8\ub7a8\uc758 \ub0b4\uc6a9\uc774 \uacf5\uac1c\ub418\uc5c8\ub2e4\ub294 \uc18c\uc2dd\uc740 \uc0c8 \ubc84\uc804\uc774 \ub098\uc654\ub2e4\ub294 \uc18c\uc2dd\uacfc \uc131\uaca9\uc774 \ub2e4\ub974\ub2e4. \uc774 \uc800\uc7a5\uc18c\ub294 \uc5ed\uc0ac\uc801 \ucc38\uace0\ub97c \ubaa9\uc801\uc73c\ub85c \uc790\ub8cc\ub97c \uc720\uc9c0\ud55c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc9c0\uae08 \uc0ac\uc6a9\ud558\ub294 \ucef4\ud4e8\ud130\ub97c \ubaa8\ub450 \uc774 \ud504\ub85c\uadf8\ub7a8\uc73c\ub85c \ubc14\uafb8\ub77c\ub294 \uad8c\uc720\uac00 \uc544\ub2c8\ub2e4. \uc61b \ubb38\uc11c\uac00 \ud604\uc7ac\uc758 \uc124\uba85\uc11c\uac00 \ub420 \uc218 \uc5c6\ub4ef \uc61b \uc18c\ud504\ud2b8\uc6e8\uc5b4\ub3c4 \ub2f9\uc2dc\uc758 \ud658\uacbd\uc5d0\uc11c \uc774\ud574\ud574\uc57c \ud55c\ub2e4. \ud638\ud658\ub418\ub294 \uc7a5\uce58\ub098 \uc2e4\ud589 \uc870\uac74\uc744 \ub530\uc838\uc57c \ud558\ub294 \ubb38\uc81c\ub294 \ubcc4\ub3c4\ub85c \ub0a8\ub294\ub2e4. \uacf5\uac1c \uc0ac\uc2e4\uc744 \uace7\ubc14\ub85c \uc624\ub298\uc758 \uc77c\uc0c1 \uc0ac\uc6a9\uc5d0 \uc801\ud569\ud558\ub2e4\ub294 \ubcf4\uc99d\uc73c\ub85c \ubc1b\uc544\ub4e4\uc774\uba74 \uc790\ub8cc\uac00 \uac00\uc9c4 \ubaa9\uc801\uc744 \ub193\uce58\uac8c \ub41c\ub2e4. \ud765\ubbf8\ub86d\uac8c\ub3c4 \uacf5\uc2dd \uc548\ub0b4\ub294 \uc18c\uc2a4 \ucf54\ub4dc\uc758 \uc218\uc815\uc744 \uc81c\uc548\ud558\ub294 \uc694\uccad\uc744 \ubcf4\ub0b4\uc9c0 \ub9d0\uc544 \ub2ec\ub77c\uace0 \ud55c\ub2e4. \uc5ed\uc0ac \uc790\ub8cc\ub85c \ubcf4\uad00\ud558\uae30 \ub54c\ubb38\uc5d0 \uadf8\ub300\ub85c \uc720\uc9c0\ud558\uaca0\ub2e4\ub294 \ub73b\uc774\ub2e4. \ubcf4\ud1b5 \uc18c\ud504\ud2b8\uc6e8\uc5b4\uc758 \uc624\ub958\ub97c \ubc1c\uacac\ud558\uba74 \uace0\uce58\ub824 \ud558\ub294\ub370, \uc5ec\uae30\uc11c\ub294 \ubcf4\uc874\uc774\ub77c\ub294 \ub2e4\ub978 \ubaa9\uc801\uc774 \uc55e\uc5d0 \ub193\uc778\ub2e4. \uc624\ub798\ub41c \uc6d0\uace0\uc758 \ub9de\ucda4\ubc95\uc744 \uc624\ub298\uc758 \uae30\uc900\uc73c\ub85c \ubaa8\ub450 \uace0\uccd0 \ub193\uc73c\uba74 \ub2f9\uc2dc \ud45c\uae30\ub97c \uc5f0\uad6c\ud558\uae30 \uc5b4\ub824\uc6cc\uc9c8 \uc218 \uc788\ub2e4. \uc18c\ud504\ud2b8\uc6e8\uc5b4\uc5d0\ub3c4 \ube44\uc2b7\ud55c \ubb38\uc81c\uac00 \uc788\ub2e4. \ud6c4\ub300\uc758 \uac1c\uc120\uc774 \uc544\ubb34\ub9ac \uc720\uc775\ud574\ub3c4 \uc6d0\ub798 \uae30\ub85d\uacfc \uc11e\uc774\uba74 \uacfc\uac70\uc758 \uc120\ud0dd\uc744 \uc77d\uae30 \uc5b4\ub824\uc6cc\uc9c4\ub2e4. \uc0ac\uc6a9\ud558\uae30 \ud3b8\ud55c \uac83\uacfc \uc5ed\uc0ac \uc790\ub8cc\ub85c \uc815\ud655\ud55c \uac83\uc740 \uac19\uc740 \uae30\uc900\uc774 \uc544\ub2c8\ub2e4. \uc6d0\ubcf8\uc744 \uc720\uc9c0\ud558\uaca0\ub2e4\ub294 \ubc29\uce68\uc774 \ubaa8\ub4e0 \uc2e4\ud5d8\uc744 \ub9c9\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc548\ub0b4\ubb38\uc740 \uc790\ub8cc\ub97c \ubcf5\uc81c\ud55c \ubcc4\ub3c4\uc758 \uacf5\uac04\uc5d0\uc11c \uc0b4\ud3b4\ubcf4\uace0 \uc2e4\ud5d8\ud560 \uc218 \uc788\ub2e4\uace0 \ub367\ubd99\uc778\ub2e4. \uc6d0\ub798 \uae30\ub85d\uacfc \ud6c4\ub300\uc758 \uc2dc\ub3c4\ub97c \uad6c\ubd84\ud558\uba74 \ubcf4\uc874\uacfc \ud0d0\uad6c\uac00 \ud568\uaed8 \uac00\ub2a5\ud574\uc9c4\ub2e4. \uacf5\uc2dd \uc800\uc7a5\uc18c\ub294 \ud30c\uc77c\uc744 MIT \ub77c\uc774\uc120\uc2a4\ub85c \uc81c\uacf5\ud55c\ub2e4\uace0 \ubc1d\ud78c\ub2e4. \uc774\uc6a9 \uc870\uac74\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub3c4 \uacf5\uac1c\uc758 \uc911\uc694\ud55c \ubd80\ubd84\uc774\ub2e4. \ub204\uad6c\ub098 \ubcfc \uc218 \uc788\ub2e4\ub294 \uac83\uacfc \uc544\ubb34 \uc870\uac74\ub3c4 \uc5c6\ub2e4\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \uc800\uc791\uad8c \uc548\ub0b4\uc758 \ubcf4\uc874 \uac19\uc740 \uc870\uac74\uc744 \ud655\uc778\ud558\ub294 \uc77c\uacfc \uae30\uc5c5\uc758 \uc0c1\ud45c\ub97c \ub9c8\uc74c\ub300\ub85c \uc4f0\ub294 \uc77c\ub3c4 \uad6c\ubcc4\ud574\uc57c \ud55c\ub2e4. \uae30\uc5c5\uc758 \uc5ed\uc0ac\ub97c \ub85c\uace0\ub098 \ucc3d\uc5c5\uc790\uc758 \ub9d0\ub85c\ub9cc \uc811\ud558\uba74 \uc2e4\uc81c\ub85c \ubb34\uc5c7\uc744 \ub9cc\ub4e4\uc5c8\ub294\uc9c0\uac00 \uba40\uc5b4\uc9c8 \uc218 \uc788\ub2e4. \uc18c\uc2a4 \ucf54\ub4dc\ub294 \uc774\ub984 \ub4a4\uc5d0 \uc788\ub294 \uad6c\uccb4\uc801\uc778 \uc791\uc5c5\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc81c\ud55c\ub41c \ud658\uacbd\uc5d0\uc11c \uc5b4\ub5a4 \uae30\ub2a5\uc744 \uad6c\ud604\ud558\uace0 \uc5b4\ub5a4 \uc21c\uc11c\ub85c \ubb38\uc81c\ub97c \ub2e4\ub8e8\uc5c8\ub294\uc9c0 \uc5f0\uad6c\ud560 \uc218 \uc788\ub294 \ucd9c\ubc1c\uc810\uc774 \ub41c\ub2e4. \uadf8\ub807\ub2e4\uace0 \ucf54\ub4dc\ub9cc\uc73c\ub85c \uae30\uc5c5\uc758 \ubaa8\ub4e0 \uacb0\uc815\uc744 \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \uacc4\uc57d\uacfc \uc2dc\uc7a5, \uc774\uc6a9\uc790\uc758 \uacbd\ud5d8\uc740 \ub2e4\ub978 \uae30\ub85d\uc774 \ud544\uc694\ud558\ub2e4. \uacf5\uac1c \uc790\ub8cc\uc758 \uc7a5\uc810\uc740 \ubaa8\ub4e0 \ub2f5\uc744 \uac16\ucd94\uc5c8\ub2e4\ub294 \ub370 \uc788\uc9c0 \uc54a\ub2e4. \ub2e4\ub978 \uc790\ub8cc\uc640 \ub300\uc870\ud558\uba70 \ubb3c\uc744 \uc218 \uc788\ub294 \uc2e4\uc81c \ub300\uc0c1\uc774 \uc0dd\uacbc\ub2e4\ub294 \ub370 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\uc740 \uc61b \uac1c\uc778\uc6a9 \ucef4\ud4e8\ud130\uc640 \uae30\ub85d \ubcf4\uad00\uc758 \ubd84\uc704\uae30\ub97c \ub2f4\uc740 AI \uc0bd\ud654\uc774\uba70 \uc2e4\uc81c MS-DOS \ud654\uba74\uc744 \uc7ac\ud604\ud55c \uac83\uc774 \uc544\ub2c8\ub2e4. \uc18c\ud504\ud2b8\uc6e8\uc5b4\uc758 \uc815\ud655\ud55c \ub0b4\uc6a9\uc740 \uadf8\ub9bc \uc18d \uac00\uc0c1\uc758 \ud654\uba74 \ub300\uc2e0 \uacf5\uc2dd \uc800\uc7a5\uc18c\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\ub2e4. \ub0a1\uc740 \ucef4\ud4e8\ud130\uc758 \uc5ed\uc0ac\ub97c \ub0a8\uae30\ub294 \uc77c\uc740 \ubcf8\uccb4\ub97c \ubc84\ub9ac\uc9c0 \uc54a\ub294 \uac83\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \ud504\ub85c\uadf8\ub7a8\uacfc \uc124\uba85\uc11c, \ub9cc\ub4dc\ub294 \ub370 \uc4f4 \uae30\ub85d\uae4c\uc9c0 \uc11c\ub85c \uc774\uc5b4\uc838\uc57c \ud55c\ub2e4. MS-DOS \uacf5\uac1c \uc790\ub8cc\ub294 \uc6b0\ub9ac\uc5d0\uac8c \ucef4\ud4e8\ud130\uac00 \uc5b4\ub5a4 \ubaa8\uc591\uc774\uc5c8\ub294\uc9c0\ub97c \ub118\uc5b4, \uadf8 \uc548\uc5d0\uc11c \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub5a4 \uc77c\uc744 \uac00\ub2a5\ud558\uac8c \ud588\ub294\uc9c0 \ubb3c\uc744 \uae30\ud68c\ub97c \uc900\ub2e4."}, {"id": "netflix-envelope-to-streaming", "title": "\ub137\ud50c\ub9ad\uc2a4 \u2014 \uc601\ud654\uac00 \uc6b0\ud3b8\ud568\uc5d0\uc11c \ud654\uba74\uc73c\ub85c \uc62e\uaca8 \uc624\uae30\uae4c\uc9c0", "summary": "DVD \uc6b0\ud3b8 \ub300\uc5ec\uc5d0\uc11c \uc2a4\ud2b8\ub9ac\ubc0d\uc73c\ub85c \uc62e\uaca8 \uac04 \uc0ac\ub840\ub97c \ud1b5\ud574 \uc11c\ube44\uc2a4\uc758 \ubcc0\ud654\uc640 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc870\uac74\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "companies", "category_title": "Companies", "subcategory": "Media", "url": "stories/netflix-envelope-to-streaming/index.html", "image": "media/netflix-envelope-to-streaming.png", "alt": "\uc6b0\ud3b8 \ubd09\ud22c \uc18d DVD\uc640 \ub178\ud2b8\ubd81, TV\uac00 \ub193\uc778 \uac70\uc2e4\uc5d0\uc11c \uc601\ud654\ub97c \uace0\ub974\ub294 AI \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\ub137\ud50c\ub9ad\uc2a4 \u2014 \uc601\ud654\uac00 \uc6b0\ud3b8\ud568\uc5d0\uc11c \ud654\uba74\uc73c\ub85c \uc62e\uaca8 \uc624\uae30\uae4c\uc9c0 \uac19\uc740 \uc601\ud654\ub97c \ubcf4\ub294 \uc77c\ub3c4 \ub3c4\ucc29\ud558\ub294 \ubc29\ubc95\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c4\ub2e4 DVD \uc6b0\ud3b8 \ub300\uc5ec\uc5d0\uc11c \uc2a4\ud2b8\ub9ac\ubc0d\uc73c\ub85c \uc62e\uaca8 \uac04 \uc0ac\ub840\ub97c \ud1b5\ud574 \uc11c\ube44\uc2a4\uc758 \ubcc0\ud654\uc640 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc870\uac74\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Media \uae30\uc5c5 \uc624\ub298 \uc800\ub141 \uc601\ud654\ub97c \uace0\ub978 \ub4a4 \uc7ac\uc0dd \ubc84\ud2bc\uc744 \ub204\ub978\ub2e4. \uc7a0\uc2dc \ud6c4 \ud654\uba74\uc774 \uc6c0\uc9c1\uc774\uba74 \uc601\ud654\uac00 \ub3c4\ucc29\ud588\ub2e4\ub294 \uc0dd\uac01\uc870\ucc28 \ud558\uc9c0 \uc54a\ub294\ub2e4. \ud558\uc9c0\ub9cc \uac19\uc740 \uc601\ud654\ub97c \ubcf4\uae30 \uc704\ud574 \uc791\uc740 \uc6d0\ubc18\uc774 \uc9d1\uae4c\uc9c0 \uc624\uae30\ub97c \uae30\ub2e4\ub9ac\ub358 \ubc29\uc2dd\ub3c4 \uc788\uc5c8\ub2e4. \ub137\ud50c\ub9ad\uc2a4\uc758 \ucd9c\ubc1c\uc740 \uc9c0\uae08\uc758 \ud654\uba74\ubcf4\ub2e4 \uc6b0\ud3b8\ud568\uc5d0 \uac00\uae4c\uc6e0\ub2e4. 1997\ub144 \uc124\ub9bd\ub41c \ub137\ud50c\ub9ad\uc2a4\ub294 \uc628\ub77c\uc778 DVD \ub300\uc5ec\uc5d0\uc11c \ucd9c\ubc1c\ud588\ub2e4. \uc778\ud130\ub137\uc5d0\uc11c \uace0\ub974\uace0 \ubb3c\ub9ac\uc801\uc778 \ub514\uc2a4\ud06c\ub97c \ubc1b\uc544 \ubcf4\ub294 \uc0ac\uc5c5\uc774\ub2e4. \uc774 \ud68c\uc0ac\uc758 \ubcc0\ud654\ub294 \uc601\ud654 \ubaa9\ub85d\uc774 \ub9ce\uc544\uc9c4 \uc774\uc57c\uae30\uc774\uae30\ub3c4 \ud558\uc9c0\ub9cc, \ub354 \ud765\ubbf8\ub85c\uc6b4 \uc9c8\ubb38\uc740 \ub530\ub85c \uc788\ub2e4. \uace0\uac1d\uc774 \ubb34\uc5c7\uc744 \uae30\ub2e4\ub824\uc57c \ud558\ub294\uc9c0\uac00 \uc5b4\ub5bb\uac8c \ub2ec\ub77c\uc84c\uc744\uae4c. \uc628\ub77c\uc778\uc774\ub77c\ub294 \ub9d0\uc774 \ubd99\uc5c8\ub2e4\uace0 \ucc98\uc74c\ubd80\ud130 \ubaa8\ub4e0 \uac83\uc774 \ud654\uba74 \uc548\uc5d0\uc11c \ub05d\ub09c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc120\ud0dd\uacfc \uc8fc\ubb38\uc740 \uc778\ud130\ub137\uc73c\ub85c \ud560 \uc218 \uc788\uc5b4\ub3c4 \uc601\uc0c1\uc744 \ub2f4\uc740 DVD\ub294 \uc2e4\uc81c \uc7a5\uc18c\uc5d0 \ubcf4\uad00\ud574\uc57c \ud588\ub2e4. \ud3ec\uc7a5\ud558\uace0 \ubcf4\ub0b4\ub294 \uc77c, \uace0\uac1d\uc5d0\uac8c \ub3c4\ucc29\ud558\ub294 \ub370 \uac78\ub9ac\ub294 \uc2dc\uac04\uc774 \uc11c\ube44\uc2a4\uc758 \uc77c\ubd80\uc600\ub2e4. \uc774 \ubc29\uc2dd\uc5d0\uc11c\ub294 \uc601\ud654\uc758 \ub0b4\uc6a9\ub9cc\ud07c \uc774\ub3d9\ub3c4 \uc911\uc694\ud558\ub2e4. \ubcf4\uace0 \uc2f6\uc740 \uc791\ud488\uc744 \ubc1c\uacac\ud558\ub294 \uac83\uacfc \uc624\ub298 \ubc14\ub85c \ubcfc \uc218 \uc788\ub294 \uac83\uc740 \ub2e4\ub978 \ubb38\uc81c\ub2e4. \uace0\uac1d\uc758 \uacbd\ud5d8\uc744 \ubc14\uafb8\ub824\uba74 \uc88b\uc740 \ubaa9\ub85d\ubfd0 \uc544\ub2c8\ub77c \ubb3c\uac74\uc774 \uc624\uac00\ub294 \ud750\ub984\ub3c4 \uc798 \ub9cc\ub4e4\uc5b4\uc57c \ud588\ub2e4. \ub514\uc9c0\ud138 \uc8fc\ubb38\uacfc \ubb3c\ub9ac\uc801\uc778 \uc720\ud1b5\uc774 \uacb9\uccd0 \uc788\ub294 \uc0ac\uc5c5\uc774\uc5c8\ub358 \uc148\uc774\ub2e4. \ub137\ud50c\ub9ad\uc2a4\ub294 2007\ub144 \uc2a4\ud2b8\ub9ac\ubc0d \uc11c\ube44\uc2a4\ub97c \uc2dc\uc791\ud588\ub2e4. \uc778\ud130\ub137\uc744 \ud1b5\ud574 \uc601\uc0c1 \ub370\uc774\ud130\ub97c \ubc1b\uc544 \ubcf4\uac8c \ub41c \uac83\uc774\ub2e4. \uc0ac\uc6a9\uc790\uc758 \uc785\uc7a5\uc5d0\uc11c\ub294 \ub514\uc2a4\ud06c\uac00 \ub3c4\ucc29\ud574\uc57c \ubcfc \uc218 \uc788\ub358 \uc0c1\ud669\uc5d0\uc11c, \uc5f0\uacb0 \uc0c1\ud0dc\uac00 \ud5c8\ub77d\ud558\uba74 \uace7\ubc14\ub85c \uc7ac\uc0dd\ud560 \uc218 \uc788\ub294 \ubc29\uc2dd\uc73c\ub85c \ubc14\ub00c\uc5c8\ub2e4. \uc774 \ubcc0\ud654\uac00 \uac00\ub2a5\ud55c \ubc30\uacbd\uc5d0\ub294 \ud1b5\uc2e0 \uc18d\ub3c4\uc640 \uae30\uc220\uc758 \ubc1c\uc804\uc774 \uc788\uc5c8\ub2e4. \uc544\uc774\ub514\uc5b4\uac00 \uba3c\uc800 \uc874\uc7ac\ud574\ub3c4 \ub9ce\uc740 \uc0ac\ub78c\uc774 \uc548\uc815\uc801\uc73c\ub85c \uc774\uc6a9\ud560 \uc870\uac74\uc774 \uac16\ucd94\uc5b4\uc9c0\uc9c0 \uc54a\uc73c\uba74 \uc11c\ube44\uc2a4\uac00 \ub418\uae30 \uc5b4\ub835\ub2e4. \uae30\uc5c5\uc758 \uc120\ud0dd\uacfc \uadf8 \ubc14\uae65\uc5d0\uc11c \ubc1c\uc804\ud558\ub294 \uae30\uc220\uc774 \uc5b4\ub290 \uc2dc\uc810\uc5d0 \ub9cc\ub0ac\ub294\uc9c0\ub97c \ud568\uaed8 \ubcf4\uc544\uc57c \ud558\ub294 \uc774\uc720\ub2e4. \uc2a4\ud2b8\ub9ac\ubc0d\uc73c\ub85c \ubc14\uafb8\uba74 \ud3ec\uc7a5\uacfc \ubc30\uc1a1\uc5d0 \uad00\ud55c \uc77c\ubd80 \ubb38\uc81c\uac00 \uc904\uc5b4\ub4e0\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc601\ud654\uac00 \uc544\ubb34\ub7f0 \uc900\ube44 \uc5c6\uc774 \ud558\ub298\uc5d0\uc11c \ub0b4\ub824\uc624\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc601\uc0c1\uc744 \uc804\ub2ec\ud558\ub294 \uc124\ube44\uc640 \ud1b5\uc2e0\ub9dd, \uc7ac\uc0dd\ud558\ub294 \uae30\uae30\uc640 \uc18c\ud504\ud2b8\uc6e8\uc5b4\uac00 \uc0c8\ub85c\uc6b4 \uc870\uac74\uc774 \ub41c\ub2e4. \uac00\ub839 \uc6b0\ud3b8\uc744 \uae30\ub2e4\ub9ac\ub294 \uc2dc\uac04\uc740 \uc5c6\uc5b4\uc84c\uc5b4\ub3c4 \uc5f0\uacb0\uc774 \ubd88\uc548\uc815\ud558\uba74 \uc7ac\uc0dd\uc774 \ub04a\uae38 \uc218 \uc788\ub2e4. \ubc14\ub010 \uac83\uc740 \ubd88\ud3b8\ud568\uc774 \ubaa8\ub450 \uc0ac\ub77c\uc84c\ub2e4\ub294 \uc0ac\uc2e4\ubcf4\ub2e4, \uc5b4\ub5a4 \ubd80\ubd84\uc744 \uc798 \uc900\ube44\ud574\uc57c \uace0\uac1d\uc774 \ud3b8\ub9ac\ud568\uc744 \ub290\ub07c\ub294\uc9c0\ub2e4. \uc81c\ud488\uc744 \ub2f4\ub294 \uadf8\ub987\uc774 \ubc14\ub00c\uba74 \uc11c\ube44\uc2a4\uc758 \uc77c\uac70\ub9ac\ub3c4 \ud568\uaed8 \uc774\ub3d9\ud55c\ub2e4. \ub137\ud50c\ub9ad\uc2a4\ub294 2010\ub144 \uce90\ub098\ub2e4\uc5d0 \uc2a4\ud2b8\ub9ac\ubc0d \uc11c\ube44\uc2a4\ub97c \uc81c\uacf5\ud558\uba70 \ud574\uc678 \uc9c4\ucd9c\uc744 \uc2dc\uc791\ud588\ub2e4. \ub514\uc2a4\ud06c\ub97c \uba3c \uacf3\uae4c\uc9c0 \ubcf4\ub0b4\ub294 \ubc29\uc2dd\uacfc \ub2ec\ub9ac \uc628\ub77c\uc778 \uc11c\ube44\uc2a4\ub294 \ub2e4\ub978 \uc2dc\uc7a5\uc73c\ub85c \ud655\uc7a5\ud560 \uc5ec\uc9c0\uac00 \ucef8\ub2e4. \uadf8\ub7ec\ub098 \uad6d\uacbd\uc744 \ub118\ub294 \uc77c\uc774 \ub2e8\uc21c\ud788 \uc6f9\uc0ac\uc774\ud2b8\uc758 \ubb38\uc744 \uc5f4\uc5b4 \ub450\ub294 \uac83\uacfc \uac19\uc9c0\ub294 \uc54a\uc558\ub2e4. \ud604\uc9c0\uc758 \uc778\ud130\ub137 \ud658\uacbd\uacfc \uaddc\uc81c, \uc0ac\ub78c\ub4e4\uc774 \uc88b\uc544\ud558\ub294 \uc791\ud488\uc774 \ub2ec\ub790\ub2e4. \uad50\uc7ac\ub294 \ud604\uc9c0 \ucf58\ud150\uce20 \uc81c\uc791\uacfc \uc791\ud488\uc758 \uad8c\ub9ac \ud655\ubcf4, \ud1b5\uc2e0\uc5c5\uccb4\uc640\uc758 \ud611\ub825, \uac00\uaca9\uacfc \uc694\uae08\uc81c \uc870\uc815\uc744 \uc774\ub7f0 \ubb38\uc81c\uc5d0 \ub300\uc751\ud558\ub294 \ubc29\uc2dd\uc73c\ub85c \uc124\uba85\ud55c\ub2e4. \uace0\uac1d\uc740 \ube44\uc2b7\ud55c \uc7ac\uc0dd \ubc84\ud2bc\uc744 \ub20c\ub7ec\ub3c4 \uadf8 \ub4a4\uc758 \uc900\ube44\ub294 \uc9c0\uc5ed\ub9c8\ub2e4 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc5c8\ub2e4. \uc628\ub77c\uc778\uc5d0\uc11c \uc804\ub2ec\ud560 \uc218 \uc788\ub2e4\ub294 \uac83\uacfc \uc5b4\ub290 \ub098\ub77c\uc5d0\uc11c\ub098 \uac19\uc740 \uc791\ud488\uc744 \uc81c\uacf5\ud560 \uad8c\ub9ac\uac00 \uc788\ub2e4\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \uc791\ud488\uc758 \uc774\uc6a9 \uad8c\ub9ac\ub97c \ud655\ubcf4\ud558\ub294 \uc77c\uc774 \ubcc4\ub3c4\ub85c \ud544\uc694\ud558\uae30 \ub54c\ubb38\uc774\ub2e4. \uc138\uacc4\ub85c \ud655\uc7a5\ud558\ub294 \uc11c\ube44\uc2a4\uac00 \uae30\uc220 \ubb38\uc81c\ub9cc \ud574\uacb0\ud558\uba74 \ub41c\ub2e4\uace0 \uc0dd\uac01\ud560 \ub54c \ub193\uce58\uae30 \uc26c\uc6b4 \ub300\ubaa9\uc774\ub2e4. \uc5b8\uc5b4\uc640 \ubb38\ud654\uc758 \ubb38\uc81c\ub3c4 \uc788\ub2e4. \ub2e4\ub978 \ub098\ub77c\uc5d0\uc11c \uc778\uae30 \uc788\ub294 \uc791\ud488\uc744 \uadf8\ub300\ub85c \ubaa8\uc544 \ub193\ub294 \uac83\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uc9c0\uc5ed\uc758 \uad00\uac1d\uc774 \uac19\uc740 \uad00\uc2ec\uc744 \ubcf4\uc774\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc9c0\uc5ed\uc758 \uc774\uc57c\uae30\ub97c \uc81c\uc791\ud558\uac70\ub098 \ud655\ubcf4\ud558\ub294 \uc120\ud0dd\uc740 \ubc88\uc5ed\uc744 \ud55c \uc904 \ub354 \ubd99\uc774\ub294 \uc77c\ubcf4\ub2e4 \ub113\ub2e4. \ubb34\uc5c7\uc744 \ubcf4\uc5ec \uc904 \uac83\uc778\uc9c0 \uc790\uccb4\uac00 \uc2dc\uc7a5\uacfc \ud568\uaed8 \ubc14\ub010\ub2e4. \uc774 \uc0ac\ub840\uc5d0\uc11c \ud68c\uc0ac\ub294 \uacc4\uc18d \uc601\ud654\ub97c \ubcf4\ub294 \uacbd\ud5d8\uacfc \uc5f0\uacb0\ub418\uc5b4 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uc6b0\ud3b8 \ub300\uc5ec\uc640 \uc2a4\ud2b8\ub9ac\ubc0d\uc5d0\ub294 \ub2e4\ub978 \uae30\uc220\uacfc \uc6b4\uc601 \ub2a5\ub825\uc774 \ud544\uc694\ud558\ub2e4. \uace0\uac1d\uc774 \uc5bb\uc73c\ub824\ub294 \uc990\uac70\uc6c0\uc774 \ube44\uc2b7\ud574\ub3c4, \ud68c\uc0ac\uac00 \uadf8 \uc990\uac70\uc6c0\uc744 \ub9cc\ub4e4\uc5b4 \ub0b4\ub294 \ubc29\ubc95\uc740 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uadf8\ub798\uc11c \uae30\uc5c5\uc744 \uc9c0\uae08 \ud30c\ub294 \ubb3c\uac74\uc758 \uc774\ub984\ub9cc\uc73c\ub85c \uc124\uba85\ud558\uba74 \ubcc0\ud654\uac00 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. DVD\ub97c \ubcf4\ub0b4\ub294 \ud68c\uc0ac\ub77c\uace0\ub9cc \uc0dd\uac01\ud558\uba74 \uc2a4\ud2b8\ub9ac\ubc0d\uc740 \ub0af\uc120 \uc77c\uc774\uc9c0\ub9cc, \uc9d1\uc5d0\uc11c \ubcf4\uace0 \uc2f6\uc740 \uc601\ud654\ub97c \uace0\ub974\uac8c \ud558\ub294 \uc11c\ube44\uc2a4\ub85c \ubcf4\uba74 \uc774\uc5b4\uc9c0\ub294 \ubd80\ubd84\ub3c4 \ubcf4\uc778\ub2e4. \ubb34\uc5c7\uc744 \uc720\uc9c0\ud558\uace0 \ubb34\uc5c7\uc744 \ubc14\uafc0\uc9c0 \uc815\ud558\ub294 \uac83\uc774 \uc0ac\uc5c5 \uc804\ud658\uc758 \ud575\uc2ec \uc9c8\ubb38\uc774 \ub41c\ub2e4. \ud604\uc7ac\uc758 \ubaa8\uc2b5\uc5d0\uc11c \uacfc\uac70\ub97c \uac70\uafb8\ub85c \ubcf4\uba74 \uc2a4\ud2b8\ub9ac\ubc0d \uc804\ud658\uc774 \ub108\ubb34 \ub2f9\uc5f0\ud574 \ubcf4\uc77c \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \ud55c \uc0b0\uc5c5\uc758 \ubcc0\ud654\ub294 \uae30\uc220, \ube44\uc6a9\uacfc \uad8c\ub9ac, \uace0\uac1d\uc758 \uc2b5\uad00\uc774 \ud568\uaed8 \uc6c0\uc9c1\uc774\ub294 \uacfc\uc815\uc774\ub2e4. \uae30\uc5c5\uc774 \ud55c \ubc88\uc758 \uba4b\uc9c4 \uacb0\ub2e8\uc73c\ub85c \ubaa8\ub4e0 \ubb38\uc81c\ub97c \ub05d\ub0c8\ub2e4\ub294 \uc774\uc57c\uae30\ub85c \uc904\uc77c \uc218\ub294 \uc5c6\ub2e4. \uc5ec\uae30\uc11c\ub294 \ud655\uc778\ud55c \ucd08\ucc3d\uae30\uc640 \uc804\ud658 \uacfc\uc815\uc5d0 \ucd08\uc810\uc744 \ub9de\ucdc4\ub2e4. \ud604\uc7ac \uac00\uc785\uc790 \uc218\ub098 \uad6d\uac00\ubcc4 \uc791\ud488 \ubaa9\ub85d, \uc694\uae08\uc740 \ubcc4\ub3c4\uc758 \ucd5c\uc2e0 \uc790\ub8cc\uac00 \ud544\uc694\ud55c \uc815\ubcf4\ub2e4. \uc5ed\uc0ac\uc801 \uc0ac\ub840\ub97c \uc774\ud574\ud558\ub294 \uac83\uacfc \uc624\ub298 \uac00\uc785\ud560 \uc11c\ube44\uc2a4\ub97c \ube44\uad50\ud558\ub294 \uac83\uc740 \ub2e4\ub978 \uc791\uc5c5\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uc2e4\uc81c \ub137\ud50c\ub9ad\uc2a4 \ubd09\ud22c\ub098 \ub2f9\uc2dc \ud654\uba74\uc744 \ubcf5\uc6d0\ud55c \uc790\ub8cc\uac00 \uc544\ub2c8\ub2e4. \ub514\uc2a4\ud06c\uc640 \uc6b0\ud3b8, \uc9d1 \uc548\uc758 \uc2dc\uccad \uacbd\ud5d8\uc774 \uc774\uc5b4\uc9c0\ub358 \ubd84\uc704\uae30\ub97c \ud45c\ud604\ud588\ub2e4. \uadf8\ub9bc\uc744 \ubcf4\uba70 \uc6d0\ubc18 \ud55c \uc7a5\uc774 \uc6c0\uc9c1\uc774\ub358 \uac70\ub9ac\uc640, \uc9c0\uae08 \uc7ac\uc0dd \ubc84\ud2bc \ub4a4\uc5d0\uc11c \uc6c0\uc9c1\uc774\ub294 \ub370\uc774\ud130\ub97c \ubc88\uac08\uc544 \ub5a0\uc62c\ub824 \ubcf4\uc790. \ub137\ud50c\ub9ad\uc2a4\uc758 \ubcc0\ud654\ub294 \ubb3c\uac74\uc744 \uc5c6\uc564 \ud68c\uc0ac\uc758 \uc774\uc57c\uae30\ub85c\ub9cc \ub0a8\uc9c0 \uc54a\ub294\ub2e4. \uac19\uc740 \uc800\ub141\uc758 \uc990\uac70\uc6c0\uc744 \uc704\ud574 \uc5b4\ub5a4 \uc900\ube44\uac00 \ud544\uc694\ud55c\uc9c0\uac00 \ub2ec\ub77c\uc9c4 \uc774\uc57c\uae30\ub2e4. \ub2e4\uc74c\uc5d0 \uc601\ud654\ub97c \uc7ac\uc0dd\ud560 \ub54c\ub294 \uc791\ud488\uc758 \uccab \uc7a5\uba74\uacfc \ud568\uaed8, \uadf8 \uc7a5\uba74\uc774 \ub0b4 \uc55e\uc5d0 \ub3c4\ucc29\ud558\ub294 \ubc29\ubc95\ub3c4 \uc7a0\uae50 \uc0dd\uac01\ud574 \ubcfc \ub9cc\ud558\ub2e4."}, {"id": "patagonia-climbing-gear-and-rock", "title": "\ud30c\ud0c0\uace0\ub2c8\uc544 \u2014 \uc798 \ud314\ub9ac\ub294 \uc7a5\ube44\ub97c \uc65c \ubc14\uafb8\ub824 \ud588\uc744\uae4c", "summary": "\uc774\ubcf8 \uc26c\ub098\ub4dc\uc758 \ub4f1\ubc18 \uc7a5\ube44 \uc0ac\uc5c5\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc81c\ud488\uc758 \uc131\uacf5\uacfc \ud658\uacbd\uc758 \ubd80\ub2f4\uc744 \ud568\uaed8 \uc0dd\uac01\ud569\ub2c8\ub2e4.", "category": "companies", "category_title": "Companies", "subcategory": "Fashion", "url": "stories/patagonia-climbing-gear-and-rock/index.html", "image": "media/patagonia-climbing-gear-and-rock.png", "alt": "\ub4f1\ubc18\uc6a9 \uae08\uc18d \uc7a5\ube44\uc640 \ubc27\uc904, \uc57c\uc678 \uc758\ub958\uac00 \ub193\uc778 \uc791\uc5c5\ub300\uc758 AI \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\ud30c\ud0c0\uace0\ub2c8\uc544 \u2014 \uc798 \ud314\ub9ac\ub294 \uc7a5\ube44\ub97c \uc65c \ubc14\uafb8\ub824 \ud588\uc744\uae4c \ubc14\uc704\ub97c \uc88b\uc544\ud558\ub294 \uc0ac\ub78c\uc774 \ubc14\uc704\uc5d0 \ub0a8\uae34 \ud754\uc801\uc744 \ubcf4\uac8c \ub418\ub2e4 \uc774\ubcf8 \uc26c\ub098\ub4dc\uc758 \ub4f1\ubc18 \uc7a5\ube44 \uc0ac\uc5c5\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc81c\ud488\uc758 \uc131\uacf5\uacfc \ud658\uacbd\uc758 \ubd80\ub2f4\uc744 \ud568\uaed8 \uc0dd\uac01\ud569\ub2c8\ub2e4. Fashion \uae30\uc5c5 \uc88b\uc544\ud558\ub294 \uc77c\uc744 \uacc4\uc18d\ud558\uae30 \uc704\ud574 \uc791\uc740 \ub3c4\uad6c\ub97c \ub9cc\ub4e4\uc5b4 \ud310\ub2e4. \uadf8 \ub3c4\uad6c\uac00 \uc798 \ud314\ub9ac\uae30 \uc2dc\uc791\ud558\uba74 \ubcf4\ud1b5\uc740 \uae30\ubed0\ud560 \uc77c\uc774\ub2e4. \uadf8\ub7f0\ub370 \ub354 \ub9ce\uc740 \uc0ac\ub78c\uc774 \uc0ac\uc6a9\ud560\uc218\ub85d \uc790\uc2e0\uc774 \uc88b\uc544\ud558\ub294 \uc7a5\uc18c\uac00 \uc190\uc0c1\ub41c\ub2e4\uba74 \uc5b4\ub5a8\uae4c. \uc81c\ud488\uc774 \uc131\uacf5\ud558\uace0 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ub9c8\uc74c \ud3b8\ud55c \uc18c\uc2dd\ub9cc\uc740 \uc544\ub2c8\uac8c \ub41c\ub2e4. \ud30c\ud0c0\uace0\ub2c8\uc544\uc758 \ucc3d\ub9bd\uc790 \uc774\ubcf8 \uc26c\ub098\ub4dc\uc758 \uc774\uc57c\uae30\uc5d0\ub294 \uc774\ub7f0 \uc7a5\uba74\uc774 \uc788\ub2e4. \uc57c\uc678 \uc758\ub958 \ube0c\ub79c\ub4dc\ub85c \uc775\uc219\ud558\uc9c0\ub9cc \uadf8 \ucd9c\ubc1c\uc744 \uac70\uc2ac\ub7ec \uc62c\ub77c\uac00\uba74 \uc637\ubcf4\ub2e4 \uba3c\uc800 \ubc14\uc704\uc640 \ub4f1\ubc18 \uc7a5\ube44\ub97c \ub9cc\ub09c\ub2e4. \uc774 \uc0ac\ub840\uac00 \ud765\ubbf8\ub85c\uc6b4 \uae4c\ub2ed\uc740 \ud658\uacbd\uc744 \uc544\ub07c\uc790\ub294 \ub9d0\uc774 \uc2e4\uc81c\ub85c \ubb34\uc5c7\uc744 \ud314\uc9c0\uc5d0 \uad00\ud55c \uc120\ud0dd\uc73c\ub85c \uc774\uc5b4\uc84c\uae30 \ub54c\ubb38\uc774\ub2e4. \uc26c\ub098\ub4dc\ub294 \ucc98\uc74c\ubd80\ud130 \ud328\uc158 \uae30\uc5c5\uc744 \uc138\uc6b0\uaca0\ub2e4\ub294 \uacc4\ud68d\ub9cc\uc73c\ub85c \uc6c0\uc9c1\uc778 \uc0ac\ub78c\uc774 \uc544\ub2c8\uc5c8\ub2e4. \ub4f1\ubc18\uc744 \uc88b\uc544\ud588\uace0 \uadf8 \uc0dd\ud65c\uc744 \uc774\uc5b4 \uac00\ub294 \uacfc\uc815\uc5d0\uc11c \uac15\ucca0 \ud53c\ud1a4\uc744 \ub9cc\ub4e4\uc5b4 \ud314\uc558\ub2e4. \ud53c\ud1a4\uc740 \ubc14\uc704 \ud2c8\uc5d0 \ubc15\uc544 \uc4f0\ub294 \uae08\uc18d \uc7a5\ube44\ub2e4. \uae30\ub2a5\uc744 \uc774\ud574\ud558\ub294 \ub370\ub294 \uc774 \uc815\ub3c4 \uc124\uba85\uc774\uba74 \ucda9\ubd84\ud558\ub2e4. \uadf8 \uc0ac\uc5c5\uc740 \uc131\uc7a5\ud574 \uc26c\ub098\ub4dc \uc774\ud045\uba3c\ud2b8\uac00 \ub418\uc5c8\ub2e4. \uad50\uc7ac\ub294 \ubbf8\uad6d\uc758 \uc911\uc694\ud55c \ub4f1\ubc18 \uc7a5\ube44 \uacf5\uae09\uc5c5\uccb4\ub85c \ubc1c\uc804\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc790\uc2e0\uc774 \uc9c1\uc811 \uc0ac\uc6a9\ud558\ub294 \ub3c4\uad6c\ub97c \uc798 \ub9cc\ub4e4 \uc218 \uc788\ub2e4\ub294 \ub2a5\ub825\uc774 \uc0ac\uc5c5\uc73c\ub85c \uc774\uc5b4\uc9c4 \uac83\uc774\ub2e4. \uace0\uac1d\uc774 \uc6d0\ud558\ub294 \uac83\uc744 \uc774\ud574\ud558\ub294 \uacbd\ud5d8\uacfc \uc81c\uc791 \uae30\uc220\uc774 \uac00\uae4c\uc774 \uc788\uc5c8\ub2e4. \ub4f1\ubc18\ud558\ub294 \uc0ac\ub78c\uc774 \ub298\uace0 \ud53c\ud1a4 \uc0ac\uc6a9\ub3c4 \ub9ce\uc544\uc9c0\uba74\uc11c \ubc14\uc704\uc5d0 \uc190\uc0c1\uc774 \uc0dd\uacbc\ub2e4. \ubc18\ubcf5\ud574\uc11c \uc7a5\ube44\ub97c \ubc15\uc544 \ub123\ub294 \ud589\ub3d9\uc774 \uc790\uc5f0\ud658\uacbd\uc5d0 \ud754\uc801\uc744 \ub0a8\uacbc\uae30 \ub54c\ubb38\uc774\ub2e4. \uc0b0\uacfc \ubc14\uc704\ub97c \uc88b\uc544\ud574 \uc2dc\uc791\ud55c \uc77c\uc774 \uadf8 \ub300\uc0c1\uc744 \ud574\uce60 \uc218 \uc788\ub2e4\ub294 \ubaa8\uc21c\uc774 \ub4dc\ub7ec\ub0ac\ub2e4. \uc81c\ud488\uc744 \ud314\uc558\ub2e4\ub294 \ub2e8\uacc4\uc5d0\uc11c\ub9cc \uacc4\uc0b0\ud558\uba74 \uc774 \uacb0\uacfc\uac00 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uadf8\ub7ec\ub098 \ubb3c\uac74\uc740 \ub9e4\uc7a5\uc744 \ub5a0\ub09c \ub4a4\uc5d0\ub3c4 \uc0ac\uc6a9\ub41c\ub2e4. \uc5b4\ub5a4 \ubc29\uc2dd\uc73c\ub85c \uc4f0\uc774\uace0 \ubb34\uc5c7\uc744 \ubc14\uafb8\ub294\uc9c0\uae4c\uc9c0 \uc0b4\ud53c\uba74 \uae30\uc5c5\uc758 \ucc45\uc784 \ubc94\uc704\uac00 \ub113\uc5b4\uc9c4\ub2e4. \uc26c\ub098\ub4dc\uac00 \ub9c8\uc8fc\ud55c \uc9c8\ubb38\ub3c4 \uc0dd\uc0b0\ud55c \uc218\ub7c9 \ubc14\uae65\uc5d0 \uc788\uc5c8\ub2e4. \uadf8\ub294 \ud53c\ud1a4\uc5d0 \ub300\ud55c \uc758\uc874\uc744 \uc904\uc774\uace0 \ubc14\uc704\uc5d0 \ubbf8\uce58\ub294 \ubd80\ub2f4\uc774 \ub354 \uc801\uc740 \uc54c\ub8e8\ubbf8\ub284 \ucd08\ud06c\ub97c \ud310\ub9e4\ud558\ub294 \ubc29\ud5a5\uc73c\ub85c \uc6c0\uc9c1\uc600\ub2e4. \uc5ec\uae30\uc11c \ucd08\ud06c\ub294 \uc190\uc5d0 \ubc14\ub974\ub294 \uac00\ub8e8\ub97c \ub73b\ud558\uc9c0 \uc54a\uace0 \ub4f1\ubc18\uc6a9 \uae08\uc18d \uc7a5\ube44\ub97c \uac00\ub9ac\ud0a8\ub2e4. \uc791\uc740 \uc774\ub984 \ucc28\uc774\uac00 \uc804\ud600 \ub2e4\ub978 \ubb3c\uac74\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud560 \uc218 \uc788\ub2e4. \uc774 \uae00\uc740 \uc7a5\ube44 \uc124\uce58\ubc95\uc774\ub098 \uc548\uc804 \uc131\ub2a5\uc744 \ube44\uad50\ud558\ub294 \uc548\ub0b4\uac00 \uc544\ub2c8\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \uc774\ubbf8 \ud314\ub9ac\ub294 \uc81c\ud488\uc774 \uc788\uc5b4\ub3c4 \ub2e4\ub978 \ubc29\uc2dd\uc744 \ucc3e\uc558\ub2e4\ub294 \uc810\uc774\ub2e4. \uc774\uc775\uc774 \uc0dd\uae30\ub294 \uae30\uc874 \ud65c\ub3d9\uc758 \uc77c\ubd80\ub97c \uc2a4\uc2a4\ub85c \ubc14\uafb8\ub824\ub294 \uc120\ud0dd\uc740 \ud658\uacbd\uc744 \uac71\uc815\ud55c\ub2e4\ub294 \uc120\uc5b8\ubcf4\ub2e4 \ud6e8\uc52c \uad6c\uccb4\uc801\uc778 \uacbd\uc601\uc758 \ubb38\uc81c\uac00 \ub41c\ub2e4. \uc26c\ub098\ub4dc\ub294 \uc57c\uc678 \ud65c\ub3d9\uc5d0 \uc4f0\ub294 \uc758\ub958\ub3c4 \uc2e4\ud5d8\ud588\ub2e4. \uad50\uc7ac\ub294 \uc758\ub958 \ubd80\ubb38\uc774 \uc7a5\ube44 \ubd80\ubb38\ubcf4\ub2e4 \ucee4\uc9c0\uba74\uc11c \ud30c\ud0c0\uace0\ub2c8\uc544 \uc758\ub958 \ube0c\ub79c\ub4dc\ub85c \uc774\uc5b4\uc84c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc624\ub298\uc758 \uc720\uba85\ud55c \ubaa8\uc2b5\uc774 \ucc98\uc74c \uc0ac\uc5c5\uc758 \uc804\ubd80\ub294 \uc544\ub2c8\uc5c8\ub358 \uc148\uc774\ub2e4. \uc637\uc740 \ub4f1\ubc18 \uc7a5\ube44\uc640 \ub2e4\ub978 \uc81c\ud488\uc774\uc9c0\ub9cc \uc57c\uc678\uc5d0\uc11c \ubb34\uc5c7\uc774 \ud544\uc694\ud55c\uc9c0 \uacbd\ud5d8\ud55c \uc0ac\ub78c\uc774\ub77c\ub294 \ubc30\uacbd\uc740 \uc774\uc5b4\uc9c4\ub2e4. \ub3d9\uc2dc\uc5d0 \uc758\ub958\uc5d0\ub294 \uc6d0\uc7ac\ub8cc\uc640 \uc5fc\uc0c9, \uc0dd\uc0b0\uacfc \uc720\ud1b5\uc774\ub77c\ub294 \uc0c8\ub85c\uc6b4 \uc9c8\ubb38\uc774 \uc0dd\uae34\ub2e4. \uc790\uc5f0\uc744 \uc88b\uc544\ud558\ub294 \ucc3d\ub9bd\uc790\uc758 \ub9c8\uc74c\ub9cc\uc73c\ub85c \uc637 \ud55c \ubc8c\uc758 \ud658\uacbd \ubd80\ub2f4\uae4c\uc9c0 \uc790\ub3d9\uc73c\ub85c \ud574\uacb0\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uad50\uc7ac\ub294 \ud30c\ud0c0\uace0\ub2c8\uc544\uac00 \uc7ac\ud65c\uc6a9 \uc6d0\ub8cc\uc640 \uc5fc\ub8cc, \uc5d0\ub108\uc9c0 \uc0ac\uc6a9\uc5d0 \uad00\uc2ec\uc744 \ub450\uc5c8\uace0 \uba74 \uc81c\ud488\uc758 \uc6d0\ub8cc\ub97c \uc720\uae30\ub18d \uba74\uc73c\ub85c \ubc14\uafb8\uc5c8\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \uc774\ub294 \ubaa8\ub4e0 \uc637\uc758 \ubaa8\ub4e0 \uc18c\uc7ac\uac00 \uc720\uae30\ub18d\uc774\ub77c\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ubb34\uc5c7\uc5d0 \uc801\uc6a9\ub41c \uc120\ud0dd\uc778\uc9c0 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ud55c \ubc8c\uc758 \uc637\uc5d0\ub294 \uc5ec\ub7ec \ub2e8\uacc4\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \uc18c\uc7ac\uac00 \ub2ec\ub77c\uc84c\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc804\uccb4 \uc0dd\uc0b0\uc774 \uc5b4\ub290 \uc815\ub3c4 \uc601\ud5a5\uc744 \uc904\uc600\ub294\uc9c0\ub294 \ubcc4\ub3c4\uc758 \uc9c8\ubb38\uc774\ub2e4. \uad6c\uccb4\uc801\uc778 \uc120\ud0dd\uc744 \uc0b4\ud53c\uba74\uc11c\ub3c4 \uc644\uc804\ud788 \ubb34\ud574\ud55c \uc81c\ud488\uc774\ub77c\ub294 \uc774\ubbf8\uc9c0\ub85c \ub113\ud788\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uae30\uc5c5\uc758 \ub178\ub825\uc744 \ud3c9\uac00\ud558\ub294 \ub370\ub3c4 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ube44\uc988\ub2c8\uc2a4 \uc724\ub9ac\uc5d0\uc11c \uc774\ud574\uad00\uacc4\uc790\ub294 \uc8fc\uc8fc\ub098 \uace0\uac1d\ub9cc\uc744 \ub73b\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc9c1\uc6d0\uacfc \uacf5\uae09\uc790, \uc9c0\uc5ed\uc0ac\ud68c, \ud658\uacbd\ucc98\ub7fc \uae30\uc5c5\uc758 \uacb0\uc815\uc73c\ub85c \uc601\ud5a5\uc744 \ubc1b\ub294 \ub300\uc0c1\uae4c\uc9c0 \uc0dd\uac01\ud55c\ub2e4. \ud53c\ud1a4\uc758 \uc0ac\ub840\uc5d0\uc11c\ub294 \ub9e4\ucd9c\uc744 \ub9cc\ub4dc\ub294 \uace0\uac1d\uacfc \ubc14\uc704\uac00 \uc11c\ub85c \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \uc81c\ud488\uc758 \uacb0\uacfc\ub97c \uacbd\ud5d8\ud588\ub2e4. \uc774 \uad00\uc810\uc740 \uae30\uc5c5\uc744 \ub098\uc058\uac70\ub098 \ucc29\ud558\ub2e4\ub294 \ub450 \uce78\uc73c\ub85c \ub098\ub204\uae30 \uc704\ud55c \uc7a5\uce58\ub9cc\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \uc120\ud0dd\uc5d0\uc11c \ub204\uac00 \uc774\uc775\uc744 \uc5bb\uace0 \ub204\uac00 \ubd80\ub2f4\uc744 \uc9c0\ub294\uc9c0 \uad6c\uccb4\uc801\uc73c\ub85c \uc9c8\ubb38\ud558\uac8c \ud55c\ub2e4. \ud658\uacbd \ud65c\ub3d9\uc744 \ud558\ub294 \ud68c\uc0ac\ub3c4 \uc81c\ud488\uc744 \ub9cc\ub4e4\uace0 \ud310\ub9e4\ud558\uba70 \uc790\uc6d0\uc744 \uc0ac\uc6a9\ud55c\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ud568\uaed8 \uc77d\uc744 \uc218 \uc788\ub2e4. \ud68c\uc0ac\uc758 \ucc3d\uc5c5 \uc774\uc57c\uae30\ub294 \uac00\uce58\uad00\uc744 \uc774\ud574\ud558\ub294 \ub370 \uc720\uc6a9\ud558\ub2e4. \uadf8\ub807\ub2e4\uace0 \uadf8 \uc77c\ud654 \ud558\ub098\ub85c \ud604\uc7ac\uc758 \ubaa8\ub4e0 \uc0c1\ud488\uacfc \uacf5\uae09\ub9dd\uc744 \ud3c9\uac00\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc774\ubc88 \uc6d0\uace0\ub294 \uad50\uc7ac\uac00 \uc18c\uac1c\ud55c \uc7a5\ube44 \uc804\ud658\uacfc \ud658\uacbd\uc801 \uc120\ud0dd\uc758 \uc0ac\ub840\uc5d0 \ucd08\uc810\uc744 \ub9de\ucdc4\ub2e4. \ud604\uc7ac \uacbd\uc601\uc9c4\uc774\ub098 \uac1c\ubcc4 \uc81c\ud488\uc758 \uc778\uc99d\uc744 \uc548\ub0b4\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc624\ud788\ub824 \uc88b\uc740 \ucd9c\ubc1c \uc774\uc57c\uae30\ub97c \uc54c\uc218\ub85d \uc774\ud6c4\uc5d0\ub3c4 \uac19\uc740 \uc9c8\ubb38\uc744 \uacc4\uc18d\ud560 \uc218 \uc788\ub2e4. \ubb34\uc5c7\uc744 \ub9cc\ub4e4\uace0 \uc5b4\ub5a4 \uc790\uc6d0\uc744 \uc4f0\ub294\uc9c0, \uc904\uc774\uaca0\ub2e4\uace0 \ud55c \ubd80\ub2f4\uc740 \uc2e4\uc81c\ub85c \uc5b4\ub5bb\uac8c \ub2ec\ub77c\uc84c\ub294\uc9c0 \ud655\uc778\ud558\ub294 \uac83\uc774\ub2e4. \ucc3d\ub9bd\uc790\uc758 \uacb0\ub2e8\uc740 \ub2f5\ubcc0\uc758 \ub05d\ubcf4\ub2e4 \uae30\uc5c5\uc744 \uc77d\ub294 \uc9c8\ubb38\uc758 \ucd9c\ubc1c\uc810\uc774 \ub420 \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\uc5d0\ub294 \ud53c\ud1a4\uacfc \ub2e4\ub978 \uae08\uc18d \uc7a5\ube44, \ubc27\uc904\uacfc \uc57c\uc678 \uc758\ub958\uac00 \ub193\uc5ec \uc788\ub2e4. \uc2e4\uc81c \uc5ed\uc0ac\uc801 \uc81c\ud488\uc744 \uc815\ubc00\ud558\uac8c \ubcf5\uc6d0\ud588\uac70\ub098 \uc7a5\ube44 \uc0ac\uc6a9\uc744 \uac00\ub974\uce58\ub294 \uadf8\ub9bc\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \ubb3c\uac74\uc744 \uacc4\uc18d \ub9cc\ub4e4 \uac83\uc778\uc9c0 \ub2e4\uc2dc \uc0dd\uac01\ud558\ub294 \uc791\uc5c5\ub300\uc758 \ubd84\uc704\uae30\ub97c \ud45c\ud604\ud588\ub2e4. \ud30c\ud0c0\uace0\ub2c8\uc544\uc758 \ucd9c\ubc1c\uc740 \uc790\uc5f0\uc744 \uc88b\uc544\ud558\uba74 \uc0ac\uc5c5\ub3c4 \uc800\uc808\ub85c \uce5c\ud658\uacbd\uc801\uc774 \ub41c\ub2e4\ub294 \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub2e4. \uc88b\uc544\ud558\ub294 \uc7a5\uc18c\uc5d0 \uc790\uae30 \uc81c\ud488\uc774 \ub0a8\uae30\ub294 \uacb0\uacfc\ub97c \ubcf4\uc558\uace0, \uadf8 \ub54c\ubb38\uc5d0 \uc0ac\uc5c5\uc758 \uc77c\ubd80\ub97c \ubc14\uafb8\ub824 \ud588\ub2e4\ub294 \uc774\uc57c\uae30\ub2e4. \uc798 \ud314\ub9ac\ub294 \ub3c4\uad6c\ub97c \ubc14\ub77c\ubcf4\ub2e4\uac00 \uadf8 \ub3c4\uad6c\uac00 \ub2ff\ub294 \ubc14\uc704\ub97c \ubcf4\uac8c \ub41c \uc21c\uac04\uc774 \uc624\ub798 \ub0a8\ub294\ub2e4."}, {"id": "pixar-openusd-many-artists", "title": "\ud53d\uc0ac \u2014 \ud55c \uc7a5\uba74\uc744 \uc5ec\ub7ec \uc0ac\ub78c\uc774 \ud568\uaed8 \ub9cc\ub4e4\ub824\uba74", "summary": "\ud53d\uc0ac\uc758 OpenUSD \uacf5\uc2dd \uc124\uba85\uc744 \ud1b5\ud574 \uc560\ub2c8\uba54\uc774\uc158 \uc7a5\uba74\uc744 \ud568\uaed8 \ub9cc\ub4dc\ub294 \ud611\uc5c5\uc758 \ubb38\uc81c\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "companies", "category_title": "Companies", "subcategory": "Media", "url": "stories/pixar-openusd-many-artists/index.html", "image": "media/pixar-openusd-many-artists.png", "alt": "\uadf8\ub9bc\uacfc \uc791\uc740 \ub098\ubb34 \ubaa8\ud615, \ud654\uba74\uc744 \ub193\uace0 \ud568\uaed8 \uc791\uc5c5\ud558\ub294 \ucc3d\uc791\uc790\ub4e4\uc758 AI \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\ud53d\uc0ac \u2014 \ud55c \uc7a5\uba74\uc744 \uc5ec\ub7ec \uc0ac\ub78c\uc774 \ud568\uaed8 \ub9cc\ub4e4\ub824\uba74 \ub098\ubb34\ub97c \ub9cc\ub4e0 \uc0ac\ub78c\uacfc \ube5b\uc744 \ube44\ucd98 \uc0ac\ub78c\uc774 \ub9cc\ub098\ub294 \uacf5\ud1b5 \uc5b8\uc5b4 \ud53d\uc0ac\uc758 OpenUSD \uacf5\uc2dd \uc124\uba85\uc744 \ud1b5\ud574 \uc560\ub2c8\uba54\uc774\uc158 \uc7a5\uba74\uc744 \ud568\uaed8 \ub9cc\ub4dc\ub294 \ud611\uc5c5\uc758 \ubb38\uc81c\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Media \uae30\uc5c5 \uc560\ub2c8\uba54\uc774\uc158 \uc601\ud654\uc5d0\uc11c \ub098\ubb34 \ud55c \uadf8\ub8e8\uac00 \ubc14\ub78c\uc5d0 \ud754\ub4e4\ub9b0\ub2e4. \uad00\uac1d\uc740 \uc790\uc5f0\uc2a4\ub7fd\uac8c \ud55c \uc7a5\uba74\uc73c\ub85c \ubcf4\uc9c0\ub9cc, \uadf8 \ub098\ubb34\uc758 \ubaa8\uc591\uacfc \ud45c\uba74\uc758 \ub290\ub08c, \uc6c0\uc9c1\uc784\uacfc \ube5b\uc740 \uc11c\ub85c \ub2e4\ub978 \uc791\uc5c5\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc9c8 \uc218 \uc788\ub2e4. \uc774 \ubaa8\ub4e0 \uac83\uc744 \ub9c8\uc9c0\ub9c9\uc5d0 \uc5b4\ub5bb\uac8c \uac19\uc740 \uc138\uacc4 \uc548\uc5d0 \ub193\uc744\uae4c. \ud53d\uc0ac\uc758 \uacf5\uac1c \ud504\ub85c\uc81d\ud2b8 OpenUSD\ub294 \uc774\ub7f0 \uc9c8\ubb38\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uc774\ub984\uc744 \uc678\uc6b0\uac70\ub098 \ud504\ub85c\uadf8\ub7a8\uc744 \ubc30\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5ec\ub7ec \uc0ac\ub78c\uc774 \ub2e4\ub978 \ub3c4\uad6c\ub85c \ub9cc\ub4e0 \uc791\uc5c5\uc744 \ud55c \uc7a5\uba74\uc73c\ub85c \ubaa8\uc73c\ub824\uba74 \uacf5\ud1b5\uc758 \uc57d\uc18d\uc774 \ud544\uc694\ud558\ub2e4\ub294 \uc810\uc5d0\uc11c, \uc601\ud654 \uc81c\uc791\uc758 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc7ac\ubbf8\ub97c \ubc1c\uacac\ud560 \uc218 \uc788\ub2e4. \ud53d\uc0ac\uc758 \uacf5\uc2dd \ubb38\uc11c\ub294 \ubaa8\ub378\ub9c1\uacfc \uc7ac\uc9c8 \ud45c\ud604, \uc560\ub2c8\uba54\uc774\uc158\uacfc \uc870\uba85 \ub4f1 \ub2e4\uc591\ud55c \uc791\uc5c5\uc744 \uc18c\uac1c\ud55c\ub2e4. \ubaa8\uc591\uc744 \ub9cc\ub4dc\ub294 \ub3c4\uad6c\uc640 \uc6c0\uc9c1\uc784\uc744 \ub9cc\ub4dc\ub294 \ub3c4\uad6c\uac00 \uaf2d \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uc815\ubcf4\ub97c \uc800\uc7a5\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uac01 \ub3c4\uad6c\ub294 \uc790\uc2e0\uc774 \uc798\ud558\ub294 \uc77c\uc5d0 \ub9de\ub294 \ud45c\ud604\uc744 \uac16\ub294\ub2e4. \uadf8\ub7f0\ub370 \ub2e4\uc74c \uc0ac\ub78c\uc774 \uadf8 \uc815\ubcf4\ub97c \uc81c\ub300\ub85c \uc77d\uc9c0 \ubabb\ud558\uba74 \uc791\uc5c5\uc744 \uc774\uc5b4 \uac00\uae30 \uc5b4\ub835\ub2e4. \uba4b\uc9c4 \ub098\ubb34\ub97c \ub9cc\ub4e4\uc5c8\uc5b4\ub3c4 \ub2e4\ub978 \ub3c4\uad6c\uc5d0\uc11c \uc704\uce58\ub098 \uc7ac\uc9c8\uc774 \uae30\ub300\uc640 \ub2e4\ub974\uac8c \ub098\ud0c0\ub098\uba74 \ubb38\uc81c\uac00 \ub41c\ub2e4. \uc791\ud488\uc744 \uc798 \ub9cc\ub4dc\ub294 \ub2a5\ub825\uacfc \uc791\uc5c5\uc744 \uc798 \uc804\ub2ec\ud558\ub294 \ub2a5\ub825\uc774 \ud568\uaed8 \ud544\uc694\ud588\ub358 \uac83\uc774\ub2e4. USD\ub294 Universal Scene Description\uc758 \uc57d\uc790\ub2e4. \uc7a5\uba74\uc744 \uad6c\uc131\ud558\ub294 \uc815\ubcf4\ub97c \uacf5\ud1b5\uc758 \ubc29\uc2dd\uc73c\ub85c \uc124\uba85\ud558\uace0 \uc870\ud569\ud558\ub294 \uae30\uc220\ub85c \uc774\ud574\ud558\uba74 \ub41c\ub2e4. \ub098\ubb34\uc758 \ubaa8\uc591\uacfc \uc704\uce58, \uc7ac\uc9c8\uacfc \ube5b\ucc98\ub7fc \uc7a5\uba74\uc744 \ub9cc\ub4dc\ub294 \uc694\uc18c\ub4e4\uc744 \ud568\uaed8 \ub2e4\ub8e8\uae30 \uc704\ud55c \uae30\ubc18\uc774\ub2e4. \uc774\ub294 \uc601\ud654\uc758 \uc904\uac70\ub9ac\ub97c \ubb38\uc7a5\uc73c\ub85c \uc694\uc57d\ud558\ub294 \ud504\ub85c\uadf8\ub7a8\uc774 \uc544\ub2c8\ub2e4. \ucef4\ud4e8\ud130\uac00 \ub2e4\ub8f0 \uc218 \uc788\ub294 3\ucc28\uc6d0 \uc7a5\uba74\uc758 \uc815\ubcf4\ub97c \uc870\uc9c1\ud558\ub294 \ubc29\uc2dd\uc774\ub2e4. \uac89\uc73c\ub85c \ubcf4\uc774\ub294 \uc644\uc131 \uc601\uc0c1\ubcf4\ub2e4 \uadf8 \uc601\uc0c1\uc774 \ub9cc\ub4e4\uc5b4\uc9c0\uae30 \uc804 \uc5ec\ub7ec \uc791\uc5c5\uc744 \uc5f0\uacb0\ud558\ub294 \ucabd\uc5d0 \uad00\uc2ec\uc744 \ub454\ub2e4. \uacf5\uc2dd \ubb38\uc11c\ub294 \uc5ec\ub7ec \uc791\uc5c5\uc790\uac00 \uac01\uc790\uc758 \ud30c\uc77c\uc5d0\uc11c \uc791\uc5c5\ud558\uace0 \uadf8 \uacb0\uacfc\ub97c \ud569\uce58\ub294 \ubc29\uc2dd\uc744 \uc124\uba85\ud55c\ub2e4. \ud30c\uc77c\uc758 \ub2e8\uc704\ub97c \ub808\uc774\uc5b4\ub77c\uace0 \ubd80\ub978\ub2e4. \uac19\uc740 \uc7a5\uba74\uc744 \ub2e4\ub8e8\uba74\uc11c\ub3c4 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc791\uc5c5\uc744 \ubc14\ub85c \uc9c0\uc6b0\uac70\ub098 \uace0\uce58\uc9c0 \uc54a\uace0 \uc790\uc2e0\uc758 \ubcc0\uacbd\uc744 \ub354\ud560 \uc218 \uc788\ub2e4. \ud3b8\uc9d1\uc790\uac00 \uc6d0\ubb38 \uc704\uc5d0 \uc218\uc815 \uc758\uacac\uc744 \ubcc4\ub3c4\ub85c \uc801\ub294 \ubaa8\uc2b5\uc744 \ub5a0\uc62c\ub9ac\uba74 \uccab \uc774\ud574\uc5d0 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ubb3c\ub860 \uc2e4\uc81c \uc7a5\uba74 \ud569\uc131\uc740 \uba54\ubaa8\ub97c \ubd99\uc774\ub294 \uc77c\ubcf4\ub2e4 \ubcf5\uc7a1\ud558\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \ud611\uc5c5\uc744 \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \ud558\ub098\uc758 \ud30c\uc77c\uc744 \ubc88\uac08\uc544 \uc218\uc815\ud558\ub294 \ubc29\uc2dd\uc73c\ub85c\ub9cc \uc0dd\uac01\ud558\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc810\uc774\ub2e4. \uac19\uc740 \uc704\uce58\ub098 \uc18d\uc131\uc5d0 \uc11c\ub85c \ub2e4\ub978 \uac12\uc774 \ub4e4\uc5b4\uc624\uba74 \uc5b4\ub290 \ucabd\uc744 \uc801\uc6a9\ud560\uc9c0 \uc815\ud574\uc838 \uc788\uc5b4\uc57c \ud55c\ub2e4. USD\ub294 \uc774\ub7f0 \uc870\ud569\uc758 \uc21c\uc11c\ub97c \uba85\uc2dc\ud558\ub294 \uad6c\uc870\ub97c \uc81c\uacf5\ud55c\ub2e4. \uc5ec\ub7ec \uc0ac\ub78c\uc758 \uc791\uc5c5\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uc77c\uad00\ub41c \uacb0\uacfc\uac00 \uc800\uc808\ub85c \ub9cc\ub4e4\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\uae30 \ub54c\ubb38\uc774\ub2e4. \uc774\uac83\uc740 \uac00\uc7a5 \ub192\uc740 \uc9c1\uae09\uc758 \uc0ac\ub78c\uc774 \uc5b8\uc81c\ub098 \uc774\uae34\ub2e4\ub294 \uc870\uc9c1 \uaddc\uce59\uacfc\ub294 \ub2e4\ub974\ub2e4. \ud30c\uc77c\uacfc \uc7a5\uba74 \uc815\ubcf4\ub97c \uc5b4\ub5a4 \uc6b0\uc120\uc21c\uc704\ub85c \uc77d\uc744\uc9c0\uc5d0 \uad00\ud55c \uae30\uc220\uc801 \uc57d\uc18d\uc774\ub2e4. \uc0ac\ub78c\uc774 \ubbf8\ub9ac \uc815\ud55c \uc791\uc5c5 \uad00\uacc4\uac00 \uae30\uacc4\uac00 \uc77d\uc744 \uc218 \uc788\ub294 \uad6c\uc870 \uc548\uc5d0\ub3c4 \ud45c\ud604\ub418\ub294 \uc148\uc774\ub2e4. \uacf5\uc2dd \ubb38\uc11c\ub294 \uc774\ub7f0 \ud611\uc5c5\uc774 \ubaa8\ub4e0 \ubb38\uc81c\ub97c \uc790\ub3d9\uc73c\ub85c \ud574\uacb0\ud558\ub294 \ub9cc\ub2a5 \uc7a5\uce58\ub294 \uc544\ub2c8\ub77c\uace0 \uc124\uba85\ud55c\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \ubaa8\uc591\uc744 \ub9cc\ub4dc\ub294 \uc791\uc5c5\uc790\uac00 \ub098\ubb34 \uad6c\uc870\ub97c \ubc14\uafb8\uba74, \uc55e\uc11c \ub2e4\ub978 \uc0ac\ub78c\uc774 \uc124\uc815\ud55c \ud45c\uba74 \ud45c\ud604\uacfc \ub9de\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \ud30c\uc77c\uc744 \ud569\uce60 \uc218 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc218\uc815 \ub4a4\uc5d0\ub3c4 \ubaa8\ub4e0 \uc608\uc220\uc801 \uc120\ud0dd\uc774 \uc801\uc808\ud558\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub2e4\ub974\ub2e4. \uc774\ub54c\ub294 \ubb34\uc5c7\uc774 \ubc14\ub00c\uc5c8\ub294\uc9c0 \ucd94\uc801\ud558\uace0 \uad00\uacc4\ub41c \uc791\uc5c5\uc744 \ub2e4\uc2dc \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uacf5\ud1b5 \uc5b8\uc5b4\ub294 \ub300\ud654\ub97c \uc5c6\uc560\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc11c\ub85c\uc758 \ubcc0\uacbd\uc744 \uc774\ud574\ud558\ub294 \uae30\ubc18\uc744 \ub9cc\ub4e0\ub2e4. \uae30\uc220\uc774 \uc88b\uc544\uc838\ub3c4 \ud568\uaed8 \ud310\ub2e8\ud574\uc57c \ud558\ub294 \uc790\ub9ac\ub294 \ub0a8\ub294\ub2e4. \ud53d\uc0ac\ub294 \uc218\uc815\ud55c \uacb0\uacfc\ub97c \ube60\ub974\uac8c \ud655\uc778\ud558\uace0 \ubc18\ubcf5\ud558\ub294 \ub2a5\ub825\uc744 \uc911\uc694\ud558\uac8c \uc124\uba85\ud55c\ub2e4. \ud55c \ubc88\uc5d0 \uc644\ubcbd\ud55c \ub2f5\uc744 \uc5bb\uae30\ubcf4\ub2e4 \uc5ec\ub7ec \ubc88 \ubcf4\uace0 \uace0\uce58\uba70 \uc7a5\uba74\uc744 \ub2e4\ub4ec\ub294 \uac83\uc774\ub2e4. \ubc14\uafbc \uacb0\uacfc\ub97c \ud655\uc778\ud558\ub294 \ub370 \uc624\ub798 \uac78\ub9ac\uba74 \uc2dc\ub3c4\ud560 \uc218 \uc788\ub294 \ud69f\uc218\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc900\ub2e4. \uc774\ub7f0 \uad00\uc810\uc5d0\uc11c \uc791\uc5c5 \uc18d\ub3c4\ub294 \uc0ac\ub78c\uc744 \ub354 \uc7ac\ucd09\ud558\ub294 \ubb38\uc81c\ub9cc\uc774 \uc544\ub2c8\ub2e4. \uacb0\uacfc\ub97c \uae30\ub2e4\ub9ac\ub294 \uc2dc\uac04\uc744 \uc904\uc5ec \ub2e4\ub978 \uc120\ud0dd\uc744 \uc2dc\ud5d8\ud560 \uc5ec\uc720\ub97c \uc8fc\ub294 \ubb38\uc81c\uac00 \ub420 \uc218 \uc788\ub2e4. \uad00\uac1d\uc5d0\uac8c\ub294 \uc9e7\uac8c \uc9c0\ub098\uac00\ub294 \uc7a5\uba74\uc5d0\ub3c4 \uc5ec\ub7ec \ubc88\uc758 \uad00\ucc30\uacfc \uc218\uc815\uc774 \ub4e4\uc5b4\uac08 \uc218 \uc788\ub2e4. USD\ub294 \ud53d\uc0ac\uc758 \uc81c\uc791 \ud658\uacbd\uc5d0\uc11c \uc911\uc694\ud55c \uae30\ubc18\uc73c\ub85c \uc4f0\uc774\uba70 \uacf5\uac1c \ud504\ub85c\uc81d\ud2b8\ub85c\ub3c4 \uc81c\uacf5\ub41c\ub2e4. \ub2e4\ub978 \ub3c4\uad6c\uc640 \uc791\uc5c5\uc790\uac00 \ud568\uaed8 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 \ubc29\uc2dd\uc774\ub77c\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \uc18c\uc2a4\uac00 \uacf5\uac1c\ub418\uc5c8\ub2e4\uace0 \ud53d\uc0ac\uc758 \ubaa8\ub4e0 \uc791\ud488 \ud30c\uc77c\uacfc \uce90\ub9ad\ud130\uac00 \ud568\uaed8 \uc790\uc720\ub86d\uac8c \ud480\ub9ac\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub610 \uc774 \uae30\uc220 \ud558\ub098\uac00 \uc774\uc57c\uae30\ub97c \uc4f0\uace0 \uc5f0\uae30\ub97c \ub9cc\ub4e4\uba70 \uc644\uc131 \uc601\ud654\ub97c \ub300\uc2e0 \uc81c\uc791\ud558\uc9c0\ub3c4 \uc54a\ub294\ub2e4. \uc7a5\uba74\uc744 \uc5f0\uacb0\ud558\ub294 \uae30\ubc18\uacfc \uac1c\ubcc4 \uc791\ud488\uc758 \ucc3d\uc791\uc740 \uad6c\ubcc4\ub41c\ub2e4. \uacf5\uac1c \uae30\uc220\uc744 \uc774\ud574\ud558\ub294 \uc77c\uc740 \uc601\ud654\uc758 \ube44\ubc00\uc744 \ubaa8\ub450 \uc54c\uc544\ub0b4\ub294 \uc77c\ubcf4\ub2e4, \ud611\uc5c5\uc744 \uac00\ub2a5\ud558\uac8c \ud55c \uc57d\uc18d\uc744 \uc0b4\ud53c\ub294 \ub370 \uac00\uae5d\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uadf8\ub9bc\uacfc \uc791\uc740 \ubaa8\ud615\uc744 \ub193\uace0 \uc758\ub17c\ud558\ub294 \ucc3d\uc791\uc790\ub4e4\uc744 \ud45c\ud604\ud588\ub2e4. \uc2e4\uc81c \ud53d\uc0ac \uc9c1\uc6d0\uc774\ub098 \uc0ac\ubb34\uc2e4, \ud2b9\uc815 \uc601\ud654\uc758 \uc791\uc5c5 \uc7a5\uba74\uc774 \uc544\ub2c8\ub2e4. \uc798 \uc54c\ub824\uc9c4 \uce90\ub9ad\ud130 \ub300\uc2e0 \uc5ec\ub7ec \uc885\ub958\uc758 \ucc3d\uc791\uc774 \ub9cc\ub09c\ub2e4\ub294 \ubd84\uc704\uae30\ub97c \ub2f4\uc558\ub2e4. \ub2e4\uc74c\uc5d0 \uc560\ub2c8\uba54\uc774\uc158\uc758 \uc232\uc744 \ubcf4\uba74 \ub098\ubb34\uc758 \uc0dd\uae40\uc0c8\ubfd0 \uc544\ub2c8\ub77c \ube5b\uacfc \uc6c0\uc9c1\uc784\ub3c4 \ub530\ub85c \ub290\uaef4 \ubcf4\uc790. \uadf8\ub7f0 \ub4a4 \ub2e4\uc2dc \ud55c \uc7a5\uba74\uc73c\ub85c \ubc14\ub77c\ubcf4\uba74 \uc5ec\ub7ec \uc120\ud0dd\uc774 \uc5b4\ub5bb\uac8c \uc5b4\uc6b8\ub9ac\ub294\uc9c0 \ubcf4\uc778\ub2e4. \ud53d\uc0ac\uc758 \uacf5\uac1c \uae30\uc220 \uc774\uc57c\uae30\ub294 \uad00\uac1d\uc774 \uc790\uc5f0\uc2a4\ub7fd\uac8c \ubcf4\ub294 \uc138\uacc4\ub97c \ub9cc\ub4e4\uae30 \uc704\ud574, \ubcf4\uc774\uc9c0 \uc54a\ub294 \uacf3\uc5d0\uc11c \uc5bc\ub9c8\ub098 \ub9ce\uc740 \uc57d\uc18d\uc774 \ud544\uc694\ud588\ub294\uc9c0 \uc54c\ub824 \uc900\ub2e4."}, {"id": "postit-weak-glue-new-use", "title": "3M \u2014 \uc798 \ubd99\uc9c0 \uc54a\ub294 \uc811\ucc29\uc81c\uc758 \uc4f8\ubaa8", "summary": "\ud3ec\uc2a4\ud2b8\uc787\uc758 \ud0c4\uc0dd \uc0ac\ub840\ub85c \uc18c\uc7ac\uc758 \uc131\ub2a5\uacfc \uc0c8\ub85c\uc6b4 \uc4f0\uc784, \uc0ac\ub78c \uc0ac\uc774\uc758 \uc9c0\uc2dd \uc5f0\uacb0\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "companies", "category_title": "Companies", "subcategory": "Technology", "url": "stories/postit-weak-glue-new-use/index.html", "image": "media/postit-weak-glue-new-use.png", "alt": "\ud3bc\uce5c \ucc2c\uc1a1\uac00 \ucc45\uc5d0 \uc791\uc740 \ub178\ub780 \uc885\uc774 \ud45c\uc2dc\ub97c \ubd99\uc774\ub294 \uc190\uc758 \uc0bd\ud654.", "text": "3M \u2014 \uc798 \ubd99\uc9c0 \uc54a\ub294 \uc811\ucc29\uc81c\uc758 \uc4f8\ubaa8 \ub5a8\uc5b4\uc9c0\ub294 \ucc45\uac08\ud53c\uac00 \uc0c8\ub85c\uc6b4 \uc9c8\ubb38\uc744 \ub9cc\ub4e4\ub2e4 \ud3ec\uc2a4\ud2b8\uc787\uc758 \ud0c4\uc0dd \uc0ac\ub840\ub85c \uc18c\uc7ac\uc758 \uc131\ub2a5\uacfc \uc0c8\ub85c\uc6b4 \uc4f0\uc784, \uc0ac\ub78c \uc0ac\uc774\uc758 \uc9c0\uc2dd \uc5f0\uacb0\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Technology \uae30\uc5c5 \uc811\ucc29\uc81c\ub77c\uba74 \ub2e8\ub2e8\ud788 \ubd99\uc5b4\uc57c \uc88b\ub2e4\uace0 \uc0dd\uac01\ud558\uae30 \uc27d\ub2e4. \uadf8\ub7f0\ub370 \ubd99\uc600\ub2e4\uac00 \ub5bc\uc5b4\ub3c4 \uc885\uc774\uac00 \ub9dd\uac00\uc9c0\uc9c0 \uc54a\ub294\ub2e4\uba74 \uc5b4\ub5a8\uae4c. \uc624\ub798 \uace0\uc815\ud558\ub294 \ub370\ub294 \uc544\uc26c\uc6b4 \uc131\uc9c8\uc774 \uc7a0\uae50 \ud45c\uc2dc\ud574 \ub450\ub294 \uc77c\uc5d0\ub294 \uc7a5\uc810\uc774 \ub420 \uc218 \uc788\ub2e4. \uc131\ub2a5\uc740 \ubb34\uc5c7\uc5d0 \uc4f0\ub294\uc9c0\uc5d0 \ub530\ub77c \ub2e4\ub978 \ub73b\uc774 \ub41c\ub2e4. 3M\uc758 \ud3ec\uc2a4\ud2b8\uc787 \uc774\uc57c\uae30\ub294 \uc774\ub7f0 \uc804\ud658\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc0ac\ub840\ub2e4. \ucc98\uc74c\ubd80\ud130 \uc644\uc131\ub41c \uba54\ubaa8\uc9c0\ub97c \ud55c \ubc88\uc5d0 \ubc1c\uba85\ud55c \uc7a5\uba74\uc774 \uc544\ub2c8\ub2e4. \uc0c8\ub85c\uc6b4 \uc18c\uc7ac\ub97c \ub2e4\ub8e8\ub358 \uc0ac\ub78c\uacfc \ucc45\uac08\ud53c\uc758 \ubd88\ud3b8\uc744 \uacaa\ub358 \uc0ac\ub78c\uc758 \uc0dd\uac01\uc774 \uc774\uc5b4\uc84c\ub2e4. \uc720\uba85\ud55c \ub178\ub780 \uba54\ubaa8\uc9c0\ub294 \uc11c\ub85c \ub2e4\ub978 \uc9c8\ubb38\uc774 \ub9cc\ub09c \uacb0\uacfc\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \uad50\uc7ac\ub294 3M \uc5f0\uad6c\uc2e4\uc5d0\uc11c \uc0c8\ub85c\uc6b4 \uc811\ucc29 \uc18c\uc7ac\ub97c \uc5f0\uad6c\ud558\ub358 \uc911 \uc2a4\ud39c\uc11c \uc2e4\ubc84\uac00 \uc57d\ud558\uac8c \ubd99\ub294 \uc131\uc9c8\uc758 \uc18c\uc7ac\ub97c \ub9cc\ub4e4\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub2f9\uc2dc\uc5d0\ub294 \ubd84\uba85\ud55c \uc4f0\uc784\uc744 \ucc3e\uc9c0 \ubabb\ud588\ub2e4. \uc0c8\ub85c\uc6b4 \ubb3c\uc9c8\uc774 \uc0dd\uacbc\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc0ac\ub78c\ub4e4\uc774 \uc0b4 \uc81c\ud488\uc774 \uc0dd\uacbc\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub2ec\ub790\ub2e4. \uc774 \ub300\ubaa9\uc744 \uac15\ud55c \uc811\ucc29\uc81c \ub9cc\ub4e4\uae30\uc5d0 \uc2e4\ud328\ud588\uc73c\ub2c8 \ubb34\uc5c7\uc774\ub4e0 \uad1c\ucc2e\ub2e4\ub294 \uad50\ud6c8\uc73c\ub85c \ubc14\uafb8\uba74 \ub108\ubb34 \uac04\ub2e8\ud558\ub2e4. \uad6c\uccb4\uc801\uc73c\ub85c \uc5b4\ub5a4 \uc131\uc9c8\uc774 \uc788\uc5c8\uace0 \uadf8 \uc131\uc9c8\uc744 \uc5b4\ub5a4 \ud544\uc694\uc640 \uc5f0\uacb0\ud560 \uc218 \uc788\ub294\uc9c0\uac00 \uc911\uc694\ud558\ub2e4. \uacb0\uacfc\ub97c \ub2e4\uc2dc \ubc14\ub77c\ubcfc \uadfc\uac70\uac00 \uc788\uc5b4\uc57c \uc0c8\ub85c\uc6b4 \uc4f0\uc784\ub3c4 \ucc3e\uc744 \uc218 \uc788\ub2e4. \uc544\ud2b8 \ud504\ub77c\uc774\ub294 \uad50\ud68c \ucc2c\uc1a1\uac00 \ucc45\uc758 \ud45c\uc2dc\uac00 \uc790\uafb8 \ub5a8\uc5b4\uc9c0\ub294 \ubd88\ud3b8\uc744 \uacaa\uc5c8\ub2e4\uace0 \uad50\uc7ac\ub294 \uc18c\uac1c\ud55c\ub2e4. \ud3bc\uce60 \uc790\ub9ac\ub97c \uc54c\ub824 \uc8fc\uc5b4\uc57c \ud558\ub294\ub370 \uc885\uc774 \ud45c\uc2dc\uac00 \uadf8 \uc5ed\ud560\uc744 \uc81c\ub300\ub85c \ud558\uc9c0 \ubabb\ud588\ub358 \uac83\uc774\ub2e4. \ubb3c\uac74\uc740 \uc791\uc544\ub3c4 \ubc18\ubcf5\ub418\ub294 \ubd88\ud3b8\uc740 \ubd84\uba85\ud588\ub2e4. \uadf8\ub294 \uc2e4\ubc84\uc758 \uc18c\uc7ac\uac00 \uc885\uc774\uc5d0 \ubd99\uc5b4 \uc788\uc73c\uba74\uc11c \ud544\uc694\ud560 \ub54c \uc885\uc774\ub97c \uc190\uc0c1\uc2dc\ud0a4\uc9c0 \uc54a\uace0 \ub5a8\uc5b4\uc9c8 \uc218 \uc788\ub2e4\ub294 \uc810\uc5d0 \uc8fc\ubaa9\ud588\ub2e4. \uac19\uc740 \uc131\uc9c8\uc774 \uc5f0\uad6c\uc2e4\uc758 \uc6a9\ub3c4 \uc5c6\ub294 \uacb0\uacfc\uc5d0\uc11c \ucc45\uc744 \uc77d\ub294 \uc0ac\ub78c\uc758 \ud574\uacb0\ucc45\uc73c\ub85c \ubc14\ub00c\uc5c8\ub2e4. \uc18c\uc7ac\uc640 \ud544\uc694\uac00 \ub9cc\ub098\ub294 \uc21c\uac04\uc774\ub2e4. \ucc45\uac08\ud53c\uc5d0\ub294 \uc11c\ub85c \ub2e4\ub978 \uc694\uad6c\uac00 \ud568\uaed8 \uc788\ub2e4. \uc27d\uac8c \ub5a8\uc5b4\uc9c0\uc9c0 \uc54a\uc544\uc57c \ud558\uc9c0\ub9cc \ud544\uc694\ud55c \ub54c\uc5d0\ub294 \uc62e\uae38 \uc218 \uc788\uc5b4\uc57c \ud55c\ub2e4. \uac15\ud558\uac8c \uace0\uc815\ud558\ub294 \ub2a5\ub825\ub9cc \ub192\uc774\uba74 \uc624\ud788\ub824 \ucc45\uc744 \uc190\uc0c1\uc2dc\ud0a4\uac70\ub098 \uc704\uce58\ub97c \ubc14\uafb8\uae30 \uc5b4\ub824\uc6cc\uc9c8 \uc218 \uc788\ub2e4. \uc81c\ud488\uc744 \uc0dd\uac01\ud560 \ub54c \ud55c \uac00\uc9c0 \uc131\ub2a5\uc744 \ucd5c\uace0\ub85c \ub9cc\ub4dc\ub294 \uac83\uacfc \uc804\uccb4 \uc6a9\ub3c4\uc5d0 \ub9de\ucd94\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \uc774 \uacbd\uc6b0\uc5d0\ub294 \uc801\uc808\ud788 \ubd99\uace0 \uc798 \ub5a8\uc5b4\uc9c0\ub294 \uad00\uacc4\uac00 \uc911\uc694\ud588\ub2e4. \uc88b\uc9c0 \uc54a\uc740 \uc131\ub2a5\uc73c\ub85c \ubcf4\uc600\ub358 \ubd80\ubd84\uc774 \ub2e4\ub978 \uc0ac\uc6a9\uc5d0\uc11c\ub294 \ud544\uc694\ud55c \uade0\ud615\uc774 \ub420 \uc218 \uc788\ub2e4\ub294 \uc810\uc774 \ud765\ubbf8\ub86d\ub2e4. \ud504\ub77c\uc774\ub294 \uadf8 \uc18c\uc7ac\ub97c \ud398\uc774\uc9c0 \ud45c\uc2dc\uc640 \uba54\ubaa8\uc9c0\uc5d0 \uc801\uc6a9\ud574 \ubcf4\uc558\ub2e4. \uad50\uc7ac\ub294 \uc774\ub7f0 \uc2e4\ud5d8\uc774 \ud3ec\uc2a4\ud2b8\uc787 \uc81c\ud488\uc73c\ub85c \uc774\uc5b4\uc84c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub5a0\uc624\ub978 \uc0dd\uac01\uc744 \ubc14\ub85c \uc644\uc131\ud488\uc774\ub77c\uace0 \ubd80\ub974\ub294 \ub300\uc2e0 \uc2e4\uc81c\ub85c \uc5b4\ub5bb\uac8c \uc4f8 \uc218 \uc788\ub294\uc9c0 \uc2dc\ud5d8\ud55c \uacfc\uc815\uc774 \uc788\uc5c8\ub2e4. \ucc45\uac08\ud53c\uc640 \uc9e7\uc740 \uba54\ubaa8\ub294 \ub2ee\uc558\uc9c0\ub9cc \uac19\uc740 \ubb3c\uac74\uc740 \uc544\ub2c8\ub2e4. \ud558\ub098\ub294 \uc704\uce58\ub97c \uc54c\ub824 \uc8fc\uace0 \ub2e4\ub978 \ud558\ub098\ub294 \ub0b4\uc6a9\uc744 \uc7a0\uc2dc \ub0a8\uae34\ub2e4. \ub5bc\uc5b4 \uc62e\uae38 \uc218 \uc788\ub2e4\ub294 \uc131\uc9c8\uc774 \ub450 \uc0ac\uc6a9\uc744 \uc5f0\uacb0\ud588\ub2e4. \uc0c8 \uc81c\ud488\uc740 \uc18c\uc7ac \ud558\ub098\ubfd0 \uc544\ub2c8\ub77c \ud06c\uae30\uc640 \uc4f0\ub294 \ubc29\uc2dd, \uc0ac\uc6a9\ud558\ub294 \uc0ac\ub78c\uc774 \uc774\ud574\ud558\ub294 \ubaa9\uc801\uae4c\uc9c0 \ud544\uc694\ub85c \ud55c\ub2e4. \uc774 \uc0ac\ub840\ub97c \ud55c \uba85\uc758 \ucc9c\uc7ac\uac00 \uc6b0\uc5f0\ud788 \uc138\uc0c1\uc744 \ubc14\uafbc \uc7a5\uba74\uc73c\ub85c\ub9cc \uc124\uba85\ud558\uba74 \uc911\uc694\ud55c \uad00\uacc4\uac00 \ube60\uc9c4\ub2e4. \uc18c\uc7ac\ub97c \ub9cc\ub4e0 \uc0ac\ub78c\uacfc \uadf8\uac83\uc758 \uc4f0\uc784\uc744 \ucc3e\uc740 \uc0ac\ub78c\uc774 \uc11c\ub85c \ub2e4\ub978 \ubb38\uc81c\ub97c \ubcf4\uace0 \uc788\uc5c8\ub2e4. \ud55c \uc0ac\ub78c\uc774 \uc54c\uace0 \uc788\ub358 \uac83\uc774 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uc758\ubbf8\uac00 \ub418\uc5c8\ub2e4. \uadf8\ub798\uc11c \uae30\uc5c5\uc758 \ud601\uc2e0\uc744 \uc0dd\uac01\ud560 \ub54c \uc544\uc774\ub514\uc5b4\ub97c \ud63c\uc790 \uc798 \ub0b4\ub294 \ub2a5\ub825\ub9cc \ubcfc \uc218\ub294 \uc5c6\ub2e4. \ub2e4\ub978 \uc0ac\ub78c\uc774 \ud55c \uc77c\uc744 \uc54c\uc544\ubcf4\uace0 \ud544\uc694\ud55c \uacf3\uc5d0 \uc5f0\uacb0\ud558\ub294 \ud658\uacbd\ub3c4 \uc911\uc694\ud558\ub2e4. \uc0c8\ub85c\uc6b4 \ubc1c\uacac\uc774 \ubcf4\uad00\ub9cc \ub418\uace0 \ub204\uad6c\uc5d0\uac8c\ub3c4 \uc54c\ub824\uc9c0\uc9c0 \uc54a\uc558\ub2e4\uba74 \ub2e4\ub978 \uacb0\uacfc\uac00 \ub098\uc654\uc744 \uc218 \uc788\ub2e4\ub294 \uc9c8\ubb38\uc744 \ud574 \ubcfc \uc218 \uc788\ub2e4. \ub2e4\ub978 \uacbd\uc601\ud559 \uc124\uba85\uc5d0\uc11c \uad50\uc7ac\ub294 3M\uc758 \ud601\uc2e0 \ud65c\ub3d9\uc5d0 \uc9c1\uc6d0\uc774 \uc790\uae30 \uc544\uc774\ub514\uc5b4\ub97c \ud0d0\uc0c9\ud560 \uc5ec\uc720\uac00 \uc911\uc694\ud588\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \ubc1c\uacac\uc744 \uc2e4\uc81c \uc81c\ud488\uc73c\ub85c \uc62e\uae30\ub824\uba74 \uc2e4\ud5d8\ud558\uace0 \ub2e4\uc2dc \ud655\uc778\ud558\ub294 \uc2dc\uac04\uc774 \ud544\uc694\ud558\uae30 \ub54c\ubb38\uc774\ub2e4. \uc774\uac83\uc740 \ud604\uc7ac \ubaa8\ub4e0 \ubd80\uc11c\uc758 \uc815\ud655\ud55c \uadfc\ubb34 \uaddc\uce59\uc744 \uc548\ub0b4\ud558\ub294 \ub9d0\uc740 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \ub2f9\uc7a5 \uc815\ud574\uc9c4 \uc791\uc5c5\ub9cc\uc73c\ub85c \ud3c9\uac00\ud558\uba74 \uc544\uc9c1 \uc6a9\ub3c4\uac00 \ubd84\uba85\ud558\uc9c0 \uc54a\uc740 \uacb0\uacfc\ub97c \uc0b4\ud53c\uae30 \uc5b4\ub835\ub2e4\ub294 \uc810\uc740 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ubc18\ub300\ub85c \uc2dc\uac04\uc744 \uc8fc\uc5c8\ub2e4\uace0 \ubaa8\ub4e0 \uc2dc\ub3c4\uac00 \uc81c\ud488\uc774 \ub418\ub294 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \ud0d0\uc0c9\uc744 \ud5c8\uc6a9\ud558\ub294 \uac83\uacfc \uc5b4\ub5a4 \uc544\uc774\ub514\uc5b4\ub97c \uacc4\uc18d\ud560\uc9c0 \ud310\ub2e8\ud558\ub294 \uc77c\uc740 \ud568\uaed8 \ud544\uc694\ud558\ub2e4. \ud3ec\uc2a4\ud2b8\uc787\uc744 \uc6b0\uc5f0\uc758 \ubc1c\uba85\uc774\ub77c\uace0 \ubd80\ub974\ub294 \ub9d0\uc5d0\ub294 \uae30\uc5b5\ud558\uae30 \uc88b\uc740 \ubd80\ubd84\uc774 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \ub4a4\uc5d0\ub294 \uc18c\uc7ac\uc758 \uc131\uc9c8\uc744 \uc774\ud574\ud558\uace0 \ub2e4\ub978 \uc0ac\uc6a9\uc744 \ub5a0\uc62c\ub9ac\uba70 \uc2dc\ud5d8\ud55c \uc0ac\ub78c\ub4e4\uc774 \uc788\ub2e4. \uc6b0\uc5f0\ud788 \uc5bb\uc740 \uacb0\uacfc\uc640 \uadf8\uac83\uc744 \uc0ac\ub78c\uc758 \ubb3c\uac74\uc73c\ub85c \ubc14\uafb8\ub294 \uacfc\uc815\uc740 \ub098\ub204\uc5b4 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc774\ubc88 \uc6d0\uace0\ub294 \uad50\uc7ac\uc5d0 \uc18c\uac1c\ub41c \ud0c4\uc0dd \uc0ac\ub840\ub97c \uc77d\ub294 \uac83\uc774\ub2e4. \ud2b9\uc815 \ud604\uc7ac \uc81c\ud488\uc758 \uc811\ucc29\ub825\uc774\ub098 \ubaa8\ub4e0 \uc885\uc774\uc5d0\uc11c\uc758 \uc131\ub2a5\uc744 \ubcf4\uc99d\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc0dd\ud65c \uc18d\uc758 \ubc1c\uba85\ub2f4\uc744 \uc81c\ud488 \uc0ac\uc6a9 \uc2dc\ud5d8\uacfc \uad6c\ubcc4\ud558\uba74, \uc88b\uc740 \uc774\uc57c\uae30 \ub54c\ubb38\uc5d0 \ud655\uc778\ud558\uc9c0 \uc54a\uc740 \uae30\ub2a5\uae4c\uc9c0 \ub367\ubd99\uc774\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \ucc45\uc5d0 \ubd99\uc778 \uc791\uc740 \ud45c\uc2dc\ub97c \ub4e4\uc5b4 \uc62c\ub9ac\ub294 \uc7a5\uba74\uc774\ub2e4. \uc2e4\uc81c \ud504\ub77c\uc774\uc758 \ucd08\uc0c1\uc774\ub098 \ub2f9\uc2dc\uc758 \ucc2c\uc1a1\uac00, \ucd5c\ucd08 \uc2dc\uc81c\ud488\uc744 \uc7ac\ud604\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \ubd99\uc774\ub294 \uc77c\uacfc \ub5bc\ub294 \uc77c\uc774 \ud568\uaed8 \ud544\uc694\ud55c \uc0c1\ud669\uc744 \ubcf4\uc5ec \uc8fc\ub294 \ubd84\uc704\uae30 \uadf8\ub9bc\uc774\ub2e4. \ud3ec\uc2a4\ud2b8\uc787\uc758 \ucd9c\ubc1c\uc740 \ubaa8\ub4e0 \uc2e4\ud328\ub97c \ubb34\uc870\uac74 \uc131\uacf5\uc774\ub77c \ubd80\ub974\uc790\ub294 \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub2e4. \ubb34\uc5c7\uc5d0 \uc4f8 \ub54c \uc88b\uc740 \uc131\uc9c8\uc778\uc9c0 \ub2e4\uc2dc \ubb3b\ub294 \uc774\uc57c\uae30\ub2e4. \uc885\uc774\uac00 \ub5a8\uc5b4\uc9c0\ub294 \ubd88\ud3b8\uacfc \uc57d\ud558\uac8c \ubd99\ub294 \uc18c\uc7ac\uac00 \ub9cc\ub0ac\uc744 \ub54c, \ub530\ub85c \ubcf4\uba74 \uc544\uc26c\uc6e0\ub358 \ub450 \uc0c1\ud669\uc774 \uc775\uc219\ud55c \uba54\ubaa8\uc9c0\uc758 \uc2dc\uc791\uc774 \ub418\uc5c8\ub2e4."}, {"id": "sony-vinyl-records-return", "title": "\uc18c\ub2c8 \u2014 \ud3b8\ub9ac\ud55c \uc74c\uc545 \uc2dc\ub300\uc5d0 \ub808\ucf54\ub4dc\ub97c \ub2e4\uc2dc \ub9cc\ub4e4\uaca0\ub2e4\uace0 \ud55c \uc774\uc720", "summary": "2017\ub144 \uc18c\ub2c8\uc758 \ub808\ucf54\ub4dc \uc0dd\uc0b0 \uc7ac\uac1c \ubc1c\ud45c\ub97c \ucd9c\ubc1c\uc810\uc73c\ub85c \uc74c\uc545\uc744 \ub4e3\ub294 \ubc29\uc2dd\uacfc \uc81c\ud488 \uac00\uce58\uc758 \ubcc0\ud654\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "companies", "category_title": "Companies", "subcategory": "Technology", "url": "stories/sony-vinyl-records-return/index.html", "image": "media/sony-vinyl-records-return.png", "alt": "\ub808\ucf54\ub4dc \uac00\uac8c\uc5d0\uc11c \ud070 \ubc14\uc774\ub2d0 \uc74c\ubc18\uc744 \uc870\uc2ec\uc2a4\ub7fd\uac8c \ub4e4\uace0 \ud134\ud14c\uc774\ube14\uc5d0 \ub193\uc73c\ub824\ub294 AI \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\uc18c\ub2c8 \u2014 \ud3b8\ub9ac\ud55c \uc74c\uc545 \uc2dc\ub300\uc5d0 \ub808\ucf54\ub4dc\ub97c \ub2e4\uc2dc \ub9cc\ub4e4\uaca0\ub2e4\uace0 \ud55c \uc774\uc720 \ub0a1\uc740 \ub9e4\uccb4\uac00 \uc0c8\ub85c\uc6b4 \uc120\ud0dd\uc774 \ub420 \ub54c 2017\ub144 \uc18c\ub2c8\uc758 \ub808\ucf54\ub4dc \uc0dd\uc0b0 \uc7ac\uac1c \ubc1c\ud45c\ub97c \ucd9c\ubc1c\uc810\uc73c\ub85c \uc74c\uc545\uc744 \ub4e3\ub294 \ubc29\uc2dd\uacfc \uc81c\ud488 \uac00\uce58\uc758 \ubcc0\ud654\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Technology \uae30\uc5c5 \ub178\ub798\ub97c \ub4e3\uae30 \uc704\ud574 \ucee4\ub2e4\ub780 \uc6d0\ubc18\uc744 \uaebc\ub0b8\ub2e4. \ubaa8\uc11c\ub9ac\ub97c \uc870\uc2ec\ud574\uc11c \uc7a1\uace0 \ud134\ud14c\uc774\ube14 \uc704\uc5d0 \uc62c\ub9b0 \ub2e4\uc74c \ubc14\ub298\uc744 \ub0b4\ub9b0\ub2e4. \uc2a4\ub9c8\ud2b8\ud3f0\uc5d0\uc11c \uace1\uc744 \uace0\ub974\ub294 \uac83\uacfc \ube44\uad50\ud558\uba74 \uc190\uc774 \ub9ce\uc774 \uac04\ub2e4. \uadf8\ub7f0\ub370 \ubc14\ub85c \uadf8 \ubc88\uac70\ub85c\uc6b4 \uacfc\uc815 \ub54c\ubb38\uc5d0 \ub808\ucf54\ub4dc\ub97c \ucc3e\ub294 \uc0ac\ub78c\ub3c4 \uc788\ub2e4. \uc18c\ub2c8\ub294 2017\ub144 \ubc14\uc774\ub2d0 \ub808\ucf54\ub4dc \uc0dd\uc0b0\uc744 \ub2e4\uc2dc \uc2dc\uc791\ud558\uaca0\ub2e4\uace0 \ubc1c\ud45c\ud588\ub2e4. OpenStax\uc758 \uacbd\uc601\ud559 \uad50\uc7ac\ub294 1989\ub144 \uc774\ud6c4 \uc774\uc5b4\uc9c4 \uc0dd\uc0b0 \uacf5\ubc31\uacfc \uc774 \uc7ac\uac1c \ubc1c\ud45c\ub97c \uc624\ub798\ub41c \ub9e4\uccb4\uc758 \uadc0\ud658 \uc0ac\ub840\ub85c \uc18c\uac1c\ud55c\ub2e4. \ub354 \ud3b8\ub9ac\ud55c \uae30\uc220\uc774 \ub4f1\uc7a5\ud588\ub294\ub370\ub3c4 \uc608\uc804 \ubc29\uc2dd\uc774 \ub3cc\uc544\uc628 \uae4c\ub2ed\uc740 \ubb34\uc5c7\uc774\uc5c8\uc744\uae4c. \uc74c\uc545 \ub9e4\uccb4\uc758 \ubcc0\ud654\ub97c \ud55c \uc904\ub85c \uadf8\ub9ac\uba74 \ub808\ucf54\ub4dc\uc5d0\uc11c CD, \ub514\uc9c0\ud138 \ud30c\uc77c\uacfc \uc2a4\ud2b8\ub9ac\ubc0d\uc73c\ub85c \uc774\ub3d9\ud55c \uac83\ucc98\ub7fc \ubcf4\uc778\ub2e4. \uc774 \ud750\ub984\ub9cc \ubcf4\uba74 \uc55e\uc120 \ubc29\uc2dd\uc740 \ub4a4\uc758 \ubc29\uc2dd\uc5d0 \uc790\ub9ac\ub97c \ub0b4\uc8fc\uace0 \uc0ac\ub77c\uc838\uc57c \ud560 \uac83 \uac19\ub2e4. \ud558\uc9c0\ub9cc \uc0ac\ub78c\ub4e4\uc758 \uc120\ud0dd\uc740 \ud56d\uc0c1 \uadf8\ub807\uac8c \ub2e8\uc21c\ud558\uac8c \uc815\ub9ac\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc0c8 \ubc29\uc2dd\uc774 \uc774\ub3d9\uacfc \uac80\uc0c9, \ubcf4\uad00\uc5d0\uc11c \ud3b8\ub9ac\ud574\uc838\ub3c4 \uae30\uc874 \ubb3c\uac74\uc5d0\uc11c \uc88b\uc544\ud558\ub358 \uacbd\ud5d8\uae4c\uc9c0 \ubaa8\ub450 \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\uc744 \uc218 \uc788\ub2e4. \uad50\uc7ac\ub294 \ubc14\uc774\ub2d0\uc758 \uc778\uae30\ub97c \uc124\uba85\ud558\uba70 \uc2e4\ubb3c \ub9e4\uccb4\ub97c \ub2e4\ub8e8\ub294 \uac10\uac01\uacfc \uc74c\uc545\uc744 \ub4e3\ub294 \uacbd\ud5d8\uc5d0 \uad00\uc2ec\uc744 \ub3cc\ub9b0\ub2e4. \ubb34\uc5c7\uc774 \ub354 \uc0c8\ub85c\uc6b4\uac00\uc640 \ubb34\uc5c7\uc744 \uc990\uae30\ub294\uac00\ub294 \uac19\uc740 \uc9c8\ubb38\uc774 \uc544\ub2c8\ub2e4. \ub808\ucf54\ub4dc\uc5d0\ub294 \uc18c\ub9ac\ub9cc \ub4e4\uc5b4 \uc788\uc9c0 \uc54a\ub2e4. \ucee4\ub2e4\ub780 \uc7ac\ud0b7\uc744 \ud3bc\uccd0 \uadf8\ub9bc\uacfc \uae00\uc744 \ubcf4\uace0, \uc190\uc5d0 \ub4e0 \ubb3c\uac74\uc744 \uc120\ubc18\uc5d0 \uaf42\ub294 \uacbd\ud5d8\uc774 \uc788\ub2e4. \uac19\uc740 \uace1\uc744 \ub4e4\uc5b4\ub3c4 \uc568\ubc94\uc744 \ud558\ub098\uc758 \ubb3c\uac74\uc73c\ub85c \ub9cc\ub098\uac8c \ub41c\ub2e4. \ud654\uba74\uc758 \uc791\uc740 \ud45c\uc9c0 \uadf8\ub9bc\uacfc\ub294 \ub2e4\ub978 \ud06c\uae30\uc640 \ucd09\uac10\uc774 \uc0dd\uae34\ub2e4. \ubb3c\ub860 \ubaa8\ub4e0 \uad6c\ub9e4\uc790\uac00 \uac19\uc740 \uc774\uc720\ub85c \ub808\ucf54\ub4dc\ub97c \uc88b\uc544\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \uc0ac\ub78c\uc740 \uc18c\uc7a5\uc744 \uc990\uae30\uace0 \uc5b4\ub5a4 \uc0ac\ub78c\uc740 \ub4e3\ub294 \uc7a5\uce58\ub97c \ub9cc\uc9c0\ub294 \uacfc\uc815\uc744 \uc88b\uc544\ud560 \uc218 \uc788\ub2e4. \uae30\uc5c5\uc774 \uad00\ucc30\ud574\uc57c \ud558\ub294 \uac83\uc740 \uc61b \ub9e4\uccb4\uac00 \ubb34\uc870\uac74 \uc6b0\uc6d4\ud558\ub2e4\ub294 \uacb0\ub860\ubcf4\ub2e4, \uadf8 \ubb3c\uac74\uc744 \ud1b5\ud574 \uace0\uac1d\uc774 \uc5b4\ub5a4 \uc990\uac70\uc6c0\uc744 \uc5bb\uace0 \uc788\ub294\uc9c0\ub2e4. \uc74c\ubc18\uc744 \uaebc\ub0b4\uace0 \ud134\ud14c\uc774\ube14\uc744 \uc900\ube44\ud558\ub294 \uc2dc\uac04\uc740 \ud6a8\uc728\ub9cc \uc0dd\uac01\ud558\uba74 \uc904\uc5ec\uc57c \ud560 \uacfc\uc815\uc774\ub2e4. \uadf8\ub7ec\ub098 \ucde8\ubbf8\uc5d0\uc11c\ub294 \uc900\ube44 \uc790\uccb4\uac00 \uacbd\ud5d8\uc758 \uc77c\ubd80\uac00 \ub418\uae30\ub3c4 \ud55c\ub2e4. \ucc28\ub97c \uc6b0\ub9ac\ub294 \ub3c4\uad6c\ub97c \uace0\ub974\ub294 \uc77c\uc774\ub098 \ucc45\uc758 \uccab \uc7a5\uc744 \ud3bc\uce58\ub294 \uc77c\uc744 \ub5a0\uc62c\ub9ac\uba74 \uc774\ud574\ud558\uae30 \uc27d\ub2e4. \uc774\uac83\uc740 \ubb3c\uac74\uc744 \uc624\ub798 \uc900\ube44\ud560\uc218\ub85d \ubc18\ub4dc\uc2dc \ub354 \uae4a\uac8c \uac10\uc0c1\ud55c\ub2e4\ub294 \ub9d0\uc740 \uc544\ub2c8\ub2e4. \uc774\ub3d9 \uc911\uc5d0 \ud3b8\ud558\uac8c \ub4e3\ub294 \uc74c\uc545\uc5d0\ub3c4 \uc790\uae30\ub9cc\uc758 \uac00\uce58\uac00 \uc788\ub2e4. \ub2e4\ub9cc \uc5b4\ub5a4 \ub54c\uc5d0\ub294 \uc989\uc2dc \uc7ac\uc0dd\ud558\ub294 \ud3b8\ub9ac\ud568\ubcf4\ub2e4 \uc74c\uc545\uc744 \ub4e3\uae30\ub85c \ub9c8\uc74c\uba39\ub294 \uc808\ucc28\uac00 \uc18c\uc911\ud574\uc9c8 \uc218 \uc788\ub2e4. \uac19\uc740 \uc0ac\ub78c\ub3c4 \uc0c1\ud669\uc5d0 \ub530\ub77c \ub2e4\ub978 \ubc29\uc2dd\uc744 \uace0\ub978\ub2e4. \uad50\uc7ac\uac00 \uc18c\uac1c\ud558\ub294 \uc18c\ub2c8\uc758 2017\ub144 \ubc1c\ud45c\ub294 \uc774\ub7f0 \uc18c\ube44 \ubcc0\ud654\uc5d0 \uae30\uc5c5\uc774 \ubc18\uc751\ud55c \uc0ac\ub840\ub2e4. \uc774\uc804\uc5d0 \uba48\ucd94\uc5c8\ub358 \uc81c\ud488\uc744 \ub2e4\uc2dc \uc0dd\uc0b0\ud558\ub824\uba74 \uc218\uc694\uac00 \uc788\ub294\uc9c0 \uc0b4\ud53c\uace0 \uc0dd\uc0b0 \ub2a5\ub825\uc744 \uc900\ube44\ud574\uc57c \ud55c\ub2e4. \uace0\uac1d\uc758 \uad00\uc2ec\uc744 \uc2e4\uc81c \ubb3c\uac74\uc73c\ub85c \ubc14\uafb8\ub294 \ub2e8\uacc4\uac00 \ub530\ub85c \uc788\ub294 \uac83\uc774\ub2e4. \uc624\ub798\ub41c \ud615\uc2dd\uc774\ub77c\uace0 \ub2e4\uc2dc \ub9cc\ub4dc\ub294 \uc77c\uc774 \uc800\uc808\ub85c \uc26c\uc6cc\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc81c\uc870 \uae30\uc220\uacfc \uc124\ube44, \ud568\uaed8 \uc77c\ud560 \uc0ac\ub78c\uacfc \uacf5\uae09 \uacfc\uc815\uc774 \ud544\uc694\ud558\ub2e4. \uc5ec\uae30\uc11c \ud655\uc778\ud55c \uac83\uc740 \uc0dd\uc0b0 \uc7ac\uac1c\ub97c \uc54c\ub9b0 \ub2f9\uc2dc\uc758 \ubc1c\ud45c\ub2e4. \uc774 \uae00\uc5d0\uc11c \ud2b9\uc815 \uacf5\uc7a5\uc758 \ud604\uc7ac \uac00\ub3d9 \uc0c1\ud669\uc774\ub098 \ucd5c\uc2e0 \ud310\ub9e4\ub7c9\uae4c\uc9c0 \ud655\uc778\ud55c \uac83\uc73c\ub85c \ub113\ud600 \uc77d\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub808\ucf54\ub4dc\uc758 \uc778\uae30\ub97c \uacfc\uac70\uc5d0 \ub300\ud55c \ud5a5\uc218 \ud558\ub098\ub85c\ub9cc \uc124\uba85\ud558\uba74 \uc80a\uc740 \uad6c\ub9e4\uc790\ub97c \uc774\ud574\ud558\uae30 \uc5b4\ub835\ub2e4. \uc790\uc2e0\uc774 \uacbd\ud5d8\ud558\uc9c0 \ubabb\ud55c \ubc29\uc2dd\uc774\uc5b4\uc11c \uc624\ud788\ub824 \uc0c8\ub86d\uac8c \ub290\ub084 \uc218\ub3c4 \uc788\ub2e4. \uc190\uc73c\ub85c \ub2e4\ub8e8\ub294 \ub9e4\uccb4\ub97c \ucc98\uc74c \ub9cc\ub098\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc624\ub798\ub41c \ubb3c\uac74\uacfc \uc0c8\ub85c\uc6b4 \uacbd\ud5d8\uc774 \uac19\uc740 \ub300\uc0c1\uc774\ub2e4. \uad50\uc7ac\ub3c4 \ub514\uc9c0\ud138 \ud658\uacbd\uc5d0 \uc775\uc219\ud55c \uc138\ub300\uac00 \uc2e4\ubb3c \uc74c\ubc18\uc744 \ucc3e\ub294 \ud604\uc0c1\uc5d0 \uc8fc\ubaa9\ud55c\ub2e4. \uc5b4\ub5a4 \ub9e4\uccb4\ub97c \uc0ac\uc6a9\ud55c \uc2dc\uc808\uc758 \uae30\uc5b5\uacfc \uadf8 \ub9e4\uccb4\ub97c \uc9c0\uae08 \uc120\ud0dd\ud558\ub294 \uc774\uc720\ub294 \uc77c\uce58\ud558\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \uae30\uc5c5 \uc785\uc7a5\uc5d0\uc11c\ub294 \uae30\uc874 \uace0\uac1d\uc774 \ub3cc\uc544\uc624\ub294 \uc2dc\uc7a5\uacfc \uc0c8 \uace0\uac1d\uc774 \ucc98\uc74c \ub4e4\uc5b4\uc624\ub294 \uc2dc\uc7a5\uc744 \ud568\uaed8 \uc0b4\ud3b4\uc57c \ud558\ub294 \uc148\uc774\ub2e4. \ub808\ucf54\ub4dc\ub97c \ub450\uace0\ub294 \ub530\ub73b\ud55c \uc18c\ub9ac\ub77c\ub294 \ud45c\ud604\uc774 \uc790\uc8fc \ub4f1\uc7a5\ud55c\ub2e4. \uadf8\ub7ec\ub098 \uadf8\ub7f0 \uac10\uc0c1\uc744 \ubaa8\ub4e0 \uc7a5\uce58\uc640 \uc74c\uc6d0\uc5d0 \ub300\ud55c \uac1d\uad00\uc801\uc778 \uc6b0\uc5f4 \ud310\uc815\uc73c\ub85c \ubc14\uafc0 \uc218\ub294 \uc5c6\ub2e4. \ub179\uc74c\uacfc \uc81c\uc791, \uc7ac\uc0dd \uae30\uae30\uc640 \uc74c\ubc18 \uc0c1\ud0dc\uc5d0 \ub530\ub77c \uc2e4\uc81c\ub85c \ub4e3\ub294 \uacb0\uacfc\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \uc774 \uc774\uc57c\uae30\ub294 \ub808\ucf54\ub4dc\uac00 \uc5b8\uc81c\ub098 \ub354 \uc815\ud655\ud55c \uc18c\ub9ac\ub97c \ub0b8\ub2e4\ub294 \uc8fc\uc7a5\uc774 \uc544\ub2c8\ub2e4. \uc18c\ub9ac\ub97c \ud3ec\ud568\ud574 \ud45c\uc9c0\uc640 \uc18c\uc7a5, \uc900\ube44\ud558\ub294 \ub3d9\uc791\uae4c\uc9c0 \ud55c\ub370 \ubb36\uc778 \uacbd\ud5d8\uc774 \ub2e4\uc2dc \uc120\ud0dd\ub420 \uc218 \uc788\ub2e4\ub294 \uc124\uba85\uc774\ub2e4. \uae30\uc220\uc758 \uc131\ub2a5\uacfc \uc81c\ud488\uc774 \uc8fc\ub294 \uc990\uac70\uc6c0\uc744 \uad6c\ubd84\ud558\uba74 \uc88b\uc544\ud558\ub294 \ucde8\ud5a5\uc744 \uacfc\uc7a5\ub41c \uacfc\ud559 \uc124\uba85\uc73c\ub85c \ubc29\uc5b4\ud560 \ud544\uc694\ub3c4 \uc904\uc5b4\ub4e0\ub2e4. \uc5b4\ub5a4 \ub0a1\uc740 \uc81c\ud488\uc774\ub4e0 \ub2e4\uc2dc \ub9cc\ub4e4\uae30\ub9cc \ud558\uba74 \uc131\uacf5\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc2e4\uc81c\ub85c \uc6d0\ud558\ub294 \uc0ac\ub78c\uc774 \uc788\uc5b4\uc57c \ud558\uace0, \uadf8 \uc0ac\ub78c\uc5d0\uac8c \uac00\uaca9\uacfc \ud488\uc9c8, \uad6c\ud560 \uc218 \uc788\ub294 \ubb3c\ub7c9\uc774 \ub9de\uc544\uc57c \ud55c\ub2e4. \ub808\ucf54\ub4dc\uc758 \uadc0\ud658\uc740 \ubaa8\ub4e0 \ubcf5\uace0 \uc0c1\ud488\uc5d0 \ud1b5\ud558\ub294 \ub9c8\ubc95\uc758 \uacf5\uc2dd\uc774 \uc544\ub2c8\ub2e4. \ub300\uc2e0 \uc81c\ud488\uc758 \uac00\uce58\ub294 \uae30\ub2a5 \ubaa9\ub85d\ub9cc\uc73c\ub85c \ub2e4 \uc124\uba85\ub418\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc810\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc74c\uc545\uc744 \ub4e4\uc744 \uc218 \uc788\ub2e4\ub294 \uae30\ubcf8 \uae30\ub2a5\uc774 \uac19\uc544\ub3c4, \uace0\uac1d\uc774 \uace0\ub974\ub294 \uac83\uc740 \uc11c\ub85c \ub2e4\ub978 \uc804\uccb4 \uacbd\ud5d8\uc77c \uc218 \uc788\ub2e4. \uae30\uc5c5\uc774 \uae30\uc220\uc758 \uc21c\uc11c\ub9cc \ubcf4\uace0 \uace0\uac1d\uc758 \ucde8\ud5a5\uc744 \ub300\uc2e0 \uacb0\uc815\ud560 \uc218 \uc5c6\ub294 \uc774\uc720\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\uc740 \ub808\ucf54\ub4dc\ub97c \uace0\ub974\uace0 \ub2e4\ub8e8\ub294 \uc7a5\uba74\uc744 \ud45c\ud604\ud55c AI \uc0bd\ud654\ub2e4. \ud2b9\uc815 \uc18c\ub2c8 \uc81c\ud488\uc774\ub098 \uc2e4\uc81c \uc0dd\uc0b0 \ud604\uc7a5\uc744 \uc7ac\ud604\ud558\uc9c0 \uc54a\uc558\ub2e4. \uae30\uae30 \uc774\ub984\ubcf4\ub2e4 \uc74c\ubc18\uc744 \uc7a1\uc740 \uc190, \ucee4\ub2e4\ub780 \ud45c\uc9c0, \ub4e3\uae30 \uc804\uc5d0 \ube44\uc6cc \ub454 \uc7a0\uae50\uc758 \uc2dc\uac04\uc744 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uc18c\ub2c8\uc758 \uc7ac\uac1c \ubc1c\ud45c\uac00 \ud765\ubbf8\ub85c\uc6b4 \uae4c\ub2ed\uc740 \uc138\uc0c1\uc774 \uacfc\uac70\ub85c \ub3cc\uc544\uac14\uae30 \ub54c\ubb38\uc774 \uc544\ub2c8\ub2e4. \ud3b8\ub9ac\ud55c \ubc29\uc2dd\uc774 \ub110\ub9ac \uc4f0\uc774\ub294 \uac00\uc6b4\ub370 \ub2e4\ub978 \ubc29\uc2dd\uc758 \uc990\uac70\uc6c0\ub3c4 \uc0b4\uc544\ub0a8\uc558\uae30 \ub54c\ubb38\uc774\ub2e4. \uc624\ub798\ub41c \ub9e4\uccb4\ub294 \ub54c\ub85c \uae30\uc220 \uacbd\uc7c1\uc758 \ud328\uc790\uac00 \uc544\ub2c8\ub77c, \uc74c\uc545\uc744 \uc870\uae08 \ub2e4\ub974\uac8c \ub9cc\ub098\ub824\ub294 \uc0ac\ub78c\uc758 \uc0c8\ub85c\uc6b4 \uc120\ud0dd\uc774 \ub41c\ub2e4."}, {"id": "tass-stencil-posters", "title": "\ud3ec\uc2a4\ud130\ub97c \ud55c \uc7a5\uc529 \ubd93\uc73c\ub85c \uce60\ud558\ub358 \uc791\uc5c5\uc7a5", "summary": "\uc804\uc7c1\uae30 \uc18c\ub828\uc758 \ud0c0\uc2a4 \ud3ec\uc2a4\ud130\uac00 \uc5ec\ub7ec \uc7a5\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc9c0\ub358 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "companies", "category_title": "Companies", "subcategory": "Media", "url": "stories/tass-stencil-posters/index.html", "image": "media/tass-stencil-posters.jpg", "alt": "\ud3ec\uc2a4\ud130\ub97c \ud55c \uc7a5\uc529 \ubd93\uc73c\ub85c \uce60\ud558\ub358 \uc791\uc5c5\uc7a5\uc758 \ub0b4\uc6a9\uc744 \ub3d5\ub294 \uc124\uba85\uc6a9 \uc774\ubbf8\uc9c0", "text": "\ud3ec\uc2a4\ud130\ub97c \ud55c \uc7a5\uc529 \ubd93\uc73c\ub85c \uce60\ud558\ub358 \uc791\uc5c5\uc7a5 \ubaa8\uc2a4\ud06c\ubc14\uc758 \ubcbd\uae4c\uc9c0 \uc774\uc5b4\uc9c4 \uc885\uc774\uc640 \ud2c0 \uc804\uc7c1\uae30 \uc18c\ub828\uc758 \ud0c0\uc2a4 \ud3ec\uc2a4\ud130\uac00 \uc5ec\ub7ec \uc7a5\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc9c0\ub358 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Media \uae30\uc5c5 \uac19\uc740 \ud3ec\uc2a4\ud130\ub97c \uc5ec\ub7ec \uc7a5 \ub9cc\ub4e0\ub2e4\uace0 \ud558\uba74 \uc778\uc1c4\uae30\ub97c \uba3c\uc800 \uc0dd\uac01\ud55c\ub2e4. \uadf8\ub7f0\ub370 \uc81c2\ucc28 \uc138\uacc4\ub300\uc804\uae30\uc758 \uc18c\ub828 \ud0c0\uc2a4 \ud3ec\uc2a4\ud130 \uc911\uc5d0\ub294 \uc798\ub77c \ub9cc\ub4e0 \ud2c0\uc744 \ub300\uace0 \ud55c \uc7a5\uc529 \uc0c9\uc744 \uce60\ud55c \uac83\ub4e4\uc774 \uc788\uc5c8\ub2e4. \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc740 \ubaa8\uc2a4\ud06c\ubc14\uc758 \uc791\uc5c5\uc7a5\uc5d0\uc11c \uc774\ub7f0 \ud3ec\uc2a4\ud130\ub97c \uc81c\uc791\ud55c \uacfc\uc815\uc744 \uc18c\uac1c\ud55c\ub2e4. \uadf8\ub9bc\uc744 \uadf8\ub9ac\ub294 \uc77c\uacfc \uc5ec\ub7ec \uc0ac\ub78c\uc5d0\uac8c \uac19\uc740 \uc774\ubbf8\uc9c0\ub97c \ubcf4\ub0b4\ub294 \uc77c\uc774 \ud55c \uc791\uc5c5\uc7a5 \uc548\uc5d0\uc11c \ub9cc\ub0ac\ub2e4. \ud0c0\uc2a4\ub294 \ub2f9\uc2dc \uc18c\ub828\uc758 \uc911\uc559 \ud1b5\uc2e0 \uae30\uad00\uc774\uc5c8\ub2e4. \uc804\uc7c1 \uc18c\uc2dd\uc744 \uc0b4\ud53c\ub358 \ud654\uac00\uc640 \uc0bd\ud654\uac00, \uc2dc\uc778\uacfc \uc791\uac00\ub4e4\uc774 \ud3ec\uc2a4\ud130 \uc81c\uc791\uc5d0 \ucc38\uc5ec\ud588\ub2e4. \uc804\ud669\uc744 \uc804\ub2ec\ud558\ub294 \ub3d9\uc2dc\uc5d0 \uc0ac\ub78c\ub4e4\uc744 \uc124\ub4dd\ud558\uace0 \uc0ac\uae30\ub97c \ubd81\ub3cb\uc6b0\ub824\ub294 \uc120\uc804 \ub9e4\uccb4\uc774\uae30\ub3c4 \ud588\ub2e4. \ub514\uc790\uc778\uc774 \uc815\ud574\uc9c0\uba74 \uadf8\uac83\uc744 \ubc14\ud0d5\uc73c\ub85c \uc190\uc73c\ub85c \uc790\ub978 \uc2a4\ud150\uc2e4\uc744 \ub9cc\ub4e4\uc5c8\ub2e4. \uc2a4\ud150\uc2e4\uc740 \uc0c9\uc744 \ub123\uc744 \ubd80\ubd84\uc774 \ub6ab\ub9b0 \ud2c0\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uba74 \ub41c\ub2e4. \uac19\uc740 \ud2c0\uc744 \ubc18\ubcf5\ud574 \ub300\uba74 \ube44\uc2b7\ud55c \ubaa8\uc591\uc744 \uc5ec\ub7ec \uc885\uc774\uc5d0 \uc62e\uae38 \uc218 \uc788\ub2e4. \ubbf8\uc220\uad00\uc758 \uc124\uba85\uc5d0 \ub530\ub974\uba74 \uc791\uc5c5\uc790\ub4e4\uc740 \ud2c0\uc744 \uc0ac\uc6a9\ud574 \uc0c9 \ubd80\ubd84\uc744 \uce60\ud558\uace0 \ub354 \ub2e4\ub4ec\uc5c8\ub2e4. \uc644\uc131\ud55c \uc885\uc774 \uc870\uac01\ub4e4\uc740 \uae00\uc774 \uc801\ud78c \ud328\ub110\uacfc \ud0c0\uc2a4 \ubc88\ud638\ub97c \ub354\ud574 \ubd99\uc600\ub2e4. \uac70\ub300\ud55c \ud55c \uc7a5\ucc98\ub7fc \ubcf4\uc774\ub294 \uc774\ubbf8\uc9c0\uc5d0\ub3c4 \uc774\uc5b4 \ubd99\uc774\ub294 \uacfc\uc815\uc774 \uc788\uc5c8\ub2e4. \uadf8\ub798\uc11c \ud3ec\uc2a4\ud130\ub294 \ud654\uac00 \ud63c\uc790 \uadf8\ub9bc \ud55c \uc810\uc744 \ub05d\ub0b4\ub294 \uc77c\uacfc\ub294 \ub2e4\ub978 \uc81c\uc791 \uccb4\uacc4\ub97c \uac00\uc84c\ub2e4. \ud2c0\uc744 \uc790\ub974\ub294 \uc77c, \uce60\ud558\ub294 \uc77c, \uc870\uac01\uc744 \ub9de\ucd94\ub294 \uc77c\uc774 \uc5f0\uacb0\ub418\uba70 \uc5ec\ub7ec \uc7a5\uc758 \uacb0\uacfc\ubb3c\uc774 \ub098\uc654\ub2e4. \uc2a4\ud150\uc2e4\uc740 \uad6c\uba4d\uc774 \ub09c \ud2c0\uc744 \ud1b5\ud574 \uc0c9\uc744 \uc885\uc774\uc5d0 \uc62e\uae30\ub294 \ubc29\uc2dd\uc774\ub2e4. \uc0c9\uc744 \ub2ec\ub9ac\ud558\ub824\uba74 \ud544\uc694\ud55c \ubd80\ubd84\uc744 \uad6c\ubd84\ud558\uace0 \ud2c0\uc744 \ub9de\ucd94\uc5b4\uc57c \ud55c\ub2e4. \ud55c \uc7a5\uc5d0 \uce60\ud55c \ud615\uc0c1\uc744 \ub2e4\uc74c \uc7a5\uc5d0\uc11c\ub3c4 \ube44\uc2b7\ud55c \uc790\ub9ac\uc5d0 \ub193\uc73c\ub824\uba74 \uc791\uc5c5 \uc21c\uc11c\uac00 \uc911\uc694\ud574\uc9c4\ub2e4. \uac19\uc740 \uadf8\ub9bc\uc744 \uc5ec\ub7ec \uc7a5 \ub9cc\ub4e0\ub2e4\ub294 \ub9d0 \uc548\uc5d0 \ubc18\ubcf5\ud574\uc11c \uc190\uc744 \uc6c0\uc9c1\uc774\ub294 \uc77c\uc774 \ub4e4\uc5b4 \uc788\uc5c8\ub2e4. \uc774\ub7f0 \uc81c\uc791\uc5d0\uc11c\ub294 \ub514\uc790\uc778\uc744 \uace0\uc548\ud558\ub294 \uc0ac\ub78c\uacfc \uc2e4\uc81c \uc885\uc774\uc5d0 \uc0c9\uc744 \uc62c\ub9ac\ub294 \uc0ac\ub78c\uc758 \uc5ed\ud560\uc774 \uc774\uc5b4\uc9c4\ub2e4. \ud654\uac00 \ud55c \uba85\uc758 \uc774\ub984\uc73c\ub85c\ub9cc \uae30\uc5b5\ud558\uba74 \ud2c0\uc744 \uc790\ub974\uace0 \uc704\uce58\ub97c \ub9de\ucd94\uace0 \uc885\uc774\ub97c \ubd99\uc778 \uc791\uc5c5\uc774 \ubcf4\uc774\uc9c0 \uc54a\uac8c \ub41c\ub2e4. \uc644\uc131\ud55c \ud3ec\uc2a4\ud130\uc758 \ud070 \ud654\uba74 \ub4a4\uc5d0 \uc791\uc740 \uacf5\uc815\ub4e4\uc774 \uc5f0\uacb0\ub418\uc5b4 \uc788\ub2e4\ub294 \uc810\uc744 \uc54c\uace0 \ubcf4\uba74 \uc190\uc73c\ub85c \ub9cc\ub4e0 \ubcf5\uc81c\ub77c\ub294 \ub9d0\ub3c4 \uc870\uae08 \uad6c\uccb4\uc801\uc73c\ub85c \ub4e4\ub9b0\ub2e4. \ubbf8\uc220\uad00 \uc124\uba85\uc5d0\ub294 \uc2dc\uc778\uacfc \uc791\uac00\uc758 \ucc38\uc5ec\uac00 \ud568\uaed8 \ub098\uc628\ub2e4. \uc774\ubbf8\uc9c0\ub97c \ub9cc\ub4e4\uace0 \ub098\uc11c \uae00\uc774 \ub0a8\ub294 \uc790\ub9ac\ub97c \uc544\ubb34 \ub9d0\ub85c \ucc44\uc6b4 \uac83\uc774 \uc544\ub2c8\ub2e4. \uadf8\ub9bc\uc758 \uc7a5\uba74\uacfc \ubb38\uc7a5\uc758 \uc5b4\uc870\uac00 \ud568\uaed8 \uad00\ub78c\uc790\uc758 \ubc18\uc751\uc744 \uc774\ub048\ub2e4. \uc6c3\uc74c\uc774\ub098 \ubd84\ub178, \uacbd\uacc4\uc2ec\uc744 \uc5b4\ub5a4 \ub300\uc0c1\uc73c\ub85c \ud5a5\ud558\uac8c \ud560\uc9c0 \uc815\ud558\ub294 \ub370\uc5d0\ub294 \ub9d0\uacfc \uc774\ubbf8\uc9c0 \ubaa8\ub450 \uc5ed\ud560\uc744 \ud560 \uc218 \uc788\ub2e4. \uc804\uc7c1\uae30\uc758 \uc120\uc804\ubb3c\uc774\ub77c\ub294 \uc131\uaca9\ub3c4 \uc5ec\uae30\uc11c \uc911\uc694\ud574\uc9c4\ub2e4. \uc2e4\uc81c \uc804\ud669\uc744 \uc54c\ub9ac\ub294 \uae30\ub2a5\uacfc \uc0ac\ub78c\uc744 \ud2b9\uc815\ud55c \ubc29\ud5a5\uc73c\ub85c \uc124\ub4dd\ud558\ub294 \uae30\ub2a5\uc740 \ud568\uaed8 \uc788\uc744 \uc218 \uc788\ub2e4. \ud3ec\uc2a4\ud130\uc5d0 \uc801\ud600 \uc788\ub2e4\uace0 \ubaa8\ub4e0 \uc8fc\uc7a5\uc744 \uc911\ub9bd\uc801\uc778 \ub274\uc2a4\ucc98\ub7fc \ubc1b\uc544\ub4e4\uc77c \uc218\ub294 \uc5c6\ub2e4. \ub204\uac00 \ub9cc\ub4e4\uc5c8\uace0 \ub204\uad6c\ub97c \ud5a5\ud588\uc73c\uba70 \uc5b4\ub5a4 \uac10\uc815\uc744 \uc694\uad6c\ud558\ub294\uc9c0 \ud568\uaed8 \uc77d\uc73c\uba74 \uc608\uc220\uacfc \uc815\ubcf4\uc758 \uad00\uacc4\uac00 \ub354 \uc120\uba85\ud574\uc9c4\ub2e4. \ucee4\ub2e4\ub780 \uc774\ubbf8\uc9c0\uac00 \uc5ec\ub7ec \uc885\uc774 \uc870\uac01\uacfc \uae00 \ud328\ub110, \ubc88\ud638\uc758 \uacb0\ud569\uc73c\ub85c \uc644\uc131\ub418\uc5c8\ub2e4\ub294 \uc810\uc740 \ubb3c\uac74\uc744 \ubcf4\ub294 \uc21c\uc11c\ub97c \ubc14\uafbc\ub2e4. \uba40\ub9ac\uc11c\ub294 \ud558\ub098\uc758 \uc7a5\uba74\uc774\uc9c0\ub9cc \uac00\uae4c\uc774\uc5d0\uc11c\ub294 \uc774\uc5b4 \ubd99\uc778 \ubd80\ubd84\uacfc \uc0c9\uc744 \ub098\ub208 \ud754\uc801\uc744 \ucc3e\uc744 \uc218 \uc788\ub2e4. \uadf8\ub9bc\uc758 \ub0b4\uc6a9\ubfd0 \uc544\ub2c8\ub77c \uadf8\uac83\uc774 \uc5b4\ub5a4 \ub2e8\uc704\ub85c \ub9cc\ub4e4\uc5b4\uc84c\ub294\uc9c0\ub3c4 \uc9c8\ubb38\ud560 \uc218 \uc788\ub2e4. \uc5ec\uae30\uc758 \uc0bd\ud654\ub294 \uc774 \uacf5\uc815\uc744 \uc774\ud574\ud558\uae30 \uc704\ud55c \uac1c\ub150 \uadf8\ub9bc\uc774\ub2e4. \ud2b9\uc815 \uc6d0\ubcf8 \ud3ec\uc2a4\ud130\uc758 \uc811\ud569 \uc704\uce58\ub098 \ubd93 \uc790\uad6d\uc744 \ud655\uc778\ud558\ub294 \uc790\ub8cc\ub85c \uc0ac\uc6a9\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc2e4\uc81c \uc791\ud488\uc758 \uc0ac\uc9c4\uc744 \ubcfc \ub54c\uc5d0\ub294 \uc778\ubb3c\uacfc \ubb38\uc7a5\ubd80\ud130 \ubcf8 \ub4a4 \uc885\uc774\uc758 \uac00\uc7a5\uc790\ub9ac\ub85c \ub208\uc744 \uc62e\uaca8 \ubcf4\uc790. \uba54\uc2dc\uc9c0\uc758 \ud070 \ubaa9\uc18c\ub9ac \uc544\ub798\uc5d0 \uc190\uc73c\ub85c \uc870\ub9bd\ud55c \ubb3c\uac74\uc758 \uad6c\uc870\uac00 \ub0a8\uc544 \uc788\uc744 \uc218 \uc788\ub2e4. \uc0c1\uc810\uacfc \uacf5\uc7a5, \uacf5\uacf5 \uac74\ubb3c\uc740 \uc0ac\ub78c\ub4e4\uc774 \uc774\ubbf8 \ub2e4\ub978 \ubaa9\uc801\uc744 \uac00\uc9c0\uace0 \ub2e4\ub2c8\ub358 \uc7a5\uc18c\ub2e4. \uadf8\uacf3\uc758 \ud3ec\uc2a4\ud130\ub294 \ubbf8\uc220\uad00\uc758 \uc791\ud488\ucc98\ub7fc \uac10\uc0c1 \uc2dc\uac04\uc744 \ub530\ub85c \ub9c8\ub828\ud55c \uad00\ub78c\uc790\ub9cc \ub9cc\ub098\uc9c0 \uc54a\ub294\ub2e4. \uc77c\uc744 \ud558\uac70\ub098 \ubb3c\uac74\uc744 \uc0ac\ub7ec \uac00\ub294 \uae38\uc5d0 \uc7a0\uc2dc \uc2dc\uc120\uc744 \ubd99\uc7a1\uc544\uc57c \ud55c\ub2e4. \uba54\uc2dc\uc9c0\uac00 \uc5b4\ub514\uc5d0 \ub193\uc774\ub294\uc9c0\uac00 \ud45c\ud604\uc758 \uc131\uaca9\uacfc \uc5f0\uacb0\ub418\ub294 \uc774\uc720\ub2e4. \uc791\uc5c5\uc7a5\uc758 \uc81c\uc791 \ubc29\uc2dd\uacfc \uac70\ub9ac\uc758 \ubc30\ud3ec\ub97c \uc774\uc5b4 \uc0dd\uac01\ud558\uba74 \uc608\uc220\uc774 \uc0ac\ud68c \uc548\uc5d0\uc11c \uc6c0\uc9c1\uc774\ub294 \uacbd\ub85c\uac00 \ubcf4\uc778\ub2e4. \ud55c \uc7a5\uc758 \uc774\ubbf8\uc9c0\ub97c \ub9cc\ub4dc\ub294 \ub370\uc11c \ub05d\ub098\uc9c0 \uc54a\uace0 \uc5ec\ub7ec \uc7a5\uc73c\ub85c \ub098\ub258\uc5b4 \ub2e4\ub978 \uc7a5\uc18c\uc758 \uc0ac\ub78c\uc5d0\uac8c \ub3c4\ucc29\ud55c\ub2e4. \uc5b4\ub5a4 \uc8fc\uc7a5\uc744 \ub2f4\uc558\ub294\uc9c0 \ube44\ud310\uc801\uc73c\ub85c \uc77d\ub294 \uc77c\uacfc, \uadf8 \uc8fc\uc7a5\uc744 \ud37c\ub728\ub9b0 \ubb3c\uac74\uc758 \ud615\ud0dc\ub97c \uc0b4\ud53c\ub294 \uc77c\uc740 \ud568\uaed8 \ud560 \uc218 \uc788\ub2e4. \uc774\ub807\uac8c \ub9cc\ub4e0 \ud3ec\uc2a4\ud130\ub294 \ubaa8\uc2a4\ud06c\ubc14\uc758 \uc0c1\uc810\uacfc \uacf5\uc7a5, \uacf5\uacf5 \uac74\ubb3c \ub4f1\uc73c\ub85c \ubcf4\ub0b4\uc84c\ub2e4. \uac10\uc0c1\ud558\ub824\uace0 \ucc3e\uc544\uc624\ub294 \uc804\uc2dc\uc7a5\ub9cc\uc774 \uc544\ub2c8\ub77c \uc0ac\ub78c\ub4e4\uc774 \uc9c0\ub098\ub294 \uc0dd\ud65c \uacf5\uac04\uc744 \ub9cc\ub098\ub294 \ub9e4\uccb4\uc600\ub2e4. \uc5ec\uae30\uc11c\ub294 \ud2b9\uc815 \ud3ec\uc2a4\ud130\ub97c \ubaa8\uc0ac\ud558\uc9c0 \uc54a\uace0 \uc81c\uc791 \uacfc\uc815\uc744 \ub5a0\uc62c\ub9ac\ub294 \uc0bd\ud654\ub97c \ud568\uaed8 \uc2e4\uc5c8\ub2e4. \uadf8\ub9bc\uc774 \ubb34\uc5c7\uc744 \uc8fc\uc7a5\ud588\ub294\uc9c0\uc640 \ud568\uaed8 \uc5b4\ub5bb\uac8c \ub9cc\ub4e4\uc5b4\uc838 \uc5b4\ub514\ub85c \uac14\ub294\uc9c0\ub3c4 \ubb3c\uc5b4\ubcfc \uc218 \uc788\ub2e4. \uc885\uc774 \ud55c \uc7a5\uc758 \uc774\uc57c\uae30\uac00 \uc791\uc5c5\uc7a5\uc758 \uc190\uacfc \ub3c4\uc2dc\uc758 \ubcbd\uae4c\uc9c0 \ub113\uc5b4\uc9c0\ub294 \uc21c\uac04\uc774\ub2e4."}, {"id": "toyota-inventory-and-timing", "title": "\ud1a0\uc694\ud0c0 \u2014 \ucc3d\uace0\uac00 \uac00\ub4dd \ucc28\uba74 \uc548\uc2ec\ud574\ub3c4 \ub420\uae4c", "summary": "\ub9b0 \uc0dd\uc0b0\uacfc \uc801\uc2dc \uacf5\uae09\uc758 \uc6d0\ub9ac\uc5d0\uc11c \uc7ac\uace0\u00b7\ud611\ub825\u00b7\ud488\uc9c8\uc744 \ud568\uaed8 \uc124\uacc4\ud558\ub294 \ubb38\uc81c\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "companies", "category_title": "Companies", "subcategory": "Automotive", "url": "stories/toyota-inventory-and-timing/index.html", "image": "media/toyota-inventory-and-timing.png", "alt": "\uc790\ub3d9\ucc28 \uc870\ub9bd \uc791\uc5c5\uc7a5\uc5d0\uc11c \uc791\uc740 \ubd80\ud488\uc744 \ud568\uaed8 \ud655\uc778\ud558\ub294 \ub450 \uc791\uc5c5\uc790\uc758 AI \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\ud1a0\uc694\ud0c0 \u2014 \ucc3d\uace0\uac00 \uac00\ub4dd \ucc28\uba74 \uc548\uc2ec\ud574\ub3c4 \ub420\uae4c \ub9ce\uc774 \uc313\uc544 \ub450\ub294 \uc77c\uacfc \uc798 \ub9cc\ub4dc\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4 \ub9b0 \uc0dd\uc0b0\uacfc \uc801\uc2dc \uacf5\uae09\uc758 \uc6d0\ub9ac\uc5d0\uc11c \uc7ac\uace0\u00b7\ud611\ub825\u00b7\ud488\uc9c8\uc744 \ud568\uaed8 \uc124\uacc4\ud558\ub294 \ubb38\uc81c\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Automotive \uae30\uc5c5 \uc790\ub3d9\ucc28 \uacf5\uc7a5 \uc606 \ucc3d\uace0\uc5d0 \ubd80\ud488\uc774 \ucc9c\uc7a5 \uac00\uae4c\uc774 \uc313\uc5ec \uc788\ub2e4. \uc774 \uc815\ub3c4\uba74 \ud55c\ub3d9\uc548 \uac71\uc815 \uc5c6\uc774 \ucc28\ub97c \ub9cc\ub4e4 \uc218 \uc788\uc744 \uac83 \uac19\ub2e4. \uadf8\ub7f0\ub370 \uacf5\uc7a5\uc744 \uc6b4\uc601\ud558\ub294 \uc0ac\ub78c\uc740 \ub2e4\ub978 \uc9c8\ubb38\uc744 \ud560 \uc218\ub3c4 \uc788\ub2e4. \uc9c0\uae08 \ud544\uc694\ud55c \uac83\uc740 \uc774 \uac00\uc6b4\ub370 \ubb34\uc5c7\uc774\uace0, \uc65c \ub098\uba38\uc9c0\ub294 \uae30\ub2e4\ub9ac\uace0 \uc788\uc744\uae4c. \ud1a0\uc694\ud0c0\ub294 \ubd88\ud544\uc694\ud55c \uacfc\uc815\uc744 \uc904\uc774\ub294 \ub9b0 \uc0dd\uc0b0\uc744 \ubc1c\uc804\uc2dc\ud0a8 \uc120\ub3c4 \uae30\uc5c5\uc73c\ub85c \uc54c\ub824\uc838 \uc788\ub2e4. \uc5b4\ub824\uc6b4 \uacbd\uc601 \uc6a9\uc5b4\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc \ucd9c\ubc1c\uc810\uc740 \uc77c\uc0c1\uc801\uc774\ub2e4. \ub354 \ub9ce\uc774 \uc0ac \ub450\uace0 \ub354 \ube68\ub9ac \uc6c0\uc9c1\uc774\ub294 \uac83\ub9cc\uc73c\ub85c \uc88b\uc740 \ubb3c\uac74\uc774 \uc81c\ub54c \ub9cc\ub4e4\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc0dd\uac01\uc774\ub2e4. \uc11c\ub78d\uc5d0 \uac74\uc804\uc9c0\uac00 \uac00\ub4dd\ud55c\ub370 \ub9ac\ubaa8\ucee8\uc5d0 \ub9de\ub294 \uaddc\uaca9\uc740 \uc5c6\ub294 \uc0c1\ud669\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc218\ub7c9\uc740 \ub9ce\uc544\ub3c4 \ub2f9\uc7a5 \ud544\uc694\ud55c \uc77c\uc744 \ud574\uacb0\ud558\uc9c0 \ubabb\ud55c\ub2e4. \uacf5\uc7a5\uc5d0\uc11c\ub3c4 \ubd80\ud488 \uc804\uccb4\uc758 \uc591\uacfc \uc2e4\uc81c\ub85c \uc9c0\uae08 \uc870\ub9bd\ud574\uc57c \ud558\ub294 \ubb3c\uac74\uc758 \ud544\uc694\ub294 \uad6c\ubcc4\ub41c\ub2e4. \uc774\uac83\uc740 \uc6d0\ub9ac\ub97c \uc774\ud574\ud558\uae30 \uc704\ud55c \uac00\uc0c1 \ube44\uc720\ub2e4. \ud2b9\uc815 \ud1a0\uc694\ud0c0 \uacf5\uc7a5\uc758 \uc0ac\ub840\ub97c \uc7ac\ud604\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \uc0dd\uc0b0\uc744 \uc900\ube44\ud55c\ub2e4\ub294 \uc77c\uc774 \ubb34\uc5c7\uc774\ub4e0 \ub9ce\uc774 \ud655\ubcf4\ud558\ub294 \uac83\uacfc \uac19\uc9c0 \uc54a\ub2e4\ub294 \uc810\uc740 \ubd84\uba85\ud558\ub2e4. \uc885\ub958\uc640 \uc218\ub7c9\ubfd0 \uc544\ub2c8\ub77c \ud544\uc694\ud55c \ub54c\ub97c \ub9de\ucd94\ub294 \ubb38\uc81c\uac00 \ud568\uaed8 \uc788\ub2e4. OpenStax\uc758 \uacbd\uc601 \uad50\uc7ac\ub294 \ub9b0 \uc0dd\uc0b0\uc744 \uace0\uac1d\uc774 \uc6d0\ud558\ub294 \uc774\uc775\uc5d0 \ubcf4\ud0ec\uc774 \ub418\uc9c0 \uc54a\ub294 \ub2e8\uacc4\ub97c \uc904\uc774\ub294 \ubc29\uc2dd\uc73c\ub85c \uc124\uba85\ud55c\ub2e4. \uc81c\ud488\uc744 \ub9cc\ub4dc\ub294 \uacfc\uc815 \uac00\uc6b4\ub370 \ubb34\uc5c7\uc774 \uac00\uce58\ub97c \ub354\ud558\ub294\uc9c0 \uc0b4\ud53c\ub294 \uac83\uc774\ub2e4. \uc791\uc5c5\uc790\uac00 \uc26c\uc9c0 \uc54a\uace0 \uc6c0\uc9c1\uc774\ub294 \ubaa8\uc2b5\ub9cc\uc744 \ubaa9\ud45c\ub85c \uc0bc\ub294 \uc124\uba85\uacfc\ub294 \ub2e4\ub974\ub2e4. \ubb3c\uac74\uc744 \ubd88\ud544\uc694\ud558\uac8c \uc62e\uae30\uace0 \uae30\ub2e4\ub9ac\uac70\ub098, \uc798\ubabb \ub9cc\ub4e4\uc5b4 \ub2e4\uc2dc \uc190\ubcf4\ub294 \uacfc\uc815\uc740 \uc790\uc6d0\uc744 \uc0ac\uc6a9\ud55c\ub2e4. \uadf8\ub7f0 \uc6c0\uc9c1\uc784\uc744 \uc904\uc774\uba74 \uac19\uc740 \uacb0\uacfc\ub97c \uc5bb\ub294 \ub370 \ub4dc\ub294 \ubd80\ub2f4\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \ub3d9\uc791\uc774 \ub9ce\uc544 \ubcf4\uc774\ub294\uac00\ubcf4\ub2e4 \uadf8 \ub3d9\uc791\uc774 \uace0\uac1d\uc5d0\uac8c \ud544\uc694\ud55c \uacb0\uacfc\uc640 \uc5f0\uacb0\ub418\ub294\uac00\ub2e4. \ubd80\ud488\uc744 \ubcf4\uad00\ud558\ub294 \ub3d9\uc548\uc5d0\ub3c4 \ucc3d\uace0\uc640 \uad00\ub9ac\uac00 \ud544\uc694\ud558\ub2e4. \uc544\uc9c1 \uc81c\ud488\uc73c\ub85c \ud314\ub9ac\uc9c0 \uc54a\uc740 \uc7ac\ub8cc\uc5d0 \uc790\uae08\uc774 \ubb36\uc774\uae30\ub3c4 \ud55c\ub2e4. \ub530\ub77c\uc11c \uc7ac\uace0\ub97c \ucda9\ubd84\ud788 \ub450\ub294 \uc120\ud0dd\uc5d0\ub294 \uc548\uc2ec\ud560 \uc218 \uc788\ub294 \uc774\uc810\uacfc \uacc4\uc18d \ubd80\ub2f4\ud574\uc57c \ud558\ub294 \ube44\uc6a9\uc774 \ud568\uaed8 \uc788\ub2e4. \uc7ac\ub8cc\uac00 \ub9ce\uc774 \uc313\uc5ec \uc788\ub2e4\uace0 \uc5b8\uc81c\ub098 \uacf5\uc7a5\uc774 \uc798 \uc6b4\uc601\ub418\ub294 \uc99d\uac70\ub294 \uc544\ub2c8\ub2e4. \ubc18\ub300\ub85c \uc7ac\uace0\uac00 \uc801\ub2e4\uace0 \uc800\uc808\ub85c \ud6a8\uc728\uc801\uc778 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \ud544\uc694\ud55c \ubd80\ud488\uc774 \ubaa8\uc790\ub77c \uc870\ub9bd\uc774 \uba48\ucd98\ub2e4\uba74 \ub2e4\ub978 \ubb38\uc81c\uac00 \uc0dd\uae34\ub2e4. \uc801\uc815\ud55c \uc7ac\uace0\ub97c \uc0dd\uac01\ud558\ub294 \uc77c\uc740 \ubb34\uc870\uac74 \ub9ce\uac70\ub098 \uc801\uc740 \ud55c\ucabd\uc744 \uace0\ub974\ub294 \uac83\ubcf4\ub2e4 \uc12c\uc138\ud558\ub2e4. \uc774\ub7f0 \uc0dd\uc0b0 \ucca0\ud559\uacfc \uc5f0\uacb0\ub418\ub294 \uac1c\ub150\uc774 \uc801\uc2dc \uacf5\uae09, \uc989 JIT\ub2e4. \uc7ac\ub8cc\ub97c \uc624\ub7ab\ub3d9\uc548 \ud604\uc7a5\uc5d0 \uc313\uc544 \ub450\uae30\ubcf4\ub2e4 \uc0dd\uc0b0\uc5d0 \ud544\uc694\ud560 \ub54c \ub9de\ucd94\uc5b4 \ub4e4\uc5b4\uc624\uac8c \ud558\ub824\ub294 \ubc29\uc2dd\uc774\ub2e4. \uad50\uc7ac\ub294 \uc218\uc694\uc5d0 \ub300\uc751\ud574 \uc0dd\uc0b0 \uacfc\uc815\uc73c\ub85c \ubb3c\uc790\uac00 \ub04c\ub824 \ub4e4\uc5b4\uc624\ub294 \ud750\ub984\uc73c\ub85c \uc124\uba85\ud55c\ub2e4. \uadf8\ub7ec\ub824\uba74 \uc55e\uc73c\ub85c \ubb34\uc5c7\uc744 \ub9cc\ub4e4\uace0 \uc5b4\ub290 \ub2e8\uacc4\uc5d0\uc11c \uc5b4\ub5a4 \ubd80\ud488\uc744 \uc0ac\uc6a9\ud560\uc9c0 \uc54c\uc544\uc57c \ud55c\ub2e4. \ucef4\ud4e8\ud130\ub85c \uc77c\uc815\uacfc \uc790\uc7ac \uc815\ubcf4\ub97c \uad00\ub9ac\ud558\ub294 \uc77c\ub3c4 \uc911\uc694\ud574\uc9c4\ub2e4. \uc7ac\uace0\ub97c \uc904\uc774\ub77c\ub294 \uad6c\ud638\ub9cc \uc678\uce5c\ub2e4\uace0 \uac00\ub2a5\ud55c \ubcc0\ud654\uac00 \uc544\ub2c8\ub2e4. \ub35c \uc313\uc544 \ub450\ub294 \ub9cc\ud07c \ub354 \uc798 \uc54c\uace0 \ub354 \uc815\ud655\ud558\uac8c \ub9de\ucd94\uc5b4\uc57c \ud55c\ub2e4. \ubd80\ud488 \uacf5\uae09\uc790\uc640 \uad6c\ub9e4 \ub2f4\ub2f9\uc790, \uc0dd\uc0b0 \ud604\uc7a5\uc740 \uc11c\ub85c \ub530\ub85c \uc6c0\uc9c1\uc77c \uc218 \uc5c6\ub2e4. \uc5b4\ub290 \ubb3c\uac74\uc774 \uc5b8\uc81c \ub3c4\ucc29\ud560\uc9c0\uc5d0 \ub300\ud55c \uc815\ubcf4\uac00 \uc5b4\uae0b\ub098\uba74 \ub2e4\uc74c \uc791\uc5c5\ub3c4 \uc601\ud5a5\uc744 \ubc1b\ub294\ub2e4. \uc801\uc2dc \uacf5\uae09\uc740 \ucc3d\uace0 \uc548\uc758 \uc815\ub9ac\ubc95\ub9cc\uc774 \uc544\ub2c8\ub77c \uc5ec\ub7ec \ud68c\uc0ac\uc640 \uc0ac\ub78c\uc774 \uc77c\uc815\uc744 \ub9de\ucd94\ub294 \uad00\uacc4\ub2e4. \ub530\ub77c\uc11c \ud55c \uae30\uc5c5 \uc548\uc758 \ud6a8\uc728\ub9cc \ubcf4\uace0 \ub05d\ub0bc \uc218 \uc5c6\ub2e4. \uac11\uc791\uc2a4\ub7ec\uc6b4 \ubcc0\uacbd\uc758 \ubd80\ub2f4\uc744 \uacf5\uae09\uc790\uc5d0\uac8c \ubb34\uc791\uc815 \ub118\uae34\ub2e4\uba74 \uc804\uccb4 \ud750\ub984\uc740 \ubd88\uc548\uc815\ud574\uc9c8 \uc218 \uc788\ub2e4. \ub204\uad70\uac00\uc758 \uae30\ub2e4\ub9bc\uc744 \uc5c6\uc574\ub294\ub370 \ub2e4\ub978 \uacf3\uc5d0 \ub300\uae30\uac00 \uc313\uc778 \uac83\uc740 \uc544\ub2cc\uc9c0 \uc0b4\ud53c\ub294 \uad00\uc810\uc774 \ud544\uc694\ud558\ub2e4. \uc774\ub294 \uc6d0\ub9ac\ub97c \ud3c9\uac00\ud560 \ub54c \ub367\ubd99\uc77c \uc218 \uc788\ub294 \uc9c8\ubb38\uc774\ub2e4. \uad50\uc7ac\ub294 \uc790\uc5f0\uc7ac\ud574 \uac19\uc740 \uc0ac\uac74\uc774 \uacf5\uae09\ub9dd\uc744 \ud754\ub4e4 \uc218 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud544\uc694\ud55c \uc2dc\uc810\uc5d0 \ub9de\ucd94\uc5b4 \ub3c4\ucc29\ud560 \uac83\uc744 \uc804\uc81c\ub85c \ud55c \uc0dd\uc0b0\uc740 \uacf5\uae09\uc774 \ub04a\uae30\uba74 \uba48\ucd9c \uc704\ud5d8\uc774 \uc788\ub2e4. \ud3c9\uc18c\uc5d0 \uc798 \ub9de\ub358 \uacc4\ud68d\uacfc \ube44\uc0c1 \uc0c1\ud669\uc744 \uacac\ub514\ub294 \uacc4\ud68d\uc740 \ud568\uaed8 \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4. \uc774\uac83\uc774 \uc801\uc2dc \uacf5\uae09\uc740 \ud2c0\ub838\ub2e4\ub294 \uacb0\ub860\uc740 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \uac00\uc7a5 \uc801\uc740 \uc7ac\uace0\uac00 \uc5b8\uc81c\ub098 \uac00\uc7a5 \uc88b\uc740 \uc7ac\uace0\ub77c\ub294 \ub2e8\uc21c\ud55c \uacf5\uc2dd\uc744 \ud53c\ud558\uac8c \ud55c\ub2e4. \ubd80\ud488\uc744 \ub2e4\uc2dc \uad6c\ud558\ub294 \ub370 \uac78\ub9ac\ub294 \uc2dc\uac04\uacfc \ub300\uccb4 \uac00\ub2a5\uc131, \uc911\ub2e8\ud588\uc744 \ub54c\uc758 \uc601\ud5a5\uc744 \uace0\ub824\ud574\uc57c \ud55c\ub2e4. \ud6a8\uc728\uacfc \uc5ec\uc720\ub97c \uc5b4\ub514\uc5d0 \ub458\uc9c0\uac00 \uc6b4\uc601\uc758 \uc120\ud0dd\uc774 \ub41c\ub2e4. \uac19\uc740 \uad50\uc7ac\ub294 \ud488\uc9c8\uacfc \uc0dd\uc0b0\uc131\uc744 \ub530\ub85c \ubcf4\uc9c0 \uc54a\ub294\ub2e4. \uacb0\ud568 \uc788\ub294 \uc81c\ud488\uc740 \uc7ac\ub8cc\uc640 \uc2dc\uac04\uc744 \ub0ad\ube44\ud558\uace0 \uace0\uac1d\uc758 \ubd88\ub9cc\uc744 \ub9cc\ub4e0\ub2e4. \ub9c8\uc9c0\ub9c9 \ub2e8\uacc4\uc5d0\uc11c \ubb38\uc81c\ub97c \ubc1c\uacac\ud574 \uace0\uce58\ub294 \uac83\ubfd0 \uc544\ub2c8\ub77c \uc0dd\uc0b0 \uc804\ubc18\uc5d0\uc11c \ud488\uc9c8\uc744 \uad00\ub9ac\ud574\uc57c \ud55c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc774 \uc810\uc744 \uc78a\uc73c\uba74 \uc0dd\uc0b0 \ucca0\ud559\uc774 \uc18d\ub3c4 \uacbd\uc7c1\uc73c\ub85c\ub9cc \ub0a8\ub294\ub2e4. \ub9cc\ub4dc\ub294 \uc218\ub7c9\uc774 \ub298\uc5b4\ub3c4 \uc7ac\uc791\uc5c5\uacfc \ud3d0\uae30\uac00 \ud568\uaed8 \ub298\uba74 \uacb0\uacfc\ub294 \ub2ec\ub77c\uc9c4\ub2e4. \uc9c0\uae08\uc758 \uae00\uc740 \ud1a0\uc694\ud0c0\uc758 \ud2b9\uc815 \ubaa8\ub378\uc774\ub098 \ucd5c\uadfc \uacf5\uc7a5\uc758 \uc131\uc801\ud45c\uac00 \uc544\ub2c8\ub77c, \uadf8 \ud68c\uc0ac\uac00 \ubc1c\uc804\uc2dc\ud0a8 \uac83\uc73c\ub85c \uc18c\uac1c\ub418\ub294 \uc0dd\uc0b0 \uc6d0\ub9ac\ub97c \uc774\ud574\ud558\ub294 \uc774\uc57c\uae30\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \ubd80\ud488\uc744 \uc0b4\ud3b4\ubcf4\ub294 \uc791\uc5c5\uc790\uc758 \ubaa8\uc2b5\uc744 \ud45c\ud604\ud588\ub2e4. \ud1a0\uc694\ud0c0\uc758 \uc2e4\uc81c \uacf5\uc7a5\uc774\ub098 \ud45c\uc900 \uc791\uc5c5\uc744 \ubcf5\uc6d0\ud55c \ub3c4\uba74\uc740 \uc544\ub2c8\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \uc313\uc778 \ubb3c\uac74\ubcf4\ub2e4 \ud544\uc694\ud55c \uac83\uc744 \ud568\uaed8 \ud655\uc778\ud558\ub294 \uc0ac\ub78c\uc758 \uad00\uacc4\ub97c \ub5a0\uc62c\ub9ac\uba74 \ub41c\ub2e4. \ud1a0\uc694\ud0c0\uc758 \uc0dd\uc0b0 \uc774\uc57c\uae30\ub294 \uc801\uac8c \uac00\uc9c0\ub77c\ub294 \uc0dd\ud65c \ud6c8\uacc4\uc640 \ub2e4\ub974\ub2e4. \ud544\uc694\ud55c \ubb3c\uac74\uc774 \ud544\uc694\ud55c \ub54c\uc5d0 \uc624\uace0 \uc81c\ub300\ub85c \ub9cc\ub4e4\uc5b4\uc9c0\ub3c4\ub85d \uc804\uccb4\ub97c \uc5f0\uacb0\ud558\ub294 \ubb38\uc81c\ub2e4. \ucc3d\uace0\uac00 \uac00\ub4dd\ud55c\uc9c0\ub97c \ubcf4\ub358 \ub208\uc774 \ubb3c\uac74\uc758 \ud750\ub984\uacfc \uc815\ubcf4\uc758 \ud750\ub984\uc744 \ud568\uaed8 \ubcf4\uac8c \ub418\ub294 \uc21c\uac04, \uacf5\uc7a5\uc740 \uc870\uae08 \ub2e4\ub978 \uc7a5\uc18c\ub85c \ubcf4\uc778\ub2e4."}, {"id": "western-union-pasted-message", "title": "\uc804\ubcf4 \ud55c \uc7a5\uc5d0\ub294 \uc885\uc774\uac00 \ud55c \ubc88 \ub354 \ubd99\uc5b4 \uc788\ub2e4", "summary": "1959\ub144 \uc6e8\uc2a4\ud134\uc720\ub2c8\uc5b8 \uc804\ubcf4\uc5d0\uc11c \uc778\uc1c4\ub41c \uc591\uc2dd\uacfc \ub367\ubd99\uc778 \uba54\uc2dc\uc9c0\ub97c \uad6c\ubd84\ud574 \ubd05\ub2c8\ub2e4.", "category": "companies", "category_title": "Companies", "subcategory": "Media", "url": "stories/western-union-pasted-message/index.html", "image": "media/western-union-pasted-message.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc804\ubcf4 (Western Union Telegram) \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc804\ubcf4 \ud55c \uc7a5\uc5d0\ub294 \uc885\uc774\uac00 \ud55c \ubc88 \ub354 \ubd99\uc5b4 \uc788\ub2e4 \ud68c\uc0ac \uc774\ub984 \uc544\ub798\uc5d0 \ub193\uc778 \uc9e7\uc740 \uc18c\uc2dd 1959\ub144 \uc6e8\uc2a4\ud134\uc720\ub2c8\uc5b8 \uc804\ubcf4\uc5d0\uc11c \uc778\uc1c4\ub41c \uc591\uc2dd\uacfc \ub367\ubd99\uc778 \uba54\uc2dc\uc9c0\ub97c \uad6c\ubd84\ud574 \ubd05\ub2c8\ub2e4. Media \uae30\uc5c5 \ud654\uba74\uc5d0 \ub72c \uba54\uc2dc\uc9c0\ub294 \uc190\uac00\ub77d\uc73c\ub85c \ub204\ub974\uba74 \uc5f4\ub9b0\ub2e4. \uc885\uc774\ub85c \ubc1b\uc740 \uc18c\uc2dd\uc774\ub77c\uba74 \ubcf4\ud1b5 \ud3b8\uc9c0 \ubd09\ud22c\ub97c \ub5a0\uc62c\ub9b4 \uac83\uc774\ub2e4. \uadf8\ub7f0\ub370 \uc774 \uc624\ub798\ub41c \uc804\ubcf4\ub294 \ub610 \ub2e4\ub974\ub2e4. \ud68c\uc0ac \uc774\ub984\uc774 \uc778\uc1c4\ub41c \uc885\uc774\uc5d0 \uba54\uc2dc\uc9c0 \uc885\uc774\uac00 \ud55c \ubc88 \ub354 \ubd99\uc5b4 \uc788\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc18c\uc7a5\ud55c \uc6e8\uc2a4\ud134\uc720\ub2c8\uc5b8 \uc804\ubcf4\ub2e4. \ub0a0\uc9dc\ub294 1959\ub144 4\uc6d4 13\uc77c\uc774\ub2e4. \ud55c \uc7a5\uc758 \ud1b5\uc2e0\ubb38\uc5d0\ub3c4 \ubbf8\ub9ac \ub9cc\ub4e4\uc5b4 \ub454 \ubd80\ubd84\uacfc \ub098\uc911\uc5d0 \ub354\ud574\uc9c4 \ubd80\ubd84\uc774 \ub098\ub258\uc5b4 \uc788\ub2e4. \uc0ac\uc9c4 \uc704\ucabd\uc5d0\ub294 WESTERN UNION\uc774\ub77c\ub294 \ud68c\uc0ac \uc774\ub984\uc774 \ud06c\uac8c \ubcf4\uc778\ub2e4. \uadf8 \uc544\ub798\ub85c \uae00\uc790\uac00 \uc774\uc5b4\uc9c4\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc740 \ube48\uce78\uc5d0 \uc804\ubcf4 \ub0b4\uc6a9\uc774 \uc801\ud78c \uc885\uc774\uac00 \ubd99\uc5b4 \uc788\ub2e4\uace0 \uc54c\ub824 \uc900\ub2e4. \uc591\uc2dd\uc740 \ud1b5\uc2e0\ud68c\uc0ac\uac00 \ub9c8\ub828\ud55c \uacf5\ud1b5\uc758 \ud2c0\uc774\uace0, \uadf8 \uc548\uc758 \uc18c\uc2dd\uc740 \uac01\uac01 \ub2e4\ub974\ub2e4. \uc624\ub298\ub0a0 \uac19\uc740 \uba54\uc2e0\uc800 \ud654\uba74\uc73c\ub85c \uc11c\ub85c \ub2e4\ub978 \uba54\uc2dc\uc9c0\ub97c \uc8fc\uace0\ubc1b\ub294 \ubaa8\uc2b5\uc744 \ub5a0\uc62c\ub9b4 \uc218\ub3c4 \uc788\ub2e4. \ud654\uba74 \ub300\uc2e0 \uc885\uc774\uac00 \ub0a8\uc544 \uc788\ub2e4\ub294 \uc810\uc5d0\uc11c \uc190\uc5d0 \uc7a1\ud788\ub294 \ub290\ub08c\uc740 \uc0ac\ubb47 \ub2e4\ub974\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc774 \uc804\ubcf4\uac00 \ub274\uc695 \ube0c\ub8e8\ud074\ub9b0\uc5d0 \uc788\ub358 \uc774\uad6c\uc5d0\uac8c \ubcf4\ub0b8 \uac83\uc73c\ub85c \ubcf4\uc778\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc5ec\uae30\uc11c \uc7a5\uc18c\uc640 \uc774\ub984\uc740 \ud55c \uc904\uc758 \uc8fc\uc18c \uc774\uc0c1\uc774\ub2e4. \uc791\uc740 \uc885\uc774\ub97c \ud2b9\uc815\ud55c \uc0ac\ub78c\uc758 \uc0dd\ud65c\uacfc \uc774\uc5b4 \uc8fc\ub294 \ub2e8\uc11c\uac00 \ub41c\ub2e4. \ub2e4\ub9cc \u2018\ubcf4\uc778\ub2e4\u2019\ub294 \ud310\ub2e8\uc744 \ud655\uc815\ub41c \ubc1c\uc1a1 \uacbd\uc704\ub85c \ubc14\uafb8\uc5b4 \uc77d\uc9c0\ub294 \ub9d0\uc790. \uc774 \uc790\ub8cc\ub294 \uc218\uc2e0\uc790\ub97c \ucd94\uc815\ud558\uace0 \uc788\ub2e4. \ub204\uac00 \uc5b4\ub5a4 \ub9c8\uc74c\uc73c\ub85c \ubcf4\ub0c8\ub294\uc9c0\uae4c\uc9c0 \ub300\ud654\ub97c \ub9cc\ub4e4\uc5b4 \ubd99\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \ub0a0\uc9dc\uc640 \uc218\uc2e0\uc9c0, \ub0a8\uc544 \uc788\ub294 \ud615\uc2dd\ub9cc\uc73c\ub85c\ub3c4 \ucda9\ubd84\ud788 \ubcfc\uac70\ub9ac\uac00 \uc788\ub2e4. \uc804\ubcf4\uc758 \ubc14\ud0d5 \uc885\uc774\uc5d0\ub294 \ud1b5\uc2e0\ud68c\uc0ac\uc758 \uc774\ub984\uacfc \uc815\ud574\uc9c4 \uce78\uc774 \uba3c\uc800 \uc778\uc1c4\ub418\uc5b4 \uc788\ub2e4. \uc804\ub2ec\ud560 \ub9d0\uc740 \uadf8 \ub4a4\uc5d0 \ubcc4\ub3c4\uc758 \uc885\uc774\ub85c \ub4e4\uc5b4\uc628\ub2e4. \uac1c\uc778\uc758 \uc18c\uc2dd\uc774 \ud68c\uc0ac\uc758 \uacf5\ud1b5 \uc591\uc2dd\uc744 \uac70\uccd0 \uc804\ub2ec\ub418\ub294 \uad6c\uc870\ub2e4. \uc0ac\uc9c4\uc744 \ubcfc \ub54c \uc778\uc1c4\ub41c \ubd80\ubd84\uacfc \ub367\ubd99\uc778 \ubd80\ubd84\uc744 \uad6c\ubcc4\ud558\uba74, \ud55c \uc7a5\uc758 \uc885\uc774\ub97c \ub9cc\ub4dc\ub294 \uc2dc\uac04\uc774 \ubaa8\ub450 \uac19\uc9c0 \uc54a\uc558\uc74c\uc744 \uc54c \uc218 \uc788\ub2e4. \uc774\uac83\uc740 \uc7a5\uc2dd\uc758 \ucc28\uc774\ubcf4\ub2e4 \uc5c5\ubb34\uc758 \ud750\ub984\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ud68c\uc0ac\ub294 \ub9ce\uc740 \uba54\uc2dc\uc9c0\ub97c \ub2e4\ub8e8\uae30 \uc704\ud574 \uac19\uc740 \ud2c0\uc744 \uc4f0\uace0, \ubc1b\ub294 \uc0ac\ub78c\uc740 \uadf8 \uc548\uc5d0\uc11c \uc790\uae30\uc5d0\uac8c \uc628 \ub9d0\uc744 \uc77d\ub294\ub2e4. \uc624\ub298\uc758 \uba54\uc2dc\uc9c0 \ucc3d\uc5d0\uc11c\ub3c4 \ubc14\ub00c\uc9c0 \uc54a\ub294 \ud654\uba74\uacfc \ub9e4\ubc88 \ub2e4\ub978 \ub0b4\uc6a9\uc774 \ud568\uaed8 \uc788\uc9c0\ub9cc, \uc885\uc774\uc5d0\uc11c\ub294 \uadf8 \ub450 \uce35\uc774 \uc2e4\uc81c\ub85c \uacb9\uccd0 \ubd99\uc5b4 \uc788\ub2e4\ub294 \uc810\uc774 \ub208\uc5d0 \ubcf4\uc778\ub2e4. \ud3b8\uc9c0\uc5d0\uc11c\ub294 \uc4f4 \uc0ac\ub78c\uc774 \uc0ac\uc6a9\ud55c \uc885\uc774\uac00 \uc774\ub3d9\ud574 \ubc1b\ub294 \uc0ac\ub78c\uc5d0\uac8c \uac08 \uc218 \uc788\ub2e4. \uc804\ubcf4\uc5d0\uc11c\ub294 \uc804\ub2ec\ubc1b\uc740 \ub0b4\uc6a9\uc744 \ud604\uc9c0\uc758 \uc591\uc2dd\uc5d0 \uc62e\uaca8 \ub0b4\uc5b4 \uc8fc\ub294 \uacfc\uc815\uc774 \uc911\uc694\ud588\ub2e4. \uc774 \uc720\ubb3c\uc758 \ubd99\uc778 \uc885\uc774\ub294 \uadf8 \uc804\ub2ec \ubc29\uc2dd\uc758 \ud754\uc801\uc744 \uc0b4\ud3b4\ubcfc \ub2e8\uc11c\ub2e4. \ud55c\ucabd\uc5d0\uc11c \uc791\uc131\ud55c \uc6d0\ubcf8 \uc885\uc774 \uc804\uccb4\uac00 \uadf8\ub300\ub85c \ub2e4\ub978 \ucabd\uc5d0 \ub3c4\ucc29\ud588\ub2e4\uace0 \uc0dd\uac01\ud558\uc9c0 \uc54a\uc544\ub3c4 \ub41c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc774 \ubb3c\uac74\ub9cc\uc73c\ub85c \uc0ac\uc6a9\ud55c \uae30\uacc4\uc640 \uc804\uc1a1 \uacbd\ub85c\ub97c \ubaa8\ub450 \uc54c \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub290 \uad50\ud658 \uc9c0\uc810\uc744 \uac70\uccd0 \uc5bc\ub9c8\ub098 \ube68\ub9ac \uc804\ub2ec\ub418\uc5c8\ub294\uc9c0\ub294 \ubcc4\ub3c4\uc758 \uae30\ub85d\uc774 \ud544\uc694\ud55c \ubb38\uc81c\ub2e4. \uc5ec\uae30\uc11c\ub294 \ub0a8\uc740 \ud615\ud0dc\uc5d0\uc11c \ubd84\uba85\ud788 \uc77d\uc744 \uc218 \uc788\ub294 \uc591\uc2dd\uacfc \uba54\uc2dc\uc9c0\uc758 \uacb0\ud569\uc744 \uba3c\uc800 \ubcf8\ub2e4. \ud1b5\uc2e0\uc758 \uc5ed\uc0ac\uac00 \uc7a5\uce58\uc758 \ubc1c\uba85\ubfd0 \uc544\ub2c8\ub77c \ubc1b\uc740 \ub9d0\uc758 \ubaa8\uc591\uc5d0\ub3c4 \ub0a8\uc544 \uc788\ub2e4. 1959\ub144 4\uc6d4 13\uc77c\uc774\ub77c\ub294 \ub0a0\uc9dc\ub294 \ubb3c\uac74\uc744 \ud2b9\uc815\ud55c \uc2dc\uac04\uc5d0 \ubb36\uc5b4 \uc900\ub2e4. \ube0c\ub8e8\ud074\ub9b0\uc758 \uc774\uad6c\ub77c\ub294 \uc218\uc2e0 \ucd94\uc815\uc740 \uadf8 \uc2dc\uac04\uc744 \ud55c \uc0ac\ub78c\uc758 \uac70\ucc98\uc640 \uc5f0\uacb0\ud55c\ub2e4. \uc9e7\uc740 \ud1b5\uc2e0\ubb38\uc774 \uc788\uc5b4\ub3c4 \ub204\uac00 \uc77d\uc5c8\ub294\uc9c0 \ubaa8\ub974\uba74 \uc774\uc57c\uae30\ub294 \ub9e4\uc6b0 \ub113\uac8c \uc5f4\ub824 \uc788\ub2e4. \ubc18\ub300\ub85c \uc774\ub984\uacfc \uc7a5\uc18c\uac00 \ub0a8\uc73c\uba74 \ub2e4\ub978 \uc790\ub8cc\uc640 \ub300\uc870\ud574 \ubcfc \uae38\uc774 \uc0dd\uae34\ub2e4. \uc774\ub54c \ucd94\uc815\uc774\ub77c\ub294 \ub9d0\uc744 \uc9c0\uc6b0\uc9c0 \uc54a\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4. \ud655\uc2e4\ud558\uc9c0 \uc54a\uc740 \uc218\uc2e0\uc790\ub97c \ud655\uc815\ud558\uace0 \uadf8 \uc0ac\ub78c\uc758 \uae30\uc068\uacfc \uc2ac\ud514\uae4c\uc9c0 \uc368 \ubc84\ub9ac\uba74 \ub0a8\uc740 \uc790\ub8cc\ubcf4\ub2e4 \uc774\uc57c\uae30\uac00 \uc55e\uc11c \ub098\uac04\ub2e4. \uc804\ubcf4\ub97c \uc77d\ub294 \uc7ac\ubbf8\ub294 \ubaa8\ub4e0 \ube48\uce78\uc744 \uc18c\uc124\ub85c \ucc44\uc6b0\ub294 \ub370\ub9cc \uc788\uc9c0 \uc54a\ub2e4. \uc5b4\ub514\uae4c\uc9c0 \uc5f0\uacb0\ub418\uace0 \ubb34\uc5c7\uc774 \uc544\uc9c1 \ub0a8\ub294\uc9c0 \ucc28\ubd84\ud558\uac8c \ub530\ub77c\uac00\ub294 \ub370\ub3c4 \uc788\ub2e4. \uc804\ubcf4\ub97c \ub9cc\ub4e4\uace0 \uc804\ub2ec\ud55c \ud68c\uc0ac\uc5d0\ub294 \uc218\ub9ce\uc740 \ud1b5\uc2e0\ubb38 \uac00\uc6b4\ub370 \ud558\ub098\uc600\uc744 \uc218 \uc788\ub2e4. \ubc1b\uc740 \uc0ac\ub78c\uc5d0\uac8c\ub294 \ub2e4\uc2dc \ubcf4\uae30 \uc704\ud574 \ubcf4\uad00\ud560 \ub2e8 \ud55c \ubc88\uc758 \uc18c\uc2dd\uc774\uc5c8\uc744 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uc65c \uc774 \uc790\ub8cc\ub97c \uac04\uc9c1\ud588\ub294\uc9c0\ub294 \ub0a8\uc740 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ub2e8\uc815\ud558\uc9c0 \uc54a\ub294\ub2e4. \uac19\uc740 \uc885\uc774\uac00 \ud68c\uc0ac\uc758 \uc5c5\ubb34\uc640 \uac1c\uc778\uc758 \uc0dd\ud65c\uc744 \ub3d9\uc2dc\uc5d0 \uc9c0\ub098\uc654\ub2e4\ub294 \uc810\uc744 \ubcfc \uc218 \uc788\ub2e4. \uae30\uc99d \ub4a4\uc5d0\ub294 \uadf8 \uc885\uc774\uac00 \uc5ec\ub7ec \uc0ac\ub78c\uc774 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub294 \uc790\ub8cc\uac00 \ub41c\ub2e4. \ub0a0\uc9dc\uc640 \uc8fc\uc18c, \uc885\uc774\ub97c \ubd99\uc778 \uacbd\uacc4\uae4c\uc9c0 \uad00\ucc30\uc758 \ub300\uc0c1\uc774 \ubc14\ub010\ub2e4. \ub0b4\uc6a9\uc774 \uc9e7\ub2e4\uace0 \uc790\ub8cc\ub85c\uc11c\uc758 \uc9c8\ubb38\ub3c4 \uc801\uc740 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc804\ubcf4 \ud55c \uc7a5\uc740 \ub204\uad70\uac00\uc758 \ub9d0\uc744 \ub2f4\uc73c\uba74\uc11c, \ub2f9\uc2dc \uc0ac\ud68c\uac00 \ub9d0\uc744 \uba40\ub9ac \ubcf4\ub0b4\uace0 \ubc1b\uc544 \uc801\uace0 \uac74\ub124\ub358 \ubc29\uc2dd\ub3c4 \ud568\uaed8 \ubcf4\uc874\ud558\uace0 \uc788\ub2e4. \uc774 \uc804\ubcf4\ub294 \uc904\ub9ac\uc544 \uba40\ub85d\uc774 \uc77c\uad04 \uae30\uc99d\ud55c \uc790\ub8cc\uc5d0 \ud3ec\ud568\ub41c\ub2e4. \uac1c\uc778\uc774 \uac04\uc9c1\ud558\ub358 \ud1b5\uc2e0\ubb38\uc774 \ubc15\ubb3c\uad00\uc758 \uae30\ub85d\uc774 \ub41c \uac83\uc774\ub2e4. \ud68c\uc0ac\uc758 \uc778\uc1c4 \uc591\uc2dd\uc774 \uc5b4\ub290 \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc790\uc2e0\uc758 \uc18c\uc2dd\uc744 \ub2f4\uc740 \ubb3c\uac74\uc774\uae30\ub3c4 \ud588\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ub290\uaef4\uc9c4\ub2e4. \ub2e4\uc2dc \uc0ac\uc9c4\uc744 \ubcf4\uba74 \ud68c\uc0ac \uc774\ub984\ubcf4\ub2e4 \ub367\ubd99\uc778 \uc885\uc774 \ucabd\uc5d0 \ub208\uc774 \uac08 \uc218 \uc788\ub2e4. \ub611\uac19\uc740 \uc591\uc2dd\uc744 \ub2e8 \ud55c \ubc88\uc758 \uc18c\uc2dd\uc73c\ub85c \ubc14\uafb8\ub294 \ubd80\ubd84\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \uc9e7\uac8c \uc804\ub2ec\ub41c \ub9d0\ub3c4 \ubb3c\uac74\uc73c\ub85c \ub0a8\uc73c\uba74, \uc18c\uc2dd\uc744 \uc8fc\uace0\ubc1b\ub358 \ubc29\uc2dd\uae4c\uc9c0 \ud568\uaed8 \ubcf4\uc5ec \uc900\ub2e4."}, {"id": "zappos-circles-and-responsibility", "title": "\uc790\ud3ec\uc2a4 \u2014 \uc0c1\uc0ac\ub97c \uc5c6\uc560\uba74 \uc77c\uc740 \ub204\uac00 \uc815\ud560\uae4c", "summary": "\uc790\ud3ec\uc2a4\uc758 2013~2015\ub144 \uc870\uc9c1 \uc2e4\ud5d8\uc744 \ud1b5\ud574 \uc790\uc728\uc131\uacfc \ucc45\uc784\uc744 \ud568\uaed8 \uc124\uacc4\ud558\ub294 \uc5b4\ub824\uc6c0\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "companies", "category_title": "Companies", "subcategory": "Fashion", "url": "stories/zappos-circles-and-responsibility/index.html", "image": "media/zappos-circles-and-responsibility.png", "alt": "\uc2e0\ubc1c\uacfc \ubc30\uc1a1 \uc0c1\uc790\uac00 \ub193\uc778 \uc0ac\ubb34\uc2e4\uc5d0\uc11c \ub3d9\ub8cc\ub4e4\uc774 \ub465\uadfc \uc2dd\ud0c1\uc5d0 \ubaa8\uc5ec \uc758\ub17c\ud558\ub294 AI \uc7a5\uba74.", "text": "\uc790\ud3ec\uc2a4 \u2014 \uc0c1\uc0ac\ub97c \uc5c6\uc560\uba74 \uc77c\uc740 \ub204\uac00 \uc815\ud560\uae4c \uc9c1\ud568\ubcf4\ub2e4 \uc5ed\ud560\uc744 \uc55e\uc138\uc6b4 \uc2e0\ubc1c \ud68c\uc0ac\uc758 \uc2e4\ud5d8 \uc790\ud3ec\uc2a4\uc758 2013~2015\ub144 \uc870\uc9c1 \uc2e4\ud5d8\uc744 \ud1b5\ud574 \uc790\uc728\uc131\uacfc \ucc45\uc784\uc744 \ud568\uaed8 \uc124\uacc4\ud558\ub294 \uc5b4\ub824\uc6c0\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Fashion \uae30\uc5c5 \ud68c\uc758\uc5d0\uc11c \ub204\uad70\uac00 \ub9d0\ud55c\ub2e4. \uc55e\uc73c\ub85c\ub294 \ud300\uc7a5\uc774\ub77c\ub294 \uc9c1\ud568\uc744 \uc5c6\uc560\uaca0\uc2b5\ub2c8\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc0ac\ubb34\uc2e4\uc774 \uc870\uae08 \uc790\uc720\ub85c\uc6cc\uc9c8 \uac83 \uac19\ub2e4. \uadf8\ub7f0\ub370 \uace7 \ub2e4\uc74c \uc9c8\ubb38\uc774 \ub530\ub77c\uc628\ub2e4. \uadf8\ub7ec\uba74 \ubb34\uc5c7\uc744 \uba3c\uc800 \ud560\uc9c0, \uc758\uacac\uc774 \ub2e4\ub97c \ub54c \uc5b4\ub5bb\uac8c \uacb0\uc815\ud560\uc9c0, \uc77c\uc758 \uacb0\uacfc\ub294 \ub204\uac00 \ub9e1\uc744\uae4c. \uc628\ub77c\uc778 \uc2e0\ubc1c \ud310\ub9e4\ub85c \uc54c\ub824\uc9c4 \uc790\ud3ec\uc2a4\ub294 2010\ub144\ub300\uc5d0 \uc774\ub7f0 \uc9c8\ubb38\uc744 \uc2e4\uc81c \uc870\uc9c1 \uc6b4\uc601\uc758 \ubb38\uc81c\ub85c \ub2e4\ub8e8\uc5c8\ub2e4. \ub2f9\uc2dc \uacbd\uc601\uc790 \ud1a0\ub2c8 \uc170\uc774\ub294 \uae30\uc874 \uc9c1\ud568\uacfc \uace0\uc815\ub41c \uad00\ub9ac \uad6c\uc870\ub97c \ubc14\uafb8\ub294 \uc2e4\ud5d8\uc5d0 \ub098\uc130\ub2e4. \ubaa8\ub4e0 \ud68c\uc0ac\uac00 \ub530\ub77c\uc57c \ud560 \uc815\ub2f5\uc774\ub77c\uae30\ubcf4\ub2e4, \uc790\uc720\ub85c\uc6b4 \uc77c\ud130\ub97c \ub9cc\ub4e4\ub824 \ud560 \ub54c \ubb34\uc5c7\uae4c\uc9c0 \ubc14\uafb8\uc5b4\uc57c \ud558\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\ub294 \uc0ac\ub840\ub2e4. OpenStax \uacbd\uc601\ud559 \uad50\uc7ac\ub294 2013\ub144 \ubb34\ub835 \uc790\ud3ec\uc2a4\uac00 \uc0ac\uc5c5\uc744 \uc798\ud558\uace0 \uc788\uc5c8\uc9c0\ub9cc, \uc170\uc774\uac00 \uc870\uc9c1\uacfc \ubb38\ud654\uc5d0 \uc0c8\ub85c\uc6b4 \ubcc0\ud654\ub97c \uc2dc\ub3c4\ud558\ub824 \ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uadf8\uac00 \ub3c4\uc785\ud55c \ubc29\uc2dd\uc758 \uc774\ub984\uc740 \ud640\ub77c\ud06c\ub77c\uc2dc\uc600\ub2e4. \uc774\ub984\uc740 \ub0af\uc124\uc9c0\ub9cc \uad00\uc2ec\uc744 \ub450\uc5b4\uc57c \ud560 \uc9c8\ubb38\uc740 \uac04\ub2e8\ud558\ub2e4. \uc0ac\ub78c\uacfc \uc77c\uc758 \uad00\uacc4\ub97c \uc5b4\ub5bb\uac8c \uc815\ud560 \uac83\uc778\uac00. \uc77c\ubc18\uc801\uc778 \uc870\uc9c1\uc5d0\uc11c\ub294 \ubd80\uc11c\uc640 \uc9c1\ud568\uc744 \ud1b5\ud574 \ucc45\uc784\uacfc \ubcf4\uace0 \uc21c\uc11c\ub97c \uc815\ud55c\ub2e4. \ud640\ub77c\ud06c\ub77c\uc2dc\ub294 \uace0\uc815\ub41c \uc9c1\ubb34 \ub300\uc2e0 \ud544\uc694\ud55c \uc5ed\ud560\uacfc \uc774\ub97c \uc218\ud589\ud558\ub294 \uc791\uc740 \ub2e8\uc704\ub4e4\uc744 \uc911\uc2ec\uc73c\ub85c \uc77c\ud558\ub824\ub294 \ubc29\uc2dd\uc774\uc5c8\ub2e4. \ub204\uac00 \ub204\uad6c\ubcf4\ub2e4 \ub192\uc740\uac00\ub9cc \ubcf4\uc9c0 \uc54a\uace0 \uc5b4\ub5a4 \uc77c\uc774 \ud544\uc694\ud558\uba70 \ub204\uac00 \ub9e1\uc744\uc9c0\ub97c \ub2e4\uc2dc \ubc30\uc5f4\ud558\ub294 \uad6c\uc0c1\uc774\ub2e4. \uc774 \uccb4\uacc4\uc5d0\uc11c \uae30\ubcf8 \ub2e8\uc704\ub97c \uc11c\ud074\uc774\ub77c\uace0 \ubd80\ub978\ub2e4. \ubaa9\ud45c\uc640 \ud544\uc694\uc5d0 \ub530\ub77c \ub9cc\ub4e4\uc5b4\uc9c0\uace0 \ubc14\ub00c\ub294 \ud300\uc73c\ub85c \uc0dd\uac01\ud558\uba74 \uc774\ud574\ud558\uae30 \uc27d\ub2e4. \uad50\uc7ac\ub294 \uc0ac\ub78c\ub4e4\uc774 \uad00\uc2ec\uacfc \ub2a5\ub825\uc5d0 \ub9de\ub294 \ud504\ub85c\uc81d\ud2b8\uc5d0 \ucc38\uc5ec\ud558\ub3c4\ub85d \ud558\ub824\ub294 \uc758\ub3c4\uac00 \uc788\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc11c\ud074\uc774\ub77c\ub294 \ub9d0\uc774 \ubd99\uc5c8\ub2e4\uace0 \ubaa8\ub450\uac00 \ub611\uac19\uc740 \uc77c\uc744 \ub098\ub204\uc5b4 \ud558\uac70\ub098 \ubaa8\ub4e0 \ud310\ub2e8\uc744 \uc804\uc6d0\uc774 \ud22c\ud45c\ud55c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc5ed\ud560\uacfc \ucc45\uc784\uc744 \ubd84\uba85\ud558\uac8c \ubc30\uc815\ud558\ub294 \uc77c\uc774 \uc5ec\uc804\ud788 \ud544\uc694\ud558\ub2e4. \uc9c1\ud568\uc744 \uc904\uc774\ub294 \uac83\uacfc \uc5c5\ubb34\uc758 \uad6c\ubd84\uc744 \uc5c6\uc560\ub294 \uac83\uc740 \ub2e4\ub978 \ubcc0\ud654\ub2e4. \uc774 \ucc28\uc774\ub97c \ub193\uce58\uba74 \uc790\uc720\ub85c\uc6b4 \uc870\uc9c1\uc744 \ub9c9\uc5f0\ud788 \uaddc\uce59 \uc5c6\ub294 \uc0ac\ubb34\uc2e4\ub85c \uc0c1\uc0c1\ud558\uac8c \ub41c\ub2e4. \uae30\uc874 \uad00\ub9ac\uc790\uc758 \uc5ed\ud560\uc740 \ub2e4\ub978 \uc5ed\ud560\ub4e4\ub85c \ub098\ub258\uc5c8\ub2e4. \uad50\uc7ac\uc758 \uc124\uba85\uc5d0 \ub530\ub974\uba74 \uc77c\uc758 \ubc29\ud5a5\uc744 \uc548\ub0b4\ud558\ub294 \uc5ed\ud560, \uc9c1\uc6d0\uc758 \uc131\uc7a5\uc744 \ub3d5\ub294 \uba58\ud1a0, \ubcf4\uc0c1\uc744 \ud3c9\uac00\ud558\ub294 \uc5ed\ud560 \ub4f1\uc774 \ub530\ub85c \uc0dd\uacbc\ub2e4. \ub204\uad70\uac00 \ub9e1\uc544\uc57c \ud560 \uc77c\uc774 \uc5c6\uc5b4\uc84c\ub2e4\uae30\ubcf4\ub2e4 \ud55c \uc9c1\ud568 \uc544\ub798 \ubb36\uc5ec \uc788\ub358 \uc77c\uc744 \ub2e4\uc2dc \uad6c\ubd84\ud55c \uac83\uc774\ub2e4. \uc774 \ub300\ubaa9\uc5d0\uc11c \uc2e4\ud5d8\uc758 \ud575\uc2ec\uc774 \ubcf4\uc778\ub2e4. \uc9c1\ud568 \ud55c \uce78\uc744 \uc9c0\uc6b0\ub294 \uac83\uc740 \uc27d\uc9c0\ub9cc \uadf8 \uc0ac\ub78c\uc774 \ud574 \uc624\ub358 \ud310\ub2e8\uacfc \uc9c0\uc6d0\uae4c\uc9c0 \uc9c0\uc6b8 \uc218\ub294 \uc5c6\ub2e4. \uc790\uc720\ub97c \ub298\ub9ac\ub294 \ubcc0\ud654\ub294 \ubb34\uc5c7\uc744 \ud558\uc9c0 \uc54a\uc744\uc9c0\ubfd0 \uc544\ub2c8\ub77c \ud544\uc694\ud55c \uc77c\uc744 \ub204\uac00 \uacc4\uc18d \ud574 \uc904\uc9c0\ub3c4 \uc124\uacc4\ud574\uc57c \ud55c\ub2e4. \uc0ac\ub78c\uc744 \uc904 \uc138\uc6b0\ub294 \ubc29\uc2dd\uacfc \uc77c\uc744 \uc5f0\uacb0\ud558\ub294 \ubc29\uc2dd\uc740 \uac19\uc9c0 \uc54a\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \uc2e0\ubc1c\uc5d0 \uad00\ud55c \uace0\uac1d \ubb38\uc758\ub97c \ucc98\ub9ac\ud558\ub294 \uc0ac\ub78c\uc774 \ub2e4\ub978 \uac1c\uc120 \ud504\ub85c\uc81d\ud2b8\uc5d0\ub3c4 \ucc38\uc5ec\ud55c\ub2e4\uace0 \uc0dd\uac01\ud574 \ubcf4\uc790. \ud55c \uc0ac\ub78c\uc774 \uc5ec\ub7ec \uc5ed\ud560\uc744 \ub9e1\uc73c\uba74 \uc790\uc2e0\uc758 \ub2a5\ub825\uc744 \ub354 \ub2e4\uc591\ud558\uac8c \uc4f8 \uc218 \uc788\ub2e4. \uc774\uac83\uc740 \uc6d0\ub9ac\ub97c \uc124\uba85\ud558\uae30 \uc704\ud55c \uac00\uc0c1 \uc608\uc774\uba70 \uc2e4\uc81c \uc790\ud3ec\uc2a4 \uc9c1\uc6d0\uc758 \uc77c\uacfc\ub97c \uae30\ub85d\ud55c \uc7a5\uba74\uc740 \uc544\ub2c8\ub2e4. \ubc18\ub300\ub85c \ub450 \uc5ed\ud560\uc758 \uc77c\uc774 \ub3d9\uc2dc\uc5d0 \uae09\ud574\uc9c0\uba74 \uc6b0\uc120\uc21c\uc704\ub97c \uc815\ud574\uc57c \ud55c\ub2e4. \ub204\uad70\uac00\uc758 \uc790\uc728\uc801\uc778 \uc120\ud0dd\uc774 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc77c\uc815\uc5d0 \uc601\ud5a5\uc744 \uc8fc\uae30 \ub54c\ubb38\uc774\ub2e4. \uc9c1\ud568\uc774 \ub2e8\uc21c\ud558\uc9c0 \uc54a\uc744\uc218\ub85d \uc5ed\ud560 \uc0ac\uc774\uc758 \uc57d\uc18d\uc740 \ub354 \ubd84\uba85\ud574\uc57c \ud560 \uc218 \uc788\ub2e4. \uc790\uc720\uc640 \uc870\uc815\uc740 \uc11c\ub85c \ubc18\ub300\ub418\ub294 \uac83\ub9cc\uc740 \uc544\ub2c8\ub2e4. \uc790\ud3ec\uc2a4\ub294 2015\ub144\uc5d0 \uc5ec\ub7ec \uae30\ub2a5\uc758 \uad6c\ubd84\uc744 \ub354 \ubc14\uafb8\uba70 \ubcc0\ud654\ub97c \ud655\ub300\ud588\ub2e4. \uad50\uc7ac\ub294 \uc9c0\uce68\uc774 \ub418\ub294 \ud5cc\uc7a5\ub3c4 \ub9c8\ub828\ud588\uc9c0\ub9cc \uc9c1\uc6d0\ub4e4\uc774 \uc0c8\ub85c\uc6b4 \ubc29\uc2dd\uc744 \uc775\ud788\ub294 \ub370 \uc5b4\ub824\uc6c0\uc774 \uc788\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc0ac\ub78c\uc744 \ubbff\uc790\ub294 \ub73b\uc774 \ubd84\uba85\ud574\ub3c4 \uc2e4\uc81c\ub85c \uc77c\ud558\ub294 \uaddc\uce59\uc740 \ub0af\uc124 \uc218 \uc788\ub2e4. \uc0c8\ub85c\uc6b4 \uc870\uc9c1\uc5d0\uc11c\ub294 \ub204\uad6c\uc5d0\uac8c \ubb34\uc5c7\uc744 \ubb3c\uc5b4\ubd10\uc57c \ud558\ub294\uc9c0\ubd80\ud130 \ub2e4\uc2dc \ubc30\uc6cc\uc57c \ud55c\ub2e4. \uc790\uc2e0\uc774 \ub9e1\uc744 \uc218 \uc788\ub294 \ubc94\uc704, \ub2e4\ub978 \uc5ed\ud560\uacfc\uc758 \uad00\uacc4, \ubcf4\uc0c1\uc5d0 \uad00\ud55c \ud310\ub2e8\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uc775\uc219\ud55c \ubcf4\uace0 \uc21c\uc11c\ub97c \uc5c6\uc560\ub294 \uc77c\uc774 \ubaa8\ub4e0 \uc0ac\ub78c\uc5d0\uac8c \uace7\ubc14\ub85c \ud3b8\uc548\ud568\uc744 \uc8fc\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ubcc0\ud654\uc758 \uc18d\ub3c4\ub3c4 \uc9c1\uc6d0\uc758 \uacbd\ud5d8\uc5d0 \uc601\ud5a5\uc744 \ubbf8\ucce4\ub2e4. \uad50\uc7ac\ub294 \ubcc0\ud654 \uacfc\uc815\uc5d0\uc11c \uc9c1\uc6d0 \uc774\ud0c8\uc774 \ub098\ud0c0\ub0ac\uace0 \uc77c\ubd80\uac00 \ube60\ub974\uace0 \ud070 \ubcc0\ud654\uc5d0 \uc9c0\ucce4\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc774\ud0c8\ud55c \uc0ac\ub78c \ubaa8\ub450\uc758 \uc774\uc720\ub97c \ud558\ub098\ub85c \ud655\uc815\ud558\uac70\ub098, \uadf8 \uc22b\uc790\ub9cc\uc73c\ub85c \uc81c\ub3c4 \uc804\uccb4\uc758 \uc131\uacf5\uacfc \uc2e4\ud328\ub97c \uc120\uc5b8\ud560 \uc218\ub294 \uc5c6\ub2e4. \uac1c\ubcc4 \uc0ac\ub78c\uc758 \uc120\ud0dd\uacfc \uae30\uc5c5 \uc804\uccb4\uc758 \uc131\uacfc\ub294 \ub2e4\ub978 \uc790\ub8cc\uac00 \ud544\uc694\ud55c \uc9c8\ubb38\uc774\ub2e4. \uc5ec\uae30\uc11c \ubd84\uba85\ud788 \uc77d\uc744 \uc218 \uc788\ub294 \uac83\uc740 \uc870\uc9c1\uc758 \uc774\uc0c1\uacfc \uc801\uc751\uc758 \uacbd\ud5d8 \uc0ac\uc774\uc5d0 \uac70\ub9ac\uac00 \uc788\uc5c8\ub2e4\ub294 \uc810\uc774\ub2e4. \uc124\uacc4\ud55c \uc0ac\ub78c\uc5d0\uac8c\ub294 \uba85\ud655\ud55c \ubc29\ud5a5\uc774 \ucc38\uc5ec\ud558\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \ubcf5\uc7a1\ud55c \uc0c8 \uaddc\uce59\uc73c\ub85c \ubcf4\uc77c \uc218 \uc788\ub2e4. \uad6c\uc131\uc6d0\uc774 \uc774\ud574\ud558\uace0 \uc775\ud790 \uc2dc\uac04\uc744 \uc5b4\ub5bb\uac8c \ub9c8\ub828\ud560\uc9c0\ub3c4 \ubcc0\ud654\uc758 \uc77c\ubd80\uc600\ub2e4. \uc0c1\uc0ac\uac00 \uacb0\uc815\uc744 \ub300\uc2e0 \ub0b4\ub824 \uc8fc\uc9c0 \uc54a\ub294\ub2e4\uba74 \uc790\uc2e0\uc758 \ud310\ub2e8\uc774 \uc911\uc694\ud574\uc9c4\ub2e4. \ub3d9\uc2dc\uc5d0 \ub2e4\ub978 \uc0ac\ub78c\uacfc \uc57d\uc18d\uc744 \ub9de\ucd94\uace0 \uacb0\uacfc\ub97c \uc124\uba85\ud560 \ucc45\uc784\ub3c4 \uc0dd\uae34\ub2e4. \uc790\uc728\uc131\uc740 \ud558\uace0 \uc2f6\uc740 \uc77c\ub9cc \uace8\ub77c \ud558\ub294 \ud5c8\uac00\uc99d\ubcf4\ub2e4, \uc2a4\uc2a4\ub85c \ud310\ub2e8\ud560 \uc815\ubcf4\uc640 \ubc94\uc704\ub97c \uac16\ub294 \uc870\uac74\uc5d0 \uac00\uae5d\ub2e4. \uadf8\ub798\uc11c \uc790\ud3ec\uc2a4 \uc0ac\ub840\ub97c \uc77d\uc744 \ub54c\ub294 \uc0c1\uc0ac\ub97c \uc5c6\uc574\ub2e4\ub294 \ubb38\uc7a5 \ub4a4\ub97c \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc5ed\ud560\uc744 \uc5b4\ub5bb\uac8c \uc815\ud558\uace0 \uc77c\uc774 \uacb9\uce60 \ub54c \uc5b4\ub5bb\uac8c \ud480\uba70 \uc131\uc7a5\uacfc \ud3c9\uac00\ub97c \ub204\uac00 \ub3c4\uc6b8\uc9c0 \uac19\uc740 \ubb38\uc81c\uac00 \ub0a8\uc544 \uc788\ub2e4. \uc870\uc9c1\uc744 \uc218\ud3c9\uc801\uc73c\ub85c \ub9cc\ub4e4\ub824\ub294 \uc2dc\ub3c4\ub3c4 \uc2e4\uc81c\ub85c \uc791\ub3d9\ud558\ub824\uba74 \uaf64 \uad6c\uccb4\uc801\uc778 \uc7a5\uce58\uac00 \ud544\uc694\ud588\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uc790\ud3ec\uc2a4\uc758 \uc2e4\uc81c \uc0ac\ubb34\uc2e4\uc774\ub098 \uc9c1\uc6d0\uc758 \ubaa8\uc2b5\uc744 \uc7ac\ud604\ud558\uc9c0 \uc54a\uc558\ub2e4. \uc5ed\ud560\uc744 \ub098\ub204\uae30 \uc704\ud574 \uc0ac\ub78c\ub4e4\uc774 \ub300\ud654\ud558\ub294 \uc7a5\uba74\uc744 \ud45c\ud604\ud588\ub2e4. \uc774 \uae00 \uc5ed\uc2dc 2013~2015\ub144\uc744 \uc911\uc2ec\uc73c\ub85c \uc18c\uac1c\ub41c \uc0ac\ub840\ub97c \uc77d\ub294 \uac83\uc774\uba70 \ud604\uc7ac \ud68c\uc0ac\uc758 \uc870\uc9c1\ub3c4\ub97c \uc548\ub0b4\ud558\ub294 \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uc790\ud3ec\uc2a4\uc758 \uc2e4\ud5d8\uc740 \uc88b\uc740 \uc77c\ud130\ub97c \ud2b9\uc815\ud55c \uc9c1\ud568\uc758 \uc720\ubb34\ub85c \ud310\ub2e8\ud558\uae30 \uc5b4\ub835\ub2e4\ub294 \uac83\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc790\uc720\ub86d\uac8c \uc77c\ud55c\ub2e4\ub294 \ub9d0\uc5d0\ub294 \uacb0\uc815\uc744 \ub3d5\ub294 \uc815\ubcf4\uc640 \ucc45\uc784\uc744 \ub098\ub204\ub294 \uc57d\uc18d\uc774 \ud568\uaed8 \ud544\uc694\ud558\ub2e4. \ub204\uac00 \uc0c1\uc0ac\uc778\uac00\ub97c \ubb3b\ub358 \uc790\ub9ac\uc5d0\uc11c, \uc77c\uc744 \uc798\ud558\ub824\uba74 \uc11c\ub85c\uc5d0\uac8c \ubb34\uc5c7\uc774 \ud544\uc694\ud55c\uac00\ub97c \ubb3b\uac8c \ub418\ub294 \uc774\uc57c\uae30\ub2e4."}, {"id": "ai-clothing-labels", "title": "AI\ub294 \uc637 \uc0ac\uc9c4\uc73c\ub85c \ubb34\uc5c7\uc744 \uc5f0\uc2b5\ud560\uae4c", "summary": "AI\uc758 \uc774\ubbf8\uc9c0 \ud559\uc2b5\uc744 \uc637\uc7a5 \uc815\ub9ac\ucc98\ub7fc \ub4e4\uc5ec\ub2e4\ubd05\ub2c8\ub2e4. \uc791\uc740 \ud751\ubc31 \uc0ac\uc9c4\uc5d0\ub3c4 \uc5f0\uc2b5\uacfc \uc2dc\ud5d8\uc774 \ub530\ub85c \uc788\uc2b5\ub2c8\ub2e4.", "category": "computing", "category_title": "Computing", "subcategory": "Artificial-Intelligence", "url": "stories/ai-clothing-labels/index.html", "image": "media/ai-clothing-labels.jpg", "alt": "\ud2f0\uc154\uce20\uc640 \ubc14\uc9c0, \uc6b4\ub3d9\ud654 \uc606\uc5d0 \ud53d\uc140 \uaca9\uc790\ub97c \uadf8\ub9b0 \uc124\uba85\uc6a9 AI \uc0bd\ud654", "text": "AI\ub294 \uc637 \uc0ac\uc9c4\uc73c\ub85c \ubb34\uc5c7\uc744 \uc5f0\uc2b5\ud560\uae4c \ud2f0\uc154\uce20\uc640 \uc6b4\ub3d9\ud654\uc5d0 \uc774\ub984\uc744 \ubd99\uc774\ub294 \uc791\uc740 \uc608\uc81c AI\uc758 \uc774\ubbf8\uc9c0 \ud559\uc2b5\uc744 \uc637\uc7a5 \uc815\ub9ac\ucc98\ub7fc \ub4e4\uc5ec\ub2e4\ubd05\ub2c8\ub2e4. \uc791\uc740 \ud751\ubc31 \uc0ac\uc9c4\uc5d0\ub3c4 \uc5f0\uc2b5\uacfc \uc2dc\ud5d8\uc774 \ub530\ub85c \uc788\uc2b5\ub2c8\ub2e4. Artificial-Intelligence \ucef4\ud4e8\ud305 \uc0ac\uc9c4\uc744 \ubcf4\uace0 \ud2f0\uc154\uce20\uc778\uc9c0 \uc6b4\ub3d9\ud654\uc778\uc9c0 \uace0\ub974\ub294 \uc77c\uc740 \uc0ac\ub78c\uc5d0\uac8c \ub300\uac1c \uc5b4\ub835\uc9c0 \uc54a\ub2e4. \uadf8\ub7f0\ub370 \ucef4\ud4e8\ud130\uc5d0\uac8c \uac19\uc740 \uc77c\uc744 \ub9e1\uae30\ub824\uba74 \ubb34\uc5c7\uc744 \ubcf4\uc5ec\uc8fc\uc5b4\uc57c \ud560\uae4c. TensorFlow\uc758 \uacf5\uc2dd \uc785\ubb38 \uc608\uc81c\ub294 \uc637\uacfc \uc2e0\ubc1c \ub4f1\uc758 \uc0ac\uc9c4\uc744 \ubd84\ub958\ud558\ub294 \uacfc\uc815\uc744 \uc18c\uac1c\ud55c\ub2e4. \uac70\ucc3d\ud55c \ud48d\uacbd \uc0ac\uc9c4 \ub300\uc2e0 \uc791\uc740 \ud751\ubc31 \uc774\ubbf8\uc9c0\uac00 \ub4f1\uc7a5\ud55c\ub2e4. \ud2f0\uc154\uce20, \ubc14\uc9c0, \uac00\ubc29, \uc6b4\ub3d9\ud654\ucc98\ub7fc \uc775\uc219\ud55c \ubb3c\uac74\ub4e4\uc774\ub2e4. \uc5b4\ub824\uc6b4 \ucf54\ub4dc\ub97c \ub530\ub77c \ud558\uc9c0 \uc54a\uace0\ub3c4 \uc774 \uc608\uc81c\uac00 \uc5b4\ub5a4 \ubc29\uc2dd\uc73c\ub85c \uc900\ube44\ub418\uc5b4 \uc788\ub294\uc9c0\ub294 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \uc608\uc81c\uc5d0\uc11c \uc0ac\uc6a9\ud558\ub294 Fashion-MNIST\uc5d0\ub294 \uc774\ubbf8\uc9c0\uc640 \ud568\uaed8 \uc885\ub958\ub97c \ub098\ud0c0\ub0b4\ub294 \ud45c\uc9c0\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \uc0ac\ub78c\uc758 \ub208\uc5d0\ub294 \uc637\uc73c\ub85c \ubcf4\uc774\ub294 \uc0ac\uc9c4\uc5d0, \ucef4\ud4e8\ud130\uac00 \ucc98\ub9ac\ud560 \uc218 \uc788\ub294 \uc815\ub2f5\uc744 \ubd99\uc5ec \ub454 \uc148\uc774\ub2e4. \uc774\ubbf8\uc9c0\ub294 \uac00\ub85c\uc640 \uc138\ub85c\uac00 \uac01\uac01 28\uce78\uc778 \uc791\uc740 \uaca9\uc790\ub85c \ud45c\ud604\ub41c\ub2e4. \uac01 \uce78\uc5d0\ub294 \ubc1d\uae30\ub97c \ub098\ud0c0\ub0b4\ub294 \uc22b\uc790\uac00 \ub4e4\uc5b4\uac04\ub2e4. \ud654\uba74\uc5d0 \ubcf4\uc774\ub294 \uadf8\ub9bc\uc744 \uacc4\uc0b0\ud560 \uc218 \uc788\ub294 \uac12\uc73c\ub85c \ub2e4\ub8e8\ub294 \uac83\uc774\ub2e4. \ubd84\ub958 \ub300\uc0c1\uc740 \uc5f4 \uc885\ub958\ub2e4. \uc774 \uc608\uc81c\uc758 \ubaa8\ub378\uc740 \uba3c\uc800 \uc815\ud574\uc9c4 \uc885\ub958\ub4e4 \uac00\uc6b4\ub370 \uc5b4\ub290 \ucabd\uc5d0 \uac00\uae4c\uc6b4\uc9c0 \uc5f0\uc2b5\ud55c\ub2e4. \uc138\uc0c1\uc758 \ubaa8\ub4e0 \uc637\uc744 \uc790\uc720\ub86d\uac8c \uc124\uba85\ud558\ub294 \uc2dc\uc2a4\ud15c\uc744 \ub9cc\ub4dc\ub294 \uac83\uacfc\ub294 \ubc94\uc704\uac00 \ub2e4\ub974\ub2e4. \uacf5\uc2dd \uc608\uc81c\ub294 \ud559\uc2b5\uc5d0 \uc4f0\ub294 \uc774\ubbf8\uc9c0 6\ub9cc \uc7a5\uacfc \ud3c9\uac00\uc5d0 \uc4f0\ub294 \uc774\ubbf8\uc9c0 1\ub9cc \uc7a5\uc744 \uad6c\ubd84\ud55c\ub2e4. \uc5f0\uc2b5\ud560 \ub54c \ubcf4\ub358 \uc0ac\uc9c4\uacfc \ub2e4\ub978 \uc0ac\uc9c4\uc5d0\uc11c\ub3c4 \ubd84\ub958\uac00 \uc798 \ub418\ub294\uc9c0 \ud655\uc778\ud558\ub824\ub294 \uad6c\uc131\uc774\ub2e4. \uc774\ubbf8 \ubcf8 \ubb38\uc81c\uc5d0\uc11c \uc798\ud588\ub2e4\uace0 \uc0c8\ub85c\uc6b4 \ubb38\uc81c\uc5d0\uc11c\ub3c4 \uac19\uc740 \uacb0\uacfc\ub97c \ub0b8\ub2e4\uace0 \uc7a5\ub2f4\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc608\uc81c\ub294 \uc774 \ucc28\uc774\uc640 \uacfc\uc801\ud569\uc774\ub77c\ub294 \ubb38\uc81c\ub3c4 \uc124\uba85\ud55c\ub2e4. \uc5ec\uae30\uc11c\ub294 \ud559\uc2b5\uc6a9 \uc0ac\uc9c4\uc744 \uc798 \ub9de\ud788\ub294 \uc77c\uacfc \uc0c8\ub85c\uc6b4 \uc0ac\uc9c4\uc744 \uc798 \ub9de\ud788\ub294 \uc77c\uc774 \ub2e4\ub974\ub2e4\ub294 \uc815\ub3c4\ub85c \uc774\ud574\ud558\uba74 \ub41c\ub2e4. \uc774 \uae00\uc5d0\uc11c \ubaa8\ub378\uc744 \uc9c1\uc811 \uc2e4\ud589\ud574 \uc131\ub2a5\uc744 \uce21\uc815\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uacf5\uc2dd \ubb38\uc11c\uac00 \uc5b4\ub5a4 \uc5f0\uc2b5\uacfc \ud3c9\uac00\ub97c \uc548\ub0b4\ud558\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uac83\uc774\ub2e4. \ub530\ub77c\uc11c \uc5ec\uae30\uc758 \uc124\uba85\uc774\ub098 \uc0bd\ud654\ub97c \uc2e4\uc81c \uc2e4\ud5d8 \uacb0\uacfc\ub85c \ubc1b\uc544\ub4e4\uc774\uba74 \uc548 \ub41c\ub2e4. \uc791\uc740 \uc774\ubbf8\uc9c0 \ud55c \uc7a5\uc740 \ubc1d\uae30\uc758 \uc22b\uc790\ub4e4\ub85c \ud45c\ud604\ub418\uace0, \uc815\ub2f5\ud45c\uc5d0\ub294 \uadf8 \uc774\ubbf8\uc9c0\uac00 \uc5b4\ub290 \uc885\ub958\uc5d0 \uc18d\ud558\ub294\uc9c0 \uc801\ud600 \uc788\ub2e4. \uc774 \ub458\uc774 \ud568\uaed8 \uc788\uc5b4\uc57c \uc5b4\ub5a4 \uc785\ub825\uc5d0 \uc5b4\ub5a4 \ub2f5\uc744 \uc5f0\uacb0\ud558\ub824\ub294\uc9c0 \uc54c \uc218 \uc788\ub2e4. \uc0ac\uc9c4 \uc18d \ubb3c\uac74\uc758 \uc774\ub984\uc744 \ucef4\ud4e8\ud130\uac00 \ucc98\uc74c\ubd80\ud130 \uc0ac\ub78c\ucc98\ub7fc \uc54c\uace0 \uc788\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc900\ube44\ub41c \uc608\ub97c \ud1b5\ud574 \uad6c\ubd84\ud558\ub294 \ubc29\uc2dd\uc744 \uc870\uc815\ud558\ub294 \uac83\uc774\ub2e4. \uac00\ub85c 28\uce78\uacfc \uc138\ub85c 28\uce78\uc744 \uacf1\ud558\uba74 784\uac1c\uc758 \uc704\uce58\uac00 \ub41c\ub2e4. \uc0ac\ub78c\uc740 \uc791\uc740 \uc2e4\ub8e8\uc5e3\uc744 \ud55c\ub208\uc5d0 \uc637\uc73c\ub85c \ubcfc \uc218 \uc788\uc9c0\ub9cc, \uacc4\uc0b0\uc5d0\uc11c\ub294 \uc774 \ubc1d\uae30\ub4e4\uc758 \uad00\uacc4\ub97c \ub2e4\ub8ec\ub2e4. \uc18c\ub9e4\uc640 \uad7d\uc774\ub77c\ub294 \ub9d0\uc744 \ucc98\uc74c\ubd80\ud130 \ubd99\uc5ec \ub193\uc9c0 \uc54a\uc544\ub3c4 \uc774\ubbf8\uc9c0\uc5d0 \ub098\ud0c0\ub09c \ubaa8\uc591\uc758 \ucc28\uc774\uac00 \ubd84\ub958\uc5d0 \uc4f0\uc77c \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ubb34\uc5c7\uc744 \uc5b4\ub5a4 \ubc29\uc2dd\uc73c\ub85c \uad6c\ubd84\ud588\ub294\uc9c0\ub294 \uc2e4\uc81c \ubaa8\ub378\uacfc \uacb0\uacfc\ub97c \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uac19\uc740 \uc0ac\uc9c4\uc744 \ubc18\ubcf5\ud574\uc11c \ubcf8 \ub4a4 \ub2f5\uc744 \uc798 \ub9de\ud788\ub294 \uc77c\ub9cc\uc73c\ub85c\ub294 \ucda9\ubd84\ud558\uc9c0 \uc54a\ub2e4. \uc2dc\ud5d8\uc5d0 \uc4f8 \uc774\ubbf8\uc9c0\ub97c \ub530\ub85c \ub450\ub294 \uae4c\ub2ed\uc740 \ucc98\uc74c \ubcf4\ub294 \uc790\ub8cc\uc5d0\uc11c\ub3c4 \ubc30\uc6b4 \uad6c\ubd84\uc774 \ud1b5\ud558\ub294\uc9c0 \ud655\uc778\ud558\uae30 \uc704\ud574\uc11c\ub2e4. \ud559\uad50\uc5d0\uc11c \uc5f0\uc2b5 \ubb38\uc81c\uc758 \ub2f5\uc744 \uc678\uc6b0\ub294 \uc77c\uacfc \uc870\uae08 \ub2ec\ub77c\uc9c4 \ubb38\uc81c\ub97c \uc774\ud574\ud558\ub294 \uc77c\uc744 \ub098\ub204\ub294 \ube44\uc720\ub85c \uc0dd\uac01\ud574 \ubcfc \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uc0ac\ub78c\uc758 \uc2dc\ud5d8\uacfc \uae30\uacc4\uc758 \ud559\uc2b5\uc774 \uac19\uc740 \uc6d0\ub9ac\ub77c\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc5ec\uae30\uc11c \uc911\uc694\ud55c \uac83\uc740 \ud3c9\uac00\ud560 \uc790\ub8cc\ub97c \uc5f0\uc2b5 \uc790\ub8cc\uc640 \uad6c\ubcc4\ud55c\ub2e4\ub294 \uc124\uacc4\ub2e4. \ud559\uc2b5\uc6a9 6\ub9cc \uc7a5\uc774\ub77c\ub294 \ud070 \uc22b\uc790\ubcf4\ub2e4 \uadf8 \uc22b\uc790\uac00 \uc5b4\ub5a4 \uc5ed\ud560\ub85c \ub098\ub258\uc5c8\ub294\uc9c0 \ubcf4\uba74 \uc608\uc81c\uc758 \ubaa9\uc801\uc774 \uc120\uba85\ud574\uc9c4\ub2e4. \uc790\ub8cc\uac00 \ub9ce\ub2e4\ub294 \ub9d0\ub9cc\uc73c\ub85c \uac80\uc99d\uc774 \ucda9\ubd84\ud588\ub2e4\uace0 \uacb0\ub860\ub0b4\ub9b4 \uc218\ub294 \uc5c6\ub2e4. \uc774 \uc608\uc81c\ub294 \uc5f4 \uc885\ub958 \uac00\uc6b4\ub370 \ud558\ub098\ub97c \uace0\ub978\ub2e4. \uc0ac\ub78c\uc774 \uc0ac\uc9c4\uc744 \ubcf4\uace0 \uc0c9\uc774\ub098 \uc7ac\uc9c8, \uc5b4\uc6b8\ub9ac\ub294 \uacc4\uc808\uc744 \uc790\uc720\ub86d\uac8c \ub9d0\ud558\ub294 \uc77c\uacfc \ubc94\uc704\uac00 \ub2e4\ub974\ub2e4. \ubaa8\ub378\uc774 \uc120\ud0dd\ud560 \uc218 \uc788\ub294 \ub2f5\uc758 \ubaa9\ub85d\uc774 \uba3c\uc800 \uc815\ud574\uc838 \uc788\ub2e4. \uc9c8\ubb38\uc774 \uc5b4\ub5bb\uac8c \ub9cc\ub4e4\uc5b4\uc84c\ub294\uc9c0 \uc54c\uba74 AI\uac00 \uc637\uc744 \uc774\ud574\ud55c\ub2e4\ub294 \ud45c\ud604\uc744 \uc870\uae08 \ub354 \uad6c\uccb4\uc801\uc73c\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \uc608\uc81c \ubc16\uc758 \ub0af\uc120 \ubb3c\uac74\uc774 \ub4e4\uc5b4\uc624\ub354\ub77c\ub3c4 \ub2f5\uc758 \ud615\uc2dd\uc774 \uc790\ub3d9\uc73c\ub85c \ub113\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub290 \ubc94\uc704\uc758 \uc0ac\uc9c4\uacfc \ubd84\ub958\ub97c \uc704\ud574 \uc900\ube44\ud55c \ubaa8\ub378\uc778\uc9c0 \ud655\uc778\ud558\ub294 \uc77c\uc774 \ud544\uc694\ud558\ub2e4. \ud55c \uc2dc\ud5d8\uc5d0\uc11c\uc758 \uacb0\uacfc\ub97c \uc138\uc0c1\uc758 \ubaa8\ub4e0 \uc0c1\ud488 \uc778\uc2dd \ub2a5\ub825\uc73c\ub85c \ud655\ub300\ud558\uc9c0 \uc54a\uc73c\uba74 \uc791\uc740 \uc2e4\ud5d8\uc744 \ub354 \uc815\ud655\ud558\uac8c \ud3c9\uac00\ud560 \uc218 \uc788\ub2e4. \uc881\uc740 \ubc94\uc704\ub97c \uc798 \uc815\ud55c \uc608\uc81c\ub3c4 \ucda9\ubd84\ud788 \uc720\uc6a9\ud558\ub2e4. \ubaa8\ub378\uc774 \uc5b4\ub5a4 \uc885\ub958\ub97c \uac15\ud558\uac8c \uc120\ud0dd\ud588\ub2e4\uace0 \uc2e4\uc81c \uc815\ub2f5\ub3c4 \ubc18\ub4dc\uc2dc \uadf8 \uc885\ub958\uc778 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubb38\uc11c\ub294 \ub192\uc740 \ud655\uc2e0\uc73c\ub85c \uc798\ubabb \uace0\ub97c \uc218 \uc788\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ub2f5\uc5d0 \ubd99\uc740 \uc218\uce58\uc640 \uc2e4\uc81c \uc815\ud655\uc131\uc740 \ub098\ub780\ud788 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc218\uce58\ub97c \uc0ac\ub78c\uc774 \ub290\ub07c\ub294 \uc790\uc2e0\uac10\uacfc \uc644\uc804\ud788 \uac19\uc740 \ub9c8\uc74c \uc0c1\ud0dc\ub85c \ud574\uc11d\ud560 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \uc774 \uc810\uc740 \uacb0\uacfc\ub97c \uc0ac\uc6a9\ud558\ub294 \uc0ac\ub78c\uc758 \uc5ed\ud560\uacfc \uc774\uc5b4\uc9c4\ub2e4. \uc5b4\ub5a4 \uc885\ub958\uc5d0\uc11c \uc798\ubabb \uace0\ub974\ub294\uc9c0, \uc0c8 \uc0ac\uc9c4\uc774 \uc6d0\ub798 \uc790\ub8cc\uc640 \uc5bc\ub9c8\ub098 \ub2e4\ub978\uc9c0 \ubb3c\uc5b4\ubcf4\uc544\uc57c \ud55c\ub2e4. AI\uc758 \ub2f5\uc744 \uc77d\uc744 \ub54c\uc5d0\ub294 \ub9de\ud614\ub290\ub0d0\ub294 \uc9c8\ubb38 \uc606\uc5d0 \uc5b4\ub5a4 \ubb38\uc81c\uc5d0\uc11c \ud655\uc778\ud588\ub290\ub0d0\ub97c \ub193\uc544 \ubcf4\uc790. \uc791\uc740 \ud68c\uc0c9 \ud2f0\uc154\uce20 \uc0ac\uc9c4\uc73c\ub85c \uc2dc\uc791\ud55c \uc774\uc57c\uae30\uac00 \uc790\ub8cc\uc640 \uac80\uc99d\uc758 \uc870\uac74\uc744 \uc77d\ub294 \uc5f0\uc2b5\uc774 \ub41c\ub2e4. \uc608\uc81c\uc5d0\uc11c\ub294 \ubaa8\ub378\uc774 \uac01 \uc885\ub958\uc5d0 \ub300\ud574 \ub0b4\ub193\uc740 \uac12\uc744 \ube44\uad50\ud574 \ub2f5\uc744 \uc0b4\ud540\ub2e4. \ubb38\uc11c\uac00 \ud568\uaed8 \uac15\uc870\ud558\ub294 \uac83\uc740 \uc790\uc2e0 \uc788\uac8c \uace0\ub978 \ub2f5\ub3c4 \ud2c0\ub9b4 \uc218 \uc788\ub2e4\ub294 \uc810\uc774\ub2e4. \uc774 \uc0ac\uc2e4\uc744 \uc54c\uba74 AI\uac00 \uc774\ubbf8\uc9c0\ub97c \ubd84\ub958\ud55c\ub2e4\ub294 \ub9d0\uc744 \uc870\uae08 \uad6c\uccb4\uc801\uc73c\ub85c \uc774\ud574\ud558\uac8c \ub41c\ub2e4. \uc5b4\ub5a4 \uc0ac\uc9c4\uc73c\ub85c \ubb34\uc5c7\uc744 \uc5f0\uc2b5\ud588\uace0, \uc5b4\ub5a4 \uc885\ub958 \uc911\uc5d0\uc11c \ub2f5\uc744 \uace8\ub790\uc73c\uba70, \uc0c8 \uc0ac\uc9c4\uc73c\ub85c \uc5b4\ub5bb\uac8c \ud655\uc778\ud588\ub294\uc9c0\uae4c\uc9c0 \ubcf4\uac8c \ub41c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc637 \uc0ac\uc9c4\uc744 \ubcfc \ub54c\ub9c8\ub2e4 \uc22b\uc790 \uaca9\uc790\ub97c \ub5a0\uc62c\ub9b4 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc0ac\ub78c\uc5d0\uac8c \uc775\uc219\ud55c \ubb3c\uac74\ub3c4 \ucef4\ud4e8\ud130\uc758 \uc5f0\uc2b5 \ubb38\uc81c\uac00 \ub420 \uc218 \uc788\ub2e4\ub294 \uac83\ub9cc\uc73c\ub85c \uc7ac\ubbf8\uc788\ub294 \uc2dc\uc791\uc774\ub2e4. \ub2e4\uc74c\uc5d0 AI\uac00 \uc0ac\uc9c4\uc5d0 \uc774\ub984\uc744 \ubd99\uc774\ub294 \ubaa8\uc2b5\uc744 \ubcf4\uba74 \ub2f5 \ud558\ub098\ub9cc \ubcf4\uc9c0 \ub9d0\uace0 \uadf8 \ub4a4\uc758 \uc5f0\uc2b5 \ubb38\uc81c\ub3c4 \uc0dd\uac01\ud574 \ubcf4\uc790. \uc791\uc740 \ud2f0\uc154\uce20 \uc0ac\uc9c4 \ud55c \uc7a5\uc774 \uc758\uc678\ub85c \ub9ce\uc740 \uc900\ube44\ub97c \ud488\uace0 \uc788\ub2e4."}, {"id": "alt-text-image-in-words", "title": "\ub300\uccb4 \ud14d\uc2a4\ud2b8 \u2014 \uadf8\ub9bc\uc744 \ub9d0\ub85c \uc804\ud55c\ub2e4\uba74", "summary": "\uc0ac\uc9c4\uc758 \ubaa9\uc801\uc5d0 \ub530\ub77c \uc124\uba85\uc774 \ub2ec\ub77c\uc9c0\ub294 \uc774\uc720\ub97c \ud1b5\ud574 \uc6f9 \uc774\ubbf8\uc9c0\uc758 \ub300\uccb4 \ud14d\uc2a4\ud2b8\uc640 \uc811\uadfc\uc131\uc744 \uc27d\uac8c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "computing", "category_title": "Computing", "subcategory": "Internet", "url": "stories/alt-text-image-in-words/index.html", "image": "media/alt-text-image-in-words.png", "alt": "\uac00\uc0c1\uc758 \ud48d\uacbd\ud654\ub97c \uc55e\uc5d0 \ub450\uace0 \uadf8\ub9bc \uc124\uba85\uc744 \ub098\ub204\ub294 \ub450 \uc0ac\ub78c\uacfc \uc606\uc758 \ud0dc\ube14\ub9bf\u00b7\ud5e4\ub4dc\ud3f0.", "text": "\ub300\uccb4 \ud14d\uc2a4\ud2b8 \u2014 \uadf8\ub9bc\uc744 \ub9d0\ub85c \uc804\ud55c\ub2e4\uba74 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc774\ubbf8\uc9c0\uc5d0\uc11c \ubb34\uc5c7\uc774 \ube60\uc9c0\ub294\uc9c0 \ubb3b\uae30 \uc0ac\uc9c4\uc758 \ubaa9\uc801\uc5d0 \ub530\ub77c \uc124\uba85\uc774 \ub2ec\ub77c\uc9c0\ub294 \uc774\uc720\ub97c \ud1b5\ud574 \uc6f9 \uc774\ubbf8\uc9c0\uc758 \ub300\uccb4 \ud14d\uc2a4\ud2b8\uc640 \uc811\uadfc\uc131\uc744 \uc27d\uac8c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Internet \ucef4\ud4e8\ud305 \uc778\ud130\ub137\uc5d0\uc11c \uc774\ubbf8\uc9c0\ub97c \uae30\ub2e4\ub9ac\ub294\ub370 \ube48\uc790\ub9ac\uc5d0 \uc9e7\uc740 \ubb38\uc7a5\ub9cc \ubcf4\uc778 \uc801\uc774 \uc788\uc744 \uac83\uc774\ub2e4. \ud30c\uc77c\uc774 \uc624\uc9c0 \uc54a\uc558\uc744 \ub54c \uc0ac\uc9c4 \ub300\uc2e0 \ub098\ud0c0\ub098\ub294 \ub9d0\uc77c \uc218 \uc788\ub2e4. \uadf8\ub7f0\ub370 \uc774 \ubb38\uc7a5\uc740 \uace0\uc7a5 \ub09c \ud654\uba74\uc744 \uc704\ud55c \uc784\uc2dc \uc548\ub0b4\uc5d0\ub9cc \uc4f0\uc774\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uadf8\ub9bc\uc744 \uc9c1\uc811 \ubcfc \uc218 \uc5c6\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub3c4 \ub0b4\uc6a9\uc744 \uc804\ub2ec\ud55c\ub2e4. \uc6f9\uc5d0\uc11c\ub294 \uc774\ub7f0 \uc124\uba85\uc744 \ub300\uccb4 \ud14d\uc2a4\ud2b8\ub77c\uace0 \ubd80\ub978\ub2e4. \uc911\uc694\ud55c \uc9c8\ubb38\uc740 \uadf8\ub9bc\uc5d0 \ubb34\uc5c7\uc774 \uc788\ub294\uac00\uc5d0\uc11c \ud55c \uac78\uc74c \ub354 \ub098\uc544\uac04\ub2e4. \uc774 \ud398\uc774\uc9c0\uc5d0\uc11c \uadf8 \uadf8\ub9bc\uc774 \uc5b4\ub5a4 \uc77c\uc744 \ud558\uace0 \uc788\uc73c\uba70, \ubcf4\uc774\uc9c0 \uc54a\uc73c\uba74 \uc5b4\ub5a4 \uc815\ubcf4\uac00 \uc0ac\ub77c\uc9c0\ub294\uac00\ub97c \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4. \uc5b4\ub5a4 \ub3c5\uc790\ub294 \ud654\uba74 \uc77d\uae30 \ud504\ub85c\uadf8\ub7a8\uc73c\ub85c \uc6f9\uc744 \uc774\uc6a9\ud55c\ub2e4. \uc5b4\ub5a4 \ub3c5\uc790\ub294 \ud1b5\uc2e0 \ud658\uacbd \ub54c\ubb38\uc5d0 \uc774\ubbf8\uc9c0\uac00 \ub2a6\uac8c \uc624\uac70\ub098 \ud45c\uc2dc\ub418\uc9c0 \uc54a\ub294\ub2e4. MDN\uc740 \ub300\uccb4 \ud14d\uc2a4\ud2b8\uac00 \uc774\ub7f0 \uc0c1\ud669\uc5d0\uc11c \ub3c4\uc6c0\uc774 \ub41c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc6f9\ud398\uc774\uc9c0\uc758 \ub3c5\uc790\uac00 \ubaa8\ub450 \uac19\uc740 \ud654\uba74\uc744 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ub9cc\ub098\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub530\ub77c\uc11c \ub300\uccb4 \ud14d\uc2a4\ud2b8\ub294 \ud2b9\uc815\ud55c \ud55c \uacbd\uc6b0\uc5d0\ub9cc \ub367\ubd99\uc774\ub294 \uc7a5\uc2dd\uc774 \uc544\ub2c8\ub2e4. \ub0b4\uc6a9\uc5d0 \uc811\uadfc\ud558\ub294 \ub2e4\ub978 \uae38\uc744 \ub9c8\ub828\ud558\ub294 \uc77c\uc774\ub2e4. \uc0ac\uc9c4\uc744 \ucda9\ubd84\ud788 \ud06c\uac8c \ub123\uc5c8\ub2e4\uace0 \ubaa8\ub4e0 \ub3c5\uc790\uc5d0\uac8c \uc815\ubcf4\uac00 \uc804\ub2ec\ub41c \uac83\uc740 \uc544\ub2d0 \uc218 \uc788\ub2e4. \ubb34\uc5c7\uc744 \ubcf4\uc774\uac8c \ud588\ub294\uc9c0\uc640 \ub204\uac00 \uadf8\uac83\uc744 \ubc1b\uc544\ub4e4\uc77c \uc218 \uc788\ub294\uc9c0\ub294 \ud568\uaed8 \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4. \uac00\uc0c1\uc758 \ub3c4\uc2dc \uc0b0\ucc45 \uae00\uc5d0 \ub2e4\ub9ac \uc0ac\uc9c4\uc744 \ub123\uc5c8\ub2e4\uace0 \ud574 \ubcf4\uc790. \ub300\uccb4 \ud14d\uc2a4\ud2b8\uac00 \uc0ac\uc9c4 \ud55c \uc7a5\uc774\ub77c\uace0\ub9cc \ub418\uc5b4 \uc788\ub2e4\uba74 \ub3c5\uc790\ub294 \uc5b4\ub5a4 \ub2e4\ub9ac\uc778\uc9c0, \ubb34\uc5c7\uc744 \uc0b4\ud3b4\ubcf4\uc544\uc57c \ud558\ub294\uc9c0 \uc54c\uae30 \uc5b4\ub835\ub2e4. \ud30c\uc77c\uc774 \uc774\ubbf8\uc9c0\ub77c\ub294 \uc0ac\uc2e4\ubcf4\ub2e4 \uc774\ubbf8\uc9c0\uac00 \uc804\ub2ec\ud558\ub294 \ub0b4\uc6a9\uc774 \ub354 \ud544\uc694\ud560 \uc218 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubcf4\uc774\ub294 \ubaa8\ub4e0 \uc0c9\uacfc \ub3cc\uc758 \uc218\ub97c \ub05d\uc5c6\uc774 \uc801\ub294 \uac83\ub3c4 \ud56d\uc0c1 \uc88b\uc740 \ub2f5\uc740 \uc544\ub2c8\ub2e4. \uc0ac\uc9c4\uc774 \ub4e4\uc5b4\uac04 \ubaa9\uc801\uc5d0 \ub9de\ucd94\uc5b4 \uc911\uc694\ud55c \uc815\ubcf4\ub97c \uac04\uacb0\ud558\uac8c \uc804\ud574\uc57c \ud55c\ub2e4. \ub3c5\uc790\uc5d0\uac8c \ub3c4\uc6c0\uc774 \ub418\ub294 \uc124\uba85\uc740 \uc0ac\ubb3c\uc758 \ubaa9\ub85d\uc744 \uae38\uac8c \ub098\uc5f4\ud558\ub294 \uc77c\uacfc \ub2e4\ub974\ub2e4. \uc7a5\uba74\uc758 \ud575\uc2ec\uc744 \uace0\ub974\ub294 \ud3b8\uc9d1\uc774 \ub4e4\uc5b4\uac04\ub2e4. \ud55c \ub2e4\ub9ac \uc0ac\uc9c4\uc774 \uc5ec\ud589\uae30\uc5d0\uc11c\ub294 \ub3c4\uc2dc\uc758 \ubd84\uc704\uae30\ub97c \uc804\ud560 \uc218 \uc788\ub2e4. \uac74\ucd95 \ud574\uc124\uc5d0\uc11c\ub294 \uc544\uce58\uc758 \ud615\ud0dc\ub97c \uc124\uba85\ud558\ub294 \uc790\ub8cc\uc77c \uc218 \uc788\ub2e4. \uac19\uc740 \ud30c\uc77c\uc774\uc5b4\ub3c4 \ud398\uc774\uc9c0\uc5d0\uc11c \ub9e1\uc740 \uc5ed\ud560\uc774 \ub2e4\ub974\uba74 \ube60\uc838\uc11c\ub294 \uc548 \ub418\ub294 \uc815\ubcf4\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \ub300\uccb4 \ud14d\uc2a4\ud2b8\ub294 \uc774\ubbf8\uc9c0\uc640 \ubb38\ub9e5\uc744 \ud568\uaed8 \uc77d\uc5b4\uc57c \ud558\ub294 \uc774\uc720\ub2e4. \uc774\ub54c \uc0ac\uc9c4\uc73c\ub85c \ud655\uc778\ud558\uc9c0 \ubabb\ud55c \uc0ac\uc5f0\uc744 \uc124\uba85\uc5d0 \ubcf4\ud0dc\uba74 \uc548 \ub41c\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \uad6c\uc870\uc640 \uc790\ub8cc\ub85c \ud655\uc778\ud55c \uc0ac\uc2e4\uc744 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ub300\uccb4 \ud14d\uc2a4\ud2b8\ub3c4 \ub3c5\uc790\uac00 \ub0b4\uc6a9\uc744 \ubc1b\uc544\ub4e4\uc774\ub294 \ud1b5\ub85c\uc774\ubbc0\ub85c \uc815\ud655\uc131\uc774 \ud544\uc694\ud558\ub2e4. \uc9e7\uac8c \uc801\ub294\ub2e4\uace0 \uadfc\uac70\uc758 \uae30\uc900\uc774 \uac00\ubcbc\uc6cc\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubaa8\ub4e0 \uc774\ubbf8\uc9c0\uac00 \uc0c8\ub85c\uc6b4 \uc815\ubcf4\ub97c \ub2f4\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubb38\ub2e8 \uc606\uc758 \ub2e8\uc21c\ud55c \uc7a5\uc2dd\ucc98\ub7fc \uc5c6\uc5b4\ub3c4 \ubcf8\ubb38\uc758 \uc758\ubbf8\uac00 \ub2ec\ub77c\uc9c0\uc9c0 \uc54a\ub294 \uacbd\uc6b0\uac00 \uc788\ub2e4. MDN\uc740 \uc774\ub7f0 \uc774\ubbf8\uc9c0\uc5d0 \ube48 \ub300\uccb4 \ud14d\uc2a4\ud2b8\ub97c \uc0ac\uc6a9\ud558\ub294 \ubc29\ubc95\uc744 \uc124\uba85\ud55c\ub2e4. \ud654\uba74 \uc77d\uae30 \ud504\ub85c\uadf8\ub7a8\uc774 \ubd88\ud544\uc694\ud55c \uc124\uba85\uc744 \ubc18\ubcf5\ud558\uc9c0 \uc54a\ub3c4\ub85d \ud558\uae30 \uc704\ud574\uc11c\ub2e4. \uc5ec\uae30\uc11c \ube44\uc6cc \ub454 \uac12\uacfc \uc124\uba85\uc744 \uc0dd\uac01\ud558\uc9c0 \uc54a\uace0 \ub204\ub77d\ud55c \uc0c1\ud0dc\ub294 \uac19\uc9c0 \uc54a\ub2e4. \uc804\uc790\ub294 \uc5ed\ud560\uc744 \ud310\ub2e8\ud55c \uacb0\uacfc\ub2e4. \ubb34\uc5c7\uc774\ub4e0 \ub9ce\uc774 \uc77d\uc5b4 \uc8fc\uba74 \ub354 \uce5c\uc808\ud560 \uac83\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc \uc911\uc694\ud55c \uc815\ubcf4 \uc0ac\uc774\uc5d0 \uc4f8\ubaa8\uc5c6\ub294 \uc18c\ub9ac\uac00 \uacc4\uc18d \ub07c\uba74 \uc774\uc6a9\uc774 \uc5b4\ub824\uc6cc\uc9c8 \uc218 \uc788\ub2e4. \ub35c \ub9d0\ud558\ub294 \uc120\ud0dd\ub3c4 \ub3c5\uc790\ub97c \uc704\ud55c \ud310\ub2e8\uc774 \ub41c\ub2e4. \uc774\ubbf8\uc9c0\ub97c \ub20c\ub7ec \ub2e4\ub978 \ud398\uc774\uc9c0\ub85c \uc774\ub3d9\ud558\uac8c \ub9cc\ub4e4 \uc218\ub3c4 \uc788\ub2e4. \uc774\ub54c\ub294 \uadf8\ub9bc\uc758 \uc0dd\uae40\uc0c8\ub9cc\ud07c \uadf8 \ub9c1\ud06c\uc758 \ubaa9\uc801\uc744 \uc544\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \uc9d1 \ubaa8\uc591 \uadf8\ub9bc\uc774 \uccab \ud654\uba74\uc73c\ub85c \uac00\ub294 \uae30\ub2a5\uc774\ub77c\uba74 \ub3c5\uc790\ub294 \uc9d1\uc758 \uc9c0\ubd95 \uc0c9\ubcf4\ub2e4 \uc5b4\ub514\ub85c \uc774\ub3d9\ud558\ub294\uc9c0 \uc54c\uace0 \uc2f6\uc744 \uc218 \uc788\ub2e4. MDN\uc740 \uc774\ubbf8\uc9c0 \ub9c1\ud06c\uc5d0\ub3c4 \uc811\uadfc \uac00\ub2a5\ud55c \ub9c1\ud06c \uc124\uba85\uc774 \ud544\uc694\ud558\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uadf8\ub9bc\uc758 \ubb18\uc0ac\uc640 \uae30\ub2a5\uc758 \uc548\ub0b4\uac00 \ub9cc\ub098\ub294 \ub300\ubaa9\uc774\ub2e4. \uac19\uc740 \uc791\uc740 \uc544\uc774\ucf58\ub3c4 \ubcf8\ubb38\uc758 \uc0bd\ud654\uc778\uc9c0 \uc6c0\uc9c1\uc774\ub294 \uae38\uc7a1\uc774\uc778\uc9c0\uc5d0 \ub530\ub77c \ud544\uc694\ud55c \ub9d0\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uc758\ubbf8\ub294 \ud30c\uc77c \uc548\uc5d0\ub9cc \ub4e4\uc5b4 \uc788\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \ubcf5\uc7a1\ud55c \ub3c4\ud45c\ub098 \uc911\uc694\ud55c \uc124\uba85\uc744 \uadf8\ub9bc \ud558\ub098\uc5d0\ub9cc \ub2f4\uc73c\uba74 \uc9e7\uc740 \ub300\uccb4 \ud14d\uc2a4\ud2b8\ub85c \ucda9\ubd84\ud788 \uc62e\uae30\uae30 \uc5b4\ub824\uc6b8 \uc218 \uc788\ub2e4. MDN\uc740 \ud544\uc694\ud55c \uc815\ubcf4\ub97c \ubaa8\ub450\uac00 \uc77d\ub294 \ubcf8\ubb38\uc5d0\uc11c\ub3c4 \uc81c\uacf5\ud558\ub294 \ubc29\uc2dd\uc744 \uad8c\ud55c\ub2e4. \uc774\ubbf8\uc9c0\uc758 \ub0b4\uc6a9\uc744 \ub2e4\ub978 \uacbd\ub85c\ub85c \uc804\ud558\ub294 \uac83\uc774 \ud575\uc2ec\uc774\uc9c0 \ud55c \uce78\uc5d0 \ubaa8\ub4e0 \ubb38\uc7a5\uc744 \ubc00\uc5b4 \ub123\ub294 \uac83\uc774 \ubaa9\uc801\uc740 \uc544\ub2c8\ub2e4. \ubcf8\ubb38\uc774 \uc774\ubbf8 \ucda9\ubd84\ud788 \uc124\uba85\ud55c \ub0b4\uc6a9\uc744 \uadf8\ub300\ub85c \ubc18\ubcf5\ud558\uba74 \uc624\ud788\ub824 \uc9c0\ub8e8\ud558\uace0 \ud63c\ub780\uc2a4\ub7ec\uc6b8 \uc218 \uc788\ub2e4. \ubb34\uc5c7\uc744 \uc5b4\ub514\uc5d0\uc11c \uc804\ub2ec\ud588\ub294\uc9c0 \ud568\uaed8 \uc0b4\ud53c\ub294 \uc77c\uc774 \ud544\uc694\ud558\ub2e4. \uadf8\ub798\uc11c \ub300\uccb4 \ud14d\uc2a4\ud2b8\ub294 \ud30c\uc77c\uc744 \ub9c8\uc9c0\ub9c9\uc5d0 \uc62c\ub9b4 \ub54c\ub9cc \uc4f0\ub294 \ud56d\ubaa9\ubcf4\ub2e4 \uae00\uacfc \uadf8\ub9bc\uc744 \ud568\uaed8 \ud3b8\uc9d1\ud558\ub294 \uacfc\uc815\uc5d0 \uac00\uae5d\ub2e4. \uadf8\ub9bc \uc544\ub798\uc758 \ucea1\uc158\uc740 \ubcf4\ud1b5 \ubaa8\ub4e0 \ub3c5\uc790\uac00 \ud654\uba74\uc5d0\uc11c \uc77d\ub294 \uc124\uba85\uc774\ub2e4. \uc791\uac00\uc640 \uc5f0\ub3c4, \ucd9c\ucc98\uc640 \ub9e5\ub77d\uc744 \uc54c\ub824 \uc904 \uc218\ub3c4 \uc788\ub2e4. \ub300\uccb4 \ud14d\uc2a4\ud2b8\ub294 \uc774\ubbf8\uc9c0\ub97c \uc9c1\uc811 \ubcfc \uc218 \uc5c6\ub294 \uc0c1\ud669\uc5d0\uc11c \uadf8 \uc5ed\ud560\uc744 \ub300\uc2e0\ud560 \uc815\ubcf4\ub97c \uc81c\uacf5\ud55c\ub2e4. \ubaa9\uc801\uc774 \uc77c\ubd80 \uacb9\uccd0\ub3c4 \uc5b8\uc81c\ub098 \uac19\uc740 \ubb38\uc7a5\uc744 \ubcf5\uc0ac\ud558\ub294 \uac83\uc774 \uc815\ub2f5\uc740 \uc544\ub2c8\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uac00\uc0c1\uc758 \uadf8\ub9bc\uc744 \ub450\uace0 \uc124\uba85\uc744 \ub098\ub204\ub294 \uc7a5\uba74\uc774\ub2e4. \ud2b9\uc815 \ubc15\ubb3c\uad00\uc758 \uc2e4\uc81c \uc791\ud488\uc774\ub098 \ud604\uc7a5 \uc548\ub0b4\ub97c \uc7ac\ud604\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uc791\ud488\uc744 \uc9c1\uc811 \ubcf4\ub294 \uae38\uacfc \ub9d0\ub85c \uc124\uba85\uc744 \ub4e3\ub294 \uae38\uc774 \ud568\uaed8 \uc788\uc744 \uc218 \uc788\ub2e4\ub294 \uc0dd\uac01\uc744 \ud45c\ud604\ud588\ub2e4. \uc774\ubbf8\uc9c0\ub97c \ubd99\uc774\ub294 \uc21c\uac04 \uae00\uc740 \ub354 \ud48d\ubd80\ud574\uc9c8 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \uc774\ubbf8\uc9c0\uac00 \ubcf4\uc774\uc9c0 \uc54a\ub294 \ub3c5\uc790\uc5d0\uac8c\ub3c4 \uc911\uc694\ud55c \ub0b4\uc6a9\uc774 \ub0a8\uc544 \uc788\ub294\uc9c0 \ud55c \ubc88 \ub354 \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \uadf8\ub9bc\uc744 \uace0\ub974\ub294 \uc77c\uacfc \uadf8\ub9bc\uc758 \uc5ed\ud560\uc744 \uc124\uba85\ud558\ub294 \uc77c\uc740 \uac19\uc740 \ud3b8\uc9d1\uc758 \ub2e4\ub978 \ub2e8\uacc4\ub2e4. \ub2e4\uc74c\uc5d0 \uc0ac\uc9c4\uc744 \ub123\uc744 \ub54c \uc7a0\uae50 \ub208\uc744 \uac10\uace0 \uc774 \uadf8\ub9bc\uc774 \ube60\uc9c0\uba74 \ubb34\uc5c7\uc744 \ub193\uce58\ub294\uc9c0 \uc0dd\uac01\ud574 \ubcf4\uc790. \ub2f5\uc774 \uc7a5\uc2dd\uc774\ub77c\uba74 \uc870\uc6a9\ud788 \uc9c0\ub098\uac00\uac8c \ud560 \uc218 \uc788\uace0, \ub2f5\uc774 \uc911\uc694\ud55c \uc815\ubcf4\ub77c\uba74 \uadf8 \ub0b4\uc6a9\uc744 \ub2e4\ub978 \uae38\ub85c\ub3c4 \uc804\ud574\uc57c \ud55c\ub2e4. \ub300\uccb4 \ud14d\uc2a4\ud2b8\ub294 \uc6f9\uc758 \uc791\uc740 \uc124\uba85\uc774 \uc5b4\ub5bb\uac8c \ub354 \ub9ce\uc740 \uc0ac\ub78c\uc5d0\uac8c \uc77d\uc744\uac70\ub9ac\ub97c \uc5f4\uc5b4 \uc8fc\ub294\uc9c0 \ubcf4\uc5ec \uc900\ub2e4."}, {"id": "computer-time-repeated-hour", "title": "\ucef4\ud4e8\ud130\uc758 \uc2dc\uacc4 \u2014 \uc624\uc804 1\uc2dc\uac00 \ub450 \ubc88 \uc624\ub294 \ub0a0", "summary": "\ub85c\uc2a4\uc564\uc824\ub808\uc2a4\uc758 \uacfc\uac70 \uc11c\uba38\ud0c0\uc784 \uc0ac\ub840\ub85c UTC\u00b7\uc2dc\uac04\ub300\u00b7\ud604\uc9c0 \uc2dc\uac01\uc758 \ucc28\uc774\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "computing", "category_title": "Computing", "subcategory": "Software", "url": "stories/computer-time-repeated-hour/index.html", "image": "media/computer-time-repeated-hour.png", "alt": "\uc5ec\ud589 \uac00\ubc29\uacfc \uc77c\uc815\ud45c \uc606\uc5d0\uc11c \ud734\ub300\uc804\ud654\ub97c \uc0b4\ud53c\ub294 \uc0ac\ub78c\uc758 \uc0bd\ud654.", "text": "\ucef4\ud4e8\ud130\uc758 \uc2dc\uacc4 \u2014 \uc624\uc804 1\uc2dc\uac00 \ub450 \ubc88 \uc624\ub294 \ub0a0 \uac19\uc740 \uc21c\uac04\uacfc \uac19\uc740 \uc2dc\uac01 \ud45c\uc2dc\ub294 \ub2e4\ub97c \uc218 \uc788\ub2e4 \ub85c\uc2a4\uc564\uc824\ub808\uc2a4\uc758 \uacfc\uac70 \uc11c\uba38\ud0c0\uc784 \uc0ac\ub840\ub85c UTC\u00b7\uc2dc\uac04\ub300\u00b7\ud604\uc9c0 \uc2dc\uac01\uc758 \ucc28\uc774\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Software \ucef4\ud4e8\ud305 \uae30\ub85d\uc5d0 \uc624\uc804 1\uc2dc\uac00 \ucc0d\ud600 \uc788\ub2e4. \ud55c \uc2dc\uac04 \ub4a4\uc758 \uae30\ub85d\uc5d0\ub3c4 \uc624\uc804 1\uc2dc\uac00 \ucc0d\ud600 \uc788\ub2e4. \uc2dc\uacc4\uac00 \uace0\uc7a5 \ub09c \uac83\uc77c\uae4c. \uc11c\uba38\ud0c0\uc784\uc774 \ub05d\ub098\uba70 \uc2dc\uacc4\ub97c \ub418\ub3cc\ub9ac\ub294 \uc9c0\uc5ed\uc5d0\uc11c\ub294 \uc2e4\uc81c\ub85c \uac19\uc740 \ud604\uc9c0 \uc2dc\uac01\uc774 \ub450 \ubc88 \ub098\ud0c0\ub0a0 \uc218 \uc788\ub2e4. \uc0ac\ub78c\uc5d0\uac8c\ub3c4 \ud5f7\uac08\ub9ac\ub294 \uc77c\uc740 \ucef4\ud4e8\ud130\uc5d0\uac8c\ub3c4 \ub530\ub85c \uad6c\ubd84\ud560 \ubc29\ubc95\uc774 \ud544\uc694\ud558\ub2e4. \uc22b\uc790\ub85c \uc800\uc7a5\ud558\ub2c8 \uc2dc\uac04\uc740 \uc5b8\uc81c\ub098 \ub2e8\uc21c\ud560 \uac83 \uac19\uc9c0\ub9cc, \uc5b4\ub290 \uc9c0\uc5ed\uc5d0\uc11c \uc5b4\ub5a4 \uaddc\uce59\uc73c\ub85c \ud45c\uc2dc\ud588\ub294\uc9c0\uac00 \uc911\uc694\ud558\ub2e4. \uc2dc\uacc4\uc758 \uc774\uc57c\uae30\ub294 \uc815\ud655\ud55c \uae30\uacc4\uc640 \uc0ac\ub78c\uc774 \uc815\ud55c \uc57d\uc18d\uc774 \ub9cc\ub098\ub294 \uc790\ub9ac\ub2e4. \uc11c\uc6b8\uacfc \ub85c\uc2a4\uc564\uc824\ub808\uc2a4\uc5d0 \uc788\ub294 \uc0ac\ub78c\uc774 \ub3d9\uc2dc\uc5d0 \ud1b5\ud654\ud574\ub3c4 \ud654\uba74\uc758 \uc2dc\uac01\uc740 \ub2e4\ub97c \uc218 \uc788\ub2e4. \ud55c \uc21c\uac04\uc5d0 \uc11c\ub85c \ub2e4\ub978 \uc9c0\uc5ed\uc758 \uc2dc\uacc4\uac00 \ub2e4\ub978 \uc22b\uc790\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uac83\uc774\ub2e4. \uc774\uac83\uc740 \ub458 \uc911 \ud55c\ucabd\uc774 \ud2c0\ub838\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \uadf8\ub798\uc11c \uc624\ud6c4 \uc138 \uc2dc\uc5d0 \ub9cc\ub098\uc790\ub77c\ub294 \ub9d0\uc5d0\ub294 \uc5b4\ub290 \uacf3\uc758 \uc624\ud6c4 \uc138 \uc2dc\uc778\uc9c0\uac00 \ud544\uc694\ud558\ub2e4. \ucef4\ud4e8\ud130\uc758 \uc77c\uc815\uc774\ub098 \uae30\ub85d\uc5d0\uc11c\ub3c4 \ube44\uc2b7\ud55c \ubb38\uc81c\uac00 \uc0dd\uae34\ub2e4. \ub0a0\uc9dc\uc640 \uc2dc\uac01\uc758 \uc22b\uc790\ub9cc \uc788\uc73c\uba74 \ucda9\ubd84\ud574 \ubcf4\uc774\uc9c0\ub9cc, \uadf8 \uc22b\uc790\uac00 \uac00\ub9ac\ud0a4\ub294 \ub9e5\ub77d\uc774 \ube60\uc838 \uc788\uc744 \uc218 \uc788\ub2e4. UTC\ub294 \ud611\uc815\uc138\uacc4\uc2dc\ub2e4. \uc5ec\ub7ec \uc9c0\uc5ed\uc758 \uc2dc\uac01\uc744 \ube44\uad50\ud560 \ub54c \uae30\uc900\uc73c\ub85c \uc4f8 \uc218 \uc788\ub2e4. \ud604\uc9c0 \uc2dc\uac01\uc774 UTC\ubcf4\ub2e4 \uc5bc\ub9c8\ub098 \uc55e\uc11c\uac70\ub098 \ub4a4\uc11c\ub294\uc9c0\ub97c \ud568\uaed8 \uc54c\uba74 \uac19\uc740 \uc21c\uac04\uc744 \uc5f0\uacb0\ud560 \uc218 \uc788\ub2e4. \uc774 \ucc28\uc774\ub97c \uc624\ud504\uc14b\uc774\ub77c\uace0 \ubd80\ub978\ub2e4. \uc5ec\uae30\uc11c \ubaa8\ub4e0 \uc9c0\uc5ed\uc774 \uae30\uc900\uc5d0\uc11c \uba87 \uc2dc\uac04 \ucc28\uc774\uc778\uc9c0\ub9cc \uc601\uc6d0\ud788 \uace0\uc815\ud574 \ub450\uba74 \ub05d\ub098\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uac19\uc740 \uc9c0\uc5ed\uc5d0\uc11c\ub3c4 \ub0a0\uc9dc\uc5d0 \ub530\ub77c \ucc28\uc774\uac00 \ubc14\ub014 \uc218 \uc788\ub2e4. \uc2dc\uac04\uc744 \ub2e4\ub8e8\ub294 \ud504\ub85c\uadf8\ub7a8\uc740 \uc22b\uc790 \ud558\ub098\ubfd0 \uc544\ub2c8\ub77c \uadf8 \ubcc0\ud654\uc758 \uaddc\uce59\ub3c4 \uace0\ub824\ud574\uc57c \ud55c\ub2e4. \ud30c\uc774\uc36c \uacf5\uc2dd \ubb38\uc11c\ub294 2020\ub144 \ub85c\uc2a4\uc564\uc824\ub808\uc2a4\uc758 \uc608\ub97c \ubcf4\uc5ec \uc900\ub2e4. 10\uc6d4 31\uc77c\uc5d0\ub294 UTC\ubcf4\ub2e4 7\uc2dc\uac04 \ub2a6\ub294 \uc2dc\uac01\uc744 \uc4f0\ub2e4\uac00, 11\uc6d4 1\uc77c\uc5d0\ub294 \uc11c\uba38\ud0c0\uc784\uc774 \ub05d\ub098\uba70 8\uc2dc\uac04 \ub2a6\ub294 \uc2dc\uac01\uc73c\ub85c \ubc14\ub010\ub2e4. \uc774\ub294 \uacfc\uac70\uc758 \uad6c\uccb4\uc801\uc778 \uc0ac\ub840\uc774\uc9c0 \uc62c\ud574\uc758 \uc77c\uc815 \uc548\ub0b4\uac00 \uc544\ub2c8\ub2e4. \ubc14\ub85c \uadf8 \uc804\ud658 \ub54c\ubb38\uc5d0 \ud558\ub8e8 \uc911 \uc77c\ubd80 \uc2dc\uac01\uc774 \ub2e4\uc2dc \ub098\ud0c0\ub09c\ub2e4. \ub2e8\uc21c\ud788 \ub0a0\uc9dc\uc5d0 24\uc2dc\uac04\uc744 \ub354\ud558\ub294 \uc77c\uacfc \ud604\uc9c0 \ub2ec\ub825\uc5d0\uc11c \ub2e4\uc74c \ub0a0 \uac19\uc740 \uc2dc\uac01\uc744 \ucc3e\ub294 \uc77c\uc774 \ud56d\uc0c1 \uac19\uc740 \uacb0\uacfc\uac00 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc775\uc219\ud55c \ud558\ub8e8\ub77c\ub294 \ub9d0\uc5d0\ub3c4 \uc5b4\ub5a4 \uae30\uc900\uc73c\ub85c \uacc4\uc0b0\ud588\ub294\uc9c0\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \uc774 \uc0ac\ub840\uc5d0\uc11c 2020\ub144 11\uc6d4 1\uc77c \uc624\uc804 1\uc2dc\ub294 \uc804\ud658 \uc804\uacfc \ud6c4\uc5d0 \uac01\uac01 \uc874\uc7ac\ud55c\ub2e4. \ud558\ub098\ub294 UTC\ubcf4\ub2e4 7\uc2dc\uac04 \ub2a6\uace0 \ub2e4\ub978 \ud558\ub098\ub294 8\uc2dc\uac04 \ub2a6\ub2e4. \uc2dc\uacc4\uc758 \uc22b\uc790\ub294 \uac19\uc9c0\ub9cc \uac00\ub9ac\ud0a4\ub294 \uc21c\uac04\uc740 \ud55c \uc2dc\uac04 \ub2e4\ub974\ub2e4. \uacf5\uc2dd \ubb38\uc11c\ub294 \uac19\uc740 \ud604\uc9c0 \uc2dc\uac01\uc758 \uc55e\uc120 \uacbd\uc6b0\uc640 \ub098\uc911 \uacbd\uc6b0\ub97c \uad6c\ubd84\ud558\ub294 \ubc29\ubc95\uc744 \uc124\uba85\ud55c\ub2e4. \ub3c5\uc790\uac00 \ud504\ub85c\uadf8\ub7a8\uc758 \uc635\uc158\uc744 \uc678\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uac19\uc740 \ud45c\uae30\ub9cc\uc73c\ub85c\ub294 \ud55c \uc21c\uac04\uc744 \ud655\uc815\ud558\uc9c0 \ubabb\ud558\ub294 \ub54c\uac00 \uc788\uc5b4\uc11c \ucd94\uac00 \uc815\ubcf4\uac00 \ud544\uc694\ud558\ub2e4\ub294 \uc810\uc744 \uc54c\uba74 \ub41c\ub2e4. \uc2dc\uac04\ub300 \ub370\uc774\ud130\ub294 \uc5b4\ub290 \uc9c0\uc5ed\uc774 \uc5b8\uc81c \uc5b4\ub5a4 \uc2dc\uac01 \uaddc\uce59\uc744 \uc37c\ub294\uc9c0 \ub2e4\ub8ec\ub2e4. \ud30c\uc774\uc36c\uc758 zoneinfo\ub294 IANA \uc2dc\uac04\ub300 \ub370\uc774\ud130\ubca0\uc774\uc2a4\ub97c \uc774\uc6a9\ud55c\ub2e4. \ub85c\uc2a4\uc564\uc824\ub808\uc2a4\ub77c\ub294 \uc9c0\uc5ed\uc744 \uc120\ud0dd\ud558\ub294 \uac83\uacfc \ubb34\uc870\uac74 UTC\ubcf4\ub2e4 8\uc2dc\uac04 \ub2a6\ub2e4\uace0 \uc815\ud558\ub294 \uac83\uc740 \uac19\uc740 \ub73b\uc774 \uc544\ub2c8\ub2e4. \uc55e\uc758 \uc0ac\ub840\uc5d0\uc11c \ubcf4\uc558\ub4ef \uac19\uc740 \uc9c0\uc5ed\uc758 \ucc28\uc774\uac00 \uc2dc\uae30\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c8 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \ud504\ub85c\uadf8\ub7a8\uc774 \uc9c0\uc5ed\uc758 \uc774\ub984\uc744 \ub2e4\ub8ec\ub2e4\ub294 \uac83\uc740 \uc9c0\uba85 \ud558\ub098\ub97c \uc7a5\uc2dd\uc73c\ub85c \ubd99\uc774\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ub0a0\uc9dc\uc640 \uc5f0\uacb0\ub41c \uaddc\uce59\uc744 \ucc3e\ub294 \uc77c\uc5d0 \uac00\uae5d\ub2e4. \ud45c\uc2dc\ud560 \uc774\ub984\uacfc \uacc4\uc0b0\ud560 \uc870\uac74\uc774 \ud568\uaed8 \uc788\ub2e4. \uc774\ubbf8 \uc77c\uc5b4\ub09c \uc0ac\uac74\uc758 \uc21c\uc11c\ub97c \ub0a8\uae30\ub294 \uc77c\uacfc \ub9e4\uc8fc \ud604\uc9c0\uc758 \uac19\uc740 \uc2dc\uac01\uc5d0 \ub9cc\ub098\ub294 \uc57d\uc18d\uc744 \uc815\ud558\ub294 \uc77c\uc740 \ubaa9\uc801\uc774 \ub2e4\ub974\ub2e4. \uc804\uc790\ub294 \uc5b4\ub5a4 \uc21c\uac04\uc774\uc5c8\ub294\uc9c0\uac00 \uc911\uc694\ud558\uace0 \ud6c4\uc790\ub294 \uc9c0\uc5ed\uc758 \uc0dd\ud65c \uc2dc\uac01\uc744 \uc720\uc9c0\ud558\ub294 \uac83\uc774 \uc911\uc694\ud560 \uc218 \uc788\ub2e4. \ub530\ub77c\uc11c \ubaa8\ub4e0 \uc2dc\uac04\uc744 \ud55c \ubc29\uc2dd\uc73c\ub85c\ub9cc \uc800\uc7a5\ud558\uba74 \ubaa8\ub4e0 \ubb38\uc81c\uac00 \ud574\uacb0\ub41c\ub2e4\ub294 \uacb0\ub860\uc740 \ud544\uc694\ud558\uc9c0 \uc54a\ub2e4. \ud504\ub85c\uadf8\ub7a8\uc740 \ubb34\uc5c7\uc744 \uae30\ub85d\ud558\uace0 \uc5b4\ub5a4 \uc57d\uc18d\uc744 \uc720\uc9c0\ud560\uc9c0\uc5d0 \ub9de\ucd94\uc5b4 \ud544\uc694\ud55c \uc815\ubcf4\ub97c \uac16\ucd94\uc5b4\uc57c \ud55c\ub2e4. \uc774 \uad6c\ubd84\uc740 \ucf54\ub4dc\ubcf4\ub2e4 \uc11c\ube44\uc2a4\uac00 \ubb34\uc5c7\uc744 \ub73b\ud558\ub824\ub294\uc9c0\uc758 \ubb38\uc81c\uc5d0\uc11c \uc2dc\uc791\ud55c\ub2e4. \uc5b4\ub5a4 \uae30\ub85d\uc5d0\uc11c \uc624\uc804 1\uc2dc\ub77c\ub294 \ubd80\ubd84\ub9cc \ub530\ub85c \uc62e\uae30\uba74 \uc6d0\ub798 \ubd99\uc5b4 \uc788\ub358 \ub0a0\uc9dc\uc640 \uc9c0\uc5ed \uc815\ubcf4\uac00 \uc0ac\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ub3c5\uc790\ub294 \ub2e4\ub978 \uc21c\uac04\uc744 \uac19\uc740 \uac83\uc73c\ub85c \uc77d\uac70\ub098, \uac19\uc740 \uc0ac\uac74\uc744 \uc11c\ub85c \ub2e4\ub978 \uac83\uc73c\ub85c \ubcfc \uc218 \uc788\ub2e4. \uc2dc\uac04 \ud45c\uc2dc\ub3c4 \ucd9c\ucc98\uc758 \uc77c\ubd80\ub77c\ub294 \uc810\uc744 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uc774 \uc6d0\uace0\uc758 \ub450 \uc624\uc804 1\uc2dc\ub294 \uacf5\uc2dd \ubb38\uc11c\uc758 \uacfc\uac70 \uc608\ub97c \ubcc4\ub3c4\ub85c \uc7ac\ud604\ud574 \ud655\uc778\ud588\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \uc608\ub97c \ubaa8\ub4e0 \ub098\ub77c\uc758 \ud604\uc7ac \uaddc\uce59\uc73c\ub85c \ud655\ub300\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc9c0\uc5ed\uacfc \ub0a0\uc9dc\ub97c \ud568\uaed8 \ubcf4\ub294 \uac04\ub2e8\ud55c \uc2b5\uad00\uc774 \uc2dc\uac04\uc744 \uc774\ud574\ud558\ub294 \ub370 \uc911\uc694\ud55c \uc774\uc720\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uc5ec\ud589 \uc77c\uc815\uc744 \uc0dd\uac01\ud558\ub294 \uc0ac\ub78c\uc758 \ubd84\uc704\uae30\ub97c \ud45c\ud604\ud588\ub2e4. \ud2b9\uc815 \ud56d\uacf5\uad8c\uc774\ub098 \uc2e4\uc81c \uc2dc\uac01 \ucc28\uc774\ub97c \ube44\uad50\ud55c \ub3c4\ud45c\ub294 \uc544\ub2c8\ub2e4. \uadf8\ub9bc \uc18d\uc758 \ubb3c\uac74\uc774 \uc774 \uae00\uc758 \uacc4\uc0b0 \uacb0\uacfc\ub97c \uc99d\uba85\ud558\ub294 \uc790\ub8cc\ub3c4 \uc544\ub2c8\ub2e4. \ucef4\ud4e8\ud130\ub294 \uc2dc\uac01\uc744 \uc815\ud655\ud558\uac8c \uacc4\uc0b0\ud560 \uc218 \uc788\uc9c0\ub9cc \ubb34\uc5c7\uc744 \uac19\uc740 \uc2dc\uac04\uc774\ub77c\uace0 \ubd80\ub97c\uc9c0\uc5d0 \uad00\ud55c \uc57d\uc18d\uae4c\uc9c0 \uc800\uc808\ub85c \uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc21c\uac04\uacfc \ud604\uc9c0 \ud45c\uc2dc, \ub0a0\uc9dc\uc640 \uc9c0\uc5ed\uc758 \uaddc\uce59\uc744 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ub450 \ubc88 \uc624\ub294 \uc624\uc804 1\uc2dc\ub294 \ub0af\uc120 \uc624\ub958\ubcf4\ub2e4, \uc77c\uc0c1\uc758 \uc2dc\uacc4 \ub4a4\uc5d0 \uc788\ub294 \uc5ec\ub7ec \uc57d\uc18d\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc7ac\ubbf8\uc788\ub294 \uc0ac\ub840\ub2e4."}, {"id": "cookies-browser-memory", "title": "\ucfe0\ud0a4 \u2014 \uc6f9\uc0ac\uc774\ud2b8\ub294 \ub0b4\uac00 \uc654\ub358 \uac83\uc744 \uc5b4\ub5bb\uac8c \uae30\uc5b5\ud560\uae4c", "summary": "\ub85c\uadf8\uc778\uacfc \uc5b8\uc5b4 \uc124\uc815\uc744 \uc774\uc5b4 \uc8fc\ub294 \ucfe0\ud0a4\uc758 \uc5ed\ud560\uacfc \uc800\uc7a5\u00b7\ucd94\uc801\uc758 \ucc28\uc774\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "computing", "category_title": "Computing", "subcategory": "Internet", "url": "stories/cookies-browser-memory/index.html", "image": "media/cookies-browser-memory.png", "alt": "\ub178\ud2b8\uc640 \ub178\ud2b8\ubd81\uc774 \uc788\ub294 \uc775\uc219\ud55c \ucc45\uc0c1\uc73c\ub85c \ub3cc\uc544\uc624\ub294 \uc0ac\ub78c\uc758 AI \ubd84\uc704\uae30 \uc7a5\uba74.", "text": "\ucfe0\ud0a4 \u2014 \uc6f9\uc0ac\uc774\ud2b8\ub294 \ub0b4\uac00 \uc654\ub358 \uac83\uc744 \uc5b4\ub5bb\uac8c \uae30\uc5b5\ud560\uae4c \uc791\uc740 \uba54\ubaa8\uac00 \ud3b8\ub9ac\ud568\uacfc \ucd94\uc801\uc758 \uc774\uc57c\uae30\ub97c \ud568\uaed8 \ub9cc\ub4dc\ub294 \uc774\uc720 \ub85c\uadf8\uc778\uacfc \uc5b8\uc5b4 \uc124\uc815\uc744 \uc774\uc5b4 \uc8fc\ub294 \ucfe0\ud0a4\uc758 \uc5ed\ud560\uacfc \uc800\uc7a5\u00b7\ucd94\uc801\uc758 \ucc28\uc774\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Internet \ucef4\ud4e8\ud305 \uc5b4\uc81c \ud55c\uad6d\uc5b4\ub85c \ubc14\uafb8\uc5b4 \ub454 \uc0ac\uc774\ud2b8\ub97c \uc624\ub298 \ub2e4\uc2dc \uc5f4\uc5c8\ub354\ub2c8 \uc5ec\uc804\ud788 \ud55c\uad6d\uc5b4\ub2e4. \uc7a5\ubc14\uad6c\ub2c8\uc5d0 \ub123\uc5b4 \ub454 \ubb3c\uac74\uc774 \ub2e4\uc74c \ud398\uc774\uc9c0\uc5d0\uc11c\ub3c4 \ub0a8\uc544 \uc788\uae30\ub3c4 \ud55c\ub2e4. \ud654\uba74\uc744 \uc0c8\ub85c \ubc1b\ub294\ub370\ub3c4 \uc0ac\uc774\ud2b8\ub294 \uc5b4\ub5bb\uac8c \uc6b0\ub9ac\uac00 \ud558\ub358 \uc77c\uc744 \uc774\uc5b4 \uc8fc\ub294 \uac78\uae4c. \uc774\ub7f4 \ub54c \uc4f0\uc774\ub294 \ubc29\ubc95 \uac00\uc6b4\ub370 \ud558\ub098\uac00 \ucfe0\ud0a4\ub2e4. \uba39\ub294 \uacfc\uc790\ub294 \uc544\ub2c8\uace0 \ube0c\ub77c\uc6b0\uc800\uc5d0 \uc800\uc7a5\ud558\ub294 \uc791\uc740 \ub370\uc774\ud130\ub2e4. \uc0ac\uc774\ud2b8\uc640 \ube0c\ub77c\uc6b0\uc800\uac00 \uc774 \uc815\ubcf4\ub97c \uc8fc\uace0\ubc1b\uc73c\uba70 \uc55e\uc120 \ubc29\ubb38\uc774\ub098 \uc0c1\ud0dc\ub97c \uc774\uc5b4 \uac08 \uc218 \uc788\ub2e4. \uc791\uc740 \uae30\uc5b5\uc774 \uc5b4\ub5a4 \ud3b8\ub9ac\ud568\uc744 \ub9cc\ub4e4\uace0 \ubb34\uc5c7\uae4c\uc9c0 \ub73b\ud558\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uc6f9\uc5d0\uc11c \uc4f0\ub294 HTTP\ub294 \uae30\ubcf8\uc801\uc73c\ub85c \uc774\uc804 \uc694\uccad\uc758 \uc0c1\ud0dc\ub97c \uc2a4\uc2a4\ub85c \uae30\uc5b5\ud558\uc9c0 \uc54a\ub294\ub2e4. \uccab \ud398\uc774\uc9c0\ub97c \ubc1b\uc558\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ub2e4\uc74c \ud398\uc774\uc9c0 \uc694\uccad\uc774 \uc790\ub3d9\uc73c\ub85c \uac19\uc740 \ub85c\uadf8\uc778 \uc0c1\ud0dc\uac00 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc11c\ube44\uc2a4\uac00 \uc774\ub97c \uc774\uc5b4 \uc8fc\ub294 \ubc29\ubc95\uc744 \ub530\ub85c \ub9c8\ub828\ud574\uc57c \ud55c\ub2e4. \uac00\uac8c\uc5d0\uc11c \uc8fc\ubb38\uc11c\ub97c \uc5ec\ub7ec \uc7a5 \ub530\ub85c \ubc1b\ub294 \uc0c1\ud669\uc744 \uc0dd\uac01\ud558\uba74 \uc774\ud574\ud558\uae30 \uc27d\ub2e4. \uac19\uc740 \uc190\ub2d8\uc758 \uc8fc\ubb38\uc778\uc9c0 \uc54c\uc544\ubcfc \ud45c\uc2dc\uac00 \uc788\uc73c\uba74 \uc55e\uc758 \uc8fc\ubb38\uacfc \uc5f0\uacb0\ud560 \uc218 \uc788\ub2e4. \ucfe0\ud0a4\ub294 \uc774\ub7f0 \uc5f0\uacb0\uc744 \ub3d5\ub294 \ub3c4\uad6c\ub2e4. \uc2e4\uc81c\ub85c \uc0ac\ub78c\uc758 \uc5bc\uad74\uc744 \uae30\uc5b5\ud558\ub294 \uc810\uc6d0\uacfc \ub611\uac19\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc11c\ubc84\ub294 \uc751\ub2f5\uacfc \ud568\uaed8 \ube0c\ub77c\uc6b0\uc800\uac00 \ubcf4\uad00\ud560 \ucfe0\ud0a4\ub97c \ubcf4\ub0bc \uc218 \uc788\ub2e4. \ube0c\ub77c\uc6b0\uc800\ub294 \ud574\ub2f9 \uc870\uac74\uc5d0 \ub9de\ub294 \ub2e4\uc74c \uc694\uccad\uc744 \ud560 \ub54c \uadf8 \uac12\uc744 \ud568\uaed8 \uc804\ud55c\ub2e4. \uc11c\ubc84\ub294 \uc774\ub97c \ubcf4\uace0 \uc5b4\ub290 \uc0c1\ud0dc\uc640 \uc5f0\uacb0\ud560\uc9c0 \ud310\ub2e8\ud560 \uc218 \uc788\ub2e4. \uc5ec\uae30\uc5d0\ub294 \ucfe0\ud0a4\uc758 \uc801\uc6a9 \ubc94\uc704\uc640 \uc720\uc9c0 \uae30\uac04 \uac19\uc740 \uc870\uac74\uc774 \uc788\ub2e4. \uc544\ubb34 \uc0ac\uc774\ud2b8\uc5d0\uc11c\ub098 \ub2e4\ub978 \ubaa8\ub4e0 \uc0ac\uc774\ud2b8\uc758 \ucfe0\ud0a4\ub97c \uadf8\ub300\ub85c \ubc1b\ub294 \uad6c\uc870\ub85c \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ud06c\uace0 \ubcf5\uc7a1\ud55c \uae30\uc5b5 \ud558\ub098\ubcf4\ub2e4 \uc815\ud574\uc9c4 \uc870\uac74\uc5d0\uc11c \uc8fc\uace0\ubc1b\ub294 \uc791\uc740 \uc815\ubcf4\ub4e4\uc774 \uc788\ub2e4\ub294 \ud3b8\uc774 \uc6d0\ub9ac\uc5d0 \uac00\uae5d\ub2e4. \ub85c\uadf8\uc778 \uc0c1\ud0dc\ub97c \uc774\uc5b4 \uc904 \ub54c \ucfe0\ud0a4\uc5d0 \uc138\uc158 \uc2dd\ubcc4\uc790\ub97c \ub2f4\ub294 \ubc29\uc2dd\uc774 \uc4f0\uc778\ub2e4. \uc11c\ubc84\uac00 \uc774 \uac12\uc744 \ud655\uc778\ud574 \uc774\ubbf8 \ub85c\uadf8\uc778\ud55c \uc0c1\ud0dc\uc778\uc9c0 \ud310\ub2e8\ud558\ub294 \uac83\uc774\ub2e4. \uc2dd\ubcc4\uc790\ub294 \uc5b4\ub5a4 \uae30\ub85d\uacfc \uc5f0\uacb0\ud560\uc9c0 \uc54c\ub824 \uc8fc\ub294 \ud45c\uc9c0\ub85c \uc774\ud574\ud558\uba74 \ub41c\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubaa8\ub4e0 \ucfe0\ud0a4\uc758 \ub0b4\uc6a9\uc774 \uac19\uc740 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b8\uc5b4 \uc124\uc815\ucc98\ub7fc \uc9c1\uc811\uc801\uc778 \uac12\uc774 \ub4e4\uc5b4\uac08 \uc218\ub3c4 \uc788\uace0 \uc11c\ubc84 \ucabd \uae30\ub85d\uc744 \uac00\ub9ac\ud0a4\ub294 \uac12\uc774 \ub4e4\uc5b4\uac08 \uc218\ub3c4 \uc788\ub2e4. \ucfe0\ud0a4\uac00 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ub0b4 \uc774\ub984\uacfc \ube44\ubc00\ubc88\ud638\uac00 \uadf8\ub300\ub85c \ub4e4\uc5b4 \uc788\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub3c4, \uc544\ubb34 \uc911\uc694\ud55c \uc815\ubcf4\uac00 \uc5c6\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \uc77c\ubd80 \ucfe0\ud0a4\ub294 \uc815\ud574\uc9c4 \ub9cc\ub8cc \uc2dc\uc810\uc774\ub098 \uc720\uc9c0 \uc2dc\uac04\uae4c\uc9c0 \ub0a8\ub3c4\ub85d \ub9cc\ub4e4\uc5b4\uc9c4\ub2e4. \ub2e4\ub978 \ucfe0\ud0a4\ub294 \uc138\uc158 \ub3d9\uc548 \uc0ac\uc6a9\ud558\ub294 \uac83\uc744 \ubaa9\uc801\uc73c\ub85c \ud55c\ub2e4. \ube0c\ub77c\uc6b0\uc800\uc758 \uc138\uc158 \ubcf5\uc6d0 \uae30\ub2a5\uacfc \uc124\uc815\uc5d0 \ub530\ub77c\uc11c\ub3c4 \uc0ac\uc6a9\uc790\uac00 \uacbd\ud5d8\ud558\ub294 \uacb0\uacfc\uac00 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ub530\ub77c\uc11c \ucc3d\uc744 \ub2eb\uc558\uc73c\ub2c8 \ubaa8\ub4e0 \uae30\ub85d\uc774 \uc989\uc2dc \uc0ac\ub77c\uc84c\ub2e4\uace0 \ub2e8\uc21c\ud558\uac8c \uacb0\ub860 \ub0b4\ub9ac\uae30 \uc5b4\ub835\ub2e4. \ubc18\ub300\ub85c \uc624\ub798 \ub0a8\ub294 \ucfe0\ud0a4\ub77c\uace0 \uc601\uc6d0\ud788 \uc720\uc9c0\ub418\ub294 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \uc800\uc7a5\ub41c \uae30\uc5b5\uc5d0\ub3c4 \uc218\uba85\uc774 \uc788\uace0 \uadf8\uac83\uc744 \uc815\ud558\ub294 \uc5ec\ub7ec \uc870\uac74\uc774 \uc788\ub2e4\ub294 \uc815\ub3c4\ub85c \uc774\ud574\ud558\uba74 \ub41c\ub2e4. \ucfe0\ud0a4\ub294 \ub85c\uadf8\uc778\uc774\ub098 \uac1c\uc778\ud654\uc5d0 \uc4f0\uc77c \uc218 \uc788\uc9c0\ub9cc \uc774\uc6a9 \ud589\ud0dc\ub97c \uae30\ub85d\ud558\uace0 \ubd84\uc11d\ud558\ub294 \ub370\ub3c4 \uc4f0\uc778\ub2e4. \uac19\uc740 \uae30\uc220\uc774 \ub2e4\ub978 \ubaa9\uc801\uc744 \uac16\ub294 \uac83\uc774\ub2e4. \uc5b8\uc5b4 \uc124\uc815\uc744 \uae30\uc5b5\ud558\ub294 \uc77c\uacfc \uc5ec\ub7ec \ubc29\ubb38\uc744 \uc5f0\uacb0\ud574 \ud589\ub3d9\uc744 \uc0b4\ud3b4\ubcf4\ub294 \uc77c\uc740 \ub3c5\uc790\uac00 \ub290\ub07c\uae30\uc5d0\ub3c4 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uc5b4\ub5a4 \uacf3\uc5d0\uc11c\ub294 \ub2e4\ub978 \uc11c\ube44\uc2a4\uac00 \uc81c\uacf5\ud558\ub294 \uc694\uc18c\uc640 \ud568\uaed8 \uad50\ucc28 \uc0ac\uc774\ud2b8 \ucfe0\ud0a4\uac00 \uad00\uc5ec\ud558\uae30\ub3c4 \ud55c\ub2e4. \ub2e4\ub9cc \uc624\ub298\ub0a0 \ube0c\ub77c\uc6b0\uc800\uac00 \uc774\ub97c \ud5c8\uc6a9\ud558\uac70\ub098 \uc81c\ud55c\ud558\ub294 \ubc29\uc2dd\uc740 \uc11c\ub85c \ub2e4\ub974\uace0 \uacc4\uc18d \ub2ec\ub77c\uc9c4\ub2e4. \ubaa8\ub4e0 \ucd94\uc801\uc774 \ucfe0\ud0a4 \ud558\ub098\ub85c \uc774\ub8e8\uc5b4\uc9c4\ub2e4\uace0 \uc0dd\uac01\ud558\uba74 \uc2e4\uc81c\uc758 \uc5ec\ub7ec \uae30\uc220\uc744 \ub193\uce58\uac8c \ub41c\ub2e4. \ucfe0\ud0a4\ub97c \uc0ad\uc81c\ud558\uba74 \uc0ac\uc774\ud2b8\uac00 \uc55e\uc120 \ub85c\uadf8\uc778 \uc0c1\ud0dc\ub098 \uc124\uc815\uacfc \uc5f0\uacb0\ud558\uc9c0 \ubabb\ud574 \ub2e4\uc2dc \ub85c\uadf8\uc778\uc744 \uc694\uad6c\ud560 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc774\uac83\uc774 \uc11c\ubc84\uc5d0 \uc788\ub294 \uacc4\uc815\uacfc \uc8fc\ubb38 \ub0b4\uc5ed\uae4c\uc9c0 \uc790\ub3d9\uc73c\ub85c \uc9c0\uc6b4\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uae30\uae30 \ucabd \ud45c\uc9c0\ub97c \uc9c0\uc6b0\ub294 \uc77c\uacfc \ud68c\uc0ac\uac00 \ubcf4\uad00\ud55c \uae30\ub85d\uc744 \uc9c0\uc6b0\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \uc774 \ucc28\uc774\ub294 \uc0ac\uc9c4\uad00\uc758 \ubcf4\uad00 \ubc88\ud638\ud45c\ub97c \ub5a0\uc62c\ub9ac\uba74 \uc27d\ub2e4. \ubc88\ud638\ud45c\ub97c \ubc84\ub838\ub2e4\uace0 \uc0ac\uc9c4\uad00\uc758 \uc6d0\ubcf8\uc774 \ud568\uaed8 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ube44\uc720\uac00 \uc2e4\uc81c \uacc4\uc815 \uad00\ub9ac \uc808\ucc28\ub97c \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\uc9c0\ub9cc, \uc5b4\ub290 \ucabd\uc758 \uc815\ubcf4\ub97c \uc9c0\uc6e0\ub294\uc9c0 \ub098\ub204\uc5b4 \uc0dd\uac01\ud558\uac8c \ud574 \uc900\ub2e4. \ube0c\ub77c\uc6b0\uc800\uc5d0\ub294 \ucfe0\ud0a4 \uc678\uc5d0\ub3c4 \ub370\uc774\ud130\ub97c \uc800\uc7a5\ud558\ub294 \ubc29\ubc95\uc774 \uc788\ub2e4. MDN\uc740 \ud070 \uc591\uc758 \uc6f9 \ub370\uc774\ud130\ub97c \uc800\uc7a5\ud558\ub294 \ub370 \ubcc4\ub3c4\uc758 \uc800\uc7a5 \uae30\uc220\uc744 \uc0ac\uc6a9\ud558\ub294 \uacbd\uc6b0\ub97c \uc124\uba85\ud55c\ub2e4. \uc0ac\uc774\ud2b8\uac00 \uc5b4\ub5a4 \uac12\uc744 \uae30\uc5b5\ud55c\ub2e4\uace0 \ud574\uc11c \ubc18\ub4dc\uc2dc \ucfe0\ud0a4\ub97c \uc37c\ub2e4\ub294 \uc99d\uac70\ub294 \uc544\ub2c8\ub2e4. \uadf8\ub798\uc11c \ucfe0\ud0a4\ub97c \ubaa8\ub450 \uc9c0\uc6e0\ub294\ub370 \uc5b4\ub5a4 \uc124\uc815\uc774 \ub0a8\uc544 \uc788\uac70\ub098, \ub2e4\ub978 \uae30\uae30\uc5d0\uc11c\ub294 \uae30\ub85d\uc774 \uc774\uc5b4\uc9c0\uc9c0 \uc54a\ub294 \ud604\uc0c1\ub3c4 \uc788\uc744 \uc218 \uc788\ub2e4. \uacc4\uc815\uc758 \uc11c\ubc84 \uae30\ub85d\uc778\uc9c0 \ube0c\ub77c\uc6b0\uc800\uc758 \uc800\uc7a5 \uc815\ubcf4\uc778\uc9c0\uc5d0 \ub530\ub77c \uc870\uac74\uc774 \ub2e4\ub974\ub2e4. \ud558\ub098\uc758 \ub2e8\uc5b4\ub85c \uc6f9\uc758 \uae30\uc5b5 \uc804\uccb4\ub97c \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uc775\uc219\ud55c \ucc45\uc0c1\uacfc \ub178\ud2b8\ub85c \ub3cc\uc544\uc624\ub294 \ubd84\uc704\uae30\ub97c \ud45c\ud604\ud588\ub2e4. \uc2e4\uc81c \ucfe0\ud0a4 \ud30c\uc77c\uc774\ub098 \ube0c\ub77c\uc6b0\uc800 \ud654\uba74\uc758 \uae30\uc220 \ub3c4\ud310\uc740 \uc544\ub2c8\ub2e4. \ub2e4\uc2dc \ucc3e\uc544\uc654\uc744 \ub54c \uc55e\uc120 \uc120\ud0dd\uc744 \uc774\uc5b4 \uc8fc\ub294 \uacbd\ud5d8\uc744 \ub5a0\uc62c\ub9ac\ub294 \uadf8\ub9bc\uc774\ub2e4. \ucfe0\ud0a4\uc758 \uc6d0\ub9ac\ub97c \uc54c\uba74 \uc0ac\uc774\ud2b8\uac00 \ub098\ub97c \uae30\uc5b5\ud55c\ub2e4\ub294 \ub9d0\uc744 \uc870\uae08 \ub098\ub204\uc5b4 \ubcfc \uc218 \uc788\ub2e4. \ubb34\uc5c7\uc744, \uc5bc\ub9c8 \ub3d9\uc548, \uc5b4\ub5a4 \ubc94\uc704\uc5d0\uc11c \uae30\uc5b5\ud560\uae4c. \uc774 \uc9c8\ubb38\uc740 \uc791\uc740 \ub370\uc774\ud130\uac00 \ub9cc\ub4dc\ub294 \ud3b8\ub9ac\ud568\uc744 \uc774\ud574\ud558\uba74\uc11c \ub3d9\uc2dc\uc5d0 \uadf8 \uc0ac\uc6a9 \ubaa9\uc801\ub3c4 \uc0b4\ud53c\uac8c \ud55c\ub2e4. \uc6f9\uc758 \uae30\uc5b5\uc740 \ub9c9\uc5f0\ud55c \ub9c8\ubc95\ubcf4\ub2e4 \uad6c\uccb4\uc801\uc778 \uc57d\uc18d\uc5d0 \uac00\uae5d\ub2e4."}, {"id": "css-same-words-different-page", "title": "CSS \u2014 \uac19\uc740 \uae00\uc774 \ub2e4\ub978 \uc5bc\uad74\ub85c \ubcf4\uc774\ub294 \uc774\uc720", "summary": "\uc6f9 \ubb38\uc11c\uc758 \ub0b4\uc6a9\uacfc \ud45c\ud604 \uaddc\uce59\uc744 \uad6c\ubd84\ud558\uba70 \uae00\uc790\u00b7\uc5ec\ubc31\u00b7\ubc30\uce58\uac00 \ub3c5\uc11c \uacbd\ud5d8\uc744 \ubc14\uafb8\ub294 \uc6d0\ub9ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "computing", "category_title": "Computing", "subcategory": "Software", "url": "stories/css-same-words-different-page/index.html", "image": "media/css-same-words-different-page.png", "alt": "\uac19\uc740 \uc6d0\uace0\ub97c \uc11c\ub85c \ub2e4\ub978 \uc5ec\ubc31\uacfc \ubc30\uce58\ub85c \ub193\uc740 \uc9c0\uba74 \ub450 \uc7a5\uc744 \ube44\uad50\ud558\ub294 \ud3b8\uc9d1\uc790\uc758 \uc0bd\ud654.", "text": "CSS \u2014 \uac19\uc740 \uae00\uc774 \ub2e4\ub978 \uc5bc\uad74\ub85c \ubcf4\uc774\ub294 \uc774\uc720 \ub0b4\uc6a9\uc758 \uad6c\uc870\uc640 \uc77d\ub294 \ubaa8\uc2b5\uc744 \ub098\ub204\uc5b4 \uc0dd\uac01\ud558\uae30 \uc6f9 \ubb38\uc11c\uc758 \ub0b4\uc6a9\uacfc \ud45c\ud604 \uaddc\uce59\uc744 \uad6c\ubd84\ud558\uba70 \uae00\uc790\u00b7\uc5ec\ubc31\u00b7\ubc30\uce58\uac00 \ub3c5\uc11c \uacbd\ud5d8\uc744 \ubc14\uafb8\ub294 \uc6d0\ub9ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Software \ucef4\ud4e8\ud305 \uac19\uc740 \uae00\uc778\ub370 \ud55c\ucabd\uc5d0\uc11c\ub294 \uc77d\uae30 \ud3b8\ud558\uace0 \ub2e4\ub978 \ucabd\uc5d0\uc11c\ub294 \ub2f5\ub2f5\ud558\ub2e4. \ubb38\uc7a5\uc740 \ubc14\ub00c\uc9c0 \uc54a\uc558\ub2e4. \uae00\uc790 \ud06c\uae30\uc640 \uc904 \uc0ac\uc774, \ubcf8\ubb38\uc774 \ucc28\uc9c0\ud558\ub294 \ud3ed\uc774 \ub2ec\ub77c\uc84c\uc744 \ubfd0\uc774\ub2e4. \ub0b4\uc6a9\uc744 \uc774\ud574\ud558\ub294 \ub370 \ub514\uc790\uc778\uc774 \uc5bc\ub9c8\ub098 \uad00\uc5ec\ud558\ub294\uc9c0 \uc774\ub7f0 \uc21c\uac04\uc5d0 \uc2e4\uac10\ud558\uac8c \ub41c\ub2e4. \uc6f9\ud398\uc774\uc9c0\uc5d0\uc11c\ub294 \uc774 \ud45c\ud604\uc758 \uc0c1\ub2f9 \ubd80\ubd84\uc744 CSS\ub77c\ub294 \uae30\uc220\uc774 \ub9e1\ub294\ub2e4. \uc774\ub984\uc740 \ub0af\uc124\uc5b4\ub3c4 \ub3c5\uc790\uac00 \ub9cc\ub098\ub294 \uacb0\uacfc\ub294 \ub9e4\uc77c \uc775\uc219\ud558\ub2e4. \ucf54\ub4dc\ub97c \ubc30\uc6b0\uae30\ubcf4\ub2e4 \ucc45\uc758 \ud3b8\uc9d1\uacfc \ube44\uad50\ud574 \ubcf4\uba74 \uac19\uc740 \ubb38\uc11c\uac00 \uc5ec\ub7ec \uc5bc\uad74\uc744 \uac16\ub294 \uc774\uc720\ub97c \uc27d\uac8c \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uc6f9 \ubb38\uc11c\uc5d0 \uc4f0\uc774\ub294 HTML\uc740 \uc81c\ubaa9\uacfc \ubb38\ub2e8, \ub9c1\ud06c \uac19\uc740 \ub0b4\uc6a9\uc758 \uad6c\uc870\ub97c \ud45c\uc2dc\ud55c\ub2e4. CSS\ub294 \uadf8\ub7f0 \uc694\uc18c\uac00 \ud654\uba74\uc5d0\uc11c \uc5b4\ub5bb\uac8c \ud45c\ud604\ub420\uc9c0 \uaddc\uce59\uc744 \uc815\ud55c\ub2e4. \uc81c\ubaa9\uc774\ub77c\ub294 \uc5ed\ud560\uacfc \uc81c\ubaa9\uc758 \uae00\uc790\ub97c \ud30c\ub780\uc0c9\uc73c\ub85c \ubcf4\uc774\uac8c \ud558\ub294 \uc120\ud0dd\uc740 \uad6c\ubd84\ub418\ub294 \uac83\uc774\ub2e4. \ucc45\uc73c\ub85c \ube44\uc720\ud558\uba74 \uc6d0\uace0\uc758 \ud070\uc81c\ubaa9\uacfc \ubb38\ub2e8\uc744 \uad6c\ubd84\ud558\ub294 \uc77c, \uadf8\ub9ac\uace0 \uae00\uaf34\uacfc \ud06c\uae30\uc640 \uac04\uaca9\uc744 \uc815\ud558\ub294 \uc77c\uc774 \ub2ee\uc544 \uc788\ub2e4. \uc644\uc804\ud788 \uac19\uc740 \uc81c\uc791 \uacfc\uc815\uc740 \uc544\ub2c8\uc9c0\ub9cc \ub450 \uc885\ub958\uc758 \ud310\ub2e8\uc744 \ub098\ub204\uc5b4 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uad6c\uc870\ub97c \uc720\uc9c0\ud55c \ucc44 \ud45c\ud604\uc744 \ubc14\uafc0 \uc218 \uc788\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud55c \ucd9c\ubc1c\uc810\uc774\ub2e4. \uc791\uc131\uc790\uac00 \ubcc4\ub3c4\uc758 \ud45c\ud604\uc744 \uc9c0\uc815\ud558\uc9c0 \uc54a\uc544\ub3c4 \ube0c\ub77c\uc6b0\uc800\ub294 \uc81c\ubaa9\uc744 \ud06c\uac8c, \ub9c1\ud06c\ub97c \ub2e4\ub978 \uc0c9\uacfc \ubc11\uc904\ub85c \ubcf4\uc5ec \uc8fc\uace4 \ud55c\ub2e4. MDN\uc740 \uc774\ub97c \ube0c\ub77c\uc6b0\uc800\uc758 \uae30\ubcf8 \uc2a4\ud0c0\uc77c\uc774\ub77c\uace0 \uc124\uba85\ud55c\ub2e4. \uc815\ub9d0 \uc544\ubb34 \uaddc\uce59\ub3c4 \uc5c6\uc774 \uae00\uc790\ub9cc \ud769\uc5b4 \ub193\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774 \ub355\ubd84\uc5d0 \ud2b9\ubcc4\ud55c \ub514\uc790\uc778\uc774 \uc5c6\ub294 \ubb38\uc11c\ub3c4 \uc5b4\ub290 \uc815\ub3c4 \uad6c\ubd84\ud574 \uc77d\uc744 \uc218 \uc788\ub2e4. \uc775\uc219\ud574\uc11c \uc790\uc5f0\ucc98\ub7fc \ub290\ub07c\ub358 \ubaa8\uc2b5\uc5d0\ub3c4 \ub204\uad70\uac00 \uc815\ud55c \uae30\ubcf8\uac12\uc774 \uc788\uc5c8\ub358 \uc148\uc774\ub2e4. \uc6f9\ud398\uc774\uc9c0\uc758 \ud45c\ud604\uc744 \uc774\ud574\ud558\ub824\uba74 \ubcf4\uc774\ub294 \uc0c9\ubfd0 \uc544\ub2c8\ub77c \uc9c0\uc815\ud558\uc9c0 \uc54a\uc558\uc744 \ub54c \ubb34\uc5c7\uc774 \uc801\uc6a9\ub418\ub294\uc9c0\ub3c4 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. CSS\ub294 \uc5b4\ub5a4 \uc694\uc18c\uc5d0 \uc5b4\ub5a4 \ud45c\ud604\uc744 \uc801\uc6a9\ud560\uc9c0 \uaddc\uce59\uc73c\ub85c \uc801\ub294\ub2e4. \ubaa8\ub4e0 \ubcf8\ubb38 \ubb38\ub2e8\uc758 \uae00\uc790\uc640 \ubc30\uacbd, \uc5ec\ubc31\uc744 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \uc815\ud560 \uc218 \uc788\ub2e4. \ubb38\ub2e8\uc774 \ub298\uc5b4\ub0a0 \ub54c\ub9c8\ub2e4 \ud55c \uc904\uc529 \uc218\ub3d9\uc73c\ub85c \uc0c9\uce60\ud558\ub294 \ubc29\uc2dd\uacfc\ub294 \ub2e4\ub974\ub2e4. \uacf5\ud1b5\uc758 \uc5ed\ud560\uc744 \uac00\uc9c4 \uc694\uc18c\ub4e4\uc744 \ud568\uaed8 \ub2e4\ub8e8\ub294 \uac83\uc774\ub2e4. MDN\uc758 \uc608\uc5d0\uc11c\ub3c4 \uc0c8 \ubb38\ub2e8\uc744 \ucd94\uac00\ud558\uba74 \uae30\uc874 \ubb38\ub2e8 \uaddc\uce59\uc774 \uc801\uc6a9\ub41c\ub2e4. \ub3c5\uc790\ub294 \ubb38\ubc95\uc744 \uc678\uc6b8 \ud544\uc694\uac00 \uc5c6\ub2e4. \uac19\uc740 \uc885\ub958\uc758 \ub0b4\uc6a9\uc5d0 \uac19\uc740 \ud45c\ud604\uc744 \uc8fc\ub294 \uc57d\uc18d\uc774 \uc788\ub2e4\ub294 \uc810\ub9cc \uc774\ud574\ud558\uba74 \ub41c\ub2e4. \uc5ec\ub7ec \ud398\uc774\uc9c0\uac00 \ud55c \uc0ac\uc774\ud2b8\ucc98\ub7fc \ub290\uaef4\uc9c0\ub294 \ub370\ub3c4 \uc774\ub7f0 \ubc18\ubcf5\uc758 \uc9c8\uc11c\uac00 \ub3c4\uc6c0\uc744 \uc900\ub2e4. CSS\ub294 \uae00\uc790 \ud06c\uae30\uc640 \uc0c9\ubfd0 \uc544\ub2c8\ub77c \ud654\uba74\uc758 \ubc30\uce58\ub3c4 \ub2e4\ub8ec\ub2e4. \ub0b4\uc6a9\uc744 \uc5ec\ub7ec \uce78\uc73c\ub85c \uc815\ub82c\ud558\uac70\ub098 \uc694\uc18c \uc0ac\uc774\uc758 \uac04\uaca9\uc744 \uc815\ud558\uace0 \uc6c0\uc9c1\uc784\uc744 \uc904 \uc218\ub3c4 \uc788\ub2e4. \uadf8\ub798\uc11c \uc6f9 \ub514\uc790\uc778\uc744 \ub2e8\uc21c\ud788 \uae00\uc5d0 \uc608\uc05c \uc0c9\uc744 \uce60\ud558\ub294 \uc77c\ub85c\ub9cc \ubcf4\uba74 \uc911\uc694\ud55c \ubd80\ubd84\uc744 \ub193\uce5c\ub2e4. \uc77d\ub294 \uc21c\uc11c\uc640 \uc2dc\uc120\uc774 \uc26c\ub294 \uc790\ub9ac\ub3c4 \ud45c\ud604\uc758 \uc601\ud5a5\uc744 \ubc1b\ub294\ub2e4. \uc81c\ubaa9\uc774 \uc9c0\ub098\uce58\uac8c \uc791\uc73c\uba74 \uad6c\uc870\ub97c \ub193\uce58\uae30 \uc27d\uace0, \uc5ec\ubc31\uc774 \uc5c6\uc73c\uba74 \uc11c\ub85c \ub2e4\ub978 \ub0b4\uc6a9\uc774 \ubd99\uc5b4 \ubcf4\uc77c \uc218 \uc788\ub2e4. \uc774\uac83\uc740 \ud2b9\uc815 \uc218\uce58 \ud558\ub098\uac00 \uc5b8\uc81c\ub098 \uc815\ub2f5\uc774\ub77c\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \ub0b4\uc6a9\uc744 \uc5b4\ub5a4 \ud658\uacbd\uc5d0\uc11c \uc77d\ub294\uc9c0\uac00 \ud568\uaed8 \uc911\uc694\ud558\ub2e4. CSS\ub294 HTML \uc548\uc5d0 \uc801\uc744 \uc218\ub3c4 \uc788\uace0 \ubcc4\ub3c4\uc758 \ud30c\uc77c\ub85c \uc5f0\uacb0\ud560 \uc218\ub3c4 \uc788\ub2e4. MDN\uc740 \ube0c\ub77c\uc6b0\uc800\uac00 \uc774\ub7f0 \ud45c\ud604 \uaddc\uce59\uc744 \ucc3e\uc544 \ubb38\uc11c\uc5d0 \uc801\uc6a9\ud55c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc5ec\ub7ec \ubb38\uc11c\uac00 \uacf5\ud1b5\uc758 \ud45c\ud604 \ud30c\uc77c\uc744 \uc0ac\uc6a9\ud558\uba74 \uc6d0\uace0 \uc804\uccb4\ub97c \ub2e4\uc2dc \uc4f0\uc9c0 \uc54a\uace0\ub3c4 \ubaa8\uc2b5\uc744 \uc870\uc815\ud560 \uc218 \uc788\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \ubcf8\ubb38 \uac04\uaca9\uc744 \ub113\ud788\ub294 \uc120\ud0dd\uc740 \uc774\uc57c\uae30\uc758 \uc0ac\uc2e4\uad00\uacc4\ub97c \ubc14\uafb8\ub294 \uc77c\uacfc \ub2e4\ub974\ub2e4. \ub0b4\uc6a9 \uc218\uc815\uacfc \ub514\uc790\uc778 \uc218\uc815\uc758 \ubc94\uc704\ub97c \ub098\ub20c \uc218 \uc788\ub294 \uac83\uc774\ub2e4. \ub2e4\ub9cc \uad6c\uc870\uac00 \ubd80\uc2e4\ud55c \ubb38\uc11c\ub97c \uac89\ubaa8\uc591\ub9cc\uc73c\ub85c \uc798 \uc815\ub9ac\ub41c \ubb38\uc11c\ub85c \ub9cc\ub4e4 \uc218\ub294 \uc5c6\ub2e4. \ud45c\ud604\uacfc \ub0b4\uc6a9\uc774 \uc5ed\ud560\uc744 \ub098\ub204\ub354\ub77c\ub3c4 \uc11c\ub85c\uc758 \uc0c1\ud0dc\ub294 \ub3c5\uc11c\uc5d0 \ud568\uaed8 \uc601\ud5a5\uc744 \uc900\ub2e4. \ube0c\ub77c\uc6b0\uc800\ub294 \ubb38\uc11c\uc758 \uad6c\uc870\ub97c \uc77d\uace0 \uc5b4\ub5a4 \ubd80\ubd84\uc5d0 \uc5b4\ub5a4 CSS \uaddc\uce59\uc774 \ud574\ub2f9\ud558\ub294\uc9c0 \uc815\ub9ac\ud55c\ub2e4. \uadf8 \uacb0\uacfc\ub97c \ubc14\ud0d5\uc73c\ub85c \ud654\uba74\uc5d0 \uadf8\ub9b0\ub2e4. \ub3c5\uc790\uac00 \ubcf4\ub294 \uc644\uc131\ub41c \ud398\uc774\uc9c0 \ub4a4\uc5d0\ub294 \ubb38\uc11c\uc640 \ud45c\ud604\uc744 \uc5f0\uacb0\ud558\ub294 \uacfc\uc815\uc774 \uc788\ub294 \uc148\uc774\ub2e4. \ud30c\uc77c\uc5d0 \uc801\ud78c \uae00\uc790\uac00 \uace7\ubc14\ub85c \uac19\uc740 \ubaa8\uc591\uc758 \ud654\uba74\uc774 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc6f9\ud398\uc774\uc9c0\uac00 \ud56d\uc0c1 \uac19\uc740 \uc21c\uac04\uc5d0 \ub611\uac19\uc774 \uc644\uc131\ub41c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ud544\uc694\ud55c \uc790\ub8cc\uac00 \ub3c4\ucc29\ud558\ub294 \uc870\uac74\uacfc \ud504\ub85c\uadf8\ub7a8\uc758 \uc9c0\uc6d0\ub3c4 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\ub2e4. \uc774\ubc88 \uae00\uc740 \uc791\ub3d9\uc758 \ud070 \uad6c\ubd84\uc744 \uc774\ud574\ud558\ub294 \uc774\uc57c\uae30\ub2e4. \ubcf5\uc7a1\ud55c \ud45c\uc2dc \ubb38\uc81c\ub97c \ud55c \uac00\uc9c0 \uc6d0\uc778\uc73c\ub85c \uc9c4\ub2e8\ud558\ub294 \uc124\uba85\uc740 \uc544\ub2c8\ub2e4. \ud45c\ud604\uc740 \ub208\uae38\uc744 \ub04c\uae30 \uc704\ud55c \uc7a5\uc2dd\uc77c \uc218\ub3c4 \uc788\uc9c0\ub9cc \uc77d\ub294 \uc0ac\ub78c\uc744 \ub3d5\ub294 \uc77c\uc77c \uc218\ub3c4 \uc788\ub2e4. \ub0b4\uc6a9\uc758 \uc911\uc694\ub3c4\uac00 \uad6c\ubd84\ub418\uace0 \ubb38\ub2e8\uc758 \uacbd\uacc4\uac00 \ub290\uaef4\uc9c0\uba74 \ub3c5\uc790\ub294 \uae00\uc758 \uae38\uc744 \ucc3e\uae30 \uc26c\uc6cc\uc9c4\ub2e4. \ud654\ub824\ud568\uacfc \uac00\ub3c5\uc131\uc740 \uac19\uc740 \uae30\uc900\uc774 \uc544\ub2c8\ubbc0\ub85c \ubaa9\uc801\uc744 \ub098\ub204\uc5b4 \ubcfc \ud544\uc694\uac00 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uac19\uc740 \uc6d0\uace0\uc758 \uc11c\ub85c \ub2e4\ub978 \uc9c0\uba74\uc744 \uc0b4\ud53c\ub294 \ud3b8\uc9d1 \uc7a5\uba74\uc774\ub2e4. \uc2e4\uc81c \ube0c\ub77c\uc6b0\uc800\uc758 \ud45c\uc2dc \uc2e4\ud5d8\uc774\ub098 \ud2b9\uc815 CSS \ucf54\ub4dc\uc758 \uacb0\uacfc \ud654\uba74\uc740 \uc544\ub2c8\ub2e4. \uae00\uc758 \ub0b4\uc6a9\uacfc \uadf8\uac83\uc744 \ub193\ub294 \ubc29\uc2dd \uc0ac\uc774\uc758 \uad00\uacc4\ub97c \ub5a0\uc62c\ub9ac\ub294 \ubd84\uc704\uae30 \uadf8\ub9bc\uc774\ub2e4. CSS\ub97c \uc54c\uba74 \uc6f9\ud398\uc774\uc9c0\ub97c \ubcfc \ub54c \ubb38\uc7a5\uacfc \ub514\uc790\uc778\uc744 \uc870\uae08 \ub098\ub204\uc5b4 \uc77d\uac8c \ub41c\ub2e4. \uae00\uc774 \uc5b4\ub824\uc6cc\uc11c \uc77d\uae30 \ud798\ub4e0\uc9c0, \ud45c\ud604 \ub54c\ubb38\uc5d0 \uae38\uc744 \uc783\ub294\uc9c0 \uc9c8\ubb38\ud560 \uc218 \uc788\ub2e4. \uac19\uc740 \ub0b4\uc6a9\uc774\ub77c\ub3c4 \uadf8\uac83\uc744 \ub9cc\ub098\ub294 \uacbd\ud5d8\uc740 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ub354 \uad6c\uccb4\uc801\uc73c\ub85c \ubcf4\uc778\ub2e4. \ub2e4\uc74c\uc5d0 \ub9c8\uc74c\uc5d0 \ub4dc\ub294 \uc77d\uae30 \ud654\uba74\uc744 \ub9cc\ub098\uba74 \uc0c9\ub9cc \ubcf4\uc9c0 \ub9d0\uace0 \uc81c\ubaa9\uc758 \ud06c\uae30\uc640 \uc5ec\ubc31, \ubb38\ub2e8\uc758 \ud3ed\ub3c4 \uc0b4\ud3b4\ubcf4\uc790. \uadf8\uacf3\uc5d0\ub294 \ub3c5\uc790\uc758 \ub208\uc744 \uc5b4\ub5bb\uac8c \uc774\ub04c\uc9c0\uc5d0 \uad00\ud55c \uc120\ud0dd\uc774 \ub4e4\uc5b4 \uc788\ub2e4. CSS\ub294 \uc6f9\uc758 \uae00\uc774 \uc5b4\ub5a4 \uc5bc\uad74\ub85c \uc0ac\ub78c\uc744 \ub9cc\ub0a0\uc9c0 \uc815\ud558\ub294 \uc5ec\ub7ec \uc57d\uc18d \uac00\uc6b4\ub370 \ud558\ub098\ub2e4."}, {"id": "csv-comma-inside-a-cell", "title": "CSV \u2014 \uc27c\ud45c\uac00 \ub4e4\uc5b4 \uc788\ub294 \uce78\uc740 \uc5b4\ub5bb\uac8c \ub098\ub20c\uae4c", "summary": "\ub3c4\uc11c \ubaa9\ub85d\uc758 \uac00\uc0c1 \uc608\ub85c \uad6c\ubd84\uc790\u00b7\ub530\uc634\ud45c\u00b7\ubb38\uc790\uc5f4\uacfc \uc22b\uc790\uc758 \ucc28\uc774\ub97c \uc774\ud574\ud558\uba70 CSV\uc758 \uc6d0\ub9ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "computing", "category_title": "Computing", "subcategory": "Programming", "url": "stories/csv-comma-inside-a-cell/index.html", "image": "media/csv-comma-inside-a-cell.png", "alt": "\uc0c9\ubcc4\ub85c \ub098\ub208 \uae30\ub85d \uce74\ub4dc\ub97c \uc815\ub9ac\ud558\ub294 \uc0ac\ub78c\uacfc \ub178\ud2b8\ubd81\uc774 \uc788\ub294 \ucc45\uc0c1\uc758 \uc0bd\ud654.", "text": "CSV \u2014 \uc27c\ud45c\uac00 \ub4e4\uc5b4 \uc788\ub294 \uce78\uc740 \uc5b4\ub5bb\uac8c \ub098\ub20c\uae4c \uac04\ub2e8\ud55c \ud45c\ub97c \uc8fc\uace0\ubc1b\uc744 \ub54c \ud544\uc694\ud55c \uc791\uc740 \uc57d\uc18d\ub4e4 \ub3c4\uc11c \ubaa9\ub85d\uc758 \uac00\uc0c1 \uc608\ub85c \uad6c\ubd84\uc790\u00b7\ub530\uc634\ud45c\u00b7\ubb38\uc790\uc5f4\uacfc \uc22b\uc790\uc758 \ucc28\uc774\ub97c \uc774\ud574\ud558\uba70 CSV\uc758 \uc6d0\ub9ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Programming \ucef4\ud4e8\ud305 \ub3c4\uc11c \ubaa9\ub85d\uc744 \ub2e4\ub978 \ud504\ub85c\uadf8\ub7a8\uc73c\ub85c \uc62e\uacbc\ub354\ub2c8 \uc81c\ubaa9\uc774 \ub450 \uce78\uc73c\ub85c \uac08\ub77c\uc84c\ub2e4. \uc81c\ubaa9 \uc548\uc5d0 \uc788\ub358 \uc27c\ud45c\uac00 \uce78\uc744 \ub098\ub204\ub294 \ud45c\uc2dc\ucc98\ub7fc \ucc98\ub9ac\ub41c \uac83\uc774\ub2e4. \ub208\uc73c\ub85c \ubcf4\uba74 \ud55c \uc81c\ubaa9\uc778\ub370 \ucef4\ud4e8\ud130\uc5d0\uac8c\ub294 \uc5b4\ub514\uc11c \ud56d\ubaa9\uc774 \ub05d\ub098\ub294\uc9c0 \ubd84\uba85\ud558\uc9c0 \uc54a\uc558\ub358 \uc148\uc774\ub2e4. \ud45c\ub97c \uc8fc\uace0\ubc1b\uc744 \ub54c \uc790\uc8fc \ub9cc\ub098\ub294 CSV\ub294 \uc774 \ubb38\uc81c\ub97c \uc0dd\uac01\ud558\uae30 \uc88b\uc740 \ud615\uc2dd\uc774\ub2e4. \ubcf5\uc7a1\ud55c \uacc4\uc0b0\uc744 \ubc30\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \ub41c\ub2e4. \uc27c\ud45c\uc640 \ub530\uc634\ud45c\ub97c \uc5b4\ub5a4 \uc5ed\ud560\ub85c \uc4f8\uc9c0 \uc57d\uc18d\ud558\ub294 \uc791\uc740 \ubb38\uc81c\uac00 \uc5ec\ub7ec \ud504\ub85c\uadf8\ub7a8 \uc0ac\uc774\uc758 \ud611\ub825\uacfc \uc5f0\uacb0\ub41c\ub2e4\ub294 \uc810\uc744 \uc0b4\ud3b4\ubcf4\uc790. CSV\ub294 \uc27c\ud45c\ub85c \uad6c\ubd84\ud55c \uac12\uc774\ub77c\ub294 \ub73b\uc758 \uc774\ub984\uc774\ub2e4. \uc2a4\ud504\ub808\ub4dc\uc2dc\ud2b8\ub098 \ub370\uc774\ud130\ubca0\uc774\uc2a4\uc758 \uc815\ubcf4\ub97c \ub0b4\ubcf4\ub0b4\uace0 \uac00\uc838\uc62c \ub54c \ub110\ub9ac \uc4f0\uc778\ub2e4. \uc5ec\ub7ec \uce78\uc5d0 \ub4e4\uc5b4 \uc788\ub358 \ub0b4\uc6a9\uc744 \uc77c\uc815\ud55c \uad6c\ubd84 \ud45c\uc2dc\ub97c \uc0ac\uc6a9\ud574 \ud14d\uc2a4\ud2b8\ub85c \uc801\ub294 \ubc29\uc2dd\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uba74 \uccab \uc774\ud574\uc5d0 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ud654\uba74\uc5d0\uc11c \ubcf8 \ud45c\uc758 \ud14c\ub450\ub9ac\uc640 \uc0c9\uc744 \uadf8\ub300\ub85c \uc62e\uae30\ub294 \uac83\uc774 \ud575\uc2ec\uc740 \uc544\ub2c8\ub2e4. \uac01 \uc904\uacfc \ud56d\ubaa9\uc5d0 \uc5b4\ub5a4 \uac12\uc774 \uc788\ub294\uc9c0\ub97c \uc8fc\uace0\ubc1b\ub294 \ub370 \ucd08\uc810\uc774 \uc788\ub2e4. \ubcf4\uae30 \uc88b\uc740 \uc9c0\uba74\uacfc \uc815\ubcf4\uc758 \uc804\ub2ec\uc740 \ub2e4\ub978 \ubaa9\uc801\uc77c \uc218 \uc788\ub2e4. \uac19\uc740 \ubaa9\ub85d\ub3c4 \uc5b4\ub5a4 \ubd80\ubd84\uc744 \ubcf4\uad00\ud558\ub824\ub294\uc9c0\uc5d0 \ub530\ub77c \ud30c\uc77c\uc758 \ud615\ud0dc\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \uac00\uc0c1\uc758 \ucc45 \uc81c\ubaa9\uc744 \u300a\ubc14\ub2e4, \uadf8\ub9ac\uace0 \uc9d1\u300b\uc774\ub77c\uace0 \ud574 \ubcf4\uc790. \uadf8 \ub2e4\uc74c \uce78\uc5d0\ub294 \ub3c4\uc2dc \uc774\ub984 \uc11c\uc6b8\uc744 \ub123\uace0 \uc2f6\ub2e4. \uc81c\ubaa9 \uc18d\uc758 \uc27c\ud45c\uc640 \uce78 \uc0ac\uc774\uc758 \uc27c\ud45c\uac00 \ub611\uac19\uc774 \uc0dd\uacbc\uc73c\ubbc0\ub85c \ub2e8\uc21c\ud788 \uc27c\ud45c\ub97c \ub9cc\ub0a0 \ub54c\ub9c8\ub2e4 \ub098\ub204\uba74 \uc81c\ubaa9\uc774 \ub458\ub85c \uac08\ub77c\uc9c4\ub2e4. \uc774\ub984\ud45c\ub97c \ub530\uc634\ud45c\ub85c \ubb36\ub294 \uc57d\uc18d\uc744 \uc0ac\uc6a9\ud558\uba74 \uadf8 \uc548\ucabd\uc758 \uc27c\ud45c\ub97c \uac12\uc758 \uc77c\ubd80\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \uc774 \uc608\ub97c \uc2e4\uc81c CSV \ud55c \uc904\ub85c \uc801\uc73c\uba74 \"\ubc14\ub2e4, \uadf8\ub9ac\uace0 \uc9d1\",\uc11c\uc6b8\uc774 \ub41c\ub2e4. \uc77d\ub294 \ud504\ub85c\uadf8\ub7a8\uc774 \uac19\uc740 \uc57d\uc18d\uc744 \ub530\ub97c \ub54c \uccab \ud56d\ubaa9\uc740 \uc81c\ubaa9 \uc804\uccb4, \ub450 \ubc88\uc9f8 \ud56d\ubaa9\uc740 \uc11c\uc6b8\ub85c \ub098\ub25c\ub2e4. \ubb38\uc81c\ub294 \ud55c \ub2e8\uacc4 \ub354 \uc774\uc5b4\uc9c4\ub2e4. \ud56d\ubaa9\uc758 \ub0b4\uc6a9\uc5d0 \ub530\uc634\ud45c\uac00 \ub4e4\uc5b4\uac08 \uc218\ub3c4 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uac12\uc758 \uacbd\uacc4\ub97c \uc54c\ub9ac\ub294 \ub530\uc634\ud45c\uc640 \uc2e4\uc81c \ubb38\uc7a5 \uc18d\uc758 \ub530\uc634\ud45c\ub97c \uad6c\ubd84\ud560 \ubc29\ubc95\uc774 \ud544\uc694\ud558\ub2e4. \uac19\uc740 \ud45c\uc2dc\uac00 \ub450 \uc5ed\ud560\uc744 \uac16\uac8c \ub418\uba74 \uc608\uc678\ub97c \ucc98\ub9ac\ud558\ub294 \uc57d\uc18d\ub3c4 \uc0dd\uae34\ub2e4. \ud30c\uc774\uc36c\uc758 CSV \ubb38\uc11c\ub294 \ub530\uc634\ud45c\ub97c \uacb9\uccd0 \uc4f0\ub294 \ubc29\uc2dd\uc774\ub098 \ubcc4\ub3c4\uc758 \ucc98\ub9ac \ud45c\uc2dc\ub97c \uc0ac\uc6a9\ud558\ub294 \uc124\uc815\uc744 \uc124\uba85\ud55c\ub2e4. \ubaa8\ub4e0 \uc138\ubd80\ub97c \uc678\uc6b0\ub294 \uac83\ubcf4\ub2e4 \uc65c \uaddc\uce59\uc774 \ud544\uc694\ud55c\uc9c0 \uc774\ud574\ud558\uba74 \ub41c\ub2e4. \uc0ac\ub78c\uc774 \ubb38\ub9e5\uc73c\ub85c \uc54c\uc544\ubcf4\ub294 \uad6c\ubd84\uc744 \ucef4\ud4e8\ud130\uc5d0\uac8c \ub9e1\uae30\ub824\uba74 \uadf8 \ubb38\ub9e5\uc744 \ub354 \uba85\uc2dc\uc801\uc73c\ub85c \ud45c\ud604\ud574\uc57c \ud558\ub294 \uac83\uc774\ub2e4. \uacf5\uc2dd \ubb38\uc11c\ub294 \ud504\ub85c\uadf8\ub7a8\ub9c8\ub2e4 \uad6c\ubd84\uc790\uc640 \ub530\uc634\ud45c \ub4f1\uc758 \uc138\ubd80\uac00 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. CSV\ub77c\ub294 \uc774\ub984\uc744 \uc37c\ub2e4\uace0 \ubaa8\ub4e0 \ud30c\uc77c\uc774 \ud55c \uac00\uc9c0 \ubc29\uc2dd\uc73c\ub85c\ub9cc \ub9cc\ub4e4\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ube44\uc2b7\ud55c \ubaa8\uc591 \uc548\uc5d0\ub3c4 \uc5ec\ub7ec \uad00\ub840\uac00 \uc788\uc5b4\uc11c \uc77d\ub294 \ucabd\uacfc \uc4f0\ub294 \ucabd\uc758 \uc124\uc815\uc774 \ub9de\uc544\uc57c \ud55c\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \uc5b4\ub5a4 \uc790\ub8cc\ub294 \ud56d\ubaa9 \uad6c\ubd84\uc5d0 \ub2e4\ub978 \ubb38\uc790\ub97c \uc0ac\uc6a9\ud55c\ub2e4. \ud30c\uc774\uc36c\uc740 \uc774\ub7f0 \ucc28\uc774\ub97c \ub2e4\ub8e8\uae30 \uc704\ud55c \uc124\uc815 \ubb36\uc74c\uc744 \uc81c\uacf5\ud55c\ub2e4. \ub3c5\uc790\uac00 \uadf8 \uc124\uc815 \uc774\ub984\uc744 \ubc30\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \ud30c\uc77c\uc744 \ubc1b\uc558\ub294\ub370 \ud55c \uce78\uc5d0 \ub0b4\uc6a9\uc774 \ubab0\ub9ac\uac70\ub098 \uc5c9\ub6b1\ud558\uac8c \uac08\ub77c\uc9c4\ub2e4\uba74 \uc790\ub8cc\uac00 \uc804\ubd80 \uc0ac\ub77c\uc84c\ub2e4\uace0 \uc0dd\uac01\ud558\uae30 \uc804\uc5d0 \uad6c\ubd84\uc758 \uc57d\uc18d\uc744 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \ud45c\uc5d0 0012\uac00 \uc801\ud600 \uc788\ub2e4. \uc774\uac83\uc774 \uc218\ub7c9\uc774\ub77c\uba74 \uc22b\uc790 12\uc640 \uac19\uc740 \uac12\uc744 \ub73b\ud560 \uc218 \uc788\uc9c0\ub9cc, \ubb3c\uac74\uc758 \uc2dd\ubcc4 \ubc88\ud638\ub77c\uba74 \uc55e\uc758 0\uae4c\uc9c0 \uc911\uc694\ud560 \uc218 \uc788\ub2e4. \uac19\uc740 \ubaa8\uc591\uc744 \uc77d\ub294 \ubc29\ubc95\uc5d0 \ub530\ub77c \ub0a8\uaca8\uc57c \ud560 \uc815\ubcf4\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \ubb38\uc790\ub97c \uc22b\uc790\ub85c \ubc14\uafb8\ub294 \uc77c\uc5d0\ub3c4 \ud310\ub2e8\uc774 \ub4e4\uc5b4\uac04\ub2e4. \uacf5\uc2dd \ubb38\uc11c\ub294 \uae30\ubcf8 CSV \uc77d\uae30\uac00 \uac01 \ud56d\ubaa9\uc744 \ubb38\uc790\uc5f4\ub85c \ub3cc\ub824\uc8fc\uba70, \ud2b9\uc815 \uc635\uc158 \uc5c6\uc774 \uc790\ub3d9\uc73c\ub85c \uc790\ub8cc\ud615\uc744 \ubc14\uafb8\uc9c0 \uc54a\ub294\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub2e4\ub978 \ud504\ub85c\uadf8\ub7a8\uc740 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \ud574\uc11d\ud560 \uc218 \uc788\ub2e4. \ub530\ub77c\uc11c \uc5b4\ub5a4 \uac12\uc774 \ubcf4\uc600\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uadf8\uac83\uc774 \uc5b4\ub5a4 \uc885\ub958\uc758 \uc815\ubcf4\ub85c \uc77d\ud614\ub294\uc9c0\ub97c \uad6c\ubd84\ud558\ub294 \uc2b5\uad00\uc774 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ub3c4\uc11c \ubaa9\ub85d\uc758 \uccab \uc904\uc5d0 \uc81c\ubaa9\uacfc \ub3c4\uc2dc\ub77c\ub294 \ud56d\ubaa9 \uc774\ub984\uc744 \ub123\uc744 \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uadf8 \uc904\uc774 \uc124\uba85\uc778\uc9c0 \uc2e4\uc81c \uc790\ub8cc\uc758 \uccab \ud589\uc778\uc9c0\ub294 \uc77d\ub294 \ubc29\uc2dd\uc5d0 \ub2ec\ub824 \uc788\ub2e4. \ud30c\uc774\uc36c\uc758 \uc0ac\uc804 \ud615\ud0dc \uc77d\uae30\ub294 \uccab \ud589\uc744 \ud56d\ubaa9 \uc774\ub984\uc73c\ub85c \uc0ac\uc6a9\ud558\ub294 \ubc29\ubc95 \ub4f1\uc744 \uc81c\uacf5\ud55c\ub2e4. \ub2e8\uc21c\ud55c \uc904\uc5d0\ub3c4 \uc5ed\ud560\uc744 \uc815\ud558\ub294 \uc120\ud0dd\uc774 \uc788\ub294 \uac83\uc774\ub2e4. \ubaa9\ub85d\uc744 \uc798 \uc804\ub2ec\ud558\ub824\uba74 \ud30c\uc77c \ud558\ub098\ubfd0 \uc544\ub2c8\ub77c \uc5f4\uc758 \uc758\ubbf8\ub3c4 \ubd84\uba85\ud574\uc57c \ud55c\ub2e4. \uac19\uc740 \ub3c4\uc2dc\ub77c\ub294 \uce78\uc5d0 \ucd9c\uc0dd\uc9c0\uc640 \ucd9c\ud310\uc9c0\ub97c \uc11e\uc73c\uba74 \ud615\uc2dd\uc774 \uc815\uc0c1\uc774\uc5b4\ub3c4 \ub0b4\uc6a9\uc740 \uc624\ud574\ub420 \uc218 \uc788\ub2e4. \ucef4\ud4e8\ud130\uac00 \uc798 \ub098\ub204\uc5b4 \uc77d\ub294 \uc77c\uacfc \uc0ac\ub78c\uc774 \uac19\uc740 \ub73b\uc73c\ub85c \uc774\ud574\ud558\ub294 \uc77c\uc740 \uc11c\ub85c \ub2e4\ub978 \ud655\uc778\uc774\ub2e4. \uc774 \uc6d0\uace0\uc758 \uac00\uc0c1 \uc81c\ubaa9\uacfc \uc11c\uc6b8\uc744 \ub123\uc740 \ud55c \uc904\uc740 \ud30c\uc774\uc36c CSV \uc77d\uae30\ub85c \uc9c1\uc811 \ud655\uc778\ud588\ub2e4. \uccab \ud56d\ubaa9\uc774 \ubc14\ub2e4, \uadf8\ub9ac\uace0 \uc9d1\uc73c\ub85c \uc720\uc9c0\ub418\ub294\uc9c0, \ub450 \ubc88\uc9f8\uac00 \uc11c\uc6b8\uc778\uc9c0 \ube44\uad50\ud588\ub2e4. \uc544\uc8fc \uc791\uc740 \uac80\uc0b0\uc774\uc9c0\ub9cc \ub9d0\ub85c \uc124\uba85\ud55c \uaddc\uce59\uc774 \uc2e4\uc81c \uc608\uc640 \ub9de\ub294\uc9c0 \uc0b4\ud53c\ub294 \uacfc\uc815\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uae30\ub85d \uce74\ub4dc\ub97c \uc815\ub9ac\ud558\ub294 \ubd84\uc704\uae30\ub97c \ud45c\ud604\ud55c\ub2e4. \uc2e4\uc81c CSV \ud30c\uc77c\uc774\ub098 \ud504\ub85c\uadf8\ub7a8\uc758 \uc2e4\ud589 \uacb0\uacfc\ub97c \uadf8\ub9b0 \ub3c4\uc2dd\uc740 \uc544\ub2c8\ub2e4. \uce74\ub4dc\uac00 \ub098\ub258\uc5b4 \uc788\uc5b4\uc57c \uc815\ub9ac\ud558\uae30 \uc26c\uc6b4 \uac83\ucc98\ub7fc, \ud14d\uc2a4\ud2b8\uc758 \uac12\uc5d0\ub3c4 \uc11c\ub85c \ud569\uc758\ud55c \uacbd\uacc4\uac00 \ud544\uc694\ud558\ub2e4\ub294 \uc0dd\uac01\uc744 \ub5a0\uc62c\ub9ac\ub294 \uadf8\ub9bc\uc774\ub2e4. CSV\uc758 \ub9e4\ub825\uc740 \ube44\uad50\uc801 \ub2e8\uc21c\ud55c \ud14d\uc2a4\ud2b8\ub85c \uc5ec\ub7ec \ub3c4\uad6c \uc0ac\uc774\uc5d0 \ud45c\uc758 \uac12\uc744 \uc62e\uae38 \uc218 \uc788\ub2e4\ub294 \ub370 \uc788\ub2e4. \uadf8\ub7ec\ub098 \ub2e8\uc21c\ud558\ub2e4\ub294 \ub9d0\uc774 \uc544\ubb34 \uaddc\uce59\ub3c4 \uc5c6\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc27c\ud45c\uc640 \ub530\uc634\ud45c, \uccab \uc904\uacfc \uc790\ub8cc\ud615\uc5d0 \uad00\ud55c \uc120\ud0dd\uc774 \uc11c\ub85c \ub9de\uc544\uc57c \ud55c\ub2e4. \ub2e4\uc74c\uc5d0 \ub0b4\ub824\ubc1b\uc740 \ubaa9\ub85d\uc774 \uc5c9\ucf1c \ubcf4\uc774\uba74 \uc774 \uc791\uc740 \uc57d\uc18d\ub4e4\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \ub0b4\uc6a9\uc774 \ud2c0\ub838\ub294\uc9c0, \ub098\ub204\uc5b4 \uc77d\ub294 \ubc29\uc2dd\uc774 \ub2ec\ub790\ub294\uc9c0 \uc9c8\ubb38\ud560 \uc218 \uc788\ub2e4. \uc27c\ud45c \ud558\ub098\uc758 \uc790\ub9ac\ub97c \uc774\ud574\ud558\ub294 \uc77c\uc740 \ucef4\ud4e8\ud130\uac00 \uc815\ubcf4\ub97c \uc8fc\uace0\ubc1b\uc744 \ub54c \uc5bc\ub9c8\ub098 \uad6c\uccb4\uc801\uc778 \ud569\uc758\uac00 \ud544\uc694\ud55c\uc9c0 \ubcf4\uc5ec \uc900\ub2e4."}, {"id": "dns-names-and-addresses", "title": "DNS \u2014 \uc0ac\uc774\ud2b8\ub294 \uc774\uc0ac\ud574\ub3c4 \uc774\ub984\uc744 \uc720\uc9c0\ud560 \uc218 \uc788\uc744\uae4c", "summary": "\ub3c4\uba54\uc778 \uc774\ub984\uacfc \uc11c\ubc84 \uc8fc\uc18c, \uc784\uc2dc \uc800\uc7a5\uc744 \ud1b5\ud574 \uc6f9\uc0ac\uc774\ud2b8 \uc774\ub984\uc774 \uc5f0\uacb0\ub418\ub294 \uc6d0\ub9ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "computing", "category_title": "Computing", "subcategory": "Internet", "url": "stories/dns-names-and-addresses/index.html", "image": "media/dns-names-and-addresses.png", "alt": "\uc8fc\uc18c \uce74\ub4dc\ub97c \ub4e4\uace0 \ub178\ud2b8\ubd81\uacfc \ucc3d\ubc16\uc758 \uac70\ub9ac \ud48d\uacbd\uc744 \ubc14\ub77c\ubcf4\ub294 \uc0ac\ub78c\uc758 AI \ube44\uc720 \uc7a5\uba74.", "text": "DNS \u2014 \uc0ac\uc774\ud2b8\ub294 \uc774\uc0ac\ud574\ub3c4 \uc774\ub984\uc744 \uc720\uc9c0\ud560 \uc218 \uc788\uc744\uae4c \uc678\uc6b0\uae30 \uc26c\uc6b4 \uc774\ub984 \ub4a4\uc5d0\uc11c \uc8fc\uc18c\ub97c \ucc3e\uc544 \uc8fc\ub294 \uc57d\uc18d \ub3c4\uba54\uc778 \uc774\ub984\uacfc \uc11c\ubc84 \uc8fc\uc18c, \uc784\uc2dc \uc800\uc7a5\uc744 \ud1b5\ud574 \uc6f9\uc0ac\uc774\ud2b8 \uc774\ub984\uc774 \uc5f0\uacb0\ub418\ub294 \uc6d0\ub9ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Internet \ucef4\ud4e8\ud305 \uc88b\uc544\ud558\ub358 \uac00\uac8c\uac00 \ub2e4\ub978 \uac74\ubb3c\ub85c \uc774\uc0ac\ud588\ub2e4. \uac04\ud310\uc758 \uc774\ub984\uc740 \uadf8\ub300\ub85c\uc9c0\ub9cc \ucc3e\uc544\uac08 \uc8fc\uc18c\ub294 \ub2ec\ub77c\uc84c\ub2e4. \uc6f9\uc0ac\uc774\ud2b8\uc5d0\ub3c4 \ube44\uc2b7\ud55c \uad6c\ubd84\uc774 \uc788\ub2e4. \uc6b0\ub9ac\uac00 \uae30\uc5b5\ud558\ub294 \uc774\ub984\uacfc \uc2e4\uc81c\ub85c \uc811\uc18d\ud560 \uc11c\ubc84\uc758 \uc8fc\uc18c\uac00 \ubc18\ub4dc\uc2dc \uac19\uc740 \uc885\ub958\uc758 \uc815\ubcf4\ub294 \uc544\ub2c8\ub77c\ub294 \uc810\uc774\ub2e4. knowledgewalk.net\ucc98\ub7fc \uc77d\uace0 \uae30\uc5b5\ud558\uae30 \uc26c\uc6b4 \uc774\ub984\uc744 \ub3c4\uba54\uc778 \uc774\ub984\uc774\ub77c\uace0 \ud55c\ub2e4. \ucef4\ud4e8\ud130\uac00 \ud1b5\uc2e0\ud560 \ub54c \uc4f0\ub294 IP \uc8fc\uc18c\ub294 \ubcc4\ub3c4\ub85c \uc788\ub2e4. DNS\ub294 \uc774 \ub458\uc744 \uc5f0\uacb0\ud574 \ud544\uc694\ud55c \uc815\ubcf4\ub97c \ucc3e\ub3c4\ub85d \ub3d5\ub294 \uccb4\uacc4\ub2e4. \uc790\uc8fc \uc811\ud558\ub294 \uc774\ub984 \ud558\ub098\uc758 \ub4a4\uc5d0 \uc5b4\ub5a4 \uc77c\uc774 \uc788\ub294\uc9c0 \ucc9c\ucc9c\ud788 \ub530\ub77c\uac00 \ubcf4\uc790. IP \uc8fc\uc18c\ub294 \uc778\ud130\ub137\uc5d0\uc11c \ub370\uc774\ud130\ub97c \uc8fc\uace0\ubc1b\ub294 \ub370 \ud544\uc694\ud55c \uc8fc\uc18c\ub2e4. \ucef4\ud4e8\ud130\ub294 \uc774\ub7f0 \uac12\uc744 \ub2e4\ub8e8\uc9c0\ub9cc \uc0ac\ub78c\uc774 \ubc29\ubb38\ud558\uace0 \uc2f6\uc740 \uc0ac\uc774\ud2b8\ub9c8\ub2e4 \uae34 \uc22b\uc790\ub098 \uae30\ud638\ub97c \uc678\uc6b0\ub294 \uac83\uc740 \ubd88\ud3b8\ud558\ub2e4. \uc8fc\uc18c\uac00 \ubc14\ub014 \ub54c\ub9c8\ub2e4 \ub2e4\uc2dc \uae30\uc5b5\ud574\uc57c \ud55c\ub2e4\uba74 \ub354 \ubc88\uac70\ub86d\ub2e4. \ub3c4\uba54\uc778 \uc774\ub984\uc740 \uc774 \ubb38\uc81c\ub97c \uc904\uc5ec \uc900\ub2e4. \uc0ac\ub78c\uc740 \uc775\uc219\ud55c \uc774\ub984\uc744 \uc0ac\uc6a9\ud558\uace0 \uae30\uacc4\ub294 \uc5f0\uacb0\ub41c \uc8fc\uc18c \uc815\ubcf4\ub97c \ucc3e\uc544 \ud1b5\uc2e0\ud560 \uc218 \uc788\ub2e4. \uc774\ub984\uc774 \uace7\ubc14\ub85c \uc6f9\ud398\uc774\uc9c0\uc758 \ub0b4\uc6a9\uc744 \ub2f4\uace0 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub514\ub85c \ucc3e\uc544\uac08\uc9c0\uc5d0 \uad00\ud55c \uc815\ubcf4\ub97c \uc5bb\ub294 \uc785\uad6c\ub77c\uace0 \uc0dd\uac01\ud558\uba74 \ub41c\ub2e4. DNS\ub97c \uc804\ud654\ubc88\ud638\ubd80\uc5d0 \ube44\uc720\ud558\uba74 \uccab \uc774\ud574\uc5d0\ub294 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \uc774\ub984\uc744 \ubcf4\uace0 \ud544\uc694\ud55c \uc8fc\uc18c\ub97c \uc5bb\uae30 \ub54c\ubb38\uc774\ub2e4. \ud558\uc9c0\ub9cc \uc804 \uc138\uacc4\uc758 \ubaa8\ub4e0 \uc815\ubcf4\uac00 \ud55c \uad8c\uc758 \ucc45\ucc98\ub7fc \ud55c \ucef4\ud4e8\ud130\uc5d0\ub9cc \ub4e4\uc5b4 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. DNS\ub294 \uacc4\uce35\uc801\uc73c\ub85c \ub098\ub25c \ubd84\uc0b0 \uccb4\uacc4\ub2e4. \uc5ec\ub7ec \uc11c\ubc84\uac00 \uac01\uc790\uc758 \uc5ed\ud560\uc744 \ub9e1\uc544 \uc774\ub984\uacfc \uad00\ub828\ub41c \uc815\ubcf4\ub97c \uc81c\uacf5\ud55c\ub2e4. \ub2e4\ub978 \uc885\ub958\uc758 \uc815\ubcf4\ub3c4 \ub2e4\ub8e8\uc9c0\ub9cc, \uc5ec\uae30\uc11c\ub294 \uc0ac\uc774\ud2b8\uc758 \uc774\ub984\uc73c\ub85c \uc811\uc18d \uc8fc\uc18c\ub97c \ucc3e\ub294 \uae30\ub2a5\uc744 \uc911\uc2ec\uc73c\ub85c \ubcf4\uba74 \ucda9\ubd84\ud558\ub2e4. \uc804\ud654\ubc88\ud638\ubd80\ub77c\ub294 \ube44\uc720\ub294 \ucc3e\ub294 \ud589\uc704\ub97c \uc124\uba85\ud560 \ubfd0 \uc2e4\uc81c \uad6c\uc870 \uc804\uccb4\ub97c \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub3c4\uba54\uc778\uc740 \uc810\uc73c\ub85c \ub098\ub25c \ubd80\ubd84\ub4e4\ub85c \uad6c\uc131\ub41c\ub2e4. \uc608\ub97c \ub4e4\uc5b4 knowledgewalk.net\uc5d0\uc11c\ub294 \uc624\ub978\ucabd\uc758 net\uc774 \ucd5c\uc0c1\uc704 \ub3c4\uba54\uc778\uc774\ub2e4. \uadf8 \uc55e\uc758 \uc774\ub984\uacfc \uacb0\ud569\ud574 \uc6b0\ub9ac\uac00 \uc774\uc6a9\ud558\ub294 \ub3c4\uba54\uc778\uc774 \ub41c\ub2e4. \ub354 \uc55e\uc5d0 \ub2e4\ub978 \ubd80\ubd84\uc744 \ubd99\uc5ec \ud558\uc704 \ub3c4\uba54\uc778\uc744 \ub9cc\ub4e4 \uc218\ub3c4 \uc788\ub2e4. \uc624\ub978\ucabd\uc5d0\uc11c \uc67c\ucabd\uc73c\ub85c \ubc94\uc704\ub97c \uc881\ud600 \ubcf8\ub2e4\uace0 \uc0dd\uac01\ud558\uba74 \uad6c\uc870\uac00 \uc870\uae08 \ud3b8\ud574\uc9c4\ub2e4. \ub2e4\ub9cc net\uc774\ub77c\ub294 \ub05d\ubd80\ubd84\uc774 \uc788\ub2e4\uace0 \uadf8 \uc0ac\uc774\ud2b8\uac00 \ud2b9\uc815\ud55c \ud488\uc9c8\uc774\ub098 \ubaa9\uc801\uc744 \ubcf4\uc99d\ubc1b\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774\ub984\uc744 \uad00\ub9ac\ud558\ub294 \uccb4\uacc4\uc640 \uc0ac\uc774\ud2b8\uc5d0 \uc2e4\ub9b0 \ub0b4\uc6a9\uc758 \uc2e0\ub8b0\uc131\uc740 \ubcc4\ub3c4\uc758 \ubb38\uc81c\ub2e4. \ube0c\ub77c\uc6b0\uc800\uc5d0 \uc0ac\uc774\ud2b8 \uc774\ub984\uc744 \uc785\ub825\ud588\uc744 \ub54c \uc8fc\uc18c \uc815\ubcf4\ub97c \uc774\ubbf8 \uc54c\uace0 \uc788\ub2e4\uba74 \uc800\uc7a5\ud574 \ub454 \uacb0\uacfc\ub97c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4. \ubaa8\ub978\ub2e4\uba74 DNS \uc870\ud68c\ub97c \ud1b5\ud574 \ud544\uc694\ud55c \uc815\ubcf4\ub97c \uad6c\ud55c\ub2e4. \uc774\ub984\uacfc \uc8fc\uc18c\uc758 \uc5f0\uacb0\uc744 \ucc3e\uc740 \ub4a4\uc5d0\uc57c \uadf8 \uc8fc\uc18c\uc758 \uc11c\ubc84\uc640 \ub0b4\uc6a9\uc744 \uc8fc\uace0\ubc1b\ub294 \ub2e4\uc74c \ub2e8\uacc4\ub85c \uc774\uc5b4\uc9c4\ub2e4. \uc6b0\ub9ac\ub294 \uc774 \uacfc\uc815 \ub300\ubd80\ubd84\uc744 \ubcf4\uc9c0 \uc54a\ub294\ub2e4. \ud654\uba74\uc5d0\ub294 \uc8fc\uc18c \uc785\ub825\uacfc \ud398\uc774\uc9c0 \ud45c\uc2dc\ub9cc \uc774\uc5b4\uc838 \ubcf4\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \uadf8\ub7ec\ub098 \uc774\ub984\uc744 \ucc3e\ub294 \uc77c\uacfc \uc2e4\uc81c \ud398\uc774\uc9c0\ub97c \ubc1b\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \uac04\ud310\uc758 \uc8fc\uc18c\ub97c \uc54c\uc544\ub0b4\ub294 \uac83\uacfc \uac00\uac8c \uc548\uc73c\ub85c \ub4e4\uc5b4\uac00\ub294 \uac83\uc744 \uad6c\ubd84\ud558\uba74 \uc774\ud574\ud558\uae30 \uc27d\ub2e4. \uc6f9\uc0ac\uc774\ud2b8\uc758 \ud30c\uc77c\uc744 \ub2e4\ub978 \uc11c\ubc84\ub85c \uc62e\uaca8\ub3c4 \ub3c4\uba54\uc778 \uc774\ub984\uc744 \uacc4\uc18d \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4. \uc774\ub984\uacfc \uc5f0\uacb0\ub418\ub294 \uc8fc\uc18c \uc815\ubcf4\ub97c \uc0c8 \ud658\uacbd\uc5d0 \ub9de\ucd94\ub294 \ubc29\uc2dd\uc774\ub2e4. \ubc29\ubb38\uc790\ub294 \uc775\uc219\ud55c \uc774\ub984\uc744 \uc785\ub825\ud558\uc9c0\ub9cc \uc2e4\uc81c \ud398\uc774\uc9c0\ub97c \uc81c\uacf5\ud558\ub294 \uc7a5\uc18c\ub294 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 DNS \uc124\uc815\ub9cc \ubc14\uafb8\uba74 \uae00\uacfc \uc0ac\uc9c4\uc774 \uc800\uc808\ub85c \ubcf5\uc0ac\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc0c8 \uc11c\ubc84\uc5d0 \uc0ac\uc774\ud2b8\ub97c \uc900\ube44\ud558\ub294 \uc791\uc5c5\uacfc \uc774\ub984\uc774 \uadf8\uacf3\uc744 \uac00\ub9ac\ud0a4\uac8c \ud558\ub294 \uc791\uc5c5\uc774 \uac01\uac01 \ud544\uc694\ud558\ub2e4. \uc774 \ucc28\uc774\ub97c \uc54c\uba74 \ub3c4\uba54\uc778\uc744 \uc0c0\ub2e4\ub294 \ub9d0\uacfc \ud648\ud398\uc774\uc9c0\ub97c \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \ub9d0\uc774 \uc65c \uac19\uc740 \ub73b\uc774 \uc544\ub2cc\uc9c0\ub3c4 \ubcf4\uc778\ub2e4. DNS \uc815\ubcf4\ub294 \ub9e4\ubc88 \ubaa8\ub4e0 \ub2e8\uacc4\ub97c \uc0c8\ub85c \uc870\ud68c\ud558\uc9c0 \uc54a\ub3c4\ub85d \uc77c\uc815 \uc2dc\uac04 \uc800\uc7a5\ub418\uae30\ub3c4 \ud55c\ub2e4. \uc774\ub97c \uce90\uc2dc\ub77c\uace0 \ud55c\ub2e4. \uc8fc\uc18c\ub97c \ubc14\uafbc \ub4a4\uc5d0\ub3c4 \uc5b4\ub5a4 \uacf3\uc5d0\uc11c\ub294 \uc774\uc804\uc5d0 \uc800\uc7a5\ud574 \ub454 \ub2f5\uc744 \uc7a0\uc2dc \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4. \uadf8\ub798\uc11c \uc0ac\ub78c\ub9c8\ub2e4 \uc0c8 \uc5f0\uacb0\uc744 \ud655\uc778\ud558\ub294 \uc2dc\uc810\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc774\ub97c \uc804 \uc138\uacc4\uc758 \ubaa8\ub4e0 DNS \uc11c\ubc84\uac00 \ud55c\uaebc\ubc88\uc5d0 \uac19\uc740 \ud30c\uc77c\uc744 \ub0b4\ub824\ubc1b\ub294 \uacfc\uc815\uc73c\ub85c \uc0c1\uc0c1\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc800\uc7a5\ub41c \uacb0\uacfc\uc758 \uc720\uc9c0 \uc2dc\uac04\uacfc \uc870\ud68c \uacbd\ub85c\uac00 \uc601\ud5a5\uc744 \uc900\ub2e4. \ub610\ud55c \uc608\uc804 \ud654\uba74\uc774 \ubcf4\uc774\ub294 \uc6d0\uc778\uc740 \uc6f9\ud398\uc774\uc9c0 \uc790\uccb4\uc758 \uc784\uc2dc \uc800\uc7a5 \ub4f1 \ub2e4\ub978 \ub370 \uc788\uc744 \uc218\ub3c4 \uc788\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \ud604\uc0c1 \ud558\ub098\uac00 \uc6d0\uc778 \ud558\ub098\ub97c \ubc14\ub85c \uc54c\ub824 \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. DNS\uac00 \uc8fc\uc18c\ub97c \uc54c\ub824 \uc8fc\uc5c8\ub2e4\uace0 \uadf8 \uc0ac\uc774\ud2b8\uac00 \ud56d\uc0c1 \uc815\uc0c1\uc801\uc73c\ub85c \uc6b4\uc601\ub41c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc8fc\uc18c\ub97c \ucc3e\uc740 \ub4a4\uc5d0\ub3c4 \uc11c\ubc84\uac00 \uc751\ub2f5\ud574\uc57c \ud558\uace0 \ud544\uc694\ud55c \ud30c\uc77c\uc774 \uc788\uc5b4\uc57c \ud55c\ub2e4. \uc2e4\uc81c \uc11c\ube44\uc2a4\ub97c \uc774\ub8e8\ub294 \uc5ec\ub7ec \uc870\uac74 \uac00\uc6b4\ub370 \uc774\ub984\uc744 \uc5f0\uacb0\ud558\ub294 \uc5ed\ud560\uc774 \ub530\ub85c \uc788\ub294 \uac83\uc774\ub2e4. \ubc18\ub300\ub85c \ub3c4\uba54\uc778 \uc774\ub984\uc744 \uc774\uc6a9\ud560 \uad8c\ub9ac\ub97c \uc720\uc9c0\ud558\ub294 \uc77c\ub3c4 \ud544\uc694\ud558\ub2e4. MDN\uc740 \ud754\ud788 \ub3c4\uba54\uc778\uc744 \uc0b0\ub2e4\uace0 \ub9d0\ud558\uc9c0\ub9cc, \uc2e4\uc81c\ub85c\ub294 \uc77c\uc815 \uae30\uac04 \uc0ac\uc6a9\ud558\ub3c4\ub85d \ub4f1\ub85d\ud558\uace0 \uac31\uc2e0\ud558\ub294 \uac83\uc774\ub77c\uace0 \uc124\uba85\ud55c\ub2e4. \uc774\ub984\uc744 \uae30\uc5b5\ud558\ub294 \ubc29\ubb38\uc790\uc640 \uadf8 \uc774\ub984\uc744 \uacc4\uc18d \uc0ac\uc6a9\ud560 \uc218 \uc788\uac8c \uad00\ub9ac\ud558\ub294 \uc6b4\uc601\uc790\uc758 \uc77c\uc774 \uc774\uc5b4\uc9c4\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uc8fc\uc18c \uce74\ub4dc\ub97c \ubcf4\uace0 \uc7a5\uc18c\ub97c \ucc3e\ub294 \ubd84\uc704\uae30\ub97c \ud45c\ud604\ud588\ub2e4. \uc2e4\uc81c DNS \uc11c\ubc84\uc758 \uad6c\uc870\ub098 \ud504\ub85c\uadf8\ub7a8 \ud654\uba74\uc744 \ubcf4\uc5ec \uc8fc\ub294 \ub3c4\uc2dd\uc740 \uc544\ub2c8\ub2e4. \uc0ac\ub78c\uc774 \uae30\uc5b5\ud558\ub294 \uc774\ub984\uacfc \ucc3e\uc544\uac08 \uacf3\uc744 \uc5f0\uacb0\ud55c\ub2e4\ub294 \uc0dd\uac01\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc704\ud55c \uadf8\ub9bc\uc774\ub2e4. \uc6b0\ub9ac\ub294 \uc8fc\uc18c\ub85d\uc758 \uc6d0\ub9ac\ub97c \ub9e4\ubc88 \uc0dd\uac01\ud558\uc9c0 \uc54a\uc544\ub3c4 \uc0ac\ub78c\uc744 \ucc3e\uc544 \uc5f0\ub77d\ud55c\ub2e4. \uc0ac\uc774\ud2b8 \uc774\ub984\ub3c4 \ube44\uc2b7\ud558\ub2e4. \uc811\uc18d\ud558\ub294 \uc7a5\uc18c\uac00 \ubc14\ub014 \uc218 \uc788\uc5b4\ub3c4 \uc775\uc219\ud55c \uc774\ub984\uc744 \uacc4\uc18d \uc0ac\uc6a9\ud560 \uc218 \uc788\ub3c4\ub85d \uc911\uac04\uc758 \uc57d\uc18d\uc774 \uc791\ub3d9\ud55c\ub2e4. DNS\ub294 \ub208\uc5d0 \uc798 \ubcf4\uc774\uc9c0 \uc54a\uc9c0\ub9cc, \uc6f9\uc5d0\uc11c \uc6b0\ub9ac\uac00 \uc774\ub984\uc744 \uae30\uc5b5\ud558\ub294 \ubc29\uc2dd\uc744 \uac00\ub2a5\ud558\uac8c \ud55c\ub2e4."}, {"id": "email-at-sign", "title": "\uc774\uba54\uc77c \uc8fc\uc18c\uc5d0\ub294 \uc65c \uace8\ubc45\uc774\uac00 \ub4e4\uc5b4\uac08\uae4c", "summary": "\uba54\uc77c \uc8fc\uc18c\ub97c \ub9d0\ud560 \ub54c \uaf2d \ub4f1\uc7a5\ud558\ub294 @. \uc774\uba54\uc77c\uc744 \uc704\ud574 \uc0c8\ub85c \uadf8\ub9b0 \uae30\ud638\ub294 \uc544\ub2d9\ub2c8\ub2e4.", "category": "computing", "category_title": "Computing", "subcategory": "Internet", "url": "stories/email-at-sign/index.html", "image": "media/email-at-sign.jpg", "alt": "\uc774\uba54\uc77c \uc8fc\uc18c\uc5d0\ub294 \uc65c \uace8\ubc45\uc774\uac00 \ub4e4\uc5b4\uac08\uae4c \u2014 \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\uc774\uba54\uc77c \uc8fc\uc18c\uc5d0\ub294 \uc65c \uace8\ubc45\uc774\uac00 \ub4e4\uc5b4\uac08\uae4c \uc775\uc219\ud55c \uae30\ud638 \ud558\ub098\uac00 \uc0ac\ub78c\uacfc \ucef4\ud4e8\ud130\ub97c \ub098\ub204\uac8c \ub41c \uc0ac\uc5f0 \uba54\uc77c \uc8fc\uc18c\ub97c \ub9d0\ud560 \ub54c \uaf2d \ub4f1\uc7a5\ud558\ub294 @. \uc774\uba54\uc77c\uc744 \uc704\ud574 \uc0c8\ub85c \uadf8\ub9b0 \uae30\ud638\ub294 \uc544\ub2d9\ub2c8\ub2e4. Internet \ucef4\ud4e8\ud305 \uc804\ud654\ubc88\ud638\ub97c \ubd88\ub7ec\uc904 \ub54c\ub294 \uc22b\uc790\ub97c \uc774\uc5b4 \ub9d0\ud558\uba74 \ub41c\ub2e4. \uc774\uba54\uc77c \uc8fc\uc18c\ub97c \uc54c\ub824\uc904 \ub54c\ub294 \uc911\uac04\uc5d0 \uac11\uc790\uae30 \uc74c\uc2dd \uc774\ub984 \uac19\uc740 \ub9d0\uc774 \ub07c\uc5b4\ub4e0\ub2e4. \uace8\ubc45\uc774. \uc6b0\ub9ac\uac00 \uace8\ubc45\uc774\ub77c\uace0 \ubd80\ub974\ub294 @\ub294 \uba54\uc77c \uc8fc\uc18c\uc5d0\uc11c \uc544\uc8fc \uc775\uc219\ud55c \uae30\ud638\ub2e4. \uc18c\ubb38\uc790 a\ub97c \uc120 \ud558\ub098\uac00 \uac10\uc2f8\uace0 \uc788\ub294 \ubaa8\uc591\uc774\ub2e4. \ucef4\ud4e8\ud130 \ud654\uba74\uc5d0\uc11c\ub9cc \ubcf4\ub358 \uc0ac\ub78c\uc774\ub77c\uba74 \uc774\uba54\uc77c\uacfc \ud568\uaed8 \ud0dc\uc5b4\ub09c \uadf8\ub9bc\ucc98\ub7fc \ub290\ub084 \uc218\ub3c4 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uc774 \uae30\ud638\ub294 \uc774\uba54\uc77c\ubcf4\ub2e4 \ub098\uc774\uac00 \ub9ce\ub2e4. \ub204\uad70\uac00 \uc0c8\ub85c \ub514\uc790\uc778\ud55c \uc791\uc740 \uc778\ud130\ub137 \ub85c\uace0\uac00 \uc544\ub2c8\uc5c8\ub2e4. \ud1b0\ub9b0\uc2a8\uc774 \uc4f0\ub358 \ubaa8\ub378 33 \ud154\ub808\ud0c0\uc774\ud504\uc758 \ud0a4\ubcf4\ub4dc\uc5d0\ub294 \uc774\ubbf8 @\uac00 \uc788\uc5c8\ub2e4. \uc778\ud130\ub137 \uba85\uc608\uc758 \uc804\ub2f9\uc758 \uc5f0\ud601\uc740 \uadf8\uac00 \uc774 \uae30\uacc4\uc758 \ubb38\uc7a5\ubd80\ud638 \ud0a4 \uac00\uc6b4\ub370\uc11c @\ub97c \uace8\ub790\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc0c8\ub85c\uc6b4 \ud1b5\uc2e0 \ubc29\ubc95\uc744 \ub9cc\ub4e4\uba74\uc11c \ubaa8\ub4e0 \ud45c\uc2dc\uae4c\uc9c0 \uc0c8\ub85c \uadf8\ub9b4 \ud544\uc694\ub294 \uc5c6\uc5c8\ub358 \uac83\uc774\ub2e4. 1971\ub144, \uc11c\ub85c \ub2e4\ub978 \ucef4\ud4e8\ud130 \uc0ac\uc774\uc5d0\uc11c \uc804\uc790\uc6b0\ud3b8\uc744 \ubcf4\ub0b4\ub294 \uc77c\uc744 \uac1c\ubc1c\ud558\ub358 \ub808\uc774 \ud1b0\ub9b0\uc2a8\uc740 \uc8fc\uc18c \uc548\uc5d0\uc11c \uc0ac\ub78c\uc758 \uc774\ub984\uacfc \ucef4\ud4e8\ud130\uc758 \uc774\ub984\uc744 \uad6c\ubd84\ud560 \ud45c\uc2dc\uac00 \ud544\uc694\ud588\ub2e4. \uadf8\uac00 \uace0\ub978 \uac83\uc774 @\uc600\ub2e4. \ud0a4\ubcf4\ub4dc\uc5d0 \uc774\ubbf8 \uc788\uc5c8\uace0, \uc774\ub984\uacfc \uae30\uacc4\uc758 \uc704\uce58\ub97c \ub098\ub204\ub294 \ub370 \uc54c\ub9de\uc558\ub2e4. \uc601\uc5b4\uc758 at\uc774 \uc8fc\ub294 \ub73b\ub3c4 \uc798 \uc5b4\uc6b8\ub838\ub2e4. \uc5b4\ub290 \ucef4\ud4e8\ud130\uc5d0 \uc788\ub294 \ub204\uad6c\ub77c\ub294 \uad00\uacc4\ub97c \ud45c\ud604\ud560 \uc218 \uc788\uc5c8\uae30 \ub54c\ubb38\uc774\ub2e4. \ubcf5\uc7a1\ud55c \uc0c8 \uae30\ud638\ub97c \ub9cc\ub4e4\uc9c0 \uc54a\uace0 \uc788\ub294 \uac83\uc744 \uace8\ub790\ub2e4\ub294 \uc810\uc774 \uc7ac\ubbf8\uc788\ub2e4. \uc9c0\uae08\uc740 \uc778\ud130\ub137\uc744 \ub300\ud45c\ud558\ub294 \uac83\ucc98\ub7fc \ubcf4\uc774\ub294 \ud45c\uc2dc\ub3c4 \ucc98\uc74c\uc5d0\ub294 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\uae30 \uc704\ud55c \uc791\uc740 \uc120\ud0dd\uc774\uc5c8\ub2e4. \uc544\uc8fc \ub2e8\uc21c\ud55c \uc608\ub85c user@example.org\ub77c\ub294 \uc8fc\uc18c\ub97c \uc0dd\uac01\ud574 \ubcf4\uc790. @ \uc55e\ucabd\uc740 \uba54\uc77c\uc744 \ubc1b\uc744 \uacc4\uc815\uc5d0 \ud574\ub2f9\ud558\uace0, \ub4a4\ucabd\uc740 \uba54\uc77c \uc2dc\uc2a4\ud15c\uc758 \ub3c4\uba54\uc778\uc5d0 \ud574\ub2f9\ud55c\ub2e4. \uc0c1\uc138\ud55c \uae30\uc220\uc740 \ub354 \ubcf5\uc7a1\ud558\uc9c0\ub9cc, \uc8fc\uc18c\ub97c \uc77d\ub294 \uccab\uac78\uc74c\uc73c\ub85c\ub294 \uc774 \uad6c\ubd84\uc774\uba74 \ucda9\ubd84\ud558\ub2e4. \uadf8\ub807\ub2e4\uace0 @ \ub4a4\uc5d0 \uc2e4\uc81c \uc0ac\ubb34\uc2e4\uc774\ub098 \uac70\ub9ac \uc8fc\uc18c\uac00 \ub4e4\uc5b4 \uc788\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc6b0\ub9ac\uac00 \uc6f9\uc0ac\uc774\ud2b8 \uc774\ub984\uc73c\ub85c \uc775\uc219\ud558\uac8c \ubcf4\ub294 \uac83\uacfc \uac19\uc740 \uc885\ub958\uc758 \uc774\ub984\uc774\ub2e4. \uc6b0\ud3b8\ubc88\ud638\ub97c \uc801\ub4ef \ud604\uc2e4\uc758 \uc704\uce58\ub97c \uadf8\ub300\ub85c \uc368 \ub123\ub294 \ubc29\uc2dd\uc740 \uc544\ub2c8\ub2e4. \ucc98\uc74c\uc5d0\ub294 \ud55c \ucef4\ud4e8\ud130\uc640 \ub2e4\ub978 \ucef4\ud4e8\ud130 \uc0ac\uc774\ub97c \uad6c\ubd84\ud558\ub294 \uc120\ud0dd\uc774\uc5c8\uc9c0\ub9cc, \uc624\ub298\uc758 \uba54\uc77c\uc740 \ud6e8\uc52c \ud070 \uc2dc\uc2a4\ud15c \uc18d\uc5d0\uc11c \uc6c0\uc9c1\uc778\ub2e4. \uadf8\ub7fc\uc5d0\ub3c4 \uc774 \uc791\uc740 \ud45c\uc2dc\uac00 \uc8fc\uc18c\uc758 \ub450 \ubd80\ubd84\uc744 \ub098\ub204\ub294 \uc5ed\ud560\uc740 \uc54c\uc544\ubcf4\uae30 \uc27d\uac8c \ub0a8\uc544 \uc788\ub2e4. \ubb3c\ub860 \uc774\uba54\uc77c \uc8fc\uc18c\uc758 \uc138\ubd80 \uaddc\uce59\uae4c\uc9c0 \ubaa8\ub450 \uc774 \ud55c \uc904\ub85c \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc5ec\uae30\uc11c\ub294 \uba54\uc77c\uc744 \ubcf4\ub0b4\ub294 \uae30\uc220\ubcf4\ub2e4, \uc775\uc219\ud55c \ubaa8\uc591\uc774 \uc65c \uadf8 \uc790\ub9ac\uc5d0 \ub193\uc600\ub294\uc9c0\ub97c \ubcf4\ub294 \uac83\uc73c\ub85c \ucda9\ubd84\ud558\ub2e4. \uac19\uc740 \uc774\ub984\uc758 \uc0ac\uc6a9\uc790\uac00 \uc11c\ub85c \ub2e4\ub978 \ucef4\ud4e8\ud130\uc5d0 \uc788\uc744 \uc218 \uc788\ub2e4\uba74 \uc774\ub984 \ud558\ub098\ub9cc\uc73c\ub85c \ubc1b\ub294 \uacf3\uc744 \uad6c\ubd84\ud558\uae30 \uc5b4\ub835\ub2e4. \ub204\uad6c\uc5d0\uac8c\uc640 \uc5b4\ub290 \ucabd\uc73c\ub85c\ub97c \ud568\uaed8 \ud45c\ud604\ud574\uc57c \ud55c\ub2e4. \ud1b0\ub9b0\uc2a8\uc774 @\ub97c \uc120\ud0dd\ud55c \uc774\uc57c\uae30\ub294 \uc0c8\ub85c\uc6b4 \ud1b5\uc2e0 \uae30\ub2a5\uc744 \ub9cc\ub4e4\uba74\uc11c \uadf8 \uae30\ub2a5\uc5d0 \ub9de\ub294 \uc8fc\uc18c\uc758 \ubb38\ubc95\ub3c4 \ud544\uc694\ud588\ub2e4\ub294 \uc810\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uae30\ud638\uc758 \ubaa8\uc591\ub9cc \ub3c5\ud2b9\ud574\uc11c \uc624\ub298\uae4c\uc9c0 \ub0a8\uc740 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub450 \ubd80\ubd84 \uc0ac\uc774\uc5d0 \ub193\uc600\uc744 \ub54c \uacbd\uacc4\ub97c \uc27d\uac8c \uc54c\uc544\ubcfc \uc218 \uc788\ub2e4\ub294 \uc5ed\ud560\uc774 \uc788\uc5c8\ub2e4. \uc774\ubbf8 \uc788\ub358 \ubb38\uc7a5\ubd80\ud638\uac00 \uc0c8\ub85c\uc6b4 \ub9e5\ub77d\uc5d0\uc11c \uc4f0\uc774\uba74\uc11c \ub110\ub9ac \uc54c\ub824\uc9c4 \uac83\uc774\ub2e4. \uc774\ub984\uc758 \uc720\ub798\ub97c \uc77d\ub294 \uc77c\ub3c4 \uc0ac\uc6a9\uc790\uac00 \uc2e4\uc81c\ub85c \ud480\uc5b4\uc57c \ud588\ub358 \ubb38\uc81c\ub97c \uc0b4\ud53c\uba74 \ub354 \uad6c\uccb4\uc801\uc778 \uc774\uc57c\uae30\uac00 \ub41c\ub2e4. \uc774\uba54\uc77c \uc8fc\uc18c \ub4a4\ucabd\uc744 \uc5b4\ub514\ub77c\uace0 \uc124\uba85\ud574\ub3c4 \uadf8\uac83\uc774 \uace7 \uc9d1\uc758 \uc704\uce58\ub098 \ud604\uc7ac \uc0ac\uc6a9\uc790\uc758 \ub3c4\uc2dc\ub97c \ub73b\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud1b5\uc2e0 \uc2dc\uc2a4\ud15c \uc548\uc5d0\uc11c \uc4f0\uc774\ub294 \uc774\ub984\uacfc \uc2e4\uc81c \uac70\ucc98\ub294 \ub2e4\ub978 \uc815\ubcf4\ub2e4. \ud3b8\uc9c0\ub97c \ubcf4\ub0b4\uba70 \ub3d9\uacfc \ud638\uc218\ub97c \uc801\ub294 \uacbd\ud5d8\uc740 \uc8fc\uc18c\uc758 \ud544\uc694\ub97c \uc774\ud574\ud558\ub294 \ube44\uc720\uc774\uc9c0\ub9cc \ubaa8\ub4e0 \uc694\uc18c\ub97c \uadf8\ub300\ub85c \ub300\uc751\uc2dc\ud0ac \uc218\ub294 \uc5c6\ub2e4. \uc774 \ucc28\uc774\ub97c \uc54c\uba74 \uc791\uc740 \uc8fc\uc18c\uc5d0 \uc9c0\ub098\uce58\uac8c \ub9ce\uc740 \ub73b\uc744 \uc77d\uc9c0 \uc54a\uac8c \ub41c\ub2e4. \uac19\uc740 \uc870\uc9c1\uc758 \uc8fc\uc18c\ub97c \uc4f4\ub2e4\uace0 \ub298 \uac19\uc740 \uac74\ubb3c \uc548\uc5d0 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\uace0, \uc8fc\uc18c \ud558\ub098\ub9cc\uc73c\ub85c \uadf8 \uc0ac\ub78c\uc774 \uc5b4\ub514\uc5d0\uc11c \uba54\uc2dc\uc9c0\ub97c \uc77d\ub294\uc9c0\ub3c4 \uc54c \uc218 \uc5c6\ub2e4. \uc8fc\uc18c\ub294 \ud544\uc694\ud55c \uc804\ub2ec \uad00\uacc4\ub97c \ud45c\ud604\ud558\uc9c0\ub9cc \uc0ac\uc6a9\uc790\uc758 \uc0dd\ud65c \uc804\uccb4\ub97c \uc124\uba85\ud558\ub294 \uc18c\uac1c\ubb38\uc740 \uc544\ub2c8\ub2e4. \ud55c\uad6d\uc5b4\uc5d0\uc11c\ub294 \uc774 \uae30\ud638\ub97c \uace8\ubc45\uc774\ub77c\uace0 \ubd80\ub978\ub2e4. \ubaa8\uc591\uc744 \ubcf4\uace0 \ubd99\uc778 \uc774\ub984\uc774\ub77c \ud55c \ubc88 \ub4e4\uc73c\uba74 \uc5b4\ub290 \ud45c\uc2dc\uc778\uc9c0 \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \uc601\uc5b4\uc5d0\uc11c\ub294 \ubcf4\ud1b5 at\uc774\ub77c\uace0 \uc77d\ub294\ub2e4. \uc8fc\uc18c\ub97c \ub9d0\ub85c \uc804\ub2ec\ud560 \ub54c \uae30\ud638\uc758 \uc815\uc2dd \uc774\ub984\ubcf4\ub2e4 \ubcc4\uba85\uc774 \ub354 \uc790\uc5f0\uc2a4\ub7ec\uc6b8 \ub54c\uac00 \uc788\ub2e4. \ub208\uc73c\ub85c \ubcf8 \ubaa8\uc591\uc744 \ub9d0\ub85c \uc62e\uae30\ub294 \ubc29\uc2dd\uc774\ub2e4. \uc791\uc740 \uae30\ud638 \ud558\ub098\ub3c4 \uc0ac\uc6a9\ud558\ub294 \uc0ac\ub78c\ub4e4\uc758 \uc5b8\uc5b4 \uc18d\uc73c\ub85c \ub4e4\uc5b4\uc624\uba74 \uc0c8\ub85c\uc6b4 \ud638\uce6d\uc744 \uc5bb\ub294\ub2e4. \uc6b0\ub9ac\ub294 \uba54\uc77c \uc8fc\uc18c\ub97c \uc4f8 \ub54c\ub9c8\ub2e4 \uc774 \ud45c\uc2dc\ub97c \uc9c0\ub098\uac00\uc9c0\ub9cc, \ub9e4\ubc88 \uadf8 \uc5ed\uc0ac\ub97c \uc0dd\uac01\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uadf8\ub7f4 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \uc798 \uc791\ub3d9\ud558\ub294 \ub3c4\uad6c\ub294 \uc0ac\uc6a9\uc790\uac00 \uc624\ub798 \uace0\ubbfc\ud558\uc9c0 \uc54a\uace0 \uc9c0\ub098\uac08 \uc218 \uc788\uac8c \ud574 \uc900\ub2e4. \ub2e4\uc74c\uc5d0 \uace8\ubc45\uc774\ub97c \uc785\ub825\ud560 \ub54c \uc190\uac00\ub77d\uc744 \uc7a0\uae50 \uba48\ucdb0\ub3c4 \uc88b\uaca0\ub2e4. \uc6d0\ub798 \ub2e4\ub978 \uc77c\uc744 \ud558\ub358 \ud45c\uc2dc\uac00 \uc790\ub9ac\ub97c \uc62e\uaca8, \uc9c0\uae08\uc740 \uc804 \uc138\uacc4 \uc0ac\ub78c\ub4e4\uc758 \uc6b0\ud3b8\ud568\uc744 \ucc3e\uc544\uc8fc\ub294 \uc77c\uc744 \ub3d5\uace0 \uc788\ub2e4. \ud0a4\ubcf4\ub4dc \uc548\uc5d0\uc11c \uaf64 \uc131\uacf5\uc801\uc73c\ub85c \uc804\uc5c5\ud55c \uae30\ud638\ub2e4."}, {"id": "emoji-number-tags", "title": "\uc6c3\ub294 \uc774\ubaa8\uc9c0\uc5d0\ub3c4 \ubc88\ud638\ud45c\uac00 \uc788\ub2e4", "summary": "\ub300\ud654\ucc3d\uc758 \uc6c3\ub294 \uc5bc\uad74\uc744 \ub530\ub77c\uac00\uba74 \uadf8\ub9bc \ub300\uc2e0 \uc22b\uc790\uc640 \uc774\ub984\uc774 \ub098\ub780\ud788 \uc801\ud78c \ubaa9\ub85d\uc744 \ub9cc\ub098\uac8c \ub429\ub2c8\ub2e4.", "category": "computing", "category_title": "Computing", "subcategory": "Software", "url": "stories/emoji-number-tags/index.html", "image": "media/emoji-number-tags.jpg", "alt": "\uc6c3\ub294 \uc5bc\uad74\uacfc \uc5c4\uc9c0\uc190 \uc544\uc774\ucf58, \ube48 \ud45c\uc9c0\ub97c \ud568\uaed8 \ub193\uc740 AI \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\uc6c3\ub294 \uc774\ubaa8\uc9c0\uc5d0\ub3c4 \ubc88\ud638\ud45c\uac00 \uc788\ub2e4 \uc791\uc740 \uc5bc\uad74 \uadf8\ub9bc \ub4a4\uc5d0 \ub193\uc778 \ubb38\uc790 \ubaa9\ub85d \ub300\ud654\ucc3d\uc758 \uc6c3\ub294 \uc5bc\uad74\uc744 \ub530\ub77c\uac00\uba74 \uadf8\ub9bc \ub300\uc2e0 \uc22b\uc790\uc640 \uc774\ub984\uc774 \ub098\ub780\ud788 \uc801\ud78c \ubaa9\ub85d\uc744 \ub9cc\ub098\uac8c \ub429\ub2c8\ub2e4. Software \ucef4\ud4e8\ud305 \uba54\uc2dc\uc9c0 \ub05d\uc5d0 \uc6c3\ub294 \uc5bc\uad74 \ud558\ub098\ub97c \ubd99\uc778\ub2e4. \ub9d0\ub85c \uc4f0\uba74 \uc870\uae08 \ub531\ub531\ud560 \uac83 \uac19\uc740 \ubb38\uc7a5\uc774, \uc791\uc740 \ud45c\uc815 \ud558\ub098\ub85c \ubd80\ub4dc\ub7ec\uc6cc\uc9c4\ub2e4. \ud654\uba74\uc5d0\uc11c\ub294 \uadf8\ub9bc\uc774\uc9c0\ub9cc \uae00 \uc0ac\uc774\uc5d0 \uc790\uc5f0\uc2a4\ub7fd\uac8c \ub4e4\uc5b4\uac04\ub2e4. \uadf8 \uc5bc\uad74\uc744 \uc815\ub9ac\ud55c \uacf5\uc2dd \uc790\ub8cc\ub97c \uc5f4\uba74 \uc608\uc0c1\uacfc \ub2e4\ub978 \ubaa8\uc2b5\uc774 \ub098\uc628\ub2e4. \uc608\uc05c \uc2a4\ud2f0\ucee4 \ubaa8\uc74c\ubcf4\ub2e4 \uc22b\uc790\uc640 \uc774\ub984\uc774 \uc774\uc5b4\uc9c4 \ubaa9\ub85d\uc5d0 \uac00\uae5d\ub2e4. \uc720\ub2c8\ucf54\ub4dc\uac00 \uacf5\uac1c\ud55c \uc774\ubaa8\uc9c0 \uc2dc\ud5d8 \uc790\ub8cc\uc5d0\ub294 \ud45c\uc815\ub9c8\ub2e4 \ucf54\ub4dc\uc640 \uc124\uba85\uc774 \ubd99\uc5b4 \uc788\ub2e4. \uc720\ub2c8\ucf54\ub4dc\uc758 \uc774\ubaa8\uc9c0 16.0 \uc2dc\ud5d8 \uc790\ub8cc\uc5d0\uc11c \ud06c\uac8c \uc6c3\ub294 \uc5bc\uad74 \ud558\ub098\ub294 \u20181F600\u2019\uc774\ub77c\ub294 \ucf54\ub4dc\ub85c \uc801\ud600 \uc788\ub2e4. \ub4a4\uc5d0\ub294 \ud65c\uc9dd \uc6c3\ub294 \uc5bc\uad74\uc774\ub77c\ub294 \ub73b\uc758 \uc601\uc5b4 \uc774\ub984\uc774 \ub530\ub77c\uc628\ub2e4. \uc774 \uc22b\uc790\ub97c \uc678\uc6cc\uc11c \uba54\uc2dc\uc9c0\ub97c \uc4f8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc6b0\ub9ac\uac00 \uadf8\ub9bc\uc744 \uace0\ub974\uba74, \uadf8 \ub4a4\uc5d0\uc11c\ub294 \uc5b4\ub5a4 \ubb38\uc790\ub97c \uace0\ub978 \uac83\uc778\uc9c0 \uad6c\ubd84\ud560 \uc218 \uc788\ub294 \uae30\uc900\uc774 \ud544\uc694\ud558\ub2e4\ub294 \uc815\ub3c4\ub85c \ubcf4\uba74 \ub41c\ub2e4. \ud45c\uc815\uc774 \ube44\uc2b7\ud558\ub2e4\uace0 \ubaa8\ub450 \uac19\uc740 \ud56d\ubaa9\ub3c4 \uc544\ub2c8\ub2e4. \uc6c3\ub294 \uc5bc\uad74, \ub208\uae4c\uc9c0 \uc6c3\ub294 \uc5bc\uad74, \uc6c3\ub2e4\uac00 \ub208\ubb3c\uc774 \ub098\ub294 \uc5bc\uad74\uc774 \uac01\uac01\uc758 \uc774\ub984\uc73c\ub85c \ub098\ub25c\ub2e4. \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc791\uc740 \ud45c\uc815 \ucc28\uc774\uc9c0\ub9cc \ubaa9\ub85d\uc5d0\uc11c\ub294 \uad6c\ubd84\ud574\uc57c \ud560 \ucc28\uc774\ub2e4. \ubaa8\ub4e0 \uc774\ubaa8\uc9c0\uac00 \ucf54\ub4dc \ud558\ub098\ub85c\ub9cc \uc774\ub8e8\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uac19\uc740 \uc790\ub8cc\uc5d0\ub294 \uc5c4\uc9c0\ub97c \uc62c\ub9b0 \uc190\uc758 \ucf54\ub4dc \ub4a4\uc5d0 \ud53c\ubd80\uc0c9\uc744 \ub098\ud0c0\ub0b4\ub294 \ucf54\ub4dc\uac00 \ub354\ud574\uc9c4 \ud56d\ubaa9\ub3c4 \ub098\uc628\ub2e4. \ud654\uba74\uc5d0\uc11c\ub294 \ud558\ub098\uc758 \uc190\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc, \uc790\ub8cc\uc5d0\ub294 \ub458 \uc774\uc0c1\uc758 \ucf54\ub4dc\ub97c \uc774\uc5b4 \uc801\uc744 \uc218 \uc788\ub294 \uac83\uc774\ub2e4. \uacf5\uc2dd \ud30c\uc77c\ub3c4 \ud56d\ubaa9\uc758 \ucf54\ub4dc\uac00 \ud558\ub098 \uc774\uc0c1\uc77c \uc218 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uadf8\ub7ec\ub2c8 \ub208\uc55e\uc758 \uadf8\ub9bc \uac1c\uc218\uc640 \ub4a4\uc5d0 \uc801\ud78c \ucf54\ub4dc \uac1c\uc218\uac00 \ud56d\uc0c1 \uac19\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc791\uc740 \uadf8\ub9bc \ud558\ub098\ub97c \ud45c\uc2dc\ud558\uae30 \uc704\ud574 \uc5b4\ub5a4 \uc815\ubcf4\ub97c \ud568\uaed8 \ub450\ub294\uc9c0 \uc5ff\ubcf4\ub294 \ub300\ubaa9\uc774\ub2e4. \ud734\ub300\uc804\ud654\uc5d0\uc11c \uc5bc\uad74\uc744 \ub204\ub974\uba74 \uc6b0\ub9ac\ub294 \uadf8\ub9bc\uc744 \uc120\ud0dd\ud588\ub2e4\uace0 \ub290\ub080\ub2e4. \uacf5\uc2dd \ubaa9\ub85d\uc740 \uc5b4\ub5a4 \ud56d\ubaa9\uc744 \uc120\ud0dd\ud588\ub294\uc9c0 \uad6c\ubcc4\ud558\ub294 \ucf54\ub4dc\uc640 \uc774\ub984\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ub204\ub974\ub294 \ud654\uba74\uacfc \uc804\ub2ec\ud558\ub294 \uc815\ubcf4\uac00 \uc11c\ub85c \ub2e4\ub978 \uce35\uc5d0 \uc788\ub294 \uc148\uc774\ub2e4. \uac19\uc740 \ud45c\uc2dc\ub97c \uc54c\uc544\ubcf4\ub824\uba74 \ubaa8\uc591\uc5d0\ub9cc \uc758\uc874\ud558\uc9c0 \uc54a\ub294 \uad6c\ubd84 \uae30\uc900\uc774 \ud544\uc694\ud558\ub2e4. 1F600\uc774\ub77c\ub294 \ud45c\uae30\ub294 \uadf8 \uae30\uc900\uc744 \uc0ac\ub78c\uc774 \uc77d\uc744 \uc218 \uc788\uac8c \uc801\uc740 \uc608\ub2e4. \uc2ed\uc721\uc9c4\uc218 \ud45c\uae30\ubc95\uc744 \uacf5\ubd80\ud574\uc57c\ub9cc \uc774\ubaa8\uc9c0\ub97c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ucc45\uc5d0 \ubd99\uc740 \ub3c4\uc11c \ubc88\ud638\ucc98\ub7fc \ud56d\ubaa9\uc744 \uad6c\ubcc4\ud558\ub294 \ud45c\uc9c0\uac00 \uc788\ub2e4\uace0 \uc0dd\uac01\ud558\uba74 \ucda9\ubd84\ud558\ub2e4. \ub2e4\ub9cc \ucc45\uc758 \ud45c\uc9c0 \uadf8\ub9bc\uacfc \uad00\ub9ac \ubc88\ud638\uac00 \uac19\uc740 \uac83\uc774 \uc544\ub2c8\ub4ef \ucf54\ub4dc\uc640 \ub208\uc5d0 \ubcf4\uc774\ub294 \uc5bc\uad74\ub3c4 \uad6c\ubd84\ud560 \uc218 \uc788\ub2e4. \uc5c4\uc9c0\uc190 \ud45c\uc2dc \ub4a4\uc5d0 \ud53c\ubd80\uc0c9 \ucf54\ub4dc\uac00 \ubd99\ub294 \uc608\uc5d0\uc11c\ub294 \uae30\ubcf8 \ub3d9\uc791\uacfc \ucd94\uac00 \ud2b9\uc131\uc774 \ud568\uaed8 \ud45c\ud604\ub41c\ub2e4. \uc0ac\uc6a9\uc790\ub294 \ud558\ub098\uc758 \uc190\uc744 \ubcf4\uc9c0\ub9cc \uc790\ub8cc\uc5d0\ub294 \uc774\uc5b4\uc9c4 \ucf54\ub4dc\ub4e4\uc774 \ub0a8\ub294\ub2e4. \uadf8\ub9bc \ud558\ub098\uc5d0 \uc815\ubcf4 \ud558\ub098\ub77c\ub294 \uc9c1\uad00\uc774 \ub298 \ub9de\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud45c\uc2dc\ub97c \uc138\ub294 \uc77c\uacfc \uc815\ubcf4\ub97c \uc774\ub8e8\ub294 \ub2e8\uc704\ub97c \uc138\ub294 \uc77c\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uc774\ub7f0 \uc870\ud569\uc744 \uc548\ub2e4\uace0 \ubaa8\ub4e0 \uc774\ubaa8\uc9c0\uac00 \uac19\uc740 \uad6c\uc870\ub77c\uace0 \uc678\uc6b0\uc9c0\ub294 \ub9d0\uc790. \uacf5\uc2dd \uc2dc\ud5d8 \ubaa9\ub85d\uc740 \ucf54\ub4dc \ud558\ub098\uc778 \ud56d\ubaa9\uacfc \uc5ec\ub7ec \ucf54\ub4dc\ub85c \uc774\ub8e8\uc5b4\uc9c4 \ud56d\ubaa9\uc744 \uc2e4\uc81c \uc0ac\ub840\ub85c \ubcf4\uc5ec \uc900\ub2e4. \ubcf5\uc7a1\ud55c \uc870\ud569 \uaddc\uce59\uc744 \ubaa8\ub450 \ubc30\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uba54\uc2dc\uc9c0 \uc18d \uc791\uc740 \ud45c\uc815\uc5d0\ub3c4 \ub2e8\uc21c\ud55c \uadf8\ub9bc \ud30c\uc77c \ud558\ub098\uc640 \ub2e4\ub978 \uad6c\uc870\uac00 \uc788\uc744 \uc218 \uc788\ub2e4\ub294 \uc810\ub9cc \uc54c\uc544\ub3c4 \ubcf4\uae30\uc758 \ud3ed\uc774 \ub113\uc5b4\uc9c4\ub2e4. \ubaa9\ub85d\uc758 \uc774\ub984\uc740 \uc5b4\ub290 \ud56d\ubaa9\uc744 \ub9d0\ud558\ub294\uc9c0 \uc2dd\ubcc4\ud558\ub3c4\ub85d \ub3d5\ub294\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \uc774\ubaa8\uc9c0\ub97c \ubcf4\ub0b8 \uc0ac\ub78c\uc758 \ub9c8\uc74c \uc804\uccb4\ub97c \uace0\uc815\ud574 \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc6c3\ub294 \uc5bc\uad74\uc744 \ubd99\uc600\uc5b4\ub3c4 \uc778\uc0ac\uc77c \uc218\ub3c4, \uae34\uc7a5\uc744 \ud480\ub824\ub294 \ud45c\ud604\uc77c \uc218\ub3c4 \uc788\ub2e4. \uacf5\uc2dd \ud56d\ubaa9\uc758 \uc774\ub984\uacfc \uc2e4\uc81c \ub300\ud654\uc5d0\uc11c \uc5bb\ub294 \ub258\uc559\uc2a4\ub294 \uc11c\ub85c \uad00\ub828\ub418\uc9c0\ub9cc \uac19\uc740 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub798\uc11c \ucf54\ub4dc\ub97c \uc815\ud655\ud788 \uc804\ub2ec\ud558\ub294 \uae30\uc220\uacfc \ub9d0\ub73b\uc774 \uc798 \ud1b5\ud558\ub294 \ub300\ud654\ub294 \ubcc4\uac1c\uc758 \ub178\ub825\uc774 \ud544\uc694\ud558\ub2e4. \uac19\uc740 \ud45c\uc2dc\ub97c \uc54c\uc544\ubcf4\ub294 \uacf5\ud1b5 \uae30\uc900\uc774 \uc788\uc5b4\ub3c4 \ubb38\ub9e5\uacfc \uad00\uacc4\ub294 \uc0ac\ub78c\uc5d0\uac8c \ub0a8\ub294\ub2e4. \uc791\uc740 \uc5bc\uad74\uc774 \ubb38\uc7a5\uc744 \ubd80\ub4dc\ub7fd\uac8c \ub9cc\ub4dc\ub294 \uae4c\ub2ed\uc744 \uc0dd\uac01\ud558\uba74\uc11c\ub3c4, \uc624\ud574\uac00 \uc0dd\uacbc\uc744 \ub54c \uc22b\uc790\ud45c\ub9cc\uc73c\ub85c \uc0c1\ub300\uc758 \uc758\ub3c4\ub97c \ud310\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4\ub294 \uc810\uc744 \uae30\uc5b5\ud560 \uc218 \uc788\ub2e4. \uc774 \uae00\uc740 \uc774\ubaa8\uc9c0 16.0\uc758 \uc2dc\ud5d8 \uc790\ub8cc\ub97c \uadfc\uac70\ub85c \ud55c\ub2e4. \ubc84\uc804\uc774 \ubd99\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ubaa9\ub85d\uc774 \uc5b8\uc81c\ub098 \ud55c \ubc88 \uc815\ud574\uc9c4 \uc0c1\ud0dc\ub85c \uba48\ucd94\uc5b4 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ub2e4\ub978 \uc2dc\uc810\uc758 \uc790\ub8cc\ub098 \ud658\uacbd\uc744 \ube44\uad50\ud560 \ub54c\uc5d0\ub294 \uc5b4\ub5a4 \ubaa9\ub85d\uc744 \uae30\uc900\uc73c\ub85c \uc0bc\uc558\ub294\uc9c0 \uc54c\uc544\uc57c \ud55c\ub2e4. \uadf8 \uc22b\uc790\ub97c \uace7 \uac1c\uc778 \uae30\uae30\uc758 \uc9c0\uc6d0 \uc0c1\ud0dc\uc640 \uac19\ub2e4\uace0 \ubcfc \uc218\ub294 \uc5c6\ub2e4. \uc790\ub8cc\uc758 \uc21c\uc11c\uc640 \ubb36\uc74c\ub3c4 \uad00\uc2ec\uc744 \ub048\ub2e4. \uc22b\uc790 \ud06c\uae30\ub300\ub85c\ub9cc \ub298\uc5b4\ub193\ub294 \ub300\uc2e0 \uc0ac\ub78c\ub4e4\uc774 \ud56d\ubaa9\uc744 \ucc3e\ub294 \ubd84\ub958\ub97c \uace0\ub824\ud55c \ubc30\uc5f4\uc774 \uc788\ub2e4. \uc774\ubaa8\uc9c0\uac00 \ubb38\uc790\ub85c \ucc98\ub9ac\ub418\ub294 \uccb4\uacc4\uc640 \uc190\uac00\ub77d\uc73c\ub85c \uace0\ub974\ub294 \uacbd\ud5d8\uc774 \ub9cc\ub098\ub294 \uc9c0\uc810\uc774\ub2e4. \uba54\uc2dc\uc9c0 \ud55c \uc904\uc744 \uc990\uae30\uba74\uc11c \uadf8 \ub4a4\uc758 \ubaa9\ub85d\uc744 \ud55c \ubc88 \ub4e4\uc5ec\ub2e4\ubcf4\uba74, \uac00\ubcbc\uc6b4 \ud45c\ud604\uc744 \uc704\ud574 \ud544\uc694\ud55c \uaf3c\uaf3c\ud55c \ud569\uc758\uac00 \ubcf4\uc778\ub2e4. \uc774 \uc790\ub8cc\ub294 \uc774\ubaa8\uc9c0\uac00 \ud0a4\ubcf4\ub4dc\uc5d0 \ub098\uc624\uace0 \ud654\uba74\uc5d0\uc11c \ucc98\ub9ac\ub418\ub294\uc9c0\ub97c \uc2dc\ud5d8\ud558\uae30 \uc704\ud574 \uacf5\uac1c\ub41c \ubaa9\ub85d\uc774\ub2e4. \ud45c\uc815\ubfd0 \uc544\ub2c8\ub77c \uc0ac\ub78c\uacfc \uc0ac\ubb3c \ub4f1 \uc5ec\ub7ec \ubb36\uc74c\uc73c\ub85c \ub098\ub258\uc5b4 \uc788\ub2e4. \uc790\ub8cc\uc758 \uc124\uba85\uc5d0\ub294 \ubaa9\ub85d\uc774 \ucf54\ub4dc \uc22b\uc790 \uc21c\uc11c\uac00 \uc544\ub2c8\ub77c CLDR\uc758 \uc774\ubaa8\uc9c0 \uc21c\uc11c\ub97c \ub530\ub978\ub2e4\ub294 \ub0b4\uc6a9\ub3c4 \uc788\ub2e4. \ud654\uba74\uc5d0\uc11c \uc0ac\ub78c\ub4e4\uc774 \uace0\ub974\ub294 \uc21c\uc11c\ub97c \uc0dd\uac01\ud558\uba70 \uc815\ub9ac\ud55c \ud754\uc801\uc774 \uacf5\uc2dd \ubaa9\ub85d \uc548\uc5d0\ub3c4 \uc788\ub294 \uc148\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \uba54\uc2dc\uc9c0\uc5d0 \uc6c3\ub294 \uc5bc\uad74\uc744 \ud558\ub098 \ubd99\uc778\ub2e4\uba74, \uadf8 \ub4a4\uc5d0 \ubc88\ud638\ud45c\uc640 \uc774\ub984\ud45c\uac00 \uc788\ub2e4\ub294 \uac83\ub9cc \uc7a0\uae50 \ub5a0\uc62c\ub824 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uc791\uace0 \uac00\ubcbc\uc6b4 \ud45c\uc815\uc744 \uc11c\ub85c \uad6c\ubd84\ud558\uae30 \uc704\ud574, \ubcf4\uc774\uc9c0 \uc54a\ub294 \uacf3\uc5d0\uc11c\ub294 \uaf64 \uaf3c\uaf3c\ud55c \uc815\ub9ac\uac00 \uc774\ub8e8\uc5b4\uc9c0\uace0 \uc788\ub2e4."}, {"id": "engelbart-mouse-demo", "title": "\uc791\uc740 \ub9c8\uc6b0\uc2a4\uac00 \ud568\uaed8 \ub4f1\uc7a5\ud55c \ud070 \uc2dc\uc5f0", "summary": "\ud654\uba74\uc744 \uac00\ub9ac\ud0a4\ub294 \uc791\uc740 \ub3c4\uad6c\ub294 \ud568\uaed8 \uc77c\ud558\ub294 \ucef4\ud4e8\ud130\ub97c \ubcf4\uc5ec\uc8fc\ub294 \ub354 \ud070 \uad6c\uc0c1\uc758 \uc77c\ubd80\uc600\uc2b5\ub2c8\ub2e4.", "category": "computing", "category_title": "Computing", "subcategory": "Computers", "url": "stories/engelbart-mouse-demo/index.html", "image": "media/engelbart-mouse-demo.jpg", "alt": "\uc77c\ubc18\ud654\ud55c \uc720\uc120 \ub9c8\uc6b0\uc2a4\uc640 \ud654\uc0b4\ud45c \ucee4\uc11c\uac00 \uc788\ub294 \ud654\uba74\uc758 \uc124\uba85\uc6a9 AI \uc0bd\ud654", "text": "\uc791\uc740 \ub9c8\uc6b0\uc2a4\uac00 \ud568\uaed8 \ub4f1\uc7a5\ud55c \ud070 \uc2dc\uc5f0 1968\ub144\uc758 \ucef4\ud4e8\ud130 \uc2dc\uc5f0\uc744 \uc870\uae08 \ub2e4\ub974\uac8c \ub5a0\uc62c\ub9ac\uae30 \ud654\uba74\uc744 \uac00\ub9ac\ud0a4\ub294 \uc791\uc740 \ub3c4\uad6c\ub294 \ud568\uaed8 \uc77c\ud558\ub294 \ucef4\ud4e8\ud130\ub97c \ubcf4\uc5ec\uc8fc\ub294 \ub354 \ud070 \uad6c\uc0c1\uc758 \uc77c\ubd80\uc600\uc2b5\ub2c8\ub2e4. Computers \ucef4\ud4e8\ud305 \ucef4\ud4e8\ud130 \ub9c8\uc6b0\uc2a4\ub294 \ub108\ubb34 \uc775\uc219\ud574\uc11c \ucc98\uc74c \ub4f1\uc7a5\ud588\uc744 \ub54c\ub97c \uc0c1\uc0c1\ud558\uae30 \uc5b4\ub835\ub2e4. \uc190\uc73c\ub85c \uc870\uae08 \uc6c0\uc9c1\uc774\uba74 \ud654\uba74\uc758 \ud45c\uc2dc\ub3c4 \uc6c0\uc9c1\uc778\ub2e4. \ucc45\uc0c1\uc5d0\uc11c \uc77c\uc5b4\ub098\ub294 \uc791\uc740 \ub3d9\uc791\uc774\ub2e4. \uadf8 \uc791\uc740 \ub3c4\uad6c\uc758 \uc5ed\uc0ac\uc5d0\uc11c \uc790\uc8fc \ub9cc\ub098\ub294 \uc774\ub984\uc774 \ub354\uae00\ub7ec\uc2a4 \uc5e5\uac94\ubc14\ud2b8\ub2e4. \uc778\ud130\ub137 \uba85\uc608\uc758 \uc804\ub2f9\uc740 \uadf8\uac00 \uc774\ub048 \uc5f0\uad6c\ud300\uc758 \uc2dc\uc2a4\ud15c\uc5d0 \ucef4\ud4e8\ud130 \ub9c8\uc6b0\uc2a4 \uac19\uc740 \ucd08\uae30 \ud654\uba74 \uc870\uc791 \ub3c4\uad6c\uac00 \ud3ec\ud568\ub418\uc5b4 \uc788\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud558\uc9c0\ub9cc \ub2f9\uc2dc\uc758 \uad6c\uc0c1\uc740 \ucc45\uc0c1 \uc704\uc758 \ub3c4\uad6c \ud558\ub098\uc5d0\uc11c \ub05d\ub098\uc9c0 \uc54a\uc558\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \ucef4\ud4e8\ud130\ub97c \ud1b5\ud574 \ud568\uaed8 \uc77c\ud558\ub294 \ubc29\uc2dd\uae4c\uc9c0 \ubcf4\uc5ec\uc8fc\ub824 \ud588\ub2e4. \uc5e5\uac94\ubc14\ud2b8\ub294 \ubbf8\uad6d SRI\uc758 \uc5f0\uad6c\uc18c\uc5d0\uc11c \uc0ac\ub78c\uc758 \uc9c0\uc801 \ud65c\ub3d9\uc744 \ub3d5\ub294 \uc2dc\uc2a4\ud15c\uc744 \uc5f0\uad6c\ud588\ub2e4. \uc5ec\ub7ec \uc0ac\uc6a9\uc790\uac00 \ud654\uba74 \uc55e\uc5d0\uc11c \uc815\ubcf4\ub97c \ub2e4\ub8e8\uba70 \ubb38\uc81c\ub97c \ud568\uaed8 \ud574\uacb0\ud558\ub294 \ubaa8\uc2b5\uc774 \uadf8 \uad6c\uc0c1\uc5d0 \ub4e4\uc5b4 \uc788\uc5c8\ub2e4. \uadf8\uc758 \ud300\uc774 \uac1c\ubc1c\ud55c NLS\uc5d0\ub294 \ud611\uc5c5 \uc18c\ud504\ud2b8\uc6e8\uc5b4\uc640 \ud558\uc774\ud37c\ud14d\uc2a4\ud2b8, \ucd08\uae30 \ud654\uba74 \uc778\ud130\ud398\uc774\uc2a4 \uc694\uc18c\uac00 \ud568\uaed8 \ud3ec\ud568\ub418\uc5c8\ub2e4. \ud558\uc774\ud37c\ud14d\uc2a4\ud2b8\ub294 \uc815\ubcf4\ub97c \uc5f0\uacb0\ud574 \ub530\ub77c\uac00\uac8c \ud558\ub294 \ubc29\uc2dd\uc73c\ub85c \uc774\ud574\ud558\uba74 \ub41c\ub2e4. \uc5b4\ub824\uc6b4 \uae30\uc220 \uc774\ub984\uc744 \uc804\ubd80 \uc678\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc624\ub298 \uc6b0\ub9ac\uac00 \ucef4\ud4e8\ud130\uc5d0\uc11c \ud558\ub294 \uc77c\ub3c4 \ud55c \uac00\uc9c0 \ub3d9\uc791\ub9cc\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub300\uc0c1\uc744 \uac00\ub9ac\ud0a4\uace0, \ub2e4\ub978 \uc815\ubcf4\ub85c \uc774\ub3d9\ud558\uace0, \ub2e4\ub978 \uc0ac\ub78c\uacfc \ub0b4\uc6a9\uc744 \ub098\ub208\ub2e4. \ub9c8\uc6b0\uc2a4\ub294 \uadf8\ub7f0 \ud070 \uc791\uc5c5\uc744 \ub3d5\ub294 \ud55c \ubd80\ubd84\uc774\uc5c8\ub2e4. 1968\ub144 \uc5e5\uac94\ubc14\ud2b8\uc640 \uc5f0\uad6c\ud300\uc740 \ucef4\ud4e8\ud130 \ud559\ud68c\uc5d0\uc11c \uc2dc\uc2a4\ud15c\uc744 \uc2dc\uc5f0\ud588\ub2e4. \ub4a4\uc5d0 \uc774 \ubc1c\ud45c\ub294 \u2018\ubaa8\ub4e0 \ub370\ubaa8\uc758 \uc5b4\uba38\ub2c8\u2019\ub77c\ub294 \ubcc4\uba85\uc73c\ub85c \ub110\ub9ac \uc54c\ub824\uc84c\ub2e4. \uc774\ub984\uc774 \uac70\ucc3d\ud574\uc11c \ubaa8\ub4e0 \ud604\ub300 \uae30\uc220\uc774 \uadf8\ub0a0 \uc644\uc131\ub418\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \uc0ac\ub78c\ub4e4\uc774 \ucef4\ud4e8\ud130\uc640 \uc0c1\ud638\uc791\uc6a9\ud558\ub294 \uc5ec\ub7ec \uc544\uc774\ub514\uc5b4\ub97c \uc791\ub3d9\ud558\ub294 \uc2dc\uc2a4\ud15c\uc73c\ub85c \ubcf4\uc5ec\uc8fc\uc5c8\ub2e4\ub294 \uc810\uc774\ub2e4. \uc778\ud130\ub137 \uba85\uc608\uc758 \uc804\ub2f9\uc740 \uc5e5\uac94\ubc14\ud2b8\uac00 \ub9c8\uc6b0\uc2a4\ub97c \ube44\ub86f\ud55c \uc5ec\ub7ec \ud2b9\ud5c8\ub3c4 \ubcf4\uc720\ud588\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \ub2e4\ub9cc \uadf8\uc758 \uc791\uc5c5\uc744 \uc791\uc740 \uc7a5\uce58 \ud558\ub098\uc758 \ubc1c\uba85\uc73c\ub85c\ub9cc \uc904\uc774\uba74, \ud611\uc5c5\uacfc \uc815\ubcf4 \uc5f0\uacb0\uc5d0 \uad00\ud55c \uad6c\uc0c1\uc774 \ubc30\uacbd\uc73c\ub85c \ubb3c\ub7ec\ub09c\ub2e4. \ubb38\uc11c\uc5d0\uc11c \ud2b9\uc815 \ubb38\uc7a5\uc744 \uace0\ub974\uace0 \uc2f6\uc744 \ub54c \uadf8 \uc704\uce58\ub97c \ub9d0\ub85c \uae38\uac8c \uc124\uba85\ud560 \uc218\ub3c4 \uc788\ub2e4. \uc190\uc758 \uc6c0\uc9c1\uc784\uc73c\ub85c \ud654\uba74\uc758 \ud55c \uc9c0\uc810\uc744 \uac00\ub9ac\ud0ac \uc218 \uc788\ub2e4\uba74 \ub2e4\ub978 \uae38\uc774 \uc5f4\ub9b0\ub2e4. \ub9c8\uc6b0\uc2a4\ub294 \uadf8\ub7f0 \uad00\uacc4\ub97c \uc775\uc219\ud558\uac8c \ub9cc\ub4e0 \ub3c4\uad6c\ub2e4. \ucc45\uc0c1\uc5d0\uc11c\uc758 \uc9e7\uc740 \uc774\ub3d9\uc744 \ud654\uba74\uc758 \uc704\uce58 \ubcc0\ud654\uc640 \uc5f0\uacb0\ud574 \uc0ac\ub78c\uc758 \uc758\ub3c4\ub97c \uc804\ub2ec\ud55c\ub2e4. \uadf8\ub798\uc11c \ub9c8\uc6b0\uc2a4\uc758 \uc758\ubbf8\ub97c \ub2e8\uc21c\ud788 \uc791\uc740 \uc0c1\uc790\uc758 \ud615\ud0dc\uc5d0\uc11c\ub9cc \ucc3e\uc744 \uc218\ub294 \uc5c6\ub2e4. \ud654\uba74\uc5d0 \ubb34\uc5c7\uc774 \ubcf4\uc774\uace0, \uac00\ub9ac\ud0a8 \ub4a4 \uc5b4\ub5a4 \uc791\uc5c5\uc744 \ud560 \uc218 \uc788\ub294\uc9c0\uac00 \ud568\uaed8 \uc788\uc5b4\uc57c \ud55c\ub2e4. \uc624\ub298\uc758 \uc0ac\uc6a9 \uacbd\ud5d8\uc744 \uadf8\ub300\ub85c \ucd08\uae30 \uc7a5\uce58\uc5d0 \ub300\uc785\ud558\uc9c0 \uc54a\ub354\ub77c\ub3c4, \uc785\ub825 \ub3c4\uad6c\uc640 \ud654\uba74 \ud45c\ud604\uc744 \ud55c \ud658\uacbd\uc73c\ub85c \uc124\uacc4\ud574\uc57c \ud55c\ub2e4\ub294 \uae30\ubcf8\uc801\uc778 \ubb38\uc81c\ub294 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \ud558\uc774\ud37c\ud14d\uc2a4\ud2b8\ub294 \ub0b4\uc6a9\uc744 \uc904\uc9c0\uc5b4 \ub193\ub294 \uac83 \uc678\uc5d0 \ub2e4\ub978 \uc815\ubcf4\ub85c \uc774\uc5b4\uc9c0\ub294 \uae38\uc744 \ub9c8\ub828\ud55c\ub2e4. \uc77d\ub358 \uacf3\uc5d0\uc11c \uad00\ub828\ub41c \ub2e4\ub978 \ubd80\ubd84\uc73c\ub85c \uc62e\uaca8 \uac08 \uc218 \uc788\ub2e4\uba74 \uc790\ub8cc\ub97c \ub2e4\ub8e8\ub294 \uc21c\uc11c\uac00 \ud558\ub098\ub85c \uace0\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc5e5\uac94\ubc14\ud2b8\uc758 \ud300\uc774 \ubcf4\uc5ec \uc900 \ud658\uacbd\uc5d0\uc11c \uc815\ubcf4 \uc5f0\uacb0\uacfc \ud654\uba74 \uc870\uc791\uc774 \ud568\uaed8 \uc911\uc694\ud588\ub358 \uae4c\ub2ed\uc744 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ud604\uc7ac\uc758 \uc6f9\uacfc NLS\ub97c \uac19\uc740 \uc2dc\uc2a4\ud15c\uc774\ub77c\uace0 \ub9d0\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc2dc\ub300\uc640 \uae30\uc220\uc758 \uad6c\uccb4\uc801\uc778 \uc791\ub3d9 \ubc29\uc2dd\uc740 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ub2e4\ub9cc \ud654\uba74\uc5d0\uc11c \ub300\uc0c1\uc744 \uace0\ub974\uace0 \uc5f0\uacb0\ub41c \uc815\ubcf4\ub97c \ucc3e\uc544\uac00\uba70 \uc791\uc5c5\ud55c\ub2e4\ub294 \uacbd\ud5d8\uc758 \ubb36\uc74c\uc744 \ub5a0\uc62c\ub9ac\uba74, \ub9c8\uc6b0\uc2a4\uac00 \uc65c \ub3c5\ub9bd\ub41c \uc7a5\ub09c\uac10\uc774 \uc544\ub2c8\ub77c \uc815\ubcf4 \ud658\uacbd\uc758 \ub3c4\uad6c\uc600\ub294\uc9c0 \uc54c \uc218 \uc788\ub2e4. \uc5ec\ub7ec \uc0ac\ub78c\uc774 \ud558\ub098\uc758 \ubb38\uc81c\ub97c \ub2e4\ub8f0 \ub54c\uc5d0\ub294 \uac01\uc790\uc758 \uc0dd\uac01\uc744 \uae30\ub85d\ud558\uace0 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ubcf4\uc5ec \uc904 \uc218 \uc788\uc5b4\uc57c \ud55c\ub2e4. \ubb38\uc11c\uc758 \ub0b4\uc6a9\uacfc \uc704\uce58\ub97c \uacf5\uc720\ud558\uace0 \uc218\uc815\ud560 \ub300\uc0c1\uc744 \uac00\ub9ac\ud0a4\ub294 \ud589\ub3d9\uc774 \uc774\uc5b4\uc9c4\ub2e4. \ud611\uc5c5\uc740 \uc0ac\ub78c\uc774 \ub3d9\uc2dc\uc5d0 \uc790\ub9ac\uc5d0 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \ud568\uaed8 \ubcfc \ub300\uc0c1\uacfc \uc11c\ub85c\uc758 \ud589\ub3d9\uc744 \uc774\ud574\ud560 \ubc29\ubc95\ub3c4 \ud544\uc694\ud558\ub2e4. 1968\ub144 \uc2dc\uc5f0\uc758 \uc758\ubbf8\ub294 \uc774\ub7f0 \uc544\uc774\ub514\uc5b4\ub97c \uc2e4\uc81c\ub85c \uc791\ub3d9\ud558\ub294 \ud658\uacbd\uc5d0\uc11c \ubcf4\uc5ec \uc8fc\uc5c8\ub2e4\ub294 \ub370 \uc788\ub2e4. \ubbf8\ub798\uc5d0\ub294 \uc774\ub807\uac8c \ub420 \uac83\uc774\ub77c\ub294 \ub9d0\uacfc \ub208\uc55e\uc5d0\uc11c \uc870\uc791\ud574 \ubcf4\uc774\ub294 \uc77c\uc740 \ub2e4\ub978 \uc124\ub4dd\ub825\uc744 \uac00\uc9c4\ub2e4. \uadf8\ub807\ub2e4\uace0 \uadf8\ub0a0 \ub4a4\uc758 \ubaa8\ub4e0 \ud611\uc5c5 \uae30\uc220\uc774 \uc644\uc131\ub418\uc5c8\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc5ec\ub7ec \uae30\ub2a5\uc744 \ud568\uaed8 \uc0ac\uc6a9\ud558\ub294 \uc7a5\uba74\uc774 \ud558\ub098\uc758 \uad6c\uc0c1\uc73c\ub85c \ub4dc\ub7ec\ub0ac\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \ucef4\ud4e8\ud130\uc758 \uc5ed\uc0ac\ub97c \ucc98\ub9ac \uc18d\ub3c4\uc640 \uc800\uc7a5 \uc6a9\ub7c9\uc73c\ub85c\ub9cc \uc815\ub9ac\ud558\uba74 \uc0ac\uc6a9\uc790\uc758 \ubab8\uc740 \ubc30\uacbd\uc73c\ub85c \ubb3c\ub7ec\ub09c\ub2e4. \ub9c8\uc6b0\uc2a4 \uc774\uc57c\uae30\ub294 \ubb34\uc5c7\uc744 \uc785\ub825\ud588\uace0 \uc190\uc744 \uc5b4\ub5bb\uac8c \uc6c0\uc9c1\uc600\ub294\uc9c0\ub97c \ubb3b\uac8c \ud55c\ub2e4. \uae30\uacc4\uc758 \ub2a5\ub825\uc774 \ucee4\uc838\ub3c4 \uc0ac\ub78c\uc774 \uc6d0\ud558\ub294 \uc77c\uc744 \ud45c\ud604\ud558\uae30 \uc5b4\ub835\ub2e4\uba74 \uadf8 \ub2a5\ub825\uc744 \ucda9\ubd84\ud788 \uc4f0\uae30 \uc5b4\ub835\ub2e4. \uc778\ud130\ud398\uc774\uc2a4\ub294 \uadf8 \uc0ac\uc774\ub97c \ub2e4\ub8e8\ub294 \uc120\ud0dd\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \ubb38\uc7a5\uc744 \uc120\ud0dd\ud558\uac70\ub098 \ucc3d\uc744 \uc62e\uae38 \ub54c\uc5d0\ub294 \ud589\ub3d9\uc774 \uba87 \ub2e8\uacc4\ub85c \uc774\uc5b4\uc9c0\ub294\uc9c0 \uc7a0\uae50 \uc0b4\ud3b4\ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uac00\ub9ac\ud0a4\uace0 \ub204\ub974\uace0 \ud655\uc778\ud558\ub294 \uc21c\uc11c\uac00 \uc790\uc5f0\uc2a4\ub7ec\uc6cc\uc11c \ud3c9\uc18c\uc5d0\ub294 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uc5e5\uac94\ubc14\ud2b8\uc758 \uc791\uc5c5\uc744 \uc54c\uba74 \uc774 \uc775\uc219\ud568\ub3c4 \ub204\uad70\uac00 \uc5f0\uad6c\ud558\uace0 \uc2dc\ud5d8\ud55c \uacb0\uacfc\uc600\uc74c\uc744 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \uc791\uc740 \ub3c4\uad6c\uc758 \uc5ed\uc0ac\uc5d0\uc11c \ub354 \ud070 \uc77c\ud558\ub294 \ubc29\uc2dd\uc774 \ubcf4\uc778\ub2e4. \ub9c8\uc6b0\uc2a4\ub294 \uc0ac\ub78c\uc758 \uc190\uacfc \ud654\uba74 \uc0ac\uc774\ub97c \uc5f0\uacb0\ud558\ub294 \ub3c4\uad6c\ub2e4. \ub108\ubb34 \uc775\uc219\ud574\uc9c4 \ub355\ubd84\uc5d0 \ud3c9\uc18c\uc5d0\ub294 \uadf8 \uad00\uacc4\ub97c \ud2b9\ubcc4\ud788 \uc0dd\uac01\ud558\uc9c0 \uc54a\ub294\ub2e4. \ud3b8\ud558\uac8c \uc4f0\uc774\ub294 \ub3c4\uad6c\uc77c\uc218\ub85d \uc0ac\uc6a9 \uc911\uc5d0\ub294 \uc874\uc7ac\ub97c \ub35c \uc758\uc2dd\ud558\uac8c \ub41c\ub2e4. \uc61b \ucef4\ud4e8\ud130\ub97c \ubcfc \ub54c \ud070 \ubcf8\uccb4\uc640 \ud654\uba74\uc5d0 \uba3c\uc800 \ub208\uc774 \uac00\uc9c0\ub9cc, \uc791\uc740 \uc785\ub825 \ub3c4\uad6c\ub3c4 \ud568\uaed8 \uc0b4\ud3b4\ubcfc \ub9cc\ud558\ub2e4. \uc0ac\uc6a9\uc790\uac00 \uc5b4\ub5a4 \ub3d9\uc791\uc73c\ub85c \ucef4\ud4e8\ud130\uc5d0 \uc758\uc0ac\ub97c \uc804\ud588\ub294\uc9c0\ub97c \ubcf4\uc5ec\uc8fc\uae30 \ub54c\ubb38\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \ub9c8\uc6b0\uc2a4\ub85c \ucc3d \ud558\ub098\ub97c \uc62e\uae30\uac70\ub098 \ubb38\uc11c\ub97c \uac00\ub9ac\ud0ac \ub54c \uc7a0\uae50 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc774 \uc791\uc740 \uc6c0\uc9c1\uc784\uc5d0\ub3c4 \uc0ac\ub78c\ub4e4\uc774 \ucef4\ud4e8\ud130\uc640 \uc77c\ud558\ub294 \ubc29\uc2dd\uc744 \ubc14\uafb8\ub824\ub358 \uae34 \uad6c\uc0c1\uc774 \uc774\uc5b4\uc838 \uc788\ub2e4."}, {"id": "git-saving-many-versions", "title": "\ucd5c\uc885\ubcf8, \uc9c4\uc9dc \ucd5c\uc885\ubcf8 \u2014 \uae43\uc740 \ubb34\uc5c7\uc744 \uae30\uc5b5\ud560\uae4c", "summary": "2005\ub144\uc758 \uac1c\ubc1c \ubc30\uacbd\uacfc \uc6d0\uace0 \ud3b8\uc9d1\uc758 \ube44\uc720\ub97c \ud1b5\ud574 \ubc84\uc804 \uad00\ub9ac\uac00 \ud544\uc694\ud55c \uc774\uc720\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "computing", "category_title": "Computing", "subcategory": "Software", "url": "stories/git-saving-many-versions/index.html", "image": "media/git-saving-many-versions.png", "alt": "\ub450 \ud3b8\uc9d1\uc790\uac00 \uc5ec\ub7ec \uc6d0\uace0\uc640 \ub178\ud2b8\ubd81\uc744 \ud568\uaed8 \uc0b4\ud3b4\ubcf4\uba70 \ub2e4\ub978 \ud310\ubcf8\uc744 \ube44\uad50\ud558\ub294 \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\ucd5c\uc885\ubcf8, \uc9c4\uc9dc \ucd5c\uc885\ubcf8 \u2014 \uae43\uc740 \ubb34\uc5c7\uc744 \uae30\uc5b5\ud560\uae4c \uc5ec\ub7ec \uc0ac\ub78c\uc774 \uace0\uccd0\ub3c4 \uc791\uc5c5\uc758 \ud750\ub984\uc744 \uc783\uc9c0 \uc54a\ub294 \ubc29\ubc95 2005\ub144\uc758 \uac1c\ubc1c \ubc30\uacbd\uacfc \uc6d0\uace0 \ud3b8\uc9d1\uc758 \ube44\uc720\ub97c \ud1b5\ud574 \ubc84\uc804 \uad00\ub9ac\uac00 \ud544\uc694\ud55c \uc774\uc720\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Software \ucef4\ud4e8\ud305 \uc6d0\uace0\ub97c \uace0\uce5c \ub4a4 \uc774\ub984\uc744 \ucd5c\uc885\ubcf8\uc73c\ub85c \uc800\uc7a5\ud55c\ub2e4. \ub2e4\uc2dc \uace0\uce58\uba74 \uc9c4\uc9dc \ucd5c\uc885\ubcf8\uc774 \ub418\uace0, \ub2e4\uc74c\uc5d0\ub294 \ucd5c\uc885\ubcf8 \uc218\uc815\uc774 \ub41c\ub2e4. \ub450 \uc0ac\ub78c\uc774 \uac01\uc790 \ubc1b\uc740 \ud30c\uc77c\uc744 \uace0\uce58\uae30 \uc2dc\uc791\ud558\uba74 \uc5b4\ub5a4 \ubb38\uc7a5\uc774 \ucd5c\uc2e0\uc778\uc9c0\ub3c4 \ud5f7\uac08\ub9b0\ub2e4. \uc18c\ud504\ud2b8\uc6e8\uc5b4\ub97c \ub9cc\ub4dc\ub294 \uc0ac\ub78c\ub4e4\ub3c4 \ube44\uc2b7\ud55c \ubb38\uc81c\ub97c \ud6e8\uc52c \ud070 \uaddc\ubaa8\ub85c \uacaa\ub294\ub2e4. \uae43\uc740 \uc774\ub7f0 \uc791\uc5c5\uc758 \uc0c1\ud0dc\uc640 \uc774\ub825\uc744 \uad00\ub9ac\ud558\ub294 \ub3c4\uad6c\ub2e4. \uba85\ub839\uc5b4\ub97c \ubc30\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \uc65c \ud544\uc694\ud55c\uc9c0\ub294 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \ubb34\uc5c7\uc744 \ubc14\uafb8\uc5c8\ub294\uc9c0 \uae30\uc5b5\ud558\uace0 \uc11c\ub85c \ub2e4\ub978 \uc791\uc5c5\uc744 \ube44\uad50\ud558\uba70 \ub2e4\uc2dc \uc774\uc5b4 \ubd99\uc77c \uc218 \uc788\uc5b4\uc57c \uc5ec\ub7ec \uc0ac\ub78c\uc774 \ud558\ub098\uc758 \uacb0\uacfc\ubb3c\uc744 \ub9cc\ub4e4 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \ud30c\uc77c \uc774\ub984\uc744 \ubc14\uafb8\uc5b4 \ubcf4\uad00\ud558\uba74 \uba87 \uac1c\uc758 \uacfc\uac70 \uc0c1\ud0dc\ub294 \ub0a8\uae38 \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uc218\ubc31 \uac1c\uc758 \ud30c\uc77c\uc774 \ud568\uaed8 \ubc14\ub00c\ub294 \ud504\ub85c\uc81d\ud2b8\ub77c\uba74 \uc774\uc57c\uae30\uc758 \ub2e8\uc704\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \uc5b4\ub290 \ubb38\uc11c\uc640 \uc5b4\ub290 \uc774\ubbf8\uc9c0\uac00 \uac19\uc740 \uc2dc\uc810\uc758 \ud55c \ubb36\uc74c\uc778\uc9c0\ub3c4 \uc54c\uc544\uc57c \ud55c\ub2e4. \uae43\uc5d0\uc11c \uc791\uc5c5 \uc0c1\ud0dc\ub97c \uae30\ub85d\ud558\ub294 \ucee4\ubc0b\uc740 \uc774\ub7f0 \ubb36\uc74c\uc744 \ub0a8\uae30\ub294 \ud589\uc704\ub2e4. \u300aPro Git\u300b\uc740 \uc774\ub97c \ud504\ub85c\uc81d\ud2b8\uc758 \uc2a4\ub0c5\uc20f\uc774\ub77c\ub294 \ub9d0\ub85c \uc124\uba85\ud55c\ub2e4. \uc2e4\uc81c \ud654\uba74 \uc0ac\uc9c4\uc744 \ucc0d\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uadf8\ub54c\uc758 \ud30c\uc77c \uc0c1\ud0dc\ub97c \uac00\ub9ac\ud0a8\ub2e4. \ubc14\ub00c\uc9c0 \uc54a\uc740 \ud30c\uc77c\uae4c\uc9c0 \ub9e4\ubc88 \uc0c8\ub85c \ud1b5\uc9f8\ub85c \uc911\ubcf5 \uc800\uc7a5\ud55c\ub2e4\ub294 \ub73b\ub3c4 \uc544\ub2c8\ub2e4. \uae43\uc758 \uc5ed\uc0ac \uc548\ub0b4\ub294 \ub9ac\ub205\uc2a4 \ucee4\ub110 \uac1c\ubc1c\uc5d0\uc11c \ucd9c\ubc1c\ud55c \ubc30\uacbd\uc744 \uc124\uba85\ud55c\ub2e4. \ub9ac\ub205\uc2a4 \uac1c\ubc1c\uc790\ub4e4\uc740 2002\ub144\ubd80\ud130 \ube44\ud2b8\ud0a4\ud37c\ub77c\ub294 \ub3c4\uad6c\ub97c \uc0ac\uc6a9\ud588\uc9c0\ub9cc, 2005\ub144 \uac1c\ubc1c \uacf5\ub3d9\uccb4\uc640 \uadf8 \ud68c\uc0ac\uc758 \uad00\uacc4\uac00 \ud2c0\uc5b4\uc9c0\uace0 \ubb34\ub8cc \uc0ac\uc6a9\uc774 \uc911\ub2e8\ub418\uc5c8\ub2e4. \ub9ac\ub204\uc2a4 \ud1a0\ub974\ubc1c\uc2a4 \ub4f1\uc744 \uc911\uc2ec\uc73c\ub85c \uc0c8 \ub3c4\uad6c\ub97c \ub9cc\ub4e4\uac8c \ub41c \uacc4\uae30\uc600\ub2e4. \ube60\ub974\uac8c \uc791\ub3d9\ud558\uace0, \ud070 \ud504\ub85c\uc81d\ud2b8\ub97c \ub2e4\ub8e8\uba70, \uc5ec\ub7ec \uac08\ub798\uc758 \uc791\uc5c5\uc744 \uc9c0\uc6d0\ud558\uace0, \ud55c\uacf3\uc5d0\ub9cc \uc758\uc874\ud558\uc9c0 \uc54a\ub294 \ubc29\uc2dd\uc774 \ubaa9\ud45c\uc5d0 \ub4e4\uc5b4\uac14\ub2e4. \ucc98\uc74c\ubd80\ud130 \ubaa8\ub4e0 \uc0ac\ub78c\uc758 \uc77c\uc0c1 \ud30c\uc77c\uc744 \uc704\ud55c \uc11c\ube44\uc2a4\ub85c \uae30\ud68d\ub418\uc5c8\ub2e4\uae30\ubcf4\ub2e4 \ud070 \uacf5\ub3d9 \uac1c\ubc1c\uc758 \ud544\uc694\uc5d0\uc11c \ub098\uc628 \uac83\uc774\ub2e4. \uc6d0\uace0\uc5d0\uc11c \ubb38\uc7a5 \ud558\ub098\uac00 \ubc14\ub00c\uc5c8\ub2e4\uba74 \uc774\uc804\uacfc \uc774\ud6c4\ub97c \ube44\uad50\ud574 \ubcfc \uc218 \uc788\uc5b4\uc57c \ud55c\ub2e4. \uc791\uc5c5\uc758 \uae30\ub85d\uc5d0\ub294 \ub0b4\uc6a9\ubfd0 \uc544\ub2c8\ub77c \ubcc0\uacbd\uc744 \uc124\uba85\ud558\ub294 \ub9d0\ub3c4 \uc911\uc694\ud558\ub2e4. \uc65c \uace0\ucce4\ub294\uc9c0 \ub0a8\uaca8 \ub450\uba74 \ub098\uc911\uc758 \ub3c5\uc790\uac00 \uadf8\ub54c\uc758 \uc758\ub3c4\ub97c \uc9d0\uc791\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ucef4\ud4e8\ud130\uac00 \ubcc0\uacbd \uc790\uccb4\ub97c \uae30\uc5b5\ud558\ub294 \uac83\uacfc \uc0ac\ub78c\uc774 \ubcc0\uacbd\uc744 \uc774\ud574\ud558\ub294 \uac83\uc740 \ub2e4\ub978 \ubb38\uc81c\ub2e4. \uae30\ub85d\uc744 \ub0a8\uacbc\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uc88b\uc740 \uc124\uba85\uc774 \uc0dd\uae30\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc5b4\ub290 \ubb38\uc7a5\uc744 \ubc14\uafb8\uc5c8\ub294\uc9c0\ub294 \ubcf4\uc5ec\ub3c4 \uc65c \uc0ac\uc2e4\uad00\uacc4\ub97c \uc218\uc815\ud588\ub294\uc9c0 \uc4f0\uc9c0 \uc54a\uc73c\uba74 \ub2e4\uc2dc \uc790\ub8cc\ub97c \ucc3e\uc544\uc57c \ud560 \uc218 \uc788\ub2e4. \ub3c4\uad6c\uc758 \uae30\uc5b5 \uc704\uc5d0 \uc0ac\ub78c\uc758 \uc124\uba85\uc774 \ud544\uc694\ud558\ub2e4. \ud55c \uc6d0\uace0\uc758 \ub3c4\uc785\ubd80\ub97c \ub450 \uac00\uc9c0\ub85c \uace0\uccd0 \ubcf4\uace0 \uc2f6\ub2e4\uace0 \ud574 \ubcf4\uc790. \uc9c0\uae08\uc758 \uc6d0\uace0\ub97c \ubc14\ub85c \ub36e\uc5b4\uc4f0\uc9c0 \uc54a\uace0 \ub2e4\ub978 \ud750\ub984\uc5d0\uc11c \uc2e4\ud5d8\ud560 \uc218 \uc788\ub2e4\uba74 \ub9c8\uc74c\uc774 \uac00\ubcbc\uc6cc\uc9c4\ub2e4. \uae43\uc758 \ube0c\ub79c\uce58\ub294 \uc5ec\ub7ec \uac08\ub798\uc758 \uc791\uc5c5\uc744 \ub2e4\ub8f0 \uc218 \uc788\uac8c \ud558\ub294 \ubc29\uc2dd\uc774\ub2e4. \uc774\uac83\uc740 \ub2e8\uc21c\ud788 \ud3f4\ub354\ub97c \ud558\ub098 \ub354 \ubcf5\uc0ac\ud574 \ub450\ub294 \uac83\uacfc \uc791\ub3d9 \uc6d0\ub9ac\uac00 \uac19\uc9c0\ub294 \uc54a\uc9c0\ub9cc, \ub3c5\uc790\uac00 \ubaa9\uc801\uc744 \uc774\ud574\ud558\uae30\uc5d0\ub294 \ub3c4\uc6c0\uc774 \ub418\ub294 \ube44\uc720\ub2e4. \ud55c \uac08\ub798\uc5d0\uc11c\ub294 \ud45c\ud604\uc744 \uace0\uce58\uace0 \ub2e4\ub978 \uac08\ub798\uc5d0\uc11c\ub294 \uc790\ub8cc\ub97c \ubcf4\uc644\ud55c \ub4a4 \uacb0\uacfc\ub97c \ube44\uad50\ud560 \uc218 \uc788\ub2e4. \uc120\ud0dd\ud558\uc9c0 \uc54a\uc740 \uc2e4\ud5d8\uacfc \ud604\uc7ac \uc0ac\uc6a9\ud560 \uacb0\uacfc\ub97c \uad6c\ubcc4\ud558\uae30 \uc26c\uc6cc\uc9c4\ub2e4. \ub450 \uc0ac\ub78c\uc774 \uc11c\ub85c \ub2e4\ub978 \ubb38\ub2e8\uc744 \uace0\ucce4\ub2e4\uba74 \ubcc0\uacbd\uc744 \ud568\uaed8 \ubc18\uc601\ud558\uae30\uac00 \ube44\uad50\uc801 \uc27d\ub2e4. \uadf8\ub7f0\ub370 \uac19\uc740 \ubb38\uc7a5\uc744 \uc11c\ub85c \ub2e4\ub974\uac8c \uace0\uce58\uba74 \uc5b4\ub290 \ucabd\uc774 \ub9de\ub294\uc9c0 \uc0ac\ub78c\uc774 \uacb0\uc815\ud574\uc57c \ud560 \uc218 \uc788\ub2e4. \uc774\ub7f0 \ucda9\ub3cc\uc744 \ubc1c\uacac\ud558\ub294 \uc77c\uacfc \ub0b4\uc6a9\uc758 \uc815\ub2f5\uc744 \ud310\ub2e8\ud558\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \uae43\uc740 \uc5ed\uc0ac\uc801 \uc0ac\uc2e4\uc744 \uc544\ub294 \ud3b8\uc9d1\uc790\uac00 \uc544\ub2c8\ub2e4. \ubb38\uc7a5\uc774 \ub354 \uc815\ud655\ud55c\uc9c0, \uc791\ud488 \uc81c\ubaa9\uc744 \uc798\ubabb \uc801\uc5c8\ub294\uc9c0\uae4c\uc9c0 \uc2a4\uc2a4\ub85c \ubcf4\uc7a5\ud558\uc9c0 \uc54a\ub294\ub2e4. \ubcc0\uacbd\uc744 \ube44\uad50\ud558\uace0 \uc120\ud0dd\ud560 \uc790\ub9ac\ub97c \uc81c\uacf5\ud560 \ubfd0\uc774\ub2e4. \ud611\uc5c5\uc758 \uc218\uace0\ub97c \uc904\uc774\uba74\uc11c\ub3c4 \uc911\uc694\ud55c \ud310\ub2e8\uc740 \uc0ac\ub78c\uacfc \ud3b8\uc9d1 \uacfc\uc815\uc5d0 \ub0a8\ub294\ub2e4. \ubd84\uc0b0\ub41c \ubc29\uc2dd\uc774\ub77c\ub294 \ub9d0\uc740 \uac01 \uc791\uc5c5 \uacf5\uac04\uc774 \uc0c1\ub2f9\ud55c \uc774\ub825\uc744 \ud568\uaed8 \uac00\uc9c8 \uc218 \uc788\ub2e4\ub294 \ub73b\uc774\ub2e4. \u300aPro Git\u300b\uc740 \ub9ce\uc740 \uc791\uc5c5\uc744 \uc790\uae30 \ucef4\ud4e8\ud130\uc758 \uc790\ub8cc\ub85c \ucc98\ub9ac\ud560 \uc218 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc5f0\uacb0\uc774 \ub04a\uaca8\ub3c4 \ubcc0\uacbd\uc744 \uae30\ub85d\ud558\uace0 \uacfc\uac70 \uc0c1\ud0dc\ub97c \uc0b4\ud3b4\ubcf4\ub294 \uc77c\uc774 \uac00\ub2a5\ud558\ub2e4. \ub2e4\ub9cc \uc790\uae30 \ucef4\ud4e8\ud130\uc5d0 \uae30\ub85d\ud55c \ub0b4\uc6a9\uc774 \uc790\ub3d9\uc73c\ub85c \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uc804\ub2ec\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud568\uaed8 \uc4f0\ub294 \uc800\uc7a5\uc18c\uc640 \ub0b4\uc6a9\uc744 \uc8fc\uace0\ubc1b\ub294 \uacfc\uc815\uc774 \ubcc4\ub3c4\ub85c \ud544\uc694\ud558\ub2e4. \uac1c\uc778\uc758 \uae30\ub85d\uacfc \uacf5\ub3d9 \uacf5\uac04\uc758 \ubc18\uc601\uc744 \uad6c\ubcc4\ud574\uc57c \ud55c\ub2e4. \ub0b4 \ucc45\uc0c1 \uc704\uc5d0\uc11c \uc6d0\uace0\ub97c \uace0\uce5c \uac83\uacfc \ud3b8\uc9d1\ubd80 \uc804\uccb4\uc5d0 \uc0c8 \uc6d0\uace0\ub97c \uc804\ub2ec\ud55c \uac83\uc774 \ub2e4\ub978 \uac83\uacfc \ube44\uc2b7\ud558\ub2e4. \uae43\uc740 \ubc84\uc804 \uad00\ub9ac\ub97c \ud558\ub294 \ub3c4\uad6c\uc774\uace0, GitHub\ub294 \uae43 \uc800\uc7a5\uc18c\ub97c \uc628\ub77c\uc778\uc5d0\uc11c \ubcf4\uad00\ud558\uace0 \ud611\uc5c5\ud560 \uc218 \uc788\uac8c \ud558\ub294 \uc11c\ube44\uc2a4\ub2e4. \uc774\ub984\uc774 \ube44\uc2b7\ud558\uace0 \ud568\uaed8 \ub9ce\uc774 \uc4f0\uc774\uc9c0\ub9cc \ud558\ub098\uac00 \uace7 \ub2e4\ub978 \ud558\ub098\ub294 \uc544\ub2c8\ub2e4. \uae43\uc744 \uc4f0\ub294 \ubaa8\ub4e0 \uc77c\uc774 \ubc18\ub4dc\uc2dc GitHub\ub97c \uac70\uccd0\uc57c \ud558\ub294 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \ub458\uc744 \uad6c\ubcc4\ud558\uba74 \uc628\ub77c\uc778 \uc11c\ube44\uc2a4\uac00 \uc81c\uacf5\ud558\ub294 \uac80\ud1a0\uc640 \uac8c\uc2dc \uae30\ub2a5\ub3c4 \ub354 \uc798 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \ud30c\uc77c\uc758 \uc774\ub825\uc744 \ub0a8\uae30\ub294 \uc77c, \ub3d9\ub8cc\uc5d0\uac8c \uc218\uc815\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc77c, \uc2e4\uc81c \ud648\ud398\uc774\uc9c0\uc5d0 \ubc18\uc601\ud558\ub294 \uc77c\uc740 \uc5f0\uacb0\ub420 \uc218 \uc788\uc9c0\ub9cc \uac01\uac01\uc758 \ub2e8\uacc4\ub2e4. \uc800\uc7a5\uc18c\uc5d0 \uc6d0\uace0\uac00 \uc788\ub2e4\uace0 \uace7\ubc14\ub85c \ub3c5\uc790\uc5d0\uac8c \uac8c\uc2dc\ub41c \uac83\uc740 \uc544\ub2c8\ub2e4. \uae30\ub85d\ud558\uc9c0 \uc54a\uc740 \ubcc0\uacbd\uc740 \uc783\uc744 \uc218 \uc788\uace0, \uae30\ub85d\ud55c \ub0b4\uc6a9\uc744 \uc9c0\uc6b0\uac70\ub098 \uc798\ubabb \ub2e4\ub8e8\ub294 \uc77c\ub3c4 \uac00\ub2a5\ud558\ub2e4. \ubc84\uc804 \uad00\ub9ac\uac00 \ubaa8\ub4e0 \uc0ac\uace0\ub97c \ub9c9\ub294 \ub9c8\ubc95\uc758 \ubcf4\ud5d8\uc740 \uc544\ub2c8\ub2e4. \uc911\uc694\ud55c \uae30\ub85d\uc744 \ub0a8\uae30\uace0 \ub2e4\ub978 \ubcf4\uad00\ucc98\uc640 \uacf5\uc720\ud558\ub294 \uc2b5\uad00\uae4c\uc9c0 \uc788\uc5b4\uc57c \uadf8 \uc7a5\uc810\uc774 \uc0b4\uc544\ub09c\ub2e4. \uae43\uc758 \uc774\uc57c\uae30\ub294 \uacb0\uad6d \ud568\uaed8 \uace0\uce58\ub294 \uc77c\uc758 \uc5ed\uc0ac\ub2e4. \ud30c\uc77c \uc774\ub984 \ub05d\uc5d0 \ucd5c\uc885\uc774\ub77c\ub294 \ub9d0\uc744 \uba87 \ubc88 \ubd99\uc774\ub294 \ub300\uc2e0 \uc5b4\ub5a4 \uc0c1\ud0dc\uc5d0\uc11c \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc84c\ub294\uc9c0\ub97c \uc774\uc5b4 \ub0a8\uae34\ub2e4. \ub355\ubd84\uc5d0 \uc6b0\ub9ac\ub294 \uacfc\uac70\ub97c \ubaa8\ub450 \uc678\uc6b0\ub294 \ub370 \uc4f0\ub358 \ud798\uc744 \uc9c0\uae08\uc758 \ubb38\uc7a5\uc744 \ub354 \uc88b\uac8c \ub9cc\ub4dc\ub294 \ub370 \uc4f8 \uc218 \uc788\ub2e4."}, {"id": "http-404-410", "title": "404\uc640 410\uc740 \uac19\uc740 \ube48 \ud398\uc774\uc9c0\uac00 \uc544\ub2c8\ub2e4", "summary": "\ucc3e\uc744 \uc218 \uc5c6\ub2e4\ub294 \uc751\ub2f5\uacfc \uc0ac\ub77c\uc84c\ub2e4\ub294 \uc751\ub2f5\uc758 \ucc28\uc774\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "computing", "category_title": "Computing", "subcategory": "Internet", "url": "stories/http-404-410/index.html", "image": "media/http-404-410.jpg", "alt": "404\uc640 410\uc740 \uac19\uc740 \ube48 \ud398\uc774\uc9c0\uac00 \uc544\ub2c8\ub2e4\uc758 \ub0b4\uc6a9\uc744 \ub3d5\ub294 \uc124\uba85\uc6a9 \uc774\ubbf8\uc9c0", "text": "404\uc640 410\uc740 \uac19\uc740 \ube48 \ud398\uc774\uc9c0\uac00 \uc544\ub2c8\ub2e4 \uc6f9\uc0ac\uc774\ud2b8\uac00 \uc5c6\uc5b4\uc9c4 \uc790\ub9ac\uc5d0 \ub0a8\uae30\ub294 \ub450 \uac00\uc9c0 \ub9d0 \ucc3e\uc744 \uc218 \uc5c6\ub2e4\ub294 \uc751\ub2f5\uacfc \uc0ac\ub77c\uc84c\ub2e4\ub294 \uc751\ub2f5\uc758 \ucc28\uc774\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Internet \ucef4\ud4e8\ud305 \uc624\ub798 \uc800\uc7a5\ud574 \ub454 \ub9c1\ud06c\ub97c \ub20c\ub800\ub294\ub370 \ud398\uc774\uc9c0 \ub300\uc2e0 404\ub77c\ub294 \uc22b\uc790\uac00 \ub098\uc628\ub2e4. \ubb38\uc774 \ub2eb\ud78c \uacf3\uc744 \ucc3e\uc544\uac04 \uae30\ubd84\uc774\ub2e4. \uadf8\ub7f0\ub370 \uc6f9\uc5d0\ub294 410\uc774\ub77c\ub294 \uc751\ub2f5\ub3c4 \uc788\ub2e4. \ub458 \ub2e4 \uc6d0\ud558\ub294 \ub0b4\uc6a9\uc744 \ubcfc \uc218 \uc5c6\uc9c0\ub9cc \ub73b\uc774 \uc644\uc804\ud788 \uac19\uc9c0\ub294 \uc54a\ub2e4. \uc6f9\uc758 \ud1b5\uc2e0 \uaddc\uce59\uc744 \uc815\ub9ac\ud55c RFC 9110\uc740 \uc774 \ub450 \uc751\ub2f5\uc744 \uad6c\ubd84\ud55c\ub2e4. \uc22b\uc790\ub97c \uc678\uc6b0\uae30\ubcf4\ub2e4 \ube48\uc790\ub9ac\uc5d0 \ub0a8\uae30\ub294 \ub9d0\uc774 \ub2e4\ub974\ub2e4\uace0 \uc0dd\uac01\ud558\uba74 \uc774\ud574\ud558\uae30 \uc27d\ub2e4. 404\ub294 \uc694\uccad\ud55c \ub300\uc0c1\uc758 \ud604\uc7ac \ub0b4\uc6a9\uc744 \ucc3e\uc9c0 \ubabb\ud588\ub2e4\ub294 \uc751\ub2f5\uc774\ub2e4. \uc11c\ubc84\uac00 \uadf8 \ub300\uc0c1\uc774 \uc874\uc7ac\ud55c\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uacf5\uac1c\ud558\uc9c0 \uc54a\uc73c\ub824 \ud560 \ub54c\ub3c4 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4. \uadf8\ub798\uc11c 404 \ud558\ub098\ub9cc \ubcf4\uace0 \uc0ac\ub77c\uc9c4 \uc0ac\uc815\uc744 \ubaa8\ub450 \uc54c\uc544\ub0bc \uc218\ub294 \uc5c6\ub2e4. \ud2b9\ud788 \uc774 \uc751\ub2f5 \uc790\uccb4\ub294 \uc0c1\ud0dc\uac00 \uc77c\uc2dc\uc801\uc778\uc9c0 \uc601\uad6c\uc801\uc778\uc9c0 \ub9d0\ud574 \uc8fc\uc9c0 \uc54a\ub294\ub2e4. \uc8fc\uc18c\ub97c \uc798\ubabb \uc801\uc5c8\uc744 \uc218\ub3c4 \uc788\uaca0\uc9c0\ub9cc, \uc5b8\uc81c\ub098 \uadf8\uac83\ub9cc\uc774 \uc774\uc720\ub77c\uace0 \uc815\ud560 \uc218\ub294 \uc5c6\ub294 \uac83\uc774\ub2e4. 410\uc740 \uadf8 \ub300\uc0c1\uc5d0 \ub354\ub294 \uc811\uadfc\ud560 \uc218 \uc5c6\uace0 \uadf8 \uc0c1\ud0dc\uac00 \uc624\ub798 \uc774\uc5b4\uc9c8 \uac83\uc73c\ub85c \ubcf4\uc778\ub2e4\ub294 \uc751\ub2f5\uc774\ub2e4. \uc6b4\uc601\uc790\uac00 \uadf8 \ucc28\uc774\ub97c \uc54c\uace0 \uc54c\ub9ac\ub824 \ud560 \ub54c \uc4f8 \uc218 \uc788\ub2e4. \uaddc\uce59\uc740 \uae30\uac04\uc774 \ub05d\ub09c \ud64d\ubcf4 \uc11c\ube44\uc2a4 \uac19\uc740 \uc608\ub3c4 \uc18c\uac1c\ud55c\ub2e4. \uac00\uac8c \uc55e\uc5d0 \ubb38\uc744 \ucc3e\uc744 \uc218 \uc5c6\ub2e4\ub294 \uc548\ub0b4\uac00 \uc788\ub294 \uac83\uacfc, \uc774\uacf3\uc740 \uc601\uc5c5\uc744 \ub9c8\ucce4\ub2e4\ub294 \uc548\ub0b4\uac00 \uc788\ub294 \uc0c1\ud669\uc744 \ub098\ub780\ud788 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc815\ud655\ud788 \uac19\uc740 \uc0ac\uc815\uc740 \uc544\ub2c8\uc9c0\ub9cc \ub450 \uc751\ub2f5\uc758 \ub2e4\ub978 \ud0dc\ub3c4\ub97c \uc774\ud574\ud558\ub294 \ube44\uc720\uac00 \ub41c\ub2e4. \uc6f9\uc758 \ub9c1\ud06c\ub294 \uc5b4\ub5a4 \uc8fc\uc18c\ub85c \uc694\uccad\uc744 \ubcf4\ub0b4\uac8c \ud55c\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \uc8fc\uc18c\uc758 \ub0b4\uc6a9\uc774 \uc5b8\uc81c\ub098 \uadf8\ub300\ub85c \ub0a8\uc544 \uc788\uc73c\ub9ac\ub77c\ub294 \ubcf4\uc99d\uae4c\uc9c0 \ub2f4\uace0 \uc788\uc9c0\ub294 \uc54a\ub2e4. \ud398\uc774\uc9c0\uac00 \ubc14\ub00c\uac70\ub098 \uc6b4\uc601 \ubc29\uc2dd\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc624\ub798\ub41c \ub9c1\ud06c\ub97c \ub20c\ub800\uc744 \ub54c \uc751\ub2f5\uc744 \uc77d\ub294 \uc77c\uc740 \uc8fc\uc18c\ub77c\ub294 \uc57d\uc18d\uacfc \ud604\uc7ac \uc81c\uacf5\ud558\ub294 \uc0c1\ud0dc\ub97c \ub098\ub204\uc5b4 \ubcf4\ub294 \uacfc\uc815\uc774\ub2e4. \uc774\ub54c 404 \ud654\uba74\uc744 \ubc1b\uc558\ub2e4\ub294 \uac83\uacfc \ud1b5\uc2e0 \uc790\uccb4\uac00 \uc804\ud600 \ub418\uc9c0 \uc54a\uc558\ub2e4\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \uc751\ub2f5\uc740 \uc694\uccad\uc5d0 \ub300\ud574 \uc5b4\ub5a4 \uc2dc\uc2a4\ud15c\uc774 \uc0c1\ud0dc\ub97c \uc54c\ub824 \uc900 \uac83\uc774\ub2e4. \ub2e4\ub9cc \uadf8 \uc22b\uc790\ub9cc\uc73c\ub85c \uc5b4\ub290 \uc9c0\uc810\uc758 \uc124\uc815\uc774 \uc798\ubabb\ub418\uc5c8\ub294\uc9c0\ub098 \uc6d0\ub798 \uc791\uc131\uc790\uc758 \uc758\ub3c4\uae4c\uc9c0 \uc54c\uc544\ub0bc \uc218\ub294 \uc5c6\ub2e4. \ubcf4\uc5ec \uc8fc\ub294 \uba54\uc2dc\uc9c0\uc758 \ubc94\uc704\ub97c \uba3c\uc800 \uad6c\ubd84\ud558\ub294 \ud3b8\uc774 \uc88b\ub2e4. 404\uac00 \uc601\uad6c\uc131\uacfc \uc77c\uc2dc\uc131\uc744 \ud655\uc815\ud558\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc810\uc740 \ub2f5\uc774 \ubd88\uce5c\uc808\ud558\ub2e4\ub294 \ub73b\ub9cc\uc740 \uc544\ub2c8\ub2e4. \uc11c\ubc84\uac00 \ud655\uc778\ud558\uac70\ub098 \uacf5\uac1c\ud560 \uc218 \uc788\ub294 \uc815\ubcf4\uc758 \ubc94\uc704\uac00 \uac70\uae30\uae4c\uc9c0\uc77c \uc218 \uc788\ub2e4. \uc6b4\uc601\uc790\ub294 \uc0ac\ub77c\uc9c4 \uc774\uc720\ub97c \uc815\ud655\ud788 \ubaa8\ub97c \uc218\ub3c4 \uc788\uace0, \uc874\uc7ac \uc5ec\ubd80\ub97c \ub4dc\ub7ec\ub0b4\uc9c0 \uc54a\uc73c\ub824 \ud560 \uc218\ub3c4 \uc788\ub2e4. \uac19\uc740 \uc0c1\ud0dc \ucf54\ub4dc \ub4a4\uc5d0 \uc5ec\ub7ec \uc0ac\uc815\uc774 \ub193\uc77c \uc218 \uc788\ub2e4. \uc0ac\ub78c \uc0ac\uc774\uc5d0\uc11c\ub3c4 \ucc3e\uc744 \uc218 \uc5c6\ub2e4\ub294 \ub9d0\uacfc \uc5c6\uc574\ub2e4\ub294 \ub9d0\uc740 \ub2e4\ub974\ub2e4. \uc804\uc790\ub294 \ud604\uc7ac\uc758 \ud655\uc778 \uacb0\uacfc\ub97c, \ud6c4\uc790\ub294 \uc774\ub825\uc5d0 \uad00\ud55c \ub354 \ub9ce\uc740 \ud310\ub2e8\uc744 \ud3ec\ud568\ud55c\ub2e4. \ub450 \uc751\ub2f5\uc744 \uc774\ub7f0 \ub9d0\uc758 \ucc28\uc774\ub85c \uc77d\uc73c\uba74 \uc22b\uc790\uac00 \ub2e8\uc21c\ud55c \uc2e4\ud328 \ud45c\uc2dc\ub9cc\uc740 \uc544\ub2c8\uac8c \ub41c\ub2e4. \uc6f9\uc740 \uc131\uacf5\ud55c \ub0b4\uc6a9\ubfd0 \uc544\ub2c8\ub77c \ubb34\uc5c7\uc744 \uc5b4\ub290 \uc815\ub3c4\ub85c \uc54c\ub9ac\ub294\uc9c0\ub3c4 \uacf5\ud1b5 \ud615\uc2dd\uc73c\ub85c \ub2e4\ub8ec\ub2e4. \uc5b4\ub5a4 \uc11c\ube44\uc2a4\uc758 \uc81c\uacf5 \uae30\uac04\uc774 \ub05d\ub0ac\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc6b4\uc601\uc790\uac00 \uc54c\uace0 \uc788\ub2e4\uba74 \ub354\ub294 \uc81c\uacf5\ud558\uc9c0 \uc54a\ub294 \uc0c1\ud0dc\ub97c \uc54c\ub9b4 \uc218 \uc788\ub2e4. 410\uc740 \uadf8\ub7f0 \uc120\ud0dd\uc744 \ud45c\ud604\ud558\ub294 \uc751\ub2f5\uc774\ub2e4. \ub2e8\uc21c\ud788 \ub0b4\uc6a9\uc774 \ube44\uc5b4 \uc788\ub2e4\ub294 \uac83\ubcf4\ub2e4 \uadf8 \ubd80\uc7ac\ub97c \uc5b4\ub5bb\uac8c \uc774\ud574\ud558\uba74 \ub418\ub294\uc9c0 \uc815\ubcf4\ub97c \ub354\ud558\ub294 \uc148\uc774\ub2e4. \uc624\ub798\ub41c \ub9c1\ud06c\ub97c \uad00\ub9ac\ud558\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub3c4 \uad6c\ubcc4\uc758 \uc774\uc720\uac00 \uc0dd\uae34\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubc29\ubb38\uc790\uac00 \uc774 \uc22b\uc790\ub97c \ubcf4\ub294 \uc989\uc2dc \ubaa8\ub4e0 \ub9c1\ud06c\ub97c \uc9c0\uc6cc\uc57c \ud55c\ub2e4\uac70\ub098 \uae30\ub85d\uc744 \ubc84\ub824\uc57c \ud55c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc6d0\ub798\uc758 \ub0b4\uc6a9\uc774 \ub2e4\ub978 \uc8fc\uc18c\ub098 \ubcf4\uc874 \uc790\ub8cc\uc5d0 \ub0a8\uc544 \uc788\uc744 \uac00\ub2a5\uc131\uc740 \ubcc4\ub3c4 \ubb38\uc81c\ub2e4. \uc0c1\ud0dc \uc751\ub2f5\uc740 \uc9c0\uae08 \uc694\uccad\ud55c \ub300\uc0c1\uc758 \uc811\uadfc\uc5d0 \uad00\ud574 \ub9d0\ud55c\ub2e4. \uc790\ub8cc\uc758 \uc5ed\uc0ac \uc804\uccb4\uc640 \ubcf4\uc874 \uac00\uce58\ub97c \ub300\uc2e0 \ud310\uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud654\uba74\uc5d0\ub294 \uc7ac\ubbf8\uc788\ub294 \uadf8\ub9bc\uacfc \ubb38\uad6c\uac00 \ub098\uc62c \uc218 \uc788\uc9c0\ub9cc, \uadf8 \ub514\uc790\uc778\uc774 \uc22b\uc790\uc758 \ub73b\uc744 \uc0c8\ub85c \uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ubc18\ub300\ub85c \uac19\uc740 404\ub77c\ub3c4 \uc0ac\uc774\ud2b8\ub9c8\ub2e4 \ubc29\ubb38\uc790\uc5d0\uac8c \ubcf4\uc5ec \uc8fc\ub294 \ud654\uba74\uc740 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uc0c1\ud0dc\ub97c \uc804\ud558\ub294 \uaddc\uce59\uacfc \uadf8\uac83\uc744 \ub208\uc5d0 \ubcf4\uc774\uac8c \ud45c\ud604\ud55c \ud398\uc774\uc9c0\ub294 \uc5f0\uacb0\ub418\uc9c0\ub9cc \uad6c\ubd84\ud560 \uc218 \uc788\ub294 \ubd80\ubd84\uc774\ub2e4. \uadf8\ub798\uc11c \uc7ac\uce58 \uc788\ub294 \uc624\ub958 \ud654\uba74\uc744 \ubcf4\ub354\ub77c\ub3c4 \uba3c\uc800 \ubb34\uc5c7\uc774 \ud655\uc778\ub418\uc9c0 \uc54a\uc558\ub294\uc9c0 \uc54c\uba74 \ub41c\ub2e4. \ub3cc\uc544\uac08 \uccab \ud654\uba74\uc774\ub098 \uac80\uc0c9\uc73c\ub85c \ub2e4\ub978 \uae38\uc744 \ucc3e\ub294 \uc77c\uc740 \uadf8\ub2e4\uc74c\uc758 \uc774\uc6a9 \uacbd\ud5d8\uc774\ub2e4. \uc2e4\ud328\ud55c \uc694\uccad\uc744 \uc5b4\ub5bb\uac8c \uc548\ub0b4\ud560\uc9c0\ub3c4 \uc6f9\uc0ac\uc774\ud2b8\uc758 \ud3b8\uc9d1\uacfc \uc124\uacc4\uc5d0 \ub4e4\uc5b4\uac04\ub2e4. \ube48 \ud654\uba74\ucc98\ub7fc \ubcf4\uc774\ub358 \uc790\ub9ac\uc5d0\ub3c4 \uc815\ubcf4\uc758 \uc815\ub3c4\uc640 \ubc29\ubb38\uc790\ub97c \ub300\ud558\ub294 \ud0dc\ub3c4\uac00 \ud568\uaed8 \ub0a8\uc544 \uc788\ub2e4. \ubaa8\ub4e0 \uc6f9\uc0ac\uc774\ud2b8\uac00 \uc5c6\uc5b4\uc9c4 \ud398\uc774\uc9c0\uc5d0 \ubc18\ub4dc\uc2dc 410\uc744 \ubd99\uc774\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uaddc\uce59\ub3c4 \ubaa8\ub4e0 \uc601\uad6c\uc801\uc778 \uc0ad\uc81c\ub97c \uc774 \uc751\ub2f5\uc73c\ub85c \ud45c\uc2dc\ud574\uc57c \ud55c\ub2e4\uace0 \uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud604\uc2e4\uc758 \uc0ac\uc774\ud2b8\ub4e4\uc740 \uc5ec\ub7ec \uc774\uc720\ub85c \ub2e4\ub978 \uc120\ud0dd\uc744 \ud55c\ub2e4. \uadf8\ub798\uc11c 404\ub098 410\uc774 \ub208\uc5d0 \ub4e4\uc5b4\uc624\uba74 \ubaa8\ub4e0 \uc0ac\uc815\uc744 \ucd94\uce21\ud558\uae30\ubcf4\ub2e4 \uc751\ub2f5\uc774 \ub9d0\ud574 \uc8fc\ub294 \ubc94\uc704\ub9cc \uc77d\uc73c\uba74 \ub41c\ub2e4. \ub0b4\uc6a9\uc774 \uc5c6\ub294 \ud654\uba74\uc5d0\ub3c4, \uc544\uc9c1 \ubaa8\ub978\ub2e4\ub294 \ub9d0\uacfc \ub5a0\ub0ac\uc74c\uc744 \uc54c\ub9ac\ub294 \ub9d0\uc758 \ucc28\uc774\ub294 \ub0a8\uc544 \uc788\ub2e4."}, {"id": "https-small-s-and-connection", "title": "HTTPS \u2014 \uc6f9 \uc8fc\uc18c\uc758 \uc791\uc740 s\uac00 \ud558\ub294 \uc77c", "summary": "\uc554\ud638\ud654\u00b7\ubcc0\uc870 \ud0d0\uc9c0\u00b7\uc11c\ubc84 \ud655\uc778\uc744 \ub098\ub204\uc5b4 \ubcf4\uace0 HTTPS\uac00 \ubcf4\ud638\ud558\ub294 \ubc94\uc704\ub97c \uc774\ud574\ud569\ub2c8\ub2e4.", "category": "computing", "category_title": "Computing", "subcategory": "Internet", "url": "stories/https-small-s-and-connection/index.html", "image": "media/https-small-s-and-connection.png", "alt": "\uacf5\uc720 \ub3c5\uc11c \uacf5\uac04\uc5d0\uc11c \ubd09\ud22c\ub97c \ub4e4\uace0 \ub9d0\uacfc \uc815\ubcf4\ub97c \ub098\ub204\ub294 \ub450 \uc0ac\ub78c\uc758 AI \ube44\uc720 \uc7a5\uba74.", "text": "HTTPS \u2014 \uc6f9 \uc8fc\uc18c\uc758 \uc791\uc740 s\uac00 \ud558\ub294 \uc77c \uc5f0\uacb0\uc744 \ubcf4\ud638\ud55c\ub2e4\ub294 \ub9d0\uacfc \ub0b4\uc6a9\uc744 \ubbff\ub294\ub2e4\ub294 \ub9d0 \uc0ac\uc774 \uc554\ud638\ud654\u00b7\ubcc0\uc870 \ud0d0\uc9c0\u00b7\uc11c\ubc84 \ud655\uc778\uc744 \ub098\ub204\uc5b4 \ubcf4\uace0 HTTPS\uac00 \ubcf4\ud638\ud558\ub294 \ubc94\uc704\ub97c \uc774\ud574\ud569\ub2c8\ub2e4. Internet \ucef4\ud4e8\ud305 \uc6f9 \uc8fc\uc18c\ub97c \uc790\uc138\ud788 \ubcf4\uba74 http \ub4a4\uc5d0 \uc791\uc740 s\uac00 \ubd99\uc5b4 \uc788\ub294 \uacbd\uc6b0\uac00 \ub9ce\ub2e4. \ud654\uba74\uc758 \uae00\uacfc \uc0ac\uc9c4\uc740 \ube44\uc2b7\ud558\uac8c \ubcf4\uc774\ub294\ub370 \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc9c0\ub294 \uac78\uae4c. \uc774 \ucc28\uc774\ub294 \uc0ac\uc774\ud2b8\uc758 \ub514\uc790\uc778\ubcf4\ub2e4 \ube0c\ub77c\uc6b0\uc800\uc640 \uc11c\ubc84 \uc0ac\uc774\uc5d0\uc11c \uc815\ubcf4\uac00 \uc624\uac00\ub294 \ubc29\uc2dd\uc5d0 \uc788\ub2e4. HTTPS\ub294 HTTP \ud1b5\uc2e0\uc744 TLS\ub77c\ub294 \ubcf4\uc548 \ud504\ub85c\ud1a0\ucf5c\ub85c \ubcf4\ud638\ud558\ub294 \ubc29\uc2dd\uc774\ub2e4. \uc774\ub984\uc774 \uc870\uae08 \uae38\uc9c0\ub9cc \uc138 \uac00\uc9c0 \uc9c8\ubb38\uc73c\ub85c \ub098\ub204\uba74 \uc774\ud574\ud558\uae30 \uc27d\ub2e4. \uc911\uac04\uc5d0\uc11c \ub0b4\uc6a9\uc744 \uc77d\uae30 \uc5b4\ub835\uac8c \ud558\ub294\uac00, \ubab0\ub798 \ubc14\uafb8\uba74 \uc54c\uc544\ucc4c \uc218 \uc788\ub294\uac00, \uc5f0\uacb0\ud55c \uc11c\ubc84\uac00 \ud574\ub2f9 \uc774\ub984\uc758 \uc11c\ubc84\uc778\uc9c0 \ud655\uc778\ud558\ub294\uac00. \ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c \ud398\uc774\uc9c0\ub97c \uc5f4\uba74 \uc694\uccad\uacfc \uc751\ub2f5\uc774 \ub124\ud2b8\uc6cc\ud06c\ub97c \uac70\uce5c\ub2e4. \uc911\uac04\uc758 \uc5f0\uacb0\uc744 \ubaa8\ub450 \ubbff\uc744 \uc218 \uc788\ub294 \uc0c1\ud669\ub9cc \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubbfc\uac10\ud55c \uc815\ubcf4\ubfd0 \uc544\ub2c8\ub77c \uc77c\ubc18\uc801\uc778 \ud398\uc774\uc9c0\ub3c4 \uc774\ub3d9 \uc911\uc758 \ubcf4\ud638\uac00 \ud544\uc694\ud560 \uc218 \uc788\ub2e4. HTTPS\ub294 \uc774 \ud1b5\uc2e0 \uad6c\uac04\uc5d0\uc11c \uc8fc\uace0\ubc1b\ub294 \ub370\uc774\ud130\ub97c \uc554\ud638\ud654\ud55c\ub2e4. \uc804\ub2ec \uc911\uc778 \ub0b4\uc6a9\uc744 \ud5c8\ub77d \uc5c6\uc774 \uc77d\uae30 \uc5b4\ub835\uac8c \ub9cc\ub4dc\ub294 \uac83\uc774\ub2e4. \ud3b8\uc9c0\ub97c \ubd09\ud22c\uc5d0 \ub123\ub294 \ube44\uc720\uac00 \uccab \uc774\ud574\uc5d0\ub294 \ub3c4\uc6c0\uc774 \ub418\uc9c0\ub9cc \uc2e4\uc81c \uae30\uc220\uc740 \uc885\uc774 \ubd09\ud22c\uc758 \ubb3c\ub9ac\uc801 \ubcf4\ud638\uc640 \uac19\uc9c0 \uc54a\ub2e4. \uc5ec\uae30\uc11c\ub294 \ubb34\uc5c7\uc744 \ubcf4\ud638\ud558\ub824\ub294\uc9c0\uc5d0 \ucd08\uc810\uc744 \ub9de\ucd94\uba74 \ub41c\ub2e4. \uc815\ubcf4\ub97c \uc228\uae30\ub294 \uae30\ub2a5\ub9cc\uc73c\ub85c\ub294 \ucda9\ubd84\ud558\uc9c0 \uc54a\ub2e4. \uc911\uac04\uc5d0\uc11c \uc751\ub2f5 \ub0b4\uc6a9\uc744 \ubab0\ub798 \ubc14\uafb8\uc5c8\uc744 \ub54c\ub3c4 \uc774\ub97c \uc54c\uc544\ucc4c \uc218 \uc788\uc5b4\uc57c \ud55c\ub2e4. MDN\uc740 \uc774\ub97c \ubb34\uacb0\uc131\uc758 \ubb38\uc81c\ub85c \uc124\uba85\ud55c\ub2e4. \uc804\ub2ec\ud558\ub294 \ub370\uc774\ud130\uac00 \ub208\uc5d0 \ub744\uc9c0 \uc54a\uac8c \ubcc0\uc870\ub418\ub294 \uc77c\uc744 \ub9c9\uae30 \uc704\ud55c \uc131\uc9c8\uc774\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \ubc1b\uc740 \ubb38\uc7a5\uc5d0 \ub2e4\ub978 \ub2e8\uc5b4\uac00 \ub07c\uc5b4\ub4e4\uc5c8\ub2e4\uba74 \uc6d0\ub798 \uc11c\ubc84\uc758 \ub9d0\uc778\uc9c0 \uc54c\uae30 \uc5b4\ub835\ub2e4. \uc815\ubcf4\uc758 \ub0b4\uc6a9\uc774 \uc798 \ubcf4\uc774\uc9c0 \uc54a\uac8c \ud558\ub294 \uc77c\uacfc \uc815\ubcf4\uac00 \ubc14\ub00c\uc5c8\ub294\uc9c0 \ud655\uc778\ud558\ub294 \uc77c\uc740 \ub2e4\ub978 \uc5ed\ud560\uc774\ub2e4. TLS\ub294 \uc774\ub7f0 \uc5ec\ub7ec \ubcf4\ud638\ub97c \ud568\uaed8 \uc81c\uacf5\ud558\ub3c4\ub85d \uc124\uacc4\ub418\uc5b4 \uc788\ub2e4. \uc544\ubb34 \uc0c1\ub300\uc640 \uc548\uc804\ud558\uac8c \uc774\uc57c\uae30\ud55c\ub2e4\uace0 \ucda9\ubd84\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \ub0b4\uac00 \uc811\uc18d\ud558\ub824\ub358 \uc774\ub984\uc758 \uc11c\ubc84\uc778\uc9c0 \ud655\uc778\ud558\ub294 \ub2e8\uacc4\ub3c4 \ud544\uc694\ud558\ub2e4. \uc6f9\uc5d0\uc11c\ub294 \ubcf4\ud1b5 \uc11c\ubc84\uac00 \ube0c\ub77c\uc6b0\uc800\uc5d0 \uc790\uc2e0\uc744 \uc778\uc99d\ud55c\ub2e4. \ubc29\ubb38\uc790 \uac1c\uc778\uc774 TLS \uc778\uc99d\uc11c\ub85c \ub9e4\ubc88 \uc790\uc2e0\uc744 \uc99d\uba85\ud558\ub294 \uac83\uc774 \uc77c\ubc18\uc801\uc778 \ubc29\uc2dd\uc740 \uc544\ub2c8\ub2e4. \uc774\ub54c \ub514\uc9c0\ud138 \uc778\uc99d\uc11c\ub294 \uc0ac\uc774\ud2b8\uc758 \ub3c4\uba54\uc778 \uc774\ub984\uacfc \uc554\ud638 \ud1b5\uc2e0\uc5d0 \uc4f0\ub294 \ud0a4\ub97c \uc5f0\uacb0\ud55c\ub2e4. \ube0c\ub77c\uc6b0\uc800\ub294 \uc774\ub97c \uac80\uc0ac\ud574 \uc5f0\uacb0\uc758 \uc0c1\ub300\ub97c \ud655\uc778\ud55c\ub2e4. \uc0ac\uc774\ud2b8\uc758 \uc774\ub984\uc744 \ud655\uc778\ud558\ub294 \uc77c\uacfc \uadf8\uacf3\uc5d0 \uc4f0\uc778 \ubaa8\ub4e0 \uae00\uc774 \uc0ac\uc2e4\uc778\uc9c0 \ud3c9\uac00\ud558\ub294 \uc77c\uc740 \uc5ec\uc804\ud788 \ub2e4\ub974\ub2e4. TLS \ud1b5\uc2e0\uc740 \ucc98\uc74c\ubd80\ud130 \uc544\ubb34 \uc900\ube44 \uc5c6\uc774 \uc774\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \uc5f0\uacb0 \ucd08\uae30\uc5d0 \uc0ac\uc6a9\ud560 \ubc29\uc2dd\uacfc \ud544\uc694\ud55c \ubcf4\uc548 \uc870\uac74\uc744 \uc815\ud558\ub294 \uacfc\uc815\uc774 \uc788\ub2e4. \uc774\ub97c \ud578\ub4dc\uc170\uc774\ud06c\ub77c\uace0 \ud55c\ub2e4. \uc545\uc218\ub97c \ud55c\ub2e4\ub294 \uc774\ub984\uc774\uc9c0\ub9cc \uc0ac\ub78c\ub07c\ub9ac \uc778\uc0ac\ud558\ub294 \ubaa8\uc2b5\uacfc \uc815\ud655\ud788 \uac19\uc740 \uc808\ucc28\ub294 \uc544\ub2c8\ub2e4. \uc774 \uacfc\uc815\uc744 \uac70\uccd0 \ud1b5\uc2e0\uc5d0 \uc0ac\uc6a9\ud560 \uc870\uac74\uacfc \ud0a4\ub97c \ub9c8\ub828\ud55c\ub2e4. \ub3c5\uc790\uac00 \uc554\ud638 \uc54c\uace0\ub9ac\uc998\uc758 \uc774\ub984\uc744 \uc678\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uacf5\ud1b5\uc758 \ubcf4\ud638 \ubc29\uc2dd\uc5d0 \ud569\uc758\ud558\uace0 \uc2e4\uc81c \ub370\uc774\ud130\ub97c \uc8fc\uace0\ubc1b\uae30 \uc704\ud55c \uc900\ube44\uac00 \uc788\ub2e4\ub294 \uc815\ub3c4\uba74 \uc791\uc740 s\uac00 \ub73b\ud558\ub294 \ubcc0\ud654\uac00 \uc880 \ub354 \uad6c\uccb4\uc801\uc73c\ub85c \ub290\uaef4\uc9c4\ub2e4. HTTPS\ub294 \ube0c\ub77c\uc6b0\uc800\uc640 \uc11c\ubc84 \uc0ac\uc774\ub85c \uc774\ub3d9\ud558\ub294 \uc815\ubcf4\ub97c \ubcf4\ud638\ud55c\ub2e4. \ub530\ub77c\uc11c \uc11c\ubc84\uc5d0 \ub3c4\ucc29\ud55c \ub4a4 \uadf8 \ud68c\uc0ac\uac00 \uc815\ubcf4\ub97c \uc5b4\ub5bb\uac8c \ubcf4\uad00\ud558\uace0 \uc0ac\uc6a9\ud558\ub294\uc9c0\uae4c\uc9c0 \uac19\uc740 \uae30\uc220\uc774 \uc790\ub3d9\uc73c\ub85c \ubcf4\uc99d\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub0b4 \uae30\uae30\uc5d0\uc11c \uc774\ubbf8 \ub204\uad70\uac00\uac00 \ud654\uba74\uc744 \ubcfc \uc218 \uc788\ub294 \ubb38\uc81c\ub3c4 \ubcc4\ub3c4\ub85c \uc788\ub2e4. \uc774\uac83\uc740 HTTPS\uac00 \ubd80\uc871\ud558\ub2c8 \uc758\ubbf8 \uc5c6\ub2e4\ub294 \ub9d0\uc774 \uc544\ub2c8\ub2e4. \uc6b0\ud3b8\uc774 \uc6b4\uc1a1 \uc911\uc5d0 \uc548\uc804\ud55c \uac83\uacfc \ubc1b\uc740 \uc0ac\ub78c\uc774 \ud3b8\uc9c0\ub97c \uc5b4\ub5bb\uac8c \ubcf4\uad00\ud558\ub294\uc9c0\uac00 \ub2e4\ub978 \uc9c8\ubb38\uc778 \uac83\ucc98\ub7fc, \uc5ed\ud560\uc758 \ubc94\uc704\uac00 \ub2e4\ub978 \uac83\uc774\ub2e4. \ubcf4\ud638\ud558\ub294 \uad6c\uac04\uc744 \uc54c\uba74 \ud55c \uae30\uc220\uc5d0 \ubaa8\ub4e0 \ucc45\uc784\uc744 \uae30\ub300\ud558\uc9c0 \uc54a\uace0 \uadf8 \uac00\uce58\ub97c \uc815\ud655\ud788 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uac00\uc9dc \uc124\uba85\uc744 \uc4f0\uac70\ub098 \uc798\ubabb\ub41c \ubb3c\uac74\uc744 \ud30c\ub294 \uc0ac\uc774\ud2b8\ub3c4 \uc554\ud638\ud654\ub41c \uc5f0\uacb0\uc744 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4. \ud574\ub2f9 \ub3c4\uba54\uc778\uacfc \ud1b5\uc2e0 \uc911\uc774\ub77c\ub294 \ud655\uc778\uc740 \uc6b4\uc601\uc790\uc758 \ubaa8\ub4e0 \ud589\ub3d9\uc744 \uc2e0\ub8b0\ud558\ub77c\ub294 \ucd94\ucc9c\uc774 \uc544\ub2c8\ub2e4. \uc548\uc804\ud55c \uc5f0\uacb0\uacfc \ubbff\uc744 \ub9cc\ud55c \uc0c1\ub300\ub294 \ub098\ub204\uc5b4 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc8fc\uc18c\uc758 \uc791\uc740 s\ub97c \uc911\uc694\ud55c \uae30\ubcf8 \uc870\uac74\uc73c\ub85c \ubcf4\uba74\uc11c\ub3c4 \uae00\uc758 \ucd9c\ucc98\uc640 \uc11c\ube44\uc2a4\uc758 \uc6b4\uc601 \uc815\ubcf4\ub294 \ubcc4\ub3c4\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. HTTPS\uc758 \ub73b\uc744 \uc774\ud574\ud558\ub294 \uc77c\uc740 \ubd88\uc548\uc744 \ud0a4\uc6b0\ub294 \uae30\uc220 \uacf5\ubd80\ubcf4\ub2e4, \uc11c\ub85c \ub2e4\ub978 \ud655\uc778\uc774 \ubb34\uc5c7\uc744 \uc54c\ub824 \uc8fc\ub294\uc9c0 \uad6c\ubcc4\ud558\ub294 \ub370 \uac00\uae5d\ub2e4. \ud55c \ud398\uc774\uc9c0\uc5d0\ub294 \ubcf8\ubb38\ubfd0 \uc544\ub2c8\ub77c \uc774\ubbf8\uc9c0\uc640 \ud504\ub85c\uadf8\ub7a8 \ud30c\uc77c \ub4f1 \uc5ec\ub7ec \uc790\ub8cc\uac00 \ud3ec\ud568\ub41c\ub2e4. \ubcf8\ubb38\uc740 HTTPS\ub85c \ubc1b\uc544\ub3c4 \ub2e4\ub978 \uc790\ub8cc\ub97c \ubcf4\ud638\ub418\uc9c0 \uc54a\uc740 \uc5f0\uacb0\ub85c \uac00\uc838\uc624\uba74 \ud398\uc774\uc9c0 \uc804\uccb4\uc758 \ubcf4\ud638\uc5d0 \ubb38\uc81c\uac00 \uc0dd\uae38 \uc218 \uc788\ub2e4. \uadf8\ub798\uc11c \ube0c\ub77c\uc6b0\uc800\ub294 \uc774\ub7f0 \ud63c\ud569 \ucf58\ud150\uce20\ub97c \uc81c\ud55c\ud55c\ub2e4. \uc774 \uc6d0\ub9ac\ub294 \uc911\uc694\ud55c \uc11c\ub958 \ud55c \uc7a5\ub9cc \ubd09\ud558\uace0 \ub098\uba38\uc9c0\ub294 \uadf8\ub300\ub85c \ubcf4\ub0b4\ub294 \uc0c1\ud669\uc744 \ub5a0\uc62c\ub9ac\uba74 \uc27d\ub2e4. \ud654\uba74\uc5d0\uc11c \ud55c \uc7a5\uc758 \ud398\uc774\uc9c0\ub85c \ubcf4\uc774\ub354\ub77c\ub3c4 \uc5ec\ub7ec \ud1b5\uc2e0\uc774 \ubaa8\uc778 \uacb0\uacfc\ub2e4. \uc0ac\uc774\ud2b8\ub97c \ub9cc\ub4dc\ub294 \ucabd\uc740 \uadf8 \uc790\ub8cc\ub4e4\uae4c\uc9c0 \ud568\uaed8 \ubcf4\ud638\ub418\ub3c4\ub85d \uc900\ube44\ud574\uc57c \ud55c\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uacf5\uc720 \uacf5\uac04\uc5d0\uc11c \ubd09\ud22c\uc5d0 \ub2f4\uae34 \ub9d0\uc744 \ub098\ub204\ub294 \ubd84\uc704\uae30\ub97c \ud45c\ud604\ud588\ub2e4. \uc2e4\uc81c \ub124\ud2b8\uc6cc\ud06c\ub098 \uc554\ud638\ud654 \uad6c\uc870\ub97c \ubcf4\uc5ec \uc8fc\ub294 \ub3c4\uc2dd\uc740 \uc544\ub2c8\ub2e4. \ube0c\ub77c\uc6b0\uc800\uc758 \ud45c\uc2dc \ubaa8\uc591\ub3c4 \uc81c\ud488\uacfc \ubc84\uc804\uc5d0 \ub530\ub77c \ubc14\ub014 \uc218 \uc788\uc73c\ubbc0\ub85c \uadf8\ub9bc\uc744 \uc124\uc815 \uc548\ub0b4\ucc98\ub7fc \uc0ac\uc6a9\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc791\uc740 s\ub294 \uc6f9\ud398\uc774\uc9c0\uc758 \ub0b4\uc6a9\uc774 \uc544\ub2c8\ub77c \uc624\uac00\ub294 \uae38\uc744 \ub2e4\ub974\uac8c \ub9cc\ub4e0\ub2e4. \uc77d\uae30 \uc5b4\ub835\uac8c \ud558\uace0, \ubc14\ub010 \uac83\uc744 \uc54c\uc544\ucc44\uba70, \ud574\ub2f9 \uc774\ub984\uc758 \uc11c\ubc84\uc640 \uc5f0\uacb0\ud588\ub294\uc9c0 \ud655\uc778\ud558\ub294 \uc57d\uc18d\uc774\ub2e4. \ub73b\uc744 \ub098\ub204\uc5b4 \uc54c\uba74 \uc775\uc219\ud55c \uc6f9 \uc8fc\uc18c\uc5d0\uc11c\ub3c4 \ud3b8\ub9ac\ud568\uc744 \uac00\ub2a5\ud558\uac8c \ud558\ub294 \uc870\uc6a9\ud55c \uae30\uc220\uc774 \ubcf4\uc778\ub2e4."}, {"id": "jpeg-small-photo-file", "title": "\uc0ac\uc9c4 \ud30c\uc77c\uc740 \uc5b4\ub5bb\uac8c \uac00\ubcbc\uc6cc\uc84c\uc744\uae4c \u2014 JPEG\uc758 \uc791\uc740 \ud0c0\ud611", "summary": "\uc0ac\uc9c4\uc744 \uc904\uc5ec \ubcf4\ub0b4\ub294 \uc555\ucd95\uc758 \uc6d0\ub9ac\uc640 \uc120\uba85\ud55c \uae00\uc528\uc5d0 \uc0dd\uae30\ub294 \ud754\uc801\uc744 \uc77c\uc0c1\uc758 \uc774\ubbf8\uc9c0\uc5d0\uc11c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "computing", "category_title": "Computing", "subcategory": "Software", "url": "stories/jpeg-small-photo-file/index.html", "image": "media/jpeg-small-photo-file.png", "alt": "\uc0ac\uc9c4\uac00\uc758 \ucc45\uc0c1 \uc704 \ud48d\uacbd \uc0ac\uc9c4 \uac00\uc7a5\uc790\ub9ac\uc5d0 \uc0c9 \uc870\uac01\uc774 \ud45c\ud604\ub41c \uc0c1\uc0c1 \uc0bd\ud654.", "text": "\uc0ac\uc9c4 \ud30c\uc77c\uc740 \uc5b4\ub5bb\uac8c \uac00\ubcbc\uc6cc\uc84c\uc744\uae4c \u2014 JPEG\uc758 \uc791\uc740 \ud0c0\ud611 \ub35c \ub0a8\uae30\uba74\uc11c\ub3c4 \uc0ac\uc9c4\ucc98\ub7fc \ubcf4\uc774\uac8c \ub9cc\ub4dc\ub294 \ubc29\ubc95 \uc0ac\uc9c4\uc744 \uc904\uc5ec \ubcf4\ub0b4\ub294 \uc555\ucd95\uc758 \uc6d0\ub9ac\uc640 \uc120\uba85\ud55c \uae00\uc528\uc5d0 \uc0dd\uae30\ub294 \ud754\uc801\uc744 \uc77c\uc0c1\uc758 \uc774\ubbf8\uc9c0\uc5d0\uc11c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Software \ucef4\ud4e8\ud305 \uc5ec\ud589 \uc0ac\uc9c4 \ud55c \uc7a5\uc744 \ubcf4\ub0b4\ub824\ub294\ub370 \ud30c\uc77c\uc774 \ub108\ubb34 \ud06c\ub2e4\ub294 \uc548\ub0b4\uac00 \ub72c\ub2e4. \ud06c\uae30\ub97c \uc904\uc600\ub354\ub2c8 \ud654\uba74\uc5d0\uc11c\ub294 \ubcc4 \ucc28\uc774\uac00 \uc5c6\uc5b4 \ubcf4\uc778\ub2e4. \uadf8\ub7f0\ub370 \uae00\uc528\uac00 \uc788\ub294 \ubd80\ubd84\uc744 \ud655\ub300\ud558\uba74 \uac00\uc7a5\uc790\ub9ac\uac00 \uc870\uae08 \ud750\ub9bf\ud558\ub2e4. \uac19\uc740 \uc774\ubbf8\uc9c0\ub97c \uac00\ubccd\uac8c \ub9cc\ub4dc\ub294 \uc77c\uc5d0\ub3c4 \uc5b4\ub5a4 \uc815\ubcf4\ub294 \ub0a8\uae30\uace0 \uc5b4\ub5a4 \uc815\ubcf4\ub294 \ub35c \ub0a8\uae38\uc9c0\uc758 \uc120\ud0dd\uc774 \uc228\uc5b4 \uc788\ub2e4. JPEG\ub294 \ub514\uc9c0\ud138 \uc0ac\uc9c4\uc5d0\uc11c \ub110\ub9ac \ub9cc\ub098\ub294 \uc774\ub984\uc774\ub2e4. \uc0ac\uc9c4\uc744 \uc791\uac8c \ub9cc\ub4dc\ub294 \ub9c8\uc220 \uc0c1\uc790\ub77c\uae30\ubcf4\ub2e4, \uc0ac\ub78c\uc758 \ub208\uc774 \ubb34\uc5c7\uc5d0 \ubbfc\uac10\ud558\uace0 \uc5b4\ub5a4 \ucc28\uc774\ub294 \ub35c \uc54c\uc544\ucc28\ub9ac\ub294\uc9c0\ub97c \uc774\uc6a9\ud558\ub294 \uc5ec\ub7ec \uc57d\uc18d\uc758 \ubb36\uc74c\uc774\ub2e4. \ubcf5\uc7a1\ud55c \uc218\uc2dd\uc744 \ubab0\ub77c\ub3c4 \uadf8 \ud0c0\ud611\uc758 \uc131\uaca9\uc740 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \ud654\uba74 \uc18d \uc0ac\uc9c4\uc740 \ub9ce\uc740 \ud654\uc18c, \uace7 \uc791\uc740 \uc810\uc758 \uc815\ubcf4\ub85c \ud45c\ud604\ub41c\ub2e4. \uc0ac\uc9c4\uc774 \ucee4\uc9c0\uace0 \uc0c9\uc758 \uc815\ubcf4\ub97c \uc790\uc138\ud788 \ub0a8\uae38\uc218\ub85d \ub2e4\ub8e8\uc5b4\uc57c \ud560 \ub370\uc774\ud130\ub3c4 \ub9ce\uc544\uc9c4\ub2e4. \ud30c\uc77c\uc744 \uac00\ubccd\uac8c \ub9cc\ub4e4\ub824\uba74 \uac19\uc740 \uc815\ubcf4\ub97c \ub354 \ud6a8\uc728\uc801\uc73c\ub85c \uc801\uac70\ub098 \uc815\ubcf4\uc758 \uc77c\ubd80\ub97c \ub35c \ub0a8\uae30\ub294 \ubc29\ubc95\uc744 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ub450 \ubc29\ubc95\uc740 \uacb0\uacfc\uac00 \ub2e4\ub974\ub2e4. \uc6d0\ub798 \ub0b4\uc6a9\uc744 \uc815\ud655\ud788 \ub2e4\uc2dc \ub9cc\ub4e4 \uc218 \uc788\uac8c \uc904\uc774\ub294 \ubc29\uc2dd\ub3c4 \uc788\uace0, \ubcf5\uc6d0\ud588\uc744 \ub54c \ucc98\uc74c\uacfc \uc644\uc804\ud788 \uac19\uc740 \ud654\uc18c\uac00 \ub418\uc9c0\ub294 \uc54a\ub294 \ubc29\uc2dd\ub3c4 \uc788\ub2e4. \uc77c\uc0c1\uc5d0\uc11c \ub110\ub9ac \uc4f0\ub294 JPEG \uc0ac\uc9c4 \uc555\ucd95\uc740 \ubcf4\ud1b5 \ub4a4\ucabd\uc5d0 \ud574\ub2f9\ud55c\ub2e4. \uc774\ub97c \uc190\uc2e4 \uc555\ucd95\uc774\ub77c\uace0 \ubd80\ub978\ub2e4. \uc0ac\ub78c\uc758 \uc2dc\uac01\uc740 \ubc1d\uae30\uc758 \uc138\ubd80\uc640 \uc0c9\uc758 \uc138\ubd80\ub97c \ub611\uac19\uc774 \ubc1b\uc544\ub4e4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uc77c\ubc18\uc801\uc778 JPEG \ucc98\ub9ac\uc5d0\uc11c\ub294 \uc774\ub7f0 \ucc28\uc774\ub97c \uc774\uc6a9\ud574 \uc0c9 \uc815\ubcf4\uc758 \uc815\ubc00\ub3c4\ub97c \ub0ae\ucd94\uae30\ub3c4 \ud55c\ub2e4. \ub35c \ubbfc\uac10\ud558\uac8c \ub290\ub07c\ub294 \ubd80\ubd84\uc744 \uc904\uc5ec \uc804\uccb4 \ud06c\uae30\ub97c \uc904\uc774\ub294 \uac83\uc774\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc0ac\uc9c4\uc5d0\uc11c \ubcc4\ub85c \uc911\uc694\ud558\uc9c0 \uc54a\uc740 \ubb3c\uac74\uc744 \uc54c\uc544\ubcf4\uace0 \uc9c0\uc6b4\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc5ec\ud589 \uc0ac\uc9c4\uc758 \uc8fc\uc778\uacf5\uacfc \ubc30\uacbd\uc744 \uc0ac\ub78c\ucc98\ub7fc \uc774\ud574\ud574 \uace0\ub974\ub294 \uacfc\uc815\uacfc\ub294 \ub2e4\ub974\ub2e4. \uc0c9\uacfc \ubc1d\uae30\uc758 \ubcc0\ud654 \uac19\uc740 \uc218\uce58\uc758 \uc131\uc9c8\uc744 \ub2e4\ub8ec\ub2e4. \uc758\ubbf8\uac00 \uc911\uc694\ud574 \ubcf4\uc774\ub294 \uae00\uc528\ub3c4 \uc555\ucd95 \ubc29\uc2dd\uc5d0 \ub530\ub77c \uc120\uba85\ud568\uc744 \uc783\uc744 \uc218 \uc788\ub2e4. \uc0ac\uc9c4\uc758 \uc77c\uc815\ud55c \uc601\uc5ed\uc5d0\uc11c \uc0c9\uacfc \ubc1d\uae30\uac00 \ubcc0\ud558\ub294 \ubaa8\uc2b5\uc744 \ub2e4\ub978 \ud615\ud0dc\uc758 \uc218\uce58\ub85c \ud45c\ud604\ud558\uace0, \uadf8\uc911 \uc77c\ubd80\ub97c \ub35c \uc815\ubc00\ud558\uac8c \ub0a8\uae30\ub294 \uacfc\uc815\uc774 \uc788\ub2e4. \uc5ec\uae30\uc11c \ud30c\uc77c\uc758 \ud06c\uae30\uc640 \uc2dc\uac01\uc801 \ucda9\uc2e4\ub3c4 \uc0ac\uc774\uc758 \ud0c0\ud611\uc774 \uc0dd\uae34\ub2e4. \ubaa8\ub4e0 \uacc4\uc0b0\uc744 \ub530\ub77c\uac00\uae30\ubcf4\ub2e4 \uc815\ubcf4\ub97c \uac70\uce60\uac8c \uae30\ub85d\ud560 \uc218 \uc788\ub2e4\ub294 \uc810\uc744 \uae30\uc5b5\ud558\uba74 \ub41c\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \ube44\uc2b7\ud55c \ud558\ub298\uc0c9\uc774 \uc774\uc5b4\uc9c0\ub294 \ub113\uc740 \ubd80\ubd84\uacfc \uac80\uc740 \uae00\uc528\uc758 \ub0a0\uce74\ub85c\uc6b4 \uacbd\uacc4\ub294 \uc131\uc9c8\uc774 \ub2e4\ub974\ub2e4. \uc555\ucd95\uc5d0 \uc798 \ub9de\ub294 \uc0ac\uc9c4\uc5d0\uc11c\ub294 \ub370\uc774\ud130\ub97c \ub9ce\uc774 \uc904\uc5ec\ub3c4 \ubcc0\ud654\uac00 \ub208\uc5d0 \uc798 \ub744\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \ubc18\ub300\ub85c \uc791\uc740 \uc138\ubd80\uc640 \uac15\ud55c \uacbd\uacc4\uac00 \ub9ce\uc740 \uacf3\uc5d0\uc11c\ub294 \uadf8 \ud754\uc801\uc774 \ub354 \uc27d\uac8c \ub4dc\ub7ec\ub09c\ub2e4. \uc0ac\uc9c4\uc744 \uc544\uc8fc \uc791\uac8c \ub9cc\ub4e4\uba74 \uae00\uc790\uc758 \ud14c\ub450\ub9ac\ub098 \ubb3c\uccb4\uc758 \uac00\uc7a5\uc790\ub9ac \uc8fc\ubcc0\uc5d0 \ubc88\uc9c0\ub294 \ub4ef\ud55c \ud754\uc801\uc774 \ubcf4\uc774\uae30\ub3c4 \ud55c\ub2e4. \ud655\ub300\ud588\uc744 \ub54c \uc791\uc740 \ube14\ub85d\uc758 \uacbd\uacc4\uac00 \ub4dc\ub7ec\ub0a0 \uc218\ub3c4 \uc788\ub2e4. \uc555\ucd95 \uacfc\uc815\uc5d0\uc11c \ub35c \ub0a8\uae34 \uc815\ubcf4\uac00 \uacb0\uacfc \ud654\uba74\uc5d0 \ub098\ud0c0\ub098\ub294 \ubaa8\uc2b5\uc774\ub2e4. JPEG \uad6c\ud604 \ubb38\uc11c\ub3c4 \ubd80\ub4dc\ub7fd\uac8c \uc0c9\uacfc \ubc1d\uae30\uac00 \ubc14\ub00c\ub294 \uc0ac\uc9c4\uc774 \uac15\uc810\uc774\uace0, \ub0a0\uce74\ub85c\uc6b4 \uc120\uc774\ub098 \uac11\uc790\uae30 \ubc14\ub00c\ub294 \ubd80\ubd84\uc5d0\uc11c\ub294 \ub208\uc5d0 \ub744\ub294 \ud754\uc801\uc744 \ud53c\ud558\uae30 \uc704\ud574 \ub354 \ub192\uc740 \ud488\uc9c8\uc774 \ud544\uc694\ud560 \uc218 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc120\uba85\ud55c \ub3c4\ud45c\uc640 \uc791\uc740 \uae00\uc528\uac00 \uc911\uc2ec\uc778 \ud654\uba74\uc740 \ud48d\uacbd \uc0ac\uc9c4\uacfc \ub2e4\ub974\uac8c \ub2e4\ub8f0 \uc774\uc720\uac00 \uc788\ub294 \uc148\uc774\ub2e4. \uc774\ubbf8\uc9c0\ub97c \uc800\uc7a5\ud560 \ub54c \ud488\uc9c8\uc744 \uc22b\uc790\ub85c \uace0\ub974\ub294 \ud504\ub85c\uadf8\ub7a8\uc774 \uc788\ub2e4. \ubcf4\ud1b5 \ub354 \ub192\uc740 \uc124\uc815\uc740 \uc815\ubcf4\ub97c \ub354 \ucda9\uc2e4\ud788 \ub0a8\uae30\uace0 \ud30c\uc77c\ub3c4 \ucee4\uc9c0\uac8c \ud558\uc9c0\ub9cc, \uc11c\ub85c \ub2e4\ub978 \ud504\ub85c\uadf8\ub7a8\uc758 \uac19\uc740 \uc22b\uc790\uac00 \uc644\uc804\ud788 \uac19\uc740 \uacb0\uacfc\ub97c \ubcf4\uc7a5\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8 \uc22b\uc790\ub9cc \ubcf4\uace0 \ubaa8\ub4e0 \ud30c\uc77c\uc744 \uacf5\ud1b5 \uae30\uc900\uc73c\ub85c \ube44\uad50\ud558\uae30\ub294 \uc5b4\ub835\ub2e4. \uc6d0\ub798\ubd80\ud130 \uc791\uc740 \uc0ac\uc9c4\uc744 \ub192\uc740 \ud488\uc9c8\ub85c \uc800\uc7a5\ud55c\ub2e4\uace0 \ucd2c\uc601\ud558\uc9c0 \uc54a\uc740 \uc138\ubd80\uac00 \ub418\uc0b4\uc544\ub098\ub294 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \ubcf4\uad00\ub41c \uc815\ubcf4\ubcf4\ub2e4 \ub354 \ub9ce\uc740 \uc2e4\uc81c \ub0b4\uc6a9\uc744 \uc790\ub3d9\uc73c\ub85c \ub418\ucc3e\uc744 \uc218\ub294 \uc5c6\ub2e4. \uc800\uc7a5 \uc124\uc815\uc740 \ub0a8\uc544 \uc788\ub294 \uc790\ub8cc\ub97c \uc5b4\ub5bb\uac8c \ucc98\ub9ac\ud560\uc9c0\uc758 \uc120\ud0dd\uc774\uc9c0 \uc774\ubbf8 \uc783\uc5b4\ubc84\ub9b0 \uc7a5\uba74\uc744 \ub418\ub3cc\ub9ac\ub294 \uc2dc\uac04 \uc5ec\ud589\uc774 \uc544\ub2c8\ub2e4. \uc0ac\uc9c4\uc744 \uc5f4\uc5b4 \ub0b4\uc6a9\uc744 \ubc14\uafbc \ub4a4 \ub2e4\uc2dc \uc190\uc2e4 \uc555\ucd95\ud558\uba74 \uc774\ubbf8 \ud55c \ubc88 \ub2ec\ub77c\uc9c4 \uc815\ubcf4\ub97c \ubc14\ud0d5\uc73c\ub85c \ub610 \uae30\ub85d\ud55c\ub2e4. \uc5ec\ub7ec \ucc28\ub840\uc758 \uc7ac\uc555\ucd95\uc740 \uc6d0\ubcf8\uacfc\uc758 \ucc28\uc774\ub97c \ub354 \ub9cc\ub4e4 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ud30c\uc77c\uc744 \uadf8\ub0e5 \ubcf5\uc0ac\ud558\uac70\ub098 \uc62e\uae34\ub2e4\uace0 \ub9e4\ubc88 \uc0ac\uc9c4\uc774 \ud750\ub824\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub2e4\uc2dc \uc555\ucd95\ud558\ub294 \uacfc\uc815\uc774 \uc788\ub294\uc9c0\ub97c \uad6c\ubcc4\ud574\uc57c \ud55c\ub2e4. JPEG\ub77c\ub294 \uc774\ub984 \uc544\ub798\uc5d0\ub3c4 \uc5ec\ub7ec \uae30\ub2a5\uacfc \ubcc0\ud615\uc774 \uc788\ub2e4. \uad6c\ud604 \ubb38\uc11c\ub294 \uc190\uc2e4 \uc5c6\uc774 \ucc98\ub9ac\ud558\ub294 \uae30\ub2a5\ub3c4 \uc124\uba85\ud55c\ub2e4. \ub530\ub77c\uc11c \uc774\ub984\ub9cc \ubcf4\uace0 \uac00\ub2a5\ud55c \ubaa8\ub4e0 \ucc98\ub9ac \uacfc\uc815\uc744 \ud558\ub098\ub85c \ub2e8\uc815\ud558\uae30\ubcf4\ub2e4, \uc5ec\uae30\uc11c\ub294 \ud754\ud788 \uc4f0\uc774\ub294 \uc190\uc2e4 \uc555\ucd95 \uc0ac\uc9c4\uc758 \uacbd\ud5d8\uc744 \uc774\uc57c\uae30\ud558\uace0 \uc788\ub2e4\ub294 \ubc94\uc704\ub97c \uae30\uc5b5\ud558\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc774\ubbf8\uc9c0\uac00 \ub108\ubb34 \ud06c\uba74 \uc800\uc7a5\ud560 \uacf5\uac04\uacfc \ubcf4\ub0b4\ub294 \uc2dc\uac04\uc774 \ub9ce\uc774 \ud544\uc694\ud558\ub2e4. \uc0ac\uc9c4\uc758 \uc77c\ubd80 \uc815\ubcf4\ub97c \ub35c \ub0a8\uae30\ub294 \ud0c0\ud611\uc740 \ub354 \ub9ce\uc740 \uc0ac\ub78c\uc774 \uc0ac\uc9c4\uc744 \uc8fc\uace0\ubc1b\uace0 \uc6f9\uc5d0\uc11c \ubcfc \uc218 \uc788\uac8c \ud558\ub294 \ub370 \uc758\ubbf8\uac00 \uc788\uc5c8\ub2e4. \uc815\ud655\ud788 \uac19\uc740 \ud654\uc18c\ub97c \uc720\uc9c0\ud558\ub294 \ubaa9\uc801\uacfc \uc77c\uc0c1\uc5d0\uc11c \ube60\ub974\uac8c \ubcf4\ub294 \ubaa9\uc801\uc774 \uc5b8\uc81c\ub098 \uc77c\uce58\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubc18\uba74 \uc791\uc740 \uae00\uc528\uac00 \ub2f4\uae34 \uae30\ub85d\uc774\ub098 \uc815\ubc00\ud55c \uad00\ucc30 \uc790\ub8cc\uc5d0\uc11c\ub294 \uc0ac\uc18c\ud574 \ubcf4\uc774\ub294 \ud754\uc801\ub3c4 \ubb38\uc81c\uac00 \ub420 \uc218 \uc788\ub2e4. \uc5b4\ub5a4 \ud615\uc2dd\uc774 \uc5b8\uc81c\ub098 \ucd5c\uace0\ub77c\uace0 \uc678\uc6b0\uae30\ubcf4\ub2e4 \ubb34\uc5c7\uc744 \ubcf4\uc874\ud574\uc57c \ud558\ub294 \uc0ac\uc9c4\uc778\uc9c0 \ubb3b\ub294 \ud3b8\uc774 \uc774\ud574\uc5d0 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \uc88b\uc740 \uc555\ucd95\uc740 \ubaa9\uc801\uacfc \ub9de\ub294 \ud0c0\ud611\uc77c \ub54c \uc88b\uc740 \uacb0\uacfc\uac00 \ub41c\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\uc740 \uc0ac\uc9c4\uacfc \uc555\ucd95\uc758 \uad00\uacc4\ub97c \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 AI \uc0bd\ud654\ub2e4. \uac00\uc7a5\uc790\ub9ac\uc758 \uc0c9 \uc870\uac01\uc740 \uc2e4\uc81c JPEG \uc2e4\ud5d8 \uacb0\uacfc\ub098 \uac19\uc740 \uc6d0\ubcf8\uc758 \ud488\uc9c8 \ube44\uad50 \uc790\ub8cc\uac00 \uc544\ub2c8\ub2e4. \uc815\ud655\ud55c \uc131\ub2a5\uc744 \ube44\uad50\ud558\ub294 \ub3c4\ud45c\ucc98\ub7fc \uc77d\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub2e4\uc74c\uc5d0 \uc791\uc740 \uc0ac\uc9c4 \ud30c\uc77c\uc744 \uc5f4 \ub54c\ub294 \uadf8 \uc548\uc758 \ud48d\uacbd\ubfd0 \uc544\ub2c8\ub77c \ub0a8\uaca8\uc9c4 \uc815\ubcf4\uc640 \ub35c \ub0a8\uaca8\uc9c4 \uc815\ubcf4\ub3c4 \uc0dd\uac01\ud574 \ubcf4\uc790. \ud654\uba74\uc5d0\uc11c \ucda9\ubd84\ud788 \uc790\uc5f0\uc2a4\ub7ec\uc6cc \ubcf4\uc778\ub2e4\ub294 \uac83\uc740 \ubaa8\ub4e0 \uc815\ubcf4\uac00 \uadf8\ub300\ub85c\ub77c\ub294 \ub73b\uacfc \ub2e4\ub974\ub2e4. \ub514\uc9c0\ud138 \uae30\uc220\uc758 \ud765\ubbf8\ub85c\uc6b4 \ubd80\ubd84\uc740 \uc885\uc885 \uc644\ubcbd\ud558\uac8c \ub611\uac19\uc740 \uac83\ubcf4\ub2e4 \uc0c1\ud669\uc5d0 \ub9de\uac8c \ucda9\ubd84\ud788 \uc88b\uc740 \uac83\uc744 \ub9cc\ub4dc\ub294 \ub370 \uc788\ub2e4."}, {"id": "linux-shared-kernel", "title": "\ub9ac\ub205\uc2a4 \u2014 \ud3ad\uadc4 \ub4a4\uc5d0\ub294 \ub204\uac00 \uc77c\ud558\uace0 \uc788\uc744\uae4c", "summary": "\ucee4\ub110\uc758 \uc5ed\ud560\uacfc \uc2e4\uc81c \uac1c\ubc1c \ubb38\uc11c\ub97c \ud1b5\ud574 \uc5f4\ub9b0 \ud611\uc5c5\uc5d0 \ud544\uc694\ud55c \uac80\ud1a0\uc640 \ucc45\uc784\uc758 \uad6c\uc870\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "computing", "category_title": "Computing", "subcategory": "Computers", "url": "stories/linux-shared-kernel/index.html", "image": "media/linux-shared-kernel.png", "alt": "\ub798\ub9ac \uc720\uc789\uc758 \uc6d0\uc791\uc744 \uac1c\ub9bf \ub974\uc0ac\uc8fc\uac00 \uc7ac\uc791\uc5c5\ud558\uace0 IFo Hancroft\uac00 \ub2e4\ub4ec\uc740 \ub9ac\ub205\uc2a4 \ud3ad\uadc4 \ud131\uc2a4\uc758 \uc2e4\uc81c \uacf5\uac1c \uc774\ubbf8\uc9c0.", "text": "\ub9ac\ub205\uc2a4 \u2014 \ud3ad\uadc4 \ub4a4\uc5d0\ub294 \ub204\uac00 \uc77c\ud558\uace0 \uc788\uc744\uae4c \ud568\uaed8 \uace0\uce58\ub418 \uc544\ubb34\ub807\uac8c\ub098 \ubc14\uafb8\uc9c0\ub294 \uc54a\ub294 \uc18c\ud504\ud2b8\uc6e8\uc5b4 \ucee4\ub110\uc758 \uc5ed\ud560\uacfc \uc2e4\uc81c \uac1c\ubc1c \ubb38\uc11c\ub97c \ud1b5\ud574 \uc5f4\ub9b0 \ud611\uc5c5\uc5d0 \ud544\uc694\ud55c \uac80\ud1a0\uc640 \ucc45\uc784\uc758 \uad6c\uc870\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Computers \ucef4\ud4e8\ud305 \ub178\ub780 \ubd80\ub9ac\ub97c \uac00\uc9c4 \ud3ad\uadc4 \uadf8\ub9bc\uc744 \ubcf4\uba74 \ucef4\ud4e8\ud130\ub97c \ub5a0\uc62c\ub9ac\ub294 \uc0ac\ub78c\uc774 \uc788\ub2e4. \ub9ac\ub205\uc2a4\uc640 \ud568\uaed8 \ub110\ub9ac \uc54c\ub824\uc9c4 \ud131\uc2a4\ub2e4. \uadf8\ub9bc\uc740 \uce5c\uadfc\ud558\uc9c0\ub9cc \uadf8 \ub4a4\uc5d0 \uc788\ub294 \uc18c\ud504\ud2b8\uc6e8\uc5b4\ub294 \uc218\ub9ce\uc740 \uc7a5\uce58\uc640 \uc791\uc5c5\uc744 \uc870\uc815\ud574\uc57c \ud55c\ub2e4. \uc5ec\ub7ec \uc0ac\ub78c\uc774 \ud568\uaed8 \ub9cc\ub4e0\ub2e4\uace0 \ud558\ub294\ub370, \ubaa8\ub450\uac00 \ub9c8\uc74c\ub300\ub85c \uace0\uce58\uba74 \uc5b4\ub5bb\uac8c \ud558\ub098\uc758 \ud504\ub85c\uadf8\ub7a8\uc73c\ub85c \uc6c0\uc9c1\uc77c \uc218 \uc788\uc744\uae4c. \ub9ac\ub205\uc2a4\ub97c \uc774\ud574\ud558\ub294 \uccab\uac78\uc74c\uc740 \uc5b4\ub824\uc6b4 \uba85\ub839\uc5b4\ubcf4\ub2e4 \ud568\uaed8 \uc77c\ud558\ub294 \ubc29\uc2dd\uc744 \ubcf4\ub294 \ub370 \uc788\ub2e4. \uc2e4\uc81c \uac1c\ubc1c \uc548\ub0b4\uc5d0\ub294 \ubb34\uc5c7\uc744 \ub9cc\ub4e4\uc9c0\ubfd0 \uc544\ub2c8\ub77c \uc5b4\ub5bb\uac8c \uc81c\uc548\ud558\uace0 \ub204\uad6c\uc5d0\uac8c \ubcf4\uc5ec \uc8fc\uba70 \uc5b4\ub5a4 \uac80\ud1a0\ub97c \uac70\uce60\uc9c0\uac00 \uae38\uac8c \uc801\ud600 \uc788\ub2e4. \uc5f4\ub9b0 \ud611\uc5c5\uc5d0\ub3c4 \uc9c8\uc11c\uc640 \ucc45\uc784\uc774 \ud544\uc694\ud558\uae30 \ub54c\ubb38\uc774\ub2e4. \ub9ac\ub205\uc2a4 \ucee4\ub110\uc758 \uacf5\uc2dd \uc18c\uac1c\ub294 \ucee4\ub110\uc744 \uc6b4\uc601\uccb4\uc81c\uc758 \ud575\uc2ec\uc73c\ub85c \uc124\uba85\ud55c\ub2e4. \uae30\uacc4\uc758 \uc790\uc6d0\uacfc \uc7a5\uce58\ub97c \uad00\ub9ac\ud558\uace0 \ub2e4\ub978 \uc18c\ud504\ud2b8\uc6e8\uc5b4\uac00 \uc774\uc6a9\ud560 \uae30\ubcf8 \uc11c\ube44\uc2a4\ub97c \uc81c\uacf5\ud55c\ub2e4. \ubb38\uc11c \uc791\uc131 \ud504\ub85c\uadf8\ub7a8\uc774 \ud654\uba74\uc5d0\uc11c \uac00\uc7a5 \ub208\uc5d0 \ub744\uc5b4\ub3c4 \uadf8 \uc544\ub798\uc5d0\uc11c\ub294 \uba54\ubaa8\ub9ac\uc640 \uc7a5\uce58\ub97c \ub2e4\ub8e8\ub294 \uc77c\uc774 \uacc4\uc18d\ub41c\ub2e4. \ucee4\ub110\uc744 \uc77c\uc0c1\uc5d0 \ube44\uc720\ud558\uba74 \uc5ec\ub7ec \ud65c\ub3d9\uc774 \uac19\uc740 \uc2dc\uc124\uc744 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub3c4\ub85d \uc870\uc815\ud558\ub294 \uae30\ucd08 \uc6b4\uc601\uc5d0 \uac00\uae5d\ub2e4. \ub2e4\ub9cc \ube44\uc720\uac00 \uc815\ud655\ud55c \uc124\uacc4\ub3c4\ub294 \uc544\ub2c8\ub2e4. \uc5ec\uae30\uc11c \uc911\uc694\ud55c \uac83\uc740 \ud654\uba74\uc758 \ubaa8\uc591\uc744 \uc815\ud558\ub294 \ud504\ub85c\uadf8\ub7a8\uacfc \ucef4\ud4e8\ud130\uc758 \uae30\ubcf8 \uc791\ub3d9\uc744 \ub9e1\ub294 \ubd80\ubd84\uc774 \uac19\uc9c0 \uc54a\ub2e4\ub294 \uc810\uc774\ub2e4. \uc77c\uc0c1\uc5d0\uc11c\ub294 \ub9ac\ub205\uc2a4\ub77c\ub294 \ub9d0\uc744 \ud558\ub098\uc758 \uc644\uc131\ub41c \uc6b4\uc601\uccb4\uc81c\ucc98\ub7fc \uc4f0\uae30\ub3c4 \ud55c\ub2e4. \uc5c4\ubc00\ud558\uac8c \ucee4\ub110\uc744 \uac00\ub9ac\ud0a4\ub294 \uacbd\uc6b0\uc640, \ucee4\ub110\uc5d0 \uc5ec\ub7ec \ud504\ub85c\uadf8\ub7a8\uc744 \ub354\ud574 \uc0ac\uc6a9\ud560 \uc218 \uc788\uac8c \ubb36\uc740 \ubc30\ud3ec\ud310\uc744 \uac00\ub9ac\ud0a4\ub294 \uacbd\uc6b0\ub97c \uad6c\ubd84\ud558\uba74 \ud63c\ub3d9\uc774 \uc904\uc5b4\ub4e0\ub2e4. \uac19\uc740 \ud575\uc2ec \uc704\uc5d0 \uc11c\ub85c \ub2e4\ub978 \uad6c\uc131\uc774 \ub193\uc77c \uc218 \uc788\ub2e4. \ub530\ub77c\uc11c \ub9ac\ub205\uc2a4\ub77c\ub294 \uc774\ub984\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \ucef4\ud4e8\ud130\uc758 \ud654\uba74\uacfc \uc0ac\uc6a9\ubc95\uc774 \uac19\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5b4\ub5a4 \ud504\ub85c\uadf8\ub7a8\uc744 \ud568\uaed8 \ubb36\uace0 \uc5b4\ub5bb\uac8c \uc5c5\ub370\uc774\ud2b8\ud558\uba70 \uc5b4\ub5a4 \uc0ac\uc6a9\uc790\ub97c \ub3d5\ub294\uc9c0\uc5d0 \ub530\ub77c \uacbd\ud5d8\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \ud558\ub098\uc758 \uae30\uc220\uacfc \uadf8\uac83\uc744 \uc0ac\uc6a9\ud558\uae30 \uc88b\uc740 \uc0c1\ud0dc\ub85c \uafb8\ub9ac\ub294 \uc77c\uc740 \uc774\uc5b4\uc838 \uc788\uc9c0\ub9cc \uac19\uc740 \uc791\uc5c5\uc740 \uc544\ub2c8\ub2e4. \ub9ac\ub205\uc2a4\uc758 \ucd08\uae30 \uc5ed\uc0ac\ub294 \ub9ac\ub204\uc2a4 \ud1a0\ub974\ubc1c\uc2a4\uc640 \uc5f0\uacb0\ub41c\ub2e4. \uae43\uc758 \uc5ed\uc0ac \uc548\ub0b4\ub294 1991\ub144\ubd80\ud130 \uc774\uc5b4\uc9c4 \ucd08\uae30 \ub9ac\ub205\uc2a4 \ucee4\ub110 \uac1c\ubc1c\uc5d0\uc11c \uc218\uc815 \ub0b4\uc6a9\uc744 \ud328\uce58\uc640 \ud30c\uc77c\ub85c \uc8fc\uace0\ubc1b\uc558\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ucc98\uc74c\uc758 \uc2dc\uc791\uc744 \uae30\uc5b5\ud558\ub294 \uac83\uacfc \uc624\ub298\uc758 \uacb0\uacfc\ub97c \ud55c \uc0ac\ub78c\uc758 \uc791\uc5c5\uc73c\ub85c \uc124\uba85\ud558\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \uacf5\uc2dd \uc548\ub0b4\uc5d0\ub294 \uc5ec\ub7ec \ubd84\uc57c\uc758 \uad00\ub9ac\uc790\uac00 \ub4f1\uc7a5\ud55c\ub2e4. \uc7a5\uce58\uc640 \uae30\ub2a5\uc774 \ub9ce\uc544\uc9c0\uba74 \ubaa8\ub4e0 \ubcc0\uacbd\uc744 \ud55c \uc0ac\ub78c\uc774 \uac19\uc740 \uae4a\uc774\ub85c \uc0b4\ud53c\uae30 \uc5b4\ub835\ub2e4. \ub2f4\ub2f9 \ubd80\ubd84\uc744 \uc798 \uc544\ub294 \uc0ac\ub78c\ub4e4\uc774 \uc81c\uc548\uc744 \uc77d\uace0 \ub354 \ud070 \ud750\ub984\uc73c\ub85c \uc5f0\uacb0\ud55c\ub2e4. \ud070 \ud611\uc5c5\uc740 \ucc38\uc5ec\uc790\uc758 \uc218\ubfd0 \uc544\ub2c8\ub77c \uac80\ud1a0\uc758 \uacbd\ub85c\ub3c4 \ud568\uaed8 \ucee4\uc838\uc57c \ud55c\ub2e4. \uc18c\uc2a4 \ucf54\ub4dc\uac00 \uacf5\uac1c\ub418\uc5b4 \uc788\uc73c\uba74 \uad00\uc2ec \uc788\ub294 \uc0ac\ub78c\uc774 \uc2e4\uc81c \ub0b4\uc6a9\uc744 \uc0b4\ud3b4\ubcf4\uace0 \ubb38\uc81c\ub97c \uc870\uc0ac\ud558\uac70\ub098 \uc218\uc815\uc548\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub2e4. \uac1c\ubc1c \uc548\ub0b4\ub294 \ub9ac\ub205\uc2a4 \ucee4\ub110\uc758 \ucf54\ub4dc\uac00 GPL\uc5d0 \ub530\ub77c \uc81c\uacf5\ub41c\ub2e4\uace0 \ubc1d\ud78c\ub2e4. \uacf5\uac1c\ub294 \uc774\uc6a9\uacfc \ubc30\ud3ec\uc758 \uc870\uac74\uc744 \uac00\uc9c4 \ud615\ud0dc\uc774\uba70 \uc870\uac74\uc774 \uc804\ud600 \uc5c6\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ub204\uad6c\ub098 \ub0b4\uc6a9\uc744 \ubcfc \uc218 \uc788\ub2e4\ub294 \uc810\uc740 \uc911\uc694\ud558\uc9c0\ub9cc \uadf8\uac83\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uc624\ub958\uac00 \uc989\uc2dc \uc0ac\ub77c\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc77d\uc744 \uc0ac\ub78c\uc758 \uc9c0\uc2dd\uacfc \uc2dc\uac04\ub3c4 \ud544\uc694\ud558\uace0 \uc218\uc815 \ub4a4\uc5d0 \ub2e4\ub978 \ubb38\uc81c\uac00 \uc0dd\uae30\ub294\uc9c0 \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \uacf5\uac1c \uc5ec\ubd80\uc640 \uac80\ud1a0\uc758 \ucda9\ubd84\ud568\uc744 \uac19\uc740 \ub9d0\ub85c \ucde8\uae09\ud558\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc815\ud655\ud558\ub2e4. \uac1c\ubc1c \ubb38\uc11c\ub294 \ucf54\ub4dc\uc758 \ud615\uc2dd\uacfc \uc218\uc815\uc548 \uc81c\ucd9c \ubc29\ubc95\uc744 \uc124\uba85\ud55c\ub2e4. \uc81c\uc548\ud55c \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc544\uc8fc \uc791\uc740 \ubcc0\ud654\ub77c\ub3c4 \uac80\ud1a0\ud558\ub294 \uc0ac\ub78c\uc740 \uc774\uc720\uc640 \uc601\ud5a5\uc744 \uc54c\uc544\uc57c \ud55c\ub2e4. \uc815\ud574\uc9c4 \ubc29\uc2dd\uc73c\ub85c \uc124\uba85\ud558\uace0 \ubcf4\ub0b4\ub294 \uac83\uc740 \ud615\uc2dd\ub9cc\uc744 \uc704\ud55c \uc608\uc808\uc774 \uc544\ub2c8\ub77c \uc5ec\ub7ec \uc0ac\ub78c\uc774 \ub0b4\uc6a9\uc744 \ube44\uad50\ud560 \uc218 \uc788\uac8c \ud558\ub294 \ub3c4\uad6c\ub2e4. \uc88b\uc740 \uc81c\uc548\uc774\ub77c\uace0 \ud574\uc11c \uc790\ub3d9\uc73c\ub85c \ubc1b\uc544\ub4e4\uc5ec\uc9c0\ub294 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \uae30\uc874 \uae30\ub2a5\uacfc \ucda9\ub3cc\ud558\uac70\ub098 \ub2e4\ub978 \ud658\uacbd\uc5d0 \ubb38\uc81c\uac00 \uc0dd\uae38 \uc218 \uc788\ub2e4. \ud568\uaed8 \uace0\uce5c\ub2e4\ub294 \ub9d0\uc5d0\ub294 \ud568\uaed8 \uac70\uc808\ud558\uace0 \ub2e4\uc2dc \uc124\uba85\ud558\uba70 \ub354 \ub098\uc740 \uc81c\uc548\uc744 \uae30\ub2e4\ub9ac\ub294 \uc77c\ub3c4 \ub4e4\uc5b4 \uc788\ub2e4. \uc5f4\ub9b0 \ubb38\uc740 \uac80\ud1a0\uac00 \uc5c6\ub294 \ubb38\uacfc \ub2e4\ub974\ub2e4. \uacf5\uc2dd \uc548\ub0b4\ub294 \ud070 \ubcc0\uacbd\uc744 \ubc1b\uc544\ub4e4\uc774\ub294 \uc2dc\uae30\uc640 \uadf8 \ub4a4\uc758 \ud6c4\ubcf4 \ubc84\uc804\uc744 \uc124\uba85\ud55c\ub2e4. \uc0c8\ub85c\uc6b4 \uae30\ub2a5\uc744 \ubaa8\uc73c\ub294 \uc77c\ub9cc \uacc4\uc18d\ud558\uba74 \uae30\uc874\uc5d0 \ub418\ub358 \uac83\uc774 \uac11\uc790\uae30 \uc548 \ub418\ub294 \ubb38\uc81c\ub97c \ub193\uce60 \uc218 \uc788\ub2e4. \ubcc0\ud654\uac00 \uc5b4\ub290 \uc815\ub3c4 \ubaa8\uc774\uba74 \uc81c\ub300\ub85c \uc791\ub3d9\ud558\ub294\uc9c0 \ub2e4\ub4ec\ub294 \uc2dc\uac04\uc774 \ud544\uc694\ud558\ub2e4. \uc774\uc804\uc5d0\ub294 \uc798\ub418\ub358 \uae30\ub2a5\uc774 \ubcc0\uacbd \ub4a4\uc5d0 \ub9dd\uac00\uc9c0\ub294 \uc77c\uc744 \ud68c\uadc0 \ubb38\uc81c\ub77c\uace0 \ubd80\ub978\ub2e4. \uc0c8\ub85c \ubb34\uc5b8\uac00\ub97c \ub354\ud588\ub2e4\ub294 \uc18c\uc2dd\ub9cc\ud07c \ud558\ub358 \uc77c\uc774 \uacc4\uc18d \ub41c\ub2e4\ub294 \uc0ac\uc2e4\ub3c4 \uc911\uc694\ud558\ub2e4. \uc0ac\uc6a9\uc790\ub294 \uac1c\ubc1c\uc790\uc758 \uc758\uc695\ubcf4\ub2e4 \uc790\uae30 \uc791\uc5c5\uc774 \uba48\ucd94\uc9c0 \uc54a\ub294 \uac83\uc744 \uba3c\uc800 \uc6d0\ud560 \uc218 \uc788\ub2e4. \uc548\uc815\uc131\ub3c4 \ud611\uc5c5\uc774 \ub9cc\ub4e4\uc5b4\uc57c \ud560 \uacb0\uacfc\ub2e4. \ud568\uaed8 \uc2e4\uc740 \ud131\uc2a4\ub294 \uc0c8\ub85c \uc0c1\uc0c1\ud55c \ud3ad\uadc4\uc774 \uc544\ub2c8\ub77c \uc6d0\uc791\uc744 \ubca1\ud130\ub85c \ub2e4\uc2dc \uadf8\ub9b0 \uc81c\uc791\uc790\uac00 \uacf5\uac1c\ud55c PNG \ud30c\uc77c\uc774\ub2e4. \ub9ac\ub205\uc2a4 \uacf5\uc2dd \uc800\uc7a5\uc18c\uc758 \uc548\ub0b4\uc640 \uc81c\uc791\uc790 \uc124\uba85\uc744 \ud568\uaed8 \ud655\uc778\ud588\ub2e4. \uc6d0\uc791\uc740 \ub798\ub9ac \uc720\uc789, \uc7ac\uc791\uc5c5\uc740 \uac1c\ub9bf \ub974\uc0ac\uc8fc, \ub2e4\ub4ec\uae30\ub294 IFo Hancroft\uc758 \uc791\uc5c5\uc73c\ub85c \ud45c\uc2dc\ub418\uc5b4 \uc788\ub2e4. \uacf5\uc2dd \uc800\uc7a5\uc18c\uc758 \uc774\uc6a9 \uc548\ub0b4\ub294 \uc6d0\uc791\uc790\uc640 \ubca1\ud130 \uc791\uc5c5\uc790\ub97c \ubc1d\ud788\ub3c4\ub85d \ud558\uace0, \uc81c\uc791\uc790 \uc800\uc7a5\uc18c\ub294 \ud37c\ube14\ub9ad \ub3c4\uba54\uc778\u00b7CC0\ub85c \ud45c\uc2dc\ud55c\ub2e4. \uc774 \uae00\ub3c4 \uc138 \uc81c\uc791\uc790\ub97c \ud06c\ub808\ub527\uc5d0 \uc801\uc5c8\ub2e4. \uce5c\uadfc\ud55c \uc0c1\uc9d5\uc5d0\ub3c4 \ucd9c\ucc98\uac00 \uc788\ub2e4. \ub2e4\ub9cc \ud3ad\uadc4 \uadf8\ub9bc\uc774 \uc788\ub2e4\uace0 \ubaa8\ub450 \uac19\uc740 \uc81c\ud488\uc774\uac70\ub098 \uac19\uc740 \uc870\uc9c1\uc758 \ubcf4\uc99d\uc744 \ubc1b\uc558\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ub9ac\ub205\uc2a4\uc758 \ud765\ubbf8\ub85c\uc6b4 \uc810\uc740 \ub2e8\uc21c\ud788 \ub9ce\uc740 \uc0ac\ub78c\uc774 \ucc38\uc5ec\ud588\ub2e4\ub294 \uc22b\uc790\uc5d0 \uc788\uc9c0 \uc54a\ub2e4. \uc218\uc815\uc758 \uc774\uc720\ub97c \uc4f0\uace0, \ub2f4\ub2f9\uc790\uc5d0\uac8c \ubcf4\ub0b4\uace0, \uac80\ud1a0\ud558\uace0, \uae30\uc874 \uae30\ub2a5\uc744 \uc9c0\ud0a4\uba70 \ubb36\uc5b4 \ub0b4\ub294 \uacfc\uc815\uc774 \uc788\ub2e4\ub294 \uc810\uc774\ub2e4. \uacf5\uc720\ub294 \uacb0\uacfc\ub97c \ub098\ub204\ub294 \uc77c\uc774\uba74\uc11c \uc791\uc5c5\uc758 \uaddc\uce59\uc744 \ud568\uaed8 \uc138\uc6b0\ub294 \uc77c\uc774\uae30\ub3c4 \ud558\ub2e4. \ud3ad\uadc4 \ub4a4\uc5d0\ub294 \ub208\uc5d0 \ub744\ub294 \ucc3d\uc2dc\uc790\ubfd0 \uc544\ub2c8\ub77c \uc791\uc740 \ubb38\uc81c\ub97c \ucc3e\uc544 \uc54c\ub9ac\ub294 \uc0ac\ub78c\uacfc \uc124\uba85\uc744 \uace0\uce58\ub294 \uc0ac\ub78c, \ubcc0\uacbd\uc744 \uac80\ud1a0\ud558\ub294 \uc0ac\ub78c\uc774 \uc788\ub2e4. \ucef4\ud4e8\ud130\uac00 \uc870\uc6a9\ud788 \uc81c \uc77c\uc744 \ud558\ub294 \uc21c\uac04\uc5d0\ub3c4 \uadf8 \uc5f0\uacb0\uc774 \uc791\ub3d9\ud558\uace0 \uc788\ub2e4. \uae30\uc220\uc744 \uc774\ud574\ud558\ub294 \uc77c\uc774 \uc0ac\ub78c\ub4e4\uc758 \ud611\uc5c5\uc744 \uc77d\ub294 \uc77c\uc774 \ub418\ub294 \ub300\ubaa9\uc774\ub2e4."}, {"id": "ocr-picture-to-searchable-text", "title": "\ubb38\uc790\uc778\uc2dd \u2014 \uc0ac\uc9c4 \uc18d \uae00\uc790\ub294 \uc65c \ubcf5\uc0ac\uac00 \uc548 \ub420\uae4c", "summary": "\uc2a4\uce94 \uc774\ubbf8\uc9c0\uc640 \ud14d\uc2a4\ud2b8\uc758 \ucc28\uc774\uc5d0\uc11c \ucd9c\ubc1c\ud574 OCR\uc758 \uc4f0\uc784\uacfc \uc624\ub958\u00b7\uac80\ud1a0\uc758 \ud544\uc694\uc131\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.", "category": "computing", "category_title": "Computing", "subcategory": "Software", "url": "stories/ocr-picture-to-searchable-text/index.html", "image": "media/ocr-picture-to-searchable-text.png", "alt": "\uc624\ub798\ub41c \ucc45 \uacc1\uc5d0\uc11c \uc778\uc1c4 \ud398\uc774\uc9c0\uc640 \uc2a4\uce90\ub108\ub97c \uc0b4\ud3b4\ubcf4\ub294 \uc0ac\ub78c\uc758 AI \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\ubb38\uc790\uc778\uc2dd \u2014 \uc0ac\uc9c4 \uc18d \uae00\uc790\ub294 \uc65c \ubcf5\uc0ac\uac00 \uc548 \ub420\uae4c \ub208\uc73c\ub85c \uc77d\ub294 \ud398\uc774\uc9c0\ub97c \ucef4\ud4e8\ud130\uac00 \ucc3e\uc744 \uc218 \uc788\ub294 \uae00\ub85c \ubc14\uafb8\uae30 \uc2a4\uce94 \uc774\ubbf8\uc9c0\uc640 \ud14d\uc2a4\ud2b8\uc758 \ucc28\uc774\uc5d0\uc11c \ucd9c\ubc1c\ud574 OCR\uc758 \uc4f0\uc784\uacfc \uc624\ub958\u00b7\uac80\ud1a0\uc758 \ud544\uc694\uc131\uc744 \uc774\ud574\ud569\ub2c8\ub2e4. Software \ucef4\ud4e8\ud305 \uc624\ub798\ub41c \uc2e0\ubb38\uc744 \uc2a4\uce94\ud574 \ud654\uba74\uc73c\ub85c \uc5f4\uc5c8\ub2e4. \uae00\uc790\ub294 \ub610\ub837\ud55c\ub370 \ubb38\uc7a5\uc744 \ub04c\uc5b4 \uc120\ud0dd\ud558\ub824 \ud558\uba74 \ud398\uc774\uc9c0 \uc804\uccb4\uac00 \uc6c0\uc9c1\uc778\ub2e4. \uc0ac\ub78c\uc5d0\uac8c\ub294 \ubd84\uba85 \uae00\uc778\ub370 \ucef4\ud4e8\ud130\uc5d0\ub294 \uc65c \ubcf5\uc0ac\ud560 \uc218 \uc788\ub294 \ubb38\uc7a5\uc73c\ub85c \ubcf4\uc774\uc9c0 \uc54a\uc744\uae4c. \ub2f5\uc740 \uac19\uc740 \ubaa8\uc591\uc774 \uc11c\ub85c \ub2e4\ub978 \uc815\ubcf4\uc77c \uc218 \uc788\ub2e4\ub294 \ub370 \uc788\ub2e4. \uc0ac\uc9c4\uc5d0\ub294 \uae00\uc790 \ubaa8\uc591\uc758 \ud53d\uc140\uc774 \uc788\uace0, \ud14d\uc2a4\ud2b8\uc5d0\ub294 \uc5b4\ub5a4 \uae00\uc790\uc778\uc9c0 \uad6c\ubcc4\ud558\ub294 \uc815\ubcf4\uac00 \uc788\ub2e4. OCR, \uc989 \uad11\ud559 \ubb38\uc790 \uc778\uc2dd\uc740 \uc774\ubbf8\uc9c0\uc5d0\uc11c \uae00\uc790\ub97c \ucc3e\uc544 \ucef4\ud4e8\ud130\uac00 \ub2e4\ub8f0 \uc218 \uc788\ub294 \ud14d\uc2a4\ud2b8\ub85c \uc62e\uae30\ub294 \uae30\uc220\uc774\ub2e4. \uc885\uc774 \ubb38\uc11c\uac00 \uac80\uc0c9 \uac00\ub2a5\ud55c \uc790\ub8cc\uac00 \ub418\ub294 \uae38\ubaa9\uc5d0 \uc788\ub2e4. \uc885\uc774\uc5d0 \uc778\uc1c4\ub41c \uc774\ub984\uc744 \ucd2c\uc601\ud558\uba74 \uc0ac\uc9c4 \ud30c\uc77c\uc5d0\ub294 \ubc1d\uae30\uc640 \uc0c9\uc758 \ubc30\uc5f4\uc774 \ub4e4\uc5b4\uac04\ub2e4. \uc0ac\ub78c\uc740 \uc775\uc219\ud55c \ubaa8\uc591\uc5d0\uc11c \uae00\uc790\ub97c \uc77d\uc9c0\ub9cc, \ud30c\uc77c \uc790\uccb4\uac00 \uc774\ub984\uc758 \ucca0\uc790\ub97c \ubb38\uc790 \ub370\uc774\ud130\ub85c \uac16\uace0 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc778\uc1c4\ubb3c\uc744 \uc2a4\uce94\ud588\ub2e4\uace0 \uc790\ub3d9\uc73c\ub85c \uc6cc\ub4dc\ud504\ub85c\uc138\uc11c \ubb38\uc11c\uac00 \ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \ubc18\ub300\ub85c \ucc98\uc74c\ubd80\ud130 \ucef4\ud4e8\ud130\uc5d0\uc11c \uc791\uc131\ud55c PDF\uc5d0\ub294 \ud14d\uc2a4\ud2b8\uc640 \uae00\uaf34 \uc815\ubcf4\uac00 \ub4e4\uc5b4 \uc788\uc744 \uc218 \uc788\ub2e4. \uac19\uc740 PDF \ud655\uc7a5\uc790\ub77c\ub3c4 \ud55c\ucabd\uc740 \ud398\uc774\uc9c0 \uc774\ubbf8\uc9c0\uac00 \uc911\uc2ec\uc774\uace0 \ub2e4\ub978 \ucabd\uc740 \uc2e4\uc81c \ud14d\uc2a4\ud2b8\ub97c \ud3ec\ud568\ud55c\ub2e4. \uac89\ubaa8\uc2b5\ub9cc \ube44\uc2b7\ud558\ub2e4\uace0 \ub0b4\ubd80\uc5d0\uc11c \ud560 \uc218 \uc788\ub294 \uc791\uc5c5\uae4c\uc9c0 \uac19\uc9c0\ub294 \uc54a\ub2e4. OCR\uc740 \uc6d0\ub798 \uae00\uc744 \ub2e4\ub978 \uc5b8\uc5b4\ub85c \ubc14\uafb8\ub294 \uc791\uc5c5\uc774 \uc544\ub2c8\ub2e4. \uc774\ubbf8\uc9c0 \uc18d \ubaa8\uc591\uc744 \uc5b4\ub5a4 \ubb38\uc790\ub85c \uc77d\uc744\uc9c0 \uc54c\uc544\ub0b4\ub824\ub294 \uc791\uc5c5\uc774\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \uc885\uc774\uc5d0 \uc4f0\uc778 \uc11c\uc6b8\uc774\ub77c\ub294 \ub450 \uae00\uc790\ub97c \uc11c\uc6b8\uc774\ub77c\ub294 \ud14d\uc2a4\ud2b8\ub85c \uc62e\uae30\ub294 \uac83\uc774 \uba3c\uc800\ub2e4. \uadf8 \ub73b\uc744 \uc601\uc5b4\ub85c \uc804\ub2ec\ud558\ub294 \ubc88\uc5ed\uc740 \ub2e4\ub978 \ub2e8\uacc4\ub2e4. \ubb3c\ub860 \uc778\uc2dd\uc5d0\ub294 \uc5b8\uc5b4\uc640 \ubb38\ub9e5\uc5d0 \uad00\ud55c \uc815\ubcf4\uac00 \ub3c4\uc6c0\uc774 \ub420 \uc218 \uc788\ub2e4. Tesseract\uc758 \ubb38\uc11c\ub294 \uc0ac\uc804\uacfc \ub2e8\uc5b4 \ubaa9\ub85d, \uc5b8\uc5b4 \uc124\uc815\uc774 \uacb0\uacfc\uc5d0 \uc601\ud5a5\uc744 \uc900\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud615\ud0dc\ub9cc \ud558\ub098\uc529 \uc644\ubcbd\ud558\uac8c \ud310\ub3c5\ud558\uba74 \ub05d\ub098\ub294 \ubb38\uc81c\ub77c\uae30\ubcf4\ub2e4, \uc774\ubbf8\uc9c0\uc640 \ubb38\uc790 \uccb4\uacc4\uc758 \uc870\uac74\uc774 \ud568\uaed8 \uad00\uc5ec\ud55c\ub2e4. \ud750\ub9bf\ud55c \ucd08\uc810\uacfc \uc5bc\ub8e9, \ubc30\uacbd\uc758 \uadf8\ub9bc\uc790\ub294 \uc778\uc2dd\uc744 \uc5b4\ub835\uac8c \ud560 \uc218 \uc788\ub2e4. \uae30\uc6b8\uc5b4\uc9c4 \uc904\uc774\ub098 \uc9c0\ub098\uce58\uac8c \uc791\uac8c \ucd2c\uc601\ub41c \uae00\uc790\ub3c4 \uc601\ud5a5\uc744 \uc900\ub2e4. \uc0ac\ub78c\uc774\ub77c\uba74 \uc8fc\ubcc0 \ub0b4\uc6a9\uc744 \ubcf4\uace0 \ucd94\uce21\ud574 \ub118\uc5b4\uac08 \ubd80\ubd84\uc5d0\uc11c \ud504\ub85c\uadf8\ub7a8\uc740 \ub2e4\ub978 \uae00\uc790\ub97c \ub0b4\ub193\uc744 \uc218 \uc788\ub2e4. Tesseract\uc758 \uacf5\uc2dd \uc548\ub0b4\ub294 \ud574\uc0c1\ub3c4\uc640 \uae30\uc6b8\uae30 \ubcf4\uc815, \ubd88\uade0\uc77c\ud55c \ubc30\uacbd\uacfc \uc7a1\uc74c \ub4f1\uc744 \ub2e4\ub8ec\ub2e4. \ub2e4\ub9cc \uc0ac\uc9c4\uc744 \ud06c\uac8c \ub298\ub9ac\uae30\ub9cc \ud558\uba74 \ubaa8\ub4e0 \uc815\ubcf4\uac00 \ub418\uc0b4\uc544\ub098\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ucc98\uc74c\ubd80\ud130 \uae00\uc790\uc758 \uc138\ubd80\uac00 \ucda9\ubd84\ud788 \ub0a8\ub3c4\ub85d \uc900\ube44\ud558\ub294 \uac83\uacfc \ub098\uc911\uc5d0 \ud654\uba74\uc744 \ud655\ub300\ud558\ub294 \uac83\uc740 \ub2e4\ub978 \ubb38\uc81c\ub2e4. \uc61b \uc2e0\ubb38\ucc98\ub7fc \ud55c \ud398\uc774\uc9c0\uc5d0 \uc5ec\ub7ec \ub2e8\uc774 \uc788\ub294 \uc790\ub8cc\ub294 \uae00\uc790\ub9cc \uc54c\uc544\ubcf4\uc544\uc11c\ub294 \ucda9\ubd84\ud558\uc9c0 \uc54a\ub2e4. \uc5b4\ub290 \uc904 \ub2e4\uc74c\uc5d0 \uc5b4\ub290 \uc904\uc744 \uc77d\uc5b4\uc57c \ud558\ub294\uc9c0\ub3c4 \ud30c\uc545\ud574\uc57c \ud55c\ub2e4. \uc67c\ucabd \ub2e8\uc758 \uc911\uac04\uacfc \uc624\ub978\ucabd \ub2e8\uc758 \uc911\uac04\uc744 \uc774\uc5b4 \ubd99\uc774\uba74 \uae00\uc790\ub294 \ub9de\uc544\ub3c4 \ubb38\uc7a5\uc740 \uc774\uc0c1\ud574\uc9c4\ub2e4. \ud45c\uc5d0\uc11c\ub3c4 \uc22b\uc790\uc640 \uc81c\ubaa9\uc758 \uad00\uacc4\uac00 \uc911\uc694\ud558\ub2e4. \uac12 \uc790\uccb4\ub97c \uc81c\ub300\ub85c \uc77d\uc5b4\ub3c4 \ub2e4\ub978 \ud589\uc5d0 \ubd99\uc774\uba74 \ub73b\uc774 \ub2ec\ub77c\uc9c4\ub2e4. OCRmyPDF\ub294 \ubb38\uc11c\uc758 \uc790\uc5f0\uc2a4\ub7ec\uc6b4 \uc77d\uae30 \uc21c\uc11c\uc5d0 \ud55c\uacc4\uac00 \uc788\uc744 \uc218 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc798 \uc77d\ud788\ub294 \uae00\uc790\uc640 \uc81c\ub300\ub85c \uc774\ud574\ud560 \uc218 \uc788\ub294 \ubb38\uc11c \uad6c\uc870\ub294 \ubcc4\ub3c4\uc758 \uc5b4\ub824\uc6c0\uc744 \uac16\ub294\ub2e4. OCRmyPDF \uac19\uc740 \ub3c4\uad6c\ub294 \uc2a4\uce94\ud55c PDF\uc5d0 \uc778\uc2dd\ud55c \ud14d\uc2a4\ud2b8 \uce35\uc744 \ub354\ud55c\ub2e4. \ud654\uba74\uc5d0\ub294 \uae30\uc874\uc758 \ud398\uc774\uc9c0 \ubaa8\uc2b5\uc774 \ubcf4\uc774\uba74\uc11c \uac80\uc0c9\uacfc \uc120\ud0dd\uc5d0 \uc0ac\uc6a9\ud560 \uae00\uc790 \uc815\ubcf4\uac00 \ud568\uaed8 \ub4e4\uc5b4\uac08 \uc218 \uc788\ub2e4. \uc774\ubbf8\uc9c0\ub97c \uc804\ubd80 \uc0c8 \ud65c\uc790\ub85c \ub2e4\uc2dc \uc870\ud310\ud558\uc9c0 \uc54a\uc544\ub3c4 \ucc3e\uc744 \uc218 \uc788\uac8c \ub9cc\ub4dc\ub294 \ubc29\uc2dd\uc774\ub2e4. \uadf8\ub798\uc11c \uac80\uc0c9\uc774 \ub41c\ub2e4\uace0 \ubb38\uc11c \uc804\uccb4\uac00 \uc790\uc720\ub86d\uac8c \ud3b8\uc9d1\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uac80\uc0c9\uc744 \uc704\ud55c \uae00\uc790 \uc815\ubcf4\uac00 \uc0dd\uacbc\ub2e4\ub294 \uac83\uacfc \uc6d0\ub798\uc758 \ud45c\u00b7\ubb38\ub2e8\u00b7\uc11c\uccb4\ub97c \uc644\ubcbd\ud558\uac8c \ubcf5\uc6d0\ud588\ub2e4\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \uc5b4\ub5a4 \uae30\ub2a5\uc774 \ucd94\uac00\ub418\uc5c8\ub294\uc9c0 \uad6c\ubcc4\ud558\uba74 \uacb0\uacfc\ub97c \ub354 \uc54c\ub9de\uac8c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4. \uc778\uc2dd\uc774 \ud2c0\ub9ac\uba74 \ud398\uc774\uc9c0\uc5d0 \uc2e4\uc81c\ub85c \uc788\ub294 \ub2e8\uc5b4\ub97c \uac80\uc0c9\uc73c\ub85c \ucc3e\uc9c0 \ubabb\ud560 \uc218 \uc788\ub2e4. \uc624\ub798\ub41c \uc2e0\ubb38\uc5d0\uc11c \ud2b9\uc815 \uc774\ub984\uc774 \uc548 \ub098\uc628\ub2e4\uace0 \uace7\ubc14\ub85c \uae30\ub85d\uc774 \uc5c6\uc5c8\ub2e4\uace0 \ub2e8\uc815\ud560 \uc218 \uc5c6\ub294 \uc774\uc720\ub2e4. \uac80\uc0c9\uc740 \ub9ce\uc740 \uc790\ub8cc\ub97c \ube68\ub9ac \uc0b4\ud53c\uac8c \ud558\uc9c0\ub9cc \uadf8 \uae30\ubc18\uc774 \ub418\ub294 \ud14d\uc2a4\ud2b8\uc5d0 \uc624\ub958\uac00 \uc788\uc744 \uc218 \uc788\ub2e4. \ubc18\ub300\ub85c \ube44\uc2b7\ud55c \ubaa8\uc591\uc744 \uc798\ubabb \uc77d\uc5b4\uc11c \uc5c6\ub358 \ub2e8\uc5b4\uac00 \uc0dd\uae38 \uc218\ub3c4 \uc788\ub2e4. \uc778\uc6a9\ud558\uac70\ub098 \uc0ac\uc2e4\uc744 \ud655\uc778\ud560 \ub54c\ub294 \ud574\ub2f9 \ud398\uc774\uc9c0\uc758 \uc6d0\ub798 \ubaa8\uc2b5\uc744 \ud568\uaed8 \ub300\uc870\ud558\ub294 \ud3b8\uc774 \uc88b\ub2e4. \ud3b8\ub9ac\ud574\uc9c4 \ucc3e\uae30 \uae30\ub2a5\uc774 \uadfc\uac70 \ud655\uc778\uc744 \ub300\uc2e0\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \ud655\uc778\ud560 \uc790\ub9ac\ub97c \ub354 \ube68\ub9ac \ucc3e\uc544 \uc8fc\ub294 \uc5ed\ud560\uc744 \ud55c\ub2e4. \uc790\ub8cc\ub97c \ub514\uc9c0\ud138\ud654\ud560 \ub54c\ub294 \uc2a4\uce94\ud55c \uc774\ubbf8\uc9c0\uc640 \uc778\uc2dd \uacb0\uacfc\ub97c \uad6c\ubd84\ud574 \ubcf4\uad00\ud558\uace0 \ud2c0\ub9b0 \uae00\uc790\ub97c \uac80\ud1a0\ud558\ub294 \uacfc\uc815\uc774 \ud544\uc694\ud560 \uc218 \uc788\ub2e4. \uae30\uc220\uc774 \ubb38\uc790\ub97c \uc790\ub3d9\uc73c\ub85c \ub0b4\ub193\ub294 \uc77c\uacfc \ubbff\uace0 \uc778\uc6a9\ud560 \uc218 \uc788\ub294 \uc790\ub8cc\ub97c \ub9cc\ub4dc\ub294 \uc77c \uc0ac\uc774\uc5d0\ub294 \ud3b8\uc9d1\uc774 \ub0a8\ub294\ub2e4. \uc774 \uae00\uc5d0\uc11c \ucc38\uace0\ud55c Tesseract\uc640 OCRmyPDF\ub294 \uc778\uc1c4 \ubb38\uc790\ub97c \uc911\uc2ec\uc73c\ub85c \uc124\uba85\ud55c \uacf5\uac1c \ub3c4\uad6c\ub4e4\uc774\ub2e4. OCR\uc774\ub77c\ub294 \ub113\uc740 \ubd84\uc57c \uc804\uccb4\uc758 \uc131\ub2a5\uc744 \ud55c \ud504\ub85c\uadf8\ub7a8\uc758 \uacb0\uacfc\ub85c \ud310\ub2e8\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ud2b9\ud788 \uc190\uae00\uc528\ub098 \ubcf5\uc7a1\ud55c \ubb38\uc11c\uac00 \uac19\uc740 \uc218\uc900\uc73c\ub85c \uc77d\ud78c\ub2e4\uace0 \uae30\ub300\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \ub300\uc0c1\uacfc \ub3c4\uad6c\uc5d0 \ub530\ub77c \uac00\ub2a5\ud55c \ubc94\uc704\uac00 \ub2e4\ub974\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uc2a4\uce90\ub108\uc640 \uc624\ub798\ub41c \ucc45\uc744 \uc0b4\ud53c\ub294 \uc7a5\uba74\uc774\ub2e4. \uc2e4\uc81c \uc7a5\ube44 \uc0ac\uc6a9 \uc21c\uc11c\ub97c \uac00\ub974\uce58\uac70\ub098 \uc778\uc2dd \uc804\ud6c4\uc758 \uc815\ud655\ub3c4\ub97c \ube44\uad50\ud55c \uc0ac\uc9c4\uc740 \uc544\ub2c8\ub2e4. \uc885\uc774\uc758 \ubaa8\uc2b5\uacfc \uac80\uc0c9 \uac00\ub2a5\ud55c \uae00\uc744 \ud568\uaed8 \ubcf4\uc874\ud558\ub824\ub294 \uc791\uc5c5\uc758 \ubd84\uc704\uae30\ub97c \ub2f4\uc558\ub2e4. \ubb38\uc790\uc778\uc2dd\uc758 \ub9e4\ub825\uc740 \uc0ac\ub78c \ub300\uc2e0 \ucc45\uc744 \uc644\ubcbd\ud558\uac8c \uc774\ud574\ud55c\ub2e4\ub294 \ub370 \uc788\uc9c0 \uc54a\ub2e4. \ub208\uc73c\ub85c\ub9cc \ub118\uae30\ub358 \ub9ce\uc740 \ud398\uc774\uc9c0\uc5d0\uc11c \ud544\uc694\ud55c \ub9d0\uc758 \uc704\uce58\ub97c \ucc3e\ub3c4\ub85d \ub3d5\ub294 \ub370 \uc788\ub2e4. \uadf8\ub9ac\uace0 \uadf8 \uc790\ub9ac\ub97c \ucc3e\uc740 \ub4a4 \ub2e4\uc2dc \uc6d0\ubcf8\uc744 \uc77d\ub294 \uc21c\uac04, \uae30\uacc4\uc758 \ud3b8\ub9ac\ud568\uacfc \uc0ac\ub78c\uc758 \uac80\ud1a0\uac00 \uac19\uc740 \uc791\uc5c5 \uc548\uc5d0\uc11c \ub9cc\ub09c\ub2e4."}, {"id": "png-transparent-background", "title": "PNG \u2014 \ubc30\uacbd\uc774 \uc5c6\ub294 \uadf8\ub9bc\uc740 \uc5b4\ub5bb\uac8c \uac00\ub2a5\ud55c\uac00", "summary": "\ub514\uc9c0\ud138 \uc774\ubbf8\uc9c0\uc758 \ud22c\uba85\ub3c4\uc640 \ubb34\uc190\uc2e4 \uc555\ucd95\uc744 \ud1b5\ud574 \ud30c\uc77c \ud615\uc2dd\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c0\ub294 \uadf8\ub9bc\uc758 \uc131\uc9c8\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "computing", "category_title": "Computing", "subcategory": "Software", "url": "stories/png-transparent-background/index.html", "image": "media/png-transparent-background.png", "alt": "\uc78e \ubaa8\uc591\uc774 \ubd99\uc740 \ud22c\uba85\ud55c \ud310 \ub4a4\ub85c \ud30c\ub780 \uc0c9\uc9c0\uac00 \ubcf4\uc774\ub294 \uc791\uc5c5\uc2e4\uc758 AI \ube44\uc720 \uc7a5\uba74.", "text": "PNG \u2014 \ubc30\uacbd\uc774 \uc5c6\ub294 \uadf8\ub9bc\uc740 \uc5b4\ub5bb\uac8c \uac00\ub2a5\ud55c\uac00 \ud770\uc0c9\uc744 \uc9c0\uc6b4 \uac83\uacfc \ud22c\uba85\ud55c \uac83\uc740 \ub2e4\ub974\ub2e4 \ub514\uc9c0\ud138 \uc774\ubbf8\uc9c0\uc758 \ud22c\uba85\ub3c4\uc640 \ubb34\uc190\uc2e4 \uc555\ucd95\uc744 \ud1b5\ud574 \ud30c\uc77c \ud615\uc2dd\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c0\ub294 \uadf8\ub9bc\uc758 \uc131\uc9c8\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Software \ucef4\ud4e8\ud305 \uc791\uc740 \uadf8\ub9bc\uc744 \ubb38\uc11c\uc5d0 \ub123\uc5c8\ub294\ub370 \ud770 \ub124\ubaa8\uac00 \ub530\ub77c\uc628\ub2e4. \ubd84\uba85 \ud770 \uc885\uc774 \uc704\uc5d0\uc11c\ub294 \ubc30\uacbd\uc774 \uc5c6\ub294 \uac83\ucc98\ub7fc \ubcf4\uc600\ub294\ub370, \ud30c\ub780 \ubc14\ud0d5 \uc704\uc5d0 \uc62c\ub9ac\uc790 \ub124\ubaa8\uc758 \uc724\uacfd\uc774 \uc120\uba85\ud558\ub2e4. \uadf8\ub9bc\uc758 \uc0c9\uc740 \ub9de\ub294\ub370 \uc5b4\uca50\uc9c0 \uc624\ub824 \ubd99\uc778 \uc790\uad6d\uc774 \ub0a8\ub294 \uac83\uc774\ub2e4. \ubc18\uba74 \uc5b4\ub5a4 \ud30c\uc77c\uc740 \ub098\ubb47\uc78e\uc774\ub098 \ub85c\uace0\uc758 \ubaa8\uc591\ub9cc \uae54\ub054\ud558\uac8c \ub193\uc778\ub2e4. \uc8fc\ubcc0\uc758 \ubc14\ud0d5\uc0c9\uc774 \uadf8\ub300\ub85c \ub4dc\ub7ec\ub09c\ub2e4. \uc774 \ucc28\uc774\ub97c \uc774\ud574\ud560 \ub54c \uc790\uc8fc \ub9cc\ub098\ub294 \uc774\ub984\uc774 PNG\ub2e4. \uadf8\ub9bc\uc744 \uc608\uc058\uac8c \ub9cc\ub4dc\ub294 \ub9c8\ubc95\uc774\ub77c\uae30\ubcf4\ub2e4, \uc0c9\uacfc \ud568\uaed8 \ubb34\uc5c7\uc744 \uc5bc\ub9c8\ub098 \ub4dc\ub7ec\ub0bc\uc9c0\ub3c4 \uc800\uc7a5\ud560 \uc218 \uc788\ub294 \ud30c\uc77c \ud615\uc2dd\uc774\ub2e4. \ub514\uc9c0\ud138 \uadf8\ub9bc\uc740 \uc791\uc740 \uc810, \uc989 \ud53d\uc140\ub4e4\uc758 \uac12\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c4\ub2e4. \ubc30\uacbd\uc774 \ud770\uc0c9\uc774\ub77c\ub294 \uac83\uc740 \uadf8 \uc790\ub9ac\uc5d0 \uc544\ubb34 \uc815\ubcf4\ub3c4 \uc5c6\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \ud770\uc0c9\uc73c\ub85c \ud45c\uc2dc\ud558\ub77c\ub294 \uc0c9 \uc815\ubcf4\uac00 \ub4e4\uc5b4 \uc788\ub294 \uac83\uc774\ub2e4. \uadf8\ub798\uc11c \ub2e4\ub978 \uc0c9 \ubc14\ud0d5 \uc704\uc5d0 \ub193\uc544\ub3c4 \uadf8 \ubd80\ubd84\uc740 \uacc4\uc18d \ud558\uc597\uac8c \ub0a8\ub294\ub2e4. \ud22c\uba85\uc740 \ub2e4\ub978 \uc870\uac74\uc774\ub2e4. \uadf8 \uc704\uce58\uc5d0\uc11c \uc544\ub798\ucabd\uc5d0 \ub193\uc778 \ub0b4\uc6a9\uc744 \uc5bc\ub9c8\ub098 \ubcf4\uc5ec \uc904\uc9c0\uc640 \uad00\uacc4\uac00 \uc788\ub2e4. \ud770\uc0c9 \ubb3c\uac10\uc744 \uce60\ud55c \uc720\ub9ac\uc640 \uc544\ubb34\uac83\ub3c4 \uce60\ud558\uc9c0 \uc54a\uc740 \uc720\ub9ac\ub97c \ube44\uad50\ud574 \ubcf4\uba74 \uc27d\ub2e4. \ub458 \ub2e4 \ubc1d\uac8c \ubcf4\uc77c \uc218 \uc788\uc9c0\ub9cc \ub4a4\uc5d0 \uc0c9\uc9c0\ub97c \ub300\ub294 \uc21c\uac04 \uc11c\ub85c \ub2e4\ub974\uac8c \ubcf4\uc778\ub2e4. \uc774\ubbf8\uc9c0\uc758 \ud53d\uc140\uc5d0\ub294 \ube68\uac15\u00b7\ucd08\ub85d\u00b7\ud30c\ub791\uc758 \uc815\ub3c4\ub97c \ub098\ud0c0\ub0b4\ub294 \uc815\ubcf4\uac00 \ub4e4\uc5b4\uac08 \uc218 \uc788\ub2e4. \uc5ec\uae30\uc5d0 \ubd88\ud22c\uba85\ub3c4\ub97c \ub098\ud0c0\ub0b4\ub294 \uc54c\ud30c \uac12\uc774 \ub354\ud574\uc9c0\uba74, \uadf8 \ud53d\uc140\uc774 \uc5bc\ub9c8\ub098 \uac00\ub824 \ubcf4\uc77c\uc9c0 \ud45c\ud604\ud560 \uc218 \uc788\ub2e4. PNG\ub294 \uc774\ub7f0 \ud22c\uba85\ub3c4 \ud45c\ud604\uc744 \uc9c0\uc6d0\ud55c\ub2e4. \uc54c\ud30c\uac00 \uc644\uc804\ud788 \ud22c\uba85\ud55c \uac12\uc774\ub77c\uba74 \ubc14\ud0d5\uc774 \ub4dc\ub7ec\ub098\uace0, \uc644\uc804\ud788 \ubd88\ud22c\uba85\ud55c \uac12\uc774\ub77c\uba74 \uc774\ubbf8\uc9c0\uc758 \uc0c9\uc774 \ubcf4\uc778\ub2e4. \uadf8 \uc0ac\uc774\uc758 \uac12\uc740 \ub450 \ubaa8\uc2b5\uc774 \uc11e\uc774\ub3c4\ub85d \ud55c\ub2e4. \ubcf5\uc7a1\ud55c \uacc4\uc0b0\uc2dd\ubcf4\ub2e4 \uc587\uc740 \uc0c9\uc885\uc774\uc640 \uc9d9\uac8c \uce60\ud55c \uc885\uc774\ub97c \ub5a0\uc62c\ub9ac\uba74, \ub2e8\uc21c\ud788 \ubcf4\uc774\uac70\ub098 \uc548 \ubcf4\uc774\ub294 \ub450 \uc0c1\ud0dc\ub9cc \ud544\uc694\ud55c \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\uc744 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uace1\uc120\uc73c\ub85c \ub41c \ub098\ubb47\uc78e\uc744 \ud654\uba74\uc5d0 \ub193\ub294\ub2e4\uace0 \uc0dd\uac01\ud574 \ubcf4\uc790. \ud53d\uc140\uc740 \ub124\ubaa8\uc778\ub370 \uc724\uacfd\uc740 \ube44\uc2a4\ub4ec\ud558\uace0 \ub465\uae00\ub2e4. \uacbd\uacc4\uc758 \uc810\ub4e4\uc744 \ubaa8\ub450 \uc644\uc804\ud788 \ubcf4\uc774\uac70\ub098 \uc548 \ubcf4\uc774\uac8c\ub9cc \uc815\ud558\uba74 \uacc4\ub2e8\ucc98\ub7fc \ubcf4\uc77c \uc218 \uc788\ub2e4. \uc911\uac04 \ud22c\uba85\ub3c4\ub294 \uc774\ub7f0 \uacbd\uacc4\uac00 \ubc30\uacbd\uacfc \ubd80\ub4dc\ub7fd\uac8c \uc774\uc5b4\uc9c0\ub3c4\ub85d \ud45c\ud604\ud558\ub294 \ub370 \uc4f0\uc77c \uc218 \uc788\ub2e4. \uadf8\ub9bc \uc8fc\uc704\uc758 \uadf8\ub9bc\uc790\ub3c4 \ube44\uc2b7\ud558\ub2e4. \ud55c \ub369\uc5b4\ub9ac\uc758 \ud68c\uc0c9 \uba74\ubcf4\ub2e4 \uc810\ucc28 \uc605\uc5b4\uc9c0\ub294 \ubd80\ubd84\uc774 \uc788\uc73c\uba74 \uc790\uc5f0\uc2a4\ub7fd\ub2e4. \uc774\ub54c \ud544\uc694\ud55c \uac83\uc740 \ud770\uc0c9\uc744 \uc798 \uce60\ud558\ub294 \uae30\uc220\ub9cc\uc774 \uc544\ub2c8\ub2e4. \ubc14\ud0d5\uc774 \uc5b4\ub5a4 \uc0c9\uc774\ub4e0 \ud568\uaed8 \uc5b4\uc6b8\ub9ac\ub3c4\ub85d, \uadf8\ub9bc\uc774 \uadf8 \uc790\ub9ac\ub97c \uc5bc\ub9c8\ub098 \uac00\ub9b4\uc9c0 \ud45c\ud604\ud558\ub294 \uc815\ubcf4\ub2e4. PNG\ub294 \ud22c\uba85\ub3c4\ub97c \uc9c0\uc6d0\ud558\uc9c0\ub9cc \ubaa8\ub4e0 PNG \ud30c\uc77c\uc5d0 \ud22c\uba85\ud55c \ubd80\ubd84\uc774 \ub4e4\uc5b4 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ucc98\uc74c\ubd80\ud130 \ud770 \ubc30\uacbd\uc744 \ud3ec\ud568\ud574 \uc800\uc7a5\ud588\ub2e4\uba74 \uadf8\ub300\ub85c \ud770\uc0c9\uc774 \ubcf4\uc778\ub2e4. \ud30c\uc77c \ud615\uc2dd\uc774 \uc5b4\ub5a4 \uae30\ub2a5\uc744 \uc81c\uacf5\ud558\ub294\uc9c0\uc640 \uc2e4\uc81c \ud30c\uc77c\uc5d0 \uadf8 \uae30\ub2a5\uc774 \uc0ac\uc6a9\ub418\uc5c8\ub294\uc9c0\ub294 \ub2e4\ub974\ub2e4. \ub610 \ud770 \ubc30\uacbd\uc774 \uc788\ub294 \uc0ac\uc9c4\uc758 \ud655\uc7a5\uc790\ub9cc PNG\ub85c \ubc14\uafbc\ub2e4\uace0 \uc778\ubb3c \uc8fc\ubcc0\uc774 \uc790\ub3d9\uc73c\ub85c \uc624\ub824\uc9c0\uc9c0\ub3c4 \uc54a\ub294\ub2e4. \ubc30\uacbd\uc744 \uad6c\ubd84\ud558\uace0 \ud22c\uba85\ud55c \uc601\uc5ed\uc73c\ub85c \ub9cc\ub4dc\ub294 \ud3b8\uc9d1\uc774 \ub530\ub85c \ud544\uc694\ud558\ub2e4. \uadf8\ub987\uc774 \ubb34\uc5c7\uc744 \ub2f4\uc744 \uc218 \uc788\ub294\uc9c0\uc640 \uc548\uc5d0 \ubb34\uc5c7\uc774 \ub2f4\uacbc\ub294\uc9c0\ub97c \ub098\ub204\uba74 \ud754\ud55c \uc624\ud574\uac00 \uc904\uc5b4\ub4e0\ub2e4. PNG\uc758 \uc911\uc694\ud55c \ud2b9\uc9d5\uc740 \ubb34\uc190\uc2e4 \uc555\ucd95\uc774\ub2e4. \uc800\uc7a5\ud560 \uc774\ubbf8\uc9c0 \uc815\ubcf4\ub97c \uc555\ucd95\ud588\ub2e4\uac00 \ub2e4\uc2dc \ud480 \ub54c \uadf8 \uc815\ubcf4\ub97c \ubcf4\uc874\ud558\ub3c4\ub85d \ud558\ub294 \ubc29\uc2dd\uc774\ub2e4. \uac19\uc740 \ub0b4\uc6a9\uc744 \ub354 \ud6a8\uc728\uc801\uc73c\ub85c \uc801\ub294 \uac83\uc5d0 \uac00\uae5d\ub2e4. \uc0ac\uc9c4\uc758 \uc138\ubd80\ub97c \uc77c\ubd80 \ubc84\ub824 \ud06c\uae30\ub97c \uc904\uc774\ub294 \uc77c\ubc18\uc801\uc778 \uc190\uc2e4 \uc555\ucd95\uacfc\ub294 \uc6d0\ub9ac\uac00 \ub2e4\ub974\ub2e4. \uadf8\ub807\ub2e4\uace0 PNG\uac00 \uc774\uc804 \ud3b8\uc9d1\uc5d0\uc11c \uc0ac\ub77c\uc9c4 \ub0b4\uc6a9\uc744 \ub418\uc0b4\ub9b0\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc774\ubbf8 \uc791\uac8c \uc904\uc774\uac70\ub098 \uc190\uc2e4 \uc555\ucd95\uc73c\ub85c \ubb49\uac1c\uc9c4 \uc774\ubbf8\uc9c0\ub97c PNG\ub85c \uc800\uc7a5\ud574\ub3c4 \uc5c6\uc5b4\uc9c4 \uc138\ubd80\ub294 \ub3cc\uc544\uc624\uc9c0 \uc54a\ub294\ub2e4. \ubb34\uc5c7\uc744 \ubcf4\uc874\ud558\ub294\uc9c0\uc758 \ucd9c\ubc1c\uc810\uc740 \uc9c0\uae08 \uc800\uc7a5\ud558\ub294 \uc774\ubbf8\uc9c0\uc774\uc9c0, \uc624\ub798\uc804 \ucd2c\uc601\ud588\ub358 \uc6d0\ub798 \uc7a5\uba74 \uc804\uccb4\uac00 \uc544\ub2c8\ub2e4. PNG\uac00 \ubaa8\ub4e0 \uc6a9\ub3c4\uc5d0\uc11c \uac00\uc7a5 \uc791\uc740 \ud30c\uc77c\uc744 \ub9cc\ub4dc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc0ac\uc9c4\ucc98\ub7fc \ubcf5\uc7a1\ud55c \uc0c9 \ubcc0\ud654\uac00 \ub9ce\uc740 \uc790\ub8cc\uc5d0\uc11c\ub294 \ub2e4\ub978 \ud615\uc2dd\uc774 \ub354 \uc801\uc740 \uc6a9\ub7c9\uc73c\ub85c \uc6d0\ud558\ub294 \ud488\uc9c8\uc744 \uc81c\uacf5\ud560 \uc218 \uc788\ub2e4. \uc6f9\uc5d0\uc11c\ub294 \uc804\uc1a1 \ud06c\uae30\uc640 \uc9c0\uc6d0 \ud658\uacbd, \uc774\ubbf8\uc9c0\uc758 \uc131\uaca9\uc744 \ud568\uaed8 \uace0\ub824\ud55c\ub2e4. \ubc18\uba74 \uae00\uc790\uc640 \uc120\uc774 \ub610\ub837\ud55c \ud654\uba74 \uc790\ub8cc\ub098 \ud22c\uba85\ud55c \uac00\uc7a5\uc790\ub9ac\uac00 \ud544\uc694\ud55c \uadf8\ub9bc\uc740 \uc190\uc2e4\uacfc \ud22c\uba85\ub3c4\uc5d0 \ub300\ud55c \uc694\uad6c\uac00 \ub2e4\ub974\ub2e4. \uc5b4\ub5a4 \ud615\uc2dd\uc774 \ucd5c\uace0\uc778\uac00\ubcf4\ub2e4 \uc774 \uadf8\ub9bc\uc744 \uc5b4\ub514\uc5d0 \uc4f0\ub294\uac00\uac00 \uba3c\uc800\ub2e4. PNG\ub97c \uc548\ub2e4\ub294 \uac83\uc740 \ud655\uc7a5\uc790 \ud558\ub098\ub97c \uace0\uc9d1\ud558\ub294 \uc77c\uc774 \uc544\ub2c8\ub77c \ud544\uc694\ud55c \uc131\uc9c8\uc744 \uad6c\ubcc4\ud558\ub294 \uc77c\uc5d0 \uac00\uae5d\ub2e4. \uc774\ubbf8\uc9c0 \ud3b8\uc9d1 \ud504\ub85c\uadf8\ub7a8\uc5d0\uc11c\ub294 \ud22c\uba85\ud55c \ubd80\ubd84\uc744 \ud68c\uc0c9\uacfc \ud770\uc0c9 \uccb4\ud06c\ubb34\ub2ac\ub85c \ubcf4\uc5ec \uc8fc\uae30\ub3c4 \ud55c\ub2e4. \ubc30\uacbd\uc774 \uc5c6\ub294 \uc790\ub9ac\ub97c \ub208\uc73c\ub85c \uad6c\ubd84\ud558\uac8c \ud558\ub294 \uc548\ub0b4\ub2e4. \uc2e4\uc81c\ub85c \uccb4\ud06c\ubb34\ub2ac \uc790\uccb4\ub97c \uadf8\ub824 \uc800\uc7a5\ud55c \uc774\ubbf8\uc9c0\ub77c\uba74 \ub2e4\ub978 \uacf3\uc5d0\uc11c\ub3c4 \ubb34\ub2ac\uac00 \ubcf4\uc774\ubbc0\ub85c, \ud654\uba74\uc5d0\uc11c \ubcf4\uc774\ub294 \ubaa8\uc591\ub9cc\uc73c\ub85c\ub294 \uad6c\ubcc4\uc774 \ud544\uc694\ud558\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \ud22c\uba85\ud55c \ud310 \ub4a4\uc5d0 \uc0c9\uc9c0\uac00 \ubcf4\uc774\ub294 \ubb3c\ub9ac\uc801\uc778 \ube44\uc720\ub2e4. \uc774 \uc0bd\ud654 \ud30c\uc77c \uc790\uccb4\uac00 \ud22c\uba85\ud55c PNG\uc758 \uc2e4\ud5d8 \ud45c\ubcf8\uc774\ub77c\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uac1c\ub150\uc744 \ub5a0\uc62c\ub9ac\ub294 \uadf8\ub9bc\uacfc \uc2e4\uc81c \ud30c\uc77c \uc18d \uc54c\ud30c \uac12\uc740 \uad6c\ubcc4\ud574\uc11c \ubcf4\uba74 \ub41c\ub2e4. PNG\uc5d0\ub294 \ud22c\uba85\ub3c4 \ud45c\ud604\uc744 \uc800\uc7a5\ud558\ub294 \ubc29\ubc95\ub3c4 \uc5ec\ub7ec \uac00\uc9c0\uac00 \uc788\uc9c0\ub9cc \uc6d0\ub9ac\ub97c \uc774\ud574\ud558\ub294 \ub370 \ubaa8\ub450 \uc678\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uadf8\ub9bc\uc5d0\uc11c \uc911\uc694\ud55c \uac83\uc740 \ubb34\uc5c7\uc744 \ubcf4\uc5ec \uc8fc\ub294\uac00\ubfd0\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uae30 \uc27d\ub2e4. \uadf8\ub7ec\ub098 \ubc30\uacbd\uc774 \ub4dc\ub7ec\ub098\ub3c4\ub85d \ube44\uc6cc \ub450\ub294 \uc815\ub3c4\ub3c4 \ud30c\uc77c\uc5d0 \ub2f4\uc744 \uc218 \uc788\ub294 \uc815\ubcf4\ub2e4. \ub208\uc5d0 \uc798 \ub744\ub294 \uc0c9 \uc606\uc5d0\uc11c \ubcf4\uc774\uc9c0 \uc54a\uc74c\uc758 \ubc29\uc2dd\uc774 \ud568\uaed8 \uc791\ub3d9\ud558\uace0 \uc788\ub2e4. \ub2e4\uc74c\uc5d0 \uadf8\ub9bc \uc8fc\uc704\uc5d0 \ud770 \ub124\ubaa8\uac00 \ub098\ud0c0\ub098\uba74 \ud30c\uc77c\uc774 \ubb34\uc870\uac74 \uc798\ubabb\ub418\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud558\uae30\ubcf4\ub2e4, \uadf8 \uc790\ub9ac\uac00 \ud770\uc0c9\uc778\uc9c0 \ud22c\uba85\uc778\uc9c0 \uba3c\uc800 \ubb3c\uc5b4\ubcf4\uc790. \uac04\ub2e8\ud55c \uc9c8\ubb38 \ud558\ub098\ub85c \uc774\ubbf8\uc9c0\uc758 \uc131\uaca9\uc774 \ub2ec\ub77c \ubcf4\uc778\ub2e4. PNG\uc758 \uc7ac\ubbf8\ub294 \ud2b9\ubcc4\ud55c \ud6a8\uacfc\ubcf4\ub2e4, \ubcf4\uc774\ub294 \uac83\uacfc \ube44\uc6cc \ub454 \uac83\uc744 \ud568\uaed8 \uae30\ub85d\ud55c\ub2e4\ub294 \ub370 \uc788\ub2e4."}, {"id": "python-comedy-name", "title": "\ud30c\uc774\uc36c\uc774\ub77c\ub294 \uc774\ub984\uc740 \ucf54\ubbf8\ub514\uc5d0\uc11c \uc654\ub2e4", "summary": "\ucef4\ud4e8\ud130 \uc5b8\uc5b4\uc758 \uc774\ub984\uc744 \ub530\ub77c\uac00\ub2e4 \ubcf4\uba74 \uc601\uad6d \ucf54\ubbf8\ub514 \ud504\ub85c\uadf8\ub7a8\uc744 \ub9cc\ub098\uac8c \ub429\ub2c8\ub2e4.", "category": "computing", "category_title": "Computing", "subcategory": "Programming", "url": "stories/python-comedy-name/index.html", "image": "media/python-comedy-name.jpg", "alt": "\ubb34\ub300 \ucee4\ud2bc\uc774 \ubcf4\uc774\ub294 \uc61b \ud154\ub808\ube44\uc804\uacfc \ube48 \ub300\ubcf8\uc758 \uc124\uba85\uc6a9 AI \uc0bd\ud654", "text": "\ud30c\uc774\uc36c\uc774\ub77c\ub294 \uc774\ub984\uc740 \ucf54\ubbf8\ub514\uc5d0\uc11c \uc654\ub2e4 \ud504\ub85c\uadf8\ub798\ubc0d \uc5b8\uc5b4\uc758 \uc774\ub984\uc5d0 \ub0a8\uc740 \uac1c\ubc1c\uc790\uc758 \ucde8\ud5a5 \ucef4\ud4e8\ud130 \uc5b8\uc5b4\uc758 \uc774\ub984\uc744 \ub530\ub77c\uac00\ub2e4 \ubcf4\uba74 \uc601\uad6d \ucf54\ubbf8\ub514 \ud504\ub85c\uadf8\ub7a8\uc744 \ub9cc\ub098\uac8c \ub429\ub2c8\ub2e4. Programming \ucef4\ud4e8\ud305 \ud30c\uc774\uc36c\uc774\ub77c\ub294 \uc774\ub984\uc744 \ucc98\uc74c \ub4e4\uc73c\uba74 \ubc40\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \uc601\uc5b4\ub85c\ub3c4 \ud070 \ubc40\uc744 \uac00\ub9ac\ud0a4\ub294 \ub9d0\uc774\ub2e4. \ucef4\ud4e8\ud130\ub97c \uc798 \ubaa8\ub974\ub294 \uc0ac\ub78c\uc774\ub77c\ub3c4 \uc5b4\ub514\uc120\uac00 \ud55c \ubc88\ucbe4 \ub4e4\uc5b4\ubcf8 \uc774\ub984\uc77c \uc218 \uc788\ub2e4. \uadf8\ub7f0\ub370 \ud504\ub85c\uadf8\ub798\ubc0d \uc5b8\uc5b4 Python\uc758 \uacf5\uc2dd FAQ\ub294 \uc774\ub984\uc758 \ucd9c\ubc1c\uc810\uc744 \uc870\uae08 \ub2e4\ub974\uac8c \uc124\uba85\ud55c\ub2e4. \uac1c\ubc1c\uc790 \uadc0\ub3c4 \ud310 \ub85c\uc12c\uc774 \uc77d\uace0 \uc788\ub358 \uc601\uad6d \ucf54\ubbf8\ub514 \ud504\ub85c\uadf8\ub7a8\uc758 \ub300\ubcf8\uc5d0\uc11c \uac00\uc838\uc654\ub2e4\ub294 \uac83\uc774\ub2e4. \ud504\ub85c\uadf8\ub7a8\uc758 \uc774\ub984\uc740 \u300c\ubaac\ud2f0 \ud30c\uc774\uc120\uc758 \ud50c\ub77c\uc789 \uc11c\ucee4\uc2a4\u300d\uc600\ub2e4. \ucef4\ud4e8\ud130 \uc5b8\uc5b4 \uc774\ub984\uc744 \ub530\ub77c\uc654\ub294\ub370 \uac11\uc790\uae30 \ud154\ub808\ube44\uc804\uc758 \ucf54\ubbf8\ub514 \ubb34\ub300\uac00 \ub098\ud0c0\ub09c\ub2e4. \uacf5\uc2dd \uc124\uba85\uc5d0 \ub530\ub974\uba74 \ud310 \ub85c\uc12c\uc740 \ud30c\uc774\uc36c\uc744 \uad6c\ud604\ud558\ub358 \ubb34\ub835 \uadf8 \ucf54\ubbf8\ub514\uc758 \ucd9c\ud310\ub41c \ub300\ubcf8\uc744 \uc77d\uace0 \uc788\uc5c8\ub2e4. \uc0c8 \uc5b8\uc5b4\uc5d0\ub294 \uc9e7\uace0 \ub3c5\ud2b9\ud558\uba70 \uc870\uae08\uc740 \uc2e0\ube44\ub85c\uc6b4 \ub290\ub08c\uc758 \uc774\ub984\uc774 \ud544\uc694\ud558\ub2e4\uace0 \uc0dd\uac01\ud588\ub2e4. \uadf8\ub798\uc11c Python\uc774\ub77c\ub294 \uc774\ub984\uc744 \uace8\ub790\ub2e4. \ubaa8\ub4e0 \uc774\ub984\uc774 \uae30\ub2a5\uc744 \uc904\uc5ec \ubd99\uc778 \uc57d\uc790\ub098 \uae30\uc220 \uc6a9\uc5b4\uc5d0\uc11c \ub098\uc624\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub9cc\ub4dc\ub294 \uc0ac\ub78c\uc774 \uc990\uae30\ub358 \ubb38\ud654\uac00 \uc774\ub984\uc758 \uc7ac\ub8cc\uac00 \ub418\uae30\ub3c4 \ud55c\ub2e4. \uc5ec\uae30\uc11c \ucf54\ubbf8\ub514\uac00 \ud504\ub85c\uadf8\ub798\ubc0d\uc758 \uc6d0\ub9ac\ub97c \uacb0\uc815\ud588\ub2e4\uace0 \uc124\uba85\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc9c0\uae08 \ud655\uc778\ud560 \uc218 \uc788\ub294 \uac83\uc740 \uc774\ub984\uc744 \uc815\ud55c \uc0ac\uc5f0\uc774\ub2e4. \uc9e7\uc740 \uc774\ub984 \ud558\ub098\uc5d0\ub3c4 \uae30\uc220 \ubc16\uc758 \uacbd\ud5d8\uc774 \ub4e4\uc5b4\uac08 \uc790\ub9ac\uac00 \uc788\uc5c8\ub2e4. \ud765\ubbf8\ub85c\uc6b4 \uac83\uc740 \uc774 \uc0ac\uc5f0\uc774 \ub5a0\ub3c4\ub294 \uc18c\ubb38\uc73c\ub85c\ub9cc \uc804\ud574\uc9c0\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uacf5\uc2dd \uc9c8\ubb38\uacfc \ub2f5\ubcc0 \ubaa9\ub85d\uc5d0 \ub4e4\uc5b4 \uc788\ub2e4\ub294 \uc810\uc774\ub2e4. \uc774\ub984\uc758 \uc720\ub798\ub97c \ubb3b\ub294 \uc9c8\ubb38 \ub2e4\uc74c\uc5d0\ub294 \uadf8 \ucf54\ubbf8\ub514\ub97c \uaf2d \uc88b\uc544\ud574\uc57c \ud558\ub294\uc9c0\ub3c4 \ubb3b\ub294\ub2e4. \ub2f5\ubcc0\ub3c4 \uac00\ubccd\ub2e4. \ubc18\ub4dc\uc2dc \uc88b\uc544\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4\ub294 \ucde8\uc9c0\ub85c \uc9e7\uc740 \ub18d\ub2f4\uc744 \ub367\ubd99\uc778\ub2e4. \uae30\uc220\uc744 \uc124\uba85\ud558\ub294 \ubb38\uc11c \uc548\uc5d0\uc11c\ub3c4 \ub9cc\ub4e0 \uc0ac\ub78c\ub4e4\uc758 \ub9d0\ud22c\uc640 \ucde8\ud5a5\uc774 \uc7a0\uae50 \ub4dc\ub7ec\ub098\ub294 \ub300\ubaa9\uc774\ub2e4. \ubb3c\ub860 \ud504\ub85c\uadf8\ub7a8\uc744 \uc4f0\uae30 \uc704\ud574 \ucf54\ubbf8\ub514\ub97c \ubcf4\uc544\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774\ub984\uc758 \ubc30\uacbd\uc744 \ubab0\ub77c\ub3c4 \ub3c4\uad6c\ub294 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ub0af\uc124\uace0 \uc804\ubb38\uc801\uc73c\ub85c \ubcf4\uc774\ub358 \uc774\ub984\uc5d0 \uc0dd\ud65c\uc758 \uc791\uc740 \ub2e8\uc11c\uac00 \uc0dd\uae34\ub2e4. \uc5b4\ub5a4 \ub2e8\uc5b4\uac00 \uc0ac\uc804\uc5d0 \uc5b4\ub5a4 \ub73b\uc73c\ub85c \ub098\uc624\ub294\uc9c0\uc640 \uac1c\ubc1c\uc790\uac00 \uc65c \uadf8 \ub2e8\uc5b4\ub97c \uace8\ub790\ub294\uc9c0\ub294 \ub2e4\ub978 \uc9c8\ubb38\uc774\ub2e4. Python\uc774 \ubc40\uc758 \uc774\ub984\uc774\ub77c\ub294 \uc0ac\uc2e4\uc740 \ub9de\uc9c0\ub9cc, \uacf5\uc2dd \ubb38\uc11c\uac00 \uc124\uba85\ud558\ub294 \uc791\uba85\uc758 \uacc4\uae30\ub294 \ucf54\ubbf8\ub514 \ub300\ubcf8\uc774\ub2e4. \ub450 \uc0ac\uc2e4\uc744 \uacbd\uc7c1\ud558\ub294 \uc815\ub2f5\uc73c\ub85c \ubcfc \ud544\uc694\ub294 \uc5c6\ub2e4. \ub2e8\uc5b4\uac00 \uc6d0\ub798 \uac00\uc9c4 \ub73b\uacfc \uadf8 \uc774\ub984\uc5d0 \ub2f4\uc740 \uac1c\uc778\uc801\uc778 \uacbd\ud5d8\uc774 \ud568\uaed8 \ub0a8\uc544 \uc788\ub294 \uacbd\uc6b0\ub2e4. \uc774 \ucc28\uc774\ub294 \ub2e4\ub978 \uae30\uc220 \uc774\ub984\uc744 \ub9cc\ub0a0 \ub54c\uc5d0\ub3c4 \uc720\uc6a9\ud558\ub2e4. \ub208\uc55e\uc758 \ub85c\uace0\uac00 \uc5b4\ub5a4 \ubaa8\uc591\uc774\ub77c\uace0 \ud574\uc11c \uadf8\uac83\uc774 \ubc18\ub4dc\uc2dc \ucd5c\ucd08 \uc791\uba85\uc758 \uc774\uc720\uc600\ub2e4\uace0 \uac70\uafb8\ub85c \ucd94\ub860\ud560 \uc218\ub294 \uc5c6\ub2e4. \uba3c\uc800 \ub9cc\ub4e4\uc5b4\uc9c4 \uc774\ub984\uc774 \ub098\uc911\uc758 \uc2dc\uac01\uc801 \ud45c\ud604\uacfc \ub9cc\ub098 \ub354 \ub110\ub9ac \uae30\uc5b5\ub418\uae30\ub3c4 \ud55c\ub2e4. \ud30c\uc774\uc36c\uc758 \uacbd\uc6b0\uc5d0\ub294 \uc774\ub984\uc744 \uace0\ub978 \uc0ac\uc815\uc744 \uc124\uba85\ud55c \uacf5\uc2dd \ub2f5\ubcc0\uc744 \ud1b5\ud574 \uc21c\uc11c\ub97c \ud655\uc778\ud560 \uc218 \uc788\ub2e4. \ub9ce\uc740 \uae30\uc220 \uc6a9\uc5b4\ub294 \uae34 \uc804\ubb38 \ud45c\ud604\uc758 \uc55e\uae00\uc790\ub97c \ubaa8\uc544 \ub9cc\ub4e0\ub2e4. \uadf8\ub798\uc11c \ucc98\uc74c \ubcf4\ub294 \uc774\ub984\uc744 \ub9cc\ub098\uba74 \uc5b4\ub5a4 \uae30\ub2a5\uc758 \uc57d\uc790\uc778\uc9c0 \ubb3b\uac8c \ub41c\ub2e4. \ud558\uc9c0\ub9cc \ud30c\uc774\uc36c\uc774\ub77c\ub294 \uc774\ub984\uc740 \uadf8\ub7f0 \ubc29\uc2dd\uc758 \uae30\ub2a5 \uc694\uc57d\uc73c\ub85c \uc124\uba85\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc9e7\uace0 \uad6c\ubcc4\ub418\uba70 \uc778\uc0c1\uc5d0 \ub0a8\ub294 \uc774\ub984\uc744 \ucc3e\ub294 \uacfc\uc815\uc5d0 \ucde8\ud5a5\uc774 \ub4e4\uc5b4\uac04 \uac83\uc774\ub2e4. \uc774 \uc0ac\uc2e4\uc744 \uc548\ub2e4\uace0 \uadf8 \uc5b8\uc5b4\uc758 \ubb38\ubc95\uc774 \ub354 \uc27d\uac70\ub098 \ube60\ub974\ub2e4\ub294 \uacb0\ub860\uc744 \ub0bc \uc218\ub294 \uc5c6\ub2e4. \uc774\ub984\uacfc \uc131\ub2a5\uc758 \uadfc\uac70\ub294 \ub530\ub85c \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \ub2e4\ub9cc \uae30\uc220\uc744 \ub9cc\ub4dc\ub294 \uc0ac\ub78c\uc758 \uc120\ud0dd\uc774 \uc5b8\uc81c\ub098 \uacc4\uc0b0 \ud6a8\uc728\ub9cc\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\uc740 \ubcfc \uc218 \uc788\ub2e4. \ub3c4\uad6c\uc5d0\ub294 \uae30\ub2a5\uc758 \uc124\uacc4\uc640 \uc0ac\ub78c\ub4e4\uc774 \uadf8\uac83\uc744 \ubd80\ub974\uace0 \uae30\uc5b5\ud558\ub294 \ubc29\uc2dd\uc774 \ud568\uaed8 \uc788\ub2e4. \uc9c8\ubb38\uacfc \ub2f5\ubcc0\uc758 \ubaa9\ub85d\uc740 \ucc98\uc74c \uc811\ud55c \uc0ac\ub78c\uc774 \uc790\uc8fc \uad81\uae08\ud574\ud558\ub294 \uac83\uc744 \ubaa8\uc740\ub2e4. \uc0ac\uc6a9\ubc95\uacfc \ubb38\uc81c \ud574\uacb0\ub9cc\uc774 \uc544\ub2c8\ub77c \uc65c \uadf8\ub7f0 \uc774\ub984\uc778\uc9c0 \uac19\uc740 \uc9c8\ubb38\ub3c4 \ud3ec\ud568\ub420 \uc218 \uc788\ub2e4. \ubb38\uc11c\uac00 \uc774\ub984\uc758 \uc720\ub798\uc640 \ucf54\ubbf8\ub514\uc5d0 \uad00\ud55c \uac00\ubcbc\uc6b4 \ub18d\ub2f4\uc744 \ud568\uaed8 \uc2e3\ub294\ub2e4\ub294 \uc810\uc740 \ub3c4\uad6c \uc8fc\ubcc0\uc758 \ubb38\ud654\uac00 \uc804\ub2ec\ub418\ub294 \ubc29\uc2dd\uc73c\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \ubb3c\ub860 \uc791\uc131\uc790\uc758 \ubaa8\ub4e0 \ub18d\ub2f4\uc744 \uc5b8\uc5b4\uc758 \uacf5\uc2dd \ucca0\ud559\uc73c\ub85c \ud06c\uac8c \ud574\uc11d\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ubb38\ubc95 \uaddc\uce59\uc740 \ubb38\ubc95 \uaddc\uce59\ub300\ub85c \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc804\ubb38\uc801\uc778 \uc124\uba85 \uc0ac\uc774\uc5d0\ub3c4 \uc0ac\ub78c\uc758 \ub9d0\ud22c\uac00 \ub0a8\uc544 \uc788\ub2e4\ub294 \uac83\uc744 \ubcf4\ub294 \uac83\uc774\ub2e4. \uae30\uc220 \ubb38\uc11c\uac00 \uac10\uc815 \uc5c6\ub294 \uae30\uacc4\uc758 \ubb38\uc7a5\ub9cc\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c4\ub2e4\ub294 \uc778\uc0c1\ub3c4 \uc870\uae08 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc5b4\ub5a4 \uc0ac\ub78c\uc5d0\uac8c \ud30c\uc774\uc36c\uc740 \uc77c\ud558\ub294 \ub3c4\uad6c\uc774\uace0 \uc5b4\ub5a4 \uc0ac\ub78c\uc5d0\uac8c\ub294 \ucc98\uc74c \ub4e3\ub294 \uc804\ubb38 \uc6a9\uc5b4\ub2e4. \ucf54\ubbf8\ub514\uc758 \ubc30\uacbd\uc744 \uc544\ub294 \uc0ac\ub78c\uc740 \uc774\ub984\uc5d0\uc11c \ub610 \ub2e4\ub978 \uc5f0\uacb0\uc744 \ub290\ub084 \uc218 \uc788\ub2e4. \ud558\ub098\uc758 \uc774\ub984\uc774 \uc11c\ub85c \ub2e4\ub978 \uacbd\ud5d8\uc744 \uac00\uc9c4 \uc0ac\ub78c\ub4e4\uc5d0\uac8c \uac01\uae30 \ub2e4\ub978 \uc785\uad6c\ub97c \ub9cc\ub4dc\ub294 \uc148\uc774\ub2e4. \uacf5\ud1b5\uc758 \uae30\ub2a5\uc744 \uc4f0\uba74\uc11c\ub3c4 \uc8fc\ubcc0 \uc774\uc57c\uae30\ub97c \ub611\uac19\uc774 \uc54c\uc544\uc57c \ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uadf8\ub807\uae30\uc5d0 \uc774 \uae00\uc740 \ub300\ubcf8\uc744 \uc77d\uc5b4\uc57c\ub9cc \uae30\uc220\uc744 \uc774\ud574\ud560 \uc218 \uc788\ub2e4\ub294 \uc0c8\ub85c\uc6b4 \uc219\uc81c\ub97c \uc8fc\ub824\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \ub3c4\uad6c\uc758 \uc791\uc740 \uc720\ub798\ub97c \ud1b5\ud574 \ub9cc\ub4dc\ub294 \uc0ac\ub78c\uacfc \uc4f0\ub294 \uc0ac\ub78c \uc0ac\uc774\uc758 \uac70\ub9ac\ub97c \uc904\uc774\ub294 \uc77d\uae30\ub2e4. \ub0af\uc120 \uae30\uc220\uc744 \ubaa8\ub450 \ubc30\uc6b8 \ud544\uc694 \uc5c6\uc774\ub3c4 \uadf8 \uc774\ub984 \ub4a4\uc5d0 \uc5b4\ub5a4 \uc120\ud0dd\uc774 \uc788\uc5c8\ub294\uc9c0 \uad6c\uacbd\ud560 \uc218 \uc788\ub2e4. \ucf54\ub529 \ubc16\uc5d0\uc11c \ucef4\ud4e8\ud130 \ubb38\ud654\ub97c \ub9cc\ub098\ub294 \ud55c \ubc29\ubc95\uc774\ub2e4. \ud504\ub85c\uadf8\ub798\ubc0d \uc5b8\uc5b4\ub294 \ucef4\ud4e8\ud130\uc5d0\uac8c \ud560 \uc77c\uc744 \ud45c\ud604\ud558\ub294 \ub3c4\uad6c\ub2e4. \ucc98\uc74c \uc811\ud558\uba74 \ubb38\ubc95\uacfc \uae30\ud638\uac00 \uba3c\uc800 \ubcf4\uc5ec \uc5b4\ub835\uac8c \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uadf8 \ub3c4\uad6c\ub97c \ub9cc\ub4e0 \uc0ac\ub78c\ub4e4\ub3c4 \ucc45\uc744 \uc77d\uace0 \ud154\ub808\ube44\uc804\uc744 \ubcf4\uba70 \uc774\ub984\uc744 \uace8\ub790\ub2e4. \uc774\uc57c\uae30\ub97c \uc548\ub2e4\uace0 \uace7\ubc14\ub85c \ucf54\ub4dc\ub97c \uc4f8 \uc218 \uc788\uac8c \ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \uadf8\ub7f4 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \uc774\ubc88\uc5d0\ub294 \uae30\uc220\uc758 \uc0ac\uc6a9\ubc95\ubcf4\ub2e4, \uc775\uc219\ud55c \uc774\ub984 \ud558\ub098\uac00 \ub9cc\ub4e4\uc5b4\uc9c4 \uacfc\uc815\uc744 \uad6c\uacbd\ud558\ub294 \uac83\uc73c\ub85c \ucda9\ubd84\ud558\ub2e4. \ub2e4\uc74c\uc5d0 \ud30c\uc774\uc36c\uc774\ub77c\ub294 \ub9d0\uc744 \ub9cc\ub098\uba74 \ubc40 \uc606\uc5d0 \uc791\uc740 \ucf54\ubbf8\ub514 \ubb34\ub300\ub3c4 \ud568\uaed8 \ub5a0\uc62c\ub824 \ubcf4\uc790. \ucef4\ud4e8\ud130 \uc138\uacc4\uc758 \uc774\ub984\uc5d0\ub3c4 \ub204\uad70\uac00 \uc7ac\ubbf8\uc788\uac8c \uc77d\ub358 \ub300\ubcf8\uc758 \ud754\uc801\uc774 \ub0a8\uc544 \uc788\ub2e4."}, {"id": "qr-code-three-corners", "title": "QR \ucf54\ub4dc \u2014 \uc65c \uc138 \ubaa8\uc11c\ub9ac\uc5d0 \ud070 \ub124\ubaa8\uac00 \uc788\uc744\uae4c", "summary": "QR \ucf54\ub4dc\uc758 \uc704\uce58 \ud45c\uc2dc\uc640 \ub370\uc774\ud130, \uc624\ub958 \uc815\uc815\uc744 \ud1b5\ud574 \uc791\uc740 \ubb34\ub2ac\uac00 \uc77d\ud788\ub294 \uc6d0\ub9ac\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "computing", "category_title": "Computing", "subcategory": "Computers", "url": "stories/qr-code-three-corners/index.html", "image": "media/qr-code-three-corners.png", "alt": "\uce74\ud398\uc5d0\uc11c \uc190\ub2d8\uc774 \ud734\ub300\uc804\ud654\ub97c \ub4e4\uace0 \uce74\ub4dc \ucabd\uc744 \ubc14\ub77c\ubcf4\uba70 \uc74c\ub8cc\ub97c \ubc1b\ub294 AI \uc7a5\uba74.", "text": "QR \ucf54\ub4dc \u2014 \uc65c \uc138 \ubaa8\uc11c\ub9ac\uc5d0 \ud070 \ub124\ubaa8\uac00 \uc788\uc744\uae4c \uc791\uc740 \uac80\uc740 \uce78\ub4e4\uc774 \uce74\uba54\ub77c\uc5d0\uac8c \uae38\uc744 \uc54c\ub824 \uc8fc\ub294 \ubc29\ubc95 QR \ucf54\ub4dc\uc758 \uc704\uce58 \ud45c\uc2dc\uc640 \ub370\uc774\ud130, \uc624\ub958 \uc815\uc815\uc744 \ud1b5\ud574 \uc791\uc740 \ubb34\ub2ac\uac00 \uc77d\ud788\ub294 \uc6d0\ub9ac\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Computers \ucef4\ud4e8\ud305 \uce74\ud398\uc5d0\uc11c \uba54\ub274\ub97c \ubcf4\ub824\uace0 \uc791\uc740 \ubb34\ub2ac\ub97c \ud734\ub300\uc804\ud654\ub85c \ube44\ucd98\ub2e4. \uac80\uc740 \uce78\ub4e4\uc774 \ube7c\uace1\ud55c\ub370 \ud654\uba74\uc740 \uace7 \uc8fc\uc18c\ub97c \uc54c\uc544\ubcf8\ub2e4. \uc0ac\ub78c \ub208\uc5d0\ub294 \ube44\uc2b7\ube44\uc2b7\ud55c \ubb34\ub2ac\uac00 \uae30\uacc4\uc5d0\ub294 \uc77d\uc744 \uc218 \uc788\ub294 \uc815\ubcf4\uc778 \uc148\uc774\ub2e4. QR \ucf54\ub4dc\ub97c \uc790\uc8fc \uc368\ub3c4 \uadf8 \uc548\uc758 \ud070 \ub124\ubaa8\ub4e4\uc740 \uadf8\ub0e5 \uc9c0\ub098\uce58\uae30 \uc27d\ub2e4. \ub2e4\uc74c\uc5d0 \ubcfc \ub54c\ub294 \ubaa8\uc11c\ub9ac \uc138 \uacf3\uc744 \uba3c\uc800 \uc0b4\ud3b4\ubcf4\uc790. \ubcf4\ud1b5\uc758 QR \ucf54\ub4dc\uc5d0\ub294 \uc791\uc740 \uce78\ubcf4\ub2e4 \ud6e8\uc52c \ud070 \ub124\ubaa8 \ubb34\ub2ac\uac00 \uc788\ub2e4. \uc7a5\uc2dd\uc774 \uc544\ub2c8\ub77c \ucf54\ub4dc\ub97c \ucc3e\uace0 \uc77d\ub294 \ub370 \ud544\uc694\ud55c \ud45c\uc9c0\ub2e4. \ubaa8\ub4e0 \uac80\uc740 \uce78\uc774 \uac19\uc740 \uc885\ub958\uc758 \uc815\ubcf4\ub97c \ub2f4\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc0ac\uc2e4\uc774 \uc774 \uc774\uc57c\uae30\uc758 \ucd9c\ubc1c\uc810\uc774\ub2e4. \ud734\ub300\uc804\ud654\ub85c \ube44\ucd98 \uc7a5\uba74\uc5d0\ub294 \ucf54\ub4dc\ub9cc \uc788\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc885\uc774\uc758 \ud14c\ub450\ub9ac\uc640 \uc2dd\ud0c1, \uadf8\ub9bc\uc790\ub3c4 \ud568\uaed8 \ub4e4\uc5b4\uc628\ub2e4. \uae30\uacc4\ub294 \uba3c\uc800 \uc5b4\ub290 \ubd80\ubd84\uc744 \uc77d\uc744 \ub300\uc0c1\uc778\uc9c0 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ud070 \uc704\uce58 \uac80\ucd9c \ubb34\ub2ac\ub294 \uadf8 \uc2dc\uc791\uc744 \ub3d5\ub294\ub2e4. \ud568\uaed8 \uc0b4\ud3b4\ubcf8 \uacf5\uac1c \uad6c\ud604\uc740 \uc77c\ubc18\uc801\uc778 QR \ucf54\ub4dc\uc758 \ub124 \ubaa8\uc11c\ub9ac \uac00\uc6b4\ub370 \uc624\ub978\ucabd \uc544\ub798\ub97c \uc81c\uc678\ud55c \uc138 \uacf3\uc5d0 \uc774 \ubb34\ub2ac\ub97c \uadf8\ub9b0\ub2e4. \uc11c\ub85c \ub5a8\uc5b4\uc838 \uc788\ub294 \ud45c\uc9c0\ub97c \ucc3e\uc73c\uba74 \ucf54\ub4dc\uc758 \uc790\ub9ac\uc640 \ubc29\ud5a5\uc744 \ud30c\uc545\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \uc774 \uae00\uc740 \uc77c\ubc18\uc801\uc778 QR \ucf54\ub4dc\ub97c \ub2e4\ub8e8\uba70, \ubaa8\uc591\uc774 \ub2e4\ub978 \ubaa8\ub4e0 \ubcc0\ud615 \ucf54\ub4dc\uc5d0 \uac19\uc740 \uc124\uba85\uc744 \uc801\uc6a9\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud070 \ub124\ubaa8\ub294 \uac80\uc740\uc0c9\uacfc \ud770\uc0c9\uc774 \uc77c\uc815\ud55c \uad6c\uc870\ub85c \uacb9\uccd0 \uc788\ub2e4. \uc8fc\ubcc0\uc758 \uc791\uc740 \ub370\uc774\ud130 \ubb34\ub2ac\uc640 \uad6c\ubcc4\ub418\ub294 \ubaa8\uc591\uc744 \uac16\ub3c4\ub85d \ub9cc\ub4e0 \uac83\uc774\ub2e4. \uc0ac\ub78c\uc5d0\uac8c \uc81c\ubaa9\uacfc \ubcf8\ubb38\uc744 \ub2e4\ub978 \ud06c\uae30\ub85c \ubcf4\uc5ec \uc8fc\ub294 \uac83\ucc98\ub7fc, \uc77d\uae30 \uc704\ud55c \ud45c\uc9c0\ub97c \ub0b4\uc6a9\uacfc \uad6c\ubd84\ud55c\ub2e4\ub294 \uc810\uc5d0\uc11c \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uadf8 \uc606\uc5d0\ub294 \uce78\uc758 \uac04\uaca9\uc744 \uc77d\ub294 \ub370 \uc4f0\uc774\ub294 \ubc18\ubcf5 \ubb34\ub2ac\ub3c4 \uc788\ub2e4. \ud06c\uae30\uc5d0 \ub530\ub77c \ucd94\uac00\uc801\uc778 \uc815\ub82c \ubb34\ub2ac\ub3c4 \ub4e4\uc5b4\uac04\ub2e4. \uc0ac\uc9c4 \uc18d \uae30\ud638\ub97c \ub2e8\uc21c\ud55c \uac80\uc740\uc0c9 \uadf8\ub9bc\uc73c\ub85c \uc778\uc2dd\ud55c \ub4a4 \ub05d\ub0b4\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \uc5b4\ub290 \uc704\uce58\uc758 \uce78\uc744 \uc5b4\ub5a4 \uc21c\uc11c\ub85c \uc77d\uc744\uc9c0 \ud30c\uc545\ud558\ub294 \uc5ec\ub7ec \uc7a5\uce58\uac00 \uc788\ub294 \uc148\uc774\ub2e4. QR \ucf54\ub4dc\uc758 \uce78 \ud558\ub098\ub97c \ubaa8\ub4c8\uc774\ub77c\uace0 \ubd80\ub978\ub2e4. \uc5ec\ub7ec \uce78\uc5d0 \uac78\uccd0 \ub370\uc774\ud130\ub97c \ubc30\uce58\ud558\uba74 \uae00\uacfc \uc22b\uc790 \ub4f1\uc744 \ub098\ud0c0\ub0bc \uc218 \uc788\ub2e4. \uc0ac\ub78c\uc774 \ud55c \uce78\uc744 \ubcf4\uace0 \uae00\uc790 \ud558\ub098\ub97c \uc77d\ub294 \ubc29\uc2dd\uc740 \uc544\ub2c8\ub2e4. \uc815\ud574\uc9c4 \uaddc\uce59\uc5d0 \ub530\ub77c \ubaa8\uc778 \uac12\ub4e4\uc744 \ud574\uc11d\ud574\uc57c \ud55c\ub2e4. \uc8fc\uc18c\uac00 \ub4e4\uc5b4 \uc788\ub294 \ucf54\ub4dc\ub77c\uba74 \uc77d\uc740 \uacb0\uacfc\ub294 \ubcf4\ud1b5 \uc9e7\uc740 \uc6f9 \uc8fc\uc18c \uac19\uc740 \ubb38\uc790\uc5f4\uc774\ub2e4. \ucf54\ub4dc \uc548\uc5d0 \uc6f9\uc0ac\uc774\ud2b8\uc758 \ubaa8\ub4e0 \ud654\uba74\uc774 \uc555\ucd95\ub418\uc5b4 \ub4e4\uc5b4 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc8fc\uc18c\ub97c \uc801\uc740 \uc885\uc774\ub97c \ubc1b\uc740 \ub4a4 \uadf8 \uc7a5\uc18c\ub85c \ucc3e\uc544\uac00\ub294 \uac83\ucc98\ub7fc, \ubb38\uc790\uc5f4\uc744 \uc77d\ub294 \ub2e8\uacc4\uc640 \uc778\ud130\ub137\uc73c\ub85c \uc2e4\uc81c \ub0b4\uc6a9\uc744 \uc5ec\ub294 \ub2e8\uacc4\uac00 \uc774\uc5b4\uc9c4\ub2e4. QR \ucf54\ub4dc\uc5d0\ub294 \ud06c\uae30\uc758 \ub2e8\uacc4\uac00 \uc788\ub2e4. \ub2f4\uc744 \ub370\uc774\ud130\uac00 \ub9ce\uc544\uc9c0\uac70\ub098 \ub354 \ub9ce\uc740 \uc624\ub958 \uc815\uc815 \uc815\ubcf4\ub97c \ub123\uc5b4\uc57c \ud558\uba74 \ud544\uc694\ud55c \uce78 \uc218\uac00 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc791\uc740 \ub3c4\ud615 \ud558\ub098\uc5d0 \ubb34\uc5c7\uc774\ub4e0 \ubb34\ud55c\ud788 \ub123\uc744 \uc218\ub294 \uc5c6\ub2e4. \uc77d\uae30 \uc27d\uac8c \uc778\uc1c4\ud560 \ud06c\uae30\uc640\ub3c4 \uad00\uacc4\uac00 \uc788\ub2e4. \uac19\uc740 \uc885\uc774 \uba74\uc801\uc5d0 \uce78\uc744 \ub354 \ucd18\ucd18\ud558\uac8c \ub123\uc73c\uba74 \uce74\uba54\ub77c\uac00 \uac01 \uce78\uc744 \uad6c\ubcc4\ud558\uae30 \uc5b4\ub824\uc6cc\uc9c8 \uc218 \uc788\ub2e4. \ud734\ub300\uc804\ud654\uc758 \uc131\ub2a5\uacfc \ube5b, \uc778\uc1c4 \uc0c1\ud0dc\ub3c4 \uc601\ud5a5\uc744 \uc900\ub2e4. \ub370\uc774\ud130\uac00 \ub4e4\uc5b4\uac08 \uc774\ub860\uc801\uc778 \uacf5\uac04\uacfc \uc0ac\ub78c\uc774 \ud3b8\ud558\uac8c \ube44\ucd94\uc5b4 \uc77d\ub294 \uc2e4\uc81c \uc870\uac74\uc744 \ud568\uaed8 \uace0\ub824\ud574\uc57c \ud55c\ub2e4. QR \ucf54\ub4dc\uc5d0\ub294 \uc6d0\ub798 \ub370\uc774\ud130\uc640 \ud568\uaed8 \uc624\ub958 \uc815\uc815\uc744 \uc704\ud55c \uc815\ubcf4\uac00 \ub4e4\uc5b4\uac04\ub2e4. \ud655\uc778\ud55c \uad6c\ud604\uc740 \ub9ac\ub4dc-\uc194\ub85c\ubaac\uc774\ub77c\ub294 \uc624\ub958 \uc815\uc815 \ubc29\ubc95\uc744 \uc0ac\uc6a9\ud55c\ub2e4. \uc774\ub984\uc744 \uc678\uc6b0\uae30\ubcf4\ub2e4 \uc77c\ubd80 \uc815\ubcf4\uac00 \uc190\uc0c1\ub418\uc5b4\ub3c4 \uc6d0\ub798 \uac12\uc744 \ubcf5\uc6d0\ud560 \uc5ec\uc9c0\ub97c \ub450\ub294 \uc7a5\uce58\ub85c \uc774\ud574\ud558\uba74 \ub41c\ub2e4. \uc815\uc815\uc758 \uc218\uc900\ub3c4 \uc5ec\ub7ec \ub2e8\uacc4\ub2e4. \ubcf5\uc6d0\uc5d0 \ud544\uc694\ud55c \uc815\ubcf4\ub97c \ub354 \ub2f4\uc73c\uba74 \uadf8\ub9cc\ud07c \uc0ac\uc6a9\ud560 \uacf5\uac04\uacfc\uc758 \uad00\uacc4\uac00 \uc0dd\uae34\ub2e4. \ub530\ub77c\uc11c \ucf54\ub4dc\ub294 \uc870\uae08 \uac00\ub824\uc838\ub3c4 \ubc18\ub4dc\uc2dc \uc77d\ud78c\ub2e4\ub294 \ubcf4\uc99d\uc11c\ub294 \uc544\ub2c8\ub2e4. \uc5b4\ub290 \ubd80\ubd84\uc774 \uc5bc\ub9c8\ub098 \uc190\uc0c1\ub418\uc5c8\ub294\uc9c0, \uc0ac\uc9c4\uc774 \uc5b4\ub5a4 \uc0c1\ud0dc\uc778\uc9c0\uc5d0 \ub530\ub77c \uacb0\uacfc\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \ud070 \uc704\uce58 \ud45c\uc9c0\ub97c \ubaa8\ub450 \uc9c0\uc6cc\ub3c4 \uad1c\ucc2e\ub2e4\uace0 \uc0dd\uac01\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \ub370\uc774\ud130\ub97c \uadf8\ub300\ub85c \uce78\uc5d0 \ub193\uc73c\uba74 \uc6b0\uc5f0\ud788 \uc77d\uae30 \uae4c\ub2e4\ub85c\uc6b4 \ubb34\ub2ac\uac00 \uc0dd\uae38 \uc218 \uc788\ub2e4. \ud655\uc778\ud55c \ud504\ub85c\uadf8\ub7a8\uc740 \uc5ec\ub7ec \ub9c8\uc2a4\ud06c\ub97c \uc801\uc6a9\ud574 \ubcf4\uace0, \ud070 \ub369\uc5b4\ub9ac\ub098 \ubc18\ubcf5 \ub4f1 \ubd88\ub9ac\ud55c \ud328\ud134\uc5d0 \uc810\uc218\ub97c \ub9e4\uaca8 \ub354 \uc801\ud569\ud55c \uacb0\uacfc\ub97c \uace0\ub978\ub2e4. \uc5ec\uae30\uc11c \ub9c8\uc2a4\ud06c\ub294 \ub370\uc774\ud130\ub97c \uc815\ud574\uc9c4 \uaddc\uce59\uc73c\ub85c \ubc14\uafb8\ub294 \uacfc\uc815\uc774\ub2e4. \ube44\ubc00\ubc88\ud638\ub85c \ub0b4\uc6a9\uc744 \uac10\ucd94\ub294 \uc554\ud638\ud654\uc640\ub294 \ubaa9\uc801\uc774 \ub2e4\ub974\ub2e4. \uc77d\ub294 \ucabd\ub3c4 \uc815\ud574\uc9c4 \uc815\ubcf4\ub97c \ubcf4\uace0 \uaddc\uce59\uc744 \ub418\ub3cc\ub9b4 \uc218 \uc788\ub2e4. \uac80\uc740 \uce78\uc774 \ub4a4\uc11e\uc778 \uac83\ucc98\ub7fc \ubcf4\uc5ec\ub3c4 \uc544\ubb34\ub807\uac8c\ub098 \ud769\ubfcc\ub9b0 \uadf8\ub9bc\uc774 \uc544\ub2cc \uc774\uc720\ub2e4. \ub0b4\uc6a9\uc744 \ub2f4\ub294 \uc77c\uacfc \uadf8 \ub0b4\uc6a9\uc744 \uc798 \uc77d\ud788\ub3c4\ub85d \ubc30\uc5f4\ud558\ub294 \uc77c\uc774 \ud568\uaed8 \ub4e4\uc5b4 \uc788\ub2e4. \uae30\uacc4\uac00 \ucf54\ub4dc\ub97c \uc815\ud655\ud788 \uc77d\uc5c8\ub2e4\uace0 \uc5f0\uacb0\ub41c \uc8fc\uc18c\uae4c\uc9c0 \uc88b\uc740 \uacf3\uc774\ub77c\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc624\ub958 \uc815\uc815\uc740 \ubb34\ub2ac\uac00 \ub9dd\uac00\uc838 \uc0dd\uae30\ub294 \ubb38\uc81c\ub97c \ub2e4\ub8e8\uc9c0, \uc8fc\uc18c\ub97c \ub9cc\ub4e0 \uc0ac\ub78c\uc758 \uc758\ub3c4\ub97c \uc2ec\uc0ac\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uae00\uc528\uac00 \uc120\uba85\ud55c \uc548\ub0b4\ubb38\ub3c4 \ub0b4\uc6a9\uc740 \ub530\ub85c \uc0b4\ud3b4\uc57c \ud558\ub294 \uac83\uacfc \uac19\ub2e4. \uc8fc\uc18c\ub97c \ud655\uc778\ud558\ub294 \uae30\ub2a5\uc774 \ubcf4\uc774\uba74 \uc5b4\ub514\ub85c \uc5f0\uacb0\ub418\ub294\uc9c0 \ubcf4\uace0 \uc5f4\uba74 \ub41c\ub2e4. \uc774\uac83\uc740 QR \ucf54\ub4dc\uac00 \ud2b9\ubcc4\ud788 \uc218\uc0c1\ud558\ub2e4\ub294 \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub77c \uc77d\uae30\uc640 \uc2e0\ub8b0\ub97c \uad6c\ubd84\ud558\ub294 \uae30\ubcf8\uc801\uc778 \ud0dc\ub3c4\ub2e4. \ud654\uba74\uc5d0\uc11c \ubb38\uc790\uc5f4\uc744 \uc5bb\ub294 \uae30\uc220\uacfc \uadf8 \ub4a4\uc758 \uc11c\ube44\uc2a4\ub294 \uc11c\ub85c \ub2e4\ub978 \uc5ed\ud560\uc744 \ub9e1\ub294\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uce74\ud398\uc5d0\uc11c \ud734\ub300\uc804\ud654\ub85c \uba54\ub274\ub97c \ud655\uc778\ud558\ub294 \ubd84\uc704\uae30\ub97c \ub2f4\uc558\ub2e4. \uac00\uc9dc QR \ubb34\ub2ac\ub97c \uc2e4\uc81c \uc791\ub3d9\ud558\ub294 \ucf54\ub4dc\ucc98\ub7fc \uc81c\uc2dc\ud558\uc9c0 \uc54a\ub3c4\ub85d \uce74\ub4dc\uc758 \ub4b7\uba74\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ucf54\ub4dc\uc758 \uc0dd\uae40\uc0c8\ub97c \uc7ac\ud604\ud55c \uae30\uc220 \ub3c4\ud310\uc774 \uc544\ub2c8\ub77c \uc4f0\uc784\uc744 \ub5a0\uc62c\ub9ac\ub294 \uc7a5\uba74\uc774\ub2e4. \uc774\uc81c QR \ucf54\ub4dc\ub97c \ub9cc\ub098\uba74 \uc138 \ubaa8\uc11c\ub9ac\uc758 \ud070 \ub124\ubaa8\uc640 \ub098\uba38\uc9c0 \uc791\uc740 \uce78\ub4e4\uc744 \ub098\ub204\uc5b4 \ubcf4\uc790. \uc5b4\ub514\uc5d0 \uc788\ub294\uc9c0 \uc54c\ub824 \uc8fc\ub294 \ud45c\uc9c0\uc640 \ub0b4\uc6a9\uc744 \ub2f4\ub294 \ubd80\ubd84, \uc190\uc0c1\uc744 \uacac\ub514\uae30 \uc704\ud55c \uc815\ubcf4\uac00 \ud568\uaed8 \uc788\ub2e4. \uc791\uc740 \ubb34\ub2ac \ud558\ub098\ub97c \uc77d\ub294 \uc21c\uac04\uc5d0\ub3c4 \uae30\uacc4\uac00 \uae38\uc744 \uc783\uc9c0 \uc54a\uac8c \ud558\ub294 \uc5ec\ub7ec \uc57d\uc18d\uc774 \uc870\uc6a9\ud788 \uc791\ub3d9\ud558\uace0 \uc788\ub2e4."}, {"id": "sqlite-small-database", "title": "SQLite \u2014 \uc571\uc758 \uae30\ub85d\uc740 \uc5b4\ub514\uc5d0 \ubaa8\uc5ec \uc788\uc744\uae4c", "summary": "\uac00\uc0c1\uc758 \uc694\ub9ac \uae30\ub85d \uc571\uc744 \ud1b5\ud574 \ud45c\u00b7\uc9c8\uc758\u00b7\ubcc0\uacbd \ud655\uc815\uacfc \ub85c\uceec \ub370\uc774\ud130\ubca0\uc774\uc2a4\uc758 \uc5ed\ud560\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "computing", "category_title": "Computing", "subcategory": "Software", "url": "stories/sqlite-small-database/index.html", "image": "media/sqlite-small-database.png", "alt": "\uc2dd\uc7ac\ub8cc\uc640 \uc694\ub9ac \ub178\ud2b8, \uae30\uae30 \uacc1\uc5d0\uc11c \uae30\ub85d\uc744 \uc815\ub9ac\ud558\ub294 \uc0ac\ub78c\uc758 AI \ube44\uc720 \uc7a5\uba74.", "text": "SQLite \u2014 \uc571\uc758 \uae30\ub85d\uc740 \uc5b4\ub514\uc5d0 \ubaa8\uc5ec \uc788\uc744\uae4c \uc791\uc740 \ub370\uc774\ud130\ubca0\uc774\uc2a4\uac00 \uc815\ubcf4\ub97c \uc815\ub9ac\ud558\uace0 \ub2e4\uc2dc \ucc3e\ub294 \ubc29\ubc95 \uac00\uc0c1\uc758 \uc694\ub9ac \uae30\ub85d \uc571\uc744 \ud1b5\ud574 \ud45c\u00b7\uc9c8\uc758\u00b7\ubcc0\uacbd \ud655\uc815\uacfc \ub85c\uceec \ub370\uc774\ud130\ubca0\uc774\uc2a4\uc758 \uc5ed\ud560\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Software \ucef4\ud4e8\ud305 \uc694\ub9ac \uae30\ub85d \uc571\uc5d0 \uc88b\uc544\ud558\ub294 \uba54\ub274\ub97c \ud558\ub098 \uc800\uc7a5\ud55c\ub2e4. \ub2e4\uc74c\uc5d0\ub294 \uc774\ub984\uc73c\ub85c \ucc3e\uace0, \uc870\ub9ac \uc2dc\uac04\uc774 \uc9e7\uc740 \uac83\ub9cc \uace8\ub77c \ubcf8\ub2e4. \ud654\uba74\uc5d0\ub294 \uba87 \ubc88\uc758 \ud130\uce58\ub9cc \uc788\uc9c0\ub9cc \uadf8 \ub4a4\uc5d0\uc11c\ub294 \uae30\ub85d\uc744 \uc815\ub9ac\ud558\uace0 \ub2e4\uc2dc \uaebc\ub0b4\ub294 \uc77c\uc774 \ud544\uc694\ud558\ub2e4. \uc571\uc758 \uae30\uc5b5\uc740 \uc5b4\ub5bb\uac8c \uad00\ub9ac\ub420\uae4c. SQLite\ub294 \uc774\ub7f0 \ub0b4\ubd80 \uc800\uc7a5\uc5d0 \uc4f0\uc77c \uc218 \uc788\ub294 \uc791\uc740 \ub370\uc774\ud130\ubca0\uc774\uc2a4 \uae30\uc220\uc774\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc2e4\uc81c \ud2b9\uc815 \uc694\ub9ac \uc571\uc744 \ubd84\uc11d\ud55c \uac83\uc774 \uc544\ub2c8\ub77c \uac00\uc0c1\uc758 \uae30\ub85d\uc7a5\uc744 \ud1b5\ud574 \uc6d0\ub9ac\ub97c \uc0b4\ud3b4\ubcf8\ub2e4. \ucf54\ub4dc\ub97c \ubc30\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \uc800\uc7a5\ub41c \uc790\ub8cc\uc5d0 \uc9c8\ubb38\uc744 \ub358\uc9c0\ub294 \ubc29\uc2dd\uc774\ub77c\ub294 \uc810\uc740 \ucda9\ubd84\ud788 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \ub178\ud2b8\uc5d0 \ub41c\uc7a5\uad6d, 20\ubd84\uc774\ub77c\uace0 \uc801\uc73c\uba74 \uc0ac\ub78c\uc740 \uc774\ub984\uacfc \uc2dc\uac04\uc744 \uc54c\uc544\uc11c \ub098\ub208\ub2e4. \ucef4\ud4e8\ud130\uc5d0\uc11c \uac19\uc740 \uc77c\uc744 \ud558\ub824\uba74 \uc5b4\ub5a4 \uac12\uc774 \uc774\ub984\uc774\uace0 \uc5b4\ub5a4 \uac12\uc774 \uc870\ub9ac \uc2dc\uac04\uc778\uc9c0 \uc815\ub9ac\ud574\uc57c \ud55c\ub2e4. \ub370\uc774\ud130\ubca0\uc774\uc2a4\uc5d0\uc11c\ub294 \ud45c\uc758 \uc5f4\uc744 \uc774\uc6a9\ud574 \uc774\ub7f0 \ud56d\ubaa9\uc744 \uad6c\ubd84\ud560 \uc218 \uc788\ub2e4. \ud55c \ud589\uc5d0 \ud558\ub098\uc758 \uae30\ub85d\uc744 \ub123\uc73c\uba74 \ube44\uc2b7\ud55c \ud615\uc2dd\uc758 \uc815\ubcf4\uac00 \uacc4\uc18d \uc313\uc778\ub2e4. \ubb3c\ub860 \uc5b4\ub5a4 \ud56d\ubaa9\uc744 \ub458\uc9c0\ub294 \uc571\uc744 \uc124\uacc4\ud558\ub294 \uc0ac\ub78c\uc758 \uc120\ud0dd\uc774\ub2e4. SQLite\uac00 \uc694\ub9ac\uc5d0 \ud544\uc694\ud55c \ubaa8\ub4e0 \uc815\ubcf4\ub97c \uc2a4\uc2a4\ub85c \uc815\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc798 \uc815\ub9ac\ud560 \uad6c\uc870\uc640 \uadf8 \uc548\uc5d0 \ub123\uc744 \ub0b4\uc6a9\uc740 \uc0ac\ub78c\uc774 \ub9c8\ub828\ud574\uc57c \ud55c\ub2e4. \uc0ac\uc6a9\uc790\ub294 \uc608\uc05c \uce74\ub4dc\ub098 \ubaa9\ub85d\uc73c\ub85c \uae30\ub85d\uc744 \ubcfc \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \ub0b4\ubd80\uc758 \uc800\uc7a5 \ubc29\uc2dd\uc774 \ud654\uba74\uc758 \uce74\ub4dc\uc640 \ub611\uac19\uc740 \ubaa8\uc591\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \uae30\ub85d\uc744 \ud45c\ub85c \uad00\ub9ac\ud558\uace0 \ud544\uc694\ud55c \uacb0\uacfc\ub9cc \uaebc\ub0b4 \uc6d0\ud558\ub294 \ud654\uba74\uc73c\ub85c \ubcf4\uc5ec \uc904 \uc218 \uc788\ub2e4. \uadf8\ub798\uc11c \ub370\uc774\ud130\ubca0\uc774\uc2a4\ub77c\ub294 \ub9d0\uc774 \ubd99\uc5c8\ub2e4\uace0 \ud56d\uc0c1 \ucee4\ub2e4\ub780 \ud45c \ud654\uba74\uc744 \uc9c1\uc811 \ub2e4\ub8e8\uc5b4\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub9ce\uc740 \uacbd\uc6b0 \uc0ac\uc6a9\uc790\ub294 \uc800\uc7a5\uacfc \uac80\uc0c9 \ubc84\ud2bc\ub9cc \ub9cc\ub09c\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \ub514\uc790\uc778\uacfc \uadf8 \ub4a4\uc758 \uc815\ubcf4 \uc870\uc9c1\uc740 \uc11c\ub85c \ub2e4\ub978 \uc5ed\ud560\uc744 \ub9e1\uace0 \uc788\ub2e4. \ub370\uc774\ud130\ubca0\uc774\uc2a4\uc5d0\ub294 \uc5b4\ub5a4 \uae30\ub85d\uc744 \uc6d0\ud558\ub294\uc9c0 \uc9c8\uc758\ud560 \uc218 \uc788\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \uc870\ub9ac \uc2dc\uac04\uc774 20\ubd84 \uc774\ud558\uc778 \uba54\ub274\ub97c \ucc3e\uc544 \ub2ec\ub77c\uace0 \ud558\ub294 \uc2dd\uc774\ub2e4. \uc2e4\uc81c \ud504\ub85c\uadf8\ub7a8\uc740 \uc774\ub97c SQL\uc774\ub77c\ub294 \uc5b8\uc5b4\uc758 \uc815\ud574\uc9c4 \ud615\ud0dc\ub85c \uc804\ub2ec\ud560 \uc218 \uc788\ub2e4. \uc5ec\uae30\uc11c \uc911\uc694\ud55c \uac83\uc740 \ubb38\ubc95\uc744 \uc678\uc6b0\ub294 \uc77c\uc774 \uc544\ub2c8\ub2e4. \uc800\uc7a5\ud55c \ubaa8\ub4e0 \uae30\ub85d\uc744 \uc0ac\ub78c\uc5d0\uac8c \ubcf4\uc5ec \uc8fc\uace0 \ud558\ub098\uc529 \uace8\ub77c\ub0b4\uac8c \ud558\ub294 \ub300\uc2e0, \ud544\uc694\ud55c \uc870\uac74\uc744 \ub370\uc774\ud130\uc5d0 \uc9c8\ubb38\ud560 \uc218 \uc788\ub2e4\ub294 \uc810\uc774\ub2e4. \uae30\ub85d\uc774 \ub9ce\uc544\uc9c8\uc218\ub85d \uc774\ub7f0 \uc815\ub9ac\uc640 \uc9c8\ubb38\uc758 \ubc29\uc2dd\uc774 \uc0ac\uc6a9 \uacbd\ud5d8\uc5d0 \uc601\ud5a5\uc744 \uc900\ub2e4. \ud30c\uc774\uc36c\uc758 \uacf5\uc2dd \ubb38\uc11c\ub294 SQLite\ub97c \ubcc4\ub3c4\uc758 \uc11c\ubc84 \ud504\ub85c\uc138\uc2a4\uac00 \ud544\uc694\ud558\uc9c0 \uc54a\uc740 \uac00\ubcbc\uc6b4 \ub514\uc2a4\ud06c \uae30\ubc18 \ub370\uc774\ud130\ubca0\uc774\uc2a4\ub85c \uc18c\uac1c\ud55c\ub2e4. \ub370\uc774\ud130\ubca0\uc774\uc2a4\ub97c \ub5a0\uc62c\ub9b4 \ub54c \ubc18\ub4dc\uc2dc \uba40\ub9ac \ub5a8\uc5b4\uc9c4 \ud070 \uc11c\ubc84\uc2e4\ubd80\ud130 \uc0c1\uc0c1\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4\ub294 \ub73b\uc774\ub2e4. \uc571\uc774 \uc790\uccb4 \uae30\ub85d\uc744 \uad00\ub9ac\ud558\ub294 \ub370 \uc774\ub97c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4. \ub370\uc774\ud130\uc640 \ud544\uc694\ud55c \uae30\ub2a5\uc774 \uae30\uae30\uc5d0 \uc900\ube44\ub418\uc5b4 \uc788\ub2e4\uba74 \uc778\ud130\ub137\uc774 \uc5c6\ub294 \uc0c1\ud669\uc5d0\uc11c\ub3c4 \uc77c\ubd80 \uae30\ub2a5\uc744 \uc81c\uacf5\ud558\ub294 \uad6c\uc870\ub97c \ub9cc\ub4e4 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ubaa8\ub4e0 \uc571\uc774 SQLite\ub97c \uc4f0\uac70\ub098 \uc5b8\uc81c\ub098 \uc624\ud504\ub77c\uc778\uc73c\ub85c \uc791\ub3d9\ud55c\ub2e4\ub294 \ub9d0\uc740 \uc544\ub2c8\ub2e4. \uc571\uc758 \uc124\uacc4\uc640 \ub2e4\ub978 \uc11c\ube44\uc2a4 \uc758\uc874\uc131\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c4\ub2e4. \ub370\uc774\ud130\ub97c \uace0\uce58\ub294 \uacfc\uc815\uc5d0\ub294 \uc5ec\ub7ec \ubcc0\uacbd\uc744 \ud558\ub098\uc758 \uc791\uc5c5 \ub2e8\uc704\ub85c \ub2e4\ub8e8\ub294 \uacbd\uc6b0\uac00 \uc788\ub2e4. \ud2b8\ub79c\uc7ad\uc158\uc774\ub77c\ub294 \ub9d0\uc774\ub2e4. \uc900\ube44\ud55c \ubcc0\uacbd\uc744 \ud655\uc815\ud558\uac70\ub098, \uc544\uc9c1 \ud655\uc815\ud558\uc9c0 \uc54a\uc740 \uc791\uc5c5\uc744 \ub418\ub3cc\ub9ac\ub294 \uae30\ub2a5\uc744 \uc774\uc6a9\ud560 \uc218 \uc788\ub2e4. \ubb38\uc11c\uc758 \ucd08\uc548\uc744 \ud655\uc778\ud55c \ub4a4 \uc800\uc7a5\ud558\ub294 \uacbd\ud5d8\uacfc \ub2ee\uc740 \ubd80\ubd84\uc774 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc774 \ube44\uc720\uac00 \ud504\ub85c\uadf8\ub7a8\uc758 \ubaa8\ub4e0 \ub3d9\uc791\uc744 \uc124\uba85\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc5b4\ub5a4 \uc2dc\uc810\uc5d0 \ubb34\uc5c7\uc744 \ud655\uc815\ud560\uc9c0\ub294 \uc0ac\uc6a9\ud558\ub294 \ubc29\uc2dd\uacfc \uc124\uc815\uc5d0 \uad00\uacc4\uac00 \uc788\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \ubcc0\uacbd\uc744 \uc815\ub9ac\ud558\uace0 \uc801\uc6a9\ud560 \uaddc\uce59\uc774 \uc788\uc73c\uba70, \ud654\uba74\uc5d0 \ud55c \ubc88 \uac12\uc744 \ub123\ub294 \ud589\uc704\uc640 \ub0b4\ubd80 \uae30\ub85d\uc744 \uc77c\uad00\ub418\uac8c \uad00\ub9ac\ud558\ub294 \uc77c\uc774 \uac19\uc9c0 \uc54a\ub2e4\ub294 \uc810\uc774\ub2e4. \uc694\ub9ac \uc774\ub984\uacfc \uc2dd\uc7ac\ub8cc \uc815\ubcf4\ub97c \uac01\uac01 \uad00\ub9ac\ud558\uace0 \uad00\uacc4\ub97c \ub9fa\ub294 \ubc29\uc2dd\ub3c4 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uac19\uc740 \uc7ac\ub8cc\uc758 \uc774\ub984\uc744 \ub9e4\ubc88 \ub2e4\ub978 \ucca0\uc790\ub85c \uc801\ub294 \ubb38\uc81c\ub97c \uc904\uc774\uace0, \uc5b4\ub5a4 \uba54\ub274\uc5d0 \uc4f0\uc600\ub294\uc9c0 \ucc3e\uc544\ubcfc \uc218 \uc788\ub2e4. \uc774\uac83\uc740 \ub370\uc774\ud130 \uad6c\uc870\ub97c \uc124\uba85\ud558\uae30 \uc704\ud55c \uac00\uc0c1 \uc608\ub2e4. \uc2e4\uc81c \uc571\uc5d0\uc11c \ud45c\ub97c \uc5b4\ub5bb\uac8c \ub098\ub20c\uc9c0\ub294 \uc790\ub8cc\uc758 \uc131\uaca9\uacfc \ud544\uc694\uc5d0 \ub530\ub77c \uc815\ud55c\ub2e4. \ubaa8\ub4e0 \uae30\ub85d\uc744 \uc798\uac8c \ub098\ub204\ub294 \uac83\uc774 \uc5b8\uc81c\ub098 \ucd5c\uc120\uc740 \uc544\ub2c8\uace0, \ud55c \ud45c\uc5d0 \uc804\ubd80 \uc801\ub294 \uac83\uc774 \uc5b8\uc81c\ub098 \uac04\ud3b8\ud55c \uac83\ub3c4 \uc544\ub2c8\ub2e4. \uc798 \uc4f0\ub294 \ub370\uc774\ud130\ubca0\uc774\uc2a4 \ub4a4\uc5d0\ub294 \ubb34\uc5c7\uc744 \uac19\uac8c \ubcf4\uace0 \uc5b4\ub5a4 \uad00\uacc4\ub97c \ub0a8\uae38\uc9c0\uc5d0 \ub300\ud55c \ud310\ub2e8\uc774 \uc788\ub2e4. \ub0b4 \uae30\uae30\uc5d0 \uae30\ub85d\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ub2e4\ub978 \uae30\uae30\uc5d0\ub3c4 \uc790\ub3d9\uc73c\ub85c \ub098\ud0c0\ub098\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5ec\ub7ec \uae30\uae30\uc5d0\uc11c \ud568\uaed8 \uc4f0\ub824\uba74 \ub3d9\uae30\ud654 \uac19\uc740 \ubcc4\ub3c4\uc758 \uc124\uacc4\uac00 \ud544\uc694\ud558\ub2e4. \ub370\uc774\ud130\ubca0\uc774\uc2a4 \uae30\uc220\uc758 \uc774\ub984 \ud558\ub098\uac00 \uc774\ub7f0 \ubaa8\ub4e0 \uc11c\ube44\uc2a4\ub97c \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub610 \ud30c\uc77c\uc5d0 \uae30\ub85d\uc774 \uc788\ub2e4\ub294 \uac83\uacfc \uc548\uc804\ud55c \ubc31\uc5c5\uc774 \ub530\ub85c \uc788\ub2e4\ub294 \uac83\ub3c4 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ud30c\uc774\uc36c \uacf5\uc2dd \ubb38\uc11c\uc5d0\ub294 \ub370\uc774\ud130\ubca0\uc774\uc2a4 \ubc31\uc5c5 \uae30\ub2a5\ub3c4 \uc124\uba85\ub418\uc5b4 \uc788\ub2e4. \uc774\ub294 \ubc31\uc5c5\uc744 \ub9c8\ub828\ud560 \uc218 \uc788\ub294 \ubc29\ubc95\uc774 \uc788\ub2e4\ub294 \ub73b\uc774\uc9c0, SQLite\ub97c \uc0ac\uc6a9\ud558\ub294 \ubaa8\ub4e0 \uc571\uc774 \uac19\uc740 \ubcf4\uad00 \uc815\ucc45\uc744 \uc790\ub3d9\uc73c\ub85c \uac16\ub294\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uc694\ub9ac \ub178\ud2b8\uc640 \uae30\uae30\ub97c \ub193\uace0 \uae30\ub85d\uc744 \uc815\ub9ac\ud558\ub294 \uc7a5\uba74\uc774\ub2e4. \uc2e4\uc81c SQLite\uc758 \ud654\uba74\uc774\ub098 \ud2b9\uc815 \uc571\uc758 \uae30\ub2a5\uc744 \uc7ac\ud604\ud558\uc9c0 \uc54a\uc558\ub2e4. \uc870\uc6a9\ud788 \uc790\ub8cc\ub97c \ubaa8\uc73c\uace0 \ub2e4\uc2dc \ucc3e\ub294 \uc77c\uc758 \ubd84\uc704\uae30\ub97c \ub2f4\uc558\ub2e4. SQLite\uc758 \uc7ac\ubbf8\ub294 \ud06c\uace0 \ubcf5\uc7a1\ud55c \uae30\uc220\uc774 \uc788\uc5b4\uc57c\ub9cc \ub370\uc774\ud130\ubca0\uc774\uc2a4\ub77c\ub294 \uc0dd\uac01\uc744 \ubc14\uafb8\uc5b4 \uc900\ub2e4\ub294 \ub370 \uc788\ub2e4. \uc791\uc740 \uae30\ub85d\uc5d0\ub3c4 \uad6c\uc870\uc640 \uc9c8\ubb38, \ubcc0\uacbd\uc744 \ub2e4\ub8e8\ub294 \uc57d\uc18d\uc774 \ud544\uc694\ud558\ub2e4. \ub2e4\uc74c\uc5d0 \uc571\uc5d0\uc11c \uc624\ub798\uc804 \uc800\uc7a5\ud55c \ud56d\ubaa9\uc744 \ucc3e\uc73c\uba74 \uadf8 \uac04\ub2e8\ud55c \uacb0\uacfc \ub4a4\uc5d0 \uc815\ubcf4\ub97c \uc815\ub9ac\ud574 \ub454 \ubc29\uc2dd\ub3c4 \uc7a0\uae50 \ub5a0\uc62c\ub824 \ubcfc \uc218 \uc788\ub2e4."}, {"id": "svg-shapes-not-fixed-pixels", "title": "SVG \u2014 \uc810 \ub300\uc2e0 \uc120\uc758 \ubaa8\uc591\uc744 \uae30\ub85d\ud558\uba74", "summary": "\ubca1\ud130 \ub3c4\ud615\uacfc \ud53d\uc140 \uc774\ubbf8\uc9c0\uc758 \ucc28\uc774\uc5d0\uc11c SVG\uc758 \ud655\ub300\u00b7\uad6c\uc131\u00b7\ud55c\uacc4\ub97c \uc27d\uac8c \uc774\ud574\ud569\ub2c8\ub2e4.", "category": "computing", "category_title": "Computing", "subcategory": "Software", "url": "stories/svg-shapes-not-fixed-pixels/index.html", "image": "media/svg-shapes-not-fixed-pixels.png", "alt": "\uc885\uc774 \uc704 \ub3c4\ud615\uacfc \uace1\uc120\uc744 \uc0b4\ud3b4\ubcf4\uba70 \uadf8\ub9bc\uc744 \ub9cc\ub4dc\ub294 \uc791\uc5c5 \uc7a5\uba74\uc758 \uc0bd\ud654.", "text": "SVG \u2014 \uc810 \ub300\uc2e0 \uc120\uc758 \ubaa8\uc591\uc744 \uae30\ub85d\ud558\uba74 \uc791\uc740 \uc544\uc774\ucf58\uc744 \ud06c\uac8c \uc368\ub3c4 \uc120\uc774 \uc774\uc5b4\uc9c0\ub294 \uc774\uc720 \ubca1\ud130 \ub3c4\ud615\uacfc \ud53d\uc140 \uc774\ubbf8\uc9c0\uc758 \ucc28\uc774\uc5d0\uc11c SVG\uc758 \ud655\ub300\u00b7\uad6c\uc131\u00b7\ud55c\uacc4\ub97c \uc27d\uac8c \uc774\ud574\ud569\ub2c8\ub2e4. Software \ucef4\ud4e8\ud305 \uc791\uc740 \uc544\uc774\ucf58\uc744 \ud06c\uac8c \ub298\ub838\ub354\ub2c8 \uac00\uc7a5\uc790\ub9ac\uac00 \ub124\ubaa8 \uacc4\ub2e8\ucc98\ub7fc \ubcf4\uc778\ub2e4. \ubc18\uba74 \uc5b4\ub5a4 \uadf8\ub9bc\uc740 \uac19\uc740 \uc77c\uc744 \ud574\ub3c4 \uc120\uc774 \ub9e4\ub048\ud558\uac8c \uc774\uc5b4\uc9c4\ub2e4. \ub458 \ub2e4 \ud654\uba74\uc758 \uadf8\ub9bc\uc778\ub370 \uc65c \ud655\ub300\ud588\uc744 \ub54c \ub2e4\ub974\uac8c \ubcf4\uc77c\uae4c. \uc774\ubbf8\uc9c0\uac00 \ubb34\uc5c7\uc744 \uae30\ub85d\ud558\uace0 \uc788\ub294\uc9c0\uac00 \ub2e4\ub974\uae30 \ub54c\ubb38\uc774\ub2e4. \ud53d\uc140\ub9c8\ub2e4\uc758 \uc0c9\uc744 \uc800\uc7a5\ud558\ub294 \ubc29\uc2dd\uacfc \uc120\uacfc \ub3c4\ud615\uc744 \uc124\uba85\ud558\ub294 \ubc29\uc2dd\uc774 \uc788\ub2e4. SVG\ub294 \ud6c4\uc790\uc5d0 \uc4f0\uc774\ub294 \ud615\uc2dd\uc774\ub2e4. \uadf8 \uc774\ub984\uc744 \uc54c\uba74 \uc778\ud130\ub137\uc758 \uc791\uc740 \uadf8\ub9bc\uc744 \ubcf4\ub294 \ub208\ub3c4 \uc870\uae08 \ub2ec\ub77c\uc9c4\ub2e4. \uc0ac\uc9c4 \uac19\uc740 \ub798\uc2a4\ud130 \uc774\ubbf8\uc9c0\ub294 \uc815\ud574\uc9c4 \uc218\uc758 \ud53d\uc140\uc5d0 \uc0c9 \uc815\ubcf4\ub97c \ub2f4\ub294\ub2e4. \ucda9\ubd84\ud788 \ud06c\uac8c \ud45c\uc2dc\ud558\uba74 \uc6d0\ub798\uc758 \uc791\uc740 \uc810\ub4e4\uc744 \ub354 \ub113\uc740 \ud654\uba74\uc5d0 \ud45c\ud604\ud574\uc57c \ud55c\ub2e4. \ud504\ub85c\uadf8\ub7a8\uc774 \uc0ac\uc774\uc758 \uac12\uc744 \uacc4\uc0b0\ud574 \ubd80\ub4dc\ub7fd\uac8c \ubcf4\uc774\uac8c \ud560 \uc218\ub294 \uc788\uc5b4\ub3c4 \ucc98\uc74c\uc5d0 \uc5c6\ub358 \ubaa8\ub4e0 \uc138\ubd80\ub97c \ub418\ucc3e\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774\uac83\uc740 \uc0ac\uc9c4\uc774 \ub098\uc05c \ud615\uc2dd\uc774\ub77c\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \ube5b\uacfc \uc9c8\uac10\uc758 \ubcf5\uc7a1\ud55c \ubcc0\ud654\ub97c \ub2f4\ub294 \ub370\ub294 \ud53d\uc140\uc758 \uc0c9\uc744 \uae30\ub85d\ud558\ub294 \ubc29\uc2dd\uc774 \uc798 \ub9de\ub294\ub2e4. \uc5b4\ub5a4 \uadf8\ub9bc\uc778\uc9c0\uc5d0 \ub530\ub77c \ud544\uc694\ud55c \ud45c\ud604\uc774 \ub2e4\ub974\ub2e4. \ud655\ub300\uc758 \uacb0\uacfc \ud558\ub098\ub85c \ubaa8\ub4e0 \uc774\ubbf8\uc9c0\uc758 \uc88b\uace0 \ub098\uc068\uc744 \uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc6d0 \ud55c \uac1c\ub97c \uadf8\ub9b0\ub2e4\uace0 \uc0dd\uac01\ud574 \ubcf4\uc790. \ud654\uba74\uc758 \uc810\ub9c8\ub2e4 \uc0c9\uc744 \ub0a8\uae38 \uc218\ub3c4 \uc788\uc9c0\ub9cc, \uc911\uc2ec\uc774 \uc5b4\ub514\uc774\uace0 \ubc18\uc9c0\ub984\uc774 \uc5bc\ub9c8\uc778\uc9c0 \uc124\uba85\ud560 \uc218\ub3c4 \uc788\ub2e4. \ud6c4\uc790\uc758 \uc815\ubcf4\ub97c \uc54c\uba74 \ub354 \ud070 \ud06c\uae30\uc5d0 \ub9de\ucd94\uc5b4 \uc6d0\uc744 \ub2e4\uc2dc \uadf8\ub9b4 \uc218 \uc788\ub2e4. \uc774\ub294 \ubca1\ud130 \ubc29\uc2dd\uc758 \uccab \uc774\ud574\ub97c \uc704\ud55c \uc608\ub2e4. \uc2e4\uc81c \ub3c4\ud615\uc5d0\ub294 \uc120\uc758 \ub450\uaed8\uc640 \uc0c9, \uc704\uce58 \uac19\uc740 \uc815\ubcf4\ub3c4 \ub4e4\uc5b4\uac04\ub2e4. \uc815\ud574\uc9c4 \uc791\uc740 \uadf8\ub9bc\uc744 \ub2e8\uc21c\ud788 \uc7a1\uc544\ub2f9\uae30\ub294 \ub300\uc2e0, \ubaa8\uc591\uc744 \uc124\uba85\ud55c \ub0b4\uc6a9\uc744 \ub2e4\ub978 \ud06c\uae30\ub85c \uadf8\ub824 \ub0b4\ub294 \ucc28\uc774\uac00 \uc788\ub2e4. \uc774 \ub54c\ubb38\uc5d0 \uc544\uc774\ucf58\uacfc \ub3c4\ud615\uc5d0\uc11c \uc7a5\uc810\uc774 \ub098\ud0c0\ub0a0 \uc218 \uc788\ub2e4. SVG\ub294 XML\uc744 \ubc14\ud0d5\uc73c\ub85c \ud558\ub294 \uc5b8\uc5b4\ub2e4. \uc6d0\uacfc \uc0ac\uac01\ud615, \uac04\ub2e8\ud558\uac70\ub098 \ubcf5\uc7a1\ud55c \uace1\uc120 \uac19\uc740 \uc694\uc18c\ub97c \ud45c\ud604\ud560 \uc218 \uc788\ub2e4. \uc5ec\ub7ec \ub3c4\ud615\uc744 \ubb36\uc5b4 \ud558\ub098\uc758 \uadf8\ub9bc\uc73c\ub85c \uc870\uc9c1\ud558\ub294 \ubc29\ubc95\ub3c4 \uc788\ub2e4. \uc0ac\ub78c\uc774 \ucf54\ub4dc\ub85c \uc9c1\uc811 \uc791\uc131\ud574\uc57c\ub9cc \ud558\ub294 \uac83\uc740 \uc544\ub2c8\uace0 \uc774\ub97c \ub2e4\ub8e8\ub294 \uadf8\ub9bc \ud504\ub85c\uadf8\ub7a8\ub3c4 \uc788\ub2e4. \uc5ec\uae30\uc11c\ub294 \ubb38\ubc95\uc744 \ubc30\uc6b8 \ud544\uc694\uac00 \uc5c6\ub2e4. \uadf8\ub9bc \ud30c\uc77c\uc758 \uc548\ucabd\uc5d0 \uc791\uc740 \uc0c9\uc810\ub9cc \ub4e4\uc5b4 \uc788\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ubaa8\uc591\uacfc \uad00\uacc4\ub97c \uc124\uba85\ud558\ub294 \uc815\ubcf4\uac00 \uc788\uc744 \uc218 \uc788\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \uac19\uc740 \ud654\uba74\uc758 \uadf8\ub9bc\ub3c4 \uadf8 \uc548\uc5d0 \uc801\uc5b4 \ub454 \ub0b4\uc6a9\uc740 \ub2e4\ub97c \uc218 \uc788\ub2e4. SVG\uc758 \ub3c4\ud615\uc740 \ud45c\uc2dc\ud560 \ud06c\uae30\uc5d0 \ub9de\ucd94\uc5b4 \ub2e4\uc2dc \uadf8\ub9b4 \uc218 \uc788\ub2e4. \uadf8\ub798\uc11c \ubca1\ud130\ub85c \uc815\uc758\ud55c \uc120\uacfc \uc724\uacfd\uc740 \ub798\uc2a4\ud130 \uc774\ubbf8\uc9c0\ub97c \ub2e8\uc21c\ud788 \ub298\ub9ac\ub294 \uacbd\uc6b0\uc640 \ub2e4\ub974\uac8c \ud655\ub300\ud560 \uc218 \uc788\ub2e4. \uac19\uc740 \ud45c\uc9c0\ub97c \uc791\uc740 \ubc84\ud2bc\uacfc \ud070 \ud654\uba74\uc5d0 \uc0ac\uc6a9\ud560 \ub54c \uc774\ub7f0 \ucc28\uc774\uac00 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc5b4\ub5a4 \ud06c\uae30\uc5d0\uc11c\ub3c4 \ubaa8\ub4e0 \ub514\ud14c\uc77c\uc774 \ub611\uac19\uc774 \ubcf4\uae30 \uc88b\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc544\uc8fc \uc791\uc740 \ud06c\uae30\uc5d0\uc11c\ub294 \ubcf5\uc7a1\ud55c \uc120\uc774 \uad6c\ubcc4\ub418\uc9c0 \uc54a\uc744 \uc218 \uc788\uace0, \ud45c\uc2dc \uc7a5\uce58\uc640 \uadf8\ub9ac\ub294 \ubc29\uc2dd\ub3c4 \uacb0\uacfc\uc5d0 \uc601\ud5a5\uc744 \uc900\ub2e4. \ub3c4\ud615 \uc815\ubcf4\ub97c \uc720\uc9c0\ud558\ub294 \uc77c\uacfc \uc77d\uae30 \uc88b\uc740 \ub514\uc790\uc778\uc740 \ud568\uaed8 \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4. MDN\uc740 SVG\uac00 \uc0c9\uc758 \uc810\uc9c4\uc801\uc778 \ubcc0\ud654\uc640 \ud68c\uc804, \ud544\ud130 \ud6a8\uacfc, \uc560\ub2c8\uba54\uc774\uc158 \ub4f1\ub3c4 \uc9c0\uc6d0\ud55c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub2e8\uc21c\ud55c \uc6d0 \uba87 \uac1c\ub9cc \uadf8\ub9ac\ub294 \ud615\uc2dd\uc740 \uc544\ub2cc \uac83\uc774\ub2e4. \uc5ec\ub7ec \uae30\ub2a5\uc744 \uc870\ud569\ud558\uba74 \uadf8\ub9bc\uc740 \uaf64 \ubcf5\uc7a1\ud574\uc9c8 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uae30\ub2a5\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ubaa8\ub4e0 \ud658\uacbd\uc774 \uac19\uc740 \uc218\uc900\uc73c\ub85c \uc9c0\uc6d0\ud55c\ub2e4\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \ubcf4\ub294 \ud504\ub85c\uadf8\ub7a8\uc5d0 \ub530\ub77c \uacb0\uacfc\uac00 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc774\ubc88 \uc774\uc57c\uae30\ub294 \uc791\uc740 \ub3c4\ud615\uc758 \uc6d0\ub9ac\ub97c \uc911\uc2ec\uc73c\ub85c \uc77d\ub294 \uac83\uc774\uba70 \ubaa8\ub4e0 \uc18c\ud504\ud2b8\uc6e8\uc5b4\uc5d0\uc11c \uac19\uc740 \ubaa8\uc2b5\uc774 \ubcf4\uc7a5\ub41c\ub2e4\ub294 \uc548\ub0b4\uac00 \uc544\ub2c8\ub2e4. SVG\ub294 \ub798\uc2a4\ud130 \uc774\ubbf8\uc9c0\uc640 \ub3c4\ud615\uc744 \ud568\uaed8 \ub2e4\ub8f0 \uc218\ub3c4 \uc788\ub2e4. \uadf8\ub798\uc11c \ud30c\uc77c \uc774\ub984\uc774 SVG\ub77c\uace0 \ub0b4\ubd80\uc758 \ubaa8\ub4e0 \ubd80\ubd84\uc774 \uc790\ub3d9\uc73c\ub85c \ubca1\ud130\uac00 \ub41c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc0ac\uc9c4\uc744 \ud3ec\ud568\ud55c \ubd80\ubd84\uc740 \uadf8 \uc0ac\uc9c4\uc774 \uac16\uace0 \uc788\ub294 \uc815\ubcf4\uc758 \ud55c\uacc4\ub97c \uc774\uc5b4\ubc1b\uc744 \uc218 \uc788\ub2e4. \uc774\ub294 PNG \ud30c\uc77c\uc774\ub77c\uace0 \ubaa8\ub450 \ud22c\uba85\ud55c \ubc30\uacbd\uc744 \uac16\uc9c0\ub294 \uc54a\ub294 \uac83\uacfc \ube44\uc2b7\ud55c \uad6c\ubd84\uc774\ub2e4. \ud615\uc2dd\uc774 \ud560 \uc218 \uc788\ub294 \uae30\ub2a5\uacfc \uc2e4\uc81c \ud30c\uc77c\uc5d0 \ub4e4\uc5b4 \uc788\ub294 \ub0b4\uc6a9\uc740 \ub2e4\ub974\ub2e4. \ud655\uc7a5\uc790\ub9cc \ubc14\uafb8\uc5b4 \ub0ae\uc740 \ud574\uc0c1\ub3c4\uc758 \uc0ac\uc9c4\uc744 \ub123\uc5c8\ub2e4\uace0 \uc5c6\ub294 \uc138\ubd80\uac00 \uc0c8\ub85c \uc0dd\uae30\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub2e8\uc21c\ud55c \ub3c4\ud615\uc740 \uc801\uc740 \uc124\uba85\uc73c\ub85c \ud45c\ud604\ud560 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \ubaa8\uc591\uc774 \ub9e4\uc6b0 \ubcf5\uc7a1\ud558\uace0 \ud6a8\uacfc\uac00 \ub9ce\uc73c\uba74 \ud544\uc694\ud55c \uc815\ubcf4\uc640 \ud45c\uc2dc \uc791\uc5c5\ub3c4 \ub298\uc5b4\ub0a0 \uc218 \uc788\ub2e4. SVG\uac00 \ubaa8\ub4e0 \uc0ac\uc9c4\uacfc \ubaa8\ub4e0 \uadf8\ub9bc\ubcf4\ub2e4 \uc791\uace0 \ube60\ub978 \ud615\uc2dd\uc774\ub77c\uace0 \uc815\ub9ac\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc5b4\ub5a4 \uc774\ubbf8\uc9c0\uc778\uc9c0\uc640 \uc5b4\ub514\uc5d0 \uc4f8\uc9c0\uac00 \uba3c\uc800\ub2e4. \ud654\uba74\uc758 \uc544\uc774\ucf58\uacfc \uc5ec\ud589 \uc0ac\uc9c4\uc740 \ud544\uc694\ud55c \uc131\uc9c8\uc774 \ub2e4\ub974\ub2e4. \uac00\uc7a5 \uc88b\uc740 \ud655\uc7a5\uc790 \ud558\ub098\ub97c \uace0\ub974\ub294 \ubb38\uc81c\ubcf4\ub2e4, \uadf8\ub9bc\uc774 \uc5b4\ub5a4 \uc815\ubcf4\ub97c \ub2f4\uace0 \uc5b4\ub5a4 \ud06c\uae30\uc5d0\uc11c \uc77d\ud600\uc57c \ud558\ub294\uc9c0\uc5d0 \ub9de\ucd94\uc5b4 \uc120\ud0dd\ud558\ub294 \ubb38\uc81c\uc5d0 \uac00\uae5d\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uace1\uc120\uacfc \ud06c\uae30\uac00 \ub2e4\ub978 \uc885\uc774 \ubaa8\uc591\uc744 \uc0b4\ud53c\ub294 \uc791\uc5c5 \uc7a5\uba74\uc774\ub2e4. \uc774 \uc0bd\ud654 \ud30c\uc77c \uc790\uccb4\uac00 SVG\uc774\uac70\ub098 \uc2e4\uc81c \ubca1\ud130\u00b7\ub798\uc2a4\ud130 \ud655\ub300\ub97c \ube44\uad50\ud55c \uc2e4\ud5d8 \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \ubaa8\uc591\uc744 \uc124\uba85\ud574 \ub2e4\uc2dc \uadf8\ub9b0\ub2e4\ub294 \uc0dd\uac01\uc744 \ub5a0\uc62c\ub9ac\ub294 \uc774\ubbf8\uc9c0\ub2e4. \ub2e4\uc74c\uc5d0 \uc791\uc740 \uc544\uc774\ucf58\uc744 \ud06c\uac8c \ubcf4\uac8c \ub418\uba74 \uadf8 \uadf8\ub9bc\uc774 \uc810\uc744 \uc800\uc7a5\ud588\ub294\uc9c0 \ub3c4\ud615\uc744 \uc124\uba85\ud588\ub294\uc9c0 \uad81\uae08\ud574\ud574 \ubcf4\uc790. \ub208\uc55e\uc758 \uacb0\uacfc\ub294 \ube44\uc2b7\ud574\ub3c4 \ud06c\uae30\ub97c \ubc14\uafc0 \ub54c \ub2e4\ub978 \uc131\uc9c8\uc774 \ub098\ud0c0\ub0a0 \uc218 \uc788\ub2e4. SVG\ub294 \uadf8\ub9bc\uc744 \ubcf4\uad00\ud558\ub294 \ubc29\uc2dd\uc5d0\ub3c4 \uc5ec\ub7ec \uc885\ub958\uc758 \uc5b8\uc5b4\uac00 \uc788\ub2e4\ub294 \uac83\uc744 \uc54c\ub824 \uc900\ub2e4."}, {"id": "unicode-letters-shared-numbers", "title": "\uc720\ub2c8\ucf54\ub4dc \u2014 \ub2e4\ub978 \ucef4\ud4e8\ud130\uc5d0\uc11c\ub3c4 \uac19\uc740 \uae00\uc790\ub97c \uc77d\ub294 \uc57d\uc18d", "summary": "\uae00\uc790\uc758 \uacf5\ud1b5 \ubc88\ud638\uc640 \uc800\uc7a5 \ubc29\uc2dd, \uae00\uaf34\uacfc \uc815\uaddc\ud654\uc758 \ucc28\uc774\ub97c \ud55c\uae00 \uc0ac\ub840\ub85c \uc27d\uac8c \uc774\ud574\ud569\ub2c8\ub2e4.", "category": "computing", "category_title": "Computing", "subcategory": "Software", "url": "stories/unicode-letters-shared-numbers/index.html", "image": "media/unicode-letters-shared-numbers.png", "alt": "\uc11c\ub85c \ub2e4\ub978 \uae30\uae30\ub97c \uc0ac\uc6a9\ud558\ub294 \ub450 \uc0ac\ub78c\uc774 \ucc45\uc774 \uaf42\ud78c \uacf5\uac04\uc5d0\uc11c \ub9c8\uc8fc \uc549\uc544 \ub300\ud654\ud558\ub294 AI \uc7a5\uba74.", "text": "\uc720\ub2c8\ucf54\ub4dc \u2014 \ub2e4\ub978 \ucef4\ud4e8\ud130\uc5d0\uc11c\ub3c4 \uac19\uc740 \uae00\uc790\ub97c \uc77d\ub294 \uc57d\uc18d \ud55c\uae00 \ud55c \uae00\uc790\uac00 \ud654\uba74\uc5d0 \ub3c4\ucc29\ud558\uae30\uae4c\uc9c0 \uae00\uc790\uc758 \uacf5\ud1b5 \ubc88\ud638\uc640 \uc800\uc7a5 \ubc29\uc2dd, \uae00\uaf34\uacfc \uc815\uaddc\ud654\uc758 \ucc28\uc774\ub97c \ud55c\uae00 \uc0ac\ub840\ub85c \uc27d\uac8c \uc774\ud574\ud569\ub2c8\ub2e4. Software \ucef4\ud4e8\ud305 \ud734\ub300\uc804\ud654\ub85c \uc548\ub155\ud558\uc138\uc694\ub77c\uace0 \ubcf4\ub0b4\uba74 \uc0c1\ub300\ubc29\uc740 \ub2e4\ub978 \uae30\uae30\uc5d0\uc11c\ub3c4 \uac19\uc740 \ub9d0\uc744 \uc77d\ub294\ub2e4. \ub108\ubb34 \uc775\uc219\ud574\uc11c \uc2e0\uae30\ud558\uac8c \ub290\uaef4\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \ud558\uc9c0\ub9cc \uc11c\ub85c \ub2e4\ub978 \uae30\uacc4\uac00 \uac19\uc740 \uae00\uc790\ub97c \uc54c\uc544\ubcf4\ub824\uba74 \uc5b4\ub5a4 \uc57d\uc18d\uc774 \ud544\uc694\ud560\uae4c. \ucef4\ud4e8\ud130\uac00 \uc6b0\ub9ac\uac00 \uc4f4 \ubb38\uc7a5\uc744 \uc0ac\uc9c4\uc73c\ub85c \ucc0d\uc5b4 \ubcf4\ub0b4\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc720\ub2c8\ucf54\ub4dc\ub294 \uc774\ub7f0 \ubb38\uc81c\ub97c \ub2e4\ub8e8\ub294 \uacf5\ud1b5 \ud45c\uc900\uc774\ub2e4. \ud575\uc2ec\uc740 \uc138\uacc4\uc758 \uc5ec\ub7ec \ubb38\uc790\uc5d0 \uacf5\ud1b5\uc758 \ubc88\ud638\ub97c \ubd80\uc5ec\ud558\ub294 \ub370 \uc788\ub2e4. \ubcf5\uc7a1\ud55c \uc22b\uc790\ud45c\ub97c \uc678\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uae00\uc790\uc758 \ubc88\ud638\uc640 \ud654\uba74\uc5d0 \uadf8\ub824\uc9c0\ub294 \ubaa8\uc591\uc774 \uc11c\ub85c \ub2e4\ub978 \uc77c\uc774\ub77c\ub294 \uc0ac\uc2e4\ub9cc \uc54c\uba74, \ud3c9\uc18c\uc758 \uc791\uc740 \ubd88\ud3b8\ub3c4 \uaf64 \uc798 \uc124\uba85\ub41c\ub2e4. \uc5b4\ub5a4 \uc0c1\uc790\uc758 17\ubc88 \uce78\uc5d0\ub294 \uc5f0\ud544\uc774, \ub2e4\ub978 \uc0c1\uc790\uc758 17\ubc88 \uce78\uc5d0\ub294 \uc9c0\uc6b0\uac1c\uac00 \uc788\ub2e4\uace0 \uc0dd\uac01\ud574 \ubcf4\uc790. \uc0c1\uc790 \uc774\ub984\uc744 \ube7c\uace0 17\ubc88\ub9cc \uc54c\ub824 \uc8fc\uba74 \uc5c9\ub6b1\ud55c \ubb3c\uac74\uc744 \uaebc\ub0bc \uc218 \uc788\ub2e4. \uc774\ub294 \uc774\ud574\ub97c \uc704\ud55c \ube44\uc720\uc9c0\ub9cc \uacfc\uac70\uc758 \uc5ec\ub7ec \ubb38\uc790 \ubd80\ud638 \uccb4\uacc4\uac00 \uc65c \ud63c\ub780\uc744 \uc77c\uc73c\ud0ac \uc218 \uc788\uc5c8\ub294\uc9c0 \ubcf4\uc5ec \uc900\ub2e4. \uc22b\uc790\uc640 \uae00\uc790\ub97c \uc5f0\uacb0\ud558\ub294 \ubc29\uc2dd\uc774 \ub2e4\ub974\uba74 \uac19\uc740 \ub370\uc774\ud130\ub97c \ub2e4\ub978 \ubb38\uc790\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \ubb38\uc790 \uae68\uc9d0\uc740 \uc6d0\ub798 \ubb38\uc7a5\uc5d0 \uc774\uc0c1\ud55c \uc678\uad6d\uc5b4\ub97c \uc37c\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub77c, \uc800\uc7a5\ud558\uac70\ub098 \uc804\ub2ec\ud55c \uc22b\uc790\ub97c \ud574\uc11d\ud558\ub294 \uc57d\uc18d\uc774 \uc5b4\uae0b\ub09c \uacb0\uacfc\uc77c \uc218 \uc788\ub2e4. \ubb38\uc81c\ub294 \uae00\uc758 \ub73b\ubcf4\ub2e4 \uadf8 \uc55e \ub2e8\uacc4\uc5d0 \uc788\ub294 \uc148\uc774\ub2e4. \uc720\ub2c8\ucf54\ub4dc\uc5d0\uc11c \ud55c\uae00 \uc74c\uc808 \uac00\uc5d0\ub294 U+AC00\uc774\ub77c\ub294 \ubc88\ud638\uac00 \ubd99\uc5b4 \uc788\ub2e4. \uc774 \ubc88\ud638\ub97c \ucf54\ub4dc \ud3ec\uc778\ud2b8\ub77c\uace0 \ud55c\ub2e4. \ub0af\uc120 \uae30\ud638\ucc98\ub7fc \ubcf4\uc5ec\ub3c4 \uc774 \uae00\uc790\ub97c \uac00\ub9ac\ud0a4\ub294 \ud45c\uc900 \ubc88\ud638\ub77c\ub294 \ub73b\uc774\ub2e4. \ubc88\ud638 \uc55e\uc758 U+ \ud45c\uae30\ub294 \uc720\ub2c8\ucf54\ub4dc\uc758 \uac12\uc744 \uc801\uc744 \ub54c \uc4f0\ub294 \uad00\ub840\ub2e4. \uc774 \uacf5\ud1b5 \ubc88\ud638 \ub355\ubd84\uc5d0 \ud504\ub85c\uadf8\ub7a8\uc740 \uc5b4\ub5a4 \uae00\uc790\ub97c \ub2e4\ub8e8\uace0 \uc788\ub294\uc9c0 \uac19\uc740 \uae30\uc900\uc73c\ub85c \uc774\uc57c\uae30\ud560 \uc218 \uc788\ub2e4. \ud55c\uad6d\uc5b4\uc640 \uc601\uc5b4, \ub2e4\ub978 \uc5b8\uc5b4\uc758 \ubb38\uc790\uac00 \ud55c \ubb38\uc11c \uc548\uc5d0 \uc788\uc5b4\ub3c4 \uac01 \uae00\uc790\ub97c \uacf5\ud1b5 \uccb4\uacc4\uc5d0\uc11c \uc2dd\ubcc4\ud55c\ub2e4. \uae00\uc790\ub9c8\ub2e4 \uac19\uc740 \uadf8\ub9bc \ud30c\uc77c\uc744 \uc8fc\uace0\ubc1b\ub294 \uac83\uacfc\ub294 \ub2e4\ub978 \ubc29\uc2dd\uc774\ub2e4. \ubc88\ud638\uac00 \uc815\ud574\uc84c\uc5b4\ub3c4 \uadf8\uac83\uc744 \ud30c\uc77c\uacfc \ud1b5\uc2e0\uc5d0\uc11c \uc5b4\ub5a4 \ubc14\uc774\ud2b8 \ubc30\uc5f4\ub85c \ud45c\ud604\ud560\uc9c0\ub294 \ub530\ub85c \uc815\ud574\uc57c \ud55c\ub2e4. \ubc14\uc774\ud2b8\ub294 \ucef4\ud4e8\ud130\uac00 \ub370\uc774\ud130\ub97c \uc800\uc7a5\ud558\ub294 \uc791\uc740 \ub2e8\uc704\ub2e4. UTF-8\uc774\ub098 UTF-16\uc740 \uc774 \ud45c\ud604 \ubc29\uc2dd\uc758 \uc774\ub984\uc774\ub2e4. \uc720\ub2c8\ucf54\ub4dc\ub77c\ub294 \ud45c\uc900\uacfc \uc774\ub97c \uc800\uc7a5\ud558\ub294 \ubc29\ubc95\uc744 \uad6c\ubcc4\ud558\uba74 \ub0af\uc120 \uc6a9\uc5b4\uac00 \uc870\uae08 \uc815\ub9ac\ub41c\ub2e4. UTF-8\uc5d0\uc11c\ub294 \ucf54\ub4dc \ud3ec\uc778\ud2b8\uc5d0 \ub530\ub77c \ud544\uc694\ud55c \ubc14\uc774\ud2b8 \uc218\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \ub530\ub77c\uc11c \uae00\uc790 \uc218\uac00 \uac19\ub2e4\uace0 \ud30c\uc77c\uc5d0\uc11c \ucc28\uc9c0\ud558\ub294 \ud06c\uae30\uae4c\uc9c0 \uac19\uc9c0\ub294 \uc54a\ub2e4. \ud654\uba74\uc5d0 \ub450 \uae00\uc790\uac00 \ub098\ub780\ud788 \ub193\uc774\ub294 \uc77c\uacfc \uc800\uc7a5 \uc7a5\uce58\uc5d0 \uac19\uc740 \uc591\uc758 \uacf5\uac04\uc744 \uc0ac\uc6a9\ud558\ub294 \uc77c\uc740 \uc11c\ub85c \ub2e4\ub978 \ubb38\uc81c\ub2e4. \uce5c\uad6c\uc758 \ud734\ub300\uc804\ud654\uc5d0\uc11c \ubcf8 \uae00\uc790\uac00 \ub0b4 \ud654\uba74\uc5d0\uc11c\ub294 \uc870\uae08 \ub2e4\ub974\uac8c \ubcf4\uc77c \uc218 \uc788\ub2e4. \ubc88\ud638\uac00 \uac19\uc544\ub3c4 \uae00\uaf34\uc774 \ub2e4\ub974\uba74 \ud68d\uacfc \uad75\uae30, \uade0\ud615\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uc720\ub2c8\ucf54\ub4dc\ub294 \uae00\uc790\ub97c \uc2dd\ubcc4\ud558\ub294 \uc57d\uc18d\uc774\uc9c0 \ubaa8\ub4e0 \uae30\uae30\uc5d0 \ub611\uac19\uc740 \uc11c\uccb4\ub97c \uc124\uce58\ud558\ub294 \uc81c\ub3c4\ub294 \uc544\ub2c8\ub2e4. ICU\uc758 \uacf5\uc2dd \ubb38\uc11c\ub294 \ubb38\uc790\uc640 \uae00\ub9ac\ud504\ub97c \uad6c\ubcc4\ud55c\ub2e4. \uae00\ub9ac\ud504\ub294 \uc2e4\uc81c\ub85c \uadf8\ub824\uc9c0\ub294 \ubaa8\uc591\uc744 \ub73b\ud55c\ub2e4. \uc6b0\ub9ac\uac00 \uc77d\ub294 \ucd94\uc0c1\uc801\uc778 \uae00\uc790\uc640 \uadf8 \uae00\uc790\ub97c \ud45c\ud604\ud558\ub294 \uc2dc\uac01\uc801 \ud615\ud0dc\uac00 \ubc18\ub4dc\uc2dc \uc77c\ub300\uc77c\ub85c\ub9cc \ub300\uc751\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uacf5\ud1b5 \ubc88\ud638\uc640 \ub514\uc790\uc778\uc758 \uc790\uc720\uac00 \ub3d9\uc2dc\uc5d0 \uc874\uc7ac\ud560 \uc218 \uc788\ub294 \uc774\uc720\ub2e4. \uc870\uae08 \ub354 \ud765\ubbf8\ub85c\uc6b4 \uc77c\ub3c4 \uc788\ub2e4. \uac00\ub97c \uc644\uc131\ub41c \ud55c \uc74c\uc808\uc758 \ubc88\ud638\ub85c \ub098\ud0c0\ub0bc \uc218\ub3c4 \uc788\uace0, \uc870\ud569\uc6a9 \ucd08\uc131 \u1100\uacfc \uc911\uc131 \u1161\ub97c \uc774\uc5b4 \ub098\ud0c0\ub0bc \uc218\ub3c4 \uc788\ub2e4. \ud654\uba74\uc5d0\uc11c\ub294 \ube44\uc2b7\ud558\uac8c \uc77d\ud788\uc9c0\ub9cc \ub0b4\ubd80\uc758 \ucf54\ub4dc \ud3ec\uc778\ud2b8 \ubc30\uc5f4\uc740 \ub2e4\ub974\ub2e4. \uc774\uac83\uc774 \ud55c\uae00\uc774 \uc798\ubabb\ub418\uc5c8\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc774\ucc98\ub7fc \ud45c\uc900\uc774 \ub3d9\ub4f1\ud55c \uac83\uc73c\ub85c \ub2e4\ub8e8\ub294 \ud45c\ud604\uc744 \uc77c\uc815\ud55c \ud615\uc2dd\uc73c\ub85c \ub9de\ucd94\ub294 \uc791\uc5c5\uc744 \uc815\uaddc\ud654\ub77c\uace0 \ud55c\ub2e4. \uac00\uc758 \uacbd\uc6b0 \uc870\ud569\ub41c \ud615\ud0dc\uc640 \ubd84\ud574\ub41c \ud615\ud0dc \uc0ac\uc774\ub97c \uc815\ub9ac\ud560 \uc218 \uc788\ub2e4. \uc774\ub984\uc740 \uc5b4\ub835\uc9c0\ub9cc \uc11c\ub85c \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \uc801\ud78c \uac19\uc740 \uae00\uc790\ub97c \ube44\uad50\ud558\uae30 \uc88b\uac8c \ub9de\ucd94\ub294 \uacfc\uc815\uc73c\ub85c \uc774\ud574\ud558\uba74 \ub41c\ub2e4. \ud30c\uc77c \uc774\ub984\uc744 \ubcf5\uc0ac\ud588\ub294\ub370 \uac80\uc0c9\uc774 \uae30\ub300\ub300\ub85c \ub418\uc9c0 \uc54a\ub294 \uc0c1\ud669\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc6d0\uc778\uc774 \uc5b8\uc81c\ub098 \uc815\uaddc\ud654\uc5d0 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\uc9c0\ub9cc, \ub208\uc5d0 \ube44\uc2b7\ud558\uac8c \ubcf4\uc774\ub294 \ubb38\uc790\uc5f4\uc758 \ub0b4\ubd80 \ubc30\uc5f4\uc774 \ub2e4\ub974\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ud504\ub85c\uadf8\ub7a8\uc774 \uace0\ub824\ud574\uc57c \ud560 \ubb38\uc81c\ub2e4. \uc0ac\ub78c\uc758 \ub208\uc73c\ub85c \uac19\uc740 \uae00\uc790\ub77c\uace0 \ub290\ub07c\ub294 \uac83\ub9cc\uc73c\ub85c \ube44\uad50\uac00 \ub05d\ub098\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \ubc18\ub300\ub85c \ubaa8\uc591\uc774 \ube44\uc2b7\ud55c \ubaa8\ub4e0 \ubb38\uc790\ub97c \uac19\uc740 \uac83\uc73c\ub85c \ubc14\uafb8\uc5b4\uc11c\ub294 \uc548 \ub41c\ub2e4. \ub2e4\ub978 \uc5b8\uc5b4\uc758 \uae00\uc790\ub098 \ub2e4\ub978 \uc758\ubbf8\uc758 \uae30\ud638\ub3c4 \ub2ee\uac8c \ubcf4\uc77c \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uc815\uaddc\ud654\ub294 \uc0ac\ub78c \ub9c8\uc74c\ub300\ub85c \ub2ee\uc740 \uae00\uc790\ub97c \ud55c\ub370 \ubb36\ub294 \uc77c\uc774 \uc544\ub2c8\ub77c \ud45c\uc900\uc5d0\uc11c \uc815\ud55c \uad00\uacc4\ub97c \ub530\ub77c\uc57c \ud55c\ub2e4. \uad6c\ubd84\ud574\uc57c \ud560 \ucc28\uc774\uc640 \ub9de\ucd94\uc5b4\ub3c4 \ub418\ub294 \ucc28\uc774\ub97c \ub098\ub204\ub294 \uc148\uc774\ub2e4. \ubb38\uc11c\uc758 \uc77c\ubd80\uac00 \ube48 \ub124\ubaa8\ub85c \ub098\ud0c0\ub098\ub294 \uacbd\uc6b0\ub3c4 \uc788\ub2e4. \uae00\uc790\uc758 \uc815\ubcf4\uac00 \uc804\ud600 \uc5c6\uc5b4\uc11c\uc77c \uc218\ub3c4 \uc788\uc9c0\ub9cc, \uae00\uaf34\uc5d0 \ud544\uc694\ud55c \ubaa8\uc591\uc774 \uc5c6\uc5b4 \ud45c\uc2dc\ud558\uc9c0 \ubabb\ud558\ub294 \uacbd\uc6b0\ub3c4 \uc788\ub2e4. \uc5b4\ub5a4 \uae00\uc790\uc778\uc9c0 \uc544\ub294 \uc77c\uacfc \uadf8 \uae00\uc790\ub97c \ud654\uba74\uc5d0 \uadf8\ub9b4 \uc218 \uc788\ub294 \uc77c\uc740 \ubcc4\uac1c\ub2e4. \uc774 \ucc28\uc774\ub97c \uc54c\uba74 \uae00\uc790\uac00 \uc774\uc0c1\ud558\ub2e4\ub294 \ud55c\ub9c8\ub514 \ub4a4\uc5d0\ub3c4 \uc5ec\ub7ec \uc6d0\uc778\uc774 \uc788\uc74c\uc744 \uc774\ud574\ud558\uac8c \ub41c\ub2e4. \ubc88\ud638\ub97c \uc77d\ub294 \ubc29\uc2dd, \ubb38\uc790\uc758 \ubc30\uc5f4, \uae00\uaf34\uc758 \uc900\ube44\uac00 \uac01\uac01 \uad00\uc5ec\ud55c\ub2e4. \uc0ac\uc6a9\uc790\uac00 \ub9e4\ubc88 \uc774\ub97c \uace0\uce60 \uc804\ubb38\uac00\uac00 \ub420 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \uacf5\ud1b5 \ud45c\uc900 \ud558\ub098\uac00 \ud654\uba74\uc758 \ubaa8\ub4e0 \ubb38\uc81c\ub97c \uc790\ub3d9\uc73c\ub85c \uc5c6\uc560 \uc8fc\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc815\ub3c4\uba74 \ucda9\ubd84\ud558\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\uc740 \ub2e4\ub978 \uae30\uae30\ub97c \uc0ac\uc6a9\ud558\ub294 \uc0ac\ub78c\ub4e4\uc774 \ub9c8\uc8fc \uc549\uc740 AI \ubd84\uc704\uae30 \uc0bd\ud654\ub2e4. \uc2e4\uc81c \ubb38\uc790\ud45c\ub098 \uae00\uc790 \ucc98\ub9ac \uacfc\uc815\uc744 \uc124\uba85\ud558\ub294 \ub3c4\uc2dd\uc740 \uc544\ub2c8\ub2e4. \uc720\ub2c8\ucf54\ub4dc\uc758 \ubc88\ud638\ub294 \ubcf4\uc774\uc9c0 \uc54a\uc544\ub3c4, \uc11c\ub85c \ub2e4\ub978 \ud658\uacbd\uc5d0\uc11c \ub9d0\uc744 \ub098\ub204\ub294 \uc77c\uc758 \ubc30\uacbd\uc5d0 \uc788\ub2e4. \ub2e4\uc74c\uc5d0 \ud55c\uae00\ub85c \uc778\uc0ac\ub97c \ubcf4\ub0bc \ub54c \uacf5\ud1b5 \ubc88\ud638\ub97c \ub5a0\uc62c\ub9b4 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc624\ud788\ub824 \uc758\uc2dd\ud558\uc9c0 \uc54a\uace0 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4\ub294 \uac83\uc774 \uc774\ub7f0 \uc57d\uc18d\uc758 \uc131\uacfc\ub2e4. \uc6b0\ub9ac\uac00 \uc77d\uace0 \uc2f6\uc740 \uac83\uc740 \ubb38\uc7a5\uc774\uace0, \ud45c\uc900\uc774 \ud558\ub294 \uc77c\uc740 \uadf8 \ubb38\uc7a5\uc774 \ub2e4\ub978 \uae30\uacc4\uc5d0\uc11c\ub3c4 \uac19\uc740 \uae00\uc790\ub85c \ub9cc\ub0a0 \uc218 \uc788\ub3c4\ub85d \uae38\uc744 \ub9de\ucd94\ub294 \uac83\uc774\ub2e4."}, {"id": "web-links-shared-knowledge", "title": "\uc6f9\uc758 \uc2dc\uc791 \u2014 \ub17c\ubb38\uc5d0\uc11c \ub2e4\ub978 \ub17c\ubb38\uc73c\ub85c \uac74\ub108\uac00\uace0 \uc2f6\uc5c8\ub2e4", "summary": "\ud300 \ubc84\ub108\uc2a4\ub9ac\uc758 \uc81c\uc548\uc5d0\uc11c \uc2dc\uc791\ud574 \uc6f9\uacfc \uc778\ud130\ub137\uc758 \ucc28\uc774, \ub9c1\ud06c\uc640 \uc5f4\ub9b0 \ud45c\uc900\uc758 \uc758\ubbf8\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "computing", "category_title": "Computing", "subcategory": "Internet", "url": "stories/web-links-shared-knowledge/index.html", "image": "media/web-links-shared-knowledge.png", "alt": "\ucd08\uae30 \uac1c\uc778\uc6a9 \ucef4\ud4e8\ud130\uc640 \uc5ec\ub7ec \ubb38\uc11c\uac00 \ub193\uc778 \uc5f0\uad6c\uc2e4\uc5d0\uc11c \ud30c\ub780 \ub9ac\ubcf8\uc774 \uc790\ub8cc\ub97c \uc787\ub294 \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\uc6f9\uc758 \uc2dc\uc791 \u2014 \ub17c\ubb38\uc5d0\uc11c \ub2e4\ub978 \ub17c\ubb38\uc73c\ub85c \uac74\ub108\uac00\uace0 \uc2f6\uc5c8\ub2e4 \uc8fc\uc18c\uc640 \ub9c1\ud06c\uac00 \ub9cc\ub4e0 \uc0c8\ub85c\uc6b4 \uc77d\uae30 \ubc29\uc2dd \ud300 \ubc84\ub108\uc2a4\ub9ac\uc758 \uc81c\uc548\uc5d0\uc11c \uc2dc\uc791\ud574 \uc6f9\uacfc \uc778\ud130\ub137\uc758 \ucc28\uc774, \ub9c1\ud06c\uc640 \uc5f4\ub9b0 \ud45c\uc900\uc758 \uc758\ubbf8\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Internet \ucef4\ud4e8\ud305 \ud55c \ubb38\uc11c\ub97c \uc77d\ub2e4\uac00 \uac70\uae30\uc5d0 \ub098\uc624\ub294 \ub2e4\ub978 \uc790\ub8cc\ub97c \ucc3e\uc544\uc57c \ud55c\ub2e4. \ucc45\uc774\ub77c\uba74 \uc11c\uac00\ub85c \uac00\uace0, \ubcf5\uc0ac\ubb3c\uc774\ub77c\uba74 \uc11c\ub958\ucca0\uc744 \ub4a4\uc9c4\ub2e4. \uc9c0\uae08\uc740 \ubb38\uc7a5 \uc548\uc758 \ub9c1\ud06c\ub97c \ub204\ub974\uba74 \ub418\uc9c0\ub9cc, \uc774 \ub2f9\uc5f0\ud55c \uc6c0\uc9c1\uc784\ub3c4 \ub204\uad70\uac00\uac00 \ub9cc\ub4e4\uc5b4 \ub193\uc740 \uae38\uc774\ub2e4. \uc6f9\uc758 \uc774\uc57c\uae30\ub97c \uac70\ub300\ud55c \uae30\uc220 \ud601\uba85\ubcf4\ub2e4 \uc77d\ub294 \uc0ac\ub78c\uc758 \uc791\uc740 \ubd88\ud3b8\uc5d0\uc11c \uc2dc\uc791\ud574 \ubcf4\uc790. \uc6f9\uc740 \uc815\ubcf4\ub97c \ud55c\uacf3\uc5d0 \ubaa8\uc544 \ub450\ub294 \uac83\uc5d0 \uadf8\uce58\uc9c0 \uc54a\uace0 \uc11c\ub85c \ub2e4\ub978 \ubb38\uc11c\ub97c \uc774\uc5b4 \uc77d\uc744 \uc218 \uc788\uac8c \ud588\ub2e4. \ucef4\ud4e8\ud130 \uc0ac\uc774\uc5d0 \uc790\ub8cc\uac00 \uc624\uac08 \uc218 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uacfc, \ud3c9\ubc94\ud55c \ub3c5\uc790\uac00 \uadf8 \uc790\ub8cc\ub97c \ucc3e\uc544 \uc77d\uae30 \uc27d\ub2e4\ub294 \uc0ac\uc2e4 \uc0ac\uc774\uc5d0\ub294 \uc0dd\uac01\ubcf4\ub2e4 \uae34 \uac70\ub9ac\uac00 \uc788\uc5c8\ub2e4. 1989\ub144 CERN\uc5d0\uc11c \uc77c\ud558\ub358 \ud300 \ubc84\ub108\uc2a4\ub9ac\ub294 \uc815\ubcf4 \uad00\ub9ac\uc5d0 \uad00\ud55c \uc81c\uc548\uc744 \uc791\uc131\ud588\ub2e4. \uc5ec\ub7ec \uc790\ub8cc\uc640 \uad00\uacc4\ub97c \ud558\uc774\ud37c\ud14d\uc2a4\ud2b8\ub85c \uc5f0\uacb0\ud558\ub294 \uad6c\uc0c1\uc774 \uc6f9\uc758 \ubc30\uacbd\uc774 \ub418\uc5c8\ub2e4. \ud558\uc774\ud37c\ud14d\uc2a4\ud2b8\ub77c\ub294 \ub9d0\uc774 \ub0af\uc124\ub2e4\uba74, \uc77d\ub358 \uacf3\uc5d0\uc11c \uad00\ub828\ub41c \ub2e4\ub978 \uacf3\uc73c\ub85c \uac74\ub108\uac08 \uc218 \uc788\ub294 \ubb38\uc11c\ub77c\uace0 \uc0dd\uac01\ud558\uba74 \ub41c\ub2e4. \ucc45\uc758 \uac01\uc8fc\ub294 \ub2e4\ub978 \uae00\uc744 \uac00\ub9ac\ud0a4\uc9c0\ub9cc \ub3c5\uc790\uac00 \uc9c1\uc811 \uadf8 \uae00\uc744 \ucc3e\uc544\uc57c \ud55c\ub2e4. \ub9c1\ud06c\ub294 \uadf8 \uc774\ub3d9\uc744 \ubb38\uc11c\uc758 \uae30\ub2a5\uc73c\ub85c \ub9cc\ub4e0\ub2e4. \ud55c \ud398\uc774\uc9c0\uc758 \uc800\uc790\uac00 \uc138\uacc4\uc758 \ubaa8\ub4e0 \uc815\ubcf4\ub97c \ub2f4\uc9c0 \uc54a\uc544\ub3c4 \ub2e4\ub978 \ud398\uc774\uc9c0\ub97c \uac00\ub9ac\ud0ac \uc218 \uc788\ub2e4. \ubb38\uc11c\ub294 \uc644\uacb0\ub41c \ud55c \uad8c\uc778 \ub3d9\uc2dc\uc5d0 \ub354 \ud070 \ub3c5\uc11c\uc758 \uc785\uad6c\uac00 \ub41c\ub2e4. \uc5f0\uacb0\ud558\uace0 \uc2f6\uc740 \ub9c8\uc74c\uc774 \uc788\uc5b4\ub3c4 \ubb38\uc11c\ub97c \uc8fc\uace0\ubc1b\uc744 \uacf5\ud1b5 \ubc29\ubc95\uc774 \uc5c6\uc73c\uba74 \ub2e4\ub978 \ucef4\ud4e8\ud130\uc5d0\uc11c\ub294 \uc77d\uae30 \uc5b4\ub835\ub2e4. \uc790\ub8cc\uc758 \uc704\uce58\ub97c \uac00\ub9ac\ud0a4\ub294 \uc8fc\uc18c, \ubb38\uc11c\uc758 \uad6c\uc870\ub97c \ud45c\ud604\ud558\ub294 \ubc29\uc2dd, \uadf8 \ubb38\uc11c\ub97c \uc694\uccad\ud558\uace0 \ubc1b\ub294 \uc57d\uc18d\uc774 \ud568\uaed8 \ud544\uc694\ud588\ub2e4. 1990~1991\ub144 \ubb34\ub835 \ubc84\ub108\uc2a4\ub9ac\ub294 \ucd08\uae30 \uc6f9\uc744 \uc774\ub8e8\ub294 HTML\uacfc HTTP, \ube0c\ub77c\uc6b0\uc800\uc640 \uc11c\ubc84, \uc6f9 \ud398\uc774\uc9c0\ub97c \ub9c8\ub828\ud588\ub2e4. \uc6a9\uc5b4\ub97c \uc678\uc6b0\uae30\ubcf4\ub2e4 \uc5ed\ud560\uc744 \ub098\ub204\uc5b4 \ubcf4\uc790. \ubb38\uc11c\uac00 \uc788\uace0, \uadf8\uac83\uc744 \ubcf4\ub0b4\ub294 \ucabd\uc774 \uc788\uc73c\uba70, \ubc1b\uc544\uc11c \ubcf4\uc5ec \uc8fc\ub294 \ucabd\uc774 \uc788\ub2e4. \uadf8 \uc0ac\uc774\uac00 \uac19\uc740 \uc57d\uc18d\uc73c\ub85c \uc774\uc5b4\uc9c8 \ub54c \ub9c1\ud06c\uac00 \uc2e4\uc81c \uae38\uc774 \ub41c\ub2e4. \uc778\ud130\ub137\uc740 \uc5ec\ub7ec \ucef4\ud4e8\ud130\uc640 \ub124\ud2b8\uc6cc\ud06c\uac00 \uc815\ubcf4\ub97c \uc8fc\uace0\ubc1b\uc744 \uc218 \uc788\uac8c \ud558\ub294 \uae30\ubc18\uc774\ub2e4. \uc6f9\uc740 \uadf8 \uae30\ubc18 \uc704\uc5d0\uc11c \ubb38\uc11c\uc640 \uc5ec\ub7ec \ucf58\ud150\uce20\ub97c \uc8fc\uc18c\ub85c \ucc3e\uace0 \uc5f0\uacb0\ud574 \uc774\uc6a9\ud558\ub294 \ubc29\uc2dd\uc774\ub2e4. \uc6f9\uc774 \uc0dd\uacbc\uae30 \ub54c\ubb38\uc5d0 \uc778\ud130\ub137 \uc790\uccb4\uac00 \ucc98\uc74c \uc0dd\uae34 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc804\uc790\uc6b0\ud3b8\uc744 \ub5a0\uc62c\ub9ac\uba74 \ucc28\uc774\uac00 \uc870\uae08 \uc26c\uc6cc\uc9c4\ub2e4. \uc6f9 \ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c \uba54\uc77c\uc744 \ubcfc \uc218\ub3c4 \uc788\uc9c0\ub9cc \uc804\uc790\uc6b0\ud3b8\uacfc \uc6f9\uc774 \uc6d0\ub798 \uac19\uc740 \uae30\uc220\uc778 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud558\ub098\uc758 \uae38 \uc704\uc5d0 \uc5ec\ub7ec \uc885\ub958\uc758 \uc11c\ube44\uc2a4\uac00 \ub193\uc77c \uc218 \uc788\ub2e4. \uc778\ud130\ub137\uc744 \uae38\uc5d0 \ube44\uc720\ud55c\ub2e4\uba74 \uc6f9\uc740 \uadf8 \uae38\uc744 \uc0ac\uc6a9\ud558\ub294 \uc911\uc694\ud55c \ud65c\ub3d9 \ud558\ub098\ub77c\uace0 \ud560 \uc218 \uc788\ub2e4. \ube0c\ub77c\uc6b0\uc800\ub294 \uba40\ub9ac \uc788\ub294 \uc790\ub8cc\ub97c \uc694\uccad\ud558\uace0 \ud654\uba74\uc5d0 \ubcf4\uc5ec \uc8fc\ub294 \ucc3d\uc774\ub2e4. \ub3c5\uc790\uac00 \ubb38\uc11c\ub97c \ub9cc\ub4e0 \uc0ac\ub78c\uacfc \uac19\uc740 \ucef4\ud4e8\ud130\ub97c \uc4f0\uac70\ub098 \uac19\uc740 \ubc29\uc5d0 \uc788\uc744 \ud544\uc694\uac00 \uc904\uc5b4\ub4e0\ub2e4. \uc8fc\uc18c\ub97c \uc54c\uac70\ub098 \ub2e4\ub978 \ud398\uc774\uc9c0\uc758 \ub9c1\ud06c\ub97c \ub530\ub77c\uac00\uba74 \uc0c8\ub85c\uc6b4 \uc77d\uc744\uac70\ub9ac\uc5d0 \ub3c4\ucc29\ud560 \uc218 \uc788\ub2e4. \ucd08\uae30\uc758 \uc6f9\uc744 \uc624\ub298\ub0a0\uc758 \ubcf5\uc7a1\ud55c \ud654\uba74\uacfc \ub611\uac19\uc774 \uc0c1\uc0c1\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc911\uc694\ud55c \ubcc0\ud654\ub294 \ud654\ub824\ud55c \uc0c9\uc774\ub098 \uc601\uc0c1\ubcf4\ub2e4 \uc11c\ub85c \ub2e4\ub978 \ubb38\uc11c\ub97c \ud55c \ud750\ub984 \uc18d\uc5d0\uc11c \ub9cc\ub0a0 \uc218 \uc788\ub2e4\ub294 \ub370 \uc788\uc5c8\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc18c\ubc15\ud55c \ud654\uba74\uc774\uc5b4\ub3c4 \uadf8 \ud654\uba74 \ubc16\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \uae38\uc740 \ub9e4\uc6b0 \ub113\uc5b4\uc9c8 \uc218 \uc788\uc5c8\ub2e4. \uc6f9\uc744 \ud55c \ud68c\uc0ac\uc758 \uc81c\ud488 \uc548\uc5d0\uc11c\ub9cc \uc77d\uc744 \uc218 \uc788\ub2e4\uba74 \uc5f0\uacb0\uc758 \ubc94\uc704\ub3c4 \uadf8 \uc81c\ud488\uc758 \uacbd\uacc4\uc5d0 \ubb36\uc778\ub2e4. \uc5ec\ub7ec \ube0c\ub77c\uc6b0\uc800\uac00 \ubb38\uc11c\ub97c \ube44\uc2b7\ud55c \ub73b\uc73c\ub85c \ubc1b\uc544\ub4e4\uc774\ub824\uba74 \uacf5\uac1c\ub41c \uacf5\ud1b5 \uaddc\uce59\uc774 \uc911\uc694\ud574\uc9c4\ub2e4. \uc6f9 \ud45c\uc900\uc740 \uc774\ub7f0 \uc57d\uc18d\uc744 \ub2e4\ub8e8\ub294 \ud2c0\uc774\ub2e4. 1994\ub144 \ubc84\ub108\uc2a4\ub9ac\ub294 W3C\ub97c \uc124\ub9bd\ud588\ub2e4. \uc5ec\ub7ec \uc870\uc9c1\uc774 \uc6f9 \uae30\uc220\uc758 \uacf5\ud1b5 \uae30\uc900\uc744 \ub17c\uc758\ud558\ub294 \uacf5\uac04\uc774\ub2e4. \uc6f9\uc758 \ubc1c\uc804\uc744 \ud55c \uc0ac\ub78c\uc774 \uacc4\uc18d \ud63c\uc790 \ub9cc\ub4e4\uc5b4 \ub0b8 \uacb0\uacfc\ub85c \uc124\uba85\ud574\uc11c\ub294 \uace4\ub780\ud558\ub2e4. \uc2dc\uc791\uc758 \uc81c\uc548\uacfc \uad6c\ud604 \ub4a4\uc5d0\ub294 \uc5ec\ub7ec \uae30\uad00\uacfc \uac1c\ubc1c\uc790\uac00 \ud569\uc758\ud558\uace0 \uad6c\ud604\ud558\uba70 \uace0\uce58\ub294 \uae34 \uacfc\uc815\uc774 \uc774\uc5b4\uc84c\ub2e4. \uc6b0\ub9ac\ub294 \uac80\uc0c9\ucc3d\uc744 \uc6f9\uc758 \uc785\uad6c\ucc98\ub7fc \ub290\ub07c\uc9c0\ub9cc \uc6f9 \uc804\uccb4\uac00 \ud558\ub098\uc758 \uac80\uc0c9 \uc11c\ube44\uc2a4 \uc548\uc5d0 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uac80\uc0c9\uc740 \uc5ec\ub7ec \ud398\uc774\uc9c0\ub97c \ucc3e\ub3c4\ub85d \ub3d5\ub294 \ubc29\ubc95\uc774\uace0, \ub9c1\ud06c\ub294 \ud398\uc774\uc9c0\uc5d0\uc11c \ub2e4\ub978 \uc8fc\uc18c\ub97c \uac00\ub9ac\ud0a4\ub294 \uae30\ub2a5\uc774\ub2e4. \ub204\uad70\uac00\uc758 \ucd94\ucc9c \uae00\uc774\ub098 \uae30\uad00\uc758 \uc548\ub0b4 \ubaa9\ub85d\uc744 \ub530\ub77c\uac00\ub294 \uac83\ub3c4 \uc6f9\uc744 \uc77d\ub294 \ubc29\uc2dd\uc774\ub2e4. \uadf8\ub798\uc11c \ud55c \ud398\uc774\uc9c0\ub97c \uc798 \ub9cc\ub4dc\ub294 \uc77c\uc5d0\ub294 \ub0b4\uc6a9\ubfd0 \uc544\ub2c8\ub77c \uc5b4\ub514\ub85c \ub3c5\uc790\ub97c \ubcf4\ub0b4 \uc904\uc9c0\ub3c4 \ud3ec\ud568\ub41c\ub2e4. \uadfc\uac70\uc790\ub8cc\uc758 \uc6d0\ubb38, \ub354 \uc790\uc138\ud55c \uc124\uba85, \ub2e4\uc74c \uc774\uc57c\uae30\ub85c \uc774\uc5b4\uc9c0\ub294 \uc8fc\uc18c\ub97c \ub193\uc73c\uba74 \ub3c5\uc790\ub294 \uc800\uc790\uc758 \uc694\uc57d \ubc16\uc73c\ub85c \ub098\uac00 \uc9c1\uc811 \ud655\uc778\ud560 \uc218 \uc788\ub2e4. \uc5f0\uacb0\uc740 \ud3b8\ub9ac\ud568\uacfc \ud568\uaed8 \uac80\uc99d\uc758 \uae30\ud68c\ub3c4 \ub9cc\ub4e0\ub2e4. \ub9c1\ud06c\ub294 \ubb38\uc11c\ub97c \uc774\uc5b4 \uc8fc\uc9c0\ub9cc \uadf8 \ubb38\uc11c\uc758 \uc815\ud655\uc131\uc744 \uc790\ub3d9\uc73c\ub85c \ubcf4\uc99d\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc5c9\ub6b1\ud55c \uc790\ub8cc\ub97c \uc5f0\uacb0\ud558\uac70\ub098 \uc624\ub798\ub41c \uc8fc\uc18c\uac00 \uc0ac\ub77c\uc9c8 \uc218\ub3c4 \uc788\ub2e4. \ub3c5\uc790\ub294 \ub204\uac00 \uc4f4 \uae00\uc778\uc9c0, \uc5b8\uc81c \ub9cc\ub4e4\uc5b4\uc84c\ub294\uc9c0, \uc5f0\uacb0\ud55c \uc790\ub8cc\uac00 \uc2e4\uc81c \uc8fc\uc7a5\uc744 \ub4b7\ubc1b\uce68\ud558\ub294\uc9c0 \uc5ec\uc804\ud788 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc5f4\ub9b0 \uae38\uc774 \ub9ce\uc544\uc9c8\uc218\ub85d \uc88b\uc740 \uc548\ub0b4\uc758 \uac00\uce58\ub3c4 \ucee4\uc9c4\ub2e4. \uc790\ub8cc\ub97c \ub9ce\uc774 \uc5f0\uacb0\ud558\ub294 \uac83\ubcf4\ub2e4 \uc801\uc808\ud55c \uacf3\uc73c\ub85c \uc5f0\uacb0\ud558\ub294 \uc77c\uc774 \uc911\uc694\ud558\ub2e4. \uae30\uc220\uc774 \ubb38\uc11c \uc0ac\uc774\uc758 \uac70\ub9ac\ub97c \uc904\uc600\ub2e4\uace0 \ud574\uc11c \ud3b8\uc9d1\uc790\uc758 \ud310\ub2e8\uc774 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ud788\ub824 \ub3c5\uc790\uac00 \ubbff\uace0 \ub530\ub77c\uac08 \uc218 \uc788\ub294 \uae38\uc744 \uace0\ub974\ub294 \uc77c\uc774 \ub0a8\ub294\ub2e4. \uc774 \uae00\uc744 \uc77d\ub2e4\uac00 \uadfc\uac70\uc790\ub8cc\ub97c \ub204\ub974\uba74 \ub2e4\ub978 \uae30\uad00\uacfc \ub2e4\ub978 \uc791\uc131\uc790\uc758 \ubb38\uc11c\ub85c \uc774\ub3d9\ud55c\ub2e4. \ub108\ubb34 \uc790\uc5f0\uc2a4\ub7ec\uc6cc\uc11c \uc78a\uae30 \uc27d\uc9c0\ub9cc, \uc774\uac83\uc740 \uc8fc\uc18c\uc640 \uc804\uc1a1 \uaddc\uce59, \ubb38\uc11c \ud615\uc2dd\uacfc \ube0c\ub77c\uc6b0\uc800\uac00 \ud568\uaed8 \uc791\ub3d9\ud55c \uacb0\uacfc\ub2e4. \uc791\uc740 \ud074\ub9ad \ud558\ub098\uc5d0 \uc5ec\ub7ec \uc0ac\ub78c\uc758 \uc624\ub79c \ud569\uc758\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc5f0\uad6c\uc2e4 \uadf8\ub9bc\uc740 \ub2f9\uc2dc\uc758 \ubd84\uc704\uae30\ub97c \ub5a0\uc62c\ub9ac\uae30 \uc704\ud55c AI \uc0bd\ud654\ub2e4. \uc2e4\uc81c \uc5f0\uad6c\uc790\uc758 \ubc29\uc774\ub098 \ucd5c\ucd08 \uc6f9 \ud654\uba74\uc744 \ubcf5\uc6d0\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uc6f9\uc758 \ud0c4\uc0dd\uc5d0\uc11c \uae30\uc5b5\ud560 \uac83\uc740 \uadf8\ub9bc \uc18d \uae30\uacc4\uc758 \uc0dd\uae40\uc0c8\ubcf4\ub2e4, \uc9c0\uc2dd\uc744 \uc11c\ub85c \uac00\ub9ac\ud0a4\uac8c \ud558\uc5ec \uc77d\ub294 \uae38\uc744 \ub113\ud614\ub2e4\ub294 \uc0dd\uac01\uc774\ub2e4."}, {"id": "wifi-connected-without-internet", "title": "\uc640\uc774\ud30c\uc774 \u2014 \uc5f0\uacb0\ub410\ub294\ub370 \uc778\ud130\ub137\uc774 \uc548 \ub418\ub294 \uae4c\ub2ed", "summary": "\uae30\uae30\uc640 \uac00\uae4c\uc6b4 \ub124\ud2b8\uc6cc\ud06c, \uc778\ud130\ub137\uacfc \uc6f9\uc744 \ub098\ub204\uc5b4 \ubcf4\uba70 \uc640\uc774\ud30c\uc774 \uc5f0\uacb0\uc758 \uc758\ubbf8\ub97c \uc774\ud574\ud569\ub2c8\ub2e4.", "category": "computing", "category_title": "Computing", "subcategory": "Internet", "url": "stories/wifi-connected-without-internet/index.html", "image": "media/wifi-connected-without-internet.png", "alt": "\ub178\ud2b8\ubd81\uacfc \uc791\uc740 \ubb34\uc120 \uc7a5\uce58\uac00 \uc788\ub294 \uc9d1 \uc548\uc5d0\uc11c \uc5f0\uacb0\uc744 \uc0dd\uac01\ud558\ub294 \uc0ac\ub78c\uc758 \uc0bd\ud654.", "text": "\uc640\uc774\ud30c\uc774 \u2014 \uc5f0\uacb0\ub410\ub294\ub370 \uc778\ud130\ub137\uc774 \uc548 \ub418\ub294 \uae4c\ub2ed \uc9d1 \uc548\uc758 \uae38\uacfc \ubc14\uae65\uc73c\ub85c \ub098\uac00\ub294 \uae38\uc740 \ub2e4\ub974\ub2e4 \uae30\uae30\uc640 \uac00\uae4c\uc6b4 \ub124\ud2b8\uc6cc\ud06c, \uc778\ud130\ub137\uacfc \uc6f9\uc744 \ub098\ub204\uc5b4 \ubcf4\uba70 \uc640\uc774\ud30c\uc774 \uc5f0\uacb0\uc758 \uc758\ubbf8\ub97c \uc774\ud574\ud569\ub2c8\ub2e4. Internet \ucef4\ud4e8\ud305 \ud734\ub300\uc804\ud654\uc5d0\ub294 \uc640\uc774\ud30c\uc774\uac00 \uc5f0\uacb0\ub418\uc5c8\ub2e4\uace0 \ub098\uc628\ub2e4. \uadf8\ub7f0\ub370 \uc6f9\ud398\uc774\uc9c0\ub294 \uc5f4\ub9ac\uc9c0 \uc54a\ub294\ub2e4. \uc5f0\uacb0\ub418\uc5c8\ub2e4\ub294 \ub9d0\uc774 \ud2c0\ub9b0 \uac83\uc77c\uae4c. \uc774 \uc0c1\ud669\uc740 \uae30\uc220\uc774 \ub9d0\uc7a5\ub09c\uc744 \ud574\uc11c\uac00 \uc544\ub2c8\ub77c \uc6b0\ub9ac\uac00 \uc11c\ub85c \ub2e4\ub978 \uc5f0\uacb0\uc744 \ud55c \ub2e8\uc5b4\ub85c \ubd80\ub974\uae30 \ub54c\ubb38\uc5d0 \ud5f7\uac08\ub9b4 \uc218 \uc788\ub2e4. \uc640\uc774\ud30c\uc774\ub85c \uc8fc\ubcc0\uc758 \ub124\ud2b8\uc6cc\ud06c\uc5d0 \ucc38\uc5ec\ud558\ub294 \uc77c\uacfc \uc778\ud130\ub137 \ub108\uba38\uc758 \uc0ac\uc774\ud2b8\uc5d0 \ub2ff\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \uc9d1 \uc548 \ubcf5\ub3c4\uc5d0 \ub098\uc654\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ubc16\uc73c\ub85c \ub098\uac00\ub294 \ubb38\uc774 \uc5f4\ub838\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ub098\ub204\uc5b4 \uc0dd\uac01\ud558\uba74 \uc870\uae08 \uc27d\ub2e4. \uc2e4\uc81c \ub124\ud2b8\uc6cc\ud06c\ub97c \ubcf5\ub3c4\uc640 \ub611\uac19\ub2e4\uace0 \ubcf4\ub294 \uac83\uc740 \uc544\ub2c8\uace0 \uc5f0\uacb0\uc758 \ub2e8\uacc4\ub97c \ub5a0\uc62c\ub9ac\ub294 \ube44\uc720\ub2e4. \ub450 \ucef4\ud4e8\ud130\uac00 \uc815\ubcf4\ub97c \uc8fc\uace0\ubc1b\uc73c\ub824\uba74 \uc5f0\uacb0\uc774 \ud544\uc694\ud558\ub2e4. \ucf00\uc774\ube14\uc744 \uc4f0\ub294 \ubc29\ubc95\ub3c4 \uc788\uace0 \uc640\uc774\ud30c\uc774 \uac19\uc740 \ubb34\uc120 \ubc29\uc2dd\uc744 \uc4f0\ub294 \ubc29\ubc95\ub3c4 \uc788\ub2e4. \uc640\uc774\ud30c\uc774\ub294 \uc774\ub807\uac8c \uae30\uae30\ub4e4\uc744 \ub124\ud2b8\uc6cc\ud06c\uc5d0 \uc5f0\uacb0\ud558\ub294 \ubc29\ubc95 \uac00\uc6b4\ub370 \ud558\ub098\ub2e4. \uc774\ub984\uc774 \uc775\uc219\ud558\ub2e4\uace0 \uc778\ud130\ub137 \uc804\uccb4\uc640 \uac19\uc740 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uac00\uae4c\uc6b4 \ub124\ud2b8\uc6cc\ud06c \uc548\uc5d0\uc11c \ud1b5\uc2e0\ud560 \uc218 \uc788\ub294 \uc0c1\ud0dc\uc640 \ub2e4\ub978 \uc9c0\uc5ed\uc758 \ub9dd\uae4c\uc9c0 \uc774\uc5b4\uc9c4 \uc0c1\ud0dc\ub294 \uad6c\ubd84\ub41c\ub2e4. \uac19\uc740 \uce74\ud398\uc5d0 \uc788\ub294 \uae30\uae30\uac00 \uadf8\uacf3\uc758 \ubb34\uc120 \uc811\uc18d \uc7a5\uce58\uc5d0 \uc5f0\uacb0\ub418\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uc678\ubd80\uc758 \ubaa8\ub4e0 \uc11c\ube44\uc2a4\uae4c\uc9c0 \ub2ff\uc558\ub2e4\uace0 \ud560 \uc218\ub294 \uc5c6\ub2e4. \uc9d1\uc5d0\uc11c \uacf5\uc720\uae30\ub77c\uace0 \ubd80\ub974\ub294 \uc791\uc740 \uc0c1\uc790\uc5d0\ub294 \uc5ec\ub7ec \uae30\ub2a5\uc774 \ud568\uaed8 \ub4e4\uc5b4\uac08 \uc218 \uc788\ub2e4. \ubb34\uc120 \uae30\uae30\ub97c \uc5f0\uacb0\ud558\ub294 \uae30\ub2a5\uacfc \ub124\ud2b8\uc6cc\ud06c \uc0ac\uc774\ub85c \ub370\uc774\ud130\ub97c \ubcf4\ub0b4\ub294 \uae30\ub2a5\uc774 \ud55c \uae30\uae30\uc5d0 \ubaa8\uc774\uae30\ub3c4 \ud55c\ub2e4. \ud1b5\uc2e0 \uc7a5\ube44\uc758 \uad6c\uc131\uc740 \uc774\uc6a9 \ud658\uacbd\uc5d0 \ub530\ub77c \ub2e4\ub974\ub2e4. \ud55c \uc0c1\uc790 \uc548\uc5d0 \ub4e4\uc5b4 \uc788\ub2e4\uace0 \ubaa8\ub4e0 \uc5ed\ud560\uc774 \uac19\uc740 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8\uc911 \uc77c\ubd80\uc758 \uc5f0\uacb0\uc774 \ub418\uc5b4 \uc788\uc5b4\ub3c4 \ub2e4\ub978 \ubd80\ubd84\uc5d0\ub294 \ubb38\uc81c\uac00 \uc788\uc744 \uc218 \uc788\ub2e4. \uadf8\ub798\uc11c \uc640\uc774\ud30c\uc774 \uc5f0\uacb0\uacfc \uc778\ud130\ub137 \uc774\uc6a9\uc774 \uac19\uc740 \uc21c\uac04\uc5d0 \ud56d\uc0c1 \uc131\uacf5\ud558\uac70\ub098 \uc2e4\ud328\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubcf4\uc774\ub294 \ubb3c\uac74 \ud558\ub098\uc640 \ub0b4\ubd80 \uae30\ub2a5 \ud558\ub098\ub97c \uac19\uc740 \uac83\uc73c\ub85c \uc0dd\uac01\ud558\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc774\ud574\uc5d0 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. MDN\uc740 \uc5ec\ub7ec \ub124\ud2b8\uc6cc\ud06c\ub97c \uc5f0\uacb0\ud558\ub294 \uc7a5\uce58\ub85c \ub77c\uc6b0\ud130\ub97c \uc124\uba85\ud55c\ub2e4. \uac19\uc740 \ub9dd \uc548\uc758 \uae30\uae30 \uc0ac\uc774\uc5d0\uc11c \uc804\ub2ec\ud558\ub294 \uc77c\uacfc \ub2e4\ub978 \ub9dd\uc73c\ub85c \ubcf4\ub0b4\ub294 \uc77c\uc5d0\ub294 \uc5ed\ud560\uc758 \ucc28\uc774\uac00 \uc788\ub2e4. \ub370\uc774\ud130\ub97c \ubaa9\uc801\uc9c0\ub85c \ub118\uae30\ub294 \uae38\uc774 \ud544\uc694\ud558\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc8fc\uc18c\uc640 \uc7a5\ube44\uc758 \uae30\uc220 \uc774\ub984\uc744 \ubaa8\ub450 \uc678\uc6b8 \ud544\uc694\uac00 \uc5c6\ub2e4. \uac00\uae4c\uc6b4 \uc5f0\uacb0\ub9cc \uc644\uc131\ud574\uc11c\ub294 \uba3c \uacf3\uc5d0 \uc788\ub294 \uc0c1\ub300\uc5d0\uac8c \ub2ff\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4\ub294 \uc6d0\ub9ac\ub97c \ubcf4\uba74 \ub41c\ub2e4. \uc9d1 \uc548\uc758 \uae38\uc744 \ub9cc\ub4e0 \ub4a4\uc5d0\ub3c4 \uadf8 \uae38\uc744 \ubc14\uae65\uacfc \uc787\ub294 \uc900\ube44\uac00 \uc788\uc5b4\uc57c \ud55c\ub2e4. \uac00\uc815\uc758 \ub124\ud2b8\uc6cc\ud06c\ub294 \uc778\ud130\ub137 \uc11c\ube44\uc2a4 \uc81c\uacf5\uc790\uc758 \ub9dd\uacfc \uc5f0\uacb0\ub418\uc5b4 \ub354 \ub113\uc740 \uc138\uacc4\uc5d0 \ub2ff\ub294\ub2e4. \uc5ec\ub7ec \uc81c\uacf5\uc790\uc758 \ub9dd\uc774 \uc11c\ub85c \uc774\uc5b4\uc9c4 \uac83\uc774 \uc778\ud130\ub137\uc758 \uc911\uc694\ud55c \ubc14\ud0d5\uc774\ub2e4. \uc9d1\uc5d0 \uc7a5\ube44\ub97c \uc124\uce58\ud588\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc678\ubd80 \uc5f0\uacb0 \uc11c\ube44\uc2a4\uac00 \uc815\uc0c1\uc801\uc73c\ub85c \uc81c\uacf5\ub41c\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub2e4\ub978 \uc870\uac74\uc774\ub2e4. \uc5b4\ub5a4 \uad6c\uac04\uc5d0\uc11c \ud1b5\uc2e0\uc774 \ub04a\uae30\uba74 \uac00\uae4c\uc6b4 \uc7a5\uce58\uc640\uc758 \ubb34\uc120 \uc5f0\uacb0\uc774 \ub0a8\uc544 \uc788\uc5b4\ub3c4 \uc6f9\uc0ac\uc774\ud2b8\ub97c \uc774\uc6a9\ud558\uc9c0 \ubabb\ud560 \uc218 \uc788\ub2e4. \uc774\uac83\uc740 \ud2b9\uc815 \ub3c5\uc790\uc758 \uae30\uae30\ub97c \uc9c4\ub2e8\ud55c \uacb0\uacfc\uac00 \uc544\ub2c8\ub2e4. \uac19\uc740 \ud654\uba74 \ud45c\uc2dc \ub4a4\uc5d0 \uc5ec\ub7ec \uc5f0\uacb0 \ub2e8\uacc4\uac00 \uc788\ub2e4\ub294 \uc124\uba85\uc774\ub2e4. \uace0\uc7a5 \uc6d0\uc778\uc744 \ud558\ub098\uc758 \ud45c\uc2dc\ub9cc\uc73c\ub85c \ud655\uc815\ud558\uae30\ub294 \uc5b4\ub835\ub2e4. \uad6c\uc131\uacfc \ud5c8\uc6a9 \uc870\uac74\uc774 \ub9de\uc73c\uba74 \uac19\uc740 \ub124\ud2b8\uc6cc\ud06c\uc758 \uae30\uae30\ub4e4\ub07c\ub9ac \uc790\ub8cc\ub97c \uc8fc\uace0\ubc1b\uc744 \uc218 \uc788\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \ub0b4\ubd80\uc758 \uacf5\uc720 \uc790\ub8cc\ub098 \ub124\ud2b8\uc6cc\ud06c \ud504\ub9b0\ud130\ub97c \uc0ac\uc6a9\ud558\ub294 \ubc29\uc2dd\uc744 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uc774\ub7f0 \ud1b5\uc2e0\uc774 \ubc18\ub4dc\uc2dc \uba3c \uc678\ubd80 \uc11c\ubc84\ub97c \uac70\uccd0\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubb3c\ub860 \ubaa8\ub4e0 \uae30\uae30\uac00 \uc11c\ub85c \uc790\ub3d9\uc73c\ub85c \ubcf4\uc774\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub124\ud2b8\uc6cc\ud06c\uc758 \uc124\uc815\uacfc \uc571\uc758 \ub3d9\uc791, \uc811\uadfc \uad8c\ud55c\ub3c4 \ud544\uc694\ud558\ub2e4. \uc911\uc694\ud55c \uc810\uc740 \uc640\uc774\ud30c\uc774\ub97c \uc778\ud130\ub137\uc758 \ub2e4\ub978 \uc774\ub984\uc73c\ub85c\ub9cc \uc0dd\uac01\ud558\uba74 \uc774\ub7f0 \uac00\uae4c\uc6b4 \ud1b5\uc2e0\uc758 \uc5ed\ud560\uc744 \ub193\uce58\uac8c \ub41c\ub2e4\ub294 \uac83\uc774\ub2e4. \ub124\ud2b8\uc6cc\ud06c\uc5d0\ub294 \uc5ec\ub7ec \ubc94\uc704\uac00 \uc788\ub2e4. \uc778\ud130\ub137\uc740 \uc5ec\ub7ec \uae30\uae30\ub97c \uc5f0\uacb0\ud558\ub294 \uae30\ubc18\uc774\ub2e4. \uc6f9\uc740 \uadf8 \uc704\uc5d0\uc11c \uc774\uc6a9\ud558\ub294 \uc11c\ube44\uc2a4 \uac00\uc6b4\ub370 \ud558\ub098\ub2e4. \uc6f9\ud398\uc774\uc9c0\ub97c \ubc1b\ub294 \uac83 \uc678\uc5d0\ub3c4 \uc804\uc790\uc6b0\ud3b8\uc774\ub098 \ub2e4\ub978 \ud1b5\uc2e0 \uc11c\ube44\uc2a4\uac00 \uc774 \uae30\ubc18\uc744 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4. \uc6b0\ub9ac\uac00 \uc790\uc8fc \uc4f0\ub294 \uc11c\ube44\uc2a4\uac00 \uc804\uccb4\uc758 \uc774\ub984\ucc98\ub7fc \ub290\uaef4\uc9c8 \ub54c\uac00 \uc788\ub294 \uc148\uc774\ub2e4. \ub530\ub77c\uc11c \uc6f9\ud398\uc774\uc9c0 \ud558\ub098\uac00 \uc548 \uc5f4\ub9b0\ub2e4\uace0 \ubaa8\ub4e0 \uc778\ud130\ub137 \uc5f0\uacb0\uc774 \ub04a\uacbc\ub2e4\uace0 \ub2e8\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \ud574\ub2f9 \uc11c\ubc84\ub098 \uc8fc\uc18c\ub97c \ucc3e\ub294 \uacfc\uc815, \ud398\uc774\uc9c0 \uc790\uccb4\uc758 \ubb38\uc81c\ub3c4 \uc788\uc744 \uc218 \uc788\ub2e4. \uc774\ubc88 \uae00\uc740 \ubb38\uc81c \ud574\uacb0 \ubaa9\ub85d\uc744 \uc8fc\uae30\ubcf4\ub2e4 \uc5b4\ub5a4 \uc9c8\ubb38\ub4e4\uc774 \uc11c\ub85c \ub2e4\ub978\uc9c0\ub97c \uc54c\ub824 \uc8fc\ub294 \uc774\uc57c\uae30\ub2e4. \uc640\uc774\ud30c\uc774\uc5d0 \uc5f0\uacb0\ub418\uc5c8\ub2e4\ub294 \ud45c\uc2dc\uac00 \uc54c\ub824 \uc8fc\ub294 \uac83\uacfc \ud2b9\uc815 \uc11c\ube44\uc2a4\uac00 \uc751\ub2f5\ud588\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub2e4\ub974\ub2e4. \uae30\uae30\ub294 \uc790\uc2e0\uc774 \ud655\uc778\ud560 \uc218 \uc788\ub294 \uc5f0\uacb0 \uc0c1\ud0dc\ub97c \ud45c\uc2dc\ud558\uc9c0\ub9cc \uc0ac\uc6a9\uc790\ub294 \uadf8 \ud45c\uc2dc\ub97c \uc778\ud130\ub137 \uc804\uccb4\uac00 \uc798\ub41c\ub2e4\ub294 \ub9d0\ub85c \ubc1b\uc544\ub4e4\uc774\uae30 \uc27d\ub2e4. \uc774 \ucc28\uc774\ub97c \uc54c\uba74 \uc5f0\uacb0\ub410\ub294\ub370 \uc548 \ub41c\ub2e4\ub294 \ub9d0\uc774 \uaf2d \ubaa8\uc21c\uc740 \uc544\ub2c8\ub77c\ub294 \uac83\uc744 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uac00\uae4c\uc6b4 \ubb34\uc120 \uc5f0\uacb0\uc740 \ub418\uc5b4 \uc788\uace0 \ub2e4\uc74c \uad6c\uac04\uc740 \ud655\uc778\ub418\uc9c0 \uc54a\uc558\uc744 \uc218 \uc788\ub2e4. \uc5b4\ub5a4 \uc0c1\ud0dc\uac00 \ud655\uc778\ub418\uc5c8\ub294\uc9c0\ub97c \ub098\ub204\uba74 \ubd88\ud3b8\ud55c \uc0c1\ud669\ub3c4 \uc870\uae08 \ub354 \uad6c\uccb4\uc801\uc778 \uc9c8\ubb38\uc73c\ub85c \ubc14\ub010\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \ucc45\uc0c1\uacfc \uc791\uc740 \ubb34\uc120 \uc7a5\uce58\uac00 \uc788\ub294 \uc9d1 \uc548\uc758 \ubd84\uc704\uae30\ub97c \ud45c\ud604\ud588\ub2e4. \uc2e4\uc81c \uacf5\uc720\uae30\uc758 \uc131\ub2a5 \ud45c\uc2dc\ub098 \ud1b5\uc2e0 \ubc94\uc704\ub97c \uce21\uc815\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \uae30\uae30\uc640 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc5f0\uacb0\uc758 \ucc28\uc774\ub97c \ub5a0\uc62c\ub9ac\uae30 \uc704\ud55c \uadf8\ub9bc\uc774\ub2e4. \uc640\uc774\ud30c\uc774\ub294 \ud3b8\ub9ac\ud574\uc11c \uc5f0\uacb0\uc758 \uacfc\uc815\uc744 \uc78a\uac8c \ub9cc\ub4e0\ub2e4. \uadf8\ub7ec\ub098 \ubb34\uc120\uc774\ub77c\ub294 \ub9d0\uc774 \uae38\uc774 \uc5c6\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uae30\uae30\uc5d0\uc11c \uac00\uae4c\uc6b4 \uc7a5\uce58\ub85c, \ub2e4\ub978 \ub124\ud2b8\uc6cc\ud06c\ub97c \uc9c0\ub098 \uc11c\ube44\uc2a4\uc5d0 \ub2ff\ub294 \uc5ec\ub7ec \uad00\uacc4\uac00 \uc788\ub2e4. \uc775\uc219\ud55c \uc5f0\uacb0 \ud45c\uc2dc\ub97c \ud55c \ubc88 \ub098\ub204\uc5b4 \uc77d\uc73c\uba74 \uc778\ud130\ub137\uc774 \uc870\uae08 \ub35c \ub9c9\uc5f0\ud55c \uac83\uc774 \ub41c\ub2e4."}, {"id": "zip-files-and-repetition", "title": "ZIP \u2014 \uc5ec\ub7ec \ud30c\uc77c\uc740 \uc5b4\ub5bb\uac8c \ud55c \ubd09\ud22c\uc5d0 \ub4e4\uc5b4\uac08\uae4c", "summary": "ZIP\uc758 \ud30c\uc77c \ubb36\uc74c\uacfc \ubb34\uc190\uc2e4 \uc555\ucd95\uc744 \ub098\ub204\uc5b4 \ubcf4\uace0 \ubc18\ubcf5 \uc815\ubcf4\ub97c \uc904\uc5ec \uc801\ub294 \uc6d0\ub9ac\ub97c \uc774\ud574\ud569\ub2c8\ub2e4.", "category": "computing", "category_title": "Computing", "subcategory": "Software", "url": "stories/zip-files-and-repetition/index.html", "image": "media/zip-files-and-repetition.png", "alt": "\uc5ec\ub7ec \ubb38\uc11c\ub97c \uc815\ub9ac\ud558\ub294 \uc0ac\ub78c \uacc1\uc5d0 \uc9c0\ud37c \ud30c\uc6b0\uce58\uac00 \ub193\uc778 AI \ube44\uc720 \uc7a5\uba74.", "text": "ZIP \u2014 \uc5ec\ub7ec \ud30c\uc77c\uc740 \uc5b4\ub5bb\uac8c \ud55c \ubd09\ud22c\uc5d0 \ub4e4\uc5b4\uac08\uae4c \ud55c\ub370 \ubb36\ub294 \uc77c\uacfc \ud06c\uae30\ub97c \uc904\uc774\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4 ZIP\uc758 \ud30c\uc77c \ubb36\uc74c\uacfc \ubb34\uc190\uc2e4 \uc555\ucd95\uc744 \ub098\ub204\uc5b4 \ubcf4\uace0 \ubc18\ubcf5 \uc815\ubcf4\ub97c \uc904\uc5ec \uc801\ub294 \uc6d0\ub9ac\ub97c \uc774\ud574\ud569\ub2c8\ub2e4. Software \ucef4\ud4e8\ud305 \uc0ac\uc9c4 \uc5f4 \uc7a5\uc744 \ubcf4\ub0b4\ub824\ub294\ub370 \ud55c \uc7a5\uc529 \ucca8\ubd80\ud558\uae30\uac00 \ubc88\uac70\ub86d\ub2e4. \ud3f4\ub354\ub97c \uc555\ucd95\ud558\uc790 ZIP \ud30c\uc77c \ud558\ub098\uac00 \uc0dd\uae34\ub2e4. \uc548\uc5d0\ub294 \ubd84\uba85 \uc5ec\ub7ec \ud30c\uc77c\uc774 \ub4e4\uc5b4 \uc788\ub294\ub370 \uac89\uc5d0\uc11c\ub294 \ud558\ub098\ub85c \ubcf4\uc778\ub2e4. \uc5ec\uae30\uae4c\uc9c0\ub294 \uc775\uc219\ud55c\ub370, \uc65c \uc5b4\ub5a4 \ub54c\ub294 \uc6a9\ub7c9\uc774 \ud06c\uac8c \uc904\uace0 \uc5b4\ub5a4 \ub54c\ub294 \uac70\uc758 \uadf8\ub300\ub85c\uc77c\uae4c. \uc774 \uc9c8\ubb38\uc744 \ud480\ub824\uba74 \ub450 \uac00\uc9c0 \uc77c\uc744 \ub098\ub204\uc5b4\uc57c \ud55c\ub2e4. \uc5ec\ub7ec \ud30c\uc77c\uc744 \ud55c\ub370 \ub2f4\ub294 \uac83\uacfc \uac01 \ud30c\uc77c\uc758 \ub370\uc774\ud130\ub97c \ub354 \uc9e7\uac8c \ud45c\ud604\ud558\ub294 \uac83\uc774\ub2e4. \ubcf4\ud1b5 \uc555\ucd95\uc774\ub77c\ub294 \ub9d0 \ud55c\ub9c8\ub514\ub85c \ubd80\ub974\uc9c0\ub9cc \uac19\uc740 \uc791\uc5c5\uc740 \uc544\ub2c8\ub2e4. ZIP\uc740 \uc774 \ub458\uc744 \ud568\uaed8 \uc0dd\uac01\ud558\uae30 \uc88b\uc740 \ud30c\uc77c \ud615\uc2dd\uc774\ub2e4. ZIP\uc5d0\ub294 \ud30c\uc77c\uc758 \ub370\uc774\ud130\uc640 \ud568\uaed8 \uc774\ub984 \ub4f1 \ud30c\uc77c\uc744 \uad6c\ubcc4\ud560 \uc815\ubcf4\uac00 \ub4e4\uc5b4\uac04\ub2e4. \uc5ec\ub7ec \ubb38\uc11c\ub97c \ud55c \ubd09\ud22c\uc5d0 \ub123\uc5c8\ub354\ub77c\ub3c4 \ub2e4\uc2dc \uaebc\ub0bc \ub54c \uc5b4\ub290 \ubb38\uc11c\uac00 \ubb34\uc5c7\uc778\uc9c0 \uc54c\uc544\uc57c \ud55c\ub2e4. \ud3f4\ub354\uc758 \uad6c\uc870\ub97c \ub2f4\uc73c\uba74 \ud30c\uc77c \uc0ac\uc774\uc758 \uc704\uce58 \uad00\uacc4\ub3c4 \uc774\uc5b4 \uac08 \uc218 \uc788\ub2e4. \ub530\ub77c\uc11c ZIP\uc740 \ub2e8\uc21c\ud788 \uc6d0\ub798 \ud30c\uc77c\ub4e4\uc744 \ud2c8 \uc5c6\uc774 \ubd99\uc5ec \ub193\uc740 \ub369\uc5b4\ub9ac\uac00 \uc544\ub2c8\ub2e4. \ud504\ub85c\uadf8\ub7a8\uc774 \ub0b4\uc6a9\uc744 \ucc3e\uace0 \ud480 \uc218 \uc788\ub3c4\ub85d \uc815\ud574\uc9c4 \uad6c\uc870\ub97c \uac00\uc9c4\ub2e4. libarchive\uc758 \ud615\uc2dd \uc124\uba85\uc740 ZIP\uc758 \uc911\uc559 \ub514\ub809\ud130\ub9ac\ub3c4 \ub2e4\ub8ec\ub2e4. \uc804\uccb4 \ub0b4\uc6a9\uc758 \ubaa9\ub85d\uc744 \ucc3e\uc544 \uc77d\ub294 \ubc29\uc2dd\uc774 \uc788\ub2e4\ub294 \uc815\ub3c4\ub85c \uc774\ud574\ud558\uba74 \ub41c\ub2e4. ZIP \uc548\uc758 \uac01 \ud56d\ubaa9\uc740 \uc555\ucd95\ud558\uc9c0 \uc54a\uc740 \uc0c1\ud0dc\ub85c \uc800\uc7a5\ub420 \uc218\ub3c4 \uc788\ub2e4. \uc5ec\ub7ec \ud30c\uc77c\uc744 \ud558\ub098\ub85c \uc804\ub2ec\ud558\ub294 \ud3b8\ub9ac\ud568\uc740 \ud06c\uae30\ub97c \uc904\uc774\ub294 \uc791\uc5c5 \uc5c6\uc774\ub3c4 \uc5bb\uc744 \uc218 \uc788\ub2e4. \ub367\ubd99\uc5ec\uc57c \ud560 \uad00\ub9ac \uc815\ubcf4 \ub54c\ubb38\uc5d0 \uc6d0\ub798 \ud30c\uc77c\ub4e4\uc758 \ud569\ubcf4\ub2e4 \uc870\uae08 \ucee4\uc9c8 \uc218\ub3c4 \uc788\ub2e4. \uc774 \uc0ac\uc2e4\uc744 \uc54c\uba74 ZIP \ud30c\uc77c\uc774 \uc608\uc0c1\ub9cc\ud07c \uc791\uc544\uc9c0\uc9c0 \uc54a\uc558\ub2e4\uace0 \uace7\ubc14\ub85c \uc2e4\ud328\ub77c\uace0 \uc0dd\uac01\ud560 \ud544\uc694\uac00 \uc5c6\ub2e4. \ud558\ub098\uc758 \uafb8\ub7ec\ubbf8\ub97c \ub9cc\ub4dc\ub294 \ubaa9\uc801\uacfc \uc800\uc7a5 \uacf5\uac04\uc744 \uc904\uc774\ub294 \ubaa9\uc801\uc774 \ub530\ub85c \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \ud558\ub098\ub97c \uc798\ud588\ub2e4\uace0 \ub2e4\ub978 \ud558\ub098\uae4c\uc9c0 \uc5b8\uc81c\ub098 \uc774\ub8e8\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc555\ucd95\uc758 \uc6d0\ub9ac\ub97c \uc774\ud574\ud558\ub824\uba74 \ubc18\ubcf5\ub418\ub294 \ubb38\uc7a5\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uac19\uc740 \uad6c\uc808\uc774 \uc5ec\ub7ec \ubc88 \ub098\uc624\uba74 \ub9e4\ubc88 \uc804\ubd80 \uc801\ub294 \ub300\uc2e0 \uc55e\uc758 \uc5b4\ub290 \ubd80\ubd84\uc744 \ub2e4\uc2dc \uc77d\uc73c\ub77c\ub294 \uc9e7\uc740 \uc57d\uc18d\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub2e4. \uc774\ud574\ub97c \uc704\ud55c \ube44\uc720\uc774\uba70 \uc2e4\uc81c ZIP\uc774 \ubb38\uc7a5\uc758 \ub73b\uc744 \uc694\uc57d\ud55c\ub2e4\ub294 \ub9d0\uc740 \uc544\ub2c8\ub2e4. ZIP\uc5d0\uc11c \ub110\ub9ac \uc4f0\uc774\ub294 DEFLATE \ubc29\uc2dd\uc740 \uc774\ub7f0 \ubc18\ubcf5\uc744 \ud65c\uc6a9\ud55c\ub2e4. \uc55e\uc11c \ub098\uc628 \ubc14\uc774\ud2b8 \ubc30\uc5f4\uacfc \uac19\uc740 \ubd80\ubd84\uc744 \ucc3e\uc73c\uba74 \uae38\uc774\uc640 \ub4a4\ub85c \ub3cc\uc544\uac08 \uac70\ub9ac\ub97c \uae30\ub85d\ud558\ub294 \uc2dd\uc774\ub2e4. \ucef4\ud4e8\ud130\ub294 \ubb38\uc7a5\uc758 \uac10\ub3d9\uc774\ub098 \uc911\uc694\ub3c4\ub97c \ud310\ub2e8\ud574 \ub35c\uc5b4 \ub0b4\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ub418\ub3cc\ub9b4 \uc218 \uc788\ub294 \uaddc\uce59\uc73c\ub85c \ub370\uc774\ud130\ub97c \ud45c\ud604\ud55c\ub2e4. DEFLATE\uc5d0\ub294 \ud5c8\ud504\uba3c \ubd80\ud638\ud654\ub3c4 \uc0ac\uc6a9\ub41c\ub2e4. \ub370\uc774\ud130 \uac12\uc744 \ud45c\ud604\ud558\ub294 \uae30\ud638\uc758 \uae38\uc774\ub97c \uc870\uc815\ud558\ub294 \ubc29\uc2dd\uc774\ub2e4. \uc774 \uc774\ub984\uc744 \uc678\uc6b0\uc9c0 \uc54a\uc544\ub3c4, \ubc18\ubcf5\ub418\ub294 \ubd80\ubd84\uc744 \uac00\ub9ac\ud0a4\ub294 \uc77c\uacfc \uac1c\ubcc4 \uac12\uc744 \ud6a8\uc728\uc801\uc73c\ub85c \uc801\ub294 \uc77c\uc774 \ud568\uaed8 \uc555\ucd95\uc5d0 \uc4f0\uc778\ub2e4\ub294 \uc810\uc740 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uc2e4\uc81c \ud615\uc2dd\uc5d0\ub294 \uc774\ub97c \ub2e4\uc2dc \ud480 \ub54c \ud544\uc694\ud55c \uc57d\uc18d\ub3c4 \ub4e4\uc5b4\uac04\ub2e4. \uc904\uc5ec \uc801\uc740 \ubb38\uc11c\uc640 \uadf8 \ubb38\uc11c\ub97c \uc77d\ub294 \uaddc\uce59\uc774 \ud568\uaed8 \uc788\uc5b4\uc57c \ud558\ub294 \uc148\uc774\ub2e4. \uadf8\ub798\uc11c \ub0b4\uc6a9\uc5d0 \ub530\ub77c \uc904\uc5b4\ub4dc\ub294 \uc815\ub3c4\uac00 \ub2e4\ub974\uace0, \uc555\ucd95 \uc790\uccb4\uc5d0 \ud544\uc694\ud55c \uc815\ubcf4\ub3c4 \uacf5\uac04\uc744 \uc0ac\uc6a9\ud55c\ub2e4. \ubb34\uc870\uac74 \uac19\uc740 \ube44\uc728\ub85c \uc791\uc544\uc9c0\ub294 \ub9c8\ubc95\uc740 \uc544\ub2c8\ub2e4. \uc774 \ubc29\uc2dd\uc740 \uc555\ucd95\uc744 \ud480\uc5c8\uc744 \ub54c \uc6d0\ub798\uc758 \ubc14\uc774\ud2b8\ub97c \ub418\ucc3e\ub294 \ubb34\uc190\uc2e4 \uc555\ucd95\uc774\ub2e4. \uc0ac\uc9c4\uc758 \uc138\ubd80\ub098 \ubb38\uc11c\uc758 \ub2e8\uc5b4\ub97c \uc77c\ubd80 \ubc84\ub824\uc11c \ud06c\uae30\ub97c \uc904\uc774\ub294 \uc694\uc57d\uacfc \ub2e4\ub974\ub2e4. \ud3b8\uc9c0 \uc5f4 \uc7a5\uc744 \ubcf4\ub0b4\uba70 \ub2e4\uc12f \uc7a5\uc758 \ub0b4\uc6a9\ub9cc \ub0a8\uae30\ub294 \ubc29\uc2dd\uc774 \uc544\ub2cc \uac83\uc774\ub2e4. \ubb3c\ub860 ZIP\uc744 \ub9cc\ub4e4\uae30 \uc804\uc5d0 \uc0ac\uc9c4\uc774 \uc774\ubbf8 \uc190\uc2e4 \uc555\ucd95\ub418\uc5b4 \uc788\uc5c8\ub2e4\uba74 \uadf8 \uc774\uc804\uc758 \uc138\ubd80\uae4c\uc9c0 \ubcf5\uc6d0\ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \ubcf4\uc874\ud558\ub294 \ub300\uc0c1\uc740 ZIP\uc5d0 \ub123\uc740 \ud30c\uc77c\uc758 \ub370\uc774\ud130\ub2e4. \uc5b4\ub290 \ub2e8\uacc4\uc758 \uc6d0\ubcf8\uc744 \ub9d0\ud558\ub294\uc9c0 \uad6c\ubd84\ud558\uba74 \ubb34\uc190\uc2e4\uc774\ub77c\ub294 \ub9d0\uc744 \uacfc\uc7a5\ud558\uc9c0 \uc54a\uace0 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. JPEG \uc0ac\uc9c4\uc774\ub098 \uc774\ubbf8 \uc555\ucd95\ub41c \ub3d9\uc601\uc0c1\uc740 \uc55e\uc120 \uc800\uc7a5 \uacfc\uc815\uc5d0\uc11c \ubc18\ubcf5\uacfc \ud328\ud134\uc744 \uc904\uc5ec \ub193\uc558\uc744 \uc218 \uc788\ub2e4. \uac19\uc740 \ub370\uc774\ud130\ub97c \ub2e4\uc2dc \ub2e4\ub978 \uc555\ucd95\uae30\uc5d0 \ub123\uc5b4\ub3c4 \ub354 \uc904\uc77c \uc5ec\uc9c0\uac00 \uc801\uc744 \uc218 \uc788\ub2e4. \ubc18\uba74 \ubc18\ubcf5\uc774 \ub9ce\uc740 \ub2e8\uc21c\ud55c \uc790\ub8cc\ub294 \ud070 \ucc28\uc774\ub97c \ubcf4\uc77c \uc218 \uc788\ub2e4. RFC 1951\uc740 \uc5b4\ub5a4 \ubb34\uc190\uc2e4 \uc555\ucd95\ubc95\ub3c4 \uac00\ub2a5\ud55c \ubaa8\ub4e0 \uc785\ub825\uc744 \ubc18\ub4dc\uc2dc \ub354 \uc791\uac8c \ub9cc\ub4e4 \uc218\ub294 \uc5c6\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ubaa8\ub4e0 \ud30c\uc77c\uc774 \ubc18\uc73c\ub85c \uc904\uc5b4\ub4e0\ub2e4\ub294 \uae30\ub300 \uc790\uccb4\uac00 \ub9de\uc9c0 \uc54a\ub294 \uac83\uc774\ub2e4. ZIP\uc5d0 \ub2f4\uc558\ub294\ub370 \ud06c\uae30\uac00 \ube44\uc2b7\ud558\ub2e4\uba74 \uc548\uc5d0 \ub123\uc740 \uc790\ub8cc\uc758 \uc131\uaca9\ub3c4 \ud568\uaed8 \ubcfc \ud544\uc694\uac00 \uc788\ub2e4. ZIP \ud615\uc2dd\uc5d0\ub294 \uc554\ud638\ud654 \uae30\ub2a5\uc744 \uc4f0\ub294 \uacbd\uc6b0\ub3c4 \uc788\uc9c0\ub9cc, ZIP\uc774\ub77c\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \ub0b4\uc6a9\uc744 \ubcf4\ud638\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5ec\ub7ec \ud30c\uc77c\uc744 \ubb36\uac70\ub098 \uc555\ucd95\ud588\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc554\ud638\ub85c \uc811\uadfc\uc744 \uc81c\ud55c\ud588\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub2e4\ub974\ub2e4. \uc9c0\ud37c\uac00 \ub2ec\ub9b0 \uc8fc\uba38\ub2c8\uac00 \uace7 \uae08\uace0\uac00 \ub418\uc9c0\ub294 \uc54a\ub294 \uac83\uacfc \ube44\uc2b7\ud558\ub2e4. \ub610 ZIP\uc740 \uc5b8\uc81c\ub098 DEFLATE \ud55c \uc885\ub958\ub9cc \uc0ac\uc6a9\ud558\ub294 \ud615\uc2dd\ub3c4 \uc544\ub2c8\ub2e4. \uad6c\ud604\uacfc \uc120\ud0dd\uc5d0 \ub530\ub77c \ub2e4\ub978 \uc555\ucd95 \ubc29\uc2dd\uc774\ub098 \uc555\ucd95\ud558\uc9c0 \uc54a\ub294 \uc800\uc7a5\uc774 \uac00\ub2a5\ud558\ub2e4. \uc774\ubc88 \uae00\uc5d0\uc11c\ub294 \uac00\uc7a5 \uc775\uc219\ud55c \uc6d0\ub9ac\ub97c \uc124\uba85\ud588\uc73c\uba70 \ubaa8\ub4e0 \ud504\ub85c\uadf8\ub7a8\uc758 \uae30\ub2a5\uc774 \uac19\ub2e4\uace0 \uc548\ub0b4\ud558\uc9c0 \uc54a\ub294\ub2e4. \ub2f4\ub294 \ud615\uc2dd\uacfc \uc548\ucabd\uc758 \ucc98\ub9ac \ubc29\ubc95\uc744 \uad6c\ubcc4\ud558\uba74 \ub41c\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \ubb38\uc11c\ub97c \ubaa8\uc73c\ub294 \uc0ac\ub78c\uacfc \uc9c0\ud37c \ud30c\uc6b0\uce58\uc758 \ube44\uc720\ub2e4. \uc2e4\uc81c \uc555\ucd95 \uc804\ud6c4\uc758 \ud06c\uae30\ub97c \ube44\uad50\ud55c \uc2e4\ud5d8 \uadf8\ub9bc\uc740 \uc544\ub2c8\ub2e4. \ubd09\ud22c\ub77c\ub294 \uc774\ubbf8\uc9c0\ub294 \uc5ec\ub7ec \ud30c\uc77c\uc744 \ud568\uaed8 \uc804\ub2ec\ud55c\ub2e4\ub294 \ub73b\uc744 \ub5a0\uc62c\ub9ac\ub294 \ub370\ub9cc \uc0ac\uc6a9\ud558\uba74 \ub41c\ub2e4. \ub2e4\uc74c\uc5d0 ZIP \ud30c\uc77c\uc744 \ub9cc\ub4e4 \ub54c\ub294 \ub450 \uc9c8\ubb38\uc744 \ub098\ub204\uc5b4 \ubcf4\uc790. \ud30c\uc77c\ub4e4\uc774 \ud3b8\ud558\uac8c \ud55c\ub370 \ubaa8\uc600\ub294\uac00, \uadf8\ub9ac\uace0 \ub370\uc774\ud130\ub294 \uc5bc\ub9c8\ub098 \uc904\uc5c8\ub294\uac00. \ub458\uc758 \ub2f5\uc774 \ub2ec\ub77c\ub3c4 \uc774\uc0c1\ud55c \uc77c\uc740 \uc544\ub2c8\ub2e4. \uc775\uc219\ud55c \uc555\ucd95 \ubc84\ud2bc \ub4a4\uc5d0\ub294 \ub0b4\uc6a9\uc744 \uc798 \ubcf4\uad00\ud558\ub294 \uc77c\uacfc \uac19\uc740 \ub0b4\uc6a9\uc744 \ub354 \ud6a8\uc728\uc801\uc73c\ub85c \uc801\ub294 \uc77c\uc774 \ud568\uaed8 \ub4e4\uc5b4 \uc788\ub2e4."}, {"id": "athens-owl-silver-coin", "title": "\uc544\ud14c\ub124 \u2014 \ubd80\uc5c9\uc774\ub294 \uc5b4\ub5bb\uac8c \ub3c8 \uc704\uc5d0 \uc549\uc558\uc744\uae4c", "summary": "\uae30\uc6d0\uc804 5\uc138\uae30 \uc544\ud14c\ub124 \uc740\ud654\uc758 \uc2e4\uc81c \uc0ac\uc9c4\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc8fc\uc870\ub41c \ub3c8\uacfc \ub3c4\uc2dc\uc758 \uc0c1\uc9d5\uc774 \ub9cc\ub098\ub294 \uc5ed\uc0ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "finance", "category_title": "Finance", "subcategory": "Money", "url": "stories/athens-owl-silver-coin/index.html", "image": "media/athens-owl-silver-coin.jpg", "alt": "\uae30\uc6d0\uc804 5\uc138\uae30 \uc544\ud14c\ub124 \uc740\ud654 \uc591\uba74. \uc67c\ucabd\uc758 \ud22c\uad6c \uc4f4 \uc544\ud14c\ub098\uc640 \uc624\ub978\ucabd\uc758 \ubd80\uc5c9\uc774.", "text": "\uc544\ud14c\ub124 \u2014 \ubd80\uc5c9\uc774\ub294 \uc5b4\ub5bb\uac8c \ub3c8 \uc704\uc5d0 \uc549\uc558\uc744\uae4c \uc740\ud654 \ud55c \ub2e2\uc5d0\uc11c \ub9cc\ub098\ub294 \uc2dc\uc7a5\uacfc \ub3c4\uc2dc\uc758 \uc5bc\uad74 \uae30\uc6d0\uc804 5\uc138\uae30 \uc544\ud14c\ub124 \uc740\ud654\uc758 \uc2e4\uc81c \uc0ac\uc9c4\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc8fc\uc870\ub41c \ub3c8\uacfc \ub3c4\uc2dc\uc758 \uc0c1\uc9d5\uc774 \ub9cc\ub098\ub294 \uc5ed\uc0ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Money \uae08\uc735 \uc740\ud654 \ud55c \ub2e2\uc5d0 \ubd80\uc5c9\uc774\uac00 \uc11c \uc788\ub2e4. \ud070 \ub208\uc740 \uc815\uba74\uc744 \ubcf4\ub294 \ub4ef\ud558\uace0 \ubab8\uc740 \uc606\uc73c\ub85c \ub193\uc600\ub2e4. \ubc18\ub300\ucabd\uc5d0\ub294 \ud22c\uad6c\ub97c \uc4f4 \uc5ec\uc2e0\uc758 \uc5bc\uad74\uc774 \uc788\ub2e4. \uc624\ub298\uc758 \ub3d9\uc804\uc5d0 \uad6d\uc801\uc744 \uc54c\ub824 \uc8fc\ub294 \ubb38\uc591\uc774 \uc788\ub4ef, \uc774 \uc791\uc740 \uc740 \uc870\uac01\uc5d0\ub3c4 \uc5b4\ub290 \ub3c4\uc2dc\uc758 \uc138\uacc4\uc778\uc9c0 \uc54c\uc544\ubcfc \uc218 \uc788\ub294 \ud45c\uc9c0\uac00 \uc0c8\uaca8\uc84c\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 \uae30\uc6d0\uc804 5\uc138\uae30 \uc544\ud14c\ub124 \uc740\ud654\uc758 \uc2e4\uc81c \uc0ac\uc9c4\uc774\ub2e4. \uc544\ud14c\ub098\uc640 \uadf8 \uc5ec\uc2e0\uc758 \uc0c1\uc9d5\uc778 \ubd80\uc5c9\uc774\uac00 \uc591\uba74\uc5d0 \ub4f1\uc7a5\ud55c\ub2e4. \uba4b\uc9c4 \uc870\uac01\uc744 \uac10\uc0c1\ud558\ub294 \ub370\uc11c \uc2dc\uc791\ud574, \uc65c \uc0ac\ub78c\ub4e4\uc740 \uadc0\ud55c \uae08\uc18d\uc5d0 \ubc18\ubcf5\ub418\ub294 \uadf8\ub9bc\uc744 \ucc0d\uc5b4 \ub3c8\uc73c\ub85c \uc0ac\uc6a9\ud588\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uace0\ub300\uc758 \uac70\ub798\uc5d0\uc11c\ub294 \uadc0\uae08\uc18d\uc758 \ubb34\uac8c\uc640 \uac00\uce58\ub97c \ud655\uc778\ud558\ub294 \uc77c\uc774 \uc911\uc694\ud588\ub2e4. \uc8fc\uc870\ub41c \ub3c8\uc740 \uc77c\uc815\ud55c \uae08\uc18d \uc870\uac01\uc5d0 \uc54c\uc544\ubcfc \uc218 \uc788\ub294 \ud45c\uc9c0\ub97c \ub0a8\uae30\ub294 \ubc29\ubc95\uc774\uc5c8\ub2e4. \uad50\uc7ac\ub294 \uadf8\ub9ac\uc2a4 \ub3c4\uc2dc\ub4e4\uc774 \uc18c\uc544\uc2dc\uc544 \uc11c\ubd80 \ub9ac\ub514\uc544\uc758 \uc8fc\uc870 \uad00\ud589\uc744 \ubc1b\uc544\ub4e4\uc778 \ud750\ub984 \uc18d\uc5d0\uc11c \uc544\ud14c\ub124\uc758 \uc740\ud654\ub97c \uc124\uba85\ud55c\ub2e4. \ub2e4\ub9cc \ub3c8\uc774 \uc5c6\ub358 \uc138\uacc4\uac00 \uc5b4\ub290 \ub0a0 \ub3d9\uc804 \ud558\ub098\ub85c \uc644\uc804\ud788 \ubc14\ub00c\uc5c8\ub2e4\uace0 \uc0c1\uc0c1\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ubb3c\uac74\uc758 \uad50\ud658\uacfc \uc5ec\ub7ec \uc9c0\uae09 \ubc29\uc2dd\uc740 \ud568\uaed8 \uc874\uc7ac\ud560 \uc218 \uc788\uc5c8\ub2e4. \ub3d9\uc804\uc740 \uadf8 \uac00\uc6b4\ub370 \ubc18\ubcf5\ub418\ub294 \uac70\ub798\uc5d0\uc11c \uae08\uc18d\uc758 \uac00\uce58\uc640 \ud45c\uc9c0\ub97c \uc5f0\uacb0\ud558\ub294 \uc0c8\ub85c\uc6b4 \ub3c4\uad6c\ub85c \uc790\ub9ac \uc7a1\uc558\ub2e4. \uc740\ud654\uc758 \ud55c\ucabd\uc5d0 \uc788\ub294 \uc544\ud14c\ub098\ub294 \uc544\ud14c\ub124\uc640 \ud2b9\ubcc4\ud55c \uad00\uacc4\ub97c \uac00\uc9c4 \uc5ec\uc2e0\uc774\uc5c8\ub2e4. \ub192\uc740 \uc5b8\ub355\uc758 \uc2e0\uc804\uc5d0\uc11c \ub9cc\ub098\ub358 \ub3c4\uc2dc\uc758 \uc0c1\uc9d5\uc774 \uc791\uc740 \ubb3c\uac74 \uc704\uc5d0\ub3c4 \ub193\uc778 \uac83\uc774\ub2e4. \uc0ac\ub78c\uc740 \ub3c8\uc744 \uc8fc\uace0\ubc1b\uc73c\uba70 \uc2e0\uc804\uae4c\uc9c0 \uac00\uc9c0 \uc54a\uace0\ub3c4 \uc5ec\uc2e0\uc758 \ubaa8\uc2b5\uc744 \uc190\uc5d0 \uc958 \uc218 \uc788\uc5c8\ub2e4. \uc624\ub298\ub0a0 \uc6b0\ub9ac\ub294 \uc9c0\ud3d0\uc640 \ub3d9\uc804\uc758 \ucd08\uc0c1\uc744 \ub108\ubb34 \uc790\uc8fc \ubcf4\uc544 \uac70\uc758 \uc758\uc2dd\ud558\uc9c0 \uc54a\uae30\ub3c4 \ud55c\ub2e4. \uadf8\ub7ec\ub098 \ub204\uad6c\uc758 \uc5bc\uad74\uacfc \uc5b4\ub5a4 \uc0c1\uc9d5\uc744 \ub123\uc744\uc9c0\ub294 \uc120\ud0dd\uc758 \uacb0\uacfc\ub2e4. \uace0\ub300 \uc544\ud14c\ub124\uc758 \ub3c8\ub3c4 \uc21c\uc218\ud55c \uad50\ud658 \ub3c4\uad6c\uc778 \ub3d9\uc2dc\uc5d0 \ub3c4\uc2dc\uac00 \uc790\uae30 \ubaa8\uc2b5\uc744 \ub4dc\ub7ec\ub0b4\ub294 \uc791\uc740 \ud654\uba74\uc774\uc5c8\ub2e4. \uad50\uc7ac\ub294 \ubd80\uc5c9\uc774\ub97c \uc544\ud14c\ub098\uc640 \uc5f0\uacb0\ub418\ub294 \uc9c0\ud61c\uc758 \uc0c1\uc9d5\uc73c\ub85c \uc18c\uac1c\ud55c\ub2e4. \uc5ec\uc2e0\uc758 \uc5bc\uad74\uacfc \ubd80\uc5c9\uc774\ub294 \uc11c\ub85c \ub5a8\uc5b4\uc9c4 \ub450 \uadf8\ub9bc\uc774 \uc544\ub2c8\ub77c \uac19\uc740 \ub3c4\uc2dc\uc758 \uc2e0\uc559\uacfc \uc815\uccb4\uc131\uc744 \uc787\ub294 \ud45c\ud604\uc774\uc5c8\ub2e4. \uae00\uc744 \uae38\uac8c \uc77d\uc9c0 \uc54a\uc544\ub3c4 \ubb38\uc591\uc744 \uc54c\uc544\ubcf4\ub294 \uae38\uc774 \uc788\uc5c8\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c\ub294 \ubd80\uc5c9\uc774\uc758 \ud070 \ub208\uacfc \ub0a0\uac1c, \ubab8\uc758 \uc724\uacfd\uc744 \ucc9c\ucc9c\ud788 \uc0b4\ud3b4\ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uc791\uc740 \uae08\uc18d \uba74 \uc548\uc5d0\uc11c \ud2b9\uc9d5\uc744 \uc54c\uc544\ubcf4\uac8c \ub9cc\ub4dc\ub294 \ud45c\ud604\uc774 \ud544\uc694\ud588\ub2e4. \uc774 \uadf8\ub9bc\ub9cc\uc73c\ub85c \ub2f9\uc2dc \uc0ac\ub78c\ub4e4\uc774 \ubaa8\ub450 \uac19\uc740 \uc2e0\uc559\uc2ec\uc744 \ud488\uc5c8\ub2e4\uace0 \ub9d0\ud560 \uc218\ub294 \uc5c6\uc9c0\ub9cc, \uc5b4\ub5a4 \uc0c1\uc9d5\uc774 \uacf5\uc801\uc778 \ubb3c\uac74 \uc704\uc5d0 \uc120\ud0dd\ub418\uc5c8\ub294\uc9c0\ub294 \ubcfc \uc218 \uc788\ub2e4. \uadf8\ub9ac\uc2a4 \ub3c4\uc2dc\uc758 \uc544\uace0\ub77c\ub294 \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc774\ub294 \uc790\ub9ac\uc774\uba74\uc11c \ubb3c\uac74\uc744 \uc0ac\uace0\ud30c\ub294 \uc7a5\uc18c\uc600\ub2e4. \uad50\uc7ac\ub294 \uc8fc\ud654\uc758 \uc0ac\uc6a9\uc774 \uac70\ub798\ub97c \ud3b8\ub9ac\ud558\uac8c \ud558\ub294 \ud750\ub984\uacfc \uc2dc\uc7a5\uc758 \uc131\uc7a5\uc744 \ud568\uaed8 \uc124\uba85\ud55c\ub2e4. \ub18d\ubd80\uc640 \uc7a5\uc778, \uc0c1\uc778\uc740 \uc790\uc2e0\uc774 \ub9cc\ub4e0 \uac83\uc744 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ub118\uae30\uace0 \ud544\uc694\ud55c \uac83\uc744 \uad6c\ud588\ub2e4. \uac01\uc790\uac00 \uac00\uc9c4 \ubb3c\uac74\uc774 \uc0c1\ub300\uc758 \ud544\uc694\uc640 \uc815\ud655\ud788 \ub9de\uc544\uc57c\ub9cc \ud558\ub294 \uac70\ub798\ubcf4\ub2e4 \uad50\ud658\uc758 \uc911\uac04 \uc218\ub2e8\uc744 \uc4f0\ub294 \uac70\ub798\uac00 \ud3b8\ub9ac\ud560 \ub54c\uac00 \uc788\ub2e4. \ud558\uc9c0\ub9cc \ub3d9\uc804\uc774 \uc0dd\uacbc\ub2e4\uace0 \uac00\uaca9\uc744 \ub458\ub7ec\uc2fc \ud765\uc815\uacfc \uc9c8\uc758 \ud655\uc778\uc774 \uc0ac\ub77c\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc0c8\ub85c\uc6b4 \ub3c4\uad6c\ub294 \uac70\ub798\uc758 \uc77c\ubd80\ub97c \ubc14\uafb8\uba74\uc11c \uae30\uc874\uc758 \ud310\ub2e8\uacfc \ud568\uaed8 \uc6c0\uc9c1\uc600\ub2e4. \uc775\uc219\ud55c \ub3c4\uc548\uc740 \ubb34\uc5c7\uc744 \ubc1b\uc558\ub294\uc9c0 \ud310\ub2e8\ud558\ub294 \ub2e8\uc11c\uac00 \ub41c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc0c8\uaca8\uc9c4 \uadf8\ub9bc\ub9cc\uc73c\ub85c \uae08\uc18d\uc758 \uc591\uacfc \uc0c1\ud0dc\uc5d0 \uad00\ud55c \ubaa8\ub4e0 \ubb38\uc81c\uac00 \ud574\uacb0\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub3c8\uc758 \ud45c\uc9c0\uc640 \uadf8\uac83\uc744 \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub5bb\uac8c \ubc1b\uc544\ub4e4\uc600\ub294\uc9c0\ub294 \ud568\uaed8 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc774 \uc740\ud654\uc758 \uc758\ubbf8\ub3c4 \ubd80\uc5c9\uc774\uac00 \uc608\ubed0\uc11c \ubaa8\ub450\uac00 \ubbff\uc5c8\ub2e4\ub294 \uc2dd\uc73c\ub85c \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub3c4\uc2dc\uc640 \uc2dc\uc7a5, \uadc0\uae08\uc18d\uc758 \uac00\uce58\uc640 \uac70\ub798\uc758 \uad00\ud589\uc774 \ubc30\uacbd\uc5d0 \uc788\uc5c8\ub2e4. \ub3c8\uc740 \ubb3c\uc9c8 \ud55c \uc870\uac01\uc774\uba74\uc11c \uadf8 \uc870\uac01\uc744 \uc5b4\ub5a4 \uad00\uacc4 \uc548\uc5d0\uc11c \uc8fc\uace0\ubc1b\ub294\uc9c0\uc5d0 \uad00\ud55c \uc57d\uc18d\uc774\uae30\ub3c4 \ud588\ub2e4. \uac19\uc740 \uc544\ud14c\ub098\uac00 \ub3d9\uc804\uc5d0\ub3c4 \ub098\ud0c0\ub098\uace0 \ud30c\ub974\ud14c\ub17c \uac19\uc740 \ud070 \uc2e0\uc804\uc758 \uc911\uc2ec\uc5d0\ub3c4 \ub193\uc600\ub2e4. \uaddc\ubaa8\ub294 \ub2e4\ub974\uc9c0\ub9cc \ub3c4\uc2dc\uc758 \uc790\uc6d0\uacfc \uae30\uc220, \uc0c1\uc9d5\uc774 \ub450 \ubb3c\uac74\uc744 \ubaa8\ub450 \ub9cc\ub4e4\uc5c8\ub2e4. \uc544\ud14c\ub124\ub97c \uac74\ucd95\uc73c\ub85c \ubcfc \ub54c\uc640 \ub3c8\uc73c\ub85c \ubcfc \ub54c \uc11c\ub85c \ub2e4\ub978 \ud06c\uae30\uc758 \ud48d\uacbd\uc774 \uc5f4\ub9b0\ub2e4. \ub3c4\uc2dc\uc758 \ubc88\uc601\uc774 \ubaa8\ub450\uc5d0\uac8c \uac19\uc740 \uc0dd\ud65c\uc744 \ub73b\ud588\ub358 \uac83\ub3c4 \uc544\ub2c8\ub2e4. \uad50\uc7ac\uac00 \uc124\uba85\ud558\ub4ef \uc544\ud14c\ub124\uc758 \uc815\uce58\uc801 \ucc38\uc5ec\uc5d0\ub294 \uc5ec\uc131\uacfc \ub178\uc608, \uac70\uc8fc \uc678\uad6d\uc778\uc744 \ubc30\uc81c\ud558\ub294 \uacbd\uacc4\uac00 \uc788\uc5c8\ub2e4. \ud6cc\ub96d\ud55c \uc870\uac01\uacfc \uc2dc\uc7a5\uc758 \uc131\uc7a5\uc744 \uac10\uc0c1\ud558\uba74\uc11c\ub3c4 \uadf8 \ubb3c\uac74\uc744 \uc0ac\uc6a9\ud55c \uc0ac\ud68c\uc758 \ucc28\uc774\ub97c \ud568\uaed8 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc0ac\uc9c4\uc740 \ud55c \uc740\ud654\uc758 \uc591\uba74\uc744 \ub098\ub780\ud788 \ubcf4\uc5ec \uc900\ub2e4. \ub450 \ub3c4\uc2dc\uc758 \ub3c8\uc774\ub098 \uc2dc\ub300\uac00 \ub2e4\ub978 \ub450 \ubb3c\uac74\uc744 \ube44\uad50\ud55c \uadf8\ub9bc\uc774 \uc544\ub2c8\ub2e4. \uc544\ud14c\ub098\uc640 \ubd80\uc5c9\uc774\uac00 \uac19\uc740 \ubb3c\uac74\uc758 \uc55e\ub4a4\uc5d0 \ub193\uc600\ub2e4\ub294 \uc810\uc744 \uc54c\uba74 \uc791\uc740 \ub3d9\uc804\uc758 \uad6c\uc131\ub3c4 \ub354 \ub610\ub837\ud558\uac8c \ubcf4\uc778\ub2e4. \ud604\uc7ac \uc0ac\uc9c4\uc774 \uae30\uc6d0\uc804 5\uc138\uae30\uc758 \uc2dc\uc7a5\uc744 \uc9c1\uc811 \ubcf4\uc5ec \uc8fc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc720\ubb3c\uc758 \ud45c\uba74\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uad50\uc7ac\uc758 \uac70\ub798\uc640 \ub3c4\uc2dc \uc124\uba85\uc744 \ud568\uaed8 \uc77d\ub294 \uac83\uc774\ub2e4. \uc740\ud654 \ud55c \ub2e2\uc744 \uc5bc\ub9c8\uc758 \ud604\ub300 \ud654\ud3d0\uc640 \uac19\ub2e4\uace0 \ub2e8\uc21c\ud788 \ud658\uc0b0\ud558\uc9c0 \uc54a\uc544\ub3c4 \uadf8 \uc2dc\ub300 \uc0ac\ub78c\ub4e4\uc758 \uacbd\uc81c\uc640 \uc0c1\uc9d5\uc744 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \uc544\ud14c\ub124\uc758 \ubd80\uc5c9\uc774\ub294 \uae08\uc735\uc758 \uc5ed\uc0ac\uac00 \uc22b\uc790\uc640 \uacc4\uc0b0\ub9cc\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c0\uc9c0 \uc54a\uc558\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uac70\ub798\ub97c \uc704\ud55c \uae08\uc18d\uc5d0 \uc5ec\uc2e0\uacfc \ub3d9\ubb3c\uc744 \uc0c8\uae30\uace0, \uadf8\uac83\uc744 \uc0ac\ub78c\ub4e4\uc774 \uc54c\uc544\ubcf4\ub294 \ubb3c\uac74\uc73c\ub85c \ub9cc\ub4dc\ub294 \uacfc\uc815\uc5d0\ub294 \uae30\uc220\uacfc \uc2e0\uc559, \ub3c4\uc2dc\uc758 \uc815\uccb4\uc131\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4. \ub2e4\uc74c\uc5d0 \uc624\ub798\ub41c \ub3d9\uc804\uc744 \ub9cc\ub098\uba74 \uac12\uc774 \uc5bc\ub9c8\uc600\ub294\uc9c0\uc640 \ud568\uaed8 \ubb34\uc5c7\uc774 \uadf8\ub824\uc84c\ub294\uc9c0\ub3c4 \ubcf4\uc544 \ub450\uc790. \uc190\ubc14\ub2e5\uc758 \uc791\uc740 \uba74\uc5d0\ub294 \uc5b4\ub290 \uc0ac\ud68c\uac00 \uc790\uc2e0\uc744 \uc5b4\ub5bb\uac8c \ud45c\ud604\ud588\ub294\uc9c0\uac00 \ub0a8\ub294\ub2e4. \ubd80\uc5c9\uc774 \ud55c \ub9c8\ub9ac\ub294 \uc544\ud14c\ub124\uc758 \uc2dc\uc7a5\uacfc \uc2e0\uc804\uc744 \uc774\uc5b4 \uc8fc\ub294 \ub73b\ubc16\uc758 \uc5ed\uc0ac \uc548\ub0b4\uc790\uac00 \ub41c\ub2e4."}, {"id": "bank-run-lombard-street", "title": "\uc740\ud589 \uc55e\uc5d0 \uc904\uc774 \uae38\uc5b4\uc9c0\uba74 \u2014 \ub3c8\uacfc \ubbff\uc74c\uc758 \uc2dc\uac04\ucc28", "summary": "19\uc138\uae30 \ub7f0\ub358 \uae08\uc735\uc2dc\uc7a5\uc758 \uae30\ub85d\uc5d0\uc11c \ub2f9\uc7a5 \uc9c0\uae09\ud560 \ub3c8\uacfc \uc790\uc0b0 \uac00\uce58\uc758 \ucc28\uc774, \uc704\uae30 \ub54c\uc758 \ub300\ucd9c \uc6d0\uce59\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "finance", "category_title": "Finance", "subcategory": "Banking", "url": "stories/bank-run-lombard-street/index.html", "image": "media/bank-run-lombard-street.png", "alt": "19\uc138\uae30 \ub7f0\ub358\uc758 \uc740\ud589 \ubb38 \uc55e\uc5d0 \uc0ac\ub78c\ub4e4\uc774 \ucc28\ub840\ub85c \uc11c \uc788\ub294 \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\uc740\ud589 \uc55e\uc5d0 \uc904\uc774 \uae38\uc5b4\uc9c0\uba74 \u2014 \ub3c8\uacfc \ubbff\uc74c\uc758 \uc2dc\uac04\ucc28 \ubc30\uc800\ud2b8\uc758 \ub86c\ubc14\ub4dc \uc2a4\ud2b8\ub9ac\ud2b8\ub85c \uc77d\ub294 \uae08\uc735 \ubd88\uc548 19\uc138\uae30 \ub7f0\ub358 \uae08\uc735\uc2dc\uc7a5\uc758 \uae30\ub85d\uc5d0\uc11c \ub2f9\uc7a5 \uc9c0\uae09\ud560 \ub3c8\uacfc \uc790\uc0b0 \uac00\uce58\uc758 \ucc28\uc774, \uc704\uae30 \ub54c\uc758 \ub300\ucd9c \uc6d0\uce59\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Banking \uae08\uc735 \uc740\ud589 \uc55e\uc5d0 \uc0ac\ub78c\ub4e4\uc774 \uc904\uc744 \uc11c \uc788\ub2e4. \uc55e\uc0ac\ub78c\uc740 \ub3c8\uc744 \ucc3e\uc73c\ub7ec \uc654\uace0, \uadf8 \ubaa8\uc2b5\uc744 \ubcf8 \ub4b7\uc0ac\ub78c\ub3c4 \uc790\uae30 \ub3c8\uc774 \uac71\uc815\ub418\uae30 \uc2dc\uc791\ud55c\ub2e4. \ubaa8\ub450\uac00 \ub3d9\uc2dc\uc5d0 \ud604\uae08\uc744 \ub2ec\ub77c\uace0 \ud558\uba74 \uc5b4\ub5a4 \uc77c\uc774 \uc0dd\uae38\uae4c. \uc740\ud589\uc5d0 \uc7ac\uc0b0\uc774 \uc788\ub2e4\ub294 \ub9d0\uacfc \uc9c0\uae08 \ucc3d\uad6c\uc5d0\uc11c \ub3c8\uc744 \ub0b4\uc904 \uc218 \uc788\ub2e4\ub294 \ub9d0\uc740 \uac19\uc740 \ub73b\uc77c\uae4c. \uc6d4\ud130 \ubc30\uc800\ud2b8\uc758 \u300a\ub86c\ubc14\ub4dc \uc2a4\ud2b8\ub9ac\ud2b8\u300b\ub294 19\uc138\uae30 \uc601\uad6d \uae08\uc735\uc2dc\uc7a5\uc758 \uc5f0\uacb0\uc744 \uc124\uba85\ud55c \ucc45\uc774\ub2e4. \ub7f0\ub358\uc758 \ud55c \uac70\ub9ac \uc774\ub984\uc744 \uc81c\ubaa9\uc73c\ub85c \uc0bc\uc558\uc9c0\ub9cc, \ucc45\uc774 \ub4e4\uc5ec\ub2e4\ubcf4\ub294 \uac83\uc740 \uac74\ubb3c\ubcf4\ub2e4 \ub3c8\uc744 \ub9e1\uae30\uace0 \ube4c\ub9ac\ub294 \uad00\uacc4\ub2e4. \ub2f9\uc2dc\uc758 \uad6c\uc870\ub97c \uc624\ub298\uc758 \ubaa8\ub4e0 \uc740\ud589\uc5d0 \uadf8\ub300\ub85c \ub300\uc785\ud558\uc9c0 \uc54a\uc73c\uba74\uc11c\ub3c4 \uc911\uc694\ud55c \uc9c8\ubb38\uc744 \uc5bb\uc744 \uc218 \uc788\ub2e4. \ub9cc\uc57d \uc740\ud589\uc774 \ubc1b\uc740 \ub3c8\uc744 \uc804\ubd80 \uae08\uace0\uc5d0 \ubcf4\uad00\ud558\uae30\ub9cc \ud55c\ub2e4\uba74 \ub3c8\uc744 \ucc3e\ub294 \ubaa8\uc2b5\uc744 \uc124\uba85\ud558\uae30\ub294 \ub2e8\uc21c\ud558\ub2e4. \uadf8\ub7ec\ub098 \uc740\ud589\uc740 \uc9c0\uae09\ud560 \uc900\ube44\ub97c \ud558\uba74\uc11c \ub2e4\ub978 \ud55c\ud3b8\uc73c\ub85c \ub300\ucd9c\uacfc \uae08\uc735 \uac70\ub798\ub97c \ud55c\ub2e4. \ub3c8\uc744 \ub9e1\uae34 \uc0ac\ub78c\uc758 \uc694\uad6c\uc640 \ub3c8\uc744 \ube4c\ub9b0 \uc0ac\ub78c\uc758 \uc0c1\ud658 \uc2dc\uc810\uc774 \uc11c\ub85c \ub2e4\ub97c \uc218 \uc788\ub2e4. \ubc30\uc800\ud2b8\ub294 \uc608\uae08\uacfc \uc900\ube44\uae08\uc774 \uc5f0\uacb0\ub41c \uc601\uad6d\uc758 \uae08\uc735\uc2dc\uc7a5\uc744 \uc790\uc138\ud788 \ub2e4\ub8ec\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 \ub3c8\uc744 \ub9e1\uae30\uace0 \ube4c\ub9ac\ub294 \uc2dc\uac04\uc758 \ucc28\uc774\uc5d0 \ucd08\uc810\uc744 \ub9de\ucd98\ub2e4. \ud604\ub300 \uc740\ud589\uc774 \uc608\uae08\uc744 \ub9cc\ub4e4\uace0 \uacb0\uc81c\ud558\ub294 \uc804\uccb4 \uc6d0\ub9ac\ub97c \ud604\uae08\uc758 \ub2e8\uc21c\ud55c \uc7ac\ubd84\ubc30 \ud558\ub098\ub85c \uc124\uba85\ud558\ub824\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uac00\uc0c1\uc758 \uc0ac\ub840\ub97c \uc0dd\uac01\ud574 \ubcf4\uc790. \ub204\uad70\uac00\uac00 \ubc1b\uc744 \ub3c8\uc740 \ucda9\ubd84\ud558\uc9c0\ub9cc \uadf8 \ub3c8\uc774 \ub2e4\uc74c \ub2ec\uc5d0 \ub4e4\uc5b4\uc624\uace0, \uc624\ub298\uae4c\uc9c0 \ub0b4\uc57c \ud560 \uae08\uc561\uc740 \ud070 \uacbd\uc6b0\ub2e4. \uc804\uccb4 \uc7ac\uc0b0\uc758 \uac00\uce58\uc640 \uc624\ub298 \uc4f8 \uc218 \uc788\ub294 \ub3c8 \uc0ac\uc774\uc5d0 \uac04\uaca9\uc774 \uc0dd\uae34\ub2e4. \uc790\uc0b0\uc744 \uace7\ubc14\ub85c \uc81c\uac12\uc5d0 \ud314\uac70\ub098 \ube4c\ub9b4 \uc218 \uc5c6\ub2e4\uba74 \ubb38\uc81c\uac00 \ub41c\ub2e4. \uc774\ucc98\ub7fc \ub2f9\uc7a5 \uc9c0\uae09\ud560 \uc218 \uc788\ub294 \ub2a5\ub825\uc758 \ubb38\uc81c\ub97c \uc720\ub3d9\uc131 \ubb38\uc81c\ub77c\uace0 \ubd80\ub97c \uc218 \uc788\ub2e4. \ubc18\uba74 \uc790\uc0b0\uc744 \ud3c9\uac00\ud574 \ubcf4\uc544\ub3c4 \uac1a\uc544\uc57c \ud560 \ube5a\uc744 \uac10\ub2f9\ud558\uae30 \uc5b4\ub824\uc6b4 \uacbd\uc6b0\ub294 \ub2e4\ub978 \ubb38\uc81c\ub2e4. \ub458\uc740 \ud604\uc2e4\uc5d0\uc11c \uc601\ud5a5\uc744 \uc8fc\uace0\ubc1b\uc744 \uc218 \uc788\uc9c0\ub9cc \uad6c\ubcc4\uc774 \ud544\uc694\ud558\ub2e4. \ubaa8\ub4e0 \uc790\uae08 \ubd80\uc871\uc744 \ub2e8\uc21c\ud788 \uc7a0\uae50\uc758 \uace4\ub780\uc73c\ub85c \ubcfc \uc218\ub294 \uc5c6\ub2e4. \ud3c9\uc0c1\uc2dc\uc5d0\ub294 \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \uac19\uc740 \ub0a0 \ub3c8\uc744 \ucc3e\uc9c0\ub294 \uc54a\ub294\ub2e4. \uadf8\ub7f0\ub370 \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uc774 \uba3c\uc800 \uac00\uc838\uac00\uba74 \ub098\ub294 \ub2a6\uc744 \uc218 \uc788\ub2e4\uace0 \ub290\ub07c\uba74 \uc0ac\uc815\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \ub2f9\uc7a5 \ub3c8\uc774 \ud544\uc694\ud558\uc9c0 \uc54a\uc740 \uc0ac\ub78c\ub3c4 \uc904\uc5d0 \uc11c\uac8c \ub41c\ub2e4. \uac1c\uc778\uc758 \uac71\uc815\uc774 \ubaa8\uc5ec \uc740\ud589\uc758 \uc9c0\uae09 \ubd80\ub2f4\uc744 \ub354 \ud06c\uac8c \ub9cc\ub4e4 \uc218 \uc788\ub2e4. \uc774\ub7f0 \uc9d1\ub2e8 \uc778\ucd9c\uc744 \ud754\ud788 \ubc45\ud06c\ub7f0\uc774\ub77c\uace0 \ubd80\ub978\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub9ac\uc11d\uc5b4\uc11c\ub9cc \uc0dd\uae30\ub294 \uc77c\ub85c \uc124\uba85\ud558\uba74 \ubd80\uc871\ud558\ub2e4. \uc790\uae30 \ub3c8\uc744 \uc9c0\ud0a4\ub824\ub294 \uac01\uc790\uc758 \ud310\ub2e8\uc774 \uc804\uccb4\ub85c\ub294 \ub354 \ud070 \ubd88\uc548\uc744 \ub9cc\ub4e4 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \ubbff\uc74c\uc740 \ucd94\uc0c1\uc801\uc778 \uac10\uc815\uc774\uba74\uc11c\ub3c4 \uc0ac\ub78c\ub4e4\uc774 \uc6c0\uc9c1\uc774\ub294 \uc2dc\uc810\uc744 \uc2e4\uc81c\ub85c \ubc14\uafb8\ub294 \uc694\uc778\uc774 \ub41c\ub2e4. \uae08\uc735\uae30\uad00\ub07c\ub9ac\ub3c4 \ub3c8\uc744 \ub9e1\uae30\uace0 \ube4c\ub9ac\uba70 \uacb0\uc81c\ud55c\ub2e4. \uc5b4\ub290 \ud55c\uacf3\uc774 \uc9c0\uae09\ud558\uc9c0 \ubabb\ud560 \uc218 \uc788\ub2e4\ub294 \uc0dd\uac01\uc740 \uadf8\uacf3\uacfc \uac70\ub798\ud55c \ub2e4\ub978 \uae30\uad00\uc5d0 \ub300\ud55c \uac71\uc815\uc73c\ub85c \ubc88\uc9c8 \uc218 \uc788\ub2e4. \ubc30\uc800\ud2b8\uac00 \ub4e4\uc5ec\ub2e4\ubcf8 \ub7f0\ub358 \uc2dc\uc7a5\uc5d0\uc11c\ub3c4 \ub3c8\uc758 \ubcf4\uad00\uacfc \ub300\ucd9c\uc740 \uc5ec\ub7ec \uce35\uc73c\ub85c \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub2e4. \uc774 \uc5f0\uacb0\uc740 \ud3c9\uc0c1\uc2dc\uc5d0\ub294 \uc790\uae08\uc744 \uc4f0\uae30 \uc27d\uac8c \ud558\uc9c0\ub9cc \uc704\uae30\uc5d0\ub294 \ubd88\uc548\uc774 \uc6c0\uc9c1\uc774\ub294 \uae38\uc774 \ub418\uae30\ub3c4 \ud55c\ub2e4. \ud558\ub098\uc758 \ucc3d\uad6c\uc5d0 \uc904\uc774 \uc0dd\uae34 \uc774\uc720\ub97c \uadf8 \uc9c0\uc810\uc758 \ud604\uae08\ub9cc\uc73c\ub85c \uc124\uba85\ud558\uae30 \uc5b4\ub824\uc6b4 \uae4c\ub2ed\uc774\ub2e4. \ub204\uad6c\uc5d0\uac8c \ubc1b\uc744 \ub3c8\uc774 \uc788\uace0, \ub204\uac00 \ub204\uad6c\uc758 \uc9c0\uae09\uc744 \uae30\ub2e4\ub9ac\ub294\uc9c0 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \ubc30\uc800\ud2b8\ub294 \uc704\uae30\uc5d0 \uc900\ube44\uae08\uc744 \ubcf4\uc720\ud55c \uc911\uc2ec \uae30\uad00\uc774 \uc5b4\ub5bb\uac8c \ub300\uc751\ud560\uc9c0 \ub17c\uc758\ud588\ub2e4. \ucc45\uc5d0\uc11c \uac15\uc870\ud558\ub294 \uc6d0\uce59\uc740 \ub192\uc740 \uc774\uc790\uc728\ub85c \ube4c\ub824\uc8fc\ub418, \uc88b\uc740 \uae08\uc735 \ub2f4\ubcf4\ub97c \ubc14\ud0d5\uc73c\ub85c \ud544\uc694\ud55c \uc790\uae08\uc744 \ub109\ub109\ud558\uac8c \uacf5\uae09\ud558\ub77c\ub294 \uac83\uc774\ub2e4. \uc77c\uc0c1\uc801\uc778 \uc2f8\uace0 \uc26c\uc6b4 \ub300\ucd9c\uc744 \ubaa8\ub450\uc5d0\uac8c \ub098\ub204\uc790\ub294 \uc8fc\uc7a5\uacfc\ub294 \ub2e4\ub974\ub2e4. \uc9c0\uae09 \uac00\ub2a5\ud55c \uc790\uae08\uc774 \ubd80\uc871\ud55c \uacf3\uc5d0 \ub3c8\uc774 \ud758\ub7ec\uac00\uba74 \uc790\uc0b0\uc744 \uae09\ud558\uac8c \ucc98\ubd84\ud558\uace0 \uc11c\ub85c \uc758\uc2ec\ud558\ub294 \uc545\uc21c\ud658\uc744 \uc904\uc77c \uc218 \uc788\ub2e4\ub294 \uc0dd\uac01\uc774\ub2e4. \uc774 \ub17c\uc758\ub294 \ud754\ud788 \ucd5c\uc885 \ub300\ubd80\uc790\uc758 \uc5ed\ud560\uacfc \uc5f0\uacb0\ud574 \uc77d\ud78c\ub2e4. \uc5ec\uae30\uc11c\ub294 \ubc30\uc800\ud2b8\uc758 \ub2f9\uc2dc \uc81c\uc548\uc744 \uc124\uba85\ud558\ub294 \uac83\uc774\uba70 \uc624\ub298\uc758 \ubaa8\ub4e0 \uc911\uc559\uc740\ud589\uc774 \ub611\uac19\uc774 \ud589\ub3d9\ud55c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ud604\uae08\uc744 \uc7a0\uc2dc \uad6c\ud558\uc9c0 \ubabb\ud55c \uacf3\uacfc \uc774\ubbf8 \uc190\uc2e4\uc774 \ucee4\uc11c \uac1a\uae30 \uc5b4\ub824\uc6b4 \uacf3\uc744 \uac00\ub9ac\ub294 \uc77c\uc740 \ub9d0\ucc98\ub7fc \uc27d\uc9c0 \uc54a\ub2e4. \uc704\uae30\uc5d0\ub294 \uc790\uc0b0\uc758 \uac00\uaca9 \uc790\uccb4\uac00 \ubd88\uc548\ud574\uc9c4\ub2e4. \ud3c9\uc0c1\uc2dc\uc5d0 \ubbff\uc744 \ub9cc\ud574 \ubcf4\uc600\ub358 \ub2f4\ubcf4\ub97c \uc5bc\ub9c8\ub85c \ud3c9\uac00\ud560\uc9c0\ub3c4 \ubb38\uc81c\uac00 \ub41c\ub2e4. \uadf8\ub798\uc11c \uc704\uae30 \ub300\ucd9c\uc740 \ub3c8\uc744 \ub9ce\uc774 \ud480\uba74 \ub05d\ub098\ub294 \uac04\ub2e8\ud55c \uc7a5\uba74\uc774 \uc544\ub2c8\ub2e4. \ub3c4\uc6c0\uc744 \uc8fc\uc9c0 \uc54a\uc544 \ubd88\uc548\uc774 \ucee4\uc9c8 \uc704\ud5d8\uacfc, \uc190\uc2e4\uc744 \ucda9\ubd84\ud788 \uc0b4\ud53c\uc9c0 \uc54a\uace0 \uc9c0\uc6d0\ud560 \uc704\ud5d8\uc744 \ud568\uaed8 \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4. \ub192\uc740 \uc774\uc790\uc728\uacfc \uc88b\uc740 \ub2f4\ubcf4\ub77c\ub294 \ub9d0\uc740 \uc774\ub7f0 \uad6c\ubcc4\uc744 \uc2dc\ub3c4\ud558\ub294 \uc6d0\uce59\uc774\uc9c0 \ud310\ub2e8\uc744 \uc790\ub3d9\uc73c\ub85c \ub300\uc2e0\ud558\ub294 \uae30\uacc4\uac00 \uc544\ub2c8\ub2e4. \ubc30\uc800\ud2b8\uac00 \uc0b4\ud3b4\ubcf8 \uc601\uad6d\uc758 \ud1b5\ud654\u00b7\uae08\uc735 \uc81c\ub3c4\uc640 \ud604\uc7ac \uc5ec\ub7ec \ub098\ub77c\uc758 \uc81c\ub3c4\ub294 \ub2e4\ub974\ub2e4. \uc608\uae08 \ubcf4\ud638\ub098 \uc911\uc559\uc740\ud589\uc758 \uc218\ub2e8\ub3c4 \ub098\ub77c\uc640 \uc2dc\ub300\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c4\ub2e4. \uc774 \uae00\ub9cc\uc73c\ub85c \uc624\ub298\uc758 \ud2b9\uc815 \uc740\ud589\uc774 \uc548\uc804\ud55c\uc9c0 \ud310\ub2e8\ud558\uac70\ub098 \uc778\ucd9c \uc5ec\ubd80\ub97c \uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc61b \ucc45\uc758 \uac00\uce58\ub294 \uadf8\ub300\ub85c \ub530\ub77c \ud560 \ucc98\ubc29\uc804\uc744 \uc900\ub2e4\ub294 \ub370\ubcf4\ub2e4 \uc9c8\ubb38\uc744 \uc815\ub9ac\ud574 \uc900\ub2e4\ub294 \ub370 \uc788\ub2e4. \uc790\uc0b0\uc774 \ucda9\ubd84\ud55c\uac00, \ub2f9\uc7a5 \uc9c0\uae09\ud560 \uc218 \uc788\ub294\uac00, \ub2e4\ub978 \uae30\uad00\uacfc \uc5b4\ub5bb\uac8c \uc5f0\uacb0\ub418\ub294\uac00. \uac89\uc73c\ub85c \ubaa8\ub450 \ub3c8\uc774 \uc5c6\ub2e4\ub294 \ub9d0\ub85c \ub4e4\ub9ac\ub294 \uc0c1\ud669\uc744 \uad6c\ubd84\ud574 \ubcf4\uba74 \uae08\uc735 \ub274\uc2a4\ub3c4 \uc870\uae08 \ub35c \ub9c9\uc5f0\ud574\uc9c4\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc740\ud589 \uac70\ub9ac \uadf8\ub9bc\uc740 19\uc138\uae30\uc758 \ubd84\uc704\uae30\ub97c \uc0c1\uc0c1\ud55c AI \uc0bd\ud654\ub2e4. \ud2b9\uc815 \uc704\uae30 \ub54c \ucd2c\uc601\ud55c \uc0ac\uc9c4\uc774\ub098 \uc5b4\ub290 \uc740\ud589\uc758 \uc2e4\uc81c \uc778\ucd9c \uc7a5\uba74\uc774 \uc544\ub2c8\ub2e4. \uc904\uc744 \uc120 \uc0ac\ub78c\uc758 \uc637\ucc28\ub9bc\ubcf4\ub2e4 \uadf8 \uc0ac\ub78c\ub4e4\uc774 \uac19\uc740 \uc2dc\uac04\uc5d0 \uac19\uc740 \uc694\uad6c\ub97c \ud558\uac8c \ub418\ub294 \uc774\uc720\ub97c \ub5a0\uc62c\ub9ac\uae30 \uc704\ud55c \uadf8\ub9bc\uc774\ub2e4. \uc740\ud589 \uc55e\uc758 \uc904 \ub4a4\uc5d0\ub294 \ub3c8\uc774 \ub4e4\uc5b4\uc624\uace0 \ub098\uac00\ub294 \uc2dc\uac04, \uc790\uc0b0\uc758 \uac00\uce58, \uc11c\ub85c\uc5d0 \ub300\ud55c \ubbff\uc74c\uc774 \uacb9\uccd0 \uc788\ub2e4. \uae08\uc735\uc740 \uc22b\uc790\ub97c \uacc4\uc0b0\ud558\ub294 \uc77c\uc778 \ub3d9\uc2dc\uc5d0 \uc5ec\ub7ec \uc0ac\ub78c\uc774 \uc11c\ub85c \ub2e4\ub978 \ubbf8\ub798\ub97c \uc57d\uc18d\ud558\ub294 \uc77c\uc774\ub2e4. \uadf8 \uc57d\uc18d\uc758 \uc2dc\uac04\uc774 \ud55c\uaebc\ubc88\uc5d0 \uc624\ub298\ub85c \ub2f9\uaca8\uc9c8 \ub54c \uc704\uae30\uc758 \uc5b4\ub824\uc6c0\uc774 \ub4dc\ub7ec\ub09c\ub2e4."}, {"id": "banknote-plate-fifty-yang", "title": "\ub3c8\uc744 \ub9cc\ub4e4\ub358 \ub098\ubb34\ud310\uc5d0\ub294 \ubb34\uc5c7\uc774 \ub0a8\uc558\uc744\uae4c", "summary": "\uc22b\uc790\uc640 \uae00\uc790\uac00 \ub0a8\uc740 \uc9c0\ud3d0\uc6d0\ud310\uc5d0\uc11c \uc885\uc774\ub3c8\uc758 \ub4b7\ubaa8\uc2b5\uc744 \ub9cc\ub0a9\ub2c8\ub2e4.", "category": "finance", "category_title": "Finance", "subcategory": "Money", "url": "stories/banknote-plate-fifty-yang/index.html", "image": "media/banknote-plate-fifty-yang.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc9c0\ud3d0\uc6d0\ud310 \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\ub3c8\uc744 \ub9cc\ub4e4\ub358 \ub098\ubb34\ud310\uc5d0\ub294 \ubb34\uc5c7\uc774 \ub0a8\uc558\uc744\uae4c \uc9c0\ud3d0 \ud55c \uc7a5\ubcf4\ub2e4 \uc55e\uc5d0 \uc788\uc5c8\ub358 \ubb3c\uac74 \uc22b\uc790\uc640 \uae00\uc790\uac00 \ub0a8\uc740 \uc9c0\ud3d0\uc6d0\ud310\uc5d0\uc11c \uc885\uc774\ub3c8\uc758 \ub4b7\ubaa8\uc2b5\uc744 \ub9cc\ub0a9\ub2c8\ub2e4. Money \uae08\uc735 \ub0a1\uc740 \uc9c1\uc0ac\uac01\ud615 \ub098\ubb34\ud310\uc774 \uc788\ub2e4. \uac00\uc6b4\ub370\ub294 \uae38\uac8c \ud30c\uc600\uace0 \uac00\uc7a5\uc790\ub9ac\uc5d0\ub294 \uc791\uc740 \uae00\uc790\uc640 \ubb34\ub2ac\uac00 \ub0a8\uc544 \uc788\ub2e4. \ucc98\uc74c \ubcf4\uba74 \uc0c1\uc790\uc758 \ubd80\ud488 \uac19\uae30\ub3c4 \ud558\ub2e4. \uadf8\ub7f0\ub370 \ubc15\ubb3c\uad00\uc774 \ubd99\uc778 \uc774\ub984\uc740 \uc9c0\ud3d0\uc6d0\ud310\uc774\ub2e4. \ub3c8\uc774\ub77c\uace0 \ud558\uba74 \uc9c0\uac11 \uc18d \uc885\uc774\ub098 \ub3d9\uc804\uc744 \ub5a0\uc62c\ub9ac\uc9c0\ub9cc, \uc774\uac83\uc740 \uadf8 \ub3c8\uc744 \ub9cc\ub4dc\ub294 \ucabd\uc5d0 \uc788\ub358 \ubb3c\uac74\uc774\ub2e4. \uc644\uc131\ub41c \uc9c0\ud3d0\uc5d0\uc11c \ud55c \uac78\uc74c \ub4a4\ub85c \ubb3c\ub7ec\uc11c\ub2c8 \ud3c9\uc18c\uc5d0\ub294 \ubcf4\uc9c0 \ubabb\ud558\ub358 \ubb3c\uac74\uc774 \ub098\uc628\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \uc124\uba85\uc5d0 \ub530\ub974\uba74 \uc6d0\ud310 \uc704\ucabd\uc5d0\ub294 TAI WHAN SHOU, \uc544\ub798\ucabd\uc5d0\ub294 FIFTY YANG\uc774\ub77c\ub294 \uae00\uc790\uac00 \uc788\ub2e4. \uc544\ub798 \ubb38\uad6c\uc5d0\ub294 \uc624\uc2ed \uc591\uc774\ub77c\ub294 \uc561\uba74\uc744 \uc601\uc5b4\ub85c \ub098\ud0c0\ub0b8 \ud45c\ud604\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \ub124 \uadc0\ud241\uc774\uc5d0\ub294 \ub465\uadfc \uad6c\uba4d \uc548\uc5d0 \uc624\uc2ed\uacfc 50\uc774\ub77c\ub294 \uae00\uc790\ub3c4 \ub0a8\uc544 \uc788\ub2e4\uace0 \ud55c\ub2e4. \uac19\uc740 \uc218\uac00 \uae00\uc790\uc640 \uc22b\uc790\ub85c \uac70\ub4ed \ub098\ud0c0\ub098\ub294 \uac83\uc774\ub2e4. \uc791\uc740 \uc7a5\uc2dd\uc73c\ub85c\ub9cc \ubcf4\uc774\ub358 \uc790\ub9ac\uc5d0 \ub3c8\uc758 \uae08\uc561\uc744 \uac00\ub9ac\ud0a4\ub294 \uc815\ubcf4\uac00 \ub4e4\uc5b4 \uc788\uc5c8\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \uba3c\uc800 \ub208\uc5d0 \ub4e4\uc5b4\uc624\ub294 \ubd80\ubd84\uc740 \uac00\uc6b4\ub370\uc758 \uae38\ucb49\ud55c \ud648\uc774\ub2e4. \ubc15\ubb3c\uad00\uc740 \uadf8 \uc8fc\ubcc0\uc73c\ub85c \ub369\uad74 \ubaa8\uc591\uc758 \ub2f9\ucd08\ubb38\uc774 \ub458\ub7ec\uc838 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ube44\uc5b4 \uc788\ub294 \uacf5\uac04\uacfc \ucd18\ucd18\ud55c \ubb34\ub2ac\uac00 \ud55c \ud310 \uc548\uc5d0\uc11c \ub098\ub25c\ub2e4. \ub2e4\ub9cc \uc774 \ud648\uc5d0 \uc5b4\ub5a4 \ubd80\ud488\uc774 \ub4e4\uc5b4\uac14\ub294\uc9c0, \uc774 \uc6d0\ud310\uc73c\ub85c \uc2e4\uc81c \uc5bc\ub9c8\ub9cc\ud07c\uc758 \uc9c0\ud3d0\ub97c \ub9cc\ub4e4\uc5c8\ub294\uc9c0\uae4c\uc9c0\ub294 \ud574\ub2f9 \uc124\uba85\uc73c\ub85c \uc54c \uc218 \uc5c6\ub2e4. \uc775\uc219\ud55c \uc778\uc1c4 \uacfc\uc815\uc744 \uac00\uc838\uc640 \ube48\uce78\uc744 \ucc44\uc6b0\uae30\ubcf4\ub2e4, \uc9c0\uae08 \ub0a8\uc544 \uc788\ub294 \ubaa8\uc591\uc5d0\uc11c \uc774\uc57c\uae30\ub97c \uc2dc\uc791\ud574 \ubcf4\uc790. \uc9c0\ud3d0\ub97c \ub5a0\uc62c\ub9ac\uba74 \uac70\ub798\ud560 \ub54c \uc190\uc5d0\uc11c \uc190\uc73c\ub85c \uc624\uac00\ub294 \uc885\uc774\ub97c \uc0dd\uac01\ud55c\ub2e4. \uc774 \uc18c\uc7a5\ud488\uc740 \uadf8 \uc885\uc774\uac00 \uc544\ub2c8\ub77c \uc9c0\ud3d0\uc640 \uad00\ub828\ub41c \ubb34\ub2ac\ub97c \uac00\uc9c4 \ubaa9\uc81c \uc6d0\ud310\uc774\ub2e4. \uc644\uc131\ud488\uacfc \uc81c\uc791 \ub3c4\uad6c\ub97c \uad6c\ubd84\ud558\uba74 \uad00\ucc30\uc758 \ucd08\uc810\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \ubb34\ub2ac\uac00 \ubb34\uc5c7\uc744 \ub73b\ud558\ub294\uc9c0 \uc606\uc5d0 \uadf8 \ubb34\ub2ac\ub97c \uc5b4\ub5a4 \ub9e4\uccb4\uc5d0 \ub0a8\uacbc\ub294\uc9c0\ub3c4 \ubb3b\uac8c \ub41c\ub2e4. \uac00\ub85c 16.3\uc13c\ud2f0\ubbf8\ud130\ub77c\ub294 \ud06c\uae30\ub97c \uc54c\uba74 \uc0ac\uc9c4 \uc18d \ubb3c\uac74\uc744 \uc2e4\uc81c \uc190\uc758 \ubc94\uc704\uc640 \uc5f0\uacb0\ud574 \ubcfc \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc774 \uce58\uc218\ub97c \uace7\ubc14\ub85c \uc644\uc131 \uc9c0\ud3d0\uc758 \ubaa8\ub4e0 \uaddc\uaca9\uc774\ub77c\uace0 \uc4f0\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc6d0\ud310\uc758 \ud06c\uae30\uc640 \uc778\uc1c4\ub41c \uc885\uc774\uc758 \ud06c\uae30\ub294 \uac19\uc740 \uc790\ub8cc\ub85c \ud655\uc815\ud560 \uc218 \uc788\ub294 \ubb38\uc81c\uac00 \uc544\ub2d0 \uc218 \uc788\ub2e4. \uc22b\uc790\uac00 \ubb34\uc5c7\uc744 \uc7ac\ub294\uc9c0\ubd80\ud130 \uc815\ud655\ud788 \uc77d\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc624\uc2ed\uc774\ub77c\ub294 \uae00\uacfc 50\uc774\ub77c\ub294 \uc22b\uc790\ub294 \uac19\uc740 \uc561\uba74\uc744 \ub2e4\ub978 \ud45c\uae30\ub85c \ubcf4\uc5ec \uc900\ub2e4. FIFTY YANG\uc774\ub77c\ub294 \ud45c\ud604\ub3c4 \ud568\uaed8 \uc788\ub2e4. \uc22b\uc790\uc640 \ubb38\uc790\uac00 \ud654\uba74\uc758 \uc5ec\ub7ec \uc790\ub9ac\uc5d0 \ub193\uc600\ub2e4\ub294 \uc810\uc740 \uac00\uce58\uc758 \ud45c\uc2dc\uac00 \uc7a5\uc2dd\uacfc \ub5a8\uc5b4\uc838 \uc788\uc9c0 \uc54a\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ubb34\ub2ac\ub97c \ud558\ub098\uc529 \uc54c\uc544\ubcf4\uba74 \ub3c8\uc758 \uc815\ubcf4\ub97c \uc77d\ub294 \ubc29\uc2dd\ub3c4 \ub2e4\uc591\ud574\uc9c4\ub2e4. \uadf8\ub807\ub2e4\uace0 \uac19\uc740 \uc218\uac00 \ubc18\ubcf5\ub41c \uc774\uc720\ub97c \ud2b9\uc815\ud55c \uc704\uc870 \ubc29\uc9c0 \uae30\uc220 \ud558\ub098\ub85c \ub2e8\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc5b4\ub5a4 \ud6a8\uacfc\ub97c \ubaa9\ud45c\ub85c \uc124\uacc4\ud588\ub294\uc9c0\ub294 \ucd94\uac00 \uae30\ub85d\uc774 \ud544\uc694\ud558\ub2e4. \uc5ec\uae30\uc11c\ub294 \ubc15\ubb3c\uad00\uc774 \ud655\uc778\ud55c \uc704\uce58\uc640 \ud45c\uae30\ub97c \uba3c\uc800 \uc0b4\ud540\ub2e4. \uae00\uacfc \uc22b\uc790\uac00 \ub098\ub258\uc5b4 \uc788\ub294 \ubaa8\uc591\uc740 \ud55c \uc7a5\uc758 \ud1b5\ud654\uac00 \uc5ec\ub7ec \ubd80\ubd84\uc744 \ud1b5\ud574 \uc790\uc2e0\uc744 \uc2dd\ubcc4\ud558\uac8c \ud55c\ub2e4\ub294 \uc810\uc744 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uc911\uc559\uc758 \uae38\ucb49\ud55c \ud648\uacfc \uadf8 \ub458\ub808\uc758 \ub369\uad74\ubb34\ub2ac\ub294 \uc11c\ub85c \ub2e4\ub978 \uc2dc\uac01\uc801 \uc790\ub9ac\ub97c \ub9cc\ub4e0\ub2e4. \ucd18\ucd18\ud55c \ubd80\ubd84\uacfc \ube44\uc5b4 \uc788\ub294 \ubd80\ubd84\uc774 \ud568\uaed8 \uc788\uc5b4\uc11c \ubb3c\uac74\uc758 \uad6c\uc870\uac00 \ub354 \ub69c\ub837\ud574\uc9c4\ub2e4. \ub2e4\ub9cc \uc9c0\uae08 \ud648\uc774 \ubcf4\uc778\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ucc98\uc74c\ubd80\ud130 \uadf8\uacf3\uc774 \ube44\uc6cc\uc838 \uc0ac\uc6a9\ub418\uc5c8\ub2e4\ub294 \ud574\uc11d\uc740 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ube60\uc9c4 \ubd80\ud488\uc758 \uc874\uc7ac\uc640 \uc5ed\ud560\uc740 \uadfc\uac70 \uc5c6\uc774 \ucc44\uc6b8 \uc218 \uc5c6\ub2e4. \uc774\ub7f0 \ubb3c\uac74\uc5d0\uc11c\ub294 \ubb34\uc5c7\uc774 \uc5c6\ub294\uc9c0 \ubb3b\ub294 \uc77c\ub3c4 \uc911\uc694\ud558\ub2e4. \uadf8\ub807\uc9c0\ub9cc \ube48\uacf3\uc744 \ubc1c\uacac\ud588\ub2e4\uace0 \uace7\ubc14\ub85c \uc644\uc804\ud55c \uc81c\uc791 \uacfc\uc815\uc744 \ubcf5\uc6d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc9c0\uae08 \ub0a8\uc740 \uc0c1\ud0dc\uc640 \uc6d0\ub798\uc758 \uae30\ub2a5\uc744 \ub098\ub204\uc5b4 \ubcf4\ub294 \ud0dc\ub3c4\ub294 \ubd88\ud655\uc2e4\ud568\uc744 \ud0a4\uc6b0\uae30\ubcf4\ub2e4 \uc9c8\ubb38\uc744 \uc815\ud655\ud558\uac8c \ub9cc\ub4e0\ub2e4. \ud655\uc778\ud560 \uc218 \uc788\ub294 \uc7a5\uc2dd\uacfc \ud45c\uae30\ubd80\ud130 \ucc28\ub840\ub85c \uc77d\ub294 \ud3b8\uc774 \uc774\uc57c\uae30\ub97c \ub2e8\ub2e8\ud558\uac8c \ud55c\ub2e4. \ud1b5\ud654\ub294 \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uc774 \uac19\uc740 \ub2e8\uc704\ub97c \uc54c\uc544\ubcf4\uace0 \ubc1b\uc544\ub4e4\uc774\ub294 \uad00\uacc4 \uc18d\uc5d0\uc11c \uc0ac\uc6a9\ub41c\ub2e4. \ubc18\ubcf5\ud574\uc11c \ube44\uc2b7\ud55c \ud45c\uc2dc\ub97c \ub9cc\ub4dc\ub294 \ub3c4\uad6c\ub294 \uadf8\ub7f0 \uacf5\ud1b5\ub41c \ubaa8\uc591\uc744 \uc900\ube44\ud558\ub294 \ubb3c\uac74\uc73c\ub85c \ubcfc \uc218 \uc788\ub2e4. \uc6d0\ud310\uc744 \ubcf4\uba74 \uc9c0\ud3d0 \ud55c \uc7a5\uc758 \uc55e\uba74 \ub4a4\uc5d0 \ub204\uad70\uac00 \uc120\uacfc \uae00\uc790\ub97c \uc815\ub9ac\ud558\uace0 \uc7ac\ub8cc\uc5d0 \uc62e\uae30\ub294 \uc791\uc5c5\uc774 \uc788\uc5c8\uc74c\uc744 \ub5a0\uc62c\ub9ac\uac8c \ub41c\ub2e4. \ub2e4\ub9cc \uc774 \ud55c \uc810\uc774 \uc2e4\uc81c\ub85c \uc5b4\ub290 \uc2dc\uae30\uc5d0 \uc5bc\ub9c8\ub098 \uc0ac\uc6a9\ub418\uc5c8\ub294\uc9c0, \uc5b4\ub5a4 \uc81c\ub3c4 \uc548\uc5d0\uc11c \ubc1c\ud589\ub418\uc5c8\ub294\uc9c0\ub294 \uc5ec\uae30\uc11c \ud655\uc778\ud55c \uc124\uba85\uc758 \ubc94\uc704\ub97c \ub118\ub294\ub2e4. \uc8fc\uace0\ubc1b\ub358 \ub3c8\uacfc \ub3c8\uc744 \ub9cc\ub4e4\ub824 \ub0a8\uae34 \ub3c4\uad6c\ub294 \uac01\uac01 \ub2e4\ub978 \uae30\ub85d\uc744 \uc694\uad6c\ud55c\ub2e4. \ub098\ubb34\ud310\uc758 \uae00\uc790\ub97c \ucc9c\ucc9c\ud788 \ubcf4\ub294 \uc77c\uc740 \ud654\ud3d0\uc758 \uc5ed\uc0ac\ub97c \uac00\uaca9\uacfc \uc81c\ub3c4\ubfd0 \uc544\ub2c8\ub77c \uc81c\uc791\ud558\ub294 \uc190\uc758 \uc5ed\uc0ac\ub85c \ub9cc\ub098\ub294 \uc785\uad6c\uac00 \ub41c\ub2e4. \uc18c\uc7a5\ud488 \uc815\ubcf4\uc5d0 \uc801\ud78c \uac00\ub85c \uae38\uc774\ub294 16.3\uc13c\ud2f0\ubbf8\ud130\ub2e4. \ud654\uba74\uc5d0\uc11c \ud06c\uac8c \ubcf4\uba74 \ubb35\uc9c1\ud55c \ud310\ucc98\ub7fc \ub290\uaef4\uc838\ub3c4 \uc2e4\uc81c \ud06c\uae30\ub97c \uac00\ub2a0\ud558\uba74 \uc190 \uac00\uae4c\uc6b4 \ubb3c\uac74\uc774 \ub41c\ub2e4. \ub3c8\uc758 \uc5ed\uc0ac\uac00 \uaf2d \uac70\ub300\ud55c \uae08\uace0\uc5d0\uc11c\ub9cc \uc2dc\uc791\ub418\ub294 \uac83\uc740 \uc544\ub2cc \uc148\uc774\ub2e4. \uc774 \uc6d0\ud310\uc744 \ubcf4\uace0 \ub098\uba74 \uc9c0\ud3d0 \uc704 \uc22b\uc790\ub3c4 \uc870\uae08 \ub2e4\ub974\uac8c \ubcf4\uc778\ub2e4. \uc885\uc774\uc5d0 \ub098\ud0c0\ub09c \uacb0\uacfc\ub9cc \uc788\uc5c8\ub358 \uac83\uc774 \uc544\ub2c8\ub77c, \uadf8\ubcf4\ub2e4 \uc55e\uc11c \uae00\uc790\uc640 \ubb34\ub2ac\ub97c \ub9c8\ub828\ud558\ub294 \ubb3c\uac74\uc774 \uc788\uc5c8\ub2e4. \uc624\ub298\uc740 \ub3c8\uc744 \uc4f0\ub294 \ub300\uc2e0 \ub3c8\uc774 \ub9cc\ub4e4\uc5b4\uc9c0\uae30 \uc804\uc758 \ud55c \uc7a5\uba74\uc744 \ub4e4\uc5ec\ub2e4\ubcf8 \uac83\uc774\ub2e4."}, {"id": "bond-price-when-interest-rates-rise", "title": "\ucc44\uad8c \u2014 \uc774\uc790\ub294 \uadf8\ub300\ub85c\uc778\ub370 \uc65c \uac00\uaca9\uc774 \ub5a8\uc5b4\uc9c8\uae4c", "summary": "\ub9cc\uae30\uac00 1\ub144 \ub0a8\uc740 \uac00\uc0c1 \ucc44\uad8c\uc758 \uacc4\uc0b0\uc73c\ub85c \ud45c\uba74\uc774\uc790\uc640 \uc2dc\uc7a5 \uc218\uc775\ub960, \uac00\uaca9\uc758 \uad00\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "finance", "category_title": "Finance", "subcategory": "Investment", "url": "stories/bond-price-when-interest-rates-rise/index.html", "image": "media/bond-price-when-interest-rates-rise.png", "alt": "\ube48 \ub2ec\ub825\uacfc \ubd09\ud22c\uac00 \ub193\uc778 \ucc45\uc0c1\uc5d0\uc11c \ub450 \uc7a5\uc758 \uc11c\ub958\ub97c \ube44\uad50\ud558\ub294 \uc0ac\ub78c\uc758 \uc0bd\ud654.", "text": "\ucc44\uad8c \u2014 \uc774\uc790\ub294 \uadf8\ub300\ub85c\uc778\ub370 \uc65c \uac00\uaca9\uc774 \ub5a8\uc5b4\uc9c8\uae4c \ubbf8\ub798\uc5d0 \ubc1b\uc744 \uc57d\uc18d\uacfc \uc624\ub298 \uc0ac\uace0\ud30c\ub294 \uac12\uc744 \ub098\ub204\uae30 \ub9cc\uae30\uac00 1\ub144 \ub0a8\uc740 \uac00\uc0c1 \ucc44\uad8c\uc758 \uacc4\uc0b0\uc73c\ub85c \ud45c\uba74\uc774\uc790\uc640 \uc2dc\uc7a5 \uc218\uc775\ub960, \uac00\uaca9\uc758 \uad00\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Investment \uae08\uc735 \ub3c8\uc744 \ube4c\ub824\uc900 \uc99d\uc11c\uac00 \uc788\uace0 \ud574\ub9c8\ub2e4 \ubc1b\uae30\ub85c \ud55c \uc774\uc790\ub3c4 \uc815\ud574\uc838 \uc788\ub2e4. \uadf8\ub7f0\ub370 \uadf8 \uc99d\uc11c\ub97c \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ud314\ub824\uace0 \ud558\ub2c8 \uac00\uaca9\uc774 \ub0b4\ub824\uac14\ub2e4\uace0 \ud55c\ub2e4. \uc57d\uc18d\ud55c \uc774\uc790\uac00 \uadf8\ub300\ub85c\ub77c\uba74 \uac12\ub3c4 \uadf8\ub300\ub85c\uc5ec\uc57c \ud558\ub294 \uac83 \uc544\ub2d0\uae4c. \ucc44\uad8c \ub274\uc2a4\ub97c \uc77d\uc744 \ub54c \uc0dd\uae30\ub294 \uc775\uc219\ud55c \uad81\uae08\uc99d\uc774\ub2e4. \uc774 \uc9c8\ubb38\uc740 \ubbf8\ub798\uc5d0 \ubc1b\ub294 \uae08\uc561\uacfc \uc624\ub298 \uadf8 \uc57d\uc18d\uc744 \uc0ac\ub294 \uac00\uaca9\uc774 \uc11c\ub85c \ub2e4\ub978 \uac83\uc784\uc744 \uc54c\uba74 \ud480\ub9ac\uae30 \uc2dc\uc791\ud55c\ub2e4. \uc5b4\ub835\uac8c \ubcf4\uc774\ub294 \uae08\ub9ac\uc640 \ucc44\uad8c\uc758 \ubc18\ub300 \ubc29\ud5a5 \uad00\uacc4\uc5d0\ub3c4 \ub2e4\ub978 \uc120\ud0dd\uacfc \ube44\uad50\ud558\ub294 \uc0ac\ub78c\uc758 \ud310\ub2e8\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \ucc44\uad8c\uc740 \ubc1c\ud589\uc790\uac00 \uc790\uae08\uc744 \ub9c8\ub828\ud558\uace0 \ud22c\uc790\uc790\uc5d0\uac8c \uc815\ud574\uc9c4 \uc870\uac74\uc758 \uc9c0\uae09\uc744 \uc57d\uc18d\ud558\ub294 \uae08\uc735\uc0c1\ud488\uc774\ub2e4. \uc774\uc790\ub97c \uc815\uae30\uc801\uc73c\ub85c \uc9c0\uae09\ud558\uace0 \ub9cc\uae30\uc5d0 \uc6d0\uae08\uc744 \uac1a\ub294 \ud615\ud0dc\uac00 \ub300\ud45c\uc801\uc774\ub2e4. \ubaa8\ub4e0 \ucc44\uad8c\uc758 \uad6c\uc870\uac00 \uac19\uc9c0\ub294 \uc54a\uc73c\ubbc0\ub85c \uc774\ubc88\uc5d0\ub294 \uae08\uc561\uc774 \uace0\uc815\ub41c \ub2e8\uc21c\ud55c \uacbd\uc6b0\ub97c \uc0dd\uac01\ud558\uc790. OpenStax\ub294 \ucc44\uad8c\uc758 \uac00\uce58\ub97c \uc55e\uc73c\ub85c \ubc1b\uc744 \ub3c8\uc758 \uae08\uc561\uacfc \uc2dc\uc810\uc744 \uc0b4\ud3b4 \ud3c9\uac00\ud55c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc624\ub298 \uc5bc\ub9c8\ub97c \ub0b4\uba74 \ub098\uc911\uc5d0 \ubb34\uc5c7\uc744 \ubc1b\ub294\uc9c0\uac00 \ud575\uc2ec\uc774\ub2e4. \uc57d\uc18d\uc758 \uc885\uc774\uc5d0 \uc801\ud78c \uc6d0\uae08\uacfc \uc9c0\uae08 \uac70\ub798\ud558\ub294 \uac00\uaca9\uc774 \ub298 \uac19\uc740 \uc22b\uc790\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \uc774\ubbf8 \uac00\uc9c4 \ucc44\uad8c\uc774 \uc5f0 3%\uc758 \uc774\uc790\ub97c \uc57d\uc18d\ud55c\ub2e4\uace0 \ud574 \ubcf4\uc790. \ube44\uc2b7\ud55c \uc704\ud5d8\uacfc \uc870\uac74\uc758 \ub2e4\ub978 \uc120\ud0dd\uc5d0\uc11c \ub354 \ub192\uc740 \uc218\uc775\uc744 \uae30\ub300\ud560 \uc218 \uc788\uac8c \ub418\uba74 \uc0c8 \uad6c\ub9e4\uc790\ub294 \uae30\uc874 \ucc44\uad8c\uc744 \uc804\uacfc \uac19\uc740 \uac00\uaca9\uc5d0 \uc0ac\ub824 \ud558\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \uac19\uc740 \ub3c8\uc744 \ub0b4\uace0 \ube44\uad50\uc801 \uc801\uc740 \uae08\uc561\uc744 \ubc1b\ub294 \uc120\ud0dd\uc774 \ub418\uae30 \ub54c\ubb38\uc774\ub2e4. \uc774 \uacbd\uc6b0 \uae30\uc874 \ucc44\uad8c\uc758 \uac00\uaca9\uc774 \ub0b4\ub824\uac00\uba74 \uc774\uc57c\uae30\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \uc801\uac8c \ub0b4\uace0 \uc815\ud574\uc9c4 \ub3c8\uc744 \ubc1b\uac8c \ub418\ubbc0\ub85c \uad6c\ub9e4\uc790\uc758 \uc218\uc775\ub960\uc740 \ub192\uc544\uc9c4\ub2e4. \ubc1c\ud589\uc790\uac00 \uc57d\uc18d\ud55c \uc774\uc790\ub97c \ubc14\uafb8\uc9c0 \uc54a\uc544\ub3c4 \uc0ac\uace0\ud30c\ub294 \uac00\uaca9\uc758 \ubcc0\ud654\ub85c \uc0c8 \uad6c\ub9e4\uc790\uac00 \uc5bb\ub294 \ube44\uc728\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub294 \uac83\uc774\ub2e4. \ub9cc\uae30\uac00 \uc815\ud655\ud788 1\ub144 \ub0a8\uc558\uace0, \uadf8\ub54c \uc6d0\uae08 100\ub9cc \uc6d0\uacfc \uc774\uc790 3\ub9cc \uc6d0\uc744 \ud55c \ubc88\uc5d0 \uc9c0\uae09\ud558\ub294 \uac00\uc0c1 \ucc44\uad8c\uc744 \uc0dd\uac01\ud558\uc790. \uc911\uac04 \uc9c0\uae09\uc740 \uc5c6\uc73c\uba70 \uc9c0\uae09\uc774 \ud655\uc2e4\ud558\ub2e4\uace0 \uac00\uc815\ud55c\ub2e4. \uc138\uae08\uacfc \uac70\ub798 \ube44\uc6a9\ub3c4 \uc0dd\ub7b5\ud55c\ub2e4. \ubc1b\ub294 \uae08\uc561\uc740 103\ub9cc \uc6d0\uc73c\ub85c \uace0\uc815\ub418\uc5b4 \uc788\ub2e4. \uc2dc\uc7a5\uc5d0\uc11c \uc774 \uc870\uac74\uc5d0 \uc5f0 5%\uc758 \uc218\uc775\uc744 \uc694\uad6c\ud55c\ub2e4\uba74 \uc624\ub298 \uac00\uaca9\uc740 103\ub9cc \uc6d0\uc744 1.05\ub85c \ub098\ub208 \uc57d 98\ub9cc 952\uc6d0\uc774 \ub41c\ub2e4. \uadf8 \uac00\uaca9\uc5d0 \uc0b0 \ub3c8\uc774 1\ub144 \ub4a4 5% \ub298\uba74 103\ub9cc \uc6d0\uc774 \ub418\ub294 \uacc4\uc0b0\uc774\ub2e4. \uc2e4\uc81c \ucc44\uad8c\uc758 \uc2dc\uc138\uac00 \uc544\ub2c8\ub77c \uc57d\uc18d\uacfc \uac00\uaca9\uc758 \uad00\uacc4\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uc608\ub2e4. \uac19\uc740 103\ub9cc \uc6d0\uc744 \ubc1b\ub294 \uc57d\uc18d\uc5d0 \uc2dc\uc7a5\uc774 \uc5f0 2%\uc758 \uc218\uc775\ub9cc \uc694\uad6c\ud55c\ub2e4\uba74 \uc624\ub298 \uac00\uaca9\uc740 \uc57d 100\ub9cc 9,804\uc6d0\uc774 \ub41c\ub2e4. \ubc1b\ub294 \ub3c8\uc740 \uac19\uc9c0\ub9cc \uadf8 \ub3c8\uc744 \ubc1b\uae30 \uc704\ud574 \uc9c0\uae08 \ub0bc \uc758\ud5a5\uc774 \uc788\ub294 \uae08\uc561\uc740 \ub354 \ucee4\uc9c4\ub2e4. \ub0ae\uc740 \uc218\uc775\ub960\uc744 \ubc1b\uc544\ub4e4\uc77c\uc218\ub85d \uac00\uaca9\uc740 \ub192\uc544\uc9c0\ub294 \uc148\uc774\ub2e4. \uad50\uc7ac\uac00 \uc124\uba85\ud558\ub294 \uc77c\ubc18\uc801\uc778 \uc5ed\uad00\uacc4\uac00 \uc774 \uc791\uc740 \uacc4\uc0b0\uc5d0 \ub4e4\uc5b4 \uc788\ub2e4. \ub2e4\ub9cc \ub450 \uc608\uc5d0\uc11c\ub294 \ub2e4\ub978 \uc870\uac74\uc774 \uac19\ub2e4\uace0 \ub193\uc558\ub2e4. \uc2e4\uc81c \uc2dc\uc7a5\uc5d0\uc11c\ub294 \uc2e0\uc6a9 \uc704\ud5d8\uacfc \uc9c0\uae09 \uc870\uac74, \uc0ac\uace0\ud314\uae30 \uc26c\uc6b4 \uc815\ub3c4\ub3c4 \ud568\uaed8 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uae08\ub9ac \ud558\ub098\ub9cc \ubcf4\uace0 \ubaa8\ub4e0 \uac00\uaca9 \ubcc0\ud654\ub97c \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \ucc44\uad8c\uc5d0 \uc801\ud78c \uc774\uc790\uc758 \ube44\uc728\uc740 \uc6d0\uae08\uc5d0 \ub300\ud574 \uc5bc\ub9c8\ub97c \uc9c0\uae09\ud560\uc9c0 \uc54c\ub824 \uc900\ub2e4. \ubc18\uba74 \uc9c0\uae08 \uc0ac\ub294 \uc0ac\ub78c\uc758 \uc218\uc775\ub960\uc5d0\ub294 \uc2e4\uc81c \uad6c\ub9e4 \uac00\uaca9\uacfc \uc55e\uc73c\ub85c \ubc1b\uc744 \ub3c8\uc774 \ud568\uaed8 \ub4e4\uc5b4\uac04\ub2e4. \uac19\uc740 \uc57d\uc18d\uc744 \uc11c\ub85c \ub2e4\ub978 \uac00\uaca9\uc5d0 \uc0c0\ub2e4\uba74 \uacb0\uacfc\uc758 \ube44\uc728\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uc774 \uad6c\ubd84\uc744 \ub193\uce58\uba74 \uc774\uc790\ub294 3%\uc778\ub370 \uc65c \uc218\uc775\ub960\uc740 5%\ub77c\uace0 \ub9d0\ud558\ub294\uc9c0 \ud63c\ub780\uc2a4\ub7fd\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uae30\uc900\uc744 \uc0ac\uc6a9\ud558\uace0 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uc55e\uc120 \uc608\uc5d0\uc11c \ubc1c\ud589\uc790\uc758 \uc9c0\uae09\uc561\uc740 \uadf8\ub300\ub85c\uc600\uace0 \uad6c\ub9e4\uc790\uc758 \ucd9c\ubc1c \uae08\uc561\uc774 \ub2ec\ub77c\uc84c\ub2e4. \uc9e7\uc740 \uae08\ub9ac \uc22b\uc790\ub97c \ubcfc \ub54c \ubb34\uc5c7\uc744 \uae30\uc900\uc73c\ub85c \ud55c \ube44\uc728\uc778\uc9c0 \ubb3c\uc5b4\ubcf4\uba74 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ucc44\uad8c\uc744 \ub9cc\uae30 \uc804\uc5d0 \ud314 \ub54c\ub294 \uadf8 \uc2dc\uc810\uc758 \uac70\ub798 \uac00\uaca9\uc774 \uc911\uc694\ud558\ub2e4. \ubc18\uba74 \ub05d\uae4c\uc9c0 \ubcf4\uc720\ud574 \uc57d\uc18d\ub300\ub85c \uc9c0\uae09\ubc1b\ub294 \uacbd\uc6b0\uc5d0\ub294 \ucc98\uc74c\uc5d0 \uc5bc\ub9c8\uc5d0 \uc0c0\uace0 \uc5b4\ub5a4 \ub3c8\uc744 \ubc1b\uc558\ub294\uc9c0\uac00 \uacb0\uacfc\ub97c \uc815\ud55c\ub2e4. \uc2dc\uc7a5 \uac00\uaca9\uc758 \ubcc0\ud654\uc640 \uc2e4\uc81c\ub85c \ub9c8\uce5c \uac70\ub798\uc758 \uc190\uc775\uc740 \uad6c\ubd84\ud574\uc11c \ubcf4\uc544\uc57c \ud55c\ub2e4. \uadf8\ub807\ub2e4\uace0 \ub05d\uae4c\uc9c0 \ubcf4\uc720\ud558\uba74 \uc5b4\ub5a4 \uc704\ud5d8\ub3c4 \uc5c6\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ubc1c\ud589\uc790\uac00 \uc9c0\uae09\ud558\uc9c0 \ubabb\ud560 \uc704\ud5d8\uc774 \uc788\uace0 \ubb3c\uac00 \ubcc0\ud654\ub85c \uad6c\ub9e4\ub825\uc774 \ub2ec\ub77c\uc9c8 \uc218\ub3c4 \uc788\ub2e4. \uad50\uc7ac\ub3c4 \uae08\ub9ac \uc704\ud5d8\uacfc \ucc44\ubb34 \ubd88\uc774\ud589 \uc704\ud5d8\uc744 \ub098\ub204\uc5b4 \uc124\uba85\ud55c\ub2e4. \ub9cc\uae30\ub77c\ub294 \ub0a0\uc9dc\uac00 \ubaa8\ub4e0 \ubb38\uc81c\ub97c \uc5c6\uc560 \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc624\ub298 \uac19\uc740 \uae08\uc561\uc744 \uc8fc\uace0 \ub098\uc911\uc5d0 \uac19\uc740 \uae08\uc561\uc744 \ubc1b\ub294\ub2e4\uace0 \ud574\ub3c4 \uc9c0\uae09\uc758 \ud655\uc2e4\uc131\uc774 \ub2e4\ub974\uba74 \uac00\uce58\ub294 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ucc44\uad8c\uc758 \uc774\ub984\uacfc \uc774\uc790\uc728\ub9cc \ube44\uad50\ud558\uba74 \uc774\ub7f0 \uc870\uac74\uc774 \ube60\uc9c4\ub2e4. \ud22c\uc790\uc790\ub294 \uc5b4\ub290 \uc2dc\uc810\uc5d0 \ubb34\uc5c7\uc744 \ubc1b\uace0 \uc5b4\ub5a4 \uc704\ud5d8\uc744 \ubd80\ub2f4\ud558\ub294\uc9c0 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uacc4\uc57d\uacfc \ub2ec\ub825\uc744 \uc0b4\ud53c\ub294 \uc0c1\uc0c1 \uc18d \uc7a5\uba74\uc774\ub2e4. \uc2e4\uc81c \ucc44\uad8c \uc99d\uc11c\ub098 \uc2dc\uc7a5 \uac00\uaca9\uc758 \ub3c4\ud45c\ub294 \uc544\ub2c8\ub2e4. \uc774\ubc88 \uae00\uc758 \ub450 \uac00\uaca9\ub3c4 \uac19\uc740 \uac00\uc815 \uc544\ub798 \uc9c1\uc811 \uacc4\uc0b0\ud55c \uac12\uc774\uba70 \ud2b9\uc815 \uc0c1\ud488\uc744 \uc0ac\uac70\ub098 \ud314 \uac00\uaca9\uc744 \uc81c\uc2dc\ud558\uc9c0 \uc54a\ub294\ub2e4. \ucc44\uad8c\uc740 \uc774\uc790\uac00 \uc815\ud574\uc84c\ub2e4\ub294 \uc774\uc720\ub85c \uc815\uc9c0\ub41c \ubb3c\uac74\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \uc57d\uc18d\uc744 \uc9c0\uae08 \uc5bc\ub9c8\uc5d0 \uad50\ud658\ud560\uc9c0\ub294 \ub2e4\ub978 \uae30\ud68c\uc640 \uc704\ud5d8\uc744 \ube44\uad50\ud558\ub294 \uc2dc\uc7a5\uc5d0\uc11c \ub2ec\ub77c\uc9c4\ub2e4. \uace0\uc815\ub41c \uc9c0\uae09\uc561\uacfc \uc6c0\uc9c1\uc774\ub294 \uac00\uaca9\uc740 \ubaa8\uc21c\uc774 \uc544\ub2c8\ub77c \uc11c\ub85c \ub2e4\ub978 \uc9c8\ubb38\uc758 \ub2f5\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \uae08\ub9ac\uac00 \uc624\ub974\uace0 \ucc44\uad8c \uac12\uc774 \ub0b4\ub824\uac14\ub2e4\ub294 \ub274\uc2a4\ub97c \ub9cc\ub098\uba74 \uc0c8 \uad6c\ub9e4\uc790\uc758 \uc785\uc7a5\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uac19\uc740 \ubbf8\ub798\uc758 \ub3c8\uc744 \ubc1b\uc73c\ub824\uba74 \uc624\ub298 \uc5bc\ub9c8\ub97c \ub0b4\ub294 \uac83\uc774 \ub9de\uc744\uae4c. \uadf8 \uc9c8\ubb38 \ud558\ub098\uac00 \ucc44\uad8c\uc774\ub77c\ub294 \ub0af\uc120 \uc99d\uc11c\ub97c \uc2dc\uac04\uacfc \uac00\uaca9\uc5d0 \uad00\ud55c \uc870\uae08 \ub354 \uc775\uc219\ud55c \uc57d\uc18d\uc73c\ub85c \ubc14\uafb8\uc5b4 \uc900\ub2e4."}, {"id": "compound-interest-time", "title": "\ubcf5\ub9ac \u2014 \uc774\uc790\uac00 \ub2e4\uc74c \ud574\uc758 \ucd9c\ubc1c\uc120\uc5d0 \uc11c\uba74", "summary": "\uc774\uc790\uac00 \ub2e4\uc2dc \uc774\uc790\ub97c \ub0b3\ub294 \uacc4\uc0b0\uc744 \ub2e8\ub9ac\uc640 \ube44\uad50\ud558\uace0, \uac00\uc815\uacfc \uc2e4\uc81c \ud22c\uc790 \uacb0\uacfc\uac00 \ub2e4\ub978 \uc774\uc720\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "finance", "category_title": "Finance", "subcategory": "Investment", "url": "stories/compound-interest-time/index.html", "image": "media/compound-interest-time.png", "alt": "\ub3d9\uc804\uc774 \uc870\uae08 \ub4e0 \uc720\ub9ac\ubcd1\uacfc \uc800\ucd95 \uc218\ucca9, \ub2ec\ub825\uacfc \ud654\ubd84\uc774 \ub193\uc778 \ud587\ubcd5 \ub4dc\ub294 \ucc45\uc0c1.", "text": "\ubcf5\ub9ac \u2014 \uc774\uc790\uac00 \ub2e4\uc74c \ud574\uc758 \ucd9c\ubc1c\uc120\uc5d0 \uc11c\uba74 \ubc31\ub9cc \uc6d0\uc758 \uc791\uc740 \uacc4\uc0b0\uc73c\ub85c \uc774\ud574\ud558\ub294 \uc2dc\uac04\uc758 \ud6a8\uacfc \uc774\uc790\uac00 \ub2e4\uc2dc \uc774\uc790\ub97c \ub0b3\ub294 \uacc4\uc0b0\uc744 \ub2e8\ub9ac\uc640 \ube44\uad50\ud558\uace0, \uac00\uc815\uacfc \uc2e4\uc81c \ud22c\uc790 \uacb0\uacfc\uac00 \ub2e4\ub978 \uc774\uc720\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Investment \uae08\uc735 \ubc31\ub9cc \uc6d0\uc744 \ub123\uace0 1\ub144 \ub4a4 \uc774\uc790\ub97c \ubc1b\uc558\ub2e4. \uadf8 \uc774\uc790\ub97c \uaebc\ub0b4 \uc4f8 \uc218\ub3c4 \uc788\uace0 \uadf8\ub300\ub85c \ub458 \uc218\ub3c4 \uc788\ub2e4. \ub2e4\uc74c \ud574\uc5d0 \ub450 \uc120\ud0dd\uc740 \uc870\uae08 \ub2e4\ub978 \ucd9c\ubc1c\uc120\uc5d0 \uc120\ub2e4. \ub0a8\uaca8 \ub454 \uc774\uc790\uc5d0\ub3c4 \uc0c8 \uc774\uc790\uac00 \ubd99\ub294\ub2e4\uba74 \uccab\ud574\uc5d0\ub294 \uc791\uc544 \ubcf4\uc774\ub358 \ucc28\uc774\uac00 \uc2dc\uac04\uc774 \uc9c0\ub098\uba70 \ucee4\uc9c8 \uc218 \uc788\ub2e4. \ubcf5\ub9ac\ub294 \uc774\ucc98\ub7fc \ub2e4\uc74c \uacc4\uc0b0\uc758 \ubc14\ud0d5\uc774 \ub2ec\ub77c\uc9c0\ub294 \uc774\uc57c\uae30\ub2e4. \ub9d0\uc740 \uac70\ucc3d\ud558\uc9c0\ub9cc \uccab \ub450 \ud574\ub9cc \ucc9c\ucc9c\ud788 \uacc4\uc0b0\ud574 \ubcf4\uba74 \uc5b4\ub835\uc9c0 \uc54a\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc6d0\ub9ac\ub97c \ubcf4\uae30 \uc704\ud574 \ub9e4\ub144 5%\uc758 \uc774\uc790\uac00 \uc5f0\ub9d0\uc5d0 \ubd99\uace0 \uc774\uc790\ub97c \ubaa8\ub450 \ub0a8\uaca8 \ub454\ub2e4\uace0 \uac00\uc815\ud55c\ub2e4. \uc138\uae08\uacfc \uc218\uc218\ub8cc, \uc911\uac04 \uc785\ucd9c\uae08\uc740 \uc5c6\ub294 \uac00\uc0c1 \uc0ac\ub840\uc774\uba70 \uc2e4\uc81c \uae08\uc735\uc0c1\ud488\uc758 \uc218\uc775\ub960\uc744 \uc81c\uc2dc\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubc31\ub9cc \uc6d0\uc758 5%\ub294 5\ub9cc \uc6d0\uc774\ub2e4. 1\ub144 \ub4a4 \uc6d0\uae08\uacfc \uc774\uc790\ub97c \ud569\ud558\uba74 105\ub9cc \uc6d0\uc774 \ub41c\ub2e4. \ucc98\uc74c \ubc1b\uc740 \ubc31\ub9cc \uc6d0\ub9cc \uae30\uc900\uc73c\ub85c \uc774\uc790\ub97c \uacc4\uc0b0\ud558\ub294 \ub2e8\ub9ac \ubc29\uc2dd\uacfc, \uc774\uc790\ub97c \ub2e4\uc2dc \ub354\ud574 \uac00\ub294 \ubcf5\ub9ac \ubc29\uc2dd\uc740 \uc774 \uccab\ud574\uc5d0\ub294 \uac19\uc740 \uacb0\uacfc\ub97c \ubcf4\uc77c \uc218 \uc788\ub2e4. \ucc28\uc774\ub294 \uadf8\ub2e4\uc74c \uacc4\uc0b0\uc5d0\uc11c \uc0dd\uae34\ub2e4. \uc6d0\ub798\uc758 \ubc31\ub9cc \uc6d0\ub9cc \uacc4\uc18d \uae30\uc900\uc73c\ub85c \uc0bc\uc744 \uac83\uc778\uc9c0, \uccab\ud574\uc5d0 \ubd88\uc5b4\ub09c 105\ub9cc \uc6d0\uc744 \uc0c8\ub85c\uc6b4 \uae30\uc900\uc73c\ub85c \uc0bc\uc744 \uac83\uc778\uc9c0\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \ubcf5\ub9ac\uc758 \ud575\uc2ec\uc740 \ud2b9\ubcc4\ud788 \ub192\uc740 \uc774\uc790\uc728\uc774 \uc544\ub2c8\ub77c \uacc4\uc0b0\uc758 \ubc14\ud0d5\uc5d0 \uc774\uc804 \uc774\uc790\uac00 \ub4e4\uc5b4\uac04\ub2e4\ub294 \uc810\uc774\ub2e4. \ub2e8\ub9ac\ub85c \ud574\ub9c8\ub2e4 \uc6d0\uae08\uc758 5%\ub97c \ubc1b\ub294\ub2e4\uba74 \ub458\uc9f8 \ud574\uc5d0\ub3c4 \uc774\uc790\ub294 5\ub9cc \uc6d0\uc774\ub2e4. 2\ub144\uac04\uc758 \uc774\uc790\ub97c \uc6d0\uae08\uacfc \ud569\ud558\uba74 110\ub9cc \uc6d0\uc774 \ub41c\ub2e4. \uac19\uc740 \uc870\uac74\uc5d0\uc11c \uc5f0\ubcf5\ub9ac\ub85c \uacc4\uc0b0\ud558\uba74 \ub458\uc9f8 \ud574\uc758 \uae30\uc900\uc740 105\ub9cc \uc6d0\uc774\uace0, \uadf8 5%\ub294 5\ub9cc 2,500\uc6d0\uc774\ub2e4. \ub530\ub77c\uc11c \ubcf5\ub9ac\uc758 2\ub144 \ub4a4 \uae08\uc561\uc740 110\ub9cc 2,500\uc6d0\uc774\ub2e4. \ucc28\uc774\uc778 2,500\uc6d0\uc740 \uccab\ud574 \uc774\uc790 5\ub9cc \uc6d0\uc5d0 \ub2e4\uc2dc \ubd99\uc740 \uc774\uc790\ub2e4. \uac11\uc790\uae30 \ud070 \ubd80\uac00 \uc0dd\uae34 \uac83\uc774 \uc544\ub2c8\ub77c \uacc4\uc0b0\uc5d0 \ub4e4\uc5b4\uac00\ub294 \uc791\uc740 \uae08\uc561\uc774 \ud558\ub098 \ub298\uc5b4\ub09c \uc148\uc774\ub2e4. \uc774 \uc791\uc740 \ubcc0\ud654\uac00 \ub2e4\uc74c \ud574\uc5d0\ub3c4 \ub0a8\uc544 \uc788\uac8c \ub41c\ub2e4. \uac19\uc740 \uac00\uc815\uc73c\ub85c 10\ub144\uc744 \uacc4\uc0b0\ud558\uba74 \ub2e8\ub9ac\uc758 \uc6d0\ub9ac\uae08 \ud569\uacc4\ub294 150\ub9cc \uc6d0\uc774\ub2e4. \uc5f0\ubcf5\ub9ac\uc758 \ud569\uacc4\ub294 \uc57d 162\ub9cc 9\ucc9c \uc6d0\uc774\ub2e4. \ucc98\uc74c \ub450 \ud574\uc758 \ucc28\uc774\ub294 \uc791\uc558\uc9c0\ub9cc \ub354\ud574\uc9c4 \uc774\uc790\uac00 \ub2e4\uc74c \uacc4\uc0b0\uc5d0\ub3c4 \ucc38\uc5ec\ud558\uba74\uc11c \ub450 \ubc29\uc2dd\uc758 \uac04\uaca9\uc774 \ucee4\uc84c\ub2e4. \uacc4\uc0b0\ubc95\uc744 \ub9d0\ub85c \uc4f0\uba74 \ub9e4\ub144 \uc9c1\uc804 \uae08\uc561\uc5d0 1.05\ub97c \uacf1\ud558\ub294 \uac83\uc774\ub2e4. 5%\ub97c \ub354\ud55c \uc804\uccb4\uac00 105%\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \ubcf5\uc7a1\ud55c \uacf5\uc2dd\ubd80\ud130 \uc678\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \uac19\uc740 \uacc4\uc0b0\uc744 \uc774\uc5b4 \uac00\uba74 \ub41c\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \uae30\uac04\uacfc \uc774\uc790\uc728, \uc774\uc790\ub97c \ub0a8\uaca8 \ub450\ub294 \uc870\uac74\uc744 \ud568\uaed8 \uc720\uc9c0\ud588\ub2e4\ub294 \uc810\uc774\ub2e4. \ub9e4\ub144 \uc774\uc790 5\ub9cc \uc6d0\uc744 \uacc4\uc88c \ubc16\uc73c\ub85c \ube7c\ub0b4 \uc4f4\ub2e4\uba74 \uadf8 \ub3c8\uc740 \ub2e4\uc74c \ud574\uc758 \uacc4\uc88c \uc774\uc790 \uacc4\uc0b0\uc5d0 \ucc38\uc5ec\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc6d0\uae08 \ubc31\ub9cc \uc6d0\uc744 \uadf8\ub300\ub85c \ub450\ub294 \uac00\uc815\uc5d0\uc11c\ub294 \uacc4\uc88c\uc758 \ubcf5\ub9ac \ud6a8\uacfc\uac00 \uc774\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \ubcf5\ub9ac\ub294 \uc2dc\uac04\uc774 \ud750\ub974\uae30\ub9cc \ud558\uba74 \uc5b4\ub514\uc11c\ub4e0 \uc790\ub3d9\uc73c\ub85c \uc0dd\uae30\ub294 \ubcf4\ub108\uc2a4\uac00 \uc544\ub2c8\ub2e4. \uc911\uac04\uc5d0 \ub3c8\uc744 \ub354 \ub123\uac70\ub098 \uc77c\ubd80\ub97c \ube7c\uba74 \uacb0\uacfc\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uc5b4\ub290 \ub0a0 \ub4e4\uc5b4\uc628 \ub3c8\uc774 \uc5bc\ub9c8 \ub3d9\uc548 \uacc4\uc0b0\uc5d0 \ucc38\uc5ec\ud588\ub294\uc9c0 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \ub450 \uc0ac\ub78c\uc758 \ub9c8\uc9c0\ub9c9 \uae08\uc561\uc744 \ube44\uad50\ud560 \ub54c \ucc98\uc74c \ub123\uc740 \ub3c8\uacfc \uc774\ud6c4 \uc785\ucd9c\uae08\uc774 \ub2e4\ub978\ub370 \uc2dc\uac04\uc758 \ud6a8\uacfc\ub9cc \ube44\uad50\ud588\ub2e4\uace0 \ub9d0\ud558\uba74 \uace4\ub780\ud558\ub2e4. \uc774 \uae00\uc758 \uc0ac\ub840\ub294 1\ub144\uc5d0 \ud55c \ubc88 \uc774\uc790\ub97c \ub354\ud588\ub2e4. \ud604\uc2e4\uc5d0\ub294 \uc774\uc790\ub97c \ubd99\uc774\ub294 \uc8fc\uae30\uc640 \uc9c0\uae09 \ubc29\uc2dd\uc774 \ub2e4\ub978 \uc0c1\ud488\uc774 \uc788\ub2e4. \uc5f0\uc774\ub77c\ub294 \ub9d0\uc774 \ubd99\uc740 \uc774\uc790\uc728 \ud558\ub098\ub9cc \uac19\ub2e4\uace0 \ubaa8\ub4e0 \uacc4\uc0b0 \uacfc\uc815\uacfc \uc2e4\uc81c \uc218\ub839\uc561\uae4c\uc9c0 \uac19\uc544\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774\uc790\uc728\uc744 \uc5b4\ub5a4 \uae30\uac04\uc758 \uac12\uc73c\ub85c \ud45c\ud604\ud588\ub294\uc9c0\uc640 \uc774\uc790\ub97c \uc5b8\uc81c \uc6d0\uae08\uc5d0 \ud569\uce58\ub294\uc9c0\ub97c \uad6c\ubd84\ud558\uba74 \ud63c\ub3d9\uc774 \uc904\uc5b4\ub4e0\ub2e4. \ub9e4\ub2ec \ud45c\uc2dc\ub418\ub294 \uc22b\uc790\ub97c \uc5f0 \uc774\uc790\uc728\ucc98\ub7fc \ube44\uad50\ud558\uac70\ub098 \ubc18\ub300\ub85c \uc0dd\uac01\ud558\uba74 \uc804\ud600 \ub2e4\ub978 \uacc4\uc0b0\uc774 \ub41c\ub2e4. \uacc4\uc0b0\uae30\uc5d0 \uc218\uce58\ub97c \ub123\uae30 \uc804\uc5d0 \uadf8 \uc218\uce58\uc758 \uc2dc\uac04 \ub2e8\uc704\ub97c \uc77d\ub294 \uc77c\uc774 \uba3c\uc800\ub2e4. \uc6d0\ub9ac \uc124\uba85\uc5d0\uc11c\ub294 \uc138\uae08\uacfc \uc218\uc218\ub8cc\ub97c \uc81c\uc678\ud588\uc9c0\ub9cc \uc2e4\uc81c\ub85c \ube44\uc6a9\uc774 \ub098\uac00\uba74 \ub0a8\uaca8 \ub458 \uc218 \uc788\ub294 \uae08\uc561\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uc791\uc740 \ucc28\uc774\uac00 \uc5ec\ub7ec \uae30\uac04 \uc774\uc5b4\uc9c4\ub2e4\ub294 \uc810\uc5d0\uc11c\ub294 \ube44\uc6a9\ub3c4 \uc2dc\uac04\uc744 \ub530\ub77c \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\ub2e4. \ub192\uc740 \ud45c\uc2dc \uc218\uc775\ub960\ub9cc\uc73c\ub85c \ub9c8\uc9c0\ub9c9 \uae08\uc561\uc744 \ub2e8\uc815\ud558\uae30 \uc5b4\ub824\uc6b4 \uc774\uc720\ub2e4. \ubb3c\uac00\uac00 \uc624\ub97c \ub54c\ub294 \uc22b\uc790\ub85c \ub298\uc5b4\ub09c \ub3c8\uc774 \uc0b4 \uc218 \uc788\ub294 \ubb3c\uac74\uc758 \uc591\ub3c4 \ub530\ub85c \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4. \uacc4\uc88c\uc758 \uae08\uc561\uc774 \ucee4\uc84c\ub2e4\ub294 \ub9d0\uacfc \uc0dd\ud65c\uc5d0\uc11c\uc758 \uad6c\ub9e4\ub825\uc774 \uac19\uc740 \ub9cc\ud07c \ub298\uc5c8\ub2e4\ub294 \ub9d0\uc740 \ub2e4\ub974\ub2e4. \uc6d0\uae08\uacfc \uc774\uc790\ub97c \ub354\ud558\ub294 \uacc4\uc0b0\uc740 \ud544\uc694\ud558\uc9c0\ub9cc \uadf8\uac83\ub9cc\uc73c\ub85c \ub3c8\uc758 \uac00\uce58\uc5d0 \uad00\ud55c \ubaa8\ub4e0 \uc9c8\ubb38\uc744 \ub05d\ub0bc \uc218\ub294 \uc5c6\ub2e4. \uc2e4\uc81c \ud22c\uc790\ub294 \ud574\ub9c8\ub2e4 \uac19\uc740 \uc218\uc775\ub960\uc744 \ubcf4\uc7a5\ud558\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \uc190\uc2e4\uc774 \ub09c \uae30\uac04\uc5d0\ub294 \uadf8\ub2e4\uc74c \uacc4\uc0b0\uc758 \ubc14\ud0d5\ub3c4 \uc791\uc544\uc9c4\ub2e4. \uc704\uc758 \uc0ac\ub840\uac00 \ubd80\ub4dc\ub7fd\uac8c \ucee4\uc9c0\ub294 \uae4c\ub2ed\uc740 \uc591\uc758 \uc774\uc790\uc728\uc774 \ub9e4\ub144 \uc77c\uc815\ud558\ub2e4\uace0 \uc815\ud574 \ub193\uc558\uae30 \ub54c\ubb38\uc774\ub2e4. \uacc4\uc0b0 \uacb0\uacfc\ub97c \ubbf8\ub798\uc758 \uc57d\uc18d\uc73c\ub85c \ubc14\uafb8\uc5b4 \uc77d\uc5b4\uc11c\ub294 \uc548 \ub41c\ub2e4. \ub192\uc740 \uc218\uc775\uc744 \uc81c\uc2dc\ud558\ub294 \ud22c\uc790\uc5d0\ub294 \uadf8\uc5d0 \ub530\ub978 \uc704\ud5d8\ub3c4 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc774 \uae00\uc758 \uadfc\uac70\ub85c \uc77d\uc740 \uae08\uc735 \uad50\uc7ac \uc5ed\uc2dc \uacc4\uc0b0\ub41c \ubbf8\ub798 \uae08\uc561\uacfc \uc2e4\uc81c \ud22c\uc790\uc758 \uc704\ud5d8\uc744 \uad6c\ubd84\ud55c\ub2e4. \ubcf5\ub9ac\ub97c \uc774\ud574\ud55c\ub2e4\ub294 \uac83\uc740 \uac00\uc7a5 \ud070 \uc22b\uc790\ub97c \uace0\ub974\ub294 \uc77c\uc774 \uc544\ub2c8\ub77c \uadf8 \uc22b\uc790\uac00 \uc5b4\ub5a4 \uac00\uc815\uc5d0\uc11c \ub098\uc654\ub294\uc9c0 \uc544\ub294 \uc77c\uc774\ub2e4. \uc774\uc790\uc5d0 \ub2e4\uc2dc \uc774\uc790\uac00 \ubd99\ub294\ub2e4\ub294 \ub9d0\uc744 \ucc98\uc74c\uc5d0\ub294 \uc791\uc740 \ub9d0\uc7a5\ub09c\ucc98\ub7fc \ub290\ub084 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \ubc31\ub9cc \uc6d0\uc774 105\ub9cc \uc6d0\uc774 \ub418\uace0, \ub2e4\uc74c \uacc4\uc0b0\uc774 \uadf8 105\ub9cc \uc6d0\uc5d0\uc11c \uc2dc\uc791\ub41c\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ubcf4\uba74 \uad6c\uc870\uac00 \ubd84\uba85\ud574\uc9c4\ub2e4. \ubcf5\ub9ac\ub294 \uc774\uc804 \uacb0\uacfc\uac00 \ub2e4\uc74c \ucd9c\ubc1c\uc810\uc5d0 \ub4e4\uc5b4\uac00\ub294 \uacfc\uc815\uc774\ub2e4. \uadf8\ub9bc \uc18d \uc800\uae08\ud1b5\uacfc \uc791\uc740 \ud654\ubd84\uc740 \uc2dc\uac04\uc758 \ubd84\uc704\uae30\ub97c \ub2f4\uc740 AI \uc0bd\ud654\uc774\uba70 \uae08\uc561 \uc99d\uac00\ub97c \uc99d\uba85\ud558\ub294 \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \ubcf5\ub9ac\ub97c \uc798 \uc774\ud574\ud558\ub824\uba74 \ubb34\uc131\ud558\uac8c \uc790\ub77c\ub294 \ub098\ubb34\ubcf4\ub2e4 \uccab\ud574\uc640 \ub458\uc9f8 \ud574\uc758 \ucc28\uc774\ub97c \uae30\uc5b5\ud574\ub3c4 \ucda9\ubd84\ud558\ub2e4. \uc791\uc740 2,500\uc6d0\uc774 \uc0dd\uae34 \uc774\uc720\ub97c \uc54c\uba74 \ud6e8\uc52c \ud070 \uc22b\uc790\ub3c4 \ucc28\ubd84\ud558\uac8c \uc77d\uc744 \uc218 \uc788\ub2e4."}, {"id": "deposit-insurance-bank-and-safety-net", "title": "\uc608\uae08\uc790\ubcf4\ud638 \u2014 \uc740\ud589\uc758 \uc57d\uc18d \ub4a4\uc5d0 \uc548\uc804\ub9dd\uc744 \ub454 \uc774\uc720", "summary": "\ubbf8\uad6d FDIC\uc758 \uc5ed\uc0ac\uc801 \uc0ac\ub840\ub97c \ubc14\ud0d5\uc73c\ub85c \uc608\uae08\uc790\ubcf4\ud638\uc758 \ubaa9\uc801\u00b7\ubc94\uc704\u00b7\uac10\ub3c5\uc744 \uad6c\ubd84\ud574 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "finance", "category_title": "Finance", "subcategory": "Banking", "url": "stories/deposit-insurance-bank-and-safety-net/index.html", "image": "media/deposit-insurance-bank-and-safety-net.png", "alt": "\uc77c\ubc18\uc801\uc778 \uc740\ud589 \ucc3d\uad6c\uc5d0\uc11c \ud1b5\uc7a5\uc744 \uc55e\uc5d0 \ub450\uace0 \uc124\uba85\uc744 \ub4e3\ub294 \uc0ac\ub78c\uc758 \uc0bd\ud654.", "text": "\uc608\uae08\uc790\ubcf4\ud638 \u2014 \uc740\ud589\uc758 \uc57d\uc18d \ub4a4\uc5d0 \uc548\uc804\ub9dd\uc744 \ub454 \uc774\uc720 1930\ub144\ub300 \ubbf8\uad6d\uc758 \uacbd\ud5d8\uc5d0\uc11c \uc0b4\ud3b4\ubcf4\ub294 \uc81c\ub3c4\uc758 \ubaa9\uc801 \ubbf8\uad6d FDIC\uc758 \uc5ed\uc0ac\uc801 \uc0ac\ub840\ub97c \ubc14\ud0d5\uc73c\ub85c \uc608\uae08\uc790\ubcf4\ud638\uc758 \ubaa9\uc801\u00b7\ubc94\uc704\u00b7\uac10\ub3c5\uc744 \uad6c\ubd84\ud574 \uc77d\uc2b5\ub2c8\ub2e4. Banking \uae08\uc735 \uc740\ud589\uc5d0 \ub9e1\uae34 \ub3c8\uc744 \ucc3e\uc73c\ub7ec \uc0ac\ub78c\ub4e4\uc774 \ud55c\uaebc\ubc88\uc5d0 \ubab0\ub9ac\uba74 \ubd88\uc548\uc740 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c\ub3c4 \ubc88\uc9c4\ub2e4. \ub098\ub294 \uae30\ub2e4\ub9b4 \uc0dd\uac01\uc774\uc5c8\uc5b4\ub3c4 \uae34 \uc904\uc744 \ubcf4\uba74 \ub9c8\uc74c\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ud55c \uc0ac\ub78c\uc758 \ud310\ub2e8\uc774 \uc5ec\ub7ec \uc0ac\ub78c\uc758 \ud589\ub3d9\uacfc \uc5f0\uacb0\ub418\ub294 \uc21c\uac04\uc774\ub2e4. \uc608\uae08\uc790\ubcf4\ud638\ub294 \uc774\ub7f0 \uc0c1\ud669\uc5d0\uc11c \uc740\ud589\uc758 \uc57d\uc18d \ub4a4\uc5d0 \ub610 \ud558\ub098\uc758 \uc548\uc804\ub9dd\uc744 \ub9c8\ub828\ud558\ub824\ub294 \uc81c\ub3c4\ub2e4. \uc774\ubc88\uc5d0\ub294 1930\ub144\ub300 \ubbf8\uad6d\uc758 \uacbd\ud5d8\uacfc \uc5f0\ubc29\uc608\uae08\ubcf4\ud5d8\uacf5\uc0ac, FDIC\uc758 \uc0ac\ub840\ub97c \uc911\uc2ec\uc73c\ub85c \ubaa9\uc801\uc744 \uc0b4\ud3b4\ubcf8\ub2e4. \ud604\uc7ac \ud55c\uad6d\uc758 \ubcf4\ud638 \ud55c\ub3c4\ub098 \ud2b9\uc815 \uc0c1\ud488\uc758 \uc801\uc6a9 \uc5ec\ubd80\ub97c \uc815\ub9ac\ud558\ub294 \uc548\ub0b4\ub294 \uc544\ub2c8\ub2e4. OpenStax\ub294 \ub300\uacf5\ud669\uae30\uc5d0 \ubbf8\uad6d\uc5d0\uc11c \uc740\ud589\uc758 \uc5b4\ub824\uc6c0\uacfc \ub300\uaddc\ubaa8 \uc778\ucd9c\uc774 \uc11c\ub85c \uc5bd\ud614\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc740\ud589\uc774 \ub3c8\uc744 \uc9c0\uae09\ud558\uc9c0 \ubabb\ud560 \uc218 \uc788\ub2e4\ub294 \uac71\uc815\uc774 \ucee4\uc9c0\uba74 \ub354 \ub9ce\uc740 \uc0ac\ub78c\uc774 \uba3c\uc800 \ucc3e\uc73c\ub824 \ud55c\ub2e4. \uadf8 \ud589\ub3d9\uc774 \uc740\ud589\uc758 \ub2f9\uc7a5 \uc9c0\uae09\ud560 \ub3c8\uc5d0 \ubd80\ub2f4\uc744 \ub354\ud560 \uc218 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubaa8\ub4e0 \uc740\ud589\uc758 \ubb38\uc81c\uac00 \uac19\uc740 \uc6d0\uc778\uc774\ub77c\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc790\uc0b0\uc758 \uc190\uc2e4\uacfc \ub2f9\uc7a5 \ud604\uae08\uc744 \ub9c8\ub828\ud560 \ub2a5\ub825\ub3c4 \ub2e4\ub978 \ubb38\uc81c\ub2e4. \ub2e4\ub9cc \uc608\uae08\uc790\ub294 \uc740\ud589 \ub0b4\ubd80\ub97c \ub9e4\uc77c \uc9c1\uc811 \ud3c9\uac00\ud558\uae30 \uc5b4\ub835\ub2e4. \uac1c\ubcc4 \uc0ac\ub78c\uc774 \uac00\uc9c4 \uc815\ubcf4\uc758 \ud55c\uacc4\uac00 \ubd88\uc548\uc758 \uc804\ud30c\uc640 \ub9cc\ub0a0 \ub54c \uc81c\ub3c4\uc758 \uc9c8\ubb38\uc774 \uc0dd\uae34\ub2e4. \uad50\uc7ac\ub294 \ubbf8\uad6d\uc758 1933\ub144 \uc740\ud589\ubc95\uc5d0 \ub530\ub77c FDIC\uac00 \ub9cc\ub4e4\uc5b4\uc84c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc740\ud589\uc774 \uc2e4\ud328\ud588\uc744 \ub54c \uc608\uae08\uc744 \ubcf4\ud638\ud558\uae30 \uc704\ud55c \uae30\uad00\uc774\uc5c8\ub2e4. \uc740\ud589\uc758 \uc790\uccb4 \uc2e0\ub8b0\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uc608\uae08\uc790\ub97c \uc548\uc2ec\uc2dc\ud0a4\uae30 \uc5b4\ub824\uc6e0\ub358 \uacbd\ud5d8\uc774 \uc81c\ub3c4\uc801 \uc7a5\uce58\ub85c \uc774\uc5b4\uc9c4 \uac83\uc774\ub2e4. \uc5ec\uae30\uc11c \ud55c \ub098\ub77c\uc758 \uc5ed\uc0ac\uc801 \uc0ac\ub840\uc640 \ubaa8\ub4e0 \ub098\ub77c\uc758 \ud604\uc7ac \uc81c\ub3c4\ub97c \uc11e\uc9c0 \uc54a\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4. \ud55c\uad6d\uc744 \ube44\ub86f\ud55c \ub2e4\ub978 \ub098\ub77c\uc758 \uc801\uc6a9 \ub300\uc0c1\uacfc \ud55c\ub3c4, \uc6b4\uc601 \ubc29\uc2dd\uc740 \ub530\ub85c \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \uc774\ubc88 \uc774\uc57c\uae30\uac00 \ubcf4\uc5ec \uc8fc\ub294 \uac83\uc740 \uad6c\uccb4\uc801\uc778 \ubcf4\ud638 \uae08\uc561\ubcf4\ub2e4 \uc740\ud589\uc758 \uc2e4\ud328 \ube44\uc6a9\uc744 \uc5b4\ub5a4 \uc7a5\uce58\ub85c \ub2e4\ub8e8\ub824 \ud588\ub294\uac00\ub77c\ub294 \uc9c8\ubb38\uc774\ub2e4. \ubcf4\ud638 \uc81c\ub3c4\uac00 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ud574\ub2f9 \uc740\ud589\uc758 \ubaa8\ub4e0 \uc790\uc0b0\uc774 \uc88b\uc740 \uc0c1\ud0dc\ub77c\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc81c\ub3c4\uc758 \ubaa9\uc801\uc740 \uc815\ud574\uc9c4 \uc870\uac74\uc5d0\uc11c \uc608\uae08\uc790\ub97c \ubcf4\ud638\ud558\ub294 \uac83\uc774\uba70 \uc740\ud589\uc758 \ubaa8\ub4e0 \uc0ac\uc5c5\uc774 \uc131\uacf5\ud558\ub3c4\ub85d \ubcf4\uc7a5\ud558\ub294 \uac83\uacfc\ub294 \ub2e4\ub974\ub2e4. \uae30\uad00\uc758 \uac74\uc804\uc131\uacfc \uc608\uae08\uc790\uc758 \ubcf4\ud638\ub294 \uc5f0\uacb0\ub418\uc9c0\ub9cc \uac19\uc740 \ud56d\ubaa9\uc740 \uc544\ub2c8\ub2e4. \uc774 \ucc28\uc774\ub97c \uc54c\uba74 \ubcf4\ud638 \ud45c\uc2dc\ub97c \ubcf4\uace0 \uc740\ud589\uc5d0 \uad00\ud55c \ub2e4\ub978 \uc815\ubcf4\ub97c \uc804\ubd80 \ubb34\uc2dc\ud558\ub294 \ud310\ub2e8\uc744 \ud53c\ud560 \uc218 \uc788\ub2e4. \ubc18\ub300\ub85c \uc740\ud589\uc774 \uc5b4\ub824\uc6cc\uc84c\ub2e4\ub294 \uc18c\uc2dd\ub9cc \ub4e3\uace0 \ubcf4\ud638 \uc7a5\uce58\uc758 \uc874\uc7ac\ub97c \uc5c6\ub294 \uac83\uc73c\ub85c \ubcfc \ud544\uc694\ub3c4 \uc5c6\ub2e4. \ubb34\uc5c7\uc774 \uc704\ud5d8\ud558\uace0 \ubb34\uc5c7\uc744 \ub204\uac00 \ubcf4\uc644\ud558\ub294\uc9c0 \ub098\ub204\uc5b4 \ubcf4\ub294 \ud3b8\uc774 \uc815\ud655\ud558\ub2e4. \uad50\uc7ac\ub294 \ubbf8\uad6d\uc758 \uac00\uc785 \uc740\ud589\ub4e4\uc774 \uc608\uae08\ubcf4\ud5d8\ub8cc\ub97c \ub0b8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc608\uae08\uc790\ubcf4\ud638\ub97c \ub2e8\uc21c\ud788 \uc88b\uc740 \uc758\uc9c0\ub97c \uc801\uc740 \ubb38\uc7a5\uc73c\ub85c\ub9cc \uc6b4\uc601\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc190\uc2e4\uc744 \uac10\ub2f9\ud560 \uc900\ube44\uc640 \uc9c0\uae09\uc744 \uc2e4\ud589\ud560 \uccb4\uacc4\uac00 \uc788\uc5b4\uc57c \ud55c\ub2e4. \uc57d\uc18d\uc5d0\ub294 \uadf8\uac83\uc744 \ub4b7\ubc1b\uce68\ud560 \uad6c\uc870\uac00 \ud544\uc694\ud558\ub2e4. \ub610 \uc5b4\ub5a4 \uc740\ud589\uc774 \uc5b4\ub290 \uc815\ub3c4 \uc704\ud5d8\uc744 \uc9c0\ub294\uc9c0\uc5d0 \ub530\ub77c \ube44\uc6a9\uc744 \uc5b4\ub5bb\uac8c \ub098\ub20c\uc9c0\ub3c4 \uc9c8\ubb38\uc774 \ub41c\ub2e4. \uad50\uc7ac\ub294 \ubbf8\uad6d\uc774 \uacfc\uac70 \uc77c\ub960\uc801\uc778 \ubcf4\ud5d8\ub8cc\uc5d0\uc11c \uc704\ud5d8\uc744 \ubc18\uc601\ud558\ub294 \ubc29\uc2dd\uc73c\ub85c \ubc14\uafbc \uc0ac\ub840\ub97c \uc18c\uac1c\ud55c\ub2e4. \ubcf4\ud638\uc758 \uc874\uc7ac\uc640 \uadf8 \ube44\uc6a9\uc744 \ubc30\ubd84\ud558\ub294 \uc124\uacc4\ub294 \ud568\uaed8 \ubcf4\uc544\uc57c \ud558\ub294 \ubb38\uc81c\ub2e4. \ubcf4\ud638\uac00 \uc788\ub2e4\ub294 \uc774\uc720\ub85c \uc704\ud5d8\uc744 \ud06c\uac8c \uc838\ub3c4 \ub41c\ub2e4\uace0 \uc0dd\uac01\ud558\uba74 \uc81c\ub3c4\uc758 \ubd80\ub2f4\uc774 \ub298 \uc218 \uc788\ub2e4. \uad50\uc7ac\ub294 \uc608\uae08\ubcf4\ud5d8\uacfc \uc740\ud589\uc758 \uc704\ud5d8 \uc120\ud0dd \uc0ac\uc774\uc5d0 \uc774\ub7f0 \uc720\uc778 \ubb38\uc81c\uac00 \uc788\uc744 \uc218 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc190\uc2e4\uc744 \ubcf4\uc644\ud558\ub294 \uc77c\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uc608\ubc29\uc774 \ub05d\ub098\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub798\uc11c \uc740\ud589\uc744 \uac80\uc0ac\ud558\uace0 \uc7ac\ubb34 \uc0c1\ud0dc\uc640 \uc6b4\uc601\uc744 \uc0b4\ud53c\ub294 \uac10\ub3c5\ub3c4 \uc911\uc694\ud558\ub2e4. \uc0ac\ud6c4\uc758 \ubcf4\ud638\uc640 \uc0ac\uc804\uc758 \uad00\ub9ac\uac00 \uc11c\ub85c \ub2e4\ub978 \uc5ed\ud560\uc744 \ud55c\ub2e4. \uc18c\ud654\uae30\uac00 \uc788\ub2e4\uace0 \ud654\uc7ac \uc608\ubc29\uc744 \ud558\uc9c0 \uc54a\uc544\ub3c4 \ub418\ub294 \uac83\uc740 \uc544\ub2cc \uac83\ucc98\ub7fc, \uc548\uc804\ub9dd\uc740 \uc810\uac80\uc744 \ub300\uc2e0\ud558\ub294 \ub9d0\ubcf4\ub2e4 \uc810\uac80\uacfc \ud568\uaed8 \uc124\uacc4\ud560 \uc870\uac74\uc5d0 \uac00\uae5d\ub2e4. \uc740\ud589\uc5d0\uc11c \uac00\uc785\ud588\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc608\uae08\uc790\ubcf4\ud638 \ub300\uc0c1\uc774\ub77c\ub294 \uc0ac\uc2e4\uc740 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \uc5b4\ub5a4 \uae30\uad00\uacfc \uc0c1\ud488\uc774 \uc81c\ub3c4\uc758 \ubc94\uc704\uc5d0 \ub4e4\uc5b4\uac00\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\ub2e4. \ubcf4\ud638\ub77c\ub294 \ub2e8\uc5b4\ub9cc \uae30\uc5b5\ud558\uace0 \uad6c\uccb4\uc801\uc778 \uc57d\uc18d\uc758 \ubc94\uc704\ub97c \uc0dd\ub7b5\ud558\uba74 \uae30\ub300\uc640 \uc2e4\uc81c\uac00 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ud55c\ub3c4\uac00 \uc801\uc6a9\ub418\ub294 \uae30\uc900\uacfc \uc9c0\uae09 \ubc29\uc2dd\ub3c4 \uc81c\ub3c4\ub9c8\ub2e4 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uacc4\uc88c\ub97c \ub098\ub204\uac70\ub098 \uc774\ub984\ub9cc \ubc14\uafb8\uba74 \uc5b4\ub5bb\uac8c \ub41c\ub2e4\ub294 \uc2dd\uc758 \uac04\ub2e8\ud55c \uacb0\ub860\uc740 \uc5ec\uae30\uc11c \uc81c\uc2dc\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc774\ub7f0 \uc138\ubd80\ub294 \ud574\ub2f9 \ub098\ub77c\uc758 \uacf5\uc2dd \uc548\ub0b4\uc640 \uc0c1\ud488 \uc124\uba85\uc5d0\uc11c \ucd5c\uc2e0 \uae30\uc900\uc744 \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \uc6d0\ub9ac\ub97c \uc544\ub294 \uc77c\uacfc \uc801\uc6a9\uc744 \ud655\uc778\ud558\ub294 \uc77c\uc740 \ub2e4\ub978 \ub2e8\uacc4\ub2e4. \uc0ac\ub78c\ub9c8\ub2e4 \uae08\uc735\uc744 \uacf5\ubd80\ud560 \uc2dc\uac04\uacfc \uc815\ubcf4\uac00 \uac19\uc9c0 \uc54a\ub2e4. \uc6d4\uae09\uacfc \uc0dd\ud65c\ube44\ub97c \ub9e1\uae30\uae30 \uc704\ud574 \ubaa8\ub4e0 \uc740\ud589\uc758 \uc790\uc0b0\uc744 \uc9c1\uc811 \uc870\uc0ac\ud574\uc57c \ud55c\ub2e4\uba74 \uc77c\uc0c1\uc801\uc778 \uac70\ub798 \uc790\uccb4\uac00 \uc5b4\ub824\uc6cc\uc9c4\ub2e4. \uc81c\ub3c4\ub294 \uc774\ub7f0 \uc815\ubcf4\uc640 \uc804\ubb38\uc131\uc758 \ucc28\uc774\ub97c \uc5b4\ub290 \uc815\ub3c4 \ub2e4\ub8e8\ub294 \uc5ed\ud560\ub3c4 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ubb3c\ub860 \ubcf4\ud638\uac00 \uc788\ub2e4\uace0 \uc5b4\ub5a4 \uc120\ud0dd\ub3c4 \uc0b4\ud3b4\ubcfc \ud544\uc694\uac00 \uc5c6\uc5b4\uc9c4 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \uac1c\uc778\uc758 \uc8fc\uc758\ub9cc \uc694\uad6c\ud558\ub294 \ubc29\uc2dd\uacfc \uacf5\ud1b5\uc758 \uc548\uc804\uc7a5\uce58\ub97c \ub450\ub294 \ubc29\uc2dd\uc740 \ub2e4\ub974\ub2e4. \uc5b4\ub5a4 \uc704\ud5d8\uc744 \uac1c\uc778\uc5d0\uac8c \ub9e1\uae30\uace0 \uc5b4\ub5a4 \ubd80\ubd84\uc744 \uc81c\ub3c4\ub85c \ubcf4\uc644\ud560\uc9c0\ub294 \uae08\uc735\uc774 \uc0ac\ud68c\uc758 \uc57d\uc18d\uacfc \ub9cc\ub098\ub294 \uc9c0\uc810\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uc740\ud589 \ucc3d\uad6c\uc5d0\uc11c \uc124\uba85\uc744 \ub4e3\ub294 \uc77c\ubc18\uc801\uc778 \uc7a5\uba74\uc774\ub2e4. \uc2e4\uc81c \uae08\uc735\uae30\uad00\uc774\ub098 \uc608\uae08\uc790\ubcf4\ud638 \uc808\ucc28\ub97c \uc7ac\ud604\ud55c \uc0ac\uc9c4\uc740 \uc544\ub2c8\ub2e4. \uc774 \uc6d0\uace0\ub294 \ubcf4\ud638 \uc81c\ub3c4\uc758 \ubaa9\uc801\uc744 \uc774\ud574\ud558\ub294 \uc774\uc57c\uae30\uc774\uba70 \ud604\uc7ac\uc758 \ubc95\ub960\uacfc \ubcf4\ud638 \uae08\uc561\uc744 \uc778\uc99d\ud558\ub294 \uc790\ub8cc\ub85c \uc4f0\uc9c0 \uc54a\ub294\ub2e4. \uc608\uae08\uc790\ubcf4\ud638\ub97c \uc54c\uba74 \uc548\uc804\ud558\ub2e4\ub294 \ub9d0 \ub2e4\uc74c\uc5d0 \ub354 \uc815\ud655\ud55c \uc9c8\ubb38\uc744 \ud560 \uc218 \uc788\ub2e4. \uc5b4\ub5a4 \uae30\uad00\uc758 \uc5b4\ub5a4 \uc608\uae08\uc744 \ub204\uac00 \uc5b4\ub5a4 \ubc94\uc704\uc5d0\uc11c \ubcf4\ud638\ud558\ub294\uac00. 1930\ub144\ub300\uc758 \uacbd\ud5d8\uc5d0\uc11c \uc2dc\uc791\ub41c \uc774 \uc9c8\ubb38\uc740 \uc740\ud589\uc758 \uc57d\uc18d\uc744 \uac1c\uc778\uc758 \ubbff\uc74c\uc5d0\ub9cc \ub9e1\uae30\uc9c0 \uc54a\uace0 \uc81c\ub3c4\uc758 \uad6c\uc870\ub85c \ub4b7\ubc1b\uce68\ud558\ub824 \ud588\ub358 \uc774\uc720\ub97c \ubcf4\uc5ec \uc900\ub2e4."}, {"id": "diversification-baskets-and-common-weather", "title": "\ubd84\uc0b0\ud22c\uc790 \u2014 \ubc14\uad6c\ub2c8\ub97c \ub298\ub824\ub3c4 \uac19\uc740 \ube44\ub97c \ub9de\ub294\ub2e4\uba74", "summary": "\uac00\uc0c1\uc758 \ub450 \uc790\uc0b0\uacfc \uc815\uc6d0\uc758 \ube44\uc720\ub85c \uc704\ud5d8\uc758 \ubd84\uc0b0\uacfc \uacf5\ud1b5 \uc694\uc778\uc758 \ucc28\uc774\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "finance", "category_title": "Finance", "subcategory": "Investment", "url": "stories/diversification-baskets-and-common-weather/index.html", "image": "media/diversification-baskets-and-common-weather.png", "alt": "\uac19\uc740 \ud750\ub9b0 \ud558\ub298 \uc544\ub798 \uc5ec\ub7ec \uad6c\ud68d\uc5d0\uc11c \uc11c\ub85c \ub2e4\ub978 \uc791\ubb3c\uc744 \uac00\uafb8\ub294 \uc815\uc6d0\uc0ac\uc758 \uc0bd\ud654.", "text": "\ubd84\uc0b0\ud22c\uc790 \u2014 \ubc14\uad6c\ub2c8\ub97c \ub298\ub824\ub3c4 \uac19\uc740 \ube44\ub97c \ub9de\ub294\ub2e4\uba74 \uc774\ub984\uc758 \uac1c\uc218\ubcf4\ub2e4 \ud568\uaed8 \uc6c0\uc9c1\uc774\ub294 \uc774\uc720\ub97c \ubcf4\uae30 \uac00\uc0c1\uc758 \ub450 \uc790\uc0b0\uacfc \uc815\uc6d0\uc758 \ube44\uc720\ub85c \uc704\ud5d8\uc758 \ubd84\uc0b0\uacfc \uacf5\ud1b5 \uc694\uc778\uc758 \ucc28\uc774\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Investment \uae08\uc735 \ub2ec\uac40\uc744 \ud55c \ubc14\uad6c\ub2c8\uc5d0 \ub2f4\uc9c0 \ub9d0\ub77c\ub294 \ub9d0\uc744 \ud22c\uc790\uc5d0\uc11c\ub3c4 \uc790\uc8fc \ub4e3\ub294\ub2e4. \uadf8\ub798\uc11c \uc11c\ub85c \ub2e4\ub978 \uc774\ub984\uc758 \uc0c1\ud488\uc744 \uc5ec\ub7ec \uac1c \uace0\ub974\uba74 \ucda9\ubd84\ud560 \uac83\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \uadf8\ub7f0\ub370 \ubc14\uad6c\ub2c8\uac00 \ubaa8\ub450 \uac19\uc740 \uc120\ubc18\uc5d0 \ub193\uc5ec \uc788\uace0 \uadf8 \uc120\ubc18\uc774 \ubb34\ub108\uc9c4\ub2e4\uba74 \uc5b4\ub5bb\uac8c \ub420\uae4c. \uac1c\uc218\ub9cc \ub298\ub9b0\ub2e4\uace0 \ubaa8\ub4e0 \uc704\ud5d8\uc774 \ub098\ub258\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubd84\uc0b0\ud22c\uc790\ub294 \uc5ec\ub7ec \ub300\uc0c1\uc744 \uace0\ub974\ub294 \uc77c\uc5d0\uc11c \uc2dc\uc791\ud558\uc9c0\ub9cc \uadf8\uac83\ub4e4\uc774 \uc65c \ud568\uaed8 \uc624\ub974\ub0b4\ub9ac\ub294\uc9c0\ub3c4 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \ubcf5\uc7a1\ud55c \uc218\ud559 \ub300\uc2e0 \uac00\uc0c1\uc758 \ub450 \uc790\uc0b0\uacfc \uac19\uc740 \ub0a0\uc528\ub97c \uacaa\ub294 \uc815\uc6d0\uc744 \ub5a0\uc62c\ub9ac\uba74 \uc774 \ucc28\uc774\ub97c \uc774\ud574\ud558\uae30 \uc27d\ub2e4. \ubaa8\ub4e0 \ub3c8\uc744 \ud55c \ud68c\uc0ac\uc758 \uc8fc\uc2dd\uc5d0 \ub450\uba74 \uadf8 \ud68c\uc0ac\uac00 \uacaa\ub294 \uc77c\uc758 \uc601\ud5a5\uc744 \ud06c\uac8c \ubc1b\ub294\ub2e4. \uc2e4\uc801\uacfc \uacbd\uc601, \uc81c\ud488\uc758 \ubb38\uc81c\uc5d0 \ub530\ub77c \uacb0\uacfc\uac00 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc5ec\ub7ec \ud68c\uc0ac\uc5d0 \ub098\ub204\uba74 \ud55c \ud68c\uc0ac\uc5d0\uc11c \uc0dd\uae34 \uc77c\uc774 \uc804\uccb4\ub97c \uadf8\ub300\ub85c \uacb0\uc815\ud558\ub294 \uc815\ub3c4\ub97c \uc904\uc77c \uc218 \uc788\ub2e4. OpenStax\ub294 \uc774\ub7f0 \uc704\ud5d8 \uad00\ub9ac\ub97c \ubd84\uc0b0\uc758 \uae30\ubcf8 \ucde8\uc9c0\ub85c \uc124\uba85\ud55c\ub2e4. \ud558\uc9c0\ub9cc \ud68c\uc0ac \uc774\ub984\uc774 \ub2e4\ub974\ub2e4\uace0 \uc11c\ub85c \uad00\uacc4\uc5c6\ub294 \uc704\ud5d8\uc744 \uac00\uc9c4 \uac83\uc740 \uc544\ub2c8\ub2e4. \uac19\uc740 \uc5c5\uc885\uacfc \uac19\uc740 \uace0\uac1d, \uac19\uc740 \uc6d0\uc7ac\ub8cc\uc5d0 \uae30\ub300\ub294 \uae30\uc5c5\ub4e4\uc740 \uacf5\ud1b5\uc758 \uc870\uac74\uc744 \uacaa\uc744 \uc218 \uc788\ub2e4. \uccab\uac78\uc74c\uc740 \ub098\ub204\ub294 \uac83\uc774\uc9c0\ub9cc \ub2e4\uc74c \uc9c8\ubb38\uc740 \ubb34\uc5c7\uc744 \ub098\ub204\uc5c8\ub294\uc9c0\ub2e4. \ud55c \uae30\uac04\uc5d0 \uac00\uc0c1\uc758 \uc790\uc0b0 A\uac00 20% \uc624\ub974\uace0 B\uac00 20% \ub0b4\ub838\ub2e4\uace0 \ud574 \ubcf4\uc790. \ucc98\uc74c\uc5d0 \uac19\uc740 \uae08\uc561\uc744 \uc808\ubc18\uc529 \ud22c\uc790\ud588\uace0 \uc911\uac04 \uac70\ub798\uc640 \ube44\uc6a9\uc774 \uc5c6\ub2e4\uba74 \uc804\uccb4 \uc218\uc775\ub960\uc740 0%\ub2e4. \ud55c\ucabd\uc758 \ubcc0\ud654\uac00 \ub2e4\ub978 \ucabd\uc744 \uc0c1\uc1c4\ud558\ub294 \ub2e8\uc21c\ud55c \uc608\ub2e4. \uc774\uac83\uc740 \ub450 \uc790\uc0b0\uc744 \uace0\ub974\uba74 \uc5b8\uc81c\ub098 \uc6d0\uae08\uc774 \uc9c0\ucf1c\uc9c4\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \uac19\uc740 \uae30\uac04\uc5d0 \ub458 \ub2e4 \ud558\ub77d\ud558\uba74 \uc804\uccb4\ub3c4 \ud558\ub77d\ud55c\ub2e4. \ubc18\uc529 \ub2f4\uc558\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ubbf8\ub798\uc758 \uacb0\uacfc\ub97c \ubcf4\uc7a5\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc608\uc2dc\uc758 \uc22b\uc790\ub294 \uacc4\uc0b0\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uac00\uc0c1 \uac12\uc774\uba70 \uc2e4\uc81c \uc0c1\ud488\uc758 \uc608\uc0c1 \uc218\uc775\ub960\uc774 \uc544\ub2c8\ub2e4. \uad50\uc7ac\ub294 \uc5ec\ub7ec \uc790\uc0b0\uc758 \uc704\ud5d8\uc774 \uac01\uac01\uc758 \ubcc0\ub3d9 \ud3ed\ubfd0 \uc544\ub2c8\ub77c \uc11c\ub85c \uc5b4\ub5bb\uac8c \uc6c0\uc9c1\uc774\ub294\uc9c0\uc5d0\ub3c4 \uc601\ud5a5\uc744 \ubc1b\ub294\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud55c\ucabd\uc774 \uc5b4\ub824\uc6b8 \ub54c \ub2e4\ub978 \ucabd\ub3c4 \uac19\uc740 \uc774\uc720\ub85c \uc5b4\ub824\uc6cc\uc9c0\ub294\uc9c0, \ubcc0\ud654\uc758 \uc2dc\uc810\uc774 \ub2e4\ub978\uc9c0 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc774\ub7f0 \uad00\uacc4\ub97c \ud1b5\uacc4\uc5d0\uc11c\ub294 \uc0c1\uad00\uad00\uacc4\ub85c \ub2e4\ub8ec\ub2e4. \uc22b\uc790 \uacf5\uc2dd\uc744 \uc678\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \ud575\uc2ec\uc740 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \ub450 \uc2dd\ub2f9\uc774 \uc11c\ub85c \ub2e4\ub978 \uc774\ub984\uc774\uc5b4\ub3c4 \uac19\uc740 \uac74\ubb3c\uc758 \ubc29\ubb38\uac1d\uc5d0\uac8c \uae30\ub300\uace0 \uc788\ub2e4\uba74 \uadf8 \uac74\ubb3c\uc774 \ubb38\uc744 \ub2eb\uc744 \ub54c \ud568\uaed8 \uc601\ud5a5\uc744 \ubc1b\uc744 \uc218 \uc788\ub2e4. \uc774\ub294 \ud22c\uc790 \uc0c1\ud488\uc744 \uc9c1\uc811 \ud3c9\uac00\ud55c \uc0ac\ub840\uac00 \uc544\ub2c8\ub77c \uacf5\ud1b5 \uc694\uc778\uc744 \ub5a0\uc62c\ub9ac\ub294 \ube44\uc720\ub2e4. \uad50\uc7ac\ub294 \uc11c\ub85c \ub2e4\ub978 \ud56d\uacf5\uc0ac\ub3c4 \uc5ec\ud589 \uc218\uc694\uc640 \uc5f0\ub8cc\ube44 \uac19\uc740 \uc870\uac74\uc744 \ud568\uaed8 \uacaa\uc744 \uc218 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud55c \ud68c\uc0ac\ub9cc\uc758 \uc2dc\uc2a4\ud15c \ubb38\uc81c\uc640 \uc5c5\uacc4 \uc804\uccb4\uc758 \uc218\uc694 \uac10\uc18c\ub294 \ub2e4\ub978 \ubc94\uc704\uc758 \uc0ac\uac74\uc774\ub2e4. \uc5ec\ub7ec \ud56d\uacf5\uc0ac\uc5d0 \ub098\ub204\uba74 \uccab \ubc88\uc9f8\uc5d0 \ub300\ud55c \ub178\ucd9c\uc740 \ub2ec\ub77c\uc838\ub3c4 \ub450 \ubc88\uc9f8\ub294 \ub0a8\uc744 \uc218 \uc788\ub2e4. \uc774 \uad6c\ubd84\uc740 \uc720\uba85\ud55c \uae30\uc5c5\uc758 \uc218\ub97c \uc138\ub294 \uc77c\ubcf4\ub2e4 \uc720\uc6a9\ud560 \ub54c\uac00 \uc788\ub2e4. \ubb34\uc5c7\uc744 \uc0dd\uc0b0\ud558\uace0 \uc5b4\ub514\uc5d0\uc11c \ubc8c\uba70 \uc5b4\ub5a4 \ube44\uc6a9\uc5d0 \uae30\ub300\ub294\uc9c0 \ubb3c\uc5b4\ubcf4\uac8c \ub41c\ub2e4. \ubb3c\ub860 \uc774 \uae00\uc740 \ud2b9\uc815 \uc5c5\uc885\uc744 \uc88b\uac70\ub098 \ub098\uc058\ub2e4\uace0 \ucd94\ucc9c\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc774\ub984\ubcf4\ub2e4 \uc791\ub3d9 \uc870\uac74\uc744 \uc0b4\ud3b4\ubcf4\uc790\ub294 \uc124\uba85\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\uc5d0\ub294 \uc11c\ub85c \ub2e4\ub978 \uc791\ubb3c\uc744 \uae30\ub974\ub294 \uc5ec\ub7ec \uad6c\ud68d\uc774 \uc788\ub2e4. \ud55c \uc791\ubb3c\uc5d0\ub9cc \uc0dd\uae30\ub294 \ubb38\uc81c\uc640 \uc815\uc6d0 \uc804\uccb4\uc5d0 \ub0b4\ub9ac\ub294 \ube44\ub294 \ub2e4\ub974\ub2e4. \uc791\ubb3c\uc744 \ub2e4\uc591\ud558\uac8c \uc2ec\uc5b4\ub3c4 \uac19\uc740 \ud558\ub298 \uc544\ub798 \uc788\ub2e4\ub294 \uc870\uac74\uc740 \ub0a8\ub294\ub2e4. \ubd84\uc0b0\uc758 \uc5ed\ud560\uacfc \ud55c\uacc4\ub97c \ud568\uaed8 \ub5a0\uc62c\ub9ac\uae30 \uc704\ud55c \ube44\uc720\ub2e4. \uc2e4\uc81c \uc790\uc0b0\uc740 \uc2dd\ubb3c\uacfc \ub611\uac19\uc774 \uc6c0\uc9c1\uc774\uc9c0 \uc54a\ub294\ub2e4. \ube44\uc720\ub294 \uac1c\ub150\uc744 \uc774\ud574\ud558\ub294 \ub3c4\uad6c\uc774\uc9c0 \uc218\uc775\uc744 \uacc4\uc0b0\ud558\ub294 \ubaa8\ud615\uc740 \uc544\ub2c8\ub2e4. \uae08\uc735\uc2dc\uc7a5\uc5d0\ub3c4 \ub113\uac8c \uc791\uc6a9\ud558\ub294 \ubcc0\ud654\uac00 \uc788\uc5b4 \ubaa8\ub4e0 \uac1c\ubcc4 \uc704\ud5d8\uc744 \uc5c6\uc560\ub4ef \uc81c\uac70\ud560 \uc218\ub294 \uc5c6\ub2e4\ub294 \uc810\ub9cc \uac00\uc838\uc624\uba74 \ucda9\ubd84\ud558\ub2e4. \uacfc\uac70\uc5d0 \ub450 \uc790\uc0b0\uc774 \uc11c\ub85c \ub2e4\ub974\uac8c \uc6c0\uc9c1\uc600\ub2e4\ub294 \uae30\ub85d\uc740 \uc720\uc6a9\ud55c \uc790\ub8cc\ub2e4. \ud558\uc9c0\ub9cc \uadf8 \uad00\uacc4\uac00 \ubbf8\ub798\uc5d0\ub3c4 \uace0\uc815\ub418\uc5b4 \uc788\ub2e4\uace0 \ubcf4\uc7a5\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uae30\uc5c5\uc758 \uc0ac\uc5c5\uacfc \uc2dc\uc7a5\uc758 \uc870\uac74\uc774 \ubc14\ub014 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uacfc\uac70\uc758 \uad00\ucc30\uc744 \uc77d\ub294 \uc77c\uacfc \ubbf8\ub798\ub97c \ud655\uc815\ud558\ub294 \uc77c\uc740 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \uc88b\uc558\ub358 \ud55c \uc2dc\uae30\ub9cc \uace8\ub77c \ubcf4\uc5ec \uc8fc\uba74 \uc804\uccb4 \uc778\uc0c1\uc774 \ub2ec\ub77c\uc9c8 \uc218\ub3c4 \uc788\ub2e4. \uae30\uac04\uacfc \ube44\uc6a9, \ube44\uad50 \ub300\uc0c1\uc744 \ud568\uaed8 \uc0b4\ud53c\ub294 \uc774\uc720\ub2e4. \ubd84\uc0b0\uc774\ub77c\ub294 \ub2e8\uc5b4\uac00 \ub4e4\uc5b4 \uc788\ub2e4\uace0 \uc704\ud5d8 \uc124\uba85\uc744 \uac74\ub108\ub6f0\uc5b4\ub3c4 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \uad00\uacc4\ub97c \uc5b4\ub5a4 \uc790\ub8cc\ub85c \ud310\ub2e8\ud588\ub294\uc9c0\uae4c\uc9c0 \ubb3c\uc5b4\ubcf4\uba74 \uc88b\ub2e4. \uc5ec\ub7ec \ubb36\uc74c\uc744 \uace8\ub790\ub294\ub370 \uac01\uac01\uc5d0 \uac19\uc740 \ud68c\uc0ac\ub4e4\uc774 \ub9ce\uc774 \ub4e4\uc5b4 \uc788\uc744 \uc218\ub3c4 \uc788\ub2e4. \uc774\ub984\uc758 \uc218\uc640 \uc2e4\uc81c\ub85c \ub098\ub204\uc5b4\uc9c4 \ud22c\uc790 \ub300\uc0c1\uc758 \uc218\ub294 \uac19\uc9c0 \uc54a\uc744 \uc218 \uc788\ub294 \uac83\uc774\ub2e4. \ubb34\uc5c7\uc744 \ub2f4\uace0 \uc788\ub294\uc9c0 \ubaa8\ub974\uba74 \uac89\uc73c\ub85c\ub294 \ub2e4\uc591\ud55c \uc120\ud0dd\uc774 \uc548\ucabd\uc5d0\uc11c\ub294 \ube44\uc2b7\ud55c \ub178\ucd9c\uc774 \ub420 \uc218 \uc788\ub2e4. \ub530\ub77c\uc11c \ubd84\uc0b0\uc744 \uc774\ud574\ud558\ub294 \uc9c8\ubb38\uc5d0\ub294 \uad6c\uc131\uacfc \ube44\uc911\uc774 \ub4e4\uc5b4\uac04\ub2e4. \uc5b4\ub5a4 \ub300\uc0c1\uc774 \uc5bc\ub9c8\ub098 \ud070 \uc790\ub9ac\ub97c \ucc28\uc9c0\ud558\ub294\uc9c0, \uacf5\ud1b5 \uc694\uc778\uc740 \ubb34\uc5c7\uc778\uc9c0 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc774\ub294 \ud2b9\uc815 \uc0c1\ud488\uc758 \uc801\ud569\uc131\uc744 \ud3c9\uac00\ud558\ub294 \uc548\ub0b4\uac00 \uc544\ub2c8\ub77c \uc5ec\ub7ec \uc790\uc0b0\uc744 \ud568\uaed8 \ubcfc \ub54c\uc758 \uae30\ubcf8\uc801\uc778 \ub3c5\ud574 \ubc29\ubc95\uc774\ub2e4. \ubd84\uc0b0\uc758 \uc758\ubbf8\ub294 \uc5b4\ub5a4 \uc190\uc2e4\ub3c4 \uc77c\uc5b4\ub098\uc9c0 \uc54a\uac8c \ud558\ub294 \ub9c8\ubc95\uc5d0 \uc788\uc9c0 \uc54a\ub2e4. \ud55c \ub300\uc0c1\uacfc \ud55c \uc885\ub958\uc758 \uc0ac\uac74\uc5d0 \uae30\ub300\ub294 \uc815\ub3c4\ub97c \uc870\uc815\ud558\ub294 \ub370 \uc788\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc704\ud5d8\uc744 \ud568\uaed8 \ubcf4\uba70 \uc804\uccb4\uac00 \uc5b4\ub5a4 \uc601\ud5a5\uc744 \ubc1b\uc744 \uc218 \uc788\ub294\uc9c0 \uc0dd\uac01\ud558\ub294 \ubc29\uc2dd\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \ub2e4\uc591\ud55c \uc774\ub984\uc774 \uc801\ud78c \ud22c\uc790 \uc124\uba85\uc744 \ub9cc\ub098\uba74 \ubc14\uad6c\ub2c8\uc758 \uac1c\uc218\ub9cc \ubcf4\uc9c0 \ub9d0\uace0 \uadf8 \ubc14\uad6c\ub2c8\ub4e4\uc774 \uc5b4\ub514\uc5d0 \ub193\uc600\ub294\uc9c0\ub3c4 \ub5a0\uc62c\ub824 \ubcf4\uc790. \ub2e4\ub978 \uc791\ubb3c\ub3c4 \uac19\uc740 \ub0a0\uc528\ub97c \uacaa\ub294\ub2e4. \ubd84\uc0b0\uc744 \ubc30\uc6b4\ub2e4\ub294 \uac83\uc740 \uc548\uc804\uc774\ub77c\ub294 \uc9e7\uc740 \ub9d0\ubcf4\ub2e4 \ubb34\uc5c7\uc774 \ub098\ub258\uc5c8\uace0 \ubb34\uc5c7\uc774 \uc5ec\uc804\ud788 \ud568\uaed8 \uc6c0\uc9c1\uc774\ub294\uc9c0 \ubb3b\ub294 \ub208\uc744 \uc5bb\ub294 \uc77c\uc774\ub2e4."}, {"id": "inflation-price-tag-and-purchasing-power", "title": "\ubb3c\uac00 \u2014 \uc9c0\uac11 \uc18d \ub3c8\uc740 \uac19\uc740\ub370 \uc65c \ub35c \uc0b4 \uc218 \uc788\uc744\uae4c", "summary": "\ube75\uac12\uacfc \uac00\uc0c1\uc758 \uc0dd\ud65c\ube44 \uc608\ub85c \ubb3c\uac00 \uc218\uc900\u00b7\uc0c1\uc2b9\ub960\u00b7\uad6c\ub9e4\ub825\uc758 \ucc28\uc774\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "finance", "category_title": "Finance", "subcategory": "Money", "url": "stories/inflation-price-tag-and-purchasing-power/index.html", "image": "media/inflation-price-tag-and-purchasing-power.png", "alt": "\ub3d9\ub124 \uac00\uac8c\uc5d0\uc11c \ube75\uacfc \uacfc\uc77c\uc774 \ub4e0 \uc7a5\ubc14\uad6c\ub2c8\ub97c \ub193\uace0 \uc9c0\uac11\uc744 \uc0b4\ud53c\ub294 \uc0ac\ub78c\uc758 \uc0bd\ud654.", "text": "\ubb3c\uac00 \u2014 \uc9c0\uac11 \uc18d \ub3c8\uc740 \uac19\uc740\ub370 \uc65c \ub35c \uc0b4 \uc218 \uc788\uc744\uae4c \uac00\uaca9\ud45c \ud55c \uc7a5\uacfc \uc7a5\ubc14\uad6c\ub2c8 \uc804\uccb4\ub97c \ub098\ub204\uc5b4 \ubcf4\uae30 \ube75\uac12\uacfc \uac00\uc0c1\uc758 \uc0dd\ud65c\ube44 \uc608\ub85c \ubb3c\uac00 \uc218\uc900\u00b7\uc0c1\uc2b9\ub960\u00b7\uad6c\ub9e4\ub825\uc758 \ucc28\uc774\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Money \uae08\uc735 \ub3d9\ub124 \uac00\uac8c\uc5d0\uc11c \ub298 \uc0ac\ub358 \ube75\uc744 \uace0\ub978\ub2e4. \ubd09\ud22c\ub294 \ube44\uc2b7\ud55c\ub370 \uacc4\uc0b0\ub300\uc5d0\uc11c \ub0b4\ub294 \ub3c8\uc774 \ub298\uc5c8\ub2e4. \uc608\uc804\uacfc \uac19\uc740 \uc9c0\ud3d0\ub97c \uaebc\ub0c8\uc9c0\ub9cc \uc0b4 \uc218 \uc788\ub294 \uac83\uc774 \uc904\uc5b4\ub4e0 \ub290\ub08c\uc774\ub2e4. \ub3c8\uc5d0 \uc801\ud78c \uc22b\uc790\uc640 \uadf8 \ub3c8\uc73c\ub85c \ud560 \uc218 \uc788\ub294 \uc77c\uc740 \ud56d\uc0c1 \uac19\uc740 \uc18d\ub3c4\ub85c \uc6c0\uc9c1\uc774\uc9c0 \uc54a\ub294\ub2e4. \ubb3c\uac00\ub294 \ubc14\ub85c \uc774 \uac04\uaca9\uc744 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ub2e4\ub9cc \ube75 \ud558\ub098\uc758 \uac00\uaca9 \ubcc0\ud654\uc640 \uacbd\uc81c \uc804\uccb4\uc758 \ubb3c\uac00 \uc0c1\uc2b9\uc740 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \uc624\ub298\uc758 \uc2e4\uc81c \ud1b5\uacc4\ub97c \uc608\uce21\ud558\uae30\ubcf4\ub2e4 \uc7a5\ubc14\uad6c\ub2c8\ub97c \ud568\uaed8 \ub5a0\uc62c\ub9ac\uba74 \ub274\uc2a4\uc5d0\uc11c \ub4e3\ub294 \ubb3c\uac00\uc640 \uc0dd\ud65c\uc5d0\uc11c \ub290\ub07c\ub294 \ubb3c\uac00\uc758 \uad00\uacc4\uac00 \uc870\uae08 \ubd84\uba85\ud574\uc9c4\ub2e4. \uac00\uc0c1\uc758 \ube75\uac12\uc774 1,000\uc6d0\uc5d0\uc11c 1,100\uc6d0\uc774 \ub418\uc5c8\ub2e4\uba74 \uadf8 \ube75\uc758 \uac00\uaca9\uc740 10% \uc62c\ub790\ub2e4. \uadf8\ub7ec\ub098 \uc774 \uc22b\uc790\ub97c \uadf8\ub300\ub85c \ub098\ub77c \uc804\uccb4\uc758 \ubb3c\uac00 \uc0c1\uc2b9\ub960\uc774\ub77c\uace0 \ubd80\ub97c \uc218\ub294 \uc5c6\ub2e4. \ub2e4\ub978 \uc0c1\ud488\uacfc \uc11c\ube44\uc2a4\uc758 \uac00\uaca9\uc740 \ub2e4\ub978 \ubc29\ud5a5\uacfc \uc18d\ub3c4\ub85c \uc6c0\uc9c1\uc600\uc744 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. OpenStax\ub294 \ubb3c\uac00\ub97c \ubcfc \ub54c \ud55c \ud488\ubaa9\ubcf4\ub2e4 \uc5ec\ub7ec \uc0c1\ud488\uacfc \uc11c\ube44\uc2a4\uc758 \ubb36\uc74c\uc744 \uc0b4\ud540\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ubb34\uc5c7\uc744 \uc5bc\ub9c8\ub098 \ub2f4\uc744\uc9c0 \uc815\ud55c \uc7a5\ubc14\uad6c\ub2c8\ub97c \ube44\uad50\ud558\ub294 \ubc29\uc2dd\uc774\ub2e4. \uc2e4\uc81c \ubb3c\uac00\uc9c0\uc218\uc5d0\ub294 \uc870\uc0ac \ub300\uc0c1\uacfc \uac00\uc911\uce58 \ub4f1 \ub354 \ub9ce\uc740 \uc808\ucc28\uac00 \ub4e4\uc5b4\uac04\ub2e4. \ube75\uac12\uc740 \uccb4\uac10\uc758 \ucd9c\ubc1c\uc810\uc774\uc9c0\ub9cc \uc804\uccb4\ub97c \ub300\uc2e0\ud558\ub294 \uc22b\uc790\ub294 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \uc7a5\ubc14\uad6c\ub2c8\ub97c \uc791\ub144\uc5d0 10\ub9cc \uc6d0\uc73c\ub85c \uc0c0\ub294\ub370 \uc62c\ud574\ub294 11\ub9cc \uc6d0\uc774 \ud544\uc694\ud558\ub2e4\uace0 \uac00\uc815\ud558\uc790. \uc9c0\uac11\uc5d0 \uc788\ub294 10\ub9cc \uc6d0\uc740 \uc22b\uc790\uac00 \uc904\uc9c0 \uc54a\uc558\ub2e4. \ud558\uc9c0\ub9cc \uc774\uc804\uacfc \uac19\uc740 \ubb36\uc74c\uc744 \uc0ac\uae30\uc5d0\ub294 \ubd80\uc871\ud574\uc84c\ub2e4. \ud654\ud3d0\uc758 \uad6c\ub9e4\ub825\uc774 \ub2ec\ub77c\uc84c\ub2e4\uace0 \ub9d0\ud560 \uc218 \uc788\ub294 \uc0c1\ud669\uc774\ub2e4. \uc774\uac83\uc740 \ubb3c\uac00\uac00 \uc624\ub974\uba74 \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \ub611\uac19\uc740 \uae08\uc561\uc744 \uc783\ub294\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uac01\uc790 \uac00\uc9c4 \uc790\uc0b0\uacfc \ubd80\ucc44, \uc218\uc785\uc758 \ubcc0\ud654\ub3c4 \uc601\ud5a5\uc744 \uc900\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc6b0\uc120 \uac19\uc740 \uae08\uc561\uc73c\ub85c \uac19\uc740 \ubb36\uc74c\uc744 \uc0b4 \uc218 \uc788\ub294\uc9c0\ub77c\ub294 \uc9c8\ubb38\ub9cc \ubd84\ub9ac\ud574 \ubcf4\uc790. \uc7ac\uc0b0\uc758 \uc22b\uc790\ub97c \ubcf4\ub294 \uc77c\uacfc \uc0dd\ud65c\uc758 \uc120\ud0dd \ubc94\uc704\ub97c \ubcf4\ub294 \uc77c\uc740 \uc11c\ub85c \uc5f0\uacb0\ub418\uba74\uc11c\ub3c4 \ub2e4\ub974\ub2e4. \uc774\ubc88\uc5d0\ub294 \uac19\uc740 \uac00\uc0c1\uc758 \uc0dd\ud65c\ube44 \ubb36\uc74c\uc774 10\ub9cc \uc6d0\uc5d0\uc11c 11\ub9cc \uc6d0\uc73c\ub85c \uc624\ub974\ub294 \ub3d9\uc548, \uadf8\uc5d0 \uc4f8 \uc218 \uc788\ub294 \ub3c8\uc740 10\ub9cc \uc6d0\uc5d0\uc11c 10\ub9cc 5,000\uc6d0\uc73c\ub85c \ub298\uc5c8\ub2e4\uace0 \ud574 \ubcf4\uc790. \ub3c8\uc740 5% \ub298\uc5c8\uc9c0\ub9cc \uc7a5\ubc14\uad6c\ub2c8\uc758 \uac00\uaca9\uc740 10% \uc62c\ub790\ub2e4. \ub298\uc5c8\ub2e4\ub294 \ub9d0\ub9cc\uc73c\ub85c \uc0b4\ub9bc\uc774 \ub354 \ub109\ub109\ud574\uc84c\ub2e4\uace0 \ud560 \uc218\ub294 \uc5c6\ub2e4. \ube44\uc728\uc744 \ube44\uad50\ud558\uba74 \uc0c8 \uc608\uc0b0\uc740 \uc0c8 \uc7a5\ubc14\uad6c\ub2c8 \uac12\uc758 \uc57d 95.5%\ub2e4. \uc774\uc804\ubcf4\ub2e4 \uad6c\ub9e4 \uac00\ub2a5\ud55c \uc591\uc774 \uc57d 4.5% \uc904\uc5b4\ub4e0 \uc148\uc774\ub2e4. \ubaa8\ub4e0 \ubb3c\uac74\uc744 \uac19\uc740 \ube44\uc728\ub85c \uc870\uae08\uc529 \uc0b4 \uc218 \uc788\ub2e4\ub294 \ub2e8\uc21c\ud55c \uacc4\uc0b0\uc774\uba70 \uc2e4\uc81c \uac00\uacc4\uc758 \uc18c\ube44\ub97c \uc7ac\ud604\ud55c \uac12\uc740 \uc544\ub2c8\ub2e4. \uc22b\uc790\uac00 \ub298\uc5b4\ub09c \ubcc0\ud654\uc640 \ubb3c\uac00\ub97c \uac10\uc548\ud55c \ubcc0\ud654\ub97c \ub098\ub204\ub294 \uc608\ub2e4. \uc544\uc774\ub97c \ud0a4\uc6b0\ub294 \uac00\uc815\uacfc \ud63c\uc790 \uc0ac\ub294 \uc0ac\ub78c, \uc758\ub8cc\ube44 \uc9c0\ucd9c\uc774 \ud070 \uc0ac\ub78c\uc758 \uc18c\ube44 \uad6c\uc131\uc740 \ub2e4\ub974\ub2e4. \uac19\uc740 \ubb3c\uac00 \ud1b5\uacc4\ub97c \ubcf4\uba74\uc11c\ub3c4 \uccb4\uac10\uc774 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uad50\uc7ac\ub3c4 \uc5f0\ub839\uacfc \uc9c0\uc5ed, \uc8fc\uac70\uc640 \uc758\ub8cc\ube44\uc758 \ube44\uc911\uc5d0 \ub530\ub77c \uacbd\ud5d8\ud558\ub294 \ubd80\ub2f4\uc774 \ub2ec\ub77c\uc9c4\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uacf5\uc2dd \ud1b5\uacc4\uac00 \ud3c9\uade0\uc801\uc778 \ubcc0\ud654\ub97c \ubcf4\uc5ec \uc900\ub2e4\uace0 \uac1c\uc778\uc758 \uacbd\ud5d8\uc774 \ubaa8\ub450 \uadf8 \uc22b\uc790\uc640 \uac19\uc544\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubc18\ub300\ub85c \ub0b4 \uc9c0\ucd9c\uc774 \ud06c\uac8c \ub298\uc5c8\ub2e4\uace0 \ud1b5\uacc4\uac00 \uace7\ubc14\ub85c \ud2c0\ub838\ub2e4\uace0 \ud560 \uc218\ub3c4 \uc5c6\ub2e4. \uc11c\ub85c \ub2e4\ub978 \ubc94\uc704\uc758 \uc9c8\ubb38\uc5d0 \ub2f5\ud558\ub294 \uc790\ub8cc\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \ubb34\uc5c7\uc744 \ub2f4\uc740 \uc7a5\ubc14\uad6c\ub2c8\uc778\uc9c0\ubd80\ud130 \ud655\uc778\ud558\uba74 \ucc28\uc774\ub97c \uc774\ud574\ud558\uae30 \uc27d\ub2e4. \ubb3c\uac00\uac00 10% \uc624\ub974\ub358 \uc0c1\ud669\uc5d0\uc11c \ub2e4\uc74c\uc5d0\ub294 3% \uc624\ub978\ub2e4\uace0 \ud574 \ubcf4\uc790. \uc624\ub974\ub294 \uc18d\ub3c4\ub294 \ub290\ub824\uc84c\uc9c0\ub9cc \uac00\uaca9 \uc218\uc900\uc774 \uc608\uc804\uc73c\ub85c \ub3cc\uc544\uac04 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub354 \ub192\uc544\uc9c4 \uac00\uaca9 \uc704\uc5d0\uc11c \ub2e4\uc2dc \uc62c\ub77c\uac00\ub294 \uacbd\uc6b0\ub2e4. \uc0c1\uc2b9\ub960\uacfc \uac00\uaca9 \uc218\uc900\uc744 \uc11e\uc73c\uba74 \ub274\uc2a4\uac00 \uc0dd\ud65c\uacfc \uc804\ud600 \ub2e4\ub978 \ub9d0\uc744 \ud558\ub294 \uac83\ucc98\ub7fc \ub4e4\ub9b0\ub2e4. \uac00\ub839 \ucc98\uc74c 100\uc774\ub358 \uc7a5\ubc14\uad6c\ub2c8 \uac12\uc740 10% \uc0c1\uc2b9 \ud6c4 110\uc774 \ub418\uace0, \uadf8 \ub4a4 3% \uc0c1\uc2b9\ud558\uba74 113.3\uc774 \ub41c\ub2e4. \ub450 \uae30\uac04\uc758 \uc0c1\uc2b9\ub960\uc744 \ub2e8\uc21c\ud788 \ub354\ud55c 13\uc774 \uc544\ub2c8\ub77c \ubc14\ub010 \uae30\uc900\uc5d0\uc11c \uacc4\uc0b0\ud55c\ub2e4. \uc774 \uc5ed\uc2dc \uac00\uc0c1 \uc608\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \uc18d\ub3c4\uc758 \ub454\ud654\uc640 \uac00\uaca9\uc758 \ud558\ub77d\uc744 \uad6c\ubd84\ud558\ub294 \uc77c\uc774\ub2e4. \uac19\uc740 \uae08\uc561\uc744 \ub098\uc911\uc5d0 \ubc1b\uac70\ub098 \uac1a\ub294 \uc57d\uc18d\uc5d0\ub294 \uadf8\ub54c \ub3c8\uc758 \uad6c\ub9e4\ub825\uc774 \uc5b4\ub5a4\uc9c0\uac00 \uc601\ud5a5\uc744 \uc900\ub2e4. \uad50\uc7ac\ub294 \uc608\uc0c1\ud55c \ubb3c\uac00\uc640 \uc2e4\uc81c \ubb3c\uac00\uc758 \ucc28\uc774\uac00 \ube4c\ub824\uc900 \uc0ac\ub78c\uacfc \ube4c\ub9b0 \uc0ac\ub78c\uc5d0\uac8c \ub2e4\ub974\uac8c \uc791\uc6a9\ud560 \uc218 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub3c8\uc744 \uac70\ub798\ud55c\ub2e4\ub294 \uac83\uc740 \uc2dc\uac04\uc744 \ud568\uaed8 \uac70\ub798\ud558\ub294 \uc77c\uc774\uae30\ub3c4 \ud558\ub2e4. \ub2e4\ub9cc \uc774 \uc124\uba85\ub9cc\uc73c\ub85c \ubb3c\uac00\uac00 \uc624\ub974\uba74 \ube5a\uc744 \ub0b4\ub294 \ud3b8\uc774 \uc5b8\uc81c\ub098 \uc720\ub9ac\ud558\ub2e4\uace0 \uacb0\ub860 \ub0bc \uc218\ub294 \uc5c6\ub2e4. \uae08\ub9ac\uc758 \ubc29\uc2dd\uacfc \uc18c\ub4dd, \uc0c1\ud658 \uc870\uac74\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uc5ec\uae30\uc11c\ub294 \ub204\uad6c\uc5d0\uac8c\ub098 \uac19\uc740 \uc190\uc775\uc774\ub77c\ub294 \ud45c\ud604\uc744 \ud53c\ud558\uace0, \ubbf8\ub798\uc758 \uace0\uc815\ub41c \uae08\uc561\uc774 \ud604\uc7ac\uc640 \uac19\uc740 \uc0dd\ud65c\uc758 \ud798\uc744 \uac16\ub294\uc9c0 \ubb3b\ub294 \uc815\ub3c4\ub85c \uc774\ud574\ud558\uba74 \uc88b\ub2e4. \uc61b\ub0a0\uc758 \ube75\uac12\uc774\ub098 \uc9d1\uac12\uc744 \ubcf4\uba74 \uc9c0\uae08\ubcf4\ub2e4 \uc544\uc8fc \ub0ae\uc544 \ubcf4\uc77c \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \ub2f9\uc2dc\uc758 \uc784\uae08\uacfc \uad6c\ub9e4\ub825, \uc0c1\ud488\uc758 \ud488\uc9c8\uacfc \uad6c\uc131\uc774 \ub2e4\ub974\uba74 \uc22b\uc790\ub9cc\uc73c\ub85c \uc0dd\ud65c\uc774 \ub354 \uc26c\uc6e0\ub2e4\uace0 \ud3c9\uac00\ud558\uae30 \uc5b4\ub835\ub2e4. \ub3c8\uc758 \ub2e8\uc704\uac00 \uac19\uc544\ub3c4 \uadf8 \ub2e8\uc704\uac00 \ub193\uc778 \uc0dd\ud65c \uc870\uac74\uc740 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \ub3d9\ub124 \uac00\uac8c\uc5d0\uc11c \uc7a5\uc744 \ubcf4\ub294 \uc0c1\uc0c1 \uc18d \uc7a5\uba74\uc774\ub2e4. \uc2e4\uc81c \uc5b4\ub290 \ud574\uc758 \ubb3c\uac00 \uc870\uc0ac\ub098 \ud2b9\uc815 \uac00\uc815\uc758 \uc18c\ube44\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uc0ac\uc9c4\uc740 \uc544\ub2c8\ub2e4. \uc774 \uae00\uc758 \uacc4\uc0b0\ub3c4 \uac00\uc0c1\uc758 \uac12\uc73c\ub85c \uc6d0\ub9ac\ub97c \uc124\uba85\ud588\uc73c\uba70 \ud604\uc7ac\uc758 \ud55c\uad6d \ubb3c\uac00 \uc218\uce58\ub97c \ub300\uc2e0\ud558\uc9c0 \uc54a\ub294\ub2e4. \ubb3c\uac00\ub97c \uc774\ud574\ud558\ub294 \uccab\uac78\uc74c\uc740 \ubcf5\uc7a1\ud55c \uacf5\uc2dd\uc744 \uc678\uc6b0\ub294 \uc77c\uc774 \uc544\ub2c8\ub2e4. \ub3c8\uc758 \uae08\uc561\uacfc \uadf8 \ub3c8\uc73c\ub85c \uc0b4 \uc218 \uc788\ub294 \uac83\uc744 \ud568\uaed8 \ubcf4\ub294 \uc77c\uc774\ub2e4. \ud55c \ud488\ubaa9\uacfc \uc804\uccb4 \ubb36\uc74c, \uac00\uaca9 \uc218\uc900\uacfc \uc0c1\uc2b9 \uc18d\ub3c4\ub97c \ub098\ub204\uba74 \uc775\uc219\ud55c \uacbd\uc81c \ub274\uc2a4\uac00 \uc870\uae08 \ub35c \ub9c9\uc5f0\ud574\uc9c4\ub2e4. \ub2e4\uc74c\uc5d0 \uac00\uaca9\ud45c\ub97c \ubcf4\uace0 \ube44\uc2f8\uc84c\ub2e4\uace0 \ub290\ub080\ub2e4\uba74 \ubb34\uc5c7\uc774 \uc5bc\ub9c8\ub098 \ub2ec\ub77c\uc84c\ub294\uc9c0 \ud55c \ubc88 \ub354 \uc0b4\ud3b4\ubcf4\uc790. \uc790\uc8fc \uc0ac\ub294 \ubb3c\uac74\uacfc \ub2e4\ub978 \uc9c0\ucd9c\uc774 \uac19\uc740 \ubc29\ud5a5\uc73c\ub85c \uc6c0\uc9c1\uc600\ub294\uc9c0\ub3c4 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uc9c0\uac11 \uc18d \uc9c0\ud3d0\ub294 \uadf8\ub300\ub85c\uc5ec\ub3c4 \uc7a5\ubc14\uad6c\ub2c8\uac00 \ub2ec\ub77c\uc9c0\ub294 \uc774\uc720\uc5d0\ub294 \uc0dd\ud65c\uacfc \ud1b5\uacc4\uac00 \ub9cc\ub098\ub294 \uc5ec\ub7ec \uae30\uc900\uc774 \ub4e4\uc5b4 \uc788\ub2e4."}, {"id": "insurance-pool-uncertain-loss", "title": "\ubcf4\ud5d8 \u2014 \uc0ac\uace0\uac00 \uc5c6\uc73c\uba74 \ub0b8 \ub3c8\uc774 \uc544\uae4c\uc6b4 \uac78\uae4c", "summary": "\uac00\uc0c1\uc758 \ud654\uc7ac \ube44\uc6a9\uc744 \ud1b5\ud574 \ubcf4\ud5d8\uc758 \uacf5\ub3d9 \ubd80\ub2f4\uacfc \ubcf4\ud5d8\ub8cc\u00b7\uc790\uae30\ubd80\ub2f4\uae08\uc758 \uc5ed\ud560\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "finance", "category_title": "Finance", "subcategory": "Insurance", "url": "stories/insurance-pool-uncertain-loss/index.html", "image": "media/insurance-pool-uncertain-loss.png", "alt": "\uc774\uc6c3\ub4e4\uc774 \uc9d1 \ubaa8\ud615\uc774 \ub193\uc778 \ud0c1\uc790\uc5d0\uc11c \ubd09\ud22c\ub97c \uacf5\ub3d9 \uc0c1\uc790\uc5d0 \ubaa8\uc73c\ub294 \uac1c\ub150 \uc0bd\ud654.", "text": "\ubcf4\ud5d8 \u2014 \uc0ac\uace0\uac00 \uc5c6\uc73c\uba74 \ub0b8 \ub3c8\uc774 \uc544\uae4c\uc6b4 \uac78\uae4c \ud070 \uc190\uc2e4\uc758 \ubd88\ud655\uc2e4\uc131\uc744 \uc5ec\ub7ec \uc0ac\ub78c\uc774 \ub098\ub204\ub294 \ubc29\ubc95 \uac00\uc0c1\uc758 \ud654\uc7ac \ube44\uc6a9\uc744 \ud1b5\ud574 \ubcf4\ud5d8\uc758 \uacf5\ub3d9 \ubd80\ub2f4\uacfc \ubcf4\ud5d8\ub8cc\u00b7\uc790\uae30\ubd80\ub2f4\uae08\uc758 \uc5ed\ud560\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Insurance \uae08\uc735 \ud55c \ud574 \ub3d9\uc548 \uc0ac\uace0\uac00 \uc5c6\uc5c8\ub2e4. \ub2e4\ud589\ud55c \uc77c\uc778\ub370 \ubcf4\ud5d8\ub8cc\ub97c \ub5a0\uc62c\ub9ac\uba74 \uc870\uae08 \ub2e4\ub978 \uc0dd\uac01\ub3c4 \ub4e0\ub2e4. \uc544\ubb34\uac83\ub3c4 \ub3cc\ub824\ubc1b\uc9c0 \ubabb\ud588\uc73c\ub2c8 \uc190\ud574\uc600\uc744\uae4c. \ubb3c\uac74\uc744 \uc0ac\uba74 \uc190\uc5d0 \ub0a8\ub294 \uac83\uc774 \uc788\ub294\ub370 \ubcf4\ud5d8\uc740 \ub208\uc5d0 \ubcf4\uc774\ub294 \uacb0\uacfc\uac00 \uc5c6\uc744 \ub54c\uac00 \ub9ce\ub2e4. \uc774 \uc9c8\ubb38\uc744 \ud480\ub824\uba74 \ubcf4\ud5d8\uc774 \ubb34\uc5c7\uc744 \ubc14\uafb8\ub294\uc9c0\ubd80\ud130 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc0ac\uace0 \uc790\uccb4\ub97c \uc5c6\uc560 \uc8fc\ub294 \uac83\uacfc \uc0ac\uace0 \ub4a4\uc758 \ud070 \uae08\uc804 \ubd80\ub2f4\uc744 \ub098\ub204\ub294 \uac83\uc740 \ub2e4\ub978 \uc77c\uc774\ub2e4. \ubcf4\ud5d8\uc758 \uae30\ubcf8 \uad6c\uc0c1\uc740 \ubd88\ud655\uc2e4\ud55c \ud070 \uc190\uc2e4\uc744 \uc5ec\ub7ec \uc0ac\ub78c\uc758 \ube44\uad50\uc801 \uc791\uc740 \ubd80\ub2f4\uc73c\ub85c \ub2e4\ub8e8\ub294 \ub370 \uc788\ub2e4. \uac00\uc0c1\uc758 \ub9c8\uc744\uc5d0 100\uac00\uad6c\uac00 \uc788\uace0, \ud55c \ud574\uc5d0 \ud55c \uc9d1\uc5d0\uc11c 1,000\ub9cc \uc6d0\uc758 \ud53c\ud574\uac00 \uc0dd\uae34\ub2e4\uace0 \ub2e8\uc21c\ud558\uac8c \uac00\uc815\ud558\uc790. \uc5b4\ub290 \uc9d1\uc77c\uc9c0\ub294 \ubbf8\ub9ac \ubaa8\ub978\ub2e4. \uac01 \uac00\uad6c\uac00 10\ub9cc \uc6d0\uc529 \ubaa8\uc73c\uba74 \ud569\uacc4\ub294 1,000\ub9cc \uc6d0\uc774 \ub41c\ub2e4. \ud53c\ud574\uac00 \ub09c \uc9d1\uc758 \ud070 \ubd80\ub2f4\uc744 \ud568\uaed8 \ub9c8\ub828\ud55c \ub3c8\uc73c\ub85c \uac10\ub2f9\ud558\ub294 \ubaa8\ud615\uc774\ub2e4. \uc2e4\uc81c\ub85c \ud654\uc7ac\uac00 \ubc18\ub4dc\uc2dc \ud55c \uac74\ub9cc \ubc1c\uc0dd\ud55c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc6b4\uc601\ube44\uc640 \uc774\uc775, \uc7ac\ub09c\uc758 \ub3d9\uc2dc \ubc1c\uc0dd\ub3c4 \uc0dd\ub7b5\ud55c \uacc4\uc0b0\uc774\ub2e4. \uc774 \uc608\uc758 \ubaa9\uc801\uc740 \uc0ac\uace0\ub97c \ub2f9\ud558\uc9c0 \uc54a\uc740 \uc0ac\ub78c\uc774 \ub3cc\ub824\ubc1b\ub294 \ub3c8\ub9cc\uc73c\ub85c \ucc38\uc5ec\uc758 \uac00\uce58\ub97c \ud310\ub2e8\ud558\uae30 \uc5b4\ub835\ub2e4\ub294 \uc810\uc744 \ubcf4\uc774\ub294 \ub370 \uc788\ub2e4. \uc2dc\uc791\ud560 \ub54c\ub294 \ub204\uad6c\ub3c4 \ud53c\ud574 \uac00\uad6c\ub97c \ud655\uc2e4\ud788 \uc54c\uc9c0 \ubabb\ud588\ub2e4. OpenStax\ub294 \ubcf4\ud5d8 \uac00\uc785\uc790\uac00 \ubcf4\ud5d8\ub8cc\ub97c \ub0b4\uace0, \uc815\ud574\uc9c4 \uc190\uc2e4\uc744 \uacaa\uc740 \uc0ac\ub78c\uc774 \uacf5\ub3d9\uc758 \uc790\uae08\uc5d0\uc11c \uc9c0\uae09\ubc1b\ub294 \uad6c\uc870\ub97c \uc124\uba85\ud55c\ub2e4. \ubcf4\ud5d8\ud68c\uc0ac\ub294 \uc9d1\ub2e8\uc5d0\uc11c \uc0ac\uac74\uc774 \uc77c\uc5b4\ub0a0 \uac00\ub2a5\uc131\uacfc \ube44\uc6a9\uc744 \ucd94\uc815\ud55c\ub2e4. \ud55c \uac1c\uc778\uc758 \ubbf8\ub798\ub97c \ub9de\ud788\ub294 \uc77c\uacfc \uc9d1\ub2e8\uc758 \uc704\ud5d8\uc744 \uacc4\uc0b0\ud558\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \uadf8\ub798\uc11c \ubcf4\ud5d8\uc744 \ub0b4\uac00 \ub0b8 \ub3c8\uc744 \ubaa8\ub450 \ub3cc\ub824\ubc1b\ub294 \uc800\ucd95\uacfc \ub611\uac19\uc774 \ubcfc \uc218\ub294 \uc5c6\ub2e4. \ubb3c\ub860 \uc2e4\uc81c \uc0c1\ud488\uc5d0\ub294 \uc5ec\ub7ec \uae30\ub2a5\uc774 \uacb0\ud569\ub420 \uc218 \uc788\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc704\ud5d8\uc744 \ub098\ub204\ub294 \uae30\ubcf8 \uae30\ub2a5\uc744 \uc0b4\ud3b4\ubcf4\ub294 \uac83\uc774\ub2e4. \uc0ac\uace0\uac00 \uc5c6\ub294 \ub3d9\uc548\uc5d0\ub3c4 \ud070 \uc190\uc2e4\uc5d0 \ub300\ube44\ud558\ub294 \uc57d\uc18d\uc740 \uc77c\uc815\ud55c \uae30\uac04 \uc720\uc9c0\ub418\uc5c8\ub2e4. \uc9d1\uc758 \uc704\uce58\uc640 \uad6c\uc870, \ucc28\ub7c9\uc758 \uc0ac\uc6a9 \uc870\uac74\ucc98\ub7fc \uc704\ud5d8\uc5d0 \uc601\ud5a5\uc744 \uc8fc\ub294 \uc694\uc18c\ub294 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uad50\uc7ac\ub294 \ubcf4\ud5d8\ud68c\uc0ac\uac00 \ube44\uc2b7\ud55c \uc704\ud5d8\uc758 \uc9d1\ub2e8\uc744 \uad6c\ubd84\ud558\ub824 \ud55c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uac19\uc740 \uae08\uc561\uc744 \ubcf4\uc7a5\ud55c\ub2e4\uace0 \ubaa8\ub450\uc5d0\uac8c \uac19\uc740 \ubcf4\ud5d8\ub8cc\uac00 \uc801\uc6a9\ub418\ub294 \uac83\uc740 \uc544\ub2cc \uc774\uc720\ub2e4. \ud558\uc9c0\ub9cc \uc9d1\ub2e8\uc744 \uad6c\ubd84\ud558\ub294 \uae30\uc900\uc740 \uc815\ud655\uc131\uacfc \uacf5\uc815\uc131\uc758 \uc9c8\ubb38\uc744 \ud568\uaed8 \ub9cc\ub4e0\ub2e4. \uad00\ucc30\ud55c \ud2b9\uc9d5\uc774 \uc2e4\uc81c \uc704\ud5d8\uc744 \uc5bc\ub9c8\ub098 \uc798 \uc124\uba85\ud558\ub294\uc9c0, \uc5b4\ub5a4 \uad6c\ubd84\uc744 \ud5c8\uc6a9\ud560\uc9c0 \ub530\uc838\uc57c \ud55c\ub2e4. \uac04\ub2e8\ud55c \ud655\ub960\ud45c\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uc81c\ub3c4\uc758 \uc120\ud0dd\uc774 \uc790\ub3d9\uc73c\ub85c \uc815\ud574\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4. \uacc4\uc0b0\uacfc \uaddc\uce59\uc774 \ud568\uaed8 \uc791\uc6a9\ud558\ub294 \uc601\uc5ed\uc774\ub2e4. \ubcf4\ud5d8\uc774 \uc788\uc5b4\ub3c4 \uc190\uc2e4\uc758 \uc77c\ubd80\ub97c \uac00\uc785\uc790\uac00 \ubd80\ub2f4\ud558\ub294 \uacc4\uc57d\uc774 \uc788\ub2e4. \uc790\uae30\ubd80\ub2f4\uae08\uc774\ub098 \uc77c\uc815 \ube44\uc728\uc758 \ubd84\ub2f4 \uac19\uc740 \ubc29\uc2dd\uc774\ub2e4. \uad50\uc7ac\ub294 \uc774\ub7f0 \uc870\uac74\uc774 \uc704\ud5d8\uc744 \uc904\uc774\ub824\ub294 \uc720\uc778\uc744 \uc720\uc9c0\ud558\ub294 \ud55c \ubc29\ubc95\uc774\ub77c\uace0 \uc124\uba85\ud55c\ub2e4. \ubcf4\ud5d8\uc774 \uc788\ub2e4\uace0 \ubaa8\ub4e0 \ube44\uc6a9\uc774 \ubb34\uc870\uac74 \uc804\uc561 \uc9c0\uae09\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uac00\ub839 \ubcf4\uc7a5 \ub300\uc0c1 \uc190\uc2e4 200\ub9cc \uc6d0 \uac00\uc6b4\ub370 \uccab 20\ub9cc \uc6d0\uc744 \ubcf8\uc778\uc774 \ub0b4\ub294 \ub2e8\uc21c\ud55c \uac00\uc0c1 \uc870\uac74\uc774\ub77c\uba74 \ub098\uba38\uc9c0\ub294 180\ub9cc \uc6d0\uc774\ub2e4. \uc2e4\uc81c \uc0c1\ud488\uc5d0\uc11c\ub294 \ud55c\ub3c4\uc640 \uc81c\uc678 \uc0ac\ud56d \ub4f1 \ub2e4\ub978 \uc870\uac74\ub3c4 \uc801\uc6a9\ub420 \uc218 \uc788\ub2e4. \uc9c0\uae09\uc561\uc744 \uc54c\ub824\uba74 \ubcf4\ud5d8\ub8cc\uc758 \uc561\uc218\ubfd0 \uc544\ub2c8\ub77c \uc5b4\ub5a4 \uc57d\uc18d\uc5d0 \uac00\uc785\ud588\ub294\uc9c0 \uc77d\uc5b4\uc57c \ud55c\ub2e4. \uc704\ud5d8\uc758 \uacb0\uacfc\ub97c \ub204\uad70\uac00 \ub098\ub204\uc5b4 \uc900\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc0ac\ub78c\uc758 \ud589\ub3d9\uc5d0 \uc601\ud5a5\uc744 \uc904 \uc218\ub3c4 \uc788\ub2e4. \uad50\uc7ac\ub294 \uc774\ub97c \ub3c4\ub355\uc801 \ud574\uc774\ub77c\ub294 \uac1c\ub150\uc73c\ub85c \uc124\uba85\ud55c\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \ubaa8\ub4e0 \uac00\uc785\uc790\uac00 \ub098\uc058\uac8c \ud589\ub3d9\ud55c\ub2e4\uace0 \ub099\uc778\ucc0d\ub294 \uc77c\uc774 \uc544\ub2c8\ub77c \ube44\uc6a9\uc744 \ubd80\ub2f4\ud558\ub294 \ubc29\uc2dd\uc774 \uc120\ud0dd\uc744 \ubc14\uafc0 \uc218 \uc788\ub2e4\ub294 \uc810\uc774\ub2e4. \uc548\uc804 \uc2dc\uc124\uc744 \uac16\ucd94\uba74 \uc870\uac74\uc744 \ub2ec\ub9ac\ud558\uac70\ub098 \uc77c\ubd80 \ube44\uc6a9\uc744 \ub0a8\uae30\ub294 \uc124\uacc4\ub294 \uc774\ub7f0 \ubb38\uc81c\uc640 \uc5f0\uacb0\ub41c\ub2e4. \ub2e4\ub9cc \ube44\uc6a9 \ubd84\ub2f4\uc744 \ub192\uc774\uba74 \ud544\uc694\ud55c \uc774\uc6a9\uae4c\uc9c0 \uc904\uc5b4\ub4e4 \uc218 \uc788\ub2e4\ub294 \uc9c8\ubb38\ub3c4 \uc0dd\uae34\ub2e4. \uc81c\ub3c4\ub294 \ud55c \uac00\uc9c0 \ubaa9\ud45c\ub9cc \ud06c\uac8c \ud558\uba74 \ub05d\ub098\ub294 \ubb38\uc81c\uac00 \uc544\ub2c8\ub2e4. \ubcf4\ud638\uc640 \ubd80\ub2f4, \uc608\ubc29 \uc0ac\uc774\uc758 \uade0\ud615\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uac00\uc0c1\uc758 \ub9c8\uc744 \uacc4\uc0b0\uc5d0\uc11c \uc5b4\ub824\uc6b4 \uacbd\uc6b0\ub294 \uc5ec\ub7ec \uc9d1\uc774 \ub3d9\uc2dc\uc5d0 \ud53c\ud574\ub97c \uc785\ub294 \uc0c1\ud669\uc774\ub2e4. \ud070 \uc7ac\ub09c\uc740 \uc704\ud5d8\ub4e4\uc774 \uc11c\ub85c \ubb34\uad00\ud558\uc9c0 \uc54a\uc744 \uc218 \uc788\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc0ac\ub78c\uc774 \ub9ce\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uc5b4\ub5a4 \uc190\uc2e4\ub3c4 \uac10\ub2f9\ud560 \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc190\uc2e4\uc758 \uaddc\ubaa8\uc640 \uc11c\ub85c \uc5f0\uacb0\ub418\ub294 \ubc29\uc2dd\uc774 \uc911\uc694\ud558\ub2e4. \ubcf4\ud5d8\ud68c\uc0ac\ub294 \uc9c0\uae09\uc744 \uc704\ud55c \uc900\ube44\uc640 \uc6b4\uc601 \ube44\uc6a9\ub3c4 \ub9c8\ub828\ud574\uc57c \ud55c\ub2e4. \uad50\uc7ac\ub294 \ubcf4\ud5d8\ub8cc\uc640 \uc6b4\uc6a9 \uc218\uc785, \ubcf4\ud5d8\uae08\uacfc \ube44\uc6a9\uc774 \ud568\uaed8 \uc791\uc6a9\ud55c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ubcf4\ud5d8\uc758 \uc790\uae08\uc744 \ub2e8\uc9c0 \uc7a0\uc2dc \ubaa8\uc544 \ub450\uc5c8\ub2e4\uac00 \uadf8\ub300\ub85c \ub098\ub204\ub294 \uc0c1\uc790\ub85c\ub9cc \uc0dd\uac01\ud558\uba74 \uc2e4\uc81c \uc6b4\uc601\uc758 \uc870\uac74\uc740 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ubcf4\ud5d8\uc774\ub77c\ub294 \uc774\ub984\ub9cc\uc73c\ub85c \ubcf4\uc7a5 \ub0b4\uc6a9\uc744 \ub2e4 \uc54c \uc218\ub294 \uc5c6\ub2e4. \uc5b4\ub5a4 \uc0ac\uac74\uc774 \ub300\uc0c1\uc774\uace0 \ubb34\uc5c7\uc774 \uc81c\uc678\ub418\uba70 \uc5b4\ub290 \ubc94\uc704\uae4c\uc9c0 \uc9c0\uae09\ub418\ub294\uc9c0 \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \uac19\uc740 \uc774\ub984\uc758 \uc0c1\ud488\uc774\ub77c\ub3c4 \uc57d\uc18d\uc758 \ub0b4\uc6a9\uc774 \ub2e4\ub97c \uc218 \uc788\ub2e4. \ub0b8 \uae08\uc561\uc774 \uc801\ub2f9\ud55c\uc9c0 \ubb3b\ub294 \uc77c\ubcf4\ub2e4 \uba3c\uc800 \uacc4\uc57d\uc774 \ub2e4\ub8e8\ub294 \uc704\ud5d8\uc744 \uc54c\uc544\uc57c \ud55c\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uc774\uc6c3\ub4e4\uc774 \uacf5\ub3d9\uc758 \ub300\ube44\ub97c \uc0dd\uac01\ud558\ub294 \uc0c1\uc0c1 \uc18d \uc7a5\uba74\uc774\ub2e4. \uc2e4\uc81c \ubcf4\ud5d8\ud68c\uc0ac\uc758 \uc6b4\uc601\uc774\ub098 \ubcf4\ud5d8\uae08 \uc9c0\uae09 \uacfc\uc815\uc744 \uc7ac\ud604\ud55c \ub3c4\ud45c\ub294 \uc544\ub2c8\ub2e4. \uc774 \uae00\uc758 \ub450 \uacc4\uc0b0\ub3c4 \uac00\uc0c1 \ubaa8\ud615\uc774\uba70 \ud2b9\uc815 \uacc4\uc57d\uc758 \uc9c0\uae09\uc561\uc744 \uc548\ub0b4\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc0ac\uace0\uac00 \uc5c6\uc5c8\ub2e4\uba74 \ud070 \uc190\uc2e4\uc774 \uc0dd\uae30\uc9c0 \uc54a\uc558\ub2e4\ub294 \uc810\uc5d0\uc11c \uba3c\uc800 \ub2e4\ud589\ud55c \uc77c\uc774\ub2e4. \uadf8\ub3d9\uc548 \ubcf4\ud5d8\uc774 \uc81c\uacf5\ud55c \uac00\uce58\ub294 \ub098\uc911\uc5d0 \ubc1b\uc740 \uae08\uc561\uacfc \uc815\ud655\ud788 \uac19\uc740 \ud56d\ubaa9\uc740 \uc544\ub2c8\ub2e4. \ubd88\ud655\uc2e4\ud55c \ube44\uc6a9\uc758 \uc77c\ubd80\ub97c \ubbf8\ub9ac \uc815\ud55c \ubd80\ub2f4\uc73c\ub85c \ubc14\uafb8\ub294 \uc57d\uc18d\uc774 \uc788\uc5c8\ub2e4. \ubcf4\ud5d8\uc744 \uc774\ud574\ud558\uba74 \ubb34\uc870\uac74 \ub9ce\uc774 \uac00\uc785\ud558\uac70\ub098 \ubaa8\ub450 \uc5c6\uc560\uc790\ub294 \ub2f5\ubcf4\ub2e4 \uad6c\uccb4\uc801\uc778 \uc9c8\ubb38\uc774 \uc0dd\uae34\ub2e4. \ub0b4\uac00 \uac10\ub2f9\ud558\uae30 \uc5b4\ub824\uc6b4 \uc704\ud5d8\uc740 \ubb34\uc5c7\uc774\uba70 \uacc4\uc57d\uc740 \uadf8 \ubd80\ubd84\uc744 \uc5b4\ub5bb\uac8c \ub098\ub204\ub294\uac00. \uc544\ubb34 \uc77c\ub3c4 \uc5c6\ub358 \ud574\ub97c \ub3cc\uc544\ubcf4\ub294 \uc9c8\ubb38\uc740 \uacb0\uad6d \ud070\uc77c\uc774 \uc0dd\uacbc\uc744 \ub54c \ub204\uac00 \uc5b4\ub5a4 \uc870\uac74\uc73c\ub85c \ubd80\ub2f4\ud560\uc9c0\ub97c \uc0dd\uac01\ud558\ub294 \uc9c8\ubb38\uacfc \uc774\uc5b4\uc9c4\ub2e4."}, {"id": "kublai-paper-money-and-seal", "title": "\ucfe0\ube4c\ub77c\uc774\uc758 \uc9c0\ud3d0 \u2014 \ub098\ubb34\uaecd\uc9c8\uc774 \ub3c8\uc774 \ub418\ub358 \uc81c\uad6d", "summary": "\ub9c8\ub974\ucf54 \ud3f4\ub85c\uc758 \ud654\ud3d0 \uc11c\uc220\uacfc \uc6d0 \uc655\uc870\uc758 \uacbd\uc81c\uc0ac\ub97c \ub300\uc870\ud574 \uc885\uc774\ub3c8\u00b7\uad8c\ub825\u00b7\uac70\ub798\uc758 \uad00\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "finance", "category_title": "Finance", "subcategory": "Money", "url": "stories/kublai-paper-money-and-seal/index.html", "image": "media/kublai-paper-money-and-seal.png", "alt": "\uc885\uc774\uc640 \ubd93, \uc778\uc7a5\uc744 \ub193\uace0 \ubb38\uc11c\ub97c \uc0b4\ud53c\ub294 \uad00\ub9ac\uc640 \uc5ec\ud589 \uc9d0\uc744 \ub4e0 \uc0c1\uc778\uc758 \uc0c1\uc0c1 \uc18d \uc7a5\uba74.", "text": "\ucfe0\ube4c\ub77c\uc774\uc758 \uc9c0\ud3d0 \u2014 \ub098\ubb34\uaecd\uc9c8\uc774 \ub3c8\uc774 \ub418\ub358 \uc81c\uad6d \ub9c8\ub974\ucf54 \ud3f4\ub85c\uac00 \ub180\ub77c\uba70 \uae30\ub85d\ud55c \uc885\uc774\uc640 \ubd89\uc740 \uc778\uc7a5 \ub9c8\ub974\ucf54 \ud3f4\ub85c\uc758 \ud654\ud3d0 \uc11c\uc220\uacfc \uc6d0 \uc655\uc870\uc758 \uacbd\uc81c\uc0ac\ub97c \ub300\uc870\ud574 \uc885\uc774\ub3c8\u00b7\uad8c\ub825\u00b7\uac70\ub798\uc758 \uad00\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Money \uae08\uc735 \ub9c8\ub974\ucf54 \ud3f4\ub85c\ub294 \uc911\uad6d\uc5d0\uc11c \ubcf8 \ub3c8\uc744 \uc124\uba85\ud558\uba70 \uc5f0\uae08\uc220\uc744 \ub5a0\uc62c\ub838\ub2e4. \uae08\uacfc \uc740\uc744 \ub9cc\ub4e4\ub824\ub294 \uc0ac\ub78c\uc774 \ub9ce\ub358 \uc2dc\ub300\uc5d0 \ucfe0\ube4c\ub77c\uc774 \uce78\uc740 \ub098\ubb34\uc5d0\uc11c \uc5bb\uc740 \uc7ac\ub8cc\ub85c \ub3c8\uc744 \ub9cc\ub4e0\ub2e4\ub294 \uac83\uc774\uc5c8\ub2e4. \uc885\uc774\ub97c \uadc0\uae08\uc18d\ucc98\ub7fc \uc0ac\uc6a9\ud55c\ub2e4\ub294 \ubc1c\uc0c1\uc740 \uba3c \uacf3\uc5d0\uc11c \uc628 \uc5ec\ud589\uc790\uc5d0\uac8c \ub180\ub78d\uac8c \ubcf4\uc600\ub2e4. \ubb3c\ub860 \uc885\uc774\uac00 \uc2e4\uc81c\ub85c \uae08\uc73c\ub85c \ubcc0\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \ud3f4\ub85c\uc758 \uc5ec\ud589\uae30\uc5d0 \ub098\ud0c0\ub098\ub294 \uac83\uc740 \uc885\uc774\uc640 \uae00, \uc778\uc7a5, \uadf8\ub9ac\uace0 \uadf8\uac83\uc744 \ud1b5\uc6a9\uc2dc\ud0a4\ub294 \uad8c\ub825\uc774\ub2e4. \uc624\ub798\ub41c \uae30\ub85d\uc758 \ub180\ub77c\uc6c0\uc744 \ub530\ub77c\uac00\uba74 \uc9c0\ud3d0\uac00 \ub2e8\uc21c\ud788 \uac00\ubcbc\uc6b4 \ub3d9\uc804\uc744 \ub73b\ud558\uc9c0 \uc54a\uc558\ub358 \uc774\uc720\ub97c \ub9cc\ub098\uac8c \ub41c\ub2e4. \ud3f4\ub85c\ub294 \ucfe0\ube4c\ub77c\uc774\uc758 \uc218\ub3c4\ub97c \uce84\ubc1c\ub8e8\ud06c\ub77c\uace0 \ubd80\ub974\uba70 \uadf8\uacf3\uc758 \ud654\ud3d0 \uc81c\uc791 \ubc29\uc2dd\uc744 \uc18c\uac1c\ud55c\ub2e4. \uc624\ub298\ub0a0 \ubca0\uc774\uc9d5\uc5d0 \ud574\ub2f9\ud558\ub294 \ub3c4\uc2dc\ub2e4. \uadf8\ub294 \ubf55\ub098\ubb34\uc758 \ubc14\uae65\uaecd\uc9c8\uacfc \ubaa9\uc9c8 \uc0ac\uc774\uc758 \uc7ac\ub8cc\ub97c \uc0ac\uc6a9\ud574 \uc885\uc774\uc640 \ube44\uc2b7\ud55c \ud310\uc744 \ub9cc\ub4e4\uace0 \uc5ec\ub7ec \ud06c\uae30\ub85c \uc790\ub978\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc774\ub294 \ub2f9\uc2dc\uc758 \ubaa8\ub4e0 \uc9c0\ud3d0 \uc7ac\ub8cc\ub97c \ud604\ub300\uc758 \uc81c\uc870 \uaddc\uaca9\ucc98\ub7fc \uc778\uc99d\ud558\ub294 \uc124\uba85\uc740 \uc544\ub2c8\ub2e4. \uc5ec\ud589\uae30\uc758 \uad00\ucc30\uacfc \uc804\uc2b9, \ud6c4\ub300 \ubc88\uc5ed\uc744 \uac70\uce5c \uae30\ub85d\uc774\ub2e4. \ub2e4\ub9cc \ub0af\uc120 \ub3c8\uc744 \ub3c5\uc790\uc5d0\uac8c \uc774\ud574\uc2dc\ud0a4\uae30 \uc704\ud574 \uc7ac\ub8cc\uc640 \ubaa8\uc591\ubd80\ud130 \uad6c\uccb4\uc801\uc73c\ub85c \ud480\uc5b4\ub0b8 \ubc29\uc2dd\uc740 \uc9c0\uae08 \uc77d\uc5b4\ub3c4 \uc0dd\uc0dd\ud558\ub2e4. \uae30\ub85d\uc5d0\ub294 \uad00\ub9ac\ub4e4\uc774 \uc774\ub984\uc744 \uc4f0\uace0 \uc778\uc7a5\uc744 \ucc0d\ub294 \uacfc\uc815\uc774 \ub098\uc628\ub2e4. \ub9c8\uc9c0\ub9c9\uc5d0\ub294 \ubd89\uc740 \uc0c9\uc744 \ubb3b\ud78c \uacf5\uc2dd \uc778\uc7a5\uc774 \ub354\ud574\uc9c4\ub2e4. \uc544\ubb34 \uc885\uc774\ub098 \uac19\uc740 \uad6c\uc2e4\uc744 \ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc815\ud574\uc9c4 \uc808\ucc28\ub97c \uac70\uccd0 \uc2b9\uc778\ub41c \ud45c\uc9c0\uac00 \ubd99\ub294\ub2e4\ub294 \uc124\uba85\uc774\ub2e4. \uc774 \uc7a5\uba74\uc5d0\uc11c \uc911\uc694\ud55c \uac83\uc740 \uc544\ub984\ub2e4\uc6b4 \ub3c4\uc7a5\ub9cc\uc774 \uc544\ub2c8\ub2e4. \ub204\uac00 \ubc1c\ud589\ud558\uace0 \ubb34\uc5c7\uc73c\ub85c \uc9c4\uc9dc\uc784\uc744 \ub4dc\ub7ec\ub0b4\ub294\uc9c0\uac00 \uac70\ub798\uc758 \uc870\uac74\uc774\uc5c8\ub2e4. \ub3c8\uc758 \uc7ac\ub8cc\uac00 \uadc0\ud558\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ubc1c\ud589\ud55c \ucabd\uc758 \uad8c\uc704\ub97c \uc778\uc815\ud55c\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub2e4\ub978 \uc885\ub958\uc758 \uadfc\uac70\ub2e4. \ud3f4\ub85c\ub294 \uadf8 \ucc28\uc774\ub97c \uc790\uae30 \ub3c5\uc790\uc5d0\uac8c \ub180\ub77c\uc6b4 \uac83\uc73c\ub85c \uc804\ub2ec\ud588\ub2e4. \ud3f4\ub85c\ub294 \uc885\uc774\ub3c8\uc774 \uadc0\uae08\uc18d\uc5d0 \ube44\ud574 \uac00\ubccd\uace0 \uc5ec\ud589 \uc911\uc5d0 \uac00\uc9c0\uace0 \ub2e4\ub2c8\uae30 \ud3b8\ud558\ub2e4\uace0 \uc37c\ub2e4. \ub0af\uc120 \uacf3\uc5d0\uc11c \ubb3c\uac74\uc744 \uc0ac\ub294 \uc0c1\uc778\uc5d0\uac8c \ubb34\uac8c\ub294 \uc2e4\uc81c \ubb38\uc81c\uc600\ub2e4. \uba3c \uae38\uc5d0 \uc4f8 \uac00\uce58\ub97c \uc5b4\ub5a4 \ud615\ud0dc\ub85c \uc6b4\ubc18\ud560 \uc218 \uc788\ub294\uc9c0\uac00 \uc911\uc694\ud588\uae30 \ub54c\ubb38\uc774\ub2e4. \uadf8\ub7ec\ub098 \uac00\ubccd\uae30\ub9cc \ud558\uba74 \uc5b4\ub514\uc11c\ub098 \ub3c8\uc774 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc0c1\ub300\uac00 \uadf8 \uc885\uc774\ub97c \uc9c0\uae09 \uc218\ub2e8\uc73c\ub85c \ubc1b\uc544\ub4e4\uc5ec\uc57c \ud55c\ub2e4. \uae30\ub85d \uc18d\uc758 \ud3b8\ub9ac\ud568\uc740 \ub3c8\uc774 \uc4f0\uc774\ub294 \ubc94\uc704\uc640 \ubc1c\ud589 \uad8c\ub825\uc774 \uc791\ub3d9\ud558\ub294 \uc9c0\uc5ed\uc774\ub77c\ub294 \uc870\uac74 \uc704\uc5d0 \ub193\uc5ec \uc788\ub2e4. \uc5ec\ud589\uc758 \uc9d0\uc774 \uac00\ubcbc\uc6cc\uc9c4 \uc774\uc57c\uae30 \ub4a4\uc5d0\ub294 \ub113\uc740 \ud1b5\uc6a9\uc758 \uc7a5\uce58\uac00 \uc788\uc5c8\ub2e4. \ud3f4\ub85c\uc758 \uc11c\uc220\uc5d0\ub294 \ub3c8\uc744 \uc4f0\uac8c \ud558\ub294 \uac15\ud55c \uba85\ub839\ub3c4 \ub4f1\uc7a5\ud55c\ub2e4. \ud604\ub300\uc758 \ub3c5\uc790\ub294 \ud3b8\ub9ac\ud55c \ubc1c\uba85\uc744 \ubaa8\ub450\uac00 \uc790\uc5f0\uc2a4\ub7fd\uac8c \uc120\ud0dd\ud55c \uc7a5\uba74\uc73c\ub85c\ub9cc \uc77d\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uad50\uc7ac\ub3c4 \uc6d0 \uc815\ubd80\uac00 \uad6d\uac00\uc640\uc758 \uac70\ub798\uc5d0\uc11c \uc9c0\ud3d0\ub97c \uc0ac\uc6a9\ud558\uac8c \ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ubb34\uc5c7\uc744 \uc138\uae08\uacfc \uc9c0\uae09\uc5d0 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294\uc9c0\ub294 \uc0ac\ub78c\ub4e4\uc758 \uc120\ud0dd\uc5d0 \uc601\ud5a5\uc744 \uc900\ub2e4. \uc9c0\ud3d0\uc758 \uc0ac\uc6a9\uc740 \ubb3c\uac74\uc758 \uc131\uc9c8\ubfd0 \uc544\ub2c8\ub77c \uc81c\ub3c4\uc640 \uc5f0\uacb0\ub418\uc5b4 \uc788\uc5c8\ub2e4. \ud3f4\ub85c\uac00 \ubb18\uc0ac\ud55c \ud3ed\ub113\uc740 \ud1b5\uc6a9\uc744 \ubaa8\ub4e0 \uac1c\uc778\uc758 \ub9cc\uc871\ub3c4\ub098 \uc81c\uad6d\uc758 \ub9e4\uc77c\uc758 \uc2e4\uc81c \uc0c1\ud669\uae4c\uc9c0 \ud655\uc778\ud55c \uc870\uc0ac\ucc98\ub7fc \ubc1b\uc544\ub4e4\uc77c \uc218\ub294 \uc5c6\ub2e4. \ud3f4\ub85c\ub294 \uce78\uc774 \uc801\uc740 \ube44\uc6a9\uc73c\ub85c \uc5c4\uccad\ub09c \ubd80\ub97c \uc5bb\ub294 \ub4ef\ud55c \ud45c\ud604\uc744 \uc4f4\ub2e4. \ud558\uc9c0\ub9cc \uc5ec\ud589\uc790\uc758 \uac10\ud0c4\uc744 \ub3c8\uc744 \ubc1c\ud589\ud558\uba74 \uc544\ubb34 \ube44\uc6a9 \uc5c6\uc774 \ubb34\uc5c7\uc774\ub4e0 \uc0b4 \uc218 \uc788\ub2e4\ub294 \ubc95\uce59\uc73c\ub85c \uc62e\uae38 \uc218\ub294 \uc5c6\ub2e4. \uc885\uc774\ub97c \ub9cc\ub4e4 \uc218 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uadf8 \ub3c8\uc758 \uad6c\ub9e4\ub825\uc774 \uc720\uc9c0\ub41c\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub2e4\ub974\ub2e4. \uc6d0 \uc655\uc870\uc758 \uc5ed\uc0ac\ub97c \ub2e4\ub8ec \uad50\uc7ac\uc5d0\ub294 \uc804\uc7c1 \ube44\uc6a9\uacfc \uc138\uae08, \ubc1c\ud589 \ud655\ub300\uc640 \ubb3c\uac00 \uc0c1\uc2b9\uc758 \ubb38\uc81c\uac00 \ud568\uaed8 \ub098\ud0c0\ub09c\ub2e4. \ud3b8\ub9ac\ud55c \uc9c0\uae09 \uc218\ub2e8\uc744 \uac00\uc9c4 \uc815\ubd80\ub3c4 \uc7ac\uc815\uacfc \uc0dd\uc0b0\uc758 \uc81c\uc57d\uc5d0\uc11c \uc790\uc720\ub86d\uc9c0 \uc54a\uc558\ub2e4. \uc5ec\ud589\uae30\uc5d0 \ube44\uce5c \ud654\ub824\ud55c \ubaa8\uc2b5\uacfc \uae34 \uc2dc\uac04\uc758 \uacbd\uc81c\uc0ac\ub294 \ub2e4\ub978 \ubc94\uc704\ub97c \ubcf4\uc5ec \uc900\ub2e4. \ucfe0\ube4c\ub77c\uc774\uc640 \ud6c4\uacc4 \uc815\ubd80\ub4e4\uc740 \uad70\uc0ac \uc6d0\uc815\uacfc \uad8c\ub825 \ub2e4\ud23c, \uc7ac\uc815 \ubd80\ub2f4\uc744 \uacaa\uc5c8\ub2e4. \uad50\uc7ac\ub294 \ub354 \ub9ce\uc740 \uc9c0\ud3d0\uac00 \ubc1c\ud589\ub418\uace0 \uc8fc\ubbfc\uc774 \uc138\uae08\uc744 \ub0b4\uae30 \uc704\ud574 \uadf8 \ub3c8\uc744 \uad6c\ud574\uc57c \ud588\ub358 \uc0c1\ud669\uc744 \uc124\uba85\ud55c\ub2e4. \ub3c8\uc744 \uc0ac\uc6a9\ud558\ub294 \uc758\ubb34\uc640 \uadf8 \ub3c8\uc758 \uac00\uce58\uac00 \ud754\ub4e4\ub9ac\ub294 \uacbd\ud5d8\uc774 \uacb9\uce60 \uc218 \uc788\uc5c8\ub2e4. \uc774\ub97c \ud604\ub300\uc758 \ubaa8\ub4e0 \uc885\uc774\ub3c8\uc5d0\ub294 \uac19\uc740 \uacb0\ub9d0\uc774 \uc815\ud574\uc838 \uc788\ub2e4\ub294 \uad50\ud6c8\uc73c\ub85c \ubc14\uafb8\uba74 \uc5ed\uc0ac\ub97c \ub108\ubb34 \ub2e8\uc21c\ud558\uac8c \uc77d\uac8c \ub41c\ub2e4. \ub2f9\uc2dc\uc758 \uc81c\ub3c4\uc640 \uc7ac\uc815, \uc804\uc7c1\uacfc \uc0ac\ud68c \uc870\uac74\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \ud55c \uc2dc\ub300\uc758 \uc0ac\ub840\ub294 \ub3c8\uc758 \uc7ac\ub8cc\ub9cc\uc73c\ub85c \uc131\uacf5\uacfc \uc2e4\ud328\ub97c \uc124\uba85\ud558\uae30 \uc5b4\ub835\ub2e4\ub294 \uc810\uc744 \uc624\ud788\ub824 \uc54c\ub824 \uc900\ub2e4. \uc5ec\ud589\uae30\uc5d0\ub294 \uc190\uc0c1\ub41c \ub3c8\uc744 \uc0c8\uac83\uc73c\ub85c \ubc14\uafb8\ub294 \uc124\uba85\ub3c4 \uc788\ub2e4. \uc885\uc774\uac00 \ub0a1\uc73c\uba74 \uac70\ub798\uac00 \ub05d\ub098\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uad50\ud658\uacfc \uad00\ub9ac\uc758 \uc808\ucc28\uac00 \ud544\uc694\ud588\ub2e4\ub294 \uac83\uc774\ub2e4. \ub3c8\uc744 \ubc1c\ud589\ud558\ub294 \uc77c\uacfc \uacc4\uc18d \uc0ac\uc6a9\ud560 \uc218 \uc788\ub3c4\ub85d \uc6b4\uc601\ud558\ub294 \uc77c\uc740 \uac19\uc740 \uc774\uc57c\uae30\uc758 \uc11c\ub85c \ub2e4\ub978 \ubd80\ubd84\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uc885\uc774\uc640 \uc778\uc7a5\uc744 \ub2e4\ub8e8\ub294 \uc0c1\uc0c1 \uc18d \uad00\uccad \uc7a5\uba74\uc774\ub2e4. \uc2e4\uc81c \uc6d0 \uc9c0\ud3d0\uc758 \ub3c4\uc548\uc774\ub098 \ud654\ud3d0 \uc81c\uc791\uc18c\ub97c \uace0\uc99d\ud574 \ubcf5\uc6d0\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uae00\uc758 \uadfc\uac70\ub294 \uc5ec\ud589\uae30\uc640 \uc5ed\uc0ac \uad50\uc7ac\uc5d0 \ub450\uace0 \uadf8\ub9bc\uc5d0\uc11c\ub294 \uc885\uc774\ub3c8\uc774 \uacf5\uc801\uc778 \ud45c\uc9c0\ub97c \uc5bb\ub294 \ubd84\uc704\uae30\ub97c \ub5a0\uc62c\ub9ac\uba74 \ub41c\ub2e4. \ub9c8\ub974\ucf54 \ud3f4\ub85c\uc5d0\uac8c \uc885\uc774\ub3c8\uc740 \uc5f0\uae08\uc220\ucc98\ub7fc \ubcf4\uc600\uc9c0\ub9cc \uadf8 \uc791\ub3d9\uc5d0\ub294 \uad00\ub9ac\uc758 \uc190\uacfc \uc2dc\uc7a5\uc758 \uac70\ub798, \uc138\uae08\uc744 \uac70\ub450\ub294 \uc815\ubd80\uac00 \uc788\uc5c8\ub2e4. \uac00\ubcbc\uc6b4 \ubb3c\uac74 \ud55c \uc7a5\uc774 \uba3c \uc9c0\uc5ed\uc744 \uc5f0\uacb0\ud560 \uc218 \uc788\uc5c8\ub358 \uc774\uc720\ub294 \uc7ac\ub8cc\ub9cc\ud07c \uadf8 \uc8fc\ubcc0\uc758 \uad00\uacc4\uc5d0 \uc788\uc5c8\ub2e4. \uc624\ub298\uc758 \uc9c0\ud3d0\ub97c \ubcfc \ub54c\ub3c4 \uc885\uc774\uac12\uacfc \uadf8 \uc704\uc758 \uc22b\uc790\uac00 \uc65c \ub2e4\ub978\uc9c0 \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \ucfe0\ube4c\ub77c\uc774 \uc2dc\ub300\uc758 \ub3c8\uc740 \uc774 \uc9c8\ubb38\uc744 \uba3c \uc5ed\uc0ac \uc18d\uc5d0\uc11c \ub2e4\uc2dc \ubcf4\uac8c \ud558\ub294 \uc0ac\ub840\ub2e4. \uc5ec\ud589\uc790\uc758 \ub180\ub77c\uc6c0\uacfc \uc8fc\ubbfc\uc774 \uacaa\uc740 \ubd80\ub2f4\uc744 \ub098\ub780\ud788 \uc77d\uc73c\uba74 \ub3c8\uc758 \uc5ed\uc0ac\ub294 \uc2e0\uae30\ud55c \ubc1c\uba85\ub2f4\ubcf4\ub2e4 \ud6e8\uc52c \uc785\uccb4\uc801\uc778 \uc774\uc57c\uae30\uac00 \ub41c\ub2e4."}, {"id": "lloyds-coffeehouse-shipping-news", "title": "\ub85c\uc774\uc988 \u2014 \ucee4\ud53c\ud558\uc6b0\uc2a4\uc5d0\uc11c \uc790\ub77c\ub09c \ud574\uc0c1\ubcf4\ud5d8", "summary": "\uc5d0\ub4dc\uc6cc\ub4dc \ub85c\uc774\ub4dc\uc758 \ucee4\ud53c\ud558\uc6b0\uc2a4\uc640 \ud6c4\ub300\uc758 \uc120\ubc15 \uc815\ubcf4\uc2e4\uc744 \ub530\ub77c \ud574\uc0c1\ubcf4\ud5d8\uacfc \uae30\ub85d\uc758 \uc5ed\uc0ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "finance", "category_title": "Finance", "subcategory": "Insurance", "url": "stories/lloyds-coffeehouse-shipping-news/index.html", "image": "media/lloyds-coffeehouse-shipping-news.jpg", "alt": "\ud6c4\ub300 \ub85c\uc5f4 \uc775\uc2a4\uccb4\uc778\uc9c0 \ub85c\uc774\uc988 \uad6c\ub3c5\uc790\uc2e4\uc758 \uc5ed\uc0ac \ub3c4\ud310. \ud070 \uae30\ub465\uacfc \uae34 \ucc45\uc0c1, \ubaa8\uc778 \uc0ac\ub78c\ub4e4.", "text": "\ub85c\uc774\uc988 \u2014 \ucee4\ud53c\ud558\uc6b0\uc2a4\uc5d0\uc11c \uc790\ub77c\ub09c \ud574\uc0c1\ubcf4\ud5d8 \ubc30\uc758 \uc18c\uc2dd\uc774 \ub3c8\uc758 \uc57d\uc18d\uc73c\ub85c \uc774\uc5b4\uc9c0\ub358 \ub7f0\ub358 \uc5d0\ub4dc\uc6cc\ub4dc \ub85c\uc774\ub4dc\uc758 \ucee4\ud53c\ud558\uc6b0\uc2a4\uc640 \ud6c4\ub300\uc758 \uc120\ubc15 \uc815\ubcf4\uc2e4\uc744 \ub530\ub77c \ud574\uc0c1\ubcf4\ud5d8\uacfc \uae30\ub85d\uc758 \uc5ed\uc0ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Insurance \uae08\uc735 17\uc138\uae30 \ub9d0 \ub7f0\ub358\uc758 \ud55c \ucee4\ud53c\ud558\uc6b0\uc2a4\uc5d0 \ubc30\uc640 \ud654\ubb3c\uc5d0 \uad00\uc2ec\uc744 \uac00\uc9c4 \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc600\ub2e4. \uc5b4\ub290 \ubc30\uac00 \ub5a0\ub0ac\uace0 \uc5b4\ub290 \ud56d\uad6c\uc5d0 \ub3c4\ucc29\ud588\ub294\uc9c0, \ubc14\ub2e4\uc5d0\uc11c \ubb34\uc2a8 \uc77c\uc774 \uc788\uc5c8\ub294\uc9c0\ub97c \uc54c\uace0 \uc2f6\uc5b4 \ud558\ub294 \uc0ac\ub78c\ub4e4\uc774\uc5c8\ub2e4. \ub530\ub73b\ud55c \uc74c\ub8cc\ub97c \ub9c8\uc2dc\ub294 \uc790\ub9ac\uc5d0\uc11c \ub2e4\uc74c \uac70\ub798\ub97c \ubc14\uafc0 \uc18c\uc2dd\uc774 \uc624\uac14\ub2e4. \uac00\uac8c \uc8fc\uc778\uc758 \uc774\ub984\uc740 \uc5d0\ub4dc\uc6cc\ub4dc \ub85c\uc774\ub4dc\uc600\ub2e4. \uadf8\uc758 \uc774\ub984\uc744 \ub534 \ub85c\uc774\uc988\uc758 \uc5ed\uc0ac\ub294 \ucee4\ud53c\uac00 \ud2b9\ubcc4\ud55c \uae08\uc735 \uc0c1\ud488\uc774\uc5b4\uc11c \uc2dc\uc791\ub41c \uac83\uc774 \uc544\ub2c8\ub2e4. \uac19\uc740 \uc815\ubcf4\ub97c \ud544\uc694\ub85c \ud558\ub294 \uc0ac\ub78c\ub4e4\uc774 \uac19\uc740 \uc7a5\uc18c\uc5d0\uc11c \ub9cc\ub0ac\uace0, \uadf8 \ub9cc\ub0a8\uc774 \ud574\uc0c1 \uc704\ud5d8\uc744 \ub098\ub204\ub294 \uac70\ub798\uc640 \uc774\uc5b4\uc84c\ub2e4. \uc70c\ub9ac\uc5c4 \uc720\ucee4\uc2a4\uc758 1922\ub144 \ucc45 \u300e\ucee4\ud53c\uc758 \ubaa8\ub4e0 \uac83\u300f\uc740 \ub85c\uc774\ub4dc\uac00 1688\ub144 \ubb34\ub835 \ub7f0\ub358 \ud0c0\uc6cc \uc2a4\ud2b8\ub9ac\ud2b8\uc5d0\uc11c \ucee4\ud53c\ud558\uc6b0\uc2a4\ub97c \uc6b4\uc601\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc774\ud6c4 \uac00\uac8c\ub294 \ub86c\ubc14\ub4dc \uc2a4\ud2b8\ub9ac\ud2b8\ub85c \uc62e\uaca8 \uac14\ub2e4. \ucc98\uc74c\ubd80\ud130 \uc624\ub298\uc758 \ud070 \uae08\uc735\uae30\uad00 \uac19\uc740 \ubaa8\uc2b5\uc73c\ub85c \ubb38\uc744 \uc5f0 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc774\uacf3\uc758 \uc190\ub2d8\uc5d0\ub294 \uc120\uc6d0\uacfc \uc0c1\uc778\ub4e4\uc774 \uc788\uc5c8\ub2e4. \ubc43\uae38\uacfc \uac70\ub798\uc758 \uc0c1\ud669\uc5d0 \uad00\ud55c \uc815\ubcf4\uac00 \uc77c\uacfc \uc5f0\uacb0\ub41c \uc0ac\ub78c\ub4e4\uc774\uc5c8\ub2e4. \uc5b4\ub5a4 \ucee4\ud53c\ud558\uc6b0\uc2a4\uac00 \ubb38\ud559\uac00\uc758 \ubaa8\uc784\uc73c\ub85c \uc54c\ub824\uc9c0\uace0 \ub2e4\ub978 \uacf3\uc774 \uc815\uce58\uc801 \ub300\ud654\uc758 \uc7a5\uc18c\uac00 \ub41c \uac83\ucc98\ub7fc, \ub85c\uc774\ub4dc\uc758 \uac00\uac8c\uc5d0\ub294 \ubc14\ub2e4\uc5d0 \uad00\ud55c \uad00\uc2ec\uc774 \ubaa8\uc600\ub2e4. \uc720\ucee4\uc2a4\ub294 \ub85c\uc774\ub4dc\uac00 \uc190\ub2d8\uc744 \uc704\ud574 \uc120\ubc15 \ubaa9\ub85d\uc744 \uc900\ube44\ud588\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \ucd08\uae30\uc5d0\ub294 \uc190\uc73c\ub85c \uc4f4 \uc815\ubcf4\uc600\ub2e4. \ud574\uc0c1\ubcf4\ud5d8\uc744 \ub2e4\ub8e8\ub294 \uc0ac\ub78c\ub4e4\uc5d0\uac8c \uc81c\uc2dc\ub420 \uc218 \uc788\ub294 \ubc30\uac00 \uc5b4\ub5a4 \uac83\uc778\uc9c0 \uc54c\uc544\ubcf4\ub294 \ub370 \uc4f0\uc600\ub2e4. \uac00\uac8c\ub294 \ub2e8\uc21c\ud788 \ub300\ud654\ub97c \ub4e3\ub294 \uacf5\uac04\uc5d0\uc11c \uc815\ub9ac\ub41c \uc815\ubcf4\ub97c \uc81c\uacf5\ud558\ub294 \uc790\ub9ac\ub85c\ub3c4 \uae30\ub2a5\ud588\ub2e4. \uc624\ub298\uc740 \uc120\ubc15\uc758 \uc704\uce58\ub97c \ud654\uba74\uc5d0\uc11c \ubcf4\ub294 \uc77c\uc774 \uac00\ub2a5\ud558\uc9c0\ub9cc \ub2f9\uc2dc\uc5d0\ub294 \uc18c\uc2dd\uc774 \uc5b4\ub514\uc11c \uc640\uc11c \ub204\uad6c\uc5d0\uac8c \ubaa8\uc774\ub294\uc9c0\uac00 \uc911\uc694\ud588\ub2e4. \uba40\ub9ac\uc11c \ubc30\uac00 \uc0ac\ub77c\uc9c4 \uac83\uc778\uc9c0, \ub2a6\uac8c \ub3c4\ucc29\ud558\ub294 \uac83\uc778\uc9c0 \uad6c\ubd84\ud558\uae30 \uc5b4\ub824\uc6b4 \uc0c1\ud669\ub3c4 \uc788\uc5c8\ub2e4. \uc815\ubcf4\uac00 \ube60\ub974\uac8c \ubaa8\uc774\ub294 \uc7a5\uc18c\uc5d0\ub294 \uc0ac\ub78c\ub4e4\uc774 \ub2e4\uc2dc \ucc3e\uc544\uc62c \uc774\uc720\uac00 \uc0dd\uacbc\ub2e4. \ubc30\ub97c \ubcf4\ub0b4\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \ub3c4\ucc29 \ub4a4\uc758 \uc218\uc775\ubfd0 \uc544\ub2c8\ub77c \ud56d\ud574 \uc911\uc758 \uc190\uc2e4\ub3c4 \ubb38\uc81c\uc600\ub2e4. \ud574\uc0c1\ubcf4\ud5d8\uc744 \ub9e1\ub294 \uc0ac\ub78c\uc740 \uc815\ud574\uc9c4 \uc870\uac74 \uc544\ub798 \uc704\ud5d8\uc758 \uc77c\ubd80\ub97c \ubd80\ub2f4\ud558\ub294 \ub300\uac00\ub97c \ubc1b\ub294\ub2e4. \ub530\ub77c\uc11c \uc5b4\ub5a4 \ubc30\uc640 \ud56d\ub85c\uc778\uc9c0\uc5d0 \uad00\ud55c \uc815\ubcf4\ub294 \ub3c8\uc758 \uc57d\uc18d\uacfc \uc9c1\uc811 \uc5f0\uacb0\ub41c\ub2e4. \ub85c\uc774\ub4dc\uc758 \uac00\uac8c\uac00 \ud765\ubbf8\ub85c\uc6b4 \uac83\uc740 \uc74c\ub8cc\uc640 \ubcf4\ud5d8\uc744 \ub2e8\uc21c\ud788 \ud55c \uc138\ud2b8\ub85c \ud314\uc558\ub2e4\ub294 \ub370 \uc788\uc9c0 \uc54a\ub2e4. \uc815\ubcf4\ub97c \uc8fc\uace0\ubc1b\uc744 \uc0ac\ub78c\uacfc \uac70\ub798\ub97c \ub17c\uc758\ud560 \uc0ac\ub78c\uc774 \ud55c\uacf3\uc5d0 \uc788\uc5c8\ub2e4\ub294 \uc810\uc774\ub2e4. \ucee4\ud53c\ud558\uc6b0\uc2a4\uc758 \ub300\ud654\uac00 \uc2e4\uc81c \uc704\ud5d8\uc744 \ud3c9\uac00\ud558\uace0 \uacc4\uc57d\uc744 \ub9fa\ub294 \uad00\uacc4\uc640 \ub9cc\ub0a0 \uc218 \uc788\uc5c8\ub2e4. \ud56d\uad6c\uc5d0\uc11c \ub4e4\ub824\uc628 \ub9d0\uc774 \uc5b8\uc81c\ub098 \uc815\ud655\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uac70\ub798\ub97c \ud310\ub2e8\ud558\ub824\uba74 \uc5b4\ub5a4 \ubc30\uc758 \uc5b4\ub5a4 \uc0ac\uac74\uc778\uc9c0 \uad6c\ubd84\ud574 \uae30\ub85d\ud560 \ud544\uc694\uac00 \uc788\ub2e4. \ud55c\uacf3\uc5d0 \uc18c\uc2dd\uc774 \ubaa8\uc778\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uadf8 \uc18c\uc2dd\uc744 \uc0ac\uc6a9\ud560 \uc218 \uc788\uac8c \uc815\ub9ac\ud55c\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub2e4\ub978 \uc885\ub958\uc758 \uc77c\uc774\ub2e4. \ub85c\uc774\uc988\uc758 \uc5ed\uc0ac\uc5d0\uc11c \uc120\ubc15 \ubaa9\ub85d\uacfc \uc7a5\ubd80\uac00 \ud568\uaed8 \ub4f1\uc7a5\ud558\ub294 \uc774\uc720\ub3c4 \uc5ec\uae30\uc5d0 \uc788\ub2e4. \ud574\uc0c1\ubcf4\ud5d8\uc758 \ubc1c\uc804\uc740 \uba4b\uc9c4 \uacc4\uc57d \ubb38\uad6c\ub9cc\uc758 \uc5ed\uc0ac\uac00 \uc544\ub2c8\uc5c8\ub2e4. \ubc30\uc758 \ucd9c\ud56d\uacfc \ub3c4\ucc29, \uc0ac\uace0\uc640 \uad6c\uc870\uc5d0 \uad00\ud55c \uc9c0\uc2dd\uc774 \ucd95\uc801\ub418\uace0 \uacf5\uc720\ub418\ub294 \uacfc\uc815\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4. \uc2dc\uac04\uc774 \ud750\ub974\uba70 \ub85c\uc774\uc988\uc640 \uad00\ub828\ub41c \uac70\ub798\uc640 \uc815\ubcf4\uc758 \uacf5\uac04\uc740 \ub354 \uc870\uc9c1\uc801\uc778 \ud615\ud0dc\ub85c \ubc1c\uc804\ud588\ub2e4. \uc720\ucee4\uc2a4\uc758 \ucc45\uc5d0\ub294 \ud6c4\ub300 \ub85c\uc5f4 \uc775\uc2a4\uccb4\uc778\uc9c0\uc758 \ubc29\ub4e4\uc774 \uc18c\uac1c\ub41c\ub2e4. \ubcf4\ud5d8\uc744 \ub9e1\ub294 \uc0ac\ub78c\ub4e4, \uc0c1\uc778\ub4e4, \uc120\uc7a5\ub4e4\uc774 \uc774\uc6a9\ud558\ub294 \uacf5\uac04\uacfc \uc120\ubc15 \uc815\ubcf4\uc758 \uc804\uc2dc\uac00 \uc124\uba85\ub41c\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc5ed\uc0ac \ub3c4\ud310\ub3c4 \uc774 \ud6c4\ub300\uc758 \uad6c\ub3c5\uc790\uc2e4\uc744 \ubcf4\uc5ec \uc900\ub2e4. 1688\ub144 \ud0c0\uc6cc \uc2a4\ud2b8\ub9ac\ud2b8\uc758 \uccab \uac00\uac8c \ub0b4\ubd80\ub97c \uc9c1\uc811 \uadf8\ub9b0 \uadf8\ub9bc\uc740 \uc544\ub2c8\ub2e4. \ucd5c\ucd08\uc758 \ucee4\ud53c\ud558\uc6b0\uc2a4\uc640 \ub4a4\uc5d0 \ub9c8\ub828\ub41c \ud070 \uc815\ubcf4\uc2e4 \uc0ac\uc774\uc5d0\ub294 \uc2dc\uac04\uacfc \uc870\uc9c1\uc758 \ubcc0\ud654\uac00 \uc788\uc5c8\ub2e4. \uadf8\ub9bc\uc744 \ubcfc \ub54c \uadf8 \uac04\uaca9\uc744 \uae30\uc5b5\ud558\uba74 \uc88b\ub2e4. \ucc45\uc740 1848\ub144 \uc790\ub8cc\ub97c \uc778\uc6a9\ud574 \ub85c\uc774\uc988\uc758 \ud070 \uc7a5\ubd80\ub4e4\uc744 \uc124\uba85\ud55c\ub2e4. \ud55c\ucabd\uc5d0\ub294 \ub3c4\ucc29\ud588\uac70\ub098 \ud56d\ud574 \uc911 \uc18c\uc2dd\uc774 \uc804\ud574\uc9c4 \ubc30\ub4e4\uc774, \ub2e4\ub978 \ucabd\uc5d0\ub294 \ub09c\ud30c\uc640 \ud654\uc7ac, \uc2ec\ud55c \ucda9\ub3cc \uac19\uc740 \uc0ac\uac74\ub4e4\uc774 \uae30\ub85d\ub418\uc5c8\ub2e4. \ubc14\ub2e4\uc758 \uc774\uc57c\uae30\uac00 \uc11c\ub85c \ub2e4\ub978 \uc885\ub958\uc758 \uc815\ubcf4\ub85c \ubd84\ub958\ub418\uc5b4 \ub0a8\uc740 \uac83\uc774\ub2e4. \ubc29 \uc548\uc5d0\ub294 \ubc14\ub78c\uacfc \ube44\ub97c \uc0b4\ud53c\ub294 \uae30\uad6c\ub3c4 \uc788\uc5c8\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \uc774\ub294 17\uc138\uae30 \ucd5c\ucd08\uc758 \uac00\uac8c\uc5d0 \uadf8\ub7f0 \uc7a5\ube44\uac00 \ubaa8\ub450 \uc788\uc5c8\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ud6c4\ub300\uc758 \uc804\ubb38 \uacf5\uac04\uc5d0\uc11c\ub294 \uc120\ubc15 \uc18c\uc2dd\ubfd0 \uc544\ub2c8\ub77c \ud56d\ud574\uc640 \uad00\ub828\ub41c \uc870\uac74\ub3c4 \ud568\uaed8 \uad00\ucc30\ud588\ub2e4\ub294 \uc124\uba85\uc73c\ub85c \uc77d\uc5b4\uc57c \ud55c\ub2e4. \uc720\ucee4\uc2a4\ub294 \ub85c\uc774\uc988\ub97c \ub9e4\uc6b0 \uc911\uc694\ud55c \uae30\uad00\uc73c\ub85c \ub192\uc774 \ud3c9\uac00\ud55c\ub2e4. \ub2e4\ub9cc 1922\ub144\uc758 \ucc45\uc5d0 \uc801\ud78c \uaddc\ubaa8\uc640 \ud65c\ub3d9\ub7c9\uc744 \uc624\ub298\uc758 \uc218\uce58\ucc98\ub7fc \ubc1b\uc544\ub4e4\uc77c \uc218\ub294 \uc5c6\ub2e4. \uadf8\uac00 \ubc14\ub77c\ubcf8 \uc2dc\uc810\uacfc, \uadf8\uac00 \ub2e4\uc2dc \uc778\uc6a9\ud55c 19\uc138\uae30 \uc790\ub8cc\uc758 \uc2dc\uc810\ub3c4 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ub85c\uc774\uc988\uc758 \ud604\uc7ac \uad6c\uc870\uc640 \uac1c\ubcc4 \ubcf4\ud5d8 \uacc4\uc57d\uc758 \uc870\uac74\uc744 \uc774 \uae00\uc5d0\uc11c \uc124\uba85\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5ec\uae30\uc11c\ub294 \ubc14\ub2e4\uc758 \uc815\ubcf4\ub97c \uacf5\uc720\ud558\ub358 \uc0ac\ub78c\ub4e4\uc774 \uac70\ub798\ub97c \uc704\ud55c \uc804\ubb38\uc801\uc778 \uad00\uacc4\ub97c \ub9cc\ub4e4\uc5b4 \uac04 \uc5ed\uc0ac\ub97c \uc0b4\ud3b4\ubcf8\ub2e4. \ucee4\ud53c\ud558\uc6b0\uc2a4\uac00 \uae08\uc735\uc758 \uc774\ub984\uc73c\ub85c \ub0a8\uc740 \uc774\uc720\ub97c \uc774\ud574\ud558\ub294 \ub370 \ucd08\uc810\uc744 \ub9de\ucd94\uba74 \ub41c\ub2e4. \ub85c\uc774\uc988\uc758 \uc774\ub984\uc744 \ub4e3\uace0 \uac70\ub300\ud55c \uac74\ubb3c\ub9cc \ub5a0\uc62c\ub838\ub2e4\uba74 \uc791\uc740 \uac00\uac8c\uc640 \uc190\uc73c\ub85c \uc4f4 \uc120\ubc15 \ubaa9\ub85d\ub3c4 \ud568\uaed8 \ub193\uc544 \ubcf4\uc790. \uc704\ud5d8\uc744 \ub098\ub204\ub294 \uc57d\uc18d \ub4a4\uc5d0\ub294 \ubb34\uc5c7\uc774 \uc77c\uc5b4\ub0ac\ub294\uc9c0 \uc54c\uae30 \uc704\ud55c \uae30\ub85d\uc774 \uc788\uc5c8\ub2e4. \uae08\uc735\uc740 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc22b\uc790\ubfd0 \uc544\ub2c8\ub77c \uc0ac\ub78c\uc774 \ubaa8\uc5ec \uc18c\uc2dd\uc744 \ud655\uc778\ud558\ub294 \uc7a5\uc18c\uc5d0\uc11c\ub3c4 \uc790\ub77c\ub0ac\ub2e4. \uc774 \uc774\uc57c\uae30\ub294 \ubcf4\ud5d8\uc774 \ucee4\ud53c \ud55c \uc794\uc5d0\uc11c \uac11\uc790\uae30 \ubc1c\uba85\ub418\uc5c8\ub2e4\ub294 \uc804\uc124\uc774 \uc544\ub2c8\ub2e4. \ubc14\ub2e4\uc5d0 \ub300\ud55c \uc624\ub798\ub41c \uac70\ub798\uac00 \ud2b9\uc815\ud55c \ub9cc\ub0a8\uc758 \uc7a5\uc18c\ub97c \ud1b5\ud574 \ub354 \uc870\uc9c1\uc801\uc73c\ub85c \uc5f0\uacb0\ub41c \uacfc\uc815\uc774\ub2e4. \ub7f0\ub358\uc758 \ucee4\ud53c\ud558\uc6b0\uc2a4\ub294 \ub204\uac00 \uc5b4\ub5a4 \uc18c\uc2dd\uc744 \ud568\uaed8 \uc77d\ub294\uc9c0\uac00 \uc0c8\ub85c\uc6b4 \uc2dc\uc7a5\uc758 \uae30\ubc18\uc774 \ub420 \uc218 \uc788\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4."}, {"id": "loan-payment-principal-interest", "title": "\ub9e4\ub2ec \uac1a\ub294\ub370 \uc65c \uc6d0\uae08\uc740 \uc870\uae08 \uc904\uc5b4\ub4e4\uae4c", "summary": "\uac19\uc740 \uc6d4 \ub0a9\uc785\uc561 \uc18d\uc5d0\uc11c \uc774\uc790\uc640 \uc6d0\uae08\uc758 \ube44\uc911\uc774 \ub2ec\ub77c\uc9c0\ub294 \uc774\uc720\ub97c \uc791\uc740 \uac00\uc0c1 \ub300\ucd9c\ub85c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "finance", "category_title": "Finance", "subcategory": "Banking", "url": "stories/loan-payment-principal-interest/index.html", "image": "media/loan-payment-principal-interest.png", "alt": "\uc9d1 \uc548 \uc2dd\ud0c1\uc5d0\uc11c \uacc4\uc0b0\uae30\uc640 \uac00\uacc4\ubd80\ub97c \ubcf4\uba70 \ub0a9\uc785 \ub0b4\uc5ed\uc744 \uc0b4\ud3b4\ubcf4\ub294 \uc0c1\uc0c1 \uc7a5\uba74.", "text": "\ub9e4\ub2ec \uac1a\ub294\ub370 \uc65c \uc6d0\uae08\uc740 \uc870\uae08 \uc904\uc5b4\ub4e4\uae4c \uc0c1\ud658\uc561 \uc548\uc5d0\uc11c \uc790\ub9ac\ub97c \ubc14\uafb8\ub294 \uc6d0\uae08\uacfc \uc774\uc790 \uac19\uc740 \uc6d4 \ub0a9\uc785\uc561 \uc18d\uc5d0\uc11c \uc774\uc790\uc640 \uc6d0\uae08\uc758 \ube44\uc911\uc774 \ub2ec\ub77c\uc9c0\ub294 \uc774\uc720\ub97c \uc791\uc740 \uac00\uc0c1 \ub300\ucd9c\ub85c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Banking \uae08\uc735 \uba87 \ub2ec\uc9f8 \ube60\uc9d0\uc5c6\uc774 \ub300\ucd9c\uc744 \uac1a\uc558\ub2e4. \uadf8\ub7f0\ub370 \ub0a8\uc740 \uc6d0\uae08\uc744 \ubcf4\ub2c8 \ub0b8 \ub3c8\ub9cc\ud07c \ud06c\uac8c \uc904\uc9c0 \uc54a\uc558\ub2e4. \ub3c8\uc774 \uc5b4\ub514\ub85c \uac04 \uac83\uc77c\uae4c. \ub9e4\ub2ec \ubcf4\ub0b4\ub294 \uae08\uc561\uc774 \ubaa8\ub450 \ube4c\ub9b0 \uc6d0\uae08\uc744 \uc904\uc774\ub294 \ub370 \uc4f0\uc774\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc77c\uc815 \ubd80\ubd84\uc740 \ub3c8\uc744 \ube4c\ub9b0 \ub370 \ub300\ud55c \uc774\uc790\ub85c \ub098\uac00\uae30 \ub54c\ubb38\uc774\ub2e4. \ub300\ucd9c \uc0c1\ud658\ud45c\ub294 \uc22b\uc790\uac00 \ub9ce\uc544\uc11c \ub0af\uc124\uc9c0\ub9cc, \ud55c \ub2ec\uc758 \ub0a9\uc785\uc561\uc744 \uc6d0\uae08\uacfc \uc774\uc790\ub85c \ub098\ub204\uc5b4 \ubcf4\uba74 \uc77d\ub294 \uae38\uc774 \uc0dd\uae34\ub2e4. \uc5ec\uae30\uc11c\ub294 \uace0\uc815\ub41c \uc774\uc790\uc728\uacfc \uc815\ud574\uc9c4 \uae30\uac04\uc744 \uac00\uc9c4 \ub2e8\uc21c\ud55c \uac00\uc0c1 \ub300\ucd9c\uc744 \uc0ac\uc6a9\ud55c\ub2e4. \uc2e4\uc81c \uc0c1\ud488\uc758 \uae08\ub9ac\ub098 \uacc4\uc57d \uc870\uac74\uc744 \ucd94\ucc9c\ud558\ub294 \uae00\uc740 \uc544\ub2c8\ub2e4. \uc6d0\uae08\uc740 \ube4c\ub9b0 \ub3c8\uc758 \uae30\ubcf8 \uae08\uc561\uc774\uace0, \uc774\uc790\ub294 \uadf8 \ub3c8\uc744 \ube4c\ub9ac\ub294 \ub370 \ub4dc\ub294 \ube44\uc6a9\uc774\ub2e4. \ub0a9\uc785\uc561 \uc548\uc5d0\ub294 \ub450 \uac00\uc9c0\uac00 \ud568\uaed8 \ub4e4\uc5b4\uac08 \uc218 \uc788\ub2e4. \uc2dd\ub2f9\uc5d0\uc11c \ub0b8 \ub3c8 \uc804\uccb4\uac00 \uc7ac\ub8cc\ube44\ub9cc\uc740 \uc544\ub2cc \uac83\ucc98\ub7fc, \uac1a\uc558\ub2e4\ub294 \ub9d0 \ud558\ub098 \uc548\uc5d0 \ub2e4\ub978 \uc131\uaca9\uc758 \ub3c8\uc774 \uc11e\uc5ec \uc788\ub2e4. \ubbf8\uad6d \uc18c\ube44\uc790\uae08\uc735\ubcf4\ud638\uad6d\uc758 \uc0c1\ud658 \uacc4\uc0b0 \uc548\ub0b4\ub3c4 \uc815\uae30 \ub0a9\uc785\uae08\uc758 \uc77c\ubd80\ub294 \uc6d0\uae08\uc5d0, \uc77c\ubd80\ub294 \uc774\uc790\uc5d0 \uc801\uc6a9\ub41c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc2e4\uc81c \uacc4\uc57d\uc5d0\ub294 \uc218\uc218\ub8cc\ub098 \ub2e4\ub978 \ud56d\ubaa9\uc774 \ubd99\uc744 \uc218 \uc788\uc73c\ubbc0\ub85c \uc5ec\uae30\uc11c\ub294 \uadf8\ub7f0 \ube44\uc6a9\uc744 \uc81c\uc678\ud55c\ub2e4. \uba3c\uc800 \uac00\uc7a5 \ub2e8\uc21c\ud55c \uad6c\uc870\ub97c \uc774\ud574\ud558\ub824\ub294 \uac83\uc774\ub2e4. 120\ub9cc \uc6d0\uc744 \ube4c\ub838\uace0 \ub9e4\ub2ec \ub0a8\uc544 \uc788\ub294 \uc6d0\uae08\uc758 1%\ub97c \uc774\uc790\ub85c \uacc4\uc0b0\ud55c\ub2e4\uace0 \uac00\uc815\ud558\uc790. \uc5ec\uae30\uc758 1%\ub294 \uc124\uba85\uc6a9 \uc6d4 \uc774\uc790\uc728\uc774\ub2e4. \uccab \ub2ec \uc774\uc790\ub294 1\ub9cc 2\ucc9c \uc6d0\uc774\ub2e4. \ub3c8\uc744 11\ub9cc 2\ucc9c \uc6d0 \ubcf4\ub0c8\ub2e4\uba74 \uadf8\uc911 1\ub9cc 2\ucc9c \uc6d0\uc740 \uc774\uc790, \ub098\uba38\uc9c0 10\ub9cc \uc6d0\uc740 \uc6d0\uae08\uc744 \uc904\uc774\ub294 \ub370 \uc4f0\uc778\ub2e4. \uc774 \ud55c \ubc88\uc758 \ub0a9\uc785 \ub4a4 \ub0a8\uc740 \uc6d0\uae08\uc740 110\ub9cc \uc6d0\uc774\ub2e4. 120\ub9cc \uc6d0\uc5d0\uc11c \ubcf4\ub0b8 \ub3c8 \uc804\uccb4\uc778 11\ub9cc 2\ucc9c \uc6d0\uc744 \ube7c\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc6d0\uae08\uc744 \uc904\uc778 \ubd80\ubd84\ub9cc \ube7c\uc57c \ud55c\ub2e4. \uc0c1\ud658\ud45c\ub97c \uc77d\uc744 \ub54c \uba3c\uc800 \ub0a9\uc785\uc561\uacfc \uc6d0\uae08 \uc0c1\ud658\uc561\uc744 \ub2e4\ub978 \uce78\uc73c\ub85c \ubcf4\ub294 \uc774\uc720\ub2e4. \ub9e4\ub2ec \uc6d0\uae08\uc744 10\ub9cc \uc6d0\uc529 \uc904\uc778\ub2e4\uace0 \uc815\ud558\uba74 \ub458\uc9f8 \ub2ec\uc740 110\ub9cc \uc6d0\uc5d0 \ub300\ud55c \uc774\uc790 1\ub9cc 1\ucc9c \uc6d0\uc744 \ub354\ud574 11\ub9cc 1\ucc9c \uc6d0\uc744 \ub0b8\ub2e4. \uc14b\uc9f8 \ub2ec\uc740 \uc6d0\uae08 \uc794\uc561\uc774 \ub2e4\uc2dc \uc904\uc5b4 \uc774\uc790\ub3c4 \ub354 \uc791\uc544\uc9c4\ub2e4. \uc6d0\uae08 \uc0c1\ud658\uc561\uc740 \uac19\uc9c0\ub9cc \uc804\uccb4 \uc6d4 \ub0a9\uc785\uc561\uc740 \uc810\uc810 \uac10\uc18c\ud55c\ub2e4. \uc774\ub97c \uc6d0\uae08\uade0\ub4f1 \uc0c1\ud658\uc774\ub77c\uace0 \ubd80\ub978\ub2e4. \uc6d0\uae08\uc744 \uc77c\uc815\ud558\uac8c \ub098\ub204\uace0 \uadf8\ub54c\uadf8\ub54c \ub0a8\uc740 \uae08\uc561\uc758 \uc774\uc790\ub97c \ub354\ud558\ub294 \ubc29\uc2dd\uc774\ub2e4. \uac19\uc740 \uc6d0\ub9ac\ub97c \ub05d\uae4c\uc9c0 \uc801\uc6a9\ud558\uba74 \ub9c8\uc9c0\ub9c9\uc5d0\ub294 10\ub9cc \uc6d0\uc758 \uc6d0\uae08\uc5d0 \ub300\ud55c \uc774\uc790 1\ucc9c \uc6d0\uc774 \ubd99\ub294\ub2e4. \uc55e\uc5d0\uc11c \ub354 \ub9ce\uc774 \ub0b4\uace0 \ub4a4\ub85c \uac08\uc218\ub85d \ubd80\ub2f4\uc774 \uc904\uc5b4\ub4dc\ub294 \ubaa8\uc591\uc774 \ub41c\ub2e4. \ub2e4\ub978 \ubc29\ubc95\uc740 \ub9e4\ub2ec \ub0b4\ub294 \uc6d0\uae08\uacfc \uc774\uc790\uc758 \ud569\uacc4\ub97c \uc77c\uc815\ud558\uac8c \ub9de\ucd94\ub294 \uac83\uc774\ub2e4. \uac19\uc740 \uac00\uc0c1 \uc870\uac74\uc73c\ub85c 12\uac1c\uc6d4\uc5d0 \ub098\ub204\uba74 \uc6d4 \ub0a9\uc785\uc561\uc740 \uc57d 10\ub9cc 6,619\uc6d0\uc774 \ub41c\ub2e4. \uc18c\uc218\uc810\uacfc \ub9c8\uc9c0\ub9c9 \ub2ec\uc758 \uc870\uc815\uc740 \ub2e8\uc21c\ud654\ud55c \uacc4\uc0b0\uc774\ub2e4. \uccab \ub2ec\uc5d0\ub294 \uadf8\uc911 \uc774\uc790 1\ub9cc 2\ucc9c \uc6d0\uc744 \ube7c\uace0 \uc57d 9\ub9cc 4,619\uc6d0\uc774 \uc6d0\uae08\uc744 \uc904\uc778\ub2e4. \ub2e4\uc74c \ub2ec\uc5d0\ub294 \ub0a8\uc740 \uc6d0\uae08\uc774 \uc791\uc544\uc838 \uc774\uc790\ub3c4 \uc904\uc5b4\ub4e0\ub2e4. \ucd1d\uc561\uc740 \ube44\uc2b7\ud558\uac8c \uc720\uc9c0\ud558\ubbc0\ub85c \uc774\ubc88\uc5d0\ub294 \uc6d0\uae08\uc744 \uac1a\ub294 \ubd80\ubd84\uc774 \uc870\uae08 \ub354 \ucee4\uc9c4\ub2e4. \uac19\uc740 \uae08\uc561\uc744 \ub0b4\uba74\uc11c \uc548\uc758 \uad6c\uc131\uc740 \uacc4\uc18d \ubc14\ub00c\ub294 \uac83\uc774\ub2e4. \uc6d0\ub9ac\uae08\uc740 \uc6d0\uae08\uacfc \uc774\uc790\ub97c \ud569\uce5c \ub9d0\uc774\ub2e4. \uc6d0\ub9ac\uae08\uade0\ub4f1 \uc0c1\ud658\uc740 \uadf8 \ud569\uacc4\ub97c \uc77c\uc815\ud558\uac8c \ub9de\ucd94\ub294 \ubc29\uc2dd\uc774\uc9c0 \ub9e4\ub2ec \uc6d0\uae08\uc744 \uac19\uc740 \uae08\uc561\uc529 \uc904\uc778\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \ub450 \ubc29\uc2dd\uc758 \uc774\ub984\uc740 \ube44\uc2b7\ud558\uc9c0\ub9cc \uade0\ub4f1\ud558\uac8c \ub9cc\ub4dc\ub294 \ub300\uc0c1\uc774 \ub2e4\ub974\ub2e4. \ucd08\uae30\uc5d0\ub294 \ub0a8\uc544 \uc788\ub294 \uc6d0\uae08\uc774 \ud06c\uae30 \ub54c\ubb38\uc5d0 \uc774\uc790\uc758 \ube44\uc911\ub3c4 \uc0c1\ub300\uc801\uc73c\ub85c \ud06c\ub2e4. \ub4a4\ub85c \uac08\uc218\ub85d \uc6d0\uae08 \uc0c1\ud658\uc758 \ube44\uc911\uc774 \ucee4\uc9c4\ub2e4. \ub530\ub77c\uc11c \ucd08\ubc18 \uba87 \ub2ec\uc758 \ucd1d \ub0a9\uc785\uc561\ub9cc \ub354\ud574 \ucc98\uc74c \ube4c\ub9b0 \ub3c8\uc5d0\uc11c \ube7c\uba74 \uc2e4\uc81c \uc794\uc561\uacfc \ub9de\uc9c0 \uc54a\ub294\ub2e4. \uc774\uc790\uac00 \ucc28\uc9c0\ud588\ub358 \ubd80\ubd84\uc744 \ub530\ub85c \ubcf4\uc544\uc57c \ud55c\ub2e4. \uac19\uc740 120\ub9cc \uc6d0\uacfc \uc6d4 1%\ub77c\ub294 \uc870\uac74\uc5d0\uc11c \uc6d0\ub9ac\uae08\uade0\ub4f1 \uc0c1\ud658 \uae30\uac04\uc744 24\uac1c\uc6d4\ub85c \ub298\ub9ac\uba74 \uc6d4 \ub0a9\uc785\uc561\uc740 \uc57d 5\ub9cc 6,488\uc6d0\uc774 \ub41c\ub2e4. \ub9e4\ub2ec \ub0b4\ub294 \ub3c8\uc740 \uc904\uc9c0\ub9cc \ub354 \uc624\ub798 \ub0b8\ub2e4. \uc774 \uac00\uc815\uc5d0\uc11c \ucd1d\uc774\uc790\ub294 12\uac1c\uc6d4 \ub54c \uc57d 7\ub9cc 9,423\uc6d0, 24\uac1c\uc6d4 \ub54c \uc57d 15\ub9cc 5,716\uc6d0\uc774\ub2e4. \uc6d4 \uae08\uc561\uc774 \uc791\ub2e4\ub294 \uac83\uacfc \uc804\uccb4 \ube44\uc6a9\uc774 \uc801\ub2e4\ub294 \uac83\uc740 \uac19\uc740 \ub9d0\uc774 \uc544\ub2c8\ub2e4. \ube4c\ub9b0 \ub3c8\uc774 \ub0a8\uc544 \uc788\ub294 \uc2dc\uac04\uc774 \uae38\uc5b4\uc9c0\uba74 \uc774\uc790\ub97c \ub0b4\ub294 \uae30\uac04\ub3c4 \uae38\uc5b4\uc9c4\ub2e4. \ubb3c\ub860 \uc2e4\uc81c \uc120\ud0dd\uc5d0\uc11c\ub294 \uac01\uc790\uc758 \ud604\uae08 \ud750\ub984\uacfc \uacc4\uc57d \uc870\uac74\ub3c4 \uc911\uc694\ud558\ub2e4. \uc22b\uc790 \ud558\ub098\ub9cc \ubcf4\uace0 \uc5b4\ub290 \uae30\uac04\uc774 \ub204\uad6c\uc5d0\uac8c\ub098 \uc815\ub2f5\uc774\ub77c\uace0 \ud560 \uc218\ub294 \uc5c6\ub2e4. \uccab\uc9f8, \uc774\ubc88\uc5d0 \ub0b8 \ub3c8 \uc911 \uc774\uc790\ub294 \uc5bc\ub9c8\uc778\uac00. \ub458\uc9f8, \uc2e4\uc81c\ub85c \uc6d0\uae08\uc740 \uc5bc\ub9c8 \uc904\uc5c8\ub294\uac00. \uc14b\uc9f8, \ub0a9\uc785 \ub4a4 \ub0a8\uc740 \uc6d0\uae08\uc740 \uc5bc\ub9c8\uc778\uac00. \uc774 \uc138 \uac00\uc9c0\ub97c \uc21c\uc11c\ub300\ub85c \ubcf4\uba74 \uae38\uac8c \uc774\uc5b4\uc9c0\ub294 \ud45c\ub3c4 \uac19\uc740 \uad00\uacc4\uc758 \ubc18\ubcf5\uc73c\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uc2e4\uc81c \uacc4\uc57d\uc758 \ubcc0\ub3d9 \uae08\ub9ac\ub098 \uc720\uc608 \uae30\uac04, \uc77c\uc218 \uacc4\uc0b0\uacfc \uc218\uc218\ub8cc, \uc911\ub3c4 \uc0c1\ud658 \uc870\uac74\uc740 \uc774 \ub2e8\uc21c\ud55c \uc0ac\ub840\uc640 \ub2e4\ub97c \uc218 \uc788\ub2e4. \ubbf8\uad6d \uae30\uad00\uc758 \uacc4\uc0b0 \uc124\uba85\uc744 \ud55c\uad6d\uc758 \ud2b9\uc815 \uc0c1\ud488 \uc57d\uad00\uc73c\ub85c \uc62e\uaca8 \uc77d\uc5b4\uc11c\ub3c4 \uc548 \ub41c\ub2e4. \uc774 \uae00\uc774 \uc124\uba85\ud558\ub294 \uac83\uc740 \uae30\ubcf8 \uad6c\uc870\uc774\uba70 \uc2e4\uc81c \uae08\uc561\uc740 \ud574\ub2f9 \uacc4\uc57d\uacfc \uc0c1\ud658\ud45c\uac00 \uae30\uc900\uc774\ub2e4. \uc794\uc561\uc744 \ubcf4\uace0 \uc2e4\ub9dd\ud588\ub2e4\uba74 \uc804\uccb4 \ub0a9\uc785\uae08\uacfc \uc6d0\uae08 \uc0c1\ud658\uc561\uc744 \uac19\uc740 \uac83\uc73c\ub85c \uc0dd\uac01\ud558\uc9c0 \uc54a\uc558\ub294\uc9c0 \uba3c\uc800 \ud655\uc778\ud560 \uc218 \uc788\ub2e4. \ub0b8 \ub3c8\uc774 \ubaa8\ub450 \uc6d0\uae08\uc73c\ub85c \uac00\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc774\uc790\ub77c\ub294 \ube44\uc6a9\uacfc \ub098\ub258\uc5c8\ub2e4\ub294 \uc810\uc744 \uc54c\uba74 \uc22b\uc790\uac00 \uc870\uae08 \ub35c \ubd88\uce5c\uc808\ud574\uc9c4\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac00\uacc4\ubd80 \uadf8\ub9bc\uc740 AI\uac00 \ub9cc\ub4e0 \uc0dd\ud65c \uc7a5\uba74\uc774\uba70 \uc2e4\uc81c \uc0c1\ud658\ud45c\uac00 \uc544\ub2c8\ub2e4. \uc774\ud574\uc758 \ud575\uc2ec\uc740 \uadf8\ub9bc \uc18d \uacc4\uc0b0\uae30\ubcf4\ub2e4 \ud55c \ub2ec\uc758 \ub3c8\uc744 \ub450 \ubd80\ubd84\uc73c\ub85c \ub098\ub204\uc5b4 \ubcf4\ub294 \ub370 \uc788\ub2e4. \uac19\uc740 \uc561\uc218\ub97c \uafb8\uc900\ud788 \ub0b4\ub294 \ub3d9\uc548\uc5d0\ub3c4 \uc6d0\uae08\uacfc \uc774\uc790\ub294 \uc11c\ub85c \ub2e4\ub978 \uc18d\ub3c4\ub85c \uc790\ub9ac\ub97c \ubc14\uafb8\uace0 \uc788\ub2e4."}, {"id": "south-sea-bubble-promise-and-shares", "title": "\ub0a8\ud574\ud68c\uc0ac \u2014 \ubc14\ub2e4 \uac74\ub108\uc758 \uafc8\uc740 \uc5b4\ub5bb\uac8c \uc8fc\uac00\uac00 \ub418\uc5c8\uc744\uae4c", "summary": "\ub0a8\ud574\ud68c\uc0ac \uac70\ud488\uc744 \ud68c\uace0\ud55c 1852\ub144\ud310 \uc5ed\uc0ac\uc11c\uc640 \ud638\uac00\uc2a4\uc758 \ud48d\uc790 \ub3c4\ud310\uc744 \ud1b5\ud574 \ubb34\uc5ed\u00b7\uad6d\uac00 \ubd80\ucc44\u00b7\uc8fc\uac00\uc758 \uad00\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "finance", "category_title": "Finance", "subcategory": "Investment", "url": "stories/south-sea-bubble-promise-and-shares/index.html", "image": "media/south-sea-bubble-promise-and-shares.png", "alt": "\ud638\uac00\uc2a4\uc758 \ub0a8\ud574\ud68c\uc0ac \ud48d\uc790 \ub3c4\ud310. \uc911\uc559\uc758 \ud68c\uc804 \uae30\uad6c\ub97c \ud0c4 \uc0ac\ub78c\ub4e4\uacfc \uc8fc\ubcc0\uc758 \uad70\uc911.", "text": "\ub0a8\ud574\ud68c\uc0ac \u2014 \ubc14\ub2e4 \uac74\ub108\uc758 \uafc8\uc740 \uc5b4\ub5bb\uac8c \uc8fc\uac00\uac00 \ub418\uc5c8\uc744\uae4c 1720\ub144 \ub7f0\ub358\uc5d0\uc11c \ubb34\uc5ed\uc758 \uae30\ub300\uc640 \uad6d\uac00\uc758 \ube5a\uc774 \ub9cc\ub0ac\ub2e4 \ub0a8\ud574\ud68c\uc0ac \uac70\ud488\uc744 \ud68c\uace0\ud55c 1852\ub144\ud310 \uc5ed\uc0ac\uc11c\uc640 \ud638\uac00\uc2a4\uc758 \ud48d\uc790 \ub3c4\ud310\uc744 \ud1b5\ud574 \ubb34\uc5ed\u00b7\uad6d\uac00 \ubd80\ucc44\u00b7\uc8fc\uac00\uc758 \uad00\uacc4\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Investment \uae08\uc735 \ub0a8\uc544\uba54\ub9ac\uce74\uc758 \uae08\uacfc \uc740, \uba3c \ud56d\uad6c\uc5d0\uc11c \ub3cc\uc544\uc62c \ubc30, \uc9c0\uae08\ubcf4\ub2e4 \ud6e8\uc52c \ubd80\uc720\ud574\uc9c8 \ubbf8\ub798. 18\uc138\uae30 \ucd08 \ub7f0\ub358\uc5d0\uc11c \ub0a8\ud574\ud68c\uc0ac\ub77c\ub294 \uc774\ub984\uc5d0\ub294 \uc774\ub7f0 \uc774\ubbf8\uc9c0\uac00 \ubd99\uc5c8\ub2e4. \uc544\uc9c1 \ucda9\ubd84\ud788 \uc774\ub8e8\uc5b4\uc9c0\uc9c0 \uc54a\uc740 \uac70\ub798\uc758 \uac00\ub2a5\uc131\uc774 \uc0ac\ub78c\ub4e4\uc758 \ub208\uc55e\uc5d0\uc11c \ub3c8\uc758 \uac12\uc73c\ub85c \ubc14\ub00c\uc5c8\ub2e4. 1720\ub144\uc758 \ub0a8\ud574\ud68c\uc0ac \uac70\ud488\uc740 \ub2e8\uc21c\ud788 \ub0af\uc120 \uc8fc\uc2dd\uc744 \uc88b\uc544\ud55c \uc0ac\ub78c\ub4e4\uc758 \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub2e4. \ubb34\uc5ed\uc758 \uae30\ub300\uc640 \uc601\uad6d \uc815\ubd80\uc758 \ube5a, \uc8fc\uc2dd\uc73c\ub85c \uad50\ud658\ud558\ub294 \uacc4\ud68d\uc774 \uc5bd\ud600 \uc788\uc5c8\ub2e4. \ucc30\uc2a4 \ub9e5\ucf00\uc774\uc758 \ud68c\uace0\uc801 \uc11c\uc220\uc744 \ub530\ub77c\uac00\ub418, \uc624\ub798\ub41c \ucc45\uc758 \uacfc\uc7a5\ub41c \uad70\uc911 \ubb18\uc0ac\uc640 \ud655\uc778\ud560 \uc218 \uc788\ub294 \uc0ac\uc5c5\uc758 \uad6c\uc870\ub97c \ub098\ub204\uc5b4 \uc0b4\ud3b4\ubcf4\uc790. \ub0a8\ud574\ud68c\uc0ac\ub294 1711\ub144\uc5d0 \uc124\ub9bd\ub418\uc5c8\ub2e4. \ub9e5\ucf00\uc774\ub294 \uadf8 \ucd9c\ubc1c\uc744 \uc601\uad6d\uc758 \uacf5\uacf5 \uc2e0\uc6a9\uacfc \uad70\ube44 \ub4f1\uc5d0\uc11c \uc0dd\uae34 \ubd80\ucc44\ub97c \uc815\ub9ac\ud558\ub294 \uacc4\ud68d\uacfc \uc5f0\uacb0\ud574 \uc124\uba85\ud55c\ub2e4. \ud68c\uc0ac\ub294 \uc815\ubd80\uc758 \ucc44\ubb34\ub97c \ub9e1\uace0 \uadf8\uc5d0 \ub530\ub978 \uc9c0\uae09\uc744 \ubc1b\ub294 \uae08\uc735\uc801 \uc5ed\ud560\uc744 \uac00\uc84c\ub2e4. \uba3c \ubc14\ub2e4\uc5d0\uc11c \ubb3c\uac74\ub9cc \uc2e4\uc5b4 \uc624\ub294 \ud68c\uc0ac\ub85c \ubcf4\uba74 \uc2dc\uc791\ubd80\ud130 \uc911\uc694\ud55c \ubd80\ubd84\uc774 \ube60\uc9c4\ub2e4. \ub3d9\uc2dc\uc5d0 \ud68c\uc0ac\uc5d0\ub294 \uc2a4\ud398\uc778\ub839 \uc544\uba54\ub9ac\uce74\uc640\uc758 \ubb34\uc5ed\uc5d0 \uad00\ud55c \uae30\ub300\uac00 \ubd99\uc5c8\ub2e4. \uc815\ubd80\uc640 \uad00\uacc4\ub97c \ub9fa\uc740 \uc0ac\uc5c5\uc774\ub77c\ub294 \uc0ac\uc2e4, \ubc14\ub2e4 \uac74\ub108 \ubd80\uc5d0 \ub300\ud55c \uc774\ubbf8\uc9c0\uac00 \ud568\uaed8 \uc774\ub984\uc758 \ubb34\uac8c\ub97c \ud0a4\uc6e0\ub2e4. \uad6d\uac00\uc758 \uc57d\uc18d\uacfc \uc0c1\uc5c5\uc758 \uac00\ub2a5\uc131\uc740 \uc11c\ub85c \ub2e4\ub978 \uac83\uc774\uc5c8\uc9c0\ub9cc \uc0ac\ub78c\ub4e4\uc758 \uae30\ub300 \uc18d\uc5d0\uc11c\ub294 \uac00\uae4c\uc774 \ub193\uc77c \uc218 \uc788\uc5c8\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \uae30\ub300\ud55c \uc790\uc720\ub85c\uc6b4 \ubb34\uc5ed\uacfc \uc2e4\uc81c\ub85c \ud5c8\uc6a9\ub41c \uac70\ub798\uc758 \ubc94\uc704\ub294 \uac19\uc9c0 \uc54a\uc558\ub2e4. \ub9e5\ucf00\uc774\ub294 \uc2a4\ud398\uc778\uacfc\uc758 \ud611\uc0c1 \uacb0\uacfc\uac00 \uc601\uad6d\uc5d0\uc11c \ubd80\ud480\ub824\uc9c4 \uc804\ub9dd\ubcf4\ub2e4 \uc81c\ud55c\uc801\uc774\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud56d\uad6c \uc774\ub984\uc744 \ub298\uc5b4\ub193\ub294 \uac83\uacfc \uadf8\uacf3\uc5d0\uc11c \ub9c8\uc74c\uaecf \uac70\ub798\ud560 \uad8c\ub9ac\ub97c \uc5bb\ub294 \uac83\uc740 \ub2e4\ub978 \uc77c\uc774\uc5c8\ub2e4. \uc774 \uc0ac\uc5c5\uc5d0\ub294 \ub178\uc608\ud654\ub41c \uc544\ud504\ub9ac\uce74\uc778\uc744 \uc2a4\ud398\uc778 \uc2dd\ubbfc\uc9c0\uc5d0 \uacf5\uae09\ud558\ub294 \uc544\uc2dc\uc5d4\ud1a0 \uacc4\uc57d\ub3c4 \ud3ec\ud568\ub418\uc5c8\ub2e4. \uc624\ub798\ub41c \uae08\uc735\uc0ac\ub97c \ud48d\ubd80\ud55c \uc0c1\ud488\uc774 \uc624\uac00\ub294 \ub0ad\ub9cc\uc73c\ub85c\ub9cc \ubcfc \uc218 \uc5c6\ub294 \uc774\uc720\ub2e4. \ub2f9\uc2dc\uc758 \uc774\uc775\uc5d0 \uad00\ud55c \uacc4\uc0b0 \uc548\uc5d0\ub294 \uc0ac\ub78c\uc744 \uac15\uc81c\ub85c \uac70\ub798\ud558\ub294 \uc2dd\ubbfc\uc9c0 \uc9c8\uc11c\ub3c4 \ub4e4\uc5b4 \uc788\uc5c8\ub2e4. \ud68c\uc0ac\uc758 \uc774\ub984 \ub54c\ubb38\uc5d0 \ud22c\uc790\uc790\ub294 \ub0a8\ubbf8 \ubb34\uc5ed\uc774 \ubc8c\uc5b4\ub2e4 \uc904 \ud070 \uc774\uc775\uc744 \ub5a0\uc62c\ub9b4 \uc218 \uc788\uc5c8\ub2e4. \uadf8\ub7ec\ub098 \ub9e5\ucf00\uc774\uc758 \uc124\uba85\uc5d0\uc11c \ud68c\uc0ac\uc758 \uae08\uc735\uc801 \ud65c\ub3d9\uacfc \uc815\ubd80\uc5d0\uc11c \ubc1b\ub294 \uc9c0\uae09\uc740 \uc911\uc694\ud55c \ube44\uc911\uc744 \ucc28\uc9c0\ud55c\ub2e4. \ubb34\uc5ed\uc774 \ud06c\uac8c \ubc88\uc131\ud558\uc9c0 \uc54a\uc544\ub3c4 \ub2e4\ub978 \uad6c\uc870\ub85c \uc218\uc785\uc774 \uc0dd\uae38 \uc218 \uc788\uc5c8\ub2e4. \uadf8\ub798\uc11c \ud68c\uc0ac\uac00 \ubb34\uc5c7\uc744 \ud574\uc11c \ub3c8\uc744 \ubc84\ub294\uc9c0\uc640 \uc0ac\ub78c\ub4e4\uc774 \uadf8 \ud68c\uc0ac\uc5d0\uc11c \ubb34\uc5c7\uc744 \uae30\ub300\ud558\ub294\uc9c0\ub97c \ub530\ub85c \ubb3c\uc5b4\uc57c \ud55c\ub2e4. \ub0a8\ud574\ud68c\uc0ac\uc758 \uc5ed\uc0ac\ub294 \ubc14\ub85c \uadf8 \uac04\uaca9\uc774 \ucee4\uc9c8 \uc218 \uc788\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ud654\ub824\ud55c \uc774\ub984\uc774 \uc2e4\uc81c \ud604\uae08\uc758 \ud750\ub984\uc744 \uc815\ud655\ud788 \uc694\uc57d\ud574 \uc8fc\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. 1720\ub144\uc5d0\ub294 \uad6d\uac00 \ubd80\ucc44\ub97c \ud68c\uc0ac \uc8fc\uc2dd\uacfc \uc5f0\uacb0\ud574 \uc804\ud658\ud558\ub294 \ub354 \ud070 \uacc4\ud68d\uc774 \ucd94\uc9c4\ub418\uc5c8\ub2e4. \ucc44\uad8c\uc744 \uac00\uc9c4 \uc0ac\ub78c\uc5d0\uac8c \ud68c\uc0ac\uc758 \uc9c0\ubd84\uc73c\ub85c \uc62e\uae38 \uc120\ud0dd\uc744 \uc81c\uc2dc\ud558\ub294 \uad6c\uc870\uc600\ub2e4. \uc8fc\uac00\uac00 \ub192\uc744\uc218\ub85d \uadf8\ub7f0 \uad50\ud658\uc758 \uc870\uac74\uacfc \ud68c\uc0ac\uc758 \uacc4\ud68d\uc744 \uc720\ub9ac\ud558\uac8c \ub9cc\ub4e4 \uc5ec\uc9c0\uac00 \uc788\uc5c8\ub2e4. \uc774 \ub54c\ubb38\uc5d0 \uc8fc\uc2dd\uc758 \uc778\uae30\uac00 \uc0ac\uc5c5\uc758 \uacb0\uacfc\ub9cc \ub4a4\ub530\ub974\ub294 \uc9c0\ud45c\uac00 \uc544\ub2c8\ub77c \uacc4\ud68d\uc744 \uc6c0\uc9c1\uc774\ub294 \uc870\uac74\uc774 \ub418\uc5c8\ub2e4. \uac00\uaca9\uc774 \uc624\ub974\ub294 \ubaa8\uc2b5\uc744 \ubcf4\uace0 \ub354 \ub9ce\uc740 \uc0ac\ub78c\uc774 \uae30\ub300\ub97c \uac16\uace0, \uadf8 \uae30\ub300\uac00 \ub2e4\uc2dc \uac00\uaca9\uacfc \uc5f0\uacb0\ub418\ub294 \uc21c\ud658\uc774 \uc0dd\uae38 \uc218 \uc788\uc5c8\ub2e4. \ubaa8\ub4e0 \uc138\ubd80\ub97c \ud558\ub098\uc758 \uacc4\uc0b0\uc73c\ub85c \uc904\uc77c \uc218\ub294 \uc5c6\uc9c0\ub9cc \uac00\uaca9\uc758 \uc5ed\ud560\uc774 \ucee4\uc84c\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \uc8fc\uc2dd\uac12\uc774 \uc624\ub974\uba74 \uc774\ubbf8 \uc0b0 \uc0ac\ub78c\uc758 \uc774\uc775\uc774 \ub208\uc5d0 \ubcf4\uc778\ub2e4. \uc55e\uc73c\ub85c \ubb34\uc2a8 \uc77c\uc774 \uc0dd\uae38\uc9c0 \ud310\ub2e8\ud558\uae30\ubcf4\ub2e4 \uc9c0\uae08 \ub0a8\ub4e4\uc774 \uc5bb\uc740 \uc774\uc775\uc744 \ub193\uce58\uc9c0 \uc54a\ub294 \uc77c\uc774 \uae09\ud574\uc9c8 \uc218 \uc788\ub2e4. \ub9e5\ucf00\uc774\ub294 \ub2f9\uc2dc \ub7f0\ub358\uc758 \ud22c\uc790 \uc5f4\uae30\ub97c \ub9e4\uc6b0 \uadf9\uc801\uc778 \ubb38\uc7a5\uc73c\ub85c \ubb18\uc0ac\ud55c\ub2e4. \ub2e4\ub9cc \uadf8\uc758 \ucc45\uc740 \uc0ac\uac74\uc774 \ubc8c\uc5b4\uc9c4 \uc9c0 \ud55c\ucc38 \ub4a4 \uc4f0\uc600\ub2e4. \ubaa8\ub4e0 \uc2dc\ubbfc\uc774 \uac19\uc740 \uc695\ub9dd\uc5d0 \uc0ac\ub85c\uc7a1\ud614\ub2e4\uace0 \ubc1b\uc544\ub4e4\uc774\uac70\ub098, \ucc45\uc5d0 \ub098\uc624\ub294 \ud669\ub2f9\ud55c \ud22c\uc790 \uc77c\ud654\ub97c \uc804\ubd80 \uc2e4\uc81c \uacc4\uc57d\uc758 \uae30\ub85d\uc73c\ub85c \ucde8\uae09\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc720\uba85\ud55c \uc775\uba85 \uc77c\ud654\ubcf4\ub2e4 \ub0a8\ud574\ud68c\uc0ac\uc758 \uad6c\uc870\uc640 1720\ub144\uc758 \ubcc0\ud654\uc5d0 \uc9d1\uc911\ud55c\ub2e4. 1720\ub144 \uc8fc\uac00\ub294 \ud06c\uac8c \uc62c\ub790\uc9c0\ub9cc \uc5ec\ub984 \uc774\ud6c4 \ud558\ub77d\ud588\uace0, \uac00\uc744\uc5d0\ub294 \uc2e0\ub8b0\ub97c \ubd99\uc7a1\uae30 \uc704\ud55c \uc2dc\ub3c4\uc640 \ubd88\uc548\uc774 \ucee4\uc84c\ub2e4. \uae30\ub300\ud558\ub358 \uc0c1\uc2b9\uc774 \uba48\ucd94\uba74 \uac19\uc740 \uc57d\uc18d\ub3c4 \ub2e4\ub978 \ub208\uc73c\ub85c \ubcf4\uc774\uae30 \uc2dc\uc791\ud55c\ub2e4. \ub098\uc911\uc5d0 \ub204\uac00 \uc0ac \uc904\uc9c0\uc5d0 \ub300\ud55c \ubbff\uc74c\uc774 \ud754\ub4e4\ub9ac\uba74 \uac00\uaca9\uc744 \uc9c0\ud0f1\ud558\ub358 \uad00\uacc4\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uc0ac\uac74 \ub4a4\uc5d0\ub294 \uc758\ud68c\uc758 \uc870\uc0ac\uc640 \ucc45\uc784\uc744 \ubb3b\ub294 \uacfc\uc815\uc774 \uc774\uc5b4\uc84c\ub2e4. \ub2e4\ub9cc \uc774\ub97c \uc601\uad6d \uae08\uc735 \uc804\uccb4\uac00 \ud55c\ub0a0\uc5d0 \uc0ac\ub77c\uc9c4 \uc77c\ub85c \uacfc\uc7a5\ud560 \uc218\ub294 \uc5c6\ub2e4. \ud68c\uc0ac\uc758 \uc0ac\uc5c5\uacfc \ubd80\ucc44 \ucc98\ub9ac, \uc190\uc2e4\uacfc \uc81c\ub3c4\uc758 \ub300\uc751\uc740 \uc0ac\uac74 \ub4a4\uc5d0\ub3c4 \uc774\uc5b4\uc84c\ub2e4. \uac70\ud488\uc758 \ub05d\uc740 \uc5ed\uc0ac \uc790\uccb4\uc758 \ub05d\uc774 \uc544\ub2c8\uc5c8\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 \ub9e5\ucf00\uc774\uc758 1852\ub144\ud310 \ucc45\uc5d0 \uc218\ub85d\ub41c \ud638\uac00\uc2a4\uc758 \ub0a8\ud574\ud68c\uc0ac \ud48d\uc790 \ub3c4\ud310\uc774\ub2e4. \uc911\uc559\uc5d0\ub294 \uc0ac\ub78c\ub4e4\uc774 \ube59\uae00\ub3c4\ub294 \uae30\uad6c\ub97c \ud0c0\uace0 \uc788\uace0, \uadf8 \uc544\ub798\ub85c \ub9ce\uc740 \uc778\ubb3c\uc774 \ubaa8\uc600\ub2e4. \ud654\uac00\ub294 \uae08\uc735\uc758 \uc5f4\uae30\ub97c \uc775\uc0b4\uc2a4\ub7fd\uace0 \ud63c\ub780\uc2a4\ub7ec\uc6b4 \uc7a5\uba74\uc73c\ub85c \ud45c\ud604\ud55c\ub2e4. \uc774 \uadf8\ub9bc\uc740 \ub2f9\uc2dc \uac70\ub9ac\uc758 \ubaa8\ub4e0 \uc0ac\ub78c\uc744 \uadf8\ub300\ub85c \uae30\ub85d\ud55c \uc0ac\uc9c4\uc774 \uc544\ub2c8\ub2e4. \ube44\ud310\uacfc \uc0c1\uc9d5\uc744 \ub2f4\uc740 \ud48d\uc790\ub2e4. \ub204\uac00 \ubb34\uc5c7\uc744 \uc6b0\uc2a4\uaf5d\uc2a4\ub7fd\uac8c \ubcf4\uc774\uac8c \ud588\ub294\uc9c0 \uc0b4\ud53c\uba74, \uae08\uc735 \uc0ac\uac74\uc774 \uc22b\uc790\uc758 \uc190\uc2e4\ubfd0 \uc544\ub2c8\ub77c \uc0ac\ud68c\uac00 \uc790\uc2e0\uc744 \ub3cc\uc544\ubcf4\ub294 \ubb38\ud654\uc801 \uc18c\uc7ac\uac00 \ub418\uc5c8\uc74c\ub3c4 \uc54c \uc218 \uc788\ub2e4. \ub0a8\ud574\ud68c\uc0ac \uc0ac\uac74\uc744 \ubaa8\ub450\uac00 \uc5b4\ub9ac\uc11d\uc5c8\ub2e4\ub294 \uad50\ud6c8\uc73c\ub85c\ub9cc \uc77d\uc73c\uba74 \uad6d\uac00 \ubd80\ucc44\uc640 \ubb34\uc5ed \uad8c\ub9ac, \uc8fc\uc2dd \uc804\ud658\uc774\ub77c\ub294 \uad6c\uccb4\uc801\uc778 \uad6c\uc870\uac00 \uc0ac\ub77c\uc9c4\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \uc544\ubb34 \uc774\uc57c\uae30\uc5d0\ub3c4 \ubc18\uc751\ud55c \uac83\uc774 \uc544\ub2c8\ub77c \uad8c\ub825\uacfc \ubd80\uc758 \uc774\ubbf8\uc9c0\uac00 \uacb0\ud569\ub41c \uc57d\uc18d\uc744 \ubcf4\uace0 \uc788\uc5c8\ub2e4. \uc774 \uc624\ub798\ub41c \uc0ac\uac74\uc744 \uc77d\ub294 \uc990\uac70\uc6c0\uc740 \uc624\ub298\uc758 \uc2dc\uc7a5\uc744 \uadf8\ub300\ub85c \ub9de\ud790 \ube44\ubc95\uc744 \uc5bb\ub294 \ub370 \uc788\uc9c0 \uc54a\ub2e4. \uc5b4\ub5a4 \uc0ac\uc5c5\uc758 \uc774\ub984\uacfc \uc2e4\uc81c \uc218\uc785, \ubbf8\ub798\uc5d0 \ub300\ud55c \uae30\ub300\uac00 \uc5b4\ub5bb\uac8c \ub2e4\ub978\uc9c0\ub97c \uc54c\uc544\ubcf4\ub294 \ub370 \uc788\ub2e4. \ub0a8\ud574\ub77c\ub294 \uba3c \ubc14\ub2e4\uc758 \uc774\ub984\uc740 \ub7f0\ub358 \ud55c\ubcf5\ud310\uc5d0\uc11c \ub3c8\uc758 \uac12\uc774 \ub418\uc5c8\uace0, \uadf8 \uac04\uaca9\uc740 \uc9c0\uae08\ub3c4 \ud765\ubbf8\ub85c\uc6b4 \uae08\uc735\uc0ac\uc758 \uc9c8\ubb38\uc73c\ub85c \ub0a8\uc544 \uc788\ub2e4."}, {"id": "troy-ounce-weight", "title": "\uae08 \ud55c \uc628\uc2a4\uc640 \ubcf4\ud1b5 \ud55c \uc628\uc2a4\ub294 \ubb34\uac8c\uac00 \ub2e4\ub974\ub2e4", "summary": "\uac19\uc740 \uc628\uc2a4\ub77c\ub294 \ub9d0 \ub4a4\uc5d0\ub3c4 \ub2e4\ub978 \uae30\uc900\uc774 \uc788\uc2b5\ub2c8\ub2e4. \uae08\uc18d\uc758 \ubb34\uac8c\ub97c \uc77d\uc744 \ub54c \ucc59\uae38 \uc791\uc740 \ucc28\uc774\uc785\ub2c8\ub2e4.", "category": "finance", "category_title": "Finance", "subcategory": "Investment", "url": "stories/troy-ounce-weight/index.html", "image": "media/troy-ounce-weight.jpg", "alt": "\uc22b\uc790\ub098 \uc0c1\ud45c\uac00 \uc5c6\ub294 \uae08\ube5b \ub9c9\ub300\uc640 \uc800\uc6b8, \ucd94\ub97c \uadf8\ub9b0 \uc124\uba85\uc6a9 AI \uc0bd\ud654", "text": "\uae08 \ud55c \uc628\uc2a4\uc640 \ubcf4\ud1b5 \ud55c \uc628\uc2a4\ub294 \ubb34\uac8c\uac00 \ub2e4\ub974\ub2e4 \uadc0\uae08\uc18d\uc5d0\uc11c \ub9cc\ub098\ub294 \ud2b8\ub85c\uc774\uc628\uc2a4 \uc774\uc57c\uae30 \uac19\uc740 \uc628\uc2a4\ub77c\ub294 \ub9d0 \ub4a4\uc5d0\ub3c4 \ub2e4\ub978 \uae30\uc900\uc774 \uc788\uc2b5\ub2c8\ub2e4. \uae08\uc18d\uc758 \ubb34\uac8c\ub97c \uc77d\uc744 \ub54c \ucc59\uae38 \uc791\uc740 \ucc28\uc774\uc785\ub2c8\ub2e4. Investment \uae08\uc735 \uae08\uc774\ub098 \uc740\uc758 \ubb34\uac8c\ub97c \uc124\uba85\ud558\ub294 \uae00\uc5d0\uc11c\ub294 \uc628\uc2a4\ub77c\ub294 \ub2e8\uc704\ub97c \uc790\uc8fc \ub9cc\ub09c\ub2e4. \ub2e4\ub978 \ubb3c\uac74\uc758 \ubb34\uac8c\uc5d0\uc11c\ub3c4 \ubcf8 \uc774\ub984\uc774\ub77c \uc775\uc219\ud558\uac8c \uc9c0\ub098\uce58\uae30 \uc27d\ub2e4. \uadf8\ub7f0\ub370 \uc5ec\uae30\uc5d0\ub294 \ud55c \uac00\uc9c0 \ud655\uc778\ud560 \uac83\uc774 \uc788\ub2e4. \uadc0\uae08\uc18d\uc5d0 \ud754\ud788 \uc4f0\ub294 \ud2b8\ub85c\uc774\uc628\uc2a4\ub294 \uc77c\ubc18\uc801\uc778 \uc628\uc2a4\uc640 \ubb34\uac8c\uac00 \ub2e4\ub974\ub2e4. \uac19\uc740 \uc774\ub984\uc758 \ub4b7\ubd80\ubd84\ub9cc \ubcf4\uace0 \uac19\uc740 \uc591\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uba74 \ucc28\uc774\uac00 \uc0dd\uae34\ub2e4. \uc601\uad6d \uc655\ub9bd\uc870\ud3d0\uad6d\uc740 \uae08\uacfc \uc740 \uac19\uc740 \uadc0\uae08\uc18d\uc774 \ubcf4\ud1b5 \ud2b8\ub85c\uc774\uc628\uc2a4\ub85c \uce21\uc815\ub41c\ub2e4\uace0 \uc548\ub0b4\ud55c\ub2e4. \uc655\ub9bd\uc870\ud3d0\uad6d\uc758 \uc124\uba85\uc5d0\uc11c \ud55c \ud2b8\ub85c\uc774\uc628\uc2a4\ub294 31.1035\uadf8\ub7a8\uc774\ub2e4. \ubcf4\ud1b5 \uc628\uc2a4\ub77c\uace0 \ubd80\ub974\ub294 \uc544\ubcf4\uc544\ub4c0\ud3ec\uc544 \uc628\uc2a4\ub294 \uc57d 28.35\uadf8\ub7a8\uc774\ub2e4. \uc18c\uc218\uc810 \uc544\ub798\ub97c \ubaa8\ub450 \uc678\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc55e\ucabd\uc740 \uc57d 31.1\uadf8\ub7a8\uc774\ub77c\ub294 \uc815\ub3c4\ub9cc \uae30\uc5b5\ud574\ub3c4 \ub458\uc774 \ub2e4\ub974\ub2e4\ub294 \uac83\uc744 \uc54c \uc218 \uc788\ub2e4. \ub450 \uc218\ub97c \ub098\ub780\ud788 \ub193\uc73c\uba74 \ud2b8\ub85c\uc774\uc628\uc2a4 \ucabd\uc774 \uc870\uae08 \ub354 \ubb34\uac81\ub2e4. \uc628\uc2a4\ub77c\ub294 \ub2e8\uc5b4\uac00 \uac19\ub2e4\uace0 \ud574\uc11c \uc800\uc6b8\uc5d0 \uc62c\ub77c\uac00\ub294 \uc591\ub3c4 \ub611\uac19\uc9c0\ub294 \uc54a\uc740 \uac83\uc774\ub2e4. \ubb3c\ub860 \uc5b4\ub5a4 \uc0c1\ud488\uc774\ub098 \ubb38\uc11c\uac00 \uc2e4\uc81c\ub85c \uc5b4\ub290 \uae30\uc900\uc744 \uc0ac\uc6a9\ud558\ub294\uc9c0\ub294 \ud45c\uc2dc\ub97c \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \uadc0\uae08\uc18d\uc774\uba74 \uc124\uba85 \uc5c6\uc774 \ubb34\uc870\uac74 \uac19\uc740 \uc870\uac74\uc774\ub77c\uace0 \ub118\uaca8\uc9da\uae30\ubcf4\ub2e4, \ub2e8\uc704\uc758 \uc774\ub984\uc744 \ub05d\uae4c\uc9c0 \ubcf4\ub294 \ud3b8\uc774 \uc815\ud655\ud558\ub2e4. \ubb3c\uac74\uc758 \uc591\uc744 \ube44\uad50\ud560 \ub54c \uc22b\uc790\uac00 \ud06c\uac8c \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uadf8\ub7ec\ub098 \uc22b\uc790\ub294 \ub2e8\uc704\uc640 \ud568\uaed8 \uc77d\uc5b4\uc57c \ud55c\ub2e4. 1\uc774\ub77c\ub294 \uc218\uac00 \uac19\uc544\ub3c4 \ubb34\uc5c7\uc744 \ud558\ub098\ub85c \uc138\ub294\uc9c0\uac00 \ub2e4\ub974\uba74 \uc591\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \ud2b8\ub85c\uc774\uc628\uc2a4\ub294 \uc774\ub7f0 \ucc28\uc774\ub97c \ubcf4\uc5ec\uc8fc\ub294 \uc775\uc219\ud558\uc9c0 \uc54a\uc740 \uc608\ub2e4. \ud3c9\uc18c \uadf8\ub7a8\uc5d0 \uc775\uc219\ud55c \uc0ac\ub78c\uc740 \uc628\uc2a4\ub07c\ub9ac \uba3c\uc800 \ube44\uad50\ud558\uae30\ubcf4\ub2e4 \uadf8\ub7a8\uc73c\ub85c \ud480\uc5b4 \ubcf4\uba74 \uc774\ud574\uac00 \uc26c\uc6cc\uc9c4\ub2e4. \uc655\ub9bd\uc870\ud3d0\uad6d\ub3c4 \uadc0\uae08\uc18d \uac00\uaca9\uc774\ub098 \uc0c1\ud488\uc5d0\uc11c \uc628\uc2a4\ub97c \ub9d0\ud560 \ub54c \ubcf4\ud1b5 \ud2b8\ub85c\uc774\uc628\uc2a4\ub97c \ub73b\ud55c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc774 \ub9d0\uc740 \uac00\uaca9 \uc804\ub9dd\uc774 \uc544\ub2c8\ub77c \ud45c\uc2dc\ub97c \uc77d\ub294 \ubc29\ubc95\uc5d0 \uad00\ud55c \uc548\ub0b4\ub2e4. \ubb34\uac8c\ub97c \uc548\ub2e4\uace0 \uac00\uce58\uc758 \ubcc0\ud654\uae4c\uc9c0 \uc54c \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. 1\uc628\uc2a4\ub77c\ub294 \ud45c\uc2dc\uac00 \ub458 \ub098\ub780\ud788 \uc788\uc5b4\ub3c4 \uae30\uc900\uc774 \ub2e4\ub974\uba74 \uac19\uc740 \uc591\uc774\ub77c\uace0 \ud560 \uc218\ub294 \uc5c6\ub2e4. \uc22b\uc790\ub294 \ub2e8\uc704\uac00 \uc815\ud55c \ubb36\uc74c\uc758 \uac1c\uc218\ub97c \ub9d0\ud55c\ub2e4. \uae08\uc18d\uc744 \uc0ac\uac70\ub098 \uc790\ub8cc\ub97c \uc77d\uc744 \ub54c\uc5d0\ub294 \uc22b\uc790 \uc55e\ub4a4\uc758 \uc791\uc740 \uae00\uc790\ub97c \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \ub2e8\uc704 \uc774\ub984\uc774 \ube44\uc2b7\ud558\ub2e4\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \ube44\uad50\ub97c \uc2dc\uc791\ud558\uba74 \uacc4\uc0b0\uc744 \uc815\ud655\ud788 \ud574\ub3c4 \ucc98\uc74c\uc758 \uc591\uc744 \uc798\ubabb \uc7a1\uc744 \uc218 \uc788\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \ub450 \ud2b8\ub85c\uc774\uc628\uc2a4\ub294 \uc774 \uae00\uc758 \uae30\uc900\uc73c\ub85c \uc57d 62.207\uadf8\ub7a8\uc774\uace0, \ubcf4\ud1b5 \uc628\uc2a4 \ub450 \uac1c\ub294 \uc57d 56.70\uadf8\ub7a8\uc774\ub2e4. \ub458 \ub2e4 2\ub77c\uace0 \uc801\ud600 \uc788\uc9c0\ub9cc \uc2e4\uc81c \ube44\uad50\ud560 \ubb34\uac8c\ub294 \ub2e4\ub974\ub2e4. \uc774\uac83\uc740 \uc0c1\ud488 \uac00\uaca9\uc758 \uc608\uce21\uc774 \uc544\ub2c8\ub77c \uac19\uc740 \ub2e8\uc5b4 \uc548\uc758 \ub450 \uae30\uc900\uc744 \ud480\uc5b4 \uc4f4 \uacc4\uc0b0\uc774\ub2e4. \uc775\uc219\ud55c \uadf8\ub7a8\uc73c\ub85c \uc62e\uae30\uba74 \ucc28\uc774\uac00 \uc870\uae08 \ub354 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uae08\uc18d \ubb3c\uac74\uc758 \uc804\uccb4 \ubb34\uac8c\ub97c \uc548\ub2e4\uace0 \uadf8 \uc548\uc5d0 \ub4e4\uc5b4 \uc788\ub294 \ud2b9\uc815 \uadc0\uae08\uc18d\uc758 \uc591\uc744 \ubaa8\ub450 \uc548 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubb34\uc5c7\uc774 \uc11e\uc5ec \uc788\ub294\uc9c0\uc640 \uc5bc\ub9c8\ub098 \uc788\ub294\uc9c0\ub294 \ubcc4\ub3c4\uc758 \uc815\ubcf4\ub2e4. \ub2e8\uc704\ub97c \uc77d\ub294 \uc77c\uc774 \uc911\uc694\ud55c \uccab \ub2e8\uacc4\ub77c\uace0 \ud574\ub3c4 \uadf8\uac83\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \uc0c1\ud488 \uc124\uba85\uc744 \ub300\uc2e0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ubb34\uac8c\ub97c \ub098\ud0c0\ub0b8 \uc22b\uc790\uc640 \uc7ac\ub8cc\uc758 \uc131\uc9c8\uc744 \ub098\ud0c0\ub0b8 \ub9d0\uc744 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 \ud2b9\uc815 \uc0c1\ud488\uc758 \uc21c\ub3c4\ub97c \uacc4\uc0b0\ud558\uac70\ub098 \ub9e4\uc785 \uac00\uce58\ub97c \ud3c9\uac00\ud558\uc9c0 \uc54a\ub294\ub2e4. \ub2e4\ub9cc \uc124\uba85\ubb38\uc5d0\uc11c \ubb34\uac8c\ub77c\ub294 \ud56d\ubaa9\uc774 \ub9e1\ub294 \uc5ed\ud560\uc744 \ubd84\uba85\ud788 \ud574 \ub454\ub2e4. \ud558\ub098\uc758 \uc22b\uc790\uc5d0 \uc7ac\ub8cc\uc640 \uac00\uaca9, \uac00\uce58\uae4c\uc9c0 \ud55c\uaebc\ubc88\uc5d0 \ub2f4\uaca8 \uc788\ub2e4\uace0 \uc0dd\uac01\ud558\uc9c0 \uc54a\uc73c\uba74 \uad11\uace0\uc640 \uc790\ub8cc\ub97c \ub354 \ucc28\ubd84\ud558\uac8c \uc77d\uc744 \uc218 \uc788\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc9c8\ubb38\uc5d0 \uc11c\ub85c \ub2e4\ub978 \uc815\ubcf4\uac00 \ud544\uc694\ud558\ub2e4\ub294 \uc810\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc0ac\ub840\ub2e4. \uadf8\ub7a8\uc5d0 \uc775\uc219\ud55c \uc0ac\ub78c\uc5d0\uac8c \uc628\uc2a4\ub294 \ub0af\uc124 \uc218 \uc788\uc9c0\ub9cc, \uc624\ub798 \uc0ac\uc6a9\ud55c \ubd84\uc57c\uc5d0\uc11c\ub294 \uadf8 \ub2e8\uc704\uac00 \uac70\ub798\uc640 \uae30\ub85d\uc744 \uc774\uc5b4 \uc8fc\ub294 \uc5ed\ud560\uc744 \ud55c\ub2e4. \ubaa8\ub4e0 \uc790\ub8cc\ub97c \uc989\uc2dc \ub2e4\ub978 \ub2e8\uc704\ub85c \ubc14\uafb8\uc5b4 \uc4f0\uae30\ubcf4\ub2e4 \uc6d0\ub798\uc758 \ud45c\uc2dc\ub97c \ud568\uaed8 \ub0a8\uaca8 \ub450\ub294 \uc774\uc720\ub3c4 \uc788\ub2e4. \ub098\uc911\uc5d0 \ub2e4\ub978 \uae30\ub85d\uacfc \ube44\uad50\ud560 \ub54c \ubb34\uc5c7\uc744 \uae30\uc900\uc73c\ub85c \uc801\uc5c8\ub294\uc9c0 \uc54c\uc544\uc57c \ud558\uae30 \ub54c\ubb38\uc774\ub2e4. \ubcc0\ud658\uac12\uc5d0\ub294 \ubc18\uc62c\ub9bc\ub3c4 \uc788\ub2e4. \uc774 \uae00\uc5d0\uc11c \uc0ac\uc6a9\ud558\ub294 31.1035\uc640 \uc57d 28.35\ub294 \uc774\ud574\ub97c \ub3d5\ub294 \ud45c\uae30\uc774\ubbc0\ub85c, \ub9e4\uc6b0 \uc815\ubc00\ud55c \uce21\uc815\uacfc \uac70\ub798\uc5d0\ub294 \ud574\ub2f9 \ubb38\uc11c\uc758 \uc815\ud655\ud55c \uae30\uc900\uc744 \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \uc6d0\ub9ac\ub97c \uc544\ub294 \uc77c\uacfc \uc2e4\uc81c \uc5c5\ubb34\uc5d0 \ud544\uc694\ud55c \uc790\ub9bf\uc218\ub97c \uacb0\uc815\ud558\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \uc77c\uc0c1\uc801\uc778 \ube44\uad50\uc5d0\uc11c\ub294 \ub450 \uc628\uc2a4\uac00 \uac19\uc9c0 \uc54a\ub2e4\ub294 \uad6c\ubd84\ubd80\ud130 \ucc59\uae30\uba74 \ucda9\ubd84\ud558\ub2e4. \uac00\uaca9\uc774 \uc624\ub974\uace0 \ub0b4\ub9ac\ub294 \uc774\uc57c\uae30\ub294 \ub208\uae38\uc744 \ub04c\uc9c0\ub9cc, \ubb34\uc5c7\uc758 \uac00\uaca9\uc778\uc9c0\ub97c \uc54c\uc544\ubcf4\ub294 \uac83\uc740 \ub354 \uae30\ubcf8\uc801\uc778 \uc9c8\ubb38\uc774\ub2e4. \uc628\uc2a4\ub2f9\uc774\ub77c\ub294 \ud45c\ud604\uc744 \ub9cc\ub098\uba74 \uc5b4\ub290 \uc628\uc2a4\ub97c \ub9d0\ud558\ub294\uc9c0 \uba3c\uc800 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \ub2e8\uc704\uc758 \ucc28\uc774\ub97c \uc548\ub2e4\uace0 \uc2dc\uc7a5\uc744 \uc608\uce21\ud560 \uc218\ub294 \uc5c6\uc9c0\ub9cc \ube44\uad50\uc758 \ucd9c\ubc1c\uc810\uc774 \ud754\ub4e4\ub9ac\ub294 \uc77c\uc744 \uc904\uc77c \uc218\ub294 \uc788\ub2e4. \uc800\uc6b8 \uc704\uc758 \ubb3c\uac74\uc740 \ud558\ub098\uc778\ub370 \uc774\ub984\uc744 \ubd99\uc774\ub294 \ubc29\uc2dd\uc5d0 \ub530\ub77c \uc22b\uc790\uac00 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc22b\uc790\uac00 \ub2ec\ub77c\uc84c\ub2e4\uace0 \ubb3c\uac74 \uc790\uccb4\uac00 \ubc14\ub010 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc790\ub8cc\uc640 \uc0c1\ud488\uc744 \uc77d\uc744 \ub54c \uc218\uc640 \ub2e8\uc704\ub97c \ud55c \ub369\uc5b4\ub9ac\ub85c \ubcf4\ub294 \uc2b5\uad00\uc740 \uc774 \uc791\uc740 \uc0ac\ub840 \ubc16\uc5d0\uc11c\ub3c4 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \uae08\uc18d\uc758 \ubc18\uc9dd\uc784 \ub4a4\uc5d0\uc11c, \uc0ac\ub78c\ub4e4\uc774 \uc591\uc744 \ud568\uaed8 \uc774\ud574\ud558\uae30 \uc704\ud574 \uc815\ud55c \uc57d\uc18d\uc774 \ubcf4\uc778\ub2e4. \uae08\uc18d\uc744 \uc9c1\uc811 \uac70\ub798\ud558\uc9c0 \uc54a\uc544\ub3c4 \uc774\ub7f0 \ub2e8\uc704\ub294 \ub274\uc2a4\uc640 \uc804\uc2dc \uc124\uba85\uc5d0\uc11c \ub9cc\ub09c\ub2e4. \uadf8\ub54c \ub0af\uc120 \ub9d0\uc744 \ubaa8\ub450 \uacf5\ubd80\ud558\ub824\uace0 \ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uac19\uc740 \uc628\uc2a4\uc5d0\ub3c4 \ub2e4\ub978 \uae30\uc900\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub9cc \ucc59\uaca8 \ub450\uba74 \ub41c\ub2e4. \uc5ec\ud589\uc9c0\uc5d0\uc11c \uc11c\ub85c \ub2e4\ub978 \ud06c\uae30\uc758 \ucef5\uc744 \ubaa8\ub450 \ud55c \uc794\uc774\ub77c\uace0 \ubd80\ub974\ub294 \uc0c1\ud669\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uc774\ub984\uc744 \ub9de\ucd94\ub294 \uac83\uacfc \uc2e4\uc81c \uc591\uc744 \ub9de\ucd94\ub294 \uac83\uc740 \ubcc4\uac1c\uc758 \uc77c\uc774\ub2e4. \ub2e8\uc704\uc758 \uae30\uc900\uc740 \uadf8 \ucc28\uc774\ub97c \ubd84\uba85\ud788 \ud558\ub824\uace0 \ud544\uc694\ud558\ub2e4. \ub2e4\uc74c\uc5d0 \uae08 \ud55c \uc628\uc2a4\ub77c\ub294 \ud45c\ud604\uc744 \ub9cc\ub098\uba74 \uc22b\uc790 1 \uc606\uc758 \ub9d0\uc744 \uc7a0\uae50 \uc0b4\ud3b4\ubcf4\uc790. \uc791\uc740 \ub2e8\uc704\uc758 \uc774\ub984\uc774, \uc0dd\uac01\ubcf4\ub2e4 \uc911\uc694\ud55c \ubb34\uac8c\ub97c \uac00\uc9c0\uace0 \uc788\ub2e4."}, {"id": "virginia-company-shares-and-colony", "title": "\ubc84\uc9c0\ub2c8\uc544 \ud68c\uc0ac \u2014 \uc2e0\ub300\ub959\uc758 \uafc8\uc744 \uc8fc\uc2dd\uc73c\ub85c \ud314\ub2e4", "summary": "1606\ub144\uc758 \ud68c\uc0ac\uc640 1607\ub144\uc758 \uc2dd\ubbfc\uc9c0\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uacf5\ub3d9 \ud22c\uc790\u00b7\ud669\uae08\uc758 \uae30\ub300\u00b7\ub2f4\ubc30\uc640 \ub178\ub3d9\uc758 \uc5ed\uc0ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "finance", "category_title": "Finance", "subcategory": "Investment", "url": "stories/virginia-company-shares-and-colony/index.html", "image": "media/virginia-company-shares-and-colony.png", "alt": "17\uc138\uae30 \ucd08 \uc0c1\uc778\ub4e4\uc744 \ub5a0\uc62c\ub9ac\ub294 \uc0ac\ub78c\ub4e4\uc774 \ud56d\uad6c\uac00 \ubcf4\uc774\ub294 \ubc29\uc5d0\uc11c \uc11c\ub958\ub97c \uc758\ub17c\ud558\ub294 \uc0bd\ud654.", "text": "\ubc84\uc9c0\ub2c8\uc544 \ud68c\uc0ac \u2014 \uc2e0\ub300\ub959\uc758 \uafc8\uc744 \uc8fc\uc2dd\uc73c\ub85c \ud314\ub2e4 \ub7f0\ub358\uc758 \ud22c\uc790\uae08\uc774 \uc81c\uc784\uc2a4\ud0c0\uc6b4\uc758 \uc0dd\ud65c\uacfc \ub9cc\ub0ac\uc744 \ub54c 1606\ub144\uc758 \ud68c\uc0ac\uc640 1607\ub144\uc758 \uc2dd\ubbfc\uc9c0\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uacf5\ub3d9 \ud22c\uc790\u00b7\ud669\uae08\uc758 \uae30\ub300\u00b7\ub2f4\ubc30\uc640 \ub178\ub3d9\uc758 \uc5ed\uc0ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Investment \uae08\uc735 \ubc30\ub97c \ubcf4\ub0b4\uace0 \uc0ac\ub78c\uc744 \uc774\uc8fc\uc2dc\ud0a4\uba70 \ub0af\uc120 \ub545\uc5d0 \uac70\uc810\uc744 \uc138\uc6b0\ub824\uba74 \ud070\ub3c8\uc774 \ub4e4\uc5c8\ub2e4. \uc655\uc774 \ubaa8\ub4e0 \ube44\uc6a9\uc744 \uc9c1\uc811 \ub9c8\ub828\ud558\ub294 \ub300\uc2e0 \uc5ec\ub7ec \ud22c\uc790\uc790\uac00 \ub3c8\uc744 \ubaa8\uc740\ub2e4\uba74 \uc5b4\ub5a8\uae4c. 17\uc138\uae30 \ucd08 \uc601\uad6d\uc758 \uc2dd\ubbfc \uc0ac\uc5c5\uc5d0\ub294 \uc774\ub7f0 \uacf5\ub3d9 \ud22c\uc790\uc758 \ubc29\uc2dd\uc774 \uae4a\uc774 \ub4e4\uc5b4\uac14\ub2e4. \ubc84\uc9c0\ub2c8\uc544 \ud68c\uc0ac\uc758 \uc774\uc57c\uae30\ub294 \uc8fc\uc2dd\uc758 \uc5ed\uc0ac\uac00 \uac70\ub798\uc18c \uc548\uc5d0\uc11c\ub9cc \uc2dc\uc791\ub418\uc9c0 \uc54a\uc558\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ub7f0\ub358\uc5d0\uc11c \uae30\ub300\ud55c \uc218\uc775\uacfc \ub300\uc11c\uc591 \uac74\ub108\uc5d0\uc11c \uc2e4\uc81c\ub85c \uc0b4\uc544\ub0a8\uc544\uc57c \ud588\ub358 \uc0ac\ub78c\ub4e4\uc758 \uc0ac\uc815\uc740 \uac19\uc740 \uacc4\ud68d \uc548\uc5d0 \uc788\uc5c8\uc9c0\ub9cc \uac19\uc740 \uacbd\ud5d8\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uad50\uc7ac\ub294 \uacf5\ub3d9 \ucd9c\uc790 \ud68c\uc0ac\uac00 \ud22c\uc790\uc790\uc5d0\uac8c \uc9c0\ubd84\uc744 \ud314\uc544 \uc790\uae08\uc744 \ubaa8\uc73c\uace0 \uc0ac\uc5c5\uc744 \uc218\ud589\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud55c \uc0ac\ub78c\uc774 \ubc30\uc640 \uc0ac\ub78c, \ubb3c\uc790\uc758 \ube44\uc6a9\uc744 \ubaa8\ub450 \ubd80\ub2f4\ud558\ub294 \ubc29\uc2dd\uacfc\ub294 \ub2e4\ub974\ub2e4. \ud22c\uc790\uc790\ub294 \uc790\uc2e0\uc774 \ucc38\uc5ec\ud55c \uc0ac\uc5c5\uc774 \uc798\ub418\uba74 \uadf8 \uacb0\uacfc\ub97c \ub098\ub204\uc5b4 \ubc1b\uc744 \uc218 \uc788\ub2e4\ub294 \uae30\ub300\ub97c \uac00\uc84c\ub2e4. \uc774 \uc2dc\uae30\uc758 \ud68c\uc0ac\ub97c \uc624\ub298\uc758 \uc8fc\uc2dd\ud68c\uc0ac\uc640 \ubaa8\ub4e0 \ubc95\ub960 \uc870\uac74\uc774 \uac19\uc740 \uac83\uc73c\ub85c \ubcfc \uc218\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \uba40\ub9ac \uc788\ub294 \uc0ac\uc5c5\uc758 \ube44\uc6a9\uc744 \uc5ec\ub7ec \uc0ac\ub78c\uc758 \ub3c8\uc73c\ub85c \ubaa8\uc740\ub2e4\ub294 \uad6c\uc0c1\uc740 \ubd84\uba85\ud558\ub2e4. \uc8fc\uc2dd\uc774\ub77c\ub294 \ub9d0 \ub4a4\uc5d0\ub294 \uc774\ubbf8 \ubc30\uac00 \ub5a0\ub098\uae30 \uc804\ubd80\ud130 \ub9ce\uc740 \uc0ac\ub78c\uc758 \uae30\ub300\ub97c \uc5f0\uacb0\ud558\ub294 \uc7a5\uce58\uac00 \uc788\uc5c8\ub2e4. \ubc84\uc9c0\ub2c8\uc544 \ud68c\uc0ac\ub294 1606\ub144 \uc655\uc2e4\uc758 \ud5c8\uac00\ub97c \ubc1b\uc558\ub2e4. \uc774\ub4ec\ud574 \uc774\uc8fc\ubbfc\ub4e4\uc740 \uc624\ub298\ub0a0 \ubbf8\uad6d \ubc84\uc9c0\ub2c8\uc544\uc758 \uccb4\uc11c\ud53c\ud06c\ub9cc \uc9c0\uc5ed\uc5d0 \uc81c\uc784\uc2a4\ud0c0\uc6b4\uc744 \uc138\uc6e0\ub2e4. \uc0c8 \uad6d\uc655 \uc81c\uc784\uc2a4 1\uc138\uc758 \uc774\ub984\uc774 \uc815\ucc29\uc9c0\uc5d0 \ubd99\uc5c8\ub2e4. \ud68c\uc0ac\uc758 \uc790\uae08\uacfc \uc655\uc2e4\uc758 \uad8c\ud55c\uc774 \ub300\uc11c\uc591 \uac74\ub108\uc758 \uc7a5\uc18c\uc5d0\uc11c \ub9cc\ub09c \uac83\uc774\ub2e4. \uadf8 \ub545\uc740 \uc0ac\ub78c\uc774 \uc5c6\ub358 \ube48 \uacf5\uac04\uc774 \uc544\ub2c8\uc5c8\ub2e4. \ud3ec\uc6b0\ud558\ud0c4\uc744 \ube44\ub86f\ud55c \uc6d0\uc8fc\ubbfc \uacf5\ub3d9\uccb4\uc758 \uc0dd\ud65c\uacfc \uad00\uacc4\uac00 \uc788\uc5c8\ub2e4. \ud22c\uc790\uc790\uac00 \uc9c0\ub3c4\ub97c \ubcf4\uace0 \uc0ac\uc5c5\uc758 \uae30\ud68c\ub77c\uace0 \uc0dd\uac01\ud55c \uacf3\uc740 \ub204\uad70\uac00\uc5d0\uac8c \uc774\ubbf8 \uc0b6\uc758 \ud130\uc804\uc774\uc5c8\ub2e4. \uacf5\ub3d9 \ud22c\uc790\uc758 \uc5ed\uc0ac\ub294 \uc774\ub7f0 \uc11c\ub85c \ub2e4\ub978 \ucd9c\ubc1c\uc810\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \ub2f9\uc2dc\uc758 \uc911\uc0c1\uc8fc\uc758\uc801 \uc0dd\uac01\uc5d0\uc11c\ub294 \uadc0\uae08\uc18d\uc744 \ud655\ubcf4\ud558\ub294 \uc77c\uc774 \uad6d\uac00\uc758 \ubd80\uc640 \uae34\ubc00\ud788 \uc5f0\uacb0\ub418\uc5c8\ub2e4. \uad50\uc7ac\ub294 \uc601\uad6d \uc815\ubd80\uc640 \uc774\uc8fc\ubbfc\ub4e4\uc774 \uae08\uc744 \ubc1c\uacac\ud560 \uac00\ub2a5\uc131\uc5d0 \uae30\ub300\ub97c \uac78\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uba3c \ub545\uc5d0 \ub300\ud55c \uc815\ubcf4\uac00 \ucda9\ubd84\ud558\uc9c0 \uc54a\uc740 \uc0c1\ud669\uc5d0\uc11c\ub3c4 \ubd80\uc758 \uc774\ubbf8\uc9c0\ub294 \uc0ac\ub78c\uc744 \ub04c\uc5b4\ub2f9\uacbc\ub2e4. \uadf8\ub7ec\ub098 \uae30\ub300\ud55c \uad11\ubb3c\uc774 \ud604\uc7a5\uc5d0\uc11c \ub098\ud0c0\ub098\ub294 \uac83\uc740 \ub2e4\ub978 \ubb38\uc81c\uc600\ub2e4. \ubc30\ub97c \ud0c0\uace0 \uac04 \uc0ac\ub78c\ub4e4 \uac00\uc6b4\ub370\ub294 \ub0af\uc120 \ud658\uacbd\uc5d0\uc11c \uc9d1\uc744 \uc9d3\uace0 \ub18d\uc0ac\ub97c \uc9c0\uc5b4 \uc0dd\ud65c\uc744 \uc720\uc9c0\ud560 \uc900\ube44\uac00 \ucda9\ubd84\ud558\uc9c0 \uc54a\uc740 \uc774\ub4e4\ub3c4 \uc788\uc5c8\ub2e4. \ud22c\uc790 \uacc4\ud68d\uc758 \ub9e4\ub825\uacfc \uadf8 \uacc4\ud68d\uc744 \uc2e4\ud589\ud560 \uc77c\uc0c1\uc758 \ub2a5\ub825 \uc0ac\uc774\uc5d0\ub294 \uac04\uaca9\uc774 \uc788\uc5c8\ub2e4. \uc81c\uc784\uc2a4\ud0c0\uc6b4\uc740 \uc9c8\ubcd1\uacfc \uc2dd\ub7c9 \ubd80\uc871, \ub0b4\ubd80 \uac08\ub4f1\uacfc \uc6d0\uc8fc\ubbfc\uacfc\uc758 \ucda9\ub3cc\uc744 \uacaa\uc5c8\ub2e4. \ud2b9\ud788 1609\ub144\uc5d0\uc11c 1610\ub144\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \uaca8\uc6b8\uc740 \uc2ec\uac01\ud55c \uae30\uadfc\uc758 \uc2dc\uae30\ub85c \uc54c\ub824\uc838 \uc788\ub2e4. \uad50\uc7ac\ub294 \uadf8 \ubb34\ub835 \uc2dd\ubbfc\uc9c0\uc640 \ud68c\uc0ac\uc758 \uc0ac\uc5c5\uc774 \uac70\uc758 \uc2e4\ud328\ud560 \uc704\uae30\uc5d0 \ub193\uc600\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc5ec\uae30\uc11c \uc218\uc775\uc774 \ub098\uc9c0 \uc54a\uc558\ub2e4\ub294 \ub9d0\uc740 \uc7a5\ubd80\uc758 \uc22b\uc790\ub9cc\uc744 \ub73b\ud558\uc9c0 \uc54a\ub294\ub2e4. \ud604\uc7a5\uc5d0\uc11c\ub294 \uc0ac\ub78c\uc758 \uc0dd\uc874\uc774 \uac78\ub824 \uc788\uc5c8\ub2e4. \ud22c\uc790\uc790\uc758 \uc190\uc2e4\uacfc \uc774\uc8fc\ubbfc\uc774 \uacaa\ub294 \uace0\ud1b5, \uc6d0\uc8fc\ubbfc \uacf5\ub3d9\uccb4\uac00 \uacaa\uc740 \uce68\ud574\ub294 \uac19\uc740 \ub2e8\uc704\ub85c \uc815\ub9ac\ub418\uc9c0 \uc54a\ub294\ub2e4. \uba40\ub9ac\uc11c \ubcf4\uc774\ub294 \uc0ac\uc5c5\uacfc \uadf8 \uc548\uc758 \uc0dd\ud65c\uc744 \ud568\uaed8 \uc77d\uc5b4\uc57c \ud558\ub294 \uc774\uc720\ub2e4. \uc81c\uc784\uc2a4\ud0c0\uc6b4\uc758 \uc218\ucd9c\uc5d0\uc11c \uc911\uc694\ud574\uc9c4 \uac83\uc740 \uae08\ubcf4\ub2e4 \ub2f4\ubc30\uc600\ub2e4. \uad50\uc7ac\ub294 1614\ub144 \ubb34\ub835 \ub2f4\ubc30\uac00 \uc720\ub7fd\uc73c\ub85c \uc218\ucd9c\ub418\uba70 \uc218\uc775\uc744 \ub9cc\ub4e4\uc5b4 \ub0b4\uae30 \uc2dc\uc791\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ucc98\uc74c \uae30\ub300\ud588\ub358 \uc885\ub958\uc758 \ubd80\uac00 \uc544\ub2c8\ub77c \ub2e4\ub978 \uc0c1\ud488\uc774 \uc0ac\uc5c5\uc758 \ubc29\ud5a5\uc744 \ubc14\uafbc \uac83\uc774\ub2e4. \uc774 \ubcc0\ud654\ub294 \uc0c8 \uc791\ubb3c\uc744 \ubc1c\uacac\ud55c \uc990\uac70\uc6b4 \uc804\ud658\uc73c\ub85c\ub9cc \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \ub2f4\ubc30\ub97c \uc7ac\ubc30\ud558\ub824\uba74 \ub545\uacfc \ub178\ub3d9\uc774 \ud544\uc694\ud588\ub2e4. \ub354 \ub9ce\uc740 \uc0c1\ud488\uc744 \ubcf4\ub0b4\ub824\ub294 \uc694\uad6c\ub294 \uc815\ucc29\uc9c0\uc758 \uaddc\ubaa8\uc640 \uc8fc\ubcc0 \uacf5\ub3d9\uccb4\uc640\uc758 \uad00\uacc4\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc8fc\uc5c8\ub2e4. \uc2dc\uc7a5\uc758 \uc218\uc694\ub294 \uba40\ub9ac \uc788\ub294 \uc0dd\ud65c\uc758 \uc870\uac74\uc744 \ubc14\uafb8\ub294 \ud798\uc774 \ub420 \uc218 \uc788\uc5c8\ub2e4. \uc601\uad6d \uc2dd\ubbfc\uc9c0\uc5d0\uc11c\ub294 \uc77c\uc815 \uae30\uac04 \ub178\ub3d9\ud558\ub294 \ub300\uac00\ub85c \uc774\uc8fc \ube44\uc6a9\uc744 \ub9c8\ub828\ud55c \uacc4\uc57d \ud558\uc778\ub4e4\uc774 \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud588\ub2e4. \uadf8\ub7ec\ub098 \uc2e4\uc81c \uc0dd\ud65c\uc740 \uc9c8\ubcd1\uacfc \uacfc\ub85c, \ubd88\uc548\uc815\ud55c \uc870\uac74\uc744 \ud3ec\ud568\ud588\ub2e4. \uc774\ud6c4 \ubc84\uc9c0\ub2c8\uc544\uc758 \uc5ed\uc0ac\ub294 \uc544\ud504\ub9ac\uce74\uc778\uc758 \uac15\uc81c \uc774\uc8fc\uc640 \uc778\uc885\uc801 \ub178\uc608\uc81c\uc758 \ud655\ub300\uc640\ub3c4 \uc5f0\uacb0\ub41c\ub2e4. \uac19\uc740 \uc2dc\ub300\uc758 \ubaa8\ub4e0 \ub178\ub3d9 \uad00\uacc4\uac00 \ucc98\uc74c\ubd80\ud130 \uc644\uc804\ud788 \uac19\uc740 \ubc95\uc801 \ud615\ud0dc\uc600\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uad50\uc7ac\ub3c4 \ubcc0\ud654\uc758 \uacfc\uc815\uc744 \uc124\uba85\ud55c\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc720\ub7fd\uc5d0 \ub3c4\ucc29\ud55c \uc0c1\ud488\uc758 \uc774\uc775 \ub4a4\uc5d0 \ub204\uac00 \uc5b4\ub5a4 \uc870\uac74\uc73c\ub85c \uc77c\ud588\ub294\uc9c0 \uc9c8\ubb38\ud558\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4. \ud68c\uc0ac\uc758 \uc131\uc7a5\ub9cc\uc73c\ub85c \ub2f9\uc2dc \uc0ac\ud68c \uc804\uccb4\uc758 \ud615\ud3b8\uc744 \ud3c9\uac00\ud560 \uc218\ub294 \uc5c6\ub2e4. \ud68c\uc0ac\ub294 \ucd9c\uc790\uae08\uacfc \uacc4\ud68d\uc744 \ud55c\uacf3\uc5d0\uc11c \ubaa8\uc558\uc9c0\ub9cc \uc2e4\ud589\uc740 \uba3c \uc2dd\ubbfc\uc9c0\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc84c\ub2e4. \uc18c\uc2dd\uc774 \uc624\uac00\ub294 \ub370 \uc2dc\uac04\uc774 \uac78\ub9ac\uace0 \ud604\uc9c0\uc758 \uc704\ud5d8\uc744 \uac00\uae4c\uc774\uc11c \uc54c\uae30 \uc5b4\ub824\uc6e0\ub2e4. \ud22c\uc790\uc790\uc640 \ud604\uc7a5\uc744 \uc787\ub294 \uc815\ubcf4\uc758 \uac70\ub9ac\ub294 \uc624\ub298\uc758 \uc989\uac01\uc801\uc778 \ud654\uba74\uacfc \ub2e4\ub978 \uc870\uac74\uc774\uc5c8\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 17\uc138\uae30 \ucd08 \uc0c1\uc778\ub4e4\uc774 \ubb38\uc11c\ub97c \uc0b4\ud53c\ub294 \uc0c1\uc0c1 \uc18d \uc7a5\uba74\uc774\ub2e4. \uc2e4\uc81c \ubc84\uc9c0\ub2c8\uc544 \ud68c\uc0ac\uc758 \uc8fc\uad8c\uc774\ub098 \uc774\uc0ac\ud68c, \ud2b9\uc815 \ud22c\uc790\uc790\uc758 \ucd08\uc0c1\uc744 \uc7ac\ud604\ud558\uc9c0 \uc54a\uc558\ub2e4. \uc885\uc774 \uc704\uc758 \uc57d\uc18d\uc774 \uba3c \ud56d\uad6c\uc758 \uc0dd\ud65c\uacfc \uc774\uc5b4\uc9c4\ub2e4\ub294 \uc0dd\uac01\uc744 \ud45c\ud604\ud55c \uadf8\ub9bc\uc774\ub2e4. \ubc84\uc9c0\ub2c8\uc544 \ud68c\uc0ac\ub294 \uc5ec\ub7ec \uc0ac\ub78c\uc758 \uc790\uae08\uc774 \ud070 \uc0ac\uc5c5\uc744 \uc6c0\uc9c1\uc774\ub294 \ubc29\uc2dd\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ub3d9\uc2dc\uc5d0 \uadf8 \uc0ac\uc5c5\uc774 \ub9cc\ub4e4\uc5b4 \ub0b8 \uc774\uc775\uacfc \uc704\ud5d8\uc774 \ub204\uad6c\uc5d0\uac8c \uc5b4\ub5bb\uac8c \ubc30\ubd84\ub418\uc5c8\ub294\uc9c0\ub3c4 \ubb3b\uac8c \ud55c\ub2e4. \uc8fc\uc2dd\uc758 \uc5ed\uc0ac\ub294 \uc0c8\ub85c\uc6b4 \uc790\uae08 \uc870\ub2ec\uc758 \uc5ed\uc0ac\uc774\uba74\uc11c \uc2dd\ubbfc\uc9c0\uc758 \uc5ed\uc0ac\uc640 \uacb9\uccd0 \uc788\uc5c8\ub2e4. \ub2e4\uc74c\uc5d0 \uc624\ub798\ub41c \ud68c\uc0ac\uc758 \uc774\ub984\uc744 \ub9cc\ub098\uba74 \uc124\ub9bd \uc5f0\ub3c4\uc640 \ud22c\uc790\uae08\ub9cc \ubcf4\uc9c0 \ub9d0\uace0 \uadf8 \ub3c8\uc774 \uc5b4\ub514\ub85c \uac14\ub294\uc9c0\ub3c4 \uc0b4\ud3b4\ubcf4\uc790. \ub7f0\ub358\uc758 \uafc8\uc740 \uc81c\uc784\uc2a4\ud0c0\uc6b4\uc5d0\uc11c \uae08\uc774 \uc544\ub2cc \ub2f4\ubc30\uc640 \ud798\uaca8\uc6b4 \uc0dd\ud65c\uc744 \ub9cc\ub0ac\ub2e4. \uadf8 \uac04\uaca9\uc744 \uc77d\uc744 \ub54c \uc8fc\uc2dd\uc774\ub77c\ub294 \uc775\uc219\ud55c \ub9d0 \ub4a4\uc758 \uc138\uacc4\uac00 \uc870\uae08 \ub354 \uad6c\uccb4\uc801\uc73c\ub85c \ubcf4\uc778\ub2e4."}, {"id": "a4-fold-same-shape", "title": "A4\ub97c \ubc18\uc73c\ub85c \uc811\uc5b4\ub3c4 \ube44\uc2b7\ud55c \ubaa8\uc591\uc778 \uc774\uc720", "summary": "\uc775\uc219\ud55c \ubcf5\uc0ac\uc6a9\uc9c0\ub97c \uc811\uc73c\uba70 \ud06c\uae30\uc640 \ubaa8\uc591\uc758 \uad00\uacc4\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "science", "category_title": "Science", "subcategory": "Mathematics", "url": "stories/a4-fold-same-shape/index.html", "image": "media/a4-fold-same-shape.jpg", "alt": "A4 210\u00d7297\ubc00\ub9ac\ubbf8\ud130, A4\ub97c \ubc18\uc73c\ub85c \uc811\uc5b4 \ub3cc\ub9b0 148.5\u00d7210\ubc00\ub9ac\ubbf8\ud130, \uc815\uc2dd A5 148\u00d7210\ubc00\ub9ac\ubbf8\ud130\ub97c \uac19\uc740 \ube44\uc728\ub85c \ube44\uad50\ud55c \uc124\uba85\ub3c4.", "text": "A4\ub97c \ubc18\uc73c\ub85c \uc811\uc5b4\ub3c4 \ube44\uc2b7\ud55c \ubaa8\uc591\uc778 \uc774\uc720 \uc885\uc774 \ud55c \uc7a5\uc5d0 \uc228\uc5b4 \uc788\ub294 \uc791\uc740 \ube44\uc728 \uc775\uc219\ud55c \ubcf5\uc0ac\uc6a9\uc9c0\ub97c \uc811\uc73c\uba70 \ud06c\uae30\uc640 \ubaa8\uc591\uc758 \uad00\uacc4\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Mathematics \uacfc\ud559 A4 \uc885\uc774\uc758 \uae34 \ucabd\uc744 \uc808\ubc18\uc73c\ub85c \uc811\uc5b4 \ubcf4\uc790. \uc791\uc544\uc84c\uc9c0\ub9cc \uc6d0\ub798 \uc885\uc774\uc640 \uaf64 \ube44\uc2b7\ud55c \ubaa8\uc591\uc774 \ub41c\ub2e4. \uae38\ucb49\ud55c \uc9c1\uc0ac\uac01\ud615\uc774 \uac11\uc790\uae30 \uc815\uc0ac\uac01\ud615\uc774 \ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud3c9\uc18c\uc5d0\ub294 \uc9c0\ub098\ucce4\uc744 \uc131\uc9c8\uc774\ub2e4. \uac00\ub85c\uc640 \uc138\ub85c\uac00 \uc544\ubb34 \ube44\uc728\uc774\ub098 \ub41c\ub2e4\uba74 \uc774\ub7f0 \ubaa8\uc2b5\uc774 \ub298 \ub098\uc624\uc9c0\ub294 \uc54a\ub294\ub2e4. A \uacc4\uc5f4 \uc885\uc774\ub294 \ud06c\uae30\ub97c \uc904\uc774\uba74\uc11c\ub3c4 \ube44\uc2b7\ud55c \ubaa8\uc591\uc774 \uc774\uc5b4\uc9c0\ub3c4\ub85d \uc0dd\uac01\ud574 \ubcfc \uc218 \uc788\ub294 \uc88b\uc740 \uc608\ub2e4. W3C\uc758 \uc6a9\uc9c0 \uaddc\uaca9 \uc124\uba85\uc740 A4\ub97c 210 \uacf1\ud558\uae30 297\ubc00\ub9ac\ubbf8\ud130, A5\ub97c 148 \uacf1\ud558\uae30 210\ubc00\ub9ac\ubbf8\ud130\ub85c \uc81c\uc2dc\ud55c\ub2e4. A4\uc758 \uae34 \ubcc0\uc744 \ubc18\uc73c\ub85c \ud558\uba74 148.5\ubc00\ub9ac\ubbf8\ud130\ub2e4. \uc815\ud574\uc9c4 A5\uc758 \uc218\uce58\uc640\ub294 \ubc18 \ubc00\ub9ac\ubbf8\ud130 \ucc28\uc774\uac00 \uc788\ub2e4. \ub530\ub77c\uc11c \uc2e4\uc81c \uc885\uc774\ub97c \uc790\ub974\uba74 \uc815\uc2dd A5\uc640 \ud55c \uce58\ub3c4 \ub2e4\ub974\uc9c0 \uc54a\ub2e4\uace0 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \ub450 \uaddc\uaca9\uc744 \ub098\ub780\ud788 \ubcf4\uba74 \uae34 \ubcc0\uacfc \uc9e7\uc740 \ubcc0\uc758 \ube44\uc728\uc774 \ub9e4\uc6b0 \ube44\uc2b7\ud558\ub2e4\ub294 \uac83\uc740 \ud655\uc778\ud560 \uc218 \uc788\ub2e4. \uc774\uc0c1\uc801\uc778 \ube44\uc728\uc5d0\uc11c \uc9e7\uc740 \ubcc0\uc744 1\uc774\ub77c\uace0 \ud558\uba74 \uae34 \ubcc0\uc740 \uc57d 1.414\uac00 \ub41c\ub2e4. \uae34 \ubcc0\uc744 \ubc18\uc73c\ub85c \ub098\ub208 \ub4a4 \uc885\uc774\ub97c \ub3cc\ub824 \ub193\uc73c\uba74 \uc791\uc740 \uc885\uc774\ub3c4 \uc6d0\ub798\uc640 \uac19\uc740 \ube44\uc728\uc744 \uac16\ub294\ub2e4. \uc22b\uc790\ub294 \uc9c1\uc811 \ub098\ub204\uc5b4 \ud655\uc778\ud560 \uc218 \uc788\ub2e4. \uc774 \ube44\uc728\uc740 \uc81c\uacf1\uadfc 2\ub77c\uace0 \ubd80\ub978\ub2e4. \uc774\ub984\uc744 \uc678\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \uad1c\ucc2e\ub2e4. \ubc18\uc73c\ub85c \uc904\uc778 \ub2e4\uc74c \ub3cc\ub824 \ubcf4\uc544\ub3c4 \ubaa8\uc591\uc774 \uc774\uc5b4\uc9c4\ub2e4\ub294 \uc7a5\uba74\uc744 \uba3c\uc800 \ub5a0\uc62c\ub9ac\uba74 \uc218\ud559\uc758 \uc5ed\ud560\uc774 \ud55c\uacb0 \uad6c\uccb4\uc801\uc73c\ub85c \ubcf4\uc778\ub2e4. \uc9c1\uc0ac\uac01\ud615\uc758 \uae34 \ubcc0\uc744 \ubc18\uc73c\ub85c \uc790\ub974\uba74 \ud55c \uc870\uac01\uc758 \ubcc0\uc740 \uc6d0\ub798 \uc9e7\uc740 \ubcc0\uacfc \uae34 \ubcc0\uc758 \uc808\ubc18\uc774 \ub41c\ub2e4. \uc791\uc740 \uc885\uc774\ub97c \ub3cc\ub824 \ubcf4\uba74 \uc5b4\ub290 \ucabd\uc774 \uae34\uc9c0\uc758 \uc5ed\ud560\uc774 \ubc14\ub010\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \uac19\uc740 \ubaa8\uc591\uc774 \ub418\ub824\uba74 \uc0c8 \uae34 \ubcc0\uacfc \uc0c8 \uc9e7\uc740 \ubcc0\uc758 \ube44\uc728\uc774 \ucc98\uc74c\uacfc \ub9de\uc544\uc57c \ud55c\ub2e4. \ub2e8\uc21c\ud788 \ub113\uc774\uac00 \ubc18\uc774 \ub418\ub294 \uac83\ub9cc\uc73c\ub85c\ub294 \ucda9\ubd84\ud558\uc9c0 \uc54a\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \uc9e7\uc740 \ubcc0\uc744 10, \uae34 \ubcc0\uc744 \uc57d 14.14\ub77c\uace0 \uc0dd\uac01\ud574 \ubcf4\uc790. \uae34 \ubcc0\uc758 \uc808\ubc18\uc740 \uc57d 7.07\uc774\uace0 \uc870\uac01\uc740 10\uacfc 7.07\uc758 \ub450 \ubcc0\uc744 \uac00\uc9c4\ub2e4. \ub3cc\ub824 \ub193\uc740 \ub4a4\uc758 \ube44\uc728\ub3c4 \uc57d 1.414\ub2e4. \uc2e4\uc81c \uc885\uc774\uc758 \uce58\uc218\uac00 \uc544\ub2c8\ub77c \ube44\uc728\uc744 \ubcf4\uae30 \uc704\ud574 \uace0\ub978 \uc22b\uc790\ub2e4. \uac04\ub2e8\ud55c \ub098\ub217\uc148\uc73c\ub85c \uc65c \ubaa8\uc591\uc774 \ub2ee\uc544 \ubcf4\uc774\ub294\uc9c0 \ud655\uc778\ud560 \uc218 \uc788\ub2e4. \ub2ee\uc740 \uc9c1\uc0ac\uac01\ud615\uc740 \ubcc0\uc758 \ube44\uc728\uc774 \uac19\uc544\ub3c4 \uc2e4\uc81c \ud06c\uae30\ub294 \ub2e4\ub97c \uc218 \uc788\ub2e4. A4\uc640 \ubc18\uc73c\ub85c \ub098\ub208 \uc870\uac01\uc740 \ub2f9\uc5f0\ud788 \uac19\uc740 \ub113\uc774\uac00 \uc544\ub2c8\ub2e4. \uc5ec\uae30\uc11c \uc720\uc9c0\ud558\ub824\ub294 \uac83\uc740 \ubaa8\uc591\uc758 \uad00\uacc4\ub2e4. \uc218\ud559\uc5d0\uc11c \ube44\uc728\uc744 \uc77d\ub294 \uc77c\uc774 \uc2e4\uc81c \ubb3c\uac74\uc758 \ud06c\uae30\ub97c \uc9c0\uc6b0\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ubb34\uc5c7\uc774 \uac19\uace0 \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc84c\ub294\uc9c0 \ub098\ub204\ub294 \ub3c4\uad6c\uac00 \ub41c\ub2e4. \uc0ac\uc9c4\uc774\ub098 \ubb38\uc11c\ub97c \ud655\ub300\ud560 \ub54c\ub3c4 \uac00\ub85c\uc640 \uc138\ub85c\uc758 \uad00\uacc4\ub97c \ud568\uaed8 \uc720\uc9c0\ud558\uba74 \ubaa8\uc591\uc774 \ucc0c\uadf8\ub7ec\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \uc774\uac83\uc740 \uc6a9\uc9c0\uc758 \ube44\uc728\uc744 \uc774\ud574\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub418\ub294 \ube44\uad50\ub2e4. \ub2e4\ub9cc \ubaa8\ub4e0 \uc778\uc1c4 \ud504\ub85c\uadf8\ub7a8\uc774 \uac19\uc740 \uc5ec\ubc31\uacfc \ubc30\uce58\ub97c \ubcf4\uc7a5\ud55c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc885\uc774\uc758 \uae30\ud558\ud559\uc801\uc778 \uc131\uc9c8\uacfc \uc2e4\uc81c \ucd9c\ub825 \uc124\uc815\uc740 \uc11c\ub85c \ub2e4\ub978 \uc870\uac74\uc774\ub2e4. \uc81c\uacf1\uadfc 2\ub294 \uc815\ud655\ud55c \uad00\uacc4\ub97c \ub098\ud0c0\ub0b4\uc9c0\ub9cc \uc2e4\uc81c \uaddc\uaca9\uc740 \ubc00\ub9ac\ubbf8\ud130 \ub2e8\uc704\uc758 \uc815\uc218\ub85c \uc801\ud78c\ub2e4. A4\uc758 297\uc744 \ubc18\uc73c\ub85c \ud55c 148.5\uc640 A5\uc758 148 \uc0ac\uc774\uc758 \ucc28\uc774\ub294 \uc774\ub7f0 \uc2e4\uc81c \ud45c\uae30\ub97c \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uc774 \ucc28\uc774\uac00 \uc788\ub2e4\uace0 \uc124\uacc4\uc758 \uc544\uc774\ub514\uc5b4\uac00 \ubb34\ub108\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774\uc0c1\uc801\uc778 \ube44\uc728\uacfc \uc4f0\ub294 \uaddc\uaca9\uc758 \uc22b\uc790\ub97c \uad6c\ubd84\ud558\uba74 \ub450 \uc124\uba85\uc744 \ud568\uaed8 \uc77d\uc744 \uc218 \uc788\ub2e4. \ub530\ub77c\uc11c A4\ub97c \uc811\uc73c\uba74 \uc815\uc2dd A5\uc640 \uc5b8\uc81c\ub098 \uc644\uc804\ud788 \uac19\ub2e4\uace0 \ub9d0\ud558\uae30\ubcf4\ub2e4 \ube44\uc728\uc774 \ub9e4\uc6b0 \uac00\uae5d\ub2e4\uace0 \uc124\uba85\ud558\ub294 \ud3b8\uc774 \uc815\ud655\ud558\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 \uacf5\uac1c\ub41c \uce58\uc218\ub85c \uc9c1\uc811 \ub098\ub204\uc5b4 \uadf8 \uad00\uacc4\ub97c \uc0b4\ud3c8\ub2e4. \ubcc4\ub3c4\uc758 \uc885\uc774\ub97c \uc2e4\uce21\ud574 \ubaa8\ub4e0 \uc81c\uc870 \uc624\ucc28\ub97c \ud655\uc778\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uaddc\uaca9\uc5d0 \uad00\ud55c \uc124\uba85\uacfc \uc2e4\uc81c \ud55c \uc7a5\uc758 \uce21\uc815\uc740 \uc9c8\ubb38\uc774 \ub2e4\ub974\ub2e4. \uc6a9\uc9c0 \uc774\ub984\uc740 \ub9e4\uc77c \uc4f0\ub2e4 \ubcf4\uba74 \uc790\uc5f0\ubb3c\uc758 \uc774\ub984\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \uadf8\ub7ec\ub098 \uce58\uc218\uc640 \ube44\uc728\uc744 \uc815\ud558\uba74 \ubb38\uc11c\uc640 \ubcf4\uad00, \ubcf5\uc0ac\uc640 \ubc30\uce58\uac00 \uacf5\ud1b5\uc758 \uc870\uac74\uc744 \uac16\uac8c \ub41c\ub2e4. \ud06c\uae30 \uccb4\uacc4\uac00 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uc0ac\ub78c\ub4e4\uc774 \uc11c\ub85c \ub2e4\ub978 \uacf3\uc5d0\uc11c \ube44\uc2b7\ud55c \uc885\uc774\ub97c \uc54c\uc544\ubcf4\uace0 \uc0ac\uc6a9\ud560 \uc218 \uc788\uac8c \ud55c\ub2e4. \uc885\uc774 \ud55c \uc7a5\uc5d0\ub3c4 \uaddc\uaca9\uc744 \ud1b5\ud55c \ud569\uc758\uac00 \ub4e4\uc5b4 \uc788\ub294 \uc148\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \uc885\uc774\ub97c \ubc18\uc73c\ub85c \uc811\uc744 \ub54c\uc5d0\ub294 \uc5b4\ub290 \ubcc0\uc774 \uc9e7\uc544\uc84c\uace0 \ub3cc\ub824 \ub193\uc73c\uba74 \uc5b4\ub5a4 \ubaa8\uc591\uc778\uc9c0 \uc7a0\uae50 \uc0b4\ud3b4\ubcf4\uc790. \uae30\ud558\ud559\uc744 \uacf5\ubd80\ud558\ub824\uace0 \ubcc4\ub3c4\uc758 \uad50\uad6c\ub97c \ucc3e\uc9c0 \uc54a\uc544\ub3c4 \uc190\uc548\uc5d0\uc11c \ube44\uc728\uc758 \uc9c8\ubb38\uc774 \uc0dd\uae34\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \uae34 \uc22b\uc790\ub97c \uc678\uc6b0\ub294 \uac83\ubcf4\ub2e4 \ubb34\uc5c7\uc744 \ubc18\uc73c\ub85c \ub098\ub204\uace0 \ubb34\uc5c7\uc744 \uac19\uac8c \uc720\uc9c0\ud558\ub824 \ud588\ub294\uc9c0 \ubcf4\ub294 \uc77c\uc774\ub2e4. \ud3c9\ubc94\ud55c \uc885\uc774\uac00 \uc218\ud559\uc758 \uc791\uc740 \uc2e4\ud5d8\uc7a5\uc774 \ub41c\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc124\uba85\ub3c4\ub294 \uc2e4\uc81c A4 \uce58\uc218\uc640 \uadf8 \uc808\ubc18\uc744 \ub098\ub780\ud788 \ube44\uad50\ud55c\ub2e4. \uc815\uc2dd A5\uc758 \uae38\uc774\ub3c4 \ub530\ub85c \ud45c\uc2dc\ud574 \uc774\uc0c1\uc801\uc778 \ube44\uc728\uacfc \uc2e4\uc81c \uaddc\uaca9\uc758 \uc791\uc740 \ucc28\uc774\ub97c \uad6c\ubd84\ud588\ub2e4. \uc885\uc774 \ud55c \uc7a5\uc740 \ud2b9\ubcc4\ud55c \ub3c4\uad6c\uac00 \uc5c6\uc5b4\ub3c4 \uad00\ucc30\ud560 \uc218 \uc788\ub2e4. \ub2e4\uc74c\uc5d0 \ubcf5\uc0ac\uc6a9\uc9c0\ub97c \uc811\uc744 \ub54c \uc791\uc544\uc9c4 \uc885\uc774\ub97c \uc6d0\ub798 \uac83 \uc606\uc5d0 \ub193\uc544 \ubcf4\uc790. \uc77c\uc0c1\uc5d0\uc11c \uc790\uc8fc \uc4f0\ub294 \ubb3c\uac74\uc758 \ud06c\uae30\uc5d0\ub3c4, \uc904\uc774\uace0 \uc774\uc5b4 \uc4f0\uae30 \uc88b\uc740 \uad00\uacc4\ub97c \ucc3e\uc73c\ub824\ub294 \uc0dd\uac01\uc774 \ub4e4\uc5b4 \uc788\ub2e4."}, {"id": "boiling-water-mountain-pressure", "title": "\ub053\ub294 \ubb3c \u2014 \uc0b0\uc5d0\uc11c\ub294 \uc65c 100\ub3c4\ubcf4\ub2e4 \uba3c\uc800 \ub053\uc744\uae4c", "summary": "\uc0b0\uc7a5\uc758 \uc8fc\uc804\uc790\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc555\ub825\u00b7\ub053\ub294\uc810\u00b7\uc0c1\ud0dc \ubcc0\ud654\uc5d0 \ud544\uc694\ud55c \uc5f4\uc758 \ucc28\uc774\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "Science", "subcategory": "Physics", "url": "stories/boiling-water-mountain-pressure/index.html", "image": "media/boiling-water-mountain-pressure.png", "alt": "\uc0b0\uc7a5\uc758 \uc5f4\ub9b0 \uc27c\ud130\uc5d0\uc11c \uc8fc\uc804\uc790\ub85c \ub530\ub73b\ud55c \uc74c\ub8cc\ub97c \uc900\ube44\ud558\ub294 \uc0ac\ub78c\uc758 \uc0bd\ud654.", "text": "\ub053\ub294 \ubb3c \u2014 \uc0b0\uc5d0\uc11c\ub294 \uc65c 100\ub3c4\ubcf4\ub2e4 \uba3c\uc800 \ub053\uc744\uae4c \ubd88\uc758 \uc138\uae30\uc640 \ubb3c\uc758 \ub053\ub294\uc810\uc744 \ub098\ub204\uc5b4 \uc0dd\uac01\ud558\uae30 \uc0b0\uc7a5\uc758 \uc8fc\uc804\uc790\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc555\ub825\u00b7\ub053\ub294\uc810\u00b7\uc0c1\ud0dc \ubcc0\ud654\uc5d0 \ud544\uc694\ud55c \uc5f4\uc758 \ucc28\uc774\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Physics \uacfc\ud559 \ub192\uc740 \uc0b0\uc5d0\uc11c \ubb3c\uc744 \ub053\uc778\ub2e4. \uc8fc\uc804\uc790\uc5d0\uc11c\ub294 \uae40\uc774 \uc624\ub974\uace0 \ubb3c\ub3c4 \ub053\ub294\ub370 \uc74c\uc2dd\uc774 \uc775\ub294 \ub290\ub08c\uc740 \ud3c9\uc18c\uc640 \ub2e4\ub97c \uc218 \uc788\ub2e4. \ub354 \ub192\uc740 \uacf3\uc5d0\uc11c \ub354 \ube68\ub9ac \ub053\ub294\ub2e4\uba74 \ubb3c\uc774 \ub354 \ub728\uac70\uc6cc\uc9c4 \uac83\uc77c\uae4c. \ub053\ub294\ub2e4\ub294 \ub9d0\uacfc \ub728\uac81\ub2e4\ub294 \ub9d0\uc744 \uac19\uc740 \ub73b\uc73c\ub85c \uc4f0\uba74 \uc774 \uc9c8\ubb38\uc774 \ud5f7\uac08\ub9b0\ub2e4. \uc6b0\ub9ac\uac00 \uc678\uc6b4 \ubb3c\uc758 \ub053\ub294\uc810 100\ub3c4\uc5d0\ub294 \uc870\uac74\uc774 \ubd99\uc5b4 \uc788\ub2e4. \uc8fc\ubcc0\uc758 \uc555\ub825\uc774\ub2e4. \uc8fc\ubc29\uacfc \uc0b0\uc7a5\uc5d0\uc11c \ub2ec\ub77c\uc9c0\ub294 \uac83\uc740 \ubd88\uaf43\ub9cc\uc774 \uc544\ub2c8\ub2e4. \ub208\uc5d0 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uacf5\uae30\uc758 \uc555\ub825\uc774 \ubb3c\uc774 \uc561\uccb4\uc5d0\uc11c \uae30\uccb4\ub85c \ubc14\ub00c\ub294 \uc870\uac74\uc5d0 \ud568\uaed8 \ub4e4\uc5b4 \uc788\ub2e4. OpenStax\ub294 \uc21c\uc218\ud55c \ubb3c\uc758 \ub053\ub294\uc810\uc774 \ud45c\uc900\uc801\uc778 \ub300\uae30\uc555 1\uae30\uc555\uc5d0\uc11c \uc12d\uc528 100\ub3c4\ub77c\uace0 \uc124\uba85\ud55c\ub2e4. \uc555\ub825\uc774 \ubc14\ub00c\uba74 \ub053\ub294\uc810\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \ub530\ub77c\uc11c \ubb3c\uc774\ub77c\ub294 \uc774\ub984\ub9cc\uc73c\ub85c \uc5b4\ub290 \ud658\uacbd\uc5d0\uc11c\ub098 \ub611\uac19\uc740 \uc628\ub3c4\uc5d0 \ub053\ub294\ub2e4\uace0 \ud560 \uc218\ub294 \uc5c6\ub2e4. \uc2e4\uc81c \ubb3c\uc5d0\ub294 \ub2e4\ub978 \ubb3c\uc9c8\uc774 \ub179\uc544 \uc788\uc744 \uc218\ub3c4 \uc788\ub2e4. \uc774\ubc88\uc5d0\ub294 \uadf8 \uc601\ud5a5\uc744 \uc7a0\uc2dc \ube7c\uace0 \uc555\ub825\uc758 \uc5ed\ud560\uc5d0 \uc9d1\uc911\ud558\uc790. \uacfc\ud559\uc758 \uc22b\uc790\uc5d0 \uc870\uac74\uc744 \ubd99\uc774\ub294 \uc77c\uc740 \ub2f5\uc744 \ubcf5\uc7a1\ud558\uac8c \ub9cc\ub4e4\ub824\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \ud658\uacbd\uc5d0\uc11c \ub9de\ub294 \ub9d0\uc778\uc9c0 \uc54c\ub824 \uc8fc\uc5b4 \uac19\uc740 \ud604\uc0c1\uc744 \ub2e4\ub978 \uc7a5\uc18c\uc5d0\uc11c\ub3c4 \uc774\ud574\ud558\uac8c \ud558\ub294 \ubc29\ubc95\uc774\ub2e4. \uc816\uc740 \uc218\uac74\uc740 100\ub3c4\uac00 \ub418\uc9c0 \uc54a\uc544\ub3c4 \ub9c8\ub978\ub2e4. \uc561\uccb4\uc758 \uc77c\ubd80\uac00 \uae30\uccb4\ub85c \uc62e\uaca8 \uac00\ub294 \uc99d\ubc1c\uc774 \ub053\uc744 \ub54c\ub9cc \uc77c\uc5b4\ub098\ub294 \uac83\uc740 \uc544\ub2c8\uae30 \ub54c\ubb38\uc774\ub2e4. \uad50\uc7ac\ub294 \uc561\uccb4\uc640 \uae30\uccb4 \uc0ac\uc774\uc5d0\uc11c \ubd84\uc790\ub4e4\uc774 \uc624\uac00\uba70 \uae30\uccb4\uac00 \ub098\ud0c0\ub0b4\ub294 \uc99d\uae30\uc555\uc744 \uc124\uba85\ud55c\ub2e4. \uc628\ub3c4\uac00 \ub192\uc544\uc9c0\uba74 \ubb3c\uc774 \ub098\ud0c0\ub0b4\ub294 \uc99d\uae30\uc555\ub3c4 \ucee4\uc9c4\ub2e4. \ub053\ub294\uc810\uc740 \uc774 \uc99d\uae30\uc555\uc774 \uc8fc\ubcc0\uc5d0\uc11c \ub204\ub974\ub294 \uc555\ub825\uacfc \uac19\uc544\uc9c0\ub294 \uc870\uac74\uc73c\ub85c \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uc6a9\uc5b4\uac00 \ub0af\uc124\ub2e4\uba74 \ubb3c\uc774 \uae30\uccb4\ub85c \uc874\uc7ac\ud558\ub824\ub294 \uc870\uac74\uacfc \uc8fc\ubcc0\uc774 \ub204\ub974\ub294 \uc870\uac74\uc744 \ube44\uad50\ud55c\ub2e4\uace0 \uc0dd\uac01\ud574\ub3c4 \uc88b\ub2e4. \ub2e8\uc21c\ud788 \ubb3c\uc18d\uc5d0\uc11c \ubb34\uc5b8\uac00 \ubcf4\uc778\ub2e4\ub294 \ub9d0\uacfc\ub294 \ub2e4\ub978 \uae30\uc900\uc774\ub2e4. \ub192\uc740 \uc0b0\uc5d0\uc11c\ub294 \uc77c\ubc18\uc801\uc73c\ub85c \ub300\uae30\uc555\uc774 \ub0ae\ub2e4. \uadf8\ub798\uc11c \ubb3c\uc758 \uc99d\uae30\uc555\uc774 \uc8fc\ubcc0 \uc555\ub825\uc5d0 \ub3c4\ub2ec\ud558\ub294 \ub370 \ud544\uc694\ud55c \uc628\ub3c4\ub3c4 \ub0ae\uc544\uc9c4\ub2e4. \ubb3c\uc774 \ub354 \uac15\ud55c \ubd88\uc744 \ubc1b\uc544 \ud2b9\ubcc4\ud55c \uc131\uc9c8\ub85c \ubcc0\ud574\uc11c\uac00 \uc544\ub2c8\ub77c \ubc14\uae65 \uc870\uac74\uc774 \ub2ec\ub77c\uc9c4 \uacb0\uacfc\ub2e4. \uac19\uc740 \uc774\uc720\ub85c \uc0b0\uc5d0\uc11c \ub053\ub294 \ubb3c\uc774 \ud3c9\uc9c0\uc758 \ub053\ub294 \ubb3c\ubcf4\ub2e4 \ubc18\ub4dc\uc2dc \ub354 \ub728\uac70\uc6b4 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ud788\ub824 \ub0ae\uc740 \uc628\ub3c4\uc5d0\uc11c \ub053\uc744 \uc218 \uc788\ub2e4. \uad50\uc7ac\ub3c4 \uace0\ub3c4\uac00 \ub192\uc740 \uacf3\uc758 \ub0ae\uc740 \uc555\ub825\uacfc \ub053\ub294\uc810 \uc0ac\ub840\ub97c \uc81c\uc2dc\ud55c\ub2e4. \ub2e4\ub9cc \ubaa8\ub4e0 \uc0b0\uc7a5\uc758 \uc815\ud655\ud55c \uc628\ub3c4\ub97c \uc774 \uc6d0\ub9ac \ud558\ub098\ub85c \uc9c0\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc2e4\uc81c \uc555\ub825\uc740 \uc7a5\uc18c\uc640 \ub0a0\uc528 \ub4f1\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c4\ub2e4. \uc74c\uc2dd\uc744 \uc775\ud788\ub294 \ub370\ub294 \uc628\ub3c4\uc640 \uc2dc\uac04\uc774 \uc601\ud5a5\uc744 \uc900\ub2e4. \ub0ae\uc740 \uc628\ub3c4\uc5d0\uc11c \ub053\ub294 \ubb3c\uc740 \uae30\ud3ec\uac00 \ud65c\ubc1c\ud558\ub2e4\uace0 \ud3c9\uc9c0\uc640 \uac19\uc740 \uc628\ub3c4\uac00 \ub41c \uac83\uc740 \uc544\ub2c8\ub2e4. \ub530\ub77c\uc11c \ub053\ub294 \ubaa8\uc2b5\uc744 \ubcf4\uace0 \uc870\ub9ac \uc870\uac74\uc774 \uac19\ub2e4\uace0 \ud310\ub2e8\ud558\uba74 \uc608\uc0c1\uacfc \ub2e4\ub978 \uacb0\uacfc\ub97c \ub9cc\ub0a0 \uc218 \uc788\ub2e4. \uc774\ubc88 \uc124\uba85\uc740 \ud2b9\uc815 \uc74c\uc2dd\uc758 \uc870\ub9ac \uc2dc\uac04\uc744 \uc81c\uc2dc\ud558\ub294 \uc548\ub0b4\uac00 \uc544\ub2c8\ub2e4. \ub053\ub294\ub2e4\ub294 \uc0c1\ud0dc\uc640 \uadf8\ub54c\uc758 \uc628\ub3c4\uac00 \ub2e4\ub978 \uc815\ubcf4\ub77c\ub294 \uc810\uc744 \uc774\ud574\ud558\ub294 \uc774\uc57c\uae30\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \ud604\uc0c1\uc774 \uac19\uc544\ub3c4 \uc218\uce58\uc758 \uc870\uac74\uc740 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uc8fc\uc804\uc790 \ud558\ub098\uac00 \uc628\ub3c4\uacc4\uc640 \uae30\uc555\uc758 \uad00\uacc4\ub97c \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uc555\ub825\uacfc \ubb3c\uc758 \uc131\ubd84\uc774 \uc77c\uc815\ud558\uace0 \uc561\uccb4\uac00 \uacc4\uc18d \ub053\ub294 \uc870\uac74\uc5d0\uc11c\ub294 \ub123\uc5b4 \uc900 \uc5f4\uc758 \uc0c1\ub2f9 \ubd80\ubd84\uc774 \ubb3c\uc744 \uae30\uccb4\ub85c \ubc14\uafb8\ub294 \ub370 \uc4f0\uc778\ub2e4. \uc628\ub3c4\ub9cc \uacc4\uc18d \uc62c\ub9ac\ub294 \ub370 \uc0ac\uc6a9\ub418\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc0c1\ud0dc \ubcc0\ud654\uc5d0\ub3c4 \uc5d0\ub108\uc9c0\uac00 \ud544\uc694\ud558\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \uad50\uc7ac\ub294 \ubb3c\uc9c8\uc758 \uc628\ub3c4\ub97c \ubc14\uafb8\ub294 \uc77c\uacfc \uc0c1\ud0dc\ub97c \ubc14\uafb8\ub294 \ub370 \ud544\uc694\ud55c \uc5f4\uc744 \ub098\ub204\uc5b4 \uc124\uba85\ud55c\ub2e4. \ub530\ub77c\uc11c \ubd88\uc744 \uc138\uac8c \ud588\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ub053\ub294 \ubb3c\uc758 \uc628\ub3c4\uac00 \uac19\uc740 \ub9cc\ud07c \ub192\uc544\uc9c4\ub2e4\uace0 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc5f4\uc774 \uc5b4\ub514\ub85c \uc804\ub2ec\ub418\uace0 \uc5b4\ub5a4 \ubcc0\ud654\uc5d0 \uc4f0\uc774\ub294\uc9c0 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc555\ub825\uc1a5\uc740 \uc555\ub825\uc774 \ub192\uc740 \uc870\uac74\uc5d0\uc11c \ubb3c\uc758 \ub053\ub294\uc810\uc774 \uc62c\ub77c\uac08 \uc218 \uc788\ub2e4\ub294 \uc6d0\ub9ac\ub97c \uc774\uc6a9\ud55c\ub2e4. \ubb3c\uc744 \uc561\uccb4 \uc0c1\ud0dc\ub85c \uc720\uc9c0\ud558\uba74\uc11c \ub354 \ub192\uc740 \uc628\ub3c4\uc758 \uc870\ub9ac \ud658\uacbd\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub294 \uac83\uc774\ub2e4. \uc0b0\uc5d0\uc11c \ub0ae\uc740 \uc555\ub825\uc774 \ub053\ub294\uc810\uc744 \ub0ae\ucd94\ub294 \ud604\uc0c1\uacfc \uac19\uc740 \uad00\uacc4\ub97c \ubc18\ub300\ucabd\uc5d0\uc11c \ud65c\uc6a9\ud55c\ub2e4. \uc5ec\uae30\uc11c \ub69c\uaed1\ub9cc \ub36e\uc73c\uba74 \uc5b4\ub5a4 \ub0c4\ube44\ub098 \uac19\uc740 \ud6a8\uacfc\ub97c \ub0b8\ub2e4\uace0 \uc0dd\uac01\ud558\uba74 \uc548 \ub41c\ub2e4. \uc555\ub825\uc744 \ub2e4\ub8e8\ub294 \uc804\uc6a9 \uae30\uad6c\ub294 \uadf8\uc5d0 \ub9de\uac8c \uc124\uacc4\ub418\uace0 \uc0ac\uc6a9\ub418\uc5b4\uc57c \ud55c\ub2e4. \uc774\ubc88 \uae00\uc740 \uc7a5\uce58\ub97c \uac1c\uc870\ud558\ub294 \ubc29\ubc95\ubcf4\ub2e4 \uc555\ub825\uc774\ub77c\ub294 \uc870\uac74\uc774 \ub053\ub294\uc810\uc5d0 \uc601\ud5a5\uc744 \uc900\ub2e4\ub294 \uc6d0\ub9ac\ub97c \uc124\uba85\ud55c\ub2e4. \uc0b0\uc7a5 \uc8fc\uc804\uc790\ub97c \ubcf4\uba74 \uc5f4\uae30\uc640 \ub530\ub73b\ud55c \uc74c\ub8cc\ubd80\ud130 \ub290\uaef4\uc9c4\ub2e4. \uadf8 \uc7a5\uba74\uc5d0\uc11c \ubb34\uc5c7\uc774 \uce21\uc815\ub418\uc5c8\ub294\uc9c0 \ubb3c\uc73c\uba74 \ub2e4\ub978 \uc774\uc57c\uae30\uac00 \uc2dc\uc791\ub41c\ub2e4. \ub053\uace0 \uc788\ub2e4\ub294 \uad00\ucc30\uacfc \uc8fc\ubcc0 \uc555\ub825, \uc2e4\uc81c \ubb3c\uc758 \uc628\ub3c4\ub294 \uc11c\ub85c \uc5f0\uacb0\ub418\uc9c0\ub9cc \uac01\uac01 \ud655\uc778\ud574\uc57c \ud560 \uc815\ubcf4\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uc0b0\uc5d0\uc11c \ub530\ub73b\ud55c \uc74c\ub8cc\ub97c \uc900\ube44\ud558\ub294 \uc0c1\uc0c1 \uc18d \uc7a5\uba74\uc774\ub2e4. \ud2b9\uc815 \uace0\ub3c4\uc758 \ub053\ub294\uc810 \uc2e4\ud5d8\uc774\ub098 \uc870\ub9ac \uae30\uad6c\uc758 \uc2e4\uc81c \uc131\ub2a5\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc0ac\uc9c4\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub9bc\uc5d0\ub294 \ubd84\uc704\uae30\ub97c, \uc6d0\ubb38 \uc790\ub8cc\uc5d0\ub294 \uc6d0\ub9ac\uc758 \uadfc\uac70\ub97c \ub9e1\uaca8 \uc77d\uc73c\uba74 \ub41c\ub2e4. \ubb3c\uc740 100\ub3c4\uc5d0\uc11c \ub053\ub294\ub2e4\ub294 \ubb38\uc7a5\uc5d0 \ud45c\uc900 \ub300\uae30\uc555\uc774\ub77c\ub294 \uc870\uac74\uc744 \ubd99\uc774\uba74 \uc0b0\uc7a5\uc758 \uacbd\ud5d8\uc774 \ub354 \uc774\uc0c1 \uc608\uc678\uc801\uc778 \uc218\uc218\uaed8\ub07c\uac00 \uc544\ub2c8\ub2e4. \uac19\uc740 \uc6d0\ub9ac\uac00 \ub2e4\ub978 \uc555\ub825\uc5d0\uc11c \ub2e4\ub978 \uc628\ub3c4\ub85c \ub098\ud0c0\ub09c \uac83\uc774\ub2e4. \ubc30\uc6b4 \uaddc\uce59\uc744 \ubc84\ub9ac\ub294 \ub300\uc2e0 \uaddc\uce59\uc774 \ub73b\ud558\ub294 \ubc94\uc704\ub97c \ub354 \uc815\ud655\ud788 \uc54c\uac8c \ub41c\ub2e4. \ub2e4\uc74c\uc5d0 \ubb3c\uc774 \ub053\ub294 \ubaa8\uc2b5\uc744 \ub9cc\ub098\uba74 \ubd88\uaf43\uc758 \ud06c\uae30\ub9cc \ubcf4\uc9c0 \ub9d0\uace0 \ubb3c\uc774 \ub193\uc778 \ud658\uacbd\ub3c4 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc5f4\uc744 \ub354 \uc8fc\ub294 \uc77c\uacfc \ub053\ub294\uc810\uc744 \ubc14\uafb8\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \uc775\uc219\ud55c \uc8fc\uc804\uc790\ub294 \uc628\ub3c4\uc640 \uc555\ub825, \uc0c1\ud0dc \ubcc0\ud654\uac00 \uc77c\uc0c1\uc5d0\uc11c \uc5b4\ub5bb\uac8c \ud568\uaed8 \uc791\ub3d9\ud558\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\ub294 \uc791\uc740 \uc2e4\ud5d8\uc2e4\uc774\ub2e4."}, {"id": "bowl-sundial", "title": "\uadf8\ub987\ucc98\ub7fc \uc0dd\uae34 \ud574\uc2dc\uacc4\uc5d0\ub294 \ub450 \uc885\ub958\uc758 \uc120\uc774 \uc788\ub2e4", "summary": "\uc624\ubaa9\ud55c \ud574\uc2dc\uacc4 \uc548\uc744 \ubcf4\uba74 \uc5ec\ub7ec \uc120\uc774 \uad50\ucc28\ud569\ub2c8\ub2e4. \ubaa8\ub450 \uac19\uc740 \uc77c\uc744 \ud558\ub294 \uc120\uc740 \uc544\ub2d9\ub2c8\ub2e4.", "category": "science", "category_title": "Science", "subcategory": "Engineering", "url": "stories/bowl-sundial/index.html", "image": "media/bowl-sundial.jpg", "alt": "\ubc1b\uce68 \uc704\uc5d0 \ub193\uc778 \uccad\ub3d9 \ubc18\uad6c\ud615 \uc559\ubd80\uc77c\uad6c\uc640 \uc548\ucabd \uc120, \uc601\uce68\uc774 \ubcf4\uc774\ub294 \uc0ac\uc9c4", "text": "\uadf8\ub987\ucc98\ub7fc \uc0dd\uae34 \ud574\uc2dc\uacc4\uc5d0\ub294 \ub450 \uc885\ub958\uc758 \uc120\uc774 \uc788\ub2e4 \uc559\ubd80\uc77c\uad6c \uc548\uc5d0\uc11c \uc2dc\uac04\uacfc \uacc4\uc808\uc744 \uc77d\ub294 \ubc29\ubc95 \uc624\ubaa9\ud55c \ud574\uc2dc\uacc4 \uc548\uc744 \ubcf4\uba74 \uc5ec\ub7ec \uc120\uc774 \uad50\ucc28\ud569\ub2c8\ub2e4. \ubaa8\ub450 \uac19\uc740 \uc77c\uc744 \ud558\ub294 \uc120\uc740 \uc544\ub2d9\ub2c8\ub2e4. Engineering \uacfc\ud559 \ubc15\ubb3c\uad00\uc5d0\uc11c \uc559\ubd80\uc77c\uad6c\ub97c \ubcf4\uba74 \uba3c\uc800 \uadf8\ub987 \uac19\ub2e4\ub294 \uc0dd\uac01\uc774 \ub4e0\ub2e4. \uac00\uc6b4\ub370\uc5d0\ub294 \ubc14\ub298\ucc98\ub7fc \uc0dd\uae34 \ubb3c\uac74\uc774 \ube44\uc2a4\ub4ec\ud788 \uc11c \uc788\uace0, \uc548\ucabd\uc5d0\ub294 \uc5ec\ub7ec \uc904\uc774 \uc0c8\uaca8\uc838 \uc788\ub2e4. \uc774\ub984\uc5d0\ub3c4 \uadf8 \ubaa8\uc2b5\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc740 \uc559\ubd80\uc77c\uad6c\ub97c \uc1a5 \ubaa8\uc591\uc758 \ud574\uc2dc\uacc4\ub77c\ub294 \ub73b\uc73c\ub85c \uc124\uba85\ud55c\ub2e4. \uc775\uc219\ud55c \ub514\uc9c0\ud138\uc2dc\uacc4\ucc98\ub7fc \uc22b\uc790\uac00 \ucc28\ub840\ub85c \ubc14\ub00c\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub300\uc2e0 \ube5b\uacfc \uadf8\ub9bc\uc790\uac00 \ud45c\uc2dc\ub97c \uc6c0\uc9c1\uc778\ub2e4. \uadf8\ub7f0\ub370 \uc548\ucabd\uc758 \uc120\uc740 \uc2dc\uac04\uc744 \ub098\ub204\uae30 \uc704\ud55c \uac83\ub9cc\uc740 \uc544\ub2c8\ub2e4. \uacc4\uc808\uc744 \uc54c\ub824\uc8fc\ub294 \uc120\ub3c4 \ud568\uaed8 \uc788\ub2e4. \uc559\ubd80\uc77c\uad6c\ub294 \ud574\uadf8\ub9bc\uc790\ub97c \ubc1b\ub294 \uc624\ubaa9\ud55c \uba74\uacfc, \uadf8\ub9bc\uc790\ub97c \ub9cc\ub4e4\uc5b4 \ub0b4\ub294 \ubc14\ub298\ub85c \uc774\ub8e8\uc5b4\uc9c4\ub2e4. \ub3c4\uad6c\ub97c \ubcfc \ub54c\ub294 \ubc14\ub298\ub9cc\ud07c \uadf8\ub9bc\uc790\uac00 \uc5b4\ub514\uc5d0 \ub4dc\ub9ac\uc6cc\uc9c0\ub294\uc9c0\ub3c4 \uc911\uc694\ud558\ub2e4. \ubc15\ubb3c\uad00 \uc18c\uc7a5\ud488 \uc124\uba85\uc5d0\uc11c\ub294 \uc548\ucabd \uba74\uc744 \uc2dc\ubc18, \ubc14\ub298\uc744 \uc601\uce68\uc774\ub77c\uace0 \ubd80\ub978\ub2e4. \uc5b4\ub824\uc6b4 \uc774\ub984\uc744 \uc678\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \uc5ed\ud560\uc740 \ub098\ub204\uc5b4 \ubcfc \uc218 \uc788\ub2e4. \ud558\ub098\ub294 \uadf8\ub9bc\uc790\ub97c \ub9cc\ub4e4\uace0, \ub2e4\ub978 \ud558\ub098\ub294 \uadf8 \uadf8\ub9bc\uc790\ub97c \uc77d\ub294 \uc790\ub9ac\ub2e4. \ube5b\uc774 \ub4e4\uc5b4\uc624\ub294 \uc870\uac74\uc5d0 \ub530\ub77c \ubc14\ub298\uc758 \uadf8\ub9bc\uc790\uac00 \ub193\uc774\ub294 \uc704\uce58\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \uc548\ucabd\uc5d0 \uc0c8\uaca8 \ub454 \uc120\ub4e4\uc740 \uadf8 \uc704\uce58\ub97c \uadf8\ub0e5 \uc9c0\ub098\uac00\ub294 \ubaa8\uc591\uc774 \uc544\ub2c8\ub77c \uc815\ubcf4\ub85c \uc77d\uc744 \uc218 \uc788\uac8c \ud55c\ub2e4. \uc18c\uc7a5\ud488 \uc124\uba85\uc5d0 \ub530\ub974\uba74 \uc2dc\uacc4 \uc548\uc5d0\ub294 \uc2dc\uac01\uc744 \ub098\ub204\ub294 \uc120\uacfc \uc808\uae30\ub97c \ub098\ud0c0\ub0b4\ub294 \uac00\ub85c\uc120\uc774 \uc788\ub2e4. \uac19\uc740 \uba74 \uc704\uc5d0 \ub450 \uc885\ub958\uc758 \uae30\uc900\uc744 \uacb9\uccd0 \ub454 \uac83\uc774\ub2e4. \uacc4\uc808\uc5d0 \ub530\ub77c \ud574\uadf8\ub9bc\uc790\uc758 \uae38\uc774\uac00 \ub2ec\ub77c\uc9c0\ubbc0\ub85c, \ub3d9\uc9c0\uc640 \ud558\uc9c0\uc758 \uadf8\ub9bc\uc790\ub3c4 \uac19\uc740 \uc790\ub9ac\uc5d0 \ub193\uc774\uc9c0 \uc54a\ub294\ub2e4. \ubc15\ubb3c\uad00\uc740 \ub3d9\uc9c0\uc5d0\ub294 \uac00\uc7a5 \ubc14\uae65\ucabd \uacc4\uc808\uc120, \ud558\uc9c0\uc5d0\ub294 \uac00\uc7a5 \uc548\ucabd \uacc4\uc808\uc120\uc5d0 \uadf8\ub9bc\uc790\uac00 \uc704\uce58\ud55c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uadf8\ub7ec\ub2c8 \ubc14\ub2e5\uc758 \uc120\uc744 \ubaa8\ub450 \ubcf5\uc7a1\ud55c \uc7a5\uc2dd\uc73c\ub85c \ubcfc \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5b4\ub290 \ubc29\ud5a5\uc73c\ub85c \uc2dc\uac04\uc744 \uc77d\uace0 \uc5b4\ub5a4 \uc120\uc73c\ub85c \uacc4\uc808\uc744 \uc0b4\ud53c\ub294\uc9c0 \ub098\ub204\uc5b4 \ubcf4\uba74 \uc870\uae08 \uc815\ub9ac\uac00 \ub41c\ub2e4. \uc22b\uc790\uc640 \uace1\uc120\uc774 \ub9ce\uc740 \uc774\uc720\uac00 \uc788\ub294 \uc148\uc774\ub2e4. \ub2e4\ub9cc \uc0ac\uc9c4 \ud55c \uc7a5\ub9cc \ubcf4\uace0 \uc2e4\uc81c \uc2dc\uac04\uc744 \uc815\ud655\ud558\uac8c \uc77d\uc5b4 \ubcf4\ub824 \ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub193\uc778 \ubc29\ud5a5\uacfc \ube5b\uc758 \uc870\uac74\uc774 \ub9de\uc544\uc57c \ud558\ub294 \ub3c4\uad6c\ub2e4. \uc804\uc2dc\uc7a5\uc5d0\uc11c \ubcf4\ub294 \ubaa8\uc2b5\uacfc \uc2e4\uc81c\ub85c \uc2dc\uac04\uc744 \uc7ac\ub294 \uc0c1\ud669\uc740 \uad6c\ubd84\ud558\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc559\ubd80\uc77c\uad6c\uc758 \uc624\ubaa9\ud55c \uba74\uc740 \ubb34\uc5c7\uc744 \ub2f4\ub294 \uadf8\ub987\uc758 \uc548\ucabd\uacfc \ub2ee\uc558\uc9c0\ub9cc \uadf8\ub9bc\uc790\uc758 \uc704\uce58\ub97c \uc77d\ub3c4\ub85d \uc900\ube44\ud55c \uc790\ub9ac\ub2e4. \ud45c\uba74\uc5d0 \uc120\uc774 \uc788\uace0 \uadf8 \uc704\uc5d0 \ubc14\ub298\uc758 \uadf8\ub9bc\uc790\uac00 \ub193\uc778\ub2e4. \ub3c4\uad6c\uc758 \ud615\ud0dc\uc640 \uae30\uc900\uc758 \ud45c\uc2dc, \ube5b\uc774 \ud568\uaed8 \uc788\uc5b4\uc57c \uc815\ubcf4\uac00 \ub41c\ub2e4. \ubb3c\uac74\ub9cc \uc788\ub2e4\uace0 \uc5b8\uc81c \uc5b4\ub514\uc11c\ub4e0 \uace7\ubc14\ub85c \uac19\uc740 \ub2f5\uc744 \uc8fc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc601\uce68\uc774 \ubd81\uadf9 \ucabd\uc744 \ud5a5\ud558\ub3c4\ub85d \ub193\uc778\ub2e4\ub294 \uc124\uba85\ub3c4 \uadf8\ub798\uc11c \uc911\uc694\ud558\ub2e4. \uc7a5\uc2dd\uc774 \ub9c8\uc74c\uc5d0 \ub4dc\ub294 \ubc29\ud5a5\uc73c\ub85c \ub3cc\ub824 \ub193\ub294 \uac83\uacfc \uc2dc\uac04\uc744 \uc7ac\uae30 \uc704\ud574 \ubc29\ud5a5\uc744 \ub9de\ucd94\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \uc804\uc2dc\uc7a5\uc5d0\uc11c \ubcf4\uc774\ub294 \ub3c4\uad6c\uc640 \uc2e4\uc81c \uc57c\uc678 \uce21\uc815\uc758 \uc870\uac74\uc744 \uad6c\ubd84\ud558\uba74, \uc0ac\uc9c4\uc758 \uadf8\ub9bc\uc790\ub97c \uadf8\ub300\ub85c \ud604\uc7ac \uc2dc\uac01\uc774\ub77c\uace0 \uc77d\ub294 \uc624\ub958\ub97c \ud53c\ud560 \uc218 \uc788\ub2e4. \uc790\ub8cc\ub294 \uc5f4\uc138 \uac1c\uc758 \uacc4\uc808\uc120\uc73c\ub85c \uc2a4\ubb3c\ub124 \uc808\uae30\uc640 \uad00\ub828\ub41c \uc815\ubcf4\ub97c \ud45c\ud604\ud55c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc22b\uc790\uac00 \ub2e4\ub974\ub2e4\uace0 \uace7 \uc798\ubabb \uc801\ud78c \uac83\uc740 \uc544\ub2c8\ub2e4. \ud55c \ud574 \ub3d9\uc548 \ud574\uac00 \ub192\uc544\uc84c\ub2e4\uac00 \ub0ae\uc544\uc9c0\ub294 \ud750\ub984\uc744 \uc0dd\uac01\ud558\uba74 \ube44\uc2b7\ud55c \uadf8\ub9bc\uc790 \uc870\uac74\uc744 \uc77c \ub144\uc758 \uc11c\ub85c \ub2e4\ub978 \ub54c\uc5d0 \ub9cc\ub0a0 \uc218 \uc788\ub2e4. \ubaa8\ub4e0 \uc808\uae30\uc5d0 \ub3c5\ub9bd\ub41c \uc120 \ud558\ub098\uc529\uc774 \uaf2d \ud544\uc694\ud55c \uad6c\uc870\ub294 \uc544\ub2c8\ub2e4. \uc5ec\uae30\uc11c \uc804\uccb4 \ucc9c\ubb38 \uacc4\uc0b0\uc744 \uc0c8\ub85c \uc99d\uba85\ud558\uac70\ub098 \uc774 \uc0ac\uc9c4\ub9cc\uc73c\ub85c \ub0a0\uc9dc\ub97c \uc0b0\ucd9c\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc120\ub4e4\uc774 \ub9e1\uc740 \uc5ed\ud560\uc774 \ub2e4\ub974\ub2e4\ub294 \uc774\ud574\uac00 \uba3c\uc800\ub2e4. \uc2dc\uac01\uc744 \ub098\ub204\ub294 \uae30\uc900\uacfc \uacc4\uc808\uc744 \uac00\ub9ac\ud0a4\ub294 \uae30\uc900\uc744 \ubd84\ub9ac\ud574\uc11c \ubcf4\uba74 \ubcf5\uc7a1\ud558\uac8c \uc5bd\ud78c \ubb34\ub2ac\uac00 \uc870\uae08 \uc815\ub9ac\ub41c\ub2e4. \uc5ec\ub7ec \uc815\ubcf4\ub97c \ud55c \ud45c\uba74\uc5d0\uc11c \uc77d\uac8c \ub9cc\ub4e0 \uc124\uacc4\uc758 \uc0ac\ub840\ub2e4. \uacc4\uc808\uc5d0 \ub530\ub77c \ud574\uadf8\ub9bc\uc790\uac00 \ub2ec\ub77c\uc9c0\uae30 \ub54c\ubb38\uc5d0 \uc2dc\uac04\ub9cc \uac19\uc740 \ub0a0\ub4e4\uc744 \ud55c \uac00\uc9c0 \uc120\uc73c\ub85c \uc0dd\uac01\ud558\uae30 \uc5b4\ub835\ub2e4. \ubc15\ubb3c\uad00\uc774 \ub3d9\uc9c0\uc120\uacfc \ud558\uc9c0\uc120\uc758 \uc704\uce58\ub97c \ub530\ub85c \uc9da\uc5b4 \uc8fc\ub294 \uc774\uc720\ub2e4. \ud558\ub8e8 \ub3d9\uc548 \uc6c0\uc9c1\uc774\ub294 \uadf8\ub9bc\uc790\uc640 \ud55c \ud574\ub97c \ub530\ub77c \ub2ec\ub77c\uc9c0\ub294 \uc870\uac74\uc774 \uac19\uc740 \ub3c4\uad6c\uc5d0 \ub2f4\uae34\ub2e4. \uc791\uc740 \uc2dc\uacc4\uac00 \uc77c\uc0c1\uc758 \uc2dc\uac04\uacfc \uacc4\uc808\uc758 \uc2dc\uac04\uc744 \ud568\uaed8 \ub2e4\ub8e8\ub294 \uc148\uc774\ub2e4. \uc774 \uc810\uc744 \uc54c\uba74 \ud574\uc2dc\uacc4\uac00 \ub2e8\uc21c\ud788 \ub9c9\ub300 \ud558\ub098\uc758 \uadf8\ub9bc\uc790\ub97c \ubcf4\ub294 \uac83\ub9cc\uc740 \uc544\ub2d8\uc744 \ub290\ub084 \uc218 \uc788\ub2e4. \ud45c\uba74\uc744 \uc5b4\ub5a4 \ud615\ud0dc\ub85c \ub9cc\ub4e4\uace0 \uae30\uc900\uc744 \uc5b4\ub5bb\uac8c \uc0c8\uae38\uc9c0\uc758 \uc120\ud0dd\uc774 \uc788\uc5c8\ub2e4. \ub2e4\ub9cc \ub2e4\ub978 \ud574\uc2dc\uacc4\uc758 \ud45c\uc2dc\ubc95\uc744 \ubaa8\ub450 \uc774 \ud55c \uc810\uacfc \uac19\ub2e4\uace0 \uc77c\ubc18\ud654\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uad6c\uccb4\uc801\uc778 \uc18c\uc7a5\ud488\uc758 \uc124\uba85\uc744 \uae30\uc900\uc73c\ub85c \ub3c4\uad6c\uc758 \uad6c\uc870\ub97c \uc0b4\ud3b4\ubcf4\ub294 \ud3b8\uc774 \uc815\ud655\ud558\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc559\ubd80\uc77c\uad6c\uac00 \uc138\uc885\ub300\uc5d0 \ucc98\uc74c \ub9cc\ub4e4\uc5b4\uc838 \uc11c\uc6b8\uc758 \ud61c\uc815\uad50\uc640 \uc885\ubb18 \ub0a8\ucabd \uac70\ub9ac\ucc98\ub7fc \uc0ac\ub78c\uc774 \ub9ce\uc774 \ub2e4\ub2c8\ub294 \uacf3\uc5d0 \uc124\uce58\ub418\uc5c8\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \uac1c\uc778\uc758 \uc791\uc740 \ubb3c\uac74\uc774 \uc544\ub2c8\ub77c \uae38\uc5d0\uc11c \uc2dc\uac04\uc744 \ub9cc\ub098\ub294 \ubc29\uc2dd\ub3c4 \uc788\uc5c8\ub358 \uac83\uc774\ub2e4. \uc9c0\uae08\uc740 \uc8fc\uba38\ub2c8\uc758 \ud654\uba74\ub9cc \uc5f4\uc5b4\ub3c4 \uc2dc\uac04\uc744 \ud655\uc778\ud560 \uc218 \uc788\ub2e4. \uadf8\ub798\uc11c \ud558\ub098\uc758 \uc2dc\uacc4\ub97c \uc5ec\ub7ec \uc0ac\ub78c\uc774 \ubc14\ub77c\ubcf4\ub294 \ud48d\uacbd\uc774 \uc870\uae08 \ub0af\uc124\uac8c \ub290\uaef4\uc9c8 \uc218\ub3c4 \uc788\ub2e4. \uc559\ubd80\uc77c\uad6c\ub97c \ub2e4\uc2dc \ubcf4\uba74 \uadf8\ub987 \uac19\uc740 \ubab8\uccb4 \uc548\uc5d0 \uadf8 \ud48d\uacbd\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \ud574\ub97c \ubcf4\uace0 \ubc14\ub298\uc758 \uadf8\ub9bc\uc790\ub97c \ucc3e\uace0, \uc120\uc744 \ub530\ub77c \uc2dc\uac04\uc744 \uc77d\ub294 \uc0ac\ub78c\ub4e4\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \uc774 \ud574\uc2dc\uacc4\ub97c \ub9cc\ub098\uba74 \ubc14\ub298\uacfc \uace1\uc120\uc744 \ub530\ub85c \ud55c\ubc88 \ubcf4\uc544\ub3c4 \uc88b\uaca0\ub2e4. \ubcf5\uc7a1\ud574 \ubcf4\uc774\ub358 \uc548\ucabd \uba74\uc774, \uc2dc\uac04\uacfc \uacc4\uc808\uc744 \ud568\uaed8 \ud3bc\uccd0 \ub193\uc740 \uc791\uc740 \uc9c0\ub3c4\ucc98\ub7fc \ubcf4\uc77c \uc218 \uc788\ub2e4."}, {"id": "braille-six-dots", "title": "\uc5ec\uc12f \uac1c\uc758 \uc810\uc73c\ub85c \uc5bc\ub9c8\ub098 \ub9ce\uc740 \ubaa8\uc591\uc744 \ub9cc\ub4e4\uae4c", "summary": "6\uc810 \uc810\uc790\uc5d0\uc11c \uc810\uc758 \uc218\ubcf4\ub2e4 \uc704\uce58\uac00 \uc911\uc694\ud558\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ubd05\ub2c8\ub2e4.", "category": "science", "category_title": "Science", "subcategory": "Mathematics", "url": "stories/braille-six-dots/index.html", "image": "media/braille-six-dots.jpg", "alt": "6\uc810 \uc810\uc790\uc758 \uc67c\ucabd \uc810\uc740 \uc704\uc5d0\uc11c 1\u00b72\u00b73\ubc88, \uc624\ub978\ucabd\uc740 4\u00b75\u00b76\ubc88\uc785\ub2c8\ub2e4. a\ub294 1\ubc88, b\ub294 1\u00b72\ubc88, c\ub294 1\u00b74\ubc88 \uc810\uc73c\ub85c \ud45c\uc2dc\ud55c \ub77c\ud2f4 \ubb38\uc790 \uc608\uc785\ub2c8\ub2e4.", "text": "\uc5ec\uc12f \uac1c\uc758 \uc810\uc73c\ub85c \uc5bc\ub9c8\ub098 \ub9ce\uc740 \ubaa8\uc591\uc744 \ub9cc\ub4e4\uae4c \uc810\uc790 \ud55c \uce78\uc5d0\uc11c \uc2dc\uc791\ud558\ub294 \uc870\ud569 \uc774\uc57c\uae30 6\uc810 \uc810\uc790\uc5d0\uc11c \uc810\uc758 \uc218\ubcf4\ub2e4 \uc704\uce58\uac00 \uc911\uc694\ud558\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ubd05\ub2c8\ub2e4. Mathematics \uacfc\ud559 \uc810 \uc5ec\uc12f \uac1c\uac00 \uc138\ub85c\ub85c \uc138 \uac1c\uc529, \ub450 \uc904\ub85c \ub098\ub780\ud788 \ub193\uc5ec \uc788\ub2e4. \uc5b4\ub5a4 \uc810\uc740 \uc62c\ub77c\uc624\uace0 \uc5b4\ub5a4 \uc790\ub9ac\ub294 \ube44\uc5b4 \uc788\ub2e4. \ud55c \uce78 \uc548\uc5d0\uc11c \uc774 \ucc28\uc774\ub97c \uc870\ud569\ud558\uba74 \uc11c\ub85c \ub2e4\ub978 \ubaa8\uc591\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub2e4. 6\uc810 \uc810\uc790\ub97c \uc0dd\uac01\ud558\ub294 \uc791\uc740 \ucd9c\ubc1c\uc810\uc774\ub2e4. \uadf8\uc800 \uc810\uc774 \uba87 \uac1c \uc788\ub294\uc9c0\ub9cc \uc138\uba74 \ub193\uce58\ub294 \ubd80\ubd84\uc774 \uc788\ub2e4. \uc810\uc774 \ud558\ub098\ub77c\ub3c4 \uc5b4\ub290 \uc790\ub9ac\uc5d0 \uc788\ub294\uc9c0\uc5d0 \ub530\ub77c \ubaa8\uc591\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uac1c\uc218\uc640 \uc704\uce58\ub294 \uac19\uc740 \uc815\ubcf4\uac00 \uc544\ub2cc \uac83\uc774\ub2e4. \uac01 \uc790\ub9ac\uc5d0\ub294 \uc62c\ub77c\uc628 \uc810\uc774 \uc788\uac70\ub098 \uc5c6\ub2e4. \ub450 \uac00\uc9c0 \uc120\ud0dd\uc774\ub2e4. \uadf8\ub7f0 \uc790\ub9ac\uac00 \uc5ec\uc12f \uac1c\uba74 \uac00\ub2a5\ud55c \uc870\ud569\uc740 2\ub97c \uc5ec\uc12f \ubc88 \uacf1\ud55c 64\uac00\uc9c0\ub2e4. \uc544\ubb34 \uc810\ub3c4 \uc5c6\ub294 \uacbd\uc6b0\ub97c \ube7c\uba74 \uc810\uc774 \ud558\ub098 \uc774\uc0c1 \uc788\ub294 \ud615\ud0dc\ub294 63\uac00\uc9c0\uac00 \ub41c\ub2e4. \uc774\uac83\uc740 \uc810\uc790 \uc804\uccb4\uc758 \ub73b\uc774 63\uac1c\ubfd0\uc774\ub77c\ub294 \ub9d0\uc774 \uc544\ub2c8\ub2e4. \ud55c \uce78\uc758 \ubaa8\uc591\uc744 \uc138\uc5b4 \ubcf8 \uacc4\uc0b0\uc774\ub2e4. \uc5ec\ub7ec \uce78\uc744 \uc774\uc5b4 \uc77d\uace0 \ubb38\ub9e5\uacfc \uaddc\uce59\uc744 \uc801\uc6a9\ud558\ub294 \uc77c\uc740 \uadf8\ub2e4\uc74c\uc5d0 \uc788\ub2e4. \uc810\uc790 \ubcc0\ud658 \ud504\ub85c\uc81d\ud2b8 Liblouis\uc758 \ub77c\ud2f4 \ubb38\uc790 \uc815\uc758\ub97c \ubcf4\uba74 \uc18c\ubb38\uc790 a\ub294 1\ubc88 \uc810, b\ub294 1\ubc88\uacfc 2\ubc88 \uc810\uc73c\ub85c \ub098\ud0c0\ub09c\ub2e4. c\ub294 1\ubc88\uacfc 4\ubc88 \uc810\uc774\ub2e4. b\uc640 c\ub294 \uc810 \ub450 \uac1c\ub77c\ub294 \uc810\uc5d0\uc11c\ub294 \uac19\uc9c0\ub9cc \ubc30\uce58\uac00 \ub2e4\ub974\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uc124\uba85\ub3c4\ub294 \uc774 \uc138 \uac00\uc9c0\ub97c \ub098\ub780\ud788 \ubcf4\uc5ec \uc900\ub2e4. \uae00\uc790 \uc774\ub984\uacfc \uc810 \ubc88\ud638\ub97c \ubd99\uc5ec \uc704\uce58\uc758 \ucc28\uc774\ub97c \ud655\uc778\ud558\ub3c4\ub85d \ub9cc\ub4e4\uc5c8\ub2e4. \uc2e4\uc81c \uc77d\uae30\uc5d0 \ud544\uc694\ud55c \ubaa8\ub4e0 \uc810\uc790 \uaddc\uce59\uc744 \ub300\uc2e0\ud558\ub294 \ud45c\ub294 \uc544\ub2c8\ub2e4. b\uc640 c\ub294 \ub458 \ub2e4 \uc810 \ub450 \uac1c\ub97c \uc4f0\uc9c0\ub9cc \ub193\uc774\ub294 \uc790\ub9ac\uac00 \ub2e4\ub974\ub2e4. \ub530\ub77c\uc11c \uac00\ub2a5\ud55c \ubaa8\uc591\uc744 \uc140 \ub54c \uc810\uc774 \uba87 \uac1c\uc778\uc9c0\ub9cc \uc138\uba74 \ubd80\uc871\ud558\ub2e4. \uc5ec\uc12f \uc790\ub9ac \uac01\uac01\uc5d0\uc11c \uc810\uc758 \uc720\ubb34\ub97c \ubcf4\uc544\uc57c \ud55c\ub2e4. \uac19\uc740 \uac1c\uc218\uc758 \uc810\ub3c4 \ub2e4\ub978 \ubc30\uc5f4\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ubb38\uc790 \ud45c\uae30\uc758 \uacf5\uac04\uc801\uc778 \uc131\uaca9\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc774\ub294 \uc8fc\uc0ac\uc704\uc758 \uc22b\uc790\ub97c \uc54c\uc544\ubcf4\ub294 \uacbd\ud5d8\uacfc \ub2ee\uc740 \uc810\uc774 \uc788\uc9c0\ub9cc \uac19\uc740 \uccb4\uacc4\ub294 \uc544\ub2c8\ub2e4. \uc8fc\uc0ac\uc704\uc758 \ubaa8\ub4e0 \ubc30\uce58\ub97c \ubb38\uc790\ub85c \uc77d\ub294 \uac83\uc740 \uc544\ub2c8\uae30 \ub54c\ubb38\uc774\ub2e4. \uc775\uc219\ud55c \uc608\ub294 \uc704\uce58\uac00 \uc911\uc694\ud558\ub2e4\ub294 \uc810\uc744 \uc774\ud574\ud558\ub294 \ub370\ub9cc \uc0ac\uc6a9\ud558\uba74 \ub41c\ub2e4. \uc2e4\uc81c \uc810\uc790\uc758 \uaddc\uce59\uc740 \uc5b8\uc5b4\uc640 \uc6a9\ub3c4\uc5d0 \ub9de\ub294 \uc790\ub8cc\ub97c \ub530\ub77c \uc77d\uc5b4\uc57c \ud55c\ub2e4. \ube44\uc720\uac00 \ud559\uc2b5\ud45c\ub97c \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc790\ub9ac\uac00 \ud558\ub098\uc774\uace0 \uc810\uc774 \uc788\uac70\ub098 \uc5c6\uc744 \uc218 \uc788\ub2e4\uba74 \ub450 \uac00\uc9c0\ub2e4. \ub450 \uc790\ub9ac\uc5d0\uc11c\ub294 \uccab \uc790\ub9ac\uc5d0 \ub300\ud55c \ub450 \uc120\ud0dd\ub9c8\ub2e4 \ub458\uc9f8 \uc790\ub9ac\uc758 \ub450 \uc120\ud0dd\uc774 \uc774\uc5b4\uc838 \ub124 \uac00\uc9c0\uac00 \ub41c\ub2e4. \uc5ec\uc12f \uc790\ub9ac\uc5d0\uc11c\ub3c4 \uac19\uc740 \uc0dd\uac01\uc744 \ubc18\ubcf5\ud574 64\ub97c \uc5bb\ub294\ub2e4. \uc5b4\ub824\uc6b4 \uacf5\uc2dd\uc744 \uba3c\uc800 \uc678\uc6b0\uae30\ubcf4\ub2e4 \uc120\ud0dd\uc774 \ud558\ub098\uc529 \ub354\ud574\uc9c8 \ub54c \uacbd\uc6b0\uc758 \uc218\uac00 \uc5b4\ub5bb\uac8c \ub298\uc5b4\ub098\ub294\uc9c0 \ubcf4\ub294 \uac83\uc774\ub2e4. \uc774 \uacc4\uc0b0\uc5d0\ub294 \uc544\ubb34 \uc810\ub3c4 \uc5c6\ub294 \uacbd\uc6b0\uac00 \ud3ec\ud568\ub41c\ub2e4. \uadf8\ub798\uc11c \uc810\uc774 \uc2e4\uc81c\ub85c \ud558\ub098 \uc774\uc0c1 \uc788\ub294 \ubaa8\uc591\ub9cc \uc138\uba74 63\uc774\ub77c\ub294 \ub2e4\ub978 \uc22b\uc790\uac00 \ub098\uc628\ub2e4. 64\uc640 63\uc774 \uc11c\ub85c \ub2e4\ub978 \uc8fc\uc7a5\uc744 \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubb34\uc5c7\uc744 \uc138\uc5c8\ub294\uc9c0\uc758 \ubc94\uc704\uac00 \ub2e4\ub974\ub2e4. \uc218\ub97c \uc815\ud655\ud788 \uc77d\uc73c\ub824\uba74 \uacc4\uc0b0\ubfd0 \uc544\ub2c8\ub77c \ud3ec\ud568\ud558\uace0 \uc81c\uc678\ud55c \ub300\uc0c1\uc744 \uc54c\uc544\uc57c \ud55c\ub2e4\ub294 \uc88b\uc740 \uc608\ub2e4. \ud55c \uce78\uc758 \ud615\ud0dc\uac00 \uc815\ud574\uc9c4 \uc218\ub77c\uace0 \ud574\uc11c \uc810\uc790\ub85c \uc804\ud560 \uc218 \uc788\ub294 \ub0b4\uc6a9\ub3c4 \uadf8 \uc218\ub9cc\ud07c\uc774\ub77c\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc5ec\ub7ec \uce78\uc744 \uc774\uc5b4 \ub193\uace0 \ubb38\ub9e5\uacfc \ud45c\uae30 \uaddc\uce59\uc744 \uc0ac\uc6a9\ud55c\ub2e4. \uac19\uc740 \ud615\ud0dc\ub3c4 \uc5b4\ub5a4 \uc5b8\uc5b4\uc640 \uc57d\uc18d \uc548\uc5d0\uc11c \uc77d\ub294\uc9c0 \uc911\uc694\ud558\ub2e4. \uc791\uc740 \uae30\ubcf8 \ub2e8\uc704\uc640 \uc804\uccb4 \ud45c\ud604 \uccb4\uacc4\ub294 \uac19\uc740 \ud06c\uae30\uc758 \ub300\uc0c1\uc774 \uc544\ub2c8\ub2e4. \uadf8\ub798\uc11c \ub77c\ud2f4 \ubb38\uc790 \uc608\uc2dc\ub97c \ud55c\uad6d\uc5b4\uc758 \ubaa8\ub4e0 \ud45c\uae30\uc5d0 \uadf8\ub300\ub85c \uc801\uc6a9\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uacf5\uc2dd \ubcc0\ud658 \ub3c4\uad6c\uac00 \uc5b8\uc5b4\ubcc4 \uaddc\uce59\uc744 \uad6c\ubd84\ud558\ub294 \uc774\uc720\ub3c4 \uc788\ub2e4. \uc774 \uae00\uc740 \uc5ec\uc12f \uc810\uc758 \uad6c\uc870\ub97c \uc774\ud574\ud558\ub294 \uc785\uad6c\uc774\uc9c0 \uc810\uc790\ub97c \uc644\uc804\ud788 \uc77d\uac8c \ud558\ub294 \uad50\uc7ac\ub294 \uc544\ub2c8\ub2e4. \ubb38\uc790\uc5d0 \uad00\uc2ec\uc744 \uac16\ub294 \uc77c\uacfc \uc2e4\uc81c \uc811\uadfc \uac00\ub2a5\ud55c \uc77d\uae30 \uc790\ub8cc\ub97c \ucda9\ubd84\ud788 \uc81c\uacf5\ud558\ub294 \uc77c\uc740 \uad6c\ubd84\ud560 \uc218 \uc788\ub2e4. \ubcf8\ubb38 \uc124\uba85\ub3c4\ub294 \uc810\uc758 \uc704\uce58\ub97c \uc2dc\uac01\uc801\uc73c\ub85c \ube44\uad50\ud558\ub3c4\ub85d \ub9cc\ub4e0 \uadf8\ub9bc\uc774\ub2e4. \uc2e4\uc81c\ub85c \ub3cc\ucd9c\ub41c \uc810\uc744 \uc190\uc73c\ub85c \uc77d\ub294 \uacbd\ud5d8\uc744 \uadf8\ub300\ub85c \uc7ac\ud604\ud558\uc9c0 \uc54a\ub294\ub2e4. \ud3c9\ud3c9\ud55c \ud654\uba74\uc5d0\uc11c \ubaa8\uc591\uc744 \uc54c\uc544\ubcf4\ub294 \uac83\uacfc \uc190\ub05d\uc73c\ub85c \ud45c\uae30\ub97c \ubc30\uc6b0\ub294 \uc77c\uc5d0\ub294 \ub2e4\ub978 \uc870\uac74\uc774 \uc788\ub2e4. \uc548\ub0b4 \uadf8\ub9bc\uc744 \ubcf4\uc558\ub2e4\uace0 \uc77d\ub294 \uc18d\ub3c4\uc640 \uc219\ub828\uae4c\uc9c0 \uc774\ud574\ud588\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uadf8\ub7fc\uc5d0\ub3c4 \uad6c\uc870\ub97c \uc544\ub294 \uc77c\uc740 \uc77c\uc0c1\uc5d0\uc11c \uc810\uc790\ub97c \ubcfc \ub54c \ubb34\uc2ec\ud788 \uc9c0\ub098\uce58\uc9c0 \uc54a\uac8c \ud55c\ub2e4. \uba87 \uac1c\uc758 \uc7a5\uc2dd\uc801\uc778 \uc810\uc774 \uc544\ub2c8\ub77c \uc704\uce58\uc640 \uc21c\uc11c\ub97c \uac00\uc9c4 \ubb38\uc790\ub77c\ub294 \uc0ac\uc2e4\uc774 \ubcf4\uc778\ub2e4. \ud615\ud0dc\ub97c \uc138\ub294 \uacc4\uc0b0\uc5d0\uc11c \uc2dc\uc791\ud574 \ub2e4\uc591\ud55c \uc5b8\uc5b4\uc640 \uc77d\uae30\uc758 \ubc29\uc2dd\uc744 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \uc5ec\uc12f \uc790\ub9ac\uc758 \uc791\uc740 \uacf5\uac04\uc740 \uc815\ubcf4\uc758 \uac1c\uc218\uc640 \uc758\ubbf8\uc758 \ubc94\uc704\uac00 \uc5b4\ub5bb\uac8c \ub2e4\ub978\uc9c0 \uc54c\ub824 \uc900\ub2e4. \uc5ec\uae30\uc11c\ub294 6\uc810 \uccb4\uacc4\uc758 \uc77c\ubd80 \uc608\ub97c \ubcf4\uace0 \uc788\ub2e4. \ubaa8\ub4e0 \uc5b8\uc5b4\uc640 \ubaa8\ub4e0 \uc810\uc790 \ubc29\uc2dd\uc774 \ud55c \uce78\uc744 \ub611\uac19\uc774 \ud574\uc11d\ud55c\ub2e4\uace0 \uc0dd\uac01\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc791\uc740 \uc608\ub97c \uc804\uccb4 \uaddc\uce59\uc73c\ub85c \ub113\ud788\uc9c0 \uc54a\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4. \uadf8\ub798\ub3c4 \uc5ec\uc12f \uc790\ub9ac\ub97c \ub2e4\uc2dc \ubcf4\uba74 \ucc98\uc74c\uacfc\ub294 \uc870\uae08 \ub2e4\ub974\uac8c \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \ub2e8\uc21c\ud788 \uc810\uc744 \ub354\ud558\uac70\ub098 \ube7c\ub294 \uc77c\uc774 \uc544\ub2c8\ub77c, \uc815\ud574\uc9c4 \uc704\uce58\ub97c \uc870\ud569\ud574 \uc77d\uc744 \uc218 \uc788\ub294 \ucc28\uc774\ub97c \ub9cc\ub4dc\ub294 \uc77c\uc774\ub2e4. \uc791\uc740 \uce78 \uc548\uc5d0\ub3c4 \uaf64 \ub113\uc740 \uac00\ub2a5\uc131\uc774 \ub4e4\uc5b4 \uc788\ub2e4."}, {"id": "darwin-life-of-observation", "title": "\ub2e4\uc708\uc758 \uc0dd\uc560 \u2014 \ud55c \ubc88\uc758 \uc5ec\ud589\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\uc740 \ubc1c\uacac", "summary": "\ub2e4\uc708\uc758 \uc790\uc11c\uc804\uc744 \ubc14\ud0d5\uc73c\ub85c \ubc30\uc6c0\uc758 \uc6b0\ud68c\uc640 \ube44\uae00\ud638 \ud56d\ud574, \uae34 \uc5f0\uad6c\uc640 \uc6d4\ub9ac\uc2a4\uc758 \uc5ed\ud560\uc744 \ud568\uaed8 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "science", "category_title": "Science", "subcategory": "Biology", "url": "stories/darwin-life-of-observation/index.html", "image": "media/darwin-life-of-observation.png", "alt": "\uc870\uac1c\uc640 \uc2dd\ubb3c \ud45c\ubcf8, \uc218\ucca9\uc774 \ub193\uc778 \ucc45\uc0c1\uc5d0\uc11c \ub3cb\ubcf4\uae30\ub85c \ud45c\ubcf8\uc744 \uc0b4\ud53c\ub294 19\uc138\uae30 \uc5f0\uad6c\uc790\uc758 \ub4b7\ubaa8\uc2b5.", "text": "\ub2e4\uc708\uc758 \uc0dd\uc560 \u2014 \ud55c \ubc88\uc758 \uc5ec\ud589\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\uc740 \ubc1c\uacac \uc218\uc9d1\uacfc \uc9c8\ubb38, \uc624\ub798\ub41c \uae30\ub85d\uc774 \ucc45\uc774 \ub418\uae30\uae4c\uc9c0 \ub2e4\uc708\uc758 \uc790\uc11c\uc804\uc744 \ubc14\ud0d5\uc73c\ub85c \ubc30\uc6c0\uc758 \uc6b0\ud68c\uc640 \ube44\uae00\ud638 \ud56d\ud574, \uae34 \uc5f0\uad6c\uc640 \uc6d4\ub9ac\uc2a4\uc758 \uc5ed\ud560\uc744 \ud568\uaed8 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Biology \uacfc\ud559 \ub2e4\uc708\uc740 \uac08\ub77c\ud30c\uace0\uc2a4\uc5d0\uc11c \uc0c8\ub97c \ud55c \ubc88 \ubcf4\uace0 \uc9c4\ud654\ub97c \ub2e8\ubc88\uc5d0 \uc54c\uc544\ub0b8 \uc0ac\ub78c\uc77c\uae4c. \uadf8\uc758 \uc790\uc11c\uc804\uc744 \uc77d\uc73c\uba74 \ud6e8\uc52c \ub290\ub9ac\uace0 \ubcf5\uc7a1\ud55c \uc2dc\uac04\uc774 \ub098\uc628\ub2e4. \uc5b4\ub9b0 \uc2dc\uc808\uc758 \uc218\uc9d1, \uc9c4\ub85c\uc758 \uc6b0\ud68c, \uae34 \ud56d\ud574\uc640 \ub3cc\uc544\uc628 \ub4a4\uc758 \uc791\uc5c5\uc774 \uc774\uc5b4\uc9c4\ub2e4. \uc5ec\ud589\uc5d0\uc11c \ub9cc\ub09c \uac83\uc740 \uc644\uc131\ub41c \uc815\ub2f5\ubcf4\ub2e4 \uc624\ub798 \ub2e4\ub8f0 \uc9c8\ubb38\ub4e4\uc774\uc5c8\ub2e4. \uc5ec\uae30\uc11c \uc77d\uc740 \ud310\ubcf8\uc740 \ub2e4\uc708\uc758 \ud68c\uace0\uc5d0 \uc544\ub4e4 \ud504\ub79c\uc2dc\uc2a4\uc758 \ud3b8\uc9d1 \uc124\uba85\uc774 \ubd99\uc740 \uc790\ub8cc\ub2e4. \ud3b8\uc9d1\uc790\ub294 \uc77c\ubd80 \uc0dd\ub7b5\uc774 \uc788\uc74c\uc744 \ubc1d\ud78c\ub2e4. \uc0dd\uc560\uc758 \ubaa8\ub4e0 \uc7a5\uba74\uc744 \ube60\uc9d0\uc5c6\uc774 \uae30\ub85d\ud55c \uac1d\uad00\uc801 \uc5f0\ub300\uae30\ub77c\uae30\ubcf4\ub2e4, \ud6d7\ub0a0\uc758 \ub2e4\uc708\uc774 \uc790\uae30 \uc0dd\uac01\uc758 \ubc1c\ub2ec\uc744 \uc5b4\ub5bb\uac8c \ub3cc\uc544\ubcf4\uc558\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\ub294 \uc6d0\uc804\uc73c\ub85c \uc77d\uc790. \ucc30\uc2a4 \ub2e4\uc708\uc740 1809\ub144 \uc601\uad6d \uc288\ub8e8\uc988\ubc84\ub9ac\uc5d0\uc11c \ud0dc\uc5b4\ub0ac\ub2e4. \uc790\uc11c\uc804\uc5d0\uc11c\ub294 \uc5b4\ub9b0 \uc2dc\uc808\ubd80\ud130 \uc790\uc5f0\ubb3c\uc744 \ubaa8\uc73c\uace0 \uc774\ub984\uc744 \uc54c\uc544\ubcf4\ub824 \ud588\ub2e4\uace0 \ub3cc\uc544\ubcf8\ub2e4. \ub098\uc911\uc758 \ud070 \uc774\ub860\uc744 \uc774\ubbf8 \ud488\uc740 \ucc9c\uc7ac\uc758 \ubaa8\uc2b5\ub9cc \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubb34\uc5c7\uc774\ub4e0 \uc218\uc9d1\ud558\uace0 \uad6c\ubd84\ud558\ub294 \ud765\ubbf8\uac00 \uba3c\uc800 \ubcf4\uc778\ub2e4. \uc218\uc9d1\uc740 \ube44\uc2b7\ud55c \uac83 \uc0ac\uc774\uc758 \ucc28\uc774\ub97c \ubcf4\uac8c \ub9cc\ub4e0\ub2e4. \ucc98\uc74c\uc5d0\ub294 \ud558\ub098\ub97c \ub354 \uc5bb\ub294 \uc990\uac70\uc6c0\uc774\uc5c8\uc5b4\ub3c4 \uc65c \ub2e4\ub978\uc9c0, \ubb34\uc5c7\uacfc \uac00\uae4c\uc6b4\uc9c0 \ubb3b\uac8c \ub420 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ubaa8\ub4e0 \ucde8\ubbf8\uac00 \ubc18\ub4dc\uc2dc \uc704\ub300\ud55c \ubc1c\uacac\uc73c\ub85c \uc774\uc5b4\uc9c4\ub2e4\ub294 \uc131\uacf5 \uacf5\uc2dd\uc73c\ub85c \ubc14\uafb8\uc5b4 \uc77d\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc774 \uc0dd\uc560\uc5d0\uc11c \uc5b4\ub5a4 \uad00\uc2ec\uc774 \uacc4\uc18d\ub418\uc5c8\ub294\uc9c0 \uc0b4\ud53c\uba74 \ub41c\ub2e4. \ub2e4\uc708\uc740 \uc5d0\ub4e0\ubc84\ub7ec\uc5d0\uc11c \uc758\ud559\uc744 \uacf5\ubd80\ud588\uc9c0\ub9cc \uadf8 \uae38\uc744 \uacc4\uc18d \uac00\uc9c0 \uc54a\uc558\ub2e4. \uc790\uc11c\uc804\uc5d0\ub294 \uac15\uc758\uc5d0 \ub300\ud55c \uc778\uc0c1\uacfc \uc218\uc220 \uc7a5\uba74\uc744 \uacac\ub514\uae30 \uc5b4\ub824\uc6cc\ud588\ub358 \uae30\uc5b5\uc774 \ub098\uc628\ub2e4. \uc774\ud6c4 \ucf00\uc784\ube0c\ub9ac\uc9c0\uc5d0\uc11c\ub294 \uc131\uc9c1\uc790\uac00 \ub418\ub294 \uae38\uc744 \uc5fc\ub450\uc5d0 \ub450\uace0 \uacf5\ubd80\ud588\ub2e4. \ud6d7\ub0a0\uc758 \uba85\uc131\ub9cc \ubcf4\uba74 \ucc98\uc74c\ubd80\ud130 \uc0dd\ubb3c\ud559\uc790\uac00 \ub420 \uacc4\ud68d\uc774 \ubd84\uba85\ud588\uc744 \uac83 \uac19\uc9c0\ub9cc \uadf8\ub807\uc9c0 \uc54a\uc558\ub2e4. \uc9c4\ub85c\uac00 \ud754\ub4e4\ub9ac\ub294 \ub3d9\uc548\uc5d0\ub3c4 \uc790\uc5f0\uc5d0 \ub300\ud55c \uad00\uc2ec\uacfc \uc8fc\ubcc0 \uc0ac\ub78c\uc5d0\uac8c\uc11c \ubc30\uc6b0\ub294 \uacbd\ud5d8\uc740 \ub0a8\uc558\ub2e4. \uc5b4\ub5a4 \uad50\uc721\uc744 \uc2dc\uc791\ud588\ub2e4\uac00 \ub2e4\ub978 \ubc29\ud5a5\uc73c\ub85c \uac04 \uc77c\uc774 \uadf8 \uc774\uc804 \uc2dc\uac04\uc744 \uc804\ubd80 \ubb34\uc758\ubbf8\ud558\uac8c \ub9cc\ub4dc\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ucf00\uc784\ube0c\ub9ac\uc9c0\uc5d0\uc11c \uc2dd\ubb3c\ud559\uc790 \ud5e8\uc2ac\ub85c\uc640\uc758 \uad00\uacc4\ub294 \uc911\uc694\ud55c \uc5f0\uacb0\uc774 \ub418\uc5c8\ub2e4. \ub2e4\uc708\uc740 \uadf8\uc640 \uac77\uace0 \ub300\ud654\ud558\uba70 \ubc30\uc6e0\uace0, \uc9c0\uc9c8\ud559\uc744 \uc811\ud558\ub294 \uae30\ud68c\ub3c4 \uc5bb\uc5c8\ub2e4. \uc9c0\uc2dd\uc740 \ud63c\uc790 \ucc45\uc0c1\uc5d0\uc11c \uc313\ub294 \uac83\ub9cc\uc774 \uc544\ub2c8\ub77c \ub204\uac00 \ubb34\uc5c7\uc744 \ubcf4\ub77c\uace0 \uc54c\ub824 \uc8fc\ub294\uc9c0\uc640\ub3c4 \uad00\ub828\ub418\uc5b4 \uc788\uc5c8\ub2e4. \ube44\uae00\ud638 \ud56d\ud574\ub85c \uc774\uc5b4\uc9c0\ub294 \uae30\ud68c\ub3c4 \uc774\ub7f0 \uad00\uacc4 \uc18d\uc5d0\uc11c \uc5f4\ub838\ub2e4. \ud55c \uc0ac\ub78c\uc758 \uc6a9\uae30\ub9cc\uc73c\ub85c \uc138\uacc4\uc758 \ubb38\uc774 \uc800\uc808\ub85c \uc5f4\ub838\ub2e4\uace0 \uc124\uba85\ud558\uba74 \ubc30\uacbd\uc774 \uc0ac\ub77c\uc9c4\ub2e4. \uad00\uc2ec\uc744 \uc54c\uc544\ubcf8 \uc0ac\ub78c\uacfc \uc18c\uac1c, \ubc30\uc6b8 \uc218 \uc788\uc5c8\ub358 \uc870\uac74\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4. \uc0dd\uc560\ub97c \uc77d\uc744 \ub54c \uc8fc\ubcc0 \uc774\ub984\uc744 \uc9c0\ub098\uce58\uc9c0 \uc54a\uc744 \uc774\uc720\ub2e4. \ub2e4\uc708\uc758 \ud56d\ud574\ub294 1831\ub144\uc5d0 \uc2dc\uc791\ud574 1836\ub144\uc5d0 \ub05d\ub0ac\ub2e4. \uc5ec\ub7ec \uc9c0\uc5ed\uc5d0\uc11c \ub3d9\uc2dd\ubb3c\uacfc \uc9c0\ud615, \ud654\uc11d\uc744 \ubcf4\uace0 \uc790\ub8cc\ub97c \ubaa8\uc558\ub2e4. \uc790\uc5f0\uc740 \ud55c \uac00\uc9c0 \ubaa8\uc2b5\uc73c\ub85c \uc815\uc9c0\ud574 \uc788\uc9c0 \uc54a\uc558\uace0, \uc11c\ub85c \ub2e4\ub978 \uc9c0\uc5ed\uc758 \uc0dd\ubb3c\uc740 \ub2ee\uc73c\uba74\uc11c\ub3c4 \ub2ec\ub790\ub2e4. \ub3cc\uc544\uc640 \ube44\uad50\ud560 \ub300\uc0c1\uc774 \uacc4\uc18d \ub298\uc5b4\ub0ac\ub2e4. \ud56d\ud574 \uc911\uc758 \uc21c\uac04 \ud558\ub098\uc5d0 \ubaa8\ub4e0 \uc124\uba85\uc774 \uc644\uc131\ub418\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud558\uc9c0 \ub9d0\uc790. \ucc44\uc9d1\ud55c \uc790\ub8cc\ub97c \ubd84\ub958\ud558\uace0 \ub2e4\ub978 \uc5f0\uad6c\uc790\uc640 \ud655\uc778\ud558\uba70 \ud574\uc11d\ud558\ub294 \uacfc\uc815\uc774 \ud544\uc694\ud588\ub2e4. \uae38 \uc704\uc5d0\uc11c\uc758 \uacbd\ud5d8\uacfc \ub098\uc911\uc758 \uc815\ub9ac\ub294 \ud55c \uc791\uc5c5\uc758 \uc11c\ub85c \ub2e4\ub978 \ubd80\ubd84\uc774\ub2e4. \ubc1c\uacac\uc758 \uc0ac\uc9c4 \ud55c \uc7a5\uc73c\ub85c \uae34 \uc5f0\uad6c\uc758 \uc2dc\uac04\uc744 \ub300\uc2e0\ud558\uae30 \uc5b4\ub835\ub2e4. \uc601\uad6d\uc73c\ub85c \ub3cc\uc544\uc628 \ub2e4\uc708\uc740 \uad00\ucc30\uacfc \ub3c5\uc11c, \uc9d1\ud544\uc744 \uc774\uc5b4 \uac14\ub2e4. \uac00\ucd95\uacfc \uc7ac\ubc30 \uc2dd\ubb3c\uc758 \ucc28\uc774, \uc0ac\ub78c\ub4e4\uc774 \uc6d0\ud558\ub294 \ud2b9\uc131\uc744 \ub0a8\uae30\ub294 \ubc29\uc2dd\ub3c4 \uc0dd\uac01\uc758 \uc7ac\ub8cc\uac00 \ub418\uc5c8\ub2e4. \uc790\uc11c\uc804\uc5d0\uc11c\ub294 1838\ub144 \ub9ec\uc11c\uc2a4\uc758 \uc778\uad6c\ub860\uc744 \uc77d\uc740 \uacbd\ud5d8\uc744 \uc790\uc2e0\uc758 \uad6c\uc0c1\uacfc \uc5f0\uacb0\ud574 \uc124\uba85\ud55c\ub2e4. \uac1c\uccb4 \uc0ac\uc774\uc758 \ucc28\uc774\uc640 \uc0dd\uc874\u00b7\ubc88\uc2dd\uc758 \uc870\uac74\uc744 \uc5b4\ub5bb\uac8c \ud568\uaed8 \uc0dd\uac01\ud560 \uac83\uc778\uac00\uac00 \uc911\uc694\ud574\uc84c\ub2e4. \uc790\uc5f0\uc120\ud0dd\uc740 \uc0dd\ubb3c\uc774 \uc758\uc2dd\uc801\uc73c\ub85c \uc6d0\ud558\ub294 \ubaa8\uc2b5\uc73c\ub85c \ubcc0\uc2e0\ud55c\ub2e4\ub294 \uc124\uba85\uc774 \uc544\ub2c8\ub2e4. \uc774 \uae00\uc740 \ud604\ub300 \uc9c4\ud654\uc0dd\ubb3c\ud559 \uc804\uccb4\ub97c \uc694\uc57d\ud558\uc9c0\ub294 \uc54a\uc9c0\ub9cc, \ud55c \uc5ec\ud589\uc5d0\uc11c \ubcf8 \uc0c8\uc758 \ubaa8\uc2b5\ub9cc\uc73c\ub85c \uc774\ub860\uc774 \ub9cc\ub4e4\uc5b4\uc84c\ub2e4\ub294 \uadf8\ub9bc\uc740 \ud53c\ud558\ub824 \ud55c\ub2e4. \ub2e4\uc708\uc740 \uc790\uc2e0\uc758 \uc0dd\uac01\uc744 \uc815\ub9ac\ud574 \ub450\uace0 \uc624\ub7ab\ub3d9\uc548 \uc790\ub8cc\ub97c \ubcf4\uc644\ud588\ub2e4. \uadf8\ub7ec\ub358 1858\ub144 \uc568\ud504\ub9ac\ub4dc \ub7ec\uc140 \uc6d4\ub9ac\uc2a4\uac00 \ubcf4\ub0b8 \uae00\uc744 \ubc1b\ub294\ub2e4. \ub2e4\uc708\uc740 \uadf8 \uc548\uc5d0 \uc790\uae30 \uad6c\uc0c1\uacfc \uac00\uae4c\uc6b4 \uc124\uba85\uc774 \uc788\uc74c\uc744 \uc54c\uc544\ubcf4\uc558\ub2e4. \ubc1c\uacac\uc758 \uc5ed\uc0ac\ub294 \ud63c\uc790\ub9cc\uc758 \uc11c\ub78d \uc548\uc5d0\uc11c \uc9c4\ud589\ub418\uc9c0 \uc54a\uc558\ub2e4. \uc774\ud6c4 \ub450 \uc0ac\ub78c\uc758 \uc790\ub8cc\uac00 \ud568\uaed8 \ubc1c\ud45c\ub418\uc5c8\ub2e4. \uc6d4\ub9ac\uc2a4\ub97c \ub2e4\uc708\uc758 \uc131\uacf5\uc744 \uc7ac\ucd09\ud55c \uc870\uc5f0\uc73c\ub85c\ub9cc \ubcf4\ub294 \uac83\uc740 \ucda9\ubd84\ud558\uc9c0 \uc54a\ub2e4. \uac19\uc740 \uc911\uc694\ud55c \ubb38\uc81c\uc5d0 \ub3c5\ub9bd\uc801\uc73c\ub85c \uc811\uadfc\ud55c \uc5f0\uad6c\uc790\uac00 \uc788\uc5c8\ub2e4\ub294 \uc810\uc774 \ud575\uc2ec\uc774\ub2e4. \uc790\uc11c\uc804 \uc790\uccb4\ub3c4 \uc6d4\ub9ac\uc2a4\uc758 \uc124\uba85\uc744 \ub192\uc774 \ud3c9\uac00\ud55c\ub2e4. \uc5f0\uad6c\uc758 \uc6b0\uc120\uad8c\uacfc \uae30\uc5ec\ub97c \ud568\uaed8 \uc0dd\uac01\ud558\uac8c \ud558\ub294 \uc7a5\uba74\uc774\ub2e4. 1859\ub144 \u300e\uc885\uc758 \uae30\uc6d0\u300f\uc774 \ucd9c\ud310\ub418\uc5c8\ub2e4. \uc624\ub7ab\ub3d9\uc548 \ubaa8\uc740 \uc0dd\uac01\uacfc \uc790\ub8cc\uac00 \ub3c5\uc790\uc640 \ub2e4\ub978 \uc5f0\uad6c\uc790 \uc55e\uc5d0 \ub193\uc774\ub294 \uc21c\uac04\uc774\uc5c8\ub2e4. \ub2e4\uc708\uc740 \uc774\ud6c4 \ud310\ubcf8\uc744 \uace0\uce58\uace0 \ub2e4\ub978 \uc791\uc5c5\ub3c4 \uc774\uc5b4 \uac14\ub2e4. \ucc45 \ud55c \uad8c\uc774 \ub098\uc654\ub2e4\uace0 \uc0dd\ubb3c\uc5d0 \ub300\ud55c \uc9c8\ubb38\uc774 \ubaa8\ub450 \ub2eb\ud78c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ub298\uc758 \uc0dd\ubb3c\ud559\uc740 \uadf8 \ub4a4\uc758 \uc5f0\uad6c\uc640 \uc720\uc804\ud559 \ub4f1 \ub9ce\uc740 \uc9c0\uc2dd\uc73c\ub85c \ub354 \ubc1c\uc804\ud588\ub2e4. \ub2e4\uc708\uc774 \ud604\uc7ac\uc758 \ubaa8\ub4e0 \ub0b4\uc6a9\uc744 \uc774\ubbf8 \uc54c\uc558\ub2e4\uace0 \uce6d\ucc2c\ud560 \ud544\uc694\ub3c4, \uc774\ud6c4\uc5d0 \ubcf4\uc644\uc774 \uc788\uc5c8\ub2e4\ub294 \uc774\uc720\ub85c \uadf8\uc758 \uc9c8\ubb38\uc744 \uc791\uac8c \ub9cc\ub4e4 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \uc5b4\ub290 \uc2dc\ub300\uc5d0 \ubb34\uc5c7\uc744 \uc124\uba85\ud558\uace0 \ubb34\uc5c7\uc744 \uc544\uc9c1 \ubab0\ub790\ub294\uc9c0 \ub098\ub204\uc5b4 \ubcf4\ub294 \uac83\uc774 \uc815\ud655\ud558\ub2e4. \ub2e4\uc708\uc758 \ud68c\uace0\uc5d0\uc11c \ub0a8\ub294 \uac83\uc740 \ubc88\ub729\uc784\ubfd0 \uc544\ub2c8\ub77c \ubaa8\uc73c\uace0 \ube44\uad50\ud558\uba70 \ub2e4\uc2dc \uc4f0\ub294 \uc2dc\uac04\uc774\ub2e4. \ub3cc\uc544\ubcf8 \uae30\uc5b5\uc5d0\ub294 \uc800\uc790\uc758 \uc2dc\uc120\uacfc \ud3b8\uc9d1\uc758 \ud55c\uacc4\ub3c4 \uc788\uc9c0\ub9cc, \uc21c\uc2dd\uac04\uc758 \ubc1c\uacac\ub2f4\ubcf4\ub2e4 \uc5f0\uad6c\uc758 \uc5ec\ub7ec \ub2e8\uacc4\ub97c \ubcf4\uc5ec \uc900\ub2e4. \uad00\ucc30\uacfc \ud574\uc11d \uc0ac\uc774\uc5d0 \uc5bc\ub9c8\ub098 \ub9ce\uc740 \uc77c\uc774 \ub4e4\uc5b4\uac00\ub294\uc9c0 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uadf8\ub9bc\uc740 \uc790\uc5f0\ubb3c\uc744 \uc0b4\ud53c\ub294 19\uc138\uae30 \uc5f0\uad6c\uc790\uc758 \ubd84\uc704\uae30\ub97c \uc0c1\uc0c1\ud55c AI \uc0bd\ud654\ub2e4. \ub2e4\uc708\uc758 \uc2e4\uc81c \uc5bc\uad74\uacfc \ubc29\uc744 \ubcf5\uc6d0\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \ucc45\uc0c1 \uc704\uc758 \uc791\uc740 \ud45c\ubcf8\uc744 \uc785\uad6c\ub85c \uc0bc\uc544 \uc5ec\ud589 \ub4a4\uc5d0\ub3c4 \ub05d\ub098\uc9c0 \uc54a\uc558\ub358 \uc9c8\ubb38\uc758 \uc2dc\uac04\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790."}, {"id": "discovery-panel-labels", "title": "\uc6b0\uc8fc\uc120 \uc548\uc5d0\ub3c4 \uc791\uc740 \uc774\ub984\ud45c\uac00 \uac00\ub4dd\ud558\ub2e4", "summary": "\uc6b0\uc8fc\uc120 \ud328\ub110\uc758 \uc2e4\uc81c \uc0ac\uc9c4\uc5d0\uc11c \ubc18\ubcf5\ub418\ub294 \ubaa8\uc591\uacfc \ud45c\uc2dc\ub97c \ucc3e\uc544\ubd05\ub2c8\ub2e4.", "category": "science", "category_title": "Science", "subcategory": "Engineering", "url": "stories/discovery-panel-labels/index.html", "image": "media/discovery-panel-labels.jpg", "alt": "NASA\uc758 \ub514\uc2a4\ucee4\ubc84\ub9ac\ud638 \ube44\ud589 \uac11\ud310 \ud328\ub110 \uc2e4\uc81c \uc0ac\uc9c4. \uc6d0\ud615 \ubd80\ubd84\uacfc \uc0c9 \ud14c\ub450\ub9ac, \uc791\uc740 \ud45c\uc2dc\ub4e4\uc774 \ubc18\ubcf5\ub429\ub2c8\ub2e4.", "text": "\uc6b0\uc8fc\uc120 \uc548\uc5d0\ub3c4 \uc791\uc740 \uc774\ub984\ud45c\uac00 \uac00\ub4dd\ud558\ub2e4 \ub514\uc2a4\ucee4\ubc84\ub9ac\ud638 \ud328\ub110\uc744 \uac00\uae4c\uc774 \ubcf4\uae30 \uc6b0\uc8fc\uc120 \ud328\ub110\uc758 \uc2e4\uc81c \uc0ac\uc9c4\uc5d0\uc11c \ubc18\ubcf5\ub418\ub294 \ubaa8\uc591\uacfc \ud45c\uc2dc\ub97c \ucc3e\uc544\ubd05\ub2c8\ub2e4. Engineering \uacfc\ud559 \uc6b0\uc8fc\uc120 \ub0b4\ubd80\ub97c \uc0c1\uc0c1\ud558\uba74 \uac70\ub300\ud55c \ud654\uba74\uc774\ub098 \uba4b\uc9c4 \uc870\uc885\uc11d\ubd80\ud130 \ub5a0\uc624\ub978\ub2e4. \uadf8\ub7f0\ub370 NASA\uac00 \uacf5\uac1c\ud55c \ub514\uc2a4\ucee4\ubc84\ub9ac\ud638 \ube44\ud589 \uac11\ud310 \ud328\ub110 \uc0ac\uc9c4\uc744 \uac00\uae4c\uc774 \ubcf4\uba74, \ub465\uadfc \ubd80\ubd84\ub4e4\uc774 \uc904\uc9c0\uc5b4 \uc788\uace0 \uadf8 \uacc1\uc5d0\ub294 \uc791\uc740 \uae00\uc790\uc640 \ud45c\uc2dc\uac00 \ubd99\uc5b4 \uc788\ub2e4. \uc804\uccb4 \uc6b0\uc8fc\uc120\uc744 \ubcf4\uc5ec \uc8fc\ub294 \ud48d\uacbd\uc774 \uc544\ub2c8\ub2e4. \uc881\uc740 \ud55c \ubd80\ubd84\uc744 \ubaa8\ud615 \uc81c\uc791 \ub4f1\uc5d0 \uc4f8 \uc218 \uc788\ub3c4\ub85d \uacf5\uac1c\ud55c \uc2e4\uc81c \ud328\ub110 \uc790\ub8cc\ub2e4. \ub113\uc740 \uc6b0\uc8fc\ubcf4\ub2e4 \uba3c\uc800 \uc190\uc774 \ub2ff\uc744 \ub9cc\ud55c \uac70\ub9ac\uc758 \ubb3c\uac74\uc744 \ubcf4\uac8c \ub41c\ub2e4. \uc0ac\uc9c4 \uc18d\uc5d0\ub294 \uc11c\ub85c \ub2ee\uc740 \ub465\uadfc \ubd80\ubd84\uc774 \ubc18\ubcf5\ub41c\ub2e4. \uba87\uba87 \ubd80\ubd84\uc5d0\ub294 \ub178\ub780 \ud14c\ub450\ub9ac\uac00 \uc788\uace0, \uc8fc\ubcc0\uc5d0\ub294 \uc5b4\ub450\uc6b4 \uc0c9\uacfc \ubd89\uc740\uc0c9\uc774 \ud568\uaed8 \uc4f0\uc600\ub2e4. \uba40\ub9ac\uc11c \ubcf4\uba74 \ubcf5\uc7a1\ud55c \ubb34\ub2ac \uac19\uc9c0\ub9cc \uac00\uae4c\uc774\uc5d0\uc11c\ub294 \uc791\uc740 \ucc28\uc774\ub4e4\uc774 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uc6b0\ub9ac\uc758 \ucc45\uc0c1\uc5d0\uc11c\ub3c4 \ube44\uc2b7\ud55c \uc77c\uc774 \uc0dd\uae34\ub2e4. \ucf00\uc774\ube14\uc774\ub098 \uc11c\ub78d, \uc5f4\uc1e0\uac00 \uc5ec\ub7ec \uac1c\uba74 \uc774\ub984\ud45c\ub098 \uc0c9\uae54\ub85c \uad6c\ubcc4\ud55c\ub2e4. \uc6b0\uc8fc\uc120\uc758 \uc815\ud655\ud55c \uc791\uc5c5 \uc808\ucc28\ub97c \ubaa8\ub974\ub354\ub77c\ub3c4, \ube44\uc2b7\ud55c \uac83\ub4e4\uc744 \ud5f7\uac08\ub9ac\uc9c0 \uc54a\uac8c \ud45c\uc2dc\ud558\ub294 \ud544\uc694\ub294 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uc774 \uc0ac\uc9c4\uc5d0\uc11c \uac01\uac01\uc774 \ubb34\uc2a8 \uae30\ub2a5\uc744 \ud558\ub294\uc9c0\uae4c\uc9c0 \ubaa8\ub450 \uc77d\uc5b4 \ub0b4\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub465\uae00\ub2e4\uace0 \uc804\ubd80 \uac19\uc740 \uc2a4\uc704\uce58\ub77c\uace0 \ubd80\ub974\uac70\ub098 \uc0c9\uae54\ub9c8\ub2e4 \ud2b9\uc815 \uae30\ub2a5\uc774 \uc788\ub2e4\uace0 \uc815\ud558\uba74 \uc2e4\uc81c \uc790\ub8cc\ub97c \ub118\uc5b4\uc120 \uc124\uba85\uc774 \ub41c\ub2e4. \ub300\uc2e0 \uac19\uc740 \ubaa8\uc591\uc774 \ubc18\ubcf5\ub418\ub294 \ubc29\uc2dd\uacfc \uadf8 \uc606\uc758 \ud45c\uc2dc\ub97c \ucc28\ub840\ub85c \uc0b4\ud3b4\ubcf4\uc790. \ubcf5\uc7a1\ud55c \uae30\uacc4\uc758 \ud45c\uba74\uc744 \uadf8\ub0e5 \ubcf5\uc7a1\ud558\ub2e4\uace0\ub9cc \ub290\ub07c\ub294 \uac83\uacfc, \uc5b4\ub5a4 \uad6c\ubd84\uc774 \ub9c8\ub828\ub418\uc5b4 \uc788\ub294\uc9c0 \ubcf4\ub294 \uac83\uc740 \uc870\uae08 \ub2e4\ub978 \uacbd\ud5d8\uc774\ub2e4. \ubcf5\uc7a1\ud55c \uc7a5\ube44\uac00 \uc788\uc5b4\ub3c4 \uc0ac\uc6a9\uc790\uac00 \ud544\uc694\ud55c \ubd80\ubd84\uc744 \uad6c\ubcc4\ud558\uae30 \uc5b4\ub824\uc6b0\uba74 \uc791\uc5c5\uc740 \ub354 \uae4c\ub2e4\ub85c\uc6cc\uc9c8 \uc218 \uc788\ub2e4. \ud328\ub110\uc758 \ud45c\uc2dc\ub97c \ubcf4\ub294 \uc77c\uc740 \uadf8\ub7f0 \uc0ac\ub78c\uacfc \uc7a5\uce58\uc758 \uad00\uacc4\ub97c \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ubaa8\uc591\uc774 \ubc18\ubcf5\ub418\ub294 \uac00\uc6b4\ub370 \uc791\uc740 \uc774\ub984\uacfc \uc0c9\uc758 \ucc28\uc774\uac00 \uc788\ub2e4. \uba40\ub9ac\uc11c \ud558\ub098\uc758 \ubcf5\uc7a1\ud55c \uba74\ucc98\ub7fc \ubcf4\uc774\ub294 \uac83\ub3c4 \uac00\uae4c\uc774\uc5d0\uc11c\ub294 \ub098\ub204\uc5b4 \uc77d\uc744 \uc790\ub9ac\uac00 \uc0dd\uae34\ub2e4. \uc774\uac83\uc740 \uc0ac\uc9c4 \uc18d \uac01 \ubd80\ud488\uc758 \uc2e4\uc81c \uc0ac\uc6a9 \uc808\ucc28\ub97c \ud655\uc778\ud55c \ub9d0\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub290 \uac83\uc774 \ubc84\ud2bc\uc774\uace0 \uc5b4\ub290 \uac83\uc774 \uc5f0\uacb0\uad6c\uc778\uc9c0, \ud2b9\uc815\ud55c \uc0c9\uc774 \ubb34\uc2a8 \ub73b\uc778\uc9c0\ub294 \ubcc4\ub3c4 \uae30\uc220 \uc790\ub8cc\uac00 \ud544\uc694\ud55c \ubb38\uc81c\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc9c1\uc811 \ubcf4\uc774\ub294 \ubc30\uc5f4\uacfc \ud45c\uae30\ub77c\ub294 \uc0ac\uc2e4\uc5d0\uc11c \ucd9c\ubc1c\ud55c\ub2e4. \ubaa8\ub974\ub294 \ubd80\ubd84\uc744 \uc804\ubd80 \ud558\ub098\uc758 \uc2a4\uc704\uce58\ub77c\uace0 \ubd80\ub974\uc9c0 \uc54a\uc73c\uba74 \uad00\ucc30\ub3c4 \ub354 \uc815\ud655\ud574\uc9c4\ub2e4. \uac19\uc740 \ubaa8\uc591\uc774 \ubc18\ubcf5\ub418\uba74 \uaddc\uce59\uc744 \ucc3e\uae30 \uc27d\uc9c0\ub9cc \uc11c\ub85c \ud5f7\uac08\ub9b4 \uc218\ub3c4 \uc788\ub2e4. \uadf8 \uc606\uc5d0 \uae00\uc790\uc640 \uc0c9, \uc704\uce58\uc758 \ucc28\uc774\ub97c \ub193\uc73c\uba74 \uc5b4\ub290 \ud56d\ubaa9\uc778\uc9c0 \ub354 \uc138\ubd84\ud574\uc11c \ubcfc \uc218 \uc788\ub2e4. \uc2e4\uc81c\ub85c \uc774 \ud328\ub110\uc774 \uc5b4\ub5a4 \uc124\uacc4 \uae30\uc900\uc744 \ub530\ub974\ub294\uc9c0 \ub2e8\uc815\ud558\uc9c0 \uc54a\ub354\ub77c\ub3c4, \ube44\uc2b7\ud55c \ubd80\ud488\uc744 \uad6c\ubcc4\ud558\ub294 \uc815\ubcf4\uac00 \uc65c \ud544\uc694\ud560\uc9c0\ub294 \uc774\ud574\ud560 \uc218 \uc788\ub2e4. \uc6b0\ub9ac \ucc45\uc0c1\uc758 \ucf00\uc774\ube14\uc774\ub098 \uc815\ub9ac\ud568\uc744 \ube44\uad50\ud55c \uac83\uc740 \uc774 \ud544\uc694\ub97c \uac00\uae4c\uc774 \ub290\ub07c\uac8c \ud558\ub294 \ube44\uc720\ub2e4. \uc6b0\uc8fc\uc120\uc758 \uc791\uc5c5\uc774 \uc9d1\uc758 \uc815\ub9ac\uc640 \uac19\uc740 \uc704\ud5d8\ub3c4\ub098 \uc808\ucc28\ub97c \uac00\uc9c4\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc775\uc219\ud55c \uc608\uc5d0\uc11c \uad6c\ubd84\uc758 \ud544\uc694\ub97c \ub5a0\uc62c\ub9b0 \ub4a4 \uc2e4\uc81c \uc0ac\uc9c4\uc758 \ubc94\uc704\ub85c \ub3cc\uc544\uc624\ub294 \uac83\uc774 \uc88b\ub2e4. \ube44\uc720\uac00 \uae30\uc220\uc758 \uc815\ud655\ud55c \ub0b4\uc6a9\uc744 \ub300\uc2e0\ud558\uc9c0 \uc54a\ub3c4\ub85d \ud558\ub294 \uac83\uc774\ub2e4. NASA \uc790\ub8cc\uba85\uacfc \uc0ac\uc9c4 \ubc88\ud638\ub294 \uc774\ubbf8\uc9c0 \uc790\uccb4\ub97c \ucc3e\uac8c \ud574 \uc8fc\ub294 \uae30\ub85d\uc774\ub2e4. \ud328\ub110 \uc704\uc758 \uc791\uc740 \uae00\uc740 \uc0ac\uc9c4 \uc548\uc5d0 \ucc0d\ud78c \ubb3c\uac74\uc758 \ud45c\uae30\ub2e4. \ud654\uba74\uc5d0\ub294 \ud568\uaed8 \ubcf4\uc774\uc9c0\ub9cc \uc11c\ub85c \ub2e4\ub978 \ub300\uc0c1\uc744 \uc2dd\ubcc4\ud55c\ub2e4. \uc790\ub8cc\uc758 \uc774\ub984\uc744 \uc77d\ub294 \uc77c\uacfc \ud328\ub110\uc758 \uae30\ub2a5\uc744 \ud574\uc11d\ud558\ub294 \uc77c\uc740 \uad6c\ubd84\ub418\uc5b4\uc57c \ud55c\ub2e4. \ud558\ub098\ub97c \uc548\ub2e4\uace0 \ub2e4\ub978 \ud558\ub098\uc758 \ub2f5\uc774 \uc790\ub3d9\uc73c\ub85c \ub098\uc624\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. Discovery Flight Deck Panels\ub77c\ub294 \uc774\ub984\uc740 \uc5b4\ub5a4 \ub9e5\ub77d\uc5d0\uc11c \uc0ac\uc9c4\uc744 \ub9cc\ub098\uc57c \ud558\ub294\uc9c0 \uc54c\ub824 \uc900\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \ub9d0\ub9cc\uc73c\ub85c \uac1c\ubcc4 \ubd80\ud488\uc758 \uae30\ub2a5\uacfc \uc0c1\ud0dc\ub97c \ubaa8\ub450 \uc54c \uc218\ub294 \uc5c6\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 \uc2e4\uc81c \uc774\ubbf8\uc9c0\uc5d0 \ub098\ud0c0\ub09c \uc6d0\ud615 \ubd80\ubd84\uacfc \ud14c\ub450\ub9ac, \ud45c\uae30\ub97c \uad00\ucc30\ud55c\ub2e4. \uc544\ub294 \uac83\uacfc \uc544\uc9c1 \uae30\uc220 \ubb38\uc11c\uac00 \ud544\uc694\ud55c \uac83\uc744 \ub098\ub204\uc5b4 \ub450\uba74 \uc0ac\uc9c4\uc774 \ub354 \uc88b\uc740 \uc9c8\ubb38\uc758 \ucd9c\ubc1c\uc810\uc774 \ub41c\ub2e4. \uc6b0\uc8fc\uc120\uc740 \uac70\ub300\ud55c \ub3d9\uccb4\uc640 \ubc1c\uc0ac\uc758 \ubd88\uaf43\uc73c\ub85c \uae30\uc5b5\ub418\uae30 \uc27d\ub2e4. \uc2e4\ub0b4\uc758 \ud328\ub110\uc740 \uadf8 \uc7a5\ube44\ub97c \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub5bb\uac8c \uc77d\uace0 \ub2e4\ub8e8\ub294\uc9c0\ub77c\ub294 \ub2e4\ub978 \ud06c\uae30\uc758 \uc774\uc57c\uae30\ub97c \ubcf4\uc5ec \uc900\ub2e4. \uae30\uacc4\ub97c \ub9cc\ub4dc\ub294 \uc77c\uc5d0\ub294 \uac15\ud55c \ucd94\uc9c4\ub825\ubfd0 \uc544\ub2c8\ub77c \ud544\uc694\ud55c \uac83\uc744 \uad6c\ubcc4\ud558\uac8c \ud558\ub294 \ud45c\uba74\ub3c4 \ud3ec\ud568\ub41c\ub2e4. \uc7a5\uce58\uc758 \ub2a5\ub825\uacfc \uc0ac\uc6a9\uc790\uc758 \ud589\ub3d9\uc740 \ub5a8\uc5b4\uc838 \uc788\uc9c0 \uc54a\ub2e4. \ub2e4\uc74c\uc5d0 \uc0ac\uc9c4\uc744 \ubcfc \ub54c\uc5d0\ub294 \uc804\uccb4\uc758 \ubcf5\uc7a1\ud568\uc744 \ud55c \ubc88 \ubcf4\uace0 \uc791\uc740 \ud45c\uae30\ub97c \ud558\ub098 \ucc3e\uc544\ubcf4\uc790. \ubb34\uc2a8 \uae30\ub2a5\uc778\uc9c0 \uc989\uc2dc \uc54c\uc544\ub9de\ud788\uae30\ubcf4\ub2e4 \uc5b4\ub5a4 \uad6c\ubd84\uc774 \ub208\uc5d0 \ubcf4\uc774\ub294\uc9c0 \uc0b4\ud53c\uba74 \ub41c\ub2e4. \uc791\ub3d9\ubc95\uc744 \ubc30\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \uc124\uacc4\uac00 \uc0ac\ub78c\uc5d0\uac8c \ub9d0\uc744 \uac74\ub124\ub294 \uc790\ub9ac\ub97c \ubcfc \uc218 \uc788\ub2e4. \uc6b0\uc8fc\uc120 \uc548\uc758 \uc791\uc740 \uc774\ub984\ud45c\ub4e4\uc740 \uba3c \ud0d0\uc0ac\ub97c \uc775\uc219\ud55c \uc77d\uae30\uc758 \ubb38\uc81c\uc640 \uc5f0\uacb0\ud574 \uc900\ub2e4. \uc774 \uae00\uc5d0\ub294 \ud328\ub110\uc744 \uc0c8\ub85c \uc0c1\uc0c1\ud55c \uc0bd\ud654 \ub300\uc2e0 NASA\uac00 \uc81c\uacf5\ud55c \uc2e4\uc81c \uc0ac\uc9c4\uc744 \ub123\uc5c8\ub2e4. \uad6c\uccb4\uc801\uc778 \uc0ac\ubb3c\uc774 \uc911\uc2ec\uc77c \ub54c \uc6d0\ub798 \uc790\ub8cc\uac00 \ubcf4\uc5ec \uc8fc\ub294 \uc791\uc740 \ucc28\uc774\ub4e4\uc774 \uc911\uc694\ud558\uae30 \ub54c\ubb38\uc774\ub2e4. \ud0d0\uc0ac \uc774\uc57c\uae30\ub294 \uc885\uc885 \ud070 \uc22b\uc790\uc640 \uba3c \uac70\ub9ac\ub85c \uae30\uc5b5\ub41c\ub2e4. \uadf8\ub7ec\ub098 \uc7a5\uce58\ub97c \uc0ac\uc6a9\ud558\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \uac00\uae4c\uc774 \ub193\uc778 \ud45c\uc2dc \ud558\ub098\ub3c4 \uc791\uc5c5\uc758 \uc77c\ubd80\uc600\uc744 \uac83\uc774\ub2e4. \uc774 \ud328\ub110 \uc0ac\uc9c4\uc740 \uac70\ub300\ud55c \uc6b0\uc8fc\uc120\uc5d0\ub3c4 \uc791\uac8c \uc77d\uc5b4\uc57c \ud560 \uc815\ubcf4\uac00 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc870\uc6a9\ud788 \ubcf4\uc5ec \uc900\ub2e4."}, {"id": "earth-map-for-globe", "title": "\uc9c0\uad6c\ubcf8\uc758 \ub465\uadfc \ubab8\uc5d0\ub294 \uc5b4\ub5a4 \uadf8\ub9bc\uc744 \uc785\ud790\uae4c", "summary": "\ub465\uadfc \uc9c0\uad6c\ub97c \ud45c\ud604\ud558\uae30 \uc704\ud574 \ub9c8\ub828\ub41c \ud3c9\ud3c9\ud55c \uc9c0\ub3c4 \uc790\ub8cc\ub97c \ub4e4\uc5ec\ub2e4\ubd05\ub2c8\ub2e4.", "category": "science", "category_title": "Science", "subcategory": "Earth-Science", "url": "stories/earth-map-for-globe/index.html", "image": "media/earth-map-for-globe.jpg", "alt": "NASA\uc758 Earth (A) \uc9c0\ub3c4 \ud14d\uc2a4\ucc98. \ub300\ub959\uacfc \ubc14\ub2e4\uac00 \uc9c1\uc0ac\uac01\ud615\uc73c\ub85c \ud3bc\uccd0\uc9c4 \uc790\ub8cc\uc774\uba70 \ub2e8\uc77c \ucd2c\uc601 \uc0ac\uc9c4\uc774 \uc544\ub2d9\ub2c8\ub2e4.", "text": "\uc9c0\uad6c\ubcf8\uc758 \ub465\uadfc \ubab8\uc5d0\ub294 \uc5b4\ub5a4 \uadf8\ub9bc\uc744 \uc785\ud790\uae4c NASA\uc758 \ub0a9\uc791\ud55c \uc9c0\uad6c \uc790\ub8cc\ub97c \ubcf4\ub294 \ubc29\ubc95 \ub465\uadfc \uc9c0\uad6c\ub97c \ud45c\ud604\ud558\uae30 \uc704\ud574 \ub9c8\ub828\ub41c \ud3c9\ud3c9\ud55c \uc9c0\ub3c4 \uc790\ub8cc\ub97c \ub4e4\uc5ec\ub2e4\ubd05\ub2c8\ub2e4. Earth-Science \uacfc\ud559 \uc0ac\uc9c4\uc744 \ubcf4\uba74 \uc9c0\uad6c\uac00 \ub465\uadfc \uacf5\uc774 \uc544\ub2c8\ub77c \uae38\ucb49\ud55c \uc9c1\uc0ac\uac01\ud615\uc73c\ub85c \ud3bc\uccd0\uc838 \uc788\ub2e4. \uc6b0\ub9ac\uac00 \uc544\ub294 \ub300\ub959\ub4e4\uc774 \ub098\ub780\ud788 \ub193\uc774\uace0, \ubc14\ub2e4\uc5d0\ub3c4 \ubc1d\uace0 \uc5b4\ub450\uc6b4 \ubb34\ub2ac\uac00 \uc774\uc5b4\uc9c4\ub2e4. NASA\uac00 \uacf5\uac1c\ud55c Earth (A)\ub77c\ub294 \uc9c0\uad6c \uc790\ub8cc\ub2e4. \uc774\uac83\uc740 \uc6b0\uc8fc\uc5d0\uc11c \uc9c0\uad6c \uc804\uccb4\ub97c \uc9c1\uc0ac\uac01\ud615\uc73c\ub85c \ud55c \ubc88\uc5d0 \ucc0d\uc5c8\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. NASA\ub294 \uc774 \ud30c\uc77c\uc744 \uc774\ubbf8\uc9c0\uc640 \ud14d\uc2a4\ucc98 \uc790\ub8cc \ubaa8\uc74c\uc5d0\uc11c \uc81c\uacf5\ud55c\ub2e4. \ub465\uadfc \ub300\uc0c1\uc744 \ud45c\ud604\ud560 \ub54c \uc4f8 \uc218 \uc788\ub3c4\ub85d \ud3bc\uccd0 \ub193\uc740 \uadf8\ub9bc\uc73c\ub85c \ubcf4\ub294 \ud3b8\uc774 \uc774\ud574\ud558\uae30 \uc27d\ub2e4. \ud14d\uc2a4\ucc98\ub77c\uace0 \ud558\uba74 \ucc9c\uc774\ub098 \uc885\uc774\uc758 \ucd09\uac10\ubd80\ud130 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \ub514\uc9c0\ud138 \ubaa8\ud615\uc5d0\uc11c\ub294 \ubb3c\uccb4\uc758 \uac89\ubaa8\uc2b5\uc744 \ub098\ud0c0\ub0b4\ub294 \uc774\ubbf8\uc9c0\ub3c4 \uadf8\ub807\uac8c \ubd80\ub978\ub2e4. \uacf5 \ubaa8\uc591\ub9cc \ub9cc\ub4e4\uc5b4 \ub193\ub294 \uac83\uacfc \uadf8 \uc704\uc5d0 \ub300\ub959\uacfc \ubc14\ub2e4\uc758 \ubaa8\uc2b5\uc744 \uc785\ud788\ub294 \uac83\uc740 \ub2e4\ub978 \uc77c\uc774\ub2e4. \ube48 \uc9c0\uad6c\ubcf8\uc5d0 \uc9c0\ub3c4\ub97c \ubd99\uc774\ub294 \ubaa8\uc2b5\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \ub465\uadfc \ud2c0\uacfc \ud45c\uba74\uc758 \uadf8\ub9bc\uc774 \ud569\uccd0\uc9c0\uba74 \ube44\ub85c\uc18c \uc6b0\ub9ac\uac00 \uc54c\uc544\ubcf4\ub294 \uc9c0\uad6c\uc758 \uc5bc\uad74\uc774 \ub41c\ub2e4. \uc774 \ube44\uc720\ub294 \uc790\ub8cc\uc758 \uc4f0\uc784\uc744 \uc774\ud574\ud558\ub294 \ud55c \uac00\uc9c0 \ubc29\ubc95\uc774\ub2e4. \ud3bc\uccd0\uc9c4 \uc790\ub8cc\uc5d0\uc11c\ub294 \uc704\uc544\ub798 \uac00\uc7a5\uc790\ub9ac\uc758 \ubaa8\uc591\uc774 \ub0af\uc124\uac8c \ubcf4\uc77c \uc218 \uc788\ub2e4. \ud3c9\uba74\uc5d0 \ub193\uc778 \uc9c0\ub3c4\ub97c \ubcfc \ub54c\uc640 \ub465\uadfc \uc9c0\uad6c\ubcf8\uc744 \ubcfc \ub54c\uc758 \uc778\uc0c1\uc774 \ub298 \uac19\uc9c0\ub294 \uc54a\ub2e4. \uac19\uc740 \ub300\uc0c1\uc744 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \ud45c\ud604\ud558\uae30 \ub54c\ubb38\uc774\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 \ud2b9\uc815 \uc9c0\ub3c4 \ud22c\uc601\ubc95\uc758 \uc774\ub984\uc774\ub098 \uba74\uc801\uc758 \uc815\ud655\uc131\uc744 \uc774 \ud30c\uc77c\ub9cc \ubcf4\uace0 \ud655\uc815\ud558\uc9c0 \uc54a\ub294\ub2e4. \ub300\uc2e0 \uc2e4\uc81c \uc81c\uacf5\ub41c \uc774\ubbf8\uc9c0\uc5d0\uc11c \ub300\ub959\ub4e4\uc774 \uc5b4\ub514\uc5d0 \ub193\uc600\ub294\uc9c0 \ucc28\ub840\ub85c \ucc3e\uc544\ubcf4\ub294 \ub370 \uc9d1\uc911\ud574 \ubcf4\uc790. \uc775\uc219\ud55c \uc9c0\uad6c\uc5d0\ub3c4 \uc5ec\ub7ec \ud45c\ud604 \ubc29\uc2dd\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ubcf4\uc778\ub2e4. \uc544\ubb34 \ubb34\ub2ac \uc5c6\ub294 \uad6c\ub97c \ubcf4\uc558\uc744 \ub54c \uadf8\uac83\uc774 \uc9c0\uad6c\uc778\uc9c0 \ub2e4\ub978 \uacf5\uc778\uc9c0 \uc54c\uae30 \uc5b4\ub835\ub2e4. \ub300\ub959\uacfc \ubc14\ub2e4\uc758 \uc774\ubbf8\uc9c0\uac00 \ud45c\uba74\uc5d0 \ub193\uc774\uba74 \ube44\ub85c\uc18c \uc775\uc219\ud55c \ubaa8\uc2b5\uc774 \ub41c\ub2e4. 3\ucc28\uc6d0 \ubaa8\ud615\uc758 \ud615\ud0dc\uc640 \ud45c\uba74\uc744 \ud45c\ud604\ud558\ub294 \uc790\ub8cc\uac00 \uc11c\ub85c \ub2e4\ub978 \uc5ed\ud560\uc744 \ub9e1\ub294 \uac83\uc774\ub2e4. NASA\uac00 \ud14d\uc2a4\ucc98 \ud30c\uc77c\uc744 \ub530\ub85c \uc81c\uacf5\ud55c\ub2e4\ub294 \uc810\uc774 \uc774 \uad00\uacc4\ub97c \ubcf4\uc5ec \uc900\ub2e4. \uc774\uac83\uc740 \uc2e4\uc81c \uc9c0\uad6c\uac00 \ube48 \uacf5\uc5d0 \uadf8\ub9bc\uc744 \ubd99\uc5ec \ub9cc\ub4e0 \ubb3c\uac74\uc774\ub77c\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ub514\uc9c0\ud138 \ud45c\ud604\uc5d0\uc11c \ubb34\uc5c7\uc744 \ub530\ub85c \uc900\ube44\ud558\ub294\uc9c0 \uc774\ud574\ud558\uae30 \uc704\ud55c \uc124\uba85\uc774\ub2e4. \ubaa8\ud615\uacfc \uc9c0\ub3c4\ub97c \ud569\uce58\ub294 \uacfc\uc815\uc740 \ucef4\ud4e8\ud130 \uc548\uc758 \ud45c\ud604 \ubc29\ubc95\uc5d0 \uc18d\ud55c\ub2e4. \uc7ac\ub8cc\uc758 \uc774\ub984\uc744 \uc2e4\uc81c \ucc9c\uc758 \ucd09\uac10\uc73c\ub85c\ub9cc \uc77d\uc9c0 \uc54a\uace0 \uc0ac\uc6a9\ub418\ub294 \ubb38\ub9e5\uc5d0\uc11c \ubcf4\uba74 \ub0af\uc120 \ub2e8\uc5b4\ub3c4 \uad6c\uccb4\uc801\uc778 \uae30\ub2a5\uc744 \uc5bb\ub294\ub2e4. \ud3bc\uccd0 \ub193\uc740 \uc774\ubbf8\uc9c0\ub294 \uacbd\uacc4\ub97c \uac00\uc9c4 \uc9c1\uc0ac\uac01\ud615\uc774\ub2e4. \ub465\uadfc \ud45c\uba74\uc5d0\uc11c\ub294 \uadf8 \uc790\ub8cc\uac00 \uc5b4\ub5a4 \ubc29\ud5a5\uc73c\ub85c \ub300\uc751\ub418\ub294\uc9c0 \uc54c\uc544\uc57c \ud55c\ub2e4. \uc774\ubbf8\uc9c0\uc758 \uac00\uc7a5\uc790\ub9ac\uc640 \uadf9\uc9c0\ubc29\uc774 \ubaa8\ud615\uc5d0 \uc5b4\ub5bb\uac8c \ub193\uc774\ub294\uc9c0\uc5d0 \ub530\ub77c \ubcf4\uc774\ub294 \uacb0\uacfc\uac00 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ub2e8\uc21c\ud788 \uc544\ubb34 \uadf8\ub9bc\uc774\ub098 \uac19\uc740 \ube44\uc728\ub85c \uacf5\uc5d0 \ubd99\uc774\uba74 \ub41c\ub2e4\ub294 \uc124\uba85\uc73c\ub85c \ub05d\ub0bc \uc218\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \uc774 \uae00\uc5d0\uc11c\ub294 \ud30c\uc77c\ub9cc \ubcf4\uace0 \ud2b9\uc815\ud55c \uc9c0\ub3c4 \ud22c\uc601\ubc95\uc758 \ubaa8\ub4e0 \uc131\uc9c8\uc744 \ud655\uc815\ud558\uc9c0 \uc54a\ub294\ub2e4. \uba74\uc801\uacfc \uac70\ub9ac\uc758 \uc815\ud655\uc131\uc744 \uc0c8\ub85c \uce21\uc815\ud55c \uac83\ub3c4 \uc544\ub2c8\ub2e4. \uc2e4\uc81c \uc81c\uacf5\ub41c \uc774\ubbf8\uc9c0\uac00 \uc9c0\ub3c4 \ud14d\uc2a4\ucc98\ub77c\ub294 \ubc94\uc704\ub97c \uba3c\uc800 \uc77d\ub294\ub2e4. \ud3c9\uba74\uacfc \uace1\uba74\uc758 \ud45c\ud604\uc774 \uc11c\ub85c \ub2e4\ub978 \uc870\uac74\uc744 \uac00\uc9c4\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc544\ub294 \uac83\ub9cc\uc73c\ub85c\ub3c4 \uc5b4\uc0c9\ud574 \ubcf4\uc774\ub294 \ubd80\ubd84\uc744 \ub2e4\uc2dc \ubcfc \uc218 \uc788\ub2e4. \uc9c0\uad6c\uc758 \ud45c\uba74\uc744 \ub113\uac8c \ubcf4\uc5ec \uc8fc\ub294 \uc774\ubbf8\uc9c0\ub77c\uace0 \uc5b8\uc81c\ub098 \uc5b4\ub290 \uc21c\uac04 \ud55c \uce74\uba54\ub77c\uac00 \ucc0d\uc740 \ud55c \uc7a5\uba74\uc774\ub77c\uace0 \uc0dd\uac01\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc790\ub8cc\uc758 \uc81c\ubaa9\uacfc \uc81c\uc791 \uc124\uba85\uc744 \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \ud14d\uc2a4\ucc98\ub85c \uc815\ub9ac\ud574 \uc81c\uacf5\ud558\ub294 \uadf8\ub9bc\uc5d0\ub294 \ubaa8\ud615\uc758 \ud45c\uba74\uc5d0 \uc4f0\ub3c4\ub85d \ubc30\uce58\ud55c \uc815\ubcf4\ub77c\ub294 \uc131\uaca9\uc774 \uc788\ub2e4. \uc6d0\ub798\uc758 \uad00\uce21\uacfc \ucd5c\uc885 \ud30c\uc77c\uc758 \uc4f0\uc784\uc744 \uad6c\ubd84\ud574 \ubcfc \uc218 \uc788\ub2e4. \uadf8\ub798\uc11c \uc774 \ud30c\uc77c\uc744 \ubcf4\uba70 \uad6c\ub984\uacfc \uacc4\uc808, \ucd2c\uc601 \ub0a0\uc9dc\uc758 \ubaa8\ub4e0 \uc138\ubd80\ub97c \ucd94\uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc5ec\uae30\uc11c \uc77d\ub294 \uac83\uc740 \ub300\ub959\uacfc \ubc14\ub2e4\uac00 \ub193\uc778 \ud45c\uba74 \uc774\ubbf8\uc9c0\uc758 \ubaa8\uc2b5\uc774\ub2e4. \uc2e4\uc81c \uc9c0\uad6c \uc804\uccb4\uc758 \ud2b9\uc815\ud55c \ub0a0\uc744 \uadf8\ub300\ub85c \ubcf4\uc5ec \uc900\ub2e4\ub294 \uc8fc\uc7a5\uacfc \uc9c0\uad6c \ubaa8\ud615\uc744 \uc54c\uc544\ubcfc \uc678\ud615 \uc790\ub8cc\ub77c\ub294 \uc124\uba85\uc740 \ub2e4\ub974\ub2e4. \uc790\ub8cc\uac00 \uc5b4\ub5a4 \ubaa9\uc801\uc73c\ub85c \uc81c\uacf5\ub418\ub294\uc9c0 \uc54c\uc544\uc57c \uc9c8\ubb38\ub3c4 \uc815\ud655\ud574\uc9c4\ub2e4. \uba3c\uc800 \uc775\uc219\ud55c \ub300\ub959 \ud558\ub098\ub97c \ucc3e\uc740 \ub4a4 \ubc14\ub2e4\ub97c \ub530\ub77c \uc606\uc73c\ub85c \uc774\ub3d9\ud574 \ubcf4\uc790. \ud654\uba74\uc5d0\uc11c \ub5a8\uc5b4\uc838 \ubcf4\uc774\ub294 \uacf3\ub3c4 \uad6c \uc704\uc5d0 \ub193\uc600\uc744 \ub54c\ub294 \ub2e4\ub978 \uad00\uacc4\ub85c \ub9cc\ub0a0 \uc218 \uc788\ub2e4. \uc9c0\uad6c\ubcf8\uacfc \ud3c9\uba74 \uc9c0\ub3c4\uac00 \uc11c\ub85c \ub2e4\ub978 \uac10\uac01\uc744 \uc8fc\ub294 \uc774\uc720\ub2e4. \uc5b4\ub290 \ud45c\ud604 \ud558\ub098\uac00 \ubaa8\ub4e0 \ubcf4\uae30\ub97c \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc774\ub807\uac8c \ubcf4\uba74 \uc9c0\uad6c \uadf8\ub9bc\uc744 \uc18c\ube44\ud558\ub294 \ubc29\uc2dd\ub3c4 \uc870\uae08 \ub2ec\ub77c\uc9c4\ub2e4. \uc608\uc05c \uc6b0\uc8fc \uc774\ubbf8\uc9c0\uc5d0\uc11c \ud55c \uac78\uc74c \ub354 \ub4e4\uc5b4\uac00 \ubb34\uc5c7\uc744 \ubaa8\ud615\uc758 \ud45c\uba74\uc5d0 \ub193\uc73c\ub824\uace0 \ub9cc\ub4e4\uc5c8\ub294\uc9c0 \ubb3c\uc744 \uc218 \uc788\ub2e4. \ud615\ud0dc\uc640 \uc774\ubbf8\uc9c0, \uad00\uce21\uacfc \ud45c\ud604\uc774\ub77c\ub294 \uce35\uc774 \ub098\ub25c\ub2e4. \uc775\uc219\ud55c \ub465\uadfc \uc9c0\uad6c\uc758 \uc5bc\uad74 \ub4a4\uc5d0\ub3c4 \uc11c\ub85c \ub2e4\ub978 \uc790\ub8cc\ub97c \uc900\ube44\ud558\uace0 \uc5f0\uacb0\ud558\ub294 \uc791\uc5c5\uc774 \uc788\uc5c8\ub2e4\ub294 \uc810\uc774 \ub0a8\ub294\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 NASA\uac00 \uacf5\uac1c\ud55c \uc2e4\uc81c \uc9c0\ub3c4 \ud14d\uc2a4\ucc98 \uc790\ub8cc\ub2e4. AI\uac00 \uc0c1\uc0c1\ud574\uc11c \uadf8\ub9b0 \uc9c0\uad6c\ub294 \uc544\ub2c8\uc9c0\ub9cc, \uadf8\ub807\ub2e4\uace0 \uc6b0\uc8fc\uc5d0\uc11c \ucd2c\uc601\ud55c \ub2e8\uc77c \uc7a5\uba74\uc758 \uc0ac\uc9c4\ub3c4 \uc544\ub2c8\ub2e4. \ubb34\uc5c7\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc790\ub8cc\uc778\uc9c0 \uc544\ub294 \uac83\uc774 \uba3c\uc800\ub2e4. \ub2e4\uc74c\uc5d0 \ud654\uba74 \uc18d \uc9c0\uad6c\ubcf8\uc744 \ub9cc\ub098\uba74 \ub465\uadfc \ubaa8\uc591\ubfd0 \uc544\ub2c8\ub77c \uadf8 \uc704\uc5d0 \uc785\ud78c \ud45c\uba74\ub3c4 \ud55c \ubc88 \uc0dd\uac01\ud574 \ubcf4\uc790. \uc775\uc219\ud55c \ud589\uc131\uc758 \ubaa8\uc2b5 \ub4a4\uc5d0\ub294 \uc5b4\ub5a4 \ud2c0\uc5d0 \uc5b4\ub5a4 \uadf8\ub9bc\uc744 \uc5b9\uc744\uc9c0 \uace0\ub978 \uc791\uc5c5\uc774 \uc788\ub2e4. \uc9c0\uad6c\uc758 \uc5bc\uad74\uc740 \uadf8\ub807\uac8c \ud654\uba74 \uc18d\uc5d0\uc11c\ub3c4 \ub9cc\ub4e4\uc5b4\uc9c4\ub2e4."}, {"id": "elephant-ear-fan", "title": "\ucf54\ub07c\ub9ac\uac00 \uadc0\ub97c \ud754\ub4dc\ub294 \ub370\uc5d0\ub294 \uc774\uc720\uac00 \uc788\ub2e4", "summary": "\ub290\uae0b\ud558\uac8c \uadc0\ub97c \ud384\ub7ed\uc774\ub294 \ucf54\ub07c\ub9ac. \uadf8 \uc6c0\uc9c1\uc784\uc5d0\ub294 \ub4e3\ub294 \uc77c \ub9d0\uace0\ub3c4 \ub2e4\ub978 \uc5ed\ud560\uc774 \uc788\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "Science", "subcategory": "Biology", "url": "stories/elephant-ear-fan/index.html", "image": "media/elephant-ear-fan.jpg", "alt": "\ub098\ubb34 \uadf8\ub298\uc5d0\uc11c \uadc0\ub97c \uc6c0\uc9c1\uc774\ub294 \uc544\uc2dc\uc544\ucf54\ub07c\ub9ac\uc758 AI \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\ucf54\ub07c\ub9ac\uac00 \uadc0\ub97c \ud754\ub4dc\ub294 \ub370\uc5d0\ub294 \uc774\uc720\uac00 \uc788\ub2e4 \ucee4\ub2e4\ub780 \uadc0\uac00 \ubab8\uc758 \uc5f4\uc744 \uc2dd\ud788\ub294 \ubc29\ubc95 \ub290\uae0b\ud558\uac8c \uadc0\ub97c \ud384\ub7ed\uc774\ub294 \ucf54\ub07c\ub9ac. \uadf8 \uc6c0\uc9c1\uc784\uc5d0\ub294 \ub4e3\ub294 \uc77c \ub9d0\uace0\ub3c4 \ub2e4\ub978 \uc5ed\ud560\uc774 \uc788\uc2b5\ub2c8\ub2e4. Biology \uacfc\ud559 \ucf54\ub07c\ub9ac \uc601\uc0c1\uc744 \ubcf4\ub2e4 \ubcf4\uba74 \uadc0\uac00 \uc790\uafb8 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uc55e\uc73c\ub85c \ud55c \ubc88, \ub4a4\ub85c \ud55c \ubc88. \ubab8\uc740 \uac00\ub9cc\ud788 \uc788\ub294\ub370 \uadc0\ub9cc \ub290\uae0b\ud558\uac8c \uc6c0\uc9c1\uc778\ub2e4. \ucee4\ub2e4\ub780 \ubd80\ucc44 \ub450 \uac1c\ub97c \ub4e4\uace0 \uc788\ub294 \uac83 \uac19\ub2e4. \uc2e4\uc81c\ub85c \uadf8 \uadc0\ub294 \uc18c\ub9ac\ub97c \ub4e3\ub294 \uc77c \uc678\uc5d0 \ubab8\uc744 \uc2dd\ud788\ub294 \ub370\uc5d0\ub3c4 \uc4f0\uc778\ub2e4. \uc2a4\ubbf8\uc2a4\uc18c\ub2c8\uc5b8 \uad6d\ub9bd\ub3d9\ubb3c\uc6d0\uc758 \uc544\uc2dc\uc544\ucf54\ub07c\ub9ac \uc548\ub0b4\ub97c \uc77d\uc73c\uba74, \ud384\ub7ed\uc774\ub294 \uadc0 \uc548\ucabd\uc5d0 \uaf64 \ubc14\uc05c \uae38\uc774 \uc788\ub2e4\ub294 \uac83\uc744 \uc54c\uac8c \ub41c\ub2e4. \ud608\uad00\uc774\ub2e4. \uc544\uc2dc\uc544\ucf54\ub07c\ub9ac\uc758 \uadc0\uc5d0\ub294 \ub9ce\uc740 \ud608\uad00\uc774 \uc788\ub2e4. \ub354\uc6b4 \ub0a0 \uadc0\ub97c \uc6c0\uc9c1\uc774\uba74 \uadf8 \uc548\uc744 \ud750\ub974\ub294 \ud53c\uac00 \uc2dd\uace0, \uc2dd\uc740 \ud53c\uac00 \ub2e4\uc2dc \ubab8\uc744 \ub3cc\uba74\uc11c \uccb4\uc628\uc744 \ub0ae\ucd94\ub294 \ub370 \ub3c4\uc6c0\uc744 \uc900\ub2e4\uace0 \ub3d9\ubb3c\uc6d0\uc740 \uc124\uba85\ud55c\ub2e4. \uc6b0\ub9ac\uac00 \ubd80\ucc44\ub97c \ud754\ub4e4 \ub54c\ub294 \uc190\uc774 \ubc14\uc058\uc9c0\ub9cc, \ucf54\ub07c\ub9ac\ub294 \uadc0 \uc790\uccb4\ub97c \uc6c0\uc9c1\uc778\ub2e4. \ub530\ub73b\ud55c \ud53c\uac00 \uc9c0\ub098\ub294 \ub113\uc740 \uc790\ub9ac\ub97c \ubc14\ub78c\uc5d0 \ub0b4\uc5b4\ub193\ub294 \uc148\uc774\ub2e4. \uadf8\ub798\uc11c \uadc0\uc758 \uc6c0\uc9c1\uc784\uc744 \ubcf4\uace0 \uace7\ubc14\ub85c \uae30\ubd84\uc774\ub098 \uc131\uaca9\ub9cc \uc9d0\uc791\ud560 \uc77c\uc740 \uc544\ub2c8\ub2e4. \uadc0\ub294 \uac89\uc73c\ub85c \ubcf4\uc774\ub294 \ud06c\uae30\ub9cc\ud07c\uc774\ub098 \uc548\ucabd\uc758 \uad6c\uc870\ub3c4 \uc911\uc694\ud558\ub2e4. \ub113\uc801\ud55c \ubaa8\uc591\uacfc \ud608\uad00, \ud384\ub7ed\uc774\ub294 \ub3d9\uc791\uc774 \ud568\uaed8 \ubab8\uc758 \uc5f4\uc744 \ub2e4\ub8e8\ub294 \ub370 \uc4f0\uc778\ub2e4. \ucf54\ub07c\ub9ac\uc758 \ud53c\ubd80\ub294 \uc5b4\ub514\ub098 \ub611\uac19\uc774 \ub450\uaecd\uc9c0 \uc54a\ub2e4. \ub3d9\ubb3c\uc6d0\uc740 \ub4f1\ucc98\ub7fc \ub450\uaebc\uc6b4 \uacf3\uc774 \uc788\ub294 \ubc18\uba74, \uadc0 \uc548\ucabd\ucc98\ub7fc \uc544\uc8fc \uc587\uc740 \uacf3\ub3c4 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uba40\ub9ac\uc11c \ubcf8 \ucee4\ub2e4\ub780 \ubab8\uc5d0\ub3c4 \uc12c\uc138\ud55c \ubd80\ubd84\uc774 \uc11e\uc5ec \uc788\ub2e4. \ud53c\ubd80\ub294 \uc2e0\uacbd\uc774 \ud48d\ubd80\ud574 \ubbfc\uac10\ud558\ub2e4. \ucf54\ub07c\ub9ac\uac00 \ud759\uc774\ub098 \ubaa8\ub798, \uc9c4\ud759\uc744 \ubab8\uc5d0 \ub36e\ub294 \ud589\ub3d9\ub3c4 \ud587\ube5b\uacfc \ubc8c\ub808\ub85c\ubd80\ud130 \ud53c\ubd80\ub97c \ubcf4\ud638\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \uadc0\ub97c \uc6c0\uc9c1\uc774\uace0 \ubab8\uc5d0 \ud759\uc744 \ubb3b\ud788\ub294 \ubaa8\uc2b5\uc740, \ub354\uc6b4 \ub0a0\uc758 \uc0dd\ud65c\uc744 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \ubcf4\uc5ec\uc900\ub2e4. \ub3d9\ubb3c\uc6d0 \uc548\ub0b4\uc5d0\ub294 \uc544\uc2dc\uc544\ucf54\ub07c\ub9ac\uac00 \ud558\ub8e8 \uc911 \uac00\uc7a5 \ub354\uc6b4 \uc2dc\uac04\uc5d0 \uc26c\uac70\ub098 \ub0ae\uc7a0\uc744 \uc790\ub294 \uacbd\ud5a5\ub3c4 \ub098\uc628\ub2e4. \uadf8\ub298\uc5d0\uc11c \uc26c\ub294 \ubab8, \uc6c0\uc9c1\uc774\ub294 \uadc0, \ud53c\ubd80\uc5d0 \uc5b9\ud78c \ud759\uc774 \ud55c \uc7a5\uba74 \uc548\uc5d0 \ub193\uc778\ub2e4. \uadc0\uac00 \ubab8\uc758 \uc5f4\uc744 \ub2e4\ub8e8\ub294 \ub370 \uc4f0\uc778\ub2e4\ub294 \uc124\uba85\uc5d0\ub294 \ub113\uc740 \ud45c\uba74\uacfc \ud608\uad00\uc774 \ud568\uaed8 \ub4f1\uc7a5\ud55c\ub2e4. \uadc0\ub97c \uc6c0\uc9c1\uc774\ub294 \ud589\ub3d9\ub9cc \ub530\ub85c \ubcf4\ub294 \uac83\ubcf4\ub2e4 \uadf8 \uc548\ucabd\uc758 \ud750\ub984\uc744 \uc0dd\uac01\ud558\uba74 \uad6c\uc870\uac00 \ub354 \uad6c\uccb4\uc801\uc774\ub2e4. \ub530\ub73b\ud55c \ud53c\uac00 \uc9c0\ub098\uac00\ub294 \uc790\ub9ac\uac00 \uc8fc\ubcc0\uc758 \uacf5\uae30\uc640 \uad00\uacc4\ub97c \ub9fa\uace0, \uadf8 \ud53c\uac00 \ub2e4\uc2dc \ubab8\uc744 \ub3c4\ub294 \uacfc\uc815\uc774 \uc788\ub2e4. \ubab8\uc758 \uc77c\ubd80\uac00 \ub2e4\ub978 \uacf3\uc758 \uc0c1\ud0dc\uc640 \uc5f0\uacb0\ub418\ub294 \uac83\uc774\ub2e4. \ubd80\ucc44\ub77c\ub294 \ube44\uc720\ub294 \uc774 \uc6c0\uc9c1\uc784\uc744 \uc774\ud574\ud558\uac8c \ub3d5\uc9c0\ub9cc \uc0ac\ub78c\uc758 \uc190\ubd80\ucc44\uc640 \uc644\uc804\ud788 \uac19\uc740 \uc7a5\uce58\ub294 \uc544\ub2c8\ub2e4. \uadc0 \uc790\uccb4\uc5d0 \ud608\uad00\uc774 \uc788\uace0 \ud53c\ubd80\uc640 \ubab8\uc758 \uad6c\uc870\uac00 \ud568\uaed8 \uc791\uc6a9\ud55c\ub2e4. \uc775\uc219\ud55c \ub3c4\uad6c\uc640 \ub2ee\uc558\ub2e4\ub294 \uc785\uad6c\uc5d0\uc11c \ucd9c\ubc1c\ud574 \ub3d9\ubb3c\uc758 \uc2e4\uc81c \ubab8\uc744 \ub530\ub85c \uc77d\uc5b4\uc57c \ud55c\ub2e4. \uc7ac\ubbf8\uc788\ub294 \ubcc4\uba85\uc774 \ud574\ubd80\uc640 \ud589\ub3d9\uc758 \uc124\uba85\uc744 \ub300\uc2e0\ud558\uc9c0 \uc54a\ub3c4\ub85d \ud558\ub294 \uac83\uc774\ub2e4. \ud070 \ub3d9\ubb3c\uc758 \uc6c0\uc9c1\uc784\uc744 \ubcf4\uba74 \uc6b0\ub9ac\ub294 \ud654\uac00 \ub0ac\ub294\uc9c0 \uc990\uac70\uc6b4\uc9c0\ubd80\ud130 \uc9d0\uc791\ud55c\ub2e4. \uadf8\ub7ec\ub098 \uadc0\uc758 \uc6c0\uc9c1\uc784\uc5d0\ub294 \uccb4\uc628 \uc870\uc808\uacfc \uad00\ub828\ub41c \uae30\ub2a5\ub3c4 \uc788\ub2e4. \ud558\ub098\uc758 \ud589\ub3d9\uc5d0 \ud55c \uac00\uc9c0 \uac10\uc815\ub9cc \ubd99\uc774\uba74 \uc2e4\uc81c \ubab8\uc758 \ud544\uc694\ub97c \ub193\uce60 \uc218 \uc788\ub2e4. \ub3d9\ubb3c\uc6d0 \uc548\ub0b4\ub294 \uadf8\ub7f0 \uc775\uc219\ud55c \ud574\uc11d \ubc16\uc758 \uc124\uba85\uc744 \uc54c\ub824 \uc900\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubaa8\ub4e0 \uadc0 \uc6c0\uc9c1\uc784\uc774 \uc5b8\uc81c\ub098 \uc5f4\uc744 \uc2dd\ud788\ub294 \ubaa9\uc801 \ud558\ub098\ub77c\uace0 \uc815\ud560 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \uac1c\ubcc4 \uc7a5\uba74\uc744 \uc774\ud574\ud558\ub824\uba74 \uc0c1\ud669\uacfc \ub2e4\ub978 \ud589\ub3d9\uc744 \ud568\uaed8 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc548\ub0b4\uac00 \uc124\uba85\ud55c \uc544\uc2dc\uc544\ucf54\ub07c\ub9ac\uc758 \ubab8\uacfc \uae30\ub2a5\uc744 \ubc30\uc6b4\ub2e4. \uba40\ub9ac\uc11c \ubcf8 \ud45c\uc815\ucc98\ub7fc \ubcf4\uc774\ub294 \uc6c0\uc9c1\uc784\uc744 \ubab8\uc758 \uad6c\uc870\uc640 \uc5f0\uacb0\ud574 \ubcf4\ub294 \uad00\uc810\uc774\ub2e4. \ucf54\ub07c\ub9ac\uac00 \ubab8\uc5d0 \ud759\uc774\ub098 \uc9c4\ud759\uc744 \ub36e\uc73c\uba74 \uc778\uac04\uc758 \uae68\ub057\ud568 \uae30\uc900\uc73c\ub85c\ub294 \uc9c0\uc800\ubd84\ud574 \ubcf4\uc77c \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uc790\ub8cc\ub294 \ud587\ube5b\uacfc \ubc8c\ub808\ub85c\ubd80\ud130 \ud53c\ubd80\ub97c \ubcf4\ud638\ud558\ub294 \uc5ed\ud560\uc744 \uc124\uba85\ud55c\ub2e4. \ubcf4\uc774\ub294 \uc0c1\ud0dc\uc640 \uc2e4\uc81c \uae30\ub2a5\uc744 \ub098\ub204\uc5b4 \uc0dd\uac01\ud560 \ud544\uc694\uac00 \uc788\ub2e4. \ub3d9\ubb3c\uc758 \ud589\ub3d9\uc744 \uc0ac\ub78c\uc758 \uc0dd\ud65c \uc2b5\uad00\uc73c\ub85c\ub9cc \ud3c9\uac00\ud558\uc9c0 \uc54a\uc744 \uc774\uc720\ub2e4. \ubbfc\uac10\ud55c \ud53c\ubd80\ub77c\ub294 \uc124\uba85\ub3c4 \ud070 \ubab8\uc758 \uccab\uc778\uc0c1\uacfc \ub2e4\ub974\ub2e4. \ub450\uaebc\uc6b4 \uacf3\uc774 \uc788\uc5b4\ub3c4 \uc804\ubd80 \uac19\uc740 \ub450\uaed8\uac00 \uc544\ub2c8\uace0 \uac10\uac01\uc744 \uac00\uc9c4 \ubab8\uc774\ub2e4. \ud06c\uace0 \ud2bc\ud2bc\ud574 \ubcf4\uc778\ub2e4\ub294 \ub9d0\uc774 \ubd88\ud3b8\uacfc \uc790\uadf9\uc744 \ub290\ub07c\uc9c0 \uc54a\ub294\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uadc0\uc758 \uc587\uc740 \ubd80\uc704\uc640 \ud53c\ubd80\ub97c \ub36e\ub294 \ud589\ub3d9\uc744 \ud568\uaed8 \ubcf4\uba74 \ucf54\ub07c\ub9ac\uc758 \ud558\ub8e8\uac00 \uc870\uae08 \ub354 \uad6c\uccb4\uc801\uc73c\ub85c \ub290\uaef4\uc9c4\ub2e4. \ud558\ub8e8 \uc911 \ub354\uc6b4 \uc2dc\uac04\uc5d0 \uc26c\ub294 \uacbd\ud5a5\uc740 \uadc0\uc640 \ud53c\ubd80\uc758 \uad6c\uc870 \uc606\uc5d0 \ud589\ub3d9\uc758 \uc870\uc808\uc744 \ub354\ud55c\ub2e4. \ub3d9\ubb3c\uc740 \ubab8\uc758 \ud55c \ubd80\ubd84\ub9cc\uc73c\ub85c \ud658\uacbd\uc744 \uacac\ub514\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc6c0\uc9c1\uc784\uacfc \ud734\uc2dd, \uadf8\ub298\uacfc \ud53c\ubd80\uc758 \uc0c1\ud0dc\uac00 \ud568\uaed8 \uad00\uacc4\ub97c \ub9fa\ub294\ub2e4. \ub2e4\ub9cc \uc0ac\uc9c4 \ud55c \uc7a5\uc73c\ub85c \uc2e4\uc81c \uae30\uc628\uacfc \uac1c\uccb4\uc758 \uccb4\uc628\uc744 \uc54c\uc544\ub0bc \uc218\ub294 \uc5c6\ub2e4. \ub2e4\uc74c\uc5d0 \ucf54\ub07c\ub9ac\ub97c \uad00\ucc30\ud560 \uae30\ud68c\uac00 \uc788\ub2e4\uba74 \uadc0\ub9cc \ud655\ub300\ud558\uae30\ubcf4\ub2e4 \ubab8 \uc804\uccb4\uc640 \uc8fc\ubcc0\ub3c4 \uc0b4\ud3b4\ubcf4\uc790. \uadf8\ub298\uc5d0 \uc788\ub294\uc9c0, \ud759\uc774 \ubb3b\uc5b4 \uc788\ub294\uc9c0, \uac00\ub9cc\ud788 \uc26c\ub294\uc9c0 \uac19\uc740 \ub2e4\ub978 \uc815\ubcf4\uac00 \ub4e4\uc5b4\uc628\ub2e4. \ubaa8\ub4e0 \ud589\ub3d9\uc758 \uc774\uc720\ub97c \uadf8 \uc790\ub9ac\uc5d0\uc11c \ud655\uc815\ud560 \ud544\uc694 \uc5c6\uc774\ub3c4 \uc9c8\ubb38\uc740 \ub298\uc5b4\ub09c\ub2e4. \ud070 \uadc0\uc758 \ud384\ub7ed\uc784\uc774 \ub2e8\uc21c\ud55c \ubab8\uc9d3\uc5d0\uc11c \ud658\uacbd\uacfc \ubab8\uc744 \uc787\ub294 \ud589\ub3d9\uc73c\ub85c \ubcf4\uc774\uae30 \uc2dc\uc791\ud55c\ub2e4. \ub3d9\ubb3c\uc740 \ube68\ub9ac \ub2ec\ub9ac\uac70\ub098 \ud06c\uac8c \uc6b8 \ub54c\ub9cc \ubcfc\uac70\ub9ac\ub97c \uc8fc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc870\uc6a9\ud788 \uc11c \uc788\uc744 \ub54c\ub3c4 \ubab8\uc758 \uc791\uc740 \ubd80\ubd84\uc740 \uc77c\uc744 \ud558\uace0 \uc788\ub2e4. \uadc0\ub97c \ud55c\ubc88 \uc6c0\uc9c1\uc774\ub294 \ub370\uc5d0\ub3c4 \uc0dd\ud65c\uc758 \uc774\uc720\uac00 \uc788\ub2e4. \ub2e4\uc74c\uc5d0 \ucf54\ub07c\ub9ac\ub97c \ub9cc\ub098\uba74 \uae34 \ucf54\ub97c \ubcf8 \ub4a4 \uadc0\uc5d0\ub3c4 \uc7a0\uae50 \ub208\uc744 \uc8fc\uc5b4 \ubcf4\uc790. \uc774 \uc774\uc57c\uae30\uac00 \ub2e4\ub8ec \uac83\uc740 \uc544\uc2dc\uc544\ucf54\ub07c\ub9ac\ub2e4. \uadc0\uc758 \ubaa8\uc591\uacfc \ud06c\uae30\ub97c \ub2e4\ub978 \ucf54\ub07c\ub9ac\uc640 \ube44\uad50\ud574 \ubcf4\ub294 \uac83\ub3c4 \uc7ac\ubbf8\uc788\uaca0\uc9c0\ub9cc, \uc6b0\uc120\uc740 \ud55c \ubc88\uc758 \ud384\ub7ed\uc784\uc744 \ucc9c\ucc9c\ud788 \ubcf4\ub294 \uac83\uc73c\ub85c \ucda9\ubd84\ud558\ub2e4. \ub290\uae0b\ud55c \uc624\ud6c4\ucc98\ub7fc \ubcf4\uc774\ub358 \uc7a5\uba74 \uc548\uc5d0\uc11c, \ucee4\ub2e4\ub780 \ubab8\uc740 \uc790\uae30 \ubc29\uc2dd\uc73c\ub85c \ub354\uc704\ub97c \uacac\ub514\uace0 \uc788\uc5c8\ub358 \uac83\uc774\ub2e4."}, {"id": "flamingo-pink-feathers", "title": "\ud50c\ub77c\ubc0d\uace0\ub294 \ud0dc\uc5b4\ub0a0 \ub54c\ubd80\ud130 \ubd84\ud64d\uc0c9\uc77c\uae4c", "summary": "\ubd84\ud64d\uc0c9 \uc0c8 \ud558\uba74 \ub5a0\uc624\ub974\ub294 \ud50c\ub77c\ubc0d\uace0. \ud558\uc9c0\ub9cc \uadf8 \uc0c9\uc740 \ud0dc\uc5b4\ub0a0 \ub54c\ubd80\ud130 \uc644\uc131\ub41c \uac83\uc774 \uc544\ub2d9\ub2c8\ub2e4.", "category": "science", "category_title": "Science", "subcategory": "Biology", "url": "stories/flamingo-pink-feathers/index.html", "image": "media/flamingo-pink-feathers.jpg", "alt": "\ud50c\ub77c\ubc0d\uace0\ub294 \ud0dc\uc5b4\ub0a0 \ub54c\ubd80\ud130 \ubd84\ud64d\uc0c9\uc77c\uae4c \u2014 \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\ud50c\ub77c\ubc0d\uace0\ub294 \ud0dc\uc5b4\ub0a0 \ub54c\ubd80\ud130 \ubd84\ud64d\uc0c9\uc77c\uae4c \uc6b0\uc544\ud55c \uae43\ud138\uc5d0 \uc228\uc5b4 \uc788\ub294 \uc2dd\uc0ac\uc758 \ud754\uc801 \ubd84\ud64d\uc0c9 \uc0c8 \ud558\uba74 \ub5a0\uc624\ub974\ub294 \ud50c\ub77c\ubc0d\uace0. \ud558\uc9c0\ub9cc \uadf8 \uc0c9\uc740 \ud0dc\uc5b4\ub0a0 \ub54c\ubd80\ud130 \uc644\uc131\ub41c \uac83\uc774 \uc544\ub2d9\ub2c8\ub2e4. Biology \uacfc\ud559 \ud50c\ub77c\ubc0d\uace0\ub97c \uadf8\ub824 \ubcf4\ub77c\uace0 \ud558\uba74 \ubd84\ud64d\uc0c9\ubd80\ud130 \ucc3e\uac8c \ub41c\ub2e4. \uae34 \ub2e4\ub9ac\uc640 \uad7d\uc740 \ubaa9\ub3c4 \uc911\uc694\ud558\uc9c0\ub9cc, \uc0c9\uc744 \ube7c\ub193\uc73c\uba74 \uc5b4\uca50\uc9c0 \ub2e4\ub978 \uc0c8\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \uadf8\ub7f0\ub370 \uc5b4\ub9b0 \ud50c\ub77c\ubc0d\uace0\ub294 \uc6b0\ub9ac\uac00 \ub5a0\uc62c\ub9ac\ub294 \uc120\uba85\ud55c \ubd84\ud64d\uc0c9\uacfc \ub2e4\ub974\ub2e4. \ud68c\uc0c9\ube5b\uc774\ub098 \ud770\ube5b\uc774 \ub3c4\ub294 \uc19c\ud138\ub85c \uc2dc\uc791\ud55c\ub2e4. \ucc98\uc74c\ubd80\ud130 \uc5b4\ub978 \uc0c8\uc640 \ub611\uac19\uc740 \uc0c9\uc758 \uc791\uc740 \ubcf5\uc0ac\ubcf8\uc774 \ud0dc\uc5b4\ub098\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub807\ub2e4\uba74 \uc790\ub77c\uba74\uc11c \ubd84\ud64d\uc0c9\uc740 \uc5b4\ub514\uc5d0\uc11c \uc624\ub294 \uac83\uc77c\uae4c. \ub2f5\uc744 \ucc3e\uc73c\ub824\uba74 \uae43\ud138\ubcf4\ub2e4 \uba3c\uc800 \uba39\uc774\ub97c \ubcf4\uc544\uc57c \ud55c\ub2e4. \ud50c\ub77c\ubc0d\uace0\uac00 \uba39\ub294 \uc870\ub958\ub098 \uc791\uc740 \uac11\uac01\ub958 \ub4f1\uc5d0\ub294 \uce74\ub85c\ud2f0\ub178\uc774\ub4dc\ub77c\ub294 \uc0c9\uc18c\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \uc870\uae08 \ub0af\uc120 \uc774\ub984\uc774\uc9c0\ub9cc \uc790\uc5f0\uc5d0\uc11c \uc5ec\ub7ec \ub178\ub791\u00b7\uc8fc\ud669\u00b7\ubd89\uc740\ube5b\uacfc \uad00\ub828\ub418\ub294 \uc0c9\uc18c \ubb34\ub9ac\ub2e4. \ud50c\ub77c\ubc0d\uace0\ub294 \uba39\uc774\uc5d0\uc11c \uc5bb\uc740 \uc774\ub7f0 \uc131\ubd84\uc744 \ubab8 \uc548\uc5d0\uc11c \ucc98\ub9ac\ud558\uace0, \uadf8 \uacb0\uacfc\uac00 \uae43\ud138\uc758 \uc0c9\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc900\ub2e4. \uba39\uc740 \uac83\uc744 \ub2e8\uc21c\ud788 \uae43\ud138 \ubc14\uae65\uc5d0 \ubb3b\ud788\ub294 \ubc29\uc2dd\uc740 \uc544\ub2c8\ub2e4. \ubab8\uc758 \uacfc\uc815\uc774 \uc788\uc5b4\uc57c \uba39\uc774\uc640 \uc0c8\uc758 \ubaa8\uc2b5\uc774 \uc5f0\uacb0\ub41c\ub2e4. \uadf8\ub798\uc11c \uc0c8\uc6b0\ub97c \uba39\uc5b4\uc11c \ubd84\ud64d\uc0c9\uc774\ub77c\ub294 \uc124\uba85\uc740 \uae30\uc5b5\ud558\uae30 \uc27d\uc9c0\ub9cc \uc870\uae08 \uc9e7\ub2e4. \ubaa8\ub4e0 \ud50c\ub77c\ubc0d\uace0\uac00 \uac19\uc740 \uba39\uc774\ub97c \uac19\uc740 \ube44\uc728\ub85c \uba39\ub294 \uac83\uc740 \uc544\ub2c8\uace0, \uc0c9\uc18c\uc758 \uacbd\ub85c\ub3c4 \ud55c \uac00\uc9c0 \uc74c\uc2dd\uc73c\ub85c\ub9cc \uc124\uba85\ub418\uc9c0 \uc54a\ub294\ub2e4. \ubd84\ud64d\uc0c9 \uae43\ud138\uc744 \uc774\ud574\ud558\ub824\uba74 \ub208\uc5d0 \ubcf4\uc774\ub294 \uc0c8\ub9cc \ubcfc \uac83\uc774 \uc544\ub2c8\ub77c \uadf8 \uc0c8\uac00 \uba39\ub294 \uac83\ub3c4 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc2a4\ubbf8\uc2a4\uc18c\ub2c8\uc5b8 \uad6d\ub9bd\ub3d9\ubb3c\uc6d0\uc740 \uba39\uc774\uc758 \uc0c9\uc18c\ub97c \ubab8 \uc548\uc5d0\uc11c \ucc98\ub9ac\ud558\ub294 \uacfc\uc815\uc774 \uae43\ud138\uc758 \ubd84\ud64d\ube5b\uc73c\ub85c \uc774\uc5b4\uc9c4\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud50c\ub77c\ubc0d\uace0 \uc0ac\uc9c4\uc744 \uc5ec\ub7ec \uc7a5 \ub193\uace0 \ubcf4\uba74 \uc0c9\uc774 \ubaa8\ub450 \uac19\uc9c0 \uc54a\ub2e4. \uc5f0\ud55c \ubd84\ud64d\ube5b\uc744 \ub760\ub294 \uc0c8\ub3c4 \uc788\uace0, \ub354 \uc120\uba85\ud55c \ubd89\uc740\ube5b\uc5d0 \uac00\uae4c\uc6b4 \uc0c8\ub3c4 \uc788\ub2e4. \uc885\uacfc \ub098\uc774, \uba39\uc774\uc640 \uae43\ud138\uc758 \uc0c1\ud0dc \uac19\uc740 \uc5ec\ub7ec \uc870\uac74\uc774 \uad00\ub828\ub41c\ub2e4. \uadf8\ub7ec\ubbc0\ub85c \uc0c9\uc774 \uc605\uc740 \uc0c8 \ud55c \ub9c8\ub9ac\ub97c \ubcf4\uace0 \ubc14\ub85c \ubc30\uac00 \uace0\ud504\ub2e4\uac70\ub098 \uac74\uac15\uc5d0 \ubb38\uc81c\uac00 \uc788\ub2e4\uace0 \ud310\ub2e8\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc0ac\uc9c4\uc758 \ube5b\uacfc \ucd2c\uc601 \uc870\uac74\ub3c4 \uc2e4\uc81c\ub85c \ubcf4\uc774\ub294 \uc0c9\uc5d0 \uc601\ud5a5\uc744 \uc900\ub2e4. \uc0c9\uae54 \ud558\ub098\ub85c \uc0c8\uc758 \uc0c1\ud0dc\ub97c \ubaa8\ub450 \uc77d\uc744 \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub9b0 \uc0c8\uac00 \uc790\ub77c\uba74\uc11c \uc5b4\ub978\uc758 \uc0c9\uc744 \uac16\ucd94\ub294 \ub370\uc5d0\ub3c4 \uc2dc\uac04\uc774 \ud544\uc694\ud558\ub2e4. \uba39\uc774 \ud55c \ub07c\ub97c \uba39\uace0 \ubc14\ub85c \uc628\ubab8\uc774 \ubb3c\ub4dc\ub294 \ub9cc\ud654 \uac19\uc740 \ubcc0\ud654\ub294 \uc544\ub2c8\ub2e4. \uc6b0\ub9ac\uac00 \ubcf4\ub294 \uae43\ud138\uc5d0\ub294 \uadf8 \uc0c8\uac00 \uc0b4\uc544\uc628 \uc2dc\uac04\uc774 \uc870\uae08\uc529 \ubc18\uc601\ub418\uc5b4 \uc788\ub2e4. \uc774\ub807\uac8c \uc0dd\uac01\ud558\uba74 \ubd84\ud64d\uc0c9\uc740 \uc7a5\uc2dd \uc774\uc0c1\uc758 \uac83\uc774 \ub41c\ub2e4. \uc0dd\uae40\uc0c8\ub97c \uc54c\uc544\ubcf4\uac8c \ud558\ub294 \ud2b9\uc9d5\uc774\uba74\uc11c, \uc0c8\uac00 \uc0ac\ub294 \ud658\uacbd\uacfc \uba39\ub294 \uac83\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \ub2e8\uc11c\uc774\uae30\ub3c4 \ud558\ub2e4. \uc0c9\uc18c\uac00 \ub4e0 \uba39\uc774\ub97c \uba39\ub294\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ubb3c\uac10\uc744 \uae43\ud138\uc5d0 \uce60\ud55c\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \uc12d\ucde8\ud55c \uc131\ubd84\uc744 \ubab8\uc5d0\uc11c \ub2e4\ub8e8\uace0 \uae43\ud138\uc774 \uc790\ub77c\ub294 \uacfc\uc815\uacfc \uc774\uc5b4\uc838\uc57c \ud55c\ub2e4. \uadf8\ub798\uc11c \ubd84\ud64d\ube5b\uc744 \ub2e8\uc21c\ud788 \ubb3c\uc5d0 \ube44\uce5c \uc0c9\uc774\ub098 \uae43\ud138 \ubc14\uae65\uc5d0 \ubb3b\uc740 \uc5bc\ub8e9\uc73c\ub85c \uc124\uba85\ud558\uc9c0 \uc54a\ub294\ub2e4. \ubcf4\uc774\ub294 \uc0c9\uc740 \uc0dd\ubb3c\uc774 \uc0b4\uc544\uac00\ub294 \uacfc\uc815\uacfc \uad00\uacc4\uac00 \uc788\ub2e4. \uc774 \uc5f0\uacb0\uc744 \uc54c\uba74 \uba39\uc774 \ud55c \uc885\ub958\ub9cc \uc678\uc6b0\ub294 \uc124\uba85\uc5d0\uc11c \uc870\uae08 \ubc97\uc5b4\ub0a0 \uc218 \uc788\ub2e4. \uc870\ub958\uc640 \uc791\uc740 \uac11\uac01\ub958 \ub4f1 \uc5ec\ub7ec \uba39\uc774\uac00 \uc788\uace0 \uc885\uacfc \ud658\uacbd\uc758 \ucc28\uc774\ub3c4 \uc788\ub2e4. \uc790\ub8cc\uc758 \ud070 \uc6d0\ub9ac\ub97c \uc774\ud574\ud558\ub294 \uac83\uacfc \ud2b9\uc815\ud55c \uc0c8\uac00 \uc2e4\uc81c\ub85c \ubb34\uc5c7\uc744 \uc5bc\ub9c8\ub098 \uba39\uc5c8\ub294\uc9c0 \uc544\ub294 \uac83\uc740 \ub2e4\ub974\ub2e4. \uc0ac\uc9c4\uc758 \uc0c9\ub9cc\uc73c\ub85c \uc2dd\ub2e8\uc744 \uc815\ud655\ud788 \uc5ed\uc0b0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ud770\uc0c9\uc774\ub098 \ud68c\uc0c9 \uc19c\ud138\uc758 \uc5b4\ub9b0 \uc0c8\ub294 \uc131\uccb4\ub97c \ucd95\uc18c\ud55c \ubaa8\uc591\ub9cc\uc740 \uc544\ub2c8\ub2e4. \uc131\uc7a5\uacfc \uae43\ud138\uc758 \ubcc0\ud654\uac00 \ud544\uc694\ud558\ub2e4. \uc774\ub984\ub09c \ud2b9\uc9d5\uc744 \uc0dd\ud6c4 \uccab \uc21c\uac04\ubd80\ud130 \ubaa8\ub450 \uac16\ucd94\uace0 \uc788\uc73c\ub9ac\ub77c\uace0 \uae30\ub300\ud558\uba74 \ub193\uce60 \uc2dc\uac04\uc774 \uc788\ub2e4. \ub3d9\ubb3c\uc758 \ubaa8\uc2b5\uc740 \ubd84\ub958\uc758 \ud45c\uc9c0\uc774\uba74\uc11c \uc0dd\uc560\uc758 \ud55c \ub2e8\uacc4\ub3c4 \ubcf4\uc5ec \uc900\ub2e4. \uac19\uc740 \uc885\uc758 \uc0ac\uc9c4\uc5d0\uc11c \uc0c9\uacfc \ud06c\uae30\uac00 \ub2e4\ub978 \uac1c\uccb4\ub97c \ubcf4\ub354\ub77c\ub3c4 \ubb34\uc870\uac74 \uc608\uc678\ub098 \uc774\uc0c1 \uc0c1\ud0dc\ub85c \ud310\ub2e8\ud558\uc9c0 \uc54a\uc544\uc57c \ud55c\ub2e4. \uc5b4\ub290 \ub098\uc774\uc640 \uae43\ud138 \uc0c1\ud0dc\uc778\uc9c0 \uc790\ub8cc\ub97c \ud655\uc778\ud558\ub294 \uac83\uc774 \uba3c\uc800\ub2e4. \uae43\ud138\uc758 \ubd84\ud64d\uc0c9\uc740 \ub2e8\ubc88\uc5d0 \uc644\uc131\ud55c \ub85c\uace0\ucc98\ub7fc \uace0\uc815\ub41c \uac83\uc774 \uc544\ub2c8\ub77c \ubab8\uacfc \ud658\uacbd, \uc2dc\uac04\uc774 \uc774\uc5b4\uc9c4 \uacb0\uacfc\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \ub3d9\ubb3c\uc6d0 \uc124\uba85\uc5d0\ub294 \uc595\uc740 \ubb3c\uc5d0\uc11c \uba39\uc774\ub97c \uc5bb\uace0 \ubd80\ub9ac\ub85c \uc5ec\uacfc\ud558\ub294 \uae30\ub2a5\ub3c4 \ub4f1\uc7a5\ud55c\ub2e4. \ubd84\ud64d\uc0c9\uc774\ub77c\ub294 \uacb0\uacfc\ub9cc \ubcf4\ub2e4\uac00 \ubb34\uc5c7\uc744 \uc5b4\ub5a4 \ubc29\uc2dd\uc73c\ub85c \uba39\ub294\uc9c0\uae4c\uc9c0 \uad00\uc2ec\uc774 \ub113\uc5b4\uc9c4\ub2e4. \uc0c9\uc758 \uc774\uc57c\uae30\uac00 \ubab8\uc758 \ub2e4\ub978 \uad6c\uc870\ub85c \uc774\uc5b4\uc9c0\ub294 \uac83\uc774\ub2e4. \ub2e4\ub9cc \ubd80\ub9ac\uac00 \uac78\ub7ec \ub0b4\ub294 \ubaa8\ub4e0 \ub300\uc0c1\uacfc \uadf8 \uc591\uc744 \uc0ac\uc9c4\uc5d0\uc11c \ud655\uc778\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \ud55c \ud2b9\uc9d5\uc744 \ubc30\uc6b4 \ub4a4\uc5d0\ub294 \uadf8 \ud2b9\uc9d5\uc744 \uac00\ub2a5\ud558\uac8c \ud558\ub294 \uc0dd\ud65c\uc744 \ubb3c\uc5b4\ubcfc \uc218 \uc788\ub2e4. \ud50c\ub77c\ubc0d\uace0\ub97c \uc54c\uc544\ubcf4\ub294 \ub370 \uc0c9\uc774 \uc88b\uc740 \ub2e8\uc11c\uac00 \ub418\uc5b4\ub3c4 \uadf8\uac83\ub9cc\uc774 \uc0dd\ubb3c\uc758 \uc804\ubd80\ub294 \uc544\ub2c8\ub2e4. \uba39\uc774\ub97c \uc5bb\ub294 \ud589\ub3d9\uacfc \uc790\ub77c\ub294 \uc2dc\uac04\uc744 \ud568\uaed8 \ubcf4\uba74 \uc544\ub984\ub2e4\uc6b4 \uc0c8\ub77c\ub294 \uc778\uc0c1\uc5d0 \uad6c\uccb4\uc801\uc778 \uc0dd\ud0dc\uc758 \uc9c8\ubb38\uc774 \ub354\ud574\uc9c4\ub2e4. \uc775\uc219\ud55c \ubd84\ud64d\ube5b\uc5d0\uc11c \ucd9c\ubc1c\ud574 \ubcf4\uae30\uc758 \ubc94\uc704\uac00 \ub113\uc5b4\uc9c4\ub2e4. \ud50c\ub77c\ubc0d\uace0\uac00 \ubb3c\uc5d0 \ubd80\ub9ac\ub97c \ub123\uace0 \uc6c0\uc9c1\uc774\ub294 \ubaa8\uc2b5\uc744 \ubcfc \ub54c\uac00 \uc788\ub2e4. \uae34 \ubaa9\uacfc \ub3c5\ud2b9\ud55c \ubd80\ub9ac\ub294 \uc595\uc740 \ubb3c\uc5d0\uc11c \uba39\uc774\ub97c \uc5bb\ub294 \ubc29\uc2dd\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uc6b0\uc544\ud55c \uc790\uc138\ub9cc \ucde8\ud558\uace0 \uc788\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc2dd\uc0ac \uc911\uc77c \uc218 \uc788\ub2e4. \uba40\ub9ac\uc11c \ubc14\ub77c\ubcf4\uba74 \uc6b0\ub9ac\ub294 \ubd84\ud64d\ube5b \ubb34\ub9ac\ub77c\ub294 \ud070 \ud48d\uacbd\uc744 \ubcf8\ub2e4. \uc870\uae08 \ub354 \ub4e4\uc5ec\ub2e4\ubcf4\uba74 \ud55c \ub9c8\ub9ac\ub294 \uba39\uc774\ub97c \ucc3e\uace0, \ub2e4\ub978 \ud55c \ub9c8\ub9ac\ub294 \uae43\ud138\uc744 \uc190\uc9c8\ud55c\ub2e4. \ud3ec\uc2a4\ud130\uc5d0 \uadf8\ub824\uc9c4 \uc0c1\uc9d5\uacfc \ub2ec\ub9ac \uc2e4\uc81c \uc0c8\ub294 \uacc4\uc18d \uc0dd\ud65c\ud558\uace0 \uc788\ub2e4. \ud50c\ub77c\ubc0d\uace0\ub97c \uc88b\uc544\ud55c\ub2e4\uace0 \uc5b4\ub824\uc6b4 \uc0dd\ubb3c\ud559 \uc6a9\uc5b4\ub97c \uc678\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \uadf8 \ubd84\ud64d\uc0c9\uc774 \ucc98\uc74c\ubd80\ud130 \uc644\uc131\ub41c \ubb3c\uac10\ucc98\ub7fc \uc8fc\uc5b4\uc9c4 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc0ac\uc2e4\ub9cc \uc54c\uc544\ub3c4 \ucda9\ubd84\ud788 \uc7ac\ubbf8\uc788\ub2e4. \ub2e4\uc74c\uc5d0 \ubd84\ud64d\uc0c9 \ud50c\ub77c\ubc0d\uace0\ub97c \ub9cc\ub098\uba74 \uae43\ud138\uc744 \ud55c \ubc88, \ubb3c\uc18d\uc758 \ubd80\ub9ac\ub97c \ud55c \ubc88 \ubcf4\uc790. \ub208\uc5d0 \ubcf4\uc774\ub294 \uc0c9\uacfc \ub208\uc5d0 \uc798 \ub744\uc9c0 \uc54a\ub294 \uc2dd\uc0ac\uac00 \uac19\uc740 \uc774\uc57c\uae30 \uc548\uc5d0 \ub4e4\uc5b4 \uc788\ub2e4. \uc544\ub984\ub2e4\uc6b4 \uae43\ud138\uc5d0\ub3c4 \ub098\ub984\uc758 \uc2dd\ub2e8\uc774 \uc788\uc5c8\ub358 \uc148\uc774\ub2e4."}, {"id": "galileo-telescope-changed-sky", "title": "\uac08\ub9b4\ub808\uc624 \u2014 \ub9dd\uc6d0\uacbd\uc744 \ubc24\ud558\ub298\ub85c \ub3cc\ub9ac\ub358 \ub54c", "summary": "1609\ub144\uc758 \ub9dd\uc6d0\uacbd \uc2dc\uc5f0\uc5d0\uc11c \ub2ec\u00b7\ubaa9\uc131\u00b7\uae08\uc131\uc758 \uad00\uce21\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \ubc1c\uacac\uc758 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "Science", "subcategory": "Physics", "url": "stories/galileo-telescope-changed-sky/index.html", "image": "media/galileo-telescope-changed-sky.png", "alt": "17\uc138\uae30 \ucd08\uc758 \uc0c1\uc0c1 \uc18d \uad00\uce21\uc790\uac00 \ud14c\ub77c\uc2a4\uc5d0\uc11c \uc791\uc740 \ub9dd\uc6d0\uacbd\uc73c\ub85c \ubc24\ud558\ub298\uc744 \ubc14\ub77c\ubcf4\ub294 \uc0bd\ud654.", "text": "\uac08\ub9b4\ub808\uc624 \u2014 \ub9dd\uc6d0\uacbd\uc744 \ubc24\ud558\ub298\ub85c \ub3cc\ub9ac\ub358 \ub54c \uba3c \ubc30\ub97c \ubcf4\ub358 \ub3c4\uad6c\uac00 \ud558\ub298\uc758 \uc9c8\uc11c\ub97c \ubb3b\uae30\uae4c\uc9c0 1609\ub144\uc758 \ub9dd\uc6d0\uacbd \uc2dc\uc5f0\uc5d0\uc11c \ub2ec\u00b7\ubaa9\uc131\u00b7\uae08\uc131\uc758 \uad00\uce21\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \ubc1c\uacac\uc758 \uacfc\uc815\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Physics \uacfc\ud559 \uba40\ub9ac \uc788\ub294 \ubc30\ub97c \uac00\uae4c\uc774 \ubcf4\ub294 \ub3c4\uad6c\uac00 \uc0dd\uacbc\ub2e4. \ud56d\uad6c\uc5d0\uc11c \uc120\ubc15\uc744 \uba3c\uc800 \uc54c\uc544\ubcf4\uace0 \uc2f6\uc5b4 \ud558\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc720\uc6a9\ud55c \ubc1c\uba85\ud488\uc774\uc5c8\ub2e4. \uadf8\ub7f0\ub370 \uadf8 \ub3c4\uad6c\ub97c \ubc24\ud558\ub298\ub85c \ub3cc\ub9ac\uba74 \ubb34\uc5c7\uc774 \ubcf4\uc77c\uae4c. 17\uc138\uae30 \ucd08 \uac08\ub9b4\ub808\uc624\ub294 \uc774 \uc9c8\ubb38\uc73c\ub85c \uc0ac\ub78c\ub4e4\uc774 \uc54c\uace0 \uc788\ub2e4\uace0 \ubbff\ub358 \ud558\ub298\uc744 \ub2e4\uc2dc \uc0b4\ud3c8\ub2e4. \uadf8\uac00 \ub9dd\uc6d0\uacbd \uc790\uccb4\ub97c \ucc98\uc74c \ubc1c\uba85\ud55c \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \uc774\ubbf8 \uc54c\ub824\uc9c4 \ub3c4\uad6c\ub97c \uac1c\uc120\ud558\uace0, \uadf8\uac83\uc744 \ud1b5\ud574 \ubcf4\uc774\ub294 \ud604\uc0c1\uc774 \ubbff\uc744 \ub9cc\ud55c\uc9c0 \ud655\uc778\ud558\uba70, \uae30\uc874\uc758 \uc124\uba85\uacfc \ube44\uad50\ud55c \uacfc\uc815\uc774\uc5c8\ub2e4. \ubc1c\uacac\uc740 \ub80c\uc988\ub97c \ub208\uc5d0 \ub304 \ud55c\uc21c\uac04\ubcf4\ub2e4 \uae38\uc5c8\ub2e4. \uad50\uc7ac\ub294 1608\ub144 \ub124\ub35c\ub780\ub4dc\uc5d0\uc11c \uc54c\ub824\uc9c4 \ub9dd\uc6d0 \ub3c4\uad6c\uc640 \ud55c\uc2a4 \ub9ac\ud37c\uc138\uc774\ub97c \uc18c\uac1c\ud55c\ub2e4. \uac08\ub9b4\ub808\uc624\ub294 \uadf8 \uc18c\uc2dd\uc744 \ub4e3\uace0 \uc790\uc2e0\uc758 \ub3c4\uad6c\ub97c \ub9cc\ub4e4\uc5c8\ub2e4. \ucc98\uc74c\ubd80\ud130 \uc624\ub298\ub0a0\uc758 \ucc9c\ubb38\ub300 \uac19\uc740 \uc7a5\ube44\uac00 \uc788\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub80c\uc988\uc640 \uad00\uc744 \uc870\ud569\ud558\ub294 \uc791\uc5c5\uc5d0\uc11c \ucd9c\ubc1c\ud588\ub2e4. \uba40\ub9ac \uc788\ub294 \uac83\uc744 \ud06c\uac8c \ubcf4\uc774\uac8c \ud55c\ub2e4\ub294 \uad6c\uc0c1\uc740 \ub2e8\uc21c\ud574 \ubcf4\uc774\uc9c0\ub9cc \uc2e4\uc81c\ub85c \uc120\uba85\ud55c \uc0c1\uc744 \uc5bb\ub294 \uac83\uc740 \ub2e4\ub978 \ubb38\uc81c\ub2e4. \uac08\ub9b4\ub808\uc624\ub294 \ubc30\uc728\uacfc \uad11\ud559 \uc131\ub2a5\uc744 \ub192\uc774\uace0 \uc548\uc815\uc801\uc73c\ub85c \uc9c0\uc9c0\ud558\ub294 \uc7a5\uce58\ub3c4 \ub9c8\ub828\ud588\ub2e4. \uad00\uce21\uc758 \uc5ed\uc0ac\ub294 \ub208\uc758 \uc5ed\uc0ac\uc774\uba74\uc11c \ub3c4\uad6c\ub97c \ub9cc\ub4dc\ub294 \uc190\uc758 \uc5ed\uc0ac\uc774\uae30\ub3c4 \ud588\ub2e4. 1609\ub144 8\uc6d4 25\uc77c \uac08\ub9b4\ub808\uc624\ub294 \ubca0\ub124\uce58\uc544\uc758 \uad00\ub9ac\ub4e4\uc5d0\uac8c \ub9dd\uc6d0\uacbd\uc744 \uc2dc\uc5f0\ud588\ub2e4. \uad50\uc7ac\ub294 \ub2f9\uc2dc \ubc30\uc728\uc774 \uc544\ud649 \ubc30\uc600\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uba40\ub9ac \uc788\ub294 \ub300\uc0c1\uc744 \uc77c\ucc0d \ud655\uc778\ud558\ub294 \ub2a5\ub825\uc740 \uad70\uc0ac\uc640 \ud574\uc0c1 \ud65c\ub3d9\uc5d0\uc11c \uad00\uc2ec\uc744 \ub04c \ub9cc\ud588\ub2e4. \ubcc4\ubcf4\ub2e4 \uc9c0\uc0c1\uc758 \ud65c\uc6a9\uc774 \uba3c\uc800 \uc0ac\ub78c\ub4e4\uc758 \ub208\uc55e\uc5d0 \ub193\uc600\ub2e4. \uadf8 \ub4a4 \ubc24\ud558\ub298\uc758 \uad00\uce21\uc5d0 \ub9de\ucd94\uc5b4 \ub3c4\uad6c\uc758 \uc131\ub2a5\uc774 \ub354 \uac1c\uc120\ub418\uc5c8\ub2e4. \uac19\uc740 \ubb3c\uac74\ub3c4 \uc5b4\ub5a4 \uc9c8\ubb38\uc5d0 \uc0ac\uc6a9\ud558\ub294\uc9c0\uc5d0 \ub530\ub77c \uc5ed\ud560\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uba3c \ubc30\ub97c \ubcf4\ub294 \uc720\uc6a9\ud568\uc5d0\uc11c \ud558\ub298\uc758 \uae30\uc874 \uc124\uba85\uc744 \uc2dc\ud5d8\ud558\ub294 \ub3c4\uad6c\ub85c \ub118\uc5b4\uac08 \uc218 \uc788\uc5c8\ub358 \uac83\uc774\ub2e4. \ub2f9\uc2dc \uc0ac\ub78c\ub4e4\uc740 \ub80c\uc988\uc640 \uac70\uc6b8\uc774 \uc0c1\uc744 \ubc14\uafb8\uac70\ub098 \ub4a4\uc9d1\uc744 \uc218 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc54c\uace0 \uc788\uc5c8\ub2e4. \ub9dd\uc6d0\uacbd\uc5d0\uc11c \uc0c8\ub85c\uc6b4 \uac83\uc774 \ubcf4\uc778\ub2e4\uace0 \uadf8\uac83\uc774 \uace7 \uc2e4\uc81c \ud558\ub298\uc758 \ubaa8\uc2b5\uc774\ub77c\uace0 \uc778\uc815\ub418\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ub3c4\uad6c\uac00 \ub9cc\ub4e0 \ud6a8\uacfc\uc778\uc9c0 \ub300\uc0c1\uc758 \uc131\uc9c8\uc778\uc9c0 \uad6c\ubcc4\ud574\uc57c \ud588\ub2e4. \uad50\uc7ac\ub294 \uac08\ub9b4\ub808\uc624\uac00 \uac00\uae4c\uc774\uc11c \ud655\uc778\ud560 \uc218 \uc788\ub294 \ub300\uc0c1\uc744 \ubc18\ubcf5\ud574\uc11c \ube44\uad50\ud558\uba70 \ub3c4\uad6c\ub97c \uc2e0\ub8b0\ud560 \uadfc\uac70\ub97c \ub9c8\ub828\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uacfc\ud559\uc758 \uc5ed\uc0ac\uc5d0\uc11c \uc911\uc694\ud55c \ub300\ubaa9\uc774\ub2e4. \ub180\ub77c\uc6b4 \uc7a5\uba74\uc744 \ubcf4\uc558\ub2e4\ub294 \uc8fc\uc7a5\ubfd0 \uc544\ub2c8\ub77c \uadf8\uac83\uc744 \uc65c \ubbff\uc744 \uc218 \uc788\ub294\uc9c0\ub3c4 \ubcf4\uc5ec \uc904 \ud544\uc694\uac00 \uc788\uc5c8\ub2e4. \ub9dd\uc6d0\uacbd\uc73c\ub85c \ubcf8 \ub2ec\uc5d0\ub294 \uc0b0\uacfc \uace8\uc9dc\uae30, \uc5ec\ub7ec \uc6b8\ud241\ubd88\ud241\ud55c \ud754\uc801\uc774 \ub098\ud0c0\ub0ac\ub2e4. \uc9c0\uc0c1\uc758 \ubd88\uc644\uc804\ud55c \uc138\uacc4\uc640 \ub2e4\ub978 \uc644\ubcbd\ud55c \ud558\ub298\uc774\ub77c\ub294 \uc0dd\uac01\uc5d0\ub294 \ubd88\ud3b8\ud55c \uad00\ucc30\uc774\uc5c8\ub2e4. \uba40\ub9ac \uc788\ub294 \ucc9c\uccb4\ub3c4 \ub545\ucc98\ub7fc \ubcf5\uc7a1\ud55c \ud45c\uba74\uc744 \uac00\uc9c4\ub2e4\uba74 \ub458 \uc0ac\uc774\uc758 \uacbd\uacc4\ub97c \ub2e4\uc2dc \ubb3c\uc744 \uc218 \uc788\uc5c8\ub2e4. \uac08\ub9b4\ub808\uc624\uac00 \uc5b4\ub450\uc6b4 \ubd80\ubd84\uc744 \ubb3c\uc77c \uc218 \uc788\ub2e4\uace0 \uc0dd\uac01\ud55c \uac83\uc740 \uc624\ub298\uc758 \uc9c0\uc2dd\uacfc \ub2e4\ub974\ub2e4. \uad00\ucc30\uc774 \uc0c8\ub85c\uc6e0\ub2e4\uace0 \ubaa8\ub4e0 \ud574\uc11d\uc774 \uc644\uc131\ub41c \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \ub3c4\uad6c\ub97c \ud1b5\ud574 \uc5bb\uc740 \uc138\ubd80\uac00 \uc624\ub798\ub41c \uc124\uba85\uacfc \ube44\uad50\ub418\uae30 \uc2dc\uc791\ud588\ub2e4\ub294 \uc810\uc774\ub2e4. \uc798 \ubcf8 \uac83\uacfc \uc815\ud655\ud558\uac8c \ub73b\uc744 \ubd99\uc778 \uac83\uc740 \ub2e4\ub978 \ub2e8\uacc4\uc600\ub2e4. \uac08\ub9b4\ub808\uc624\ub294 \ubaa9\uc131 \uc8fc\ubcc0\uc744 \ub3c4\ub294 \ub124 \uc704\uc131\uc744 \ud655\uc778\ud588\ub2e4. \uc774 \ubc1c\uacac\uc740 \ubaa8\ub4e0 \ucc9c\uccb4\uac00 \uc9c0\uad6c\ub9cc\uc744 \uc911\uc2ec\uc73c\ub85c \uc6c0\uc9c1\uc5ec\uc57c \ud55c\ub2e4\ub294 \uc0dd\uac01\uc5d0 \ubb38\uc81c\ub97c \uc81c\uae30\ud588\ub2e4. \uc6c0\uc9c1\uc774\ub294 \ud589\uc131\ub3c4 \uc790\uae30 \uc8fc\uc704\ub97c \ub3c4\ub294 \ucc9c\uccb4\ub97c \uac00\uc9c8 \uc218 \uc788\uc5c8\ub2e4. \uc9c0\uad6c\uac00 \uc6c0\uc9c1\uc774\uba74 \ub2ec\uc774 \ub530\ub77c\uc624\uc9c0 \ubabb\ud560 \uac83\uc774\ub77c\ub294 \ubc18\ub860\ub3c4 \ub2e4\uc2dc \uc0dd\uac01\ud558\uac8c \ud588\ub2e4. \ub2e4\ub9cc \uc774 \uad00\ucc30 \ud558\ub098\ub85c \ud0dc\uc591\uacc4\uc758 \ubaa8\ub4e0 \ubaa8\ud615\uc774 \ub3d9\uc2dc\uc5d0 \ud310\uc815\ub41c \uac83\uc740 \uc544\ub2c8\ub2e4. \ubaa9\uc131 \uc704\uc131\uc740 \ubb34\uc5c7\uc774 \uc9c0\uad6c \uc8fc\uc704\ub97c \ub3c4\ub294\uc9c0\uc5d0 \uad00\ud55c \uc911\uc694\ud55c \uc99d\uac70\uc600\uc9c0\ub9cc, \ub2e4\ub978 \uad00\uce21\uacfc \uc774\ub860\uc758 \ube44\uad50\uac00 \uacc4\uc18d \ud544\uc694\ud588\ub2e4. \ubc1c\uacac\uc758 \uc758\ubbf8\ub97c \ud06c\uac8c \ubcf4\uba74\uc11c\ub3c4 \uadf8\uac83\uc774 \ub2f5\ud55c \uc9c8\ubb38\uc758 \ubc94\uc704\ub97c \ub098\ub204\uc5b4 \uc77d\uc744 \uc218 \uc788\ub2e4. \uae08\uc131\uc740 \ub2ec\ucc98\ub7fc \uc5ec\ub7ec \ubaa8\uc2b5\uc73c\ub85c \ubcf4\uc600\ub2e4. \uad50\uc7ac\ub294 \uac08\ub9b4\ub808\uc624\uac00 \uad00\uce21\ud55c \uae08\uc131\uc758 \uc704\uc0c1 \ubcc0\ud654\uac00 \uae30\uc874 \ud504\ud1a8\ub808\ub9c8\uc774\uc624\uc2a4 \uccb4\uacc4\uc640 \ub9de\uc9c0 \uc54a\uc558\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ubb34\uc5c7\uc774 \uc5b4\ub290 \uc911\uc2ec\uc744 \ub3cc \ub54c \uc5b4\ub5a4 \ubaa8\uc2b5\uc774 \ubcf4\uc5ec\uc57c \ud558\ub294\uc9c0\ub97c \ube44\uad50\ud558\ub294 \uad00\uce21\uc774\uc5c8\ub2e4. \uc774 \uacb0\uacfc\ub294 \ucf54\ud398\ub974\ub2c8\ucfe0\uc2a4\uc758 \uad6c\uc0c1\uc744 \uc9c0\uc9c0\ud558\ub294 \ub370 \uc911\uc694\ud588\ub2e4. \uadf8\ub807\ub2e4\uace0 \ud558\ub8fb\ubc24\uc5d0 \uc9c0\ub3d9\uc124\uc758 \ubaa8\ub4e0 \uc7c1\uc810\uc774 \ub05d\ub0ac\ub2e4\uace0 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uad00\uce21\uc758 \uc885\ub958\uc640 \uac01 \ubaa8\ud615\uc774 \uc124\uba85\ud558\ub294 \ubc94\uc704\uac00 \uc11c\ub85c \ub2ec\ub790\ub2e4. \uacfc\ud559\uc758 \ubcc0\ud654\ub294 \uc0c8\ub85c\uc6b4 \uadf8\ub9bc \ud558\ub098\uac00 \uc61b \uadf8\ub9bc\uc744 \uc989\uc2dc \uc9c0\uc6b0\ub294 \uac83\ubcf4\ub2e4 \ub354 \uae34 \ub17c\uc7c1\uacfc \ud655\uc778\uc758 \uacfc\uc815\uc774\uc5c8\ub2e4. \uac08\ub9b4\ub808\uc624\uc758 \uc8fc\uc7a5\uc740 \uad50\ud68c \uad8c\uc704\uc640 \ucda9\ub3cc\ud588\ub2e4. 1616\ub144\uc5d0\ub294 \ucf54\ud398\ub974\ub2c8\ucfe0\uc2a4\uc758 \uc8fc\uc7a5\uc744 \uc639\ud638\ud558\uc9c0 \ubabb\ud558\uac8c \ud558\ub294 \uacb0\uc815\uc774 \ub098\uc654\uace0, \uac08\ub9b4\ub808\uc624\ub294 \uc774\ud6c4 \uc885\uad50\uc7ac\ud310\uacfc \uac00\ud0dd\uc5f0\uae08\ub3c4 \uacaa\uc5c8\ub2e4. \uad00\uce21 \uacb0\uacfc\ub97c \ud574\uc11d\ud558\ub294 \uc77c\uc740 \ub2f9\uc2dc\uc758 \uc815\uce58\uc640 \uc885\uad50\uc801 \uad8c\uc704\uc5d0\uc11c \ub5a8\uc5b4\uc838 \uc788\uc9c0 \uc54a\uc558\ub2e4. \uc774 \uc5ed\uc0ac\ub97c \uc885\uad50\uc778 \uc804\uccb4\uc640 \uacfc\ud559\uc790 \uc804\uccb4\uc758 \ub2e8\uc21c\ud55c \ub450 \ud3b8 \uc2f8\uc6c0\uc73c\ub85c \uc904\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \uac08\ub9b4\ub808\uc624 \uc790\uc2e0\ub3c4 \uc2e0\uc559\uc744 \uac00\uc9c4 \uc0ac\ub78c\uc774\uc5c8\ub2e4. \ubb34\uc5c7\uc744 \uadfc\uac70\ub85c \uc790\uc5f0\uc744 \uc124\uba85\ud558\uace0 \ub204\uac00 \uadf8 \uc124\uba85\uc744 \uacf5\uc801\uc73c\ub85c \uc778\uc815\ud558\ub294\uc9c0\ub77c\ub294 \uad6c\uccb4\uc801\uc778 \uae34\uc7a5\uc774 \uc788\uc5c8\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 17\uc138\uae30 \ucd08 \uad00\uce21\uc790\ub97c \ub5a0\uc62c\ub9ac\ub294 \uc0c1\uc0c1 \uc18d \uc7a5\uba74\uc774\ub2e4. \uac08\ub9b4\ub808\uc624\uc758 \uc2e4\uc81c \ucd08\uc0c1\uc774\ub098 \ud2b9\uc815 \ub9dd\uc6d0\uacbd, \uad00\uce21\ud55c \ubcc4\uc758 \uc704\uce58\ub97c \uc7ac\ud604\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \ub3c4\uad6c\ub97c \ud558\ub298\ub85c \ub3cc\ub9b0 \ud589\uc704\uc758 \ubd84\uc704\uae30\ub97c \ud45c\ud604\ud588\ub2e4. \uac08\ub9b4\ub808\uc624\uac00 \ubc14\uafbc \uac83\uc740 \ud558\ub298 \uc790\uccb4\uac00 \uc544\ub2c8\ub77c \ud558\ub298\uc744 \uc54c\uc544\ubcf4\ub294 \ubc29\ubc95\uc774\uc5c8\ub2e4. \ub80c\uc988\ub97c \ub9cc\ub4e4\uace0 \uc2e0\ub8b0\ub97c \ud655\uc778\ud558\uba70 \ubcf4\uc774\ub294 \uac83\uacfc \uc124\uba85\uc744 \ube44\uad50\ud588\ub2e4. \ubc24\ud558\ub298\uc758 \uc791\uc740 \ube5b\ub4e4\uc744 \ub2e4\uc2dc \uc77d\uc740 \uc774 \uacfc\uc815\uc740 \uacfc\ud559\uc0ac\uac00 \uc815\ub2f5\uc758 \uc5f0\ud45c\ubfd0 \uc544\ub2c8\ub77c \uc9c8\ubb38\uacfc \uac80\uc99d\uc758 \uc5ed\uc0ac\uc774\uae30\ub3c4 \ud568\uc744 \ubcf4\uc5ec \uc900\ub2e4."}, {"id": "gecko-feet-small-forces", "title": "\ub3c4\ub9c8\ubc40\ubd99\uc774 \u2014 \uc811\ucc29\uc81c \uc5c6\uc774 \ubcbd\uc744 \uac77\ub294 \ubc1c", "summary": "\ub3c4\ub9c8\ubc40\ubd99\uc774 \ubc1c\uc758 \ubbf8\uc138\ud55c \ud138\uacfc \ubd84\uc790 \uc0ac\uc774 \ud798\uc744 \uc5f0\uacb0\ud574 \ubd80\ucc29\uacfc \ub5bc\uc5b4 \ub0b4\uae30\uc758 \uc6d0\ub9ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "Science", "subcategory": "Biology", "url": "stories/gecko-feet-small-forces/index.html", "image": "media/gecko-feet-small-forces.png", "alt": "\uc78e\uc0ac\uadc0 \uc606\uc758 \uc218\uc9c1 \ubcbd\uc5d0 \ubc1c\uc744 \ud3bc\uccd0 \ubd99\uc5b4 \uc788\ub294 \uc791\uc740 \ub3c4\ub9c8\ubc40\ubd99\uc774\uc758 \uc0bd\ud654.", "text": "\ub3c4\ub9c8\ubc40\ubd99\uc774 \u2014 \uc811\ucc29\uc81c \uc5c6\uc774 \ubcbd\uc744 \uac77\ub294 \ubc1c \uc791\uc740 \uc811\ucd09\uc774 \uc544\uc8fc \ub9ce\uc774 \ubaa8\uc774\uba74 \uc0dd\uae30\ub294 \ud798 \ub3c4\ub9c8\ubc40\ubd99\uc774 \ubc1c\uc758 \ubbf8\uc138\ud55c \ud138\uacfc \ubd84\uc790 \uc0ac\uc774 \ud798\uc744 \uc5f0\uacb0\ud574 \ubd80\ucc29\uacfc \ub5bc\uc5b4 \ub0b4\uae30\uc758 \uc6d0\ub9ac\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Biology \uacfc\ud559 \uc791\uc740 \ub3c4\ub9c8\ubc40\ubd99\uc774\uac00 \ub9e4\ub048\ud55c \ubcbd\uc5d0 \ubd99\uc5b4 \uc788\ub2e4. \uc190\ud1b1\uc774 \uac78\ub9b4 \ud2c8\ub3c4 \uc5c6\uc5b4 \ubcf4\uc774\ub294\ub370 \ubc1c\uc744 \uc62e\uae30\uba70 \uc6c0\uc9c1\uc778\ub2e4. \ucc9c\uc7a5\uc5d0\uc11c\ub3c4 \ube44\uc2b7\ud55c \ub2a5\ub825\uc744 \ubcf4\uc774\ub294 \uc885\ub958\uac00 \uc788\ub2e4. \ubc1c\ubc14\ub2e5\uc5d0 \uc811\ucc29\uc81c\uac00 \ubb3b\uc5b4 \uc788\uac70\ub098 \uc791\uc740 \ube68\ud310\uc774 \ub2ec\ub824 \uc788\ub294 \uac83\uc77c\uae4c. \uad50\uc7ac\uc5d0 \uc18c\uac1c\ub41c \uc5f0\uad6c\ub294 \ub2e4\ub978 \ub2f5\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ubc1c\uc758 \uc544\uc8fc \uc791\uc740 \uad6c\uc870\uac00 \ud45c\uba74\uacfc \ub9ce\uc740 \uc811\ucd09\uc744 \ub9cc\ub4e4\uace0, \uac00\uae4c\uc6b4 \uac70\ub9ac\uc5d0\uc11c \uc791\uc6a9\ud558\ub294 \uc791\uc740 \ud798\ub4e4\uc774 \ubaa8\uc778\ub2e4. \ubcbd\uc744 \uac77\ub294 \ub2a5\ub825\uc740 \uac70\ub300\ud55c \ud798 \ud558\ub098\ubcf4\ub2e4 \ub208\uc5d0 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc811\ucd09\uc758 \uc218\uc640 \ubc29\uc2dd\uc5d0 \uad00\ud55c \uc774\uc57c\uae30\ub2e4. OpenStax\ub294 \ub3c4\ub9c8\ubc40\ubd99\uc774\uc758 \ubc1c\uac00\ub77d\uc5d0 \ub9ce\uc740 \ubbf8\uc138\ud55c \ud138\uc774 \uc788\uace0, \uadf8 \ud138\uc774 \ub354 \uc791\uc740 \ub0a9\uc791\ud55c \ub05d\uc73c\ub85c \uac08\ub77c\uc9c4\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc6b0\ub9ac\uac00 \uba40\ub9ac\uc11c \ubcf4\ub294 \ubc1c\ubc14\ub2e5\uc740 \ub9e4\ub048\ud55c \ud55c \uc7a5\uc758 \ud310\uc774 \uc544\ub2c8\ub2e4. \ub9e4\uc6b0 \uc791\uc740 \ud06c\uae30\uc5d0\uc11c \ud45c\uba74\uc744 \ub9cc\ub098\ub294 \uad6c\uc870\uac00 \ubc18\ubcf5\ub418\uc5b4 \uc788\ub2e4. \uc774\ub7f0 \uad6c\uc870\ub294 \ud45c\uba74\uacfc \uc811\ucd09\ud560 \uc218 \uc788\ub294 \ubd80\ubd84\uc744 \ud06c\uac8c \ub298\ub9b0\ub2e4. \ubc1c \uc804\uccb4\uac00 \ubcbd\uc5d0 \ud55c \ubc88 \ub2ff\ub294 \uac83\ucc98\ub7fc \ubcf4\uc5ec\ub3c4 \ubbf8\uc138\ud55c \ub05d\ub4e4\uc740 \ub9ce\uc740 \uc790\ub9ac\uc5d0\uc11c \uc791\uc6a9\ud560 \uc218 \uc788\ub2e4. \ubab8\uc758 \ud06c\uae30\ub9cc \ubcf4\ub294 \uc2dc\uc120\uacfc \uc811\ucd09\uc758 \uc791\uc740 \ud06c\uae30\ub85c \ub0b4\ub824\uac00\ub294 \uc2dc\uc120\uc774 \uc11c\ub85c \ub2e4\ub978 \uc815\ubcf4\ub97c \uc8fc\ub294 \uac83\uc774\ub2e4. \uad50\uc7ac\ub294 \ubd84\uc0b0\ub825\uc774\ub77c\ub294 \ubd84\uc790 \uc0ac\uc774\uc758 \uc778\ub825\uc744 \uc124\uba85\ud55c\ub2e4. \uc804\uc790\uc758 \ubd84\ud3ec\uac00 \uc21c\uac04\uc801\uc73c\ub85c \ub2ec\ub77c\uc9c0\uba74\uc11c \uc774\uc6c3\ud55c \uc785\uc790\uc640\uc758 \ub04c\ub9bc\uc774 \ub098\ud0c0\ub0a0 \uc218 \uc788\ub2e4. \uc6d0\uc790\uc640 \ubd84\uc790\uac00 \ub2e8\ub2e8\ud55c \uad6c\uc2ac\ucc98\ub7fc \uc11c\ub85c \uc804\ud600 \uad00\uacc4\uc5c6\uc774 \ub193\uc5ec \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5ec\uae30\uc11c \uc911\uc694\ud55c \uac83\uc740 \ud55c \uc30d \uc0ac\uc774\uc758 \ud798\uc774 \uc791\ub2e4\ub294 \uc810\uc774\ub2e4. \uc791\uc740 \ud798\uc774\ub77c\ub294 \uc774\uc720\ub85c \uc5b8\uc81c\ub098 \ubb34\uc2dc\ud574\ub3c4 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc544\uc8fc \uac00\uae4c\uc6b4 \uc811\ucd09\uc774 \ucda9\ubd84\ud788 \ub9ce\uc544\uc9c0\uba74 \uc804\uccb4\uc758 \ud6a8\uacfc\uac00 \ucee4\uc9c8 \uc218 \uc788\ub2e4. \ub3c4\ub9c8\ubc40\ubd99\uc774\uc758 \ubc1c\uc740 \uc774 \uc791\uc740 \ud06c\uae30\uc640 \ub9ce\uc740 \uc218\uc758 \ub9cc\ub0a8\uc744 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ubbf8\uc138\ud55c \ud138 \ub05d\ub4e4\uc774 \ubcbd\uacfc \uac00\uae4c\uc774 \uc811\ucd09\ud558\uba74 \ub9ce\uc740 \uc790\ub9ac\uc5d0\uc11c \ubd84\uc790 \uc0ac\uc774\uc758 \ud798\uc774 \uc791\uc6a9\ud55c\ub2e4. \uad50\uc7ac\ub294 \uadf8 \ud569\uc774 \ubab8\uc744 \uc9c0\ud0f1\ud560 \ub9cc\ud07c \ucee4\uc9c8 \uc218 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc811\ucc29\uc81c\ub97c \ubc1c\ub77c \uad73\ud788\ub294 \ubc29\uc2dd\uc774\ub098 \uacf5\uae30\ub97c \ube68\uc544\ub0b4\ub294 \ube68\ud310\uacfc\ub294 \ub2e4\ub978 \uc6d0\ub9ac\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubc1c\uc774 \ub2ff\ub294 \ubaa8\ub4e0 \uacf3\uc5d0\uc11c \uac19\uc740 \ud798\uc744 \ub0b8\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc2e4\uc81c \uc811\ucd09\uc758 \uc0c1\ud0dc\uc640 \ud45c\uba74\uc758 \uc131\uc9c8\uc774 \uc911\uc694\ud558\ub2e4. \uc791\uc6a9\ud560 \uc218 \uc788\ub294 \uad6c\uc870\uac00 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uadf8 \uad6c\uc870\uac00 \ucda9\ubd84\ud788 \uc811\ucd09\ud558\uace0 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub2e4\ub974\ub2e4. \ub2a5\ub825\uc744 \uc124\uba85\ud560 \ub54c\ub3c4 \uc870\uac74\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uad50\uc7ac\ub294 2000\ub144 \ucf08\ub7ec \uc624\ud140 \uc5f0\uad6c\ud300\uc774 \uc11c\ub85c \ub2e4\ub978 \uc131\uc9c8\uc758 \ud45c\uba74\uc5d0\uc11c \ubd80\ucc29\uc744 \ube44\uad50\ud55c \uc5f0\uad6c\ub97c \uc18c\uac1c\ud55c\ub2e4. \uadf9\uc131\uc774 \uc788\ub294 \ud45c\uba74\uacfc \uadf8\ub807\uc9c0 \uc54a\uc740 \ud45c\uba74\uc5d0\uc11c\ub3c4 \uc798 \ubd99\ub294\ub2e4\ub294 \uad00\ucc30\uc740 \ubd84\uc0b0\ub825\uc758 \uc911\uc694\uc131\uc744 \uc124\uba85\ud558\ub294 \uadfc\uac70\uac00 \ub418\uc5c8\ub2e4. \uc778\uc0c1\uc801\uc778 \ub3d9\uc791\uc744 \ubcf4\ub294 \ub370\uc11c \uba48\ucd94\uc9c0 \uc54a\uace0 \uac00\ub2a5\ud55c \uc6d0\uc778\uc744 \uad6c\ubd84\ud558\ub824 \ud55c \uac83\uc774\ub2e4. \uc774 \ub300\ubaa9\uc5d0\uc11c \uc7ac\ubbf8\uc788\ub294 \uac83\uc740 \ub2f5\uc758 \uc774\ub984\ubcf4\ub2e4 \uc9c8\ubb38\uc758 \ubc29\uc2dd\uc774\ub2e4. \uc811\ucc29\uc81c\uc778\uc9c0, \ub2e4\ub978 \ubd84\uc790 \uac04 \uc0c1\ud638\uc791\uc6a9\uc778\uc9c0 \uc124\uba85\uc744 \ub098\ub204\uace0, \uc11c\ub85c \ub2e4\ub978 \uc608\uce21\uc774 \ub098\uc624\ub294 \uc870\uac74\uc5d0\uc11c \ube44\uad50\ud55c\ub2e4. \uc0dd\ubb3c\uc758 \ubb18\uae30\ub97c \uacfc\ud559\uc758 \ubb38\uc81c\ub85c \ubc14\uafb8\ub294 \uc77c\uc5d0\ub294 \uc774\ub7f0 \uc2e4\ud5d8\uc758 \uc124\uacc4\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \ubcbd\uc5d0 \uc544\uc8fc \uc798 \ubd99\uae30\ub9cc \ud55c\ub2e4\uba74 \ub2e4\uc74c \ubc1c\uc744 \uc62e\uae30\uae30 \uc5b4\ub824\uc6b8 \uac83\uc774\ub2e4. \uc2e4\uc81c \ub3d9\ubb3c\uc740 \ubd99\ub294 \uc77c\uacfc \ub5a8\uc5b4\uc9c0\ub294 \uc77c\uc744 \ubc18\ubcf5\ud558\uba70 \uac77\ub294\ub2e4. \uad50\uc7ac\ub294 \ubc1c\ub05d\uacfc \ud45c\uba74 \uc0ac\uc774\uc758 \uac01\ub3c4, \ubc1c\uac00\ub77d\uc758 \uc6c0\uc9c1\uc784\uc774 \uc811\ucd09\uc744 \ubc14\uafb8\ub294 \uc124\uba85\uc744 \uc18c\uac1c\ud55c\ub2e4. \ud798\uc758 \ud06c\uae30\ub9cc \ud0a4\uc6b0\ub294 \uac83\uacfc \ud544\uc694\ud560 \ub54c \uc791\uc6a9\uc744 \ubc14\uafb8\ub294 \uac83\uc740 \ub2e4\ub978 \uacfc\uc81c\ub2e4. \uad6c\uc870\uac00 \ud45c\uba74\uc5d0 \uc5b4\ub5bb\uac8c \ub193\uc774\ub294\uc9c0\uc5d0 \ub530\ub77c \uc804\uccb4\uc758 \ubd80\ucc29 \uc0c1\ud0dc\uac00 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ub3c4\ub9c8\ubc40\ubd99\uc774\uc758 \ub2a5\ub825\uc740 \uac15\ud558\uac8c \ubc84\ud2f0\ub294 \ubc1c\ubfd0 \uc544\ub2c8\ub77c \uc6c0\uc9c1\uc784\uc5d0 \ub9de\ucd94\uc5b4 \uc811\ucd09\uc744 \uc870\uc808\ud558\ub294 \ubc1c\uc758 \uc774\uc57c\uae30\uc774\uae30\ub3c4 \ud558\ub2e4. \uad50\uc7ac\ub294 \ubb3c\uc5d0 \uc798 \uc816\uc9c0 \uc54a\ub294 \ud45c\uba74\uc5d0\uc11c \ub9c8\ub978 \uc870\uac74\uacfc \uc816\uc740 \uc870\uac74\uc758 \ubd80\ucc29\uc744 \ube44\uad50\ud55c \ud6c4\uc18d \uc5f0\uad6c\ub3c4 \uc18c\uac1c\ud55c\ub2e4. \uc774\ub294 \ubaa8\ub4e0 \uc885\ub958\uc758 \uc816\uc740 \ubcbd\uc5d0\uc11c \ud56d\uc0c1 \ub611\uac19\uc774 \ubd99\ub294\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ubb3c\uacfc \ud45c\uba74\uc758 \uc870\ud569, \uc2dc\ud5d8 \uc870\uac74\uc744 \uad6c\ubcc4\ud574\uc57c \ud55c\ub2e4. \uc5b4\ub5a4 \uc5f0\uad6c\uac00 \ud2b9\uc815\ud55c \uc870\uac74\uc5d0\uc11c \uc88b\uc740 \uacb0\uacfc\ub97c \ubcf4\uc600\ub2e4\ub294 \ub9d0\uacfc \uc790\uc5f0\uc758 \ubaa8\ub4e0 \uc0c1\ud669\uc744 \ud574\uacb0\ud588\ub2e4\ub294 \ub9d0\uc740 \ub2e4\ub974\ub2e4. \ub3d9\ubb3c\uc758 \ub2a5\ub825\uc744 \ud765\ubbf8\ub86d\uac8c \uc18c\uac1c\ud560\uc218\ub85d \uadf8 \ubc94\uc704\ub97c \uc9c0\ud0a4\ub294 \uc77c\uc774 \uc911\uc694\ud558\ub2e4. \uc870\uac74\uc774 \ub0a8\uc544 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ubc1c\uacac\uc744 \uc57d\ud558\uac8c \ud558\uae30\ubcf4\ub2e4 \ubb34\uc5c7\uc744 \ub354 \uc54c\uc544\ubcfc\uc9c0 \uc54c\ub824 \uc900\ub2e4. \uc5f0\uad6c\uc790\ub4e4\uc740 \uc774\ub7f0 \ubd80\ucc29 \uad6c\uc870\ub97c \uc774\ud574\ud574 \uc0c8\ub85c\uc6b4 \uc811\ucc29 \uae30\uc220\uc5d0 \ud65c\uc6a9\ud560 \uac00\ub2a5\uc131\uc744 \uc0b4\ud540\ub2e4. \ub048\uc801\ud55c \ubb3c\uc9c8\uc744 \ub354 \ub9ce\uc774 \uc4f0\ub294 \ub300\uc2e0 \ud45c\uba74\uc758 \ubbf8\uc138\ud55c \ubaa8\uc591\uacfc \uc811\ucd09\uc744 \ubc14\uafb8\ub294 \uae38\uc744 \uc0dd\uac01\ud560 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uc790\uc5f0\uc744 \uad00\ucc30\ud558\ub294 \uc77c\uc774 \uc7ac\ub8cc\uc758 \uc124\uacc4\uc640 \uc774\uc5b4\uc9c0\ub294 \ub300\ubaa9\uc774\ub2e4. \uadf8\ub7ec\ub098 \ub3d9\ubb3c\uc758 \uc6d0\ub9ac\ub97c \uc54c\uc558\ub2e4\uace0 \uac19\uc740 \uc131\ub2a5\uc758 \uc81c\ud488\uc774 \ubc14\ub85c \uc644\uc131\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubc18\ubcf5 \uc0ac\uc6a9\uacfc \uba3c\uc9c0, \ud45c\uba74\uc758 \ucc28\uc774 \uac19\uc740 \uc2e4\uc81c \uc870\uac74\uc774 \ub0a8\ub294\ub2e4. \uc0dd\ubb3c\uc758 \ud2b9\uc9d5\uc5d0\uc11c \uc544\uc774\ub514\uc5b4\ub97c \uc5bb\ub294 \uc77c\uacfc \uadf8 \uc544\uc774\ub514\uc5b4\ub97c \uc548\uc815\uc801\uc778 \ubb3c\uac74\uc73c\ub85c \ub9cc\ub4dc\ub294 \uc77c \uc0ac\uc774\uc5d0\ub3c4 \ubcc4\ub3c4\uc758 \uc5f0\uad6c\uc640 \uc2dc\ud5d8\uc774 \ud544\uc694\ud558\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \ubcbd\uc5d0 \ubd99\uc740 \ub3c4\ub9c8\ubc40\ubd99\uc774\ub97c \ud45c\ud604\ud55c \uad00\ucc30 \ubd84\uc704\uae30\uc758 \uadf8\ub9bc\uc774\ub2e4. \uc2e4\uc81c \uac1c\uccb4\uc758 \uc0ac\uc9c4\uc774\ub098 \ubc1c\uac00\ub77d \ubbf8\uc138 \uad6c\uc870\ub97c \ucd2c\uc601\ud55c \ud604\ubbf8\uacbd \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uc774 \uadf8\ub9bc\ub9cc\uc73c\ub85c \ud138\uc758 \uc218\uc640 \uc811\ucd09 \uba74\uc801\uc744 \ud655\uc778\ud560 \uc218\ub294 \uc5c6\ub2e4. \uba40\ub9ac\uc11c\ub294 \uc791\uc740 \ub3d9\ubb3c\uc774 \ubcbd\uc744 \uac77\uace0, \uac00\uae4c\uc6b4 \uc5f0\uad6c\uc5d0\uc11c\ub294 \ubbf8\uc138\ud55c \uad6c\uc870\uc640 \ubd84\uc790 \uc0ac\uc774\uc758 \ud798\uc774 \ub9cc\ub09c\ub2e4. \uc5b4\ub290 \ud55c\ucabd\ub9cc\uc73c\ub85c\ub294 \uc2e0\uae30\ud568\uacfc \uc6d0\ub9ac\ub97c \ud568\uaed8 \ubcf4\uae30 \uc5b4\ub835\ub2e4. \ub3c4\ub9c8\ubc40\ubd99\uc774\uc758 \ubc1c\uc740 \uc791\uc740 \uc791\uc6a9\ub3c4 \ub9ce\uc774 \ubaa8\uc774\uace0 \uc801\uc808\ud558\uac8c \uc870\uc808\ub418\uba74 \ub180\ub77c\uc6b4 \ub2a5\ub825\uc774 \ub420 \uc218 \uc788\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4."}, {"id": "ice-floats-lake-freezes-from-top", "title": "\uc5bc\uc74c \u2014 \ud638\uc218\ub294 \uc65c \uc704\uc5d0\uc11c\ubd80\ud130 \uc5bc\uc5b4 \uac08\uae4c", "summary": "\uaca8\uc6b8 \ud638\uc218\uc758 \uc7a5\uba74\uc5d0\uc11c \ubc00\ub3c4\u00b7\ubd80\ub825\u00b7\ubb3c\uc758 \uc628\ub3c4 \ubcc0\ud654\ub97c \uc5f0\uacb0\ud574 \uc5bc\uc74c\uc774 \ub728\ub294 \uc774\uc720\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "Science", "subcategory": "Physics", "url": "stories/ice-floats-lake-freezes-from-top/index.html", "image": "media/ice-floats-lake-freezes-from-top.png", "alt": "\uaca8\uc6b8 \ud638\uc22b\uac00\uc758 \uc5bc\uc74c \ud45c\uba74\uacfc \uc5b4\ub450\uc6b4 \uc5f4\ub9b0 \ubb3c, \uc8fc\ubcc0 \uac08\ub300\uc640 \ub098\ubb34\ub97c \ud45c\ud604\ud55c \uc0bd\ud654.", "text": "\uc5bc\uc74c \u2014 \ud638\uc218\ub294 \uc65c \uc704\uc5d0\uc11c\ubd80\ud130 \uc5bc\uc5b4 \uac08\uae4c \ubb3c\ubcf4\ub2e4 \uac00\ubcbc\uc6b4 \uc5bc\uc74c\uacfc \uc870\uae08 \ud2b9\ubcc4\ud55c 4\ub3c4 \uaca8\uc6b8 \ud638\uc218\uc758 \uc7a5\uba74\uc5d0\uc11c \ubc00\ub3c4\u00b7\ubd80\ub825\u00b7\ubb3c\uc758 \uc628\ub3c4 \ubcc0\ud654\ub97c \uc5f0\uacb0\ud574 \uc5bc\uc74c\uc774 \ub728\ub294 \uc774\uc720\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Physics \uacfc\ud559 \uaca8\uc6b8 \ud638\uc218\uc758 \ud45c\uba74\uc774 \uc5bc\uc5c8\ub2e4. \uadf8\ub7f0\ub370 \uc5bc\uc74c \uc544\ub798\uc5d0\ub294 \uc5ec\uc804\ud788 \ubb3c\uc774 \uc788\uace0 \uadf8 \uc18d\uc5d0\uc11c \uc0b4\uc544\uac00\ub294 \uc0dd\ubb3c\ub3c4 \uc788\ub2e4. \ub2e8\ub2e8\ud55c \uc5bc\uc74c\uc774 \uc561\uccb4\uc778 \ubb3c \uc704\uc5d0 \ub193\uc778\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub108\ubb34 \uc775\uc219\ud574\uc11c \uc774\uc0c1\ud558\uac8c \ub290\uaef4\uc9c0\uc9c0 \uc54a\ub294\ub2e4. \uac19\uc740 \ubb3c\uc9c8\uc778\ub370 \uad73\uc740 \ucabd\uc774 \uc544\ub798\ub85c \uac00\ub77c\uc549\uc9c0 \uc54a\ub294 \uc774\uc720\ub294 \ubb34\uc5c7\uc77c\uae4c. \uc774 \uc7a5\uba74\uc744 \uc774\ud574\ud558\ub824\uba74 \ub2e8\ub2e8\ud568\uacfc \ubb34\uac8c\ub97c \uc7a0\uc2dc \ub098\ub204\uc5b4 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uac19\uc740 \ubd80\ud53c\uc5d0 \uc5bc\ub9c8\ub098 \ub9ce\uc740 \ubb3c\uc9c8\uc774 \ub4e4\uc5b4 \uc788\ub294\uc9c0, \ubb3c\uc740 \uc2dd\uc744 \ub54c \uc5b4\ub5bb\uac8c \ub2ec\ub77c\uc9c0\ub294\uc9c0\ub97c \uc0b4\ud3b4\ubcf4\uba74 \ud638\uc218\uc758 \uaca8\uc6b8 \ud48d\uacbd\uc774 \uc791\uc740 \uacfc\ud559 \uc774\uc57c\uae30\ub85c \ubc14\ub010\ub2e4. \ub3cc\uba69\uc774\ub294 \uac00\ub77c\uc549\uace0 \ucee4\ub2e4\ub780 \ub098\ubb34\ud1a0\ub9c9\uc740 \ub730 \uc218 \uc788\ub2e4. \ubb3c\uac74 \uc804\uccb4\uac00 \uba87 \ud0ac\ub85c\uadf8\ub7a8\uc778\uc9c0\ubcf4\ub2e4 \uac19\uc740 \ubd80\ud53c\uc758 \ubb3c\uacfc \ube44\uad50\ud588\uc744 \ub54c \uc5b4\ub5a4\uc9c0\uac00 \uc911\uc694\ud558\ub2e4. \ubc00\ub3c4\ub294 \uc9c8\ub7c9\uc744 \ubd80\ud53c\uc640 \uc5f0\uacb0\ud574 \ubcf4\ub294 \uac12\uc774\ub2e4. \ubb3c\uac74\uc758 \ud06c\uae30\uc640 \uc7ac\ub8cc\ub97c \ud568\uaed8 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. OpenStax\ub294 \ubb3c\uc18d\uc758 \ubb3c\uccb4\uac00 \ubc00\uc5b4\ub0b8 \ubb3c\uc758 \ubb34\uac8c\ub9cc\ud07c \uc704\ub85c \ubbf8\ub294 \ud798\uc744 \ubc1b\ub294\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ubd80\ub825\uc774\ub77c\uace0 \ubd80\ub974\ub294 \ud798\uc774\ub2e4. \ub728\ub294 \ubb3c\uccb4\ub294 \uadf8 \ud798\uacfc \uc790\uae30 \ubb34\uac8c\uac00 \uade0\ud615\uc744 \uc774\ub8e8\ub294 \uc790\ub9ac\uc5d0 \ub193\uc778\ub2e4. \uc5bc\uc74c\uc774 \ubb3c\uc5d0 \ub728\ub294 \uc774\uc57c\uae30\uc5d0\ub3c4 \uc774 \ube44\uad50\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \ubcf4\ud1b5\uc758 \uc555\ub825\uc5d0\uc11c \ubb3c\uc774 \uc5bc\uc74c\uc73c\ub85c \ubc14\ub00c\uba74 \ubd84\uc790\ub4e4\uc774 \uc815\ub3c8\ub41c \uad6c\uc870\ub97c \uc774\ub8e8\uba70 \uc561\uccb4\uc77c \ub54c\ubcf4\ub2e4 \uacf5\uac04\uc744 \ub354 \ub113\uac8c \ucc28\uc9c0\ud55c\ub2e4. \ubd84\uc790\uac00 \uc0ac\ub77c\uc9c0\uac70\ub098 \uc0c8 \ubb3c\uc9c8\ub85c \ubc14\ub00c\uc5b4\uc11c \uac00\ubcbc\uc6cc\uc9c0\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uac19\uc740 \uc9c8\ub7c9\uc774 \ub354 \ud070 \ubd80\ud53c\uc5d0 \ub4e4\uc5b4\uac00 \ubc00\ub3c4\uac00 \ub0ae\uc544\uc9c4\ub2e4. \uad50\uc7ac\ub294 \uc5bc\uc74c\uc758 \uacb0\uc815 \uad6c\uc870\uc5d0 \uc561\uccb4\ubcf4\ub2e4 \ube48 \uacf5\uac04\uc774 \ub354 \ub9ce\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ubb3c \ubd84\uc790\ub4e4 \uc0ac\uc774\uc758 \uc218\uc18c \uacb0\ud569\ub3c4 \uc774\ub7f0 \uc131\uc9c8\uacfc \uad00\ub828\ub41c\ub2e4. \ub3c5\uc790\uac00 \ubd84\uc790 \ubaa8\ud615\uc744 \uc678\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub2e8\ub2e8\ud574\uc9c4\ub2e4\ub294 \ubcc0\ud654\uc640 \ub354 \ube7d\ube7d\ud574\uc9c4\ub2e4\ub294 \ubcc0\ud654\uac00 \uc5b8\uc81c\ub098 \uac19\uc740 \ub73b\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\uc774 \ud575\uc2ec\uc774\ub2e4. \ubb3c\ubcf4\ub2e4 \ubc00\ub3c4\uac00 \ub0ae\uc740 \uc5bc\uc74c\uc740 \uc77c\ubd80\ub9cc \uc7a0\uae34 \uc0c1\ud0dc\uc5d0\uc11c\ub3c4 \uc790\uae30 \ubb34\uac8c\uc640 \uade0\ud615\uc744 \uc774\ub8e8\ub294 \ubd80\ub825\uc744 \ubc1b\uc744 \uc218 \uc788\ub2e4. \uadf8\ub798\uc11c \ub098\uba38\uc9c0 \ubd80\ubd84\uc774 \ubb3c \uc704\ub85c \ub098\uc628\ub2e4. \uc5bc\ub9c8\ub098 \uc7a0\uae30\ub294\uc9c0\ub294 \uc5bc\uc74c\uacfc \ubb3c\uc758 \ubc00\ub3c4\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c4\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \uc717\ubd80\ubd84\uc774 \uc804\uccb4\uc758 \uc804\ubd80\uac00 \uc544\ub2cc \uc774\uc720\ub2e4. \uadf8\ub807\ub2e4\uace0 \ubaa8\ub4e0 \ub5a0 \uc788\ub294 \uc5bc\uc74c\uc758 \ubaa8\uc591\uacfc \ube44\uc728\uc774 \ub611\uac19\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ubc14\ub2f7\ubb3c\uacfc \ubbfc\ubb3c\uc758 \uc870\uac74\uc774 \ub2e4\ub974\uace0 \uc5bc\uc74c\uc5d0 \uacf5\uae30\ub098 \ub2e4\ub978 \ubb3c\uc9c8\uc774 \ud3ec\ud568\ub420 \uc218\ub3c4 \uc788\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc77c\ubc18\uc801\uc778 \ubb3c\uacfc \uc5bc\uc74c\uc758 \uae30\ubcf8 \uad00\uacc4\ub97c \uc0b4\ud540\ub2e4. \uc0ac\uc9c4 \ud55c \uc7a5\uc5d0\uc11c \uc815\ud655\ud55c \ubd80\ud53c\ub97c \uc7ac\ub294 \ubb38\uc81c\uc640\ub294 \ub2e4\ub978 \uc124\uba85\uc774\ub2e4. \ub9ce\uc740 \ubb3c\uc9c8\uc740 \uc2dd\uc73c\uba74\uc11c \ubd80\ud53c\uac00 \uc904\uace0 \ubc00\ub3c4\uac00 \ub192\uc544\uc9c4\ub2e4. \uadf8\ub7f0\ub370 \ubcf4\ud1b5 \uae30\uc555\uc758 \ubbfc\ubb3c\uc740 \uc57d 4\ub3c4\uc5d0\uc11c \ubc00\ub3c4\uac00 \uac00\uc7a5 \ub192\ub2e4. \uadf8\ubcf4\ub2e4 \ub354 \ucc28\uac00\uc6cc\uc838 0\ub3c4\uc5d0 \uac00\uae4c\uc6cc\uc9c0\ub294 \uad6c\uac04\uc5d0\uc11c\ub294 \uc624\ud788\ub824 \ubd80\ud53c\uac00 \ub298\uace0 \ubc00\ub3c4\uac00 \ub0ae\uc544\uc9c0\ub294 \ud2b9\uc131\uc774 \uc788\ub2e4. \uc774 \uc791\uc740 \ucc28\uc774\uac00 \ud638\uc218\uc5d0\uc11c \uc911\uc694\ud574\uc9c4\ub2e4. \ud45c\uba74\uc758 \ubb3c\uc774 \uc2dd\uc5b4 \uc57d 4\ub3c4\uac00 \ub418\uba74 \uc544\ub798\ub85c \uac00\ub77c\uc549\uc544 \ub2e4\ub978 \ubb3c\uacfc \uc11e\uc77c \uc218 \uc788\ub2e4. \uc774\ud6c4 \ub354 \ucc28\uac00\uc6cc\uc9c4 \ubb3c\uc740 \uc544\ub798\uc758 \ubb3c\ubcf4\ub2e4 \ubc00\ub3c4\uac00 \ub0ae\uc544 \uc704\ucabd\uc5d0 \ub0a8\uae30 \uc26c\uc6cc\uc9c4\ub2e4. \ucc28\uac11\ub2e4\ub294 \ub9d0 \ud558\ub098\ub9cc\uc73c\ub85c \ud56d\uc0c1 \uc544\ub798\uc5d0 \ub193\uc778\ub2e4\uace0 \uc0dd\uac01\ud558\uba74 \uc774 \uc21c\uc11c\ub97c \ub193\uce5c\ub2e4. \uad50\uc7ac\ub294 \uc774\ub7f0 \uc131\uc9c8 \ub54c\ubb38\uc5d0 \uc5f0\ubabb\uc758 \ud45c\uba74\uc774 \uc5bc \uc218 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub300\uae30\uc640 \uc5f4\uc744 \uc8fc\uace0\ubc1b\ub294 \uc704\ucabd\uc5d0\uc11c \ubb3c\uc774 \ucda9\ubd84\ud788 \ucc28\uac00\uc6cc\uc9c0\uace0 \uc5bc\uc74c\uc774 \uc0dd\uae34\ub2e4. \uc0dd\uae34 \uc5bc\uc74c\ub3c4 \ubb3c \uc704\uc5d0 \ub0a8\ub294\ub2e4. \ubb3c\uc758 \ubc00\ub3c4 \ubcc0\ud654\uc640 \ubd80\ub825\uc774 \ud568\uaed8 \uaca8\uc6b8\uc758 \uce35\uc744 \ub9cc\ub4dc\ub294 \uac83\uc774\ub2e4. \ubb3c\ub860 \uc2e4\uc81c \ud638\uc218\uc758 \uc0c1\ud0dc\ub294 \uae4a\uc774\uc640 \ubc14\ub78c, \ubb3c\uc758 \uc774\ub3d9, \uc5fc\ubd84 \uac19\uc740 \uc870\uac74\uc5d0\ub3c4 \uc601\ud5a5\uc744 \ubc1b\ub294\ub2e4. \ubaa8\ub4e0 \uc5f0\ubabb\uc774 \uaca8\uc6b8 \ub0b4\ub0b4 \ubc14\ub2e5\uae4c\uc9c0 \uc5bc\uc9c0 \uc54a\ub294\ub2e4\uace0 \ubcf4\uc7a5\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc774 \uc124\uba85\uc740 \ubbfc\ubb3c\uc758 \uae30\ubcf8 \uc131\uc9c8\uc774 \uc65c \ud45c\uba74\uc758 \uacb0\ube59\uacfc \uc5f0\uacb0\ub418\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\ub294 \ucd9c\ubc1c\uc810\uc774\ub2e4. \ud45c\uba74\uc758 \uc5bc\uc74c\uc740 \uadf8 \uc544\ub798 \ubb3c\uacfc \ucc28\uac00\uc6b4 \uacf5\uae30 \uc0ac\uc774\uc758 \uc5f4 \uc774\ub3d9\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc900\ub2e4. \uad50\uc7ac\ub294 \uc5bc\uc74c\uce35\uc758 \ub2e8\uc5f4 \ud6a8\uacfc\uc640 \ubb3c\uc758 \ud2b9\uc131 \ub355\ubd84\uc5d0 \uc544\ub798\uc758 \uc561\uccb4 \ud658\uacbd\uc5d0\uc11c \uc218\uc0dd \uc0dd\ubb3c\uc774 \uc0b4\uc544\uac08 \uc218 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ubb3c\uc758 \uc791\uc740 \ubb3c\ub9ac\uc801 \uc131\uc9c8\uc774 \uc0dd\ubb3c\uc758 \uc0dd\ud65c \uc870\uac74\uacfc \ub9cc\ub098\ub294 \ub300\ubaa9\uc774\ub2e4. \ub2e4\ub9cc \uc5bc\uc74c \uc544\ub798\uc5d0 \ubb3c\uc774 \uc788\ub2e4\uace0 \ubaa8\ub4e0 \uc0dd\ubb3c\uc774 \uc548\uc804\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc0b0\uc18c\uc640 \uc218\uc628, \uc11c\uc2dd \ud658\uacbd \ub4f1 \ub2e4\ub978 \uc870\uac74\ub3c4 \ud544\uc694\ud558\ub2e4. \ud55c \uc6d0\ub9ac\uac00 \uc0dd\uc874\uc758 \uc911\uc694\ud55c \uc870\uac74\uc744 \uc124\uba85\ud560 \uc218 \uc788\uc5b4\ub3c4 \uc0dd\ud0dc\uacc4 \uc804\uccb4\ub97c \ub300\uc2e0 \uc124\uba85\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uacfc\ud559\uc758 \uc5f0\uacb0\uc740 \uc774\ub7f0 \ubc94\uc704\ub97c \ud568\uaed8 \ubcfc \ub54c \ub354 \ubd84\uba85\ud574\uc9c4\ub2e4. \uac19\uc740 \ubb3c\uc9c8\uc774 \uc561\uccb4\uc640 \uace0\uccb4\uc5d0\uc11c \ub2e4\ub978 \ubc00\ub3c4\ub97c \uac00\uc9c8 \uc218 \uc788\ub2e4\ub294 \uc810\uc740 \uc77c\uc0c1\uc758 \uc9c1\uac10\uacfc \uc870\uae08 \uc5b4\uae0b\ub09c\ub2e4. \ub2e8\ub2e8\ud55c \uac83\uc740 \ubb34\uac81\uace0 \uc561\uccb4\ub294 \uac00\ubccd\ub2e4\ub294 \ub290\ub08c\uc744 \uc7a0\uc2dc \ub0b4\ub824\ub193\uc544\uc57c \ud55c\ub2e4. \ubb34\uc5c7\uc744 \uac19\uc740 \ubd80\ud53c\ub85c \ube44\uad50\ud558\ub294\uc9c0\uc5d0 \ub530\ub77c \ub2f5\uc774 \ub2ec\ub77c\uc9c0\uae30 \ub54c\ubb38\uc774\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uaca8\uc6b8 \ud638\uc22b\uac00\uc758 \uc5bc\uc74c\uacfc \uc5f4\ub9b0 \ubb3c\uc744 \ud45c\ud604\ud55c \ubd84\uc704\uae30 \uadf8\ub9bc\uc774\ub2e4. \ud2b9\uc815 \ud638\uc218\uc758 \uad00\uce21 \uc0ac\uc9c4\uc774\ub098 \uc218\uc628 \ubd84\ud3ec\ub97c \uce21\uc815\ud55c \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uc5bc\uc74c\uc758 \uc815\ud655\ud55c \ub450\uaed8\uc640 \uc544\ub798 \ubb3c\uc758 \uc0c1\ud0dc\ub97c \uc774 \uadf8\ub9bc\uc5d0\uc11c \ud655\uc778\ud560 \uc218\ub294 \uc5c6\ub2e4. \ud638\uc218\uac00 \uc704\uc5d0\uc11c\ubd80\ud130 \uc5bc\uc5b4 \uac00\ub294 \ud48d\uacbd\uc5d0\ub294 \ubb3c \ubd84\uc790\uc758 \ubc30\uc5f4\uacfc \ubc00\ub3c4, \ubd80\ub825\uacfc \uc5f4\uc758 \uc774\ub3d9\uc774 \ud568\uaed8 \uc788\ub2e4. \ud55c \uac00\uc9c0 \ub2e8\uc5b4\ub85c \ub05d\ub098\ub294 \ud604\uc0c1\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc \uc5ec\ub7ec \uc6d0\ub9ac\uac00 \uc11c\ub85c \uc774\uc5b4\uc9c4\ub2e4. \ub208\uc55e\uc758 \uc870\uc6a9\ud55c \ud45c\uba74 \uc544\ub798\uc5d0\ub3c4 \uacc4\uc18d\ub418\ub294 \ubb3c\uc758 \uc6c0\uc9c1\uc784\uc774 \uc788\ub294 \uac83\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \ucef5\uc758 \uc5bc\uc74c\uc774\ub098 \uaca8\uc6b8 \ubb3c\uac00\ub97c \ub9cc\ub098\uba74 \uc5bc\uc74c\uc774 \ub2e8\ub2e8\ud558\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ubb3c\uc5d0 \ub72c\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ub530\ub85c \uc0dd\uac01\ud574 \ubcf4\uc790. \uac19\uc740 \uc9c8\ub7c9\uc774 \uc5b4\ub5a4 \uacf5\uac04\uc744 \ucc28\uc9c0\ud558\uace0 \uc8fc\ubcc0\uc758 \ubb3c\uacfc \uc5b4\ub5bb\uac8c \uade0\ud615\uc744 \uc774\ub8e8\ub294\uc9c0 \uc9c8\ubb38\ud560 \uc218 \uc788\ub2e4. \uc775\uc219\ud55c \uc5bc\uc74c\uc740 \ubb3c\uc774 \uc5bc\ub9c8\ub098 \ud2b9\ubcc4\ud55c \ubb3c\uc9c8\uc778\uc9c0 \ubcf4\uc5ec \uc8fc\ub294 \uac00\uc7a5 \uac00\uae4c\uc6b4 \ud45c\ubcf8\uc774\ub2e4."}, {"id": "jenner-cowpox-and-vaccination-history", "title": "\uc81c\ub108 \u2014 \uc6b0\uc720 \uc9dc\ub294 \uc0ac\ub78c\ub4e4\uc758 \uacbd\ud5d8\uc774 \ubc31\uc2e0\uc73c\ub85c \uc774\uc5b4\uc9c0\uae30\uae4c\uc9c0", "summary": "\uc778\ub450\ubc95\uc758 \uc120\ud589 \uc5ed\uc0ac\uc640 \uc81c\ub108\uc758 \uc6b0\ub450 \uc811\uc885\uc744 \ub098\ub204\uc5b4 \uc0b4\ud53c\uba70 \uad00\ucc30\u00b7\uc2dc\ud5d8\u00b7\uc5f0\uad6c \uc724\ub9ac\uc758 \ubb38\uc81c\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "Science", "subcategory": "Biology", "url": "stories/jenner-cowpox-and-vaccination-history/index.html", "image": "media/jenner-cowpox-and-vaccination-history.png", "alt": "18\uc138\uae30 \ub9d0 \uc601\uad6d \ub18d\ucd0c\uc744 \ub5a0\uc62c\ub9ac\ub294 \uc758\uc0ac\uc640 \uc6b0\uc720 \uc9dc\ub294 \uc0ac\ub78c\uc774 \ub300\ud654\ud558\ub294 \uc0c1\uc0c1 \uc18d \uc7a5\uba74.", "text": "\uc81c\ub108 \u2014 \uc6b0\uc720 \uc9dc\ub294 \uc0ac\ub78c\ub4e4\uc758 \uacbd\ud5d8\uc774 \ubc31\uc2e0\uc73c\ub85c \uc774\uc5b4\uc9c0\uae30\uae4c\uc9c0 1796\ub144\uc758 \uc2dc\ub3c4\uc640 \uadf8\ubcf4\ub2e4 \uc624\ub798\ub41c \uc608\ubc29\uc758 \uc5ed\uc0ac \uc778\ub450\ubc95\uc758 \uc120\ud589 \uc5ed\uc0ac\uc640 \uc81c\ub108\uc758 \uc6b0\ub450 \uc811\uc885\uc744 \ub098\ub204\uc5b4 \uc0b4\ud53c\uba70 \uad00\ucc30\u00b7\uc2dc\ud5d8\u00b7\uc5f0\uad6c \uc724\ub9ac\uc758 \ubb38\uc81c\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Biology \uacfc\ud559 \ubcd1\uc5d0 \uac78\ub9b0 \ub4a4 \uace0\uce58\ub294 \ubc29\ubc95\uc774 \ub9c8\ub545\uce58 \uc54a\ub358 \uc2dc\ub300\uc5d0\ub294 \ubbf8\ub9ac \ud53c\ud560 \uc218 \uc788\ub294 \uae38\uc774 \ud070 \ud76c\ub9dd\uc774\uc5c8\ub2e4. \ucc9c\uc5f0\ub450\ub294 \uadf8\ub7f0 \uc808\ubc15\ud568\uc744 \ub0b3\uc740 \uc9c8\ubcd1\uc774\uc5c8\ub2e4. \uadf8\ub7f0\ub370 \uc18c\uc640 \uac00\uae4c\uc774 \uc77c\ud558\ub294 \uc0ac\ub78c\ub4e4\uc774 \uacaa\ub294 \ub2e4\ub978 \ubcd1\uc758 \uacbd\ud5d8\uc774 \uc608\ubc29\uc758 \uc0c8\ub85c\uc6b4 \ubc29\ubc95\uacfc \uc5f0\uacb0\ub418\uc5c8\ub2e4. \uc601\uad6d \uc758\uc0ac \uc5d0\ub4dc\uc6cc\ub4dc \uc81c\ub108\ub294 \uc6b0\ub450\ub97c \uc553\uc740 \uc0ac\ub78c\ub4e4\uc774 \ucc9c\uc5f0\ub450\uc5d0 \uc798 \uac78\ub9ac\uc9c0 \uc54a\ub294\ub2e4\ub294 \uad00\ucc30\uc5d0 \uc8fc\ubaa9\ud588\ub2e4. \uc5ec\uae30\uc11c \ucd9c\ubc1c\ud55c 1796\ub144\uc758 \uc2dc\ub3c4\ub294 \ubc31\uc2e0\uc758 \uc5ed\uc0ac\uc5d0\uc11c \uc911\uc694\ud55c \uc7a5\uba74\uc774 \ub418\uc5c8\ub2e4. \ub2e4\ub9cc \ud55c \ucc9c\uc7ac\uac00 \uc544\ubb34 \uc120\ud589 \uc9c0\uc2dd \uc5c6\uc774 \uc608\ubc29\uc744 \ubc1c\uba85\ud55c \uc774\uc57c\uae30\ub85c \uc77d\uc73c\uba74 \uadf8 \uc55e\ub4a4\uc758 \uc0ac\ub78c\uacfc \uc2dc\uac04\uc744 \ub193\uce5c\ub2e4. \uad50\uc7ac\ub294 \ucc9c\uc5f0\ub450\ub97c \ub9c9\uae30 \uc704\ud55c \uc778\ub450\ubc95\uc774 \uc81c\ub108 \uc774\uc804\ubd80\ud130 \uc0ac\uc6a9\ub418\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc911\uad6d\uc744 \ube44\ub86f\ud55c \uc9c0\uc5ed\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc9c4 \uc2dc\ub3c4\uac00 \ub2e4\ub978 \uc9c0\uc5ed\uc73c\ub85c \ud37c\uc84c\ub2e4. \ucc9c\uc5f0\ub450\ub97c \uc553\uc740 \uc0ac\ub78c\uc758 \ubb3c\uc9c8\uc744 \uc774\uc6a9\ud574 \uc608\ubc29\uc744 \uae30\ub300\ud55c \ubc29\uc2dd\uc774\uc5c8\ub2e4. \ubcd1\uc744 \uacaa\uc740 \ub4a4 \ub2e4\uc2dc \uac78\ub9ac\uc9c0 \uc54a\ub294 \ud604\uc0c1\uc5d0 \ub300\ud55c \uacbd\ud5d8\uc774 \ubc30\uacbd\uc5d0 \uc788\uc5c8\ub2e4. \uadf8\ub7ec\ub098 \uc774 \ubc29\ubc95 \uc790\uccb4\uac00 \uac10\uc5fc\uacfc \uc720\ud589\uc744 \uc77c\uc73c\ud0ac \uc704\ud5d8\ub3c4 \uc788\uc5c8\ub2e4. \uc608\ubc29\uc758 \ud544\uc694\uac00 \ucef8\ub2e4\uace0 \uc2dc\ub3c4\ud558\ub294 \ubaa8\ub4e0 \ubc29\ubc95\uc774 \uc548\uc804\ud588\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc81c\ub108\uc758 \uc774\uc57c\uae30\ub294 \uc774\ubbf8 \uc788\ub358 \uc608\ubc29\uc758 \uc5ed\uc0ac\uc640 \uadf8 \uc704\ud5d8 \uc18d\uc5d0\uc11c \ub354 \ub098\uc740 \ubc29\ubc95\uc744 \ucc3e\ub358 \ud750\ub984\uc5d0 \ub193\uc5ec \uc788\ub2e4. \uc6b0\ub450\ub294 \uc18c\uc640 \uc0ac\ub78c \uc0ac\uc774\uc5d0\uc11c \uad00\ub828\ub418\ub294 \uac10\uc5fc\ubcd1\uc73c\ub85c \ucc9c\uc5f0\ub450\uc640\ub294 \ub2e4\ub974\ub2e4. \uad50\uc7ac\ub294 \uc81c\ub108\uac00 \uc6b0\ub450\ub97c \uacaa\uc740 \uc6b0\uc720 \uc9dc\ub294 \uc0ac\ub78c\ub4e4\uc758 \uacbd\ud5d8\uc5d0\uc11c \uac00\uc124\uc744 \uc138\uc6e0\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ube44\uad50\uc801 \uac00\ubcbc\uc6b4 \ub2e4\ub978 \uac10\uc5fc\uc774 \ub354 \uc2ec\uac01\ud55c \ubcd1\uc5d0 \ub300\ud55c \ubcf4\ud638\uc640 \uc5f0\uacb0\ub420 \uc218 \uc788\ub294\uac00\ub77c\ub294 \uc9c8\ubb38\uc774\uc5c8\ub2e4. \uc774\uac83\uc740 \ub2f9\uc2dc \uadf8\uac00 \ubc14\uc774\ub7ec\uc2a4\uc758 \uc720\uc804\uc790\uc640 \uba74\uc5ed \uc138\ud3ec\ub97c \ubaa8\ub450 \uc774\ud574\ud588\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc9c0\uae08\uc758 \uc124\uba85\uacfc \ub2f9\uc2dc\uc758 \uc9c8\ubb38\uc740 \uad6c\ubcc4\ud574\uc57c \ud55c\ub2e4. \uc8fc\ubcc0\uc5d0\uc11c \uad00\ucc30\ud55c \uacbd\ud5d8\uc744 \uc0c8\ub85c\uc6b4 \uc608\ubc29 \ubc29\ubc95\uc758 \uac00\ub2a5\uc131\uc73c\ub85c \uc77d\uc5c8\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud558\ub2e4. \uc77c\uc0c1\uc758 \uc9c0\uc2dd\uc774 \uc758\ud559\uc758 \uc9c8\ubb38\uacfc \ub9cc\ub098\ub294 \uc790\ub9ac\uc600\ub2e4. \uc81c\ub108\ub294 1796\ub144 \uc6b0\ub450\uc758 \ubb3c\uc9c8\uc744 \uc5b4\ub9b0\uc544\uc774\uc5d0\uac8c \uc811\uc885\ud588\ub2e4. \uad50\uc7ac\ub294 \uc544\uc774\uac00 \ube44\uad50\uc801 \uac00\ubcbc\uc6b4 \uc99d\uc0c1\uc744 \ubcf4\uc778 \ub4a4, \uc774\ud6c4 \ucc9c\uc5f0\ub450 \ubb3c\uc9c8\uc5d0 \ub178\ucd9c\ub418\uc5c8\uc744 \ub54c \ucc9c\uc5f0\ub450\ub97c \uc553\uc9c0 \uc54a\uc558\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc81c\ub108\uc5d0\uac8c\ub294 \uc790\uc2e0\uc758 \uac00\uc124\uc744 \ub4b7\ubc1b\uce68\ud558\ub294 \uc911\uc694\ud55c \uacb0\uacfc\uc600\ub2e4. \uadf8\ub7ec\ub098 \uc624\ub298\uc758 \ub3c5\uc790\ub294 \uc774 \uc7a5\uba74\uc744 \uc6a9\uac10\ud55c \uc131\uacf5\ub2f4\uc73c\ub85c\ub9cc \uc77d\uc744 \uc218 \uc5c6\ub2e4. \uc5b4\ub9b0\uc774\ub97c \uc5f0\uad6c\uc5d0 \ucc38\uc5ec\uc2dc\ud0a4\uace0 \uc704\ud5d8\uc5d0 \ub178\ucd9c\ud55c \ud589\ub3d9\uc5d0\ub294 \ub3d9\uc758\uc640 \ubcf4\ud638\ub77c\ub294 \uc911\ub300\ud55c \uc724\ub9ac\uc801 \uc9c8\ubb38\uc774 \uc788\ub2e4. \uc5ed\uc0ac\uc801 \uc131\uacfc\ub97c \uc774\ud574\ud558\ub294 \uc77c\uacfc \uadf8 \uacfc\uc815\uc758 \uc704\ud5d8\uc744 \uc815\ub2f9\ud654\ud558\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \ub2f9\uc2dc\uc758 \ubc29\ubc95\uc744 \ub2e4\uc2dc \ub530\ub77c \ud560 \uc218 \uc788\ub294 \uc808\ucc28\ub85c \uc77d\uc5b4\uc11c\ub294 \uc548 \ub41c\ub2e4. \ubc31\uc2e0 \uc811\uc885\uc744 \ub73b\ud558\ub294 vaccination\uc774\ub77c\ub294 \ub9d0\uc740 \uc18c\ub97c \ub73b\ud558\ub294 \ub77c\ud2f4\uc5b4 vacca\uc640 \uc5f0\uacb0\ub41c\ub2e4. \uc6b0\ub450\ub97c \uc774\uc6a9\ud55c \uc774 \uc5ed\uc0ac\uac00 \uc774\ub984 \uc18d\uc5d0 \ub0a8\uc740 \uac83\uc774\ub2e4. \uc624\ub298\ub0a0 \uc775\uc219\ud55c \uc758\ub8cc \uc6a9\uc5b4 \ub4a4\uc5d0 \ubaa9\uc7a5\uacfc \uc18c, \uc0ac\ub78c\uc758 \uac10\uc5fc \uacbd\ud5d8\uc774 \ub4e4\uc5b4 \uc788\ub2e4\ub294 \uc810\uc774 \ud765\ubbf8\ub86d\ub2e4. \uadf8\ub807\ub2e4\uace0 \ud604\uc7ac\uc758 \ubaa8\ub4e0 \ubc31\uc2e0\uc774 \uc18c\uc5d0\uc11c \uc5bb\uc740 \uac19\uc740 \ubb3c\uc9c8\uc774\ub77c\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc774\ud6c4 \uc5ec\ub7ec \uc9c8\ubcd1\uacfc \ub2e4\uc591\ud55c \ubc29\uc2dd\uc758 \ubc31\uc2e0\uc774 \uac1c\ubc1c\ub418\uc5c8\ub2e4. \uc774\ub984\uc758 \uae30\uc6d0\uc740 \ucd9c\ubc1c\uc810\uc744 \uc54c\ub824 \uc8fc\uc9c0\ub9cc \uc9c0\uae08 \uc874\uc7ac\ud558\ub294 \ubaa8\ub4e0 \ubc29\ubc95\uc744 \ud55c\uaebc\ubc88\uc5d0 \uc124\uba85\ud574 \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \uad50\uc7ac\ub294 \uc6b0\ub450\uc640 \ucc9c\uc5f0\ub450\ub97c \uc77c\uc73c\ud0a4\ub294 \ubc14\uc774\ub7ec\uc2a4\uac00 \uad00\ub828\ub418\uc5b4 \uc788\uc5b4 \uba74\uc5ed \ubc18\uc751\uc774 \ubcf4\ud638\ub85c \uc774\uc5b4\uc9c8 \uc218 \uc788\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc6b0\ub9ac \ubab8\uc774 \ud55c \ubc88 \ub9cc\ub09c \ubcd1\uc6d0\uccb4\uc758 \ud2b9\uc9d5\uc744 \uae30\uc5b5\ud558\uace0 \ub2e4\uc74c\uc758 \uad00\ub828\ub41c \uce68\uc785\uc5d0 \ubc18\uc751\ud558\ub294 \ub2a5\ub825\uc774 \uc911\uc694\ud558\ub2e4. \uc81c\ub108\uc758 \uad00\ucc30\uc740 \ub098\uc911\uc5d0 \ub354 \uc815\uad50\ud55c \uc9c0\uc2dd\uc73c\ub85c \ud574\uc11d\ub420 \uc218 \uc788\uc5c8\ub2e4. \uc774 \ucc28\uc774\ub97c \uc54c\uba74 \uc61b \uc758\uc0ac\uac00 \uc624\ub298\uc758 \uc124\uba85\uc744 \ubaa8\ub450 \uc54c\uace0 \ud589\ub3d9\ud55c \uac83\ucc98\ub7fc \ubb18\uc0ac\ud558\uc9c0 \uc54a\uac8c \ub41c\ub2e4. \uacb0\uacfc\uac00 \uba3c\uc800 \uad00\ucc30\ub418\uace0 \uadf8 \uacb0\uacfc\ub97c \uc774\ud574\ud558\ub294 \uc5b8\uc5b4\uac00 \ub4a4\uc5d0 \ubc1c\uc804\ud560 \uc218\ub3c4 \uc788\ub2e4. \uacfc\ud559\uc758 \uc5ed\uc0ac\ub294 \uc2e4\ucc9c\uacfc \uc124\uba85\uc774 \uc5b8\uc81c\ub098 \uac19\uc740 \ub0a0 \uc644\uc131\ub418\ub294 \uac83\uc740 \uc544\ub2d8\uc744 \ubcf4\uc5ec \uc900\ub2e4. 1796\ub144\uc758 \uc2dc\ub3c4\uac00 \uc758\ubbf8 \uc788\uc5c8\ub2e4\uace0 \uadf8 \ud55c \ubc88\uc73c\ub85c \ubaa8\ub4e0 \uc0ac\ub78c\uc758 \ud6a8\uacfc\uc640 \uc548\uc804\uc131\uc774 \ud655\uc778\ub41c \uac83\uc740 \uc544\ub2c8\ub2e4. \ub354 \ub9ce\uc740 \uacbd\ud5d8\uacfc \uac80\ud1a0, \uc0dd\uc0b0\uacfc \ubcf4\uae09\uc758 \ubb38\uc81c\uac00 \ub4a4\uc5d0 \ub0a8\uc544 \uc788\uc5c8\ub2e4. \uac1c\uc778\uc758 \uad00\ucc30\uc774 \uc0ac\ud68c\uc758 \uc758\ub8cc\ub85c \uc774\uc5b4\uc9c0\ub824\uba74 \uc5ec\ub7ec \ub2e8\uacc4\uac00 \ud544\uc694\ud558\ub2e4. \uad50\uc7ac\ub294 \uc81c\ub108 \uc774\ud6c4 \ud30c\uc2a4\ud1f4\ub974\ub97c \ube44\ub86f\ud55c \uc5f0\uad6c\uc790\ub4e4\uc774 \ub2e4\ub978 \uc9c8\ubcd1\uc758 \uc608\ubc29\uc73c\ub85c \uae38\uc744 \ub113\ud600 \uac14\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ubc31\uc2e0\uc758 \uc5ed\uc0ac\ub294 \ud55c \ubb3c\uc9c8\uc758 \uc131\uacf5\uc744 \uadf8\ub300\ub85c \ubcf5\uc81c\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc9c8\ubcd1\uacfc \ubc29\ubc95\uc5d0 \ub9de\ucd94\uc5b4 \uc0c8\ub85c\uc6b4 \uadfc\uac70\ub97c \uc313\uc544 \uac04 \uacfc\uc815\uc774\uc5c8\ub2e4. \uc720\uba85\ud55c \uc774\ub984\uc740 \uc81c\ub108\uc9c0\ub9cc \ubc30\uacbd\uc5d0\ub294 \uc6b0\uc720\ub97c \uc9dc\ub358 \uc0ac\ub78c\ub4e4\uc758 \uacbd\ud5d8\uacfc \uc774\uc804\uc758 \uc608\ubc29 \uad00\ud589, \uc2dc\ub3c4\uc5d0 \ucc38\uc5ec\ud55c \uc544\uc774\uac00 \uc788\uc5c8\ub2e4. \ubc1c\uacac\uc774 \ud55c \uc0ac\ub78c\uc758 \uba38\ub9ac \uc548\uc5d0\uc11c\ub9cc \uc774\ub8e8\uc5b4\uc9c4 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \uacbd\ud5d8\uc744 \ub204\uac00 \ub4e3\uace0 \uc5b4\ub5a4 \ubb38\uc81c\ub85c \ubc14\uafb8\uc5c8\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uba74 \uc774\uc57c\uae30\uac00 \ub113\uc5b4\uc9c4\ub2e4. \uc774\ub7f0 \uc2dc\uc120\uc740 \uacf5\ub85c\ub97c \uc5c6\uc560\ub824\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uad00\ucc30\ud55c \uc0ac\ub78c\uacfc \uc2e4\ud5d8\ud55c \uc0ac\ub78c, \uc704\ud5d8\uc744 \uac10\uc218\ud55c \uc0ac\ub78c\uc758 \uc790\ub9ac\uac00 \uac19\uc9c0 \uc54a\uc558\uc74c\uc744 \ud568\uaed8 \ubcf4\ub824\ub294 \uac83\uc774\ub2e4. \uacfc\ud559\uc758 \uc131\uacfc\ub97c \uc18c\uc911\ud788 \uc5ec\uae30\ub294 \uc77c\uc740 \uadf8 \uc131\uacfc\ub97c \uac00\ub2a5\ud558\uac8c \ud55c \uad00\uacc4\uc640 \ucc45\uc784\uc744 \uc0b4\ud53c\ub294 \uc77c\uacfc \ud568\uaed8 \uac08 \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 18\uc138\uae30 \ub9d0 \ub18d\ucd0c\uc5d0\uc11c \uc758\uc0ac\uc640 \uc6b0\uc720 \uc9dc\ub294 \uc0ac\ub78c\uc774 \ub300\ud654\ud558\ub294 \uc0c1\uc0c1 \uc18d \uc7a5\uba74\uc774\ub2e4. \uc81c\ub108\uc758 \uc2e4\uc81c \ucd08\uc0c1\uc774\ub098 \uae30\ub85d\ub41c \ub9cc\ub0a8\uc744 \uc7ac\ud604\ud558\uc9c0 \uc54a\uc558\ub2e4. \uc5b4\ub9b0\uc774\uc5d0\uac8c \uc2dc\ud589\ub41c \uc2e4\ud5d8\uc744 \uadf8\ub9b0 \uc790\ub8cc\ub3c4 \uc544\ub2c8\ub2e4. \uc77c\uc0c1\uc758 \uad00\ucc30\uacfc \uc9c8\ubb38\uc758 \uad00\uacc4\ub97c \ud45c\ud604\ud588\ub2e4. \uc81c\ub108\uc758 \uc774\uc57c\uae30\ub97c \uc77d\uace0 \ub098\uba74 \ubc31\uc2e0\uc740 \uc644\uc131\ub41c \uc6d0\ub9ac\ub97c \uc678\uc6b0\ub294 \ub2e8\uc5b4\ubcf4\ub2e4 \uae34 \uc2dc\uac04\uc744 \uac00\uc9c4 \uc774\ub984\uc774 \ub41c\ub2e4. \ubcd1\uc744 \ub9c9\uace0 \uc2f6\uc5c8\ub358 \uc0ac\ub78c\ub4e4\uc758 \ud544\uc694\uc640 \uc55e\uc120 \uad00\ud589, \uc0c8\ub85c\uc6b4 \uc2dc\ud5d8\uacfc \uc724\ub9ac\uc758 \uc9c8\ubb38\uc774 \ud568\uaed8 \ub4e4\uc5b4 \uc788\ub2e4. \uadf8 \uacfc\uc815\uc744 \uc77d\ub294 \uac83\uc774 \ubc1c\uacac\uc744 \ub354 \uae4a\uac8c \uc774\ud574\ud558\ub294 \uacfc\ud559\uc0ac\uc758 \uc990\uac70\uc6c0\uc774\ub2e4."}, {"id": "magnetic-penny", "title": "\ub2ee\uc740 \ub3d9\uc804\uc778\ub370 \uc65c \ud558\ub098\ub9cc \uc790\uc11d\uc5d0 \ubd99\uc744\uae4c", "summary": "\uac19\uc740 \uc0c9\uc758 \uc601\uad6d \ub3d9\uc804\ub3c4 \uc790\uc11d \uc55e\uc5d0\uc11c\ub294 \ub2e4\ub974\uac8c \uc6c0\uc9c1\uc785\ub2c8\ub2e4. \ube44\ubc00\uc740 \uac89\ubaa8\uc2b5\ubcf4\ub2e4 \uc548\ucabd\uc5d0 \uc788\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "Science", "subcategory": "Physics", "url": "stories/magnetic-penny/index.html", "image": "media/magnetic-penny.jpg", "alt": "\uc791\uc740 \uc790\uc11d\uacfc \uad6c\ub9ac\ube5b \uc6d0\ubc18\uc73c\ub85c \uc7ac\ub8cc\uc5d0 \ub530\ub978 \ubc18\uc751\uc744 \uc5f0\uc0c1\uc2dc\ud0a4\ub294 AI \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\ub2ee\uc740 \ub3d9\uc804\uc778\ub370 \uc65c \ud558\ub098\ub9cc \uc790\uc11d\uc5d0 \ubd99\uc744\uae4c \uad6c\ub9ac\ube5b \ud45c\uba74 \uc544\ub798\uc5d0 \uc228\uc5b4 \uc788\ub294 \ub2e4\ub978 \uc7ac\ub8cc \uac19\uc740 \uc0c9\uc758 \uc601\uad6d \ub3d9\uc804\ub3c4 \uc790\uc11d \uc55e\uc5d0\uc11c\ub294 \ub2e4\ub974\uac8c \uc6c0\uc9c1\uc785\ub2c8\ub2e4. \ube44\ubc00\uc740 \uac89\ubaa8\uc2b5\ubcf4\ub2e4 \uc548\ucabd\uc5d0 \uc788\uc2b5\ub2c8\ub2e4. Physics \uacfc\ud559 \uc11c\ub78d\uc5d0\uc11c \ub3d9\uc804\uc744 \uaebc\ub0b4\ub2e4\uac00 \uc790\uc11d\uc5d0 \ud558\ub098\uac00 \ubd99\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud574 \ubcf4\uc790. \uc606\uc5d0 \uc788\ub358 \ub2e4\ub978 \ub3d9\uc804\uc740 \uadf8\ub300\ub85c\ub2e4. \ub458 \ub2e4 \uad6c\ub9ac\ube5b\uc778\ub370 \ubc18\uc751\uc740 \ub2e4\ub974\ub2e4. \uc601\uad6d\uc758 1\ud398\ub2c8\uc640 2\ud39c\uc2a4 \ub3d9\uc804\uc5d0\ub294 \uc2e4\uc81c\ub85c \uc774\ub7f0 \ucc28\uc774\uac00 \uc788\ub2e4. \uc655\ub9bd\uc870\ud3d0\uad6d\uc758 \uc548\ub0b4\uc5d0 \ub530\ub974\uba74, \uac89\uc73c\ub85c \ube44\uc2b7\ud574 \ubcf4\uc5ec\ub3c4 \ub9cc\ub4e4\uc5b4\uc9c4 \uc2dc\uae30\uc5d0 \ub530\ub77c \uc548\ucabd \uc7ac\ub8cc\uac00 \ub2e4\ub974\uae30 \ub54c\ubb38\uc774\ub2e4. \uc608\uc804\uc758 \uc601\uad6d 1\ud398\ub2c8\uc640 2\ud39c\uc2a4 \ub3d9\uc804\uc740 \uad6c\ub9ac\uc640 \uc544\uc5f0, \uc8fc\uc11d\uc744 \uc11e\uc740 \uccad\ub3d9\uc73c\ub85c \ub9cc\ub4e4\uc5c8\ub2e4. \uc655\ub9bd\uc870\ud3d0\uad6d\uc740 1992\ub144 9\uc6d4\ubd80\ud130 \uad6c\ub9ac\ub97c \uc785\ud78c \uac15\ucca0\ub85c \uc7ac\ub8cc\ub97c \ubc14\uafb8\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud45c\uba74\uc740 \uacc4\uc18d \uad6c\ub9ac\ube5b\uc744 \ub760\uc9c0\ub9cc \uc18d\uc5d0\ub294 \uac15\ucca0\uc774 \ub4e4\uc5b4\uac04\ub2e4. \uc774 \uac15\ucca0 \ub54c\ubb38\uc5d0 \uad6c\ub9ac \ub3c4\uae08 \uac15\ucca0 \ub3d9\uc804\uc740 \uc790\uc11d\uc5d0 \ub04c\ub9ac\uace0, \uc774\uc804 \uccad\ub3d9 \ub3d9\uc804\uc740 \uadf8\ub807\uc9c0 \uc54a\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \uc0c9\ub9cc\uc73c\ub85c\ub294 \ucc28\uc774\ub97c \ub193\uce58\uae30 \uc27d\ub2e4. \uc0c8 \uc7ac\ub8cc\uac00 \ub4e4\uc5b4\uac14\ub2e4\uace0 \ub3d9\uc804\uc774 \uac11\uc790\uae30 \uc804\ud600 \ub2e4\ub978 \ubb3c\uac74\ucc98\ub7fc \ubcf4\uc774\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc655\ub9bd\uc870\ud3d0\uad6d\uc758 \ud574\uc124\uc740 \ub450 \uc885\ub958\uc758 \uc0c9\uacfc \ubb34\uac8c, \uc9c0\ub984, \ub514\uc790\uc778\uc774 \uac19\uc558\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \uc775\uc219\ud55c \ubaa8\uc2b5\uc744 \uc774\uc5b4 \uac00\uba74\uc11c \ub0b4\ubd80\uc758 \uad6c\uc131\uc774 \ubc14\ub010 \uac83\uc774\ub2e4. \uc5ec\uae30\uc11c \uc7ac\ubbf8\uc788\ub294 \uc810\uc740 \uc790\uc11d\uc774 \uc6b0\ub9ac\uac00 \ubcf4\ub294 \uad6c\ub9ac\ube5b\uc5d0 \ubc18\uc751\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c\ub294 \ub370 \uc788\ub2e4. \uac89\uc73c\ub85c \ube44\uc2b7\ud55c \ubb3c\uac74\ub3c4 \ubb34\uc5c7\uc73c\ub85c \ub9cc\ub4e4\uc5c8\ub294\uc9c0\uc5d0 \ub530\ub77c \uacb0\uacfc\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \uac19\uc740 \uc0c9\uc758 \uadf8\ub987\uc774 \ubaa8\ub450 \uac19\uc740 \uc7ac\ub8cc\ub294 \uc544\ub2c8\ub4ef, \ub3d9\uc804\uc758 \ud45c\uba74\uc0c9\ub3c4 \uc7ac\ub8cc \uc804\uccb4\ub97c \uc54c\ub824\uc8fc\ub294 \uc774\ub984\ud45c\ub294 \uc544\ub2c8\ub2e4. \uc587\uac8c \uc785\ud78c \uae08\uc18d\uacfc \uadf8 \uc548\ucabd\uc758 \uae08\uc18d\uc774 \uc11c\ub85c \ub2e4\ub978 \uc5ed\ud560\uc744 \ub9e1\uc744 \uc218 \uc788\ub2e4. \uc774 \uc774\uc57c\uae30\ub294 \uc601\uad6d\uc758 \ud574\ub2f9 \ub3d9\uc804\uc744 \ub2e4\ub8ec\ub2e4. \ub098\ub77c\uc640 \uc561\uba74\uc774 \ub2ec\ub77c\uc9c0\uba74 \uc7ac\ub8cc\ub3c4 \ub2ec\ub77c\uc9c0\ubbc0\ub85c, \ubaa8\ub4e0 \ub3d9\uc804\uc774 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ubc18\uc751\ud55c\ub2e4\uace0 \ub113\ud600 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uad6c\ub9ac \ub3c4\uae08\uc774\ub77c\ub294 \uc124\uba85\uc740 \ud45c\uba74\uacfc \ub0b4\ubd80\ub97c \ub098\ub204\uc5b4 \ubcf4\uac8c \ud55c\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \uc0c9\uc774 \ubb3c\uac74 \uc804\uccb4\ub97c \uc774\ub8e8\ub294 \uc7ac\ub8cc\uc640 \uac19\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \uac89\uc5d0\ub294 \uc775\uc219\ud55c \uad6c\ub9ac\ube5b\uc744 \ub450\uace0 \uc548\uc5d0\ub294 \uac15\ucca0\uc744 \uc0ac\uc6a9\ud558\uba74 \uc678\ud615\uc744 \uc54c\uc544\ubcf4\ub294 \uacbd\ud5d8\uacfc \uc790\uc11d\uc5d0 \ubc18\uc751\ud558\ub294 \uc131\uc9c8\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uc7ac\ub8cc\ub97c \uc77d\ub294 \ub370 \uc2dc\uac01\ub9cc\uc774 \uc720\uc77c\ud55c \ub3c4\uad6c\ub294 \uc544\ub2c8\ub2e4. \uadf8\ub807\ub2e4\uace0 \uac15\ucca0\uc774 \ub4e4\uc5b4 \uc788\uc73c\uba74 \uc5b4\ub5a4 \uc870\uac74\uc5d0\uc11c\ub3c4 \uac19\uc740 \uc815\ub3c4\ub85c \ubd99\ub294\ub2e4\uace0 \ud310\ub2e8\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc774 \uae00\uc740 \uc870\ud3d0\uad6d\uc774 \uc124\uba85\ud55c \ub450 \uc7ac\ub8cc\uc758 \ucc28\uc774\ub97c \uc18c\uac1c\ud55c\ub2e4. \uc2e4\uc81c \ub3d9\uc804\uc758 \uc815\ud655\ud55c \uad6c\uc131\uc744 \uc2dd\ubcc4\ud558\ub824\uba74 \ud574\ub2f9 \uc561\uba74\uacfc \uc2dc\uae30\uc758 \uc790\ub8cc\ub3c4 \ud568\uaed8 \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \ubc18\uc751 \ud558\ub098\ub85c \ub098\ub77c\uc640 \uc5f0\ub3c4, \ud1b5\uc6a9 \uc5ec\ubd80\uae4c\uc9c0 \ubaa8\ub450 \ud310\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc0c8 \uc7ac\ub8cc\ub97c \uc37c\uc5b4\ub3c4 \uc0c9\uacfc \uc9c0\ub984, \ubb34\uac8c\uc640 \ub514\uc790\uc778\uc744 \uac19\uac8c \uc720\uc9c0\ud588\ub2e4\ub294 \uc124\uba85\uc740 \ubcc0\ud654\uac00 \ud56d\uc0c1 \uac89\uc73c\ub85c \ub4dc\ub7ec\ub098\ub294 \uac83\uc740 \uc544\ub2d8\uc744 \ubcf4\uc5ec \uc900\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \uc54c\uc544\ubcf4\ub294 \ud45c\uba74\uc744 \uc720\uc9c0\ud558\uba74\uc11c \ub9cc\ub4dc\ub294 \uc870\uac74\uc744 \ubc14\uafb8\ub294 \uc120\ud0dd\uc774\ub2e4. \ub2e4\ub9cc \uc774 \uc720\uc0ac\ud568\uc744 \uadfc\uac70\ub85c \ub450 \ubb3c\uac74\uc774 \ubb3c\ub9ac\uc801\uc73c\ub85c \ubaa8\ub4e0 \uc810\uc5d0\uc11c \ub3d9\uc77c\ud558\ub2e4\uace0 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub3d9\uc804\uc740 \ubc18\ubcf5\ud574\uc11c \uc190\uc5d0 \uc950\ub294 \ubb3c\uac74\uc774\ub77c \ud070 \ubaa8\uc591\uc774 \uacc4\uc18d \uc774\uc5b4\uc9c0\ub294 \uc77c\uc774 \uc911\uc694\ud558\uac8c \ub290\uaef4\uc9c4\ub2e4. \uadf8 \ub4a4\uc758 \uae08\uc18d \uad6c\uc131\uc740 \ud3c9\uc18c\uc5d0 \ub35c \uc758\uc2dd\ud560 \uc218 \uc788\ub2e4. \uc790\uc11d\uc744 \ud568\uaed8 \ub193\uc558\uc744 \ub54c \ube44\ub85c\uc18c \ub2e4\ub978 \uc131\uc9c8\uc774 \ub4dc\ub7ec\ub098\ub294 \uac83\uc774\ub2e4. \uc775\uc219\ud55c \ubb3c\uac74\uc744 \uc7ac\ub8cc\uc758 \uc9c8\ubb38\uc73c\ub85c \ub2e4\uc2dc \uc77d\uc73c\uba74 \uac89\ubaa8\uc2b5\uc5d0\uc11c \uc9c0\ub098\ucce4\ub358 \ubcc0\ud654\uac00 \ubcf4\uc778\ub2e4. 1992\ub144 9\uc6d4\uc774\ub77c\ub294 \uc2dc\uc810\uc740 \uc870\ud3d0\uad6d\uc774 \uc124\uba85\ud558\ub294 \uc7ac\ub8cc \uc804\ud658\uc758 \uae30\uc900\uc774\ub2e4. \ud558\uc9c0\ub9cc \uac1c\ubcc4 \ub3d9\uc804\uc744 \uc5b4\ub5a4 \uc7ac\ub8cc\ub85c \ub9cc\ub4e4\uc5c8\ub294\uc9c0 \uc790\uc138\ud788 \ud655\uc778\ud558\ub824\uba74 \ud574\ub2f9 \uc790\ub8cc\ub97c \ub354 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc561\uba74\uacfc \uc885\ub958\uac00 \ub2ec\ub77c\uc838\ub3c4 \uac19\uc740 \uc2dc\uc810\uc758 \uaddc\uce59\uc744 \ubb34\uc870\uac74 \uc801\uc6a9\ud558\ub294 \ubc29\uc2dd\uc740 \ud53c\ud558\ub294 \ud3b8\uc774 \uc815\ud655\ud558\ub2e4. \uc774 \uc774\uc57c\uae30\ub294 \ubaa8\ub4e0 \ub3d9\uc804\uc744 \uac00\ub974\ub294 \uc138\uacc4 \uacf5\ud1b5\ud45c\uac00 \uc544\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc790\uc11d\uc5d0 \ubd99\uc9c0 \uc54a\ub294\ub2e4\uace0 \uadf8 \ub3d9\uc804\uc744 \uace7 \uac00\uc9dc\ub77c\uace0 \ubd80\ub97c \uc218\ub294 \uc5c6\ub2e4. \uc815\uc2dd \ub3d9\uc804\ub3c4 \uc7ac\ub8cc\uac00 \ub2e4\ub97c \uc218 \uc788\ub2e4\ub294 \uac83\uc774 \ubc14\ub85c \uc774 \uc0ac\ub840\uc758 \ucd9c\ubc1c\uc810\uc774\ub2e4. \ubb3c\uac74\uc758 \uc9c4\uc704\uc640 \uc790\uc131\uc774\ub77c\ub294 \ud55c \uac00\uc9c0 \uc131\uc9c8\uc740 \ub2e4\ub978 \uc9c8\ubb38\uc774\ub2e4. \uad00\ucc30 \uacb0\uacfc\uc5d0\uc11c \ub108\ubb34 \uba3c \uacb0\ub860\uc73c\ub85c \ub098\uc544\uac00\uc9c0 \uc54a\uc73c\uba74 \uac04\ub2e8\ud55c \ube44\uad50\ub3c4 \ub354 \uc7ac\ubbf8\uc788\ub294 \ud0d0\uad6c\uac00 \ub41c\ub2e4. \ub3d9\uc804 \ub450 \uac1c\ub97c \ub098\ub780\ud788 \uc0dd\uac01\ud574 \ubcf4\uba74 \uc22b\uc790\uc640 \uadf8\ub9bc\uc740 \ub2ee\uc558\ub294\ub370 \uc548\ucabd\uc758 \uc7ac\ub8cc\ub294 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uadf8 \ucc28\uc774\uac00 \uc790\uc11d\uacfc\uc758 \uad00\uacc4\uc5d0\uc11c \ub4dc\ub7ec\ub09c\ub2e4. \uc77c\uc0c1\uc5d0\uc11c \uc7ac\ub8cc\uc758 \uc131\uc9c8\uc740 \ub208\uc5d0 \ubcf4\uc774\ub294 \uc774\ub984\ubcf4\ub2e4 \ud589\ub3d9\uc73c\ub85c \ud655\uc778\ub418\uae30\ub3c4 \ud55c\ub2e4. \ub2e4\ub9cc \uc2e4\uc81c \ubb3c\uac74\uc744 \ud6fc\uc190\ud558\uac70\ub098 \uc798\ub77c \ubcf4\uc544\uc57c \ud55c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uacf5\uc2dd \uc790\ub8cc\uc640 \ube44\ud30c\uad34\uc801\uc778 \uad00\ucc30\ub85c\ub3c4 \uc774\ud574\ud560 \uc218 \uc788\ub294 \ubd80\ubd84\uc774 \uc788\ub2e4. \uae08\uc18d\uc774\ub77c\ub294 \ud55c \ubc94\uc8fc \uc548\uc5d0\ub3c4 \uc11c\ub85c \ub2e4\ub978 \uc131\uc9c8\uc774 \uc788\ub2e4\ub294 \uc810\uc744 \uae30\uc5b5\ud574 \ubcf4\uc790. \uc791\uc740 \ub3d9\uc804\uc740 \ud654\ud3d0\uc774\uba74\uc11c \uc7ac\ub8cc\ub97c \uc120\ud0dd\ud574 \ub9cc\ub4e0 \uc81c\ud488\uc774\ub2e4. \uac00\uaca9\uacfc \uc561\uba74\uc73c\ub85c\ub9cc \ubcf4\ub358 \ubb3c\uac74\uc744 \ud45c\uba74\uacfc \ub0b4\ubd80\ub85c \ub098\ub204\uc5b4 \ubcf4\ub294 \uc21c\uac04, \uc870\ud3d0\uc758 \uc5ed\uc0ac\uac00 \uc190\ub05d\uc758 \uacfc\ud559\uacfc \ub9cc\ub09c\ub2e4. \ub2ee\uc558\ub2e4\ub294 \uccab\uc778\uc0c1\uc740 \uc9c8\ubb38\uc758 \ub05d\uc774 \uc544\ub2c8\ub77c \uc2dc\uc791\uc774 \ub420 \uc218 \uc788\ub2e4. \ub3d9\uc804\uc5d0\ub294 \ucd08\uc0c1\uacfc \uc22b\uc790\ub9cc \uc788\ub294 \uac83 \uac19\uc9c0\ub9cc, \uc7ac\ub8cc\uc758 \uc5ed\uc0ac\ub3c4 \ub4e4\uc5b4 \uc788\ub2e4. \uc190\uc5d0 \uc954 \ub3c8\uc774 \uc5b8\uc81c \uc5b4\ub5a4 \uae08\uc18d\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc84c\ub294\uc9c0 \uc0b4\ud53c\uba74 \ud45c\uba74\uc758 \uadf8\ub9bc\uacfc\ub294 \ub2e4\ub978 \uc774\uc57c\uae30\ub97c \ub9cc\ub098\uac8c \ub41c\ub2e4. \uc790\uc11d\uc5d0 \ubd99\uc740 \ub3d9\uc804\uacfc \ubd99\uc9c0 \uc54a\uc740 \ub3d9\uc804\uc744 \ub098\ub780\ud788 \ub5a0\uc62c\ub9ac\uba74, \ubcf4\uc774\ub294 \ubaa8\uc2b5\uacfc \uc2e4\uc81c \uad6c\uc131\uc774 \ub2e4\ub97c \uc218 \uc788\ub2e4\ub294 \ub9d0\uc774 \uaf64 \uad6c\uccb4\uc801\uc73c\ub85c \ub290\uaef4\uc9c4\ub2e4. \uc5b4\ub824\uc6b4 \uacf5\uc2dd\ubcf4\ub2e4 \uc190\ubc14\ub2e5\uc5d0 \uc62c\ub77c\uc624\ub294 \ubb3c\uac74\uc774 \uba3c\uc800 \uc774\ud574\ub97c \ub3d5\ub294\ub2e4. \ub2e4\uc74c\uc5d0 \uad6c\ub9ac\ube5b \ub3d9\uc804\uc744 \ubcf4\uac8c \ub41c\ub2e4\uba74 \uac89\uc758 \uc0c9\ub9cc\uc73c\ub85c \uc18d\uae4c\uc9c0 \ub2e4 \uc548\ub2e4\uace0 \uc0dd\uac01\ud558\uc9c0 \uc54a\uc544\ub3c4 \uc88b\uaca0\ub2e4. \uc775\uc219\ud55c \ud45c\uba74 \uc544\ub798\uc5d0\uc11c \uc7ac\ub8cc\ub294 \uc774\ubbf8 \ub2e4\ub978 \uc2dc\ub300\ub85c \ub118\uc5b4\uac14\uc744\uc9c0\ub3c4 \ubaa8\ub978\ub2e4."}, {"id": "marie-curie-life-and-discovery", "title": "\ub9c8\ub9ac \ud034\ub9ac\uc758 \uc0dd\uc560 \u2014 \ubc18\uc9dd\uc774\ub294 \ubc1c\uacac \ub4a4\uc758 \uc624\ub798\ub41c \uc2e4\ud5d8\uc2e4", "summary": "\uc720\ud559\uacfc \uacf5\ub3d9 \uc5f0\uad6c, \ub450 \ubc88\uc758 \ub178\ubca8\uc0c1\uacfc \uc804\uc2dc \ud65c\ub3d9\uc744 \ud1b5\ud574 \ubc1c\uacac\uc744 \uc774\uc5b4 \uac00\ub294 \uc0b6\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "Science", "subcategory": "Physics", "url": "stories/marie-curie-life-and-discovery/index.html", "image": "media/marie-curie-life-and-discovery.jpg", "alt": "\ud30c\ub9ac \ud034\ub9ac \uc5f0\uad6c\uc18c\uc758 \uc2e4\ud5d8\uc2e4\uc5d0\uc11c \uc7a5\ube44 \uacc1\uc5d0 \uc549\uc544 \uc788\ub294 \ub9c8\ub9ac \ud034\ub9ac\uc758 \uc61b \uc0ac\uc9c4.", "text": "\ub9c8\ub9ac \ud034\ub9ac\uc758 \uc0dd\uc560 \u2014 \ubc18\uc9dd\uc774\ub294 \ubc1c\uacac \ub4a4\uc758 \uc624\ub798\ub41c \uc2e4\ud5d8\uc2e4 \ubc14\ub974\uc0e4\ubc14\uc758 \ubc30\uc6c0\uc5d0\uc11c \ud30c\ub9ac\uc758 \uc5f0\uad6c\uc640 \uc804\uc7a5\uc758 X\uc120 \ucc28\ub7c9\uae4c\uc9c0 \uc720\ud559\uacfc \uacf5\ub3d9 \uc5f0\uad6c, \ub450 \ubc88\uc758 \ub178\ubca8\uc0c1\uacfc \uc804\uc2dc \ud65c\ub3d9\uc744 \ud1b5\ud574 \ubc1c\uacac\uc744 \uc774\uc5b4 \uac00\ub294 \uc0b6\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Physics \uacfc\ud559 \uc2e4\ud5d8\uc2e4\uc758 \uc0ac\uc9c4 \uc18d \ub9c8\ub9ac \ud034\ub9ac\ub294 \uc7a5\ube44\uc5d0 \ub458\ub7ec\uc2f8\uc5ec \uc788\ub2e4. \uc6b0\ub9ac\uc5d0\uac8c \uc775\uc219\ud55c \uac83\uc740 \ub178\ubca8\uc0c1\uc744 \ub450 \ubc88 \ubc1b\uc740 \uacfc\ud559\uc790\uc758 \uc774\ub984\uc774\uc9c0\ub9cc, \uc0ac\uc9c4\uc740 \uc0c1\ubcf4\ub2e4 \uc77c\uc744 \uba3c\uc800 \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \uce21\uc815\ud558\uace0 \uc815\ub9ac\ud558\uace0 \ub2e4\uc2dc \ud655\uc778\ud558\ub294 \uc2dc\uac04\uc774 \ubc1c\uacac\uc758 \ud55c\uac00\uc6b4\ub370 \uc788\uc5c8\uae30 \ub54c\ubb38\uc774\ub2e4. \uadf8\ub294 1867\ub144\uc5d0 \ud0dc\uc5b4\ub098 1934\ub144\uc5d0 \uc138\uc0c1\uc744 \ub5a0\ub0ac\ub2e4. \ubc14\ub974\uc0e4\ubc14\uc5d0\uc11c \uacf5\ubd80\ud558\ub358 \uccad\ub144\uc774 \ud30c\ub9ac\uc758 \uc5f0\uad6c\uc790\uac00 \ub418\uace0 \uc804\uc7c1 \uc911\uc5d0\ub294 X\uc120 \uc7a5\ube44\ub97c \uc2e4\uc740 \ucc28\ub7c9\uc744 \uc6c0\uc9c1\uc774\ub294 \uc77c\uc5d0\ub3c4 \ub098\uc120\ub2e4. \ud55c \ubc88\uc758 \ucc9c\uc7ac\uc801\uc778 \uc21c\uac04\ubcf4\ub2e4 \uadf8 \uc5ec\ub7ec \uc804\ud658\uc744 \ub530\ub77c\uac00 \ubcf4\uba74 \uc0b6\uc758 \ud3ed\uc774 \ubcf4\uc778\ub2e4. \ub9c8\ub9ac\uc758 \uc6d0\ub798 \uc774\ub984\uc740 \ub9c8\ub9ac\uc544 \uc2a4\ud06c\uc6cc\ub3c4\ud504\uc2a4\uce74\ub2e4. \ud3f4\ub780\ub4dc\uc758 \uad50\uc0ac \uc9d1\uc548\uc5d0\uc11c \uc790\ub790\uace0 \ubc30\uc6c0\uc5d0 \ub300\ud55c \uad00\uc2ec\ub3c4 \ucef8\ub2e4. \uadf8\ub7ec\ub098 \uc6d0\ud558\ub294 \uacf5\ubd80\ub97c \ubc14\ub85c \uc2dc\uc791\ud560 \uc218 \uc788\ub294 \uc870\uac74\uc774 \ub298 \uac16\ucd94\uc5b4\uc838 \uc788\uc9c0\ub294 \uc54a\uc558\ub2e4. \uc77c\ud558\uace0 \ub3c8\uc744 \ub9c8\ub828\ud558\uba70 \uc55e\uc73c\ub85c\uc758 \ud559\uc5c5\uc744 \uc900\ube44\ud558\ub294 \uc2dc\uac04\uc774 \ud544\uc694\ud588\ub2e4. \uc790\uc804\uc801 \uae30\ub85d\uc5d0\ub294 \uac00\uc815\uad50\uc0ac\ub85c \uc9c0\ub0b4\uba74\uc11c\ub3c4 \uacf5\ubd80\ub97c \uc774\uc5b4 \uac00\ub358 \uc0dd\ud65c\uc774 \ub098\uc628\ub2e4. \ub4a4\uc758 \uba85\uc131\uc744 \uc54c\uace0 \uc77d\uc73c\uba74 \uc7a0\uc2dc \uac70\uccd0 \uac04 \uc900\ube44 \uae30\uac04\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc, \ub2f9\uc2dc\uc5d0\ub294 \uc5b8\uc81c \uae30\ud68c\uac00 \uc5f4\ub9b4\uc9c0 \ud655\uc2e4\ud558\uc9c0 \uc54a\uc740 \uc0b6\uc774\uc5c8\ub2e4. \ud559\ubb38\uc801 \uc5f4\uc815\uacfc \uc0dd\ud65c\ube44\uc758 \ubb38\uc81c\ub294 \uc11c\ub85c \ub2e4\ub978 \uc138\uacc4\uc5d0 \ub193\uc5ec \uc788\uc9c0 \uc54a\uc558\ub2e4. 1891\ub144 \uadf8\ub294 \ud30c\ub9ac\uc5d0 \uac00\uc11c \uacf5\ubd80\ub97c \uc2dc\uc791\ud55c\ub2e4. \uc0c8\ub85c\uc6b4 \uc5b8\uc5b4\uc640 \ub3c4\uc2dc, \ube60\ub4ef\ud55c \uc0dd\ud65c\uc744 \uac10\ub2f9\ud558\uba70 \ubb3c\ub9ac\ud559\uacfc \uc218\ud559\uc744 \ubc30\uc6e0\ub2e4. \ub0af\uc120 \uacf3\uc5d0 \ub3c4\ucc29\ud588\ub2e4\ub294 \uc7a5\uba74\uc73c\ub85c \ub05d\ub0b4\uae30\ubcf4\ub2e4, \uc218\uc5c5\uc744 \ub530\ub77c\uac00\uace0 \uc0dd\ud65c\uc744 \uafb8\ub9ac\ub294 \ud558\ub8e8\uac00 \uacc4\uc18d\ub418\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud558\uba74 \uc720\ud559\uc758 \ubb34\uac8c\uac00 \ub354 \uad6c\uccb4\uc801\uc774\ub2e4. \uc774 \uc2dc\uae30\uc758 \ub9c8\ub9ac\ub97c \uc774\ubbf8 \uc704\ub300\ud55c \ubc1c\uacac\uc744 \uc55e\ub454 \uc601\uc6c5\uc73c\ub85c\ub9cc \ubcfc \ud544\uc694\ub294 \uc5c6\ub2e4. \ubb34\uc5c7\uc744 \uc5f0\uad6c\ud560\uc9c0 \ucc3e\uace0 \ud544\uc694\ud55c \ub3c4\uad6c\uc640 \uae30\ucd08\ub97c \ubc30\uc6b0\ub294 \ud559\uc0dd\uc774\uc5c8\ub2e4. \uc774\ud6c4\uc758 \uacf5\ub3d9 \uc5f0\uad6c\ub3c4 \uadf8\ub7f0 \ubc30\uc6c0\uacfc \ub9cc\ub0a8 \uc18d\uc5d0\uc11c \uac00\ub2a5\ud574\uc84c\ub2e4. \ud53c\uc5d0\ub974 \ud034\ub9ac\uc640\uc758 \uad00\uacc4\uc5d0\ub294 \uacb0\ud63c\uacfc \uac00\uc871\ubfd0 \uc544\ub2c8\ub77c \uc2e4\ud5d8\uacfc \ub17c\uc758\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \ud53c\uc5d0\ub974\ub294 \uc774\ubbf8 \uc5f0\uad6c \uacbd\ud5d8\uc744 \uac00\uc9c4 \ubb3c\ub9ac\ud559\uc790\uc600\uace0, \ub9c8\ub9ac\ub294 \uc790\uae30 \uc5f0\uad6c \ubb38\uc81c\ub97c \uc138\uc6cc \ub098\uac14\ub2e4. \ub450 \uc0ac\ub78c\uc740 \uac01\uc790\uc758 \ub2a5\ub825\uacfc \uc791\uc5c5\uc744 \uacf5\ub3d9\uc758 \ud0d0\uad6c\uc5d0 \uc5f0\uacb0\ud588\ub2e4. \ub9c8\ub9ac\ub294 \ub0a8\ud3b8\uc758 \uc774\ub984\uc744 \uc54c\ub9ac\ub294 \uc774\uc57c\uae30 \uc18d \uc870\uc218\ub9cc\ub3c4 \uc544\ub2c8\uace0, \ub2e4\ub978 \uc0ac\ub78c\uc758 \ub3c4\uc6c0 \uc5c6\uc774 \ubaa8\ub4e0 \uac83\uc744 \uc774\ub8e8\uc5b4 \ub0b8 \uace0\ub9bd\ub41c \ucc9c\uc7ac\ub9cc\ub3c4 \uc544\ub2c8\ub2e4. \uc5f0\uad6c \uc8fc\uc81c\uc758 \uc120\ud0dd\uacfc \uce21\uc815, \ud611\ub825\uc758 \ubc29\uc2dd\uc774 \uc5b4\ub5bb\uac8c \uc774\uc5b4\uc84c\ub294\uc9c0\ub97c \ubcf4\uba74 \uc0ac\ub78c\uc774 \ud568\uaed8 \uc77c\ud558\uba70 \ubc1c\uacac\uc744 \ud0a4\uc6b0\ub294 \uacfc\uc815\uc774 \ub4dc\ub7ec\ub09c\ub2e4. \ubca0\ud06c\ub810\uc774 \uc5f0\uad6c\ud55c \uc6b0\ub77c\ub284\uc758 \ubc29\ucd9c \ud604\uc0c1\uc744 \uacc4\uae30\ub85c \ub9c8\ub9ac\ub294 \uad00\ub828 \ubb3c\uc9c8\uc744 \uc0b4\ud3c8\ub2e4. \uc5b4\ub5a4 \uad11\uc11d\uc758 \ud6a8\uacfc\uac00 \uc6b0\ub77c\ub284\ub9cc\uc73c\ub85c \uc124\uba85\ud558\uae30\uc5d0 \uc9c0\ub098\uce58\uac8c \uac15\ud558\ub2e4\ub294 \uc810\uc774 \uc0c8\ub85c\uc6b4 \uc9c8\ubb38\uc774 \ub41c\ub2e4. \uc774\ubbf8 \uc54c\ub824\uc9c4 \uc131\ubd84\uc73c\ub85c \ucda9\ubd84\ud558\uc9c0 \uc54a\ub2e4\uba74 \uadf8 \uc548\uc5d0 \ub2e4\ub978 \ubb3c\uc9c8\uc774 \uc788\ub294 \uac83\uc740 \uc544\ub2d0\uae4c. 1898\ub144\uc5d0\ub294 \ud3f4\ub85c\ub284\uacfc \ub77c\ub4d0\uc758 \uc874\uc7ac\ub97c \uc54c\ub9ac\ub294 \uc5f0\uad6c\uac00 \uc774\uc5b4\uc84c\ub2e4. \ud3f4\ub85c\ub284\uc774\ub77c\ub294 \uc774\ub984\uc5d0\ub294 \uace0\ud5a5 \ud3f4\ub780\ub4dc\uac00 \ub2f4\uaca8 \uc788\ub2e4. \uc774\ub984 \ubd99\uc774\uae30\ub294 \ub0ad\ub9cc\uc801\uc778 \uc7a5\uc2dd\ub9cc\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \ubc1c\uacac\uc744 \ubb34\uc5c7\uc73c\ub85c \uc2dd\ubcc4\ud560\uc9c0 \uc815\ud558\uba74\uc11c \ud55c \uc5f0\uad6c\uc790\uc758 \uac1c\uc778\uc801\u00b7\uc5ed\uc0ac\uc801 \ubc30\uacbd\ub3c4 \ud568\uaed8 \ub0a8\ub294 \uc77c\uc774\ub2e4. \uc874\uc7ac\ub97c \ucd94\uc815\ud558\uace0 \ubc1c\ud45c\ud558\ub294 \uac83\uacfc \ucda9\ubd84\ud788 \ubd84\ub9ac\ud558\uc5ec \uc131\uc9c8\uc744 \ud655\uc778\ud558\ub294 \uac83\uc740 \uac19\uc740 \ub2e8\uacc4\uac00 \uc544\ub2c8\ub2e4. \ub9ce\uc740 \uc7ac\ub8cc\ub97c \ucc98\ub9ac\ud558\uace0 \ubc18\ubcf5\ud574\uc11c \ubd84\ub9ac\uc640 \uce21\uc815\uc744 \ud574\uc57c \ud588\ub2e4. \uc790\uc804\uc801 \uae30\ub85d\uc740 \uc774\ub7f0 \uc791\uc5c5\uc5d0 \ub4e4\uc5b4\uac04 \ubb3c\ub9ac\uc801\uc778 \uc218\uace0\uc640 \uc5f4\uc545\ud55c \uc2e4\ud5d8 \uc870\uac74\uc744 \uc790\uc138\ud788 \uc804\ud55c\ub2e4. \ubc1c\uacac\uc774\ub77c\ub294 \ub9d0\uc744 \ub4e3\uace0 \uc720\ub9ac\ubcd1 \ud558\ub098\uc5d0\uc11c \uac11\uc790\uae30 \ube5b\uc774 \ud130\uc9c0\ub294 \uc7a5\uba74\ub9cc \uc0c1\uc0c1\ud558\uba74 \uc774 \uae34 \uacfc\uc815\uc774 \uc0ac\ub77c\uc9c4\ub2e4. \uc5b4\ub5a4 \uc218\uce58\uac00 \uc65c \ub2e4\ub978\uc9c0 \ud655\uc778\ud558\uace0 \ub2e4\ub978 \uac00\ub2a5\uc131\uc744 \uc881\ud600 \uac00\ub294 \uc77c\uc774 \uc911\uc694\ud588\ub2e4. \uc9c1\uac10\uacfc \ub048\uae30\ub294 \uc2e4\ud5d8\uc744 \ub300\uc2e0\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc2e4\uc81c \ud655\uc778\uc758 \uacfc\uc815 \uc548\uc5d0\uc11c \ud798\uc744 \uc5bb\ub294\ub2e4. 1903\ub144 \ub9c8\ub9ac\uc640 \ud53c\uc5d0\ub974, \ubca0\ud06c\ub810\uc740 \ud568\uaed8 \ub178\ubca8\uc0c1\uc744 \ubc1b\ub294\ub2e4. \uc5f0\uad6c\uac00 \ub110\ub9ac \uc54c\ub824\uc9c0\uace0 \uc9c0\uc6d0\ub3c4 \ub298\uc9c0\ub9cc \ubc29\ubb38\uacfc \uc694\uad6c\uac00 \ub9ce\uc544\uc838 \uc77c\uc0c1\uc758 \ud3c9\uc628\uc740 \uc904\uc5b4\ub4e4\uc5c8\ub2e4\uace0 \uae30\ub85d\ud55c\ub2e4. \uba85\uc608\uac00 \uc0dd\uacbc\ub2e4\uace0 \uc2e4\ud5d8\uacfc \uc0dd\ud65c\uc758 \ubaa8\ub4e0 \uc5b4\ub824\uc6c0\uc774 \ub05d\ub098\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. 1906\ub144 \ud53c\uc5d0\ub974\uac00 \uc0ac\uace0\ub85c \uc138\uc0c1\uc744 \ub5a0\ub09c \ub4a4 \ub9c8\ub9ac\ub294 \ud070 \uc0c1\uc2e4 \uc18d\uc5d0\uc11c\ub3c4 \uc5f0\uad6c\uc640 \uac15\uc758\ub97c \uc774\uc5b4 \uac14\ub2e4. 1911\ub144\uc5d0\ub294 \ub450 \ubc88\uc9f8 \ub178\ubca8\uc0c1\uc744 \ubc1b\ub294\ub2e4. \ub450 \ubc88\uc758 \uc218\uc0c1 \uc0ac\uc774\ub97c \uc22b\uc790\ub85c\ub9cc \uc5f0\uacb0\ud558\uba74 \uac1c\uc778\uc758 \uc2ac\ud514\uacfc \uc77c\uc744 \uc9c0\uc18d\ud558\uae30 \uc704\ud55c \uc120\ud0dd\uc774 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uc0c1\uc740 \uc774 \uc0b6\uc758 \uc911\uc694\ud55c \ud45c\uc9c0\uc9c0\ub9cc \uc0b6 \uc804\uccb4\ub97c \ub300\uc2e0\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc81c1\ucc28 \uc138\uacc4\ub300\uc804 \uc911\uc5d0\ub294 \ubd80\uc0c1\uc790\ub97c \uc0b4\ud53c\ub294 \ub370 \ud544\uc694\ud55c X\uc120 \uc7a5\ube44\uc640 \uc778\ub825\uc744 \ub9c8\ub828\ud558\ub294 \ud65c\ub3d9\uc5d0 \ub098\uc120\ub2e4. \uc774\ub3d9 \ucc28\ub7c9\uc5d0 \uc7a5\ube44\uc640 \ubc1c\uc804\uae30\ub97c \uc2e3\uace0 \ubcd1\uc6d0\uc758 \ucd2c\uc601\uc744 \ub3d5\ub294 \ubc29\uc2dd\uc774\uc5c8\ub2e4. \uc5f0\uad6c\ud55c \uc9c0\uc2dd\uc744 \uc5b4\ub514\uc5d0\uc11c \uc5b4\ub5a4 \ud544\uc694\uc5d0 \uc5f0\uacb0\ud560\uc9c0 \ud310\ub2e8\ud558\ub294 \ub610 \ub2e4\ub978 \uc885\ub958\uc758 \uc77c\uc774\uc5c8\ub2e4. \ub77c\ub4d0 \uac19\uc740 \ubc29\uc0ac\uc131 \uc6d0\uc18c\uc758 \uc5f0\uad6c\uc640 X\uc120 \ucd2c\uc601 \uc7a5\ube44\uc758 \uc6b4\uc601\uc740 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \uc804\uc7a5\uc758 \ucc28\ub7c9\uc740 X\uc120 \uc7a5\ube44\ub97c \uc0ac\uc6a9\ud588\ub2e4. \ub9c8\ub9ac\ub294 \uc7a5\ube44\ub9cc \uc804\ub2ec\ud558\ub294 \ub370\uc11c \uadf8\uce58\uc9c0 \uc54a\uace0 \uc774\ub97c \ub2e4\ub8f0 \uc0ac\ub78c\uc744 \uad50\uc721\ud558\ub294 \uc77c\ub3c4 \uc911\uc694\ud558\uac8c \uc5ec\uacbc\ub2e4. \ub538 \uc774\ub80c\ub3c4 \uc804\uc2dc \ud65c\ub3d9\uc5d0 \ucc38\uc5ec\ud588\ub2e4. \ub9c8\ub9ac\uc758 \uae30\ub85d\uc5d0\ub294 \ub77c\ub4d0\uacfc \uad00\ub828\ud55c \uc5f0\uad6c\uc5d0\uc11c \ud2b9\ud5c8\ub85c \ub3c5\uc810\uc801\uc778 \uc774\uc775\uc744 \ub0a8\uae30\uc9c0 \uc54a\uc558\ub2e4\ub294 \uc124\uba85\ub3c4 \uc788\ub2e4. \uc5f0\uad6c \uacb0\uacfc\uc640 \uc81c\uc870 \ubc29\ubc95\uc774 \uc5b4\ub5a4 \ubc29\uc2dd\uc73c\ub85c \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uc804\ud574\uc838\uc57c \ud558\ub294\uc9c0\uc5d0 \uad00\ud55c \uc120\ud0dd\uc774\ub2e4. \uc774\ub97c \ubaa8\ub4e0 \uc2dc\ub300\uc640 \ubaa8\ub4e0 \uc5f0\uad6c\uc5d0 \ub611\uac19\uc774 \uc801\uc6a9\ud560 \uc815\ub2f5\uc73c\ub85c \ub9cc\ub4e4\uae30\ubcf4\ub2e4 \uadf8\uac00 \uc2e4\uc81c\ub85c \ucde8\ud55c \ud0dc\ub3c4\ub85c \uc77d\uc73c\uba74 \uc88b\ub2e4. \ud568\uaed8 \uc2e4\uc740 \uac83\uc740 1923\ub144 \uc800\uc11c\uc5d0 \uc218\ub85d\ub41c \ud30c\ub9ac \ud034\ub9ac \uc5f0\uad6c\uc18c \uc2e4\ud5d8\uc2e4\uc758 \uc2e4\uc81c \uc0ac\uc9c4\uc774\ub2e4. \ubc1c\uacac\uc758 \uc21c\uac04\uc744 \uc7ac\ud604\ud55c \uc5f0\ucd9c \uadf8\ub9bc\uc774 \uc544\ub2c8\ub2e4. \uc7a5\ube44 \uacc1\uc758 \ud55c \uc0ac\ub78c\uc744 \ubc14\ub77c\ubcf4\uba70, \uc774\ub984 \ub4a4\uc5d0 \uc788\ub358 \uacf5\ubd80\uc640 \uce21\uc815, \ud611\ub825\uacfc \ub3cc\ubd04\uc758 \uc2dc\uac04\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uacfc\ud559\uc758 \uae4a\uc774\ub294 \uc5b4\ub824\uc6b4 \uacf5\uc2dd\ub9cc\uc774 \uc544\ub2c8\ub77c \uadf8\ub7f0 \uc77c\uc744 \ub05d\uae4c\uc9c0 \ud655\uc778\ud574 \uac00\ub294 \uc0dd\ud65c\uc5d0\uc11c\ub3c4 \ub9cc\ub0a0 \uc218 \uc788\ub2e4."}, {"id": "red-panda-tail", "title": "\ub808\uc11c\ud310\ub2e4\uc758 \uaf2c\ub9ac\ub294 \ub2f4\uc694\uac00 \ub418\uae30\ub3c4 \ud55c\ub2e4", "summary": "\uc904\ubb34\ub2ac \uaf2c\ub9ac\ub294 \uadc0\uc5ec\uc6b4 \uc7a5\uc2dd\ub9cc\uc740 \uc544\ub2d9\ub2c8\ub2e4. \ub098\ubb34 \uc704\uc758 \uc0dd\ud65c\uacfc \ucd94\uc6b4 \ub0a0\uc528\uc5d0 \ubaa8\ub450 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.", "category": "science", "category_title": "Science", "subcategory": "Biology", "url": "stories/red-panda-tail/index.html", "image": "media/red-panda-tail.jpg", "alt": "\ub098\ubb47\uac00\uc9c0 \uc704\uc5d0\uc11c \ud48d\uc131\ud55c \uaf2c\ub9ac\ub97c \ubab8 \uac00\uae4c\uc774\uc5d0 \ub454 \ub808\uc11c\ud310\ub2e4\uc758 AI \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\ub808\uc11c\ud310\ub2e4\uc758 \uaf2c\ub9ac\ub294 \ub2f4\uc694\uac00 \ub418\uae30\ub3c4 \ud55c\ub2e4 \ub098\ubb47\uac00\uc9c0 \uc704\uc5d0\uc11c \ubc1c\uacac\ud558\ub294 \uaf2c\ub9ac\uc758 \ub450 \uac00\uc9c0 \uc4f0\uc784 \uc904\ubb34\ub2ac \uaf2c\ub9ac\ub294 \uadc0\uc5ec\uc6b4 \uc7a5\uc2dd\ub9cc\uc740 \uc544\ub2d9\ub2c8\ub2e4. \ub098\ubb34 \uc704\uc758 \uc0dd\ud65c\uacfc \ucd94\uc6b4 \ub0a0\uc528\uc5d0 \ubaa8\ub450 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4. Biology \uacfc\ud559 \ub808\uc11c\ud310\ub2e4\ub97c \uadf8\ub824 \ubcf4\ub77c\uace0 \ud558\uba74 \ubab8\ubcf4\ub2e4 \uaf2c\ub9ac\ub97c \uba3c\uc800 \ub5a0\uc62c\ub9b4\uc9c0\ub3c4 \ubaa8\ub978\ub2e4. \ubd89\uc740 \ud138 \uc0ac\uc774\ub85c \uc605\uc740 \uace0\ub9ac\uac00 \ubc88\uac08\uc544 \uc774\uc5b4\uc9c0\ub294, \uae38\uace0 \ud48d\uc131\ud55c \uaf2c\ub9ac\ub2e4. \ub098\ubb47\uac00\uc9c0\uc5d0 \uc549\uc544 \uc788\uc73c\uba74 \ubab8 \ub4a4\ub85c \ud55c\ucc38 \ub298\uc5b4\uc9c0\uae30\ub3c4 \ud55c\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c\ub294 \uadc0\uc5ec\uc6b4 \ubb34\ub2ac\ubd80\ud130 \ubcf4\uc774\uc9c0\ub9cc, \uadf8 \uaf2c\ub9ac\uc5d0\ub294 \uaf64 \uc2e4\uc6a9\uc801\uc778 \uc4f0\uc784\ub3c4 \uc788\ub2e4. \uc2a4\ubbf8\uc2a4\uc18c\ub2c8\uc5b8 \uad6d\ub9bd\ub3d9\ubb3c\uc6d0\uc740 \ub808\uc11c\ud310\ub2e4\uc758 \uaf2c\ub9ac\uac00 \uade0\ud615\uc744 \uc7a1\uace0 \ucd94\uc704\uc640 \ubc14\ub78c\uc744 \uacac\ub514\ub294 \ub370 \ub3c4\uc6c0\uc744 \uc900\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \ub808\uc11c\ud310\ub2e4\ub294 \ub098\ubb34\ub97c \uc798 \ud0c4\ub2e4. \ub098\ubb34\ub294 \ubab8\uc744 \uc228\uae30\uace0, \ud3ec\uc2dd\uc790\ub97c \ud53c\ud558\uace0, \uaca8\uc6b8\uc5d0 \ud587\ubcd5\uc744 \ucb10\ub294 \uc7a5\uc18c\uc774\uae30\ub3c4 \ud558\ub2e4. \ub545 \uc704\uc5d0\uc11c\ub9cc \uc0ac\ub294 \ub3d9\ubb3c\uacfc\ub294 \ub2e4\ub978 \uc0dd\ud65c\uc758 \uc790\ub9ac\uac00 \uc788\ub2e4. \uadf8 \uc790\ub9ac\uc5d0\uc11c \uae38\uace0 \ud48d\uc131\ud55c \uaf2c\ub9ac\ub294 \uade0\ud615\uc744 \uc720\uc9c0\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \uac00\uc9c0\uac00 \ubab8\uc744 \ubc1b\uccd0 \uc900\ub2e4\uace0 \ud574\uc11c \uac77\uace0 \ub3cc\uc544\uc11c\ub294 \uc77c\uc774 \uc800\uc808\ub85c \uc26c\uc6cc\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubab8 \ub4a4\uc758 \uae34 \ubd80\ubd84\ub3c4 \ub098\ubb34 \uc704 \uc0dd\ud65c\uc758 \ud55c\ubaab\uc744 \ub9e1\ub294\ub2e4. \ub098\ubb34\ub97c \ub0b4\ub824\uc624\ub294 \ubaa8\uc2b5\ub3c4 \ud765\ubbf8\ub86d\ub2e4. \ub3d9\ubb3c\uc6d0\uc740 \uc720\uc5f0\ud55c \ubc1c\ubaa9 \uad6c\uc870 \ub355\ubd84\uc5d0 \uba38\ub9ac\ub97c \uc544\ub798\ub85c \ud5a5\ud55c \ucc44 \ub098\ubb34\uc904\uae30\ub97c \ub0b4\ub824\uc62c \uc218 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uaf2c\ub9ac\ub9cc \ub530\ub85c \ub5bc\uc5b4 \ubcf4\uae30\ubcf4\ub2e4 \ubab8 \uc804\uccb4\uc758 \uc6c0\uc9c1\uc784\uacfc \ud568\uaed8 \ubcf4\uba74 \ub354 \uc7ac\ubbf8\uc788\ub2e4. \ub808\uc11c\ud310\ub2e4\uac00 \uc0ac\ub294 \uacf3\uc5d0\ub294 \ud788\ub9d0\ub77c\uc57c\ub97c \ube44\ub86f\ud55c \ub192\uc740 \uc0b0\uc9c0\uc758 \uc232\uc774 \ud3ec\ud568\ub41c\ub2e4. \uadf8\uacf3\uc5d0\uc11c \ud48d\uc131\ud55c \ud138\uc740 \ubcf4\uae30 \uc88b\uc740 \uc678\ud22c \uc774\uc0c1\uc758 \uc758\ubbf8\ub97c \uac16\ub294\ub2e4. \ubab8\uc5d0\ub294 \ubd80\ub4dc\ub7fd\uace0 \ucd18\ucd18\ud55c \uc18d\ud138\uc774 \uc788\uace0, \uae34 \uaf2c\ub9ac\ub294 \uc2ec\ud55c \ucd94\uc704\uc640 \ubc14\ub78c\uc73c\ub85c\ubd80\ud130 \ubab8\uc744 \ubcf4\ud638\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ubc1c\ubc14\ub2e5\ub3c4 \ud138\ub85c \ub36e\uc5ec \uc788\ub2e4. \ud654\uba74\uc5d0\uc11c\ub294 \uc791\uc740 \ub3d9\ubb3c\uc774\uc9c0\ub9cc, \ucd94\uc6b4 \uacf3\uc758 \uc0dd\ud65c\uc5d0 \ud544\uc694\ud55c \ucc28\ub9bc\uc744 \ud558\uace0 \uc788\ub294 \uc148\uc774\ub2e4. \uaf2c\ub9ac\ub97c \ubab8 \uac00\uae4c\uc774\uc5d0 \ub454 \ubaa8\uc2b5\uc744 \ubcf4\uba74 \ub2f4\uc694\ub098 \ubaa9\ub3c4\ub9ac\uac00 \ub5a0\uc624\ub978\ub2e4. \ubb3c\ub860 \uc0ac\ub78c\uc774 \uc9e0 \ubb3c\uac74\uc744 \ub450\ub978 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub530\ub73b\ud55c \ubb3c\uac74\uc5d0 \ube57\ub300\uc5b4 \ubcf4\uba74, \uae34 \ud138\uc774 \uc65c \uc0dd\ud65c\uc5d0 \uc4f8\ubaa8\uac00 \uc788\ub294\uc9c0 \uc870\uae08 \uce5c\uc219\ud558\uac8c \ub290\uaef4\uc9c4\ub2e4. \uac00\uc9c0 \uc704\ub97c \uc62e\uaca8 \uac00\ub294 \uc21c\uac04\uc5d0\ub294 \uae34 \uaf2c\ub9ac\uac00 \uade0\ud615\uc5d0 \ub3c4\uc6c0\uc744 \uc900\ub2e4. \ubab8\uc744 \uc6c5\ud06c\ub9ac\uace0 \uc26c\ub294 \uc21c\uac04\uc5d0\ub294 \ucd94\uc704\uc640 \ubc14\ub78c\uc744 \ub9c9\ub294 \ub370 \uc4f0\uc77c \uc218 \uc788\ub2e4. \uac19\uc740 \ubd80\ubd84\uc774 \ub298 \uac19\uc740 \uc790\uc138\ub85c \uac19\uc740 \uae30\ub2a5\ub9cc \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud589\ub3d9\uc5d0 \ub530\ub77c \uc5b4\ub5a4 \uad00\uacc4\uac00 \ub450\ub4dc\ub7ec\uc9c0\ub294\uc9c0 \ub2ec\ub77c\uc9c4\ub2e4. \uaf2c\ub9ac\uc758 \uae38\uc774\ub97c \uc7a5\uc2dd\uc801\uc778 \ud2b9\uc9d5\uc73c\ub85c\ub9cc \uae30\uc5b5\ud558\uc9c0 \uc54a\uc744 \uc774\uc720\ub2e4. \ub2f4\uc694\ub77c\ub294 \ube44\uc720\ub294 \ubab8\uc744 \uac10\uc2f8\ub294 \uc778\uc0c1\uc744 \uac00\uae4c\uc774 \uac00\uc838\uc624\uc9c0\ub9cc \uc2e4\uc81c \ucc9c\uc73c\ub85c \ub9cc\ub4e0 \ubb3c\uac74\uacfc \uac19\uc740 \uad6c\uc870\ub294 \uc544\ub2c8\ub2e4. \uaf2c\ub9ac\ub294 \ubab8\uc758 \uc77c\ubd80\uc774\uace0 \ud138\uc744 \uc9c0\ub2cc\ub2e4. \ub530\ub73b\ud568\uc758 \uae30\ub2a5\uc744 \uc774\ud574\ud558\ub294 \uc785\uad6c\ub85c \ube44\uc720\ub97c \uc4f0\uace0, \uc2e4\uc81c \ubab8\uc758 \uc124\uba85\uc740 \uae30\uad00 \uc790\ub8cc\ub97c \ub530\ub77c \uc77d\uc73c\uba74 \ub41c\ub2e4. \uce5c\uc219\ud55c \ub9d0\uc774 \ub3d9\ubb3c\uc758 \uace0\uc720\ud55c \uc0dd\ud65c\uc744 \uc9c0\uc6b0\uc9c0 \uc54a\uac8c \ud558\ub294 \ubc29\ubc95\uc774\ub2e4. \uba38\ub9ac\ub97c \uc544\ub798\ub85c \ud5a5\ud574 \ub0b4\ub824\uc62c \uc218 \uc788\ub2e4\ub294 \uc124\uba85\uc740 \ub808\uc11c\ud310\ub2e4\uc758 \uc6c0\uc9c1\uc784\uc744 \ub2e4\ub974\uac8c \ubcf4\uac8c \ud55c\ub2e4. \uae34 \uaf2c\ub9ac\ub9cc\uc774 \uc544\ub2c8\ub77c \ubc1c\ubaa9\uc758 \uc720\uc5f0\ud568\ub3c4 \ub098\ubb34 \uc704 \uc0dd\ud65c\uacfc \uad00\uacc4\uac00 \uc788\ub2e4. \ud55c \uac00\uc9c0 \ub208\uc5d0 \ub744\ub294 \ubd80\ubd84\ub9cc\uc73c\ub85c \uc804\uccb4 \ud589\ub3d9\uc744 \uc124\uba85\ud558\uae30 \uc5b4\ub824\uc6b4 \uac83\uc774\ub2e4. \ubab8\uc758 \uac01 \ubd80\ubd84\uc774 \ud568\uaed8 \uc77c\uc744 \ud55c\ub2e4\ub294 \uc810\uc744 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uc774\ub54c \uc0ac\ub78c\uc774 \uac19\uc740 \uc790\uc138\ub97c \ud749\ub0b4 \ub0b4\uc5b4 \uc5bc\ub9c8\ub098 \uc26c\uc6b4\uc9c0 \uc2dc\ud5d8\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub3d9\ubb3c\uc758 \ud574\ubd80\ud559\uc801 \uc870\uac74\uc740 \uc6b0\ub9ac\uc640 \ub2e4\ub974\ub2e4. \uad00\ucc30\uc5d0\uc11c\ub294 \uc5b4\ub290 \ubc29\ud5a5\uc73c\ub85c \ub0b4\ub824\uc624\ub294\uc9c0\uc640 \ubc1c\uc774 \ub098\ubb34\uc5d0 \ub193\uc774\ub294 \uc790\ub9ac\ub97c \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uc815\uc9c0\ud55c \uc0ac\uc9c4 \ud558\ub098\ub85c \uc6c0\uc9c1\uc784\uc758 \ubaa8\ub4e0 \uc21c\uc11c\ub97c \ud655\uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc2e4\uc81c \ud589\ub3d9 \uc790\ub8cc\uc640 \ud574\uc124\uc774 \uc11c\ub85c \ub3c4\uc6b8 \uc218 \uc788\ub2e4. \ub808\uc11c\ud310\ub2e4\ub294 \ub192\uc740 \uc0b0\uc9c0\uc758 \uc232\uc5d0\uc11c \uc0b0\ub2e4\uace0 \uc18c\uac1c\ub41c\ub2e4. \ub098\ubb34\ub294 \uc62c\ub77c\uac08 \uc9c0\ud615\uc774\uace0 \ud138\uc740 \ucd94\uc704\ub97c \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uc0dd\uae40\uc0c8\ub97c \ud658\uacbd\uacfc \uc5f0\uacb0\ud558\uba74 \uadc0\uc5fd\ub2e4\ub294 \uac10\uc0c1 \uc678\uc5d0 \uc5b4\ub5a4 \uc870\uac74\uc5d0\uc11c \uc0dd\ud65c\ud558\ub294\uc9c0\ub77c\ub294 \uc9c8\ubb38\uc774 \uc0dd\uae34\ub2e4. \ubab8\uc758 \ud2b9\uc9d5\uc774 \ub2e8\uc9c0 \ubcf4\ub294 \uc0ac\ub78c\uc744 \uc990\uac81\uac8c \ud558\ub824\uace0 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc5b4\ub290 \ud589\ub3d9\uc774\ub4e0 \ud558\ub098\uc758 \uc801\uc751 \uc774\uc57c\uae30\ub85c \uc989\uc2dc \ud655\uc815\ud574 \ub9d0\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \uc790\ub8cc\uac00 \ud655\uc778\ud55c \uade0\ud615\uacfc \ubcf4\uc628, \ubc1c\ubaa9\uc758 \uae30\ub2a5\uc744 \uc911\uc2ec\uc73c\ub85c \uc77d\ub294 \uac83\uc774 \uc815\ud655\ud558\ub2e4. \ud55c \uac1c\uccb4\uc758 \uc0c1\ud0dc\uc640 \ud65c\ub3d9\uc740 \uadf8 \uc21c\uac04\uc758 \ud658\uacbd\ub3c4 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc54c\ub824\uc9c4 \uae30\ub2a5\uc744 \ubc30\uc6b0\ub294 \uc77c\uacfc \uc0ac\uc9c4 \uc18d \ud589\ub3d9\uc758 \uc6d0\uc778\uc744 \ubaa8\ub450 \uc548\ub2e4\uace0 \uc0dd\uac01\ud558\ub294 \uc77c\uc740 \uad6c\ubd84\ud560 \uc218 \uc788\ub2e4. \uc6c5\ud06c\ub9b0 \ub808\uc11c\ud310\ub2e4\ub294 \uac00\ub9cc\ud788 \ub193\uc778 \uc778\ud615\ucc98\ub7fc \ubcf4\uc77c \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \uc790\uc138 \uc548\uc5d0 \ub098\ubb34\ub97c \uc624\ub974\uace0 \ubc14\ub78c\uc744 \ud53c\ud558\ub294 \ub3d9\ubb3c\uc758 \ubab8\uc774 \uc788\ub2e4. \uae34 \uaf2c\ub9ac\uc640 \ubc1c\uc758 \ud138, \ucd18\ucd18\ud55c \uc18d\ud138\uc5d0 \uad00\ud55c \uc124\uba85\uc744 \uc54c\uace0 \ub2e4\uc2dc \ubcf4\uba74 \uc870\uc6a9\ud55c \ubaa8\uc2b5\ub3c4 \ub2e4\ub978 \uc815\ubcf4\ub85c \ucc44\uc6cc\uc9c4\ub2e4. \uc6c0\uc9c1\uc784\uc774 \uc5c6\ub2e4\uace0 \uad00\ucc30\ud560 \ubd80\ubd84\uc774 \uc5c6\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub2e4\uc74c \uc0ac\uc9c4\uc5d0\uc11c\ub294 \uc5bc\uad74\uc744 \ubcf8 \ub4a4 \ubab8 \ub4a4\uc758 \uaf2c\ub9ac\ub85c \ub208\uc744 \uc62e\uaca8 \ubcf4\uc790. \uc5b4\ub290 \ucabd\uc5d0 \ub193\uc5ec \uc788\uace0 \ubab8\uacfc \uc5bc\ub9c8\ub098 \uac00\uae4c\uc6b4\uc9c0 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \uadf8 \ubaa8\uc591\uc5d0 \uac10\uc815\uc744 \ub2e8\uc815\ud574 \ubd99\uc774\uc9c0 \uc54a\uc544\ub3c4 \uc88b\ub2e4. \uaf2c\ub9ac\uac00 \ub2f4\uc694\uac00 \ub418\uae30\ub3c4 \ud55c\ub2e4\ub294 \ub9d0\uc740 \ud55c \ud2b9\uc9d5\uc744 \uc0dd\ud65c\uc758 \ub9e5\ub77d\uc73c\ub85c \uc77d\uac8c \ud558\ub294 \uc791\uc740 \uae38\uc7a1\uc774\ub2e4. \ubcf4\uae30 \uc88b\uc740 \ubaa8\uc591 \ub4a4\uc5d0 \uc4f0\uc784\uc758 \uc5ec\ub7ec \uc2dc\uac04\uc774 \uc788\uc5c8\ub2e4. \ub808\uc11c\ud310\ub2e4\uc758 \uaf2c\ub9ac\uc5d0\ub294 \ubd89\uc740\uc0c9\uacfc \uc605\uc740 \uc0c9\uc758 \uace0\ub9ac \ubb34\ub2ac\uac00 \ubc88\uac08\uc544 \ub098\ud0c0\ub09c\ub2e4. \uadf8 \ubb34\ub2ac\ub97c \uc54c\uc544\ubcf4\ub294 \uc990\uac70\uc6c0\uacfc \uaf2c\ub9ac\uc758 \uc4f0\uc784\uc744 \uc544\ub294 \uc990\uac70\uc6c0\uc740 \uc870\uae08 \ub2e4\ub974\ub2e4. \uc774\ub984\uacfc \uc0dd\uae40\uc0c8\ub97c \ub9de\ud78c \ub2e4\uc74c\uc5d0\ub3c4 \uad6c\uacbd\uc740 \uacc4\uc18d\ub41c\ub2e4. \uac00\uc9c0 \uc704\uc5d0\uc11c \ubc29\ud5a5\uc744 \ubc14\uafc0 \ub54c \uaf2c\ub9ac\uac00 \uc5b4\ub514\uc5d0 \uc788\ub294\uc9c0, \uc26c\ub294 \ub3d9\uc548\uc5d0\ub294 \ubab8\uacfc \uc5bc\ub9c8\ub098 \uac00\uae4c\uc6b4\uc9c0 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \ub2e4\uc74c\uc5d0 \ub808\uc11c\ud310\ub2e4 \uc0ac\uc9c4\uc744 \ubcf8\ub2e4\uba74 \uc5bc\uad74\ub9cc \ud655\ub300\ud558\uc9c0 \ub9d0\uace0 \uaf2c\ub9ac\uae4c\uc9c0 \ub4e4\uc5b4\uc628 \uc7a5\uba74\ub3c4 \uace8\ub77c \ubcf4\uc790. \uc791\uc740 \uc5bc\uad74 \ub4a4\ub85c \ub298\uc5b4\uc9c4 \uae34 \ubd80\ubd84\uc5d0, \ub098\ubb34\ub97c \ud0c0\uace0 \ucd94\uc704\ub97c \uacac\ub514\ub294 \uc0dd\ud65c\uc774 \ud568\uaed8 \ub2ec\ub824 \uc788\ub2e4."}, {"id": "soap-water-and-oily-plate", "title": "\ube44\ub204 \u2014 \ubb3c\uacfc \uae30\ub984 \uc0ac\uc774\uc5d0 \ub2e4\ub9ac\ub97c \ub193\ub2e4", "summary": "\uc124\uac70\uc9c0\uc758 \uc7a5\uba74\uc5d0\uc11c \ube44\ub204 \ubd84\uc790\uc758 \uc11c\ub85c \ub2e4\ub978 \ubd80\ubd84\uacfc \uae30\ub984\ubc29\uc6b8\uc758 \ubd84\uc0b0\uc744 \uc27d\uac8c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "Science", "subcategory": "Chemistry", "url": "stories/soap-water-and-oily-plate/index.html", "image": "media/soap-water-and-oily-plate.png", "alt": "\uc8fc\ubc29 \uc2f1\ud06c\ub300\uc5d0\uc11c \ube44\ub204 \uac70\ud488\uacfc \uc218\uc138\ubbf8\ub85c \uae30\ub984 \ubb3b\uc740 \uc811\uc2dc\ub97c \uc53b\ub294 \uc190\uc758 \uc0bd\ud654.", "text": "\ube44\ub204 \u2014 \ubb3c\uacfc \uae30\ub984 \uc0ac\uc774\uc5d0 \ub2e4\ub9ac\ub97c \ub193\ub2e4 \uae30\ub984\ub54c\uac00 \uc0ac\ub77c\uc9c0\ub294 \uac83\uacfc \ubb3c\uc5d0 \uc53b\uaca8 \ub098\uac00\ub294 \uac83 \uc124\uac70\uc9c0\uc758 \uc7a5\uba74\uc5d0\uc11c \ube44\ub204 \ubd84\uc790\uc758 \uc11c\ub85c \ub2e4\ub978 \ubd80\ubd84\uacfc \uae30\ub984\ubc29\uc6b8\uc758 \ubd84\uc0b0\uc744 \uc27d\uac8c \uc77d\uc2b5\ub2c8\ub2e4. Chemistry \uacfc\ud559 \uae30\ub984 \ubb3b\uc740 \uc811\uc2dc\uc5d0 \ubb3c\uc744 \ud758\ub824\ubcf4\ub0b8\ub2e4. \ubb3c\ubc29\uc6b8\uc740 \uc9c0\ub098\uac00\uc9c0\ub9cc \ubbf8\ub048\ud55c \ub290\ub08c\uc740 \ub0a8\ub294\ub2e4. \uadf8\ub7f0\ub370 \ube44\ub204\ub098 \uc138\uc81c\ub97c \uc870\uae08 \uc4f0\uace0 \ubb38\uc9c0\ub974\uba74 \uc0c1\ud0dc\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \ubb3c\uacfc \uc798 \uc11e\uc774\uc9c0 \uc54a\ub294 \uae30\ub984\uc744 \ubb34\uc5c7\uc774 \uc6c0\uc9c1\uc774\uac8c \ud55c \uac83\uc77c\uae4c. \uc774 \uc7a5\uba74\uc5d0\ub294 \uc791\uc740 \ubd84\uc790\uc758 \uc11c\ub85c \ub2e4\ub978 \uc131\uc9c8\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \ubb3c\uacfc \uc798 \uc5b4\uc6b8\ub9ac\ub294 \ubd80\ubd84\uacfc \uae30\ub984 \ucabd\uc5d0 \ub04c\ub9ac\ub294 \ubd80\ubd84\uc774 \ud55c \ubd84\uc790 \uc548\uc5d0 \uc788\ub2e4. \ube44\ub204\ub294 \ub450 \uc138\uacc4 \uc0ac\uc774\uc5d0\uc11c \uc791\uc6a9\ud558\uba70 \uae30\ub984\uc774 \ubb3c\uacfc \ud568\uaed8 \uc774\ub3d9\ud560 \uc218 \uc788\ub294 \uc0c1\ud0dc\ub97c \ub9cc\ub4dc\ub294 \ub370 \ub3c4\uc6c0\uc744 \uc900\ub2e4. \ubb3c\uacfc \uae30\ub984\uc744 \uc11e\uc73c\ub824 \ud754\ub4e4\uba74 \uc7a0\uc2dc \uc791\uc740 \ubc29\uc6b8\ub4e4\uc774 \uc0dd\uae38 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uadf8\ub300\ub85c \ub450\uba74 \ub2e4\uc2dc \uce35\uc744 \uc774\ub8e8\uae30 \uc27d\ub2e4. \uad50\uc7ac\ub294 \uc11c\ub85c \uc798 \uc11e\uc774\uc9c0 \uc54a\ub294 \uc561\uccb4\uc758 \uc608\ub85c \ubb3c\uacfc \uae30\ub984\uc744 \uc124\uba85\ud55c\ub2e4. \ud754\ub4e4\uc5b4\uc11c \ub098\ub204\uc5b4 \ub193\ub294 \uc77c\uacfc \uc548\uc815\uc801\uc73c\ub85c \uc11e\uc5ec \uc788\uac8c \ud558\ub294 \uc77c\uc740 \ub2e4\ub974\ub2e4. \ubb3c\uacfc \uae30\ub984\uc758 \ubd84\uc790 \uc0ac\uc774\uc5d0 \uc791\uc6a9\ud558\ub294 \ud798\uc774 \uc11c\ub85c \ub2e4\ub978 \uac83\uc774 \uc911\uc694\ud55c \uc774\uc720\ub2e4. \ud55c\ucabd\uc774 \ub2e4\ub978 \ucabd\uc744 \uc2eb\uc5b4\ud55c\ub2e4\ub294 \ud45c\ud604\uc740 \uae30\uc5b5\ud558\uae30 \ud3b8\ud55c \ube44\uc720\uc9c0\ub9cc \uc2e4\uc81c \uac10\uc815\uc774 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubd84\uc790\ub4e4\uc774 \uc8fc\ubcc0\uacfc \ub9fa\ub294 \uc0c1\ud638\uc791\uc6a9\uc758 \ucc28\uc774\uac00 \ud070 \ub369\uc5b4\ub9ac\uc758 \uc131\uc9c8\ub85c \ub098\ud0c0\ub09c\ub2e4\uace0 \uc774\ud574\ud558\uba74 \uc88b\ub2e4. OpenStax\ub294 \ube44\ub204 \ubd84\uc790\uc5d0 \uae34 \ud0c4\ud654\uc218\uc18c \ubd80\ubd84\uacfc \ubb3c\uc5d0 \ub04c\ub9ac\ub294 \uc774\uc628\uc131 \ubd80\ubd84\uc774 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc27d\uac8c \ub9d0\ud558\uba74 \uae30\ub984\uacfc \uc5b4\uc6b8\ub9ac\uae30 \uc88b\uc740 \ubd80\ubd84, \ubb3c\uacfc \uc0c1\ud638\uc791\uc6a9\ud558\uae30 \uc88b\uc740 \ubd80\ubd84\uc774 \uc774\uc5b4\uc838 \uc788\ub2e4. \uc804\uccb4\ub97c \ud55c \uac00\uc9c0 \uc131\uc9c8\ub85c\ub9cc \ubd80\ub974\uae30 \uc5b4\ub824\uc6b4 \uad6c\uc870\ub2e4. \uc774 \ub54c\ubb38\uc5d0 \ube44\ub204\ub294 \ubb3c\uacfc \uae30\ub984\uc758 \uacbd\uacc4\uc5d0\uc11c \uc5ed\ud560\uc744 \ud560 \uc218 \uc788\ub2e4. \ubaa8\ub4e0 \ubd84\uc790\uc758 \uc774\ub984\uacfc \ud654\ud559\uc2dd\uc744 \uc678\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \ub41c\ub2e4. \uc911\uc694\ud55c \uc810\uc740 \uc11c\ub85c \ub2e4\ub978 \uc131\uc9c8\uc774 \ud55c\uacf3\uc5d0 \uc5f0\uacb0\ub418\uc5b4 \uc788\ub2e4\ub294 \uac83\uc774\ub2e4. \uc791\uc740 \uad6c\uc870\uc758 \ucc28\uc774\uac00 \uc190\uc73c\ub85c \ub290\ub07c\ub294 \uc124\uac70\uc9c0\uc758 \uacb0\uacfc\uc5d0\uae4c\uc9c0 \uc774\uc5b4\uc9c4\ub2e4. \ube44\ub204 \ubd84\uc790\uc758 \uae30\ub984\uacfc \uc5b4\uc6b8\ub9ac\ub294 \ubd80\ubd84\uc740 \uae30\ub984 \ucabd\uc73c\ub85c, \ubb3c\uacfc \uc798 \uc0c1\ud638\uc791\uc6a9\ud558\ub294 \ubd80\ubd84\uc740 \ubb3c \ucabd\uc73c\ub85c \ub193\uc77c \uc218 \uc788\ub2e4. \uad50\uc7ac\ub294 \uc774\ub97c \uc11c\ub85c \ub2e4\ub978 \ub450 \uc885\ub958\uc758 \ubb3c\uc9c8 \uc0ac\uc774\uc5d0 \ub2e4\ub9ac\ub97c \ub193\ub294 \ubaa8\uc2b5\uc73c\ub85c \uc124\uba85\ud55c\ub2e4. \uae30\ub984\ubc29\uc6b8\uc758 \ubc14\uae65\uc5d0 \ubb3c\uacfc \ub9cc\ub098\ub294 \uc870\uac74\uc774 \uc0dd\uae30\ub294 \uac83\uc774\ub2e4. \uadf8 \uacb0\uacfc \uae30\ub984\ub54c\uac00 \uc791\uc740 \ubc29\uc6b8\ub85c \ubb3c\uc18d\uc5d0 \ubd84\uc0b0\ub418\uc5b4 \uc53b\uaca8 \ub098\uac00\uae30 \uc26c\uc6cc\uc9c4\ub2e4. \uae30\ub984\uc774 \uac11\uc790\uae30 \ubb3c \ubd84\uc790\ub85c \ubc14\ub00c\uac70\ub098 \uc138\uc0c1\uc5d0\uc11c \uc0ac\ub77c\uc84c\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \ud615\ud0dc\ub85c \uc8fc\ubcc0\uc5d0 \uc874\uc7ac\ud558\uace0 \ubb34\uc5c7\uacfc \ud568\uaed8 \uc774\ub3d9\ud560 \uc218 \uc788\ub294\uc9c0\uac00 \ub2ec\ub77c\uc9c4 \uac83\uc774\ub2e4. \uc81c\uac70\uc640 \ubcc0\ud658\uc744 \uad6c\ubcc4\ud558\uba74 \uc791\ub3d9\uc774 \ub354 \uc798 \ubcf4\uc778\ub2e4. \uc138\uc81c\uc758 \ubd84\uc790\ub9cc \ub5a0\uc62c\ub9ac\uba74 \uc124\uac70\uc9c0\uac00 \uc800\uc808\ub85c \ub05d\ub0a0 \uac83 \uac19\uc9c0\ub9cc \uc2e4\uc81c \uacfc\uc815\uc5d0\ub294 \uc6c0\uc9c1\uc784\ub3c4 \uc788\ub2e4. \ubb38\uc9c0\ub974\uace0 \ud5f9\uad6c\uba74\uc11c \ub5a8\uc5b4\uc9c4 \uae30\ub984\uacfc \uc624\uc5fc\ubb3c\uc774 \ub2e4\ub978 \uacf3\uc73c\ub85c \uc62e\uaca8 \uac04\ub2e4. \ubd84\uc790\uc758 \uc131\uc9c8\uacfc \ubb3c\ub9ac\uc801\uc778 \uc791\uc5c5\uc740 \uac19\uc740 \uc7a5\uba74\uc5d0\uc11c \ud568\uaed8 \uc791\uc6a9\ud55c\ub2e4. \uc774\ubc88 \uae00\uc740 \ud2b9\uc815 \uc81c\ud488\uc758 \uc138\ucc99\ub825\uc744 \uc2dc\ud5d8\ud55c \uacb0\uacfc\uac00 \uc544\ub2c8\ub2e4. \uc811\uc2dc\uc758 \uc7ac\ub8cc\uc640 \uc624\uc5fc\uc758 \uc885\ub958, \ubb3c\uc758 \uc870\uac74\uc5d0 \ub530\ub77c \uc2e4\uc81c \uacb0\uacfc\ub294 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ubb3c\uacfc \uae30\ub984 \uc0ac\uc774\uc758 \uad00\uacc4\ub97c \ubc14\uafb8\ub294 \uc5ed\ud560\uc744 \uc774\ud574\ud558\uba74 \uc65c \ubb3c\ub9cc \uc4f8 \ub54c\uc640 \ub2e4\ub978 \uacbd\ud5d8\uc744 \ud558\ub294\uc9c0 \ud070 \ud750\ub984\uc744 \uc54c \uc218 \uc788\ub2e4. \uac70\ud488\uc774 \ub9ce\uc774 \ubcf4\uc774\uba74 \uc798 \uc53b\uae30\ub294 \uac83\ucc98\ub7fc \ub290\uaef4\uc9c8 \ub54c\uac00 \uc788\ub2e4. \uadf8\ub7ec\ub098 \ub208\uc5d0 \ubcf4\uc774\ub294 \uac70\ud488\uc758 \uc591\ub9cc\uc73c\ub85c \uae30\ub984\uc774 \uc5bc\ub9c8\ub098 \uc81c\uac70\ub418\uc5c8\ub294\uc9c0\ub97c \uc9c1\uc811 \uce21\uc815\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774 \uae00\uc5d0\uc11c \uc124\uba85\ud55c \ud575\uc2ec\uc740 \ubb3c\uacfc \uc624\uc5fc\ubb3c\uc758 \uacbd\uacc4\uc5d0\uc11c \ubd84\uc790\uac00 \uc5b4\ub5a4 \uc5ed\ud560\uc744 \ud558\ub294\uac00\uc5d0 \uc788\ub2e4. \uac70\ud488\uc740 \uae30\uccb4\uac00 \uc561\uccb4 \uc548\uc5d0 \ubd84\uc0b0\ub41c \uc0c1\ud0dc\ub85c \ubcfc \uc218 \uc788\uace0, \uae30\ub984\ubc29\uc6b8\uc774 \ubb3c\uc5d0 \ud37c\uc838 \uc788\ub294 \uc0c1\ud0dc\uc640\ub294 \ub2e4\ub978 \uad6c\ubd84\uc774\ub2e4. \uad50\uc7ac\ub294 \uc774\ub7f0 \uc5ec\ub7ec \ubd84\uc0b0 \uc0c1\ud0dc\ub97c \ucf5c\ub85c\uc774\ub4dc\ub77c\ub294 \ud2c0\uc5d0\uc11c \ud568\uaed8 \ub2e4\ub8ec\ub2e4. \ub2ee\uc544 \ubcf4\uc774\ub294 \ud604\uc0c1\ub3c4 \ubb34\uc5c7\uc774 \ubb34\uc5c7 \uc18d\uc5d0 \ud37c\uc838 \uc788\ub294\uc9c0 \ubb3c\uc73c\uba74 \uc11c\ub85c \ub2e4\ub978 \uad6c\uc870\uac00 \ub4dc\ub7ec\ub09c\ub2e4. \uce7c\uc298\uacfc \ub9c8\uadf8\ub124\uc298 \uc774\uc628\uc774 \ub9ce\uc740 \uacbd\uc218\uc5d0\uc11c\ub294 \ube44\ub204\uac00 \uc798 \ub179\uc9c0 \uc54a\ub294 \ubb3c\uc9c8\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub2e4. \uad50\uc7ac\ub294 \ud569\uc131 \uc138\uc81c\uac00 \uc774\ub7f0 \uc870\uac74\uc5d0\uc11c \uac16\ub294 \ucc28\uc774\ub97c \uc124\uba85\ud55c\ub2e4. \uac19\uc740 \ube44\ub204\ub97c \uc368\ub3c4 \ubb3c\uc758 \uc870\uac74\uc5d0 \ub530\ub77c \uacbd\ud5d8\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub294 \uc774\uc720 \uac00\uc6b4\ub370 \ud558\ub098\ub2e4. \ub530\ub77c\uc11c \ube44\ub204\uc640 \uc138\uc81c\ub97c \ubaa8\ub4e0 \uc0c1\ud669\uc5d0\uc11c \uac19\uc740 \uac83\uc73c\ub85c \ubb49\ub6b1\uadf8\ub9ac\uae30\ub3c4 \uc5b4\ub835\ub2e4. \ube44\uc2b7\ud55c \uc77c\uc744 \ud558\ub3c4\ub85d \ub9cc\ub4e4\uc5b4\uc84c\uc9c0\ub9cc \ubd84\uc790 \uad6c\uc870\uc640 \ubb3c\uc18d\uc758 \ubc18\uc751\uc740 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uc774\ubc88\uc5d0\ub294 \ud2b9\uc815 \uc81c\ud488\uc744 \ube44\uad50\ud558\uae30\ubcf4\ub2e4 \ubb3c\uc774\ub77c\ub294 \ubc30\uacbd\ub3c4 \uc791\ub3d9 \uc870\uac74\uc758 \uc77c\ubd80\ub77c\ub294 \uc810\uc744 \uae30\uc5b5\ud558\uba74 \ucda9\ubd84\ud558\ub2e4. \ubb3c\uc18d\uc5d0 \uc791\uc740 \ubc29\uc6b8\ub85c \ud37c\uc838 \uc788\ub2e4\uace0 \ubc18\ub4dc\uc2dc \ubd84\uc790 \uc218\uc900\uc5d0\uc11c \ubaa8\ub450 \ub179\uc740 \uac83\uc740 \uc544\ub2c8\ub2e4. \uad50\uc7ac\ub294 \uc720\ud654\uc640 \uc6a9\ud574\ub97c \uad6c\ubd84\ud574 \uc124\uba85\ud55c\ub2e4. \uc6b0\uc720\ub098 \ub9c8\uc694\ub124\uc988 \uac19\uc740 \uc77c\uc0c1\uc758 \ud63c\ud569\ubb3c\ub3c4 \uc11c\ub85c \ub2e4\ub978 \uc131\ubd84\uc774 \uc5b4\ub5a4 \ubc29\uc2dd\uc73c\ub85c \ubd84\uc0b0\ub418\ub294\uc9c0 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uae30\ub984 \ubb3b\uc740 \uc811\uc2dc\ub97c \uc53b\ub294 \uc77c\ubc18\uc801\uc778 \uc7a5\uba74\uc774\ub2e4. \ube44\ub204 \ubd84\uc790\uc758 \uc2e4\uc81c \ubaa8\uc2b5\uc774\ub098 \ud604\ubbf8\uacbd \uad00\ucc30 \uacb0\uacfc\ub97c \ubcf4\uc5ec \uc8fc\ub294 \ub3c4\uc2dd\uc740 \uc544\ub2c8\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \uc124\uac70\uc9c0\uc640 \ub208\uc5d0 \ubcf4\uc774\uc9c0 \uc54a\ub294 \ubd84\uc790\uc758 \uc124\uba85\uc744 \uc5f0\uacb0\ud558\ub294 \ubd84\uc704\uae30 \uadf8\ub9bc\uc774\ub2e4. \uc124\uac70\uc9c0\uac00 \ub05d\ub098\uba74 \uc811\uc2dc\ub9cc \ubcf4\uace0 \uae68\ub057\ud574\uc84c\ub2e4\uace0 \ub9d0\ud55c\ub2e4. \uadf8\ub7ec\ub098 \uacfc\ud559\uc758 \uc9c8\ubb38\uc740 \uae30\ub984\uc774 \uc5b4\ub5a4 \uc0c1\ud0dc\uac00 \ub418\uc5b4 \uc5b4\ub514\ub85c \uc62e\uaca8 \uac14\ub294\uc9c0\uae4c\uc9c0 \uc774\uc5b4\uc9c8 \uc218 \uc788\ub2e4. \ube44\ub204\uc758 \uc5ed\ud560\uc740 \ubb3c\uacfc \uae30\ub984\uc744 \uc804\ud600 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \ub9cc\ub098\uac8c \ud574 \uc774\ub3d9\uc744 \ub3d5\ub294 \ub370 \uc788\ub2e4. \ub2e4\uc74c\uc5d0 \ubb3c\ub9cc\uc73c\ub85c \ub0a8\uc544 \uc788\ub358 \uae30\ub984\uc774 \uc138\uc81c\uc640 \ud568\uaed8 \uc53b\uaca8 \ub098\uac00\ub294 \ubaa8\uc2b5\uc744 \ubcf4\uba74 \uc791\uc740 \ubd84\uc790\uc758 \ub450 \ubd80\ubd84\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \ubb3c\uacfc \uac00\uae4c\uc6cc\uc9c0\ub294 \ucabd\uacfc \uae30\ub984\uc5d0 \uac00\uae4c\uc6cc\uc9c0\ub294 \ucabd\uc774 \uc5f0\uacb0\ub418\uc5b4 \uc788\ub2e4. \ubd84\uc790 \ud558\ub098\uc758 \uad6c\uc870\uac00 \uc77c\uc0c1\uc758 \ubc88\uac70\ub85c\uc6b4 \uc77c\uc744 \ubc14\uafb8\ub294 \uacfc\uc815\uc774 \uc190\ub05d\uc5d0\uc11c \uc77c\uc5b4\ub098\uace0 \uc788\ub294 \uc148\uc774\ub2e4."}, {"id": "star-map-carved-again", "title": "\ubcc4\uc9c0\ub3c4\ub97c \ub2e4\ub978 \ub3cc\uc5d0 \ub2e4\uc2dc \uc0c8\uae34 \uc774\uc720", "summary": "\uac19\uc740 \ubcc4\uc9c0\ub3c4\ub97c \uc0c8 \ub3cc\uc5d0 \uc62e\uae34 \ubcf5\uac01\ucc9c\uc0c1\uc5f4\ucc28\ubd84\uc57c\uc9c0\ub3c4\uac01\uc11d\uc758 \uc0ac\uc5f0\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "Science", "subcategory": "Physics", "url": "stories/star-map-carved-again/index.html", "image": "media/star-map-carved-again.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \ubcf5\uac01\ucc9c\uc0c1\uc5f4\ucc28\ubd84\uc57c\uc9c0\ub3c4\uac01\uc11d \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\ubcc4\uc9c0\ub3c4\ub97c \ub2e4\ub978 \ub3cc\uc5d0 \ub2e4\uc2dc \uc0c8\uae34 \uc774\uc720 \ub0a1\uc544 \uac00\ub294 \uae30\ub85d\uc744 \uc62e\uaca8 \ub450\ub294 \ubc29\ubc95 \uac19\uc740 \ubcc4\uc9c0\ub3c4\ub97c \uc0c8 \ub3cc\uc5d0 \uc62e\uae34 \ubcf5\uac01\ucc9c\uc0c1\uc5f4\ucc28\ubd84\uc57c\uc9c0\ub3c4\uac01\uc11d\uc758 \uc0ac\uc5f0\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Physics \uacfc\ud559 \ubcc4\uc9c0\ub3c4\ub97c \uc0dd\uac01\ud558\uba74 \uc885\uc774\ub098 \ud654\uba74\ubd80\ud130 \ub5a0\uc624\ub978\ub2e4. \uadf8\ub7f0\ub370 \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc5d0\ub294 \ub3cc\uc5d0 \uc0c8\uae34 \ubcc4\uc9c0\ub3c4\uac00 \uc788\ub2e4. \uc774\ub984\uc740 \uae38\ub2e4. \ubcf5\uac01\ucc9c\uc0c1\uc5f4\ucc28\ubd84\uc57c\uc9c0\ub3c4\uac01\uc11d. \uc624\ub298\uc740 \uadf8 \uc774\ub984\uc744 \ub2e4 \uc678\uc6b0\uc9c0 \ub9d0\uace0 \ub9e8 \uc55e\uc758 \ubcf5\uac01\uc5d0\ub9cc \ub208\uae38\uc744 \uc8fc\uc5b4 \ubcf4\uc790. \uc774 \ubb3c\uac74\uc758 \uc7ac\ubbf8\ub294 \ubcc4\uc744 \uba87 \uac1c \uadf8\ub838\ub290\ub0d0\ubcf4\ub2e4 \uc65c \uac19\uc740 \ub0b4\uc6a9\uc744 \ub2e4\ub978 \ub3cc\uc5d0 \ub2e4\uc2dc \uc0c8\uacbc\ub290\ub0d0\uc5d0 \uc788\ub2e4. \ud558\ub298\uc744 \uae30\ub85d\ud55c \ub3cc\uc5d0\ub3c4 \uc2dc\uac04\uc774 \ud758\ub800\ub358 \uac83\uc774\ub2e4. \ubc15\ubb3c\uad00\uc740 1395\ub144\uc5d0 \ub3cc\uc5d0 \uc0c8\uae34 \ucc9c\ubb38\ub3c4 \uac01\uc11d\uc774 \uc138\uc6d4\uc774 \ud750\ub974\uba70 \ud6fc\uc190\ub418\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uadf8\ub798\uc11c 1687\ub144\uc5d0 \uadf8 \ub0b4\uc6a9\uc744 \ub2e4\ub978 \ub3cc\uc5d0 \ub2e4\uc2dc \uc0c8\uacbc\ub2e4. \uc774\ub54c \ub9cc\ub4e4\uc5b4\uc9c4 \uac83\uc774 \uc0ac\uc9c4\uc758 \ubcf5\uac01\ubcf8\uc774\ub2e4. \uc624\ub798 \ubcf4\uad00\ud558\ub824\uace0 \ub2e8\ub2e8\ud55c \uc7ac\ub8cc\ub97c \uace8\ub77c\ub3c4 \uae30\ub85d\uc774 \uc800\uc808\ub85c \uc601\uc6d0\ud574\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5ec\uae30\uc11c\ub294 \ub0b4\uc6a9\uc774 \uc0ac\ub77c\uc9c0\uae30 \uc804\uc5d0 \uc0c8\ub85c\uc6b4 \ub3cc\ub85c \uc62e\uae30\ub294 \ubc29\ubc95\uc744 \ud0dd\ud588\ub2e4. \uc190\uc0c1\ub41c \uc885\uc774\ub97c \ub2e4\uc2dc \ubca0\ub07c\ub294 \uc77c\uacfc \ub098\ub780\ud788 \uc0dd\uac01\ud574 \ubcfc \uc218 \uc788\ub294 \ub300\ubaa9\uc774\ub2e4. \uc0c8 \ub3cc\uc5d0 \uc0c8\uacbc\ub2e4\uace0 \uc0c8 \ubcc4\uc790\ub9ac\ub97c \ubc1c\uacac\ud588\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc758 \uc911\uc2ec\uc740 \uae30\uc874 \ub0b4\uc6a9\uc744 \ub2e4\uc2dc \uc0c8\uaca8 \ubcf4\uc874\ud588\ub2e4\ub294 \ub370 \uc788\ub2e4. \uae30\ub85d\uc758 \ub0b4\uc6a9\uacfc \uadf8 \ub0b4\uc6a9\uc744 \ub2f4\uc740 \ubb3c\uac74\uc758 \uc81c\uc791 \uc2dc\uc810\uc744 \ub098\ub204\uc5b4 \ubcfc \ud544\uc694\uac00 \uc788\ub2e4. \uc0ac\uc9c4\uc758 \ub3cc\uc774 1687\ub144 \uac83\uc774\ub77c\ub294 \uc0ac\uc2e4\uacfc \uc6d0\ub798 \ucc9c\ubb38\ub3c4\uac00 1395\ub144\uc5d0 \uc0c8\uaca8\uc84c\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uadf8\ub798\uc11c \ud568\uaed8 \ub4f1\uc7a5\ud55c\ub2e4. \uc11c\ub85c \ub2e4\ub978 \ub450 \ub0a0\uc9dc\uac00 \uc2e4\uc218\ub85c \uc801\ud78c \uac83\uc774 \uc544\ub2c8\ub77c, \uc62e\uaca8 \ub0a8\uae30\ub294 \uacfc\uc815\uc758 \uc55e\ub4a4\ub97c \uc54c\ub824 \uc8fc\ub294 \uac83\uc774\ub2e4. \ucc9c\ubb38\ub3c4\uc758 \ub0b4\uc6a9\uc774 \uc5b4\ub514\uc5d0\uc11c \uc654\ub294\uc9c0\uc640 \ub208\uc55e\uc758 \ub3cc\uc744 \uc5b8\uc81c \uc0c8\uacbc\ub294\uc9c0\ub294 \ub2e4\ub978 \uc9c8\ubb38\uc774\ub2e4. \ubcf5\uac01\ubcf8\uc740 \uc774 \ub450 \uc2dc\uac04\uc744 \ud568\uaed8 \ud488\ub294\ub2e4. 1687\ub144 \uc81c\uc791\uc774\ub77c\ub294 \uc815\ubcf4\uac00 \uc6d0\ub798\uc758 \ub0b4\uc6a9\uc744 \uadf8\ud574 \ucc98\uc74c \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ub9e4\uccb4\ub97c \uc0c8\ub85c \ub9c8\ub828\ud574 \uae30\ub85d\uc744 \uc774\uc5b4 \uac00\ub294 \ubc29\uc2dd\uc774\uc5c8\ub2e4. \uadf8\ub798\uc11c \uc6d0\ubcf8\uc774\ub77c\ub294 \ub9d0 \ud558\ub098\uc640 \ubcf5\uc81c\ud488\uc774\ub77c\ub294 \ub9d0 \ud558\ub098\ub85c \uac00\uce58\ub97c \ub098\ub204\uae30 \uc5b4\ub835\ub2e4. \uc62e\uaca8 \uc0c8\uae34 \ubb3c\uac74\ub3c4 \ub2f9\uc2dc \uc0ac\ub78c\ub4e4\uc774 \ubb34\uc5c7\uc744 \ubcf4\uc874\ud560 \ud544\uc694\uac00 \uc788\ub2e4\uace0 \uc0dd\uac01\ud588\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\ub294 \uc790\ub8cc\ub2e4. \ub2e4\ub9cc \uc0c8 \ub3cc\uc758 \ubaa8\ub4e0 \uc120\uc774 \uc6d0\ub798\uc640 \uc5b4\ub5bb\uac8c \uc77c\uce58\ud558\ub294\uc9c0\ub294 \uad6c\uccb4\uc801\uc778 \ube44\uad50\uac00 \ud544\uc694\ud55c \ubb38\uc81c\ub85c \ub0a8\ub294\ub2e4. \uc5ec\uae30\uc11c\ub294 \ubc15\ubb3c\uad00\uc774 \ud655\uc778\ud55c \ubcf5\uac01\uc758 \uc774\uc720\uc640 \uc774\ub825\uc744 \ub530\ub77c \uc77d\ub294\ub2e4. \ub3cc\uc740 \uc885\uc774\ubcf4\ub2e4 \uc624\ub798 \ub0a8\uc744 \uac83\ucc98\ub7fc \ub290\uaef4\uc9c0\uc9c0\ub9cc \uc2dc\uac04\uacfc \ud658\uacbd\uc758 \uc601\ud5a5\uc744 \ubc1b\uc9c0 \uc54a\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud6fc\uc190\ub41c \ub0b4\uc6a9\uc744 \ub2e4\uc2dc \uc0c8\uacbc\ub2e4\ub294 \uae30\ub85d\uc740 \ubcf4\uc874\uc774 \ud55c \ubc88\uc758 \uc7ac\ub8cc \uc120\ud0dd\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\uc74c\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ub0a8\uc740 \uac83\uc744 \uc0b4\ud53c\uace0 \ub2e4\ub978 \ub9e4\uccb4\ub85c \uc774\uc5b4 \uc8fc\ub294 \uacb0\uc815\uc774 \ud544\uc694\ud588\ub2e4. \uae30\ub85d\uc758 \uc218\uba85\uc5d0\ub294 \uadf8 \ub4a4\uc758 \ub3cc\ubd04\uacfc \ubcf5\uc81c\ub3c4 \ub4e4\uc5b4 \uc788\ub2e4. \uc774\ub54c \ubcf4\uc874\uacfc \uc0c8\ub85c\uc6b4 \uad00\uce21\uc740 \uac19\uc740 \uc77c\uc774 \uc544\ub2c8\ub2e4. \ub2e4\ub978 \ub3cc\uc5d0 \uc0c8\uacbc\ub2e4\uace0 \uadf8\ub54c \uc0c8 \ud558\ub298\uc744 \uce21\uc815\ud55c \uacb0\uacfc\ub77c\uace0 \uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub0b4\uc6a9\uc744 \uc62e\uae30\ub294 \uc791\uc5c5\uc778\uc9c0 \uc0c8 \uc9c0\uc2dd\uc744 \ucd94\uac00\ud55c \uac83\uc778\uc9c0 \uad6c\ubd84\ud574\uc11c \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \ub450 \ub0a0\uc9dc\ub97c \ud558\ub098\ub85c \ud569\uce58\uc9c0 \uc54a\ub294 \uc791\uc740 \uc8fc\uc758\uac00 \uc624\ub798\ub41c \uacfc\ud559 \uc790\ub8cc\ub97c \ub354 \uc815\ud655\ud558\uac8c \uc77d\ub3c4\ub85d \ub3d5\ub294\ub2e4. \ubcf5\uac01\ubcf8\uc740 \uad00\uc0c1\uac10\uc5d0 \ubcf4\uad00\ub418\uc5c8\ub2e4\uac00 \uc601\uc870 \ub54c \ud0dc\uc870\ubcf8\uacfc \ud568\uaed8 \ud760\uacbd\uac01\uc73c\ub85c \uc62e\uaca8\uc84c\ub2e4\uace0 \uc18c\uac1c\ub41c\ub2e4. \ubb3c\uac74\uc758 \uc8fc\uc18c\uac00 \ud55c \ubc88 \uc815\ud574\uc9c4 \ub4a4 \uba48\ucd98 \uac83\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc62e\uae30\ub294 \ub3d9\uc548\uc5d0\ub3c4 \uc5b4\ub5a4 \ucc9c\ubb38\ub3c4\uc640 \uad00\uacc4\ub41c \uc790\ub8cc\uc778\uc9c0\uc758 \uc5f0\uacb0\uc740 \uc911\uc694\ud588\ub2e4. \ubcf4\uad00\uc758 \uc774\ub825\uc740 \ubcc4\uc790\ub9ac\uc758 \ub0b4\uc6a9\uacfc \ub2e4\ub978 \uc885\ub958\uc758 \uc2dc\uac04\ud45c\ub2e4. \uc774 \uc124\uba85\uc744 \uace7\ubc14\ub85c \uc624\ub298\uc758 \uc804\uc2dc \uc704\uce58\ub098 \ub2f9\uc2dc \uacf5\uac04\uc758 \uc644\uc804\ud55c \ubaa8\uc2b5\uc73c\ub85c \uc77d\uc9c0\ub294 \uc54a\ub294\ub2e4. \ud655\uc778\ud55c \uc774\ub3d9 \uae30\ub85d\uc774 \uc54c\ub824 \uc8fc\ub294 \ud070 \uad00\uacc4\ub97c \ub530\ub77c\uac00\ub294 \uac83\uc774\ub2e4. \ud604\uc7ac \ubc15\ubb3c\uad00\uc5d0\uc11c \ubcf4\ub294 \ubb3c\uac74\uc740 \uc81c\uc791\uacfc \ubcf4\uad00, \uc774\uc804\uacfc \uc218\uc9d1\uc758 \uc5ec\ub7ec \uc2dc\uac04\uc744 \uac70\ucce4\uc744 \uc218 \uc788\ub2e4. \ub3cc \uc704\uc758 \ud558\ub298\uc744 \uc77d\ub294 \uc77c \uc606\uc5d0 \ub3cc \uc790\uccb4\uc758 \uc5ec\ud589\ub3c4 \ub193\uc744 \uc218 \uc788\ub2e4. \uc624\ub298\uc758 \uc6b0\ub9ac\ub294 \uc0ac\uc9c4\uacfc \ud30c\uc77c\ub85c \uc790\ub8cc\ub97c \ubcf5\uc0ac\ud558\uc9c0\ub9cc \uc5ec\uae30\uc11c\ub294 \ub2e4\ub978 \ub3cc\uc744 \ub9c8\ub828\ud574 \ub2e4\uc2dc \uc0c8\uae30\ub294 \uc218\uace0\ub97c \ub4e4\uc600\ub2e4. \ubc29\ubc95\uc740 \ub2e4\ub974\ub354\ub77c\ub3c4 \uc0ac\ub77c\uc9c8 \uc218 \uc788\ub294 \uc815\ubcf4\ub97c \ub2e4\uc74c \uc2dc\uac04\uc73c\ub85c \ub118\uae30\ub824\ub294 \ubb38\uc81c\ub294 \ub5a0\uc62c\ub9b4 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ub514\uc9c0\ud138 \ubcf5\uc0ac\uc640 \uc218\uacf5 \ubcf5\uac01\uc774 \ubaa8\ub4e0 \uc810\uc5d0\uc11c \uac19\uc740 \uacfc\uc815\uc774\ub77c\uace0 \ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc7ac\ub8cc\uc640 \uc624\ucc28, \uad00\ub9ac\uc758 \uc870\uac74\uc740 \uac01\uac01 \ub2e4\ub974\ub2e4. \ubcc4\uc9c0\ub3c4\ub97c \ubcf4\uba74 \uba3c\uc800 \ud558\ub298\uc758 \uc774\ub984\uacfc \uc810\uc744 \ucc3e\uac8c \ub41c\ub2e4. \uadf8 \uc606\uc5d0 \uc65c \ub2e4\uc2dc \ub9cc\ub4e4\uc5c8\ub294\uac00\ub77c\ub294 \uc9c8\ubb38\ub3c4 \ub193\uc544 \ubcf4\uc790. \ubb3c\uac74\uc744 \ubcf5\uc81c\ud588\ub2e4\ub294 \ub9d0\uc774 \ucc3d\uc791\uc131\uc774 \uc5c6\ub2e4\ub294 \ub73b\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \uc624\ub798\ub41c \uc9c0\uc2dd\uc744 \uacc4\uc18d \uc77d\uc744 \uc218 \uc788\uac8c \ud558\ub824\ub294 \ud310\ub2e8\uacfc \uc190\uc77c\uc774 \ub610 \ud558\ub098\uc758 \uc5ed\uc0ac\ub85c \ub0a8\uc558\ub2e4. \uc775\uc219\ud55c \ubcc4\uc758 \ubaa8\uc591 \ub4a4\uc5d0 \ubcf4\uc874\uc758 \uc120\ud0dd\uc774 \uc788\uc5c8\ub2e4. \ubcf5\uac01\ubcf8\uc740 \ucc98\uc74c\uc5d0 \ucc3d\ub355\uad81 \ubc16 \uad00\uc0c1\uac10\uc5d0 \ubcf4\uad00\ub418\uc5c8\ub2e4. \uc774\ud6c4 \uc601\uc870 \ub54c \uc6d0\ub798\uc758 \ud0dc\uc870\ubcf8\uacfc \ud568\uaed8 \ucc3d\ub355\uad81 \ud760\uacbd\uac01\uc73c\ub85c \uc62e\uacbc\ub2e4\uace0 \ubc15\ubb3c\uad00\uc740 \uc18c\uac1c\ud55c\ub2e4. \ub450 \ub3cc\uc740 \ub0b4\uc6a9\uc73c\ub85c \uc774\uc5b4\uc9c0\uba74\uc11c\ub3c4 \uac01\uac01 \ubcf4\uad00 \uc774\ub825\uc744 \uc9c0\ub2cc \ubb3c\uac74\uc774\ub2e4. \uc694\uc998 \ud30c\uc77c\uc744 \ubcf5\uc0ac\ud574 \ub2e4\ub978 \uacf3\uc5d0 \uc800\uc7a5\ud558\ub294 \uc77c\uc774 \ub5a0\uc624\ub97c \uc218\ub3c4 \uc788\ub2e4. \ubc29\ubc95\uc740 \uc544\uc8fc \ub2e4\ub974\uc9c0\ub9cc \uae30\ub85d\uc744 \uc783\uc9c0 \uc54a\uc73c\ub824\ub294 \uc120\ud0dd\uc774\ub77c\ub294 \uc810\uc5d0\uc11c \uac00\uae4c\uc774 \ub290\uaef4\uc9c4\ub2e4. \uc774 \ubcc4\uc9c0\ub3c4\ub294 \ud558\ub298\uc744 \uad00\ucc30\ud558\ub358 \uc0ac\ub78c\ub4e4\ubfd0 \uc544\ub2c8\ub77c, \uadf8 \uae30\ub85d\uc744 \ub2e4\uc74c \uc2dc\ub300\ub85c \uc804\ud558\ub824\ub358 \uc0ac\ub78c\ub4e4\uc758 \uc77c\ub3c4 \ubcf4\uc5ec \uc900\ub2e4."}, {"id": "tides-moon-and-changing-shore", "title": "\ubc00\ubb3c\uacfc \uc370\ubb3c \u2014 \ub2ec\uc740 \uc65c \ubc18\ub300\ud3b8 \ubc14\ub2e4\ub3c4 \uc6c0\uc9c1\uc77c\uae4c", "summary": "\ub0ae\uc740 \ubb3c\ub54c\uc758 \ud56d\uad6c\uc5d0\uc11c \uc2dc\uc791\ud574 \ub2ec\uc758 \uc911\ub825 \ucc28\uc774\u00b7\ud0dc\uc591\uc758 \uc601\ud5a5\u00b7\uc9c0\uc5ed\ubcc4 \uc870\uc11d\uc758 \ucc28\uc774\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "Science", "subcategory": "Earth-Science", "url": "stories/tides-moon-and-changing-shore/index.html", "image": "media/tides-moon-and-changing-shore.png", "alt": "\uc370\ubb3c \ub54c \ubb3c\uc774 \ube60\uc9c4 \ubc14\ub2e5\uc5d0 \uc791\uc740 \ubc30\ub4e4\uc774 \ub193\uc778 \uc0c1\uc0c1 \uc18d \ud56d\uad6c \ud48d\uacbd\uc758 \uc0bd\ud654.", "text": "\ubc00\ubb3c\uacfc \uc370\ubb3c \u2014 \ub2ec\uc740 \uc65c \ubc18\ub300\ud3b8 \ubc14\ub2e4\ub3c4 \uc6c0\uc9c1\uc77c\uae4c \ubc14\ub2f7\ubb3c\uc758 \ub192\uc774\uc5d0 \ub2f4\uae34 \uac70\ub9ac\uc758 \ucc28\uc774\uc640 \ud574\uc548\uc758 \ubaa8\uc591 \ub0ae\uc740 \ubb3c\ub54c\uc758 \ud56d\uad6c\uc5d0\uc11c \uc2dc\uc791\ud574 \ub2ec\uc758 \uc911\ub825 \ucc28\uc774\u00b7\ud0dc\uc591\uc758 \uc601\ud5a5\u00b7\uc9c0\uc5ed\ubcc4 \uc870\uc11d\uc758 \ucc28\uc774\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Earth-Science \uacfc\ud559 \ud56d\uad6c\uc5d0 \ubc30\uac00 \uc788\uc9c0\ub9cc \ubb3c\uc774 \uc544\ub2c8\ub77c \ubc14\ub2e5 \uc704\uc5d0 \ub193\uc5ec \uc788\ub2e4. \uba87 \uc2dc\uac04 \ub4a4 \uac19\uc740 \ubc30\uac00 \ub2e4\uc2dc \ub5a0 \uc788\uc744 \uc218 \uc788\ub2e4. \ubc14\ub2e4\uac00 \ub2e8\uc21c\ud788 \ud30c\ub3c4\uce58\ub294 \uac83\uacfc \ub2ec\ub9ac \ud574\uc548\uc758 \ubb3c\ub192\uc774 \uc790\uccb4\uac00 \uc624\ub974\ub0b4\ub9ac\ub294 \ud604\uc0c1\uc774\ub2e4. \ubc00\ubb3c\uacfc \uc370\ubb3c\uc740 \uac19\uc740 \uc7a5\uc18c\ub97c \ub2e4\ub978 \ud48d\uacbd\uc73c\ub85c \ubc14\uafbc\ub2e4. \ub2ec\uc774 \ubc14\ub2e4\ub97c \ub2f9\uae34\ub2e4\ub294 \uc124\uba85\uc740 \uc775\uc219\ud558\ub2e4. \uadf8\ub7f0\ub370 \ub2ec\uc774 \uc788\ub294 \ucabd\ub9cc \ubb3c\uc774 \ub192\uc544\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\uace0 \ud55c\ub2e4. \ubc18\ub300\ucabd\uc5d0\ub3c4 \ubb3c\uc774 \ubd80\ud478\ub294 \uae30\ubcf8 \ubaa8\ud615\uc774 \uc788\ub2e4. \uc774 \uc7a5\uba74\uc744 \uc774\ud574\ud558\ub824\uba74 \uc911\ub825\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc5d0\uc11c \ud55c \uac78\uc74c \ub354 \ub098\uc544\uac00 \uadf8 \ud798\uc774 \uc704\uce58\ub9c8\ub2e4 \ub2e4\ub974\ub2e4\ub294 \uc810\uc744 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uc9c0\uad6c\ub294 \ud558\ub098\uc758 \uc810\uc774 \uc544\ub2c8\ub77c \ud06c\uae30\uac00 \uc788\ub294 \ubb3c\uccb4\ub2e4. \ub2ec\uacfc \uac00\uae4c\uc6b4 \ucabd, \uc9c0\uad6c\uc758 \uc911\uc2ec, \ub2ec\uc5d0\uc11c \uba3c \ucabd\uc740 \uac01\uac01 \uac70\ub9ac\uac00 \ub2e4\ub974\ub2e4. \uad50\uc7ac\ub294 \ub2ec\uc774 \uac00\uae4c\uc6b4 \ucabd\uc744 \ub354 \uac15\ud558\uac8c, \uba3c \ucabd\uc744 \ub354 \uc57d\ud558\uac8c \ub2f9\uae34\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uac19\uc740 \ubc29\ud5a5\uc758 \uc911\ub825\ub3c4 \ubaa8\ub4e0 \uacf3\uc5d0\uc11c \uac19\uc740 \ud06c\uae30\ub85c \uc791\uc6a9\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774 \ucc28\uc774\uac00 \uc870\uc11d\uc744 \uc77c\uc73c\ud0a4\ub294 \uc911\uc694\ud55c \ucd9c\ubc1c\uc810\uc774\ub2e4. \ub2ec\uc774 \uc9c0\uad6c \uc804\uccb4\ub97c \uc6c0\uc9c1\uc774\ub294 \ud6a8\uacfc\uc640 \uc9c0\uad6c \uc548\uc758 \uc11c\ub85c \ub2e4\ub978 \uc704\uce58\ub97c \ub2e4\ub974\uac8c \ub2f9\uae30\ub294 \ud6a8\uacfc\ub97c \ub098\ub204\uc5b4 \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4. \ubc14\ub2e4\ub97c \ud1b5\uc9f8\ub85c \ud55c \ub369\uc5b4\ub9ac\uc758 \ubb3c\ucc98\ub7fc \ubcf4\uace0 \ub2ec \ucabd\uc73c\ub85c\ub9cc \ub04c\uc5b4\uc62c\ub9b0\ub2e4\uace0 \uc0c1\uc0c1\ud558\uba74 \ud604\uc0c1\uc774 \ucda9\ubd84\ud788 \uc124\uba85\ub418\uc9c0 \uc54a\ub294\ub2e4. \ub2e8\uc21c\ud654\ud55c \ubaa8\ud615\uc5d0\uc11c\ub294 \uc9c0\uad6c\uc640 \ubc14\ub2e4\uac00 \ub2ec\uc744 \ud5a5\ud55c \ubc29\ud5a5\uc73c\ub85c \uc0c1\ub300\uc801\uc73c\ub85c \ub298\uc5b4\ub098\ub294 \ubcc0\ud615\uc744 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ub2ec \ucabd\uc740 \uc9c0\uad6c \uc911\uc2ec\ubcf4\ub2e4 \uac15\ud558\uac8c \ub04c\ub9ac\uace0, \ubc18\ub300\ud3b8\uc740 \uc911\uc2ec\ubcf4\ub2e4 \uc57d\ud558\uac8c \ub04c\ub9b0\ub2e4. \uc911\uc2ec\uacfc \ube44\uad50\ud55c \ucc28\uc774\uac00 \uc591\ucabd\uc5d0 \ubaa8\ub450 \uc911\uc694\ud574\uc9c0\ub294 \uac83\uc774\ub2e4. \uad50\uc7ac\ub294 \uc774 \ucc28\uc774\ub85c \ubb3c\uc774 \ub2ec \uc544\ub798\uc640 \uadf8 \ubc18\ub300\ucabd\uc758 \ub450 \uc601\uc5ed\uc73c\ub85c \uc774\ub3d9\ud574 \ub192\uc544\uc9c0\ub294 \ubaa8\ud615\uc744 \uc124\uba85\ud55c\ub2e4. \ubb3c\uc774 \uac11\uc790\uae30 \ub298\uc5b4\ub098\uac70\ub098 \ub2ec\uc774 \ubc14\ub2f7\ubb3c\uc744 \uc9c0\uad6c \ubc16\uc73c\ub85c \ub4e4\uc5b4 \uc62c\ub9ac\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc5b4\ub290 \uacf3\uc73c\ub85c \ubb3c\uc774 \ud750\ub974\uace0 \uc313\uc774\ub294\uc9c0\ub97c \ubcf4\ub294 \uc124\uba85\uc774\ub2e4. \uc2e4\uc81c \ud574\uc591\uc744 \uadf8\ub300\ub85c \ubcf5\uc81c\ud55c \ubaa8\uc2b5\uc740 \uc544\ub2c8\uc9c0\ub9cc \ubc18\ub300\ud3b8\uc758 \ud604\uc0c1\uc744 \uc774\ud574\ud558\ub294 \ucd9c\ubc1c\uc810\uc774 \ub41c\ub2e4. \ub113\uc740 \ubc14\ub2e4\ub85c \ub458\ub7ec\uc2f8\uc778 \ub2e8\uc21c\ud55c \uc9c0\uad6c\ub97c \uc0dd\uac01\ud558\uba74, \uc9c0\uad6c\uac00 \uc790\uc804\ud558\uba74\uc11c \ud55c \ud574\uc548\uc740 \ubb3c\uc774 \ub192\uc740 \uc601\uc5ed\uacfc \ub0ae\uc740 \uc601\uc5ed\uc744 \ubc88\uac08\uc544 \uc9c0\ub09c\ub2e4. \uc774 \uae30\ubcf8 \ubaa8\ud615\uc5d0\uc11c\ub294 \ub450 \ubc88\uc758 \ub192\uc740 \ubb3c\uacfc \ub450 \ubc88\uc758 \ub0ae\uc740 \ubb3c\uc744 \uacbd\ud5d8\ud55c\ub2e4. \ubc14\ub2e4\ub97c \ubcf4\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \ubc00\ubb3c\uc774 \ub4e4\uace0 \uc370\ubb3c\uc774 \ub098\ub294 \ubcc0\ud654\uac00 \ub41c\ub2e4. \uadf8\ub7ec\ub098 \ubaa8\ub4e0 \ud574\uc548\uc5d0\uc11c \ud558\ub8e8 \ub450 \ubc88 \uac19\uc740 \ub192\uc774\uc758 \ubc00\ubb3c\uc774 \uc815\ud655\ud788 \ubc18\ubcf5\ub41c\ub2e4\uace0 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc2e4\uc81c \ubc14\ub2e4\ub294 \ub300\ub959\uacfc \ud574\uc800, \ud68c\uc804\uc758 \ud6a8\uacfc \ub54c\ubb38\uc5d0 \ud6e8\uc52c \ubcf5\uc7a1\ud558\ub2e4. \uac04\ub2e8\ud55c \ubaa8\ud615\uc73c\ub85c \uc6d0\ub9ac\ub97c \ubc30\uc6b0\ub294 \uc77c\uacfc \ud2b9\uc815 \ud56d\uad6c\uc758 \uc2e4\uc81c \uc2dc\uac01\ud45c\ub97c \ub9cc\ub4dc\ub294 \uc77c\uc740 \ub2e4\ub978 \ub2e8\uacc4\ub2e4. \ubc14\ub2e4\uc758 \uc870\uc11d\uc5d0\ub294 \ud0dc\uc591\uc758 \uc601\ud5a5\ub3c4 \uc788\ub2e4. \uad50\uc7ac\ub294 \ub2ec\uacfc \ud0dc\uc591\uc758 \ud6a8\uacfc\uac00 \ud568\uaed8 \ub098\ud0c0\ub09c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud0dc\uc591\uc774 \uc544\uc8fc \uba40\ub9ac \uc788\ub2e4\uace0 \ubc14\ub2e4\uc5d0 \uc544\ubb34 \uc601\ud5a5\uc744 \uc8fc\uc9c0 \uc54a\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \uc870\uc11d\uc744 \uc77c\uc73c\ud0a4\ub294 \ud6a8\uacfc\ub294 \uc804\uccb4\uc758 \uc911\ub825 \ud06c\uae30\ub9cc\uc73c\ub85c \ube44\uad50\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc5ec\uae30\uc11c\ub3c4 \uac70\ub9ac\ubcc4 \ud798\uc758 \ucc28\uc774\uac00 \uc911\uc694\ud558\ub2e4. \ub2ec\uacfc \ud0dc\uc591\uc774 \uc9c0\uad6c\uc5d0\uc11c \uc5b4\ub5a4 \ubc29\ud5a5\uc5d0 \uc788\ub294\uc9c0\uc5d0 \ub530\ub77c \ub450 \ud6a8\uacfc\uac00 \ub354\ud574\uc9c0\uac70\ub098 \uc77c\ubd80 \uc0c1\uc1c4\ub41c\ub2e4. \ud558\ub298\uc758 \ub450 \ucc9c\uccb4\uac00 \ubc14\ub2e4\uc5d0 \uac01\uac01 \uba85\ub839\ud558\ub294 \ub290\ub08c\ubcf4\ub2e4, \uc5ec\ub7ec \ud798\uc758 \ucc28\uc774\uac00 \uac19\uc740 \ubb3c\uc5d0 \ud568\uaed8 \uc791\uc6a9\ud55c\ub2e4\uace0 \uc0dd\uac01\ud558\uba74 \uc774\ud574\ud558\uae30 \uc27d\ub2e4. \ub2ec\uacfc \ud0dc\uc591\uc774 \uc9c0\uad6c\uc640 \ub300\uccb4\ub85c \ud55c \uc904\uc5d0 \ub193\uc774\ub294 \ub54c\uc5d0\ub294 \uc870\uc11d\uc758 \ud6a8\uacfc\uac00 \uac15\ud654\ub418\uc5b4 \ubb3c\ub192\uc774 \ucc28\uac00 \ucee4\uc9c0\ub294 \uacbd\ud5a5\uc774 \uc788\ub2e4. \uc0c8\ub2ec\uacfc \ubcf4\ub984\ub2ec \ubb34\ub835\uc758 \uc0ac\ub9ac\uc640 \uad00\ub828\ub41c\ub2e4. \ubc18\ub300\ub85c \uc0c1\ud604\uacfc \ud558\ud604 \ubb34\ub835\uc5d0\ub294 \ubb3c\ub192\uc774 \ucc28\uac00 \uc0c1\ub300\uc801\uc73c\ub85c \uc791\uc544\uc9c0\ub294 \uc870\uae08\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uc774\uac83\uc740 \ud2b9\uc815 \ub0a0\uc9dc\uc758 \ud2b9\uc815 \ud574\uc548\uc5d0\uc11c \uba87 \ubbf8\ud130\uac00 \ub2ec\ub77c\uc9c4\ub2e4\ub294 \uc608\ubcf4\ub294 \uc544\ub2c8\ub2e4. \uc9c0\uc5ed\uc758 \uc2e4\uc81c \ubc18\uc751\uacfc \uc2dc\ucc28\uac00 \ud568\uaed8 \ub4e4\uc5b4\uac04\ub2e4. \ub2ec\uc758 \ubaa8\uc591\uc744 \ubcf4\uba70 \ud070 \ud750\ub984\uc744 \uc774\ud574\ud560 \uc218\ub294 \uc788\uc5b4\ub3c4 \uadf8\uac83\ub9cc\uc73c\ub85c \uac2f\ubc8c\uc5d0 \ub4e4\uc5b4\uac08 \uc2dc\uac01\uc744 \uc815\ud558\ub294 \uc790\ub8cc\ub85c \uc4f0\uc9c0\ub294 \uc54a\ub294\ub2e4. \uad50\uc7ac\ub294 \ub300\ub959\uc774 \ubb3c\uc758 \uc774\ub3d9\uc744 \ub9c9\ub294 \ud6a8\uacfc\uc640 \ubc14\ub2e4\uc758 \uae4a\uc774, \ub9c8\ucc30, \uc9c0\uad6c\uc758 \ud68c\uc804, \ubc14\ub78c \ub4f1\uc774 \uc2e4\uc81c \uc870\uc11d\uc744 \ubcf5\uc7a1\ud558\uac8c \ub9cc\ub4e0\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub113\uace0 \uae4a\uc740 \ubc14\ub2e4\ub97c \uac00\uc815\ud55c \ubaa8\ud615\uacfc \uc881\uc740 \ub9cc\uc758 \ubb3c\uc740 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ubc18\uc751\ud558\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \uadf8\ub798\uc11c \uc138\uacc4 \uc804\uccb4\uc5d0 \ud1b5\ud558\ub294 \ud558\ub098\uc758 \ubb3c\ub54c\ud45c\ub97c \ub9cc\ub4e4 \uc218\ub294 \uc5c6\ub2e4. \uc9c0\uc5ed\ubcc4 \uc790\ub8cc\uc640 \uacc4\uc0b0\uc774 \ud544\uc694\ud558\ub2e4. \uac19\uc740 \ud558\ub298\uc744 \ubcf4\uace0 \uc788\ub294\ub370 \ubc14\ub2e4\uc758 \ubcc0\ud654\uac00 \ub2e4\ub974\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uc6d0\ub9ac\uac00 \ud2c0\ub838\ub2e4\ub294 \ub73b\ubcf4\ub2e4 \uc6d0\ub9ac\uac00 \uc791\uc6a9\ud558\ub294 \ud658\uacbd\uc774 \ub2e4\ub974\ub2e4\ub294 \ub73b\uc73c\ub85c \uc77d\uc744 \uc218 \uc788\ub2e4. \ub2ec\uc758 \uc911\ub825 \ucc28\uc774\uac00 \ubb3c\uc5d0\ub9cc \uc791\uc6a9\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uad50\uc7ac\ub294 \ub2e8\ub2e8\ud55c \uc9c0\uad6c\ub3c4 \uc791\uc740 \ubcc0\ud615\uc744 \uacaa\ub294\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub2e4\ub9cc \uc554\uc11d\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c4 \uc9c0\uad6c\uc640 \uc790\uc720\ub86d\uac8c \uc774\ub3d9\ud558\ub294 \ubc14\ub2e4\uac00 \uac19\uc740 \uc815\ub3c4\uc640 \ubc29\uc2dd\uc73c\ub85c \uc6c0\uc9c1\uc774\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub208\uc5d0 \ub744\ub294 \ud574\uc548 \ud48d\uacbd\uc740 \uadf8 \ubc18\uc751 \uac00\uc6b4\ub370 \uc798 \ubcf4\uc774\ub294 \ubd80\ubd84\uc774\ub2e4. \uc774 \uc0ac\uc2e4\uc740 \ubc14\ub2e4\uac00 \ud2b9\ubcc4\ud788 \ub2ec\uc758 \ubd80\ub984\uc744 \ub4e3\ub294\ub2e4\ub294 \uc778\uc0c1\uc5d0\uc11c \ubc97\uc5b4\ub098\uac8c \ud55c\ub2e4. \uc911\ub825\uc740 \uc5ec\ub7ec \ubb3c\uc9c8\uc5d0 \uc791\uc6a9\ud558\uace0 \ubb3c\uc9c8\uc758 \uc131\uc9c8\uacfc \uc870\uac74\uc5d0 \ub530\ub77c \uacb0\uacfc\uac00 \ub2e4\ub974\uac8c \ub098\ud0c0\ub09c\ub2e4. \ud798\uacfc \ubc18\uc751\uc744 \ud568\uaed8 \ubcf4\uc544\uc57c \ud604\uc0c1\uc744 \ub354 \uc815\ud655\ud558\uac8c \uc124\uba85\ud560 \uc218 \uc788\ub2e4. \ud568\uaed8 \uc2e4\uc740 AI \uc0bd\ud654\ub294 \uc370\ubb3c \ub54c\uc758 \ud56d\uad6c\ub97c \ub5a0\uc62c\ub9ac\ub294 \uc0c1\uc0c1 \uc18d \ud48d\uacbd\uc774\ub2e4. \uc2e4\uc81c \ud56d\uad6c\uc758 \uce21\uc815 \uc0ac\uc9c4\uc774\ub098 \ub450 \uc2dc\uc810\uc758 \ubb3c\ub192\uc774 \ube44\uad50 \uc790\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uadf8\ub9bc \uc18d\uc758 \ubc30\uc640 \ubb3c\uac00\ub9cc\uc73c\ub85c \uc870\uc11d\uc758 \ud06c\uae30\ub098 \uc2dc\uac01\uc744 \uacc4\uc0b0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub2e4\uc74c\uc5d0 \uac19\uc740 \ud574\uc548\uc774 \uba87 \uc2dc\uac04 \uc0ac\uc774 \ub2e4\ub978 \ubaa8\uc2b5\uc774 \ub418\ub294 \uac83\uc744 \ubcf4\uba74 \ub2ec\uc758 \ubc29\ud5a5\ubfd0 \uc544\ub2c8\ub77c \ubb3c\uc774 \uc9c0\ub098\uac00\ub294 \uae38\ub3c4 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc911\ub825\uc758 \ucc28\uc774\uc640 \uc9c0\uad6c\uc758 \ud68c\uc804, \ud574\uc548\uc758 \ubaa8\uc591\uc774 \ud55c \ud48d\uacbd\uc5d0 \ud568\uaed8 \ub4e4\uc5b4 \uc788\ub2e4. \ubb3c\ub54c\uc758 \ubcc0\ud654\ub294 \uba3c \ud558\ub298\uacfc \ubc14\ub85c \ubc1c\ubc11\uc758 \uc9c0\ud615\uc774 \uc5b4\ub5bb\uac8c \uc5f0\uacb0\ub418\ub294\uc9c0 \ubcf4\uc5ec \uc8fc\ub294 \uc77c\uc0c1\uc758 \ucc9c\ubb38\ud559\uc774\ub2e4."}, {"id": "water-clock-floating-turtle", "title": "\uc774 \uac70\ubd81\uc774\ub294 \ubb3c\uc774 \ucc28\uba74 \ub5a0\uc62c\ub790\ub2e4", "summary": "\ub124 \ub0a0\uac1c\uac00 \ub2ec\ub9b0 \uc790\uaca9\ub8e8 \ubd80\ud45c\uc5d0\uc11c \ubb3c\uc758 \uc6c0\uc9c1\uc784\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "Science", "subcategory": "Engineering", "url": "stories/water-clock-floating-turtle/index.html", "image": "media/water-clock-floating-turtle.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc790\uaca9\ub8e8 \ubd80\ud45c \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc774 \uac70\ubd81\uc774\ub294 \ubb3c\uc774 \ucc28\uba74 \ub5a0\uc62c\ub790\ub2e4 \uc790\uaca9\ub8e8\uc5d0\uc11c \uc2dc\uac04\uc744 \uc804\ud558\ub358 \ub465\uadfc \ubd80\ud488 \ub124 \ub0a0\uac1c\uac00 \ub2ec\ub9b0 \uc790\uaca9\ub8e8 \ubd80\ud45c\uc5d0\uc11c \ubb3c\uc758 \uc6c0\uc9c1\uc784\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Engineering \uacfc\ud559 \ub465\uadfc \ubab8\uccb4\uc5d0 \ub0a0\uac1c \uac19\uc740 \ubd80\ubd84\uc774 \ub124 \uac1c \ub2ec\ub838\ub2e4. \uac70\ubd81\uc774\ucc98\ub7fc \ubcf4\uc774\uae30\ub3c4 \ud558\uace0 \ub69c\uaed1\ucc98\ub7fc \ubcf4\uc774\uae30\ub3c4 \ud55c\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc740 \uc774\uac83\uc744 \uc790\uaca9\ub8e8\uc758 \ubd80\ud45c\ub77c\uace0 \uc18c\uac1c\ud55c\ub2e4. \uc2dc\uacc4 \uc804\uccb4\uac00 \uc544\ub2c8\ub77c \uadf8 \uc548\uc5d0\uc11c \uc6c0\uc9c1\uc774\ub358 \ubd80\ud488\uc774\ub2e4. \uac70\ubd81\uc774\ub97c \ub2ee\uc558\ub2e4\uace0 \ubd80\uad6c\ub77c\ub294 \uc774\ub984\uc73c\ub85c\ub3c4 \ubd88\ub800\ub2e4\uace0 \ud55c\ub2e4. \uce5c\uadfc\ud55c \ubcc4\uba85\uc744 \uc54c\uace0 \ub098\uba74 \ub465\uadfc \ubab8\uccb4\uc640 \uc606\uc73c\ub85c \ubed7\uc740 \ubd80\ubd84\uc744 \ub2e4\uc2dc \ubcf4\uac8c \ub41c\ub2e4. \uc774 \ubb3c\uac74\uc5d0\uc11c\ub294 \ubb3c \uc704\uc5d0\uc11c \uc6c0\uc9c1\uc774\ub294 \uc77c\uc774 \uc774\uc57c\uae30\uc758 \uc911\uc2ec\uc774\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc5d0 \ub530\ub974\uba74 \ubd80\ud45c\ub294 \uc587\uc740 \uad6c\ub9ac\ud310\uc744 \ubd99\uc5ec \ub9cc\ub4e4\uc5c8\ub2e4. \uc6d0\ud615 \ubab8\uccb4\uc758 \uc0ac\ubc29\uc5d0\ub294 \ub0a0\uac1c\uac00 \ud558\ub098\uc529 \ub2ec\ub9ac\uace0, \ud55c\ucabd \uba74\uc758 \uac00\uc6b4\ub370\uc5d0\ub294 \uae38\ucb49\ud55c \uc5f0\uacb0\uad6c\uac00 \uc788\ub2e4. \uc5ec\uae30\uc5d0 \uc7a3\ub300\ub97c \uaf42\uc558\ub2e4. \uc2dc\uacc4\ub97c \ub5a0\uc62c\ub9ac\uba74 \ubc14\ub298\ubd80\ud130 \ucc3e\uac8c \ub418\uc9c0\ub9cc \uc774 \ubd80\ud488\uc5d0\uc11c\ub294 \uc7a3\ub300\uac00 \ub4f1\uc7a5\ud55c\ub2e4. \uac00\uc6b4\ub370\uc758 \uc791\uc740 \uc790\ub9ac\uac00 \ub2e4\ub978 \ubb3c\uac74\uacfc \uc774\uc5b4\uc9c0\ub294 \uc9c0\uc810\uc774\ub77c\ub294 \uac83\uc744 \uc54c\uace0 \ubcf4\uba74, \ud3c9\ubc94\ud55c \uad6c\uba4d \uac19\uc740 \ubd80\ubd84\uc5d0\ub3c4 \ub208\uae38\uc774 \uac04\ub2e4. \ubd80\ud45c\ub294 \ubb3c\uc744 \ubc1b\ub294 \ud1b5\uc778 \uc218\uc218\ud638 \uc548\uc5d0 \ub4e4\uc5b4\uac00\ub3c4\ub85d \ub9cc\ub4e4\uc5c8\ub2e4. \ubc15\ubb3c\uad00\uc740 \uadf8 \ud06c\uae30\ub97c \uc218\uc218\ud638\uc758 \uc18d\ub458\ub808\uc5d0 \ub9de\ucd94\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uadf8\ub987\uacfc \ubd80\ud45c\uac00 \uc544\ubb34\ub807\uac8c\ub098 \ub9cc\ub098\ub294 \uad6c\uc870\uac00 \uc544\ub2c8\uc5c8\ub358 \uac83\uc774\ub2e4. \uc218\uc218\ud638\uc5d0 \ubb3c\uc774 \ucc28\uba74 \ubd80\ud45c\uac00 \ub5a0\uc624\ub974\uace0 \uc7a3\ub300\ub3c4 \ud568\uaed8 \uc62c\ub77c\uac04\ub2e4. \uc624\ub298 \uc774 \uae00\uc5d0\uc11c \uc54c\uc544\ub458 \uc6c0\uc9c1\uc784\uc740 \uc774\uac83\uc774\uba74 \ucda9\ubd84\ud558\ub2e4. \ubb3c\uc774 \ub192\uc544\uc9c0\ub294 \ubcc0\ud654\uac00 \ub2e4\ub978 \ubd80\ud488\uc758 \uc704\uce58 \ubcc0\ud654\ub85c \uc774\uc5b4\uc9c4\ub2e4. \ubcf5\uc7a1\ud55c \uc790\ub3d9 \uc7a5\uce58\uc758 \uc124\uba85\ub3c4 \uc774\ub807\uac8c \uc791\uc740 \uc6c0\uc9c1\uc784 \ud558\ub098\uc5d0\uc11c \uc2dc\uc791\ud560 \uc218 \uc788\ub2e4. \uc2dc\uac04 \uc790\uccb4\ub294 \uc190\uc73c\ub85c \uc7a1\uc744 \uc218 \uc5c6\uc9c0\ub9cc \uacc4\uc18d \uc77c\uc5b4\ub098\ub294 \ubcc0\ud654\ub97c \uae30\uc900\uc73c\ub85c \uc140 \uc218 \uc788\ub2e4. \uc774 \ubd80\ud488\uc5d0\uc11c\ub294 \ubb3c\uc758 \ub192\uc774\uac00 \uc62c\ub77c\uac00\uba74 \ubd80\ud45c\uc640 \uc7a3\ub300\uc758 \uc704\uce58\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \ubb3c\uc18d\uc758 \uc0c1\ud0dc\ub97c \ubc16\uc5d0\uc11c \uc77d\uc744 \uc218 \uc788\ub294 \uc6c0\uc9c1\uc784\uc73c\ub85c \uc774\uc5b4 \uc8fc\ub294 \uc148\uc774\ub2e4. \ubb3c\uc774 \ucc28\ub294 \ud1b5\uacfc \uadf8 \uc548\uc758 \ub5a0\uc624\ub974\ub294 \ubb3c\uac74, \uc5f0\uacb0\ub41c \uc7a3\ub300\uac00 \ud55c \uad00\uacc4\ub97c \uc774\ub8ec\ub2e4. \uc774 \uc6d0\ub9ac\ub9cc\uc73c\ub85c \uc790\uaca9\ub8e8 \uc804\uccb4\uc758 \uc2dc\uac04\uc744 \uc815\ud655\ud788 \uc124\uba85\ud588\ub2e4\uace0 \uc0dd\uac01\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4. \ubb3c\uc774 \ub4e4\uc5b4\uc624\ub294 \uc870\uac74\uacfc \ub2e4\ub978 \uc7a5\uce58\ub4e4\uc774 \ud568\uaed8 \uc788\uc5b4\uc57c \ud55c\ub2e4. \uc5ec\uae30\uc11c\ub294 \ubd80\ud45c\ub77c\ub294 \ud55c \ubd80\ud488\uc774 \ub9e1\uc740 \uc77c\uc744 \uc54c\uc544\ubcf4\ub294 \ub370 \uc9d1\uc911\ud55c\ub2e4. \ubcf5\uc7a1\ud55c \uae30\uacc4\ub97c \ucc98\uc74c \ubcfc \ub54c \uc804\uccb4\ub97c \ud55c\uaebc\ubc88\uc5d0 \uc678\uc6b0\uae30\ubcf4\ub2e4 \ud655\uc778\ud560 \uc218 \uc788\ub294 \uc791\uc740 \ubcc0\ud654\uc5d0\uc11c \uc2dc\uc791\ud558\ub294 \ubc29\ubc95\uc774\ub2e4. \uad6c\ub9ac\ud310\uc744 \ubd99\uc5ec \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \uc124\uba85\uc740 \uac89\uc758 \uc7ac\ub8cc\ubfd0 \uc544\ub2c8\ub77c \uc81c\uc791 \ubc29\uc2dd\uc744 \uc54c\ub824 \uc900\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \uae08\uc18d\uc73c\ub85c \ubcf4\uc778\ub2e4\uace0 \uc18d\uae4c\uc9c0 \uaf49 \ucc2c \ubb34\uac70\uc6b4 \ub369\uc5b4\ub9ac\ub77c\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ubb3c\uc5d0 \ub728\ub294 \ubb3c\uac74\uc758 \uc131\uc9c8\uc740 \uc7ac\ub8cc \uc774\ub984 \ud558\ub098\ubcf4\ub2e4 \uc804\uccb4 \ud615\ud0dc\uc640 \ubd80\ud53c\ub3c4 \ud568\uaed8 \ubcf4\uc544\uc57c \ud55c\ub2e4. \uae30\uad00 \uc124\uba85\uc740 \uc774 \ubd80\ud488\uc774 \uc2e4\uc81c\ub85c \ub5a0\uc624\ub974\ub3c4\ub85d \ub9cc\ub4e0 \ubab8\uccb4\uc600\uc74c\uc744 \uc54c\ub824 \uc900\ub2e4. \ub2e4\ub9cc \uc0ac\uc9c4\uc744 \ubcf4\uace0 \ubd80\ud53c\uc640 \ubb34\uac8c\ub97c \uc0c8\ub85c \uacc4\uc0b0\ud558\uac70\ub098 \uc815\ud655\ud55c \ubd80\ub825\uc744 \ud310\uc815\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc774 \uae00\uc740 \ubb3c\ub9ac \uc2e4\ud5d8 \uacb0\uacfc\uac00 \uc544\ub2c8\ub77c \ubc15\ubb3c\uad00\uc774 \uc18c\uac1c\ud55c \ubd80\ud488\uc758 \uad6c\uc870\ub97c \uc77d\ub294 \uc124\uba85\uc774\ub2e4. \uc791\uc740 \uc5f0\uacb0\uad6c\uc640 \ub0a0\uac1c \ubaa8\uc591\uc758 \ubd80\ubd84\uc744 \ucc28\ub840\ub85c \ubcf4\uba74 \uc870\uac01\ucc98\ub7fc \ubcf4\uc774\ub358 \uae08\uc18d \ubb3c\uac74\uc774 \ud2b9\uc815\ud55c \ud1b5\uacfc \uc7a3\ub300\uc5d0 \ub9de\ucd98 \uc7a5\uce58\ub85c \ubc14\ub010\ub2e4. \ubd80\ud45c\uc758 \ud06c\uae30\ub97c \ubb3c\uc744 \ubc1b\ub294 \ud1b5\uc758 \uc18d\ub458\ub808\uc640 \ub9de\ucd94\uc5c8\ub2e4\ub294 \uc815\ubcf4\ub294 \ub9de\ucda4\uc758 \uc911\uc694\uc131\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ubb3c\uc5d0 \ub728\uae30\ub9cc \ud558\uba74 \uc544\ubb34 \ubb3c\uac74\uc774\ub098 \uac19\uc740 \uc77c\uc744 \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub4e4\uc5b4\uac08 \uacf5\uac04\uacfc \uc6c0\uc9c1\uc77c \ubc94\uc704, \uc5f0\uacb0\ud560 \ubd80\ubd84\uc744 \ud568\uaed8 \uc0dd\uac01\ud574\uc57c \ud588\ub2e4. \uae30\uacc4\uc758 \ud55c \ubd80\ud488\uc744 \ub9cc\ub4e4 \ub54c \ub2e4\ub978 \ubd80\ud488\uc758 \uc870\uac74\uc774 \uba3c\uc800 \ub4e4\uc5b4\uc624\ub294 \uc148\uc774\ub2e4. \uadf8\ub798\uc11c \uc774 \ubb3c\uac74\uc744 \ud63c\uc790 \ub5bc\uc5b4 \ubcf4\uba74 \uc4f0\uc784\uc744 \uc54c\uc544\ubcf4\uae30 \uc5b4\ub824\uc6b8 \uc218 \uc788\ub2e4. \ubc15\ubb3c\uad00\uc758 \uc124\uba85\uc740 \uc0ac\ub77c\uc84c\uac70\ub098 \ud568\uaed8 \uc804\uc2dc\ub418\uc9c0 \uc54a\uc740 \ub2e4\ub978 \ubd80\ubd84\uacfc\uc758 \uad00\uacc4\ub97c \uc774\uc5b4 \uc900\ub2e4. \uc18c\uc7a5\ud488\uc758 \ub2e8\uc704\uc640 \uc791\ub3d9\ud558\ub294 \uc7a5\uce58\uc758 \ub2e8\uc704\ub294 \ub2e4\ub97c \uc218 \uc788\ub2e4\ub294 \uc810\uc744 \uc54c\uba74 \ubb3c\uac74\uc758 \ud615\ud0dc\ub3c4 \ub2e4\ub974\uac8c \uc77d\ud78c\ub2e4. \uc791\uc740 \ud2c8\uacfc \uad6c\uba4d\uc5d0\ub3c4 \uc5f0\uacb0\ud560 \uc0c1\ub300\uac00 \uc788\uc5c8\ub2e4. \uc81c\ubaa9\uc758 \uac70\ubd81\uc774\ub294 \ubaa8\uc591\uc744 \uce5c\uadfc\ud558\uac8c \ubcf4\ub294 \uc785\uad6c\ub2e4. \uc2e4\uc81c \ub3d9\ubb3c\uc758 \uc0dd\ud0dc\ub97c \uc124\uba85\ud558\ub294 \ubb3c\uac74\uc740 \uc544\ub2c8\ub2e4. \uc7a5\uc2dd\uc744 \uc704\ud574 \uc218\uba74\uc5d0 \ub193\uc740 \uc870\uac01\uacfc\ub3c4 \ub2e4\ub974\ub2e4. \uae30\uad00\uc774 \ubd80\uad6c\ub098 \ubd80\uc790\ub77c\uace0 \ubd80\ub974\ub294 \uae30\ub2a5\uc801 \uba85\uce6d\uc744 \ud568\uaed8 \uc54c\uba74 \ube44\uc720\uc640 \uc2e4\uc81c \uc4f0\uc784\uc744 \ub098\ub204\uc5b4 \ubcfc \uc218 \uc788\ub2e4. \ub3d9\ubb3c\ucc98\ub7fc \ubcf4\uc778\ub2e4\ub294 \ub290\ub08c\uc744 \uc990\uae30\uba74\uc11c\ub3c4 \uae30\uacc4 \ubd80\ud488\uc774\ub77c\ub294 \uc131\uaca9\uc744 \ub193\uce58\uc9c0 \uc54a\ub294 \uac83\uc774\ub2e4. \ubb3c\uc774 \ucc28\uba74 \ub5a0\uc624\ub978\ub2e4\ub294 \uac04\ub2e8\ud55c \ubb38\uc7a5\uc744 \ub2e4\uc2dc \ub5a0\uc62c\ub824 \ubcf4\uc790. \uadf8 \uc6c0\uc9c1\uc784\uc740 \uc587\uc740 \ud310\uc758 \ubab8\uccb4\uc640 \uc54c\ub9de\uc740 \ud06c\uae30, \uc7a3\ub300\uc758 \uc5f0\uacb0\uc744 \ud1b5\ud574 \uac00\ub2a5\ud558\ub3c4\ub85d \uc900\ube44\ub418\uc5c8\ub2e4. \ud070 \uc2dc\uacc4\uc758 \uc774\ub984\ub9cc \uae30\uc5b5\ud560 \ub54c\uc5d0\ub294 \ubcf4\uc774\uc9c0 \uc54a\ub358 \uc190\uc77c\uc774\ub2e4. \uae08\uc18d\uc758 \uc791\uc740 \ud615\uc0c1\uc5d0\uc11c \uc0ac\ub78c\ub4e4\uc774 \uc2dc\uac04\uc744 \uc77d\uae30 \uc704\ud574 \uc790\uc5f0\uc758 \ubcc0\ud654\ub97c \uc5b4\ub5a4 \uc6c0\uc9c1\uc784\uc73c\ub85c \ubc14\uafb8\uc5c8\ub294\uc9c0 \ub9cc\ub098\uac8c \ub41c\ub2e4. \uc774 \ubd80\ud45c\ub9cc\uc73c\ub85c \uc790\uaca9\ub8e8 \uc804\uccb4\uc758 \uc791\ub3d9\uc744 \ubaa8\ub450 \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc885\uc774 \uc6b8\ub9ac\ub294 \uacfc\uc815\uc774\ub098 \uc2dc\uac04\uc744 \uc54c\ub9ac\ub294 \uc7a5\uce58\uc5d0\ub294 \ub2e4\ub978 \ubd80\ud488\ub3c4 \ud544\uc694\ud558\ub2e4. \ub2e4\ub9cc \uc0ac\uc9c4 \uc18d \ub465\uadfc \ubb3c\uac74\uc774 \ud63c\uc790 \ub5a0 \uc788\ub294 \uc7a5\uc2dd\ud488\uc774 \uc544\ub2c8\ub77c\ub294 \uc0ac\uc2e4\uc740 \ubd84\uba85\ud574\uc9c4\ub2e4. \uac00\uc6b4\ub370\uc758 \uc5f0\uacb0\uad6c, \uc606\uc73c\ub85c \ub098\uc628 \ub124 \ub0a0\uac1c, \ud1b5\uc5d0 \ub4e4\uc5b4\uac08 \ud06c\uae30. \uadf8\ub7f0 \ud2b9\uc9d5\uc744 \ucc28\ub840\ub85c \ubcf4\uba74 \ubd80\ud488\uc774 \uc65c \uadf8 \ubaa8\uc591\uc778\uc9c0 \uad81\uae08\ud574\uc9c4\ub2e4. \uc2dc\uac04\uc744 \uc7ac\ub294 \ubb3c\uac74 \uc548\uc5d0\ub3c4 \ubb3c \uc704\ub85c \ucc9c\ucc9c\ud788 \ub5a0\uc624\ub974\ub294 \uac70\ubd81\uc774 \uac19\uc740 \ubd80\ud488\uc774 \uc788\uc5c8\ub2e4."}];
